-- Ingesting Edition: en.sahih (Saheeh International (English Translation)) - 6236 Ayahs
INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 1, 1, 1, 'In the name of Allah, the Entirely Merciful, the Especially Merciful.', NULL, NULL, 'a794514ac0b08662a9c76dd9dcfab3601298ce798089d6235b957d9c391e9c62'),
  ('en.sahih', 1, 2, 2, '[All] praise is [due] to Allah, Lord of the worlds -', NULL, NULL, '76c68721bd1f581ffaef6822f550c821df4c59dd9c590861bf9a4c2882f6b1cc'),
  ('en.sahih', 1, 3, 3, 'The Entirely Merciful, the Especially Merciful,', NULL, NULL, '34e9640449d2d2669856349c091cbd8db2335626210ecac633f8ec048aa45b8f'),
  ('en.sahih', 1, 4, 4, 'Sovereign of the Day of Recompense.', NULL, NULL, 'f441d5e46ec61e1f130aa96c68e3064e1d200b479967a507eb8465b71e859e03'),
  ('en.sahih', 1, 5, 5, 'It is You we worship and You we ask for help.', NULL, NULL, 'ec8a98b4642eeb4ab75ddeb3b7f6918e501a4a16108c8c4ae968ce8b025094fa'),
  ('en.sahih', 1, 6, 6, 'Guide us to the straight path -', NULL, NULL, 'c887d10986ce97c0aa01fda08aed18c2a115e6c746764d196b16c9f6cde17ea4'),
  ('en.sahih', 1, 7, 7, 'The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.', NULL, NULL, '89af11d100adc9913ef2b498d1da3067853b9173f20be0eb5570d1edc2e33a74'),
  ('en.sahih', 2, 1, 8, 'Alif, Lam, Meem.', NULL, NULL, 'c0271a8d54e5b8ca6868a624b25c94d32c317177546d0577b0ceceac58956c78'),
  ('en.sahih', 2, 2, 9, 'This is the Book about which there is no doubt, a guidance for those conscious of Allah -', NULL, NULL, '7332e12f691ae3798267b39b614bd6e5d5d66770fd096e0e51f67042318e79fb'),
  ('en.sahih', 2, 3, 10, 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,', NULL, NULL, '4be704b0475002ea9defe6467d53b75da1e23c278535f7f619b92edae03a1621'),
  ('en.sahih', 2, 4, 11, 'And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith].', NULL, NULL, '75dc50f5375bc73a70e6068ade3ceada0baeaee1e6b551cc166ad37e24723f6e'),
  ('en.sahih', 2, 5, 12, 'Those are upon [right] guidance from their Lord, and it is those who are the successful.', NULL, NULL, '8c9cce326768e929b8d534a3b7e14aeb4b4c599f073162325efe32424e4af813'),
  ('en.sahih', 2, 6, 13, 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.', NULL, NULL, 'e3a898c4465ec93f7188f0853c4eb562024a209ae0420d38e0e0ad283d852ea9'),
  ('en.sahih', 2, 7, 14, 'Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.', NULL, NULL, '767bed385a8395e4924c3d71182661e3cd6126824a771845a2be27652032dee6'),
  ('en.sahih', 2, 8, 15, 'And of the people are some who say, "We believe in Allah and the Last Day," but they are not believers.', NULL, NULL, '16dae730373b1b00396d097b51625573de671c3f47d8b0921fd2a1f53264d054'),
  ('en.sahih', 2, 9, 16, 'They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not.', NULL, NULL, '7a3d552464b686e12af587b4bc6984f3a675f5ec0dae9413fb4cc6e475d21bcb'),
  ('en.sahih', 2, 10, 17, 'In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie.', NULL, NULL, '4458391f97634f727e2520886bba52a38ea04d1415e0421bd44fa0a2560c8a22'),
  ('en.sahih', 2, 11, 18, 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."', NULL, NULL, 'cd1f23d3bf025c442241c0e59abdb886202391e22f6e5e8e6ca1ed084b68f8b3'),
  ('en.sahih', 2, 12, 19, 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.', NULL, NULL, '2670df1f2ecd81dd940d478f04a92f813193455c93b7c67a1446eb1e336a9b15'),
  ('en.sahih', 2, 13, 20, 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.', NULL, NULL, 'fa6faf6413e79a40ccbcac696befdceb7177e74063b3048b93e17609dd80479c'),
  ('en.sahih', 2, 14, 21, 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."', NULL, NULL, '33e1fa1424b868b5aeebf83c811fe71245f52e61ac16711518464ba5727de690'),
  ('en.sahih', 2, 15, 22, '[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly.', NULL, NULL, '506068eae1037d18bb5cfec586269559ab34e038c68bc5a58379da7ae0f20e64'),
  ('en.sahih', 2, 16, 23, 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.', NULL, NULL, '70675e6905de964f1327a9806492b8e6cb2ead0980ec1bc7fbe00534162c8c78'),
  ('en.sahih', 2, 17, 24, 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see.', NULL, NULL, 'b85bcbff81d2c3d65abece691716a381f5252a48a4809227f112d3eff4c05d58'),
  ('en.sahih', 2, 18, 25, 'Deaf, dumb and blind - so they will not return [to the right path].', NULL, NULL, 'a8c3f0f303fabdf17ba03812da7088bbf340aec7c921f315399ccab52ff080d2'),
  ('en.sahih', 2, 19, 26, 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers.', NULL, NULL, 'fa14e21532662bbfecde43c48c5ecb7b19b852880c29ebddfe945e896a7e38b0'),
  ('en.sahih', 2, 20, 27, 'The lightning almost snatches away their sight. Every time it lights [the way] for them, they walk therein; but when darkness comes over them, they stand [still]. And if Allah had willed, He could have taken away their hearing and their sight. Indeed, Allah is over all things competent.', NULL, NULL, '9b749d3fee545be487254ad0149cc8d7718d8c164be104cd0020ad19b85806b3'),
  ('en.sahih', 2, 21, 28, 'O mankind, worship your Lord, who created you and those before you, that you may become righteous -', NULL, NULL, '35ab29f4f0f058dcbc0effc246beaa93c0a68410ac9c5adefd4a09af184e7c96'),
  ('en.sahih', 2, 22, 29, '[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him].', NULL, NULL, 'e95c8d2486a7781a1fbe301083e56aa5a67a821ed5e4a1edf01e18b84a70483b'),
  ('en.sahih', 2, 23, 30, 'And if you are in doubt about what We have sent down upon Our Servant [Muhammad], then produce a surah the like thereof and call upon your witnesses other than Allah, if you should be truthful.', NULL, NULL, 'd0675047f150e08b41fc986d2e35bba1c26dc63e7996684c59a561066cc5f2ab'),
  ('en.sahih', 2, 24, 31, 'But if you do not - and you will never be able to - then fear the Fire, whose fuel is men and stones, prepared for the disbelievers.', NULL, NULL, '4cb4ad4d76bcc674ed8c8a44621dddd83f527961790e9ffaafab07637a8b0db9'),
  ('en.sahih', 2, 25, 32, 'And give good tidings to those who believe and do righteous deeds that they will have gardens [in Paradise] beneath which rivers flow. Whenever they are provided with a provision of fruit therefrom, they will say, "This is what we were provided with before." And it is given to them in likeness. And they will have therein purified spouses, and they will abide therein eternally.', NULL, NULL, 'dde5fdd5c0deefe1d68473702ca82277d32befea9b0952b83c0a7136d6b1788d'),
  ('en.sahih', 2, 26, 33, 'Indeed, Allah is not timid to present an example - that of a mosquito or what is smaller than it. And those who have believed know that it is the truth from their Lord. But as for those who disbelieve, they say, "What did Allah intend by this as an example?" He misleads many thereby and guides many thereby. And He misleads not except the defiantly disobedient,', NULL, NULL, 'ef39a15469888a380c069ce3f65cc641d9bee010bf43ea3d694f096735156d70'),
  ('en.sahih', 2, 27, 34, 'Who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and cause corruption on earth. It is those who are the losers.', NULL, NULL, 'b165dacdc75890e957060b52cac7e282b366424ce58aaa7c076144f3e02d9bb7'),
  ('en.sahih', 2, 28, 35, 'How can you disbelieve in Allah when you were lifeless and He brought you to life; then He will cause you to die, then He will bring you [back] to life, and then to Him you will be returned.', NULL, NULL, '7b9f2a322804c67e0328d7a678db1491cf72dd1132653ef4c468be42f4a70657'),
  ('en.sahih', 2, 29, 36, 'It is He who created for you all of that which is on the earth. Then He directed Himself to the heaven, [His being above all creation], and made them seven heavens, and He is Knowing of all things.', NULL, NULL, 'f9ed07e2497070963bf03101fab72e3a1bd866dd9eab085791aced4716f3fa2c'),
  ('en.sahih', 2, 30, 37, 'And [mention, O Muhammad], when your Lord said to the angels, "Indeed, I will make upon the earth a successive authority." They said, "Will You place upon it one who causes corruption therein and sheds blood, while we declare Your praise and sanctify You?" Allah said, "Indeed, I know that which you do not know."', NULL, NULL, 'f0597ece45e914692d158b921a81e1ac7b8d926ff13d34572d978d750c5b65bb'),
  ('en.sahih', 2, 31, 38, 'And He taught Adam the names - all of them. Then He showed them to the angels and said, "Inform Me of the names of these, if you are truthful."', NULL, NULL, '9fc2c21f7bf0f235f544671a7dbe1d91d0ee51a0f3c20d460cf5c4d3bf714699'),
  ('en.sahih', 2, 32, 39, 'They said, "Exalted are You; we have no knowledge except what You have taught us. Indeed, it is You who is the Knowing, the Wise."', NULL, NULL, 'e4c189398e13b15200a3a2ebbc40b38ede6d48b37b214f1c9d223732f6f8635d'),
  ('en.sahih', 2, 33, 40, 'He said, "O Adam, inform them of their names." And when he had informed them of their names, He said, "Did I not tell you that I know the unseen [aspects] of the heavens and the earth? And I know what you reveal and what you have concealed."', NULL, NULL, 'e839ca29451f80a579c88eeaa9a288a268afe4aeb84d6076f265f3a536f66378'),
  ('en.sahih', 2, 34, 41, 'And [mention] when We said to the angels, "Prostrate before Adam"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers.', NULL, NULL, '8a9257e46ee21d1270a30abf70ca3eb3c463009db8c0f4d5f81226041cb7a805'),
  ('en.sahih', 2, 35, 42, 'And We said, "O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers."', NULL, NULL, '68ac119adefe367472653f71435fa1fe065b4326ba7c6f2da6c65d67c1c9f702'),
  ('en.sahih', 2, 36, 43, 'But Satan caused them to slip out of it and removed them from that [condition] in which they had been. And We said, "Go down, [all of you], as enemies to one another, and you will have upon the earth a place of settlement and provision for a time."', NULL, NULL, 'db1b3d01aae685d939423ac8c1bf2e595ec2b77c48ae921d0ccd5f5e82e8f081'),
  ('en.sahih', 2, 37, 44, 'Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of repentance, the Merciful.', NULL, NULL, 'decb6382fab1114c865a704babb0b262fe0815baf8c82add2ca94d2497420df4'),
  ('en.sahih', 2, 38, 45, 'We said, "Go down from it, all of you. And when guidance comes to you from Me, whoever follows My guidance - there will be no fear concerning them, nor will they grieve.', NULL, NULL, '6a9e99e72a4d588ce71b7cdd33e5f56ebf5287f38a4402b0442479f63db8f3cc'),
  ('en.sahih', 2, 39, 46, 'And those who disbelieve and deny Our signs - those will be companions of the Fire; they will abide therein eternally."', NULL, NULL, '3d118708a5045d6a6730d02c0be78069b1b0552883f3379dcb8ac108f802fd53'),
  ('en.sahih', 2, 40, 47, 'O Children of Israel, remember My favor which I have bestowed upon you and fulfill My covenant [upon you] that I will fulfill your covenant [from Me], and be afraid of [only] Me.', NULL, NULL, '62e5c443bff95d577820749802db6fc77283802c9ff5a9acddc31aa915f1e303'),
  ('en.sahih', 2, 41, 48, 'And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me.', NULL, NULL, 'a4751a16c36512ce295d10571262622421b580248ece396c6698d4202a45946d'),
  ('en.sahih', 2, 42, 49, 'And do not mix the truth with falsehood or conceal the truth while you know [it].', NULL, NULL, 'f715a617e3bbf1d99c90b5f9bbd88e7b5d722e55f91bf064f8f3d8807e789eae'),
  ('en.sahih', 2, 43, 50, 'And establish prayer and give zakah and bow with those who bow [in worship and obedience].', NULL, NULL, '08b1c819e171b0a7938d62aeec8a215079a183fd39446c343dd5afae06d3fcc3'),
  ('en.sahih', 2, 44, 51, 'Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason?', NULL, NULL, '943fc3900c44579c57109fdda2054ca8059a4c48285413f6fe3564c46534c98b'),
  ('en.sahih', 2, 45, 52, 'And seek help through patience and prayer, and indeed, it is difficult except for the humbly submissive [to Allah]', NULL, NULL, '8d3b33e838913788a7d16ffa6ef359ed78a7c112902bb5ff70619cdb5922f71f'),
  ('en.sahih', 2, 46, 53, 'Who are certain that they will meet their Lord and that they will return to Him.', NULL, NULL, '067c74713c8842e93d957c9c14df98974eb8dee8f3e7799fa68cbf2e31b19f34'),
  ('en.sahih', 2, 47, 54, 'O Children of Israel, remember My favor that I have bestowed upon you and that I preferred you over the worlds.', NULL, NULL, '8fbfa49b81da5c5f4acb9f6861dd5ddb2f67615947c7c95bac4af065a8ebae0c'),
  ('en.sahih', 2, 48, 55, 'And fear a Day when no soul will suffice for another soul at all, nor will intercession be accepted from it, nor will compensation be taken from it, nor will they be aided.', NULL, NULL, '04e4355de51a0c6e749d94fb65f65f521b822347719e0ac6c48ede923397fa2d'),
  ('en.sahih', 2, 49, 56, 'And [recall] when We saved your forefathers from the people of Pharaoh, who afflicted you with the worst torment, slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', NULL, NULL, '100cc6b7f4c2303571383c5252a35e67d6145d9f974a52f00ce80007ed136ff2'),
  ('en.sahih', 2, 50, 57, 'And [recall] when We parted the sea for you and saved you and drowned the people of Pharaoh while you were looking on.', NULL, NULL, 'de7f0a4e3ff4564b46b71d71861f4afc030b35b114dac22c84f6c0654fe10c1a'),
  ('en.sahih', 2, 51, 58, 'And [recall] when We made an appointment with Moses for forty nights. Then you took [for worship] the calf after him, while you were wrongdoers.', NULL, NULL, '34ebc71110fee01ce9c287ebe3148977509eb5e291eeb44c281a96ae3ac78dec'),
  ('en.sahih', 2, 52, 59, 'Then We forgave you after that so perhaps you would be grateful.', NULL, NULL, 'f84e5a3435d372ffcafe1f34afaa4f50ed44f35082cc0093a8d416f53f1accbe'),
  ('en.sahih', 2, 53, 60, 'And [recall] when We gave Moses the Scripture and criterion that perhaps you would be guided.', NULL, NULL, '96fdf67b820aa3ebc77ed65526e86fa199cae61ad87a8c6fa998ab7a61e84d81'),
  ('en.sahih', 2, 54, 61, 'And [recall] when Moses said to his people, "O my people, indeed you have wronged yourselves by your taking of the calf [for worship]. So repent to your Creator and kill yourselves. That is best for [all of] you in the sight of your Creator." Then He accepted your repentance; indeed, He is the Accepting of repentance, the Merciful.', NULL, NULL, 'c75ed70b739d366498d108ddcdc560afa108e3a4ab2c6963c7236bcb0d69c6d2'),
  ('en.sahih', 2, 55, 62, 'And [recall] when you said, "O Moses, we will never believe you until we see Allah outright"; so the thunderbolt took you while you were looking on.', NULL, NULL, 'd019ec6a159ffd39f29ab3458063194982e350f7b89c4ad78d842e68f03f5211'),
  ('en.sahih', 2, 56, 63, 'Then We revived you after your death that perhaps you would be grateful.', NULL, NULL, '2d8495c34e3dc21c84b36c754ac41fe5b7d1573b82e9b22002276cca538f6230'),
  ('en.sahih', 2, 57, 64, 'And We shaded you with clouds and sent down to you manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not - but they were [only] wronging themselves.', NULL, NULL, 'ea971d9a829d7d35323e6da609f04e0ab912804149e47e9220593e519ade211e'),
  ('en.sahih', 2, 58, 65, 'And [recall] when We said, "Enter this city and eat from it wherever you will in [ease and] abundance, and enter the gate bowing humbly and say, ''Relieve us of our burdens.'' We will [then] forgive your sins for you, and We will increase the doers of good [in goodness and reward]."', NULL, NULL, '170c4ca06437f0d3b4f8a405066b0afb984c2e1d4f8ecfc069056b7c62498c77'),
  ('en.sahih', 2, 59, 66, 'But those who wronged changed [those words] to a statement other than that which had been said to them, so We sent down upon those who wronged a punishment from the sky because they were defiantly disobeying.', NULL, NULL, 'a42ec4b6ab250c66e8abe20e5e9a6e71fae7d160815e73afcc63d94a984f697e'),
  ('en.sahih', 2, 60, 67, 'And [recall] when Moses prayed for water for his people, so We said, "Strike with your staff the stone." And there gushed forth from it twelve springs, and every people knew its watering place. "Eat and drink from the provision of Allah, and do not commit abuse on the earth, spreading corruption."', NULL, NULL, 'fae6eca044db4abb6fdbd531787bc3cede9e6b1cfdab99c645816f0ea9065c74'),
  ('en.sahih', 2, 61, 68, 'And [recall] when you said, "O Moses, we can never endure one [kind of] food. So call upon your Lord to bring forth for us from the earth its green herbs and its cucumbers and its garlic and its lentils and its onions." [Moses] said, "Would you exchange what is better for what is less? Go into [any] settlement and indeed, you will have what you have asked." And they were covered with humiliation and poverty and returned with anger from Allah [upon them]. That was because they [repeatedly] disbelieved in the signs of Allah and killed the prophets without right. That was because they disobeyed and were [habitually] transgressing.', NULL, NULL, '59f342181dad0d1b7c93e23ce0d0fc89ac301ecf596f490099701121040135f0'),
  ('en.sahih', 2, 62, 69, 'Indeed, those who believed and those who were Jews or Christians or Sabeans [before Prophet Muhammad] - those [among them] who believed in Allah and the Last Day and did righteousness - will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve.', NULL, NULL, 'a733957729e2570f140c7fd64abb4611de6541e48b32ce0d280536de5e02807c'),
  ('en.sahih', 2, 63, 70, 'And [recall] when We took your covenant, [O Children of Israel, to abide by the Torah] and We raised over you the mount, [saying], "Take what We have given you with determination and remember what is in it that perhaps you may become righteous."', NULL, NULL, '6ae815c9ba728b4b9ecdcf00d87d6ff3a47e45f600a61eb21cc3d789d59d9411'),
  ('en.sahih', 2, 64, 71, 'Then you turned away after that. And if not for the favor of Allah upon you and His mercy, you would have been among the losers.', NULL, NULL, '745be0c5be9603104b2e54c51bc265c6c2165c8b0100411084de982deb8ba366'),
  ('en.sahih', 2, 65, 72, 'And you had already known about those who transgressed among you concerning the sabbath, and We said to them, "Be apes, despised."', NULL, NULL, 'fef510301cf3efa0b85c8c43c3bd871bc32a0a5a0e4555e85f5c4564f1ef9b7a'),
  ('en.sahih', 2, 66, 73, 'And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allah.', NULL, NULL, '59a5c0763938d475404efd2e905296c3ef3113cf1cea1f8a62b1493127d79542'),
  ('en.sahih', 2, 67, 74, 'And [recall] when Moses said to his people, "Indeed, Allah commands you to slaughter a cow." They said, "Do you take us in ridicule?" He said, "I seek refuge in Allah from being among the ignorant."', NULL, NULL, '67a133782778bf417762a1f206526e8c4382063eabab32c38440804004820c4d'),
  ('en.sahih', 2, 68, 75, 'They said, "Call upon your Lord to make clear to us what it is." [Moses] said, "[Allah] says, ''It is a cow which is neither old nor virgin, but median between that,'' so do what you are commanded."', NULL, NULL, '7e5be1834384dfea2c18117ddeb1a34dd1e58a9e317a9b2b1fa545698db65830'),
  ('en.sahih', 2, 69, 76, 'They said, "Call upon your Lord to show us what is her color." He said, "He says, ''It is a yellow cow, bright in color - pleasing to the observers.'' "', NULL, NULL, 'feecb38eade7c15e83ccab331825bd0f20caf7f0ac1aa5a413f3c67f73928f6d'),
  ('en.sahih', 2, 70, 77, 'They said, "Call upon your Lord to make clear to us what it is. Indeed, [all] cows look alike to us. And indeed we, if Allah wills, will be guided."', NULL, NULL, '0c3f4f6e503c2a6eae62593374c2a54096152bf3bc8a9d4aa6f294f0473a3f7b'),
  ('en.sahih', 2, 71, 78, 'He said, "He says, ''It is a cow neither trained to plow the earth nor to irrigate the field, one free from fault with no spot upon her.'' " They said, "Now you have come with the truth." So they slaughtered her, but they could hardly do it.', NULL, NULL, '3e15a209ccd8d68dc99471fbfd17fe861186d3866bf12d16faf4ceaa5f00a14a'),
  ('en.sahih', 2, 72, 79, 'And [recall] when you slew a man and disputed over it, but Allah was to bring out that which you were concealing.', NULL, NULL, '6b1a2b28578dea3b69d42674e4cf42c55a1595f65869002e7885da19a3a5d805'),
  ('en.sahih', 2, 73, 80, 'So, We said, "Strike the slain man with part of it." Thus does Allah bring the dead to life, and He shows you His signs that you might reason.', NULL, NULL, 'f529372de6b3829efcf281930f6a5069a72f5a201bf434abb3f516b5c6a9f958'),
  ('en.sahih', 2, 74, 81, 'Then your hearts became hardened after that, being like stones or even harder. For indeed, there are stones from which rivers burst forth, and there are some of them that split open and water comes out, and there are some of them that fall down for fear of Allah. And Allah is not unaware of what you do.', NULL, NULL, 'facc5e4e93a36d27074885522a624bf5a4dcfce10a1c9488db63e183fd988e54'),
  ('en.sahih', 2, 75, 82, 'Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allah and then distort the Torah after they had understood it while they were knowing?', NULL, NULL, 'b582686c5c2da99abf86b26ace6723bc3c61efe76ed6a6bc1ff8c70b898c5815'),
  ('en.sahih', 2, 76, 83, 'And when they meet those who believe, they say, "We have believed"; but when they are alone with one another, they say, "Do you talk to them about what Allah has revealed to you so they can argue with you about it before your Lord?" Then will you not reason?', NULL, NULL, '82afd3521cea6378ad4e653291051b419b191e80ce5f922d9c65e999a20708e2'),
  ('en.sahih', 2, 77, 84, 'But do they not know that Allah knows what they conceal and what they declare?', NULL, NULL, 'ed560efbcb5116b906070e3688585d09c54df1e455780d28f9585b1ae8870265'),
  ('en.sahih', 2, 78, 85, 'And among them are unlettered ones who do not know the Scripture except in wishful thinking, but they are only assuming.', NULL, NULL, '9fcc9fa35edb170b618e2162eaf2ab34271e88efd996c87898c6145ca3994785'),
  ('en.sahih', 2, 79, 86, 'So woe to those who write the "scripture" with their own hands, then say, "This is from Allah," in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn.', NULL, NULL, 'f4265aa740c5a52372291bbd7e6e0e8fe4a662e697b1da5f914f0864adf6a522'),
  ('en.sahih', 2, 80, 87, 'And they say, "Never will the Fire touch us, except for a few days." Say, "Have you taken a covenant with Allah? For Allah will never break His covenant. Or do you say about Allah that which you do not know?"', NULL, NULL, '13806c02f5ca85ed29b149223f6e38b04d12cce82140ea4e773a72aee0501c1d'),
  ('en.sahih', 2, 81, 88, 'Yes, whoever earns evil and his sin has encompassed him - those are the companions of the Fire; they will abide therein eternally.', NULL, NULL, '63e540f3c40fcfa34ea5624bd9bd9faaf531be62981c49ce8e797732eb1fc8aa'),
  ('en.sahih', 2, 82, 89, 'But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally.', NULL, NULL, '245711f9f35105be0e8b0e3a047ebb671e8a136c7f6c26abe0a09bb56c383b76'),
  ('en.sahih', 2, 83, 90, 'And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], "Do not worship except Allah; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakah." Then you turned away, except a few of you, and you were refusing.', NULL, NULL, 'c0f1301f5bf006817334d76f4b564df48837cee584fe875ca49783e8c1fad9b7'),
  ('en.sahih', 2, 84, 91, 'And [recall] when We took your covenant, [saying], "Do not shed each other''s blood or evict one another from your homes." Then you acknowledged [this] while you were witnessing.', NULL, NULL, 'bb39e728610ac7211920df61104a34320f074ed975e0620a463a8e188f6c9887'),
  ('en.sahih', 2, 85, 92, 'Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allah is not unaware of what you do.', NULL, NULL, '63fd5f96880ae09bbb9ed4051d83f48600f860c4ffa2b208c9476440d946c09d'),
  ('en.sahih', 2, 86, 93, 'Those are the ones who have bought the life of this world [in exchange] for the Hereafter, so the punishment will not be lightened for them, nor will they be aided.', NULL, NULL, '3b429ddd9d2257d11e3051f0883d5492e0b03d715d963319b0f2f6ed75ea271f'),
  ('en.sahih', 2, 87, 94, 'And We did certainly give Moses the Torah and followed up after him with messengers. And We gave Jesus, the son of Mary, clear proofs and supported him with the Pure Spirit. But is it [not] that every time a messenger came to you, [O Children of Israel], with what your souls did not desire, you were arrogant? And a party [of messengers] you denied and another party you killed.', NULL, NULL, 'd4c5858488e4f5663cf1b02b880e4aa810049fe38e19943d451c401519b29144'),
  ('en.sahih', 2, 88, 95, 'And they said, "Our hearts are wrapped." But, [in fact], Allah has cursed them for their disbelief, so little is it that they believe.', NULL, NULL, '875853cbc67e70d036d0de8f3989e86a778ed7068777ca01c7a39d784b27e962'),
  ('en.sahih', 2, 89, 96, 'And when there came to them a Book from Allah confirming that which was with them - although before they used to pray for victory against those who disbelieved - but [then] when there came to them that which they recognized, they disbelieved in it; so the curse of Allah will be upon the disbelievers.', NULL, NULL, 'b31e2c1ee4b8165d5dfdd90506de9cdb32564b899e0d80916a22f0f22421b830'),
  ('en.sahih', 2, 90, 97, 'How wretched is that for which they sold themselves - that they would disbelieve in what Allah has revealed through [their] outrage that Allah would send down His favor upon whom He wills from among His servants. So they returned having [earned] wrath upon wrath. And for the disbelievers is a humiliating punishment.', NULL, NULL, '0b15114cc00317ff95b281538d033a2bc37656c59a0f80203df9d2be54fb1053'),
  ('en.sahih', 2, 91, 98, 'And when it is said to them, "Believe in what Allah has revealed," they say, "We believe [only] in what was revealed to us." And they disbelieve in what came after it, while it is the truth confirming that which is with them. Say, "Then why did you kill the prophets of Allah before, if you are [indeed] believers?"', NULL, NULL, '22677c7f8f9efda992f7b7db368c37fc32343c078ca43eb197af9c04dc220e5e'),
  ('en.sahih', 2, 92, 99, 'And Moses had certainly brought you clear proofs. Then you took the calf [in worship] after that, while you were wrongdoers.', NULL, NULL, '7c4ef8b9e4adad86b7ef57064b2195268a9bfeb76874a805eda3edb13e3bfe0c'),
  ('en.sahih', 2, 93, 100, 'And [recall] when We took your covenant and raised over you the mount, [saying], "Take what We have given you with determination and listen." They said [instead], "We hear and disobey." And their hearts absorbed [the worship of] the calf because of their disbelief. Say, "How wretched is that which your faith enjoins upon you, if you should be believers."', NULL, NULL, '70baee93f849fcf4ba0f165ab07e58a906b048e7a734cb4a16cccb996bd1c1c4')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 2, 94, 101, 'Say, [O Muhammad], "If the home of the Hereafter with Allah is for you alone and not the [other] people, then wish for death, if you should be truthful.', NULL, NULL, 'e49f26b82406fefbd45599cd37081794cee5e18bed846cc41df7853f682be38d'),
  ('en.sahih', 2, 95, 102, 'But they will never wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.', NULL, NULL, '0f5f533d2d2ec4ad866b050c22f13b03906b2d826ccd26eebb2d904f1e65781f'),
  ('en.sahih', 2, 96, 103, 'And you will surely find them the most greedy of people for life - [even] more than those who associate others with Allah. One of them wishes that he could be granted life a thousand years, but it would not remove him in the least from the [coming] punishment that he should be granted life. And Allah is Seeing of what they do.', NULL, NULL, 'cb3d051696b7e98d6e8e8e077a1221d91701af0cf5796249772be733ba63f621'),
  ('en.sahih', 2, 97, 104, 'Say, "Whoever is an enemy to Gabriel - it is [none but] he who has brought the Qur''an down upon your heart, [O Muhammad], by permission of Allah, confirming that which was before it and as guidance and good tidings for the believers."', NULL, NULL, '264b47043f5eeb7f886dc72fe2a67acebc8038132f03f497c5e7617e83e3ae71'),
  ('en.sahih', 2, 98, 105, 'Whoever is an enemy to Allah and His angels and His messengers and Gabriel and Michael - then indeed, Allah is an enemy to the disbelievers.', NULL, NULL, '9c78a00bafa237be0f0df2185ffd6ce70f0ec99a1b2581d93149ab9449606052'),
  ('en.sahih', 2, 99, 106, 'And We have certainly revealed to you verses [which are] clear proofs, and no one would deny them except the defiantly disobedient.', NULL, NULL, '2c2ca0ce912a438f53a2761c4047f073254c09dfd88f8746bc86b8c4c65c6bd0'),
  ('en.sahih', 2, 100, 107, 'Is it not [true] that every time they took a covenant a party of them threw it away? But, [in fact], most of them do not believe.', NULL, NULL, 'f1278c70254908322dfdc6ee63bacc0443f5b45b09e9abde79df8e44a0caf672'),
  ('en.sahih', 2, 101, 108, 'And when a messenger from Allah came to them confirming that which was with them, a party of those who had been given the Scripture threw the Scripture of Allah behind their backs as if they did not know [what it contained].', NULL, NULL, '21de66ec8dc22cab447f69d261c2a99652f85a2522f75fb12a50ebfabaafa99c'),
  ('en.sahih', 2, 102, 109, 'And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Harut and Marut. But the two angels do not teach anyone unless they say, "We are a trial, so do not disbelieve [by practicing magic]." And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allah. And the people learn what harms them and does not benefit them. But the Children of Israel certainly knew that whoever purchased the magic would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew.', NULL, NULL, '1cc27c56ee8a5a6cce62ba12ecc250bd90c700f59d6ca711441418b943d08843'),
  ('en.sahih', 2, 103, 110, 'And if they had believed and feared Allah, then the reward from Allah would have been [far] better, if they only knew.', NULL, NULL, '112d36853b7ec40c7d1b7276a9bab19501c55d4f3b1ca0493dfe95f5b22376d6'),
  ('en.sahih', 2, 104, 111, 'O you who have believed, say not [to Allah ''s Messenger], "Ra''ina" but say, "Unthurna" and listen. And for the disbelievers is a painful punishment.', NULL, NULL, 'c02996eb18968ca494cf3cfe5edd7a591dbcfb29ebfb3ac7548d6289d8b5a59a'),
  ('en.sahih', 2, 105, 112, 'Neither those who disbelieve from the People of the Scripture nor the polytheists wish that any good should be sent down to you from your Lord. But Allah selects for His mercy whom He wills, and Allah is the possessor of great bounty.', NULL, NULL, '424018955886545b0b6466d1149cd3a4576e6675dd3166da5cc67bbb88cfbdc5'),
  ('en.sahih', 2, 106, 113, 'We do not abrogate a verse or cause it to be forgotten except that We bring forth [one] better than it or similar to it. Do you not know that Allah is over all things competent?', NULL, NULL, '877f017de7bef21857df9a0f8b0d43b9901ec9b39d92c897d22d925a96d76727'),
  ('en.sahih', 2, 107, 114, 'Do you not know that to Allah belongs the dominion of the heavens and the earth and [that] you have not besides Allah any protector or any helper?', NULL, NULL, 'db064b063b585e342b41cb38a15fa09bc855f6bf2395e806494f55cb2c7f660a'),
  ('en.sahih', 2, 108, 115, 'Or do you intend to ask your Messenger as Moses was asked before? And whoever exchanges faith for disbelief has certainly strayed from the soundness of the way.', NULL, NULL, '69256af002d576ff02c83563e33b0f84c5d2cfb111e797de8ec8fda5b061375d'),
  ('en.sahih', 2, 109, 116, 'Many of the People of the Scripture wish they could turn you back to disbelief after you have believed, out of envy from themselves [even] after the truth has become clear to them. So pardon and overlook until Allah delivers His command. Indeed, Allah is over all things competent.', NULL, NULL, '2ba5b4b522bbd9bd637f63644046f641ff774250226594911b1bc7735df4f248'),
  ('en.sahih', 2, 110, 117, 'And establish prayer and give zakah, and whatever good you put forward for yourselves - you will find it with Allah. Indeed, Allah of what you do, is Seeing.', NULL, NULL, '99a6e99f36f9534efcb5d298e1924a2c1463e6f80569d7fc658d17ac23add661'),
  ('en.sahih', 2, 111, 118, 'And they say, "None will enter Paradise except one who is a Jew or a Christian." That is [merely] their wishful thinking, Say, "Produce your proof, if you should be truthful."', NULL, NULL, '9f6f6fbbc2ceed6b1cbcfa7ae21a54ad50824de1e2c8e51a2d262371238405f0'),
  ('en.sahih', 2, 112, 119, 'Yes [on the contrary], whoever submits his face in Islam to Allah while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve.', NULL, NULL, '34fa330e7dc43b6a32fcae58ba5086862bfbdf9baad7efaaff158e52d065f1f8'),
  ('en.sahih', 2, 113, 120, 'The Jews say "The Christians have nothing [true] to stand on," and the Christians say, "The Jews have nothing to stand on," although they [both] recite the Scripture. Thus the polytheists speak the same as their words. But Allah will judge between them on the Day of Resurrection concerning that over which they used to differ.', NULL, NULL, 'a4015afd83af9e6efb2079306619338c0bbcdd10b17cc528d22f9b6971f8bc31'),
  ('en.sahih', 2, 114, 121, 'And who are more unjust than those who prevent the name of Allah from being mentioned in His mosques and strive toward their destruction. It is not for them to enter them except in fear. For them in this world is disgrace, and they will have in the Hereafter a great punishment.', NULL, NULL, '0e2ee35e79e6cf98f4943c7c51330503f7590510f9206987d332ab4df384b520'),
  ('en.sahih', 2, 115, 122, 'And to Allah belongs the east and the west. So wherever you [might] turn, there is the Face of Allah. Indeed, Allah is all-Encompassing and Knowing.', NULL, NULL, '75d348f790c77f7051ffc24876e6763208070990542adaf0e3b890a71ba5acba'),
  ('en.sahih', 2, 116, 123, 'They say, "Allah has taken a son." Exalted is He! Rather, to Him belongs whatever is in the heavens and the earth. All are devoutly obedient to Him,', NULL, NULL, 'e02c34a44ce88d8c3d97c1ed60460bdfaeed73ef31aa86c18288988b14cf0444'),
  ('en.sahih', 2, 117, 124, 'Originator of the heavens and the earth. When He decrees a matter, He only says to it, "Be," and it is.', NULL, NULL, 'd23192dfbd980541e60cc9ef14f3fc77e254365bba1fbc6a424faadda612d802'),
  ('en.sahih', 2, 118, 125, 'Those who do not know say, "Why does Allah not speak to us or there come to us a sign?" Thus spoke those before them like their words. Their hearts resemble each other. We have shown clearly the signs to a people who are certain [in faith].', NULL, NULL, 'a225f831156eac38d3b9b8da1f7b504de80ebc561f723c04d21265074ea41e90'),
  ('en.sahih', 2, 119, 126, 'Indeed, We have sent you, [O Muhammad], with the truth as a bringer of good tidings and a warner, and you will not be asked about the companions of Hellfire.', NULL, NULL, 'f96844db8ce2af26d912b4b0fc082ece987eca53488fdb79141d21cf2805c0ee'),
  ('en.sahih', 2, 120, 127, 'And never will the Jews or the Christians approve of you until you follow their religion. Say, "Indeed, the guidance of Allah is the [only] guidance." If you were to follow their desires after what has come to you of knowledge, you would have against Allah no protector or helper.', NULL, NULL, '3f1d9139faa4fdf176949f9ed6cc3d3b77902fbb52a96c2de428a48731050950'),
  ('en.sahih', 2, 121, 128, 'Those to whom We have given the Book recite it with its true recital. They [are the ones who] believe in it. And whoever disbelieves in it - it is they who are the losers.', NULL, NULL, 'f7ee75eba351d73418dc384f5d4fa1269e825b82cecaa2593031ffe8d687240b'),
  ('en.sahih', 2, 122, 129, 'O Children of Israel, remember My favor which I have bestowed upon you and that I preferred you over the worlds.', NULL, NULL, 'edd267016d4adb39fcc25c41c586750774f7cade1d28e9b92450bcdb9c1cf8ad'),
  ('en.sahih', 2, 123, 130, 'And fear a Day when no soul will suffice for another soul at all, and no compensation will be accepted from it, nor will any intercession benefit it, nor will they be aided.', NULL, NULL, 'aea126fdf460033ac7a9f04374d302a9260aa5b462cecdc13bbb309babe7ee94'),
  ('en.sahih', 2, 124, 131, 'And [mention, O Muhammad], when Abraham was tried by his Lord with commands and he fulfilled them. [Allah] said, "Indeed, I will make you a leader for the people." [Abraham] said, "And of my descendants?" [Allah] said, "My covenant does not include the wrongdoers."', NULL, NULL, 'c26ac5bfba7808c0e7e9923e61acc0dbd8a08750412f48c04535c4fb0abc6a54'),
  ('en.sahih', 2, 125, 132, 'And [mention] when We made the House a place of return for the people and [a place of] security. And take, [O believers], from the standing place of Abraham a place of prayer. And We charged Abraham and Ishmael, [saying], "Purify My House for those who perform Tawaf and those who are staying [there] for worship and those who bow and prostrate [in prayer]."', NULL, NULL, '0ccc389325118eeafab9cc0cdb3e117c602475a372412d70eb63518fdbd8296a'),
  ('en.sahih', 2, 126, 133, 'And [mention] when Abraham said, "My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allah and the Last Day." [Allah] said. "And whoever disbelieves - I will grant him enjoyment for a little; then I will force him to the punishment of the Fire, and wretched is the destination."', NULL, NULL, '2f8ba5ec2ed5844ab439f5ead56222e947c81de07404c4f39e36ccd11fb67513'),
  ('en.sahih', 2, 127, 134, 'And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], "Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing.', NULL, NULL, '0be7fe6e75bf0bd3f29a08d162687dbbee8872063c7e98d6ccceb28242c5400e'),
  ('en.sahih', 2, 128, 135, 'Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful.', NULL, NULL, '5283ae7e0eeb18ec70522ca8163638546d6db492b69b1f67d7b42a627e7932e5'),
  ('en.sahih', 2, 129, 136, 'Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise."', NULL, NULL, '3b97a07bc4a07ea3e0ebf672c8d5a2ce64ca495eee39bcc5defdc0203d735290'),
  ('en.sahih', 2, 130, 137, 'And who would be averse to the religion of Abraham except one who makes a fool of himself. And We had chosen him in this world, and indeed he, in the Hereafter, will be among the righteous.', NULL, NULL, '5eba1453c7389d0c626df1efb531dbd4fd8f6c810f0057b7c31aae9080d16a94'),
  ('en.sahih', 2, 131, 138, 'When his Lord said to him, "Submit", he said "I have submitted [in Islam] to the Lord of the worlds."', NULL, NULL, '00a83250a6580c78e7fdd788ad353afaa75ae593c9e6aecc79f7f5a0d2a2669a'),
  ('en.sahih', 2, 132, 139, 'And Abraham instructed his sons [to do the same] and [so did] Jacob, [saying], "O my sons, indeed Allah has chosen for you this religion, so do not die except while you are Muslims."', NULL, NULL, 'd2ff618b26bdf03730fdac1ff79906a375b27e19c63758c055a3c51ad48b9c72'),
  ('en.sahih', 2, 133, 140, 'Or were you witnesses when death approached Jacob, when he said to his sons, "What will you worship after me?" They said, "We will worship your God and the God of your fathers, Abraham and Ishmael and Isaac - one God. And we are Muslims [in submission] to Him."', NULL, NULL, 'da27c9b20d42e9d87fe2bc2676558c47d3be5f50d8288f35198768e2979a94a5'),
  ('en.sahih', 2, 134, 141, 'That was a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.', NULL, NULL, 'b95ed9f154a8d646b9225316b796c00f77deec40048e4000dac7e60afe7e5131'),
  ('en.sahih', 2, 135, 142, 'They say, "Be Jews or Christians [so] you will be guided." Say, "Rather, [we follow] the religion of Abraham, inclining toward truth, and he was not of the polytheists."', NULL, NULL, '5ec2db4f0abaf6749f6feef76857ebac82d2db78937af6afaccf7aa9e7e26cb9'),
  ('en.sahih', 2, 136, 143, 'Say, [O believers], "We have believed in Allah and what has been revealed to us and what has been revealed to Abraham and Ishmael and Isaac and Jacob and the Descendants and what was given to Moses and Jesus and what was given to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [in submission] to Him."', NULL, NULL, '9ce1d7e0a950dafa96e91876086a6350f21cde51a4cbcf00a518672aac9bba80'),
  ('en.sahih', 2, 137, 144, 'So if they believe in the same as you believe in, then they have been [rightly] guided; but if they turn away, they are only in dissension, and Allah will be sufficient for you against them. And He is the Hearing, the Knowing.', NULL, NULL, 'def94d97fa78ca38f921b1783ac66846a352aa791384586c1ae8bdcad5c8abd3'),
  ('en.sahih', 2, 138, 145, '[And say, "Ours is] the religion of Allah. And who is better than Allah in [ordaining] religion? And we are worshippers of Him."', NULL, NULL, 'ce4524d3e215418c771ae151fdea1e5e3c740bdf9fccb2acaa7d86791c4184e9'),
  ('en.sahih', 2, 139, 146, 'Say, [O Muhammad], "Do you argue with us about Allah while He is our Lord and your Lord? For us are our deeds, and for you are your deeds. And we are sincere [in deed and intention] to Him."', NULL, NULL, '0f6d2620a2c56edc75f34715a7b94615646e3de92b65e7ba85f23cbf830a2272'),
  ('en.sahih', 2, 140, 147, 'Or do you say that Abraham and Ishmael and Isaac and Jacob and the Descendants were Jews or Christians? Say, "Are you more knowing or is Allah?" And who is more unjust than one who conceals a testimony he has from Allah? And Allah is not unaware of what you do.', NULL, NULL, '35e929a887ae5bd81a47cb8e488a9ca317bfc4c552f07591be5272b8cf9446dd'),
  ('en.sahih', 2, 141, 148, 'That is a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.', NULL, NULL, '1385153ee864ee5fce65c7894133ab36cf4cef0a6fd4e7d98abfec4294de1fcb'),
  ('en.sahih', 2, 142, 149, 'The foolish among the people will say, "What has turned them away from their qiblah, which they used to face?" Say, "To Allah belongs the east and the west. He guides whom He wills to a straight path."', NULL, NULL, 'b834ca98b3585630200f9b0104a7c672b4201923c4ed0798f2b05c76361c70b2'),
  ('en.sahih', 2, 143, 150, 'And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you. And We did not make the qiblah which you used to face except that We might make evident who would follow the Messenger from who would turn back on his heels. And indeed, it is difficult except for those whom Allah has guided. And never would Allah have caused you to lose your faith. Indeed Allah is, to the people, Kind and Merciful.', NULL, NULL, '289a75098eb977188bfcaae3cfc4219e05e7af03724fcc50043b697050eb6257'),
  ('en.sahih', 2, 144, 151, 'We have certainly seen the turning of your face, [O Muhammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face toward al-Masjid al-Haram. And wherever you [believers] are, turn your faces toward it [in prayer]. Indeed, those who have been given the Scripture well know that it is the truth from their Lord. And Allah is not unaware of what they do.', NULL, NULL, 'c41f493e8254f2f58908bddfc56bc7e53533e921d67de8494b0fea34eda48a75'),
  ('en.sahih', 2, 145, 152, 'And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another''s qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers.', NULL, NULL, 'f98a453d41ac6b22f5cfa0642c8a929976a8d2a92f14d78f004c153a5012372c'),
  ('en.sahih', 2, 146, 153, 'Those to whom We gave the Scripture know him as they know their own sons. But indeed, a party of them conceal the truth while they know [it].', NULL, NULL, '5294b71e5c3ba4f098b20748a1e6c4e12c166b836a79867ca988aaa1bdf04d1c'),
  ('en.sahih', 2, 147, 154, 'The truth is from your Lord, so never be among the doubters.', NULL, NULL, '07dd51c544f17bc46bb8f3699cbbbcdb51c24043bd473d0468e4f27dfdc38a36'),
  ('en.sahih', 2, 148, 155, 'For each [religious following] is a direction toward which it faces. So race to [all that is] good. Wherever you may be, Allah will bring you forth [for judgement] all together. Indeed, Allah is over all things competent.', NULL, NULL, '12f5561a488a6abc17575b5e6a5ff59d27cc01d7f8993c7e0738da9eb6c51313'),
  ('en.sahih', 2, 149, 156, 'So from wherever you go out [for prayer, O Muhammad] turn your face toward al- Masjid al-Haram, and indeed, it is the truth from your Lord. And Allah is not unaware of what you do.', NULL, NULL, 'df89e90a47d5f6ad8a3385941e7f9087e85332d3d71999ac18b6f5a906b07a93'),
  ('en.sahih', 2, 150, 157, 'And from wherever you go out [for prayer], turn your face toward al-Masjid al-Haram. And wherever you [believers] may be, turn your faces toward it in order that the people will not have any argument against you, except for those of them who commit wrong; so fear them not but fear Me. And [it is] so I may complete My favor upon you and that you may be guided.', NULL, NULL, '68ac695f8966e20fe8d3c7a29ab3d5b6ceddb0ed3cd5832b215c54999586126e'),
  ('en.sahih', 2, 151, 158, 'Just as We have sent among you a messenger from yourselves reciting to you Our verses and purifying you and teaching you the Book and wisdom and teaching you that which you did not know.', NULL, NULL, '2fe8896d520db09389494ca5c507296936ba60d113b8dc6e1e2f8f9ddaf1d9e5'),
  ('en.sahih', 2, 152, 159, 'So remember Me; I will remember you. And be grateful to Me and do not deny Me.', NULL, NULL, '48561b6c21df1486cc9b7cefe63355481d85670906263f6c4e1b73a5cf01df82'),
  ('en.sahih', 2, 153, 160, 'O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient.', NULL, NULL, '73513c50dbf342952e5f57d0ee5a25041ff8def9dbe1bdda5d5f3561a2a2a7a1'),
  ('en.sahih', 2, 154, 161, 'And do not say about those who are killed in the way of Allah, "They are dead." Rather, they are alive, but you perceive [it] not.', NULL, NULL, '29265c375bc590ccdce4379efc0136ad6182574e2cd8d1dc3190c8432e41e589'),
  ('en.sahih', 2, 155, 162, 'And We will surely test you with something of fear and hunger and a loss of wealth and lives and fruits, but give good tidings to the patient,', NULL, NULL, '2cb9a6ccf15ac7fa8699e5f62447b2765fa8c104640651c0523d9e7b154db2d9'),
  ('en.sahih', 2, 156, 163, 'Who, when disaster strikes them, say, "Indeed we belong to Allah, and indeed to Him we will return."', NULL, NULL, '5d1ba4c7ac992576dc91b24063cec1b897a6790a09c537c7348299adb203de88'),
  ('en.sahih', 2, 157, 164, 'Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided.', NULL, NULL, '01c0485c1a752c0cf3f11d538b6ff9a6c8feb24f8912a2008570019d1fbcf0c8'),
  ('en.sahih', 2, 158, 165, 'Indeed, as-Safa and al-Marwah are among the symbols of Allah. So whoever makes Hajj to the House or performs ''umrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allah is appreciative and Knowing.', NULL, NULL, 'd2b5839eecd0a99722b84b019065c6fd7b55b0f7a8ce77ffc2a617e228db9c5c'),
  ('en.sahih', 2, 159, 166, 'Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse,', NULL, NULL, '0dcacdafb6bcec3584d04f8c2a1fdc4e4341d4e5e75b89575bf4bd9c0194a87d'),
  ('en.sahih', 2, 160, 167, 'Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful.', NULL, NULL, '2c944c17ebc4fb8e66b075ea4dba944c2b5a9aeeed08bc74f690d2f7d66ef534'),
  ('en.sahih', 2, 161, 168, 'Indeed, those who disbelieve and die while they are disbelievers - upon them will be the curse of Allah and of the angels and the people, all together,', NULL, NULL, 'ae664825f5ca27a7b1621a77f712b9856f9ef05d0a9fc136d9381b187627b9b9'),
  ('en.sahih', 2, 162, 169, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.', NULL, NULL, '2e98cddf4c5736aa70835b310e7e5a10290d3801f92a9d7bba49e20d007770f9'),
  ('en.sahih', 2, 163, 170, 'And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful.', NULL, NULL, 'c8c302d8a7d4cc07cc468efd66d4f00455aa40c13b49bed5d339277eccbb3067'),
  ('en.sahih', 2, 164, 171, 'Indeed, in the creation of the heavens and earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allah has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and the earth are signs for a people who use reason.', NULL, NULL, '8773e0046f2c3b4ad589c379178006e7cdc621bfe14cb2de2f55d050c02e6b45'),
  ('en.sahih', 2, 165, 172, 'And [yet], among the people are those who take other than Allah as equals [to Him]. They love them as they [should] love Allah. But those who believe are stronger in love for Allah. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allah and that Allah is severe in punishment.', NULL, NULL, 'b21492b0d412cc378be829ff237f4f76e73c9a9d7e40522257fd60996c88c823'),
  ('en.sahih', 2, 166, 173, '[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship],', NULL, NULL, 'dd20a08944ff130da64c5dcd4e097bd5b0f5d3e8bd27b6cba5ef4c2222a12566'),
  ('en.sahih', 2, 167, 174, 'Those who followed will say, "If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us." Thus will Allah show them their deeds as regrets upon them. And they are never to emerge from the Fire.', NULL, NULL, '655c8d0882222d9e4397d8952c52851ceb446d96a29f02187d47d4639500143a'),
  ('en.sahih', 2, 168, 175, 'O mankind, eat from whatever is on earth [that is] lawful and good and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', NULL, NULL, '8b93f516a4d506ed3984213e4a5af26510ba7e847fd56e40132866fbc7dbc5a5'),
  ('en.sahih', 2, 169, 176, 'He only orders you to evil and immorality and to say about Allah what you do not know.', NULL, NULL, '1da72423a0e9568f4a9ac0f7b866f6b0a629d8b46f561f44a9c5d43420f550ee'),
  ('en.sahih', 2, 170, 177, 'And when it is said to them, "Follow what Allah has revealed," they say, "Rather, we will follow that which we found our fathers doing." Even though their fathers understood nothing, nor were they guided?', NULL, NULL, 'f6489fd7be5aabd55376ae39a1194e5baab5b03a6a20d27dfba96eb3dd9f784a'),
  ('en.sahih', 2, 171, 178, 'The example of those who disbelieve is like that of one who shouts at what hears nothing but calls and cries cattle or sheep - deaf, dumb and blind, so they do not understand.', NULL, NULL, '11e49a48c4756a87ab9cde944f10bd20f28ac7ea4146bfd0d504da89905f09a0'),
  ('en.sahih', 2, 172, 179, 'O you who have believed, eat from the good things which We have provided for you and be grateful to Allah if it is [indeed] Him that you worship.', NULL, NULL, 'fe1062f2a5da3e071508da8db6df235f14be0620c91528608f70b80d1e4e8944'),
  ('en.sahih', 2, 173, 180, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], there is no sin upon him. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '758c1fe1d961f42037d58ac556a37b6d2e40849c5eeec2376bd7f43aab0384c3'),
  ('en.sahih', 2, 174, 181, 'Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment.', NULL, NULL, '8f30054f7a23edc35305ee58e36d2994c7cf02455af7672fe3c0b4bb213a2648'),
  ('en.sahih', 2, 175, 182, 'Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are in pursuit of the Fire!', NULL, NULL, '7412e2b78c55598fbaca3c537b48ba39d516a9c79c021a93af29f1bf34d27c92'),
  ('en.sahih', 2, 176, 183, 'That is [deserved by them] because Allah has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension.', NULL, NULL, 'c573011ca7f6b87c1fed29090c3c5e94f3cb071a70f1afbddc04770809aae864'),
  ('en.sahih', 2, 177, 184, 'Righteousness is not that you turn your faces toward the east or the west, but [true] righteousness is [in] one who believes in Allah, the Last Day, the angels, the Book, and the prophets and gives wealth, in spite of love for it, to relatives, orphans, the needy, the traveler, those who ask [for help], and for freeing slaves; [and who] establishes prayer and gives zakah; [those who] fulfill their promise when they promise; and [those who] are patient in poverty and hardship and during battle. Those are the ones who have been true, and it is those who are the righteous.', NULL, NULL, '5d398bda8da38704ca0ee62d05b2e4bfa57a0f1d6978187a7cc6ef1e7518fff8'),
  ('en.sahih', 2, 178, 185, 'O you who have believed, prescribed for you is legal retribution for those murdered - the free for the free, the slave for the slave, and the female for the female. But whoever overlooks from his brother anything, then there should be a suitable follow-up and payment to him with good conduct. This is an alleviation from your Lord and a mercy. But whoever transgresses after that will have a painful punishment.', NULL, NULL, 'bd55db934cbd4dff42b9e9bef5d83385fefb1cb0fabfa4f138d1832f5961e43a'),
  ('en.sahih', 2, 179, 186, 'And there is for you in legal retribution [saving of] life, O you [people] of understanding, that you may become righteous.', NULL, NULL, '34c706097f43087c1c08bfd83c71c04a2be2d1b53c42315b65538bf1627b1ad3'),
  ('en.sahih', 2, 180, 187, 'Prescribed for you when death approaches [any] one of you if he leaves wealth [is that he should make] a bequest for the parents and near relatives according to what is acceptable - a duty upon the righteous.', NULL, NULL, '12308f27d020a0703c7bb1787ac13952be557674b8acd5b89f37f27facb3e505'),
  ('en.sahih', 2, 181, 188, 'Then whoever alters the bequest after he has heard it - the sin is only upon those who have altered it. Indeed, Allah is Hearing and Knowing.', NULL, NULL, '668c7f945a2edf218878f2fc93ebf2a55c2819fb7bb05ffafe6e2963306adf2c'),
  ('en.sahih', 2, 182, 189, 'But if one fears from the bequeather [some] error or sin and corrects that which is between them, there is no sin upon him. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, 'e40a71b3b1a64d90d9c4cff07fe2ad3ed2fdb0a024d1ebb42268b9073b80466a'),
  ('en.sahih', 2, 183, 190, 'O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -', NULL, NULL, '551bda789ef4f81bae75f6ea59ba4dc3f698d9490fada4dad22de1089e0df682'),
  ('en.sahih', 2, 184, 191, '[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers excess - it is better for him. But to fast is best for you, if you only knew.', NULL, NULL, '1696174c9d5df98e7175ff8053ee50fdc77ae673d97c255bb82db0784426ae42'),
  ('en.sahih', 2, 185, 192, 'The month of Ramadhan [is that] in which was revealed the Qur''an, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the new moon of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allah intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allah for that [to] which He has guided you; and perhaps you will be grateful.', NULL, NULL, 'de73b43e71166b14aa5a52c95b57b089d4880261ec45f714edc49f34ad004e32'),
  ('en.sahih', 2, 186, 193, 'And when My servants ask you, [O Muhammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided.', NULL, NULL, '61499def7ed746078cb14dded67bff14222bbcc8079f26272e9fbff7e908992f'),
  ('en.sahih', 2, 187, 194, 'It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are clothing for you and you are clothing for them. Allah knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allah has decreed for you. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the sunset. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allah, so do not approach them. Thus does Allah make clear His ordinances to the people that they may become righteous.', NULL, NULL, '32db6ee4a7b370ff847645cc043a9e204e5ecd1f6eefc75c2da7d8d1d84e03cf'),
  ('en.sahih', 2, 188, 195, 'And do not consume one another''s wealth unjustly or send it [in bribery] to the rulers in order that [they might aid] you [to] consume a portion of the wealth of the people in sin, while you know [it is unlawful].', NULL, NULL, '3da00e28265e4fbac813fb05f6cbdd24cddf51701a471d0a41c7b5b7cb9986f8'),
  ('en.sahih', 2, 189, 196, 'They ask you, [O Muhammad], about the new moons. Say, "They are measurements of time for the people and for Hajj." And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allah. And enter houses from their doors. And fear Allah that you may succeed.', NULL, NULL, '83eae680abdd454b7868171755ca7fb2215afe3c5653a753d66f5289381deb4d'),
  ('en.sahih', 2, 190, 197, 'Fight in the way of Allah those who fight you but do not transgress. Indeed. Allah does not like transgressors.', NULL, NULL, '8bef726d62dfae4542b4bfcfc28da96f3d82d8c1eae5b649771a4a1afc6f8693'),
  ('en.sahih', 2, 191, 198, 'And kill them wherever you overtake them and expel them from wherever they have expelled you, and fitnah is worse than killing. And do not fight them at al-Masjid al- Haram until they fight you there. But if they fight you, then kill them. Such is the recompense of the disbelievers.', NULL, NULL, 'd8f3107ec17763d6bf4f943296308e276fad4877af22213be75b2af697ca4ada'),
  ('en.sahih', 2, 192, 199, 'And if they cease, then indeed, Allah is Forgiving and Merciful.', NULL, NULL, '219e697b0ab712be8b61431acbde6e5a24ce52d2701cc46003251a570c9bec70'),
  ('en.sahih', 2, 193, 200, 'Fight them until there is no [more] fitnah and [until] worship is [acknowledged to be] for Allah. But if they cease, then there is to be no aggression except against the oppressors.', NULL, NULL, '3ef3ed01dbc1a86f3863237dbf40a3172bcf455ce4521a1cd1b5363980e1db21')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 2, 194, 201, '[Fighting in] the sacred month is for [aggression committed in] the sacred month, and for [all] violations is legal retribution. So whoever has assaulted you, then assault him in the same way that he has assaulted you. And fear Allah and know that Allah is with those who fear Him.', NULL, NULL, 'e039835d834f5b83e395bc28c4979a82887214e8199180b983666fc51df89462'),
  ('en.sahih', 2, 195, 202, 'And spend in the way of Allah and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allah loves the doers of good.', NULL, NULL, 'db8772a4919cd0d0bc4ffa6d89f981a28ca2fa7f211c50476466b86c82481ece'),
  ('en.sahih', 2, 196, 203, 'And complete the Hajj and ''umrah for Allah. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity or sacrifice. And when you are secure, then whoever performs ''umrah [during the Hajj months] followed by Hajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during Hajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Haram. And fear Allah and know that Allah is severe in penalty.', NULL, NULL, '1f8dbdff559ab425626241c5018ecd5d8299847d58e88a8f3290aaab169fc912'),
  ('en.sahih', 2, 197, 204, 'Hajj is [during] well-known months, so whoever has made Hajj obligatory upon himself therein [by entering the state of ihram], there is [to be for him] no sexual relations and no disobedience and no disputing during Hajj. And whatever good you do - Allah knows it. And take provisions, but indeed, the best provision is fear of Allah. And fear Me, O you of understanding.', NULL, NULL, '010068ace78e1bcda5ce8f8e1b646ce0abcb97f0fa8e4c89b1566cfe9c916eab'),
  ('en.sahih', 2, 198, 205, 'There is no blame upon you for seeking bounty from your Lord [during Hajj]. But when you depart from ''Arafat, remember Allah at al- Mash''ar al-Haram. And remember Him, as He has guided you, for indeed, you were before that among those astray.', NULL, NULL, '9bf6bac13d15272ddada245fbcc21d92c1c21fb6f61c9bdfa578d664d8fb085f'),
  ('en.sahih', 2, 199, 206, 'Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, 'be4d720e43b5f9c2b76acd0124494824b03c0e6b9e0c977f9f8f414a82fd335d'),
  ('en.sahih', 2, 200, 207, 'And when you have completed your rites, remember Allah like your [previous] remembrance of your fathers or with [much] greater remembrance. And among the people is he who says, "Our Lord, give us in this world," and he will have in the Hereafter no share.', NULL, NULL, 'ab1914cef3e0762787d1dfb34c6f930421cfbb68da8cbd0694ea1042996350e8'),
  ('en.sahih', 2, 201, 208, 'But among them is he who says, "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire."', NULL, NULL, 'b9ba8a1a2b188367770cddfb2e644f9585fa3d31e7d3c96f25bc0a70da2c574b'),
  ('en.sahih', 2, 202, 209, 'Those will have a share of what they have earned, and Allah is swift in account.', NULL, NULL, 'c6c4649a9d2162fc488d02d02a9d1aacc874f0d20576976ce45c823410db152b'),
  ('en.sahih', 2, 203, 210, 'And remember Allah during [specific] numbered days. Then whoever hastens [his departure] in two days - there is no sin upon him; and whoever delays [until the third] - there is no sin upon him - for him who fears Allah. And fear Allah and know that unto Him you will be gathered.', NULL, NULL, 'db01de293f8c575a5bd59d89672b5bb09225640aa99b77c1d1ee489f647fd295'),
  ('en.sahih', 2, 204, 211, 'And of the people is he whose speech pleases you in worldly life, and he calls Allah to witness as to what is in his heart, yet he is the fiercest of opponents.', NULL, NULL, '9d8486a2ac8e7f40eaae4f507ec118df48d28ca9e4960e8489a5fe9d80720663'),
  ('en.sahih', 2, 205, 212, 'And when he goes away, he strives throughout the land to cause corruption therein and destroy crops and animals. And Allah does not like corruption.', NULL, NULL, '822a1e0c79237516ed552fb5c42ab45b5e676f64b82be9051dc4c8543418922c'),
  ('en.sahih', 2, 206, 213, 'And when it is said to him, "Fear Allah," pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place.', NULL, NULL, 'cabe7f4d2268507e6d26ea8d07c6ad5bcd9b4acbbb32a2193e93cddc31ed0455'),
  ('en.sahih', 2, 207, 214, 'And of the people is he who sells himself, seeking means to the approval of Allah. And Allah is kind to [His] servants.', NULL, NULL, '998b4bbd339c0fa08dedf80095fe25f3878735049a4e3995fc3e25d23fa6c6e5'),
  ('en.sahih', 2, 208, 215, 'O you who have believed, enter into Islam completely [and perfectly] and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', NULL, NULL, '6afd39c4eb605ab529fd660d5e0801b9ae45c486b3ef7a7ab1e0acfa0547e633'),
  ('en.sahih', 2, 209, 216, 'But if you deviate after clear proofs have come to you, then know that Allah is Exalted in Might and Wise.', NULL, NULL, '6feee97c450b7c79e9a19881d2d610ea0b2f5cb09f84978cbc83fd98e0854f55'),
  ('en.sahih', 2, 210, 217, 'Do they await but that Allah should come to them in covers of clouds and the angels [as well] and the matter is [then] decided? And to Allah [all] matters are returned.', NULL, NULL, 'e6d2e0a17bd645aa19d5dddddeb54bc5f3d8b833c8edbd05d28e2a318e4e8f6a'),
  ('en.sahih', 2, 211, 218, 'Ask the Children of Israel how many a sign of evidence We have given them. And whoever exchanges the favor of Allah [for disbelief] after it has come to him - then indeed, Allah is severe in penalty.', NULL, NULL, '74e34c13f9878c5a5af400c942885714c57f118940cc6f1df8cfaa136c3df6c9'),
  ('en.sahih', 2, 212, 219, 'Beautified for those who disbelieve is the life of this world, and they ridicule those who believe. But those who fear Allah are above them on the Day of Resurrection. And Allah gives provision to whom He wills without account.', NULL, NULL, '6b7d98ab4511d17e85558f2e3027b197024187b365f6535661f06fad65aa5af8'),
  ('en.sahih', 2, 213, 220, 'Mankind was [of] one religion [before their deviation]; then Allah sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over the Scripture except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allah guided those who believed to the truth concerning that over which they had differed, by His permission. And Allah guides whom He wills to a straight path.', NULL, NULL, 'a87cdc22a698905995212694ada5cb3ccca1445ab0d2ebe6e154566ac802ad46'),
  ('en.sahih', 2, 214, 221, 'Or do you think that you will enter Paradise while such [trial] has not yet come to you as came to those who passed on before you? They were touched by poverty and hardship and were shaken until [even their] messenger and those who believed with him said, "When is the help of Allah?" Unquestionably, the help of Allah is near.', NULL, NULL, '8ea8a671f6fc67f2eee85717142c37fc17c2186efb9f170965857b2a31dfa3ad'),
  ('en.sahih', 2, 215, 222, 'They ask you, [O Muhammad], what they should spend. Say, "Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allah is Knowing of it."', NULL, NULL, 'f5469a130afc941d8ac53f6151746311eda998b14f290199666816e0022456b7'),
  ('en.sahih', 2, 216, 223, 'Fighting has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allah Knows, while you know not.', NULL, NULL, 'a2e1dd7c07199835976a23eb9f21ec51560fb1ed521c533063fdcb1f48a2b348'),
  ('en.sahih', 2, 217, 224, 'They ask you about the sacred month - about fighting therein. Say, "Fighting therein is great [sin], but averting [people] from the way of Allah and disbelief in Him and [preventing access to] al-Masjid al-Haram and the expulsion of its people therefrom are greater [evil] in the sight of Allah. And fitnah is greater than killing." And they will continue to fight you until they turn you back from your religion if they are able. And whoever of you reverts from his religion [to disbelief] and dies while he is a disbeliever - for those, their deeds have become worthless in this world and the Hereafter, and those are the companions of the Fire, they will abide therein eternally.', NULL, NULL, '5a4d5ef7c1defc44c84a11b6c4ba728bd5dbdf0ed791e7e50859b5736caf1d8a'),
  ('en.sahih', 2, 218, 225, 'Indeed, those who have believed and those who have emigrated and fought in the cause of Allah - those expect the mercy of Allah. And Allah is Forgiving and Merciful.', NULL, NULL, '9b887736f565032ee4e0eb97a3cd694c6d469c1014bf697209166a23e80e713d'),
  ('en.sahih', 2, 219, 226, 'They ask you about wine and gambling. Say, "In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit." And they ask you what they should spend. Say, "The excess [beyond needs]." Thus Allah makes clear to you the verses [of revelation] that you might give thought.', NULL, NULL, '566f24d3cdc0fbf8aac51e2c7380bb9edd832e073c56f768153ad8ff5cc27011'),
  ('en.sahih', 2, 220, 227, 'To this world and the Hereafter. And they ask you about orphans. Say, "Improvement for them is best. And if you mix your affairs with theirs - they are your brothers. And Allah knows the corrupter from the amender. And if Allah had willed, He could have put you in difficulty. Indeed, Allah is Exalted in Might and Wise.', NULL, NULL, 'ed8994e92cc2e750db9fca1d47033a58244e9f0d921793b22045c7e600b109c5'),
  ('en.sahih', 2, 221, 228, 'And do not marry polytheistic women until they believe. And a believing slave woman is better than a polytheist, even though she might please you. And do not marry polytheistic men [to your women] until they believe. And a believing slave is better than a polytheist, even though he might please you. Those invite [you] to the Fire, but Allah invites to Paradise and to forgiveness, by His permission. And He makes clear His verses to the people that perhaps they may remember.', NULL, NULL, '184c53c1e4723416b584404623e3cc9ab33afe9bdba7ae25617119f0cb1c1349'),
  ('en.sahih', 2, 222, 229, 'And they ask you about menstruation. Say, "It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allah has ordained for you. Indeed, Allah loves those who are constantly repentant and loves those who purify themselves."', NULL, NULL, '8c331180f314e937b2ac604d4108f13f570c086b81cb1ad7cec2c95af6bbab2e'),
  ('en.sahih', 2, 223, 230, 'Your wives are a place of sowing of seed for you, so come to your place of cultivation however you wish and put forth [righteousness] for yourselves. And fear Allah and know that you will meet Him. And give good tidings to the believers.', NULL, NULL, '74148cf15f5ec4178ecdc55b67022957f243ede3b5281f0fac6d07035a3a6b30'),
  ('en.sahih', 2, 224, 231, 'And do not make [your oath by] Allah an excuse against being righteous and fearing Allah and making peace among people. And Allah is Hearing and Knowing.', NULL, NULL, '797870f43a5449d42dc89fbdc43cdce8fdf4f44b07d4888d989946c767039a18'),
  ('en.sahih', 2, 225, 232, 'Allah does not impose blame upon you for what is unintentional in your oaths, but He imposes blame upon you for what your hearts have earned. And Allah is Forgiving and Forbearing.', NULL, NULL, 'f7d12d394740cb1ceb4ec5135804cf8dae3367de9e948e69d365c5ca3258e2ce'),
  ('en.sahih', 2, 226, 233, 'For those who swear not to have sexual relations with their wives is a waiting time of four months, but if they return [to normal relations] - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, 'adb6d5e91795dddd916464c150a2c8075df0fd0f0a0adb6d522731bcecf662df'),
  ('en.sahih', 2, 227, 234, 'And if they decide on divorce - then indeed, Allah is Hearing and Knowing.', NULL, NULL, 'f8f744d27b808fc8c54ad3045326c190bad38154d73e80ff9fb6c0d1737faa89'),
  ('en.sahih', 2, 228, 235, 'Divorced women remain in waiting for three periods, and it is not lawful for them to conceal what Allah has created in their wombs if they believe in Allah and the Last Day. And their husbands have more right to take them back in this [period] if they want reconciliation. And due to the wives is similar to what is expected of them, according to what is reasonable. But the men have a degree over them [in responsibility and authority]. And Allah is Exalted in Might and Wise.', NULL, NULL, '12d5752ad76c3af3ab60a5a07c10282525d7317acd6610545eef13307300bb0d'),
  ('en.sahih', 2, 229, 236, 'Divorce is twice. Then, either keep [her] in an acceptable manner or release [her] with good treatment. And it is not lawful for you to take anything of what you have given them unless both fear that they will not be able to keep [within] the limits of Allah. But if you fear that they will not keep [within] the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself. These are the limits of Allah, so do not transgress them. And whoever transgresses the limits of Allah - it is those who are the wrongdoers.', NULL, NULL, '7c65700914a48d2048c722769bae895f3957eb916465dba7efa8072f1b070817'),
  ('en.sahih', 2, 230, 237, 'And if he has divorced her [for the third time], then she is not lawful to him afterward until [after] she marries a husband other than him. And if the latter husband divorces her [or dies], there is no blame upon the woman and her former husband for returning to each other if they think that they can keep [within] the limits of Allah. These are the limits of Allah, which He makes clear to a people who know.', NULL, NULL, 'f4d60da562833d18e3bb52476188676cef8b76c3f28b927832505214656c3713'),
  ('en.sahih', 2, 231, 238, 'And when you divorce women and they have [nearly] fulfilled their term, either retain them according to acceptable terms or release them according to acceptable terms, and do not keep them, intending harm, to transgress [against them]. And whoever does that has certainly wronged himself. And do not take the verses of Allah in jest. And remember the favor of Allah upon you and what has been revealed to you of the Book and wisdom by which He instructs you. And fear Allah and know that Allah is Knowing of all things.', NULL, NULL, '18463546cfcb48fa5ba23579452797553fd8571a14a481e8dcd52c15b7033cc0'),
  ('en.sahih', 2, 232, 239, 'And when you divorce women and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allah and the Last Day. That is better for you and purer, and Allah knows and you know not.', NULL, NULL, 'a8f303508658c66e8a00e44b2f2899e1118d3c286223292cb54f60118e448cad'),
  ('en.sahih', 2, 233, 240, 'Mothers may breastfeed their children two complete years for whoever wishes to complete the nursing [period]. Upon the father is the mothers'' provision and their clothing according to what is acceptable. No person is charged with more than his capacity. No mother should be harmed through her child, and no father through his child. And upon the [father''s] heir is [a duty] like that [of the father]. And if they both desire weaning through mutual consent from both of them and consultation, there is no blame upon either of them. And if you wish to have your children nursed by a substitute, there is no blame upon you as long as you give payment according to what is acceptable. And fear Allah and know that Allah is Seeing of what you do.', NULL, NULL, '12fae6514e8c538f9e67836cbccb2fa83b78c3aae622503d95e4b66c49811f25'),
  ('en.sahih', 2, 234, 241, 'And those who are taken in death among you and leave wives behind - they, [the wives, shall] wait four months and ten [days]. And when they have fulfilled their term, then there is no blame upon you for what they do with themselves in an acceptable manner. And Allah is [fully] Acquainted with what you do.', NULL, NULL, 'eb5d9648a0e7a1c2cc891f83f40807b47428e6820d91dd27257c26556368ea40'),
  ('en.sahih', 2, 235, 242, 'There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allah knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period reaches its end. And know that Allah knows what is within yourselves, so beware of Him. And know that Allah is Forgiving and Forbearing.', NULL, NULL, '992ebd3992abe51bc16281a338ab23262a3c5cecb911008a3214c08019373448'),
  ('en.sahih', 2, 236, 243, 'There is no blame upon you if you divorce women you have not touched nor specified for them an obligation. But give them [a gift of] compensation - the wealthy according to his capability and the poor according to his capability - a provision according to what is acceptable, a duty upon the doers of good.', NULL, NULL, 'd3846ab6f4c750d2a0f9a92d1b20c4c1cacc5212bbf0d26c4c86aebe886b7f53'),
  ('en.sahih', 2, 237, 244, 'And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allah, of whatever you do, is Seeing.', NULL, NULL, 'b55964bb0d28e5ca30994fafc87fc5b35dca8401a7b520acff68d538c29d9f3d'),
  ('en.sahih', 2, 238, 245, 'Maintain with care the [obligatory] prayers and [in particular] the middle prayer and stand before Allah, devoutly obedient.', NULL, NULL, '10548cea07e89e11c02ad085b74f168ae4e29db4c7aa83ed1c3ae88179e35f4b'),
  ('en.sahih', 2, 239, 246, 'And if you fear [an enemy, then pray] on foot or riding. But when you are secure, then remember Allah [in prayer], as He has taught you that which you did not [previously] know.', NULL, NULL, '2acd842c71ec45bef282613ef020b5f0bbe143793820d80f1f7b764ed722f89f'),
  ('en.sahih', 2, 240, 247, 'And those who are taken in death among you and leave wives behind - for their wives is a bequest: maintenance for one year without turning [them] out. But if they leave [of their own accord], then there is no blame upon you for what they do with themselves in an acceptable way. And Allah is Exalted in Might and Wise.', NULL, NULL, '72a05e88e51e5021d75df6d610690940ed5d06ca22b76f62c6ead9b4a35905b4'),
  ('en.sahih', 2, 241, 248, 'And for divorced women is a provision according to what is acceptable - a duty upon the righteous.', NULL, NULL, '1b13f5dbac751d11f55b83b6d5ddeddd22d9e1aaf1ae8ec0c9605cd4a4065788'),
  ('en.sahih', 2, 242, 249, 'Thus does Allah make clear to you His verses that you might use reason.', NULL, NULL, '91ab2cdbd028e8618c3589046ccdb6a730d0b253ee58ee3c722f11c86bf28901'),
  ('en.sahih', 2, 243, 250, 'Have you not considered those who left their homes in many thousands, fearing death? Allah said to them, "Die"; then He restored them to life. And Allah is full of bounty to the people, but most of the people do not show gratitude.', NULL, NULL, '0cd4b46d048a3cca095ce792fc855b3208db3fd412957418a5fa47d87e8327bd'),
  ('en.sahih', 2, 244, 251, 'And fight in the cause of Allah and know that Allah is Hearing and Knowing.', NULL, NULL, 'fb65da95c3f8782260cc7f0946cb03c52f7fb8e8c59b71560500b0b36b81343f'),
  ('en.sahih', 2, 245, 252, 'Who is it that would loan Allah a goodly loan so He may multiply it for him many times over? And it is Allah who withholds and grants abundance, and to Him you will be returned.', NULL, NULL, '63a601296cca1cd438d2ffdda1d8304ea55e96a819d95bec19db0915a7da0d5e'),
  ('en.sahih', 2, 246, 253, 'Have you not considered the assembly of the Children of Israel after [the time of] Moses when they said to a prophet of theirs, "Send to us a king, and we will fight in the way of Allah "? He said, "Would you perhaps refrain from fighting if fighting was prescribed for you?" They said, "And why should we not fight in the cause of Allah when we have been driven out from our homes and from our children?" But when fighting was prescribed for them, they turned away, except for a few of them. And Allah is Knowing of the wrongdoers.', NULL, NULL, 'c2fa3a78b6e6f9e6d17227bcb2db52f85b71ae115e80184b9341dab6c17dc64e'),
  ('en.sahih', 2, 247, 254, 'And their prophet said to them, "Indeed, Allah has sent to you Saul as a king." They said, "How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?" He said, "Indeed, Allah has chosen him over you and has increased him abundantly in knowledge and stature. And Allah gives His sovereignty to whom He wills. And Allah is all-Encompassing [in favor] and Knowing."', NULL, NULL, 'f5f338577b8a9edffe4134b1b3537ed9896111d71e056feb221d6f9508ae73d8'),
  ('en.sahih', 2, 248, 255, 'And their prophet said to them, "Indeed, a sign of his kingship is that the chest will come to you in which is assurance from your Lord and a remnant of what the family of Moses and the family of Aaron had left, carried by the angels. Indeed in that is a sign for you, if you are believers."', NULL, NULL, '0ad1a98e43273d5983beff549a705f489dd1d71193fb7edf694a36fcb2e357fc'),
  ('en.sahih', 2, 249, 256, 'And when Saul went forth with the soldiers, he said, "Indeed, Allah will be testing you with a river. So whoever drinks from it is not of me, and whoever does not taste it is indeed of me, excepting one who takes [from it] in the hollow of his hand." But they drank from it, except a [very] few of them. Then when he had crossed it along with those who believed with him, they said, "There is no power for us today against Goliath and his soldiers." But those who were certain that they would meet Allah said, "How many a small company has overcome a large company by permission of Allah. And Allah is with the patient."', NULL, NULL, 'c5ef2ccf79cc686d6e64c28ab7a9fb889b85b249b9b45b6e183fbc63d1e8986a'),
  ('en.sahih', 2, 250, 257, 'And when they went forth to [face] Goliath and his soldiers, they said, "Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people."', NULL, NULL, 'ab9dd86822730255adef6e8c8dc813850dbb9cee417e26473bf28e9feaf1cebc'),
  ('en.sahih', 2, 251, 258, 'So they defeated them by permission of Allah, and David killed Goliath, and Allah gave him the kingship and prophethood and taught him from that which He willed. And if it were not for Allah checking [some] people by means of others, the earth would have been corrupted, but Allah is full of bounty to the worlds.', NULL, NULL, '38a81876a02d44bab35a48516f884bbf96be300eb57d1fc01aa8c5bf670c4059'),
  ('en.sahih', 2, 252, 259, 'These are the verses of Allah which We recite to you, [O Muhammad], in truth. And indeed, you are from among the messengers.', NULL, NULL, '2f23bf046d26a4f79be4c23bcced4379f6e8cd8bf2be54f81e53fde0895a0e40'),
  ('en.sahih', 2, 253, 260, 'Those messengers - some of them We caused to exceed others. Among them were those to whom Allah spoke, and He raised some of them in degree. And We gave Jesus, the Son of Mary, clear proofs, and We supported him with the Pure Spirit. If Allah had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allah had willed, they would not have fought each other, but Allah does what He intends.', NULL, NULL, '0d94c23fa5786275a9dda200b1d6b7608e6f616d887f526b7fa889c407e69917'),
  ('en.sahih', 2, 254, 261, 'O you who have believed, spend from that which We have provided for you before there comes a Day in which there is no exchange and no friendship and no intercession. And the disbelievers - they are the wrongdoers.', NULL, NULL, '51daef1625ab4914e9007f05f80bf5a4b270e0e2a617261b85a05389fa04534a'),
  ('en.sahih', 2, 255, 262, 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', NULL, NULL, '7a81e2092444f0d7a1ee4a8b9817652642528f83c6bc4e92b628867c6b5dbfad'),
  ('en.sahih', 2, 256, 263, 'There shall be no compulsion in [acceptance of] the religion. The right course has become clear from the wrong. So whoever disbelieves in Taghut and believes in Allah has grasped the most trustworthy handhold with no break in it. And Allah is Hearing and Knowing.', NULL, NULL, 'f5f7907b152fa3170bda0951944d2494740f1e1965117a96cd93f7cd56d2856f'),
  ('en.sahih', 2, 257, 264, 'Allah is the ally of those who believe. He brings them out from darknesses into the light. And those who disbelieve - their allies are Taghut. They take them out of the light into darknesses. Those are the companions of the Fire; they will abide eternally therein.', NULL, NULL, '132b199aa68537ef99c7baee7c27e7ce04462e8b3679b04ee8704dcd6354003f'),
  ('en.sahih', 2, 258, 265, 'Have you not considered the one who argued with Abraham about his Lord [merely] because Allah had given him kingship? When Abraham said, "My Lord is the one who gives life and causes death," he said, "I give life and cause death." Abraham said, "Indeed, Allah brings up the sun from the east, so bring it up from the west." So the disbeliever was overwhelmed [by astonishment], and Allah does not guide the wrongdoing people.', NULL, NULL, '3f7146dfc2f585f38f9526bea49ea3e5b0e8d16be56619da9f903a3bebcfa64a'),
  ('en.sahih', 2, 259, 266, 'Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said, "How will Allah bring this to life after its death?" So Allah caused him to die for a hundred years; then He revived him. He said, "How long have you remained?" The man said, "I have remained a day or part of a day." He said, "Rather, you have remained one hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of this donkey] - how We raise them and then We cover them with flesh." And when it became clear to him, he said, "I know that Allah is over all things competent."', NULL, NULL, 'a9d58358e1bc1a7b5d5ce5caa0262b2a0ac3c72d4e87df508c6e3bc3cb0ac01e'),
  ('en.sahih', 2, 260, 267, 'And [mention] when Abraham said, "My Lord, show me how You give life to the dead." [Allah] said, "Have you not believed?" He said, "Yes, but [I ask] only that my heart may be satisfied." [Allah] said, "Take four birds and commit them to yourself. Then [after slaughtering them] put on each hill a portion of them; then call them - they will come [flying] to you in haste. And know that Allah is Exalted in Might and Wise."', NULL, NULL, '8b64900c057c92f0ca4805ba5024733491246696428e0af90aa06a6abff806e2'),
  ('en.sahih', 2, 261, 268, 'The example of those who spend their wealth in the way of Allah is like a seed [of grain] which grows seven spikes; in each spike is a hundred grains. And Allah multiplies [His reward] for whom He wills. And Allah is all-Encompassing and Knowing.', NULL, NULL, '4d5ca92c4cd2ace79dcc669e99902fd2523995d5a52787439507d6439c2eba5c'),
  ('en.sahih', 2, 262, 269, 'Those who spend their wealth in the way of Allah and then do not follow up what they have spent with reminders [of it] or [other] injury will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.', NULL, NULL, '263413ca882e445ce64ccb61e92806d16909e3c728d047aa4fb5d12011b0bdac'),
  ('en.sahih', 2, 263, 270, 'Kind speech and forgiveness are better than charity followed by injury. And Allah is Free of need and Forbearing.', NULL, NULL, 'aa9805c5981c79673a25e49ad90b96f6e8de16d7d8f2bfae5564e183bca21784'),
  ('en.sahih', 2, 264, 271, 'O you who have believed, do not invalidate your charities with reminders or injury as does one who spends his wealth [only] to be seen by the people and does not believe in Allah and the Last Day. His example is like that of a [large] smooth stone upon which is dust and is hit by a downpour that leaves it bare. They are unable [to keep] anything of what they have earned. And Allah does not guide the disbelieving people.', NULL, NULL, '1fe3bfd677885b6a49a4f795501b641ac6e2965c596c00ab41e5fb882d1cfe5c'),
  ('en.sahih', 2, 265, 272, 'And the example of those who spend their wealth seeking means to the approval of Allah and assuring [reward for] themselves is like a garden on high ground which is hit by a downpour - so it yields its fruits in double. And [even] if it is not hit by a downpour, then a drizzle [is sufficient]. And Allah, of what you do, is Seeing.', NULL, NULL, 'ef32ca5194acebe67da921db836eab178f47a91c152bca909f36aa0a439a7096'),
  ('en.sahih', 2, 266, 273, 'Would one of you like to have a garden of palm trees and grapevines underneath which rivers flow in which he has from every fruit? But he is afflicted with old age and has weak offspring, and it is hit by a whirlwind containing fire and is burned. Thus does Allah make clear to you [His] verses that you might give thought.', NULL, NULL, '1a9141d0dd2a54ce794aea0059d8fb3378cf65b3e9d8a91a0c2e12d710d1ae64'),
  ('en.sahih', 2, 267, 274, 'O you who have believed, spend from the good things which you have earned and from that which We have produced for you from the earth. And do not aim toward the defective therefrom, spending [from that] while you would not take it [yourself] except with closed eyes. And know that Allah is Free of need and Praiseworthy.', NULL, NULL, '489309cba100c9883bc2e48846dc2ccdd285ff5c885683e6ae541bdf68a00414'),
  ('en.sahih', 2, 268, 275, 'Satan threatens you with poverty and orders you to immorality, while Allah promises you forgiveness from Him and bounty. And Allah is all-Encompassing and Knowing.', NULL, NULL, '96e96dc82d4e797324e69bfeb243a83204aa0591b72397e547e8a1351636b557'),
  ('en.sahih', 2, 269, 276, 'He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good. And none will remember except those of understanding.', NULL, NULL, '7d34360da57a22a073478a4b42dc71201dd43af6357cbfe3955378efec3f2b7a'),
  ('en.sahih', 2, 270, 277, 'And whatever you spend of expenditures or make of vows - indeed, Allah knows of it. And for the wrongdoers there are no helpers.', NULL, NULL, '63014eec2fd7a01a400502749ba10270955e53636963b1640af631fe6678bbe0'),
  ('en.sahih', 2, 271, 278, 'If you disclose your charitable expenditures, they are good; but if you conceal them and give them to the poor, it is better for you, and He will remove from you some of your misdeeds [thereby]. And Allah, with what you do, is [fully] Acquainted.', NULL, NULL, '4916f226edcf5a1cabacf1e159d99ca9f8f0e458d2e89cf18be7ae38e032685b'),
  ('en.sahih', 2, 272, 279, 'Not upon you, [O Muhammad], is [responsibility for] their guidance, but Allah guides whom He wills. And whatever good you [believers] spend is for yourselves, and you do not spend except seeking the countenance of Allah. And whatever you spend of good - it will be fully repaid to you, and you will not be wronged.', NULL, NULL, '2431d8499e16a15f8e5143a96303e2deafc259fd10bc5a893fac5e831cbf636b'),
  ('en.sahih', 2, 273, 280, '[Charity is] for the poor who have been restricted for the cause of Allah, unable to move about in the land. An ignorant [person] would think them self-sufficient because of their restraint, but you will know them by their [characteristic] sign. They do not ask people persistently [or at all]. And whatever you spend of good - indeed, Allah is Knowing of it.', NULL, NULL, '61d0b427d4371f0e6ff5019ec9f9ff97b5a2ee7f842313bc06f1354f0c3611ea'),
  ('en.sahih', 2, 274, 281, 'Those who spend their wealth [in Allah ''s way] by night and by day, secretly and publicly - they will have their reward with their Lord. And no fear will there be concerning them, nor will they grieve.', NULL, NULL, 'c56ba4ad3c02a2a5e34273cd54b6a1caf7df55a608769109be506de464ca8505'),
  ('en.sahih', 2, 275, 282, 'Those who consume interest cannot stand [on the Day of Resurrection] except as one stands who is being beaten by Satan into insanity. That is because they say, "Trade is [just] like interest." But Allah has permitted trade and has forbidden interest. So whoever has received an admonition from his Lord and desists may have what is past, and his affair rests with Allah. But whoever returns to [dealing in interest or usury] - those are the companions of the Fire; they will abide eternally therein.', NULL, NULL, 'a9763386791735f81eb9ee4ad63ea9b3aa13c661470513de227c06a886b7fbf6'),
  ('en.sahih', 2, 276, 283, 'Allah destroys interest and gives increase for charities. And Allah does not like every sinning disbeliever.', NULL, NULL, '1caa2171c515d3256dd0fe8f8a23d4719af31177c580ce882af02b6d0e39b37f'),
  ('en.sahih', 2, 277, 284, 'Indeed, those who believe and do righteous deeds and establish prayer and give zakah will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.', NULL, NULL, 'd6e3891549f630817622366c0b5b0f0f60e737ef033c6baacc7b7699f9ad6812'),
  ('en.sahih', 2, 278, 285, 'O you who have believed, fear Allah and give up what remains [due to you] of interest, if you should be believers.', NULL, NULL, '9c090887e5ea9b41372afce30a0e3408d6a07b6056a716abf936b57cba11d5c3'),
  ('en.sahih', 2, 279, 286, 'And if you do not, then be informed of a war [against you] from Allah and His Messenger. But if you repent, you may have your principal - [thus] you do no wrong, nor are you wronged.', NULL, NULL, '9530c682991c330b55aa162ffdd6c4b7e00321041e38fe43f74a8383010b56c9'),
  ('en.sahih', 2, 280, 287, 'And if someone is in hardship, then [let there be] postponement until [a time of] ease. But if you give [from your right as] charity, then it is better for you, if you only knew.', NULL, NULL, '5f1fdb0bdbc2ea7c47276a0c28360d76f0ae13141797265ebe47605a51cf606c'),
  ('en.sahih', 2, 281, 288, 'And fear a Day when you will be returned to Allah. Then every soul will be compensated for what it earned, and they will not be treated unjustly.', NULL, NULL, '52c3077d7ac74a23a9b8d3d9e8feb0ec622a1d028806345bd1ae458839cdb83f'),
  ('en.sahih', 2, 282, 289, 'O you who have believed, when you contract a debt for a specified term, write it down. And let a scribe write [it] between you in justice. Let no scribe refuse to write as Allah has taught him. So let him write and let the one who has the obligation dictate. And let him fear Allah, his Lord, and not leave anything out of it. But if the one who has the obligation is of limited understanding or weak or unable to dictate himself, then let his guardian dictate in justice. And bring to witness two witnesses from among your men. And if there are not two men [available], then a man and two women from those whom you accept as witnesses - so that if one of the women errs, then the other can remind her. And let not the witnesses refuse when they are called upon. And do not be [too] weary to write it, whether it is small or large, for its [specified] term. That is more just in the sight of Allah and stronger as evidence and more likely to prevent doubt between you, except when it is an immediate transaction which you conduct among yourselves. For [then] there is no blame upon you if you do not write it. And take witnesses when you conclude a contract. Let no scribe be harmed or any witness. For if you do so, indeed, it is [grave] disobedience in you. And fear Allah. And Allah teaches you. And Allah is Knowing of all things.', NULL, NULL, '09088faafc88d1557fdb0a0d44ff1f7b361fe7314711bbd9c5e9bc68039b1630'),
  ('en.sahih', 2, 283, 290, 'And if you are on a journey and cannot find a scribe, then a security deposit [should be] taken. And if one of you entrusts another, then let him who is entrusted discharge his trust [faithfully] and let him fear Allah, his Lord. And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do.', NULL, NULL, '2217a331239b57a61f9acc43172023427b799bd0f51f1142fd67842852920170'),
  ('en.sahih', 2, 284, 291, 'To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allah will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allah is over all things competent.', NULL, NULL, '78a901aaa20f057321027ac596aec2b90ee6eb8d9608e09ac63b76011b0d5a3c'),
  ('en.sahih', 2, 285, 292, 'The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], "We make no distinction between any of His messengers." And they say, "We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination."', NULL, NULL, '0738d3333f6f7a0a673dbe786073a4ce6957c0956c48a9f89f7c7ec4d2c7d025'),
  ('en.sahih', 2, 286, 293, 'Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."', NULL, NULL, '561cb30663be587a86a8ad617526ca94b0a114ecc3d7d6bbcdba9fb9c9bbb8e8'),
  ('en.sahih', 3, 1, 294, 'Alif, Lam, Meem.', NULL, NULL, 'c0271a8d54e5b8ca6868a624b25c94d32c317177546d0577b0ceceac58956c78'),
  ('en.sahih', 3, 2, 295, 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of existence.', NULL, NULL, 'd5ba0d1bbd06fea41c2a5cac1b654a2815545eca25a705c949277df18df79e29'),
  ('en.sahih', 3, 3, 296, 'He has sent down upon you, [O Muhammad], the Book in truth, confirming what was before it. And He revealed the Torah and the Gospel.', NULL, NULL, 'bdda5937ffd724452be60efb6b2bee620ac4478edeaf555d15d8d540c6cf5909'),
  ('en.sahih', 3, 4, 297, 'Before, as guidance for the people. And He revealed the Qur''an. Indeed, those who disbelieve in the verses of Allah will have a severe punishment, and Allah is exalted in Might, the Owner of Retribution.', NULL, NULL, '43e60bf1f8c1bb94db63986ef8c4b79222a6eb3c1daf0699e7706eea982c8613'),
  ('en.sahih', 3, 5, 298, 'Indeed, from Allah nothing is hidden in the earth nor in the heaven.', NULL, NULL, '00401c2fdc308baedf3ceb6379377e48e059d8dfee9249e2fb5d68a53ad31b9f'),
  ('en.sahih', 3, 6, 299, 'It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise.', NULL, NULL, 'f16ffabf7d1e4ff37a6c21caca31274d2104e593c2e31689e611a7c8c155551e'),
  ('en.sahih', 3, 7, 300, 'It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, "We believe in it. All [of it] is from our Lord." And no one will be reminded except those of understanding.', NULL, NULL, '805267d47587d321ed425825927a2a466011be5ea57b31312f21c7d40c171c6f')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 3, 8, 301, '[Who say], "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.', NULL, NULL, 'b6999c9d031e4b18a05761e8f704cfe9bd83d2eb2111499a7b08143c10ae5aa8'),
  ('en.sahih', 3, 9, 302, 'Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."', NULL, NULL, '735601f7b39f68385742dc4a1b7401eda3831ee28f4c68487807ee27637340ee'),
  ('en.sahih', 3, 10, 303, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all. And it is they who are fuel for the Fire.', NULL, NULL, '5cc524167e6b2885d8818c24a09bd415d22e8280d84bb5e5109b35a21b6f81d2'),
  ('en.sahih', 3, 11, 304, '[Theirs is] like the custom of the people of Pharaoh and those before them. They denied Our signs, so Allah seized them for their sins. And Allah is severe in penalty.', NULL, NULL, 'adbbfedc5a92c443728aca5e8f5ffab9839305f756792125f18f96525286a371'),
  ('en.sahih', 3, 12, 305, 'Say to those who disbelieve, "You will be overcome and gathered together to Hell, and wretched is the resting place."', NULL, NULL, '9b88b37f68490caa2477134ba9a75099853d57f5b00ae645e78ef4a2bce23aff'),
  ('en.sahih', 3, 13, 306, 'Already there has been for you a sign in the two armies which met - one fighting in the cause of Allah and another of disbelievers. They saw them [to be] twice their [own] number by [their] eyesight. But Allah supports with His victory whom He wills. Indeed in that is a lesson for those of vision.', NULL, NULL, '4c2d56f1d1c007b42e06a1252d2f3d74afac58b498349e010d141391e5dfc0f0'),
  ('en.sahih', 3, 14, 307, 'Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allah has with Him the best return.', NULL, NULL, '03420a9bf3f3f10c9bc30400b35a00c246e5e3ec19df80d0ff5d68b0cdd1763e'),
  ('en.sahih', 3, 15, 308, 'Say, "Shall I inform you of [something] better than that? For those who fear Allah will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allah. And Allah is Seeing of [His] servants -', NULL, NULL, '8eab9dd1c3588caab42ef59457b3b672054d417f5517441b091b838f9c9aec2f'),
  ('en.sahih', 3, 16, 309, 'Those who say, "Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,"', NULL, NULL, '301168f5d665b029b422c508eabb263c24720cf3f2647afba069ceb929aace7f'),
  ('en.sahih', 3, 17, 310, 'The patient, the true, the obedient, those who spend [in the way of Allah], and those who seek forgiveness before dawn.', NULL, NULL, '9861c783cf426499e519c5317006c29702ec84d3b45e7b507a22906306fce1d7'),
  ('en.sahih', 3, 18, 311, 'Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise.', NULL, NULL, 'f1697138603150d1cc18cd4179cf683077eb63ff4cfb4ab8212101a578d72f80'),
  ('en.sahih', 3, 19, 312, 'Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account.', NULL, NULL, '5c6eae35f9354b13373dc0207ac31dad5772f44d7bf9f28f52cab45044d2a4ae'),
  ('en.sahih', 3, 20, 313, 'So if they argue with you, say, "I have submitted myself to Allah [in Islam], and [so have] those who follow me." And say to those who were given the Scripture and [to] the unlearned, "Have you submitted yourselves?" And if they submit [in Islam], they are rightly guided; but if they turn away - then upon you is only the [duty of] notification. And Allah is Seeing of [His] servants.', NULL, NULL, 'd2da8c4c3355b3f1ca920ecd9458119e851739d2a5fa32e2898a5dd7c6f885db'),
  ('en.sahih', 3, 21, 314, 'Those who disbelieve in the signs of Allah and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment.', NULL, NULL, '372443e4289a8f0115f1d8a4c70cbea19d769560d34afeea12f4b37029e4ac74'),
  ('en.sahih', 3, 22, 315, 'They are the ones whose deeds have become worthless in this world and the Hereafter, and for them there will be no helpers.', NULL, NULL, 'd937145a65988318512b579279ab8b218002fdb2118febf1b3b7ceb194789499'),
  ('en.sahih', 3, 23, 316, 'Do you not consider, [O Muhammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allah that it should arbitrate between them; then a party of them turns away, and they are refusing.', NULL, NULL, '297a79ef7c8947e8efa92da09926b7b8d7e797ce92f7cb461747c9734ebd522a'),
  ('en.sahih', 3, 24, 317, 'That is because they say, "Never will the Fire touch us except for [a few] numbered days," and [because] they were deluded in their religion by what they were inventing.', NULL, NULL, '8f1f4dd860325f3913ca9a6de3b56e90eb726265f26010ca5fb597c277398a4d'),
  ('en.sahih', 3, 25, 318, 'So how will it be when We assemble them for a Day about which there is no doubt? And each soul will be compensated [in full for] what it earned, and they will not be wronged.', NULL, NULL, '7d0b76b719932f09afd23e7d40ed653aa3ebf61d4f574b28764a5153cfca2f6d'),
  ('en.sahih', 3, 26, 319, 'Say, "O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent.', NULL, NULL, 'a50974e96b813aa72eb5daa188d63d20cb7365ea7688a0a814f85c4e242f8776'),
  ('en.sahih', 3, 27, 320, 'You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account."', NULL, NULL, 'd6a3eda42f6507f61236a19e1c969d079fd02214538e452d7729be19469646ff'),
  ('en.sahih', 3, 28, 321, 'Let not believers take disbelievers as allies rather than believers. And whoever [of you] does that has nothing with Allah, except when taking precaution against them in prudence. And Allah warns you of Himself, and to Allah is the [final] destination.', NULL, NULL, 'ef633cdf17385fab53b4bebd6b4fd8693b9f1df9b0df813f457056d51d2d7733'),
  ('en.sahih', 3, 29, 322, 'Say, "Whether you conceal what is in your breasts or reveal it, Allah knows it. And He knows that which is in the heavens and that which is on the earth. And Allah is over all things competent.', NULL, NULL, '97c7119ab6bb89e030fec151ed09e65a7409ca711840ce705547f5fa1af371a6'),
  ('en.sahih', 3, 30, 323, 'The Day every soul will find what it has done of good present [before it] and what it has done of evil, it will wish that between itself and that [evil] was a great distance. And Allah warns you of Himself, and Allah is Kind to [His] servants."', NULL, NULL, 'fa8c03a9762407aff80fbb4207f73d40f41b399902b02914240fb7a570cee4a8'),
  ('en.sahih', 3, 31, 324, 'Say, [O Muhammad], "If you should love Allah, then follow me, [so] Allah will love you and forgive you your sins. And Allah is Forgiving and Merciful."', NULL, NULL, '58466c30811a8f2800cdf9d11db0e40a28708d592383138a994af3b971c9c0ab'),
  ('en.sahih', 3, 32, 325, 'Say, "Obey Allah and the Messenger." But if they turn away - then indeed, Allah does not like the disbelievers.', NULL, NULL, '2297442b0c3ecbcf1e2961cd5274a1e009f9cb2fc2a7b89e9f1c43a272ddfbc8'),
  ('en.sahih', 3, 33, 326, 'Indeed, Allah chose Adam and Noah and the family of Abraham and the family of ''Imran over the worlds -', NULL, NULL, 'c220c687d360ae6c690c36c06546dd651b5d52789336efbcd275bbd39d746701'),
  ('en.sahih', 3, 34, 327, 'Descendants, some of them from others. And Allah is Hearing and Knowing.', NULL, NULL, 'fc9bb5dfbd77758884c9e2500b8f57c87f4f1757411a775cf6135f9e3b3a434a'),
  ('en.sahih', 3, 35, 328, '[Mention, O Muhammad], when the wife of ''Imran said, "My Lord, indeed I have pledged to You what is in my womb, consecrated [for Your service], so accept this from me. Indeed, You are the Hearing, the Knowing."', NULL, NULL, 'fac9df94b2800c08b8782417e88f377839a53aa5d08d33857220bf967b7ace2a'),
  ('en.sahih', 3, 36, 329, 'But when she delivered her, she said, "My Lord, I have delivered a female." And Allah was most knowing of what she delivered, "And the male is not like the female. And I have named her Mary, and I seek refuge for her in You and [for] her descendants from Satan, the expelled [from the mercy of Allah]."', NULL, NULL, '298e8deddd90c883f199dcc8794e7090c44c3059b923e5d2e8a58c5e179bf46b'),
  ('en.sahih', 3, 37, 330, 'So her Lord accepted her with good acceptance and caused her to grow in a good manner and put her in the care of Zechariah. Every time Zechariah entered upon her in the prayer chamber, he found with her provision. He said, "O Mary, from where is this [coming] to you?" She said, "It is from Allah. Indeed, Allah provides for whom He wills without account."', NULL, NULL, '7f33d47ce4fa480a5a0edbc2df1482686e1680a82dd9f671af966c606ee9e0c4'),
  ('en.sahih', 3, 38, 331, 'At that, Zechariah called upon his Lord, saying, "My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication."', NULL, NULL, 'ed3b2acf59dac508e6c9b236a6e1956ae330336f23775a7da283bca4c5006298'),
  ('en.sahih', 3, 39, 332, 'So the angels called him while he was standing in prayer in the chamber, "Indeed, Allah gives you good tidings of John, confirming a word from Allah and [who will be] honorable, abstaining [from women], and a prophet from among the righteous."', NULL, NULL, 'cc2644c3db3f7c49d9b45cdded9143e1a37886d52143da21b191aeabf41df580'),
  ('en.sahih', 3, 40, 333, 'He said, "My Lord, how will I have a boy when I have reached old age and my wife is barren?" The angel said, "Such is Allah; He does what He wills."', NULL, NULL, '2efb3391f72243a0532c36c413e2171473b16eaade5a8c5f5f56dabe40420e20'),
  ('en.sahih', 3, 41, 334, 'He said, "My Lord, make for me a sign." He Said, "Your sign is that you will not [be able to] speak to the people for three days except by gesture. And remember your Lord much and exalt [Him with praise] in the evening and the morning."', NULL, NULL, '068b67f8660aa0bdf50a5cc00003e2c7a44f0e93e458277bb4b272a1997424e4'),
  ('en.sahih', 3, 42, 335, 'And [mention] when the angels said, "O Mary, indeed Allah has chosen you and purified you and chosen you above the women of the worlds.', NULL, NULL, '8475387db18b43725c0f2bfef3124e489cf2fad64f9697721e1c005159cae063'),
  ('en.sahih', 3, 43, 336, 'O Mary, be devoutly obedient to your Lord and prostrate and bow with those who bow [in prayer]."', NULL, NULL, '505a31c856c59f383a2ea78971ca08274180aabec3f0c0dac936f4cca3cfe6da'),
  ('en.sahih', 3, 44, 337, 'That is from the news of the unseen which We reveal to you, [O Muhammad]. And you were not with them when they cast their pens as to which of them should be responsible for Mary. Nor were you with them when they disputed.', NULL, NULL, '46a1f00cde91dece29c27962ad39890b1ac3eeddad5975dd6992a308db35d2e1'),
  ('en.sahih', 3, 45, 338, '[And mention] when the angels said, "O Mary, indeed Allah gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allah].', NULL, NULL, '98a19c6182364dc0adf0403e33ec771c1e6044817c71e5a3d78754b2c341fba2'),
  ('en.sahih', 3, 46, 339, 'He will speak to the people in the cradle and in maturity and will be of the righteous."', NULL, NULL, '3ca2c4121a6c3204fa0ef4350406c557b176eee88a649a33c641049a504460d0'),
  ('en.sahih', 3, 47, 340, 'She said, "My Lord, how will I have a child when no man has touched me?" [The angel] said, "Such is Allah; He creates what He wills. When He decrees a matter, He only says to it, ''Be,'' and it is.', NULL, NULL, '72b3a4625ac8c504540f0a9632e49fc7af9cad415ff59d9dbac0740fe359fc88'),
  ('en.sahih', 3, 48, 341, 'And He will teach him writing and wisdom and the Torah and the Gospel', NULL, NULL, '4b46fb3f9122d1065dabbe5a4f8084d6510ac664c97a76f8db3f34248ed86e0c'),
  ('en.sahih', 3, 49, 342, 'And [make him] a messenger to the Children of Israel, [who will say], ''Indeed I have come to you with a sign from your Lord in that I design for you from clay [that which is] like the form of a bird, then I breathe into it and it becomes a bird by permission of Allah. And I cure the blind and the leper, and I give life to the dead - by permission of Allah. And I inform you of what you eat and what you store in your houses. Indeed in that is a sign for you, if you are believers.', NULL, NULL, 'be170d7d488af55626175066aa5674c823894aa5989ce98e7fe4a9c2204f5778'),
  ('en.sahih', 3, 50, 343, 'And [I have come] confirming what was before me of the Torah and to make lawful for you some of what was forbidden to you. And I have come to you with a sign from your Lord, so fear Allah and obey me.', NULL, NULL, 'eb7d4196fadad83b17226e9e23b820e417ba83b616ee6ff564e1d98e1eee8be4'),
  ('en.sahih', 3, 51, 344, 'Indeed, Allah is my Lord and your Lord, so worship Him. That is the straight path."', NULL, NULL, 'ce0776c0ab5e08c2c40fce2b903d03a2f92687a02dab441ab54cba4ce453a45a'),
  ('en.sahih', 3, 52, 345, 'But when Jesus felt [persistence in] disbelief from them, he said, "Who are my supporters for [the cause of] Allah?" The disciples said, "We are supporters for Allah. We have believed in Allah and testify that we are Muslims [submitting to Him].', NULL, NULL, '23dc3b0fc711c279a18744eb3c89c5faef917138114b91f7d89f9e02cb1a5ae7'),
  ('en.sahih', 3, 53, 346, 'Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth]."', NULL, NULL, 'e0b50883ad234dfa01cab205b1d851bcb67727c259643c4ac1a651894e21e5af'),
  ('en.sahih', 3, 54, 347, 'And the disbelievers planned, but Allah planned. And Allah is the best of planners.', NULL, NULL, '9945f1880b40c2c0a8d3a4fa38a5f02fe635ea9cd0fbca0408c53fc1cecb45d1'),
  ('en.sahih', 3, 55, 348, '[Mention] when Allah said, "O Jesus, indeed I will take you and raise you to Myself and purify you from those who disbelieve and make those who follow you [in submission to Allah alone] superior to those who disbelieve until the Day of Resurrection. Then to Me is your return, and I will judge between you concerning that in which you used to differ.', NULL, NULL, 'd90f59f7e42cee5465639a13f8417cd0f0d0a59123379a4bd669b842b028d75e'),
  ('en.sahih', 3, 56, 349, 'And as for those who disbelieved, I will punish them with a severe punishment in this world and the Hereafter, and they will have no helpers."', NULL, NULL, '2ce16a2940dfc9e2f906b09c884e3a2f2dcf043b9a84c943e4527864755eac99'),
  ('en.sahih', 3, 57, 350, 'But as for those who believed and did righteous deeds, He will give them in full their rewards, and Allah does not like the wrongdoers.', NULL, NULL, 'cf975ac0601c96fd2659adf1ef0a3c2d97966b14316ab61209e3c86a743de6b4'),
  ('en.sahih', 3, 58, 351, 'This is what We recite to you, [O Muhammad], of [Our] verses and the precise [and wise] message.', NULL, NULL, '9acc00ef86c82e8f364b1400c24022626cef370dc4dcda0f475640933db4fb8b'),
  ('en.sahih', 3, 59, 352, 'Indeed, the example of Jesus to Allah is like that of Adam. He created Him from dust; then He said to him, "Be," and he was.', NULL, NULL, '6cdee99cf19e1ab36bbcf4af067805941088f93fc1e51c49a31b8808bb991c62'),
  ('en.sahih', 3, 60, 353, 'The truth is from your Lord, so do not be among the doubters.', NULL, NULL, 'e9a51be31465c801a91613a2f69a21c55fcaf83bcdb570e85504be85c0030e65'),
  ('en.sahih', 3, 61, 354, 'Then whoever argues with you about it after [this] knowledge has come to you - say, "Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then supplicate earnestly [together] and invoke the curse of Allah upon the liars [among us]."', NULL, NULL, '7bad4f67106769079e856edbef7e6b7fdb64b1d70dcb5d8e4d57858ff8bd4e9d'),
  ('en.sahih', 3, 62, 355, 'Indeed, this is the true narration. And there is no deity except Allah. And indeed, Allah is the Exalted in Might, the Wise.', NULL, NULL, 'a132894aec4cdad3cadf8852d0ea3ed94ae437d18621cfda892593665c78e5f9'),
  ('en.sahih', 3, 63, 356, 'But if they turn away, then indeed - Allah is Knowing of the corrupters.', NULL, NULL, '5034ac2cc6ffceaf16a8150363b8e9a2265e9e6edf84ba5dcb7aef1269e57e18'),
  ('en.sahih', 3, 64, 357, 'Say, "O People of the Scripture, come to a word that is equitable between us and you - that we will not worship except Allah and not associate anything with Him and not take one another as lords instead of Allah." But if they turn away, then say, "Bear witness that we are Muslims [submitting to Him]."', NULL, NULL, 'cd315025ca51e209c6186e2a5ed87cf2876346e8b1d0a3c8c41e71734c1826e5'),
  ('en.sahih', 3, 65, 358, 'O People of the Scripture, why do you argue about Abraham while the Torah and the Gospel were not revealed until after him? Then will you not reason?', NULL, NULL, '207d84a1426dfe535b5bd682b62b23d3084c89e62c7cad007723707e855e8c57'),
  ('en.sahih', 3, 66, 359, 'Here you are - those who have argued about that of which you have [some] knowledge, but why do you argue about that of which you have no knowledge? And Allah knows, while you know not.', NULL, NULL, 'e0e864ae47f03642fabd04f73108a9a5821e9fee6a8005ef8f4d36e76f7b49a0'),
  ('en.sahih', 3, 67, 360, 'Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allah]. And he was not of the polytheists.', NULL, NULL, 'b60c5a4a718856baae3a73f3385a21984e8ab5a32d641e6505c0d94e29532a0f'),
  ('en.sahih', 3, 68, 361, 'Indeed, the most worthy of Abraham among the people are those who followed him [in submission to Allah] and this prophet, and those who believe [in his message]. And Allah is the ally of the believers.', NULL, NULL, '5f8e2876561fd7be3ddb6aeda11492ad1b588e0ae2188d2771e0f780860a3207'),
  ('en.sahih', 3, 69, 362, 'A faction of the people of the Scripture wish they could mislead you. But they do not mislead except themselves, and they perceive [it] not.', NULL, NULL, 'df96713800c820d2003c08d6c21dcab70b9c3ba97a57fb754ebb313b44c0977e'),
  ('en.sahih', 3, 70, 363, 'O People of the Scripture, why do you disbelieve in the verses of Allah while you witness [to their truth]?', NULL, NULL, '8daff361c0bedf6061ad067aa1a7847d196bb2909ac873fff7f701d10377dc6a'),
  ('en.sahih', 3, 71, 364, 'O People of the Scripture, why do you confuse the truth with falsehood and conceal the truth while you know [it]?', NULL, NULL, 'e548b756e3081a70a2a9106517eb9fa9d6a862f9ddbbb85541df4f3e886d0735'),
  ('en.sahih', 3, 72, 365, 'And a faction of the People of the Scripture say [to each other], "Believe in that which was revealed to the believers at the beginning of the day and reject it at its end that perhaps they will abandon their religion,', NULL, NULL, '222afc86e50cf4d7b5e488653321f0c61e6d8b17f7fac9e319fb976fbe32daf0'),
  ('en.sahih', 3, 73, 366, 'And do not trust except those who follow your religion." Say, "Indeed, the [true] guidance is the guidance of Allah. [Do you fear] lest someone be given [knowledge] like you were given or that they would [thereby] argue with you before your Lord?" Say, "Indeed, [all] bounty is in the hand of Allah - He grants it to whom He wills. And Allah is all-Encompassing and Wise."', NULL, NULL, 'ba954ad5adbd3bd81cb4ad8c9c4473acd74b9d36ef4cae1823b18ae324f71492'),
  ('en.sahih', 3, 74, 367, 'He selects for His mercy whom He wills. And Allah is the possessor of great bounty.', NULL, NULL, '06bdf66f13d807b836b304f9dfccba4aeed943c78f9d57d25f2af5ee7fdc8970'),
  ('en.sahih', 3, 75, 368, 'And among the People of the Scripture is he who, if you entrust him with a great amount [of wealth], he will return it to you. And among them is he who, if you entrust him with a [single] silver coin, he will not return it to you unless you are constantly standing over him [demanding it]. That is because they say, "There is no blame upon us concerning the unlearned." And they speak untruth about Allah while they know [it].', NULL, NULL, '21f161c3470848cacc76873f631dbb288a9480a68b360ef9dfa5f30bf9b24eb7'),
  ('en.sahih', 3, 76, 369, 'But yes, whoever fulfills his commitment and fears Allah - then indeed, Allah loves those who fear Him.', NULL, NULL, '75a92e591dfb2192afcece6e7241363c00468259719032125714ea6f318172d2'),
  ('en.sahih', 3, 77, 370, 'Indeed, those who exchange the covenant of Allah and their [own] oaths for a small price will have no share in the Hereafter, and Allah will not speak to them or look at them on the Day of Resurrection, nor will He purify them; and they will have a painful punishment.', NULL, NULL, '08ce03793491bbb2470cedb95890549b29b36ecf3e9ec1d87db0efc60dae27d3'),
  ('en.sahih', 3, 78, 371, 'And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, "This is from Allah," but it is not from Allah. And they speak untruth about Allah while they know.', NULL, NULL, '1c56b1526457bae149553fae4f244909081b958bc74e55272f933ddec111a136'),
  ('en.sahih', 3, 79, 372, 'It is not for a human [prophet] that Allah should give him the Scripture and authority and prophethood and then he would say to the people, "Be servants to me rather than Allah," but [instead, he would say], "Be pious scholars of the Lord because of what you have taught of the Scripture and because of what you have studied."', NULL, NULL, '57f5b6e8234850b2c79e0fde6631997429c257122eb77e40a21eadfd9a57fe21'),
  ('en.sahih', 3, 80, 373, 'Nor could he order you to take the angels and prophets as lords. Would he order you to disbelief after you had been Muslims?', NULL, NULL, '3a16bbd6d826a838c6ff8b2cb4793a4abdcda632d3e6cb97c679914444a841a9'),
  ('en.sahih', 3, 81, 374, 'And [recall, O People of the Scripture], when Allah took the covenant of the prophets, [saying], "Whatever I give you of the Scripture and wisdom and then there comes to you a messenger confirming what is with you, you [must] believe in him and support him." [Allah] said, "Have you acknowledged and taken upon that My commitment?" They said, "We have acknowledged it." He said, "Then bear witness, and I am with you among the witnesses."', NULL, NULL, 'b76738bbfd7439520e1216146c0ae0d627c5eea44afbceb54b536430387dc260'),
  ('en.sahih', 3, 82, 375, 'And whoever turned away after that - they were the defiantly disobedient.', NULL, NULL, 'f65ebe1a2ebfd4fb4bb03a02697013bd479386295acb33874e90d289b6e2425c'),
  ('en.sahih', 3, 83, 376, 'So is it other than the religion of Allah they desire, while to Him have submitted [all] those within the heavens and earth, willingly or by compulsion, and to Him they will be returned?', NULL, NULL, 'f3c6765939a31d99a1974c391d648e9de141ea02afb4802c1ec799bd3e18578a'),
  ('en.sahih', 3, 84, 377, 'Say, "We have believed in Allah and in what was revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and the Descendants, and in what was given to Moses and Jesus and to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [submitting] to Him."', NULL, NULL, '7a2e8639f955596bee8b5c2175663a079de72276ddae3151048f52cfb9a10601'),
  ('en.sahih', 3, 85, 378, 'And whoever desires other than Islam as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers.', NULL, NULL, '345addf253c3b06fa066b8c6865e840a7f7db32d70801e6fe770c68d189462d6'),
  ('en.sahih', 3, 86, 379, 'How shall Allah guide a people who disbelieved after their belief and had witnessed that the Messenger is true and clear signs had come to them? And Allah does not guide the wrongdoing people.', NULL, NULL, 'bac7fda26d83a1918885b717dcb4309d4793f669e83aacc24aee5f7b88436316'),
  ('en.sahih', 3, 87, 380, 'Those - their recompense will be that upon them is the curse of Allah and the angels and the people, all together,', NULL, NULL, '74b1c198d94bb86edaee64a64e1785b716e94b6283c61c4fa0796288c1ec9a94'),
  ('en.sahih', 3, 88, 381, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.', NULL, NULL, '2e98cddf4c5736aa70835b310e7e5a10290d3801f92a9d7bba49e20d007770f9'),
  ('en.sahih', 3, 89, 382, 'Except for those who repent after that and correct themselves. For indeed, Allah is Forgiving and Merciful.', NULL, NULL, '18ed3c884cf1206a1c7c8519e51dec818ddd0e494a35e20ba5f97482aca730e9'),
  ('en.sahih', 3, 90, 383, 'Indeed, those who reject the message after their belief and then increase in disbelief - never will their [claimed] repentance be accepted, and they are the ones astray.', NULL, NULL, 'c3386c4dd7485c5e88f38c4109a6c870f8c0c9f8221ad003a5998ddc66a45665'),
  ('en.sahih', 3, 91, 384, 'Indeed, those who disbelieve and die while they are disbelievers - never would the [whole] capacity of the earth in gold be accepted from one of them if he would [seek to] ransom himself with it. For those there will be a painful punishment, and they will have no helpers.', NULL, NULL, '888c5e038244ff473474add89569bba45262b683aa9a25996f8f2ec9508ab93f'),
  ('en.sahih', 3, 92, 385, 'Never will you attain the good [reward] until you spend [in the way of Allah] from that which you love. And whatever you spend - indeed, Allah is Knowing of it.', NULL, NULL, '11d9f4e2ed89d495c9f218e8b143ed8b382b303136709128175d79a807dc6c06'),
  ('en.sahih', 3, 93, 386, 'All food was lawful to the Children of Israel except what Israel had made unlawful to himself before the Torah was revealed. Say, [O Muhammad], "So bring the Torah and recite it, if you should be truthful."', NULL, NULL, '04849d943177f574920cb6bdde00a4ec4b9ee44accbeacfad83be22ad79e6c5b'),
  ('en.sahih', 3, 94, 387, 'And whoever invents about Allah untruth after that - then those are [truly] the wrongdoers.', NULL, NULL, 'f9d502e7bf4e86faa15dbe52919321f652afcc1b1e0ffd434e1bc97bc984872b'),
  ('en.sahih', 3, 95, 388, 'Say, "Allah has told the truth. So follow the religion of Abraham, inclining toward truth; and he was not of the polytheists."', NULL, NULL, 'b5f754ce8a9c17c2147f9150a541b392eccbbd38ad70d3e6a29f8aad11c8f31c'),
  ('en.sahih', 3, 96, 389, 'Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds.', NULL, NULL, '0d7d64f1cacb3e3def2a9ac122e49d416729837c79eb99d61dedf1e0c079a682'),
  ('en.sahih', 3, 97, 390, 'In it are clear signs [such as] the standing place of Abraham. And whoever enters it shall be safe. And [due] to Allah from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves - then indeed, Allah is free from need of the worlds.', NULL, NULL, '6b55af0162c60eaa64664b05169be897bb94540f6d1c5db63787ea6246179a0f'),
  ('en.sahih', 3, 98, 391, 'Say, "O People of the Scripture, why do you disbelieve in the verses of Allah while Allah is Witness over what you do?"', NULL, NULL, '5dc3d7c3a00e8bafcc8384be6f50f14991d2eea920f46f5e261c3a4544135b5b'),
  ('en.sahih', 3, 99, 392, 'Say, "O People of the Scripture, why do you avert from the way of Allah those who believe, seeking to make it [seem] deviant, while you are witnesses [to the truth]? And Allah is not unaware of what you do."', NULL, NULL, '198cedf7d80579b1ae4e23f4d7692e3187784c8fdd6d633c91a8b463fee20818'),
  ('en.sahih', 3, 100, 393, 'O you who have believed, if you obey a party of those who were given the Scripture, they would turn you back, after your belief, [to being] unbelievers.', NULL, NULL, '4ca26c9eabf1e50448919101700040b894f890503bfbe9534471175317cd070f'),
  ('en.sahih', 3, 101, 394, 'And how could you disbelieve while to you are being recited the verses of Allah and among you is His Messenger? And whoever holds firmly to Allah has [indeed] been guided to a straight path.', NULL, NULL, 'ceb2dabfaca810e055bc1dc892b39f4b44e0564122763ed3b284dbbd2efac36d'),
  ('en.sahih', 3, 102, 395, 'O you who have believed, fear Allah as He should be feared and do not die except as Muslims [in submission to Him].', NULL, NULL, '6214447c49ace191c22d14c03206f8a22d752cf92a40f38c1d995631ddbe692b'),
  ('en.sahih', 3, 103, 396, 'And hold firmly to the rope of Allah all together and do not become divided. And remember the favor of Allah upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allah make clear to you His verses that you may be guided.', NULL, NULL, 'f53133723d096a46fc562240e3c75f9295054603c0c8bee08194412a8ee6ec02'),
  ('en.sahih', 3, 104, 397, 'And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful.', NULL, NULL, 'e0fe9d3ebc5f09df0110603f69dfe3de4a1a589456c82c4c6ab5dca32f995c43'),
  ('en.sahih', 3, 105, 398, 'And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment.', NULL, NULL, '4d151b3f49515506004466410ea5540bd177c1094ec9cbc99fb0c92aabdbc688'),
  ('en.sahih', 3, 106, 399, 'On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], "Did you disbelieve after your belief? Then taste the punishment for what you used to reject."', NULL, NULL, '05445e80c993d7787ad8148c5fcc7cdd9bc8ba7538320f3eb6ce5c3cca2f5d54'),
  ('en.sahih', 3, 107, 400, 'But as for those whose faces will turn white, [they will be] within the mercy of Allah. They will abide therein eternally.', NULL, NULL, 'bcf9bee7796b146fd701bce6a9ab4acc08753dc6c3a180996ce5456e2c32c5aa')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 3, 108, 401, 'These are the verses of Allah. We recite them to you, [O Muhammad], in truth; and Allah wants no injustice to the worlds.', NULL, NULL, 'de723218160e35476fe1be5a26cd6bdc42f5b32e28873cb0720826df2ae67af8'),
  ('en.sahih', 3, 109, 402, 'To Allah belongs whatever is in the heavens and whatever is on the earth. And to Allah will [all] matters be returned.', NULL, NULL, 'fe92512a06da022f498b57a44dd732a48eaf491a63395f3ce35b5552ec97a8cf'),
  ('en.sahih', 3, 110, 403, 'You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allah. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient.', NULL, NULL, 'e47e21b8d0d82c5b26757b0263fe0a9303077655b5cf6c4e5752138c1944655d'),
  ('en.sahih', 3, 111, 404, 'They will not harm you except for [some] annoyance. And if they fight you, they will show you their backs; then they will not be aided.', NULL, NULL, '887f3d468b6850bc8c8cd2d4d949efc83d00c6dd5d19d33ed9f65036c3e35d8d'),
  ('en.sahih', 3, 112, 405, 'They have been put under humiliation [by Allah] wherever they are overtaken, except for a covenant from Allah and a rope from the Muslims. And they have drawn upon themselves anger from Allah and have been put under destitution. That is because they disbelieved in the verses of Allah and killed the prophets without right. That is because they disobeyed and [habitually] transgressed.', NULL, NULL, 'faec54b5f2eae2cd2f5237ae37a0452a50534ed08c5eb2f89cf47b60769c2054'),
  ('en.sahih', 3, 113, 406, 'They are not [all] the same; among the People of the Scripture is a community standing [in obedience], reciting the verses of Allah during periods of the night and prostrating [in prayer].', NULL, NULL, 'a2793d0fa4f36c431ea1e65e8bfb8705432f175a731e291ceb3e04547b2a1256'),
  ('en.sahih', 3, 114, 407, 'They believe in Allah and the Last Day, and they enjoin what is right and forbid what is wrong and hasten to good deeds. And those are among the righteous.', NULL, NULL, '53a30f988e45d88eeeb64850285865772fb5ab9c3906e1de11e643b91f42c451'),
  ('en.sahih', 3, 115, 408, 'And whatever good they do - never will it be removed from them. And Allah is Knowing of the righteous.', NULL, NULL, '509f22e144ad29b6554dce23c287de26b59b1abfb45efc96568c63f279d90212'),
  ('en.sahih', 3, 116, 409, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all, and those are the companions of the Fire; they will abide therein eternally.', NULL, NULL, '695f161e7edd50f1661541272d75bc4f81d0745e7861b0b04ab682655c05039a'),
  ('en.sahih', 3, 117, 410, 'The example of what they spend in this worldly life is like that of a wind containing frost which strikes the harvest of a people who have wronged themselves and destroys it. And Allah has not wronged them, but they wrong themselves.', NULL, NULL, '36f8383683543648cc6973627f0265899b7aa48a408188de76589dd1e598eeeb'),
  ('en.sahih', 3, 118, 411, 'O you who have believed, do not take as intimates those other than yourselves, for they will not spare you [any] ruin. They wish you would have hardship. Hatred has already appeared from their mouths, and what their breasts conceal is greater. We have certainly made clear to you the signs, if you will use reason.', NULL, NULL, '8afa410491e347288f1aeee26465e14a254a4bba840ea12e1d0402e517bb2d97'),
  ('en.sahih', 3, 119, 412, 'Here you are loving them but they are not loving you, while you believe in the Scripture - all of it. And when they meet you, they say, "We believe." But when they are alone, they bite their fingertips at you in rage. Say, "Die in your rage. Indeed, Allah is Knowing of that within the breasts."', NULL, NULL, 'cf6b454854c435707312f1414db7aa9836cbc6f0f9ab9a4aeeb76ae3c431627a'),
  ('en.sahih', 3, 120, 413, 'If good touches you, it distresses them; but if harm strikes you, they rejoice at it. And if you are patient and fear Allah, their plot will not harm you at all. Indeed, Allah is encompassing of what they do.', NULL, NULL, '7ae90d33cef4249dd903223d5c01118fda5850d98db83fca742073825ed4a2f2'),
  ('en.sahih', 3, 121, 414, 'And [remember] when you, [O Muhammad], left your family in the morning to post the believers at their stations for the battle [of Uhud] - and Allah is Hearing and Knowing -', NULL, NULL, '36ad8f3172d3c1040a49720abb7857d0919c768d373a7a7061c9f85a5e72ecca'),
  ('en.sahih', 3, 122, 415, 'When two parties among you were about to lose courage, but Allah was their ally; and upon Allah the believers should rely.', NULL, NULL, '52592f608a0aba9add3fe11ffa5edcad67a68490e75f0143c8df81671c24c2c5'),
  ('en.sahih', 3, 123, 416, 'And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful.', NULL, NULL, '868b13064641c34c31b7e076c54982dd7276c822c9d4a6463cfe5a77cc516ccd'),
  ('en.sahih', 3, 124, 417, '[Remember] when you said to the believers, "Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down?', NULL, NULL, '66f5640f466c2768b672f240310b2ee6e7300a8c8ff6cd42270bdc267b8a12a4'),
  ('en.sahih', 3, 125, 418, 'Yes, if you remain patient and conscious of Allah and the enemy come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction]', NULL, NULL, 'c3990e7b43dcf9c634c1734cc35f9a2d4a197bd4e334599ede5f5cdf2d99d9ed'),
  ('en.sahih', 3, 126, 419, 'And Allah made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allah, the Exalted in Might, the Wise -', NULL, NULL, 'e93e642e60ffd895e9665d405b4987ca4ac91f5e512aca92045dacffec4de39f'),
  ('en.sahih', 3, 127, 420, 'That He might cut down a section of the disbelievers or suppress them so that they turn back disappointed.', NULL, NULL, '7cdb3fb6c9ed70e96c73882d101c89323a9abc1ce77f1ab9991ffaa12ee8f1c3'),
  ('en.sahih', 3, 128, 421, 'Not for you, [O Muhammad, but for Allah], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers.', NULL, NULL, '2fcc1848290231724628b89deb88cb368f07e38c2e860e5c5a86fe66d719bcee'),
  ('en.sahih', 3, 129, 422, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. He forgives whom He wills and punishes whom He wills. And Allah is Forgiving and Merciful.', NULL, NULL, '80d7db35e679512eee03df633c894757d0ade4febd8cf6dfd101a6bfdcf25ece'),
  ('en.sahih', 3, 130, 423, 'O you who have believed, do not consume usury, doubled and multiplied, but fear Allah that you may be successful.', NULL, NULL, '7aa99fbffdeafe8b884b49c48b40b827783dc36ce1cdc4efccfb278d423bcbb1'),
  ('en.sahih', 3, 131, 424, 'And fear the Fire, which has been prepared for the disbelievers.', NULL, NULL, '521cf52c9496c86befeef7f1e645c8950cf7839d074694ccc23267afff2c5250'),
  ('en.sahih', 3, 132, 425, 'And obey Allah and the Messenger that you may obtain mercy.', NULL, NULL, '1fc5bfda5219b69d2c5f804e4b7bfb9640b8564a2379a1fd0b1b2cbcda028083'),
  ('en.sahih', 3, 133, 426, 'And hasten to forgiveness from your Lord and a garden as wide as the heavens and earth, prepared for the righteous', NULL, NULL, 'a0162962117d583a175525e3a00c9c2de7ab6ab79fb1dde2c26f57a69e150965'),
  ('en.sahih', 3, 134, 427, 'Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good;', NULL, NULL, '3fc8f801704c0dc4666b4766bc54f399e1bc8851013007b4c6d98e060dc8b6fc'),
  ('en.sahih', 3, 135, 428, 'And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah? - and [who] do not persist in what they have done while they know.', NULL, NULL, 'a6b5aed0ade94a6ebd4ee07d02a559818582eeddb80aad46603583c4b8de4335'),
  ('en.sahih', 3, 136, 429, 'Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers.', NULL, NULL, '17ac43495cf8d150527913bd55c65b8cb49332172f53ef8b035ce509fefa3823'),
  ('en.sahih', 3, 137, 430, 'Similar situations [as yours] have passed on before you, so proceed throughout the earth and observe how was the end of those who denied.', NULL, NULL, '22c6a4e1e49c51f4b7bb727d554fb1aed772bdd081a244d6d2ca859bfc4e9038'),
  ('en.sahih', 3, 138, 431, 'This [Qur''an] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allah.', NULL, NULL, 'deb304ec2920bcd3237f19b3fb7eb381bb27d29496f3dd1c6a3d475612074412'),
  ('en.sahih', 3, 139, 432, 'So do not weaken and do not grieve, and you will be superior if you are [true] believers.', NULL, NULL, 'd94570519e57807b24edb9f6469c6523b6f0a4b60e2d469c8facee7a8d9fbde4'),
  ('en.sahih', 3, 140, 433, 'If a wound should touch you - there has already touched the [opposing] people a wound similar to it. And these days [of varying conditions] We alternate among the people so that Allah may make evident those who believe and [may] take to Himself from among you martyrs - and Allah does not like the wrongdoers -', NULL, NULL, '39f8038adae4ea037ffceb8671f81bd13f8a85469ca6d501ba54d80c53b65391'),
  ('en.sahih', 3, 141, 434, 'And that Allah may purify the believers [through trials] and destroy the disbelievers.', NULL, NULL, 'acd4307a8f90ac5fe67af9eceb732c526d231721bf0ac205c5f496ca70166146'),
  ('en.sahih', 3, 142, 435, 'Or do you think that you will enter Paradise while Allah has not yet made evident those of you who fight in His cause and made evident those who are steadfast?', NULL, NULL, '6dd1143bb7a424988c3031443a15b81296c4df83bef69eff0540eab82186d1f6'),
  ('en.sahih', 3, 143, 436, 'And you had certainly wished for martyrdom before you encountered it, and you have [now] seen it [before you] while you were looking on.', NULL, NULL, 'e19afefeb0dd9c6b9058d0632fd6c510cabb1e9e35be76da24a1f854e583c729'),
  ('en.sahih', 3, 144, 437, 'Muhammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allah at all; but Allah will reward the grateful.', NULL, NULL, '6cc415c7a3d10c18f7d7833b605807c73375d73750fd27a67ab4e4dfecf8c31f'),
  ('en.sahih', 3, 145, 438, 'And it is not [possible] for one to die except by permission of Allah at a decree determined. And whoever desires the reward of this world - We will give him thereof; and whoever desires the reward of the Hereafter - We will give him thereof. And we will reward the grateful.', NULL, NULL, '99150e85e84381cb01d025fd0bd02e47b85b19efb3ef64297339309c9e677ce4'),
  ('en.sahih', 3, 146, 439, 'And how many a prophet [fought and] with him fought many religious scholars. But they never lost assurance due to what afflicted them in the cause of Allah, nor did they weaken or submit. And Allah loves the steadfast.', NULL, NULL, '0bcf4b3d6832c9b615fd78e6a615a855864f7623033da4655099b9fe85b1b63f'),
  ('en.sahih', 3, 147, 440, 'And their words were not but that they said, "Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people."', NULL, NULL, 'aba953f2127e8bfc6002e7456bbb4ad09d0cd14baafb3f24b7e8017aaaf0579f'),
  ('en.sahih', 3, 148, 441, 'So Allah gave them the reward of this world and the good reward of the Hereafter. And Allah loves the doers of good.', NULL, NULL, '696dc1a121010edee861cabda641b3bff072b96e256457ed70e21a27b33298ac'),
  ('en.sahih', 3, 149, 442, 'O you who have believed, if you obey those who disbelieve, they will turn you back on your heels, and you will [then] become losers.', NULL, NULL, '403093670f3bc1a4fa0e1d53d3406bf6ea6235d50698c8edeef433a91f27903e'),
  ('en.sahih', 3, 150, 443, 'But Allah is your protector, and He is the best of helpers.', NULL, NULL, '8c1eb57dcdb8755acb716004828a53cdad97163ab33aa71c9fc527a758f3b3e9'),
  ('en.sahih', 3, 151, 444, 'We will cast terror into the hearts of those who disbelieve for what they have associated with Allah of which He had not sent down [any] authority. And their refuge will be the Fire, and wretched is the residence of the wrongdoers.', NULL, NULL, '8c6d44e3edbc5c973997a655c0acc3f5c22a4e6aef708817d629b49dd0db5136'),
  ('en.sahih', 3, 152, 445, 'And Allah had certainly fulfilled His promise to you when you were killing the enemy by His permission until [the time] when you lost courage and fell to disputing about the order [given by the Prophet] and disobeyed after He had shown you that which you love. Among you are some who desire this world, and among you are some who desire the Hereafter. Then he turned you back from them [defeated] that He might test you. And He has already forgiven you, and Allah is the possessor of bounty for the believers.', NULL, NULL, '73f7589fe5e15d9c31434e3f7e3015aa60f920bab44d7407d12b6caf1d387202'),
  ('en.sahih', 3, 153, 446, '[Remember] when you [fled and] climbed [the mountain] without looking aside at anyone while the Messenger was calling you from behind. So Allah repaid you with distress upon distress so you would not grieve for that which had escaped you [of victory and spoils of war] or [for] that which had befallen you [of injury and death]. And Allah is [fully] Acquainted with what you do.', NULL, NULL, '4bef942907d042465e038b929a074cf754e8a3e1afb9f6b646b5687b0c20f725'),
  ('en.sahih', 3, 154, 447, 'Then after distress, He sent down upon you security [in the form of] drowsiness, overcoming a faction of you, while another faction worried about themselves, thinking of Allah other than the truth - the thought of ignorance, saying, "Is there anything for us [to have done] in this matter?" Say, "Indeed, the matter belongs completely to Allah." They conceal within themselves what they will not reveal to you. They say, "If there was anything we could have done in the matter, some of us would not have been killed right here." Say, "Even if you had been inside your houses, those decreed to be killed would have come out to their death beds." [It was] so that Allah might test what is in your breasts and purify what is in your hearts. And Allah is Knowing of that within the breasts.', NULL, NULL, '4b96fdc777bd6a03dbbef085075d5ef631d411c8a5a18a739033d9b2b4c26d30'),
  ('en.sahih', 3, 155, 448, 'Indeed, those of you who turned back on the day the two armies met, it was Satan who caused them to slip because of some [blame] they had earned. But Allah has already forgiven them. Indeed, Allah is Forgiving and Forbearing.', NULL, NULL, '3b2f506be5b090c68a1795ca65507201705036b8e4200a104730a95fd142023e'),
  ('en.sahih', 3, 156, 449, 'O you who have believed, do not be like those who disbelieved and said about their brothers when they traveled through the land or went out to fight, "If they had been with us, they would not have died or have been killed," so Allah makes that [misconception] a regret within their hearts. And it is Allah who gives life and causes death, and Allah is Seeing of what you do.', NULL, NULL, 'c2001f4f60e9fdab15cab48e1a95f4711a44fa20600ef661bd600472848d71e3'),
  ('en.sahih', 3, 157, 450, 'And if you are killed in the cause of Allah or die - then forgiveness from Allah and mercy are better than whatever they accumulate [in this world].', NULL, NULL, '101e0f099946abf3da671e1d855bd2ce1673b822055de480da514f68b1cf502f'),
  ('en.sahih', 3, 158, 451, 'And whether you die or are killed, unto Allah you will be gathered.', NULL, NULL, '2a8c63eca2738ad5715be07fd5afc35a84ab5592aa2bb11a26ea821b5743edb7'),
  ('en.sahih', 3, 159, 452, 'So by mercy from Allah, [O Muhammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allah. Indeed, Allah loves those who rely [upon Him].', NULL, NULL, '8d1fb8c1cc6baa64e41cab898de6e55d111fb5e7ce3f0fc8fe59b0c18136376e'),
  ('en.sahih', 3, 160, 453, 'If Allah should aid you, no one can overcome you; but if He should forsake you, who is there that can aid you after Him? And upon Allah let the believers rely.', NULL, NULL, '48ed1baf32549d5c45402b35ce489e72873b331a65b4e10bcf63115d5b4d69fa'),
  ('en.sahih', 3, 161, 454, 'It is not [attributable] to any prophet that he would act unfaithfully [in regard to war booty]. And whoever betrays, [taking unlawfully], will come with what he took on the Day of Resurrection. Then will every soul be [fully] compensated for what it earned, and they will not be wronged.', NULL, NULL, '4877396b18cc099d3b57e4dad49b7d94b881fc9db3837782b34ebc38b2444e8e'),
  ('en.sahih', 3, 162, 455, 'So is one who pursues the pleasure of Allah like one who brings upon himself the anger of Allah and whose refuge is Hell? And wretched is the destination.', NULL, NULL, '6b274c0d380876ef7c5bd3ad09fabd2a28c811cbf3e9f74a93bd19bf23ed324e'),
  ('en.sahih', 3, 163, 456, 'They are [varying] degrees in the sight of Allah, and Allah is Seeing of whatever they do.', NULL, NULL, 'f2c04cd5cf6fd562228eec8f9402a9b49daba371f7b370605ee35ad22a29cdff'),
  ('en.sahih', 3, 164, 457, 'Certainly did Allah confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book and wisdom, although they had been before in manifest error.', NULL, NULL, '8e4d878e67497769ffeeaf760c95d6ca8761a2c2aaa6bf12e3c4a05df61c5255'),
  ('en.sahih', 3, 165, 458, 'Why [is it that] when a [single] disaster struck you [on the day of Uhud], although you had struck [the enemy in the battle of Badr] with one twice as great, you said, "From where is this?" Say, "It is from yourselves." Indeed, Allah is over all things competent.', NULL, NULL, '9f7fc83966e4f7d70d213682ca69fb2ad9cea8b768cd54247de87fe09d95f84a'),
  ('en.sahih', 3, 166, 459, 'And what struck you on the day the two armies met was by permission of Allah that He might make evident the [true] believers.', NULL, NULL, 'f1147047bc8251b7e384e57c53c8202225dfcaf7272a78b8530d2cdd8d76d229'),
  ('en.sahih', 3, 167, 460, 'And that He might make evident those who are hypocrites. For it was said to them, "Come, fight in the way of Allah or [at least] defend." They said, "If we had known [there would be] fighting, we would have followed you." They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allah is most Knowing of what they conceal -', NULL, NULL, '3d8e53d7353ea37186b6995238594d250eb4f3950891d699e16221fdc3b5fe35'),
  ('en.sahih', 3, 168, 461, 'Those who said about their brothers while sitting [at home], "If they had obeyed us, they would not have been killed." Say, "Then prevent death from yourselves, if you should be truthful."', NULL, NULL, 'e2f289f3d1777b0a9ce91d451ea8bf24795ebc132ca96dc70cecbc0fa204d3db'),
  ('en.sahih', 3, 169, 462, 'And never think of those who have been killed in the cause of Allah as dead. Rather, they are alive with their Lord, receiving provision,', NULL, NULL, '26d7e6406806f5159909d2f436bbdb1e5814cff6aff025c32caaa5d1dfaa8a7f'),
  ('en.sahih', 3, 170, 463, 'Rejoicing in what Allah has bestowed upon them of His bounty, and they receive good tidings about those [to be martyred] after them who have not yet joined them - that there will be no fear concerning them, nor will they grieve.', NULL, NULL, '160785a8655d50362e15cb4acccaf0e053d41f66b1018e25fd2402721124495d'),
  ('en.sahih', 3, 171, 464, 'They receive good tidings of favor from Allah and bounty and [of the fact] that Allah does not allow the reward of believers to be lost -', NULL, NULL, '7104d3f0315cfca11392f803d02cf2b36f41f7e775780f84b6ab21ca9614637b'),
  ('en.sahih', 3, 172, 465, 'Those [believers] who responded to Allah and the Messenger after injury had struck them. For those who did good among them and feared Allah is a great reward -', NULL, NULL, 'a3db2a68361aa94a11728d74458a1390df72e9b635aabcb1ac060b79c8a8c588'),
  ('en.sahih', 3, 173, 466, 'Those to whom hypocrites said, "Indeed, the people have gathered against you, so fear them." But it [merely] increased them in faith, and they said, "Sufficient for us is Allah, and [He is] the best Disposer of affairs."', NULL, NULL, 'e6697645964d0a40e17c1233e48073da2a8322b13db87362a430dff546655020'),
  ('en.sahih', 3, 174, 467, 'So they returned with favor from Allah and bounty, no harm having touched them. And they pursued the pleasure of Allah, and Allah is the possessor of great bounty.', NULL, NULL, 'f591c55644375f4d473cd9dc8f1418a235ee37fc0eae6592a4ab763dc013e7ac'),
  ('en.sahih', 3, 175, 468, 'That is only Satan who frightens [you] of his supporters. So fear them not, but fear Me, if you are [indeed] believers.', NULL, NULL, 'ee420aeabe753829aade19f15e60acf48b1214d602fc5c9d6e520324e30bc199'),
  ('en.sahih', 3, 176, 469, 'And do not be grieved, [O Muhammad], by those who hasten into disbelief. Indeed, they will never harm Allah at all. Allah intends that He should give them no share in the Hereafter, and for them is a great punishment.', NULL, NULL, 'e7dcff1dbf1d56ebdd6385f4711c3a0fc65a162847faae5bf45f5286a894ea4b'),
  ('en.sahih', 3, 177, 470, 'Indeed, those who purchase disbelief [in exchange] for faith - never will they harm Allah at all, and for them is a painful punishment.', NULL, NULL, '6ef6997659aa05a393eeb6a59bb7794e0d959ce0e0396bd0bc2b2e356bda56cd'),
  ('en.sahih', 3, 178, 471, 'And let not those who disbelieve ever think that [because] We extend their time [of enjoyment] it is better for them. We only extend it for them so that they may increase in sin, and for them is a humiliating punishment.', NULL, NULL, 'b6555996d3fc0fa1c34a7cc9966327f2ec755781dabfbe09037d485f49cb10b3'),
  ('en.sahih', 3, 179, 472, 'Allah would not leave the believers in that [state] you are in [presently] until He separates the evil from the good. Nor would Allah reveal to you the unseen. But [instead], Allah chooses of His messengers whom He wills, so believe in Allah and His messengers. And if you believe and fear Him, then for you is a great reward.', NULL, NULL, '3dcc715d237c8c683a48b07668e81bfe593f2fd138ac5e424de72df80bc1e2ca'),
  ('en.sahih', 3, 180, 473, 'And let not those who [greedily] withhold what Allah has given them of His bounty ever think that it is better for them. Rather, it is worse for them. Their necks will be encircled by what they withheld on the Day of Resurrection. And to Allah belongs the heritage of the heavens and the earth. And Allah, with what you do, is [fully] Acquainted.', NULL, NULL, 'e4e01d45f02247213e5d40822aef568df235bf851adc9841d960c124bfd14232'),
  ('en.sahih', 3, 181, 474, 'Allah has certainly heard the statement of those [Jews] who said, "Indeed, Allah is poor, while we are rich." We will record what they said and their killing of the prophets without right and will say, "Taste the punishment of the Burning Fire.', NULL, NULL, '550bb0de551c7138a9d05a86ebd96143f5f184fbc1a1f9bc81779e0370218a53'),
  ('en.sahih', 3, 182, 475, 'That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."', NULL, NULL, '53fb623eea27ba517827fec1f0f4e3cca922b9b62f4275de643ae02dfe1cabc2'),
  ('en.sahih', 3, 183, 476, '[They are] those who said, "Indeed, Allah has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume." Say, "There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?"', NULL, NULL, 'eb2e5632ed617431ec6ba381c84a0bd459b2deae462df0453fa0918da878e5ba'),
  ('en.sahih', 3, 184, 477, 'Then if they deny you, [O Muhammad] - so were messengers denied before you, who brought clear proofs and written ordinances and the enlightening Scripture.', NULL, NULL, '6e5e666c5ba197b7bf5711c8a859376ae9995bbff41001cb69e52d9f71df8e37'),
  ('en.sahih', 3, 185, 478, 'Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion.', NULL, NULL, '91c2f715c171fbad5c5f45e3d6928196a116c40b556be97e0066ea3798448867'),
  ('en.sahih', 3, 186, 479, 'You will surely be tested in your possessions and in yourselves. And you will surely hear from those who were given the Scripture before you and from those who associate others with Allah much abuse. But if you are patient and fear Allah - indeed, that is of the matters [worthy] of determination.', NULL, NULL, '19c3b746a59780d91d382594e3d161e79bef40a2c406fc8323585cdbe24f0807'),
  ('en.sahih', 3, 187, 480, 'And [mention, O Muhammad], when Allah took a covenant from those who were given the Scripture, [saying], "You must make it clear to the people and not conceal it." But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased.', NULL, NULL, 'd759a84040e2daacf19dcf2699180b608765c716e99ab426abbfd4917fad1df3'),
  ('en.sahih', 3, 188, 481, 'And never think that those who rejoice in what they have perpetrated and like to be praised for what they did not do - never think them [to be] in safety from the punishment, and for them is a painful punishment.', NULL, NULL, 'bcf6e04e0c21fd0f2e96ef529d13fa94a08c21f9c94727e7a68a9f088869e20e'),
  ('en.sahih', 3, 189, 482, 'And to Allah belongs the dominion of the heavens and the earth, and Allah is over all things competent.', NULL, NULL, 'eaeae3769a494df80ec072d69cdaeadb6c39b4ba09e6d112aee25b13d9a046b2'),
  ('en.sahih', 3, 190, 483, 'Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding.', NULL, NULL, '2b7d5bdf399de646a1d16a0f69c4818cd2b88759c5d29a2fb0d9e3675afbf196'),
  ('en.sahih', 3, 191, 484, 'Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], "Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire.', NULL, NULL, '1635c1ac2bb3856b8c81e1c42881d7432367bd2fb37198ea6fdc20fb0d6249a6'),
  ('en.sahih', 3, 192, 485, 'Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.', NULL, NULL, '8ecb8ba2ca882baf9fccfb127f07976e3a877d415e84cc4020c78e00c8f3bb02'),
  ('en.sahih', 3, 193, 486, 'Our Lord, indeed we have heard a caller calling to faith, [saying], ''Believe in your Lord,'' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.', NULL, NULL, '0465f0127b97826d263d3981f4de9ab031fe5d64fcb2ecb8666ff58ddfeeac18'),
  ('en.sahih', 3, 194, 487, 'Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise."', NULL, NULL, '7ce4a0dffaaa8a73c33df0b85b218b32f3b15328223bc7c8356219f93be791a3'),
  ('en.sahih', 3, 195, 488, 'And their Lord responded to them, "Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward."', NULL, NULL, 'ddfc6aacf085c9dc03969760b214411b6e89a5c9e3d0c697da857ee17e7d5957'),
  ('en.sahih', 3, 196, 489, 'Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.', NULL, NULL, 'd4b2544886df2f9ac3df52e95424ed88e451e2e4254bc9d7b1b65e5198b9dcf7'),
  ('en.sahih', 3, 197, 490, '[It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place.', NULL, NULL, '87f28083f9b354408dae4fd63887857c14954081a43e447d847b5a2b3a0f14a3'),
  ('en.sahih', 3, 198, 491, 'But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah. And that which is with Allah is best for the righteous.', NULL, NULL, '6a2e14a3c59c700c7527c0d3e9a07a112c61f83ea0eac8a3ed53651820660b6e'),
  ('en.sahih', 3, 199, 492, 'And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah. They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account.', NULL, NULL, '182309920c1b6b3886f27e854d73185b796a8ac9e59d7d430fbc00c8f0bc097f'),
  ('en.sahih', 3, 200, 493, 'O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful.', NULL, NULL, '9e34a4f39ad1404d568a439c67fee2a905b6cd8222e5b1daa865830c510420e5'),
  ('en.sahih', 4, 1, 494, 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer.', NULL, NULL, '8fe099f7040822c02d1681894a57e0fb2855a64f8b5eb02c3e40766178a906d7'),
  ('en.sahih', 4, 2, 495, 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.', NULL, NULL, 'bbaa268eb2a19958879ca571b100daae1042db00b0725fed139366918bc1e149'),
  ('en.sahih', 4, 3, 496, 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice].', NULL, NULL, 'ba74a356a3ca3badb144d6365d595b3374fad797fd3094d7a7cd700d4472c9b2'),
  ('en.sahih', 4, 4, 497, 'And give the women [upon marriage] their [bridal] gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.', NULL, NULL, '368ffcd65c37870e0d1327207cf50f131269e0e6a93485813c45b6e31fdcc1f0'),
  ('en.sahih', 4, 5, 498, 'And do not give the weak-minded your property, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.', NULL, NULL, '8ef2d1dc63b5c8272f31b0dd60b8d178b14c00639b75fb160bd625dac3f4b724'),
  ('en.sahih', 4, 6, 499, 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain [from taking a fee]; and whoever is poor - let him take according to what is acceptable. Then when you release their property to them, bring witnesses upon them. And sufficient is Allah as Accountant.', NULL, NULL, '9db987ab378060cdcb452342de2a06d74a65c3723f452c9eefecc0e8b2112643'),
  ('en.sahih', 4, 7, 500, 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.', NULL, NULL, 'a67976bed2f5b6cc980a04789a931e47fac98ec774feb57326c240133f294a5c')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 4, 8, 501, 'And when [other] relatives and orphans and the needy are present at the [time of] division, then provide for them [something] out of the estate and speak to them words of appropriate kindness.', NULL, NULL, '52f2d1f67ba64900fd4d0273dda74300111280b21e10646079b6aeaf9dbf511f'),
  ('en.sahih', 4, 9, 502, 'And let those [executors and guardians] fear [injustice] as if they [themselves] had left weak offspring behind and feared for them. So let them fear Allah and speak words of appropriate justice.', NULL, NULL, '50a0111c64a0ed24937e47451f7eb631bfd39702cc81342e708b12ee3beac9e0'),
  ('en.sahih', 4, 10, 503, 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze.', NULL, NULL, 'bf6c3f09b2e0b8a8bd3057f67d47d0a9fdbe4d858b01f123c2f55e0e8abe0196'),
  ('en.sahih', 4, 11, 504, 'Allah instructs you concerning your children: for the male, what is equal to the share of two females. But if there are [only] daughters, two or more, for them is two thirds of one''s estate. And if there is only one, for her is half. And for one''s parents, to each one of them is a sixth of his estate if he left children. But if he had no children and the parents [alone] inherit from him, then for his mother is one third. And if he had brothers [or sisters], for his mother is a sixth, after any bequest he [may have] made or debt. Your parents or your children - you know not which of them are nearest to you in benefit. [These shares are] an obligation [imposed] by Allah. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, '7aec24461c21c560406c63ddfb252025f4154184a0c553fcf6374388165e608f'),
  ('en.sahih', 4, 12, 505, 'And for you is half of what your wives leave if they have no child. But if they have a child, for you is one fourth of what they leave, after any bequest they [may have] made or debt. And for the wives is one fourth if you leave no child. But if you leave a child, then for them is an eighth of what you leave, after any bequest you [may have] made or debt. And if a man or woman leaves neither ascendants nor descendants but has a brother or a sister, then for each one of them is a sixth. But if they are more than two, they share a third, after any bequest which was made or debt, as long as there is no detriment [caused]. [This is] an ordinance from Allah, and Allah is Knowing and Forbearing.', NULL, NULL, '47ecb531c3789bdede354390f1898a42326ed8961f4c69b1d12b156aa84fc1d2'),
  ('en.sahih', 4, 13, 506, 'These are the limits [set by] Allah, and whoever obeys Allah and His Messenger will be admitted by Him to gardens [in Paradise] under which rivers flow, abiding eternally therein; and that is the great attainment.', NULL, NULL, '62f4879dfe49c80c2e78bdc297b02729adc3132145f84f969581a94998f01fbd'),
  ('en.sahih', 4, 14, 507, 'And whoever disobeys Allah and His Messenger and transgresses His limits - He will put him into the Fire to abide eternally therein, and he will have a humiliating punishment.', NULL, NULL, 'd24f937cdfca8f7160f58bd27c3b813de03fae68b76d5f298624060c10ad3d2d'),
  ('en.sahih', 4, 15, 508, 'Those who commit unlawful sexual intercourse of your women - bring against them four [witnesses] from among you. And if they testify, confine the guilty women to houses until death takes them or Allah ordains for them [another] way.', NULL, NULL, '585c521eb4d2a464f86b5c0aafd39b8b591c10fc5f96e0a7db248605792188eb'),
  ('en.sahih', 4, 16, 509, 'And the two who commit it among you, dishonor them both. But if they repent and correct themselves, leave them alone. Indeed, Allah is ever Accepting of repentance and Merciful.', NULL, NULL, '7f229397f22d6853f4359a5405fbc334d2b1d549fd5357388fa02e1e40933292'),
  ('en.sahih', 4, 17, 510, 'The repentance accepted by Allah is only for those who do wrong in ignorance [or carelessness] and then repent soon after. It is those to whom Allah will turn in forgiveness, and Allah is ever Knowing and Wise.', NULL, NULL, '496f6cc3b137f33e71b6c94d1bfca66ec863d9a9b7e2635bfc67b830c51e1ee8'),
  ('en.sahih', 4, 18, 511, 'But repentance is not [accepted] of those who [continue to] do evil deeds up until, when death comes to one of them, he says, "Indeed, I have repented now," or of those who die while they are disbelievers. For them We have prepared a painful punishment.', NULL, NULL, '91b96a6986094761efc094cffd02384b2e3dc28cb07ff2c7f4437dd1c795beaa'),
  ('en.sahih', 4, 19, 512, 'O you who have believed, it is not lawful for you to inherit women by compulsion. And do not make difficulties for them in order to take [back] part of what you gave them unless they commit a clear immorality. And live with them in kindness. For if you dislike them - perhaps you dislike a thing and Allah makes therein much good.', NULL, NULL, 'f82f34609b25abe4b6a7f26515c24a915c77b99217da0d06caf5fc38bbc60fdd'),
  ('en.sahih', 4, 20, 513, 'But if you want to replace one wife with another and you have given one of them a great amount [in gifts], do not take [back] from it anything. Would you take it in injustice and manifest sin?', NULL, NULL, '5d0e05a62e2917d52bfb32dd9978db547539d5a4a83db6b0ccd35f0b76a2bb8e'),
  ('en.sahih', 4, 21, 514, 'And how could you take it while you have gone in unto each other and they have taken from you a solemn covenant?', NULL, NULL, '0f902c39ca5e20536601b21b2886fe9ad26e3218dce661cf60118ca9591687a6'),
  ('en.sahih', 4, 22, 515, 'And do not marry those [women] whom your fathers married, except what has already occurred. Indeed, it was an immorality and hateful [to Allah] and was evil as a way.', NULL, NULL, '6f3a21cf62e204d72d75441382e6e999124e25196b584b9d2d32ebc157f8422d'),
  ('en.sahih', 4, 23, 516, 'Prohibited to you [for marriage] are your mothers, your daughters, your sisters, your father''s sisters, your mother''s sisters, your brother''s daughters, your sister''s daughters, your [milk] mothers who nursed you, your sisters through nursing, your wives'' mothers, and your step-daughters under your guardianship [born] of your wives unto whom you have gone in. But if you have not gone in unto them, there is no sin upon you. And [also prohibited are] the wives of your sons who are from your [own] loins, and that you take [in marriage] two sisters simultaneously, except for what has already occurred. Indeed, Allah is ever Forgiving and Merciful.', NULL, NULL, '7f949ef1c20552d556a5044ec13524c76ea4cc14f68315d781a4a5ce45bd2df9'),
  ('en.sahih', 4, 24, 517, 'And [also prohibited to you are all] married women except those your right hands possess. [This is] the decree of Allah upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, 'bd12e5cbaf96e4f6af7ba86e257c943f519703d56c6e3b5969c033440e8377a5'),
  ('en.sahih', 4, 25, 518, 'And whoever among you cannot [find] the means to marry free, believing women, then [he may marry] from those whom your right hands possess of believing slave girls. And Allah is most knowing about your faith. You [believers] are of one another. So marry them with the permission of their people and give them their due compensation according to what is acceptable. [They should be] chaste, neither [of] those who commit unlawful intercourse randomly nor those who take [secret] lovers. But once they are sheltered in marriage, if they should commit adultery, then for them is half the punishment for free [unmarried] women. This [allowance] is for him among you who fears sin, but to be patient is better for you. And Allah is Forgiving and Merciful.', NULL, NULL, '1bc20577ed94b7b307c1d7ff45d97404de8153609765093ca652a579a136e13d'),
  ('en.sahih', 4, 26, 519, 'Allah wants to make clear to you [the lawful from the unlawful] and guide you to the [good] practices of those before you and to accept your repentance. And Allah is Knowing and Wise.', NULL, NULL, 'daf78e1c908075bc7db32c3b66ac6f5ef21b6361add89adf1b3f82743c931618'),
  ('en.sahih', 4, 27, 520, 'Allah wants to accept your repentance, but those who follow [their] passions want you to digress [into] a great deviation.', NULL, NULL, 'c23d7428c6ac2576f2eefafb0a6ddfd5aa9e2aab56080ae5c18d4fb2e60c48ef'),
  ('en.sahih', 4, 28, 521, 'And Allah wants to lighten for you [your difficulties]; and mankind was created weak.', NULL, NULL, 'c7332ba2edcfe5117e999cba8344e20654697a1c527c8c33eff02f3164fdb583'),
  ('en.sahih', 4, 29, 522, 'O you who have believed, do not consume one another''s wealth unjustly but only [in lawful] business by mutual consent. And do not kill yourselves [or one another]. Indeed, Allah is to you ever Merciful.', NULL, NULL, 'ebca041769348352588bfb03beb17f83e7b176bcaae9307a660f38fcba3203ad'),
  ('en.sahih', 4, 30, 523, 'And whoever does that in aggression and injustice - then We will drive him into a Fire. And that, for Allah, is [always] easy.', NULL, NULL, '1c224a56c783499d494c652f6478daa6258db8b81de33d5f82ecaed45505a08d'),
  ('en.sahih', 4, 31, 524, 'If you avoid the major sins which you are forbidden, We will remove from you your lesser sins and admit you to a noble entrance [into Paradise].', NULL, NULL, '30abadc2571e032f356cb8186a258f79261f11a89781b56ea71c172b918ef708'),
  ('en.sahih', 4, 32, 525, 'And do not wish for that by which Allah has made some of you exceed others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask Allah of his bounty. Indeed Allah is ever, of all things, Knowing.', NULL, NULL, 'a24d0bd7430030d1eda1f70de85ba7a7f60b883c133feeda05db26e2454190f6'),
  ('en.sahih', 4, 33, 526, 'And for all, We have made heirs to what is left by parents and relatives. And to those whom your oaths have bound [to you] - give them their share. Indeed Allah is ever, over all things, a Witness.', NULL, NULL, 'f580853400776a8170da4f5a56876eab941303285fc7feb94b9b241ee7df20bf'),
  ('en.sahih', 4, 34, 527, 'Men are in charge of women by [right of] what Allah has given one over the other and what they spend [for maintenance] from their wealth. So righteous women are devoutly obedient, guarding in [the husband''s] absence what Allah would have them guard. But those [wives] from whom you fear arrogance - [first] advise them; [then if they persist], forsake them in bed; and [finally], strike them. But if they obey you [once more], seek no means against them. Indeed, Allah is ever Exalted and Grand.', NULL, NULL, '69c2b16411d520386344d7543441579df50a52ffd7afd687c2822ea9c7458041'),
  ('en.sahih', 4, 35, 528, 'And if you fear dissension between the two, send an arbitrator from his people and an arbitrator from her people. If they both desire reconciliation, Allah will cause it between them. Indeed, Allah is ever Knowing and Acquainted [with all things].', NULL, NULL, '294c8509a9b9ffb49b0c366af95b6072325ce830c05460b42a81c9d287e5314b'),
  ('en.sahih', 4, 36, 529, 'Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful.', NULL, NULL, '6bb9140cbd0d30bdf5cfcfd74fea3da2bbadf2fca488f7e9fedfee87c0efca2f'),
  ('en.sahih', 4, 37, 530, 'Who are stingy and enjoin upon [other] people stinginess and conceal what Allah has given them of His bounty - and We have prepared for the disbelievers a humiliating punishment -', NULL, NULL, '6fa5a4ae0314b2d601cda682874aba1ce1a99c68abbdbee906f2bc54a1814218'),
  ('en.sahih', 4, 38, 531, 'And [also] those who spend of their wealth to be seen by the people and believe not in Allah nor in the Last Day. And he to whom Satan is a companion - then evil is he as a companion.', NULL, NULL, '83e469efc6bb23db241c89d2d8f097bb32c5bfa7b916ccc55e693c59bf8e520f'),
  ('en.sahih', 4, 39, 532, 'And what [harm would come] upon them if they believed in Allah and the Last Day and spent out of what Allah provided for them? And Allah is ever, about them, Knowing.', NULL, NULL, 'ffe6f341543c0734fe495b9b02881db2362e7903daa5b69143b22195c2a24cd8'),
  ('en.sahih', 4, 40, 533, 'Indeed, Allah does not do injustice, [even] as much as an atom''s weight; while if there is a good deed, He multiplies it and gives from Himself a great reward.', NULL, NULL, 'e710b003411955fa6e741354456b7c9518baa5e37f89195bb5eece37f55be5a3'),
  ('en.sahih', 4, 41, 534, 'So how [will it be] when We bring from every nation a witness and we bring you, [O Muhammad] against these [people] as a witness?', NULL, NULL, '44159dc5c86e7112a72b3f3c5d5b5ae8f167a582929ed8088a506588dc6f5b33'),
  ('en.sahih', 4, 42, 535, 'That Day, those who disbelieved and disobeyed the Messenger will wish they could be covered by the earth. And they will not conceal from Allah a [single] statement.', NULL, NULL, '63b1c2bbff40532686a763feacff2d6ce900d0f5bcd4c01202c46263d3963c1d'),
  ('en.sahih', 4, 43, 536, 'O you who have believed, do not approach prayer while you are intoxicated until you know what you are saying or in a state of janabah, except those passing through [a place of prayer], until you have washed [your whole body]. And if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and find no water, then seek clean earth and wipe over your faces and your hands [with it]. Indeed, Allah is ever Pardoning and Forgiving.', NULL, NULL, 'a4a1f50e5b90ed1eb93d32ee42e3ceee4d25eaff9a3728bf0230a0cbb0979ba2'),
  ('en.sahih', 4, 44, 537, 'Have you not seen those who were given a portion of the Scripture, purchasing error [in exchange for it] and wishing you would lose the way?', NULL, NULL, 'f30974bcda285fbf1c98df3f4415738161af9f119b7abac6a7eb538484d5dda4'),
  ('en.sahih', 4, 45, 538, 'And Allah is most knowing of your enemies; and sufficient is Allah as an ally, and sufficient is Allah as a helper.', NULL, NULL, '5d3903ef987947489076615943abc79362fdce2a0264059f5521a1ea0b61c42d'),
  ('en.sahih', 4, 46, 539, 'Among the Jews are those who distort words from their [proper] usages and say, "We hear and disobey" and "Hear but be not heard" and "Ra''ina," twisting their tongues and defaming the religion. And if they had said [instead], "We hear and obey" and "Wait for us [to understand]," it would have been better for them and more suitable. But Allah has cursed them for their disbelief, so they believe not, except for a few.', NULL, NULL, '4b5a4a22660dfcafb76c412c5db55902ef93631965db50ffe360bac221b96447'),
  ('en.sahih', 4, 47, 540, 'O you who were given the Scripture, believe in what We have sent down [to Muhammad], confirming that which is with you, before We obliterate faces and turn them toward their backs or curse them as We cursed the sabbath-breakers. And ever is the decree of Allah accomplished.', NULL, NULL, '313ea59988490a66803e24964a912246e1e9b60ca37285ce70223fa779a319e8'),
  ('en.sahih', 4, 48, 541, 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly fabricated a tremendous sin.', NULL, NULL, '8a3a8f1ebf3f8ca4797398b7c349db391697c089b7e6e6d621ae5821ef36875c'),
  ('en.sahih', 4, 49, 542, 'Have you not seen those who claim themselves to be pure? Rather, Allah purifies whom He wills, and injustice is not done to them, [even] as much as a thread [inside a date seed].', NULL, NULL, '6b0950a617ed8891a1c91d469c1bb1996f44f261d6d68f0e8b580ec1b5433455'),
  ('en.sahih', 4, 50, 543, 'Look how they invent about Allah untruth, and sufficient is that as a manifest sin.', NULL, NULL, 'ae82430e8a640a85086e4f958d27fd656de4aa42ba94fb311dc072a7b3afe20f'),
  ('en.sahih', 4, 51, 544, 'Have you not seen those who were given a portion of the Scripture, who believe in superstition and false objects of worship and say about the disbelievers, "These are better guided than the believers as to the way"?', NULL, NULL, 'b63184104b5d5d0ef6521baa1584d1930fdbd2a275be142f3ee32c84125110a0'),
  ('en.sahih', 4, 52, 545, 'Those are the ones whom Allah has cursed; and he whom Allah curses - never will you find for him a helper.', NULL, NULL, '467ee7f3a40e258eafba937dd25e360e36471ccb148700c05a5e807c9df8a7ef'),
  ('en.sahih', 4, 53, 546, 'Or have they a share of dominion? Then [if that were so], they would not give the people [even as much as] the speck on a date seed.', NULL, NULL, '6cf38f54ac1e6f9258d13b1bc65d166d4cc42566c126423871eea244cc74e6e1'),
  ('en.sahih', 4, 54, 547, 'Or do they envy people for what Allah has given them of His bounty? But we had already given the family of Abraham the Scripture and wisdom and conferred upon them a great kingdom.', NULL, NULL, '1ce458daf60a474a2aabd6dd54d98e43134d8e2e9d2ed17cc351efff3f94e04f'),
  ('en.sahih', 4, 55, 548, 'And some among them believed in it, and some among them were averse to it. And sufficient is Hell as a blaze.', NULL, NULL, '252647f71457352714e79835928730b34cd9014e7c7b9906c89b1f53b12cc06b'),
  ('en.sahih', 4, 56, 549, 'Indeed, those who disbelieve in Our verses - We will drive them into a Fire. Every time their skins are roasted through We will replace them with other skins so they may taste the punishment. Indeed, Allah is ever Exalted in Might and Wise.', NULL, NULL, 'f586a2e92f2000fdb0967f48050c65d61364ac50a906af1697705699cf645ee7'),
  ('en.sahih', 4, 57, 550, 'But those who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they abide forever. For them therein are purified spouses, and We will admit them to deepening shade.', NULL, NULL, '4eafe8723affeff638a62cc5d29d034823f3ddc1151a43c883b9d7dc0a034099'),
  ('en.sahih', 4, 58, 551, 'Indeed, Allah commands you to render trusts to whom they are due and when you judge between people to judge with justice. Excellent is that which Allah instructs you. Indeed, Allah is ever Hearing and Seeing.', NULL, NULL, 'bbdfb1f2e4785434d95fc9c7d6be9417c11e45aa207296e8753d61032e458be3'),
  ('en.sahih', 4, 59, 552, 'O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best [way] and best in result.', NULL, NULL, '39a970108a6e176741d915ba6de4ad7b3640938674be8508e8d21eada682ad4c'),
  ('en.sahih', 4, 60, 553, 'Have you not seen those who claim to have believed in what was revealed to you, [O Muhammad], and what was revealed before you? They wish to refer legislation to Taghut, while they were commanded to reject it; and Satan wishes to lead them far astray.', NULL, NULL, '53a73ebfa323ac6e3219f60ce7c9fda61ce797026dbaf71391b60a35c089793f'),
  ('en.sahih', 4, 61, 554, 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," you see the hypocrites turning away from you in aversion.', NULL, NULL, 'acea3ef9a713518fddbf33dca0ff6519b75ff69f7ebad4cfa636bf4db87dde65'),
  ('en.sahih', 4, 62, 555, 'So how [will it be] when disaster strikes them because of what their hands have put forth and then they come to you swearing by Allah, "We intended nothing but good conduct and accommodation."', NULL, NULL, '0badc9740115d3869efe8a3caaa656a09d9bb5a4f47feeb91c79b884cdc3f182'),
  ('en.sahih', 4, 63, 556, 'Those are the ones of whom Allah knows what is in their hearts, so turn away from them but admonish them and speak to them a far-reaching word.', NULL, NULL, '9e66ff7156628027070363a628ce6618793175810b3a6729d4bdb07af4bfe3a3'),
  ('en.sahih', 4, 64, 557, 'And We did not send any messenger except to be obeyed by permission of Allah. And if, when they wronged themselves, they had come to you, [O Muhammad], and asked forgiveness of Allah and the Messenger had asked forgiveness for them, they would have found Allah Accepting of repentance and Merciful.', NULL, NULL, '73f88192ea33e7c2aeae98aaa0256f23633789e2ae3a110e47f003e3f0138001'),
  ('en.sahih', 4, 65, 558, 'But no, by your Lord, they will not [truly] believe until they make you, [O Muhammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission.', NULL, NULL, 'ba1cdb3a13de54cb6e2118474af5bd64ec23045542f9f098e9ab8db1b8cd9ad1'),
  ('en.sahih', 4, 66, 559, 'And if We had decreed upon them, "Kill yourselves" or "Leave your homes," they would not have done it, except for a few of them. But if they had done what they were instructed, it would have been better for them and a firmer position [for them in faith].', NULL, NULL, '8771ee1909897f60fb3476ea0e5f3f84d7c6e2626b525b49a4b70a97c698072c'),
  ('en.sahih', 4, 67, 560, 'And then We would have given them from Us a great reward.', NULL, NULL, '2bcc41836a0398ec242edad4dd45d34946ea957b917181d5be56047fa2efa5c7'),
  ('en.sahih', 4, 68, 561, 'And We would have guided them to a straight path.', NULL, NULL, '5c120f6507004bee1b32452438034701e97669d139a809eb842ba1e3a37e4a03'),
  ('en.sahih', 4, 69, 562, 'And whoever obeys Allah and the Messenger - those will be with the ones upon whom Allah has bestowed favor of the prophets, the steadfast affirmers of truth, the martyrs and the righteous. And excellent are those as companions.', NULL, NULL, '68b9e5bd1019f354a3b3b205ad58638bb094e4584feb46b0287a6925fc748ca7'),
  ('en.sahih', 4, 70, 563, 'That is the bounty from Allah, and sufficient is Allah as Knower.', NULL, NULL, 'd370e826ce5d91c9a066851fb9435406227abc69207e28aa601446f56740260e'),
  ('en.sahih', 4, 71, 564, 'O you who have believed, take your precaution and [either] go forth in companies or go forth all together.', NULL, NULL, '8b992f1c629440eb29fff7546e4fd2fe309a16500cdd99f3eebf192a72ea1447'),
  ('en.sahih', 4, 72, 565, 'And indeed, there is among you he who lingers behind; and if disaster strikes you, he says, "Allah has favored me in that I was not present with them."', NULL, NULL, 'a841c3602f62ab15d7d82c0788c5271789dcba177995758eedd73cdc121141a6'),
  ('en.sahih', 4, 73, 566, 'But if bounty comes to you from Allah, he will surely say, as if there had never been between you and him any affection. "Oh, I wish I had been with them so I could have attained a great attainment."', NULL, NULL, 'b83b8ee0703459ab9be1341233cd1392e64cb7f7bee894025da715722470948d'),
  ('en.sahih', 4, 74, 567, 'So let those fight in the cause of Allah who sell the life of this world for the Hereafter. And he who fights in the cause of Allah and is killed or achieves victory - We will bestow upon him a great reward.', NULL, NULL, '017bfa4a6df0fe1b9827b6db5382189c32a2dee003cac432bd4bdabdfd1ff49a'),
  ('en.sahih', 4, 75, 568, 'And what is [the matter] with you that you fight not in the cause of Allah and [for] the oppressed among men, women, and children who say, "Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper?"', NULL, NULL, 'f66c8676519bcbed80b0d63040f9c3cabd6900029cc5c29c8374d80f26b711a4'),
  ('en.sahih', 4, 76, 569, 'Those who believe fight in the cause of Allah, and those who disbelieve fight in the cause of Taghut. So fight against the allies of Satan. Indeed, the plot of Satan has ever been weak.', NULL, NULL, 'fa0f53dc7974ab7721d722e1b142be2196509d9b9cd06228ddba9bc2ea9ceef2'),
  ('en.sahih', 4, 77, 570, 'Have you not seen those who were told, "Restrain your hands [from fighting] and establish prayer and give zakah"? But then when fighting was ordained for them, at once a party of them feared men as they fear Allah or with [even] greater fear. They said, "Our Lord, why have You decreed upon us fighting? If only You had postponed [it for] us for a short time." Say, The enjoyment of this world is little, and the Hereafter is better for he who fears Allah. And injustice will not be done to you, [even] as much as a thread [inside a date seed]."', NULL, NULL, '5114845cafa28fc4e37b6820b95b342b09ca96477caae8430ec733924eeb736d'),
  ('en.sahih', 4, 78, 571, 'Wherever you may be, death will overtake you, even if you should be within towers of lofty construction. But if good comes to them, they say, "This is from Allah "; and if evil befalls them, they say, "This is from you." Say, "All [things] are from Allah." So what is [the matter] with those people that they can hardly understand any statement?', NULL, NULL, 'd8d1d277dbeffd9d10205d3c9c11ac8e9fb727fbca87871622a233245b722a74'),
  ('en.sahih', 4, 79, 572, 'What comes to you of good is from Allah, but what comes to you of evil, [O man], is from yourself. And We have sent you, [O Muhammad], to the people as a messenger, and sufficient is Allah as Witness.', NULL, NULL, 'ba622c31b1569408e05070e44c0083593d6473cb4a08d363c859185b814f0203'),
  ('en.sahih', 4, 80, 573, 'He who obeys the Messenger has obeyed Allah; but those who turn away - We have not sent you over them as a guardian.', NULL, NULL, '0e7da86d14ec306830e222932bdb6726cb161b658983ea6fd188cb9110f627ed'),
  ('en.sahih', 4, 81, 574, 'And they say, "[We pledge] obedience." But when they leave you, a group of them spend the night determining to do other than what you say. But Allah records what they plan by night. So leave them alone and rely upon Allah. And sufficient is Allah as Disposer of affairs.', NULL, NULL, 'da38b735c44898a4a60e8ce79eb4f691ec3d553071e43bd6bbd7d5d996397a7f'),
  ('en.sahih', 4, 82, 575, 'Then do they not reflect upon the Qur''an? If it had been from [any] other than Allah, they would have found within it much contradiction.', NULL, NULL, '392f40dc255f07914cc2eacb9350c04d58457ffab395ef231bf9c0f88ef5807f'),
  ('en.sahih', 4, 83, 576, 'And when there comes to them information about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allah upon you and His mercy, you would have followed Satan, except for a few.', NULL, NULL, '0d94ae93c557ab5542920cc1d1de27d859519c5120075c245c3575c10e76f276'),
  ('en.sahih', 4, 84, 577, 'So fight, [O Muhammad], in the cause of Allah; you are not held responsible except for yourself. And encourage the believers [to join you] that perhaps Allah will restrain the [military] might of those who disbelieve. And Allah is greater in might and stronger in [exemplary] punishment.', NULL, NULL, 'a4599acf0e66a07c6826e1f76c34752a6f0334f19275d52ab7626f4c38b464c7'),
  ('en.sahih', 4, 85, 578, 'Whoever intercedes for a good cause will have a reward therefrom; and whoever intercedes for an evil cause will have a burden therefrom. And ever is Allah, over all things, a Keeper.', NULL, NULL, 'fcfaf7e30790fd6194475c094e8f38cf9c8311dab2c5ac8abac2e4b4d3119038'),
  ('en.sahih', 4, 86, 579, 'And when you are greeted with a greeting, greet [in return] with one better than it or [at least] return it [in a like manner]. Indeed, Allah is ever, over all things, an Accountant.', NULL, NULL, 'd9ed1a950a8a439b2558df7fd2d2acd44076cc540a54dcadb67943d8b3267734'),
  ('en.sahih', 4, 87, 580, 'Allah - there is no deity except Him. He will surely assemble you for [account on] the Day of Resurrection, about which there is no doubt. And who is more truthful than Allah in statement.', NULL, NULL, '7cdbf30a9908f2d3cef33cf5db14aa479924e68480f192a2bb83b3e972fc61ee'),
  ('en.sahih', 4, 88, 581, 'What is [the matter] with you [that you are] two groups concerning the hypocrites, while Allah has made them fall back [into error and disbelief] for what they earned. Do you wish to guide those whom Allah has sent astray? And he whom Allah sends astray - never will you find for him a way [of guidance].', NULL, NULL, '9afe2cdd4d26c94c25bb33db3bcc2578f7a80e2b21a5441ac84dfd68d7a52867'),
  ('en.sahih', 4, 89, 582, 'They wish you would disbelieve as they disbelieved so you would be alike. So do not take from among them allies until they emigrate for the cause of Allah. But if they turn away, then seize them and kill them wherever you find them and take not from among them any ally or helper.', NULL, NULL, 'face89748eb75f5a1d56ce5a4d89c083a294e68e40497d411c86fc5fdb816700'),
  ('en.sahih', 4, 90, 583, 'Except for those who take refuge with a people between yourselves and whom is a treaty or those who come to you, their hearts strained at [the prospect of] fighting you or fighting their own people. And if Allah had willed, He could have given them power over you, and they would have fought you. So if they remove themselves from you and do not fight you and offer you peace, then Allah has not made for you a cause [for fighting] against them.', NULL, NULL, '2eb743e85c5ba903d0c2cf89016baf2a7457cb1a56ccded4c8fc7161ac57a18b'),
  ('en.sahih', 4, 91, 584, 'You will find others who wish to obtain security from you and [to] obtain security from their people. Every time they are returned to [the influence of] disbelief, they fall back into it. So if they do not withdraw from you or offer you peace or restrain their hands, then seize them and kill them wherever you overtake them. And those - We have made for you against them a clear authorization.', NULL, NULL, '15adf336cec2ba53cd455cd84fda8b31a712fe39f5aa4f30a6e0283fb9171bd2'),
  ('en.sahih', 4, 92, 585, 'And never is it for a believer to kill a believer except by mistake. And whoever kills a believer by mistake - then the freeing of a believing slave and a compensation payment presented to the deceased''s family [is required] unless they give [up their right as] charity. But if the deceased was from a people at war with you and he was a believer - then [only] the freeing of a believing slave; and if he was from a people with whom you have a treaty - then a compensation payment presented to his family and the freeing of a believing slave. And whoever does not find [one or cannot afford to buy one] - then [instead], a fast for two months consecutively, [seeking] acceptance of repentance from Allah. And Allah is ever Knowing and Wise.', NULL, NULL, 'ed728cf0277715e517ec6923f6a631ff679720b3ec834875846afc474bd9dbf0'),
  ('en.sahih', 4, 93, 586, 'But whoever kills a believer intentionally - his recompense is Hell, wherein he will abide eternally, and Allah has become angry with him and has cursed him and has prepared for him a great punishment.', NULL, NULL, '10acd859fff3bfb004e357ac06c2b2192aca711f2cbe420b9635460ee4535c07'),
  ('en.sahih', 4, 94, 587, 'O you who have believed, when you go forth [to fight] in the cause of Allah, investigate; and do not say to one who gives you [a greeting of] peace "You are not a believer," aspiring for the goods of worldly life; for with Allah are many acquisitions. You [yourselves] were like that before; then Allah conferred His favor upon you, so investigate. Indeed Allah is ever, with what you do, Acquainted.', NULL, NULL, 'a53f7f13ecbc4e83dfdce918d9c8d2dfbe365b244ff00434f41844c1b1c7a5cd'),
  ('en.sahih', 4, 95, 588, 'Not equal are those believers remaining [at home] - other than the disabled - and the mujahideen, [who strive and fight] in the cause of Allah with their wealth and their lives. Allah has preferred the mujahideen through their wealth and their lives over those who remain [behind], by degrees. And to both Allah has promised the best [reward]. But Allah has preferred the mujahideen over those who remain [behind] with a great reward -', NULL, NULL, 'ca77142e6c00788fc6c3393ae1e7f202a1f0f1b8920396ec11f8a7696dad1c14'),
  ('en.sahih', 4, 96, 589, 'Degrees [of high position] from Him and forgiveness and mercy. And Allah is ever Forgiving and Merciful.', NULL, NULL, '6bfe9804386d3e386f28bc53444354c780fadea02f1aa9756287705923f6a462'),
  ('en.sahih', 4, 97, 590, 'Indeed, those whom the angels take [in death] while wronging themselves - [the angels] will say, "In what [condition] were you?" They will say, "We were oppressed in the land." The angels will say, "Was not the earth of Allah spacious [enough] for you to emigrate therein?" For those, their refuge is Hell - and evil it is as a destination.', NULL, NULL, '390ddded45ad3cd23c957220bbdcd561c9ebb3d11930b85924fb38f34297cf9a'),
  ('en.sahih', 4, 98, 591, 'Except for the oppressed among men, women and children who cannot devise a plan nor are they directed to a way -', NULL, NULL, '622118ed261f2cefd0eab31d421954aef0b39fc748347b8315613977135afa7a'),
  ('en.sahih', 4, 99, 592, 'For those it is expected that Allah will pardon them, and Allah is ever Pardoning and Forgiving.', NULL, NULL, 'a6240991a614e6d582f692f3a5b44b81255941ea9408871177b4a5a5641da35f'),
  ('en.sahih', 4, 100, 593, 'And whoever emigrates for the cause of Allah will find on the earth many [alternative] locations and abundance. And whoever leaves his home as an emigrant to Allah and His Messenger and then death overtakes him - his reward has already become incumbent upon Allah. And Allah is ever Forgiving and Merciful.', NULL, NULL, '7c6bf2c22a8722626c4b6d62a5ce6ab9f966324d524f05a4033ba3a70fe395ea'),
  ('en.sahih', 4, 101, 594, 'And when you travel throughout the land, there is no blame upon you for shortening the prayer, [especially] if you fear that those who disbelieve may disrupt [or attack] you. Indeed, the disbelievers are ever to you a clear enemy.', NULL, NULL, '2b5c19525f6dca82e41e8436e7c54b6b07b42838d97970e76f01e0dbfcd668c8'),
  ('en.sahih', 4, 102, 595, 'And when you are among them and lead them in prayer, let a group of them stand [in prayer] with you and let them carry their arms. And when they have prostrated, let them be [in position] behind you and have the other group come forward which has not [yet] prayed and let them pray with you, taking precaution and carrying their arms. Those who disbelieve wish that you would neglect your weapons and your baggage so they could come down upon you in one [single] attack. But there is no blame upon you, if you are troubled by rain or are ill, for putting down your arms, but take precaution. Indeed, Allah has prepared for the disbelievers a humiliating punishment.', NULL, NULL, '739c895bbc4d3178d2ea49564532b1cf7b6c34529e5c6eee20c2342f4c5d9ca5'),
  ('en.sahih', 4, 103, 596, 'And when you have completed the prayer, remember Allah standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times.', NULL, NULL, '5b6eae505e79585ddca80d66d1b3182c4fb9ca216721a937803b48b40fe70be1'),
  ('en.sahih', 4, 104, 597, 'And do not weaken in pursuit of the enemy. If you should be suffering - so are they suffering as you are suffering, but you expect from Allah that which they expect not. And Allah is ever Knowing and Wise.', NULL, NULL, '410aa277f80d16c6f42d8053e02c0166d00dbaa7b916a678e93c89cc213ae4d3'),
  ('en.sahih', 4, 105, 598, 'Indeed, We have revealed to you, [O Muhammad], the Book in truth so you may judge between the people by that which Allah has shown you. And do not be for the deceitful an advocate.', NULL, NULL, '75d7469103374af88f1af89c4f335e1e7cd7c44df706f48266e0e23f980cf131'),
  ('en.sahih', 4, 106, 599, 'And seek forgiveness of Allah. Indeed, Allah is ever Forgiving and Merciful.', NULL, NULL, '55daecc340dbe6688e3a592540f63d76c6d2a1cc5d23e33a72ed5f8a5b7657aa'),
  ('en.sahih', 4, 107, 600, 'And do not argue on behalf of those who deceive themselves. Indeed, Allah loves not one who is a habitually sinful deceiver.', NULL, NULL, '7a08b9f43858384cde689e182b9bb898595fc46e9a5378a3cf027e1ab1257919')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 4, 108, 601, 'They conceal [their evil intentions and deeds] from the people, but they cannot conceal [them] from Allah, and He is with them [in His knowledge] when they spend the night in such as He does not accept of speech. And ever is Allah, of what they do, encompassing.', NULL, NULL, 'b818119fb6e7468bb5c5f50319ac539963453c1e968d85f93bf335c113eda545'),
  ('en.sahih', 4, 109, 602, 'Here you are - those who argue on their behalf in [this] worldly life - but who will argue with Allah for them on the Day of Resurrection, or who will [then] be their representative?', NULL, NULL, '86edecd52388f7c65f2d5a12210b386551b23093233cfb1075a00025223acaf6'),
  ('en.sahih', 4, 110, 603, 'And whoever does a wrong or wrongs himself but then seeks forgiveness of Allah will find Allah Forgiving and Merciful.', NULL, NULL, 'f301bc8b9753d83d8660eeae3ee8cefd0af4258ceb165cca4abfed07f7deb0f9'),
  ('en.sahih', 4, 111, 604, 'And whoever commits a sin only earns it against himself. And Allah is ever Knowing and Wise.', NULL, NULL, 'ead1cbf55353a2a495c33013d55ff0c1954e7b2a708b9c5b523047e3a815f927'),
  ('en.sahih', 4, 112, 605, 'But whoever earns an offense or a sin and then blames it on an innocent [person] has taken upon himself a slander and manifest sin.', NULL, NULL, '5383d32bac60879a641c5f7e2e5db899d075036d26141ba13f21c2ce0024dab3'),
  ('en.sahih', 4, 113, 606, 'And if it was not for the favor of Allah upon you, [O Muhammad], and His mercy, a group of them would have determined to mislead you. But they do not mislead except themselves, and they will not harm you at all. And Allah has revealed to you the Book and wisdom and has taught you that which you did not know. And ever has the favor of Allah upon you been great.', NULL, NULL, '492c8d55bd5e60deffa935f49bfb75bf53c4e14d10a08bf67cf7e54b2a109ab4'),
  ('en.sahih', 4, 114, 607, 'No good is there in much of their private conversation, except for those who enjoin charity or that which is right or conciliation between people. And whoever does that seeking means to the approval of Allah - then We are going to give him a great reward.', NULL, NULL, 'ea495e1d835068c0d6d35d4b40068b8ee307e2aad55142d4e4d1f89006e3981c'),
  ('en.sahih', 4, 115, 608, 'And whoever opposes the Messenger after guidance has become clear to him and follows other than the way of the believers - We will give him what he has taken and drive him into Hell, and evil it is as a destination.', NULL, NULL, 'f0f42771f1a09f11637264fb5c3d7953f11bf7a5a65487c2e23b3b50c69e01a9'),
  ('en.sahih', 4, 116, 609, 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly gone far astray.', NULL, NULL, '7a00959851b9065c8905da3d367213e066522b57784123acea95fa39dec76faf'),
  ('en.sahih', 4, 117, 610, 'They call upon instead of Him none but female [deities], and they [actually] call upon none but a rebellious Satan.', NULL, NULL, 'edf74a5741b2b1fb74479eb83ea39b691859cd5c36884cd2f3995c4f7e2af2e8'),
  ('en.sahih', 4, 118, 611, 'Whom Allah has cursed. For he had said, "I will surely take from among Your servants a specific portion.', NULL, NULL, '529b15b88d078a0ecf8cd27437057190e45823c8ad89365de885e352aee545fc'),
  ('en.sahih', 4, 119, 612, 'And I will mislead them, and I will arouse in them [sinful] desires, and I will command them so they will slit the ears of cattle, and I will command them so they will change the creation of Allah." And whoever takes Satan as an ally instead of Allah has certainly sustained a clear loss.', NULL, NULL, '42004c19b528f201ac059f356869506d4bd030917bd549405fe808df49ff81c0'),
  ('en.sahih', 4, 120, 613, 'Satan promises them and arouses desire in them. But Satan does not promise them except delusion.', NULL, NULL, 'e5bfbfa708c83b14aca909081f19dc084fc289ab906cece5c978d51d65c2575b'),
  ('en.sahih', 4, 121, 614, 'The refuge of those will be Hell, and they will not find from it an escape.', NULL, NULL, '7e71ce19fddec0c9dc7d861ade942bc3c619a00fe125b3157af5f8e15b30d847'),
  ('en.sahih', 4, 122, 615, 'But the ones who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they will abide forever. [It is] the promise of Allah, [which is] truth, and who is more truthful than Allah in statement.', NULL, NULL, 'af63fb3cec9f0b4c5f5eea28df1e4df425a60bc32c73cc7fb813d166c9aab15b'),
  ('en.sahih', 4, 123, 616, 'Paradise is not [obtained] by your wishful thinking nor by that of the People of the Scripture. Whoever does a wrong will be recompensed for it, and he will not find besides Allah a protector or a helper.', NULL, NULL, 'b759fb4ec80c2c2515dc82138582c59787a6efc4defa3e4547fbcd61f90d59c9'),
  ('en.sahih', 4, 124, 617, 'And whoever does righteous deeds, whether male or female, while being a believer - those will enter Paradise and will not be wronged, [even as much as] the speck on a date seed.', NULL, NULL, 'eeba5260c1bca56b8be74082e8ba98f5d07491d5c72df0b9f7bdd1bd2d032ea7'),
  ('en.sahih', 4, 125, 618, 'And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend.', NULL, NULL, '97bc4284891578d03ac38be5451b56466ce8c2adafc2591637c3dd5847cb8b31'),
  ('en.sahih', 4, 126, 619, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah, of all things, encompassing.', NULL, NULL, 'e1b3014b33627484b9649c71b52c0a7e962433a97330f4335e6f4ea1fecee3b9'),
  ('en.sahih', 4, 127, 620, 'And they request from you, [O Muhammad], a [legal] ruling concerning women. Say, "Allah gives you a ruling about them and [about] what has been recited to you in the Book concerning the orphan girls to whom you do not give what is decreed for them - and [yet] you desire to marry them - and concerning the oppressed among children and that you maintain for orphans [their rights] in justice." And whatever you do of good - indeed, Allah is ever Knowing of it.', NULL, NULL, 'a59ab6be289ac39c996d6511c41d41525ebd300877846d6728bbf3e4a6c42171'),
  ('en.sahih', 4, 128, 621, 'And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them - and settlement is best. And present in [human] souls is stinginess. But if you do good and fear Allah - then indeed Allah is ever, with what you do, Acquainted.', NULL, NULL, '55f800508339d5c81dbdd86d55db95b66a75f8be390e812cce71926b227b7325'),
  ('en.sahih', 4, 129, 622, 'And you will never be able to be equal [in feeling] between wives, even if you should strive [to do so]. So do not incline completely [toward one] and leave another hanging. And if you amend [your affairs] and fear Allah - then indeed, Allah is ever Forgiving and Merciful.', NULL, NULL, '5f6bfa07f12a948d3f71df6cf70559c2defcb1ac00321146979f329c9749433e'),
  ('en.sahih', 4, 130, 623, 'But if they separate [by divorce], Allah will enrich each [of them] from His abundance. And ever is Allah Encompassing and Wise.', NULL, NULL, 'a9fa2285e3349c29787bf9733f724eb3e64ddd3dbb1141b1dfd97a1e366ea423'),
  ('en.sahih', 4, 131, 624, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And We have instructed those who were given the Scripture before you and yourselves to fear Allah. But if you disbelieve - then to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah Free of need and Praiseworthy.', NULL, NULL, '01c3d63cdb8f46c178d081526e181e37ce9ed0d1c17deba9e50ba9d0d05af3f3'),
  ('en.sahih', 4, 132, 625, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.', NULL, NULL, 'd98798a1863934919e7f78b49d9d0f83fb7fa9c45a880d98c3c1e436824a08b1'),
  ('en.sahih', 4, 133, 626, 'If He wills, He can do away with you, O people, and bring others [in your place]. And ever is Allah competent to do that.', NULL, NULL, 'f91acd1c22ab0e9d9bf67d6b8023bed0cb7b784fd1b310d78bebb5757fde0f69'),
  ('en.sahih', 4, 134, 627, 'Whoever desires the reward of this world - then with Allah is the reward of this world and the Hereafter. And ever is Allah Hearing and Seeing.', NULL, NULL, '98b48184c4c210d20e92f02c63b698281303d53e72c7e967a7dfb89d093b4d70'),
  ('en.sahih', 4, 135, 628, 'O you who have believed, be persistently standing firm in justice, witnesses for Allah, even if it be against yourselves or parents and relatives. Whether one is rich or poor, Allah is more worthy of both. So follow not [personal] inclination, lest you not be just. And if you distort [your testimony] or refuse [to give it], then indeed Allah is ever, with what you do, Acquainted.', NULL, NULL, '9152b3f0528f121ecef75e2b9f6a98aff99d3ee215a461b01c87aae73b1f2aee'),
  ('en.sahih', 4, 136, 629, 'O you who have believed, believe in Allah and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allah, His angels, His books, His messengers, and the Last Day has certainly gone far astray.', NULL, NULL, 'dd3764bbabc4ec3e87e9b50721987ecb41f4e40c525ca8597fe90447a661cd50'),
  ('en.sahih', 4, 137, 630, 'Indeed, those who have believed then disbelieved, then believed, then disbelieved, and then increased in disbelief - never will Allah forgive them, nor will He guide them to a way.', NULL, NULL, '8069bc4286424625e32f41d4b5bd675c05808cb0e8a77eb34e3eee649bf3bcc3'),
  ('en.sahih', 4, 138, 631, 'Give tidings to the hypocrites that there is for them a painful punishment -', NULL, NULL, '9de6f8a9b5307000f3d8204231f700a2b4b04a18af6115f56eddd313a367d4d4'),
  ('en.sahih', 4, 139, 632, 'Those who take disbelievers as allies instead of the believers. Do they seek with them honor [through power]? But indeed, honor belongs to Allah entirely.', NULL, NULL, 'e056878d57bb9d3e711a55b9d10777cf9f5832e8462e214665fd1f0fe47198ca'),
  ('en.sahih', 4, 140, 633, 'And it has already come down to you in the Book that when you hear the verses of Allah [recited], they are denied [by them] and ridiculed; so do not sit with them until they enter into another conversation. Indeed, you would then be like them. Indeed Allah will gather the hypocrites and disbelievers in Hell all together -', NULL, NULL, 'b51a90f04782cbc3f1619036ac659d43980868af1048ee5a460bdbd93a24b748'),
  ('en.sahih', 4, 141, 634, 'Those who wait [and watch] you. Then if you gain a victory from Allah, they say, "Were we not with you?" But if the disbelievers have a success, they say [to them], "Did we not gain the advantage over you, but we protected you from the believers?" Allah will judge between [all of] you on the Day of Resurrection, and never will Allah give the disbelievers over the believers a way [to overcome them].', NULL, NULL, '56a8175ae9e2513907ac5c49d89914573e25bda176fd8c79acb7bc729cd4bf08'),
  ('en.sahih', 4, 142, 635, 'Indeed, the hypocrites [think to] deceive Allah, but He is deceiving them. And when they stand for prayer, they stand lazily, showing [themselves to] the people and not remembering Allah except a little,', NULL, NULL, 'beb12c9749ce4536f54b894a970554569898e88e01c6cda4ef2fb48a320d09f9'),
  ('en.sahih', 4, 143, 636, 'Wavering between them, [belonging] neither to the believers nor to the disbelievers. And whoever Allah leaves astray - never will you find for him a way.', NULL, NULL, 'a42361f9575b798c389ed5889a7b5fe77a75eb32f879ac80850e7c179cc68bfe'),
  ('en.sahih', 4, 144, 637, 'O you who have believed, do not take the disbelievers as allies instead of the believers. Do you wish to give Allah against yourselves a clear case?', NULL, NULL, '81bf76af1fc83c90b86dfe83ffd05ce3ce0dbb07b1383c0db3014f9ab16bacdd'),
  ('en.sahih', 4, 145, 638, 'Indeed, the hypocrites will be in the lowest depths of the Fire - and never will you find for them a helper -', NULL, NULL, 'b8c75699df025287782ca9060b729073afa88f91ab86eee986cccfcd3d37bd4e'),
  ('en.sahih', 4, 146, 639, 'Except for those who repent, correct themselves, hold fast to Allah, and are sincere in their religion for Allah, for those will be with the believers. And Allah is going to give the believers a great reward.', NULL, NULL, 'e89eca3bc6834ea2697c0e7265c6375bb06be220e3976c357da1946e88b7deb6'),
  ('en.sahih', 4, 147, 640, 'What would Allah do with your punishment if you are grateful and believe? And ever is Allah Appreciative and Knowing.', NULL, NULL, 'decb569c6a51d7534bcf522275e6ce29edd760341d9e4a808cd9cc488a921d2b'),
  ('en.sahih', 4, 148, 641, 'Allah does not like the public mention of evil except by one who has been wronged. And ever is Allah Hearing and Knowing.', NULL, NULL, 'dd81634a9d439d3c55ef0f47f775262eb98df8a51308a0d71be213fd84bfcfe8'),
  ('en.sahih', 4, 149, 642, 'If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allah is ever Pardoning and Competent.', NULL, NULL, '3e6a1f6bcbfe198880da9ed6074430287fee211fd628b4a749803f204ad4bf25'),
  ('en.sahih', 4, 150, 643, 'Indeed, those who disbelieve in Allah and His messengers and wish to discriminate between Allah and His messengers and say, "We believe in some and disbelieve in others," and wish to adopt a way in between -', NULL, NULL, 'd3b7f5d2c6ec8a6cebff979d4eedfc499143a5374610735a35fca59bec61492b'),
  ('en.sahih', 4, 151, 644, 'Those are the disbelievers, truly. And We have prepared for the disbelievers a humiliating punishment.', NULL, NULL, '1f7b6749b4b729047958b4516d058d1ce66206557d95e8629a8536972654a23e'),
  ('en.sahih', 4, 152, 645, 'But they who believe in Allah and His messengers and do not discriminate between any of them - to those He is going to give their rewards. And ever is Allah Forgiving and Merciful.', NULL, NULL, 'f13a904b5d2176d2ec48585bcbf7c4b5a31c37d42116e9b18fb45bc85519f8b5'),
  ('en.sahih', 4, 153, 646, 'The People of the Scripture ask you to bring down to them a book from the heaven. But they had asked of Moses [even] greater than that and said, "Show us Allah outright," so the thunderbolt struck them for their wrongdoing. Then they took the calf [for worship] after clear evidences had come to them, and We pardoned that. And We gave Moses a clear authority.', NULL, NULL, '68fd6cf02a54f2d417954516a992a6adca7c0a97b39a29d101571597e69d54f7'),
  ('en.sahih', 4, 154, 647, 'And We raised over them the mount for [refusal of] their covenant; and We said to them, "Enter the gate bowing humbly", and We said to them, "Do not transgress on the sabbath", and We took from them a solemn covenant.', NULL, NULL, '3250427fa93ea864ca3d8a5d12378cbf24e4b90c7b23240c9a379557fbb84039'),
  ('en.sahih', 4, 155, 648, 'And [We cursed them] for their breaking of the covenant and their disbelief in the signs of Allah and their killing of the prophets without right and their saying, "Our hearts are wrapped". Rather, Allah has sealed them because of their disbelief, so they believe not, except for a few.', NULL, NULL, 'a180029f4d6a79f98cd4a500b5fa0b53d2c84f62826b58d2fa9a1a857ca5f569'),
  ('en.sahih', 4, 156, 649, 'And [We cursed them] for their disbelief and their saying against Mary a great slander,', NULL, NULL, '129afda9417e934b3c919bf890edeba9e4ccd2b7a92383b3651b7fc4bc2ffbb6'),
  ('en.sahih', 4, 157, 650, 'And [for] their saying, "Indeed, we have killed the Messiah, Jesus, the son of Mary, the messenger of Allah." And they did not kill him, nor did they crucify him; but [another] was made to resemble him to them. And indeed, those who differ over it are in doubt about it. They have no knowledge of it except the following of assumption. And they did not kill him, for certain.', NULL, NULL, '285c65857c8286d1b965204fc9ec3050372b6b1e1961b27ee38f2b5b86d213d7'),
  ('en.sahih', 4, 158, 651, 'Rather, Allah raised him to Himself. And ever is Allah Exalted in Might and Wise.', NULL, NULL, 'f7926e1758a287c9ddf833d91f9ffb1dffd7ad40907cc5b0d04e81239f56a980'),
  ('en.sahih', 4, 159, 652, 'And there is none from the People of the Scripture but that he will surely believe in Jesus before his death. And on the Day of Resurrection he will be against them a witness.', NULL, NULL, 'b149e56fbc995447ffc3be1f5856d844af8ed14493c571ae6cf6dababc33e0de'),
  ('en.sahih', 4, 160, 653, 'For wrongdoing on the part of the Jews, We made unlawful for them [certain] good foods which had been lawful to them, and for their averting from the way of Allah many [people],', NULL, NULL, '11e8128f781ede5a69e8dcd19137d1c42b89bf24bcdd0277db58fdc388fd907e'),
  ('en.sahih', 4, 161, 654, 'And [for] their taking of usury while they had been forbidden from it, and their consuming of the people''s wealth unjustly. And we have prepared for the disbelievers among them a painful punishment.', NULL, NULL, '4bb3777e4ca608d4489864b3f9bfa39b6d7a50f733cc6377f29eb36ba4451d60'),
  ('en.sahih', 4, 162, 655, 'But those firm in knowledge among them and the believers believe in what has been revealed to you, [O Muhammad], and what was revealed before you. And the establishers of prayer [especially] and the givers of zakah and the believers in Allah and the Last Day - those We will give a great reward.', NULL, NULL, '5b7212d2bf2b7f8f2e503e5cacf0a974ef1dd6167c8e6a7d9d0ac3bfab13b95a'),
  ('en.sahih', 4, 163, 656, 'Indeed, We have revealed to you, [O Muhammad], as We revealed to Noah and the prophets after him. And we revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon, and to David We gave the book [of Psalms].', NULL, NULL, 'e3bb884cca036782b6dfa23e4d0106aef65635a1618ed21ac85038f52ad83663'),
  ('en.sahih', 4, 164, 657, 'And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allah spoke to Moses with [direct] speech.', NULL, NULL, '8d7c751455286e8313b7fd2ce0c8ccdf1884c039e85247ad874dc409531ce1da'),
  ('en.sahih', 4, 165, 658, '[We sent] messengers as bringers of good tidings and warners so that mankind will have no argument against Allah after the messengers. And ever is Allah Exalted in Might and Wise.', NULL, NULL, '5fa6b3d56069c6ff14a016475acef0976ed91a34967e1b1cacd74487b450d4f0'),
  ('en.sahih', 4, 166, 659, 'But Allah bears witness to that which He has revealed to you. He has sent it down with His knowledge, and the angels bear witness [as well]. And sufficient is Allah as Witness.', NULL, NULL, '86fc4a2f04afd7e2732f43b69013f5e40dd53acdc96f67220a2540f8db794d5e'),
  ('en.sahih', 4, 167, 660, 'Indeed, those who disbelieve and avert [people] from the way of Allah have certainly gone far astray.', NULL, NULL, '3aeb7bdf1471aa9c79c0092ebbfa6a6335395633a696fa0c88dd8e7bd8f2d983'),
  ('en.sahih', 4, 168, 661, 'Indeed, those who disbelieve and commit wrong [or injustice] - never will Allah forgive them, nor will He guide them to a path.', NULL, NULL, '900504df14efbfd21141d9df02b36710c956a35e9799c5046bd1b03aa818cac2'),
  ('en.sahih', 4, 169, 662, 'Except the path of Hell; they will abide therein forever. And that, for Allah, is [always] easy.', NULL, NULL, '7a94a0a073a600023f9797233584a7030619c7cd291bb2a40b3e24eb67148bab'),
  ('en.sahih', 4, 170, 663, 'O Mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allah belongs whatever is in the heavens and earth. And ever is Allah Knowing and Wise.', NULL, NULL, 'f1ed604de4e87f7932f8337eef2eb99993c8f7e557177037d643161e4f7c438d'),
  ('en.sahih', 4, 171, 664, 'O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, "Three"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.', NULL, NULL, '4d1cdf58bcc9a30e54304f335454c741fcfa1e0399b1935c9f250e49b0400450'),
  ('en.sahih', 4, 172, 665, 'Never would the Messiah disdain to be a servant of Allah, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together.', NULL, NULL, 'a75ad5a6088cd263abe62a02da034e02aeab5d72b74f67fe471e7b0745030a4d'),
  ('en.sahih', 4, 173, 666, 'And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allah any protector or helper.', NULL, NULL, '433c4002925887821f582de9a8077c07e26f6292a370683110667619fbbfa151'),
  ('en.sahih', 4, 174, 667, 'O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light.', NULL, NULL, 'c61d92bff59309c1daa4f81ccadf70b4cde444d9764feed9d9a2ce11f52ce4bd'),
  ('en.sahih', 4, 175, 668, 'So those who believe in Allah and hold fast to Him - He will admit them to mercy from Himself and bounty and guide them to Himself on a straight path.', NULL, NULL, '49ae4c97f59fa85e8f48bbffec4590fc220f5257308dce1218068f0813defb8d'),
  ('en.sahih', 4, 176, 669, 'They request from you a [legal] ruling. Say, "Allah gives you a ruling concerning one having neither descendants nor ascendants [as heirs]." If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two-thirds of what he left. If there are both brothers and sisters, the male will have the share of two females. Allah makes clear to you [His law], lest you go astray. And Allah is Knowing of all things.', NULL, NULL, '2dafe13feb536a565a519574888fc5c04810b050a24aa47eaac9202d764bbcc0'),
  ('en.sahih', 5, 1, 670, 'O you who have believed, fulfill [all] contracts. Lawful for you are the animals of grazing livestock except for that which is recited to you [in this Qur''an] - hunting not being permitted while you are in the state of ihram. Indeed, Allah ordains what He intends.', NULL, NULL, '060620d1e583652ab1e3a3286d2dab1e88e16ceda2ba4110893a225f8bafa1e2'),
  ('en.sahih', 5, 2, 671, 'O you who have believed, do not violate the rites of Allah or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of ihram, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Haram lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allah; indeed, Allah is severe in penalty.', NULL, NULL, 'b28c7625b9f6856d199a6320f1d1dfa477997b043be78ccd888a3f26b14c68b7'),
  ('en.sahih', 5, 3, 672, 'Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islam as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, '491b831fb56ca8e7fdba7e0ca141be6abb1a72fb69a80a421c595e827b817fc3'),
  ('en.sahih', 5, 4, 673, 'They ask you, [O Muhammad], what has been made lawful for them. Say, "Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals which you train as Allah has taught you. So eat of what they catch for you, and mention the name of Allah upon it, and fear Allah." Indeed, Allah is swift in account.', NULL, NULL, '9807df0976f599c63b481c999a3fed0df2c2f513cd18acd6156792939fc6d553'),
  ('en.sahih', 5, 5, 674, 'This day [all] good foods have been made lawful, and the food of those who were given the Scripture is lawful for you and your food is lawful for them. And [lawful in marriage are] chaste women from among the believers and chaste women from among those who were given the Scripture before you, when you have given them their due compensation, desiring chastity, not unlawful sexual intercourse or taking [secret] lovers. And whoever denies the faith - his work has become worthless, and he, in the Hereafter, will be among the losers.', NULL, NULL, 'a85723a7f782936e08a8d0cf036d9cd2a174b4b02bda3998ed43b1c3307b20b1'),
  ('en.sahih', 5, 6, 675, 'O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janabah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allah does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful.', NULL, NULL, '80f9fff652f69f8034ee6d292915fb948fff175556ce573552b416a3d0466770'),
  ('en.sahih', 5, 7, 676, 'And remember the favor of Allah upon you and His covenant with which He bound you when you said, "We hear and we obey"; and fear Allah. Indeed, Allah is Knowing of that within the breasts.', NULL, NULL, '4380f91a17f53585a74d5a80d10874e67acc1ab78e6c0e9d04b3525e20db78d4'),
  ('en.sahih', 5, 8, 677, 'O you who have believed, be persistently standing firm for Allah, witnesses in justice, and do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. And fear Allah; indeed, Allah is Acquainted with what you do.', NULL, NULL, '3793df0b1f63f64ab9233eea7d3deed343a0d92bf57518cba4b1324712e5d7ba'),
  ('en.sahih', 5, 9, 678, 'Allah has promised those who believe and do righteous deeds [that] for them there is forgiveness and great reward.', NULL, NULL, '77b122dcbecda2e2186010939dc3589d67508696d12bb047030616f6cbabd081'),
  ('en.sahih', 5, 10, 679, 'But those who disbelieve and deny Our signs - those are the companions of Hellfire.', NULL, NULL, '32fc41d014c24067f8a77561423b8828e176ad66c37c26887d8b9dfdaa607b3b'),
  ('en.sahih', 5, 11, 680, 'O you who have believed, remember the favor of Allah upon you when a people determined to extend their hands [in aggression] against you, but He withheld their hands from you; and fear Allah. And upon Allah let the believers rely.', NULL, NULL, 'ec46f266468312bef979f37e444671cd9cc9eb4005c01b345a2ba889350cc8b6'),
  ('en.sahih', 5, 12, 681, 'And Allah had already taken a covenant from the Children of Israel, and We delegated from among them twelve leaders. And Allah said, "I am with you. If you establish prayer and give zakah and believe in My messengers and support them and loan Allah a goodly loan, I will surely remove from you your misdeeds and admit you to gardens beneath which rivers flow. But whoever of you disbelieves after that has certainly strayed from the soundness of the way."', NULL, NULL, '38f2d86173f167c17b0bd0776650c14be5863fa9ef9838a6dfd0ebf7356730ee'),
  ('en.sahih', 5, 13, 682, 'So for their breaking of the covenant We cursed them and made their hearts hard. They distort words from their [proper] usages and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allah loves the doers of good.', NULL, NULL, '480058f8d2e8b6848bcab3df7d9a6da7177de021ad04b6bf2aa3e7f133afc46d'),
  ('en.sahih', 5, 14, 683, 'And from those who say, "We are Christians" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allah is going to inform them about what they used to do.', NULL, NULL, '9d009f426778507aae450ca7d496f61baf3ed0c6f8451dc93299d5afcb44974c'),
  ('en.sahih', 5, 15, 684, 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book.', NULL, NULL, '051c3f6a1c7e2b4941bbb9c37c61180381e732b6dd78a017a82df2e8f7966d0d'),
  ('en.sahih', 5, 16, 685, 'By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.', NULL, NULL, 'e37b9355da5220518e85b0dc990a080ff4ea5de482b6bb223f80a25c2718f79a'),
  ('en.sahih', 5, 17, 686, 'They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, "Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent.', NULL, NULL, '81032972527a0cd79affc9cd142dc6f6f0d9782ed319fb306fdc8380bd0d4608'),
  ('en.sahih', 5, 18, 687, 'But the Jews and the Christians say, "We are the children of Allah and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.', NULL, NULL, '70dc329f2e24119cbce946966891ac8a8f14c180249ab9316d7152bb8d2bce19'),
  ('en.sahih', 5, 19, 688, 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent.', NULL, NULL, '7de02500c712a17d5796ebec3ad60bcbaf321683b1942cc3e74ef4c271430036'),
  ('en.sahih', 5, 20, 689, 'And [mention, O Muhammad], when Moses said to his people, "O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.', NULL, NULL, '0cc1d21c7fc8dfc59215bc3cea4c91326e70bccb5188ee784a424aef80003192'),
  ('en.sahih', 5, 21, 690, 'O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah ''s cause] and [thus] become losers."', NULL, NULL, '0786d7ca62f7992fabdac6ee5afe7639a311b80735565a1998b7f4023f7bc812'),
  ('en.sahih', 5, 22, 691, 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."', NULL, NULL, '6e6206c2ff9d36c883db97adc8a0529cb801527f24389b08b40134c6beaa5dc5'),
  ('en.sahih', 5, 23, 692, 'Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers."', NULL, NULL, '7268cb813d20cc13e99420b01ed0c95192c2d6229f7a2c8519ad06f251828f76'),
  ('en.sahih', 5, 24, 693, 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."', NULL, NULL, '8d33d94e17b0e2898666dac27bc0b041f6267d53c7e2fca6b62e3c4d846b7e74'),
  ('en.sahih', 5, 25, 694, '[Moses] said, "My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people."', NULL, NULL, '1a2fd627ab15baa39b49f4f8026cb748bce5bdcbe8b05e18b3c154bdc89f70c0'),
  ('en.sahih', 5, 26, 695, '[Allah] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."', NULL, NULL, '0f1d2f71d0ebaffb09f9da0e5398db85e12c325d785b821853a4fbaadcb9983e'),
  ('en.sahih', 5, 27, 696, 'And recite to them the story of Adam''s two sons, in truth, when they both offered a sacrifice [to Allah], and it was accepted from one of them but was not accepted from the other. Said [the latter], "I will surely kill you." Said [the former], "Indeed, Allah only accepts from the righteous [who fear Him].', NULL, NULL, '359bdf7074392bf9e5901b525d7d0bc1a59e9975ed1bc60185a7b0f4d021f406'),
  ('en.sahih', 5, 28, 697, 'If you should raise your hand against me to kill me - I shall not raise my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds.', NULL, NULL, '64b897aa7f34d3be1fce8e082940ec5db15a79a181fad926219e7cf7e12db62d'),
  ('en.sahih', 5, 29, 698, 'Indeed I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of wrongdoers."', NULL, NULL, '7bdb6cc2486016bcf219c834c40516827960efdc99101d403c5958fe7f71fcef'),
  ('en.sahih', 5, 30, 699, 'And his soul permitted to him the murder of his brother, so he killed him and became among the losers.', NULL, NULL, 'bb63ea1a91f987b71fd8914c84f7e2d0b5d43dbefb3c324ec530079231ad23ae'),
  ('en.sahih', 5, 31, 700, 'Then Allah sent a crow searching in the ground to show him how to hide the disgrace of his brother. He said, "O woe to me! Have I failed to be like this crow and hide the body of my brother?" And he became of the regretful.', NULL, NULL, '14d833cdfe9b6cfbfc53b7d894d98771d80d7da2b4519e52df2091737684f488')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 5, 32, 701, 'Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land - it is as if he had slain mankind entirely. And whoever saves one - it is as if he had saved mankind entirely. And our messengers had certainly come to them with clear proofs. Then indeed many of them, [even] after that, throughout the land, were transgressors.', NULL, NULL, 'dfe3a2adf9d9de779b7d51c30a4d82ba69cc4eb846e79ea8fa009737b3b55ea1'),
  ('en.sahih', 5, 33, 702, 'Indeed, the penalty for those who wage war against Allah and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,', NULL, NULL, '63dd4f57f4ff76b025e7db54ff9403a45cf3f0bcce80ca0658c91bddc863c88f'),
  ('en.sahih', 5, 34, 703, 'Except for those who return [repenting] before you apprehend them. And know that Allah is Forgiving and Merciful.', NULL, NULL, 'd9fb6b2e10ca8a3b43afff3790dae616fc770e3aabe3174f0014538cc56d4072'),
  ('en.sahih', 5, 35, 704, 'O you who have believed, fear Allah and seek the means [of nearness] to Him and strive in His cause that you may succeed.', NULL, NULL, 'ec1276ad9060e9e482fb6f83e519fc41be691eee462394e01fda4b357b892b8e'),
  ('en.sahih', 5, 36, 705, 'Indeed, those who disbelieve - if they should have all that is in the earth and the like of it with it by which to ransom themselves from the punishment of the Day of Resurrection, it will not be accepted from them, and for them is a painful punishment', NULL, NULL, 'ee1786994515120838a9fc7709a8a79d0b9ac0d14e968b968d5137c046a07bcd'),
  ('en.sahih', 5, 37, 706, 'They will wish to get out of the Fire, but never are they to emerge therefrom, and for them is an enduring punishment.', NULL, NULL, '732378336dc391048dfbbd4fc84c600ea31dde44a9f7ac65e8eeacc10f0a4ded'),
  ('en.sahih', 5, 38, 707, '[As for] the thief, the male and the female, amputate their hands in recompense for what they committed as a deterrent [punishment] from Allah. And Allah is Exalted in Might and Wise.', NULL, NULL, 'f72cd7f3f06f0215e1920962c9395006c398c7474eef249bb62cfd8091fdee3f'),
  ('en.sahih', 5, 39, 708, 'But whoever repents after his wrongdoing and reforms, indeed, Allah will turn to him in forgiveness. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '10d559ba2f1be6ad8bf2fa5eb0b22fa9f893709b424991e239c060e7b613edd1'),
  ('en.sahih', 5, 40, 709, 'Do you not know that to Allah belongs the dominion of the heavens and the earth? He punishes whom He wills and forgives whom He wills, and Allah is over all things competent.', NULL, NULL, '86d590b0dde9b24a78ff3ba4f1cfff1e0a7ad777420b4a5880db26d29b29d1f9'),
  ('en.sahih', 5, 41, 710, 'O Messenger, let them not grieve you who hasten into disbelief of those who say, "We believe" with their mouths, but their hearts believe not, and from among the Jews. [They are] avid listeners to falsehood, listening to another people who have not come to you. They distort words beyond their [proper] usages, saying "If you are given this, take it; but if you are not given it, then beware." But he for whom Allah intends fitnah - never will you possess [power to do] for him a thing against Allah. Those are the ones for whom Allah does not intend to purify their hearts. For them in this world is disgrace, and for them in the Hereafter is a great punishment.', NULL, NULL, '6ac1dc4fc7fe4158bff16a115cebb1bcf4360fb3fff2c3f00affe6712ed4da1c'),
  ('en.sahih', 5, 42, 711, '[They are] avid listeners to falsehood, devourers of [what is] unlawful. So if they come to you, [O Muhammad], judge between them or turn away from them. And if you turn away from them - never will they harm you at all. And if you judge, judge between them with justice. Indeed, Allah loves those who act justly.', NULL, NULL, '1328f192b803011598e1b5bde382b8f63b7291482ed916aa2a19cafbf2e6f7ff'),
  ('en.sahih', 5, 43, 712, 'But how is it that they come to you for judgement while they have the Torah, in which is the judgement of Allah? Then they turn away, [even] after that; but those are not [in fact] believers.', NULL, NULL, 'a68a1f38df67f967f24b170e3384a4654a1d9c41152b14773323a79e22617004'),
  ('en.sahih', 5, 44, 713, 'Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allah] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allah, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price. And whoever does not judge by what Allah has revealed - then it is those who are the disbelievers.', NULL, NULL, 'e7014bc7e6529e66485c835544594e544746e3ce584a3d6e0aa2e3055681be02'),
  ('en.sahih', 5, 45, 714, 'And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allah has revealed - then it is those who are the wrongdoers.', NULL, NULL, '7af0266ba535d9c8b91dde71e1d82c9305cdc57b15af3e5aed44408c872d09f3'),
  ('en.sahih', 5, 46, 715, 'And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous.', NULL, NULL, '6d63279fb430d38c39dd41e293d4c068daabdf13907a496c80452ff2c2a2f8a9'),
  ('en.sahih', 5, 47, 716, 'And let the People of the Gospel judge by what Allah has revealed therein. And whoever does not judge by what Allah has revealed - then it is those who are the defiantly disobedient.', NULL, NULL, '719fd328d0bd9a18433647f1e828daf265c394b4d00e286b11da98ca3754f9cc'),
  ('en.sahih', 5, 48, 717, 'And We have revealed to you, [O Muhammad], the Book in truth, confirming that which preceded it of the Scripture and as a criterion over it. So judge between them by what Allah has revealed and do not follow their inclinations away from what has come to you of the truth. To each of you We prescribed a law and a method. Had Allah willed, He would have made you one nation [united in religion], but [He intended] to test you in what He has given you; so race to [all that is] good. To Allah is your return all together, and He will [then] inform you concerning that over which you used to differ.', NULL, NULL, '14538477e54d19402978f1bf40ecf2aad8cfae745ed0e1d7298d0e4f5743a5aa'),
  ('en.sahih', 5, 49, 718, 'And judge, [O Muhammad], between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you. And if they turn away - then know that Allah only intends to afflict them with some of their [own] sins. And indeed, many among the people are defiantly disobedient.', NULL, NULL, '46266564c3c22e9bb0c7b4ab1737c09a91c6180bf1367846ba3619e754928086'),
  ('en.sahih', 5, 50, 719, 'Then is it the judgement of [the time of] ignorance they desire? But who is better than Allah in judgement for a people who are certain [in faith].', NULL, NULL, '8a7586b846da5a47c5c6881a97a57d3eee079dbbd7ea4cb20dbc6c64d8fea5c2'),
  ('en.sahih', 5, 51, 720, 'O you who have believed, do not take the Jews and the Christians as allies. They are [in fact] allies of one another. And whoever is an ally to them among you - then indeed, he is [one] of them. Indeed, Allah guides not the wrongdoing people.', NULL, NULL, 'f7eb09f02b82683718cb22ec3747be97989a8fd06d6bd32a4a0ae1ce2d63594a'),
  ('en.sahih', 5, 52, 721, 'So you see those in whose hearts is disease hastening into [association with] them, saying, "We are afraid a misfortune may strike us." But perhaps Allah will bring conquest or a decision from Him, and they will become, over what they have been concealing within themselves, regretful.', NULL, NULL, 'ba32f91a9d8b38d8f90dbc0d62938ade0a93739a04ed2de26c144b3628fd2f72'),
  ('en.sahih', 5, 53, 722, 'And those who believe will say, "Are these the ones who swore by Allah their strongest oaths that indeed they were with you?" Their deeds have become worthless, and they have become losers.', NULL, NULL, '8a6b62a2923a74720b73bb65d8de28b66ebccc5798f25c5c976566cdbf2e2d45'),
  ('en.sahih', 5, 54, 723, 'O you who have believed, whoever of you should revert from his religion - Allah will bring forth [in place of them] a people He will love and who will love Him [who are] humble toward the believers, powerful against the disbelievers; they strive in the cause of Allah and do not fear the blame of a critic. That is the favor of Allah; He bestows it upon whom He wills. And Allah is all-Encompassing and Knowing.', NULL, NULL, '5fee9f3434a17f48eb9e12d058cc03961f6ad542d045a66b58accc0da65e6aeb'),
  ('en.sahih', 5, 55, 724, 'Your ally is none but Allah and [therefore] His Messenger and those who have believed - those who establish prayer and give zakah, and they bow [in worship].', NULL, NULL, '463cb5c4b2fa5f72556525b258014d5a982c66e7d6551c05c811af7694e5db1c'),
  ('en.sahih', 5, 56, 725, 'And whoever is an ally of Allah and His Messenger and those who have believed - indeed, the party of Allah - they will be the predominant.', NULL, NULL, '29f46a3455e92dfdd606dcebb9ef395734548a3afff287925086a9828c34f91f'),
  ('en.sahih', 5, 57, 726, 'O you who have believed, take not those who have taken your religion in ridicule and amusement among the ones who were given the Scripture before you nor the disbelievers as allies. And fear Allah, if you should [truly] be believers.', NULL, NULL, '491b69144a9c663a86f546cf5b33a59e299ea175a2700f15d964f15cbae46e9f'),
  ('en.sahih', 5, 58, 727, 'And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason.', NULL, NULL, '141d81b2dcef60fa1fc0cfbe1a5cefb8d9aadca6a5bd36c59881f9e0092532d5'),
  ('en.sahih', 5, 59, 728, 'Say, "O People of the Scripture, do you resent us except [for the fact] that we have believed in Allah and what was revealed to us and what was revealed before and because most of you are defiantly disobedient?"', NULL, NULL, '7b563ac9eb528ee0a0340b1bd72a53b3b9a2e9488ef79a6c1c3a12be12ccc2f9'),
  ('en.sahih', 5, 60, 729, 'Say, "Shall I inform you of [what is] worse than that as penalty from Allah? [It is that of] those whom Allah has cursed and with whom He became angry and made of them apes and pigs and slaves of Taghut. Those are worse in position and further astray from the sound way."', NULL, NULL, '79fdbb750cb7d143829b6db1e011bfea2fa2c5a801be81521400e9c3281c1a3b'),
  ('en.sahih', 5, 61, 730, 'And when they come to you, they say, "We believe." But they have entered with disbelief [in their hearts], and they have certainly left with it. And Allah is most knowing of what they were concealing.', NULL, NULL, 'f67dbe477ca51df2414943667980f21a306a54752e17ad12674d2605e14f6e87'),
  ('en.sahih', 5, 62, 731, 'And you see many of them hastening into sin and aggression and the devouring of [what is] unlawful. How wretched is what they have been doing.', NULL, NULL, '7ac28c3351de848d9cb1b85bc2e6084099225c8f9cc4fe070385948fd46d25d2'),
  ('en.sahih', 5, 63, 732, 'Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing.', NULL, NULL, '170a9074da8b6ae8caa10f23af00337a4e8b78542b88d4e66c836acbd95eedca'),
  ('en.sahih', 5, 64, 733, 'And the Jews say, "The hand of Allah is chained." Chained are their hands, and cursed are they for what they say. Rather, both His hands are extended; He spends however He wills. And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. And We have cast among them animosity and hatred until the Day of Resurrection. Every time they kindled the fire of war [against you], Allah extinguished it. And they strive throughout the land [causing] corruption, and Allah does not like corrupters.', NULL, NULL, '050787424e011697bad84b55ccf8e7dce5ab0edf6898ca8af4a582a5a7269fa0'),
  ('en.sahih', 5, 65, 734, 'And if only the People of the Scripture had believed and feared Allah, We would have removed from them their misdeeds and admitted them to Gardens of Pleasure.', NULL, NULL, '1404ea0a9bf9b0bdd507880add942c9ff6d89bf418fa514f0b308b5775bfa7eb'),
  ('en.sahih', 5, 66, 735, 'And if only they upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord, they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate community, but many of them - evil is that which they do.', NULL, NULL, '5565c9747dac547d5ddab627652033cd3462f3184815315771017049c60292a6'),
  ('en.sahih', 5, 67, 736, 'O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allah will protect you from the people. Indeed, Allah does not guide the disbelieving people.', NULL, NULL, 'acc853c7bb1fa7e82110c425bd2cd78e5f232da2c772acf3074319e7460379c6'),
  ('en.sahih', 5, 68, 737, 'Say, "O People of the Scripture, you are [standing] on nothing until you uphold [the law of] the Torah, the Gospel, and what has been revealed to you from your Lord." And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. So do not grieve over the disbelieving people.', NULL, NULL, 'a376ce4d0b54e64de920783694e0aecfb9c63ceb17cbc35364d8f706f168fb9b'),
  ('en.sahih', 5, 69, 738, 'Indeed, those who have believed [in Prophet Muhammad] and those [before Him] who were Jews or Sabeans or Christians - those [among them] who believed in Allah and the Last Day and did righteousness - no fear will there be concerning them, nor will they grieve.', NULL, NULL, 'f01c26d3bce9c6a934147a18c8ac49f639812deea6470620e390de7f1672b204'),
  ('en.sahih', 5, 70, 739, 'We had already taken the covenant of the Children of Israel and had sent to them messengers. Whenever there came to them a messenger with what their souls did not desire, a party [of messengers] they denied, and another party they killed.', NULL, NULL, 'abadf8ae8b3e8672b217cc2648a5cfeeba3378b4c6cad080430eca1a1f917af7'),
  ('en.sahih', 5, 71, 740, 'And they thought there would be no [resulting] punishment, so they became blind and deaf. Then Allah turned to them in forgiveness; then [again] many of them became blind and deaf. And Allah is Seeing of what they do.', NULL, NULL, 'd1bc8490481bf5dc54e59c259beb0b33cad69ecf116844023b5e02b3fcd3f934'),
  ('en.sahih', 5, 72, 741, 'They have certainly disbelieved who say, "Allah is the Messiah, the son of Mary" while the Messiah has said, "O Children of Israel, worship Allah, my Lord and your Lord." Indeed, he who associates others with Allah - Allah has forbidden him Paradise, and his refuge is the Fire. And there are not for the wrongdoers any helpers.', NULL, NULL, '1b17e97ead9600630bc38861963e5c75b55e512dcec004c4645923e3a5e39618'),
  ('en.sahih', 5, 73, 742, 'They have certainly disbelieved who say, "Allah is the third of three." And there is no god except one God. And if they do not desist from what they are saying, there will surely afflict the disbelievers among them a painful punishment.', NULL, NULL, 'f8780bd10854cb0df2de8ec8c77664772633fe729152ea07d13ae93b7e2894de'),
  ('en.sahih', 5, 74, 743, 'So will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful.', NULL, NULL, '3e2870e0846d5a18662259853c12c19c6a67635b103f528022193bba83f3a52c'),
  ('en.sahih', 5, 75, 744, 'The Messiah, son of Mary, was not but a messenger; [other] messengers have passed on before him. And his mother was a supporter of truth. They both used to eat food. Look how We make clear to them the signs; then look how they are deluded.', NULL, NULL, 'bec7f26771cf440559d2a5035505cecd8af77dffe3df2d700a746b85cb121487'),
  ('en.sahih', 5, 76, 745, 'Say, "Do you worship besides Allah that which holds for you no [power of] harm or benefit while it is Allah who is the Hearing, the Knowing?"', NULL, NULL, '022fa1e70c19c365edc66af64693bc6459af498462be66f3703a63773184cec4'),
  ('en.sahih', 5, 77, 746, 'Say, "O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way."', NULL, NULL, '44f197b589dd33fff969be4c6a94e5326c9afabe09ec163df617971841a0ab1d'),
  ('en.sahih', 5, 78, 747, 'Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed.', NULL, NULL, 'e3d30ed42cd033fb6b8cfa9e3ef24e679d752dd887c77e505e4508e814889a2a'),
  ('en.sahih', 5, 79, 748, 'They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing.', NULL, NULL, 'd19342c82df6c764eb75697ba49f3c9fe4153be59da86930378e0dbee0222019'),
  ('en.sahih', 5, 80, 749, 'You see many of them becoming allies of those who disbelieved. How wretched is that which they have put forth for themselves in that Allah has become angry with them, and in the punishment they will abide eternally.', NULL, NULL, 'e97bc15aae2c188da80210d8ef3214a231f7dddf77e8aa06713f68b0157b662f'),
  ('en.sahih', 5, 81, 750, 'And if they had believed in Allah and the Prophet and in what was revealed to him, they would not have taken them as allies; but many of them are defiantly disobedient.', NULL, NULL, 'dd9dfd0ba07953cd87427bfc18abe6fa89f56415715d0bdc71cb9325b101fb01'),
  ('en.sahih', 5, 82, 751, 'You will surely find the most intense of the people in animosity toward the believers [to be] the Jews and those who associate others with Allah; and you will find the nearest of them in affection to the believers those who say, "We are Christians." That is because among them are priests and monks and because they are not arrogant.', NULL, NULL, 'c8e82bfb99f7a833cbd32482d083379cd172121c45b0a95a4c60f096812383b1'),
  ('en.sahih', 5, 83, 752, 'And when they hear what has been revealed to the Messenger, you see their eyes overflowing with tears because of what they have recognized of the truth. They say, "Our Lord, we have believed, so register us among the witnesses.', NULL, NULL, '3fe93663e590d8044916b7b4be03c013928950b0397dd99e84725abcba4295b8'),
  ('en.sahih', 5, 84, 753, 'And why should we not believe in Allah and what has come to us of the truth? And we aspire that our Lord will admit us [to Paradise] with the righteous people."', NULL, NULL, '6432fbca3f5286cdebefb0a06ea4a26a4336b08229a6f7496c00da8ae6d31944'),
  ('en.sahih', 5, 85, 754, 'So Allah rewarded them for what they said with gardens [in Paradise] beneath which rivers flow, wherein they abide eternally. And that is the reward of doers of good.', NULL, NULL, '92809a7d23e3dd978f10f6619f09af6ef6fbbeea617328e244cc9b0d74917699'),
  ('en.sahih', 5, 86, 755, 'But those who disbelieved and denied Our signs - they are the companions of Hellfire.', NULL, NULL, '961aece00940159621288d14cd1e32c2aad42d3d7435c934376ada2ffb87aa76'),
  ('en.sahih', 5, 87, 756, 'O you who have believed, do not prohibit the good things which Allah has made lawful to you and do not transgress. Indeed, Allah does not like transgressors.', NULL, NULL, '29f9d55bba3d269af529ff180419be38f1db2a738ad44f66cf46a7afd90ade36'),
  ('en.sahih', 5, 88, 757, 'And eat of what Allah has provided for you [which is] lawful and good. And fear Allah, in whom you are believers.', NULL, NULL, 'f230c4e466c39506cc619f12e82f925a5107f7140d9002acea9b06de8acea37f'),
  ('en.sahih', 5, 89, 758, 'Allah will not impose blame upon you for what is meaningless in your oaths, but He will impose blame upon you for [breaking] what you intended of oaths. So its expiation is the feeding of ten needy people from the average of that which you feed your [own] families or clothing them or the freeing of a slave. But whoever cannot find [or afford it] - then a fast of three days [is required]. That is the expiation for oaths when you have sworn. But guard your oaths. Thus does Allah make clear to you His verses that you may be grateful.', NULL, NULL, 'a6ebe3603f2cc18486a4bdb86e0eaae3e101aad9dc4b17768a5aa3786926674b'),
  ('en.sahih', 5, 90, 759, 'O you who have believed, indeed, intoxicants, gambling, [sacrificing on] stone alters [to other than Allah], and divining arrows are but defilement from the work of Satan, so avoid it that you may be successful.', NULL, NULL, '1c6928be67027c49762ee6d71604f075830e3cc7ad73ca541becad37e0dacfd3'),
  ('en.sahih', 5, 91, 760, 'Satan only wants to cause between you animosity and hatred through intoxicants and gambling and to avert you from the remembrance of Allah and from prayer. So will you not desist?', NULL, NULL, 'f7f5a494a8d54914dc7027aa781eecf584b0a6066e40c73f6c639edd71f912f2'),
  ('en.sahih', 5, 92, 761, 'And obey Allah and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification.', NULL, NULL, '49eda8ba6a21f4c61d48b6a19e7a7753ed6987167c6e2c813f13b7b772840b07'),
  ('en.sahih', 5, 93, 762, 'There is not upon those who believe and do righteousness [any] blame concerning what they have eaten [in the past] if they [now] fear Allah and believe and do righteous deeds, and then fear Allah and believe, and then fear Allah and do good; and Allah loves the doers of good.', NULL, NULL, '45740bbaaf84e4b68623204b339a02754277d5a177cc5f99cc436a608995816e'),
  ('en.sahih', 5, 94, 763, 'O you who have believed, Allah will surely test you through something of the game that your hands and spears [can] reach, that Allah may make evident those who fear Him unseen. And whoever transgresses after that - for him is a painful punishment.', NULL, NULL, '7eaaeca4df810a593530124328252d1940bfe6abf3b4732e63f5a8d498728104'),
  ('en.sahih', 5, 95, 764, 'O you who have believed, do not kill game while you are in the state of ihram. And whoever of you kills it intentionally - the penalty is an equivalent from sacrificial animals to what he killed, as judged by two just men among you as an offering [to Allah] delivered to the Ka''bah, or an expiation: the feeding of needy people or the equivalent of that in fasting, that he may taste the consequence of his deed. Allah has pardoned what is past; but whoever returns [to violation], then Allah will take retribution from him. And Allah is Exalted in Might and Owner of Retribution.', NULL, NULL, '297b99b9255bd2368c6c1a1ad73e08e1d50d77041660dbe65fbf64ad05cc616b'),
  ('en.sahih', 5, 96, 765, 'Lawful to you is game from the sea and its food as provision for you and the travelers, but forbidden to you is game from the land as long as you are in the state of ihram. And fear Allah to whom you will be gathered.', NULL, NULL, 'a52b4827d631c77b475527f9886c53cf798456412bd1026b87f3b368378435b0'),
  ('en.sahih', 5, 97, 766, 'Allah has made the Ka''bah, the Sacred House, standing for the people and [has sanctified] the sacred months and the sacrificial animals and the garlands [by which they are identified]. That is so you may know that Allah knows what is in the heavens and what is in the earth and that Allah is Knowing of all things.', NULL, NULL, '2fbbf433fd75fc1cb4a77724c32b2ed83e3d4e91affb79e9a36f7842cba4b77d'),
  ('en.sahih', 5, 98, 767, 'Know that Allah is severe in penalty and that Allah is Forgiving and Merciful.', NULL, NULL, '192f6993ed735a81b7fa39d1c702dddf4389efc974bfff78fb4586daf976a594'),
  ('en.sahih', 5, 99, 768, 'Not upon the Messenger is [responsibility] except [for] notification. And Allah knows whatever you reveal and whatever you conceal.', NULL, NULL, 'c5c4d3ca266486ddf28d32eec3c8970c25c73f24af7bc0a6620c5f34733ea744'),
  ('en.sahih', 5, 100, 769, 'Say, "Not equal are the evil and the good, although the abundance of evil might impress you." So fear Allah, O you of understanding, that you may be successful.', NULL, NULL, '3a0533a2951a635f21bcd3458efce216e4234f71630d2fac77e683451f980cfb'),
  ('en.sahih', 5, 101, 770, 'O you who have believed, do not ask about things which, if they are shown to you, will distress you. But if you ask about them while the Qur''an is being revealed, they will be shown to you. Allah has pardoned that which is past; and Allah is Forgiving and Forbearing.', NULL, NULL, '68f66d38f7eb2ce5c3bc4c729030cd36137521bcc0f07f88b0806e00b13b3fc9'),
  ('en.sahih', 5, 102, 771, 'A people asked such [questions] before you; then they became thereby disbelievers.', NULL, NULL, '37bd8156d322c2fa748c3d5f98f97875b995f32a179f9974172f72400f6c829e'),
  ('en.sahih', 5, 103, 772, 'Allah has not appointed [such innovations as] bahirah or sa''ibah or wasilah or ham. But those who disbelieve invent falsehood about Allah, and most of them do not reason.', NULL, NULL, '269c8e9f2c163eee8beb5467fba8c4b62101de62631856e93415c593341d232d'),
  ('en.sahih', 5, 104, 773, 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," they say, "Sufficient for us is that upon which we found our fathers." Even though their fathers knew nothing, nor were they guided?', NULL, NULL, '322987351c1bab4921224ead3813ce1c53ffc03928714b2323c7405c17b2b959'),
  ('en.sahih', 5, 105, 774, 'O you who have believed, upon you is [responsibility for] yourselves. Those who have gone astray will not harm you when you have been guided. To Allah is you return all together; then He will inform you of what you used to do.', NULL, NULL, '22f2157d8910e52474cc7401ea8bd37a6442d31d7d0bf2d893e12c8299e48d90'),
  ('en.sahih', 5, 106, 775, 'O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allah if you doubt [their testimony, saying], "We will not exchange our oath for a price, even if he should be a near relative, and we will not withhold the testimony of Allah. Indeed, we would then be of the sinful."', NULL, NULL, '26121915a88cdb89af27b5af98885274504c8738df21616ca3e4ee9d48ea4288'),
  ('en.sahih', 5, 107, 776, 'But if it is found that those two were guilty of perjury, let two others stand in their place [who are] foremost [in claim] from those who have a lawful right. And let them swear by Allah, "Our testimony is truer than their testimony, and we have not transgressed. Indeed, we would then be of the wrongdoers."', NULL, NULL, '97c3aedc04a504a3873733249cb25bdea3b17ffa64baeff138a2ebc06aa54a9e'),
  ('en.sahih', 5, 108, 777, 'That is more likely that they will give testimony according to its [true] objective, or [at least] they would fear that [other] oaths might be taken after their oaths. And fear Allah and listen; and Allah does not guide the defiantly disobedient people.', NULL, NULL, 'ca93e7e49c0c221420d720a3d0001aa64bebebd9ab3b9208818d8b8d4949aa64'),
  ('en.sahih', 5, 109, 778, '[Be warned of] the Day when Allah will assemble the messengers and say, "What was the response you received?" They will say, "We have no knowledge. Indeed, it is You who is Knower of the unseen"', NULL, NULL, 'c8b155b924e0eb6c9ed155a75574a17318102a3eb879b7b6e774d81d51629cb1'),
  ('en.sahih', 5, 110, 779, '[The Day] when Allah will say, "O Jesus, Son of Mary, remember My favor upon you and upon your mother when I supported you with the Pure Spirit and you spoke to the people in the cradle and in maturity; and [remember] when I taught you writing and wisdom and the Torah and the Gospel; and when you designed from clay [what was] like the form of a bird with My permission, then you breathed into it, and it became a bird with My permission; and you healed the blind and the leper with My permission; and when you brought forth the dead with My permission; and when I restrained the Children of Israel from [killing] you when you came to them with clear proofs and those who disbelieved among them said, "This is not but obvious magic."', NULL, NULL, '985b2360612f43d9ef2601b2ea32a00fb3b3d61de5f50743ef9d551ebacd1e4d'),
  ('en.sahih', 5, 111, 780, 'And [remember] when I inspired to the disciples, "Believe in Me and in My messenger Jesus." They said, "We have believed, so bear witness that indeed we are Muslims [in submission to Allah]."', NULL, NULL, '442a7114aeb0a1a1815c33c19b5051e6052e0cac8f23f1afa0b8eb5dd9827bf7'),
  ('en.sahih', 5, 112, 781, '[And remember] when the disciples said, "O Jesus, Son of Mary, can your Lord send down to us a table [spread with food] from the heaven? [Jesus] said," Fear Allah, if you should be believers."', NULL, NULL, '3e7feb050d17449625439540a43e1f180092858cc658ad067444dee3bb4431b2'),
  ('en.sahih', 5, 113, 782, 'They said, "We wish to eat from it and let our hearts be reassured and know that you have been truthful to us and be among its witnesses."', NULL, NULL, '9642bfb70274e423cc8103f988f556ce453ea7b22af4bdba6f1b7347b3ac6c95'),
  ('en.sahih', 5, 114, 783, 'Said Jesus, the son of Mary, "O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers."', NULL, NULL, 'ab4a513549822e0764b7a5960840d40c5d8a57c17e874faffeb20e721e313277'),
  ('en.sahih', 5, 115, 784, 'Allah said, "Indeed, I will sent it down to you, but whoever disbelieves afterwards from among you - then indeed will I punish him with a punishment by which I have not punished anyone among the worlds."', NULL, NULL, '26120284ef4142a4dc8328c6abca342748221d87127793762ac32485764d7dc9'),
  ('en.sahih', 5, 116, 785, 'And [beware the Day] when Allah will say, "O Jesus, Son of Mary, did you say to the people, ''Take me and my mother as deities besides Allah?''" He will say, "Exalted are You! It was not for me to say that to which I have no right. If I had said it, You would have known it. You know what is within myself, and I do not know what is within Yourself. Indeed, it is You who is Knower of the unseen.', NULL, NULL, 'ac8da6a29dd709c316dc69d99c9dd1427dde05f0703ecd8a231dc7120a13816c'),
  ('en.sahih', 5, 117, 786, 'I said not to them except what You commanded me - to worship Allah, my Lord and your Lord. And I was a witness over them as long as I was among them; but when You took me up, You were the Observer over them, and You are, over all things, Witness.', NULL, NULL, '2e5d89cecc9b885c5e9c8d20a9a88d4f9cad9a3ee692481e8e58c990819a91ff'),
  ('en.sahih', 5, 118, 787, 'If You should punish them - indeed they are Your servants; but if You forgive them - indeed it is You who is the Exalted in Might, the Wise.', NULL, NULL, '132c7c03726792b28fb9bf63643bf8d058f624195be6a904cf710bd2c38d8ab4'),
  ('en.sahih', 5, 119, 788, 'Allah will say, "This is the Day when the truthful will benefit from their truthfulness." For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allah being pleased with them, and they with Him. That is the great attainment.', NULL, NULL, '49cbea31622575172d5a432b8da4e6dee8020d911a9aad59a01d0e186d74c7c6'),
  ('en.sahih', 5, 120, 789, 'To Allah belongs the dominion of the heavens and the earth and whatever is within them. And He is over all things competent.', NULL, NULL, '124c02db7866f7a70c16bd8ba6b36b2a3fe5b211b11bf12e94d23c6f6babac39'),
  ('en.sahih', 6, 1, 790, '[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.', NULL, NULL, '42bf2e6c5b176f1f52b2454cdaabbc4c9dad7003239e29355f5abe4265b85c6b'),
  ('en.sahih', 6, 2, 791, 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.', NULL, NULL, 'fe943457cae744a393b6c3d24c38d18d91c9881dca909827d21d2c3435ddd11b'),
  ('en.sahih', 6, 3, 792, 'And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.', NULL, NULL, '371d17371a1191c5207dd0b933ec1992dc98af05759cb1242cc45d76e1fb0566'),
  ('en.sahih', 6, 4, 793, 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.', NULL, NULL, '213a596c0fc8489d4f9f09bcb1f06a481037704c7e983f2d38b2e743723e1de5'),
  ('en.sahih', 6, 5, 794, 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.', NULL, NULL, 'd01dbab3032229e7e8d8cbd4ac4d8b923c697efe4d9f42daefa6b61bd52b53ef'),
  ('en.sahih', 6, 6, 795, 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.', NULL, NULL, '485d0e030e8d0361cdcd99bf535f54434f02e1ad9ee0643b640e9c34512ab1ef'),
  ('en.sahih', 6, 7, 796, 'And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."', NULL, NULL, '8f7d22a0867b9eec68f531bc4332ee318be06c2b237009dfd772c8607537abff'),
  ('en.sahih', 6, 8, 797, 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.', NULL, NULL, '8ebd8f1e4779d8d0dfa094ff7eff8787f28ca2ca15c37f19db0b055138856c66'),
  ('en.sahih', 6, 9, 798, 'And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves.', NULL, NULL, 'f4d6b6bc9f908541d695bec67f00f0fbc6b3c0a675ec34f7cb3f9478fa9fb84d'),
  ('en.sahih', 6, 10, 799, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.', NULL, NULL, '8c32df5456fb03f0585fe354e4e3624263d5c9910ee3001d26659a438d3b12ed'),
  ('en.sahih', 6, 11, 800, 'Say, "Travel through the land; then observe how was the end of the deniers."', NULL, NULL, '122d6880651f7c182ba1ada68c46cea0ea21be6a2e288deebbd8de7606e3598f')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 6, 12, 801, 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allah." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.', NULL, NULL, '81e1576e3cc73b22f005687595cf1faabc951a2bcb36fcaa1e6412c2de49e57e'),
  ('en.sahih', 6, 13, 802, 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.', NULL, NULL, '047d898c5edb26462534abdd8dfdb62ef1f9ae5487c98ffb6cb1cbcc01a5fb85'),
  ('en.sahih', 6, 14, 803, 'Say, "Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?" Say, [O Muhammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], ''Do not ever be of the polytheists.'' "', NULL, NULL, '435b96a5684b5a4dfce61b3bb2fe08ce2692e572fc9259caac6e8ff8b6e87a1d'),
  ('en.sahih', 6, 15, 804, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', NULL, NULL, '280f56573651c116aa611bde5937784253114a05e2b501c558b31f401296d6fc'),
  ('en.sahih', 6, 16, 805, 'He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.', NULL, NULL, '4769f1d15b7a5676358b0060fe548c49d862978e2d00be43ed9b7480dcac4772'),
  ('en.sahih', 6, 17, 806, 'And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.', NULL, NULL, '975f7af6739714862e9b8e6904550af83303bc652055f06caa990e9e457474d1'),
  ('en.sahih', 6, 18, 807, 'And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all].', NULL, NULL, '59971761402fb11dd00bda5a0799df0a9e5ec8687ba0de07c98922814eb15072'),
  ('en.sahih', 6, 19, 808, 'Say, "What thing is greatest in testimony?" Say, "Allah is witness between me and you. And this Qur''an was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allah there are other deities?" Say, "I will not testify [with you]." Say, "Indeed, He is but one God, and indeed, I am free of what you associate [with Him]."', NULL, NULL, 'afa0b69fa95fe149af3bdabdd5497dc10ff63e4963d4a1ba9247d5b50fe1fb57'),
  ('en.sahih', 6, 20, 809, 'Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe.', NULL, NULL, 'e847fd762b45b002bd5d52b6574ad426d84ffbf4efa10be5e879aa1418cd89fa'),
  ('en.sahih', 6, 21, 810, 'And who is more unjust than one who invents about Allah a lie or denies His verses? Indeed, the wrongdoers will not succeed.', NULL, NULL, 'a2ac82ac0b13bc7f53f50181165bd2452192f5f441f18d53c3e0881ba115ead0'),
  ('en.sahih', 6, 22, 811, 'And [mention, O Muhammad], the Day We will gather them all together; then We will say to those who associated others with Allah, "Where are your ''partners'' that you used to claim [with Him]?"', NULL, NULL, '058d00166b1a7abb93ab67c317dfa119b52078656327c8fc5fdead278d1436ed'),
  ('en.sahih', 6, 23, 812, 'Then there will be no [excuse upon] examination except they will say, "By Allah, our Lord, we were not those who associated."', NULL, NULL, '1ef19e6f04c78f46bd32a451bc61f23fc68b3d2be4de758afa17eb08938d25de'),
  ('en.sahih', 6, 24, 813, 'See how they will lie about themselves. And lost from them will be what they used to invent.', NULL, NULL, 'be4e67c8864e8a9437b95ba8f9d3226e139eca613f12e92ba0f60d0c5671ffaa'),
  ('en.sahih', 6, 25, 814, 'And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, "This is not but legends of the former peoples."', NULL, NULL, '639c17cb1de4a87227b1e2ffb358973eb416552d30f6c736dbaec72771e65a8c'),
  ('en.sahih', 6, 26, 815, 'And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not.', NULL, NULL, '57b6f57e1be929524ca0410248168a0c448a205135181d55274a604c38ef413a'),
  ('en.sahih', 6, 27, 816, 'If you could but see when they are made to stand before the Fire and will say, "Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers."', NULL, NULL, '1e7f32a97ffe3c0e56cb5c9b2cbb7489f2f26899b3bb9c8363b1504be47a5e28'),
  ('en.sahih', 6, 28, 817, 'But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars.', NULL, NULL, '2dff74f1a32ddd2488ec0c4286111658a4ee0433d6506e461deee2b5b241d65f'),
  ('en.sahih', 6, 29, 818, 'And they say, "There is none but our worldly life, and we will not be resurrected."', NULL, NULL, '877f0fda6a05d11c52f1910dcc559dc1f6e2bc6880c5bbcba97e2d2f4c99c73a'),
  ('en.sahih', 6, 30, 819, 'If you could but see when they will be made to stand before their Lord. He will say, "Is this not the truth?" They will say, "Yes, by our Lord." He will [then] say, "So taste the punishment because you used to disbelieve."', NULL, NULL, 'd1986a90de9bfeefe47478c75dd425a203577c6f77ab1ac83fd8ae5975324874'),
  ('en.sahih', 6, 31, 820, 'Those will have lost who deny the meeting with Allah, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, "Oh, [how great is] our regret over what we neglected concerning it," while they bear their burdens on their backs. Unquestionably, evil is that which they bear.', NULL, NULL, '9ffe13d73d576728d46b3a70722fb5610dad3e14f4e51a15e467be28e930016b'),
  ('en.sahih', 6, 32, 821, 'And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allah, so will you not reason?', NULL, NULL, '5af52fdaeae60cb4bdf186c0a97d8e62095a18f1499e500df851768377afb4e4'),
  ('en.sahih', 6, 33, 822, 'We know that you, [O Muhammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allah that the wrongdoers reject.', NULL, NULL, '99b61905a20978b8782f611402e8718c56b0cce7de8bc9094423566f0e290ed3'),
  ('en.sahih', 6, 34, 823, 'And certainly were messengers denied before you, but they were patient over [the effects of] denial, and they were harmed until Our victory came to them. And none can alter the words of Allah. And there has certainly come to you some information about the [previous] messengers.', NULL, NULL, 'd24d54d092c418f75fe198e3d99ad9ee64d6d3afe6dac71ff8b1297d65d8edf8'),
  ('en.sahih', 6, 35, 824, 'And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allah had willed, He would have united them upon guidance. So never be of the ignorant.', NULL, NULL, 'fffce7ad130252c293fb68a721774239b4d5619c08a18b3f2584736ab21d0e11'),
  ('en.sahih', 6, 36, 825, 'Only those who hear will respond. But the dead - Allah will resurrect them; then to Him they will be returned.', NULL, NULL, 'f13205c839e54c78f1fa44b419eaf4ed852e8bd15a6bc8f46d291451e2bd4f14'),
  ('en.sahih', 6, 37, 826, 'And they say, "Why has a sign not been sent down to him from his Lord?" Say, "Indeed, Allah is Able to send down a sign, but most of them do not know."', NULL, NULL, '41a5a5ed7b91274c75c23e979074b5b866918ef5716f3bb39146c81c7eafe397'),
  ('en.sahih', 6, 38, 827, 'And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered.', NULL, NULL, 'd353f0ff6b0d1f225502a0621082797dccc230366c63ae7fff947b0fb137df73'),
  ('en.sahih', 6, 39, 828, 'But those who deny Our verses are deaf and dumb within darknesses. Whomever Allah wills - He leaves astray; and whomever He wills - He puts him on a straight path.', NULL, NULL, 'f5e63bead91bd0479af4a3ceccab6563c0602caf639534cab78c2e278cfb3af1'),
  ('en.sahih', 6, 40, 829, 'Say, "Have you considered: if there came to you the punishment of Allah or there came to you the Hour - is it other than Allah you would invoke, if you should be truthful?"', NULL, NULL, '7686aa1125f6b1e628be10aa3f484e39ae37c573e716278fefd749ff18cd0a77'),
  ('en.sahih', 6, 41, 830, 'No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him].', NULL, NULL, '56a8eb19b2d29e64618977104680eb159c1278fce2f1b1904c3ff7ce5b2abbaa'),
  ('en.sahih', 6, 42, 831, 'And We have already sent [messengers] to nations before you, [O Muhammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us].', NULL, NULL, 'd73e1a851e06fbfe705fc42580ca281a13ec863c76fa5028ee37a5d51bededbe'),
  ('en.sahih', 6, 43, 832, 'Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing.', NULL, NULL, 'ffd32cf533ca90f4364bd39af75f34b89b659ee863a4cf700b45641a283ed6ea'),
  ('en.sahih', 6, 44, 833, 'So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.', NULL, NULL, '509b5dd23268a81600649d91bbfdad3b0014a8431722133dcd04dff4ecebc828'),
  ('en.sahih', 6, 45, 834, 'So the people that committed wrong were eliminated. And praise to Allah, Lord of the worlds.', NULL, NULL, '8db4ef0f973f28bb8e6c23d47beb8ba4428a120cd9d81c777626823120749f18'),
  ('en.sahih', 6, 46, 835, 'Say, "Have you considered: if Allah should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allah could bring them [back] to you?" Look how we diversify the verses; then they [still] turn away.', NULL, NULL, '0a0b65456e5f08bdd1d19aded321d0bd60f1434acbae884cfd6d36358b94dfee'),
  ('en.sahih', 6, 47, 836, 'Say, "Have you considered: if the punishment of Allah should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?"', NULL, NULL, '52781c7de7c6018e6ca7e0442bada071df5c5de9725afb6a03a837806961b76d'),
  ('en.sahih', 6, 48, 837, 'And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve.', NULL, NULL, '94e97001bb32224f743409f8faed59760a477bf7089746bbaba7568cab06e774'),
  ('en.sahih', 6, 49, 838, 'But those who deny Our verses - the punishment will touch them for their defiant disobedience.', NULL, NULL, 'a08875eb9ba4b833a84c0d4364a48beb0496e28f2a02e0a82843148ef9e2fb35'),
  ('en.sahih', 6, 50, 839, 'Say, [O Muhammad], "I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me." Say, "Is the blind equivalent to the seeing? Then will you not give thought?"', NULL, NULL, '0f3c460e1436f1bf2b393c5b349dfbb5457dcca8a0f3fb789920673a172c7669'),
  ('en.sahih', 6, 51, 840, 'And warn by the Qur''an those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous.', NULL, NULL, '91d5383fba76991ba261f2e08eb5b6160eeb12d843ec5ea1e86f7bb571886bc8'),
  ('en.sahih', 6, 52, 841, 'And do not send away those who call upon their Lord morning and afternoon, seeking His countenance. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers.', NULL, NULL, '889bca6fac6cafe92d6187f3b82026d012f0f79da5b92feb3b0ae1992a85516f'),
  ('en.sahih', 6, 53, 842, 'And thus We have tried some of them through others that the disbelievers might say, "Is it these whom Allah has favored among us?" Is not Allah most knowing of those who are grateful?', NULL, NULL, '54c8cf61ff6eb8f7a0a1f02f107062d8415ffb4ee1a876223bea9f8bba07f033'),
  ('en.sahih', 6, 54, 843, 'And when those come to you who believe in Our verses, say, "Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful."', NULL, NULL, '03361b6f4a13c65ebce867c8a70f1ff1b77f5af107b75376cdf16b6a11e92e39'),
  ('en.sahih', 6, 55, 844, 'And thus do We detail the verses, and [thus] the way of the criminals will become evident.', NULL, NULL, '6d091972310e9beb4f5ee9be8bff781155f36917f5d7bfd15ea2d3080a6e22fb'),
  ('en.sahih', 6, 56, 845, 'Say, "Indeed, I have been forbidden to worship those you invoke besides Allah." Say, "I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided."', NULL, NULL, 'f71ca3858301de46c151b17bc74bc9561b8ac79db858ad0542cd3727ea079c8a'),
  ('en.sahih', 6, 57, 846, 'Say, "Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allah. He relates the truth, and He is the best of deciders."', NULL, NULL, '38595cc9be3b3ebe23bfb7f9998c3e7b52b5e5e1cc3d81d3489cd07eb1aea859'),
  ('en.sahih', 6, 58, 847, 'Say, "If I had that for which you are impatient, the matter would have been decided between me and you, but Allah is most knowing of the wrongdoers."', NULL, NULL, 'c399c16c061a8fb01d94951ab76029b17a4534a922537126e693c3fcdddeed84'),
  ('en.sahih', 6, 59, 848, 'And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record.', NULL, NULL, '2d6fc40eefb6f1e07c9752a179dcdd50050e3e27730ef0f16a7cb4a8835cfb27'),
  ('en.sahih', 6, 60, 849, 'And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do.', NULL, NULL, '721e826c68aefadf955aaba3a23aae6b58c80abc4caba777d50c582bae37ed0a'),
  ('en.sahih', 6, 61, 850, 'And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers take him, and they do not fail [in their duties].', NULL, NULL, 'f006006b8696a3ccecdb43068cdb550697f790e851e86d9f9c2ea594913ec587'),
  ('en.sahih', 6, 62, 851, 'Then they His servants are returned to Allah, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants.', NULL, NULL, '636678e77d3791e0cab724df8a5548be69a1135a53a4f3d50df973f07df15964'),
  ('en.sahih', 6, 63, 852, 'Say, "Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, ''If He should save us from this [crisis], we will surely be among the thankful.'' "', NULL, NULL, '77bbb9cb71bc26875ebbf08092eef4c5bd580766d8df66da0d7dc71dc45996bc'),
  ('en.sahih', 6, 64, 853, 'Say, "It is Allah who saves you from it and from every distress; then you [still] associate others with Him."', NULL, NULL, '6ad4f18add9eb4758aaf22573b49861d4487db03aec64fe6ce33d1966acb9346'),
  ('en.sahih', 6, 65, 854, 'Say, "He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another." Look how We diversify the signs that they might understand.', NULL, NULL, '30406d9d413296f432224d52285522aed6832d3bcf646de36bfb347d9c7ea894'),
  ('en.sahih', 6, 66, 855, 'But your people have denied it while it is the truth. Say, "I am not over you a manager."', NULL, NULL, '952a86d0cbc541d8fb296292db3a392199f266196f8959cf34413ddf69c5806c'),
  ('en.sahih', 6, 67, 856, 'For every happening is a finality; and you are going to know.', NULL, NULL, '21002dce788b82ba652e836fcae7aeea28e0d0410ad2454ceeba4028fa2a1cbd'),
  ('en.sahih', 6, 68, 857, 'And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people.', NULL, NULL, '8f534a81e6dd9b8506b7855055407eca94b14829b7a44601b3dd9c47a2ae21ec'),
  ('en.sahih', 6, 69, 858, 'And those who fear Allah are not held accountable for the disbelievers at all, but [only for] a reminder - that perhaps they will fear Him.', NULL, NULL, 'bdf54ec033fc38b2e338f26f46cee49f9a199098d651ede9d5fef9b06c3a533d'),
  ('en.sahih', 6, 70, 859, 'And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with the Qur''an, lest a soul be given up to destruction for what it earned; it will have other than Allah no protector and no intercessor. And if it should offer every compensation, it would not be taken from it. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve.', NULL, NULL, 'ef84000b42cbfdb74c69fad5d8e23faf602f0018b747467dd2ae2cd8abcf4199'),
  ('en.sahih', 6, 71, 860, 'Say, "Shall we invoke instead of Allah that which neither benefits us nor harms us and be turned back on our heels after Allah has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], ''Come to us.'' " Say, "Indeed, the guidance of Allah is the [only] guidance; and we have been commanded to submit to the Lord of the worlds.', NULL, NULL, '5d6b816bcbeea37a4aa472caf3829d1ef9142d0bd1ff8c9f97d1aa6e0f90befb'),
  ('en.sahih', 6, 72, 861, 'And to establish prayer and fear Him." And it is He to whom you will be gathered.', NULL, NULL, '8e94af85df2355373844cbf66c07106320d0f8631a3093486b9754323d688c49'),
  ('en.sahih', 6, 73, 862, 'And it is He who created the heavens and earth in truth. And the day He says, "Be," and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Acquainted.', NULL, NULL, '41426b772f4d0a0264d9c7d1a766b924f203068e4697760def3c926abe848308'),
  ('en.sahih', 6, 74, 863, 'And [mention, O Muhammad], when Abraham said to his father Azar, "Do you take idols as deities? Indeed, I see you and your people to be in manifest error."', NULL, NULL, 'c0a278be8a8bd3620b9afbf0bc0b04745b51157017f179f1c27257efd852391f'),
  ('en.sahih', 6, 75, 864, 'And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith]', NULL, NULL, '0d643ac59e68e224d73cae1444ccb3e2d13e0bad279d48397d0c955556df46a2'),
  ('en.sahih', 6, 76, 865, 'So when the night covered him [with darkness], he saw a star. He said, "This is my lord." But when it set, he said, "I like not those that disappear."', NULL, NULL, '0ead52d4aabbb6d7fa3f83de0dd72607b793eb5c72c4c1430b5fd94da90be646'),
  ('en.sahih', 6, 77, 866, 'And when he saw the moon rising, he said, "This is my lord." But when it set, he said, "Unless my Lord guides me, I will surely be among the people gone astray."', NULL, NULL, 'ab62e13f943c790ad9bea33c3f1eaa2e4ac52752862e003d3f27996c605f157c'),
  ('en.sahih', 6, 78, 867, 'And when he saw the sun rising, he said, "This is my lord; this is greater." But when it set, he said, "O my people, indeed I am free from what you associate with Allah.', NULL, NULL, 'a0d091ffc956a2c98c8db52b3a979fb42502440cc945d34e8814389edfcad4fc'),
  ('en.sahih', 6, 79, 868, 'Indeed, I have turned my face toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allah."', NULL, NULL, '36260209d495eed262241e5dd4611a2396e53503b6e430b6808282fe1eecff64'),
  ('en.sahih', 6, 80, 869, 'And his people argued with him. He said, "Do you argue with me concerning Allah while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?', NULL, NULL, 'ee8a87ab44049a94155a6ed4b761501b4f0d11edbcb1594698dbdf322cffb0c0'),
  ('en.sahih', 6, 81, 870, 'And how should I fear what you associate while you do not fear that you have associated with Allah that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?', NULL, NULL, 'c0cd0f37a604d0cefcaf299a0c6a78c36dd2f10db9e970199d8ffead0b39493a'),
  ('en.sahih', 6, 82, 871, 'They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided.', NULL, NULL, 'dbf963c6f084d459f240d15360ff8df10a1f46096acf00009fa1942dbc8dea4a'),
  ('en.sahih', 6, 83, 872, 'And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing.', NULL, NULL, 'b9561ba21e7a7dfdfd87dc4b34280c2841e94836b410eace28fb3a65c965280e'),
  ('en.sahih', 6, 84, 873, 'And We gave to Abraham, Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good.', NULL, NULL, '129fbe416dd2945805f725a9c185d86a42bfdf94cbe76e5b8aa0097b38466a22'),
  ('en.sahih', 6, 85, 874, 'And Zechariah and John and Jesus and Elias - and all were of the righteous.', NULL, NULL, '195af218a8b6cb07b6c7d1dd5cda4ec2e6eda46d90fe9199813ad5a1e4bc09e1'),
  ('en.sahih', 6, 86, 875, 'And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds.', NULL, NULL, '6e6294f6a6713a0ced16d082714b1c5816f4f893c97e09f0b717cbe63b7143fe'),
  ('en.sahih', 6, 87, 876, 'And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.', NULL, NULL, '7a62a014e6ef5fad695508e6e1a2cb595a18c3e3932e092278ead5448ae86973'),
  ('en.sahih', 6, 88, 877, 'That is the guidance of Allah by which He guides whomever He wills of His servants. But if they had associated others with Allah, then worthless for them would be whatever they were doing.', NULL, NULL, 'e7f5d3a692b766d7ee711fa936b09a7c591a4949058483cf61b48742149aa398'),
  ('en.sahih', 6, 89, 878, 'Those are the ones to whom We gave the Scripture and authority and prophethood. But if the disbelievers deny it, then We have entrusted it to a people who are not therein disbelievers.', NULL, NULL, '14c86351a0325464bc341e0a5da7cf12900f34dfd80bd85552efdc69decf7e29'),
  ('en.sahih', 6, 90, 879, 'Those are the ones whom Allah has guided, so from their guidance take an example. Say, "I ask of you for this message no payment. It is not but a reminder for the worlds."', NULL, NULL, 'ee6be8099f838f10a4bee560b8db295c6fb775d1f9c57c33a6760f1c41583064'),
  ('en.sahih', 6, 91, 880, 'And they did not appraise Allah with true appraisal when they said, "Allah did not reveal to a human being anything." Say, "Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers." Say, "Allah [revealed it]." Then leave them in their [empty] discourse, amusing themselves.', NULL, NULL, '958af466b0a08c5a677af26822453e0866df3029d8f96628facb566f1ab357d6'),
  ('en.sahih', 6, 92, 881, 'And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers.', NULL, NULL, 'e71c8be10da44d923448598edbcaa6cdd56e55b6e175039a9bf3fc7d9d013249'),
  ('en.sahih', 6, 93, 882, 'And who is more unjust than one who invents a lie about Allah or says, "It has been inspired to me," while nothing has been inspired to him, and one who says, "I will reveal [something] like what Allah revealed." And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], "Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allah other than the truth and [that] you were, toward His verses, being arrogant."', NULL, NULL, '14e2b88dbb3fdc9b077acc39a7d63c5ef008e9f5cdb7197b36a6da764a827d62'),
  ('en.sahih', 6, 94, 883, '[It will be said to them], "And you have certainly come to Us alone as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your ''intercessors'' which you claimed that they were among you associates [of Allah]. It has [all] been severed between you, and lost from you is what you used to claim."', NULL, NULL, 'df10ab45f151aee40dbf02ba49e2aa7b3a99f7ce0d7f12dd0c6dfa21ddcd6958'),
  ('en.sahih', 6, 95, 884, 'Indeed, Allah is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allah; so how are you deluded?', NULL, NULL, '878e7221092e6513881c07f58c6ee0870c6d9835bc0e5b40697fbf659850e20f'),
  ('en.sahih', 6, 96, 885, '[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing.', NULL, NULL, '9ea73d6e596fdb32691887459a78e555ecd433103c494a3e9e777d784250a4a9'),
  ('en.sahih', 6, 97, 886, 'And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.', NULL, NULL, '4c9b8b10992bdaa42dcfe441f23c11c71e445f733465096bea9f99eb6caf8032'),
  ('en.sahih', 6, 98, 887, 'And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand.', NULL, NULL, '34d299f12ffdda54bc6cfd1aa0b16de0a38acdaae82fcf5dafd2145c12e971da'),
  ('en.sahih', 6, 99, 888, 'And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe.', NULL, NULL, '57b5461a2994dcc0078d8b741399891cd8655b3b31a181c7a9c55b30144331e6'),
  ('en.sahih', 6, 100, 889, 'But they have attributed to Allah partners - the jinn, while He has created them - and have fabricated for Him sons and daughters. Exalted is He and high above what they describe', NULL, NULL, '4b744b37dad508ea25bbd84f0227570bc3bcedd044a326088a9d082f1b9c01b4'),
  ('en.sahih', 6, 101, 890, '[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion and He created all things? And He is, of all things, Knowing.', NULL, NULL, '963548eeb3d3608aa2f5bb15306750702f710cbe1f25bae98a5ed5b1a6cf2723'),
  ('en.sahih', 6, 102, 891, 'That is Allah, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things.', NULL, NULL, 'efb35b0deebc47541798c0ad3bc25662b412173db6d775114b2ccd5a265d0bc6'),
  ('en.sahih', 6, 103, 892, 'Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Acquainted.', NULL, NULL, 'fa9bc15aee9745e6e29e9c40e67362844f557a4cccd3fbfd805a47bf22747aff'),
  ('en.sahih', 6, 104, 893, 'There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], "I am not a guardian over you."', NULL, NULL, '4aed567dbd8ef49752ae777f850b30831e1cde18858bacd219f8366f1c6a71dc'),
  ('en.sahih', 6, 105, 894, 'And thus do We diversify the verses so the disbelievers will say, "You have studied," and so We may make the Qur''an clear for a people who know.', NULL, NULL, 'ed4c995e3439b261ceead63e276cefec67a7d8dc356c178585042eca7b9d6531'),
  ('en.sahih', 6, 106, 895, 'Follow, [O Muhammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allah.', NULL, NULL, '998317756b39a82c5911c26becac3131005fecbffd304ff6c76aea788f740ce4'),
  ('en.sahih', 6, 107, 896, 'But if Allah had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them.', NULL, NULL, 'de3cb30423a46e8476c2e840f488e11763b98982af959d397e8390c1f96a18bf'),
  ('en.sahih', 6, 108, 897, 'And do not insult those they invoke other than Allah, lest they insult Allah in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do.', NULL, NULL, '50b70020996469617b7ef78485132b0f658f234fe429e84710e732ff55fb6e57'),
  ('en.sahih', 6, 109, 898, 'And they swear by Allah their strongest oaths that if a sign came to them, they would surely believe in it. Say, "The signs are only with Allah." And what will make you perceive that even if a sign came, they would not believe.', NULL, NULL, 'b4e76b4af29f16ff2608df4a0396b10103b1547a4ac7f8a5ac5382d1e89c606b'),
  ('en.sahih', 6, 110, 899, 'And We will turn away their hearts and their eyes just as they refused to believe in it the first time. And We will leave them in their transgression, wandering blindly.', NULL, NULL, 'f3e6a1df27d528bb41c004b8c61d81c2697bf959eda6ab54787f954c30f00007'),
  ('en.sahih', 6, 111, 900, 'And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allah should will. But most of them, [of that], are ignorant.', NULL, NULL, '81b57f02e43f6d431964597289e55a3e12711892d71764a7b1b83be44870ac49')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 6, 112, 901, 'And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent.', NULL, NULL, '5eded7ebf375a72466491da9bc3dbe4d3d4b99e162aab39bc1e73150bec88577'),
  ('en.sahih', 6, 113, 902, 'And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it and that they will be satisfied with it and that they will commit that which they are committing.', NULL, NULL, 'fe1baebdacd30ade1f99279180d5c47653c59d0ca84cc163c2c20c63d84dfa6f'),
  ('en.sahih', 6, 114, 903, '[Say], "Then is it other than Allah I should seek as judge while it is He who has revealed to you the Book explained in detail?" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters.', NULL, NULL, '18389e5b00885cf68ce2df793ecff0e225ace410e060815879f11ae02e413d06'),
  ('en.sahih', 6, 115, 904, 'And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing.', NULL, NULL, '3d3388990a5c131e0e9c629abbfe195d8c0eaf4edc374dcbb1b08464cbd121aa'),
  ('en.sahih', 6, 116, 905, 'And if you obey most of those upon the earth, they will mislead you from the way of Allah. They follow not except assumption, and they are not but falsifying.', NULL, NULL, 'd539bdf2f87e452a755249779d133826a10f490ea2ccdb126bf1f73e8fa6672a'),
  ('en.sahih', 6, 117, 906, 'Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided.', NULL, NULL, '87674805fd197cc5e94596f379c544ec2ddac30a760f4ef6cefc2cf3a8f06c5e'),
  ('en.sahih', 6, 118, 907, 'So eat of that [meat] upon which the name of Allah has been mentioned, if you are believers in His verses.', NULL, NULL, 'a73ce81f255337691ec932c6c9bc6f8e516b0621eff55f0f872aa447eb503f2c'),
  ('en.sahih', 6, 119, 908, 'And why should you not eat of that upon which the name of Allah has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors.', NULL, NULL, '4035be067cae6d25f72d6cc5d994f3a49b80a555e8d0ed5c464973c49c07d61c'),
  ('en.sahih', 6, 120, 909, 'And leave what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit.', NULL, NULL, '73ec6b04dfb1d228e8cb8fc21ef562fe3a856c75d126818f72bc02ee0411b9ef'),
  ('en.sahih', 6, 121, 910, 'And do not eat of that upon which the name of Allah has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him].', NULL, NULL, '5ba879afaa50c98cd2339dae972140937122358e8bcf34dbc7e0bacd6877d8f3'),
  ('en.sahih', 6, 122, 911, 'And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing.', NULL, NULL, 'c6b634adb6279e327c3d85189b059e3855e66afe2a7216166c8adb0cbba8cb49'),
  ('en.sahih', 6, 123, 912, 'And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not.', NULL, NULL, '779f9d2cabd522b9aa740178c29a5442e6c34538fd21d70f7631c662ecd68381'),
  ('en.sahih', 6, 124, 913, 'And when a sign comes to them, they say, "Never will we believe until we are given like that which was given to the messengers of Allah." Allah is most knowing of where He places His message. There will afflict those who committed crimes debasement before Allah and severe punishment for what they used to conspire.', NULL, NULL, '8c626e3a259ae45255a67d56fe5a4bcb144e07ececcdb30e0e761455ba2c225b'),
  ('en.sahih', 6, 125, 914, 'So whoever Allah wants to guide - He expands his breast to [contain] Islam; and whoever He wants to misguide - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allah place defilement upon those who do not believe.', NULL, NULL, '4fde4bbe6fba87198882759c033fe02a248fbe166ae308aa2cc98d821ae16d9c'),
  ('en.sahih', 6, 126, 915, 'And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.', NULL, NULL, 'f8a180e667db8738cbf9d7f5ad5d0bbe8f11c2c52d0a787bfc5b20624ea98957'),
  ('en.sahih', 6, 127, 916, 'For them will be the Home of Peace with their Lord. And He will be their protecting friend because of what they used to do.', NULL, NULL, 'fe5ee33e402379b17a17baf6972a33f7eab0a4d825360e27c1be1743a25d181d'),
  ('en.sahih', 6, 128, 917, 'And [mention, O Muhammad], the Day when He will gather them together [and say], "O company of jinn, you have [misled] many of mankind." And their allies among mankind will say, "Our Lord, some of us made use of others, and we have [now] reached our term, which you appointed for us." He will say, "The Fire is your residence, wherein you will abide eternally, except for what Allah wills. Indeed, your Lord is Wise and Knowing."', NULL, NULL, '69e6d36b208d17f2af00a9b2d03d2e4657bc82d92d8eda9b838174f136ddb240'),
  ('en.sahih', 6, 129, 918, 'And thus will We make some of the wrongdoers allies of others for what they used to earn.', NULL, NULL, '733c8f65bf15a67c435ff587c7707b24afe4c00c148ab5607e7fbc818ae0fbc5'),
  ('en.sahih', 6, 130, 919, '"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?" They will say, "We bear witness against ourselves"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers.', NULL, NULL, '83e667aff8862741abb2aa200192c6884ac7e946c3682c8f6206e65950a3c9ef'),
  ('en.sahih', 6, 131, 920, 'That is because your Lord would not destroy the cities for wrongdoing while their people were unaware.', NULL, NULL, '025e59c4787b3ad9ce22ebf446480752d7eaa2cbd26abf5b02d535dba8d2d649'),
  ('en.sahih', 6, 132, 921, 'And for all are degrees from what they have done. And your Lord is not unaware of what they do.', NULL, NULL, '3a79f6e75a9cd92cde515cd6f759b5d1bb66129bd081ddc8b46ae96e20bae453'),
  ('en.sahih', 6, 133, 922, 'And your Lord is the Free of need, the possessor of mercy. If He wills, he can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people.', NULL, NULL, 'ae8d407974548b25af7b86acd4f70b74719c3a376a64f13432c3a7db3a345f01'),
  ('en.sahih', 6, 134, 923, 'Indeed, what you are promised is coming, and you will not cause failure [to Allah].', NULL, NULL, 'f4c10256bcc0f43f4045ddbc1df033ff4bc408e2a8242bf2b2b670a4fc1f9204'),
  ('en.sahih', 6, 135, 924, 'Say, "O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed.', NULL, NULL, 'd887b48b28a5c60a4a16343b96fd4416145b914f75a79c8fc68a9c0b84f31ae9'),
  ('en.sahih', 6, 136, 925, 'And the polytheists assign to Allah from that which He created of crops and livestock a share and say, "This is for Allah," by their claim, "and this is for our partners [associated with Him]." But what is for their "partners" does not reach Allah, while what is for Allah - this reaches their "partners." Evil is that which they rule.', NULL, NULL, '1199af8f1b6cc195da3a0543fbba77d7ec41a51c47b05f548ec2cb4842974d05'),
  ('en.sahih', 6, 137, 926, 'And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allah had willed, they would not have done so. So leave them and that which they invent.', NULL, NULL, 'f4597631e125d2252d92cb3e1b76da9c985e5af77f12e38b76faebfb677e1d5a'),
  ('en.sahih', 6, 138, 927, 'And they say, "These animals and crops are forbidden; no one may eat from them except whom we will," by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allah is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing.', NULL, NULL, '6d9b04c91af313d2b6cdd96ad19e151e7b7a41c0164da1e826eb8399b23c4606'),
  ('en.sahih', 6, 139, 928, 'And they say, "What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein." He will punish them for their description. Indeed, He is Wise and Knowing.', NULL, NULL, 'a034f2d0efc15c77ef8c27e28ef7b6de31bf77ef215d957bfce2e4566777ad64'),
  ('en.sahih', 6, 140, 929, 'Those will have lost who killed their children in foolishness without knowledge and prohibited what Allah had provided for them, inventing untruth about Allah. They have gone astray and were not [rightly] guided.', NULL, NULL, '22b0d37329956c3d0081bae499cfb64e9c37277770e10eec7d67edbafc1c0c8b'),
  ('en.sahih', 6, 141, 930, 'And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakah] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess.', NULL, NULL, '07735b72f225f38b3b264b79650b89c34837bbca7e93135f9282ab3499b1053a'),
  ('en.sahih', 6, 142, 931, 'And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allah has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.', NULL, NULL, '6449d8caa93b04c2c286ac91f8e8f9e605606707ec5fade129489ad1a75a6829'),
  ('en.sahih', 6, 143, 932, '[They are] eight mates - of the sheep, two and of the goats, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful."', NULL, NULL, 'c85d17b653bc0582edfb6d48df5dc692c4ffb9225bfe3ca3ceb29b890bbd2444'),
  ('en.sahih', 6, 144, 933, 'And of the camels, two and of the cattle, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allah charged you with this? Then who is more unjust than one who invents a lie about Allah to mislead the people by [something] other than knowledge? Indeed, Allah does not guide the wrongdoing people."', NULL, NULL, '520d5d004a1a87bb16a5b134971ddb6af6eeb75ebc8bab09b6343901fe55610d'),
  ('en.sahih', 6, 145, 934, 'Say, "I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful."', NULL, NULL, '2e28fa126b451e0de3c99f4a4013313ce5a0701c48b8e4f6f62b97cbad8ecaf5'),
  ('en.sahih', 6, 146, 935, 'And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their injustice. And indeed, We are truthful.', NULL, NULL, '0fa973837726b6af06ef2cc4b70a861b9d3c2fedbf8144b7dc6d3b702d2f3d5f'),
  ('en.sahih', 6, 147, 936, 'So if they deny you, [O Muhammad], say, "Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals."', NULL, NULL, '8a7021047658a22b7259bccb2418d532be8b42a70c2122704b4a232e59ef36a0'),
  ('en.sahih', 6, 148, 937, 'Those who associated with Allah will say, "If Allah had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything." Likewise did those before deny until they tasted Our punishment. Say, "Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but falsifying."', NULL, NULL, 'b163c868fd4d191a5bd362302e0e9fee20ffd972ac1ea15990fe294e8698b966'),
  ('en.sahih', 6, 149, 938, 'Say, "With Allah is the far-reaching argument. If He had willed, He would have guided you all."', NULL, NULL, '337d79467bd696aac29cdbe410710e20caa2b1bcc7728c3ad7538938fda71154'),
  ('en.sahih', 6, 150, 939, 'Say, [O Muhammad], "Bring forward your witnesses who will testify that Allah has prohibited this." And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord.', NULL, NULL, 'd3de92c3e911f34a3c93d169574813bf5288127cc6ed7adf172a94e03000d728'),
  ('en.sahih', 6, 151, 940, 'Say, "Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allah has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason."', NULL, NULL, '51119c06853f880bd9afe82175afcd1e01b9e2be5bf5b97f827bd358c0f76637'),
  ('en.sahih', 6, 152, 941, 'And do not approach the orphan''s property except in a way that is best until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you testify, be just, even if [it concerns] a near relative. And the covenant of Allah fulfill. This has He instructed you that you may remember.', NULL, NULL, '84a33327fa8d9e84fe4236d447d008be790caf5569d45b4b10b34620ee3331fa'),
  ('en.sahih', 6, 153, 942, 'And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous.', NULL, NULL, '9708521e29531541273693428ebc7eae2c4c641880937c7315b383eb60f96f42'),
  ('en.sahih', 6, 154, 943, 'Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good and as a detailed explanation of all things and as guidance and mercy that perhaps in [the matter of] the meeting with their Lord they would believe.', NULL, NULL, 'eca084a41adb5cdb17d7615e7448e80610741f26488923c799a0faef2156b1a5'),
  ('en.sahih', 6, 155, 944, 'And this [Qur''an] is a Book We have revealed [which is] blessed, so follow it and fear Allah that you may receive mercy.', NULL, NULL, 'cbbbad78518239c1e4c8ac6dbe9f2dfc62e9f653d888d3bb362d7a94d0175259'),
  ('en.sahih', 6, 156, 945, '[We revealed it] lest you say, "The Scripture was only sent down to two groups before us, but we were of their study unaware,"', NULL, NULL, 'bdf8b0b5f4caef178cf2e1b199ea8c825622a49fa71667f18229e60f5340b6f4'),
  ('en.sahih', 6, 157, 946, 'Or lest you say, "If only the Scripture had been revealed to us, we would have been better guided than they." So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allah and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away.', NULL, NULL, 'cc5d6293f2fc1c6c4460ef9d5032c99b42f2f318212941ffaf5b636a098f7d44'),
  ('en.sahih', 6, 158, 947, 'Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, "Wait. Indeed, we [also] are waiting."', NULL, NULL, 'a5ae6332cae9585dc882dee5ca822b53423b6ffbb888ddaaca8f7d74b373038a'),
  ('en.sahih', 6, 159, 948, 'Indeed, those who have divided their religion and become sects - you, [O Muhammad], are not [associated] with them in anything. Their affair is only [left] to Allah; then He will inform them about what they used to do.', NULL, NULL, '3bd956ee3528c092fc79eed41bb604b8ee304925318678881e1e7819c527d1b6'),
  ('en.sahih', 6, 160, 949, 'Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.', NULL, NULL, '01b3a59606d18b3bbe844f49ebd7c5c9a77bfb8c00168cd6cf55bb2d6ce2cb36'),
  ('en.sahih', 6, 161, 950, 'Say, "Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allah."', NULL, NULL, '93a31426fdf83d35ad77a0610a90909de490801c455ffd56dea1b26c700e1801'),
  ('en.sahih', 6, 162, 951, 'Say, "Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds.', NULL, NULL, '561f194968e45ab2de5896577efbec229a7afddb86b0fd139d437b043819904b'),
  ('en.sahih', 6, 163, 952, 'No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims."', NULL, NULL, '713bc6f58e3f75d5696528d369ed50629e6a2ee6c76e0cd1a56f2e1284d34022'),
  ('en.sahih', 6, 164, 953, 'Say, "Is it other than Allah I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ."', NULL, NULL, '3ed37070c5662b2f576897f69af34e3331c4f923f002a8b23027cca1263f0cc1'),
  ('en.sahih', 6, 165, 954, 'And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.', NULL, NULL, '7a4c3fbc2dc453810076759195f3539b3d141a857b92dbffd713204fa403aa85'),
  ('en.sahih', 7, 1, 955, 'Alif, Lam, Meem, Sad.', NULL, NULL, 'fe8df6a48f7104229adcf003f49fd961453ee5ce271d1cefaddc2062739bc224'),
  ('en.sahih', 7, 2, 956, '[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.', NULL, NULL, '82dc14cd456cab41e12207dc7aacd4ddd0af9512aec3fa9ff66427c9497c8ea0'),
  ('en.sahih', 7, 3, 957, 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.', NULL, NULL, '1c4eb4789c9415ddfb3c554ba55a0e74a4821c46b98205e86c56adf1d0e1078c'),
  ('en.sahih', 7, 4, 958, 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.', NULL, NULL, '875bcf046c894ed1e7afaa2559ff68a719d0043e4e0fe78c8d2e0d195dab561b'),
  ('en.sahih', 7, 5, 959, 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"', NULL, NULL, '8f2353928c48a2b34648831c74e68d35fb156acc5b07ce34a1999a116436546c'),
  ('en.sahih', 7, 6, 960, 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.', NULL, NULL, '0e1ea6e01cd77b7ecb7b83b18b6367624d1076b234c5a5614ff9467b963131bd'),
  ('en.sahih', 7, 7, 961, 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.', NULL, NULL, '800be8bb1fa88928f80d529414101b921fdd34531b0bc85551c5996d234bc714'),
  ('en.sahih', 7, 8, 962, 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.', NULL, NULL, '78d361fa98e0cfea4acd7af9893220354516c34a36fc359efba334ba7ebe2a4b'),
  ('en.sahih', 7, 9, 963, 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.', NULL, NULL, '29366f3485138862efdda0fa3182636195b31d75f17e707f9648268bf5b7e497'),
  ('en.sahih', 7, 10, 964, 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.', NULL, NULL, '522d34eec69fc38121134c7fd327c9631c72d7657624a6137d4436d1093039d9'),
  ('en.sahih', 7, 11, 965, 'And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.', NULL, NULL, 'f137e305fa013cc2d3d6d25eb0f91f9d36c591eede2f1a1b833131c37ecdcc1b'),
  ('en.sahih', 7, 12, 966, '[Allah] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay."', NULL, NULL, '4ac8b16543b55512221d1d76ab3daba7ceca336a16585bc8a00c7b4ef9a60fb0'),
  ('en.sahih', 7, 13, 967, '[Allah] said, "Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.', NULL, NULL, 'c674d708f948b56ac6734769391d16f12b059f84a46130756d047e2079427e3a'),
  ('en.sahih', 7, 14, 968, '[Satan] said, "Reprieve me until the Day they are resurrected."', NULL, NULL, 'f63b57481c18b67497cce1bd37acf0f7e44aaf8b2a210ae5e744639d4c2963d1'),
  ('en.sahih', 7, 15, 969, '[Allah] said, "Indeed, you are of those reprieved."', NULL, NULL, '12871a3ba60bd2b7567bf8240df519688b27c4872eb9f6eff043ee276ee3b9da'),
  ('en.sahih', 7, 16, 970, '[Satan] said, "Because You have put me in error, I will surely sit in wait for them on Your straight path.', NULL, NULL, '61b018471b2739e128359cd4ffab7f22dc26825231fc1a3604f97f4cc1678484'),
  ('en.sahih', 7, 17, 971, 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."', NULL, NULL, '5df0042e27470f7609aa5b4717713a15cb29dcbdc323a4022fe38ad43867dd7f'),
  ('en.sahih', 7, 18, 972, '[Allah] said, "Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."', NULL, NULL, 'dd0261b9940794f08c5625bc6d51f1c0f3f9f92e758fcc6e0fc343d629fa24d2'),
  ('en.sahih', 7, 19, 973, 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."', NULL, NULL, 'f8254333f4d609bc9178f13e8f2c5bd5d874c65d27f28193e6179d5a3b3761fe'),
  ('en.sahih', 7, 20, 974, 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."', NULL, NULL, '4523dc44531f0ea650c9c521c974c7c890adeb7d5da7fcc249c2fbe15c863e63'),
  ('en.sahih', 7, 21, 975, 'And he swore [by Allah] to them, "Indeed, I am to you from among the sincere advisors."', NULL, NULL, '86c81329ae30b695a81e56e50fdaaaf29274e8d4e5b334452b4608323f41de87'),
  ('en.sahih', 7, 22, 976, 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"', NULL, NULL, '9c1731cc74ad4d576c74b6b82d8de5032fe28095279dbc76f680ef1512a225ba'),
  ('en.sahih', 7, 23, 977, 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."', NULL, NULL, 'de197e52353053dc11dc619e3b35229b4d6fa696660388a45ecda5b2cd2084bf'),
  ('en.sahih', 7, 24, 978, '[Allah] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time."', NULL, NULL, 'c9e7d9aeb4db301c1cb9f93c54d565042394b63536ef68aba9444b2bbdb67276'),
  ('en.sahih', 7, 25, 979, 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."', NULL, NULL, '2209e4d41dfc04128a2bceb75937f230bd5c1eac04dbc90042aa6cc07d1f04aa'),
  ('en.sahih', 7, 26, 980, 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember.', NULL, NULL, 'f1043a65f768d46ebc2e1fcdc530b7800af81df122a114cb09ebfa9fafd6735a'),
  ('en.sahih', 7, 27, 981, 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.', NULL, NULL, 'e68f905e71516feff417a1dca1f3d9a1eb44958c55d9b293a7a6f7208ea1d7c5'),
  ('en.sahih', 7, 28, 982, 'And when they commit an immorality, they say, "We found our fathers doing it, and Allah has ordered us to do it." Say, "Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?"', NULL, NULL, '11ccd7180c0966526d8c3bd9e16d89259ae6177b7b1462e05e1a164d3c896509'),
  ('en.sahih', 7, 29, 983, 'Say, [O Muhammad], "My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -', NULL, NULL, '6c9b96350111cbedd820ce7dfe173118975a98bcc0d10b765058c22fe8db13b8'),
  ('en.sahih', 7, 30, 984, 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided.', NULL, NULL, '4070c915e4379fdcf7d969523a4474c49aa4badd7794fc2ee1288d7b97663ca1'),
  ('en.sahih', 7, 31, 985, 'O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.', NULL, NULL, 'c9169014f8cc552c8b43fcaa49de06ce649bf65e5c75bf237aa091ba159b42f3'),
  ('en.sahih', 7, 32, 986, 'Say, "Who has forbidden the adornment of Allah which He has produced for His servants and the good [lawful] things of provision?" Say, "They are for those who believe during the worldly life [but] exclusively for them on the Day of Resurrection." Thus do We detail the verses for a people who know.', NULL, NULL, '0148b5aefa5aed0c8251afeccc58eec299f020f143d37187a08fdfc8457557ef'),
  ('en.sahih', 7, 33, 987, 'Say, "My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allah that for which He has not sent down authority, and that you say about Allah that which you do not know."', NULL, NULL, '0ec159e40123d48a9f329c2b104ea15581026c2f9cf62d4e0d609e0570d9ef11'),
  ('en.sahih', 7, 34, 988, 'And for every nation is a [specified] term. So when their time has come, they will not remain behind an hour, nor will they precede [it].', NULL, NULL, 'f256e42b57ac74c47e9f56c8966c4ff30bc201a4beead529765f98195cd0270b'),
  ('en.sahih', 7, 35, 989, 'O children of Adam, if there come to you messengers from among you relating to you My verses, then whoever fears Allah and reforms - there will be no fear concerning them, nor will they grieve.', NULL, NULL, 'a5b11203d1cf6f24a7251bbf36f33ba779d04db7996d6a343f4b48f2228299ab'),
  ('en.sahih', 7, 36, 990, 'But the ones who deny Our verses and are arrogant toward them - those are the companions of the Fire; they will abide therein eternally.', NULL, NULL, '7c3579a4ffb08249867d64d676ed195ca4650f8ad2edcfe59e24c6e7b42255cc'),
  ('en.sahih', 7, 37, 991, 'And who is more unjust than one who invents about Allah a lie or denies His verses? Those will attain their portion of the decree until when Our messengers come to them to take them in death, they will say, "Where are those you used to invoke besides Allah?" They will say, "They have departed from us," and will bear witness against themselves that they were disbelievers.', NULL, NULL, '583ac2fd53641ec215d8474d852c8112e9b8be4d1791756bfc1cb55b566ecd95'),
  ('en.sahih', 7, 38, 992, '[Allah] will say, "Enter among nations which had passed on before you of jinn and mankind into the Fire." Every time a nation enters, it will curse its sister until, when they have all overtaken one another therein, the last of them will say about the first of them "Our Lord, these had misled us, so give them a double punishment of the Fire. He will say, "For each is double, but you do not know."', NULL, NULL, '8f3ec1611f9cb23c644b69e81084838b469b488972c6567006127118cd726e9b'),
  ('en.sahih', 7, 39, 993, 'And the first of them will say to the last of them, "Then you had not any favor over us, so taste the punishment for what you used to earn."', NULL, NULL, 'ebecd62622d96d83315350b02dce52ad58819404906866c114f230c3be683b26'),
  ('en.sahih', 7, 40, 994, 'Indeed, those who deny Our verses and are arrogant toward them - the gates of Heaven will not be opened for them, nor will they enter Paradise until a camel enters into the eye of a needle. And thus do We recompense the criminals.', NULL, NULL, 'd3e30d6412820790eceae52caacee64fb16c70d7f34a593580bab989e7f7b431'),
  ('en.sahih', 7, 41, 995, 'They will have from Hell a bed and over them coverings [of fire]. And thus do We recompense the wrongdoers.', NULL, NULL, 'd5a5e1a160d0a19f799e2816ebc803c868de7c89c041ed84a88a17230d87a1eb'),
  ('en.sahih', 7, 42, 996, 'But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally.', NULL, NULL, '46c4ab00859a258f184814e17715afddbf9b8c318ee5d721a297b3f9257349a7'),
  ('en.sahih', 7, 43, 997, 'And We will have removed whatever is within their breasts of resentment, [while] flowing beneath them are rivers. And they will say, "Praise to Allah, who has guided us to this; and we would never have been guided if Allah had not guided us. Certainly the messengers of our Lord had come with the truth." And they will be called, "This is Paradise, which you have been made to inherit for what you used to do."', NULL, NULL, '9aa85bb18e9859ca5fdbbc3911c99c4eb9aab5f9d78e264713f07bdb25ddf893'),
  ('en.sahih', 7, 44, 998, 'And the companions of Paradise will call out to the companions of the Fire, "We have already found what our Lord promised us to be true. Have you found what your Lord promised to be true?" They will say, "Yes." Then an announcer will announce among them, "The curse of Allah shall be upon the wrongdoers."', NULL, NULL, '2340b7cf7140ab4ec9a33d1a8a5203bb7a3bb7974a014b5c42c343eff5b5a379'),
  ('en.sahih', 7, 45, 999, 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they were, concerning the Hereafter, disbelievers.', NULL, NULL, 'f51c74fe755ecba20c47b6ecf0eae124b4e52e123ffca978da1d74e0451ccdf1'),
  ('en.sahih', 7, 46, 1000, 'And between them will be a partition, and on [its] elevations are men who recognize all by their mark. And they call out to the companions of Paradise, "Peace be upon you." They have not [yet] entered it, but they long intensely.', NULL, NULL, '4b43ffdc7670a6637e437ae7efe222e037cf8ff10aebc6fe5dee427b10aca548')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 7, 47, 1001, 'And when their eyes are turned toward the companions of the Fire, they say, "Our Lord, do not place us with the wrongdoing people."', NULL, NULL, '93157722152efe919d5054f780ce949e74dfc0153393600d1442ea0ce9681ce5'),
  ('en.sahih', 7, 48, 1002, 'And the companions of the Elevations will call to men [within Hell] whom they recognize by their mark, saying, "Of no avail to you was your gathering and [the fact] that you were arrogant."', NULL, NULL, 'a328319f113311ed0b30df8eea6d8a60987a8873fbe43e999c75a153e6ec104a'),
  ('en.sahih', 7, 49, 1003, '[Allah will say], "Are these the ones whom you [inhabitants of Hell] swore that Allah would never offer them mercy? Enter Paradise, [O People of the Elevations]. No fear will there be concerning you, nor will you grieve."', NULL, NULL, 'db71e109334c571100d5c002de75a234a10e6d392edf4b1a7a3f043ed134b508'),
  ('en.sahih', 7, 50, 1004, 'And the companions of the Fire will call to the companions of Paradise, "Pour upon us some water or from whatever Allah has provided you." They will say, "Indeed, Allah has forbidden them both to the disbelievers."', NULL, NULL, 'b62ec83457f5d4840be0e94cfce1369982ebe29a33f753a2ec6f56cf371ce23c'),
  ('en.sahih', 7, 51, 1005, 'Who took their religion as distraction and amusement and whom the worldly life deluded." So today We will forget them just as they forgot the meeting of this Day of theirs and for having rejected Our verses.', NULL, NULL, 'a1e9cb9b3b233010631db662358b3aab6dcb6c3a9755dcdce9def9b5b576e489'),
  ('en.sahih', 7, 52, 1006, 'And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe.', NULL, NULL, '123728b68647f6667fca5dffcef461bf039cc58e52e70bcc2ff5d29ed07bcf2d'),
  ('en.sahih', 7, 53, 1007, 'Do they await except its result? The Day its result comes those who had ignored it before will say, "The messengers of our Lord had come with the truth, so are there [now] any intercessors to intercede for us or could we be sent back to do other than we used to do?" They will have lost themselves, and lost from them is what they used to invent.', NULL, NULL, '83ef2f75a9d7ccb1b39e9c53b3af9cf00a3f511b6b26ec551b7a37aa744971c6'),
  ('en.sahih', 7, 54, 1008, 'Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds.', NULL, NULL, 'dae0a10d447bdf060daed7bcb4ddcd394ddf9b14f6d78ede2a142a398d273c43'),
  ('en.sahih', 7, 55, 1009, 'Call upon your Lord in humility and privately; indeed, He does not like transgressors.', NULL, NULL, '6023d711aedf20de345c782fc3cedb20dc596ac58bc32c81fe4a3922b6f946cd'),
  ('en.sahih', 7, 56, 1010, 'And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allah is near to the doers of good.', NULL, NULL, '4e04e70a7b7cc30e6e8a120ea65880fa0cdd937729bb63e74d0e9739959e2084'),
  ('en.sahih', 7, 57, 1011, 'And it is He who sends the winds as good tidings before His mercy until, when they have carried heavy rainclouds, We drive them to a dead land and We send down rain therein and bring forth thereby [some] of all the fruits. Thus will We bring forth the dead; perhaps you may be reminded.', NULL, NULL, 'e4043e92c6b74bc2a73d85892175e03a4476e146d8c9541bc21844900a0375d0'),
  ('en.sahih', 7, 58, 1012, 'And the good land - its vegetation emerges by permission of its Lord; but that which is bad - nothing emerges except sparsely, with difficulty. Thus do We diversify the signs for a people who are grateful.', NULL, NULL, 'cde838be36753c907f28e55f8ab9c9e66f16d2a70a9bee2b4bb7e74625229bfd'),
  ('en.sahih', 7, 59, 1013, 'We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him. Indeed, I fear for you the punishment of a tremendous Day.', NULL, NULL, '2f296c1256d54090c4bebc1ccf7d652f9f8a58875535c036a896684470a6cf2a'),
  ('en.sahih', 7, 60, 1014, 'Said the eminent among his people, "Indeed, we see you in clear error."', NULL, NULL, 'd04b340f157583375a9b945c261ea83b73a2e230e4170f1b103cdc5689f1ff49'),
  ('en.sahih', 7, 61, 1015, '[Noah] said, "O my people, there is not error in me, but I am a messenger from the Lord of the worlds."', NULL, NULL, '3e3fad895e12d15ad9f40023e7d10b4d0db2a74872f0cc7407c947530dce25c7'),
  ('en.sahih', 7, 62, 1016, 'I convey to you the messages of my Lord and advise you; and I know from Allah what you do not know.', NULL, NULL, '445d70ce21560e793b81a2d7a173b75890c4af55706f1e794bab2e32fdde1ae7'),
  ('en.sahih', 7, 63, 1017, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you and that you may fear Allah so you might receive mercy."', NULL, NULL, '1630a6fd0825809c7faf02b4634d1616d71780c19dd900ded1c09ffdd5f386f7'),
  ('en.sahih', 7, 64, 1018, 'But they denied him, so We saved him and those who were with him in the ship. And We drowned those who denied Our signs. Indeed, they were a blind people.', NULL, NULL, 'f4bb1a1d1be1e6c0eba46e9aeab320bac5fc4df493fd9a4748af1af76023be1a'),
  ('en.sahih', 7, 65, 1019, 'And to the ''Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. Then will you not fear Him?"', NULL, NULL, '5c1d1dd9f30222cbaa062615e757f0e271824f27e0709bd3129db44846b10ce7'),
  ('en.sahih', 7, 66, 1020, 'Said the eminent ones who disbelieved among his people, "Indeed, we see you in foolishness, and indeed, we think you are of the liars."', NULL, NULL, 'b6a2c2bd0416a47e156ba063f4a60530f169ba07ee11be727019bfb19be7d87c'),
  ('en.sahih', 7, 67, 1021, '[Hud] said, "O my people, there is not foolishness in me, but I am a messenger from the Lord of the worlds."', NULL, NULL, '539237e2779aa3c08c9a33d59b372f05ec7e1650dd247b4d0d5a116467d88a4e'),
  ('en.sahih', 7, 68, 1022, 'I convey to you the messages of my Lord, and I am to you a trustworthy adviser.', NULL, NULL, 'e898a76eed7380f1cfcdc35957112c8748a200504e300b40eef6899d1c1cd802'),
  ('en.sahih', 7, 69, 1023, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you? And remember when He made you successors after the people of Noah and increased you in stature extensively. So remember the favors of Allah that you might succeed.', NULL, NULL, '0a5b8f069dddf7505fd75cabc2e72c7fa8603cc4bf057b17afb928c007f26ff9'),
  ('en.sahih', 7, 70, 1024, 'They said, "Have you come to us that we should worship Allah alone and leave what our fathers have worshipped? Then bring us what you promise us, if you should be of the truthful."', NULL, NULL, '3bc557c9b2d460b58f5f50dae76da0d090bde932ac2f144a90c60cf3543a3b24'),
  ('en.sahih', 7, 71, 1025, '[Hud] said, "Already have defilement and anger fallen upon you from your Lord. Do you dispute with me concerning [mere] names you have named them, you and your fathers, for which Allah has not sent down any authority? Then wait; indeed, I am with you among those who wait."', NULL, NULL, '37cfa10a2843d134e1b62393ae078e84899b41c2113294b4d3f5bd4ac2bdc3c8'),
  ('en.sahih', 7, 72, 1026, 'So We saved him and those with him by mercy from Us. And We eliminated those who denied Our signs, and they were not [at all] believers.', NULL, NULL, 'cd73d1353b3b3e34468c48d15f35e36801967789e15f829a5423e43edb46f99d'),
  ('en.sahih', 7, 73, 1027, 'And to the Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. This is the she-camel of Allah [sent] to you as a sign. So leave her to eat within Allah ''s land and do not touch her with harm, lest there seize you a painful punishment.', NULL, NULL, '1d0d3ac2a0342bb8538e4779a8f0d265ec1af5f666adcf61a9c67f404e766942'),
  ('en.sahih', 7, 74, 1028, 'And remember when He made you successors after the ''Aad and settled you in the land, [and] you take for yourselves palaces from its plains and carve from the mountains, homes. Then remember the favors of Allah and do not commit abuse on the earth, spreading corruption."', NULL, NULL, '3317af5593754dc3a4755734a0d3d94ed7f276022a4f2fb16892f169e8f513e9'),
  ('en.sahih', 7, 75, 1029, 'Said the eminent ones who were arrogant among his people to those who were oppressed - to those who believed among them, "Do you [actually] know that Salih is sent from his Lord?" They said, "Indeed we, in that with which he was sent, are believers."', NULL, NULL, '5944eeb0d0f9a96717e4780663ec9f5b904c39e5939b15c444369770fecf4334'),
  ('en.sahih', 7, 76, 1030, 'Said those who were arrogant, "Indeed we, in that which you have believed, are disbelievers."', NULL, NULL, 'c5b225c717059c2c4a25b7744daade0d4c7110d64b41b4b69c080e8b581e6d56'),
  ('en.sahih', 7, 77, 1031, 'So they hamstrung the she-camel and were insolent toward the command of their Lord and said, "O Salih, bring us what you promise us, if you should be of the messengers."', NULL, NULL, '23d25c0430f6cfd4c9e4d0963731b327a7c3ef9175f1ea2cdabeeacaded19cdc'),
  ('en.sahih', 7, 78, 1032, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.', NULL, NULL, 'c2e2b4def718ebb3a71490370053412db1c9ad890ef7c1d3923561814cd0ad39'),
  ('en.sahih', 7, 79, 1033, 'And he turned away from them and said, "O my people, I had certainly conveyed to you the message of my Lord and advised you, but you do not like advisors."', NULL, NULL, '6f6ad8641b273053d168cb199b596cc9eb0e8a805643b9ee105a558a1599b1e7'),
  ('en.sahih', 7, 80, 1034, 'And [We had sent] Lot when he said to his people, "Do you commit such immorality as no one has preceded you with from among the worlds?', NULL, NULL, '7fa0c54a6a80565ed663f7ed73db0e99418d51a91375e89256794ecfba0aee85'),
  ('en.sahih', 7, 81, 1035, 'Indeed, you approach men with desire, instead of women. Rather, you are a transgressing people."', NULL, NULL, '9a27a17b3959acf69566543e7a58974511ce91b2c45f174335b96108befbbd66'),
  ('en.sahih', 7, 82, 1036, 'But the answer of his people was only that they said, "Evict them from your city! Indeed, they are men who keep themselves pure."', NULL, NULL, 'a7b90c2ade455e3d687d3f16cdb9baaec58a951f690b846dacfafc976e227eec'),
  ('en.sahih', 7, 83, 1037, 'So We saved him and his family, except for his wife; she was of those who remained [with the evildoers].', NULL, NULL, '46f8214dbea5882515038a1758e96c8e40a5f21b7bb6e9a0a41644a60826102d'),
  ('en.sahih', 7, 84, 1038, 'And We rained upon them a rain [of stones]. Then see how was the end of the criminals.', NULL, NULL, '36c7462d17b96f96e43bc9406e74dea54539110c8032326d162e9d6364932026'),
  ('en.sahih', 7, 85, 1039, 'And to [the people of] Madyan [We sent] their brother Shu''ayb. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. So fulfill the measure and weight and do not deprive people of their due and cause not corruption upon the earth after its reformation. That is better for you, if you should be believers.', NULL, NULL, 'aab34a73e36ec78a1dc3aebcdda255f0e7680f7a8b510c32d777901703dca41d'),
  ('en.sahih', 7, 86, 1040, 'And do not sit on every path, threatening and averting from the way of Allah those who believe in Him, seeking to make it [seem] deviant. And remember when you were few and He increased you. And see how was the end of the corrupters.', NULL, NULL, '0e0ee13494032c3d235bec195bfa5d685e3830b637905b060b534a0f3ca38ed0'),
  ('en.sahih', 7, 87, 1041, 'And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allah judges between us. And He is the best of judges."', NULL, NULL, 'add6a7e44551e2aacecbc8983a07de1e0df19c19b5e4736f388ead69eb3288ee'),
  ('en.sahih', 7, 88, 1042, 'Said the eminent ones who were arrogant among his people, "We will surely evict you, O Shu''ayb, and those who have believed with you from our city, or you must return to our religion." He said, "Even if we were unwilling?"', NULL, NULL, 'f57be0e3e4514077da6203b2ce98ed6a92a79148891341f57ee0a19ed517b6fd'),
  ('en.sahih', 7, 89, 1043, 'We would have invented against Allah a lie if we returned to your religion after Allah had saved us from it. And it is not for us to return to it except that Allah, our Lord, should will. Our Lord has encompassed all things in knowledge. Upon Allah we have relied. Our Lord, decide between us and our people in truth, and You are the best of those who give decision."', NULL, NULL, 'c4d84a6bc88ac98ebcae8139bb31fce2304bb82c17a6b1e1aea677b404aaab7f'),
  ('en.sahih', 7, 90, 1044, 'Said the eminent ones who disbelieved among his people, "If you should follow Shu''ayb, indeed, you would then be losers."', NULL, NULL, 'add41da45bd9ef3d01659ce17c1d3e8ba2b157d2bbf20e66c6108a09515debcd'),
  ('en.sahih', 7, 91, 1045, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.', NULL, NULL, 'c2e2b4def718ebb3a71490370053412db1c9ad890ef7c1d3923561814cd0ad39'),
  ('en.sahih', 7, 92, 1046, 'Those who denied Shu''ayb - it was as though they had never resided there. Those who denied Shu''ayb - it was they who were the losers.', NULL, NULL, 'f96a86db8508fc4e775c3ba3690587bb7a1e1a34d07716005d02446458a2d8b7'),
  ('en.sahih', 7, 93, 1047, 'And he turned away from them and said, "O my people, I had certainly conveyed to you the messages of my Lord and advised you, so how could I grieve for a disbelieving people?"', NULL, NULL, '5743239ed24c39a6d7dd3fde872b6e5a17cefa113a4ad05ff2ff7a42a4859e0a'),
  ('en.sahih', 7, 94, 1048, 'And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allah].', NULL, NULL, 'f3d376a8dadcda22e4da4288011c1107608fac6a21d63ec5356a1088e6b11e84'),
  ('en.sahih', 7, 95, 1049, 'Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, "Our fathers [also] were touched with hardship and ease." So We seized them suddenly while they did not perceive.', NULL, NULL, '7c4fe3195abe96fd46dc9164e57d95fb6b2c32da182114bb71219e20277f9e04'),
  ('en.sahih', 7, 96, 1050, 'And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning."', NULL, NULL, '1e0ba2a49354d914c85a9a76a0277901576f6247b8c5342569e5987059941fe3'),
  ('en.sahih', 7, 97, 1051, 'Then, did the people of the cities feel secure from Our punishment coming to them at night while they were asleep?', NULL, NULL, 'e7e97351fc3be6d8cc47d54db8082ad76963d829671673a069fbce1305ccf151'),
  ('en.sahih', 7, 98, 1052, 'Or did the people of the cities feel secure from Our punishment coming to them in the morning while they were at play?', NULL, NULL, '646abc0cb0e96325be5c8cf4da8cae0ad0c51dab24075483b86d4b9530273e66'),
  ('en.sahih', 7, 99, 1053, 'Then did they feel secure from the plan of Allah? But no one feels secure from the plan of Allah except the losing people.', NULL, NULL, 'fe656445c7e6ce7069308df5fd565b622f6f4142251bfe9009ea89e17715aa46'),
  ('en.sahih', 7, 100, 1054, 'Has it not become clear to those who inherited the earth after its [previous] people that if We willed, We could afflict them for their sins? But We seal over their hearts so they do not hear.', NULL, NULL, 'ee578cea9ba0e9d1e39f9477fb420f6a2dc4f8708c74e2cc5c574774e54d3292'),
  ('en.sahih', 7, 101, 1055, 'Those cities - We relate to you, [O Muhammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before. Thus does Allah seal over the hearts of the disbelievers.', NULL, NULL, 'b750ac1ea0629848ff9b698d755092e218358e13034f1a5104200fc63c23fecf'),
  ('en.sahih', 7, 102, 1056, 'And We did not find for most of them any covenant; but indeed, We found most of them defiantly disobedient.', NULL, NULL, '42c39ae905aabfc4078539a2c3022e0712858d9eb3bee578a1d10886d8ea92f2'),
  ('en.sahih', 7, 103, 1057, 'Then We sent after them Moses with Our signs to Pharaoh and his establishment, but they were unjust toward them. So see how was the end of the corrupters.', NULL, NULL, 'f0244bbee7082c5c6a5872b34fe65b87680625dd12b4f2004607244465a65033'),
  ('en.sahih', 7, 104, 1058, 'And Moses said, "O Pharaoh, I am a messenger from the Lord of the worlds', NULL, NULL, '9b6d25944bbdca369e50e7ae3a9193acf4f07d570ec3c0ff280bc5830742fccb'),
  ('en.sahih', 7, 105, 1059, '[Who is] obligated not to say about Allah except the truth. I have come to you with clear evidence from your Lord, so send with me the Children of Israel."', NULL, NULL, 'da09109274be89a8a2ae0b208801fb7ed7bc0d67e49f7e74a6d14c07a3fc7fcc'),
  ('en.sahih', 7, 106, 1060, '[Pharaoh] said, "If you have come with a sign, then bring it forth, if you should be of the truthful."', NULL, NULL, '99acbb7d2101d65fa33d1a76f1d5ed39cedb2f43769c25c8076cd4c2cc569208'),
  ('en.sahih', 7, 107, 1061, 'So Moses threw his staff, and suddenly it was a serpent, manifest.', NULL, NULL, '4ddd469fdc89469bbbd87ce73618d40ca38fb02f4cb1db6d35dc5f3a8ad5851b'),
  ('en.sahih', 7, 108, 1062, 'And he drew out his hand; thereupon it was white [with radiance] for the observers.', NULL, NULL, '6e780694e91129808766332503a67bea41c62d30b07412dda5db7d4f265c0fc9'),
  ('en.sahih', 7, 109, 1063, 'Said the eminent among the people of Pharaoh, "Indeed, this is a learned magician', NULL, NULL, '5a2622a6f891cef74516233dcfa079cf4b4b27139044f1e193bf305a25ed7959'),
  ('en.sahih', 7, 110, 1064, 'Who wants to expel you from your land [through magic], so what do you instruct?"', NULL, NULL, 'c41fa9b108a1f7db45ed88460d00f95d6633a409e4bbc0b79b49cba7f36e45f5'),
  ('en.sahih', 7, 111, 1065, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', NULL, NULL, 'a7824df01998e6698582785af3fb4d10e71621280abdbb2bd9daa4198ac0f160'),
  ('en.sahih', 7, 112, 1066, 'Who will bring you every learned magician."', NULL, NULL, 'b7ecda4dabc58fa139fc49f25435389f0fba0d8d0b7960b2ef16809ed3752ec8'),
  ('en.sahih', 7, 113, 1067, 'And the magicians came to Pharaoh. They said, "Indeed for us is a reward if we are the predominant."', NULL, NULL, '88d4aec6279e0b9d930eb8116e6b1071b3e0ea3deec2a8b6448c748058db63f8'),
  ('en.sahih', 7, 114, 1068, 'He said, "Yes, and, [moreover], you will be among those made near [to me]."', NULL, NULL, '48ecc13c6f631b52df0e3b15dc3ef7193d360373ee59c1d4a1bbb7b3de74abd1'),
  ('en.sahih', 7, 115, 1069, 'They said, "O Moses, either you throw [your staff], or we will be the ones to throw [first]."', NULL, NULL, 'c690fac023583dc5b898944848b7eb4a05e1190d219f4bf95f2fdbdf3b813fe7'),
  ('en.sahih', 7, 116, 1070, 'He said, "Throw," and when they threw, they bewitched the eyes of the people and struck terror into them, and they presented a great [feat of] magic.', NULL, NULL, '9d0f59686de754f29f7f62b3c86bcc0099a144a1cdc3b2f5318e69752f5cd693'),
  ('en.sahih', 7, 117, 1071, 'And We inspired to Moses, "Throw your staff," and at once it devoured what they were falsifying.', NULL, NULL, '886d7026675da08c59ece66c2f48984b3be20f640824427159c846c095158e35'),
  ('en.sahih', 7, 118, 1072, 'So the truth was established, and abolished was what they were doing.', NULL, NULL, 'ecdd436e20e449c26776fee8ad0c0398d9e0b83f3b6d344faf58c3d58e5d9274'),
  ('en.sahih', 7, 119, 1073, 'And Pharaoh and his people were overcome right there and became debased.', NULL, NULL, '30e53e18e77591f11d05cf541d62576699e372a280905c50803fe49534cead3c'),
  ('en.sahih', 7, 120, 1074, 'And the magicians fell down in prostration [to Allah].', NULL, NULL, 'b21c8af42bba4f42b2f05a119ed1eb36964f5b917ed6fe8015cae5be59cb1db9'),
  ('en.sahih', 7, 121, 1075, 'They said, "We have believed in the Lord of the worlds,', NULL, NULL, '5eed1846d1feffad9dc6f30c4e2977224b87221f57bcc495e922f194e053ff56'),
  ('en.sahih', 7, 122, 1076, 'The Lord of Moses and Aaron."', NULL, NULL, '843795dffd2ca4684a2dce1061b46b0255a83d1bae06f6fab7228fd88bbff2eb'),
  ('en.sahih', 7, 123, 1077, 'Said Pharaoh, "You believed in him before I gave you permission. Indeed, this is a conspiracy which you conspired in the city to expel therefrom its people. But you are going to know.', NULL, NULL, '81af1dbfcce59472f16bd86d3b373e2ff8474cffef2610978c9b2990dab743a5'),
  ('en.sahih', 7, 124, 1078, 'I will surely cut off your hands and your feet on opposite sides; then I will surely crucify you all."', NULL, NULL, '47b87a24112586809c6a187d0c0c0269c239ec137f8cbc99dff5afe14cd24e55'),
  ('en.sahih', 7, 125, 1079, 'They said, "Indeed, to our Lord we will return.', NULL, NULL, '6a7401f9149e4f9c2b96228994ed75f09db58888e10aca08117016ecc30ed0d6'),
  ('en.sahih', 7, 126, 1080, 'And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You]."', NULL, NULL, '54edc154dae740eb1c05f92751f5671eb15ab252622627ec49e2c0af17f8d1c5'),
  ('en.sahih', 7, 127, 1081, 'And the eminent among the people of Pharaoh said," Will you leave Moses and his people to cause corruption in the land and abandon you and your gods?" [Pharaoh] said, "We will kill their sons and keep their women alive; and indeed, we are subjugators over them."', NULL, NULL, 'fc3a830a65d92d23dd2841e62badd494b648d11b1eaa7a990d23d26eef62d715'),
  ('en.sahih', 7, 128, 1082, 'Said Moses to his people, "Seek help through Allah and be patient. Indeed, the earth belongs to Allah. He causes to inherit it whom He wills of His servants. And the [best] outcome is for the righteous."', NULL, NULL, '07ead44ed0608c212233a6f5c8c88952790e612672888d26815c705d6374f62b'),
  ('en.sahih', 7, 129, 1083, 'They said, "We have been harmed before you came to us and after you have come to us." He said, "Perhaps your Lord will destroy your enemy and grant you succession in the land and see how you will do."', NULL, NULL, '30ca77ee1c6215f5679c3d756c09ab26fee647b8f9273c0abfa53243f31f5d04'),
  ('en.sahih', 7, 130, 1084, 'And We certainly seized the people of Pharaoh with years of famine and a deficiency in fruits that perhaps they would be reminded.', NULL, NULL, '8e867328d381520c46c28f6cc0bdbc92b888d2ed275eb8a2e41c9c2d340cacb4'),
  ('en.sahih', 7, 131, 1085, 'But when good came to them, they said, "This is ours [by right]." And if a bad [condition] struck them, they saw an evil omen in Moses and those with him. Unquestionably, their fortune is with Allah, but most of them do not know.', NULL, NULL, '8d4064306b4ed88c4470abf6534294dbecf99857d5767adffd8e33e60e254a11'),
  ('en.sahih', 7, 132, 1086, 'And they said, "No matter what sign you bring us with which to bewitch us, we will not be believers in you."', NULL, NULL, 'cc0f92fd1af48e568d36f23b390940baf5130f9c743d663556e73d8c4519c451'),
  ('en.sahih', 7, 133, 1087, 'So We sent upon them the flood and locusts and lice and frogs and blood as distinct signs, but they were arrogant and were a criminal people.', NULL, NULL, '29b78cc737cbd7835f757c512169626285c08ddfaca84476e0b97b8c3de19c2e'),
  ('en.sahih', 7, 134, 1088, 'And when the punishment descended upon them, they said, "O Moses, invoke for us your Lord by what He has promised you. If you [can] remove the punishment from us, we will surely believe you, and we will send with you the Children of Israel."', NULL, NULL, '0bed918c0e4155a112c6e05b3dbde1f1149ce6d3f16c5d8b9a89db7ded0d38d5'),
  ('en.sahih', 7, 135, 1089, 'But when We removed the punishment from them until a term which they were to reach, then at once they broke their word.', NULL, NULL, 'e197d48617689ee67bb4de5419a26706215bb383f7d5b18cbc0e475ad3873760'),
  ('en.sahih', 7, 136, 1090, 'So We took retribution from them, and We drowned them in the sea because they denied Our signs and were heedless of them.', NULL, NULL, 'c5d417e49b4ee130bdd013d5b3701be0a94188631c1afc1923237bf7e25f4ea5'),
  ('en.sahih', 7, 137, 1091, 'And We caused the people who had been oppressed to inherit the eastern regions of the land and the western ones, which We had blessed. And the good word of your Lord was fulfilled for the Children of Israel because of what they had patiently endured. And We destroyed [all] that Pharaoh and his people were producing and what they had been building.', NULL, NULL, 'afca3146dc0613230a240b9ded9e2ef6d99848d86aaec7575b30cec03c76cfff'),
  ('en.sahih', 7, 138, 1092, 'And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They said, "O Moses, make for us a god just as they have gods." He said, "Indeed, you are a people behaving ignorantly.', NULL, NULL, 'a518fa3b1b842d86d6424b5ce8b5566bcfa80306edd10a66eb328af38d1db09a'),
  ('en.sahih', 7, 139, 1093, 'Indeed, those [worshippers] - destroyed is that in which they are [engaged], and worthless is whatever they were doing."', NULL, NULL, 'b0bd8e6737d77e44f97e96185330fc0d0dbe224c36d6daa075e95d2428c56231'),
  ('en.sahih', 7, 140, 1094, 'He said, "Is it other than Allah I should desire for you as a god while He has preferred you over the worlds?"', NULL, NULL, '2377b6ce8ff7ba6397d569caffead5e285a8648e5dec037dfc12282790041608'),
  ('en.sahih', 7, 141, 1095, 'And [recall, O Children of Israel], when We saved you from the people of Pharaoh, [who were] afflicting you with the worst torment - killing your sons and keeping your women alive. And in that was a great trial from your Lord.', NULL, NULL, 'cb01594b05a0f67e3746582df3b07d27643009e059b14d77d39a7b05aba0500b'),
  ('en.sahih', 7, 142, 1096, 'And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, "Take my place among my people, do right [by them], and do not follow the way of the corrupters."', NULL, NULL, 'fe0223ca75f8aef4e8d89edb9f75b39670a1d995f26c0a040295442b9258a965'),
  ('en.sahih', 7, 143, 1097, 'And when Moses arrived at Our appointed time and his Lord spoke to him, he said, "My Lord, show me [Yourself] that I may look at You." [Allah] said, "You will not see Me, but look at the mountain; if it should remain in place, then you will see Me." But when his Lord appeared to the mountain, He rendered it level, and Moses fell unconscious. And when he awoke, he said, "Exalted are You! I have repented to You, and I am the first of the believers."', NULL, NULL, '897850182a470791afb44db48636615f42c280d55e04335d18f009111659b746'),
  ('en.sahih', 7, 144, 1098, '[Allah] said, "O Moses, I have chosen you over the people with My messages and My words [to you]. So take what I have given you and be among the grateful."', NULL, NULL, '05aa6f7b2ea9ff9ca7fb98d51db846ce24a7a1482639bd42958d01bb5fbffcba'),
  ('en.sahih', 7, 145, 1099, 'And We wrote for him on the tablets [something] of all things - instruction and explanation for all things, [saying], "Take them with determination and order your people to take the best of it. I will show you the home of the defiantly disobedient."', NULL, NULL, '43adc3ca5fd36570aa8dd82255be88fa744b324176b9114235df7d953901dc7b'),
  ('en.sahih', 7, 146, 1100, 'I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them.', NULL, NULL, '972d5f4ec98ec2904f169d12d3e838e4d84ad378cdf40bf56f8e963169c71520')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 7, 147, 1101, 'Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?', NULL, NULL, 'a206fe18e510df7feefe1918abc2cdb414aea7f3dc8530abd7d076bad6f1d1d2'),
  ('en.sahih', 7, 148, 1102, 'And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers.', NULL, NULL, 'bac8e454da1a68e7aabc421a5883615dd13e7aa4fae578b605d3f4ac9afbd290'),
  ('en.sahih', 7, 149, 1103, 'And when regret overcame them and they saw that they had gone astray, they said, "If our Lord does not have mercy upon us and forgive us, we will surely be among the losers."', NULL, NULL, 'de981e6c44865de3949696b1fe71a81113e4aeab476e11d5f2abb2a85a5c521d'),
  ('en.sahih', 7, 150, 1104, 'And when Moses returned to his people, angry and grieved, he said, "How wretched is that by which you have replaced me after [my departure]. Were you impatient over the matter of your Lord?" And he threw down the tablets and seized his brother by [the hair of] his head, pulling him toward him. [Aaron] said, "O son of my mother, indeed the people oppressed me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people."', NULL, NULL, '7110d421214f4fa9be901e484ead92b4d62c73e526431457b6e3941e08e35ffb'),
  ('en.sahih', 7, 151, 1105, '[Moses] said, "My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful."', NULL, NULL, '9162d1896fcbf2951245d10d93e897818f01bbe5a22e44855201c4b5564d7e18'),
  ('en.sahih', 7, 152, 1106, 'Indeed, those who took the calf [for worship] will obtain anger from their Lord and humiliation in the life of this world, and thus do We recompense the inventors [of falsehood].', NULL, NULL, 'b82e43d7cc0755afadc1276786675f00453343d9c261669b63132c6358cd1af6'),
  ('en.sahih', 7, 153, 1107, 'But those who committed misdeeds and then repented after them and believed - indeed your Lord, thereafter, is Forgiving and Merciful.', NULL, NULL, 'bb361e604e27e73cd87b79ad73b8c203b9436a36770b78d9322b1d07efc19592'),
  ('en.sahih', 7, 154, 1108, 'And when the anger subsided in Moses, he took up the tablets; and in their inscription was guidance and mercy for those who are fearful of their Lord.', NULL, NULL, 'b4c59e5f9fbd00f8754a927e140b5976d7047685c031a361179996e7e48b298c'),
  ('en.sahih', 7, 155, 1109, 'And Moses chose from his people seventy men for Our appointment. And when the earthquake seized them, he said, "My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers.', NULL, NULL, '98c93bc293d105b41bc4a10b5ce90aafab6d48b91c14db6d40614b7b4a35f8ca'),
  ('en.sahih', 7, 156, 1110, 'And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You." [Allah] said, "My punishment - I afflict with it whom I will, but My mercy encompasses all things." So I will decree it [especially] for those who fear Me and give zakah and those who believe in Our verses -', NULL, NULL, 'ea3112f205cfbcf31ca7e68201c6394075e61228ed60e32b88329bfad2cead5d'),
  ('en.sahih', 7, 157, 1111, 'Those who follow the Messenger, the unlettered prophet, whom they find written in what they have of the Torah and the Gospel, who enjoins upon them what is right and forbids them what is wrong and makes lawful for them the good things and prohibits for them the evil and relieves them of their burden and the shackles which were upon them. So they who have believed in him, honored him, supported him and followed the light which was sent down with him - it is those who will be the successful.', NULL, NULL, '98d9f15f5a2c8daacc5da7587e599a49a0bc878b4a2331c9df86163944e0b5a9'),
  ('en.sahih', 7, 158, 1112, 'Say, [O Muhammad], "O mankind, indeed I am the Messenger of Allah to you all, [from Him] to whom belongs the dominion of the heavens and the earth. There is no deity except Him; He gives life and causes death." So believe in Allah and His Messenger, the unlettered prophet, who believes in Allah and His words, and follow him that you may be guided.', NULL, NULL, '0b780736e7a471512d6a95127f6888ed2b2a43f228f19da4aa6439e656750531'),
  ('en.sahih', 7, 159, 1113, 'And among the people of Moses is a community which guides by truth and by it establishes justice.', NULL, NULL, '5e7e6ad1a085202a7913889f4eea3ba12b03222828d53d8063bc8607df90995a'),
  ('en.sahih', 7, 160, 1114, 'And We divided them into twelve descendant tribes [as distinct] nations. And We inspired to Moses when his people implored him for water, "Strike with your staff the stone," and there gushed forth from it twelve springs. Every people knew its watering place. And We shaded them with clouds and sent down upon them manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not, but they were [only] wronging themselves.', NULL, NULL, '0317201d20240d7526892bc6cb5e06583e2cb787fe3fd3bd50ba593a084506cf'),
  ('en.sahih', 7, 161, 1115, 'And [mention, O Muhammad], when it was said to them, "Dwell in this city and eat from it wherever you will and say, ''Relieve us of our burdens,'' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward]."', NULL, NULL, 'ea030d1831e820a6a9466344dc31357d97b9cb9e116f3086daa7b2ed4cb20fc6'),
  ('en.sahih', 7, 162, 1116, 'But those who wronged among them changed [the words] to a statement other than that which had been said to them. So We sent upon them a punishment from the sky for the wrong that they were doing.', NULL, NULL, 'df0b6eb4aaece16dd6c31421b50acdf21a15cb88a2f6c04b38a4e4cc924797dd'),
  ('en.sahih', 7, 163, 1117, 'And ask them about the town that was by the sea - when they transgressed in [the matter of] the sabbath - when their fish came to them openly on their sabbath day, and the day they had no sabbath they did not come to them. Thus did We give them trial because they were defiantly disobedient.', NULL, NULL, 'f84062e53884cc34aa8a189f900b8d5db9b6d3ae85858c5f47bce6e91d26c0a8'),
  ('en.sahih', 7, 164, 1118, 'And when a community among them said, "Why do you advise [or warn] a people whom Allah is [about] to destroy or to punish with a severe punishment?" they [the advisors] said, "To be absolved before your Lord and perhaps they may fear Him."', NULL, NULL, 'd7d095a76f29f9235661a58fce13f184bd45e128936956a6842928df94593775'),
  ('en.sahih', 7, 165, 1119, 'And when they forgot that by which they had been reminded, We saved those who had forbidden evil and seized those who wronged, with a wretched punishment, because they were defiantly disobeying.', NULL, NULL, '8ae8569b34d14421e798c282f9fd8352b59cd8ba84eb0637daa72833059ae0e9'),
  ('en.sahih', 7, 166, 1120, 'So when they were insolent about that which they had been forbidden, We said to them, "Be apes, despised."', NULL, NULL, '2e2dd5708c0167db55c6540aecb7b6cae65a03e1790e99313d5670182574ea2c'),
  ('en.sahih', 7, 167, 1121, 'And [mention] when your Lord declared that He would surely [continue to] send upon them until the Day of Resurrection those who would afflict them with the worst torment. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.', NULL, NULL, 'be32fe50886f668bf9d36f7b3246ecc91644f5ae5718188107e4e409f0fc4ee7'),
  ('en.sahih', 7, 168, 1122, 'And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience].', NULL, NULL, '436ce484bc530cad2f6df36d0b95097ddbb93ea9dedffdaa2172c8039f9b0700'),
  ('en.sahih', 7, 169, 1123, 'And there followed them successors who inherited the Scripture [while] taking the commodities of this lower life and saying, "It will be forgiven for us." And if an offer like it comes to them, they will [again] take it. Was not the covenant of the Scripture taken from them that they would not say about Allah except the truth, and they studied what was in it? And the home of the Hereafter is better for those who fear Allah, so will you not use reason?', NULL, NULL, 'fa7cd673f380d72ec21610dfb711d7b5290471d05c5b01d26413c690decd3a32'),
  ('en.sahih', 7, 170, 1124, 'But those who hold fast to the Book and establish prayer - indeed, We will not allow to be lost the reward of the reformers.', NULL, NULL, 'b9f2997b247565b98ea17fcdbed683ce133c986948b38f6773b87ca4a400ea61'),
  ('en.sahih', 7, 171, 1125, 'And [mention] when We raised the mountain above them as if it was a dark cloud and they were certain that it would fall upon them, [and Allah said], "Take what We have given you with determination and remember what is in it that you might fear Allah."', NULL, NULL, '4f58f0e3ed7fc83d8b6749152e911cadcb9dcd546477f74ec0b7ea1bc642d725'),
  ('en.sahih', 7, 172, 1126, 'And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], "Am I not your Lord?" They said, "Yes, we have testified." [This] - lest you should say on the day of Resurrection, "Indeed, we were of this unaware."', NULL, NULL, '0db56581705ce769777e600576d72f558166b45afbc6355cb8ff4ba27713dbff'),
  ('en.sahih', 7, 173, 1127, 'Or [lest] you say, "It was only that our fathers associated [others in worship] with Allah before, and we were but descendants after them. Then would You destroy us for what the falsifiers have done?"', NULL, NULL, '44ae71305db5aad65b378e6727faa046708700e9a6ca4da343b8901ecfbe2445'),
  ('en.sahih', 7, 174, 1128, 'And thus do We [explain in] detail the verses, and perhaps they will return.', NULL, NULL, '5efb48decbdee51ad0e52faba4d5bf58cbdbf0b562beb6f62c0def515735c7c8'),
  ('en.sahih', 7, 175, 1129, 'And recite to them, [O Muhammad], the news of him to whom we gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators.', NULL, NULL, 'ac0a592bb27ab821a74658aafc8b6901cfed776b12b15b70b5fa08ecdb8a6260'),
  ('en.sahih', 7, 176, 1130, 'And if We had willed, we could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought.', NULL, NULL, '8ac1135a44f71e6e39cdf81c14b1ad0ad66dae15db26b6085468d2d293468c92'),
  ('en.sahih', 7, 177, 1131, 'How evil an example [is that of] the people who denied Our signs and used to wrong themselves.', NULL, NULL, '1dc82757e80c8fa3941b0e80ddd6b8c33a3550242ea42cd46bf6c7560a13cf21'),
  ('en.sahih', 7, 178, 1132, 'Whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - it is those who are the losers.', NULL, NULL, 'f0e2168d01633207d3a492be7f81667a351c09199409f30372f6099e342cd3ba'),
  ('en.sahih', 7, 179, 1133, 'And We have certainly created for Hell many of the jinn and mankind. They have hearts with which they do not understand, they have eyes with which they do not see, and they have ears with which they do not hear. Those are like livestock; rather, they are more astray. It is they who are the heedless.', NULL, NULL, '3e601d1c635b3514dc3eadfc24adc548b3fd756ebdaff818fccdf88d4ef0b583'),
  ('en.sahih', 7, 180, 1134, 'And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing.', NULL, NULL, '953a48df57a971b626f356771fdf39b84f5851faa8d6b7aa282825b3e2551927'),
  ('en.sahih', 7, 181, 1135, 'And among those We created is a community which guides by truth and thereby establishes justice.', NULL, NULL, 'd033c92942f8ac492b9f479bfe201a07c0ed73db6e54f8eaae3e6daea25553d9'),
  ('en.sahih', 7, 182, 1136, 'But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know.', NULL, NULL, 'aaceecf054a1a2b230bdee5d4499bea50d48c2aa5f47d00c19d205e94704d77e'),
  ('en.sahih', 7, 183, 1137, 'And I will give them time. Indeed, my plan is firm.', NULL, NULL, 'e57965cff836eba7aa99a3068c89afa586d472460d20088bb6e3da4a1db2d041'),
  ('en.sahih', 7, 184, 1138, 'Then do they not give thought? There is in their companion [Muhammad] no madness. He is not but a clear warner.', NULL, NULL, '019cb040acc57f07b69c30b75d5f5579dcaa8e035dbd84e4e64e200aa4a75697'),
  ('en.sahih', 7, 185, 1139, 'Do they not look into the realm of the heavens and the earth and everything that Allah has created and [think] that perhaps their appointed time has come near? So in what statement hereafter will they believe?', NULL, NULL, '86259208569dbe1e007cb0411dcbe0e9af22004985599943ad07d23ae328bffb'),
  ('en.sahih', 7, 186, 1140, 'Whoever Allah sends astray - there is no guide for him. And He leaves them in their transgression, wandering blindly.', NULL, NULL, 'bbe6b080feaa8023f1b5a2309eab572bfa478d57b265a34ba1f0e0177b4acff2'),
  ('en.sahih', 7, 187, 1141, 'They ask you, [O Muhammad], about the Hour: when is its arrival? Say, "Its knowledge is only with my Lord. None will reveal its time except Him. It lays heavily upon the heavens and the earth. It will not come upon you except unexpectedly." They ask you as if you are familiar with it. Say, "Its knowledge is only with Allah, but most of the people do not know."', NULL, NULL, 'a0e20591f9d5075459ea42323d8d63956c45549b9867ba87015fc864ba25e574'),
  ('en.sahih', 7, 188, 1142, 'Say, "I hold not for myself [the power of] benefit or harm, except what Allah has willed. And if I knew the unseen, I could have acquired much wealth, and no harm would have touched me. I am not except a warner and a bringer of good tidings to a people who believe."', NULL, NULL, '18d023be6ae0810ef69cedc5b7fb1a56a56a8914b42a9872d80f045a4038eadc'),
  ('en.sahih', 7, 189, 1143, 'It is He who created you from one soul and created from it its mate that he might dwell in security with her. And when he covers her, she carries a light burden and continues therein. And when it becomes heavy, they both invoke Allah, their Lord, "If You should give us a good [child], we will surely be among the grateful."', NULL, NULL, '0c8e2797833c6d9a0e24e649f637fbe4fc4f7116702e6dbc342175187b0b682c'),
  ('en.sahih', 7, 190, 1144, 'But when He gives them a good [child], they ascribe partners to Him concerning that which He has given them. Exalted is Allah above what they associate with Him.', NULL, NULL, '4d2c12b6bb986e3138eb8a41772abea039177bf331d4711196c3dac77208c65b'),
  ('en.sahih', 7, 191, 1145, 'Do they associate with Him those who create nothing and they are [themselves] created?', NULL, NULL, '96e068af8342f7c4b10bb72e606f53311b2f6f20e9b35fbed3b07604bb1e56b6'),
  ('en.sahih', 7, 192, 1146, 'And the false deities are unable to [give] them help, nor can they help themselves.', NULL, NULL, 'd8d2c9b69408e1bb481279b0424f2a8c2240b31e105b14dafc6ce6f17ec8a488'),
  ('en.sahih', 7, 193, 1147, 'And if you [believers] invite them to guidance, they will not follow you. It is all the same for you whether you invite them or you are silent.', NULL, NULL, '7958b338ddc428547c5cd1d2873cd35f236301d66c2ae1ba32803efe5cf6c279'),
  ('en.sahih', 7, 194, 1148, 'Indeed, those you [polytheists] call upon besides Allah are servants like you. So call upon them and let them respond to you, if you should be truthful.', NULL, NULL, 'edeff987a8c9f904ec548ec3ff3695b789cb88218879177a16656138caeec853'),
  ('en.sahih', 7, 195, 1149, 'Do they have feet by which they walk? Or do they have hands by which they strike? Or do they have eyes by which they see? Or do they have ears by which they hear? Say, [O Muhammad], "Call your ''partners'' and then conspire against me and give me no respite.', NULL, NULL, 'a44924c97723e114b6424e63ac03ca8898e3c3112a997456d7918b44b010d9c5'),
  ('en.sahih', 7, 196, 1150, 'Indeed, my protector is Allah, who has sent down the Book; and He is an ally to the righteous.', NULL, NULL, '91ef986eb3e90bec024d1a758aaff670125f0307754c6118620afad4589c8a24'),
  ('en.sahih', 7, 197, 1151, 'And those you call upon besides Him are unable to help you, nor can they help themselves."', NULL, NULL, '373c7b83d069776062f8bc6b4c81f6b26143271ed8d2b574d8ae20ba7d86a637'),
  ('en.sahih', 7, 198, 1152, 'And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see.', NULL, NULL, 'e4bf051e531721d5a4823f90875f97b7b2e21e7086dc5023dd9025b222b106ce'),
  ('en.sahih', 7, 199, 1153, 'Take what is given freely, enjoin what is good, and turn away from the ignorant.', NULL, NULL, '9b8436daff7506bc87fb9fb909c51893e1d666700e19e11f8c0f21afb94185d1'),
  ('en.sahih', 7, 200, 1154, 'And if an evil suggestion comes to you from Satan, then seek refuge in Allah. Indeed, He is Hearing and Knowing.', NULL, NULL, 'd70a3aa110adae23c4f801022e61682b2646d35e24f73f44e371a11031e69d84'),
  ('en.sahih', 7, 201, 1155, 'Indeed, those who fear Allah - when an impulse touches them from Satan, they remember [Him] and at once they have insight.', NULL, NULL, '7864a813aa78f949e9032fc0eb4e326386316e7112fc2a2bbd95d4be66a728de'),
  ('en.sahih', 7, 202, 1156, 'But their brothers - the devils increase them in error; then they do not stop short.', NULL, NULL, '7cf7d95ff7d22a6e170e0ecb8deeb71232b71e593d30c6daaf7a1c07bd9c3f70'),
  ('en.sahih', 7, 203, 1157, 'And when you, [O Muhammad], do not bring them a sign, they say, "Why have you not contrived it?" Say, "I only follow what is revealed to me from my Lord. This [Qur''an] is enlightenment from your Lord and guidance and mercy for a people who believe."', NULL, NULL, '480a021bc62f182c87e8cf36e99c14725009e5e26e3ec0ebac87c0c063bf2707'),
  ('en.sahih', 7, 204, 1158, 'So when the Qur''an is recited, then listen to it and pay attention that you may receive mercy.', NULL, NULL, '4123de9835731949d836639f8d0e692f07c0e79bb4e27926ddc867907fefcb32'),
  ('en.sahih', 7, 205, 1159, 'And remember your Lord within yourself in humility and in fear without being apparent in speech - in the mornings and the evenings. And do not be among the heedless.', NULL, NULL, 'c67767906efd5609dab69250bd0dad5fc2ee53ef268343696e587f065e34237d'),
  ('en.sahih', 7, 206, 1160, 'Indeed, those who are near your Lord are not prevented by arrogance from His worship, and they exalt Him, and to Him they prostrate.', NULL, NULL, 'e8dce04f33c245daced212ad901f01b320d26723a4bb83f407627e8e481fb20f'),
  ('en.sahih', 8, 1, 1161, 'They ask you, [O Muhammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allah and the Messenger." So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers.', NULL, NULL, '621a9c2e6d3ebbfb1d0e5189fcacb325618639953b2fd55aab7996c4031da114'),
  ('en.sahih', 8, 2, 1162, 'The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -', NULL, NULL, '02c27c71dc4c62b027c25d439ae09ccbb981ff888467d1459a8760abbbefede8'),
  ('en.sahih', 8, 3, 1163, 'The ones who establish prayer, and from what We have provided them, they spend.', NULL, NULL, '9e3bd31a5e115c0aa6715eecddf06326fc1db23c324763d8138e2d286f3aed21'),
  ('en.sahih', 8, 4, 1164, 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.', NULL, NULL, '35c7e4c8b3707d6a2e945bc23f60166e57139b67de43b75bc25aec1371d0d40b'),
  ('en.sahih', 8, 5, 1165, '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,', NULL, NULL, '6d8087fe3bd099a78300e61a607ee98b5a8abf6b503b1dd6c821050c6af576b2'),
  ('en.sahih', 8, 6, 1166, 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.', NULL, NULL, 'c5297378ae0e2aa4285ce33e3a234ee69fd5e83f8c8d939d6897c86195f28728'),
  ('en.sahih', 8, 7, 1167, '[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers', NULL, NULL, '2511beb2db33ff6c590018f3531aeb4af38198264c1410fa61f0626613aabc39'),
  ('en.sahih', 8, 8, 1168, 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.', NULL, NULL, 'd4cb865f8345390e3dd28f145b98ad50bc5fbd9be21691779bacf4ded2bc52d2'),
  ('en.sahih', 8, 9, 1169, '[Remember] when you asked help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."', NULL, NULL, 'be61d656d1f5ce0780ffbec9cb4c988faf660bb7861a69b7e3ba27aa76fbc0b0'),
  ('en.sahih', 8, 10, 1170, 'And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise.', NULL, NULL, 'e900e86601c705326687dde3345e903fea168c3fbfeb8336c6a3f95a5ffc71a6'),
  ('en.sahih', 8, 11, 1171, '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.', NULL, NULL, '87f4c1ef818a6a7008d086fd041750475c0bc4e4dbc0c88d06957c9ea686e571'),
  ('en.sahih', 8, 12, 1172, '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."', NULL, NULL, '461d97bdf0f81f0a5eebb737d8f76ecaef7cbf702fd956bf4347feab6258bf26'),
  ('en.sahih', 8, 13, 1173, 'That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty.', NULL, NULL, '7b0457cb79e0b4339d65dc244ffbe65509d1f003a2f9d4c51dadc143ac0cf4c5'),
  ('en.sahih', 8, 14, 1174, '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.', NULL, NULL, '3825085fa6e47bd08d1333151b1c17e040c7c6dd93585174fc93fd8994ee8ee4'),
  ('en.sahih', 8, 15, 1175, 'O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight].', NULL, NULL, 'd5a160836ad8b882869853b925bbb158828b1a3b7c139643d9d88e4db31b2172'),
  ('en.sahih', 8, 16, 1176, 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination.', NULL, NULL, 'ed2b18f0f9020000ad4e01364e31c65884118ece4936c232ba5ea5b35c5e284a'),
  ('en.sahih', 8, 17, 1177, 'And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing.', NULL, NULL, '8703171eb0e4d51d448da6c1c111faba2392c75318f38a57e49dc008c6d38d43'),
  ('en.sahih', 8, 18, 1178, 'That [is so], and [also] that Allah will weaken the plot of the disbelievers.', NULL, NULL, '25a0eec61f498d277e48e1a0703ec3f42b8fe7f838751d9c347db68c272ea5ac'),
  ('en.sahih', 8, 19, 1179, 'If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers.', NULL, NULL, '1ee828c9b8baf512c906f401d1069adcf157ad28ce989643c93ebbf2d49a03f3'),
  ('en.sahih', 8, 20, 1180, 'O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order].', NULL, NULL, '76a07e7e10d7bc22b4e637f197567859e774d94505874a11d85d551e7df97e23'),
  ('en.sahih', 8, 21, 1181, 'And do not be like those who say, "We have heard," while they do not hear.', NULL, NULL, 'e5d1e81dd59b994085e8130a649905d2646ea679bba0590f15ef4fc39d002a0d'),
  ('en.sahih', 8, 22, 1182, 'Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.', NULL, NULL, 'b4d3e5187040a3ceeb0f7cba1d9f1e65b3d4a0523e7e850aaeeb608771d8f8df'),
  ('en.sahih', 8, 23, 1183, 'Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.', NULL, NULL, 'e53786836960a9ce1e8824856d64864c7daf8035e2d07f037ff5426285bf348a'),
  ('en.sahih', 8, 24, 1184, 'O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered.', NULL, NULL, '1022ba942a3dd110d86b8f8eab3b93c5149840a710e9c1b1cfa675d441bdfd4f'),
  ('en.sahih', 8, 25, 1185, 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty.', NULL, NULL, '38ed8b0d06e046d3af5357d8e20852cd56967edda08d929a9c62cd1592489a91'),
  ('en.sahih', 8, 26, 1186, 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.', NULL, NULL, '972a09c4e01f45dd7e434b8c4ce10fa29459f022b5cd996b08f08cb1275dc1d3'),
  ('en.sahih', 8, 27, 1187, 'O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence].', NULL, NULL, '23522b13078538d908373b0435817d44eb0e4c753ff8520b3f87e182bdeb9f81'),
  ('en.sahih', 8, 28, 1188, 'And know that your properties and your children are but a trial and that Allah has with Him a great reward.', NULL, NULL, '9794753eb9e960594a1e734825157e2659863729fc0b9cf19b9393164061ed6e'),
  ('en.sahih', 8, 29, 1189, 'O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty.', NULL, NULL, '741145c05abef8b2035bfc94d17df81424e90363450466f367cd0481f02514bc'),
  ('en.sahih', 8, 30, 1190, 'And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners.', NULL, NULL, 'b6a5a577ae38c0721f8a310f4ad93b58a0f2211ec0b06603aa6037d1c3a0d974'),
  ('en.sahih', 8, 31, 1191, 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."', NULL, NULL, 'dc43d695e39bd71f1b33926c5e9713e3b31e2c535ebceeeaeac5578ee68e03f0'),
  ('en.sahih', 8, 32, 1192, 'And [remember] when they said, "O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."', NULL, NULL, '973bc8586445ccf20411d2e1740d06c97d15dce52fb9f8e12d3ef353f8c55d96'),
  ('en.sahih', 8, 33, 1193, 'But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness.', NULL, NULL, '5aad59344ffc0b735fa2553be2213939ce9d88d98b76695af69f331e4f95895c'),
  ('en.sahih', 8, 34, 1194, 'But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.', NULL, NULL, '447f18195587184148dd4c66ba4805756cbff1822d6304f519cb562378379c0e'),
  ('en.sahih', 8, 35, 1195, 'And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved.', NULL, NULL, '2507cab03a42aeeb5583864ca61e804792f661fa6b689152fcc6aa8d4d428b71'),
  ('en.sahih', 8, 36, 1196, 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.', NULL, NULL, '697457f1acc6924064d3a55d96cdb03afbab6e5a279eab068c84b20f36dc329e'),
  ('en.sahih', 8, 37, 1197, '[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.', NULL, NULL, '33c4d07a78a02dd8834fe528e5324cd240529614a20f1b055b9c4befb6cf10c2'),
  ('en.sahih', 8, 38, 1198, 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.', NULL, NULL, '96085692eb9d4471545c581647c918bf64d5e5efebe5fce5408f3a74afe5cd15'),
  ('en.sahih', 8, 39, 1199, 'And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do.', NULL, NULL, 'f414cf0e9ab1fae68d17232785f5f469c46ef6571f343e77cac3aa22c83bb3b2'),
  ('en.sahih', 8, 40, 1200, 'But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper.', NULL, NULL, 'dc5ee0884764473598ea3cfc2de20c7047ef49f2b3c23c07363a2d33974225d9')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 8, 41, 1201, 'And know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allah and in that which We sent down to Our Servant on the day of criterion - the day when the two armies met. And Allah, over all things, is competent.', NULL, NULL, '69b110d67d3dbb602870381cd1a2d94198c9be9f9b3437b7adfe1abf6aff0178'),
  ('en.sahih', 8, 42, 1202, '[Remember] when you were on the near side of the valley, and they were on the farther side, and the caravan was lower [in position] than you. If you had made an appointment [to meet], you would have missed the appointment. But [it was] so that Allah might accomplish a matter already destined - that those who perished [through disbelief] would perish upon evidence and those who lived [in faith] would live upon evidence; and indeed, Allah is Hearing and Knowing.', NULL, NULL, 'b58c773736c1e088520e57372243d83aafb9772e44535767c0331b01a71b5316'),
  ('en.sahih', 8, 43, 1203, '[Remember, O Muhammad], when Allah showed them to you in your dream as few; and if He had shown them to you as many, you [believers] would have lost courage and would have disputed in the matter [of whether to fight], but Allah saved [you from that]. Indeed, He is Knowing of that within the breasts.', NULL, NULL, 'd4fd622bcd858a04cfd364ca66957b03efff67ee2aa475212542703ff0b68d2f'),
  ('en.sahih', 8, 44, 1204, 'And [remember] when He showed them to you, when you met, as few in your eyes, and He made you [appear] as few in their eyes so that Allah might accomplish a matter already destined. And to Allah are [all] matters returned.', NULL, NULL, 'bb94b193d02ce125e6aaed4cdf67c699dc9872a37c49057624b3b641c95b14b0'),
  ('en.sahih', 8, 45, 1205, 'O you who have believed, when you encounter a company [from the enemy forces], stand firm and remember Allah much that you may be successful.', NULL, NULL, 'b13ea85ec90782cc10927fad5bc5b5a24f9f1b4098b5d1eae785585f61730baf'),
  ('en.sahih', 8, 46, 1206, 'And obey Allah and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allah is with the patient.', NULL, NULL, '7303ce6c7333a23c5ea20c1e55e9981e860125931a8a6e38e0ab1d42dfdc8afb'),
  ('en.sahih', 8, 47, 1207, 'And do not be like those who came forth from their homes insolently and to be seen by people and avert [them] from the way of Allah. And Allah is encompassing of what they do.', NULL, NULL, '99378fbaf4e6410b60ec846cb040837ec19f348bff6ae1c07f0af893e7c349c4'),
  ('en.sahih', 8, 48, 1208, 'And [remember] when Satan made their deeds pleasing to them and said, "No one can overcome you today from among the people, and indeed, I am your protector." But when the two armies sighted each other, he turned on his heels and said, "Indeed, I am disassociated from you. Indeed, I see what you do not see; indeed I fear Allah. And Allah is severe in penalty."', NULL, NULL, '153e59dea683a658c96874da56152322797cbf734f4f580daf1b30e5651259f7'),
  ('en.sahih', 8, 49, 1209, '[Remember] when the hypocrites and those in whose hearts was disease said, "Their religion has deluded those [Muslims]." But whoever relies upon Allah - then indeed, Allah is Exalted in Might and Wise.', NULL, NULL, '7a4a3fb51b4c4f5bbba896e21ff68f5e04a218f50bf3071bee86ee6f60d53ad6'),
  ('en.sahih', 8, 50, 1210, 'And if you could but see when the angels take the souls of those who disbelieved... They are striking their faces and their backs and [saying], "Taste the punishment of the Burning Fire.', NULL, NULL, '28b6e41e30b96af1bf2ae52acea967c69b8435f10d6c2c142a1b6a4fecbbcdf8'),
  ('en.sahih', 8, 51, 1211, 'That is for what your hands have put forth [of evil] and because Allah is not ever unjust to His servants."', NULL, NULL, '2677eba13157ef0cdd1611066d0d21ba7ca0d0f5578490816116e8e2879e3f96'),
  ('en.sahih', 8, 52, 1212, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allah, so Allah seized them for their sins. Indeed, Allah is Powerful and severe in penalty.', NULL, NULL, 'c3955571ff2b205b3f66cee67baab572ad7de41ca2138f3168551244cca97cec'),
  ('en.sahih', 8, 53, 1213, 'That is because Allah would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allah is Hearing and Knowing.', NULL, NULL, 'e10e1ee45d453c0763755786be2848dd42cb24e61a4dd0b8ddff55b34f52db8e'),
  ('en.sahih', 8, 54, 1214, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They denied the signs of their Lord, so We destroyed them for their sins, and We drowned the people of Pharaoh. And all [of them] were wrongdoers.', NULL, NULL, '7893a753865701c2cf9800921b1412aa4ce70061a64efca262c2e4ccd008b28d'),
  ('en.sahih', 8, 55, 1215, 'Indeed, the worst of living creatures in the sight of Allah are those who have disbelieved, and they will not [ever] believe -', NULL, NULL, '6419b81261691fcd443ff61b7e145831f4baf2f4edac1731f736b3335881db4f'),
  ('en.sahih', 8, 56, 1216, 'The ones with whom you made a treaty but then they break their pledge every time, and they do not fear Allah.', NULL, NULL, '2dc09ea6fe268d66b577c7fc3148163dcc8a84c6ff722464fd8fa6fe73039510'),
  ('en.sahih', 8, 57, 1217, 'So if you, [O Muhammad], gain dominance over them in war, disperse by [means of] them those behind them that perhaps they will be reminded.', NULL, NULL, '44bcf3a07aae62ccfac1d30d2ce3f85b2f0373af5b98dc1951dfd95c79895173'),
  ('en.sahih', 8, 58, 1218, 'If you [have reason to] fear from a people betrayal, throw [their treaty] back to them, [putting you] on equal terms. Indeed, Allah does not like traitors.', NULL, NULL, '74a3052f4ed892e6543174c98dcdc7bbbe0609ece704ed99e56de916df8fd00d'),
  ('en.sahih', 8, 59, 1219, 'And let not those who disbelieve think they will escape. Indeed, they will not cause failure [to Allah].', NULL, NULL, '043d881280b68f954215c4bdecb75731c058cf0eb49e31e41f10fa6478fda543'),
  ('en.sahih', 8, 60, 1220, 'And prepare against them whatever you are able of power and of steeds of war by which you may terrify the enemy of Allah and your enemy and others besides them whom you do not know [but] whom Allah knows. And whatever you spend in the cause of Allah will be fully repaid to you, and you will not be wronged.', NULL, NULL, '6b35ce034f113a49795d7133a1d8021026a0a2d40f4dfbd649ca6490a0c8d273'),
  ('en.sahih', 8, 61, 1221, 'And if they incline to peace, then incline to it [also] and rely upon Allah. Indeed, it is He who is the Hearing, the Knowing.', NULL, NULL, '7072028162d8487434495af283d57805aa3d77acd5001b5195aa428207d99043'),
  ('en.sahih', 8, 62, 1222, 'But if they intend to deceive you - then sufficient for you is Allah. It is He who supported you with His help and with the believers', NULL, NULL, '1cf83386582c050a6d5c907f506a8979919796aa927386bb75a97118bbc400fe'),
  ('en.sahih', 8, 63, 1223, 'And brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allah brought them together. Indeed, He is Exalted in Might and Wise.', NULL, NULL, '033938207d45114b3997f6ac8c5d8ea52f2d884065f77d8f52815a168642e0ed'),
  ('en.sahih', 8, 64, 1224, 'O Prophet, sufficient for you is Allah and for whoever follows you of the believers.', NULL, NULL, '93c721c3179a5836593ffc0488c4fed981300259986eb1f1345758c886fef18e'),
  ('en.sahih', 8, 65, 1225, 'O Prophet, urge the believers to battle. If there are among you twenty [who are] steadfast, they will overcome two hundred. And if there are among you one hundred [who are] steadfast, they will overcome a thousand of those who have disbelieved because they are a people who do not understand.', NULL, NULL, 'b96d2f2be6d04b858c079b5406765a35249fc83444ca098d053d198916fff95f'),
  ('en.sahih', 8, 66, 1226, 'Now, Allah has lightened [the hardship] for you, and He knows that among you is weakness. So if there are from you one hundred [who are] steadfast, they will overcome two hundred. And if there are among you a thousand, they will overcome two thousand by permission of Allah. And Allah is with the steadfast.', NULL, NULL, 'c796ce555d83315b712769051ebc1ac567cf09133ab6ade64f04397d05d24a28'),
  ('en.sahih', 8, 67, 1227, 'It is not for a prophet to have captives [of war] until he inflicts a massacre [upon Allah ''s enemies] in the land. Some Muslims desire the commodities of this world, but Allah desires [for you] the Hereafter. And Allah is Exalted in Might and Wise.', NULL, NULL, '1bdf76d21208f172d77fc70600efa9febac21b936611bcf721d36e8703515631'),
  ('en.sahih', 8, 68, 1228, 'If not for a decree from Allah that preceded, you would have been touched for what you took by a great punishment.', NULL, NULL, 'f4a6e9f4699455ac69d6f24eeba985d660b70f58eededfe6b6e3d3d39e578a97'),
  ('en.sahih', 8, 69, 1229, 'So consume what you have taken of war booty [as being] lawful and good, and fear Allah. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '3ae09fa01e667c7f4e4ae8d677d3c8f49e4d4128231246b8efb82ab567072f10'),
  ('en.sahih', 8, 70, 1230, 'O Prophet, say to whoever is in your hands of the captives, "If Allah knows [any] good in your hearts, He will give you [something] better than what was taken from you, and He will forgive you; and Allah is Forgiving and Merciful."', NULL, NULL, '384c973b43dd24960a4b0a72da910a92d618ba21e4acf9f84bd6a80380dd30bc'),
  ('en.sahih', 8, 71, 1231, 'But if they intend to betray you - then they have already betrayed Allah before, and He empowered [you] over them. And Allah is Knowing and Wise.', NULL, NULL, 'ef118d205fa9d26f47b7fb8bda20a74ad4c7d777fd53f4b967673e17d5ede466'),
  ('en.sahih', 8, 72, 1232, 'Indeed, those who have believed and emigrated and fought with their wealth and lives in the cause of Allah and those who gave shelter and aided - they are allies of one another. But those who believed and did not emigrate - for you there is no guardianship of them until they emigrate. And if they seek help of you for the religion, then you must help, except against a people between yourselves and whom is a treaty. And Allah is Seeing of what you do.', NULL, NULL, '596b94c88b812f221e8b329b050fed5194f901d1792f3ef0f98cd822e2f60f49'),
  ('en.sahih', 8, 73, 1233, 'And those who disbelieved are allies of one another. If you do not do so, there will be fitnah on earth and great corruption.', NULL, NULL, 'f54a5dcfcc3720acf819c20a963e1dfaf8af640fbba2756c91a753dd60128b33'),
  ('en.sahih', 8, 74, 1234, 'But those who have believed and emigrated and fought in the cause of Allah and those who gave shelter and aided - it is they who are the believers, truly. For them is forgiveness and noble provision.', NULL, NULL, '5d9ac53c29846ebce6d79f71375398f10c79b29c729ad5152637a2cbc593a197'),
  ('en.sahih', 8, 75, 1235, 'And those who believed after [the initial emigration] and emigrated and fought with you - they are of you. But those of [blood] relationship are more entitled [to inheritance] in the decree of Allah. Indeed, Allah is Knowing of all things.', NULL, NULL, '4583170296e40811ca7b374dba0b416942534913725f4904ce4663cb7fc423c4'),
  ('en.sahih', 9, 1, 1236, '[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists.', NULL, NULL, '498c5c9e0cb74091165a4ca6d735db74f511df28ebd9e21fb63ec405ac7ba7e1'),
  ('en.sahih', 9, 2, 1237, 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers.', NULL, NULL, 'c9b596533aa829d6016d7cdc05d04e78a1e8c959e7d4bf62105adfd6988c3ca2'),
  ('en.sahih', 9, 3, 1238, 'And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment.', NULL, NULL, '39223383b6a7a20d743198964b7d788eb2c8c97a744259f57fb5bf2349da19c6'),
  ('en.sahih', 9, 4, 1239, 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him].', NULL, NULL, 'b392458a612970f6df323ad11aa8f351166faf057e5fd9de6151b077bffbe44b'),
  ('en.sahih', 9, 5, 1240, 'And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '4186449e01f8cdbad535dbb593f278815257e3f8dc9f1448a870e3a16faf1400'),
  ('en.sahih', 9, 6, 1241, 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know.', NULL, NULL, '89758a7a99230854e55e64b4a0cb756fae697369a26ff4c50c8f096aaf8e3bec'),
  ('en.sahih', 9, 7, 1242, 'How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him].', NULL, NULL, '2d9a0c3f8fdbe84720698bad8c1a9e5730295d5e57be931139f13deaa00f7487'),
  ('en.sahih', 9, 8, 1243, 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.', NULL, NULL, 'f28c282fbe481046f32d735221506d4b317712ed192cf45459deeaae393ead71'),
  ('en.sahih', 9, 9, 1244, 'They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing.', NULL, NULL, 'e33720a08becb99c34d3e4cbb8f48b3309e5331e9a35538e2eb29c2e634dce1f'),
  ('en.sahih', 9, 10, 1245, 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.', NULL, NULL, 'd8b80a99ad60144210bf115c2c024e731b3384b93f8cccef577f2de50a1520d6'),
  ('en.sahih', 9, 11, 1246, 'But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know.', NULL, NULL, 'ee7d6054868902635cbb0adabc26942759268acbe4f8b1fd6f41e704ca26fb10'),
  ('en.sahih', 9, 12, 1247, 'And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.', NULL, NULL, '576e46ad3ce66efc4472039e58cd99daeb87d1113894dad5e8afe236addde13d'),
  ('en.sahih', 9, 13, 1248, 'Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers.', NULL, NULL, '108f678da341a061cb01dbef2f365b9b1f266fcbf1d0aeaf47fe936f3677cd6f'),
  ('en.sahih', 9, 14, 1249, 'Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people', NULL, NULL, 'b424c0c1a9c13d494838fb33ebcc5dda478058a8329c9826308d03f9075a956d'),
  ('en.sahih', 9, 15, 1250, 'And remove the fury in the believers'' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.', NULL, NULL, 'a52370d47968264cc1e53d03b88695fc751aceb07487f71dfe41047387177f95'),
  ('en.sahih', 9, 16, 1251, 'Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do.', NULL, NULL, 'ad13a7d3df76b8654c92f82fef49466221a3786325645557a34174e8c77b52ee'),
  ('en.sahih', 9, 17, 1252, 'It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.', NULL, NULL, 'dbd590e07ba871f293e573fe1215fb0712179091d3d7d401b19c67015f28304b'),
  ('en.sahih', 9, 18, 1253, 'The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided.', NULL, NULL, 'fa7b3d87db64f72ee98fbc52a01117ab7188dcd262d8974db288b8a8caf5cf79'),
  ('en.sahih', 9, 19, 1254, 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people.', NULL, NULL, 'd605541bfdafe40c5c82f846b63270aedcb6c5d24eec2b7a198e30ad91483b20'),
  ('en.sahih', 9, 20, 1255, 'The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success].', NULL, NULL, '7e3eed1a53f4c58548b64b9e768b1ee59c4feb64b80fa6d7a020b3de44b857c1'),
  ('en.sahih', 9, 21, 1256, 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.', NULL, NULL, '67d89e9f5344818b70aeb2418fb26b62c63ade6c141405d928da8e634f8fffbf'),
  ('en.sahih', 9, 22, 1257, '[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.', NULL, NULL, '34dfcfeaa71aaf6302cf9015288438e09c523686e4473ccec76ee4d24ba0b395'),
  ('en.sahih', 9, 23, 1258, 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.', NULL, NULL, '7dba8df4a7629a6d063da112d509812eb25582b119c35cfefa1e8b0619b003ed'),
  ('en.sahih', 9, 24, 1259, 'Say, [O Muhammad], "If your fathers, your sons, your brothers, your wives, your relatives, wealth which you have obtained, commerce wherein you fear decline, and dwellings with which you are pleased are more beloved to you than Allah and His Messenger and jihad in His cause, then wait until Allah executes His command. And Allah does not guide the defiantly disobedient people."', NULL, NULL, '6725abca3432196e38f700be26c47b212bd7ac8faca79725acad097eb65914d5'),
  ('en.sahih', 9, 25, 1260, 'Allah has already given you victory in many regions and [even] on the day of Hunayn, when your great number pleased you, but it did not avail you at all, and the earth was confining for you with its vastness; then you turned back, fleeing.', NULL, NULL, 'adaf54f75372b159a329af0dd3270d5d79fe2858ec73dfdb69ee308af48275a6'),
  ('en.sahih', 9, 26, 1261, 'Then Allah sent down His tranquillity upon His Messenger and upon the believers and sent down soldiers angels whom you did not see and punished those who disbelieved. And that is the recompense of the disbelievers.', NULL, NULL, '66378fb66782e35b675fb30359343f66f538c8446201cc8417861642645eab85'),
  ('en.sahih', 9, 27, 1262, 'Then Allah will accept repentance after that for whom He wills; and Allah is Forgiving and Merciful.', NULL, NULL, 'b35f8b660b3d6438282a4ab386a880174f9fa09f29d2cc0d36501c4b6c195716'),
  ('en.sahih', 9, 28, 1263, 'O you who have believed, indeed the polytheists are unclean, so let them not approach al-Masjid al-Haram after this, their [final] year. And if you fear privation, Allah will enrich you from His bounty if He wills. Indeed, Allah is Knowing and Wise.', NULL, NULL, '14bbdf8dae436ee15f6e1e134f02fed639ac565c4445d6c7b3028872a0d1bbae'),
  ('en.sahih', 9, 29, 1264, 'Fight those who do not believe in Allah or in the Last Day and who do not consider unlawful what Allah and His Messenger have made unlawful and who do not adopt the religion of truth from those who were given the Scripture - [fight] until they give the jizyah willingly while they are humbled.', NULL, NULL, '149daf95a4e14436be22c7fc558c7a2935e3ceb1df0ecc67536bc0cff0e20668'),
  ('en.sahih', 9, 30, 1265, 'The Jews say, "Ezra is the son of Allah "; and the Christians say, "The Messiah is the son of Allah." That is their statement from their mouths; they imitate the saying of those who disbelieved [before them]. May Allah destroy them; how are they deluded?', NULL, NULL, '520530823cdfb98298c6b57c1ee47ac985b5cab3da9d7dba016edf74f12de65e'),
  ('en.sahih', 9, 31, 1266, 'They have taken their scholars and monks as lords besides Allah, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him.', NULL, NULL, '637c61869b5ba187dbf588262c5f538f3b1d35e042f4b5597e86df19e58e53e1'),
  ('en.sahih', 9, 32, 1267, 'They want to extinguish the light of Allah with their mouths, but Allah refuses except to perfect His light, although the disbelievers dislike it.', NULL, NULL, '88c429f5b15228a9235be8aacf065efcda664a82029902798435ca600a83380e'),
  ('en.sahih', 9, 33, 1268, 'It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allah dislike it.', NULL, NULL, 'cc049514f298d90039eff67b7c1a8a385539297752140651ab8605618a443eb8'),
  ('en.sahih', 9, 34, 1269, 'O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allah. And those who hoard gold and silver and spend it not in the way of Allah - give them tidings of a painful punishment.', NULL, NULL, '199efb7223924fe4247a0de1329ab820482687eabcfec5b4570037bb6f3614ec'),
  ('en.sahih', 9, 35, 1270, 'The Day when it will be heated in the fire of Hell and seared therewith will be their foreheads, their flanks, and their backs, [it will be said], "This is what you hoarded for yourselves, so taste what you used to hoard."', NULL, NULL, 'f1d33bcf694ca9b1bb15aa55c84624d512192d67bca597046c495f994f9d29cf'),
  ('en.sahih', 9, 36, 1271, 'Indeed, the number of months with Allah is twelve [lunar] months in the register of Allah [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion, so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allah is with the righteous [who fear Him].', NULL, NULL, 'fbf7e10365c5d2cee1a983ffe98cedecd061dd6209cea67474d028dc3876160c'),
  ('en.sahih', 9, 37, 1272, 'Indeed, the postponing [of restriction within sacred months] is an increase in disbelief by which those who have disbelieved are led [further] astray. They make it lawful one year and unlawful another year to correspond to the number made unlawful by Allah and [thus] make lawful what Allah has made unlawful. Made pleasing to them is the evil of their deeds; and Allah does not guide the disbelieving people.', NULL, NULL, 'f4c36d9f62fbb710f196f3449f9d2df62f3977357d0648600b0692c96a715d1e'),
  ('en.sahih', 9, 38, 1273, 'O you who have believed, what is [the matter] with you that, when you are told to go forth in the cause of Allah, you adhere heavily to the earth? Are you satisfied with the life of this world rather than the Hereafter? But what is the enjoyment of worldly life compared to the Hereafter except a [very] little.', NULL, NULL, 'bc543081a6c7296082a3e9093bbc23b4aa24e38af9b5f5835c2a3d6b95b7c325'),
  ('en.sahih', 9, 39, 1274, 'If you do not go forth, He will punish you with a painful punishment and will replace you with another people, and you will not harm Him at all. And Allah is over all things competent.', NULL, NULL, '762908f86b83aa435c5148b82947d27a9f5b5f807d9f94c2e4229c09f7d08436'),
  ('en.sahih', 9, 40, 1275, 'If you do not aid the Prophet - Allah has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he said to his companion, "Do not grieve; indeed Allah is with us." And Allah sent down his tranquillity upon him and supported him with angels you did not see and made the word of those who disbelieved the lowest, while the word of Allah - that is the highest. And Allah is Exalted in Might and Wise.', NULL, NULL, '6e9956939912fefa6a9f42988806cfee4111cc554e1439caebe6454c37557c6a'),
  ('en.sahih', 9, 41, 1276, 'Go forth, whether light or heavy, and strive with your wealth and your lives in the cause of Allah. That is better for you, if you only knew.', NULL, NULL, '8fbc371c38d01c11abd2cb023407f2d76e01500c7ce6feb9dd73f4b9b55e67f1'),
  ('en.sahih', 9, 42, 1277, 'Had it been an easy gain and a moderate trip, the hypocrites would have followed you, but distant to them was the journey. And they will swear by Allah, "If we were able, we would have gone forth with you," destroying themselves [through false oaths], and Allah knows that indeed they are liars.', NULL, NULL, '8cc6b606cdc5297a4ba2927d0b28f827a4775abd024f3ac196293067d5f3a79d'),
  ('en.sahih', 9, 43, 1278, 'May Allah pardon you, [O Muhammad]; why did you give them permission [to remain behind]? [You should not have] until it was evident to you who were truthful and you knew [who were] the liars.', NULL, NULL, '69ab0545b66a24f139b19fc59e2f66cec78776f6aa392269e1be2f2e7b464d5a'),
  ('en.sahih', 9, 44, 1279, 'Those who believe in Allah and the Last Day would not ask permission of you to be excused from striving with their wealth and their lives. And Allah is Knowing of those who fear Him.', NULL, NULL, 'b8df4ddc03bf2cade61199b4b25a7a190035c63bad9e1fd74e958e8c3e4c86e8'),
  ('en.sahih', 9, 45, 1280, 'Only those would ask permission of you who do not believe in Allah and the Last Day and whose hearts have doubted, and they, in their doubt, are hesitating.', NULL, NULL, '7d7103a509dfb6673d357a8dbdff958b76179f674f6acf849a16b5a4a57f75ea'),
  ('en.sahih', 9, 46, 1281, 'And if they had intended to go forth, they would have prepared for it [some] preparation. But Allah disliked their being sent, so He kept them back, and they were told, "Remain [behind] with those who remain."', NULL, NULL, 'baee37d918e20067d6510f9bc427dadda2a5ae0a94654625b93c0dddaeaf5778'),
  ('en.sahih', 9, 47, 1282, 'Had they gone forth with you, they would not have increased you except in confusion, and they would have been active among you, seeking [to cause] you fitnah. And among you are avid listeners to them. And Allah is Knowing of the wrongdoers.', NULL, NULL, '30ad131d5733e4fa0501ab7e0b7a5bcf9302060bef0003981f015d1ab936ed2a'),
  ('en.sahih', 9, 48, 1283, 'They had already desired dissension before and had upset matters for you until the truth came and the ordinance of Allah appeared, while they were averse.', NULL, NULL, '87f3ef5b0a0c272ac480d9ff3b52f8d2d1765859e5b5db541c2663ccbb416fee'),
  ('en.sahih', 9, 49, 1284, 'And among them is he who says, "Permit me [to remain at home] and do not put me to trial." Unquestionably, into trial they have fallen. And indeed, Hell will encompass the disbelievers.', NULL, NULL, 'd8ea4b636bcf1cc668156bbcf81e6fbab5bcc385bdf4e84ece801c6fff4d00e0'),
  ('en.sahih', 9, 50, 1285, 'If good befalls you, it distresses them; but if disaster strikes you, they say, "We took our matter [in hand] before," and turn away while they are rejoicing.', NULL, NULL, '8d4818a8f149a7250de5d92ff23513be370c81f8fb510c22b5e9854721d0e947'),
  ('en.sahih', 9, 51, 1286, 'Say, "Never will we be struck except by what Allah has decreed for us; He is our protector." And upon Allah let the believers rely.', NULL, NULL, '454240c4f61da1a265906af135f480234adba2f69a48fbf54ca94f0503b9deb3'),
  ('en.sahih', 9, 52, 1287, 'Say, "Do you await for us except one of the two best things while we await for you that Allah will afflict you with punishment from Himself or at our hands? So wait; indeed we, along with you, are waiting."', NULL, NULL, '4cc3bbab4c3206f6310b3b303fb91d5ca5f8b6d14c789e4287b5c35bca2fb707'),
  ('en.sahih', 9, 53, 1288, 'Say, "Spend willingly or unwillingly; never will it be accepted from you. Indeed, you have been a defiantly disobedient people."', NULL, NULL, 'a160d57102636b556e901c340577a7d1f3b00fad8181cd5c0a73e45b61d08a66'),
  ('en.sahih', 9, 54, 1289, 'And what prevents their expenditures from being accepted from them but that they have disbelieved in Allah and in His Messenger and that they come not to prayer except while they are lazy and that they do not spend except while they are unwilling.', NULL, NULL, 'e7b0050bf7031f17bc5e3c894c6b2f8474776fe36724268a8b76fe3794c71797'),
  ('en.sahih', 9, 55, 1290, 'So let not their wealth or their children impress you. Allah only intends to punish them through them in worldly life and that their souls should depart [at death] while they are disbelievers.', NULL, NULL, '64a75d41b2f989042669b59f4f150c96c775248c2b21fd7ba320a8ee98fbd20d'),
  ('en.sahih', 9, 56, 1291, 'And they swear by Allah that they are from among you while they are not from among you; but they are a people who are afraid.', NULL, NULL, '9c715c2bfa1fd2981d758767e08dd8aec4aae92d021d047ca23094a722bdb89a'),
  ('en.sahih', 9, 57, 1292, 'If they could find a refuge or some caves or any place to enter [and hide], they would turn to it while they run heedlessly.', NULL, NULL, 'd99095cfe561deac8c445bd2b1043aa9de8603b194eafbd3044f47fdd93c787a'),
  ('en.sahih', 9, 58, 1293, 'And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry.', NULL, NULL, '33fd575157501343ccaf448d690b2f3ce551cca1088d93301b3f746e89983e22'),
  ('en.sahih', 9, 59, 1294, 'If only they had been satisfied with what Allah and His Messenger gave them and said, "Sufficient for us is Allah; Allah will give us of His bounty, and [so will] His Messenger; indeed, we are desirous toward Allah," [it would have been better for them].', NULL, NULL, '0d9db9732c6db28b97ab7e8f2e50ad8b6314a66a2b12413cfaa5b977d3d6006a'),
  ('en.sahih', 9, 60, 1295, 'Zakah expenditures are only for the poor and for the needy and for those employed to collect [zakah] and for bringing hearts together [for Islam] and for freeing captives [or slaves] and for those in debt and for the cause of Allah and for the [stranded] traveler - an obligation [imposed] by Allah. And Allah is Knowing and Wise.', NULL, NULL, '8ca16c4dc80d4a18e065819f296e41b3aa3bccf8b84f001a81b335b56672e23e'),
  ('en.sahih', 9, 61, 1296, 'And among them are those who abuse the Prophet and say, "He is an ear." Say, "[It is] an ear of goodness for you that believes in Allah and believes the believers and [is] a mercy to those who believe among you." And those who abuse the Messenger of Allah - for them is a painful punishment.', NULL, NULL, '4a8663f0e66501e90716b9815e10a5f95ccb612897779e45754e8d1ac9653dd8'),
  ('en.sahih', 9, 62, 1297, 'They swear by Allah to you [Muslims] to satisfy you. But Allah and His Messenger are more worthy for them to satisfy, if they should be believers.', NULL, NULL, '7819feb729af1bf263e053881221ba6b13b67826627cff14c368b6a2c06f3d22'),
  ('en.sahih', 9, 63, 1298, 'Do they not know that whoever opposes Allah and His Messenger - that for him is the fire of Hell, wherein he will abide eternally? That is the great disgrace.', NULL, NULL, '247532c4cfe0cac266f70a18c3f67a410bedb75f703805c9a371915c01468abf'),
  ('en.sahih', 9, 64, 1299, 'They hypocrites are apprehensive lest a surah be revealed about them, informing them of what is in their hearts. Say, "Mock [as you wish]; indeed, Allah will expose that which you fear."', NULL, NULL, 'b4664e46968524226737c5700752f0b02536cccd7c9a72f326138a4cb7d4c937'),
  ('en.sahih', 9, 65, 1300, 'And if you ask them, they will surely say, "We were only conversing and playing." Say, "Is it Allah and His verses and His Messenger that you were mocking?"', NULL, NULL, '0466f3376225fc3ba1932265e3197d7b44cff96533424f565afd02bbbe8cc27c')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 9, 66, 1301, 'Make no excuse; you have disbelieved after your belief. If We pardon one faction of you - We will punish another faction because they were criminals.', NULL, NULL, '2a543d1ed79a017052228d34d4496c14952e739bba019990d97b14567dc55e72'),
  ('en.sahih', 9, 67, 1302, 'The hypocrite men and hypocrite women are of one another. They enjoin what is wrong and forbid what is right and close their hands. They have forgotten Allah, so He has forgotten them [accordingly]. Indeed, the hypocrites - it is they who are the defiantly disobedient.', NULL, NULL, 'c72a8c2219587f9244c2b82b562c7658ccaecad6b3e0a0f391d4d403f5db776c'),
  ('en.sahih', 9, 68, 1303, 'Allah has promised the hypocrite men and hypocrite women and the disbelievers the fire of Hell, wherein they will abide eternally. It is sufficient for them. And Allah has cursed them, and for them is an enduring punishment.', NULL, NULL, 'a900106acf656c3f87bf24c2bf1a1ebccfb0fac35a46f0af74f742f54c670d0d'),
  ('en.sahih', 9, 69, 1304, '[You disbelievers are] like those before you; they were stronger than you in power and more abundant in wealth and children. They enjoyed their portion [of worldly enjoyment], and you have enjoyed your portion as those before you enjoyed their portion, and you have engaged [in vanities] like that in which they engaged. [It is] those whose deeds have become worthless in this world and in the Hereafter, and it is they who are the losers.', NULL, NULL, 'f4e11aaf9de56ed4252c1839905ededb623757cf9c85d8af01ff1e7f40d15523'),
  ('en.sahih', 9, 70, 1305, 'Has there not reached them the news of those before them - the people of Noah and [the tribes of] ''Aad and Thamud and the people of Abraham and the companions of Madyan and the towns overturned? Their messengers came to them with clear proofs. And Allah would never have wronged them, but they were wronging themselves.', NULL, NULL, 'ee321fefdead75223d2c0b0c8860a649751c9f1bdcde149900781aceb0d30e15'),
  ('en.sahih', 9, 71, 1306, 'The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakah and obey Allah and His Messenger. Those - Allah will have mercy upon them. Indeed, Allah is Exalted in Might and Wise.', NULL, NULL, '904ae717f714eb29ec5172a86a6cc5f7034f9482320372d7fcea5e7db81b1a2c'),
  ('en.sahih', 9, 72, 1307, 'Allah has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allah is greater. It is that which is the great attainment.', NULL, NULL, 'd25bef4701cd2178fc4e57995316adb1995be5e185d139ae51ff0d6f3d2c206a'),
  ('en.sahih', 9, 73, 1308, 'O Prophet, fight against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.', NULL, NULL, '8ee3831c94fbac8f996cbf866bb6363de5e8f186496b9e49001a402ae7a59b28'),
  ('en.sahih', 9, 74, 1309, 'They swear by Allah that they did not say [anything against the Prophet] while they had said the word of disbelief and disbelieved after their [pretense of] Islam and planned that which they were not to attain. And they were not resentful except [for the fact] that Allah and His Messenger had enriched them of His bounty. So if they repent, it is better for them; but if they turn away, Allah will punish them with a painful punishment in this world and the Hereafter. And there will not be for them on earth any protector or helper.', NULL, NULL, '6d045788c01b2fe3248e20ab0212064c2c8f84b8a560352bdca21b2730401ed7'),
  ('en.sahih', 9, 75, 1310, 'And among them are those who made a covenant with Allah, [saying], "If He should give us from His bounty, we will surely spend in charity, and we will surely be among the righteous."', NULL, NULL, '3e42ba6316665e8480bc5c2a7f46a87a090f85110816cac08c812c6b1145c793'),
  ('en.sahih', 9, 76, 1311, 'But when he gave them from His bounty, they were stingy with it and turned away while they refused.', NULL, NULL, '3b2d0dd342c6ae55a227a2c3aa1c15eb78bc2937656d1df4cddc65620e3909ff'),
  ('en.sahih', 9, 77, 1312, 'So He penalized them with hypocrisy in their hearts until the Day they will meet Him - because they failed Allah in what they promised Him and because they [habitually] used to lie.', NULL, NULL, '48b71700d338fd43778e74cc5aa2cbb46ed8a147cea55220991728233d3f96d1'),
  ('en.sahih', 9, 78, 1313, 'Did they not know that Allah knows their secrets and their private conversations and that Allah is the Knower of the unseen?', NULL, NULL, 'db882f4e3fdebd4c0aac87b6c956e3c966f17a9eee374bc81ec93aea45fdcb14'),
  ('en.sahih', 9, 79, 1314, 'Those who criticize the contributors among the believers concerning [their] charities and [criticize] the ones who find nothing [to spend] except their effort, so they ridicule them - Allah will ridicule them, and they will have a painful punishment.', NULL, NULL, '5e29be55a629f960579668feacad283531af6f01050f37c65991e9ff65950c50'),
  ('en.sahih', 9, 80, 1315, 'Ask forgiveness for them, [O Muhammad], or do not ask forgiveness for them. If you should ask forgiveness for them seventy times - never will Allah forgive them. That is because they disbelieved in Allah and His Messenger, and Allah does not guide the defiantly disobedient people.', NULL, NULL, '3540e4f42d2642f224353ddff265775cab90a4fa769089b0d49d629bc6c71804'),
  ('en.sahih', 9, 81, 1316, 'Those who remained behind rejoiced in their staying [at home] after [the departure of] the Messenger of Allah and disliked to strive with their wealth and their lives in the cause of Allah and said, "Do not go forth in the heat." Say, "The fire of Hell is more intensive in heat" - if they would but understand.', NULL, NULL, '0dc6213764cb97e2825a56d82c62bb3a413bf6a37cb59ee73586f05870205041'),
  ('en.sahih', 9, 82, 1317, 'So let them laugh a little and [then] weep much as recompense for what they used to earn.', NULL, NULL, '406ec40f5498ccb65a0418b4f6a13fcd88ada73e07bdbfab4d99a8e98eb7e0b7'),
  ('en.sahih', 9, 83, 1318, 'If Allah should return you to a faction of them [after the expedition] and then they ask your permission to go out [to battle], say, "You will not go out with me, ever, and you will never fight with me an enemy. Indeed, you were satisfied with sitting [at home] the first time, so sit [now] with those who stay behind."', NULL, NULL, 'c0631c164dd4bbace62fe6c69494b9f48e32272b4c26e20b717ba6d4b2af7e67'),
  ('en.sahih', 9, 84, 1319, 'And do not pray [the funeral prayer, O Muhammad], over any of them who has died - ever - or stand at his grave. Indeed, they disbelieved in Allah and His Messenger and died while they were defiantly disobedient.', NULL, NULL, '1ebb2da26895ef608aeef9411b89a6f81bcd8c24e724775bc2fee80ec19face1'),
  ('en.sahih', 9, 85, 1320, 'And let not their wealth and their children impress you. Allah only intends to punish them through them in this world and that their souls should depart [at death] while they are disbelievers.', NULL, NULL, '5be81bfabf70e1c99c4d0140dbbcd86b9dc1800f04b705e67fddbbac66214a46'),
  ('en.sahih', 9, 86, 1321, 'And when a surah was revealed [enjoining them] to believe in Allah and to fight with His Messenger, those of wealth among them asked your permission [to stay back] and said, "Leave us to be with them who sit [at home]."', NULL, NULL, 'b5176518247554f0b5cbbb213e1417e7e51f9e754781ec7173819278f6214c35'),
  ('en.sahih', 9, 87, 1322, 'They were satisfied to be with those who stay behind, and their hearts were sealed over, so they do not understand.', NULL, NULL, '5cff6fc3761d0d753a20c92d32049f5082604bdf095432a1f5add5dcd9da6b24'),
  ('en.sahih', 9, 88, 1323, 'But the Messenger and those who believed with him fought with their wealth and their lives. Those will have [all that is] good, and it is those who are the successful.', NULL, NULL, 'd0c196e8348af6fdbfae07854972213e10d308688244c48f6d05e940296d415b'),
  ('en.sahih', 9, 89, 1324, 'Allah has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment.', NULL, NULL, '27b3c33a558abb3fce74cc395b0940f8b12ff92285058ac657f648fcc06f536c'),
  ('en.sahih', 9, 90, 1325, 'And those with excuses among the bedouins came to be permitted [to remain], and they who had lied to Allah and His Messenger sat [at home]. There will strike those who disbelieved among them a painful punishment.', NULL, NULL, '07f342612ceb07c1211fbdbf52c7f9ed8ddd3d8cd38572ea60fe9acc234120ca'),
  ('en.sahih', 9, 91, 1326, 'There is not upon the weak or upon the ill or upon those who do not find anything to spend any discomfort when they are sincere to Allah and His Messenger. There is not upon the doers of good any cause [for blame]. And Allah is Forgiving and Merciful.', NULL, NULL, 'a86481ed35929392b4cb81b85a77a9c69aab96802968469050ff9a2ab9e5c4ac'),
  ('en.sahih', 9, 92, 1327, 'Nor [is there blame] upon those who, when they came to you that you might give them mounts, you said, "I can find nothing for you to ride upon." They turned back while their eyes overflowed with tears out of grief that they could not find something to spend [for the cause of Allah].', NULL, NULL, '0bf97ea3c8d7ff06abef36fb9ea6f69a3d966c77f9397a552de56664cbf77d36'),
  ('en.sahih', 9, 93, 1328, 'The cause [for blame] is only upon those who ask permission of you while they are rich. They are satisfied to be with those who stay behind, and Allah has sealed over their hearts, so they do not know.', NULL, NULL, '8072845be913bfe3835babd966d502bc10dcc6a8d5e529d827fa8e491f1a1155'),
  ('en.sahih', 9, 94, 1329, 'They will make excuses to you when you have returned to them. Say, "Make no excuse - never will we believe you. Allah has already informed us of your news. And Allah will observe your deeds, and [so will] His Messenger; then you will be taken back to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."', NULL, NULL, 'd91bc288e55012586162f0e074ef85511d71b88bdb206bbf6d4e428cfa29b03d'),
  ('en.sahih', 9, 95, 1330, 'They will swear by Allah to you when you return to them that you would leave them alone. So leave them alone; indeed they are evil; and their refuge is Hell as recompense for what they had been earning.', NULL, NULL, '1293da099c26314fe010698e851a3fdd9c3c188dfc8f17f3cc28fdeb14c6efd5'),
  ('en.sahih', 9, 96, 1331, 'They swear to you so that you might be satisfied with them. But if you should be satisfied with them - indeed, Allah is not satisfied with a defiantly disobedient people.', NULL, NULL, '5791f3b7c83811dd81e2e0ebc59f8ea107af6cc9bb71a5695d11fefe1aabd2ee'),
  ('en.sahih', 9, 97, 1332, 'The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allah has revealed to His Messenger. And Allah is Knowing and Wise.', NULL, NULL, 'ff1117d872eb03a78d525d64271aa8efeac68be4a1a80b9ee1c5d2d26ce3b2a5'),
  ('en.sahih', 9, 98, 1333, 'And among the bedouins are some who consider what they spend as a loss and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allah is Hearing and Knowing.', NULL, NULL, 'd24909d293b91b2499c00e7d3bd05da6c7464b8e6c847b4c187fb626d623c7c6'),
  ('en.sahih', 9, 99, 1334, 'But among the bedouins are some who believe in Allah and the Last Day and consider what they spend as means of nearness to Allah and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allah will admit them to His mercy. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '1ea6ae41d1d6542f37ef4f7e068c0aab8c9064b2a37ed8f08c5808a74c728311'),
  ('en.sahih', 9, 100, 1335, 'And the first forerunners [in the faith] among the Muhajireen and the Ansar and those who followed them with good conduct - Allah is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', NULL, NULL, '1fdc7b062a73352dbf7f67316785452ac1f10489887e2c1ffe51738d71c77faf'),
  ('en.sahih', 9, 101, 1336, 'And among those around you of the bedouins are hypocrites, and [also] from the people of Madinah. They have become accustomed to hypocrisy. You, [O Muhammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment.', NULL, NULL, 'e87ac553be6dc15ddee68ba7651ef58334d7f24cabe7cee7b5204b1f52f8b5e4'),
  ('en.sahih', 9, 102, 1337, 'And [there are] others who have acknowledged their sins. They had mixed a righteous deed with another that was bad. Perhaps Allah will turn to them in forgiveness. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '3bdd3a4acf8a6d391ff276005658c2404bfe1d77574e77a670a9a61d235d0e83'),
  ('en.sahih', 9, 103, 1338, 'Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah ''s blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing.', NULL, NULL, '757241afecc28cf5f0d4509fc9af6fe9a1f22dfd8e679cfafd922b4b0c73d70f'),
  ('en.sahih', 9, 104, 1339, 'Do they not know that it is Allah who accepts repentance from His servants and receives charities and that it is Allah who is the Accepting of repentance, the Merciful?', NULL, NULL, '20492e70d6a13ee97cca34e2265a15acb0f0e0d1c13936817cc763d4dba94fee'),
  ('en.sahih', 9, 105, 1340, 'And say, "Do [as you will], for Allah will see your deeds, and [so, will] His Messenger and the believers. And you will be returned to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."', NULL, NULL, 'a8b471e97cf31bdc60f79efa693ee87c150fb13e7403ca8a6a5a78ed63969de6'),
  ('en.sahih', 9, 106, 1341, 'And [there are] others deferred until the command of Allah - whether He will punish them or whether He will forgive them. And Allah is Knowing and Wise.', NULL, NULL, 'e39fcc64bc8571eeaf883a3c9b7809b56e2a0cef18e090069fe15848a5c1a1cf'),
  ('en.sahih', 9, 107, 1342, 'And [there are] those [hypocrites] who took for themselves a mosque for causing harm and disbelief and division among the believers and as a station for whoever had warred against Allah and His Messenger before. And they will surely swear, "We intended only the best." And Allah testifies that indeed they are liars.', NULL, NULL, 'b1d5813ce34afe4f42cfaa438e93c788f90905a69f075a2b5ee8266feaf406d3'),
  ('en.sahih', 9, 108, 1343, 'Do not stand [for prayer] within it - ever. A mosque founded on righteousness from the first day is more worthy for you to stand in. Within it are men who love to purify themselves; and Allah loves those who purify themselves.', NULL, NULL, '958492426177917f954ccb8591a271bdb8ff2e4faaade59dc7f397864ceb4cbc'),
  ('en.sahih', 9, 109, 1344, 'Then is one who laid the foundation of his building on righteousness [with fear] from Allah and [seeking] His approval better or one who laid the foundation of his building on the edge of a bank about to collapse, so it collapsed with him into the fire of Hell? And Allah does not guide the wrongdoing people.', NULL, NULL, 'a0e38771602eadb77ffb86e3fd6b31f07f31b4fca1ed977a55baa58ec325c963'),
  ('en.sahih', 9, 110, 1345, 'Their building which they built will not cease to be a [cause of] skepticism in their hearts until their hearts are stopped. And Allah is Knowing and Wise.', NULL, NULL, '04c912ef094ed1cc931708fb9117c48a4559ea27f2c24afb5719eb1faf2f260e'),
  ('en.sahih', 9, 111, 1346, 'Indeed, Allah has purchased from the believers their lives and their properties [in exchange] for that they will have Paradise. They fight in the cause of Allah, so they kill and are killed. [It is] a true promise [binding] upon Him in the Torah and the Gospel and the Qur''an. And who is truer to his covenant than Allah? So rejoice in your transaction which you have contracted. And it is that which is the great attainment.', NULL, NULL, 'cd2c2a5d7cfe73402c0128e80820ee84da5c8cf7ac83535275da4665ccac0e2c'),
  ('en.sahih', 9, 112, 1347, '[Such believers are] the repentant, the worshippers, the praisers [of Allah], the travelers [for His cause], those who bow and prostrate [in prayer], those who enjoin what is right and forbid what is wrong, and those who observe the limits [set by] Allah. And give good tidings to the believers.', NULL, NULL, '421aba0e28979397a62dc0b654382440e34efc4c69b54f0056473247cb56008e'),
  ('en.sahih', 9, 113, 1348, 'It is not for the Prophet and those who have believed to ask forgiveness for the polytheists, even if they were relatives, after it has become clear to them that they are companions of Hellfire.', NULL, NULL, 'd50c7c79138ccb57354de43b7410c2aefe306cb9eebeaacea093ff44d9c438cb'),
  ('en.sahih', 9, 114, 1349, 'And the request of forgiveness of Abraham for his father was only because of a promise he had made to him. But when it became apparent to Abraham that his father was an enemy to Allah, he disassociated himself from him. Indeed was Abraham compassionate and patient.', NULL, NULL, '46fa114451034e8c570880a8ee023d521c8c68205163a8bb2e5cee8baf282e76'),
  ('en.sahih', 9, 115, 1350, 'And Allah would not let a people stray after He has guided them until He makes clear to them what they should avoid. Indeed, Allah is Knowing of all things.', NULL, NULL, 'e9290e8ff5d4cdb05263e98845dd3a4a1e919701eafcfd11f8fec63f73421349'),
  ('en.sahih', 9, 116, 1351, 'Indeed, to Allah belongs the dominion of the heavens and the earth; He gives life and causes death. And you have not besides Allah any protector or any helper.', NULL, NULL, '5e30e2f38a7aff52b5a2b672355708692b08484203e2e99412926cb9ad351785'),
  ('en.sahih', 9, 117, 1352, 'Allah has already forgiven the Prophet and the Muhajireen and the Ansar who followed him in the hour of difficulty after the hearts of a party of them had almost inclined [to doubt], and then He forgave them. Indeed, He was to them Kind and Merciful.', NULL, NULL, '39575772acd5ecc447f1e7267f4feeeccf6d293a19a20dcc0e81de3f6b8a0690'),
  ('en.sahih', 9, 118, 1353, 'And [He also forgave] the three who were left behind [and regretted their error] to the point that the earth closed in on them in spite of its vastness and their souls confined them and they were certain that there is no refuge from Allah except in Him. Then He turned to them so they could repent. Indeed, Allah is the Accepting of repentance, the Merciful.', NULL, NULL, '506d9f20c71ff4ca22be679fc90028b6bb54572de10c5b5d7fb507a2b0c61e86'),
  ('en.sahih', 9, 119, 1354, 'O you who have believed, fear Allah and be with those who are true.', NULL, NULL, 'c9ee7ff96ca3b95f3d5b7f888644136a6fe69b518956d97fa945b6f18b62c309'),
  ('en.sahih', 9, 120, 1355, 'It was not [proper] for the people of Madinah and those surrounding them of the bedouins that they remain behind after [the departure of] the Messenger of Allah or that they prefer themselves over his self. That is because they are not afflicted by thirst or fatigue or hunger in the cause of Allah, nor do they tread on any ground that enrages the disbelievers, nor do they inflict upon an enemy any infliction but that is registered for them as a righteous deed. Indeed, Allah does not allow to be lost the reward of the doers of good.', NULL, NULL, 'f8d678422905a1874fe63cd739f877bfa47855fab5967c30df0e27c7e45de3f5'),
  ('en.sahih', 9, 121, 1356, 'Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allah may reward them for the best of what they were doing.', NULL, NULL, '990204d79d89b0111763165c88eb7cb9d0ba661e282f2ae1f885c66db82ca79c'),
  ('en.sahih', 9, 122, 1357, 'And it is not for the believers to go forth [to battle] all at once. For there should separate from every division of them a group [remaining] to obtain understanding in the religion and warn their people when they return to them that they might be cautious.', NULL, NULL, 'a436513fe0c32fcd2353d4703656d84611d0db337f8ac9a248b951441b98ac00'),
  ('en.sahih', 9, 123, 1358, 'O you who have believed, fight those adjacent to you of the disbelievers and let them find in you harshness. And know that Allah is with the righteous.', NULL, NULL, '0baab37e9d4cdb22d845e5f05aca8f7081113fb300ffd94c30fdfdb1608c448e'),
  ('en.sahih', 9, 124, 1359, 'And whenever a surah is revealed, there are among the hypocrites those who say, "Which of you has this increased faith?" As for those who believed, it has increased them in faith, while they are rejoicing.', NULL, NULL, '561ed163eeb6625740a20b73d5906eecf5d729e2cdec54260c2ae009f776391c'),
  ('en.sahih', 9, 125, 1360, 'But as for those in whose hearts is disease, it has [only] increased them in evil [in addition] to their evil. And they will have died while they are disbelievers.', NULL, NULL, '93c2a5909789a644170aab0f2df37127281489817cfcde8abdaf773b709bb734'),
  ('en.sahih', 9, 126, 1361, 'Do they not see that they are tried every year once or twice but then they do not repent nor do they remember?', NULL, NULL, '7f91a2ff19e52ee70ddc76eb20af3b955775d1c01f5ea2a13d4df00713e89b25'),
  ('en.sahih', 9, 127, 1362, 'And whenever a surah is revealed, they look at each other, [saying], "Does anyone see you?" and then they dismiss themselves. Allah has dismissed their hearts because they are a people who do not understand.', NULL, NULL, '3ca7a4b9cdc893618c8980d4d7ed11f8f7c8977363ecd8b7d8f7e4016378a060'),
  ('en.sahih', 9, 128, 1363, 'There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; [he is] concerned over you and to the believers is kind and merciful.', NULL, NULL, '0da4d1b4e7474c8eaa771b76fc96ba8127abcfdd1031bb3f391c0eb403ed3e5a'),
  ('en.sahih', 9, 129, 1364, 'But if they turn away, [O Muhammad], say, "Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne."', NULL, NULL, '405330ec69b69cef4e8b852136dd70089903acc9b531af8e5aef9d3667fd7789'),
  ('en.sahih', 10, 1, 1365, 'Alif, Lam, Ra. These are the verses of the wise Book', NULL, NULL, '866d1b4fec613589f392e6a3adf3f48ef121f59f68bca58b35ccdccb0fba2a42'),
  ('en.sahih', 10, 2, 1366, 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."', NULL, NULL, '42da5458bdce08613a455ebdb3a0b43151a61b74a1bf341428ec84d0da75694f'),
  ('en.sahih', 10, 3, 1367, 'Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?', NULL, NULL, '83a103e197e479ba69c3c7d9bd68433719d6efcbf2f7e79f15274db05b55d23a'),
  ('en.sahih', 10, 4, 1368, 'To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.', NULL, NULL, 'a145604441ba6a02f6c64e09e160990ee77ce11f9444a6fb95094b354c1ec31a'),
  ('en.sahih', 10, 5, 1369, 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know', NULL, NULL, '75486a5111fe5f59460a69415a22be187bcbab56dbd5540a4d2697b3c463b85b'),
  ('en.sahih', 10, 6, 1370, 'Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah', NULL, NULL, '8e4dd2b2e3daaef53f3724a39e4697da71324fe4012373c3096134e0ef1cc3d3'),
  ('en.sahih', 10, 7, 1371, 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs', NULL, NULL, '101952c34a1f21fcefe3dd10ab37f2fd654393bb5fd520586032f5e1dca5e4a1'),
  ('en.sahih', 10, 8, 1372, 'For those their refuge will be the Fire because of what they used to earn.', NULL, NULL, '2f7a2b7ac8ddb41595bdd015f3d2b7a2c6edae80de711d830c4ecf358cdd92d8'),
  ('en.sahih', 10, 9, 1373, 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure', NULL, NULL, '49fa25a7a1cbb6b97e967d944d08f350e1eda79547636d1b136bba36e2b4ad73'),
  ('en.sahih', 10, 10, 1374, 'Their call therein will be, "Exalted are You, O Allah," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allah, Lord of the worlds!"', NULL, NULL, '4fdeb52bc638f6c5c4aa9dbe115d6c122553f17a5eda9284a1921ffe000ac9fb'),
  ('en.sahih', 10, 11, 1375, 'And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly', NULL, NULL, '721ed53fb3388b952ebbba1f0da47624a481970e20f9c467a982ae8acb14a8df'),
  ('en.sahih', 10, 12, 1376, 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing', NULL, NULL, '5a12eff746a8b48f3dd2cea07d62b8d061fb84e6b7d82086119d57cc19f85656'),
  ('en.sahih', 10, 13, 1377, 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people', NULL, NULL, '3584059e5530d0c5df3981b26a0191167563da7ced979cbe293c7eaa0476c458'),
  ('en.sahih', 10, 14, 1378, 'Then We made you successors in the land after them so that We may observe how you will do.', NULL, NULL, '5f410293739507217c6fea89c106ddfa6c93b0d2f1ea1dccf9953c3868c03c5b'),
  ('en.sahih', 10, 15, 1379, 'And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, "Bring us a Qur''an other than this or change it." Say, [O Muhammad], "It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', NULL, NULL, 'aab2992e6d6017a7ee8c8c0a54704455aada9178e16b854b9ea033a09952c9ba'),
  ('en.sahih', 10, 16, 1380, 'Say, "If Allah had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?"', NULL, NULL, 'ddf569f6ce4fe351f63decaed8655f7a80f8bf6a53463617c9a30de89b2fdb82'),
  ('en.sahih', 10, 17, 1381, 'So who is more unjust than he who invents a lie about Allah or denies His signs? Indeed, the criminals will not succeed', NULL, NULL, '4aefc3723ff95f3c703383897afd0e9322e750269efad43e4c51267dba1af0f4'),
  ('en.sahih', 10, 18, 1382, 'And they worship other than Allah that which neither harms them nor benefits them, and they say, "These are our intercessors with Allah " Say, "Do you inform Allah of something He does not know in the heavens or on the earth?" Exalted is He and high above what they associate with Him', NULL, NULL, '1ea4d9d6d99b51d1a47c39211f59597b27a903cd88c80eaec97d1163feeea8e0'),
  ('en.sahih', 10, 19, 1383, 'And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ.', NULL, NULL, 'db2ccc1c8e789051a9b595c44cca0aedfcbe0a02b5b3f8511059058672667031'),
  ('en.sahih', 10, 20, 1384, 'And they say, "Why is a sign not sent down to him from his Lord?" So say, "The unseen is only for Allah [to administer], so wait; indeed, I am with you among those who wait."', NULL, NULL, 'b5f9ef1a3e696d018d66cccb60a139597894171679aaa9b3dabc90e3f1071300'),
  ('en.sahih', 10, 21, 1385, 'And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, "Allah is swifter in strategy." Indeed, Our messengers record that which you conspire', NULL, NULL, '0ed8c65009fdb9f96f511390c6ad40c09c3a961ba5cc8b8ec8d6670defbeb607'),
  ('en.sahih', 10, 22, 1386, 'It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from everywhere and they assume that they are surrounded, supplicating Allah, sincere to Him in religion, "If You should save us from this, we will surely be among the thankful."', NULL, NULL, 'b9264a0290bb18e98ae20a28067e5371c85559fae4119a3e47bd35289a43142a'),
  ('en.sahih', 10, 23, 1387, 'But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do.', NULL, NULL, '69d66a7159ca836453175bc46a0f7789235594a40a20f27a4d1119e924e5e981'),
  ('en.sahih', 10, 24, 1388, 'The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought.', NULL, NULL, '35e16e052391967629f6d88b3275a860b4ae71c5e95db825a0ead64082b6bb56'),
  ('en.sahih', 10, 25, 1389, 'And Allah invites to the Home of Peace and guides whom He wills to a straight path', NULL, NULL, 'e498e5a1eebd7d5656ef92be982a13013c0120ed078515b6ad93e084a659dc05'),
  ('en.sahih', 10, 26, 1390, 'For them who have done good is the best [reward] and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally', NULL, NULL, 'aaa13eb4ec072116835a69b4fbba37e322ba54800e633b434585ea6cb85b8090'),
  ('en.sahih', 10, 27, 1391, 'But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allah no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally.', NULL, NULL, 'e58e1b42d4def01ffd8637cec0f3d8f3d0e8b3a5c23a3364aac3dadc5b6eb55f'),
  ('en.sahih', 10, 28, 1392, 'And [mention, O Muhammad], the Day We will gather them all together - then We will say to those who associated others with Allah, "[Remain in] your place, you and your ''partners.'' " Then We will separate them, and their "partners" will say, "You did not used to worship us,', NULL, NULL, '6c701f4910b8131c96a9b6a662680364f406653891de831f6720546e5ed002c6'),
  ('en.sahih', 10, 29, 1393, 'And sufficient is Allah as a witness between us and you that we were of your worship unaware."', NULL, NULL, '78a004453120ae1f98deb9cdab86308f72b69407bbced8094c4db953ab35b105'),
  ('en.sahih', 10, 30, 1394, 'There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allah, their master, the Truth, and lost from them is whatever they used to invent.', NULL, NULL, 'c33a81b020840b4c553bfa28c442ceda3c71d0ba3b13eabd7cfc44003f7f66dc'),
  ('en.sahih', 10, 31, 1395, 'Say, "Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?" They will say, "Allah," so say, "Then will you not fear Him?"', NULL, NULL, 'c233c492de493000870dd5d8751054b7709228ec02756b7bbd2bf599baa69a01'),
  ('en.sahih', 10, 32, 1396, 'For that is Allah, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?', NULL, NULL, 'd8b36380c6da970d1a62a2b008485f0d78d0766a0a710918ee69518176c972b2'),
  ('en.sahih', 10, 33, 1397, 'Thus the word of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe.', NULL, NULL, '463b1aae4237d31d9be12cc7d73778201bb6d64ac692546b12cc6d4074ce1fd3'),
  ('en.sahih', 10, 34, 1398, 'Say, "Are there of your ''partners'' any who begins creation and then repeats it?" Say, "Allah begins creation and then repeats it, so how are you deluded?"', NULL, NULL, 'a661ad2a6c34e2fa53c5e73eac1e5ce641361e2b316325f7b307042f1b20cef1'),
  ('en.sahih', 10, 35, 1399, 'Say, "Are there of your ''partners'' any who guides to the truth?" Say, "Allah guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?"', NULL, NULL, '63e5ac5b80099b2a42e5c5a77efa376fee46bdb3a3e22fc219e53e1bcb46df1e'),
  ('en.sahih', 10, 36, 1400, 'And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allah is Knowing of what they do.', NULL, NULL, 'a142f52cee96236ebbb3d310c7a8f15c9d7cc796f62aa2423b8afe2d79d8afc8')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 10, 37, 1401, 'And it was not [possible] for this Qur''an to be produced by other than Allah, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds.', NULL, NULL, 'a284e899a71922255aa5a168ac2f53dafe82625bbd02e4227bc2d5e6506d6f3e'),
  ('en.sahih', 10, 38, 1402, 'Or do they say [about the Prophet], "He invented it?" Say, "Then bring forth a surah like it and call upon [for assistance] whomever you can besides Allah, if you should be truthful."', NULL, NULL, '47ad96de34da30a5937dd631889e23e5a4b80e1be4861e784da2f2ed42ac4d12'),
  ('en.sahih', 10, 39, 1403, 'Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers.', NULL, NULL, '0a479ccc310927f89a249cde10425d86d676238d467ca837cd6d184280e351ff'),
  ('en.sahih', 10, 40, 1404, 'And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters', NULL, NULL, '5d94c282e62fda932eb90b47a65db413377d47bb5af6a60ff945da6b2ee1965f'),
  ('en.sahih', 10, 41, 1405, 'And if they deny you, [O Muhammad], then say, "For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do."', NULL, NULL, '852ab6a837744ae859ae64ac9df6535dd1e6e86c687decc31ede5517ad24293e'),
  ('en.sahih', 10, 42, 1406, 'And among them are those who listen to you. But can you cause the deaf to hear, although they will not use reason?', NULL, NULL, '86c18554a8e65ceb7497aec198562455708dc76fab59269e0a99da44f273beec'),
  ('en.sahih', 10, 43, 1407, 'And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?', NULL, NULL, '85e3a3ae496370f88c16ec70a8ca37ae1d584b2fc4b0e550dd10707b0838530f'),
  ('en.sahih', 10, 44, 1408, 'Indeed, Allah does not wrong the people at all, but it is the people who are wronging themselves.', NULL, NULL, '5811de7d65099d430cb77a4a3c684a8ed5a27ec17dffb1a3797df26ca297009a'),
  ('en.sahih', 10, 45, 1409, 'And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allah and were not guided', NULL, NULL, 'd795d34213e0f731aa5e9e66c298766f8792a42cea9617cfe9e14e1702ef392d'),
  ('en.sahih', 10, 46, 1410, 'And whether We show you some of what We promise them, [O Muhammad], or We take you in death, to Us is their return; then, [either way], Allah is a witness concerning what they are doing', NULL, NULL, '2a3537e62f313c6fe9e439b571a513daf797661decefac7a55baaa6a00d084c7'),
  ('en.sahih', 10, 47, 1411, 'And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged', NULL, NULL, '6f22d97b8b01760ff6d614978525314bdadf1e3ab5d09911185e81294342660e'),
  ('en.sahih', 10, 48, 1412, 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"', NULL, NULL, '9884f1decb74c4094b73b09a71d09a5148744c5676a3ea93ef49c3adc6cd4425'),
  ('en.sahih', 10, 49, 1413, 'Say, "I possess not for myself any harm or benefit except what Allah should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it]."', NULL, NULL, '378d4a26fdec61399b9112ebff5c39e5ae07da4d45c095305f8f1c891174b2a6'),
  ('en.sahih', 10, 50, 1414, 'Say, "Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?"', NULL, NULL, '4c74ef1066c3211722fb14e766bb5c0570dd916807a69b1b2beef63e9e91ba71'),
  ('en.sahih', 10, 51, 1415, 'Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient', NULL, NULL, 'b5ce9f154b99a53c93a941c143e974a42b31a81cc7f3d57ced2e271808a30621'),
  ('en.sahih', 10, 52, 1416, 'Then it will be said to those who had wronged, "Taste the punishment of eternity; are you being recompensed except for what you used to earn?"', NULL, NULL, 'faa8f3423180515c2da51270e8a32ce880d0965c1f913612769e12b23918c4f4'),
  ('en.sahih', 10, 53, 1417, 'And they ask information of you, [O Muhammad], "Is it true?" Say, "Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allah]."', NULL, NULL, 'b5fcc685a5fe5ea25bf3e2fb5d1f5fe6dd3b6908964e1f2914f62e33a2b172a1'),
  ('en.sahih', 10, 54, 1418, 'And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged', NULL, NULL, '8b6d368356b70f019378ce290b22c40283f5ec0c57d890d873f59693cd5487de'),
  ('en.sahih', 10, 55, 1419, 'Unquestionably, to Allah belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allah is truth, but most of them do not know', NULL, NULL, 'a3efcd3540cec066766bcb18101717ca212642f6cc838669c3edd601176a346b'),
  ('en.sahih', 10, 56, 1420, 'He gives life and causes death, and to Him you will be returned', NULL, NULL, 'e4419ef4de0524cf50a919b6c0c35f98e51746d68891828a99422eba893ecf58'),
  ('en.sahih', 10, 57, 1421, 'O mankind, there has to come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers.', NULL, NULL, 'b0e33fc20c6224cd7360d89cf2f4b07e7b759e87d59e30a1ccb192bebd0aa3d7'),
  ('en.sahih', 10, 58, 1422, 'Say, "In the bounty of Allah and in His mercy - in that let them rejoice; it is better than what they accumulate."', NULL, NULL, '5bb76a9ecc298ae87a9e6c9cd970025e1db171e7e7504af7e7e10734b1f4324e'),
  ('en.sahih', 10, 59, 1423, 'Say, "Have you seen what Allah has sent down to you of provision of which you have made [some] lawful and [some] unlawful?" Say, "Has Allah permitted you [to do so], or do you invent [something] about Allah?"', NULL, NULL, 'c705900696edc12ca55bca5d1751b3cbf5cf37070624674be3f620f25a9bbb0c'),
  ('en.sahih', 10, 60, 1424, 'And what will be the supposition of those who invent falsehood about Allah on the Day of Resurrection? Indeed, Allah is full of bounty to the people, but most of them are not grateful."', NULL, NULL, '73c1964804d057ac26f23a3662d82ffcdf1daf75690f11576ed24de34cf630f4'),
  ('en.sahih', 10, 61, 1425, 'And, [O Muhammad], you are not [engaged] in any matter or recite any of the Qur''an and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom''s weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register.', NULL, NULL, 'fa4961440d9cc87c414da37e60cd05bc755621d381b13a501a66c92884546d1e'),
  ('en.sahih', 10, 62, 1426, 'Unquestionably, [for] the allies of Allah there will be no fear concerning them, nor will they grieve', NULL, NULL, '99e95208bbc11f49646af03696078cf60c7fd472606c3ce34fe0a872566003de'),
  ('en.sahih', 10, 63, 1427, 'Those who believed and were fearing Allah', NULL, NULL, '6aea649d67e578085c28bf651353d640f2049d19cae910d778da6eed98ffb9ed'),
  ('en.sahih', 10, 64, 1428, 'For them are good tidings in the worldly life and in the Hereafter. No change is there in the words of Allah. That is what is the great attainment.', NULL, NULL, '981b2c8ee75c6e5ed787f9440cb6f2fc88a611e6131657164246527d4aebe7f0'),
  ('en.sahih', 10, 65, 1429, 'And let not their speech grieve you. Indeed, honor [due to power] belongs to Allah entirely. He is the Hearing, the Knowing.', NULL, NULL, 'c2ed1226a7c8ffb0d6bebd2fb9f1339dc020cad5effc898a73ae619a1e8a0b40'),
  ('en.sahih', 10, 66, 1430, 'Unquestionably, to Allah belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allah do not [actually] follow [His] "partners." They follow not except assumption, and they are not but falsifying', NULL, NULL, '79cb59bce855418dc4ed5d34be03cb073fb31bb9c6c07daf3477f03847a6f9c6'),
  ('en.sahih', 10, 67, 1431, 'It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen.', NULL, NULL, '331a6023b7e3ad83439fcc156287660bc96e22a7c675fd099dc8ef7885fded83'),
  ('en.sahih', 10, 68, 1432, 'They have said, "Allah has taken a son." Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allah that which you do not know?', NULL, NULL, '46f832d53ce1d592e3f7913dfd8baee9dcb8af8d7d5d45334fc2389931c3dedf'),
  ('en.sahih', 10, 69, 1433, 'Say, "Indeed, those who invent falsehood about Allah will not succeed."', NULL, NULL, '5502f3cb33062ef9dabe28f82e4681f39a1db5e9834f64462f9f9c897823b0bc'),
  ('en.sahih', 10, 70, 1434, '[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve', NULL, NULL, 'd6003a8ae6785b792ae051f24823d56df4f6204a361e7caca76afaac4f203a01'),
  ('en.sahih', 10, 71, 1435, 'And recite to them the news of Noah, when he said to his people, "O my people, if my residence and my reminding of the signs of Allah has become burdensome upon you - then I have relied upon Allah. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite.', NULL, NULL, '7226d9577945e855275a6d80d34b34a0a8785e3b8934f49b427dd27ce5b7cff6'),
  ('en.sahih', 10, 72, 1436, 'And if you turn away [from my advice] then no payment have I asked of you. My reward is only from Allah, and I have been commanded to be of the Muslims."', NULL, NULL, 'a873b607dce30777a776f7c85c6e8063c760c99934e0e9f299d3a9cd2d3844c7'),
  ('en.sahih', 10, 73, 1437, 'And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned.', NULL, NULL, '2b6bc2c46f4ba72466318aa104dad3a557b66e2fb1eeadf716113779c351eb8d'),
  ('en.sahih', 10, 74, 1438, 'Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors', NULL, NULL, '61199d67bcf647d55660b1d9fffc3adc40aff54b78999ff61899ca4af8da765b'),
  ('en.sahih', 10, 75, 1439, 'Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people', NULL, NULL, 'a7b74fc2e99ff411733a0c33bd02cc058c71b61cbc954fd01bc76304d141e335'),
  ('en.sahih', 10, 76, 1440, 'So when there came to them the truth from Us, they said, "Indeed, this is obvious magic."', NULL, NULL, '168e0d51661faaf111508c9ec8741d942a0307e48b7bc9d0f74d9ca4c989e164'),
  ('en.sahih', 10, 77, 1441, 'Moses said, "Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed."', NULL, NULL, 'e0307943c22fa6525be3ab1c364204c487b80b6db26d8857952a96c7a6f16ea0'),
  ('en.sahih', 10, 78, 1442, 'They said, "Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you."', NULL, NULL, '4f7000ac528f5d85bd47db395f2a727a81a8387f507d23647a1e7de38ad05ec4'),
  ('en.sahih', 10, 79, 1443, 'And Pharaoh said, "Bring to me every learned magician."', NULL, NULL, '783589ddb49503e0af63826a6ed76fbcb8bd801dab58f336d7af729266008a91'),
  ('en.sahih', 10, 80, 1444, 'So when the magicians came, Moses said to them, "Throw down whatever you will throw."', NULL, NULL, '28dd762490786c7686211020bbdfebe42bcc5b61439c26c4f28c429beafd8d92'),
  ('en.sahih', 10, 81, 1445, 'And when they had thrown, Moses said, "What you have brought is [only] magic. Indeed, Allah will expose its worthlessness. Indeed, Allah does not amend the work of corrupters.', NULL, NULL, '429bce929c847153b472cdf21fc9de556c1e9ab32a6a09034ac3b5830c4bf859'),
  ('en.sahih', 10, 82, 1446, 'And Allah will establish the truth by His words, even if the criminals dislike it."', NULL, NULL, '3e77014a9adcc256fd2d837d7db9de9ae82e3cb636f7713f3ed209d942c677ce'),
  ('en.sahih', 10, 83, 1447, 'But no one believed Moses, except [some] youths among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors', NULL, NULL, 'a24b271124f63038ef0898d3573242b38f011efdf735175c7b41e2c6c609ade1'),
  ('en.sahih', 10, 84, 1448, 'And Moses said, "O my people, if you have believed in Allah, then rely upon Him, if you should be Muslims."', NULL, NULL, '7fbe4ae9e914492cb4fa82ef3934d53313c53f453a6f9ccdf400660002d48064'),
  ('en.sahih', 10, 85, 1449, 'So they said, "Upon Allah do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people', NULL, NULL, '74f7157efb190378e6935f56bea5dff21dd7355ab389ae6673c48222d3db2bc4'),
  ('en.sahih', 10, 86, 1450, 'And save us by Your mercy from the disbelieving people."', NULL, NULL, '6e6bb0d2b4dbea1205a85dedc176174dc6ade535a8264207a744904c3c43c7ee'),
  ('en.sahih', 10, 87, 1451, 'And We inspired to Moses and his brother, "Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers."', NULL, NULL, 'a7eb8beb7d3f24e7c1b5faa3a16c05d86a7e9a8b9e11197050ae853fc83d999f'),
  ('en.sahih', 10, 88, 1452, 'And Moses said, "Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment."', NULL, NULL, '79750b04426a99c1e5f17cff1d4f58879c5de0525fc00269d6d7f2905af3d5e5'),
  ('en.sahih', 10, 89, 1453, '[Allah] said, "Your supplication has been answered." So remain on a right course and follow not the way of those who do not know."', NULL, NULL, '23893b1f8bc851dce3ec988939e964f3a65575f07d838bca696bd2943e3ea089'),
  ('en.sahih', 10, 90, 1454, 'And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, "I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims."', NULL, NULL, 'ad476d745bd71919acfe8b7ebc46a67b5fc4703968a1691bebd11e6f1308d176'),
  ('en.sahih', 10, 91, 1455, 'Now? And you had disobeyed [Him] before and were of the corrupters?', NULL, NULL, 'f250f8da90a78c4db215f007a0a85830880b71eedd7e3861907064d5fad41eef'),
  ('en.sahih', 10, 92, 1456, 'So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless', NULL, NULL, 'b97bc337cabac544df5cd292020df9b17e92727c8f6c7ae6b24d699ce43e05a3'),
  ('en.sahih', 10, 93, 1457, 'And We had certainty settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ', NULL, NULL, 'e1907706d6efbf82591e8fe54cad66f396dc71dbfd7cd217fd06229ea4c3b67a'),
  ('en.sahih', 10, 94, 1458, 'So if you are in doubt, [O Muhammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters.', NULL, NULL, 'e821d4753155670ea681b5749524e4745c152717af2d15a94c22d19789e36d01'),
  ('en.sahih', 10, 95, 1459, 'And never be of those who deny the signs of Allah and [thus] be among the losers.', NULL, NULL, '05db19365c56e86af92a9bc006c454a58bc2bad3ff43338d31f6d2ebcf39e617'),
  ('en.sahih', 10, 96, 1460, 'Indeed, those upon whom the word of your Lord has come into effect will not believe,', NULL, NULL, 'ae42fefdb0d5d3090386a4226d588a44710b72919300c2f92a0bc432398bbfcb'),
  ('en.sahih', 10, 97, 1461, 'Even if every sign should come to them, until they see the painful punishment.', NULL, NULL, '6da1221a3bd4c6d1b72cc57119d41a29408b5f3b3083528d4a7d99a71b359866'),
  ('en.sahih', 10, 98, 1462, 'Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment for a time.', NULL, NULL, '483ba17896cf6830501ccdd7e96db9ce48d9cd6a659f49bd76720c7cc9a95338'),
  ('en.sahih', 10, 99, 1463, 'And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muhammad], would you compel the people in order that they become believers?', NULL, NULL, 'd6dc7c042bedd21f839dc8810382c27f6b075317a501b6bafdad24a2c09ba429'),
  ('en.sahih', 10, 100, 1464, 'And it is not for a soul to believe except by permission of Allah, and He will place defilement upon those who will not use reason.', NULL, NULL, '592e3a587adcb082091a873e3b310771062baaa98491331796feb044dd2c1b90'),
  ('en.sahih', 10, 101, 1465, 'Say, "Observe what is in the heavens and earth." But of no avail will be signs or warners to a people who do not believe', NULL, NULL, 'e490b024fcf7c7cc987b565efadb77051c7a52bc0f9831e8f10f78c7eaedb2bc'),
  ('en.sahih', 10, 102, 1466, 'So do they wait except for like [what occurred in] the days of those who passed on before them? Say, "Then wait; indeed, I am with you among those who wait."', NULL, NULL, '489d8eb64e51e6d5093f3949e5fd71fabf12859347de2d037ea0dcfded6068d9'),
  ('en.sahih', 10, 103, 1467, 'Then We will save our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers', NULL, NULL, '745a37164c6b58c76a7e0e72dedd6da9d1fd540c52302fc6e1827bd85d59e902'),
  ('en.sahih', 10, 104, 1468, 'Say, [O Muhammad], "O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allah; but I worship Allah, who causes your death. And I have been commanded to be of the believers', NULL, NULL, '5c90b571be2ffd437f2ba689eab7848be6358fb38cb4d3b3129480f44c5ba854'),
  ('en.sahih', 10, 105, 1469, 'And [commanded], ''Direct your face toward the religion, inclining to truth, and never be of those who associate others with Allah;', NULL, NULL, 'f1fe0ca9a877a371490226ba5bbe0105b14150aa09fa6a50a1bcab4877cdba10'),
  ('en.sahih', 10, 106, 1470, 'And do not invoke besides Allah that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.''"', NULL, NULL, 'f940bf634ba9bad1cab1e573663fa79a2640a4e1d69c67fdf5e18c00143e3bf8'),
  ('en.sahih', 10, 107, 1471, 'And if Allah should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful', NULL, NULL, '4175790273006a13befd2f01cbfc56adae50062bdc2db9bf32f63213bcc76e9c'),
  ('en.sahih', 10, 108, 1472, 'Say, "O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager."', NULL, NULL, '461a7072a18bc990c31bedb4afe76e7643d414a7c4193b17c6eed3a9ac3bff66'),
  ('en.sahih', 10, 109, 1473, 'And follow what is revealed to you, [O Muhammad], and be patient until Allah will judge. And He is the best of judges.', NULL, NULL, '5c626640b8a7a707df181c598fde68f6512c96da600da81070b292c832076a17'),
  ('en.sahih', 11, 1, 1474, 'Alif, Lam, Ra. [This is] a Book whose verses are perfected and then presented in detail from [one who is] Wise and Acquainted.', NULL, NULL, '312514a1010d9b757f9f7cc30e5a284508160ac8283a8d1956b9f9f4f3f51b63'),
  ('en.sahih', 11, 2, 1475, '[Through a messenger, saying], "Do not worship except Allah. Indeed, I am to you from Him a warner and a bringer of good tidings,"', NULL, NULL, 'ee04c814973ac6811a7f9758d2c336b8034dcaa662c2b063a547d0f8b7173ea1'),
  ('en.sahih', 11, 3, 1476, 'And [saying], "Seek forgiveness of your Lord and repent to Him, [and] He will let you enjoy a good provision for a specified term and give every doer of favor his favor. But if you turn away, then indeed, I fear for you the punishment of a great Day.', NULL, NULL, 'afe9b0f386c58d203671c8fbbad722985ad7167cfcb16a13d665794ded61da29'),
  ('en.sahih', 11, 4, 1477, 'To Allah is your return, and He is over all things competent."', NULL, NULL, '897f3e763ceac76b337109fbfeace7ab03dc95fd3baf7dbb9274abed5e29cc66'),
  ('en.sahih', 11, 5, 1478, 'Unquestionably, they the disbelievers turn away their breasts to hide themselves from Him. Unquestionably, [even] when they cover themselves in their clothing, Allah knows what they conceal and what they declare. Indeed, He is Knowing of that within the breasts.', NULL, NULL, '2990b63d74e971ecbc747398441b874e292fc2192b7c2d1483c9e9fa72b5bcd8'),
  ('en.sahih', 11, 6, 1479, 'And there is no creature on earth but that upon Allah is its provision, and He knows its place of dwelling and place of storage. All is in a clear register.', NULL, NULL, '2aa27de1717d5d90e71fdb648202e5f054f4a28530844ef8dcbd889912b5550b'),
  ('en.sahih', 11, 7, 1480, 'And it is He who created the heavens and the earth in six days - and His Throne had been upon water - that He might test you as to which of you is best in deed. But if you say, "Indeed, you are resurrected after death," those who disbelieve will surely say, "This is not but obvious magic."', NULL, NULL, 'ed273a277e33f9d145d9951aaf1060db26fcfd380508edd2f950f273b8a8cdaf'),
  ('en.sahih', 11, 8, 1481, 'And if We hold back from them the punishment for a limited time, they will surely say, "What detains it?" Unquestionably, on the Day it comes to them, it will not be averted from them, and they will be enveloped by what they used to ridicule.', NULL, NULL, '1f1b6cbc61d7448e21f284e891ba596ad4a8c0a0abb69fdeb35e57c7d8949f00'),
  ('en.sahih', 11, 9, 1482, 'And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful.', NULL, NULL, 'bfaf37ddb2e4bedb67a1f4200108e3715ad076aa8f8f6669aa1ab047dbf6fb25'),
  ('en.sahih', 11, 10, 1483, 'But if We give him a taste of favor after hardship has touched him, he will surely say, "Bad times have left me." Indeed, he is exultant and boastful -', NULL, NULL, '44b68f9a7ea50bb731d96b24d4392e45c2d4bf542c580940d10d893b97f55c91'),
  ('en.sahih', 11, 11, 1484, 'Except for those who are patient and do righteous deeds; those will have forgiveness and great reward.', NULL, NULL, '2af4c659f35afa1b91444dd1bfa4125cb525abc162ee444c39698af4642b409d'),
  ('en.sahih', 11, 12, 1485, 'Then would you possibly leave [out] some of what is revealed to you, or is your breast constrained by it because they say, "Why has there not been sent down to him a treasure or come with him an angel?" But you are only a warner. And Allah is Disposer of all things.', NULL, NULL, 'b4d5dbd9ada766fa627ea96fc302fc9ee6368f0cf1d218540050c80f436b230e'),
  ('en.sahih', 11, 13, 1486, 'Or do they say, "He invented it"? Say, "Then bring ten surahs like it that have been invented and call upon [for assistance] whomever you can besides Allah, if you should be truthful."', NULL, NULL, 'f731ba3ad394d83f44daab98cf2477407a1fb7b6f494962b819c666b5461f7e4'),
  ('en.sahih', 11, 14, 1487, 'And if they do not respond to you - then know that the Qur''an was revealed with the knowledge of Allah and that there is no deity except Him. Then, would you [not] be Muslims?', NULL, NULL, '0a0812996cc2faad5dab750f370fdb67e647eece5f97cdd0ea500128c6752bca'),
  ('en.sahih', 11, 15, 1488, 'Whoever desires the life of this world and its adornments - We fully repay them for their deeds therein, and they therein will not be deprived.', NULL, NULL, '38079e076c635d554df3e0b07e26664efe634ef62b0fcc2600e4ba4ea886c659'),
  ('en.sahih', 11, 16, 1489, 'Those are the ones for whom there is not in the Hereafter but the Fire. And lost is what they did therein, and worthless is what they used to do.', NULL, NULL, '9973c6cb0ad00523d9a25b48a447807d9a6171f5affb998a9ee0708a96be1b44'),
  ('en.sahih', 11, 17, 1490, 'So is one who [stands] upon a clear evidence from his Lord [like the aforementioned]? And a witness from Him follows it, and before it was the Scripture of Moses to lead and as mercy. Those [believers in the former revelations] believe in the Qur''an. But whoever disbelieves in it from the [various] factions - the Fire is his promised destination. So be not in doubt about it. Indeed, it is the truth from your Lord, but most of the people do not believe.', NULL, NULL, '183db4b0ba23bf88b804a92a048fc56d8100aaf74bd6fb9aaf45f1022acec0ef'),
  ('en.sahih', 11, 18, 1491, 'And who is more unjust than he who invents a lie about Allah? Those will be presented before their Lord, and the witnesses will say, "These are the ones who lied against their Lord." Unquestionably, the curse of Allah is upon the wrongdoers.', NULL, NULL, '5d24abdd93ab75a1fff298e0b48feeb4e86ebee1f2b71e09b8f34effb20f64c6'),
  ('en.sahih', 11, 19, 1492, 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they, concerning the Hereafter, were disbelievers.', NULL, NULL, '300fe97971e985054ed9edfdd4d48b14b1ac844c86d98e722b5d599c80c88821'),
  ('en.sahih', 11, 20, 1493, 'Those were not causing failure [to Allah] on earth, nor did they have besides Allah any protectors. For them the punishment will be multiplied. They were not able to hear, nor did they see.', NULL, NULL, 'c30f25b95f547ec07e07bd360442a46b8b7da1b58f7a41be4673b798f3e5fd7f'),
  ('en.sahih', 11, 21, 1494, 'Those are the ones who will have lost themselves, and lost from them is what they used to invent.', NULL, NULL, 'c78326b8cc0b11ee1783c976c524f01ba0d79ef2ae4d4f8ae62f8e06908a71a8'),
  ('en.sahih', 11, 22, 1495, 'Assuredly, it is they in the Hereafter who will be the greatest losers.', NULL, NULL, '3f5bf498d8773421364d096271c31b53a5c6934f27f0e7ac924eafbf2b8d7fa2'),
  ('en.sahih', 11, 23, 1496, 'Indeed, they who have believed and done righteous deeds and humbled themselves to their Lord - those are the companions of Paradise; they will abide eternally therein.', NULL, NULL, '8b13ab6cccc68743a88b601cfc36b3169eb3b51f7befb3007973d1cfd333b34a'),
  ('en.sahih', 11, 24, 1497, 'The example of the two parties is like the blind and deaf, and the seeing and hearing. Are they equal in comparison? Then, will you not remember?', NULL, NULL, '784327299ecdc088a8dcd3e511e18aeda3e088ea01e58b2ef4f5e54c429c97e7'),
  ('en.sahih', 11, 25, 1498, 'And We had certainly sent Noah to his people, [saying], "Indeed, I am to you a clear warner', NULL, NULL, '20aeca8c44efaed5b5e21aa8d540dda28be2315ca8e09d4321e3eafd9e11c13e'),
  ('en.sahih', 11, 26, 1499, 'That you not worship except Allah. Indeed, I fear for you the punishment of a painful day."', NULL, NULL, '40e0fb5260be5c888e2f4645be577356759830b064bafd3690bb717730b2175e'),
  ('en.sahih', 11, 27, 1500, 'So the eminent among those who disbelieved from his people said, "We do not see you but as a man like ourselves, and we do not see you followed except by those who are the lowest of us [and] at first suggestion. And we do not see in you over us any merit; rather, we think you are liars."', NULL, NULL, 'e44bcf92cedcde8df335f3d57133b6bf2e034cd9aabf4f0b053c1776f180bc00')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 11, 28, 1501, 'He said, "O my people have you considered: if I should be upon clear evidence from my Lord while He has given me mercy from Himself but it has been made unapparent to you, should we force it upon you while you are averse to it?', NULL, NULL, 'f74679d7dae1e0febe44b48bae81936130204720a081a8c82f06df062070e74c'),
  ('en.sahih', 11, 29, 1502, 'And O my people, I ask not of you for it any wealth. My reward is not but from Allah. And I am not one to drive away those who have believed. Indeed, they will meet their Lord, but I see that you are a people behaving ignorantly.', NULL, NULL, '33d7787c9f5ddd0f91732e5b0a144bb569b4b6c5b499eeb7bdadd6474d38d897'),
  ('en.sahih', 11, 30, 1503, 'And O my people, who would protect me from Allah if I drove them away? Then will you not be reminded?', NULL, NULL, '08cc263aa978b7d5a452131b1e033bc0969101af079c928bd8ffd4ea9a73167a'),
  ('en.sahih', 11, 31, 1504, 'And I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel, nor do I say of those upon whom your eyes look down that Allah will never grant them any good. Allah is most knowing of what is within their souls. Indeed, I would then be among the wrongdoers."', NULL, NULL, '0c57e37405a8276e75a4863a212d621f2f5c06871f5a01eb1ccff20f989a80d2'),
  ('en.sahih', 11, 32, 1505, 'They said, "O Noah, you have disputed us and been frequent in dispute of us. So bring us what you threaten us, if you should be of the truthful."', NULL, NULL, '5dd36a38853dda3dedc4268f553c0140d76187770b654c282ab3eee7d8394036'),
  ('en.sahih', 11, 33, 1506, 'He said, "Allah will only bring it to you if He wills, and you will not cause [Him] failure.', NULL, NULL, '4633b9d857678b3485cb4ac51989d55de424c740164994f58bcbc78fde122b42'),
  ('en.sahih', 11, 34, 1507, 'And my advice will not benefit you - although I wished to advise you - If Allah should intend to put you in error. He is your Lord, and to Him you will be returned."', NULL, NULL, 'b3b035bff6f4c5039297dfe55bff8b462aaba90c5eafc713c00d31f78e6bcb78'),
  ('en.sahih', 11, 35, 1508, 'Or do they say [about Prophet Muhammad], "He invented it"? Say, "If I have invented it, then upon me is [the consequence of] my crime; but I am innocent of what [crimes] you commit."', NULL, NULL, '78db168b4e1cc84b14006b621d273cbb2b97bd750209fafd87adcff049fa2ddc'),
  ('en.sahih', 11, 36, 1509, 'And it was revealed to Noah that, "No one will believe from your people except those who have already believed, so do not be distressed by what they have been doing.', NULL, NULL, '82cd3d4118cd87d15030e8de1044ad911ebd571e94bb38fc3db211b697521dbf'),
  ('en.sahih', 11, 37, 1510, 'And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned."', NULL, NULL, '2b40e37b64be9f6d55b203bf97c57d656a9d502bf0c5067dc142aa92e0cc2793'),
  ('en.sahih', 11, 38, 1511, 'And he constructed the ship, and whenever an assembly of the eminent of his people passed by him, they ridiculed him. He said, "If you ridicule us, then we will ridicule you just as you ridicule.', NULL, NULL, 'a22334848963ae27878f7a1c2e875d519639b5c10e7dda9a95f0e9f39ad9f652'),
  ('en.sahih', 11, 39, 1512, 'And you are going to know who will get a punishment that will disgrace him [on earth] and upon whom will descend an enduring punishment [in the Hereafter]."', NULL, NULL, 'efdf6b55baca8376cb50688abe006988a8e134df70281168498480d6479b9fac'),
  ('en.sahih', 11, 40, 1513, '[So it was], until when Our command came and the oven overflowed, We said, "Load upon the ship of each [creature] two mates and your family, except those about whom the word has preceded, and [include] whoever has believed." But none had believed with him, except a few.', NULL, NULL, '7d602cde5afd6a107ac577b72ec1048b86c830b0db150a4157875c14a1ee6b9b'),
  ('en.sahih', 11, 41, 1514, 'And [Noah] said, "Embark therein; in the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful."', NULL, NULL, '02dd5d590b3f10e7d65986c302ca92f7d1d1e0f07d68ad42d14919ccffcdef99'),
  ('en.sahih', 11, 42, 1515, 'And it sailed with them through waves like mountains, and Noah called to his son who was apart [from them], "O my son, come aboard with us and be not with the disbelievers."', NULL, NULL, '968a44f6f9daedb4066f4bd57dbc58ddee35af962f53eee8e7759720c941cbfa'),
  ('en.sahih', 11, 43, 1516, '[But] he said, "I will take refuge on a mountain to protect me from the water." [Noah] said, "There is no protector today from the decree of Allah, except for whom He gives mercy." And the waves came between them, and he was among the drowned.', NULL, NULL, 'bdbee2ba8cce68c018e5f4b0bf79b2d4c714a0b04055eb7942a83d901e81c0e0'),
  ('en.sahih', 11, 44, 1517, 'And it was said, "O earth, swallow your water, and O sky, withhold [your rain]." And the water subsided, and the matter was accomplished, and the ship came to rest on the [mountain of] Judiyy. And it was said, "Away with the wrongdoing people."', NULL, NULL, 'f19cfeb19ad12c4e5a2a84ae8327af83220271de441f05bced98740e056a73b5'),
  ('en.sahih', 11, 45, 1518, 'And Noah called to his Lord and said, "My Lord, indeed my son is of my family; and indeed, Your promise is true; and You are the most just of judges!"', NULL, NULL, '6e182b86e2283acd7397d2f01acb034af7ca8471cb84c58ef125e43b95e89410'),
  ('en.sahih', 11, 46, 1519, 'He said, "O Noah, indeed he is not of your family; indeed, he is [one whose] work was other than righteous, so ask Me not for that about which you have no knowledge. Indeed, I advise you, lest you be among the ignorant."', NULL, NULL, '628f217a8418ebaa2c4d1ff931d72f1caca3ac472a4e891a7f0c6549c076b525'),
  ('en.sahih', 11, 47, 1520, '[Noah] said, "My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers."', NULL, NULL, '01ecce852498b52fb30845c03b4832e5202b856040a188c045a1c1e93c3af7ee'),
  ('en.sahih', 11, 48, 1521, 'It was said, "O Noah, disembark in security from Us and blessings upon you and upon nations [descending] from those with you. But other nations [of them] We will grant enjoyment; then there will touch them from Us a painful punishment."', NULL, NULL, '1d8c48c74dc7134c6bdc70b8baff613561807553c3cf5b5211ce432850b2344a'),
  ('en.sahih', 11, 49, 1522, 'That is from the news of the unseen which We reveal to you, [O Muhammad]. You knew it not, neither you nor your people, before this. So be patient; indeed, the [best] outcome is for the righteous.', NULL, NULL, '1d3c1bfa26d6bf85d9973ecfd79c7a31a44d8d4c7d6c171ffe7dd635fa62fbd5'),
  ('en.sahih', 11, 50, 1523, 'And to ''Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. You are not but inventors [of falsehood].', NULL, NULL, 'd5bdcc2a77bb3f0e4a292b37111aa147855ea9e2f5bab58fbf9ecb5c424f81ba'),
  ('en.sahih', 11, 51, 1524, 'O my people, I do not ask you for it any reward. My reward is only from the one who created me. Then will you not reason?', NULL, NULL, '05b3321005dd4f0d40fee95ccd6700398c7d00ee6da2a266c040920b8748f9ae'),
  ('en.sahih', 11, 52, 1525, 'And O my people, ask forgiveness of your Lord and then repent to Him. He will send [rain from] the sky upon you in showers and increase you in strength [added] to your strength. And do not turn away, [being] criminals."', NULL, NULL, '1bc1465ac793c5a9887c00e3c280d5f11fa0f706465e1d04c3af28f24258c419'),
  ('en.sahih', 11, 53, 1526, 'They said, "O Hud, you have not brought us clear evidence, and we are not ones to leave our gods on your say-so. Nor are we believers in you.', NULL, NULL, 'e3ef36f95db29c009e1e9c4030b4971a95f8f9bd1c4eaccb5ff58992efdeee28'),
  ('en.sahih', 11, 54, 1527, 'We only say that some of our gods have possessed you with evil." He said, "Indeed, I call Allah to witness, and witness [yourselves] that I am free from whatever you associate with Allah', NULL, NULL, '59ff110327bb27af6b60e2a1132205f83e810212eb996bfe24de9a15fca0881c'),
  ('en.sahih', 11, 55, 1528, 'Other than Him. So plot against me all together; then do not give me respite.', NULL, NULL, '7202642241197e26d4d0154b82fd90cae5020f3643cc21533bfc410aa6438c30'),
  ('en.sahih', 11, 56, 1529, 'Indeed, I have relied upon Allah, my Lord and your Lord. There is no creature but that He holds its forelock. Indeed, my Lord is on a path [that is] straight."', NULL, NULL, '2f8194802664b87dee38a8413efbb9dd99a7fc5e977f8bc5001e22c17e3b207e'),
  ('en.sahih', 11, 57, 1530, 'But if they turn away, [say], "I have already conveyed that with which I was sent to you. My Lord will give succession to a people other than you, and you will not harm Him at all. Indeed my Lord is, over all things, Guardian."', NULL, NULL, '4d287b00d5e00de5727adbc68a2af562c78cf0f241d16728ad43e7437d873e68'),
  ('en.sahih', 11, 58, 1531, 'And when Our command came, We saved Hud and those who believed with him, by mercy from Us; and We saved them from a harsh punishment.', NULL, NULL, '31929f970471b67a7ad6d05b406c9cc089da4b3b014fd893bcfc2558dbeeb006'),
  ('en.sahih', 11, 59, 1532, 'And that was ''Aad, who rejected the signs of their Lord and disobeyed His messengers and followed the order of every obstinate tyrant.', NULL, NULL, '70d9e034c0950ec02eaab55354f908a64d253487fc0d2e63603fd692395a343a'),
  ('en.sahih', 11, 60, 1533, 'And they were [therefore] followed in this world with a curse and [as well] on the Day of Resurrection. Unquestionably, ''Aad denied their Lord; then away with ''Aad, the people of Hud.', NULL, NULL, 'ed69714faef3128ebe443c746cb8fe48eccd23822535e0243979981ea78e444a'),
  ('en.sahih', 11, 61, 1534, 'And to Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. He has produced you from the earth and settled you in it, so ask forgiveness of Him and then repent to Him. Indeed, my Lord is near and responsive."', NULL, NULL, 'cff0e761e7a9ba46e054d74a2b97f893bd572f54a299302851d60dec41a9da90'),
  ('en.sahih', 11, 62, 1535, 'They said, "O Salih, you were among us a man of promise before this. Do you forbid us to worship what our fathers worshipped? And indeed we are, about that to which you invite us, in disquieting doubt."', NULL, NULL, '0f184bbac61ce102a674612cfee46c65c4a83127ae37430e9fecf5551ab2de00'),
  ('en.sahih', 11, 63, 1536, 'He said, "O my people, have you considered: if I should be upon clear evidence from my Lord and He has given me mercy from Himself, who would protect me from Allah if I disobeyed Him? So you would not increase me except in loss.', NULL, NULL, 'e0d763a80135d8f47baf9aac8162b31b3eab4a26f487aaaae0364549c5a7611c'),
  ('en.sahih', 11, 64, 1537, 'And O my people, this is the she-camel of Allah - [she is] to you a sign. So let her feed upon Allah ''s earth and do not touch her with harm, or you will be taken by an impending punishment."', NULL, NULL, '6c391f1d5f55bb05db5e5ff9546abd532c391008dd0838a4ccdcb5195994df98'),
  ('en.sahih', 11, 65, 1538, 'But they hamstrung her, so he said, "Enjoy yourselves in your homes for three days. That is a promise not to be denied."', NULL, NULL, 'd3901857c3baf716a053ca7bdf0b0f92810bbf7b86a442362a01fbab7a3ac3b8'),
  ('en.sahih', 11, 66, 1539, 'So when Our command came, We saved Salih and those who believed with him, by mercy from Us, and [saved them] from the disgrace of that day. Indeed, it is your Lord who is the Powerful, the Exalted in Might.', NULL, NULL, 'a472c4e027f25c465da2fd4bc12294f8dee6da6c8ba7c81ea35082dcdebe0dff'),
  ('en.sahih', 11, 67, 1540, 'And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone', NULL, NULL, 'cdec003a239f7557d97ebf3c1b180f6c5e992b5b7e915429e403c22be38fecbe'),
  ('en.sahih', 11, 68, 1541, 'As if they had never prospered therein. Unquestionably, Thamud denied their Lord; then, away with Thamud.', NULL, NULL, '775153c578618d75c2f7de38e584e081e1df7d38def9c20083165a3a203f7701'),
  ('en.sahih', 11, 69, 1542, 'And certainly did Our messengers come to Abraham with good tidings; they said, "Peace." He said, "Peace," and did not delay in bringing [them] a roasted calf.', NULL, NULL, '773d5b731d242299088e6732aec664ff1e876ea73a0252b077a16a715c1be437'),
  ('en.sahih', 11, 70, 1543, 'But when he saw their hands not reaching for it, he distrusted them and felt from them apprehension. They said, "Fear not. We have been sent to the people of Lot."', NULL, NULL, '3fd145617ea970dc9e2638231693ef5dd6dec15c1c6d90b2dd4e57e9ce688156'),
  ('en.sahih', 11, 71, 1544, 'And his Wife was standing, and she smiled. Then We gave her good tidings of Isaac and after Isaac, Jacob.', NULL, NULL, '5a7ca46127f2e27f365c898288d8f6985be3a83e03158fdf2f9e14febef8e00a'),
  ('en.sahih', 11, 72, 1545, 'She said, "Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is an amazing thing!"', NULL, NULL, '8aafc7913598f052ba455b1b49b6093890756bbc6365b92ab0c91e10955b13d7'),
  ('en.sahih', 11, 73, 1546, 'They said, "Are you amazed at the decree of Allah? May the mercy of Allah and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honorable."', NULL, NULL, '5c22834cfbb026a1fc8ed6f94852fd38e4474268cd0ef226bb7db20b8c17cbf8'),
  ('en.sahih', 11, 74, 1547, 'And when the fright had left Abraham and the good tidings had reached him, he began to argue with Us concerning the people of Lot.', NULL, NULL, 'd10281c1d6154dc3934df48c5fff50f4a079890e521ed2cab7698dd74a92b419'),
  ('en.sahih', 11, 75, 1548, 'Indeed, Abraham was forbearing, grieving and [frequently] returning [to Allah].', NULL, NULL, '550fb70b84c887a7a1bfc87ad11e066e8b855b85628c6f7b84f6cd433492d374'),
  ('en.sahih', 11, 76, 1549, '[The angels said], "O Abraham, give up this [plea]. Indeed, the command of your Lord has come, and indeed, there will reach them a punishment that cannot be repelled."', NULL, NULL, '75ff803818ce81906f749208de6106349b01640b05b22d3916c5f9016ff36ea5'),
  ('en.sahih', 11, 77, 1550, 'And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort and said, "This is a trying day."', NULL, NULL, '810a0734a8263c27bee8d15b12253d59a257590e13de1642f8796e3fd5ddd658'),
  ('en.sahih', 11, 78, 1551, 'And his people came hastening to him, and before [this] they had been doing evil deeds. He said, "O my people, these are my daughters; they are purer for you. So fear Allah and do not disgrace me concerning my guests. Is there not among you a man of reason?"', NULL, NULL, '1c066bae5e7ed8bf40fc8189e6664574c2c8486e56836a4a326df883eab6104e'),
  ('en.sahih', 11, 79, 1552, 'They said, "You have already known that we have not concerning your daughters any claim, and indeed, you know what we want."', NULL, NULL, 'b030b09baf5eb4fc38c73b3fcce71b672b608960523344a91649403975db0828'),
  ('en.sahih', 11, 80, 1553, 'He said, "If only I had against you some power or could take refuge in a strong support."', NULL, NULL, 'f3f29b66f63c5cbed327d2fdd1b4326d63decc76ac4e50d832200bb57306880e'),
  ('en.sahih', 11, 81, 1554, 'The angels said, "O Lot, indeed we are messengers of your Lord; [therefore], they will never reach you. So set out with your family during a portion of the night and let not any among you look back - except your wife; indeed, she will be struck by that which strikes them. Indeed, their appointment is [for] the morning. Is not the morning near?"', NULL, NULL, '003c1bb4ad74bf17e19edddc65f80b4869bfe59611135c6e91ae896af6216be6'),
  ('en.sahih', 11, 82, 1555, 'So when Our command came, We made the highest part [of the city] its lowest and rained upon them stones of layered hard clay, [which were]', NULL, NULL, '9bcc1bddb1843c4c0727e34244271998843f3f491edab84cb56b6bcca46a60d2'),
  ('en.sahih', 11, 83, 1556, 'Marked from your Lord. And Allah ''s punishment is not from the wrongdoers [very] far.', NULL, NULL, '220997cd3f177c97cfde46477dafb5dcb98d9f6f32c9b1c6dad71c3460877bb4'),
  ('en.sahih', 11, 84, 1557, 'And to Madyan [We sent] their brother Shu''ayb. He said, "O my people, worship Allah; you have no deity other than Him. And do not decrease from the measure and the scale. Indeed, I see you in prosperity, but indeed, I fear for you the punishment of an all-encompassing Day.', NULL, NULL, '95b4fb9b803e117841743088e6fd4713eb243b934a6617711da4d24316d41dfd'),
  ('en.sahih', 11, 85, 1558, 'And O my people, give full measure and weight in justice and do not deprive the people of their due and do not commit abuse on the earth, spreading corruption.', NULL, NULL, '2696f2e434f9d5f5d36af9f22e3906efa70876ecd448bd45f40089f0d7a61446'),
  ('en.sahih', 11, 86, 1559, 'What remains [lawful] from Allah is best for you, if you would be believers. But I am not a guardian over you."', NULL, NULL, 'f26b36e651ad053a2c0fa6402a3980e2e0222dc65f560577165b7353211b6392'),
  ('en.sahih', 11, 87, 1560, 'They said, "O Shu''ayb, does your prayer command you that we should leave what our fathers worship or not do with our wealth what we please? Indeed, you are the forbearing, the discerning!"', NULL, NULL, 'c8b6d919b91ac93342ac061c98138f2b80e8a9ca365ef84d56174445b6006290'),
  ('en.sahih', 11, 88, 1561, 'He said, "O my people, have you considered: if I am upon clear evidence from my Lord and He has provided me with a good provision from Him...? And I do not intend to differ from you in that which I have forbidden you; I only intend reform as much as I am able. And my success is not but through Allah. Upon him I have relied, and to Him I return.', NULL, NULL, '4529c33784118a1fb661e4eafb468552d0969dfd92b603cfad3bfd3aaec8a6df'),
  ('en.sahih', 11, 89, 1562, 'And O my people, let not [your] dissension from me cause you to be struck by that similar to what struck the people of Noah or the people of Hud or the people of Salih. And the people of Lot are not from you far away.', NULL, NULL, '63d40d05ad0996ad0d3a445ed196a84448647eb3e6e2160177d15b267ebf3e42'),
  ('en.sahih', 11, 90, 1563, 'And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate."', NULL, NULL, '3f351e682c3807e50c7c253cc7af3b239e2c5dc365d964397a9f4489f591ee0e'),
  ('en.sahih', 11, 91, 1564, 'They said, "O Shu''ayb, we do not understand much of what you say, and indeed, we consider you among us as weak. And if not for your family, we would have stoned you [to death]; and you are not to us one respected."', NULL, NULL, '7a32d85a3fc2b5bf2e0a66db6f139ed5e63c1b53c9762e7fbac591b0d46d3525'),
  ('en.sahih', 11, 92, 1565, 'He said, "O my people, is my family more respected for power by you than Allah? But you put Him behind your backs [in neglect]. Indeed, my Lord is encompassing of what you do.', NULL, NULL, '3275330f2d3308bce1db45e008035afd347eb58dab5503867be18992c7d07c75'),
  ('en.sahih', 11, 93, 1566, 'And O my people, work according to your position; indeed, I am working. You are going to know to whom will come a punishment that will disgrace him and who is a liar. So watch; indeed, I am with you a watcher, [awaiting the outcome]."', NULL, NULL, '9e2dd6c91452099d9f8e2c5f31a09a416574f8d11056ae53525d20de2712f532'),
  ('en.sahih', 11, 94, 1567, 'And when Our command came, We saved Shu''ayb and those who believed with him, by mercy from Us. And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone', NULL, NULL, '9672a9806e3f195fa9588c4153de7a8569ddfd9fb6c14d353b91d54be4266a26'),
  ('en.sahih', 11, 95, 1568, 'As if they had never prospered therein. Then, away with Madyan as Thamud was taken away.', NULL, NULL, '64bf9de696a689f5b790f7e058b8f2200361d663a728bcd4226bb56b1407e76d'),
  ('en.sahih', 11, 96, 1569, 'And We did certainly send Moses with Our signs and a clear authority', NULL, NULL, '2263f24c5afbd5cd14e5c63891b8d0e47785ece9fc4b88dc90c796ba20b7b861'),
  ('en.sahih', 11, 97, 1570, 'To Pharaoh and his establishment, but they followed the command of Pharaoh, and the command of Pharaoh was not [at all] discerning.', NULL, NULL, '6ff7f08974077a38eb879832710786b6f51e23badbfa6970c5b7b8351a3a291c'),
  ('en.sahih', 11, 98, 1571, 'He will precede his people on the Day of Resurrection and lead them into the Fire; and wretched is the place to which they are led.', NULL, NULL, '01c9dc40b017727a7a60538bb3d67e135747ba5c1d4918e2fe8027e6cfca8e73'),
  ('en.sahih', 11, 99, 1572, 'And they were followed in this [world] with a curse and on the Day of Resurrection. And wretched is the gift which is given.', NULL, NULL, '04b5dc7acf2228a2e915b982a9801c63ef294f65eaeefa57915299dc66e07dc0'),
  ('en.sahih', 11, 100, 1573, 'That is from the news of the cities, which We relate to you; of them, some are [still] standing and some are [as] a harvest [mowed down].', NULL, NULL, 'd37f8b10cb6ba4d03dd6a787836b3d5e9cc423ddd748ebe8a8301102ddb0d9cc'),
  ('en.sahih', 11, 101, 1574, 'And We did not wrong them, but they wronged themselves. And they were not availed at all by their gods which they invoked other than Allah when there came the command of your Lord. And they did not increase them in other than ruin.', NULL, NULL, '0ea025077d196361e0b99f4a4515ddf2d296fcd64e0ea47c9d7db1575903e25b'),
  ('en.sahih', 11, 102, 1575, 'And thus is the seizure of your Lord when He seizes the cities while they are committing wrong. Indeed, His seizure is painful and severe.', NULL, NULL, '7d2338d1458a98f67f029e91965b3b8f6c01ad658c273699a69f266b5594886e'),
  ('en.sahih', 11, 103, 1576, 'Indeed in that is a sign for those who fear the punishment of the Hereafter. That is a Day for which the people will be collected, and that is a Day [which will be] witnessed.', NULL, NULL, 'd0e7fe76899bfa076404b6ae41e48762c689cb453aa0640f3c3eb3f9fade7fab'),
  ('en.sahih', 11, 104, 1577, 'And We do not delay it except for a limited term.', NULL, NULL, '7f044127811d1f555979d9a104bbaeaa0765e33bb54d43f9384126e7469630a4'),
  ('en.sahih', 11, 105, 1578, 'The Day it comes no soul will speak except by His permission. And among them will be the wretched and the prosperous.', NULL, NULL, '910e6a37a987bfd4d508aeb710718f112f8f62f06a3b277f562dcd4a6d89bb5c'),
  ('en.sahih', 11, 106, 1579, 'As for those who were [destined to be] wretched, they will be in the Fire. For them therein is [violent] exhaling and inhaling.', NULL, NULL, '2f4602ce315bfa9a6565cacfcd19c39440997dfe6276a0170b035bc803b8b639'),
  ('en.sahih', 11, 107, 1580, '[They will be] abiding therein as long as the heavens and the earth endure, except what your Lord should will. Indeed, your Lord is an effecter of what He intends.', NULL, NULL, '4bd4f052bb710c47539931d776c5fead38e8d179afed78c95661553fe86c2310'),
  ('en.sahih', 11, 108, 1581, 'And as for those who were [destined to be] prosperous, they will be in Paradise, abiding therein as long as the heavens and the earth endure, except what your Lord should will - a bestowal uninterrupted.', NULL, NULL, '16d8bc9b038014642bd62c91c18423701cfd2b001873a5faf20c4659ab6017fb'),
  ('en.sahih', 11, 109, 1582, 'So do not be in doubt, [O Muhammad], as to what these [polytheists] are worshipping. They worship not except as their fathers worshipped before. And indeed, We will give them their share undiminished.', NULL, NULL, '055c9f09af33b19aef2445bc6b87a2f33e4811d5999a32418f2535f8f2d784d7'),
  ('en.sahih', 11, 110, 1583, 'And We had certainly given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been judged between them. And indeed they are, concerning the Qur''an, in disquieting doubt.', NULL, NULL, '85c274781e40e6dd5092e82dd10d23c27988b937ad5fd0d13522d3a758fbc5e2'),
  ('en.sahih', 11, 111, 1584, 'And indeed, each [of the believers and disbelievers] - your Lord will fully compensate them for their deeds. Indeed, He is Acquainted with what they do.', NULL, NULL, '340b06791029daa76b8fadd37ab116a7630fd97aae076f0ceb3b9d18f75ae57f'),
  ('en.sahih', 11, 112, 1585, 'So remain on a right course as you have been commanded, [you] and those who have turned back with you [to Allah], and do not transgress. Indeed, He is Seeing of what you do.', NULL, NULL, '6ed8487bedb758be9c7389652a16f8e523b1f4a8679619bc8ab2493c434a0e56'),
  ('en.sahih', 11, 113, 1586, 'And do not incline toward those who do wrong, lest you be touched by the Fire, and you would not have other than Allah any protectors; then you would not be helped.', NULL, NULL, '6f3b17915a2eff7493d4902526d382eb027dc3d45bc61f125d23f13f2c8fa3e7'),
  ('en.sahih', 11, 114, 1587, 'And establish prayer at the two ends of the day and at the approach of the night. Indeed, good deeds do away with misdeeds. That is a reminder for those who remember.', NULL, NULL, '8e4df28983cb98ca824d3bfdf8cd410f334fdf4cb882d2a93fd6567d13c2c3b9'),
  ('en.sahih', 11, 115, 1588, 'And be patient, for indeed, Allah does not allow to be lost the reward of those who do good.', NULL, NULL, 'ffb3933b572140c13204320f2c8de654840cfbbe80f65bc6f9952c0a4e556203'),
  ('en.sahih', 11, 116, 1589, 'So why were there not among the generations before you those of enduring discrimination forbidding corruption on earth - except a few of those We saved from among them? But those who wronged pursued what luxury they were given therein, and they were criminals.', NULL, NULL, 'b5042f1b6955e6ec9d6d01e9af2ec3a0090f02a1386ae8d3f976393219db5457'),
  ('en.sahih', 11, 117, 1590, 'And your Lord would not have destroyed the cities unjustly while their people were reformers.', NULL, NULL, '3ac7f33c1ab6dc704ce234dc742d911a80d5383340ca4fc3b6088c69d30d11a3'),
  ('en.sahih', 11, 118, 1591, 'And if your Lord had willed, He could have made mankind one community; but they will not cease to differ.', NULL, NULL, '87aacb0f1ead9613588c72faef783db1926f73b955b717e4b805e53a6f73c305'),
  ('en.sahih', 11, 119, 1592, 'Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, "I will surely fill Hell with jinn and men all together."', NULL, NULL, 'f85e30c9a1e1a584c9494a3446330ad74634d3fa7bcee0069166eacdec129a8e'),
  ('en.sahih', 11, 120, 1593, 'And each [story] We relate to you from the news of the messengers is that by which We make firm your heart. And there has come to you, in this, the truth and an instruction and a reminder for the believers.', NULL, NULL, '4b9eca3832d3edc37596edefbcdcedf8eef702b06a9fc8bf93484726cb772d79'),
  ('en.sahih', 11, 121, 1594, 'And say to those who do not believe, "Work according to your position; indeed, we are working.', NULL, NULL, '8cd873bf00f1a5ce76f53e888dcb7f4a3b88e94cf916e7e8561e82d963e403ef'),
  ('en.sahih', 11, 122, 1595, 'And wait, indeed, we are waiting."', NULL, NULL, '2e7355f0d6b4fc4994d43ab5a8b36de376ebe65921cdd158748b7422bc34521c'),
  ('en.sahih', 11, 123, 1596, 'And to Allah belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do.', NULL, NULL, 'b6c420076912e5ce85ac8a64fd4c9955dfac683648b2611f93bcd439e449579f'),
  ('en.sahih', 12, 1, 1597, 'Alif, Lam, Ra. These are the verses of the clear Book.', NULL, NULL, 'b1e949a89c3f4ed91364bc9b307e0ae28128afcb0f002abcd2176e0f29089d43'),
  ('en.sahih', 12, 2, 1598, 'Indeed, We have sent it down as an Arabic Qur''an that you might understand.', NULL, NULL, '9d7f6e2eb9db22e645668bc55922c9e4a17376594b3e04a5e46a2f78e1707fcc'),
  ('en.sahih', 12, 3, 1599, 'We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur''an although you were, before it, among the unaware.', NULL, NULL, '972298cfbc3cbc1aa6f00c036169d4396ac17dc87baf4dea6e17bb501023d45c'),
  ('en.sahih', 12, 4, 1600, '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."', NULL, NULL, '5100880e9ab217a5fcb405c019126b642e35beec7293d46545a8545e305ec9a7')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 12, 5, 1601, 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.', NULL, NULL, '5114576afc81b63ac63371f4cd8119407765c831f1d5e89c0d3561472c8f7913'),
  ('en.sahih', 12, 6, 1602, 'And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."', NULL, NULL, '1f357ca7ed7170bae1d52b0c9adda181d7e82e4babd8a01319c554b247cbfde4'),
  ('en.sahih', 12, 7, 1603, 'Certainly were there in Joseph and his brothers signs for those who ask,', NULL, NULL, 'bf1d72841f92d753a08af27335ab3f460aaeccafa516658b86d1c4829b4a7d49'),
  ('en.sahih', 12, 8, 1604, 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.', NULL, NULL, 'dbba216344b17c0bad6d723e63ee38ce68ae596dfa7004478bfb6b844a70536c'),
  ('en.sahih', 12, 9, 1605, 'Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people."', NULL, NULL, '80e60af954cce8d50c8c6eca6be7bac248d4cfab1b4ca63a328a10254b572331'),
  ('en.sahih', 12, 10, 1606, 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."', NULL, NULL, 'c675edb44b03193962f3b5f37ef11cc4a7eb978d48fb618d9da8df4af9b890ff'),
  ('en.sahih', 12, 11, 1607, 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?', NULL, NULL, '593f38025410d9b0b7fdbde68630974e30c1be541734d251dce67114dc2d00b0'),
  ('en.sahih', 12, 12, 1608, 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.', NULL, NULL, 'fd37677ec943c1383032a7274ae9b8dfc12ff8d4b3eae32cdddbbccfd46488c5'),
  ('en.sahih', 12, 13, 1609, '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."', NULL, NULL, 'ea13cd202048eac9c5a3e2f71e00914ea5b519b7740da234fce016bc78d32621'),
  ('en.sahih', 12, 14, 1610, 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."', NULL, NULL, 'a32f237a39508dee23b8932b8d8a5b86a51502e4f31f3f22b5d4a88e7f8ab7c3'),
  ('en.sahih', 12, 15, 1611, 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."', NULL, NULL, '12a85e926c8ae408bc8320c89615452c26aea9433609f2c943efd09e03c0395a'),
  ('en.sahih', 12, 16, 1612, 'And they came to their father at night, weeping.', NULL, NULL, 'c00f6cd7c493804e2dc45669265831f218e22b9c4c02d733d7b3ff4c31c127f1'),
  ('en.sahih', 12, 17, 1613, 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."', NULL, NULL, '45c51c035c170944b644a318b269f4a01ef44cdd63a7b3ea130880e9c890cc15'),
  ('en.sahih', 12, 18, 1614, 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe."', NULL, NULL, '7d0d31689d4f438981a4d6a4e48fadf9483ecac1f09def1dce8c972bd9f7ec83'),
  ('en.sahih', 12, 19, 1615, 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did.', NULL, NULL, '90de852c87cecca01d5df3e6797eb3deec586e14c849a49bbec3ccdcea8c4084'),
  ('en.sahih', 12, 20, 1616, 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.', NULL, NULL, '9a472f0b624655506b23dcde8a490a03dae5f8a59b6e492697166f67174b2b09'),
  ('en.sahih', 12, 21, 1617, 'And the one from Egypt who bought him said to his wife, "Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son." And thus, We established Joseph in the land that We might teach him the interpretation of events. And Allah is predominant over His affair, but most of the people do not know.', NULL, NULL, '021f9f55ecd4272019a780f38e7ed002eeb751ed9338cec219011d86cf8d41f4'),
  ('en.sahih', 12, 22, 1618, 'And when Joseph reached maturity, We gave him judgment and knowledge. And thus We reward the doers of good.', NULL, NULL, '9fa1d100bf3eaa4d56af04e877eac2616148053a3f19c6e12d5caca0e901de67'),
  ('en.sahih', 12, 23, 1619, 'And she, in whose house he was, sought to seduce him. She closed the doors and said, "Come, you." He said, "[I seek] the refuge of Allah. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed."', NULL, NULL, '87eeaa7eb62844f229c968be53bdc26fb0d19387ce867e2b4afea5579e017cd4'),
  ('en.sahih', 12, 24, 1620, 'And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants.', NULL, NULL, '82ab7533a8e66d40d3f313a093650426b39bf0a64d6edfd6dba7bbdcd275d0d3'),
  ('en.sahih', 12, 25, 1621, 'And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, "What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?"', NULL, NULL, '019da68104b060ce17dbd9889988432c9b11753a1ce86f98564c5746b68907e2'),
  ('en.sahih', 12, 26, 1622, '[Joseph] said, "It was she who sought to seduce me." And a witness from her family testified. "If his shirt is torn from the front, then she has told the truth, and he is of the liars.', NULL, NULL, '5cec3ae1d12678032a94cb31394a45e437bdb8df0d6394b33c049bddfd1901d5'),
  ('en.sahih', 12, 27, 1623, 'But if his shirt is torn from the back, then she has lied, and he is of the truthful."', NULL, NULL, '13ff6ee0e0aa73b51095d3882e2425bf5e5a5aacd47871aeac9c2391091c5f0f'),
  ('en.sahih', 12, 28, 1624, 'So when her husband saw his shirt torn from the back, he said, "Indeed, it is of the women''s plan. Indeed, your plan is great.', NULL, NULL, 'e2158a880904384ee5855e04575eb4e8a3b7dcd8ea00254121e30178a2270ec4'),
  ('en.sahih', 12, 29, 1625, 'Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful."', NULL, NULL, '7483cfec14f93fb2e2df04bea6995c2156da96161a9e5b59038daf7dae999ccd'),
  ('en.sahih', 12, 30, 1626, 'And women in the city said, "The wife of al-''Azeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error."', NULL, NULL, 'f5fcc21de1c74fdd92246e3432afdaed245ad199795581eba0dc62906dbda699'),
  ('en.sahih', 12, 31, 1627, 'So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], "Come out before them." And when they saw him, they greatly admired him and cut their hands and said, "Perfect is Allah! This is not a man; this is none but a noble angel."', NULL, NULL, '57cd5f20eade6f74a8b8426f59d23a9456c8e43187f9d230f1fee0425bbc9139'),
  ('en.sahih', 12, 32, 1628, 'She said, "That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased."', NULL, NULL, 'dfe38257cdca095c40a34f9bf9538a52771bef02c05d1af40cc17afa6a78f22b'),
  ('en.sahih', 12, 33, 1629, 'He said, "My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."', NULL, NULL, 'a2c2799f4e1ad553370229e26e0f015c6343e443c68b4edbbb3a1b4221cea1d9'),
  ('en.sahih', 12, 34, 1630, 'So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing.', NULL, NULL, '5182db452ff3233d26d393aeb51418ccf9507da6373ce803c5aa4b65ce711302'),
  ('en.sahih', 12, 35, 1631, 'Then it appeared to them after they had seen the signs that al-''Azeez should surely imprison him for a time.', NULL, NULL, '77ec2f19342fb717cea145b9c6aa2e5568c376d4a08e1dfeddedca9d9d87eaa4'),
  ('en.sahih', 12, 36, 1632, 'And there entered the prison with him two young men. One of them said, "Indeed, I have seen myself [in a dream] pressing wine." The other said, "Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good."', NULL, NULL, '92db01c5754f76def2b98af572e8ed997779017fd1ecb361187f34034e5b7d45'),
  ('en.sahih', 12, 37, 1633, 'He said, "You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allah, and they, in the Hereafter, are disbelievers.', NULL, NULL, 'aed05f52031166c2a6d11ab3953162764479707fd2cb936a6bf01f7f35e1df34'),
  ('en.sahih', 12, 38, 1634, 'And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allah. That is from the favor of Allah upon us and upon the people, but most of the people are not grateful.', NULL, NULL, '2982caf3924f27f32217d92f8f85f0f82a2bb0a3c61dc36f076a75b900be1a2e'),
  ('en.sahih', 12, 39, 1635, 'O [my] two companions of prison, are separate lords better or Allah, the One, the Prevailing?', NULL, NULL, '406cb536463082284eccf7f4a1d481ff51a280bc9ae0ff02d4b59b528a06ad7b'),
  ('en.sahih', 12, 40, 1636, 'You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allah has sent down no authority. Legislation is not but for Allah. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know.', NULL, NULL, '0cadd1e4095ae8bc5613caf7f7d49d6905ea06e5a057d24f16ac5c7f280cc6b9'),
  ('en.sahih', 12, 41, 1637, 'O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire."', NULL, NULL, 'b81231727a58a762968501ce4621b5871ad23b1f67dc81f3478b9fe38a9f8c82'),
  ('en.sahih', 12, 42, 1638, 'And he said to the one whom he knew would go free, "Mention me before your master." But Satan made him forget the mention [to] his master, and Joseph remained in prison several years.', NULL, NULL, '8d8101465cffa9a6e024e61b2fac35b527333a16e8276e28c1f96f4cb0e86783'),
  ('en.sahih', 12, 43, 1639, 'And [subsequently] the king said, "Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions."', NULL, NULL, '93f47dc12ed6f978c53c69308228b9bae2b294e95e0ff11905719304872c144e'),
  ('en.sahih', 12, 44, 1640, 'They said, "[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams."', NULL, NULL, '28751304cb89e4e3b93917445f0b7926989e5d3eb35b29bebc4bafb4a86c464c'),
  ('en.sahih', 12, 45, 1641, 'But the one who was freed and remembered after a time said, "I will inform you of its interpretation, so send me forth."', NULL, NULL, '3a4d2deb64ca788d7bab1b380cf0769a0b699004e740886cea09c3184fa707fb'),
  ('en.sahih', 12, 46, 1642, '[He said], "Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people; perhaps they will know [about you]."', NULL, NULL, '823469411c31e835d7682e743edecdf366edec0902fee4957383ec4f45060df7'),
  ('en.sahih', 12, 47, 1643, '[Joseph] said, "You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat.', NULL, NULL, '0896182086720aa2545073b4062aa8244bdadda2424c0bfc8cdb488f5ebb4904'),
  ('en.sahih', 12, 48, 1644, 'Then will come after that seven difficult [years] which will consume what you saved for them, except a little from which you will store.', NULL, NULL, '747bbc192bf1e1f17173edf20109e88060911086f4140b5016d9c722980ecab8'),
  ('en.sahih', 12, 49, 1645, 'Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes]."', NULL, NULL, 'db8777fd20acdef5f6125e23dbccf09d75ccd9db27a604f68e2131d7de3a5e0c'),
  ('en.sahih', 12, 50, 1646, 'And the king said, "Bring him to me." But when the messenger came to him, [Joseph] said, "Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan."', NULL, NULL, '804eb37a19f4c27ced001215c8b85176be602747365ea1cc24e700ed6775cd1c'),
  ('en.sahih', 12, 51, 1647, 'Said [the king to the women], "What was your condition when you sought to seduce Joseph?" They said, "Perfect is Allah! We know about him no evil." The wife of al-''Azeez said, "Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.', NULL, NULL, '9454445e2097ba1ab37892c1e46267ec81f5f5f7ba229750a4f900ecad195964'),
  ('en.sahih', 12, 52, 1648, 'That is so al-''Azeez will know that I did not betray him in [his] absence and that Allah does not guide the plan of betrayers.', NULL, NULL, '7a30d5ceb6c55c4fb6458f45545552444ddc0b83dde05e17f3c3fb4710e3699f'),
  ('en.sahih', 12, 53, 1649, 'And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful."', NULL, NULL, '4d11e7eb1fc1c05a6457b22a5aabdab840c4c58c0dfb777dfb8d98c450385a77'),
  ('en.sahih', 12, 54, 1650, 'And the king said, "Bring him to me; I will appoint him exclusively for myself." And when he spoke to him, he said, "Indeed, you are today established [in position] and trusted."', NULL, NULL, 'f2c9cbd85c65610e5e6fd00325db7fe731f5340b3c8e603ad46572d9c65ed1fa'),
  ('en.sahih', 12, 55, 1651, '[Joseph] said, "Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian."', NULL, NULL, 'e2ea1979c98a45363c4b3c22a3613f3d92777d05fb0b7a7f41a69b1062dabd6b'),
  ('en.sahih', 12, 56, 1652, 'And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good.', NULL, NULL, 'da2f28fc50df125d3189ae5527bc1a29f7a7e2a3c7c60c7f4ecbf15b23bdeec8'),
  ('en.sahih', 12, 57, 1653, 'And the reward of the Hereafter is better for those who believed and were fearing Allah.', NULL, NULL, '359a21812e54443afb8a7df035b72757b8751c9dd9bc25ac2929c8b225ca80ed'),
  ('en.sahih', 12, 58, 1654, 'And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown.', NULL, NULL, 'ec5097ee98cf548a63c4ec10c627a2ffb95250db73dcbfabea040e4b12feafb5'),
  ('en.sahih', 12, 59, 1655, 'And when he had furnished them with their supplies, he said, "Bring me a brother of yours from your father. Do not you see that I give full measure and that I am the best of accommodators?', NULL, NULL, '9043fb9a887e4b4a2ac63f342c9e2742a37dab36bacac934a3207fbde010f0c2'),
  ('en.sahih', 12, 60, 1656, 'But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me."', NULL, NULL, 'c4b22728f03a6810d2ddc87720810b400f1e88899b602e0b25f72a981c7875dd'),
  ('en.sahih', 12, 61, 1657, 'They said, "We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it]."', NULL, NULL, 'cce228fc076830545b765de7b75756ea22427491c84d1a4a9068f753f58a9c3c'),
  ('en.sahih', 12, 62, 1658, 'And [Joseph] said to his servants, "Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return."', NULL, NULL, 'c0f83aa0957526a86ef2e797cdba08e19a0d7ed3a4b3af2f03db8f94e2ff8f20'),
  ('en.sahih', 12, 63, 1659, 'So when they returned to their father, they said, "O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians."', NULL, NULL, '0d77a628174a11fc038c258e6753fe06d792e1f6ecbab92f831531a3e260b783'),
  ('en.sahih', 12, 64, 1660, 'He said, "Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allah is the best guardian, and He is the most merciful of the merciful."', NULL, NULL, '70b3e2a17da8f0a39566713fb846cf8b643dcb32b7fd44a021a5b9c815a3e4b4'),
  ('en.sahih', 12, 65, 1661, 'And when they opened their baggage, they found their merchandise returned to them. They said, "O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies for our family and protect our brother and obtain an increase of a camel''s load; that is an easy measurement."', NULL, NULL, 'a9208b71dac0cea524235b9081157dce46f6194eb88940c06d001b98d16fb22f'),
  ('en.sahih', 12, 66, 1662, '[Jacob] said, "Never will I send him with you until you give me a promise by Allah that you will bring him [back] to me, unless you should be surrounded by enemies." And when they had given their promise, he said, "Allah, over what we say, is Witness."', NULL, NULL, '0d36f66a4ac5c4b7d032841ab2fa0b8c510a206f81bf0981d1ef53197f655ad4'),
  ('en.sahih', 12, 67, 1663, 'And he said, "O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allah at all. The decision is only for Allah; upon Him I have relied, and upon Him let those who would rely [indeed] rely."', NULL, NULL, '8fad0379ce541d2789e408b5996ecddb8ec528c7c9cb872b6a32accec4366a5e'),
  ('en.sahih', 12, 68, 1664, 'And when they entered from where their father had ordered them, it did not avail them against Allah at all except [it was] a need within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know.', NULL, NULL, '8b4e7fde3c5ff5c2b82d92d10d5bf88c01325b5dceff0cd4c397dbb1a1003d5d'),
  ('en.sahih', 12, 69, 1665, 'And when they entered upon Joseph, he took his brother to himself; he said, "Indeed, I am your brother, so do not despair over what they used to do [to me]."', NULL, NULL, '74ca29311c10273f202e58c02ccaa07632009686d8635eb97d6e545bc14a9ce5'),
  ('en.sahih', 12, 70, 1666, 'So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, "O caravan, indeed you are thieves."', NULL, NULL, '3fb0922572702ed696376a1d2e9cd48e7508b7f33070dbf3ca323e428c536674'),
  ('en.sahih', 12, 71, 1667, 'They said while approaching them, "What is it you are missing?"', NULL, NULL, 'ee29d364890ca8b2be3a11ab935b4214f64613569aac0a253922860e150db24e'),
  ('en.sahih', 12, 72, 1668, 'They said, "We are missing the measure of the king. And for he who produces it is [the reward of] a camel''s load, and I am responsible for it."', NULL, NULL, 'd077593324f5c9d720ea3f147777a734428a163d0979001704f75c2e3d693eff'),
  ('en.sahih', 12, 73, 1669, 'They said, "By Allah, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves."', NULL, NULL, '8d5b52157f956eaf128ab7f84a556e87e631c50be6f225cbe5bbd5525fcb2820'),
  ('en.sahih', 12, 74, 1670, 'The accusers said, "Then what would be its recompense if you should be liars?"', NULL, NULL, 'e6f085edbff6f7a5cff4a27bc9f691a0efd28b84726c533f4f1d8f59ff7e3e9b'),
  ('en.sahih', 12, 75, 1671, '[The brothers] said, "Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers."', NULL, NULL, 'c9a7660ba313e4c8eb31b4391e92a346425285657bb451325571c19b2893d6f7'),
  ('en.sahih', 12, 76, 1672, 'So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion of the king except that Allah willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing.', NULL, NULL, '257c2dfb9f1bd0c229208419281739e46f43c13f86beabc6600f312d48b2ebc7'),
  ('en.sahih', 12, 77, 1673, 'They said, "If he steals - a brother of his has stolen before." But Joseph kept it within himself and did not reveal it to them. He said, "You are worse in position, and Allah is most knowing of what you describe."', NULL, NULL, '478fb3bb76c87ee40dbc32a91a44936522a4abf8aa40b74532f61c277e554980'),
  ('en.sahih', 12, 78, 1674, 'They said, "O ''Azeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good."', NULL, NULL, '8a4f18fbee97eacd247ae9d03af09d022edde5bb215a7865d4dda12992d2ee51'),
  ('en.sahih', 12, 79, 1675, 'He said, "[I seek] the refuge of Allah [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust."', NULL, NULL, '8eb35deba4b2bc6a2ba5e97ca401f996f5e7c72b9dd8fc05388e4a9198df9ca5'),
  ('en.sahih', 12, 80, 1676, 'So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, "Do you not know that your father has taken upon you an oath by Allah and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allah decides for me, and He is the best of judges.', NULL, NULL, 'cf177c798265c76a870bd98eed666911f5b504df87eab3f33683cee10e1602ce'),
  ('en.sahih', 12, 81, 1677, 'Return to your father and say, "O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen,', NULL, NULL, 'f63aab0928a252db67cb28dbd18a0a4c554684031f0ebe461d7af575625a66e0'),
  ('en.sahih', 12, 82, 1678, 'And ask the city in which we were and the caravan in which we came - and indeed, we are truthful,"', NULL, NULL, '09ed30d0eb72d0985c06601b393639150dd70dc24ea6d0d0051c1ef2f650a185'),
  ('en.sahih', 12, 83, 1679, '[Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allah will bring them to me all together. Indeed it is He who is the Knowing, the Wise."', NULL, NULL, '143bafcb28395db2fea0745abda3e7e8396e2c82edcc7eb40807c73bdfe3061b'),
  ('en.sahih', 12, 84, 1680, 'And he turned away from them and said, "Oh, my sorrow over Joseph," and his eyes became white from grief, for he was [of that] a suppressor.', NULL, NULL, 'b3c5b85b30a91c4e40021a056b90321a90502726b56140783d9f96e5aa2f1fd2'),
  ('en.sahih', 12, 85, 1681, 'They said, "By Allah, you will not cease remembering Joseph until you become fatally ill or become of those who perish."', NULL, NULL, 'b86e04772e4f65f6b3d638251289091bb1070552a45ce6d09e27210af00d00bf'),
  ('en.sahih', 12, 86, 1682, 'He said, "I only complain of my suffering and my grief to Allah, and I know from Allah that which you do not know.', NULL, NULL, 'eb6e7c2056cd00c61f7739666ad518ac405afe658d1c29b7ccd08c640daf302e'),
  ('en.sahih', 12, 87, 1683, 'O my sons, go and find out about Joseph and his brother and despair not of relief from Allah. Indeed, no one despairs of relief from Allah except the disbelieving people."', NULL, NULL, '946474981043687bb9502ffcedd7c596b1473bba893975e754fa056336e11269'),
  ('en.sahih', 12, 88, 1684, 'So when they entered upon Joseph, they said, "O ''Azeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allah rewards the charitable."', NULL, NULL, '89e0527327fb81872210f3058e602f8d309ad0e8d6e2ef2771cbad4251efa22b'),
  ('en.sahih', 12, 89, 1685, 'He said, "Do you know what you did with Joseph and his brother when you were ignorant?"', NULL, NULL, 'd5bc2141023f2fb2fe7528ad4e73d52982af236f8669f17a63916dc01511b58e'),
  ('en.sahih', 12, 90, 1686, 'They said, "Are you indeed Joseph?" He said "I am Joseph, and this is my brother. Allah has certainly favored us. Indeed, he who fears Allah and is patient, then indeed, Allah does not allow to be lost the reward of those who do good."', NULL, NULL, '3cb454573535f99e26d0b573c58a4afaa4b7afd531605c19fad7992af6d25e63'),
  ('en.sahih', 12, 91, 1687, 'They said, "By Allah, certainly has Allah preferred you over us, and indeed, we have been sinners."', NULL, NULL, 'acda8334ad4b0602b34c1cfe55cc07bda905f5f6f09308ec6cf7f50db0596e17'),
  ('en.sahih', 12, 92, 1688, 'He said, "No blame will there be upon you today. Allah will forgive you; and He is the most merciful of the merciful."', NULL, NULL, '15b638f39869867bfbe207e7cfe2ac76da27eb52940764b80c63e9ecbc6ea402'),
  ('en.sahih', 12, 93, 1689, 'Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together."', NULL, NULL, '4465e70d7401082f5461139e320e42ae79c25c038a699cf57b896c2e7dc36f6d'),
  ('en.sahih', 12, 94, 1690, 'And when the caravan departed [from Egypt], their father said, "Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind."', NULL, NULL, 'e3ab9ec79dab54b488290155af8099b10c6b6c71d1d04bdb2768f65f0583d86f'),
  ('en.sahih', 12, 95, 1691, 'They said, "By Allah, indeed you are in your [same] old error."', NULL, NULL, 'bb1da9e479fa1c196b1f1ef85981dec78c7d63b41ae9667155e2655956b246a3'),
  ('en.sahih', 12, 96, 1692, 'And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, "Did I not tell you that I know from Allah that which you do not know?"', NULL, NULL, '3cf8aca1ae8235d30187d2948a23eec4aee5dc6ee6fb7d402e7385ee69390c07'),
  ('en.sahih', 12, 97, 1693, 'They said, "O our father, ask for us forgiveness of our sins; indeed, we have been sinners."', NULL, NULL, '5ce19eb1f6030d2e910fa1c0b63f103c4cfb9bf8484e2b64de026a563be88499'),
  ('en.sahih', 12, 98, 1694, 'He said, "I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful."', NULL, NULL, 'a1544de87cce4a0c7c29212981eaa83525c80bf997710973366abbeb5da6b37f'),
  ('en.sahih', 12, 99, 1695, 'And when they entered upon Joseph, he took his parents to himself and said, "Enter Egypt, Allah willing, safe [and secure]."', NULL, NULL, '994ed99e34f27a59533fca446e2b083ea771d7700b0307639496435a637091f6'),
  ('en.sahih', 12, 100, 1696, 'And he raised his parents upon the throne, and they bowed to him in prostration. And he said, "O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise.', NULL, NULL, 'a2b05c912517e3d143dc2e5fe20b028b55790ec9a2c2c42322e2d5eef75bc126'),
  ('en.sahih', 12, 101, 1697, 'My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous."', NULL, NULL, '12329c9c72940fd0d74825061f10a9d59990a13ce4ca4c5aa11d898afabd2730'),
  ('en.sahih', 12, 102, 1698, 'That is from the news of the unseen which We reveal, [O Muhammad], to you. And you were not with them when they put together their plan while they conspired.', NULL, NULL, 'f0e08536e7247662d5f92017abc22d0e121fdca2cee6186d30eb1d0feafcdf30'),
  ('en.sahih', 12, 103, 1699, 'And most of the people, although you strive [for it], are not believers.', NULL, NULL, '5fcc91f787113dc144af88c3198fb93fe3c9dbf448d033a43377b99d03fc4b24'),
  ('en.sahih', 12, 104, 1700, 'And you do not ask of them for it any payment. It is not except a reminder to the worlds.', NULL, NULL, '22756cd15030b6dd899b7d5e348b636555c6de6940ebacb1d6b57e40a6ec1244')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 12, 105, 1701, 'And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away.', NULL, NULL, '8895218795c0895a3523fc2471364e0d9b1c3a40d412e23073ad9aaeec9be692'),
  ('en.sahih', 12, 106, 1702, 'And most of them believe not in Allah except while they associate others with Him.', NULL, NULL, '462b7d0682005a7cdc36253bf3232031bc894c3e79129684cb9912dc0703eb44'),
  ('en.sahih', 12, 107, 1703, 'Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allah or that the Hour will not come upon them suddenly while they do not perceive?', NULL, NULL, '8d7b8500d3ea2b8608e300fd5ab4aeeefaf932f9873e9894cf4dcb7dc25d363e'),
  ('en.sahih', 12, 108, 1704, 'Say, "This is my way; I invite to Allah with insight, I and those who follow me. And exalted is Allah; and I am not of those who associate others with Him."', NULL, NULL, 'fca0fc9eb241fd9b035f0be5006a9fea39d64d7afe69a587c84d8595937b62c9'),
  ('en.sahih', 12, 109, 1705, 'And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allah; then will you not reason?', NULL, NULL, 'c07e52a0c7077c763c9c19caa7ace6c16b3a38f58bd9787c977265deff86e69d'),
  ('en.sahih', 12, 110, 1706, '[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals.', NULL, NULL, '3f81367947ad6d879fe4b7c70c570624ba599828d5d313d799b61ed50f48757d'),
  ('en.sahih', 12, 111, 1707, 'There was certainly in their stories a lesson for those of understanding. Never was the Qur''an a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.', NULL, NULL, '54d4e42c671eac2460f5e34a882bb64e0609a4a5ad8ffc4f327aaa02b6fc7f7a'),
  ('en.sahih', 13, 1, 1708, 'Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.', NULL, NULL, 'bc7c3a7d43f9ee0e6f874015168b7ba62fa376b7550a0e0640b616e38a72efc7'),
  ('en.sahih', 13, 2, 1709, 'It is Allah who erected the heavens without pillars that you [can] see; then He established Himself above the Throne and made subject the sun and the moon, each running [its course] for a specified term. He arranges [each] matter; He details the signs that you may, of the meeting with your Lord, be certain.', NULL, NULL, 'ad4d50b28d86ee8b6dacb1d036169814bc0f35176712af870c10c978ca378010'),
  ('en.sahih', 13, 3, 1710, 'And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought.', NULL, NULL, '1e98b0dccb70a1b9b85fd3f2118d056d553acd4c227d14645cc8bf795379bade'),
  ('en.sahih', 13, 4, 1711, 'And within the land are neighboring plots and gardens of grapevines and crops and palm trees, [growing] several from a root or otherwise, watered with one water; but We make some of them exceed others in [quality of] fruit. Indeed in that are signs for a people who reason.', NULL, NULL, '7d7bcda0f8db6b590e241ae1021ad4e0a1ab5282bd62144c9df35bd82ca4b3a9'),
  ('en.sahih', 13, 5, 1712, 'And if you are astonished, [O Muhammad] - then astonishing is their saying, "When we are dust, will we indeed be [brought] into a new creation?" Those are the ones who have disbelieved in their Lord, and those will have shackles upon their necks, and those are the companions of the Fire; they will abide therein eternally.', NULL, NULL, '80350a15d8182864d12e8c8ee95de472f7aeb4d5875a4a1cd8eb6fb688dfdf60'),
  ('en.sahih', 13, 6, 1713, 'They impatiently urge you to bring about evil before good, while there has already occurred before them similar punishments [to what they demand]. And indeed, your Lord is full of forgiveness for the people despite their wrongdoing, and indeed, your Lord is severe in penalty.', NULL, NULL, '34669951159ea491d4b65a267d7d3096ebd6084037561fbf11519262c842eb5a'),
  ('en.sahih', 13, 7, 1714, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" You are only a warner, and for every people is a guide.', NULL, NULL, '92bf04edf88c0e0cf9165ec832dd7e4133f3e03662e58ee221d72639e41c362a'),
  ('en.sahih', 13, 8, 1715, 'Allah knows what every female carries and what the wombs lose [prematurely] or exceed. And everything with Him is by due measure.', NULL, NULL, 'bef485e2280f126d0330dcf359970c99c11578ccc75c25be3327de95b8941acc'),
  ('en.sahih', 13, 9, 1716, '[He is] Knower of the unseen and the witnessed, the Grand, the Exalted.', NULL, NULL, '5a57baa25730ba3abe6f55902b24e36fe363de10844c4cf4dd834bff3f78d28a'),
  ('en.sahih', 13, 10, 1717, 'It is the same [to Him] concerning you whether one conceals [his] speech or one publicizes it and whether one is hidden by night or conspicuous [among others] by day.', NULL, NULL, '826f1e8b95b569516b4f9d6954f71c10c748b3db21c3920584aec6966d994377'),
  ('en.sahih', 13, 11, 1718, 'For each one are successive [angels] before and behind him who protect him by the decree of Allah. Indeed, Allah will not change the condition of a people until they change what is in themselves. And when Allah intends for a people ill, there is no repelling it. And there is not for them besides Him any patron.', NULL, NULL, 'fa05f6db99aabd7523ec84453b06f9ab77b01a536da2a7a92ed1762ef08e381c'),
  ('en.sahih', 13, 12, 1719, 'It is He who shows you lightening, [causing] fear and aspiration, and generates the heavy clouds.', NULL, NULL, 'f69d47731653b1028740c36a15891fa6d7c5f66d0c38f42fe246b4c8503491b2'),
  ('en.sahih', 13, 13, 1720, 'And the thunder exalts [Allah] with praise of Him - and the angels [as well] from fear of Him - and He sends thunderbolts and strikes therewith whom He wills while they dispute about Allah; and He is severe in assault.', NULL, NULL, 'c006c9736fd7647081c0be3a28cbfae0bbae654e47c4f0557408388ea17ffc3f'),
  ('en.sahih', 13, 14, 1721, 'To Him [alone] is the supplication of truth. And those they call upon besides Him do not respond to them with a thing, except as one who stretches his hands toward water [from afar, calling it] to reach his mouth, but it will not reach it [thus]. And the supplication of the disbelievers is not but in error [i.e. futility].', NULL, NULL, '619ba9295ee053fde96b6c0da2ddf65f3e3112516b2672ccdcb3fc26aefc34fd'),
  ('en.sahih', 13, 15, 1722, 'And to Allah prostrates whoever is within the heavens and the earth, willingly or by compulsion, and their shadows [as well] in the mornings and the afternoons.', NULL, NULL, '7644f459e34745ba0cf22ad96d0ff00792834e3dc5f2b2fde13b512bd7ca5158'),
  ('en.sahih', 13, 16, 1723, 'Say, "Who is Lord of the heavens and earth?" Say, "Allah." Say, "Have you then taken besides Him allies not possessing [even] for themselves any benefit or any harm?" Say, "Is the blind equivalent to the seeing? Or is darkness equivalent to light? Or have they attributed to Allah partners who created like His creation so that the creation [of each] seemed similar to them?" Say, "Allah is the Creator of all things, and He is the One, the Prevailing."', NULL, NULL, 'c94d7be9dcb4408a743e6aac23a25aa1bf02c779fbbf542e8c351ab2d88cb371'),
  ('en.sahih', 13, 17, 1724, 'He sends down from the sky, rain, and valleys flow according to their capacity, and the torrent carries a rising foam. And from that [ore] which they heat in the fire, desiring adornments and utensils, is a foam like it. Thus Allah presents [the example of] truth and falsehood. As for the foam, it vanishes, [being] cast off; but as for that which benefits the people, it remains on the earth. Thus does Allah present examples.', NULL, NULL, '86aa281f114bf9bcb6d673ed3f0ebf611c69aba3a78c8ca314360e76b61bb800'),
  ('en.sahih', 13, 18, 1725, 'For those who have responded to their Lord is the best [reward], but those who did not respond to Him - if they had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby. Those will have the worst account, and their refuge is Hell, and wretched is the resting place.', NULL, NULL, 'e81aff4c3fcc3c77dfa0e46f6c219e5137b0e411359a4115fe1fb5677dbc7bd2'),
  ('en.sahih', 13, 19, 1726, 'Then is he who knows that what has been revealed to you from your Lord is the truth like one who is blind? They will only be reminded who are people of understanding -', NULL, NULL, '5b1f99a1a78a4809bf759f4a2e2dce77ec165b356ea1ed9f928f303128204d70'),
  ('en.sahih', 13, 20, 1727, 'Those who fulfill the covenant of Allah and do not break the contract,', NULL, NULL, '3052b315ae43ad1f9e48e8a5776a12792983a3af34092d1abdb0631e4647b8c6'),
  ('en.sahih', 13, 21, 1728, 'And those who join that which Allah has ordered to be joined and fear their Lord and are afraid of the evil of [their] account,', NULL, NULL, '446e1989b374afe4a6481e9609290527f5fe2c46bbccc7b50027a3fe9dba66e6'),
  ('en.sahih', 13, 22, 1729, 'And those who are patient, seeking the countenance of their Lord, and establish prayer and spend from what We have provided for them secretly and publicly and prevent evil with good - those will have the good consequence of [this] home -', NULL, NULL, '9cedd2493aade8f8c53a7748cd0a86e93146f967b9d0ff8a41fdaa19c2a842e6'),
  ('en.sahih', 13, 23, 1730, 'Gardens of perpetual residence; they will enter them with whoever were righteous among their fathers, their spouses and their descendants. And the angels will enter upon them from every gate, [saying],', NULL, NULL, '3c1b76d3fa4871ceb978075a82f9297172ef224c5ba6103f928938dcb5ceede8'),
  ('en.sahih', 13, 24, 1731, '"Peace be upon you for what you patiently endured. And excellent is the final home."', NULL, NULL, 'd5e7d4b6aeed99e39a4f26567c3f30cdf115c8d8d7987d14bbe1258871ff10d8'),
  ('en.sahih', 13, 25, 1732, 'But those who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and spread corruption on earth - for them is the curse, and they will have the worst home.', NULL, NULL, 'ef138370ce6250c7729f6aec1231eab714e0dbfb573bb7f7c1d11ca0c82c9823'),
  ('en.sahih', 13, 26, 1733, 'Allah extends provision for whom He wills and restricts [it]. And they rejoice in the worldly life, while the worldly life is not, compared to the Hereafter, except [brief] enjoyment.', NULL, NULL, 'd4ee4607479301492a3f24381aa7750e83dd571dc23a13ac47ead4c4de663ac4'),
  ('en.sahih', 13, 27, 1734, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" Say, [O Muhammad], "Indeed, Allah leaves astray whom He wills and guides to Himself whoever turns back [to Him] -', NULL, NULL, '8526abf32eecf37ff1058d292f44c0647c5f5dc7026a1e555d386fe3f000adf7'),
  ('en.sahih', 13, 28, 1735, 'Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured."', NULL, NULL, '3c52c17457142d47c6a8f5531ad00db0037d264a66e0d77b09e116a5de789f1a'),
  ('en.sahih', 13, 29, 1736, 'Those who have believed and done righteous deeds - a good state is theirs and a good return.', NULL, NULL, 'cdce142df323dfb3ae330f347918cfce571dfaaba83155bb8a0c063a062f5e36'),
  ('en.sahih', 13, 30, 1737, 'Thus have We sent you to a community before which [other] communities have passed on so you might recite to them that which We revealed to you, while they disbelieve in the Most Merciful. Say, "He is my Lord; there is no deity except Him. Upon Him I rely, and to Him is my return."', NULL, NULL, '93708c93e132559611bb0beeb7fcc2006ae7c0d1252040725f552424bf14de35'),
  ('en.sahih', 13, 31, 1738, 'And if there was any qur''an by which the mountains would be removed or the earth would be broken apart or the dead would be made to speak, [it would be this Qur''an], but to Allah belongs the affair entirely. Then have those who believed not accepted that had Allah willed, He would have guided the people, all of them? And those who disbelieve do not cease to be struck, for what they have done, by calamity - or it will descend near their home - until there comes the promise of Allah. Indeed, Allah does not fail in [His] promise.', NULL, NULL, 'c9314ad87aa3a9c35ea7c2e686198c1012c1bc78b5ec8c755f8a822275ca07f2'),
  ('en.sahih', 13, 32, 1739, 'And already were [other] messengers ridiculed before you, and I extended the time of those who disbelieved; then I seized them, and how [terrible] was My penalty.', NULL, NULL, '19942b9b64759fa042781d3c7aa5335b06b4710b03524ea37f296488a2afa045'),
  ('en.sahih', 13, 33, 1740, 'Then is He who is a maintainer of every soul, [knowing] what it has earned, [like any other]? But to Allah they have attributed partners. Say, "Name them. Or do you inform Him of that which He knows not upon the earth or of what is apparent of speech?" Rather, their [own] plan has been made attractive to those who disbelieve, and they have been averted from the way. And whomever Allah leaves astray - there will be for him no guide.', NULL, NULL, 'cc1478ce348af9d9d4dd6450a47f09a435894bbc6ed33bd524fe997e3179f9a7'),
  ('en.sahih', 13, 34, 1741, 'For them will be punishment in the life of [this] world, and the punishment of the Hereafter is more severe. And they will not have from Allah any protector.', NULL, NULL, '4a21f9b87cb3b8ddf35ae05da514bfe37b51d3d0aef24496f8ba70180815d555'),
  ('en.sahih', 13, 35, 1742, 'The example of Paradise, which the righteous have been promised, is [that] beneath it rivers flow. Its fruit is lasting, and its shade. That is the consequence for the righteous, and the consequence for the disbelievers is the Fire.', NULL, NULL, '8a87d457a0fa283a9e30d06cdbb611c22c28d5c4849d80d37d9779c856a89b7a'),
  ('en.sahih', 13, 36, 1743, 'And [the believers among] those to whom We have given the [previous] Scripture rejoice at what has been revealed to you, [O Muhammad], but among the [opposing] factions are those who deny part of it. Say, "I have only been commanded to worship Allah and not associate [anything] with Him. To Him I invite, and to Him is my return."', NULL, NULL, 'c10663b17397ce6338a48c7f9916412499f013631ccd25b469864fcf2e0a2e73'),
  ('en.sahih', 13, 37, 1744, 'And thus We have revealed it as an Arabic legislation. And if you should follow their inclinations after what has come to you of knowledge, you would not have against Allah any ally or any protector.', NULL, NULL, 'e15b72ca80ec5bacf9928d13241123856c8dde1a65c68ded81f8e1577d1ab7dd'),
  ('en.sahih', 13, 38, 1745, 'And We have already sent messengers before you and assigned to them wives and descendants. And it was not for a messenger to come with a sign except by permission of Allah. For every term is a decree.', NULL, NULL, 'd17ec4461877d93849584460c71fb9c4b62720da940a239e2bb8fd16649820b9'),
  ('en.sahih', 13, 39, 1746, 'Allah eliminates what He wills or confirms, and with Him is the Mother of the Book.', NULL, NULL, '781ef11e48c9722c68021a265193c79e9bf364a4a7dd6168200aed0042008375'),
  ('en.sahih', 13, 40, 1747, 'And whether We show you part of what We promise them or take you in death, upon you is only the [duty of] notification, and upon Us is the account.', NULL, NULL, '09f7f52dfee384805e6d4a09764cc2abcbece5de799937f5a606b230903a4da8'),
  ('en.sahih', 13, 41, 1748, 'Have they not seen that We set upon the land, reducing it from its borders? And Allah decides; there is no adjuster of His decision. And He is swift in account.', NULL, NULL, '4fa79d9736166299a8c8031ebab71a4f52ff62dd6c0cd9b369f43ca8b042489d'),
  ('en.sahih', 13, 42, 1749, 'And those before them had plotted, but to Allah belongs the plan entirely. He knows what every soul earns, and the disbelievers will know for whom is the final home.', NULL, NULL, '4d6fd126b3fa71e1936075aa75d241e3b7c3ddf5b92aaa2eda554c0911875ac9'),
  ('en.sahih', 13, 43, 1750, 'And those who have disbelieved say, "You are not a messenger." Say, [O Muhammad], "Sufficient is Allah as Witness between me and you, and [the witness of] whoever has knowledge of the Scripture."', NULL, NULL, '80a39c90bbfdce6ca2a8d7237688677fc28c8adc3abc8d14a16ec91374e3a531'),
  ('en.sahih', 14, 1, 1751, 'Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -', NULL, NULL, '1088ec1cc753ff767419b43928e9b8351e68630f9cee4add495729f500bb14f4'),
  ('en.sahih', 14, 2, 1752, 'Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment', NULL, NULL, 'fc97dc0ac589465d6142e0f19582a351ce36cd62674d9e88af2ffa471f8f88b2'),
  ('en.sahih', 14, 3, 1753, 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error.', NULL, NULL, 'db71a465f95c86b37caa8fe8b31a41b1368519d1e34ff06728e87667519a692f'),
  ('en.sahih', 14, 4, 1754, 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.', NULL, NULL, 'b3062cfb5c9fc6e37e09fbcdb279c8be8fa47b75f1704cf1b4f1d6d4d8fdf075'),
  ('en.sahih', 14, 5, 1755, 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allah." Indeed in that are signs for everyone patient and grateful.', NULL, NULL, '03eac293afcbd6d61c2f6626c17e74b0d94c853727785719f957b4bd86d5b971'),
  ('en.sahih', 14, 6, 1756, 'And [recall, O Children of Israel], when Moses said to His people, "Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.', NULL, NULL, '7ab5126656b4aa30abb4ff64004023a340b943b5416ce364c496dc9755cf3f04'),
  ('en.sahih', 14, 7, 1757, 'And [remember] when your Lord proclaimed, ''If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.'' "', NULL, NULL, '5a5a7019bb183c552dbbfcdcddc04400d618a9f8e0f774f725d8641216a459b0'),
  ('en.sahih', 14, 8, 1758, 'And Moses said, "If you should disbelieve, you and whoever is on the earth entirely - indeed, Allah is Free of need and Praiseworthy."', NULL, NULL, '9f60bc5888ef1c80f2569b3e4fad2f182a5a93ad714d9bccc4ca23fd0529d207'),
  ('en.sahih', 14, 9, 1759, 'Has there not reached you the news of those before you - the people of Noah and ''Aad and Thamud and those after them? No one knows them but Allah. Their messengers brought them clear proofs, but they returned their hands to their mouths and said, "Indeed, we disbelieve in that with which you have been sent, and indeed we are, about that to which you invite us, in disquieting doubt."', NULL, NULL, '198e0880eb0cae5eed257c78d2e04982beb84c7ff262fafbf96c465c5706774d'),
  ('en.sahih', 14, 10, 1760, 'Their messengers said, "Can there be doubt about Allah, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays your death for a specified term." They said, "You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority."', NULL, NULL, '66d89db237ad0849593ae8c4d434c27d77ab4296c17081fdf030490a4675537e'),
  ('en.sahih', 14, 11, 1761, 'Their messengers said to them, "We are only men like you, but Allah confers favor upon whom He wills of His servants. It has never been for us to bring you evidence except by permission of Allah. And upon Allah let the believers rely.', NULL, NULL, 'd2bab921f390056500a9c2c44e75736619a10ff262af2d96ecd42555a97ecdc5'),
  ('en.sahih', 14, 12, 1762, 'And why should we not rely upon Allah while He has guided us to our [good] ways. And we will surely be patient against whatever harm you should cause us. And upon Allah let those who would rely [indeed] rely."', NULL, NULL, 'ef710cb4fc9d9b22fe3c264b0d27fa2a473c3b73abf9abed86a37dd1e75e0cba'),
  ('en.sahih', 14, 13, 1763, 'And those who disbelieved said to their messengers, "We will surely drive you out of our land, or you must return to our religion." So their Lord inspired to them, "We will surely destroy the wrongdoers.', NULL, NULL, 'fdca22f2f65d69f9d8508d333d41d10b6a188cbeb2852908b296047ed287b7d8'),
  ('en.sahih', 14, 14, 1764, 'And We will surely cause you to dwell in the land after them. That is for he who fears My position and fears My threat."', NULL, NULL, 'b3082e5ca98b99f9b57d26bab5ab9ddfe8810a9d23a7b8837dfaaf86d89baba0'),
  ('en.sahih', 14, 15, 1765, 'And they requested victory from Allah, and disappointed, [therefore], was every obstinate tyrant.', NULL, NULL, '781468e0a6535f2456b93d5e56b411b83afb0be25f97f6c02f8b9feb08b9768a'),
  ('en.sahih', 14, 16, 1766, 'Before him is Hell, and he will be given a drink of purulent water.', NULL, NULL, 'a089ea67eb3659b818b9e39e1ccd417531bcea2e47c0614685af32fd1d97ec15'),
  ('en.sahih', 14, 17, 1767, 'He will gulp it but will hardly [be able to] swallow it. And death will come to him from everywhere, but he is not to die. And before him is a massive punishment.', NULL, NULL, '39b7a41edff879e63bcd1cc9058c1729bf24fb683541b2e733360fa09794463a'),
  ('en.sahih', 14, 18, 1768, 'The example of those who disbelieve in their Lord is [that] their deeds are like ashes which the wind blows forcefully on a stormy day; they are unable [to keep] from what they earned a [single] thing. That is what is extreme error.', NULL, NULL, 'ccbe54877f46f340282e485e825e6025cddb96bae9b2e6c78e98f78527989845'),
  ('en.sahih', 14, 19, 1769, 'Have you not seen that Allah created the heavens and the earth in truth? If He wills, He can do away with you and produce a new creation.', NULL, NULL, 'd1c3ad0b6c680a96cd2a5e56950a631bfe5387d2442f15183950927cbca605af'),
  ('en.sahih', 14, 20, 1770, 'And that is not difficult for Allah.', NULL, NULL, '69e255774f510dd1edb157d0b9aad881ce26fb38e47481f36b3a04c1e630660c'),
  ('en.sahih', 14, 21, 1771, 'And they will come out [for judgement] before Allah all together, and the weak will say to those who were arrogant, "Indeed, we were your followers, so can you avail us anything against the punishment of Allah?" They will say, "If Allah had guided us, we would have guided you. It is all the same for us whether we show intolerance or are patient: there is for us no place of escape."', NULL, NULL, 'b7c5a859652d16c07000e2b0bec870c8ca899f8647af5ec1a4343f2afba3171e'),
  ('en.sahih', 14, 22, 1772, 'And Satan will say when the matter has been concluded, "Indeed, Allah had promised you the promise of truth. And I promised you, but I betrayed you. But I had no authority over you except that I invited you, and you responded to me. So do not blame me; but blame yourselves. I cannot be called to your aid, nor can you be called to my aid. Indeed, I deny your association of me [with Allah] before. Indeed, for the wrongdoers is a painful punishment."', NULL, NULL, '9e928f671030b3b29bbb8dfca28905b8f215fa6a4b3df1542240a7b47a7558c7'),
  ('en.sahih', 14, 23, 1773, 'And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, "Peace!"', NULL, NULL, '87f4145d47c3e07ada336c350b597d31749619a999c089929affaa38ba487856'),
  ('en.sahih', 14, 24, 1774, 'Have you not considered how Allah presents an example, [making] a good word like a good tree, whose root is firmly fixed and its branches [high] in the sky?', NULL, NULL, 'c4e505c897ea5378e326c86f48bd1e2f9e6a3e70c08b4f2bb880e59b00e53080'),
  ('en.sahih', 14, 25, 1775, 'It produces its fruit all the time, by permission of its Lord. And Allah presents examples for the people that perhaps they will be reminded.', NULL, NULL, '561ec41c9ae736c4ec8d3c5491bd2bdc2668cf1594a7c365997851b4f3d01d39'),
  ('en.sahih', 14, 26, 1776, 'And the example of a bad word is like a bad tree, uprooted from the surface of the earth, not having any stability.', NULL, NULL, '7ac1edd65428698238d0a1070663effeb12206e154f4e82334367461f43584f9'),
  ('en.sahih', 14, 27, 1777, 'Allah keeps firm those who believe, with the firm word, in worldly life and in the Hereafter. And Allah sends astray the wrongdoers. And Allah does what He wills.', NULL, NULL, '9898f46e494486c42f932dfb7d25c58c2d8877e34ca9e4742888a699a0385f03'),
  ('en.sahih', 14, 28, 1778, 'Have you not considered those who exchanged the favor of Allah for disbelief and settled their people [in] the home of ruin?', NULL, NULL, '415514e771dae9c20cdba061755e2b0ef3d1c0db6ff4daf4de1e0ae6b3295394'),
  ('en.sahih', 14, 29, 1779, '[It is] Hell, which they will [enter to] burn, and wretched is the settlement.', NULL, NULL, 'd4484333efc75d962aa790a81fd6b07e2d2fdacb52eb391f6d7aca9502b077b0'),
  ('en.sahih', 14, 30, 1780, 'And they have attributed to Allah equals to mislead [people] from His way. Say, "Enjoy yourselves, for indeed, your destination is the Fire."', NULL, NULL, '82a5293a4a5eeea8c0c97fd79036e8211a1028ab1c9ca5c78fe7c506d624acdb'),
  ('en.sahih', 14, 31, 1781, '[O Muhammad], tell My servants who have believed to establish prayer and spend from what We have provided them, secretly and publicly, before a Day comes in which there will be no exchange, nor any friendships.', NULL, NULL, 'e012eb6188d0d3b544930ee108b1b2a80d69b6377ba6658266dafe891d65b777'),
  ('en.sahih', 14, 32, 1782, 'It is Allah who created the heavens and the earth and sent down rain from the sky and produced thereby some fruits as provision for you and subjected for you the ships to sail through the sea by His command and subjected for you the rivers.', NULL, NULL, '2b4b70761434adedc63bb4017058b8a6c68e8506dcb814854e6a0905829c49c8'),
  ('en.sahih', 14, 33, 1783, 'And He subjected for you the sun and the moon, continuous [in orbit], and subjected for you the night and the day.', NULL, NULL, '83c4ca1cf2a070bc3da059ee67d2df56b420c634225109925a3d731f5fe6b5b3'),
  ('en.sahih', 14, 34, 1784, 'And He gave you from all you asked of Him. And if you should count the favor of Allah, you could not enumerate them. Indeed, mankind is [generally] most unjust and ungrateful.', NULL, NULL, '4bed53d30a204e53e8cc778681a6edbccce10bd7c87efa3e838b884c6c7844b9'),
  ('en.sahih', 14, 35, 1785, 'And [mention, O Muhammad], when Abraham said, "My Lord, make this city [Makkah] secure and keep me and my sons away from worshipping idols.', NULL, NULL, 'f44f9006fd1e2b4988da81aac374f036dc611bd023382942790ec98b4aa09268'),
  ('en.sahih', 14, 36, 1786, 'My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.', NULL, NULL, '20215f40a2f263f6d66f2f7f374ced7e6b514c088908ed5c28595136e8de1044'),
  ('en.sahih', 14, 37, 1787, 'Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful.', NULL, NULL, '012edbdd427420a62b06e60b8085e49130a2352c04974c6e4bf407d2a56fcbcd'),
  ('en.sahih', 14, 38, 1788, 'Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven.', NULL, NULL, 'd22479a68e0ed46168bb4a3f32a14fdafc87204cb07a10f82bc0779b2b572aae'),
  ('en.sahih', 14, 39, 1789, 'Praise to Allah, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication.', NULL, NULL, 'cc3131f277dc6b174001ccc9bb198623cf7bc74684eb47a2c92dacb54b652687'),
  ('en.sahih', 14, 40, 1790, 'My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.', NULL, NULL, 'b89a8f4246e36d43ee5ef1a33b257c556479367361d6c93c3c6e290df6323339'),
  ('en.sahih', 14, 41, 1791, 'Our Lord, forgive me and my parents and the believers the Day the account is established."', NULL, NULL, 'ae3696d02f90bf0ec2f23045ccd223894ae8ec0a07a0102b2de48257f887e413'),
  ('en.sahih', 14, 42, 1792, 'And never think that Allah is unaware of what the wrongdoers do. He only delays them for a Day when eyes will stare [in horror].', NULL, NULL, '84e8d324171e05e4765fc4331cc0a2b715790bb3ede33674a37bc7bbe5f10d58'),
  ('en.sahih', 14, 43, 1793, 'Racing ahead, their heads raised up, their glance does not come back to them, and their hearts are void.', NULL, NULL, 'c9e74ba50736006f34352c5a9772ef5604c73e1841c3be62cc554ffd1b040fff'),
  ('en.sahih', 14, 44, 1794, 'And, [O Muhammad], warn the people of a Day when the punishment will come to them and those who did wrong will say, "Our Lord, delay us for a short term; we will answer Your call and follow the messengers." [But it will be said], "Had you not sworn, before, that for you there would be no cessation?', NULL, NULL, '8be73712d56af705c911a478d9d11eeba6c4d48e0fda0920e737e0e8b5dfc463'),
  ('en.sahih', 14, 45, 1795, 'And you lived among the dwellings of those who wronged themselves, and it had become clear to you how We dealt with them. And We presented for you [many] examples."', NULL, NULL, 'bca255898644bb75e5e3f97e84f3c61718649997e9fc6c411bd11c8e5792147f'),
  ('en.sahih', 14, 46, 1796, 'And they had planned their plan, but with Allah is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains.', NULL, NULL, '69facd49a4afa9601581ba41fd7ae3d8470f5e474a95d611c80dbb35c89b3cd4'),
  ('en.sahih', 14, 47, 1797, 'So never think that Allah will fail in His promise to His messengers. Indeed, Allah is Exalted in Might and Owner of Retribution.', NULL, NULL, 'c0ec836fb50f168203fffa701c341cec1443c27761add3cbb92709bcd9a72666'),
  ('en.sahih', 14, 48, 1798, '[It will be] on the Day the earth will be replaced by another earth, and the heavens [as well], and all creatures will come out before Allah, the One, the Prevailing.', NULL, NULL, '4f135cc3105436a9f1fc8a7fff7bec997a205c2bdad2ee6b3a537fd6df3814cf'),
  ('en.sahih', 14, 49, 1799, 'And you will see the criminals that Day bound together in shackles,', NULL, NULL, '88ebedeeb0f406bf41ee1aae3860e6044396080473cc67cdbda69976f6b66e4f'),
  ('en.sahih', 14, 50, 1800, 'Their garments of liquid pitch and their faces covered by the Fire.', NULL, NULL, 'b54fa867615b02328876daa57c2a814a36fe48c573702ade4c3efa0567c1359e')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 14, 51, 1801, 'So that Allah will recompense every soul for what it earned. Indeed, Allah is swift in account.', NULL, NULL, '1d5503f9bd64ad315671759680c3c6d000410880f15806f4e43d1f7e2fb0b32e'),
  ('en.sahih', 14, 52, 1802, 'This [Qur''an] is notification for the people that they may be warned thereby and that they may know that He is but one God and that those of understanding will be reminded.', NULL, NULL, '441ad14c7246778d59c4e6440f95f0c350c9e9190e120752d5e8d7695ab8e914'),
  ('en.sahih', 15, 1, 1803, 'Alif, Lam, Ra. These are the verses of the Book and a clear Qur''an.', NULL, NULL, 'f1621a0c704c45c38709fb07c178dfd5ff7c44d66cc14193c5e7b604aa7488e1'),
  ('en.sahih', 15, 2, 1804, 'Perhaps those who disbelieve will wish that they had been Muslims.', NULL, NULL, '3ac810dc8392e3d7aa28d8c2014eb737519c6f6c879033e633f992ce37dacbaf'),
  ('en.sahih', 15, 3, 1805, 'Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know.', NULL, NULL, '68249d9199a3e601b91f5af177519480266b9ccc38f4c0503479a2de278bddb6'),
  ('en.sahih', 15, 4, 1806, 'And We did not destroy any city but that for it was a known decree.', NULL, NULL, '0c009dcfb064162806aaa96b7db8918fd1c87f9316dc3d84b56d7c079d85af6f'),
  ('en.sahih', 15, 5, 1807, 'No nation will precede its term, nor will they remain thereafter.', NULL, NULL, 'a36342f6d1a2543c2ff65d35dea74718376943a5b0dad0a016e2fb3c89d07480'),
  ('en.sahih', 15, 6, 1808, 'And they say, "O you upon whom the message has been sent down, indeed you are mad.', NULL, NULL, '7d791ffcc0d90cd8c05d4b4776cf5beb1995cff36b6b1c7340d740b38abeff66'),
  ('en.sahih', 15, 7, 1809, 'Why do you not bring us the angels, if you should be among the truthful?"', NULL, NULL, '1d05e36b085da9af5b653fab2566c3109a203d269fe8a6a2059ebd63da6b4d6c'),
  ('en.sahih', 15, 8, 1810, 'We do not send down the angels except with truth; and the disbelievers would not then be reprieved.', NULL, NULL, 'a3021fb90ece137da198140eb60c2c00cbb58ab1760ba15de167f5fbce4205e0'),
  ('en.sahih', 15, 9, 1811, 'Indeed, it is We who sent down the Qur''an and indeed, We will be its guardian.', NULL, NULL, 'a0ffbc81144f7dc754adcc6f47c684517d2f93916b02aca91d5801e889123139'),
  ('en.sahih', 15, 10, 1812, 'And We had certainly sent [messengers] before you, [O Muhammad], among the sects of the former peoples.', NULL, NULL, '4780d5f2b5cff2e1068895fe49e220b4ac7eb62024760e342aaa26411af9d64e'),
  ('en.sahih', 15, 11, 1813, 'And no messenger would come to them except that they ridiculed him.', NULL, NULL, '31abe48bd804a5dac9118c1f29bace9364b63c5a9e6827393ab877318a0fdbfc'),
  ('en.sahih', 15, 12, 1814, 'Thus do We insert denial into the hearts of the criminals.', NULL, NULL, '1dc24de525f10005ab3b266f79bdf2dce58dfcaa32b5c4492c6090b0361595aa'),
  ('en.sahih', 15, 13, 1815, 'They will not believe in it, while there has already occurred the precedent of the former peoples.', NULL, NULL, 'bb6f20285af4689c4171b4f6371225279bd1a81b7816c0f140671b1abd8973ba'),
  ('en.sahih', 15, 14, 1816, 'And [even] if We opened to them a gate from the heaven and they continued therein to ascend,', NULL, NULL, '42cfee24699a462d831227ff13276b309fbe0e95acce36164b93187a24760b26'),
  ('en.sahih', 15, 15, 1817, 'They would say, "Our eyes have only been dazzled. Rather, we are a people affected by magic."', NULL, NULL, '81304998a144a3161fc55d4c3e7565b849c5e528a0e65c0c09a8bd710622e81f'),
  ('en.sahih', 15, 16, 1818, 'And We have placed within the heaven great stars and have beautified it for the observers.', NULL, NULL, 'b343f2bf797becf28bb659c282df6803c7dce11178d06e5cdd72308251e5f68e'),
  ('en.sahih', 15, 17, 1819, 'And We have protected it from every devil expelled [from the mercy of Allah]', NULL, NULL, 'a73f31d923f60cc077577266a868a178cdce6ac24d235891703377af83422601'),
  ('en.sahih', 15, 18, 1820, 'Except one who steals a hearing and is pursued by a clear burning flame.', NULL, NULL, '2410e200c6adcf7e97b6c8564903f0b0281747b14490651b2f4156fb0821c9c9'),
  ('en.sahih', 15, 19, 1821, 'And the earth - We have spread it and cast therein firmly set mountains and caused to grow therein [something] of every well-balanced thing.', NULL, NULL, '6932f40a606d23147c0b5024d6de9e96ff1860c40faec5caf3b70f88f4d72c8f'),
  ('en.sahih', 15, 20, 1822, 'And We have made for you therein means of living and [for] those for whom you are not providers.', NULL, NULL, '9428d118892d5fa68abd58583c2200247eda30b497217f8658eb809d11507a07'),
  ('en.sahih', 15, 21, 1823, 'And there is not a thing but that with Us are its depositories, and We do not send it down except according to a known measure.', NULL, NULL, 'da2ea036888ded2915cdf80d491c43381675af67ed87fcde8e708006f13a4fb7'),
  ('en.sahih', 15, 22, 1824, 'And We have sent the fertilizing winds and sent down water from the sky and given you drink from it. And you are not its retainers.', NULL, NULL, '4423d77e09cef090bb70fd844fa3b23a19f8974a85e3294b3b71018231c0b5ed'),
  ('en.sahih', 15, 23, 1825, 'And indeed, it is We who give life and cause death, and We are the Inheritor.', NULL, NULL, '6cbc7ddc1e366601a0edf8d38c5efd29eebacd9f25dc24d300b96f4c264fb8fc'),
  ('en.sahih', 15, 24, 1826, 'And We have already known the preceding [generations] among you, and We have already known the later [ones to come].', NULL, NULL, '6ab2dee9c3a20207a8d98fb5e288b2e30d3dc362300967ddf408ab9003972b55'),
  ('en.sahih', 15, 25, 1827, 'And indeed, your Lord will gather them; indeed, He is Wise and Knowing.', NULL, NULL, '1365c94ef3e2e297269e3ed0f72cd4a5996f91b5b02260a6032ad0e4055bcbbf'),
  ('en.sahih', 15, 26, 1828, 'And We did certainly create man out of clay from an altered black mud.', NULL, NULL, '993c0e8fee2c615bcc0b61ecb3db7dbc8ea46211f2e43fcfdaf366c56415b170'),
  ('en.sahih', 15, 27, 1829, 'And the jinn We created before from scorching fire.', NULL, NULL, '37fdf2f6cf6f6d22175f7fc1e6ebdb5f6c87989a15deb7a614f7f6ef457e2303'),
  ('en.sahih', 15, 28, 1830, 'And [mention, O Muhammad], when your Lord said to the angels, "I will create a human being out of clay from an altered black mud.', NULL, NULL, '7801a9a2145c8eab2a5d6faf8b50d97fa5bf2983cc8fcd6ee7164ab0291b0bf9'),
  ('en.sahih', 15, 29, 1831, 'And when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', NULL, NULL, 'a057581cdbde5a17e70c7a066a3e45ba3cad0b8e60124ccd517e56e88cc30c3c'),
  ('en.sahih', 15, 30, 1832, 'So the angels prostrated - all of them entirely,', NULL, NULL, 'c0e0b81227298dd645e22e9199a8e2a38d9a43980c7026001c0dbfc33919359e'),
  ('en.sahih', 15, 31, 1833, 'Except Iblees, he refused to be with those who prostrated.', NULL, NULL, 'eac9e902dddf17aabcf745378d826141d2bd25a60935b43b29563791823af816'),
  ('en.sahih', 15, 32, 1834, '[Allah] said, O Iblees, what is [the matter] with you that you are not with those who prostrate?"', NULL, NULL, 'b48e0555503868c0b57cdd0dbdf0f98e560cdde81dd865e80127b0c7e9817a0b'),
  ('en.sahih', 15, 33, 1835, 'He said, "Never would I prostrate to a human whom You created out of clay from an altered black mud."', NULL, NULL, '0df25be90b9bf0b3a21403a2036530e60683aeca868c9db1ef0294b88173442e'),
  ('en.sahih', 15, 34, 1836, '[Allah] said, "Then get out of it, for indeed, you are expelled.', NULL, NULL, '42d6c8169aaa8eec80afd9cf266689d41afab02e30ebd442e7e469cdce838dfa'),
  ('en.sahih', 15, 35, 1837, 'And indeed, upon you is the curse until the Day of Recompense."', NULL, NULL, '8d64301b332387eb801fd658fc754af236282a4c477783fb6ec8e431c651be25'),
  ('en.sahih', 15, 36, 1838, 'He said, "My Lord, then reprieve me until the Day they are resurrected."', NULL, NULL, 'e70cd5c25cabaa6ab26287180416d0aa62ea8435768c53f59259531827dfcc02'),
  ('en.sahih', 15, 37, 1839, '[Allah] said, "So indeed, you are of those reprieved', NULL, NULL, 'f131cae6d883e68d89f3dabb05adc2c8f790c568ad66d9e0df3a98ae6a64e398'),
  ('en.sahih', 15, 38, 1840, 'Until the Day of the time well-known."', NULL, NULL, '37ff67a273925e0c6c477e6bb04b9b6d920147c26c501b4d55e83785a98c18f0'),
  ('en.sahih', 15, 39, 1841, '[Iblees] said, "My Lord, because You have put me in error, I will surely make [disobedience] attractive to them on earth, and I will mislead them all', NULL, NULL, '213cb44a5478969f25962ee3981b776674cbdd143ac6a94c7ed6161f935cb833'),
  ('en.sahih', 15, 40, 1842, 'Except, among them, Your chosen servants."', NULL, NULL, 'e415bfc577fdb823d643335ed26d99205a43998813c84868200bc1e0c6032291'),
  ('en.sahih', 15, 41, 1843, '[Allah] said, "This is a path [of return] to Me [that is] straight.', NULL, NULL, '08fa15079b10c3b4da93aa19428e438da04551dc6326a9a2e12ac61af85c757c'),
  ('en.sahih', 15, 42, 1844, 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.', NULL, NULL, '8c4b7ef6f30c4c3612164e991bc41a72e77529d6ff307da7edfedc21e6536a7d'),
  ('en.sahih', 15, 43, 1845, 'And indeed, Hell is the promised place for them all.', NULL, NULL, 'd70fafe2432f68c1c2d8f2dcc15b1cfda2d83f18e6f51d0df03e46dc6ccb9de3'),
  ('en.sahih', 15, 44, 1846, 'It has seven gates; for every gate is of them a portion designated."', NULL, NULL, '0815d61601ef4731577fc13081951aa0e75e0e997d2b9abd09dd566cb5e21bda'),
  ('en.sahih', 15, 45, 1847, 'Indeed, the righteous will be within gardens and springs.', NULL, NULL, '02c5468751c98b50d711b4fed3bec310e41eb7a5a696176fba99f97183034016'),
  ('en.sahih', 15, 46, 1848, '[Having been told], "Enter it in peace, safe [and secure]."', NULL, NULL, 'd3f16f0d5d75cf1c07ab928cc40a9413c39cf9abc8be162d6a2c493e490f5c20'),
  ('en.sahih', 15, 47, 1849, 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.', NULL, NULL, '5a534ab517a5fe30525aa73ae7380f190c83e441b54593f1339a82d7a17d75b9'),
  ('en.sahih', 15, 48, 1850, 'No fatigue will touch them therein, nor from it will they [ever] be removed.', NULL, NULL, 'a8851080888e7521c622ef021be3ec59e72ad4e594af8854a90a8f2afa3b72ed'),
  ('en.sahih', 15, 49, 1851, '[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.', NULL, NULL, '66daa8931ca2059c2f17235eac8010dbb28bcad58f83b649f033137a539a3e9d'),
  ('en.sahih', 15, 50, 1852, 'And that it is My punishment which is the painful punishment.', NULL, NULL, 'e9194e65c4b6fa72a1a7bc4d42b55ae1df98b0ace944b240a193a86b893d9845'),
  ('en.sahih', 15, 51, 1853, 'And inform them about the guests of Abraham,', NULL, NULL, 'f734e4eaed88486489b6c677a9592abcce71556e480b8e44fcbde3960049e80f'),
  ('en.sahih', 15, 52, 1854, 'When they entered upon him and said, "Peace." [Abraham] said, "Indeed, we are fearful of you."', NULL, NULL, 'bcbe3b6c84442ab6a20b1409c6cf90bba27e44cfceaf3b4ba45974282d72ecbe'),
  ('en.sahih', 15, 53, 1855, '[The angels] said, "Fear not. Indeed, we give you good tidings of a learned boy."', NULL, NULL, 'd3044a757f258c937be8f1807ad7bfc13f33b8dcaaa634d6b6e52dc7cf62cbff'),
  ('en.sahih', 15, 54, 1856, 'He said, "Have you given me good tidings although old age has come upon me? Then of what [wonder] do you inform?"', NULL, NULL, '65537b5ebe310db529e41050d06673092998c5448107a25bf9a095d7a7ec9599'),
  ('en.sahih', 15, 55, 1857, 'They said, "We have given you good tidings in truth, so do not be of the despairing."', NULL, NULL, 'bdb2cb0ccdcca2d742fbe110aa22a0bf770c4695f4034d4f02e0aa345b2b5a48'),
  ('en.sahih', 15, 56, 1858, 'He said, "And who despairs of the mercy of his Lord except for those astray?"', NULL, NULL, '8032b52cc983a569e9b95a1a8f271614c0f6cd8ecfe5b68fb6972eddaa902a95'),
  ('en.sahih', 15, 57, 1859, '[Abraham] said, "Then what is your business [here], O messengers?"', NULL, NULL, '021702240c9847db5a14b94bdcdf7e75ed2c4ee6110095c17d8b77feb544fd89'),
  ('en.sahih', 15, 58, 1860, 'They said, "Indeed, we have been sent to a people of criminals,', NULL, NULL, '1e6194dd3658362a02cb83330c495fa00528e5798b11ebeebebb6bcf53d294a1'),
  ('en.sahih', 15, 59, 1861, 'Except the family of Lot; indeed, we will save them all', NULL, NULL, '2b585b5180d1ccec10f9aefe55c3a8ee6ca592a4851cf0e4fd83c1c0115327bc'),
  ('en.sahih', 15, 60, 1862, 'Except his wife." Allah decreed that she is of those who remain behind.', NULL, NULL, 'cfffb01c28420247899eba34f421394e56ca44336697a71b61f0a49c880f2ec1'),
  ('en.sahih', 15, 61, 1863, 'And when the messengers came to the family of Lot,', NULL, NULL, '080bb55fdc995b59c9c984866b4d6760cd7ce9f0a021aacbb9a8b871653f6e87'),
  ('en.sahih', 15, 62, 1864, 'He said, "Indeed, you are people unknown."', NULL, NULL, '42576040c47c553a8032286885f868d7c9b4f4d967ab2304badb911c5931723b'),
  ('en.sahih', 15, 63, 1865, 'They said, "But we have come to you with that about which they were disputing,', NULL, NULL, '63901f07a53b0594b2e7ea621780b882ca86222af05e7c799c18c376a4a3f121'),
  ('en.sahih', 15, 64, 1866, 'And we have come to you with truth, and indeed, we are truthful.', NULL, NULL, '6b4b5cafeea068a6c0c2e98a333dbffe331fe97e49ffce00deb263ab9e995191'),
  ('en.sahih', 15, 65, 1867, 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."', NULL, NULL, '9b028aff912323d46c2297da59015b9c8d07a163def833e039b2e47665b45bce'),
  ('en.sahih', 15, 66, 1868, 'And We conveyed to him [the decree] of that matter: that those [sinners] would be eliminated by early morning.', NULL, NULL, '2d677f6e121f54616eb324acbf8d1495b97341f12f0701cb3e76caa701a84e50'),
  ('en.sahih', 15, 67, 1869, 'And the people of the city came rejoicing.', NULL, NULL, '405fa9966d3f979bde4edbd24a4179c3575a764b459c72182feadae0b22dbf15'),
  ('en.sahih', 15, 68, 1870, '[Lot] said, "Indeed, these are my guests, so do not shame me.', NULL, NULL, '0a2de687ca8fce846f888d8b0950e85de5bf91d50858aa737132d6e6e8e7f8dd'),
  ('en.sahih', 15, 69, 1871, 'And fear Allah and do not disgrace me."', NULL, NULL, '5a2bade0937dcc2c0ddc9a668aa789a7f82b039c99f28723b6a15b080c4ac0b1'),
  ('en.sahih', 15, 70, 1872, 'They said, "Have we not forbidden you from [protecting] people?"', NULL, NULL, '40e19ede506b74f4d8cad2ecf0f9b6904dbb03af1c8d883b29260438125710f0'),
  ('en.sahih', 15, 71, 1873, '[Lot] said, "These are my daughters - if you would be doers [of lawful marriage]."', NULL, NULL, 'fd0335639b3519f31729aba5f1b9d02c31cc7c4df43a0e7bca4985516fc105da'),
  ('en.sahih', 15, 72, 1874, 'By your life, [O Muhammad], indeed they were, in their intoxication, wandering blindly.', NULL, NULL, 'e2b2f90a0dbfd5e3e7492bdc28c3fdd12b390af8439735ded4e6b5bfa391a84a'),
  ('en.sahih', 15, 73, 1875, 'So the shriek seized them at sunrise.', NULL, NULL, 'a80e70dfbd88765eeed97cb6f2d5503261c350a7f8c3dc037c132a17267d0cab'),
  ('en.sahih', 15, 74, 1876, 'And We made the highest part [of the city] its lowest and rained upon them stones of hard clay.', NULL, NULL, '3d9596c5b6c548441e585a5a7f3814ad5240b1cbbcad70bba06f50cc3e892f3b'),
  ('en.sahih', 15, 75, 1877, 'Indeed in that are signs for those who discern.', NULL, NULL, 'ead5325c5ea30e1f3545104414f2d18cc1ec73aa6979af84902d8989ac7ee81b'),
  ('en.sahih', 15, 76, 1878, 'And indeed, those cities are [situated] on an established road.', NULL, NULL, '27d4a26e04eb22fd151940cc7b94feb4404effda244446d740afd6f3085ebe06'),
  ('en.sahih', 15, 77, 1879, 'Indeed in that is a sign for the believers.', NULL, NULL, '11bc2b196b6101d4a0426885812f30022f10dd0a23b702ecae970eb6e182f5fc'),
  ('en.sahih', 15, 78, 1880, 'And the companions of the thicket were [also] wrongdoers.', NULL, NULL, '92e7c2a2a5970423a18e5a79bb09de97a908409c6ea6a2f61e087dd1d8db5006'),
  ('en.sahih', 15, 79, 1881, 'So We took retribution from them, and indeed, both [cities] are on a clear highway.', NULL, NULL, 'e17c6e75dca6f28aa2ce13d36d6915aee828b4439a57a7e7000bee4355a8f18f'),
  ('en.sahih', 15, 80, 1882, 'And certainly did the companions of Thamud deny the messengers.', NULL, NULL, '08a2d9ace2827f89da3f565bc59681530ea56e2e3c2618c646154930f3d050e5'),
  ('en.sahih', 15, 81, 1883, 'And We gave them Our signs, but from them they were turning away.', NULL, NULL, '00f507a30318d8af0b6e89bf580d21dc64e9cc88f621dcce70748f2c86bb5098'),
  ('en.sahih', 15, 82, 1884, 'And they used to carve from the mountains, houses, feeling secure.', NULL, NULL, '34f2aad1446f8e2e4e15483d60165a9940e6c891a31b6537f4fe1a9ab8c69caf'),
  ('en.sahih', 15, 83, 1885, 'But the shriek seized them at early morning.', NULL, NULL, '65d266120d47a3df73eba0c6d9687de1ec0e16fa882721f3750bd887c7329280'),
  ('en.sahih', 15, 84, 1886, 'So nothing availed them [from] what they used to earn.', NULL, NULL, 'f9cb86242c0e8cf9683724360801a573755ca0232fbe26ef8b996e6336ba9337'),
  ('en.sahih', 15, 85, 1887, 'And We have not created the heavens and earth and that between them except in truth. And indeed, the Hour is coming; so forgive with gracious forgiveness.', NULL, NULL, '8d5ffc5b7f91fa02e5b9d13e3a09b4e1943562cbfa954bb5772e9bd8bf7e0100'),
  ('en.sahih', 15, 86, 1888, 'Indeed, your Lord - He is the Knowing Creator.', NULL, NULL, 'a264c1c3a26eca0d1ebaf8991fc36786f30cbaef5c094090b99f7ee35e1f42b4'),
  ('en.sahih', 15, 87, 1889, 'And We have certainly given you, [O Muhammad], seven of the often repeated [verses] and the great Qur''an.', NULL, NULL, '39d458b2ad14b939a26e6a6969a234bd601d97bc1415cea81860aa3b62fc9d50'),
  ('en.sahih', 15, 88, 1890, 'Do not extend your eyes toward that by which We have given enjoyment to [certain] categories of the disbelievers, and do not grieve over them. And lower your wing to the believers', NULL, NULL, 'd6209f9610f8261ddf022b95c983fa5e9542f57b074860e2e0856a542b602913'),
  ('en.sahih', 15, 89, 1891, 'And say, "Indeed, I am the clear warner" -', NULL, NULL, '9a67426caf7b322a9b96aa7a4a86733a7b799b8aec0d288405a426affb868c46'),
  ('en.sahih', 15, 90, 1892, 'Just as We had revealed [scriptures] to the separators', NULL, NULL, 'b8d5a332b614f6d8cfa5e325c5522a083e6c4e095e360c6f0393facf70864e8f'),
  ('en.sahih', 15, 91, 1893, 'Who have made the Qur''an into portions.', NULL, NULL, '333a97abbb94a81e9eacd2e0d1bfbe4dc21e68a89ee2870a49bfec4be7d14fdd'),
  ('en.sahih', 15, 92, 1894, 'So by your Lord, We will surely question them all', NULL, NULL, 'b9e0509060faf5f680a4a2031f9232537edf850d4e9762200f300b5d68e0c669'),
  ('en.sahih', 15, 93, 1895, 'About what they used to do.', NULL, NULL, 'e510d0c19d94e25b20c7987386d8441fb569a64cc0591ac43bf29e9ce5177b76'),
  ('en.sahih', 15, 94, 1896, 'Then declare what you are commanded and turn away from the polytheists.', NULL, NULL, 'd9788e3ea54d855cf930153e4380f419588c157e3773f59380933bb97819b267'),
  ('en.sahih', 15, 95, 1897, 'Indeed, We are sufficient for you against the mockers', NULL, NULL, 'dd226036fc904b7c9fad76f2f654ecc600fbbaf32514e2f894236091f4dc2dbf'),
  ('en.sahih', 15, 96, 1898, 'Who make [equal] with Allah another deity. But they are going to know.', NULL, NULL, '452ee724b88c71fc6de5cf9b65f52091de4817e97d3376b3e739f4156c512c52'),
  ('en.sahih', 15, 97, 1899, 'And We already know that your breast is constrained by what they say.', NULL, NULL, '9ea6f82bb32a9e8f55e73e0838bccb8d64dc9a89e73a281a643d08adebebeb9f'),
  ('en.sahih', 15, 98, 1900, 'So exalt [Allah] with praise of your Lord and be of those who prostrate [to Him].', NULL, NULL, '72716db0f4cef44319108f0b0757af60d8d35fae2bbcf6c878f740227e9f3051')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 15, 99, 1901, 'And worship your Lord until there comes to you the certainty (death).', NULL, NULL, '98e1d882fc4a9508569ccaf0ba79845c97c9269ee3092643c8a33f553fbad910'),
  ('en.sahih', 16, 1, 1902, 'The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.', NULL, NULL, '8c80aad7a2072a3dcced6b1753e11b7c39a919d3a477f84801c2d23fd6c82e1e'),
  ('en.sahih', 16, 2, 1903, 'He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."', NULL, NULL, 'ab530ef11133485dcf7d632ffc856b9130d679a429b6ca4182c2190db559195f'),
  ('en.sahih', 16, 3, 1904, 'He created the heavens and earth in truth. High is He above what they associate with Him.', NULL, NULL, 'd32f6127819e31b7d1e161d51db551d37ce48796bb19d5cab096f5e5fda6aad4'),
  ('en.sahih', 16, 4, 1905, 'He created man from a sperm-drop; then at once, he is a clear adversary.', NULL, NULL, '6005b84203ede63b6912cd17a3eaf574c1d0cae7c14f2ea6f39fe2bba2859c24'),
  ('en.sahih', 16, 5, 1906, 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.', NULL, NULL, 'ff43de612c4dc609fdf5bbd14fd3770eea60717a65a5203337f3b4dca2fd60ba'),
  ('en.sahih', 16, 6, 1907, 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].', NULL, NULL, '5becf4f7b83aa9bb1a48e12618841438eb1eaa1ac6631f1902349eefdf2560bb'),
  ('en.sahih', 16, 7, 1908, 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.', NULL, NULL, '1c4679c4391365d8744cc71961f52b46d9aae0d8d1d55bd81611686172431dc7'),
  ('en.sahih', 16, 8, 1909, 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.', NULL, NULL, '74cb06fb7a8482abc421c70d70793737d0bb1d054485196526cfecd90e041381'),
  ('en.sahih', 16, 9, 1910, 'And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.', NULL, NULL, '48a21e0ecc73965f8b91b1dbd16fd120c3f9b636b7958fde6cebd59a8860864c'),
  ('en.sahih', 16, 10, 1911, 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].', NULL, NULL, '600a0bd3fa848a385f6e1e8d5791adb103e8c60393193989c9c1d978408cc961'),
  ('en.sahih', 16, 11, 1912, 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought.', NULL, NULL, '1700e8a6d3e3ae6f39e7cb49212dceaa8f004eaa11f3adf2257cceb7631cf53c'),
  ('en.sahih', 16, 12, 1913, 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.', NULL, NULL, '59f02221f8bf43670b4a5a987dc1f1440213e3b99d55bf56217a5aa96bbeed17'),
  ('en.sahih', 16, 13, 1914, 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.', NULL, NULL, '50092801a75490773421ca478447a18d7e12ee30473b931b7c78ddf8e35004f1'),
  ('en.sahih', 16, 14, 1915, 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.', NULL, NULL, 'f851c2ea9b0947c1ae41dba7dc19ccfd7ea8f5593d34d20a9f03a2e6f5e019fb'),
  ('en.sahih', 16, 15, 1916, 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,', NULL, NULL, '3ebc53b6900befaa50f6fbdd0a344068db640ef0662a70eac833c7404731f74b'),
  ('en.sahih', 16, 16, 1917, 'And landmarks. And by the stars they are [also] guided.', NULL, NULL, 'a0e5ad29c1bbc58aa4a536adb580d8cfd4449bbc832bb1ddbb8e3724dd43e510'),
  ('en.sahih', 16, 17, 1918, 'Then is He who creates like one who does not create? So will you not be reminded?', NULL, NULL, '497543d12488befd3ab9f69bbdfbc4523b025cbfeb12aad3082b7c5f5554dd61'),
  ('en.sahih', 16, 18, 1919, 'And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '56af7bf5c6a3128ef2fed500a8c8db2f2a5cf67cb9918cfc970bac3ba9e002e3'),
  ('en.sahih', 16, 19, 1920, 'And Allah knows what you conceal and what you declare.', NULL, NULL, '80aa571b62a32fee7a8a18f9694c50cf082376cf0f8ba4fe86a6d0931faaec4f'),
  ('en.sahih', 16, 20, 1921, 'And those they invoke other than Allah create nothing, and they [themselves] are created.', NULL, NULL, '2532fa1eb735407042fa395fff6422cbef0e2ba04807ce95013923b9c35bbf5b'),
  ('en.sahih', 16, 21, 1922, 'They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected.', NULL, NULL, '49e361f954c14578dba74fd9b98fdf6b0a64720ca012083418217691278647ce'),
  ('en.sahih', 16, 22, 1923, 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.', NULL, NULL, 'eb749943f5fa2fc38a1119cb9b54227f17dedaf9a0f90b874bb1cbc1f69c80ab'),
  ('en.sahih', 16, 23, 1924, 'Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.', NULL, NULL, 'f6f28a923e01ba581d6d719ef684c929563c311288f78d3c7d39c447e6e87af5'),
  ('en.sahih', 16, 24, 1925, 'And when it is said to them, "What has your Lord sent down?" They say, "Legends of the former peoples,"', NULL, NULL, 'f645540fd9c1a3c30f4bd67b66b41268f505271b27c6f4deee840fd23408d1f6'),
  ('en.sahih', 16, 25, 1926, 'That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear.', NULL, NULL, '832ef7cd170bf6ebc6ed311ac0ad67f9448bbb8f47fe5726bd89f2ae034923d0'),
  ('en.sahih', 16, 26, 1927, 'Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.', NULL, NULL, 'b17aa287576fd44b14eb226146a04521f9cd7ab14458f150c809be3f6bfd463c'),
  ('en.sahih', 16, 27, 1928, 'Then on the Day of Resurrection He will disgrace them and say, "Where are My ''partners'' for whom you used to oppose [the believers]?" Those who were given knowledge will say, "Indeed disgrace, this Day, and evil are upon the disbelievers" -', NULL, NULL, '9bae4a695bcd69e60d851f1b8bfa8a6fa42fbc392d2d24fb4a6b431a75916117'),
  ('en.sahih', 16, 28, 1929, 'The ones whom the angels take in death [while] wronging themselves, and [who] then offer submission, [saying], "We were not doing any evil." But, yes! Indeed, Allah is Knowing of what you used to do.', NULL, NULL, 'ba730c678f048b0adcf5a3cf949c691000ab88018fffa474350d97a81997f015'),
  ('en.sahih', 16, 29, 1930, 'So enter the gates of Hell to abide eternally therein, and how wretched is the residence of the arrogant.', NULL, NULL, '94d5063f952f7e38856643acbbbf6e8833ced8d84db14b96baf956efaf1dd4c7'),
  ('en.sahih', 16, 30, 1931, 'And it will be said to those who feared Allah, "What did your Lord send down?" They will say, "[That which is] good." For those who do good in this world is good; and the home of the Hereafter is better. And how excellent is the home of the righteous -', NULL, NULL, '565796858526ebd212e750c5d9702dc69d140907e3ab3b776adafe858ff2b131'),
  ('en.sahih', 16, 31, 1932, 'Gardens of perpetual residence, which they will enter, beneath which rivers flow. They will have therein whatever they wish. Thus does Allah reward the righteous -', NULL, NULL, '7ea36ee359c1e950571fc519272e2444650fea3025601176d382fb9b4ab42cd4'),
  ('en.sahih', 16, 32, 1933, 'The ones whom the angels take in death, [being] good and pure; [the angels] will say, "Peace be upon you. Enter Paradise for what you used to do."', NULL, NULL, '789ee2e3b672e91d2a7da9bf096ff0d45d3819dd11cc65630350ddab9d4ad787'),
  ('en.sahih', 16, 33, 1934, 'Do the disbelievers await [anything] except that the angels should come to them or there comes the command of your Lord? Thus did those do before them. And Allah wronged them not, but they had been wronging themselves.', NULL, NULL, '57e4ec0fbc7f2aeb9b592945d1752c355c66b2a97d4a0b1d76c7034be3eba581'),
  ('en.sahih', 16, 34, 1935, 'So they were struck by the evil consequences of what they did and were enveloped by what they used to ridicule.', NULL, NULL, '9936dbbb3056bc65a4441f83a6b7b748f5441a360bec7a46dc5b9f4609ecf91a'),
  ('en.sahih', 16, 35, 1936, 'And those who associate others with Allah say, "If Allah had willed, we would not have worshipped anything other than Him, neither we nor our fathers, nor would we have forbidden anything through other than Him." Thus did those do before them. So is there upon the messengers except [the duty of] clear notification?', NULL, NULL, '3ecd5f9d007361ec0df91c332cd046a7e89ba21a767c7ffc929ec2ac5c155964'),
  ('en.sahih', 16, 36, 1937, 'And We certainly sent into every nation a messenger, [saying], "Worship Allah and avoid Taghut." And among them were those whom Allah guided, and among them were those upon whom error was [deservedly] decreed. So proceed through the earth and observe how was the end of the deniers.', NULL, NULL, 'dd910587220506c8a51b6d97f4f25716dd5aa9748354f2381d446644cd71f663'),
  ('en.sahih', 16, 37, 1938, '[Even] if you should strive for their guidance, [O Muhammad], indeed, Allah does not guide those He sends astray, and they will have no helpers.', NULL, NULL, '695599978ad8b3baf1c71481f1ecf56fe1f113ebe8fd7b7d97935e0981a52a2f'),
  ('en.sahih', 16, 38, 1939, 'And they swear by Allah their strongest oaths [that] Allah will not resurrect one who dies. But yes - [it is] a true promise [binding] upon Him, but most of the people do not know.', NULL, NULL, '46bcc7044996a646919cfd1745a0ee7239f5779fd0150145f8ad4242c565193c'),
  ('en.sahih', 16, 39, 1940, '[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars.', NULL, NULL, '2e8c3266c32656d51480deab2e1543bfb81f8897b692383990a5616e10b24d84'),
  ('en.sahih', 16, 40, 1941, 'Indeed, Our word to a thing when We intend it is but that We say to it, "Be," and it is.', NULL, NULL, 'dab2eaf0e7e2747c73822ad7e166736120a1bbc860f6bdc604236088e55d6643'),
  ('en.sahih', 16, 41, 1942, 'And those who emigrated for [the cause of] Allah after they had been wronged - We will surely settle them in this world in a good place; but the reward of the Hereafter is greater, if only they could know.', NULL, NULL, '8dbdebf396d33083fda1a22be668e2aaca4fd2c3d3ad41f53cf8bd66fadcac80'),
  ('en.sahih', 16, 42, 1943, '[They are] those who endured patiently and upon their Lord relied.', NULL, NULL, 'da14bb72a6a7e86956a2ad1bf05394ea1d850420d9845e31f17ac7d7a3a6d2fc'),
  ('en.sahih', 16, 43, 1944, 'And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message if you do not know.', NULL, NULL, 'b99ff7fbfe33853abd8464266c0dfdecd7d83a1e086a9f0dbbb7da566420ea9d'),
  ('en.sahih', 16, 44, 1945, '[We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought.', NULL, NULL, '851ff06d54d0d30a9deff4cdbb550d5a1e8bb8348023faa56747e3c3d95684f9'),
  ('en.sahih', 16, 45, 1946, 'Then, do those who have planned evil deeds feel secure that Allah will not cause the earth to swallow them or that the punishment will not come upon them from where they do not perceive?', NULL, NULL, 'b050c18bfeb95b7144cb61451400cd2686926f55fc47790a3a0c4406a67b8eec'),
  ('en.sahih', 16, 46, 1947, 'Or that He would not seize them during their [usual] activity, and they could not cause failure?', NULL, NULL, 'd6f89b351d6bf449ebf8c8701276ff5f64f526a843c8f7f020191ad55336b944'),
  ('en.sahih', 16, 47, 1948, 'Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful.', NULL, NULL, '33a75bf58650737b820e0c75b505f9c01e991fb71e7d8626c8ec1a5ace492b8f'),
  ('en.sahih', 16, 48, 1949, 'Have they not considered what things Allah has created? Their shadows incline to the right and to the left, prostrating to Allah, while they are humble.', NULL, NULL, 'c289ec276fe57bce2383d3fa689d7d350203186de06f4fec06fff7904fa3b78e'),
  ('en.sahih', 16, 49, 1950, 'And to Allah prostrates whatever is in the heavens and whatever is on the earth of creatures, and the angels [as well], and they are not arrogant.', NULL, NULL, '8aecc7ef2d63fdcfeaf976c1d698e9575b64155f8c86fe98078772728241515c'),
  ('en.sahih', 16, 50, 1951, 'They fear their Lord above them, and they do what they are commanded.', NULL, NULL, '60a94c3812fd015062ad380347765eb9c6f35d130ac1e6cc7b79e7e07017c742'),
  ('en.sahih', 16, 51, 1952, 'And Allah has said, "Do not take for yourselves two deities. He is but one God, so fear only Me."', NULL, NULL, '9e6c02563f777f3be670aaad59b58082ea9fef954b63c2ca4f2c03cf816776e8'),
  ('en.sahih', 16, 52, 1953, 'And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allah that you fear?', NULL, NULL, '68c24ed059058ae6cfc4f50fda860c719fc1822d802c09bd0d39ed09c8001d8a'),
  ('en.sahih', 16, 53, 1954, 'And whatever you have of favor - it is from Allah. Then when adversity touches you, to Him you cry for help.', NULL, NULL, '19860846aaf3c1df8598cd267ad5fe85178e6625f99fb827dff6c89fe41dbca6'),
  ('en.sahih', 16, 54, 1955, 'Then when He removes the adversity from you, at once a party of you associates others with their Lord', NULL, NULL, '4c845e65cc9a58265f3e44948a125dcbef2dd042cbe3bfc4cdd3af2ad7bb29e3'),
  ('en.sahih', 16, 55, 1956, 'So they will deny what We have given them. Then enjoy yourselves, for you are going to know.', NULL, NULL, '043d6e126052ba2df30c4ec88d3b7ae90ece8abeb72f44e2e7262c9504b07b8c'),
  ('en.sahih', 16, 56, 1957, 'And they assign to what they do not know a portion of that which We have provided them. By Allah, you will surely be questioned about what you used to invent.', NULL, NULL, '630347b04744f7e63b47eb81fbddf12f5b0dcf5b42dc0dad014de2e792706d7f'),
  ('en.sahih', 16, 57, 1958, 'And they attribute to Allah daughters - exalted is He - and for them is what they desire.', NULL, NULL, '784e01887e1f6e1097decdb41a71c124975cc6419af5de6abc2001c8142a1017'),
  ('en.sahih', 16, 58, 1959, 'And when one of them is informed of [the birth of] a female, his face becomes dark, and he suppresses grief.', NULL, NULL, '55936ee429414e9bb8bc832216c287afbf5becba816ceb7de43380ae0289c2b9'),
  ('en.sahih', 16, 59, 1960, 'He hides himself from the people because of the ill of which he has been informed. Should he keep it in humiliation or bury it in the ground? Unquestionably, evil is what they decide.', NULL, NULL, '9779f8bd212d1d2b0544d8dd4b24820a2368494d044894f11e2dcef4eb2b6eab'),
  ('en.sahih', 16, 60, 1961, 'For those who do not believe in the Hereafter is the description of evil; and for Allah is the highest attribute. And He is Exalted in Might, the Wise.', NULL, NULL, '4a9a85b3b25ecd83f84f409d4851111aac9fd853be65337644425d50cae9f082'),
  ('en.sahih', 16, 61, 1962, 'And if Allah were to impose blame on the people for their wrongdoing, He would not have left upon the earth any creature, but He defers them for a specified term. And when their term has come, they will not remain behind an hour, nor will they precede [it].', NULL, NULL, '737220954cf0c809e8a4c68bf7a3f3bf54268caf1e7a0f6efcf0a2152b587883'),
  ('en.sahih', 16, 62, 1963, 'And they attribute to Allah that which they dislike, and their tongues assert the lie that they will have the best [from Him]. Assuredly, they will have the Fire, and they will be [therein] neglected.', NULL, NULL, 'ffb1779cec105350d47eaeca4e503e5b2f3017bff5b7652680d15bd69a49caa9'),
  ('en.sahih', 16, 63, 1964, 'By Allah, We did certainly send [messengers] to nations before you, but Satan made their deeds attractive to them. And he is the disbelievers'' ally today [as well], and they will have a painful punishment.', NULL, NULL, 'c7e376e0f3b506cf78ed854198da0f7b09865dcd3eb942a0be977453118a78be'),
  ('en.sahih', 16, 64, 1965, 'And We have not revealed to you the Book, [O Muhammad], except for you to make clear to them that wherein they have differed and as guidance and mercy for a people who believe.', NULL, NULL, '5b982f8db12da0941d5c014f4258e49ee82d73bc3f09fb79a30f693a761c0855'),
  ('en.sahih', 16, 65, 1966, 'And Allah has sent down rain from the sky and given life thereby to the earth after its lifelessness. Indeed in that is a sign for a people who listen.', NULL, NULL, '377535d76546b173a0f83f6b1f3544889a8ee3642c383fd38bc68a7c5382f078'),
  ('en.sahih', 16, 66, 1967, 'And indeed, for you in grazing livestock is a lesson. We give you drink from what is in their bellies - between excretion and blood - pure milk, palatable to drinkers.', NULL, NULL, '1ba5086c73ad23111934891ba20a225dc5e024a5143a86be6264c59dc1f4092c'),
  ('en.sahih', 16, 67, 1968, 'And from the fruits of the palm trees and grapevines you take intoxicant and good provision. Indeed in that is a sign for a people who reason.', NULL, NULL, 'f9632236674aecf63580499aad0da91a8a51edcce2bbcc82678f6985f5b5d0fa'),
  ('en.sahih', 16, 68, 1969, 'And your Lord inspired to the bee, "Take for yourself among the mountains, houses, and among the trees and [in] that which they construct.', NULL, NULL, 'ae86b32819a25c3063eb9c8c71befebbdb878fa587c270376c7513fd20a59e78'),
  ('en.sahih', 16, 69, 1970, 'Then eat from all the fruits and follow the ways of your Lord laid down [for you]." There emerges from their bellies a drink, varying in colors, in which there is healing for people. Indeed in that is a sign for a people who give thought.', NULL, NULL, 'e95eb42c116dccce3c3ae1185563e9e0a12ca1e02612d1d96a39e90105db19c5'),
  ('en.sahih', 16, 70, 1971, 'And Allah created you; then He will take you in death. And among you is he who is reversed to the most decrepit [old] age so that he will not know, after [having had] knowledge, a thing. Indeed, Allah is Knowing and Competent.', NULL, NULL, '2fd73579353110ec17c1a089135314d7f235068a4d2387df55092bd25aa6aa0e'),
  ('en.sahih', 16, 71, 1972, 'And Allah has favored some of you over others in provision. But those who were favored would not hand over their provision to those whom their right hands possess so they would be equal to them therein. Then is it the favor of Allah they reject?', NULL, NULL, 'e0a73998321b500a1edcf1787ec26551ea4a21fa4ae8a94bebe63cce46ac91c5'),
  ('en.sahih', 16, 72, 1973, 'And Allah has made for you from yourselves mates and has made for you from your mates sons and grandchildren and has provided for you from the good things. Then in falsehood do they believe and in the favor of Allah they disbelieve?', NULL, NULL, 'a5ccb5f1e1ca5dbd8f343c6cbfaff4ec76ecd0c9dc92761c9f5e9bfdafb90507'),
  ('en.sahih', 16, 73, 1974, 'And they worship besides Allah that which does not possess for them [the power of] provision from the heavens and the earth at all, and [in fact], they are unable.', NULL, NULL, '04d82297069e40fcc5a564779891bb76c16daedc55b5cace3c39df8f18ea5955'),
  ('en.sahih', 16, 74, 1975, 'So do not assert similarities to Allah. Indeed, Allah knows and you do not know.', NULL, NULL, 'f525b1cea7a744162f706a9cca37616c1bbf0419cc775cf678288e20fc73f2ce'),
  ('en.sahih', 16, 75, 1976, 'Allah presents an example: a slave [who is] owned and unable to do a thing and he to whom We have provided from Us good provision, so he spends from it secretly and publicly. Can they be equal? Praise to Allah! But most of them do not know.', NULL, NULL, '2c32b895f49d91eb0b5089f238c2e08971a40d1ba3f6bb5e5c997f7a45620508'),
  ('en.sahih', 16, 76, 1977, 'And Allah presents an example of two men, one of them dumb and unable to do a thing, while he is a burden to his guardian. Wherever he directs him, he brings no good. Is he equal to one who commands justice, while he is on a straight path?', NULL, NULL, 'f251f8ad6a6b159943e603c81762a5e345e96ffdf049d7d688b2a2960db99b8b'),
  ('en.sahih', 16, 77, 1978, 'And to Allah belongs the unseen [aspects] of the heavens and the earth. And the command for the Hour is not but as a glance of the eye or even nearer. Indeed, Allah is over all things competent.', NULL, NULL, '5c2018bece673648f2167b9d70ab6def406d49df17097d935212c2d9ec2e58ff'),
  ('en.sahih', 16, 78, 1979, 'And Allah has extracted you from the wombs of your mothers not knowing a thing, and He made for you hearing and vision and intellect that perhaps you would be grateful.', NULL, NULL, '459e2e4ae055e2cd305955e32c6d1ba5266925ac091f14048c991d1365cf80c2'),
  ('en.sahih', 16, 79, 1980, 'Do they not see the birds controlled in the atmosphere of the sky? None holds them up except Allah. Indeed in that are signs for a people who believe.', NULL, NULL, '58a997f88b7bc81f6d64bd26e9770108c3ff601b16b18d8fbd36f68b467bc957'),
  ('en.sahih', 16, 80, 1981, 'And Allah has made for you from your homes a place of rest and made for you from the hides of the animals tents which you find light on your day of travel and your day of encampment; and from their wool, fur and hair is furnishing and enjoyment for a time.', NULL, NULL, 'cc419ed7c115196e251c710681a4cb5899174140a80b2e9cbd5de2d1708e0a78'),
  ('en.sahih', 16, 81, 1982, 'And Allah has made for you, from that which He has created, shadows and has made for you from the mountains, shelters and has made for you garments which protect you from the heat and garments which protect you from your [enemy in] battle. Thus does He complete His favor upon you that you might submit [to Him].', NULL, NULL, '54b570f0cd993a2034168f50e679f386a12b69795fd8ff3a183f7ab63fbe2dcc'),
  ('en.sahih', 16, 82, 1983, 'But if they turn away, [O Muhammad] - then only upon you is [responsibility for] clear notification.', NULL, NULL, '266dc2ccc122d8988b5d010843c436b59c090057b387e5470c9089802e47cd13'),
  ('en.sahih', 16, 83, 1984, 'They recognize the favor of Allah; then they deny it. And most of them are disbelievers.', NULL, NULL, 'ff558d6f9c7bf8197dab23705e28b4b7ebcb0e6850469249acb42e8cb911a8f4'),
  ('en.sahih', 16, 84, 1985, 'And [mention] the Day when We will resurrect from every nation a witness. Then it will not be permitted to the disbelievers [to apologize or make excuses], nor will they be asked to appease [Allah].', NULL, NULL, '667ed13fdb1d043bc32034cea876d648c3ecaf5353aff64fc51399cab939ab01'),
  ('en.sahih', 16, 85, 1986, 'And when those who wronged see the punishment, it will not be lightened for them, nor will they be reprieved.', NULL, NULL, 'a8d95a72221899c769ab11e9b1aed7c6b941f63de3defe59127a6f24610c9123'),
  ('en.sahih', 16, 86, 1987, 'And when those who associated others with Allah see their "partners," they will say," Our Lord, these are our partners [to You] whom we used to invoke besides You." But they will throw at them the statement, "Indeed, you are liars."', NULL, NULL, '6c1fc33a3bcacf796adabd0e30ffa05cf95834b8dcda7ac2c3b8a5894b39a44f'),
  ('en.sahih', 16, 87, 1988, 'And they will impart to Allah that Day [their] submission, and lost from them is what they used to invent.', NULL, NULL, '5b1afcf25d54b9f54fb42c1c7e74b4a0aef918b9cfe3bfc7dc5773d1e9a785a6'),
  ('en.sahih', 16, 88, 1989, 'Those who disbelieved and averted [others] from the way of Allah - We will increase them in punishment over [their] punishment for what corruption they were causing.', NULL, NULL, 'c48cc67a064bd2ebadbb62bc081625f7d4339d6bb1364ab18c40d459893fe0d9'),
  ('en.sahih', 16, 89, 1990, 'And [mention] the Day when We will resurrect among every nation a witness over them from themselves. And We will bring you, [O Muhammad], as a witness over your nation. And We have sent down to you the Book as clarification for all things and as guidance and mercy and good tidings for the Muslims.', NULL, NULL, 'aa289084021852a8c7dfbdbf65be52edb107448af4dd13798353cd2771bfad8e'),
  ('en.sahih', 16, 90, 1991, 'Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded.', NULL, NULL, '0306b64905cfd6ee3ea937570495237ab5934c9806bd0b6ad53174be23b7c999'),
  ('en.sahih', 16, 91, 1992, 'And fulfill the covenant of Allah when you have taken it, [O believers], and do not break oaths after their confirmation while you have made Allah, over you, a witness. Indeed, Allah knows what you do.', NULL, NULL, '7eb0776d2ed392438eee21bcbc9579dcb1a3f52ebf4706c21854b0cd196ceda6'),
  ('en.sahih', 16, 92, 1993, 'And do not be like she who untwisted her spun thread after it was strong [by] taking your oaths as [means of] deceit between you because one community is more plentiful [in number or wealth] than another community. Allah only tries you thereby. And He will surely make clear to you on the Day of Resurrection that over which you used to differ.', NULL, NULL, '5284e0e1ffc4ae722a71f4e9d78cfd836d7e20290cf7bf8a66b0b46125d5adda'),
  ('en.sahih', 16, 93, 1994, 'And if Allah had willed, He could have made you [of] one religion, but He causes to stray whom He wills and guides whom He wills. And you will surely be questioned about what you used to do.', NULL, NULL, 'd8a8f0b2be404f5ad86a8b85dad148204953ec9a50eb6ba548e345cd5f89bda3'),
  ('en.sahih', 16, 94, 1995, 'And do not take your oaths as [means of] deceit between you, lest a foot slip after it was [once] firm, and you would taste evil [in this world] for what [people] you diverted from the way of Allah, and you would have [in the Hereafter] a great punishment.', NULL, NULL, '0d8f226ab2c56477ac0159fc5773d7bb4163e0f79983cabf3b65b4dc37126018'),
  ('en.sahih', 16, 95, 1996, 'And do not exchange the covenant of Allah for a small price. Indeed, what is with Allah is best for you, if only you could know.', NULL, NULL, '14cdd6d80b524df57098e57b8e04520a3dbf4280c89776b8b75ee9bf16c59898'),
  ('en.sahih', 16, 96, 1997, 'Whatever you have will end, but what Allah has is lasting. And We will surely give those who were patient their reward according to the best of what they used to do.', NULL, NULL, '61b26b35994858609db4459b949385adde9f81878596fff72f375ce7a5d3a8e4'),
  ('en.sahih', 16, 97, 1998, 'Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do.', NULL, NULL, '7d33ca0bb114d7ebc456c0c999090cd7331b1e1a27182c6444554dfdcdaf3f6e'),
  ('en.sahih', 16, 98, 1999, 'So when you recite the Qur''an, [first] seek refuge in Allah from Satan, the expelled [from His mercy].', NULL, NULL, '1a6c71164720e2aba95162f73e04da2f6f0eed472fc14dcbd6faffa021f2fc73'),
  ('en.sahih', 16, 99, 2000, 'Indeed, there is for him no authority over those who have believed and rely upon their Lord.', NULL, NULL, 'f64aad65b5a697f51cf63b4b76a912fb8c6ae937cb5458816470a1c6f9c9637c')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 16, 100, 2001, 'His authority is only over those who take him as an ally and those who through him associate others with Allah.', NULL, NULL, '8ea1d560dd2041d50dce240c6e72c4fe57987ee6ee90cec0aab2523378fb029c'),
  ('en.sahih', 16, 101, 2002, 'And when We substitute a verse in place of a verse - and Allah is most knowing of what He sends down - they say, "You, [O Muhammad], are but an inventor [of lies]." But most of them do not know.', NULL, NULL, '024eb201603ca2ddcf29dd540ad37029b554311b8e0d4ff6e8a4695527d64140'),
  ('en.sahih', 16, 102, 2003, 'Say, [O Muhammad], "The Pure Spirit has brought it down from your Lord in truth to make firm those who believe and as guidance and good tidings to the Muslims."', NULL, NULL, '0c4b2e13cda0245201be7af0342986c07c9892a0e7b2c78577c143d83c643fb9'),
  ('en.sahih', 16, 103, 2004, 'And We certainly know that they say, "It is only a human being who teaches the Prophet." The tongue of the one they refer to is foreign, and this Qur''an is [in] a clear Arabic language.', NULL, NULL, 'facdb5e19167e1ddc0e37195d141e9cabdff355784fea11734715340d0a4cc9c'),
  ('en.sahih', 16, 104, 2005, 'Indeed, those who do not believe in the verses of Allah - Allah will not guide them, and for them is a painful punishment.', NULL, NULL, '296fc3eab3810b85ad9eaf74976d116420e199d226a341b0a401fca6e27d4980'),
  ('en.sahih', 16, 105, 2006, 'They only invent falsehood who do not believe in the verses of Allah, and it is those who are the liars.', NULL, NULL, 'dd190d9707784744b3cd7dc319294712e8db8700eb48b79b4db9446eed2d4337'),
  ('en.sahih', 16, 106, 2007, 'Whoever disbelieves in Allah after his belief... except for one who is forced [to renounce his religion] while his heart is secure in faith. But those who [willingly] open their breasts to disbelief, upon them is wrath from Allah, and for them is a great punishment;', NULL, NULL, 'e84e02c873ac69efd231ffa8ebe07ab259ae39a5e1c77739f4a6a82e78815ea1'),
  ('en.sahih', 16, 107, 2008, 'That is because they preferred the worldly life over the Hereafter and that Allah does not guide the disbelieving people.', NULL, NULL, '5632e24dddd926d016aa6b553e33f034cefc27f16dc5f6b2c615a655dc6fb195'),
  ('en.sahih', 16, 108, 2009, 'Those are the ones over whose hearts and hearing and vision Allah has sealed, and it is those who are the heedless.', NULL, NULL, '36fdf5ea6839051ff4a4c056ec14204e86f3d47aa178cd94a2cc8d3b691c65ae'),
  ('en.sahih', 16, 109, 2010, 'Assuredly, it is they, in the Hereafter, who will be the losers.', NULL, NULL, '8100293d3a0753eea037e5c1cffd09d8d37adc316621842087d3f5944d6f5097'),
  ('en.sahih', 16, 110, 2011, 'Then, indeed your Lord, to those who emigrated after they had been compelled [to renounce their religion] and thereafter fought [for the cause of Allah] and were patient - indeed, your Lord, after that, is Forgiving and Merciful', NULL, NULL, '60de1f79747bef9b4b8a798fa7ff4a40af2245c178af336ae9c3dbb29844b954'),
  ('en.sahih', 16, 111, 2012, 'On the Day when every soul will come disputing for itself, and every soul will be fully compensated for what it did, and they will not be wronged.', NULL, NULL, 'bf144c49c3534cb34d11ce8bddf574fda5a89b91d984ee48d0bde48d101d3488'),
  ('en.sahih', 16, 112, 2013, 'And Allah presents an example: a city which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allah. So Allah made it taste the envelopment of hunger and fear for what they had been doing.', NULL, NULL, 'f69a08c948d0aeab3e948964eb95894762138b68864a058090f1741e3dc1b770'),
  ('en.sahih', 16, 113, 2014, 'And there had certainly come to them a Messenger from among themselves, but they denied him; so punishment overtook them while they were wrongdoers.', NULL, NULL, '947edf63f6cd731dc3d66b1420cd02292c30481c560bb22bfa65df7e55947ba3'),
  ('en.sahih', 16, 114, 2015, 'Then eat of what Allah has provided for you [which is] lawful and good. And be grateful for the favor of Allah, if it is [indeed] Him that you worship.', NULL, NULL, '85d4d14eed682c5210e45e026527012cf6d281e55357037b33878cfa752ace21'),
  ('en.sahih', 16, 115, 2016, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit] - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, '6ecbf23c57a5d4018a9c4937da34f79b08e61715bb0067325b93e28e923af96c'),
  ('en.sahih', 16, 116, 2017, 'And do not say about what your tongues assert of untruth, "This is lawful and this is unlawful," to invent falsehood about Allah. Indeed, those who invent falsehood about Allah will not succeed.', NULL, NULL, '8f251fee256264d63ee0b3e9da0136cb3b3645ab36a4a90f5f7e8afa80308c07'),
  ('en.sahih', 16, 117, 2018, '[It is but] a brief enjoyment, and they will have a painful punishment.', NULL, NULL, 'c21b67a55bc51d9dec3920d2a65d89218df8ebe6290e949641d4040888861d59'),
  ('en.sahih', 16, 118, 2019, 'And to those who are Jews We have prohibited that which We related to you before. And We did not wrong them [thereby], but they were wronging themselves.', NULL, NULL, '2364a60cc708d6c76df65ee348ca0abc0e0d0e878cc5e134f52f4012c56206dd'),
  ('en.sahih', 16, 119, 2020, 'Then, indeed your Lord, to those who have done wrong out of ignorance and then repent after that and correct themselves - indeed, your Lord, thereafter, is Forgiving and Merciful.', NULL, NULL, '8da6293d2c6c2659ad8579cfa86c9ef19ff32601171d2f8c0e78b4753f976f93'),
  ('en.sahih', 16, 120, 2021, 'Indeed, Abraham was a [comprehensive] leader, devoutly obedient to Allah, inclining toward truth, and he was not of those who associate others with Allah.', NULL, NULL, '653c809564ebfaa2798e03664ab698f5b05f1199e99735d74043a2610d3b2686'),
  ('en.sahih', 16, 121, 2022, '[He was] grateful for His favors. Allah chose him and guided him to a straight path.', NULL, NULL, '99d72a24421a0f937137e7d98a5583c9d15cd6a90c717627454974a54df27fe4'),
  ('en.sahih', 16, 122, 2023, 'And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous.', NULL, NULL, 'b2fb601e43d25ed8878d7d752a1deefa57dfebc077f22dceafd322ce568bbf29'),
  ('en.sahih', 16, 123, 2024, 'Then We revealed to you, [O Muhammad], to follow the religion of Abraham, inclining toward truth; and he was not of those who associate with Allah.', NULL, NULL, 'e781c45a394f855f48ecbce6ebe2025261a35cdfee88be36e02f69ba291f4b7e'),
  ('en.sahih', 16, 124, 2025, 'The sabbath was only appointed for those who differed over it. And indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', NULL, NULL, 'ff29c91dc8d82690ef7f1a38f7bfc408b9df168653a0a72e1fc2418c4f8b78d6'),
  ('en.sahih', 16, 125, 2026, 'Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided.', NULL, NULL, '5e424eeadc6033756591ff4791401d86719fd8c31ef6a1fd8384fcef94447aa8'),
  ('en.sahih', 16, 126, 2027, 'And if you punish [an enemy, O believers], punish with an equivalent of that with which you were harmed. But if you are patient - it is better for those who are patient.', NULL, NULL, 'b57f9bfc3b344bf46cac0f6e68affdd718194e3ceddbba3fec76f601165309dd'),
  ('en.sahih', 16, 127, 2028, 'And be patient, [O Muhammad], and your patience is not but through Allah. And do not grieve over them and do not be in distress over what they conspire.', NULL, NULL, '41adffba5820b0fd0a0c86b04e905d6b2f78cb8ea171eff32bbb4543730aa7cf'),
  ('en.sahih', 16, 128, 2029, 'Indeed, Allah is with those who fear Him and those who are doers of good.', NULL, NULL, '40eeb0c68c7daaf2d82d0ec5c16cafcb35e235f7ec555ac4cea93300b3dbc3e7'),
  ('en.sahih', 17, 1, 2030, 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.', NULL, NULL, '2575f7429d865a5fe51faba0715878ecefd89fa79104f494783b2a3a91b26c6a'),
  ('en.sahih', 17, 2, 2031, 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,', NULL, NULL, '4234c3f0dbb20347273ae9cc61ac2b63bdbd7686cb1aeaff825d754626f5ee83'),
  ('en.sahih', 17, 3, 2032, 'O descendants of those We carried [in the ship] with Noah. Indeed, he was a grateful servant.', NULL, NULL, 'e54dae8ef436169f707b97bc40c9e7f03d84697ba0690bf6d301377c7982c549'),
  ('en.sahih', 17, 4, 2033, 'And We conveyed to the Children of Israel in the Scripture that, "You will surely cause corruption on the earth twice, and you will surely reach [a degree of] great haughtiness.', NULL, NULL, '88dc4f87c034141e6d82f65c33fb2b943f4c1ce76977f356a67d4498befe92e4'),
  ('en.sahih', 17, 5, 2034, 'So when the [time of] promise came for the first of them, We sent against you servants of Ours - those of great military might, and they probed [even] into the homes, and it was a promise fulfilled.', NULL, NULL, '676f592817edbfddbb14addc1c0f7379db01b4014214556263dd4cae1d10f6fe'),
  ('en.sahih', 17, 6, 2035, 'Then We gave back to you a return victory over them. And We reinforced you with wealth and sons and made you more numerous in manpower', NULL, NULL, 'a6fb97064a9a7315fd9f2744df83a0a8e2895fe894ab1d97372490916968b9b1'),
  ('en.sahih', 17, 7, 2036, '[And said], "If you do good, you do good for yourselves; and if you do evil, [you do it] to yourselves." Then when the final promise came, [We sent your enemies] to sadden your faces and to enter the temple in Jerusalem, as they entered it the first time, and to destroy what they had taken over with [total] destruction.', NULL, NULL, '43dd94fd98d13254219e54c6b71c2ab55ddade02a391514d08a58116faa88e85'),
  ('en.sahih', 17, 8, 2037, '[Then Allah said], "It is expected, [if you repent], that your Lord will have mercy upon you. But if you return [to sin], We will return [to punishment]. And We have made Hell, for the disbelievers, a prison-bed."', NULL, NULL, '639163fbe01991ff3d9eeaf6f090b7d8c81bb248d459a37afba2be258c14ec21'),
  ('en.sahih', 17, 9, 2038, 'Indeed, this Qur''an guides to that which is most suitable and gives good tidings to the believers who do righteous deeds that they will have a great reward.', NULL, NULL, 'f3629e51ab36b46cf2754f058820697a743e6f866981f0da6366d047628e6061'),
  ('en.sahih', 17, 10, 2039, 'And that those who do not believe in the Hereafter - We have prepared for them a painful punishment.', NULL, NULL, '07a6b07710f352b04ff709a8c60e476e208654fd6a0e68ff8b04947d8aad3994'),
  ('en.sahih', 17, 11, 2040, 'And man supplicates for evil as he supplicates for good, and man is ever hasty.', NULL, NULL, 'f8ac11d7b6b437d02da829599c60ab770316f7e073517282a6d81fb53bafe5b8'),
  ('en.sahih', 17, 12, 2041, 'And We have made the night and day two signs, and We erased the sign of the night and made the sign of the day visible that you may seek bounty from your Lord and may know the number of years and the account [of time]. And everything We have set out in detail.', NULL, NULL, '11362727f78e8de777995b20babc5be96ddf94bc3c0d9a896d7075ecd18190d5'),
  ('en.sahih', 17, 13, 2042, 'And [for] every person We have imposed his fate upon his neck, and We will produce for him on the Day of Resurrection a record which he will encounter spread open.', NULL, NULL, '9846312ea6d6cf90905bc035bd832b1831a28b0bc963d3c721992f4b95e96b0b'),
  ('en.sahih', 17, 14, 2043, '[It will be said], "Read your record. Sufficient is yourself against you this Day as accountant."', NULL, NULL, '49b8ed8a0a5afc31dfcaf74f49656c31ab1e3c946e348a954462685d62ac72e3'),
  ('en.sahih', 17, 15, 2044, 'Whoever is guided is only guided for [the benefit of] his soul. And whoever errs only errs against it. And no bearer of burdens will bear the burden of another. And never would We punish until We sent a messenger.', NULL, NULL, 'daa1cf273d170aba64272c1ffd0d0763cf7836c99cb7049e13c97850c805ea1c'),
  ('en.sahih', 17, 16, 2045, 'And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word comes into effect upon it, and We destroy it with [complete] destruction.', NULL, NULL, '803485b7f9218536d8e4c11492f1262a2c7c1693d9548a3606438f46c5185946'),
  ('en.sahih', 17, 17, 2046, 'And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Acquainted and Seeing.', NULL, NULL, '6799520abbdc4ded608909508981a15fb0ae76a553202141c3c896f3a6d081d6'),
  ('en.sahih', 17, 18, 2047, 'Whoever should desire the immediate - We hasten for him from it what We will to whom We intend. Then We have made for him Hell, which he will [enter to] burn, censured and banished.', NULL, NULL, 'cfaeb3383bd8c8a2fae388fec0f7dcb320e76d9dfb3babd5f22e7641d46fed5d'),
  ('en.sahih', 17, 19, 2048, 'But whoever desires the Hereafter and exerts the effort due to it while he is a believer - it is those whose effort is ever appreciated [by Allah].', NULL, NULL, 'fdb5d6cc59ae5f1f43fbcf5f75c8f8199818e9ed29b63b273a474976e4edee08'),
  ('en.sahih', 17, 20, 2049, 'To each [category] We extend - to these and to those - from the gift of your Lord. And never has the gift of your Lord been restricted.', NULL, NULL, '08195792a0bb57c6b6138a89273fea3eca5e934c22c135adb332a4f24590f593'),
  ('en.sahih', 17, 21, 2050, 'Look how We have favored [in provision] some of them over others. But the Hereafter is greater in degrees [of difference] and greater in distinction.', NULL, NULL, '9036369c9d7c222849f9b0b1bfa54934bf59bee064b814dd672c9802aa601947'),
  ('en.sahih', 17, 22, 2051, 'Do not make [as equal] with Allah another deity and [thereby] become censured and forsaken.', NULL, NULL, '8cb835722d911b32b2d5244e6541d0749734bb493a4e082b28bfc8df58c446ce'),
  ('en.sahih', 17, 23, 2052, 'And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], "uff," and do not repel them but speak to them a noble word.', NULL, NULL, '4a4ecfc9fea892cd74938a9a41b1f5f58d0b9b21e75de3870105c4bc6ec34de0'),
  ('en.sahih', 17, 24, 2053, 'And lower to them the wing of humility out of mercy and say, "My Lord, have mercy upon them as they brought me up [when I was] small."', NULL, NULL, 'd2831a9af3c1d24a993a8f5842ded3e63a4bb2975f0075a5e2977b2c772f962c'),
  ('en.sahih', 17, 25, 2054, 'Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving.', NULL, NULL, '8aacd42f9d9eb9f27bfdd67d8ea12d1c7bffb9b38748f951ac5824c227d561e5'),
  ('en.sahih', 17, 26, 2055, 'And give the relative his right, and [also] the poor and the traveler, and do not spend wastefully.', NULL, NULL, '13446c9fb0d7e693f0f97eaf2e46adcb441fe1669b7c5c86b92a832c2e57153d'),
  ('en.sahih', 17, 27, 2056, 'Indeed, the wasteful are brothers of the devils, and ever has Satan been to his Lord ungrateful.', NULL, NULL, 'ec48f3d21cedbbd03e270f649a04cea0e3103a8d528448304fce70381933d874'),
  ('en.sahih', 17, 28, 2057, 'And if you [must] turn away from the needy awaiting mercy from your Lord which you expect, then speak to them a gentle word.', NULL, NULL, 'bed66c612f08a36d1a8e343f9ac2914565d20d8d945a15ef21f7eb9aa44ade3d'),
  ('en.sahih', 17, 29, 2058, 'And do not make your hand [as] chained to your neck or extend it completely and [thereby] become blamed and insolvent.', NULL, NULL, 'e5f8bdfa794c8b9c965276daed3a790bea6c92945f32cb29ad1ccdd06b7fd3e6'),
  ('en.sahih', 17, 30, 2059, 'Indeed, your Lord extends provision for whom He wills and restricts [it]. Indeed He is ever, concerning His servants, Acquainted and Seeing.', NULL, NULL, 'd6318c78c5e0449e1a43eb74e8361b34f5452c9a36b7aa81cea8587762349941'),
  ('en.sahih', 17, 31, 2060, 'And do not kill your children for fear of poverty. We provide for them and for you. Indeed, their killing is ever a great sin.', NULL, NULL, '44a5171d00fc5d7a2251dd65d120468a8dd4236012a1f07d8b3199bcf0f665ed'),
  ('en.sahih', 17, 32, 2061, 'And do not approach unlawful sexual intercourse. Indeed, it is ever an immorality and is evil as a way.', NULL, NULL, 'ae9cf748b0c45540a1f7ec00aa246536f25a779dba1e6fea4678879616bb02e9'),
  ('en.sahih', 17, 33, 2062, 'And do not kill the soul which Allah has forbidden, except by right. And whoever is killed unjustly - We have given his heir authority, but let him not exceed limits in [the matter of] taking life. Indeed, he has been supported [by the law].', NULL, NULL, '5109d8d8cab5d92f036aad6518f0e75590144444bbb2db2b2b61fc0bb7e22fda'),
  ('en.sahih', 17, 34, 2063, 'And do not approach the property of an orphan, except in the way that is best, until he reaches maturity. And fulfill [every] commitment. Indeed, the commitment is ever [that about which one will be] questioned.', NULL, NULL, '7a89efd0d8742c8f8de66453816ad37e9c7e9a5a0110997917e51a01e49cefa3'),
  ('en.sahih', 17, 35, 2064, 'And give full measure when you measure, and weigh with an even balance. That is the best [way] and best in result.', NULL, NULL, '4f1f5ee6c1b8f7c3b9ed8efa46ad7dcfa0ae3a15ccc73351551744ab679a840f'),
  ('en.sahih', 17, 36, 2065, 'And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned.', NULL, NULL, '6cb425729d68ffc68525cd2f89225db2310d69257f49bc8acfcfc89c363d8563'),
  ('en.sahih', 17, 37, 2066, 'And do not walk upon the earth exultantly. Indeed, you will never tear the earth [apart], and you will never reach the mountains in height.', NULL, NULL, 'c25b2626f65f25603b70d69e13375999a5781a039d0f09aff816317b4c1c7bc2'),
  ('en.sahih', 17, 38, 2067, 'All that - its evil is ever, in the sight of your Lord, detested.', NULL, NULL, 'a45abd244d00a729cfdb776a3a7934db89bb1875ca8067be19707168fc8236b8'),
  ('en.sahih', 17, 39, 2068, 'That is from what your Lord has revealed to you, [O Muhammad], of wisdom. And, [O mankind], do not make [as equal] with Allah another deity, lest you be thrown into Hell, blamed and banished.', NULL, NULL, 'eb9798824361d29542d8ff61068eef6944fee5650e9b28132328aab1356fc7dc'),
  ('en.sahih', 17, 40, 2069, 'Then, has your Lord chosen you for [having] sons and taken from among the angels daughters? Indeed, you say a grave saying.', NULL, NULL, '47b5a68a53ac499b0b76466fe1294877b22fb28183df0453e33fbf6f974d786a'),
  ('en.sahih', 17, 41, 2070, 'And We have certainly diversified [the contents] in this Qur''an that mankind may be reminded, but it does not increase the disbelievers except in aversion.', NULL, NULL, '499421a39a73de590c3d6dc65bb09c813ed8c8c023d4194ef4c868e418b50afb'),
  ('en.sahih', 17, 42, 2071, 'Say, [O Muhammad], "If there had been with Him [other] gods, as they say, then they [each] would have sought to the Owner of the Throne a way."', NULL, NULL, '0136d3bcea32578cf0e995930c837a0960e54ae3954214dbc9f4d59aff08e60f'),
  ('en.sahih', 17, 43, 2072, 'Exalted is He and high above what they say by great sublimity.', NULL, NULL, 'b9b6bc77a005e8e6a192986714261cd69b4589107d5205c6bfa5a799e1309095'),
  ('en.sahih', 17, 44, 2073, 'The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts [Allah] by His praise, but you do not understand their [way of] exalting. Indeed, He is ever Forbearing and Forgiving.', NULL, NULL, 'a0f878b00b3d874b0d589969033c9d9384d3b2033fa0d6bfaae7d86fb8276742'),
  ('en.sahih', 17, 45, 2074, 'And when you recite the Qur''an, We put between you and those who do not believe in the Hereafter a concealed partition.', NULL, NULL, '1f29c9bdc28e56deef57650c94243bf2af3cb0a4f70912d7f165e731199a8972'),
  ('en.sahih', 17, 46, 2075, 'And We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And when you mention your Lord alone in the Qur''an, they turn back in aversion.', NULL, NULL, '89932db43873f2c370c7c4c8ad5cd4437dec62cadd90db47473c52df21ab34d9'),
  ('en.sahih', 17, 47, 2076, 'We are most knowing of how they listen to it when they listen to you and [of] when they are in private conversation, when the wrongdoers say, "You follow not but a man affected by magic."', NULL, NULL, '6067d3d59151912fda01dde686d7732948809d3c600a60e2449411ccced54e87'),
  ('en.sahih', 17, 48, 2077, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', NULL, NULL, '25081411324145bc8b440d707de279d6aaaf375c8b4eb3625fe72f5c60ddf4c6'),
  ('en.sahih', 17, 49, 2078, 'And they say, "When we are bones and crumbled particles, will we [truly] be resurrected as a new creation?"', NULL, NULL, '7cb8af525b0cb5502514c8fd451a53cc35cb9638841e71b81535f35c3a3bc814'),
  ('en.sahih', 17, 50, 2079, 'Say, "Be you stones or iron', NULL, NULL, 'e0454f5138cb2777b3e84604831753cfcaa69978a4eaec0b64bfd56f6517b634'),
  ('en.sahih', 17, 51, 2080, 'Or [any] creation of that which is great within your breasts." And they will say, "Who will restore us?" Say, "He who brought you forth the first time." Then they will nod their heads toward you and say, "When is that?" Say, "Perhaps it will be soon -', NULL, NULL, 'a577b13e665fdb3fd66d9309e4c19016ff023132626e68441cd2c061d18fb4aa'),
  ('en.sahih', 17, 52, 2081, 'On the Day He will call you and you will respond with praise of Him and think that you had not remained [in the world] except for a little."', NULL, NULL, 'e307ebfbb41bb2476eee7e3430b2a87a2b325cd25619d227d053e5a78dfc47c2'),
  ('en.sahih', 17, 53, 2082, 'And tell My servants to say that which is best. Indeed, Satan induces [dissension] among them. Indeed Satan is ever, to mankind, a clear enemy.', NULL, NULL, '8046977736b239e8a44528389f870cd4f7bdaa008dc02e8ac7511310ca4c1407'),
  ('en.sahih', 17, 54, 2083, 'Your Lord is most knowing of you. If He wills, He will have mercy upon you; or if He wills, He will punish you. And We have not sent you, [O Muhammad], over them as a manager.', NULL, NULL, 'd37b9ea47101de70505092802719f0b406458d6af8c47337fe0c017a9d2eaff9'),
  ('en.sahih', 17, 55, 2084, 'And your Lord is most knowing of whoever is in the heavens and the earth. And We have made some of the prophets exceed others [in various ways], and to David We gave the book [of Psalms].', NULL, NULL, '29b2e8ae4534638d55ab74e486051ecf9fea18bb1b94705fdadba26f2c1108c7'),
  ('en.sahih', 17, 56, 2085, 'Say, "Invoke those you have claimed [as gods] besides Him, for they do not possess the [ability for] removal of adversity from you or [for its] transfer [to someone else]."', NULL, NULL, 'd7cc373fda57109ecf412412793e628d6496932a1db48d0dda7b1a45d22d2b5f'),
  ('en.sahih', 17, 57, 2086, 'Those whom they invoke seek means of access to their Lord, [striving as to] which of them would be nearest, and they hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is ever feared.', NULL, NULL, '28a92534c0ea82d8593177bb399334d40253606df3307c9b6806bf7317d537ed'),
  ('en.sahih', 17, 58, 2087, 'And there is no city but that We will destroy it before the Day of Resurrection or punish it with a severe punishment. That has ever been in the Register inscribed.', NULL, NULL, 'bc1994473ebda5048343f5ddb6469e924ffae21fce7cb84736d568542adc33c8'),
  ('en.sahih', 17, 59, 2088, 'And nothing has prevented Us from sending signs except that the former peoples denied them. And We gave Thamud the she-camel as a visible sign, but they wronged her. And We send not the signs except as a warning.', NULL, NULL, 'cb6b68706c71efa8ec04c2e16085bcd0c113484a83425d8baa26fafb4face5b6'),
  ('en.sahih', 17, 60, 2089, 'And [remember, O Muhammad], when We told you, "Indeed, your Lord has encompassed the people." And We did not make the sight which We showed you except as a trial for the people, as was the accursed tree [mentioned] in the Qur''an. And We threaten them, but it increases them not except in great transgression.', NULL, NULL, '8c8a2e5c377b93f98de86678c6fbc7f503120bb165e11aed46f36a3f270d4865'),
  ('en.sahih', 17, 61, 2090, 'And [mention] when We said to the angles, "Prostrate to Adam," and they prostrated, except for Iblees. He said, "Should I prostrate to one You created from clay?"', NULL, NULL, '276a11bc756e3ef4bf500ed104b280aa2400155366c50ea88c180d1a92d62651'),
  ('en.sahih', 17, 62, 2091, '[Iblees] said, "Do You see this one whom You have honored above me? If You delay me until the Day of Resurrection, I will surely destroy his descendants, except for a few."', NULL, NULL, 'e29146d8331bd6b942cb6177f56405e24e339f7a54815f1838f109e9594f0018'),
  ('en.sahih', 17, 63, 2092, '[Allah] said, "Go, for whoever of them follows you, indeed Hell will be the recompense of you - an ample recompense.', NULL, NULL, 'e8195c5b2dbcae997772a01e5c664fbf8f7129dc603a9c95f40857f5441a8941'),
  ('en.sahih', 17, 64, 2093, 'And incite [to senselessness] whoever you can among them with your voice and assault them with your horses and foot soldiers and become a partner in their wealth and their children and promise them." But Satan does not promise them except delusion.', NULL, NULL, '1fd0052f28078a7d9d32b3ccce918ca3a8bc5faa8f694153e3802559e122b1b9'),
  ('en.sahih', 17, 65, 2094, 'Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs.', NULL, NULL, '5660c3a67bba75d7043dd11525f393fd53edf0a7c40e72580b735e94512e2717'),
  ('en.sahih', 17, 66, 2095, 'It is your Lord who drives the ship for you through the sea that you may seek of His bounty. Indeed, He is ever, to you, Merciful.', NULL, NULL, 'c9dcc467e1c9dab5dd418e0c0fafcb9f4e608deb63877416d402a6ae5e34cce5'),
  ('en.sahih', 17, 67, 2096, 'And when adversity touches you at sea, lost are [all] those you invoke except for Him. But when He delivers you to the land, you turn away [from Him]. And ever is man ungrateful.', NULL, NULL, '744e00500a97d06e0455a3e06f20dc7d1175adda76f58e85b7a4f2d32e035d72'),
  ('en.sahih', 17, 68, 2097, 'Then do you feel secure that [instead] He will not cause a part of the land to swallow you or send against you a storm of stones? Then you would not find for yourselves an advocate.', NULL, NULL, 'd7f82c25350733aeccd6f7251df677c4d032ded96641909bff989b9a606e5484'),
  ('en.sahih', 17, 69, 2098, 'Or do you feel secure that He will not send you back into the sea another time and send upon you a hurricane of wind and drown you for what you denied? Then you would not find for yourselves against Us an avenger.', NULL, NULL, '745ffdc6a4659cfc48a23845e87ac6afcfbfc25e6d7a591ddaf4ba33a0ad5d65'),
  ('en.sahih', 17, 70, 2099, 'And We have certainly honored the children of Adam and carried them on the land and sea and provided for them of the good things and preferred them over much of what We have created, with [definite] preference.', NULL, NULL, '8ab6a11ab0aee4fb1bbf113aed561500dda7b24c177bf98f45de0bc7c0adf0e0'),
  ('en.sahih', 17, 71, 2100, '[Mention, O Muhammad], the Day We will call forth every people with their record [of deeds]. Then whoever is given his record in his right hand - those will read their records, and injustice will not be done to them, [even] as much as a thread [inside the date seed].', NULL, NULL, '428dc2ede60a1c743997153d6c108084ff9a087c642de1d5ef7c6437c7ed2f74')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 17, 72, 2101, 'And whoever is blind in this [life] will be blind in the Hereafter and more astray in way.', NULL, NULL, 'd0e456541d6e8a54e80333354f5e981aae20e57d926c7ce21465d1fec9b454d2'),
  ('en.sahih', 17, 73, 2102, 'And indeed, they were about to tempt you away from that which We revealed to you in order to [make] you invent about Us something else; and then they would have taken you as a friend.', NULL, NULL, '0129e3ab226814d79e232aa9e729a40f2b024fc3b2d993f4edda947bed31d90d'),
  ('en.sahih', 17, 74, 2103, 'And if We had not strengthened you, you would have almost inclined to them a little.', NULL, NULL, '88c8f4f5e555a78058e3b600252c6ff9a0338ab4a44fa42138c10415f05552ce'),
  ('en.sahih', 17, 75, 2104, 'Then [if you had], We would have made you taste double [punishment in] life and double [after] death. Then you would not find for yourself against Us a helper.', NULL, NULL, 'c0eebbdd5e6ae5c5a36f1ab14024e6922e16062456c80735136769a400941cc8'),
  ('en.sahih', 17, 76, 2105, 'And indeed, they were about to drive you from the land to evict you therefrom. And then [when they do], they will not remain [there] after you, except for a little.', NULL, NULL, '64c5b7ae9edbff34a2724b6e26beabc6a4047f2bc09b6eadb9e7050de2bae05c'),
  ('en.sahih', 17, 77, 2106, '[That is Our] established way for those We had sent before you of Our messengers; and you will not find in Our way any alteration.', NULL, NULL, '248296579275faa6a7b9844128dd0a68dd8912703f0110b8504eb252604222b1'),
  ('en.sahih', 17, 78, 2107, 'Establish prayer at the decline of the sun [from its meridian] until the darkness of the night and [also] the Qur''an of dawn. Indeed, the recitation of dawn is ever witnessed.', NULL, NULL, 'ac221ed4e3ea48221d1f8d586450d8a2aa3c0a6d03e90b9c1103bede133b99f8'),
  ('en.sahih', 17, 79, 2108, 'And from [part of] the night, pray with it as additional [worship] for you; it is expected that your Lord will resurrect you to a praised station.', NULL, NULL, 'bc4eeec00f63d339b817ced4fe988a7b59ef9d1493d268dbcdd71da02581b42e'),
  ('en.sahih', 17, 80, 2109, 'And say, "My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority."', NULL, NULL, '34b4583f9e75a802dab8d40b916497d869a98dee5d887ab06fedb7312194d5f9'),
  ('en.sahih', 17, 81, 2110, 'And say, "Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart."', NULL, NULL, '0127536c7f88a745b41022f607090f9cf1710fd5ce22cf555a341ecb8a9d3210'),
  ('en.sahih', 17, 82, 2111, 'And We send down of the Qur''an that which is healing and mercy for the believers, but it does not increase the wrongdoers except in loss.', NULL, NULL, 'dd55cf7ba730a60f70d8336842ac5831e099f54a5ddedbcee369c90041f1dd61'),
  ('en.sahih', 17, 83, 2112, 'And when We bestow favor upon the disbeliever, he turns away and distances himself; and when evil touches him, he is ever despairing.', NULL, NULL, '3759a360f4f5c60feae43f43eb6badff4c4d6d31dd8b1305c347c8a15fb0df6d'),
  ('en.sahih', 17, 84, 2113, 'Say, "Each works according to his manner, but your Lord is most knowing of who is best guided in way."', NULL, NULL, '7983f2cf1b48762bb7341619f0d921a5396fc4ed3ce5f89bb5be6f44c582d7a9'),
  ('en.sahih', 17, 85, 2114, 'And they ask you, [O Muhammad], about the soul. Say, "The soul is of the affair of my Lord. And mankind have not been given of knowledge except a little."', NULL, NULL, '48e2a231f8398b5c6624b2d7af7cb87808e81b5b5b8efc46f8f208b4d6071d63'),
  ('en.sahih', 17, 86, 2115, 'And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us.', NULL, NULL, '016293f1dccf409686511be036ea264c5a9521bd274db0294aab2d1488e4ed33'),
  ('en.sahih', 17, 87, 2116, 'Except [We have left it with you] as a mercy from your Lord. Indeed, His favor upon you has ever been great.', NULL, NULL, '25e24006a35df5dfa4aedbfb41ac0aae07018e940dcb52b10e5c367c2e28206b'),
  ('en.sahih', 17, 88, 2117, 'Say, "If mankind and the jinn gathered in order to produce the like of this Qur''an, they could not produce the like of it, even if they were to each other assistants."', NULL, NULL, '84509bd889808560ef40854285b1c3a9962186af64f73c9735404a0e002c3572'),
  ('en.sahih', 17, 89, 2118, 'And We have certainly diversified for the people in this Qur''an from every [kind] of example, but most of the people refused [anything] except disbelief.', NULL, NULL, 'a02a2771bd53f04a9570c61bc5e67fc9470b97cf0ada2078285451f0aec90636'),
  ('en.sahih', 17, 90, 2119, 'And they say, "We will not believe you until you break open for us from the ground a spring.', NULL, NULL, '723b76ab906fd39acd8423fa99c945f10051f41321b0476f81f7036094c61a75'),
  ('en.sahih', 17, 91, 2120, 'Or [until] you have a garden of palm tress and grapes and make rivers gush forth within them in force [and abundance]', NULL, NULL, '80f3b924fcb41b615c1d83ffee2000ea9bd043d112cd40e0421a92a4b77d3ffd'),
  ('en.sahih', 17, 92, 2121, 'Or you make the heaven fall upon us in fragments as you have claimed or you bring Allah and the angels before [us]', NULL, NULL, '99b82264379d9dbb3859e3ac5ba0140a01c97a17b664fea62c94a2353ce0dec7'),
  ('en.sahih', 17, 93, 2122, 'Or you have a house of gold or you ascend into the sky. And [even then], we will not believe in your ascension until you bring down to us a book we may read." Say, "Exalted is my Lord! Was I ever but a human messenger?"', NULL, NULL, '98531776d601d77ff6467235adb3cbac629e9f1fdf639b3300dd3d7c56f981ae'),
  ('en.sahih', 17, 94, 2123, 'And what prevented the people from believing when guidance came to them except that they said, "Has Allah sent a human messenger?"', NULL, NULL, 'abea5d9fe698e678b817af50dd3776e07c1a2775ff832cce862b0334e12739e2'),
  ('en.sahih', 17, 95, 2124, 'Say, "If there were upon the earth angels walking securely, We would have sent down to them from the heaven an angel [as a] messenger."', NULL, NULL, 'c03ddec5c894852ff1a492c3e64c04f19937159a5595566f2ff7e263cefaac82'),
  ('en.sahih', 17, 96, 2125, 'Say, "Sufficient is Allah as Witness between me and you. Indeed he is ever, concerning His servants, Acquainted and Seeing."', NULL, NULL, '4fa6735c3677d0a1fac5f6e01abe213aa9c224d20dd80f20dddfe5c1733359dc'),
  ('en.sahih', 17, 97, 2126, 'And whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - you will never find for them protectors besides Him, and We will gather them on the Day of Resurrection [fallen] on their faces - blind, dumb and deaf. Their refuge is Hell; every time it subsides We increase them in blazing fire.', NULL, NULL, '932f0443ba01321d1a8b35f8da05aef851a713bd1812de1f400d26d5073def60'),
  ('en.sahih', 17, 98, 2127, 'That is their recompense because they disbelieved in Our verses and said, "When we are bones and crumbled particles, will we [truly] be resurrected [in] a new creation?"', NULL, NULL, '225d5423ae11f31e01bea54e4df1b3a35b0d709f464e3ea0c4a5d6cfd741de10'),
  ('en.sahih', 17, 99, 2128, 'Do they not see that Allah, who created the heavens and earth, is [the one] Able to create the likes of them? And He has appointed for them a term, about which there is no doubt. But the wrongdoers refuse [anything] except disbelief.', NULL, NULL, 'bae21ba0010ed60276128c46f867ee97ce417008cae2702653ad7dec1904c7d1'),
  ('en.sahih', 17, 100, 2129, 'Say [to them], "If you possessed the depositories of the mercy of my Lord, then you would withhold out of fear of spending." And ever has man been stingy.', NULL, NULL, '3fcc4af383edd52770fb6e13a2ce4ee198cb60d0350a1f82a41811aaf28dd153'),
  ('en.sahih', 17, 101, 2130, 'And We had certainly given Moses nine evident signs, so ask the Children of Israel [about] when he came to them and Pharaoh said to him, "Indeed I think, O Moses, that you are affected by magic."', NULL, NULL, 'cca7b3434367580f0bd8dc28bf3359a921ed99e830bb8f7f3a5c858b51f94642'),
  ('en.sahih', 17, 102, 2131, '[Moses] said, "You have already known that none has sent down these [signs] except the Lord of the heavens and the earth as evidence, and indeed I think, O Pharaoh, that you are destroyed."', NULL, NULL, '9a8b1de2ef478c62866a03614ced29a61542c1f24495c7ae5a04c598dfc3f8fb'),
  ('en.sahih', 17, 103, 2132, 'So he intended to drive them from the land, but We drowned him and those with him all together.', NULL, NULL, '01d1d7f21fee9f2f835b55f3861fe8c4732135e38fbd71a228887c20a5f55cd8'),
  ('en.sahih', 17, 104, 2133, 'And We said after Pharaoh to the Children of Israel, "Dwell in the land, and when there comes the promise of the Hereafter, We will bring you forth in [one] gathering."', NULL, NULL, '5e9704305c6f0eacbe25fc2235c48b77417ef621082b29e7ea69bed583a90826'),
  ('en.sahih', 17, 105, 2134, 'And with the truth We have sent the Qur''an down, and with the truth it has descended. And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.', NULL, NULL, 'bd3eea461abc463d22174a2729201186903c288946b0ca2b086ba76f127e85b0'),
  ('en.sahih', 17, 106, 2135, 'And [it is] a Qur''an which We have separated [by intervals] that you might recite it to the people over a prolonged period. And We have sent it down progressively.', NULL, NULL, '678bda442864db713932b60cc8829895829342867141a92dacc656683cd35e34'),
  ('en.sahih', 17, 107, 2136, 'Say, "Believe in it or do not believe. Indeed, those who were given knowledge before it - when it is recited to them, they fall upon their faces in prostration,', NULL, NULL, '6d2e21395b198ba84a6307529aae710e0d635dcc884aecbb6719c719e77e4986'),
  ('en.sahih', 17, 108, 2137, 'And they say, "Exalted is our Lord! Indeed, the promise of our Lord has been fulfilled."', NULL, NULL, 'e5eb63f4d024e674348a496d6cd56265bba385a45702fd2a3d048a82a841e38f'),
  ('en.sahih', 17, 109, 2138, 'And they fall upon their faces weeping, and the Qur''an increases them in humble submission.', NULL, NULL, '32aadf469902eefff826203563c3b8d7428c1e24108b4e236bd94cdf0dce81f2'),
  ('en.sahih', 17, 110, 2139, 'Say, "Call upon Allah or call upon the Most Merciful. Whichever [name] you call - to Him belong the best names." And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way.', NULL, NULL, '2f8904590b0abbac7be7502af4fbd336b0c700d682af6e521ed88084cb823013'),
  ('en.sahih', 17, 111, 2140, 'And say, "Praise to Allah, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification."', NULL, NULL, '26bd36e40d9eb59655c65cf405b2d7d5df749126e30182847ab1a8e672743823'),
  ('en.sahih', 18, 1, 2141, '[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance.', NULL, NULL, '4003d6b162c67e58cd17fa2aa6a90ad93d342837c769bcd3432bf773e5448651'),
  ('en.sahih', 18, 2, 2142, '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward', NULL, NULL, 'b93e67b6e03b8f498de6e943fe52b763dd7486aa5bace640f27e302662fe7b79'),
  ('en.sahih', 18, 3, 2143, 'In which they will remain forever', NULL, NULL, '866bb5e775279abda72ead85f1dcf73023e5af94f68c12687c04b0b2950befce'),
  ('en.sahih', 18, 4, 2144, 'And to warn those who say, "Allah has taken a son."', NULL, NULL, 'e8e11eda62647b11a1d435cd89247b417f506e056ee80d77aa1614fcf722ed5c'),
  ('en.sahih', 18, 5, 2145, 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.', NULL, NULL, '33d8955762a66cba9be6171c5497bc1c7c726737ef5eddb347df831deec01b17'),
  ('en.sahih', 18, 6, 2146, 'Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow.', NULL, NULL, 'c92808a572a69f29d9912bb1f4c51832a40575c51d74711e09f624763b3c000b'),
  ('en.sahih', 18, 7, 2147, 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.', NULL, NULL, '75e0d5eb489cb4697a88c4121415a23a968f1a871d7ce468ef9b146cc67809a9'),
  ('en.sahih', 18, 8, 2148, 'And indeed, We will make that which is upon it [into] a barren ground.', NULL, NULL, '5421135205641b6379e253e820d344ce6f5ed2a43f83fe1183b641b46e69be39'),
  ('en.sahih', 18, 9, 2149, 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?', NULL, NULL, '59dc8db062faafaa433e94515009fab0762591611799106e324f6bb6d2387776'),
  ('en.sahih', 18, 10, 2150, '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."', NULL, NULL, 'd852d64722e448e6d8284bbe1e978c990546a968bc02d6a7c7b47dca0e143f1e'),
  ('en.sahih', 18, 11, 2151, 'So We cast [a cover of sleep] over their ears within the cave for a number of years.', NULL, NULL, '38b858d0009b1c85754913f14cf1b5f7e14dc48171e00e51a0ae4a20a181f7c6'),
  ('en.sahih', 18, 12, 2152, 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.', NULL, NULL, '468a80a6ce67415a6786163a9838b4935ec138712a9cd4c1393a301606ee738a'),
  ('en.sahih', 18, 13, 2153, 'It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.', NULL, NULL, '46282ee2959e2f6d1798936cac33ba3fd1af9abfd6f204568501939051b61f13'),
  ('en.sahih', 18, 14, 2154, 'And We made firm their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.', NULL, NULL, '9d733d5f3b0721827a03ae79c23b4c2e8b788bfbf90c13c91dc5b35eca16aa1b'),
  ('en.sahih', 18, 15, 2155, 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?"', NULL, NULL, '1189ec1b29e5d364857e093baf6fdac934e4d9d21f40a2f509be713657d21443'),
  ('en.sahih', 18, 16, 2156, '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."', NULL, NULL, 'cc29d3cb7869718420791ab4bd02e5bb37cd93ee1a4d1047823d11b206ca955f'),
  ('en.sahih', 18, 17, 2157, 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide.', NULL, NULL, '39217163ce369e5967edf947728c814a503fd8c265840586ef394e0a51deb8eb'),
  ('en.sahih', 18, 18, 2158, 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.', NULL, NULL, 'd0414493ada21216b53bab3652cb842f5f11434fd5c0a701df71911ba83a1226'),
  ('en.sahih', 18, 19, 2159, 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.', NULL, NULL, '4a5280c42da01c45a287d4a804cf486712083525c3b13e1d5f261b5a28345a48'),
  ('en.sahih', 18, 20, 2160, 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."', NULL, NULL, '93f52e293b5c7083a1dbb8cd77849d9bdec3cad89876f8d510d665574c65dba5'),
  ('en.sahih', 18, 21, 2161, 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."', NULL, NULL, '66861145f827e2a0b7e9cddc236b6c298016ac1397caa62b388ec8907e0063df'),
  ('en.sahih', 18, 22, 2162, 'They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."', NULL, NULL, '39be42342de0993c5c2aaecc3c4b9679a9028efe1063d4730e192fd3be570745'),
  ('en.sahih', 18, 23, 2163, 'And never say of anything, "Indeed, I will do that tomorrow,"', NULL, NULL, '413969cf13049d3d92d350f41ec7be195856af57ae1f6880fc49540fe1731f53'),
  ('en.sahih', 18, 24, 2164, 'Except [when adding], "If Allah wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."', NULL, NULL, '57e05aad3d676795df317d4d3cd3c5cd5581777c4e4c848c5da8e78bab7148c4'),
  ('en.sahih', 18, 25, 2165, 'And they remained in their cave for three hundred years and exceeded by nine.', NULL, NULL, '085b42d779e35ac3c4072e427aa700f8dcd3dd73d350bc082f34ee8007769efd'),
  ('en.sahih', 18, 26, 2166, 'Say, "Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."', NULL, NULL, '63f2730ab12298aaa31c8b38d706a1a1043b3d44c02797faf1404ae57da53254'),
  ('en.sahih', 18, 27, 2167, 'And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.', NULL, NULL, '8835be771fbfa07fba6c1568e4f13dcea3481bd216b29785c36d35f921c1563d'),
  ('en.sahih', 18, 28, 2168, 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.', NULL, NULL, '88f3a1c00920521211a03bea099f3470e4b934cdac576917ef3785d88e753d50'),
  ('en.sahih', 18, 29, 2169, 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.', NULL, NULL, 'e5387bbd220be21a28f2567d5a51d4af788b2392e68d4e651d65373e36790280'),
  ('en.sahih', 18, 30, 2170, 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.', NULL, NULL, 'c5120281b86f98be2f69ac6110b875b249224f4775ce91b4b3c2a978b48200be'),
  ('en.sahih', 18, 31, 2171, 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.', NULL, NULL, '3824a174f66082b0604dc31c3b531a9c5c910ad4029c921c7513eed20d4d3657'),
  ('en.sahih', 18, 32, 2172, 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.', NULL, NULL, 'b2c8a499fd6081708f1d2a0bf275cffc2ad7c62fd631a0a80ad36338fda0bc53'),
  ('en.sahih', 18, 33, 2173, 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.', NULL, NULL, '36f08eb7fd5571588d73b6f0e878c997de603ca77c3c0e8a6581b1bd3b6e9361'),
  ('en.sahih', 18, 34, 2174, 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."', NULL, NULL, 'd45bdd5c0a634543fa48151aee18356bb9c86828624d60559b2da3844315b6dd'),
  ('en.sahih', 18, 35, 2175, 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.', NULL, NULL, '5caeb84104e456e68918123a256630254c143ac7db881a51b77cfc9de8c3d50d'),
  ('en.sahih', 18, 36, 2176, 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."', NULL, NULL, 'e5bac33992f775785c56ac5d2c5db58a34b1fe804c80850946c2eb7e4dfc1a9f'),
  ('en.sahih', 18, 37, 2177, 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?', NULL, NULL, 'c738b24ca601d64034e62c2e49d111d1a627ead1709c48a827f0399e25a31863'),
  ('en.sahih', 18, 38, 2178, 'But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone.', NULL, NULL, '4378b87d4fc7b2f59f732f5af51d1ef9e90789f37a101b25288ee542415685f6'),
  ('en.sahih', 18, 39, 2179, 'And why did you, when you entered your garden, not say, ''What Allah willed [has occurred]; there is no power except in Allah ''? Although you see me less than you in wealth and children,', NULL, NULL, '08102f23b8e4e2249c6a8f732477ca0e6f84bb30fc3e917ed28e5860301c0747'),
  ('en.sahih', 18, 40, 2180, 'It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,', NULL, NULL, 'a1d8bb95b97118a20c6dbf55ebbfc8ba3f19f0e1d5e672c306772c6d57dcea53'),
  ('en.sahih', 18, 41, 2181, 'Or its water will become sunken [into the earth], so you would never be able to seek it."', NULL, NULL, 'ba6ee7df67eb80bbc94f58249cf27d628416c078aca7822df6b5cfda3413c47c'),
  ('en.sahih', 18, 42, 2182, 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."', NULL, NULL, 'f55048c6f0b9ea593591e28907cc76f0b52db43492a6e3e4d89ca7f4ace7cd5f'),
  ('en.sahih', 18, 43, 2183, 'And there was for him no company to aid him other than Allah, nor could he defend himself.', NULL, NULL, 'b97ceecfe09c02a18b85b074de292bff464a0d0615b82a809328a37a25ef3b32'),
  ('en.sahih', 18, 44, 2184, 'There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome.', NULL, NULL, '17722f7296a65fef40c9adba803a7d7699a4b8efd2554835c1886e34554a8a8f'),
  ('en.sahih', 18, 45, 2185, 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability.', NULL, NULL, '4696fe72325c41ca9cf84a8d6c2d0607bd51fbbef83ba506980071b180ad524b'),
  ('en.sahih', 18, 46, 2186, 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one''s] hope.', NULL, NULL, '44b2bf5db88915eb9e86fce31d633ba1a032fd71d9be3c58fb82fc2779704582'),
  ('en.sahih', 18, 47, 2187, 'And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone.', NULL, NULL, 'aaeb55b8aa0f9be765810fe48ccb29fbe7d72a26cd6771f6db1e29b83612f8a9'),
  ('en.sahih', 18, 48, 2188, 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."', NULL, NULL, 'ca2215a0ec5836f7e98a32d8dfd56159ccefaa3379587f0c06928de511b5bc51'),
  ('en.sahih', 18, 49, 2189, 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.', NULL, NULL, 'b1fbb3fbf2af7da1fce4e83a85870426454848186d04925c3e85025d799afff9'),
  ('en.sahih', 18, 50, 2190, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.', NULL, NULL, '281eaa496162832fe3d7d9303ebc0779335ec6acc5b13e708787bd0e2d2ece4d'),
  ('en.sahih', 18, 51, 2191, 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.', NULL, NULL, 'ca6541ca47b616567389f1606922feb4ec1dc7872cedfc02d39911cb2213b61e'),
  ('en.sahih', 18, 52, 2192, 'And [warn of] the Day when He will say, "Call ''My partners'' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.', NULL, NULL, '510c3bd38f52b8f8bed88b081d21112e320da0b38dd8e7ab32788fbc8e8ecc84'),
  ('en.sahih', 18, 53, 2193, 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.', NULL, NULL, 'd7957c6120d5b3325340f61cf68d2fedd60d37d542ca8cb27499dfaf5f21deb1'),
  ('en.sahih', 18, 54, 2194, 'And We have certainly diversified in this Qur''an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.', NULL, NULL, '5ddab83a3d1d16366f71dc537fafd678632c44afcc6d6b88805551c2888163d6'),
  ('en.sahih', 18, 55, 2195, 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.', NULL, NULL, '7d3684580265861098161ec7413f9ad74df236544d4026962cdd1f05486868bc'),
  ('en.sahih', 18, 56, 2196, 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.', NULL, NULL, '256a23dc537ce050d46e60ae3bdc921eb25e016abbc297062e49c67db569b812'),
  ('en.sahih', 18, 57, 2197, 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.', NULL, NULL, '91cd31d07c223ece77e5cae839080c0b378997516ebe23dd6a713541441db014'),
  ('en.sahih', 18, 58, 2198, 'And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.', NULL, NULL, 'd38671298ee4bb28090afd2fa371196b2ee6188cefba45d14719a7abef7395d2'),
  ('en.sahih', 18, 59, 2199, 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.', NULL, NULL, 'b1efee4e1a7da81aedcba0c8ccb57313a003e89ce4916b7f5a6f6572bbfd8078'),
  ('en.sahih', 18, 60, 2200, 'And [mention] when Moses said to his servant, "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."', NULL, NULL, 'f9bbc29adcb32bd8abf395088947bebaa0cfa470011d65f19d75b8c03f5422fc')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 18, 61, 2201, 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.', NULL, NULL, '7bfc052a87b3e5d446820824b61d8bd3853ce0cfd51d233df634126619c8d542'),
  ('en.sahih', 18, 62, 2202, 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."', NULL, NULL, '650119aef51e559c2d5398333b066a5ce2cddcf11d977e2f281cabd655da371d'),
  ('en.sahih', 18, 63, 2203, 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly".', NULL, NULL, '845c5cbe159a824717a4f278353ef78133a031c65cc3d4529650dab90f7646df'),
  ('en.sahih', 18, 64, 2204, '[Moses] said, "That is what we were seeking." So they returned, following their footprints.', NULL, NULL, 'cacf0d80db354778e3c81657649fe340d1f8cef483b1389b598f9a23a6567eb0'),
  ('en.sahih', 18, 65, 2205, 'And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.', NULL, NULL, '8e6ad47329fc0d16f15ada9774d51a251e3194266cc36a93540ee654bfbed284'),
  ('en.sahih', 18, 66, 2206, 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"', NULL, NULL, 'f8dc264be192825e684278f0b9cc2828f038b6ab91e081001d570f30e49a47f3'),
  ('en.sahih', 18, 67, 2207, 'He said, "Indeed, with me you will never be able to have patience.', NULL, NULL, '7cad0aa3681592b20ae4cfd07c5234ee31d6f43c8afaa6e600be81e087aa3111'),
  ('en.sahih', 18, 68, 2208, 'And how can you have patience for what you do not encompass in knowledge?"', NULL, NULL, '271ebdba3f7f5e884754b0ef67b3a88ee330b00725b1651d033af532e57d16f0'),
  ('en.sahih', 18, 69, 2209, '[Moses] said, "You will find me, if Allah wills, patient, and I will not disobey you in [any] order."', NULL, NULL, 'cfc6eeedcaa7be54a1ef54465fe361d579b09ff5d54b5cbb854ed8973df5f517'),
  ('en.sahih', 18, 70, 2210, 'He said, "Then if you follow me, do not ask me about anything until I make to you about it mention."', NULL, NULL, 'df1c232f9a22ec343c13e5ee4a5d56545f4eb6d663a7d47139f5a25b4a19a8d7'),
  ('en.sahih', 18, 71, 2211, 'So they set out, until when they had embarked on the ship, al-Khidh r tore it open. [Moses] said, "Have you torn it open to drown its people? You have certainly done a grave thing."', NULL, NULL, 'cfcb4c6bcc608ac1373261f63d5b5ef284116967e3070e9e3c160272d95153e7'),
  ('en.sahih', 18, 72, 2212, '[Al-Khidh r] said, "Did I not say that with me you would never be able to have patience?"', NULL, NULL, 'a91edee07d2542af9dbfd36b5b535d8f1c0f66838c0620707e10fadd460a2617'),
  ('en.sahih', 18, 73, 2213, '[Moses] said, "Do not blame me for what I forgot and do not cover me in my matter with difficulty."', NULL, NULL, '866c9d82a3cafc4c2ed5b07beb4081ad7289c5d4502fef05708b0a6242ddb1fd'),
  ('en.sahih', 18, 74, 2214, 'So they set out, until when they met a boy, al-Khidh r killed him. [Moses] said, "Have you killed a pure soul for other than [having killed] a soul? You have certainly done a deplorable thing."', NULL, NULL, '8a860f5d5baf5d7608ad652225d673f1dd66443f54f109c156e83a47dcd2ccca'),
  ('en.sahih', 18, 75, 2215, '[Al-Khidh r] said, "Did I not tell you that with me you would never be able to have patience?"', NULL, NULL, '816b30443cfd893067634fa1456554be4a8bff8bbfac3c353cbd0d7826c8a003'),
  ('en.sahih', 18, 76, 2216, '[Moses] said, "If I should ask you about anything after this, then do not keep me as a companion. You have obtained from me an excuse."', NULL, NULL, 'a90fb4af8295a669057a8ca30c641cd3a0bbd0dfdb8e53d2ccbdf7e061a1c91c'),
  ('en.sahih', 18, 77, 2217, 'So they set out, until when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. And they found therein a wall about to collapse, so al-Khidh r restored it. [Moses] said, "If you wished, you could have taken for it a payment."', NULL, NULL, 'b89f0ad2144d8fd32fece2eb5fe9fc80b16f9a902db06cf509816ca69fe1fe16'),
  ('en.sahih', 18, 78, 2218, '[Al-Khidh r] said, "This is parting between me and you. I will inform you of the interpretation of that about which you could not have patience.', NULL, NULL, 'c2a872838d19b7e403a7640541d7719b252c44f957acb6d3601b3e4b1f8525a8'),
  ('en.sahih', 18, 79, 2219, 'As for the ship, it belonged to poor people working at sea. So I intended to cause defect in it as there was after them a king who seized every [good] ship by force.', NULL, NULL, '4c5614a956c40a0f762fe73f0265e401b13fad03a08478aa8a846d2f5bde98cd'),
  ('en.sahih', 18, 80, 2220, 'And as for the boy, his parents were believers, and we feared that he would overburden them by transgression and disbelief.', NULL, NULL, 'bffb9af774c024a7c9f92d16601a07639bb8b3dfd4fb008f0953eb7530c59714'),
  ('en.sahih', 18, 81, 2221, 'So we intended that their Lord should substitute for them one better than him in purity and nearer to mercy.', NULL, NULL, '9a231d94929f77817446f8ad32dd27fdf8507bb27311f75f7b694e123b664b54'),
  ('en.sahih', 18, 82, 2222, 'And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure for them, and their father had been righteous. So your Lord intended that they reach maturity and extract their treasure, as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of that about which you could not have patience."', NULL, NULL, 'c3abf76ec6ad8b113dbbf5cf6b30ac0dd53539eefc6322bcd04c72f86d759267'),
  ('en.sahih', 18, 83, 2223, 'And they ask you, [O Muhammad], about Dhul-Qarnayn. Say, "I will recite to you about him a report."', NULL, NULL, '1314cd9904e3ffdc8d2bf8b99e80f95218d2afeb0c842f07c33de3829cdf104d'),
  ('en.sahih', 18, 84, 2224, 'Indeed We established him upon the earth, and We gave him to everything a way.', NULL, NULL, 'aa70cdcf07ab075c1ed9f04ea2c95631d08270393e7220020db78c0b9c8029ec'),
  ('en.sahih', 18, 85, 2225, 'So he followed a way', NULL, NULL, '77ffa505c6ecd0c0a8239b49ab1292dddfa0c949ba58cc0e834fd0eea89f4048'),
  ('en.sahih', 18, 86, 2226, 'Until, when he reached the setting of the sun, he found it [as if] setting in a spring of dark mud, and he found near it a people. Allah said, "O Dhul-Qarnayn, either you punish [them] or else adopt among them [a way of] goodness."', NULL, NULL, '979b57d72f8027f8fa18372efbf29eb6b011bf8dbb96a44fc9214ac74be8fc09'),
  ('en.sahih', 18, 87, 2227, 'He said, "As for one who wrongs, we will punish him. Then he will be returned to his Lord, and He will punish him with a terrible punishment.', NULL, NULL, '8b202e99d94e049b5febde4174f57680e02f269c9ffb9bb507b407cb542480be'),
  ('en.sahih', 18, 88, 2228, 'But as for one who believes and does righteousness, he will have a reward of Paradise, and we will speak to him from our command with ease."', NULL, NULL, '587084dac45eaf57d9aafba243d3185e85c128bbb8805d3c4baf3ed570878d30'),
  ('en.sahih', 18, 89, 2229, 'Then he followed a way', NULL, NULL, 'c1f9aae49ae6c08905399717f70c6bae40222d6f8265463fe544dfce06447504'),
  ('en.sahih', 18, 90, 2230, 'Until, when he came to the rising of the sun, he found it rising on a people for whom We had not made against it any shield.', NULL, NULL, '14261378cc3ae72c0961ceb77886ab063c965bc7816473fdf6e7103340083eab'),
  ('en.sahih', 18, 91, 2231, 'Thus. And We had encompassed [all] that he had in knowledge.', NULL, NULL, '6cd19d575b0c890bbe4ab16c2a755cb0fbc301fa53dee5ca66caca7741faa32e'),
  ('en.sahih', 18, 92, 2232, 'Then he followed a way', NULL, NULL, 'c1f9aae49ae6c08905399717f70c6bae40222d6f8265463fe544dfce06447504'),
  ('en.sahih', 18, 93, 2233, 'Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech.', NULL, NULL, '32f559e0c3b4624df71d634f590bc985f84a701c4b037c1142b9b26b1f97e8cc'),
  ('en.sahih', 18, 94, 2234, 'They said, "O Dhul-Qarnayn, indeed Gog and Magog are [great] corrupters in the land. So may we assign for you an expenditure that you might make between us and them a barrier?"', NULL, NULL, '78a179c41b9725fac62d06a23b53e24d0708d839091654ec626e328b043686b5'),
  ('en.sahih', 18, 95, 2235, 'He said, "That in which my Lord has established me is better [than what you offer], but assist me with strength; I will make between you and them a dam.', NULL, NULL, '599c6e5aa3e943718959ada980fcfeb9c2cd1712e13994e00b4fbc9cc8d46273'),
  ('en.sahih', 18, 96, 2236, 'Bring me sheets of iron" - until, when he had leveled [them] between the two mountain walls, he said, "Blow [with bellows]," until when he had made it [like] fire, he said, "Bring me, that I may pour over it molten copper."', NULL, NULL, '533e6c4bf071256acae003a9bef0d60e4b4b4ca6cd6131606a43d62cff0eef47'),
  ('en.sahih', 18, 97, 2237, 'So Gog and Magog were unable to pass over it, nor were they able [to effect] in it any penetration.', NULL, NULL, 'ca2783e0f3d83b6db13f6b53101cba9d38f70a4d455c1e768eeba827e243c553'),
  ('en.sahih', 18, 98, 2238, '[Dhul-Qarnayn] said, "This is a mercy from my Lord; but when the promise of my Lord comes, He will make it level, and ever is the promise of my Lord true."', NULL, NULL, '10cc949b9c15f8fc6a8521853309bd59558aaf8ed993af7983415b35a9fdcf59'),
  ('en.sahih', 18, 99, 2239, 'And We will leave them that day surging over each other, and [then] the Horn will be blown, and We will assemble them in [one] assembly.', NULL, NULL, '395b84ef7462fd637d9684e1179998a1a8880d5d1b6ee9e83a3a0df30a17e981'),
  ('en.sahih', 18, 100, 2240, 'And We will present Hell that Day to the Disbelievers, on display -', NULL, NULL, '269d610ee8ef10e9dee3dd1b0bc8c8183d46ba7956e8f1862f50268aaf8fb345'),
  ('en.sahih', 18, 101, 2241, 'Those whose eyes had been within a cover [removed] from My remembrance, and they were not able to hear.', NULL, NULL, 'd7194c57e75b2a9cc0d572b0aca4caab2a0de60b80051808cf5fd79463a6a6a1'),
  ('en.sahih', 18, 102, 2242, 'Then do those who disbelieve think that they can take My servants instead of Me as allies? Indeed, We have prepared Hell for the disbelievers as a lodging.', NULL, NULL, 'df0cd981dd062292ee598c5aedf303987b6f3557d36482b31cbd335beaed7c97'),
  ('en.sahih', 18, 103, 2243, 'Say, [O Muhammad], "Shall we [believers] inform you of the greatest losers as to [their] deeds?', NULL, NULL, '26f055398207bd208d79c3ea94440c6d73b23205aef6e45349b8854c6c10e996'),
  ('en.sahih', 18, 104, 2244, '[They are] those whose effort is lost in worldly life, while they think that they are doing well in work."', NULL, NULL, 'd2915df5771578b176803035b94c92678020a1ae3c21f7c44c4a0cb013dd8681'),
  ('en.sahih', 18, 105, 2245, 'Those are the ones who disbelieve in the verses of their Lord and in [their] meeting Him, so their deeds have become worthless; and We will not assign to them on the Day of Resurrection any importance.', NULL, NULL, '455e801a62e1678ded176e19cbe7b994f898c031a009dc8a9e94166a04419496'),
  ('en.sahih', 18, 106, 2246, 'That is their recompense - Hell - for what they denied and [because] they took My signs and My messengers in ridicule.', NULL, NULL, '46c722853ac6bf487bce4723d2010aa3c4b9b59424a8631bb439973120fb6714'),
  ('en.sahih', 18, 107, 2247, 'Indeed, those who have believed and done righteous deeds - they will have the Gardens of Paradise as a lodging,', NULL, NULL, '3187be442184fac58725fde5922450cd42e41e97ef1abd49b5240d1ff188d55d'),
  ('en.sahih', 18, 108, 2248, 'Wherein they abide eternally. They will not desire from it any transfer.', NULL, NULL, 'eb115cc40b8fe40b103f896079f8038c6e834a44d6e2aef280baa2981b12133e'),
  ('en.sahih', 18, 109, 2249, 'Say, "If the sea were ink for [writing] the words of my Lord, the sea would be exhausted before the words of my Lord were exhausted, even if We brought the like of it as a supplement."', NULL, NULL, '4bf371c16a453052b895510c0818dad4e5d018962661fd056cec8a0173503d7f'),
  ('en.sahih', 18, 110, 2250, 'Say, "I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone."', NULL, NULL, '58bf98b2134eb2f759918a1f5fc63fbe1dccbc86104506176492813453393db4'),
  ('en.sahih', 19, 1, 2251, 'Kaf, Ha, Ya, ''Ayn, Sad.', NULL, NULL, '170726ed6da0060d19d8e342ede2120fe5a3590e35e6d2a4f77b5259c9436550'),
  ('en.sahih', 19, 2, 2252, '[This is] a mention of the mercy of your Lord to His servant Zechariah', NULL, NULL, '4ea586f5ad3957dbbd55a6a46e013b24c27b30d7d6e62c6ebe652686200b4e96'),
  ('en.sahih', 19, 3, 2253, 'When he called to his Lord a private supplication.', NULL, NULL, '7dfffbc09965c768831dcd8408aefaf211fa6bd0ece8ceeee59506f90d3569db'),
  ('en.sahih', 19, 4, 2254, 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy.', NULL, NULL, '53154cdb7f420d7a53ca66a28ef6330f3044881f321f87d4f55d41d393eee7d0'),
  ('en.sahih', 19, 5, 2255, 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir', NULL, NULL, 'f32c58d78f2175368376ccef41839b7411232aac8f1d75e023b2817b4fb21044'),
  ('en.sahih', 19, 6, 2256, 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."', NULL, NULL, 'b6e517b85518466655e6fb4524a831198fc64770daae68e8c26f78e9f89492c7'),
  ('en.sahih', 19, 7, 2257, '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."', NULL, NULL, 'b90c394ef01bcbc69c47c06175a1eac9f0fce2da4ae9b72939a2953b50b78e54'),
  ('en.sahih', 19, 8, 2258, 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"', NULL, NULL, '6ee897579e814815dd842b2f01def2597e6ae3a2d528f5a2d1a77d349301e10e'),
  ('en.sahih', 19, 9, 2259, '[An angel] said, "Thus [it will be]; your Lord says, ''It is easy for Me, for I created you before, while you were nothing.'' "', NULL, NULL, '33953b09d32a2e42b88f4b3665546061e26fe8e2d47232f7643c33a86eaaf60f'),
  ('en.sahih', 19, 10, 2260, '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."', NULL, NULL, '2e5fcdaf4f568f3c1152df240c17c2845c8460451db100717a41c875d03ddfad'),
  ('en.sahih', 19, 11, 2261, 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon.', NULL, NULL, '0db0992f8f4b5c6ae74cbc2ee3ab7d6058b2f12394949415e6fb75a1363b7bd0'),
  ('en.sahih', 19, 12, 2262, '[Allah] said, "O John, take the Scripture with determination." And We gave him judgement [while yet] a boy', NULL, NULL, '70a6322e18649a9e8e3b7971257f17ea69b5e59abad0c8fab4f73f2185919155'),
  ('en.sahih', 19, 13, 2263, 'And affection from Us and purity, and he was fearing of Allah', NULL, NULL, '7f6987a5dad44d1f76a34a900449f9d52aed6c02162295efe11891dc51659178'),
  ('en.sahih', 19, 14, 2264, 'And dutiful to his parents, and he was not a disobedient tyrant.', NULL, NULL, '7a28b53d411c8f5c97fc48f6f4184000b5213c9945f1d980a7040084b7eb32e4'),
  ('en.sahih', 19, 15, 2265, 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.', NULL, NULL, 'a26247d7a2bea8fb8ec157cd6912a79abf964561c932b0557f501ecf9f9a47e5'),
  ('en.sahih', 19, 16, 2266, 'And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.', NULL, NULL, '45123896ddb39e37a79b170342267335a51df3a56d6187cc254a82ae5ccd78a2'),
  ('en.sahih', 19, 17, 2267, 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man.', NULL, NULL, '72684a6794af6e63f430767f14d003ad0720c0ea58e3773aee68fa6cd9d4b401'),
  ('en.sahih', 19, 18, 2268, 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah."', NULL, NULL, '290ce0deb5a531f9762e508cb9adee7f6abab4fba347e3f83459197724dd2125'),
  ('en.sahih', 19, 19, 2269, 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy."', NULL, NULL, 'b2cfc72a9acdfd770c89efae6fdc6f9bb1eb5298da479700df5e1aa96d573d53'),
  ('en.sahih', 19, 20, 2270, 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"', NULL, NULL, 'bf502335a19a053aa48fe66f84640a8a9af8d06ec231c7907e8a96df60164aff'),
  ('en.sahih', 19, 21, 2271, 'He said, "Thus [it will be]; your Lord says, ''It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.'' "', NULL, NULL, '38be52d0d68a6ba739509d27ce360a4cb513eca7de6c7931f291ae23b3e8c93d'),
  ('en.sahih', 19, 22, 2272, 'So she conceived him, and she withdrew with him to a remote place.', NULL, NULL, 'ab3c0f7a35111b4c53c70c58a61643fd310dd4ea0adfc4d8f29d91205726e648'),
  ('en.sahih', 19, 23, 2273, 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."', NULL, NULL, '9d6801780e4feab9baeb7f733ae23e32dacc7ca30ce8806e10e51a77fe76306a'),
  ('en.sahih', 19, 24, 2274, 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.', NULL, NULL, '5dc32ea732334c3620108748ee68949183fdcd626155b5496134a318e5709082'),
  ('en.sahih', 19, 25, 2275, 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.', NULL, NULL, 'f2cfcc5fe0c6163ce5fabd4bd42e4e5425b90e93cee49a649bd3b2cda968e9e3'),
  ('en.sahih', 19, 26, 2276, 'So eat and drink and be contented. And if you see from among humanity anyone, say, ''Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.'' "', NULL, NULL, 'a364879353d0db048823dd1f103cacdf45cf008a23b4b7eaefaa05555a562653'),
  ('en.sahih', 19, 27, 2277, 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.', NULL, NULL, 'ca25e73e629372ecba16f59403db86cb2ebe457341310eef93423030b1f1030c'),
  ('en.sahih', 19, 28, 2278, 'O sister of Aaron, your father was not a man of evil, nor was your mother unchaste."', NULL, NULL, '21e4587f424d3295b2eaea258e9c075a90f4a90040a219c431503d718ec90628'),
  ('en.sahih', 19, 29, 2279, 'So she pointed to him. They said, "How can we speak to one who is in the cradle a child?"', NULL, NULL, '79ccbdc78691ff0c0e6d0f617e20ec40c73c60b2766c01176b1c221ad4d0de8e'),
  ('en.sahih', 19, 30, 2280, '[Jesus] said, "Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.', NULL, NULL, '2fe8857c28c1c11972fa8df6014f4b682ae71b0d07c4c80e1edb6da8de9b81e8'),
  ('en.sahih', 19, 31, 2281, 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive', NULL, NULL, '58e027721e0b8044d8e99b2dc76fb089a969c13449d05d2747deffb3d7cefb9a'),
  ('en.sahih', 19, 32, 2282, 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.', NULL, NULL, '4e571dfde28704b2c9e856bf907901b920931b401d0a6f3feb8e084c1916fcf6'),
  ('en.sahih', 19, 33, 2283, 'And peace is on me the day I was born and the day I will die and the day I am raised alive."', NULL, NULL, 'ac4829ac4b7beb31aabfe6fbd5d23c09fe9555760a7875e7197ad51419112318'),
  ('en.sahih', 19, 34, 2284, 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.', NULL, NULL, '07f707de5ab8b6c7e857f2e895449365b8aa3635da33c7829d7e31768a30e2c3'),
  ('en.sahih', 19, 35, 2285, 'It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.', NULL, NULL, '8dc824832993365e8fd9754988f70afc9f1fac79009f61d139ae7ac335302a7e'),
  ('en.sahih', 19, 36, 2286, '[Jesus said], "And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path."', NULL, NULL, '0b99286d505f233af49cc5c385ec42c011d5adad97dc94bd01cb88f307cc995a'),
  ('en.sahih', 19, 37, 2287, 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.', NULL, NULL, 'f2684fa89be4e0f0971c38590a5b772a0cb55aa45147bc2f0df931703161ab51'),
  ('en.sahih', 19, 38, 2288, 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.', NULL, NULL, 'b64cc9628939afbe978e3f2c4106654a13ceb23f731a47aa8fe307be5b9a16b0'),
  ('en.sahih', 19, 39, 2289, 'And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.', NULL, NULL, 'fe7441abcebcb2f1155dd7fcd7eef15afd901cde4199597247905a0a4da08c4b'),
  ('en.sahih', 19, 40, 2290, 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.', NULL, NULL, '73214fd9dd05ea05098a6e81df58e87aafd5e7dd9027788722bbebdb79fee221'),
  ('en.sahih', 19, 41, 2291, 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.', NULL, NULL, '1bf932ae1e13d871c0540c939f5ff496e3ec6eff9c58f6146db69c9d9db068d2'),
  ('en.sahih', 19, 42, 2292, '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?', NULL, NULL, '20cb6783d8192c6cd452290c64f6bb5bab38dfbfc8a980e87c18a0cc82c6eb4c'),
  ('en.sahih', 19, 43, 2293, 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.', NULL, NULL, 'a6cc7e4c5a725ddf8a1f3ef1ac9b85b6fc8a6f3402982152ccd510106ce0a557'),
  ('en.sahih', 19, 44, 2294, 'O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.', NULL, NULL, '5439150c2691e791598f8f0f2a42cba58a513e24eeb1417c65dc523b06d0d8dd'),
  ('en.sahih', 19, 45, 2295, 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."', NULL, NULL, '3cdbe7f6874183c17511ec419de6193d18e91e7c742750144eea2bd286f0facc'),
  ('en.sahih', 19, 46, 2296, '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."', NULL, NULL, '15f09898993b6b9f7124bbd652d81d8d5cb4ef98e850aedbbdf76d78026426a8'),
  ('en.sahih', 19, 47, 2297, '[Abraham] said, "Peace will be upon you. I will ask forgiveness for you of my Lord. Indeed, He is ever gracious to me.', NULL, NULL, '4a1dec3c54fb9d117696919952815b54b0d6a04b5e7a9dca576c9a96089953c1'),
  ('en.sahih', 19, 48, 2298, 'And I will leave you and those you invoke other than Allah and will invoke my Lord. I expect that I will not be in invocation to my Lord unhappy."', NULL, NULL, '6340725390f2715b796a61e3996e50f7f89613289c028d6193556dcc918cfab5'),
  ('en.sahih', 19, 49, 2299, 'So when he had left them and those they worshipped other than Allah, We gave him Isaac and Jacob, and each [of them] We made a prophet.', NULL, NULL, 'b9243882d4ebd8788d0c80d322a32b5bbc18d3ad1f82d75286e0fd90b334d725'),
  ('en.sahih', 19, 50, 2300, 'And We gave them of Our mercy, and we made for them a reputation of high honor.', NULL, NULL, 'e25a217c4ca055a43f1c6837aa2aca6a04fd7ab6e0f7f701533998eff2a34563')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 19, 51, 2301, 'And mention in the Book, Moses. Indeed, he was chosen, and he was a messenger and a prophet.', NULL, NULL, '90b7627e6ad6d725279da386f3cb386dfcd85dc52033d6d333591dbce48aabf9'),
  ('en.sahih', 19, 52, 2302, 'And We called him from the side of the mount at [his] right and brought him near, confiding [to him].', NULL, NULL, '2c0afec22515fe03aa640e25caa70a8ae34e11230999e9110909f6736ef3e881'),
  ('en.sahih', 19, 53, 2303, 'And We gave him out of Our mercy his brother Aaron as a prophet.', NULL, NULL, '19bf7376bd64beb37a5673a808033ea0a430e2b1b0405f15b1adf26400baf70d'),
  ('en.sahih', 19, 54, 2304, 'And mention in the Book, Ishmael. Indeed, he was true to his promise, and he was a messenger and a prophet.', NULL, NULL, 'e1d818d7bdb422656df5390002521400b6c23a33d9d0e2a645f49c39a43ae0e2'),
  ('en.sahih', 19, 55, 2305, 'And he used to enjoin on his people prayer and zakah and was to his Lord pleasing.', NULL, NULL, 'edd15dc3832b75469f604fb44a5fe2d92f6403882fbac86f5d85a1294559439f'),
  ('en.sahih', 19, 56, 2306, 'And mention in the Book, Idrees. Indeed, he was a man of truth and a prophet.', NULL, NULL, '9cdab0f51a8363e17bab73a7b03de3441837aea38468675556aa842fe229970c'),
  ('en.sahih', 19, 57, 2307, 'And We raised him to a high station.', NULL, NULL, '54dd48e1f4bdb9a4938dffb599eef7a65fb825c48499332d5e1abc0b5cdbc7d2'),
  ('en.sahih', 19, 58, 2308, 'Those were the ones upon whom Allah bestowed favor from among the prophets of the descendants of Adam and of those We carried [in the ship] with Noah, and of the descendants of Abraham and Israel, and of those whom We guided and chose. When the verses of the Most Merciful were recited to them, they fell in prostration and weeping.', NULL, NULL, '85349802b39df6a887710ba9001f4900e7339faba13206eb764398d590f0dd55'),
  ('en.sahih', 19, 59, 2309, 'But there came after them successors who neglected prayer and pursued desires; so they are going to meet evil -', NULL, NULL, '7d42b2b5dc4323793593a6ff21be6169a57ac19ada8ee4dce1fc27f45f5515cc'),
  ('en.sahih', 19, 60, 2310, 'Except those who repent, believe and do righteousness; for those will enter Paradise and will not be wronged at all.', NULL, NULL, 'b13b476fc990eeeee311002867686e3c2f6f282b21bbfe6790b4637370e05d23'),
  ('en.sahih', 19, 61, 2311, '[Therein are] gardens of perpetual residence which the Most Merciful has promised His servants in the unseen. Indeed, His promise has ever been coming.', NULL, NULL, '47a7316263b8aea867001a1e152d0f61f6b3ca90b31ec7961e1d295a56635e62'),
  ('en.sahih', 19, 62, 2312, 'They will not hear therein any ill speech - only [greetings of] peace - and they will have their provision therein, morning and afternoon.', NULL, NULL, '54321ad87dc357992d3cc410d7d9684ed338c3f2b19323094f4c6b56e9d80faf'),
  ('en.sahih', 19, 63, 2313, 'That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allah.', NULL, NULL, 'f3dab339a6d04f627aa94b76773d8cde6ab6b30269b24a30a74cd3aee17931e8'),
  ('en.sahih', 19, 64, 2314, '[Gabriel said], "And we [angels] descend not except by the order of your Lord. To Him belongs that before us and that behind us and what is in between. And never is your Lord forgetful -', NULL, NULL, 'eafdf566d060c54216a9e745c12e849eafbcddfa9f64abf683ef92908755076d'),
  ('en.sahih', 19, 65, 2315, 'Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?"', NULL, NULL, '975cb2eeb0532bbdf623bdbe0e6184abda1b3a100a5dcc7cb4908bf0e73228c2'),
  ('en.sahih', 19, 66, 2316, 'And the disbeliever says, "When I have died, am I going to be brought forth alive?"', NULL, NULL, '53a1bc1366ff9742a3d7c309c11b6ce1926635bdca48551b245493c2ff6a0666'),
  ('en.sahih', 19, 67, 2317, 'Does man not remember that We created him before, while he was nothing?', NULL, NULL, 'd0d9f818533ae1c178df5852b2c52ec77ed830bb57b3a80b077d0dede3848259'),
  ('en.sahih', 19, 68, 2318, 'So by your Lord, We will surely gather them and the devils; then We will bring them to be present around Hell upon their knees.', NULL, NULL, '882c490b5b0bfaa57a1162764fef29ef00bf8be438c5e522ff6bddcd6ae67efd'),
  ('en.sahih', 19, 69, 2319, 'Then We will surely extract from every sect those of them who were worst against the Most Merciful in insolence.', NULL, NULL, '1233252e085fa7e2ad2cf5b9c79d8fed62810fb52c25613519cc81618c5009d4'),
  ('en.sahih', 19, 70, 2320, 'Then, surely it is We who are most knowing of those most worthy of burning therein.', NULL, NULL, '6f608d5bb89953fb13e1c103da212abc6ab0c6cbe8e5408fed73994ccdde82cc'),
  ('en.sahih', 19, 71, 2321, 'And there is none of you except he will come to it. This is upon your Lord an inevitability decreed.', NULL, NULL, 'e1dbbacd44dcb39496fdc8337fea0f34d77e040425153b71d24da093346b7b55'),
  ('en.sahih', 19, 72, 2322, 'Then We will save those who feared Allah and leave the wrongdoers within it, on their knees.', NULL, NULL, '6c8bb62635d8d393507f27a99a04f4cb7e8563524b504c5450c5c5356d79b4ac'),
  ('en.sahih', 19, 73, 2323, 'And when Our verses are recited to them as clear evidences, those who disbelieve say to those who believe, "Which of [our] two parties is best in position and best in association?"', NULL, NULL, 'd73ca5b3b347393c076c123b2c9dfb735bbe78c0dd4268ae2d3195a52a9e5736'),
  ('en.sahih', 19, 74, 2324, 'And how many a generation have We destroyed before them who were better in possessions and [outward] appearance?', NULL, NULL, '0a1b88ac4882e74b2ead065354098682bc8e7470a72a55cc15d1fdb9e02f9c30'),
  ('en.sahih', 19, 75, 2325, 'Say, "Whoever is in error - let the Most Merciful extend for him an extension [in wealth and time] until, when they see that which they were promised - either punishment [in this world] or the Hour [of resurrection] - they will come to know who is worst in position and weaker in soldiers."', NULL, NULL, '4270f2f9219448ad047701cf803dbf9051bd683f420c0a5a5f26a80f6550f21f'),
  ('en.sahih', 19, 76, 2326, 'And Allah increases those who were guided, in guidance, and the enduring good deeds are better to your Lord for reward and better for recourse.', NULL, NULL, 'c6546b2194c7d0dd6d895431b7a4187d92a18376bf920959dc4f594014c9fe9f'),
  ('en.sahih', 19, 77, 2327, 'Then, have you seen he who disbelieved in Our verses and said, "I will surely be given wealth and children [in the next life]?"', NULL, NULL, '510814b5feced2ee6515e82f4b5be8866547c785a0bbb3484031a055d594b4aa'),
  ('en.sahih', 19, 78, 2328, 'Has he looked into the unseen, or has he taken from the Most Merciful a promise?', NULL, NULL, '1e20a3051004de266b957d6b3782f4b613437ae4d97fda7c8ce5a49282130284'),
  ('en.sahih', 19, 79, 2329, 'No! We will record what he says and extend for him from the punishment extensively.', NULL, NULL, '5dcbc020fd87d96662c8d92323d8f4d8ff2f87c367e2b961a8497c5387c4d0ad'),
  ('en.sahih', 19, 80, 2330, 'And We will inherit him [in] what he mentions, and he will come to Us alone.', NULL, NULL, 'c93b0aaaf4ba1a93e0ca89e325792f90d4d25d0b61a42c98d806b9cb230f6148'),
  ('en.sahih', 19, 81, 2331, 'And they have taken besides Allah [false] deities that they would be for them [a source of] honor.', NULL, NULL, 'a90edc1ef104a95e7a525242f8ebbe33bd4e4ee1ea63c0f72c268e26f65e2f21'),
  ('en.sahih', 19, 82, 2332, 'No! Those "gods" will deny their worship of them and will be against them opponents [on the Day of Judgement].', NULL, NULL, '3d7f1c5a98f07646edeca62d0d8802ab7f77a955e570ddbaa86c25e2a080543b'),
  ('en.sahih', 19, 83, 2333, 'Do you not see that We have sent the devils upon the disbelievers, inciting them to [evil] with [constant] incitement?', NULL, NULL, 'b3898b6f3965275b688601be1096ceaaab9575ce3db7e5efebf42654a14da1b9'),
  ('en.sahih', 19, 84, 2334, 'So be not impatient over them. We only count out to them a [limited] number.', NULL, NULL, '02c9cb35a2e732e4018b0219997fa3270cb769ac48c15fb2d3ecbfa7a1fb516d'),
  ('en.sahih', 19, 85, 2335, 'On the Day We will gather the righteous to the Most Merciful as a delegation', NULL, NULL, '86c5cf849242d16534554f9b2f9b5692407e10fc1a7f6cdc8e9eb928b190707f'),
  ('en.sahih', 19, 86, 2336, 'And will drive the criminals to Hell in thirst', NULL, NULL, '8a03215423d425002e6fab0e5542defd2a082c0f77aff1446bb4dcf6df4231ea'),
  ('en.sahih', 19, 87, 2337, 'None will have [power of] intercession except he who had taken from the Most Merciful a covenant.', NULL, NULL, '492027cb4be6fdcd6acd1a7e6903135f13116aa3516e45cd4b399a292762acc8'),
  ('en.sahih', 19, 88, 2338, 'And they say, "The Most Merciful has taken [for Himself] a son."', NULL, NULL, '1ff29d02ca65064e3c2ce65f166e43bdfa7accbcbd79c33ba52ff77893cc4303'),
  ('en.sahih', 19, 89, 2339, 'You have done an atrocious thing.', NULL, NULL, '59dadb8c3750ce542cf23bab03555045a9b4ea08490ae2ad00bd8583080d89c5'),
  ('en.sahih', 19, 90, 2340, 'The heavens almost rupture therefrom and the earth splits open and the mountains collapse in devastation', NULL, NULL, 'd7f5f579ede87ac99ccf62f81746d6078e2ca6addcbd5fab7030f01a313d3482'),
  ('en.sahih', 19, 91, 2341, 'That they attribute to the Most Merciful a son.', NULL, NULL, 'cc8ea0611a2d187e8b9ab3e6ffd6ff268f9ad814b7571650ad7bc35283583c11'),
  ('en.sahih', 19, 92, 2342, 'And it is not appropriate for the Most Merciful that He should take a son.', NULL, NULL, '9efc3d856176665e88359f96aaebfa312b780549f5fd20635d7c8b06592799d1'),
  ('en.sahih', 19, 93, 2343, 'There is no one in the heavens and earth but that he comes to the Most Merciful as a servant.', NULL, NULL, '73614a0d81d8e4317be9d095a876653eec26aaf7087f1cb66b9c68c4581c555b'),
  ('en.sahih', 19, 94, 2344, 'He has enumerated them and counted them a [full] counting.', NULL, NULL, 'ea03eec1883fdbebcc3beccc716cf2bf7bd49383c6f361a9b997b43f48455c3f'),
  ('en.sahih', 19, 95, 2345, 'And all of them are coming to Him on the Day of Resurrection alone.', NULL, NULL, 'eda9af8150955255811673b1ccd2c0ba5874b1efb20d507f74869f92d405cb45'),
  ('en.sahih', 19, 96, 2346, 'Indeed, those who have believed and done righteous deeds - the Most Merciful will appoint for them affection.', NULL, NULL, '09eedf740189541de7a78c8a1dc5fb0016fc577c5a2bb30ae607358b4ada99ba'),
  ('en.sahih', 19, 97, 2347, 'So, [O Muhammad], We have only made Qur''an easy in the Arabic language that you may give good tidings thereby to the righteous and warn thereby a hostile people.', NULL, NULL, 'df63937197d58aac895b11d36f62478fe2661d44e4850ea2a62ad91d2a78eff0'),
  ('en.sahih', 19, 98, 2348, 'And how many have We destroyed before them of generations? Do you perceive of them anyone or hear from them a sound?', NULL, NULL, '78bb09663594674c2de394b8d5ec31baf9ee8479dd504b704d2d23026cd964f5'),
  ('en.sahih', 20, 1, 2349, 'Ta, Ha.', NULL, NULL, '7f08172fd01777944f66c1fbfc17aec8b8f88ad4080e49cbcf8c30f616f92eb2'),
  ('en.sahih', 20, 2, 2350, 'We have not sent down to you the Qur''an that you be distressed', NULL, NULL, 'e7817d98e57529f203bf7c92174cae80df1e3d1642cd26480bb3d14b444898a3'),
  ('en.sahih', 20, 3, 2351, 'But only as a reminder for those who fear [Allah] -', NULL, NULL, 'bdf554b7fa780d4ee530cbc19c9621dcff057cd4bf0d8416218aa428611055ea'),
  ('en.sahih', 20, 4, 2352, 'A revelation from He who created the earth and highest heavens,', NULL, NULL, 'cb3b72a3962f407c431e05ac2846bb441cbf95cd2ad6bc2fde9772304cb79d99'),
  ('en.sahih', 20, 5, 2353, 'The Most Merciful [who is] above the Throne established.', NULL, NULL, '0fe5baaa7f28b2dffde57fa088bfc0901a9402a8707869adb6b6875fd23b8535'),
  ('en.sahih', 20, 6, 2354, 'To Him belongs what is in the heavens and what is on the earth and what is between them and what is under the soil.', NULL, NULL, '5f8570b941990a1250e30dc248eeb15114cdbcd0a018bf26f797090b667f62f7'),
  ('en.sahih', 20, 7, 2355, 'And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden.', NULL, NULL, '1df8a2c14d48a19a2b71d232fd552fee552739f8918c0efc8e9c9b3e9b62d079'),
  ('en.sahih', 20, 8, 2356, 'Allah - there is no deity except Him. To Him belong the best names.', NULL, NULL, '992cae1681c489a0237cb97ab20546850681f69d61cbfa7e34c760fe82d334ad'),
  ('en.sahih', 20, 9, 2357, 'And has the story of Moses reached you? -', NULL, NULL, '5763db8fb1375e1bbbf3ff523ecf5bc6faf1df477423ee126f1ac50843650166'),
  ('en.sahih', 20, 10, 2358, 'When he saw a fire and said to his family, "Stay here; indeed, I have perceived a fire; perhaps I can bring you a torch or find at the fire some guidance."', NULL, NULL, '0ae44814578b61d9c7385b4f3081363206d43f9ed83b4eb52c02eab15eddc345'),
  ('en.sahih', 20, 11, 2359, 'And when he came to it, he was called, "O Moses,', NULL, NULL, 'e146ef7c1ce7832c4e7132a62294bb0c419a7ae986b4b54f8985bbe8fd0c65bf'),
  ('en.sahih', 20, 12, 2360, 'Indeed, I am your Lord, so remove your sandals. Indeed, you are in the sacred valley of Tuwa.', NULL, NULL, 'c90b5f3b792cfbca1ce00784a0bd65c0347b82a2ac58cc86c5f0d2b414e20582'),
  ('en.sahih', 20, 13, 2361, 'And I have chosen you, so listen to what is revealed [to you].', NULL, NULL, '7f20c8b27f7f3c8a9567ea2c6cf2299177e829940601e5bc7ddaf494d5e00ce5'),
  ('en.sahih', 20, 14, 2362, 'Indeed, I am Allah. There is no deity except Me, so worship Me and establish prayer for My remembrance.', NULL, NULL, '0a78dbcd0cfee06906ea95091fef9b230d24695dab46cb18e0961e0865ae3a15'),
  ('en.sahih', 20, 15, 2363, 'Indeed, the Hour is coming - I almost conceal it - so that every soul may be recompensed according to that for which it strives.', NULL, NULL, 'c290d149433f1ace906827b889bd7f94b18d35ee11d9c912c5dea040ae308b84'),
  ('en.sahih', 20, 16, 2364, 'So do not let one avert you from it who does not believe in it and follows his desire, for you [then] would perish.', NULL, NULL, '68265bea6d553409a7c33d30b1f004904cb929a1e27c546121fc7eadaa63f826'),
  ('en.sahih', 20, 17, 2365, 'And what is that in your right hand, O Moses?"', NULL, NULL, '90320c6fd3eefc8d751fa95e85ed5c4c2a2afad3e3966190f2507206d1e09410'),
  ('en.sahih', 20, 18, 2366, 'He said, "It is my staff; I lean upon it, and I bring down leaves for my sheep and I have therein other uses."', NULL, NULL, '9958fc16f2c159b740c362f8621c8e443046460fe9706f3a16d73cd6108ff864'),
  ('en.sahih', 20, 19, 2367, '[Allah] said, "Throw it down, O Moses."', NULL, NULL, '89cd0b7e0b9a555708796aef11060f72f27d159643b9c5fc929aa62cae3e92ea'),
  ('en.sahih', 20, 20, 2368, 'So he threw it down, and thereupon it was a snake, moving swiftly.', NULL, NULL, '2bd7507eb699b87952797ac83a379875450b66f2a75175930b625e705c7e9897'),
  ('en.sahih', 20, 21, 2369, '[Allah] said, "Seize it and fear not; We will return it to its former condition.', NULL, NULL, 'dce275556493fb6ef0db08f4183aa28e84e484df2c221ad438fd64f75181ffbf'),
  ('en.sahih', 20, 22, 2370, 'And draw in your hand to your side; it will come out white without disease - another sign,', NULL, NULL, 'a63e81a6d58ee4b35d1e6034c9c5b79a64250956164552747cdb96df17a3e1f2'),
  ('en.sahih', 20, 23, 2371, 'That We may show you [some] of Our greater signs.', NULL, NULL, 'f31c3236fa4bee190a05b466f4ec7306f6773ee7279f6218a5bcf99c9096a32c'),
  ('en.sahih', 20, 24, 2372, 'Go to Pharaoh. Indeed, he has transgressed."', NULL, NULL, '612483c6e27176b869b9fdac224c2e0c0fdfe16224714171802b215e84c10aa5'),
  ('en.sahih', 20, 25, 2373, '[Moses] said, "My Lord, expand for me my breast [with assurance]', NULL, NULL, '7a74c704b3e02b782cecbdec321d5d1e72eb4c70dce53fdd27288f0a37e266b9'),
  ('en.sahih', 20, 26, 2374, 'And ease for me my task', NULL, NULL, 'd331807f77567fe9280e8f0ee82078755eb2c9362f930ffbf3a6fb366facf3b0'),
  ('en.sahih', 20, 27, 2375, 'And untie the knot from my tongue', NULL, NULL, '187648d76008044afc08d7a4462f707032e0937436365ebe0e50d3bbd6a9edd9'),
  ('en.sahih', 20, 28, 2376, 'That they may understand my speech.', NULL, NULL, 'cf69d731a8f672bfff919468fdddc9ab38372a81bffc47914ed38eedba9de7b4'),
  ('en.sahih', 20, 29, 2377, 'And appoint for me a minister from my family -', NULL, NULL, '3b5bc7719863d5a0604946f545786896069e2c4daa3b475ce18b0dd000c0b6c8'),
  ('en.sahih', 20, 30, 2378, 'Aaron, my brother.', NULL, NULL, 'f82a44188890da6a601d89bc65a35cb2eeb7e7687f38f6cc37ca61d22c2e69d4'),
  ('en.sahih', 20, 31, 2379, 'Increase through him my strength', NULL, NULL, '349a76a1e057cb020fe2056d4f065a74466eb7a4821fc9364a7e6eb2f6d51690'),
  ('en.sahih', 20, 32, 2380, 'And let him share my task', NULL, NULL, 'a272d7447860ab04800eefbb0c32a62b28938f9d60d289a849a8fcae7f091ddc'),
  ('en.sahih', 20, 33, 2381, 'That we may exalt You much', NULL, NULL, 'e402121bcf3da19844e78d7dfe390bbb31af55cdbcca88d8a654b21bec424e49'),
  ('en.sahih', 20, 34, 2382, 'And remember You much.', NULL, NULL, '3a9075784b6d78ce4a0ebb61fbe1a754a477f96adb34a910cf003a2f6f928e29'),
  ('en.sahih', 20, 35, 2383, 'Indeed, You are of us ever Seeing."', NULL, NULL, 'b8110ea6113bb8a32ac4b73e7e6dfb5683d48156c263945bfac092d875617095'),
  ('en.sahih', 20, 36, 2384, '[Allah] said, "You have been granted your request, O Moses.', NULL, NULL, '7c8bd1df594bfa9774d62279e0d5839d512e3902db0e32f8527641328fc62bc7'),
  ('en.sahih', 20, 37, 2385, 'And We had already conferred favor upon you another time,', NULL, NULL, '653ee5dea860669cd808e99140b18a9ec9eb46c27478123fd354bca311490568'),
  ('en.sahih', 20, 38, 2386, 'When We inspired to your mother what We inspired,', NULL, NULL, '0f1bfce34f17c5e6d9c0e1e21d1b3000f90176fbc8b027f23919dffa31558feb'),
  ('en.sahih', 20, 39, 2387, '[Saying], ''Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.'' And I bestowed upon you love from Me that you would be brought up under My eye.', NULL, NULL, '94b3d415f4e63e817c33c61f0e4607d33f2bc7e4ecfd0350ade5f72ff318ea43'),
  ('en.sahih', 20, 40, 2388, '[And We favored you] when your sister went and said, ''Shall I direct you to someone who will be responsible for him?'' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.', NULL, NULL, '8a817ab57bc2e0e2470bde6dc2f64e495d32f991863817ac513e3433708c348b'),
  ('en.sahih', 20, 41, 2389, 'And I produced you for Myself.', NULL, NULL, '40928e8138756e2800bb765094ed8c183939307b5d3bb75e13305ecd692f6351'),
  ('en.sahih', 20, 42, 2390, 'Go, you and your brother, with My signs and do not slacken in My remembrance.', NULL, NULL, '8f2c749d311ee309057bc7d3f8c7e2d3753319268cb026dcf4e9b9cefa67648a'),
  ('en.sahih', 20, 43, 2391, 'Go, both of you, to Pharaoh. Indeed, he has transgressed.', NULL, NULL, 'd8cf03a8e5b7a6f0011a05749e6603b8403fdee7b9d6651a68b498c2c0fb1fc2'),
  ('en.sahih', 20, 44, 2392, 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allah]."', NULL, NULL, '434c63c64fca4a6269a67e8d7ba94ed52c8d1c75507dd6b050a1bc9076ced288'),
  ('en.sahih', 20, 45, 2393, 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."', NULL, NULL, 'e43cfe9d453d218937c76132503c58824a81dc838517ba52c0f799649cba6c29'),
  ('en.sahih', 20, 46, 2394, '[Allah] said, "Fear not. Indeed, I am with you both; I hear and I see.', NULL, NULL, 'c1930fdcc39497372e97ccfb10a0c39a3e1045dcb774afbbe300fb4f6e80ea96'),
  ('en.sahih', 20, 47, 2395, 'So go to him and say, ''Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.', NULL, NULL, '3b3715cb57ad329ded2834fafe97916bd97624b237a3946e8cf2a2487cd7c06c'),
  ('en.sahih', 20, 48, 2396, 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.'' "', NULL, NULL, 'ae2dd64bdcb9213e312ab1a1df46fbe46d21bc1989be07319f96ad5f505530e7'),
  ('en.sahih', 20, 49, 2397, '[Pharaoh] said, "So who is the Lord of you two, O Moses?"', NULL, NULL, 'f94f93512f1703c8c5658fe45aa3890ff089b336deb7d2f19740208d871ea439'),
  ('en.sahih', 20, 50, 2398, 'He said, "Our Lord is He who gave each thing its form and then guided [it]."', NULL, NULL, 'a564168824cc9db8f79b21463f6a698c4bdc30484495074a22aac996ab20fd22'),
  ('en.sahih', 20, 51, 2399, '[Pharaoh] said, "Then what is the case of the former generations?"', NULL, NULL, '95ed54b52cde03125ba45703fee9d52b8a06923ac0722087b938a7f046ffd641'),
  ('en.sahih', 20, 52, 2400, '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."', NULL, NULL, '6dad3038c1a2311cd4a685bcb15a57890a3b52a12e71a763e163683f80160a62')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 20, 53, 2401, '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.', NULL, NULL, '4b43257c186f1e34c7642967e43d435a8fd7e743be9ea9807917956aeb2f743d'),
  ('en.sahih', 20, 54, 2402, 'Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence.', NULL, NULL, 'e4cf801642af53bba2deb27847c6bf4dd0d2d77461d14941f5e41c9e93602ed0'),
  ('en.sahih', 20, 55, 2403, 'From the earth We created you, and into it We will return you, and from it We will extract you another time.', NULL, NULL, '8db48c4068f36a339313ed84b296ae2488dcc83a980a98874578e063a2601ecd'),
  ('en.sahih', 20, 56, 2404, 'And We certainly showed Pharaoh Our signs - all of them - but he denied and refused.', NULL, NULL, '63d08d32b7beea6bdee9916cd72a18f5367ea1d417f6f3a4306e2ec1f1b90248'),
  ('en.sahih', 20, 57, 2405, 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?', NULL, NULL, '9611d272b869895ef9208abab6f2c12d0c8bdc9fd9e0725b015cad58071e5eba'),
  ('en.sahih', 20, 58, 2406, 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."', NULL, NULL, '552dcdefc38fb3c58541b7ac0a902605e0a69b3b41537b78a407b5218a628ac4'),
  ('en.sahih', 20, 59, 2407, '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."', NULL, NULL, '30cbf5bdff25afc822141530c00744ca18ab1ebda5411f71c41e893ff9a38c6a'),
  ('en.sahih', 20, 60, 2408, 'So Pharaoh went away, put together his plan, and then came [to Moses].', NULL, NULL, '2b108786feb911044f7e9e864a234ffa43b09bda1bf700139a6b501d277cd2c1'),
  ('en.sahih', 20, 61, 2409, 'Moses said to the magicians summoned by Pharaoh, "Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."', NULL, NULL, '6dbaee8769e45035721fd1752f31cf18a7e282cb9a38803466f8dee1dd1a4720'),
  ('en.sahih', 20, 62, 2410, 'So they disputed over their affair among themselves and concealed their private conversation.', NULL, NULL, '1d019c38031f8832d3735ea5565ac652627fd9154bfc9f36be954f6e37a6bd2c'),
  ('en.sahih', 20, 63, 2411, 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way.', NULL, NULL, 'a95b306698cf9f2edca5055b7258a6007b15113eaa0fa1d3c84cbe325ec6966c'),
  ('en.sahih', 20, 64, 2412, 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."', NULL, NULL, '20eff957d283e8d928f2fe229591fd5d17ef092d48ee30089e5fc3da7eb5d3e7'),
  ('en.sahih', 20, 65, 2413, 'They said, "O Moses, either you throw or we will be the first to throw."', NULL, NULL, '84c3fcbe489858d70771e468a041ef6247d7e7e22c692ebbdaf50e65a29abdd3'),
  ('en.sahih', 20, 66, 2414, 'He said, "Rather, you throw." And suddenly their ropes and staffs seemed to him from their magic that they were moving [like snakes].', NULL, NULL, '94cf9d83ac65b7b5f8c0c15abe01bc2706c4e1d0e43ea2eb699867fbbbc1d733'),
  ('en.sahih', 20, 67, 2415, 'And he sensed within himself apprehension, did Moses.', NULL, NULL, '126b39db6b6a1bb186b1ef183666fa7ec2aa26fc9b1555f932a2ea7adcb88f56'),
  ('en.sahih', 20, 68, 2416, 'Allah said, "Fear not. Indeed, it is you who are superior.', NULL, NULL, '9eefb7fb7cdc22d96b789daddce3fab5fb20c8abd61bea02b5bf86bba0073f38'),
  ('en.sahih', 20, 69, 2417, 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."', NULL, NULL, 'd229b8b64ae262b6174a2b9d217dc361f07a42d096d2a2640f639a7b5649d613'),
  ('en.sahih', 20, 70, 2418, 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."', NULL, NULL, '95572b11ee1a378317ec09cf1f781c711a097f3ccfe615658317ef66b24952d6'),
  ('en.sahih', 20, 71, 2419, '[Pharaoh] said, "You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."', NULL, NULL, '70c4d2b690e6c4980c713272cbdc59c18cb1287039ac2dd34aaa8909a4234f42'),
  ('en.sahih', 20, 72, 2420, 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.', NULL, NULL, '66d974895862d7f3c7a4e9a2ea3ee19825ab9526336322b902f379ec440392eb'),
  ('en.sahih', 20, 73, 2421, 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring."', NULL, NULL, 'f163aa2d30d74c6906cb0fd0a0a8aa52fc45f19f1d73a827412768a6609e4916'),
  ('en.sahih', 20, 74, 2422, 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.', NULL, NULL, '32985becf3b44cd6ecbd5147dc8d3c6ce6aad414c67d7d55e8e60b54e08d7558'),
  ('en.sahih', 20, 75, 2423, 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:', NULL, NULL, '51cc7f2effa96332a3b8c715af503d3c247a123aea6620af97eaea5d5e431ebf'),
  ('en.sahih', 20, 76, 2424, 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.', NULL, NULL, '0f0139d4328e85e9a46d091e6cf30452307ef320f669da9ca018b2fbd4651361'),
  ('en.sahih', 20, 77, 2425, 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."', NULL, NULL, 'db5a0c1bda03a686bc01fde7607771fe301614336df29797b4407a9e222117c4'),
  ('en.sahih', 20, 78, 2426, 'So Pharaoh pursued them with his soldiers, and there covered them from the sea that which covered them,', NULL, NULL, 'bbd183d6a6327bb34c7ea1529a2416352afb62edc4091a15ccb3dd7ab70c2ff8'),
  ('en.sahih', 20, 79, 2427, 'And Pharaoh led his people astray and did not guide [them].', NULL, NULL, 'e816c167d8d4fe76c2dbe45273632818ece128c1c40b3aff269bf3dc9fa8d709'),
  ('en.sahih', 20, 80, 2428, 'O Children of Israel, We delivered you from your enemy, and We made an appointment with you at the right side of the mount, and We sent down to you manna and quails,', NULL, NULL, '7e93aca717ec4c2be9f4d2c82e37381beb95c7d7bcd7436923df41cb73e84b47'),
  ('en.sahih', 20, 81, 2429, '[Saying], "Eat from the good things with which We have provided you and do not transgress [or oppress others] therein, lest My anger should descend upon you. And he upon whom My anger descends has certainly fallen."', NULL, NULL, 'cf6240539191250f4e31c43ce5e3d11236c3d972e2c522873dfe924c2b5201d4'),
  ('en.sahih', 20, 82, 2430, 'But indeed, I am the Perpetual Forgiver of whoever repents and believes and does righteousness and then continues in guidance.', NULL, NULL, '9923c382c3dacacb5dc70cec8793f549e912b2006584e4ecd00e6f16b06c1c80'),
  ('en.sahih', 20, 83, 2431, '[Allah] said, "And what made you hasten from your people, O Moses?"', NULL, NULL, '8a2760f85a5ee9be0b037653f0b4c11d34d2a905f09d1c83cbca1b6e4cfd042f'),
  ('en.sahih', 20, 84, 2432, 'He said, "They are close upon my tracks, and I hastened to You, my Lord, that You be pleased."', NULL, NULL, 'e8c02e99df45d1ab06d278e9ca1ef9c4fa66bd4c59c0459162f2196ee837c2db'),
  ('en.sahih', 20, 85, 2433, '[Allah] said, "But indeed, We have tried your people after you [departed], and the Samiri has led them astray."', NULL, NULL, '5fbfd2bb0c00fd7ad0cf72b632cea248ec2eaa62f0e0a6400e7afbdb6cfa9921'),
  ('en.sahih', 20, 86, 2434, 'So Moses returned to his people, angry and grieved. He said, "O my people, did your Lord not make you a good promise? Then, was the time [of its fulfillment] too long for you, or did you wish that wrath from your Lord descend upon you, so you broke your promise [of obedience] to me?"', NULL, NULL, '32568c9271dfd299d063b420d005007a6447ead11113e01b465f94758ae9835e'),
  ('en.sahih', 20, 87, 2435, 'They said, "We did not break our promise to you by our will, but we were made to carry burdens from the ornaments of the people [of Pharaoh], so we threw them [into the fire], and thus did the Samiri throw."', NULL, NULL, 'c11fc0874c1dee7e91e6cf1e87d698a070a2956a795da880840e413b8010c76c'),
  ('en.sahih', 20, 88, 2436, 'And he extracted for them [the statue of] a calf which had a lowing sound, and they said, "This is your god and the god of Moses, but he forgot."', NULL, NULL, '4c1a7c703a0b63c0a9d9625c93a58d10a713ef620fd831f6c2adfc970e8ed13d'),
  ('en.sahih', 20, 89, 2437, 'Did they not see that it could not return to them any speech and that it did not possess for them any harm or benefit?', NULL, NULL, '8aabb0b589e48e95ace1fcd1dc24d9cc59024b628d3ea1c8d04bd73ab7bc830d'),
  ('en.sahih', 20, 90, 2438, 'And Aaron had already told them before [the return of Moses], "O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order."', NULL, NULL, '6307c40c04dd91d8ed23ea7606f7279a979c5c0872aea9c538422ccde584a935'),
  ('en.sahih', 20, 91, 2439, 'They said, "We will never cease being devoted to the calf until Moses returns to us."', NULL, NULL, 'd787735b14ba60ae99eab9cc6d8838ffa500c0db2742d7e49457b692a89809f7'),
  ('en.sahih', 20, 92, 2440, '[Moses] said, "O Aaron, what prevented you, when you saw them going astray,', NULL, NULL, '76209aac51e27711f9201b730a203ddef82d6709a691097922b43b88583a001b'),
  ('en.sahih', 20, 93, 2441, 'From following me? Then have you disobeyed my order?"', NULL, NULL, 'ba807af9295aa05a04f214746c9dce44ae10361462831b9fa97b261fae49731e'),
  ('en.sahih', 20, 94, 2442, '[Aaron] said, "O son of my mother, do not seize [me] by my beard or by my head. Indeed, I feared that you would say, ''You caused division among the Children of Israel, and you did not observe [or await] my word.'' "', NULL, NULL, 'ee16dd972cb76bfabc522c483bca21e9e4beb237340d507421e789a91abe21b5'),
  ('en.sahih', 20, 95, 2443, '[Moses] said, "And what is your case, O Samiri?"', NULL, NULL, '8016c8f3b56743d3a3e529bedc484a56cf413fe1c88c67934950c291ea1c6603'),
  ('en.sahih', 20, 96, 2444, 'He said, "I saw what they did not see, so I took a handful [of dust] from the track of the messenger and threw it, and thus did my soul entice me."', NULL, NULL, '4c7b7fe4e6851ffc2e474468cfde06146d724c01c10e4a18d84525c9e7a90613'),
  ('en.sahih', 20, 97, 2445, '[Moses] said, "Then go. And indeed, it is [decreed] for you in [this] life to say, ''No contact.'' And indeed, you have an appointment [in the Hereafter] you will not fail to keep. And look at your ''god'' to which you remained devoted. We will surely burn it and blow it into the sea with a blast.', NULL, NULL, 'b3b17363f1e68c55db78c83bd4543d5f1a3e3f6a63a9eb03b0b371407496ec1d'),
  ('en.sahih', 20, 98, 2446, 'Your god is only Allah, except for whom there is no deity. He has encompassed all things in knowledge."', NULL, NULL, 'f67725dc90846756badfd49138d5d84a5ee958002de22bc142ad5dfa8de78c5e'),
  ('en.sahih', 20, 99, 2447, 'Thus, [O Muhammad], We relate to you from the news of what has preceded. And We have certainly given you from Us the Qur''an.', NULL, NULL, 'e0351b6bcd5ced4b1a148d5c27737cc1e1e6d1a692cf119f9be0c69599f193dc'),
  ('en.sahih', 20, 100, 2448, 'Whoever turns away from it - then indeed, he will bear on the Day of Resurrection a burden,', NULL, NULL, 'c8c5811061724447f857f64a9144f683c1da5a1df2df57f103940bb62fbbaa93'),
  ('en.sahih', 20, 101, 2449, '[Abiding] eternally therein, and evil it is for them on the Day of Resurrection as a load -', NULL, NULL, '44f609153ea76468e50c0df9db8e5bed2689f277605d58c33ed540b566289a0f'),
  ('en.sahih', 20, 102, 2450, 'The Day the Horn will be blown. And We will gather the criminals, that Day, blue-eyed.', NULL, NULL, 'ff8972f7c6b2db9a2053f3531dd729a6b9569073aae0f398a992e8822ad84c19'),
  ('en.sahih', 20, 103, 2451, 'They will murmur among themselves, "You remained not but ten [days in the world]."', NULL, NULL, '3fbdc3b1042991c7099d3ca694e5d7c501ac2064e082b3001420f524cf2fead2'),
  ('en.sahih', 20, 104, 2452, 'We are most knowing of what they say when the best of them in manner will say, "You remained not but one day."', NULL, NULL, 'a6322d46689df8adf9d1e8d5414bdeab9bdf24a774a90cba7a008542568d27f2'),
  ('en.sahih', 20, 105, 2453, 'And they ask you about the mountains, so say, "My Lord will blow them away with a blast.', NULL, NULL, 'a0dab79de56f15249b34ac3c1889ba78b73989722482d8b152995bf07553fe78'),
  ('en.sahih', 20, 106, 2454, 'And He will leave the earth a level plain;', NULL, NULL, '0584bd09cdbf3000b354ed97bcdb412271b54705385e68248ac1ffd58420c861'),
  ('en.sahih', 20, 107, 2455, 'You will not see therein a depression or an elevation."', NULL, NULL, 'c0a4d4b71c43fe5b7f4e9a4188f07b20ea6160aefd83e92864dc3b49a271f1bd'),
  ('en.sahih', 20, 108, 2456, 'That Day, everyone will follow [the call of] the Caller [with] no deviation therefrom, and [all] voices will be stilled before the Most Merciful, so you will not hear except a whisper [of footsteps].', NULL, NULL, '8e4bcee9d3d38d65697ac941acb901e6b328173a9f8f168b70092275c646436e'),
  ('en.sahih', 20, 109, 2457, 'That Day, no intercession will benefit except [that of] one to whom the Most Merciful has given permission and has accepted his word.', NULL, NULL, '88ce4b0255c1c0cdb00ecf770060a0f8aa057594806be2b992740313e3e23d47'),
  ('en.sahih', 20, 110, 2458, 'Allah knows what is [presently] before them and what will be after them, but they do not encompass it in knowledge.', NULL, NULL, 'd4918eeb27d7f67e12cbb8f8a3755128f816146a4e509ee4fdf8203aece3523f'),
  ('en.sahih', 20, 111, 2459, 'And [all] faces will be humbled before the Ever-Living, the Sustainer of existence. And he will have failed who carries injustice.', NULL, NULL, 'ea4cb18055aef464494dd068415a1b17dffbdc87201582738b27a59ae7bb9d1c'),
  ('en.sahih', 20, 112, 2460, 'But he who does of righteous deeds while he is a believer - he will neither fear injustice nor deprivation.', NULL, NULL, '5b5361752dc59006c6699c4cff99385b6df7572abffbf4d2a30a4e596b472ca9'),
  ('en.sahih', 20, 113, 2461, 'And thus We have sent it down as an Arabic Qur''an and have diversified therein the warnings that perhaps they will avoid [sin] or it would cause them remembrance.', NULL, NULL, '6d6c556fb85648896f3b333178f9b3c5067fa328e9381deef88d101adebc55b6'),
  ('en.sahih', 20, 114, 2462, 'So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur''an before its revelation is completed to you, and say, "My Lord, increase me in knowledge."', NULL, NULL, 'af8c569ddecd4528223016ff23b225ca90cdd44b08d93cf32e24a889f8a22c83'),
  ('en.sahih', 20, 115, 2463, 'And We had already taken a promise from Adam before, but he forgot; and We found not in him determination.', NULL, NULL, 'd46acdf96432c4d6918e144d225047922cc7e2d65513bd11bfd9185322f98da0'),
  ('en.sahih', 20, 116, 2464, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except Iblees; he refused.', NULL, NULL, 'b05a36cdb755cbe7a8017016b68d1976231d2882072f2c04a536d1b0e1e7a48a'),
  ('en.sahih', 20, 117, 2465, 'So We said, "O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer.', NULL, NULL, '77dff347619f50739f40d4921f2b30e0658efbcc7ce2c1ddca94db128b3036bd'),
  ('en.sahih', 20, 118, 2466, 'Indeed, it is [promised] for you not to be hungry therein or be unclothed.', NULL, NULL, '8bfca28d061c4d6970e6e1c419119a1dbe7bde98afdc5de46e28fd6815349bfa'),
  ('en.sahih', 20, 119, 2467, 'And indeed, you will not be thirsty therein or be hot from the sun."', NULL, NULL, '37487079e3fe10de23ba01fcac11c1d59b59fe21dd692e5741ce466d8e0e45eb'),
  ('en.sahih', 20, 120, 2468, 'Then Satan whispered to him; he said, "O Adam, shall I direct you to the tree of eternity and possession that will not deteriorate?"', NULL, NULL, 'c8bd7b7fb1fb59714238d6d58db929aa2bf1dbf6565dcb5a51a7f74db904044f'),
  ('en.sahih', 20, 121, 2469, 'And Adam and his wife ate of it, and their private parts became apparent to them, and they began to fasten over themselves from the leaves of Paradise. And Adam disobeyed his Lord and erred.', NULL, NULL, '71dcba7f3c96e4206ca6b99a27715b78225f37dc8ba6b165d429464fe5933d53'),
  ('en.sahih', 20, 122, 2470, 'Then his Lord chose him and turned to him in forgiveness and guided [him].', NULL, NULL, '6629f6fe8df2628182960395e51d0b8be24a8c316bf259dc3b215322d32ef26f'),
  ('en.sahih', 20, 123, 2471, '[Allah] said, "Descend from Paradise - all, [your descendants] being enemies to one another. And if there should come to you guidance from Me - then whoever follows My guidance will neither go astray [in the world] nor suffer [in the Hereafter].', NULL, NULL, '7289dcb8470fed3b4e4e3fe12c535cc48a22b033860d5b3701a4baa61f93e544'),
  ('en.sahih', 20, 124, 2472, 'And whoever turns away from My remembrance - indeed, he will have a depressed life, and We will gather him on the Day of Resurrection blind."', NULL, NULL, 'c55677c2a2348313bf11c6ebb78a65bd5c1e181293d4e141ea039ee0f88381b2'),
  ('en.sahih', 20, 125, 2473, 'He will say, "My Lord, why have you raised me blind while I was [once] seeing?"', NULL, NULL, 'c6c90e56300c90e9c35d9185babf670a3bd103ecbdbb920c239bfb0f1896fff3'),
  ('en.sahih', 20, 126, 2474, '[Allah] will say, "Thus did Our signs come to you, and you forgot them; and thus will you this Day be forgotten."', NULL, NULL, 'a5fcea7a7d13eeecbb273829f95235247168b83027980e08f48f68663fd15bfa'),
  ('en.sahih', 20, 127, 2475, 'And thus do We recompense he who transgressed and did not believe in the signs of his Lord. And the punishment of the Hereafter is more severe and more enduring.', NULL, NULL, 'abb7d92028de379a0bb2f4d09e7ffca4c8d4d63652d2ff42d76ac4fd1b283cca'),
  ('en.sahih', 20, 128, 2476, 'Then, has it not become clear to them how many generations We destroyed before them as they walk among their dwellings? Indeed in that are signs for those of intelligence.', NULL, NULL, '50fdb82b407311e02425d3391feeb9eca02f74fdd734a4d30a6d31baee75db10'),
  ('en.sahih', 20, 129, 2477, 'And if not for a word that preceded from your Lord, punishment would have been an obligation [due immediately], and [if not for] a specified term [decreed].', NULL, NULL, '05fb5d5cb32ee088d5ba67f753a1c551baa540982e4ca783932807e0fedc5fe5'),
  ('en.sahih', 20, 130, 2478, 'So be patient over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting; and during periods of the night [exalt Him] and at the ends of the day, that you may be satisfied.', NULL, NULL, '67dd3deb1f7b919cfd5c16193002b73d3ecd125b85907c523f0873308f2b035a'),
  ('en.sahih', 20, 131, 2479, 'And do not extend your eyes toward that by which We have given enjoyment to [some] categories of them, [its being but] the splendor of worldly life by which We test them. And the provision of your Lord is better and more enduring.', NULL, NULL, '077cdc84bdaf0ed3110a79d36da9b0e5af1c1ea78cb02c5be045430a6ecb6ddb'),
  ('en.sahih', 20, 132, 2480, 'And enjoin prayer upon your family [and people] and be steadfast therein. We ask you not for provision; We provide for you, and the [best] outcome is for [those of] righteousness.', NULL, NULL, '99723b2d89dc0e219537c6de5ff175f7ef6089f17b62919c7419984906533ba6'),
  ('en.sahih', 20, 133, 2481, 'And they say, "Why does he not bring us a sign from his Lord?" Has there not come to them evidence of what was in the former scriptures?', NULL, NULL, '4ff0469dc9ad5d5a411cd20aad8729d3f99d9571e947a566a93ab968f5cad05d'),
  ('en.sahih', 20, 134, 2482, 'And if We had destroyed them with a punishment before him, they would have said, "Our Lord, why did You not send to us a messenger so we could have followed Your verses before we were humiliated and disgraced?"', NULL, NULL, '4e2555a1c40cd6542db58f45aed7afa6d6305e84a4199a2e4c3893aacacd9369'),
  ('en.sahih', 20, 135, 2483, 'Say, "Each [of us] is waiting; so wait. For you will know who are the companions of the sound path and who is guided."', NULL, NULL, '33ed26a9a75faadbc37d4c4cb5fb684449686cabd22bee00a0bfe35d5e621de9'),
  ('en.sahih', 21, 1, 2484, '[The time of] their account has approached for the people, while they are in heedlessness turning away.', NULL, NULL, 'a60ec9882d64b28aec9ad832224a5b977f345bbea9b3aea5fb0da0dcd244a726'),
  ('en.sahih', 21, 2, 2485, 'No mention comes to them anew from their Lord except that they listen to it while they are at play', NULL, NULL, '36a950085d2aabd1ce05ac6545b405e33cf3bd3f3e1c7f6165961577931b9d47'),
  ('en.sahih', 21, 3, 2486, 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"', NULL, NULL, '4034784dad5daf3843cc0dcadc314c048f8f025c1158e351716809604bbf5f7a'),
  ('en.sahih', 21, 4, 2487, 'The Prophet said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."', NULL, NULL, '856b4307894f41fb2077c8157b694da08a1f529c3d4e2fcb647cafbbf8e51d5d'),
  ('en.sahih', 21, 5, 2488, 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."', NULL, NULL, 'b58d1622f81df368b1462da76212c989e8ead0ac20a6d8073aad9fb6600120cf'),
  ('en.sahih', 21, 6, 2489, 'Not a [single] city which We destroyed believed before them, so will they believe?', NULL, NULL, 'fd7be4b092bc16bc95f91b38c89a889a51115b66d4b9ec57ca400772b4421e21'),
  ('en.sahih', 21, 7, 2490, 'And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know.', NULL, NULL, '5830bbb91e9619ec20b6fd3c9cb9925afed9861d388c9f3ea6cfac5c774aa3bc'),
  ('en.sahih', 21, 8, 2491, 'And We did not make the prophets forms not eating food, nor were they immortal [on earth].', NULL, NULL, '5735d3e772064e8545a90cb4d2147ada25f27c2674b54e6d4dbe7ffcb0a60217'),
  ('en.sahih', 21, 9, 2492, 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.', NULL, NULL, 'c8a2f983a79dd2aabfe5963bc305562ae4bace77532eae6e8cd56ef1d2fa249d'),
  ('en.sahih', 21, 10, 2493, 'We have certainly sent down to you a Book in which is your mention. Then will you not reason?', NULL, NULL, '4a4888358b407b8ef9dcd1fdb9b3b413b3ccd284a98e9b251f175b144c31535d'),
  ('en.sahih', 21, 11, 2494, 'And how many a city which was unjust have We shattered and produced after it another people.', NULL, NULL, '5ad99db2d4494832dd4e30734c1e59171bb80388cf1a4b64e340195e787c967a'),
  ('en.sahih', 21, 12, 2495, 'And when its inhabitants perceived Our punishment, at once they fled from it.', NULL, NULL, '66f7084501d2466bb79497a0d1b8766ce658945a5240c6f410fbd27c59449365'),
  ('en.sahih', 21, 13, 2496, '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."', NULL, NULL, '5d42fcacaff1bbfd00fc293ae35978a9b8ea9542c0e33990c66696359e44fbaf'),
  ('en.sahih', 21, 14, 2497, 'They said, "O woe to us! Indeed, we were wrongdoers."', NULL, NULL, '3934f5bd3a74d30ce1b803f44833403aa5fdbd36db83a3542e9c923a5015cac9'),
  ('en.sahih', 21, 15, 2498, 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].', NULL, NULL, 'dc3994090cabf9e7247f6d3ebb9e4aad7fd0d2161460e91566693456316a0b67'),
  ('en.sahih', 21, 16, 2499, 'And We did not create the heaven and earth and that between them in play.', NULL, NULL, '86a546c1cd32139d1074d7b1b9b7329ed0e63917007bf49534d258fd93a9c18e'),
  ('en.sahih', 21, 17, 2500, 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.', NULL, NULL, 'c335bc7b6a75f3386d6b1472b6fe00debdcabbefafc2047601053bc7cfc2d535')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 21, 18, 2501, 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.', NULL, NULL, '8fb6ef42e7486dbcbf4a38696e485f384fa82fbaac897c14df975847d929c2f3'),
  ('en.sahih', 21, 19, 2502, 'To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire.', NULL, NULL, 'c4f80031af992ea8979969af7361f7d057f9a9c975d7129591319e83727a55c1'),
  ('en.sahih', 21, 20, 2503, 'They exalt [Him] night and day [and] do not slacken.', NULL, NULL, '1b8ae0fb8570a19757391e717b360f5f345bd3de28c5b22c5cf5de97f780d2b0'),
  ('en.sahih', 21, 21, 2504, 'Or have men taken for themselves gods from the earth who resurrect [the dead]?', NULL, NULL, 'daecc44447534748f1063b346900bcb8ed32c2263ff26fc588bdd7559c5de9a6'),
  ('en.sahih', 21, 22, 2505, 'Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe.', NULL, NULL, '3b3d2493ba271e635c1e9ac2578c91e04b1770f38c6aa7a10c97368cefaabe70'),
  ('en.sahih', 21, 23, 2506, 'He is not questioned about what He does, but they will be questioned.', NULL, NULL, '28f5076d013171969ee5ee1c73085bba3d258ea067663e489ff2f3fe346a3371'),
  ('en.sahih', 21, 24, 2507, 'Or have they taken gods besides Him? Say, [O Muhammad], "Produce your proof. This [Qur''an] is the message for those with me and the message of those before me." But most of them do not know the truth, so they are turning away.', NULL, NULL, 'fdb8e04d1510faf8c2c2d63b87b45760775e55c5a5b23ee05fa6a755ceaca6a2'),
  ('en.sahih', 21, 25, 2508, 'And We sent not before you any messenger except that We revealed to him that, "There is no deity except Me, so worship Me."', NULL, NULL, 'f5731aaa7e183efd5884628fa1345938786f0dd31cc9be0991a7bd1c4e405873'),
  ('en.sahih', 21, 26, 2509, 'And they say, "The Most Merciful has taken a son." Exalted is He! Rather, they are [but] honored servants.', NULL, NULL, '3139ec7e7d2d25ee361acd9edbae690b990bceb59c07230500e981c987261068'),
  ('en.sahih', 21, 27, 2510, 'They cannot precede Him in word, and they act by His command.', NULL, NULL, '7ad7f99707c0339995fdb99a5c12af74953068968fb10c9da0aff7ecf4541ec1'),
  ('en.sahih', 21, 28, 2511, 'He knows what is [presently] before them and what will be after them, and they cannot intercede except on behalf of one whom He approves. And they, from fear of Him, are apprehensive.', NULL, NULL, '0029f9147ecd7c2aba3c1f1baae41a4c886090e8af310af86e1ab0a62d242e20'),
  ('en.sahih', 21, 29, 2512, 'And whoever of them should say, "Indeed, I am a god besides Him"- that one We would recompense with Hell. Thus do We recompense the wrongdoers.', NULL, NULL, '7b2e6b1bd1238cd2bf6942a5d3ed41367273362ad312d3cdca15fd757795e3d5'),
  ('en.sahih', 21, 30, 2513, 'Have those who disbelieved not considered that the heavens and the earth were a joined entity, and We separated them and made from water every living thing? Then will they not believe?', NULL, NULL, '4f34f05ece2b48ec9ead2def9456a0d6e6eb5a789189ac8fcbb8f53c2e9baa1b'),
  ('en.sahih', 21, 31, 2514, 'And We placed within the earth firmly set mountains, lest it should shift with them, and We made therein [mountain] passes [as] roads that they might be guided.', NULL, NULL, 'b48091c600839f0907a2beb33d7538cdaca9d9627313129210a50ba5e5171373'),
  ('en.sahih', 21, 32, 2515, 'And We made the sky a protected ceiling, but they, from its signs, are turning away.', NULL, NULL, '03ba68a61ef20748a25e155a271b9461b2db789c1e0bdd30d76302875ba13a21'),
  ('en.sahih', 21, 33, 2516, 'And it is He who created the night and the day and the sun and the moon; all [heavenly bodies] in an orbit are swimming.', NULL, NULL, 'cfc8a8467a3a0d10d0eb18103751dc875df638e2b9b24a839594aeba9e622b98'),
  ('en.sahih', 21, 34, 2517, 'And We did not grant to any man before you eternity [on earth]; so if you die - would they be eternal?', NULL, NULL, 'e25894130d65c69933f6e78c6303a9c2d7afc4cd84107443a84bf6793b566b3f'),
  ('en.sahih', 21, 35, 2518, 'Every soul will taste death. And We test you with evil and with good as trial; and to Us you will be returned.', NULL, NULL, '944346c6423b9386cd7d90760555641c66b45447e40a4d059107fc877fc10420'),
  ('en.sahih', 21, 36, 2519, 'And when those who disbelieve see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one who insults your gods?" And they are, at the mention of the Most Merciful, disbelievers.', NULL, NULL, 'f53dca8a7164e3aec82a2be0f39b77097e522f9633d235c44b04907055e49749'),
  ('en.sahih', 21, 37, 2520, 'Man was created of haste. I will show you My signs, so do not impatiently urge Me.', NULL, NULL, 'abc63f1881ed1e1b81c310dd09b828a07568939f2ab252ffa8c1499a60128f6e'),
  ('en.sahih', 21, 38, 2521, 'And they say, "When is this promise, if you should be truthful?"', NULL, NULL, 'e4ee081fcbbad38a41d5b6a7019faf4a99f8ff664f6d41adf700b9660b4d4a8a'),
  ('en.sahih', 21, 39, 2522, 'If those who disbelieved but knew the time when they will not avert the Fire from their faces or from their backs and they will not be aided...', NULL, NULL, '97e85db377cc1c6bde1fc00baf1e1c07bc3862d32586afe594262dff63ce07b7'),
  ('en.sahih', 21, 40, 2523, 'Rather, it will come to them unexpectedly and bewilder them, and they will not be able to repel it, nor will they be reprieved.', NULL, NULL, '8146ce9aa6a69bfa165c45a8be85eabbae508742ecac0e5e8ddb3d8cecd238c3'),
  ('en.sahih', 21, 41, 2524, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by what they used to ridicule.', NULL, NULL, '87fa8fa39b1371a9c4d56f838af94e3776f3fdec2da0eccd7cd49a648925ddb3'),
  ('en.sahih', 21, 42, 2525, 'Say, "Who can protect you at night or by day from the Most Merciful?" But they are, from the remembrance of their Lord, turning away.', NULL, NULL, 'bb3eee363a10a1547afdff8660a8c157fffb9a8042e775696bb08ab6519c63f2'),
  ('en.sahih', 21, 43, 2526, 'Or do they have gods to defend them other than Us? They are unable [even] to help themselves, nor can they be protected from Us.', NULL, NULL, '0e17d32b12d11d1f68d18fb138d3338a7e120ee34d318dcef467a2348f88478f'),
  ('en.sahih', 21, 44, 2527, 'But, [on the contrary], We have provided good things for these [disbelievers] and their fathers until life was prolonged for them. Then do they not see that We set upon the land, reducing it from its borders? So it is they who will overcome?', NULL, NULL, '8e74d9b26c334a1cc71c53e053dc3e18ef2ab4b9d22801245aa679900600c3fc'),
  ('en.sahih', 21, 45, 2528, 'Say, "I only warn you by revelation." But the deaf do not hear the call when they are warned.', NULL, NULL, 'adf869755fa8f9e7be821273684ac45251783c0f8cac48abc3b0d48a2c69234a'),
  ('en.sahih', 21, 46, 2529, 'And if [as much as] a whiff of the punishment of your Lord should touch them, they would surely say, "O woe to us! Indeed, we have been wrongdoers."', NULL, NULL, 'ef2abce1dfd529429a9a65c9ef6b5ffd18b899c40dd6d5e8098b8251a0eaa31a'),
  ('en.sahih', 21, 47, 2530, 'And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant.', NULL, NULL, 'fa1f3ad279c91471bbbe467cec3c7778bef19722be9439d400f3ab09f9604884'),
  ('en.sahih', 21, 48, 2531, 'And We had already given Moses and Aaron the criterion and a light and a reminder for the righteous', NULL, NULL, '58aa157a32019b626c6215639124ea2e0fd7e461c2091c51c1447a31f8a0d136'),
  ('en.sahih', 21, 49, 2532, 'Who fear their Lord unseen, while they are of the Hour apprehensive.', NULL, NULL, 'e56ae9d3eaa2bfa8e946ffce70eaf7d4dc9718f3d387ceb08e8392bdb3fae7dd'),
  ('en.sahih', 21, 50, 2533, 'And this [Qur''an] is a blessed message which We have sent down. Then are you with it unacquainted?', NULL, NULL, '47901abecdf24efa2b9b16059dd997f9d9bde2b0fd02e20a7d3bcd446930715e'),
  ('en.sahih', 21, 51, 2534, 'And We had certainly given Abraham his sound judgement before, and We were of him well-Knowing', NULL, NULL, 'c1918b6757336388afe2123266626d66b50b5c55faa245e40ec932246371f959'),
  ('en.sahih', 21, 52, 2535, 'When he said to his father and his people, "What are these statues to which you are devoted?"', NULL, NULL, 'd144f3ec542ff494d48260e5a4c0ccd84aceed427a4dc571bec8f178077e3486'),
  ('en.sahih', 21, 53, 2536, 'They said, "We found our fathers worshippers of them."', NULL, NULL, '9699bd7c7655c2e3d0cbceb91350540d6b396c2a7d6ba704eac75360402e4db6'),
  ('en.sahih', 21, 54, 2537, 'He said, "You were certainly, you and your fathers, in manifest error."', NULL, NULL, '02f1f39a48ced7c6356a9bc621b3233b4a31536323f9dac28476ee5eb99c0f33'),
  ('en.sahih', 21, 55, 2538, 'They said, "Have you come to us with truth, or are you of those who jest?"', NULL, NULL, 'c42e38369a2bf527cb15e2bf8645e6ed4a04693a9a69fb109e06d2adf1cd6d02'),
  ('en.sahih', 21, 56, 2539, 'He said, "[No], rather, your Lord is the Lord of the heavens and the earth who created them, and I, to that, am of those who testify.', NULL, NULL, 'a21493821192021635f3d5069506ad251aa19631d277c33035d5066c80405058'),
  ('en.sahih', 21, 57, 2540, 'And [I swear] by Allah, I will surely plan against your idols after you have turned and gone away."', NULL, NULL, 'f84d8a8c05117fbc05d837a32b7d0408906c802a749ebfc8e005d739f5aa2f29'),
  ('en.sahih', 21, 58, 2541, 'So he made them into fragments, except a large one among them, that they might return to it [and question].', NULL, NULL, 'b31dc95076d44a216d47cd37b94d2799b5120069cbace0d3f6a73a2eca3165c0'),
  ('en.sahih', 21, 59, 2542, 'They said, "Who has done this to our gods? Indeed, he is of the wrongdoers."', NULL, NULL, '332a4b72035858d46112a12fc0195c79f28b9d61c827e7e0c964b1562d835903'),
  ('en.sahih', 21, 60, 2543, 'They said, "We heard a young man mention them who is called Abraham."', NULL, NULL, 'dfc83cce580e5a8be19815bd9bdd5479b17d87164ca159239922e92e79930953'),
  ('en.sahih', 21, 61, 2544, 'They said, "Then bring him before the eyes of the people that they may testify."', NULL, NULL, '4b6e1ff79998982cdbed10ca1fb0bc93a2a8aaff5241adfc9dca528c2e09a31b'),
  ('en.sahih', 21, 62, 2545, 'They said, "Have you done this to our gods, O Abraham?"', NULL, NULL, '39dfb40b0bd01c3a68dd5a19b3a52bc73b99de49279f0ed414a99c93d3d87c99'),
  ('en.sahih', 21, 63, 2546, 'He said, "Rather, this - the largest of them - did it, so ask them, if they should [be able to] speak."', NULL, NULL, '6f204333d88143c5518823a34824fc649fa7f5ab16a88d83d6618d1c05463bc5'),
  ('en.sahih', 21, 64, 2547, 'So they returned to [blaming] themselves and said [to each other], "Indeed, you are the wrongdoers."', NULL, NULL, '7fe6acdf7810b8bf89e384fa887e0f46fa4829117ab3f7f8ddb2bf6d560e5e7d'),
  ('en.sahih', 21, 65, 2548, 'Then they reversed themselves, [saying], "You have already known that these do not speak!"', NULL, NULL, '059101d81ac1e3b4860defb4889b492a4aa675e9f72856165e466fb27061696b'),
  ('en.sahih', 21, 66, 2549, 'He said, "Then do you worship instead of Allah that which does not benefit you at all or harm you?', NULL, NULL, '3562041bf77020479928b552ba9d6fa559be7286aff9cea952dfaf24c18bbca1'),
  ('en.sahih', 21, 67, 2550, 'Uff to you and to what you worship instead of Allah. Then will you not use reason?"', NULL, NULL, '5fdfa06f79515242dc7d68d2084993000a81228110135a2d2f05294aa3628f12'),
  ('en.sahih', 21, 68, 2551, 'They said, "Burn him and support your gods - if you are to act."', NULL, NULL, '4967db5420989fe4edad0b17e4b06cc512e76a2e60ecf33bf54d0b1e1c8df314'),
  ('en.sahih', 21, 69, 2552, 'Allah said, "O fire, be coolness and safety upon Abraham."', NULL, NULL, '6843de0dbf1bb23ecd38d5bfa89723f3d5c01092be8d37fbc3329d4e3aae5dfc'),
  ('en.sahih', 21, 70, 2553, 'And they intended for him harm, but We made them the greatest losers.', NULL, NULL, '0cb34b0baa132ec5351489bb9c513d6323217b49b9098fb3029be3fa4419b213'),
  ('en.sahih', 21, 71, 2554, 'And We delivered him and Lot to the land which We had blessed for the worlds.', NULL, NULL, 'ecee8750d7eb5ec7093259693e76c1f4d9c17617cc8b529bdc130a55eead3c8f'),
  ('en.sahih', 21, 72, 2555, 'And We gave him Isaac and Jacob in addition, and all [of them] We made righteous.', NULL, NULL, 'f09ef1eb7651f317414478a4343f5a45dce6fac29ee8ee475388094f177cb51a'),
  ('en.sahih', 21, 73, 2556, 'And We made them leaders guiding by Our command. And We inspired to them the doing of good deeds, establishment of prayer, and giving of zakah; and they were worshippers of Us.', NULL, NULL, 'dce584246dbf8d013b881f17c3110b966eb22bd1a7b53f94e0fc0b6ef8208c27'),
  ('en.sahih', 21, 74, 2557, 'And to Lot We gave judgement and knowledge, and We saved him from the city that was committing wicked deeds. Indeed, they were a people of evil, defiantly disobedient.', NULL, NULL, '7a049774b61c410175689cd36a07d651003e9d31e2faa3555d2628e55592d818'),
  ('en.sahih', 21, 75, 2558, 'And We admitted him into Our mercy. Indeed, he was of the righteous.', NULL, NULL, 'ab00e3a7f40802bc6d2af5803d341d340bff410c6fac6d6635cdeb49e6ada7e2'),
  ('en.sahih', 21, 76, 2559, 'And [mention] Noah, when he called [to Allah] before [that time], so We responded to him and saved him and his family from the great flood.', NULL, NULL, '0a53aa08debf69f8a87d2ae4197259a3819b48ffc134384c6f971e4129673cdf'),
  ('en.sahih', 21, 77, 2560, 'And We saved him from the people who denied Our signs. Indeed, they were a people of evil, so We drowned them, all together.', NULL, NULL, 'fd6e463630d804e26edb9d92b9c1cf19118fcc3d5c97a182b1f6092e3b6a5053'),
  ('en.sahih', 21, 78, 2561, 'And [mention] David and Solomon, when they judged concerning the field - when the sheep of a people overran it [at night], and We were witness to their judgement.', NULL, NULL, 'f29ef3d9b8fbfe79af3103ddc3d16925285c852ee20a6a9f5d364fc69871bca9'),
  ('en.sahih', 21, 79, 2562, 'And We gave understanding of the case to Solomon, and to each [of them] We gave judgement and knowledge. And We subjected the mountains to exalt [Us], along with David and [also] the birds. And We were doing [that].', NULL, NULL, '617edcd0fac8d57e7d1b8f9928f1382911c7139ff6c9f292dd7fd75857a57144'),
  ('en.sahih', 21, 80, 2563, 'And We taught him the fashioning of coats of armor to protect you from your [enemy in] battle. So will you then be grateful?', NULL, NULL, '7c34e4c2d1bfaf556df1fb228326985f4980dd48d43fc82b32ce7adfec050786'),
  ('en.sahih', 21, 81, 2564, 'And to Solomon [We subjected] the wind, blowing forcefully, proceeding by his command toward the land which We had blessed. And We are ever, of all things, Knowing.', NULL, NULL, '33c242a85da2faefef8646020c4f94bdd5a2aabb41d293b431969acc74f23b5a'),
  ('en.sahih', 21, 82, 2565, 'And of the devils were those who dived for him and did work other than that. And We were of them a guardian.', NULL, NULL, '2c23f97387ce5b0b6e93fd207040b920bdf10f825c2f3e834bdd28fe99c0b93d'),
  ('en.sahih', 21, 83, 2566, 'And [mention] Job, when he called to his Lord, "Indeed, adversity has touched me, and you are the Most Merciful of the merciful."', NULL, NULL, '696339872a8a6bfbe7222258c332632c0fa20bc946d6733855f0ded83ec0b0b6'),
  ('en.sahih', 21, 84, 2567, 'So We responded to him and removed what afflicted him of adversity. And We gave him [back] his family and the like thereof with them as mercy from Us and a reminder for the worshippers [of Allah].', NULL, NULL, 'c283a7b944e2a460eff48e2a1748b7f031fb0ee508ca20f7bf03080fe5271225'),
  ('en.sahih', 21, 85, 2568, 'And [mention] Ishmael and Idrees and Dhul-Kifl; all were of the patient.', NULL, NULL, '1d9a37e430b9b3770afccb4b34ba56c29ee0cd6f1fca58a70ed86f6e6cd9ae08'),
  ('en.sahih', 21, 86, 2569, 'And We admitted them into Our mercy. Indeed, they were of the righteous.', NULL, NULL, 'e21ef671f953f9c59735371975102fc8ef19a8cfe86231d3dea101494eec6575'),
  ('en.sahih', 21, 87, 2570, 'And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers."', NULL, NULL, '301c2ef3ddec8df9256af6f4b7adac4d2a8890ec5bb2e7b173bb4ab2995af47a'),
  ('en.sahih', 21, 88, 2571, 'So We responded to him and saved him from the distress. And thus do We save the believers.', NULL, NULL, 'b5958f24a0d2c4a5aaf906f7afbf1647267f863d699c6c1f28b95a90d68c4a65'),
  ('en.sahih', 21, 89, 2572, 'And [mention] Zechariah, when he called to his Lord, "My Lord, do not leave me alone [with no heir], while you are the best of inheritors."', NULL, NULL, '5468380c9f8db59467e03c72eecb21a14b3cec98eb2b30b2af82940cc61b3c02'),
  ('en.sahih', 21, 90, 2573, 'So We responded to him, and We gave to him John, and amended for him his wife. Indeed, they used to hasten to good deeds and supplicate Us in hope and fear, and they were to Us humbly submissive.', NULL, NULL, 'beeee2e7334f47acf76a89df9652bc0a97c5af495d08fa1d6c37531dc576a64c'),
  ('en.sahih', 21, 91, 2574, 'And [mention] the one who guarded her chastity, so We blew into her [garment] through Our angel [Gabriel], and We made her and her son a sign for the worlds.', NULL, NULL, 'e80d9240f5f2da85984fb1a2dcaaacdce657688a2830293303a71f23be7adc39'),
  ('en.sahih', 21, 92, 2575, 'Indeed this, your religion, is one religion, and I am your Lord, so worship Me.', NULL, NULL, 'a81838c14ff54907e656b44bbe1c650f402690692c9e58dd73dceb4425c031fe'),
  ('en.sahih', 21, 93, 2576, 'And [yet] they divided their affair among themselves, [but] all to Us will return.', NULL, NULL, '937f0c647f5ef08c2c02324a1c633efabe138b6ad916d19cd88ef75df32a5db5'),
  ('en.sahih', 21, 94, 2577, 'So whoever does righteous deeds while he is a believer - no denial will there be for his effort, and indeed We, of it, are recorders.', NULL, NULL, 'fe0540fcda21c0d800cb1cbeb6174969c8bf15b46436154664d75854a420ca78'),
  ('en.sahih', 21, 95, 2578, 'And there is prohibition upon [the people of] a city which We have destroyed that they will [ever] return', NULL, NULL, '81bc38dc1a60bb0dfd28dc0514cbae23af8d0649ffd823936405a6393e006f12'),
  ('en.sahih', 21, 96, 2579, 'Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend', NULL, NULL, '257516f01b8568057e8301c1805d1ae1ddebf46cb793007b7eafb6a727e897e0'),
  ('en.sahih', 21, 97, 2580, 'And [when] the true promise has approached; then suddenly the eyes of those who disbelieved will be staring [in horror, while they say], "O woe to us; we had been unmindful of this; rather, we were wrongdoers."', NULL, NULL, '62f847f2da3a74c803ef4986ad0199464a978691e171fad9cfb735c5b12d9dd0'),
  ('en.sahih', 21, 98, 2581, 'Indeed, you [disbelievers] and what you worship other than Allah are the firewood of Hell. You will be coming to [enter] it.', NULL, NULL, 'ca43cbea07dc6454fd8545596bec8f82bb3e73aa33139b551d19a05db18f3ec6'),
  ('en.sahih', 21, 99, 2582, 'Had these [false deities] been [actual] gods, they would not have come to it, but all are eternal therein.', NULL, NULL, '2c16ce4a3589e3f8b53cde2655b95587a9c736c12d044d44c42331f8206e11c5'),
  ('en.sahih', 21, 100, 2583, 'For them therein is heavy sighing, and they therein will not hear.', NULL, NULL, '749b127cbfccf3a7c449c3b7a2fdb9c3add5f3e92146612e218aad7816ea7379'),
  ('en.sahih', 21, 101, 2584, 'Indeed, those for whom the best [reward] has preceded from Us - they are from it far removed.', NULL, NULL, '086ce28d25f3618e171c0fcf93287dbfbe7e76c4737dec75effe87a2cefed52c'),
  ('en.sahih', 21, 102, 2585, 'They will not hear its sound, while they are, in that which their souls desire, abiding eternally.', NULL, NULL, '074d95e27a2396e90d849369c0d20431970d6ef608afc68f04e833e8f0df5a85'),
  ('en.sahih', 21, 103, 2586, 'They will not be grieved by the greatest terror, and the angels will meet them, [saying], "This is your Day which you have been promised" -', NULL, NULL, '30a60c6e68177fd4967673058d54fe5c4de0b16ded165de3544251773f541880'),
  ('en.sahih', 21, 104, 2587, 'The Day when We will fold the heaven like the folding of a [written] sheet for the records. As We began the first creation, We will repeat it. [That is] a promise binding upon Us. Indeed, We will do it.', NULL, NULL, '4cba750d3a8524262bd9e7cce0985bcf8e34463f2d13af6e4cb14df8c2297ff8'),
  ('en.sahih', 21, 105, 2588, 'And We have already written in the book [of Psalms] after the [previous] mention that the land [of Paradise] is inherited by My righteous servants.', NULL, NULL, '365907a4152a17e00343d499ca85e4e17c06176bd84330310f9623fb92798546'),
  ('en.sahih', 21, 106, 2589, 'Indeed, in this [Qur''an] is notification for a worshipping people.', NULL, NULL, 'a69b9f840fc657c769752feeca2528dafd58ddb07f7eab26fd897417070113bc'),
  ('en.sahih', 21, 107, 2590, 'And We have not sent you, [O Muhammad], except as a mercy to the worlds.', NULL, NULL, '3bae50d7f0a7393acdabe86631fa5dc6b35ca775a4effe5cf8f23f6e234c88f8'),
  ('en.sahih', 21, 108, 2591, 'Say, "It is only revealed to me that your god is but one God; so will you be Muslims [in submission to Him]?"', NULL, NULL, 'c8f51b9d2459f304119dc4bed6cd56263e211783dc11550b829183100af5e8b9'),
  ('en.sahih', 21, 109, 2592, 'But if they turn away, then say, "I have announced to [all of] you equally. And I know not whether near or far is that which you are promised.', NULL, NULL, '8e74a5776fb7d0ab44106a6733c1cb70987c9a989bbf09548ca853588537899d'),
  ('en.sahih', 21, 110, 2593, 'Indeed, He knows what is declared of speech, and He knows what you conceal.', NULL, NULL, '92b489cf3a60242eb108a8f66d80b35b3c38e0ae25af46cb037d00ff9fd25586'),
  ('en.sahih', 21, 111, 2594, 'And I know not; perhaps it is a trial for you and enjoyment for a time."', NULL, NULL, 'c0b7fa8df3cb2315184d3a1fe006baffb5bac9ecd9814daff027dc908374d4d8'),
  ('en.sahih', 21, 112, 2595, '[The Prophet] has said, "My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe."', NULL, NULL, '9974ed026c6bad36ae19e81841bbb67fd27baed0fd586b5829380c22fd2a6592'),
  ('en.sahih', 22, 1, 2596, 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.', NULL, NULL, 'de3abcdd61efa3d5f5160a87f1a701cc36c9c8536fffb9c9b9c0a147c7fc67b7'),
  ('en.sahih', 22, 2, 2597, 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe.', NULL, NULL, '518716206e36a4270c5ec84916b3ae449ae706b01c47310025e4e8731e0d6c7b'),
  ('en.sahih', 22, 3, 2598, 'And of the people is he who disputes about Allah without knowledge and follows every rebellious devil.', NULL, NULL, 'de838bb51607a58afe751c130ceb36e677fdb7cefcde9abd554d3c7c4e19de54'),
  ('en.sahih', 22, 4, 2599, 'It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.', NULL, NULL, 'b327cf8d2235a8cb42a7fdbf59c48bc9f0635663424dd3e598b2075dba334fbd'),
  ('en.sahih', 22, 5, 2600, 'O People, if you should be in doubt about the Resurrection, then [consider that] indeed, We created you from dust, then from a sperm-drop, then from a clinging clot, and then from a lump of flesh, formed and unformed - that We may show you. And We settle in the wombs whom We will for a specified term, then We bring you out as a child, and then [We develop you] that you may reach your [time of] maturity. And among you is he who is taken in [early] death, and among you is he who is returned to the most decrepit [old] age so that he knows, after [once having] knowledge, nothing. And you see the earth barren, but when We send down upon it rain, it quivers and swells and grows [something] of every beautiful kind.', NULL, NULL, 'b321b57407f2188c970db7a55def57d9f1b6b554e3e123c83642dba13e779feb')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 22, 6, 2601, 'That is because Allah is the Truth and because He gives life to the dead and because He is over all things competent', NULL, NULL, '948bbc3149a847ee894bbfe64a873ebeaa936d5eed377f4857368cde5307a2a6'),
  ('en.sahih', 22, 7, 2602, 'And [that they may know] that the Hour is coming - no doubt about it - and that Allah will resurrect those in the graves.', NULL, NULL, '805be364c04dcb360118edd957d04d2254d7522a43cab4658008ffe136013069'),
  ('en.sahih', 22, 8, 2603, 'And of the people is he who disputes about Allah without knowledge or guidance or an enlightening book [from Him],', NULL, NULL, '7bf9be6302424267b379310d20cab65341628405e17bff3e253d8f0d7e3eb4dc'),
  ('en.sahih', 22, 9, 2604, 'Twisting his neck [in arrogance] to mislead [people] from the way of Allah. For him in the world is disgrace, and We will make him taste on the Day of Resurrection the punishment of the Burning Fire [while it is said],', NULL, NULL, '0176e4f1b5b50d9ac4c76b824a80444ddf0290c607c460c8b0b23861ca6c2dfb'),
  ('en.sahih', 22, 10, 2605, '"That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."', NULL, NULL, 'c5fe0c540901a725950e90e133a695adb81e852f8e4d9e38ea0cc27acd34ac12'),
  ('en.sahih', 22, 11, 2606, 'And of the people is he who worships Allah on an edge. If he is touched by good, he is reassured by it; but if he is struck by trial, he turns on his face [to the other direction]. He has lost [this] world and the Hereafter. That is what is the manifest loss.', NULL, NULL, '787eab1bf2ca62ebd082b8d1463f047662229b1f9824857213537cd3cb95fea2'),
  ('en.sahih', 22, 12, 2607, 'He invokes instead of Allah that which neither harms him nor benefits him. That is what is the extreme error.', NULL, NULL, '45f82c66ae50cc0638231b657c1981baeb7198cb721fdd97e20e86caff92f394'),
  ('en.sahih', 22, 13, 2608, 'He invokes one whose harm is closer than his benefit - how wretched the protector and how wretched the associate.', NULL, NULL, '72dfd53c3d03f6d061e94eb186d4630459919b1bbf4cf2eec9535eed7733faf3'),
  ('en.sahih', 22, 14, 2609, 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. Indeed, Allah does what He intends.', NULL, NULL, '5da08133902122d56733e5cae5731410a9bdd924ae4becdd2f66943716c1862e'),
  ('en.sahih', 22, 15, 2610, 'Whoever should think that Allah will not support [Prophet Muhammad] in this world and the Hereafter - let him extend a rope to the ceiling, then cut off [his breath], and let him see: will his effort remove that which enrages [him]?', NULL, NULL, 'b3e9e7795f9d62db3932557190d4b4a952b88faa82391bdd09315ef8fd2ffc43'),
  ('en.sahih', 22, 16, 2611, 'And thus have We sent the Qur''an down as verses of clear evidence and because Allah guides whom He intends.', NULL, NULL, '426c901e71e7a70ab9e22309402d628e5d37c8d983cf6c6fd95fb978eec2849f'),
  ('en.sahih', 22, 17, 2612, 'Indeed, those who have believed and those who were Jews and the Sabeans and the Christians and the Magians and those who associated with Allah - Allah will judge between them on the Day of Resurrection. Indeed Allah is, over all things, Witness.', NULL, NULL, '352becbc3476f1e0866c9c9bbf84823b709845b37b22169e6b9c9c2892733af4'),
  ('en.sahih', 22, 18, 2613, 'Do you not see that to Allah prostrates whoever is in the heavens and whoever is on the earth and the sun, the moon, the stars, the mountains, the trees, the moving creatures and many of the people? But upon many the punishment has been justified. And he whom Allah humiliates - for him there is no bestower of honor. Indeed, Allah does what He wills.', NULL, NULL, '33f748e52df08474fcb3c594cb49a6434a46dbb09fd4b8fdc0416f0f5d98586e'),
  ('en.sahih', 22, 19, 2614, 'These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water', NULL, NULL, 'e837a8ee08335ec7ae3832aff1859792b1f5829f82579281458209e4ea44361d'),
  ('en.sahih', 22, 20, 2615, 'By which is melted that within their bellies and [their] skins.', NULL, NULL, '90629cc5712943503a21e6e30a017b2ae6305cc09a9f4614a3d03e6a1be21d60'),
  ('en.sahih', 22, 21, 2616, 'And for [striking] them are maces of iron.', NULL, NULL, '13fbf85f882f6b539b9ecec75820b8b4eea630780e3d51e4248d5e135fdad2b7'),
  ('en.sahih', 22, 22, 2617, 'Every time they want to get out of Hellfire from anguish, they will be returned to it, and [it will be said], "Taste the punishment of the Burning Fire!"', NULL, NULL, '4f57e6783dedd820eb54c10d295d0d587036f9f844452bbc0ba7c2e6952a88d7'),
  ('en.sahih', 22, 23, 2618, 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearl, and their garments therein will be silk.', NULL, NULL, '72d245e6bff7fb06d6cf5ccd2b1dbbca068c29ec499226e2c52c67cd8ab27a19'),
  ('en.sahih', 22, 24, 2619, 'And they had been guided [in worldly life] to good speech, and they were guided to the path of the Praiseworthy.', NULL, NULL, '41a90bc2ef8d9801186c4062bdc40a83bc00c1034dc1a2cb906615aad4b051f8'),
  ('en.sahih', 22, 25, 2620, 'Indeed, those who have disbelieved and avert [people] from the way of Allah and [from] al-Masjid al-Haram, which We made for the people - equal are the resident therein and one from outside; and [also] whoever intends [a deed] therein of deviation [in religion] or wrongdoing - We will make him taste of a painful punishment.', NULL, NULL, '813ab24b22214f4568f34ce760bdd7a52b98f1d010cc6731b5cb0a9399cb6251'),
  ('en.sahih', 22, 26, 2621, 'And [mention, O Muhammad], when We designated for Abraham the site of the House, [saying], "Do not associate anything with Me and purify My House for those who perform Tawaf and those who stand [in prayer] and those who bow and prostrate.', NULL, NULL, '0b97eb069640146093f1565457ef8aef4f55bed15cf1ff316a8f9969105d51ac'),
  ('en.sahih', 22, 27, 2622, 'And proclaim to the people the Hajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -', NULL, NULL, '768f171d2ed8176f1563153b18f9b59134157bf310077285169e45b865d974ab'),
  ('en.sahih', 22, 28, 2623, 'That they may witness benefits for themselves and mention the name of Allah on known days over what He has provided for them of [sacrificial] animals. So eat of them and feed the miserable and poor.', NULL, NULL, '5bad15b838f7e76b541cfc63e977ee3a88c9beaaafe4aa03389dd9c7732b3c88'),
  ('en.sahih', 22, 29, 2624, 'Then let them end their untidiness and fulfill their vows and perform Tawaf around the ancient House."', NULL, NULL, 'df2ae2fa7f3fce6b9853a582b94c9cb63894bd7d29dad30198032ca0c8705d26'),
  ('en.sahih', 22, 30, 2625, 'That [has been commanded], and whoever honors the sacred ordinances of Allah - it is best for him in the sight of his Lord. And permitted to you are the grazing livestock, except what is recited to you. So avoid the uncleanliness of idols and avoid false statement,', NULL, NULL, '3f8947710a9abc5a2bb943e281bf207d01f3090198681ae2814f03375ad577ea'),
  ('en.sahih', 22, 31, 2626, 'Inclining [only] to Allah, not associating [anything] with Him. And he who associates with Allah - it is as though he had fallen from the sky and was snatched by the birds or the wind carried him down into a remote place.', NULL, NULL, '6112a15cc0f426e28fac73a8901d2dbb70fc29bc473ad52bc5c207753beaeaf1'),
  ('en.sahih', 22, 32, 2627, 'That [is so]. And whoever honors the symbols of Allah - indeed, it is from the piety of hearts.', NULL, NULL, '0fe79f4189e303e5085f7fa88af4991187902bbad27a5bd1c04d0c7b29571c8f'),
  ('en.sahih', 22, 33, 2628, 'For you the animals marked for sacrifice are benefits for a specified term; then their place of sacrifice is at the ancient House.', NULL, NULL, '55e5ea631891711e4343ffbbeec1a0433f25ece84e1efe1a9de4ec5868361870'),
  ('en.sahih', 22, 34, 2629, 'And for all religion We have appointed a rite [of sacrifice] that they may mention the name of Allah over what He has provided for them of [sacrificial] animals. For your god is one God, so to Him submit. And, [O Muhammad], give good tidings to the humble [before their Lord]', NULL, NULL, '1121e2ca77fe50eed393dbc0f2ea63d536d05663d284229f5f8f7b1e7367b6eb'),
  ('en.sahih', 22, 35, 2630, 'Who, when Allah is mentioned, their hearts are fearful, and [to] the patient over what has afflicted them, and the establishers of prayer and those who spend from what We have provided them.', NULL, NULL, '60cf01f0a0cb19754eef8a7e5c1d9d5026b624ca3c3b780d6a35ff4e012b149b'),
  ('en.sahih', 22, 36, 2631, 'And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the name of Allah upon them when lined up [for sacrifice]; and when they are [lifeless] on their sides, then eat from them and feed the needy and the beggar. Thus have We subjected them to you that you may be grateful.', NULL, NULL, '2bdd1a9bb4032e827033948d3fb03f1d415353ea77fbf7eb5891f02d8a45c18e'),
  ('en.sahih', 22, 37, 2632, 'Their meat will not reach Allah, nor will their blood, but what reaches Him is piety from you. Thus have We subjected them to you that you may glorify Allah for that [to] which He has guided you; and give good tidings to the doers of good.', NULL, NULL, '0ef7ae18f6cbd85bf6f0aa3611678dbfb5e8f3067936a0dc05016321f147421b'),
  ('en.sahih', 22, 38, 2633, 'Indeed, Allah defends those who have believed. Indeed, Allah does not like everyone treacherous and ungrateful.', NULL, NULL, 'd7479ae792d4bbed4e89e16919d1e4065194f06a30d8bfc4f2a3fe33a59f96c4'),
  ('en.sahih', 22, 39, 2634, 'Permission [to fight] has been given to those who are being fought, because they were wronged. And indeed, Allah is competent to give them victory.', NULL, NULL, 'c550574b23356497bcfea2fa759e4b0ef09f22997adc836e08bdc83e84559b20'),
  ('en.sahih', 22, 40, 2635, '[They are] those who have been evicted from their homes without right - only because they say, "Our Lord is Allah." And were it not that Allah checks the people, some by means of others, there would have been demolished monasteries, churches, synagogues, and mosques in which the name of Allah is much mentioned. And Allah will surely support those who support Him. Indeed, Allah is Powerful and Exalted in Might.', NULL, NULL, '21bfdbb84bf73d893067f27c5c2d5af594e77cbc86a282a68b23ce1a6ca4a4f8'),
  ('en.sahih', 22, 41, 2636, '[And they are] those who, if We give them authority in the land, establish prayer and give zakah and enjoin what is right and forbid what is wrong. And to Allah belongs the outcome of [all] matters.', NULL, NULL, '0672392fdb434a079d0a29db3d7fcd346f18ee90d2a190d166bd623245b759e2'),
  ('en.sahih', 22, 42, 2637, 'And if they deny you, [O Muhammad] - so, before them, did the people of Noah and ''Aad and Thamud deny [their prophets],', NULL, NULL, '5e70ee5778b3494df0814a6a13745e3683229e37e59a292070078597c04d3751'),
  ('en.sahih', 22, 43, 2638, 'And the people of Abraham and the people of Lot', NULL, NULL, '1e1139c775cd75c69b27334e136aa8556879da476e78101c28037c068b07eeab'),
  ('en.sahih', 22, 44, 2639, 'And the inhabitants of Madyan. And Moses was denied, so I prolonged enjoyment for the disbelievers; then I seized them, and how [terrible] was My reproach.', NULL, NULL, '8dcb9a73a08a63bb3200380047457a09678cd0a2ed354ad4f48c06febf15cf7f'),
  ('en.sahih', 22, 45, 2640, 'And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace.', NULL, NULL, '9324a476f3ed8e556551e0b9a5c02ee246bf343118d3348906ad202efff5bde2'),
  ('en.sahih', 22, 46, 2641, 'So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts.', NULL, NULL, '1c2721c360d759470b82bcae1f37786e6c33029fe4ff0a068c606655ff50948e'),
  ('en.sahih', 22, 47, 2642, 'And they urge you to hasten the punishment. But Allah will never fail in His promise. And indeed, a day with your Lord is like a thousand years of those which you count.', NULL, NULL, '4904d134f5fd905e59bef972ebfe1ce85a54713d1c61a0c87ba25df5aabe5698'),
  ('en.sahih', 22, 48, 2643, 'And for how many a city did I prolong enjoyment while it was committing wrong. Then I seized it, and to Me is the [final] destination.', NULL, NULL, '2b185446b699f905575c38b8e2f509404413cb473102e0a93853dfa588c775ff'),
  ('en.sahih', 22, 49, 2644, 'Say, "O people, I am only to you a clear warner."', NULL, NULL, '88a4cb6d412344d0ffb3b3b7dba64afd06ea0ac15352ac25f76f78bc0c9eeafc'),
  ('en.sahih', 22, 50, 2645, 'And those who have believed and done righteous deeds - for them is forgiveness and noble provision.', NULL, NULL, 'f5874cb10974381528a27780275d524bffc55b62bf9b5597d1e901fd47663da8'),
  ('en.sahih', 22, 51, 2646, 'But the ones who strove against Our verses, [seeking] to cause failure - those are the companions of Hellfire.', NULL, NULL, '8e595a586a80839a2f2a29379ce5ad68e1eb3cfc84a9ee7b1b0504657887a81f'),
  ('en.sahih', 22, 52, 2647, 'And We did not send before you any messenger or prophet except that when he spoke [or recited], Satan threw into it [some misunderstanding]. But Allah abolishes that which Satan throws in; then Allah makes precise His verses. And Allah is Knowing and Wise.', NULL, NULL, 'fff9683ef9388b0f6ceee3e048e25266e55684968ae4272bb0df81a0fdc067eb'),
  ('en.sahih', 22, 53, 2648, '[That is] so He may make what Satan throws in a trial for those within whose hearts is disease and those hard of heart. And indeed, the wrongdoers are in extreme dissension.', NULL, NULL, '834aa11e1284d1a45f27d8b2340ab523f4787c7a13f277f8143e1ac3fa577e0e'),
  ('en.sahih', 22, 54, 2649, 'And so those who were given knowledge may know that it is the truth from your Lord and [therefore] believe in it, and their hearts humbly submit to it. And indeed is Allah the Guide of those who have believed to a straight path.', NULL, NULL, 'f196bdedb99c4f18dc27be01e3d7db03ebdf2bd1b31c514501927e42339ac720'),
  ('en.sahih', 22, 55, 2650, 'But those who disbelieve will not cease to be in doubt of it until the Hour comes upon them unexpectedly or there comes to them the punishment of a barren Day.', NULL, NULL, '26e6020b0a9d49e9bc3dc28a32fca2cd502c32a6c9c1cd96937c5b6c347dc1ce'),
  ('en.sahih', 22, 56, 2651, '[All] sovereignty that Day is for Allah; He will judge between them. So they who believed and did righteous deeds will be in the Gardens of Pleasure.', NULL, NULL, 'da7a518b77b417210c9e967edef23eecb8450445cad00b19a7a5c22ff2a1df24'),
  ('en.sahih', 22, 57, 2652, 'And they who disbelieved and denied Our signs - for those there will be a humiliating punishment.', NULL, NULL, '8b2533dc0836276523028809e9d9f39b875ff7b0b9c6f56392537ab2bb5c9770'),
  ('en.sahih', 22, 58, 2653, 'And those who emigrated for the cause of Allah and then were killed or died - Allah will surely provide for them a good provision. And indeed, it is Allah who is the best of providers.', NULL, NULL, 'ac8206c18ed13f584ac09d630d13a86aedc8268bd361a2ba1a53cd52ab8e7047'),
  ('en.sahih', 22, 59, 2654, 'He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allah is Knowing and Forbearing.', NULL, NULL, '47330e20d12da1b0d457ee71f92015dd27958ce22fc02c0f47834b3af7c2da46'),
  ('en.sahih', 22, 60, 2655, 'That [is so]. And whoever responds [to injustice] with the equivalent of that with which he was harmed and then is tyrannized - Allah will surely aid him. Indeed, Allah is Pardoning and Forgiving.', NULL, NULL, 'bc364b8d2e959369e03ffd91240ec46a0faed9ae6b3418ac57b62ff7bd2293ea'),
  ('en.sahih', 22, 61, 2656, 'That is because Allah causes the night to enter the day and causes the day to enter the night and because Allah is Hearing and Seeing.', NULL, NULL, '333e3a4cdc97ec1b454fea6cc3925e980305288b7948a33ccbac6e7ffcaae76f'),
  ('en.sahih', 22, 62, 2657, 'That is because Allah is the Truth, and that which they call upon other than Him is falsehood, and because Allah is the Most High, the Grand.', NULL, NULL, '2d18f7b69488fc624f6e1e7e009e52e7894cd4c6cfba5ef3a9ce6eb0427475a3'),
  ('en.sahih', 22, 63, 2658, 'Do you not see that Allah has sent down rain from the sky and the earth becomes green? Indeed, Allah is Subtle and Acquainted.', NULL, NULL, 'bd228d9e459532beeb6f40528b65e017e7b8f93b511db1b79726980a89280cca'),
  ('en.sahih', 22, 64, 2659, 'To Him belongs what is in the heavens and what is on the earth. And indeed, Allah is the Free of need, the Praiseworthy.', NULL, NULL, 'b119472133095eb5444a3cc3f6719af266a6b787e3958b148777dc6f4f22438e'),
  ('en.sahih', 22, 65, 2660, 'Do you not see that Allah has subjected to you whatever is on the earth and the ships which run through the sea by His command? And He restrains the sky from falling upon the earth, unless by His permission. Indeed Allah, to the people, is Kind and Merciful.', NULL, NULL, '145e418f1eea82fe0cc4ba536b4fc75f2b2c445a901891ef426389a245e9d100'),
  ('en.sahih', 22, 66, 2661, 'And He is the one who gave you life; then He causes you to die and then will [again] give you life. Indeed, mankind is ungrateful.', NULL, NULL, 'f582570bdc6d24ff180d3b60a85ec3448916bb97b231f325e88af368aff8957a'),
  ('en.sahih', 22, 67, 2662, 'For every religion We have appointed rites which they perform. So, [O Muhammad], let the disbelievers not contend with you over the matter but invite them to your Lord. Indeed, you are upon straight guidance.', NULL, NULL, '9f6535127018039b83e41416308adffb9ddaa5c6bb8bb94068767a09df4813de'),
  ('en.sahih', 22, 68, 2663, 'And if they dispute with you, then say, "Allah is most knowing of what you do.', NULL, NULL, '8399a591c494f771781b39213aea2f8436ee515af1f442714a749c40d8dbbfcd'),
  ('en.sahih', 22, 69, 2664, 'Allah will judge between you on the Day of Resurrection concerning that over which you used to differ."', NULL, NULL, 'd83dace9b94b16944e5ed75fb7c58cac72231fa7c15350abb8937675f51268ef'),
  ('en.sahih', 22, 70, 2665, 'Do you not know that Allah knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allah, is easy.', NULL, NULL, '7322d8b174ae9115cb9f4268ba7c239a3ce578093ce1bd15b501ffa62069266c'),
  ('en.sahih', 22, 71, 2666, 'And they worship besides Allah that for which He has not sent down authority and that of which they have no knowledge. And there will not be for the wrongdoers any helper.', NULL, NULL, '37537833098cc4a765c39336ff13a93b8c72f4458bb7c950a44dfccfacc32925'),
  ('en.sahih', 22, 72, 2667, 'And when Our verses are recited to them as clear evidences, you recognize in the faces of those who disbelieve disapproval. They are almost on the verge of assaulting those who recite to them Our verses. Say, "Then shall I inform you of [what is] worse than that? [It is] the Fire which Allah has promised those who disbelieve, and wretched is the destination."', NULL, NULL, 'd50f51f8c459ab1eb971e3ecc35c87a6d1e53cd542323b61d826e6f8fa1a44e1'),
  ('en.sahih', 22, 73, 2668, 'O people, an example is presented, so listen to it. Indeed, those you invoke besides Allah will never create [as much as] a fly, even if they gathered together for that purpose. And if the fly should steal away from them a [tiny] thing, they could not recover it from him. Weak are the pursuer and pursued.', NULL, NULL, 'e741ea9bb2da1b5dbb6fdc32eb23277f33124adbc691a3b6b3d9fb87c20c1366'),
  ('en.sahih', 22, 74, 2669, 'They have not appraised Allah with true appraisal. Indeed, Allah is Powerful and Exalted in Might.', NULL, NULL, '20bbf7f3dd1d7174f1c62d449e33c30c3facadb2bdcf476c259d784450ea5263'),
  ('en.sahih', 22, 75, 2670, 'Allah chooses from the angels messengers and from the people. Indeed, Allah is Hearing and Seeing.', NULL, NULL, '93f949a2192d8187517ed01b5ee05cc39bdd74734ce8979a8f2c2b0dece0aa7f'),
  ('en.sahih', 22, 76, 2671, 'He knows what is [presently] before them and what will be after them. And to Allah will be returned [all] matters.', NULL, NULL, '2d4efa2849c994fb43065e5f71a038d3b9e5ef2c0499192d756519bfd168bf2d'),
  ('en.sahih', 22, 77, 2672, 'O you who have believed, bow and prostrate and worship your Lord and do good - that you may succeed.', NULL, NULL, 'a08df1e8be3940aec8c9adecb11d13221cf88984025cd25245e91fbb8b01f212'),
  ('en.sahih', 22, 78, 2673, 'And strive for Allah with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. Allah named you "Muslims" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakah and hold fast to Allah. He is your protector; and excellent is the protector, and excellent is the helper.', NULL, NULL, '8b0c7eba8d4a461704aaf7b9d654693a6602b7faa8d46c0d9454cdc43ef7c811'),
  ('en.sahih', 23, 1, 2674, 'Certainly will the believers have succeeded:', NULL, NULL, '18cb55800f04b4c4b80dd88e10523762ea97181c1d9b2ca1af2b16701f22fd7e'),
  ('en.sahih', 23, 2, 2675, 'They who are during their prayer humbly submissive', NULL, NULL, '5b6cdf70d14ec7f8aec5793a029e2a25b655ae642b3bd94b826d3b9b6a16de5e'),
  ('en.sahih', 23, 3, 2676, 'And they who turn away from ill speech', NULL, NULL, 'c61e18b8cf09f89c65e94d5d0d36f49290bf6cdde4de3b3b4fc9e3a3f4fe7d10'),
  ('en.sahih', 23, 4, 2677, 'And they who are observant of zakah', NULL, NULL, 'b1ef4fa83c310ca66604ff4c94b710d84b1e9666d4f05003df0b2c5e7b40087c'),
  ('en.sahih', 23, 5, 2678, 'And they who guard their private parts', NULL, NULL, '27c4d6b194ee75994048976a4e0710137f36c7aff3fafe90bfe7465a323c8845'),
  ('en.sahih', 23, 6, 2679, 'Except from their wives or those their right hands possess, for indeed, they will not be blamed -', NULL, NULL, '27d5e948aacfec7d5b2c95a3fafd4d500af76f25ea8d61c01253f53d37529f65'),
  ('en.sahih', 23, 7, 2680, 'But whoever seeks beyond that, then those are the transgressors -', NULL, NULL, 'f68c6232e8de8458eef28b3998f6b93113a0e6f6e2c0a2f52325ac80e78aae34'),
  ('en.sahih', 23, 8, 2681, 'And they who are to their trusts and their promises attentive', NULL, NULL, 'f4085d8953bc5ffaee3d2a7d7d3819d38de7754cfaf5e8a3c8f4a372cf67f66e'),
  ('en.sahih', 23, 9, 2682, 'And they who carefully maintain their prayers -', NULL, NULL, 'f3375e72150ed3793d49b9c4cd0ca9cdced9d61b5b9d36b244589120be15224e'),
  ('en.sahih', 23, 10, 2683, 'Those are the inheritors', NULL, NULL, 'bde17c8af99576e97f7081cce21a4b8772ccab95877c6bee7b0e3aa72533f700'),
  ('en.sahih', 23, 11, 2684, 'Who will inherit al-Firdaus. They will abide therein eternally.', NULL, NULL, 'a36e77938331e7ec7d9f934b86e02ad9418371fd90ad624b2c2d8ad8cdc0ae7d'),
  ('en.sahih', 23, 12, 2685, 'And certainly did We create man from an extract of clay.', NULL, NULL, 'f2812eeeecf136515405985504806b57a13f9f472010636a0662075e4e41fa9d'),
  ('en.sahih', 23, 13, 2686, 'Then We placed him as a sperm-drop in a firm lodging.', NULL, NULL, '4556e10317dc8d1a6d06e9d86677bcd55f7494b6e46f58ee0a682862d5f0ce15'),
  ('en.sahih', 23, 14, 2687, 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators.', NULL, NULL, '91aa66214af5046813497fa929eb64302ca7a44fd12e76973bf252a58a9d5b16'),
  ('en.sahih', 23, 15, 2688, 'Then indeed, after that you are to die.', NULL, NULL, '80723e70a1ce6dc378dd0a95ddddd9090f98f5cd80c9ecd97d7c44ad5eb8964f'),
  ('en.sahih', 23, 16, 2689, 'Then indeed you, on the Day of Resurrection, will be resurrected.', NULL, NULL, 'd7b4e3d86bd752bd3b48da91cdecc9521f4fd6968c835038d3eae1056577eb18'),
  ('en.sahih', 23, 17, 2690, 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.', NULL, NULL, '3e2ab73c24c9a6b492dffcc1c6e46ca482fc45f9caef078c154fb8dbfb58e161'),
  ('en.sahih', 23, 18, 2691, 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.', NULL, NULL, '783556152f48dae888ad534bd051563fe5eec4faa6c25b4172ac64ec11e98083'),
  ('en.sahih', 23, 19, 2692, 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.', NULL, NULL, '999d0360fce7b1a93d330d5b2dd9e61a0dff6806546902abd1bb443f6068bcf9'),
  ('en.sahih', 23, 20, 2693, 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat.', NULL, NULL, 'fe171f88232d714199f44b873cefa23fe2925bcbeb6c3a68d67a5f99e97ddb44'),
  ('en.sahih', 23, 21, 2694, 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.', NULL, NULL, 'fe9809963850adb4ff24bd44894dbc0dd76950762c710bf9ecd4eda5469de903'),
  ('en.sahih', 23, 22, 2695, 'And upon them and on ships you are carried.', NULL, NULL, '11205a21c680a80d505641e0bb4c222aec2213e3a2ca4b0261f290add2cb25b2'),
  ('en.sahih', 23, 23, 2696, 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him; then will you not fear Him?"', NULL, NULL, '825d6945e261bbd471eefa907af59dbe9e35bea701f32ecbb0a0cb255d4ac5a9'),
  ('en.sahih', 23, 24, 2697, 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.', NULL, NULL, '5829f760b9c038fb2608b407a3262956f25c49bc828be9a49215e36b29a59d77'),
  ('en.sahih', 23, 25, 2698, 'He is not but a man possessed with madness, so wait concerning him for a time."', NULL, NULL, 'efb503230e358bf6843d6c80b05b8b68bec97b1aa6593f1a9bf1d728991062cc'),
  ('en.sahih', 23, 26, 2699, '[Noah] said, "My Lord, support me because they have denied me."', NULL, NULL, 'f8d8c8fed6cfe01d5c0415595c4a8dfe0266c12c3edc80d30803bfecabdc56c9'),
  ('en.sahih', 23, 27, 2700, 'So We inspired to him, "Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.', NULL, NULL, '0bf58450be1b03e9879d2a9eba418608fb473f3e23039c4b3f34e50c0b379eca')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 23, 28, 2701, 'And when you have boarded the ship, you and those with you, then say, ''Praise to Allah who has saved us from the wrongdoing people.''', NULL, NULL, '596ce23ba93ffd28aed44263734b98c2db2caa77b36301b70439a24db5a00398'),
  ('en.sahih', 23, 29, 2702, 'And say, ''My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].'' "', NULL, NULL, 'ceefdd2ff39c29f1fe623e11c4f2066e89c0f4abb174bad7f081b1d0c778440a'),
  ('en.sahih', 23, 30, 2703, 'Indeed in that are signs, and indeed, We are ever testing [Our servants].', NULL, NULL, '0ef4fbb3d3426e799cc11c372a42c15b659c3db560175ed54196d33d532d85e5'),
  ('en.sahih', 23, 31, 2704, 'Then We produced after them a generation of others.', NULL, NULL, 'f149440ab1238256532c7a312f2efdfaeb4cea3bc34782b0ade93151c3778a41'),
  ('en.sahih', 23, 32, 2705, 'And We sent among them a messenger from themselves, [saying], "Worship Allah; you have no deity other than Him; then will you not fear Him?"', NULL, NULL, 'aab292b4cc0214cc3db4a2d8aa6a739aefd60654a959e3a27403cbc10424a18f'),
  ('en.sahih', 23, 33, 2706, 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.', NULL, NULL, '5d90a2a757b2a27652707164aa15132c84f81cce6afb2f7b02718be8e6a57455'),
  ('en.sahih', 23, 34, 2707, 'And if you should obey a man like yourselves, indeed, you would then be losers.', NULL, NULL, 'c2b82759075b9c23a25118a604ff19c0f0c9a0e730f97d9ad3b63a8ca54a8c03'),
  ('en.sahih', 23, 35, 2708, 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?', NULL, NULL, '129425bc5d05a4e2a98ec3832647c60288219ca3c1b67e22c2be48e1fd1a6542'),
  ('en.sahih', 23, 36, 2709, 'How far, how far, is that which you are promised.', NULL, NULL, '78ebe1c7d103c85aa46394354a1bed918a02f1adf8fee5d17edccf947d9011d0'),
  ('en.sahih', 23, 37, 2710, 'Life is not but our worldly life - we die and live, but we will not be resurrected.', NULL, NULL, '469f01e065e8e47ef28b4a2aca0d48eb7875d7a19e42f5efc1f95d29a0b2d06f'),
  ('en.sahih', 23, 38, 2711, 'He is not but a man who has invented a lie about Allah, and we will not believe him."', NULL, NULL, '64a07cb52cb84ea26283a0aa3837a059099d41c2bb2211c19d8817421c9091ef'),
  ('en.sahih', 23, 39, 2712, 'He said, "My Lord, support me because they have denied me."', NULL, NULL, 'f54321eb0f8591ce60cca9ae71afc2629407149063f92798c8839b384eee803f'),
  ('en.sahih', 23, 40, 2713, '[Allah] said, "After a little, they will surely become regretful."', NULL, NULL, 'e2bd2bea8a84b986e10a87a304631e69f38fb5c542c862b76c19e7592847424d'),
  ('en.sahih', 23, 41, 2714, 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.', NULL, NULL, '9d2e23961b91b612572b74746acfe0c572c736a9cf0313c34f027b02b6dadffb'),
  ('en.sahih', 23, 42, 2715, 'Then We produced after them other generations.', NULL, NULL, '64ff432d893dff25644f3b3a2ee5d053a6fc0fee5c8d2eddfe6419967c6fefa1'),
  ('en.sahih', 23, 43, 2716, 'No nation will precede its time [of termination], nor will they remain [thereafter].', NULL, NULL, 'e7e45bbfb6f78f29dd59a0334d0bf1695e7e9ee3f06481caefb4fb1008dc32b2'),
  ('en.sahih', 23, 44, 2717, 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.', NULL, NULL, '64a94807ec445788b817284fc951feac8f4b11b5513a64c91609305762f8762f'),
  ('en.sahih', 23, 45, 2718, 'Then We sent Moses and his brother Aaron with Our signs and a clear authority', NULL, NULL, '516d8693cac2cc89ffdaa2c4281520470770aa331a38b8704bef3f21dfff9bbe'),
  ('en.sahih', 23, 46, 2719, 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.', NULL, NULL, 'e6dae55fe4cb109e28951206197e7b6e0d898ab9c72e7144addfccefdd95ba34'),
  ('en.sahih', 23, 47, 2720, 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"', NULL, NULL, '91f27296cf24507a259ffe64a41098c7bd25aa9cd721284dd387328190288d31'),
  ('en.sahih', 23, 48, 2721, 'So they denied them and were of those destroyed.', NULL, NULL, '272a813697c3b547a691a7af3977f89304ceb609b5ca1679bc7c99ba44d20a9a'),
  ('en.sahih', 23, 49, 2722, 'And We certainly gave Moses the Scripture that perhaps they would be guided.', NULL, NULL, 'abb5295d46a8f142b9de3b76ac34a4760732388b31004ed3dfa8552a0b100f94'),
  ('en.sahih', 23, 50, 2723, 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.', NULL, NULL, 'e88eff1a51ff0058db250d3e6d5395678d902849fa65239f75eabe46abd2591e'),
  ('en.sahih', 23, 51, 2724, '[Allah said], "O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing.', NULL, NULL, 'f44de8a6eb2d7fb2f37c2d8dbaa1488c2eb0a058a0004b20abf5ab24a3c31867'),
  ('en.sahih', 23, 52, 2725, 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."', NULL, NULL, 'add80bacea488d87ee9bf16e89ee5374041ff61b17475f0ccd7ebfb2b5123ba4'),
  ('en.sahih', 23, 53, 2726, 'But the people divided their religion among them into sects - each faction, in what it has, rejoicing.', NULL, NULL, 'ba0729c1ed1f60aa03e600eb85dbc89e29054871c624caf149551f1af0a9a8f7'),
  ('en.sahih', 23, 54, 2727, 'So leave them in their confusion for a time.', NULL, NULL, '577be10ec088bdcfd0569dbdd51bbb152b9bcd20e22d74a3e8382bac43772432'),
  ('en.sahih', 23, 55, 2728, 'Do they think that what We extend to them of wealth and children', NULL, NULL, 'b3aaed7aeeff85a5d3ef300b895bfefde7ca1ccf16432347676189e66dc85096'),
  ('en.sahih', 23, 56, 2729, 'Is [because] We hasten for them good things? Rather, they do not perceive.', NULL, NULL, '0c26209460f4c8095c46cce870dc22ee23ddabdb84b246b0ef2e249ee3529e5b'),
  ('en.sahih', 23, 57, 2730, 'Indeed, they who are apprehensive from fear of their Lord', NULL, NULL, '396cd4b26ca4e3646055d4476a47e280b8140c7fcf75a4ecd1927375787b45bc'),
  ('en.sahih', 23, 58, 2731, 'And they who believe in the signs of their Lord', NULL, NULL, 'b53eebead0f817a7fce0083b4268b23ecd5285d9fd1a682ac40e5b16bdefa433'),
  ('en.sahih', 23, 59, 2732, 'And they who do not associate anything with their Lord', NULL, NULL, '78fbf18f4b3128fc9e8b511f81afc38e2a42338670e913d891ee22597fd87e96'),
  ('en.sahih', 23, 60, 2733, 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -', NULL, NULL, '2724c8306ef104a8d3fd70cb77b7c3be843326f2cc9cf05baa9e3b0b52ae5592'),
  ('en.sahih', 23, 61, 2734, 'It is those who hasten to good deeds, and they outstrip [others] therein.', NULL, NULL, '07ac6d3a2cdc9a9f5e30fb8c7dc99e831700836528fec089afc8827f01a56c03'),
  ('en.sahih', 23, 62, 2735, 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.', NULL, NULL, '2e36ee86fa37ef9cfb98963b95425d2b41894c2ba6ecbe1f0588e93f862e1104'),
  ('en.sahih', 23, 63, 2736, 'But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,', NULL, NULL, '8ea1344eab71bc7563f69e46fda66eff6add4ce3006ae0b69beae53ff653a5ac'),
  ('en.sahih', 23, 64, 2737, 'Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help.', NULL, NULL, 'dd77b652546b31b126d948d61dfbebe7bd36fc307b648e26dbdadfda2b48662a'),
  ('en.sahih', 23, 65, 2738, 'Do not cry out today. Indeed, by Us you will not be helped.', NULL, NULL, '617df8cfdece83a7dc8cf04ad1e6bd11794c0a1ec55191ed509d04b37278fd29'),
  ('en.sahih', 23, 66, 2739, 'My verses had already been recited to you, but you were turning back on your heels', NULL, NULL, 'cf9cfb7b2c65df7b83e6f706199c937b9726fa67dddc81161805b81258373590'),
  ('en.sahih', 23, 67, 2740, 'In arrogance regarding it, conversing by night, speaking evil.', NULL, NULL, 'a32c66d9d924bdb0670dcac7d6f3c25f6e1bc8f53dbf1319eaa58533d8601ee5'),
  ('en.sahih', 23, 68, 2741, 'Then have they not reflected over the Qur''an, or has there come to them that which had not come to their forefathers?', NULL, NULL, 'db4c3cc15f0c00f12d5f39fce4ea664421f96161b750634d8f4f13a1a734e19a'),
  ('en.sahih', 23, 69, 2742, 'Or did they not know their Messenger, so they are toward him disacknowledging?', NULL, NULL, '11e4b201769a775d287c7ce81d4aa1908226295f329dee36357dc82e4abb3261'),
  ('en.sahih', 23, 70, 2743, 'Or do they say, "In him is madness?" Rather, he brought them the truth, but most of them, to the truth, are averse.', NULL, NULL, 'd1e20fcabdb80f65741251220537716d483227d75193bf66be8a54c1d7bf2fb0'),
  ('en.sahih', 23, 71, 2744, 'But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.', NULL, NULL, 'dc9f8d08b299c441a43b1d04c7e3f02ddb2bb6b98ffcfb13bc27119c1d90928b'),
  ('en.sahih', 23, 72, 2745, 'Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.', NULL, NULL, 'baf1b56701f338e134799efe866b92dffbd7c8fd4e0715c5a91502c947483054'),
  ('en.sahih', 23, 73, 2746, 'And indeed, you invite them to a straight path.', NULL, NULL, '9e4b5923b089cbab74059c9fe97d6967e940e5ab09d152d95bd647191eed445d'),
  ('en.sahih', 23, 74, 2747, 'But indeed, those who do not believe in the Hereafter are deviating from the path.', NULL, NULL, '52d1e52bcf8a63d05d2a1f9e25b98508b78ad9df77afc15e20d000464fa33dbd'),
  ('en.sahih', 23, 75, 2748, 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.', NULL, NULL, 'f3f2826209c0ace1175e53977fd49cec784e41206acf6e74b856cf3378e06ca0'),
  ('en.sahih', 23, 76, 2749, 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]', NULL, NULL, 'a8e8dea2559671037d26d4f9091226cc73f463077d8c0db837f6bce3874871dc'),
  ('en.sahih', 23, 77, 2750, 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.', NULL, NULL, '0bce33df15ad41a7b6483fefae68c3ada23ec0949de123adeb8751cf1d9a067a'),
  ('en.sahih', 23, 78, 2751, 'And it is He who produced for you hearing and vision and hearts; little are you grateful.', NULL, NULL, 'd5ccb3db8dcbeb0460880ee029f4ea327f301174fa70e27d52c9d30e141ebdb4'),
  ('en.sahih', 23, 79, 2752, 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.', NULL, NULL, '5d0b5171214ba750c5ace0380d9dbc88747d769253c8b5f7977ad0e11bf3481c'),
  ('en.sahih', 23, 80, 2753, 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?', NULL, NULL, '916a7dc4b37b8527d38366ae83672c916a636ad0c1a4985573b3fae54367091c'),
  ('en.sahih', 23, 81, 2754, 'Rather, they say like what the former peoples said.', NULL, NULL, 'f4a5b6f2382a37492fdf17015e6b9e948921791a89d5c7cf0aa7cad8dcca4c88'),
  ('en.sahih', 23, 82, 2755, 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?', NULL, NULL, 'e255ba4b3c20a52279b4ea62fa97f7d2bb6b99b8b56c6cd7fcdc8e6679d5a99d'),
  ('en.sahih', 23, 83, 2756, 'We have been promised this, we and our forefathers, before; this is not but legends of the former peoples."', NULL, NULL, 'ba23095b1f6e30c8575c1b0b2aa12b66dd2369e2abe0b795be706959b56aa106'),
  ('en.sahih', 23, 84, 2757, 'Say, [O Muhammad], "To whom belongs the earth and whoever is in it, if you should know?"', NULL, NULL, 'ff7c425b2b32639a653832f68b4be8d7164797c443efcf5dbaf699224aaba8fd'),
  ('en.sahih', 23, 85, 2758, 'They will say, "To Allah." Say, "Then will you not remember?"', NULL, NULL, '1892e219bcfc8582e264d96c2361423e4e2e78c75bba687d695effe86439a94b'),
  ('en.sahih', 23, 86, 2759, 'Say, "Who is Lord of the seven heavens and Lord of the Great Throne?"', NULL, NULL, '4cf2441afcb970290331adfd8ed38977f412eea6256f2fa81478a267785954b7'),
  ('en.sahih', 23, 87, 2760, 'They will say, "[They belong] to Allah." Say, "Then will you not fear Him?"', NULL, NULL, 'a634e30f73009b9e97522c9d48bed1db5f0f82450bac94367a33e527bb2fa328'),
  ('en.sahih', 23, 88, 2761, 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"', NULL, NULL, '47b6f162a36a3459c5d541691dad6a28e628e89c7f49404653ed4cac4a381f0a'),
  ('en.sahih', 23, 89, 2762, 'They will say, "[All belongs] to Allah." Say, "Then how are you deluded?"', NULL, NULL, '4fd29084bfe951cea19d5a43e9e090d7350c0fad1bfa9bb576480c1bf02e7478'),
  ('en.sahih', 23, 90, 2763, 'Rather, We have brought them the truth, and indeed they are liars.', NULL, NULL, '7b29a34284579a571cf9e2417af43b787305c5b24e2a0aa80a52801f67aa5002'),
  ('en.sahih', 23, 91, 2764, 'Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him].', NULL, NULL, '1134680116f11c6bbc60a6e798f51953a456b6e28e0a295bd436e42b45e4f5fa'),
  ('en.sahih', 23, 92, 2765, '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].', NULL, NULL, '3ceab261ccd9a3631373b65dec3dd2195b5f2417479b1251e94d34fd26002a5b'),
  ('en.sahih', 23, 93, 2766, 'Say, [O Muhammad], "My Lord, if You should show me that which they are promised,', NULL, NULL, '52ae4cc83c3430e6da01272e62efee826abbdcf8bab3216b71d5e15bb9140b5a'),
  ('en.sahih', 23, 94, 2767, 'My Lord, then do not place me among the wrongdoing people."', NULL, NULL, 'f187b4082f6e0f8e2b4d83fb84937f128cb4277040b1e575ceb10a21a6ec75fb'),
  ('en.sahih', 23, 95, 2768, 'And indeed, We are able to show you what We have promised them.', NULL, NULL, 'cf8dbaebbad4b7749966a67c1b1afec886603556294469ea7b34b9119fde058d'),
  ('en.sahih', 23, 96, 2769, 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.', NULL, NULL, '28c76bd79e93daec861d3c6629698ad7c67ee21eec52a2aed678cb099574cef8'),
  ('en.sahih', 23, 97, 2770, 'And say, "My Lord, I seek refuge in You from the incitements of the devils,', NULL, NULL, '57e3f565b042b8cacae3093da26be8a484e968d4cfee10c3fdd9cc0a0b2b4c0e'),
  ('en.sahih', 23, 98, 2771, 'And I seek refuge in You, my Lord, lest they be present with me."', NULL, NULL, 'bda2325010f0cadc95aba1ebb2d519eb7efaebc3a45a00477c456ee02013c405'),
  ('en.sahih', 23, 99, 2772, '[For such is the state of the disbelievers], until, when death comes to one of them, he says, "My Lord, send me back', NULL, NULL, '5427ee17328fcdac2904f0ee8597c29ac142de08c0623c1fe8812f5655947df4'),
  ('en.sahih', 23, 100, 2773, 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.', NULL, NULL, 'c7b5257ec5b858c2d40c6b88c1599516f09a468bb6dc391e33398367e4554e31'),
  ('en.sahih', 23, 101, 2774, 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.', NULL, NULL, 'b838721d5ec9b8320301670703e4679d4d03f0c43b95f57145947344eb32319b'),
  ('en.sahih', 23, 102, 2775, 'And those whose scales are heavy [with good deeds] - it is they who are the successful.', NULL, NULL, 'a8f5d2d2fff280b991fe35b805b6663b27579d7507d18740b3bfaf69d4216586'),
  ('en.sahih', 23, 103, 2776, 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.', NULL, NULL, 'c176ba43f326707541af6a230cb4289e384008235ffbc9759e5710f16da55285'),
  ('en.sahih', 23, 104, 2777, 'The Fire will sear their faces, and they therein will have taut smiles.', NULL, NULL, '576160f486bd8338b009fceab0afc28f3f4f6b6799f1c3225256a888c49244df'),
  ('en.sahih', 23, 105, 2778, '[It will be said]. "Were not My verses recited to you and you used to deny them?"', NULL, NULL, '74bc4490efa83f38a2dcb303459541399a05be9633fb1c217e444f18ffc86fa1'),
  ('en.sahih', 23, 106, 2779, 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.', NULL, NULL, '4fd9fc4eb932ad1efde8e66831dfc1d321453bb101b47ed01493b32f08f12116'),
  ('en.sahih', 23, 107, 2780, 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."', NULL, NULL, '1e270fe0f12808dc28381b2cd456c58d8430cd8679434904faf6ba351be48758'),
  ('en.sahih', 23, 108, 2781, 'He will say, "Remain despised therein and do not speak to Me.', NULL, NULL, '0340bd0bc8d39521e92b28ead6ba771abb2e0db336a589da3a2dd276c2e41d3b'),
  ('en.sahih', 23, 109, 2782, 'Indeed, there was a party of My servants who said, ''Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.''', NULL, NULL, 'db07d4f473b209038912ce018a2df9d879121db194473fb2cc92e68488bf6cc5'),
  ('en.sahih', 23, 110, 2783, 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.', NULL, NULL, '89e32746fb62b42a392f795f87cacf36ba206213929746a22afa6b74e318dccc'),
  ('en.sahih', 23, 111, 2784, 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."', NULL, NULL, '19ec05bc3bab04044099a36ddc3df8160f2bd3e953dafbdae1e1edd01fa29275'),
  ('en.sahih', 23, 112, 2785, '[Allah] will say, "How long did you remain on earth in number of years?"', NULL, NULL, '3ac972a522abe5b183b4c5f9550095e33e5d3391946aabc861b1307e9502b304'),
  ('en.sahih', 23, 113, 2786, 'They will say, "We remained a day or part of a day; ask those who enumerate."', NULL, NULL, '4566c79a6816af490edc82066ad31ceff71a51eb45a240f3a76470225af627e7'),
  ('en.sahih', 23, 114, 2787, 'He will say, "You stayed not but a little - if only you had known.', NULL, NULL, 'f4cf044c7cba3af823be75769a4547111812acbcaa344103b45b437c293eeddf'),
  ('en.sahih', 23, 115, 2788, 'Then did you think that We created you uselessly and that to Us you would not be returned?"', NULL, NULL, 'f5ea8237ebe557e50ddd68fa41a95eb87881ebcd6709c7c8b16be4449f41e4c8'),
  ('en.sahih', 23, 116, 2789, 'So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.', NULL, NULL, 'e2860593701855c79e49d60ae5eceda1c688a37af9e9512a6898cb1ce999932d'),
  ('en.sahih', 23, 117, 2790, 'And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.', NULL, NULL, '67371796b71482076da64afd174ce86fab732883e3fb3c2e39bcd36b0557e116'),
  ('en.sahih', 23, 118, 2791, 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."', NULL, NULL, '75a6f2626229d5e96d9ad8d9589421a317be8430d82fc5757aadeed8faacba1a'),
  ('en.sahih', 24, 1, 2792, '[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.', NULL, NULL, 'd14f16f513fc1b6800aa58ce3788ae193fcf68a41afd4a7c76af6307eb380e4a'),
  ('en.sahih', 24, 2, 2793, 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment.', NULL, NULL, '3a894dee02f94fb20eb05e1053ec9fdc4fb7a30363fc2a12064267954cb75ecd'),
  ('en.sahih', 24, 3, 2794, 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers.', NULL, NULL, '5368dcdb2a2a0f3aba289a69e446a9b3341bc318f6882e802db75897a112b951'),
  ('en.sahih', 24, 4, 2795, 'And those who accuse chaste women and then do not produce four witnesses - lash them with eighty lashes and do not accept from them testimony ever after. And those are the defiantly disobedient,', NULL, NULL, '31dda62a27c9ad91a8011705a0d37666dfb48b085671f7ff5fb6dc170361d3f4'),
  ('en.sahih', 24, 5, 2796, 'Except for those who repent thereafter and reform, for indeed, Allah is Forgiving and Merciful.', NULL, NULL, '042aa6e0bcee6bb557dc8db7a5f47f205cdd1f56b3f67ee5bd3d88be47bff585'),
  ('en.sahih', 24, 6, 2797, 'And those who accuse their wives [of adultery] and have no witnesses except themselves - then the witness of one of them [shall be] four testimonies [swearing] by Allah that indeed, he is of the truthful.', NULL, NULL, '6c53b6724bc07c203d7243d71174dcb7273c06c9f50cb197d8f7ae0a44c95b2e'),
  ('en.sahih', 24, 7, 2798, 'And the fifth [oath will be] that the curse of Allah be upon him if he should be among the liars.', NULL, NULL, 'f8fa82c8cf44001873d7c62e81137f70b434599088e2d5778efcae29b4ae3fb3'),
  ('en.sahih', 24, 8, 2799, 'But it will prevent punishment from her if she gives four testimonies [swearing] by Allah that indeed, he is of the liars.', NULL, NULL, 'c9d4d299b4714e473f596156558dd83be8259423896e233ca36fed3242594c57'),
  ('en.sahih', 24, 9, 2800, 'And the fifth [oath will be] that the wrath of Allah be upon her if he was of the truthful.', NULL, NULL, '68dd3c59b74f11d713ff6d8dbf6c7057cb87c2fceb55bf3a177f741bc6a28b40')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 24, 10, 2801, 'And if not for the favor of Allah upon you and His mercy... and because Allah is Accepting of repentance and Wise.', NULL, NULL, '441798644419ec49f6858eb6cb67fa2cc9a50daa05519755d3dbef2528b94725'),
  ('en.sahih', 24, 11, 2802, 'Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather it is good for you. For every person among them is what [punishment] he has earned from the sin, and he who took upon himself the greater portion thereof - for him is a great punishment.', NULL, NULL, 'ec403a025aac4e6d91a04b54766a1b1e8f757ee4ea477d2c561143f8f1a0cbff'),
  ('en.sahih', 24, 12, 2803, 'Why, when you heard it, did not the believing men and believing women think good of one another and say, "This is an obvious falsehood"?', NULL, NULL, '09083eb8d2c606c8fcf3d931916a4a00811e46ce79781d437c63507264ae88af'),
  ('en.sahih', 24, 13, 2804, 'Why did they [who slandered] not produce for it four witnesses? And when they do not produce the witnesses, then it is they, in the sight of Allah, who are the liars.', NULL, NULL, 'f00e07d55f301a93159d43ed21a783cb595cf9924dc49865bec6cd5bfbbaede3'),
  ('en.sahih', 24, 14, 2805, 'And if it had not been for the favor of Allah upon you and His mercy in this world and the Hereafter, you would have been touched for that [lie] in which you were involved by a great punishment', NULL, NULL, 'dc5a4f9a8e6ab9b24be07dc34eca9e54d477f857256832b5de6c2af128bad930'),
  ('en.sahih', 24, 15, 2806, 'When you received it with your tongues and said with your mouths that of which you had no knowledge and thought it was insignificant while it was, in the sight of Allah, tremendous.', NULL, NULL, '333cb90d47ed3bd3625f762fda1afae77a1290046a141e47568a36fa7c350d8c'),
  ('en.sahih', 24, 16, 2807, 'And why, when you heard it, did you not say, "It is not for us to speak of this. Exalted are You, [O Allah]; this is a great slander"?', NULL, NULL, '43b046dc4deebdeff3c7ce0a7850ed0d46f6fa02bdf4286647e0fa47c5aed39f'),
  ('en.sahih', 24, 17, 2808, 'Allah warns you against returning to the likes of this [conduct], ever, if you should be believers.', NULL, NULL, '5e0916c7c31291a3f3f5bf92d80b7257d6284fb969e9f57df846dad50f892e66'),
  ('en.sahih', 24, 18, 2809, 'And Allah makes clear to you the verses, and Allah is Knowing and Wise.', NULL, NULL, 'e6ac7bd02e29453103b9d95549441a1c5fe9e5dcb8b2dc237f5ed89281e41ee7'),
  ('en.sahih', 24, 19, 2810, 'Indeed, those who like that immorality should be spread [or publicized] among those who have believed will have a painful punishment in this world and the Hereafter. And Allah knows and you do not know.', NULL, NULL, '75ece5bff0effda3e6140307fb08441d0c0a7afcf51d32968c995f0a72485098'),
  ('en.sahih', 24, 20, 2811, 'And if it had not been for the favor of Allah upon you and His mercy... and because Allah is Kind and Merciful.', NULL, NULL, '54b52fcaedc0b3510d0cbd2b0e3c92fafa1f202562019eed9db93bc01ef58463'),
  ('en.sahih', 24, 21, 2812, 'O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allah upon you and His mercy, not one of you would have been pure, ever, but Allah purifies whom He wills, and Allah is Hearing and Knowing.', NULL, NULL, '1299573db0299bb7c28906de063ec1b794e38dae8724c3fa71c1c2a4fc73112e'),
  ('en.sahih', 24, 22, 2813, 'And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allah, and let them pardon and overlook. Would you not like that Allah should forgive you? And Allah is Forgiving and Merciful.', NULL, NULL, 'f215767e25ae366fb4690f079eb3975d42c75c4d8ca829fba1df4d11c3ddb36f'),
  ('en.sahih', 24, 23, 2814, 'Indeed, those who [falsely] accuse chaste, unaware and believing women are cursed in this world and the Hereafter; and they will have a great punishment', NULL, NULL, 'fa996a15e692ab3ac6756c0d77b3f03ccb87c933df7d6c2321242472bb1513dd'),
  ('en.sahih', 24, 24, 2815, 'On a Day when their tongues, their hands and their feet will bear witness against them as to what they used to do.', NULL, NULL, '07a66207bfb4c1e6dbe2fdb6a4212debd759f918995d4d273e122d454d030eed'),
  ('en.sahih', 24, 25, 2816, 'That Day, Allah will pay them in full their deserved recompense, and they will know that it is Allah who is the perfect in justice.', NULL, NULL, 'c2c0965f7915b94c804d7ce7c326fe046a366d2cc40d93de4a49ae44a288aa10'),
  ('en.sahih', 24, 26, 2817, 'Evil words are for evil men, and evil men are [subjected] to evil words. And good words are for good men, and good men are [an object] of good words. Those [good people] are declared innocent of what the slanderers say. For them is forgiveness and noble provision.', NULL, NULL, '5ea2647ba194dae6ca0003f82f967c63d6ba3547f2eefdeb5c7f7278187db4e7'),
  ('en.sahih', 24, 27, 2818, 'O you who have believed, do not enter houses other than your own houses until you ascertain welcome and greet their inhabitants. That is best for you; perhaps you will be reminded.', NULL, NULL, '75a7102d5c6faa3aed6c352c031964e1ccf0ab5c47712f2492d5fcd6fac7b538'),
  ('en.sahih', 24, 28, 2819, 'And if you do not find anyone therein, do not enter them until permission has been given you. And if it is said to you, "Go back," then go back; it is purer for you. And Allah is Knowing of what you do.', NULL, NULL, '6ed40818aea19f58c28780254d916cc6213171f78fa2044344b31bbd0e023b29'),
  ('en.sahih', 24, 29, 2820, 'There is no blame upon you for entering houses not inhabited in which there is convenience for you. And Allah knows what you reveal and what you conceal.', NULL, NULL, '1848c4c84d7fa7af714e2c7aa31aa17819893fec7b3c346b0dcedad9f289b4df'),
  ('en.sahih', 24, 30, 2821, 'Tell the believing men to reduce [some] of their vision and guard their private parts. That is purer for them. Indeed, Allah is Acquainted with what they do.', NULL, NULL, '02b89c52fbeed5e0712ac899faa5639baecdc2ff2258803bf24bf5a9956ed709'),
  ('en.sahih', 24, 31, 2822, 'And tell the believing women to reduce [some] of their vision and guard their private parts and not expose their adornment except that which [necessarily] appears thereof and to wrap [a portion of] their headcovers over their chests and not expose their adornment except to their husbands, their fathers, their husbands'' fathers, their sons, their husbands'' sons, their brothers, their brothers'' sons, their sisters'' sons, their women, that which their right hands possess, or those male attendants having no physical desire, or children who are not yet aware of the private aspects of women. And let them not stamp their feet to make known what they conceal of their adornment. And turn to Allah in repentance, all of you, O believers, that you might succeed.', NULL, NULL, '15c0c86c094fb2fbab6314febb37ad56c72379ba7ab7eb5a25a6c03d95ba4b6b'),
  ('en.sahih', 24, 32, 2823, 'And marry the unmarried among you and the righteous among your male slaves and female slaves. If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing and Knowing.', NULL, NULL, '3e2dd72b83024ba464ee00561d87469de7f3ca8934fbfa13df72250312a5589f'),
  ('en.sahih', 24, 33, 2824, 'But let them who find not [the means for] marriage abstain [from sexual relations] until Allah enriches them from His bounty. And those who seek a contract [for eventual emancipation] from among whom your right hands possess - then make a contract with them if you know there is within them goodness and give them from the wealth of Allah which He has given you. And do not compel your slave girls to prostitution, if they desire chastity, to seek [thereby] the temporary interests of worldly life. And if someone should compel them, then indeed, Allah is [to them], after their compulsion, Forgiving and Merciful.', NULL, NULL, '188a0974df31724fd599047bf557bfcd0dfbac7137cd64516cbe9468e370c835'),
  ('en.sahih', 24, 34, 2825, 'And We have certainly sent down to you distinct verses and examples from those who passed on before you and an admonition for those who fear Allah.', NULL, NULL, '698ef6829cca6e5b542c4ea33043c7fdaa067305895a9e906270ee2269f05d0f'),
  ('en.sahih', 24, 35, 2826, 'Allah is the Light of the heavens and the earth. The example of His light is like a niche within which is a lamp, the lamp is within glass, the glass as if it were a pearly [white] star lit from [the oil of] a blessed olive tree, neither of the east nor of the west, whose oil would almost glow even if untouched by fire. Light upon light. Allah guides to His light whom He wills. And Allah presents examples for the people, and Allah is Knowing of all things.', NULL, NULL, 'e525a47c625bfb07a1b7b69620eff601403baf1536cd365df819b7eee8865367'),
  ('en.sahih', 24, 36, 2827, '[Such niches are] in mosques which Allah has ordered to be raised and that His name be mentioned therein; exalting Him within them in the morning and the evenings', NULL, NULL, '8100490df3f3f34b3b14e6f4f615f39dca66452a9057cef9be9a13a041f7cfa2'),
  ('en.sahih', 24, 37, 2828, '[Are] men whom neither commerce nor sale distracts from the remembrance of Allah and performance of prayer and giving of zakah. They fear a Day in which the hearts and eyes will [fearfully] turn about -', NULL, NULL, 'df5295a7032b3d0f1aa0d0c8051be7af528090d25c43c92e20328319f7299c6a'),
  ('en.sahih', 24, 38, 2829, 'That Allah may reward them [according to] the best of what they did and increase them from His bounty. And Allah gives provision to whom He wills without account.', NULL, NULL, '3501c1005d8f4eb2d6d33c7a1d2d5a9a0c218409c434f37486aa28c6960a9a86'),
  ('en.sahih', 24, 39, 2830, 'But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allah before Him, and He will pay him in full his due; and Allah is swift in account.', NULL, NULL, '69235eaa4239d697cd8488adcdbfea35690cf9abeaf46b4827454f098f9c17e6'),
  ('en.sahih', 24, 40, 2831, 'Or [they are] like darknesses within an unfathomable sea which is covered by waves, upon which are waves, over which are clouds - darknesses, some of them upon others. When one puts out his hand [therein], he can hardly see it. And he to whom Allah has not granted light - for him there is no light.', NULL, NULL, '0b530b53b6d9da7a9eeb460efb5fc85ab275cf89bbe5ee72d14f53c53e6bd6e1'),
  ('en.sahih', 24, 41, 2832, 'Do you not see that Allah is exalted by whomever is within the heavens and the earth and [by] the birds with wings spread [in flight]? Each [of them] has known his [means of] prayer and exalting [Him], and Allah is Knowing of what they do.', NULL, NULL, 'dcf9d7c42f853946ac7d69c5f3f12e7d752c8749be8d5e12fb4c042cf3027079'),
  ('en.sahih', 24, 42, 2833, 'And to Allah belongs the dominion of the heavens and the earth, and to Allah is the destination.', NULL, NULL, 'fb5ec800860353b6d3116f7a40d55f84de0680ed0a1d5f7919620a7505d2ff95'),
  ('en.sahih', 24, 43, 2834, 'Do you not see that Allah drives clouds? Then He brings them together, then He makes them into a mass, and you see the rain emerge from within it. And He sends down from the sky, mountains [of clouds] within which is hail, and He strikes with it whom He wills and averts it from whom He wills. The flash of its lightening almost takes away the eyesight.', NULL, NULL, 'b5356ac8ae80e7b52096b8ed416ecdad8e803b9044ca8823871892ba0841e528'),
  ('en.sahih', 24, 44, 2835, 'Allah alternates the night and the day. Indeed in that is a lesson for those who have vision.', NULL, NULL, '066049e534ac040e700378dc608f30d70f066972b32c6991d6e05ced2de83e60'),
  ('en.sahih', 24, 45, 2836, 'Allah has created every [living] creature from water. And of them are those that move on their bellies, and of them are those that walk on two legs, and of them are those that walk on four. Allah creates what He wills. Indeed, Allah is over all things competent.', NULL, NULL, '3628fed4e9cb9547b9ee4202078cdde6a3d6b17a231a06d94746566fab485578'),
  ('en.sahih', 24, 46, 2837, 'We have certainly sent down distinct verses. And Allah guides whom He wills to a straight path.', NULL, NULL, 'fee5b5ed9ca4575305ea089f7a8a4b439e0130f846b65c5a81a52903184b4732'),
  ('en.sahih', 24, 47, 2838, 'But the hypocrites say, "We have believed in Allah and in the Messenger, and we obey"; then a party of them turns away after that. And those are not believers.', NULL, NULL, '17cbbc3066f1ee30f130de6bb3ca8d06daa3ca774973e628a6049425412fda9f'),
  ('en.sahih', 24, 48, 2839, 'And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal].', NULL, NULL, 'd512d6521dc62d11f1a1fee634e4be910bccf616ad3991c190d3f0a9dc052064'),
  ('en.sahih', 24, 49, 2840, 'But if the right is theirs, they come to him in prompt obedience.', NULL, NULL, '3107c66d7102cbe60b6a18d4ed02ae412f2b7dc658d61f9e9261379ba77b191b'),
  ('en.sahih', 24, 50, 2841, 'Is there disease in their hearts? Or have they doubted? Or do they fear that Allah will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers.', NULL, NULL, '078f166cb15d6a75d6de296742979a80646e5e39a86ab31e729e95038b5abe7c'),
  ('en.sahih', 24, 51, 2842, 'The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, "We hear and we obey." And those are the successful.', NULL, NULL, '485e7b0737abd72b9168cc9cbe14ce3ca3f9122866b6e9e2a2f3b74f58931b67'),
  ('en.sahih', 24, 52, 2843, 'And whoever obeys Allah and His Messenger and fears Allah and is conscious of Him - it is those who are the attainers.', NULL, NULL, '6cc9c7dee8db2ef9060631fb63da7ba08ac2788af25ad900097cddd7869661a1'),
  ('en.sahih', 24, 53, 2844, 'And they swear by Allah their strongest oaths that if you ordered them, they would go forth [in Allah ''s cause]. Say, "Do not swear. [Such] obedience is known. Indeed, Allah is Acquainted with that which you do."', NULL, NULL, '01a316eff6156ca9276f360c6dd5cfeeb4a831681dd892f960bb2886e37f5212'),
  ('en.sahih', 24, 54, 2845, 'Say, "Obey Allah and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification."', NULL, NULL, 'cc5f6667463b751e41059ee3052076c2b230a177f8cac23bd7fe60eaf9d76376'),
  ('en.sahih', 24, 55, 2846, 'Allah has promised those who have believed among you and done righteous deeds that He will surely grant them succession [to authority] upon the earth just as He granted it to those before them and that He will surely establish for them [therein] their religion which He has preferred for them and that He will surely substitute for them, after their fear, security, [for] they worship Me, not associating anything with Me. But whoever disbelieves after that - then those are the defiantly disobedient.', NULL, NULL, 'c53636be5ab9f351c9a0235f059a6f952558e84c85f86a693b958e952a1ab217'),
  ('en.sahih', 24, 56, 2847, 'And establish prayer and give zakah and obey the Messenger - that you may receive mercy.', NULL, NULL, '6db4a948d1c4d07251a75752acc570108ab28013359350e0ec181e9e8048b8e6'),
  ('en.sahih', 24, 57, 2848, 'Never think that the disbelievers are causing failure [to Allah] upon the earth. Their refuge will be the Fire - and how wretched the destination.', NULL, NULL, 'a4fa0b13477e51813e8ee80cd1167aa66c109ffd9a93122a3c089ad80eae375e'),
  ('en.sahih', 24, 58, 2849, 'O you who have believed, let those whom your right hands possess and those who have not [yet] reached puberty among you ask permission of you [before entering] at three times: before the dawn prayer and when you put aside your clothing [for rest] at noon and after the night prayer. [These are] three times of privacy for you. There is no blame upon you nor upon them beyond these [periods], for they continually circulate among you - some of you, among others. Thus does Allah make clear to you the verses; and Allah is Knowing and Wise.', NULL, NULL, 'c569981337b98b059c967399357fbf41ae80c127e901b7bfe899e6281b578470'),
  ('en.sahih', 24, 59, 2850, 'And when the children among you reach puberty, let them ask permission [at all times] as those before them have done. Thus does Allah make clear to you His verses; and Allah is Knowing and Wise.', NULL, NULL, '06f06f48486a19824e05b8d68fcc572788fcff53e471e28bf83c1a3744e72b23'),
  ('en.sahih', 24, 60, 2851, 'And women of post-menstrual age who have no desire for marriage - there is no blame upon them for putting aside their outer garments [but] not displaying adornment. But to modestly refrain [from that] is better for them. And Allah is Hearing and Knowing.', NULL, NULL, 'e0d0cf23457108f2fe28027898858d0d69033c9bbff6ec4b1d67b62ab437da07'),
  ('en.sahih', 24, 61, 2852, 'There is not upon the blind [any] constraint nor upon the lame constraint nor upon the ill constraint nor upon yourselves when you eat from your [own] houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your father''s brothers or the houses of your father''s sisters or the houses of your mother''s brothers or the houses of your mother''s sisters or [from houses] whose keys you possess or [from the house] of your friend. There is no blame upon you whether you eat together or separately. But when you enter houses, give greetings of peace upon each other - a greeting from Allah, blessed and good. Thus does Allah make clear to you the verses [of ordinance] that you may understand.', NULL, NULL, '9f12c4fde0f63cdbc75ed63fb51e9fce9d8deba2fd8261c17571215da48fbf34'),
  ('en.sahih', 24, 62, 2853, 'The believers are only those who believe in Allah and His Messenger and, when they are [meeting] with him for a matter of common interest, do not depart until they have asked his permission. Indeed, those who ask your permission, [O Muhammad] - those are the ones who believe in Allah and His Messenger. So when they ask your permission for something of their affairs, then give permission to whom you will among them and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, 'aa5de3447374b51fc09281c2f7597ebbd7337a772c931800cb80fe5785683095'),
  ('en.sahih', 24, 63, 2854, 'Do not make [your] calling of the Messenger among yourselves as the call of one of you to another. Already Allah knows those of you who slip away, concealed by others. So let those beware who dissent from the Prophet''s order, lest fitnah strike them or a painful punishment.', NULL, NULL, '25c5e0aa84f258144ecffed047a957db94cd276d223efe6314b4ff67cfc70482'),
  ('en.sahih', 24, 64, 2855, 'Unquestionably, to Allah belongs whatever is in the heavens and earth. Already He knows that upon which you [stand] and [knows] the Day when they will be returned to Him and He will inform them of what they have done. And Allah is Knowing of all things.', NULL, NULL, '9f92cc9939f315273896c8b09d3d35a296e2f85d4dd5cbe2f10be878547950e1'),
  ('en.sahih', 25, 1, 2856, 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -', NULL, NULL, '1ba2ed2cc26fea60e7b7fb2cc76313e3756bc86c0deb544581439f3ec286670a'),
  ('en.sahih', 25, 2, 2857, 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.', NULL, NULL, '0614a7e74279b08bc3afaaf06de6a15e3c624209efe18c4e50f050b9c0ada248'),
  ('en.sahih', 25, 3, 2858, 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.', NULL, NULL, '699909d6e7318637a8b436d7b9f2d82df21dbcdd78fec6bbd63951eba0e1d941'),
  ('en.sahih', 25, 4, 2859, 'And those who disbelieve say, "This [Qur''an] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.', NULL, NULL, '4fb336d8490eec26799dde55f90e163d1ab0834b1f16a887854e9b986b1bba61'),
  ('en.sahih', 25, 5, 2860, 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."', NULL, NULL, 'fe3615a1b8115cefe62bdcca2f0364f2426ac9b301f94ce668b83b0bb5591cfb'),
  ('en.sahih', 25, 6, 2861, 'Say, [O Muhammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."', NULL, NULL, '85688951310d5efe03e17eaa6ff4a0ed9878e0399a0f5ccb0dfa65ba906fcf9d'),
  ('en.sahih', 25, 7, 2862, 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?', NULL, NULL, 'd74e20c15bb08d8b2b9ffcab45af0a51cb10354c80a6ae4b90c1d40579683e9b'),
  ('en.sahih', 25, 8, 2863, 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."', NULL, NULL, '6fe78e794217ed2db98bf64e88eb8dbfa366080cf8737b31413b81afbeb23a9e'),
  ('en.sahih', 25, 9, 2864, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.', NULL, NULL, '25081411324145bc8b440d707de279d6aaaf375c8b4eb3625fe72f5c60ddf4c6'),
  ('en.sahih', 25, 10, 2865, 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.', NULL, NULL, 'ce126a8fc6c270535667c621c62ba846819c989cfbbf768f593d0560513c4534'),
  ('en.sahih', 25, 11, 2866, 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.', NULL, NULL, 'd63520525ebe0a5a43236c2cfed81dba27a5e7f57e9c7347c62e6b421ae256c5'),
  ('en.sahih', 25, 12, 2867, 'When the Hellfire sees them from a distant place, they will hear its fury and roaring.', NULL, NULL, '8cddffcd2d41f3665f34e252ea0e1bc5e21757124c42d00a66fc38dbce2a602c'),
  ('en.sahih', 25, 13, 2868, 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.', NULL, NULL, '01f5caccdad593b9a6577b0ed3ba750e80bb50ec472688c1cbf66046cc5075fc'),
  ('en.sahih', 25, 14, 2869, '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."', NULL, NULL, '7800fc47c804f1387dab3bbc40675aa4d7aa5eb5c541e2474929007077c4dec3'),
  ('en.sahih', 25, 15, 2870, 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.', NULL, NULL, '67c6bc8f451992c83c29e6091efbb00634f4608757207a69e1e721ed77fdee38'),
  ('en.sahih', 25, 16, 2871, 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.', NULL, NULL, '27a7ac412a0b433feb98c77527b100bcc0d5fe0ae30561c0844ff30a762d1169'),
  ('en.sahih', 25, 17, 2872, 'And [mention] the Day He will gather them and that which they worship besides Allah and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"', NULL, NULL, 'a856ab1c2514dd3a5ea6dacdaf63f7f7eec46bf71e628f9788942aae48470d0d'),
  ('en.sahih', 25, 18, 2873, 'They will say, "Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."', NULL, NULL, '5ee2a7c9e867742f95817a179cbc0cc4ce860a9d8f26ba6acfc581781b788b17'),
  ('en.sahih', 25, 19, 2874, 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.', NULL, NULL, 'a869e8d2547bcd3092f5d08d2513ee7ecea2eb020e74e0c0b5d88cc87c03304d'),
  ('en.sahih', 25, 20, 2875, 'And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.', NULL, NULL, 'be466b2d73449163276de45c2730163e44b2d13e485d24f3d7eea4804f38067e'),
  ('en.sahih', 25, 21, 2876, 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.', NULL, NULL, '4c7f2832286b13991c65bbac9f6232539eb4a0f1307cd1c98be0dc248b3882af'),
  ('en.sahih', 25, 22, 2877, 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."', NULL, NULL, 'fb7d26e6435505cbd119e849e5940d0d37392a8724b07ed44862f88597443993'),
  ('en.sahih', 25, 23, 2878, 'And We will regard what they have done of deeds and make them as dust dispersed.', NULL, NULL, '5319bc4ceddbc76b2591450ac8d278447ee537c95854739afa0b294b138367ad'),
  ('en.sahih', 25, 24, 2879, 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.', NULL, NULL, '162d632a4f260e98ab06c1909cb6be5e41bced38dfb86fa39ea3b97f9a54846a'),
  ('en.sahih', 25, 25, 2880, 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.', NULL, NULL, '64bf2f700d3d0b2da2f6ffdb5c38b7f629049baa931e157bb8f999405625bb02'),
  ('en.sahih', 25, 26, 2881, 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.', NULL, NULL, 'be4a24371a0b75d792ba9f0086bbbf469ee3d4c036f417e01911d2572306fe26'),
  ('en.sahih', 25, 27, 2882, 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.', NULL, NULL, 'dbb423aa5755bb055c6fb2b8f4e94a483d7be7545bcae2d619085169ad992285'),
  ('en.sahih', 25, 28, 2883, 'Oh, woe to me! I wish I had not taken that one as a friend.', NULL, NULL, 'c159ea16a137e3ad25a47d43624fd32f4f3c8d2e5316960cb0c341c98b352759'),
  ('en.sahih', 25, 29, 2884, 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."', NULL, NULL, '6cabcf0330871ec092bf2a165dc61d52462cf652961c510ab033084c02516709'),
  ('en.sahih', 25, 30, 2885, 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur''an as [a thing] abandoned."', NULL, NULL, '8f9c5f930707a58fb274f067b05d0a4ae90ae705709bce15149fe62b7405b233'),
  ('en.sahih', 25, 31, 2886, 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.', NULL, NULL, '3a36bae111c5ebfe91fdd0d35652f9bb4c4f1438f701ea72bb21fb62192ca5d8'),
  ('en.sahih', 25, 32, 2887, 'And those who disbelieve say, "Why was the Qur''an not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.', NULL, NULL, '3b09783e7106088d1ca05e479963803e21e0c66f16d87b875a793c62c1df0516'),
  ('en.sahih', 25, 33, 2888, 'And they do not come to you with an argument except that We bring you the truth and the best explanation.', NULL, NULL, '4d5b1a50897201b22175857bfb52b1225b2f861e38e47fdcd4ff5541a4090c3b'),
  ('en.sahih', 25, 34, 2889, 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.', NULL, NULL, '4d30f06e26ccf5ea57fd5098147bc83f3cb9844411f7b5ea88affb56deb765f1'),
  ('en.sahih', 25, 35, 2890, 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.', NULL, NULL, 'bf3fc4edad73009bcc1fd262757234b030b3fbf6de252c4f576bfa84c30f1254'),
  ('en.sahih', 25, 36, 2891, 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.', NULL, NULL, 'ed9e7560f0a9cff99ae3e5897749ff75a09d63e5c2648ad9eca1e50aeed850d5'),
  ('en.sahih', 25, 37, 2892, 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.', NULL, NULL, '4ff0d52ebe0101104cdb0e8cbc4539e6fccb5d8185821e4c600949adb0cf4db1'),
  ('en.sahih', 25, 38, 2893, 'And [We destroyed] ''Aad and Thamud and the companions of the well and many generations between them.', NULL, NULL, 'ed67cdc6af1e8faeedd5ec8d7eb310f4df78e21d5b3fde9429d58903ba94a810'),
  ('en.sahih', 25, 39, 2894, 'And for each We presented examples [as warnings], and each We destroyed with [total] destruction.', NULL, NULL, '67d3b8dc0028842c9b6bf262ad7d94f7ea247f4e833b3d925f9b9128917afb0d'),
  ('en.sahih', 25, 40, 2895, 'And they have already come upon the town which was showered with a rain of evil. So have they not seen it? But they are not expecting resurrection.', NULL, NULL, '6b99a0502d6dba14d930561bcac843a0b536e678d2325257f7aaa042626b66e8'),
  ('en.sahih', 25, 41, 2896, 'And when they see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one whom Allah has sent as a messenger?', NULL, NULL, 'c2b78df839a8d10df1e9665b47566aaff4f1d93504fb0f85c930ee44d2bad348'),
  ('en.sahih', 25, 42, 2897, 'He almost would have misled us from our gods had we not been steadfast in [worship of] them." But they are going to know, when they see the punishment, who is farthest astray in [his] way.', NULL, NULL, '90d52ed399e777b6f75e496e62fa19c176a9cad09e9282dd40635a69d6d6d345'),
  ('en.sahih', 25, 43, 2898, 'Have you seen the one who takes as his god his own desire? Then would you be responsible for him?', NULL, NULL, 'b9a1f1e16aa120cd84ec5d5e71844e57ba348a0c5601d413cb6876b28cb6bff6'),
  ('en.sahih', 25, 44, 2899, 'Or do you think that most of them hear or reason? They are not except like livestock. Rather, they are [even] more astray in [their] way.', NULL, NULL, '0084754e13081bcefd490a12e06dbfce79b6739e872c4d9ab5cb5e81d6133d69'),
  ('en.sahih', 25, 45, 2900, 'Have you not considered your Lord - how He extends the shadow, and if He willed, He could have made it stationary? Then We made the sun for it an indication.', NULL, NULL, '9a3bfb6c7382b8a53e784cbf7935ed606e01b9d93b82d3e55fb86cb110f1cf26')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 25, 46, 2901, 'Then We hold it in hand for a brief grasp.', NULL, NULL, 'dc2fd18c260110762555dc0487d981c92f989a0fdbf8c02668ef4df9ba8fbd9e'),
  ('en.sahih', 25, 47, 2902, 'And it is He who has made the night for you as clothing and sleep [a means for] rest and has made the day a resurrection.', NULL, NULL, '6cb78c2ae1a29e03639635121b342f8449ba12c485f82e50a30c4f8e200761a0'),
  ('en.sahih', 25, 48, 2903, 'And it is He who sends the winds as good tidings before His mercy, and We send down from the sky pure water', NULL, NULL, '4f49a6dace95e1b1c6aa9fd620c578ebfa172b5f4b660b367fba9086888346df'),
  ('en.sahih', 25, 49, 2904, 'That We may bring to life thereby a dead land and give it as drink to those We created of numerous livestock and men.', NULL, NULL, '66259755a514f890db8a5b1c9bdef737516184e9594ed427a4e8adbf0dcb907c'),
  ('en.sahih', 25, 50, 2905, 'And We have certainly distributed it among them that they might be reminded, but most of the people refuse except disbelief.', NULL, NULL, 'b8e2d8c9cf08dd1d421862d359b7ac61488fa928843eec7b5e08099455df0304'),
  ('en.sahih', 25, 51, 2906, 'And if We had willed, We could have sent into every city a warner.', NULL, NULL, '233d133a830332ec7f14bce8f36ea6de6b3ce0ed578e0d81d29aa7e887b0dab6'),
  ('en.sahih', 25, 52, 2907, 'So do not obey the disbelievers, and strive against them with the Qur''an a great striving.', NULL, NULL, '156960434780b4192ac462ec832a55fb3ecf2165e41dff1772508bea799fc527'),
  ('en.sahih', 25, 53, 2908, 'And it is He who has released [simultaneously] the two seas, one fresh and sweet and one salty and bitter, and He placed between them a barrier and prohibiting partition.', NULL, NULL, '67c0001d2938fd316b1eb1c57323273251b598b21b4ef1caaedbfe0e390b85c5'),
  ('en.sahih', 25, 54, 2909, 'And it is He who has created from water a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation].', NULL, NULL, 'c7a4acfacfb273578a20c9811c75fc0df8098ee177e378c2e63b035e06c07745'),
  ('en.sahih', 25, 55, 2910, 'But they worship rather than Allah that which does not benefit them or harm them, and the disbeliever is ever, against his Lord, an assistant [to Satan].', NULL, NULL, '3b541d0e810eea305f3c7d868867b3de38c948509eff42410f5e2d08e9d657d6'),
  ('en.sahih', 25, 56, 2911, 'And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.', NULL, NULL, 'dafaabd6711e2045a4061ddb9c0750f90d2f5cbc2a1177d45b646a5ce0e0db87'),
  ('en.sahih', 25, 57, 2912, 'Say, "I do not ask of you for it any payment - only that whoever wills might take to his Lord a way."', NULL, NULL, 'dc45c6247803ea1f773367e9b0e1c29f32a8fe47ecb03ba9e4d78315cce97975'),
  ('en.sahih', 25, 58, 2913, 'And rely upon the Ever-Living who does not die, and exalt [Allah] with His praise. And sufficient is He to be, with the sins of His servants, Acquainted -', NULL, NULL, '1a890b1b51ec33e2ddde649b41756f6067c33237e82d45ba8c70098f475f2947'),
  ('en.sahih', 25, 59, 2914, 'He who created the heavens and the earth and what is between them in six days and then established Himself above the Throne - the Most Merciful, so ask about Him one well informed.', NULL, NULL, '03be9a82e4c91980b254cb926271dd66e2722667b4a7752d29efddb568eac3ae'),
  ('en.sahih', 25, 60, 2915, 'And when it is said to them, "Prostrate to the Most Merciful," they say, "And what is the Most Merciful? Should we prostrate to that which you order us?" And it increases them in aversion.', NULL, NULL, '4fd158ebf359119053d5bb44641180a1b311ac3ad0d100339951823232702572'),
  ('en.sahih', 25, 61, 2916, 'Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon.', NULL, NULL, 'b4302cddd393467a553559a5940c3f99d494837f948f5cdaae0f7482182701b3'),
  ('en.sahih', 25, 62, 2917, 'And it is He who has made the night and the day in succession for whoever desires to remember or desires gratitude.', NULL, NULL, 'aa4f7cccbda409704cccfe191de97b017b66ed6144c911597dd8ca1378b47406'),
  ('en.sahih', 25, 63, 2918, 'And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace,', NULL, NULL, 'f4c5938a1a9be941d2e795a92dc50122e2c71b089d93d7987ea4456517e603bc'),
  ('en.sahih', 25, 64, 2919, 'And those who spend [part of] the night to their Lord prostrating and standing [in prayer]', NULL, NULL, '540247372e3ea0ee153b17878e6699bc54cd4fa24c3952f0aeb7d96f127a0ed4'),
  ('en.sahih', 25, 65, 2920, 'And those who say, "Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;', NULL, NULL, '7802c0accd1f2b37ae817201eae0a71da1ed501c821dc02251e73cf11a5e0506'),
  ('en.sahih', 25, 66, 2921, 'Indeed, it is evil as a settlement and residence."', NULL, NULL, '5e0b33a38f3b1a200a903dfe0823c881bee18db64cfb3d7ea6f5964bd6d5b9e4'),
  ('en.sahih', 25, 67, 2922, 'And [they are] those who, when they spend, do so not excessively or sparingly but are ever, between that, [justly] moderate', NULL, NULL, '667b14b2ca8329136378788dce53890973d1477d169fbb78c8b05542c6503847'),
  ('en.sahih', 25, 68, 2923, 'And those who do not invoke with Allah another deity or kill the soul which Allah has forbidden [to be killed], except by right, and do not commit unlawful sexual intercourse. And whoever should do that will meet a penalty.', NULL, NULL, '2b1d6c3d21506d1ac1de0d3dbf1b064673283fa0a40ab174fe34dd765ada621e'),
  ('en.sahih', 25, 69, 2924, 'Multiplied for him is the punishment on the Day of Resurrection, and he will abide therein humiliated -', NULL, NULL, '308e38e7871b26fd7c410fef460a330dd79ef1b265fccb59b724f5c414a5d400'),
  ('en.sahih', 25, 70, 2925, 'Except for those who repent, believe and do righteous work. For them Allah will replace their evil deeds with good. And ever is Allah Forgiving and Merciful.', NULL, NULL, 'b28b5643b4f86b42ec5f930e2ffd39aeabce259cad42c6af447456809a8ee2f6'),
  ('en.sahih', 25, 71, 2926, 'And he who repents and does righteousness does indeed turn to Allah with [accepted] repentance.', NULL, NULL, 'f2c6a8ac1066fa4d9298306014ddb087f8b9b9b616ec848e645fc3d52df5b797'),
  ('en.sahih', 25, 72, 2927, 'And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity.', NULL, NULL, 'bc35aeda9f2d2c485001cd4c8f0b97781ff3342784115973765227081a634c81'),
  ('en.sahih', 25, 73, 2928, 'And those who, when reminded of the verses of their Lord, do not fall upon them deaf and blind.', NULL, NULL, '99f31d03c06dab50838a5d1fe3f2982949ff9a84e6b7787ae3972c1187458676'),
  ('en.sahih', 25, 74, 2929, 'And those who say, "Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous."', NULL, NULL, '5e666493404d1bc93795a694f749ca7c1aa10a2b0dc07aa496ec92a7afb3df49'),
  ('en.sahih', 25, 75, 2930, 'Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace.', NULL, NULL, '8121b6053f1d5d5ea47b83851d8b2bb0839ac2e530baf2d1a124299dacb2dc14'),
  ('en.sahih', 25, 76, 2931, 'Abiding eternally therein. Good is the settlement and residence.', NULL, NULL, '104c636916889b090de87b8500c749afd177a33250f76f0a3b155123e76deee0'),
  ('en.sahih', 25, 77, 2932, 'Say, "What would my Lord care for you if not for your supplication?" For you [disbelievers] have denied, so your denial is going to be adherent.', NULL, NULL, 'b42efb5f59deffca78690206802c1b806d9dc88fb41ebd3795e83343f8900347'),
  ('en.sahih', 26, 1, 2933, 'Ta, Seen, Meem.', NULL, NULL, '0ef4275790a43c15542f62fd834a4d45820bf430d4be33209b885d5163b4db79'),
  ('en.sahih', 26, 2, 2934, 'These are the verses of the clear Book.', NULL, NULL, '6802874ff2a5033a4f7f1b8eb6fc22128f011a66754506d268c945ea656d6c4d'),
  ('en.sahih', 26, 3, 2935, 'Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers.', NULL, NULL, '313ec490f223922419cf07b66bfeea23c6def89b3d0f5bd0fa1c245255685332'),
  ('en.sahih', 26, 4, 2936, 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.', NULL, NULL, 'e126eaaf947af56a96867ab1a6a4581a262d38c01f0e2fe6931a7c142ef32df4'),
  ('en.sahih', 26, 5, 2937, 'And no revelation comes to them anew from the Most Merciful except that they turn away from it.', NULL, NULL, '90d12e4743755014eae77fa729c29dd433a80ab4cf293de104159e0830040e30'),
  ('en.sahih', 26, 6, 2938, 'For they have already denied, but there will come to them the news of that which they used to ridicule.', NULL, NULL, 'a85eb38dcf58dc2f9abe2500fab08e68c6de7855fc1f5fb04f65c3e73f5ace25'),
  ('en.sahih', 26, 7, 2939, 'Did they not look at the earth - how much We have produced therein from every noble kind?', NULL, NULL, '9f335d99e7ece7dbda150316f872851a6325a615abd7f6469622b9e050b7674c'),
  ('en.sahih', 26, 8, 2940, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 9, 2941, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 10, 2942, 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -', NULL, NULL, 'c619857f6e21bf92a3ed2e2a9a924357ca257c35421dbcb7ad77020463a3ee4f'),
  ('en.sahih', 26, 11, 2943, 'The people of Pharaoh. Will they not fear Allah?"', NULL, NULL, '1f1b091f079aed4021c6ef2db3f6be71db6966bbbd5a368e08c7ff514a6f70c2'),
  ('en.sahih', 26, 12, 2944, 'He said, "My Lord, indeed I fear that they will deny me', NULL, NULL, 'c7dc15cfad68205e0eb31335aaff0da0d0360e410f77a6c71cab65bf67ef68d0'),
  ('en.sahih', 26, 13, 2945, 'And that my breast will tighten and my tongue will not be fluent, so send for Aaron.', NULL, NULL, '69df74420d80cf92f7596ef7a948e802d8e1d87b6bb8ea7dc2d52d5f19737ede'),
  ('en.sahih', 26, 14, 2946, 'And they have upon me a [claim due to] sin, so I fear that they will kill me."', NULL, NULL, '7c66fe9e3fb68d43ab3f340b0e4b428cc1f0bae6261785531d9a68abb9f7c5fb'),
  ('en.sahih', 26, 15, 2947, '[Allah] said, "No. Go both of you with Our signs; indeed, We are with you, listening.', NULL, NULL, '7aa5b4440a563cc81652df48426279b2949baedbdc88ceb078af8e32134b7e1b'),
  ('en.sahih', 26, 16, 2948, 'Go to Pharaoh and say, ''We are the messengers of the Lord of the worlds,', NULL, NULL, 'ec26eba4b9d34007ec809d883bd92119399b040821f9e006aa42a808bd20c49a'),
  ('en.sahih', 26, 17, 2949, '[Commanded to say], "Send with us the Children of Israel."''"', NULL, NULL, '6b4fc2ecb5272db4a2e7d39ea9a1e6b12b01c87f8e8f2c2a64635772547136cb'),
  ('en.sahih', 26, 18, 2950, '[Pharaoh] said, "Did we not raise you among us as a child, and you remained among us for years of your life?', NULL, NULL, '64c17ca84771c37e07ef627ed44a3746d165f7385f2705c26140a5f8919a2364'),
  ('en.sahih', 26, 19, 2951, 'And [then] you did your deed which you did, and you were of the ungrateful."', NULL, NULL, '6ba37d3eeacf80f4c4c315ec53551b44cd3026f94cf3a65561dbae74888e8e34'),
  ('en.sahih', 26, 20, 2952, '[Moses] said, "I did it, then, while I was of those astray.', NULL, NULL, 'c691c081398dddc036047da307e723faba532e2747d1fc2fda557fc3ed9c3504'),
  ('en.sahih', 26, 21, 2953, 'So I fled from you when I feared you. Then my Lord granted me wisdom and prophethood and appointed me [as one] of the messengers.', NULL, NULL, '930099d142ea663b0b81cc33be1de6e8dd5a058b8b4fe16443dd8cd4a7acae25'),
  ('en.sahih', 26, 22, 2954, 'And is this a favor of which you remind me - that you have enslaved the Children of Israel?"', NULL, NULL, '767bd7c976579c83863347de22e9933e4d82f61f2754cfb67d9167914896daad'),
  ('en.sahih', 26, 23, 2955, 'Said Pharaoh, "And what is the Lord of the worlds?"', NULL, NULL, 'cd09bf24c0faccf1bf1281346c5457b2d0e27a0ef5d31d11f8654d3a0502cb46'),
  ('en.sahih', 26, 24, 2956, '[Moses] said, "The Lord of the heavens and earth and that between them, if you should be convinced."', NULL, NULL, '1d8aa4c88cd5a6205dec57e0e9101f83f0c5a5a7b0666f1951f1e0c32d20b197'),
  ('en.sahih', 26, 25, 2957, '[Pharaoh] said to those around him, "Do you not hear?"', NULL, NULL, '979b553f0fbe20520c701f86f5f7e0022f7245959d0dfc0e2d35810c0b3885fc'),
  ('en.sahih', 26, 26, 2958, '[Moses] said, "Your Lord and the Lord of your first forefathers."', NULL, NULL, '87f0461a663acd061d903f3b277fce8c8a89f7dc1fd82eb4d5c6cde284160b81'),
  ('en.sahih', 26, 27, 2959, '[Pharaoh] said, "Indeed, your ''messenger'' who has been sent to you is mad."', NULL, NULL, '7f237bc9d411b13bcfa1b08f05d61d46c252802dbea5e52d649d6f046bcbdb59'),
  ('en.sahih', 26, 28, 2960, '[Moses] said, "Lord of the east and the west and that between them, if you were to reason."', NULL, NULL, '4b033dc6eafbc3f722d5bdcb1c89978e0215b1abed87bab6d3743dca1c5463fe'),
  ('en.sahih', 26, 29, 2961, '[Pharaoh] said, "If you take a god other than me, I will surely place you among those imprisoned."', NULL, NULL, '2f5f3bc2dfd7c3a48f24f90d3243520b25d7542863c8b39390d075cdad2a3b2f'),
  ('en.sahih', 26, 30, 2962, '[Moses] said, "Even if I brought you proof manifest?"', NULL, NULL, '28e198d18cfeb59bef6a50b6f9fede99e91cc178cc6fdcdba9e28de87a56815a'),
  ('en.sahih', 26, 31, 2963, '[Pharaoh] said, "Then bring it, if you should be of the truthful."', NULL, NULL, 'cd596f3a1559268166a5da578b08932fca788ca54d981629cdde4dd10f00e10b'),
  ('en.sahih', 26, 32, 2964, 'So [Moses] threw his staff, and suddenly it was a serpent manifest.', NULL, NULL, 'c3b38a68f48e96f482f76278fbee85dc9a35402147b6cf21f90ffbd34136bc24'),
  ('en.sahih', 26, 33, 2965, 'And he drew out his hand; thereupon it was white for the observers.', NULL, NULL, '09cd826c409d6842ca70e60b186c6728eaf4fa80bea7231cdd42d5dfb2991592'),
  ('en.sahih', 26, 34, 2966, '[Pharaoh] said to the eminent ones around him, "Indeed, this is a learned magician.', NULL, NULL, '4d0cac1f47504360c60e8e869270929c334f0bf7d5884a09888610101152d687'),
  ('en.sahih', 26, 35, 2967, 'He wants to drive you out of your land by his magic, so what do you advise?"', NULL, NULL, 'd25e7867a232f5b508bf19aaf5ead2f3d6368364d5f7977261499aa5f44f7aee'),
  ('en.sahih', 26, 36, 2968, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers', NULL, NULL, 'a7824df01998e6698582785af3fb4d10e71621280abdbb2bd9daa4198ac0f160'),
  ('en.sahih', 26, 37, 2969, 'Who will bring you every learned, skilled magician."', NULL, NULL, 'bc63cded67f0b0f94ab7739acfa7afc0688b7017934b7881cd07c4877d0edd73'),
  ('en.sahih', 26, 38, 2970, 'So the magicians were assembled for the appointment of a well-known day.', NULL, NULL, '73ab2c419abf85b869a41cef7363cfbc23a25605a32fefe102ec68f2f56c3605'),
  ('en.sahih', 26, 39, 2971, 'And it was said to the people, "Will you congregate', NULL, NULL, '1fcac768e352597177f3c2169654b7c47768d596418a579b2ee72b19f4484ac7'),
  ('en.sahih', 26, 40, 2972, 'That we might follow the magicians if they are the predominant?"', NULL, NULL, 'df5ca67edc838f82ce892ceebbe2e53eaa352cd084451094067c219f6a2a3e07'),
  ('en.sahih', 26, 41, 2973, 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"', NULL, NULL, 'b510bd791a955b1fee3fdaed0b8d66b99a7a0a4888460c9c30655b87086cc756'),
  ('en.sahih', 26, 42, 2974, 'He said, "Yes, and indeed, you will then be of those near [to me]."', NULL, NULL, 'f824a7fe8ba0337dcba4694486c631b223b820a7908bd6f43c3525c823932590'),
  ('en.sahih', 26, 43, 2975, 'Moses said to them, "Throw whatever you will throw."', NULL, NULL, 'e93912b88294d05fd0ba897ca3ccf49f684431fedd76cdfff5748b7cc342408b'),
  ('en.sahih', 26, 44, 2976, 'So they threw their ropes and their staffs and said, "By the might of Pharaoh, indeed it is we who are predominant."', NULL, NULL, '90e765ac27c0ea63a2805ffda0aca5ebaa924737e261f016ed786c101991c31a'),
  ('en.sahih', 26, 45, 2977, 'Then Moses threw his staff, and at once it devoured what they falsified.', NULL, NULL, '4c067173eac42f356ed17bcf5ccd32f8585895a62c41934f35abf41d697dc521'),
  ('en.sahih', 26, 46, 2978, 'So the magicians fell down in prostration [to Allah].', NULL, NULL, 'e259304b2fff2a412b25ea16ace6606132d2f6d97486968428d078b38a246782'),
  ('en.sahih', 26, 47, 2979, 'They said, "We have believed in the Lord of the worlds,', NULL, NULL, '5eed1846d1feffad9dc6f30c4e2977224b87221f57bcc495e922f194e053ff56'),
  ('en.sahih', 26, 48, 2980, 'The Lord of Moses and Aaron."', NULL, NULL, '843795dffd2ca4684a2dce1061b46b0255a83d1bae06f6fab7228fd88bbff2eb'),
  ('en.sahih', 26, 49, 2981, '[Pharaoh] said, "You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."', NULL, NULL, '83d5f771103f2639a5bbad92b71af81885b4761cf950311da28791fe91e4e903'),
  ('en.sahih', 26, 50, 2982, 'They said, "No harm. Indeed, to our Lord we will return.', NULL, NULL, 'dc20c141d278360d4ce9e40f9cafc2cd3e8776f894ca9eedcfc87da9be55378f'),
  ('en.sahih', 26, 51, 2983, 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."', NULL, NULL, '708f82ce61b261fae2bc3d366119381bf7e6492dc4011dd4531c5ef5d6b78918'),
  ('en.sahih', 26, 52, 2984, 'And We inspired to Moses, "Travel by night with My servants; indeed, you will be pursued."', NULL, NULL, 'be9cf8565383bd49f75618280723ce9c96264e330c8d6e4812a9a6658e02fa12'),
  ('en.sahih', 26, 53, 2985, 'Then Pharaoh sent among the cities gatherers', NULL, NULL, '7920a4f2e8b6c185e5d05dba6890c2cd83ceb9941511163d63be60aee5e345cd'),
  ('en.sahih', 26, 54, 2986, '[And said], "Indeed, those are but a small band,', NULL, NULL, '0fd7c843f51de9f43f198b47d25cacb64ea60f4610a2d952f5f34e58d5414a4e'),
  ('en.sahih', 26, 55, 2987, 'And indeed, they are enraging us,', NULL, NULL, '35b100c40eabe88e9808785dc2be12a75242758b72c387f3cd812212758b6d83'),
  ('en.sahih', 26, 56, 2988, 'And indeed, we are a cautious society... "', NULL, NULL, '774b4ce841037c04e5ecd4f25b752f63680381fdb072956d8777a1400125fa14'),
  ('en.sahih', 26, 57, 2989, 'So We removed them from gardens and springs', NULL, NULL, 'e3ae183386654bd21b7ea0dc64ee4a612984c870a07b007aa2e6f2e693bcbac5'),
  ('en.sahih', 26, 58, 2990, 'And treasures and honorable station -', NULL, NULL, '201f48d9c50e39e48030835299d0ef6ede5c8057177a9ddfdc14c5e0134e835f'),
  ('en.sahih', 26, 59, 2991, 'Thus. And We caused to inherit it the Children of Israel.', NULL, NULL, '5c0a154f72cf02a8ea25c4ff5d5045a237bb7cb9b1da9fc77a797502ea322240'),
  ('en.sahih', 26, 60, 2992, 'So they pursued them at sunrise.', NULL, NULL, 'b3eee810c86873e376ee96f215d29b29bd65a4467fb6d5f4f9d6cabb19d9a4bb'),
  ('en.sahih', 26, 61, 2993, 'And when the two companies saw one another, the companions of Moses said, "Indeed, we are to be overtaken!"', NULL, NULL, '719376fdf161d0e449587185d06b346eabc924de6dc96620350c512a34ddcd15'),
  ('en.sahih', 26, 62, 2994, '[Moses] said, "No! Indeed, with me is my Lord; He will guide me."', NULL, NULL, 'a09da7aede07969e28e9d0c8b13e4f56c08a39307769b2a2bc0ca20473f3592c'),
  ('en.sahih', 26, 63, 2995, 'Then We inspired to Moses, "Strike with your staff the sea," and it parted, and each portion was like a great towering mountain.', NULL, NULL, '9dbb2024349bf4aa87207f23fbbfa85bf841c67abf1356183000f02c28226051'),
  ('en.sahih', 26, 64, 2996, 'And We advanced thereto the pursuers.', NULL, NULL, 'a16af6bd7a2f66f2e00c52d64fbc1fa2988d62fb3d7219c8d52b1adaec4a15ea'),
  ('en.sahih', 26, 65, 2997, 'And We saved Moses and those with him, all together.', NULL, NULL, 'f67a8ce77ed170e0c751b3601f1a09a25ec6fefd3a0d488e89b630ee7bb92ade'),
  ('en.sahih', 26, 66, 2998, 'Then We drowned the others.', NULL, NULL, 'd82f940a67894fbe3309145625ba6f62e0d150c0d5c29e0d081d94992e8e9c77'),
  ('en.sahih', 26, 67, 2999, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 68, 3000, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 26, 69, 3001, 'And recite to them the news of Abraham,', NULL, NULL, '32aea4d6997f43c399cf9991873faa032128311ff1b70c57a9720bc2842ae47d'),
  ('en.sahih', 26, 70, 3002, 'When he said to his father and his people, "What do you worship?"', NULL, NULL, '7418852cd52cd5c5a3650f8c584b88192381011ed33dad0f59bc47715e6141ed'),
  ('en.sahih', 26, 71, 3003, 'They said, "We worship idols and remain to them devoted."', NULL, NULL, '74e39e18c0d5e6160355352c93947c6f6f528b29901a2e09aab4878260e50a76'),
  ('en.sahih', 26, 72, 3004, 'He said, "Do they hear you when you supplicate?', NULL, NULL, '7168466230ee79c7505aa832c095a6de7911d393a95becad1bde0142d66db98f'),
  ('en.sahih', 26, 73, 3005, 'Or do they benefit you, or do they harm?"', NULL, NULL, '2e2419ae5b09810d25f0360124ffa44ec75a3f1a6eb9f04ff603eb708b420963'),
  ('en.sahih', 26, 74, 3006, 'They said, "But we found our fathers doing thus."', NULL, NULL, '129c89d9b67d8ab85caa0c0987f7235f2c44266dde30a4de62b291c307493e74'),
  ('en.sahih', 26, 75, 3007, 'He said, "Then do you see what you have been worshipping,', NULL, NULL, '9f73485ee07f28ca3387502b7ebcae3cf3785ebeca48494cb6b571c34d1206df'),
  ('en.sahih', 26, 76, 3008, 'You and your ancient forefathers?', NULL, NULL, 'de5f91793946a09b274cddef93af1e3927d089aa1e4c7097657566f8b91e4f29'),
  ('en.sahih', 26, 77, 3009, 'Indeed, they are enemies to me, except the Lord of the worlds,', NULL, NULL, 'ecb6242f46aa2992df4aa051ef942f997936462097f079c89fda2efc7d76faaf'),
  ('en.sahih', 26, 78, 3010, 'Who created me, and He [it is who] guides me.', NULL, NULL, 'f42b5e1195a18a662d4c104f91279d4b2d0857d383437b06d7a733c21e2c3936'),
  ('en.sahih', 26, 79, 3011, 'And it is He who feeds me and gives me drink.', NULL, NULL, 'b96cbc5b240624a92bea41e37c22104d0f3cdf7d32ed294d2e4b4dd6c67b9638'),
  ('en.sahih', 26, 80, 3012, 'And when I am ill, it is He who cures me', NULL, NULL, 'c0a98437db4e6a7f3c088f44786f7b3fc01991b48209bbcf569d62c437cd186f'),
  ('en.sahih', 26, 81, 3013, 'And who will cause me to die and then bring me to life', NULL, NULL, 'e4bb5b054290ff69dd6331bfbfe7bd4d4ff739ff1573adea951cad4c80096be7'),
  ('en.sahih', 26, 82, 3014, 'And who I aspire that He will forgive me my sin on the Day of Recompense."', NULL, NULL, '259d0026c45bc5d0218b7704b0c4e60b4a9ed9b55a0fbf015567b4daed9e5bb4'),
  ('en.sahih', 26, 83, 3015, '[And he said], "My Lord, grant me authority and join me with the righteous.', NULL, NULL, 'edfe418f7e9f0efd2549875cbcd7b42dc317688cd7ad4abfb8a3a257bd7cbbc4'),
  ('en.sahih', 26, 84, 3016, 'And grant me a reputation of honor among later generations.', NULL, NULL, '7c9572fbde73b2716bd6f598b8575c5b5205fdb8dd68b9c351d37fd2aaebef56'),
  ('en.sahih', 26, 85, 3017, 'And place me among the inheritors of the Garden of Pleasure.', NULL, NULL, '84c928657ba1aaa4f23d63251c8684f77b41375954fd2f115f01e192b9080a72'),
  ('en.sahih', 26, 86, 3018, 'And forgive my father. Indeed, he has been of those astray.', NULL, NULL, '4b1bc6a4bcef5657f568fca810d179793e4bd105f405d381dcc036554f06f6ce'),
  ('en.sahih', 26, 87, 3019, 'And do not disgrace me on the Day they are [all] resurrected -', NULL, NULL, '8dd36ceebf685f24af6f9da1f09d96228dee93104f0d5960ccd1650e531dc77b'),
  ('en.sahih', 26, 88, 3020, 'The Day when there will not benefit [anyone] wealth or children', NULL, NULL, '20173bdb7031c412be5459d849bd4500cfae8a8ee25b5297bec59a75506eda89'),
  ('en.sahih', 26, 89, 3021, 'But only one who comes to Allah with a sound heart."', NULL, NULL, '2d4503c60b7fb1c6ffe4813d1226d8a237fc62c1cf09482cb2507c18cd689694'),
  ('en.sahih', 26, 90, 3022, 'And Paradise will be brought near [that Day] to the righteous.', NULL, NULL, 'a3716da52c00fa8d011c342894795f96159f2a16c7f53de88eee6af419e599d3'),
  ('en.sahih', 26, 91, 3023, 'And Hellfire will be brought forth for the deviators,', NULL, NULL, '7015a79d8229a9365aa3c5969da811ed228e14064db8d683f03b0d74183eff71'),
  ('en.sahih', 26, 92, 3024, 'And it will be said to them, "Where are those you used to worship', NULL, NULL, '75afe49fa6bea6793416a66c3706ef647d28efd10bd815f737f4985605790a95'),
  ('en.sahih', 26, 93, 3025, 'Other than Allah? Can they help you or help themselves?"', NULL, NULL, '5589374a2551119b46788255053264cd5dd31af3f0278871b1f22ca0f6e3bd56'),
  ('en.sahih', 26, 94, 3026, 'So they will be overturned into Hellfire, they and the deviators', NULL, NULL, 'a6bc6f194fc514bca386114ac93ae3443263ec02fc8dc2669f6e0aaca05ca73c'),
  ('en.sahih', 26, 95, 3027, 'And the soldiers of Iblees, all together.', NULL, NULL, '10617ec4c79dc4d10c8a281f1ecd63dc5c7b7b80be0b91f2ccea259bdade1724'),
  ('en.sahih', 26, 96, 3028, 'They will say while they dispute therein,', NULL, NULL, '29a41381ac3533cda032fa8a988c80b19d16d595ced7957dbfd40f1edba56505'),
  ('en.sahih', 26, 97, 3029, '"By Allah, we were indeed in manifest error', NULL, NULL, '748a4ac6182d5c0dee71029d50ec86790e48f105529e6ad659671d80a3501ea6'),
  ('en.sahih', 26, 98, 3030, 'When we equated you with the Lord of the worlds.', NULL, NULL, 'f3febc3f99974d55859895e01446c83f365ef435572c0cf2bc5e90ba91eea9d2'),
  ('en.sahih', 26, 99, 3031, 'And no one misguided us except the criminals.', NULL, NULL, '88617c54dd5c9a6cda08f04026672e32df0866f658361773f7ed18b4e8f866e4'),
  ('en.sahih', 26, 100, 3032, 'So now we have no intercessors', NULL, NULL, 'b7a4e5efecfc21376694252408f29eb0708937a1b55c4faa1c761fb9fb0f5bc5'),
  ('en.sahih', 26, 101, 3033, 'And not a devoted friend.', NULL, NULL, 'e06407a019cb38fc42dabdbec2fa8ad487e226911808b367738799716182517e'),
  ('en.sahih', 26, 102, 3034, 'Then if we only had a return [to the world] and could be of the believers... "', NULL, NULL, '71e3d3a0346300d5f6de51d83e95cab47c4d1b0fcc8c0ab972e1f627639780f3'),
  ('en.sahih', 26, 103, 3035, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 104, 3036, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 105, 3037, 'The people of Noah denied the messengers', NULL, NULL, 'fc91a0b54054e1a3299abc81d11a45fb271694546aa5db8a82adb104a444fea5'),
  ('en.sahih', 26, 106, 3038, 'When their brother Noah said to them, "Will you not fear Allah?', NULL, NULL, '4cfdb6a3499ebe0ecff7f406050c26cc8543abd366210a4f65607388ce24e10f'),
  ('en.sahih', 26, 107, 3039, 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, '59edfd3bc6ca2ebb47f422c777ca178a2f82670aec16fd91ca55f5d981df0f1b'),
  ('en.sahih', 26, 108, 3040, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 109, 3041, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, 'cdcfcfb6026aff096cc40583aabebcac95b5e7fc55a5b7e4114174c65822f897'),
  ('en.sahih', 26, 110, 3042, 'So fear Allah and obey me."', NULL, NULL, '0222d88f18143857e4415d1fdd64e6e89212b451c233e6d2e4902cb081d664c4'),
  ('en.sahih', 26, 111, 3043, 'They said, "Should we believe you while you are followed by the lowest [class of people]?"', NULL, NULL, 'dc519296b66703b587585a03cd4d82b085dd77e49b8a37b53b73e1ac979bd64a'),
  ('en.sahih', 26, 112, 3044, 'He said, "And what is my knowledge of what they used to do?', NULL, NULL, '43eb11ccf5f097cadce06df9aafe1a362b481fb803d80b65ff511de6dbad0cf0'),
  ('en.sahih', 26, 113, 3045, 'Their account is only upon my Lord, if you [could] perceive.', NULL, NULL, '84537dd81dd2c250c7a8947490b24ef9b5f446534797be5f71f2ceed806ce44b'),
  ('en.sahih', 26, 114, 3046, 'And I am not one to drive away the believers.', NULL, NULL, 'b82fafdfd4afd59bb888c80a26831c36737dbb59f18877b70a0237586817313e'),
  ('en.sahih', 26, 115, 3047, 'I am only a clear warner."', NULL, NULL, '905e402e9ec77ce065054987915ffc8e15e7cc87ae433ab5aa3a3d76225b806e'),
  ('en.sahih', 26, 116, 3048, 'They said, "If you do not desist, O Noah, you will surely be of those who are stoned."', NULL, NULL, 'd26493be83135f28c4899848da9e1a0a5c36fb3effa7a50c0e7050cd6a298641'),
  ('en.sahih', 26, 117, 3049, 'He said, "My Lord, indeed my people have denied me.', NULL, NULL, '83009094bf7c46d20ebcd762a7a54d48ec88f82bcd483860281a62a0b30e705c'),
  ('en.sahih', 26, 118, 3050, 'Then judge between me and them with decisive judgement and save me and those with me of the believers."', NULL, NULL, 'bc49d07bbbdd3868ca18117604a2df408d3bc1fae5b60a5e1997d94eb57a947e'),
  ('en.sahih', 26, 119, 3051, 'So We saved him and those with him in the laden ship.', NULL, NULL, '9adf08d175a50ac52bf507d9442940c475db40e81f0f9fac02abac5f6e2e7c2c'),
  ('en.sahih', 26, 120, 3052, 'Then We drowned thereafter the remaining ones.', NULL, NULL, '77c7d60fb97ee078492f8100658337124ba04ca5e56c784c496726040d204dca'),
  ('en.sahih', 26, 121, 3053, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 122, 3054, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 123, 3055, '''Aad denied the messengers', NULL, NULL, '3ef545c98d38399a2d72dd57b75b1f6a247f42a9c69c49214ff1271b9b2f665d'),
  ('en.sahih', 26, 124, 3056, 'When their brother Hud said to them, "Will you not fear Allah?', NULL, NULL, 'b0286507d2fc41a23abe82bde0f2c7cea5e20dce47b877f5333fd1ecdb4eaa2e'),
  ('en.sahih', 26, 125, 3057, 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, '59edfd3bc6ca2ebb47f422c777ca178a2f82670aec16fd91ca55f5d981df0f1b'),
  ('en.sahih', 26, 126, 3058, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 127, 3059, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, 'cdcfcfb6026aff096cc40583aabebcac95b5e7fc55a5b7e4114174c65822f897'),
  ('en.sahih', 26, 128, 3060, 'Do you construct on every elevation a sign, amusing yourselves,', NULL, NULL, '6f138fcfffee54b11e20c5a6ff75bb279fa8a23ce7f5745fb31fb7dbf75f487e'),
  ('en.sahih', 26, 129, 3061, 'And take for yourselves palaces and fortresses that you might abide eternally?', NULL, NULL, '13c9b29134fd247e0e4caaae884677490f604ea13013d4a8c282a9c5ccca019b'),
  ('en.sahih', 26, 130, 3062, 'And when you strike, you strike as tyrants.', NULL, NULL, 'a143c3c2af0615ce41d3afaa64de252760a30baa2f3281f7120d1792baf97dc0'),
  ('en.sahih', 26, 131, 3063, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 132, 3064, 'And fear He who provided you with that which you know,', NULL, NULL, '55859288fb7c55138363dc7fc9be1b28a206e0ef878f612dd0f963e093095d3f'),
  ('en.sahih', 26, 133, 3065, 'Provided you with grazing livestock and children', NULL, NULL, '12a53c142c5d8d4952b725d0d5b6393c74f959034899c38ad31bfdfbcc42ee35'),
  ('en.sahih', 26, 134, 3066, 'And gardens and springs.', NULL, NULL, '473be4bffb634699237ea96208391b340dc4e1153b06dcb9e09d478a2fc8cc79'),
  ('en.sahih', 26, 135, 3067, 'Indeed, I fear for you the punishment of a terrible day."', NULL, NULL, 'ed64f66a7c03b91506b49a411434929f3f8cf7c3ef05926e8b663cd22bf8a1f4'),
  ('en.sahih', 26, 136, 3068, 'They said, "It is all the same to us whether you advise or are not of the advisors.', NULL, NULL, '266e1f7cbb3063791e63a0212acc4b9cd0f4e4eef042d85dfa7c7ca2c256e55b'),
  ('en.sahih', 26, 137, 3069, 'This is not but the custom of the former peoples,', NULL, NULL, '2bf0ef31f59102a702096762acf498f26d3ad9b5aa4364ed2895fa78e366e1e3'),
  ('en.sahih', 26, 138, 3070, 'And we are not to be punished."', NULL, NULL, '505128dac3dd6eaade0a18f61a44a4dcb0bb1b6085d6edf21aef212c58c02d87'),
  ('en.sahih', 26, 139, 3071, 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '875ddac0c5740096563c12178a678cdbc1a28bd8d2127a3cf73b21f22c70c320'),
  ('en.sahih', 26, 140, 3072, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 141, 3073, 'Thamud denied the messengers', NULL, NULL, 'a864ecb335cfd73a6644a94ae50f1c27b63d47188e2e87996ebc88089c40ab72'),
  ('en.sahih', 26, 142, 3074, 'When their brother Salih said to them, "Will you not fear Allah?', NULL, NULL, 'a952910021c7d9516122124ee8a640c3fc82c3451639792606bd0de00a07089f'),
  ('en.sahih', 26, 143, 3075, 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, '59edfd3bc6ca2ebb47f422c777ca178a2f82670aec16fd91ca55f5d981df0f1b'),
  ('en.sahih', 26, 144, 3076, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 145, 3077, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, 'cdcfcfb6026aff096cc40583aabebcac95b5e7fc55a5b7e4114174c65822f897'),
  ('en.sahih', 26, 146, 3078, 'Will you be left in what is here, secure [from death],', NULL, NULL, '03f2a61f4478ea4bfad82665fd893ff3b1a8b37d1872ec90d32463eaaee7602e'),
  ('en.sahih', 26, 147, 3079, 'Within gardens and springs', NULL, NULL, '354caf49ada4013277c71b4dab22332bb58b8617257040713bbefc973aa611e3'),
  ('en.sahih', 26, 148, 3080, 'And fields of crops and palm trees with softened fruit?', NULL, NULL, 'ee6721cfefc0a98876c246365516d92bd63e8a4870096111633115c6e74928c1'),
  ('en.sahih', 26, 149, 3081, 'And you carve out of the mountains, homes, with skill.', NULL, NULL, 'cd5f800d681b1752bb926a4413aa8c5124b895a5fecdd943ad97111bb57bdbc5'),
  ('en.sahih', 26, 150, 3082, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 151, 3083, 'And do not obey the order of the transgressors,', NULL, NULL, '7500f9234ba1cc6ef17898c0696d085d02c1b07073d600be6de37559cdfea80c'),
  ('en.sahih', 26, 152, 3084, 'Who cause corruption in the land and do not amend."', NULL, NULL, 'c2e5648d82eb74095d0d35a09c9cfae0062e967540d8fa01f27c41e132712cc3'),
  ('en.sahih', 26, 153, 3085, 'They said, "You are only of those affected by magic.', NULL, NULL, '25125986eee59a93963f07cffcbd444c19fe484ae5e9e3d5aaabfa5c2a691f70'),
  ('en.sahih', 26, 154, 3086, 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."', NULL, NULL, '117e247393df97cb0f6489e4984bf23dafcf344d558a5e4e61d1368ceb963722'),
  ('en.sahih', 26, 155, 3087, 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.', NULL, NULL, '1c1ac0531b05b5aa0ab84f95887cb30e45ebf75849d569c18e206a66807bea46'),
  ('en.sahih', 26, 156, 3088, 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."', NULL, NULL, '4206a91c3748f28665078199ce01c79ad591526a40833f2eaebcb332010cc8f3'),
  ('en.sahih', 26, 157, 3089, 'But they hamstrung her and so became regretful.', NULL, NULL, '044a918cdfba19ae05eca22bdb26a000f89b1cb10cbe6b22c5f0de4e0210e10b'),
  ('en.sahih', 26, 158, 3090, 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '65ce48d837f41d13174c68dfb99245c95c2039139f7f4b3abc69a47863f5480d'),
  ('en.sahih', 26, 159, 3091, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 160, 3092, 'The people of Lot denied the messengers', NULL, NULL, '8f0f8ee622c984f4a1ed249e7796191dd8312ff92875f24113bdaa46f1cc46d0'),
  ('en.sahih', 26, 161, 3093, 'When their brother Lot said to them, "Will you not fear Allah?', NULL, NULL, '445c756f4b0b279181a7173f3feef5a282f3d857f82b0f06c2cc7aed0393bb99'),
  ('en.sahih', 26, 162, 3094, 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, '59edfd3bc6ca2ebb47f422c777ca178a2f82670aec16fd91ca55f5d981df0f1b'),
  ('en.sahih', 26, 163, 3095, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 164, 3096, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, 'cdcfcfb6026aff096cc40583aabebcac95b5e7fc55a5b7e4114174c65822f897'),
  ('en.sahih', 26, 165, 3097, 'Do you approach males among the worlds', NULL, NULL, 'adf14a646e1a9edfa16d5f5179fb348b0374b22cc34f094a5fb17574de0c151c'),
  ('en.sahih', 26, 166, 3098, 'And leave what your Lord has created for you as mates? But you are a people transgressing."', NULL, NULL, '9e0758276e82de303f60267d55f450f59f006024bd83680a07f0fdabcfdb9b71'),
  ('en.sahih', 26, 167, 3099, 'They said, "If you do not desist, O Lot, you will surely be of those evicted."', NULL, NULL, '2706831927ada79aacca3c0abdb4ff6589c8fac08d7cdde9e3d352e42b36f5e3'),
  ('en.sahih', 26, 168, 3100, 'He said, "Indeed, I am, toward your deed, of those who detest [it].', NULL, NULL, '72abf8cd2a8313a37034a4c27f0784b41b07be168f1f32e7e6a1c58233ce1073')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 26, 169, 3101, 'My Lord, save me and my family from [the consequence of] what they do."', NULL, NULL, '33261abb665e8326761bcb59cadea5762c27d5515cfb0bcf0bc9c599a07639d0'),
  ('en.sahih', 26, 170, 3102, 'So We saved him and his family, all,', NULL, NULL, '04b31938cd8646f2d6022ad7822dda24e0ce812b1ec3e4ef90329c912dafbac0'),
  ('en.sahih', 26, 171, 3103, 'Except an old woman among those who remained behind.', NULL, NULL, 'dc080f7f57237d28c59f2718797d59f3c9988abaa1b673b153ddd033bbbab855'),
  ('en.sahih', 26, 172, 3104, 'Then We destroyed the others.', NULL, NULL, '34d8d6508e2f142b554ebf95d58419d50d2903808418fc10800ec676cbbb5b57'),
  ('en.sahih', 26, 173, 3105, 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', NULL, NULL, '119fd9d3b95be145c0e2c4990d6785452f3b586e076520dff1edf477f5ed3668'),
  ('en.sahih', 26, 174, 3106, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 175, 3107, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 176, 3108, 'The companions of the thicket denied the messengers', NULL, NULL, '95b2dc700edd2bcd8fee533621f9f88e32c8d664424a82aa9e8d0a52a02842d2'),
  ('en.sahih', 26, 177, 3109, 'When Shu''ayb said to them, "Will you not fear Allah?', NULL, NULL, 'd94923c8b437633f5fa87b99dbbade2fbb323a2938bcdc412d86b9fb4d9e6763'),
  ('en.sahih', 26, 178, 3110, 'Indeed, I am to you a trustworthy messenger.', NULL, NULL, '59edfd3bc6ca2ebb47f422c777ca178a2f82670aec16fd91ca55f5d981df0f1b'),
  ('en.sahih', 26, 179, 3111, 'So fear Allah and obey me.', NULL, NULL, 'fccb4d68f79ce6633d39bdeedeb1b35791e8d6b0ca9df800d5db0f107e8a53f6'),
  ('en.sahih', 26, 180, 3112, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.', NULL, NULL, 'cdcfcfb6026aff096cc40583aabebcac95b5e7fc55a5b7e4114174c65822f897'),
  ('en.sahih', 26, 181, 3113, 'Give full measure and do not be of those who cause loss.', NULL, NULL, 'f78da8352183ea12b9628d236bd9143e29644365f257a3ec2d7426768e4db27d'),
  ('en.sahih', 26, 182, 3114, 'And weigh with an even balance.', NULL, NULL, 'b468b338ae9df68c5d9aacc47dc0a556f442874c799d1b6b360dbb2e5dc9180e'),
  ('en.sahih', 26, 183, 3115, 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.', NULL, NULL, 'e0d48b5c9935928c31d238b5cffd8d2367452fa68e40c1bbd5d3fd81d9faa438'),
  ('en.sahih', 26, 184, 3116, 'And fear He who created you and the former creation."', NULL, NULL, 'f34e0fa8c99be2e0c627ad8e1d7580020d9687ad3a510b48db1fa8ba78bb21d2'),
  ('en.sahih', 26, 185, 3117, 'They said, "You are only of those affected by magic.', NULL, NULL, '25125986eee59a93963f07cffcbd444c19fe484ae5e9e3d5aaabfa5c2a691f70'),
  ('en.sahih', 26, 186, 3118, 'You are but a man like ourselves, and indeed, we think you are among the liars.', NULL, NULL, 'cc614815d7c30efccb0506a15f88fddeea8018c9a0201243481d57824da9338c'),
  ('en.sahih', 26, 187, 3119, 'So cause to fall upon us fragments of the sky, if you should be of the truthful."', NULL, NULL, '975439fbd16dac93dfbbeb3aadecc7342cdbaf84ab2a18f77ceafc2b4d4e54fa'),
  ('en.sahih', 26, 188, 3120, 'He said, "My Lord is most knowing of what you do."', NULL, NULL, '9c22d10c66ff5d03b4968b2648dacf73b3a60d8ccef8532db8d3383fd0e66466'),
  ('en.sahih', 26, 189, 3121, 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.', NULL, NULL, 'bf5fd7122d3d520dc7eb5d0e125e4aa6101b4ac34d23a9c755b8d2e5e138db29'),
  ('en.sahih', 26, 190, 3122, 'Indeed in that is a sign, but most of them were not to be believers.', NULL, NULL, '19e2eeb3208bb376af0bbb85310e69d77c785e9f2af973052b855fb1e8009c60'),
  ('en.sahih', 26, 191, 3123, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.', NULL, NULL, '8a36054ed2a4945f324ba07ef634ae90d35e46fc56ffbb214d1635d30c0ab168'),
  ('en.sahih', 26, 192, 3124, 'And indeed, the Qur''an is the revelation of the Lord of the worlds.', NULL, NULL, '188eb3bc5e32e1a2ca0872a953af66e80a2f8eef656704c6df9dd56d037982cb'),
  ('en.sahih', 26, 193, 3125, 'The Trustworthy Spirit has brought it down', NULL, NULL, '5ad79af7d3979601a72941bf84797fc2ec89afd7dbde3437da3436289df14084'),
  ('en.sahih', 26, 194, 3126, 'Upon your heart, [O Muhammad] - that you may be of the warners -', NULL, NULL, '9fd46b39381909eaf5f089bb4a8a9fbb78fd134f46f29e6092216b1e42f4b383'),
  ('en.sahih', 26, 195, 3127, 'In a clear Arabic language.', NULL, NULL, '78608b6683769c50fc51e0dee408ee741f4b07985fa01d4ebdeabb18011d88c3'),
  ('en.sahih', 26, 196, 3128, 'And indeed, it is [mentioned] in the scriptures of former peoples.', NULL, NULL, 'fac1930798b18cfbe4afb304abc5b8d7c312360254634d60311965bb05f1184e'),
  ('en.sahih', 26, 197, 3129, 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?', NULL, NULL, '815c3d017cb1305591d40778cdaccef90225d1dd051dbe2542e31c8096c3a256'),
  ('en.sahih', 26, 198, 3130, 'And even if We had revealed it to one among the foreigners', NULL, NULL, 'fd191503fe096231a40a0bb0aee8fb3a76f74e87df76229f07855b7e2960a9dd'),
  ('en.sahih', 26, 199, 3131, 'And he had recited it to them [perfectly], they would [still] not have been believers in it.', NULL, NULL, '4cd9d468cc92c151a3ad09f3637eb391e3e8710edcef0a085743671c2de0d876'),
  ('en.sahih', 26, 200, 3132, 'Thus have We inserted disbelief into the hearts of the criminals.', NULL, NULL, 'ac19c3bbe36f1326dbb52d7603aa7a7a2d890dec98721570db9b809421eca2f5'),
  ('en.sahih', 26, 201, 3133, 'They will not believe in it until they see the painful punishment.', NULL, NULL, '4a115f93d0021096b9bdb09185a5a25ee01bf33485a032a0650c0e0a135bda71'),
  ('en.sahih', 26, 202, 3134, 'And it will come to them suddenly while they perceive [it] not.', NULL, NULL, '9d8c087b38632762926527b03a8c1d1eb4101489de4b9fb661389f7ed434bcb9'),
  ('en.sahih', 26, 203, 3135, 'And they will say, "May we be reprieved?"', NULL, NULL, '27f4f4e3f4993139b1584b00fa944b7da73c4f3c40f45604e412f600a467b64e'),
  ('en.sahih', 26, 204, 3136, 'So for Our punishment are they impatient?', NULL, NULL, '21efe6fb5bedae2b9b6a765a07227d427300d096e02a201c3ae02db366236242'),
  ('en.sahih', 26, 205, 3137, 'Then have you considered if We gave them enjoyment for years', NULL, NULL, 'a6a82d65e39fc68f8f4fa51a9017abf3f6bba031279e55efa7bc964e356ab689'),
  ('en.sahih', 26, 206, 3138, 'And then there came to them that which they were promised?', NULL, NULL, 'f38479020410e9376339ce87e60f2036d3353780a425ad293c308c9bc8d783ca'),
  ('en.sahih', 26, 207, 3139, 'They would not be availed by the enjoyment with which they were provided.', NULL, NULL, '07d3a5d113d8a7bdca64906c03df5a45db54f85f93299f9b2e4ad4f223a2db53'),
  ('en.sahih', 26, 208, 3140, 'And We did not destroy any city except that it had warners', NULL, NULL, '7abc56f0e42577a3a30d588fb05339f54a61c9b7fd5745978960e0c9ee622001'),
  ('en.sahih', 26, 209, 3141, 'As a reminder; and never have We been unjust.', NULL, NULL, '00df4da4ebdd23117813c59f9b901fd0b4aee83071a29bbd6481a83039cbb8b7'),
  ('en.sahih', 26, 210, 3142, 'And the devils have not brought the revelation down.', NULL, NULL, '4ac632051404f4baaa8fa2442427f270bbf5f11ad085aac448414a869ddf0bb3'),
  ('en.sahih', 26, 211, 3143, 'It is not allowable for them, nor would they be able.', NULL, NULL, '84a8ab3efac74cd8ca83e31b6c381aa03b8340e5276b8a488f061359bfd421fe'),
  ('en.sahih', 26, 212, 3144, 'Indeed they, from [its] hearing, are removed.', NULL, NULL, '05a86487536eace02fde3cc8ce26a1dc88bff668495fd79a845e5ec92fa0c12f'),
  ('en.sahih', 26, 213, 3145, 'So do not invoke with Allah another deity and [thus] be among the punished.', NULL, NULL, '52c04d7b8dfc5546344189e030dc13fa4dc2d0086741e49d545544cd8527d0e0'),
  ('en.sahih', 26, 214, 3146, 'And warn, [O Muhammad], your closest kindred.', NULL, NULL, 'd4fe52c11a9d1a937fa94b4a3227cffb8504c9f55ee5dcae78494eba66f0b32e'),
  ('en.sahih', 26, 215, 3147, 'And lower your wing to those who follow you of the believers.', NULL, NULL, 'e3cdd3d7bd4a0438a36afa851e9d98fea6d9dd1e4884042bbb0983673f2b7441'),
  ('en.sahih', 26, 216, 3148, 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."', NULL, NULL, '2abac938e6ee62f3b16054aecf9ecd76c36100f40149ce35bb5da4e5af3319e4'),
  ('en.sahih', 26, 217, 3149, 'And rely upon the Exalted in Might, the Merciful,', NULL, NULL, 'fa9e2b2910360f829fcfa4b3d71bb5bbd1a8e5fc8acebc3a13656ea702c64b1a'),
  ('en.sahih', 26, 218, 3150, 'Who sees you when you arise', NULL, NULL, '807f72e854beaf4155f524ec51d9208e842f8b834121ac9f66111a173b9e2cb1'),
  ('en.sahih', 26, 219, 3151, 'And your movement among those who prostrate.', NULL, NULL, '3aad52b596d7c2d484efec73f96f1242d2500f106d1ece849cab78ccf78b5f01'),
  ('en.sahih', 26, 220, 3152, 'Indeed, He is the Hearing, the Knowing.', NULL, NULL, '86ebee439ffb073532e16a362a3f9164c82092c2729a9c9d8053fbcb44f0a473'),
  ('en.sahih', 26, 221, 3153, 'Shall I inform you upon whom the devils descend?', NULL, NULL, '756269c999b456d0f4e683448924a3ac522d498914d5f3b523e7528d5d9bf0ac'),
  ('en.sahih', 26, 222, 3154, 'They descend upon every sinful liar.', NULL, NULL, 'fcfd50070a3017e03c301ce1cbda890d257a209ae1df686785ef687fec35e359'),
  ('en.sahih', 26, 223, 3155, 'They pass on what is heard, and most of them are liars.', NULL, NULL, '699b1025f6c51904052e01767977f4881c19f0e45e53f4ba5e3df6f8cac08059'),
  ('en.sahih', 26, 224, 3156, 'And the poets - [only] the deviators follow them;', NULL, NULL, 'c3538c226cc821a127b827877f55419657aa20005f838de4c378b9af3c216e3a'),
  ('en.sahih', 26, 225, 3157, 'Do you not see that in every valley they roam', NULL, NULL, '5ba6527e427037b89c69263e52c637b9291af5d1dc70643f8efa573636a64b0a'),
  ('en.sahih', 26, 226, 3158, 'And that they say what they do not do? -', NULL, NULL, '3f9fab33fc20b22ad7c38b528c824c3b12b0ba2c34f9c28c158117fdcfe1825d'),
  ('en.sahih', 26, 227, 3159, 'Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.', NULL, NULL, 'e271a01767503ee79e8e6142e1c7c60770132e3aa4f07a27b77dcdef08ea8c66'),
  ('en.sahih', 27, 1, 3160, 'Ta, Seen. These are the verses of the Qur''an and a clear Book', NULL, NULL, '8b6f61f3599eb072e0c127d7c3195627796590fef48e5ec9f4535b74d8c32b7d'),
  ('en.sahih', 27, 2, 3161, 'As guidance and good tidings for the believers', NULL, NULL, '032b6de00ab6f91507ce1adac0c94cd9df1b3c1dd961a54c769cd6fd818d0e73'),
  ('en.sahih', 27, 3, 3162, 'Who establish prayer and give zakah, and of the Hereafter they are certain [in faith].', NULL, NULL, '035ce2cac3b12da272f57a3c3454165d6e2471363ffb65170aec7dd1ceb0434d'),
  ('en.sahih', 27, 4, 3163, 'Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.', NULL, NULL, '019bdb56ac39c5086ed6e64d8fd66a088686fd0805db9cb08b8cd364084b6cb1'),
  ('en.sahih', 27, 5, 3164, 'Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.', NULL, NULL, '3aae1a5ebabbb7979f4342becd9d665438b747f8539bf9f4c81fe421f833ee1e'),
  ('en.sahih', 27, 6, 3165, 'And indeed, [O Muhammad], you receive the Qur''an from one Wise and Knowing.', NULL, NULL, 'f420665e293405d1bcfb5817084d3570e1c78a3572ecb71a8608ede8626d3e6b'),
  ('en.sahih', 27, 7, 3166, '[Mention] when Moses said to his family, "Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves."', NULL, NULL, '05e87feab64397b9229413ab8d879b8252e16178b71e99f85ce510468d596f5d'),
  ('en.sahih', 27, 8, 3167, 'But when he came to it, he was called, "Blessed is whoever is at the fire and whoever is around it. And exalted is Allah, Lord of the worlds.', NULL, NULL, '4801da83e841fa72168abf3a2c7628593e8358a23a7d689149711e616ca2a726'),
  ('en.sahih', 27, 9, 3168, 'O Moses, indeed it is I - Allah, the Exalted in Might, the Wise."', NULL, NULL, '22488829bad214dc3e62ad62a11cc489cbd75a563ea5fe8545d1a900e8745d90'),
  ('en.sahih', 27, 10, 3169, 'And [he was told], "Throw down your staff." But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allah said], "O Moses, fear not. Indeed, in My presence the messengers do not fear.', NULL, NULL, 'ec2e90366b395beaea71be43b408878436eb88c9cbc936b88732ce3bbea287d1'),
  ('en.sahih', 27, 11, 3170, 'Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.', NULL, NULL, '5db9d8c4d66d06989374ad493eb5b713c662c8e023877b49ada871fc03f20e0f'),
  ('en.sahih', 27, 12, 3171, 'And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient."', NULL, NULL, '064fb5dc4ac79bdedf320ea7f7a380be784d1d33a65373587cd3376b3abdc3ca'),
  ('en.sahih', 27, 13, 3172, 'But when there came to them Our visible signs, they said, "This is obvious magic."', NULL, NULL, 'f97339229bb55f4385d323cbfb960bffad3221d5e3cd5c8ae9beadd651f8031d'),
  ('en.sahih', 27, 14, 3173, 'And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.', NULL, NULL, '658d1392c2ae9d9c47a457dc4362a88fa1a2a5b9dd9a6d7a42815e1eee92e1a4'),
  ('en.sahih', 27, 15, 3174, 'And We had certainly given to David and Solomon knowledge, and they said, "Praise [is due] to Allah, who has favored us over many of His believing servants."', NULL, NULL, 'ef9342efbc9476c9c85e066a8ecbf5efdca2eab1d3b40f257784d65396473462'),
  ('en.sahih', 27, 16, 3175, 'And Solomon inherited David. He said, "O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty."', NULL, NULL, '0e6ac2e7fce34f710246b70165494efaebe7cfeb92be51a59a8996b3ddf29bc4'),
  ('en.sahih', 27, 17, 3176, 'And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows.', NULL, NULL, '128992c80ab3e061af7c065414378547ce4523ff3169a4812e09553f9c5cd22e'),
  ('en.sahih', 27, 18, 3177, 'Until, when they came upon the valley of the ants, an ant said, "O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not."', NULL, NULL, '23063d7d2ce6c0cbc23d86a13554265b83d0224aeec1dd2faebf9b70c4688310'),
  ('en.sahih', 27, 19, 3178, 'So [Solomon] smiled, amused at her speech, and said, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."', NULL, NULL, '4e71bb928bd2bfe791941a4896e32f5c6da589f7488cf8061699b43560654d3f'),
  ('en.sahih', 27, 20, 3179, 'And he took attendance of the birds and said, "Why do I not see the hoopoe - or is he among the absent?', NULL, NULL, '014e8f33e69e814de620e154e0402605395f649be1e125acbb3c5a930d1ee7a0'),
  ('en.sahih', 27, 21, 3180, 'I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization."', NULL, NULL, 'e7a43f30dcd8f10adabe749dc0937e2a46e6ee6c466d5b05c9d812cb87c2c7f7'),
  ('en.sahih', 27, 22, 3181, 'But the hoopoe stayed not long and said, "I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.', NULL, NULL, '0e78d2fd01b95052b0fbe31b779f6dc2a0d02602fad4c107f105513e6f6ae6be'),
  ('en.sahih', 27, 23, 3182, 'Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.', NULL, NULL, '678d459ce843a5a1f5ce16f7f8927dcd230fc46bbd2722cd04c37dd945add8f0'),
  ('en.sahih', 27, 24, 3183, 'I found her and her people prostrating to the sun instead of Allah, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,', NULL, NULL, '8e9fd0defe8f0a5488432fbd1583d7c07cf29bc9769a2ded5890103c72bb4847'),
  ('en.sahih', 27, 25, 3184, '[And] so they do not prostrate to Allah, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -', NULL, NULL, 'de68a487f33272a60ea80f58febecb9f962f6f721b15e8bb7955b2204ced7783'),
  ('en.sahih', 27, 26, 3185, 'Allah - there is no deity except Him, Lord of the Great Throne."', NULL, NULL, '42dc1199bab80b33d067e3c64f1d545a86a30b82d3755c160f1daf29c85a4f24'),
  ('en.sahih', 27, 27, 3186, '[Solomon] said, "We will see whether you were truthful or were of the liars.', NULL, NULL, 'ae7ce1d854ac1755e55527c2cd52bbdacf1fb159fafe97ad9f78be9d78fbe668'),
  ('en.sahih', 27, 28, 3187, 'Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return."', NULL, NULL, 'b5e9f9c7011183bdc0db2b50b0f184b1394b18ba1956203d08936c51ada07237'),
  ('en.sahih', 27, 29, 3188, 'She said, "O eminent ones, indeed, to me has been delivered a noble letter.', NULL, NULL, 'cec16668b1bf71d6cbf34263b8fa9a8de82af3b26fff52bc2e28fe21d7b94294'),
  ('en.sahih', 27, 30, 3189, 'Indeed, it is from Solomon, and indeed, it reads: ''In the name of Allah, the Entirely Merciful, the Especially Merciful,', NULL, NULL, 'fc2c6bc021e9351aa65c7ca051dbfb1624664a1b474cdb23c44700f7566f0142'),
  ('en.sahih', 27, 31, 3190, 'Be not haughty with me but come to me in submission [as Muslims].'' "', NULL, NULL, 'eab997a196aa734ecb82fccd591b439d57ace49ef67f2e53d2bdb9ed243caede'),
  ('en.sahih', 27, 32, 3191, 'She said, "O eminent ones, advise me in my affair. I would not decide a matter until you witness [for] me."', NULL, NULL, '1502a9a28ad7eff68d58b721f56a60c51593b34a8ca015951d7668bb3661dcb9'),
  ('en.sahih', 27, 33, 3192, 'They said, "We are men of strength and of great military might, but the command is yours, so see what you will command."', NULL, NULL, '9a504a6ce32150705fbf1f204720434a9901211df9178b8f2c95f2c18a8ff2ea'),
  ('en.sahih', 27, 34, 3193, 'She said, "Indeed kings - when they enter a city, they ruin it and render the honored of its people humbled. And thus do they do.', NULL, NULL, '62692c88e3c951d04ea2e84673c2bf5cfd4056df0c3b529b0fed3404e238a1af'),
  ('en.sahih', 27, 35, 3194, 'But indeed, I will send to them a gift and see with what [reply] the messengers will return."', NULL, NULL, '33aa5a3a4c35dc6d46c560ec98ec6100adbbd336f2d99da1ab0f1fae8f0bb55b'),
  ('en.sahih', 27, 36, 3195, 'So when they came to Solomon, he said, "Do you provide me with wealth? But what Allah has given me is better than what He has given you. Rather, it is you who rejoice in your gift.', NULL, NULL, 'c60b913a89cf33c4459fe88393b2dfd9f0f9681c685a87a77b642ab79fdaa154'),
  ('en.sahih', 27, 37, 3196, 'Return to them, for we will surely come to them with soldiers that they will be powerless to encounter, and we will surely expel them therefrom in humiliation, and they will be debased."', NULL, NULL, '925917cc3f3bce94673e562b8ba66eb310801cea2a65d9dbfaed6b4eafb2b0c6'),
  ('en.sahih', 27, 38, 3197, '[Solomon] said, "O assembly [of jinn], which of you will bring me her throne before they come to me in submission?"', NULL, NULL, 'dd639b3ed96354be6f8e9e49dc164cdd3ab7519dbac518ee0b78a0650db3719d'),
  ('en.sahih', 27, 39, 3198, 'A powerful one from among the jinn said, "I will bring it to you before you rise from your place, and indeed, I am for this [task] strong and trustworthy."', NULL, NULL, '3d487acf68a4d5aa2935230c698bd62a37cb03c3f3f76c1b78d4a28083a94dba'),
  ('en.sahih', 27, 40, 3199, 'Said one who had knowledge from the Scripture, "I will bring it to you before your glance returns to you." And when [Solomon] saw it placed before him, he said, "This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful - his gratitude is only for [the benefit of] himself. And whoever is ungrateful - then indeed, my Lord is Free of need and Generous."', NULL, NULL, 'fa72fff62e56e0f78c082bc780b176170d54cb44b91d6501e7b6c475457be8ec'),
  ('en.sahih', 27, 41, 3200, 'He said, "Disguise for her her throne; we will see whether she will be guided [to truth] or will be of those who is not guided."', NULL, NULL, 'eb82b8096d3be75f0a96992d82b5c1e32d9befd329fc0b1ec0551e30905b8ab6')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 27, 42, 3201, 'So when she arrived, it was said [to her], "Is your throne like this?" She said, "[It is] as though it was it." [Solomon said], "And we were given knowledge before her, and we have been Muslims [in submission to Allah].', NULL, NULL, '8ea2caf9b14cbb42e335408aa42ff0b0d0fdd194c20ff20e6fa2f665c658ab0b'),
  ('en.sahih', 27, 43, 3202, 'And that which she was worshipping other than Allah had averted her [from submission to Him]. Indeed, she was from a disbelieving people."', NULL, NULL, '00553a2723f71f2af7eeb156cb471dbdb9b26e550e5abe99095ead4b0f91cc33'),
  ('en.sahih', 27, 44, 3203, 'She was told, "Enter the palace." But when she saw it, she thought it was a body of water and uncovered her shins [to wade through]. He said, "Indeed, it is a palace [whose floor is] made smooth with glass." She said, "My Lord, indeed I have wronged myself, and I submit with Solomon to Allah, Lord of the worlds."', NULL, NULL, 'a1810d4a57dd46f739479adb9757896d987f341aef526be0452b729704f92d33'),
  ('en.sahih', 27, 45, 3204, 'And We had certainly sent to Thamud their brother Salih, [saying], "Worship Allah," and at once they were two parties conflicting.', NULL, NULL, '2f7378c040ef3313867f14a9c9060b4956ef1910ddd50d17031eb2fae817cd7c'),
  ('en.sahih', 27, 46, 3205, 'He said, "O my people, why are you impatient for evil instead of good? Why do you not seek forgiveness of Allah that you may receive mercy?"', NULL, NULL, '315b21fba8236c0eb4c026fe311b5d904f8ed71e0b0724120d92dbda7d6c65bc'),
  ('en.sahih', 27, 47, 3206, 'They said, "We consider you a bad omen, you and those with you." He said, "Your omen is with Allah. Rather, you are a people being tested."', NULL, NULL, '6d23114e5aa6be82c90124891abec3a8a7e42261bc7181efad18b15306ac567e'),
  ('en.sahih', 27, 48, 3207, 'And there were in the city nine family heads causing corruption in the land and not amending [its affairs].', NULL, NULL, '3b3b5cdff372d1dde5d379ae8fa81aae051411048a7378d111502b30be6b6366'),
  ('en.sahih', 27, 49, 3208, 'They said, "Take a mutual oath by Allah that we will kill him by night, he and his family. Then we will say to his executor, ''We did not witness the destruction of his family, and indeed, we are truthful.'' "', NULL, NULL, '75ac71caf5363c001fc1cf9260aa762d948ba5cda574f8003a6a5a46dc77064a'),
  ('en.sahih', 27, 50, 3209, 'And they planned a plan, and We planned a plan, while they perceived not.', NULL, NULL, 'b330ce3b4b4bf53be1923aa2d5524e0f4d2493ccfb9efcd687f0877e502a6805'),
  ('en.sahih', 27, 51, 3210, 'Then look how was the outcome of their plan - that We destroyed them and their people, all.', NULL, NULL, '6ad21973acc84f1c28c51db295f70d4140e31162490f8b24c3347fd2c9681b2c'),
  ('en.sahih', 27, 52, 3211, 'So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know.', NULL, NULL, '087cfa9c7cb9d4a2693d3d48b3697d39ba78ed60c13873c4ab1f0db0984776a8'),
  ('en.sahih', 27, 53, 3212, 'And We saved those who believed and used to fear Allah.', NULL, NULL, 'a43c480e4a7df953da112c0ffe88d17b4f6e8cf01133a51f9023f493737dbff9'),
  ('en.sahih', 27, 54, 3213, 'And [mention] Lot, when he said to his people, "Do you commit immorality while you are seeing?', NULL, NULL, 'ec640235a7d8e8ff1fe113ab56c967928093bb92ddd120570d3c211c0252d782'),
  ('en.sahih', 27, 55, 3214, 'Do you indeed approach men with desire instead of women? Rather, you are a people behaving ignorantly."', NULL, NULL, '7ac159bfebaa7e20d3adf83e2b0e9d07c472c23c3f9de56ec48b6f09c560f57d'),
  ('en.sahih', 27, 56, 3215, 'But the answer of his people was not except that they said, "Expel the family of Lot from your city. Indeed, they are people who keep themselves pure."', NULL, NULL, '8691b8cd43923b8226edacd0bbfeb93f0d98a536b6638f59913c0a5e24146d29'),
  ('en.sahih', 27, 57, 3216, 'So We saved him and his family, except for his wife; We destined her to be of those who remained behind.', NULL, NULL, '0a0d237dbddbbdf9204e8f4b7717d63455979f207fe17863f6a748e29477d18e'),
  ('en.sahih', 27, 58, 3217, 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.', NULL, NULL, '119fd9d3b95be145c0e2c4990d6785452f3b586e076520dff1edf477f5ed3668'),
  ('en.sahih', 27, 59, 3218, 'Say, [O Muhammad], "Praise be to Allah, and peace upon His servants whom He has chosen. Is Allah better or what they associate with Him?"', NULL, NULL, '3d078095911b0e98807c8453eb18244b374e728c9004908e404af3212214761e'),
  ('en.sahih', 27, 60, 3219, '[More precisely], is He [not best] who created the heavens and the earth and sent down for you rain from the sky, causing to grow thereby gardens of joyful beauty which you could not [otherwise] have grown the trees thereof? Is there a deity with Allah? [No], but they are a people who ascribe equals [to Him].', NULL, NULL, '527be75c49d34b9e84c60dbaf8ec12947da26138b7f28d9fabfbc0ebc29fa618'),
  ('en.sahih', 27, 61, 3220, 'Is He [not best] who made the earth a stable ground and placed within it rivers and made for it firmly set mountains and placed between the two seas a barrier? Is there a deity with Allah? [No], but most of them do not know.', NULL, NULL, '1035fb0047efdd3d36197323b69be3a634f2f1735cd0cfe1982c3666c355c674'),
  ('en.sahih', 27, 62, 3221, 'Is He [not best] who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allah? Little do you remember.', NULL, NULL, '9b58dd8296b9f33d84f565d93c0da1638644ca6833a58b6a7e49bcca38cfa150'),
  ('en.sahih', 27, 63, 3222, 'Is He [not best] who guides you through the darknesses of the land and sea and who sends the winds as good tidings before His mercy? Is there a deity with Allah? High is Allah above whatever they associate with Him.', NULL, NULL, '927e37e136895b5ca28675c15320db5cac1a22a551583b9a221adb6b064351d5'),
  ('en.sahih', 27, 64, 3223, 'Is He [not best] who begins creation and then repeats it and who provides for you from the heaven and earth? Is there a deity with Allah? Say, "Produce your proof, if you should be truthful."', NULL, NULL, '18a2db04c43c32e8224d49e023991d2f4b0a61ce070a53837cbc8e4959bfdc66'),
  ('en.sahih', 27, 65, 3224, 'Say, "None in the heavens and earth knows the unseen except Allah, and they do not perceive when they will be resurrected."', NULL, NULL, 'b27f86df9d2de50bd38f97e509eb344163249aa8ed8210cc49715f3ff4696421'),
  ('en.sahih', 27, 66, 3225, 'Rather, their knowledge is arrested concerning the Hereafter. Rather, they are in doubt about it. Rather, they are, concerning it, blind.', NULL, NULL, '8c488f5190b5f810567a900f2ca7bab6ba3e6fa5ac777664c2cf36567b86c892'),
  ('en.sahih', 27, 67, 3226, 'And those who disbelieve say, "When we have become dust as well as our forefathers, will we indeed be brought out [of the graves]?', NULL, NULL, '4056e90edff78ae07fbba158debddd86eb8c3632c108481023fb9b1880f263e9'),
  ('en.sahih', 27, 68, 3227, 'We have been promised this, we and our forefathers, before. This is not but legends of the former peoples."', NULL, NULL, 'ae1c493f4dbb49024c7d647fac8342b182d060cf6e8c76ff0ac4d0d85b299bb8'),
  ('en.sahih', 27, 69, 3228, 'Say, [O Muhammad], "Travel through the land and observe how was the end of the criminals."', NULL, NULL, '1db042709cb7d35beb84c986f91ce1d7f8df413d61c7d4a44da0b53cf8999f6d'),
  ('en.sahih', 27, 70, 3229, 'And grieve not over them or be in distress from what they conspire.', NULL, NULL, '1aac07136005c47cc206b92595a7b4237b085213e028b7b4de782b46eeb72a4b'),
  ('en.sahih', 27, 71, 3230, 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"', NULL, NULL, '9884f1decb74c4094b73b09a71d09a5148744c5676a3ea93ef49c3adc6cd4425'),
  ('en.sahih', 27, 72, 3231, 'Say, "Perhaps it is close behind you - some of that for which you are impatient.', NULL, NULL, '2f745dac2c45ebb5565f55d1b6f62bf425b80d9a522f4c473edc97a39af5f30c'),
  ('en.sahih', 27, 73, 3232, 'And indeed, your Lord is full of bounty for the people, but most of them do not show gratitude."', NULL, NULL, '31c919254ffffa4e242d1d64266b8e267f966a7918eeb97b67a766da3b91a760'),
  ('en.sahih', 27, 74, 3233, 'And indeed, your Lord knows what their breasts conceal and what they declare.', NULL, NULL, '61ed5ce853c8abf0b3f445a3c16245ad7b109ff8dec6082569619f2f6f58c4cc'),
  ('en.sahih', 27, 75, 3234, 'And there is nothing concealed within the heaven and the earth except that it is in a clear Register.', NULL, NULL, 'b6ea591d858c089ab5626b286ee89644b60f55b5cdef7186ac1c45959b4de437'),
  ('en.sahih', 27, 76, 3235, 'Indeed, this Qur''an relates to the Children of Israel most of that over which they disagree.', NULL, NULL, 'e9fb213a074da1cd2399af69a6ab2d5677a6bb64ced8d31ce96d6b5013a9d830'),
  ('en.sahih', 27, 77, 3236, 'And indeed, it is guidance and mercy for the believers.', NULL, NULL, '0bbec9d22ac8502b30251d31434cc493ec669005a21101e33832f56afc8ad72e'),
  ('en.sahih', 27, 78, 3237, 'Indeed, your Lord will judge between them by His [wise] judgement. And He is the Exalted in Might, the Knowing.', NULL, NULL, 'dbe6902ecae7da474b8de531fd89a63d2120f84bc8fab04b2424eff26eede631'),
  ('en.sahih', 27, 79, 3238, 'So rely upon Allah; indeed, you are upon the clear truth.', NULL, NULL, '9739013c7171dfa68b30875e4c0a0630035b8cb87ae5946393eca35fb382bc32'),
  ('en.sahih', 27, 80, 3239, 'Indeed, you will not make the dead hear, nor will you make the deaf hear the call when they have turned their backs retreating.', NULL, NULL, '65b3a85ebb359e1833e4192bad8ddb740b8910879a2d203c4cc16422381576e4'),
  ('en.sahih', 27, 81, 3240, 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [submitting to Allah].', NULL, NULL, '2fd1785c96373d9d82899a5957a45df0231ae040b8c429159d33fee55db21ff5'),
  ('en.sahih', 27, 82, 3241, 'And when the word befalls them, We will bring forth for them a creature from the earth speaking to them, [saying] that the people were, of Our verses, not certain [in faith].', NULL, NULL, '3aaf243d4fb9aeaac8ea61fd3a4a5dfa2e4cf099a56db1feedbb54c2d7aba98e'),
  ('en.sahih', 27, 83, 3242, 'And [warn of] the Day when We will gather from every nation a company of those who deny Our signs, and they will be [driven] in rows', NULL, NULL, 'a2548f0703f71e7987bc0a9017ec392fa5fff67727a3a7f0e3a2898266837ec3'),
  ('en.sahih', 27, 84, 3243, 'Until, when they arrive [at the place of Judgement], He will say, "Did you deny My signs while you encompassed them not in knowledge, or what [was it that] you were doing?"', NULL, NULL, '24af3e70c86954e006aa253d2b98419514031644d844031ad823ad992c5b43ef'),
  ('en.sahih', 27, 85, 3244, 'And the decree will befall them for the wrong they did, and they will not [be able to] speak.', NULL, NULL, '3b436bae3440aff268428265bab134433879142b44ff704069ba9cd02452695d'),
  ('en.sahih', 27, 86, 3245, 'Do they not see that We made the night that they may rest therein and the day giving sight? Indeed in that are signs for a people who believe.', NULL, NULL, '74ed985aee56e68560001862adf7e081f9340ab2f8c3cefe3193ea5c3dc7be3d'),
  ('en.sahih', 27, 87, 3246, 'And [warn of] the Day the Horn will be blown, and whoever is in the heavens and whoever is on the earth will be terrified except whom Allah wills. And all will come to Him humbled.', NULL, NULL, '3a8c3447197c56b17f86e35d90b595c43f1ef8e02b29e0ab9b89305fa5f446da'),
  ('en.sahih', 27, 88, 3247, 'And you see the mountains, thinking them rigid, while they will pass as the passing of clouds. [It is] the work of Allah, who perfected all things. Indeed, He is Acquainted with that which you do.', NULL, NULL, '5f24ed535ebd7ebecc3912253d0ce56237606a4521608701883a16408dbf10bb'),
  ('en.sahih', 27, 89, 3248, 'Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe.', NULL, NULL, 'cde629eb1828607f1f6421271fbd66879e883334bd79f351f37d059651b92b0e'),
  ('en.sahih', 27, 90, 3249, 'And whoever comes with an evil deed - their faces will be overturned into the Fire, [and it will be said], "Are you recompensed except for what you used to do?"', NULL, NULL, '6b3606862831d001ef6abf43dcb73acb8ac0e21835b6af7ec4b5bc7981185eee'),
  ('en.sahih', 27, 91, 3250, '[Say, O Muhammad], "I have only been commanded to worship the Lord of this city, who made it sacred and to whom [belongs] all things. And I am commanded to be of the Muslims [those who submit to Allah]', NULL, NULL, 'b5c3eab7c51cdde7b791ac25c6eb46d55ff68a72494388189101bd0368f6d559'),
  ('en.sahih', 27, 92, 3251, 'And to recite the Qur''an." And whoever is guided is only guided for [the benefit of] himself; and whoever strays - say, "I am only [one] of the warners."', NULL, NULL, 'b06de9eb7213f973b6b42a3736d243f01f807ad908282f7bfb4f2d85492e4e89'),
  ('en.sahih', 27, 93, 3252, 'And say, "[All] praise is [due] to Allah. He will show you His signs, and you will recognize them. And your Lord is not unaware of what you do."', NULL, NULL, 'ebc8f499fcb50e5eb7b835a17c41ee791a2963610caefe43048c71f51bf64506'),
  ('en.sahih', 28, 1, 3253, 'Ta, Seen, Meem.', NULL, NULL, '0ef4275790a43c15542f62fd834a4d45820bf430d4be33209b885d5163b4db79'),
  ('en.sahih', 28, 2, 3254, 'These are the verses of the clear Book.', NULL, NULL, '6802874ff2a5033a4f7f1b8eb6fc22128f011a66754506d268c945ea656d6c4d'),
  ('en.sahih', 28, 3, 3255, 'We recite to you from the news of Moses and Pharaoh in truth for a people who believe.', NULL, NULL, 'b6df207893dcee35757297cef0e25221d0f7a91088dd2ad6178fee424a3507cb'),
  ('en.sahih', 28, 4, 3256, 'Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters.', NULL, NULL, 'd6faa459c7514e0cdb1d130181e3ab775c45c1ef042dd5825a40f54a2d38d6b2'),
  ('en.sahih', 28, 5, 3257, 'And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors', NULL, NULL, '33b8a17477c9d3ed49a569d4ab7fcb6328f11df08127fcae66c264712acdff97'),
  ('en.sahih', 28, 6, 3258, 'And establish them in the land and show Pharaoh and [his minister] Haman and their soldiers through them that which they had feared.', NULL, NULL, 'd9333d1e712e7923c0635ae37692ef03dd993592f62bbdb420996ba5a0f584f6'),
  ('en.sahih', 28, 7, 3259, 'And We inspired to the mother of Moses, "Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers."', NULL, NULL, 'c4bc9b03bce990fd88bca0b0fce036aa8838e426e6b7aea088e1b5b10b93d70b'),
  ('en.sahih', 28, 8, 3260, 'And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners.', NULL, NULL, '750ee58cb3626b875cda288213d18626c4579adcf314bcc10538b001c1d9e369'),
  ('en.sahih', 28, 9, 3261, 'And the wife of Pharaoh said, "[He will be] a comfort of the eye for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son." And they perceived not.', NULL, NULL, '8625a37929d15c530b8b0e8bd1d58ef29c8e95d520db077560cee9db54551bcd'),
  ('en.sahih', 28, 10, 3262, 'And the heart of Moses'' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers.', NULL, NULL, '52eeaacae98daf53b1942ca53cb6c243af54ef498dae529c3aca57a769991bd9'),
  ('en.sahih', 28, 11, 3263, 'And she said to his sister, "Follow him"; so she watched him from a distance while they perceived not.', NULL, NULL, 'cde8cef4c143eee2e06fd587fa91951f3ba2360044ab78e1b50e31b96696639f'),
  ('en.sahih', 28, 12, 3264, 'And We had prevented from him [all] wet nurses before, so she said, "Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?"', NULL, NULL, '433b81325d0184749f2ed4ca4541f36edf1fd718b75ccdeaf98a21bdbc730288'),
  ('en.sahih', 28, 13, 3265, 'So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allah is true. But most of the people do not know.', NULL, NULL, '6c78252af1f600653275e70ce2761f1e5eca5892ed7ca227341816d5fc88eae6'),
  ('en.sahih', 28, 14, 3266, 'And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good.', NULL, NULL, '33636dabeb54f7ea79b828df8a5a0cb423daf0ff60bd9181fd7c2463142f9147'),
  ('en.sahih', 28, 15, 3267, 'And he entered the city at a time of inattention by its people and found therein two men fighting: one from his faction and one from among his enemy. And the one from his faction called for help to him against the one from his enemy, so Moses struck him and [unintentionally] killed him. [Moses] said, "This is from the work of Satan. Indeed, he is a manifest, misleading enemy."', NULL, NULL, '3aa3f84bb878b507a63fa0967af4587433df37313ca3a5168b3d635f25f6deca'),
  ('en.sahih', 28, 16, 3268, 'He said, "My Lord, indeed I have wronged myself, so forgive me," and He forgave him. Indeed, He is the Forgiving, the Merciful.', NULL, NULL, '2ba0e9986efdf79390ff2e5eba07d4bca5a2f4b69cf91c7ba7f1f6af1e3194ff'),
  ('en.sahih', 28, 17, 3269, 'He said, "My Lord, for the favor You bestowed upon me, I will never be an assistant to the criminals."', NULL, NULL, 'f8a7694f07d0acaad33c3056f9a4b355b010aad51c333d89b0ddfb25eab1a6c5'),
  ('en.sahih', 28, 18, 3270, 'And he became inside the city fearful and anticipating [exposure], when suddenly the one who sought his help the previous day cried out to him [once again]. Moses said to him, "Indeed, you are an evident, [persistent] deviator."', NULL, NULL, 'c1270820e4485f3800d717927e2ea2f52e54bb8b483c17b9b03c682d769b700c'),
  ('en.sahih', 28, 19, 3271, 'And when he wanted to strike the one who was an enemy to both of them, he said, "O Moses, do you intend to kill me as you killed someone yesterday? You only want to be a tyrant in the land and do not want to be of the amenders."', NULL, NULL, '437fe15d17b6c467e85954a843661fcf24042f7a31fbbac0e94e00e802b1bbc3'),
  ('en.sahih', 28, 20, 3272, 'And a man came from the farthest end of the city, running. He said, "O Moses, indeed the eminent ones are conferring over you [intending] to kill you, so leave [the city]; indeed, I am to you of the sincere advisors."', NULL, NULL, 'ee439f5a58e6a2679861f9614878a6920d3d6d0fd37eacfe4eb736446651c8b8'),
  ('en.sahih', 28, 21, 3273, 'So he left it, fearful and anticipating [apprehension]. He said, "My Lord, save me from the wrongdoing people."', NULL, NULL, '0bf0d4f0cdeb087da915d8d610aa695d3df293b487255ea365e908efac18f45c'),
  ('en.sahih', 28, 22, 3274, 'And when he directed himself toward Madyan, he said, "Perhaps my Lord will guide me to the sound way."', NULL, NULL, '04cf54b143d3ba196b0a9a350ce88eaee9b26edb684cec759413c4403d9b3496'),
  ('en.sahih', 28, 23, 3275, 'And when he came to the well of Madyan, he found there a crowd of people watering [their flocks], and he found aside from them two women driving back [their flocks]. He said, "What is your circumstance?" They said, "We do not water until the shepherds dispatch [their flocks]; and our father is an old man."', NULL, NULL, '1647ec5c8cc7ef888e17e404274488ef401c400463b85d2b40c4b4259ffb4430'),
  ('en.sahih', 28, 24, 3276, 'So he watered [their flocks] for them; then he went back to the shade and said, "My Lord, indeed I am, for whatever good You would send down to me, in need."', NULL, NULL, 'cec4c2d6bb839ebef0e6712f9b9d0ab10849d6e0ad8fb71ca19567cfd8a8b2d5'),
  ('en.sahih', 28, 25, 3277, 'Then one of the two women came to him walking with shyness. She said, "Indeed, my father invites you that he may reward you for having watered for us." So when he came to him and related to him the story, he said, "Fear not. You have escaped from the wrongdoing people."', NULL, NULL, '6ff61b88c360d80c6566d28127ec224ce00a7201305994a5f69ef3c3e8e17956'),
  ('en.sahih', 28, 26, 3278, 'One of the women said, "O my father, hire him. Indeed, the best one you can hire is the strong and the trustworthy."', NULL, NULL, 'd6927fed4db195fcc341b3d8fae3b79cf0f01d5b2609df9541511da1d70fe6dd'),
  ('en.sahih', 28, 27, 3279, 'He said, "Indeed, I wish to wed you one of these, my two daughters, on [the condition] that you serve me for eight years; but if you complete ten, it will be [as a favor] from you. And I do not wish to put you in difficulty. You will find me, if Allah wills, from among the righteous."', NULL, NULL, '19d9ce7758f78342c2d28fb6aa92d664e252700691a227a0593c959afe4e1671'),
  ('en.sahih', 28, 28, 3280, '[Moses] said, "That is [established] between me and you. Whichever of the two terms I complete - there is no injustice to me, and Allah, over what we say, is Witness."', NULL, NULL, 'c39073246474d1fa593e1ebeeaa875ad9549f231e1ec251f85863f18590aa104'),
  ('en.sahih', 28, 29, 3281, 'And when Moses had completed the term and was traveling with his family, he perceived from the direction of the mount a fire. He said to his family, "Stay here; indeed, I have perceived a fire. Perhaps I will bring you from there [some] information or burning wood from the fire that you may warm yourselves."', NULL, NULL, '758e4fb00e4f7f6aeb22bc84c9c61d67d54f037dc52b4fd46fd56ca0f2c38318'),
  ('en.sahih', 28, 30, 3282, 'But when he came to it, he was called from the right side of the valley in a blessed spot - from the tree, "O Moses, indeed I am Allah, Lord of the worlds."', NULL, NULL, 'b08f2f98f2ec77a01f92d1f495c8c0443602f31498933fcdf09bd3ad25a4807a'),
  ('en.sahih', 28, 31, 3283, 'And [he was told], "Throw down your staff." But when he saw it writhing as if it was a snake, he turned in flight and did not return. [Allah said], "O Moses, approach and fear not. Indeed, you are of the secure.', NULL, NULL, '4966bbd24d3f1dd85f282bf2ee5a3bb67f06468aabc3c9509121732df8a64263'),
  ('en.sahih', 28, 32, 3284, 'Insert your hand into the opening of your garment; it will come out white, without disease. And draw in your arm close to you [as prevention] from fear, for those are two proofs from your Lord to Pharaoh and his establishment. Indeed, they have been a people defiantly disobedient."', NULL, NULL, '7d14d053ebd75d09c73296c61f870cbb7ce9004a27c86dff5aaa114f3cd7dc7b'),
  ('en.sahih', 28, 33, 3285, 'He said, "My Lord, indeed, I killed from among them someone, and I fear they will kill me.', NULL, NULL, '3e037318bf2baf5792cfcd0ee74e809d9992a574345ddb82d650f896d557f9cd'),
  ('en.sahih', 28, 34, 3286, 'And my brother Aaron is more fluent than me in tongue, so send him with me as support, verifying me. Indeed, I fear that they will deny me."', NULL, NULL, 'bffa91446e5b94d42eae5ebe7cde5976f8710a3629b1999a85e610ecbc59b098'),
  ('en.sahih', 28, 35, 3287, '[Allah] said, "We will strengthen your arm through your brother and grant you both supremacy so they will not reach you. [It will be] through Our signs; you and those who follow you will be the predominant."', NULL, NULL, 'e6d240f34e7e2671074af498398020030254240ad6703e85a1eb8ba8b7f952a6'),
  ('en.sahih', 28, 36, 3288, 'But when Moses came to them with Our signs as clear evidences, they said, "This is not except invented magic, and we have not heard of this [religion] among our forefathers."', NULL, NULL, '12b0bdb3ec262747f9c4f6c8ac123afa4216e716cc748246deb61f6169063589'),
  ('en.sahih', 28, 37, 3289, 'And Moses said, "My Lord is more knowing [than we or you] of who has come with guidance from Him and to whom will be succession in the home. Indeed, wrongdoers do not succeed."', NULL, NULL, 'b84dec43524be4c2ef0549126dc7299392f0a07a9754bf4b86cd84b98360814a'),
  ('en.sahih', 28, 38, 3290, 'And Pharaoh said, "O eminent ones, I have not known you to have a god other than me. Then ignite for me, O Haman, [a fire] upon the clay and make for me a tower that I may look at the God of Moses. And indeed, I do think he is among the liars."', NULL, NULL, '5e57afbac00e4719b87da5e2bd363781fe9bdeb831e343b8cdeeb8a3a0500e80'),
  ('en.sahih', 28, 39, 3291, 'And he was arrogant, he and his soldiers, in the land, without right, and they thought that they would not be returned to Us.', NULL, NULL, 'b5175f9cfe9f04e12dc2e7abf52fa5d7793f7554a6a2c2900e36eae3069cb666'),
  ('en.sahih', 28, 40, 3292, 'So We took him and his soldiers and threw them into the sea. So see how was the end of the wrongdoers.', NULL, NULL, 'c49985f0200aa2f7f56a425179360a3315f0ec28eb79101f3892eeb027ba738a'),
  ('en.sahih', 28, 41, 3293, 'And We made them leaders inviting to the Fire, and on the Day of Resurrection they will not be helped.', NULL, NULL, 'e0dda01769d775e4949e5a350c113362882aa2161ee1390878267e0227a1dd37'),
  ('en.sahih', 28, 42, 3294, 'And We caused to overtake them in this world a curse, and on the Day of Resurrection they will be of the despised.', NULL, NULL, 'e3064bd7b99f1d899890b7488a6b305966d4e7eeef4d2efde6bd9ee4f40fdad0'),
  ('en.sahih', 28, 43, 3295, 'And We gave Moses the Scripture, after We had destroyed the former generations, as enlightenment for the people and guidance and mercy that they might be reminded.', NULL, NULL, '6836388173b1ab21a04c61482671281c6360ccbcdda93af1789727fe7466c069'),
  ('en.sahih', 28, 44, 3296, 'And you, [O Muhammad], were not on the western side [of the mount] when We revealed to Moses the command, and you were not among the witnesses [to that].', NULL, NULL, '63407c8e5b0880a0ca2f08623c16ba25639c92bd8bdd87a91e4426f75a9c1107'),
  ('en.sahih', 28, 45, 3297, 'But We produced [many] generations [after Moses], and prolonged was their duration. And you were not a resident among the people of Madyan, reciting to them Our verses, but We were senders [of this message].', NULL, NULL, '6ce507bda1873e55c728d2f72847e06945632bfc687aae80d59b68cd2006a5d8'),
  ('en.sahih', 28, 46, 3298, 'And you were not at the side of the mount when We called [Moses] but [were sent] as a mercy from your Lord to warn a people to whom no warner had come before you that they might be reminded.', NULL, NULL, '138366447e4e1bcd4a215f170d648a700a035dd51483a41d8daa0972b9e9a134'),
  ('en.sahih', 28, 47, 3299, 'And if not that a disaster should strike them for what their hands put forth [of sins] and they would say, "Our Lord, why did You not send us a messenger so we could have followed Your verses and been among the believers?"...', NULL, NULL, '672e8365a338f59f6f4ed52138a2ea7849aaf130dd6b66dd22fdaec043e762e6'),
  ('en.sahih', 28, 48, 3300, 'But when the truth came to them from Us, they said, "Why was he not given like that which was given to Moses?" Did they not disbelieve in that which was given to Moses before? They said, "[They are but] two works of magic supporting each other, and indeed we are, in both, disbelievers."', NULL, NULL, '47335eb135faae7a3e6bd842ed43100c8d6a1de46c2c8567e59496a6772ded48')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 28, 49, 3301, 'Say, "Then bring a scripture from Allah which is more guiding than either of them that I may follow it, if you should be truthful."', NULL, NULL, '4cb0be35237d04af110f755fccff07c75f4d1295d2dea63186096f0147230fbe'),
  ('en.sahih', 28, 50, 3302, 'But if they do not respond to you - then know that they only follow their [own] desires. And who is more astray than one who follows his desire without guidance from Allah? Indeed, Allah does not guide the wrongdoing people.', NULL, NULL, '72fe1631dcfabc276a14de493b6f2da0091aa396ba443484c7de4e173f949b82'),
  ('en.sahih', 28, 51, 3303, 'And We have [repeatedly] conveyed to them the Qur''an that they might be reminded.', NULL, NULL, '3582caa1c26a495b9a48a68462b045af8c63798baebc58689ed45342f0e276ae'),
  ('en.sahih', 28, 52, 3304, 'Those to whom We gave the Scripture before it - they are believers in it.', NULL, NULL, '9c5574b47fc0aa1c83b51418287b5f41d2baac79b026a9de42fce12b52d68c73'),
  ('en.sahih', 28, 53, 3305, 'And when it is recited to them, they say, "We have believed in it; indeed, it is the truth from our Lord. Indeed we were, [even] before it, Muslims [submitting to Allah]."', NULL, NULL, '88a56724ad545e62cd45b27431d6b9c5152e674f219dc831d874547e6ba4729c'),
  ('en.sahih', 28, 54, 3306, 'Those will be given their reward twice for what they patiently endured and [because] they avert evil through good, and from what We have provided them they spend.', NULL, NULL, 'ca1003194eda194af8edd8a6feaccd2327b44604091fc9f493f56cd08bf2864a'),
  ('en.sahih', 28, 55, 3307, 'And when they hear ill speech, they turn away from it and say, "For us are our deeds, and for you are your deeds. Peace will be upon you; we seek not the ignorant."', NULL, NULL, 'f2135df7684440f28ca3d60fc97d2726f8cc39d1b96b1356978c88f99275c848'),
  ('en.sahih', 28, 56, 3308, 'Indeed, [O Muhammad], you do not guide whom you like, but Allah guides whom He wills. And He is most knowing of the [rightly] guided.', NULL, NULL, '864ca14b9dbd52ba71e45c14ec7e9f56c60638d4434344b1e0eea2d054154d3f'),
  ('en.sahih', 28, 57, 3309, 'And they say, "If we were to follow the guidance with you, we would be swept from our land." Have we not established for them a safe sanctuary to which are brought the fruits of all things as provision from Us? But most of them do not know.', NULL, NULL, 'e90f8f072418979e20656c3c49721d3224c89aa9c2d1f0ff2c2283dd7d2ddf21'),
  ('en.sahih', 28, 58, 3310, 'And how many a city have We destroyed that was insolent in its [way of] living, and those are their dwellings which have not been inhabited after them except briefly. And it is We who were the inheritors.', NULL, NULL, 'b3f5cb1bd393157a62f39d18d93e0358174c93b860a61656e9995edd1199fdb9'),
  ('en.sahih', 28, 59, 3311, 'And never would your Lord have destroyed the cities until He had sent to their mother a messenger reciting to them Our verses. And We would not destroy the cities except while their people were wrongdoers.', NULL, NULL, 'e78c247a9cc1c712f9ad461ccd129858b1529ad5cecdba2cd271f78afed1ff1e'),
  ('en.sahih', 28, 60, 3312, 'And whatever thing you [people] have been given - it is [only for] the enjoyment of worldly life and its adornment. And what is with Allah is better and more lasting; so will you not use reason?', NULL, NULL, 'a8eb27a7b8b90509cf4bfd7c09fa87d32b7564d123a5f04b71364badf2b4e54d'),
  ('en.sahih', 28, 61, 3313, 'Then is he whom We have promised a good promise which he will obtain like he for whom We provided enjoyment of worldly life [but] then he is, on the Day of Resurrection, among those presented [for punishment in Hell]?', NULL, NULL, '92b499f3835a6e4fb16087fdb9f959a9f09bd3a4f4633460de7ac8a3df6d936c'),
  ('en.sahih', 28, 62, 3314, 'And [warn of] the Day He will call them and say, "Where are My ''partners'' which you used to claim?"', NULL, NULL, '48562b21d91b3489b96bd0fc726631950783caec3b39cd703dd52d27befa3521'),
  ('en.sahih', 28, 63, 3315, 'Those upon whom the word will have come into effect will say, "Our Lord, these are the ones we led to error. We led them to error just as we were in error. We declare our disassociation [from them] to You. They did not used to worship us."', NULL, NULL, '9723b31ac4b8b5d54536e31594c5019f69f2102a3915a22afe4b41d5208dc52c'),
  ('en.sahih', 28, 64, 3316, 'And it will be said, "Invoke your ''partners'' " and they will invoke them; but they will not respond to them, and they will see the punishment. If only they had followed guidance!', NULL, NULL, 'a7f3231a4a508e1983cc42e65f54f1560729dcc1d8e09fbefadf03cfe823c9b8'),
  ('en.sahih', 28, 65, 3317, 'And [mention] the Day He will call them and say, "What did you answer the messengers?"', NULL, NULL, '5ff28f2c6779f596a9ea66105cb41a8e69c7e50a1bae5f8253bd76e22a18e7e3'),
  ('en.sahih', 28, 66, 3318, 'But the information will be unapparent to them that Day, so they will not [be able to] ask one another.', NULL, NULL, '8a5f767b31ec444c686b97338d8024a2dbe647ace6993104429afd85b92d3ae7'),
  ('en.sahih', 28, 67, 3319, 'But as for one who had repented, believed, and done righteousness, it is promised by Allah that he will be among the successful.', NULL, NULL, 'aed4754b9dedcf2992842320f023a6582c6c36d8d802a1f6bac894526ab6dba5'),
  ('en.sahih', 28, 68, 3320, 'And your Lord creates what He wills and chooses; not for them was the choice. Exalted is Allah and high above what they associate with Him.', NULL, NULL, '9a29549473df2db43687e1fe170150763ea201603d2ef8412b3491d3c49b09c9'),
  ('en.sahih', 28, 69, 3321, 'And your Lord knows what their breasts conceal and what they declare.', NULL, NULL, '88575763a5c636274b34338bc8e590169625974139302dd38fa3365165e6cbf5'),
  ('en.sahih', 28, 70, 3322, 'And He is Allah; there is no deity except Him. To Him is [due all] praise in the first [life] and the Hereafter. And His is the [final] decision, and to Him you will be returned.', NULL, NULL, '15293b614de5cc42643a8c6d3fffc8eaff6f97035ee14930818206f1b91db5e4'),
  ('en.sahih', 28, 71, 3323, 'Say, "Have you considered: if Allah should make for you the night continuous until the Day of Resurrection, what deity other than Allah could bring you light? Then will you not hear?"', NULL, NULL, '8c04e75bafda93c92e2d5fa48cd8df1ecb547409e08a599fa5df907928ee14ab'),
  ('en.sahih', 28, 72, 3324, 'Say, "Have you considered: if Allah should make for you the day continuous until the Day of Resurrection, what deity other than Allah could bring you a night in which you may rest? Then will you not see?"', NULL, NULL, '349603f949f0d000bc0f400215c8b2150bc21fba5ac32b1618ebe2c8a89a92b0'),
  ('en.sahih', 28, 73, 3325, 'And out of His mercy He made for you the night and the day that you may rest therein and [by day] seek from His bounty and [that] perhaps you will be grateful.', NULL, NULL, '46209dada028579c9f7110aa7a6f6af23225c67f35b59a14e986c0f95a1b823d'),
  ('en.sahih', 28, 74, 3326, 'And [warn of] the Day He will call them and say, "Where are my ''partners'' which you used to claim?"', NULL, NULL, '720bffb5b43d8d8b274298cde831ecba030f5a9cacf0e2d3185e9ffcb3ac6179'),
  ('en.sahih', 28, 75, 3327, 'And We will extract from every nation a witness and say, "Produce your proof," and they will know that the truth belongs to Allah, and lost from them is that which they used to invent.', NULL, NULL, '377e7df24399182e8eb4f7716aeade7b9b2134fbd717c9a4c31cf5e46bfefa5b'),
  ('en.sahih', 28, 76, 3328, 'Indeed, Qarun was from the people of Moses, but he tyrannized them. And We gave him of treasures whose keys would burden a band of strong men; thereupon his people said to him, "Do not exult. Indeed, Allah does not like the exultant.', NULL, NULL, 'f6293b7f34ceb2414476d7c0a49175d3a120ca1a2dec2dd9df6febb8c5dcb7d2'),
  ('en.sahih', 28, 77, 3329, 'But seek, through that which Allah has given you, the home of the Hereafter; and [yet], do not forget your share of the world. And do good as Allah has done good to you. And desire not corruption in the land. Indeed, Allah does not like corrupters."', NULL, NULL, '200e2b4ae8efc8be9bc4f9c625f244c29e5e283bdbd4e153bcda0dfd2c740de8'),
  ('en.sahih', 28, 78, 3330, 'He said, "I was only given it because of knowledge I have." Did he not know that Allah had destroyed before him of generations those who were greater than him in power and greater in accumulation [of wealth]? But the criminals, about their sins, will not be asked.', NULL, NULL, '38b8fd6c4784c0d84a8cc364b1215ace282da3b3c3343885f297f2e6ccb460ef'),
  ('en.sahih', 28, 79, 3331, 'So he came out before his people in his adornment. Those who desired the worldly life said, "Oh, would that we had like what was given to Qarun. Indeed, he is one of great fortune."', NULL, NULL, 'b6984739e51fe3c7201a27e0b9809435a2c77c6e8d4bbea417754d8bb596ff80'),
  ('en.sahih', 28, 80, 3332, 'But those who had been given knowledge said, "Woe to you! The reward of Allah is better for he who believes and does righteousness. And none are granted it except the patient."', NULL, NULL, '404fc39b809e2721c3da1bcb125423649727195ab9378f0d182b286802383b97'),
  ('en.sahih', 28, 81, 3333, 'And We caused the earth to swallow him and his home. And there was for him no company to aid him other than Allah, nor was he of those who [could] defend themselves.', NULL, NULL, '33cd95ff5662bb752dd1628f9c2cef5b89418a798a687804a2f082e4675b4f90'),
  ('en.sahih', 28, 82, 3334, 'And those who had wished for his position the previous day began to say, "Oh, how Allah extends provision to whom He wills of His servants and restricts it! If not that Allah had conferred favor on us, He would have caused it to swallow us. Oh, how the disbelievers do not succeed!"', NULL, NULL, 'd2cbea5a5033490be62e22af56e0c2e1511fd07f91a1bff923f7b7dca325e57f'),
  ('en.sahih', 28, 83, 3335, 'That home of the Hereafter We assign to those who do not desire exaltedness upon the earth or corruption. And the [best] outcome is for the righteous.', NULL, NULL, 'fb52f680c2afa91e8763f4e509fe08920bbe42533b216a9bf2f0b54b1f5b0580'),
  ('en.sahih', 28, 84, 3336, 'Whoever comes [on the Day of Judgement] with a good deed will have better than it; and whoever comes with an evil deed - then those who did evil deeds will not be recompensed except [as much as] what they used to do.', NULL, NULL, 'f5e2847b10679932d333433c5d026d96be45e5c40efca8f6eddb909c95a7d51b'),
  ('en.sahih', 28, 85, 3337, 'Indeed, [O Muhammad], He who imposed upon you the Qur''an will take you back to a place of return. Say, "My Lord is most knowing of who brings guidance and who is in clear error."', NULL, NULL, '564d1567558f1476b0bbcd0c78b709bd1252d8a9eeca4c0db9773348b318acd4'),
  ('en.sahih', 28, 86, 3338, 'And you were not expecting that the Book would be conveyed to you, but [it is] a mercy from your Lord. So do not be an assistant to the disbelievers.', NULL, NULL, 'bb5e47b8ed8ca1cbf3e527b5227806dc4fcec71b4c4e72a05de6b73d3f5fd530'),
  ('en.sahih', 28, 87, 3339, 'And never let them avert you from the verses of Allah after they have been revealed to you. And invite [people] to your Lord. And never be of those who associate others with Allah.', NULL, NULL, '7dec413476b5e567baf0727b4cc970db31fa9236aa86c7e440a8862957914f99'),
  ('en.sahih', 28, 88, 3340, 'And do not invoke with Allah another deity. There is no deity except Him. Everything will be destroyed except His Face. His is the judgement, and to Him you will be returned.', NULL, NULL, 'b0a87531c0782d5739a67d08866d39ee13a80400a92b9df93877639bbbad4489'),
  ('en.sahih', 29, 1, 3341, 'Alif, Lam, Meem', NULL, NULL, 'e4b0f6bd9de839f23c4b4ad4c011cd9546777bc11a852109e78a9c924942369a'),
  ('en.sahih', 29, 2, 3342, 'Do the people think that they will be left to say, "We believe" and they will not be tried?', NULL, NULL, 'f2ff4849e8104c5dc928792d87e6c2c18c3a7dae954ddfa6c1106dbf33ad9780'),
  ('en.sahih', 29, 3, 3343, 'But We have certainly tried those before them, and Allah will surely make evident those who are truthful, and He will surely make evident the liars.', NULL, NULL, 'ce7e2d38de5737815a6065d3cae20f9010713fad30dd475695a56dcc66f7e2a6'),
  ('en.sahih', 29, 4, 3344, 'Or do those who do evil deeds think they can outrun Us? Evil is what they judge.', NULL, NULL, '29fe1cf57b4674f9a2fde7ae5d4fb74b6f143c1fa6d9baed6c234fbc83606d3a'),
  ('en.sahih', 29, 5, 3345, 'Whoever should hope for the meeting with Allah - indeed, the term decreed by Allah is coming. And He is the Hearing, the Knowing.', NULL, NULL, '62b0ea22ce31287297f1835456405dab769bc24306f1d19576e6903b5788f407'),
  ('en.sahih', 29, 6, 3346, 'And whoever strives only strives for [the benefit of] himself. Indeed, Allah is free from need of the worlds.', NULL, NULL, 'a2a4d8cd7ba74d381a00ec239a41957793d4ebaeff50c15e2dda059228f8b71e'),
  ('en.sahih', 29, 7, 3347, 'And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do.', NULL, NULL, '4ff327654d785c94161c4ddfa67cff1b37b5cca4a293b3a3e67ccff0ee1a8a76'),
  ('en.sahih', 29, 8, 3348, 'And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do.', NULL, NULL, 'bf1ca933e224cbe68207153858e5c8ad808b38eaf22b614a3e08536c1f542d22'),
  ('en.sahih', 29, 9, 3349, 'And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise].', NULL, NULL, 'e6fa1038e898e4202b6c1d99fd17b95a3b856fbad979909a5bf2450d1eb27077'),
  ('en.sahih', 29, 10, 3350, 'And of the people are some who say, "We believe in Allah," but when one [of them] is harmed for [the cause of] Allah, they consider the trial of the people as [if it were] the punishment of Allah. But if victory comes from your Lord, they say, "Indeed, We were with you." Is not Allah most knowing of what is within the breasts of all creatures?', NULL, NULL, 'fb242f87063e575e929203d5e3d54ce8220366050dd1f8dee2e4e8dbb854de18'),
  ('en.sahih', 29, 11, 3351, 'And Allah will surely make evident those who believe, and He will surely make evident the hypocrites.', NULL, NULL, '1fbb3b7372232e8d897e65a04c950598f65d52a8b8292b79dd6cfc2a629fe1cb'),
  ('en.sahih', 29, 12, 3352, 'And those who disbelieve say to those who believe, "Follow our way, and we will carry your sins." But they will not carry anything of their sins. Indeed, they are liars.', NULL, NULL, 'e4236ad5b4409774e0497d715d648fd49e3f4931498b633e91cb591bad8e17b0'),
  ('en.sahih', 29, 13, 3353, 'But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent.', NULL, NULL, '55e8454e893cf9d8cdd380b6c40296b64f44f78bcb157ad7b6e5ccc417967a63'),
  ('en.sahih', 29, 14, 3354, 'And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.', NULL, NULL, '24a647ace8469a342412c0de58b7c38bbe73223807e1073169f3742b61aea82b'),
  ('en.sahih', 29, 15, 3355, 'But We saved him and the companions of the ship, and We made it a sign for the worlds.', NULL, NULL, '5348a041c2af2da996f9c29e53590f0274d09efc1f2c03be0db9004c3100db2e'),
  ('en.sahih', 29, 16, 3356, 'And [We sent] Abraham, when he said to his people, "Worship Allah and fear Him. That is best for you, if you should know.', NULL, NULL, 'ff03a543163b472e99c44c9e707cbf505387e72dfb24843619b036b3351f61b6'),
  ('en.sahih', 29, 17, 3357, 'You only worship, besides Allah, idols, and you produce a falsehood. Indeed, those you worship besides Allah do not possess for you [the power of] provision. So seek from Allah provision and worship Him and be grateful to Him. To Him you will be returned."', NULL, NULL, '1031bcc6edfa70f440b19a8565c156ef69e25e3d66fe1b000560543c980e8246'),
  ('en.sahih', 29, 18, 3358, 'And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification.', NULL, NULL, 'b8b480285fdb0a09a2b0d1ca6be36e069e6cc04a8dc48dd3676893d5f7a8feb4'),
  ('en.sahih', 29, 19, 3359, 'Have they not considered how Allah begins creation and then repeats it? Indeed that, for Allah, is easy.', NULL, NULL, 'c23cbd0fb6cdbab0d8d4737f0a3dba55ba7651ac67ca27f17827d233214482f2'),
  ('en.sahih', 29, 20, 3360, 'Say, [O Muhammad], "Travel through the land and observe how He began creation. Then Allah will produce the final creation. Indeed Allah, over all things, is competent."', NULL, NULL, 'a9b66f08d7651cc0cb4881c5c8021e914bbff683c00b01e1c1c2b56f13d23c91'),
  ('en.sahih', 29, 21, 3361, 'He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned.', NULL, NULL, 'bf8c8ceff0ab63ed45ea338c3d1c423fa1b970bf82390cdf31561ef5cc1137f9'),
  ('en.sahih', 29, 22, 3362, 'And you will not cause failure [to Allah] upon the earth or in the heaven. And you have not other than Allah any protector or any helper.', NULL, NULL, 'd46abb9bd077e28c63c01b19929812b00b1d618787355de42faf0c458c07583d'),
  ('en.sahih', 29, 23, 3363, 'And the ones who disbelieve in the signs of Allah and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment.', NULL, NULL, 'ea08d44ede25801146e425ff409980c7d1ac4e7861538eb574ce86a8864fafb3'),
  ('en.sahih', 29, 24, 3364, 'And the answer of Abraham''s people was not but that they said, "Kill him or burn him," but Allah saved him from the fire. Indeed in that are signs for a people who believe.', NULL, NULL, 'a3288cf7ca1577e2fc673b24c03fd7d21eb844e43c385e7f2c6435b564627fd0'),
  ('en.sahih', 29, 25, 3365, 'And [Abraham] said, "You have only taken, other than Allah, idols as [a bond of] affection among you in worldly life. Then on the Day of Resurrection you will deny one another and curse one another, and your refuge will be the Fire, and you will not have any helpers."', NULL, NULL, 'e4bec0b98dce6147769831da3eb286740a59c468274fe93d3cd8016260ae8f04'),
  ('en.sahih', 29, 26, 3366, 'And Lot believed him. [Abraham] said, "Indeed, I will emigrate to [the service of] my Lord. Indeed, He is the Exalted in Might, the Wise."', NULL, NULL, 'c025d0c6807453f77ed2d7f0cda6446ba8ac783f4719b21b31715c552abb5f4f'),
  ('en.sahih', 29, 27, 3367, 'And We gave to Him Isaac and Jacob and placed in his descendants prophethood and scripture. And We gave him his reward in this world, and indeed, he is in the Hereafter among the righteous.', NULL, NULL, 'ba5b12bc316dbc62ea07a29bd66aae46da9788bd9d4e51859f4243aca94f7ab6'),
  ('en.sahih', 29, 28, 3368, 'And [mention] Lot, when he said to his people, "Indeed, you commit such immorality as no one has preceded you with from among the worlds.', NULL, NULL, 'd65096c0a610ad7dd69efe8310ba8c7718b49857b3354c6787817664d20b9130'),
  ('en.sahih', 29, 29, 3369, 'Indeed, you approach men and obstruct the road and commit in your meetings [every] evil." And the answer of his people was not but they said, "Bring us the punishment of Allah, if you should be of the truthful."', NULL, NULL, 'f4c5b7c0e0d8406aa9ae271b44835658e02c2e79311369290ddc85448f8fa6fb'),
  ('en.sahih', 29, 30, 3370, 'He said, "My Lord, support me against the corrupting people."', NULL, NULL, '166c98256dbb6153d5c42654e50b9853a8a2923f1a86afce80f340bf981fa822'),
  ('en.sahih', 29, 31, 3371, 'And when Our messengers came to Abraham with the good tidings, they said, "Indeed, we will destroy the people of that Lot''s city. Indeed, its people have been wrongdoers."', NULL, NULL, '456c324a49ec105a81e7183714dfd02c38eeea439796c1a28869c28cee205696'),
  ('en.sahih', 29, 32, 3372, '[Abraham] said, "Indeed, within it is Lot." They said, "We are more knowing of who is within it. We will surely save him and his family, except his wife. She is to be of those who remain behind."', NULL, NULL, 'c9a218fdfc2b4d29596cafc06fca71f0281ff88d9c472eb9cb078235ed4bd11b'),
  ('en.sahih', 29, 33, 3373, 'And when Our messengers came to Lot, he was distressed for them and felt for them great discomfort. They said, "Fear not, nor grieve. Indeed, we will save you and your family, except your wife; she is to be of those who remain behind.', NULL, NULL, '9a70e2076a10ffb6eae03091c479a7c5578def3464f9544c333aae59cfbc30d2'),
  ('en.sahih', 29, 34, 3374, 'Indeed, we will bring down on the people of this city punishment from the sky because they have been defiantly disobedient."', NULL, NULL, '406169b7ccf627f316e2942f103d4383099b7b7c5b9297d80a772c648c9f8fe7'),
  ('en.sahih', 29, 35, 3375, 'And We have certainly left of it a sign as clear evidence for a people who use reason.', NULL, NULL, '2a389fd4d86beac7832fda470333ddfabe721cb5199c230b1bd6b22aca26bc26'),
  ('en.sahih', 29, 36, 3376, 'And to Madyan [We sent] their brother Shu''ayb, and he said, "O my people, worship Allah and expect the Last Day and do not commit abuse on the earth, spreading corruption."', NULL, NULL, 'dc65ce6ee3a32c7a14217f7c3becf16f3f63c6051a004a44d31670297410e3b0'),
  ('en.sahih', 29, 37, 3377, 'But they denied him, so the earthquake seized them, and they became within their home [corpses] fallen prone.', NULL, NULL, '7c97aeb0a86726f80471fe1dca98b3e42760e810998effccdec3649eb91d0fd1'),
  ('en.sahih', 29, 38, 3378, 'And [We destroyed] ''Aad and Thamud, and it has become clear to you from their [ruined] dwellings. And Satan had made pleasing to them their deeds and averted them from the path, and they were endowed with perception.', NULL, NULL, '15f498b636cc7e0d0a2377269bf09d9f9fe1efa6786d50c6cdbdfb70d5baafd0'),
  ('en.sahih', 29, 39, 3379, 'And [We destroyed] Qarun and Pharaoh and Haman. And Moses had already come to them with clear evidences, and they were arrogant in the land, but they were not outrunners [of Our punishment].', NULL, NULL, 'ba8a04771177725493e9ebcadf328297abd6a4d1b33d8a6e7b7e1fb284d92c0d'),
  ('en.sahih', 29, 40, 3380, 'So each We seized for his sin; and among them were those upon whom We sent a storm of stones, and among them were those who were seized by the blast [from the sky], and among them were those whom We caused the earth to swallow, and among them were those whom We drowned. And Allah would not have wronged them, but it was they who were wronging themselves.', NULL, NULL, 'd0985eaaabcbe79e389cf5229c0ed4d9d997ce8ce3bbe6f74559182f79be950c'),
  ('en.sahih', 29, 41, 3381, 'The example of those who take allies other than Allah is like that of the spider who takes a home. And indeed, the weakest of homes is the home of the spider, if they only knew.', NULL, NULL, '064a1e76319d3b04d59aac46f6c9fcdb94334a3a8c98dfe2f27ea1f9e1e2a372'),
  ('en.sahih', 29, 42, 3382, 'Indeed, Allah knows whatever thing they call upon other than Him. And He is the Exalted in Might, the Wise.', NULL, NULL, '9e7fa8901e2a1dae9c380bf9428a160cb8a083a2067ab9bf57919156945ecaf2'),
  ('en.sahih', 29, 43, 3383, 'And these examples We present to the people, but none will understand them except those of knowledge.', NULL, NULL, '28e272e7847809fbc52eba8de0859fd4c6a2fd804658478a3bf8d656d2f625a9'),
  ('en.sahih', 29, 44, 3384, 'Allah created the heavens and the earth in truth. Indeed in that is a sign for the believers.', NULL, NULL, 'e40df67e36b2cf41b36e5873c78a3eb83f165daa0e051f9fd6600c30af260976'),
  ('en.sahih', 29, 45, 3385, 'Recite, [O Muhammad], what has been revealed to you of the Book and establish prayer. Indeed, prayer prohibits immorality and wrongdoing, and the remembrance of Allah is greater. And Allah knows that which you do.', NULL, NULL, '83a3c84866d0b973d3ecf287a29d1be028dcb06324385f27123750b6631d463a'),
  ('en.sahih', 29, 46, 3386, 'And do not argue with the People of the Scripture except in a way that is best, except for those who commit injustice among them, and say, "We believe in that which has been revealed to us and revealed to you. And our God and your God is one; and we are Muslims [in submission] to Him."', NULL, NULL, '0caf2a8daf6a6c8b6a9a768258001a3e86a04627c4ebebeb0893a2d21c17f455'),
  ('en.sahih', 29, 47, 3387, 'And thus We have sent down to you the Qur''an. And those to whom We [previously] gave the Scripture believe in it. And among these [people of Makkah] are those who believe in it. And none reject Our verses except the disbelievers.', NULL, NULL, '5fe9e669f4f5012142f7b89dca6a5d2efcd1964e5f4766b76c8d0be3c299eb1e'),
  ('en.sahih', 29, 48, 3388, 'And you did not recite before it any scripture, nor did you inscribe one with your right hand. Otherwise the falsifiers would have had [cause for] doubt.', NULL, NULL, '415b086f2abcff42407d268d2d967762011c2fce24daa2eafbe257d425b1758f'),
  ('en.sahih', 29, 49, 3389, 'Rather, the Qur''an is distinct verses [preserved] within the breasts of those who have been given knowledge. And none reject Our verses except the wrongdoers.', NULL, NULL, '10d3d599846d3d06b1a1f5e5ea515e842ae82ba658a7de99d197d97833ba96c1'),
  ('en.sahih', 29, 50, 3390, 'But they say, "Why are not signs sent down to him from his Lord?" Say, "The signs are only with Allah, and I am only a clear warner."', NULL, NULL, '00370cfe580f653596ff24bff9ddc4214bfa5bf6b8d14813edef93b53f7fb073'),
  ('en.sahih', 29, 51, 3391, 'And is it not sufficient for them that We revealed to you the Book which is recited to them? Indeed in that is a mercy and reminder for a people who believe.', NULL, NULL, 'a8c186e6e10fd20bfce81de3566d6822a50dcd3ec7f493c4e579b0aefacedd7e'),
  ('en.sahih', 29, 52, 3392, 'Say, "Sufficient is Allah between me and you as Witness. He knows what is in the heavens and earth. And they who have believed in falsehood and disbelieved in Allah - it is those who are the losers."', NULL, NULL, '18c0c98d052bc432ec4d7f07a9c2a33a55eceff6b76bc87cdb0b40c78e8810fa'),
  ('en.sahih', 29, 53, 3393, 'And they urge you to hasten the punishment. And if not for [the decree of] a specified term, punishment would have reached them. But it will surely come to them suddenly while they perceive not.', NULL, NULL, 'b3b23311125d3eaa7b90e0018b366aece8c45c3d93586e0bd02fd84056ff1236'),
  ('en.sahih', 29, 54, 3394, 'They urge you to hasten the punishment. And indeed, Hell will be encompassing of the disbelievers', NULL, NULL, '51195e910763f831a23cc40e5ae4e702c7eec43cebdecf2c71dac2ac9fb5bfa7'),
  ('en.sahih', 29, 55, 3395, 'On the Day the punishment will cover them from above them and from below their feet and it is said, "Taste [the result of] what you used to do."', NULL, NULL, 'a4222d3c1cba18853d8cbecf2830fab81df57b5982ed16a6caf9f15b0c4e05d8'),
  ('en.sahih', 29, 56, 3396, 'O My servants who have believed, indeed My earth is spacious, so worship only Me.', NULL, NULL, 'c2aa2d9df70c50e563978e3ab0514a76d36ef1b28c8198608c7a5e32f17f6f90'),
  ('en.sahih', 29, 57, 3397, 'Every soul will taste death. Then to Us will you be returned.', NULL, NULL, '65fce38af7d305db69d2bded09f2e0f516491d1ca230f42755d213c07314a768'),
  ('en.sahih', 29, 58, 3398, 'And those who have believed and done righteous deeds - We will surely assign to them of Paradise [elevated] chambers beneath which rivers flow, wherein they abide eternally. Excellent is the reward of the [righteous] workers', NULL, NULL, '39502811ae7a1e514ee4d4ab84c6d64f35d6f973458cfe8f4a5286d03a26d448'),
  ('en.sahih', 29, 59, 3399, 'Who have been patient and upon their Lord rely.', NULL, NULL, '73e285febadc4fedde802a74affc10e25257f84cd03eef071dcc9fce1b459f0d'),
  ('en.sahih', 29, 60, 3400, 'And how many a creature carries not its [own] provision. Allah provides for it and for you. And He is the Hearing, the Knowing.', NULL, NULL, '6c848ae10ee973f777babde227fcd06d93e802d7ce7fdb33cf9df94324749924')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 29, 61, 3401, 'If you asked them, "Who created the heavens and earth and subjected the sun and the moon?" they would surely say, "Allah." Then how are they deluded?', NULL, NULL, '6b1e481ad03bfa3f918ad4892fddf7aacee7097c611012a800626714f66ac263'),
  ('en.sahih', 29, 62, 3402, 'Allah extends provision for whom He wills of His servants and restricts for him. Indeed Allah is, of all things, Knowing.', NULL, NULL, '90f2dd9cb44f9ff45b09b9cc513bf604493c505f61526ca183496a6561d22116'),
  ('en.sahih', 29, 63, 3403, 'And if you asked them, "Who sends down rain from the sky and gives life thereby to the earth after its lifelessness?" they would surely say " Allah." Say, "Praise to Allah "; but most of them do not reason.', NULL, NULL, 'b44e87aeac148671e0962763b17cba002a8f396864230a9ac891b9e295416f72'),
  ('en.sahih', 29, 64, 3404, 'And this worldly life is not but diversion and amusement. And indeed, the home of the Hereafter - that is the [eternal] life, if only they knew.', NULL, NULL, '81a8fe025a6287e23df48dbc175a6329b5c3e41054c3af75c0135c428add272b'),
  ('en.sahih', 29, 65, 3405, 'And when they board a ship, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, at once they associate others with Him', NULL, NULL, '8a5ae035a166a91df2193112c408a3c1ea43778abd07f2485d647ef5ca294bfc'),
  ('en.sahih', 29, 66, 3406, 'So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know.', NULL, NULL, '5b08e4b9c0942cd4afe9172ac05d76c4646768246cb6bbf64dfca892687798a0'),
  ('en.sahih', 29, 67, 3407, 'Have they not seen that We made [Makkah] a safe sanctuary, while people are being taken away all around them? Then in falsehood do they believe, and in the favor of Allah they disbelieve?', NULL, NULL, 'ccc59a13072b57392f01fa23a7815677822f42f202fb67a08693c2e628d7803d'),
  ('en.sahih', 29, 68, 3408, 'And who is more unjust than one who invents a lie about Allah or denies the truth when it has come to him? Is there not in Hell a [sufficient] residence for the disbelievers?', NULL, NULL, '6334fd8f430fea0a2e2872915a6108846a4ff66ec9bfdfe6315a85d93985a1f2'),
  ('en.sahih', 29, 69, 3409, 'And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good.', NULL, NULL, 'aa7d314a4c48510204da5ce7366f0eae2e4bea1068ab967f226d8e827c478a47'),
  ('en.sahih', 30, 1, 3410, 'Alif, Lam, Meem.', NULL, NULL, 'c0271a8d54e5b8ca6868a624b25c94d32c317177546d0577b0ceceac58956c78'),
  ('en.sahih', 30, 2, 3411, 'The Byzantines have been defeated', NULL, NULL, '0af17b56b8080dc5f80e03db5eef90ae6ce57032a91aa491b08cc82f6d111222'),
  ('en.sahih', 30, 3, 3412, 'In the nearest land. But they, after their defeat, will overcome.', NULL, NULL, '64d9595de52f034239a9e8f33c3115968b523ac01ea4803445990d863e9f75d3'),
  ('en.sahih', 30, 4, 3413, 'Within three to nine years. To Allah belongs the command before and after. And that day the believers will rejoice', NULL, NULL, 'e3e532684e1a56c6d7c0e17512de23fd85c37d27c8fe1946d5d109ed68a72db0'),
  ('en.sahih', 30, 5, 3414, 'In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.', NULL, NULL, '53b76cba4e53385c39b90b887e785eae4ccf2a83562b6f92804fb7b73803aff3'),
  ('en.sahih', 30, 6, 3415, '[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know.', NULL, NULL, 'e10e6da0e52e4b4dc20d7b4487ef0b0fbffa472ef4ecd2e00dd51ed9517aa034'),
  ('en.sahih', 30, 7, 3416, 'They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.', NULL, NULL, 'd9f4b24e4b8cfd98394de1b268be3aefddf35be29fdb9f0f8a0fe629229394cc'),
  ('en.sahih', 30, 8, 3417, 'Do they not contemplate within themselves? Allah has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in [the matter of] the meeting with their Lord, are disbelievers.', NULL, NULL, '0e2849ba509479f78a39de48dbd989e9c266bda24bdd3b0d4242b548bfe1eda3'),
  ('en.sahih', 30, 9, 3418, 'Have they not traveled through the earth and observed how was the end of those before them? They were greater than them in power, and they plowed the earth and built it up more than they have built it up, and their messengers came to them with clear evidences. And Allah would not ever have wronged them, but they were wronging themselves.', NULL, NULL, '72b559a55a2d88e8efe38673494214b675ddcd3cf20de7b553022f0fea6d75d6'),
  ('en.sahih', 30, 10, 3419, 'Then the end of those who did evil was the worst [consequence] because they denied the signs of Allah and used to ridicule them.', NULL, NULL, 'd91fa408f38b4150e0be6a9d3e81b17dd7e5c867674bb9e5173ad6ea6def3db5'),
  ('en.sahih', 30, 11, 3420, 'Allah begins creation; then He will repeat it; then to Him you will be returned.', NULL, NULL, '183d3c93e35cd8b1862e616d17f883e296bc4dfa3990b82444e68e9ed24eabc8'),
  ('en.sahih', 30, 12, 3421, 'And the Day the Hour appears the criminals will be in despair.', NULL, NULL, 'cc557341bfc936ecef83014fb5cb9b38bfd44e1a0c68ffd5193e58d04867522d'),
  ('en.sahih', 30, 13, 3422, 'And there will not be for them among their [alleged] partners any intercessors, and they will [then] be disbelievers in their partners.', NULL, NULL, '16cd529ff6a3a7b891b55df2cc8c535b01d5b0cd31a86c9c3fdb94cfdf20a0a5'),
  ('en.sahih', 30, 14, 3423, 'And the Day the Hour appears - that Day they will become separated.', NULL, NULL, 'd07a8da0a5ad2c410d8ea644dd3670ae213fc2339146d54b8e576714b49db874'),
  ('en.sahih', 30, 15, 3424, 'And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted.', NULL, NULL, 'ae95fe4a1f1ccd1b9943c7e2b75655bd697814daabcacff051e576510b233554'),
  ('en.sahih', 30, 16, 3425, 'But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain].', NULL, NULL, 'f7275aa4b94a55697460d00e92d436a63737b2dd917438610b6efe993bf68df7'),
  ('en.sahih', 30, 17, 3426, 'So exalted is Allah when you reach the evening and when you reach the morning.', NULL, NULL, 'dbac709498a3f18c0ed3080a303dc1e2ae560ee4e4fd1ebb4eae52062a204187'),
  ('en.sahih', 30, 18, 3427, 'And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.', NULL, NULL, '6815af354841f4858d724725c8ac6d1d7d7f89e806dc3145b9fecf9464ba7a33'),
  ('en.sahih', 30, 19, 3428, 'He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out.', NULL, NULL, '64e76b0453a2743af4525b74eee7cf30145f1a98c4ce306916fdfe92e8cc98e4'),
  ('en.sahih', 30, 20, 3429, 'And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth].', NULL, NULL, '5b59d97da19888b3b0e241e8cc7ab39e8e87337f9a5e6a6c24a91ee64ea5091f'),
  ('en.sahih', 30, 21, 3430, 'And of His signs is that He created for you from yourselves mates that you may find tranquillity in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought.', NULL, NULL, 'f773f983cbaba472e2f19f20fc706275552cad5cc0774acd7ff9c8324fd85616'),
  ('en.sahih', 30, 22, 3431, 'And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge.', NULL, NULL, '3f5a2313bb8c206a3c1d49d4a6fdcacd8188a4367185e04c2a6a42abae793c3d'),
  ('en.sahih', 30, 23, 3432, 'And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen.', NULL, NULL, '3b2171325f7c566d0455df75b397aa39ac3272d8813d10ce278cb4b7e3ba98fd'),
  ('en.sahih', 30, 24, 3433, 'And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason.', NULL, NULL, 'b413845b314dd87edfa044a05ff301310dc717749bd5b78d5fa3c3b887e0d409'),
  ('en.sahih', 30, 25, 3434, 'And of His signs is that the heaven and earth remain by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth.', NULL, NULL, '89b4f5a93fc25990581ce4d3af0ffc4f007e8ff4fcccba20700b1d7a162839fa'),
  ('en.sahih', 30, 26, 3435, 'And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient.', NULL, NULL, 'cb3bc7ec8ead3f23285369fb1e6a4bc66fee918c0a136854faf8f857f8f06af1'),
  ('en.sahih', 30, 27, 3436, 'And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest attribute in the heavens and earth. And He is the Exalted in Might, the Wise.', NULL, NULL, 'ec767a456ed423753992ccb20edf67567063c4140c61454b4fb4ddd0bd381e9e'),
  ('en.sahih', 30, 28, 3437, 'He presents to you an example from yourselves. Do you have among those whom your right hands possess any partners in what We have provided for you so that you are equal therein [and] would fear them as your fear of one another [within a partnership]? Thus do We detail the verses for a people who use reason.', NULL, NULL, 'ab4d2ec7356d64af962f3b1ef81cf5cea64a5179249cf15bb7efc4b2490e9a4e'),
  ('en.sahih', 30, 29, 3438, 'But those who wrong follow their [own] desires without knowledge. Then who can guide one whom Allah has sent astray? And for them there are no helpers.', NULL, NULL, '267e967840cb54dff0ab1797372cb62b821ed6b1d732b10c5f00fe2bb87ce7f8'),
  ('en.sahih', 30, 30, 3439, 'So direct your face toward the religion, inclining to truth. [Adhere to] the fitrah of Allah upon which He has created [all] people. No change should there be in the creation of Allah. That is the correct religion, but most of the people do not know.', NULL, NULL, '3db7ceb4687d3c59bcdafa3589d63851c29ce27367670b998d9040da30a83805'),
  ('en.sahih', 30, 31, 3440, '[Adhere to it], turning in repentance to Him, and fear Him and establish prayer and do not be of those who associate others with Allah', NULL, NULL, '0130ea6a65e84ee3afa3ba7b79625ea5b67330b5667780b51fa3d9deac2ea35a'),
  ('en.sahih', 30, 32, 3441, '[Or] of those who have divided their religion and become sects, every faction rejoicing in what it has.', NULL, NULL, '0e6471564aa92045e1e75e46900f1b9b34a024f571ef0bba6b8053e5ce3b8d05'),
  ('en.sahih', 30, 33, 3442, 'And when adversity touches the people, they call upon their Lord, turning in repentance to Him. Then when He lets them taste mercy from Him, at once a party of them associate others with their Lord,', NULL, NULL, '57a27b30462d4cc533958be5d0f4b1566ab5588929caa9350a534160edb022a3'),
  ('en.sahih', 30, 34, 3443, 'So that they will deny what We have granted them. Then enjoy yourselves, for you are going to know.', NULL, NULL, '461e84a2d8caf3a7676ad320a17be781536b2c8f057f25d992031d89abafc3e2'),
  ('en.sahih', 30, 35, 3444, 'Or have We sent down to them an authority, and it speaks of what they were associating with Him?', NULL, NULL, '78b9db5985152a0cb1adc6c8963b0d69f0f97562519e508bfbfb992b28112cf9'),
  ('en.sahih', 30, 36, 3445, 'And when We let the people taste mercy, they rejoice therein, but if evil afflicts them for what their hands have put forth, immediately they despair.', NULL, NULL, '601a0c92b300a333d072f007ac9917ac57294173597e4756fbdf495cf1b9e208'),
  ('en.sahih', 30, 37, 3446, 'Do they not see that Allah extends provision for whom He wills and restricts [it]? Indeed, in that are signs for a people who believe.', NULL, NULL, '5e985d4be6db9592b543036324974c4533a935e56f76099b69bca713b1b681ea'),
  ('en.sahih', 30, 38, 3447, 'So give the relative his right, as well as the needy and the traveler. That is best for those who desire the countenance of Allah, and it is they who will be the successful.', NULL, NULL, '48a32d686093fa6973d8d198d2ce6c88ec978c7816bd9ab52a3cc15dc826d7f5'),
  ('en.sahih', 30, 39, 3448, 'And whatever you give for interest to increase within the wealth of people will not increase with Allah. But what you give in zakah, desiring the countenance of Allah - those are the multipliers.', NULL, NULL, '4b8ff52ab4279abb098573e3b653c284860ef9d0916a5c8032eadfc90f8f7a62'),
  ('en.sahih', 30, 40, 3449, 'Allah is the one who created you, then provided for you, then will cause you to die, and then will give you life. Are there any of your "partners" who does anything of that? Exalted is He and high above what they associate with Him.', NULL, NULL, 'e0fd5ce5e1c1b75976e147deb1b54546dcda30b8ac60053a300ba0b1385cc03b'),
  ('en.sahih', 30, 41, 3450, 'Corruption has appeared throughout the land and sea by [reason of] what the hands of people have earned so He may let them taste part of [the consequence of] what they have done that perhaps they will return [to righteousness].', NULL, NULL, '93b7c7530e35f1b1d913709b7ef812fb087ce9067bdca53d8a305e050227be26'),
  ('en.sahih', 30, 42, 3451, 'Say, [O Muhammad], "Travel through the land and observe how was the end of those before. Most of them were associators [of others with Allah].', NULL, NULL, 'a3b1b6a0c70f31e005cfb5820e5de0b8424acfffe152e6f735560f7a88e2ace0'),
  ('en.sahih', 30, 43, 3452, 'So direct your face toward the correct religion before a Day comes from Allah of which there is no repelling. That Day, they will be divided.', NULL, NULL, 'c367371a34cbfb78f32a29564b0726b11b3e18834c61916569540921d443d645'),
  ('en.sahih', 30, 44, 3453, 'Whoever disbelieves - upon him is [the consequence of] his disbelief. And whoever does righteousness - they are for themselves preparing,', NULL, NULL, '14a21806c30b34229e971530e714c138e68717b45421dff33590e23aa5e4b9b7'),
  ('en.sahih', 30, 45, 3454, 'That He may reward those who have believed and done righteous deeds out of His bounty. Indeed, He does not like the disbelievers.', NULL, NULL, '1cebdba4223450e5b5bc0881041d4fc3aa17dd02d57df1ad455b6cf07f68ffa5'),
  ('en.sahih', 30, 46, 3455, 'And of His signs is that He sends the winds as bringers of good tidings and to let you taste His mercy and so the ships may sail at His command and so you may seek of His bounty, and perhaps you will be grateful.', NULL, NULL, '795a707d6a2a2bb0409e9bada3dbd3f368ea917889178a9c179adc8f2f324b46'),
  ('en.sahih', 30, 47, 3456, 'And We have already sent messengers before you to their peoples, and they came to them with clear evidences; then We took retribution from those who committed crimes, and incumbent upon Us was support of the believers.', NULL, NULL, 'ff75c2254292cafb63b41215b75973beb71f82d2fccf6da358b315da4cff75de'),
  ('en.sahih', 30, 48, 3457, 'It is Allah who sends the winds, and they stir the clouds and spread them in the sky however He wills, and He makes them fragments so you see the rain emerge from within them. And when He causes it to fall upon whom He wills of His servants, immediately they rejoice', NULL, NULL, 'd849f896a65008e9cf5d41b70b5b2f99d64c65b2d12917292ef12142b1e03a83'),
  ('en.sahih', 30, 49, 3458, 'Although they were, before it was sent down upon them - before that, in despair.', NULL, NULL, 'a27f5d2b1e6da09402a35fdc651aeee3ec563b34bd569027c5988d54bce36eeb'),
  ('en.sahih', 30, 50, 3459, 'So observe the effects of the mercy of Allah - how He gives life to the earth after its lifelessness. Indeed, that [same one] will give life to the dead, and He is over all things competent.', NULL, NULL, 'a5f98b15ebca837e21629958dc608c452e9020e94e6fce100ccdca3566f33b3a'),
  ('en.sahih', 30, 51, 3460, 'But if We should send a [bad] wind and they saw [their crops] turned yellow, they would remain thereafter disbelievers.', NULL, NULL, '95b20a045560b34a07cb94c94958073eaa837d32c0b30d0c15fa222219f05a00'),
  ('en.sahih', 30, 52, 3461, 'So indeed, you will not make the dead hear, nor will you make the deaf hear the call when they turn their backs, retreating.', NULL, NULL, '6a1202d667e404d31bc670a2a10b60d674f556560b10c9f3e995925b97d74ff3'),
  ('en.sahih', 30, 53, 3462, 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [in submission to Allah].', NULL, NULL, '385e5c5d247afcc10de4bf5b6935bbca93be48dd2bd112d7e18f3f765eaf6561'),
  ('en.sahih', 30, 54, 3463, 'Allah is the one who created you from weakness, then made after weakness strength, then made after strength weakness and white hair. He creates what He wills, and He is the Knowing, the Competent.', NULL, NULL, '3f0202576ffa690d0adcfbb93ed543f4f281fee9d2ca36518cff2dac25eb3250'),
  ('en.sahih', 30, 55, 3464, 'And the Day the Hour appears the criminals will swear they had remained but an hour. Thus they were deluded.', NULL, NULL, '5087acedd056c31a315daa6598011695685ceb468d1d1321038f5d819f63ebba'),
  ('en.sahih', 30, 56, 3465, 'But those who were given knowledge and faith will say, "You remained the extent of Allah ''s decree until the Day of Resurrection, and this is the Day of Resurrection, but you did not used to know."', NULL, NULL, '793887d10706d3b255529aae80e8e7d52dbf2039ff3d05998d3d27129d8002a3'),
  ('en.sahih', 30, 57, 3466, 'So that Day, their excuse will not benefit those who wronged, nor will they be asked to appease [Allah].', NULL, NULL, '12851800cbf8f4e34e7c570bc8f0d78240953105faca6dc9dd7cd40f2580a306'),
  ('en.sahih', 30, 58, 3467, 'And We have certainly presented to the people in this Qur''an from every [kind of] example. But, [O Muhammad], if you should bring them a sign, the disbelievers will surely say, "You [believers] are but falsifiers."', NULL, NULL, '49e4b9908ba748ad6b963cb561fe0600b987ae1dd84b8c855005c72746491e69'),
  ('en.sahih', 30, 59, 3468, 'Thus does Allah seal the hearts of those who do not know.', NULL, NULL, '467dbf3b3880f30b393be6b8ec26780965cbb947b070601480f1f84c5a4586e3'),
  ('en.sahih', 30, 60, 3469, 'So be patient. Indeed, the promise of Allah is truth. And let them not disquiet you who are not certain [in faith].', NULL, NULL, '344e7ea1f56ad033321e718a8238b7aa60b40e7195b74ee3c1fb34c8891daf44'),
  ('en.sahih', 31, 1, 3470, 'Alif, Lam, Meem.', NULL, NULL, 'c0271a8d54e5b8ca6868a624b25c94d32c317177546d0577b0ceceac58956c78'),
  ('en.sahih', 31, 2, 3471, 'These are verses of the wise Book,', NULL, NULL, 'b2b1034f93d82b9ce056b0d6a4fb320872f68a70e978780f6952669523296eed'),
  ('en.sahih', 31, 3, 3472, 'As guidance and mercy for the doers of good', NULL, NULL, '03be5d44907206511072d0068b0c179bdedad97472163695b52c4df15b420ee8'),
  ('en.sahih', 31, 4, 3473, 'Who establish prayer and give zakah, and they, of the Hereafter, are certain [in faith].', NULL, NULL, '5a35ec52404062d8407b47e495cb8288920e9f0750f803bb0e528c002c7c4bbe'),
  ('en.sahih', 31, 5, 3474, 'Those are on [right] guidance from their Lord, and it is those who are the successful.', NULL, NULL, 'd8d0bbc324d104639ff6e67cbaf70aa85ec8736881ddc0b2b7b99942d07e5497'),
  ('en.sahih', 31, 6, 3475, 'And of the people is he who buys the amusement of speech to mislead [others] from the way of Allah without knowledge and who takes it in ridicule. Those will have a humiliating punishment.', NULL, NULL, '00e8f49a1efc6827ba48382cf440cc29d32e801a09244160e151220873e328d7'),
  ('en.sahih', 31, 7, 3476, 'And when our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment.', NULL, NULL, '0a290a1553161439a630dc0abb3e5d55d40cd159ef91e26428c79ef36af39066'),
  ('en.sahih', 31, 8, 3477, 'Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure.', NULL, NULL, 'b06444913fce5c55cc8e4473991d33ec00c2a26a95d8bafca14dd3ccddca2246'),
  ('en.sahih', 31, 9, 3478, 'Wherein they abide eternally; [it is] the promise of Allah [which is] truth. And He is the Exalted in Might, the Wise.', NULL, NULL, '6d46891ef587772e0a53d92b4228f707a1d3ec87f80710a8e64e8e299548ec92'),
  ('en.sahih', 31, 10, 3479, 'He created the heavens without pillars that you see and has cast into the earth firmly set mountains, lest it should shift with you, and dispersed therein from every creature. And We sent down rain from the sky and made grow therein [plants] of every noble kind.', NULL, NULL, '956bfa7781aef536b0bff4b5444358ed3fe377b6f9f694767365879d30ab4332'),
  ('en.sahih', 31, 11, 3480, 'This is the creation of Allah. So show Me what those other than Him have created. Rather, the wrongdoers are in clear error.', NULL, NULL, '8d83f3a7db5afcaaba6a62355e34b40f154dbb83cdcbcce81c2a6089c47b5d3b'),
  ('en.sahih', 31, 12, 3481, 'And We had certainly given Luqman wisdom [and said], "Be grateful to Allah." And whoever is grateful is grateful for [the benefit of] himself. And whoever denies [His favor] - then indeed, Allah is Free of need and Praiseworthy.', NULL, NULL, '1b8a852f2cab0a2d4aca9fcecfde4b060d25f695f47a0464859d2a5c3d4338d8'),
  ('en.sahih', 31, 13, 3482, 'And [mention, O Muhammad], when Luqman said to his son while he was instructing him, "O my son, do not associate [anything] with Allah. Indeed, association [with him] is great injustice."', NULL, NULL, '1ae54916dd92bb3e4b4aa527acd7dfc6840d481cc1d89372a8dd247b13db256a'),
  ('en.sahih', 31, 14, 3483, 'And We have enjoined upon man [care] for his parents. His mother carried him, [increasing her] in weakness upon weakness, and his weaning is in two years. Be grateful to Me and to your parents; to Me is the [final] destination.', NULL, NULL, 'c057c4ff73dfcfca0b7d3d800514da8af7498a06c88402d022c487271d1d7ee7'),
  ('en.sahih', 31, 15, 3484, 'But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them but accompany them in [this] world with appropriate kindness and follow the way of those who turn back to Me [in repentance]. Then to Me will be your return, and I will inform you about what you used to do.', NULL, NULL, '81fdeaf6dfa75b805bbb829873955a8132fd4cef22b91f40498454741f1f358c'),
  ('en.sahih', 31, 16, 3485, '[And Luqman said], "O my son, indeed if wrong should be the weight of a mustard seed and should be within a rock or [anywhere] in the heavens or in the earth, Allah will bring it forth. Indeed, Allah is Subtle and Acquainted.', NULL, NULL, 'b39610a858c1f9063e3e63654b366a94524813d9ce31082a8c16ada0de9e6af3'),
  ('en.sahih', 31, 17, 3486, 'O my son, establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you. Indeed, [all] that is of the matters [requiring] determination.', NULL, NULL, '74238eea04df827fe4f7e420211b02272613e15bcbaa417151f37b7cb4a061f6'),
  ('en.sahih', 31, 18, 3487, 'And do not turn your cheek [in contempt] toward people and do not walk through the earth exultantly. Indeed, Allah does not like everyone self-deluded and boastful.', NULL, NULL, '07ac6d46ed038b774b9a686922e6cca13c1dff8a6cfe35da73c69c62c8eb7f5d'),
  ('en.sahih', 31, 19, 3488, 'And be moderate in your pace and lower your voice; indeed, the most disagreeable of sounds is the voice of donkeys."', NULL, NULL, '8d737906eb0285f9df832c0eaf938441d15301dbb4194df9d31d25e3023849e5'),
  ('en.sahih', 31, 20, 3489, 'Do you not see that Allah has made subject to you whatever is in the heavens and whatever is in the earth and amply bestowed upon you His favors, [both] apparent and unapparent? But of the people is he who disputes about Allah without knowledge or guidance or an enlightening Book [from Him].', NULL, NULL, '8c5a8380cd76a3912ff84ae27015e09822f65e5065d45d07e7f6e862f68ce321'),
  ('en.sahih', 31, 21, 3490, 'And when it is said to them, "Follow what Allah has revealed," they say, "Rather, we will follow that upon which we found our fathers." Even if Satan was inviting them to the punishment of the Blaze?', NULL, NULL, '535dfbdd85812759f01fbf56e4d6d7dfef236d51773c43da44c0988b2ed96bc2'),
  ('en.sahih', 31, 22, 3491, 'And whoever submits his face to Allah while he is a doer of good - then he has grasped the most trustworthy handhold. And to Allah will be the outcome of [all] matters.', NULL, NULL, '924adb192475135723bdb91045bb88f97d5f7edecee7960447e3a5039014c2e8'),
  ('en.sahih', 31, 23, 3492, 'And whoever has disbelieved - let not his disbelief grieve you. To Us is their return, and We will inform them of what they did. Indeed, Allah is Knowing of that within the breasts.', NULL, NULL, '624ef2a24c5d84bc03db6beb1327e239e4d45b5dc3960638c0aee829b87f0b48'),
  ('en.sahih', 31, 24, 3493, 'We grant them enjoyment for a little; then We will force them to a massive punishment.', NULL, NULL, '867e3e876c031a63b62bff89b08978e7dda77cc98b7b9583c2dbaef85742714f'),
  ('en.sahih', 31, 25, 3494, 'And if you asked them, "Who created the heavens and earth?" they would surely say, "Allah." Say, "[All] praise is [due] to Allah "; but most of them do not know.', NULL, NULL, '3fad0fa9dcbc5f8df1572218725d00448f12c4a0091d74d11bf91969eb6b5186'),
  ('en.sahih', 31, 26, 3495, 'To Allah belongs whatever is in the heavens and earth. Indeed, Allah is the Free of need, the Praiseworthy.', NULL, NULL, '365f10420a48062b95d79bca658b412f4603c22c39fde1841a348e9098deda98'),
  ('en.sahih', 31, 27, 3496, 'And if whatever trees upon the earth were pens and the sea [was ink], replenished thereafter by seven [more] seas, the words of Allah would not be exhausted. Indeed, Allah is Exalted in Might and Wise.', NULL, NULL, '3111ed96edf81af91aebdee79b4e1b53961392fd75511a9cc5431e6236396d72'),
  ('en.sahih', 31, 28, 3497, 'Your creation and your resurrection will not be but as that of a single soul. Indeed, Allah is Hearing and Seeing.', NULL, NULL, 'e3aa131f24444817fffa1a996e7cdbb60a1cc947df8691a7364320865c9ea87c'),
  ('en.sahih', 31, 29, 3498, 'Do you not see that Allah causes the night to enter the day and causes the day to enter the night and has subjected the sun and the moon, each running [its course] for a specified term, and that Allah, with whatever you do, is Acquainted?', NULL, NULL, '354a3fa94d24910d9474b1c32b60a9e7b0f012277b7c36d32ca9c63d07de0a5b'),
  ('en.sahih', 31, 30, 3499, 'That is because Allah is the Truth, and that what they call upon other than Him is falsehood, and because Allah is the Most High, the Grand.', NULL, NULL, 'dbe1149d7d10ccbd918c8995b8846b1c249ac99500fdb2b8a07725f7154847d1'),
  ('en.sahih', 31, 31, 3500, 'Do you not see that ships sail through the sea by the favor of Allah that He may show you of His signs? Indeed in that are signs for everyone patient and grateful.', NULL, NULL, 'e3572421ebbc266f364580e087f07155c1535f3bcdfd94e9825d1eee489f8de2')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 31, 32, 3501, 'And when waves come over them like canopies, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, there are [some] of them who are moderate [in faith]. And none rejects Our signs except everyone treacherous and ungrateful.', NULL, NULL, '940df028a3562f322c04211ca512d965563959825572212d3f6c41ee778379d8'),
  ('en.sahih', 31, 33, 3502, 'O mankind, fear your Lord and fear a Day when no father will avail his son, nor will a son avail his father at all. Indeed, the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.', NULL, NULL, '17666fa7caac89aa4e28a8fd41d65b4e4484de7f2237ed5cea3dcb6c29ddd1f4'),
  ('en.sahih', 31, 34, 3503, 'Indeed, Allah [alone] has knowledge of the Hour and sends down the rain and knows what is in the wombs. And no soul perceives what it will earn tomorrow, and no soul perceives in what land it will die. Indeed, Allah is Knowing and Acquainted.', NULL, NULL, 'bf9ee29c9290064901507b2a8765c0fb9caa73ccadc2d5fd7f7f67ee156f5649'),
  ('en.sahih', 32, 1, 3504, 'Alif, Lam, Meem.', NULL, NULL, 'c0271a8d54e5b8ca6868a624b25c94d32c317177546d0577b0ceceac58956c78'),
  ('en.sahih', 32, 2, 3505, '[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds.', NULL, NULL, '8be9737ebdc3408ee9ee471b25458a9071f240dfa74d8bdb243939b0b77ce598'),
  ('en.sahih', 32, 3, 3506, 'Or do they say, "He invented it"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided.', NULL, NULL, '2f639bd9669f49b71d82cc30b60d04ba2c0dd24a20fddc6e71b8ef6a635b85d3'),
  ('en.sahih', 32, 4, 3507, 'It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?', NULL, NULL, 'bbf2bb3f6b0133a054540486bec1d02937ca5eb136e76d3f9c5f9f8902fa4816'),
  ('en.sahih', 32, 5, 3508, 'He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count.', NULL, NULL, 'fe5110a76699dcc9917882faf3555c70ae4079657d5d5134d61b51858aba34af'),
  ('en.sahih', 32, 6, 3509, 'That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,', NULL, NULL, 'fc167e1230cdf3458a074c18a17412f6edf944a3a5ac2f598adfeee5152c5d31'),
  ('en.sahih', 32, 7, 3510, 'Who perfected everything which He created and began the creation of man from clay.', NULL, NULL, 'adb410abe912c85e8165491def5c2deb17557fc489c9eb668ed91f7f755e408c'),
  ('en.sahih', 32, 8, 3511, 'Then He made his posterity out of the extract of a liquid disdained.', NULL, NULL, '4f07e79e5780dbe62a36626547aecbc1abfb85f6db7ba488534cf046acdd2834'),
  ('en.sahih', 32, 9, 3512, 'Then He proportioned him and breathed into him from His [created] soul and made for you hearing and vision and hearts; little are you grateful.', NULL, NULL, '864ebd23fcb2ed4d380f581db2750c5db0d337d58f033e7da83d18d66b8dca92'),
  ('en.sahih', 32, 10, 3513, 'And they say, "When we are lost within the earth, will we indeed be [recreated] in a new creation?" Rather, they are, in [the matter of] the meeting with their Lord, disbelievers.', NULL, NULL, '34ba07d3cf36e684509d5632b9dbf2e326a4df895702a55bb6cfe9bf1bcb0b68'),
  ('en.sahih', 32, 11, 3514, 'Say, "The angel of death will take you who has been entrusted with you. Then to your Lord you will be returned."', NULL, NULL, '90c410b6fd38a0eb2d62c6b81d2f93704e873977af8fd7cf932f300eefbe522b'),
  ('en.sahih', 32, 12, 3515, 'If you could but see when the criminals are hanging their heads before their Lord, [saying], "Our Lord, we have seen and heard, so return us [to the world]; we will work righteousness. Indeed, we are [now] certain."', NULL, NULL, '2bf5edb15fa9375775dd3652bb306b0c52786f8e9c1d06269964641fad19a3da'),
  ('en.sahih', 32, 13, 3516, 'And if We had willed, We could have given every soul its guidance, but the word from Me will come into effect [that] "I will surely fill Hell with jinn and people all together.', NULL, NULL, '782621bd27309e022dc174f2e75c464ec15c710a6f56e4101f34ace296c9a7f1'),
  ('en.sahih', 32, 14, 3517, 'So taste [punishment] because you forgot the meeting of this, your Day; indeed, We have [accordingly] forgotten you. And taste the punishment of eternity for what you used to do."', NULL, NULL, '89063fcdc51c7157c71471ac97154f878c24c3141cb0a80e72574e76cb1cd573'),
  ('en.sahih', 32, 15, 3518, 'Only those believe in Our verses who, when they are reminded by them, fall down in prostration and exalt [Allah] with praise of their Lord, and they are not arrogant.', NULL, NULL, '53da3c1b6e9e33b7182e33845905eef4fa260cb5018b7cc8fc1580b11134a91a'),
  ('en.sahih', 32, 16, 3519, 'They arise from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend.', NULL, NULL, 'e18d4d4e213bc78f9bee0a73abbdc39f997535dace9782eeeb3ce0184beb41eb'),
  ('en.sahih', 32, 17, 3520, 'And no soul knows what has been hidden for them of comfort for eyes as reward for what they used to do.', NULL, NULL, '0911c8661a76ff25cee705cadf05938509e51dc41f0f99e2ae70870c2cf92cbf'),
  ('en.sahih', 32, 18, 3521, 'Then is one who was a believer like one who was defiantly disobedient? They are not equal.', NULL, NULL, 'fc169008bb49e028372bc6f0dcf9f903d355c4f9296affafb0494b6d2d08552d'),
  ('en.sahih', 32, 19, 3522, 'As for those who believed and did righteous deeds, for them will be the Gardens of Refuge as accommodation for what they used to do.', NULL, NULL, 'f383a561e6bacabe1a9a39448bde6182c3552a812b27eda54e119138060bba21'),
  ('en.sahih', 32, 20, 3523, 'But as for those who defiantly disobeyed, their refuge is the Fire. Every time they wish to emerge from it, they will be returned to it while it is said to them, "Taste the punishment of the Fire which you used to deny."', NULL, NULL, 'b0210e9c85a9370aba031bdaaa2b310576340b2bdf8818fad3b3be918135dad8'),
  ('en.sahih', 32, 21, 3524, 'And we will surely let them taste the nearer punishment short of the greater punishment that perhaps they will repent.', NULL, NULL, '60303043177a6c4e58c4b366b3e6d507e74e17ddb59c7041bb32d60db791cb0d'),
  ('en.sahih', 32, 22, 3525, 'And who is more unjust than one who is reminded of the verses of his Lord; then he turns away from them? Indeed We, from the criminals, will take retribution.', NULL, NULL, '7f5eada092439a73bcf65e7a2806f4845dbdf81a08a00eb3f356a820f04755b1'),
  ('en.sahih', 32, 23, 3526, 'And We certainly gave Moses the Scripture, so do not be in doubt over his meeting. And we made the Torah guidance for the Children of Israel.', NULL, NULL, '22b31d431f7a2603a048794c1a266e8a7a66deeeb71a7eeacc450768fd3f3a73'),
  ('en.sahih', 32, 24, 3527, 'And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs.', NULL, NULL, '2102d4373afcbac26d78008377233b5ac97b14a183a5c3f7577c23a7360dcc5b'),
  ('en.sahih', 32, 25, 3528, 'Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', NULL, NULL, '6061dee57f4bbda6b3f44d0250998ee4a1eb3199bfb229b3b302de5ad66122dd'),
  ('en.sahih', 32, 26, 3529, 'Has it not become clear to them how many generations We destroyed before them, [as] they walk among their dwellings? Indeed in that are signs; then do they not hear?', NULL, NULL, '61f98901257efcfc868fcb0ceed8b8e45c5e678d4ffa65e4b9c276920b7f9790'),
  ('en.sahih', 32, 27, 3530, 'Have they not seen that We drive the water [in clouds] to barren land and bring forth thereby crops from which their livestock eat and [they] themselves? Then do they not see?', NULL, NULL, '69468c4b36010a358bb86d8f5fa3fe282171803f3e8a89343728c7aa7b7193f6'),
  ('en.sahih', 32, 28, 3531, 'And they say, "When will be this conquest, if you should be truthful?"', NULL, NULL, '50a02a5638f93efd2613287e2f1eb96572b94513331de57a061e82405e6a855b'),
  ('en.sahih', 32, 29, 3532, 'Say, [O Muhammad], "On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved."', NULL, NULL, 'b970622a87a996c83569932313ac96554528f1adbe14257d0158f6a4c06f6438'),
  ('en.sahih', 32, 30, 3533, 'So turn away from them and wait. Indeed, they are waiting.', NULL, NULL, '72ff14748350c210f6f933844fe5c680d765e7323545d9d7c14339973edf486c'),
  ('en.sahih', 33, 1, 3534, 'O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, '7f24c0b447578b1ce5ce4a92f94d305dded16b1d9956f109c1196565cff9e803'),
  ('en.sahih', 33, 2, 3535, 'And follow that which is revealed to you from your Lord. Indeed Allah is ever, with what you do, Acquainted.', NULL, NULL, '2fd742329d866f65dde1633121ee535e3fdf92013b97acc0324d86c7e4428316'),
  ('en.sahih', 33, 3, 3536, 'And rely upon Allah; and sufficient is Allah as Disposer of affairs.', NULL, NULL, '746867ce61eaae70129c22eeee682af3d007b3b173ed582c7cb0e478f22acf31'),
  ('en.sahih', 33, 4, 3537, 'Allah has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And he has not made your adopted sons your [true] sons. That is [merely] your saying by your mouths, but Allah says the truth, and He guides to the [right] way.', NULL, NULL, '4f4e4b4e9aa75385a1cedeaa8a11082a61dd5d00d9ffaca629863d2eb63cc2d2'),
  ('en.sahih', 33, 5, 3538, 'Call them by [the names of] their fathers; it is more just in the sight of Allah. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allah Forgiving and Merciful.', NULL, NULL, '8e7265fd67c6981e92c42b3687066be52e90a23c451f8fff5dd921b853856b14'),
  ('en.sahih', 33, 6, 3539, 'The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allah than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed.', NULL, NULL, '71780a1bfa563c269dcde29d3e7a853ab1f1c4ce94b0c91087b740653fd6744f'),
  ('en.sahih', 33, 7, 3540, 'And [mention, O Muhammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant.', NULL, NULL, 'b22ffa6c7e3cacef898f52ca7374896b15189300b4496eeab980c61017d8d6f3'),
  ('en.sahih', 33, 8, 3541, 'That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment.', NULL, NULL, '58cc2537717780cabf8b20a749f7681b6b4ee02b88c379dd7d484ac047580883'),
  ('en.sahih', 33, 9, 3542, 'O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing.', NULL, NULL, 'fc84a406af8d2fdb0bc8d9eef7a33abd4d8e40ce0305f12811ce7b77276e92b4'),
  ('en.sahih', 33, 10, 3543, '[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions.', NULL, NULL, 'f6e0818394ffb01d394ea88fec25aa065f9822ce642d2d3037b21ebbb85db723'),
  ('en.sahih', 33, 11, 3544, 'There the believers were tested and shaken with a severe shaking.', NULL, NULL, '7565d218d77af81e789248091d910e13c7b41daaa5e2fc2de8c64d6f34db2605'),
  ('en.sahih', 33, 12, 3545, 'And [remember] when the hypocrites and those in whose hearts is disease said, "Allah and His Messenger did not promise us except delusion,"', NULL, NULL, 'df659bd4e80ddb83a6540d8af8d5937c3378fcb7e5011ab8a33bd3c1febba7f5'),
  ('en.sahih', 33, 13, 3546, 'And when a faction of them said, "O people of Yathrib, there is no stability for you [here], so return [home]." And a party of them asked permission of the Prophet, saying, "Indeed, our houses are unprotected," while they were not exposed. They did not intend except to flee.', NULL, NULL, 'e81919b7e6db5b50d1eaecdd30322543e43b973b5482fc08e23fa39a277d64ca'),
  ('en.sahih', 33, 14, 3547, 'And if they had been entered upon from all its [surrounding] regions and fitnah had been demanded of them, they would have done it and not hesitated over it except briefly.', NULL, NULL, 'ecf5464677699e4a33b57e0ee3531fd13fda7842057316247dad4b7f44c3d2b2'),
  ('en.sahih', 33, 15, 3548, 'And they had already promised Allah before not to turn their backs and flee. And ever is the promise to Allah [that about which one will be] questioned.', NULL, NULL, '6166e64e164e9eb669b507aef0a45dcb00c71d071c152171978f43805bc37975'),
  ('en.sahih', 33, 16, 3549, 'Say, [O Muhammad], "Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little."', NULL, NULL, '010621280f29d32b8d5cc3e480de9537c20ad5c16ab92717844add8f0a3b0686'),
  ('en.sahih', 33, 17, 3550, 'Say, "Who is it that can protect you from Allah if He intends for you an ill or intends for you a mercy?" And they will not find for themselves besides Allah any protector or any helper.', NULL, NULL, '7434d277bd417df8aeeb7d64833ea23987b0f5507fe3f1d00bcbd5f956f5ac43'),
  ('en.sahih', 33, 18, 3551, 'Already Allah knows the hinderers among you and those [hypocrites] who say to their brothers, "Come to us," and do not go to battle, except for a few,', NULL, NULL, 'cbc69b4b0262a61064212e218f38790bfc59b2d53f426dc81ccb01a4342846f1'),
  ('en.sahih', 33, 19, 3552, 'Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allah has rendered their deeds worthless, and ever is that, for Allah, easy.', NULL, NULL, '9d64c858dfc52988d201324e7ccb23db29a3d8140f3ca165013b6b529e545906'),
  ('en.sahih', 33, 20, 3553, 'They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little.', NULL, NULL, '134f4d622cde43aa8d5dd61c24cc5d50a290724d1d25437869f2d696f358b0d5'),
  ('en.sahih', 33, 21, 3554, 'There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often.', NULL, NULL, '0bca74ad3e9c556954f0a663a8e5e6f80b17460745b4c3271e7e7c7204fb29a1'),
  ('en.sahih', 33, 22, 3555, 'And when the believers saw the companies, they said, "This is what Allah and His Messenger had promised us, and Allah and His Messenger spoke the truth." And it increased them only in faith and acceptance.', NULL, NULL, 'b8d52657d0020893c66dc4fab9ae59c43fb0b6a86b418950a93e923290e46b6f'),
  ('en.sahih', 33, 23, 3556, 'Among the believers are men true to what they promised Allah. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -', NULL, NULL, '41429460c1b2a894d381327f619aa495bcccac202e45efc0225239d0faf7e638'),
  ('en.sahih', 33, 24, 3557, 'That Allah may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allah is ever Forgiving and Merciful.', NULL, NULL, '1847ef2440e313b0a3c564eeafbbf4fa1500e26e02a1f357819d2b0ac10819be'),
  ('en.sahih', 33, 25, 3558, 'And Allah repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allah for the believers in battle, and ever is Allah Powerful and Exalted in Might.', NULL, NULL, '022dce1ef5104dac299253059838149ee1ddb7b2f89122e2131e2e74a7f0d9df'),
  ('en.sahih', 33, 26, 3559, 'And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party you killed, and you took captive a party.', NULL, NULL, '2e7caeeca381ae39b6799d5a229acfa2a85f6bf485419ecd5b37fe21d31edd11'),
  ('en.sahih', 33, 27, 3560, 'And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allah, over all things, competent.', NULL, NULL, 'd30e53a118c3c4f527d822e15e2002e7cb7e6de945a801ab45ae1341dbc93ae6'),
  ('en.sahih', 33, 28, 3561, 'O Prophet, say to your wives, "If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release.', NULL, NULL, '28d92ff1de361c2f5c0f5b6935250f64d3c4eaed6adf1a0bed8ec817dfd8fea9'),
  ('en.sahih', 33, 29, 3562, 'But if you should desire Allah and His Messenger and the home of the Hereafter - then indeed, Allah has prepared for the doers of good among you a great reward."', NULL, NULL, '534923ed199dc8dde478f0e0424a7ac3ef910f697ee314b1fb771114006b41ec'),
  ('en.sahih', 33, 30, 3563, 'O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allah, easy.', NULL, NULL, 'b026fa467a23bd4ef701afddeb266fa8123714faf970f1771af395aeee35de98'),
  ('en.sahih', 33, 31, 3564, 'And whoever of you devoutly obeys Allah and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision.', NULL, NULL, 'ec9222514ed867a3d721d52b2a8adb0ea58825d61ce2b0ed4ecc2ef13fef4798'),
  ('en.sahih', 33, 32, 3565, 'O wives of the Prophet, you are not like anyone among women. If you fear Allah, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech.', NULL, NULL, '18b31b724a9c4b053ca6c81ad38d56df95b8cd903d2303213a84129af0565163'),
  ('en.sahih', 33, 33, 3566, 'And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakah and obey Allah and His Messenger. Allah intends only to remove from you the impurity [of sin], O people of the [Prophet''s] household, and to purify you with [extensive] purification.', NULL, NULL, '972e99263d2660b73eb356e4f0a6756b10b5aea7b04931a94c68c246979f5f6a'),
  ('en.sahih', 33, 34, 3567, 'And remember what is recited in your houses of the verses of Allah and wisdom. Indeed, Allah is ever Subtle and Acquainted [with all things].', NULL, NULL, '0db0005af94b3809712d21bca5b7ef5aa40c08cdaeae38cd388be90311ee5505'),
  ('en.sahih', 33, 35, 3568, 'Indeed, the Muslim men and Muslim women, the believing men and believing women, the obedient men and obedient women, the truthful men and truthful women, the patient men and patient women, the humble men and humble women, the charitable men and charitable women, the fasting men and fasting women, the men who guard their private parts and the women who do so, and the men who remember Allah often and the women who do so - for them Allah has prepared forgiveness and a great reward.', NULL, NULL, '06b35ba8ea17b940b92431e6134cb497035b228a3a75dacad015f16d5f7ef891'),
  ('en.sahih', 33, 36, 3569, 'It is not for a believing man or a believing woman, when Allah and His Messenger have decided a matter, that they should [thereafter] have any choice about their affair. And whoever disobeys Allah and His Messenger has certainly strayed into clear error.', NULL, NULL, '4bffe9faf3b313eb96d04e3b1fb3a9cc73cd27f3fde07424827ecb2ba3742568'),
  ('en.sahih', 33, 37, 3570, 'And [remember, O Muhammad], when you said to the one on whom Allah bestowed favor and you bestowed favor, "Keep your wife and fear Allah," while you concealed within yourself that which Allah is to disclose. And you feared the people, while Allah has more right that you fear Him. So when Zayd had no longer any need for her, We married her to you in order that there not be upon the believers any discomfort concerning the wives of their adopted sons when they no longer have need of them. And ever is the command of Allah accomplished.', NULL, NULL, 'b56ddba5acc0f3b2fc8946388ee224b193b98e0c5d20c2705cbcce0defe00b34'),
  ('en.sahih', 33, 38, 3571, 'There is not to be upon the Prophet any discomfort concerning that which Allah has imposed upon him. [This is] the established way of Allah with those [prophets] who have passed on before. And ever is the command of Allah a destiny decreed.', NULL, NULL, '8f126b70f1f7e987155085ab53ab00564676be5bf805725b196be8e6462ac33a'),
  ('en.sahih', 33, 39, 3572, '[Allah praises] those who convey the messages of Allah and fear Him and do not fear anyone but Allah. And sufficient is Allah as Accountant.', NULL, NULL, '6f4a4cb1bba17f17e91b91046268863b59f88b1c0c2084a88e113d1650fb70b0'),
  ('en.sahih', 33, 40, 3573, 'Muhammad is not the father of [any] one of your men, but [he is] the Messenger of Allah and last of the prophets. And ever is Allah, of all things, Knowing.', NULL, NULL, '10a472685ca4aa18cd899cfe075b232f5900d9fa7278d448fd73d9f5f9dc1f3d'),
  ('en.sahih', 33, 41, 3574, 'O you who have believed, remember Allah with much remembrance', NULL, NULL, '113d27939e554627e53e691b840e788cb1efa9f442b0a281c8eb15b4d413f281'),
  ('en.sahih', 33, 42, 3575, 'And exalt Him morning and afternoon.', NULL, NULL, '74d30d65027a17ab575107cf8fc5f2bf526cacdf998656818b980dcac7506665'),
  ('en.sahih', 33, 43, 3576, 'It is He who confers blessing upon you, and His angels [ask Him to do so] that He may bring you out from darknesses into the light. And ever is He, to the believers, Merciful.', NULL, NULL, '5fc29b99885f692bc2affb2c46c739316a690945b0710eafdacd7b6b2d6219e6'),
  ('en.sahih', 33, 44, 3577, 'Their greeting the Day they meet Him will be, "Peace." And He has prepared for them a noble reward.', NULL, NULL, '58ac099ff5fb45a9d3d69afbc3bed1540e6033f5fa0d76b394c37f0b15b98fbd'),
  ('en.sahih', 33, 45, 3578, 'O Prophet, indeed We have sent you as a witness and a bringer of good tidings and a warner.', NULL, NULL, '2c603bc866fa7825eabf10b0638b3096865ee7edfbdb56c98f214d0bc30cca8a'),
  ('en.sahih', 33, 46, 3579, 'And one who invites to Allah, by His permission, and an illuminating lamp.', NULL, NULL, 'a653ae4ac2866637515d129bbd3cda260eea3acee7cfbad8b199776c9e27cfee'),
  ('en.sahih', 33, 47, 3580, 'And give good tidings to the believers that they will have from Allah great bounty.', NULL, NULL, '4b62efe27d3c662f9e792adb324a29f07c85933450e4c9e13c5e9ba6517fcc99'),
  ('en.sahih', 33, 48, 3581, 'And do not obey the disbelievers and the hypocrites but do not harm them, and rely upon Allah. And sufficient is Allah as Disposer of affairs.', NULL, NULL, '142a08b9e8c362bd92b89c3544df3816d5a0da7c1d87a6aa966cf81d145ccb39'),
  ('en.sahih', 33, 49, 3582, 'O You who have believed, when you marry believing women and then divorce them before you have touched them, then there is not for you any waiting period to count concerning them. So provide for them and give them a gracious release.', NULL, NULL, '8e55b42470da27d715771715acf943b516c51bb1e507fa03d8f07f8e06584066'),
  ('en.sahih', 33, 50, 3583, 'O Prophet, indeed We have made lawful to you your wives to whom you have given their due compensation and those your right hand possesses from what Allah has returned to you [of captives] and the daughters of your paternal uncles and the daughters of your paternal aunts and the daughters of your maternal uncles and the daughters of your maternal aunts who emigrated with you and a believing woman if she gives herself to the Prophet [and] if the Prophet wishes to marry her, [this is] only for you, excluding the [other] believers. We certainly know what We have made obligatory upon them concerning their wives and those their right hands possess, [but this is for you] in order that there will be upon you no discomfort. And ever is Allah Forgiving and Merciful.', NULL, NULL, 'f67154deaf22072a1c3f1ba580160b1eef03f6d49b7d1838ca9a4859cf0aeac4'),
  ('en.sahih', 33, 51, 3584, 'You, [O Muhammad], may put aside whom you will of them or take to yourself whom you will. And any that you desire of those [wives] from whom you had [temporarily] separated - there is no blame upon you [in returning her]. That is more suitable that they should be content and not grieve and that they should be satisfied with what you have given them - all of them. And Allah knows what is in your hearts. And ever is Allah Knowing and Forbearing.', NULL, NULL, 'fcc098e3493a524de7077bb0e212a4923636637227430f3c4e76f924a769be50'),
  ('en.sahih', 33, 52, 3585, 'Not lawful to you, [O Muhammad], are [any additional] women after [this], nor [is it] for you to exchange them for [other] wives, even if their beauty were to please you, except what your right hand possesses. And ever is Allah, over all things, an Observer.', NULL, NULL, 'a9056dbb7f6df05ed2eccffbad1dd0c7299c388ea422b676ef2bc56119ac9ff1'),
  ('en.sahih', 33, 53, 3586, 'O you who have believed, do not enter the houses of the Prophet except when you are permitted for a meal, without awaiting its readiness. But when you are invited, then enter; and when you have eaten, disperse without seeking to remain for conversation. Indeed, that [behavior] was troubling the Prophet, and he is shy of [dismissing] you. But Allah is not shy of the truth. And when you ask [his wives] for something, ask them from behind a partition. That is purer for your hearts and their hearts. And it is not [conceivable or lawful] for you to harm the Messenger of Allah or to marry his wives after him, ever. Indeed, that would be in the sight of Allah an enormity.', NULL, NULL, '6bdbe0fc30cd76a9aeb4420137ba7bc48102aa406af37b620fff0fe7a917ac6d'),
  ('en.sahih', 33, 54, 3587, 'Whether you reveal a thing or conceal it, indeed Allah is ever, of all things, Knowing.', NULL, NULL, 'cebd12d3264824fd5a3cf2bcf4ed88f199f74301d6871096de7b9e16ceb31681'),
  ('en.sahih', 33, 55, 3588, 'There is no blame upon women concerning their fathers or their sons or their brothers or their brothers'' sons or their sisters'' sons or their women or those their right hands possess. And fear Allah. Indeed Allah is ever, over all things, Witness.', NULL, NULL, 'f6f03ea2882e79bedded2af02e8ce50364a68c10149928a95d06bbdcfaf23f0b'),
  ('en.sahih', 33, 56, 3589, 'Indeed, Allah confers blessing upon the Prophet, and His angels [ask Him to do so]. O you who have believed, ask [Allah to confer] blessing upon him and ask [Allah to grant him] peace.', NULL, NULL, '1f3ac33941ff11bdef03b4477be5f446f9dd50fc1e94b57c5282baf8ac2151ad'),
  ('en.sahih', 33, 57, 3590, 'Indeed, those who abuse Allah and His Messenger - Allah has cursed them in this world and the Hereafter and prepared for them a humiliating punishment.', NULL, NULL, '48e8a6cafb1c77547d77ae5b1639ff1baeb29397e03bbcd7655b8a9c39d42e13'),
  ('en.sahih', 33, 58, 3591, 'And those who harm believing men and believing women for [something] other than what they have earned have certainly born upon themselves a slander and manifest sin.', NULL, NULL, '331c012e3c452e3c8781468d768dfe3adedbeb6d495cdd12564f3c013a6ae91b'),
  ('en.sahih', 33, 59, 3592, 'O Prophet, tell your wives and your daughters and the women of the believers to bring down over themselves [part] of their outer garments. That is more suitable that they will be known and not be abused. And ever is Allah Forgiving and Merciful.', NULL, NULL, 'd694c590e8ad16a651e064a9b27de0dc4cb48d3ccb649cb421fcdde61e586d10'),
  ('en.sahih', 33, 60, 3593, 'If the hypocrites and those in whose hearts is disease and those who spread rumors in al-Madinah do not cease, We will surely incite you against them; then they will not remain your neighbors therein except for a little.', NULL, NULL, '9761ef8693e8dabf7bb7f968e6a549c1ab6f63faad7b66a4cb0f18b35b883f82'),
  ('en.sahih', 33, 61, 3594, 'Accursed wherever they are found, [being] seized and massacred completely.', NULL, NULL, 'bd056de179bef352fb2f2159a94f453dc41269e613a6d8634ff2da417836df1d'),
  ('en.sahih', 33, 62, 3595, '[This is] the established way of Allah with those who passed on before; and you will not find in the way of Allah any change.', NULL, NULL, '37e5ec3d07af584b7d85f0c91ea57c43f0e394bfb71aba35bc5c78d0fc7e7ef8'),
  ('en.sahih', 33, 63, 3596, 'People ask you concerning the Hour. Say," Knowledge of it is only with Allah. And what may make you perceive? Perhaps the Hour is near."', NULL, NULL, '44dec0bfd89289bf74f8366ea0ea35201d65bcf1d90f9fd3d6f91775f75fdc71'),
  ('en.sahih', 33, 64, 3597, 'Indeed, Allah has cursed the disbelievers and prepared for them a Blaze.', NULL, NULL, '7513dcdf930cefac0c94ef5de6b9f6bf142de3a783a3a2d7ffbe326de108db72'),
  ('en.sahih', 33, 65, 3598, 'Abiding therein forever, they will not find a protector or a helper.', NULL, NULL, '54092e1da6b869580c03f0621b70fd66ac647c48dd07ea2f1a5e6f327d7d092d'),
  ('en.sahih', 33, 66, 3599, 'The Day their faces will be turned about in the Fire, they will say, "How we wish we had obeyed Allah and obeyed the Messenger."', NULL, NULL, '364a20ef930a84eb4e2f2793b6c185189e9dd202a364ff927c3dd01853f0f806'),
  ('en.sahih', 33, 67, 3600, 'And they will say, "Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way.', NULL, NULL, '3c34595a79d456183499840fa808ea8296fcb47d4fabae63b55a4f175c0695d0')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 33, 68, 3601, 'Our Lord, give them double the punishment and curse them with a great curse."', NULL, NULL, '6d16d19abecfc44ca59fff851512e692ddfaa6a045630bea6c2c8e5b071085c5'),
  ('en.sahih', 33, 69, 3602, 'O you who have believed, be not like those who abused Moses; then Allah cleared him of what they said. And he, in the sight of Allah, was distinguished.', NULL, NULL, 'fd936487645d893d5cfcfb2f68fc2e8ac67a3d06d093c305de7ed6d97031c761'),
  ('en.sahih', 33, 70, 3603, 'O you who have believed, fear Allah and speak words of appropriate justice.', NULL, NULL, 'ca257774a245cacad25b943ac5fecbd323937311905ceed1b488513e1c390142'),
  ('en.sahih', 33, 71, 3604, 'He will [then] amend for you your deeds and forgive you your sins. And whoever obeys Allah and His Messenger has certainly attained a great attainment.', NULL, NULL, 'ca9eb36ed4f94405443fe392db0ed2d08fbbbed62618871f110e950ff58a6001'),
  ('en.sahih', 33, 72, 3605, 'Indeed, we offered the Trust to the heavens and the earth and the mountains, and they declined to bear it and feared it; but man [undertook to] bear it. Indeed, he was unjust and ignorant.', NULL, NULL, '6d118dff2f33b24641a970cb6578d981398520060ab9be1f0c190e7de10c3529'),
  ('en.sahih', 33, 73, 3606, '[It was] so that Allah may punish the hypocrite men and hypocrite women and the men and women who associate others with Him and that Allah may accept repentance from the believing men and believing women. And ever is Allah Forgiving and Merciful.', NULL, NULL, '4cc2f218df53d215239174c9a377fa3dce48261a442c30cccd8e425d36b642b1'),
  ('en.sahih', 34, 1, 3607, '[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Acquainted.', NULL, NULL, '293409adc21f2f6fb10e7435f6b8112e280dbe079fea0f335ec0023f1ce0242f'),
  ('en.sahih', 34, 2, 3608, 'He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving.', NULL, NULL, 'c47dda6bb30ec831502567ad976366f25e3e20589ba653e573a68aa688cbe486'),
  ('en.sahih', 34, 3, 3609, 'But those who disbelieve say, "The Hour will not come to us." Say, "Yes, by my Lord, it will surely come to you. [Allah is] the Knower of the unseen." Not absent from Him is an atom''s weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -', NULL, NULL, '9b54089362f63c784c0799bf00f9a1345304044c0d92f60aed0f9cd09f417e7f'),
  ('en.sahih', 34, 4, 3610, 'That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.', NULL, NULL, 'bd82eea5635c7962bfd32bacb56d25ff29118967bdde87fe5cda19938b8295fb'),
  ('en.sahih', 34, 5, 3611, 'But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature.', NULL, NULL, 'c72af426de3f95c7fc8445c6847b944ffd81aa61d25ae02742cfa3fe6309e6bb'),
  ('en.sahih', 34, 6, 3612, 'And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy.', NULL, NULL, '2cbe241862769e0a92908444c9d7031138940ca541c400837a88774bcfaaba47'),
  ('en.sahih', 34, 7, 3613, 'But those who disbelieve say, "Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?', NULL, NULL, 'dffb98ae34a60c5358460d8ba3a2c7d99ebe13a9da24571ad9cca49ba29ea32e'),
  ('en.sahih', 34, 8, 3614, 'Has he invented about Allah a lie or is there in him madness?" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error.', NULL, NULL, '75d38ec9b24c19c5d9a44ea72a1d5e0ec790e2df8f60d3b57724ccc540b3d15e'),
  ('en.sahih', 34, 9, 3615, 'Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allah].', NULL, NULL, '9ff0ed087fac5473272575a09328288a35b49f2011367c04efcb8e79ca47c3b7'),
  ('en.sahih', 34, 10, 3616, 'And We certainly gave David from Us bounty. [We said], "O mountains, repeat [Our] praises with him, and the birds [as well]." And We made pliable for him iron,', NULL, NULL, '60424d5d2b1157edeb852123a8fd92a3262b3a82494b10fc3182a772bee5789d'),
  ('en.sahih', 34, 11, 3617, '[Commanding him], "Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing."', NULL, NULL, '944f74390731dcf73a1c1f7089151fe20d9122b611f3d5e8f0c67746130eb9cc'),
  ('en.sahih', 34, 12, 3618, 'And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze.', NULL, NULL, 'c97e744113ad0c5d9ebd8dedb6c277e0fe543e21b937312c061b45a9e32e4724'),
  ('en.sahih', 34, 13, 3619, 'They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], "Work, O family of David, in gratitude." And few of My servants are grateful.', NULL, NULL, 'b5d59297c2f43f41e6ae66fd353cace01d3fde2de89f48230dff4a856a17f292'),
  ('en.sahih', 34, 14, 3620, 'And when We decreed for Solomon death, nothing indicated to the jinn his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment.', NULL, NULL, 'e8abb07e917942a71242058cc66d9476279ba6731c41f4ee92e8d79c1ff4e2f2'),
  ('en.sahih', 34, 15, 3621, 'There was for [the tribe of] Saba'' in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], "Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord."', NULL, NULL, '6e26b39d4b4379f89a92aace0b91607757a91441eb0ca4692e57df1414619f98'),
  ('en.sahih', 34, 16, 3622, 'But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees.', NULL, NULL, 'e4269aa26f2f9bed0fb4446d8c385348781e13d6a286f69c34cdcc69796bda97'),
  ('en.sahih', 34, 17, 3623, '[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?', NULL, NULL, '69c64501085ffddd76a84a3f42143a4078275457ab695f60cab600c979795dab'),
  ('en.sahih', 34, 18, 3624, 'And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], "Travel between them by night or day in safety."', NULL, NULL, '4e4c6cd86803ad73155c506361fd81ea98ae5cbe29b6af18b7e1fd0685c9515f'),
  ('en.sahih', 34, 19, 3625, 'But [insolently] they said, "Our Lord, lengthen the distance between our journeys," and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful.', NULL, NULL, 'fc83c751aa58cdcb045d924bf75f80d5bd701151a4a3e69ff0fc96d47a8ddc3e'),
  ('en.sahih', 34, 20, 3626, 'And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers.', NULL, NULL, '28ac2729cb9f0c2a91f74f79bbcc7e4ed0ab3dcd94243ad146d28419384dc999'),
  ('en.sahih', 34, 21, 3627, 'And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian.', NULL, NULL, '6b76b24b6dc4b7015a471b4490565df40da699c4d03ddaf82efa5f4ef6046586'),
  ('en.sahih', 34, 22, 3628, 'Say, [O Muhammad], "Invoke those you claim [as deities] besides Allah." They do not possess an atom''s weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant.', NULL, NULL, '02c146b34192b64b46c523c32374ba225d8aa3f9eaf3cd84d1c85c8a36ef932e'),
  ('en.sahih', 34, 23, 3629, 'And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], "What has your Lord said?" They will say, "The truth." And He is the Most High, the Grand.', NULL, NULL, '30f5f5c0c21cda79ee0c0044fa17eeef2e1e9ff4bac60a44e91eda0700a512a5'),
  ('en.sahih', 34, 24, 3630, 'Say, "Who provides for you from the heavens and the earth?" Say, "Allah. And indeed, we or you are either upon guidance or in clear error."', NULL, NULL, '99940934a780d68de142f441ba61491097c485eb8c03987c474157f0a3e865d3'),
  ('en.sahih', 34, 25, 3631, 'Say, "You will not be asked about what we committed, and we will not be asked about what you do."', NULL, NULL, '5ee11f9924eb2956deff28c798124bd0fe34a209236b725070d1b8e66287b830'),
  ('en.sahih', 34, 26, 3632, 'Say, "Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge."', NULL, NULL, '0a1cc8bcd11234cd6cc389ee652c62affeafd53daec9c04001576ee96dd870ce'),
  ('en.sahih', 34, 27, 3633, 'Say, "Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allah, the Exalted in Might, the Wise."', NULL, NULL, '3360103752cd2ed66b3e77d41e2169f3d295cbf9c3601edf699d53d71795b24a'),
  ('en.sahih', 34, 28, 3634, 'And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know.', NULL, NULL, 'a47988fdcd4aac1ac28e2a897b3f92d8b1dd656e0404a0e502228582994f2f66'),
  ('en.sahih', 34, 29, 3635, 'And they say, "When is this promise, if you should be truthful?"', NULL, NULL, 'e4ee081fcbbad38a41d5b6a7019faf4a99f8ff664f6d41adf700b9660b4d4a8a'),
  ('en.sahih', 34, 30, 3636, 'Say, "For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it]."', NULL, NULL, 'e8fa7cb4e963e73ad8b4499acf26597b412ef9b1ee4d801133a3cc2bb8e90bf7'),
  ('en.sahih', 34, 31, 3637, 'And those who disbelieve say, "We will never believe in this Qur''an nor in that before it." But if you could see when the wrongdoers are made to stand before their Lord, refuting each other''s words... Those who were oppressed will say to those who were arrogant, "If not for you, we would have been believers."', NULL, NULL, 'bbc5dab968a8849e76963d3051af63fa5126701aa0150aa12eeb7431a7d8ee66'),
  ('en.sahih', 34, 32, 3638, 'Those who were arrogant will say to those who were oppressed, "Did we avert you from guidance after it had come to you? Rather, you were criminals."', NULL, NULL, 'bb0aa1e342828823d41d5c93904162084fcceab46672a00623eb79af1b6dcdce'),
  ('en.sahih', 34, 33, 3639, 'Those who were oppressed will say to those who were arrogant, "Rather, [it was your] conspiracy of night and day when you were ordering us to disbelieve in Allah and attribute to Him equals." But they will [all] confide regret when they see the punishment; and We will put shackles on the necks of those who disbelieved. Will they be recompensed except for what they used to do?', NULL, NULL, '283fc1d8f946075715292c560d31b6875e9d6946b4ee555843f0625b2f4e41d8'),
  ('en.sahih', 34, 34, 3640, 'And We did not send into a city any warner except that its affluent said, "Indeed we, in that with which you were sent, are disbelievers."', NULL, NULL, '162c702c20447f36c1b9f9ae895b924d106b8607103a67bbe16de5f4bbc58f43'),
  ('en.sahih', 34, 35, 3641, 'And they said, "We are more [than the believers] in wealth and children, and we are not to be punished."', NULL, NULL, '9eb9fb0cfce12f5fa8f26c8443ed4024e607e7b5d2c8c2477839adcec98ce9f9'),
  ('en.sahih', 34, 36, 3642, 'Say, "Indeed, my Lord extends provision for whom He wills and restricts [it], but most of the people do not know."', NULL, NULL, 'd7a9d44c6cac94c667eb50e78f0c217ff3c52fd526701b1b39f56a6bdcf2d6f8'),
  ('en.sahih', 34, 37, 3643, 'And it is not your wealth or your children that bring you nearer to Us in position, but it is [by being] one who has believed and done righteousness. For them there will be the double reward for what they did, and they will be in the upper chambers [of Paradise], safe [and secure].', NULL, NULL, '12e732b5a8215ea368587cb00567391be1762c259238c2c2e30575153c1d7e64'),
  ('en.sahih', 34, 38, 3644, 'And the ones who strive against Our verses to cause [them] failure - those will be brought into the punishment [to remain].', NULL, NULL, '4231c6d5f80e0d1832b6910a5233c1217d258eda49fddc7268272e220a21834a'),
  ('en.sahih', 34, 39, 3645, 'Say, "Indeed, my Lord extends provision for whom He wills of His servants and restricts [it] for him. But whatever thing you spend [in His cause] - He will compensate it; and He is the best of providers."', NULL, NULL, '1ab405f1402b365ccd68cc6bc7c7a05b8d263c253840fe68a043a98feb1e1724'),
  ('en.sahih', 34, 40, 3646, 'And [mention] the Day when He will gather them all and then say to the angels, "Did these [people] used to worship you?"', NULL, NULL, 'ceab33fa4b8d2dd685ae864fd1d53627949a383f6e95f22c640fe2b83dc99af0'),
  ('en.sahih', 34, 41, 3647, 'They will say, "Exalted are You! You, [O Allah], are our benefactor not them. Rather, they used to worship the jinn; most of them were believers in them."', NULL, NULL, '0f67fff02515e91483ece4d45e821c20aaad37e02354b2b50acd9ba504606f16'),
  ('en.sahih', 34, 42, 3648, 'But today you do not hold for one another [the power of] benefit or harm, and We will say to those who wronged, "Taste the punishment of the Fire, which you used to deny."', NULL, NULL, 'e6a8f3e4aec587e295154ad6e38697e399d5b054dceb120075bb3e8502b67deb'),
  ('en.sahih', 34, 43, 3649, 'And when our verses are recited to them as clear evidences, they say, "This is not but a man who wishes to avert you from that which your fathers were worshipping." And they say, "This is not except a lie invented." And those who disbelieve say of the truth when it has come to them, "This is not but obvious magic."', NULL, NULL, '1898ca682576a1e61f35eee32b05dfb5d609d135d4afe45d312aa8c722150520'),
  ('en.sahih', 34, 44, 3650, 'And We had not given them any scriptures which they could study, and We had not sent to them before you, [O Muhammad], any warner.', NULL, NULL, '7366699c92fea53d8ee813281b06dd99d8cf74e241d8b7c14b5580e745fd1cb0'),
  ('en.sahih', 34, 45, 3651, 'And those before them denied, and the people of Makkah have not attained a tenth of what We had given them. But the former peoples denied My messengers, so how [terrible] was My reproach.', NULL, NULL, 'e8eaa96b6b3091daea9450741a2bf32953eeffd23a13852c5d871cfd6094f062'),
  ('en.sahih', 34, 46, 3652, 'Say, "I only advise you of one [thing] - that you stand for Allah, [seeking truth] in pairs and individually, and then give thought." There is not in your companion any madness. He is only a warner to you before a severe punishment.', NULL, NULL, '868790782bd820bd4104c12fad92f2357a8de8566e67dc05f43db1f22204167a'),
  ('en.sahih', 34, 47, 3653, 'Say, "Whatever payment I might have asked of you - it is yours. My payment is only from Allah, and He is, over all things, Witness."', NULL, NULL, '94d50ac74039db5fa2faa73f38ff94059b225cf53b19b462661d4672f1df0c73'),
  ('en.sahih', 34, 48, 3654, 'Say, "Indeed, my Lord projects the truth. Knower of the unseen."', NULL, NULL, '64129b95408f64854d761783a918cb113afcd1e14afb1825eb2bc6b0b406a997'),
  ('en.sahih', 34, 49, 3655, 'Say, "The truth has come, and falsehood can neither begin [anything] nor repeat [it]."', NULL, NULL, '5c03823e7842e965653ed9125b74351405c1661112f4a5bc17788ae80044e6a9'),
  ('en.sahih', 34, 50, 3656, 'Say, "If I should err, I would only err against myself. But if I am guided, it is by what my Lord reveals to me. Indeed, He is Hearing and near."', NULL, NULL, '1e9ed33b5a6f9faa170190261575913a40cd05923a55fc4d1c64101f25a083f8'),
  ('en.sahih', 34, 51, 3657, 'And if you could see when they are terrified but there is no escape, and they will be seized from a place nearby.', NULL, NULL, 'bc72154d42bac1e01aa48e70b949370df13e70a86d74d2adaf65f543a0807fae'),
  ('en.sahih', 34, 52, 3658, 'And they will [then] say, "We believe in it!" But how for them will be the taking [of faith] from a place far away?', NULL, NULL, '5f6335b7545d03f8b62e6e760a10a8ae1e652ae3805bcec0b99e9d466a112140'),
  ('en.sahih', 34, 53, 3659, 'And they had already disbelieved in it before and would assault the unseen from a place far away.', NULL, NULL, 'eba92d5ff574f1ebaa4120d2c9a91186e343f3eb3c40b90fc1c50e81ac5008a4'),
  ('en.sahih', 34, 54, 3660, 'And prevention will be placed between them and what they desire, as was done with their kind before. Indeed, they were in disquieting denial.', NULL, NULL, '29b5014e95da7e63ea2ed95202a9029dc9fd984c8eda18636b55744e4c2d84b2'),
  ('en.sahih', 35, 1, 3661, '[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent.', NULL, NULL, '2aeffeee9639178d86c8c7d32782e37a3d4eae08d8e56c7839d8bc0f8e34c3ee'),
  ('en.sahih', 35, 2, 3662, 'Whatever Allah grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise.', NULL, NULL, '4daed7833ce1a23e3f42e04c145cb7bc6623e18ed9db7bd7de40fff6afb91c24'),
  ('en.sahih', 35, 3, 3663, 'O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?', NULL, NULL, 'b73ad9e3fa34932586642aec9cd723de3a43f99bf60813595aafb384f9601223'),
  ('en.sahih', 35, 4, 3664, 'And if they deny you, [O Muhammad] - already were messengers denied before you. And to Allah are returned [all] matters.', NULL, NULL, 'e784bf9fbb20157bb88930866fb098b4c6a88ccc49715d5ee4f30a7169088179'),
  ('en.sahih', 35, 5, 3665, 'O mankind, indeed the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.', NULL, NULL, '4b2faee284585fc0ca81ae4aaee3eecfaca4f55700040cbebb8c034c491c40fa'),
  ('en.sahih', 35, 6, 3666, 'Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze.', NULL, NULL, '542e4c1a20083aa33cd8cc582a5bfb6da120897ce8fb26a23415129d08c5101f'),
  ('en.sahih', 35, 7, 3667, 'Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward.', NULL, NULL, '5a1b457c6d98cfbac19158ce8e5a8f9331a90f8af0dea27533d2699addc20799'),
  ('en.sahih', 35, 8, 3668, 'Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allah sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allah is Knowing of what they do.', NULL, NULL, '47eef6d550e8852440911d57f752c94d6052ea997d7a91a453ebbe260726bfbd'),
  ('en.sahih', 35, 9, 3669, 'And it is Allah who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection.', NULL, NULL, '7b9db49c7c3f7ab142c8e84a07b4c1c76c6f4461b14e8554d6fccbab6f59ed84'),
  ('en.sahih', 35, 10, 3670, 'Whoever desires honor [through power] - then to Allah belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish.', NULL, NULL, 'e5485635f472f37c01d412e7fc12767fd51942a8317328cd13a921c4e5145393'),
  ('en.sahih', 35, 11, 3671, 'And Allah created you from dust, then from a sperm-drop; then He made you mates. And no female conceives nor does she give birth except with His knowledge. And no aged person is granted [additional] life nor is his lifespan lessened but that it is in a register. Indeed, that for Allah is easy.', NULL, NULL, '19acb7cf03dc931095b24298d23c2c04f4a9c438856a90c26fd917bc96b8c816'),
  ('en.sahih', 35, 12, 3672, 'And not alike are the two bodies of water. One is fresh and sweet, palatable for drinking, and one is salty and bitter. And from each you eat tender meat and extract ornaments which you wear, and you see the ships plowing through [them] that you might seek of His bounty; and perhaps you will be grateful.', NULL, NULL, '1658043515b78930175f644ee53f84820fdfc1f641a43f02ff90b03c1b40933b'),
  ('en.sahih', 35, 13, 3673, 'He causes the night to enter the day, and He causes the day to enter the night and has subjected the sun and the moon - each running [its course] for a specified term. That is Allah, your Lord; to Him belongs sovereignty. And those whom you invoke other than Him do not possess [as much as] the membrane of a date seed.', NULL, NULL, 'fd6c5559d575152b0bed75258c1e38cdab72a2dcb1b732d89979d1dd7e673d9b'),
  ('en.sahih', 35, 14, 3674, 'If you invoke them, they do not hear your supplication; and if they heard, they would not respond to you. And on the Day of Resurrection they will deny your association. And none can inform you like [one] Acquainted [with all matters].', NULL, NULL, '83f8c987c167f78a964c0447b1a07938ad46960cd478141f559893fd57dbba4b'),
  ('en.sahih', 35, 15, 3675, 'O mankind, you are those in need of Allah, while Allah is the Free of need, the Praiseworthy.', NULL, NULL, 'ad214eaf3fab6bc14badf2884a988a294400ddbd10073f5f8d5989feddc28a02'),
  ('en.sahih', 35, 16, 3676, 'If He wills, He can do away with you and bring forth a new creation.', NULL, NULL, '6a61b3f98fd95a40f3285678bbf10141636f92276767dfb55fb53271e687e269'),
  ('en.sahih', 35, 17, 3677, 'And that is for Allah not difficult.', NULL, NULL, '12535400514bae90ef4fd6a49bae7dda933bcf023dc54a0bd1cf919b226d012a'),
  ('en.sahih', 35, 18, 3678, 'And no bearer of burdens will bear the burden of another. And if a heavily laden soul calls [another] to [carry some of] its load, nothing of it will be carried, even if he should be a close relative. You can only warn those who fear their Lord unseen and have established prayer. And whoever purifies himself only purifies himself for [the benefit of] his soul. And to Allah is the [final] destination.', NULL, NULL, '05bedc9805038bc69ac01d1ae69ee82c376a1c6f1f3a3bfebb45df874ff517c2'),
  ('en.sahih', 35, 19, 3679, 'Not equal are the blind and the seeing,', NULL, NULL, 'c00a99f5e8c7ca3bb9165befcb59649e1b2ef221856b5cb03ed63b51767fc05c'),
  ('en.sahih', 35, 20, 3680, 'Nor are the darknesses and the light,', NULL, NULL, 'eed68e38787455f67f7b313a85384f132c3a9798fd8c1b194027dfdce3817475'),
  ('en.sahih', 35, 21, 3681, 'Nor are the shade and the heat,', NULL, NULL, 'd55df5116e0b4e21121c081a39a5e3726e7943be8119e36512000a4b6a7a3367'),
  ('en.sahih', 35, 22, 3682, 'And not equal are the living and the dead. Indeed, Allah causes to hear whom He wills, but you cannot make hear those in the graves.', NULL, NULL, '6547220a4f3bf9c0352f27fa1da536c5a815428d5f10beb8bebc6f0500e92e6d'),
  ('en.sahih', 35, 23, 3683, 'You, [O Muhammad], are not but a warner.', NULL, NULL, 'ee3d9409801cc03eee1ba316fff5b789a84621a422fe9f5d045f40a8d1946915'),
  ('en.sahih', 35, 24, 3684, 'Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner.', NULL, NULL, 'a8720c74dd6c98ebc366efb8483047bc9ff7284de58ae98095f157305538bd7a'),
  ('en.sahih', 35, 25, 3685, 'And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture.', NULL, NULL, 'dd35bbe0d1a8d92aa735cbb1c3d37d926047e262aa92ade879a35e491b5a4a3b'),
  ('en.sahih', 35, 26, 3686, 'Then I seized the ones who disbelieved, and how [terrible] was My reproach.', NULL, NULL, '79f0b656c971b0df1d69d3d85706c9970fb5dcd152e5bc7ba95c36c833b25d53'),
  ('en.sahih', 35, 27, 3687, 'Do you not see that Allah sends down rain from the sky, and We produce thereby fruits of varying colors? And in the mountains are tracts, white and red of varying shades and [some] extremely black.', NULL, NULL, 'abc04bfd19bbd807cc66f5d3d2e9522d012caaf7a6f7a85ad639876d9c729df5'),
  ('en.sahih', 35, 28, 3688, 'And among people and moving creatures and grazing livestock are various colors similarly. Only those fear Allah, from among His servants, who have knowledge. Indeed, Allah is Exalted in Might and Forgiving.', NULL, NULL, 'c59d74f76e246dbef1429509a174bcb94cc7a255dc25e6a3a034e918ea388084'),
  ('en.sahih', 35, 29, 3689, 'Indeed, those who recite the Book of Allah and establish prayer and spend [in His cause] out of what We have provided them, secretly and publicly, [can] expect a profit that will never perish -', NULL, NULL, 'cedde8c0f4d5cd2696f1b60729563af6e37d3f79155a36971d6d85746e5a51d4'),
  ('en.sahih', 35, 30, 3690, 'That He may give them in full their rewards and increase for them of His bounty. Indeed, He is Forgiving and Appreciative.', NULL, NULL, '0138c9f7ecefd48183607873a13711f62fee4fea45eae3114d11bebcf2df99bc'),
  ('en.sahih', 35, 31, 3691, 'And that which We have revealed to you, [O Muhammad], of the Book is the truth, confirming what was before it. Indeed, Allah, of His servants, is Acquainted and Seeing.', NULL, NULL, '24de4cb996edc70b93da86a1a26a2ffae56cfbd64f4022ba41a7012d870321f9'),
  ('en.sahih', 35, 32, 3692, 'Then we caused to inherit the Book those We have chosen of Our servants; and among them is he who wrongs himself, and among them is he who is moderate, and among them is he who is foremost in good deeds by permission of Allah. That [inheritance] is what is the great bounty.', NULL, NULL, 'c2bc5532f2f333e93a9631e311d9d35cfb1d516b31598ab7050f00452304f1d8'),
  ('en.sahih', 35, 33, 3693, '[For them are] gardens of perpetual residence which they will enter. They will be adorned therein with bracelets of gold and pearls, and their garments therein will be silk.', NULL, NULL, '54d1cf2b7b2fb47b068c32d3ff269ca9359953b6fcf4803531389bc8013697a3'),
  ('en.sahih', 35, 34, 3694, 'And they will say, "Praise to Allah, who has removed from us [all] sorrow. Indeed, our Lord is Forgiving and Appreciative -', NULL, NULL, 'c1174da26dfcdf17b15d3125c2cadf2ac11de51a56dd0a2ac25e0c05807ba16d'),
  ('en.sahih', 35, 35, 3695, 'He who has settled us in the home of duration out of His bounty. There touches us not in it any fatigue, and there touches us not in it weariness [of mind]."', NULL, NULL, '006074f5edafa0aa026a147984c7540c509632cedecc107567c7ff46d0e64d82'),
  ('en.sahih', 35, 36, 3696, 'And for those who disbelieve will be the fire of Hell. [Death] is not decreed for them so they may die, nor will its torment be lightened for them. Thus do we recompense every ungrateful one.', NULL, NULL, '2691c3ae249aa8f9efce26846d69e929fbf3d7d2f0c9c2e5a0c197a227f4f6ac'),
  ('en.sahih', 35, 37, 3697, 'And they will cry out therein, "Our Lord, remove us; we will do righteousness - other than what we were doing!" But did We not grant you life enough for whoever would remember therein to remember, and the warner had come to you? So taste [the punishment], for there is not for the wrongdoers any helper.', NULL, NULL, '22a5fae1f403f2ae32a14331e7a28df0b692dc9fa4a735bcc0dbd4c2dd271594'),
  ('en.sahih', 35, 38, 3698, 'Indeed, Allah is Knower of the unseen [aspects] of the heavens and earth. Indeed, He is Knowing of that within the breasts.', NULL, NULL, '1c4713c423b676ee4247a09b137e417e89e68319815d2b965c44e6bb714d7920'),
  ('en.sahih', 35, 39, 3699, 'It is He who has made you successors upon the earth. And whoever disbelieves - upon him will be [the consequence of] his disbelief. And the disbelief of the disbelievers does not increase them in the sight of their Lord except in hatred; and the disbelief of the disbelievers does not increase them except in loss.', NULL, NULL, 'd54dec6d618b60cf28fe009d4f067acbc182ab5e4ce89bd10313a3d5495edb2b'),
  ('en.sahih', 35, 40, 3700, 'Say, "Have you considered your ''partners'' whom you invoke besides Allah? Show me what they have created from the earth, or have they partnership [with Him] in the heavens? Or have We given them a book so they are [standing] on evidence therefrom? [No], rather, the wrongdoers do not promise each other except delusion."', NULL, NULL, '027f045c1069c069e63044a8a5069bb29eebbc4d0829e31a801b45914339d91d')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 35, 41, 3701, 'Indeed, Allah holds the heavens and the earth, lest they cease. And if they should cease, no one could hold them [in place] after Him. Indeed, He is Forbearing and Forgiving.', NULL, NULL, '7a990e2bc676a1d50290bb7baa43c3dc2083f5b2d34a8a169d3d6ae44de11703'),
  ('en.sahih', 35, 42, 3702, 'And they swore by Allah their strongest oaths that if a warner came to them, they would be more guided than [any] one of the [previous] nations. But when a warner came to them, it did not increase them except in aversion.', NULL, NULL, '689e84861a5e17945f3cdafde84dce52345db425a29e3152d8adf96fb42a32b7'),
  ('en.sahih', 35, 43, 3703, '[Due to] arrogance in the land and plotting of evil; but the evil plot does not encompass except its own people. Then do they await except the way of the former peoples? But you will never find in the way of Allah any change, and you will never find in the way of Allah any alteration.', NULL, NULL, '80df114204e5a990d795782b2023f54f38fdadbaeecae2ae799e8ec26355213c'),
  ('en.sahih', 35, 44, 3704, 'Have they not traveled through the land and observed how was the end of those before them? And they were greater than them in power. But Allah is not to be caused failure by anything in the heavens or on the earth. Indeed, He is ever Knowing and Competent.', NULL, NULL, 'ee2eef88fff4cd2d4aee494e30a6d7a59d7c46792e343be936d4e45ce8564626'),
  ('en.sahih', 35, 45, 3705, 'And if Allah were to impose blame on the people for what they have earned, He would not leave upon the earth any creature. But He defers them for a specified term. And when their time comes, then indeed Allah has ever been, of His servants, Seeing.', NULL, NULL, '888b31f505db2abeb6505e96f3f455a9d4c670506673aaec1908c349700e47d2'),
  ('en.sahih', 36, 1, 3706, 'Ya, Seen.', NULL, NULL, 'd0a2783d8220a9e963c4bbbf981010ad754af0e5fed168f7ba60c04ef996faaf'),
  ('en.sahih', 36, 2, 3707, 'By the wise Qur''an.', NULL, NULL, '68146da4587282459954fc91cf7f977e4add379689950e6d6cbc401cc0873a96'),
  ('en.sahih', 36, 3, 3708, 'Indeed you, [O Muhammad], are from among the messengers,', NULL, NULL, '0f1ed6d21e4e27138fd11c002288d888a8bcaa5c94cc27ba3160dae2558af4b7'),
  ('en.sahih', 36, 4, 3709, 'On a straight path.', NULL, NULL, 'eb014e29434510597fc011cf84358eeb92ae52d651e9fef2f25488e1dd04032f'),
  ('en.sahih', 36, 5, 3710, '[This is] a revelation of the Exalted in Might, the Merciful,', NULL, NULL, '20832ec9ece263ccc36d748a4c0116bafad174afc24f6ad5507410fc08956b4a'),
  ('en.sahih', 36, 6, 3711, 'That you may warn a people whose forefathers were not warned, so they are unaware.', NULL, NULL, '282db7cc8384a4a5ef1527ad522058f5005f4fa77cd01bb1f634680ce5674cac'),
  ('en.sahih', 36, 7, 3712, 'Already the word has come into effect upon most of them, so they do not believe.', NULL, NULL, '3e5627869be89a890135915f36c825d4ead439aa73943135abe051813a690ce4'),
  ('en.sahih', 36, 8, 3713, 'Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft.', NULL, NULL, '4d2dbe234885f972ec1564f18f7358e5147138050db6a9a6577d418ad3284c2f'),
  ('en.sahih', 36, 9, 3714, 'And We have put before them a barrier and behind them a barrier and covered them, so they do not see.', NULL, NULL, '8c5b4a8a7ce667f87cc1be4793e507ecd01ec67192935af919b9f22f14921d41'),
  ('en.sahih', 36, 10, 3715, 'And it is all the same for them whether you warn them or do not warn them - they will not believe.', NULL, NULL, '8c04f0bc563cc51996dd0e0bbfd773602f63e0be0732c14921490d22175a5791'),
  ('en.sahih', 36, 11, 3716, 'You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.', NULL, NULL, 'e9321403092427de19443e12a32782729b0fc9513f62d3d639ba2182e4ee38ae'),
  ('en.sahih', 36, 12, 3717, 'Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register.', NULL, NULL, '1a01d207aef4a3731df7d362ac92d3aa019b79606c7ee746e4e39a458b85e1e1'),
  ('en.sahih', 36, 13, 3718, 'And present to them an example: the people of the city, when the messengers came to it -', NULL, NULL, 'a5f7d7e337cfa152b64fb339ee9f43fb67c671de9971501f7feecbffd82f8a23'),
  ('en.sahih', 36, 14, 3719, 'When We sent to them two but they denied them, so We strengthened them with a third, and they said, "Indeed, we are messengers to you."', NULL, NULL, '2b17a6b39b69f0e6170d27aa57b393a3aa966a1bcb8af9e8a217cfcc822c6d62'),
  ('en.sahih', 36, 15, 3720, 'They said, "You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies."', NULL, NULL, '68dded83031efc241d3c60614dfbb3d70121bfccba8fe25c437c43d8ff3feb0e'),
  ('en.sahih', 36, 16, 3721, 'They said, "Our Lord knows that we are messengers to you,', NULL, NULL, '6a39857b8a7da2e989d110e2b731454ce9012c32e8d3666ab94a7006a8690d9d'),
  ('en.sahih', 36, 17, 3722, 'And we are not responsible except for clear notification."', NULL, NULL, '865a90e3336e00a5762f821817fa6c11a656435489c34a437172aa8e8f2b4cf1'),
  ('en.sahih', 36, 18, 3723, 'They said, "Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment."', NULL, NULL, '8f0dd0eb3d012038f9517b622dcccc86875a4cd32935bd28c804e62a03da52ec'),
  ('en.sahih', 36, 19, 3724, 'They said, "Your omen is with yourselves. Is it because you were reminded? Rather, you are a transgressing people."', NULL, NULL, '90e74ff42603d1e73ec5c93e5a533c36822df2b312d0d3596c689a63c1e17cc4'),
  ('en.sahih', 36, 20, 3725, 'And there came from the farthest end of the city a man, running. He said, "O my people, follow the messengers.', NULL, NULL, '8361aa23c1dfb25e293b696242f8fc67fdb35a1e8318cd6f5c97ecb383ae3afc'),
  ('en.sahih', 36, 21, 3726, 'Follow those who do not ask of you [any] payment, and they are [rightly] guided.', NULL, NULL, 'bf4f416e0b437ca2f4754b1eafab008c58889ef45faf79165013dac7511fbdb0'),
  ('en.sahih', 36, 22, 3727, 'And why should I not worship He who created me and to whom you will be returned?', NULL, NULL, '3e0d8f4b45cdf70f87f74bb4009f84b7b9b1d1f07e820ffc49564d31929c3c4b'),
  ('en.sahih', 36, 23, 3728, 'Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?', NULL, NULL, '993f779941333df75e314f1f0d19c20becc373dd89f0542ac7975febc0bd8381'),
  ('en.sahih', 36, 24, 3729, 'Indeed, I would then be in manifest error.', NULL, NULL, '5d2a83f798f3d9b12bd0b24d1a79310fbe849635764d96afc3d07c7378b29e63'),
  ('en.sahih', 36, 25, 3730, 'Indeed, I have believed in your Lord, so listen to me."', NULL, NULL, 'c8e700fda73dfba891aaf6360303e5f27e4cdd14cc6ef51fee507ef8e410e420'),
  ('en.sahih', 36, 26, 3731, 'It was said, "Enter Paradise." He said, "I wish my people could know', NULL, NULL, '14b779bd015458881682ca44a41950ea595d947a85e64bba2129cea9efd3b0b6'),
  ('en.sahih', 36, 27, 3732, 'Of how my Lord has forgiven me and placed me among the honored."', NULL, NULL, '7ae22502c6e72012ce02f9426da8971ed6bcf1a1c25b078c924a01961b070f7b'),
  ('en.sahih', 36, 28, 3733, 'And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so.', NULL, NULL, '7b944be5ac04f29c8fcaa32e8e9e7bb1815cc8416ae134e9467bc937de6508f4'),
  ('en.sahih', 36, 29, 3734, 'It was not but one shout, and immediately they were extinguished.', NULL, NULL, 'afacaa1407383cd92ef445fe1ca83b7e94dc63c5a87a50ba3634490d90e6a89a'),
  ('en.sahih', 36, 30, 3735, 'How regretful for the servants. There did not come to them any messenger except that they used to ridicule him.', NULL, NULL, '687a3940f3761e34b504177acdf4a3a8b62fdf0c6740b27d6e4a3f35dc1006d1'),
  ('en.sahih', 36, 31, 3736, 'Have they not considered how many generations We destroyed before them - that they to them will not return?', NULL, NULL, '2d2c2392a613f5a172f962ebb5991f886930fab2b103afd91f17d41e57737834'),
  ('en.sahih', 36, 32, 3737, 'And indeed, all of them will yet be brought present before Us.', NULL, NULL, '891b460f3963e85529d724d992995a12128b9dd39bc5734db1bc5f39459cb878'),
  ('en.sahih', 36, 33, 3738, 'And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat.', NULL, NULL, '290a743de5f3b86b97495b080f8f191af92ec1c2360f006f7240d0390a570920'),
  ('en.sahih', 36, 34, 3739, 'And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -', NULL, NULL, '8f958c0b7b24a595908d49af37f01b239e220c67a48b0e8d2186f3e184143e7a'),
  ('en.sahih', 36, 35, 3740, 'That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?', NULL, NULL, '81e1971a2ce4a6c60f4a5650ac9b9a645759b99139cc471e55e373d06fdcd6c3'),
  ('en.sahih', 36, 36, 3741, 'Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.', NULL, NULL, '3d00e57fe6e932384bb733ad63ce2aedf65d03d5c290b025e37865df8761cb87'),
  ('en.sahih', 36, 37, 3742, 'And a sign for them is the night. We remove from it [the light of] day, so they are [left] in darkness.', NULL, NULL, '324ce19148f4b7f729f73282913c90f3198b20d241e97666c3ac33f4ecb62bfb'),
  ('en.sahih', 36, 38, 3743, 'And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.', NULL, NULL, '9e4f4fb0bae94585f658d28ca430cfd491ef5838ac45a3d630db5bbcf33c96f4'),
  ('en.sahih', 36, 39, 3744, 'And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.', NULL, NULL, '87a2bd1ebcfe99fee40d1f9513f0d8b9b7e0e7bc85bd73c3e787aa9c91506a6a'),
  ('en.sahih', 36, 40, 3745, 'It is not allowable for the sun to reach the moon, nor does the night overtake the day, but each, in an orbit, is swimming.', NULL, NULL, 'fd8a55490eba9b72a17f9ed695b88c04dc8670176bfd126568acc47d9f58d683'),
  ('en.sahih', 36, 41, 3746, 'And a sign for them is that We carried their forefathers in a laden ship.', NULL, NULL, 'b4f0f798a9654e1e13db76496c368e3b3eaa9ff924f04c140b47295d22040b83'),
  ('en.sahih', 36, 42, 3747, 'And We created for them from the likes of it that which they ride.', NULL, NULL, '2578a1ad6202bb4dbd9435dd86067c77dbebd6c337303b38f9577267e3bd2e97'),
  ('en.sahih', 36, 43, 3748, 'And if We should will, We could drown them; then no one responding to a cry would there be for them, nor would they be saved', NULL, NULL, 'b92c6caae2fb3894c4a190f29442dfcfae5668d2f28757c4c7c518375b0fbdf4'),
  ('en.sahih', 36, 44, 3749, 'Except as a mercy from Us and provision for a time.', NULL, NULL, '833e803798cdc943503bef9b002b86e7ebb017cebe616105cff23f91374de73c'),
  ('en.sahih', 36, 45, 3750, 'But when it is said to them, "Beware of what is before you and what is behind you; perhaps you will receive mercy... "', NULL, NULL, 'a63312d00ffd747ea4710a09b55bec93701312b8d32f50b37eeb18eca2939404'),
  ('en.sahih', 36, 46, 3751, 'And no sign comes to them from the signs of their Lord except that they are from it turning away.', NULL, NULL, 'd79fd7e581e445ed7fd7a3083ca7ec207d85233963ff78f79d90f05662a8008f'),
  ('en.sahih', 36, 47, 3752, 'And when it is said to them, "Spend from that which Allah has provided for you," those who disbelieve say to those who believe, "Should we feed one whom, if Allah had willed, He would have fed? You are not but in clear error."', NULL, NULL, '5e507ca609051fd9ba2a25379663ba08bb819a7c70a9932b3893b54bebc19a8f'),
  ('en.sahih', 36, 48, 3753, 'And they say, "When is this promise, if you should be truthful?"', NULL, NULL, 'e4ee081fcbbad38a41d5b6a7019faf4a99f8ff664f6d41adf700b9660b4d4a8a'),
  ('en.sahih', 36, 49, 3754, 'They do not await except one blast which will seize them while they are disputing.', NULL, NULL, '5f5ce846ee2f093b981c697a9d70673315d9e795f1a9cebe14a5bac2888003bf'),
  ('en.sahih', 36, 50, 3755, 'And they will not be able [to give] any instruction, nor to their people can they return.', NULL, NULL, '45b6bc0d7afcd2417b246ee6ce732321761246dc287e5a70ebeab34dce810b9d'),
  ('en.sahih', 36, 51, 3756, 'And the Horn will be blown; and at once from the graves to their Lord they will hasten.', NULL, NULL, '09cc630e20a16d58cf8748c00ce5b2efaddcdb8e55688561d2206f0f3c08f340'),
  ('en.sahih', 36, 52, 3757, 'They will say, "O woe to us! Who has raised us up from our sleeping place?" [The reply will be], "This is what the Most Merciful had promised, and the messengers told the truth."', NULL, NULL, 'ad5e8a23e56647ae23eee7dcab3762251b2192b1e42204f2fd694ddd00990a82'),
  ('en.sahih', 36, 53, 3758, 'It will not be but one blast, and at once they are all brought present before Us.', NULL, NULL, '03f33f487d078a3c5d8a3f334234718c03b514ab8ac04d134ba06d619be4c3a6'),
  ('en.sahih', 36, 54, 3759, 'So today no soul will be wronged at all, and you will not be recompensed except for what you used to do.', NULL, NULL, '107bc7a5615233c8ffda727c2643d55ee40aec94030a96768afaf54db48f93a5'),
  ('en.sahih', 36, 55, 3760, 'Indeed the companions of Paradise, that Day, will be amused in [joyful] occupation -', NULL, NULL, 'c0c15b85d520f7fa4688b0ca7466bf44b2ff2bebfdaed9b924825d1f9c513733'),
  ('en.sahih', 36, 56, 3761, 'They and their spouses - in shade, reclining on adorned couches.', NULL, NULL, 'e43dbe7fecbf2bb2614602514854609f1434bf9decc1abd81979bb7788fe1e82'),
  ('en.sahih', 36, 57, 3762, 'For them therein is fruit, and for them is whatever they request [or wish]', NULL, NULL, 'c06cb8a80134d372aacf3eae1f97f50a6b7ee067b244f8fd32f3943b94445911'),
  ('en.sahih', 36, 58, 3763, '[And] "Peace," a word from a Merciful Lord.', NULL, NULL, 'b7c55d3bdf54285a2f06bb30be8e8b12d57a60796a80608ac5442baa820930bf'),
  ('en.sahih', 36, 59, 3764, '[Then He will say], "But stand apart today, you criminals.', NULL, NULL, '3603f319c603fb81f2b21e54e97e2b77b21d06a8d609fe0f7684dbab17e40807'),
  ('en.sahih', 36, 60, 3765, 'Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -', NULL, NULL, '19232fda7e6dbfe7758cc303cd63701eabe61053a389fb28755e043e134ab321'),
  ('en.sahih', 36, 61, 3766, 'And that you worship [only] Me? This is a straight path.', NULL, NULL, '440ae849eae343c553a092a86b58459d0d996b1e46a2eb7c21935f65a2869fb0'),
  ('en.sahih', 36, 62, 3767, 'And he had already led astray from among you much of creation, so did you not use reason?', NULL, NULL, '53f41b9dba937ce2923141fd4e5c24a311ae395e24bc50767ed956ce59483bec'),
  ('en.sahih', 36, 63, 3768, 'This is the Hellfire which you were promised.', NULL, NULL, '7005cf375ebcb94b27fa1c5143b5c280973626109eb5b75c7b60b0836ab9a8c1'),
  ('en.sahih', 36, 64, 3769, '[Enter to] burn therein today for what you used to deny."', NULL, NULL, '90012919aee1cc09199af4c58764aaa0a5848d3b375372690bda90d3fd7bdff7'),
  ('en.sahih', 36, 65, 3770, 'That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn.', NULL, NULL, '768296d5de664ef31e14fea6675c41612a3419c97e9bdc76e312d12f32e64700'),
  ('en.sahih', 36, 66, 3771, 'And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?', NULL, NULL, 'b42e9a77850b09c7578a89ee61840b6febc58404617e21dfa6a8903d60fdf709'),
  ('en.sahih', 36, 67, 3772, 'And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return.', NULL, NULL, '34cfa1b532fd383f4fd84583db4798574b2fa430dc0e75a49feb119f6327eef5'),
  ('en.sahih', 36, 68, 3773, 'And he to whom We grant long life We reverse in creation; so will they not understand?', NULL, NULL, '3d3825a0bcbfe56bb993c679d689654dc0cdf623651cf290e3200aef3ccf4932'),
  ('en.sahih', 36, 69, 3774, 'And We did not give Prophet Muhammad, knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur''an', NULL, NULL, '8e6b1d907aa39ad6a573ccb39d89f7c9c152a9ec5da161944305a3f64a4c56e3'),
  ('en.sahih', 36, 70, 3775, 'To warn whoever is alive and justify the word against the disbelievers.', NULL, NULL, 'bce415060bbe565623521fba426ddd485a9b2883aef94b3403a553e675d6773e'),
  ('en.sahih', 36, 71, 3776, 'Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?', NULL, NULL, 'ce06e31ead7e18706518486b6e69dc1cbe3946b1e5fa3ff1ab39af9a07d4037f'),
  ('en.sahih', 36, 72, 3777, 'And We have tamed them for them, so some of them they ride, and some of them they eat.', NULL, NULL, '6dea100f465186ed5a01ea0603d3421bdd3ec8e0de9bfdce3e4ad4e62085abf2'),
  ('en.sahih', 36, 73, 3778, 'And for them therein are [other] benefits and drinks, so will they not be grateful?', NULL, NULL, 'b59763af57cd29384e759d738bccc312a63df6ada6fb6672dd955ead48a8280a'),
  ('en.sahih', 36, 74, 3779, 'But they have taken besides Allah [false] deities that perhaps they would be helped.', NULL, NULL, 'a1eef951823fc56c60d128afbbb253f8588de0379c2e124861fe01918b095afe'),
  ('en.sahih', 36, 75, 3780, 'They are not able to help them, and they [themselves] are for them soldiers in attendance.', NULL, NULL, '86d14ff58948931d07527ecc224401e6b527f7c0451d106136fa2b0b3947ed7f'),
  ('en.sahih', 36, 76, 3781, 'So let not their speech grieve you. Indeed, We know what they conceal and what they declare.', NULL, NULL, 'cfd8f66d0bb57da71bcdb7a71b2b06cac0b0dd383a269bcbfc696f2be4372f83'),
  ('en.sahih', 36, 77, 3782, 'Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?', NULL, NULL, '4771d0eb15ffb1fb2a75891b02e693bd0c7db5ee17faa75b0dc7bd2d4d1fdf85'),
  ('en.sahih', 36, 78, 3783, 'And he presents for Us an example and forgets his [own] creation. He says, "Who will give life to bones while they are disintegrated?"', NULL, NULL, 'de88c98cdafe8cbcb3345b97d150387e45f088dc9d478e41d2777255339a2c9d'),
  ('en.sahih', 36, 79, 3784, 'Say, "He will give them life who produced them the first time; and He is, of all creation, Knowing."', NULL, NULL, '79b91fac2caa9e99daf4b2c9c13ab04ad7c3219f53ae9f5a9e94644969d87955'),
  ('en.sahih', 36, 80, 3785, '[It is] He who made for you from the green tree, fire, and then from it you ignite.', NULL, NULL, 'af77c415ba0075e98c12f6d2b8ccfb44fd9ebb696b9e663b2f1369eef2eca2e2'),
  ('en.sahih', 36, 81, 3786, 'Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator.', NULL, NULL, 'e2121881604c63db94e1a90fb2b35547ca5a824a34e09f92fb1a2a3424e1fc4e'),
  ('en.sahih', 36, 82, 3787, 'His command is only when He intends a thing that He says to it, "Be," and it is.', NULL, NULL, '20ac7cc202cc62fc2ad7db6119594b4661025c0eab2e834882e0d249d683f897'),
  ('en.sahih', 36, 83, 3788, 'So exalted is He in whose hand is the realm of all things, and to Him you will be returned.', NULL, NULL, '9ec37413246f7f4ad9b6c44da2d4933720a0ab568b2641c4ad2c1b8ea4c968dd'),
  ('en.sahih', 37, 1, 3789, 'By those [angels] lined up in rows', NULL, NULL, '59178d3b1aff0695ad0f9ef6dab225af6fdfed63308dfcdb52d47ef9f6ddf647'),
  ('en.sahih', 37, 2, 3790, 'And those who drive [the clouds]', NULL, NULL, '2e0dfb4f8995aed3ded1302c9427ac3ec854bcf7c10e9010394b9c0346bc1055'),
  ('en.sahih', 37, 3, 3791, 'And those who recite the message,', NULL, NULL, '9d6672cf20ec2c494d117a6d18d2b2205d9c6995fb5c7eec99cf679fe084d195'),
  ('en.sahih', 37, 4, 3792, 'Indeed, your God is One,', NULL, NULL, 'cf847aa0a5b658fc688bca9eb1a2a985c0e72581cf3d1087ff4100339245417d'),
  ('en.sahih', 37, 5, 3793, 'Lord of the heavens and the earth and that between them and Lord of the sunrises.', NULL, NULL, '14bcc8eeb3946d5d13231652b88b8ce548cc8b082b053ed5e465fb502ffafbe4'),
  ('en.sahih', 37, 6, 3794, 'Indeed, We have adorned the nearest heaven with an adornment of stars', NULL, NULL, 'abadb8f9e7ccde91755e563acf1276f17c2cb7cef2a4ffc3891eb9aa14886e6d'),
  ('en.sahih', 37, 7, 3795, 'And as protection against every rebellious devil', NULL, NULL, '5d01a52fe603dcd2039f7ed3e864168e8f8c931e2535afd11782316b5d4886e9'),
  ('en.sahih', 37, 8, 3796, '[So] they may not listen to the exalted assembly [of angels] and are pelted from every side,', NULL, NULL, '5fe81033ea367a816ed54c00c6ff38e1c59d5daa8355d0276ad54ee42e661e44'),
  ('en.sahih', 37, 9, 3797, 'Repelled; and for them is a constant punishment,', NULL, NULL, '1995cf6a1d3d9d90d0d400307394204ae4b97008ca607edd10e341350271cebc'),
  ('en.sahih', 37, 10, 3798, 'Except one who snatches [some words] by theft, but they are pursued by a burning flame, piercing [in brightness].', NULL, NULL, 'b7f8df581a8b0a5f4805babab9a1386a927cf522d15ec5c87fd8a3ece4214a36'),
  ('en.sahih', 37, 11, 3799, 'Then inquire of them, [O Muhammad], "Are they a stronger [or more difficult] creation or those [others] We have created?" Indeed, We created men from sticky clay.', NULL, NULL, 'c697f60287bc56092a0f526ca546a96a1d3ebf1a2c2e69b095070b5e6a6270f0'),
  ('en.sahih', 37, 12, 3800, 'But you wonder, while they mock,', NULL, NULL, '57771798e05916528e214dedcf0e6c2695237d9b0fca528db420d75b5a39ee77')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 37, 13, 3801, 'And when they are reminded, they remember not.', NULL, NULL, 'bc4fbbe1db15948350c97a0a95c430699fe28908b62ddb7514d3bb86c3d7167f'),
  ('en.sahih', 37, 14, 3802, 'And when they see a sign, they ridicule', NULL, NULL, '82a78c57364974f739ceb4e96e7fefa208c67c605b790d92d9146eabc09fa5ca'),
  ('en.sahih', 37, 15, 3803, 'And say, "This is not but obvious magic.', NULL, NULL, '4e34dcc459784617ebf7d14bef9ee4b7add92a3320706c7bbf4776f250166a16'),
  ('en.sahih', 37, 16, 3804, 'When we have died and become dust and bones, are we indeed to be resurrected?', NULL, NULL, '1815c5437b4caa29f13ad05d19d4a688dbf47d6739b61f0cd22ddb10aa5d7469'),
  ('en.sahih', 37, 17, 3805, 'And our forefathers [as well]?"', NULL, NULL, 'e3252d59bc61776bdc8ba91dafba8d69ee877c31c6e58d8b99901c80bdf8ded3'),
  ('en.sahih', 37, 18, 3806, 'Say, "Yes, and you will be [rendered] contemptible."', NULL, NULL, '1b2e0901150b92df01b9d418e2d663afdc9268c960ba855ec754119e07ff0148'),
  ('en.sahih', 37, 19, 3807, 'It will be only one shout, and at once they will be observing.', NULL, NULL, '69e5c95f679b125d590752ab998963e3959e87152501c181837a739fcd545d2f'),
  ('en.sahih', 37, 20, 3808, 'They will say, "O woe to us! This is the Day of Recompense."', NULL, NULL, 'e3966ff7fb08ec37d8101db249da27ae53a26bbddfcf1fdd256ad93c52059050'),
  ('en.sahih', 37, 21, 3809, '[They will be told], "This is the Day of Judgement which you used to deny."', NULL, NULL, '4d71c9452796d6d32101cd6eab58472b35edb968737389cc4def8b388aeb68d1'),
  ('en.sahih', 37, 22, 3810, '[The angels will be ordered], "Gather those who committed wrong, their kinds, and what they used to worship', NULL, NULL, 'a374e84b7a3212cfbaf5d617d12713f7646dd52a3b578b93a43e85fde10b6dcc'),
  ('en.sahih', 37, 23, 3811, 'Other than Allah, and guide them to the path of Hellfire', NULL, NULL, 'beb91428519b2cfe313f7a74ee3c451e4a0c671e4a09cc88354ac6e442dd506b'),
  ('en.sahih', 37, 24, 3812, 'And stop them; indeed, they are to be questioned."', NULL, NULL, '21c7f2ae5873df47791fb994846f3099bec26a706690491f65c571ef87bd411c'),
  ('en.sahih', 37, 25, 3813, '[They will be asked], "What is [wrong] with you? Why do you not help each other?"', NULL, NULL, '29141c0e0bee63968ee2671f13155c76d031de9a785ae5ab16c41e8883466ca6'),
  ('en.sahih', 37, 26, 3814, 'But they, that Day, are in surrender.', NULL, NULL, '7965232414e5dac7845d39a4a03ee99b23106a470739331ac9c60e67c72cf08b'),
  ('en.sahih', 37, 27, 3815, 'And they will approach one another blaming each other.', NULL, NULL, 'a03ad79d71b976bdb59b03f6ec0b270176c9f5f806bd726986ee580d4c266ef8'),
  ('en.sahih', 37, 28, 3816, 'They will say, "Indeed, you used to come at us from the right."', NULL, NULL, '7641e432ba9d7bc4454f0d587490eb311ad59c81ad561bc3d3c4829925645432'),
  ('en.sahih', 37, 29, 3817, 'The oppressors will say, "Rather, you [yourselves] were not believers,', NULL, NULL, '628c64a92a1b0caef13a6314069361565dabee31c982148f867025effce5a719'),
  ('en.sahih', 37, 30, 3818, 'And we had over you no authority, but you were a transgressing people.', NULL, NULL, '5b8fa197f575aeded952440a70b28a3f84eb68814c0085549ebe3dca52237658'),
  ('en.sahih', 37, 31, 3819, 'So the word of our Lord has come into effect upon us; indeed, we will taste [punishment].', NULL, NULL, '04cd3e841e2891956e0b62c2246d9e9e211607eb8254a8d6e13fc5791913ceba'),
  ('en.sahih', 37, 32, 3820, 'And we led you to deviation; indeed, we were deviators."', NULL, NULL, '01649514ad09c9b3898b125cb9f5afc1f286a50532becba5a5b44708cab78878'),
  ('en.sahih', 37, 33, 3821, 'So indeed they, that Day, will be sharing in the punishment.', NULL, NULL, '4cc9e7b49ba2004e308a6a33182d747ab3d46e4adc19e9e999c8b5183d726c12'),
  ('en.sahih', 37, 34, 3822, 'Indeed, that is how We deal with the criminals.', NULL, NULL, '6022336606612e4e80263b0f1caf099a56568dbed66d55fe9736768ad5c193b6'),
  ('en.sahih', 37, 35, 3823, 'Indeed they, when it was said to them, "There is no deity but Allah," were arrogant', NULL, NULL, 'cda2ab718b1ff5f97439bd1212a98aa0c87c27f3db4c685e6474102f17bdac7c'),
  ('en.sahih', 37, 36, 3824, 'And were saying, "Are we to leave our gods for a mad poet?"', NULL, NULL, '1b7bba34752a6e2ea99abe132f2f780861ebc1e33f44a0aea47a84f783c49e97'),
  ('en.sahih', 37, 37, 3825, 'Rather, the Prophet has come with the truth and confirmed the [previous] messengers.', NULL, NULL, '3cb09d7448fea3acfecbfdbd09836e55bfc9baf1f969e2e5b48595644f427a58'),
  ('en.sahih', 37, 38, 3826, 'Indeed, you [disbelievers] will be tasters of the painful punishment,', NULL, NULL, 'aa06f4105a5516f802a5a606b7e92e6da14bd427603329c8cc970e65f32d18ea'),
  ('en.sahih', 37, 39, 3827, 'And you will not be recompensed except for what you used to do -', NULL, NULL, 'c502fb38617372ec3f77fed5de687d439d379f41dfaea9c972b535974de10941'),
  ('en.sahih', 37, 40, 3828, 'But not the chosen servants of Allah.', NULL, NULL, 'a5371336c3cc33c6e954e2bc2de29d980350b92b73a64475b3aa3ccda596a152'),
  ('en.sahih', 37, 41, 3829, 'Those will have a provision determined -', NULL, NULL, '3c3947291942e7aa6ea7775e773cc28fd6b6c66373c1b10896a5e420a86b87ba'),
  ('en.sahih', 37, 42, 3830, 'Fruits; and they will be honored', NULL, NULL, '189de2168cba6f3ea491f28b2ea76d871ab6971a57afcd4fa29cba82cfcea0ac'),
  ('en.sahih', 37, 43, 3831, 'In gardens of pleasure', NULL, NULL, '54de24f7773ab71662029743f9c0f3f9ffa2d48b572e9473ae0ec35fbcf9ecad'),
  ('en.sahih', 37, 44, 3832, 'On thrones facing one another.', NULL, NULL, '282e40ac01692ce973a5d4a32f7de4cc9cf78cd560841263d8c3774fa883d8a7'),
  ('en.sahih', 37, 45, 3833, 'There will be circulated among them a cup [of wine] from a flowing spring,', NULL, NULL, '0d2f5424021b5775542dff09ec9c1f9c158fdc61d513c159d93f0e1d4ab85714'),
  ('en.sahih', 37, 46, 3834, 'White and delicious to the drinkers;', NULL, NULL, '0bf87c2583b97e759febcd8718030426583f0e1cd99a7dfe051a166fedce45d5'),
  ('en.sahih', 37, 47, 3835, 'No bad effect is there in it, nor from it will they be intoxicated.', NULL, NULL, '89249eed41accc4c05c6beae7d7c82adffe7b261dca50532316a28db3cb0a2aa'),
  ('en.sahih', 37, 48, 3836, 'And with them will be women limiting [their] glances, with large, [beautiful] eyes,', NULL, NULL, '5cab868a250daf622ee664879bcfef16860947583fed4478be06d76f0681e2cd'),
  ('en.sahih', 37, 49, 3837, 'As if they were [delicate] eggs, well-protected.', NULL, NULL, '16e46ce8ee6cab2ab5c513f9a47bdf9a93d46cc3133394dee8a821860ae194b1'),
  ('en.sahih', 37, 50, 3838, 'And they will approach one another, inquiring of each other.', NULL, NULL, '34de1de76968e65dc56e67864361acc7ea450257d0e3b0c6a38e2c52c8d9cfc5'),
  ('en.sahih', 37, 51, 3839, 'A speaker among them will say, "Indeed, I had a companion [on earth]', NULL, NULL, '942db5f7dd07e15f2570e4987102aaa04266c88ea018f751c6e2c3717af3b4ff'),
  ('en.sahih', 37, 52, 3840, 'Who would say, ''Are you indeed of those who believe', NULL, NULL, '8922ef8b84fa883b6ef1d500683496b02c6fc4f9d174af0fa13103c1b57c6f87'),
  ('en.sahih', 37, 53, 3841, 'That when we have died and become dust and bones, we will indeed be recompensed?''"', NULL, NULL, 'ef1a1b6ba67cef63df5643e440476351f49aaa57826fa4278d82bbf43c44b2ff'),
  ('en.sahih', 37, 54, 3842, 'He will say, "Would you [care to] look?"', NULL, NULL, 'd406328ffd896c8335a3a4a68edff6da28a433172cc7613b9da9b7dc29f80dd9'),
  ('en.sahih', 37, 55, 3843, 'And he will look and see him in the midst of the Hellfire.', NULL, NULL, '0cb11156fe356468ec5fb305233d7186151f063badfd036526cd44a821d3250b'),
  ('en.sahih', 37, 56, 3844, 'He will say, "By Allah, you almost ruined me.', NULL, NULL, '7395019bfd5b67ab8f8566ef060f3f8d3b0b67d1985b85aa4686f5b01de047b2'),
  ('en.sahih', 37, 57, 3845, 'If not for the favor of my Lord, I would have been of those brought in [to Hell].', NULL, NULL, '2e6d32872e17bc2728fca061787cef43d7d11eca1664fc74eab5ee19a0b441d1'),
  ('en.sahih', 37, 58, 3846, 'Then, are we not to die', NULL, NULL, '542ea6207951c4f6e0e8607a9ef42868caa9e266732744ca21e8bc2bd6672f94'),
  ('en.sahih', 37, 59, 3847, 'Except for our first death, and we will not be punished?"', NULL, NULL, '9d68ea894b0b0b5451ccb18874401b58ec5c2f49503b640ac01387fdd7ca89e0'),
  ('en.sahih', 37, 60, 3848, 'Indeed, this is the great attainment.', NULL, NULL, '3901a31b9e92a70a146a155b6adbd3f13a8471a6c3bf7054329d6b3e8acb00cf'),
  ('en.sahih', 37, 61, 3849, 'For the like of this let the workers [on earth] work.', NULL, NULL, 'aef504edf19b252460c088a02ad44257ae4f99ead1577eb6a0ef8cf87914eed2'),
  ('en.sahih', 37, 62, 3850, 'Is Paradise a better accommodation or the tree of zaqqum?', NULL, NULL, '1474f0f15f078f405a62def1829fb3fb0f27b5570a60209f80778228bc62ad94'),
  ('en.sahih', 37, 63, 3851, 'Indeed, We have made it a torment for the wrongdoers.', NULL, NULL, '77335fec403388cb269b698d1233105520d1c9e593e34dce3941b8ff28fa9677'),
  ('en.sahih', 37, 64, 3852, 'Indeed, it is a tree issuing from the bottom of the Hellfire,', NULL, NULL, 'd83b5a85dd56e16b143f6788c9bd05d1e79db0f790491fdc613d62abeade138e'),
  ('en.sahih', 37, 65, 3853, 'Its emerging fruit as if it was heads of the devils.', NULL, NULL, 'c30ce6f3b11ca0301251ab80a38164645bad2165473458cb8b116ceb68b05f6e'),
  ('en.sahih', 37, 66, 3854, 'And indeed, they will eat from it and fill with it their bellies.', NULL, NULL, '76fa24813b264eb41d971df43145ccc720dba20c6a3d0ddae0228314e21a89bb'),
  ('en.sahih', 37, 67, 3855, 'Then indeed, they will have after it a mixture of scalding water.', NULL, NULL, 'ccbc15e37d1959e2f598520b4dd84eb9693cb5b31b046a669c4c8c24d65854be'),
  ('en.sahih', 37, 68, 3856, 'Then indeed, their return will be to the Hellfire.', NULL, NULL, '3d988216d1dd99921b46030e67c5e63d2f888a6db83f1bdcf90143e18cbc4c15'),
  ('en.sahih', 37, 69, 3857, 'Indeed they found their fathers astray.', NULL, NULL, '2b201132d57698f814400c699c3f7ba06b6367736db2dfc3586972b129c105f6'),
  ('en.sahih', 37, 70, 3858, 'So they hastened [to follow] in their footsteps.', NULL, NULL, 'cf1cf19860e2e9b0712e356fb15b9151aad975e6c9d4cfa981a0e874daa05f82'),
  ('en.sahih', 37, 71, 3859, 'And there had already strayed before them most of the former peoples,', NULL, NULL, 'c84f68f6fd72efeb135de4119d60a8b6afe7a2bd2052ac0747054fed2147d519'),
  ('en.sahih', 37, 72, 3860, 'And We had already sent among them warners.', NULL, NULL, 'ab31012b1b3f0a08f8a7c1f2ae60d43793c007f3459b772099545bad4adb7a81'),
  ('en.sahih', 37, 73, 3861, 'Then look how was the end of those who were warned -', NULL, NULL, 'a2fe5cb5ed22c6c3bda8e84b2594f9f6a15602e3dbb52b6a2931e8ce3c52fdfd'),
  ('en.sahih', 37, 74, 3862, 'But not the chosen servants of Allah.', NULL, NULL, 'a5371336c3cc33c6e954e2bc2de29d980350b92b73a64475b3aa3ccda596a152'),
  ('en.sahih', 37, 75, 3863, 'And Noah had certainly called Us, and [We are] the best of responders.', NULL, NULL, '2e5637ff6aa4e3f4e83c8a00368bec955018abdb83e005c581ad0a6a7243234a'),
  ('en.sahih', 37, 76, 3864, 'And We saved him and his family from the great affliction.', NULL, NULL, '7a97b533f1a6188936afaa8e9775611fc5e33d619ea366858d9293a89c404bcf'),
  ('en.sahih', 37, 77, 3865, 'And We made his descendants those remaining [on the earth]', NULL, NULL, 'b4f6ab680a35ea6506b0acd857dde20e8b83e8a75db35d090758d8bd6d4d252b'),
  ('en.sahih', 37, 78, 3866, 'And left for him [favorable mention] among later generations:', NULL, NULL, 'efe441936d63b52c9695a1f246db1cee13edf0421b74450d64fd4c445750d7b1'),
  ('en.sahih', 37, 79, 3867, '"Peace upon Noah among the worlds."', NULL, NULL, 'ccdad1b779cf8846f315da799e9a4fb7de25751ccb629334038f62ec2f6b7293'),
  ('en.sahih', 37, 80, 3868, 'Indeed, We thus reward the doers of good.', NULL, NULL, '96fb15e06afcb86aac61f0538d3be159d74652207077142bce899cf15e857d94'),
  ('en.sahih', 37, 81, 3869, 'Indeed, he was of Our believing servants.', NULL, NULL, 'e96d3c63ea2de2fddfb72e1284ab6cd4804c64edb23df9b1e2af1fda7a3e18e2'),
  ('en.sahih', 37, 82, 3870, 'Then We drowned the disbelievers.', NULL, NULL, '0836e1db638c1cef4e692124eec5a8cc8f730116b643dd533e1c4bf0f333be19'),
  ('en.sahih', 37, 83, 3871, 'And indeed, among his kind was Abraham,', NULL, NULL, 'e8def2ceab1eba4f76e0a5b403859d0f873c498b89735d34f17853549a80d547'),
  ('en.sahih', 37, 84, 3872, 'When he came to his Lord with a sound heart', NULL, NULL, '84d2b12bea99c9f80cc807c97d94bbf7a3b48c40e982b47a96dfa30597cc9fa6'),
  ('en.sahih', 37, 85, 3873, '[And] when he said to his father and his people, "What do you worship?', NULL, NULL, '30dc5d0068ad07331c3ff14cfc244aebbfa268df9c9ecd699a2a0111519d44b9'),
  ('en.sahih', 37, 86, 3874, 'Is it falsehood [as] gods other than Allah you desire?', NULL, NULL, '04ece9cbd2441d046cd761bffae0c5dea73ae5951bf669fcb321d4edd540441e'),
  ('en.sahih', 37, 87, 3875, 'Then what is your thought about the Lord of the worlds?"', NULL, NULL, '7da31cfb21273a91373008314c1941b93c2978a589df567ffd401425e777754d'),
  ('en.sahih', 37, 88, 3876, 'And he cast a look at the stars', NULL, NULL, 'f57ade051bfe2962febe3bc3a5aadb16b4f1b8112a4f0fdca1e0796aecd0c96e'),
  ('en.sahih', 37, 89, 3877, 'And said, "Indeed, I am [about to be] ill."', NULL, NULL, 'daf3a3cc22d937060c3f1f743ec0d293132fda43b8f93c12f86560f0131e6e96'),
  ('en.sahih', 37, 90, 3878, 'So they turned away from him, departing.', NULL, NULL, 'c7d814e420190afd3f1c180c9c9ec37ab504dd0d7aa2ba05d8de5458d7905eb7'),
  ('en.sahih', 37, 91, 3879, 'Then he turned to their gods and said, "Do you not eat?', NULL, NULL, '824a7f8dcabc56083dfd70796bee3aa3cac72d7b0dc43ee7cf9a12de90432023'),
  ('en.sahih', 37, 92, 3880, 'What is [wrong] with you that you do not speak?"', NULL, NULL, 'b836c66275ef57293895438b74144bc3ba17456c9267649bda2642be8349e31b'),
  ('en.sahih', 37, 93, 3881, 'And he turned upon them a blow with [his] right hand.', NULL, NULL, '6898be2c74cfd468b377b2a9d1b5233783882c3e85bf344727c243306da540a0'),
  ('en.sahih', 37, 94, 3882, 'Then the people came toward him, hastening.', NULL, NULL, '7107ebf87cc51df0298645365c444d93d3a9d4b5a6c088677662bc969ee7f0f8'),
  ('en.sahih', 37, 95, 3883, 'He said, "Do you worship that which you [yourselves] carve,', NULL, NULL, '5ff8e40b8b615f603154551a0e27aed97dcaf54978b32a91703ca37e3bce1a56'),
  ('en.sahih', 37, 96, 3884, 'While Allah created you and that which you do?"', NULL, NULL, '5f523b4b3514ab1861d6ac1a30070de6af5700991ec31125f2843efe8961ae72'),
  ('en.sahih', 37, 97, 3885, 'They said, "Construct for him a furnace and throw him into the burning fire."', NULL, NULL, '5bb8e16d8fd3f6d76562f3a3c984e328cfd42e15ee5e4a6aad9142179d139131'),
  ('en.sahih', 37, 98, 3886, 'And they intended for him a plan, but We made them the most debased.', NULL, NULL, '0053b891bc2a77bf7603225ec175bced6a842ef0f07821af6bcff305ad89abd0'),
  ('en.sahih', 37, 99, 3887, 'And [then] he said, "Indeed, I will go to [where I am ordered by] my Lord; He will guide me.', NULL, NULL, '3f980b19dfd68e10acd4f885a1129b08c22ff787e6556a46a1b37547f8f52125'),
  ('en.sahih', 37, 100, 3888, 'My Lord, grant me [a child] from among the righteous."', NULL, NULL, '3df3035d264cc2dea51af07d0a99368cb0b8ad84fcaed39faa34dd243f276427'),
  ('en.sahih', 37, 101, 3889, 'So We gave him good tidings of a forbearing boy.', NULL, NULL, '3bc5db7925dee9a06880b6d0eb148ded78799a2428a03c1bab8f4da9718c75c6'),
  ('en.sahih', 37, 102, 3890, 'And when he reached with him [the age of] exertion, he said, "O my son, indeed I have seen in a dream that I [must] sacrifice you, so see what you think." He said, "O my father, do as you are commanded. You will find me, if Allah wills, of the steadfast."', NULL, NULL, 'f05d339f528ce6d2a75746bcb2c47dfa65d377421d9e7b2e7b78a2888e04d731'),
  ('en.sahih', 37, 103, 3891, 'And when they had both submitted and he put him down upon his forehead,', NULL, NULL, '946535528b68943c125fc156dad4b5a9526d3b7003d700463132b04cb84199f7'),
  ('en.sahih', 37, 104, 3892, 'We called to him, "O Abraham,', NULL, NULL, 'e1486a293577d1cdbe1edbea31c385aae4f58725084cfb9f6d44c48ddc9cd15d'),
  ('en.sahih', 37, 105, 3893, 'You have fulfilled the vision." Indeed, We thus reward the doers of good.', NULL, NULL, '1dd77a35e29e37dc3d6b02c653fce06fd57023b9b5207d52c252f3d65863b61d'),
  ('en.sahih', 37, 106, 3894, 'Indeed, this was the clear trial.', NULL, NULL, 'f5f8040a32ffa6b5d7ec045a5d8995d05bd2efb96ac206703dbb3acebd43f09f'),
  ('en.sahih', 37, 107, 3895, 'And We ransomed him with a great sacrifice,', NULL, NULL, '2f780806f4c354f60d6a6cd5626447b61cf0d421606f0c0d503f23fab624979b'),
  ('en.sahih', 37, 108, 3896, 'And We left for him [favorable mention] among later generations:', NULL, NULL, '7fc102657f8bb29b7bdfaa053827faff4b0b3b83fcbc5806e92f6e8127199878'),
  ('en.sahih', 37, 109, 3897, '"Peace upon Abraham."', NULL, NULL, 'ae6e413b1dc0810477a949217fd6f159a821a263d8e595d64e848a988a8fc154'),
  ('en.sahih', 37, 110, 3898, 'Indeed, We thus reward the doers of good.', NULL, NULL, '96fb15e06afcb86aac61f0538d3be159d74652207077142bce899cf15e857d94'),
  ('en.sahih', 37, 111, 3899, 'Indeed, he was of Our believing servants.', NULL, NULL, 'e96d3c63ea2de2fddfb72e1284ab6cd4804c64edb23df9b1e2af1fda7a3e18e2'),
  ('en.sahih', 37, 112, 3900, 'And We gave him good tidings of Isaac, a prophet from among the righteous.', NULL, NULL, 'fb281558138aa2c1dd027c0e22e63e69f7c7dff9bdc5c66e0ed969c139ba282c')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 37, 113, 3901, 'And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself.', NULL, NULL, '8f69948807d849369b3daa895dbf0d1083b859a5b9e5c2a38a3fdd5cd34bb56d'),
  ('en.sahih', 37, 114, 3902, 'And We did certainly confer favor upon Moses and Aaron.', NULL, NULL, '4ad85b9cb47f890e4c8988c315da215b296f90ef772bc1ce1bfa998f7a207bb2'),
  ('en.sahih', 37, 115, 3903, 'And We saved them and their people from the great affliction,', NULL, NULL, '39fe7e15e239936d64396aaf488f212b2c9ebfbcbfbf99e3e071783ff6de196f'),
  ('en.sahih', 37, 116, 3904, 'And We supported them so it was they who overcame.', NULL, NULL, '289e7ac8f5704805a665392c14234a1f8f824276c5f477aa484d5addc2838924'),
  ('en.sahih', 37, 117, 3905, 'And We gave them the explicit Scripture,', NULL, NULL, '3c98045a35802d969ff775cc67aac43c015c79a0857a2b14c4b3acd259e104a2'),
  ('en.sahih', 37, 118, 3906, 'And We guided them on the straight path.', NULL, NULL, '8bba7e999be13ce9914ef661b64c970cc6b8a52891f35afbb10ec001cc3a3108'),
  ('en.sahih', 37, 119, 3907, 'And We left for them [favorable mention] among later generations:', NULL, NULL, '29b0d405ddc2eb2793e60bd1b5ff4dd1063fd44be29eb2738f60624ab6829b06'),
  ('en.sahih', 37, 120, 3908, '"Peace upon Moses and Aaron."', NULL, NULL, '4c4821011330278d6cfbf430d9364155f4b23f992a5aa7e082bc328d379392c5'),
  ('en.sahih', 37, 121, 3909, 'Indeed, We thus reward the doers of good.', NULL, NULL, '96fb15e06afcb86aac61f0538d3be159d74652207077142bce899cf15e857d94'),
  ('en.sahih', 37, 122, 3910, 'Indeed, they were of Our believing servants.', NULL, NULL, 'aa13e4927094f57d768aefaffccd71fa4ef571c413a304b32eda396c2f29fae1'),
  ('en.sahih', 37, 123, 3911, 'And indeed, Elias was from among the messengers,', NULL, NULL, '9c9a8f2eff007393be4a357e59a66fbf13c36c643a959fe29b886d3dc86ff7c0'),
  ('en.sahih', 37, 124, 3912, 'When he said to his people, "Will you not fear Allah?', NULL, NULL, '2b25ad971d63236b7e2531e9c41bb323794df34ea6392db279355972e0b3db12'),
  ('en.sahih', 37, 125, 3913, 'Do you call upon Ba''l and leave the best of creators -', NULL, NULL, '7eb075bbbec807e6a5344d8e1ab477cf2038fd4164fa5447aeb42f2687a6a15f'),
  ('en.sahih', 37, 126, 3914, 'Allah, your Lord and the Lord of your first forefathers?"', NULL, NULL, '1e0946cbc188d8ecb9b914218f93dde8adb3cb5a377fc19a004d051044698d3e'),
  ('en.sahih', 37, 127, 3915, 'And they denied him, so indeed, they will be brought [for punishment],', NULL, NULL, '14b88c6b50842aff9f9d6a737c2186166a264e53bc77eb248a0584a19943b6fe'),
  ('en.sahih', 37, 128, 3916, 'Except the chosen servants of Allah.', NULL, NULL, 'a99384773bf9a76ea74cb3e65fb8d06b1335ef9ced813dd6e4d53d7100c56f6c'),
  ('en.sahih', 37, 129, 3917, 'And We left for him [favorable mention] among later generations:', NULL, NULL, '7fc102657f8bb29b7bdfaa053827faff4b0b3b83fcbc5806e92f6e8127199878'),
  ('en.sahih', 37, 130, 3918, '"Peace upon Elias."', NULL, NULL, 'a2fec2605fb3af3351cc53cdaa77272d7599d1547c7319b9019153edf3ae5489'),
  ('en.sahih', 37, 131, 3919, 'Indeed, We thus reward the doers of good.', NULL, NULL, '96fb15e06afcb86aac61f0538d3be159d74652207077142bce899cf15e857d94'),
  ('en.sahih', 37, 132, 3920, 'Indeed, he was of Our believing servants.', NULL, NULL, 'e96d3c63ea2de2fddfb72e1284ab6cd4804c64edb23df9b1e2af1fda7a3e18e2'),
  ('en.sahih', 37, 133, 3921, 'And indeed, Lot was among the messengers.', NULL, NULL, '92c5b2004a6a1a58bd48edf9f9fbf671d1006344b9163a2315ce60e779d963fc'),
  ('en.sahih', 37, 134, 3922, '[So mention] when We saved him and his family, all,', NULL, NULL, '0c341ae6ae60cd21d87be40b96be3f6d7cc604d7ad0f647d3d10be6f9bb87459'),
  ('en.sahih', 37, 135, 3923, 'Except his wife among those who remained [with the evildoers].', NULL, NULL, '940a381219c05c07d93292677a68341b31bc3e30f0afc28be523ff3a0b4f1cdc'),
  ('en.sahih', 37, 136, 3924, 'Then We destroyed the others.', NULL, NULL, '34d8d6508e2f142b554ebf95d58419d50d2903808418fc10800ec676cbbb5b57'),
  ('en.sahih', 37, 137, 3925, 'And indeed, you pass by them in the morning', NULL, NULL, '80483c64a80cdb3e596d7d803402147a2fbfe189b89f30284f23a5945e2f3f33'),
  ('en.sahih', 37, 138, 3926, 'And at night. Then will you not use reason?', NULL, NULL, '428596b4ae109f8fc61b0e093a21e1c320fd17189205931fc8a4d614017f2360'),
  ('en.sahih', 37, 139, 3927, 'And indeed, Jonah was among the messengers.', NULL, NULL, '06ad8b7846896338a1de2777efbc101456fd51829bcaff9a64854b4d236eebb8'),
  ('en.sahih', 37, 140, 3928, '[Mention] when he ran away to the laden ship.', NULL, NULL, '611b5e1440f7f3685e51a6420a400e0928698ebb8138413c4e21fbb416d5d4f7'),
  ('en.sahih', 37, 141, 3929, 'And he drew lots and was among the losers.', NULL, NULL, 'ec44c83d1cc54c07e504af16032c55c3181977035a5e7f82f8d635e15797fb3f'),
  ('en.sahih', 37, 142, 3930, 'Then the fish swallowed him, while he was blameworthy.', NULL, NULL, '3dc2dfe9c86f0167c3647843fd65f1874ea33ee85e91a6630ea5533650db3368'),
  ('en.sahih', 37, 143, 3931, 'And had he not been of those who exalt Allah,', NULL, NULL, 'f3cb9e1fbc30440465e959b0703886e07323b2c63808d7279d596b5754a2e208'),
  ('en.sahih', 37, 144, 3932, 'He would have remained inside its belly until the Day they are resurrected.', NULL, NULL, 'ac8aca60b8d5b4a7a143bda71073e9f54d56e8104241b6c41a0697703b2c1f6b'),
  ('en.sahih', 37, 145, 3933, 'But We threw him onto the open shore while he was ill.', NULL, NULL, '232f0efa720298633b00597ed39908fcfba71a105d4418e483eea965bb1d56f9'),
  ('en.sahih', 37, 146, 3934, 'And We caused to grow over him a gourd vine.', NULL, NULL, 'b994e7a52bdb1d906b6a570dec2c532c24715c28183a4d732d2df25bbf811136'),
  ('en.sahih', 37, 147, 3935, 'And We sent him to [his people of] a hundred thousand or more.', NULL, NULL, '6d297ee116b157401bf59b7decea9af6783f7c6b2b848ea03c8ae516c6cf69c8'),
  ('en.sahih', 37, 148, 3936, 'And they believed, so We gave them enjoyment [of life] for a time.', NULL, NULL, 'd733fc21376bd9e76a741b0c96924fb0c9eddb2a149e8ca9d758d6f467a2558a'),
  ('en.sahih', 37, 149, 3937, 'So inquire of them, [O Muhammad], "Does your Lord have daughters while they have sons?', NULL, NULL, '096b33258274288cb3b52c814ec4d35182edd47af1665f00ae82546acf369351'),
  ('en.sahih', 37, 150, 3938, 'Or did We create the angels as females while they were witnesses?"', NULL, NULL, '29449d98269996f1e75c760f93fe2406893f584962a89e65c276589a267a2204'),
  ('en.sahih', 37, 151, 3939, 'Unquestionably, it is out of their [invented] falsehood that they say,', NULL, NULL, '83938da70484101bed50e444006b90a10c5bc1c67c9e39f9c4b0d6086f1499c9'),
  ('en.sahih', 37, 152, 3940, '" Allah has begotten," and indeed, they are liars.', NULL, NULL, '9a7ee7a6e60ebb877f997067059a10e4d37f8bc5662b6d165f622fa2dffafc8d'),
  ('en.sahih', 37, 153, 3941, 'Has He chosen daughters over sons?', NULL, NULL, 'e8d82c7ed8e4bb48881fb407a75f86a3a4bab78aa24d27a58c497a805c62f01a'),
  ('en.sahih', 37, 154, 3942, 'What is [wrong] with you? How do you make judgement?', NULL, NULL, '048d5e350c3e40966b1eff4e337f169953ad898284fa4b5796be0c178115ab8c'),
  ('en.sahih', 37, 155, 3943, 'Then will you not be reminded?', NULL, NULL, '8cb6f4e4dbddd9fca521010cee992b9e4f67a5d508da632e8107b11b9addd97f'),
  ('en.sahih', 37, 156, 3944, 'Or do you have a clear authority?', NULL, NULL, 'ae2d153a83bb43a89241e28b1e2d22fd56b6c664c6c122a030be00ca9cadb9dc'),
  ('en.sahih', 37, 157, 3945, 'Then produce your scripture, if you should be truthful.', NULL, NULL, '2ba0d9e9c2c3b4ab3861605f10d36c1335173d80f621b4958fbef4fee1dca397'),
  ('en.sahih', 37, 158, 3946, 'And they have claimed between Him and the jinn a lineage, but the jinn have already known that they [who made such claims] will be brought to [punishment].', NULL, NULL, '2b7467a2fc7e9f47514c6bc339600b932397905f154cbe1fb24ea7b530b4f976'),
  ('en.sahih', 37, 159, 3947, 'Exalted is Allah above what they describe,', NULL, NULL, '291cac3a977cc8aa7eb556ff0649d6e0c9e321e4bd835f075d44690597d46ac9'),
  ('en.sahih', 37, 160, 3948, 'Except the chosen servants of Allah [who do not share in that sin].', NULL, NULL, '118380405c9c76a23dd012d1d40c6f2679278091dae641be64bbfea9f04de8e3'),
  ('en.sahih', 37, 161, 3949, 'So indeed, you [disbelievers] and whatever you worship,', NULL, NULL, '1e81c9954a8de711cb41a992c9455f471b5b70d31e4c9b713ead47e6cee7aaed'),
  ('en.sahih', 37, 162, 3950, 'You cannot tempt [anyone] away from Him', NULL, NULL, 'fcee398dc022db288fb57f17748df3fc2874e54bdffe7b03b934570365c4a559'),
  ('en.sahih', 37, 163, 3951, 'Except he who is to [enter and] burn in the Hellfire.', NULL, NULL, '50e7bd71fee3f79733d59c0c8e082b42ec9b5a89cc4bfc44b09163f18937b3f8'),
  ('en.sahih', 37, 164, 3952, '[The angels say], "There is not among us any except that he has a known position.', NULL, NULL, 'a02b21bcb1e8ab12ecc7bc47c829f1b5bf1ca50ef8635d12cc3633829b20dfd5'),
  ('en.sahih', 37, 165, 3953, 'And indeed, we are those who line up [for prayer].', NULL, NULL, '3f29b0b25ced02496ddb3ff846a0661ea4bd5f80c13f6c2b023823129522fa63'),
  ('en.sahih', 37, 166, 3954, 'And indeed, we are those who exalt Allah."', NULL, NULL, 'f1e75127e9d8f417cea2765cddf983c93abc3075ee28d7ce7cc8be0d61f51f6b'),
  ('en.sahih', 37, 167, 3955, 'And indeed, the disbelievers used to say,', NULL, NULL, '6451aa9c131b813b78219f8f526dfde0c2fc1b622894f1f82f61f4e99f7d6ae2'),
  ('en.sahih', 37, 168, 3956, '"If we had a message from [those of] the former peoples,', NULL, NULL, '834b81583a694d2ef558e1745dcb6abd70501ae54b95ef2c2a6fca5e9a92c449'),
  ('en.sahih', 37, 169, 3957, 'We would have been the chosen servants of Allah."', NULL, NULL, 'aa94dcbc5f63c1e998c287e81eaee213c5385f6cda868725b39c8d225bc7d5a5'),
  ('en.sahih', 37, 170, 3958, 'But they disbelieved in it, so they are going to know.', NULL, NULL, 'f7b439c77d308fd3169c9101387a045d102391de67b1d942133fa2c68842dd07'),
  ('en.sahih', 37, 171, 3959, 'And Our word has already preceded for Our servants, the messengers,', NULL, NULL, 'eecbcda9e18d784cacb59b1f64bbf3e5c28d9412a4cc7ba6bea85588e950a861'),
  ('en.sahih', 37, 172, 3960, '[That] indeed, they would be those given victory', NULL, NULL, '75d4252c377a11f282af1fda3dd57053d5d6d32d665a1e9beec0cb58ae7f4e96'),
  ('en.sahih', 37, 173, 3961, 'And [that] indeed, Our soldiers will be those who overcome.', NULL, NULL, '42c1b22fcbae912c0ad5c4d827ab50de136129047ca0604ebf727e95be4592ef'),
  ('en.sahih', 37, 174, 3962, 'So, [O Muhammad], leave them for a time.', NULL, NULL, 'df747f974b9e83a1a823d8a0e449241e46c1db44a711a765be126f99cb5df282'),
  ('en.sahih', 37, 175, 3963, 'And see [what will befall] them, for they are going to see.', NULL, NULL, 'c0d768f264f9ac53724da7db083eb00c30413d772b615a17a90bea83fe188436'),
  ('en.sahih', 37, 176, 3964, 'Then for Our punishment are they impatient?', NULL, NULL, '256c2cfbf3cc83eae9b054d466e20ab989359bfca0906eaaa0310505a9ca9492'),
  ('en.sahih', 37, 177, 3965, 'But when it descends in their territory, then evil is the morning of those who were warned.', NULL, NULL, 'dca8c8b4bd4b6f71aacc18145668b41c0f32291ecb12b859d189ac1a7e582943'),
  ('en.sahih', 37, 178, 3966, 'And leave them for a time.', NULL, NULL, '903833a21ab1fa84e20563f99afbf86f9f766089db6ab6125d8e6fb3d6490aaf'),
  ('en.sahih', 37, 179, 3967, 'And see, for they are going to see.', NULL, NULL, 'f6c53329ca799bbac36df3efd15b3964a697da195630139417e25270985bed98'),
  ('en.sahih', 37, 180, 3968, 'Exalted is your Lord, the Lord of might, above what they describe.', NULL, NULL, 'a13b720244d63e4df3fdd826c9fd71a12fa7c54865510e0e33f278bd79159bfa'),
  ('en.sahih', 37, 181, 3969, 'And peace upon the messengers.', NULL, NULL, 'edd0731dce163338e8339bd1faa0ed697afbfe3bc5b7fec0d464fcb963ed3bf4'),
  ('en.sahih', 37, 182, 3970, 'And praise to Allah, Lord of the worlds.', NULL, NULL, '1579cee1d925dd4221fc5228a680ee3596b7012548a4d1bdb1d5aa382c624aca'),
  ('en.sahih', 38, 1, 3971, 'Sad. By the Qur''an containing reminder...', NULL, NULL, 'a5f6cb2f869568441c91d0a99b74871a9fb0b2cb60cadcb6ae7370a94b40e2ec'),
  ('en.sahih', 38, 2, 3972, 'But those who disbelieve are in pride and dissension.', NULL, NULL, 'aa617d63b0cf42fd0d8036c0808a6947f12744efbe0469d8876ee7ca13499328'),
  ('en.sahih', 38, 3, 3973, 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.', NULL, NULL, '725f38fb08598352d7bf5ee3d7c6fe605423306882c6fd420e35e31290d148fc'),
  ('en.sahih', 38, 4, 3974, 'And they wonder that there has come to them a warner from among themselves. And the disbelievers say, "This is a magician and a liar.', NULL, NULL, '0e83d7dca79a8e662e31a21365720dec1967dd37e52903a6d9152802437fa638'),
  ('en.sahih', 38, 5, 3975, 'Has he made the gods [only] one God? Indeed, this is a curious thing."', NULL, NULL, '031280b7c1223cd90c61953621df33f5d67d73abe9560f49179477cf664e567f'),
  ('en.sahih', 38, 6, 3976, 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.', NULL, NULL, '3abe92d11bf01cfc730d4a92f1a204e87727c7d44c0d543066bbd4b8a3e7f56b'),
  ('en.sahih', 38, 7, 3977, 'We have not heard of this in the latest religion. This is not but a fabrication.', NULL, NULL, 'f7347995cddafb25da96932caa0c63db71b61abf972c3319db973df221cdd049'),
  ('en.sahih', 38, 8, 3978, 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.', NULL, NULL, 'd2f9885588ba6c6cfb40a2f1efaf638903375dafeaa3d5e80abdc0ac9b8752c1'),
  ('en.sahih', 38, 9, 3979, 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?', NULL, NULL, '1b16a33d44810170ed250d560c13fea28e55a4411a68c95f24a753b3dec2f17a'),
  ('en.sahih', 38, 10, 3980, 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.', NULL, NULL, 'c50bbad0c6f189595a7287ffdaf142a6308ba19d3a485d2e0c41fbd4bbaea910'),
  ('en.sahih', 38, 11, 3981, '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].', NULL, NULL, 'a3d80d35034c9e1187f9ef3d2488a6c2cf331ea232f037a37abe448086f58533'),
  ('en.sahih', 38, 12, 3982, 'The people of Noah denied before them, and [the tribe of] ''Aad and Pharaoh, the owner of stakes,', NULL, NULL, '325944f8019ee75a72d497ec7f20fae2442c524d8f332b7b45eed2a97477b005'),
  ('en.sahih', 38, 13, 3983, 'And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies.', NULL, NULL, 'f455642487ce26fbb74a9b79e34fe7d95e019c0d4099f5c1b3880f7c017c70a7'),
  ('en.sahih', 38, 14, 3984, 'Each of them denied the messengers, so My penalty was justified.', NULL, NULL, '21bfa401d0daf546d1a82e164d41f63c0b6a91e93a48490e4405fa55d10698e5'),
  ('en.sahih', 38, 15, 3985, 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.', NULL, NULL, '28a66cc228627162ddac62e2d1defd86fe2ba1ddb70291d30b21c832a04d570e'),
  ('en.sahih', 38, 16, 3986, 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account"', NULL, NULL, '6c5aa746ff1730bc0c90c1b05b0c329ebc7d7076c8d2b611541e67889b090e11'),
  ('en.sahih', 38, 17, 3987, 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah].', NULL, NULL, 'ef0b2d8095de8a2f480183c2bede8ef463ce7768d17eb3d171bacc8e64c75bb8'),
  ('en.sahih', 38, 18, 3988, 'Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise.', NULL, NULL, '8de4c4c5b5c1aba6aa29098607cb2d11e23db1d6cf4fd193e744617573c8966f'),
  ('en.sahih', 38, 19, 3989, 'And the birds were assembled, all with him repeating [praises].', NULL, NULL, '41ca3568737d8431887ef8188714bdca8e20f62491850f4cbfb69e78d8b35873'),
  ('en.sahih', 38, 20, 3990, 'And We strengthened his kingdom and gave him wisdom and discernment in speech.', NULL, NULL, 'ce6bc02a355587a2e0ce99422859f5d2d61f455bb321de49d59c98128df28289'),
  ('en.sahih', 38, 21, 3991, 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -', NULL, NULL, '38b9c65f8fe9d6024e7a1e00144bbabe0d23c12c76e9fe05f324d3d37f7ef89e'),
  ('en.sahih', 38, 22, 3992, 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.', NULL, NULL, 'ef4d4c9d4971b3571e118f2aa39bf6131db504b664a9c06f756f6fcc192044d8'),
  ('en.sahih', 38, 23, 3993, 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, ''Entrust her to me,'' and he overpowered me in speech."', NULL, NULL, '2a5ea6c35d94c5896f4b585e3e03ad59594de8e8920890d7b9b33c33ab6da029'),
  ('en.sahih', 38, 24, 3994, '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah].', NULL, NULL, 'aa8098a448089e8fa00bf3fb8dfe21c0e9abff700caf7946f97cdf93bce1c325'),
  ('en.sahih', 38, 25, 3995, 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.', NULL, NULL, 'ee36954ba4e806606234feb847a14aabf3cfa1d9862a83015f9899d9622ffeb1'),
  ('en.sahih', 38, 26, 3996, '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah." Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account.', NULL, NULL, 'ed96c2a7207872e494c134c53d33cd79fd0f72fa6f261f21e91b3cb190f0cd8c'),
  ('en.sahih', 38, 27, 3997, 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.', NULL, NULL, 'fd7468074fead8e9500c3f9e8b71e7e06c1bd8650ccdb2cd7617dda68c62f916'),
  ('en.sahih', 38, 28, 3998, 'Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?', NULL, NULL, '4a5ccbc66811ba3c05ab4d15f63244902940f191eb55b52f62207feed21b80fb'),
  ('en.sahih', 38, 29, 3999, '[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded.', NULL, NULL, 'c513479d3c068558bc1588c58de1fe030c785f0e6829783039aedff4e6e3a979'),
  ('en.sahih', 38, 30, 4000, 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah].', NULL, NULL, 'f92ebb8ea7ce52157b91654da495c69948ff8636a084f53d73ca5f27a0eecd0b')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 38, 31, 4001, '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.', NULL, NULL, 'c6c4090246d9eaa14e8212739da8b114b08d0b9f190cc4ae248ee1b9a6c7296f'),
  ('en.sahih', 38, 32, 4002, 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness]."', NULL, NULL, '704bb929d4a2f34272615077458a3823da01c1d21608c3e9002b57fb4b631f31'),
  ('en.sahih', 38, 33, 4003, '[He said], "Return them to me," and set about striking [their] legs and necks.', NULL, NULL, 'a12500a589d41052427c7de3f259bced04c58c9f1eb324da6c5efd2e904b016f'),
  ('en.sahih', 38, 34, 4004, 'And We certainly tried Solomon and placed on his throne a body; then he returned.', NULL, NULL, '662e57202388a0ecbff9a1a33352d34094e887108ca5593f1f2f42946291609a'),
  ('en.sahih', 38, 35, 4005, 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."', NULL, NULL, 'bd616f82b15d9f50e867ed7427b84b60db2e0215dd6e4af1ff299c67af14bf59'),
  ('en.sahih', 38, 36, 4006, 'So We subjected to him the wind blowing by his command, gently, wherever he directed,', NULL, NULL, '3650c47f511fe82625b41a7f4695e84572a68eeffc637d017ba2c55b86578771'),
  ('en.sahih', 38, 37, 4007, 'And [also] the devils [of jinn] - every builder and diver', NULL, NULL, '9ad4cb30dccb8f1303ae5cdc3915d3869a5373efb0fe05c2caaa5d89171fa3fc'),
  ('en.sahih', 38, 38, 4008, 'And others bound together in shackles.', NULL, NULL, '61089865752df65527055e12f289173f6c5caecc1acc8fcb76f9a231c16f3960'),
  ('en.sahih', 38, 39, 4009, '[We said], "This is Our gift, so grant or withhold without account."', NULL, NULL, '1002f2ccc56dc931e8c4d0e6c4c7be2db9ffa44680f291021afd1462a6d1e05c'),
  ('en.sahih', 38, 40, 4010, 'And indeed, for him is nearness to Us and a good place of return.', NULL, NULL, 'ce1f91ad094736349dd6e64d70b616c291273672ddafe996487595828707037e'),
  ('en.sahih', 38, 41, 4011, 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."', NULL, NULL, '7a05d95708897f8ed56c40206ab403dfd781f986292e7bc477759531b2ebb951'),
  ('en.sahih', 38, 42, 4012, '[So he was told], "Strike [the ground] with your foot; this is a [spring for] a cool bath and drink."', NULL, NULL, '84f02b46c62bc6200808511b23700c64efd156536449547f109e8a2d4c17775b'),
  ('en.sahih', 38, 43, 4013, 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.', NULL, NULL, 'eceb3e3ca26138f6321cb98d58287f6581b794cb53ea22a8800e4c156fe86631'),
  ('en.sahih', 38, 44, 4014, '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah].', NULL, NULL, 'aeae35088a04d3cacf3aeeeb75d3b18d0a9d1d1327842ed3c6ae15ff03e70958'),
  ('en.sahih', 38, 45, 4015, 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.', NULL, NULL, '6fd150306f9f7cd49201a4ee768f4ab0a1bf88ba7d46d8d05a7708031fb51ed5'),
  ('en.sahih', 38, 46, 4016, 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].', NULL, NULL, '6b6b8e4e8eb8f9c28d64ccc519d38ef95f077281f557a8a846c3ec51d65b892e'),
  ('en.sahih', 38, 47, 4017, 'And indeed they are, to Us, among the chosen and outstanding.', NULL, NULL, '26b3a7553775245a2f36dd8dd9e4ff260848a6dd8672f10ce7142d1f8d43ff4a'),
  ('en.sahih', 38, 48, 4018, 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.', NULL, NULL, '84d21db032beef350c23860680ac54ef31f161afcc21320e999b189c9ec52146'),
  ('en.sahih', 38, 49, 4019, 'This is a reminder. And indeed, for the righteous is a good place of return', NULL, NULL, '17a8d5c96d964542d1a335a29c3624a7a9ccda4f3cd2975c2db5b8ce4e0f6f12'),
  ('en.sahih', 38, 50, 4020, 'Gardens of perpetual residence, whose doors will be opened to them.', NULL, NULL, 'efa95f52b8953d7f061f27c4d7509e1e756f32483a31645edf44bc79a1e65f67'),
  ('en.sahih', 38, 51, 4021, 'Reclining within them, they will call therein for abundant fruit and drink.', NULL, NULL, '52f6a95ddfccd2405ee1f77ff67c310cb6add39c422147febc1007d1e693c6b7'),
  ('en.sahih', 38, 52, 4022, 'And with them will be women limiting [their] glances and of equal age.', NULL, NULL, '2729c9e574e8b2368197008811e7465275f7fc8dedca7789435f74ef1ffc4bdb'),
  ('en.sahih', 38, 53, 4023, 'This is what you, [the righteous], are promised for the Day of Account.', NULL, NULL, '481e2c07cea3779a0f115fe2382360e6748b07ed1c0cd9d489b7965bf08ad4d6'),
  ('en.sahih', 38, 54, 4024, 'Indeed, this is Our provision; for it there is no depletion.', NULL, NULL, '65800ec3764dd5ea89bc8d2a03878c7b7456cfaf93904b614174849fd982ff70'),
  ('en.sahih', 38, 55, 4025, 'This [is so]. But indeed, for the transgressors is an evil place of return -', NULL, NULL, 'e1f79e7e4fda9377fb1fa0ce15f395093033c24aba39dfcd972680dd17fd2e16'),
  ('en.sahih', 38, 56, 4026, 'Hell, which they will [enter to] burn, and wretched is the resting place.', NULL, NULL, '1c4439fffc8716481232bdab1f19799ac1da59be3f0693daebf8c265c3b12239'),
  ('en.sahih', 38, 57, 4027, 'This - so let them taste it - is scalding water and [foul] purulence.', NULL, NULL, '8e8b874137df790e4426cbfcc756b634d778ab8e89fe48cf45048dcce6c56c58'),
  ('en.sahih', 38, 58, 4028, 'And other [punishments] of its type [in various] kinds.', NULL, NULL, '86ac98435fc4e18c2dd212808cb4d51f7ecd31fab1e81294568c153397f37e26'),
  ('en.sahih', 38, 59, 4029, '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."', NULL, NULL, 'e4e74b9902ae393cf89fc3b09ab9725d0cfbca9a38d1c350143dac931044d673'),
  ('en.sahih', 38, 60, 4030, 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."', NULL, NULL, '44823b69d285e5c3e9f0b07ba2740c596a9f539e39f1ba431253f0053bc110e8'),
  ('en.sahih', 38, 61, 4031, 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."', NULL, NULL, '56f64b66b521aea67a162aca19d3dab3de926e9e537b8abec43b79059a525459'),
  ('en.sahih', 38, 62, 4032, 'And they will say, "Why do we not see men whom we used to count among the worst?', NULL, NULL, '10a38eae5116aa555045ca98a19daf0a526d3d3b1102f4946a8ca98bb4b29fdd'),
  ('en.sahih', 38, 63, 4033, 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"', NULL, NULL, '60908dc540eeaf720e372182bdaf38c59958d03024da79358e8f1975f9b5350b'),
  ('en.sahih', 38, 64, 4034, 'Indeed, that is truth - the quarreling of the people of the Fire.', NULL, NULL, '80b07faae9abfd150a23713b663c353f7f5ba2311c5d473dc4dea458b7353473'),
  ('en.sahih', 38, 65, 4035, 'Say, [O Muhammad], "I am only a warner, and there is not any deity except Allah, the One, the Prevailing.', NULL, NULL, '0241a8d2d0c2defebc5c5c5f33ebe2fc33986457d18844acba6605acc94f8a41'),
  ('en.sahih', 38, 66, 4036, 'Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver."', NULL, NULL, 'e5e1fc1eb1dfade36214a9617f367c48d38c9ebd34a65d81486c90b9a0c5f99e'),
  ('en.sahih', 38, 67, 4037, 'Say, "It is great news', NULL, NULL, 'd082414425ee7cce3b1ac21d5dee93761ce54bfb1e905f1686bece42f6f259f7'),
  ('en.sahih', 38, 68, 4038, 'From which you turn away.', NULL, NULL, '865825b90b0f0ebaec408fcaeb97569cc70ea868ed17ab59276a9024adaa6d6d'),
  ('en.sahih', 38, 69, 4039, 'I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam].', NULL, NULL, '336bae364849c17011f13c8012db2a97d44222d798d762fb326b52b0525baa32'),
  ('en.sahih', 38, 70, 4040, 'It has not been revealed to me except that I am a clear warner."', NULL, NULL, 'e7307215ab124dbcf7868976f067a757dee01ff8c0f1e7a50af7eb01a7baa08e'),
  ('en.sahih', 38, 71, 4041, '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.', NULL, NULL, '0854f653aa04e0433dcdac0789f19b7a50c898aab0b6090f179e895dff58ddfb'),
  ('en.sahih', 38, 72, 4042, 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."', NULL, NULL, '8f746c0d5166a68c4e07e85ffb9d64d6c4c532aa9e9e02539983e41f1fdb30fc'),
  ('en.sahih', 38, 73, 4043, 'So the angels prostrated - all of them entirely.', NULL, NULL, '00e67a73525569189e67f7cd1714573e2f9a71c424f24064aeab9e46c924115e'),
  ('en.sahih', 38, 74, 4044, 'Except Iblees; he was arrogant and became among the disbelievers.', NULL, NULL, '64fa14d7497f5cad41a4fec77faedef86ed836d77224c19ac0ef4df5226315aa'),
  ('en.sahih', 38, 75, 4045, '[Allah] said, "O Iblees, what prevented you from prostrating to that which I created with My hands? Were you arrogant [then], or were you [already] among the haughty?"', NULL, NULL, '24e2b75d9cbb9fb9f2fff36b286f072e87ee1c77887472a4858e4b73d6072bee'),
  ('en.sahih', 38, 76, 4046, 'He said, "I am better than him. You created me from fire and created him from clay."', NULL, NULL, '68ea27ece56766df1b8d9b1fe17b874b219a098d751ed8bb848d1f5a4d1e4dee'),
  ('en.sahih', 38, 77, 4047, '[Allah] said, "Then get out of Paradise, for indeed, you are expelled.', NULL, NULL, '752943ee64c4a040ba7b38803c0033e3bbfa775b1377eaca709264079739219d'),
  ('en.sahih', 38, 78, 4048, 'And indeed, upon you is My curse until the Day of Recompense."', NULL, NULL, 'bdf9a4b8df799d16b4e1d37bb6a3eacc6dc4102dd63fde4922848367cd8c7d0a'),
  ('en.sahih', 38, 79, 4049, 'He said, "My Lord, then reprieve me until the Day they are resurrected."', NULL, NULL, 'e70cd5c25cabaa6ab26287180416d0aa62ea8435768c53f59259531827dfcc02'),
  ('en.sahih', 38, 80, 4050, '[Allah] said, "So indeed, you are of those reprieved', NULL, NULL, 'f131cae6d883e68d89f3dabb05adc2c8f790c568ad66d9e0df3a98ae6a64e398'),
  ('en.sahih', 38, 81, 4051, 'Until the Day of the time well-known."', NULL, NULL, '37ff67a273925e0c6c477e6bb04b9b6d920147c26c501b4d55e83785a98c18f0'),
  ('en.sahih', 38, 82, 4052, '[Iblees] said, "By your might, I will surely mislead them all', NULL, NULL, '809a9abd57322b711710e23d6412084d7ce0ee5148cf5cf1dade4d27821988f7'),
  ('en.sahih', 38, 83, 4053, 'Except, among them, Your chosen servants."', NULL, NULL, 'e415bfc577fdb823d643335ed26d99205a43998813c84868200bc1e0c6032291'),
  ('en.sahih', 38, 84, 4054, '[Allah] said, "The truth [is My oath], and the truth I say -', NULL, NULL, 'c1c61117cccf16899a29e20ea20904f52fbd21c2aeb361c34757f64f3ae4b1e8'),
  ('en.sahih', 38, 85, 4055, '[That] I will surely fill Hell with you and those of them that follow you all together."', NULL, NULL, 'e57db9ffdfc866adddf83098ed42a8057cc94c20d83058de6da655c6a549cac8'),
  ('en.sahih', 38, 86, 4056, 'Say, [O Muhammad], "I do not ask you for the Qur''an any payment, and I am not of the pretentious', NULL, NULL, '70dada1962dbc56a6c06fab4b033b0858efb9279758090a045cc75f45cb0f5c3'),
  ('en.sahih', 38, 87, 4057, 'It is but a reminder to the worlds.', NULL, NULL, '527d2843b0f90c930c34a2f810c2838babfd7e03367a92576f1cb94ea75dfbfb'),
  ('en.sahih', 38, 88, 4058, 'And you will surely know [the truth of] its information after a time."', NULL, NULL, '6380b7b7064e7b64863f5c19a329a5fec3f282972b344e60aec4df3c90a77ba5'),
  ('en.sahih', 39, 1, 4059, 'The revelation of the Qur''an is from Allah, the Exalted in Might, the Wise.', NULL, NULL, 'f5930c65de2f3062093e3e63e3883c9c00f594d84568f3dcc30a8cdcb02ec4d0'),
  ('en.sahih', 39, 2, 4060, 'Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion.', NULL, NULL, 'd096ac40c5e8f2a980fe8a91915803fcaddec0538d0a4a4e8e4b2abd5f5b93e9'),
  ('en.sahih', 39, 3, 4061, 'Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allah in position." Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever.', NULL, NULL, '1d7eeff7f4523f2559bea0ccedafb52daba68d9c622bf5b296402857dd82b433'),
  ('en.sahih', 39, 4, 4062, 'If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing.', NULL, NULL, 'a14e06b0b8d2ea80924272861ef6877818e149265b62915ac2af567bd5c48ad3'),
  ('en.sahih', 39, 5, 4063, 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.', NULL, NULL, '1ee34d2adaddaaccac58d00691d39014ab4f1e70d6e89e15981218113663450a'),
  ('en.sahih', 39, 6, 4064, 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?', NULL, NULL, 'fbfceaccb33430e305bc317781a0834a1f6d846a7e57175a48200567b9dcbcb3'),
  ('en.sahih', 39, 7, 4065, 'If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.', NULL, NULL, 'd7eb472824cd98fd9996b761304478876f6d8c11ae176a854eb39c547dfb2151'),
  ('en.sahih', 39, 8, 4066, 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."', NULL, NULL, '66bc58ed854601b30283910182c7af289b1cef8b69ee614dcf1c35666dda8d3f'),
  ('en.sahih', 39, 9, 4067, 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.', NULL, NULL, 'a3b5c46d6e99fee29df6b4f925fffdcf56eb224ebdd538383a35d4578ae3b0e6'),
  ('en.sahih', 39, 10, 4068, 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account."', NULL, NULL, '03792a9c78e5190eea67e55aa64f7af0f62ad91b648d1096efa9ab1e1f6e78bc'),
  ('en.sahih', 39, 11, 4069, 'Say, [O Muhammad], "Indeed, I have been commanded to worship Allah, [being] sincere to Him in religion.', NULL, NULL, '07e665bed9feb7b1f5d2bb9304944f8fc1ab2c9a3286163fcea5ad2353c3b094'),
  ('en.sahih', 39, 12, 4070, 'And I have been commanded to be the first [among you] of the Muslims."', NULL, NULL, '62aaae64f554d4548082a24607baf360e0945cfee5aa4399a5dc8356a7f4e465'),
  ('en.sahih', 39, 13, 4071, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."', NULL, NULL, '280f56573651c116aa611bde5937784253114a05e2b501c558b31f401296d6fc'),
  ('en.sahih', 39, 14, 4072, 'Say, "Allah [alone] do I worship, sincere to Him in my religion,', NULL, NULL, '6ce2ad1f7a2875fa82a1193f1ed59958aa94c724f28973b8d3d9bbc4060a2aa9'),
  ('en.sahih', 39, 15, 4073, 'So worship what you will besides Him." Say, "Indeed, the losers are the ones who will lose themselves and their families on the Day of Resurrection. Unquestionably, that is the manifest loss."', NULL, NULL, 'b8b9061db4efbac3e612a7241b2965d2ee8f59bb9258d7d96acda3c19efd04ef'),
  ('en.sahih', 39, 16, 4074, 'They will have canopies of fire above them and below them, canopies. By that Allah threatens His servants. O My servants, then fear Me.', NULL, NULL, 'a510cfef8a5b3e88ba5e39441c73775c5044e88c6c9ed86faa79e7a985de0730'),
  ('en.sahih', 39, 17, 4075, 'But those who have avoided Taghut, lest they worship it, and turned back to Allah - for them are good tidings. So give good tidings to My servants', NULL, NULL, '0f8393dece206740fade569e887e019c37ce963e2dbf69350745c0b7e8e7db6e'),
  ('en.sahih', 39, 18, 4076, 'Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding.', NULL, NULL, 'c366bf473b1ce9b5d4373998a64aadb38291b2637549d27bf410b0f94fe01448'),
  ('en.sahih', 39, 19, 4077, 'Then, is one who has deserved the decree of punishment [to be guided]? Then, can you save one who is in the Fire?', NULL, NULL, '0b0e9483d1a0e01d756c0db2d972172788e44bc5fbb8a4acfde6ddde2946f3ac'),
  ('en.sahih', 39, 20, 4078, 'But those who have feared their Lord - for them are chambers, above them chambers built high, beneath which rivers flow. [This is] the promise of Allah. Allah does not fail in [His] promise.', NULL, NULL, 'd3cc8564d6a140d5b32a6714698f835200cef32c65f6b068496fd6041032165f'),
  ('en.sahih', 39, 21, 4079, 'Do you not see that Allah sends down rain from the sky and makes it flow as springs [and rivers] in the earth; then He produces thereby crops of varying colors; then they dry and you see them turned yellow; then He makes them [scattered] debris. Indeed in that is a reminder for those of understanding.', NULL, NULL, '31abf543d851eed0ce1efa2d5a43ef85d16020e75b6f8699913db4377547072f'),
  ('en.sahih', 39, 22, 4080, 'So is one whose breast Allah has expanded to [accept] Islam and he is upon a light from his Lord [like one whose heart rejects it]? Then woe to those whose hearts are hardened against the remembrance of Allah. Those are in manifest error.', NULL, NULL, '76e43d35994cc5b955b30c8e55b2193dc72b55130871a7766ed2c50d2a25dd10'),
  ('en.sahih', 39, 23, 4081, 'Allah has sent down the best statement: a consistent Book wherein is reiteration. The skins shiver therefrom of those who fear their Lord; then their skins and their hearts relax at the remembrance of Allah. That is the guidance of Allah by which He guides whom He wills. And one whom Allah leaves astray - for him there is no guide.', NULL, NULL, '83380588c79674f601a2984b32ec2217586a9e9744a4c94d14ec85c8cf87cd7c'),
  ('en.sahih', 39, 24, 4082, 'Then is he who will shield with his face the worst of the punishment on the Day of Resurrection [like one secure from it]? And it will be said to the wrongdoers, "Taste what you used to earn."', NULL, NULL, '64f0e4f648ddd56d9df779324ce1227593dc8cdd6aeb9af8972bbe9f8cbf409c'),
  ('en.sahih', 39, 25, 4083, 'Those before them denied, and punishment came upon them from where they did not perceive.', NULL, NULL, 'cce794f574df86e7bc524fc394a791a2c9f1dc30d91eedb901a9ca26758af631'),
  ('en.sahih', 39, 26, 4084, 'So Allah made them taste disgrace in worldly life. But the punishment of the Hereafter is greater, if they only knew.', NULL, NULL, 'ee3d259ba70931b113c3834879c297d09f2291cc5d48be7ca890d38946f7bec5'),
  ('en.sahih', 39, 27, 4085, 'And We have certainly presented for the people in this Qur''an from every [kind of] example - that they might remember.', NULL, NULL, '2bf6c1a3012b520eded82661391b7344b5f707f64d4f499bcb4587c554d9c074'),
  ('en.sahih', 39, 28, 4086, '[It is] an Arabic Qur''an, without any deviance that they might become righteous.', NULL, NULL, '2ab74102debba3e3ec668f682b6220b8672693fc6f443dc83c26a3724a7618b3'),
  ('en.sahih', 39, 29, 4087, 'Allah presents an example: a slave owned by quarreling partners and another belonging exclusively to one man - are they equal in comparison? Praise be to Allah! But most of them do not know.', NULL, NULL, 'd4deb8de50a8201db1a3fede766eaf9cd67260b2905b8d21ce3d31e048e65da5'),
  ('en.sahih', 39, 30, 4088, 'Indeed, you are to die, and indeed, they are to die.', NULL, NULL, '5b0adaaacbdf6e6c02ebc12bec994f98867c408b4d2ac3d0828d7d0ab769bb81'),
  ('en.sahih', 39, 31, 4089, 'Then indeed you, on the Day of Resurrection, before your Lord, will dispute.', NULL, NULL, '1d91fbf2debe303417e32d61024763745e616f1bfc6a04c7ba09b330e73b8658'),
  ('en.sahih', 39, 32, 4090, 'So who is more unjust than one who lies about Allah and denies the truth when it has come to him? Is there not in Hell a residence for the disbelievers?', NULL, NULL, 'ac64e4374a03076ebd2210ff400408e82de608c0b204e43d7eccd11be660bd94'),
  ('en.sahih', 39, 33, 4091, 'And the one who has brought the truth and [they who] believed in it - those are the righteous.', NULL, NULL, 'a68c5239f2506025b1e593151185249422485497898d9f2a111df61eb11bef15'),
  ('en.sahih', 39, 34, 4092, 'They will have whatever they desire with their Lord. That is the reward of the doers of good -', NULL, NULL, 'eda52cd6a7ad4fd6ec3568fe88ba8dfd68c8b79eadbf2a5b0b0cb23c23bfc515'),
  ('en.sahih', 39, 35, 4093, 'That Allah may remove from them the worst of what they did and reward them their due for the best of what they used to do.', NULL, NULL, '0157da5c7294888387c528fa4cf8de4e0d12ef0832ade31510a768833732d1a7'),
  ('en.sahih', 39, 36, 4094, 'Is not Allah sufficient for His Servant [Prophet Muhammad]? And [yet], they threaten you with those [they worship] other than Him. And whoever Allah leaves astray - for him there is no guide.', NULL, NULL, '314093de407804e6c2cd4054604d945014f776a5b503fe53e271f6ee0242b4a1'),
  ('en.sahih', 39, 37, 4095, 'And whoever Allah guides - for him there is no misleader. Is not Allah Exalted in Might and Owner of Retribution?', NULL, NULL, '3505cd7bcddb1958328a5c7355cc8d14807069daecd6378b7db78355cfbeea31'),
  ('en.sahih', 39, 38, 4096, 'And if you asked them, "Who created the heavens and the earth?" they would surely say, "Allah." Say, "Then have you considered what you invoke besides Allah? If Allah intended me harm, are they removers of His harm; or if He intended me mercy, are they withholders of His mercy?" Say, "Sufficient for me is Allah; upon Him [alone] rely the [wise] reliers."', NULL, NULL, '0d4732b7af200d8747e888d4856cee2b26ae322802311f1b770a29675c2b9725'),
  ('en.sahih', 39, 39, 4097, 'Say, "O my people, work according to your position, [for] indeed, I am working; and you are going to know', NULL, NULL, '602ddad65eaac7841cca3e73f5b433b07f7b9bb7a5d28068c8af3229cb913953'),
  ('en.sahih', 39, 40, 4098, 'To whom will come a torment disgracing him and on whom will descend an enduring punishment."', NULL, NULL, '3d53bceb826652a115c8eb4707936f71c916cfae1e1553d455fcb5c0a2feee5b'),
  ('en.sahih', 39, 41, 4099, 'Indeed, We sent down to you the Book for the people in truth. So whoever is guided - it is for [the benefit of] his soul; and whoever goes astray only goes astray to its detriment. And you are not a manager over them.', NULL, NULL, 'd0ef7148345bb6af64646be057044746564ef2af488d2e15a265ac43958291e5'),
  ('en.sahih', 39, 42, 4100, 'Allah takes the souls at the time of their death, and those that do not die [He takes] during their sleep. Then He keeps those for which He has decreed death and releases the others for a specified term. Indeed in that are signs for a people who give thought.', NULL, NULL, 'ff1d61954f2b7071891c74d2a5c1fdb05349a9d704236a0d20a6cc4f624ca6f2')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 39, 43, 4101, 'Or have they taken other than Allah as intercessors? Say, "Even though they do not possess [power over] anything, nor do they reason?"', NULL, NULL, 'e2426981239acb82b20fe3a560c4ae75fb98ac0068c8fa94cd7b169782468313'),
  ('en.sahih', 39, 44, 4102, 'Say, "To Allah belongs [the right to allow] intercession entirely. To Him belongs the dominion of the heavens and the earth. Then to Him you will be returned."', NULL, NULL, '4949eb87ceb1adab038bde502a1a5ade869571b94a481ea6327fdde64542f141'),
  ('en.sahih', 39, 45, 4103, 'And when Allah is mentioned alone, the hearts of those who do not believe in the Hereafter shrink with aversion, but when those [worshipped] other than Him are mentioned, immediately they rejoice.', NULL, NULL, '5fb2121271d745267b431b3f05b12ceacf02e114e237afbbf8258718a00c6309'),
  ('en.sahih', 39, 46, 4104, 'Say, "O Allah, Creator of the heavens and the earth, Knower of the unseen and the witnessed, You will judge between your servants concerning that over which they used to differ."', NULL, NULL, 'e111a0111138ac4b175c0dc5388009911bbe14aef7b5960c870116d178c60ec2'),
  ('en.sahih', 39, 47, 4105, 'And if those who did wrong had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby from the worst of the punishment on the Day of Resurrection. And there will appear to them from Allah that which they had not taken into account.', NULL, NULL, '39878e6db53a3c045bec43c29ae9df1c65705f3f0eebe8006682f42055cf8378'),
  ('en.sahih', 39, 48, 4106, 'And there will appear to them the evils they had earned, and they will be enveloped by what they used to ridicule.', NULL, NULL, '473e5ade0c30e01f2959192d68eb05d61d5466a669eda35c1606ec6c6d79a260'),
  ('en.sahih', 39, 49, 4107, 'And when adversity touches man, he calls upon Us; then when We bestow on him a favor from Us, he says, "I have only been given it because of [my] knowledge." Rather, it is a trial, but most of them do not know.', NULL, NULL, '2763b84986ef1531156f11627aa81c34bc89473d78b5c8fddde5c6d9e599b208'),
  ('en.sahih', 39, 50, 4108, 'Those before them had already said it, but they were not availed by what they used to earn.', NULL, NULL, '268d291158757a26c3fe2b9bb7505a7705c7627f7bf73dc9f53e76ea674db07c'),
  ('en.sahih', 39, 51, 4109, 'And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be afflicted by the evil consequences of what they earned; and they will not cause failure.', NULL, NULL, 'aeff3fa22a4f7b7b33b5f24e856307fc3e4605c9a41858f3d3375a689b5b495e'),
  ('en.sahih', 39, 52, 4110, 'Do they not know that Allah extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.', NULL, NULL, 'd4575a48bfe3369008576367fcebceee443eb03650a6d16c00df2e9a08992438'),
  ('en.sahih', 39, 53, 4111, 'Say, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."', NULL, NULL, '636fd137bafa11575a615f7c91513e24870f11ac15506ef3e2d48bf971c2ee5c'),
  ('en.sahih', 39, 54, 4112, 'And return [in repentance] to your Lord and submit to Him before the punishment comes upon you; then you will not be helped.', NULL, NULL, '8c582990f1fb917f9d69116b8daa627ed4cf063d0ceb0f10176d37d1bc891f29'),
  ('en.sahih', 39, 55, 4113, 'And follow the best of what was revealed to you from your Lord before the punishment comes upon you suddenly while you do not perceive,', NULL, NULL, '4c1eca121179083d47a9e597634fb6b08f82c162252b2b7a30e5b7cda815cb03'),
  ('en.sahih', 39, 56, 4114, 'Lest a soul should say, "Oh [how great is] my regret over what I neglected in regard to Allah and that I was among the mockers."', NULL, NULL, 'c8a8f8c50225e33bb68fa68aeb23f8b094e932b4713cb50ffaf1b01df5415df3'),
  ('en.sahih', 39, 57, 4115, 'Or [lest] it say, "If only Allah had guided me, I would have been among the righteous."', NULL, NULL, 'd4b5f867d3890f3b7369477413c9e43a7f1324d38a60116661249b912050540c'),
  ('en.sahih', 39, 58, 4116, 'Or [lest] it say when it sees the punishment, "If only I had another turn so I could be among the doers of good."', NULL, NULL, 'f37063bc6e6dabc887358d9a4d7784376ec713686ef840540636409b6684a34f'),
  ('en.sahih', 39, 59, 4117, 'But yes, there had come to you My verses, but you denied them and were arrogant, and you were among the disbelievers.', NULL, NULL, '9e5e410bfcab8ea944a3bef03cb293a51d1c14ad1d0187eb09564603bf2a79d4'),
  ('en.sahih', 39, 60, 4118, 'And on the Day of Resurrection you will see those who lied about Allah [with] their faces blackened. Is there not in Hell a residence for the arrogant?', NULL, NULL, 'c443b92ecbc823f8773a953e599e92cca7a94617ec368f04e8406d6549b51a56'),
  ('en.sahih', 39, 61, 4119, 'And Allah will save those who feared Him by their attainment; no evil will touch them, nor will they grieve.', NULL, NULL, 'eb2e5dd118f62d1425a555e9d666f7f3aa4b873995fd572a1594a99dbd2c07ce'),
  ('en.sahih', 39, 62, 4120, 'Allah is the Creator of all things, and He is, over all things, Disposer of affairs.', NULL, NULL, '449a42cab3cdaa83f704c330b1bbb7567d50698a3c873803e90426db6b2b758d'),
  ('en.sahih', 39, 63, 4121, 'To Him belong the keys of the heavens and the earth. And they who disbelieve in the verses of Allah - it is those who are the losers.', NULL, NULL, '9ad08461a9714be30eca80723793d60493ce28b065f664e8303966a6b24a85d0'),
  ('en.sahih', 39, 64, 4122, 'Say, [O Muhammad], "Is it other than Allah that you order me to worship, O ignorant ones?"', NULL, NULL, 'e0ffdf0863d782d9e59c0be66134f644fbabd674458d6b418624120a6606b4be'),
  ('en.sahih', 39, 65, 4123, 'And it was already revealed to you and to those before you that if you should associate [anything] with Allah, your work would surely become worthless, and you would surely be among the losers."', NULL, NULL, 'a44875c60ff3dd9af143747773db5698ffc3115cc5401ffac81d22c32c24245d'),
  ('en.sahih', 39, 66, 4124, 'Rather, worship [only] Allah and be among the grateful.', NULL, NULL, '567b8c4e853dfb6a2bbc34073d1f9abea238cef8c6dd388778ff5ec0cc135d5d'),
  ('en.sahih', 39, 67, 4125, 'They have not appraised Allah with true appraisal, while the earth entirely will be [within] His grip on the Day of Resurrection, and the heavens will be folded in His right hand. Exalted is He and high above what they associate with Him.', NULL, NULL, '527b7f9b0ea6b62acec2b67cb23fd318caa0d0448afe2092d1061119ec216a70'),
  ('en.sahih', 39, 68, 4126, 'And the Horn will be blown, and whoever is in the heavens and whoever is on the earth will fall dead except whom Allah wills. Then it will be blown again, and at once they will be standing, looking on.', NULL, NULL, 'e5b6d771b7b6a52d1f5f3c7d82e011c7a722517aa5c11b024edc0fcab6fe45d5'),
  ('en.sahih', 39, 69, 4127, 'And the earth will shine with the light of its Lord, and the record [of deeds] will be placed, and the prophets and the witnesses will be brought, and it will be judged between them in truth, and they will not be wronged.', NULL, NULL, '1f953c14a4e39eada0073742e9cd2d7cf184798a4b0a8eed5705c69900c85c2f'),
  ('en.sahih', 39, 70, 4128, 'And every soul will be fully compensated [for] what it did; and He is most knowing of what they do.', NULL, NULL, '9ca3e8f5f12ec5735dd237094ff51accc33e4c610e362e5b607b72972c9877a9'),
  ('en.sahih', 39, 71, 4129, 'And those who disbelieved will be driven to Hell in groups until, when they reach it, its gates are opened and its keepers will say, "Did there not come to you messengers from yourselves, reciting to you the verses of your Lord and warning you of the meeting of this Day of yours?" They will say, "Yes, but the word of punishment has come into effect upon the disbelievers.', NULL, NULL, 'a22d713ae83c7a9192d315bab65f0e6ce949b06d88aa10c7a2049690e98d0519'),
  ('en.sahih', 39, 72, 4130, '[To them] it will be said, "Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."', NULL, NULL, '6db38143517cc975e91c345159cdb050474311ad6c9792eeeda82c0b967badf1'),
  ('en.sahih', 39, 73, 4131, 'But those who feared their Lord will be driven to Paradise in groups until, when they reach it while its gates have been opened and its keepers say, "Peace be upon you; you have become pure; so enter it to abide eternally therein," [they will enter].', NULL, NULL, 'ba768bfb47b5757645d4068bf2d46018882cdab5ffda08a2dddb4d227027e7cb'),
  ('en.sahih', 39, 74, 4132, 'And they will say, "Praise to Allah, who has fulfilled for us His promise and made us inherit the earth [so] we may settle in Paradise wherever we will. And excellent is the reward of [righteous] workers."', NULL, NULL, '9e04c4b0b888d53007828e733d323addbaa11d09a02cd19ae33f6386d0817abe'),
  ('en.sahih', 39, 75, 4133, 'And you will see the angels surrounding the Throne, exalting [Allah] with praise of their Lord. And it will be judged between them in truth, and it will be said, "[All] praise to Allah, Lord of the worlds."', NULL, NULL, 'bee12d792062489fc091dabe15168c196c0d1272524df0c24d7388221a23b9e1'),
  ('en.sahih', 40, 1, 4134, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 40, 2, 4135, 'The revelation of the Book is from Allah, the Exalted in Might, the Knowing.', NULL, NULL, '9976b5aca72f379263c3935eab2443b1e55d740669c22e2d94c0d76986c5b769'),
  ('en.sahih', 40, 3, 4136, 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.', NULL, NULL, '6c63d16a70cf67ac4973a0355f063b888e25bdbbfc243e4043e05eadc10efdc6'),
  ('en.sahih', 40, 4, 4137, 'No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.', NULL, NULL, 'fd80885db6b697fecb39c98aecaff7396ceece82c5dd39f53c12d6e930e2ec1f'),
  ('en.sahih', 40, 5, 4138, 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.', NULL, NULL, '55b84a570ba241937d223cfd2ccd0d1beedb8588934a9f1174faf34b1fcc1889'),
  ('en.sahih', 40, 6, 4139, 'And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire.', NULL, NULL, '0c2c17e7ecbec4083200676014f714b915c3071db50f4799676c4348dd3352df'),
  ('en.sahih', 40, 7, 4140, 'Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.', NULL, NULL, '862a010d3e8f54c371d40f28305d0cf330aa11bc7d51b3b8a57300b1212e9ff7'),
  ('en.sahih', 40, 8, 4141, 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.', NULL, NULL, '44bfe7c444afb81783bc6c66ade1b5b439188555c734853645f5ed61cc990515'),
  ('en.sahih', 40, 9, 4142, 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."', NULL, NULL, '6dfda5b0b1e89434b3f47471c24dc573525289fbac1375a73582f65cbe05f145'),
  ('en.sahih', 40, 10, 4143, 'Indeed, those who disbelieve will be addressed, "The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused."', NULL, NULL, '59a96f496378a585cbd1ae88fab4a71612c06b2d5c8f93d5288374eb985cc6e2'),
  ('en.sahih', 40, 11, 4144, 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"', NULL, NULL, '3df913210f6e1d191d03218c2052ba97b3aba146912e20bbdc35421612bc9936'),
  ('en.sahih', 40, 12, 4145, '[They will be told], "That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand."', NULL, NULL, '0ea60903c2b974b5da27812f97808ce7e3e3c19ab21a20c2e352e1bc527fbb4e'),
  ('en.sahih', 40, 13, 4146, 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].', NULL, NULL, 'd8b2375234b621600407f8b2dd03a60dbc8075db688b5a04c24bcdc98143d541'),
  ('en.sahih', 40, 14, 4147, 'So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it.', NULL, NULL, '68bf5f8f8fe1b99079239a68a314851ae39acdd134e800d0abf2dd3bc922d106'),
  ('en.sahih', 40, 15, 4148, '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting.', NULL, NULL, '4f79cfa4c2b91c6bb7edd20b00f702e0b061dfe63bcf29062c2171015234c8b2'),
  ('en.sahih', 40, 16, 4149, 'The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing.', NULL, NULL, '80238e0ec882014155a90c2bca71684d56ebe8a38c0ddb86974e9153e607e163'),
  ('en.sahih', 40, 17, 4150, 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account.', NULL, NULL, '7475543f8cc76ab3b997ca66441e280cc4f7948127793dae65276e352dee3174'),
  ('en.sahih', 40, 18, 4151, 'And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.', NULL, NULL, '12e4e07cf9489cabfc88d336bf8904acea8341e9008592f9b7006b5550d8ba38'),
  ('en.sahih', 40, 19, 4152, 'He knows that which deceives the eyes and what the breasts conceal.', NULL, NULL, 'eb9e22cb12d1adcf613b95f7ebbb1a90322a23c6a4848e864a48d534846326f4'),
  ('en.sahih', 40, 20, 4153, 'And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing.', NULL, NULL, '4cc75dd41173ffca38c324735e839ab429df6142283de6ed9f78c821c7b3227b'),
  ('en.sahih', 40, 21, 4154, 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector.', NULL, NULL, '77de9c41962b1f0caa45b727ca121b3538603f4da7521239e1fefc8dc0c0baf5'),
  ('en.sahih', 40, 22, 4155, 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment.', NULL, NULL, '4e59940e30589c80f5f68d8551149d7817f72ac2428291c4714c51a3d5e12501'),
  ('en.sahih', 40, 23, 4156, 'And We did certainly send Moses with Our signs and a clear authority', NULL, NULL, '2263f24c5afbd5cd14e5c63891b8d0e47785ece9fc4b88dc90c796ba20b7b861'),
  ('en.sahih', 40, 24, 4157, 'To Pharaoh, Haman and Qarun; but they said, "[He is] a magician and a liar."', NULL, NULL, '65ace463c79e873204a3a908e352131c4e476df336d533f6488d7f16cd1b6d45'),
  ('en.sahih', 40, 25, 4158, 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.', NULL, NULL, '33c334b29280640ed7c788ac247875bc67f90f9d02e955568110b58e93043227'),
  ('en.sahih', 40, 26, 4159, 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."', NULL, NULL, '9ff94a75beb83b1d4f16f4fefee4fd3d3cd3a38a09e96d086562e551785fa8de'),
  ('en.sahih', 40, 27, 4160, 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."', NULL, NULL, '656441be7e534eddd983a2bac4af2a473ed0ca77635b34ba3910c564f2513fd1'),
  ('en.sahih', 40, 28, 4161, 'And a believing man from the family of Pharaoh who concealed his faith said, "Do you kill a man [merely] because he says, ''My Lord is Allah'' while he has brought you clear proofs from your Lord? And if he should be lying, then upon him is [the consequence of] his lie; but if he should be truthful, there will strike you some of what he promises you. Indeed, Allah does not guide one who is a transgressor and a liar.', NULL, NULL, '65221d423f230af599bc0b9cb54f4df0ac1547056a31e4f9e572d19770f95a2e'),
  ('en.sahih', 40, 29, 4162, 'O my people, sovereignty is yours today, [your being] dominant in the land. But who would protect us from the punishment of Allah if it came to us?" Pharaoh said, "I do not show you except what I see, and I do not guide you except to the way of right conduct."', NULL, NULL, 'ccc514023242dc174017f9d0bef17f78b92479eb36613e288cdd429aa13a47dd'),
  ('en.sahih', 40, 30, 4163, 'And he who believed said, "O my people, indeed I fear for you [a fate] like the day of the companies -', NULL, NULL, '529cdd85cabb18e25cdb9bb75be2c1ca5041f6b5725abc3e5194a7441a40a022'),
  ('en.sahih', 40, 31, 4164, 'Like the custom of the people of Noah and of ''Aad and Thamud and those after them. And Allah wants no injustice for [His] servants.', NULL, NULL, '764a5f0f129a8e07cce5ac1026fa5b9c7547b369356b19332dfcf768cf1a28e2'),
  ('en.sahih', 40, 32, 4165, 'And O my people, indeed I fear for you the Day of Calling -', NULL, NULL, 'a1933056f26ee8d8586cc94abab4677b415be1300b7ec73d8d556f9c069a0f81'),
  ('en.sahih', 40, 33, 4166, 'The Day you will turn your backs fleeing; there is not for you from Allah any protector. And whoever Allah leaves astray - there is not for him any guide.', NULL, NULL, '92d92621e4b0fb9a661c5c275a524a98f452a5a213410dae080478b5d9de0fab'),
  ('en.sahih', 40, 34, 4167, 'And Joseph had already come to you before with clear proofs, but you remained in doubt of that which he brought to you, until when he died, you said, ''Never will Allah send a messenger after him.'' Thus does Allah leave astray he who is a transgressor and skeptic."', NULL, NULL, '48b88f81db64fdc333d5207868e120a35539fabb5a550ecc5096a4a64f2a7dbc'),
  ('en.sahih', 40, 35, 4168, 'Those who dispute concerning the signs of Allah without an authority having come to them - great is hatred [of them] in the sight of Allah and in the sight of those who have believed. Thus does Allah seal over every heart [belonging to] an arrogant tyrant.', NULL, NULL, '31e65e7e60962ae391414ff744b7f21d9cbc80862cf6992facaea5b950cb9aee'),
  ('en.sahih', 40, 36, 4169, 'And Pharaoh said, "O Haman, construct for me a tower that I might reach the ways -', NULL, NULL, 'c97d3e165c09096e57cfea147c11aa47ed709be961c8ba8c4ec25d0713f3f913'),
  ('en.sahih', 40, 37, 4170, 'The ways into the heavens - so that I may look at the deity of Moses; but indeed, I think he is a liar." And thus was made attractive to Pharaoh the evil of his deed, and he was averted from the [right] way. And the plan of Pharaoh was not except in ruin.', NULL, NULL, 'c8072e98d603e9186aae812b3feb599d7e98742e6a50aeaed517bcfaf2480be3'),
  ('en.sahih', 40, 38, 4171, 'And he who believed said, "O my people, follow me, I will guide you to the way of right conduct.', NULL, NULL, 'f7adc7f84e017ba33eb5a44bf449f445e94da61f81cf5c395178fcc2e832b6c4'),
  ('en.sahih', 40, 39, 4172, 'O my people, this worldly life is only [temporary] enjoyment, and indeed, the Hereafter - that is the home of [permanent] settlement.', NULL, NULL, '30a06191ca7a5d5c25dd5e6614cdaca7e8a37fbc45dd2537ef3fd5a037837578'),
  ('en.sahih', 40, 40, 4173, 'Whoever does an evil deed will not be recompensed except by the like thereof; but whoever does righteousness, whether male or female, while he is a believer - those will enter Paradise, being given provision therein without account.', NULL, NULL, '58ed3996cd32a11aeb9830e4e24e7adad2c88679c7deb50e65a2ecfbb5da9327'),
  ('en.sahih', 40, 41, 4174, 'And O my people, how is it that I invite you to salvation while you invite me to the Fire?', NULL, NULL, 'b76eb9f3c9843e5fb3417f8153351b37a1cab9127f34dd65b694a4699226e15b'),
  ('en.sahih', 40, 42, 4175, 'You invite me to disbelieve in Allah and associate with Him that of which I have no knowledge, and I invite you to the Exalted in Might, the Perpetual Forgiver.', NULL, NULL, 'b75e37216bba7254e5c69e33a5923b65f304d5b96c73d5c4e666f2e420f80d37'),
  ('en.sahih', 40, 43, 4176, 'Assuredly, that to which you invite me has no [response to a] supplication in this world or in the Hereafter; and indeed, our return is to Allah, and indeed, the transgressors will be companions of the Fire.', NULL, NULL, 'c6c0abfd3ca6136c85e0b9e1cb9475381535423e141740005706e1c3118b08a9'),
  ('en.sahih', 40, 44, 4177, 'And you will remember what I [now] say to you, and I entrust my affair to Allah. Indeed, Allah is Seeing of [His] servants."', NULL, NULL, 'f97dd428d6732f0933fc167fb2dd8f1b0b39ecf2e5dbd6fd964304be1985637b'),
  ('en.sahih', 40, 45, 4178, 'So Allah protected him from the evils they plotted, and the people of Pharaoh were enveloped by the worst of punishment -', NULL, NULL, '1398a30ae39abe1c04347aa43dffd201fed20a1b5111aa16b8e4a45a02bf6188'),
  ('en.sahih', 40, 46, 4179, 'The Fire, they are exposed to it morning and evening. And the Day the Hour appears [it will be said], "Make the people of Pharaoh enter the severest punishment."', NULL, NULL, 'eef9bd3d2d68c621a3fe4c2ce45b085c7bf6197c7dc589c43b44d788fe5d6c4d'),
  ('en.sahih', 40, 47, 4180, 'And [mention] when they will argue within the Fire, and the weak will say to those who had been arrogant, "Indeed, we were [only] your followers, so will you relieve us of a share of the Fire?"', NULL, NULL, 'f80fab44d8e1cd85304b788a62457a72d0d880e685e2c5c3ca8c08ac109d0f28'),
  ('en.sahih', 40, 48, 4181, 'Those who had been arrogant will say, "Indeed, all [of us] are in it. Indeed, Allah has judged between the servants."', NULL, NULL, '6c886c5c15540d1938959d0ad0d8514267e025d4ef23e1274d909911433d2bb1'),
  ('en.sahih', 40, 49, 4182, 'And those in the Fire will say to the keepers of Hell, "Supplicate your Lord to lighten for us a day from the punishment."', NULL, NULL, '52d25d4629aedda4a1efc21d48f74dd0eb7ea45f0ca6e7727c82a96ce6b31aa2'),
  ('en.sahih', 40, 50, 4183, 'They will say, "Did there not come to you your messengers with clear proofs?" They will say, "Yes." They will reply, "Then supplicate [yourselves], but the supplication of the disbelievers is not except in error."', NULL, NULL, 'ce68d19ae85d1a734dd89244218ae1cc20836893c69c4cdf0f0818e2d6f309d1'),
  ('en.sahih', 40, 51, 4184, 'Indeed, We will support Our messengers and those who believe during the life of this world and on the Day when the witnesses will stand -', NULL, NULL, '0867839a170c6351119f655df57800bd736c8db5e95fbb5ff72b4936a389a2fa'),
  ('en.sahih', 40, 52, 4185, 'The Day their excuse will not benefit the wrongdoers, and they will have the curse, and they will have the worst home.', NULL, NULL, '9e2984540046642aea8969be867acb533783b7cd288db322a08afbf5975ec4ca'),
  ('en.sahih', 40, 53, 4186, 'And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture', NULL, NULL, '31029245ba459154fe31d6340c8566c20f4113b13e86daff15bc60d2850125ef'),
  ('en.sahih', 40, 54, 4187, 'As guidance and a reminder for those of understanding.', NULL, NULL, '405b38786b5900dcd3b52ab58d1f6ee3258161bd872eed0f666ff2cc86e74d31'),
  ('en.sahih', 40, 55, 4188, 'So be patient, [O Muhammad]. Indeed, the promise of Allah is truth. And ask forgiveness for your sin and exalt [Allah] with praise of your Lord in the evening and the morning.', NULL, NULL, '28d6f93282d579fda98485e758d8e7660f7f6694e33f28a59f191243237a24e3'),
  ('en.sahih', 40, 56, 4189, 'Indeed, those who dispute concerning the signs of Allah without [any] authority having come to them - there is not within their breasts except pride, [the extent of] which they cannot reach. So seek refuge in Allah. Indeed, it is He who is the Hearing, the Seeing.', NULL, NULL, '2a2d5e9b556906b04c0cb6c5dda71350c86e6133725a298d093cc6e918c6707f'),
  ('en.sahih', 40, 57, 4190, 'The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know.', NULL, NULL, '34da552f8ed1d8b31c65bdea5fb2fae5e8bd9ab605a363936d478ed1597119c1'),
  ('en.sahih', 40, 58, 4191, 'And not equal are the blind and the seeing, nor are those who believe and do righteous deeds and the evildoer. Little do you remember.', NULL, NULL, 'c849b2663d7dfea9b7f94f85bf728a570916a205302f960ccc1579f4946220cd'),
  ('en.sahih', 40, 59, 4192, 'Indeed, the Hour is coming - no doubt about it - but most of the people do not believe.', NULL, NULL, 'b0117f65121e75f1c9b25557cca852866d49094fb7e82d3ed1a542e39ca09cc4'),
  ('en.sahih', 40, 60, 4193, 'And your Lord says, "Call upon Me; I will respond to you." Indeed, those who disdain My worship will enter Hell [rendered] contemptible.', NULL, NULL, 'd8740dc22331a0d914290758e8d04944f59d3f9ef9d4e70f4538867e9c4f886f'),
  ('en.sahih', 40, 61, 4194, 'It is Allah who made for you the night that you may rest therein and the day giving sight. Indeed, Allah is full of bounty to the people, but most of the people are not grateful.', NULL, NULL, '319d665000176fd96515f890b2aa1ceb8b8b907be2375181acdaa62e5456bf47'),
  ('en.sahih', 40, 62, 4195, 'That is Allah, your Lord, Creator of all things; there is no deity except Him, so how are you deluded?', NULL, NULL, '704458045d8e6c0f3b5b93e5185c99ce155ca1569ba8a2a6530459ed78b4585f'),
  ('en.sahih', 40, 63, 4196, 'Thus were those [before you] deluded who were rejecting the signs of Allah.', NULL, NULL, 'd86ae7f30e1b7832627cc5ce465d8fdfbb28995bb580b386983bb0526ae31e1f'),
  ('en.sahih', 40, 64, 4197, 'It is Allah who made for you the earth a place of settlement and the sky a ceiling and formed you and perfected your forms and provided you with good things. That is Allah, your Lord; then blessed is Allah, Lord of the worlds.', NULL, NULL, '28b7b3239970aaa5597d1312aa87778a0ebcd798c72975a3e2acfbd0ecc1f610'),
  ('en.sahih', 40, 65, 4198, 'He is the Ever-Living; there is no deity except Him, so call upon Him, [being] sincere to Him in religion. [All] praise is [due] to Allah, Lord of the worlds.', NULL, NULL, 'c9b7f6a893b6a028e4d6446944872ca961cd5106dc1c866fd602538a8baa71c5'),
  ('en.sahih', 40, 66, 4199, 'Say, [O Muhammad], "Indeed, I have been forbidden to worship those you call upon besides Allah once the clear proofs have come to me from my Lord, and I have been commanded to submit to the Lord of the worlds."', NULL, NULL, '901956b978fc88132afe3431522e4830b0bc57670c5e66789cbf7b74101c1f94'),
  ('en.sahih', 40, 67, 4200, 'It is He who created you from dust, then from a sperm-drop, then from a clinging clot; then He brings you out as a child; then [He develops you] that you reach your [time of] maturity, then [further] that you become elders. And among you is he who is taken in death before [that], so that you reach a specified term; and perhaps you will use reason.', NULL, NULL, 'dc4852b7a6d70fb5a30e5c02f49db8cd071f53226f27b3633410c020e772b7c0')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 40, 68, 4201, 'He it is who gives life and causes death; and when He decrees a matter, He but says to it, "Be," and it is.', NULL, NULL, 'cd0a8ce06dc726e2e3971c2b0ebf815a37d3896e8698ddbc971503bcf299b8a5'),
  ('en.sahih', 40, 69, 4202, 'Do you not consider those who dispute concerning the signs of Allah - how are they averted?', NULL, NULL, 'c6ee63b0a3dbd7ef62d6034900fac301d1631e39607c0e0a4deb2734fde18e0d'),
  ('en.sahih', 40, 70, 4203, 'Those who deny the Book and that with which We sent Our messengers - they are going to know,', NULL, NULL, 'e870238e4fd4c746b68cf23e04294b7edffc8b2804257f1753bd1bb83e9397b3'),
  ('en.sahih', 40, 71, 4204, 'When the shackles are around their necks and the chains; they will be dragged', NULL, NULL, '1c92a1130e18a929ff9072436b94c6ebd4bc6fd5b201000e912e7bcad2cc8dbc'),
  ('en.sahih', 40, 72, 4205, 'In boiling water; then in the Fire they will be filled [with flame].', NULL, NULL, '2c1e99501b56ea287f02714659a05947ebb02aabdc6b25b97dd6ecb81f518f89'),
  ('en.sahih', 40, 73, 4206, 'Then it will be said to them, "Where is that which you used to associate [with Him in worship]', NULL, NULL, '641677ee1c0a46a67d5f78eecd33e976b47e38cdd5a419e6588e588fef29bf2c'),
  ('en.sahih', 40, 74, 4207, 'Other than Allah?" They will say, "They have departed from us; rather, we did not used to invoke previously anything." Thus does Allah put astray the disbelievers.', NULL, NULL, '6d5eabc2afc8f63a29897c9c5b8d30a35902ac974d33c4c0dbb230f91044fb11'),
  ('en.sahih', 40, 75, 4208, '[The angels will say], "That was because you used to exult upon the earth without right and you used to behave insolently.', NULL, NULL, 'a6eaf1a1c49cdba015affb5e0b974a3a4ef22a7b071eec3cd993d4a0d5d6610a'),
  ('en.sahih', 40, 76, 4209, 'Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."', NULL, NULL, '015d9bdaf001175a300639a0f7d21c201cb319bd0ef6cf4bd50c429c2edb8c24'),
  ('en.sahih', 40, 77, 4210, 'So be patient, [O Muhammad]; indeed, the promise of Allah is truth. And whether We show you some of what We have promised them or We take you in death, it is to Us they will be returned.', NULL, NULL, '34c6eed90ce017cdc7b19e953937eb8f0e9817194db532c93656589c7b9bb120'),
  ('en.sahih', 40, 78, 4211, 'And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allah. So when the command of Allah comes, it will be concluded in truth, and the falsifiers will thereupon lose [all].', NULL, NULL, 'e6675724e35838d96dc05f865c372653a30028fbaec3dc2c13b1cadfdc581768'),
  ('en.sahih', 40, 79, 4212, 'It is Allah who made for you the grazing animals upon which you ride, and some of them you eat.', NULL, NULL, 'ef880a1fb53ea4c41756b9e2a989571a21307eec2210e590761039841eb7b5af'),
  ('en.sahih', 40, 80, 4213, 'And for you therein are [other] benefits and that you may realize upon them a need which is in your breasts; and upon them and upon ships you are carried.', NULL, NULL, 'c870af4ae35bc84a707e3f8841d0e7d99bd7fe56eb34df43fb7d68e04a886de0'),
  ('en.sahih', 40, 81, 4214, 'And He shows you His signs. So which of the signs of Allah do you deny?', NULL, NULL, 'fcfdb6736413494873ee8f749c140c26c018dbe560218f8c947c4caee507a601'),
  ('en.sahih', 40, 82, 4215, 'Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn.', NULL, NULL, '1497694d503716108420e7231082a0a7a31a3a78db1c4ca1b42c9e828a2f8139'),
  ('en.sahih', 40, 83, 4216, 'And when their messengers came to them with clear proofs, they [merely] rejoiced in what they had of knowledge, but they were enveloped by what they used to ridicule.', NULL, NULL, '0e94672e06edea386faf835b59c4b476dafb7b4d2190c754adb62f937b5edcd7'),
  ('en.sahih', 40, 84, 4217, 'And when they saw Our punishment, they said," We believe in Allah alone and disbelieve in that which we used to associate with Him."', NULL, NULL, 'ddf1d835969bd13fd3004b084762722fa65265f96c02ce0b64a4d4ffc879c758'),
  ('en.sahih', 40, 85, 4218, 'But never did their faith benefit them once they saw Our punishment. [It is] the established way of Allah which has preceded among His servants. And the disbelievers thereupon lost [all].', NULL, NULL, 'fd4f4ed83e1dfc07304642c2ee69ec265d8e7d3e87f34643b4ad40a4be427e50'),
  ('en.sahih', 41, 1, 4219, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 41, 2, 4220, '[This is] a revelation from the Entirely Merciful, the Especially Merciful -', NULL, NULL, '3c9e24f0500a1fa177a1b838cac0a93c7c75bf549ff2087b6551720b3c5391b3'),
  ('en.sahih', 41, 3, 4221, 'A Book whose verses have been detailed, an Arabic Qur''an for a people who know,', NULL, NULL, '0cbe312101dc1c02442e40791d3c6bf5971384d0f6dc7dcb13641ee004c7537b'),
  ('en.sahih', 41, 4, 4222, 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.', NULL, NULL, '98c569dcad015d3a8961e4cbec6cb830977b4aed4536ceeaba0e91db059ddc58'),
  ('en.sahih', 41, 5, 4223, 'And they say, "Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."', NULL, NULL, '1d630403f14073cc2b25c93d9f692353eda99733f361c1fd465c40aed3e91747'),
  ('en.sahih', 41, 6, 4224, 'Say, O [Muhammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allah -', NULL, NULL, 'f69662c6da0b10ab83816a787c00682d7a9afe3a2214e2710e890f1f4f44281d'),
  ('en.sahih', 41, 7, 4225, 'Those who do not give zakah, and in the Hereafter they are disbelievers.', NULL, NULL, 'aba0db6a177713911902070fdf3a18f65ba7218ad9272b01f55a997d02574eb5'),
  ('en.sahih', 41, 8, 4226, 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.', NULL, NULL, 'f9afb1727f92848ecddd8ac99a62e8eecee3ae42417b3e08193e926102aa0e74'),
  ('en.sahih', 41, 9, 4227, 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."', NULL, NULL, 'b5fb37ce5109e0ddd3d67e462578253898752b77725e07f8bb4943910f83164c'),
  ('en.sahih', 41, 10, 4228, 'And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures''] sustenance in four days without distinction - for [the information] of those who ask.', NULL, NULL, '122e9799a9b03ce93ebd3ca499d404cedf45c03d3bae584333c040ec5104a8f6'),
  ('en.sahih', 41, 11, 4229, 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."', NULL, NULL, '38efd7c10c5e29504f0ed02c1357811af3412567eda7dbcd75a1e25a8818ae2d'),
  ('en.sahih', 41, 12, 4230, 'And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing.', NULL, NULL, 'b67c112fa7bf304a570044b3d13b861847c73814694e6cc10119de5c81b3eb45'),
  ('en.sahih', 41, 13, 4231, 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] ''Aad and Thamud.', NULL, NULL, '9cbe4a20b04bff2dd85f7288df270fec3d00fee0c91883d78712eaebe0678d0f'),
  ('en.sahih', 41, 14, 4232, '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allah." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."', NULL, NULL, '6393630cfac91703b6650603c42321a2c7c8f4655858ea0edeefcc59156115bd'),
  ('en.sahih', 41, 15, 4233, 'As for ''Aad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs.', NULL, NULL, '63f1efe3829366c9d3b62c956ceb2b5fdc7fd820227144ad309d0e921d5d9788'),
  ('en.sahih', 41, 16, 4234, 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.', NULL, NULL, '4bb95d71716072e683aecee5f3ce75b185044c881e6a513fad0d022ebbcb1330'),
  ('en.sahih', 41, 17, 4235, 'And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.', NULL, NULL, 'ece4b32f0810478f925ca79853ef9aa02eb9a7d6e1cbae8740bd6c26a2129d39'),
  ('en.sahih', 41, 18, 4236, 'And We saved those who believed and used to fear Allah.', NULL, NULL, 'a43c480e4a7df953da112c0ffe88d17b4f6e8cf01133a51f9023f493737dbff9'),
  ('en.sahih', 41, 19, 4237, 'And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,', NULL, NULL, 'f72d9551c6b404394827b8df851099a168a8a7f2642b1420778314ec7fe31160'),
  ('en.sahih', 41, 20, 4238, 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.', NULL, NULL, 'd1a32c84f17563190d85cfbff5517d02ecc79bf30755965ee32b9948e5ab0d5b'),
  ('en.sahih', 41, 21, 4239, 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned.', NULL, NULL, '3d1a40d27958edf4037d2de2030a100245657269df6cb087a53f91470dc68488'),
  ('en.sahih', 41, 22, 4240, 'And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do.', NULL, NULL, '1bbf2e4e1c12b55cb6b064ee6f5a49fb496b9a3a5d9d05a78fde7a2149c19518'),
  ('en.sahih', 41, 23, 4241, 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."', NULL, NULL, 'f17e4075c7a74cba39f41666873a632c22b795e0dba611e7c1fad40176bd36a0'),
  ('en.sahih', 41, 24, 4242, 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease.', NULL, NULL, '52f5bd9de6d06c7ef74048770cd72b20b226bb789120835155a3a7b2916de4db'),
  ('en.sahih', 41, 25, 4243, 'And We appointed for them companions who made attractive to them what was before them and what was behind them [of sin], and the word has come into effect upon them among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.', NULL, NULL, 'f9256d34d934017b3fca2e582029bee288fadaf14d74c2945b856e114081f2d1'),
  ('en.sahih', 41, 26, 4244, 'And those who disbelieve say, "Do not listen to this Qur''an and speak noisily during [the recitation of] it that perhaps you will overcome."', NULL, NULL, 'b46ab7b96d7995caecbf9646d9f3b17aeaefcd9c67ad903ca2431e3af40be999'),
  ('en.sahih', 41, 27, 4245, 'But We will surely cause those who disbelieve to taste a severe punishment, and We will surely recompense them for the worst of what they had been doing.', NULL, NULL, '3312e9db1674c57d0d6fcdedc8a98b2139b2340feec403e5d209edd0fef13a37'),
  ('en.sahih', 41, 28, 4246, 'That is the recompense of the enemies of Allah - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting.', NULL, NULL, 'c0b74d7dd2e7cdb2822353f3ea5e3a9f4d00a03a7e3c07dfb29335b3f28bddb9'),
  ('en.sahih', 41, 29, 4247, 'And those who disbelieved will [then] say, "Our Lord, show us those who misled us of the jinn and men [so] we may put them under our feet that they will be among the lowest."', NULL, NULL, '911aa2595f1c36f636ba236a1b7dc4b41ce1178ed1aae421bdf3bc8e4b3436fb'),
  ('en.sahih', 41, 30, 4248, 'Indeed, those who have said, "Our Lord is Allah " and then remained on a right course - the angels will descend upon them, [saying], "Do not fear and do not grieve but receive good tidings of Paradise, which you were promised.', NULL, NULL, 'd69c5645dc6b314283ab34c5fbaf80f6b9fc1162b84c14ee7a5e3aacf3defcdd'),
  ('en.sahih', 41, 31, 4249, 'We [angels] were your allies in worldly life and [are so] in the Hereafter. And you will have therein whatever your souls desire, and you will have therein whatever you request [or wish]', NULL, NULL, 'd6566f7de1207d7ff30d8f3941e4d5283f8990f0098e8b6fe57838debcda3564'),
  ('en.sahih', 41, 32, 4250, 'As accommodation from a [Lord who is] Forgiving and Merciful."', NULL, NULL, '722cca1c028de70359325dee5700f89410d3e6b3993ba50275b79b69be36a2a4'),
  ('en.sahih', 41, 33, 4251, 'And who is better in speech than one who invites to Allah and does righteousness and says, "Indeed, I am of the Muslims."', NULL, NULL, '2346d89dfada76dcc665f1406fd7a87f3f01fb4a7f474803a2bf3ba0eb2df3df'),
  ('en.sahih', 41, 34, 4252, 'And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend.', NULL, NULL, 'f78971b32316dd4283b28d49591aa7ad222e2a9a8b8778b8f27a49b8599603de'),
  ('en.sahih', 41, 35, 4253, 'But none is granted it except those who are patient, and none is granted it except one having a great portion [of good].', NULL, NULL, 'ca77afcb93c840171c74183f68d8b6a80cbf555c61f75747ffdfe8c372218af2'),
  ('en.sahih', 41, 36, 4254, 'And if there comes to you from Satan an evil suggestion, then seek refuge in Allah. Indeed, He is the Hearing, the Knowing.', NULL, NULL, '5a64d0de2a9be5c74ab19a9d49836183781d7dd33f05c1fba28bf790260d472c'),
  ('en.sahih', 41, 37, 4255, 'And of His signs are the night and day and the sun and moon. Do not prostrate to the sun or to the moon, but prostate to Allah, who created them, if it should be Him that you worship.', NULL, NULL, 'c82da8ab7fd633ea60521845dac551e72ba47552a90b938f5968837a3d6e29cc'),
  ('en.sahih', 41, 38, 4256, 'But if they are arrogant - then those who are near your Lord exalt Him by night and by day, and they do not become weary.', NULL, NULL, 'f419bb3376edc1177fa894b94391588358111c41bfaeecdc2bc3fece67cca132'),
  ('en.sahih', 41, 39, 4257, 'And of His signs is that you see the earth stilled, but when We send down upon it rain, it quivers and grows. Indeed, He who has given it life is the Giver of Life to the dead. Indeed, He is over all things competent.', NULL, NULL, 'eb348b07955aaed71df2fd5be38aac27c1726df7104308b7f64ee4b59f30159a'),
  ('en.sahih', 41, 40, 4258, 'Indeed, those who inject deviation into Our verses are not concealed from Us. So, is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do whatever you will; indeed, He is Seeing of what you do.', NULL, NULL, '422a1c450e9ffd4cfc30a7039f08937444003d994bbaab339269eeb1bce258fa'),
  ('en.sahih', 41, 41, 4259, 'Indeed, those who disbelieve in the message after it has come to them... And indeed, it is a mighty Book.', NULL, NULL, 'e953eb99d763bbd46783f6abd5be2cb6baf4b54a2ad37cb95887e87dd8c51e6d'),
  ('en.sahih', 41, 42, 4260, 'Falsehood cannot approach it from before it or from behind it; [it is] a revelation from a [Lord who is] Wise and Praiseworthy.', NULL, NULL, '54b92c370c695c14603bc0b0398cd0de95200a51838b0a1abe08ef59fe4349cb'),
  ('en.sahih', 41, 43, 4261, 'Nothing is said to you, [O Muhammad], except what was already said to the messengers before you. Indeed, your Lord is a possessor of forgiveness and a possessor of painful penalty.', NULL, NULL, '9442be1a6f07f298ce87871166b028ddc0218c962a282ff41511b2551382b658'),
  ('en.sahih', 41, 44, 4262, 'And if We had made it a non-Arabic Qur''an, they would have said, "Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?" Say, "It is, for those who believe, a guidance and cure." And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place.', NULL, NULL, '1227e51879c2ce1890ab4801b2ada66f305d2cbc0339517ab4acc43a8f82ebc1'),
  ('en.sahih', 41, 45, 4263, 'And We had already given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been concluded between them. And indeed they are, concerning the Qur''an, in disquieting doubt.', NULL, NULL, '16dff313f50a754947e77590f85086d20f2260e1eb5a86c46f9ddccfef014607'),
  ('en.sahih', 41, 46, 4264, 'Whoever does righteousness - it is for his [own] soul; and whoever does evil [does so] against it. And your Lord is not ever unjust to [His] servants.', NULL, NULL, '76b1ed52d18caee6122ab320140b28746c8ea836c4d51822b5fc520398cd7426'),
  ('en.sahih', 41, 47, 4265, 'To him [alone] is attributed knowledge of the Hour. And fruits emerge not from their coverings nor does a female conceive or give birth except with His knowledge. And the Day He will call to them, "Where are My ''partners''?" they will say, "We announce to You that there is [no longer] among us any witness [to that]."', NULL, NULL, 'caff2bf555ddfdbdca96ac2c5e11e912ce213bb2010f2b58fb86ea6f755a04f6'),
  ('en.sahih', 41, 48, 4266, 'And lost from them will be those they were invoking before, and they will be certain that they have no place of escape.', NULL, NULL, '4aa66ab1df64a4f58d88ff894a5159eb663b4407082cb35a5471053b763cb366'),
  ('en.sahih', 41, 49, 4267, 'Man is not weary of supplication for good [things], but if evil touches him, he is hopeless and despairing.', NULL, NULL, '298a87eae8d53c76d7fe13777f5f67de20f784871e834ecdbdc87d95a26b0db2'),
  ('en.sahih', 41, 50, 4268, 'And if We let him taste mercy from Us after an adversity which has touched him, he will surely say, "This is [due] to me, and I do not think the Hour will occur; and [even] if I should be returned to my Lord, indeed, for me there will be with Him the best." But We will surely inform those who disbelieved about what they did, and We will surely make them taste a massive punishment.', NULL, NULL, 'b69f5d60a621d5ee8edfeb3f9f68677f0e7c25b15ac68c974bb57e30011a83ab'),
  ('en.sahih', 41, 51, 4269, 'And when We bestow favor upon man, he turns away and distances himself; but when evil touches him, then he is full of extensive supplication.', NULL, NULL, '0787289b523ecce7e1ba5631c809028146032fe065aefd7b10221e355897e9bf'),
  ('en.sahih', 41, 52, 4270, 'Say, "Have you considered: if the Qur''an is from Allah and you disbelieved in it, who would be more astray than one who is in extreme dissension?"', NULL, NULL, 'f7a36101d1fc864e9aa14fcc470feedb40e4a8e428cd265f41809a8999dcc213'),
  ('en.sahih', 41, 53, 4271, 'We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth. But is it not sufficient concerning your Lord that He is, over all things, a Witness?', NULL, NULL, '9b68de16c33d152d81f69ad2cf114c5e67988f6372480054a77db824d9b5e576'),
  ('en.sahih', 41, 54, 4272, 'Unquestionably, they are in doubt about the meeting with their Lord. Unquestionably He is, of all things, encompassing.', NULL, NULL, 'c4ee82daf758fd16247590311e370cea24e59396b7f78c0d15e3dcb9f2aec7d8'),
  ('en.sahih', 42, 1, 4273, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 42, 2, 4274, '''Ayn, Seen, Qaf.', NULL, NULL, '05231111251be63424965a51c56ef3378411e832a2101b97d4dd982db281c4f1'),
  ('en.sahih', 42, 3, 4275, 'Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise.', NULL, NULL, 'f9f1744847313e0fa3b83ae2ec2684ab7e2a5242bac56298231f38b1394ff63c'),
  ('en.sahih', 42, 4, 4276, 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.', NULL, NULL, 'f812560729f993c94bf4f12f16c1700729663d03adde47ba521a7e1da2df7fdd'),
  ('en.sahih', 42, 5, 4277, 'The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful.', NULL, NULL, '8b13aaecca6aa23d8603339a05e01d5317d29c94ac6cc89ba885d1243e9872c5'),
  ('en.sahih', 42, 6, 4278, 'And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.', NULL, NULL, 'fc5d1008635ee01ee8736d136a7189862f00d57074006be28d97fcdde260a833'),
  ('en.sahih', 42, 7, 4279, 'And thus We have revealed to you an Arabic Qur''an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.', NULL, NULL, '3a9dc780ea10305e3c33c651901901c0a878adcc8816afe9fa8330c1515187b9'),
  ('en.sahih', 42, 8, 4280, 'And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.', NULL, NULL, 'ab806b8f91afa6aea77fa05510585b01e60bab0ed1bb860cf322346f2dfc3ed9'),
  ('en.sahih', 42, 9, 4281, 'Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent.', NULL, NULL, 'c29c93cd5e82ff067814556f5e58d913f1d7f83b6539c8b83f8ead80b3afee65'),
  ('en.sahih', 42, 10, 4282, 'And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], "That is Allah, my Lord; upon Him I have relied, and to Him I turn back."', NULL, NULL, '1872b8d7e97dcc3d72a2882a8f707aefe78c08d09e6b9de5a94bcf2044d9e886'),
  ('en.sahih', 42, 11, 4283, '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.', NULL, NULL, '7cbb6b1e71818a1deaf9a82f78bf174350bc6867e13535270ef3d53689ecff9c'),
  ('en.sahih', 42, 12, 4284, 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.', NULL, NULL, '1401f148eb5c15296d5b0fb8c7e73b27e46cc59fee4cee85b22bda2f8a33307b'),
  ('en.sahih', 42, 13, 4285, 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].', NULL, NULL, '2231af83d5bb1b2ef28c24e8ca99dcfa9ea55ae0f2aeee269288316006d6c3c8'),
  ('en.sahih', 42, 14, 4286, 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.', NULL, NULL, '9a5bfd23a4c290c0708e63c5c175796712c367bc1e12f399f89530c8dee37947'),
  ('en.sahih', 42, 15, 4287, 'So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allah has revealed of the Qur''an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination."', NULL, NULL, '157e995d03f62834086da19614f3bf216e99b8b7ad44e204c0a9cbde8d4330bc'),
  ('en.sahih', 42, 16, 4288, 'And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.', NULL, NULL, 'e8da85b569351ac0f6c8044af7913d00cbbe0f08733aafa9b159cdbae04fa285'),
  ('en.sahih', 42, 17, 4289, 'It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.', NULL, NULL, 'e71d757d883414a7fe802a5593c1675264be969f2e8a61bf59a9ea2f84f9e007'),
  ('en.sahih', 42, 18, 4290, 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.', NULL, NULL, 'ebd513edf79f738f12a49aeb993b15dcd33f491cb8becac083c0a30a4eb9df93'),
  ('en.sahih', 42, 19, 4291, 'Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.', NULL, NULL, '1773869b9baca9eafb2e71c486ad903c3c34852bdecde4c7bcd88ec8907fbf20'),
  ('en.sahih', 42, 20, 4292, 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share.', NULL, NULL, '9d99b7b6c1e0a842d0986a387a6cf7de3618cf1a40db7059721f156e7aa7da4c'),
  ('en.sahih', 42, 21, 4293, 'Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.', NULL, NULL, 'adc58f4feacd8f056a0e2e6d882621735a0d461fd2e6a380a91b66ab468c29bf'),
  ('en.sahih', 42, 22, 4294, 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.', NULL, NULL, '4072756af6eee2640552b7fe16da8ee7541f98235b5f24e2d7f6f145f876fbeb'),
  ('en.sahih', 42, 23, 4295, 'It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], "I do not ask you for this message any payment [but] only good will through kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative.', NULL, NULL, 'daf7aaf814dfb0629b63b03ed9a58910b9b1b619d6f9358b6f737bb0cd9ef39f'),
  ('en.sahih', 42, 24, 4296, 'Or do they say, "He has invented about Allah a lie"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.', NULL, NULL, '17a3d36cd4205014426d8d9e28e4b35457b75c9cca515ac0453fdc305e2f7b7c'),
  ('en.sahih', 42, 25, 4297, 'And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.', NULL, NULL, '6cb2b043254b7cbfb318525598d97d7c6f81ecb6ad08df86dcac5647591833bb'),
  ('en.sahih', 42, 26, 4298, 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.', NULL, NULL, '4dd95b7b9e3a4d5ad20f3a1e34a1cff19f02296d6fee3023ec9da72ba4426f1e'),
  ('en.sahih', 42, 27, 4299, 'And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing.', NULL, NULL, 'b720b62532e3debd0ad8a674bf080d0ab3664a4f21580451a0297004a1a70dce'),
  ('en.sahih', 42, 28, 4300, 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.', NULL, NULL, 'fda2779ca60f4cbb9bc75bab6fcd14846fbf44ea91602b87c481f6c2ce151eb6')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 42, 29, 4301, 'And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.', NULL, NULL, '9fbf20babbbf8b30b36b710d150d2456436f7a2a1efcd5094247a0d32bd1951b'),
  ('en.sahih', 42, 30, 4302, 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.', NULL, NULL, '4dac9b7d6b5ac8390205fb2fda475f8ef6a8d13b5c44c3f806bbe8583beb5b9d'),
  ('en.sahih', 42, 31, 4303, 'And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper.', NULL, NULL, '087b3cceefaf7e242e78a2080e558c0a595f44124cb41047405cd1dd5c35d510'),
  ('en.sahih', 42, 32, 4304, 'And of His signs are the ships in the sea, like mountains.', NULL, NULL, '8952d38b1cd9ccebcb3f7edef87bb6148a9de860f8869a4ab9cd4eae666e23e0'),
  ('en.sahih', 42, 33, 4305, 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.', NULL, NULL, '776b48ca95e319e7bbde84bdf195f076a4adc0d17f39e74119eeb9733ff3f7a2'),
  ('en.sahih', 42, 34, 4306, 'Or He could destroy them for what they earned; but He pardons much.', NULL, NULL, '1bcdb7281b8bf433f36591c9f1293a3539f53cc3928d013b74ef6c2d59ed5b55'),
  ('en.sahih', 42, 35, 4307, 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.', NULL, NULL, 'f0203ff3216f633c8ea63f41160ec05dea4e98ef3dc0bb3d9ca2fab6aeb926d4'),
  ('en.sahih', 42, 36, 4308, 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely', NULL, NULL, '3c407028a8c3d5c4acc12bcbdba164b4dfbce4325659d54972cb35f185fe42f5'),
  ('en.sahih', 42, 37, 4309, 'And those who avoid the major sins and immoralities, and when they are angry, they forgive,', NULL, NULL, '156b700271de16771b10802d37b6fcda158ed0017b57ea2fecf46748d766f525'),
  ('en.sahih', 42, 38, 4310, 'And those who have responded to their lord and established prayer and whose affair is [determined by] consultation among themselves, and from what We have provided them, they spend.', NULL, NULL, 'ea841a5ba37c045d673e649842ee560a5e4f30a0bb969621a0a664febc7f6c80'),
  ('en.sahih', 42, 39, 4311, 'And those who, when tyranny strikes them, they defend themselves,', NULL, NULL, 'feb53155abf2fd096697430d7da4291a97373b0c351169f7dd0fa940e89c2498'),
  ('en.sahih', 42, 40, 4312, 'And the retribution for an evil act is an evil one like it, but whoever pardons and makes reconciliation - his reward is [due] from Allah. Indeed, He does not like wrongdoers.', NULL, NULL, '654de5057c883bc6050f7cf636c2fa4e99335a0fff2805d02b7f2a99917ae2a0'),
  ('en.sahih', 42, 41, 4313, 'And whoever avenges himself after having been wronged - those have not upon them any cause [for blame].', NULL, NULL, '619738e845e24917a4c25e8ec58f56b418776a0f6097da054e3c1893300b200d'),
  ('en.sahih', 42, 42, 4314, 'The cause is only against the ones who wrong the people and tyrannize upon the earth without right. Those will have a painful punishment.', NULL, NULL, '397140ef0e6c505219feda9a60dfec38679644b281c0de3520d5700e48e81a49'),
  ('en.sahih', 42, 43, 4315, 'And whoever is patient and forgives - indeed, that is of the matters [requiring] determination.', NULL, NULL, '16b99ef9917fec8ef5fbf14446a0e48e13d9188cbfaa4124df11f7f556df8da7'),
  ('en.sahih', 42, 44, 4316, 'And he whom Allah sends astray - for him there is no protector beyond Him. And you will see the wrongdoers, when they see the punishment, saying, "Is there for return [to the former world] any way?"', NULL, NULL, '51cb2e8ec38388421525296a8687f0c591e3f4ebf5442b31abc7c52b3d9cbf54'),
  ('en.sahih', 42, 45, 4317, 'And you will see them being exposed to the Fire, humbled from humiliation, looking from [behind] a covert glance. And those who had believed will say, "Indeed, the [true] losers are the ones who lost themselves and their families on the Day of Resurrection. Unquestionably, the wrongdoers are in an enduring punishment."', NULL, NULL, '11c997b88346c7adb5831ff407196b713c1eac2a1c61fa7c8c446c6ba5805c82'),
  ('en.sahih', 42, 46, 4318, 'And there will not be for them any allies to aid them other than Allah. And whoever Allah sends astray - for him there is no way.', NULL, NULL, '67a46658d46ba4297196fc4192d77c5eb7d2024b4da3ce1ec38236e0a35fe468'),
  ('en.sahih', 42, 47, 4319, 'Respond to your Lord before a Day comes from Allah of which there is no repelling. No refuge will you have that day, nor for you will there be any denial.', NULL, NULL, 'b25a32d45d278d2588ffc6feffd60ff7c2fe54f81d1bcd9a1911e56df3b4b1e6'),
  ('en.sahih', 42, 48, 4320, 'But if they turn away - then We have not sent you, [O Muhammad], over them as a guardian; upon you is only [the duty of] notification. And indeed, when We let man taste mercy from us, he rejoices in it; but if evil afflicts him for what his hands have put forth, then indeed, man is ungrateful.', NULL, NULL, 'c0af08e7df468c3d16c3a6fca3bcb4fbd31cc3ccfc2420618c3b9aaaf55f7829'),
  ('en.sahih', 42, 49, 4321, 'To Allah belongs the dominion of the heavens and the earth; He creates what he wills. He gives to whom He wills female [children], and He gives to whom He wills males.', NULL, NULL, 'c347148e66a88e27e45f50416baa94665473bc31be21b2cc3a4038ea5260fc69'),
  ('en.sahih', 42, 50, 4322, 'Or He makes them [both] males and females, and He renders whom He wills barren. Indeed, He is Knowing and Competent.', NULL, NULL, '2bf68938be8e4d615910cdbe0281f8321783628c1a5791f7ef3c101184bbfc2a'),
  ('en.sahih', 42, 51, 4323, 'And it is not for any human being that Allah should speak to him except by revelation or from behind a partition or that He sends a messenger to reveal, by His permission, what He wills. Indeed, He is Most High and Wise.', NULL, NULL, '732bf9f660dab124496703e543e4d5891bfb8a31c9de184a632a7a129378b452'),
  ('en.sahih', 42, 52, 4324, 'And thus We have revealed to you an inspiration of Our command. You did not know what is the Book or [what is] faith, but We have made it a light by which We guide whom We will of Our servants. And indeed, [O Muhammad], you guide to a straight path -', NULL, NULL, '5199362bb495768e3571d044bd77553e485b4b3559cec019dfb6eff3176e93be'),
  ('en.sahih', 42, 53, 4325, 'The path of Allah, to whom belongs whatever is in the heavens and whatever is on the earth. Unquestionably, to Allah do [all] matters evolve.', NULL, NULL, 'c4188c1d701a50b73172f27e9e31fb7e703c3002ea0af95d8770c6b9a4a942f0'),
  ('en.sahih', 43, 1, 4326, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 43, 2, 4327, 'By the clear Book,', NULL, NULL, '8622bbf3188cb3f5caa6afb97bcf96475341de14784b0f24f9baa84ab9930964'),
  ('en.sahih', 43, 3, 4328, 'Indeed, We have made it an Arabic Qur''an that you might understand.', NULL, NULL, '23a4f68d946f6063fe858fde4904112b9cb2a2e36c946910d3049d1542a30506'),
  ('en.sahih', 43, 4, 4329, 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.', NULL, NULL, '2167802f11bc497be6c270191708d6598eeb22cbfb029c40e0c78105c3d85cea'),
  ('en.sahih', 43, 5, 4330, 'Then should We turn the message away, disregarding you, because you are a transgressing people?', NULL, NULL, '3511a5738962a16c49d354d69d038f64e262f965d527ec55b7e249426d34b10a'),
  ('en.sahih', 43, 6, 4331, 'And how many a prophet We sent among the former peoples,', NULL, NULL, '2617708903fca2fb63b1c884282ac19c245d4d7d3e91d63e4a56ece2700dd83c'),
  ('en.sahih', 43, 7, 4332, 'But there would not come to them a prophet except that they used to ridicule him.', NULL, NULL, '83ffe6715a896b0764e37a11e0fe8fd5ee6fcf73d54bd464fb9ff7499f816732'),
  ('en.sahih', 43, 8, 4333, 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.', NULL, NULL, '1c8d1726c4c9456c3b664cd8a42e1db3dd56bb38723f50140b6f6040a1e6f761'),
  ('en.sahih', 43, 9, 4334, 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing."', NULL, NULL, '256d7b50a47735ca2e21ae68143c7d13e1085fa57c8abc333646255911f728f3'),
  ('en.sahih', 43, 10, 4335, '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided', NULL, NULL, 'e93b92be85031c31f1cadfdae753162fdbae0326e6bddd3fa38026b2f3dd7a79'),
  ('en.sahih', 43, 11, 4336, 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -', NULL, NULL, 'add08ba53778651f0ecf20818c1bc0088d34d8e9fae9d6a5c8be7e25751bd489'),
  ('en.sahih', 43, 12, 4337, 'And who created the species, all of them, and has made for you of ships and animals those which you mount.', NULL, NULL, 'cf305c1ef0a809fda2d03f069b3d88bb34632a9d5dc0df93cf109a8cf72e3f4e'),
  ('en.sahih', 43, 13, 4338, 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.', NULL, NULL, '457c40f13778a3ce8a2a3bdcb69409dc7854ae46119f6ff6b1b494a8b6c6c38e'),
  ('en.sahih', 43, 14, 4339, 'And indeed we, to our Lord, will [surely] return."', NULL, NULL, '94ebe92be9fbc9a9743568b95e663ae96aa07ce17e6a7f1f7f2357600adc5c59'),
  ('en.sahih', 43, 15, 4340, 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.', NULL, NULL, '38476ebed1acc122499a0ae193de367d97b2071ad78d68c94bc1bc920070c945'),
  ('en.sahih', 43, 16, 4341, 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?', NULL, NULL, 'e09af583610559e40ccc43c18d2f315a72a244dce672b174e363c11739669237'),
  ('en.sahih', 43, 17, 4342, 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief.', NULL, NULL, 'f7293d215ba73017471045eb328c7da6d673d4649e5befe41779f8cbf2e90174'),
  ('en.sahih', 43, 18, 4343, 'So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?', NULL, NULL, 'c02f3a137af22a7f2b6729f279cfcaa60354ff6f5118e4f0463b0ffe3525d275'),
  ('en.sahih', 43, 19, 4344, 'And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.', NULL, NULL, 'aee3934dc0c65562268fb9ed37cdbd984606717849fd1070bb6cdc96797b5bd2'),
  ('en.sahih', 43, 20, 4345, 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but falsifying.', NULL, NULL, '4ec13490ca3e96d952fba1e1e9cab8814fc373879e202dad82a90f06fc4f31f9'),
  ('en.sahih', 43, 21, 4346, 'Or have We given them a book before the Qur''an to which they are adhering?', NULL, NULL, '7b6f5221fad7f123c492274f10c1a1dfe7b7f56b1571c586d516daac562e9f86'),
  ('en.sahih', 43, 22, 4347, 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."', NULL, NULL, '466b9e023e6a2c629f6a9349d2def449f9deaccf3124928595fa4f401653a69a'),
  ('en.sahih', 43, 23, 4348, 'And similarly, We did not send before you any warner into a city except that its affluent said, "Indeed, we found our fathers upon a religion, and we are, in their footsteps, following."', NULL, NULL, '4bff97719ef9f038226f49a8aa0956530d642de7edf562039f03b7d74e578cbc'),
  ('en.sahih', 43, 24, 4349, '[Each warner] said, "Even if I brought you better guidance than that [religion] upon which you found your fathers?" They said, "Indeed we, in that with which you were sent, are disbelievers."', NULL, NULL, 'ee54b6e0d23cb25412619b314a34804850a9d804238bb03895f0cb954a48e0e0'),
  ('en.sahih', 43, 25, 4350, 'So we took retribution from them; then see how was the end of the deniers.', NULL, NULL, 'ffb134b006d69665df21a682c10c18c3ae6a6bca054907b2dcf84e63582220f6'),
  ('en.sahih', 43, 26, 4351, 'And [mention, O Muhammad], when Abraham said to his father and his people, "Indeed, I am disassociated from that which you worship', NULL, NULL, 'c21bf300a36f61493a0507147ceeee66df72bd0b6ff30fe446b92442bbe90a97'),
  ('en.sahih', 43, 27, 4352, 'Except for He who created me; and indeed, He will guide me."', NULL, NULL, '74fe01929b52a09b852033700d0b184300147c86b9129246f8571cef48826f72'),
  ('en.sahih', 43, 28, 4353, 'And he made it a word remaining among his descendants that they might return [to it].', NULL, NULL, 'd3271db589cba1fd86671254302968ca2f2b4dd2ea871f6bb5cc3ad66334431e'),
  ('en.sahih', 43, 29, 4354, 'However, I gave enjoyment to these [people of Makkah] and their fathers until there came to them the truth and a clear Messenger.', NULL, NULL, '8c62b083fdc8b532b24762ffe0f0044b809b00e53398a99a9d0cc6f0c966660c'),
  ('en.sahih', 43, 30, 4355, 'But when the truth came to them, they said, "This is magic, and indeed we are, concerning it, disbelievers."', NULL, NULL, 'ad49f5997ff7585f9a4ca56d3664c6a56571dc8ca3c9dfdf3004199899a55342'),
  ('en.sahih', 43, 31, 4356, 'And they said, "Why was this Qur''an not sent down upon a great man from [one of] the two cities?"', NULL, NULL, '5bf33132e2d308f840e241223a4e6a10568a90472d4674283fffb36ed7cf4761'),
  ('en.sahih', 43, 32, 4357, 'Do they distribute the mercy of your Lord? It is We who have apportioned among them their livelihood in the life of this world and have raised some of them above others in degrees [of rank] that they may make use of one another for service. But the mercy of your Lord is better than whatever they accumulate.', NULL, NULL, '728e4cf41ec37ca5b519d8048eb4097940a7c9ab0f0ea7d007d049949250a276'),
  ('en.sahih', 43, 33, 4358, 'And if it were not that the people would become one community [of disbelievers], We would have made for those who disbelieve in the Most Merciful - for their houses - ceilings and stairways of silver upon which to mount', NULL, NULL, '0e6a9c9710e4c4f90f655d128798cb53c35c7b15d1113729e9d84d8b30595d13'),
  ('en.sahih', 43, 34, 4359, 'And for their houses - doors and couches [of silver] upon which to recline', NULL, NULL, 'b34830971c4f8e1267994fddc3a47c0d7050d2875243671cd1dbbd018acaaadb'),
  ('en.sahih', 43, 35, 4360, 'And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous.', NULL, NULL, 'c43453842e5aac76d8ef47eda4d8222119f93a48afdb773fe5fd84514c5fdcff'),
  ('en.sahih', 43, 36, 4361, 'And whoever is blinded from remembrance of the Most Merciful - We appoint for him a devil, and he is to him a companion.', NULL, NULL, '52f15fc27d0601813679a72879b2455ba6024310299bbaade1d94ed49d621fa9'),
  ('en.sahih', 43, 37, 4362, 'And indeed, the devils avert them from the way [of guidance] while they think that they are [rightly] guided', NULL, NULL, '8a664169b83231deebec81ac64f2465316dfeacf6c9aab26f72c7989bf784bac'),
  ('en.sahih', 43, 38, 4363, 'Until, when he comes to Us [at Judgement], he says [to his companion], "Oh, I wish there was between me and you the distance between the east and west - how wretched a companion."', NULL, NULL, '5c3a9c2f98951e2413705d7aeebaddb67bd91763341922a95d7b2805eafb8f9a'),
  ('en.sahih', 43, 39, 4364, 'And never will it benefit you that Day, when you have wronged, that you are [all] sharing in the punishment.', NULL, NULL, '36243f28657b6a4ec529e6a0715db860c8a662d941af2b8790e189bfc146b3e0'),
  ('en.sahih', 43, 40, 4365, 'Then will you make the deaf hear, [O Muhammad], or guide the blind or he who is in clear error?', NULL, NULL, '91359e83a7b8a6d2a4742e05acc25ceda3bf66fb9b2034d0aae1f6067d2d5d39'),
  ('en.sahih', 43, 41, 4366, 'And whether [or not] We take you away [in death], indeed, We will take retribution upon them.', NULL, NULL, '74ac99613ff0a4b032d0cf708d28e1977d0618e0d816793559b2393eb769b9d1'),
  ('en.sahih', 43, 42, 4367, 'Or whether [or not] We show you that which We have promised them, indeed, We are Perfect in Ability.', NULL, NULL, 'ebd9c3a59b6b97587e5dbaf7f06b5302a6bde3e8f38ef5f09d367c29b7f35203'),
  ('en.sahih', 43, 43, 4368, 'So adhere to that which is revealed to you. Indeed, you are on a straight path.', NULL, NULL, '8ac35a695aea87aa9844821b632863f426f27a2fc9b0a2071314e8b5eb37bd51'),
  ('en.sahih', 43, 44, 4369, 'And indeed, it is a remembrance for you and your people, and you [all] are going to be questioned.', NULL, NULL, '8531a169db5de11cc97503bd371bdd92f8d87a7ed96fe47b4f95f1651c4719d7'),
  ('en.sahih', 43, 45, 4370, 'And ask those We sent before you of Our messengers; have We made besides the Most Merciful deities to be worshipped?', NULL, NULL, '18fb8679750366188abe22e4ba59d3bf0b30b783403381dd364a5fa88eb4265a'),
  ('en.sahih', 43, 46, 4371, 'And certainly did We send Moses with Our signs to Pharaoh and his establishment, and he said, "Indeed, I am the messenger of the Lord of the worlds."', NULL, NULL, '3c40b7a717f23aff4b2be9c45426623b512e2adf1bf5fffd78e9d54b2d09d953'),
  ('en.sahih', 43, 47, 4372, 'But when he brought them Our signs, at once they laughed at them.', NULL, NULL, '5523660d2fa245a8a7d7ebcdecaf230f23420887ad3061a3d143a53571e7ba7b'),
  ('en.sahih', 43, 48, 4373, 'And We showed them not a sign except that it was greater than its sister, and We seized them with affliction that perhaps they might return [to faith].', NULL, NULL, '8dcf4837c7100d7290028b7a071535b42774a2cca833d1ca7117da83ed740bbf'),
  ('en.sahih', 43, 49, 4374, 'And they said [to Moses], "O magician, invoke for us your Lord by what He has promised you. Indeed, we will be guided."', NULL, NULL, '0ec0e47940db9f6810e485987f1a8e3dd79f6f801e95fb68506c862e2ab9f2f0'),
  ('en.sahih', 43, 50, 4375, 'But when We removed from them the affliction, at once they broke their word.', NULL, NULL, 'f44e7be85a1a2018dbe1a827eae8e67a8d221e810e326b6b4fb667e903d712e7'),
  ('en.sahih', 43, 51, 4376, 'And Pharaoh called out among his people; he said, "O my people, does not the kingdom of Egypt belong to me, and these rivers flowing beneath me; then do you not see?', NULL, NULL, 'f2426286cef1e476a2df61325fd2922af96bf340b756bb9b9eae68c0a49d5640'),
  ('en.sahih', 43, 52, 4377, 'Or am I [not] better than this one who is insignificant and hardly makes himself clear?', NULL, NULL, '71a9059c01af98df66d5a59be70a450554e1522d5175582bac814dfeadabc76f'),
  ('en.sahih', 43, 53, 4378, 'Then why have there not been placed upon him bracelets of gold or come with him the angels in conjunction?"', NULL, NULL, '1a5fd435cced7df471b57f3d804b891544aae152622fd76f0bfd349f97afcea9'),
  ('en.sahih', 43, 54, 4379, 'So he bluffed his people, and they obeyed him. Indeed, they were [themselves] a people defiantly disobedient [of Allah].', NULL, NULL, '299ef063b40322b8b95318cc69310c908d0a78de474f5a95119766a3e1ded04c'),
  ('en.sahih', 43, 55, 4380, 'And when they angered Us, We took retribution from them and drowned them all.', NULL, NULL, '38e99a34843ba39905b908e7a1dea440f7a1c9b1508c0d380bff764e0639e4db'),
  ('en.sahih', 43, 56, 4381, 'And We made them a precedent and an example for the later peoples.', NULL, NULL, 'dd1d01480d8c019789b89347caaf2dedf48400e05517dbd20391ceb58a6b507e'),
  ('en.sahih', 43, 57, 4382, 'And when the son of Mary was presented as an example, immediately your people laughed aloud.', NULL, NULL, '99768a0ed13adab7b7114f5f47d8c6537562c3b62be8467bf1b66d3f686c4ff7'),
  ('en.sahih', 43, 58, 4383, 'And they said, "Are your gods better, or is he?" They did not present the comparison except for [mere] argument. But, [in fact], they are a people prone to dispute.', NULL, NULL, 'c79f2a5900c523c047f48c7ecd8fae701ee09fb7de4aa2332facbbd9bb829759'),
  ('en.sahih', 43, 59, 4384, 'Jesus was not but a servant upon whom We bestowed favor, and We made him an example for the Children of Israel.', NULL, NULL, '14f210eb63d027c51541881269958da7d726cf108bbeece135a3777d811831ab'),
  ('en.sahih', 43, 60, 4385, 'And if We willed, We could have made [instead] of you angels succeeding [one another] on the earth.', NULL, NULL, '77df9aa446cf40f73a9ba58919ceac1c0ac7c9d140eae41a3d916fff1b8eea56'),
  ('en.sahih', 43, 61, 4386, 'And indeed, Jesus will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path.', NULL, NULL, 'c14cac7d15a7f3179992abab7ebd2d37dd95272eff9931747311028392fb52d9'),
  ('en.sahih', 43, 62, 4387, 'And never let Satan avert you. Indeed, he is to you a clear enemy.', NULL, NULL, 'e5a280727a3e28c15cc08f283ec1ba57549bbe0ec6fb5086e435dbe8b34b3650'),
  ('en.sahih', 43, 63, 4388, 'And when Jesus brought clear proofs, he said, "I have come to you with wisdom and to make clear to you some of that over which you differ, so fear Allah and obey me.', NULL, NULL, '0a5a95872852f6fb8caf815450158f3b14a6c60b723021084ef621e6b2762087'),
  ('en.sahih', 43, 64, 4389, 'Indeed, Allah is my Lord and your Lord, so worship Him. This is a straight path."', NULL, NULL, 'f59597bac65fbc29e905fe6cd14a678a3e47f90b5175d2689d5c5a819b3ae9c7'),
  ('en.sahih', 43, 65, 4390, 'But the denominations from among them differed [and separated], so woe to those who have wronged from the punishment of a painful Day.', NULL, NULL, '7fc2b8ee4f118ac8d9ab433102aa7fa33f76e8266c9dc6ad6cf32e2544f9ff32'),
  ('en.sahih', 43, 66, 4391, 'Are they waiting except for the Hour to come upon them suddenly while they perceive not?', NULL, NULL, 'ac80b3a769d019b812812454f0ba4d97238723034027775dc619b60fcc80e020'),
  ('en.sahih', 43, 67, 4392, 'Close friends, that Day, will be enemies to each other, except for the righteous', NULL, NULL, '0d1229cba39fa53a3043831fbf8ebeca3a9d79896c65486e30e915bbbd03d02a'),
  ('en.sahih', 43, 68, 4393, '[To whom Allah will say], "O My servants, no fear will there be concerning you this Day, nor will you grieve,', NULL, NULL, 'cc98290053593eac11899c3ee408642b22caef31c1aeb1d85dabef1473887127'),
  ('en.sahih', 43, 69, 4394, '[You] who believed in Our verses and were Muslims.', NULL, NULL, '3389d1ff151bdf14519d9ae6af085e81042458e91036b65d8989cd81cf12169e'),
  ('en.sahih', 43, 70, 4395, 'Enter Paradise, you and your kinds, delighted."', NULL, NULL, 'b2c6eaf292b8c662774d4ad7595324338587b3d7ab26d5c68c2d9b7b73c64e19'),
  ('en.sahih', 43, 71, 4396, 'Circulated among them will be plates and vessels of gold. And therein is whatever the souls desire and [what] delights the eyes, and you will abide therein eternally.', NULL, NULL, '1509b6a4d064942aaf99f97bea47a49e6090fb155641f817e4b6c431842e9ba6'),
  ('en.sahih', 43, 72, 4397, 'And that is Paradise which you are made to inherit for what you used to do.', NULL, NULL, 'f16a8ae3427904ff4480754242925a0ea0b441fc3edd26b6c365f5113c81e84e'),
  ('en.sahih', 43, 73, 4398, 'For you therein is much fruit from which you will eat.', NULL, NULL, '2922731c07bd2e4c365cbc7b7c6eaa7c46e222a0903824afa9813f91021d886f'),
  ('en.sahih', 43, 74, 4399, 'Indeed, the criminals will be in the punishment of Hell, abiding eternally.', NULL, NULL, '26742a972c743fd002ac7e5e1789b6bad6bf5d567e947ee3f4f677f86755b57e'),
  ('en.sahih', 43, 75, 4400, 'It will not be allowed to subside for them, and they, therein, are in despair.', NULL, NULL, 'd5ea316d9096a1d55c10ca1a5e4cffdb950b77431ed7ca8f73fbe4e5dea9a832')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 43, 76, 4401, 'And We did not wrong them, but it was they who were the wrongdoers.', NULL, NULL, '587d7503c15ca2216d72266944e78ed587669b23d22b5ae63b894da263354317'),
  ('en.sahih', 43, 77, 4402, 'And they will call, "O Malik, let your Lord put an end to us!" He will say, "Indeed, you will remain."', NULL, NULL, '9082762d4d4b5f0dd342199d6fef7f3bc7b043547433c9b55186b689153c2103'),
  ('en.sahih', 43, 78, 4403, 'We had certainly brought you the truth, but most of you, to the truth, were averse.', NULL, NULL, '84f8f519ca33f13b46153f09ccb14d721c4f7b6109495e373c2a828f0d5a36cf'),
  ('en.sahih', 43, 79, 4404, 'Or have they devised [some] affair? But indeed, We are devising [a plan].', NULL, NULL, '54ca63c12b11a4e349341bfd26fb9b13dbe63d7c1f1acb141bd1ffa3f3a49686'),
  ('en.sahih', 43, 80, 4405, 'Or do they think that We hear not their secrets and their private conversations? Yes, [We do], and Our messengers are with them recording.', NULL, NULL, '0ce106b151577e0f1df1b0c401a00039b27322eb8343bffeca404343af53e75f'),
  ('en.sahih', 43, 81, 4406, 'Say, [O Muhammad], "If the Most Merciful had a son, then I would be the first of [his] worshippers."', NULL, NULL, '847de059d027a504fb2d0735dca03e5d157bd800593ef2252f8c919f462db431'),
  ('en.sahih', 43, 82, 4407, 'Exalted is the Lord of the heavens and the earth, Lord of the Throne, above what they describe.', NULL, NULL, '0bf44d020a9ddc1101a5887e4669d679dacf2f1871513eed89f3058143d29d98'),
  ('en.sahih', 43, 83, 4408, 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised.', NULL, NULL, 'cf9317246dc5eb5bc2005fcc3f68aa19bccb889cf289d6d19733e57f11731b14'),
  ('en.sahih', 43, 84, 4409, 'And it is Allah who is [the only] deity in the heaven, and on the earth [the only] deity. And He is the Wise, the Knowing.', NULL, NULL, 'f57ad066576912752ae336dc456ddc2aadf3752e414deebed879e378b16863d9'),
  ('en.sahih', 43, 85, 4410, 'And blessed is He to whom belongs the dominion of the heavens and the earth and whatever is between them and with whom is knowledge of the Hour and to whom you will be returned.', NULL, NULL, '7a18b0140eb0d11bfb92bf8fb875028c7bec52d2d5a9523de84b9d6ef789d61c'),
  ('en.sahih', 43, 86, 4411, 'And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know.', NULL, NULL, 'a9ef8e6329009fd43427778250246d396d496c777c6990177dbe4c4eb0601cea'),
  ('en.sahih', 43, 87, 4412, 'And if you asked them who created them, they would surely say, "Allah." So how are they deluded?', NULL, NULL, 'b15ae04da56385166f9d8dbaeb7b0ce84156e6ab60da37b2ee48df59390627b3'),
  ('en.sahih', 43, 88, 4413, 'And [Allah acknowledges] his saying, "O my Lord, indeed these are a people who do not believe."', NULL, NULL, 'b90a9e8ca05a30f3fbe9d2752a437fa03f3982e5b23e606a7de35c61e069e0c8'),
  ('en.sahih', 43, 89, 4414, 'So turn aside from them and say, "Peace." But they are going to know.', NULL, NULL, 'a2c9baa4770ce9efdf442dd450be60ec4caecfb35573330ae17f3f90c66b0572'),
  ('en.sahih', 44, 1, 4415, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 44, 2, 4416, 'By the clear Book,', NULL, NULL, '8622bbf3188cb3f5caa6afb97bcf96475341de14784b0f24f9baa84ab9930964'),
  ('en.sahih', 44, 3, 4417, 'Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind].', NULL, NULL, 'a50d9b4732de4c1c3d40beb37fde03422e3e7e26f0882d19f0cdaea2cda727d9'),
  ('en.sahih', 44, 4, 4418, 'On that night is made distinct every precise matter -', NULL, NULL, 'a4a6b0d044e14e93d3a077b50e3ccb1ee4065c956d4b6bbd1946142609632328'),
  ('en.sahih', 44, 5, 4419, '[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]', NULL, NULL, '4250a9df315caa1836a74dca2b1c07a71d64348fab42a63a101ecc4f94c4ee04'),
  ('en.sahih', 44, 6, 4420, 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing.', NULL, NULL, 'c9ddddcf27753641cb2cb3ac1aa28bffa1a2e867818c6f5924e5b7bcff209f63'),
  ('en.sahih', 44, 7, 4421, 'Lord of the heavens and the earth and that between them, if you would be certain.', NULL, NULL, 'caa92f7ae8649ef9424c8c8b86004917592af53f79b5163b28900393be7bdb22'),
  ('en.sahih', 44, 8, 4422, 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.', NULL, NULL, 'ec6be9d92b0e715a12efb492dee9edbf75e0c86f28fc0649a32d1cdc0140da49'),
  ('en.sahih', 44, 9, 4423, 'But they are in doubt, amusing themselves.', NULL, NULL, '805227ed0621630c7f008abc424a00462ab9e0f128e35b47dc61bbeb817fc774'),
  ('en.sahih', 44, 10, 4424, 'Then watch for the Day when the sky will bring a visible smoke.', NULL, NULL, 'bd108d3da338839cc04a5703aac27c6121445cb3a5c3cfff47fe4cf7c7e181f8'),
  ('en.sahih', 44, 11, 4425, 'Covering the people; this is a painful torment.', NULL, NULL, 'ea2429bdec8cbfeae8ed27c45429c90f7c8d40f7e5e50f4b4a307c6b0e3e0253'),
  ('en.sahih', 44, 12, 4426, '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."', NULL, NULL, 'def6077bf3f5688c466b0ae59501b69df70c89e5a4b5367958ce1858c4805cb2'),
  ('en.sahih', 44, 13, 4427, 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.', NULL, NULL, 'fea8a5bf6505cc0c799c506dfa139aadf00bf75d7d826f6ea3c992d5e128548a'),
  ('en.sahih', 44, 14, 4428, 'Then they turned away from him and said, "[He was] taught [and is] a madman."', NULL, NULL, '5599b7b0de5989a89eb088daa38d5dcb4c55cba073e32b87da325721b71efc11'),
  ('en.sahih', 44, 15, 4429, 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].', NULL, NULL, '83472a9b036742611e3e18a0798765abfaf8c56603dbb6eb621b8c7ae28253a1'),
  ('en.sahih', 44, 16, 4430, 'The Day We will strike with the greatest assault, indeed, We will take retribution.', NULL, NULL, '3ba1500a61e050214e35334f1d5391e16d3a78138198470cb921f2005ce5f74a'),
  ('en.sahih', 44, 17, 4431, 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,', NULL, NULL, 'e247fe54235f7365d04853fa4ffe4e87be37d2898e0c67592b94f324f57e76fb'),
  ('en.sahih', 44, 18, 4432, '[Saying], "Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,"', NULL, NULL, 'e4d1b96d72a35722a18d5a86c5264d0667432a81d855f54e4aee2cc0ca583b79'),
  ('en.sahih', 44, 19, 4433, 'And [saying], "Be not haughty with Allah. Indeed, I have come to you with clear authority.', NULL, NULL, '10ac3bb2540340b573491cf3554fa30d2734fec3758f6febe1c4da606d1ca315'),
  ('en.sahih', 44, 20, 4434, 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.', NULL, NULL, '4ddf39c3957cd7db8a8ba4814eb3b042247fbffee90696ac37f6782336899ef1'),
  ('en.sahih', 44, 21, 4435, 'But if you do not believe me, then leave me alone."', NULL, NULL, 'b147425ad789735580c24856e73c8868016de32ee496eb24f65b8d63a46beeeb'),
  ('en.sahih', 44, 22, 4436, 'And [finally] he called to his Lord that these were a criminal people.', NULL, NULL, '22017f3042218ad5d6567a129e249cb72ffca792236873baa79789f5cf074cb2'),
  ('en.sahih', 44, 23, 4437, '[Allah said], "Then set out with My servants by night. Indeed, you are to be pursued.', NULL, NULL, 'a0eb62a7fc2f5fafd13e31969edd88f8e8f48002ab451a82b32e7803c6b276b1'),
  ('en.sahih', 44, 24, 4438, 'And leave the sea in stillness. Indeed, they are an army to be drowned."', NULL, NULL, '5054cd9c0f9097b22c867f6b5fce6b296e19cdd086cca0a434bef26e2d9ddb21'),
  ('en.sahih', 44, 25, 4439, 'How much they left behind of gardens and springs', NULL, NULL, 'b85db6c1dd891e694aec85c7fe76f82d821767d4f46c08fc147b9289f95b379a'),
  ('en.sahih', 44, 26, 4440, 'And crops and noble sites', NULL, NULL, '2305bd509d79aa396f30f4317fe1add93114be4e49e9f3e00155af443d38b6a6'),
  ('en.sahih', 44, 27, 4441, 'And comfort wherein they were amused.', NULL, NULL, '0c6e93478e2c000020b27aa277022a76e0dad1864419fcc83c40abe1270b7872'),
  ('en.sahih', 44, 28, 4442, 'Thus. And We caused to inherit it another people.', NULL, NULL, '25131bcce87d7c7389937b884084b02d3448189c76f2aa340d00038447902079'),
  ('en.sahih', 44, 29, 4443, 'And the heaven and earth wept not for them, nor were they reprieved.', NULL, NULL, '13d55e7196f0293f71f603435bf9a1852ac644807050e63b1f51ee7af47f823c'),
  ('en.sahih', 44, 30, 4444, 'And We certainly saved the Children of Israel from the humiliating torment -', NULL, NULL, '384da848fad02f1759a67c04c71900f54d4180ec275a47aed205d1bab70ea5f4'),
  ('en.sahih', 44, 31, 4445, 'From Pharaoh. Indeed, he was a haughty one among the transgressors.', NULL, NULL, '12e7619e0a47d3ac52f4120699828082ee01bd4b74db4128f508c1c542c527c4'),
  ('en.sahih', 44, 32, 4446, 'And We certainly chose them by knowledge over [all] the worlds.', NULL, NULL, '6e82abe2af6a378f917b913074be9fc3c3d8830e4619e3b9d561191012c7e745'),
  ('en.sahih', 44, 33, 4447, 'And We gave them of signs that in which there was a clear trial.', NULL, NULL, '04bf42c42545d3454fc872188b2e9342207baa1e0b257892e185d6a0f0701979'),
  ('en.sahih', 44, 34, 4448, 'Indeed, these [disbelievers] are saying,', NULL, NULL, 'edce12b45e7f21f69d0c1f3a9e907a8b66cf40e299ddbf3ce99032caaa2eb78f'),
  ('en.sahih', 44, 35, 4449, '"There is not but our first death, and we will not be resurrected.', NULL, NULL, '0a18cf31a93e53ea8c4ae0832987c6820eee7f5eba18fdebef4858d1f7d82d44'),
  ('en.sahih', 44, 36, 4450, 'Then bring [back] our forefathers, if you should be truthful."', NULL, NULL, '9f9906ff5170710c59b933a3433987ed8aeac41ebc08ab2e6a0a7293d2d6cf17'),
  ('en.sahih', 44, 37, 4451, 'Are they better or the people of Tubba'' and those before them? We destroyed them, [for] indeed, they were criminals.', NULL, NULL, '86d932255675fb20892e8f3f956940a9970a650f0cebe9419f78e155ceafd6e2'),
  ('en.sahih', 44, 38, 4452, 'And We did not create the heavens and earth and that between them in play.', NULL, NULL, '386f7af1a082decfa49c4c6e38dc41affef3e43ec6cadc9905a30477f5f2dfc6'),
  ('en.sahih', 44, 39, 4453, 'We did not create them except in truth, but most of them do not know.', NULL, NULL, 'c2e7565bea2a86a3fe0435f8ede95c2e97d6880ed5ca8307d5b40439bc9dd390'),
  ('en.sahih', 44, 40, 4454, 'Indeed, the Day of Judgement is the appointed time for them all -', NULL, NULL, 'ec11ac032603f9ad207b88f2af6fffc5561c0e5909903467f4c9469c2a915713'),
  ('en.sahih', 44, 41, 4455, 'The Day when no relation will avail a relation at all, nor will they be helped -', NULL, NULL, '11108ee18f4384cc0b4c389c2e097209a6e09453ecb2a302da26836a47ea69e1'),
  ('en.sahih', 44, 42, 4456, 'Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful.', NULL, NULL, '6410cde8577aa1b257429b5bb8792a06ab6c03629a248aad96adc1f11aedefa1'),
  ('en.sahih', 44, 43, 4457, 'Indeed, the tree of zaqqum', NULL, NULL, '31c358aa08b44e4b31b6cba3d8235e6574f051828d57fbb8b8ed9970370a6370'),
  ('en.sahih', 44, 44, 4458, 'Is food for the sinful.', NULL, NULL, 'dbdc5f7d90188a648faea835939eb817f26b1a33b70abc0715576b9d08863eef'),
  ('en.sahih', 44, 45, 4459, 'Like murky oil, it boils within bellies', NULL, NULL, '7421df343c03e9162c7c028328969035b3793ef0a5df86da987c18f55ec10ee0'),
  ('en.sahih', 44, 46, 4460, 'Like the boiling of scalding water.', NULL, NULL, '3101e14a9bc7de1fb7e452a89b40f384ef89a1422d25dafafb635ff8765dab43'),
  ('en.sahih', 44, 47, 4461, '[It will be commanded], "Seize him and drag him into the midst of the Hellfire,', NULL, NULL, 'b6e83169dbaa8b7e46dad9f0a0667b2d6902a63583cf27e1273c24413c53a99a'),
  ('en.sahih', 44, 48, 4462, 'Then pour over his head from the torment of scalding water."', NULL, NULL, '97dbed80b3d51eb3235ab48618fecdf947aa90a668c4ee422241bd8a125da964'),
  ('en.sahih', 44, 49, 4463, '[It will be said], "Taste! Indeed, you are the honored, the noble!', NULL, NULL, '3ae904318bf48f1cd9b0cd1c313b16cb30129476ae1f0da50524c60165856179'),
  ('en.sahih', 44, 50, 4464, 'Indeed, this is what you used to dispute."', NULL, NULL, '0e5abc8d49f3b2f5b3acbbe69ec6f87cc8a159d6c7fb69c904db709b6fbbd6bc'),
  ('en.sahih', 44, 51, 4465, 'Indeed, the righteous will be in a secure place;', NULL, NULL, '4777ad587dddeedfb4c2b54f0bb61ff02a460cd5512d9d072f85031bf76d6edd'),
  ('en.sahih', 44, 52, 4466, 'Within gardens and springs,', NULL, NULL, '64c8d1272cc5212e9fbbe3585ebb9540904cd4198d297b73c775e1ebae24dcd7'),
  ('en.sahih', 44, 53, 4467, 'Wearing [garments of] fine silk and brocade, facing each other.', NULL, NULL, '7764f634374b93773922c8f4900eb6895e4aa10075bac25bce906643ccbc0c29'),
  ('en.sahih', 44, 54, 4468, 'Thus. And We will marry them to fair women with large, [beautiful] eyes.', NULL, NULL, 'ea3197d92395654200257b4e3e84cd5d2630e9edaea5dfbbd680c7f8c5a533c3'),
  ('en.sahih', 44, 55, 4469, 'They will call therein for every [kind of] fruit - safe and secure.', NULL, NULL, '06fa6dffc09d7dd629d866e5afe204b23b2b912ad737d377ccb993144707c10f'),
  ('en.sahih', 44, 56, 4470, 'They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire', NULL, NULL, 'e94fe3a204b74dc7232ea4c044ac822cd781680798083b6b46adbb0cdf4be94e'),
  ('en.sahih', 44, 57, 4471, 'As bounty from your Lord. That is what is the great attainment.', NULL, NULL, '23dfac958600396a0b1315e456fea507927bdb602c20b1d5666a6d4d774ec6b6'),
  ('en.sahih', 44, 58, 4472, 'And indeed, We have eased the Qur''an in your tongue that they might be reminded.', NULL, NULL, '53986ab8c109e689e572905b6120f57b079cfa015971f0be804ec7f2fc4584ca'),
  ('en.sahih', 44, 59, 4473, 'So watch, [O Muhammad]; indeed, they are watching [for your end].', NULL, NULL, '3aafecae1c31524efae93c7730448b40149a4daa68e7ce6aa3f6cf1d62af30c0'),
  ('en.sahih', 45, 1, 4474, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 45, 2, 4475, 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', NULL, NULL, '111ab390c01b279db09964e008c1e94f12e4e326c866c3a8b1e8fff9eaf267ea'),
  ('en.sahih', 45, 3, 4476, 'Indeed, within the heavens and earth are signs for the believers.', NULL, NULL, 'aeee35dc74bb066bf61aeebd8ae946cd9ee988fed5c1ed0c4c8d0baf533ef170'),
  ('en.sahih', 45, 4, 4477, 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].', NULL, NULL, '4a50b37f84b8320cb450a0335b4c05f49cbe85ebf1a91cd27ec40491e993e771'),
  ('en.sahih', 45, 5, 4478, 'And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.', NULL, NULL, '3336bb9c20ecb59847951a559b6fe1c2753f6eed2f8daa96207c9300b8ff6955'),
  ('en.sahih', 45, 6, 4479, 'These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?', NULL, NULL, 'caf9c34db17f071d29f2c485a86f49dd77cbc59df2901be4a628f54432b9bdbe'),
  ('en.sahih', 45, 7, 4480, 'Woe to every sinful liar', NULL, NULL, '1f65a536c41a5e9d52ee91b3fe8194199ac217c6457792a9aad9b59d866ecbcf'),
  ('en.sahih', 45, 8, 4481, 'Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.', NULL, NULL, '2eca147a65347448875f8e41fa1cad953cd7b4d13c0e1230f77043228686bdc4'),
  ('en.sahih', 45, 9, 4482, 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.', NULL, NULL, 'f44457ad3609194c2e6bb61d55d0cdfb3c60f320e7224603e1ac6b5c71de565d'),
  ('en.sahih', 45, 10, 4483, 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment.', NULL, NULL, '13d6ebf036ebacf18750f57aad76c5143a06f92dda6bbedc8f9d390ee1873f84'),
  ('en.sahih', 45, 11, 4484, 'This [Qur''an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.', NULL, NULL, '8860155d56d95a735a3074a24b109f3783ed1da65ef79a2dbc3bdce8a1b135a7'),
  ('en.sahih', 45, 12, 4485, 'It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.', NULL, NULL, '4e5efda6af3ee465de9a417b4031ef073a9a60e3165a96e207b9d1d8369a7366'),
  ('en.sahih', 45, 13, 4486, 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.', NULL, NULL, 'caee0d0dff398fe8050e722b6dabc8eda833ae442580ee752cac857ecaf8b05a'),
  ('en.sahih', 45, 14, 4487, 'Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn.', NULL, NULL, '598d91e48b27feb1b295897c619fde27abd150d7af51ecb133bf58eb5ab93fd1'),
  ('en.sahih', 45, 15, 4488, 'Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned.', NULL, NULL, 'a9d29cf8639c7b30f37ebd15d80f3963cf2df3152de66831a57d33c18c8230e5'),
  ('en.sahih', 45, 16, 4489, 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.', NULL, NULL, '8c46deba3f49ac32e2fd9a5c203b59226c65ecb15a8a484723bf2fa7588fd8bd'),
  ('en.sahih', 45, 17, 4490, 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.', NULL, NULL, '7c6f7b6ca0c61a084cfc218f8ff412c5613f88f71fc0374d26c8ac30558bfab6'),
  ('en.sahih', 45, 18, 4491, 'Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.', NULL, NULL, 'c70a652b536038eace198d7a8262e42f2362ebaaba81b52f6b3f638884521e52'),
  ('en.sahih', 45, 19, 4492, 'Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous.', NULL, NULL, '7fd38975e285b6dd4cfbec7f8df5dc40f8a95aa3c7eccfce5be83efd78d2badf'),
  ('en.sahih', 45, 20, 4493, 'This [Qur''an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].', NULL, NULL, 'fa99cf74f2fcfc1d3e7a56b03078479dd007d3465399c782eaf926028d64f32d'),
  ('en.sahih', 45, 21, 4494, 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge.', NULL, NULL, 'a2196c6411efad43ef27282a765e79030e737952aae3318e6c76b44e4d08de29'),
  ('en.sahih', 45, 22, 4495, 'And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.', NULL, NULL, '68ee490a5cc336951402bc397eed09464040f37fc80a55f7cf9798bc6bae21b1'),
  ('en.sahih', 45, 23, 4496, 'Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?', NULL, NULL, '58ed2f034d7572e21a1d5a6ea39f126ed402eb02cdf9384f63619d1cd93d58b6'),
  ('en.sahih', 45, 24, 4497, 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.', NULL, NULL, '8e4f798b3af55f8c86f9dee2bdc056800041af47e2352447b4ab918a3795b839'),
  ('en.sahih', 45, 25, 4498, 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."', NULL, NULL, '1033114bc3a00f810f03451fa664f88ae39b744e0e3104a4852e2eb08a38403c'),
  ('en.sahih', 45, 26, 4499, 'Say, "Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."', NULL, NULL, '108e1324a47a6f231fd454723d78c128fdc35830643abcb8eab6575605db674e'),
  ('en.sahih', 45, 27, 4500, 'And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.', NULL, NULL, 'd9da0a581fad570929ac0cbb96fcabd8a4830e660b3723d45b5cd518987239f2')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 45, 28, 4501, 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.', NULL, NULL, '7999ed6f848fe00a728b95de48cc280620749e4654e95d5481232b0b56f8125d'),
  ('en.sahih', 45, 29, 4502, 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."', NULL, NULL, '85e5f44e82109866ce8b94e05621c32a017761a59f36040a3b24641953fefe1a'),
  ('en.sahih', 45, 30, 4503, 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.', NULL, NULL, '7f460226ffc55082cde3f1d0e235a4992cfb445a5b13ee935cc5e3d8335c6650'),
  ('en.sahih', 45, 31, 4504, 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a people of criminals?', NULL, NULL, '1740f444884962c018b26b8b62d0e1b42ead3a4beae4dcccb39e666f52280e23'),
  ('en.sahih', 45, 32, 4505, 'And when it was said, ''Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,'' you said, ''We know not what is the Hour. We assume only assumption, and we are not convinced.'' "', NULL, NULL, '8ab9f2eeb7d6456c63ac6541a7f6e71721c4e1d92f0ee7563e27357e3525eb1d'),
  ('en.sahih', 45, 33, 4506, 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.', NULL, NULL, 'cb4323533ea798b296c954476fb6ad32a1c51c5cad523f80d5f1b0a4bc5cd033'),
  ('en.sahih', 45, 34, 4507, 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.', NULL, NULL, 'afb01f527c720b1e78492a1913f677fa3949078b0816d91d9cd79d0962e1fc16'),
  ('en.sahih', 45, 35, 4508, 'That is because you took the verses of Allah in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allah].', NULL, NULL, '9ecc8a3df6f825de79c7f0eab6e30d17643894190afa051c3aa2290d697a77bb'),
  ('en.sahih', 45, 36, 4509, 'Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.', NULL, NULL, '5039d343dead206236f3254545eccd9321445fbbca715f3ffa08b85b42d8277d'),
  ('en.sahih', 45, 37, 4510, 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.', NULL, NULL, '23b355ce64dc296da813bdebecb12cc8d730ad33f2c9ae658c000d2095b280af'),
  ('en.sahih', 46, 1, 4511, 'Ha, Meem.', NULL, NULL, '3ab7a7c4fa9c216ad28412a31c1b51559cb5b9eb4853a1dee507d3e8e61f52d6'),
  ('en.sahih', 46, 2, 4512, 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.', NULL, NULL, '111ab390c01b279db09964e008c1e94f12e4e326c866c3a8b1e8fff9eaf267ea'),
  ('en.sahih', 46, 3, 4513, 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.', NULL, NULL, '3c85de1e3e3ef6705a09e8cafa89559dc5f6b5fc28d134ace61c8228d8e08c37'),
  ('en.sahih', 46, 4, 4514, 'Say, [O Muhammad], "Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."', NULL, NULL, 'f3910bf0d99b89e5156ebbb4f45223fbf914786579a3b78948f6639667f5e501'),
  ('en.sahih', 46, 5, 4515, 'And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware.', NULL, NULL, '6032cf6ef9b21cd8e1943cd38544da070c59301fe0f3494d034bc445f5dd74d3'),
  ('en.sahih', 46, 6, 4516, 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.', NULL, NULL, '891d03cb4bb70e28666682061ba1b38ce548f66f042bb20a4e59a6cbcf85033b'),
  ('en.sahih', 46, 7, 4517, 'And when Our verses are recited to them as clear evidences, those who disbelieve say of the truth when it has come to them, "This is obvious magic."', NULL, NULL, '8155a710ea4f96062288515d0d3d7726fdcc88a5bda863de16624b39745a48f2'),
  ('en.sahih', 46, 8, 4518, 'Or do they say, "He has invented it?" Say, "If I have invented it, you will not possess for me [the power of protection] from Allah at all. He is most knowing of that in which you are involved. Sufficient is He as Witness between me and you, and He is the Forgiving the Merciful."', NULL, NULL, 'ab98e32b7ef4e499e37efb11378edf5eb07433dc3d67928433e6d720bdbc3af5'),
  ('en.sahih', 46, 9, 4519, 'Say, "I am not something original among the messengers, nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am not but a clear warner."', NULL, NULL, '0b238209c853efcbd2e278c4cc79e40060619c0bce73f07fe816d21627430c8d'),
  ('en.sahih', 46, 10, 4520, 'Say, "Have you considered: if the Qur''an was from Allah, and you disbelieved in it while a witness from the Children of Israel has testified to something similar and believed while you were arrogant...?" Indeed, Allah does not guide the wrongdoing people.', NULL, NULL, '6d67fbc6f20c5420c07f2aa3b636aa66084383d3be663cfe86c352578d78f440'),
  ('en.sahih', 46, 11, 4521, 'And those who disbelieve say of those who believe, "If it had [truly] been good, they would not have preceded us to it." And when they are not guided by it, they will say, "This is an ancient falsehood."', NULL, NULL, 'eb7401a8a62e342887e10634f0a8ab5a504e4bc76b83434748fb0fb2c692b19c'),
  ('en.sahih', 46, 12, 4522, 'And before it was the scripture of Moses to lead and as a mercy. And this is a confirming Book in an Arabic tongue to warn those who have wronged and as good tidings to the doers of good.', NULL, NULL, '4a1d494f16796ea73740100f8eb91f17420f3dde43c59339fae59a751ebd4580'),
  ('en.sahih', 46, 13, 4523, 'Indeed, those who have said, "Our Lord is Allah," and then remained on a right course - there will be no fear concerning them, nor will they grieve.', NULL, NULL, '54c46996399582a2f91af354ed887f12cf926e3f77f964c6b7f8d165e97556d9'),
  ('en.sahih', 46, 14, 4524, 'Those are the companions of Paradise, abiding eternally therein as reward for what they used to do.', NULL, NULL, '7324a380237b6f92a4dd92e77f3a6937e24405b768d88aed4ec44a074438513e'),
  ('en.sahih', 46, 15, 4525, 'And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims."', NULL, NULL, '8934a01d095872e49121479dd81991b9cf2b8ae138cc5d6e8905da86bb7fb8cf'),
  ('en.sahih', 46, 16, 4526, 'Those are the ones from whom We will accept the best of what they did and overlook their misdeeds, [their being] among the companions of Paradise. [That is] the promise of truth which they had been promised.', NULL, NULL, '866850545f449c00ede7ffc72b3dde15e8bc5fa5a96d0460449209208aa74a40'),
  ('en.sahih', 46, 17, 4527, 'But one who says to his parents, "Uff to you; do you promise me that I will be brought forth [from the earth] when generations before me have already passed on [into oblivion]?" while they call to Allah for help [and to their son], "Woe to you! Believe! Indeed, the promise of Allah is truth." But he says, "This is not but legends of the former people" -', NULL, NULL, '2b492ac3df5fd59d1a724137cc9a65170d68e7135a64e4776b333d2b2d3ad8e3'),
  ('en.sahih', 46, 18, 4528, 'Those are the ones upon whom the word has come into effect, [who will be] among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.', NULL, NULL, 'fe141ee20e3839cbf213b00affa7b0acad6f87fc45a59beffdef2f735859327d'),
  ('en.sahih', 46, 19, 4529, 'And for all there are degrees [of reward and punishment] for what they have done, and [it is] so that He may fully compensate them for their deeds, and they will not be wronged.', NULL, NULL, '5d64a0a8c44b9224203122ec0ba44df6f1633ab2664379fc5762496fb4f863a6'),
  ('en.sahih', 46, 20, 4530, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "You exhausted your pleasures during your worldly life and enjoyed them, so this Day you will be awarded the punishment of [extreme] humiliation because you were arrogant upon the earth without right and because you were defiantly disobedient."', NULL, NULL, '75ccc9ebe3a6eafa0fb5817080d1425f3ee08323f68d5221213b5181f38dfea6'),
  ('en.sahih', 46, 21, 4531, 'And mention, [O Muhammad], the brother of ''Aad, when he warned his people in the [region of] al-Ahqaf - and warners had already passed on before him and after him - [saying], "Do not worship except Allah. Indeed, I fear for you the punishment of a terrible day."', NULL, NULL, 'df75a6353992fb139e66202a8095682ad7c800f84b27a0f963b049adbf2d6df9'),
  ('en.sahih', 46, 22, 4532, 'They said, "Have you come to delude us away from our gods? Then bring us what you promise us, if you should be of the truthful."', NULL, NULL, '702a34e651c596e4c0234d7f1a9e708e1cfa424122b0f3b037775233bcc0ed2e'),
  ('en.sahih', 46, 23, 4533, 'He said, "Knowledge [of its time] is only with Allah, and I convey to you that with which I was sent; but I see you [to be] a people behaving ignorantly."', NULL, NULL, '1ccd048cab3abaa52155d0ecd02098ed1e11f0cda34d2373811c49e5359c9d33'),
  ('en.sahih', 46, 24, 4534, 'And when they saw it as a cloud approaching their valleys, they said, "This is a cloud bringing us rain!" Rather, it is that for which you were impatient: a wind, within it a painful punishment,', NULL, NULL, 'f2966239238d272dba52a5b9d3a91d705bcdade96ba23bf366f54b2a68abd392'),
  ('en.sahih', 46, 25, 4535, 'Destroying everything by command of its Lord. And they became so that nothing was seen [of them] except their dwellings. Thus do We recompense the criminal people.', NULL, NULL, 'bc9dd0c7136c815bdd147f01ea3763ff62dca5689962acc370df8501dd9b4bf2'),
  ('en.sahih', 46, 26, 4536, 'And We had certainly established them in such as We have not established you, and We made for them hearing and vision and hearts. But their hearing and vision and hearts availed them not from anything [of the punishment] when they were [continually] rejecting the signs of Allah; and they were enveloped by what they used to ridicule.', NULL, NULL, '40ca2b2f835597a0a8169613518a7259e1bca20116bec6ad531f92f003b90880'),
  ('en.sahih', 46, 27, 4537, 'And We have already destroyed what surrounds you of [those] cities, and We have diversified the signs [or verses] that perhaps they might return [from disbelief].', NULL, NULL, '06d111b197e74f91975bbe7d9c3c902ad9e3a1e36e6e2f1fcd1005b679853642'),
  ('en.sahih', 46, 28, 4538, 'Then why did those they took besides Allah as deities by which to approach [Him] not aid them? But they had strayed from them. And that was their falsehood and what they were inventing.', NULL, NULL, '5a37d7d837bfba35feb6595a0adc86670caad06934e2cc48e39fdeb20a4a28d4'),
  ('en.sahih', 46, 29, 4539, 'And [mention, O Muhammad], when We directed to you a few of the jinn, listening to the Qur''an. And when they attended it, they said, "Listen quietly." And when it was concluded, they went back to their people as warners.', NULL, NULL, '6cee2f14826963955832d813860d8d8b99978e850f046c3bb02567d1c57baebc'),
  ('en.sahih', 46, 30, 4540, 'They said, "O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path.', NULL, NULL, '48abc8f88bf6531872494ac2523972abb2cfdfcb5e3a697ad17f553403c96dce'),
  ('en.sahih', 46, 31, 4541, 'O our people, respond to the Messenger of Allah and believe in him; Allah will forgive for you your sins and protect you from a painful punishment.', NULL, NULL, 'df0483d056402b2b0c8f60fa06d4f47f45c65e47a5dd4634960029cfb7f5ffc6'),
  ('en.sahih', 46, 32, 4542, 'But he who does not respond to the Caller of Allah will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error."', NULL, NULL, '0c2467ecaffa290fbc3802d1474e439ea758044ddf4524820e464c1430ff52d8'),
  ('en.sahih', 46, 33, 4543, 'Do they not see that Allah, who created the heavens and earth and did not fail in their creation, is able to give life to the dead? Yes. Indeed, He is over all things competent.', NULL, NULL, '9b1e096f25d30320a6ed43e641887b810cbb372a7fa207b021d6d34d1c8adcad'),
  ('en.sahih', 46, 34, 4544, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "Is this not the truth?" They will say, "Yes, by our Lord." He will say, "Then taste the punishment because you used to disbelieve."', NULL, NULL, 'afb047095ca93dfbf88b4f1eca9a48ed4fa62c68b4bbc35c64f7ef6400a759fe'),
  ('en.sahih', 46, 35, 4545, 'So be patient, [O Muhammad], as were those of determination among the messengers and do not be impatient for them. It will be - on the Day they see that which they are promised - as though they had not remained [in the world] except an hour of a day. [This is] notification. And will [any] be destroyed except the defiantly disobedient people?', NULL, NULL, '52ae5698262771095d0f81f6bdb5c29731a5c51b8719a9e2775659f7cb745c46'),
  ('en.sahih', 47, 1, 4546, 'Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds.', NULL, NULL, '6fff4953f5a041e4ddc35d00d39067369198e113b720c09ab0b199d0a061d453'),
  ('en.sahih', 47, 2, 4547, 'And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.', NULL, NULL, '1eceb725215efec5a85159964dc855f16abbc0c7096530057aca5132c840b2b0'),
  ('en.sahih', 47, 3, 4548, 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons.', NULL, NULL, 'dc3f3222f14dd9316ca86b4c55951bc84015be8bbf3a69de3e70f3defe9dce46'),
  ('en.sahih', 47, 4, 4549, 'So when you meet those who disbelieve [in battle], strike [their] necks until, when you have inflicted slaughter upon them, then secure their bonds, and either [confer] favor afterwards or ransom [them] until the war lays down its burdens. That [is the command]. And if Allah had willed, He could have taken vengeance upon them [Himself], but [He ordered armed struggle] to test some of you by means of others. And those who are killed in the cause of Allah - never will He waste their deeds.', NULL, NULL, '3888cc2db47ec570e574eb8e13df3fda0d2d03a19f059f1227e269465b1a6f2c'),
  ('en.sahih', 47, 5, 4550, 'He will guide them and amend their condition', NULL, NULL, 'd207126a616ac0ffe54040cbd99e568099b1c5440c8321e8621ad4dabdbe081c'),
  ('en.sahih', 47, 6, 4551, 'And admit them to Paradise, which He has made known to them.', NULL, NULL, '1a9594c7494212dcda661b1ed727cadc016a45f05ede6e3f7633e436b1f182ec'),
  ('en.sahih', 47, 7, 4552, 'O you who have believed, if you support Allah, He will support you and plant firmly your feet.', NULL, NULL, 'dc8ed76710bc4bc0f89879d68943244121a3357683a560e9c4f4c14164830a83'),
  ('en.sahih', 47, 8, 4553, 'But those who disbelieve - for them is misery, and He will waste their deeds.', NULL, NULL, '77834926f51eb1920a96eb642e2c32715ce7bdd628dbfe8a0782b067ad0a3a34'),
  ('en.sahih', 47, 9, 4554, 'That is because they disliked what Allah revealed, so He rendered worthless their deeds.', NULL, NULL, 'fddf7d84ca0619e8816adb8e2776ad218db99b07d94d0ad06c7afe2ac7443e3d'),
  ('en.sahih', 47, 10, 4555, 'Have they not traveled through the land and seen how was the end of those before them? Allah destroyed [everything] over them, and for the disbelievers is something comparable.', NULL, NULL, '8872fce9e05eee6824e331d20a0a2c2c4628c5a94cb4a4585d154c5b68b42d0d'),
  ('en.sahih', 47, 11, 4556, 'That is because Allah is the protector of those who have believed and because the disbelievers have no protector.', NULL, NULL, 'c469d615b16f0bdb1e474b66e09bcdd649f7e15f1243b987ac6122f86b236322'),
  ('en.sahih', 47, 12, 4557, 'Indeed, Allah will admit those who have believed and done righteous deeds to gardens beneath which rivers flow, but those who disbelieve enjoy themselves and eat as grazing livestock eat, and the Fire will be a residence for them.', NULL, NULL, '00e38591c6fb45dabc3f3132d1c2164b74eace78a667ebd0425bd72e97e441de'),
  ('en.sahih', 47, 13, 4558, 'And how many a city was stronger than your city [Makkah] which drove you out? We destroyed them; and there was no helper for them.', NULL, NULL, 'b27ff1983adeb05a5d090ef8a4d32cfc34ece48cf13231201e83019011c10138'),
  ('en.sahih', 47, 14, 4559, 'So is he who is on clear evidence from his Lord like him to whom the evil of his work has been made attractive and they follow their [own] desires?', NULL, NULL, '1ffca8e790a4f4038bd825404aa73581c3f8d12510ab52b221727eadf7a2f13b'),
  ('en.sahih', 47, 15, 4560, 'Is the description of Paradise, which the righteous are promised, wherein are rivers of water unaltered, rivers of milk the taste of which never changes, rivers of wine delicious to those who drink, and rivers of purified honey, in which they will have from all [kinds of] fruits and forgiveness from their Lord, like [that of] those who abide eternally in the Fire and are given to drink scalding water that will sever their intestines?', NULL, NULL, '9e09185e9810658d5da979a7bae298835471f18a86716277eb9109eebf56c716'),
  ('en.sahih', 47, 16, 4561, 'And among them, [O Muhammad], are those who listen to you, until when they depart from you, they say to those who were given knowledge, "What has he said just now?" Those are the ones of whom Allah has sealed over their hearts and who have followed their [own] desires.', NULL, NULL, 'd62aa9fe418323d338b07315ffce4acb324d16f78228ef69448bc748ab90fcbd'),
  ('en.sahih', 47, 17, 4562, 'And those who are guided - He increases them in guidance and gives them their righteousness.', NULL, NULL, '615e43507cf72630bf496287a71471bcb16896820e5d8f95541a532e4d2bc03f'),
  ('en.sahih', 47, 18, 4563, 'Then do they await except that the Hour should come upon them unexpectedly? But already there have come [some of] its indications. Then what good to them, when it has come, will be their remembrance?', NULL, NULL, 'a9f23f3706e265ac02265cd4f191b9ef73a67a83b8e4498557b9c511e6d3d614'),
  ('en.sahih', 47, 19, 4564, 'So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place.', NULL, NULL, '9fe0e6390457c3cb86df1efc71bf31f0e2633a7a472a9b7ce81e251e09e56988'),
  ('en.sahih', 47, 20, 4565, 'Those who believe say, "Why has a surah not been sent down? But when a precise surah is revealed and fighting is mentioned therein, you see those in whose hearts is hypocrisy looking at you with a look of one overcome by death. And more appropriate for them [would have been]', NULL, NULL, 'd973f47286b206d6096e3eff84fda1e017ab5f5203fb38f6c7c4fe3fca3f3da2'),
  ('en.sahih', 47, 21, 4566, 'Obedience and good words. And when the matter [of fighting] was determined, if they had been true to Allah, it would have been better for them.', NULL, NULL, '82f7a864c42d5ce3ca68991ca96aec8b9490a89b3277151bbf33dacdeda938e5'),
  ('en.sahih', 47, 22, 4567, 'So would you perhaps, if you turned away, cause corruption on earth and sever your [ties of] relationship?', NULL, NULL, '12acd2434d4ef2e289543e81e1cec2a9e0b4109f06344d28a590fd22551b7296'),
  ('en.sahih', 47, 23, 4568, 'Those [who do so] are the ones that Allah has cursed, so He deafened them and blinded their vision.', NULL, NULL, '7387e70d9e42391420a02d641dc5f4cc4eb23b485d0908724a216a1601c7d51b'),
  ('en.sahih', 47, 24, 4569, 'Then do they not reflect upon the Qur''an, or are there locks upon [their] hearts?', NULL, NULL, '7752b6319034a0c48b2bfc4a722a7a7276436179054809e38c156666beef6bec'),
  ('en.sahih', 47, 25, 4570, 'Indeed, those who reverted back [to disbelief] after guidance had become clear to them - Satan enticed them and prolonged hope for them.', NULL, NULL, 'b1e3bfdc183cd31a0a9d4908e2cdde9f701fba1585e30cf9fd863bca5ee5366b'),
  ('en.sahih', 47, 26, 4571, 'That is because they said to those who disliked what Allah sent down, "We will obey you in part of the matter." And Allah knows what they conceal.', NULL, NULL, 'e99b9b6a2006f6cab034bedeb63bbb63bac4a6c6634f057c5e7e52b64a368ce1'),
  ('en.sahih', 47, 27, 4572, 'Then how [will it be] when the angels take them in death, striking their faces and their backs?', NULL, NULL, '64f27303496b488074628299644712b11f8c1552440da4a36274e7b1fb753725'),
  ('en.sahih', 47, 28, 4573, 'That is because they followed what angered Allah and disliked [what earns] His pleasure, so He rendered worthless their deeds.', NULL, NULL, '8a3991d4c10e5c151d5bf397b7bd71a2ba0feb80309f8bc74e1d124b16848fea'),
  ('en.sahih', 47, 29, 4574, 'Or do those in whose hearts is disease think that Allah would never expose their [feelings of] hatred?', NULL, NULL, '35b04e046f9d5777e685d7b8385b08bc0a9865fed40cadc21ceb186075fb5eb7'),
  ('en.sahih', 47, 30, 4575, 'And if We willed, We could show them to you, and you would know them by their mark; but you will surely know them by the tone of [their] speech. And Allah knows your deeds.', NULL, NULL, '9d6dd588ae6bfd37a4bf5ffeab903b888a2dddef05257171f6d0cb183eb3853c'),
  ('en.sahih', 47, 31, 4576, 'And We will surely test you until We make evident those who strive among you [for the cause of Allah] and the patient, and We will test your affairs.', NULL, NULL, '3f49dfe5974e9f895f011dc586c57d817f3d1212b86aee81b506222af7cf5e50'),
  ('en.sahih', 47, 32, 4577, 'Indeed, those who disbelieved and averted [people] from the path of Allah and opposed the Messenger after guidance had become clear to them - never will they harm Allah at all, and He will render worthless their deeds.', NULL, NULL, '4e8fda12fb643073ffde9c30010ab33d55cba78a530b30ee36134c7b4d48172e'),
  ('en.sahih', 47, 33, 4578, 'O you who have believed, obey Allah and obey the Messenger and do not invalidate your deeds.', NULL, NULL, '3c267548a87414dc4ec78e78729a5ae6c67faad4d7bbd72bdef4418be321d7ef'),
  ('en.sahih', 47, 34, 4579, 'Indeed, those who disbelieved and averted [people] from the path of Allah and then died while they were disbelievers - never will Allah forgive them.', NULL, NULL, '4f365281dd2ffd3ec862c106cb13abc9a82d29c96c62db25a9df82a59f52f732'),
  ('en.sahih', 47, 35, 4580, 'So do not weaken and call for peace while you are superior; and Allah is with you and will never deprive you of [the reward of] your deeds.', NULL, NULL, '0487a39505774b5e1da9499faa1e29479d81e3ac5d1e238d6b94abb391abedca'),
  ('en.sahih', 47, 36, 4581, '[This] worldly life is only amusement and diversion. And if you believe and fear Allah, He will give you your rewards and not ask you for your properties.', NULL, NULL, 'bc661d6b13cbbfa21ceb4a5fa0181a615d19e869ec36ae67ec7c81a4bc6c983c'),
  ('en.sahih', 47, 37, 4582, 'If He should ask you for them and press you, you would withhold, and He would expose your unwillingness.', NULL, NULL, '0a468084ed843358b7482f9578a27fb045cd9504c1393bcdf3c943b3569e492e'),
  ('en.sahih', 47, 38, 4583, 'Here you are - those invited to spend in the cause of Allah - but among you are those who withhold [out of greed]. And whoever withholds only withholds [benefit] from himself; and Allah is the Free of need, while you are the needy. And if you turn away, He will replace you with another people; then they will not be the likes of you.', NULL, NULL, 'ed6ff343599548fb5b1333d9cf61e364fd3b7c40bd1965747fc803bed9abfc8a'),
  ('en.sahih', 48, 1, 4584, 'Indeed, We have given you, [O Muhammad], a clear conquest', NULL, NULL, 'be4ac0de6c54f63723f8fa701bac263dad3f14f16760565f26f833f19a774908'),
  ('en.sahih', 48, 2, 4585, 'That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path', NULL, NULL, '3423eb98f9cbac8a5aaea9bacc5c71c69e8af8d63f02a3905390531e00776c7a'),
  ('en.sahih', 48, 3, 4586, 'And [that] Allah may aid you with a mighty victory.', NULL, NULL, '951182102ef703bc2576a0e2aa86b5cd324874d9d3e670d53e4789d3a3a6c9fd'),
  ('en.sahih', 48, 4, 4587, 'It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise.', NULL, NULL, '996bf2a01f93d6514fdfed37081fd59de54ce7929be18c939ea62030a2a55685'),
  ('en.sahih', 48, 5, 4588, '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -', NULL, NULL, 'f46a9e45f534b61c701dc0fb62477ef03e2631c1ababe6de7f90b966b619643b'),
  ('en.sahih', 48, 6, 4589, 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.', NULL, NULL, '344ae3ee2db449ac537b3c7ae19b542e5e722faa3a9d1646ddb2849b057fc67b'),
  ('en.sahih', 48, 7, 4590, 'And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise.', NULL, NULL, 'e5ad37cf73e941d64be2391a212ff5bd8d63d361341d0ebfd626484c4185943a'),
  ('en.sahih', 48, 8, 4591, 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner', NULL, NULL, '89b878452b57bc0f96f86b2154077ff04b2b808924112cbb09af1d6514efbf07'),
  ('en.sahih', 48, 9, 4592, 'That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon.', NULL, NULL, '6ee8e546676b9eaaa0d8707bb9f7de94eb8964d9cbd7a3df53bb54cdfb565b05'),
  ('en.sahih', 48, 10, 4593, 'Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward.', NULL, NULL, 'aabc6da18a41a0340c28c3521582fffaf06c68fed20b7ea962005454a563ee73'),
  ('en.sahih', 48, 11, 4594, 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted.', NULL, NULL, '52605a33fd98d9a64441bee8675cf28d8765c7cfb872cfb47c50d8cd8d8a6874'),
  ('en.sahih', 48, 12, 4595, 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."', NULL, NULL, '64b4fbd1346f56ab9e85c405d76585336b98a1ad0379fb67c59fd4ffe07c678e'),
  ('en.sahih', 48, 13, 4596, 'And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.', NULL, NULL, 'b9e812ce612ffbec79cbf6eeef15e601e6c45e28ac5c63cecf3c801628b87f3c'),
  ('en.sahih', 48, 14, 4597, 'And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful.', NULL, NULL, '6186a15f42eaaedb0454b2cbc41b7367ad21b05d33096c0c8f473a248b7e80e9'),
  ('en.sahih', 48, 15, 4598, 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allah. Say, "Never will you follow us. Thus did Allah say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.', NULL, NULL, '7054dea26eec916ecfd169ded5fc6aff56e84c7f171f3a2dce24d9811655f341'),
  ('en.sahih', 48, 16, 4599, 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."', NULL, NULL, '9695d5692cb71973b87e7a87b67ab0dc78cbb0219cbf010797bd4e22f9808a43'),
  ('en.sahih', 48, 17, 4600, 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.', NULL, NULL, 'eda9b78461bc2f9c4e985c725039a83b131267ade002f28bb12589a1d79e9ea3')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 48, 18, 4601, 'Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest', NULL, NULL, 'ffa26906b911252628ba7c7f2f4714348aafc12e29ac8aa7ab51c366f6669ee6'),
  ('en.sahih', 48, 19, 4602, 'And much war booty which they will take. And ever is Allah Exalted in Might and Wise.', NULL, NULL, 'fb4d36eff5faf48cb73ff5981432c26c4bd24899b02ea3518d751c17aebbc0ea'),
  ('en.sahih', 48, 20, 4603, 'Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.', NULL, NULL, '3d8e086b4737e0fa4e2616f15709394a83d21de1c5bb2667e282563aebf82f1d'),
  ('en.sahih', 48, 21, 4604, 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent.', NULL, NULL, '25fe58f6cd801db170abd63d9507bf598a05eea4d8867719ebc376766fd89391'),
  ('en.sahih', 48, 22, 4605, 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.', NULL, NULL, '5e5afc968b3cec83976754527086534ad59cff088dbe6c8659bb4e08bfd199bd'),
  ('en.sahih', 48, 23, 4606, '[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change.', NULL, NULL, '59adb04c7ff358f47d8435d8a280cf37fc3d62f1e41bd325f1cda09a9ab8fc1b'),
  ('en.sahih', 48, 24, 4607, 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing.', NULL, NULL, 'c1d7b543f00de38a98314789b2b806c0b7ea4468256abe6fdb23bf7b0431e9d3'),
  ('en.sahih', 48, 25, 4608, 'They are the ones who disbelieved and obstructed you from al-Masjid al-Haram while the offering was prevented from reaching its place of sacrifice. And if not for believing men and believing women whom you did not know - that you might trample them and there would befall you because of them dishonor without [your] knowledge - [you would have been permitted to enter Makkah]. [This was so] that Allah might admit to His mercy whom He willed. If they had been apart [from them], We would have punished those who disbelieved among them with painful punishment', NULL, NULL, '6ec8e906ac8dca7d9af3ec727e6f66bb96b70560a51ed492efdbe7f9d51b8b0d'),
  ('en.sahih', 48, 26, 4609, 'When those who disbelieved had put into their hearts chauvinism - the chauvinism of the time of ignorance. But Allah sent down His tranquillity upon His Messenger and upon the believers and imposed upon them the word of righteousness, and they were more deserving of it and worthy of it. And ever is Allah, of all things, Knowing.', NULL, NULL, '46543a97b3b807f48d1103875755d83998677e13e58e0d4adf1117ea808533b1'),
  ('en.sahih', 48, 27, 4610, 'Certainly has Allah showed to His Messenger the vision in truth. You will surely enter al-Masjid al-Haram, if Allah wills, in safety, with your heads shaved and [hair] shortened, not fearing [anyone]. He knew what you did not know and has arranged before that a conquest near [at hand].', NULL, NULL, '07d1e9fbf6bcafaee233a66fdfde47e70ce7726c8c316bf4576997028128ba3f'),
  ('en.sahih', 48, 28, 4611, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion. And sufficient is Allah as Witness.', NULL, NULL, 'e7cbebe9c76627a57377120bf2f6048c562d955b2f5c4e272702ef64fc7fc809'),
  ('en.sahih', 48, 29, 4612, 'Muhammad is the Messenger of Allah; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allah and [His] pleasure. Their mark is on their faces from the trace of prostration. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that Allah may enrage by them the disbelievers. Allah has promised those who believe and do righteous deeds among them forgiveness and a great reward.', NULL, NULL, '130d02ba0072b77f8e214dd6d5c768c39e015a33adaf2aa0810e5df32b801906'),
  ('en.sahih', 49, 1, 4613, 'O you who have believed, do not put [yourselves] before Allah and His Messenger but fear Allah. Indeed, Allah is Hearing and Knowing.', NULL, NULL, '29c3c4197fcb253761dc4d8bde6bf40db32a0a481affac2fed363faf5fa149e7'),
  ('en.sahih', 49, 2, 4614, 'O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not.', NULL, NULL, 'f614478acbcaefab58b4f25521327e9327123cb9345840f1362dfb30fe756588'),
  ('en.sahih', 49, 3, 4615, 'Indeed, those who lower their voices before the Messenger of Allah - they are the ones whose hearts Allah has tested for righteousness. For them is forgiveness and great reward.', NULL, NULL, '121c1dd205bfa37db6158f068f3b7b4539800afa41f2d5abf13911d989c569a0'),
  ('en.sahih', 49, 4, 4616, 'Indeed, those who call you, [O Muhammad], from behind the chambers - most of them do not use reason.', NULL, NULL, 'f82083f6c33dabeb8ff095235a4bfaf715973c5f5c3de7666484ed135a4d8a12'),
  ('en.sahih', 49, 5, 4617, 'And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful.', NULL, NULL, '97ddb15c504c54235fccd4ba971ed8dd86833985cf72eadb9e4b64934c30f1f2'),
  ('en.sahih', 49, 6, 4618, 'O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful.', NULL, NULL, '80290cf4953d482467b61f949034effc3d4f48676d6bc7c8cceca8a666d9dc6b'),
  ('en.sahih', 49, 7, 4619, 'And know that among you is the Messenger of Allah. If he were to obey you in much of the matter, you would be in difficulty, but Allah has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided.', NULL, NULL, '6302c4af4dec92acbe9122fadb6fc8d5a8c930d3767e4dc13923c4c4666ec155'),
  ('en.sahih', 49, 8, 4620, '[It is] as bounty from Allah and favor. And Allah is Knowing and Wise.', NULL, NULL, 'ce63a7e18afed722e66595a72bab9a76f3826a7c0746d3378d2c7c348ad9069b'),
  ('en.sahih', 49, 9, 4621, 'And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly.', NULL, NULL, 'e80b15b31ef40fced14006ae2c1707f7d5bd9c1171e8217e440b4eaddede5986'),
  ('en.sahih', 49, 10, 4622, 'The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy.', NULL, NULL, '67f53d748017c5c87d4c4dda590308fa86b852970cf8605ad5fd02771f5a2097'),
  ('en.sahih', 49, 11, 4623, 'O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one''s] faith. And whoever does not repent - then it is those who are the wrongdoers.', NULL, NULL, '096c3815a1b3173faf50cf963a1dc7d86827dc55cc2bc1343bc1d97b4c03e4dd'),
  ('en.sahih', 49, 12, 4624, 'O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful.', NULL, NULL, 'a8d4ed2bf3dae3c6a8b963ae61416d2bd179ee2a259cd6d97acbda86eb049557'),
  ('en.sahih', 49, 13, 4625, 'O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Acquainted.', NULL, NULL, '0966e20b0f618d8e7ee7ba2be7943277623db294cbf6dcb3de6a9e45aefe9a7a'),
  ('en.sahih', 49, 14, 4626, 'The bedouins say, "We have believed." Say, "You have not [yet] believed; but say [instead], ''We have submitted,'' for faith has not yet entered your hearts. And if you obey Allah and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allah is Forgiving and Merciful."', NULL, NULL, '3ac876b617dc7c1f37fad262d76254961c6622dbd493e622ac81bee1462b5dee'),
  ('en.sahih', 49, 15, 4627, 'The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful.', NULL, NULL, '10c2c4f04f14c165660710e81e3b9b5cfb2166ec521b14e23ffaf05ccf402ce4'),
  ('en.sahih', 49, 16, 4628, 'Say, "Would you acquaint Allah with your religion while Allah knows whatever is in the heavens and whatever is on the earth, and Allah is Knowing of all things?"', NULL, NULL, 'edd74494ee4161d8d78ee6be3a7a6ce6ed6a9fca0ea03f309a3b53c26fffa0bc'),
  ('en.sahih', 49, 17, 4629, 'They consider it a favor to you that they have accepted Islam. Say, "Do not consider your Islam a favor to me. Rather, Allah has conferred favor upon you that He has guided you to the faith, if you should be truthful."', NULL, NULL, '7fb9995a58358409d2a0700c5a024f3c9b0504f65a0be7eec5912cbb12ba7bfe'),
  ('en.sahih', 49, 18, 4630, 'Indeed, Allah knows the unseen [aspects] of the heavens and the earth. And Allah is Seeing of what you do.', NULL, NULL, '9b6ced9b6e8cb8fb85ea80a26c908a1059b47d3c9a98bbe516ed69696cea1251'),
  ('en.sahih', 50, 1, 4631, 'Qaf. By the honored Qur''an...', NULL, NULL, '9e8e4f1aad213227a71fcadfe93a94717f3609560159b4e0d795b26edac5b5ee'),
  ('en.sahih', 50, 2, 4632, 'But they wonder that there has come to them a warner from among themselves, and the disbelievers say, "This is an amazing thing.', NULL, NULL, '7746d9f1fd5236d8418475533eaec180679500a0b5ba790a6b78ea2030205ead'),
  ('en.sahih', 50, 3, 4633, 'When we have died and have become dust, [we will return to life]? That is a distant return."', NULL, NULL, '41cf39f201b90001d75d4dc6b8d73c5c4523a2d851460c1e578153d6aeaa0718'),
  ('en.sahih', 50, 4, 4634, 'We know what the earth diminishes of them, and with Us is a retaining record.', NULL, NULL, '4b2903fb900869d36c25b9a31af4fae87928edad680fa280b07da6a33c3d5a9c'),
  ('en.sahih', 50, 5, 4635, 'But they denied the truth when it came to them, so they are in a confused condition.', NULL, NULL, 'e9b228d2a54728b23293ee499d4db1778717082dd11ee98d424b852152620ded'),
  ('en.sahih', 50, 6, 4636, 'Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts?', NULL, NULL, '8c388895eb95b1323dd080f27a7f3da8f3e48ea49118b0fd5a22bd22cf937dd6'),
  ('en.sahih', 50, 7, 4637, 'And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind,', NULL, NULL, '331ef6bf1172c447ccb01294c1ae6fd88aeb635c77958d5a978a14c9b522d2a4'),
  ('en.sahih', 50, 8, 4638, 'Giving insight and a reminder for every servant who turns [to Allah].', NULL, NULL, '581d9a86663ad2173b82f2ddfc2e3ff9a734d1cb00caa55179974459c33c1cfa'),
  ('en.sahih', 50, 9, 4639, 'And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest', NULL, NULL, 'f23ed3cf77edbdf3cc7cdfb1b384f470ba27270a6795371bf32274d07a450332'),
  ('en.sahih', 50, 10, 4640, 'And lofty palm trees having fruit arranged in layers -', NULL, NULL, '31059efd37ebce4c318baffff123b5f52baa34e13c938f44e548cb393bbac754'),
  ('en.sahih', 50, 11, 4641, 'As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection.', NULL, NULL, 'bf89495c6a794598d7f804f1fe7609934c8259bdf87ebba8c134def37bb8aa31'),
  ('en.sahih', 50, 12, 4642, 'The people of Noah denied before them, and the companions of the well and Thamud', NULL, NULL, '547dd419bc62c832785e1768d02e161f29d1e322a2ae26ceba8017c891e3c91c'),
  ('en.sahih', 50, 13, 4643, 'And ''Aad and Pharaoh and the brothers of Lot', NULL, NULL, '7710c74b933833979cf88673e658901c7e31a77cc011b6196e90c459ccf630ff'),
  ('en.sahih', 50, 14, 4644, 'And the companions of the thicket and the people of Tubba''. All denied the messengers, so My threat was justly fulfilled.', NULL, NULL, '8b37baf5edff34ff629cbe24188838cd814f439f9757441df331ad6e7f501402'),
  ('en.sahih', 50, 15, 4645, 'Did We fail in the first creation? But they are in confusion over a new creation.', NULL, NULL, 'c90f127cc7c8fff9252a4e4aba8501b1a8848113be721060cf23d6c11c496044'),
  ('en.sahih', 50, 16, 4646, 'And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein', NULL, NULL, 'ea0fd226fcb95c24696e5aeb2020d4757854111d85a3daa7bcbcd2bd39c7d918'),
  ('en.sahih', 50, 17, 4647, 'When the two receivers receive, seated on the right and on the left.', NULL, NULL, 'aeeeade230bab6c88c48136176e9a54908a156886e93df21e22103a5357f91cb'),
  ('en.sahih', 50, 18, 4648, 'Man does not utter any word except that with him is an observer prepared [to record].', NULL, NULL, '4b35a9c70d90bd300eb2cb2eb1993cda7a4a2f30030322244f42d452e6dc4a07'),
  ('en.sahih', 50, 19, 4649, 'And the intoxication of death will bring the truth; that is what you were trying to avoid.', NULL, NULL, 'd7350be14ebf9542a3a6b1c65b64e2e68815fdc11773fb520d8209b4bcce34d8'),
  ('en.sahih', 50, 20, 4650, 'And the Horn will be blown. That is the Day of [carrying out] the threat.', NULL, NULL, '6e26dd56a79ef87a69363e2f65d2330d939f1819ced2b5a3646699d08ee40bfc'),
  ('en.sahih', 50, 21, 4651, 'And every soul will come, with it a driver and a witness.', NULL, NULL, '094f7492bf35b18b6fec93a631b4e8e8678fc7081c50c1de9b7fbde7f0019e79'),
  ('en.sahih', 50, 22, 4652, '[It will be said], "You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp."', NULL, NULL, 'b7e1e7f8c9a54ab8be3dff218858be03a6c293c38caba8b56c54212740cddfd1'),
  ('en.sahih', 50, 23, 4653, 'And his companion, [the angel], will say, "This [record] is what is with me, prepared."', NULL, NULL, 'a2dec2cf18464dfba5e87a9aa1d7dc2d0c0658784a38d59bd21cf529124ee80e'),
  ('en.sahih', 50, 24, 4654, '[Allah will say], "Throw into Hell every obstinate disbeliever,', NULL, NULL, '1d1ad1a982d7d70808febb3fce3e26f3b482118c501607e955d9943d11b1e120'),
  ('en.sahih', 50, 25, 4655, 'Preventer of good, aggressor, and doubter,', NULL, NULL, '0294bbe1aad01dc0ed204aecbe4b8dfdf228e32db019cc6facaa4b6017f45e19'),
  ('en.sahih', 50, 26, 4656, 'Who made [as equal] with Allah another deity; then throw him into the severe punishment."', NULL, NULL, '99a047c5e4b676354f3cc2f2559ea495515fc9542f794947b7c02dbb6c3f02d2'),
  ('en.sahih', 50, 27, 4657, 'His [devil] companion will say, "Our Lord, I did not make him transgress, but he [himself] was in extreme error."', NULL, NULL, '5be75d03c42e3d7999f5e33f88f1ac799b30db00e4c0d4d49e9fba78cb5699c7'),
  ('en.sahih', 50, 28, 4658, '[Allah] will say, "Do not dispute before Me, while I had already presented to you the warning.', NULL, NULL, '8c1f58ae50efad2f959a01306b5f8163d2ef6c1c570fb43d1682b13b1b185e85'),
  ('en.sahih', 50, 29, 4659, 'The word will not be changed with Me, and never will I be unjust to the servants."', NULL, NULL, '9a239ab67ed0c555a6bacaa7d076743339335f627020a0f08d9c2ef45fab67c0'),
  ('en.sahih', 50, 30, 4660, 'On the Day We will say to Hell, "Have you been filled?" and it will say, "Are there some more,"', NULL, NULL, '86066d087aafd15706a5be6d79c796730c9d9f69fe9323c5d73922f6b235e84d'),
  ('en.sahih', 50, 31, 4661, 'And Paradise will be brought near to the righteous, not far,', NULL, NULL, '0115c44ddebe275e4bbb9479b7175e620b75515580dc2bcb7963a2d9844edb3a'),
  ('en.sahih', 50, 32, 4662, '[It will be said], "This is what you were promised - for every returner [to Allah] and keeper [of His covenant]', NULL, NULL, '30383981d7155faa3606c76250d0345c7d6ffc080ebf374606b16d6b46e3a1e2'),
  ('en.sahih', 50, 33, 4663, 'Who feared the Most Merciful unseen and came with a heart returning [in repentance].', NULL, NULL, 'b1c37105f16e0f243ccbf719b9eaab363189f34a5bcb258d21e724308e9b2160'),
  ('en.sahih', 50, 34, 4664, 'Enter it in peace. This is the Day of Eternity."', NULL, NULL, '4fcb21905d99fdf59d04c8219adf67398b587270c4213c02370850cad448c6e6'),
  ('en.sahih', 50, 35, 4665, 'They will have whatever they wish therein, and with Us is more.', NULL, NULL, 'da9590829688d31dc9d5c9c9bcaafb75c1d094c0ace19427cd2956db98b2c060'),
  ('en.sahih', 50, 36, 4666, 'And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape?', NULL, NULL, '101972973fae3ab72f7c6743f4c40ec4b485861c8caf40ccfa8c4a038b1649e6'),
  ('en.sahih', 50, 37, 4667, 'Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind].', NULL, NULL, 'b6d7a344f43ef06b05b7d6d701b26db5cbaf14ae732267e36bc393ecab6c1870'),
  ('en.sahih', 50, 38, 4668, 'And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness.', NULL, NULL, '7a6958c9d9322fbd96f27818b3227d0e030164fa3e1a4553b2afda731fff866c'),
  ('en.sahih', 50, 39, 4669, 'So be patient, [O Muhammad], over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting,', NULL, NULL, '3aaefae71b6e53d277612d5a36955511b34e1ff0288e5caeef30b6f2e773f2a1'),
  ('en.sahih', 50, 40, 4670, 'And [in part] of the night exalt Him and after prostration.', NULL, NULL, '91420b496ff91ed26a1cfc24d9096601e3d669afaf2bf96704aed885953ba199'),
  ('en.sahih', 50, 41, 4671, 'And listen on the Day when the Caller will call out from a place that is near -', NULL, NULL, '1453b9f18a036b15cf0089df9b9d84be4008c7e879f431dabaece5f62b491ec3'),
  ('en.sahih', 50, 42, 4672, 'The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves].', NULL, NULL, '48c53c5943dd29f5801dd4658c37e9f7ba5d37a0656a64c8005f1ceaf9470b43'),
  ('en.sahih', 50, 43, 4673, 'Indeed, it is We who give life and cause death, and to Us is the destination', NULL, NULL, '585f9fad343c6f6a20e539074018486f436e38744abaf3eb2c3684431545bb18'),
  ('en.sahih', 50, 44, 4674, 'On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us.', NULL, NULL, '1d43cb4e624c93dca37fc489634fd3d3ff3f9a3817345352e76929210bb335ac'),
  ('en.sahih', 50, 45, 4675, 'We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur''an whoever fears My threat.', NULL, NULL, '15207cad85d7b21074e4913251dedeac55f59f376a9c44e8728e53b9aebd60f6'),
  ('en.sahih', 51, 1, 4676, 'By those [winds] scattering [dust] dispersing', NULL, NULL, '826d41ab8e5568c7f9f0c3943306b0d1be8ca40b4fa44070069a86fc3fa88950'),
  ('en.sahih', 51, 2, 4677, 'And those [clouds] carrying a load [of water]', NULL, NULL, '935ebcbdeb45e88d7445cd028d535e91f5bf3b89e686cf80887baefa62f203c8'),
  ('en.sahih', 51, 3, 4678, 'And those [ships] sailing with ease', NULL, NULL, 'af8261aad6eb52ccacc064850835c6f44e0c2656a2c30ccf82abd869fe14b4a5'),
  ('en.sahih', 51, 4, 4679, 'And those [angels] apportioning [each] matter,', NULL, NULL, '4d1ebbbeafec05663355579ae2f9034013f907c1c2bb64c385d01cf96a6caa22'),
  ('en.sahih', 51, 5, 4680, 'Indeed, what you are promised is true.', NULL, NULL, '0c3d3734e6bb4ca76c99907f55f6e216653a2413b8ab470cbe8e180a45fa726d'),
  ('en.sahih', 51, 6, 4681, 'And indeed, the recompense is to occur.', NULL, NULL, '3b747a6c595f43c989572f32767f6b826addff44e245d7839ad78761f545336e'),
  ('en.sahih', 51, 7, 4682, 'By the heaven containing pathways,', NULL, NULL, '1fbbae52af80e73b3108daf39043c8828b749c4640e818cc23130ca9c46ef17f'),
  ('en.sahih', 51, 8, 4683, 'Indeed, you are in differing speech.', NULL, NULL, 'eec3bb3014d6017c3028ceb5f7fecfcb32fd68ef7a0605b92aae59728855d62f'),
  ('en.sahih', 51, 9, 4684, 'Deluded away from the Qur''an is he who is deluded.', NULL, NULL, 'c38dc0a20b068089dbc3c5f3b890a0f8635b1dc9e0af0accd5c92d141a05d7ab'),
  ('en.sahih', 51, 10, 4685, 'Destroyed are the falsifiers', NULL, NULL, '8ac11de9936cefa2e901fcf5c37b8bac34fa29b24641459ca2b0d591c793708c'),
  ('en.sahih', 51, 11, 4686, 'Who are within a flood [of confusion] and heedless.', NULL, NULL, '14cb0b00cb3473c86e62e7fe175857d4bf2b272f272f0c69cd5985e36e399523'),
  ('en.sahih', 51, 12, 4687, 'They ask, "When is the Day of Recompense?"', NULL, NULL, '19cdc00157562e16530b4c467e4637f4288205e20f7f2da71237022381868d75'),
  ('en.sahih', 51, 13, 4688, '[It is] the Day they will be tormented over the Fire', NULL, NULL, '6b341a406452bc204d972da873aeb16ffe28d531c382e9c39effd592ceea24f3'),
  ('en.sahih', 51, 14, 4689, '[And will be told], "Taste your torment. This is that for which you were impatient."', NULL, NULL, 'f5cf26bf23d97bcea776b34619766dff8289c0fb14c2f476ebecf6432b704ecc'),
  ('en.sahih', 51, 15, 4690, 'Indeed, the righteous will be among gardens and springs,', NULL, NULL, 'aa6789e4faf0b3b3f7034b3f7e856356bf69d455ecfd47fe71eeb3d51c2b71f3'),
  ('en.sahih', 51, 16, 4691, 'Accepting what their Lord has given them. Indeed, they were before that doers of good.', NULL, NULL, '906696e6ffe4542d5c7b42ca223756891d95581bb79020b4c92f3983bd9a01bd'),
  ('en.sahih', 51, 17, 4692, 'They used to sleep but little of the night,', NULL, NULL, 'a47007db515f94d121cb951cd43becaa3adccb3abab6b4b30cad8e5527a7811a'),
  ('en.sahih', 51, 18, 4693, 'And in the hours before dawn they would ask forgiveness,', NULL, NULL, '282d708da881bfec492424a0aa693b5109b5af558f114e7302bc654e817274b7'),
  ('en.sahih', 51, 19, 4694, 'And from their properties was [given] the right of the [needy] petitioner and the deprived.', NULL, NULL, '610318ca22f06c0e7bc3f5a56ce2ad4a0869249365a78bf6a3807aafad8b4f0e'),
  ('en.sahih', 51, 20, 4695, 'And on the earth are signs for the certain [in faith]', NULL, NULL, 'e49b86e11e63c15c9cd1d8e174cb94a891e599579c02f9c5d2447593ce1cf5c4'),
  ('en.sahih', 51, 21, 4696, 'And in yourselves. Then will you not see?', NULL, NULL, '6d3c1bab9a1641f6f72fdeab59c8b04ca16b628289fd73d521a3877080c315fe'),
  ('en.sahih', 51, 22, 4697, 'And in the heaven is your provision and whatever you are promised.', NULL, NULL, 'a9af7f055cf80390be65b790c0284874e4c332294ccabf6ee5db5aeed7f44a96'),
  ('en.sahih', 51, 23, 4698, 'Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking.', NULL, NULL, '8daecffdea40056315609dc3e8b19b72a8733bd46208c881458dffa6ef02095d'),
  ('en.sahih', 51, 24, 4699, 'Has there reached you the story of the honored guests of Abraham? -', NULL, NULL, '21bf443f0376427f39f0f6ff390f4029fb4c1ce6dceb5bf6490340838ebaecfc'),
  ('en.sahih', 51, 25, 4700, 'When they entered upon him and said, "[We greet you with] peace." He answered, "[And upon you] peace, [you are] a people unknown.', NULL, NULL, '1812399d32a9001f1fd5e8d7685c200c6f36ae3235693ccbad10293e31b0cae9')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 51, 26, 4701, 'Then he went to his family and came with a fat [roasted] calf', NULL, NULL, '20899a825f5590d4cb01fb76becaea986bf927097839de1793324853e9972747'),
  ('en.sahih', 51, 27, 4702, 'And placed it near them; he said, "Will you not eat?"', NULL, NULL, 'f2e2d668b63128d771f10c466ef08835b946c2335d1e9a3a0b1403506b78a7a3'),
  ('en.sahih', 51, 28, 4703, 'And he felt from them apprehension. They said, "Fear not," and gave him good tidings of a learned boy.', NULL, NULL, 'c129afe379a5a7be338e716ea49abdcb9ca82b41aaa2b5a13902de9d9e57a95e'),
  ('en.sahih', 51, 29, 4704, 'And his wife approached with a cry [of alarm] and struck her face and said, "[I am] a barren old woman!"', NULL, NULL, 'e84f10c8a84269c834c17e684907e3add3745aeef485784fc8f6563ed595c385'),
  ('en.sahih', 51, 30, 4705, 'They said, "Thus has said your Lord; indeed, He is the Wise, the Knowing."', NULL, NULL, '201dd44b9e065920d2374854928066fa78c7ff9c856fa2945c57fe4183ee1b74'),
  ('en.sahih', 51, 31, 4706, '[Abraham] said, "Then what is your business [here], O messengers?"', NULL, NULL, '021702240c9847db5a14b94bdcdf7e75ed2c4ee6110095c17d8b77feb544fd89'),
  ('en.sahih', 51, 32, 4707, 'They said, "Indeed, we have been sent to a people of criminals', NULL, NULL, '8b9535d90809649db1148503d86ccf97ac13d4d25b107d6ec8e04e736f4b2d83'),
  ('en.sahih', 51, 33, 4708, 'To send down upon them stones of clay,', NULL, NULL, 'fc215e86d38dc72c35ca9912f7b935e57b452530b63c08f42542dbb25bf1f086'),
  ('en.sahih', 51, 34, 4709, 'Marked in the presence of your Lord for the transgressors."', NULL, NULL, '9d70d6b9a698d9e7e9cd5132483e56d78a9f458f232e6592819d5debf7f9db46'),
  ('en.sahih', 51, 35, 4710, 'So We brought out whoever was in the cities of the believers.', NULL, NULL, '6f59d28ee6fc1a591d4e5d051444b2f04e787a592ab4102e4dbd08234b0760ee'),
  ('en.sahih', 51, 36, 4711, 'And We found not within them other than a [single] house of Muslims.', NULL, NULL, '68806199a5e0734359538330953cce51760bed1341507180b7d91d3d3aee2a22'),
  ('en.sahih', 51, 37, 4712, 'And We left therein a sign for those who fear the painful punishment.', NULL, NULL, '01feae13e8ce1c073073e135754a3a2a7236c38e07161df0851f3bf07947f9bd'),
  ('en.sahih', 51, 38, 4713, 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.', NULL, NULL, 'd3d539fef4a4f3d9dffa9c2505a342e644fedd50520baea71c73d10657ce06e8'),
  ('en.sahih', 51, 39, 4714, 'But he turned away with his supporters and said," A magician or a madman."', NULL, NULL, 'f393c13b94ae2d9bcc2c2b72032c51e78d110d33ddf70d8d2cafa77dc06dcd7d'),
  ('en.sahih', 51, 40, 4715, 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.', NULL, NULL, 'ae2d5cd5849947adbc15b5e6cf39f39372b53e85423d7764ddfeeb5cd9ac51cb'),
  ('en.sahih', 51, 41, 4716, 'And in ''Aad [was a sign], when We sent against them the barren wind.', NULL, NULL, '85beb280b82b9dfc97cfb07bd9ec5f18ed59d3111480b213f50df29057734666'),
  ('en.sahih', 51, 42, 4717, 'It left nothing of what it came upon but that it made it like disintegrated ruins.', NULL, NULL, '579efb9758296fe71c50b5d08623679bcd351c0a62f1eadebb4fe8e4796cac6e'),
  ('en.sahih', 51, 43, 4718, 'And in Thamud, when it was said to them, "Enjoy yourselves for a time."', NULL, NULL, '468555e8ad9f242c6ca4ef3d22444ac5c7e1394826a575193a90d4901fcb83b8'),
  ('en.sahih', 51, 44, 4719, 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.', NULL, NULL, '069dc64b1ce9364d8c67ddaf2aa02930af930f0750b98c7bbda3f64667f1f412'),
  ('en.sahih', 51, 45, 4720, 'And they were unable to arise, nor could they defend themselves.', NULL, NULL, '922d409af4c37cf6f7e868c6cedd9644f1a32963a19c3b5ad5fdba91b12d377a'),
  ('en.sahih', 51, 46, 4721, 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.', NULL, NULL, 'd74f421ecfaab71f3e67021834d3be59e3243c03bf12578c9265e58e92af9cca'),
  ('en.sahih', 51, 47, 4722, 'And the heaven We constructed with strength, and indeed, We are [its] expander.', NULL, NULL, '10e9c7dd03f70100502005a79c22608060875acf33a184fd177ff9d7cb8366b6'),
  ('en.sahih', 51, 48, 4723, 'And the earth We have spread out, and excellent is the preparer.', NULL, NULL, '1a91083265cded27ce4c411438cd1cffb6080e77df2d597ffbab68a314e27925'),
  ('en.sahih', 51, 49, 4724, 'And of all things We created two mates; perhaps you will remember.', NULL, NULL, 'dcf50852528c1edac3063ae955d9c9f1bfaa0cd5ff762f548a848f094851338f'),
  ('en.sahih', 51, 50, 4725, 'So flee to Allah. Indeed, I am to you from Him a clear warner.', NULL, NULL, '26dc2942a40449c5bf429ca0b2c54b98739631101b97f9f0d7bdf75f88403dd3'),
  ('en.sahih', 51, 51, 4726, 'And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner.', NULL, NULL, 'b6b89709dc8da25971d4bbe053acb3592cd35796263ff28b763f76640122563d'),
  ('en.sahih', 51, 52, 4727, 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."', NULL, NULL, '119a2db731f37d812f986deff37716df7d3c2553b6aabec80ac356e821be38c0'),
  ('en.sahih', 51, 53, 4728, 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.', NULL, NULL, '0c80f11fd41f84b9f4b3dab2c08056fc742aa6bb7a8c1311bed4381565533f52'),
  ('en.sahih', 51, 54, 4729, 'So leave them, [O Muhammad], for you are not to be blamed.', NULL, NULL, 'bbe3e9db9260d664e6fd89faaca62210a8f35e0e1a937bcebf75aaa303e1ae20'),
  ('en.sahih', 51, 55, 4730, 'And remind, for indeed, the reminder benefits the believers.', NULL, NULL, 'a38d457887653b897ce5cd77e8cf8ee0d4fdbe542e1f44cc5af28c274e50c773'),
  ('en.sahih', 51, 56, 4731, 'And I did not create the jinn and mankind except to worship Me.', NULL, NULL, 'a96b844b43b3864ef3e6d398e00e320d31ecdbd7a64bfd3ccb0c50957c7908f4'),
  ('en.sahih', 51, 57, 4732, 'I do not want from them any provision, nor do I want them to feed Me.', NULL, NULL, 'f553a1666bd5561183a0fe0116efe4b73213466205eeebd52251cc4aa92fe078'),
  ('en.sahih', 51, 58, 4733, 'Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength.', NULL, NULL, 'fa8e261fdfb2d5597b44f91a181714dae8f5363ad4477e4caa5df6e6cbc231ce'),
  ('en.sahih', 51, 59, 4734, 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me.', NULL, NULL, '5be1a5f06b7affb8a7badf0b97cabfe21e94a689a3ee94704a72f51599bc2527'),
  ('en.sahih', 51, 60, 4735, 'And woe to those who have disbelieved from their Day which they are promised.', NULL, NULL, '5267d14e55cb1e6333bc694379ecc4901cc25a74b1f9f76650ab26d53ae6b34b'),
  ('en.sahih', 52, 1, 4736, 'By the mount', NULL, NULL, '016b0bc1910426d561f5bda68f1feabed7390513db5dc359bf8dbfce07a7eae5'),
  ('en.sahih', 52, 2, 4737, 'And [by] a Book inscribed', NULL, NULL, '628a27d242e5e8ea97e00689cdc60882894f71def7d4fa5157de17c830dd49d7'),
  ('en.sahih', 52, 3, 4738, 'In parchment spread open', NULL, NULL, '78639e03027df5f43bb081c7f12034a34c62e84da988098b36311e998152b042'),
  ('en.sahih', 52, 4, 4739, 'And [by] the frequented House', NULL, NULL, 'a65a569af9210e18c493307b69e16d3a37a5bdccd1056efaa3ea7968c8ded836'),
  ('en.sahih', 52, 5, 4740, 'And [by] the heaven raised high', NULL, NULL, 'a0720dc0cf7d6a286d1e5937350c108590c0f76cad717cf53e9584894ba0f1ee'),
  ('en.sahih', 52, 6, 4741, 'And [by] the sea filled [with fire],', NULL, NULL, '9411b9c8dd41e5f0c8b12a7767542914aa1e2023a320470d988a3d3151571399'),
  ('en.sahih', 52, 7, 4742, 'Indeed, the punishment of your Lord will occur.', NULL, NULL, '0e309aa61404026192f8fad73366edef52545f66875b420db07f404083fbb268'),
  ('en.sahih', 52, 8, 4743, 'Of it there is no preventer.', NULL, NULL, 'c7ef263c6610fbf1cac327a7820db963054e0a8f67163896caefa1072e7df484'),
  ('en.sahih', 52, 9, 4744, 'On the Day the heaven will sway with circular motion', NULL, NULL, '5b9cea2320bd40de0ce091cc1ac8b305cd01da1fa2035c03185b6281d82332f1'),
  ('en.sahih', 52, 10, 4745, 'And the mountains will pass on, departing -', NULL, NULL, 'ba6de8d064c3dd474e252441aedc94d80421754b01615e5ba41f5bfebbd5beb6'),
  ('en.sahih', 52, 11, 4746, 'Then woe, that Day, to the deniers,', NULL, NULL, '60e5ded549607a78efe1a9394c654068aeb5d1940b687ebf93a6c263774f5575'),
  ('en.sahih', 52, 12, 4747, 'Who are in [empty] discourse amusing themselves.', NULL, NULL, '74ca095df02c51cc9ba596438179bb2e0ae6ab2e340981469bb359f68058a611'),
  ('en.sahih', 52, 13, 4748, 'The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say],', NULL, NULL, 'ff54ef914fed40d94d5d1d98cef1939988f98a6049c307741c7eeece77410d4e'),
  ('en.sahih', 52, 14, 4749, '"This is the Fire which you used to deny.', NULL, NULL, '7a03ead44970e34099edab47ea291d956af3fc04ffcc340060750ccf5a873d5f'),
  ('en.sahih', 52, 15, 4750, 'Then is this magic, or do you not see?', NULL, NULL, '5c32c6a443691d52ba7710ed3d36cba8bf54884396244f9be810c280721fd3c4'),
  ('en.sahih', 52, 16, 4751, '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."', NULL, NULL, '0875702115959d6d9bd8f44aa03d0c2e252aa9ba65b1c2ba50f9c44b0e6ea05a'),
  ('en.sahih', 52, 17, 4752, 'Indeed, the righteous will be in gardens and pleasure,', NULL, NULL, 'a07764b38ad85e95a150402b6303038844ae9c2a08eaee5efe85c2c2f20b50d9'),
  ('en.sahih', 52, 18, 4753, 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.', NULL, NULL, '49a6c3aa1de148d632e8faf171aa67b6774a2531437c4a30fc2358dc15c3a7b7'),
  ('en.sahih', 52, 19, 4754, '[They will be told], "Eat and drink in satisfaction for what you used to do."', NULL, NULL, '69c178832a2b7322c28caff501331b9984b43ea6638b2c6383bb58814428d1bf'),
  ('en.sahih', 52, 20, 4755, 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.', NULL, NULL, 'f4a79552e4f9880902a16f19280b737420440e251264ded02b773384a1de4c28'),
  ('en.sahih', 52, 21, 4756, 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.', NULL, NULL, '28e2ddd7bacad0fc5176a138ce0ae647fbee1d6a53fe92a9b293db5cc79caea9'),
  ('en.sahih', 52, 22, 4757, 'And We will provide them with fruit and meat from whatever they desire.', NULL, NULL, '51f17fed7a17143dbb3a077e87310ee30f71005731f7bf9ccb8e23f26848c610'),
  ('en.sahih', 52, 23, 4758, 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.', NULL, NULL, '12dcdba585d9fb0813ce2874630ce818c0d73025d95b964f0784ad8b1840f175'),
  ('en.sahih', 52, 24, 4759, 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.', NULL, NULL, 'd74d2c792b880cf9c860990754e55452fa9a6f28e63781cc917a01b4e9727178'),
  ('en.sahih', 52, 25, 4760, 'And they will approach one another, inquiring of each other.', NULL, NULL, '34de1de76968e65dc56e67864361acc7ea450257d0e3b0c6a38e2c52c8d9cfc5'),
  ('en.sahih', 52, 26, 4761, 'They will say, "Indeed, we were previously among our people fearful [of displeasing Allah].', NULL, NULL, '8ba32aafe3860ba5ce36c18419e28eba21a6ef2fb12a7e25142a2b526778b021'),
  ('en.sahih', 52, 27, 4762, 'So Allah conferred favor upon us and protected us from the punishment of the Scorching Fire.', NULL, NULL, '4cd6ceb6c60952b007b8bbe18e900d840fd532fa717a457fcf8c6b829f45056d'),
  ('en.sahih', 52, 28, 4763, 'Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful."', NULL, NULL, 'df3c43222d99cef6cd2f14711d8f245308967f921cb953484777d39b3ce8fa1f'),
  ('en.sahih', 52, 29, 4764, 'So remind [O Muhammad], for you are not, by the favor of your Lord, a soothsayer or a madman.', NULL, NULL, '71667c7c5a21d5f3699e1c225f40001fe7252ea0774ad9cabaa60ab69a7f08ea'),
  ('en.sahih', 52, 30, 4765, 'Or do they say [of you], "A poet for whom we await a misfortune of time?"', NULL, NULL, 'eb5b439116efe65b5607b4318c828744af0f1469c634951e77c170bd2b49e42e'),
  ('en.sahih', 52, 31, 4766, 'Say, "Wait, for indeed I am, with you, among the waiters."', NULL, NULL, '4f915a36fae1c6f20b9fc6d6b13a38926f336750acfe0ffa259b62ae5cb37b99'),
  ('en.sahih', 52, 32, 4767, 'Or do their minds command them to [say] this, or are they a transgressing people?', NULL, NULL, 'eaa42c85c0aef7eb5115a8acb1d95f4068cbecaead5f8f930e00088b1bb58b53'),
  ('en.sahih', 52, 33, 4768, 'Or do they say, "He has made it up"? Rather, they do not believe.', NULL, NULL, '66bbf8f2cf6d705b2d1d9ba2297a47744140bc03fc1985cbc362a9a60463d10b'),
  ('en.sahih', 52, 34, 4769, 'Then let them produce a statement like it, if they should be truthful.', NULL, NULL, 'abf1a74c1dff5e83e0a8d4273ff9aaea0d7a3c7678b67c311448ca92be3148e3'),
  ('en.sahih', 52, 35, 4770, 'Or were they created by nothing, or were they the creators [of themselves]?', NULL, NULL, '8c047f486e40286a98334e0ee94eeb0d91b5b9b940628b1e841183c7b8a0452c'),
  ('en.sahih', 52, 36, 4771, 'Or did they create the heavens and the earth? Rather, they are not certain.', NULL, NULL, '1601d4ee513269f84f3ba4478d9bb8cd5508422871a50f514e96fece910008dc'),
  ('en.sahih', 52, 37, 4772, 'Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]?', NULL, NULL, 'dce401b409f5a97d8a877533a932f5a01fbe92551b7ff603b41e3f6f75fcca67'),
  ('en.sahih', 52, 38, 4773, 'Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority.', NULL, NULL, '235624150acf2ab2eed17e00f94324f130c0d8894c098ec71e0f49492faf27d5'),
  ('en.sahih', 52, 39, 4774, 'Or has He daughters while you have sons?', NULL, NULL, '4d1dc43d9374313f54f9c7e4c40997d6178579a9af9f479cf40f72397c3b06b7'),
  ('en.sahih', 52, 40, 4775, 'Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down?', NULL, NULL, '7643f5b7699d31ed12f5a66aba4955e3030e5578519dfb9463d84f0669a152c8'),
  ('en.sahih', 52, 41, 4776, 'Or have they [knowledge of] the unseen, so they write [it] down?', NULL, NULL, 'd9247f91f119ed86a589bb1be7726297cc660ff4922c6c7df5cae7d955badad9'),
  ('en.sahih', 52, 42, 4777, 'Or do they intend a plan? But those who disbelieve - they are the object of a plan.', NULL, NULL, 'e4ddb83e6f87feca99a01ace0ae2bd12c0b6347b97caecd4126dd7fe60332f9c'),
  ('en.sahih', 52, 43, 4778, 'Or have they a deity other than Allah? Exalted is Allah above whatever they associate with Him.', NULL, NULL, 'ee7ef8f50fa1a919af59cb0e36546a29f494ba7dfedb09fdba76d94850ad0c9c'),
  ('en.sahih', 52, 44, 4779, 'And if they were to see a fragment from the sky falling, they would say, "[It is merely] clouds heaped up."', NULL, NULL, 'cb649afdb497f31994100e4b6d6287ac641106051a2c18725768be8989c39935'),
  ('en.sahih', 52, 45, 4780, 'So leave them until they meet their Day in which they will be struck insensible -', NULL, NULL, 'dc217b8626f80f10e7f8cdcb49664c0108806f5977c7cb0d1b012589f5ddffa0'),
  ('en.sahih', 52, 46, 4781, 'The Day their plan will not avail them at all, nor will they be helped.', NULL, NULL, '85c63c01f3c8d7554443e75b05301f189df406326a384ec2ae156875a4dfd450'),
  ('en.sahih', 52, 47, 4782, 'And indeed, for those who have wronged is a punishment before that, but most of them do not know.', NULL, NULL, 'd140464c24e015146148c4b0d7a5784f7142569782df9eb1ef4177667ef539f6'),
  ('en.sahih', 52, 48, 4783, 'And be patient, [O Muhammad], for the decision of your Lord, for indeed, you are in Our eyes. And exalt [Allah] with praise of your Lord when you arise.', NULL, NULL, '436c44ab64204ebb94ce13fe9529384eaea2ebf4afd7e0a0aebdc72a6b6807c0'),
  ('en.sahih', 52, 49, 4784, 'And in a part of the night exalt Him and after [the setting of] the stars.', NULL, NULL, '731f9611a437ce3427f166288f95b4b7a5ed30e35b51d95779c3d674219782e4'),
  ('en.sahih', 53, 1, 4785, 'By the star when it descends,', NULL, NULL, 'ee557ef4a5e494a0ed59baa7659766a401d572123e3857bf6d1e0818a0502884'),
  ('en.sahih', 53, 2, 4786, 'Your companion [Muhammad] has not strayed, nor has he erred,', NULL, NULL, '19981b8bb97ccc3976b8a8b9bb14534128fb5c02d2660718e3ec5bedbe47ac53'),
  ('en.sahih', 53, 3, 4787, 'Nor does he speak from [his own] inclination.', NULL, NULL, 'fc13899ed331e79d0f72b51b942fb666297aa223634de11a263905ed11cd85d5'),
  ('en.sahih', 53, 4, 4788, 'It is not but a revelation revealed,', NULL, NULL, 'ca79a43ccaeb2bde983ae3df4bccaad6ea7f85cc9c11245fcf5c90dcbff616ba'),
  ('en.sahih', 53, 5, 4789, 'Taught to him by one intense in strength -', NULL, NULL, 'd03c0b1af75210a48435438b9067f32962f6e171b6039a0de24381b57d45d352'),
  ('en.sahih', 53, 6, 4790, 'One of soundness. And he rose to [his] true form', NULL, NULL, 'e0d259626db0ecbf76a75612c14d7850dd1c2151e02eaea69fbce20caeb8b74f'),
  ('en.sahih', 53, 7, 4791, 'While he was in the higher [part of the] horizon.', NULL, NULL, '92d82fe469f96bdb1c340481913fb91b1d7ba86332b645d1c202c5c8c967d994'),
  ('en.sahih', 53, 8, 4792, 'Then he approached and descended', NULL, NULL, '302527d0e93c4b039fe2dcbd519b16f2b9db4e1f2183a3c7b22bba17e74c4aa5'),
  ('en.sahih', 53, 9, 4793, 'And was at a distance of two bow lengths or nearer.', NULL, NULL, 'b551aa8b50b7f74592c7232e92270491ea1502a38776cc88e354c14a6fbd25eb'),
  ('en.sahih', 53, 10, 4794, 'And he revealed to His Servant what he revealed.', NULL, NULL, '4edbf1bea51b7fd4b70b9ef2abc02b37f38b6de27e5cc178fe0c186e17271714'),
  ('en.sahih', 53, 11, 4795, 'The heart did not lie [about] what it saw.', NULL, NULL, '0ca15f283f6e2df133db5d025bc8812e8072d359afdc9367c251ecaf1189f3ec'),
  ('en.sahih', 53, 12, 4796, 'So will you dispute with him over what he saw?', NULL, NULL, '8214cd94b85ca529720f834995fb30cd7ed82607af1f20478f32dabe20840486'),
  ('en.sahih', 53, 13, 4797, 'And he certainly saw him in another descent', NULL, NULL, 'a23ef049e9d41b88fc47c72bcc1c810a98a7148a5d89616047a9adf1ecb2a219'),
  ('en.sahih', 53, 14, 4798, 'At the Lote Tree of the Utmost Boundary -', NULL, NULL, '50eee271c66cb0980d3263188fda4ed793f65987c48ca08732e4dd089c7b2193'),
  ('en.sahih', 53, 15, 4799, 'Near it is the Garden of Refuge -', NULL, NULL, 'b5e8c11e7a71625ca2c55f1f261c5d23e06b7f6883c19629422246f65387bb89'),
  ('en.sahih', 53, 16, 4800, 'When there covered the Lote Tree that which covered [it].', NULL, NULL, 'ea1fcaf5235b243fa2ed0520a9e8ac71519c4dd94351ba47c70dd268bff80559')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 53, 17, 4801, 'The sight [of the Prophet] did not swerve, nor did it transgress [its limit].', NULL, NULL, '4d7f78221be8c42e2556970e69bdf6f7765b7a4d8fb99d826c05df261ac016e2'),
  ('en.sahih', 53, 18, 4802, 'He certainly saw of the greatest signs of his Lord.', NULL, NULL, 'd192d40d0f187dc497a723c7b7d05f70b2276f026a71b41344d65bd0af198aaf'),
  ('en.sahih', 53, 19, 4803, 'So have you considered al-Lat and al-''Uzza?', NULL, NULL, '49b0a61607cbe30857c0a11007f60bb465b94cc9c51c1671aae36b3488aa014a'),
  ('en.sahih', 53, 20, 4804, 'And Manat, the third - the other one?', NULL, NULL, '63ce2b24cac4ddf62999c599e7ce5a58381221b01169f225da6b2f8c98fd6436'),
  ('en.sahih', 53, 21, 4805, 'Is the male for you and for Him the female?', NULL, NULL, 'd56f6035c8b9e7cbaae5d275dba150d2724ce55975fc70a44dd794e2a1fac5e1'),
  ('en.sahih', 53, 22, 4806, 'That, then, is an unjust division.', NULL, NULL, '0390c8fb16c21734a340419639a8c7acf3acd3a9df80bf597684552a907bcbc7'),
  ('en.sahih', 53, 23, 4807, 'They are not but [mere] names you have named them - you and your forefathers - for which Allah has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance.', NULL, NULL, '7c29bc64f0e2835eca197b3f7cc233084582b7260880dc74cea09bf72bd67fbf'),
  ('en.sahih', 53, 24, 4808, 'Or is there for man whatever he wishes?', NULL, NULL, '88d9e092afac4381fcae6a3539808b68e48bfbb4dd260caa08ba1e5e998ed1b2'),
  ('en.sahih', 53, 25, 4809, 'Rather, to Allah belongs the Hereafter and the first [life].', NULL, NULL, 'ef30bd2b8acfd0c53693cdce0de1cae8a877376595c66144c2d553cd4904f1b8'),
  ('en.sahih', 53, 26, 4810, 'And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allah has permitted [it] to whom He wills and approves.', NULL, NULL, '341a62198a4f5d0ede24a2d3b55660d5c2d57a53690e3df491581297efe1c975'),
  ('en.sahih', 53, 27, 4811, 'Indeed, those who do not believe in the Hereafter name the angels female names,', NULL, NULL, 'b15ddccdb0c459c899e7bc7220d7148114a8845979be3f0dddda041a5c1511ea'),
  ('en.sahih', 53, 28, 4812, 'And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all.', NULL, NULL, 'ffa2f30ee60ab7417413d9777b0872a1ce350015a768200a68f85e40f9295027'),
  ('en.sahih', 53, 29, 4813, 'So turn away from whoever turns his back on Our message and desires not except the worldly life.', NULL, NULL, '6ed1ef3e98449f8f53205cc599823600c457a7de5797cbfa40df9f406c43f487'),
  ('en.sahih', 53, 30, 4814, 'That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided.', NULL, NULL, '22e528a316acac78c0613b3b47e0c885b2c653bb7d0d60db3f5de3e7cb5ebc0b'),
  ('en.sahih', 53, 31, 4815, 'And to Allah belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward] -', NULL, NULL, '9df53424ed1b989710eec9fabb712d41ff1118b56e5078e1950ecafff654f26d'),
  ('en.sahih', 53, 32, 4816, 'Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him.', NULL, NULL, 'fc159cd2a1ee03ac490636486dafe0fff9a24416554d560b3b0f2a3500439d21'),
  ('en.sahih', 53, 33, 4817, 'Have you seen the one who turned away', NULL, NULL, 'f562b005a64af2f1ff7a736c03c0f51415478b424d2d87a94747cead2cb113b6'),
  ('en.sahih', 53, 34, 4818, 'And gave a little and [then] refrained?', NULL, NULL, '6d0f8c8084454a4fb678275991af5cac64833ca175915ed43df3fa7f3408f029'),
  ('en.sahih', 53, 35, 4819, 'Does he have knowledge of the unseen, so he sees?', NULL, NULL, '59ba42221c563e9904b8d72985ae7b86625dbda2f090f168bd62717687b35093'),
  ('en.sahih', 53, 36, 4820, 'Or has he not been informed of what was in the scriptures of Moses', NULL, NULL, 'ba12b40c0bedfc678aca52eccf4c112507dae0960cd8db7e577cacaa86254f1d'),
  ('en.sahih', 53, 37, 4821, 'And [of] Abraham, who fulfilled [his obligations] -', NULL, NULL, 'a749c9aae1bbdb375822d6881e9a18d8f03740b06bf0b397081d1063c881a19d'),
  ('en.sahih', 53, 38, 4822, 'That no bearer of burdens will bear the burden of another', NULL, NULL, '8c1233ebed1d4a960fcedcf0749e80023142b531f77670a4c6ca33a205cb8367'),
  ('en.sahih', 53, 39, 4823, 'And that there is not for man except that [good] for which he strives', NULL, NULL, '5bf96610232f902ce519e9fb770e1cad6d3ed0dab1ce3fc42d08ea29b36b77bb'),
  ('en.sahih', 53, 40, 4824, 'And that his effort is going to be seen -', NULL, NULL, '1d173c285b9ba22ac0e719dc5b27dc90efdaf478380d5de2de33a8173bc9797d'),
  ('en.sahih', 53, 41, 4825, 'Then he will be recompensed for it with the fullest recompense', NULL, NULL, 'f6e79ce196d2093244ec3597bc28ad4070f2d868e542879d28f2495664aac7f8'),
  ('en.sahih', 53, 42, 4826, 'And that to your Lord is the finality', NULL, NULL, 'b7156cd7c47111e52a366d3f2180ade0bf883c9cbb3cda36507160cdaedb4e04'),
  ('en.sahih', 53, 43, 4827, 'And that it is He who makes [one] laugh and weep', NULL, NULL, '291e5dd8f95926ef0a9dba886978ac0c9b29f17f0d14af87a6693e8d827c5f8c'),
  ('en.sahih', 53, 44, 4828, 'And that it is He who causes death and gives life', NULL, NULL, 'e393254f46bd6d9f969dc42f79438fba849411a4ebc8117044464d640fbd0307'),
  ('en.sahih', 53, 45, 4829, 'And that He creates the two mates - the male and female -', NULL, NULL, 'd6a267722174909d80fae54a4ec290df239590e795a2f7ffb0b8f71b3d658c6f'),
  ('en.sahih', 53, 46, 4830, 'From a sperm-drop when it is emitted', NULL, NULL, '6d6f8480392a2768eed1cc1553195546d799a942982c904cd7e349561de42a14'),
  ('en.sahih', 53, 47, 4831, 'And that [incumbent] upon Him is the next creation', NULL, NULL, '6d53a9ad911819ae3544850a708536d9954ed2add1fd5e2207e803a68f979b13'),
  ('en.sahih', 53, 48, 4832, 'And that it is He who enriches and suffices', NULL, NULL, 'ba606361f8c634c1076de4b10e2e5dd198dc6b848377d3dbbd3f0fcbe13d1263'),
  ('en.sahih', 53, 49, 4833, 'And that it is He who is the Lord of Sirius', NULL, NULL, '59fcf23b739e243871e16a52f1edcb76d1afc8f3f06d896dfe84dba591c54bbb'),
  ('en.sahih', 53, 50, 4834, 'And that He destroyed the first [people of] ''Aad', NULL, NULL, 'c7fbb079ebf8dc1724392fb3e33f2d9ba4cc8da2f0635a5c9ef8255822d06bc6'),
  ('en.sahih', 53, 51, 4835, 'And Thamud - and He did not spare [them] -', NULL, NULL, '3526f51082f59aec1ce4ee56c2185f24ad7ef9a91faa8a9a949ad4eefcc84b49'),
  ('en.sahih', 53, 52, 4836, 'And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing.', NULL, NULL, '1163c9d51db5a35544501cb6a5bab4a0020d863f33b75dfa899a0dd61401fe83'),
  ('en.sahih', 53, 53, 4837, 'And the overturned towns He hurled down', NULL, NULL, '5e3664e2104a202d7acf655ea9c15ac915335dcd2f67dcaa54830a4785ca31c4'),
  ('en.sahih', 53, 54, 4838, 'And covered them by that which He covered.', NULL, NULL, '0aafefb2fc53bd73c94f14b2fd3871277e6908f57f595acdc0e687bfa24261e0'),
  ('en.sahih', 53, 55, 4839, 'Then which of the favors of your Lord do you doubt?', NULL, NULL, '63d3ec090aa141f179c1900aca0198af03e55725f9451805a834ffd6ba1038a1'),
  ('en.sahih', 53, 56, 4840, 'This [Prophet] is a warner like the former warners.', NULL, NULL, 'e857add71a55b1ea710009311b7db39d959d42fd332f8d13996a86a04db9ce35'),
  ('en.sahih', 53, 57, 4841, 'The Approaching Day has approached.', NULL, NULL, '94fc26346124d9f8185690824cda124ce58c7b80c73adcb6751fe7f9c4d52c6a'),
  ('en.sahih', 53, 58, 4842, 'Of it, [from those] besides Allah, there is no remover.', NULL, NULL, 'ddec1033201579d60ff27a19ce8ff69cacb9d30fbe1be739e1cf21914d9a1454'),
  ('en.sahih', 53, 59, 4843, 'Then at this statement do you wonder?', NULL, NULL, '5e419694633ea3694ab0a44f6ec15efaaec651223d9bfec70e64fa1a2b0315d8'),
  ('en.sahih', 53, 60, 4844, 'And you laugh and do not weep', NULL, NULL, 'aa85fce87190fbff23270d29442e41170bb20fd894e282d7f3fd1d718229db2e'),
  ('en.sahih', 53, 61, 4845, 'While you are proudly sporting?', NULL, NULL, 'c57b9a268719cad1c3b7261fde79afadd3994ad395eefd55b5440d9dde4afc8f'),
  ('en.sahih', 53, 62, 4846, 'So prostrate to Allah and worship [Him].', NULL, NULL, '9dee427a89dead70a28c62e08462158649ae9388f424a280a2074b43d4982ad5'),
  ('en.sahih', 54, 1, 4847, 'The Hour has come near, and the moon has split [in two].', NULL, NULL, '396f7902a12e28e79b108ee9027db5dce3e978f9266305dbda3de4aa341ad97f'),
  ('en.sahih', 54, 2, 4848, 'And if they see a miracle, they turn away and say, "Passing magic."', NULL, NULL, 'e04f789ca6b3dc7d84c8da44944f1be9746fec65fae8759c64722b6c53117379'),
  ('en.sahih', 54, 3, 4849, 'And they denied and followed their inclinations. But for every matter is a [time of] settlement.', NULL, NULL, '7528546fa54975310a4098f15eefe282fe0c27156cc68ef3601de0e1f19d127c'),
  ('en.sahih', 54, 4, 4850, 'And there has already come to them of information that in which there is deterrence -', NULL, NULL, 'b5a79449c047a841c5d2c4cb99cbfecb4cce9d631709ad99b7f1bd411149191e'),
  ('en.sahih', 54, 5, 4851, 'Extensive wisdom - but warning does not avail [them].', NULL, NULL, 'b9f930c04fbf9617981e011d0d1e5d6e59a2fce358a07399a5c330fa76c379af'),
  ('en.sahih', 54, 6, 4852, 'So leave them, [O Muhammad]. The Day the Caller calls to something forbidding,', NULL, NULL, 'ced5865df3671ee14d75576fb789bb3a462d7db2aad93ba40f3648650177567c'),
  ('en.sahih', 54, 7, 4853, 'Their eyes humbled, they will emerge from the graves as if they were locusts spreading,', NULL, NULL, 'f0b1164a52689a0e48357c4f8d1b3dd308657074cf2d237a23c43356f1102753'),
  ('en.sahih', 54, 8, 4854, 'Racing ahead toward the Caller. The disbelievers will say, "This is a difficult Day."', NULL, NULL, 'd6f368c7ff10b4f8c6dc962759391d6b2f5b043a21a81fefa83b270b11d45cbd'),
  ('en.sahih', 54, 9, 4855, 'The people of Noah denied before them, and they denied Our servant and said, "A madman," and he was repelled.', NULL, NULL, '494385c0488adb5b8582bba42de79849c086f318949e9c1dc8ee41a7eb0fbe3e'),
  ('en.sahih', 54, 10, 4856, 'So he invoked his Lord, "Indeed, I am overpowered, so help."', NULL, NULL, 'c6ed3a4837a6e433446c1c4a6c3295babfc3c1fb6598304c8e18f9fb1d35773a'),
  ('en.sahih', 54, 11, 4857, 'Then We opened the gates of the heaven with rain pouring down', NULL, NULL, '36fb8bcfc0cdd95090ebaee08e1c7758daf393f4ea9c96eec453905aae4fd542'),
  ('en.sahih', 54, 12, 4858, 'And caused the earth to burst with springs, and the waters met for a matter already predestined.', NULL, NULL, '1a328ab7ccf1762b1c69f548756132c4635a6fdbe6690f1997d8151738076f88'),
  ('en.sahih', 54, 13, 4859, 'And We carried him on a [construction of] planks and nails,', NULL, NULL, '621629c601a00128ad711d93ae84947d985c2ad66a3bd668567c8394014eca76'),
  ('en.sahih', 54, 14, 4860, 'Sailing under Our observation as reward for he who had been denied.', NULL, NULL, 'e71d8f39b7765358994119313e023ec32159f5506618910600d479416c9d601a'),
  ('en.sahih', 54, 15, 4861, 'And We left it as a sign, so is there any who will remember?', NULL, NULL, '9a473fa07c0ef029904070ac07fa1344e90a4997be77de8fa1c868495b2c3819'),
  ('en.sahih', 54, 16, 4862, 'And how [severe] were My punishment and warning.', NULL, NULL, 'f288f7dde39c41c774a28bf5772dbbc2ccac007a3400101ca44aa66edc30f1b0'),
  ('en.sahih', 54, 17, 4863, 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, '4c9c444def80e17f3fdc79f4557f7fa065f7ae9be0ce2993fa11d9fe7739729b'),
  ('en.sahih', 54, 18, 4864, '''Aad denied; and how [severe] were My punishment and warning.', NULL, NULL, 'd49f35d98b71594e9e976b14382179ac1c871a9cb95ead88fd4c93e4f40a6101'),
  ('en.sahih', 54, 19, 4865, 'Indeed, We sent upon them a screaming wind on a day of continuous misfortune,', NULL, NULL, '4ec129bd3d76422e01e4d7cc9b4b153ba0573cd06693bec84c851427658bf199'),
  ('en.sahih', 54, 20, 4866, 'Extracting the people as if they were trunks of palm trees uprooted.', NULL, NULL, 'ca35c6dbc4402a742fa85190ca791dc0ac7204b7ef4079bcca96d61bd7079621'),
  ('en.sahih', 54, 21, 4867, 'And how [severe] were My punishment and warning.', NULL, NULL, 'f288f7dde39c41c774a28bf5772dbbc2ccac007a3400101ca44aa66edc30f1b0'),
  ('en.sahih', 54, 22, 4868, 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, '4c9c444def80e17f3fdc79f4557f7fa065f7ae9be0ce2993fa11d9fe7739729b'),
  ('en.sahih', 54, 23, 4869, 'Thamud denied the warning', NULL, NULL, '203c5e2ae4a03a66e63f209712ca1e5cc2db5f12368b05e1b4bbde0b737d9058'),
  ('en.sahih', 54, 24, 4870, 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.', NULL, NULL, 'f57dbe23fbeda0f7557a50d53f0f96fdd11c7c05cc93f651c2c273c5a470a566'),
  ('en.sahih', 54, 25, 4871, 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."', NULL, NULL, 'f4b7d723dd6c1830790697fd663985448590aee746e8980418ed1f12846e9581'),
  ('en.sahih', 54, 26, 4872, 'They will know tomorrow who is the insolent liar.', NULL, NULL, '9819edd02902d53539505d4ecd95c186e5ccca9e021d37ef1bbfd60376ee12af'),
  ('en.sahih', 54, 27, 4873, 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.', NULL, NULL, '748639a4f006bf5fda9e314bfc6ae3999dfa2b4e511d62a8012979cd40ecebc6'),
  ('en.sahih', 54, 28, 4874, 'And inform them that the water is shared between them, each [day of] drink attended [by turn].', NULL, NULL, 'f0c6975d28433a57b013c2b9799101778c4f9ce4d7175c49751e5d2f0eb58bd3'),
  ('en.sahih', 54, 29, 4875, 'But they called their companion, and he dared and hamstrung [her].', NULL, NULL, '9aab0f1a39a9e3d5f0a4ab5f3fc2059038f4c8096cf916c020c4c7e4c5d8b956'),
  ('en.sahih', 54, 30, 4876, 'And how [severe] were My punishment and warning.', NULL, NULL, 'f288f7dde39c41c774a28bf5772dbbc2ccac007a3400101ca44aa66edc30f1b0'),
  ('en.sahih', 54, 31, 4877, 'Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen.', NULL, NULL, '4ab4435efdba9d33e5a23cc62691425be955bd35b652ace5d3fa531483c35c35'),
  ('en.sahih', 54, 32, 4878, 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, '4c9c444def80e17f3fdc79f4557f7fa065f7ae9be0ce2993fa11d9fe7739729b'),
  ('en.sahih', 54, 33, 4879, 'The people of Lot denied the warning.', NULL, NULL, '547865fd80cfb93eb4fd5e38a4bf05a745af4f6b2da2bc1a7703623286711f6a'),
  ('en.sahih', 54, 34, 4880, 'Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn', NULL, NULL, 'c20811e0f48d5561d903d69f5b8495c6cccc710ec861a73bdaa0c9f88f51fdba'),
  ('en.sahih', 54, 35, 4881, 'As favor from us. Thus do We reward he who is grateful.', NULL, NULL, 'a75f57148c97a4ce81297c0985b63b80909ce3fbd12b1c110def36ec4cfc238d'),
  ('en.sahih', 54, 36, 4882, 'And he had already warned them of Our assault, but they disputed the warning.', NULL, NULL, '4c118eac877a9108fde3c4ff4e39fa736a2efe2d76d8c23147b02f966a229591'),
  ('en.sahih', 54, 37, 4883, 'And they had demanded from him his guests, but We obliterated their eyes, [saying], "Taste My punishment and warning."', NULL, NULL, 'a29b86e334d8294ebb0611647d357cdd53e6fb6cbf7a32f03c24a6ce43c8e3bd'),
  ('en.sahih', 54, 38, 4884, 'And there came upon them by morning an abiding punishment.', NULL, NULL, 'f8a82d4f6d1ec577abc5bc01ebba66927c49e2043688b5da3dd003ac17b5f1dd'),
  ('en.sahih', 54, 39, 4885, 'So taste My punishment and warning.', NULL, NULL, '383888797f3c6b0f0391280425043691f5f79d2e776c7e53173853ac3d3d0bbc'),
  ('en.sahih', 54, 40, 4886, 'And We have certainly made the Qur''an easy for remembrance, so is there any who will remember?', NULL, NULL, '4c9c444def80e17f3fdc79f4557f7fa065f7ae9be0ce2993fa11d9fe7739729b'),
  ('en.sahih', 54, 41, 4887, 'And there certainly came to the people of Pharaoh warning.', NULL, NULL, '2ed7a875cd43dd142a6693bacb71a3fe3b3d6bf2f4edb934ebe26a90af39bb42'),
  ('en.sahih', 54, 42, 4888, 'They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability.', NULL, NULL, '94293eedb365a7636eec57cb93495743f7fbfa5864b97ef2d29392a9b9d74c31'),
  ('en.sahih', 54, 43, 4889, 'Are your disbelievers better than those [former ones], or have you immunity in the scripture?', NULL, NULL, 'e22eadb5ae52a80fdf8f73da78041544b21ca0df2ab57e3defdef80923553bff'),
  ('en.sahih', 54, 44, 4890, 'Or do they say, "We are an assembly supporting [each other]"?', NULL, NULL, 'ec63e5b9fa9d5db70e46d070cc8a2fee0267f21e30722b488aab3bed898eb080'),
  ('en.sahih', 54, 45, 4891, '[Their] assembly will be defeated, and they will turn their backs [in retreat].', NULL, NULL, 'ed047e9cb0534fd90db366575403fc3d7c6b0d8605feebb037257dde5c3dcb13'),
  ('en.sahih', 54, 46, 4892, 'But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter.', NULL, NULL, 'a653f83626c9ee00ee2318b86cd3a60357aa59ee5008d1537da9909da9e5b2c9'),
  ('en.sahih', 54, 47, 4893, 'Indeed, the criminals are in error and madness.', NULL, NULL, '05fc8d9aa3910ac115a718db96f1fa29f1395cc9164959a8e3ea98fb516e5a94'),
  ('en.sahih', 54, 48, 4894, 'The Day they are dragged into the Fire on their faces [it will be said], "Taste the touch of Saqar."', NULL, NULL, '162fc9de0de1a7f977bbae6d10a8fbd204c32f04a4248e0c4bf5fe0436e71626'),
  ('en.sahih', 54, 49, 4895, 'Indeed, all things We created with predestination.', NULL, NULL, 'd18672c04f5cbbdd43fe05e0bfffb03835508ed401bc926954bb0327149f9c2e'),
  ('en.sahih', 54, 50, 4896, 'And Our command is but one, like a glance of the eye.', NULL, NULL, '6cf822b8691e0ab44f6d29f714b3eb003c2b6a7352930e4a14b1db3f134d8e0d'),
  ('en.sahih', 54, 51, 4897, 'And We have already destroyed your kinds, so is there any who will remember?', NULL, NULL, '7e05d350927761392eed236accdd9d93babc5c65a4487a7328e7fc06fec5b8ae'),
  ('en.sahih', 54, 52, 4898, 'And everything they did is in written records.', NULL, NULL, '3579e0dba7bf98a2810fe766050494b238cf3995c29c61f07f3876996280440c'),
  ('en.sahih', 54, 53, 4899, 'And every small and great [thing] is inscribed.', NULL, NULL, '8a4a2e6c76b521ec8717ee7a59173c1da2c6e8a0b03f3cdafa2a4c433f9df8af'),
  ('en.sahih', 54, 54, 4900, 'Indeed, the righteous will be among gardens and rivers,', NULL, NULL, 'a804d57c334bdc40a57447772aeb4d42aa9b458c2e9912e35db8aeb6a8c69370')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 54, 55, 4901, 'In a seat of honor near a Sovereign, Perfect in Ability.', NULL, NULL, 'cbea23ae81ed20362908a59d739051d3922aeb702ca629af664b813d29a72b8e'),
  ('en.sahih', 55, 1, 4902, 'The Most Merciful', NULL, NULL, '380f2f4e3f38abd70a54f0a938400538ce3c6591ca915b50f22d1ebeff335141'),
  ('en.sahih', 55, 2, 4903, 'Taught the Qur''an,', NULL, NULL, '6d8910c24f5dda1d4725646e6d5e6477333352b71f75a5e12d49ab959a2025c4'),
  ('en.sahih', 55, 3, 4904, 'Created man,', NULL, NULL, 'ac347f922414ac29a077bb4a000821efea2a0daa979b480ead6264b81a090cc2'),
  ('en.sahih', 55, 4, 4905, '[And] taught him eloquence.', NULL, NULL, '18d18735bad4ffcdbe3d095706815d57186cb77ab24a5948b6f59d6d036f61d7'),
  ('en.sahih', 55, 5, 4906, 'The sun and the moon [move] by precise calculation,', NULL, NULL, 'c5a2ee926e2a2fff7bd715053d8cbf703743961160730be5bea9a3e51762b7a8'),
  ('en.sahih', 55, 6, 4907, 'And the stars and trees prostrate.', NULL, NULL, '8bb62af55321686d33d4046c85c24f55ffdb3f1959aed02a05a5183c9a5ecb9f'),
  ('en.sahih', 55, 7, 4908, 'And the heaven He raised and imposed the balance', NULL, NULL, 'd40709cd54a249efcdb75fa2a655a4df341fd063bc40f958beca02d20bb526a4'),
  ('en.sahih', 55, 8, 4909, 'That you not transgress within the balance.', NULL, NULL, 'a7c5495817ad442ce1d1e3f8a962d78264319bdad2bf9d4235d0868c83a0614e'),
  ('en.sahih', 55, 9, 4910, 'And establish weight in justice and do not make deficient the balance.', NULL, NULL, 'f19df842680e1124710bf5850d6b24e9835d987e90df7cdde9f5f283a517a257'),
  ('en.sahih', 55, 10, 4911, 'And the earth He laid [out] for the creatures.', NULL, NULL, '9fdeae5592d2b3cb75bfbf8ca659697c7512accd0653c1e7d36922d76c9196e6'),
  ('en.sahih', 55, 11, 4912, 'Therein is fruit and palm trees having sheaths [of dates]', NULL, NULL, '369e91dd94edd6ba8ce3a9a1a2186b3223e017657e748f362557a91ec902ef68'),
  ('en.sahih', 55, 12, 4913, 'And grain having husks and scented plants.', NULL, NULL, '9c13cf8911a1b5965e9e886836f853462036f3de83efabec82c2eecb8a8221f7'),
  ('en.sahih', 55, 13, 4914, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 14, 4915, 'He created man from clay like [that of] pottery.', NULL, NULL, '0a16547270b6df5922424beefcd4dfb00d963f1ed001e7b186f1952573d0f78b'),
  ('en.sahih', 55, 15, 4916, 'And He created the jinn from a smokeless flame of fire.', NULL, NULL, '006c10c2f2f7e2b07ff46b375e9691d1c9c9b5bbfa60e50f669040fd1d2b4559'),
  ('en.sahih', 55, 16, 4917, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 17, 4918, '[He is] Lord of the two sunrises and Lord of the two sunsets.', NULL, NULL, '4e83d66e5ef3361a03137ec2637088230fd872afb0533ecb08e47da330703424'),
  ('en.sahih', 55, 18, 4919, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 19, 4920, 'He released the two seas, meeting [side by side];', NULL, NULL, '71a9b3d753cd83a2daea974cfd3547fd16a1cc3585289c3130b6ae6b1cfa92fe'),
  ('en.sahih', 55, 20, 4921, 'Between them is a barrier [so] neither of them transgresses.', NULL, NULL, '45ae9c90b1931b393283d2acf9458c09f345c918311e6888749a582c5c4ba494'),
  ('en.sahih', 55, 21, 4922, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 22, 4923, 'From both of them emerge pearl and coral.', NULL, NULL, 'c94680a058def1d5dc18392a0491b9902a1bdceec624bb7797658c25b397804e'),
  ('en.sahih', 55, 23, 4924, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 24, 4925, 'And to Him belong the ships [with sails] elevated in the sea like mountains.', NULL, NULL, '95e4abf6c66369eefe33fceba00a5bdb620c75ec76225842262d1de880983659'),
  ('en.sahih', 55, 25, 4926, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 26, 4927, 'Everyone upon the earth will perish,', NULL, NULL, '48bd4d26552a1ccfe4ef41636aacc9d8fb5c01eb88999dc084659f53307c4eb7'),
  ('en.sahih', 55, 27, 4928, 'And there will remain the Face of your Lord, Owner of Majesty and Honor.', NULL, NULL, 'd9610424219ba130d95b1c45301a23304a7a66600b3301b806d76532d98c48f4'),
  ('en.sahih', 55, 28, 4929, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 29, 4930, 'Whoever is within the heavens and earth asks Him; every day He is bringing about a matter.', NULL, NULL, 'cb5cbf3a1bf5c1f4664fea63a522d3ec83641603a61f14e2ea9deb7509cac890'),
  ('en.sahih', 55, 30, 4931, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 31, 4932, 'We will attend to you, O prominent beings.', NULL, NULL, '02035e46510ce28112a2756aa0a28ca8bdd2657404ba9b5f1ac09fa1ded971d8'),
  ('en.sahih', 55, 32, 4933, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 33, 4934, 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah].', NULL, NULL, '4793532b34d7845d557d2ee8f8c2f1185943519ed182b2c551585797bfdccc18'),
  ('en.sahih', 55, 34, 4935, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 35, 4936, 'There will be sent upon you a flame of fire and smoke, and you will not defend yourselves.', NULL, NULL, 'd1fc6cf931c2b723225de6f344833e6b462703e8da935c23ab68857af9d6484e'),
  ('en.sahih', 55, 36, 4937, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 37, 4938, 'And when the heaven is split open and becomes rose-colored like oil -', NULL, NULL, '2d42cd28a5282b68a3cbd38c6e35c1ee307bceb225a73484bb1c2fef22815f4a'),
  ('en.sahih', 55, 38, 4939, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 39, 4940, 'Then on that Day none will be asked about his sin among men or jinn.', NULL, NULL, 'ee728d25d1f4857c22874455431835996434db4887f5bbec94b57f07ed04914b'),
  ('en.sahih', 55, 40, 4941, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 41, 4942, 'The criminals will be known by their marks, and they will be seized by the forelocks and the feet.', NULL, NULL, 'f6c60fa0e80899c2faab67e66626a8efe1bc462ecba4ad192b8889e276886d3c'),
  ('en.sahih', 55, 42, 4943, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 43, 4944, 'This is Hell, which the criminals deny.', NULL, NULL, 'bf5b1b2cbba59c0de0afb499942bd4acfa8c319292b49db59efe1a7278957da2'),
  ('en.sahih', 55, 44, 4945, 'They will go around between it and scalding water, heated [to the utmost degree].', NULL, NULL, '087199abac0c26a9c85985fed835f0cb6720024727e0fb1723c53e927a7e7529'),
  ('en.sahih', 55, 45, 4946, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 46, 4947, 'But for he who has feared the position of his Lord are two gardens -', NULL, NULL, 'bca8c9bc50e2bff7e8808120a01ccc893241ddc27e89b0f6b8bde17046681bec'),
  ('en.sahih', 55, 47, 4948, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 48, 4949, 'Having [spreading] branches.', NULL, NULL, 'f75a6a9e9a7b9c1cbd2f456b0296ba95324c84dba9a30c853632962d81f7ee83'),
  ('en.sahih', 55, 49, 4950, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 50, 4951, 'In both of them are two springs, flowing.', NULL, NULL, '1534ccd12afde2709f4f769c48aa5f5376b01a91aefb06199c8d59f9ff58cbaf'),
  ('en.sahih', 55, 51, 4952, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 52, 4953, 'In both of them are of every fruit, two kinds.', NULL, NULL, 'c4f5cd7be2cb862b35e4f36d94bf36bda844f29ded574a594343a975ccd707ae'),
  ('en.sahih', 55, 53, 4954, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 54, 4955, '[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low.', NULL, NULL, '89e9d2ffe07a7fa13874ca3524886b26c120da931cd0544fc9470f4b5c56757d'),
  ('en.sahih', 55, 55, 4956, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 56, 4957, 'In them are women limiting [their] glances, untouched before them by man or jinni -', NULL, NULL, '9ef6ddded15ae9b18e9727452de4b878a3ba25b162a01281f0a6268c817a136b'),
  ('en.sahih', 55, 57, 4958, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 58, 4959, 'As if they were rubies and coral.', NULL, NULL, '6f5b29f16aa27a888c3ad655a0ed518fd571d9e30a8c21625ce1dab3b05bb705'),
  ('en.sahih', 55, 59, 4960, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 60, 4961, 'Is the reward for good [anything] but good?', NULL, NULL, '4ed2a1ba8791e3fa1d1bb78ae74f0b8d2e4eb181de7327cf8617ee932490aa83'),
  ('en.sahih', 55, 61, 4962, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 62, 4963, 'And below them both [in excellence] are two [other] gardens -', NULL, NULL, 'be9d365729ff45455b98b673e28d7c775a6ba3f9429de291f1b9d92cc051953e'),
  ('en.sahih', 55, 63, 4964, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 64, 4965, 'Dark green [in color].', NULL, NULL, 'c3151a8574c74a643c5cbfa3ab1c8dc0ebb2c0ca11d7f495dd3c63c954c24026'),
  ('en.sahih', 55, 65, 4966, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 66, 4967, 'In both of them are two springs, spouting.', NULL, NULL, '8c6ea4d1531f2318cb0c182f6bff07fc5adac56077707b607467be56bf710eee'),
  ('en.sahih', 55, 67, 4968, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 68, 4969, 'In both of them are fruit and palm trees and pomegranates.', NULL, NULL, 'e3772efb1b97d3048a3f308c82679fd0f6c1c21fda341a8dc9337146f6227bb3'),
  ('en.sahih', 55, 69, 4970, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 70, 4971, 'In them are good and beautiful women -', NULL, NULL, '97885bf4b13cba17b8295f940fdc9671d18a3a89daef18e9f4d94afb62663124'),
  ('en.sahih', 55, 71, 4972, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 72, 4973, 'Fair ones reserved in pavilions -', NULL, NULL, '0ba1bd03d907049acd86e9379bb7877af0a575e6a5698c3548b4bbd860d52e9a'),
  ('en.sahih', 55, 73, 4974, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 74, 4975, 'Untouched before them by man or jinni -', NULL, NULL, '9b53f383dd2763ec71497351f8853651ea85c5d62b6004fecb5924941cc75d8c'),
  ('en.sahih', 55, 75, 4976, 'So which of the favors of your Lord would you deny? -', NULL, NULL, 'dc58882082a2548620f48130e952ba2aaa2c728e7c0c3fd1980e0f0a8a8d8267'),
  ('en.sahih', 55, 76, 4977, 'Reclining on green cushions and beautiful fine carpets.', NULL, NULL, '623868c63e77ab9dcf5486a94ffe741499e93846709fde8c95dd80c1f23d2d46'),
  ('en.sahih', 55, 77, 4978, 'So which of the favors of your Lord would you deny?', NULL, NULL, '50a9a1eab9cb96b67ee685b25aa3d7740d6f0eef50f9d34903ad0f4210bd7afe'),
  ('en.sahih', 55, 78, 4979, 'Blessed is the name of your Lord, Owner of Majesty and Honor.', NULL, NULL, 'f57d01119b1e877e26c1b933e767bc29ca31b48cb6a79b143be89bab82dcca0b'),
  ('en.sahih', 56, 1, 4980, 'When the Occurrence occurs,', NULL, NULL, '373a388b9694e58bfcb90d763015d36e461b1c31f7e21abd5414ecdfbac28f37'),
  ('en.sahih', 56, 2, 4981, 'There is, at its occurrence, no denial.', NULL, NULL, 'c7022e3254c30a5b515ac6afffe6cc71974d3b274c639997adf8b1088852eb2a'),
  ('en.sahih', 56, 3, 4982, 'It will bring down [some] and raise up [others].', NULL, NULL, 'b374fe49231b4625881d3469b587b7e0f0a8d0ae9e160645a897a52e49aecd0d'),
  ('en.sahih', 56, 4, 4983, 'When the earth is shaken with convulsion', NULL, NULL, '69f45d9dd5e4070a7aa479da43746a7ea7780d1c0f729974861a6add734c9963'),
  ('en.sahih', 56, 5, 4984, 'And the mountains are broken down, crumbling', NULL, NULL, '497fa786523ba64289e26199d8fac5ec334045815cf7034af57eab5208bfa11e'),
  ('en.sahih', 56, 6, 4985, 'And become dust dispersing.', NULL, NULL, '4e16cadc3b91b34de82291baf4274ef1b3baf5c9a9e9f2ada6fca9b69caa3e8c'),
  ('en.sahih', 56, 7, 4986, 'And you become [of] three kinds:', NULL, NULL, 'cce44a7afd9398118ccc6599043ff0c1c5eb3cedc4472fc74e0e11f2e9ccb55b'),
  ('en.sahih', 56, 8, 4987, 'Then the companions of the right - what are the companions of the right?', NULL, NULL, '671568174bb687f68dd2ca98786f9205ea3f1d1b415acaa3abb5e637d8d2ac87'),
  ('en.sahih', 56, 9, 4988, 'And the companions of the left - what are the companions of the left?', NULL, NULL, '361479e2950e5ad692d5d5c4b89c29fd50cbeb123d92955689cfa4c6d13b0ce7'),
  ('en.sahih', 56, 10, 4989, 'And the forerunners, the forerunners -', NULL, NULL, '47519d0455d7f0fe83dbb66b2260b73602ac8fb66cde182161689779c0c5fe0b'),
  ('en.sahih', 56, 11, 4990, 'Those are the ones brought near [to Allah]', NULL, NULL, 'aebf043b36497ec627cf484d8c0cbb0f48a1298e8ba6f3167adfb7a3324baca3'),
  ('en.sahih', 56, 12, 4991, 'In the Gardens of Pleasure,', NULL, NULL, '7963252937c94cab7144db964a06b3db189a322dcf16fb1a26148cecdc6e58d9'),
  ('en.sahih', 56, 13, 4992, 'A [large] company of the former peoples', NULL, NULL, '27213c25fc5bcde700fdb3e96fe36bde9059014d1dcf3fc44b524b9fa377d3d3'),
  ('en.sahih', 56, 14, 4993, 'And a few of the later peoples,', NULL, NULL, 'c51c9120d640f4d360f59fa7904b907199460c4e5aaa776a6f5cc07cab40632b'),
  ('en.sahih', 56, 15, 4994, 'On thrones woven [with ornament],', NULL, NULL, 'ccd8bb7cffc2e359292fdb35803fc3765b7a424ad7efc6800520c0f40c87790d'),
  ('en.sahih', 56, 16, 4995, 'Reclining on them, facing each other.', NULL, NULL, 'e0ee3f7f1e63aac53bdae9b5b0fbe42bf1c6e8393b6e420f75d0e94bfcc190e2'),
  ('en.sahih', 56, 17, 4996, 'There will circulate among them young boys made eternal', NULL, NULL, 'f2ce40f30bab6ae31b0783c548c074dde27728577cfb5c96592728878efbc1b9'),
  ('en.sahih', 56, 18, 4997, 'With vessels, pitchers and a cup [of wine] from a flowing spring -', NULL, NULL, 'ed29bd019246fc0a3c6bf880daa964d0c9bd2884eebf9fc87b3a481e82e3dc71'),
  ('en.sahih', 56, 19, 4998, 'No headache will they have therefrom, nor will they be intoxicated -', NULL, NULL, '9339770b0d6ccef88e9016e57c5516372fcd5edf46fca2694df88fc82f8d3ff0'),
  ('en.sahih', 56, 20, 4999, 'And fruit of what they select', NULL, NULL, 'ad5352ded8f46f84c145b285164906264390fa5822e5b6eee78492cfb201ed61'),
  ('en.sahih', 56, 21, 5000, 'And the meat of fowl, from whatever they desire.', NULL, NULL, '457676d31150006f27a1c9c9e48c0fcc19fc6faff2aa7c4e0818d8431101186d')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 56, 22, 5001, 'And [for them are] fair women with large, [beautiful] eyes,', NULL, NULL, 'fa3f631c5f5dd14d224d42a8f38184593f1127c9f178c9b75195343cd77c8983'),
  ('en.sahih', 56, 23, 5002, 'The likenesses of pearls well-protected,', NULL, NULL, '77c9bb645efccfa3fed7a976bfaf719afaf026dc337e10fd21ed94096fc6ea17'),
  ('en.sahih', 56, 24, 5003, 'As reward for what they used to do.', NULL, NULL, 'f281919468e9b9df83da758b6f7c6936519774a0c37c10e42b087b1335be70fa'),
  ('en.sahih', 56, 25, 5004, 'They will not hear therein ill speech or commission of sin -', NULL, NULL, 'ee0a3ea629845aa19dca748b89b43c25c1d1af48a6ef133c61a118bff6de1147'),
  ('en.sahih', 56, 26, 5005, 'Only a saying: "Peace, peace."', NULL, NULL, 'beeabe1b8fb4c95b0712eb5b223610b16143a800aa9f34509fa5b5cc174b75a1'),
  ('en.sahih', 56, 27, 5006, 'The companions of the right - what are the companions of the right?', NULL, NULL, '0d3e709740c6ff6d21e517bc9766cc0914a35408379f6061b7166517c2e86af9'),
  ('en.sahih', 56, 28, 5007, '[They will be] among lote trees with thorns removed', NULL, NULL, 'fdf41f0d19bfe57dbfafe08e8d0cfc90d71041386ced0108f5a81e1164ec36da'),
  ('en.sahih', 56, 29, 5008, 'And [banana] trees layered [with fruit]', NULL, NULL, '7f51534fb2162d4801847aa73d06caf5211a95f4ea8cc50b833a4ea9cafe3b69'),
  ('en.sahih', 56, 30, 5009, 'And shade extended', NULL, NULL, 'd66aa1697a7f5da44f079f3e14da989d53aafb967f79134057f9b4e8880300f2'),
  ('en.sahih', 56, 31, 5010, 'And water poured out', NULL, NULL, '73cd0f64d22a1d2a90bf243d5686ade1f2c9d2f149535f890e6c0d98d234b0f5'),
  ('en.sahih', 56, 32, 5011, 'And fruit, abundant [and varied],', NULL, NULL, '5c6f02c1148045a94e8975d52e573df0e76f942006efa0be91d9a65dba28b0e6'),
  ('en.sahih', 56, 33, 5012, 'Neither limited [to season] nor forbidden,', NULL, NULL, '17f2c1ee8158e95417e6b8b236650b7930c10227a050352483de0fe23c123976'),
  ('en.sahih', 56, 34, 5013, 'And [upon] beds raised high.', NULL, NULL, 'd34fc1d8dbd8f66b6ff3214ea11d5a98b73f71f22525f8819ce7442240b21bcd'),
  ('en.sahih', 56, 35, 5014, 'Indeed, We have produced the women of Paradise in a [new] creation', NULL, NULL, '2c0a47349fc21bad91f62eaaf4958c5c556d358f361094023eff681817dd2f2b'),
  ('en.sahih', 56, 36, 5015, 'And made them virgins,', NULL, NULL, 'c01c33d4e410c963ad8df41b6e4590a045ab60d9e281b07ea7befb7f00081520'),
  ('en.sahih', 56, 37, 5016, 'Devoted [to their husbands] and of equal age,', NULL, NULL, 'debf3d81665ea67baac9ad3e43773f15ebdb2082dd8096dd2372201ce30b4855'),
  ('en.sahih', 56, 38, 5017, 'For the companions of the right [who are]', NULL, NULL, '60ce5f2dba46623a41b0e4fcc2e8a93e21955310961ac201103dabab0d87f5f0'),
  ('en.sahih', 56, 39, 5018, 'A company of the former peoples', NULL, NULL, '34f8f7f35cf66673544fd7e517303e0f3e7db8952bb531afb4ae95d62955e1ef'),
  ('en.sahih', 56, 40, 5019, 'And a company of the later peoples.', NULL, NULL, '99352383ac0ec18f494998e1bdef710a6c24617ade834d222ea68264c5c06a96'),
  ('en.sahih', 56, 41, 5020, 'And the companions of the left - what are the companions of the left?', NULL, NULL, '361479e2950e5ad692d5d5c4b89c29fd50cbeb123d92955689cfa4c6d13b0ce7'),
  ('en.sahih', 56, 42, 5021, '[They will be] in scorching fire and scalding water', NULL, NULL, '34c3ca00027ff04b823a5c3fafee2919cbef7d0c6ecbd632e75f02740ca2af45'),
  ('en.sahih', 56, 43, 5022, 'And a shade of black smoke,', NULL, NULL, 'e57356cf30e68bdd429a5ee3986355a9eeaa6709616e1168db3fe9a93e19cf09'),
  ('en.sahih', 56, 44, 5023, 'Neither cool nor beneficial.', NULL, NULL, '21bcac676c2795e73541ee8af12e5d7f0e1c0649580b6795f0765defd50fa856'),
  ('en.sahih', 56, 45, 5024, 'Indeed they were, before that, indulging in affluence,', NULL, NULL, 'b1c8f5e674cac01d60f8fd69843c5e378fc030b6e442a866ca3dc04d74d2fdf6'),
  ('en.sahih', 56, 46, 5025, 'And they used to persist in the great violation,', NULL, NULL, 'bb91325edc001b5df44e0d1565e0d308524cfb81f47ad27b1273c9f1c53afd10'),
  ('en.sahih', 56, 47, 5026, 'And they used to say, "When we die and become dust and bones, are we indeed to be resurrected?', NULL, NULL, 'a86bf72ff3754d4787ffe6423041dac8479ed91eb1af0aebe7779ac551dafa56'),
  ('en.sahih', 56, 48, 5027, 'And our forefathers [as well]?"', NULL, NULL, 'e3252d59bc61776bdc8ba91dafba8d69ee877c31c6e58d8b99901c80bdf8ded3'),
  ('en.sahih', 56, 49, 5028, 'Say, [O Muhammad], "Indeed, the former and the later peoples', NULL, NULL, 'a3735f3048a783c38b99c1df0ec398375995baf8be151e7172a816c031142dea'),
  ('en.sahih', 56, 50, 5029, 'Are to be gathered together for the appointment of a known Day."', NULL, NULL, 'b52edbf09084fc03c1477e06aa9cee23a6eb8b3c0f0a1859667e3c18941ea799'),
  ('en.sahih', 56, 51, 5030, 'Then indeed you, O those astray [who are] deniers,', NULL, NULL, '397d0c9121d280ea668b8f858364c72607ece4dad80f94f030614734a18ea6d3'),
  ('en.sahih', 56, 52, 5031, 'Will be eating from trees of zaqqum', NULL, NULL, '0795eaed7467769c7fd4641f65e5ae58734cece33ae0ce90c176960234d38ae6'),
  ('en.sahih', 56, 53, 5032, 'And filling with it your bellies', NULL, NULL, '3bc38a006d42d1dc08f547c1f564b856bd55b9cdb00972dcc9de6b7ffdf1bb32'),
  ('en.sahih', 56, 54, 5033, 'And drinking on top of it from scalding water', NULL, NULL, '563a2a45de8b2139548cddc3d4f1c3611e43ce0c247ef4ab7c85ada5d11bbacb'),
  ('en.sahih', 56, 55, 5034, 'And will drink as the drinking of thirsty camels.', NULL, NULL, 'd79a73fdd380902a690f8267868c9bf233a677d26c83fb17a3bd01ea4edd126c'),
  ('en.sahih', 56, 56, 5035, 'That is their accommodation on the Day of Recompense.', NULL, NULL, '59baacf27d6e7df666ee7fac84d20de6a8bb0d5dd45f12f7469a271cf6d7c6bf'),
  ('en.sahih', 56, 57, 5036, 'We have created you, so why do you not believe?', NULL, NULL, '0cfdd5b027e3e26ae76aa0c95c46e7b286fcd1ebeba390ceaf49353fa6b81445'),
  ('en.sahih', 56, 58, 5037, 'Have you seen that which you emit?', NULL, NULL, 'f7084bd2eb73012146cbacc7111712731c4264ec8b4c8334206748021c6fbbf5'),
  ('en.sahih', 56, 59, 5038, 'Is it you who creates it, or are We the Creator?', NULL, NULL, '16f83e7e57897c56b05e26e61433ce9529cb8350d0ee54488158d80563fad153'),
  ('en.sahih', 56, 60, 5039, 'We have decreed death among you, and We are not to be outdone', NULL, NULL, '2b4a535d81a643567749d15a5e6c8129ba1562d6e4e31c9e7abd7758797f7965'),
  ('en.sahih', 56, 61, 5040, 'In that We will change your likenesses and produce you in that [form] which you do not know.', NULL, NULL, '678ae2497e817f4857d403b5fbb86df40d1907aaf6dee22fd02f6e5cbbdba8b6'),
  ('en.sahih', 56, 62, 5041, 'And you have already known the first creation, so will you not remember?', NULL, NULL, 'b52e981af4ed1b6c1a31f83f23697c78ea80641ae8adef27f296230da0c5f369'),
  ('en.sahih', 56, 63, 5042, 'And have you seen that [seed] which you sow?', NULL, NULL, '40ab5ee44f5370a3d709a95504cd058a63dc79a544d3660cf8d4b02516e7d674'),
  ('en.sahih', 56, 64, 5043, 'Is it you who makes it grow, or are We the grower?', NULL, NULL, '7a5a4a2d0589385f42d18b1174d6866845318a9b5b3ac257e4026ffc0f4789af'),
  ('en.sahih', 56, 65, 5044, 'If We willed, We could make it [dry] debris, and you would remain in wonder,', NULL, NULL, '778320085d33b383b7238d63be0a57fba56223250e06fc9669fd71b55110db39'),
  ('en.sahih', 56, 66, 5045, '[Saying], "Indeed, we are [now] in debt;', NULL, NULL, 'c8884d0867ce57fea55b90724867c7dfefa2df170f19e3d4a4e77377d30bec25'),
  ('en.sahih', 56, 67, 5046, 'Rather, we have been deprived."', NULL, NULL, '5734366bc766c56fe5ae3228eeb2f21e4829e63e35a198ea652766ac3f25bf0d'),
  ('en.sahih', 56, 68, 5047, 'And have you seen the water that you drink?', NULL, NULL, '75e87aa73edb875768b055401c46bd1a7899d897c9abb67620c55b42d3757f27'),
  ('en.sahih', 56, 69, 5048, 'Is it you who brought it down from the clouds, or is it We who bring it down?', NULL, NULL, 'b84625af1b7dc42544667db2a94e1d75c616f31ac338ed68974785ea568ce819'),
  ('en.sahih', 56, 70, 5049, 'If We willed, We could make it bitter, so why are you not grateful?', NULL, NULL, '6beda8b7866ef5c8948da1ebe4dde7e545802138f85fbf3904ded17e64c6de13'),
  ('en.sahih', 56, 71, 5050, 'And have you seen the fire that you ignite?', NULL, NULL, 'cd281b94d245331570e253a15227f315af5d0395035edf5d5dc6202bc20a6e80'),
  ('en.sahih', 56, 72, 5051, 'Is it you who produced its tree, or are We the producer?', NULL, NULL, '9949a9c16b72ee2c793c69827c45daa6a8d773298496c54fe571eded21b968d2'),
  ('en.sahih', 56, 73, 5052, 'We have made it a reminder and provision for the travelers,', NULL, NULL, '047445cd906a9a2be5a42be1b5f18b76be83286456392eb28a2ba994027f4c91'),
  ('en.sahih', 56, 74, 5053, 'So exalt the name of your Lord, the Most Great.', NULL, NULL, '08981e024909026d286f8f09888619fdfb6d8af9fa59c685d1acc0c484cfced6'),
  ('en.sahih', 56, 75, 5054, 'Then I swear by the setting of the stars,', NULL, NULL, 'd248a37a1375dc0b688da71afcdb6b61eac799c7a0ef0ce2cf5ae701942059d4'),
  ('en.sahih', 56, 76, 5055, 'And indeed, it is an oath - if you could know - [most] great.', NULL, NULL, '295cbc1b13d96f4721f61170c46ecd217430a3481d851aa2638148ebbfbf51cc'),
  ('en.sahih', 56, 77, 5056, 'Indeed, it is a noble Qur''an', NULL, NULL, '7a5d4e776f1715e5637f9627785d9d0900120e0c032f6c2ce739ec56ede24332'),
  ('en.sahih', 56, 78, 5057, 'In a Register well-protected;', NULL, NULL, '37bca9080c64271e3595c96f1b5a5180f720213a10d863b5c4bc678c4880a9f4'),
  ('en.sahih', 56, 79, 5058, 'None touch it except the purified.', NULL, NULL, 'd155cf0b7b82f08aed17a552f412a02198eeb12a9cb166e2df1c8d38f1ac13c9'),
  ('en.sahih', 56, 80, 5059, '[It is] a revelation from the Lord of the worlds.', NULL, NULL, 'bd22e18822c81578b1586128b75971f56d9ae6c434681cd9c9a768e9cce07628'),
  ('en.sahih', 56, 81, 5060, 'Then is it to this statement that you are indifferent', NULL, NULL, '7156a8c0020ef34deadf70dab88c1b0d639a602a7d4c57442649be8d7d8495ae'),
  ('en.sahih', 56, 82, 5061, 'And make [the thanks for] your provision that you deny [the Provider]?', NULL, NULL, '01e25733abc65424cc4217accc6f231bd472e15f002c84f686d026038e870904'),
  ('en.sahih', 56, 83, 5062, 'Then why, when the soul at death reaches the throat', NULL, NULL, 'c1adb348702d0bd1388df1be6342ca6b74d0a0d9e15e379dd566914e099ffb23'),
  ('en.sahih', 56, 84, 5063, 'And you are at that time looking on -', NULL, NULL, 'a1ddd18465d0c8190e1001e9a249ca7098c22f6883acb2f0947735ef85acf798'),
  ('en.sahih', 56, 85, 5064, 'And Our angels are nearer to him than you, but you do not see -', NULL, NULL, 'f5e10ae4a9d0240cd4d28f176a556114b60d89a1efb0217fa3ee8b56233c6b41'),
  ('en.sahih', 56, 86, 5065, 'Then why do you not, if you are not to be recompensed,', NULL, NULL, '828f5a7a079e3bdc1ce2199f9a20724063c37275e125537a55feb758a784dc97'),
  ('en.sahih', 56, 87, 5066, 'Bring it back, if you should be truthful?', NULL, NULL, '8359f082c5b3bc85922881ddb7801ac92704af0b9535a22944f74d6e814b8b1a'),
  ('en.sahih', 56, 88, 5067, 'And if the deceased was of those brought near to Allah,', NULL, NULL, '3eeef55e93dbe4c2c2da1b8e244ff4f4bea2081ead4cccca37f0662365009a54'),
  ('en.sahih', 56, 89, 5068, 'Then [for him is] rest and bounty and a garden of pleasure.', NULL, NULL, '10e45bc2d53a5762a2e6003a6770345d4c25f1196d010512133d522b55a36376'),
  ('en.sahih', 56, 90, 5069, 'And if he was of the companions of the right,', NULL, NULL, 'c7f4e9d3ea075d5ffadbcbe2d52bc1dd5223be2791b8b2bcdc22be8e690f50aa'),
  ('en.sahih', 56, 91, 5070, 'Then [the angels will say], "Peace for you; [you are] from the companions of the right."', NULL, NULL, 'a47720da4aa7385c948e89a02f2df62181eadbbd894807c780b817a259e9a512'),
  ('en.sahih', 56, 92, 5071, 'But if he was of the deniers [who were] astray,', NULL, NULL, '9f71a1b75e2184ae37ab69f2feb3892ff24e807a1414cc7235e1ce76560e11a3'),
  ('en.sahih', 56, 93, 5072, 'Then [for him is] accommodation of scalding water', NULL, NULL, '753a464b36230f060975f19681f41424bc384b5466659c99d66381f194ebda83'),
  ('en.sahih', 56, 94, 5073, 'And burning in Hellfire', NULL, NULL, '7d4a60981ccb7a6a4ea734a0a95e1cccc003ba174bbe6de12bd4e472c2142e2c'),
  ('en.sahih', 56, 95, 5074, 'Indeed, this is the true certainty,', NULL, NULL, '5b44b0e3ea15e0e96336f763fb0a8f65ec7aa7370317a3925aaa51a4ba3f9cb4'),
  ('en.sahih', 56, 96, 5075, 'So exalt the name of your Lord, the Most Great.', NULL, NULL, '08981e024909026d286f8f09888619fdfb6d8af9fa59c685d1acc0c484cfced6'),
  ('en.sahih', 57, 1, 5076, 'Whatever is in the heavens and earth exalts Allah, and He is the Exalted in Might, the Wise.', NULL, NULL, 'd0f23543dfd7d725fb4bb954ac64be24c735b9805d604a6b83130adc0da9749c'),
  ('en.sahih', 57, 2, 5077, 'His is the dominion of the heavens and earth. He gives life and causes death, and He is over all things competent.', NULL, NULL, 'acaa52d75de3622dbdbce80b106dfa017e227da9896b46635f628405451389bb'),
  ('en.sahih', 57, 3, 5078, 'He is the First and the Last, the Ascendant and the Intimate, and He is, of all things, Knowing.', NULL, NULL, '06548cbc6d1d42c091d86ad6d5ae234c5d47b265fba391fa1e4561f149af73e2'),
  ('en.sahih', 57, 4, 5079, 'It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allah, of what you do, is Seeing.', NULL, NULL, 'c11d2cbc4f6ad4fdce790eb0706cfefc3a5b71b264cfc507dde376d50daaf569'),
  ('en.sahih', 57, 5, 5080, 'His is the dominion of the heavens and earth. And to Allah are returned [all] matters.', NULL, NULL, '970a5274b9851f5d5d467f2f76b1cfd6eabb8bda537807df20dd25d7841e67c3'),
  ('en.sahih', 57, 6, 5081, 'He causes the night to enter the day and causes the day to enter the night, and he is Knowing of that within the breasts.', NULL, NULL, '4ce20091f850b0d22eb3bd6f4cfa824dfa0c9747bc0b52d4e0363205070bcd58'),
  ('en.sahih', 57, 7, 5082, 'Believe in Allah and His Messenger and spend out of that in which He has made you successors. For those who have believed among you and spent, there will be a great reward.', NULL, NULL, 'bd1b4bbde065063777f7ac57375fde946c9768a70d669a50a87f3ede631dfc01'),
  ('en.sahih', 57, 8, 5083, 'And why do you not believe in Allah while the Messenger invites you to believe in your Lord and He has taken your covenant, if you should [truly] be believers?', NULL, NULL, 'd624fb6ee299791445486a9956ee6206095d9375afe23c5ac69cd1ef3217157c'),
  ('en.sahih', 57, 9, 5084, 'It is He who sends down upon His Servant [Muhammad] verses of clear evidence that He may bring you out from darknesses into the light. And indeed, Allah is to you Kind and Merciful.', NULL, NULL, '167dd961ca60ae14c5f4273d4b58dc7eb95d2f54273b399d7de67dbd8002a849'),
  ('en.sahih', 57, 10, 5085, 'And why do you not spend in the cause of Allah while to Allah belongs the heritage of the heavens and the earth? Not equal among you are those who spent before the conquest [of Makkah] and fought [and those who did so after it]. Those are greater in degree than they who spent afterwards and fought. But to all Allah has promised the best [reward]. And Allah, with what you do, is Acquainted.', NULL, NULL, '8f5882714ee1be0b4f6e9ea8672ae2b009227975cb387f2dbcdfc7a7215cb1c2'),
  ('en.sahih', 57, 11, 5086, 'Who is it that would loan Allah a goodly loan so He will multiply it for him and he will have a noble reward?', NULL, NULL, '0246002fad298615e80dfcc2a3bc213a7c225bde8565b55afef7b99a9c6dd9bf'),
  ('en.sahih', 57, 12, 5087, 'On the Day you see the believing men and believing women, their light proceeding before them and on their right, [it will be said], "Your good tidings today are [of] gardens beneath which rivers flow, wherein you will abide eternally." That is what is the great attainment.', NULL, NULL, '43171b1e447cbd9d6cca253316d0f8ce9f3c729ff32232b9036952cc7072e3c1'),
  ('en.sahih', 57, 13, 5088, 'On the [same] Day the hypocrite men and hypocrite women will say to those who believed, "Wait for us that we may acquire some of your light." It will be said, "Go back behind you and seek light." And a wall will be placed between them with a door, its interior containing mercy, but on the outside of it is torment.', NULL, NULL, 'bc071772dbbda96fbcb095c1a9859dc44fb62e2f278ff6dd7b80783320117bd9'),
  ('en.sahih', 57, 14, 5089, 'The hypocrites will call to the believers, "Were we not with you?" They will say, "Yes, but you afflicted yourselves and awaited [misfortune for us] and doubted, and wishful thinking deluded you until there came the command of Allah. And the Deceiver deceived you concerning Allah.', NULL, NULL, '2c082eafbfe5f2f141260f85712a253c4075cdd5cfee453bb88dcdfa88c0aa6e'),
  ('en.sahih', 57, 15, 5090, 'So today no ransom will be taken from you or from those who disbelieved. Your refuge is the Fire. It is most worthy of you, and wretched is the destination.', NULL, NULL, 'ebaba8b40bc1278ba5197ea2c08f192afd79dfa9dfb549f658bcc3f8adfb157d'),
  ('en.sahih', 57, 16, 5091, 'Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allah and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient.', NULL, NULL, '1029dd5079af971300c5f7287a58b63de56d46dd269223ce8126ce507f377616'),
  ('en.sahih', 57, 17, 5092, 'Know that Allah gives life to the earth after its lifelessness. We have made clear to you the signs; perhaps you will understand.', NULL, NULL, '78cc0098057e4e4d2d05a103b0b90a1f61e654f64b4c1ae025704abbfe1f4cab'),
  ('en.sahih', 57, 18, 5093, 'Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allah a goodly loan - it will be multiplied for them, and they will have a noble reward.', NULL, NULL, '0caad06a12a899646b5953418be71d8024227229d1a3f83a088b0330121e401a'),
  ('en.sahih', 57, 19, 5094, 'And those who have believed in Allah and His messengers - those are [in the ranks of] the supporters of truth and the martyrs, with their Lord. For them is their reward and their light. But those who have disbelieved and denied Our verses - those are the companions of Hellfire.', NULL, NULL, '6f49a0c01f67dcb9bffd74ae42b9c4dec103929b5dddabc66d1e351f37351028'),
  ('en.sahih', 57, 20, 5095, 'Know that the life of this world is but amusement and diversion and adornment and boasting to one another and competition in increase of wealth and children - like the example of a rain whose [resulting] plant growth pleases the tillers; then it dries and you see it turned yellow; then it becomes [scattered] debris. And in the Hereafter is severe punishment and forgiveness from Allah and approval. And what is the worldly life except the enjoyment of delusion.', NULL, NULL, '97fd6859f5c17d5e1092af5063da7a62bf068d5e02a180f12db7178764bc9627'),
  ('en.sahih', 57, 21, 5096, 'Race toward forgiveness from your Lord and a Garden whose width is like the width of the heavens and earth, prepared for those who believed in Allah and His messengers. That is the bounty of Allah which He gives to whom He wills, and Allah is the possessor of great bounty.', NULL, NULL, 'b16ef8a993043d5a68845dbe810ea4e232e80f558459d1445268e1dca50590f2'),
  ('en.sahih', 57, 22, 5097, 'No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy -', NULL, NULL, 'a0214c4a07cede5fbe266b0b0001b96da53776b8e646b0db6cde82f865c435ec'),
  ('en.sahih', 57, 23, 5098, 'In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful -', NULL, NULL, '92ddc34c2d10da22dc0e77c28c31e6570e6b9947027f3e905c7f94670fd906f4'),
  ('en.sahih', 57, 24, 5099, '[Those] who are stingy and enjoin upon people stinginess. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.', NULL, NULL, 'b09be4de3286137dd19e9279d30248caebff8f1df44a0d8b21b9ea398da3864e'),
  ('en.sahih', 57, 25, 5100, 'We have already sent Our messengers with clear evidences and sent down with them the Scripture and the balance that the people may maintain [their affairs] in justice. And We sent down iron, wherein is great military might and benefits for the people, and so that Allah may make evident those who support Him and His messengers unseen. Indeed, Allah is Powerful and Exalted in Might.', NULL, NULL, 'cd9366370148c3253db566a160a6ebf4184761e5e3631fdaaca4a5b5849c73f6')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 57, 26, 5101, 'And We have already sent Noah and Abraham and placed in their descendants prophethood and scripture; and among them is he who is guided, but many of them are defiantly disobedient.', NULL, NULL, '06395e0f7f97c5d755a3f417d62d24d844ef4ecf133c619acaa46a32e318e303'),
  ('en.sahih', 57, 27, 5102, 'Then We sent following their footsteps Our messengers and followed [them] with Jesus, the son of Mary, and gave him the Gospel. And We placed in the hearts of those who followed him compassion and mercy and monasticism, which they innovated; We did not prescribe it for them except [that they did so] seeking the approval of Allah. But they did not observe it with due observance. So We gave the ones who believed among them their reward, but many of them are defiantly disobedient.', NULL, NULL, '592c31775d9ea57f3ecfc6d7e3ff1ba160140898ffc168f64a72e88b52e08c11'),
  ('en.sahih', 57, 28, 5103, 'O you who have believed, fear Allah and believe in His Messenger; He will [then] give you a double portion of His mercy and make for you a light by which you will walk and forgive you; and Allah is Forgiving and Merciful.', NULL, NULL, '338db20a6b117f93ab9cdcefdc52534328720c6b2b10ebf5328e0bf11ed17360'),
  ('en.sahih', 57, 29, 5104, '[This is] so that the People of the Scripture may know that they are not able [to obtain] anything from the bounty of Allah and that [all] bounty is in the hand of Allah; He gives it to whom He wills. And Allah is the possessor of great bounty.', NULL, NULL, '81dfa1371f871b30f70256eb3bebf6c9cf9b72a971ab56138d72048fef95f15a'),
  ('en.sahih', 58, 1, 5105, 'Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing.', NULL, NULL, 'fe1b860c15791d24ccae547be0aca3b68e30266f7ef22d5d6cd3698f55af9237'),
  ('en.sahih', 58, 2, 5106, 'Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving.', NULL, NULL, '158b1e87a0f6a4d0031f2bf9d8dcc7cbc19cb50f5a14af4076a4300107e3d283'),
  ('en.sahih', 58, 3, 5107, 'And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do.', NULL, NULL, '814978432aa0c70e591e36170fded5f4d3a7600e775bcb36e3b5dd060c472da7'),
  ('en.sahih', 58, 4, 5108, 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment.', NULL, NULL, 'c05b9c2d917a0550d48ee56cedb57f1e701f61367b607e322c24ef937c3ae0fc'),
  ('en.sahih', 58, 5, 5109, 'Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment.', NULL, NULL, 'd4b0249e81a3e408b03d9be9f836065564e15b33d4f45a47b88f147da19a5d23'),
  ('en.sahih', 58, 6, 5110, 'On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness.', NULL, NULL, '6dbc58962d90df6050b1ab27e45070f9031a8442afe5c4ee3e0c6b513f08c2d3'),
  ('en.sahih', 58, 7, 5111, 'Have you not considered that Allah knows what is in the heavens and what is on the earth? There is in no private conversation three but that He is the fourth of them, nor are there five but that He is the sixth of them - and no less than that and no more except that He is with them [in knowledge] wherever they are. Then He will inform them of what they did, on the Day of Resurrection. Indeed Allah is, of all things, Knowing.', NULL, NULL, '5bd90cbc7929b1b56c9bcec6d9a039a6b968dd2770a4ea66e2373c599f945ca9'),
  ('en.sahih', 58, 8, 5112, 'Have you not considered those who were forbidden from private conversation, then they return to that which they were forbidden and converse among themselves about sin and aggression and disobedience to the Messenger? And when they come to you, they greet you with that [word] by which Allah does not greet you and say among themselves, "Why does Allah not punish us for what we say?" Sufficient for them is Hell, which they will [enter to] burn, and wretched is the destination.', NULL, NULL, 'd523a600cd3ac4713822104e26d037993ae79c7655c9d7ab4765ebd417eae3fd'),
  ('en.sahih', 58, 9, 5113, 'O you who have believed, when you converse privately, do not converse about sin and aggression and disobedience to the Messenger but converse about righteousness and piety. And fear Allah, to whom you will be gathered.', NULL, NULL, '296956665713f45a6015a2d1b1f23a966b3c071948a04e569ecb36632bc4e783'),
  ('en.sahih', 58, 10, 5114, 'Private conversation is only from Satan that he may grieve those who have believed, but he will not harm them at all except by permission of Allah. And upon Allah let the believers rely.', NULL, NULL, 'a9f7988b18aaccacd55cf679fc51f3c4483fe5fc096ddcce628ac7e9a6ba0466'),
  ('en.sahih', 58, 11, 5115, 'O you who have believed, when you are told, "Space yourselves" in assemblies, then make space; Allah will make space for you. And when you are told, "Arise," then arise; Allah will raise those who have believed among you and those who were given knowledge, by degrees. And Allah is Acquainted with what you do.', NULL, NULL, '97bad52e3e0f1b5376bc3b277b1677d1c06377df648bee1991bdda0365473884'),
  ('en.sahih', 58, 12, 5116, 'O you who have believed, when you [wish to] privately consult the Messenger, present before your consultation a charity. That is better for you and purer. But if you find not [the means] - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, '62a150caeaea48af2b6be1b3b0fb9e2e3982b2870f4e0a3a5fa3d55ea08c7d8b'),
  ('en.sahih', 58, 13, 5117, 'Have you feared to present before your consultation charities? Then when you do not and Allah has forgiven you, then [at least] establish prayer and give zakah and obey Allah and His Messenger. And Allah is Acquainted with what you do.', NULL, NULL, '8094f90f8b3a98a9bcba26c91b7a46143c400c43dfbb0fcd093ae3c1668f0817'),
  ('en.sahih', 58, 14, 5118, 'Have you not considered those who make allies of a people with whom Allah has become angry? They are neither of you nor of them, and they swear to untruth while they know [they are lying].', NULL, NULL, '68860c286ab70c64ce49c54719647eb55de3ed2e77d270217dfde1275a20056c'),
  ('en.sahih', 58, 15, 5119, 'Allah has prepared for them a severe punishment. Indeed, it was evil that they were doing.', NULL, NULL, '97cd0ebbe447380afe77da2b3e9308ac860e4ec18c899aeb2e597378c8134016'),
  ('en.sahih', 58, 16, 5120, 'They took their [false] oaths as a cover, so they averted [people] from the way of Allah, and for them is a humiliating punishment.', NULL, NULL, '95bfb7a85f56a655aa173ecc34c7a587891a8b4c1d067811e630d5385fbebf1d'),
  ('en.sahih', 58, 17, 5121, 'Never will their wealth or their children avail them against Allah at all. Those are the companions of the Fire; they will abide therein eternally', NULL, NULL, 'b9ec7624f8c6c43238570cf6992d7f7bb33c6ba2e2b53c31f3a448847d417996'),
  ('en.sahih', 58, 18, 5122, 'On the Day Allah will resurrect them all, and they will swear to Him as they swear to you and think that they are [standing] on something. Unquestionably, it is they who are the liars.', NULL, NULL, '4e3d8d752f4bb717fc063c03b941cd875a299a22335d0a681732a452c95f684b'),
  ('en.sahih', 58, 19, 5123, 'Satan has overcome them and made them forget the remembrance of Allah. Those are the party of Satan. Unquestionably, the party of Satan - they will be the losers.', NULL, NULL, 'c2db67339ec0c5a49eba9061edc2ea0120111ed1160069969e81bee47a0a29be'),
  ('en.sahih', 58, 20, 5124, 'Indeed, the ones who oppose Allah and His Messenger - those will be among the most humbled.', NULL, NULL, '45c76d3c6278363f742ac2af80c02bbf51d57bfdd3aff5dea6e64e6af74d1bc5'),
  ('en.sahih', 58, 21, 5125, 'Allah has written, "I will surely overcome, I and My messengers." Indeed, Allah is Powerful and Exalted in Might.', NULL, NULL, '0a788244187cb750190bb8079c965cb677adb61ae17e917542c5f5c790a382f2'),
  ('en.sahih', 58, 22, 5126, 'You will not find a people who believe in Allah and the Last Day having affection for those who oppose Allah and His Messenger, even if they were their fathers or their sons or their brothers or their kindred. Those - He has decreed within their hearts faith and supported them with spirit from Him. And We will admit them to gardens beneath which rivers flow, wherein they abide eternally. Allah is pleased with them, and they are pleased with Him - those are the party of Allah. Unquestionably, the party of Allah - they are the successful.', NULL, NULL, 'd9015bd7d45c3ee2b844dd9bc8de2f95fac5fdcdd14e8f9afc7c8b51d9fc1e87'),
  ('en.sahih', 59, 1, 5127, 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', NULL, NULL, 'b81bb3f05895f9c6c010cd42f720b968a5accf40a7639667d57e0ee0dce1b968'),
  ('en.sahih', 59, 2, 5128, 'It is He who expelled the ones who disbelieved among the People of the Scripture from their homes at the first gathering. You did not think they would leave, and they thought that their fortresses would protect them from Allah; but [the decree of] Allah came upon them from where they had not expected, and He cast terror into their hearts [so] they destroyed their houses by their [own] hands and the hands of the believers. So take warning, O people of vision.', NULL, NULL, '86fc8675248a915b049e5c370add93358a16490e002d8ab59a9cf15db9b21275'),
  ('en.sahih', 59, 3, 5129, 'And if not that Allah had decreed for them evacuation, He would have punished them in [this] world, and for them in the Hereafter is the punishment of the Fire.', NULL, NULL, '32bd5eb044c0b95b9533cb3282ce7b496f594988efd5799daf02d525935bb3bb'),
  ('en.sahih', 59, 4, 5130, 'That is because they opposed Allah and His Messenger. And whoever opposes Allah - then indeed, Allah is severe in penalty.', NULL, NULL, 'c0262b7936b8264e7c5d1deab82b2dcff1e6b1899940d0c1126415725276a6ea'),
  ('en.sahih', 59, 5, 5131, 'Whatever you have cut down of [their] palm trees or left standing on their trunks - it was by permission of Allah and so He would disgrace the defiantly disobedient.', NULL, NULL, 'f8e797a7d7f656147a40f3a396c91564c3ec82948338edef30c311fa63cf52f2'),
  ('en.sahih', 59, 6, 5132, 'And what Allah restored [of property] to His Messenger from them - you did not spur for it [in an expedition] any horses or camels, but Allah gives His messengers power over whom He wills, and Allah is over all things competent.', NULL, NULL, '11c1090851584147fc46711e95c2a2ca9c1ea2c990af4e7e4419e6464d4a2ebf'),
  ('en.sahih', 59, 7, 5133, 'And what Allah restored to His Messenger from the people of the towns - it is for Allah and for the Messenger and for [his] near relatives and orphans and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allah; indeed, Allah is severe in penalty.', NULL, NULL, 'd6b9b34c2b263fc8d4840d163f10fc480bf32a43f3b182fd087af5f973092090'),
  ('en.sahih', 59, 8, 5134, 'For the poor emigrants who were expelled from their homes and their properties, seeking bounty from Allah and [His] approval and supporting Allah and His Messenger, [there is also a share]. Those are the truthful.', NULL, NULL, '259d7ccc08eeed01319915df7608bb8620a1840f47c2828b4805f87b184d08e2'),
  ('en.sahih', 59, 9, 5135, 'And [also for] those who were settled in al-Madinah and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what the emigrants were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', NULL, NULL, 'e623f5d667d9139b3114a8e3a40902afa4e32cc7dd9f24082784b2f889142351'),
  ('en.sahih', 59, 10, 5136, 'And [there is a share for] those who came after them, saying, "Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."', NULL, NULL, '3b0599fd870983efadcfd541972397e68091bf2ba983d8dd824f009b0b5ab5af'),
  ('en.sahih', 59, 11, 5137, 'Have you not considered those who practice hypocrisy, saying to their brothers who have disbelieved among the People of the Scripture, "If you are expelled, we will surely leave with you, and we will not obey, in regard to you, anyone - ever; and if you are fought, we will surely aid you." But Allah testifies that they are liars.', NULL, NULL, 'b40ea78d498a31456c04e178ee33205e327b2972f3a1a2f18a01bb3c81d884dd'),
  ('en.sahih', 59, 12, 5138, 'If they are expelled, they will not leave with them, and if they are fought, they will not aid them. And [even] if they should aid them, they will surely turn their backs; then [thereafter] they will not be aided.', NULL, NULL, 'cdf1a9ce8c1b7bbd8fb66b166ea97d5b123709cb759febdbc81c93236c2a978f'),
  ('en.sahih', 59, 13, 5139, 'You [believers] are more fearful within their breasts than Allah. That is because they are a people who do not understand.', NULL, NULL, '16325b45e2bcb0c9296f8a7f53490aae92fd6acbd4f963cdd0e71f68fbc4ba81'),
  ('en.sahih', 59, 14, 5140, 'They will not fight you all except within fortified cities or from behind walls. Their violence among themselves is severe. You think they are together, but their hearts are diverse. That is because they are a people who do not reason.', NULL, NULL, '7ad5b4ccc20c1b6a2cf5057770ea940f7da11560963b84c6e6abbb9ed360a1a4'),
  ('en.sahih', 59, 15, 5141, '[Theirs is] like the example of those shortly before them: they tasted the bad consequence of their affair, and they will have a painful punishment.', NULL, NULL, '352b415da57460790d0edd8172c1f6be0c935ac18478deba7c4c3a8fe30cddc0'),
  ('en.sahih', 59, 16, 5142, '[The hypocrites are] like the example of Satan when he says to man, "Disbelieve." But when he disbelieves, he says, "Indeed, I am disassociated from you. Indeed, I fear Allah, Lord of the worlds."', NULL, NULL, '4d56c49b60417cd05606fcd93377948cbc658c89ad7f4624e2d52cabec67cdb0'),
  ('en.sahih', 59, 17, 5143, 'So the outcome for both of them is that they will be in the Fire, abiding eternally therein. And that is the recompense of the wrong-doers.', NULL, NULL, '95423a4f3b7e9801112feb0b67d5f0c725a3699f25b45f3400e0ae6e3fea17d4'),
  ('en.sahih', 59, 18, 5144, 'O you who have believed, fear Allah. And let every soul look to what it has put forth for tomorrow - and fear Allah. Indeed, Allah is Acquainted with what you do.', NULL, NULL, '50fd2a719606a5ae1314223edc943cb6bcc3174a4dbf24dbdf01bb4ea55e6608'),
  ('en.sahih', 59, 19, 5145, 'And be not like those who forgot Allah, so He made them forget themselves. Those are the defiantly disobedient.', NULL, NULL, 'd7af9ff5c04d94827d3740b64a9e6bb6c605245c5092bec917ede49ead8adc40'),
  ('en.sahih', 59, 20, 5146, 'Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success].', NULL, NULL, 'e5d013f01bcb9662420f9254f4c863f9a9a7424d34b1e2dbe3483601d92b0b2d'),
  ('en.sahih', 59, 21, 5147, 'If We had sent down this Qur''an upon a mountain, you would have seen it humbled and coming apart from fear of Allah. And these examples We present to the people that perhaps they will give thought.', NULL, NULL, '49f79b4e219a07b35de8fcde4d1925103d812f169499a2c1a41aa61043963356'),
  ('en.sahih', 59, 22, 5148, 'He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful.', NULL, NULL, 'd4db674dab7edab22ef8893310e942e75abc8dfdd1b28cfb56bf76eee96214ae'),
  ('en.sahih', 59, 23, 5149, 'He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him.', NULL, NULL, '07f3170ac7115186e6484dfaffe7a605a0966efe9c26956420c69c01e95a8262'),
  ('en.sahih', 59, 24, 5150, 'He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise.', NULL, NULL, '7dd8976849720b16ba6da8e9ab86f6c1f33a0d493bef2291eae841406455b364'),
  ('en.sahih', 60, 1, 5151, 'O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allah, your Lord. If you have come out for jihad in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection, but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way.', NULL, NULL, '78bacea3d48e8c79d6d4d6960fa8bfce726302271ed9b7a3687fe99f72e737c8'),
  ('en.sahih', 60, 2, 5152, 'If they gain dominance over you, they would be to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve.', NULL, NULL, '98d68ddea3a60cfef747cb35609357ee926e65e784df823a25494b7ea391f7c8'),
  ('en.sahih', 60, 3, 5153, 'Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allah, of what you do, is Seeing.', NULL, NULL, '37df04b5eb65b617cbdfa091e111617c7b68895fdcb967a973de43202d008220'),
  ('en.sahih', 60, 4, 5154, 'There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, "Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone" except for the saying of Abraham to his father, "I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination.', NULL, NULL, '6867e808beb244a507e2388ad801b162bd1f03bd861b211305da1343e2d61c0c'),
  ('en.sahih', 60, 5, 5155, 'Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."', NULL, NULL, '56a37556df432cca82549a8287b8767502d463f7addd0efc29d82dbb23419dfa'),
  ('en.sahih', 60, 6, 5156, 'There has certainly been for you in them an excellent pattern for anyone whose hope is in Allah and the Last Day. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.', NULL, NULL, '27f0d01c3ad593a2068c156bbe4175baca27a4ab821319adfbeb9dd7baf99150'),
  ('en.sahih', 60, 7, 5157, 'Perhaps Allah will put, between you and those to whom you have been enemies among them, affection. And Allah is competent, and Allah is Forgiving and Merciful.', NULL, NULL, 'bf88cadc42642aed38f80ef6624ee9b809719170c0c631aa61d9a2d66999ca45'),
  ('en.sahih', 60, 8, 5158, 'Allah does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allah loves those who act justly.', NULL, NULL, '7cdb4bde822e85c14590d5103f12e3540d6ec1628e40072db9553491aba575da'),
  ('en.sahih', 60, 9, 5159, 'Allah only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers.', NULL, NULL, 'd9da8da83ef3e2f9f588209290ab36f77ed0eeb8da9031530354bb4af925c1c6'),
  ('en.sahih', 60, 10, 5160, 'O you who have believed, when the believing women come to you as emigrants, examine them. Allah is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give the disbelievers what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them ask for what they have spent. That is the judgement of Allah; He judges between you. And Allah is Knowing and Wise.', NULL, NULL, '19180e93c26167577ca921bfb550cc2547fac0a5a412a6524932100c4ddefae9'),
  ('en.sahih', 60, 11, 5161, 'And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allah, in whom you are believers.', NULL, NULL, '86535bdb67c39b282ae0a641e27caf0b55ea2d86c88b05c28ca3aad9d336ad56'),
  ('en.sahih', 60, 12, 5162, 'O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allah, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, '22b1f131427a70a7c8f4fc26e79989fe3ce68a517c8284e3eb667d6961291d7d'),
  ('en.sahih', 60, 13, 5163, 'O you who have believed, do not make allies of a people with whom Allah has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the inhabitants of the graves.', NULL, NULL, '2f5cd1c50e4220e4a8232c80987890391a5b19a43cb67b4169f907e5c14c5ada'),
  ('en.sahih', 61, 1, 5164, 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.', NULL, NULL, 'b81bb3f05895f9c6c010cd42f720b968a5accf40a7639667d57e0ee0dce1b968'),
  ('en.sahih', 61, 2, 5165, 'O you who have believed, why do you say what you do not do?', NULL, NULL, '7c5146a93072a27d93245e7fef24518885629fd3edc1386f4b5e2ba9e258725a'),
  ('en.sahih', 61, 3, 5166, 'Great is hatred in the sight of Allah that you say what you do not do.', NULL, NULL, '25dcb4a53196f17176eaed6a9ba6a894bfcc386ec8e582006b8567ebae3d6865'),
  ('en.sahih', 61, 4, 5167, 'Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly.', NULL, NULL, 'e9df9d8a30f28310adbb2403357c7cbf4b5b4fc13aee4cc855dd3ebfcec48569'),
  ('en.sahih', 61, 5, 5168, 'And [mention, O Muhammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people.', NULL, NULL, '2e1e8ed9a9b8b3c859ad0c511ffaaa61e2b43601de1914573ee06a2adaca07e6'),
  ('en.sahih', 61, 6, 5169, 'And [mention] when Jesus, the son of Mary, said, "O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad." But when he came to them with clear evidences, they said, "This is obvious magic."', NULL, NULL, '54b438f2d4f831daeada79918f7cf9d11dbaee983ec0ca54966068fc7c664c31'),
  ('en.sahih', 61, 7, 5170, 'And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people.', NULL, NULL, '5d34196ac89c6b34b07dfad7253e45db4df935bf24cc424d75cca982ddd70b58'),
  ('en.sahih', 61, 8, 5171, 'They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.', NULL, NULL, '13e69e20298d5aa78dd56d778f216ff0d7368d8169c3c37f46b44402ec41f45e'),
  ('en.sahih', 61, 9, 5172, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it.', NULL, NULL, '5c378075e192d1a7f033f3f1c53bdfe5e1c5b052810af26f6d9f90878d60d7fb'),
  ('en.sahih', 61, 10, 5173, 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?', NULL, NULL, '2f6331351bfc2a45db7a4e2a2fe7c0b5c88e68c21441bc77df39659e8998c6d6'),
  ('en.sahih', 61, 11, 5174, '[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know.', NULL, NULL, '94ff7fed2bf142a406a4c06edb4b500b1bfcccc08f83e78e98a7faa659debeed'),
  ('en.sahih', 61, 12, 5175, 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.', NULL, NULL, 'efa28a12d7f25f8cb3e37b756d9c365e13995e54a4b72fd928415eab53267108'),
  ('en.sahih', 61, 13, 5176, 'And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.', NULL, NULL, 'b6e392b2efb6c82057209cecbec79d8186c5977f3bf5fe4ede0d5c0ec5a49e1d'),
  ('en.sahih', 61, 14, 5177, 'O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allah?" The disciples said, "We are supporters of Allah." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.', NULL, NULL, 'd50a8a3bf525ae861eb9b68647d6f3fc1d342be9e19e412f6dbaaa34d098b41b'),
  ('en.sahih', 62, 1, 5178, 'Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise.', NULL, NULL, '2c3f2c0e5f8f053ff4948e3cd4d506d2b526ee78af574a9842d8d964804a5b7c'),
  ('en.sahih', 62, 2, 5179, 'It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -', NULL, NULL, 'ce8fc8f97c9e8b595f492f93d3d5a8bfb55fc2e6228fc02eec4aa8378db0ea3d'),
  ('en.sahih', 62, 3, 5180, 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.', NULL, NULL, '1b1705cc2b628baea7165484eca6a3e95eba59690386a0046daccc558b17406c'),
  ('en.sahih', 62, 4, 5181, 'That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty.', NULL, NULL, '138f3578c1d5dfaafb8aea2af0e8c75403bc0fcd38334ec82a595a3550e8ec53'),
  ('en.sahih', 62, 5, 5182, 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.', NULL, NULL, '9f84889d0a51970d1b1c35354a28bc57758880c29a4132a24adcf8e5d049f0a8'),
  ('en.sahih', 62, 6, 5183, 'Say, "O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful."', NULL, NULL, 'aaa40072e02d6cd8a7876fbe936ab5475be222c40ee30fd4f9453042f5d06202'),
  ('en.sahih', 62, 7, 5184, 'But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.', NULL, NULL, '2c752d6eb9c14c1a47021f57fc70636c0670c981ddaf0ad4ea6b1d04ca333b59'),
  ('en.sahih', 62, 8, 5185, 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."', NULL, NULL, '916914d7e0efc34de2e828bd34231c4a045e4e00bd773924186363f3a24f77e6'),
  ('en.sahih', 62, 9, 5186, 'O you who have believed, when [the adhan] is called for the prayer on the day of Jumu''ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.', NULL, NULL, '1dcc2acddebfc23e53af1b0c92b283f4f1fcd2ac901e4fe4a5e9a7df68431885'),
  ('en.sahih', 62, 10, 5187, 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed.', NULL, NULL, '3a1625661207eb65a3c93d9a9c6a65a3b2667b074281bead478e696010c43699'),
  ('en.sahih', 62, 11, 5188, 'But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, "What is with Allah is better than diversion and than a transaction, and Allah is the best of providers."', NULL, NULL, '64984224a48bdb188bd982863fb887d2fe3be8702b76d2f0558331c0e497d146'),
  ('en.sahih', 63, 1, 5189, 'When the hypocrites come to you, [O Muhammad], they say, "We testify that you are the Messenger of Allah." And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars.', NULL, NULL, '02a508acc292e500af7ce1ec5eae1a8e335cc6d7b3a95e071b080199ac224020'),
  ('en.sahih', 63, 2, 5190, 'They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.', NULL, NULL, '4b8be0531a577f9d023b58d69ee701380e8cc021931d7149ea8efab6d31a863e'),
  ('en.sahih', 63, 3, 5191, 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.', NULL, NULL, '315189e40be5fee70d7f5f8667305bfab4d6123d52c10d08a3eeba22f0573dae'),
  ('en.sahih', 63, 4, 5192, 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?', NULL, NULL, '1523e8265a2d67aafab81f518a31973e6f7c748e1d435bb02cdc0439ba8cb422'),
  ('en.sahih', 63, 5, 5193, 'And when it is said to them, "Come, the Messenger of Allah will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.', NULL, NULL, 'd7c634b0dd78d045fcfff91d1a6ddbf15264b163eb48871fd9f4c19a90b675af'),
  ('en.sahih', 63, 6, 5194, 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people.', NULL, NULL, 'b6e099fa3e61c121c4b424822358e57d5dd008aa1503744bdc27eb4ac0c1e530'),
  ('en.sahih', 63, 7, 5195, 'They are the ones who say, "Do not spend on those who are with the Messenger of Allah until they disband." And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand.', NULL, NULL, '13db9f1cfd0a235300af96e7ca2f8c5836e20be5c98794099809c9b21cb614d7'),
  ('en.sahih', 63, 8, 5196, 'They say, "If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble." And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.', NULL, NULL, '7a10f865fd850fe1b9670bbd2bd620f6b9b5818eda769114cc1edeb907b2ad72'),
  ('en.sahih', 63, 9, 5197, 'O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers.', NULL, NULL, '20844c6b721bc2f0a0764f27b22643705095c3d4b95bac04bb98a68d5b122d5b'),
  ('en.sahih', 63, 10, 5198, 'And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous."', NULL, NULL, 'f620d881c9128a5d9d0175ff5ff9bcee0e1e423e996879a50db918fb6cdcd7d2'),
  ('en.sahih', 63, 11, 5199, 'But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do.', NULL, NULL, '8003a702ae39bbcb830af62eacd18e6321e96de754f37bf289cc9eb89a8aedbb'),
  ('en.sahih', 64, 1, 5200, 'Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.', NULL, NULL, 'fb752d1a73a4cfbc9f401ef5dbfab70f916494b0e12a5b2eacaf6e2295b5fbf1')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 64, 2, 5201, 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing.', NULL, NULL, '9b8e377fdf3125922987deef12f98cc95f7c8671d2a5ad03ace26b516ab16941'),
  ('en.sahih', 64, 3, 5202, 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.', NULL, NULL, 'd00dcc1291d39b971a78092d437044b5d58d88f6dd11902e17cb959dac214e8e'),
  ('en.sahih', 64, 4, 5203, 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts.', NULL, NULL, '6fe84ad2728d8a518d14440bcba234aaf2e3f0f4698127bca214358763d07dc1'),
  ('en.sahih', 64, 5, 5204, 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.', NULL, NULL, '7766a0b293b2f39fe4b2e73a3c90f95663ec95305aa44fa62600001bfd094fd7'),
  ('en.sahih', 64, 6, 5205, 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy.', NULL, NULL, '41f11d1f211778d6badb3e30a9045cc4fa8f36fd8331c27b1b3ca63f1f6caa77'),
  ('en.sahih', 64, 7, 5206, 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy."', NULL, NULL, '613f4e1603ca5869c4aa5afcaed20fa7e685ab79d55116447ad8393d47dcc2d2'),
  ('en.sahih', 64, 8, 5207, 'So believe in Allah and His Messenger and the Qur''an which We have sent down. And Allah is Acquainted with what you do.', NULL, NULL, '98e0db2cb17b10268214344a82f795cc84c7975fcb5e74ce45ba064b85aeed7b'),
  ('en.sahih', 64, 9, 5208, 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.', NULL, NULL, '935b6c8f22c0232d78c2c7899c5cd5a5208b6fff655db4b9576efa91db3a0ce7'),
  ('en.sahih', 64, 10, 5209, 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.', NULL, NULL, '63ddc914c70b58619ba928c796c45b76228775320ba8b82f62dfde04c41f2dcc'),
  ('en.sahih', 64, 11, 5210, 'No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things.', NULL, NULL, '6969ccb0a6cc2dd648c9ed2b9252c8c3a3735df4d79889a4ce99a125279b54d8'),
  ('en.sahih', 64, 12, 5211, 'And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.', NULL, NULL, '67c97e1a4b0b57597af9db8baa9b32eebd8d2b9ae9ae7ba854402358a8c1c150'),
  ('en.sahih', 64, 13, 5212, 'Allah - there is no deity except Him. And upon Allah let the believers rely.', NULL, NULL, 'dca1725184a9764bb34fc69ea42236a2a164fb374b2488fa2b7d79d360e5951d'),
  ('en.sahih', 64, 14, 5213, 'O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful.', NULL, NULL, '2513882d8a4d89ee202dfebd330d0f1dfaf7ede0dfa88787eae1a70b95ddd6ad'),
  ('en.sahih', 64, 15, 5214, 'Your wealth and your children are but a trial, and Allah has with Him a great reward.', NULL, NULL, 'ff531c7a0d758f226e09dfffc8053505be18083f52e12f9934aabc8c744b701d'),
  ('en.sahih', 64, 16, 5215, 'So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.', NULL, NULL, '41b8f0b38bb3b6345713c0252483c5560a2f9ea7e3be9010e79bf143588040b2'),
  ('en.sahih', 64, 17, 5216, 'If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.', NULL, NULL, 'a461083725c63d914fb724b4825844b64fdbf3822334deb19e3ed58d9a930e64'),
  ('en.sahih', 64, 18, 5217, 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.', NULL, NULL, '66726567c98a9e9f5c3c9b58f4e33d97ea8b1bb83f664cab8b4c252099b7f620'),
  ('en.sahih', 65, 1, 5218, 'O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allah, your Lord. Do not turn them out of their [husbands''] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allah. And whoever transgresses the limits of Allah has certainly wronged himself. You know not; perhaps Allah will bring about after that a [different] matter.', NULL, NULL, '5b293be74cb088e3058b3a6871a76873264e2bcb62a9a9a0c9626f4853de2a60'),
  ('en.sahih', 65, 2, 5219, 'And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last day. And whoever fears Allah - He will make for him a way out', NULL, NULL, 'c8e4e86d30e2180076e3e70896bfe8c13b568cf28b82e3af4128b412fa4f02ba'),
  ('en.sahih', 65, 3, 5220, 'And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent.', NULL, NULL, '88c15a3520f6a027777e3fc849873452b361fa397ad7bc24b4134def12f5dbd9'),
  ('en.sahih', 65, 4, 5221, 'And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allah - He will make for him of his matter ease.', NULL, NULL, 'fb97448c82c0b5ae1408241508c268ffed7a29af2c610f3549aa576a4258d435'),
  ('en.sahih', 65, 5, 5222, 'That is the command of Allah, which He has sent down to you; and whoever fears Allah - He will remove for him his misdeeds and make great for him his reward.', NULL, NULL, 'c6c916178628bd1364f4ea08e8d98ba9d409c4b40c1dd924dd4f1087d6efc588'),
  ('en.sahih', 65, 6, 5223, 'Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for the father another woman.', NULL, NULL, 'd06bc3125a65fdccbfea0d5c1fc0fde3f335f1a0a4c58a368398baad0137ee51'),
  ('en.sahih', 65, 7, 5224, 'Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allah has given him. Allah does not charge a soul except [according to] what He has given it. Allah will bring about, after hardship, ease.', NULL, NULL, '0e07c67b4bdeec967e18e1229676f817c70c5965a4c58da6801782b943f81868'),
  ('en.sahih', 65, 8, 5225, 'And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment.', NULL, NULL, 'd76e06bbfb6809afc0a4c574acf126612e8b36ffd1ebdf5f987b895258a89603'),
  ('en.sahih', 65, 9, 5226, 'And it tasted the bad consequence of its affair, and the outcome of its affair was loss.', NULL, NULL, 'e80156b1bf8bcf7501f69212ac6a9f648ad2ab59b9e83b52be61d958993ca125'),
  ('en.sahih', 65, 10, 5227, 'Allah has prepared for them a severe punishment; so fear Allah, O you of understanding who have believed. Allah has sent down to you the Qur''an.', NULL, NULL, '8df704c4aa28535cd515c99103a912f1662f0daf421ac6af56e072a3d0abcb18'),
  ('en.sahih', 65, 11, 5228, '[He sent] a Messenger [Muhammad] reciting to you the distinct verses of Allah that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allah and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allah will have perfected for him a provision.', NULL, NULL, '1f4343589eeb444a26b5c432f61aa5bc8a59b8d3f23dbe92f9c25e5be0744051'),
  ('en.sahih', 65, 12, 5229, 'It is Allah who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allah is over all things competent and that Allah has encompassed all things in knowledge.', NULL, NULL, '1039baeb92bddbd33c5dc8400354740a1cb261dd44f40f5cb713e97c09ffbcfc'),
  ('en.sahih', 66, 1, 5230, 'O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful.', NULL, NULL, 'ff8beca90120997037cfe4ffe3a1dbf7eea86e679d45582eeca35a439cb73322'),
  ('en.sahih', 66, 2, 5231, 'Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise.', NULL, NULL, 'dccedc712b751db4e9d26aa103876cf6f7d64ccdbc8fb5e3194442a2a4f0b5d6'),
  ('en.sahih', 66, 3, 5232, 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Acquainted."', NULL, NULL, '8dfde5b8f96c181beef45735aad1d47d190b8ae7c2d2c016127a547b573533d3'),
  ('en.sahih', 66, 4, 5233, 'If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.', NULL, NULL, '3a6a9a947f036486dbb9fbded600824c3a4e86630f19ebbfffc28ef641f12f87'),
  ('en.sahih', 66, 5, 5234, 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.', NULL, NULL, '6a48330d75022c1f356ded41b9845344f8aa799d910e18407f21356b99d6e28f'),
  ('en.sahih', 66, 6, 5235, 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.', NULL, NULL, '739936e60d22ba6b92510d3356aef5b2b40dfcd0f641740b7c78d29eeadcc83e'),
  ('en.sahih', 66, 7, 5236, 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.', NULL, NULL, 'cdef75d06f7ce40feff413abaca0f6cf22e20b617b12e7dee3feb640c12605a9'),
  ('en.sahih', 66, 8, 5237, 'O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, "Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent."', NULL, NULL, '66c3deee6242003103abbff3ee3a232723b0b9b9014f8483d45d7729d8cba24b'),
  ('en.sahih', 66, 9, 5238, 'O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.', NULL, NULL, '7eec0ae13a52cc80070e71ce89e19741b03b87ecda911fbf17baab4e5c2a6833'),
  ('en.sahih', 66, 10, 5239, 'Allah presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so those prophets did not avail them from Allah at all, and it was said, "Enter the Fire with those who enter."', NULL, NULL, 'be84d175fcf013bcfb3d93b689500fda3a96299a923825ed3c4c4256ddacf2dd'),
  ('en.sahih', 66, 11, 5240, 'And Allah presents an example of those who believed: the wife of Pharaoh, when she said, "My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people."', NULL, NULL, '1463fd53b4b8bb19cb94b401d39116f7daf53d5c1c84d2fa7b3ad0013cbaf0b5'),
  ('en.sahih', 66, 12, 5241, 'And [the example of] Mary, the daughter of ''Imran, who guarded her chastity, so We blew into [her garment] through Our angel, and she believed in the words of her Lord and His scriptures and was of the devoutly obedient.', NULL, NULL, '2254760c9ef74044b6faaef4c470df4e8cb4f5b08ff598e105ced075533f3c37'),
  ('en.sahih', 67, 1, 5242, 'Blessed is He in whose hand is dominion, and He is over all things competent -', NULL, NULL, 'd7170fcab28408d3c023f673ce27e075c0f8e502b9dedd22421319cdd8ecb3fd'),
  ('en.sahih', 67, 2, 5243, '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -', NULL, NULL, '249f367b7fa910e27eb4e1fb56ec77652cd405b4adf5fff45e99ea72ed6abb6f'),
  ('en.sahih', 67, 3, 5244, '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?', NULL, NULL, '2022557e5d19017fb1c3ca446096d12c45406631158fbc4fc8cfa546aeda6a1f'),
  ('en.sahih', 67, 4, 5245, 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.', NULL, NULL, '1607d2282ca945c72925b42616e2cf64dcdc8b2fdb0bb35f8ee323f4459a196a'),
  ('en.sahih', 67, 5, 5246, 'And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.', NULL, NULL, 'c646cec3d1b2e583fc13c75b0f1b91f3a7398a8351ec4032c27579c192e4b2ed'),
  ('en.sahih', 67, 6, 5247, 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.', NULL, NULL, 'e3804aafbe76143edd9ee0c85ec16b4579947f2e02f30b99330f7b33e8b70f6f'),
  ('en.sahih', 67, 7, 5248, 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.', NULL, NULL, 'f2048372c55fcf93f501367b28ef6eb0e256494c2f10589419b4b3c734d89d72'),
  ('en.sahih', 67, 8, 5249, 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"', NULL, NULL, '3361fb543f7afb2929006187d552a24ed542f4bac9a74b3f048ae409dd341b33'),
  ('en.sahih', 67, 9, 5250, 'They will say," Yes, a warner had come to us, but we denied and said, ''Allah has not sent down anything. You are not but in great error.''"', NULL, NULL, '415eb0c1f2b073ab99e18fb7ac2fec53fa114a511c1c2358e6b3ebb5d4d0bcc6'),
  ('en.sahih', 67, 10, 5251, 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."', NULL, NULL, '4fe91d14a21bf01f1693fc7d7b0160b4135ef61ab2e03aad7bcdc5a86f7987b7'),
  ('en.sahih', 67, 11, 5252, 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.', NULL, NULL, '4c7ba51b51974647e2b06bf17b8c0b2354e26e2463cb1b0489384a3ddbdf179e'),
  ('en.sahih', 67, 12, 5253, 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.', NULL, NULL, 'ef0d1985f35a2df035aee6a6d5327205dabdc9bb62006f4dfe3dc846791bd28d'),
  ('en.sahih', 67, 13, 5254, 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.', NULL, NULL, '4cc30c60fe2dcb107492e8312f8098e38d8c7fe87d0a9b15a47da22415cd4738'),
  ('en.sahih', 67, 14, 5255, 'Does He who created not know, while He is the Subtle, the Acquainted?', NULL, NULL, '249fed759be13980a8f2d5ae8458b12d454f9f386d943d7436b46daca1435cf3'),
  ('en.sahih', 67, 15, 5256, 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.', NULL, NULL, 'a67cd48e6b7b44223d3a697a53b9055da8f04ac7c2fe8cf3594168188ac25e3a'),
  ('en.sahih', 67, 16, 5257, 'Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?', NULL, NULL, '8c4387ba17ae2b282a2766465c97eec19d7caf2c13c75d2539f36a6c0c0d5698'),
  ('en.sahih', 67, 17, 5258, 'Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning.', NULL, NULL, '8b392375278206f520d32236fa9b067aca2cd07c005b5c38e1b58b65fe2cf782'),
  ('en.sahih', 67, 18, 5259, 'And already had those before them denied, and how [terrible] was My reproach.', NULL, NULL, '3957c0f0b51f33ec1c181120daf5f38cd2438af7535b9daf63c93813da30cb79'),
  ('en.sahih', 67, 19, 5260, 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.', NULL, NULL, '993fe5262f020a44c3047ce94700033d1117a0c32197142bdf717057406bb580'),
  ('en.sahih', 67, 20, 5261, 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.', NULL, NULL, 'fcc87a1dd0b9c94525624e7147d6fd11cb13dfcf837ed3a9ad97e9d38ca19bba'),
  ('en.sahih', 67, 21, 5262, 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.', NULL, NULL, 'e501e3413c1803a709570188f3290573b15fe46d5f0fa9855bf2e40fde585556'),
  ('en.sahih', 67, 22, 5263, 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?', NULL, NULL, '5c038ece7ee736f78828d47fe16ee613c4ca07d4aa18e48a08887c2ffcaa680a'),
  ('en.sahih', 67, 23, 5264, 'Say, "It is He who has produced you and made for you hearing and vision and hearts; little are you grateful."', NULL, NULL, 'e5859f8399f1c4694abd9ce114769806f25d0c752a33a4319dba06f11e3baf05'),
  ('en.sahih', 67, 24, 5265, 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."', NULL, NULL, '5d78c98f4c8f98b228b153663fc6ad116cbba5603fc71c1e29891bb03b179788'),
  ('en.sahih', 67, 25, 5266, 'And they say, "When is this promise, if you should be truthful?"', NULL, NULL, 'e4ee081fcbbad38a41d5b6a7019faf4a99f8ff664f6d41adf700b9660b4d4a8a'),
  ('en.sahih', 67, 26, 5267, 'Say, "The knowledge is only with Allah, and I am only a clear warner."', NULL, NULL, '5b42f4e3c292e06e60110e6b4e1e29a5d7e7ace58edeb8cda3a654441228cdb2'),
  ('en.sahih', 67, 27, 5268, 'But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, "This is that for which you used to call."', NULL, NULL, 'aa7d54ae6182fb3dad2167a6936afb526fdd9bc2103562c2b1658aacc99dd1ca'),
  ('en.sahih', 67, 28, 5269, 'Say, [O Muhammad], "Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?"', NULL, NULL, '1b1ac3e0a313aa340472615226faea2296057c5b8fd17f6933f2d6144d40a143'),
  ('en.sahih', 67, 29, 5270, 'Say, "He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error."', NULL, NULL, '6090e45e1542c37356433b10bb2545d85bcbbd98bacdb43952cd401433348d2a'),
  ('en.sahih', 67, 30, 5271, 'Say, "Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?"', NULL, NULL, 'da77d01e47ad5a9c6225edf1682fcdb9f71cfd999c3c6d952914021212b5e4f3'),
  ('en.sahih', 68, 1, 5272, 'Nun. By the pen and what they inscribe,', NULL, NULL, '23471b0114b2df145c284352eb33c012e91db1889f0fe7f5d3b2263499a0daba'),
  ('en.sahih', 68, 2, 5273, 'You are not, [O Muhammad], by the favor of your Lord, a madman.', NULL, NULL, '740dea9e001ad4f5397e746bbd2e3d10badaff110bb5e1cb04229a21d005ce46'),
  ('en.sahih', 68, 3, 5274, 'And indeed, for you is a reward uninterrupted.', NULL, NULL, '6734e6eaed8b19e093cd3a227f6e586cddf78f52a36b6ec6bb1206da717c420f'),
  ('en.sahih', 68, 4, 5275, 'And indeed, you are of a great moral character.', NULL, NULL, '94b84798870196e5bd28ed3450c8136e62fff0f56181fa13cf5926771119a7cb'),
  ('en.sahih', 68, 5, 5276, 'So you will see and they will see', NULL, NULL, 'e96ab901eaba6c5e6900ef53ce5e4ec5033f5ae42756db3bf03daf03be553e9f'),
  ('en.sahih', 68, 6, 5277, 'Which of you is the afflicted [by a devil].', NULL, NULL, '748187026cf9031f9c255f3bd9798fc285e82612f677a607811c087d185bc6af'),
  ('en.sahih', 68, 7, 5278, 'Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided.', NULL, NULL, 'b328fa348a7fa7c80bdb95b65ef0efd13d7c52b5562aa9b4179306eacd660f64'),
  ('en.sahih', 68, 8, 5279, 'Then do not obey the deniers.', NULL, NULL, '3750ee81cd4362a955de339b05032e1f53146798e8c82b2222bbab0940b8f73e'),
  ('en.sahih', 68, 9, 5280, 'They wish that you would soften [in your position], so they would soften [toward you].', NULL, NULL, 'c38433b8389d45a36e42c005f9a4f365acbd68c47de91d3f0cebcebe4f5ebbf2'),
  ('en.sahih', 68, 10, 5281, 'And do not obey every worthless habitual swearer', NULL, NULL, 'e7e4f748ab6afa86ed3fcc868a1e676cf874b66b5a88723a26f3a16e5a2ac210'),
  ('en.sahih', 68, 11, 5282, '[And] scorner, going about with malicious gossip -', NULL, NULL, '0b7ca27b42e88e57a5b913e1319638247ec654a7d9a9ecfde5be176b6a36b017'),
  ('en.sahih', 68, 12, 5283, 'A preventer of good, transgressing and sinful,', NULL, NULL, '39ca3bb4c38724e92d0a1c6079634b3121c0d9d85b00cf78608bffe40434e91b'),
  ('en.sahih', 68, 13, 5284, 'Cruel, moreover, and an illegitimate pretender.', NULL, NULL, '51c2a88165e2697a9e32679edffe2ad1716052b42e251bf2806904319dbce51b'),
  ('en.sahih', 68, 14, 5285, 'Because he is a possessor of wealth and children,', NULL, NULL, '72eee3224cbc726a1979489c528914295aae8402060cf87f9c94e67acafd5b46'),
  ('en.sahih', 68, 15, 5286, 'When Our verses are recited to him, he says, "Legends of the former peoples."', NULL, NULL, '6a63c1d09f470309c92815a14cdd7a4a7e3a5d95257acd0be60e171f77973bfa'),
  ('en.sahih', 68, 16, 5287, 'We will brand him upon the snout.', NULL, NULL, '125f379cfa0df9927456b4f99aa6d1093784d4f308f40bd2a6040ff30ce62f69'),
  ('en.sahih', 68, 17, 5288, 'Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning', NULL, NULL, '5f1c91acbada1573af1f43a2ffbdf39995c8bb4661cc3a0146975eed4ecafa6c'),
  ('en.sahih', 68, 18, 5289, 'Without making exception.', NULL, NULL, '8e43f27f7c01efbe6fdad941841150b26906b6f90e29b0d50e29815f13bc6f68'),
  ('en.sahih', 68, 19, 5290, 'So there came upon the garden an affliction from your Lord while they were asleep.', NULL, NULL, 'dae39a2c2977010ce9fc0b0536c85a8c4d976039b12679dff9bcabcc5899161b'),
  ('en.sahih', 68, 20, 5291, 'And it became as though reaped.', NULL, NULL, '22633376ef9de4a6f5af7f910cbb584ef4e52fd926164ca9e16f20fe84765c3d'),
  ('en.sahih', 68, 21, 5292, 'And they called one another at morning,', NULL, NULL, '92491a137a1d3403ff03aa847557c495626acf628c137c672b9c2fa880b794db'),
  ('en.sahih', 68, 22, 5293, '[Saying], "Go early to your crop if you would cut the fruit."', NULL, NULL, 'b89a1aabaa4915badd3529eb696c2d6b4453f8f8e004c638de99a6add8949875'),
  ('en.sahih', 68, 23, 5294, 'So they set out, while lowering their voices,', NULL, NULL, '83f0c7b9aed28ef5ffcd8764675f285596a7556a9e4b81988f58c2db3e3f05c7'),
  ('en.sahih', 68, 24, 5295, '[Saying], "There will surely not enter it today upon you [any] poor person."', NULL, NULL, 'f1fb14da775215b0633d0c1c2f5cb88fa40747674ba92f4ad536afdeb2a42ab3'),
  ('en.sahih', 68, 25, 5296, 'And they went early in determination, [assuming themselves] able.', NULL, NULL, '7fadf7e8708967ce288283d4dc03b5f7f6016ffd8c331b0f0baef3d389192b63'),
  ('en.sahih', 68, 26, 5297, 'But when they saw it, they said, "Indeed, we are lost;', NULL, NULL, '88a28d8f0fdfd7b3069027bd887b92692e37cfa3d89eb60c6db9f900cad22d65'),
  ('en.sahih', 68, 27, 5298, 'Rather, we have been deprived."', NULL, NULL, '5734366bc766c56fe5ae3228eeb2f21e4829e63e35a198ea652766ac3f25bf0d'),
  ('en.sahih', 68, 28, 5299, 'The most moderate of them said, "Did I not say to you, ''Why do you not exalt [Allah]?'' "', NULL, NULL, '362376bfbee70256eeef00019d5472839aa9d54cde1af24fd01dbf320175df9d'),
  ('en.sahih', 68, 29, 5300, 'They said, "Exalted is our Lord! Indeed, we were wrongdoers."', NULL, NULL, '701eaaa0bf76b1b41469e305495e24267c82495430ee69de142224dfbea22f24')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 68, 30, 5301, 'Then they approached one another, blaming each other.', NULL, NULL, '6b9c078235490aa286ebc1d1e2b4839e4e8334c2bc93ebea915521294bf960e2'),
  ('en.sahih', 68, 31, 5302, 'They said, "O woe to us; indeed we were transgressors.', NULL, NULL, '7a3dfccf172b36d9e00a647935a098380ee3052e4fb80435253f8f71baea2165'),
  ('en.sahih', 68, 32, 5303, 'Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous."', NULL, NULL, '39949eecb633d5c59b51046f821e03be9d668c9d8d562c3ca34c1f99f907279a'),
  ('en.sahih', 68, 33, 5304, 'Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew.', NULL, NULL, '46ab7c9595946176c06610936c63986d2a90e39f5d4c1097cbaf947e55955678'),
  ('en.sahih', 68, 34, 5305, 'Indeed, for the righteous with their Lord are the Gardens of Pleasure.', NULL, NULL, '62dfaae56e78e2ff51e8abecf8d3c9d115e4c6179d4d3ef65fb09ca26d433748'),
  ('en.sahih', 68, 35, 5306, 'Then will We treat the Muslims like the criminals?', NULL, NULL, 'f51fcd60f096ef09c80d527a764d900c917ae9880029aa593c06d994594db0a3'),
  ('en.sahih', 68, 36, 5307, 'What is [the matter] with you? How do you judge?', NULL, NULL, 'f8b2380d419bb6d2f5298de5cc63bb9a1db8cc120938d6d4f0828bb13ce01d34'),
  ('en.sahih', 68, 37, 5308, 'Or do you have a scripture in which you learn', NULL, NULL, '084821e8e9dbc584ef1c098e0f4c0f89e08c820985a208a728f4c2f030528b60'),
  ('en.sahih', 68, 38, 5309, 'That indeed for you is whatever you choose?', NULL, NULL, '4f60547a27b7ff9303fd94cb418da3e8da2078775410176fc9902c3a5e7d1053'),
  ('en.sahih', 68, 39, 5310, 'Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge?', NULL, NULL, '6a3e856be777256a2dbf29a7b9ba8a1cfdf8bcff43efe70053713a122f8d1eca'),
  ('en.sahih', 68, 40, 5311, 'Ask them which of them, for that [claim], is responsible.', NULL, NULL, '06ffcdfd95440abc8e02f7bcb8fbfa556425101bafe2a5a8b37402b27506096a'),
  ('en.sahih', 68, 41, 5312, 'Or do they have partners? Then let them bring their partners, if they should be truthful.', NULL, NULL, '235a06d5684a8baaf11f09776e25a99df320cb8681a810e5eaa8a40a4b761780'),
  ('en.sahih', 68, 42, 5313, 'The Day the shin will be uncovered and they are invited to prostration but the disbelievers will not be able,', NULL, NULL, '8a2e3cb5ca6acd45b08cf9d0e0bb610a59eb3ac22eacd03fea150a010dadc430'),
  ('en.sahih', 68, 43, 5314, 'Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound.', NULL, NULL, '7fb03ff39b9c61d5aadb7477a972bcbe366ecda1069b787fee533e5f9b5058e0'),
  ('en.sahih', 68, 44, 5315, 'So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur''an. We will progressively lead them [to punishment] from where they do not know.', NULL, NULL, '7521a288b70b5dbb5eaf315ba6535c39bda51019c2ecd6b30bd8fa9c4d90d880'),
  ('en.sahih', 68, 45, 5316, 'And I will give them time. Indeed, My plan is firm.', NULL, NULL, '529112a3c1f4088a5561ee52848ec2c6a8b2cca7eb18a652973ce115f7728d78'),
  ('en.sahih', 68, 46, 5317, 'Or do you ask of them a payment, so they are by debt burdened down?', NULL, NULL, '25261fca21c08e62620cb8e7073bb7b533078ba2148d0bc3269b380a1220eb59'),
  ('en.sahih', 68, 47, 5318, 'Or have they [knowledge of] the unseen, so they write [it] down?', NULL, NULL, 'd9247f91f119ed86a589bb1be7726297cc660ff4922c6c7df5cae7d955badad9'),
  ('en.sahih', 68, 48, 5319, 'Then be patient for the decision of your Lord, [O Muhammad], and be not like the companion of the fish when he called out while he was distressed.', NULL, NULL, 'd1680f30b2e9dc3afd49066932f440c9abceda7e521dcc641e82a1a59456e8b3'),
  ('en.sahih', 68, 49, 5320, 'If not that a favor from his Lord overtook him, he would have been thrown onto the naked shore while he was censured.', NULL, NULL, '5f7987580b8d20acb4a1f75faff72b624326237f7b7fc8e96a54f4e34bed8534'),
  ('en.sahih', 68, 50, 5321, 'And his Lord chose him and made him of the righteous.', NULL, NULL, '15af7ae2bae89b6691a3550bb6d85dae545634d468cacdd01851953a19761f17'),
  ('en.sahih', 68, 51, 5322, 'And indeed, those who disbelieve would almost make you slip with their eyes when they hear the message, and they say, "Indeed, he is mad."', NULL, NULL, 'e921c90687b599734bc079d72df4bb1e8e6a6eb3a06e9132c56410c5de996fe1'),
  ('en.sahih', 68, 52, 5323, 'But it is not except a reminder to the worlds.', NULL, NULL, 'a0d69854c391dfe8543acce6f2258c7ae54295d953860cc00b2db4c044ba2a82'),
  ('en.sahih', 69, 1, 5324, 'The Inevitable Reality -', NULL, NULL, '2312fea238efa35ccef614179524264dc62340655d5332ddf6e1f22f1f88046e'),
  ('en.sahih', 69, 2, 5325, 'What is the Inevitable Reality?', NULL, NULL, 'f0cba170e2c154fb8ed8fc772a80885f5c3ec5584c6e54d8a4147f84016b5748'),
  ('en.sahih', 69, 3, 5326, 'And what can make you know what is the Inevitable Reality?', NULL, NULL, 'bcf1d8d2dcec429ccdb164eda9d7afcf0339c1a20ae8392c664a2f0ba60c202f'),
  ('en.sahih', 69, 4, 5327, 'Thamud and ''Aad denied the Striking Calamity.', NULL, NULL, '2c3f8bdd6e40d69551e0e2b6e8f330a90f3ad8294653ae187cd7c0d94f6768c0'),
  ('en.sahih', 69, 5, 5328, 'So as for Thamud, they were destroyed by the overpowering [blast].', NULL, NULL, '28f60628b12c50a7efc7df2f81b6977e3ab8f667a3dd90f58252025640c318b5'),
  ('en.sahih', 69, 6, 5329, 'And as for ''Aad, they were destroyed by a screaming, violent wind', NULL, NULL, '9f4f35dd42d26b4c5deeac8aa9646942361206a66757355fa29e1dba25a52ff3'),
  ('en.sahih', 69, 7, 5330, 'Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.', NULL, NULL, '4059da1062c02a2faf795b32d7c37031c662dd86f1a9d54f4da5d90e93a6bbd6'),
  ('en.sahih', 69, 8, 5331, 'Then do you see of them any remains?', NULL, NULL, '4490d81b05157f8f94249fbe936413502698f2be154d3febe8a1f7a143113c72'),
  ('en.sahih', 69, 9, 5332, 'And there came Pharaoh and those before him and the overturned cities with sin.', NULL, NULL, '8046368c6a4c832c8ea7039fe3f3dbf58c39fff11345f09ec259f8706fa4ebe8'),
  ('en.sahih', 69, 10, 5333, 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].', NULL, NULL, '9d24249569ca4f642d79e20de5c513ecba4821ff89f9e49d6681855b6fa7b2d4'),
  ('en.sahih', 69, 11, 5334, 'Indeed, when the water overflowed, We carried your ancestors in the sailing ship', NULL, NULL, 'adc193739990cf2a506800326a5a58542e2d82a4997055a50822b6a9fa10e168'),
  ('en.sahih', 69, 12, 5335, 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.', NULL, NULL, 'f6a1e94c5ef58dcabaa342d184b54a0719ebc440f74735af890b780257fe3e68'),
  ('en.sahih', 69, 13, 5336, 'Then when the Horn is blown with one blast', NULL, NULL, 'eb1ae62d111cbd95f072cc80aca6ff13d11e60675e20d95cdbbed2c893556969'),
  ('en.sahih', 69, 14, 5337, 'And the earth and the mountains are lifted and leveled with one blow -', NULL, NULL, '4d81bc007ba811d08b09457f370330eda547e4af7087f902c3be657276fdc5cc'),
  ('en.sahih', 69, 15, 5338, 'Then on that Day, the Resurrection will occur,', NULL, NULL, '43e9ecef6a0195a4d32fc7becf32c5cb41e68e720df7827f26d4585595e58a3f'),
  ('en.sahih', 69, 16, 5339, 'And the heaven will split [open], for that Day it is infirm.', NULL, NULL, 'cad807bbf21c1c8d0ecd717753357063bd9ef86dc557a25c0cd050de649c884c'),
  ('en.sahih', 69, 17, 5340, 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].', NULL, NULL, '50e1d78f385ccb055410b830d2e8057f4a99dd6d2a06c2d044ad7cf2cb4586cc'),
  ('en.sahih', 69, 18, 5341, 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.', NULL, NULL, '585d6b0eb023f2fcbec4d3e4861df5bea2d500834e33c9f812feb6057bf3971c'),
  ('en.sahih', 69, 19, 5342, 'So as for he who is given his record in his right hand, he will say, "Here, read my record!', NULL, NULL, '4f66895c4bfcaef44ecc820ac2f301f59dea436f236fd16e27fa47ae288c0ee7'),
  ('en.sahih', 69, 20, 5343, 'Indeed, I was certain that I would be meeting my account."', NULL, NULL, '7b7f1241dacdb4ad25ee80ada8c1aa775086e55f3adb3128978fd18b17791828'),
  ('en.sahih', 69, 21, 5344, 'So he will be in a pleasant life -', NULL, NULL, '0ed2134a130425d845ea92a1150ffb17d05b8ea8ec8d9ddfed3b17dfc81c968b'),
  ('en.sahih', 69, 22, 5345, 'In an elevated garden,', NULL, NULL, '6d636554d8ad1f9eb1fa517543dc81bfd5457510712a2a59d19bedfde52d96c0'),
  ('en.sahih', 69, 23, 5346, 'Its [fruit] to be picked hanging near.', NULL, NULL, '246a958320cc6eef9ca47c7078c4e6468953a4ab2d8bfd1923a65def36bcb6f5'),
  ('en.sahih', 69, 24, 5347, '[They will be told], "Eat and drink in satisfaction for what you put forth in the days past."', NULL, NULL, '9f43d3dd7959da2ac7e09d82b4fcf7b73df2049dfd57a40bfc6535a3b4bc2707'),
  ('en.sahih', 69, 25, 5348, 'But as for he who is given his record in his left hand, he will say, "Oh, I wish I had not been given my record', NULL, NULL, '71f4e351b97e9e3a0cb85d087ea76daca03566f0b3a687f0a5e33d00760aaefa'),
  ('en.sahih', 69, 26, 5349, 'And had not known what is my account.', NULL, NULL, '2ecaa41709481a1bf3571977aa70b729017ac8192b3bf5b2f8f3396630e12052'),
  ('en.sahih', 69, 27, 5350, 'I wish my death had been the decisive one.', NULL, NULL, '037fcc083f9d211e0c0204361259876f715df6744ee459a6a1d80aa0d006771f'),
  ('en.sahih', 69, 28, 5351, 'My wealth has not availed me.', NULL, NULL, 'a239865e784fbc851a622dbbda1cb434e319b4aa8d2983daf574d885c17e993f'),
  ('en.sahih', 69, 29, 5352, 'Gone from me is my authority."', NULL, NULL, '21864e9af429ed53848e7a7a0a4c93edbc36abf56466e0f85d1560ade5f551ba'),
  ('en.sahih', 69, 30, 5353, '[Allah will say], "Seize him and shackle him.', NULL, NULL, '4fb5a220b6ee36e01f920f153cce5eef5240492521c03675d31f63a7cf7b05a9'),
  ('en.sahih', 69, 31, 5354, 'Then into Hellfire drive him.', NULL, NULL, '1a0cce6479aa5a6189adc7b546bb7b0bfd9ee19ec10723c36d609edcf517b21a'),
  ('en.sahih', 69, 32, 5355, 'Then into a chain whose length is seventy cubits insert him."', NULL, NULL, 'b88b4e16f7de9ff10fd601f345a47b0f27046588ce83e282b77b801d4df38238'),
  ('en.sahih', 69, 33, 5356, 'Indeed, he did not used to believe in Allah, the Most Great,', NULL, NULL, '2b4b369cda5a4c5527e0c6b408acd95fcde705b33ac113d05746db41ddebe805'),
  ('en.sahih', 69, 34, 5357, 'Nor did he encourage the feeding of the poor.', NULL, NULL, '6a8fa1afa8aa05f7776ce6f6448d052e421d9eaf14488d4b0587c34bd543af08'),
  ('en.sahih', 69, 35, 5358, 'So there is not for him here this Day any devoted friend', NULL, NULL, '200499c3063293607ec91f81e98f51127d3331e421faca126619a43b52324992'),
  ('en.sahih', 69, 36, 5359, 'Nor any food except from the discharge of wounds;', NULL, NULL, '82d7d12e3d4fde3ead5cbdc305b922836338c55a07d8ce59871c711751a19675'),
  ('en.sahih', 69, 37, 5360, 'None will eat it except the sinners.', NULL, NULL, 'bc88ad86329e5146636eb984935a50666b0ee50d32bc62ba790329b9e6795da9'),
  ('en.sahih', 69, 38, 5361, 'So I swear by what you see', NULL, NULL, '3002f77f1098b416060c2297f2b13314fb88744de2b8d089ed01800f78574790'),
  ('en.sahih', 69, 39, 5362, 'And what you do not see', NULL, NULL, '3893b799dfb5f2f496cb6ad7e16db04d73c3bc87c99a64b2c4b9db724dacdac1'),
  ('en.sahih', 69, 40, 5363, '[That] indeed, the Qur''an is the word of a noble Messenger.', NULL, NULL, '3e4a87071c371e911d9a23420a3e33d5eba4239c98576499712c4a9a19005bfe'),
  ('en.sahih', 69, 41, 5364, 'And it is not the word of a poet; little do you believe.', NULL, NULL, '25e6e9495acd908fdac3af07613b3cc4e2dccd95442e07423e3b63de6efbc0e1'),
  ('en.sahih', 69, 42, 5365, 'Nor the word of a soothsayer; little do you remember.', NULL, NULL, '5d92c4fe17b508302a5e57ed3c363e5e384d53804cbb8429465c1061812912c5'),
  ('en.sahih', 69, 43, 5366, '[It is] a revelation from the Lord of the worlds.', NULL, NULL, 'bd22e18822c81578b1586128b75971f56d9ae6c434681cd9c9a768e9cce07628'),
  ('en.sahih', 69, 44, 5367, 'And if Muhammad had made up about Us some [false] sayings,', NULL, NULL, 'cff94ed5a881e180e993664c662561a5e8229e8a1074e293bb9ba4a2f43575a5'),
  ('en.sahih', 69, 45, 5368, 'We would have seized him by the right hand;', NULL, NULL, '325e7e93a4e8b22a508b406dfcfcba2c842dbdcf3433e57cddc212cfbcd5619b'),
  ('en.sahih', 69, 46, 5369, 'Then We would have cut from him the aorta.', NULL, NULL, 'f2c5a36667f491c4acc817b55ed5edc7d2e09b300edfa83d4c501d73384caf10'),
  ('en.sahih', 69, 47, 5370, 'And there is no one of you who could prevent [Us] from him.', NULL, NULL, '6d716b49db0483b496211aab8f4bc364c67895d3502592ad03a1d481a2005d40'),
  ('en.sahih', 69, 48, 5371, 'And indeed, the Qur''an is a reminder for the righteous.', NULL, NULL, 'ebee5d939cd3cb1379ae91a5d6f31e0caaa0d98b6721ee5d16803f116e24fceb'),
  ('en.sahih', 69, 49, 5372, 'And indeed, We know that among you are deniers.', NULL, NULL, '3d6174e2db0d7ef34393465d3c6cf98fff2f8b07e3664c5bc625777816bca7f2'),
  ('en.sahih', 69, 50, 5373, 'And indeed, it will be [a cause of] regret upon the disbelievers.', NULL, NULL, '773c20da5765974ad0385262153b84dbb9ecb67d6571813ae9fa27cb53e5b920'),
  ('en.sahih', 69, 51, 5374, 'And indeed, it is the truth of certainty.', NULL, NULL, '722e3728cb1ffce55c2d8c7f3090b94747552bd77eb7933ba8b7f62701fbd1a5'),
  ('en.sahih', 69, 52, 5375, 'So exalt the name of your Lord, the Most Great.', NULL, NULL, '08981e024909026d286f8f09888619fdfb6d8af9fa59c685d1acc0c484cfced6'),
  ('en.sahih', 70, 1, 5376, 'A supplicant asked for a punishment bound to happen', NULL, NULL, 'e6a90fa3d225b4e6690c3c072091a9f255f472707991a4b9898f863e051ec74d'),
  ('en.sahih', 70, 2, 5377, 'To the disbelievers; of it there is no preventer.', NULL, NULL, '059532bf44c53b2c7b8db2157a10ab799f6a866c50f544e26398f619d9fcfaeb'),
  ('en.sahih', 70, 3, 5378, '[It is] from Allah, owner of the ways of ascent.', NULL, NULL, '96668e7dcf9b58b7f17b9e45419092410184f6d33aa7c0b954a7ec3669237589'),
  ('en.sahih', 70, 4, 5379, 'The angels and the Spirit will ascend to Him during a Day the extent of which is fifty thousand years.', NULL, NULL, '18f54f498ff486a041dbf360150a757493d27c31251c2f5a0b0414f794eceadc'),
  ('en.sahih', 70, 5, 5380, 'So be patient with gracious patience.', NULL, NULL, 'de2c6dc3b2531c51603ed4ff0aafbd8dbcb9970a7c7435c6e3ea1efdf0ff8a2a'),
  ('en.sahih', 70, 6, 5381, 'Indeed, they see it [as] distant,', NULL, NULL, '1490213f3f8d128b0cace8f0737e1e827f222fd0c993897e46ac6b7b401e518e'),
  ('en.sahih', 70, 7, 5382, 'But We see it [as] near.', NULL, NULL, '5a6d316112b2dbc6f7e02e06f41883f8c818d62a2cb2db3cfdde3ac1259f0e18'),
  ('en.sahih', 70, 8, 5383, 'On the Day the sky will be like murky oil,', NULL, NULL, 'c3f49606aca5abebb06f46c25fe666d85ba3ac094486332a03694e1929a11ed7'),
  ('en.sahih', 70, 9, 5384, 'And the mountains will be like wool,', NULL, NULL, '27f9168e28e91111418916dc51149b1df12bb317b73a411051519a3166fec768'),
  ('en.sahih', 70, 10, 5385, 'And no friend will ask [anything of] a friend,', NULL, NULL, '6cf9c1ed8697b33838bef258d9d7c930af0b541d34915f129019b6241c5f7f6c'),
  ('en.sahih', 70, 11, 5386, 'They will be shown each other. The criminal will wish that he could be ransomed from the punishment of that Day by his children', NULL, NULL, '309c842e4f0f5bd3a8117abec4833455ef5278b410e0342973cdf116f156e670'),
  ('en.sahih', 70, 12, 5387, 'And his wife and his brother', NULL, NULL, '36d6c0ba35d609413162b3a27cfb8a34d4d4e8b82427dc7e181ba2c50412dae6'),
  ('en.sahih', 70, 13, 5388, 'And his nearest kindred who shelter him', NULL, NULL, 'd89d921ecc38db9cebb17891f25da72f213e6c6b2407e9e2636079126ce3890f'),
  ('en.sahih', 70, 14, 5389, 'And whoever is on earth entirely [so] then it could save him.', NULL, NULL, '1d025a2da4a97e13558ccf8dc0ea5cb456b8a1ee34a818276a1ebd92fadf710f'),
  ('en.sahih', 70, 15, 5390, 'No! Indeed, it is the Flame [of Hell],', NULL, NULL, '9265bf949aeb0b15ec36446a7798fb362711df07f7f18a30fe1e6481030fae08'),
  ('en.sahih', 70, 16, 5391, 'A remover of exteriors.', NULL, NULL, '4db6cb24634001db4739153a3f49860c1bd092d74dfc5317e10b2da0678f47e0'),
  ('en.sahih', 70, 17, 5392, 'It invites he who turned his back [on truth] and went away [from obedience]', NULL, NULL, '63a69e2ba98bea544c473f9fbc5ed9e7a7efea6c8d3dd916c91bd27a58c15631'),
  ('en.sahih', 70, 18, 5393, 'And collected [wealth] and hoarded.', NULL, NULL, 'e47d939e8f87d1f36d834589c83189ea9c946ff9f72ac38cde5d3e85d72300f8'),
  ('en.sahih', 70, 19, 5394, 'Indeed, mankind was created anxious:', NULL, NULL, 'd4d29e65d8da09a3511e5a35503cd4dc877183dd26a8dfc6e14cf24fbc227749'),
  ('en.sahih', 70, 20, 5395, 'When evil touches him, impatient,', NULL, NULL, 'edfd812b707411fc828e9528e2632aa12a386a6e2fc74e73e242d4d5176bde6d'),
  ('en.sahih', 70, 21, 5396, 'And when good touches him, withholding [of it],', NULL, NULL, '7f34e50a9a6fd304ca2c21c8d41691f7bc48e8e4223fd532645f58e8aba07b10'),
  ('en.sahih', 70, 22, 5397, 'Except the observers of prayer -', NULL, NULL, 'a769726304c107b810078bf2cc028396e1c3aa15d4827aef543d0ea6a20c155c'),
  ('en.sahih', 70, 23, 5398, 'Those who are constant in their prayer', NULL, NULL, 'be49d8c7356a19d9265740097e047bee148e2e40268ae02fd27c7d9d58e56298'),
  ('en.sahih', 70, 24, 5399, 'And those within whose wealth is a known right', NULL, NULL, 'f9a6550bb166dc910563601a3115b5fcb4720871b8736b9d0d053f935795d0e9'),
  ('en.sahih', 70, 25, 5400, 'For the petitioner and the deprived -', NULL, NULL, '37b719f1389ca4036c0bedd24d69c967f0f6496e74ae43bd169212c0426d434e')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 70, 26, 5401, 'And those who believe in the Day of Recompense', NULL, NULL, 'fd2f7ba5f4ce3324bf8e7412534a90bc26ffe563fae110739f34fd9ab73d9354'),
  ('en.sahih', 70, 27, 5402, 'And those who are fearful of the punishment of their Lord -', NULL, NULL, '12a1f0ce8f3f4082267deba2a2f6554b2f4e3a871f43c56d1518352757c0fb0d'),
  ('en.sahih', 70, 28, 5403, 'Indeed, the punishment of their Lord is not that from which one is safe -', NULL, NULL, '576d3ddd8dfcd1c4251772ba146e2a60669e3f9dbf8966d9eaec56dd7091417b'),
  ('en.sahih', 70, 29, 5404, 'And those who guard their private parts', NULL, NULL, '8ff36417073dfe7fb831933133b6e22122c1e6f263c71e2a1f6159bd7bdb6842'),
  ('en.sahih', 70, 30, 5405, 'Except from their wives or those their right hands possess, for indeed, they are not to be blamed -', NULL, NULL, 'ae95bfd7c29688096038860bb2000ef1c63d4a732ed624a1fcfb5d4a85daa5f5'),
  ('en.sahih', 70, 31, 5406, 'But whoever seeks beyond that, then they are the transgressors -', NULL, NULL, 'b9476a04e5e4bae8e210c103d8cc3a18e2134f9c282701507af356f6886c38d5'),
  ('en.sahih', 70, 32, 5407, 'And those who are to their trusts and promises attentive', NULL, NULL, '7e68edcd868a119f95d1316729acb6dee3ce98213a8f752a2ee0ebc894c86851'),
  ('en.sahih', 70, 33, 5408, 'And those who are in their testimonies upright', NULL, NULL, '8f9b8c87d5f5c7a3d80466f7927bfae2cf3d3fd0098074e9531dc24276e15422'),
  ('en.sahih', 70, 34, 5409, 'And those who [carefully] maintain their prayer:', NULL, NULL, 'fe93d4e14bf6b407c13070b6433dfc744f4bca43444622b6f6b7ca6dc79a75da'),
  ('en.sahih', 70, 35, 5410, 'They will be in gardens, honored.', NULL, NULL, '79ebfe9e258e4e13975c3bdc9b4cad3fa4ad63792b6777438fc39e92ffa2cbf2'),
  ('en.sahih', 70, 36, 5411, 'So what is [the matter] with those who disbelieve, hastening [from] before you, [O Muhammad],', NULL, NULL, 'ac543fc0f82291e7ec2c34d0386c0e48b17ab529244c2f26e813e36354d963ce'),
  ('en.sahih', 70, 37, 5412, '[To sit] on [your] right and [your] left in separate groups?', NULL, NULL, '2198911a1119fbb42eb4835f75fc394a8020d33777678c898a38dd91fdb00029'),
  ('en.sahih', 70, 38, 5413, 'Does every person among them aspire to enter a garden of pleasure?', NULL, NULL, '5fe0fbd1edc6bcaff363b24574ba66db3a45c1fedc5d14af4b7342db2c51041d'),
  ('en.sahih', 70, 39, 5414, 'No! Indeed, We have created them from that which they know.', NULL, NULL, '099b6aac67e440d493a52e26d7f3f6a5e4827b5273e15b2e40f5ca9c54311075'),
  ('en.sahih', 70, 40, 5415, 'So I swear by the Lord of [all] risings and settings that indeed We are able', NULL, NULL, 'f83c9de518730a0a739603e8ac6d52d0980ca8a063c5c4ed7764f45b40047491'),
  ('en.sahih', 70, 41, 5416, 'To replace them with better than them; and We are not to be outdone.', NULL, NULL, '82882360e445582b73b83ad8da9da22383be1fb6dcc0be4f9cd6a20f56fc7b45'),
  ('en.sahih', 70, 42, 5417, 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -', NULL, NULL, '4405bb3bc7d88e858c0442e8a93dac875e304e3ed63d320e9d50160f67207328'),
  ('en.sahih', 70, 43, 5418, 'The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening.', NULL, NULL, '98a8ce9f0efdd04e0f46fe3b5358ad6630b6ba3f014fb013f4a7ae35132554f9'),
  ('en.sahih', 70, 44, 5419, 'Their eyes humbled, humiliation will cover them. That is the Day which they had been promised.', NULL, NULL, 'ee87d69dc7b511c08ece38197d0a65659a1199e9653d806692f81380b1661e21'),
  ('en.sahih', 71, 1, 5420, 'Indeed, We sent Noah to his people, [saying], "Warn your people before there comes to them a painful punishment."', NULL, NULL, 'c0e1624ad067b0abc7f716bc680d65c5556e9a24cd3d082c70b50f57c52b164b'),
  ('en.sahih', 71, 2, 5421, 'He said, "O my people, indeed I am to you a clear warner,', NULL, NULL, 'd23fe4f41fbc39917bf96b86bd07dcbf4742d1ce0bdda0674c98861b4e5f9e3f'),
  ('en.sahih', 71, 3, 5422, '[Saying], ''Worship Allah, fear Him and obey me.', NULL, NULL, '03c7c19b1e56ef5ca47834f8f70cfef90070e27ac781bab6a2d82a687462654e'),
  ('en.sahih', 71, 4, 5423, 'Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew.'' "', NULL, NULL, '60972575274c5f8a9fd9b73dad9a107d05cc94eac793675c2b383cced52031ff'),
  ('en.sahih', 71, 5, 5424, 'He said, "My Lord, indeed I invited my people [to truth] night and day.', NULL, NULL, 'eea2b69535be819544a69fc99801f34fd53d40d89a93e2e5aa5d70f0b06da2f5'),
  ('en.sahih', 71, 6, 5425, 'But my invitation increased them not except in flight.', NULL, NULL, '810837c5c100ed86f70dadc962a31b8c8f59c0cf2e54413349fef1e7be7a3927'),
  ('en.sahih', 71, 7, 5426, 'And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance.', NULL, NULL, 'd175cc1cf96645834acebe4bbfbdcef3a776c88727155850e64d37707afd7eef'),
  ('en.sahih', 71, 8, 5427, 'Then I invited them publicly.', NULL, NULL, '3118830bb541c0d289fa1a769bbcfdb178d4c3971176daf89c51f9cbea0e2a79'),
  ('en.sahih', 71, 9, 5428, 'Then I announced to them and [also] confided to them secretly', NULL, NULL, '4c776393414dc12488ccef3e6e79c2a7dd4d131e67629acd90bd7816f62b1988'),
  ('en.sahih', 71, 10, 5429, 'And said, ''Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.', NULL, NULL, '617c42f2d53b1c085fd640b16e64f23460a539c5ec5bfe3eea37a4dbfcaba30c'),
  ('en.sahih', 71, 11, 5430, 'He will send [rain from] the sky upon you in [continuing] showers', NULL, NULL, 'cbe97694249c982a5dd13ce9b272d490eaac320c18652c004edc69056adcbc05'),
  ('en.sahih', 71, 12, 5431, 'And give you increase in wealth and children and provide for you gardens and provide for you rivers.', NULL, NULL, 'fa66cdc726ad4a356698866ad3871c332a821051bcc9395a593a793bb31786de'),
  ('en.sahih', 71, 13, 5432, 'What is [the matter] with you that you do not attribute to Allah [due] grandeur', NULL, NULL, '6ad1c71e7684b6b15ca464d2023e865342e8d385237490440ac4b610b7d2d778'),
  ('en.sahih', 71, 14, 5433, 'While He has created you in stages?', NULL, NULL, '6c92f75202cd76791295f6d91d4d30b77b54d2501f857db1dae115bbf0cd065f'),
  ('en.sahih', 71, 15, 5434, 'Do you not consider how Allah has created seven heavens in layers', NULL, NULL, '54ac5ae4ab432966850203812c91d43a5d286b5abf0c9f240c25de034136712f'),
  ('en.sahih', 71, 16, 5435, 'And made the moon therein a [reflected] light and made the sun a burning lamp?', NULL, NULL, 'd2bdeff060839d160d6375b75e7b73607ab089d451e26328d241c151135aa701'),
  ('en.sahih', 71, 17, 5436, 'And Allah has caused you to grow from the earth a [progressive] growth.', NULL, NULL, 'ea3e6ee2b4fd6e39fd5f87335cd941ba35dbdd8a45e8353c69bca1009dbf4ade'),
  ('en.sahih', 71, 18, 5437, 'Then He will return you into it and extract you [another] extraction.', NULL, NULL, '2d0af9ff07a8299faebd89668a9d184505406c512a6364db07247720d0329ecd'),
  ('en.sahih', 71, 19, 5438, 'And Allah has made for you the earth an expanse', NULL, NULL, '15b2875b66ac285ebc5cb4f24d991cbc19843d3b57483f0b4dc2e6ecf922c584'),
  ('en.sahih', 71, 20, 5439, 'That you may follow therein roads of passage.'' "', NULL, NULL, '7d723f6e284f32cd6d2a8c321183f911992284d71a2ca4094bca3bed7db4f7cc'),
  ('en.sahih', 71, 21, 5440, 'Noah said, "My Lord, indeed they have disobeyed me and followed him whose wealth and children will not increase him except in loss.', NULL, NULL, '9813dd84e4c7207a2cc34497ecb2af59a76cdc4eb52ab17266313bc91cac223d'),
  ('en.sahih', 71, 22, 5441, 'And they conspired an immense conspiracy.', NULL, NULL, 'f589556d0906ee656e93797424c27e5549c0e00650dcb19b492e202ffe95537e'),
  ('en.sahih', 71, 23, 5442, 'And said, ''Never leave your gods and never leave Wadd or Suwa'' or Yaghuth and Ya''uq and Nasr.', NULL, NULL, '0d667d63760eb206166800e99fb199bd4ee998f280a1012fb871ff6b6b5c6fb4'),
  ('en.sahih', 71, 24, 5443, 'And already they have misled many. And, [my Lord], do not increase the wrongdoers except in error."', NULL, NULL, 'e656afd9486d8a102cb03157c2410e9cb896d4eff698fa08f83faff2d517a2e6'),
  ('en.sahih', 71, 25, 5444, 'Because of their sins they were drowned and put into the Fire, and they found not for themselves besides Allah [any] helpers.', NULL, NULL, '0f9c196e6e357810db06aa49f183868112972b3bea9b3dbe0dfaeb99aa64507f'),
  ('en.sahih', 71, 26, 5445, 'And Noah said, "My Lord, do not leave upon the earth from among the disbelievers an inhabitant.', NULL, NULL, 'd21a8b8066a0cf419fe139ef7bbd24ece53973427360db8f552ab0cec047893e'),
  ('en.sahih', 71, 27, 5446, 'Indeed, if You leave them, they will mislead Your servants and not beget except [every] wicked one and [confirmed] disbeliever.', NULL, NULL, 'fb0955fd1ea786a000035f6a958c62400009f1f719f92de97adbd361b8f28a80'),
  ('en.sahih', 71, 28, 5447, 'My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction."', NULL, NULL, '011ba77b3092bebd5e3f28e82f3c73ebd851a014f5282dc5fb55f6fbe6394b20'),
  ('en.sahih', 72, 1, 5448, 'Say, [O Muhammad], "It has been revealed to me that a group of the jinn listened and said, ''Indeed, we have heard an amazing Qur''an.', NULL, NULL, '6a1afdf0f1dcc85f9090d3b92841d93a6cfd857b78468f5e57e73b8111e15fa0'),
  ('en.sahih', 72, 2, 5449, 'It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone.', NULL, NULL, 'e45b4c6c3f62de15b8458c10dacfb52a30f4dfe8801d5c1203226ed3a07455cc'),
  ('en.sahih', 72, 3, 5450, 'And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son', NULL, NULL, '49a8aa1e0fb0f604dea1c288ab4c9fb932c26eb277f570fd988332abe3c3ede8'),
  ('en.sahih', 72, 4, 5451, 'And that our foolish one has been saying about Allah an excessive transgression.', NULL, NULL, '236ab4b3386f0c81354fa5f31f04258888430a8de21a8117fc691baa6bc3c363'),
  ('en.sahih', 72, 5, 5452, 'And we had thought that mankind and the jinn would never speak about Allah a lie.', NULL, NULL, '7c5157054e9c6bb6fdb3211ae6abdbb446fe539a9410ed8c9fc379a9e43b4f89'),
  ('en.sahih', 72, 6, 5453, 'And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden.', NULL, NULL, '070a51094db0ede63fb186b91f2a7fcadc0793762c062864fde8b6ea80d572b7'),
  ('en.sahih', 72, 7, 5454, 'And they had thought, as you thought, that Allah would never send anyone [as a messenger].', NULL, NULL, 'f8d30d8c28d2e7ce485577c138ab19a1750d8cb68879facf241782b4f48b5eaf'),
  ('en.sahih', 72, 8, 5455, 'And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames.', NULL, NULL, '20b0a30d26df1b6332f67a6ddd93e3a42647729558764167e0f9ad7df6ca62a1'),
  ('en.sahih', 72, 9, 5456, 'And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him.', NULL, NULL, '0bf95a50bb8eb48a43209f6a1354865fb6b4b05164912104cc8fb06f0b98e13e'),
  ('en.sahih', 72, 10, 5457, 'And we do not know [therefore] whether evil is intended for those on earth or whether their Lord intends for them a right course.', NULL, NULL, '9bf02df46c33b2b578d578031acb9348ec4a8808a98607852c511dbb84a9e995'),
  ('en.sahih', 72, 11, 5458, 'And among us are the righteous, and among us are [others] not so; we were [of] divided ways.', NULL, NULL, '322dbe28e747a6dfe7182e11f461e5346aed05b0b59e41daafa14e49d835961c'),
  ('en.sahih', 72, 12, 5459, 'And we have become certain that we will never cause failure to Allah upon earth, nor can we escape Him by flight.', NULL, NULL, '9c6bec13688a8d82033de386612581a74203d8f6187e13ba136aa24dffb0b878'),
  ('en.sahih', 72, 13, 5460, 'And when we heard the guidance, we believed in it. And whoever believes in his Lord will not fear deprivation or burden.', NULL, NULL, 'c463bf3ce1fb892b1640ccd488953939dc0a258b3623fcadd5e931c7f818b2f8'),
  ('en.sahih', 72, 14, 5461, 'And among us are Muslims [in submission to Allah], and among us are the unjust. And whoever has become Muslim - those have sought out the right course.', NULL, NULL, '32a829eca1aeb7c6c62e15d04a79e8a379cc8cc6525cfc4fc36671247a746407'),
  ('en.sahih', 72, 15, 5462, 'But as for the unjust, they will be, for Hell, firewood.''', NULL, NULL, '2d373460b5c97e61a19ed3588574bc5dd7559ecf67c0856644b18bb2f0d91b66'),
  ('en.sahih', 72, 16, 5463, 'And [Allah revealed] that if they had remained straight on the way, We would have given them abundant provision', NULL, NULL, '377aa7c3403d26f8f0843c581c99e72dd0093cb6ebcf1bfef9ce0d5c7d278438'),
  ('en.sahih', 72, 17, 5464, 'So We might test them therein. And whoever turns away from the remembrance of his Lord He will put into arduous punishment.', NULL, NULL, '26351508107f10e09e099f6b08a991d1b8b6a21bfce8aae049cf71d8bbb0cb13'),
  ('en.sahih', 72, 18, 5465, 'And [He revealed] that the masjids are for Allah, so do not invoke with Allah anyone.', NULL, NULL, '8a99f1b3d561a691fe03d6682375db2c71660d5671ebd4a91c04d9e28c168084'),
  ('en.sahih', 72, 19, 5466, 'And that when the Servant of Allah stood up supplicating Him, they almost became about him a compacted mass."', NULL, NULL, 'b41b3a0b416edc213c6d9215a0aae27434bd128090f49628e3de88323c05bbec'),
  ('en.sahih', 72, 20, 5467, 'Say, [O Muhammad], "I only invoke my Lord and do not associate with Him anyone."', NULL, NULL, 'd8794df353c94ac5bd2d53a9fa532c8588684563f97ca6792968f22ed9418c9a'),
  ('en.sahih', 72, 21, 5468, 'Say, "Indeed, I do not possess for you [the power of] harm or right direction."', NULL, NULL, '716faaf247b5810959ba461ea09f37cc99ebfc412017b9d40cf765faddb1d74a'),
  ('en.sahih', 72, 22, 5469, 'Say, "Indeed, there will never protect me from Allah anyone [if I should disobey], nor will I find in other than Him a refuge.', NULL, NULL, 'e599fa639c9f1804c6bed8805ba5ece52d23296cc64cd20e357e8282eef9589b'),
  ('en.sahih', 72, 23, 5470, 'But [I have for you] only notification from Allah, and His messages." And whoever disobeys Allah and His Messenger - then indeed, for him is the fire of Hell; they will abide therein forever.', NULL, NULL, '098250bf6220fef644a1db8b8c19f5a720d7f0c83fffef77493391781e24bf94'),
  ('en.sahih', 72, 24, 5471, '[The disbelievers continue] until, when they see that which they are promised, then they will know who is weaker in helpers and less in number.', NULL, NULL, '533772f3d18c3b0bf7c247ec723f522d9cef719092d880cf3c06b2820ab8774d'),
  ('en.sahih', 72, 25, 5472, 'Say, "I do not know if what you are promised is near or if my Lord will grant for it a [long] period."', NULL, NULL, 'ffc07a3d1b67e3403d753005f32cf87d3856bd3c364730c51598a3d7cceaec78'),
  ('en.sahih', 72, 26, 5473, '[He is] Knower of the unseen, and He does not disclose His [knowledge of the] unseen to anyone', NULL, NULL, 'c8563edb5929e1adc43652c919236eba8d95453dcead0c0fad80607b4857c845'),
  ('en.sahih', 72, 27, 5474, 'Except whom He has approved of messengers, and indeed, He sends before each messenger and behind him observers', NULL, NULL, '34218669c8db7941e1de1f1beacf103604d9ba7309ba755f38082aeeea8783c0'),
  ('en.sahih', 72, 28, 5475, 'That he may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number.', NULL, NULL, 'fce2ee9db0d38f5d8c2b79d039480cf904816555fe676071cc19d47727a3f8fd'),
  ('en.sahih', 73, 1, 5476, 'O you who wraps himself [in clothing],', NULL, NULL, 'fc0341c3b4cff343b826cb11a7e17c46486f0e316dd7c57d637aed0bf8584c6c'),
  ('en.sahih', 73, 2, 5477, 'Arise [to pray] the night, except for a little -', NULL, NULL, '52c427649c71d794dfe4a3afec694e41d52d600d0ff42947fb63fd52fe52630e'),
  ('en.sahih', 73, 3, 5478, 'Half of it - or subtract from it a little', NULL, NULL, 'e01453c460afb6c87cc33b9375f44751440d40f7b05dcfa3bbfca13d4c78d150'),
  ('en.sahih', 73, 4, 5479, 'Or add to it, and recite the Qur''an with measured recitation.', NULL, NULL, '6b71e1fcd3e2c89a140eb152db958a102e31de9f97d89b0194bd036d98b4f8c6'),
  ('en.sahih', 73, 5, 5480, 'Indeed, We will cast upon you a heavy word.', NULL, NULL, '91df5d32dd2ccafee8406d9f80c5b9a614bab3db8cdb6783cc92dd3daff948c5'),
  ('en.sahih', 73, 6, 5481, 'Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words.', NULL, NULL, '0a2af7768f0c95c26f8e1de1b623a382eac576fae5ec23bbb7cf0366442bea64'),
  ('en.sahih', 73, 7, 5482, 'Indeed, for you by day is prolonged occupation.', NULL, NULL, 'a9f5127dd3819bd410e447c02c0943b705d2718b15ceb178df7aad06141033ca'),
  ('en.sahih', 73, 8, 5483, 'And remember the name of your Lord and devote yourself to Him with [complete] devotion.', NULL, NULL, '30742a2a8ab33e5068f56a7e1d3205dd7cf06feeeb9ad8252ec82d0980fdef24'),
  ('en.sahih', 73, 9, 5484, '[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.', NULL, NULL, '0476156bd4cf9c0a1ee30cd979afd97f177f0183a70fa062aac5e3945a6cc8e5'),
  ('en.sahih', 73, 10, 5485, 'And be patient over what they say and avoid them with gracious avoidance.', NULL, NULL, '5a153b698a114a50a1f36d04cd6539099ed3d4b796fe94a98a542534b8406cfc'),
  ('en.sahih', 73, 11, 5486, 'And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.', NULL, NULL, '22270469571bb89b66d00fdf39fe6a4cbc4c4007653f2577f2eef2b81cd291b6'),
  ('en.sahih', 73, 12, 5487, 'Indeed, with Us [for them] are shackles and burning fire', NULL, NULL, '495ffe0e814ed08e5475c878b33046cd9877777f800096b21df77c05a049a166'),
  ('en.sahih', 73, 13, 5488, 'And food that chokes and a painful punishment -', NULL, NULL, 'f516580e0e995978463b1ecec792e698a1f115dbd04478bb42e70e9ed4ee1b9c'),
  ('en.sahih', 73, 14, 5489, 'On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down.', NULL, NULL, '1eca30c9ea5e0a484cf63174070c0eaeff8713f0d499cad34d065f9bdc03ed5b'),
  ('en.sahih', 73, 15, 5490, 'Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger.', NULL, NULL, 'cbd525e96c64dab114813f9d51b51d9744a55ae3a44955c4ea51f639fae1d37c'),
  ('en.sahih', 73, 16, 5491, 'But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure.', NULL, NULL, '66e073a32c91630eafd4261191b7a04ea5d29508bad0a9ebc011e9d8dfce1703'),
  ('en.sahih', 73, 17, 5492, 'Then how can you fear, if you disbelieve, a Day that will make the children white- haired?', NULL, NULL, '6b6c72dd90a651304416e1d02848f183cb160fcf18e437d5e1723b0f94d1bbe5'),
  ('en.sahih', 73, 18, 5493, 'The heaven will break apart therefrom; ever is His promise fulfilled.', NULL, NULL, '97ba48653d1ae8dd4511f667ca51549681ec76d73851f953cdfaaea588fb8d96'),
  ('en.sahih', 73, 19, 5494, 'Indeed, this is a reminder, so whoever wills may take to his Lord a way.', NULL, NULL, 'e1e4db3e0674ad160a1f24692c6154c284e8e09f095e2bc8ded0111da9253e22'),
  ('en.sahih', 73, 20, 5495, 'Indeed, your Lord knows, [O Muhammad], that you stand [in prayer] almost two thirds of the night or half of it or a third of it, and [so do] a group of those with you. And Allah determines [the extent of] the night and the day. He has known that you [Muslims] will not be able to do it and has turned to you in forgiveness, so recite what is easy [for you] of the Qur''an. He has known that there will be among you those who are ill and others traveling throughout the land seeking [something] of the bounty of Allah and others fighting for the cause of Allah. So recite what is easy from it and establish prayer and give zakah and loan Allah a goodly loan. And whatever good you put forward for yourselves - you will find it with Allah. It is better and greater in reward. And seek forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.', NULL, NULL, 'cdb91dc0b985e1eafc079361934eed76cc905a903568972c66134195b5a61246'),
  ('en.sahih', 74, 1, 5496, 'O you who covers himself [with a garment],', NULL, NULL, '9cdf40ec55b88d9170e26a9c797e0845217b79b72014329fef8b22ea31dba39d'),
  ('en.sahih', 74, 2, 5497, 'Arise and warn', NULL, NULL, '5fff5305e3c938dee38e21093134671131c2df240b54b35dc63a76a2b1f5c1d8'),
  ('en.sahih', 74, 3, 5498, 'And your Lord glorify', NULL, NULL, 'c7b9f1df2987144e043d6ee434080428ea5ad50eb0c479af357e413e70988f49'),
  ('en.sahih', 74, 4, 5499, 'And your clothing purify', NULL, NULL, '82e28c9046324002446d361ddcb5a9fb1c405138ef703ecdd1b7279b0c9ad50a'),
  ('en.sahih', 74, 5, 5500, 'And uncleanliness avoid', NULL, NULL, 'f19b80465edafa9ddc686623f2a1793fa8690df669431a05e67d03781f6ee613')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 74, 6, 5501, 'And do not confer favor to acquire more', NULL, NULL, 'fc6b65733c6bbd29f3ed09f69460d62d68929b18cf750fdbc12202f8a7bda79d'),
  ('en.sahih', 74, 7, 5502, 'But for your Lord be patient.', NULL, NULL, '39ff37444d9f09538ae9edca9d233662b5037d2f59319d9088c3a190d6e6f16e'),
  ('en.sahih', 74, 8, 5503, 'And when the trumpet is blown,', NULL, NULL, 'fce5ec7f8059b64c9b2eab13bfcc483a97f56c497166b2155e87a3dc2d982e35'),
  ('en.sahih', 74, 9, 5504, 'That Day will be a difficult day', NULL, NULL, '0c63801823eee2b879e341716a9583965dde282f736f29b2765c5514b05a8b44'),
  ('en.sahih', 74, 10, 5505, 'For the disbelievers - not easy.', NULL, NULL, '5716c82ab7a33d3b6991f5f0176ab371ee4cbb5543c4d1804afe48e7f3b49d77'),
  ('en.sahih', 74, 11, 5506, 'Leave Me with the one I created alone', NULL, NULL, 'd5a219f77e395048498285b0f1096de324ec2265162280858f60f746edbf105e'),
  ('en.sahih', 74, 12, 5507, 'And to whom I granted extensive wealth', NULL, NULL, '064f853981141659df9b8568b4d7e0c9317293aba4621bc9eea8f28de4e66ede'),
  ('en.sahih', 74, 13, 5508, 'And children present [with him]', NULL, NULL, '33ab848b16df587f5f83d6d64a8b89f1b6d2ef4e73b4a386cdaf89035cd8d7cd'),
  ('en.sahih', 74, 14, 5509, 'And spread [everything] before him, easing [his life].', NULL, NULL, '2871d1f1e86286d6894f9e402b600118305a7f4056dcb623a2db36602061f51e'),
  ('en.sahih', 74, 15, 5510, 'Then he desires that I should add more.', NULL, NULL, '9cad10bdfe356d77a072a1f8116ad63f6809a80447b702150f24810770d93b6b'),
  ('en.sahih', 74, 16, 5511, 'No! Indeed, he has been toward Our verses obstinate.', NULL, NULL, 'd9ca03d1a23c8d9377abe40c1ceaff54df6a3b134fe588ce56c5d517da2deebf'),
  ('en.sahih', 74, 17, 5512, 'I will cover him with arduous torment.', NULL, NULL, '6e94b5d48032d437e56d53e195dd19153e9b8c76deec306f273846405fab1a9d'),
  ('en.sahih', 74, 18, 5513, 'Indeed, he thought and deliberated.', NULL, NULL, '000dbf4280ca8bb49aa0400fccb118389593ae449e1a89fc612528397313c0a6'),
  ('en.sahih', 74, 19, 5514, 'So may he be destroyed [for] how he deliberated.', NULL, NULL, 'd533ad5737941db1cc9e1f48a504cc673301c97b742598df6e0a9a9aaa3ba9d3'),
  ('en.sahih', 74, 20, 5515, 'Then may he be destroyed [for] how he deliberated.', NULL, NULL, 'acb19ad39daeb00043b8b75383855a5d711512223e226e273c6a3cfe3bc888f5'),
  ('en.sahih', 74, 21, 5516, 'Then he considered [again];', NULL, NULL, '95e6c448574f18d94c9cb082a76199c87b0bdd41012410f892b445037f8a8139'),
  ('en.sahih', 74, 22, 5517, 'Then he frowned and scowled;', NULL, NULL, '651b21c9d82b371ef61be86e620ccf5896badc48255cea8c7d380ef911b3781a'),
  ('en.sahih', 74, 23, 5518, 'Then he turned back and was arrogant', NULL, NULL, '233fba0aab3e4257a614da789991f7d94b71cd14196e05e21b1a76fc2b9b9346'),
  ('en.sahih', 74, 24, 5519, 'And said, "This is not but magic imitated [from others].', NULL, NULL, '08f7c7764a570c371aa5ff976656c1686e6c0cf0cb3404772fd65eefa70945d2'),
  ('en.sahih', 74, 25, 5520, 'This is not but the word of a human being."', NULL, NULL, '9916b4dded72620bbe9128a7b5f652fb18e866061cbf092b45c4d3a105de2883'),
  ('en.sahih', 74, 26, 5521, 'I will drive him into Saqar.', NULL, NULL, '5e5480ae2a338479f958513b259a35babe58f2673c06f68891caa305a334c25c'),
  ('en.sahih', 74, 27, 5522, 'And what can make you know what is Saqar?', NULL, NULL, 'efd871a11ff3846938aa589150259d25867414c99cd7b113860a96e6f4523103'),
  ('en.sahih', 74, 28, 5523, 'It lets nothing remain and leaves nothing [unburned],', NULL, NULL, '47b017d91791be0fc2156405cd26c8408b4c01a7a1c4f982895404a41b2f55d9'),
  ('en.sahih', 74, 29, 5524, 'Blackening the skins.', NULL, NULL, 'b31fc43bae1dd50fbe7d8a0be143c2208fc88f287418e6702827421169952065'),
  ('en.sahih', 74, 30, 5525, 'Over it are nineteen [angels].', NULL, NULL, 'bc894efa7bf94aa36012b662c0f6172fe295737cd1041853b45b389eb8272df4'),
  ('en.sahih', 74, 31, 5526, 'And We have not made the keepers of the Fire except angels. And We have not made their number except as a trial for those who disbelieve - that those who were given the Scripture will be convinced and those who have believed will increase in faith and those who were given the Scripture and the believers will not doubt and that those in whose hearts is hypocrisy and the disbelievers will say, "What does Allah intend by this as an example?" Thus does Allah leave astray whom He wills and guides whom He wills. And none knows the soldiers of your Lord except Him. And mention of the Fire is not but a reminder to humanity.', NULL, NULL, '7be161d379da79f81b015ffd279b157a94c310b233373c2784c79000cb2b5857'),
  ('en.sahih', 74, 32, 5527, 'No! By the moon', NULL, NULL, '1b10151c2275e1d6285be16db94bc67b96754fa1b449755563a87f2bc25c593b'),
  ('en.sahih', 74, 33, 5528, 'And [by] the night when it departs', NULL, NULL, '92562ad4d335e4a1b753a92769287c43055e6d4ddfdc93f5df0e09c478664925'),
  ('en.sahih', 74, 34, 5529, 'And [by] the morning when it brightens,', NULL, NULL, '8a65fd982dec0f775c2607ba3eec30ae6e74a4fb106e30fc2972e9b72a52baa0'),
  ('en.sahih', 74, 35, 5530, 'Indeed, the Fire is of the greatest [afflictions]', NULL, NULL, '1ef741a205f449860ecd1db27f798fc55e21d757cc4944b0c2317cc72abf4737'),
  ('en.sahih', 74, 36, 5531, 'As a warning to humanity -', NULL, NULL, 'e5d6342d707f4ddd583397baef8538f9acc57319b050a53ac131c38666340929'),
  ('en.sahih', 74, 37, 5532, 'To whoever wills among you to proceed or stay behind.', NULL, NULL, '8f6d84f1a9bebc6c6c1e5d542b8371c5e42abca9813b7c9bc0869ee72c5f4461'),
  ('en.sahih', 74, 38, 5533, 'Every soul, for what it has earned, will be retained', NULL, NULL, '8e2aa99400ed07b3f322fb69ace1fb88eacd564636a0f964d55cb854d4849ff7'),
  ('en.sahih', 74, 39, 5534, 'Except the companions of the right,', NULL, NULL, '59b937630e5e56a90bdd6e51f3fea118baef35fc9ad956515e9b1f2be93012ec'),
  ('en.sahih', 74, 40, 5535, '[Who will be] in gardens, questioning each other', NULL, NULL, 'b7c5d6ca102c7cb0577aad8de4e41e19e6ddb31b61662823f894e237947da2fd'),
  ('en.sahih', 74, 41, 5536, 'About the criminals,', NULL, NULL, '8013fb10f4f384a77af08d8911f2a4997cf3689ef53183f8f987c90d9bc6e94b'),
  ('en.sahih', 74, 42, 5537, '[And asking them], "What put you into Saqar?"', NULL, NULL, '634072a1a775aa7807c95a0f07e7fc318e8582e3fd6e8a26961ce2d64b5e0bde'),
  ('en.sahih', 74, 43, 5538, 'They will say, "We were not of those who prayed,', NULL, NULL, '850f5663eb3f782f6484add6041402b63278f69045f54cceabbbf92dfd78d314'),
  ('en.sahih', 74, 44, 5539, 'Nor did we used to feed the poor.', NULL, NULL, '829c657cbe28bda26747621a2b853a6e8a526c9e46f71a59954178abe7ca7e13'),
  ('en.sahih', 74, 45, 5540, 'And we used to enter into vain discourse with those who engaged [in it],', NULL, NULL, 'c71d4e51249dac33d32f751e0300d6d248821dd5f22a791f98c148f1d0ce44c9'),
  ('en.sahih', 74, 46, 5541, 'And we used to deny the Day of Recompense', NULL, NULL, '83ef6b7979470c0c783c8e6576c3dc8d8d94e53bb28b6132925fba70a2b31495'),
  ('en.sahih', 74, 47, 5542, 'Until there came to us the certainty."', NULL, NULL, '07761914458d4887048fbb829871f9693c9929a64d1e9f33b84ad9c60c3c3325'),
  ('en.sahih', 74, 48, 5543, 'So there will not benefit them the intercession of [any] intercessors.', NULL, NULL, '599f69539f251e7a4a668999b5b96309a650832e6c18f9c5cd639af481c6c1b2'),
  ('en.sahih', 74, 49, 5544, 'Then what is [the matter] with them that they are, from the reminder, turning away', NULL, NULL, '05c3b0d52e2399e80687b512a2c3ee21ec739a9d81fa37e4becd7e23d3e93552'),
  ('en.sahih', 74, 50, 5545, 'As if they were alarmed donkeys', NULL, NULL, 'f512a5b75034071401ea48dce6e6c40d879c3272d41efc50222fbb2e8ad90193'),
  ('en.sahih', 74, 51, 5546, 'Fleeing from a lion?', NULL, NULL, '212d75135c87ffbd0a9b7e24e72b80dbfb29bf413e39150783463abca91abcf7'),
  ('en.sahih', 74, 52, 5547, 'Rather, every person among them desires that he would be given scriptures spread about.', NULL, NULL, '446d5e6deb5b2661eec3e197bf79c6278807afa3375d7a46d715e98ebfa16dac'),
  ('en.sahih', 74, 53, 5548, 'No! But they do not fear the Hereafter.', NULL, NULL, '62928b6c65da6476396e24058af599140ea5b33ceb6436828b6a5df44dc12bc9'),
  ('en.sahih', 74, 54, 5549, 'No! Indeed, the Qur''an is a reminder', NULL, NULL, 'b680525193310d9eeac681c3094b76313f972e28ca35f2dcf3899d8c3adf25d7'),
  ('en.sahih', 74, 55, 5550, 'Then whoever wills will remember it.', NULL, NULL, 'a7142275f63dbbf4993a84c9f41d87133efbd5e92ebd65157ed588a9f112e43e'),
  ('en.sahih', 74, 56, 5551, 'And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness.', NULL, NULL, '498d456edf1035a3906dc57fd0c6b1cd1ae2481eed94fee9095305f30d68e870'),
  ('en.sahih', 75, 1, 5552, 'I swear by the Day of Resurrection', NULL, NULL, 'acaf2227f520bc7de93943b55a9f51c1bf7ff6d31206491ccef0c8d45e230a0c'),
  ('en.sahih', 75, 2, 5553, 'And I swear by the reproaching soul [to the certainty of resurrection].', NULL, NULL, '42230ba6022882b54b88644cee6b962fd5f5b92e4318fd7083f6e38a1dd06491'),
  ('en.sahih', 75, 3, 5554, 'Does man think that We will not assemble his bones?', NULL, NULL, '94e5175426bb2d9bf81cefcbd7fd9314075e56214bcd1fcf59529c2fa9cad621'),
  ('en.sahih', 75, 4, 5555, 'Yes. [We are] Able [even] to proportion his fingertips.', NULL, NULL, 'b53d885d557b672391f423e0fdb9c81ea660ce71f97c17ab3f42d7a7f34e39a2'),
  ('en.sahih', 75, 5, 5556, 'But man desires to continue in sin.', NULL, NULL, '4f03d33950c0a8626f53260a68ac54780b34d6dc4cf54a3a12ff1592aa34b1f7'),
  ('en.sahih', 75, 6, 5557, 'He asks, "When is the Day of Resurrection?"', NULL, NULL, '2113bd8d756e00887f23539e0fa9553b29653e27db564f706b4fec675e670d29'),
  ('en.sahih', 75, 7, 5558, 'So when vision is dazzled', NULL, NULL, '445d6fdadba1158149ff30a365d71792b7f8c960c5a5b6694014a7207e512160'),
  ('en.sahih', 75, 8, 5559, 'And the moon darkens', NULL, NULL, 'e7247993fe4012bb4788f3111dd46a0964f35a5f59e83ecbf4bf84b0633a20f4'),
  ('en.sahih', 75, 9, 5560, 'And the sun and the moon are joined,', NULL, NULL, '8ce4561895fbcd0e2dc90d930412502e39b5dae95b4ab6601fa969abe9d85d71'),
  ('en.sahih', 75, 10, 5561, 'Man will say on that Day, "Where is the [place of] escape?"', NULL, NULL, '474e32c1ccf5819ab4f120cc74be2b3639937c57880ffcf6d1ce7cb0f3aeb1f3'),
  ('en.sahih', 75, 11, 5562, 'No! There is no refuge.', NULL, NULL, '67687d09fe8eb4675d69f93e457f8f0bc6ab56d35af40fcd28eb6cbb7a2327fc'),
  ('en.sahih', 75, 12, 5563, 'To your Lord, that Day, is the [place of] permanence.', NULL, NULL, '297d730840a336420aee2c7058888928f77424276e5b1b3bf00cbcc766901b4d'),
  ('en.sahih', 75, 13, 5564, 'Man will be informed that Day of what he sent ahead and kept back.', NULL, NULL, '57308317b941845ef270e46365450aad8697347b562b2150765228503209c104'),
  ('en.sahih', 75, 14, 5565, 'Rather, man, against himself, will be a witness,', NULL, NULL, 'ce5b9b3c9649bca91a647f68b9bc9ef26690881ded6157496160d7e1c3f43dc1'),
  ('en.sahih', 75, 15, 5566, 'Even if he presents his excuses.', NULL, NULL, 'f64ad0676b102eca97e0b779ba77f65792a686e2ea2e3ad8bb52b14c8de76c01'),
  ('en.sahih', 75, 16, 5567, 'Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur''an.', NULL, NULL, '6f5035a288bd14947b346734ecbaaef8d3467beb13ff7d994b4bf2f805f150f2'),
  ('en.sahih', 75, 17, 5568, 'Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.', NULL, NULL, 'bed0c3e15f1cbf9b0eaac49f68926061e3226b151d31b718a9c6e87e1291b4a3'),
  ('en.sahih', 75, 18, 5569, 'So when We have recited it [through Gabriel], then follow its recitation.', NULL, NULL, '93a750064881429d5ed318ca5ca324d091bb082a9c51cb397dbadeef6d4367b2'),
  ('en.sahih', 75, 19, 5570, 'Then upon Us is its clarification [to you].', NULL, NULL, '496b3dcf0d16bd8747a56fef15be6a8f8aa0c2338d1eb9804e1e3e7884bebc09'),
  ('en.sahih', 75, 20, 5571, 'No! But you love the immediate', NULL, NULL, '7e54daecde5a585ea5d93f5fd80db23065198e7c0fc42956fc43078238e3efaf'),
  ('en.sahih', 75, 21, 5572, 'And leave the Hereafter.', NULL, NULL, 'a12243a3ed488fe86637a1d12df2d7a2dbcda249c0c20afe8a3973d1e13ccb57'),
  ('en.sahih', 75, 22, 5573, '[Some] faces, that Day, will be radiant,', NULL, NULL, '49703bccf9104430bcc6ca4813f0f42f5d103c7e08f231d69bc15744632f47df'),
  ('en.sahih', 75, 23, 5574, 'Looking at their Lord.', NULL, NULL, 'b1baec18237086b68ad1be7db099f41798241aecf7259cdf962a5391139fce5f'),
  ('en.sahih', 75, 24, 5575, 'And [some] faces, that Day, will be contorted,', NULL, NULL, '6fb4ccdb6a1f0bfaff66c8365564bd807437922fb7024bb53f97c7cc6b83dd98'),
  ('en.sahih', 75, 25, 5576, 'Expecting that there will be done to them [something] backbreaking.', NULL, NULL, '447469a3c607d74b3ff68bcd65b805ccba7f4702b26a984ae8de9a8ae39b976b'),
  ('en.sahih', 75, 26, 5577, 'No! When the soul has reached the collar bones', NULL, NULL, 'a15869418c111c99a047a5b343a4aa886927a81f233c7805cccacf9fce30d05a'),
  ('en.sahih', 75, 27, 5578, 'And it is said, "Who will cure [him]?"', NULL, NULL, '0faecf849690a4a922c1bf52168446871a8e22aef3553d8f07cb281c40ccd8bc'),
  ('en.sahih', 75, 28, 5579, 'And the dying one is certain that it is the [time of] separation', NULL, NULL, '145678b049dd4305bccd0dd334bdbcbfaee59747d544d7d7b595fabdcdcc33a3'),
  ('en.sahih', 75, 29, 5580, 'And the leg is wound about the leg,', NULL, NULL, 'f04238f239428decb3056eeb15235f391897cf64d8d2025eb393a03dbe5543f8'),
  ('en.sahih', 75, 30, 5581, 'To your Lord, that Day, will be the procession.', NULL, NULL, '3d7323ab63c3b261240be8eda7e5e6540197b3f3453c52d7b38e312e4c6aba07'),
  ('en.sahih', 75, 31, 5582, 'And the disbeliever had not believed, nor had he prayed.', NULL, NULL, 'bda069324a2b545159a0a54be047a0b5929caf2b27623649d0950ab8386cac07'),
  ('en.sahih', 75, 32, 5583, 'But [instead], he denied and turned away.', NULL, NULL, '2bbc50d1fe4cfe59b33423cb2ad5894273168380bc537416e18c7aa15d7ccf43'),
  ('en.sahih', 75, 33, 5584, 'And then he went to his people, swaggering [in pride].', NULL, NULL, '17ffb1c33700511e5e719b9249d7b1a0b6696de07f24bff34826eee6da17d1d0'),
  ('en.sahih', 75, 34, 5585, 'Woe to you, and woe!', NULL, NULL, '307d2ae5651604564877e9b06d06c4612eea08a83cf042fc19be167de4009760'),
  ('en.sahih', 75, 35, 5586, 'Then woe to you, and woe!', NULL, NULL, '3a66abab747256d26d0d48529cce05d659f8b84c70127a53524c29eab909a5cc'),
  ('en.sahih', 75, 36, 5587, 'Does man think that he will be left neglected?', NULL, NULL, '6d739f1a048385332ad016e760b5b58db74abd770dd958a877c4ce7c908c05a7'),
  ('en.sahih', 75, 37, 5588, 'Had he not been a sperm from semen emitted?', NULL, NULL, '4a22cf11e633b96d370cc74882b782b7499e6ec20b0936b4a4ea73379eda86ff'),
  ('en.sahih', 75, 38, 5589, 'Then he was a clinging clot, and [Allah] created [his form] and proportioned [him]', NULL, NULL, '3d3650d5bf740cd9fd49f1bc46f21cd8e8ff84253c26c504676aa83ebdb3f769'),
  ('en.sahih', 75, 39, 5590, 'And made of him two mates, the male and the female.', NULL, NULL, '60fcae67786cd7e280bb8594bc2939c61d65188e59602f595b4b60f39e633473'),
  ('en.sahih', 75, 40, 5591, 'Is not that [Creator] Able to give life to the dead?', NULL, NULL, 'f85be0da1b078a003a89c478f87f23589d0e9ea0c71fab6e598a13122c79e2f8'),
  ('en.sahih', 76, 1, 5592, 'Has there [not] come upon man a period of time when he was not a thing [even] mentioned?', NULL, NULL, '52d48c29009c14df06643bd2150992931cd4fdbf13d64a2f3e11999ca462feb9'),
  ('en.sahih', 76, 2, 5593, 'Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing.', NULL, NULL, '885905e3fe042cdcf19606d44f5e719ac6c2be1f876f4faac6339680c454d096'),
  ('en.sahih', 76, 3, 5594, 'Indeed, We guided him to the way, be he grateful or be he ungrateful.', NULL, NULL, 'ae2f7aa89ae28a87b5b34e7b94930edcddd0151635a89a09726db55b4b8ea062'),
  ('en.sahih', 76, 4, 5595, 'Indeed, We have prepared for the disbelievers chains and shackles and a blaze.', NULL, NULL, '9d174a4fe7f7ccd52d2579f5a94f860db3fa71c209ba31cdd668a291c860e351'),
  ('en.sahih', 76, 5, 5596, 'Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur,', NULL, NULL, '4df1d7b7e852e118b4195a3e1a251f214a4e930d72b6ee822824ba02c22271ac'),
  ('en.sahih', 76, 6, 5597, 'A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance].', NULL, NULL, '96507b2a484777722b6e5397e3d2213800a098866a8fd7d075a0855a1c05b718'),
  ('en.sahih', 76, 7, 5598, 'They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread.', NULL, NULL, 'a6805f55e428249ff8b65911ce6c349bdd23391fab554b5b147e4fe0ca558988'),
  ('en.sahih', 76, 8, 5599, 'And they give food in spite of love for it to the needy, the orphan, and the captive,', NULL, NULL, '2161ccc98e9627f58cb0887743c1cf30c8caf818d6cd1b3b7794f485e289c659'),
  ('en.sahih', 76, 9, 5600, '[Saying], "We feed you only for the countenance of Allah. We wish not from you reward or gratitude.', NULL, NULL, 'c3825c55abe3d62c2e1ad8673d59dd9f46d0ef62fd6664f6c7b5c14c969c975b')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 76, 10, 5601, 'Indeed, We fear from our Lord a Day austere and distressful."', NULL, NULL, 'f221b3ce875217012064020b2e4f1c143e9a89fc263b05c939d23f2a90de30df'),
  ('en.sahih', 76, 11, 5602, 'So Allah will protect them from the evil of that Day and give them radiance and happiness', NULL, NULL, '7052971c69292e49d4c48d2afc5e85ef09b126182d748696706bab7a2180e708'),
  ('en.sahih', 76, 12, 5603, 'And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].', NULL, NULL, '9306487825efc6add7ccdd4e0194b06717474754b583678320a5c486e7bd01e8'),
  ('en.sahih', 76, 13, 5604, '[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold.', NULL, NULL, '881ceb151296989cf5c2c0b81f86d8dc03d47e5b6b3e5531213f76531931f67f'),
  ('en.sahih', 76, 14, 5605, 'And near above them are its shades, and its [fruit] to be picked will be lowered in compliance.', NULL, NULL, 'daad9cb83b50cc3ae4a4f7a54470446215366c0eaa348b0fde5b7fd16284c152'),
  ('en.sahih', 76, 15, 5606, 'And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],', NULL, NULL, '82cb279c0c9a37ba5f44a2c2b6ca679194527b2118348538cab93d1885d3e8ff'),
  ('en.sahih', 76, 16, 5607, 'Clear glasses [made] from silver of which they have determined the measure.', NULL, NULL, 'cfa9e629447945009464bea381fe5b30e8a74f7e4a4725e5f35c3ee06e469207'),
  ('en.sahih', 76, 17, 5608, 'And they will be given to drink a cup [of wine] whose mixture is of ginger', NULL, NULL, '47bccd8a34d7ed6ab67726785336903bf060ac4a1b8d85b2acb7db00a154e374'),
  ('en.sahih', 76, 18, 5609, '[From] a fountain within Paradise named Salsabeel.', NULL, NULL, '879dd3a0087adc88ad8d74f100ee007214c57b83f1c5e1fe50af8efe334298ae'),
  ('en.sahih', 76, 19, 5610, 'There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls.', NULL, NULL, '33349a03aad9ef72084ee1702f9e5d66f3c4f785f0ee42d5a23ff13a8ceb06b8'),
  ('en.sahih', 76, 20, 5611, 'And when you look there [in Paradise], you will see pleasure and great dominion.', NULL, NULL, '66fe5f697b7a9107b34111553efc19db91e572bbe533e033d3fce927da4d0de1'),
  ('en.sahih', 76, 21, 5612, 'Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink.', NULL, NULL, '26d99e35de2dea46f7b62169b8dde403c220afb8b25cdf8b091e9791042ba331'),
  ('en.sahih', 76, 22, 5613, '[And it will be said], "Indeed, this is for you a reward, and your effort has been appreciated."', NULL, NULL, '858ed20ba394f2e3d37cf5427d912896946755f2e652543b4bd3d248f91829d8'),
  ('en.sahih', 76, 23, 5614, 'Indeed, it is We who have sent down to you, [O Muhammad], the Qur''an progressively.', NULL, NULL, '451449b202c53607bb56c0fa9c68c18772f721759b2e4c32b5fe3b37521f18be'),
  ('en.sahih', 76, 24, 5615, 'So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever].', NULL, NULL, '4feee349cf56cb221d5d328fd7ecbcbd3f7ecb0f857348a962075a4fd242cb4d'),
  ('en.sahih', 76, 25, 5616, 'And mention the name of your Lord [in prayer] morning and evening', NULL, NULL, 'fd703d445248892a10e5712fcf43cfa41a78c270c5485861a771d9d02cb0f9bd'),
  ('en.sahih', 76, 26, 5617, 'And during the night prostrate to Him and exalt Him a long [part of the] night.', NULL, NULL, '785805c1532e5c4f28bd7223dea39869f671ece08aeadc1ae920f9e60ecc28e4'),
  ('en.sahih', 76, 27, 5618, 'Indeed, these [disbelievers] love the immediate and leave behind them a grave Day.', NULL, NULL, 'd6a0ca2ba0541ef24a603f7946daac55430066fe089e2361088f4c1d7f9c8068'),
  ('en.sahih', 76, 28, 5619, 'We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration.', NULL, NULL, 'fb1857be447e66280906d58c5154420ab49d6e5d4e5d0d7a3dba808f284e34da'),
  ('en.sahih', 76, 29, 5620, 'Indeed, this is a reminder, so he who wills may take to his Lord a way.', NULL, NULL, 'ac1a510c719b5a3e143a728b460f872c444b4a6a2d78bfbd9227dbf41d1b09a5'),
  ('en.sahih', 76, 30, 5621, 'And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, '2a2dcf2f202626be6f55399b41bc28cf8d28102f46c03d3755ab7a71dc2876fe'),
  ('en.sahih', 76, 31, 5622, 'He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment.', NULL, NULL, '0babc7d19ed9362e5352556efcc2ae1b8e723a8507da593f8d9be5a35a330537'),
  ('en.sahih', 77, 1, 5623, 'By those [winds] sent forth in gusts', NULL, NULL, '536e43b9e75882e5442561d2b3949320d5484eca593216d0b221a745a339071c'),
  ('en.sahih', 77, 2, 5624, 'And the winds that blow violently', NULL, NULL, '66c6242adc78181a5cd16d092ee40b666624f9b532cdd6aa21ca521773fcc9a6'),
  ('en.sahih', 77, 3, 5625, 'And [by] the winds that spread [clouds]', NULL, NULL, '40028065faa51edd3e7fe074cfb64b71a207d084fcba9ac3d96ba244f2f8f908'),
  ('en.sahih', 77, 4, 5626, 'And those [angels] who bring criterion', NULL, NULL, 'b1847829d8a76b4cd3d435a25d02295681b05ab1d1556a8de29debaa97200be1'),
  ('en.sahih', 77, 5, 5627, 'And those [angels] who deliver a message', NULL, NULL, '060390a804856e95fbe3c90fca7d21054e6da973f2aa5ac87b25e78661bd12f7'),
  ('en.sahih', 77, 6, 5628, 'As justification or warning,', NULL, NULL, '9efb118f17e4885e7267bc85acc95e788b82e6edea278d32a00bff80869c3d69'),
  ('en.sahih', 77, 7, 5629, 'Indeed, what you are promised is to occur.', NULL, NULL, '1f10897bbf9d1a1946ae430efa7ba986e943403d2de3cc5233b965b034a83011'),
  ('en.sahih', 77, 8, 5630, 'So when the stars are obliterated', NULL, NULL, '12b6075e80395056d81a312e414b9e65e18e6d8bbe0d75c7c4d446933be2e571'),
  ('en.sahih', 77, 9, 5631, 'And when the heaven is opened', NULL, NULL, '664a6ee46346a09a5af5a3e099837c91bc25d9cc7cb96640632588f81f9112e9'),
  ('en.sahih', 77, 10, 5632, 'And when the mountains are blown away', NULL, NULL, 'a458f28a95639a9ce12f8ace523d413cdea5fea23a4e0bb52f17ecf04f83730f'),
  ('en.sahih', 77, 11, 5633, 'And when the messengers'' time has come...', NULL, NULL, '98ce2dfa2ba2e1ddd4b47be91737d32b362867c312621048df7c04c9d1220d57'),
  ('en.sahih', 77, 12, 5634, 'For what Day was it postponed?', NULL, NULL, '214dbbe92b067fd73999e824705cf5156191e223cfad0e1b9be18ec69a831d46'),
  ('en.sahih', 77, 13, 5635, 'For the Day of Judgement.', NULL, NULL, 'ad54f067a8404562fd1ce7aaf399ed3224750854f908318cd419927f2d4f37bc'),
  ('en.sahih', 77, 14, 5636, 'And what can make you know what is the Day of Judgement?', NULL, NULL, '2a8aefb16eb7cfd0f04b0a9fef6ec5a1d1407cb43bb80aab08d0a9b53b7ca4fa'),
  ('en.sahih', 77, 15, 5637, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 16, 5638, 'Did We not destroy the former peoples?', NULL, NULL, 'de73572875984e705a7d282afee0815e62d7cca040d1ba4ea9bdbbc25529d577'),
  ('en.sahih', 77, 17, 5639, 'Then We will follow them with the later ones.', NULL, NULL, 'a6ae22ad4f4a0e30282487516590bf5f79e948fe4c4ae7769b04b06c9d6761e4'),
  ('en.sahih', 77, 18, 5640, 'Thus do We deal with the criminals.', NULL, NULL, '34f157ad032b5fd9ff8ea3575a60f060deea00fb71da376243a89af9ef5f9182'),
  ('en.sahih', 77, 19, 5641, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 20, 5642, 'Did We not create you from a liquid disdained?', NULL, NULL, 'aa4db712f073d02e704234a568f29cc960be0d1ba6325ab50b9d7df48e3cca2b'),
  ('en.sahih', 77, 21, 5643, 'And We placed it in a firm lodging', NULL, NULL, '353e296e2cca5919ccbbc2a21b32c09d14169abe63af779baaf4fa73c7de7022'),
  ('en.sahih', 77, 22, 5644, 'For a known extent.', NULL, NULL, 'f0731d06e66b3f3bd73ce08775d22b180fedcff61d4dbd40dfe178df84c843d6'),
  ('en.sahih', 77, 23, 5645, 'And We determined [it], and excellent [are We] to determine.', NULL, NULL, 'f7b6a537d24d62a89209b558bf2ed7ae816bffb8485a6e81b493b8556d0aed39'),
  ('en.sahih', 77, 24, 5646, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 25, 5647, 'Have We not made the earth a container', NULL, NULL, 'e1d41b305df9cce21aca1766b9c7d1d655dd3d76d535ba88b3142d94ea9be3cf'),
  ('en.sahih', 77, 26, 5648, 'Of the living and the dead?', NULL, NULL, 'f828514f9aada3cff3af59250f3b5bc1a7df51c34cf7ce2a0ddfc42d8d8dd9a3'),
  ('en.sahih', 77, 27, 5649, 'And We placed therein lofty, firmly set mountains and have given you to drink sweet water.', NULL, NULL, 'fdec0509fb80118496e42b3b20728e35717fca3d1db79ba189f1369e6bceeeb8'),
  ('en.sahih', 77, 28, 5650, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 29, 5651, '[They will be told], "Proceed to that which you used to deny.', NULL, NULL, '50a1529b06d252db98566ead7d4579abe27bec41573a7285d686816ab5658222'),
  ('en.sahih', 77, 30, 5652, 'Proceed to a shadow [of smoke] having three columns', NULL, NULL, '182260b99e4a2e346746f4279774ab3a58750db8a8c8c7cb805fc1a0736d9730'),
  ('en.sahih', 77, 31, 5653, '[But having] no cool shade and availing not against the flame."', NULL, NULL, 'c32b984e7a4f50df08a6607e45814dd4a55c4e92b2c688809412015c073d121a'),
  ('en.sahih', 77, 32, 5654, 'Indeed, it throws sparks [as huge] as a fortress,', NULL, NULL, 'b09477ecab1f1d0c9c0379c5b0b8f088864f77cbe641947ac3ad1e6405d80c91'),
  ('en.sahih', 77, 33, 5655, 'As if they were yellowish [black] camels.', NULL, NULL, '3b7d3c56e76be719200eae71c01155547feb250ee81ebf0c31fdfcb208ca50fd'),
  ('en.sahih', 77, 34, 5656, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 35, 5657, 'This is a Day they will not speak,', NULL, NULL, 'f6c22287a15f6b1fff23b6bd866712bd26575d7b092aeae8c1b46a0ffa4fa43a'),
  ('en.sahih', 77, 36, 5658, 'Nor will it be permitted for them to make an excuse.', NULL, NULL, '362bbc8c09cea227a1593396ce3455ea8ca0e392fa79dbca7f299e1f5fda1990'),
  ('en.sahih', 77, 37, 5659, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 38, 5660, 'This is the Day of Judgement; We will have assembled you and the former peoples.', NULL, NULL, 'a9a808054181244bbba094335f47aecfd0ecbfe69433292159cd0dce5708e0f9'),
  ('en.sahih', 77, 39, 5661, 'So if you have a plan, then plan against Me.', NULL, NULL, '6d0bafe25da6aabfa8e8d483ffbb8bfad332a250caad44b89c0729321ce687c7'),
  ('en.sahih', 77, 40, 5662, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 41, 5663, 'Indeed, the righteous will be among shades and springs', NULL, NULL, '8de9ae4aac285647c20a0eb3291183f8c785738f04c81a236609f0741f585835'),
  ('en.sahih', 77, 42, 5664, 'And fruits from whatever they desire,', NULL, NULL, 'f69e0724cdc653a55e1ca399a99617ce79bd4c40352cad255f344e5e6dde8781'),
  ('en.sahih', 77, 43, 5665, '[Being told], "Eat and drink in satisfaction for what you used to do."', NULL, NULL, '569e9828e49fb69f91766f5d2c7e1f356d0838493562ebc963e90cac7ee47b5b'),
  ('en.sahih', 77, 44, 5666, 'Indeed, We thus reward the doers of good.', NULL, NULL, '96fb15e06afcb86aac61f0538d3be159d74652207077142bce899cf15e857d94'),
  ('en.sahih', 77, 45, 5667, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 46, 5668, '[O disbelievers], eat and enjoy yourselves a little; indeed, you are criminals.', NULL, NULL, '37765d99e3ab447c7af1b447b1425ee7f713057e95233f75cea3ffed901eea09'),
  ('en.sahih', 77, 47, 5669, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 48, 5670, 'And when it is said to them, "Bow [in prayer]," they do not bow.', NULL, NULL, '3558ea93fb92132a9b1f8c12b0204ac97243bcb7a94e48cf802784c314c4207f'),
  ('en.sahih', 77, 49, 5671, 'Woe, that Day, to the deniers.', NULL, NULL, '545a43575700cfa83ad134c6a2810998a1fb0d934153e5ca0e2af12e0203f3da'),
  ('en.sahih', 77, 50, 5672, 'Then in what statement after the Qur''an will they believe?', NULL, NULL, '44ce6480cb9c321b2047bf0a9c9d0d22c1736268d7df3b305b46b43b68983969'),
  ('en.sahih', 78, 1, 5673, 'About what are they asking one another?', NULL, NULL, '9b5f7a8dc61c90f55cff2ebe7613ed5400787a83b0380edfc898ce0b7adef0b4'),
  ('en.sahih', 78, 2, 5674, 'About the great news -', NULL, NULL, '1d59e50b0b63e3a892501252422ed83b9003539f5984fdca3d5b134c65209f64'),
  ('en.sahih', 78, 3, 5675, 'That over which they are in disagreement.', NULL, NULL, '78f2c874917e2f619646415298c49e683d206cbb1c1ccf7d15108147f96cf9da'),
  ('en.sahih', 78, 4, 5676, 'No! They are going to know.', NULL, NULL, '175b32be9a0ce1eb164ed8c9aea0aedbd8e3e5dfc49b44844b0841fe55989aa1'),
  ('en.sahih', 78, 5, 5677, 'Then, no! They are going to know.', NULL, NULL, 'e41969348ec0d163999bfc5bd460b78da14f487e38a61192705680b5846a3b34'),
  ('en.sahih', 78, 6, 5678, 'Have We not made the earth a resting place?', NULL, NULL, 'abd03551bdc06a163a2f5abde12824372f56f40401d5be9bb3752d9467fbca0d'),
  ('en.sahih', 78, 7, 5679, 'And the mountains as stakes?', NULL, NULL, 'ed0425c5a0976d2eefa991de9f7d109334a98d2b766f63aad13958d3bc81aa60'),
  ('en.sahih', 78, 8, 5680, 'And We created you in pairs', NULL, NULL, 'b503901c3b67f19c6ff7d069f616f870808d92291dc458120e1ec823561cf682'),
  ('en.sahih', 78, 9, 5681, 'And made your sleep [a means for] rest', NULL, NULL, '8df75c47a3a93a53f264a9fdeb8dd2e7209a53737e4824d87f7fb44d0eb58153'),
  ('en.sahih', 78, 10, 5682, 'And made the night as clothing', NULL, NULL, 'fc499d08c413efd5e985e92328956d50b55d5cafaff22061b789628c9a2a575b'),
  ('en.sahih', 78, 11, 5683, 'And made the day for livelihood', NULL, NULL, '877b467b2dbff461f3d397f34a29f120e1837a7992837fcfbdca86730d81e52d'),
  ('en.sahih', 78, 12, 5684, 'And constructed above you seven strong [heavens]', NULL, NULL, '92b9f3e0ac7b52fd5f1e57e4cfdc8df85c79bc81c525bf606748b02796693997'),
  ('en.sahih', 78, 13, 5685, 'And made [therein] a burning lamp', NULL, NULL, 'd7d1ccd9be0365ac24e74505d638f08fc03d4090a4e3f7fcd553023e659010d6'),
  ('en.sahih', 78, 14, 5686, 'And sent down, from the rain clouds, pouring water', NULL, NULL, 'c8a15d368918e5bc3a3224f2f73b6bc4bd3ee858a49190f80939c603c84a014f'),
  ('en.sahih', 78, 15, 5687, 'That We may bring forth thereby grain and vegetation', NULL, NULL, 'c08709472df0f93af36b13dc5b5d6b5d04e26a6338038426af6c7df545009395'),
  ('en.sahih', 78, 16, 5688, 'And gardens of entwined growth.', NULL, NULL, '06110ccf3817d3a1b7fee6a3fff5beddb38ebb7b95d354c4fbafbb06c7664522'),
  ('en.sahih', 78, 17, 5689, 'Indeed, the Day of Judgement is an appointed time -', NULL, NULL, 'e4a22030659c5440eea2e61def0292418366ee352ceb22cebc608877b5c14ea3'),
  ('en.sahih', 78, 18, 5690, 'The Day the Horn is blown and you will come forth in multitudes', NULL, NULL, 'd1352a5504de62f85447423fa98e294084f656cba98c948d5e51b4fde7155ccc'),
  ('en.sahih', 78, 19, 5691, 'And the heaven is opened and will become gateways', NULL, NULL, '4135d3f192b31bbeadac537cadba1431a198be31120d515eb43d984d456ba8ae'),
  ('en.sahih', 78, 20, 5692, 'And the mountains are removed and will be [but] a mirage.', NULL, NULL, 'ef1861e529b4dea64d80b48aa0441a94fa6ee875a4798da2163d78296167b604'),
  ('en.sahih', 78, 21, 5693, 'Indeed, Hell has been lying in wait', NULL, NULL, 'e91947b7d9db496372f829e8afea22513f7e81b5245332108308ddb2b1963007'),
  ('en.sahih', 78, 22, 5694, 'For the transgressors, a place of return,', NULL, NULL, '2f4df0ade057a8eaefc8607700ecf2c11d7b2fe89e301431629c1917148e394b'),
  ('en.sahih', 78, 23, 5695, 'In which they will remain for ages [unending].', NULL, NULL, '6749de33ee1973a904b254aac710ac8dab57230d7b40b99ea445026cf85355b1'),
  ('en.sahih', 78, 24, 5696, 'They will not taste therein [any] coolness or drink', NULL, NULL, '0f3b23f349b914b5fa3627b959768dec626abbfbb9c91b2c7a9fe3d22c289a40'),
  ('en.sahih', 78, 25, 5697, 'Except scalding water and [foul] purulence -', NULL, NULL, '8619d665e0163de004691ee9628141ec3bd5799022be421e6f25152be67bec4e'),
  ('en.sahih', 78, 26, 5698, 'An appropriate recompense.', NULL, NULL, 'cd573814986ba1c4f63940d3739b8c18fca6632551c7e3acb4dafaa787b1dd61'),
  ('en.sahih', 78, 27, 5699, 'Indeed, they were not expecting an account', NULL, NULL, '75373db9f2ccb1baa072bf1edcdb1de85f63db2fccc973b9cc54784fb280ce22'),
  ('en.sahih', 78, 28, 5700, 'And denied Our verses with [emphatic] denial.', NULL, NULL, 'b52bdc1cef3bd40e18f6d297576c78d367861ccc0464f1d234f645cd1509af07')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 78, 29, 5701, 'But all things We have enumerated in writing.', NULL, NULL, '398aef64a5b056714a6f09a626a4dec734684b2e2b217a8f1d75c88e7eeb5006'),
  ('en.sahih', 78, 30, 5702, '"So taste [the penalty], and never will We increase you except in torment."', NULL, NULL, '06045a82feb84336f23a165e0c9918c6c1b712cfae7fcf8911c691a4ce83573e'),
  ('en.sahih', 78, 31, 5703, 'Indeed, for the righteous is attainment -', NULL, NULL, '29f6f7bb471a9c024e97d1329992a5678e538eefe88cc4f866e97e2e7f57fa1d'),
  ('en.sahih', 78, 32, 5704, 'Gardens and grapevines', NULL, NULL, '0ee11e4d5b13466699b7487744f2ff7319ee0e14ac462310f51757b7255788f2'),
  ('en.sahih', 78, 33, 5705, 'And full-breasted [companions] of equal age', NULL, NULL, '079cd122677523efe533c642bb850f6943252c5768029024ba640c5172bacb8e'),
  ('en.sahih', 78, 34, 5706, 'And a full cup.', NULL, NULL, '5346d39691f8f0456f6b68a3c8c6fe4eaa0cb85e6e9fe2be842ab2461fbf0246'),
  ('en.sahih', 78, 35, 5707, 'No ill speech will they hear therein or any falsehood -', NULL, NULL, '17d3b4b579df77cf118c4ace2c59075f2dcdb9067966aa1670ef0b36da2fc11a'),
  ('en.sahih', 78, 36, 5708, '[As] reward from your Lord, [a generous] gift [made due by] account,', NULL, NULL, '553268a17691d87c1e6fdd9ca04c3783bccafa26b626c6511d5f5a2827615277'),
  ('en.sahih', 78, 37, 5709, '[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.', NULL, NULL, '686b6211b2a8ce9baeb64013b14830fd46e4365447353290809072fda67081ec'),
  ('en.sahih', 78, 38, 5710, 'The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.', NULL, NULL, '0de5faa2c554bb3ea461ce7313d56006c067fed92cc26ca2a58ac5eda14432ab'),
  ('en.sahih', 78, 39, 5711, 'That is the True Day; so he who wills may take to his Lord a [way of] return.', NULL, NULL, '9be24c81ca4c969f00c2a24f75ba9630762f6494e0df6b4628237d7d8e77a7b6'),
  ('en.sahih', 78, 40, 5712, 'Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, "Oh, I wish that I were dust!"', NULL, NULL, '85cbfa888d79d654f93dfb22fff04e84a8cd9863d75be91dee2299e77ce87301'),
  ('en.sahih', 79, 1, 5713, 'By those [angels] who extract with violence', NULL, NULL, '9794f05ce1f1ae413c57b8948cf44b2f91a3e0363507e6c5bb5bc7ca655b0bed'),
  ('en.sahih', 79, 2, 5714, 'And [by] those who remove with ease', NULL, NULL, '2fc351e6ca079200708c262ddc2e0135a1d42acae09b256f58f9e852aca4afc7'),
  ('en.sahih', 79, 3, 5715, 'And [by] those who glide [as if] swimming', NULL, NULL, '68335be3aef92a8d2e693ac726ed20fefd1d5637aad0965f20d45d9a9d48e355'),
  ('en.sahih', 79, 4, 5716, 'And those who race each other in a race', NULL, NULL, 'd2ebd7d5b08fe58dfd85203313a42e8b08eb73748dbdca9c7637fe70adf5f1b8'),
  ('en.sahih', 79, 5, 5717, 'And those who arrange [each] matter,', NULL, NULL, '27785d349892fb4e8a79028b2925b232213d54920f737dc285c253901812a782'),
  ('en.sahih', 79, 6, 5718, 'On the Day the blast [of the Horn] will convulse [creation],', NULL, NULL, 'f11003a65a376dfdd47a3347162c689f675311e88fc7b8c2892ae5372d477555'),
  ('en.sahih', 79, 7, 5719, 'There will follow it the subsequent [one].', NULL, NULL, '08828e6bf12f9b0c69554a2837c236edf2c4d8d9d6067226f9f204562d45a5cb'),
  ('en.sahih', 79, 8, 5720, 'Hearts, that Day, will tremble,', NULL, NULL, 'dc1a33217b6e2baa69f3fbd011276fa08913c8b9329f49c1d8cf217b71bd4650'),
  ('en.sahih', 79, 9, 5721, 'Their eyes humbled.', NULL, NULL, 'f612ac67f5eb2b93a5fcb40912bc37ca6f843bba3ad71c88f4f3e1d8750fa622'),
  ('en.sahih', 79, 10, 5722, 'They are [presently] saying, "Will we indeed be returned to [our] former state [of life]?', NULL, NULL, '0468450113d8dca3c6e702c0bf9bf050f7577fe9d0af919cd7132e6c93d723bb'),
  ('en.sahih', 79, 11, 5723, 'Even if we should be decayed bones?', NULL, NULL, '27463398a5fb10195fdddb74403a79aa58166256e27832db62441c0c9da7b131'),
  ('en.sahih', 79, 12, 5724, 'They say, "That, then, would be a losing return."', NULL, NULL, 'ef9fc49407b2c65140e841d5dff6d104f3427aa0a85459f38cc8b69876b4beb9'),
  ('en.sahih', 79, 13, 5725, 'Indeed, it will be but one shout,', NULL, NULL, '63302dcdb0ab19773f1ff27bf30b890f1e093ce77a7b062019e74f2cf454d75a'),
  ('en.sahih', 79, 14, 5726, 'And suddenly they will be [alert] upon the earth''s surface.', NULL, NULL, '9139a245c6585526d1a58bd3e39c955f6991c276bdece76d5e26512926f42873'),
  ('en.sahih', 79, 15, 5727, 'Has there reached you the story of Moses? -', NULL, NULL, '6693728f9a41f3680520f1c11cfb7875c133e7d81cccff1db1e32ab98ab44451'),
  ('en.sahih', 79, 16, 5728, 'When his Lord called to him in the sacred valley of Tuwa,', NULL, NULL, '7673b5549e089dfb44b93e3b12409f81be2b83c0748fe38521da3cc7ca2b18e4'),
  ('en.sahih', 79, 17, 5729, '"Go to Pharaoh. Indeed, he has transgressed.', NULL, NULL, '24633f2ef56751b14578eb1fb6227a9e8aeb3bec237beba8980a5d92b0230ba3'),
  ('en.sahih', 79, 18, 5730, 'And say to him, ''Would you [be willing to] purify yourself', NULL, NULL, '6ae4faa3f26d5aa965ee8d6314dce2de6a0e8c6374489e9a891c161adbc1eb61'),
  ('en.sahih', 79, 19, 5731, 'And let me guide you to your Lord so you would fear [Him]?''"', NULL, NULL, '00bcff25d5da49e4841a86ce67deddf80017d03943694adc87ce4559ba9dc68f'),
  ('en.sahih', 79, 20, 5732, 'And he showed him the greatest sign,', NULL, NULL, '49e0d25971150d08def505a7458211bd3c894c16a3f4c36cfd96e69559ba2fa3'),
  ('en.sahih', 79, 21, 5733, 'But Pharaoh denied and disobeyed.', NULL, NULL, '865bd08d817b1b7f4781ba3b11ba23a512251536e301f4c0cfeda5313c516827'),
  ('en.sahih', 79, 22, 5734, 'Then he turned his back, striving.', NULL, NULL, '705ed1c609d91cd60823f30238bf143f2ed1a444c0a21660f8da14bc371175b9'),
  ('en.sahih', 79, 23, 5735, 'And he gathered [his people] and called out', NULL, NULL, '1c8d8ce303107f6a4aeeff99a7a0c1232b77f91a4119019e366ab0874ea0094d'),
  ('en.sahih', 79, 24, 5736, 'And said, "I am your most exalted lord."', NULL, NULL, '7477a7c97e8b0fc49325fdfa294d212ee1c5fc7f46adde510fa911b433974e2c'),
  ('en.sahih', 79, 25, 5737, 'So Allah seized him in exemplary punishment for the last and the first [transgression].', NULL, NULL, '7674dc5729ff797562e127dce271c4ee3856f1d8b3b840cdbb2a29d516de9155'),
  ('en.sahih', 79, 26, 5738, 'Indeed in that is a warning for whoever would fear [Allah].', NULL, NULL, 'ee55731155938f971a4d869913b78d21a9ba2a479e530eadf726e0d3f6bfa401'),
  ('en.sahih', 79, 27, 5739, 'Are you a more difficult creation or is the heaven? Allah constructed it.', NULL, NULL, 'd89e8f1350380c7acda7263b001adf80fde5fe1ebb1d7f3df1badf84072c05ba'),
  ('en.sahih', 79, 28, 5740, 'He raised its ceiling and proportioned it.', NULL, NULL, 'd195a5bc1899a0b61b6f073332d5fd3f6d6aa04d29d69cd9472fb7e1283a5e10'),
  ('en.sahih', 79, 29, 5741, 'And He darkened its night and extracted its brightness.', NULL, NULL, 'fdf2f2d4dab0b43b6ff367bc11eb3b28e89b97eeb619302a56a82851de40082e'),
  ('en.sahih', 79, 30, 5742, 'And after that He spread the earth.', NULL, NULL, '1f58c61e47243f1fe1998c9866a18eb2e46154c926a9e42d6e828eafbb60e541'),
  ('en.sahih', 79, 31, 5743, 'He extracted from it its water and its pasture,', NULL, NULL, '12b4dd5452005882068abaf196f52eb0ae774c808de1c41b8507725380d071fc'),
  ('en.sahih', 79, 32, 5744, 'And the mountains He set firmly', NULL, NULL, '261720705b04ba710011c7690445cbafeb6a08ce9630c71a61778995260ca2d0'),
  ('en.sahih', 79, 33, 5745, 'As provision for you and your grazing livestock.', NULL, NULL, 'ad1fa28cea89ce69715a15bccedb113e6edd7bc1b6d95f4a12a0a60e1e925f54'),
  ('en.sahih', 79, 34, 5746, 'But when there comes the greatest Overwhelming Calamity -', NULL, NULL, 'ca1165f54ea6cc4afe0c6f741b3cd4e44c16224fdeaa4b832e2b982ada72434c'),
  ('en.sahih', 79, 35, 5747, 'The Day when man will remember that for which he strove,', NULL, NULL, '437aa9c3f3aa241977a0c8b91a3c17f1f46aa4c7087c453237d823c6925dbcba'),
  ('en.sahih', 79, 36, 5748, 'And Hellfire will be exposed for [all] those who see -', NULL, NULL, 'c23106c410ac64fe52755958e3a51a8849d453c7145289836dd588189b8a7d2c'),
  ('en.sahih', 79, 37, 5749, 'So as for he who transgressed', NULL, NULL, '50e4d49ba86be809d27ded16f17354a0a906e5f1eeb01e531f514b5aa191e26d'),
  ('en.sahih', 79, 38, 5750, 'And preferred the life of the world,', NULL, NULL, '96ff82efa72ae23238e7f0033c68572ab3b5c47923aeea18ffb1aa5527451198'),
  ('en.sahih', 79, 39, 5751, 'Then indeed, Hellfire will be [his] refuge.', NULL, NULL, '4110a96946e07090beb7a2f074e1699552601ae4e84d07faf30a5e8849d05d8d'),
  ('en.sahih', 79, 40, 5752, 'But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,', NULL, NULL, 'd4b0c976e64820171ea449d4a7dd01b11e28921fac26d11ee25e13d521e6800b'),
  ('en.sahih', 79, 41, 5753, 'Then indeed, Paradise will be [his] refuge.', NULL, NULL, '9ec9959b4584e270639625006569165a93c7b3aeceefe61c5948f76d0453b5a0'),
  ('en.sahih', 79, 42, 5754, 'They ask you, [O Muhammad], about the Hour: when is its arrival?', NULL, NULL, '72091380d13010a725e638543e783efc5d0cf725dfac9ba5bdf0b4e92e2b0289'),
  ('en.sahih', 79, 43, 5755, 'In what [position] are you that you should mention it?', NULL, NULL, 'c92348d7bfc3827b29b1ed3bbb72f113b0a6bc379b782e9b0fc5f817bbe74f52'),
  ('en.sahih', 79, 44, 5756, 'To your Lord is its finality.', NULL, NULL, 'ba7a575437508abaee903a1fdee022f945574e44a2e4d1fbc68090e520648147'),
  ('en.sahih', 79, 45, 5757, 'You are only a warner for those who fear it.', NULL, NULL, 'e1f0785e84899e7d69c93eaefeb8ebbbed5c2450cfad2af669a42f8863637e58'),
  ('en.sahih', 79, 46, 5758, 'It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof.', NULL, NULL, '034a347149f64f1920ae65daf7216068c74340a22965eb5ab83ef86e146103b2'),
  ('en.sahih', 80, 1, 5759, 'The Prophet frowned and turned away', NULL, NULL, 'c38a08db97292608dac9aeb3920516fca446782ddeaf62ffa71d965e11fc0325'),
  ('en.sahih', 80, 2, 5760, 'Because there came to him the blind man, [interrupting].', NULL, NULL, '0a5293797a7b149dae124a8e4d7056f0903a2e3b1abfadad10e0a5bc2abe7146'),
  ('en.sahih', 80, 3, 5761, 'But what would make you perceive, [O Muhammad], that perhaps he might be purified', NULL, NULL, '00099d1a3cb65b018f5bed3ea6c384a7e8f3bf8870eb0f68d7a1db0a1fc5fea1'),
  ('en.sahih', 80, 4, 5762, 'Or be reminded and the remembrance would benefit him?', NULL, NULL, 'dd5f29b1235efb02d69fd2bd3d8cb01e9454de18b37e4c927ccbb4ebb061e281'),
  ('en.sahih', 80, 5, 5763, 'As for he who thinks himself without need,', NULL, NULL, '30702350ec2fafee9d21fac67bbb84905cc9f438584b1d9be6b6c30635cb0676'),
  ('en.sahih', 80, 6, 5764, 'To him you give attention.', NULL, NULL, 'd0f6803302080a3222af7cc815219e55559de289ca6df4e136066ee256773c48'),
  ('en.sahih', 80, 7, 5765, 'And not upon you [is any blame] if he will not be purified.', NULL, NULL, '26fcda63ddc66df04cc4542f087df54ca58ae1d7f73fb0ecc35f2db1170f33d2'),
  ('en.sahih', 80, 8, 5766, 'But as for he who came to you striving [for knowledge]', NULL, NULL, '92615b039ca4b78040e30b96b4be327e0f920150d75c87f870c5ba0536b20d59'),
  ('en.sahih', 80, 9, 5767, 'While he fears [Allah],', NULL, NULL, '71740f6139aac494ea2c63f26399513ce2f38166e96e86054940d4dc08afd2a6'),
  ('en.sahih', 80, 10, 5768, 'From him you are distracted.', NULL, NULL, '4d803fdcd5be5a8cd56750fda810df523d011259d8ba5318ad2c6c1eba44597e'),
  ('en.sahih', 80, 11, 5769, 'No! Indeed, these verses are a reminder;', NULL, NULL, 'c0b3f43c99d0fd0e12835d5766fa17be14b2515217dbe925d0c4b45266eed052'),
  ('en.sahih', 80, 12, 5770, 'So whoever wills may remember it.', NULL, NULL, '01c57724a62d4923d9e323adfb6ced88380b0d27e9d052657167ebe8349819ad'),
  ('en.sahih', 80, 13, 5771, '[It is recorded] in honored sheets,', NULL, NULL, '1fdb3070be11c42ce0d227dcfa404094ec145b3e7766add1b34b32e029d60bf6'),
  ('en.sahih', 80, 14, 5772, 'Exalted and purified,', NULL, NULL, 'c14730ec09c8ebd925d1f536d7d92e33c626dfd15e4e472dfaba93becc424752'),
  ('en.sahih', 80, 15, 5773, '[Carried] by the hands of messenger-angels,', NULL, NULL, '12f1d2a8c580d99299101a6971a85eccb7a267b9b3ced5658a35dd00c48272f4'),
  ('en.sahih', 80, 16, 5774, 'Noble and dutiful.', NULL, NULL, 'da4d59a4043d64da2fc0120e7e8950ba7780d7865b94ed6c8f1500cabd3ac006'),
  ('en.sahih', 80, 17, 5775, 'Cursed is man; how disbelieving is he.', NULL, NULL, '46def01197f5d73b33bfb72882c2b1995b3cb96ec27aeabc2cc5487131cdc875'),
  ('en.sahih', 80, 18, 5776, 'From what substance did He create him?', NULL, NULL, 'c76881251c87e67c196b1ebef410007b1f6cb3e195c621aef7ad0d3f684e5134'),
  ('en.sahih', 80, 19, 5777, 'From a sperm-drop He created him and destined for him;', NULL, NULL, '0f8da302e3867e216cfb39bccc9805354e2550615a7eb9adcf4a02873423c181'),
  ('en.sahih', 80, 20, 5778, 'Then He eased the way for him;', NULL, NULL, '310a4b38d83751586d4f671a67bfa97450a99b3f9afa957d35030ee67a914db1'),
  ('en.sahih', 80, 21, 5779, 'Then He causes his death and provides a grave for him.', NULL, NULL, '4e092ce2db30f8318d06ff1f908e5f237efd9b452e2e4c771adb5b6c46f0836b'),
  ('en.sahih', 80, 22, 5780, 'Then when He wills, He will resurrect him.', NULL, NULL, '3effd28bae7e0da814ed56571a3e07584be54c9c9e5041bc0945e05eaacf2006'),
  ('en.sahih', 80, 23, 5781, 'No! Man has not yet accomplished what He commanded him.', NULL, NULL, '1c076e025706755196790b7c18c8fbed89b77267308e837ebeb63651c4a2d389'),
  ('en.sahih', 80, 24, 5782, 'Then let mankind look at his food -', NULL, NULL, '2dbbaaeddc4e28e0c67f3aa0a14dfe5936b1be925d334ee72c020ec4bdcee619'),
  ('en.sahih', 80, 25, 5783, 'How We poured down water in torrents,', NULL, NULL, 'ef090386e87548198ae44a764f3da146b8148a217f83c46885e282d768617ec5'),
  ('en.sahih', 80, 26, 5784, 'Then We broke open the earth, splitting [it with sprouts],', NULL, NULL, '8843d278d0f9b519b47fe030e3fc0c6799e9d5147f5dfbf51f496e4bbede3bfe'),
  ('en.sahih', 80, 27, 5785, 'And caused to grow within it grain', NULL, NULL, '237b3cfc8c2f519b64413202865043a51d930b32ae726c5094b0698edfe7eeab'),
  ('en.sahih', 80, 28, 5786, 'And grapes and herbage', NULL, NULL, '2d4e8107b57e5774e2a1ae819365ebea0e43850310b721070d8e2fc78ca87947'),
  ('en.sahih', 80, 29, 5787, 'And olive and palm trees', NULL, NULL, 'd218206f1c3bf314fe824755f2d0d5f862d76d2d224d59e1905fed4788972281'),
  ('en.sahih', 80, 30, 5788, 'And gardens of dense shrubbery', NULL, NULL, 'a6ea1b3b7341ccaffbaf534ba781adcf424a87c2de8eca5776e4de94d2e2a718'),
  ('en.sahih', 80, 31, 5789, 'And fruit and grass -', NULL, NULL, '85ff4f5fe64d33e6fdd32e9003b0a53de054a333d1bb4365553044881c6f4694'),
  ('en.sahih', 80, 32, 5790, '[As] enjoyment for you and your grazing livestock.', NULL, NULL, '73aa75d929b42b030840d88e581f9686b270869c644ce627c64f67e5cdfad437'),
  ('en.sahih', 80, 33, 5791, 'But when there comes the Deafening Blast', NULL, NULL, 'bd006037c7c9220c80e0def8de71fc4ae32d8f69d79942e71b6b8bee082f96c5'),
  ('en.sahih', 80, 34, 5792, 'On the Day a man will flee from his brother', NULL, NULL, 'da47d83387fdce89658e2dd64c8fc81145d8b1d86c7b5fdda27852f17dc07560'),
  ('en.sahih', 80, 35, 5793, 'And his mother and his father', NULL, NULL, '10ad4e41ba60db98c6507bf9402a38c084a1c5d340e10f812104dc13195220c3'),
  ('en.sahih', 80, 36, 5794, 'And his wife and his children,', NULL, NULL, '5d6059354d2b02432e11b1215e8b1cbd21986a5e7a6573a04ff56470459438af'),
  ('en.sahih', 80, 37, 5795, 'For every man, that Day, will be a matter adequate for him.', NULL, NULL, '3283f5ae4d0f789068cd444da4d782ab41c20166b48c813ba4fd596aae60b2ea'),
  ('en.sahih', 80, 38, 5796, '[Some] faces, that Day, will be bright -', NULL, NULL, '8a854d38fd8709e00facef8fcfd5cf7fbf0e7ca462950a855053d826ef9919ac'),
  ('en.sahih', 80, 39, 5797, 'Laughing, rejoicing at good news.', NULL, NULL, '3946128946e17269843cd820d3f88ebbdb86487f27a94c48fc1ceca5d2dd1763'),
  ('en.sahih', 80, 40, 5798, 'And [other] faces, that Day, will have upon them dust.', NULL, NULL, 'b901458127aae4e844095647b8c6a265727b4b0852e794fec3f9aaa0cbd25038'),
  ('en.sahih', 80, 41, 5799, 'Blackness will cover them.', NULL, NULL, '4209f094aab3987a84109b4f53928cb16e51a0f29ec88e8d6c18b359bcf72fa1'),
  ('en.sahih', 80, 42, 5800, 'Those are the disbelievers, the wicked ones.', NULL, NULL, '2be6e347fddee7f16f2620bf098ed942fe8e6f8140858b4f346d38c4879edd5a')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 81, 1, 5801, 'When the sun is wrapped up [in darkness]', NULL, NULL, 'd7b503fd4ae4767403431bd98d907718d3952d334e5063a79d29eb05a9fd423c'),
  ('en.sahih', 81, 2, 5802, 'And when the stars fall, dispersing,', NULL, NULL, '1f671998a1caae1bd4961e7eb0d740931958d70a5cf0255e1607a84b2e454171'),
  ('en.sahih', 81, 3, 5803, 'And when the mountains are removed', NULL, NULL, '75822d64febf1b898df1b6e7f01a584e0192a42e478def5799206764b78436a2'),
  ('en.sahih', 81, 4, 5804, 'And when full-term she-camels are neglected', NULL, NULL, '10bb8509610b92a974f3a50a8b54690bf386da6dd9d6b68c68b5da03adec0bc7'),
  ('en.sahih', 81, 5, 5805, 'And when the wild beasts are gathered', NULL, NULL, '8b4d156c15734cd141ae103b0b2da43d94f9a98c12ad92606ee1970ba6ad95b0'),
  ('en.sahih', 81, 6, 5806, 'And when the seas are filled with flame', NULL, NULL, '6d17d309662687eb623150a510848c0e532aba02b808df2fbb7501a31825a121'),
  ('en.sahih', 81, 7, 5807, 'And when the souls are paired', NULL, NULL, 'f899d607d347d7a18d7afe6f867068530d2ce1e43612d5053b79084885b7d8b2'),
  ('en.sahih', 81, 8, 5808, 'And when the girl [who was] buried alive is asked', NULL, NULL, 'b68db2084633096fa50ba4eb6fbfa8a131f803d8e8ebe600263341522dbce145'),
  ('en.sahih', 81, 9, 5809, 'For what sin she was killed', NULL, NULL, '094707e03faebef54db2c09aac3eb5ec7156cf2dee9a03fe4d695e349a719841'),
  ('en.sahih', 81, 10, 5810, 'And when the pages are made public', NULL, NULL, 'a88f692a47d5d01160aae1ffa5f0a07adbe411e2220a4db9e2b83fddeab41e88'),
  ('en.sahih', 81, 11, 5811, 'And when the sky is stripped away', NULL, NULL, '06338a403e4649ab3bdda4787b9591399fb2d6e5f30d8a8ca445002f65940468'),
  ('en.sahih', 81, 12, 5812, 'And when Hellfire is set ablaze', NULL, NULL, 'ca9b42a8ac46301ff78a2f529acbf64b388a2d62194cc9851fcf9a8ce16dfb45'),
  ('en.sahih', 81, 13, 5813, 'And when Paradise is brought near,', NULL, NULL, '53790bef5192a85effda5cfb64f5d93eadfaead58ade51b9add7fd83958b4fe9'),
  ('en.sahih', 81, 14, 5814, 'A soul will [then] know what it has brought [with it].', NULL, NULL, '86adf361140a3545509dfbef234a7ccd86b976563af93e1acecdc1eb516a1c28'),
  ('en.sahih', 81, 15, 5815, 'So I swear by the retreating stars -', NULL, NULL, 'c04f57aec2bb1fa9007f1e58a3d0d9b7f598ecd9f0820871821bacb9d9e5576c'),
  ('en.sahih', 81, 16, 5816, 'Those that run [their courses] and disappear -', NULL, NULL, '7b1a71f9a4f2d77c3a6731daa23fcbe76d0165b1aad4946177f196a29eb6550e'),
  ('en.sahih', 81, 17, 5817, 'And by the night as it closes in', NULL, NULL, '68492d50ac27c280492705465e3419fe6eb39ef6b34f85ed89e77cf9a361be88'),
  ('en.sahih', 81, 18, 5818, 'And by the dawn when it breathes', NULL, NULL, 'adfdc27c86d54f4bd3c598ed02902950ac87d13e87b16600d8da242c776ad890'),
  ('en.sahih', 81, 19, 5819, '[That] indeed, the Qur''an is a word [conveyed by] a noble messenger', NULL, NULL, 'f7dcba13cf06dd848fdca0204fd6be430f69cf226a7b842861dd1e59bf3a10a3'),
  ('en.sahih', 81, 20, 5820, '[Who is] possessed of power and with the Owner of the Throne, secure [in position],', NULL, NULL, '2b47400920686116f9c34100471b1a34369bfc692be9b0f109d27a72ac8cbe16'),
  ('en.sahih', 81, 21, 5821, 'Obeyed there [in the heavens] and trustworthy.', NULL, NULL, '76e5e2db38ce3367272d6750af3bde43d7c87dbfb0f0fc674862a03ea907d56e'),
  ('en.sahih', 81, 22, 5822, 'And your companion is not [at all] mad.', NULL, NULL, '912121e6324894e3a5adfb40851feb0bf51ec02dc93e0499145cb9f6d9f5e7cb'),
  ('en.sahih', 81, 23, 5823, 'And he has already seen Gabriel in the clear horizon.', NULL, NULL, '74a261bb563b824b3d232d8033ca9ec5a33f6c8c1469cfe66614125539afbdde'),
  ('en.sahih', 81, 24, 5824, 'And Muhammad is not a withholder of [knowledge of] the unseen.', NULL, NULL, '8dfb48a622298354ccefa56751f207478f60a4ebf268023790c3c116086ce78d'),
  ('en.sahih', 81, 25, 5825, 'And the Qur''an is not the word of a devil, expelled [from the heavens].', NULL, NULL, 'd8e134af7b0c1294bcfeccd79f0bce4fed1224e9ab72d3c03eafc1ed748776a8'),
  ('en.sahih', 81, 26, 5826, 'So where are you going?', NULL, NULL, '95560a69ca6c5e66ec941fd0f0caa8f192df65ca829716ec5bacf1be4eec2080'),
  ('en.sahih', 81, 27, 5827, 'It is not except a reminder to the worlds', NULL, NULL, '1852422799f7f4fde53d954db87125d7ab35d3d372c3808aa70a95fe13aaf37d'),
  ('en.sahih', 81, 28, 5828, 'For whoever wills among you to take a right course.', NULL, NULL, 'a13a7cf068785430fbdb160afd12dcaef14e73bc6fdbde916c1de07deb9d7177'),
  ('en.sahih', 81, 29, 5829, 'And you do not will except that Allah wills - Lord of the worlds.', NULL, NULL, 'ada5980c41e451e01dde734625406bf414a254530e57e0171fd1357962994b4b'),
  ('en.sahih', 82, 1, 5830, 'When the sky breaks apart', NULL, NULL, '63b15804c969a4caafa3da7007a8680ce8445f50d2e55968f94585020b28b8f1'),
  ('en.sahih', 82, 2, 5831, 'And when the stars fall, scattering,', NULL, NULL, 'aa47caa175bc341b5974e44c7e4e8997d4bb13263fd7e977db3d27e6f2a48524'),
  ('en.sahih', 82, 3, 5832, 'And when the seas are erupted', NULL, NULL, 'f6e46cde2d3f7339b4bb6d8f2586b54dbfda59bd95b74de4b3b10a7cc2ed3962'),
  ('en.sahih', 82, 4, 5833, 'And when the [contents of] graves are scattered,', NULL, NULL, 'e5b0fc99ab87f984598948e48a17f1c7e3e02689052ee4be16f17d684d869c64'),
  ('en.sahih', 82, 5, 5834, 'A soul will [then] know what it has put forth and kept back.', NULL, NULL, 'a46f2180e408e70b5a047ee0103e121fcf478c4b560e6168d1ee6ee05baead81'),
  ('en.sahih', 82, 6, 5835, 'O mankind, what has deceived you concerning your Lord, the Generous,', NULL, NULL, 'd3fc80d1b4910e2268a924f15775aa3dc67b06d446f76e603c59ba226361ec63'),
  ('en.sahih', 82, 7, 5836, 'Who created you, proportioned you, and balanced you?', NULL, NULL, 'e538d8cdc3bba2e67305a33ec9bbd77952dd6512d0de6ec90713632da0f45632'),
  ('en.sahih', 82, 8, 5837, 'In whatever form He willed has He assembled you.', NULL, NULL, '3d89dce892d9bb09305bde71c69512f709aaba613524d9651f6f27aee879fcca'),
  ('en.sahih', 82, 9, 5838, 'No! But you deny the Recompense.', NULL, NULL, '0f665d0ffcf11d1a0f2a2f45c5dd25469aab59b13fb3136387cf0627a2a3eb9c'),
  ('en.sahih', 82, 10, 5839, 'And indeed, [appointed] over you are keepers,', NULL, NULL, '1f74b7ec17c73cd5989568b41b2f7c39f1548709497d8453e9516a52271dde6f'),
  ('en.sahih', 82, 11, 5840, 'Noble and recording;', NULL, NULL, '93111ca0402bda930995e32a583067f77d3ddd9847676a5568796c8a06a6b1bc'),
  ('en.sahih', 82, 12, 5841, 'They know whatever you do.', NULL, NULL, '7c6c66ce82f493bfd9c68f9037836308a3ed04084bec9e94e977a81d7c4bd3e1'),
  ('en.sahih', 82, 13, 5842, 'Indeed, the righteous will be in pleasure,', NULL, NULL, '96f70c6e23831ee019d0dc5b4777c41538dc08858a11b3f089dabe80aec37067'),
  ('en.sahih', 82, 14, 5843, 'And indeed, the wicked will be in Hellfire.', NULL, NULL, 'c640e132aa3f129c0310b3e24f45ff96e57f7360b8131f69e033e2d6faaecc32'),
  ('en.sahih', 82, 15, 5844, 'They will [enter to] burn therein on the Day of Recompense,', NULL, NULL, 'aa50cc77d1caf8bcec036afc49238f93a66ccaa91bfb4166cb7e91bf318ea4c0'),
  ('en.sahih', 82, 16, 5845, 'And never therefrom will they be absent.', NULL, NULL, '8b70898b79759ec0a308f2a7cf6b227f42bd3fbc6680ac1495feff5c6d3dc81e'),
  ('en.sahih', 82, 17, 5846, 'And what can make you know what is the Day of Recompense?', NULL, NULL, '3fb7deec6ee3fec61eb1737c61fc58f3efb337abff28fc92be7ccc68d9831cb8'),
  ('en.sahih', 82, 18, 5847, 'Then, what can make you know what is the Day of Recompense?', NULL, NULL, 'e62816087c2c389f419e134aa7d95f8d030784cd846d0433e9abbe5891ce8b55'),
  ('en.sahih', 82, 19, 5848, 'It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.', NULL, NULL, '455e81d0d02c1d778d3be6c7910fa6d271623f152615c9edd3ccfbf867c89d51'),
  ('en.sahih', 83, 1, 5849, 'Woe to those who give less [than due],', NULL, NULL, 'e1e238bea98388b9a43418b89b557eb62900713c06ac78875c8da7deb4b5c110'),
  ('en.sahih', 83, 2, 5850, 'Who, when they take a measure from people, take in full.', NULL, NULL, 'bbc0b656ccd330d519532d5059d95693d2ee1229788d4cd2397ebe1bf7d5dc10'),
  ('en.sahih', 83, 3, 5851, 'But if they give by measure or by weight to them, they cause loss.', NULL, NULL, 'a6dec958c9baab93d3c7e4a834fa3ce8d912c0a08760fbabd663e99da8e62337'),
  ('en.sahih', 83, 4, 5852, 'Do they not think that they will be resurrected', NULL, NULL, '3c53982c8c7c3e32d584d5eae2ff7f62a1669598b512a2f748458a7452ddd1ac'),
  ('en.sahih', 83, 5, 5853, 'For a tremendous Day -', NULL, NULL, 'dfcba4f83d4231fd8e215c47236322672b1a034a87e9d9e85d89929a7b31da4b'),
  ('en.sahih', 83, 6, 5854, 'The Day when mankind will stand before the Lord of the worlds?', NULL, NULL, 'eb9c33dd3cfbb99a8e8fbd2aecadde1b61e56de8926288241363918c01921eb1'),
  ('en.sahih', 83, 7, 5855, 'No! Indeed, the record of the wicked is in sijjeen.', NULL, NULL, 'babe5dd909c98151003eacf0a6e67f1fcefaa80f3a571bfb4ef8aa3b4bcc4d30'),
  ('en.sahih', 83, 8, 5856, 'And what can make you know what is sijjeen?', NULL, NULL, 'b0f01d147fb29e4ed39e7b6828e2eee31ee0d28403e952e27377e269b53fbf7e'),
  ('en.sahih', 83, 9, 5857, 'It is [their destination recorded in] a register inscribed.', NULL, NULL, 'd7d632edef50513b6d2f56771acdc8faeab244df6142f9fab255e6bb2976e5c7'),
  ('en.sahih', 83, 10, 5858, 'Woe, that Day, to the deniers,', NULL, NULL, '310981f181bc79cacd2ec91d25461c0342eb5a076d10ee12f73c61469be3ac79'),
  ('en.sahih', 83, 11, 5859, 'Who deny the Day of Recompense.', NULL, NULL, 'ac0588ae5418cb8e548ff4c94e42e788c003cee9a4a383ea4e50c03b8d2dd81c'),
  ('en.sahih', 83, 12, 5860, 'And none deny it except every sinful transgressor.', NULL, NULL, 'c18c90386396f62417585cc525c0158738c6cdb29b2878464649cbc832e700eb'),
  ('en.sahih', 83, 13, 5861, 'When Our verses are recited to him, he says, "Legends of the former peoples."', NULL, NULL, '6a63c1d09f470309c92815a14cdd7a4a7e3a5d95257acd0be60e171f77973bfa'),
  ('en.sahih', 83, 14, 5862, 'No! Rather, the stain has covered their hearts of that which they were earning.', NULL, NULL, '9ca96629cab694f02977713c0726c777b04f2368868200dfd259325218177023'),
  ('en.sahih', 83, 15, 5863, 'No! Indeed, from their Lord, that Day, they will be partitioned.', NULL, NULL, '4faa35f702f9e711e4c38f54f2b608b1067d9718817c11ebdd3ae3fe4df2a92b'),
  ('en.sahih', 83, 16, 5864, 'Then indeed, they will [enter and] burn in Hellfire.', NULL, NULL, '5267c064e8e12837e337470dbc6a50819201b33eab03d65779e18a03d184f166'),
  ('en.sahih', 83, 17, 5865, 'Then it will be said [to them], "This is what you used to deny."', NULL, NULL, '0cbbc387cf4497d4f3c56450be358894aa3ece6c8c627e145b92af4514da3376'),
  ('en.sahih', 83, 18, 5866, 'No! Indeed, the record of the righteous is in ''illiyyun.', NULL, NULL, '64f1791e686c1470ffa581a912321812ca55dfc90a08dddedaf3d310f79e7b2c'),
  ('en.sahih', 83, 19, 5867, 'And what can make you know what is ''illiyyun?', NULL, NULL, 'd241aff7847707dfd6e85af00e37ebec4655cadb73d16665fbe68bc0c6d18116'),
  ('en.sahih', 83, 20, 5868, 'It is [their destination recorded in] a register inscribed', NULL, NULL, '161000fdbbe38e51b27b35af78a93678d9d59d346ec37b6b44bbc7e1e0b71fc9'),
  ('en.sahih', 83, 21, 5869, 'Which is witnessed by those brought near [to Allah].', NULL, NULL, '5404cd35b0857b217245239fa772beae110a8d2c22260b79d31368e675d442a0'),
  ('en.sahih', 83, 22, 5870, 'Indeed, the righteous will be in pleasure', NULL, NULL, '87fc9fdc37846f1167c4a987b5b78ce15d8fd48743390841d00f109cda03e180'),
  ('en.sahih', 83, 23, 5871, 'On adorned couches, observing.', NULL, NULL, 'e7557631c16c309c689552431ef23ca7db7ae85f566d3d8bf3a57f39d1504afe'),
  ('en.sahih', 83, 24, 5872, 'You will recognize in their faces the radiance of pleasure.', NULL, NULL, '70649862d40c3ba9fff145e036c7b94ff4b613e22c4f04a4ef943eae42250af6'),
  ('en.sahih', 83, 25, 5873, 'They will be given to drink [pure] wine [which was] sealed.', NULL, NULL, '777d68e054bf2e9580a03bd0c9c1b2e7f24439769b0766f03fbcf05fac2217a9'),
  ('en.sahih', 83, 26, 5874, 'The last of it is musk. So for this let the competitors compete.', NULL, NULL, 'fe56673dcca27cb854bc9b701223d3cbfbebefeb900c1057060e5b6e082a4b18'),
  ('en.sahih', 83, 27, 5875, 'And its mixture is of Tasneem,', NULL, NULL, 'b5b457140e893ec470cb90154c50580e6015f22d69e977054625fe5f87eafe97'),
  ('en.sahih', 83, 28, 5876, 'A spring from which those near [to Allah] drink.', NULL, NULL, '5eb4a12c8c23df054321a1c4457c9c12b4e393cfccd514ba7c7de561b393fc7e'),
  ('en.sahih', 83, 29, 5877, 'Indeed, those who committed crimes used to laugh at those who believed.', NULL, NULL, '513681f080b4d5908a3d59d4db4fa53e83d15b2df6257a588a8cfc8b57f27300'),
  ('en.sahih', 83, 30, 5878, 'And when they passed by them, they would exchange derisive glances.', NULL, NULL, '3c8362657c51d48ef0b4bf6408b917efd7284d5c18fdfca288e3bb5aee7c0af9'),
  ('en.sahih', 83, 31, 5879, 'And when they returned to their people, they would return jesting.', NULL, NULL, '75465a2df05447753b4f7e7db8326bbd752eb713c7a1ffc6aff41b44821fb633'),
  ('en.sahih', 83, 32, 5880, 'And when they saw them, they would say, "Indeed, those are truly lost."', NULL, NULL, '8ab41c63c939b1d455f5ebe7346c089e6a3f061e7bd249af8b4e8eb7c8cc6fe4'),
  ('en.sahih', 83, 33, 5881, 'But they had not been sent as guardians over them.', NULL, NULL, '85d1686feb9151aac21d5807eb735d2b6cc8b58bdb3b7f5329412e113242dca2'),
  ('en.sahih', 83, 34, 5882, 'So Today those who believed are laughing at the disbelievers,', NULL, NULL, '91457a34755b777eb39e3c78ba6f059a9479af747417320030ffc4b8c24497d5'),
  ('en.sahih', 83, 35, 5883, 'On adorned couches, observing.', NULL, NULL, 'e7557631c16c309c689552431ef23ca7db7ae85f566d3d8bf3a57f39d1504afe'),
  ('en.sahih', 83, 36, 5884, 'Have the disbelievers [not] been rewarded [this Day] for what they used to do?', NULL, NULL, '9b0ed0e7b4aa5cec4e59e0d3e80ab5a5f4e25b983e64cd396cce93ce053f4dff'),
  ('en.sahih', 84, 1, 5885, 'When the sky has split [open]', NULL, NULL, '7a5329f1d6c5d2ab4a1cb94e685c2e1e25deae845217b84e74b1857f9fdde69b'),
  ('en.sahih', 84, 2, 5886, 'And has responded to its Lord and was obligated [to do so]', NULL, NULL, '258a574640dabdc6ed0685c6703ce1ced6115c1f65af8e663a282adf94b4406e'),
  ('en.sahih', 84, 3, 5887, 'And when the earth has been extended', NULL, NULL, 'c5739962f6234609ae039c5430f1117af44f0f5ce711c5bbf1fc74827de9ad11'),
  ('en.sahih', 84, 4, 5888, 'And has cast out that within it and relinquished [it]', NULL, NULL, '02aff07ace3952bd36ea3217333beba270b7c2a6d33245a25bddcbce7d624016'),
  ('en.sahih', 84, 5, 5889, 'And has responded to its Lord and was obligated [to do so] -', NULL, NULL, '99a65e89f70a7727ac1d2af511b91e42719ce46917c6bc1703f6c4b577193a98'),
  ('en.sahih', 84, 6, 5890, 'O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.', NULL, NULL, 'f43840ebd14804699f47fc15e573d1f6e423a33e444ffbfde72f30e1f914d7d4'),
  ('en.sahih', 84, 7, 5891, 'Then as for he who is given his record in his right hand,', NULL, NULL, 'f6db01a9024e982396b828675e042463c737e1228a1b827bdaa37492c0052bac'),
  ('en.sahih', 84, 8, 5892, 'He will be judged with an easy account', NULL, NULL, 'd7f09a7ff010ab44ddb44b91770e165a57ad97374f09a49ce49edb15d793dde6'),
  ('en.sahih', 84, 9, 5893, 'And return to his people in happiness.', NULL, NULL, '5c5ac5cafb4578487cc1d43dc18a71dfeeac6b04758549d1ad71378a77774240'),
  ('en.sahih', 84, 10, 5894, 'But as for he who is given his record behind his back,', NULL, NULL, '2e422094ee53058373a2c7636c5bc3320f249731ec2e80cf3157431f22a1f451'),
  ('en.sahih', 84, 11, 5895, 'He will cry out for destruction', NULL, NULL, '86539bc2286c94996ad59cf4ef1f89ccc0af9ae1aba7f66f6ffa8c0c892ea069'),
  ('en.sahih', 84, 12, 5896, 'And [enter to] burn in a Blaze.', NULL, NULL, '9375b89cd3aef059f5bbf5ea5cfd783f1cc94a02239aa12193430797d4bb82d4'),
  ('en.sahih', 84, 13, 5897, 'Indeed, he had [once] been among his people in happiness;', NULL, NULL, '673a307349e6302381670bda22f520da05fefb05e3f03dbdf5f0b0f7ea47ce83'),
  ('en.sahih', 84, 14, 5898, 'Indeed, he had thought he would never return [to Allah].', NULL, NULL, '809b54994eb222f8bccf567491ca9fde5925545629b92ddb28cdfc737289717b'),
  ('en.sahih', 84, 15, 5899, 'But yes! Indeed, his Lord was ever of him, Seeing.', NULL, NULL, '1524fddb7a26f1f4ebc0d83619fa18ef9db9c27ea5f0aa935cadca953b37ac27'),
  ('en.sahih', 84, 16, 5900, 'So I swear by the twilight glow', NULL, NULL, 'c0c2ef39a72cf5aac6a45bd9c1c6d47a084866adada50ab5590ea7dfb17930dd')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 84, 17, 5901, 'And [by] the night and what it envelops', NULL, NULL, '4a39583ea3920dba3ef94b54d040f9e3e8cac921e2b249b2405c981736a84f46'),
  ('en.sahih', 84, 18, 5902, 'And [by] the moon when it becomes full', NULL, NULL, 'f11c1e662f69a943de595743b2aa991f7360c4831783efd294ce11f028c1d472'),
  ('en.sahih', 84, 19, 5903, '[That] you will surely experience state after state.', NULL, NULL, '3e4fcf3b2cfa5768b9bcc901be64825d5ac91d693e48517efdedc6509fc4eb6e'),
  ('en.sahih', 84, 20, 5904, 'So what is [the matter] with them [that] they do not believe,', NULL, NULL, '70cafea022a987dd77236fabf67934367a1dea832659de88246243ed862c5b79'),
  ('en.sahih', 84, 21, 5905, 'And when the Qur''an is recited to them, they do not prostrate [to Allah]?', NULL, NULL, '7ccf9cc74099d3daa91cc750be44798e979ab8736cd0c127c90132d07dc26537'),
  ('en.sahih', 84, 22, 5906, 'But those who have disbelieved deny,', NULL, NULL, 'eadc9ae9ba18e17df5b4d59c31b48ebd7ecd8e818256a43fa27a14bda3be8c25'),
  ('en.sahih', 84, 23, 5907, 'And Allah is most knowing of what they keep within themselves.', NULL, NULL, 'fd7b876b73a57d74f072bd94bbf4437268c4320a3f0d2e54d237c5c3b0ebe9c8'),
  ('en.sahih', 84, 24, 5908, 'So give them tidings of a painful punishment,', NULL, NULL, 'c04dfa3122f3b7190cc9ce567fdbc319b6d7eac930ba866d715000059a42ed1a'),
  ('en.sahih', 84, 25, 5909, 'Except for those who believe and do righteous deeds. For them is a reward uninterrupted.', NULL, NULL, '72b58323f4dfefa4f1392516f17700f2967f06c5e5bf2c22dae174b2f06c676c'),
  ('en.sahih', 85, 1, 5910, 'By the sky containing great stars', NULL, NULL, '989e2aadcac3e2c154500747eb1a1264d0109c2cfc9beaffbd43340803ba5efb'),
  ('en.sahih', 85, 2, 5911, 'And [by] the promised Day', NULL, NULL, '0b6206b2c6bf346fa48cc73c5ead42c30de5c02d7cc644a1f0ff232c8bb1ab40'),
  ('en.sahih', 85, 3, 5912, 'And [by] the witness and what is witnessed,', NULL, NULL, '05bf7872527979a72ba107a53a1144e8b302bcf189aab6ea87ae308de8962df7'),
  ('en.sahih', 85, 4, 5913, 'Cursed were the companions of the trench', NULL, NULL, '98626ec20cddb28165fa5581ce43601075f0e9b04c2a1b98c03556900bf4ef23'),
  ('en.sahih', 85, 5, 5914, '[Containing] the fire full of fuel,', NULL, NULL, '94ac2786f6dd107f2673839bd7ec3b082d7924ea3d4c307816c3704b8558e384'),
  ('en.sahih', 85, 6, 5915, 'When they were sitting near it', NULL, NULL, 'e3ec696804554a258ddbf862e7253edd87dd1cefeb4b3b23da9b60a7a82fdb3d'),
  ('en.sahih', 85, 7, 5916, 'And they, to what they were doing against the believers, were witnesses.', NULL, NULL, 'ab401479b0f93b0c75f3f606b900a200da8cd506d770c02be94a4800d938434d'),
  ('en.sahih', 85, 8, 5917, 'And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,', NULL, NULL, '34c01d7993cb054f840a330fb253d71e099fb831166a616667fcc67ddb74863b'),
  ('en.sahih', 85, 9, 5918, 'To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness.', NULL, NULL, '2b2f26bca67a5c7349f75872a48f348e8b9bfa5fd56aca0ce6a94c46bf121a37'),
  ('en.sahih', 85, 10, 5919, 'Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.', NULL, NULL, 'a5d3cf80523b03a297c0c38c71d34cd7b6fb7067a547ba9754a528f782408f39'),
  ('en.sahih', 85, 11, 5920, 'Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.', NULL, NULL, 'b9f09ab5b0ec2f6ec2dd5960672d8b0a4637f4c9dcaf5e048944c03ca267a8ad'),
  ('en.sahih', 85, 12, 5921, 'Indeed, the vengeance of your Lord is severe.', NULL, NULL, '695de6a939ba9123dd040df6dc88cd6411bc8901ecd2bb72198cef56d2520365'),
  ('en.sahih', 85, 13, 5922, 'Indeed, it is He who originates [creation] and repeats.', NULL, NULL, 'df30c323a83157d687b8b149071d62d1ad53296bf07746f887dcfdce6afd62bf'),
  ('en.sahih', 85, 14, 5923, 'And He is the Forgiving, the Affectionate,', NULL, NULL, '5f72b459b3645fc52c00c5e72fadb7575935b71619da8ae54e7cfedf603502c0'),
  ('en.sahih', 85, 15, 5924, 'Honorable Owner of the Throne,', NULL, NULL, 'c506a8b82f5b665815c78bb85a4dd375b42d538f05d3cfb8d36e4c4321f7ca3f'),
  ('en.sahih', 85, 16, 5925, 'Effecter of what He intends.', NULL, NULL, '9956e10f5c8126bc73bc0a4e593a37762a6fd182d7fadb1b4477db7dd2181c49'),
  ('en.sahih', 85, 17, 5926, 'Has there reached you the story of the soldiers -', NULL, NULL, '638910852312fce82fbc88538b421c6b07a21391e40c5735dc9875ada29b8ace'),
  ('en.sahih', 85, 18, 5927, '[Those of] Pharaoh and Thamud?', NULL, NULL, '16a31985103eb38acc18a710ebc0418b816f5c6984534e3774ea4dbd44b39b38'),
  ('en.sahih', 85, 19, 5928, 'But they who disbelieve are in [persistent] denial,', NULL, NULL, 'e0e4179eec9fee3a03737a372f69b12f3049c1f032144247dd198c62c2d75b15'),
  ('en.sahih', 85, 20, 5929, 'While Allah encompasses them from behind.', NULL, NULL, 'edb4cbef21e984ebb6d4051111eed72380b1ffd7392602597634ad10442db6e3'),
  ('en.sahih', 85, 21, 5930, 'But this is an honored Qur''an', NULL, NULL, 'd09a2b6cdb6237b278b5597d69ce80359dfc7b33f0fd9fdcebdf18ae0c429263'),
  ('en.sahih', 85, 22, 5931, '[Inscribed] in a Preserved Slate.', NULL, NULL, 'b8f233690b75dfa5fdf3508e2e663566088c99f9149b2b4a513709aa35849f3c'),
  ('en.sahih', 86, 1, 5932, 'By the sky and the night comer -', NULL, NULL, 'fead39b7e533e14596cc88cbf01c8d0880fad3ee729a66e8a86645b75169b1ca'),
  ('en.sahih', 86, 2, 5933, 'And what can make you know what is the night comer?', NULL, NULL, 'c23e8a047e8d49dde57d9be893b2b64c533cb90c06ddfbb102f237121bef2c84'),
  ('en.sahih', 86, 3, 5934, 'It is the piercing star -', NULL, NULL, 'd066e8e6de725193c52eb821a0e817139da253bf224fd30b585f2bd31b62fd01'),
  ('en.sahih', 86, 4, 5935, 'There is no soul but that it has over it a protector.', NULL, NULL, 'cc37a6d6065e45cb36cef765cc32d434e62029e5e641dc28299fdf0ae3f30510'),
  ('en.sahih', 86, 5, 5936, 'So let man observe from what he was created.', NULL, NULL, 'c2962c72a9715d21fbf03a5798a3177f005ff3c03bd35c35f96e7e85b7bd2e42'),
  ('en.sahih', 86, 6, 5937, 'He was created from a fluid, ejected,', NULL, NULL, '6f5045b1fcb0eadd28df9fe4fe4e2de5a6ba7c8e664f4d937ee42ecc080f13fd'),
  ('en.sahih', 86, 7, 5938, 'Emerging from between the backbone and the ribs.', NULL, NULL, 'e346cbef0f545719b749c085b7efe9899395e39fc7f08cbccb939fafce784680'),
  ('en.sahih', 86, 8, 5939, 'Indeed, Allah, to return him [to life], is Able.', NULL, NULL, '7e592b7f20b3f0073bf62be5ed894d01fc9c71c68fc113c0132a2cfd1437560e'),
  ('en.sahih', 86, 9, 5940, 'The Day when secrets will be put on trial,', NULL, NULL, 'f0d71cedac217db9139aa6cbe761aa8b72363c1dccd274467013e5f331530cd1'),
  ('en.sahih', 86, 10, 5941, 'Then man will have no power or any helper.', NULL, NULL, 'b0dfd53b6e65d85aeafc521b5da132f7043d5c01b17065b94cf7edc66008edaf'),
  ('en.sahih', 86, 11, 5942, 'By the sky which returns [rain]', NULL, NULL, '711b0d2954649e36814628ada9285045f13911da105ba01c2b09fc475a0163bb'),
  ('en.sahih', 86, 12, 5943, 'And [by] the earth which cracks open,', NULL, NULL, '4836522a2638b976d31fbd26bf0f9ea4f188a9bf5250f4b55e00c72207f89b7d'),
  ('en.sahih', 86, 13, 5944, 'Indeed, the Qur''an is a decisive statement,', NULL, NULL, '5c1110b071a58263b61dca65df72e034a9971175ae85d36d30ae534e8e549f50'),
  ('en.sahih', 86, 14, 5945, 'And it is not amusement.', NULL, NULL, '20a7e72671d8adfa46fc125cd9074eeb1c2cadf5c3fbed6e5e438f23894e8bd4'),
  ('en.sahih', 86, 15, 5946, 'Indeed, they are planning a plan,', NULL, NULL, '9f8661c80e86d0da8b0e50bcaefff8206b12baac4f4fca434e6558c9e9e1ac93'),
  ('en.sahih', 86, 16, 5947, 'But I am planning a plan.', NULL, NULL, 'cbe34705728b6d4ea2f0f0b1fa25f2478c4ff636434aded5d9697ab603fe2fe1'),
  ('en.sahih', 86, 17, 5948, 'So allow time for the disbelievers. Leave them awhile.', NULL, NULL, 'b5655344a4c53061f34fefa13431f128a1bc6a01e08fb7780d804f8800f64a14'),
  ('en.sahih', 87, 1, 5949, 'Exalt the name of your Lord, the Most High,', NULL, NULL, 'e86dfd017e07f1576c4a3302f5a41352726f09306e285698e7825fc417a76a75'),
  ('en.sahih', 87, 2, 5950, 'Who created and proportioned', NULL, NULL, '8e2f29f1cf9c6b4c683d60f539910a2c0de1dd1c686e077c1a1fc61aefa4eb77'),
  ('en.sahih', 87, 3, 5951, 'And who destined and [then] guided', NULL, NULL, 'eb538c54aa3df086eff6c5c94b3f687e3aae78badb1b62bf96da751c4364e713'),
  ('en.sahih', 87, 4, 5952, 'And who brings out the pasture', NULL, NULL, '6857318fd0403143b7d7782b6f60c80c9d6a89127bedb44c6833b2d3af66434e'),
  ('en.sahih', 87, 5, 5953, 'And [then] makes it black stubble.', NULL, NULL, '447906b06e4b4d8d078c0bb05d78f5590b830435c7f15ffce61ce3a84ce137c3'),
  ('en.sahih', 87, 6, 5954, 'We will make you recite, [O Muhammad], and you will not forget,', NULL, NULL, '2f36b080b1d4f41b23eb7d523d394a9ef71986bfe093b4500b364f88dda08563'),
  ('en.sahih', 87, 7, 5955, 'Except what Allah should will. Indeed, He knows what is declared and what is hidden.', NULL, NULL, 'bbddb6befd6fb77fd6ade12722baa8dd9827906e7edf462c1d8e86d97b84a6bd'),
  ('en.sahih', 87, 8, 5956, 'And We will ease you toward ease.', NULL, NULL, '49f4a9b34b2713c4531c89d9334469d78bc6c85473f1e073707e948db630f32a'),
  ('en.sahih', 87, 9, 5957, 'So remind, if the reminder should benefit;', NULL, NULL, 'af9fa24b5e41ad64002ee23f20b6370dd0d6fc6570e2431b858aa43765968e3c'),
  ('en.sahih', 87, 10, 5958, 'He who fears [Allah] will be reminded.', NULL, NULL, 'e3856b2816d612431cc5f8ae15c20aba571b7f6790b3f4cba5acf0a76d308aaa'),
  ('en.sahih', 87, 11, 5959, 'But the wretched one will avoid it -', NULL, NULL, '9b125f7144069f399f60add2bd73637af6cb2537fe97b8625440e45029828368'),
  ('en.sahih', 87, 12, 5960, '[He] who will [enter and] burn in the greatest Fire,', NULL, NULL, '8117825019e2ddb946126b9a28e131c471b5296b99f5f6319c6e36502845cd11'),
  ('en.sahih', 87, 13, 5961, 'Neither dying therein nor living.', NULL, NULL, '0f698647378d2ff14f48351fd611c359a35807a7a893c5d60a1c4e2d148b725a'),
  ('en.sahih', 87, 14, 5962, 'He has certainly succeeded who purifies himself', NULL, NULL, '2366ce7623a18287e0d95b5c1d5f9dd99987d8128bf014fc7301eb6eb1ab13b3'),
  ('en.sahih', 87, 15, 5963, 'And mentions the name of his Lord and prays.', NULL, NULL, '00a821a91d5e7e5ee01ffd6124d988cd1832954aae0039d639bc0908190b3990'),
  ('en.sahih', 87, 16, 5964, 'But you prefer the worldly life,', NULL, NULL, '421b32b91c7b514a3420996989b5a5b14717764c9f1a825b0fff3ab565370ec7'),
  ('en.sahih', 87, 17, 5965, 'While the Hereafter is better and more enduring.', NULL, NULL, '49e8d6121f284f33b7ee595c3bc4e95f9f396e5c009d97e1143290fef2b2d303'),
  ('en.sahih', 87, 18, 5966, 'Indeed, this is in the former scriptures,', NULL, NULL, 'e5c0dd92dccff1ce6f5e4651611a6841feb50a1c53ab263030afb6466553d0bc'),
  ('en.sahih', 87, 19, 5967, 'The scriptures of Abraham and Moses.', NULL, NULL, '8a83497ee7291514f7f5d1a06f527a218f8009b2b04b9113ec62e1181a939d07'),
  ('en.sahih', 88, 1, 5968, 'Has there reached you the report of the Overwhelming [event]?', NULL, NULL, 'cfadaef22be7d23d589becedafa29404b88a6b5f579e74944b98daddede96bb3'),
  ('en.sahih', 88, 2, 5969, '[Some] faces, that Day, will be humbled,', NULL, NULL, 'a83ff00f75344c0a51d8503ca9dcd6bc82f7a0bb827007b2771623661f94bdc3'),
  ('en.sahih', 88, 3, 5970, 'Working [hard] and exhausted.', NULL, NULL, '9f94f700bf6eb976973a85fb385fbde1ac7751eec181ab3ed3e749d953f497d4'),
  ('en.sahih', 88, 4, 5971, 'They will [enter to] burn in an intensely hot Fire.', NULL, NULL, 'fdf5f007f1df2cb0108f320033817401c20299c1e896bf1688007fecd4aa3c98'),
  ('en.sahih', 88, 5, 5972, 'They will be given drink from a boiling spring.', NULL, NULL, '628dc9d3abf21b8a6dc735dcf89e48579cd27033dcc2894cf65e25329865e5a6'),
  ('en.sahih', 88, 6, 5973, 'For them there will be no food except from a poisonous, thorny plant', NULL, NULL, '6c564828d5be91a4120277d4d4eeb6bae6c6e1e16bf411469cea56d9a86ad27d'),
  ('en.sahih', 88, 7, 5974, 'Which neither nourishes nor avails against hunger.', NULL, NULL, '6c2ad927518ffe4aeb6c265130a984fd27cb3bd26eab23c1c635a71f8f5303ed'),
  ('en.sahih', 88, 8, 5975, '[Other] faces, that Day, will show pleasure.', NULL, NULL, 'b3fac8161b18992e63da8986d655ed5d44341456326c1bc954a50c4b1ef9784c'),
  ('en.sahih', 88, 9, 5976, 'With their effort [they are] satisfied', NULL, NULL, '1569722a9ba926c595572471ce03da312e4ebc79986fea54714af937d50ac229'),
  ('en.sahih', 88, 10, 5977, 'In an elevated garden,', NULL, NULL, '6d636554d8ad1f9eb1fa517543dc81bfd5457510712a2a59d19bedfde52d96c0'),
  ('en.sahih', 88, 11, 5978, 'Wherein they will hear no unsuitable speech.', NULL, NULL, 'c96497b6c44d87c10ad84c24c7a9b51b9180c7ec1c924ddcb5a1bb0dda8e34e1'),
  ('en.sahih', 88, 12, 5979, 'Within it is a flowing spring.', NULL, NULL, '1c4eb13d4e41b027e480ffcffc939c8da80983aa174603a41102dadc34ad4525'),
  ('en.sahih', 88, 13, 5980, 'Within it are couches raised high', NULL, NULL, '692ec5040761385d19c57df9ba112dcfb432f44ccdd490db33aa41e7ed6a0d22'),
  ('en.sahih', 88, 14, 5981, 'And cups put in place', NULL, NULL, 'df15ecdfabe2e782bcee6ee120b6e6b4f7256ac6f40c372cef117c8290ad4c0c'),
  ('en.sahih', 88, 15, 5982, 'And cushions lined up', NULL, NULL, '3b2ec163dcd7f3c31114f310038d160e67cd33ef0345d6f11ba97e77be180f02'),
  ('en.sahih', 88, 16, 5983, 'And carpets spread around.', NULL, NULL, '98b8e2b60020fed4c9010f9c2e694dd67e219ed6ef2278a37b3d462a238e2840'),
  ('en.sahih', 88, 17, 5984, 'Then do they not look at the camels - how they are created?', NULL, NULL, '9591adcd41c0c6c47deef55bb64bae76390721e79b43f754e0a0346220847492'),
  ('en.sahih', 88, 18, 5985, 'And at the sky - how it is raised?', NULL, NULL, 'd8ba845c99cb95cff8b360ae166b51fa804a47ba9ed36cec1cb88639fa3c8901'),
  ('en.sahih', 88, 19, 5986, 'And at the mountains - how they are erected?', NULL, NULL, 'd4a0a4d3a49ee05d20ac49eeb1aaa4f59e38ac0979ccc034880dc80c554310ee'),
  ('en.sahih', 88, 20, 5987, 'And at the earth - how it is spread out?', NULL, NULL, 'c62b2e186322e40cbc23948411ac22aacf2a167a5730ba68ee8feebedc89288b'),
  ('en.sahih', 88, 21, 5988, 'So remind, [O Muhammad]; you are only a reminder.', NULL, NULL, 'd8f256f237f906607d0418627caa660c645dc183c89f7c0cd8ac43a80905e25c'),
  ('en.sahih', 88, 22, 5989, 'You are not over them a controller.', NULL, NULL, '6ac304a084754d3723c65908c7d43d4cc2504c0b080b33e5af1244e286ffe0d9'),
  ('en.sahih', 88, 23, 5990, 'However, he who turns away and disbelieves -', NULL, NULL, 'd30b559d5b415ed5df1a974fe862bf16f9c8f68bad170e2c259991d79dd37d3b'),
  ('en.sahih', 88, 24, 5991, 'Then Allah will punish him with the greatest punishment.', NULL, NULL, 'd248a957c50eb6a24544399787e89e58c01c72eebd2fc09ef6b76cb74a5b2d11'),
  ('en.sahih', 88, 25, 5992, 'Indeed, to Us is their return.', NULL, NULL, 'dafc98961c6e105de04a6619325e72a366d29332038242bd89abe6faf08c1164'),
  ('en.sahih', 88, 26, 5993, 'Then indeed, upon Us is their account.', NULL, NULL, 'b02d7ec40e5b955b8f9a2da557deb4be48f1e5e536c8e951316cf89f63b1e421'),
  ('en.sahih', 89, 1, 5994, 'By the dawn', NULL, NULL, '985e03f24f1edaf4a729801f0f30f7fcb6c423749ca2363347b297480fd6bac4'),
  ('en.sahih', 89, 2, 5995, 'And [by] ten nights', NULL, NULL, '572aa982219f184cccefb7cce55a3083c0c37db546c12a7b56f5d5252a60552d'),
  ('en.sahih', 89, 3, 5996, 'And [by] the even [number] and the odd', NULL, NULL, '93df08d8e007dee5f7be4c9c10eca7cd654b82f04efa42808e7b7405cfd1c20c'),
  ('en.sahih', 89, 4, 5997, 'And [by] the night when it passes,', NULL, NULL, '1f2e807cc0f5795451cd4e16e7d8979f7ba89b1208f0f70105e16c9b7df2bbae'),
  ('en.sahih', 89, 5, 5998, 'Is there [not] in [all] that an oath [sufficient] for one of perception?', NULL, NULL, 'ae0c658dbc00b93006cbd6399333cc01774a4b9ba620b0836823bfe0c8f9fa41'),
  ('en.sahih', 89, 6, 5999, 'Have you not considered how your Lord dealt with ''Aad -', NULL, NULL, 'd86a1d96f8c75a4d33d9229ccc81981dbdc4aac88463bad0a64855e4aa11242b'),
  ('en.sahih', 89, 7, 6000, '[With] Iram - who had lofty pillars,', NULL, NULL, 'f9aff6a21ac0e7e00e43cc22c733c1eb63bc484c8cab9c9f707b4dad42552d62')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 89, 8, 6001, 'The likes of whom had never been created in the land?', NULL, NULL, '0342be003d60a52bac3d2b5096dae6c5f28fab13236fcf20ec2bf82eb137a880'),
  ('en.sahih', 89, 9, 6002, 'And [with] Thamud, who carved out the rocks in the valley?', NULL, NULL, '3408e4ae040ec21cdf0488786aa8c9355487cca8308bf7c1071a8a8dfc8677e9'),
  ('en.sahih', 89, 10, 6003, 'And [with] Pharaoh, owner of the stakes? -', NULL, NULL, '15e404fcffea6cfe6396093b6598ae55a31532619257f200a47a65916230074a'),
  ('en.sahih', 89, 11, 6004, '[All of] whom oppressed within the lands', NULL, NULL, '80911d794fac43efdf36fe9a546526545050d5f5ef1b4eb4d1c01b9445855761'),
  ('en.sahih', 89, 12, 6005, 'And increased therein the corruption.', NULL, NULL, '387f4c4ef254eb6d9ecd581589e5f40ff28dcd73321ac615881731d3b1345224'),
  ('en.sahih', 89, 13, 6006, 'So your Lord poured upon them a scourge of punishment.', NULL, NULL, '95ba864e2948f5d31084da239e2fb80b724789ce7531eee575dc176bac471e08'),
  ('en.sahih', 89, 14, 6007, 'Indeed, your Lord is in observation.', NULL, NULL, 'a20a0f61ad97897bf2a3892863848f4dc4241d4738b55e76c3380f601272178c'),
  ('en.sahih', 89, 15, 6008, 'And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, "My Lord has honored me."', NULL, NULL, '96c97baf164399f875a4960b7798e35fe74186a20d72b9aa440efe12c8699e19'),
  ('en.sahih', 89, 16, 6009, 'But when He tries him and restricts his provision, he says, "My Lord has humiliated me."', NULL, NULL, '24d4f44986499b1a68a03016d35e5ec8f46195c884b3a6205129e0bc66b4c35c'),
  ('en.sahih', 89, 17, 6010, 'No! But you do not honor the orphan', NULL, NULL, 'efd72ae2b8fde5f4f888071fa8a79555f026f161c7b853e8550b8a0531a7e1cc'),
  ('en.sahih', 89, 18, 6011, 'And you do not encourage one another to feed the poor.', NULL, NULL, 'bbf36bbce075ce1f8a2412e65a5c5882d13e6c9c9da7603bd1a92970061d1862'),
  ('en.sahih', 89, 19, 6012, 'And you consume inheritance, devouring [it] altogether,', NULL, NULL, '20aa04dcbe3c80eccbc37fd286d79c20d5cc698ca2c0cd34e9e7849e39c60496'),
  ('en.sahih', 89, 20, 6013, 'And you love wealth with immense love.', NULL, NULL, 'c8c9b6a3d59d49a0f24cbed30a3d1ee0c5fba2eb32be9cf256edd9f2897dbf0f'),
  ('en.sahih', 89, 21, 6014, 'No! When the earth has been leveled - pounded and crushed -', NULL, NULL, '29e9f2ee4f024f8ffe4d6a623952cd4bc467a741d063943283a99d70b6c8f576'),
  ('en.sahih', 89, 22, 6015, 'And your Lord has come and the angels, rank upon rank,', NULL, NULL, '7482e9454957113fa6603895c047e7f1f618a29ff23d24a661df9e97a1e866c8'),
  ('en.sahih', 89, 23, 6016, 'And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance?', NULL, NULL, '85d267e37ad8a23d1075354f85809deeb2d408c4397f58cbade916f14c100245'),
  ('en.sahih', 89, 24, 6017, 'He will say, "Oh, I wish I had sent ahead [some good] for my life."', NULL, NULL, '0d17950a6a745341e5d6f6ce912cea339558512b564416197767979aff12da75'),
  ('en.sahih', 89, 25, 6018, 'So on that Day, none will punish [as severely] as His punishment,', NULL, NULL, 'da1d211728d9bb01e1e34cae3e9f4dc5b9dabd761af90cdd63088ed2af11818b'),
  ('en.sahih', 89, 26, 6019, 'And none will bind [as severely] as His binding [of the evildoers].', NULL, NULL, '9c46bf0b991ad25de99b69eca109ad50572e855d5a6a0d9a35ede919f6de17fb'),
  ('en.sahih', 89, 27, 6020, '[To the righteous it will be said], "O reassured soul,', NULL, NULL, '58c9db8511d12c49625aac0fc4310c6eea027ad9b7de16f3ccc8e01560cc8406'),
  ('en.sahih', 89, 28, 6021, 'Return to your Lord, well-pleased and pleasing [to Him],', NULL, NULL, '37212ead95af1207d9ec991ce57b747fa60874d6a11a60eab357e667752e3234'),
  ('en.sahih', 89, 29, 6022, 'And enter among My [righteous] servants', NULL, NULL, '3df9e636630c5ebe4ccd8829c2fe0f8c44355db53fec042f8bab76e8c76b1057'),
  ('en.sahih', 89, 30, 6023, 'And enter My Paradise."', NULL, NULL, 'd27f00f0bc51957f3ffeaa503c95d77ee5cef8920973c990f7de788f85ee95ec'),
  ('en.sahih', 90, 1, 6024, 'I swear by this city, Makkah -', NULL, NULL, '350a351a397ccd57912bf024af01717840769d997855510acb0d9c6a3494869e'),
  ('en.sahih', 90, 2, 6025, 'And you, [O Muhammad], are free of restriction in this city -', NULL, NULL, '60c695405685c006a3ca90a76b5d627189ae3a0fc5874476c1b7cd150c4233d5'),
  ('en.sahih', 90, 3, 6026, 'And [by] the father and that which was born [of him],', NULL, NULL, 'ed5d790633902c4d09255a0d25f044f924652af262bc2e1806483822674eabc4'),
  ('en.sahih', 90, 4, 6027, 'We have certainly created man into hardship.', NULL, NULL, '5431c7602bf04977c4a7e0214d2cd6abe38f2ef0e4269ffeef8e8608b5587adb'),
  ('en.sahih', 90, 5, 6028, 'Does he think that never will anyone overcome him?', NULL, NULL, '96d13d43dd9beb6780117f27dfa5da14956041b85e53ed0ec48b82d2a1ce365b'),
  ('en.sahih', 90, 6, 6029, 'He says, "I have spent wealth in abundance."', NULL, NULL, 'b170845969cbacc4ab4129129e49edff915cee969159a36b3cbf61d796054ba4'),
  ('en.sahih', 90, 7, 6030, 'Does he think that no one has seen him?', NULL, NULL, 'bc9bfe418fa9154dbb0220447902c23bd23fc659e87083d1ac6e1589e9c4ae07'),
  ('en.sahih', 90, 8, 6031, 'Have We not made for him two eyes?', NULL, NULL, 'e957d170ceedd295b5163f18840bf1aa515f70d1d590425e830ffd84b791881a'),
  ('en.sahih', 90, 9, 6032, 'And a tongue and two lips?', NULL, NULL, '1ddcbda602e32cbf6f528b5c9007998de862e7aa23de8db335551eccbd66e15e'),
  ('en.sahih', 90, 10, 6033, 'And have shown him the two ways?', NULL, NULL, 'e04f03b3be82d055e4dbb5bf9286c8c5cd801454e65e80ad2bb74d2c8647efe3'),
  ('en.sahih', 90, 11, 6034, 'But he has not broken through the difficult pass.', NULL, NULL, '2361c15d780ee833726f30d4391072db04eff1363ce46224e8022d53e693849e'),
  ('en.sahih', 90, 12, 6035, 'And what can make you know what is [breaking through] the difficult pass?', NULL, NULL, '34b1b8886363128b8140b52087afd1bf5b5f6331440f8d2f54121814d019067a'),
  ('en.sahih', 90, 13, 6036, 'It is the freeing of a slave', NULL, NULL, '97025f7935ab82b6ba60130a9d59a154e4d0eae5adec396871b856310c7c460e'),
  ('en.sahih', 90, 14, 6037, 'Or feeding on a day of severe hunger', NULL, NULL, '2f8cf3c4f08e23bb177367ef784fd037c763f506e88b9a3f751688fc1ce79cee'),
  ('en.sahih', 90, 15, 6038, 'An orphan of near relationship', NULL, NULL, 'fcd25ebb78613c4b4ea9cadbe1cdaf0ced2e2359481f51ba8a93212854cc6cf4'),
  ('en.sahih', 90, 16, 6039, 'Or a needy person in misery', NULL, NULL, 'c8da00c487ff44e0a11431af16e5a968fdf0bd4635df93587cf077c818f0119a'),
  ('en.sahih', 90, 17, 6040, 'And then being among those who believed and advised one another to patience and advised one another to compassion.', NULL, NULL, 'b464e49997f5a397b1baa45d8ba1582b3d3a129f8d8d50fc35f901be958684c4'),
  ('en.sahih', 90, 18, 6041, 'Those are the companions of the right.', NULL, NULL, '44d04251328fd461d1ccde02d6a819014186c4f33c4bf29092a6ff2fca703731'),
  ('en.sahih', 90, 19, 6042, 'But they who disbelieved in Our signs - those are the companions of the left.', NULL, NULL, '813e7192656c3b31ae53967a323f3fa8eca3f96cd00c90ec32dcb21043f56e39'),
  ('en.sahih', 90, 20, 6043, 'Over them will be fire closed in.', NULL, NULL, '298da00580ff0ca743f1d269e73b3cc43308e67a78a15b2abacbd709243774ce'),
  ('en.sahih', 91, 1, 6044, 'By the sun and its brightness', NULL, NULL, 'ba765bc6fc09676f0ae498578b86d878b6433574f9e5bfcdcebdc622910826aa'),
  ('en.sahih', 91, 2, 6045, 'And [by] the moon when it follows it', NULL, NULL, '39c4f2db944ac11d8616fd75e225a27731e747a4b7ce76b753025b3b63cd5660'),
  ('en.sahih', 91, 3, 6046, 'And [by] the day when it displays it', NULL, NULL, '8f47f69b1d2fef54965cd2b49b620c38849212485b56059cf7e6e0237939be15'),
  ('en.sahih', 91, 4, 6047, 'And [by] the night when it covers it', NULL, NULL, '5ab2245808d6b7a2bf365e8b8085728182331250272212abcc09a1bd6bd48887'),
  ('en.sahih', 91, 5, 6048, 'And [by] the sky and He who constructed it', NULL, NULL, '4a42554a079e1f00ee5a55f291603918b67ee46e366d987adb557ed10e1b0823'),
  ('en.sahih', 91, 6, 6049, 'And [by] the earth and He who spread it', NULL, NULL, '2e9c9403a7018df520f3350b9cf037cb6fc1bce8595b5a60b849769bf9b614ad'),
  ('en.sahih', 91, 7, 6050, 'And [by] the soul and He who proportioned it', NULL, NULL, '35a0b048bd094c8e972eb18e4267c09777ed54fd770f92d518d3dd22a9f7b46a'),
  ('en.sahih', 91, 8, 6051, 'And inspired it [with discernment of] its wickedness and its righteousness,', NULL, NULL, '40f369638cc5cc74ad0585afddd0bdac5d44a64f77b6702ff30368f2618bf0c2'),
  ('en.sahih', 91, 9, 6052, 'He has succeeded who purifies it,', NULL, NULL, 'e9ebc0612eeef62b782161f88996b51df8fb9d6cf76b8dfe3471d5acc186f325'),
  ('en.sahih', 91, 10, 6053, 'And he has failed who instills it [with corruption].', NULL, NULL, '211f4c9968f8843e05e6517eb61b6e542400b7c2d3ea92d78627b2ee89f47462'),
  ('en.sahih', 91, 11, 6054, 'Thamud denied [their prophet] by reason of their transgression,', NULL, NULL, '5369493e9172dfea0d9e7e2dd97309ece960fd03f97619a4eaf50f5133758872'),
  ('en.sahih', 91, 12, 6055, 'When the most wretched of them was sent forth.', NULL, NULL, 'b0d4e4d74cdc980674b5c60e839a2d534bbeaaeedb933ac8a5d90f053442c623'),
  ('en.sahih', 91, 13, 6056, 'And the messenger of Allah [Salih] said to them, "[Do not harm] the she-camel of Allah or [prevent her from] her drink."', NULL, NULL, 'e18908bc6d4cb16bc1191d6add56ef522f414a6b4aa7c87a07976934d9234efa'),
  ('en.sahih', 91, 14, 6057, 'But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].', NULL, NULL, '0efb2993888a3653f557565e9e90985183cc7f1216b7b6e89fb2ea3db947b031'),
  ('en.sahih', 91, 15, 6058, 'And He does not fear the consequence thereof.', NULL, NULL, '46a27870bb513f551508ba215c2f43c53fcf7c808f64987a1347d4b567adfecb'),
  ('en.sahih', 92, 1, 6059, 'By the night when it covers', NULL, NULL, '61c83c72d28e0f53f3b223614b39858e59c8e771f9ed7bc2b2bc0f179d1d505a'),
  ('en.sahih', 92, 2, 6060, 'And [by] the day when it appears', NULL, NULL, '4bd2d204de7b324e115e96b017b47827a9b52e42e403f226c80eb82cd984927c'),
  ('en.sahih', 92, 3, 6061, 'And [by] He who created the male and female,', NULL, NULL, '43b40811a03a95f4fa7f381233ef62b6c4f2b49d4931e0192b5f8ec86c541f22'),
  ('en.sahih', 92, 4, 6062, 'Indeed, your efforts are diverse.', NULL, NULL, '9ea64f2d813f71cd860a36f40eec845b3ba140587b55212ab396525a03f0b592'),
  ('en.sahih', 92, 5, 6063, 'As for he who gives and fears Allah', NULL, NULL, 'cf41f567c1377488e99dae062dfbda757d4b8ae6e489871b7006a55093a0ec76'),
  ('en.sahih', 92, 6, 6064, 'And believes in the best [reward],', NULL, NULL, '5c225e734c0e30968ff6139eb47d23520325e7dde58fbcf5c779a27663e02d0b'),
  ('en.sahih', 92, 7, 6065, 'We will ease him toward ease.', NULL, NULL, 'aa9a33dc81046b693fe02b53d621fbf31166dabc92bffc7652a5c16a3d842904'),
  ('en.sahih', 92, 8, 6066, 'But as for he who withholds and considers himself free of need', NULL, NULL, 'd7e33225c214e6e9f8409218bcb5502ddff0e40ffaa5cd3cd59e02d96cd569ea'),
  ('en.sahih', 92, 9, 6067, 'And denies the best [reward],', NULL, NULL, '67832269d06aebbb8d541f45f2a1827b53cf371e48b2aeb6f952c49207feb7f3'),
  ('en.sahih', 92, 10, 6068, 'We will ease him toward difficulty.', NULL, NULL, '62fbaf181b61b17f09beab31a9859ac6757fb64f398ca1557b492c3ec0e0c000'),
  ('en.sahih', 92, 11, 6069, 'And what will his wealth avail him when he falls?', NULL, NULL, 'ea35521ffeed40648d82b5c91e23ef1a7a316f8f39edc185c08d955025ac5985'),
  ('en.sahih', 92, 12, 6070, 'Indeed, [incumbent] upon Us is guidance.', NULL, NULL, '022ad4e5cbe28aa2afd6c9e87e96744ab140683c853c1c2eceee7d19ee30adb6'),
  ('en.sahih', 92, 13, 6071, 'And indeed, to Us belongs the Hereafter and the first [life].', NULL, NULL, '87ad2e6a7fbed355d6ed5db8eec7daef62c686508caa9c5af8148977ae848566'),
  ('en.sahih', 92, 14, 6072, 'So I have warned you of a Fire which is blazing.', NULL, NULL, 'f95e22c6146d15ab78f44ff99411feabea8ecccf284315e19e2abc4e8d591277'),
  ('en.sahih', 92, 15, 6073, 'None will [enter to] burn therein except the most wretched one.', NULL, NULL, 'b4c6c2b66c6a813dbb0341122d1cfccfbb7c76536da46e63c0835467d7dfb61c'),
  ('en.sahih', 92, 16, 6074, 'Who had denied and turned away.', NULL, NULL, '3871289263abd2e24ca609c66cae9e2fab86ca5ea28b8fc916f03587e34c8f12'),
  ('en.sahih', 92, 17, 6075, 'But the righteous one will avoid it -', NULL, NULL, '55240acbebf42549619c2acf81b009af1747d0dca70c4a76f0e3d78342531b23'),
  ('en.sahih', 92, 18, 6076, '[He] who gives [from] his wealth to purify himself', NULL, NULL, 'deaed79ffa8e5617060728cec751d62b4d300b307e3025e93d2329eb7de75722'),
  ('en.sahih', 92, 19, 6077, 'And not [giving] for anyone who has [done him] a favor to be rewarded', NULL, NULL, '3f06656becc3434cf79d7a7ced59518d336dffbb0da301f21e4346a4a9a1af57'),
  ('en.sahih', 92, 20, 6078, 'But only seeking the countenance of his Lord, Most High.', NULL, NULL, '953979086892205c7d0dcd70c7e2e21d0ff0db2e90a78722a137ba461448456e'),
  ('en.sahih', 92, 21, 6079, 'And he is going to be satisfied.', NULL, NULL, '14fc8d417fd9fe1c0ceb0f5faac8f1158f33c0ab01cb7076f19646c4c4eef470'),
  ('en.sahih', 93, 1, 6080, 'By the morning brightness', NULL, NULL, '8a2f693f05ab34b4f18ac5af035aaa6fa849e3a2df8f45e9e2cbde4672708f12'),
  ('en.sahih', 93, 2, 6081, 'And [by] the night when it covers with darkness,', NULL, NULL, 'f5a266ea4232ebbd68ea4ddc4772f5078030f4772fa1bed05c967a2c82c44eec'),
  ('en.sahih', 93, 3, 6082, 'Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you].', NULL, NULL, '27d0d772b40ef4193654041c5b3bde8ca901f3d9c56b1a7266c9a92d64e54ec3'),
  ('en.sahih', 93, 4, 6083, 'And the Hereafter is better for you than the first [life].', NULL, NULL, 'b63fa3fc5be34d02d39a09498bc063dbc40519f101d976b061ed172d7db7d56a'),
  ('en.sahih', 93, 5, 6084, 'And your Lord is going to give you, and you will be satisfied.', NULL, NULL, 'ba88fa62706151c5c7adcc55edaa2048df64602f283b9de57706222f2bdcd1b5'),
  ('en.sahih', 93, 6, 6085, 'Did He not find you an orphan and give [you] refuge?', NULL, NULL, '82ff6ab246f3605156c1365cf91ae12ad4a1b4e238e3e059a60a2712a0308551'),
  ('en.sahih', 93, 7, 6086, 'And He found you lost and guided [you],', NULL, NULL, '01607cfe4e2203fa219e8aa999c1cdaed7b6b566d8d7559f7702eb46b98efe1f'),
  ('en.sahih', 93, 8, 6087, 'And He found you poor and made [you] self-sufficient.', NULL, NULL, 'ca4fd960339bf25f35d665ffa031b8541502b71501f6e67bfc841b2586ffdc0a'),
  ('en.sahih', 93, 9, 6088, 'So as for the orphan, do not oppress [him].', NULL, NULL, '4437b8e07b707319ab572e97e333302cdb03306369f299cbec664ab4dc2e5f80'),
  ('en.sahih', 93, 10, 6089, 'And as for the petitioner, do not repel [him].', NULL, NULL, 'e326b3be6eba91a7f8154e31b5a8398d863f6751d8ddff41d6dfec37500e9a39'),
  ('en.sahih', 93, 11, 6090, 'But as for the favor of your Lord, report [it].', NULL, NULL, 'aa26e9bb5252e0f2245a225987447c730f3c24c42f7e55bbc41782e41ada50f5'),
  ('en.sahih', 94, 1, 6091, 'Did We not expand for you, [O Muhammad], your breast?', NULL, NULL, 'b42d379e381cfda5609f247f6028f58028d7646d2f87b5ee68591e9975e02d5a'),
  ('en.sahih', 94, 2, 6092, 'And We removed from you your burden', NULL, NULL, '04689d57b9b3447f326c3068dc13af7c116cf4b9657e18d9a832880eae04ff47'),
  ('en.sahih', 94, 3, 6093, 'Which had weighed upon your back', NULL, NULL, '2f282f1b0d7687234c781aaf3e2a71529c6badb831a0f59895f1c9f3ad917d32'),
  ('en.sahih', 94, 4, 6094, 'And raised high for you your repute.', NULL, NULL, '9af0daea11d955c4f18dd7ed4d810c020ad0ec81c6657a74334bb09747441dea'),
  ('en.sahih', 94, 5, 6095, 'For indeed, with hardship [will be] ease.', NULL, NULL, '6849d08ca41ef37bf28f2122cdeed4f655a6d9cd39171bc2613ca0c71e529750'),
  ('en.sahih', 94, 6, 6096, 'Indeed, with hardship [will be] ease.', NULL, NULL, '3f2f7b7c580326389c4b86e3b230d53f59fd34900e74a10a1487e5412c777457'),
  ('en.sahih', 94, 7, 6097, 'So when you have finished [your duties], then stand up [for worship].', NULL, NULL, 'd9e1a06739d116b8b6376dab771d95a1fc1011e68458f9e6ba8a9480b3b51651'),
  ('en.sahih', 94, 8, 6098, 'And to your Lord direct [your] longing.', NULL, NULL, 'b2b4ae09fe924dcf92c9d63413dedad57b3f242508892a63fbeb29b18c8bbbc6'),
  ('en.sahih', 95, 1, 6099, 'By the fig and the olive', NULL, NULL, '02dd153462d817b91e650eb781a7702bbdd4b6d3a49b774b3efce0eebed17e17'),
  ('en.sahih', 95, 2, 6100, 'And [by] Mount Sinai', NULL, NULL, '0e535e3f26fa2beab9004a686290b1ffd3442cd96abda04e2047cd52277454c8')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 95, 3, 6101, 'And [by] this secure city [Makkah],', NULL, NULL, '312b4f50432d6b6ef23d9c5351348166a97968a8aa8351ec96f56a73785f94ba'),
  ('en.sahih', 95, 4, 6102, 'We have certainly created man in the best of stature;', NULL, NULL, '8b1f34ff4a826f25778e48f7f0409e257096c598eb6dc4c3dfc69cfb161901c7'),
  ('en.sahih', 95, 5, 6103, 'Then We return him to the lowest of the low,', NULL, NULL, 'e4a1d428d05a3b0ca162c0c95dd8f095e5a00d81d583f102a264f166e1b88d1a'),
  ('en.sahih', 95, 6, 6104, 'Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.', NULL, NULL, '3b7441d193d1dbb1fea2977fcfa0a315066e0a2e772a3e0c9bd5be536b758a58'),
  ('en.sahih', 95, 7, 6105, 'So what yet causes you to deny the Recompense?', NULL, NULL, '85660a345431206ffeec993efe8509f626a716f6a7bc6297bda53f5a8ceda123'),
  ('en.sahih', 95, 8, 6106, 'Is not Allah the most just of judges?', NULL, NULL, '3398fae8796e73bfaf0596f31b3fe82dece2d2fa3db2df4a23c8b9a39450e8c6'),
  ('en.sahih', 96, 1, 6107, 'Recite in the name of your Lord who created -', NULL, NULL, '332b4c745c16834a7ea077ac32ff853b2d20e5970e8bea14734cf0570316bf66'),
  ('en.sahih', 96, 2, 6108, 'Created man from a clinging substance.', NULL, NULL, 'd5c43074dbb12e936bb9cd06b290f05db519816fef19f5e5b5bc801a2df88591'),
  ('en.sahih', 96, 3, 6109, 'Recite, and your Lord is the most Generous -', NULL, NULL, '50a2f5f533bd273f4e7f3582833a4fcc42047ad0582f47d72ba8c6f3ed69e558'),
  ('en.sahih', 96, 4, 6110, 'Who taught by the pen -', NULL, NULL, 'af30f6725b7b105cb05a91980aff28ae464fbe5ef0d67bcb3137500886e72302'),
  ('en.sahih', 96, 5, 6111, 'Taught man that which he knew not.', NULL, NULL, '3bfa2e75204333cb14cc0216471e8b199215fce0e533ec74340569323e54006a'),
  ('en.sahih', 96, 6, 6112, 'No! [But] indeed, man transgresses', NULL, NULL, 'ea38d5030811bb1e8981d16094e7d11e48884b80c2d39eae1281cf5060bc2b83'),
  ('en.sahih', 96, 7, 6113, 'Because he sees himself self-sufficient.', NULL, NULL, '94476854f1991bd5958ec0325c81b3e2c008d7724e9b4191a44642647d30b11f'),
  ('en.sahih', 96, 8, 6114, 'Indeed, to your Lord is the return.', NULL, NULL, '262c3d5c94bb78c950bc13ac84ca6b103012933f405d0222dd03e2da645131d9'),
  ('en.sahih', 96, 9, 6115, 'Have you seen the one who forbids', NULL, NULL, 'da0020ec8ce8667eed243e4aa0200862ef751a8e004676ec928bb76617093697'),
  ('en.sahih', 96, 10, 6116, 'A servant when he prays?', NULL, NULL, '2dcc102adab7023c04213d61168632540cbc57037eabe8bf24145951d63e9187'),
  ('en.sahih', 96, 11, 6117, 'Have you seen if he is upon guidance', NULL, NULL, '5288e3cdb3588218ee2a0140e6a08fe1d75892aab9420ff22a67f2dd066de3b3'),
  ('en.sahih', 96, 12, 6118, 'Or enjoins righteousness?', NULL, NULL, '069946abd8b68273facb5af14beed0772a10a2a5955eb7792cd4ab2aeeda58ed'),
  ('en.sahih', 96, 13, 6119, 'Have you seen if he denies and turns away -', NULL, NULL, '3f8f29d517489b01d87011852bbfbf5844ca5ec503a16a7da5e9cea8891c131a'),
  ('en.sahih', 96, 14, 6120, 'Does he not know that Allah sees?', NULL, NULL, '2ac2fbea2c8256a7137eba14ca47a0217f2d1310bdd676a2296a4ec88a1bdac3'),
  ('en.sahih', 96, 15, 6121, 'No! If he does not desist, We will surely drag him by the forelock -', NULL, NULL, 'ff49afc9d1b44243195808ad4a2e58aa6ff840c0e4668e0a37caf233339ff84e'),
  ('en.sahih', 96, 16, 6122, 'A lying, sinning forelock.', NULL, NULL, 'e0508e2edd8f3ccdf4d437cdb1d2ee4977f7c3e35163669382b1761e41644d01'),
  ('en.sahih', 96, 17, 6123, 'Then let him call his associates;', NULL, NULL, 'ba8cd24f81bb1905bf6792f1fb47413bfdbd7cb269d096f34d5e62e5a11d9ba5'),
  ('en.sahih', 96, 18, 6124, 'We will call the angels of Hell.', NULL, NULL, 'fa31952cccb9bb2ad4cf14c0418033cf35c307140639476288e52c0cf4827d1f'),
  ('en.sahih', 96, 19, 6125, 'No! Do not obey him. But prostrate and draw near [to Allah].', NULL, NULL, 'd2793cb2fb805f6d454ee64fb25ad6811888c286c122dcf8a16f2ade28a4a26e'),
  ('en.sahih', 97, 1, 6126, 'Indeed, We sent the Qur''an down during the Night of Decree.', NULL, NULL, '833c5f99d5cd95994b20dfbbc5e3ccc55520d44d9d6a676e48ec996845d1fa57'),
  ('en.sahih', 97, 2, 6127, 'And what can make you know what is the Night of Decree?', NULL, NULL, '18e33c607bab7b823f4ead5d0d213cd1c496b599359acb5c3eeb7bfecc0d86fd'),
  ('en.sahih', 97, 3, 6128, 'The Night of Decree is better than a thousand months.', NULL, NULL, '96c87d8b68c11f76ed7df5230de4f91139c072c5f4ab27c04736b6d3ba117e82'),
  ('en.sahih', 97, 4, 6129, 'The angels and the Spirit descend therein by permission of their Lord for every matter.', NULL, NULL, '94853d0ee4598d107035302ed8eef09cfb937131f8240a93ab6ee1787b2447c6'),
  ('en.sahih', 97, 5, 6130, 'Peace it is until the emergence of dawn.', NULL, NULL, '3b63532997f292dece4104749cffbacf34758d3089a87890d30dcfe143add508'),
  ('en.sahih', 98, 1, 6131, 'Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -', NULL, NULL, '1628e28938ddddace447373dccd75abf77c8f9208c46ece9dc07f2fb47f40fa0'),
  ('en.sahih', 98, 2, 6132, 'A Messenger from Allah, reciting purified scriptures', NULL, NULL, 'f14718fdcff55a1e04df8eb9eafe22539a875fa6945ea4f450a3ae629fbc5417'),
  ('en.sahih', 98, 3, 6133, 'Within which are correct writings.', NULL, NULL, '83892a7e317947f0f35896eb5ab18d419e1d18b525838797f1c03c44bf629493'),
  ('en.sahih', 98, 4, 6134, 'Nor did those who were given the Scripture become divided until after there had come to them clear evidence.', NULL, NULL, 'e444f29990c5afc53851b311876313f235af4795031466886961434150ddbff9'),
  ('en.sahih', 98, 5, 6135, 'And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion.', NULL, NULL, '1bb91c1a245359f4acbe352dc19e7a72f8ef500564e98cd7631a2fff32196d03'),
  ('en.sahih', 98, 6, 6136, 'Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.', NULL, NULL, '2e637540eaa4c3db2fb96ccf3d51543963e327e0d062ebc1180699aa77ceba56'),
  ('en.sahih', 98, 7, 6137, 'Indeed, they who have believed and done righteous deeds - those are the best of creatures.', NULL, NULL, '2a74e61b2ec9a61fee4eba5d813616aa5deac8441f014a9672b29158fcf88c86'),
  ('en.sahih', 98, 8, 6138, 'Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord.', NULL, NULL, '1242f36ae04325bb118859b3fe9043950f458ac8c11f9ac2d3af0e19ccde1315'),
  ('en.sahih', 99, 1, 6139, 'When the earth is shaken with its [final] earthquake', NULL, NULL, 'c002a304f37939da4e75cbe4536d9af48475f36e9079e34b1316a619c1a5e580'),
  ('en.sahih', 99, 2, 6140, 'And the earth discharges its burdens', NULL, NULL, '53d2bf8f7b6cf7460c63ebc1ecf7e8b3e55fe27eb544e5c472f18d5f6a7cabf2'),
  ('en.sahih', 99, 3, 6141, 'And man says, "What is [wrong] with it?" -', NULL, NULL, 'bda264e5e2f5ba8af4ddc2715b8380a73551439f908e713a5d2327bad891068a'),
  ('en.sahih', 99, 4, 6142, 'That Day, it will report its news', NULL, NULL, '0a6c393cc224e3ab1a8af15077753a850b1b24c454f5ab077f0cce0402e71c7a'),
  ('en.sahih', 99, 5, 6143, 'Because your Lord has commanded it.', NULL, NULL, '8553a766f07fe730910faf120a5faf26ad63d6dbac76848341a6cb7be9cb9dcd'),
  ('en.sahih', 99, 6, 6144, 'That Day, the people will depart separated [into categories] to be shown [the result of] their deeds.', NULL, NULL, 'e92ae7a4f0dc6ebc04424a0f102aae08bd5e7e25f86d96f9a5038b7619fbd5b6'),
  ('en.sahih', 99, 7, 6145, 'So whoever does an atom''s weight of good will see it,', NULL, NULL, '029c90deabf63388e3794e33db3ee0fa472fc73137865bad0aacaa788071e287'),
  ('en.sahih', 99, 8, 6146, 'And whoever does an atom''s weight of evil will see it.', NULL, NULL, '9bb0626d88733b68a6e8fe8da36071b7ac936e090320b30d9626b346cc6d9e17'),
  ('en.sahih', 100, 1, 6147, 'By the racers, panting,', NULL, NULL, '593bdcbd4543f4154787455dd056a27e20d91678c4d666999ca8edca510d1025'),
  ('en.sahih', 100, 2, 6148, 'And the producers of sparks [when] striking', NULL, NULL, '0d11eacce96a37e957cdbe64cd4e21bc5a5b61d2a6485b5667261190eeef9ccc'),
  ('en.sahih', 100, 3, 6149, 'And the chargers at dawn,', NULL, NULL, '8836dab699113b3589ac79c30bc8250dcb308111759be165a0f5cfb5157e0e97'),
  ('en.sahih', 100, 4, 6150, 'Stirring up thereby [clouds of] dust,', NULL, NULL, '43fcc9767732e27f257ff22144a9dcc411a50833123e44658f545d31aee04c95'),
  ('en.sahih', 100, 5, 6151, 'Arriving thereby in the center collectively,', NULL, NULL, '51d2ac9eca9abe5f158197aff625299e80a3c618e8b2bac17746a62a6050e513'),
  ('en.sahih', 100, 6, 6152, 'Indeed mankind, to his Lord, is ungrateful.', NULL, NULL, '175d936b1b62223efa4f86caf8eedf8d5e7164be9d5193779a8a3a7782d3dc6b'),
  ('en.sahih', 100, 7, 6153, 'And indeed, he is to that a witness.', NULL, NULL, 'cb9db8f1b1b896d932676aee14761740e93183ed1a2d98fb8ebccd1179082840'),
  ('en.sahih', 100, 8, 6154, 'And indeed he is, in love of wealth, intense.', NULL, NULL, '4bee3a50c417253f790202ac37a4f1b62341cbee67a40c7532b8c0578396852c'),
  ('en.sahih', 100, 9, 6155, 'But does he not know that when the contents of the graves are scattered', NULL, NULL, '4d6721c9437061006a5eb76e0994b908c08ffe0c841b6dd14af32841a2ae5920'),
  ('en.sahih', 100, 10, 6156, 'And that within the breasts is obtained,', NULL, NULL, '493630588c75adae176779e4f88d75477c42ae4688f4987310a0419aaa19776e'),
  ('en.sahih', 100, 11, 6157, 'Indeed, their Lord with them, that Day, is [fully] Acquainted.', NULL, NULL, 'feeb6736b59ab052e2b69825eccdbf31ac8fbafc0150f1eb0db74141e3c12781'),
  ('en.sahih', 101, 1, 6158, 'The Striking Calamity -', NULL, NULL, '87890d7defe5e1fa10968d05b3b6d8f3689ec449f6bfcf9462c545f5c50946d0'),
  ('en.sahih', 101, 2, 6159, 'What is the Striking Calamity?', NULL, NULL, '71c1385703f644db9d5207e8b2861ec452e2fba45004b4ce1d4d09ca2ea4b312'),
  ('en.sahih', 101, 3, 6160, 'And what can make you know what is the Striking Calamity?', NULL, NULL, '2dc82be3d8a164c87a28d8390d1b90eb956bdb07fadbaaa862bef34e7bb5a497'),
  ('en.sahih', 101, 4, 6161, 'It is the Day when people will be like moths, dispersed,', NULL, NULL, 'b6336a0ff800e0784aff16a32627f53595b6238cb0448a27b5a099be9ecd2b21'),
  ('en.sahih', 101, 5, 6162, 'And the mountains will be like wool, fluffed up.', NULL, NULL, '322eae85c8f86cdf64735b3a5b3678b3301a18e9bd557eaeb2b782782b306a4e'),
  ('en.sahih', 101, 6, 6163, 'Then as for one whose scales are heavy [with good deeds],', NULL, NULL, 'f1e2c5bdb4c4c7991744d0399f68287db7304984d54d3b0ea9629afea543debe'),
  ('en.sahih', 101, 7, 6164, 'He will be in a pleasant life.', NULL, NULL, 'aa82b13d80a05370d33f22b01d1bde4dacf50b3821438e7de530713c3591ea4d'),
  ('en.sahih', 101, 8, 6165, 'But as for one whose scales are light,', NULL, NULL, 'a5e5e3bccee729ccdfae93f04e3d9673f62ac73854a10ec2de44c81d1c2bd655'),
  ('en.sahih', 101, 9, 6166, 'His refuge will be an abyss.', NULL, NULL, '38c09719e34d2a2c3885f18b519ce91c7b602af2b17cd5a21c19006eea4a56af'),
  ('en.sahih', 101, 10, 6167, 'And what can make you know what that is?', NULL, NULL, '608ff4a601afe484ee9f343d7c4ebad10d8d104d927d010e59d9d31f3937db6f'),
  ('en.sahih', 101, 11, 6168, 'It is a Fire, intensely hot.', NULL, NULL, '4f7116d1c9e4a9cd70101cd068af77bf74edc6b4cffb3f03ef9a66b787309613'),
  ('en.sahih', 102, 1, 6169, 'Competition in [worldly] increase diverts you', NULL, NULL, 'af4bc2e082721326f934655c7fe47cc0403eb05fd148717e27c350f6c90aa463'),
  ('en.sahih', 102, 2, 6170, 'Until you visit the graveyards.', NULL, NULL, 'd0dd214ada0798bc5725e2aa14a50948be4f0d98e634cc816ee21275f502299c'),
  ('en.sahih', 102, 3, 6171, 'No! You are going to know.', NULL, NULL, '5494e01f9703e7666e6cfa006596d9eae7cef5b7b80f500423b057840c8c2026'),
  ('en.sahih', 102, 4, 6172, 'Then no! You are going to know.', NULL, NULL, 'efb8a63f1f27e00fa758e132141b246ba516652af71ef99e3538ae516a45748a'),
  ('en.sahih', 102, 5, 6173, 'No! If you only knew with knowledge of certainty...', NULL, NULL, '3e57bb0311ca42751289a6978c62d8d52e05fb325785513b188532d4f2186378'),
  ('en.sahih', 102, 6, 6174, 'You will surely see the Hellfire.', NULL, NULL, '805f7759ecb2c042ed88b46fee31bde9e031caf5daac4bd0df5a78581c99e6d1'),
  ('en.sahih', 102, 7, 6175, 'Then you will surely see it with the eye of certainty.', NULL, NULL, '6e982d5165c7845e7461026a30a54b04c17b5736e5eee2ea4912791a9ad6901f'),
  ('en.sahih', 102, 8, 6176, 'Then you will surely be asked that Day about pleasure.', NULL, NULL, '970cd411acd7eb4106cbc1f5075a071d05d463ee3556b75b271492a3ba0807f2'),
  ('en.sahih', 103, 1, 6177, 'By time,', NULL, NULL, '2bd7c0695e2d28d6e37541fbaf3fa797528e26a29b86f2c90f7f498cae13758a'),
  ('en.sahih', 103, 2, 6178, 'Indeed, mankind is in loss,', NULL, NULL, '2b25dbcd6b566ea6d81325746ff214dd9c57a64d14c84284532096dc36a1a37c'),
  ('en.sahih', 103, 3, 6179, 'Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.', NULL, NULL, '943654dbc533902dcc6b2cdd4db0757a69625e1e38896cdc033ffacbd47ceb26'),
  ('en.sahih', 104, 1, 6180, 'Woe to every scorner and mocker', NULL, NULL, 'da58ade97bb15fb9c72d003cb483b4c19d857004ab0019829b65094c31368aa2'),
  ('en.sahih', 104, 2, 6181, 'Who collects wealth and [continuously] counts it.', NULL, NULL, 'cf5f9a7674ecae8baec65b850abcdaa3156306736e1d78744f7a12a1a0ce1d21'),
  ('en.sahih', 104, 3, 6182, 'He thinks that his wealth will make him immortal.', NULL, NULL, 'f94f9088de57ec19a4d0c0b059df05e6ca51b766d13f265bf66def5ec3fbc4e4'),
  ('en.sahih', 104, 4, 6183, 'No! He will surely be thrown into the Crusher.', NULL, NULL, '75062722f7fa08054477c4a2b180119d9ab386c63c743c5f586c379f2c200280'),
  ('en.sahih', 104, 5, 6184, 'And what can make you know what is the Crusher?', NULL, NULL, 'a30c5bc43af2a327aeb8be464087145f8a9447baf4c3dd4c038649dc9ee6ccda'),
  ('en.sahih', 104, 6, 6185, 'It is the fire of Allah, [eternally] fueled,', NULL, NULL, '29034b22c6e535da8a0f2434e00df57d65c961634cc29663551d5971f87d2be4'),
  ('en.sahih', 104, 7, 6186, 'Which mounts directed at the hearts.', NULL, NULL, '0ad004e2495ce289aabffe3473fafb6367581bd456bcc74b9ceaa150b75def02'),
  ('en.sahih', 104, 8, 6187, 'Indeed, Hellfire will be closed down upon them', NULL, NULL, 'dac13baad6964abb2669e0bc05973a7ee19abacddb227ac1fb6318b7a6ec98c2'),
  ('en.sahih', 104, 9, 6188, 'In extended columns.', NULL, NULL, '00903af96d5c5167d56507bbc50c9484dfe995fbb948e041f076a69a57c2c19d'),
  ('en.sahih', 105, 1, 6189, 'Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?', NULL, NULL, '05f6a19cae4eb7251975627e77f537b2e36427c9f2b33feb612d78e190bcf100'),
  ('en.sahih', 105, 2, 6190, 'Did He not make their plan into misguidance?', NULL, NULL, '4a667d4fac3964451ebc0b0d1e31a23355d9fcded7a6840b8380b52a04ea9459'),
  ('en.sahih', 105, 3, 6191, 'And He sent against them birds in flocks,', NULL, NULL, 'a3095212d723debdbf915e84029eff33fd3e70823d7f10511070993fe701018e'),
  ('en.sahih', 105, 4, 6192, 'Striking them with stones of hard clay,', NULL, NULL, 'bbeac09fab81c2e67bfb0b783e61bd9a37dd9e0c8d24393a55df2fea2d125a0f'),
  ('en.sahih', 105, 5, 6193, 'And He made them like eaten straw.', NULL, NULL, 'a2af2134a6f36078c597f31d594e1c0c1defeca201dc882220a7d22b1a384357'),
  ('en.sahih', 106, 1, 6194, 'For the accustomed security of the Quraysh -', NULL, NULL, 'a1c64e07f2184348b928b711b703309fd1d25fd2700b58827383ac3599c82cfa'),
  ('en.sahih', 106, 2, 6195, 'Their accustomed security [in] the caravan of winter and summer -', NULL, NULL, '4c613300ecb1fecf5c29eb6a876fa2f975b81395518dc5049e83e950ffa152aa'),
  ('en.sahih', 106, 3, 6196, 'Let them worship the Lord of this House,', NULL, NULL, '83b5ee98b79b12568c09755d3d5c7f1457c535272b0802e56d44300511b31628'),
  ('en.sahih', 106, 4, 6197, 'Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.', NULL, NULL, 'e63d7d35c04e0bb5f2cebbd5dd263e1637c1229e3df5a5dee80c7e9678e30938'),
  ('en.sahih', 107, 1, 6198, 'Have you seen the one who denies the Recompense?', NULL, NULL, '721d500d5f89a4e2b9f99c6be01ba8b405735c0e48466ac116b636e3adcf2fb0'),
  ('en.sahih', 107, 2, 6199, 'For that is the one who drives away the orphan', NULL, NULL, '876fbba8787986fe53ce65b054a2be87ebc767225ed9be5298095c953d28656e'),
  ('en.sahih', 107, 3, 6200, 'And does not encourage the feeding of the poor.', NULL, NULL, 'c5db3681416c6869746eb9130169d4d43f3cfe6fb0f7c172fe050733f73697c7')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('en.sahih', 107, 4, 6201, 'So woe to those who pray', NULL, NULL, '7ab29313cff3ed36f906c08622f12d6dba80e7779925e6e2e3fdd8dfa055322a'),
  ('en.sahih', 107, 5, 6202, '[But] who are heedless of their prayer -', NULL, NULL, '4f3412c4724a184bda6d9964abc7fbbdd616d88a6e1bbbe380a4605bceff223e'),
  ('en.sahih', 107, 6, 6203, 'Those who make show [of their deeds]', NULL, NULL, '52519af41f640ca12c2c2a60e6c27aa063b061598b4d2ecfb8a3b6267c00762c'),
  ('en.sahih', 107, 7, 6204, 'And withhold [simple] assistance.', NULL, NULL, '9d77f3dde74d327d1d8fd487e181c7be794b08d9e6e3709cc1c02c5c900a489a'),
  ('en.sahih', 108, 1, 6205, 'Indeed, We have granted you, [O Muhammad], al-Kawthar.', NULL, NULL, '07e19129c33255b992ad420da291c741d01e54d927fe0aa7c66d4917d330bb28'),
  ('en.sahih', 108, 2, 6206, 'So pray to your Lord and sacrifice [to Him alone].', NULL, NULL, 'd68efca7a90ae998f08a988efc27741000479deb8b1a2ec1f878be35ba487420'),
  ('en.sahih', 108, 3, 6207, 'Indeed, your enemy is the one cut off.', NULL, NULL, '634a2c7194882729e2a65583b313348c5ab5aeb66ee9efd361059ea825cf6481'),
  ('en.sahih', 109, 1, 6208, 'Say, "O disbelievers,', NULL, NULL, 'a3f5c364f961cd8dba8675eef4e69fc4212b49f4569c97d134c6bb1b2bb79e9f'),
  ('en.sahih', 109, 2, 6209, 'I do not worship what you worship.', NULL, NULL, '15a2665c2d4c1b4b48f7b983900274576e4cc2f4cec96068b00d3e4791be7255'),
  ('en.sahih', 109, 3, 6210, 'Nor are you worshippers of what I worship.', NULL, NULL, '5abde83f2d2cfbe6473300db181bc740f5cca4431db37554c5981deb6a73f070'),
  ('en.sahih', 109, 4, 6211, 'Nor will I be a worshipper of what you worship.', NULL, NULL, 'f62717c09f8c02f64c357123ddce406cb827076953d65fa21fe50c6abfce0423'),
  ('en.sahih', 109, 5, 6212, 'Nor will you be worshippers of what I worship.', NULL, NULL, '4710972a700c985cd5d3785ae2ce566329c59c80475824f135438d79691a6957'),
  ('en.sahih', 109, 6, 6213, 'For you is your religion, and for me is my religion."', NULL, NULL, '3f84a6832d6f8b85d8c761bdf1b203a08ab1bf11fd58608f992c8eeb5ffa1875'),
  ('en.sahih', 110, 1, 6214, 'When the victory of Allah has come and the conquest,', NULL, NULL, 'e631545830595310e3e7228c623ac096fc713b6ca83828d17f2d8c6d5039a30f'),
  ('en.sahih', 110, 2, 6215, 'And you see the people entering into the religion of Allah in multitudes,', NULL, NULL, '685cae3fab8fdca4c1255b7d4ef8334e6648532526c23491ee8eb99af332f4a7'),
  ('en.sahih', 110, 3, 6216, 'Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.', NULL, NULL, 'e95cd59b7f946c390b901778596c96b73d117c5859ad3d17a9292a61bfc2a60a'),
  ('en.sahih', 111, 1, 6217, 'May the hands of Abu Lahab be ruined, and ruined is he.', NULL, NULL, 'd835f1cb8acb298ff75d4e88a3c135163e4772a2ec0de9e24fdb0746b063d762'),
  ('en.sahih', 111, 2, 6218, 'His wealth will not avail him or that which he gained.', NULL, NULL, '2dd525f7dbafb833248034efe7294aa29eab5c018f025765ee725c9f9c1fa3fd'),
  ('en.sahih', 111, 3, 6219, 'He will [enter to] burn in a Fire of [blazing] flame', NULL, NULL, '0fe40905440022d9092f3731f33e7ddba4669df8c3f84385b89fb07dfb7fe219'),
  ('en.sahih', 111, 4, 6220, 'And his wife [as well] - the carrier of firewood.', NULL, NULL, '827ca89eb78dd3bf4a5a20c369dc5efe8d74bb518df40d880f15b2dc5729bbd8'),
  ('en.sahih', 111, 5, 6221, 'Around her neck is a rope of [twisted] fiber.', NULL, NULL, '39e32933049c6d8f2a5f77505dbd10eae3b98d4b511421fcab42bcf7d67b2d8e'),
  ('en.sahih', 112, 1, 6222, 'Say, "He is Allah, [who is] One,', NULL, NULL, '73f74e4ec4403becdf66f4afb25937d00ba40f07d4473585dcc95a73152e61cc'),
  ('en.sahih', 112, 2, 6223, 'Allah, the Eternal Refuge.', NULL, NULL, '811f03aa2a2eb31022149bba68a2a5fa02d89af2c932f8f0e016d222b21e38b3'),
  ('en.sahih', 112, 3, 6224, 'He neither begets nor is born,', NULL, NULL, '352fe010431349927c9bac8f3e5adbcea094bda23d42a308355efb685e5b3201'),
  ('en.sahih', 112, 4, 6225, 'Nor is there to Him any equivalent."', NULL, NULL, 'af9131f6c33d4c25564d471f5785b8bd091c58e9b98842fb2519c845fab305f2'),
  ('en.sahih', 113, 1, 6226, 'Say, "I seek refuge in the Lord of daybreak', NULL, NULL, '9dbd03c502f1b56f77088e708e4d267b258e7d43eb7fb34072d437c366507496'),
  ('en.sahih', 113, 2, 6227, 'From the evil of that which He created', NULL, NULL, '5c1a38a8631bbec447a5d8368c444ce94c5e642d304fbe402c5b8b1e2219c226'),
  ('en.sahih', 113, 3, 6228, 'And from the evil of darkness when it settles', NULL, NULL, '2aa198c76be21de843be7d03fd3376bc7367e7a96b1d5be162898339511f8a26'),
  ('en.sahih', 113, 4, 6229, 'And from the evil of the blowers in knots', NULL, NULL, '3a4c2f87014b8dc794a9ce4a97ff4ea626b08e5e19a334e5135630313ddb7e7d'),
  ('en.sahih', 113, 5, 6230, 'And from the evil of an envier when he envies."', NULL, NULL, '75daffefa15081bf6474d104b93cf52278c9e1a1aa806fed05c31a0fb0c504a5'),
  ('en.sahih', 114, 1, 6231, 'Say, "I seek refuge in the Lord of mankind,', NULL, NULL, 'a0ebd229366dd39478a391af3f359f08b6f7827e29aed4511d42f81bcacb9a56'),
  ('en.sahih', 114, 2, 6232, 'The Sovereign of mankind.', NULL, NULL, 'd21fdbfa3c20854bb8322cba4f467bf0fa9ed7c35cc9e0697673bee24e1b4e8e'),
  ('en.sahih', 114, 3, 6233, 'The God of mankind,', NULL, NULL, '8d097ea78227170ab271610c649aeb4f5f814c2cf23e6efdfdada371113ad126'),
  ('en.sahih', 114, 4, 6234, 'From the evil of the retreating whisperer -', NULL, NULL, 'd05636f4e9240d00fc19b92704df1c33602dfb2fe6f67b629bf52dcd2a259385'),
  ('en.sahih', 114, 5, 6235, 'Who whispers [evil] into the breasts of mankind -', NULL, NULL, '401c1531433eaf50574acd573bc182c0f812a5bc74d7a7df204428f92f640d47'),
  ('en.sahih', 114, 6, 6236, 'From among the jinn and mankind."', NULL, NULL, '703f1e4350679f2caf3c8aa5155f3ddf36ff2f293f1577532564a8ab1fb52340')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

-- Ingesting Edition: ur.jalandhry (مولانا فتح محمد جالندھری (اردو ترجمہ)) - 6236 Ayahs
INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 1, 1, 1, 'شروع الله کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے', NULL, NULL, '4f5193dc7195750eae70cf1aa3601697b1e1506f11aa9339b1d7236fe376b9d9'),
  ('ur.jalandhry', 1, 2, 2, 'سب طرح کی تعریف خدا ہی کو (سزاوار) ہے جو تمام مخلوقات کا پروردگار ہے', NULL, NULL, '4a755a03b4e50a480f4752b6459cb729fb98fd8914fa5458d85cff818d3a92f7'),
  ('ur.jalandhry', 1, 3, 3, 'بڑا مہربان نہایت رحم والا', NULL, NULL, '2686f11f3e2e86196df1adede0494d1a58c79addc9f2afe77cedba89754b08c9'),
  ('ur.jalandhry', 1, 4, 4, 'انصاف کے دن کا حاکم', NULL, NULL, '3da646911ea55451f0796d8cb241558e7f54bf3056c6d70b79aad99784c3a952'),
  ('ur.jalandhry', 1, 5, 5, '(اے پروردگار) ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں', NULL, NULL, 'ab660549bf333b90c096fdb56da71915967e3ab7f7d9acd6d3469500e4e52c3e'),
  ('ur.jalandhry', 1, 6, 6, 'ہم کو سیدھے رستے چلا', NULL, NULL, 'c6852c9eabe4efd4373a81bb933ccda524a1f675b120310817983d5169472664'),
  ('ur.jalandhry', 1, 7, 7, 'ان لوگوں کے رستے جن پر تو اپنا فضل وکرم کرتا رہا نہ ان کے جن پر غصے ہوتا رہا اور نہ گمراہوں کے', NULL, NULL, 'd543bb44dadb6a6269ae94ad04223bda892f591b26a0b2d2caf835cf6a597353'),
  ('ur.jalandhry', 2, 1, 8, 'الم', NULL, NULL, '58bc1e3007bc0ed70b737b562ad04a88867c38e78e58e2f15c3f43c9be783acb'),
  ('ur.jalandhry', 2, 2, 9, 'یہ کتاب (قرآن مجید) اس میں کچھ شک نہیں (کہ کلامِ خدا ہے۔ خدا سے) ڈرنے والوں کی رہنما ہے', NULL, NULL, '94e6c4a599040965b09e373cef4c53db9cb28e7cf9e21978ec161bc30d55e237'),
  ('ur.jalandhry', 2, 3, 10, 'جو غیب پر ایمان لاتے اور آداب کے ساتھ نماز پڑھتے اور جو کچھ ہم نے ان کو عطا فرمایا ہے اس میں سے خرچ کرتے ہیں', NULL, NULL, 'dc65d6220bef057041dc8292a800caca04a9dc0f45b3b7a74fb36eb17a381ddb'),
  ('ur.jalandhry', 2, 4, 11, 'اور جو کتاب (اے محمدﷺ) تم پر نازل ہوئی اور جو کتابیں تم سے پہلے (پیغمبروں پر) نازل ہوئیں سب پر ایمان لاتے اور آخرت کا یقین رکھتے ہیں', NULL, NULL, '612812fbb64eee2d447fea0494b92fff11ae61a647a7dea2900a6d510bba61a0'),
  ('ur.jalandhry', 2, 5, 12, 'یہی لوگ اپنے پروردگار (کی طرف) سے ہدایت پر ہیں اور یہی نجات پانے والے ہیں', NULL, NULL, '28294f6e60c39c295771d13b2d4c0a08a7b424837339467ccdcdcbfb563998fb'),
  ('ur.jalandhry', 2, 6, 13, 'جو لوگ کافر ہیں انہیں تم نصیحت کرو یا نہ کرو ان کے لیے برابر ہے۔ وہ ایمان نہیں لانے کے', NULL, NULL, '7f44f74db33ddbb52de7a4148c8aaf6f0712b08545f64835dd4b2bbe599cd0b4'),
  ('ur.jalandhry', 2, 7, 14, 'خدا نے ان کے دلوں اور کانوں پر مہر لگا رکھی ہے اور ان کی آنکھوں پر پردہ (پڑا ہوا) ہے اور ان کے لیے بڑا عذاب (تیار) ہے', NULL, NULL, '3dd1879238bbdca95370ae0167512960bc6c67b8e4aa88c62067a3055e735bd7'),
  ('ur.jalandhry', 2, 8, 15, 'اور بعض لوگ ایسے ہیں جو کہتے ہیں کہ ہم خدا پر اور روزِ آخرت پر ایمان رکھتے ہیں حالانکہ وہ ایمان نہیں رکھتے', NULL, NULL, 'bbaf7e2c1252a61c4eca40513df1cff133a80dbf05ea941ab3ebe281137deced'),
  ('ur.jalandhry', 2, 9, 16, 'یہ (اپنے پندار میں) خدا کو اور مومنوں کو چکما دیتے ہیں مگر (حقیقت میں) اپنے سوا کسی کو چکما نہیں دیتے اور اس سے بے خبر ہیں', NULL, NULL, '6deb98b16137ed4a92fb69b8124158624a52ed3658016e10cf9e0b6daa1721a8'),
  ('ur.jalandhry', 2, 10, 17, 'ان کے دلوں میں (کفر کا) مرض تھا۔ خدا نے ان کا مرض اور زیادہ کر دیا اور ان کے جھوٹ بولنے کے سبب ان کو دکھ دینے والا عذاب ہوگا', NULL, NULL, '6bae0e8b43f106b920e053932f7308f2c44178b9473e4128e48c22610f0355da'),
  ('ur.jalandhry', 2, 11, 18, 'اور جب ان سے کہا جاتا ہے کہ زمین میں فساد نہ ڈالو تو کہتے ہیں، ہم تو اصلاح کرنے والے ہیں', NULL, NULL, '58a25c8c30dc2d276d37cc44798894940055ce0791416a7a175b1b2fb4d6edf8'),
  ('ur.jalandhry', 2, 12, 19, 'دیکھو یہ بلاشبہ مفسد ہیں، لیکن خبر نہیں رکھتے', NULL, NULL, '94e3b57dd7336c26f6a3affdca5330f8a31a49460878e4821617a3fb1df50efe'),
  ('ur.jalandhry', 2, 13, 20, 'اور جب ان سے کہا جاتا ہے کہ جس طرح اور لوگ ایمان لے آئے، تم بھی ایمان لے آؤ تو کہتے ہیں، بھلا جس طرح بےوقوف ایمان لے آئے ہیں اسی طرح ہم بھی ایمان لے آئیں؟ سن لو کہ یہی بےوقوف ہیں لیکن نہیں جانتے', NULL, NULL, 'd7db6ce2016519e68d3e368bf0c7d6c4cfba6da51986bc07a8546ff923320e41'),
  ('ur.jalandhry', 2, 14, 21, 'اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے ہیں، اور جب اپنے شیطانوں میں جاتے ہیں تو (ان سے) کہتے ہیں کہ ہم تمھارے ساتھ ہیں اور (پیروانِ محمدﷺ سے) تو ہم ہنسی کیا کرتے ہیں', NULL, NULL, '23ae1e3ed7c614cfe55559922c235e53a5daa48db599416b512a658000e08618'),
  ('ur.jalandhry', 2, 15, 22, 'ان (منافقوں) سے خدا ہنسی کرتا ہے اور انہیں مہلت دیئے جاتا ہے کہ شرارت وسرکشی میں پڑے بہک رہے ہیں', NULL, NULL, 'bfb8bc7fe828e194c9eb06304b6662d07a6e9571e3be65ec9ff7ea17d9501259'),
  ('ur.jalandhry', 2, 16, 23, 'یہ وہ لوگ ہیں جنہوں نے ہدایت چھوڑ کر گمراہی خریدی، تو نہ تو ان کی تجارت ہی نے کچھ نفع دیا اور نہ وہ ہدایت یاب ہی ہوئے', NULL, NULL, '29f63144ec372c863bceea9429e75e0d35a3023f39a47f61f5479415e026c23b'),
  ('ur.jalandhry', 2, 17, 24, 'ان کی مثال اس شخص کی سی ہے کہ جس نے (شبِ تاریک میں) آگ جلائی۔ جب آگ نے اس کے اردگرد کی چیزیں روشن کیں تو خدا نے ان کی روشنی زائل کر دی اور ان کو اندھیروں میں چھوڑ دیا کہ کچھ نہیں دیکھتے', NULL, NULL, '89ae8ee2ba568f51a633fc89dcc19c5cee93348a324d797f43e803f3e4d9ee36'),
  ('ur.jalandhry', 2, 18, 25, '(یہ) بہرے ہیں، گونگے ہیں، اندھے ہیں کہ (کسی طرح سیدھے رستے کی طرف) لوٹ ہی نہیں سکتے', NULL, NULL, 'a4c80a599dbb6703c44af4af734ce79b839b85e8fdb29ecbd7b6f4c00b9d2cf7'),
  ('ur.jalandhry', 2, 19, 26, 'یا ان کی مثال مینہ کی سی ہے کہ آسمان سے (برس رہا ہو اور) اس میں اندھیرے پر اندھیرا (چھا رہا) ہو اور (بادل) گرج (رہا) ہو اور بجلی (کوند رہی) ہو تو یہ کڑک سے (ڈر کر) موت کے خوف سے کانوں میں انگلیاں دے لیں اور الله کافروں کو (ہر طرف سے) گھیرے ہوئے ہے', NULL, NULL, '392e0fef94c7beef72a094590aa45656faafc595d93f7d2b40482241f63c6bbd'),
  ('ur.jalandhry', 2, 20, 27, 'قریب ہے کہ بجلی (کی چمک) ان کی آنکھوں (کی بصارت) کو اچک لے جائے۔ جب بجلی (چمکتی اور) ان پر روشنی ڈالی ہے تو اس میں چل پڑتے ہیں اور جب اندھیرا ہو جاتا ہے تو کھڑے کے کھڑے رہ جاتے ہیں اور اگر الله چاہتا تو ان کے کانوں (کی شنوائی) اور آنکھوں (کی بینائی دونوں) کو زائل کر دیتا ہے۔ بے شک الله ہر چیز پر قادر ہے', NULL, NULL, 'f0605173493d5097cf40911f2339036966a7071e5ded551fee02a1da00985a8a'),
  ('ur.jalandhry', 2, 21, 28, 'لوگو! اپنے پروردگار کی عبات کرو جس نے تم کو اور تم سے پہلے لوگوں کو پیدا کیا تاکہ تم (اس کے عذاب سے) بچو', NULL, NULL, '2118a12cb6fdc9e0f763e2e73daa8c282b2664d14f4cdbfc480b2cee44ef51ea'),
  ('ur.jalandhry', 2, 22, 29, 'جس نے تمھارے لیے زمین کو بچھونا اور آسمان کو چھت بنایا اور آسمان سے مینہ برسا کر تمہارے کھانے کے لیے انواع و اقسام کے میوے پیدا کئے۔ پس کسی کو خدا کا ہمسر نہ بناؤ۔ اور تم جانتے تو ہو', NULL, NULL, '6be5d55b3951188a00958cebddbfcf5c1d098463a7da639150c8b8fa471127b1'),
  ('ur.jalandhry', 2, 23, 30, 'اور اگر تم کو اس (کتاب) میں، جو ہم نے اپنے بندے (محمدﷺ عربی) پر نازل فرمائی ہے کچھ شک ہو تو اسی طرح کی ایک سورت تم بھی بنا لاؤ اور خدا کے سوا جو تمہارے مددگار ہوں ان کو بھی بلالو اگر تم سچے ہو', NULL, NULL, '9dbb4de317555177c9440a795ba75c5897f39dd616dbfda52356babe7ae44c14'),
  ('ur.jalandhry', 2, 24, 31, 'لیکن اگر (ایسا) نہ کر سکو اور ہرگز نہیں کر سکو گے تو اس آگ سے ڈرو جس کا ایندھن آدمی اور پتھر ہوں گے (اور جو) کافروں کے لیے تیار کی گئی ہے', NULL, NULL, '36ce70dd2cad0317073ac472f726b258ea4b1fde932262cc78042f49ceec43dc'),
  ('ur.jalandhry', 2, 25, 32, 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے، ان کو خوشخبری سنا دو کہ ان کے لیے (نعمت کے) باغ ہیں، جن کے نیچے نہریں بہہ رہی ہیں۔ جب انہیں ان میں سے کسی قسم کا میوہ کھانے کو دیا جائے گا تو کہیں گے، یہ تو وہی ہے جو ہم کو پہلے دیا گیا تھا۔ اور ان کو ایک دوسرے کے ہم شکل میوے دیئے جائیں گے اور وہاں ان کے لیے پاک بیویاں ہوں گی اور وہ بہشتوں میں ہمیشہ رہیں گے', NULL, NULL, '892b509d5d8cf6a25b8fb1d1274bbfa99a89ada58a76819ff5c347f8fbd20dc5'),
  ('ur.jalandhry', 2, 26, 33, 'الله اس بات سے عار نہیں کرتا کہ مچھر یا اس سے بڑھ کر کسی چیز (مثلاً مکھی مکڑی وغیرہ) کی مثال بیان فرمائے۔ جو مومن ہیں، وہ یقین کرتے ہیں وہ ان کے پروردگار کی طرف سے سچ ہے اور جو کافر ہیں وہ کہتے ہیں کہ اس مثال سے خدا کی مراد ہی کیا ہے۔ اس سے (خدا) بہتوں کو گمراہ کرتا ہے اور بہتوں کو ہدایت بخشتا ہے اور گمراہ بھی کرتا تو نافرمانوں ہی کو', NULL, NULL, '27dbbd72f7d5f2b176cd1a3260c48b8bbbb9cc3c50e91a95f67fe9a662be0a03'),
  ('ur.jalandhry', 2, 27, 34, 'جو خدا کے اقرار کو مضبوط کرنے کے بعد توڑ دیتے ہیں اور جس چیز (یعنی رشتہٴ قرابت) کے جوڑے رکھنے کا الله نے حکم دیا ہے اس کو قطع کئے ڈالتے ہیں اور زمین میں خرابی کرتے ہیں یہی لوگ نقصان اٹھانے والے ہیں', NULL, NULL, '198f5917a90cb06836e262511b88bcbf88aa75d0b881db402c7c04ce93e74fd3'),
  ('ur.jalandhry', 2, 28, 35, '(کافرو!) تم خدا سے کیوں کر منکر ہو سکتے ہو جس حال میں کہ تم بےجان تھے تو اس نے تم کو جان بخشی پھر وہی تم کو مارتا ہے پھر وہی تم کو زندہ کرے گا پھر تم اسی کی طرف لوٹ کر جاؤ گے', NULL, NULL, '18e1953c9470366ca4484a48be3e2f558e4e55b9dce6409c6019cd063601d8c7'),
  ('ur.jalandhry', 2, 29, 36, 'وہی تو ہے جس نے سب چیزیں جو زمین میں ہیں تمہارے لیے پیدا کیں پھر آسمان کی طرف متوجہ ہوا تو ان کو ٹھیک سات آسمان بنا دیا اور وہ ہر چیز سے خبردار ہے', NULL, NULL, '07e6aebc059f9bcd0d8711e60a9dab0bfeebd895a6f88548b95c9095e0e92378'),
  ('ur.jalandhry', 2, 30, 37, 'اور (وہ وقت یاد کرنے کے قابل ہے) جب تمہارے پروردگار نے فرشتوں سے فرمایا کہ میں زمین میں (اپنا) نائب بنانے والا ہوں۔ انہوں نے کہا۔ کیا تُو اس میں ایسے شخص کو نائب بنانا چاہتا ہے جو خرابیاں کرے اور کشت وخون کرتا پھرے اور ہم تیری تعریف کے ساتھ تسبیح وتقدیس کرتے رہتے ہیں۔ (خدا نے) فرمایا میں وہ باتیں جانتا ہوں جو تم نہیں جانتے', NULL, NULL, '372a5c411bdd1992d8404f4a8fefcca2f15e72c0b7e3a666fd672f45789fd4cf'),
  ('ur.jalandhry', 2, 31, 38, 'اور اس نے آدم کو سب (چیزوں کے) نام سکھائے پھر ان کو فرشتوں کے سامنے کیا اور فرمایا کہ اگر تم سچے ہو تو مجھے ان کے نام بتاؤ', NULL, NULL, '0f65c81f97e9a3d9c6e3f2ec73d3d217f01d42a92559cdee08fdc8a01fdce375'),
  ('ur.jalandhry', 2, 32, 39, 'انہوں نے کہا، تو پاک ہے۔ جتنا علم تو نے ہمیں بخشا ہے، اس کے سوا ہمیں کچھ معلوم نہیں۔ بے شک تو دانا (اور) حکمت والا ہے', NULL, NULL, '2db2d2e79c2e4c17519d327d677455804205831b2780774474e55d9a99c6e230'),
  ('ur.jalandhry', 2, 33, 40, '(تب) خدا نے (آدم کو) حکم دیا کہ آدم! تم ان کو ان (چیزوں) کے نام بتاؤ۔ جب انہوں نے ان کو ان کے نام بتائے تو (فرشتوں سے) فرمایا کیوں میں نے تم سے نہیں کہا تھا کہ میں آسمانوں اور زمین کی (سب) پوشیدہ باتیں جاتنا ہوں اور جو تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو (سب) مجھ کو معلوم ہے', NULL, NULL, '06e6365b2b7bb82fbf10990f3e81936ae9750a12087c201fb8db9192a12def43'),
  ('ur.jalandhry', 2, 34, 41, 'اور جب ہم نے فرشتوں کو حکم دیا کہ آدم کے آگے سجدہ کرو تو وہ سجدے میں گر پڑے مگر شیطان نے انکار کیا اور غرور میں آکر کافر بن گیا', NULL, NULL, '63f80106923a7fec38d5190f4d7f5b0d5bba93844b7a77df78aa16738997182e'),
  ('ur.jalandhry', 2, 35, 42, 'اور ہم نے کہا کہ اے آدم تم اور تمہاری بیوی بہشت میں رہو اور جہاں سے چاہو بے روک ٹوک کھاؤ (پیو) لیکن اس درخت کے پاس نہ جانا نہیں تو ظالموں میں (داخل) ہو جاؤ گے', NULL, NULL, '49d751edc34dce875c2a3efb5e73297cf3c9e9e0ef0ed3646d6c619ca3c984ff'),
  ('ur.jalandhry', 2, 36, 43, 'پھر شیطان نے دونوں کو وہاں سے پھسلا دیا اور جس (عیش ونشاط) میں تھے، اس سے ان کو نکلوا دیا۔ تب ہم نے حکم دیا کہ (بہشت بریں سے) چلے جاؤ۔ تم ایک دوسرے کے دشمن ہو، اور تمہارے لیے زمین میں ایک وقت تک ٹھکانا اور معاش (مقرر کر دیا گیا) ہے', NULL, NULL, '8a48ef30bd8db2647ad55887671e19f5a44bfb975718b0c808ff02f28054fb0c'),
  ('ur.jalandhry', 2, 37, 44, 'پھر آدم نے اپنے پروردگار سے کچھ کلمات سیکھے (اور معافی مانگی) تو اس نے ان کا قصور معاف کر دیا بے شک وہ معاف کرنے والا (اور) صاحبِ رحم ہے', NULL, NULL, 'f4cbb491ce3aeca3bf5c37c5fb465b5fb8bcd06f917d8833ab073443cc9e9fd2'),
  ('ur.jalandhry', 2, 38, 45, 'ہم نے فرمایا کہ تم سب یہاں سے اتر جاؤ جب تمہارے پاس میری طرف سے ہدایت پہنچے تو (اس کی پیروی کرنا کہ) جنہوں نے میری ہدایت کی پیروی کی ان کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے', NULL, NULL, 'c2ac048288bde9d6a4804ebcc5bcaa68ee2048b1b5cb0f549327226c8a85bbc3'),
  ('ur.jalandhry', 2, 39, 46, 'اور جنہوں نے (اس کو) قبول نہ کیا اور ہماری آیتوں کو جھٹلایا، وہ دوزخ میں جانے والے ہیں (اور) وہ ہمیشہ اس میں رہیں گے', NULL, NULL, '7a394b82f0657d35c33865c262f488db635d590aa4bebd5de43062512b2f94de'),
  ('ur.jalandhry', 2, 40, 47, 'اے یعقوب کی اولاد! میرے وہ احسان یاد کرو جو میں نے تم پر کئے تھے اور اس اقرار کو پورا کرو جو تم نے مجھ سے کیا تھا۔ میں اس اقرار کو پورا کروں گا جو میں نے تم سے کیا تھا اور مجھی سے ڈرتے رہو', NULL, NULL, '3d315e5b2fc4b06de015ce8050b20d8b8641823f21dc73f897dab4a58c407b76'),
  ('ur.jalandhry', 2, 41, 48, 'اور جو کتاب میں نے (اپنے رسول محمدﷺ پر) نازل کی ہے جو تمہاری کتاب تورات کو سچا کہتی ہے، اس پر ایمان لاؤ اور اس سے منکرِ اول نہ بنو، اور میری آیتوں میں (تحریف کر کے) ان کے بدلے تھوڑی سی قیمت (یعنی دنیاوی منعفت) نہ حاصل کرو، اور مجھی سے خوف رکھو', NULL, NULL, 'ecc0f4bc33350255538ec5da7e08799d873ebb315488b5a8a87de3c6304236fb'),
  ('ur.jalandhry', 2, 42, 49, 'اور حق کو باطل کے ساتھ نہ ملاؤ، اور سچی بات کو جان بوجھ کر نہ چھپاؤ', NULL, NULL, '3030009e4b9ba0208a1c759917d9b57893bf3f78088d981fbf6fd234c03fcffd'),
  ('ur.jalandhry', 2, 43, 50, 'اور نماز پڑھا کرو اور زکوٰة دیا کرو اور (خدا کے آگے) جھکنے والوں کے ساتھ جھکا کرو', NULL, NULL, '63687b9da75c8f1b6b53cb3c15aad919711cbda8260cf4db3d5c4288343d1e04'),
  ('ur.jalandhry', 2, 44, 51, '(یہ) کیا (عقل کی بات ہے کہ) تم لوگوں کو نیکی کرنے کو کہتے ہو اور اپنے تئیں فراموش کئے دیتے ہو، حالانکہ تم کتاب (خدا) بھی پڑھتے ہو۔ کیا تم سمجھتے نہیں؟', NULL, NULL, 'ae660e5c6e84abcbacac79cfe3f50ba4a6c11e1400ccace2d2119c493d89e5a4'),
  ('ur.jalandhry', 2, 45, 52, 'اور (رنج وتکلیف میں) صبر اور نماز سے مدد لیا کرو اور بے شک نماز گراں ہے، مگر ان لوگوں پر (گراں نہیں) جو عجز کرنے والے ہیں', NULL, NULL, '263c04239e96075b4467fd351a2e0f7600e83510fcbc11259acdbf7c39f8d03d'),
  ('ur.jalandhry', 2, 46, 53, 'اور جو یقین کئے ہوئے ہیں کہ وہ اپنے پروردگار سے ملنے والے ہیں اور اس کی طرف لوٹ کر جانے والے ہیں', NULL, NULL, '37d3143d9d36129a2b02413096cf999d8cb5db3e9ff5f80d3207899d5a9ba8f7'),
  ('ur.jalandhry', 2, 47, 54, 'اے یعقوب کی اولاد! میرے وہ احسان یاد کرو، جو میں نے تم پر کئے تھے اور یہ کہ میں نے تم کو جہان کے لوگوں پر فضیلت بخشی تھی', NULL, NULL, '536a2c85cee2164de5d28b77bc150ba28cc724474a5592b4a3c09d694ddc1704'),
  ('ur.jalandhry', 2, 48, 55, 'اور اس دن سے ڈرو جب کوئی کسی کے کچھ کام نہ آئے اور نہ کسی کی سفارش منظور کی جائے اور نہ کسی سے کسی طرح کا بدلہ قبول کیا جائے اور نہ لوگ (کسی اور طرح) مدد حاصل کر سکیں', NULL, NULL, '31ecb2fb64abe1abec7a63c0417c57fe6f7eeb10b05b6e26972a4746e0e887c0'),
  ('ur.jalandhry', 2, 49, 56, 'اور (ہمارے ان احسانات کو یاد کرو) جب ہم نے تم کو قومِ فرعون سے نجات بخشی وہ (لوگ) تم کو بڑا دکھ دیتے تھے تمہارے بیٹوں کو تو قتل کر ڈالتے تھے اور بیٹیوں کو زندہ رہنے دیتے تھے اور اس میں تمہارے پروردگار کی طرف سے بڑی (سخت) آزمائش تھی', NULL, NULL, 'a05b5bc773e4acc35cae8ae7eb3372d69fca7acfef099d81c47c065b6aa158a0'),
  ('ur.jalandhry', 2, 50, 57, 'اور جب ہم نے تمہارے لیے دریا کو پھاڑ دیا تم کو نجات دی اور فرعون کی قوم کو غرق کر دیا اور تم دیکھ ہی تو رہے تھے', NULL, NULL, 'd9ebfec2c89b8998b9867c68f2f1c591c0ed4ce7349d26078293281e17509139'),
  ('ur.jalandhry', 2, 51, 58, 'اور جب ہم نے موسیٰ سے چالیس رات کا وعدہ کیا تو تم نے ان کے پیچھے بچھڑے کو (معبود) مقرر کر لیا اور تم ظلم کر رہے تھے', NULL, NULL, '1780308f70137472805647985f0e3ae394d01589bf33617b0a998704474a740b'),
  ('ur.jalandhry', 2, 52, 59, 'پھر اس کے بعد ہم نے تم کو معاف کر دیا، تاکہ تم شکر کرو', NULL, NULL, '3b4cb77697d4aaee4094bfc6dfe0e89c233da0c28a940f5305fe42065997deba'),
  ('ur.jalandhry', 2, 53, 60, 'اور جب ہم نے موسیٰ کو کتاب اور معجزے عنایت کئے، تاکہ تم ہدایت حاصل کرو', NULL, NULL, 'ecc39c9dcc540b4d0145a6c83a40b3848de0486218483fa3abb15d4df6740b28'),
  ('ur.jalandhry', 2, 54, 61, 'اور جب موسیٰ نے اپنی قوم کے لوگوں سے کہا کہ بھائیو، تم نے بچھڑے کو (معبود) ٹھہرانے میں (بڑا) ظلم کیا ہے، تو اپنے پیدا کرنے والے کے آگے توبہ کرو اور اپنے تئیں ہلاک کر ڈالو۔ تمہارے خالق کے نزدیک تمہارے حق میں یہی بہتر ہے۔ پھر اس نے تمہارا قصور معاف کر دیا۔ وہ بے شک معاف کرنے والا (اور) صاحبِ رحم ہے', NULL, NULL, '31679bc1c48dea6481cea8627a12e3d7c43cbfd711102ce99bdfd19505ef077d'),
  ('ur.jalandhry', 2, 55, 62, 'اور جب تم نے (موسیٰ) سے کہا کہ موسیٰ، جب تک ہم خدا کو سامنے نہ دیکھ لیں گے، تم پر ایمان نہیں لائیں گے، تو تم کو بجلی نے آ گھیرا اور تم دیکھ رہے تھے', NULL, NULL, 'd425d85e7525a8e9f5d90285f58da55478004a3dc1647b7633585d736daf302f'),
  ('ur.jalandhry', 2, 56, 63, 'پھر موت آ جانے کے بعد ہم نے تم کو ازسرِ نو زندہ کر دیا، تاکہ احسان مانو', NULL, NULL, 'ac78d642206a8a575eab80fbe5c8d65cd4900c3dc566db9b1a84b97c0ddfcdde'),
  ('ur.jalandhry', 2, 57, 64, 'اور بادل کا تم پر سایہ کئے رکھا اور (تمہارے لیے) من و سلویٰ اتارتے رہے کہ جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائی ہیں، ان کو کھاؤ (پیو) مگر تمہارے بزرگوں نے ان نعمتوں کی کچھ قدر نہ جانی (اور) وہ ہمارا کچھ نہیں بگاڑتے تھے بلکہ اپنا ہی نقصان کرتے تھے', NULL, NULL, '2daa76f405fb2c1e01fb90d00453a9dc26822c6ed825263f5b80ba435141bf04'),
  ('ur.jalandhry', 2, 58, 65, 'اور جب ہم نے (ان سے) کہا کہ اس گاؤں میں داخل ہو جاؤ اور اس میں جہاں سے چاہو، خوب کھاؤ (پیو) اور (دیکھنا) دروازے میں داخل ہونا تو سجدہ کرنا اور حطة کہنا، ہم تمہارے گناہ معاف کر دیں گے اور نیکی کرنے والوں کو اور زیادہ دیں گے', NULL, NULL, 'ded5e9ed92f2c5cdb3891e8740cc047c5ec3203688614f2213742d0312730aad'),
  ('ur.jalandhry', 2, 59, 66, 'تو جو ظالم تھے، انہوں نے اس لفظ کو، جس کا ان کو حکم دیا تھا، بدل کر اس کی جگہ اور لفظ کہنا شروع کیا، پس ہم نے (ان) ظالموں پر آسمان سے عذاب نازل کیا، کیونکہ نافرمانیاں کئے جاتے تھے', NULL, NULL, '72a0dad0af4c485651bb6aee4896678d9f541857f6705d1db09faf790574f5a0'),
  ('ur.jalandhry', 2, 60, 67, 'اور جب موسیٰ نے اپنی قوم کے لیے (خدا سے) پانی مانگا تو ہم نے کہا کہ اپنی لاٹھی پتھر پر مارو۔ (انہوں نے لاٹھی ماری) تو پھر اس میں سے بارہ چشمے پھوٹ نکلے، اور تمام لوگوں نے اپنا اپنا گھاٹ معلوم کر (کے پانی پی) لیا۔ (ہم نے حکم دیا کہ) خدا کی (عطا فرمائی ہوئی) روزی کھاؤ اور پیو، مگر زمین میں فساد نہ کرتے پھرنا', NULL, NULL, 'e89354b8edc5579ce1e913dce4e8d0d144c1d530ef724239238d7659a84729ab'),
  ('ur.jalandhry', 2, 61, 68, 'اور جب تم نے کہا کہ موسیٰ! ہم سے ایک (ہی) کھانے پر صبر نہیں ہو سکتا تو اپنے پروردگار سے دعا کیجئے کہ ترکاری اور ککڑی اور گیہوں اور مسور اور پیاز (وغیرہ) جو نباتات زمین سے اُگتی ہیں، ہمارے لیے پیدا کر دے۔ انہوں نے کہا کہ بھلا عمدہ چیزیں چھوڑ کر ان کے عوض ناقص چیزیں کیوں چاہتے ہوں۔ (اگر یہی چیزیں مطلوب ہیں) تو کسی شہر میں جا اترو، وہاں جو مانگتے ہو، مل جائے گا۔ اور (آخرکار) ذلت (ورسوائی) اور محتاجی (وبے نوائی) ان سے چمٹا دی گئی اور وہ الله کے غضب میں گرفتار ہو گئے۔ یہ اس لیے کہ وہ الله کی آیتوں سے انکار کرتے تھے اور (اس کے) نبیوں کو ناحق قتل کر دیتے تھے۔ (یعنی) یہ اس لیے کہ نافرمانی کئے جاتے اور حد سے بڑھے جاتے تھے', NULL, NULL, '9ca6a09245b16c298b0c35206c0f9bc913991a13818b3de4f864ff56f606d121'),
  ('ur.jalandhry', 2, 62, 69, 'جو لوگ مسلمان ہیں یا یہودی یا عیسائی یا ستارہ پرست، (یعنی کوئی شخص کسی قوم و مذہب کا ہو) جو خدا اور روز قیامت پر ایمان لائے گا، اور نیک عمل کرے گا، تو ایسے لوگوں کو ان (کے اعمال) کا صلہ خدا کے ہاں ملے گا اور (قیامت کے دن) ان کو نہ کسی طرح کا خوف ہوگا اور نہ وہ غم ناک ہوں گے', NULL, NULL, '1fb9c5ca617b29c3131545992b11f7bfb92023d35e7747e1dd38c7f42aa3fd21'),
  ('ur.jalandhry', 2, 63, 70, 'اور جب ہم نے تم سے عہد (کر) لیا اور کوہِ طُور کو تم پر اٹھا کھڑا کیا (اور حکم دیا) کہ جو کتاب ہم نے تم کو دی ہے، اس کو زور سے پکڑے رہو، اور جو اس میں (لکھا) ہے، اسے یاد رکھو، تاکہ (عذاب سے) محفوظ رہو', NULL, NULL, '54bde80518a9575a19103fcb7a928af055cee3dd7f20cad9da3542efacce6425'),
  ('ur.jalandhry', 2, 64, 71, 'تو تم اس کے بعد (عہد سے) پھر گئے اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو تم خسارے میں پڑے گئے ہوتے', NULL, NULL, '5f9c942600fb29f0ffab4a55f27116d8082493ad39b1b2e1710ff0ea3eb41ddd'),
  ('ur.jalandhry', 2, 65, 72, 'اور تم ان لوگوں کو خوب جانتے ہوں، جو تم میں سے ہفتے کے دن (مچھلی کا شکار کرنے) میں حد سے تجاوز کر گئے تھے، تو ہم نے ان سے کہا کہ ذلیل وخوار بندر ہو جاؤ', NULL, NULL, '4d77d765dfc65b85a15e003e68e86d6eb348ef2a7d8b4e90f5be1e8c705200f8'),
  ('ur.jalandhry', 2, 66, 73, 'اور اس قصے کو اس وقت کے لوگوں کے لیے اور جو ان کے بعد آنے والے تھے عبرت اور پرہیز گاروں کے لیے نصیحت بنا دیا', NULL, NULL, 'cd3f176b62928272f1ce7700d559b867f8f73099097b057d2b716c9a444c443f'),
  ('ur.jalandhry', 2, 67, 74, 'اور جب موسیٰ نے اپنی قوم کے لوگوں سے کہا کہ خدا تم کو حکم دیتا ہے کہ ایک بیل ذبح کرو۔ وہ بولے، کیا تم ہم سے ہنسی کرتے ہو۔ (موسیٰ نے) کہا کہ میں الله کی پناہ مانگتا ہوں کہ نادان بنوں', NULL, NULL, '6706074a8a501faf48500cdddacc86629b77e1ed78a5a0da9783ffda9a342b7e'),
  ('ur.jalandhry', 2, 68, 75, 'انہوں نے کہا کہ اپنے پروردگار سے التجا کیجئے کہ وہ ہمیں یہ بتائے کہ وہ بیل کس طرح کا ہو۔ (موسیٰ نے) کہا کہ پروردگار فرماتا ہے کہ وہ بیل نہ تو بوڑھا ہو اور نہ بچھڑا، بلکہ ان کے درمیان (یعنی جوان) ہو۔ جیسا تم کو حکم دیا گیا ہے، ویسا کرو', NULL, NULL, 'dc378567741be7dafc31ded5c3111d8d5706207b2aefc04de817f829c35a8e85'),
  ('ur.jalandhry', 2, 69, 76, 'انہوں نے کہا کہ پروردگار سے درخواست کیجئے کہ ہم کو یہ بھی بتائے کہ اس کا رنگ کیسا ہو۔ موسیٰ نے کہا، پروردگار فرماتا ہے کہ اس کا رنگ گہرا زرد ہو کہ دیکھنے والوں (کے دل) کو خوش کر دیتا ہو', NULL, NULL, '7e0f9f7cb3bcea7a895d14bc5a3fd6482bf5f2e2718f2c28ff223583853fba6f'),
  ('ur.jalandhry', 2, 70, 77, 'انہوں نے کہا کہ (اب کے) پروردگار سے پھر درخواست کیجئے کہ ہم کو بتا دے کہ وہ اور کس کس طرح کا ہو، کیونکہ بہت سے بیل ہمیں ایک دوسرے کے مشابہ معلوم ہوتے ہیں، (پھر) خدا نے چاہا تو ہمیں ٹھیک بات معلوم ہو جائے گی', NULL, NULL, 'b36e267ead5f505c1b071068b238afa53edadf3cedcd16eb35bce589c1a3c640'),
  ('ur.jalandhry', 2, 71, 78, 'موسیٰ نے کہا کہ خدا فرماتا ہے کہ وہ بیل کام میں لگا ہوا نہ ہو، نہ تو زمین جوتتا ہو اور نہ کھیتی کو پانی دیتا ہو۔ اس میں کسی طرح کا داغ نہ ہو۔ کہنے لگے، اب تم نے سب باتیں درست بتا دیں۔ غرض (بڑی مشکل سے) انہوں نے اس بیل کو ذبح کیا، اور وہ ایسا کرنے والے تھے نہیں', NULL, NULL, '9576509070bcbc1ab0c4567b238fe894344aa82304fa9af63aafd8bf33cb4c13'),
  ('ur.jalandhry', 2, 72, 79, 'اور جب تم نے ایک شخص کو قتل کیا، تو اس میں باہم جھگڑنے لگے۔ لیکن جو بات تم چھپا رہے تھے، خدا اس کو ظاہر کرنے والا تھا', NULL, NULL, '7d5eeb93e0659f492d060dd78bf2ca80b7ddb022f0e18b1adcdced39b8224167'),
  ('ur.jalandhry', 2, 73, 80, 'تو ہم نے کہا کہ اس بیل کا کوئی سا ٹکڑا مقتول کو مارو۔ اس طرح خدا مردوں کو زندہ کرتا ہے اور تم کو اپنی (قدرت کی) نشانیاں دکھاتا ہے تاکہ تم سمجھو', NULL, NULL, 'e66454a07500a2b66f95951e383189791811ccbb1636b1a77bace9b9a7f90072'),
  ('ur.jalandhry', 2, 74, 81, 'پھر اس کے بعد تمہارے دل سخت ہو گئے۔ گویا وہ پتھر ہیں یا ان سے بھی زیادہ سخت۔ اور پتھر تو بعضے ایسے ہوتے ہیں کہ ان میں سے چشمے پھوٹ نکلتے ہیں، اور بعضے ایسے ہوتے ہیں کہ پھٹ جاتے ہیں، اور ان میں سے پانی نکلنے لگتا ہے، اور بعضے ایسے ہوتے ہیں کہ خدا کے خوف سے گر پڑتے ہیں، اور خدا تمہارے عملوں سے بے خبر نہیں', NULL, NULL, '0a47536b1f01d9ca741069b8588b100f565b00a5b00375114ee9efae3afc730e'),
  ('ur.jalandhry', 2, 75, 82, '(مومنو) کیا تم امید رکھتے ہو کہ یہ لوگ تمہارے (دین کے) قائل ہو جائیں گے، (حالانکہ) ان میں سے کچھ لوگ کلامِ خدا (یعنی تورات) کو سنتے، پھر اس کے سمجھ لینے کے بعد اس کو جان بوجھ کر بدل دیتے رہے ہیں', NULL, NULL, '23cbfab4458cbf92befcde1ea20eed2724aa2876a56dbb2037f69a9b0f148a93'),
  ('ur.jalandhry', 2, 76, 83, 'اور یہ لوگ جب مومنوں سے ملتے ہیں تو کہتے ہیں، ہم ایمان لے آئے ہیں۔ اور جب آپس میں ایک دوسرے سے ملتے ہیں تو کہتے ہیں، جو بات خدا نے تم پر ظاہر فرمائی ہے، وہ تم ان کو اس لیے بتائے دیتے ہو کہ (قیامت کے دن) اسی کے حوالے سے تمہارے پروردگار کے سامنے تم کو الزام دیں۔ کیا تم سمجھتے نہیں؟', NULL, NULL, '5cc2907a4fe4b20fa65c38821f8d665d8c47360b3a82e271b91662d30cf6155c'),
  ('ur.jalandhry', 2, 77, 84, 'کیا یہ لوگ یہ نہیں جانتے کہ جو کچھ یہ چھپاتے اور جو کچھ ظاہر کرتے ہیں، خدا کو (سب) معلوم ہے', NULL, NULL, 'd228975fc1b12742c4df9faa914de19ecb208bfcccbad9355d5b988a14e3d48e'),
  ('ur.jalandhry', 2, 78, 85, 'اور بعض ان میں ان پڑھ ہیں کہ اپنے باطل خیالات کے سوا (خدا کی) کتاب سے واقف ہی نہیں اور وہ صرف ظن سے کام لیتے ہیں', NULL, NULL, 'd2dcc0059325deb0d053a89cc8d1af926c7ddb27c648090e3c54cc754e345ab3'),
  ('ur.jalandhry', 2, 79, 86, 'تو ان لوگوں پر افسوس ہے جو اپنے ہاتھ سے تو کتاب لکھتے ہیں اور کہتے یہ ہیں کہ یہ خدا کے پاس سے (آئی) ہے، تاکہ اس کے عوض تھوڑی سے قیمت (یعنی دنیوی منفعت) حاصل کریں۔ ان پر افسوس ہے، اس لیے کہ (بےاصل باتیں) اپنے ہاتھ سے لکھتے ہیں اور (پھر) ان پر افسوس ہے، اس لیے کہ ایسے کام کرتے ہیں', NULL, NULL, '48c1d71e5a615d5d74b35a40fca27fa248902605df7115ad4963f7d490dc885d'),
  ('ur.jalandhry', 2, 80, 87, 'اور کہتے ہیں کہ (دوزخ کی) آگ ہمیں چند روز کے سوا چھو ہی نہیں سکے گی۔ ان سے پوچھو، کیا تم نے خدا سے اقرار لے رکھا ہے کہ خدا اپنے اقرار کے خلاف نہیں کرے گا۔ (نہیں)، بلکہ تم خدا کے بارے میں ایسی باتیں کہتے ہو جن کا تمہیں مطلق علم نہیں', NULL, NULL, 'a8ec08020c49f891653d9f8be8c5e2048bfeeeb5574fb8725405de2ccdbbb149'),
  ('ur.jalandhry', 2, 81, 88, 'ہاں جو برے کام کرے، اور اس کے گناہ (ہر طرف سے) گھیر لیں تو ایسے لوگ دوزخ (میں جانے) والے ہیں (اور) وہ ہمیشہ اس میں (جلتے) رہیں گے', NULL, NULL, '20811664e12212b9cda0e2217d8335f840ae2490498dc6f05460ea62d3f95869'),
  ('ur.jalandhry', 2, 82, 89, 'اور جو ایمان لائیں اور نیک کام کریں، وہ جنت کے مالک ہوں گے (اور) ہمیشہ اس میں (عیش کرتے) رہیں گے', NULL, NULL, '1f8919e1c1aa73a5244e124cf3662f353f62da7b710c1a4f954e327ff5e2dded'),
  ('ur.jalandhry', 2, 83, 90, 'اور جب ہم نے بنی اسرائیل سے عہد لیا کہ خدا کے سوا کسی کی عبادت نہ کرنا اور ماں باپ اور رشتہ داروں اور یتیموں اور محتاجوں کے ساتھ بھلائی کرتے رہنا اور لوگوں سے اچھی باتیں کہنا، اور نماز پڑھتے اور زکوٰة دیتے رہنا، تو چند شخصوں کے سوا تم سب (اس عہد سے) منہ پھیر کر پھر بیٹھے', NULL, NULL, '11ebc1b7e86a67e9e396fec66732eb3d9fd8203e4dae0204d44db0a4d27d3e20'),
  ('ur.jalandhry', 2, 84, 91, 'اور جب ہم نے تم سے عہد لیا کہ آپس میں کشت وخون نہ کرنا اور اپنے کو ان کے وطن سے نہ نکالنا تو تم نے اقرار کر لیا، اور تم (اس بات کے) گواہ ہو', NULL, NULL, 'f1cba14fc3aedbf5445f832c672e633724788a71bd16258d5b3d7f167bbfc7d7'),
  ('ur.jalandhry', 2, 85, 92, 'پھر تم وہی ہو کہ اپنوں کو قتل بھی کر دیتے ہو اور اپنے میں سے بعض لوگوں پر گناہ اور ظلم سے چڑھائی کرکے انہیں وطن سے نکال بھی دیتے ہو، اور اگر وہ تمہارے پاس قید ہو کر آئیں تو بدلہ دے کر ان کو چھڑا بھی لیتے ہو، حالانکہ ان کا نکال دینا ہی تم کو حرام تھا۔ (یہ) کیا (بات ہے کہ) تم کتابِ (خدا) کے بعض احکام کو تو مانتے ہو اور بعض سے انکار کئے دیتے ہو، تو جو تم میں سے ایسی حرکت کریں، ان کی سزا اس کے سوا اور کیا ہو سکتی ہے کہ دنیا کی زندگی میں تو رسوائی ہو اور قیامت کے دن سخت سے سخت عذاب میں ڈال دیئے جائیں اور جو کام تم کرتے ہو، خدا ان سے غافل نہیں', NULL, NULL, 'c452b6e70b198bdcb637261498d42eec0f195b0f66619ddcfb67718da33f4ebf'),
  ('ur.jalandhry', 2, 86, 93, 'یہ وہ لوگ ہیں جنہوں نے آخرت کے بدلے دنیا کی زندگی خریدی۔ سو نہ تو ان سے عذاب ہی ہلکا کیا جائے گا اور نہ ان کو (اور طرح کی) مدد ملے گی', NULL, NULL, '6f9eda9db95f331ab2d033063f44f028f0eef2df186bb24dbebf98596b398150'),
  ('ur.jalandhry', 2, 87, 94, 'اور ہم نے موسیٰ کو کتاب عنایت کی اور ان کے پیچھے یکے بعد دیگرے پیغمبر بھیجتے رہے اور عیسیٰ بن مریم کو کھلے نشانات بخشے اور روح القدس (یعنی جبرئیل) سے ان کو مدد دی۔تو جب کوئی پیغمبر تمہارے پاس ایسی باتیں لے کر آئے، جن کو تمہارا جی نہیں چاہتا تھا، تو تم سرکش ہو جاتے رہے، اور ایک گروہ (انبیاء) کو تو جھٹلاتے رہے اور ایک گروہ کو قتل کرتے رہے', NULL, NULL, 'c96df5acda3e0b22460421d940ac6fd6afc0d2811139f97f00d15015c041a6ca'),
  ('ur.jalandhry', 2, 88, 95, 'اور کہتے ہیں، ہمارے دل پردے میں ہیں۔ (نہیں) بلکہ الله نے ان کے کفر کے سبب ان پر لعنت کر رکھی ہے۔ پس یہ تھوڑے ہی پر ایمان لاتے ہیں', NULL, NULL, 'e1635096e6637674c966d80965b1fcd2195ee5d502d23903b4a6ae655f898a0e'),
  ('ur.jalandhry', 2, 89, 96, 'اور جب الله کے ہاں سے ان کے پاس کتاب آئی جو ان کی (آسمانی) کتاب کی بھی تصدیق کرتی ہے، اور وہ پہلے (ہمیشہ) کافروں پر فتح مانگا کرتے تھے، تو جس چیز کو وہ خوب پہچانتے تھے، جب ان کے پاس آپہنچی تو اس سے کافر ہو گئے۔ پس کافروں پر الله کی لعنت', NULL, NULL, '70cd36868a66103cfda5427e42abe1f7c1451b7ec4caa8ac8fbfc401c7ba7395'),
  ('ur.jalandhry', 2, 90, 97, 'جس چیز کے بدلے انہوں نے اپنے تئیں بیچ ڈالا، وہ بہت بری ہے، یعنی اس جلن سے کہ خدا اپنے بندوں میں جس پر چاہتا ہے، اپنی مہربانی سے نازل فرماتا ہے۔ خدا کی نازل کی ہوئی کتاب سے کفر کرنے لگے تو وہ (اس کے) غضب بالائے غضب میں مبتلا ہو گئے۔ اور کافروں کے لیے ذلیل کرنے والا عذاب ہے', NULL, NULL, '489cdd14ff01f02a7022be63b0de9b3c45a683c47da766ee436e0b9bb2e1d1f5'),
  ('ur.jalandhry', 2, 91, 98, 'اور جب ان سے کہا جاتا ہے کہ جو (کتاب) خدا نے (اب) نازل فرمائی ہے، اس کو مانو۔ تو کہتے ہیں کہ جو کتاب ہم پر (پہلے) نازل ہو چکی ہے، ہم تو اسی کو مانتے ہیں۔ (یعنی) یہ اس کے سوا کسی اور (کتاب) کو نہیں مانتے، حالانکہ وہ (سراسر) سچی ہے اور جو ان کی (آسمانی) کتاب ہے، اس کی بھی تصدیق کرتی ہے۔ (ان سے) کہہ دو کہ اگر تم صاحبِ ایمان ہوتے تو الله کے پیغمبروں کو پہلے ہی کیوں قتل کیا کرتے', NULL, NULL, '4d0ff098b1b3b9ee60bffc135e0ed733d0dbec6b894b3b3c8e6a8bcbcfbca66f'),
  ('ur.jalandhry', 2, 92, 99, 'اور موسیٰ تمہارے پاس کھلے ہوئے معجزات لے کر آئے تو تم ان کے (کوہِ طور جانے کے) بعد بچھڑے کو معبود بنا بیٹھے اور تم (اپنے ہی حق میں) ظلم کرتے تھے', NULL, NULL, 'a0dd682bcf86e8dc4a98f203379869ae8adec517ff2ee869f81dca4a6b7a0923'),
  ('ur.jalandhry', 2, 93, 100, 'اور جب ہم نے تم (لوگوں) سے عہد واثق لیا اور کوہ طور کو تم پر اٹھا کھڑا کیا (اور حکم دیا کہ) جو (کتاب) ہم نے تم کو دی ہے، اس کو زور سے پکڑو اور جو تمہیں حکم ہوتا ہے (اس کو) سنو تو وہ (جو تمہارے بڑے تھے) کہنے لگے کہ ہم نے سن تو لیا لیکن مانتے نہیں۔ اور ان کے کفر کے سبب بچھڑا (گویا) ان کے دلوں میں رچ گیا تھا۔ (اے پیغمبر ان سے) کہہ دو کہ اگر تم مومن ہو تو تمہارا ایمان تم کو بری بات بتاتا ہے', NULL, NULL, '421514b120f46fc6ce9ccecf02d6730542e93509b335abe095d756b421480a64')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 2, 94, 101, 'کہہ دو کہ اگر آخرت کا گھر اور لوگوں (یعنی مسلمانوں) کے لیے نہیں اور خدا کے نزدیک تمہارے ہی لیے مخصوص ہے تو اگر سچے ہو تو موت کی آرزو تو کرو', NULL, NULL, 'cd9da4d2efa06ba32d1ae0e4b28a5a89c1106e137e59e98766e13e1b14c6c64a'),
  ('ur.jalandhry', 2, 95, 102, 'لیکن ان اعمال کی وجہ سے، جو ان کے ہاتھ آگے بھیج چکے ہیں، یہ کبھی اس کی آرزو نہیں کریں گے، اور خدا ظالموں سے (خوب) واقف ہے', NULL, NULL, '1341c68470c9a8055b06539eca31392203368b58d286c9a794be3207aa74da09'),
  ('ur.jalandhry', 2, 96, 103, 'بلکہ ان کو تم اور لوگوں سے زندگی کے کہیں حریص دیکھو گے، یہاں تک کہ مشرکوں سے بھی۔ ان میں سے ہر ایک یہی خواہش کرتا ہے کہ کاش وہ ہزار برس جیتا رہے، مگر اتنی لمبی عمر اس کو مل بھی جائے تو اسے عذاب سے تو نہیں چھڑا سکتی۔ اور جو کام یہ کرتے ہیں، خدا ان کو دیکھ رہا ہے', NULL, NULL, '8ffb932320e805491889b207c9f17fde74d212a5a5fd357c199a9e2b853fc426'),
  ('ur.jalandhry', 2, 97, 104, 'کہہ دو کہ جو شخص جبرئیل کا دشمن ہو (اس کو غصے میں مر جانا چاہیئے) اس نے تو (یہ کتاب) خدا کے حکم سے تمہارے دل پر نازل کی ہے جو پہلی کتابوں کی تصدیق کرتی ہے، اور ایمان والوں کے لیے ہدایت اور بشارت ہے', NULL, NULL, '698b653d9dbcc0089f5472f84fd2cfc4c8464508f49727503e6a4536b7596bde'),
  ('ur.jalandhry', 2, 98, 105, 'جو شخص خدا کا اور اس کے فرشتوں کا اور اس کے پیغمبروں کا اور جبرئیل اور میکائیل کا دشمن ہو تو ایسے کافروں کا خدا دشمن ہے', NULL, NULL, '1644cc091c487025dddff58cfc30826eec9edf5f18a47c0470287b163dd96769'),
  ('ur.jalandhry', 2, 99, 106, 'اور ہم نے تمہارے پاس سلجھی ہوئی آیتیں ارسال فرمائی ہیں، اور ان سے انکار وہی کرتے ہیں جو بدکار ہیں', NULL, NULL, 'cecc75e8a39c69efe748cdce2a116126e168b2bbc99b63493308e816d6676eec'),
  ('ur.jalandhry', 2, 100, 107, 'ان لوگوں نے جب (خدا سے) عہد واثق کیا تو ان میں سے ایک فریق نے اس کو (کسی چیز کی طرح) پھینک دیا۔ حقیقت یہ ہے کہ ان میں اکثر بے ایمان ہیں', NULL, NULL, '74779428947d6c3cd1500cbbba23689cbcaba05abda3d66f59f8ace612009290'),
  ('ur.jalandhry', 2, 101, 108, 'اور جب ان کے پاس الله کی طرف سے پیغمبر (آخرالزماں) آئے، اور وہ ان کی (آسمانی) کتاب کی بھی تصدیق کرتے ہیں تو جن لوگوں کو کتاب دی گئی تھی، ان میں سے ایک جماعت نے خدا کی کتاب کو پیٹھ پیچھے پھینک دیا، گویا وہ جانتے ہی نہیں', NULL, NULL, '89eec686265cbb0ad51bc237eafb8f7a24fa0bd90e5e2b4ea973a1ae2d5f4c74'),
  ('ur.jalandhry', 2, 102, 109, 'اور ان (ہزلیات) کے پیچھے لگ گئے جو سلیمان کے عہدِ سلطنت میں شیاطین پڑھا کرتے تھے اور سلیمان نے مطلق کفر کی بات نہیں کی، بلکہ شیطان ہی کفر کرتے تھے کہ لوگوں کو جادو سکھاتے تھے۔ اور ان باتوں کے بھی (پیچھے لگ گئے) جو شہر بابل میں دو فرشتوں (یعنی) ہاروت اور ماروت پر اتری تھیں۔ اور وہ دونوں کسی کو کچھ نہیں سکھاتے تھے، جب تک یہ نہ کہہ دیتے کہ ہم تو (ذریعہٴ) آزمائش ہیں۔ تم کفر میں نہ پڑو۔ غرض لوگ ان سے (ایسا) جادو سیکھتے، جس سے میاں بیوی میں جدائی ڈال دیں۔ اور خدا کے حکم کے سوا وہ اس (جادو) سے کسی کا کچھ بھی نہیں بگاڑ سکتے تھے۔ اور کچھ ایسے (منتر) سیکھتے جو ان کو نقصان ہی پہنچاتے اور فائدہ کچھ نہ دیتے۔ اور وہ جانتے تھے کہ جو شخص ایسی چیزوں (یعنی سحر اور منتر وغیرہ) کا خریدار ہوگا، اس کا آخرت میں کچھ حصہ نہیں۔ اور جس چیز کے عوض انہوں نے اپنی جانوں کو بیچ ڈالا، وہ بری تھی۔ کاش وہ (اس بات کو) جانتے', NULL, NULL, '81098b2885bc40125ddbd3527dd9cb2704a532a30b8bfed2bdd0f3f7e64d509b'),
  ('ur.jalandhry', 2, 103, 110, 'اور اگر وہ ایمان لاتے اور پرہیز گاری کرتے تو خدا کے ہاں سے بہت اچھا صلہ ملتا۔ اے کاش، وہ اس سے واقف ہوتے', NULL, NULL, 'e4ca546919bcbbf6c69b9f2a19eda304b4719eed38e466f92a991311aba8c874'),
  ('ur.jalandhry', 2, 104, 111, 'اے اہل ایمان! (گفتگو کے وقت پیغمبرِ خدا سے) راعنا نہ کہا کرو۔ انظرنا کہا کرو۔ اور خوب سن رکھو، اور کافروں کے لیے دکھ دینے والا عذاب ہے', NULL, NULL, '178d09b3dde163a466503fb33a520c3df1f7e9945bdf53ad7069aead37550e8c'),
  ('ur.jalandhry', 2, 105, 112, 'جو لوگ کافر ہیں، اہل کتاب یا مشرک وہ اس بات کو پسند نہیں کرتے کہ تم پر تمہارے پروردگار کی طرف سے خیر (وبرکت) نازل ہو۔ اور خدا تو جس کو چاہتا ہے، اپنی رحمت کے ساتھ خاص کر لیتا ہے اور خدا بڑے فضل کا مالک ہے', NULL, NULL, '73019158ad78dcdbc415a53085da3e92bf912907b428c64466b7dd0634a83400'),
  ('ur.jalandhry', 2, 106, 113, 'ہم جس آیت کو منسوخ کر دیتے یا اسے فراموش کرا دیتے ہیں تو اس سے بہتر یا ویسی ہی اور آیت بھیج دیتے ہیں۔ کیا تم نہیں جانتے کہ خدا ہر بات پر قادر ہے', NULL, NULL, '457159d9d0e1a2a1ba3c3ededf4c36fbac6c0b2cc18b853e9173d147b171313c'),
  ('ur.jalandhry', 2, 107, 114, 'تمہیں معلوم نہیں کہ آسمانوں اور زمین کی بادشاہت خدا ہی کی ہے، اور خدا کے سوا تمہارا کوئی دوست اور مدد گار نہیں', NULL, NULL, 'f0bbe7b2ccebe219cce6b8d1df1bd31d12edfb2c05b6d2e29149949e9dcda715'),
  ('ur.jalandhry', 2, 108, 115, 'کیا تم یہ چاہتے ہو کہ اپنے پیغمبر سے اسی طرح کے سوال کرو، جس طرح کے سوال پہلے موسیٰ سے کئے گئے تھے۔ اور جس شخص نے ایمان (چھوڑ کر اس) کے بدلے کفر لیا، وہ سیدھے رستے سے بھٹک گیا', NULL, NULL, 'e5b84a5ea4d561974d3fd38548a175168037788d68a637324cddd375654ffed3'),
  ('ur.jalandhry', 2, 109, 116, 'بہت سے اہل کتاب اپنے دل کی جلن سے یہ چاہتے ہیں کہ ایمان لا چکنے کے بعد تم کو پھر کافر بنا دیں۔ حالانکہ ان پر حق ظاہر ہو چکا ہے۔ تو تم معاف کردو اور درگزر کرو۔ یہاں تک کہ خدا اپنا (دوسرا) حکم بھیجے۔ بے شک خدا ہر بات پر قادر ہے', NULL, NULL, '21b51a651a3e4d9f5ff47cc8f593202cf1645b8dc08d6e9fa91f5114a83677a9'),
  ('ur.jalandhry', 2, 110, 117, 'اور نماز ادا کرتے رہو اور زکوٰة دیتے رہو۔ اور جو بھلائی اپنے لیے آگے بھیج رکھو گے، اس کو خدا کے ہاں پا لو گے۔ کچھ شک نہیں کہ خدا تمہارے سب کاموں کو دیکھ رہا ہے', NULL, NULL, 'ec3758840e2022c84798a100191e6fb7734312983adc1f6ac67bc7ca3062cfbc'),
  ('ur.jalandhry', 2, 111, 118, 'اور (یہودی اور عیسائی) کہتے ہیں کہ یہودیوں اور عیسائیوں کے سوا کوئی بہشت میں نہیں جانے کا۔ یہ ان لوگوں کے خیالاتِ باطل ہیں۔ (اے پیغمبر ان سے) کہہ دو کہ اگر سچے ہو تو دلیل پیش کرو', NULL, NULL, '482cd0581b25a546bb055aec80b4883f298b068497bc53801458410ddaf7798e'),
  ('ur.jalandhry', 2, 112, 119, 'ہاں جو شخص خدا کے آگے گردن جھکا دے، (یعنی ایمان لے آئے) اور وہ نیکو کار بھی ہو تو اس کا صلہ اس کے پروردگار کے پاس ہے اور ایسے لوگوں کو (قیامت کے دن) نہ کسی طرح کا خوف ہوگا اور نہ وہ غمناک ہوں گے', NULL, NULL, '8b71982a5b406fcc97e9aeafc79614a8eb4295695e78911445e47edafccd2b88'),
  ('ur.jalandhry', 2, 113, 120, 'اور یہودی کہتے ہیں کہ عیسائی رستے پر نہیں اور عیسائی کہتے ہیں کہ یہودی رستے پر نہیں۔ حالانکہ وہ کتاب (الہٰی) پڑھتے ہیں۔ اسی طرح بالکل انہی کی سی بات وہ لوگ کہتے ہیں جو (کچھ) نہیں جانتے (یعنی مشرک) تو جس بات میں یہ لوگ اختلاف کر رہے خدا قیامت کے دن اس کا ان میں فیصلہ کر دے گا', NULL, NULL, '7949a4f41ed665eed0da991889775d61088a7e00945937751ab858e6f7f2dd32'),
  ('ur.jalandhry', 2, 114, 121, 'اور اس سے بڑھ کر ظالم کون، جو خدا کی مسجدوں میں خدا کے نام کا ذکر کئے جانے کو منع کرے اور ان کی ویرانی میں ساعی ہو۔ان لوگوں کو کچھ حق نہیں کہ ان میں داخل ہوں، مگر ڈرتے ہوئے۔ ان کے لیے دنیا میں رسوائی ہے اور آخرت میں بڑا عذاب', NULL, NULL, 'db95ae1f3dbda03db4b703ed134aed7edd618c911348d2e25c4bd0ef9530f4df'),
  ('ur.jalandhry', 2, 115, 122, 'اور مشرق اور مغرب سب خدا ہی کا ہے۔ تو جدھر تم رخ کرو۔ ادھر خدا کی ذات ہے۔ بے شک خدا صاحبِ وسعت اور باخبر ہے', NULL, NULL, 'afd29de12571f62a2da30b165080c4a8897475926411fc0f62c5fa15b266117f'),
  ('ur.jalandhry', 2, 116, 123, 'اور یہ لوگ اس بات کے قائل ہیں کہ خدا اولاد رکھتا ہے۔ (نہیں) وہ پاک ہے، بلکہ جو کچھ آسمانوں اور زمین میں ہے، سب اسی کا ہے اور سب اس کے فرماں بردار ہیں', NULL, NULL, '4152dfa4c3515b2f5daf4ebbb49e302a6667bf80df33b17c2eba97d745a0dfc7'),
  ('ur.jalandhry', 2, 117, 124, '(وہی) آسمانوں اور زمین کا پیدا کرنے والاہے۔ جب کوئی کام کرنا چاہتا ہے تو اس کو ارشاد فرما دیتا ہے کہ ہوجا تو وہ ہو جاتا ہے.', NULL, NULL, 'b11c15f1c7a1a27e892de245834a63e0039ff71c06c4d22633d162beb43d9a79'),
  ('ur.jalandhry', 2, 118, 125, 'اور جو لوگ (کچھ) نہیں جانتے (یعنی مشرک) وہ کہتے ہیں کہ خدا ہم سے کلام کیوں نہیں کرتا۔ یا ہمارے پاس کوئی نشانی کیوں نہیں آتی۔ اسی طرح جو لوگ ان سے پہلے تھے، وہ بھی انہی کی سی باتیں کیا کرتے تھے۔ ان لوگوں کے دل آپس میں ملتے جلتے ہیں۔ جو لوگ صاحبِ یقین ہیں، ان کے (سمجھانے کے) لیے نشانیاں بیان کردی ہیں', NULL, NULL, '758ca09690a64e52bc1e718d5061658b15d11b4e560bbb878dbfb2d87d250502'),
  ('ur.jalandhry', 2, 119, 126, '(اے محمدﷺ) ہم نے تم کو سچائی کے ساتھ خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا ہے۔ اور اہل دوزخ کے بارے میں تم سے کچھ پرسش نہیں ہوگی', NULL, NULL, '7e74e3da81f9a8c47db17ea7c04d180a6461c7cc749c0b00e7cc3b8c56cf7ceb'),
  ('ur.jalandhry', 2, 120, 127, 'اور تم سے نہ تو یہودی کبھی خوش ہوں گے اور نہ عیسائی، یہاں تک کہ تم ان کے مذہب کی پیروی اختیار کرلو۔ (ان سے) کہہ دو کہ خدا کی ہدایت (یعنی دین اسلام) ہی ہدایت ہے۔ اور (اے پیغمبر) اگر تم اپنے پاس علم (یعنی وحی خدا) کے آ جانے پر بھی ان کی خواہشوں پر چلو گے تو تم کو (عذاب) خدا سے (بچانے والا) نہ کوئی دوست ہوگا اور نہ کوئی مددگار', NULL, NULL, '397b38b160fa1c195ea4bbea891992fb883658d5e478bbba8dc4f8e373cc2cb3'),
  ('ur.jalandhry', 2, 121, 128, 'جن لوگوں کو ہم نے کتاب عنایت کی ہے، وہ اس کو (ایسا) پڑھتے ہیں جیسا اس کے پڑھنے کا حق ہے۔ یہی لوگ اس پر ایمان رکھنے والے ہیں، اور جو اس کو نہیں مانتے، وہ خسارہ پانے والے ہیں', NULL, NULL, '55e29efa840ad90980d4c3bf122f6fa82db89e913ccc9226c1aaaec37a910c61'),
  ('ur.jalandhry', 2, 122, 129, 'اے بنی اسرائیل! میرے وہ احسان یاد کرو، جو میں نے تم پر کئے اور یہ کہ میں نے تم کو اہلِ عالم پر فضیلت بخشی', NULL, NULL, '36ab302cd9541af00c1544685775e71ee01c23a4ab98a536ed4855dde6037e1f'),
  ('ur.jalandhry', 2, 123, 130, 'اور اس دن سے ڈرو جب کوئی شخص کسی شخص کے کچھ کام نہ آئے، اور نہ اس سے بدلہ قبول کیا جائے اور نہ اس کو کسی کی سفارش کچھ فائدہ دے اور نہ لوگوں کو (کسی اور طرح کی) مدد مل سکے', NULL, NULL, '973afb7cd7d6b57229562b562f8e7d9ab6f4ed3f4a304162b7261efd28093bfc'),
  ('ur.jalandhry', 2, 124, 131, 'اور جب پروردگار نے چند باتوں میں ابراہیم کی آزمائش کی تو ان میں پورے اترے۔ خدا نے کہا کہ میں تم کو لوگوں کا پیشوا بناؤں گا۔ انہوں نے کہا کہ (پروردگار) میری اولاد میں سے بھی (پیشوا بنائیو) ۔ خدا نے فرمایا کہ ہمارا اقرار ظالموں کے لیے نہیں ہوا کرتا', NULL, NULL, 'd5def3a5605f7ac54c75a61bd1646dc692a09c1465726dfe2d224b17d81dfa4b'),
  ('ur.jalandhry', 2, 125, 132, 'اور جب ہم نے خانہٴ کعبہ کو لوگوں کے لیے جمع ہونے اور امن پانے کی جگہ مقرر کیا اور (حکم دیا کہ) جس مقام پر ابراہیم کھڑے ہوئے تھے، اس کو نماز کی جگہ بنا لو۔ اور ابراہیم اور اسمٰعیل کو کہا کہ طواف کرنے والوں اور اعتکاف کرنے والوں اور رکوع کرنے والوں اور سجدہ کرنے والوں کے لیے میرے گھر کو پاک صاف رکھا کرو', NULL, NULL, '7307227e48f5ca3116d0d548ffe59c94e511cd8547aedeb686f086a75318ae5d'),
  ('ur.jalandhry', 2, 126, 133, 'اور جب ابراہیم نے دعا کی کہ اے پروردگار، اس جگہ کو امن کا شہر بنا اور اس کے رہنے والوں میں سے جو خدا پر اور روزِ آخرت پر ایمان لائیں، ان کے کھانے کو میوے عطا کر، تو خدا نے فرمایا کہ جو کافر ہوگا، میں اس کو بھی کسی قدر متمتع کروں گا، (مگر) پھر اس کو (عذاب) دوزخ کے (بھگتنے کے) لیے ناچار کردوں گا، اور وہ بری جگہ ہے', NULL, NULL, 'debf61a8ca243721bc7f2ce0fe4159d7e7af1d64c5e93587664ad94c5b430e7d'),
  ('ur.jalandhry', 2, 127, 134, 'اور جب ابراہیم اور اسمٰعیل بیت الله کی بنیادیں اونچی کر رہے تھے (تو دعا کئے جاتے تھے کہ) اے پروردگار، ہم سے یہ خدمت قبول فرما۔ بےشک تو سننے والا (اور) جاننے والا ہے', NULL, NULL, '3cc34339b89b4f6963cd1784de03b4b9665cfe9ad773f5367ce1ae8a0069cfb3'),
  ('ur.jalandhry', 2, 128, 135, 'اے پروردگار، ہم کو اپنا فرمانبردار بنائے رکھیو۔ اور ہماری اولاد میں سے بھی ایک گروہ کو اپنا مطیع بنائے رہیو، اور (پروردگار) ہمیں طریق عبادت بتا اور ہمارے حال پر (رحم کے ساتھ) توجہ فرما۔ بے شک تو توجہ فرمانے والا مہربان ہے', NULL, NULL, '7cae7ec126c0ffef430b6883db14e510f249891b896adb552a788f26924bfdfa'),
  ('ur.jalandhry', 2, 129, 136, 'اے پروردگار، ان (لوگوں) میں انہیں میں سے ایک پیغمبر مبعوث کیجیو جو ان کو تیری آیتیں پڑھ پڑھ کر سنایا کرے اور کتاب اور دانائی سکھایا کرے اور ان (کے دلوں) کو پاک صاف کیا کرے۔ بےشک تو غالب اور صاحبِ حکمت ہے', NULL, NULL, '1412cb0d270f53242c2e8e1cb1bcb720877db0a98edbc6d94eb4e2cfad3d2b25'),
  ('ur.jalandhry', 2, 130, 137, 'اور ابراہیم کے دین سے کون رو گردانی کر سکتا ہے، بجز اس کے جو نہایت نادان ہو۔ ہم نے ان کو دنیا میں بھی منتخب کیا تھا اور آخرت میں بھی وہ (زمرہٴ) صلحا میں سے ہوں گے', NULL, NULL, 'c606be7a1982c43d0335bc546c6d90336cb694a3a3f621daa5857f054e5b7288'),
  ('ur.jalandhry', 2, 131, 138, 'جب ان سے ان کے پروردگار نے فرمایا کہ اسلام لے آؤ تو انہوں نے عرض کی کہ میں رب العالمین کے آگے سر اطاعت خم کرتا ہوں', NULL, NULL, 'f5328f07d0df6fb310f52ca2c299c4f8a3e97fe14da3faa93b1eb3c5e51d2295'),
  ('ur.jalandhry', 2, 132, 139, 'اور ابرہیم نے اپنے بیٹوں کو اسی بات کی وصیت کی اور یعقوب نے بھی (اپنے فرزندوں سے یہی کہا) کہ بیٹا خدا نے تمہارے لیے یہی دین پسند فرمایا ہے تو مرنا ہے تو مسلمان ہی مرنا', NULL, NULL, 'a51e7e5768b6338e3c5643c1052c19494649da9dff3e6ba14f81bfad059cde9f'),
  ('ur.jalandhry', 2, 133, 140, 'بھلا جس وقت یعقوب وفات پانے لگے تو تم اس وقت موجود تھے، جب انہوں نے اپنے بیٹوں سے پوچھا کہ میرے بعد تم کس کی عبادت کرو گے، تو انہوں نے کہا کہ آپ کے معبود اور آپ کے باپ دادا ابراہیم اور اسمٰعیل اور اسحاق کے معبود کی عبادت کریں گے جو معبود یکتا ہے اور ہم اُسی کے حکم بردار ہیں', NULL, NULL, 'f8bfed9d7a5601f9b49727ed0ae9c0957dbc5e2c4b8bb4ea5c9efc8a4cbb10f1'),
  ('ur.jalandhry', 2, 134, 141, 'یہ جماعت گزرچکی۔ ان کو اُن کے اعمال (کا بدلہ ملے گا) اور تم کو تمھارے اعمال (کا) اور جو عمل وہ کرتے تھے ان کی پرسش تم سے نہیں ہوگی', NULL, NULL, '49e329c390a62023fa1a85ca7c05c8f661d966db4923e44578c9f8d3459592e1'),
  ('ur.jalandhry', 2, 135, 142, 'اور (یہودی اور عیسائی) کہتے ہیں کہ یہودی یا عیسائی ہو جاؤ تو سیدھے رستے پر لگ جاؤ۔ (اے پیغمبر ان سے) کہہ دو، (نہیں) بلکہ (ہم) دین ابراہیم (اختیار کئے ہوئے ہیں) جو ایک خدا کے ہو رہے تھے اور مشرکوں میں سے نہ تھے', NULL, NULL, '50baa64a370ddb98c7de046f5256c6a27f0552cc3b65e5e3e5c99bb1382cacb4'),
  ('ur.jalandhry', 2, 136, 143, '(مسلمانو) کہو کہ ہم خدا پر ایمان لائے اور جو (کتاب) ہم پر اتری، اس پر اور جو (صحیفے) ابراہیم اور اسمٰعیل اور اسحاق اور یعقوب اور ان کی اولاد پر نازل ہوئے ان پر اور جو (کتابیں) موسیٰ اور عیسی کو عطا ہوئیں، ان پر، اور جو اور پیغمبروں کو ان کے پروردگار کی طرف سے ملیں، ان پر (سب پر ایمان لائے) ہم ان پیغمروں میں سے کسی میں کچھ فرق نہیں کرتے اور ہم اسی (خدائے واحد) کے فرمانبردار ہیں', NULL, NULL, '33c1d93f796ce8c1fe77cff8ba94d3b890dd64a874b2eb61bb3aecd55873610e'),
  ('ur.jalandhry', 2, 137, 144, 'تو اگر یہ لوگ بھی اسی طرح ایمان لے آئیں جس طرح تم ایمان لے آئے ہو تو ہدایت یاب ہو جائیں اور اگر منہ پھیر لیں (اور نہ مانیں) تو وہ (تمھارے) مخالف ہیں اور ان کے مقابلے میں تمھیں خدا کافی ہے۔ اور وہ سننے والا (اور) جاننے والا ہے', NULL, NULL, '6ab7926412d3aed14900f999d761f09cc14ef07f03cc4575b3cd3230a6ba7e6d'),
  ('ur.jalandhry', 2, 138, 145, '(کہہ دو کہ ہم نے) خدا کا رنگ (اختیار کر لیا ہے) اور خدا سے بہتر رنگ کس کا ہو سکتا ہے۔ اور ہم اسی کی عبادت کرنے والے ہیں', NULL, NULL, '01a00a49e54d77185ae7b33f79eea3fce46e4a20c60835e4d951f8de4c826ac1'),
  ('ur.jalandhry', 2, 139, 146, '(ان سے) کہو، کیا تم خدا کے بارے میں ہم سے جھگڑتے ہو، حالانکہ وہی ہمارا اور تمھارا پروردگار ہے اور ہم کو ہمارے اعمال (کا بدلہ ملے گا) اور تم کو تمھارے اعمال (کا) اور ہم خاص اسی کی عبادت کرنے والے ہیں', NULL, NULL, '1ea1b99fece8d593e1a5b419e4b8f2b67c5c104d6789cda278f669f819d25a02'),
  ('ur.jalandhry', 2, 140, 147, '(اے یہود ونصاریٰ) کیا تم اس بات کے قائل ہو کہ ابراہیم اور اسمٰعیل اور اسحاق اور یعقوب اور ان کی اولاد یہودی یا عیسائی تھے۔ (اے محمدﷺ ان سے) کہو کہ بھلا تم زیادہ جانتے ہو یا خدا؟ اور اس سے بڑھ کر ظالم کون، جو خدا کی شہادت کو، جو اس کے پاس (کتاب میں موجود) ہے چھپائے۔ اور جو کچھ تم کر رہے ہو، خدا اس سے غافل نہیں', NULL, NULL, '349ceceb94816209bbb391a6f779079f1a10a36076539ea3b3802b4fcf2ccd8e'),
  ('ur.jalandhry', 2, 141, 148, 'یہ جماعت گزر چکی۔ ان کو وہ (ملے گا) جو انہوں نے کیا، اور تم کو وہ جو تم نے کیا۔ اور جو عمل وہ کرتے تھے، اس کی پرسش تم سے نہیں ہوگی', NULL, NULL, '0e5d41b15445bdb03f697941d4e245768d9cba1e132367f9bd6cb267a6440727'),
  ('ur.jalandhry', 2, 142, 149, 'احمق لوگ کہیں گے کہ مسلمان جس قبلے پر (پہلے سے چلے آتے) تھے (اب) اس سے کیوں منہ پھیر بیٹھے۔ تم کہہ دو کہ مشرق اور مغرب سب خدا ہی کا ہے۔ وہ جس کو چاہتا ہے، سیدھے رستے پر چلاتا ہے', NULL, NULL, '0687bb781021cdda7251e5d233de6906348da60acadf8956bfbe78b47f5d6bdd'),
  ('ur.jalandhry', 2, 143, 150, 'اور اسی طرح ہم نے تم کو امتِ معتدل بنایا ہے، تاکہ تم لوگوں پر گواہ بنو اور پیغمبر (آخرالزماں) تم پر گواہ بنیں۔ اور جس قبلے پر تم (پہلے) تھے، اس کو ہم نے اس لیے مقرر کیا تھا کہ معلوم کریں، کون (ہمارے) پیغمبر کا تابع رہتا ہے، اور کون الٹے پاؤں پھر جاتا ہے۔ اور یہ بات (یعنی تحویل قبلہ لوگوں کو) گراں معلوم ہوئی، مگر جن کو خدا نے ہدایت بخشی (وہ اسے گراں نہیں سمجھتے) اور خدا ایسا نہیں کہ تمہارے ایمان کو یونہی کھو دے۔ خدا تو لوگوں پر بڑا مہربان (اور) صاحبِ رحمت ہے', NULL, NULL, '5ef0c6c24f0b8b7d30253051dbbc8665e0a6e4605adddec9d943dd8413a55425'),
  ('ur.jalandhry', 2, 144, 151, '(اے محمدﷺ) ہم تمہارا آسمان کی طرف منہ پھیر پھیر کر دیکھنا دیکھ رہے ہیں۔ سو ہم تم کو اسی قبلے کی طرف جس کو تم پسند کرتے ہو، منہ کرنے کا حکم دیں گے تو اپنا منہ مسجد حرام (یعنی خانہٴ کعبہ) کی طرف پھیر لو۔ اور تم لوگ جہاں ہوا کرو، (نماز پڑھنے کے وقت) اسی مسجد کی طرف منہ کر لیا کرو۔ اور جن لوگوں کو کتاب دی گئی ہے، وہ خوب جانتے ہیں کہ (نیا قبلہ) ان کے پروردگار کی طرف سے حق ہے۔ اور جو کام یہ لوگ کرتے ہیں، خدا ان سے بے خبر نہیں', NULL, NULL, '50d0dc3b0455cd4dbe4ec7aef06059966bf919248a6f0e5b4653b19e1f7a6c22'),
  ('ur.jalandhry', 2, 145, 152, 'اور اگر تم ان اہلِ کتاب کے پاس تمام نشانیاں بھی لے کر آؤ، تو بھی یہ تمہارے قبلے کی پیروی نہ کریں۔ اور تم بھی ان کے قبلے کی پیروی کرنے والے نہیں ہو۔ اور ان میں سے بھی بعض بعض کے قبلے کے پیرو نہیں۔ اور اگر تم باوجود اس کے کہ تمہارے پاس دانش (یعنی وحئ خدا) آ چکی ہے، ان کی خواہشوں کے پیچھے چلو گے تو ظالموں میں (داخل) ہو جاؤ گے', NULL, NULL, '282b6b9a625d5a1f7c3af41cb6b1649d9aa770739aa426a4baf471cdfa1b1e9e'),
  ('ur.jalandhry', 2, 146, 153, 'جن لوگوں کو ہم نے کتاب دی ہے، وہ ان (پیغمبر آخرالزماں) کو اس طرح پہچانتے ہیں، جس طرح اپنے بیٹوں کو پہچانا کرتے ہیں، مگر ایک فریق ان میں سے سچی بات کو جان بوجھ کر چھپا رہا ہے', NULL, NULL, '27247e4de0abdaaba30cd69443048d398c92eb9f989829afc09f976bfd2b6d81'),
  ('ur.jalandhry', 2, 147, 154, '(اے پیغمبر، یہ نیا قبلہ) تمہارے پروردگار کی طرف سے حق ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا', NULL, NULL, '2e59da1d039fad72da9385bb3cd1a582aaaeec56c16a8769875e673c29f691be'),
  ('ur.jalandhry', 2, 148, 155, 'اور ہر ایک (فرقے) کے لیے ایک سمت (مقرر) ہے۔ جدھر وہ (عبادت کے وقت) منہ کیا کرتے ہیں۔ تو تم نیکیوں میں سبقت حاصل کرو۔ تم جہاں رہو گے خدا تم سب کو جمع کرلے گا۔ بے شک خدا ہر چیز پر قادر ہے', NULL, NULL, '360115b17d1191ec25287d463866564faf2c4f41f29cb895ddfd135f61a7daf0'),
  ('ur.jalandhry', 2, 149, 156, 'اور تم جہاں سے نکلو، (نماز میں) اپنا منہ مسجد محترم کی طرف کر لیا کرو بےشک وہ تمہارے پروردگار کی طرف سے حق ہے۔ اور تم لوگ جو کچھ کرتے ہو۔ خدا اس سے بے خبر نہیں', NULL, NULL, 'e8acdf6dd88cbc8514bc2725cc1f78997089ca694bf78a3f0aa408358fcf3512'),
  ('ur.jalandhry', 2, 150, 157, 'اور تم جہاں سے نکلو، مسجدِ محترم کی طرف منہ (کرکے نماز پڑھا) کرو۔ اور مسلمانو، تم جہاں ہوا کرو، اسی (مسجد) کی طرف رخ کیا کرو۔ (یہ تاکید) اس لیے (کی گئی ہے) کہ لوگ تم کو کسی طرح کا الزام نہ دے سکیں۔ مگر ان میں سے جو ظالم ہیں، (وہ الزام دیں تو دیں) سو ان سے مت ڈرنا اور مجھی سے ڈرتے رہنا۔ اور یہ بھی مقصود ہے کہ تم کو اپنی تمام نعمتیں بخشوں اور یہ بھی کہ تم راہِ راست پر چلو', NULL, NULL, '0ae78d456be8d4146587793875e952ec58eafaeac60ea984aeec6ed6fe880f59'),
  ('ur.jalandhry', 2, 151, 158, 'جس طرح (منجملہ اور نعمتوں کے) ہم نے تم میں تمھیں میں سے ایک رسول بھیجے ہیں جو تم کو ہماری آیتیں پڑھ پڑھ کر سناتے اور تمہیں پاک بناتے اور کتاب (یعنی قرآن) اور دانائی سکھاتے ہیں، اور ایسی باتیں بتاتے ہیں، جو تم پہلے نہیں جانتے تھے', NULL, NULL, '13bf44521df5b9538b0ce92543ad302ee90da45ddb8a4827b024457c14aa49ad'),
  ('ur.jalandhry', 2, 152, 159, 'سو تم مجھے یاد کرو۔ میں تمہیں یاد کیا کروں گا۔ اور میرے احسان مانتے رہنا اور ناشکری نہ کرنا', NULL, NULL, 'becee8119dbb87215285a3bf1b9478120224ed2d9d2383e61e74f77e4a221995'),
  ('ur.jalandhry', 2, 153, 160, 'اے ایمان والو صبر اور نماز سے مدد لیا کرو بےشک خدا صبر کرنے والوں کے ساتھ ہے', NULL, NULL, 'b0717b38a21d4ce443a0f06bdf2affa7d8f5c9e84f194af95a37e65e8fd72385'),
  ('ur.jalandhry', 2, 154, 161, 'اور جو لوگ خدا کی راہ میں مارے جائیں ان کی نسبت یہ کہنا کہ وہ مرے ہوئے ہیں (وہ مردہ نہیں) بلکہ زندہ ہیں لیکن تم نہیں جانتے', NULL, NULL, 'd0a5440d1a25974a0272b9ba64252f8775f00ffda33d55323a09cd913770cf3d'),
  ('ur.jalandhry', 2, 155, 162, 'اور ہم کسی قدر خوف اور بھوک اور مال اور جانوں اور میوؤں کے نقصان سے تمہاری آزمائش کریں گے توصبر کرنے والوں کو (خدا کی خوشنودی کی) بشارت سنا دو', NULL, NULL, 'd92f7b856cd1a1b11cec51bbdd4f986158f7d649e40edb87f019b60f13319507'),
  ('ur.jalandhry', 2, 156, 163, 'ان لوگوں پر جب کوئی مصیبت واقع ہوتی ہے تو کہتے ہیں کہ ہم خدا ہی کا مال ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں', NULL, NULL, '8223ad2dfd29da01b9dbd6d024eb69b3253132fa3f75d2d47e23634e32dc9a12'),
  ('ur.jalandhry', 2, 157, 164, 'یہی لوگ ہیں جن پر ان کے پروردگار کی مہربانی اور رحمت ہے۔ اور یہی سیدھے رستے پر ہیں', NULL, NULL, '50494c9e94ccbc6aa59c3e9d5714164cad46bc7dfb39323119a0df2e36bb7249'),
  ('ur.jalandhry', 2, 158, 165, 'بےشک (کوہ) صفا اور مروہ خدا کی نشانیوں میں سے ہیں۔ تو جو شخص خانہٴ کعبہ کا حج یا عمرہ کرے اس پر کچھ گناہ نہیں کہ دونوں کا طواف کرے۔ (بلکہ طواف ایک قسم کا نیک کام ہے) اور جو کوئی نیک کام کرے تو خدا قدر شناس اور دانا ہے', NULL, NULL, 'a3d6cb604a1c48e49c058ee5d320ea8499d452d30fff8206cc2bfcea79312caa'),
  ('ur.jalandhry', 2, 159, 166, 'جو لوگ ہمارے حکموں اور ہدایتوں کو جو ہم نے نازل کی ہیں (کسی غرض فاسد سے) چھپاتے ہیں باوجود یہ کہ ہم نے ان لوگوں کے (سمجھانے کے) لئے اپنی کتاب میں کھول کھول کر بیان کردیا ہے۔ ایسوں پر خدا اور تمام لعنت کرنے والے لعنت کرتے ہیں', NULL, NULL, '7b38fbf8720ca7979403cf5c820aad0a9113e0c9f44208ce2f14dc36cdefb46c'),
  ('ur.jalandhry', 2, 160, 167, 'ہاں جو توبہ کرتے ہیں اور اپنی حالت درست کرلیتے اور (احکام الہیٰ کو) صاف صاف بیان کردیتے ہیں تو میں ان کے قصور معاف کردیتا ہوں اور میں بڑا معاف کرنے والا (اور) رحم والا ہوں', NULL, NULL, '0389665b5e69ef08145e60a60ffc41b958d30ce9a9134f0d3d2ebb39b3b81c69'),
  ('ur.jalandhry', 2, 161, 168, 'جو لوگ کافر ہوئے اور کافر ہی مرے ایسوں پر خدا کی اور فرشتوں اور لوگوں کی سب کی لعنت', NULL, NULL, '406a3f6b311281d3fcb6dcad833b8e96316b31a2f96f73841af03352b7f2eca6'),
  ('ur.jalandhry', 2, 162, 169, 'وہ ہمیشہ اسی (لعنت) میں (گرفتار) رہیں گے۔ ان سے نہ تو عذاب ہی ہلکا کیا جائے گا اور نہ انہیں (کچھ) مہلت ملے گی', NULL, NULL, '698301b1842286c70d883ffec13dd07e79862a023f1a1b31dadd5716e6f53027'),
  ('ur.jalandhry', 2, 163, 170, 'اور (لوگو) تمہارا معبود خدائے واحد ہے اس بڑے مہربان (اور) رحم کرنے کے سوا کوئی عبادت کے لائق نہیں', NULL, NULL, 'cb60243b3772fc44e8ecd9ebe53502def6b482eb30678713fba81980a00e2095'),
  ('ur.jalandhry', 2, 164, 171, 'بےشک آسمانوں اور زمین کے پیدا کرنے میں اور رات اور دن کے ایک دوسرے کے پیچھے آنے جانے میں اور کشتیوں اور جہازوں میں جو دریا میں لوگوں کے فائدے کی چیزیں لے کر رواں ہیں اور مینہ میں جس کو خدا آسمان سے برساتا اور اس سے زمین کو مرنے کے بعد زندہ (یعنی خشک ہوئے پیچھے سرسبز) کردیتا ہے اور زمین پر ہر قسم کے جانور پھیلانے میں اور ہواؤں کے چلانےمیں اور بادلوں میں جو آسمان اور زمین کے درمیان گھرے رہتے ہیں۔ عقلمندوں کے لئے (خدا کی قدرت کی) نشانیاں ہیں', NULL, NULL, 'e90da48f3fe9a2421d25fa8d75d6a4b3cb9b10408ec3b50ccfbc427caef5b28e'),
  ('ur.jalandhry', 2, 165, 172, 'اور بعض لوگ ایسے ہیں جو غیر خدا کو شریک (خدا) بناتے اور ان سے خدا کی سی محبت کرتے ہیں۔ لیکن جو ایمان والے ہیں وہ تو خدا ہی کے سب سے زیادہ دوستدار ہیں۔ اور اے کاش ظالم لوگ جو بات عذاب کے وقت دیکھیں گے اب دیکھ لیتے کہ سب طرح کی طاقت خدا ہی کو ہے۔ اور یہ کہ خدا سخت عذاب کرنے والا ہے', NULL, NULL, '1345616c3f2d900756cc6282acf766ab4dde94a6847922e6fbb3aed8307376a1'),
  ('ur.jalandhry', 2, 166, 173, 'اس دن (کفر کے) پیشوا اپنے پیرووں سے بیزاری ظاہر کریں گے اور (دونوں) عذاب (الہیٰ) دیکھ لیں گے اور ان کے آپس کے تعلقات منقطع ہوجائیں گے', NULL, NULL, 'a0e7588f42c866db8e95844b7683e1ae2531f0efa8ecdeb627c9b82aa748f109'),
  ('ur.jalandhry', 2, 167, 174, '(یہ حال دیکھ کر) پیروی کرنے والے (حسرت سے) کہیں گے کہ اے کاش ہمیں پھر دنیا میں جانا نصیب ہو تاکہ جس طرح یہ ہم سے بیزار ہو رہے ہیں اسی طرح ہم بھی ان سے بیزار ہوں۔ اسی طرح خدا ان کے اعمال انہیں حسرت بنا کر دکھائے گااور وہ دوزخ سے نکل نہیں سکیں گے', NULL, NULL, '5f4a9f9d3705a4ec7d80191964bba12116dbba29896a57cd49828981330cbaeb'),
  ('ur.jalandhry', 2, 168, 175, 'لوگو جو چیزیں زمین میں حلال طیب ہیں وہ کھاؤ۔ اور شیطان کے قدموں پر نہ چلو۔ وہ تمہارا کھلا دشمن ہے', NULL, NULL, '64eb5c57e41e659eeeeba9e21d5e091cf896b63be887cdb35c969a47d4985abc'),
  ('ur.jalandhry', 2, 169, 176, 'وہ تو تم کو برائی اور بےحیائی ہی کے کام کرنے کو کہتا ہے اور یہ بھی کہ خدا کی نسبت ایسی باتیں کہو جن کا تمہیں (کچھ بھی) علم نہیں', NULL, NULL, 'dcf7023652f0d6e6f3a639e224a9ba6b9f502fa1b2588125b8c23ad08ce77558'),
  ('ur.jalandhry', 2, 170, 177, 'اور جب ان لوگوں سے کہا جاتا ہے کہ جو (کتاب) خدا نے نازل فرمائی ہے اس کی پیروی کرو تو کہتے ہیں (نہیں) بلکہ ہم تو اسی چیز کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کو پایا۔ بھلا اگرچہ ان کے باپ دادا نہ کچھ سمجھتے ہوں اورنہ سیدھے رستے پر ہوں (تب بھی وہ انہیں کی تقلید کئے جائیں گے)', NULL, NULL, 'f76ee2e3a7f7fd11d10e9447efee81cc3f8df43301f754f00795f8d0626f5f8e'),
  ('ur.jalandhry', 2, 171, 178, 'جو لوگ کافر ہیں ان کی مثال اس شخص کی سی ہے جو کسی ایسی چیز کو آواز دے جو پکار اور آواز کے سوا کچھ سن نہ سکے۔ (یہ) بہرے ہیں گونگے ہیں اندھے ہیں کہ (کچھ) سمجھ ہی نہیں سکتے', NULL, NULL, '31eb84b2cf148cf6a6f6cfd139e24d83dd7e15c8c3e20b7d442a2b9cb9732ebf'),
  ('ur.jalandhry', 2, 172, 179, 'اے اہل ایمان جو پاکیزہ چیزیں ہم نے تم کو عطا فرمائیں ہیں ان کو کھاؤ اور اگر خدا ہی کے بندے ہو تو اس (کی نعمتوں) کا شکر بھی ادا کرو', NULL, NULL, '6ea2fcc453441d6c442f4a54bda05d5e76b41c6ebc7a2fbbb4961127542b8125'),
  ('ur.jalandhry', 2, 173, 180, 'اس نے تم پر مرا ہوا جانور اور لہو اور سور کا گوشت اور جس چیز پر خدا کے سوا کسی اور کا نام پکارا جائے حرام کردیا ہے ہاں جو ناچار ہوجائے (بشرطیکہ) خدا کی نافرمانی نہ کرے اور حد (ضرورت) سے باہر نہ نکل جائے اس پر کچھ گناہ نہیں۔ بےشک خدا بخشنے والا (اور) رحم کرنے والا ہے', NULL, NULL, '9e9194e34d35dd6ee174eb72e71d3b9a175f3a34a6896a4a87d25c4b62733eab'),
  ('ur.jalandhry', 2, 174, 181, 'جو لوگ (خدا) کی کتاب سے ان (آیتوں اور ہدایتوں) کو جو اس نے نازل فرمائی ہیں چھپاتے اور ان کے بدلے تھوڑی سی قیمت (یعنی دنیاوی منفعت) حاصل کرتے ہیں وہ اپنے پیٹوں میں محض آگ بھرتے ہیں۔ ایسے لوگوں سے خدا قیامت کے دن نہ کلام کرے گا اور نہ ان کو (گناہوں سے) پاک کرے گا۔اور ان کے لئے دکھ دینے والا عذاب ہے', NULL, NULL, 'b2f7ecc07da445b19acae12f2ffab50ef8c444ef44b5d6893ba99a3b25bb1b34'),
  ('ur.jalandhry', 2, 175, 182, 'یہ وہ لوگ ہیں جنہوں نے ہدایت چھوڑ کر گمراہی اور بخشش چھوڑ کر عذاب خریدا۔ یہ (آتش) جہنم کی کیسی برداشت کرنے والے ہیں!', NULL, NULL, 'ea7210851322ce592adf35e3b229a1e03a33075864d11f52bb68f719e50cd488'),
  ('ur.jalandhry', 2, 176, 183, 'یہ اس لئے کہ خدا نے کتاب سچائی کے ساتھ نازل فرمائی۔ اور جن لوگوں نے اس کتاب میں اختلاف کیا وہ ضد میں (آکر نیکی سے) دور (ہوگئے) ہیں', NULL, NULL, '28b00775a865ad80ebd5e872100c99dd27c7cba788a545d1655893416128694a'),
  ('ur.jalandhry', 2, 177, 184, 'نیکی یہی نہیں کہ تم مشرق یا مغرب کو (قبلہ سمجھ کر ان) کی طرف منہ کرلو بلکہ نیکی یہ ہے کہ لوگ خدا پر اور روز آخرت پر اور فرشتوں پر اور (خدا کی) کتاب پر اور پیغمبروں پر ایمان لائیں۔ اور مال باوجود عزیز رکھنے کے رشتہ داروں اور یتیموں اور محتاجوں اور مسافروں اور مانگنے والوں کو دیں اور گردنوں (کے چھڑانے) میں (خرچ کریں) اور نماز پڑھیں اور زکوٰة دیں۔ اور جب عہد کرلیں تو اس کو پورا کریں۔ اور سختی اور تکلیف میں اور (معرکہ) کارزار کے وقت ثابت قدم رہیں۔ یہی لوگ ہیں جو (ایمان میں) سچے ہیں اور یہی ہیں جو (خدا سے) ڈرنے والے ہیں', NULL, NULL, '71b80ee88d6096b09fec0db1a1c211c26fde02e3688e49a7e000596418c38f36'),
  ('ur.jalandhry', 2, 178, 185, 'مومنو! تم کو مقتولوں کے بارےمیں قصاص (یعنی خون کے بدلے خون) کا حکم دیا جاتا ہے (اس طرح پر کہ) آزاد کے بدلے آزاد (مارا جائے) اور غلام کے بدلے غلام اور عورت کے بدلے عورت اور قاتل کو اس کے (مقتول) بھائی (کے قصاص میں) سے کچھ معاف کردیا جائے تو (وارث مقتول) کو پسندیدہ طریق سے (قرار داد کی) پیروی (یعنی مطالبہٴ خون بہا) کرنا اور (قاتل کو) خوش خوئی کے ساتھ ادا کرنا چاہیئے یہ پروردگار کی طرف سے تمہارے لئے آسانی اور مہربانی ہے جو اس کے بعد زیادتی کرے اس کے لئے دکھ کا عذاب ہے', NULL, NULL, 'c054768da875265babd278fc821b2c21e8dbd43c85b36b20b63e87df6afa3f40'),
  ('ur.jalandhry', 2, 179, 186, 'اور اے اہل عقل (حکم) قصاص میں (تمہاری) زندگانی ہے کہ تم (قتل و خونریزی سے) بچو', NULL, NULL, '643073c665b229891e4e044c88a20b83bf6f1ed791e113f88db59e3aff7a74bd'),
  ('ur.jalandhry', 2, 180, 187, 'تم پر فرض کیا جاتا ہے کہ جب تم میں سے کسی کو موت کا وقت آجائے تو اگر وہ کچھ مال چھوڑ جانے والا ہو تو ماں با پ اور رشتہ داروں کے لئے دستور کے مطابق وصیت کرجائے (خدا سے) ڈر نے والوں پر یہ ایک حق ہے', NULL, NULL, 'bf72b73c847efd541630b4175aaa4f375f72601f3b07c9393844da97bc2eaddf'),
  ('ur.jalandhry', 2, 181, 188, 'جو شخص وصیت کو سننے کے بعد بدل ڈالے تو اس (کے بدلنے) کا گناہ انہیں لوگوں پر ہے جو اس کو بدلیں۔ اور بےشک خدا سنتا جانتا ہے', NULL, NULL, '38dfed1783a8e7c2fed02001178a388cd194ea77383e237f479e4506a61aa5c6'),
  ('ur.jalandhry', 2, 182, 189, 'اگر کسی کو وصیت کرنے والے کی طرف سے (کسی وارث کی) طرفداری یا حق تلفی کا اندیشہ ہو تو اگر وہ (وصیت کو بدل کر) وارثوں میں صلح کرادے تو اس پر کچھ گناہ نہیں۔ بےشک خدا بخشنے والا (اور) رحم والا ہے', NULL, NULL, 'fd0b06de3e28f01b149cd7894f6a03130adf490db8d4b3277837c942ee199a2f'),
  ('ur.jalandhry', 2, 183, 190, 'مومنو! تم پر روزے فرض کئے گئے ہیں۔ جس طرح تم سے پہلے لوگوں پر فرض کئے گئے تھے تاکہ تم پرہیزگار بنو', NULL, NULL, 'ce2b9abb82111bdefce4e3698327dc1063102349aff91ce6116791629c41f9af'),
  ('ur.jalandhry', 2, 184, 191, '(روزوں کے دن) گنتی کے چند روز ہیں تو جو شخص تم میں سے بیمار ہو یا سفر میں ہو تو دوسرے دنوں میں روزوں کا شمار پورا کرلے اور جو لوگ روزہ رکھنے کی طاقت رکھیں (لیکن رکھیں نہیں) وہ روزے کے بدلے محتاج کو کھانا کھلا دیں اور جو کوئی شوق سے نیکی کرے تو اس کے حق میں زیادہ اچھا ہے۔ اور اگر سمجھو تو روزہ رکھنا ہی تمہارے حق میں بہتر ہے', NULL, NULL, 'b3962c8ef9873483dae4ae3fd84d3317ddcbac1c974f877b09318fa73adf2c05'),
  ('ur.jalandhry', 2, 185, 192, '(روزوں کا مہینہ) رمضان کا مہینہ (ہے) جس میں قرآن (اول اول) نازل ہوا جو لوگوں کا رہنما ہے اور (جس میں) ہدایت کی کھلی نشانیاں ہیں اور (جو حق و باطل کو) الگ الگ کرنے والا ہے تو جو کوئی تم میں سے اس مہینے میں موجود ہو چاہیئے کہ پورے مہینے کے روزے رکھے اور جو بیمار ہو یا سفر میں ہو تو دوسرے دنوں میں (رکھ کر) ان کا شمار پورا کرلے۔ خدا تمہارے حق میں آسانی چاہتا ہے اور سختی نہیں چاہتا اور (یہ آسانی کا حکم) اس لئے (دیا گیا ہے) کہ تم روزوں کا شمار پورا کرلو اور اس احسان کے بدلے کہ خدا نے تم کو ہدایت بخشی ہے تم اس کو بزرگی سے یاد کر واور اس کا شکر کرو', NULL, NULL, 'a6d1be21b0f4657c19e6f7e9baf8a8e41c49fb025d51638b5866dc319d42c56a'),
  ('ur.jalandhry', 2, 186, 193, 'اور (اے پیغمبر) جب تم سے میرے بندے میرے بارے میں دریافت کریں تو (کہہ دو کہ) میں تو (تمہارے) پاس ہوں جب کوئی پکارنے والا مجھے پکارتا ہے تو میں اس کی دعا قبول کرتا ہوں تو ان کو چاہیئے کہ میرے حکموں کو مانیں اور مجھ پر ایمان لائیں تاکہ نیک رستہ پائیں', NULL, NULL, '9a4459fc791d86b2f4a01051c0bd197baf62a247c95bbd058f4ee0ba183c32f8'),
  ('ur.jalandhry', 2, 187, 194, 'روزوں کی راتوں میں تمہارے لئے اپنی عورتوں کے پاس جانا کردیا گیا ہے وہ تمہاری پوشاک ہیں اور تم ان کی پوشاک ہو خدا کو معلوم ہے کہ تم (ان کے پاس جانے سے) اپنے حق میں خیانت کرتے تھے سو اس نے تم پر مہربانی کی اور تمہاری حرکات سےدرگزرفرمائی۔اب (تم کو اختیار ہے کہ) ان سے مباشرت کرو۔ اور خدا نے جو چیز تمہارے لئے لکھ رکھی ہے (یعنی اولاد) اس کو (خدا سے) طلب کرو اور کھاؤ پیو یہاں تک کہ صبح کی سفید دھاری (رات کی) سیاہ دھاری سے الگ نظر آنے لگے۔ پھر روزہ (رکھ کر) رات تک پورا کرو اور جب تم مسجدوں میں اعتکاف بیٹھے ہو تو ان سے مباشرت نہ کرو۔ یہ خدا کی حدیں ہیں ان کے پاس نہ جانا۔ اسی طرح خدا اپنی آیتیں لوگوں کے (سمجھانے کے) لئے کھول کھول کر بیان فرماتا ہے تاکہ وہ پرہیزگار بنیں', NULL, NULL, 'b8ef0c6bca3c0ff14186da9c4a6ecd6b53869e3f6f5eb34a9396c27d521bc36e'),
  ('ur.jalandhry', 2, 188, 195, 'اور ایک دوسرے کا مال ناحق نہ کھاؤ اورنہ اس کو (رشوةً) حاکموں کے پاس پہنچاؤ تاکہ لوگوں کے مال کا کچھ حصہ ناجائز طور پر کھا جاؤ اور (اسے) تم جانتے بھی ہو', NULL, NULL, 'ec20b40004da95a23df8cf364b244a95226f5442ed7a6abcf5433d4e2ca90f31'),
  ('ur.jalandhry', 2, 189, 196, '(اے محمدﷺ) لوگ تم سے نئے چاند کے بارے میں دریافت کرتے ہیں (کہ گھٹتا بڑھتا کیوں ہے) کہہ دو کہ وہ لوگوں کے (کاموں کی میعادیں) اور حج کے وقت معلوم ہونے کا ذریعہ ہے اور نیکی اس بات میں نہیں کہ (احرام کی حالت میں) گھروں میں ان کے پچھواڑے کی طرف سے آؤ۔ بلکہ نیکوکار وہ ہے جو پرہیز گار ہو اور گھروں میں ان کے دروازوں سے آیا کرو اور خدا سے ڈرتے رہو تاکہ نجات پاؤ', NULL, NULL, 'd8de5213ec0d9b47e7c6e5c1026b40f5547f3a894058564277bbf06df53d7faa'),
  ('ur.jalandhry', 2, 190, 197, 'اور جو لوگ تم سے لڑتے ہیں تم بھی خدا کی راہ میں ان سے لڑو مگر زیادتی نہ کرنا کہ خدا زیادتی کرنے والوں کو دوست نہیں رکھتا', NULL, NULL, 'c459542a2d7c35a0d3db64e8c6869eaca95a454ea8b6f8b126572af6da163161'),
  ('ur.jalandhry', 2, 191, 198, 'اور ان کو جہاں پاؤ قتل کردو اور جہاں سے انہوں نے تم کو نکالا ہے (یعنی مکے سے) وہاں سے تم بھی ان کو نکال دو۔ اور (دین سے گمراہ کرنے کا) فساد قتل وخونریزی سے کہیں بڑھ کر ہے اور جب تک وہ تم سے مسجد محترم (یعنی خانہ کعبہ) کے پاس نہ لڑیں تم بھی وہاں ان سے نہ لڑنا۔ ہاں اگر وہ تم سے لڑیں تو تم ان کو قتل کرڈالو۔ کافروں کی یہی سزا ہے', NULL, NULL, 'db08799ff5d2ae34fb7c570316725c09f87bd77162bbd7fdf651c623bb55a5bf'),
  ('ur.jalandhry', 2, 192, 199, 'اور اگر وہ باز آجائیں تو خدا بخشنے والا (اور) رحم کرنے والا ہے', NULL, NULL, 'bb29d6bd8374f99d48ea443ba29ed0cf77f6a31be0bb6be3ec9f7446f80bb355'),
  ('ur.jalandhry', 2, 193, 200, 'اور ان سے اس وقت تک لڑتے رہنا کہ فساد نابود ہوجائے اور (ملک میں) خدا ہی کا دین ہوجائے اور اگر وہ (فساد سے) باز آجائیں تو ظالموں کے سوا کسی پر زیادتی نہیں (کرنی چاہیئے)', NULL, NULL, '436ea2d9fb15db1933c4877f03f5682951022438cb1f579f0e538e49a3ac983f')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 2, 194, 201, 'ادب کا مہینہ ادب کے مہینے کے مقابل ہے اور ادب کی چیزیں ایک دوسرے کا بدلہ ہیں۔ پس اگر کوئی تم پر زیادتی کرے تو جیسی زیادتی وہ تم پر کرے ویسی ہی تم اس پر کرو۔ اور خدا سے ڈرتے رہو اور جان رکھو کہ خدا ڈرنے والوں کے ساتھ ہے', NULL, NULL, '2934aa1e099c2d9281fd879dacd1219192c2a5cad35c0bf82a1dbf7cd9db7212'),
  ('ur.jalandhry', 2, 195, 202, 'اور خدا کی راہ میں (مال) خرچ کرو اور اپنے آپ کو ہلاکت میں نہ ڈالو اور نیکی کرو بےشک خدا نیکی کرنے والوں کو دوست رکھتا ہے', NULL, NULL, 'c4c6022fba10a0c1f1b471ec56a397fe3898d66294fdb6ed8a395f456bfe974b'),
  ('ur.jalandhry', 2, 196, 203, 'اور خدا (کی خوشنودی) کے لئے حج اور عمرے کو پورا کرو۔ اور اگر (راستےمیں) روک لئے جاؤ تو جیسی قربانی میسر ہو (کردو) اور جب تک قربانی اپنے مقام پر نہ پہنچ جائے سر نہ منڈاؤ۔ اور اگر کوئی تم میں بیمار ہو یا اس کے سر میں کسی طرح کی تکلیف ہو تو (اگر وہ سر منڈالے تو) اس کے بدلے روزے رکھے یا صدقہ دے یا قربانی کرے پھر جب (تکلیف دور ہو کر) تم مطمئن ہوجاؤ تو جو (تم میں) حج کے وقت تک عمرے سے فائدہ اٹھانا چاہے وہ جیسی قربانی میسر ہو کرے۔ اور جس کو (قربانی) نہ ملے وہ تین روزے ایام حج میں رکھے اور سات جب واپس ہو۔ یہ پورے دس ہوئے۔ یہ حکم اس شخص کے لئے ہے جس کے اہل وعیال مکے میں نہ رہتے ہوں اور خدا سے ڈرتے رہو اور جان رکھو کہ خدا سخت عذاب دینے والا ہے', NULL, NULL, '63c3ad4da509d25ebc75ff05fdb6a295e2d47fd2f0e5f709eb24ded7d224e732'),
  ('ur.jalandhry', 2, 197, 204, 'حج کے مہینے (معین ہیں جو) معلوم ہیں تو شخص ان مہینوں میں حج کی نیت کرلے تو حج (کے دنوں) میں نہ عورتوں سے اختلاط کرے نہ کوئی برا کام کرے نہ کسی سے جھگڑے۔ اور جو نیک کام تم کرو گے وہ خدا کو معلوم ہوجائے گا اور زاد راہ (یعنی رستے کا خرچ) ساتھ لے جاؤ کیونکہ بہتر (فائدہ) زاد راہ (کا) پرہیزگاری ہے اور اے اہل عقل مجھ سے ڈرتے رہو', NULL, NULL, '9fd42b2220504b0e4ded245ff3839adb885e2f7c55ebbf41a08823b1a89ab77d'),
  ('ur.jalandhry', 2, 198, 205, 'اس کا تمہیں کچھ گناہ نہیں کہ (حج کے دنوں میں بذریعہ تجارت) اپنے پروردگار سے روزی طلب کرو اور جب عرفات سے واپس ہونے لگو تو مشعر حرام (یعنی مزدلفے) میں خدا کا ذکر کرو اور اس طرح ذکر کرو جس طرح اس نے تم کو سکھایا۔ اور اس سے پیشتر تم لوگ (ان طریقوں سے) محض ناواقف تھے', NULL, NULL, '54c142b027011a36a90c98e717801ef4d8d882f0528aaee8c9a5bdc453cb7b6e'),
  ('ur.jalandhry', 2, 199, 206, 'پھر جہاں سے اور لوگ واپس ہوں وہیں سے تم بھی واپس ہو اور خدا سے بخشش مانگو۔ بےشک خدا بخشنے والا اور رحمت کرنے والا ہے', NULL, NULL, 'ace1b20f5f91fe7b3304276eb00d14413b59e9e4ce8c5f043bade1722a50b9cf'),
  ('ur.jalandhry', 2, 200, 207, 'پھر جب حج کے تمام ارکان پورے کرچکو تو (منیٰ میں) خدا کو یاد کرو۔ جس طرح اپنے باپ دادا کو یاد کیا کرتے تھے بلکہ اس سے بھی زیادہ اور بعض لوگ ایسے ہیں جو (خدا سے) التجا کرتے ہیں کہ اے پروردگار ہم کو (جو دنیا ہے) دنیا ہی میں عنایت کر ایسے لوگوں کا آخرت میں کچھ حصہ نہیں', NULL, NULL, '05d9931cdd36a785935767fe7e861eb603f294d99a473af1ad3cb2630adc05f7'),
  ('ur.jalandhry', 2, 201, 208, 'اور بعضے ایسے ہیں کہ دعا کرتے ہیں کہ پروردگار ہم کو دنیا میں بھی نعمت عطا فرما اور آخرت میں بھی نعمت بخشیو اور دوزخ کے عذاب سے محفوظ رکھیو', NULL, NULL, '39c6b6e9be1f360d4fcd3d4d009074dfaedcc8413e868e678c1595d82e11cf3a'),
  ('ur.jalandhry', 2, 202, 209, 'یہی لوگ ہیں جن کے لئے ان کے کاموں کا حصہ (یعنی اجر نیک تیار) ہے اور خدا جلد حساب لینے والا (اور جلد اجر دینے والا) ہے', NULL, NULL, 'dd7fb0b24645eb1eeadbd11454430b07f16540ee7f4fb6dd79add4215af92b23'),
  ('ur.jalandhry', 2, 203, 210, 'اور (قیام منیٰ کے) دنوں میں (جو) گنتی کے (دن میں) خدا کو یاد کرو۔ اگر کوئی جلدی کرے (اور) دو ہی دن میں (چل دے) تو اس پر بھی کچھ گناہ نہیں۔ اور جو بعد تک ٹھہرا رہے اس پر بھی کچھ گناہ نہیں۔ یہ باتیں اس شخص کے لئے ہیں جو (خدا سے) ڈرے اور تم لوگ خدا سے ڈرتے رہو اور جان رکھو کہ تم سب اس کے پاس جمع کئے جاؤ گے۔', NULL, NULL, '6c4847f2df77dedb2d21baccb675036613fada5dbe66e8d27845e1a524558d0c'),
  ('ur.jalandhry', 2, 204, 211, 'اور کوئی شخص تو ایسا ہے جس کی گفتگو دنیا کی زندگی میں تم کو دلکش معلوم ہوتی ہے اور وہ اپنی مانی الضمیر پر خدا کو گواہ بناتا ہے حالانکہ وہ سخت جھگڑالو ہے', NULL, NULL, 'e85ec4dbb24832332bfead72fbbacbfb12b5868fecee654d727f477d0fd28df6'),
  ('ur.jalandhry', 2, 205, 212, 'اور جب پیٹھ پھیر کر چلا جاتا ہے تو زمین میں دوڑتا پھرتا ہے تاکہ اس میں فتنہ انگیزی کرے اور کھیتی کو (برباد) اور (انسانوں اور حیوانوں کی) نسل کو نابود کردے اور خدا فتنہ انگیزی کو پسند نہیں کرتا', NULL, NULL, '09e77f26b53746fbecb16aa6fe1e4bb03446788dcf2587e398ccfa0cc3e67921'),
  ('ur.jalandhry', 2, 206, 213, 'اور جب اس سے کہا جاتا ہے کہ خدا سے خوف کر تو غرور اس کو گناہ میں پھنسا دیتا ہے۔ سو ایسے کو جہنم سزاوار ہے۔ اور وہ بہت برا ٹھکانہ ہے', NULL, NULL, '33673ff5991c0e9f07c00148ef5feb089c2904cea44b2cedcb57d87a01d45f00'),
  ('ur.jalandhry', 2, 207, 214, 'اور کوئی شخص ایسا ہے کہ خدا کی خوشنودی حاصل کرنے کے لئے اپنی جان بیچ ڈالتا ہے اور خدا بندوں پر بہت مہربان ہے', NULL, NULL, 'e60745b173a2ce390892aed1943253072e4f2c4e5df1f5ae9b22d3980ae141e8'),
  ('ur.jalandhry', 2, 208, 215, 'مومنو! اسلام میں پورے پورے داخل ہوجاؤ اور شیطان کے پیچھے نہ چلو وہ تو تمہارا صریح دشمن ہے', NULL, NULL, 'b6feb5246497774d787a4206eb5a65bb61ee1d0a200f67ca2a7a6e77074e7691'),
  ('ur.jalandhry', 2, 209, 216, 'پھر اگر تم احکام روشن پہنچ جانے کے بعد لڑکھڑاجاؤ تو جان جاؤ کہ خدا غالب (اور) حکمت والا ہے', NULL, NULL, '432fb7208c8e0cbb044bc42f8960457a9d031713a540e7f09d6753ece7188839'),
  ('ur.jalandhry', 2, 210, 217, 'کیا یہ لوگ اسی بات کے منتظر ہیں کہ ان پر خدا (کاعذاب) بادل کے سائبانوں میں آنازل ہو اور فرشتے بھی (اتر آئیں) اور کام تمام کردیا جائے اور سب کاموں کا رجوع خدا ہی کی طرف ہے', NULL, NULL, '5eca6a7cf18232b42326359a96498a2bb1b3904340d5a489d101d553a7f130b5'),
  ('ur.jalandhry', 2, 211, 218, '(اے محمد) بنی اسرائیل سے پوچھو کہ ہم نے ان کو کتنی کھلی نشانیاں دیں۔ اور جو شخص خدا کی نعمت کو اپنے پاس آنے کے بعد بدل دے تو خدا سخت عذاب کرنے والا ہے', NULL, NULL, '247b9662f226f4071f9c960701f82b47983daa91b8edb2c5f0ce39d6aae36ada'),
  ('ur.jalandhry', 2, 212, 219, 'اور جو کافر ہیں ان کے لئے دنیا کی زندگی خوشنما کر دی گئی ہے اور وہ مومنوں سے تمسخر کرتے ہیں لیکن جو پرہیز گار ہیں وہ قیامت کے دن ان پر غالب ہوں گے اور خدا جس کو چاہتا ہے بےشمار رزق دیتا ہے', NULL, NULL, '3af6678ad05550a401db6c4184787827dd4b8cd14a8f7e33da13ee91cb1bbabf'),
  ('ur.jalandhry', 2, 213, 220, '(پہلے تو سب) لوگوں کا ایک ہی مذہب تھا (لیکن وہ آپس میں اختلاف کرنے لگے) تو خدا نے (ان کی طرف) بشارت دینے والے اور ڈر سنانے والے پیغمبر بھیجے اور ان پر سچائی کے ساتھ کتابیں نازل کیں تاکہ جن امور میں لوگ اختلاف کرتے تھے ان کا ان میں فیصلہ کردے۔ اور اس میں اختلاف بھی انہیں لوگوں نے کیا جن کو کتاب دی گئی تھی باوجود یہ کہ ان کے پاس کھلے ہوئے احکام آچکے تھے (اور یہ اختلاف انہوں نے صرف) آپس کی ضد سے (کیا) تو جس امر حق میں وہ اختلاف کرتے تھے خدا نے اپنی مہربانی سے مومنوں کو اس کی راہ دکھا دی۔ اور خدا جس کو چاہتا ہے سیدھا رستہ دکھا دیتا ہے', NULL, NULL, '8d6640c3f973be8eda1009a4a3f9c89ad9034146955ef69c878c133c72057a14'),
  ('ur.jalandhry', 2, 214, 221, 'کیا تم یہ خیال کرتے ہو کہ (یوں ہی) بہشت میں داخل ہوجاؤ گے اور ابھی تم کو پہلے لوگوں کی سی (مشکلیں) تو پیش آئی ہی نہیں۔ ان کو (بڑی بڑی) سختیاں اور تکلیفیں پہنچیں اور وہ (صعوبتوں میں) ہلا ہلا دیئے گئے۔ یہاں تک کہ پیغمبر اور مومن لوگ جو ان کے ساتھ تھے سب پکار اٹھے کہ کب خدا کی مدد آئے گی ۔ دیکھو خدا کی مدد (عن) قریب (آيا چاہتی) ہے', NULL, NULL, '1ca21e9c4d63ddd434b1b441d1e2f5b9ed6dc2da9def77295124ae12cf99ea41'),
  ('ur.jalandhry', 2, 215, 222, '(اے محمدﷺ) لوگ تم سے پوچھتے ہیں کہ (خدا کی راہ میں) کس طرح کا مال خرچ کریں۔ کہہ دو کہ (جو چاہو خرچ کرو لیکن) جو مال خرچ کرنا چاہو وہ (درجہ بدرجہ اہل استحقاق یعنی) ماں باپ اور قریب کے رشتے داروں کو اور یتیموں کو اور محتاجوں کو اور مسافروں کو (سب کو دو) اور جو بھلائی تم کرو گے خدا اس کو جانتا ہے', NULL, NULL, '63520d3b90962a35e3fc178e1db7192ffa84d8d836089aceb41e005dd85b50af'),
  ('ur.jalandhry', 2, 216, 223, '(مسلمانو) تم پر (خدا کے رستے میں) لڑنا فرض کردیا گیا ہے وہ تمہیں ناگوار تو ہوگا مگر عجب نہیں کہ ایک چیز تم کو بری لگے اور وہ تمہارے حق میں بھلی ہو اور عجب نہیں کہ ایک چیز تم کو بھلی لگے اور وہ تمہارے لئے مضر ہو۔ اور ان باتوں کو) خدا ہی بہتر جانتا ہے اور تم نہیں جانتے', NULL, NULL, '361a3f6c71dc4f33adcf79de63f37f3c8247b67ca915b1d0246cbd27963e36f4'),
  ('ur.jalandhry', 2, 217, 224, '(اے محمدﷺ) لوگ تم سے عزت والے مہینوں میں لڑائی کرنے کے بارے میں دریافت کرتے ہیں کہہ دو کہ ان میں لڑنا بڑا (گناہ) ہےاور خدا کی راہ سے روکنا اور اس سے کفر کرنا اور مسجد حرام (یعنی خانہ کعبہ میں جانے) سے (بند کرنا) ۔ اور اہل مسجد کو اس میں سے نکال دینا (جو یہ کفار کرتے ہیں) خدا کے نزدیک اس سے بھی زیادہ (گناہ) ہے۔ اور فتنہ انگیزی خونریزی سے بھی بڑھ کر ہے۔ اور یہ لوگ ہمیشہ تم سے لڑتے رہیں گے یہاں تک کہ اگر مقدور رکھیں تو تم کو تمہارے دین سے پھیر دیں۔ اور جو کوئی تم میں سے اپنے دین سے پھر کر (کافر ہو) جائے گا اور کافر ہی مرے گا تو ایسے لوگوں کے اعمال دنیا اور آخرت دونوں میں برباد ہوجائیں گے اور یہی لوگ دوزخ (میں جانے) والے ہیں جس میں ہمیشہ رہیں گے', NULL, NULL, '66dafe9aac4f4b4f6a4fe5cc4242f28af8a35748a3d84d9a100ea682691dd2e7'),
  ('ur.jalandhry', 2, 218, 225, 'جو لوگ ایمان لائے اور خدا کے لئے وطن چھوڑ گئے اور (کفار سے) جنگ کرتے رہے وہی خدا کی رحمت کے امیدوار ہیں۔ اور خدا بخشنے والا (اور) رحمت کرنے والا ہے', NULL, NULL, '41c81a0810094588994157bc3ddf81ed04afbaa13da784977ca3226e523f536e'),
  ('ur.jalandhry', 2, 219, 226, '(اے پیغمبر) لوگ تم سے شراب اور جوئے کا حکم دریافت کرتے ہیں۔ کہہ دو کہ ان میں نقصان بڑے ہیں اور لوگوں کے لئے کچھ فائدے بھی ہیں مگر ان کے نقصان فائدوں سے کہیں زیادہ ہیں اور یہ بھی تم سے پوچھتے ہیں کہ (خدا کی راہ میں) کون سا مال خرچ کریں۔ کہہ دو کہ جو ضرورت سے زیادہ ہو۔ اس طرح خدا تمہارے لئے اپنے احکام کھول کھول کر بیان فرماتا ہے تاکہ تم سوچو', NULL, NULL, '68f86405bd87a54c45fcaf07d04ff1e23d789112fec5efdcb9bf11fb4ac47590'),
  ('ur.jalandhry', 2, 220, 227, '(یعنی) دنیا اور آخرت (کی باتوں) میں (غور کرو) ۔ اور تم سے یتیموں کے بارے میں دریافت کرتے ہیں کہہ دو کہ ان کی (حالت کی) اصلاح بہت اچھا کام ہے۔ اور اگر تم ان سے مل جل کر رہنا (یعنی خرچ اکھٹا رکھنا) چاہو تو وہ تمہارے بھائی ہیں اور خدا خوب جانتا ہے کہ خرابی کرنے والا کون ہے اور اصلاح کرنے والا کون۔ اور اگر خدا چاہتا تو تم کو تکلیف میں ڈال دیتا۔بےشک خدا غالب (اور) حکمت والا ہے', NULL, NULL, '6df857672209280c18e4038e7b3170e98d806ef7ecf78da5c0cc2a56167c9e0b'),
  ('ur.jalandhry', 2, 221, 228, 'اور (مومنو) مشرک عورتوں سے جب تک کہ ایمان نہ لائیں نکاح نہ کرنا۔ کیونکہ مشرک عورت خواہ تم کو کیسی ہی بھلی لگے اس سے مومن لونڈی بہتر ہے۔ اور (اسی طرح) مشرک مرد جب تک ایمان نہ لائیں مومن عورتوں کو ان کو زوجیت میں نہ دینا کیونکہ مشرک (مرد) سے خواہ وہ تم کو کیسا ہی بھلا لگے مومن غلام بہتر ہے۔ یہ (مشرک لوگوں کو) دوزخ کی طرف بلاتے ہیں۔ اور خدا اپنی مہربانی سے بہشت اور بخشش کی طرف بلاتا ہے۔ اور اپنے حکم لوگوں سے کھول کھول کر بیان کرتا ہے تاکہ نصیحت حاصل کریں', NULL, NULL, '386f0109ddc25cf9bd42345e45917d9e20ff7a89dafcb468edeef719a6b244b5'),
  ('ur.jalandhry', 2, 222, 229, 'اور تم سے حیض کے بارے میں دریافت کرتے ہیں۔ کہہ دو کہ وہ تو نجاست ہے۔ سو ایام حیض میں عورتوں سے کنارہ کش رہو۔ اور جب تک پاک نہ ہوجائیں ان سے مقاربت نہ کرو۔ ہاں جب پاک ہوجائیں تو جس طریق سے خدا نے ارشاد فرمایا ہے ان کے پاس جاؤ۔ کچھ شک نہیں کہ خدا توبہ کرنے والوں اور پاک صاف رہنے والوں کو دوست رکھتا ہے', NULL, NULL, 'cee930f667dc8ef1e30578d8b6d68836fc4c95bf0da3ad3546d8b9fb16d8293f'),
  ('ur.jalandhry', 2, 223, 230, 'تمہاری عورتیں تمہارای کھیتی ہیں تو اپنی کھیتی میں جس طرح چاہو جاؤ۔ اور اپنے لئے (نیک عمل) آگے بھیجو۔ اور خدا سے ڈرتے رہو اور جان رکھو کہ (ایک دن) تمہیں اس کے روبرو حاضر ہونا ہے اور (اے پیغمبر) ایمان والوں کو بشارت سنا دو', NULL, NULL, 'f541aa5757424862e2e16f5f9f2f9044ef69aa83701ce28f9bb86b9dcce05df7'),
  ('ur.jalandhry', 2, 224, 231, 'اور خدا (کے نام کو) اس بات کا حیلہ نہ بنانا کہ (اس کی) قسمیں کھا کھا کر سلوک کرنے اورپرہیزگاری کرنے اور لوگوں میں صلح و سازگاری کرانے سے رک جاؤ۔ اور خدا سب کچھ سنتا اور جانتا ہے', NULL, NULL, 'b9e4bdeea75de9538dfd133966bf1c51662050fd83a103077f05fdadea5a636f'),
  ('ur.jalandhry', 2, 225, 232, 'خدا تمہاری لغو قسموں پر تم سے مواخذہ نہ کرے گا۔ لیکن جو قسمیں تم قصد دلی سے کھاؤ گے ان پر مواخذہ کرے گا۔ اور خدا بخشنے والا بردبار ہے', NULL, NULL, '55ef5d6b626a0d622dd8c568aab9ec12cfc3dfa30ddbe44890a09a21090eb209'),
  ('ur.jalandhry', 2, 226, 233, 'جو لوگ اپنی عورتوں کے پاس جانے سے قسم کھالیں ان کو چار مہینے تک انتظار کرنا چاہیئے۔ اگر (اس عرصے میں قسم سے) رجوع کرلیں تو خدا بخشنے والا مہربان ہے', NULL, NULL, '6ebd1521f345f943638f72efb70396cd0edfa5ceb1fb11424e35548ab2b4797c'),
  ('ur.jalandhry', 2, 227, 234, 'اور اگر طلاق کا ارادہ کرلیں تو بھی خدا سنتا (اور) جانتا ہے', NULL, NULL, '43440702beff3ab3072bf6f877173c24902b9b1a8d27e4205d5eb9726e81de5a'),
  ('ur.jalandhry', 2, 228, 235, 'اور طلاق والی عورتیں تین حیض تک اپنی تئیں روکے رہیں۔ اور اگر وہ خدا اور روز قیامت پر ایمان رکھتی ہیں تو ان کا جائز نہیں کہ خدا نے جو کچھ ان کے شکم میں پیدا کیا ہے اس کو چھپائیں۔ اور ان کے خاوند اگر پھر موافقت چاہیں تو اس (مدت) میں وہ ان کو اپنی زوجیت میں لے لینے کے زیادہ حقدار ہیں۔ اور عورتوں کا حق (مردوں پر) ویسا ہی ہے جیسے دستور کے مطابق (مردوں کا حق) عورتوں پر ہے۔ البتہ مردوں کو عورتوں پر فضیلت ہے۔ اور خدا غالب (اور) صاحب حکمت ہے', NULL, NULL, '89dc1de570f673bc8a9210bb9e306fee53589d4969a83ce7115fc80a7e6b2f44'),
  ('ur.jalandhry', 2, 229, 236, 'طلاق (صرف) دوبار ہے (یعنی جب دو دفعہ طلاق دے دی جائے تو) پھر (عورتوں کو) یا تو بطریق شائستہ (نکاح میں) رہنے دینا یا بھلائی کے ساتھ چھوڑ دینا۔ اور یہ جائز نہیں کہ جو مہر تم ان کو دے چکے ہو اس میں سے کچھ واپس لے لو۔ ہاں اگر زن و شوہر کو خوف ہو کہ وہ خدا کی حدوں کو قائم نہیں رکھ سکیں گے تو اگر عورت (خاوند کے ہاتھ سے) رہائی پانے کے بدلے میں کچھ دے ڈالے تو دونوں پر کچھ گناہ نہیں۔ یہ خدا کی (مقرر کی ہوئی) حدیں ہیں ان سے باہر نہ نکلنا۔ اور جو لوگ خدا کی حدوں سے باہر نکل جائیں گے وہ گنہگار ہوں گے', NULL, NULL, '3bd2def390da9b055839c33b7580dd9ebd35cb9c3c0032f12ac991f0ef65c918'),
  ('ur.jalandhry', 2, 230, 237, 'پھر اگر شوہر (دو طلاقوں کے بعد تیسری) طلاق عورت کو دے دے تو اس کے بعد جب تک عورت کسی دوسرے شخص سے نکاح نہ کرلے اس (پہلے شوہر) پر حلال نہ ہوگی۔ ہاں اگر دوسرا خاوند بھی طلاق دے دے اورعورت اور پہلا خاوند پھر ایک دوسرے کی طرف رجوع کرلیں تو ان پر کچھ گناہ نہیں بشرطیکہ دونوں یقین کریں کہ خدا کی حدوں کو قائم رکھ سکیں گے اور یہ خدا کی حدیں ہیں ان کو وہ ان لوگوں کے لئے بیان فرماتا ہے جو دانش رکھتے ہیں', NULL, NULL, '7da4aff808c1d28d813ee31b319c2d32bd233c97ebc1a4c6fe31ede32f3c8b3d'),
  ('ur.jalandhry', 2, 231, 238, 'اور جب تم عورتوں کو (دو دفعہ) طلاق دے چکو اور ان کی عدت پوری ہوجائے تو انہیں یا تو حسن سلوک سے نکاح میں رہنے دو یا بطریق شائستہ رخصت کردو اور اس نیت سے ان کو نکاح میں نہ رہنے دینا چاہئے کہ انہیں تکلیف دو اور ان پر زیادتی کرو۔ اور جو ایسا کرے گا وہ اپنا ہی نقصان کرے گا اور خدا کے احکام کو ہنسی (اور کھیل) نہ بناؤ اور خدا نے تم کو جو نعمتیں بخشی ہیں اور تم پر جو کتاب اور دانائی کی باتیں نازل کی ہیں جن سے وہ تمہیں نصیحت فرماتا ہے ان کو یاد کرو۔ اور خدا سے ڈرتے رہو اور جان رکھوکہ خدا ہر چیز سے واقف ہے', NULL, NULL, 'e3155eae76380e8cf038f09c0b67db7da47d22e245e99953e45996b21be3cd0f'),
  ('ur.jalandhry', 2, 232, 239, 'اور جب تم عورتوں کو طلاق دے چکو اور ان کی عدت پوری ہوجائے تو ان کو دوسرے شوہروں کے ساتھ جب وہ آپس میں جائز طور پر راضی ہوجائیں نکاح کرنے سے مت روکو۔ اس (حکم) سے اس شخص کو نصیحت کی جاتی ہے جو تم میں خدا اور روز آخرت پر یقین رکھتا ہے۔ یہ تمہارے لئے نہایت خوب اور بہت پاکیزگی کی بات ہے اور خدا جانتا ہے اور تم نہیں جانتے', NULL, NULL, 'eb4051b5748ce3791f874e2721758d9c119db3f4a878e97b1ccf07b39c1970d1'),
  ('ur.jalandhry', 2, 233, 240, 'اور مائیں اپنے بچوں کو پورے دو سال دودھ پلائیں یہ (حکم) اس شخص کے لئے ہے جو پوری مدت تک دودھ پلوانا چاہے۔ اور دودھ پلانے والی ماؤں کا کھانا اور کپڑا دستور کے مطابق باپ کے ذمے ہوگا۔ کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دی جاتی (تو یاد رکھو کہ) نہ تو ماں کو اس کے بچے کے سبب نقصان پہنچایا جائے اور نہ باپ کو اس کی اولاد کی وجہ سے نقصان پہنچایا جائے اور اسی طرح (نان نفقہ) بچے کے وارث کے ذمے ہے۔ اور اگر دونوں (یعنی ماں باپ) آپس کی رضامندی اور صلاح سے بچے کا دودھ چھڑانا چاہیں تو ان پر کچھ گناہ نہیں۔ اور اگر تم اپنی اولاد کو دودھ پلوانا چاہو تو تم پر کچھ گناہ نہیں بشرطیکہ تم دودھ پلانے والیوں کو دستور کے مطابق ان کا حق جو تم نے دینا کیا تھا دے دو اور خدا سے ڈرتے رہو اور جان رکھو کہ جو کچھ تم کرتے ہو خدا اس کو دیکھ رہا ہے', NULL, NULL, '7b3d8b92803a6b0dba4660159712d082c78050d9f8d11f29bd91cb27a8fc5704'),
  ('ur.jalandhry', 2, 234, 241, 'اور جو لوگ تم میں سے مرجائیں اور عورتیں چھوڑ جائیں تو عورتیں چار مہینے دس دن اپنے آپ کو روکے رہیں۔ اور جب (یہ) عدت پوری کرچکیں اور اپنے حق میں پسندیدہ کام (یعنی نکاح) کرلیں تو ان پر کچھ گناہ نہیں۔ اور خدا تمہارے سب کاموں سے واقف ہے', NULL, NULL, '7a3e3b3ef0d48ff56d296eb8f4af15071c6ceee139dd937eea0770c8982395ce'),
  ('ur.jalandhry', 2, 235, 242, 'اور اگر تم کنائے کی باتوں میں عورتوں کو نکاح کا پیغام بھیجو یا (نکاح کی خواہش کو) اپنے دلوں میں مخفی رکھو تو تو تم پر کچھ گناہ نہیں۔ خدا کو معلوم ہے کہ تم ان سے (نکاح کا) ذکر کرو گے۔ مگر (ایام عدت میں) اس کے سوا کہ دستور کے مطابق کوئی بات کہہ دو پوشیدہ طور پر ان سے قول واقرار نہ کرنا۔ اور جب تک عدت پوری نہ ہولے نکاح کا پختہ ارادہ نہ کرنا۔ اور جان رکھو کہ جو کچھ تمہارے دلوں میں ہے خدا کو سب معلوم ہے تو اس سے ڈرتے رہو اور جان رکھو کہ خدا بخشنے والا اور حلم والا ہے', NULL, NULL, 'b3ff2722c72397bceeb3f62d565c7da45c1b762882c67c0d021cc96465a832e1'),
  ('ur.jalandhry', 2, 236, 243, 'اور اگر تم عورتوں کو ان کے پاس جانے یا ان کا مہر مقرر کرنے سے پہلے طلاق دے دو تو تم پر کچھ گناہ نہیں۔ ہاں ان کو دستور کے مطابق کچھ خرچ ضرور دو (یعنی) مقدور والا اپنے مقدور کے مطابق دے اور تنگدست اپنی حیثیت کے مطابق۔ نیک لوگوں پر یہ ایک طرح کا حق ہے', NULL, NULL, 'f937cb583aaf4d67b47523cbf53b256f1f3f8ea56ec2cf3cb3c223db05d05f23'),
  ('ur.jalandhry', 2, 237, 244, 'اور اگر تم عورتوں کو ان کے پاس جانے سے پہلے طلاق دے دو لیکن مہر مقرر کرچکے ہو تو آدھا مہر دینا ہوگا۔ ہاں اگر عورتیں مہر بخش دیں یا مرد جن کے ہاتھ میں عقد نکاح ہے (اپنا حق) چھوڑ دیں۔ (اور پورا مہر دے دیں تو ان کو اختیار ہے) اور اگر تم مرد لوگ ہ اپنا حق چھوڑ دو تو یہ پرہیزگاری کی بات ہے۔ اور آپس میں بھلائی کرنے کو فراموش نہ کرنا۔ کچھ شک نہیں کہ خدا تمہارے سب کاموں کو دیکھ رہا ہے', NULL, NULL, '61c81e3e84f7081785527aa069c515316a6f65f56ad7e64fb1e3ddcb91c52442'),
  ('ur.jalandhry', 2, 238, 245, '(مسلمانو) سب نمازیں خصوصاً بیچ کی نماز (یعنی نماز عصر) پورے التزام کے ساتھ ادا کرتے رہو۔ اور خدا کے آگے ادب سے کھڑے رہا کرو', NULL, NULL, '91901be6ac7eaada4ce43b501a2b9efc87b2fcff3e76d91aa906e60cb7b98707'),
  ('ur.jalandhry', 2, 239, 246, 'اگر تم خوف کی حالت میں ہو تو پیادے یا سوار (جس حال میں ہو نماز پڑھ لو) پھر جب امن (واطمینان) ہوجائے تو جس طریق سے خدا نے تم کو سکھایا ہے جو تم پہلے نہیں جانتے تھے خدا کو یاد کرو', NULL, NULL, 'a53540ed4cca294b0f19a3c138a6e8238993b144aa6863f250ed1ff99ce97bbc'),
  ('ur.jalandhry', 2, 240, 247, 'اور جو لوگ تم میں سے مرجائیں اور عورتیں چھوڑ جائیں وہ اپنی عورتوں کے حق میں وصیت کرجائیں کہ ان کو ایک سال تک خرچ دیا جائے اور گھر سے نہ نکالی جائیں۔ ہاں اگر وہ خود گھر سے نکل جائیں اور اپنے حق میں پسندیدہ کام (یعنی نکاح) کرلیں تو تم پر کچھ گناہ نہیں۔ اور خدا زبردست حکمت والا ہے', NULL, NULL, 'fb6f9aa0c08f8df1c79bc59a3640d34b66ca4b8907467f68ee4ddd7951cba288'),
  ('ur.jalandhry', 2, 241, 248, 'اور مطلقہ عورتوں کو بھی دستور کے مطابق نان و نفقہ دینا چاہیئے پرہیزگاروں پر (یہ بھی) حق ہے', NULL, NULL, 'c15966e8cd3ab32a965c37290850f4eee7e97fb7632d3e4f01dedc3b46db7779'),
  ('ur.jalandhry', 2, 242, 249, 'اسی طرح خدا اپنے احکام تمہارے لئے بیان فرماتا ہے تاکہ تم سمجھو', NULL, NULL, 'cf444dfec70518e6fac7fc2c86e0f3020153894c04e92ea01096233867a804a6'),
  ('ur.jalandhry', 2, 243, 250, 'بھلا تم نے ان لوگوں کو نہیں دیکھا جو (شمار میں) ہزاروں ہی تھے اور موت کے ڈر سے اپنے گھروں سے نکل بھاگے تھے۔ تو خدا نے ان کو حکم دیا کہ مرجاؤ۔ پھر ان کو زندہ بھی کردیا۔ کچھ شک نہیں کہ خدا لوگوں پر مہربانی رکھتا ہے۔ لیکن اکثر لوگ شکر نہیں کرتے', NULL, NULL, '350275d9af7df3680f65f2d4673ea21128fe4f09f77bf6223fe3a2ca91e198af'),
  ('ur.jalandhry', 2, 244, 251, 'اور (مسلمانو) خدا کی راہ میں جہاد کرو اور جان رکھو کہ خدا (سب کچھ) جانتا ہے', NULL, NULL, 'a76075c3e830f2498c0c1f7d79794540e3ba55a53721cd4916ce9a924bd1444f'),
  ('ur.jalandhry', 2, 245, 252, 'کوئی ہے کہ خدا کو قرض حسنہ دے کہ وہ اس کے بدلے اس کو کئی حصے زیادہ دے گا۔ اور خدا ہی روزی کو تنگ کرتا اور (وہی اسے) کشادہ کرتا ہے۔ اور تم اسی کی طرف لوٹ کر جاؤ گے', NULL, NULL, '8b014f220f3170fcbb847728671908b76b44fd79d20ae104971aa26dc0e0acd8'),
  ('ur.jalandhry', 2, 246, 253, 'بھلا تم نے بنی اسرائیل کی ایک جماعت کو نہیں دیکھا جس نے موسیٰ کے بعد اپنے پیغمبر سے کہا کہ آپ ہمارے لئے ایک بادشاہ مقرر کردیں تاکہ ہم خدا کی راہ میں جہاد کریں۔ پیغمبر نے کہا کہ اگر تم کو جہاد کا حکم دیا جائے تو عجب نہیں کہ لڑنے سے پہلو تہی کرو۔ وہ کہنے لگے کہ ہم راہ خدا میں کیوں نہ لڑیں گے جب کہ ہم وطن سے (خارج) اور بال بچوں سے جدا کردیئے گئے۔ لیکن جب ان کو جہاد کا حکم دیا گیا تو چند اشخاص کے سوا سب پھر گئے۔ اور خدا ظالموں سے خوب واقف ہے', NULL, NULL, 'c09120e16092c90db650642751a20a3bbb2ea27598a37e41b7c7476db1a5c3af'),
  ('ur.jalandhry', 2, 247, 254, 'اور پیغمبر نے ان سے (یہ بھی) کہا کہ خدا نے تم پر طالوت کو بادشاہ مقرر فرمایا ہے۔ وہ بولے کہ اسے ہم پر بادشاہی کا حق کیونکر ہوسکتا ہےبادشاہی کے مستحق تو ہم ہیں اور اس کے پاس تو بہت سی دولت بھی نہیں۔ پیغمبر نے کہا کہ خدا نےاس کو تم پر فضیلت دی ہے اور (بادشاہی کے لئے) منتخب فرمایا ہے اس نے اسے علم بھی بہت سا بخشا ہے اور تن و توش بھی (بڑا عطا کیا ہے) اور خدا (کو اختیار ہے) جسے چاہے بادشاہی بخشے۔ وہ بڑا کشائش والا اور دانا ہے', NULL, NULL, 'b93a4cc387a1deb342accf9911af5c937c4d7787e2320acb70f5702d8470f18f'),
  ('ur.jalandhry', 2, 248, 255, 'اور پیغمبر نے ان سے کہا کہ ان کی بادشاہی کی نشانی یہ ہے کہ تمہارے پاس ایک صندوق آئے گا جس کو فرشتے اٹھائے ہوئے ہوں گے اس میں تمہارے پروردگار کی طرف سے تسلی (بخشنے والی چیز) ہوگی اور کچھ اور چیزیں بھی ہوں گی جو موسیٰ اور ہارون چھوڑ گئے تھے۔ اگر تم ایمان رکھتے ہو تو یہ تمہارے لئے ایک بڑی نشانی ہے', NULL, NULL, '9caa9ba0abe1f71d3c080fd24f511ca21778534b0581bb70d5c613176da68bdd'),
  ('ur.jalandhry', 2, 249, 256, 'غرض جب طالوت فوجیں لے کر روانہ ہوا تو اس نے (ان سے) کہا کہ خدا ایک نہر سے تمہاری آزمائش کرنے والا ہے۔ جو شخص اس میں سے پانی پی لے گا (اس کی نسبت تصور کیا جائے گا کہ) وہ میرا نہیں۔ اور جو نہ پئے گا وہ (سمجھا جائے گا کہ) میرا ہے۔ ہاں اگر کوئی ہاتھ سے چلو بھر پانی پی لے (تو خیر۔ جب وہ لوگ نہر پر پہنچے) تو چند شخصوں کے سوا سب نے پانی پی لیا۔ پھر جب طالوت اور مومن لوگ جو اس کے ساتھ تھے نہر کے پار ہوگئے۔ تو کہنے لگے کہ آج ہم میں جالوت اور اس کے لشکر سے مقابلہ کرنے کی طاقت نہیں۔ جو لوگ یقین رکھتے تھے کہ ان کو خدا کے روبرو حاضر ہونا ہے وہ کہنے لگے کہ بسااوقات تھوڑی سی جماعت نے خدا کے حکم سے بڑی جماعت پر فتح حاصل کی ہے اور خدا استقلال رکھنے والوں کے ساتھ ہے', NULL, NULL, 'b5657716f0f63970fd368e178d2bc15da70adb2f8fbd42ee181fbfa6fbd1e877'),
  ('ur.jalandhry', 2, 250, 257, 'اور جب وہ لوگ جالوت اور اس کے لشکر کے مقابل آئے تو (خدا سے) دعا کی کہ اے پروردگار ہم پر صبر کے دہانے کھول دے اور ہمیں (لڑائی میں) ثابت قدم رکھ اور (لشکر) کفار پر فتحیاب کر', NULL, NULL, '3e6ada2ed1cdf434ff23482772fd64dad67bd958bbea77d1a1462571d6a3e346'),
  ('ur.jalandhry', 2, 251, 258, 'تو طالوت کی فوج نے خدا کے حکم سے ان کو ہزیمت دی۔ اور داؤد نے جالوت کو قتل کر ڈالا۔ اور خدا نے اس کو بادشاہی اور دانائی بخشی اور جو کچھ چاہا سکھایا۔ اور خدا لوگوں کو ایک دوسرے (پر چڑھائی اور حملہ کرنے) سے ہٹاتا نہ رہتا تو ملک تباہ ہوجاتا لیکن خدا اہل عالم پر بڑا مہربان ہے', NULL, NULL, 'd9c1263498b799aa7ab5e8548af66a91d9a00547fab102a6f6d6070e07d50cb7'),
  ('ur.jalandhry', 2, 252, 259, 'یہ خدا کی آیتیں ہیں جو ہم تم کو سچائی کے ساتھ پڑھ کر سناتے ہیں (اور اے محمدﷺ) تم بلاشبہ پیغمبروں میں سے ہو', NULL, NULL, '41a599a97b97535dceba8e758cb9c2b5833fbb7f4af362e70b22c36390fa187c'),
  ('ur.jalandhry', 2, 253, 260, 'یہ پیغمبر (جو ہم وقتاً فوقتاً بھیجتے رہیں ہیں) ان میں سے ہم نے بعض کو بعض پر فضیلت دی ہے۔ بعض ایسے ہیں جن سے خدا نے گفتگو فرمائی اور بعض کے (دوسرے امور میں) مرتبے بلند کئے۔ اور عیسیٰ بن مریم کو ہم نے کھلی ہوئی نشانیاں عطا کیں اور روح القدس سے ان کو مدد دی۔ اور اگر خداچاہتا تو ان سے پچھلے لوگ اپنے پاس کھلی نشانیاں آنے کے بعد آپس میں نہ لڑتے لیکن انہوں نے اختلاف کیا تو ان میں سے بعض تو ایمان لے آئے اور بعض کافر ہی رہے۔ اور اگر خدا چاہتا تو یہ لوگ باہم جنگ و قتال نہ کرتے۔ لیکن خدا جو چاہتا ہے کرتا ہے', NULL, NULL, '7dc1e05cc85b27b7ef0c0870a34504170fc5bfe2b3265d024d7b70434b3eaef2'),
  ('ur.jalandhry', 2, 254, 261, 'اے ایمان والو جو (مال) ہم نے تم کو دیا ہے اس میں سے اس دن کے آنے سے پہلے پہلے خرچ کرلو جس میں نہ (اعمال کا) سودا ہو اور نہ دوستی اور سفارش ہو سکے اور کفر کرنے والے لوگ ظالم ہیں', NULL, NULL, '4805f6cf4683b912581f87e1e6559f67b80e641a2b90624f8862763953487472'),
  ('ur.jalandhry', 2, 255, 262, 'خدا (وہ معبود برحق ہے کہ) اس کے سوا کوئی عبادت کے لائق نہیں زندہ ہمیشہ رہنے والا اسے نہ اونگھ آتی ہے نہ نیند جو کچھ آسمانوں میں اور جو کچھ زمین میں ہیں سب اسی کا ہے کون ہے جو اس کی اجازت کے بغیر اس سے (کسی کی) سفارش کر سکے جو کچھ لوگوں کے روبرو ہو رہا ہے اور جو کچھ ان کے پیچھے ہوچکا ہے اسے سب معلوم ہے اور وہ اس کی معلومات میں سے کسی چیز پر دسترس حاصل نہیں کر سکتے ہاں جس قدر وہ چاہتا ہے (اسی قدر معلوم کرا دیتا ہے) اس کی بادشاہی (اور علم) آسمان اور زمین سب پر حاوی ہے اور اسے ان کی حفاظت کچھ بھی دشوار نہیں وہ بڑا عالی رتبہ اور جلیل القدر ہے', NULL, NULL, '1da0f393448d7d835c5a9760f352c1a2f9e90e86313cd87511360bf1aacab0f2'),
  ('ur.jalandhry', 2, 256, 263, 'دین (اسلام) میں زبردستی نہیں ہے ہدایت (صاف طور پر ظاہر اور) گمراہی سے الگ ہو چکی ہے تو جو شخص بتوں سے اعتقاد نہ رکھے اور خدا پر ایمان لائے اس نے ایسی مضبوط رسی ہاتھ میں پکڑ لی ہے جو کبھی ٹوٹنے والی نہیں اور خدا (سب کچھ) سنتا اور (سب کچھ) جانتا ہے', NULL, NULL, '126d04a6b5c2820f8b920279fa337ae85703b373c5f143da25d29f641466fc86'),
  ('ur.jalandhry', 2, 257, 264, 'جو لوگ ایمان لائے ہیں ان کا دوست خدا ہے کہ اُن کو اندھیرے سے نکال کر روشنی میں لے جاتا ہے اور جو کافر ہیں ان کے دوست شیطان ہیں کہ ان کو روشنی سے نکال کر اندھیرے میں لے جاتے ہیں یہی لوگ اہل دوزخ ہیں کہ اس میں ہمیشہ رہیں گے', NULL, NULL, '7faf3400bc3279c1ffafd0bc451f7694e9b771920d64ae59cdd6d908c177cad3'),
  ('ur.jalandhry', 2, 258, 265, 'بھلا تم نے اس شخص کو نہیں دیکھا جو اس (غرور کے) سبب سے کہ خدا نے اس کو سلطنت بخشی تھی ابراہیم سے پروردگار کے بارے میں جھگڑنے لگا۔ جب ابراہیم نے کہا میرا پروردگار تو وہ ہے جو جلاتا اور مارتا ہے۔ وہ بولا کہ جلا اور مار تو میں بھی سکتا ہوں۔ ابراہیم نے کہا کہ خدا تو سورج کو مشرق سے نکالتا ہے آپ اسے مغرب سے نکال دیجیئے (یہ سن کر) کافر حیران رہ گیا اور خدا بےانصافوں کو ہدایت نہیں دیا کرتا', NULL, NULL, '5e7080f5ea1f02f817aa5e4f5163ffa052c0c29c2d0fbfe3afe3d403abf9c81a'),
  ('ur.jalandhry', 2, 259, 266, 'یا اسی طرح اس شخص کو (نہیں دیکھا) جسے ایک گاؤں میں جو اپنی چھتوں پر گرا پڑا تھا اتفاق گزر ہوا۔ تو اس نے کہا کہ خدا اس (کے باشندوں) کو مرنے کے بعد کیونکر زندہ کرے گا۔ تو خدا نے اس کی روح قبض کرلی (اور) سو برس تک (اس کو مردہ رکھا) پھر اس کو جلا اٹھایا اور پوچھا تم کتنا عرصہ (مرے) رہے ہو اس نے جواب دیا کہ ایک دن یا اس سے بھی کم۔ خدا نے فرمایا (نہیں) بلکہ سو برس (مرے) رہے ہو۔ اور اپنے کھانے پینے کی چیزوں کو دیکھو کہ (اتنی مدت میں مطلق) سڑی بسی نہیں اور اپنے گدھے کو بھی دیکھو (جو مرا پڑا ہے) غرض (ان باتوں سے) یہ ہے کہ ہم تم کو لوگوں کے لئے (اپنی قدرت کی) نشانی بنائیں اور (ہاں گدھے) کی ہڈیوں کو دیکھو کہ ہم ان کو کیونکر جوڑے دیتے اور ان پر (کس طرح) گوشت پوست چڑھا دیتے ہیں۔ جب یہ واقعات اس کے مشاہدے میں آئے تو بول اٹھا کہ میں یقین کرتا ہوں کہ خدا ہر چیز پر قادر ہے', NULL, NULL, '3b9ea7b34728e09cf40062cd3df6a5e891aa5c915800f3793b3bffa63547e67d'),
  ('ur.jalandhry', 2, 260, 267, 'اور جب ابراہیم نے (خدا سے) کہا کہ اے پروردگار مجھے دکھا کہ تو مردوں کو کیونکر زندہ کرے گا۔ خدا نے فرمایا کیا تم نے (اس بات کو) باور نہیں کیا۔ انہوں نے کہا کیوں نہیں۔ لیکن (میں دیکھنا) اس لئے (چاہتا ہوں) کہ میرا دل اطمینان کامل حاصل کرلے۔ خدا نے فرمایا کہ چار جانور پکڑوا کر اپنے پاس منگا لو (اور ٹکڑے ٹکڑے کرادو) پھر ان کا ایک ٹکڑا ہر ایک پہاڑ پر رکھوا دو پھر ان کو بلاؤ تو وہ تمہارے پاس دوڑتے چلے آئیں گے۔ اور جان رکھو کہ خدا غالب اور صاحب حکمت ہے۔', NULL, NULL, '966298f4d77033ff5c89b84d33cb87c6e3d904c86e377d108969bdaf252a2540'),
  ('ur.jalandhry', 2, 261, 268, 'جو لوگ اپنا مال خدا کی راہ میں خرچ کرتے ہیں ان (کے مال) کی مثال اس دانے کی سی ہے جس سے سات بالیں اگیں اور ہر ایک بال میں سو سو دانے ہوں اور خدا جس (کے مال) کو چاہتا ہے زیادہ کرتا ہے۔ وہ بڑی کشائش والا اور سب کچھ جاننے والا ہے', NULL, NULL, 'a37414faf1f883738897bfc73e07592140cdea5bd5db5afb8f731f7e8b0499cf'),
  ('ur.jalandhry', 2, 262, 269, 'جو لوگ اپنا مال خدا کے رستے میں صرف کرتے ہیں پھر اس کے بعد نہ اس خرچ کا (کسی پر) احسان رکھتے ہیں اور نہ (کسی کو) تکلیف دیتے ہیں۔ ان کا صلہ ان کے پروردگار کے پاس (تیار) ہے۔ اور (قیامت کے روز) نہ ان کو کچھ خوف ہوگا اور نہ وہ غمگین ہوں گے', NULL, NULL, 'cfeb9e8f884d14cdc0701df178d2d6716f5d49bb34f2fd666fa666bc7a20d9ab'),
  ('ur.jalandhry', 2, 263, 270, 'جس خیرات دینے کے بعد (لینے والے کو) ایذا دی جائے اس سے تو نرم بات کہہ دینی اور (اس کی بے ادبی سے) درگزر کرنا بہتر ہے اور خدا بےپروا اور بردبار ہے', NULL, NULL, '51bb0658c1643cf35c3a172cf4478744a74a957789aa20add6bc787462ccb891'),
  ('ur.jalandhry', 2, 264, 271, 'مومنو! اپنے صدقات (وخیرات) احسان رکھنے اور ایذا دینے سے اس شخص کی طرح برباد نہ کردینا۔ جو لوگوں کو دکھاوے کے لئے مال خرچ کرتا ہے اور خدا اور روز آخرت پر ایمان نہیں رکھتا۔ تو اس (کے مال) کی مثال اس چٹان کی سی ہے جس پر تھوڑی سی مٹی پڑی ہو اور اس پر زور کا مینہ برس کر اسے صاف کر ڈالے۔ (اسی طرح) یہ (ریاکار) لوگ اپنے اعمال کا کچھ بھی صلہ حاصل نہیں کرسکیں گے۔ اور خدا ایسے ناشکروں کو ہدایت نہیں دیا کرتا', NULL, NULL, 'cc090c9c4db01a8749b80aa3763ee5ccafe1bbb9ccd29ba27a5635be492e1d0f'),
  ('ur.jalandhry', 2, 265, 272, 'اور جو لوگ خدا کی خوشنودی حاصل کرنے کے لئے خلوص نیت سے اپنا مال خرچ کرتے ہیں ان کی مثال ایک باغ کی سی ہے جو اونچی جگہ پر واقع ہو (جب) اس پر مینہ پڑے تو دگنا پھل لائے۔ اور اگر مینہ نہ بھی پڑے تو خیر پھوار ہی سہی اور خدا تمہارے کاموں کو دیکھ رہا ہے', NULL, NULL, '2d743ca923c4f850003bd093add2fb0b8055a10d298e6523392a1069042cb9e2'),
  ('ur.jalandhry', 2, 266, 273, 'بھلا تم میں کوئی یہ چاہتا ہے کہ اس کا کھجوروں اور انگوروں کا باغ ہو جس میں نہریں بہہ رہی ہوں اور اس میں اس کے لئے ہر قسم کے میوے موجود ہوں اور اسے بڑھاپا آپکڑے اور اس کے ننھے ننھے بچے بھی ہوں۔ تو (ناگہاں) اس باغ پر آگ کا بھرا ہوا بگولا چلے اور وہ جل کر (راکھ کا ڈھیر ہو) جائے۔ اس طرح خدا تم سے اپنی آیتیں کھول کھول کر بیان فرماتا ہے تاکہ تم سوچو (اور سمجھو)', NULL, NULL, 'eef9b139b0ec8e4fa98ef2c8e98629a47ba2c14f801ee82e8f87150a3e0c4a8b'),
  ('ur.jalandhry', 2, 267, 274, 'مومنو! جو پاکیزہ اور عمدہ مال تم کماتے ہوں اور جو چیزیں ہم تمہارے لئے زمین سےنکالتے ہیں ان میں سے (راہ خدا میں) خرچ کرو۔ اور بری اور ناپاک چیزیں دینے کا قصد نہ کرنا کہ (اگر وہ چیزیں تمہیں دی جائیں تو) بجز اس کے کہ (لیتے وقت) آنکھیں بند کرلو ان کو کبھی نہ لو۔ اور جان رکھو کہ خدا بےپروا (اور) قابل ستائش ہے', NULL, NULL, '0caccf6c1492c43b8fb87ee94cfab7468afb8b271ce882b432c12f29f1a034c9'),
  ('ur.jalandhry', 2, 268, 275, '(اور دیکھنا) شیطان (کا کہنا نہ ماننا وہ) تمہیں تنگ دستی کا خوف دلاتا اور بےحیائی کے کام کر نے کو کہتا ہے۔ اور خدا تم سے اپنی بخشش اور رحمت کا وعدہ کرتا ہے۔ اور خدا بڑی کشائش والا (اور) سب کچھ جاننے والا ہے', NULL, NULL, 'f75a6d58316d7947dd2a67fc9faf30ad7416714fe59aa1218135f27e57bc7266'),
  ('ur.jalandhry', 2, 269, 276, 'وہ جس کو چاہتا ہے دانائی بخشتا ہے۔ اور جس کو دانائی ملی بےشک اس کو بڑی نعمت ملی۔ اور نصیحت تو وہی لوگ قبول کرتے ہیں جو عقلمند ہیں', NULL, NULL, 'a960593fd56ced3fbfb026d6ca8497ffd46e37e3913f9ad864c5cb471080fdd9'),
  ('ur.jalandhry', 2, 270, 277, 'اور تم (خدا کی راہ میں) جس طرح کا خرچ کرو یا کوئی نذر مانو خدا اس کو جانتا ہے اور ظالموں کا کوئی مددگار نہیں', NULL, NULL, '2d9e6b94711e3fd08ebdba58a420af4beccee8064b23173c2057a34ecd723350'),
  ('ur.jalandhry', 2, 271, 278, 'اگر تم خیرات ظاہر دو تو وہ بھی خوب ہے اور اگر پوشیدہ دو اور دو بھی اہل حاجت کو تو وہ خوب تر ہے اور (اس طرح کا دینا) تمہارے گناہوں کو بھی دور کردے گا۔ اور خدا کو تمہارے سب کاموں کی خبر ہے', NULL, NULL, 'a45d37b2c0d10b9032a491b094cf759577d5ff05fe59775325f35c4b737aa48f'),
  ('ur.jalandhry', 2, 272, 279, '(اے محمدﷺ) تم ان لوگوں کی ہدایت کے ذمہ دار نہیں ہو بلکہ خدا ہی جس کو چاہتا ہے ہدایت بخشتا ہے۔ اور (مومنو) تم جو مال خرچ کرو گے تو اس کا فائدہ تمہیں کو ہے اور تم جو خرچ کرو گے خدا کی خوشنودی کے لئے کرو گے۔ اور جو مال تم خرچ کرو گے وہ تمہیں پورا پورا دے دیا جائے گا اور تمہارا کچھ نقصان نہیں کیا جائے گا،', NULL, NULL, 'c472cecafcc65c39a31d2b63ab08754d556ee6b90dd66633a5b8ace98f457bde'),
  ('ur.jalandhry', 2, 273, 280, '(اور ہاں تم جو خرچ کرو گے تو) ان حاجتمندوں کے لئے جو خدا کی راہ میں رکے بیٹھے ہیں اور ملک میں کسی طرف جانے کی طاقت نہیں رکھتے (اور مانگنے سے عار رکھتے ہیں) یہاں تک کہ نہ مانگنے کی وجہ سے ناواقف شخص ان کو غنی خیال کرتا ہے اور تم قیافے سے ان کو صاف پہچان لو (کہ حاجتمند ہیں اور شرم کے سبب) لوگوں سے (منہ پھوڑ کر اور) لپٹ کر نہیں مانگ سکتے اور تم جو مال خرچ کرو گے کچھ شک نہیں کہ خدا اس کو جانتا ہے', NULL, NULL, 'beb2dfa14d2defa23b5e502b10ddb85d9df0a36cab50e45484aadace2f059182'),
  ('ur.jalandhry', 2, 274, 281, 'جو لوگ اپنا مال رات اور دن اور پوشیدہ اور ظاہر (راہ خدا میں) خرچ کرتے رہتے ہیں ان کا صلہ پروردگار کے پاس ہے اور ان کو (قیامت کے دن) نہ کسی طرح کا خوف ہوگا اور نہ غم', NULL, NULL, 'cf8a4f6fe21b3aff1448f93f44bbaae8746ede3e14d40ad77a896d9eda93e660'),
  ('ur.jalandhry', 2, 275, 282, 'جو لوگ سود کھاتے ہیں وہ (قبروں سے) اس طرح (حواس باختہ) اٹھیں گے جیسے کسی کو جن نے لپٹ کر دیوانہ بنا دیا ہو یہ اس لئے کہ وہ کہتے ہیں کہ سودا بیچنا بھی تو (نفع کے لحاظ سے) ویسا ہی ہے جیسے سود (لینا) حالانکہ سودے کو خدا نے حلال کیا ہے اور سود کو حرام۔ تو جس شخص کے پاس خدا کی نصیحت پہنچی اور وہ (سود لینے سے) باز آگیا تو جو پہلے ہوچکا وہ اس کا۔ اور (قیامت میں) اس کا معاملہ خدا کے سپرد اور جو پھر لینے لگا تو ایسے لوگ دوزخی ہیں کہ ہمیشہ دوزخ میں (جلتے) رہیں گے', NULL, NULL, 'e633a290a2590136b9c38a1aed48dff3137d50eb6876df2a6be99edcc3463ef5'),
  ('ur.jalandhry', 2, 276, 283, 'خدا سود کو نابود (یعنی بےبرکت) کرتا اور خیرات (کی برکت) کو بڑھاتا ہے اور خدا کسی ناشکرے گنہگار کو دوست نہیں رکھتا', NULL, NULL, '6a092383aed327a066e8150adf8c3ac148f06913132b004ac063a28a0f5e3c07'),
  ('ur.jalandhry', 2, 277, 284, 'جو لوگ ایمان لائے اور نیک عمل کرتے اور نماز پڑھتے اور زکوٰة دیتے رہے ان کو ان کے کاموں کا صلہ خدا کے ہاں ملے گا اور (قیامت کے دن) ان کو نہ کچھ خوف ہوا اور نہ وہ غمناک ہوں گے', NULL, NULL, '439433c365fccacb0023c1052a8bc66e0e6def6beb51582bb784efb2e4b812b6'),
  ('ur.jalandhry', 2, 278, 285, 'مومنو! خدا سے ڈرو اور اگر ایمان رکھتے ہو تو جتنا سود باقی رہ گیا ہے اس کو چھوڑ دو', NULL, NULL, '0b7f6eb1dba137db15560868c683888f3c5d6dbff63cb29075b1822443f45776'),
  ('ur.jalandhry', 2, 279, 286, 'اگر ایسا نہ کرو گے تو خبردار ہوجاؤ (کہ تم) خدا اور رسول سے جنگ کرنے کے لئے (تیار ہوتے ہو) اور اگر توبہ کرلو گے (اور سود چھوڑ دو گے) تو تم کو اپنی اصل رقم لینے کا حق ہے جس میں نہ اوروں کا نقصان اور تمہارا نقصان', NULL, NULL, '2d24bc9ca9520c17795dc8b99e8689eba925e3b9d232cd42bbf7e8bb1a85e8c0'),
  ('ur.jalandhry', 2, 280, 287, 'اور اگر قرض لینے والا تنگ دست ہو تو (اسے) کشائش (کے حاصل ہونے) تک مہلت (دو) اور اگر (زر قرض) بخش ہی دو توتمہارے لئے زیادہ اچھا ہے بشرطیکہ سمجھو', NULL, NULL, 'c1854556baceb9942ab06a77589e08e1109a9a2c395c8bc818998f24c5281612'),
  ('ur.jalandhry', 2, 281, 288, 'اور اس دن سے ڈرو جب کہ تم خدا کے حضور میں لوٹ کر جاؤ گے اور ہر شخص اپنے اعمال کا پورا پورا بدلہ پائے گا۔ اور کسی کا کچھ نقصان نہ ہوگا', NULL, NULL, '55a6249e5c65f73eda76c9e2682caa69d5ada5f451131d209ff9c5943b722f3d'),
  ('ur.jalandhry', 2, 282, 289, 'مومنو! جب تم آپس میں کسی میعاد معین کے لئے قرض کا معاملہ کرنے لگو تو اس کو لکھ لیا کرو اور لکھنے والا تم میں (کسی کا نقصان نہ کرے بلکہ) انصاف سے لکھے نیز لکھنے والا جیسا اسے خدا نے سکھایا ہے لکھنے سے انکار بھی نہ کرے اور دستاویز لکھ دے۔ اور جو شخص قرض لے وہی (دستاویز کا) مضمون بول کر لکھوائے اور خدا سے کہ اس کا مالک ہے خوف کرے اور زر قرض میں سے کچھ کم نہ لکھوائے۔ اور اگر قرض لینے والا بےعقل یا ضعیف ہو یا مضمون لکھوانے کی قابلیت نہ رکھتا ہو تو جو اس کا ولی ہو وہ انصاف کے ساتھ مضمون لکھوائے۔ اور اپنے میں سے دو مردوں کو (ایسے معاملے کے) گواہ کرلیا کرو۔ اور اگر دو مرد نہ ہوں تو ایک مرد اور دو عورتیں جن کو تم گواہ پسند کرو (کافی ہیں) کہ اگر ان میں سے ایک بھول جائے گی تو دوسری اسے یاد دلادے گی۔ اور جب گواہ (گواہی کے لئے طلب کئے جائیں تو انکار نہ کریں۔ اور قرض تھوڑا ہو یا بہت اس (کی دستاویز) کے لکھنے میں کاہلی نہ کرنا۔ یہ بات خدا کے نزدیک نہایت قرین انصاف ہے اور شہادت کے لئے بھی یہ بہت درست طریقہ ہے۔ اس سے تمہیں کسی طرح کا شک وہ شبہ بھی نہیں پڑے گا۔ ہاں اگر سودا دست بدست ہو جو تم آپس میں لیتے دیتے ہو تو اگر (ایسے معاملے کی) دستاویز نہ لکھوتو تم پر کچھ گناہ نہیں۔ اور جب خرید وفروخت کیا کرو تو بھی گواہ کرلیا کرو۔ اور کاتب دستاویز اور گواہ (معاملہ کرنے والوں کا) کسی طرح نقصان نہ کریں۔ اگر تم (لوگ) ایسا کرو تو یہ تمہارے لئے گناہ کی بات ہے۔ اور خدا سے ڈرو اور (دیکھو کہ) وہ تم کو (کیسی مفید باتیں) سکھاتا ہے اور خدا ہر چیز سے واقف ہے', NULL, NULL, 'e8e2eef254439dad5d22c42395a0be16b13e9e66d431acecf3d1031ea25b06ea'),
  ('ur.jalandhry', 2, 283, 290, 'اور اگر تم سفر پر ہواور (دستاویز) لکھنے والا مل نہ سکے تو (کوئی چیز) رہن یا قبضہ رکھ کر (قرض لے لو) اور اگر کوئی کسی کو امین سمجھے (یعنی رہن کے بغیر قرض دیدے) تو امانتدار کو چاہیئے کہ صاحب امانت کی امانت ادا کردے اور خدا سے جو اس کا پروردگار ہے ڈرے۔اور (دیکھنا) شہادت کو مت چھپانا۔ جو اس کو چھپائے گا وہ دل کا گنہگار ہوگا۔ اور خدا تمہارے سب کاموں سے واقف ہے', NULL, NULL, 'd42ec10fae9bf500a1f69065c1f4a16357d01e58ff755f149a968a28ead9f954'),
  ('ur.jalandhry', 2, 284, 291, 'جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے۔ تم اپنے دلوں کی بات کو ظاہر کرو گے تو یا چھپاؤ گے تو خدا تم سے اس کا حساب لے گا پھر وہ جسے چاہے مغفرت کرے اور جسے چاہے عذاب دے۔ اور خدا ہر چیز پر قادر ہے', NULL, NULL, '626f373570ddc051c49ab7f1a89a17505bb427faa220a127336297ec008350f5'),
  ('ur.jalandhry', 2, 285, 292, 'رسول (خدا) اس کتاب پر جو ان کے پروردگار کی طرف سے ان پر نازل ہوئی ایمان رکھتے ہیں اور مومن بھی۔ سب خدا پر اور اس کے فرشتوں پر اور اس کی کتابوں پر اور اس کے پیغمبروں پر ایمان رکھتے ہیں (اورکہتے ہیں کہ) ہم اس کے پیغمبروں سے کسی میں کچھ فرق نہیں کرتے اور وہ (خدا سے) عرض کرتے ہیں کہ ہم نے (تیرا حکم) سنا اور قبول کیا۔ اے پروردگار ہم تیری بخشش مانگتے ہیں اور تیری ہی طرف لوٹ کر جانا ہے', NULL, NULL, '46e7a9865686f124590bfb01aad730b813717c7d034da89f9cb7f1dbb94280cd'),
  ('ur.jalandhry', 2, 286, 293, 'خدا کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دیتا۔ اچھے کام کرے گا تو اس کو ان کا فائدہ ملے گا برے کرے گا تو اسے ان کا نقصان پہنچے گا۔ اے پروردگار اگر ہم سے بھول یا چوک ہوگئی ہو تو ہم سے مؤاخذہ نہ کیجیو۔ اے پروردگار ہم پر ایسا بوجھ نہ ڈالیو جیسا تو نے ہم سے پہلے لوگوں پر ڈالا تھا۔ اے پروردگار جتنا بوجھ اٹھانے کی ہم میں طاقت نہیں اتنا ہمارے سر پر نہ رکھیو۔ اور (اے پروردگار) ہمارے گناہوں سے درگزر کر اور ہمیں بخش دے۔ اور ہم پر رحم فرما۔ تو ہی ہمارا مالک ہے اور ہم کو کافروں پر غالب فرما', NULL, NULL, 'a6d442d2ee09b3f9dd732ce50930aec713de2bde68d87b3a53bd00b943623eb8'),
  ('ur.jalandhry', 3, 1, 294, 'الم', NULL, NULL, '58bc1e3007bc0ed70b737b562ad04a88867c38e78e58e2f15c3f43c9be783acb'),
  ('ur.jalandhry', 3, 2, 295, 'خدا (جو معبود برحق ہے) اس کے سوا کوئی عبادت کے لائق نہیں ہمیشہ زندہ رہنے والا', NULL, NULL, '2ff19a66ee671b8945cb9dcadc69ff0ebab1017dceb915fd647d6065c3831298'),
  ('ur.jalandhry', 3, 3, 296, 'اس نے (اے محمدﷺ) تم پر سچی کتاب نازل کی جو پہلی (آسمانی) کتابوں کی تصدیق کرتی ہے اور اسی نے تورات اور انجیل نازل کی', NULL, NULL, '91da26f72e3dadaaf29cf5f53389436970602afa0231222fd04433957e53d84c'),
  ('ur.jalandhry', 3, 4, 297, '(یعنی) لوگوں کی ہدایت کے لیے پہلے (تورات اور انجیل اتاری) اور (پھر قرآن جو حق اور باطل کو) الگ الگ کر دینے والا (ہے) نازل کیا جو لوگ خدا کی آیتوں کا انکار کرتے ہیں ان کو سخت عذاب ہوگا اور خدا زبردست (اور) بدلہ لینے والا ہے', NULL, NULL, '9fb2097e83fa698e468020a788751cb60c7d5ec0f5f1d7bac4feb57d72720e6b'),
  ('ur.jalandhry', 3, 5, 298, 'خدا (ایسا خبیر وبصیر ہے کہ) کوئی چیز اس سے پوشیدہ نہیں نہ زمین میں اور نہ آسمان میں', NULL, NULL, 'd3d689d9646beba6096ed2e69ced874c1515b91cd9fcfc56599a07571065f082'),
  ('ur.jalandhry', 3, 6, 299, 'وہی تو ہے جو (ماں کے پیٹ میں) جیسی چاہتا ہے تمہاری صورتیں بناتا ہے اس غالب حکمت والے کے سوا کوئی عبادت کے لائق نہیں', NULL, NULL, '3204e74bb74650268eab1a47afc886e1030a971da5349072a13cc958b00733e1'),
  ('ur.jalandhry', 3, 7, 300, 'وہی تو ہے جس نے تم پر کتاب نازل کی جس کی بعض آیتیں محکم ہیں (اور) وہی اصل کتاب ہیں اور بعض متشابہ ہیں تو جن لوگوں کے دلوں میں کجی ہے وہ متشابہات کا اتباع کرتے ہیں تاکہ فتنہ برپا کریں اور مراد اصلی کا پتہ لگائیں حالانکہ مراد اصلی خدا کے سوا کوئی نہیں جانتا اور جو لوگ علم میں دست گاہ کامل رکھتے ہیں وہ یہ کہتے ہیں کہ ہم ان پر ایمان لائے یہ سب ہمارے پروردگار کی طرف سے ہیں اور نصیحت تو عقل مند ہی قبول کرتے ہیں', NULL, NULL, '4fc0392c4c3f3824d73c2e8cc583e9526c869b87fc374dea94fa69cd5fc1e225')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 3, 8, 301, 'اے پروردگار جب تو نے ہمیں ہدایت بخشی ہے تو اس کے بعد ہمارے دلوں میں کجی نہ پیدا کر دیجیو اور ہمیں اپنے ہاں سے نعمت عطا فرما تو تو بڑا عطا فرمانے والا ہے', NULL, NULL, 'a4d155ac3d652353d0d6dd48e5d528c553730bc796e6309c084bf752bf840363'),
  ('ur.jalandhry', 3, 9, 302, 'اے پروردگار! تو اس روز جس (کے آنے) میں کچھ بھی شک نہیں سب لوگوں کو (اپنے حضور میں) جمع کرلے گا بے شک خدا خلاف وعدہ نہیں کرتا', NULL, NULL, '99181b98a8b21d82978667e181de065109150efea0f03462c94c03fccb029674'),
  ('ur.jalandhry', 3, 10, 303, 'جو لوگ کافر ہوئے (اس دن) نہ تو ان کا مال ہی خدا (کے عذاب) سے ان کو بچا سکے گا اور نہ ان کی اولاد ہی (کچھ کام آئے گی) اور یہ لوگ آتش (جہنم) کا ایندھن ہوں گے', NULL, NULL, 'af85820da2afb192ea8515be5204115562c783554798a135f732df994e094015'),
  ('ur.jalandhry', 3, 11, 304, 'ان کا حال بھی فرعونیوں اور ان سے پہلے لوگوں کا سا ہوگا جنہوں نے ہماری آیتوں کی تکذیب کی تھی تو خدا نے ان کو ان کے گناہوں کے سبب (عذاب میں) پکڑ لیا تھا اور خدا سخت عذاب کرنے والا ہے', NULL, NULL, 'e75a971141689b362d9ef7608cd3e28edafa5e289e90456a9766bf629f91c83c'),
  ('ur.jalandhry', 3, 12, 305, '(اے پیغمبر) کافروں سے کہدو کہ تم (دنیا میں بھی) عنقریب مغلوب ہو جاؤ گے اور (آخرت میں) جہنم کی طرف ہانکے جاؤ گے اور وہ بری جگہ ہے', NULL, NULL, '7877953dbe7b6cb6c82d57078321584ba9a101c417fafe1fb019b2cb4c27ff78'),
  ('ur.jalandhry', 3, 13, 306, 'تمہارے لیے دو گروہوں میں جو (جنگ بدر کے دن) آپس میں بھڑ گئے (قدرت خدا کی عظیم الشان) نشانی تھی ایک گروہ (مسلمانوں کا تھا وہ) خدا کی راہ میں لڑ رہا تھا اور دوسرا گروہ (کافروں کا تھا وہ) ان کو اپنی آنکھوں سے اپنے سے دگنا مشاہدہ کر رہا تھا اور خدا اپنی نصرت سے جس کو چاہتا ہے مدد دیتا ہے جو اہل بصارت ہیں ان کے لیے اس (واقعے) میں بڑی عبرت ہے', NULL, NULL, 'db37105978a6b4480511e2a23a31c50f5c1848aa6487af5a118a329acbbd9293'),
  ('ur.jalandhry', 3, 14, 307, 'لوگوں کو ان کی خواہشوں کی چیزیں یعنی عورتیں اور بیٹے اور سونے اور چاندی کے بڑے بڑے ڈھیر اور نشان لگے ہوئے گھوڑے اور مویشی اور کھیتی بڑی زینت دار معلوم ہوتی ہیں (مگر) یہ سب دنیا ہی کی زندگی کے سامان ہیں اور خدا کے پاس بہت اچھا ٹھکانا ہے', NULL, NULL, '26225522c9533ca5a50298c27bbc6f765ae52194243eba728a40da0c9ce7f0e3'),
  ('ur.jalandhry', 3, 15, 308, '(اے پیغمبر ان سے) کہو کہ بھلا میں تم کو ایسی چیز بتاؤں جو ان چیزوں سے کہیں اچھی ہو (سنو) جو لوگ پرہیزگار ہیں ان کے لیے خدا کے ہاں باغات (بہشت) ہیں جن کے نیچے نہریں بہہ رہی ہیں ان میں وہ ہمیشہ رہیں گے اور پاکیزہ عورتیں ہیں اور (سب سے بڑھ کر) خدا کی خوشنودی اور خدا (اپنے نیک) بندوں کو دیکھ رہا ہے', NULL, NULL, '5ece18c9a3556bf967586fc39e930d98614ddf5f5c547fc7f8ab2bc6104b702b'),
  ('ur.jalandhry', 3, 16, 309, 'جو خدا سے التجا کرتے ہیں کہ اے پروردگار ہم ایمان لے آئے سو ہم کو ہمارے گناہ معاف فرما اور دوزخ کے عذاب سے محفوظ رکھ', NULL, NULL, 'e1a5e5e0f077c17a5c8296b6f6f3f7b3c968c9f301bafec2da6aee6e95edb8d3'),
  ('ur.jalandhry', 3, 17, 310, 'یہ وہ لوگ ہیں جو (مشکلات میں) صبر کرتے اور سچ بولتے اور عبادت میں لگے رہتے اور (راہ خدا میں) خرچ کرتے اور اوقات سحر میں گناہوں کی معافی مانگا کرتے ہیں', NULL, NULL, 'e42cc550b53cc6f2cedc268daf45afeca0d7c11e5bd9e26490e9ac73e6da7c54'),
  ('ur.jalandhry', 3, 18, 311, 'خدا تو اس بات کی گواہی دیتا ہے کہ اس کے سوا کوئی معبود نہیں اور فرشتے اور علم والے لوگ جو انصاف پر قائم ہیں وہ بھی (گواہی دیتے ہیں کہ) اس غالب حکمت والے کے سوا کوئی عبادت کے لائق نہیں', NULL, NULL, '53da48ab90dbc95a632ca164f44d0b8fadb05de1bf89e4ee34f230f450d0aad0'),
  ('ur.jalandhry', 3, 19, 312, 'دین تو خدا کے نزدیک اسلام ہے اور اہل کتاب نے جو (اس دین سے) اختلاف کیا تو علم ہونے کے بعد آپس کی ضد سے کیا اور جو شخص خدا کی آیتوں کو نہ مانے تو خدا جلد حساب لینے والا (اور سزا دینے والا) ہے', NULL, NULL, '3b54552a834717693609938ea4ffefd70ded06f994ce7a57bef59477b08aefa7'),
  ('ur.jalandhry', 3, 20, 313, 'اے پیغمبر اگر یہ لوگ تم سے جھگڑنے لگیں تو کہنا کہ میں اور میرے پیرو تو خدا کے فرمانبردار ہو چکے اور اہل کتاب اور ان پڑھ لوگوں سے کہو کہ کیا تم بھی (خدا کے فرمانبردار بنتے ہو) اور اسلام لاتے ہو؟ اگر یہ لوگ اسلام لے آئیں تو بے شک ہدایت پالیں اور اگر (تمہارا کہا) نہ مانیں تو تمہارا کام صرف خدا کا پیغام پہنچا دینا ہے اور خدا (اپنے) بندوں کو دیکھ رہا ہے', NULL, NULL, '744e8abcaad19dee596ca4a745964d9e240e985f10ea8e0ec446bee2f5164fed'),
  ('ur.jalandhry', 3, 21, 314, 'جو لوگ خدا کی آیتوں کو نہیں مانتے اور انبیاء کو ناحق قتل کرتے رہے ہیں اور جو انصاف (کرنے) کا حکم دیتے ہیں انہیں بھی مار ڈالتے ہیں ان کو دکھ دینے والے عذاب کی خوشخبری سنا دو', NULL, NULL, '04029970c17c56d350247828a3caf0ac49d5f423155efef32438604fce6fb017'),
  ('ur.jalandhry', 3, 22, 315, 'یہ ایسے لوگ ہیں جن کے اعمال دنیا اور آخرت دونوں میں برباد ہیں اور ان کا کوئی مددگار نہیں (ہوگا)', NULL, NULL, '09c6d4ad1f3d799561f2c5ff8a0edaa2d1c9314417a728ca386482f495521623'),
  ('ur.jalandhry', 3, 23, 316, 'بھلا تم نے ان لوگوں کو نہیں دیکھا جن کو کتاب (خدا یعنی تورات سے) بہرہ دیا گیا اور وہ (اس) کتاب الله کی طرف بلائے جاتے ہیں تاکہ وہ (ان کے تنازعات کا) ان میں فیصلہ کر دے تو ایک فریق ان میں سے کج ادائی کے ساتھ منہ پھیر لیتا ہے', NULL, NULL, 'e6f222207dd684cd9490aca31d1679075147565e9efadf48fe661107d669146c'),
  ('ur.jalandhry', 3, 24, 317, 'یہ اس لیے کہ یہ اس بات کے قائل ہیں کہ (دوزخ کی) آگ ہمیں چند روز کے سوا چھو ہی نہیں سکے گی اور جو کچھ یہ دین کے بارے میں بہتان باندھتے رہے ہیں اس نے ان کو دھوکے میں ڈال رکھا ہے', NULL, NULL, 'f9b129c665c8e78436b8b3c127ca7499f5e2fef193bafd46b2e2a52a99267ea7'),
  ('ur.jalandhry', 3, 25, 318, 'تو اس وقت کیا حال ہوگا جب ہم ان کو جمع کریں گے (یعنی) اس روز جس (کے آنے) میں کچھ بھی شک نہیں اور ہر نفس اپنے اعمال کا پورا پورا بدلہ پائے گا اور ان پر ظلم نہیں کیا جائے گا', NULL, NULL, '7c05565029f0bba4e6ca43035174411a413cba4189f10e2b3435335cd6abfdbb'),
  ('ur.jalandhry', 3, 26, 319, 'کہو کہ اے خدا (اے) بادشاہی کے مالک تو جس کو چاہے بادشاہی بخشے اور جس سے چاہے بادشاہی چھین لے اور جس کو چاہے عزت دے اور جسے چاہے ذلیل کرے ہر طرح کی بھلائی تیرے ہی ہاتھ ہے اور بے شک تو ہر چیز پر قادر ہے', NULL, NULL, '641e2e42b02b67c12d899349b609a2028888ab2acb0e661f3b97731b78bb1140'),
  ('ur.jalandhry', 3, 27, 320, 'تو ہی رات کو دن میں داخل کرتا اور تو ہی دن کو رات میں داخل کرتا ہے تو ہی بے جان سے جاندار پیدا کرتا ہے اور تو ہی جاندار سے بے جان پیدا کرتا ہے اور توہی جس کو چاہتا ہے بے شمار رزق بخشتا ہے', NULL, NULL, '34272e1a173f0ee82ed79a84ee510c3a6b1315483ddcc723c162270349e3da76'),
  ('ur.jalandhry', 3, 28, 321, 'مؤمنوں کو چاہئے کہ مؤمنوں کے سوا کافروں کو دوست نہ بنائیں اور جو ایسا کرے گا اس سے خدا کا کچھ (عہد) نہیں ہاں اگر اس طریق سے تم ان (کے شر) سے بچاؤ کی صورت پیدا کرو (تو مضائقہ نہیں) اور خدا تم کو اپنے (غضب) سے ڈراتا ہے اور خدا ہی کی طرف (تم کو) لوٹ کر جانا ہے', NULL, NULL, 'c75c7f0c3b4619af51c94f74442ce31f4e2b05482f899f04297b96504339bdd7'),
  ('ur.jalandhry', 3, 29, 322, '(اے پیغمبر لوگوں سے) کہہ دو کہ کوئی بات تم اپنے دلوں میں مخفی رکھو یا اسے ظاہر کرو خدا اس کو جانتا ہے اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے اس کو سب کی خبر ہے اور وہ ہر چیز پر قادر ہے', NULL, NULL, '7d56a0901c8937382ddc18a3ec455838708e1a9d71709df10e921ff190354fdc'),
  ('ur.jalandhry', 3, 30, 323, 'جس دن ہر شخص اپنے اعمال کی نیکی کو موجود پالے گا اور ان کی برائی کو بھی (دیکھ لے گا) تو آرزو کرے گا کہ اے کاش اس میں اور اس برائی میں دور کی مسافت ہو جاتی اور خدا تم کو اپنے (غضب) سے ڈراتا ہے اور خدا اپنے بندوں پر نہایت مہربان ہے', NULL, NULL, 'de73d47c2d0dd8234154651200327d6f539b0ff733b86420117c054a42ee6a61'),
  ('ur.jalandhry', 3, 31, 324, '(اے پیغمبر لوگوں سے) کہہ دو کہ اگر تم خدا کو دوست رکھتے ہو تو میری پیروی کرو خدا بھی تمہیں دوست رکھے گا اور تمہارے گناہ معاف کر دے گا اور خدا بخشنے والا مہربان ہے', NULL, NULL, '6f5e28130e72853c3666ca90d21ca35d03d8242e0a48377bb5a4b118e308022e'),
  ('ur.jalandhry', 3, 32, 325, 'کہہ دو کہ خدا اور اس کے رسول کا حکم مانو اگر نہ مانیں تو خدا بھی کافروں کو دوست نہیں رکھتا', NULL, NULL, '6c194a54db12aa322a235bc6ae38cb744fe7e38af3aff7f6b7d362be16816fd8'),
  ('ur.jalandhry', 3, 33, 326, 'خدا نے آدم اور نوح اور خاندان ابراہیم اور خاندان عمران کو تمام جہان کے لوگوں میں منتخب فرمایا تھا', NULL, NULL, 'e0a7bfbfadfcd4f14a00c58626403ff7b704a1b63f68323451a1969cd85f925f'),
  ('ur.jalandhry', 3, 34, 327, 'ان میں سے بعض بعض کی اولاد تھے اور خدا سننے والا (اور) جاننے والا ہے', NULL, NULL, '7591f186787fc10f0f71783a233396909a7e5c42ba1a64edcc004040ae83c1fa'),
  ('ur.jalandhry', 3, 35, 328, '(وہ وقت یاد کرنے کے لائق ہے) جب عمران کی بیوی نے کہا کہ اے پروردگار جو (بچہ) میرے پیٹ میں ہے میں اس کو تیری نذر کرتی ہوں اسے دنیا کے کاموں سے آزاد رکھوں گی تو (اسے) میری طرف سے قبول فرما توتو سننے والا (اور) جاننے والا ہے', NULL, NULL, '014f2137bb30d3e25589488148e63b10a714c59b62ae5979e97056ebbea46e12'),
  ('ur.jalandhry', 3, 36, 329, 'جب ان کے ہاں بچہ پیدا ہوا اور جو کچھ ان کے ہاں پیدا ہوا تھا خدا کو خوب معلوم تھا تو کہنے لگیں کہ پروردگار! میرے تو لڑکی ہوئی ہے اور (نذر کے لیے) لڑکا (موزوں تھا کہ وہ) لڑکی کی طرح (ناتواں) نہیں ہوتا اور میں نے اس کا نام مریم رکھا ہے اور میں اس کو اور اس کی اولاد کو شیطان مردود سے تیری پناہ میں دیتی ہوں', NULL, NULL, '586e4e1e07e9e45ce0f5a085cf7d758c413d496b5501bc7b51f8dddc92e50d16'),
  ('ur.jalandhry', 3, 37, 330, 'تو پروردگار نے اس کو پسندیدگی کے ساتھ قبول فرمایا اور اسے اچھی طرح پرورش کیا اور زکریا کو اس کا متکفل بنایا زکریا جب کبھی عبادت گاہ میں اس کے پاس جاتے تو اس کے پاس کھانا پاتے (یہ کیفیت دیکھ کر ایک دن مریم سے) پوچھنے لگے کہ مریم یہ کھانا تمہارے پاس کہاں سے آتا ہے وہ بولیں خدا کے ہاں سے (آتا ہے) بیشک خدا جسے چاہتا ہے بے شمار رزق دیتا ہے', NULL, NULL, 'a50d07d54f9022edb8754d322e2047707f8d1c44ade2e70157d3ad084d533df1'),
  ('ur.jalandhry', 3, 38, 331, 'اس وقت زکریا نے اپنے پروردگار سے دعا کی (اور) کہا کہ پروردگار مجھے اپنی جناب سے اولاد صالح عطا فرما تو بے شک دعا سننے (اور قبول کرنے) والا ہے', NULL, NULL, '9fd41d762a68d6d78ccee321bea422772057d57c34dc715aea37b94a38d183ea'),
  ('ur.jalandhry', 3, 39, 332, 'وہ ابھی عبادت گاہ میں کھڑے نماز ہی پڑھ رہے تھے کہ فرشتوں نے آواز دی کہ (زکریا) خدا تمہیں یحییٰ کی بشارت دیتا ہے جو خدا کے فیض یعنی (عیسیٰ) کی تصدیق کریں گے اور سردار ہوں گے اور عورتوں سے رغبت نہ رکھنے والے اور (خدا کے) پیغمبر (یعنی) نیکو کاروں میں ہوں گے', NULL, NULL, '27ec8ad6d0e18824bffd79b27db4f877f6c2ce92d272ffcd3a0ea8c31ce99a8c'),
  ('ur.jalandhry', 3, 40, 333, 'زکریا نے کہا اے پروردگار میرے ہاں لڑکا کیونکر پیدا ہوگا کہ میں تو بڈھا ہوگیا ہوں اور میری بیوی بانجھ ہے خدا نے فرمایا اسی طرح خدا جو چاہتا ہے کرتا ہے', NULL, NULL, '35be20ce93cb2d12c93b1fb5cc8724640a3f1555311127b70ef8aa771ad838eb'),
  ('ur.jalandhry', 3, 41, 334, 'زکریا نے کہا کہ پروردگار (میرے لیے) کوئی نشانی مقرر فرما خدا نے فرمایا نشانی یہ ہے کہ تم لوگوں سے تین دن اشارے کے سوا بات نہ کر سکو گے تو (ان دنوں میں) اپنے پروردگار کی کثرت سے یاد اور صبح و شام اس کی تسبیح کرنا', NULL, NULL, 'adc4e99451c377db17a3d6f8771ff7556028afc4e4f08d0465fd791a65aa740b'),
  ('ur.jalandhry', 3, 42, 335, 'اور جب فرشتوں نے (مریم سے) کہا کہ مریم! خدا نے تم کو برگزیدہ کیا ہے اور پاک بنایا ہے اور جہان کی عورتوں میں منتخب کیا ہے', NULL, NULL, 'edbdd88bc2d662c0a38ec60f0e5f584ef43aa6136c3f5df579eb2aa0a9e59ace'),
  ('ur.jalandhry', 3, 43, 336, 'مریم اپنے پروردگار کی فرمانبرداری کرنا اور سجدہ کرنا اور رکوع کرنے والوں کے ساتھ رکوع کرنا', NULL, NULL, 'de8879b253e145c1901cfbf9d5764ecfc4b41053f314cbbd38e98bd262213dde'),
  ('ur.jalandhry', 3, 44, 337, '(اے محمدﷺ) یہ باتیں اخبار غیب میں سے ہیں جو ہم تمہارے پاس بھیجتے ہیں اور جب وہ لوگ اپنے قلم (بطور قرعہ) ڈال رہے تھے کہ مریم کا متکفل کون بنے تو تم ان کے پاس نہیں تھے اور نہ اس وقت ہی ان کے پاس تھے جب وہ آپس میں جھگڑ رہے تھے', NULL, NULL, 'a84ab32d6091317173bb14da833a4cce011c0871d1fa5b8617dd0df7d18bbd49'),
  ('ur.jalandhry', 3, 45, 338, '(وہ وقت بھی یاد کرنے کے لائق ہے) جب فرشتوں نے (مریم سے کہا) کہ مریم خدا تم کو اپنی طرف سے ایک فیض کی بشارت دیتا ہے جس کا نام مسیح (اور مشہور) عیسیٰ ابن مریم ہوگا (اور) جو دنیا اور آخرت میں باآبرو اور (خدا کے) خاصوں میں سے ہوگا', NULL, NULL, '5c122da47cd82c872d083cecfeee0faba0d82e235d13586bcb1ff248fd85658e'),
  ('ur.jalandhry', 3, 46, 339, 'اور ماں کی گود میں اور بڑی عمر کا ہو کر (دونوں حالتوں میں) لوگوں سے (یکساں) گفتگو کرے گا اور نیکو کاروں میں ہوگا', NULL, NULL, '2f48f6d768cda5a9b80de589689f115eb797d8940cb6ab68de3d6a4752d93039'),
  ('ur.jalandhry', 3, 47, 340, 'مریم نے کہا پروردگار میرے ہاں بچہ کیونکر ہوگا کہ کسی انسان نے مجھے ہاتھ تک تو لگایا نہیں فرمایا کہ خدا اسی طرح جو چاہتا ہے پیدا کرتا ہے جب وہ کوئی کام کرنا چاہتا ہے تو ارشاد فرما دیتا ہے کہ ہوجا تو وہ ہو جاتا ہے', NULL, NULL, '677f4b0d062c2fff09ac8531c9b6858ba8d5faa3e08fc16648ca074258dcf2dd'),
  ('ur.jalandhry', 3, 48, 341, 'اور وہ انہیں لکھنا (پڑھنا) اور دانائی اور تورات اور انجیل سکھائے گا', NULL, NULL, 'b5e854b0231ea91af1c831d6ebec843aa55390c70bb9074d07ced3df2b8483af'),
  ('ur.jalandhry', 3, 49, 342, 'اور (عیسیٰ) بنی اسرائیل کی طرف پیغمبر (ہو کر جائیں گے اور کہیں گے) کہ میں تمہارے پروردگار کی طرف سے نشانی لے کر آیا ہوں وہ یہ کہ تمہارے سامنے مٹی کی مورت بشکل پرند بناتا ہوں پھر اس میں پھونک مارتا ہوں تو وہ خدا کے حکم سے (سچ مچ) جانور ہو جاتا ہے اور اندھے اور ابرص کو تندرست کر دیتا ہوں اور خدا کے حکم سے مردے میں جان ڈال دیتا ہوں اور جو کچھ تم کھا کر آتے ہو اور جو اپنے گھروں میں جمع کر رکھتے ہو سب تم کو بتا دیتا ہوں اگر تم صاحب ایمان ہو تو ان باتوں میں تمہارے لیے (قدرت خدا کی) نشانی ہے', NULL, NULL, '978fcf0d2a32c6bd71bc2f7d35b13704e66a98d849be159f3a246690bdc2eeea'),
  ('ur.jalandhry', 3, 50, 343, 'اور مجھ سے پہلے جو تورات (نازل ہوئی) تھی اس کی تصدیق بھی کرتا ہوں اور (میں) اس لیے بھی (آیا ہوں) کہ بعض چیزیں جو تم پر حرام تھیں ان کو تمہارے لیے حلال کر دوں اور میں تو تمہارے پروردگار کی طرف سے نشانی لے کر آیا ہوں تو خدا سے ڈرو اور میرا کہا مانو', NULL, NULL, '77f53141e85d6a674117ee7ab14a886e70f602d0268bbc0ad151361f435cc572'),
  ('ur.jalandhry', 3, 51, 344, 'کچھ شک نہیں کہ خدا ہی میرا اور تمہارا پروردگار ہے تو اسی کی عبادت کرو یہی سیدھا رستہ ہے', NULL, NULL, 'dba2b1f41915d8b10dc1627c30293368f282aae1722e6b8328134bec78fb9302'),
  ('ur.jalandhry', 3, 52, 345, 'جب عیسیٰؑ نے ان کی طرف سے نافرمانی اور (نیت قتل) دیکھی تو کہنے لگے کہ کوئی ہے جو خدا کا طرف دار اور میرا مددگار ہو حواری بولے کہ ہم خدا کے (طرفدار اور آپ کے) مددگار ہیں ہم خدا پر ایمان لائے اور آپ گواہ رہیں کہ ہم فرمانبردار ہیں', NULL, NULL, 'de0e8148a60285c5db068f2395d5d95c489c58d9ca9974d51d0d81dc8bdf970f'),
  ('ur.jalandhry', 3, 53, 346, 'اے پروردگار جو (کتاب) تو نے نازل فرمائی ہے ہم اس پر ایمان لے آئے اور (تیرے) پیغمبر کے متبع ہو چکے تو ہم کو ماننے والوں میں لکھ رکھ', NULL, NULL, '3d3784baa522f09ca00a3c15e98d4a22b39ea53703fdbe7d7a5276e80c9da9f4'),
  ('ur.jalandhry', 3, 54, 347, 'اور وہ (یعنی یہود قتل عیسیٰ کے بارے میں ایک) چال چلے اور خدا بھی (عیسیٰ کو بچانے کے لیے) چال چلا اور خدا خوب چال چلنے والا ہے', NULL, NULL, 'c66990e88bb758486d896df360613ff3ced19785356608d53567d71d999278eb'),
  ('ur.jalandhry', 3, 55, 348, 'اس وقت خدا نے فرمایا کہ عیسیٰ! میں تمہاری دنیا میں رہنے کی مدت پوری کرکے تم کو اپنی طرف اٹھا لوں گا اور تمہیں کافروں (کی صحبت) سے پاک کر دوں گا اور جو لوگ تمہاری پیروی کریں گے ان کو کافروں پر قیامت تک فائق (وغالب) رکھوں گا پھر تم سب میرے پاس لوٹ کر آؤ گے تو جن باتوں میں تم اختلاف کرتے تھے اس دن تم میں ان کا فیصلہ کردوں گا', NULL, NULL, '8a2ec5cb9c2dab60ee3a61f5c280d136a40a443fde8ea7fb646d86dc68ce0f49'),
  ('ur.jalandhry', 3, 56, 349, 'یعنی جو کافر ہوئے ان کو دنیا اور آخرت (دونوں) میں سخت عذاب دوں گا اور ان کا کوئی مددگار نہ ہوگا', NULL, NULL, '4f5908fd6545098f376261bf5eeaac709602c2ae28530d5c602047676d312221'),
  ('ur.jalandhry', 3, 57, 350, 'اور جو ایمان لائے اور نیک عمل کرتے رہے ان کو خدا پورا پورا صلہ دے گا اور خدا ظالموں کو دوست نہیں رکھتا', NULL, NULL, '65382b5d0027bdc3d6ac00f4cd3e2ca466cc88f7dd57fabe03f2e289d8342eb8'),
  ('ur.jalandhry', 3, 58, 351, '(اے محمدﷺ) یہ ہم تم کو (خدا کی) آیتیں اور حکمت بھری نصیحتیں پڑھ پڑھ کر سناتے ہیں', NULL, NULL, '8c992c0f57bb30f9c9a64c9051d976876a08576cfd63448169238706636959b2'),
  ('ur.jalandhry', 3, 59, 352, 'عیسیٰ کا حال خدا کے نزدیک آدم کا سا ہے کہ اس نے (پہلے) مٹی سے ان کا قالب بنایا پھر فرمایا کہ (انسان) ہو جا تو وہ (انسان) ہو گئے', NULL, NULL, '854905ebdbe63934348b4a7e80d0b390e4b4dd20c33e110ab6207e2949637f98'),
  ('ur.jalandhry', 3, 60, 353, '(یہ بات) تمہارے پروردگار کی طرف سے حق ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا', NULL, NULL, '414df5ecee9392050e395ae74d5b119f15355150696e9ef141cf06d65372c2cf'),
  ('ur.jalandhry', 3, 61, 354, 'پھر اگر یہ لوگ عیسیٰ کے بارے میں تم سے جھگڑا کریں اور تم کو حقیقت الحال تو معلوم ہو ہی چلی ہے تو ان سے کہنا کہ آؤ ہم اپنے بیٹوں اور عورتوں کو بلائیں تم اپنے بیٹوں اور عورتوں کو بلاؤ اور ہم خود بھی آئیں اور تم خود بھی آؤ پھر دونوں فریق (خدا سے) دعا والتجا کریں اور جھوٹوں پر خدا کی لعنت بھیجیں', NULL, NULL, '603240fcb41634cc572e7e753b44f6932c4f6d1e775f2382141d7c01b6c1fab7'),
  ('ur.jalandhry', 3, 62, 355, 'یہ تمام بیانات صحیح ہیں اور خدا کے سوا کوئی معبود نہیں اور بیشک خدا غالب اور صاحبِ حکمت ہے', NULL, NULL, 'bf249b39e40de355fc6e3d7dd6e1c1a5accf590190e6ec347dc8458cce836fc9'),
  ('ur.jalandhry', 3, 63, 356, 'تو اگر یہ لوگ پھر جائیں تو خدا مفسدوں کو خوب جانتا ہے', NULL, NULL, 'b6bf21573582ff8986e9cc5d609713ea0c363fa36386b9229fd822bd9a08741e'),
  ('ur.jalandhry', 3, 64, 357, 'کہہ دو کہ اے اہل کتاب جو بات ہمارے اور تمہارے دونوں کے درمیان یکساں (تسلیم کی گئی) ہے اس کی طرف آؤ وہ یہ کہ خدا کے سوا ہم کسی کی عبادت نہ کریں اور اس کے ساتھ کسی چیز کو شریک نہ بنائیں اور ہم میں سے کوئی کسی کو خدا کے سوا اپنا کار ساز نہ سمجھے اگر یہ لوگ (اس بات کو) نہ مانیں تو (ان سے) کہہ دو کہ تم گواہ رہو کہ ہم (خدا کے) فرماں بردار ہیں', NULL, NULL, 'cc5b8fab6fa18fca2c78b37c375a34f49e3f2b3304d0971baf2b756eb52eb449'),
  ('ur.jalandhry', 3, 65, 358, 'اے اہلِ کتاب تم ابراہیم کے بارے میں کیوں جھگڑتے ہو حالانکہ تورات اور انجیل ان کے بعد اتری ہیں (اور وہ پہلے ہو چکے ہیں) تو کیا تم عقل نہیں رکھتے', NULL, NULL, 'e8c035d90ffdc278535c28ff618954dcfc7ba90f9aca036c18ff8c32ce8060c3'),
  ('ur.jalandhry', 3, 66, 359, 'دیکھو ایسی بات میں تو تم نے جھگڑا کیا ہی تھا جس کا تمہیں کچھ علم تھا بھی مگر ایسی بات میں کیوں جھگڑتے ہو جس کا تمہیں کچھ بھی علم نہیں اور خدا جانتا ہے اور تم نہیں جانتے', NULL, NULL, '0adc387a554c6bfd6d1d5f358806d5427a77789201613f73ed5083e832a29af5'),
  ('ur.jalandhry', 3, 67, 360, 'ابراہیم نہ تو یہودی تھے اور نہ عیسائی بلکہ سب سے بے تعلق ہو کر ایک (خدا) کے ہو رہے تھے اور اسی کے فرماں بردار تھے اور مشرکوں میں نہ تھے', NULL, NULL, 'a01506699380809c2df30b0a26805fa223b6b7232afb39b45f40c85e830bb4c9'),
  ('ur.jalandhry', 3, 68, 361, 'ابراہیم سے قرب رکھنے والے تو وہ لوگ ہیں جو ان کی پیروی کرتے ہیں اور پیغمبر (آخرالزمان) اور وہ لوگ جو ایمان لائے ہیں اور خدا مومنوں کا کارساز ہے', NULL, NULL, 'e117b5435b74675d6e9efadb1b8496846893a36cc1986f660e5fc7e5d57e35f9'),
  ('ur.jalandhry', 3, 69, 362, '(اے اہل اسلام) بعضے اہلِ کتاب اس بات کی خواہش رکھتے ہیں کہ تم کو گمراہ کر دیں مگر یہ (تم کو کیا گمراہ کریں گے) اپنے آپ کو ہی گمراہ کر رہے ہیں اور نہیں جانتے', NULL, NULL, '7c4defc91d44be3b94ab5b97cc940ab44c2fd5ec83d173b2baa2d41b4ba090bd'),
  ('ur.jalandhry', 3, 70, 363, 'اے اہلِ کتاب تم خدا کی آیتوں سے کیوں انکار کرتے ہو اور تم (تورات کو) مانتے تو ہو', NULL, NULL, 'd37c4cee09a8d496624720e7b199f693f7d0db6d8ccad26dfe11daed76c65676'),
  ('ur.jalandhry', 3, 71, 364, 'اے اہلِ کتاب تم سچ کو جھوٹ کے ساتھ خلط ملط کیوں کرتے ہو اور حق کو کیوں چھپاتے ہو اور تم جانتے بھی ہو', NULL, NULL, '2ff2cf1f6fd466dd9d96c66763ae59ef8bba669e500b5471e477edcb8ddd98f1'),
  ('ur.jalandhry', 3, 72, 365, 'اور اہلِ کتاب ایک دوسرے سے کہتے ہیں کہ جو (کتاب) مومنوں پر نازل ہوئی ہے اس پر دن کے شروع میں تو ایمان لے آیا کرو اور اس کے آخر میں انکار کر دیا کرو تاکہ وہ (اسلام سے) برگشتہ ہو جائیں', NULL, NULL, 'ad4c2ce7414d5c730ad6c7f21eae96434aaa01414d1dadbba949b70c67d30614'),
  ('ur.jalandhry', 3, 73, 366, 'اور اپنے دین کے پیرو کے سوا کسی اور کے قائل نہ ہونا (اے پیغمبر) کہہ دو کہ ہدایت تو خدا ہی کی ہدایت ہے (وہ یہ بھی کہتے ہیں) یہ بھی (نہ ماننا) کہ جو چیز تم کو ملی ہے ویسی کسی اور کو ملے گی یا وہ تمہیں خدا کے روبرو قائل معقول کر سکیں گے یہ بھی کہہ دو کہ بزرگی خدا ہی کے ہاتھ میں ہے وہ جسے چاہتا ہے دیتا ہے اور خدا کشائش والا (اور) علم والا ہے', NULL, NULL, '15e0d8d13f0d641ead8bc1afae65820efa134c18213f5b5a8a729928dd7e6ae4'),
  ('ur.jalandhry', 3, 74, 367, 'وہ اپنی رحمت سے جس کو چاہتا ہے خاص کر لیتا ہے اور خدا بڑے فضل کا مالک ہے', NULL, NULL, '6d79d48d704acadda24d8cd5ed38229f5261a8aa070ce961235500b07d5855c4'),
  ('ur.jalandhry', 3, 75, 368, 'اور اہلِ کتاب میں سے کوئی تو ایسا ہے کہ اگر تم اس کے پاس (روپوں کا) ڈھیر امانت رکھ دو تو تم کو (فوراً) واپس دے دے اور کوئی اس طرح کا ہے کہ اگر اس کے پاس ایک دینار بھی امانت رکھو تو جب تک اس کے سر پر ہر وقت کھڑے نہ رہو تمہیں دے ہی نہیں یہ اس لیے کہ وہ کہتے ہیں کہ امیوں کے بارے میں ہم سے مواخذہ نہیں ہوگا یہ خدا پر محض جھوٹ بولتے ہیں اور (اس بات کو) جانتے بھی ہیں', NULL, NULL, '5fbc3a3fc1d154009364674e8157753c5c67fbb69b6ef603c1cc534bcbb765c2'),
  ('ur.jalandhry', 3, 76, 369, 'ہاں جو شخص اپنے اقرار کو پورا کرے اور (خدا سے) ڈرے تو خدا ڈرنے والوں کو دوست رکھتا ہے', NULL, NULL, 'a50b093e907a0c45d17c29172b5e48c747dad0229cf489c463a8c7b3974d332a'),
  ('ur.jalandhry', 3, 77, 370, 'جو لوگ خدا کے اقراروں اور اپنی قسموں (کو بیچ ڈالتے ہیں اور ان) کے عوض تھوڑی سی قیمت حاصل کرتے ہیں ان کا آخرت میں کچھ حصہ نہیں ان سے خدا نہ تو کلام کرے گا اور نہ قیامت کے روز ان کی طرف دیکھے گا اور نہ ان کو پاک کرے گا اور ان کو دکھ دینے والا عذاب ہوگا', NULL, NULL, '28bc604975319168ae1864fb4e7e9fe5606c22686bc532378e6653dc8acfe475'),
  ('ur.jalandhry', 3, 78, 371, 'اور ان (اہلِ کتاب) میں بعضے ایسے ہیں کہ کتاب (تورات) کو زبان مروڑ مروڑ کر پڑھتے ہیں تاکہ تم سمجھو کہ جو کچھ وہ پڑھتے ہیں کتاب میں سے ہے حالانکہ وہ کتاب میں سے نہیں ہے اور کہتے ہیں کہ وہ خدا کی طرف سے (نازل ہوا) ہے حالانکہ وہ خدا کی طرف سے نہیں ہوتا اور خدا پر جھوٹ بولتے ہیں اور (یہ بات) جانتے بھی ہیں', NULL, NULL, '390774de44f08cbc40d0ecb6ff651a1ea26a7fb48a34a048d925b21530028fb5'),
  ('ur.jalandhry', 3, 79, 372, 'کسی آدمی کو شایاں نہیں کہ خدا تو اسے کتاب اور حکومت اور نبوت عطا فرمائے اور وہ لوگوں سے کہے کہ خدا کو چھوڑ کر میرے بندے ہو جاؤ بلکہ (اس کو یہ کہنا سزاوار ہے کہ اے اہلِ کتاب) تم (علمائے) ربانی ہو جاؤ کیونکہ تم کتابِ (خدا) پڑھتے پڑھاتے رہتے ہو', NULL, NULL, 'af79d1aea7db680c45ff7118152880dfc24cadbfc14707fe102b07795d9d979c'),
  ('ur.jalandhry', 3, 80, 373, 'اور اس کو یہ بھی نہیں کہنا چاہیے کہ تم فرشتوں اور پیغمبروں کو خدا بنالو بھلا جب تم مسلمان ہو چکے تو کیا اسے زیبا ہے کہ تمہیں کافر ہونے کو کہے', NULL, NULL, '4e1825a38a5d761334cc0ea7fe6f969621a246821f4823acc2b98155bc8e0032'),
  ('ur.jalandhry', 3, 81, 374, 'اور جب خدا نے پیغمبروں سے عہد لیا کہ جب میں تم کو کتاب اور دانائی عطا کروں پھر تمہارے پاس کوئی پیغمبر آئے جو تمہاری کتاب کی تصدیق کرے تو تمھیں ضرور اس پر ایمان لانا ہوگا اور ضرور اس کی مدد کرنی ہوگی اور (عہد لینے کے بعد) پوچھا کہ بھلا تم نے اقرار کیا اور اس اقرار پر میرا ذمہ لیا (یعنی مجھے ضامن ٹہرایا) انہوں نے کہا (ہاں) ہم نے اقرار کیا (خدا نے) فرمایا کہ تم (اس عہد وپیمان کے) گواہ رہو اور میں بھی تمہارے ساتھ گواہ ہوں', NULL, NULL, '5da8b7ab831e593793d6e107d1b0324b5a8f7b443d5f41c4ae8a1684b15d0df3'),
  ('ur.jalandhry', 3, 82, 375, 'تو جو اس کے بعد پھر جائیں وہ بد کردار ہیں', NULL, NULL, '049b610ed688b45cb2eb864ab34559e1288c40af72ae61eb2999d6cdf3639e8d'),
  ('ur.jalandhry', 3, 83, 376, 'کیا یہ (کافر) خدا کے دین کے سوا کسی اور دین کے طالب ہیں حالانکہ سب اہلِ آسمان و زمین خوشی یا زبردستی سے خدا کے فرماں بردار ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں', NULL, NULL, 'd92d90c1540bee46a6918decf3e533250af6cdda1692eafe050efed43fd2d9ed'),
  ('ur.jalandhry', 3, 84, 377, 'کہو کہ ہم خدا پر ایمان لائے اور جو کتاب ہم پر نازل ہوئی اور جو صحیفے ابراہیم اور اسماعیل اور اسحٰق اور یعقوب اور ان کی اولاد پر اترے اور جو کتابیں موسیٰ اور عیسیٰ اور دوسرے انبیاء کو پروردگار کی طرف سے ملیں سب پر ایمان لائے ہم ان پیغمبروں میں سے کسی میں کچھ فرق نہیں کرتے اور ہم اسی (خدائے واحد) کے فرماں بردار ہیں', NULL, NULL, '5be6ea77644aedf90caf2dd55acbd2388cc92c7ce8a4748a02a6fb044e9deb28'),
  ('ur.jalandhry', 3, 85, 378, 'اور جو شخص اسلام کے سوا کسی اور دین کا طالب ہوگا وہ اس سے ہرگز قبول نہیں کیا جائے گا اور ایسا شخص آخرت میں نقصان اٹھانے والوں میں ہوگا', NULL, NULL, '64a8d89b291c3f49665fb819958e812f3652063ba6eaf89d7d7121285b76b864'),
  ('ur.jalandhry', 3, 86, 379, 'خدا ایسے لوگوں کو کیونکر ہدایت دے جو ایمان لانے کے بعد کافر ہوگئے اور (پہلے) اس بات کی گواہی دے چکے کہ یہ پیغمبر برحق ہے اور ان کے پاس دلائل بھی آگئے اور خدا بے انصافوں کو ہدایت نہیں دیتا', NULL, NULL, '7c261ac51e3d2b44ca2a156f1b1fdf6596a4e29f15e59d682530e8a640f3edd4'),
  ('ur.jalandhry', 3, 87, 380, 'ان لوگوں کی سزا یہ ہے کہ ان پر خدا کی اور فرشتوں کی اور انسانوں کی سب کی لعنت ہو', NULL, NULL, 'ff02a3f9fb70f93bd65f57e3fd966b60108f1f0e18adae2dc96dfaa04d535a99'),
  ('ur.jalandhry', 3, 88, 381, 'ہمیشہ اس لعنت میں (گرفتار) رہیں گے ان سے نہ تو عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دے جائے گی', NULL, NULL, '8b207debe294175f6067600337b2877fa9db452b04c2d9d06f4639ba9048031a'),
  ('ur.jalandhry', 3, 89, 382, 'ہاں جنہوں نے اس کے بعد توبہ کی اور اپنی حالت درست کر لی تو خدا بخشنے والا مہربان ہے', NULL, NULL, 'ddef29463b3d090808df19e04bf444c4f0397cce3d736f85d161f9ee4da19c8d'),
  ('ur.jalandhry', 3, 90, 383, 'جو لوگ ایمان لانے کے بعد کافر ہو گئے پھر کفر میں بڑھتے گئے ایسوں کی توبہ ہرگز قبول نہ ہوگی اور یہ لوگ گمراہ ہیں', NULL, NULL, '1e41d8356e330f0810b563b00a569fc28d0527b928ee16334e3c6ccb23778a4b'),
  ('ur.jalandhry', 3, 91, 384, 'جو لوگ کافر ہوئے اور کفر ہی کی حالت میں مر گئے وہ اگر (نجات حاصل کرنی چاہیں اور) بدلے میں زمین بھر کر سونا دیں تو ہرگز قبول نہ کیا جائے گا ان لوگوں کو دکھ دینے والا عذاب ہو گا اور ان کی کوئی مدد نہیں کرے گا', NULL, NULL, '67be06e1edfd7482506a5f827fa29b05fe1727314249999b132f5e628b64e391'),
  ('ur.jalandhry', 3, 92, 385, '(مومنو!) جب تک تم ان چیزوں میں سے جو تمھیں عزیز ہیں (راہِ خدا میں) صرف نہ کرو گے کبھی نیکی حاصل نہ کر سکو گے اور جو چیز تم صرف کرو گے خدا اس کو جانتا ہے', NULL, NULL, '0d7f2335a1bf17bb81cada8051ea5a5220cdf3dc8b3995418f1fce98fa10aa14'),
  ('ur.jalandhry', 3, 93, 386, 'بنی اسرائیل کے لیے (تورات کے نازل ہونے سے) پہلے کھانے کی تمام چیزیں حلال تھیں بجز ان کے جو یعقوب نے خود اپنے اوپر حرام کر لی تھیں کہہ دو کہ اگر سچے ہو تو تورات لاؤ اور اسے پڑھو (یعنی دلیل پیش کرو)', NULL, NULL, 'c85acd0e566809670cb80a82e874eab15748158f17ee9476281636ce6496eaa8'),
  ('ur.jalandhry', 3, 94, 387, 'جو اس کے بعد بھی خدا پر جھوٹے افترا کریں تو ایسے لوگ ہی بےانصاف ہیں', NULL, NULL, 'da49584fc1bd614fcb2f4c8c1160557af3821f9ad53b6a494447f736eca9494c'),
  ('ur.jalandhry', 3, 95, 388, 'کہہ دو کہ خدا نے سچ فرمایا دیا پس دین ابراہیم کی پیروی کرو جو سب سے بےتعلق ہو کر ایک (خدا) کے ہو رہے تھے اور مشرکوں سے نہ تھے', NULL, NULL, '2b75d1b6366dbf24d5b3132180b253fbaefa91aa4ac237853df1d62112a38ec2'),
  ('ur.jalandhry', 3, 96, 389, 'پہلا گھر جو لوگوں (کے عبادت کرنے) کے لیے مقرر کیا گیا تھا وہی ہے جو مکے میں ہے بابرکت اور جہاں کے لیے موجبِ ہدایت', NULL, NULL, 'd2fd7728e77cbb9dfb55e7232ae4a094d3dcb1748645ce4f08378499994d36c6'),
  ('ur.jalandhry', 3, 97, 390, 'اس میں کھلی ہوئی نشانیاں ہیں جن میں سے ایک ابراہیم کے کھڑے ہونے کی جگہ ہے جو شخص اس (مبارک) گھر میں داخل ہوا اس نے امن پا لیا اور لوگوں پر خدا کا حق (یعنی فرض) ہے کہ جو اس گھر تک جانے کا مقدور رکھے وہ اس کا حج کرے اور جو اس حکم کی تعمیل نہ کرے گا تو خدا بھی اہلِ عالم سے بے نیاز ہے', NULL, NULL, 'd2950ef8629e3818fdf8823f894506481cf736588278c6d35d91019806c13220'),
  ('ur.jalandhry', 3, 98, 391, 'کہو کہ اہلِ کتاب! تم خدا کی آیتوں سے کیوں کفر کرتے ہو اور خدا تمہارے سب اعمال سے باخبر ہے', NULL, NULL, '6e85fcd53cc8fea58429fa193cddf25e400f6ea115c98f906954be7b8dad502e'),
  ('ur.jalandhry', 3, 99, 392, 'کہو کہ اہلِ کتاب تم مومنوں کو خدا کے رستے سے کیوں روکتے ہو اور باوجود یہ کہ تم اس سے واقف ہو اس میں کجی نکالتے ہو اور خدا تمھارے کاموں سے بےخبر نہیں', NULL, NULL, '832a5b11938eedf2241ba4663efb2a0a2404107a16ba61bbdd9d9a5792e70809'),
  ('ur.jalandhry', 3, 100, 393, 'مومنو! اگر تم اہلِ کتاب کے کسی فریق کا کہا مان لو گے تو وہ تمھیں ایمان لانے کے بعد کافر بنا دیں گے', NULL, NULL, '548d005cfe9021ca13a1d4d02569f3b4d5d2cd60a8970560198bbea6408dc2dd'),
  ('ur.jalandhry', 3, 101, 394, 'اور تم کیونکر کفر کرو گے جبکہ تم کو خدا کی آیتیں پڑھ پڑھ کر سنائی جاتی ہیں اور تم میں اس کے پیغمبر موجود ہیں اور جس نے خدا (کی ہدایت کی رسی) کو مضبوط پکڑ لیا وہ سیدھے رستے لگ گیا', NULL, NULL, '70bdfbfd266a90a90d28ea7fc9a6de9736ad11c37060833f09ee8ac126c2f9bd'),
  ('ur.jalandhry', 3, 102, 395, 'مومنو! خدا سے ڈرو جیسا کہ اس سے ڈرنے کا حق ہے اور مرنا تو مسلمان ہی مرنا', NULL, NULL, '597043b507dc6bd2b7d86dd4ec7b6720c04968c02cf256906004c05fcc3e02df'),
  ('ur.jalandhry', 3, 103, 396, 'اور سب مل کر خدا کی (ہدایت کی رسی) کو مضبوط پکڑے رہنا اور متفرق نہ ہونا اور خدا کی اس مہربانی کو یاد کرو جب تم ایک دوسرے کے دشمن تھے تو اس نے تمہارے دلوں میں الفت ڈال دی اور تم اس کی مہربانی سے بھائی بھائی ہوگئے اور تم آگ کے گڑھے کے کنارے تک پہنچ چکے تھے تو خدا نے تم کو اس سے بچا لیا اس طرح خدا تم کو اپنی آیتیں کھول کھول کر سناتا ہے تاکہ تم ہدایت پاؤ', NULL, NULL, '7dc5f9470e084636584d5a26b2345ebbd63769192bfb09aa8cebb0624dea61bc'),
  ('ur.jalandhry', 3, 104, 397, 'اور تم میں ایک جماعت ایسی ہونی چاہیئے جو لوگوں کو نیکی کی طرف بلائے اور اچھے کام کرنے کا حکم دے اور برے کاموں سے منع کرے یہی لوگ ہیں جو نجات پانے والے ہیں', NULL, NULL, '0d36479147343d9bc56befdf4ed6cd39ed77b087e84cd255723272c0e66a2a09'),
  ('ur.jalandhry', 3, 105, 398, 'اور ان لوگوں کی طرح نہ ہونا جو متفرق ہو گئے اور احکام بین آنے کے بعد ایک دوسرےسے (خلاف و) اختلاف کرنے لگے یہ وہ لوگ ہیں جن کو قیامت کے دن بڑا عذاب ہوگا', NULL, NULL, '4e431ebd21352cc3c4aac2c38094ff79b0014e66e96a7eb4e18723688f5186ec'),
  ('ur.jalandhry', 3, 106, 399, 'جس دن بہت سے منہ سفید ہوں گے اور بہت سے منہ سیاہ تو جن لوگوں کے منہ سیاہ ہوں گے (ان سے خدا فرمائے گا) کیا تم ایمان لا کر کافر ہوگئے تھے؟ سو (اب) اس کفر کے بدلے عذاب (کے مزے) چکھو', NULL, NULL, '338a36e3d5c5bdbf9126ee340be57abe47c61e79d09cd86bce8fd3da26fcfa48'),
  ('ur.jalandhry', 3, 107, 400, 'اور جن لوگوں کے منہ سفید ہوں گے وہ خدا کی رحمت (کے باغوں) میں ہوں گے اور ان میں ہمیشہ رہیں گے', NULL, NULL, '335df7cbc72b033588793d5b4eb643bc0349c76f4afd462292cf63caca37ec50')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 3, 108, 401, 'یہ خدا کی آیتیں ہیں جو ہم تم کو صحت کے ساتھ پڑھ کر سناتے ہیں اور خدا اہلِ عالم پر ظلم نہیں کرنا چاہتا', NULL, NULL, 'e1e7e81f6c4a82af7bcb1955af21c4f59d8ae2d35e462065cca17dd1a9a75f82'),
  ('ur.jalandhry', 3, 109, 402, 'اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے اور سب کاموں کا رجوع (اور انجام) خدا ہی کی طرف ہے', NULL, NULL, '2399d99f0c97fed92d3315a0f8179c2a6cbabfb4cb9e514c854106b134a07f99'),
  ('ur.jalandhry', 3, 110, 403, '(مومنو) جتنی امتیں (یعنی قومیں) لوگوں میں پیدا ہوئیں تم ان سب سے بہتر ہو کہ نیک کام کرنے کو کہتے ہو اور برے کاموں سے منع کرتے ہو اور خدا پر ایمان رکھتے ہو اور اگر اہلِ کتاب بھی ایمان لے آتے تو ان کے لیے بہت اچھا ہوتا ان میں ایمان لانے والے بھی ہیں (لیکن تھوڑے) اور اکثر نافرمان ہیں', NULL, NULL, '6fbcdf7116b0078d47dc57b37c7aa77d88e1456f0229347247da9adf5b9f7cc7'),
  ('ur.jalandhry', 3, 111, 404, 'اور یہ تمہیں خفیف سی تکلیف کے سوا کچھ نقصان نہیں پہنچا سکیں گے اور اگر تم سے لڑیں گے تو پیٹھ پھیر کر بھاگ جائیں گے پھر ان کو مدد بھی (کہیں سے) نہیں ملے گی', NULL, NULL, 'bccd4201dcf20d419f5838801b8c417f610fa316561455d41f59cec6738e5b0c'),
  ('ur.jalandhry', 3, 112, 405, 'یہ جہاں نظر آئیں گے ذلت (کو دیکھو گے کہ) ان سے چمٹ رہی ہے بجز اس کے کہ یہ خدا اور (مسلمان) لوگوں کی پناہ میں آ جائیں اور یہ لوگ خدا کے غضب میں گرفتار ہیں اور ناداری ان سے لپٹ رہی ہے یہ اس لیے کہ خدا کی آیتوں سے انکار کرتےتھے اور (اس کے) پیغمبروں کو ناحق قتل کر دیتے تھے یہ اس لیے کہ یہ نافرمانی کیے جاتے اور حد سے بڑھے جاتے تھے', NULL, NULL, '3ef7206cec4a601272368010a164abd70b08a8c398ad3f4882a8217727f018a3'),
  ('ur.jalandhry', 3, 113, 406, 'یہ بھی سب ایک جیسے نہیں ہیں ان اہلِ کتاب میں کچھ لوگ (حکمِ خدا پر) قائم بھی ہیں جو رات کے وقت خدا کی آیتیں پڑھتے اور (اس کے آگے) سجدہ کرتے ہیں', NULL, NULL, '2fef7f798601a331125106661bc1b72f5a15b4f0c79da46b3f0ace5a758d12d4'),
  ('ur.jalandhry', 3, 114, 407, '(اور) خدا پر اور روز آخرت پر ایمان رکھتے اور اچھے کام کرنےکو کہتے اور بری باتوں سے منع کرتےاور نیکیوں پر لپکتے ہیں اور یہی لوگ نیکوکار ہیں', NULL, NULL, '5d5a9bc0045d41b90e2f4be0d3b44ddec3a91894f6a566221d17ee2f45463e2f'),
  ('ur.jalandhry', 3, 115, 408, 'اور یہ جس طرح کی نیکی کریں گے اس کی ناقدری نہیں کی جائے گی اور خدا پرہیزگاروں کو خوب جانتا ہے', NULL, NULL, '15df1c94e24a384d73fec551c908fa0fe0e36b72002ffd881b805a284d468fc9'),
  ('ur.jalandhry', 3, 116, 409, 'جو لوگ کافر ہیں ان کے مال اور اولاد خدا کے غضب کو ہرگز نہیں ٹال سکیں گے اور یہ لوگ اہلِ دوزخ ہیں کہ ہمیشہ اسی میں رہیں گے', NULL, NULL, 'f837dd53c93d8137c090249111bdc9b31990cb1a8e5217c5cf0e02f884419381'),
  ('ur.jalandhry', 3, 117, 410, 'یہ جو مال دنیا کی زندگی میں خرچ کرتے ہیں اس کی مثال ہوا کی سی ہے جس میں سخت سردی ہو اور وہ ایسے لوگوں کی کھیتی پر جو اپنے آپ پر ظلم کرتے تھے چلے اور اسے تباہ کر دے اور خدا نے ان پر کچھ ظلم نہیں کیا بلکہ یہ خود اپنے اوپر ظلم کر رہے ہیں', NULL, NULL, '78e4680d59ad0731c5b5fe036e5fef60bee115952adab1e10dbbfa90ebca8f2f'),
  ('ur.jalandhry', 3, 118, 411, 'مومنو! کسی غیر (مذہب کے آدمی) کو اپنا رازداں نہ بنانا یہ لوگ تمہاری خرابی اور (فتنہ انگیزی کرنے) میں کسی طرح کی کوتاہی نہیں کرتے اور چاہتے ہیں کہ (جس طرح ہو) تمہیں تکلیف پہنچے ان کی زبانوں سے تو دشمنی ظاہر ہوہی چکی ہے اور جو (کینے) ان کے سینوں میں مخفی ہیں وہ کہیں زیادہ ہیں اگر تم عقل رکھتے ہو تو ہم نے تم کو اپنی آیتیں کھول کھول کر سنا دی ہیں', NULL, NULL, 'a582136ea50d7d3c7bf67eaa1edc7d36c8fae5fd45145c638caa668b1c39e29c'),
  ('ur.jalandhry', 3, 119, 412, 'دیکھو تم ایسے (صاف دل) لوگ ہو کہ ان لوگوں سے دوستی رکھتے ہو حالانکہ وہ تم سے دوستی نہیں رکھتے اور تم سب کتابوں پر ایمان رکھتے ہو (اور وہ تمہاری کتاب کو نہیں مانتے) اور جب تم سے ملتے ہیں تو کہتے ہیں ہم ایمان لے آئے اور جب الگ ہوتے ہیں تو تم پر غصے کے سبب انگلیاں کاٹ کاٹ کھاتے ہیں (ان سے) کہہ دو کہ (بدبختو) غصے میں مر جاؤ خدا تمہارے دلوں کی باتوں سے خوب واقف ہے', NULL, NULL, '0835fd10ac78750735fcb0987f7c9094150da63423a7c8dbc9946009fd6527da'),
  ('ur.jalandhry', 3, 120, 413, 'اگر تمہیں آسودگی حاصل ہو تو ان کو بری لگتی ہے اور اگر رنج پہنچے تو خوش ہوتے ہیں اور اگر تم تکلیفوں کی برداشت اور (ان سے) کنارہ کشی کرتے رہو گے تو ان کا فریب تمھیں کچھ بھی نقصان نہ پہنچا سکے گا یہ جو کچھ کرتے ہیں خدا اس پر احاطہ کیے ہوئے ہے', NULL, NULL, '9720e567bf800fb18885ac40e6bcfb1501e5e7e08d5aef82bd5e01f89a12e01d'),
  ('ur.jalandhry', 3, 121, 414, 'اور (اس وقت کو یاد کرو) جب تم صبح کو اپنے گھر روانہ ہو کر ایمان والوں کو لڑائی کے لیے مورچوں پر (موقع بہ موقع) متعین کرنے لگے اور خدا سب کچھ سنتا اور جانتا ہے', NULL, NULL, 'dcb9f5fa3dfca5815dc343c1884438b942166a942beea550ae11b45f212b942e'),
  ('ur.jalandhry', 3, 122, 415, 'اس وقت تم میں سے دو جماعتوں نے جی چھوڑ دینا چاہا مگر خدا ان کا مددگار تھا اور مومنوں کو خدا ہی پر بھروسہ رکھنا چاہیئے', NULL, NULL, '37d6d3b7145cb84651cf37a939d3e17ecc594063314097e468d0c1c4a6d2e5c9'),
  ('ur.jalandhry', 3, 123, 416, 'اور خدا نے جنگِ بدر میں بھی تمہاری مدد کی تھی اور اس وقت بھی تم بے سرو وسامان تھے پس خدا سے ڈرو (اور ان احسانوں کو یاد کرو) تاکہ شکر کرو', NULL, NULL, '3ec6b9fc1604e479f2898470f48ea22c0083bdcb39b63393f3a44422e58a8358'),
  ('ur.jalandhry', 3, 124, 417, 'جب تم مومنوں سے یہ کہہ (کر ان کے دل بڑھا) رہے تھے کہ کیا یہ کافی نہیں کہ پروردگار تین ہزار فرشتے نازل کر کے تمہیں مدد دے', NULL, NULL, '7fcb787884829fb8154635bd1922658e10a0283ca40386dedf4c1fcc9d186755'),
  ('ur.jalandhry', 3, 125, 418, 'ہاں اگر تم دل کو مضبوط رکھو اور (خدا سے) ڈرتے رہو اور کافر تم پر جوش کے ساتھ دفعتہً حملہ کردیں تو پروردگار پانچ ہزار فرشتے جن پر نشان ہوں گے تمہاری مدد کو بھیجے گا', NULL, NULL, '7c10d23dc18403a538bf1b21440c0ef80f541b88a335a2106a67178f18dfa29b'),
  ('ur.jalandhry', 3, 126, 419, 'اور اس مدد کو خدا نے تمھارے لیے (ذریعہٴ) بشارت بنایا یعنی اس لیے کہ تمہارے دلوں کو اس سے تسلی حاصل ہو ورنہ مدد تو خدا ہی کی ہے جو غالب (اور) حکمت والا ہے', NULL, NULL, 'c9c5e709d520f36eee5628fecb7ba2b4c5a8f51260d3efcdea03eee3ca3ef1e2'),
  ('ur.jalandhry', 3, 127, 420, '(یہ خدا نے) اس لیے (کیا) کہ کافروں کی ایک جماعت کو ہلاک یا انہیں ذلیل ومغلوب کر دے کہ (جیسے آئے تھے ویسے ہی) ناکام واپس جائیں', NULL, NULL, 'eecf5741d29d75bc9efc431e88781b9d2f72ed41f799d74c706466b40953d658'),
  ('ur.jalandhry', 3, 128, 421, '(اے پیغمبر) اس کام میں تمہارا کچھ اختیار نہیں (اب دو صورتیں ہیں) یا خدا انکے حال پر مہربانی کرے یا انہیں عذاب دے کہ یہ ظالم لوگ ہیں', NULL, NULL, '9a66e6c8b4adc5fe22d0acfb8698bc01eb64b171e548f4f4a8a2cd4b0b27e9d0'),
  ('ur.jalandhry', 3, 129, 422, 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب خدا ہی کا ہے وہ جسے چاہے بخش دے اور جسے چاہے عذاب کرے اور خدا بخشنے والا مہربان ہے', NULL, NULL, 'f995a6240acb588d6b6ebba5e61182dd4f05ebe0504be377295ede73bb5ce68d'),
  ('ur.jalandhry', 3, 130, 423, 'اےایمان والو! دگنا چوگنا سود نہ کھاؤ اور خدا سے ڈرو تاکہ نجات حاصل کرو', NULL, NULL, '8aaf85e62b93f9f56fefc4ba836c36a7d52146b36de32451c90621539e905597'),
  ('ur.jalandhry', 3, 131, 424, 'اور (دوزخ کی) آگ سے بچو جو کافروں کے لیے تیار کی گئی ہے', NULL, NULL, '082af85d7751df3ef4bb49bf02762d811bcf1b5cb46cd539786a426040cf49c0'),
  ('ur.jalandhry', 3, 132, 425, 'اور خدا اور اس کے رسول کی اطاعت کرو تاکہ تم پر رحمت کی جائے', NULL, NULL, '2eb1c197486f4b5105208d87337c652d9cad7cfd48f1add1c62eec0cb0902cb7'),
  ('ur.jalandhry', 3, 133, 426, 'اپنے پروردگار کی بخشش اور بہشت کی طرف لپکو جس کا عرض آسمان اور زمین کے برابر ہے اور جو (خدا سے) ڈرنے والوں کے لیے تیار کی گئی ہے', NULL, NULL, '4323d8a8971f3d00783e2a4ef5d577799e0e771388c7c03aec1ee5fe9ce4618e'),
  ('ur.jalandhry', 3, 134, 427, 'جو آسودگی اور تنگی میں (اپنا مال خدا کی راہ میں) خرچ کرتےہیں اور غصے کو روکتے اور لوگوں کے قصور معاف کرتے ہیں اور خدا نیکو کاروں کو دوست رکھتا ہے', NULL, NULL, '7345ef135eef550b5e76272b49a783c0d48d12b73ad8b041c345b971c5260cf8'),
  ('ur.jalandhry', 3, 135, 428, 'اور وہ کہ جب کوئی کھلا گناہ یا اپنے حق میں کوئی اور برائی کر بیٹھتے ہیں تو خدا کو یاد کرتے اور اپنے گناہوں کی بخشش مانگتے ہیں اور خدا کے سوا گناہ بخش بھی کون سکتا ہے؟ اور جان بوجھ کر اپنے افعال پر اڑے نہیں رہتے', NULL, NULL, '34272d30b3ac6c32cd54bc07cb1cc5a7c47d08d00d03ae6bd9447f90cd2bb89d'),
  ('ur.jalandhry', 3, 136, 429, 'ایسے ہی لوگوں کا صلہ پروردگار کی طرف سے بخشش اور باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں (اور) وہ ان میں ہمیشہ بستے رہیں گے اور (اچھے) کام کرنے والوں کا بدلہ بہت اچھا ہے', NULL, NULL, 'f7a9278f145d863bb6e3a11dd2a144d19e55e071969fb5123a2613d89028001d'),
  ('ur.jalandhry', 3, 137, 430, 'تم لوگوں سے پہلے بھی بہت سے واقعات گزر چکے ہیں تو تم زمین کی سیر کرکے دیکھ لو کہ جھٹلانے والوں کا کیسا انجام ہوا', NULL, NULL, '0ae93f88898114367aa912b3c346848d87e75d92cb82484ed40c477fdc5b3af1'),
  ('ur.jalandhry', 3, 138, 431, 'یہ (قرآن) لوگوں کے لیے بیان صریح اور اہلِ تقویٰ کے لیے ہدایت اور نصیحت ہے', NULL, NULL, '6d5828c382a1be1f4e2adf0027f189e25909f5485226b7f55b919303f627ec19'),
  ('ur.jalandhry', 3, 139, 432, 'اور (دیکھو) بے دل نہ ہونا اور نہ کسی طرح کا غم کرنا اگر تم مومن (صادق) ہو تو تم ہی غالب رہو گے', NULL, NULL, '77706a5bd588b0db7f1246afff5b4545304ea8f1928dff96a7009b3e11ba0db0'),
  ('ur.jalandhry', 3, 140, 433, 'اگر تمہیں زخم (شکست) لگا ہے تو ان لوگوں کو بھی ایسا زخم لگ چکا ہے اور یہ دن ہیں کہ ہم ان کو لوگوں میں بدلتے رہتے ہیں اور اس سے یہ بھی مقصود تھا کہ خدا ایمان والوں کو متمیز کر دے اور تم میں سے گواہ بنائے اور خدا بےانصافوں کو پسند نہیں کرتا', NULL, NULL, 'be5df8d9e2f6d4dffe9cac63be4a8fdf559031eb641dd4ad9e149554268766a5'),
  ('ur.jalandhry', 3, 141, 434, 'اور یہ بھی مقصود تھا کہ خدا ایمان والوں کو خالص (مومن) بنا دے اور کافروں کو نابود کر دے', NULL, NULL, '4b2d0f68f3888e9a14481fd7da384f92e5c9b9d07aba402f15a8dd24118a2826'),
  ('ur.jalandhry', 3, 142, 435, 'کیا تم یہ سمجھتے ہو کہ (بےآزمائش) بہشت میں جا داخل ہو گے حالانکہ ابھی خدا نے تم میں سے جہاد کرنے والوں کو تو اچھی طرح معلوم کیا ہی نہیں اور (یہ بھی مقصود ہے) کہ وہ ثابت قدم رہنے والوں کو معلوم کرے', NULL, NULL, 'd1c0f889e5139726b5503d5be0c0dd83ccaa9f77a47a995787a2ff1d7c95a2ad'),
  ('ur.jalandhry', 3, 143, 436, 'اور تم موت (شہادت) کے آنے سے پہلے اس کی تمنا کیا کرتے تھے سو تم نے اس کو آنکھوں سے دیکھ لیا', NULL, NULL, '956789dcd8e94fdc7b227d5b34cc90265fd318b5c2383291b1281511ad548bab'),
  ('ur.jalandhry', 3, 144, 437, 'اور محمد (صلی الله علیہ وسلم) تو صرف (خدا کے) پیغمبر ہیں ان سے پہلے بھی بہت سے پیغمبر ہو گزرے ہیں بھلا اگر یہ مر جائیں یا مارے جائیں تو تم الٹے پاؤں پھر جاؤ؟ (یعنی مرتد ہو جاؤ؟) اور جو الٹے پاؤں پھر جائے گا تو خدا کا کچھ نقصان نہ کر سکے گا اور خدا شکر گزاروں کو (بڑا) ثواب دے گا', NULL, NULL, '4db0cfad29d753eaff3991c9b6ef3dba44884023eb2fd83fd3b68ee7263d409e'),
  ('ur.jalandhry', 3, 145, 438, 'اور کسی شخص میں طاقت نہیں کہ خدا کے حکم کے بغیر مر جائے (اس نے موت کا) وقت مقرر کر کے لکھ رکھا ہے اور جو شخص دنیا میں (اپنے اعمال کا) بدلہ چاہے اس کو ہم یہیں بدلہ دے دیں گے اور جو آخرت میں طالبِ ثواب ہو اس کو وہاں اجر عطا کریں گے اور ہم شکر گزاروں کو عنقریب (بہت اچھا) صلہ دیں گے', NULL, NULL, '952ac88bc34f571996715c02243418009cb1feff687feae81fc99f42d318a8fd'),
  ('ur.jalandhry', 3, 146, 439, 'اور بہت سے نبی ہوئے ہیں جن کے ساتھ ہو کر اکثر اہل الله (خدا کے دشمنوں سے) لڑے ہیں تو جو مصبتیں ان پر راہِ خدا میں واقع ہوئیں ان کے سبب انہوں نے نہ تو ہمت ہاری اور نہ بزدلی کی نہ (کافروں سے) دبے اور خدا استقلال رکھنے والوں کو دوست رکھتا ہے', NULL, NULL, 'a2f88572f8cbb00288f14aa69c8068c546f6a397bae37917f1212d7c75ae69a3'),
  ('ur.jalandhry', 3, 147, 440, 'اور (اس حالت میں) ان کے منہ سے کوئی بات نکلتی ہے تو یہی کہ اے پروردگار ہمارے گناہ اور زیادتیاں جو ہم اپنے کاموں میں کرتے رہے ہیں معاف فرما اور ہم کو ثابت قدم رکھ اور کافروں پر فتح عنایت فرما', NULL, NULL, '2f257131c4d8ce82dae8293825918cd4c965e8775c2b8a0137611ada192cafc4'),
  ('ur.jalandhry', 3, 148, 441, 'تو خدا نے ان کو دنیا میں بھی بدلہ دیا اور آخرت میں بھی بہت اچھا بدلہ (دے گا) اور خدا نیکو کاروں کو دوست رکھتا ہے', NULL, NULL, '18d12f4c66d147c28ffd1649a56440571d24d9ec64cd28d4c8c475068da28902'),
  ('ur.jalandhry', 3, 149, 442, 'مومنو! اگر تم کافروں کا کہا مان لو گے تو وہ تم کو الٹے پاؤں پھیر کر (مرتد کر) دیں گے پھر تم بڑے خسارے میں پڑ جاؤ گے', NULL, NULL, '03db9a8230bf13f693da5ec1d27fe205e76d98bd4dc556d3ce589699f2d824b7'),
  ('ur.jalandhry', 3, 150, 443, '(یہ تمہارے مددگار نہیں ہیں) بلکہ خدا تمہارا مددگار ہے اور وہ سب سے بہتر مددگار ہے', NULL, NULL, 'a41f046886cfe7ddd0927d59cde6c09a5d36f70115b2e48b4433a3404ae50e23'),
  ('ur.jalandhry', 3, 151, 444, 'ہم عنقریب کافروں کے دلوں میں تمہارا رعب بٹھا دیں گے کیونکہ یہ خدا کے ساتھ شرک کرتے ہیں جس کی اس نے کوئی بھی دلیل نازل نہیں کی اور ان کا ٹھکانہ دوزخ ہے وہ ظالموں کا بہت بُرا ٹھکانا ہے', NULL, NULL, 'a107a050739f28fff7ad7b5819f78d7ad0ec4a3086a65f5354a0eb29603501f7'),
  ('ur.jalandhry', 3, 152, 445, 'اور خدا نے اپنا وعدہ سچا کر دیا (یعنی) اس وقت جبکہ تم کافروں کو اس کے حکم سے قتل کر رہے تھے یہاں تک کہ جو تم چاہتے تھے خدا نے تم کو دکھا دیا اس کے بعد تم نے ہمت ہار دی اور حکم (پیغمبر) میں جھگڑا کرنے لگے اور اس کی نافرمانی کی بعض تو تم میں سے دنیا کے خواستگار تھے اور بعض آخرت کے طالب اس وقت خدا نے تم کو ان (کے مقابلے) سے پھیر (کر بھگا) دیا تاکہ تمہاری آزمائش کرے اور اس نے تمہارا قصور معاف کر دیا اور خدا مومنو پر بڑا فضل کرنے والا ہے', NULL, NULL, 'cfa094dbd80c207a366feda2295840f4e4658401a4245e93d071ac969f5f3143'),
  ('ur.jalandhry', 3, 153, 446, '(وہ وقت بھی یاد کرنے کے لائق ہے) جب تم لوگ دور بھاگے جاتے تھے اور کسی کو پیچھے پھر کر نہیں دیکھتے تھے اور رسول الله تم کو تمہارے پیچھے کھڑے بلا رہے تھے تو خدا نے تم کو غم پر غم پہنچایا تاکہ جو چیز تمہارے ہاتھ سے جاتی رہی یا جو مصیبت تم پر واقع ہوئی ہے اس سے تم اندوہ ناک نہ ہو اور خدا تمہارے سب اعمال سے خبردار ہے', NULL, NULL, '635e4c52817ca619471c4dd95abe821869a09919f73bc50edc5f7496193b28d9'),
  ('ur.jalandhry', 3, 154, 447, 'پھر خدا نے غم ورنج کے بعد تم پر تسلی نازل فرمائی (یعنی) نیند کہ تم میں سے ایک جماعت پر طاری ہو گئی اور کچھ لوگ جن کو جان کے لالے پڑ رہے تھے خدا کے بارے میں ناحق (ایام) کفر کے سے گمان کرتے تھے اور کہتے تھے بھلا ہمارے اختیار کی کچھ بات ہے؟ تم کہہ دو کہ بےشک سب باتیں خدا ہی کے اختیار میں ہیں یہ لوگ (بہت سی باتیں) دلوں میں مخفی رکھتے ہیں جو تم پر ظاہر نہیں کرتے تھے کہتے تھے کہ ہمارے بس کی بات ہوتی تو ہم یہاں قتل ہی نہ کیے جاتے کہہ دو کہ اگر تم اپنے گھروں میں بھی ہوتے تو جن کی تقدیر میں مارا جانا لکھا تھا وہ اپنی اپنی قتل گاہوں کی طرف ضرور نکل آتے اس سے غرض یہ تھی کہ خدا تمہارے سینوں کی باتوں کو آزمائے اور جو کچھ تمہارے دلوں میں ہے اس کو خالص اور صاف کر دے اور خدا دلوں کی باتوں سے خوب واقف ہے', NULL, NULL, '8336aa917bf7e5489c661f36f9f96ff1fcb89f185a460f3c6b9fcdcede2e9fba'),
  ('ur.jalandhry', 3, 155, 448, 'جو لوگ تم میں سے (اُحد کے دن) جبکہ (مومنوں اور کافروں کی) دو جماعتیں ایک دوسرے سے گتھ گئیں (جنگ سے) بھاگ گئے تو ان کے بعض افعال کے سبب شیطان نے ان کو پھسلا دیا مگر خدا نے ان کا قصور معاف کر دیا بےشک خدا بخشنے والا اور بردبار ہے', NULL, NULL, '24a6b0b0dd49af8e673f7ebcb9923cd6a0f605ccac98291cf7f99eb96dfbef14'),
  ('ur.jalandhry', 3, 156, 449, 'مومنو! ان لوگوں جیسے نہ ہونا جو کفر کرتے ہیں اور ان کے (مسلمان) بھائی جب (خدا کی راہ میں) سفر کریں (اور مر جائیں) یا جہاد کو نکلیں (اور مارے جائیں) تو ان کی نسبت کہتے ہیں کہ اگر وہ ہمارے پاس رہتے تو نہ مرتے اور نہ مارے جاتے۔ ان باتوں سے مقصود یہ ہے کہ خدا ان لوگوں کے دلوں میں افسوس پیدا کر دے اور زندگی اور موت تو خدا ہی دیتا ہے اور خدا تمہارے سب کاموں کو دیکھ رہا ہے', NULL, NULL, '56e35c4fde03c3396764a5b151524c4a6c86b80ec8ce1e679720790a98543619'),
  ('ur.jalandhry', 3, 157, 450, 'اور اگر تم خدا کے رستے میں مارے جاؤ یا مرجاؤ تو جو (مال و متاع) لوگ جمع کرتے ہیں اس سے خدا کی بخشش اور رحمت کہیں بہتر ہے', NULL, NULL, 'bf11a0734fc70158d980028c995f5d8d8b934542376f6dffd046c971c3225a4f'),
  ('ur.jalandhry', 3, 158, 451, 'اور اگر تم مرجاؤ یا مارے جاؤ خدا کے حضور میں ضرور اکھٹے کئے جاؤ گے', NULL, NULL, 'cece57e4bc682aadfef1fda5f6f405a65ab7c3e5b5cb0df247476d34f861a962'),
  ('ur.jalandhry', 3, 159, 452, '(اے محمدﷺ) خدا کی مہربانی سے تمہاری افتاد مزاج ان لوگوں کے لئے نرم واقع ہوئی ہے۔ اور اگر تم بدخو اور سخت دل ہوتے تو یہ تمہارے پاس سے بھاگ کھڑے ہوتے۔ تو ان کو معاف کردو اور ان کے لئے (خدا سے) مغفرت مانگو۔ اور اپنے کاموں میں ان سے مشورت لیا کرو۔ اور جب (کسی کام کا) عزم مصمم کرلو تو خدا پر بھروسا رکھو۔ بےشک خدا بھروسا رکھنے والوں کو دوست رکھتا ہے', NULL, NULL, '4dbcfae62f4656f0421d082f50f413bd463713c100db4c03c87e65a89d5ba266'),
  ('ur.jalandhry', 3, 160, 453, 'اور خدا تمہارا مددگار ہے تو تم پر کوئی غالب نہیں آسکتا۔ اور اگر وہ تمہیں چھوڑ دے تو پھر کون ہے کہ تمہاری مدد کرے اور مومنوں کو چاہیئے کہ خدا ہی پر بھروسا رکھیں', NULL, NULL, '270829e919c01e87d3e8eed0af17d584695e5b264348019e83c5cc7d1f3bb9c0'),
  ('ur.jalandhry', 3, 161, 454, 'اور کبھی نہیں ہوسکتا کہ پیغمبر (خدا) خیانت کریں۔ اور خیانت کرنے والوں کو قیامت کے دن خیانت کی ہوئی چیز (خدا کے روبرو) لاحاضر کرنی ہوگی۔ پھر ہر شخص کو اس کے اعمال کا پورا پورا بدلا دیا جائے گا اور بےانصافی نہیں کی جائے گی', NULL, NULL, 'ad39c6e29531ce57b3d76d7189a56db0c48da49edfa1bebcb2975aae1fddad8d'),
  ('ur.jalandhry', 3, 162, 455, 'بھلا جو شخص خدا کی خوشنودی کا تابع ہو وہ اس شخص کی طرح (مرتکب خیانت) ہوسکتا ہے جو خدا کی ناخوشی میں گرفتار ہو اور جس کا ٹھکانہ دوزخ ہے، اور وہ برا ٹھکانا ہے', NULL, NULL, '5bf10c00ce7538a734ba64380fc542a90ca9545fbd50c11f13f4eb9cd130f9e4'),
  ('ur.jalandhry', 3, 163, 456, 'ان لوگوں کے خدا کے ہاں (مختلف اور متفاوت) درجے ہیں اور خدا ان کے سب اعمال کو دیکھ رہا ہے', NULL, NULL, '20333f305490661059083c6933d42e2f2f64ed345cc8d781e50bb267fdc78aa0'),
  ('ur.jalandhry', 3, 164, 457, 'خدا نے مومنوں پر بڑا احسان کیا ہے کہ ان میں انہیں میں سے ایک پیغمبر بھیجے۔ جو ان کو خدا کی آیتیں پڑھ پڑھ کر سناتے اور ان کو پاک کرتے اور (خدا کی) کتاب اور دانائی سکھاتے ہیں اور پہلے تو یہ لوگ صریح گمراہی میں تھے', NULL, NULL, '9b7b7b0744e72e406f2f6e5373428f237dcb559d0f8fde98fd0a363cb9dd2961'),
  ('ur.jalandhry', 3, 165, 458, '(بھلا یہ) کیا (بات ہے کہ) جب (اُحد کے دن کافر کے ہاتھ سے) تم پر مصیبت واقع ہوئی حالانکہ (جنگ بدر میں) اس سے دوچند مصیبت تمہارے ہاتھ سے ان پر پڑچکی ہے توتم چلا اٹھے کہ (ہائے) آفت (ہم پر) کہاں سے آپڑی کہہ دو کہ یہ تمہاری ہی شامت اعمال ہے (کہ تم نے پیغمبر کے حکم کے خلاف کیا) بےشک خدا ہر چیز پر قادر ہے', NULL, NULL, '49d32e07097fe919543ceb4853abace4f2494526edbaefc6a51ec2b3c5f7eab6'),
  ('ur.jalandhry', 3, 166, 459, 'اور جو مصیبت تم پر دونوں جماعتوں کے مقابلے کے دن واقع ہوئی سو خدا کے حکم سے (واقع ہوئی) اور (اس سے) یہ مقصود تھا کہ خدا مومنوں کو اچھی طرح معلوم', NULL, NULL, 'b6beb24c3a1d759312af251f348d95f5b2345fa484234d6f6f581efee688d87c'),
  ('ur.jalandhry', 3, 167, 460, 'اور منافقوں کو بھی معلوم کرلے اور (جب) ان سے کہا گیا کہ آؤ خدا کے رستے میں جنگ کرو یا (کافروں کے) حملوں کو روکو۔ تو کہنے لگے کہ اگر ہم کو لڑائی کی خبر ہوتی تو ہم ضرور تمہارے ساتھ رہتے یہ اس دن ایمان کی نسبت کفر سے زیادہ قریب تھے منہ سے وہ باتیں کہتے ہیں جو ان کے دل میں نہیں ہیں۔ اور جو کچھ یہ چھپاتے ہیں خدا ان سے خوب واقف ہے', NULL, NULL, '83734148474f5abc966a1f87dd1ef035782817da2d4d0f99b0d3bf01f130ce54'),
  ('ur.jalandhry', 3, 168, 461, 'یہ خود تو (جنگ سے بچ کر) بیٹھ ہی رہے تھے مگر (جنہوں نے راہ خدا میں جانیں قربان کردیں) اپنے (ان) بھائیوں کے بارے میں بھی کہتے ہیں کہ اگر ہمارا کہا مانتے تو قتل نہ ہوتے۔ کہہ دو کہ اگر سچے ہو تو اپنے اوپر سے موت کو ٹال دینا', NULL, NULL, 'e320a56f4d9728a4a6039d291432f700924f6a05ed4c10f10cc1e009135d8ae3'),
  ('ur.jalandhry', 3, 169, 462, 'جو لوگ خدا کی راہ میں مارے گئے ان کو مرے ہوئے نہ سمجھنا (وہ مرے ہوئے نہیں ہیں) بلکہ خدا کے نزدیک زندہ ہیں اور ان کو رزق مل رہا ہے', NULL, NULL, '9d1463ddede9e06df3c2b75f5e163c41da7625fe9e79e5e7416f36383fb908e1'),
  ('ur.jalandhry', 3, 170, 463, 'جو کچھ خدا نے ان کو اپنے فضل سے بخش رکھا ہے اس میں خوش ہیں۔ اور جو لوگ ان کے پیچھے رہ گئے اور (شہید ہوکر) ان میں شامل نہیں ہوسکے ان کی نسبت خوشیاں منا رہے ہیں کہ (قیامت کے دن) ان کو بھی نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے', NULL, NULL, '77f1f7e917aeeeef27ef0cf4557c025a4307176c4a1f76228efcc0c9bdeeabb1'),
  ('ur.jalandhry', 3, 171, 464, 'اور خدا کے انعامات اور فضل سے خوش ہورہے ہیں۔ اور اس سے کہ خدا مومنوں کا اجر ضائع نہیں کرتا', NULL, NULL, '605add82cc7afca76ba1842de122f64993cd3bd3770e3e57226be192cb4f9372'),
  ('ur.jalandhry', 3, 172, 465, 'جنہوں نے باوجود زخم کھانے کے خدا اور رسول (کے حکم) کو قبول کیا جو لوگ ان میں نیکوکار اور پرہیزگار ہیں ان کے لئے بڑا ثواب ہے', NULL, NULL, '3c7939875759703ead5c7582b422cd918086aaff22dd94f66a3a150da943c940'),
  ('ur.jalandhry', 3, 173, 466, '(جب) ان سے لوگوں نے آکر بیان کیا کہ کفار نے تمہارے (مقابلے کے) لئے لشکر کثیر) جمع کیا ہے تو ان سے ڈرو۔ تو ان کا ایمان اور زیادہ ہوگیا۔ اور کہنے لگے ہم کو خدا کافی ہے اور وہ بہت اچھا کارساز ہے', NULL, NULL, '35d4d8272f27f667e3fdbe6e047741783a24c5a08fcb2e4d689a41ddfe86bc9b'),
  ('ur.jalandhry', 3, 174, 467, 'پھر وہ خدا کی نعمتوں اور اس کے فضل کے ساتھ (خوش وخرم) واپس آئے ان کو کسی طرح کا ضرر نہ پہنچا۔ اور وہ خدا کی خوشنودی کے تابع رہے۔ اور خدا بڑے فضل کا مالک ہے', NULL, NULL, '070b6b94e11978a719fadc70fec2c03b44afb31a4f9d95d5b32d78cfdcc31080'),
  ('ur.jalandhry', 3, 175, 468, 'یہ (خوف دلانے والا) تو شیطان ہے جو اپنے دوستوں سے ڈراتا ہے تو اگر تم مومن ہو تو ان سے مت ڈرنا اور مجھ ہی سے ڈرتے رہنا', NULL, NULL, '509ababf31e53a440cd25b907f964664e64b7c910f7bc114834b18f9d9445167'),
  ('ur.jalandhry', 3, 176, 469, 'اور جو لوگ کفر میں جلدی کرتے ہیں ان (کی وجہ) سے غمگین نہ ہونا۔ یہ خدا کا کچھ نقصان نہیں کرسکتے خدا چاہتا ہے کہ آخرت میں ان کو کچھ حصہ نہ دے اور ان کے لئے بڑا عذاب تیار ہے', NULL, NULL, 'e52aca30cbec73b9bc09f330973b7553fad5c8c24df8742aa9b2e87f2f5b59c4'),
  ('ur.jalandhry', 3, 177, 470, 'جن لوگوں نے ایمان کے بدلے کفر خریدا وہ خدا کا کچھ نہیں بگاڑ سکتے اور ان کو دکھ دینے والا عذاب ہوگا', NULL, NULL, '9e8db21fdc3571c492a8bccb648d8b3d4b03f1d6817516ec65e6c2fd8745e938'),
  ('ur.jalandhry', 3, 178, 471, 'اور کافر لوگ یہ نہ خیال کریں کہ ہم جو ان کو مہلت دیئے جاتے ہیں تو یہ ان کے حق میں اچھا ہے۔ (نہیں بلکہ) ہم ان کو اس لئے مہلت دیتے ہیں کہ اور گناہ کرلیں۔ آخرکار ان کو ذلیل کرنے والا عذاب ہوگا', NULL, NULL, '8feaed5b65173dcacc1fad70b7fdd5fa26b45a8dedaf794d3a35275da799ef59'),
  ('ur.jalandhry', 3, 179, 472, '(لوگو) جب تک خدا ناپاک کو پاک سے الگ نہ کردے گا مومنوں کو اس حال میں جس میں تم ہو ہرگز نہیں رہنے دے گا۔ اور الله تم کوغیب کی باتوں سے بھی مطلع نہیں کرے گاالبتہ خدا اپنے پیغمبروں میں سے جسے چاہتا ہے انتخاب کرلیتا ہے۔ تو تم خدا پر اور اس کے رسولوں پر ایمان لاؤاور اگر ایمان لاؤ گے اور پرہیزگاری کرو گے تو تم کو اجر عظیم ملے گا', NULL, NULL, 'e5e44fe84f3066febc948aff9915c01bc5b31e4fd1828c38392c55af553cca1e'),
  ('ur.jalandhry', 3, 180, 473, 'جو لوگ مال میں جو خدا نے اپنے فضل سے ان کو عطا فرمایا ہے بخل کرتے ہیں وہ اس بخل کو اپنے حق میں اچھا نہ سمجھیں۔ (وہ اچھا نہیں) بلکہ ان کے لئے برا ہے وہ جس مال میں بخل کرتے ہیں قیامت کے دن اس کا طوق بنا کر ان کی گردنوں میں ڈالا جائے گا۔ اور آسمانوں اور زمین کا وارث خدا ہی ہے۔ اور جو عمل تم کرتے ہوخدا کو معلوم ہے', NULL, NULL, '43eec7105e651c4693e99146cdcb99ffe1e2be378804604b53f7d3cd9241657b'),
  ('ur.jalandhry', 3, 181, 474, 'خدا نے ان لوگوں کا قول سن لیا ہے جو کہتے ہیں کہ خدا فقیر ہے۔ اور ہم امیر ہیں۔ یہ جو کہتے ہیں ہم اس کو لکھ لیں گے۔ اور پیغمبروں کو جو یہ ناحق قتل کرتے رہے ہیں اس کو بھی (قلمبند کر رکھیں گے) اور (قیامت کے روز) کہیں گے کہ عذاب (آتش) سوزاں کے مزے چکھتے رہو', NULL, NULL, 'a8e8e4d7ed578053ee1cbddba5cedb4138b19d9fca108f0ba0455831910ddcc8'),
  ('ur.jalandhry', 3, 182, 475, 'یہ ان کاموں کی سزا ہے جو تمہارے ہاتھ آگے بھیجتے رہے ہیں اور خدا تو بندوں پر مطلق ظلم نہیں کرتا', NULL, NULL, 'f99c9ba7703bfe4d06479789036397c99ae57c29ab937e54bd34688fdde90ee2'),
  ('ur.jalandhry', 3, 183, 476, 'جو لوگ کہتے ہی کہ خدا نے ہمیں حکم بھیجا ہے کہ جب تک کوئی پیغمبر ہمارے پاس ایسی نیاز لے کر نہ آئے جس کو آگ آکر کھا جائے تب تک ہم اس پر ایمان نہ لائیں گے (اے پیغمبر ان سے) کہہ دو کہ مجھ سے پہلے کئی پیغمبر تمہارے پاس کھلی ہوئی نشانیاں لے کر آئے اور وہ (معجزہ) بھی لائے جو تم کہتے ہو تو اگر سچے ہو تو تم نے ان کو قتل کیوں کیا؟', NULL, NULL, '1cbff7365372ed753f33f847e066cf73ef7bde5c3409124a68d2840d3fdc7e20'),
  ('ur.jalandhry', 3, 184, 477, 'پھر اگر یہ لوگ تم کو سچا نہ سمجھیں تو تم سے پہلے بہت سے پیغمبر کھلی ہوئی نشانیاں اور صحیفے اور روشن کتابیں لے کر آچکے ہیں اور لوگوں نے ان کو بھی سچا نہیں سمجھا', NULL, NULL, '5369f86e4b5657cd5b647d9bff53237d7568e63b3a173ce16d733c50fc8001e8'),
  ('ur.jalandhry', 3, 185, 478, 'ہر متنفس کو موت کا مزا چکھنا ہے اور تم کو قیامت کے دن تمہارے اعمال کا پورا پورا بدلا دیا جائے گا۔ تو جو شخص آتش جہنم سے دور رکھا گیا اور بہشت میں داخل کیا گیا وہ مراد کو پہنچ گیا اور دنیا کی زندگی تو دھوکے کا سامان ہے', NULL, NULL, '702c756630383c6b4937c86f63798982cb8bfc7ae3a2e6bf8dbd0c0eda67b1f8'),
  ('ur.jalandhry', 3, 186, 479, '(اے اہل ایمان) تمہارے مال و جان میں تمہاری آزمائش کی جائے گی۔ اور تم اہل کتاب سے اور ان لوگوں سے جو مشرک ہیں بہت سی ایذا کی باتیں سنو گے۔ اور تو اگر صبر اور پرہیزگاری کرتے رہو گے تو یہ بڑی ہمت کے کام ہیں', NULL, NULL, '0f220f300c9fb7d5c9d8777847feca08c76c417723d0391b743e960e27ceb3d2'),
  ('ur.jalandhry', 3, 187, 480, 'اور جب خدا نے ان لوگوں سے جن کو کتاب عنایت کی گئی تھی اقرار کرلیا کہ (جو کچھ اس میں لکھا ہے) اسے صاف صاف بیان کرتے رہنا۔ اور اس (کی کسی بات) کو نہ چھپانا تو انہں نے اس کو پس پشت پھینک دیا اور اس کے بدلے تھوڑی سی قیمت حاصل کی۔ یہ جو کچھ حاصل کرتے ہیں برا ہے', NULL, NULL, '63ace125deca222783869d2d7f8acf6807af0805fed99a618add1aafde3ce290'),
  ('ur.jalandhry', 3, 188, 481, 'جو لوگ اپنے (ناپسند) کاموں سے خوش ہوتے ہیں اور پسندیدہ کام) جو کرتے نہیں ان کے لئے چاہتے ہیں کہ ان ک تعریف کی جائے ان کی نسبت خیال نہ کرنا کہ وہ عذاب سے رستگار ہوجائیں گے۔ اور انہیں درد دینے والا عذاب ہوگا', NULL, NULL, '4426828749776198152591b420d7b582462b8e2509164990d6522cb19e92889a'),
  ('ur.jalandhry', 3, 189, 482, 'اور آسمانوں اور زمین کی بادشاہی خدا ہی کو ہے اور خدا ہر چیز پر قادر ہے', NULL, NULL, '1dc16773cb4cf844f7a8d5f59df70a4bb718810a14cb58bcbcc9b5336407e232'),
  ('ur.jalandhry', 3, 190, 483, 'بے شک آسمانوں اور زمین کی پیدائش اور رات اور دن کے بدل بدل کے آنے جانے میں عقل والوں کے لیے نشانیاں ہیں', NULL, NULL, '23149682fe22caef9349cffc4e018ed47304821d27915407093d4bfa4c6f9247'),
  ('ur.jalandhry', 3, 191, 484, 'جو کھڑے اور بیٹھے اور لیٹے (ہر حال میں) خدا کو یاد کرتے اور آسمان اور زمین کی پیدائش میں غور کرتے (اور کہتے ہیں) کہ اے پروردگار! تو نے اس (مخلوق) کو بے فائدہ نہیں پیدا کیا تو پاک ہے تو (قیامت کے دن) ہمیں دوزخ کے عذاب سے بچائیو', NULL, NULL, '06e731c802002f89280766fa0b1b23271578a1bce3e33f65b7ac7b9dc2515f1b'),
  ('ur.jalandhry', 3, 192, 485, 'اے پروردگار جس کو تو نے دوزخ میں ڈالا اسے رسوا کیا اور ظالموں کا کوئی مددگار نہیں', NULL, NULL, '536946e9efa2492cb13a8bed2d9c206a4ad208b65fe7a8f4168472fbc508f9a8'),
  ('ur.jalandhry', 3, 193, 486, 'اے پروردگارہم نے ایک ندا کرنے والے کو سنا کہ ایمان کے لیے پکار رہا تھا (یعنی) اپنے پروردگار پر ایمان لاؤ تو ہم ایمان لے آئے اے پروردگار ہمارے گناہ معاف فرما اور ہماری برائیوں کو ہم سے محو کر اور ہم کو دنیا سے نیک بندوں کے ساتھ اٹھا', NULL, NULL, 'e875f455de6a5a1e97f4e1b72425857e752cd70d91846afecacaee1c6832aa4e'),
  ('ur.jalandhry', 3, 194, 487, 'اے پروردگار تو نے جن جن چیزوں کے ہم سے اپنے پیغمبروں کے ذریعے سے وعدے کیے ہیں وہ ہمیں عطا فرما اور قیامت کے دن ہمیں رسوا نہ کیجو کچھ شک نہیں کہ تو خلاف وعدہ نہیں کرتا', NULL, NULL, '7dfaa04def86e9649f5040de92ce693c1c669c38dda85ccb3891ab85be1ec269'),
  ('ur.jalandhry', 3, 195, 488, 'تو ان کے پرردگار نے ان کی دعا قبول کر لی (اور فرمایا) کہ میں کسی عمل کرنے والے کے عمل کو مرد ہو یا عورت ضائع نہیں کرتا تم ایک دوسرے کی جنس ہو تو جو لوگ میرے لیے وطن چھوڑ گئے اور اپنے گھروں سے نکالے گئے اور ستائے گئے اور لڑے اور قتل کیے گئے میں ان کے گناہ دور کردوں گا اور ان کو بہشتوں میں داخل کروں گا جن کے نیچے نہریں بہ رہی ہیں (یہ) خدا کے ہاں سے بدلہ ہے اور خدا کے ہاں اچھا بدلہ ہے', NULL, NULL, '537cd05d6c66b9eadb464ac15b39f9adbc815b86cf9cc374c5c230689438a510'),
  ('ur.jalandhry', 3, 196, 489, '(اے پیغمبر) کافروں کا شہروں میں چلنا پھرنا تمہیں دھوکا نہ دے', NULL, NULL, '3bab94e0a926bb0b6bca7a745991b34a604715dfcec267950f5edbaf703b232d'),
  ('ur.jalandhry', 3, 197, 490, '(یہ دنیا کا) تھوڑا سا فائدہ ہے پھر (آخرت میں) تو ان کا ٹھکانا دوزخ ہے اور وہ بری جگہ ہے', NULL, NULL, '6939fbcac98e4ce31b07c3875568e9eac5a9722570df5868b154fb67248fc880'),
  ('ur.jalandhry', 3, 198, 491, 'لیکن جو لوگ اپنے پروردگار سے ڈرتے رہے ان کے لیے باغ ہے جن کے نیچے نہریں بہہ رہی ہیں (اور) ان میں ہمیشہ رہیں گے (یہ) خدا کے ہاں سے (ان کی) مہمانی ہے اور جو کچھ خدا کے ہاں ہے وہ نیکو کاروں کے لیے بہت اچھا ہے', NULL, NULL, '7cc4621dddc05bec8485eb4bb7db49226927dd2972452d71e845b45c808f5557'),
  ('ur.jalandhry', 3, 199, 492, 'اور بعض اہلِ کتاب ایسے بھی ہیں جو خدا پر اور اس (کتاب) پر جو تم پر نازل ہوئی اور اس پر جو ان پر نازل ہوئی ایمان رکھتے ہیں اور خدا کے آگے عاجزی کرتے ہیں اور خدا کی آیتوں کے بدلے تھوڑی سی قیمت نہیں لیتے یہی لوگ ہیں جن کا صلہ ان کے پروردگار کے ہاں تیار ہے اور خدا جلد حساب لینے والا ہے', NULL, NULL, '45f86e6fd685176f8572b2495c1d3adb4b3eaadbe42dff35d5cd1e77e4fa4eb3'),
  ('ur.jalandhry', 3, 200, 493, 'اے اہل ایمان (کفار کے مقابلے میں) ثابت قدم رہو اور استقامت رکھو اور مورچوں پر جمے رہو اور خدا سے ڈرو تاکہ مراد حاصل کرو', NULL, NULL, 'e40f675a8a7531ff35cff8e1ed321b4e953376f305c898611e627fdbe97dd875'),
  ('ur.jalandhry', 4, 1, 494, 'لوگو اپنے پروردگار سے ڈرو جس نے تم کو ایک شخص سے پیدا کیا (یعنی اول) اس سے اس کا جوڑا بنایا۔ پھر ان دونوں سے کثرت سے مرد وعورت (پیدا کرکے روئے زمین پر) پھیلا دیئے۔ اور خدا سے جس کے نام کو تم اپنی حاجت بر آری کا ذریعہ بناتے ہو ڈرو اور (قطع مودت) ارحام سے (بچو) کچھ شک نہیں کہ خدا تمہیں دیکھ رہا ہے', NULL, NULL, 'a0a414eb087f866b081f4b4a99b1785aee4511a1e496868fd6052cc0c50c16cf'),
  ('ur.jalandhry', 4, 2, 495, 'اور یتیموں کا مال (جو تمہاری تحویل میں ہو) ان کے حوالے کردو اور ان کے پاکیزہ (اور عمدہ) مال کو (اپنے ناقص اور) برے مال سے نہ بدلو۔ اور نہ ان کا مال اپنے مال میں ملا کر کھاؤ۔ کہ یہ بڑا سخت گناہ ہے', NULL, NULL, '6fc87ac16584ede276e558a79afe253e90b025a21a05e9146f7380565d3ebcd2'),
  ('ur.jalandhry', 4, 3, 496, 'اور اگر تم کو اس بات کا خوف ہو کہ یتیم لڑکیوں کے بارےانصاف نہ کرسکوگے تو ان کے سوا جو عورتیں تم کو پسند ہوں دو دو یا تین تین یا چار چار ان سے نکاح کرلو۔ اور اگر اس بات کا اندیشہ ہو کہ (سب عورتوں سے) یکساں سلوک نہ کرسکو گے تو ایک عورت (کافی ہے) یا لونڈی جس کے تم مالک ہو۔ اس سے تم بےانصافی سے بچ جاؤ گے', NULL, NULL, 'fbfdef02e2b11459c424ee53742b7b488f4582f29d81165868a84c36fdcd8a40'),
  ('ur.jalandhry', 4, 4, 497, 'اور عورتوں کو ان کے مہر خوشی سے دے دیا کرو۔ ہاں اگر وہ اپنی خوشی سے اس میں سے کچھ تم کو چھوڑ دیں تو اسے ذوق شوق سے کھالو', NULL, NULL, '09b62369361304502bb290e23d1ca03c378b23230d45cd60149fc02c3ca05bd3'),
  ('ur.jalandhry', 4, 5, 498, 'اور بےعقلوں کو ان کا مال جسے خدا نے تم لوگوں کے لئے سبب معیشت بنایا ہے مت دو (ہاں) اس میں سے ان کو کھلاتے اور پہناتے رہے اور ان سے معقول باتیں کہتے رہو', NULL, NULL, 'c60377e214b53ef45d7b1d4e8163f6e83d31ef59eb1c4f1485d4a16584820e79'),
  ('ur.jalandhry', 4, 6, 499, 'اور یتمیوں کو بالغ ہونے تک کام کاج میں مصروف رکھو پھر (بالغ ہونے پر) اگر ان میں عقل کی پختگی دیکھو تو ان کا مال ان کے حوالے کردو اور اس خوف سے کہ وہ بڑے ہوجائیں گے (یعنی بڑے ہو کر تم سے اپنا مال واپس لے لیں گے) اس کو فضول خرچی اور جلدی میں نہ اڑا دینا۔ جو شخص آسودہ حال ہو اس کو (ایسے مال سے قطعی طور پر) پرہیز رکھنا چاہیئے اور جو بے مقدور ہو وہ مناسب طور پر (یعنی بقدر خدمت) کچھ لے لے اور جب ان کا مال ان کے حوالے کرنے لگو تو گواہ کرلیا کرو۔ اور حقیقت میں تو خدا ہی (گواہ اور) حساب لینے والا کافی ہے', NULL, NULL, '0b763ca03522a68798201cc8c338253f694f50f0cf647338cfc1c284ed753be2'),
  ('ur.jalandhry', 4, 7, 500, 'جو مال ماں باپ اور رشتہ دار چھوڑ مریں تھوڑا ہو یا بہت۔ اس میں مردوں کا بھی حصہ ہے اور عورتوں کا بھی یہ حصے (خدا کے) مقرر کئے ہوئے ہیں', NULL, NULL, 'e46d024a1275032d771b5fd7f7e77b9e44056c8670e9e9446fa92778e18945ca')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 4, 8, 501, 'اور جب میراث کی تقسیم کے وقت (غیر وارث) رشتہ دار اور یتیم اور محتاج آجائیں تو ان کو بھی اس میں سے کچھ دے دیا کرو۔ اور شیریں کلامی سے پیش آیا کرو', NULL, NULL, 'fcc3d32372f050418f74842c8ca23e838f2e495f6a4306dc4e0f35c32cf32b07'),
  ('ur.jalandhry', 4, 9, 502, 'اور ایسے لوگوں کو ڈرنا چاہیئے جو (ایسی حالت میں ہوں کہ) اپنے بعد ننھے ننھے بچے چھوڑ جائیں اور ان کو ان کی نسبت خوف ہو (کہ ان کے مرنے کے بعد ان بیچاروں کا کیا حال ہوگا) پس چاہیئے کہ یہ لوگ خدا سے ڈریں اور معقول بات کہیں', NULL, NULL, '8c6a4ae44c9e87db0a6cf2aae8185e16ea67d4cc5212f6680cdd8f2b9f220b44'),
  ('ur.jalandhry', 4, 10, 503, 'لوگ یتیموں کا مال ناجائز طور پر کھاتے ہیں وہ اپنے پیٹ میں آگ بھرتے ہیں۔ اور دوزخ میں ڈالے جائیں گے', NULL, NULL, '19c01911a1ad9ed0ede83ab9a78f835609f4e8dbb15f0a180dc6940ec915b118'),
  ('ur.jalandhry', 4, 11, 504, 'خدا تمہاری اولاد کے بارے میں تم کو ارشاد فرماتا ہے کہ ایک لڑکے کا حصہ دو لڑکیوں کے حصے کے برابر ہے۔ اور اگر اولاد میت صرف لڑکیاں ہی ہوں (یعنی دو یا) دو سے زیادہ تو کل ترکے میں ان کادو تہائی۔ اور اگر صرف ایک لڑکی ہو تو اس کا حصہ نصف۔ اور میت کے ماں باپ کا یعنی دونوں میں سے ہر ایک کا ترکے میں چھٹا حصہ بشرطیکہ میت کے اولاد ہو۔ اور اگر اولاد نہ ہو اور صرف ماں باپ ہی اس کے وارث ہوں تو ایک تہائی ماں کا حصہ۔ اور اگر میت کے بھائی بھی ہوں تو ماں کا چھٹا حصہ۔ (اور یہ تقسیم ترکہ میت کی) وصیت (کی تعمیل) کے بعد جو اس نے کی ہو یا قرض کے (ادا ہونے کے بعد جو اس کے ذمے ہو عمل میں آئے گی) تم کو معلوم نہیں کہ تمہارے باپ دادؤں اور بیٹوں پوتوں میں سے فائدے کے لحاظ سے کون تم سے زیادہ قریب ہے، یہ حصے خدا کے مقرر کئے ہوئے ہیں اور خدا سب کچھ جاننے والا اور حکمت والا ہے', NULL, NULL, '951b28016a0751274adeddf039aa518e92792a0b41b79468d530d50b383f493c'),
  ('ur.jalandhry', 4, 12, 505, 'اور جو مال تمہاری عورتیں چھوڑ مریں۔ اگر ان کے اولاد نہ ہو تو اس میں نصف حصہ تمہارا۔ اور اگر اولاد ہو تو ترکے میں تمہارا حصہ چوتھائی۔ (لیکن یہ تقسیم) وصیت (کی تعمیل) کے بعد جو انہوں نے کی ہو یا قرض کے (ادا ہونے کے بعد جو ان کے ذمے ہو، کی جائے گی) اور جو مال تم (مرد) چھوڑ مرو۔ اگر تمہارے اولاد نہ ہو تو تمہاری عورتوں کا اس میں چوتھا حصہ۔ اور اگر اولاد ہو تو ان کا آٹھواں حصہ (یہ حصے) تمہاری وصیت (کی تعمیل) کے بعد جو تم نے کی ہو اور (ادائے) قرض کے (بعد تقسیم کئے جائیں گے) اور اگر ایسے مرد یا عورت کی میراث ہو جس کے نہ باپ ہو نہ بیٹا مگر اس کے بھائی بہن ہو تو ان میں سے ہر ایک کا چھٹا حصہ اور اگر ایک سے زیادہ ہوں تو سب ایک تہائی میں شریک ہوں گے (یہ حصے بھی ادائے وصیت و قرض بشرطیکہ ان سے میت نے کسی کا نقصان نہ کیا ہو (تقسیم کئے جائیں گے) یہ خدا کا فرمان ہے۔ اور خدا نہایت علم والا (اور) نہایت حلم والا ہے', NULL, NULL, 'a70fa74ab12f2d9b2ed25ae13de561471f10728d3c882eb11c0d71f50d8d1cbb'),
  ('ur.jalandhry', 4, 13, 506, '(یہ تمام احکام) خدا کی حدیں ہیں۔ اور جو شخص خدا اور اس کے پیغمبر کی فرمانبرداری کرے گا خدا اس کو بہشتوں میں داخل کرے گا جن میں نہریں بہہ رہی ہیں وہ ان میں ہمیشہ رہیں گے۔اور یہ بڑی کامیابی ہے', NULL, NULL, 'dd532c70c9d8c21769929b1fb6899518ada7e9cba684bdfacd9d4d586bd95bf5'),
  ('ur.jalandhry', 4, 14, 507, 'اور جو خدا اور اس کے رسول کی نافرمانی کرے گا اور اس کی حدوں سے نکل جائے گا اس کو خدا دوزخ میں ڈالے گا جہاں وہ ہمیشہ رہے گا۔ اور اس کو ذلت کا عذاب ہوگا', NULL, NULL, 'fafbcf62af2fd1ff22374a9dc14f637c98f8852db2f59345ac7ce01952fa914a'),
  ('ur.jalandhry', 4, 15, 508, 'مسلمانو تمہاری عورتوں میں جو بدکاری کا ارتکاب کر بیٹھیں ان پر اپنے لوگوں میں سے چار شخصوں کی شہادت لو۔ اگر وہ (ان کی بدکاری کی) گواہی دیں تو ان عورتوں کو گھروں میں بند رکھو یہاں تک کہ موت ان کا کام تمام کردے یا خدا ان کے لئے کوئی اور سبیل (پیدا) کرے', NULL, NULL, 'b5e12286fa47aabef9725602bbfcf4dcd6772407ac84f7eb0b636e16db1b1011'),
  ('ur.jalandhry', 4, 16, 509, 'اور جو دو مرد تم میں سے بدکاری کریں تو ان کو ایذا دو۔ پھر اگر وہ توبہ کرلیں اور نیکوکار ہوجائیں تو ان کا پیچھا چھوڑ دو۔ بےشک خدا توبہ قبول کرنے والا (اور) مہربان ہے', NULL, NULL, '1c31c08015ded3d9887e7667e2d6849f1854c5dbeb7e62c51bc7cf54bf74ed74'),
  ('ur.jalandhry', 4, 17, 510, 'خدا انہیں لوگوں کی توبہ قبول فرماتا ہے جو نادانی سے بری حرکت کر بیٹھے ہیں۔ پھر جلد توبہ قبول کرلیتے ہیں پس ایسے لوگوں پر خدا مہربانی کرتا ہے۔ اور وہ سب کچھ جانتا (اور) حکمت والا ہے', NULL, NULL, '3655b47c80d188881c149ddeac664a07d0dcfbc9c063832ffbf66d39a94b1b06'),
  ('ur.jalandhry', 4, 18, 511, 'اور ایسے لوگوں کی توبہ قبول نہیں ہوتی جو (ساری عمر) برے کام کرتے ہیں۔ یہاں تک کہ جب ان میں سے کسی موت آموجود ہو تو اس وقت کہنے لگے کہ اب میں توبہ کرتا ہوں اور نہ ان کی (توبہ قبول ہوتی ہے) جو کفر کی حالت میں مریں۔ ایسے لوگوں کے لئے ہم نے عذاب الیم تیار کر رکھا ہے', NULL, NULL, '1626d7e0959622a53b19f5f7139f89968e5d06a2fd77375dc0f624899e8aa35e'),
  ('ur.jalandhry', 4, 19, 512, 'مومنو! تم کو جائز نہیں کہ زبردستی عورتوں کے وارث بن جاؤ۔ اور (دیکھنا) اس نیت سے کہ جو کچھ تم نے ان کو دیا ہے اس میں سے کچھ لے لو انہیں (گھروں میں) میں مت روک رکھنا ہاں اگر وہ کھلے طور پر بدکاری کی مرتکب ہوں (تو روکنا مناسب نہیں) اور ان کے ساتھ اچھی طرح رہو سہو اگر وہ تم کو ناپسند ہوں تو عجب نہیں کہ تم کسی چیز کو ناپسند کرو اور خدا اس میں بہت سی بھلائی پیدا کردے', NULL, NULL, 'df363f64c621bb250f3ac25619e3447669e894fe89061b0833c19d99bbb37a2f'),
  ('ur.jalandhry', 4, 20, 513, 'اور اگر تم ایک عورت کو چھوڑ کر دوسری عورت کرنی چاہو۔ اور پہلی عورت کو بہت سال مال دے چکے ہو تو اس میں سے کچھ مت لینا۔ بھلا تم ناجائز طور پر اور صریح ظلم سے اپنا مال اس سے واپس لے لوگے؟', NULL, NULL, 'b845e079482fc84874eb883e02962bf97cfa0290c6b47a5162b42449a505e639'),
  ('ur.jalandhry', 4, 21, 514, 'اور تم دیا ہوا مال کیونکر واپس لے سکتے ہو جب کہ تم ایک دوسرے کے ساتھ صحبت کرچکے ہو۔ اور وہ تم سے عہد واثق بھی لے چکی ہے', NULL, NULL, 'f63a0749fd9cee336bee13446925daad321422dcf18c05c3f0bfd6e7b976cd46'),
  ('ur.jalandhry', 4, 22, 515, 'اور جن عورتوں سے تمہارے باپ نے نکاح کیا ہو ان نکاح مت کرنا (مگر جاہلیت میں) جو ہوچکا (سوہوچکا) یہ نہایت بےحیائی اور (خدا کی) ناخوشی کی بات تھی۔ اور بہت برا دستور تھا', NULL, NULL, '12f4fd9cc037ba03278161f034cce687da2e51b67929e1e9e59ab2175e930897'),
  ('ur.jalandhry', 4, 23, 516, 'تم پر تمہاری مائیں اور بیٹیاں اور بہنیں اور پھوپھیاں اور خالائیں اور بھتیجیاں اور بھانجیاں اور وہ مائیں جنہوں نے تم کو دودھ پلایا ہو اور رضاعی بہنیں اور ساسیں حرام کر دی گئی ہیں اور جن عورتوں سے تم مباشرت کر چکے ہو ان کی لڑکیاں جنہیں تم پرورش کرتے (ہو وہ بھی تم پر حرام ہیں) ہاں اگر ان کے ساتھ تم نے مباشرت نہ کی ہو تو (ان کی لڑکیوں کے ساتھ نکاح کر لینے میں) تم پر کچھ گناہ نہیں اور تمہارے صلبی بیٹوں کی عورتیں بھی اور دو بہنوں کا اکٹھا کرنا بھی (حرام ہے) مگر جو ہو چکا (سو ہو چکا) بے شک خدا بخشنے والا (اور) رحم کرنے والا ہے', NULL, NULL, 'c369cfee36f000f048c67f6dc5f8c465a182614510062443d8e1687cbf8d9755'),
  ('ur.jalandhry', 4, 24, 517, 'اور شوہر والی عورتیں بھی (تم پر حرام ہیں) مگر وہ جو (اسیر ہو کر لونڈیوں کے طور پر) تمہارے قبضے میں آجائیں (یہ حکم) خدا نے تم کو لکھ دیا ہے اور ان (محرمات) کے سوا اور عورتیں تم کو حلال ہیں اس طرح سے کہ مال خرچ کر کے ان سے نکاح کرلو بشرطیکہ (نکاح سے) مقصود عفت قائم رکھنا ہو نہ شہوت رانی تو جن عورتوں سے تم فائدہ حاصل کرو ان کا مہر جو مقرر کیا ہو ادا کردو اور اگر مقرر کرنے کے بعد آپس کی رضامندی سے مہر میں کمی بیشی کرلو تو تم پر کچھ گناہ نہیں بےشک خدا سب کچھ جاننے والا (اور) حکمت والا ہے', NULL, NULL, '4b7f8e2d6dcf017742b5f54becfec0429342fae2481de2d665048e9542957fa8'),
  ('ur.jalandhry', 4, 25, 518, 'اور جو شخص تم میں سے مومن آزاد عورتوں (یعنی بیبیوں) سے نکاح کرنے کا مقدور نہ رکھے تو مومن لونڈیوں میں ہی جو تمہارے قبضے میں آگئی ہوں (نکاح کرلے) اور خدا تمہارے ایمان کو اچھی طرح جانتا ہے تم آپس میں ایک دوسرے کے ہم جنس ہو تو ان لونڈیوں کے ساتھ ان کے مالکوں سے اجازت حاصل کرکے نکاح کر لو اور دستور کے مطابق ان کا مہر بھی ادا کردو بشرطیکہ عفیفہ ہوں نہ ایسی کہ کھلم کھلا بدکاری کریں اور نہ درپردہ دوستی کرنا چاہیں پھر اگر نکاح میں آکر بدکاری کا ارتکاب کر بیٹھیں تو جو سزا آزاد عورتوں (یعنی بیبیوں) کے لئے ہے اس کی آدھی ان کو (دی جائے) یہ (لونڈی کے ساتھ نکاح کرنے کی) اجازت اس شخص کو ہے جسے گناہ کر بیٹھنے کا اندیشہ ہو اور اگر صبر کرو تو یہ تمہارے لئے بہت اچھا ہے اور خدا بخشنے والا مہربان ہے', NULL, NULL, '5f5c8f2459c9834458938359be77d5c3d30fb6931e664792dfef8187cb3571ae'),
  ('ur.jalandhry', 4, 26, 519, 'خدا چاہتا ہے کہ (اپنی آیتیں) تم سے کھول کھول کر بیان فرمائے اور تم کو اگلے لوگوں کے طریقے بتائے اور تم پر مہربانی کرے اور خدا جاننے والا (اور) حکمت والا ہے', NULL, NULL, 'd694df967329f91f1dbd09a55106930a8b6608600a3d7fc14782a7093a7e7cd0'),
  ('ur.jalandhry', 4, 27, 520, 'اور خدا تو چاہتا ہے کہ تم پر مہربانی کرے اور جو لوگ اپنی خواہشوں کے پیچھے چلتے ہیں وہ چاہتے ہیں کہ تم سیدھے راستے سے بھٹک کر دور جا پڑو', NULL, NULL, '4c6e6738119247319b3c67209549cba7e32212028f7d9a9da380ec0e92d924c6'),
  ('ur.jalandhry', 4, 28, 521, 'خدا چاہتا ہے کہ تم پر سے بوجھ ہلکا کرے اور انسان (طبعاً) کمزور پیدا ہوا ہے', NULL, NULL, '729156e8efd32a359bda4d01596089031d478499b1f264754b2c4d55f91fb7e6'),
  ('ur.jalandhry', 4, 29, 522, 'مومنو! ایک دوسرے کا مال ناحق نہ کھاؤ ہاں اگر آپس کی رضامندی سے تجارت کا لین دین ہو (اور اس سے مالی فائدہ حاصل ہو جائے تو وہ جائز ہے) اور اپنے آپ کو ہلاک نہ کرو کچھ شک نہیں کہ خدا تم پر مہربان ہے', NULL, NULL, '92111b7f6f888591de5829195a6db6ddcca307cc4c31b76a92f60b0d38abc969'),
  ('ur.jalandhry', 4, 30, 523, 'اور جو تعدی اور ظلم سے ایسا کرے گا ہم اس کو عنقریب جہنم میں داخل کریں گے اور یہ خدا کو آسان ہے', NULL, NULL, 'f30e143df30f3862dea55a7fd0590737858396a9e371bc903e0cb727e9a0ec77'),
  ('ur.jalandhry', 4, 31, 524, 'اگر تم بڑے بڑے گناہوں سے جن سے تم کو منع کیا جاتا ہے اجتناب رکھو گے تو ہم تمہارے (چھوٹے چھوٹے) گناہ معاف کردیں گے اور تمہیں عزت کے مکانوں میں داخل کریں گے', NULL, NULL, '8ea3655e602a2105a0b8460f0ca31e1595f0fd05856103ab45eaeddf608726c6'),
  ('ur.jalandhry', 4, 32, 525, 'اور جس چیز میں خدا نے تم میں سے بعض کو بعض پر فضیلت دی ہے اس کی ہوس مت کرو مردوں کو ان کاموں کا ثواب ہے جو انہوں نے کئے اور عورتوں کو ان کاموں کا ثواب ہے جو انہوں نے کئے اور خدا سے اس کا فضل (وکرم) مانگتے رہو کچھ شک نہیں کہ خدا ہر چیز سے واقف ہے', NULL, NULL, '962609df64f4506701ffc7e3149c4e051c8f9ddd0496a08513e1cf0f9c580284'),
  ('ur.jalandhry', 4, 33, 526, 'اور جو مال ماں باپ اور رشتہ دار چھوڑ مریں تو (حق داروں میں تقسیم کردو کہ) ہم نے ہر ایک کے حقدار مقرر کردیئے ہیں اور جن لوگوں سے تم عہد کرچکے ہو ان کو بھی ان کا حصہ دو بےشک خدا ہر چیز کے سامنے ہے', NULL, NULL, '042216faa21984e8b596d3895769e1555b0300b159bd4e1250645f428571fe26'),
  ('ur.jalandhry', 4, 34, 527, 'مرد عورتوں پر مسلط وحاکم ہیں اس لئے کہ خدا نے بعض کو بعض سے افضل بنایا ہے اور اس لئے بھی کہ مرد اپنا مال خرچ کرتے ہیں تو جو نیک بیبیاں ہیں وہ مردوں کے حکم پر چلتی ہیں اور ان کے پیٹھ پیچھے خدا کی حفاظت میں (مال وآبرو کی) خبرداری کرتی ہیں اور جن عورتوں کی نسبت تمہیں معلوم ہو کہ سرکشی (اور بدخوئی) کرنے لگی ہیں تو (پہلے) ان کو (زبانی) سمجھاؤ (اگر نہ سمجھیں تو) پھر ان کے ساتھ سونا ترک کردو اگر اس پر بھی باز نہ آئیں تو زدوکوب کرو اور اگر فرمانبردار ہوجائیں تو پھر ان کو ایذا دینے کا کوئی بہانہ مت ڈھونڈو بےشک خدا سب سے اعلیٰ (اور) جلیل القدر ہے', NULL, NULL, 'a64eb8a94e7837fc698eda10f2bb6086227a8b224405d8c579143df3092732e4'),
  ('ur.jalandhry', 4, 35, 528, 'اور اگر تم کو معلوم ہو کہ میاں بیوی میں ان بن ہے تو ایک منصف مرد کے خاندان میں سے اور ایک منصف عورت کے خاندان میں سے مقرر کرو وہ اگر صلح کرا دینی چاہیں گے تو خدا ان میں موافقت پیدا کردے گا کچھ شک نہیں کہ خدا سب کچھ جانتا اور سب باتوں سے خبردار ہے', NULL, NULL, 'f900bfbd7253177a2868e7eca828b85d5f1894f073b14a23731d15e51f282509'),
  ('ur.jalandhry', 4, 36, 529, 'اور خدا ہی کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ بناؤ اور ماں باپ اور قرابت والوں اور یتیموں اور محتاجوں اور رشتہ دار ہمسائیوں اور اجنبی ہمسائیوں اور رفقائے پہلو (یعنی پاس بیٹھنے والوں) اور مسافروں اور جو لوگ تمہارے قبضے میں ہوں سب کے ساتھ احسان کرو کہ خدا (احسان کرنے والوں کو دوست رکھتا ہے اور) تکبر کرنے والے بڑائی مارنے والے کو دوست نہیں رکھتا', NULL, NULL, '8cdeb0e211fbf00866a364f4f0045e45a196ab731dc614aeb74d8a15e606e4cc'),
  ('ur.jalandhry', 4, 37, 530, 'جو خود بھی بخل کریں اور لوگوں کو بھی بخل سکھائیں اور جو (مال) خدا نے ان کو اپنے فضل سے عطا فرمایا ہے اسے چھپا چھپا کے رکھیں اور ہم نے ناشکروں کے لئے ذلت کا عذاب تیار کر رکھا ہے', NULL, NULL, '52894aca401457b60999a7fb013fbd86e4b77be0030d306e80b0c3b576b934ca'),
  ('ur.jalandhry', 4, 38, 531, 'اور خرچ بھی کریں تو (خدا کے لئے نہیں بلکہ) لوگوں کے دکھانے کو اور ایمان نہ خدا پر لائیں اور نہ روز آخرت پر (ایسے لوگوں کو ساتھی شیطان ہے) اور جس کا ساتھی شیطان ہوا تو (کچھ شک نہیں کہ) وہ برا ساتھی ہے', NULL, NULL, '80488ff9a76adc884483f239558712366960b1c8df6580dd0ed9b78f2879c2f2'),
  ('ur.jalandhry', 4, 39, 532, 'اور اگر یہ لوگ خدا پر اور روز قیامت پر ایمان لاتے اور جو کچھ خدا نے ان کو دیا تھا اس میں سے خرچ کرتے تو ان کا کیا نقصان ہوتا اور خدا ان کو خوب جانتا ہے', NULL, NULL, 'caaa541366f0820fb31481fc4b7c9f2d21af40786cee40fc86011bfef20df5bc'),
  ('ur.jalandhry', 4, 40, 533, 'خدا کسی کی ذرا بھی حق تلفی نہیں کرتا اور اگر نیکی (کی) ہوگی تو اس کو دوچند کردے گا اور اپنے ہاں سے اجرعظیم بخشے گا', NULL, NULL, '5bc70c2504438bb2b36b4cbf20e796cc19d1b0f3a9d88b47a5e32ce62c6e4732'),
  ('ur.jalandhry', 4, 41, 534, 'بھلا اس دن کا کیا حال ہوگا جب ہم ہر امت میں سے احوال بتائے والے کو بلائیں گے اور تم کو ان لوگوں کا حال (بتانے کو) گواہ طلب کریں گے', NULL, NULL, '4f06d222945c14db550f0c4d8f6502ed5f9bd2328d414f58a6396c63219e0811'),
  ('ur.jalandhry', 4, 42, 535, 'اس روز کافر اور پیغمبر کے نافرمان آرزو کریں گے کہ کاش ان کو زمین میں مدفون کرکے مٹی برابر کردی جاتی اور خدا سے کوئی بات چھپا نہیں سکیں گے', NULL, NULL, 'ec98046149fcddc2ef869a491d48b5f460b616de0cfd9d7e7c9733d4e0663d44'),
  ('ur.jalandhry', 4, 43, 536, 'مومنو! جب تم نشے کی حالت میں ہو تو جب تک (ان الفاظ کو) جو منہ سے کہو سمجھنے (نہ) لگو نماز کے پاس نہ جاؤ اور جنابت کی حالت میں بھی (نماز کے پاس نہ جاؤ) جب تک کہ غسل (نہ) کرلو ہاں اگر بحالت سفر رستے چلے جارہے ہو اور پانی نہ ملنے کے سبب غسل نہ کرسکو تو تیمم کرکے نماز پڑھ لو) اور اگر تم بیمار ہو سفر میں ہو یا تم میں سے کوئی بیت الخلاء سے ہو کر آیا ہو یا تم عورتوں سے ہم بستر ہوئے ہو اور تمہیں پانی نہ ملے تو پاک مٹی لو اور منہ اور ہاتھوں پر مسح (کرکے تیمم) کرلو بےشک خدا معاف کرنے والا اور بخشنے والا ہے', NULL, NULL, '95572a570630625e3cae66e0afb1c6f15cc2884d293758c17d99ce3421f23ee7'),
  ('ur.jalandhry', 4, 44, 537, 'بھلا تم نے ان لوگوں کو نہیں دیکھا جن کو کتاب سے حصہ دیا گیا تھا کہ وہ گمراہی کو خریدتے ہیں اور چاہتے ہیں کہ تم بھی رستے سے بھٹک جاؤ', NULL, NULL, '89a5f077c798a8599289645f57b28154dce326f0d5076efb6ea6bced64036d92'),
  ('ur.jalandhry', 4, 45, 538, 'اور خدا تمہارے دشمنوں سے خوب واقف ہے اور خدا ہی کافی کارساز ہے اور کافی مددگار ہے', NULL, NULL, '54e484d3bd939515195c08d5ba976791d93011f2e70c85398e44067eb66b76c2'),
  ('ur.jalandhry', 4, 46, 539, 'اور یہ جو یہودی ہیں ان میں سے کچھ لوگ ایسے بھی ہیں کہ کلمات کو ان کے مقامات سے بدل دیتے ہیں اور کہتے ہیں کہ ہم نے سن لیا اور نہیں مانا اور سنیئے نہ سنوائے جاؤ اور زبان کو مروڑ کر اور دین میں طعن کی راہ سے (تم سے گفتگو) کے وقت راعنا کہتے ہیں اور اگر (یوں) کہتے ہیں کہ ہم نے سن لیا اور مان لیا اور (صرف) اسمع اور (راعنا کی جگہ) انظرنا (کہتے) تو ان کے حق میں بہتر ہوتا اور بات بھی بہت درست ہوتی لیکن خدان نے ان کے کفر کے سبب ان پر لعنت کر رکھی ہے تو یہ کچھ تھوڑے ہی ایمان لاتے ہیں', NULL, NULL, '0374ee3e58a14f169a041417199bbb8703adbd998208aeea2c2cb938a3330b2c'),
  ('ur.jalandhry', 4, 47, 540, 'اے کتاب والو! قبل اس کے کہ ہم لوگوں کے مونہوں کو بگاڑ کر ان کی پیٹھ کی طرف پھیر دیں یا ان پر اس طرح لعنت کریں جس طرح ہفتے والوں پر کی تھی ہماری نازل کی ہوئی کتاب پر جو تمہاری کتاب کی بھی تصدیق کرتی ہے ایمان لے آؤ اور خدا نے جو حکم فرمایا سو (سمجھ لو کہ) ہوچکا', NULL, NULL, '3c36762d9cf2b03dc5048427411cc44bd695109ceeff3ada7b2bb5373b781217'),
  ('ur.jalandhry', 4, 48, 541, 'خدا اس گناہ کو نہیں بخشے گا کہ کسی کو اس کا شریک بنایا جائے اور اس کے سوا اور گناہ جس کو چاہے معاف کردے اور جس نے خدا کا شریک مقرر کیا اس نے بڑا بہتان باندھا', NULL, NULL, 'bfd24804dc922f3849509e51509bb57c3fcc876ef161f1a8f64bb671359dfe64'),
  ('ur.jalandhry', 4, 49, 542, 'کیا تم نے ان لوگوں کو نہیں دیکھا جو اپنے تئیں پاکیزہ کہتے ہیں (نہیں) بلکہ خدا ہی جس کو چاہتا ہے پاکیزہ کرتا ہے اور ان پر دھاگے کے برابر بھی ظلم نہیں ہوگا', NULL, NULL, 'ae46fdb7ad9b271fb43c39ac8a5ab74ebd7afcc7f6ad2326af9f35c8e446176c'),
  ('ur.jalandhry', 4, 50, 543, 'دیکھو یہ خدا پر کیسا جھوٹ (طوفان) باندھتے ہیں اور یہی گناہ صریح کافی ہے', NULL, NULL, '86aa01f5931a4cee62fb67ad9a0c432978331c74ea0850a7cd587f9b844134fa'),
  ('ur.jalandhry', 4, 51, 544, 'بھلا تم نے ان لوگوں کو نہیں دیکھا جن کو کتاب سے حصہ دیا گیا ہے کہ بتوں اور شیطان کو مانتے ہیں اور کفار کے بارے میں کہتے ہیں کہ یہ لوگ مومنوں کی نسبت سیدھے رستے پر ہیں', NULL, NULL, 'bb5ccdb4cd6cd7d561eb08fcf611e1ec3134f25e8d39ee8de0878144dd78f2c1'),
  ('ur.jalandhry', 4, 52, 545, 'یہی لوگ ہیں جن پر خدا نے لعنت کی ہے اور جس پر خدا لعنت کرے تو تم اس کا کسی کو مددگار نہ پاؤ گے', NULL, NULL, 'e403e287f84eaa455ebcca5d8ac06f3655c2af7e3ef4f807f162cf8d22d0b999'),
  ('ur.jalandhry', 4, 53, 546, 'کیا ان کے پاس بادشاہی کا کچھ حصہ ہے تو لوگوں کو تل برابر بھی نہ دیں گے', NULL, NULL, 'a60f8ff016561e3dd710ce329a93fc39da5a47af83bcc0eb31c85d7b5b9d1309'),
  ('ur.jalandhry', 4, 54, 547, 'یا جو خدا نے لوگوں کو اپنے فضل سے دے رکھا ہے اس کا حسد کرتے ہیں تو ہم نے خاندان ابراہیم ؑ کو کتاب اور دانائی عطا فرمائی تھی اور سلطنت عظیم بھی بخشی تھی', NULL, NULL, '1fd20064fef998afeecb5889d39ead266e34405abaef7093fc4cd798b2463c06'),
  ('ur.jalandhry', 4, 55, 548, 'پھر لوگوں میں سے کسی نے تو اس کتاب کو مانا اور کوئی اس سے رکا (اور ہٹا) رہا تو نہ ماننے والوں (کے جلانے) کو دوزخ کی جلتی ہوئی آگ کافی ہے', NULL, NULL, 'f74581354b2cfd2300489f80e7ce6ee2d0e66df2a4d58ac16ec6e0e997eaf018'),
  ('ur.jalandhry', 4, 56, 549, 'جن لوگوں نے ہماری آیتوں سے کفر کیا ان کو ہم عنقریب آگ میں داخل کریں گے جب ان کی کھالیں گل (اور جل) جائیں گی تو ہم اور کھالیں بدل دیں گے تاکہ (ہمیشہ) عذاب (کا مزہ چکھتے) رہیں بےشک خدا غالب حکمت والا ہے', NULL, NULL, '3edd30d7d9722f997ec0333ff035a0eeba068bf29e01b5f8a8dc02afe5fb4ef7'),
  ('ur.jalandhry', 4, 57, 550, 'اور جو ایمان لائے اور نیک عمل کرتے رہے ان کو ہم بہشتوں میں داخل کریں گے جن کے نیچے نہریں بہہ رہی ہیں وہ ان میں ہمیشہ ہمیشہ رہیں گے وہاں ان کے لئے پاک بیبیاں ہیں اور ان کو ہم گھنے سائے میں داخل کریں گے', NULL, NULL, '21608bd0c456fb321fef79918227c9ec81160746f7efede73eee80b504fbf313'),
  ('ur.jalandhry', 4, 58, 551, 'خدا تم کو حکم دیتا ہے کہ امانت والوں کی امانتیں ان کے حوالے کردیا کرو اور جب لوگوں میں فیصلہ کرنے لگو تو انصاف سے فیصلہ کیا کرو خدا تمہیں بہت خوب نصیحت کرتا ہے بےشک خدا سنتا اور دیکھتا ہے', NULL, NULL, '3817e0a79f042c453d72cda840b5a2c1b74e9c5c84aa613519f63975e5b3cda2'),
  ('ur.jalandhry', 4, 59, 552, 'مومنو! خدا اور اس کے رسول کی فرمانبرداری کرو اور جو تم میں سے صاحب حکومت ہیں ان کی بھی اور اگر کسی بات میں تم میں اختلاف واقع ہو تو اگر خدا اور روز آخرت پر ایمان رکھتے ہو تو اس میں خدا اور اس کے رسول (کے حکم) کی طرف رجوع کرو یہ بہت اچھی بات ہے اور اس کا مآل بھی اچھا ہے', NULL, NULL, '9e1de95e1a258b4943749498ca4ca83cadea5ca36d7776b63e1f72c22d4f8cdd'),
  ('ur.jalandhry', 4, 60, 553, 'کیا تم نے ان لوگوں کو نہیں دیکھا جو دعویٰ تو یہ کرتے ہیں کہ جو (کتاب) تم پر نازل ہوئی اور جو (کتابیں) تم سے پہلے نازل ہوئیں ان سب پر ایمان رکھتے ہیں اور چاہتے یہ ہیں کہ اپنا مقدمہ ایک سرکش کے پاس لے جا کر فیصلہ کرائیں حالانکہ ان کو حکم دیا گیا تھا کہ اس سے اعتقاد نہ رکھیں اور شیطان (تو یہ) چاہتا ہے کہ ان کو بہکا کر رستے سے دور ڈال دے', NULL, NULL, 'd252df5f81ffbc030a4fe164c3714e119d1da9c5c9b3d3d73e8c51e3a148af1e'),
  ('ur.jalandhry', 4, 61, 554, 'اور جب ان سے کہا جاتا ہے کہ جو حکم خدا نے نازل فرمایا ہے اس کی طرف (رجوع کرو) اور پیغمبر کی طرف آؤ تو تم منافقوں کو دیکھتے ہو کہ تم سے اعراض کرتے اور رکے جاتے ہیں', NULL, NULL, '0bee3f681e6714f01c33cf3c6d9f2025614050f689ba9f85fc0ce48a05ddae2a'),
  ('ur.jalandhry', 4, 62, 555, 'تو کیسی (ندامت کی) بات ہے کہ جب ان کے اعمال (کی شامت سے) ان پر کوئی مصیبت واقع ہوتی ہے تو تمہارے پاس بھاگے آتے ہیں اور قسمیں کھاتے ہیں کہ والله ہمارا مقصود تو بھلائی اور موافقت تھا', NULL, NULL, '618a8a3785e296635a5bc3b737fd3bdcdc2e98cdb0af4ba5dfe41cfe855f2942'),
  ('ur.jalandhry', 4, 63, 556, 'ان لوگوں کے دلوں میں جو کچھ ہے خدا اس کو خوب جانتا ہے تم ان (کی باتوں) کو کچھ خیال نہ کرو اور انہیں نصیحت کرو اور ان سے ایسی باتیں کہو جو ان کے دلوں میں اثر کر جائیں', NULL, NULL, '72042688095d6bb44eb0027e4d79fbf2f1f1727c1e04172b316eb9cc5263bca6'),
  ('ur.jalandhry', 4, 64, 557, 'اور ہم نے جو پیغمبر بھیجا ہے اس لئے بھیجا ہے کہ خدا کے فرمان کے مطابق اس کا حکم مانا جائے اور یہ لوگ جب اپنے حق میں ظلم کر بیٹھے تھے اگر تمہارے پاس آتے اور خدا سے بخشش مانگتے اور رسول (خدا) بھی ان کے لئے بخشش طلب کرتے تو خدا کو معاف کرنے والا (اور) مہربان پاتے', NULL, NULL, '87d3ac8f406187530d0579359186ceb49e5e146ffb248d300967bbea6d670a58'),
  ('ur.jalandhry', 4, 65, 558, 'تمہارے پروردگار کی قسم یہ لوگ جب تک اپنے تنازعات میں تمہیں منصف نہ بنائیں اور جو فیصلہ تم کردو اس سے اپنے دل میں تنگ نہ ہوں بلکہ اس کو خوشی سے مان لیں تب تک مومن نہیں ہوں گے', NULL, NULL, 'aa6246572ed815b8caff5285d009482892cfec7a192f0dbfffa55c060e554d13'),
  ('ur.jalandhry', 4, 66, 559, 'اور اگر ہم انہیں حکم دیتے کہ اپنے آپ کو قتل کر ڈالو یا اپنے گھر چھوڑ کر نکل جاؤ تو ان میں سے تھوڑے ہی ایسا کرتے اور اگر یہ اس نصیحت پر کاربند ہوتے جو ان کو کی جاتی ہے تو ان کے حق میں بہتر اور (دین میں) زیادہ ثابت قدمی کا موجب ہوتا', NULL, NULL, 'e600fecf0adfbd1ae24fd426645285a74cac4500b6982af41669c6b8603d4211'),
  ('ur.jalandhry', 4, 67, 560, 'اور ہم ان کو اپنے ہاں سے اجر عظیم بھی عطا فرماتے', NULL, NULL, 'c3ba8b1974382d2b342f55fdf13d303e80a4b16b256996b35f826422333c168e'),
  ('ur.jalandhry', 4, 68, 561, 'اور سیدھا رستہ بھی دکھاتے', NULL, NULL, 'e9978cab61b6bce752d2e03cbb2a3d14ad3c09c721d00f2de9727ad0aa63438c'),
  ('ur.jalandhry', 4, 69, 562, 'اور جو لوگ خدا اور اس کے رسول کی اطاعت کرتے ہیں وہ (قیامت کے روز) ان لوگوں کے ساتھ ہوں گے جن پر خدا نے بڑا فضل کیا یعنی انبیاء اور صدیق اور شہید اور نیک لوگ اور ان لوگوں کی رفاقت بہت ہی خوب ہے', NULL, NULL, '2e622318646349e333b256cb4645d93e713e6f528d00ce668402971e423033e4'),
  ('ur.jalandhry', 4, 70, 563, 'یہ خدا کا فضل ہے اور خدا جاننے والا کافی ہے', NULL, NULL, '87840bbe83dd7ff4390eb2411d1a117a8faaac4b3cd183d8f427964e21d83009'),
  ('ur.jalandhry', 4, 71, 564, 'مومنو! (جہاد کے لئے) ہتھیار لے لیا کرو پھر یا تو جماعت جماعت ہو کر نکلا کرو یا سب اکھٹے کوچ کیا کرو', NULL, NULL, '0a46464356ee428181034331e2ca28120e542595dd26d96a7c32e977e9cd32e0'),
  ('ur.jalandhry', 4, 72, 565, 'اور تم میں کوئی ایسا بھی ہے کہ (عمداً) دیر لگاتا ہے۔ پھر اگر تم پر کوئی مصیبت پڑ جائے تو کہتا ہے کہ خدا نے مجھ پر بڑی مہربانی کی کہ میں ان میں موجود نہ تھا', NULL, NULL, 'cdb4e1412402c28f480cb2439279b09a5e5bc0c96525084b419600ae251fc117'),
  ('ur.jalandhry', 4, 73, 566, 'اور اگر خدا تم پر فضل کرے تو اس طرح سے کہ گویا تم میں اس میں دوستی تھی ہی نہیں (کہ افسوس کرتا اور) کہتا ہے کہ کاش میں بھی ان کے ساتھ ہوتا تو مقصد عظیم حاصل کرتا', NULL, NULL, 'b1193235932af2ac10a197549d9d889e47e2ab53ad380f8e1bfdd63b4f1656d9'),
  ('ur.jalandhry', 4, 74, 567, 'تو جو لوگ آخرت (کو خریدتے اور اس) کے بدلے دنیا کی زندگی کو بیچنا چاہتے ہیں اُن کو چاہیئے کہ خدا کی راہ میں جنگ کریں اور جو شخص خدا کی راہ میں جنگ کرے اور شہید ہوجائے یا غلبہ پائے ہم عنقریب اس کو بڑا ثواب دیں گے', NULL, NULL, '966a09249e77af5425b1e1b1142dedd11ab005f8e0ec79b3628a1a7e5206aeee'),
  ('ur.jalandhry', 4, 75, 568, 'اور تم کو کیا ہوا ہے کہ خدا کی راہ میں اور اُن بےبس مردوں اور عورتوں اور بچوں کی خاطر نہیں لڑتے جو دعائیں کیا کرتے ہیں کہ اے پروردگار ہم کو اس شہر سے جس کے رہنے والے ظالم ہیں نکال کر کہیں اور لے جا۔ اور اپنی طرف سے کسی کو ہمارا حامی بنا۔ اور اپنی ہی طرف سے کسی کو ہمارا مددگار مقرر فرما', NULL, NULL, '8425cbe3d32b8e8ac16d4e5fd49f123ce2609f1dfb547a108d5c9558eca8af23'),
  ('ur.jalandhry', 4, 76, 569, 'جو مومن ہیں وہ تو خدا کے لئے لڑتے ہیں اور جو کافر ہیں وہ بتوں کے لئے لڑتے ہیں سو تم شیطان کے مددگاروں سے لڑو۔ (اور ڈرو مت) کیونکہ شیطان کا داؤ بودا ہوتا ہے', NULL, NULL, '3b568c9c98f9bc9012a5b2efc9fe6e1fe5866e500297b334744eede3a282f8f3'),
  ('ur.jalandhry', 4, 77, 570, 'بھلا تم نے ان لوگوں کو نہیں دیکھا جن کو (پہلے یہ) حکم دیا گیا تھا کہ اپنے ہاتھوں کو (جنگ سے) روکے رہو اور نماز پڑھتے رہو اور زکوٰة دیتے رہو پھر جب ان پر جہاد فرض کردیا گیا تو بعض لوگ ان میں سے لوگوں سے یوں ڈرنے لگے جیسے خدا سے ڈرا کرتے ہیں بلکہ اس سے بھی زیادہ اور بڑبڑانے لگے کہ اے خدا تو نے ہم پر جہاد (جلد) کیوں فرض کردیا تھوڑی مدت اور ہمیں کیوں مہلت نہ دی (اے پیغمبر ان س) ے کہہ دو کہ دنیا کا فائدہ بہت تھوڑا ہے اور بہت اچھی چیز تو پرہیزگار کے لئے (نجات) آخرت ہے اور تم پر دھاگے برابر بھی ظلم نہیں کیا جائے گا', NULL, NULL, 'fd253806740ab41d765528b1d18a393feedb68f295e6391a3cfaddc005d8087b'),
  ('ur.jalandhry', 4, 78, 571, '(اے جہاد سے ڈرنے والو) تم کہیں رہو موت تو تمہیں آ کر رہے گی خواہ بڑے بڑے محلوں میں رہو اور ان لوگوں کو اگر کوئی فائدہ پہنچتا ہے تو کہتے ہیں یہ خدا کی طرف سے ہے اور اگر کوئی گزند پہنچتا ہے تو (اے محمدﷺ تم سے) کہتے ہیں کہ یہ گزند آپ کی وجہ سے (ہمیں پہنچا) ہے کہہ دو کہ (رنج وراحت) سب الله ہی کی طرف سے ہے ان لوگوں کو کیا ہوگیا ہے کہ بات بھی نہیں سمجھ سکتے', NULL, NULL, '3d7f55b316a05d4bdee98bdfafdd680e2c33fbbc5b7ad5e937946dfa4cb186b9'),
  ('ur.jalandhry', 4, 79, 572, 'اے (آدم زاد) تجھ کو جو فائدہ پہنچے وہ خدا کی طرف سے ہے اور جو نقصان پہنچے وہ تیری ہی (شامت اعمال) کی وجہ سے ہے اور (اے محمدﷺ) ہم نے تم کو لوگوں (کی ہدایت) کے لئے پیغمبر بنا کر بھیجا ہے اور (اس بات کا) خدا ہی گواہ کافی ہے', NULL, NULL, '32a80a8b95108137b27a5d00d2f9cb23eb520d46f2b800924cc621fe67c22797'),
  ('ur.jalandhry', 4, 80, 573, 'جو شخص رسول کی فرمانبرداری کرے گا تو بےشک اس نے خدا کی فرمانبرداری کی اور جو نافرمانی کرے گا تو اے پیغمبر تمہیں ہم نے ان کا نگہبان بنا کر نہیں بھیجا', NULL, NULL, 'defe2223e73e188f3f4dd8a597b73f1eb4d88181364fc99e4d154c8b04568cbb'),
  ('ur.jalandhry', 4, 81, 574, 'اور یہ لوگ منہ سے تو کہتے ہیں کہ (آپ کی) فرمانبرداری (دل سے منظور ہے) لیکن جب تمہارے پاس سے چلے جاتے ہیں تو ان میں سے بعض لوگ رات کو تمہاری باتوں کے خلاف مشورے کرتے ہیں اور جو مشورے یہ کرتے ہیں خدا ان کو لکھ لیتا ہے تو ان کا کچھ خیال نہ کرو اور خدا پر بھروسہ رکھو اور خدا ہی کافی کارساز ہے', NULL, NULL, '92eb69d80c894730f42393a371fd1332fbc27b808ac11509d96e512a32df5853'),
  ('ur.jalandhry', 4, 82, 575, 'بھلا یہ قرآن میں غور کیوں نہیں کرتے؟ اگر یہ خدا کے سوا کسی اور کا (کلام) ہوتا تو اس میں (بہت سا) اختلاف پاتے', NULL, NULL, 'c5203a4ee644173f90e805c20129762c15ea532c9c593ea13790760bf357424d'),
  ('ur.jalandhry', 4, 83, 576, 'اور جب ان کے پاس امن یا خوف کی کوئی خبر پہنچتی ہے تو اس کو مشہور کردیتے ہیں اور اگر اس کو پیغمبر اور اپنے سرداروں کے پاس پہنچاتے تو تحقیق کرنے والے اس کی تحقیق کر لیتے اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو چند اشخاص کے سوا سب شیطان کے پیرو ہوجاتے', NULL, NULL, '069ca13ff858107e5eb7fc454fb9e27827c456ec36122febf793e2ab9188ee0b'),
  ('ur.jalandhry', 4, 84, 577, 'تو (اے محمدﷺ) تم خدا کی راہ میں لڑو تم اپنے سوا کسی کے ذمہ دار نہیں اور مومنوں کو بھی ترغیب دو قریب ہے کہ خدا کافروں کی لڑائی کو بند کردے اور خدا لڑائی کے اعتبار سے بہت سخت ہے اور سزا کے لحاظ سے بھی بہت سخت ہے', NULL, NULL, '81388443280d2910b9d9fe3b72cac937060c7f2e8ca3179623e8892bb544fb56'),
  ('ur.jalandhry', 4, 85, 578, 'جو شخص نیک بات کی سفارش کرے تو اس کو اس (کے ثواب) میں سے حصہ ملے گا اور جو بری بات کی سفارش کرے اس کو اس (کے عذاب) میں سے حصہ ملے گا اور خدا ہر چیز پر قدرت رکھتا ہے', NULL, NULL, 'a506aa04a3521f5cd16cfe5be9b2a2a0e5892de5e63a06cb371fce637a931004'),
  ('ur.jalandhry', 4, 86, 579, 'اور جب تم کو کوئی دعا دے تو (جواب میں) تم اس سے بہتر (کلمے) سے (اسے) دعا دو یا انہیں لفظوں سے دعا دو بےشک خدا ہر چیز کا حساب لینے والا ہے', NULL, NULL, '6d276afa3d001167c6c3c8a3b852690ef3b8d5c0b986a778e0c9e1bf2318d8d4'),
  ('ur.jalandhry', 4, 87, 580, 'خدا (وہ معبود برحق ہے کہ) اس کے سوا کوئی عبادت کے لائق نہیں وہ قیامت کے دن تم سب کو ضرور جمع کرے گا اور خدا سے بڑھ کر بات کا سچا کون ہے؟', NULL, NULL, 'c39181dada5a3750d5dbc3a859307d50a223a425be3fdfb66949c9e19d4e05d1'),
  ('ur.jalandhry', 4, 88, 581, 'تو کیا سبب ہے کہ تم منافقوں کے بارے میں دو گروہ ہو رہے ہو حالانکہ خدا نے ان کو ان کے کرتوتوں کے سبب اوندھا کردیا ہے کیا تم چاہتے ہو کہ جس شخص کو خدا نے گمراہ کردیا ہے اس کو رستے پر لے آؤ اور جس شخص کو خدا گمراہ کردے تو اس کے لئے کبھی بھی رستہ نہیں پاؤ گے', NULL, NULL, '1eb12137353f69796c02cb5236c83cf3a0596ed1788bdc7545cea74cc3b58c0b'),
  ('ur.jalandhry', 4, 89, 582, 'وہ تو یہی چاہتے ہیں کہ جس طرح وہ خود کافر ہیں (اسی طرح) تم بھی کافر ہو کر (سب) برابر ہوجاؤ تو جب تک وہ خدا کی راہ میں وطن نہ چھوڑ جائیں ان میں سے کسی کو دوست نہ بنانا اگر (ترک وطن کو) قبول نہ کریں تو ان کو پکڑ لو اور جہاں پاؤ قتل کردو اور ان میں سے کسی کو اپنا رفیق اور مددگار نہ بناؤ', NULL, NULL, '88d016beb9331776a9ce094141a61bec35d1f7099fa85f37fd747db348e6d5df'),
  ('ur.jalandhry', 4, 90, 583, 'مگر جو لوگ ایسے لوگوں سے جا ملے ہوں جن میں اور تم میں (صلح کا) عہد ہو یا اس حال میں کہ ان کے دل تمہارے ساتھ یا اپنی قوم کے ساتھ لڑنے سے رک گئے ہوں تمہارے پاس آجائیں (تو احتراز ضروری نہیں) اور اگر خدا چاہتا تو ان کو تم پر غالب کردیتا تو وہ تم سے ضرور لڑتے پھر اگر وہ تم سے (جنگ کرنے سے) کنارہ کشی کریں اور لڑیں نہیں اور تمہاری طرف صلح (کا پیغام) بھیجیں تو خدا نے تمہارے لئے ان پر (زبردستی کرنے کی) کوئی سبیل مقرر نہیں کی', NULL, NULL, 'c691d007dce02a3040f1764a9e386754cf6555fe6db644d72051feb176137534'),
  ('ur.jalandhry', 4, 91, 584, 'تم کچھ اور لوگ ایسے بھی پاؤ گے جو یہ چاہتے ہیں کہ تم سے بھی امن میں رہیں اور اپنی قوم سے بھی امن میں رہیں لیکن فتنہ انگیزی کو بلائے جائیں تو اس میں اوندھے منہ گر پڑیں تو ایسے لوگ اگر تم سے (لڑنے سے) کنارہ کشی نہ کریں اور نہ تمہاری طرف (پیغام) صلح بھیجیں اور نہ اپنے ہاتھوں کو روکیں تو ان کو پکڑ لو اور جہاں پاؤ قتل کردو ان لوگوں کے مقابلے میں ہم نے تمہارے لئے سند صریح مقرر کردی ہے', NULL, NULL, 'e0448ae3ab2abc1e1757b64da9d538c83b005e8dfafafcfe7ae38b8b8470c9ed'),
  ('ur.jalandhry', 4, 92, 585, 'اور کسی مومن کو شایان نہیں کہ مومن کو مار ڈالے مگر بھول کر اور جو بھول کر بھی مومن کو مار ڈالے تو (ایک تو) ایک مسلمان غلام آزاد کردے اور (دوسرے) مقتول کے وارثوں کو خون بہا دے ہاں اگر وہ معاف کردیں (تو ان کو اختیار ہے) اگر مقتول تمہارے دشمنوں کی جماعت میں سے ہو اور وہ خود مومن ہو تو صرف ایک مسلمان غلام آزاد کرنا چاہیئے اور اگر مقتول ایسے لوگوں میں سے ہو جن میں اور تم میں صلح کا عہد ہو تو وارثان مقتول کو خون بہا دینا اور ایک مسلمان غلام آزاد کرنا چاہیئے اور جس کو یہ میسر نہ ہو وہ متواتر دو مہینے کے روزے رکھے یہ (کفارہ) خدا کی طرف سے (قبول) توبہ (کے لئے) ہے اور خدا (سب کچھ) جانتا اور بڑی حکمت والا ہے', NULL, NULL, '5b5d97ae6a5ee10d3ae0691d336ba0b7d3bc2dd90d945eecb84258c0918321e8'),
  ('ur.jalandhry', 4, 93, 586, 'اور جو شخص مسلمان کو قصداً مار ڈالے گا تو اس کی سزا دوزخ ہے جس میں وہ ہمیشہ (جلتا) رہے گا اور خدا اس پر غضبناک ہوگا اور اس پر لعنت کرے گا اور ایسے شخص کے لئے اس نے بڑا (سخت) عذاب تیار کر رکھا ہے', NULL, NULL, '5a0509f7ae688d9dca65197096e6df640dea31824406cd272d39ced27bd8d241'),
  ('ur.jalandhry', 4, 94, 587, 'مومنو! جب تم خدا کی راہ میں باہر نکلو کرو تو تحقیق سے کام لیا کرو اور جو شخص تم سے سلام علیک کرے اس سے یہ نہ کہو کہ تم مومن نہیں اور اس سے تمہاری غرض یہ ہو کہ دنیا کی زندگی کا فائدہ حاصل کرو سو خدا کے نزدیک بہت سے غنیمتیں ہیں تم بھی تو پہلے ایسے ہی تھے پھر خدا نے تم پر احسان کیا تو (آئندہ) تحقیق کرلیا کرو اور جو عمل تم کرتے ہو خدا کو سب کی خبر ہے', NULL, NULL, 'e90524163f0eda83fd2c57e0c80c0414d18793124e28ac91cf3ba228a081684b'),
  ('ur.jalandhry', 4, 95, 588, 'جو مسلمان (گھروں میں) بیٹھ رہتے (اور لڑنے سے جی چراتے) ہیں اور کوئی عذر نہیں رکھتے وہ اور جو خدا کی راہ میں اپنے مال اور جان سے لڑتے ہیں وہ دونوں برابر نہیں ہو سکتے خدا نے مال اور جان سے جہاد کرنے والوں کو بیٹھ رہنے والوں پر درجے میں فضیلت بخشی ہے اور (گو) نیک وعدہ سب سے ہے لیکن اجر عظیم کے لحاظ سے خدا نے جہاد کرنے والوں کو بیٹھ رہنے والوں پر کہیں فضیلت بخشی ہے', NULL, NULL, 'bbbfe1fb8038f3a05b37822a316b8451585b814b0eab54f42a377871b8083f34'),
  ('ur.jalandhry', 4, 96, 589, '(یعنی) خدا کی طرف سے درجات میں اور بخشش میں اور رحمت میں اور خدا بڑا بخشنے والا (اور) مہربان ہے', NULL, NULL, 'b434b05c9b400fb8390734c2238204aa12fce40b108ccb831b3eb6ac66fc246b'),
  ('ur.jalandhry', 4, 97, 590, 'اور جو لوگ اپنی جانوں پر ظلم کرتے ہیں جب فرشتے ان کی جان قبض کرنے لگتے ہیں تو ان سے پوچھتے ہیں کہ تم کس حال میں تھے وہ کہتے ہیں کہ ہم ملک میں عاجز وناتواں تھے فرشتے کہتے ہیں کیا خدا کا ملک فراخ نہیں تھا کہ تم اس میں ہجرت کر جاتے ایسے لوگوں کا ٹھکانہ دوزخ ہے اور وہ بری جگہ ہے', NULL, NULL, '5be16992d572e6ea121afe7ed7807808e6c1412d948f71ca162f4f7c897d57bb'),
  ('ur.jalandhry', 4, 98, 591, 'ہاں جو مرد اور عورتیں اور بچے بےبس ہیں کہ نہ تو کوئی چارہ کر سکتے ہیں اور نہ رستہ جانتے ہیں', NULL, NULL, '242c804acb47af0e12ed7c71d8183bbe05af36ca9f5abbe0ced7a82066ec8af2'),
  ('ur.jalandhry', 4, 99, 592, 'قریب ہے کہ خدا ایسوں کو معاف کردے اور خدا معاف کرنے والا (اور) بخشنے والا ہے', NULL, NULL, 'd905d80cdc3aa7083ac55b3935abcb4b3ac138833d65619ac01d9e864b9045f3'),
  ('ur.jalandhry', 4, 100, 593, 'اور جو شخص خدا کی راہ میں گھر بار چھوڑ جائے وہ زمین میں بہت سی جگہ اور کشائش پائے گا اور جو شخص خدا اور رسول کی طرف ہجرت کرکے گھر سے نکل جائے پھر اس کو موت آپکڑے تو اس کا ثواب خدا کے ذمے ہوچکا اور خدا بخشنے والا اور مہربان ہے', NULL, NULL, '439e09a464037e40beac3ab980a62a7243ed0d9f548ad77c65f105a3aa9ada91'),
  ('ur.jalandhry', 4, 101, 594, 'اور جب تم سفر کو جاؤ تو تم پر کچھ گناہ نہیں کہ نماز کو کم کرکے پڑھو بشرطیکہ تم کو خوف ہو کہ کافر لوگ تم کو ایذا دیں گے بےشک کافر تمہارے کھلے دشمن ہیں', NULL, NULL, '60fec5a35b703d27cb5d1c2206659a22314226f1c3b1527fb81adaec63ff44da'),
  ('ur.jalandhry', 4, 102, 595, 'اور (اے پیغمبر) جب تم ان (مجاہدین کے لشکر) میں ہو اور ان کو نماز پڑھانے لگو تو چاہیئے کہ ان کی ایک جماعت تمہارے ساتھ مسلح ہو کر کھڑی رہے جب وہ سجدہ کرچکیں تو پرے ہو جائیں پھر دوسری جماعت جس نے نماز نہیں پڑھی (ان کی جگہ) آئے اور ہوشیار اور مسلح ہو کر تمہارے ساتھ نماز ادا کرے کافر اس گھات میں ہیں کہ تم ذرا اپنے ہتھیاروں اور سامان سے غافل ہو جاؤ تو تم پر یکبارگی حملہ کردیں اگر تم بارش کے سبب تکلیف میں یا بیمار ہو تو تم پر کچھ گناہ نہیں کہ ہتھیار اتار رکھو مگر ہوشیار ضرور رہنا خدا نے کافروں کے لئے ذلت کا عذاب تیار کر رکھا ہے', NULL, NULL, '84d7c780e1f77554b06969f093b18b8d806eaedc8d9a30bce589c1c134ff0e2c'),
  ('ur.jalandhry', 4, 103, 596, 'پھر جب تم نماز تمام کرچکو تو کھڑے اور بیٹھے اور لیٹے (ہر حالت میں) خدا کو یاد کرو پھر جب خوف جاتا رہے تو (اس طرح سے) نماز پڑھو (جس طرح امن کی حالت میں پڑھتے ہو) بےشک نماز کا مومنوں پر اوقات (مقررہ) میں ادا کرنا فرض ہے', NULL, NULL, '1de2b85a9c46b54cabfd1fbdf242240d947c439287d2446f32adecf3845fbd4f'),
  ('ur.jalandhry', 4, 104, 597, 'اور کفار کا پیچھا کرنے میں سستی نہ کرنا اگر تم بےآرام ہوتے ہو تو جس طرح تم بےآرام ہوتے ہو اسی طرح وہ بھی بےآرام ہوتے ہیں اور تم خدا سے ایسی ایسی امیدیں رکھتے ہو جو وہ نہیں رکھ سکتے اور خدا سب کچھ جانتا اور (بڑی) حکمت والا ہے', NULL, NULL, '0edaa0d817e4db29107864e40f90434404633a2132a011b4faff01b88300bb70'),
  ('ur.jalandhry', 4, 105, 598, '(اے پیغمبر) ہم نے تم پر سچی کتاب نازل کی ہے تاکہ خدا کی ہدایت کے مطابق لوگوں کے مقدمات میں فیصلہ کرو اور (دیکھو) دغابازوں کی حمایت میں کبھی بحث نہ کرنا', NULL, NULL, '66e1fad77b63f5f2d6b57950e9eadce79dc891637e21212f1d709c84fc047cfd'),
  ('ur.jalandhry', 4, 106, 599, 'اور خدا سے بخشش مانگنا بےشک خدا بخشنے والا مہربان ہے', NULL, NULL, 'b85aa4202a99ec7210860735ac66e876e569b1575662901e5c5885eaa2c0d4d2'),
  ('ur.jalandhry', 4, 107, 600, 'اور لوگ اپنے ہم جنسوں کی خیانت کرتے ہیں ان کی طرف سے بحث نہ کرنا کیونکہ خدا خائن اور مرتکب جرائم کو دوست نہیں رکھتا', NULL, NULL, '7feff85b92e40ee4196db34f500099dcdd0dcd260ee0aa761ec8f6c96d05400e')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 4, 108, 601, 'یہ لوگوں سے تو چھپتے ہیں اور خدا سے نہیں چھپتے حالانکہ جب وہ راتوں کو ایسی باتوں کے مشورے کیا کرتے ہیں جن کو وہ پسند نہیں کرتا ان کے ساتھ ہوا کرتا ہے اور خدا ان کے (تمام) کاموں پر احاطہ کئے ہوئے ہے', NULL, NULL, '1d4332b20f42a9a91304db087af4bc0008ab1cd3da1ed984926d65ee3376b6e1'),
  ('ur.jalandhry', 4, 109, 602, 'بھلا تم لوگ دنیا کی زندگی میں تو ان کی طرف سے بحث کر لیتے ہو قیامت کو ان کی طرف سے خدا کے ساتھ کون جھگڑے گا اور کون ان کا وکیل بنے گا؟', NULL, NULL, '5d9ecf08d57ad34eae4fb4d69e6f3a27b509de75fcb860e487f1c10a82f03448'),
  ('ur.jalandhry', 4, 110, 603, 'اور جو شخص کوئی برا کام کر بیٹھے یا اپنے حق میں ظلم کرلے پھر خدا سے بخشش مانگے تو خدا کو بخشنے والا اور مہربان پائے گا', NULL, NULL, 'da4982620d931c6cdcc63b57ce10fe5e503c6469c1b8727aea22203e9fd5c3e6'),
  ('ur.jalandhry', 4, 111, 604, 'اور جو کوئی گناہ کرتا ہے تو اس کا وبال اسی پر ہے اور خدا جاننے والا (اور) حکمت والا ہے', NULL, NULL, '33a7753f47075c9bf291f6b4b0eab17feca0a1a0deb8c496d681299f212403b7'),
  ('ur.jalandhry', 4, 112, 605, 'اور جو شخص کوئی قصور یا گناہ تو خود کرے لیکن اس سے کسی بےگناہ کو مہتم کردے تو اس نے بہتان اور صریح گناہ کا بوجھ اپنے سر پر رکھا', NULL, NULL, 'c56135c1ce545b72a97fad733fb4469952037f3f09e82dcf485a3fbc98b0e157'),
  ('ur.jalandhry', 4, 113, 606, 'اور اگر تم پر خدا کا فضل اور مہربانی نہ ہوتی تو ان میں سے ایک جماعت تم کو بہکانے کا قصد کر ہی چکی تھی اور یہ اپنے سوا (کسی کو) بہکا نہیں سکتے اور نہ تمہارا کچھ بگاڑ سکتے ہیں اور خدا نے تم پر کتاب اور دانائی نازل فرمائی ہے اور تمہیں وہ باتیں سکھائی ہیں جو تم جانتے نہیں تھے اور تم پر خدا کا بڑا فضل ہے', NULL, NULL, '7f3cd3851dec72f45fb67298fce7fdfd3dde233b40c76992c63cdcc145d95dce'),
  ('ur.jalandhry', 4, 114, 607, 'ان لوگوں کی بہت سی مشورتیں اچھی نہیں ہاں (اس شخص کی مشورت اچھی ہوسکتی ہے) جو خیرات یا نیک بات یا لوگوں میں صلح کرنے کو کہے اور جو ایسے کام خدا کی خوشنودی حاصل کرنے کے لئے کرے گا تو ہم اس کو بڑا ثواب دیں گے', NULL, NULL, 'c881afbe2b5b52ed0f0a96fe09e71713933825d62ebdb64af2851acaea217bee'),
  ('ur.jalandhry', 4, 115, 608, 'اور جو شخص سیدھا رستہ معلوم ہونے کے بعد پیغمبر کی مخالف کرے اور مومنوں کے رستے کے سوا اور رستے پر چلے تو جدھر وہ چلتا ہے ہم اسے ادھر ہی چلنے دیں گے اور (قیامت کے دن) جہنم میں داخل کریں گے اور وہ بری جگہ ہے', NULL, NULL, '9ed35b8c98087904d2530b6b7592a243768232ba5ab15c0de9dc845e621edc07'),
  ('ur.jalandhry', 4, 116, 609, 'خدا اس کے گناہ کو نہیں بخشے گا کہ کسی کو اس کا شریک بنایا جائے اور اس کے سوا (اور گناہ) جس کو چاہیے گا بخش دے گا۔ اور جس نے خدا کے ساتھ شریک بنایا وہ رستے سے دور جا پڑا', NULL, NULL, '2768d5a0ce7ba46c8456d77ab5e18f73b94962f24b142a0df0dac9d18130ccae'),
  ('ur.jalandhry', 4, 117, 610, 'یہ جو خدا کے سوا پرستش کرتے ہیں تو عورتوں کی اور پکارتے ہیں تو شیطان کی سرکش ہی کو', NULL, NULL, 'acc9fa7c409e4af846fc37ac8dbdbe867ab1700de838425165c301b722527e25'),
  ('ur.jalandhry', 4, 118, 611, 'جس پر خدا نے لعنت کی ہے (جو خدا سے) کہنے لگا میں تیرے بندوں سے (غیر خدا کی نذر دلوا کر مال کا) ایک مقرر حصہ لے لیا کروں گا۔', NULL, NULL, '44eb0004ca367b0cfb26eccf8aaa0a98f8ec0bc61ed4175d4014221d4c44893a'),
  ('ur.jalandhry', 4, 119, 612, 'اور ان کو گمراہ کرتا اور امیدیں دلاتا ہروں گا اور یہ سکھاتا رہوں گا کہ جانوروں کے کان چیرتے رہیں اور (یہ بھی) کہتا رہوں گا کہ وہ خدا کی بنائی ہوئی صورتوں کو بدلتے رہیں اور جس شخص نے خدا کو چھوڑ کر شیطان کو دوست بنایا اور وہ صریح نقصان میں پڑ گیا', NULL, NULL, '7d7e763df44107dd390b0de3679082df35563d9ee01e7cd5bae61a864379dd5c'),
  ('ur.jalandhry', 4, 120, 613, 'وہ ان کو وعدے دیتا رہا اور امیدیں دلاتا ہے اور جو کچھ شیطان انہیں وعدے دیتا ہے جو دھوکا ہی دھوکا ہے', NULL, NULL, '7ac2906c794f3dbddb674a1061efa1207ab4200ef296530fefd9dfc30f40e1cb'),
  ('ur.jalandhry', 4, 121, 614, 'ایسے لوگوں کا ٹھکانا جہنم ہے۔ اور وہ وہاں سے مخلصی نہیں پاسکیں گے', NULL, NULL, '604e222d5cc38ce7988e73461f51b1a0210bce83e4b885a043bcb8eec9b4d9ca'),
  ('ur.jalandhry', 4, 122, 615, 'اور جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کو ہم بہشتوں میں داخل کریں گے جن کے نیچے نہریں جاری ہیں۔ ابدالآباد ان میں رہیں گے۔ یہ خدا کا سچا وعدہ ہے۔ اور خدا سے زیادہ بات کا سچا کون ہوسکتا ہے', NULL, NULL, '02904cf67d84cd0fde32e44e3f9f0063548250a36c3c30fa06645bb1887e63da'),
  ('ur.jalandhry', 4, 123, 616, '(نجات) نہ تو تمہاری آرزوؤں پر ہے اور نہ اہل کتاب کی آرزوؤں پر۔ جو شخص برے عمل کرے گا اسے اسی (طرح) کا بدلا دیا جائے گا اور وہ خدا کے سوا نہ کسی کو حمایتی پائے گا اور نہ مددگار', NULL, NULL, 'ff183abe06eddab86d97d58a00f7d9957a5786b7a6eb34faee9db6d741e464f6'),
  ('ur.jalandhry', 4, 124, 617, 'اور جو نیک کام کرے گا مرد ہو یا عورت اور وہ صاحب ایمان بھی ہوگا تو ایسے لوگ بہشت میں داخل ہوں گے اور ان کی تل برابر بھی حق تلفی نہ کی جائے گی', NULL, NULL, '1a5bc4c3e7bdafc2a7fbdce9104225ad7dcbae458fc291e8f0209aae718b4987'),
  ('ur.jalandhry', 4, 125, 618, 'اور اس شخص سے کس کا دین اچھا ہوسکتا ہے جس نے حکم خدا کو قبول کیا اور وہ نیکوکار بھی ہے۔ اور ابراہیم کے دین کا پیرو ہے جو یکسوں (مسلمان) تھے اور خدا نے ابراہیم کو اپنا دوست بنایا تھا', NULL, NULL, '1c251b9cf563cee5166178e00f5af6fbc6ae6e2b9e991225635bc1bcb1f7a0a8'),
  ('ur.jalandhry', 4, 126, 619, 'اور آسمان وزمین میں جو کچھ ہے سب خدا ہی کا ہے۔ اور خدا ہر چیز پر احاطے کئے ہوئے ہے', NULL, NULL, '8a7e5b7aa3836b288fbd82892e0be95af3b9a19b475fe7ba66e4cb4e8f96c866'),
  ('ur.jalandhry', 4, 127, 620, '(اے پیغمبر) لوگ تم سے (یتیم) عورتوں کے بارے میں فتویٰ طلب کرتے ہیں۔ کہہ دو کہ خدا تم کو ان کے (ساتھ نکاح کرنے کے) معاملے میں اجازت دیتا ہے اور جو حکم اس کتاب میں پہلے دیا گیا ہے وہ ان یتیم عورتوں کے بارے میں ہے جن کو تم ان کا حق تو دیتے نہیں اور خواہش رکھتے ہو کہ ان کے ساتھ نکاح کرلو اور (نیز) بیچارے بیکس بچوں کے بارے میں۔ اور یہ (بھی حکم دیتا ہے) کہ یتیموں کے بارے میں انصاف پر قائم رہو۔ اور جو بھلائی تم کرو گے خدا اس کو جانتا ہے', NULL, NULL, 'dddd55e737241ba8cf4b55e5422934823237541fa6d8d587cba8194d2c492474'),
  ('ur.jalandhry', 4, 128, 621, 'اور اگر کسی عورت کو اپنے خاوند کی طرف سے زیادتی یا بےرغبتی کا اندیشہ ہو تم میاں بیوی پر کچھ گناہ نہیں کہ آپس میں کسی قرارداد پر صلح کرلیں۔ اور صلح خوب (چیز) ہے اور طبیعتیں تو بخل کی طرف مائل ہوتی ہیں اور اگر تم نیکوکاری اور پرہیزگاری کرو گے تو خدا تمہارے سب کاموں سے واقف ہے', NULL, NULL, 'd671e48b139e7067e18fec2ba6fb6c70c937fb62d7c9f24f0855e4d8e26cfad7'),
  ('ur.jalandhry', 4, 129, 622, 'اور تم خوا کتنا ہی چاہو عورتوں میں ہرگز برابری نہیں کرسکو گے تو ایسا بھی نہ کرنا کہ ایک ہی کی طرف ڈھل جاؤ اور دوسری کو (ایسی حالت میں) چھوڑ دو کہ گویا ادھر ہوا میں لٹک رہی ہے اور اگر آپس میں موافقت کرلو اور پرہیزگاری کرو تو خدا بخشنے والا مہربان ہے', NULL, NULL, 'efd0d8a3a3914fdd6e2dce49bc32b7e27c6bc903615ad35f65bec5a09bb64711'),
  ('ur.jalandhry', 4, 130, 623, 'اور اگر میاں بیوی (میں موافقت نہ ہوسکے اور) ایک دوسرے سے جدا ہوجائیں تو خدا ہر ایک کو اپنی دولت سے غنی کردے گا اور خدا بڑی کشائش والا اور حکمت والا ہے', NULL, NULL, 'ab29f70a55747c66308135e95f3084de70e65e03af1461f3ba153785c1faeab2'),
  ('ur.jalandhry', 4, 131, 624, 'اور جو کچھ آسمانوں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے۔ اور جن لوگوں کو تم سے پہلے کتاب دی گئی تھی ان کو بھی اور (اے محمدﷺ) تم کو بھی ہم نے حکم تاکیدی کیا ہے کہ خدا سے ڈرتے رہو اور اگر کفر کرو گے تو (سمجھ رکھو کہ) جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے۔ اور خدا بے پروا اور سزاوار حمدوثنا ہے', NULL, NULL, 'cd744d6bc25a12c93cce9b2594485b290add9198ce3b16f080d84d34b478f3ce'),
  ('ur.jalandhry', 4, 132, 625, 'اور (پھر سن رکھو کہ) جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب خدا ہی کا ہے اور خدا کارساز کافی ہے', NULL, NULL, '69cee0efc464f7d412da37c0e735efff3f35f978334963df4df7914c2bbbbe52'),
  ('ur.jalandhry', 4, 133, 626, 'لوگو! اگر وہ چاہے تو تم کو فنا کردے اور (تمہاری جگہ) اور لوگوں کو پیدا کردے۔اور خدا اس بات پر قادر ہے', NULL, NULL, 'c5d65382664f05b4614f7a2f4158fd3a4cbfa2ac892df978f043ebd4f8e73ca6'),
  ('ur.jalandhry', 4, 134, 627, 'جو شخص دنیا (میں عملوں) کی جزا کا طالب ہو تو خدا کے پاس دنیا اور آخرت (دونوں) کے لئے اجر (موجود) ہیں۔ اور خدا سنتا دیکھتا ہے', NULL, NULL, 'f3ed43dee1da6bcd6567725216bf8dad3b9bf4f7a19e3f8ac723b302e90590af'),
  ('ur.jalandhry', 4, 135, 628, 'اے ایمان والو! انصاف پر قائم رہو اور خدا کے لئے سچی گواہی دو خواہ (اس میں) تمہارا یا تمہارےماں باپ اور رشتہ داروں کا نقصان ہی ہو۔ اگر کوئی امیر ہے یا فقیر تو خدا ان کا خیر خواہ ہے۔ تو تم خواہش نفس کے پیچھے چل کر عدل کو نہ چھوڑ دینا۔ اگر تم پیچیدا شہادت دو گے یا (شہادت سے) بچنا چاہو گے تو (جان رکھو) خدا تمہارے سب کاموں سے واقف ہے', NULL, NULL, '95b535df3cda7f03368779732d7499ad5762d1ba6936427af6fbc019a737f65b'),
  ('ur.jalandhry', 4, 136, 629, 'مومنو! خدا پر اور اس کے رسول پر اور جو کتاب اس نے اپنی پیغمبر (آخرالزماں) پر نازل کی ہے اور جو کتابیں اس سے پہلے نازل کی تھیں سب پر ایمان لاؤ۔ اور جو شخص خدا اور اس کے فرشتوں اور اس کی کتابوں اور اس کے پیغمبروں اور روزقیامت سے انکار کرے وہ رستے سے بھٹک کر دور جا پڑا', NULL, NULL, 'eb83cb3c27f898bcaf5c62a7c8b5311ade711bebee4ad20ee5c297834c7e93ed'),
  ('ur.jalandhry', 4, 137, 630, 'جو لوگ ایمان لائے پھر کافر ہوگئے پھر ایمان لائے پھر کافر ہوگئے پھر کفر میں بڑھتے گئے ان کو خدا نہ تو بخشے گا اور نہ سیدھا رستہ دکھائے گا', NULL, NULL, '00d54b6a1949e6f4c496e5144e61d2180df99e9754dff76f7a33c0e464c956c7'),
  ('ur.jalandhry', 4, 138, 631, '(اے پیغمبر) منافقوں (یعنی دو رخے لوگوں) کو بشارت سناد دو کہ ان کے لئے دکھ دینے والا عذاب (تیار) ہے', NULL, NULL, '2b950232468c754ddc16ce10487eaf193bf6e284ec25c73dd8a73bb87684f4d2'),
  ('ur.jalandhry', 4, 139, 632, 'جو مومنوں کو چھوڑ کر کافروں کو دوست بناتے ہیں۔ کیا یہ ان کے ہاں عزت حاصل کرنا چاہتے ہیں تو عزت تو سب خدا ہی کی ہے', NULL, NULL, '74a2b9d82f42c371ffed3aaf197b82181ee0ae87cbe888db763cc96705b9a649'),
  ('ur.jalandhry', 4, 140, 633, 'اور خدا نے تم (مومنوں) پر اپنی کتاب میں (یہ حکم) نازل فرمایا ہے کہ جب تم (کہیں) سنو کہ خدا کی آیتوں سے انکار ہورہا ہے اور ان کی ہنسی اڑائی جاتی ہے تو جب تک وہ لوگ اور باتیں (نہ) کرنے لگیں۔ ان کے پاس مت بیٹھو۔ ورنہ تم بھی انہیں جیسے ہوجاؤ گے۔ کچھ شک نہیں کہ خدا منافقوں اور کافروں سب کو دوزخ میں اکھٹا کرنے والا ہے', NULL, NULL, 'aa56fd7403fbf3e5696035a921d2b3cabe489cc3985415c5ab447a75744a5617'),
  ('ur.jalandhry', 4, 141, 634, 'جو تم کو دیکھتے رہتے ہیں اگر خدا کی طرف سے تم کو فتح ملے تو کہتے ہیں کیا ہم تمہارے ساتھ نہ تھے۔ اور اگر کافروں کو (فتح) نصیب ہو تو (ان سے) کہتے ہیں کیا ہم تم پر غالب نہیں تھے اور تم کو مسلمانوں (کے ہاتھ) سے بچایا نہیں۔ تو خدا تم میں قیامت کے دن فیصلہ کردے گا۔ اور خدا کافروں کو مومنوں پر ہرگز غلبہ نہیں دے گا', NULL, NULL, '21c7d41d8921fa62df8b988021cf173beb5494bf1f276935c5083f3cf5aa7995'),
  ('ur.jalandhry', 4, 142, 635, 'منافق (ان چالوں سے اپنے نزدیک) خدا کو دھوکا دیتے ہیں (یہ اس کو کیا دھوکا دیں گے) وہ انہیں کو دھوکے میں ڈالنے والا ہے اور جب یہ نماز کو کھڑے ہوتے ہیں تو سست اور کاہل ہو کر (صرف) لوگوں کے دکھانے کو اور خدا کی یاد ہی نہیں کرتے مگر بہت کم', NULL, NULL, '515d0e167741204c88e5d0933d0c187cc383c3d074d379cf249e7e8285476615'),
  ('ur.jalandhry', 4, 143, 636, 'بیچ میں پڑے لٹک رہے ہیں نہ ان کی طرف (ہوتے ہیں) نہ ان کی طرف اور جس کو خدا بھٹکائے تو اس کے لئے کبھی بھی رستہ نہ پاؤ گے', NULL, NULL, '991a59265e898db299f365b7dcda5ef19cbb7b31a9abd2cafca195d7dad8f342'),
  ('ur.jalandhry', 4, 144, 637, 'اے اہل ایمان! مومنوں کے سوا کافروں کو دوست نہ بناؤ کیا تم چاہتے ہو کہ اپنے اوپر خدا کا صریح الزام لو؟', NULL, NULL, 'd5a85249b0109f1fb240d234e4ff659b0c2e072ae0a3f36668f80aa87ca5529e'),
  ('ur.jalandhry', 4, 145, 638, 'کچھ شک نہیں کہ منافق لوگ دوزخ کے سب سے نیچے کے درجے میں ہوں گے۔ اور تم ان کا کسی کو مددگار نہ پاؤ گے', NULL, NULL, 'f6674322af691084a8130df28976ef138e3d6212a6a34030f6f4e4873f1db34b'),
  ('ur.jalandhry', 4, 146, 639, 'ہاں جنہوں نے توبہ کی اور اپنی حالت کو درست کیا اور خدا (کی رسی) کو مضبوط پکڑا اور خاص خدا کے فرمانبردار ہوگئے تو ایسے لوگ مومنوں کے زمرے میں ہوں گے اور خدا عنقریب مومنوں کو بڑا ثواب دے گا', NULL, NULL, 'fe93d936623f2e3c3f999c5db10542d8828397c56e1a1bd27d74c6c596df8ea0'),
  ('ur.jalandhry', 4, 147, 640, 'اگر تم (خدا کے شکرگزار رہو اور (اس پر) ایمان لے آؤ تو خدا تم کو عذاب دے کر کیا کرے گا۔ اور خدا تو قدرشناس اور دانا ہے', NULL, NULL, '2bac4b3c7f48a0364d26c9e16d21c1af6648562b2801ea3bd7af0beb6e5bd4b6'),
  ('ur.jalandhry', 4, 148, 641, 'خدا اس بات کو پسند نہیں کرتا کہ کوئی کسی کو علانیہ برا کہے مگر وہ جو مظلوم ہو۔ اور خدا (سب کچھ) سنتا (اور) جانتا ہے', NULL, NULL, 'ecc4397c3015619a7d513a09ac988f613542559d2d1b196b50ff54d98c4e9cb0'),
  ('ur.jalandhry', 4, 149, 642, 'اگر تم لوگ بھلائی کھلم کھلا کرو گے یا چھپا کر یا برائی سے درگزر کرو گے تو خدا بھی معاف کرنے والا (اور) صاحب قدرت ہے', NULL, NULL, '38af29eaa888e2acfdc3bfb59bb4dc62aa0dae18fbf64062a6c8f175b7316fb4'),
  ('ur.jalandhry', 4, 150, 643, 'جو لوگ خدا سے اور اس کے پیغمبروں سے کفر کرتے ہیں اور خدا اور اس کے پیغمبروں میں فرق کرنا چاہتے ہیں اور کہتے ہیں کہ ہم بعض کو مانتے ہیں اور بعض کو نہیں مانتے اور ایمان اور کفر کے بیچ میں ایک راہ نکالنی چاہتے ہیں', NULL, NULL, '2fc78227559a397a5d97e687e503f847c4c1d2802358981d90b89cb78b20a8b7'),
  ('ur.jalandhry', 4, 151, 644, 'وہ بلا اشتباہ کافر ہیں اور کافروں کے لئے ہم نے ذلت کا عذاب تیار کر رکھا ہے', NULL, NULL, '8fe814463368622851a056e1b26101cf11d6b98692313fb4d90dc3aceb3f3aa9'),
  ('ur.jalandhry', 4, 152, 645, 'اور جو لوگ خدا اور اس کے پیغمبروں پر ایمان لائے اور ان میں سے کسی میں فرق نہ کیا (یعنی سب کو مانا) ایسے لوگوں کو وہ عنقریب ان (کی نیکیوں) کے صلے عطا فرمائے گا اور خدا بخشنے والا مہربان ہے', NULL, NULL, '77f08d2a73188c85cc0a4a0a97b9cda80dfdf3bd7f88cb59f7b6c14a59940b10'),
  ('ur.jalandhry', 4, 153, 646, '(اے محمدﷺ) اہل کتاب تم سے درخواست کرتے ہیں کہ تم ان پر ایک (لکھی ہوئی) کتاب آسمان سے اتار لاؤ تو یہ موسیٰ سے اس سے بھی بڑی بڑی درخواستیں کرچکے ہیں (ان سے) کہتے تھے ہمیں خدا ظاہر (یعنی آنکھوں سے) دکھا دو سو ان کے گناہ کی وجہ سے ان کو بجلی نے آپکڑا۔ پھر کھلی نشانیاں آئے پیچھے بچھڑے کو (معبود) بنا بیٹھے تو اس سے بھی ہم نے درگزر کی۔ اور موسیٰ کو صریح غلبہ دیا', NULL, NULL, 'e3f1f62367b1a0826cae94a1a132b2f65a87bfd2c71ca4190ef95482cac09cbf'),
  ('ur.jalandhry', 4, 154, 647, 'اور ان سے عہد لینے کو ہم نے ان پر کوہ طور اٹھا کھڑا کیا اور انہیں حکم دیا کہ (شہر کے) دروازے میں (داخل ہونا تو) سجدہ کرتے ہوئے داخل ہونا اور یہ بھی حکم دیا کہ ہفتے کے دن (مچھلیاں پکڑنے) میں تجاویز (یعنی حکم کے خلاف) نہ کرنا۔ غرض ہم نے ان سے مضبوط عہد لیا', NULL, NULL, '8db3b505214ace2bb666a5ae7146376dc8758ead58fb2ef796f100fc9219bd55'),
  ('ur.jalandhry', 4, 155, 648, '(لیکن انہوں نے عہد کو توڑ ڈالا) تو ان کے عہد توڑ دینے اور خدا کی آیتوں سے کفر کرنے اور انبیاء کو ناحق مار ڈالنے اور یہ کہنے کے سبب کہ ہمارے دلوں پر پردے (پڑے ہوئے) ہیں۔ (خدا نے ان کو مردود کردیا اور ان کے دلوں پر پردے نہیں ہیں) بلکہ ان کے کفر کے سبب خدا نے ان پر مہر کردی ہے تو یہ کم ہی ایمان لاتے ہیں', NULL, NULL, '8be1e8f8ec82f14718e4ce9292aaf07e62492b9986f877a14fccc87f06b99b9e'),
  ('ur.jalandhry', 4, 156, 649, 'اور ان کے کفر کے سبب اور مریم پر ایک بہتان عظیم باندھنے کے سبب', NULL, NULL, '9dd53e16e8406bc8ecafb45dfd979bdaf21cee0231209c35feae5f935e0b757a'),
  ('ur.jalandhry', 4, 157, 650, 'اور یہ کہنے کے سبب کہ ہم نے مریم کے بیٹے عیسیٰ مسیح کو جو خدا کے پیغمبر (کہلاتے) تھے قتل کردیا ہے (خدا نے ان کو معلون کردیا) اور انہوں نے عیسیٰ کو قتل نہیں کیا اور نہ انہیں سولی پر چڑھایا بلکہ ان کو ان کی سی صورت معلوم ہوئی اور جو لوگ ان کے بارے میں اختلاف کرتے ہیں وہ ان کے حال سے شک میں پڑے ہوئے ہیں اور پیروئی ظن کے سوا ان کو اس کا مطلق علم نہیں۔ اور انہوں نے عیسیٰ کو یقیناً قتل نہیں کیا', NULL, NULL, '4d37be6e8b416328dae968a8e5e6f9837b65330743033513acdfe03b0a6bcc87'),
  ('ur.jalandhry', 4, 158, 651, 'بلکہ خدا نے ان کو اپنی طرف اٹھا لیا۔ اور خدا غالب اور حکمت والا ہے', NULL, NULL, '15081525040171b233aab1585e59075055db85c584119ebcfd5d2932057078e0'),
  ('ur.jalandhry', 4, 159, 652, 'اور کوئی اہل کتاب نہیں ہوگا مگر ان کی موت سے پہلے ان پر ایمان لے آئے گا۔ اور وہ قیامت کے دن ان پر گواہ ہوں گے', NULL, NULL, '3dfa9fda7c7173620b1f1aeae6fa0a051bd8e848017c60ac3c96f643276dd87a'),
  ('ur.jalandhry', 4, 160, 653, 'تو ہم نے یہودیوں کے ظلموں کے سبب (بہت سی) پاکیزہ چیزیں جو ان کو حلال تھیں ان پر حرام کردیں اور اس سبب سے بھی کہ وہ اکثر خدا کے رستے سے (لوگوں کو) روکتے تھے', NULL, NULL, '0f47d58aa1ff7108f339090dd6c87389946a2eae49ae64bb76647306533ad1b5'),
  ('ur.jalandhry', 4, 161, 654, 'اور اس سبب سے بھی کہ باوجود منع کئے جانے کے سود لیتے تھے اور اس سبب سے بھی کہ لوگوں کا مال ناحق کھاتے تھے۔ اور ان میں سے جو کافر ہیں ان کے لئے ہم نے درد دینے والا عذاب تیار کر رکھا ہے', NULL, NULL, '0f79f8e90390cd3121b042c7e39a1aa5a8c75f79c9d06638b9b1ead36dba749a'),
  ('ur.jalandhry', 4, 162, 655, 'مگر جو لوگ ان میں سے علم میں پکے ہیں اور جو مومن ہیں وہ اس (کتاب) پر جو تم پر نازل ہوئی اور جو (کتابیں) تم سے پہلے نازل ہوئیں (سب پر) ایمان رکھتے ہیں اور نماز پڑھتے ہیں اور زکوٰة دیتے ہیں اور خدا اور روز آخرت کو مانتے ہیں۔ ان کو ہم عنقریب اجر عظیم دیں گے', NULL, NULL, 'a5ec2f41ec32cd26cf563d994f076d0a8a2861e1ee7875f69d3797da64933432'),
  ('ur.jalandhry', 4, 163, 656, '(اے محمدﷺ) ہم نے تمہاری طرف اسی طرح وحی بھیجی ہے جس طرح نوح اور ان سے پچھلے پیغمبروں کی طرف بھیجی تھی۔ اور ابراہیم اور اسمعیل اور اسحاق اور یعقوب اور اولاد یعقوب اور عیسیٰ اور ایوب اور یونس اور ہارون اور سلیمان کی طرف بھی ہم نے وحی بھیجی تھی اور داؤد کو ہم نے زبور بھی عنایت کی تھی', NULL, NULL, '2d0822288c60242502fe02cc6d845903b0ff2ac6159928bcf1b34bdeebafaa44'),
  ('ur.jalandhry', 4, 164, 657, 'اور بہت سے پیغمبر ہیں جن کے حالات ہم تم سے پیشتر بیان کرچکے ہیں اور بہت سے پیغمبر ہیں جن کے حالات تم سے بیان نہیں کئے۔ اور موسیٰ سے تو خدا نے باتیں بھی کیں', NULL, NULL, '229a1bac43ca0a0d2fe6dc3cc9be04000c73b1c585f50792e2efe104347d9d3a'),
  ('ur.jalandhry', 4, 165, 658, '(سب) پیغمبروں کو (خدا نے) خوشخبری سنانے والے اور ڈرانے والے (بنا کر بھیجا تھا) تاکہ پیغمبروں کے آنے کے بعد لوگوں کو خدا پر الزام کا موقع نہ رہے اور خدا غالب حکمت والا ہے', NULL, NULL, '2a912ce5203758aa31b82f30049d3ed6a76af8e27c9df0a66edf36a2cda7d5b1'),
  ('ur.jalandhry', 4, 166, 659, 'لیکن خدا نے جو (کتاب) تم پر نازل کی ہے اس کی نسبت خدا گواہی دیتا ہے کہ اس نے اپنے علم سے نازل کی ہے اور فرشتے بھی گواہی دیتے ہیں۔ اور گواہ تو خدا ہی کافی ہے', NULL, NULL, '93973b2226e5f4a21ca1bced9941b5ac83e6459be42b45a3ab4296c5243d6a2b'),
  ('ur.jalandhry', 4, 167, 660, 'جن لوگوں نے کفر کیا اور (لوگوں کو) خدا کے رستے سے روکا وہ رستے سے بھٹک کر دور جا پڑے', NULL, NULL, '3a562b481a6d2baa2f31d2f86c84c447df09f7fca18767fbbacf44bff2a6295b'),
  ('ur.jalandhry', 4, 168, 661, 'جو لوگ کافر ہوئے اور ظلم کرتے رہے خدا ان کو بخشنے والا نہیں اور نہ انہیں رستہ ہی دکھائے گا', NULL, NULL, 'dc97af90d922fee35bbacf8714d35e044a99fbc23603356e3bc139e7aff9706e'),
  ('ur.jalandhry', 4, 169, 662, 'ہاں دوزخ کا رستہ جس میں وہ ہمیشہ (جلتے) رہیں گے۔ اور یہ (بات) خدا کو آسان ہے', NULL, NULL, 'c4621a2fad103898fb7fb02c472cb95d0ff681ee89fcdfcdabfeca750b7b8617'),
  ('ur.jalandhry', 4, 170, 663, 'لوگو! خدا کے پیغمبر تمہارے پاس تمہارے پروردگار کی طرف سے حق بات لے کر آئے ہیں تو (ان پر) ایمان لاؤ (یہی) تمہارے حق میں بہتر ہے۔ اور اگر کفر کرو گے تو (جان رکھو کہ) جو کچھ آسمانوں اور زمین میں ہے سب خداہی کا ہے اور خدا سب کچھ جاننے والا (اور) حکمت والا ہے', NULL, NULL, '934b8f30b0f7ece8355240dd7b83b5dfc4047d5fe63040c51ab7b4623bb8ba7c'),
  ('ur.jalandhry', 4, 171, 664, 'اے اہل کتاب اپنے دین (کی بات) میں حد سے نہ بڑھو اور خدا کے بارے میں حق کے سوا کچھ نہ کہو۔ مسیح (یعنی) مریم کے بیٹے عیسیٰ (نہ خدا تھے نہ خدا کے بیٹے بلکہ) خدا کے رسول اور کا کلمہٴ (بشارت) تھے جو اس نے مریم کی طرف بھیجا تھا اور اس کی طرف سے ایک روح تھے تو خدا اوراس کے رسولوں پر ایمان لاؤ۔ اور (یہ) نہ کہو (کہ خدا) تین (ہیں۔ اس اعتقاد سے) باز آؤ کہ یہ تمہارے حق میں بہتر ہے۔ خدا ہی معبود واحد ہے اور اس سے پاک ہے کہ اس کے اولاد ہو۔ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے۔ اور خدا ہی کارساز کافی ہے', NULL, NULL, '59decdc1947089e22f403f9c2e6cf0f2c27855837d0f640fa53f9d800dc03c39'),
  ('ur.jalandhry', 4, 172, 665, 'مسیح اس بات سے عار نہیں رکھتے کہ خدا کے بندے ہوں اور نہ مقرب فرشتے (عار رکھتے ہیں) اور جو شخص خدا کا بندہ ہونے کو موجب عار سمجھے اور سرکشی کرے تو خدا سب کو اپنے پاس جمع کرلے گا', NULL, NULL, '353dbd3b9959faed9db03fd3786f0b3c8c94b84ef20604626c0c19b96ca228ed'),
  ('ur.jalandhry', 4, 173, 666, 'تو جو لوگ ایمان لائے اور نیک کام کرتے رہے وہ ان کو ان کا پورا بدلا دے گا اور اپنے فضل سے کچھ زیادہ بھی عنایت کرے گا۔ اور جنہوں نے (بندوں ہونے سے) عاروانکار اور تکبر کیا ان کو تکلیف دینے والا عذاب دے گا۔ اور یہ لوگ خدا کے سوا اپنا حامی اور مددگار نہ پائیں گے', NULL, NULL, 'c4130bdbd620ab19fbbd6a6897477d30c7b2c692a40570e400a06067ee40e56a'),
  ('ur.jalandhry', 4, 174, 667, 'لوگو تمہارے پروردگار کی طرف سے تمہارے پاس دلیل (روشن) آچکی ہے اور ہم نے (کفر اور ضلالت کا اندھیرا دور کرنے کو) تمہاری طرف چمکتا ہوا نور بھیج دیا ہے', NULL, NULL, '661bd6d40eea93924bbd9f1ebb992f905faf04f920f01560dfefd961c8455aaa'),
  ('ur.jalandhry', 4, 175, 668, 'پس جو لوگ خدا پر ایمان لائے اور اس (کے دین کی رسی) کو مضبوط پکڑے رہے ان کو وہ اپنی رحمت اور فضل (کے بہشتوں) میں داخل کرے گا۔ اور اپنی طرف (پہچنے کا) سیدھا رستہ دکھائے گا', NULL, NULL, 'a7d32ab6d35d9fd8a94b029df903f91afeddd575d8ff132e367f7373f570b44e'),
  ('ur.jalandhry', 4, 176, 669, '(اے پیغمبر) لوگ تم سے (کلالہ کے بارے میں) حکم (خدا) دریافت کرتے ہیں کہہ دو کہ خدا کلالہ بارے میں یہ حکم دیتا ہے کہ اگر کوئی ایسا مرد مرجائے جس کے اولاد نہ ہو (اور نہ ماں باپ) اور اس کے بہن ہو تو اس کو بھائی کے ترکے میں سے آدھا حصہ ملے گا۔ اور اگر بہن مرجائے اور اس کے اولاد نہ ہو تو اس کے تمام مال کا وارث بھائی ہوگا اور اگر (مرنے والے بھائی کی) دو بہنیں ہوں تو دونوں کو بھائی کے ترکے میں سے دو تہائی۔ اور اگر بھائی اور بہن یعنی مرد اور عورتیں ملے جلے وارث ہوں تو مرد کا حصہ دو عورتوں کے برابر ہے۔ (یہ احکام) خدا تم سے اس لئے بیان فرماتا ہے کہ بھٹکتے نہ پھرو۔ اور خدا ہر چیز سے واقف ہے', NULL, NULL, '5600e60aec854ae65dc01f5dc6b64828a87d5defab9ad33db4d3375349e07005'),
  ('ur.jalandhry', 5, 1, 670, 'اے ایمان والو! اپنے اقراروں کو پورا کرو۔ تمہارے لیے چارپائے جانور (جو چرنے والے ہیں) حلال کر دیئے گئے ہیں۔ بجز ان کے جو تمہیں پڑھ کر سنائے جاتے ہیں مگر احرام (حج) میں شکار کو حلال نہ جاننا۔ خدا جیسا چاہتا ہے حکم دیتا ہے', NULL, NULL, 'd5955386ecd3ba56e3e7fe8feadd7aa59f2710803e381516e5449b11f1c2817f'),
  ('ur.jalandhry', 5, 2, 671, 'مومنو! خدا کے نام کی چیزوں کی بےحرمتی نہ کرنا اور نہ ادب کے مہینے کی اور نہ قربانی کے جانوروں کی اور نہ ان جانوروں کی (جو خدا کی نذر کر دیئے گئے ہوں اور) جن کے گلوں میں پٹے بندھے ہوں اور نہ ان لوگوں کی جو عزت کے گھر (یعنی بیت الله) کو جا رہے ہوں (اور) اپنے پروردگار کے فضل اور اس کی خوشنودی کے طلبگار ہوں اور جب احرام اتار دو تو (پھر اختیار ہے کہ) شکار کرو اور لوگوں کی دشمنی اس وجہ سے کہ انہوں نے تم کو عزت والی مسجد سے روکا تھا تمہیں اس بات پر آمادہ نہ کرے کہ تم ان پر زیادتی کرنے لگو اور (دیکھو) نیکی اور پرہیزگاری کے کاموں میں ایک دوسرے کی مدد کیا کرو اور گناہ اور ظلم کی باتوں میں مدد نہ کیا کرو اور خدا سے ڈرتے رہو۔ کچھ شک نہیں کہ خدا کا عذاب سخت ہے', NULL, NULL, 'c006810afad32e5f3691f1709ba3cdacd616959aadf6b5becd3b2535f38a5d84'),
  ('ur.jalandhry', 5, 3, 672, 'تم پر مرا ہوا جانور اور (بہتا) لہو اور سور کا گوشت اور جس چیز پر خدا کے سوا کسی اور کا نام پکارا جائے اور جو جانور گلا گھٹ کر مر جائے اور جو چوٹ لگ کر مر جائے اور جو گر کر مر جائے اور جو سینگ لگ کر مر جائے یہ سب حرام ہیں اور وہ جانور بھی جس کو درندے پھاڑ کھائیں۔ مگر جس کو تم (مرنے سے پہلے) ذبح کرلو اور وہ جانور بھی جو تھان پر ذبح کیا جائے اور یہ بھی کہ پاسوں سے قسمت معلوم کرو یہ سب گناہ (کے کام) ہیں آج کافر تمہارے دین سے ناامید ہو گئے ہیں تو ان سے مت ڈرو اور مجھی سے ڈرتے رہو (اور) آج ہم نے تمہارے لئے تمہارا دین کامل کر دیا اور اپنی نعمتیں تم پر پوری کر دیں اور تمہارے لئے اسلام کو دین پسند کیا ہاں جو شخص بھوک میں ناچار ہو جائے (بشرطیکہ) گناہ کی طرف مائل نہ ہو تو خدا بخشنے والا مہربان ہے', NULL, NULL, '8a8cdec06a24dc261a801ae0eb51b74495bfed68db69fb246abe8ae9f81f7ed9'),
  ('ur.jalandhry', 5, 4, 673, 'تم سے پوچھتے ہیں کہ کون کون سی چیزیں ان کے لیے حلال ہیں (ان سے) کہہ دو کہ سب پاکیزہ چیزیں تم کو حلال ہیں اور وہ (شکار) بھی حلال ہے جو تمہارے لیے ان شکاری جانوروں نے پکڑا ہو جن کو تم نے سدھا رکھا ہو اور جس (طریق) سے خدا نے تمہیں (شکار کرنا) سکھایا ہے (اس طریق سے) تم نے ان کو سکھایا ہو تو جو شکار وہ تمہارے لئے پکڑ رکھیں اس کو کھا لیا کرو اور (شکاری جانوروں کو چھوڑتے وقت) خدا کا نام لے لیا کرو اور خدا سے ڈرتے رہو۔ بےشک خدا جلد حساب لینے والا ہے', NULL, NULL, '1937607a59e668c280f32514d597bdba0737bb829d05e30248150feb323af6f8'),
  ('ur.jalandhry', 5, 5, 674, 'آج تمہارے لیے سب پاکیزہ چیزیں حلال کر دی گئیں اور اہل کتاب کا کھانا بھی تم کو حلال ہے اور تمہارا کھانا ان کو حلال ہے اور پاک دامن مومن عورتیں اور پاک دامن اہل کتاب عورتیں بھی (حلال ہیں) جبکہ ان کا مہر دے دو۔ اور ان سے عفت قائم رکھنی مقصود ہو نہ کھلی بدکاری کرنی اور نہ چھپی دوستی کرنی اور جو شخص ایمان سے منکر ہوا اس کے عمل ضائع ہو گئے اور وہ آخرت میں نقصان پانے والوں میں ہوگا', NULL, NULL, '112304b00443857bc4357c0434def93effbe276ecc3571368554f947f53ff7d7'),
  ('ur.jalandhry', 5, 6, 675, 'مومنو! جب تم نماز پڑھنے کا قصد کیا کرو تم منہ اور کہنیوں تک ہاتھ دھو لیا کرو اور سر کا مسح کر لیا کرو اور ٹخنوں تک پاؤں (دھو لیا کرو) اور اگر نہانے کی حاجت ہو تو (نہا کر) پاک ہو جایا کرو اور اگر بیمار ہو یا سفر میں ہو یا کوئی تم میں سے بیت الخلا سے ہو کر آیا ہو یا تم عورتوں سے ہم بستر ہوئے ہو اور تمہیں پانی نہ مل سکے تو پاک مٹی لو اور اس سے منہ اور ہاتھوں کا مسح (یعنی تیمم) کر لو۔ خدا تم پر کسی طرح کی تنگی نہیں کرنا چاہتا بلکہ یہ چاہتا ہے کہ تمہیں پاک کرے اور اپنی نعمتیں تم پر پوری کرے تاکہ تم شکر کرو', NULL, NULL, '9d37b531758e8ea910f289e8cd9112325020914ab0896f3d5c7d6a82d35b2afe'),
  ('ur.jalandhry', 5, 7, 676, 'اور خدا نے جو تم پر احسان کئے ہیں ان کو یاد کرو اور اس عہد کو بھی جس کا تم سے قول لیا تھا (یعنی) جب تم نے کہا تھا کہ ہم نے (خدا کا حکم) سن لیا اور قبول کیا۔ اور الله سے ڈرو۔ کچھ شک نہیں کہ خدا دلوں کی باتوں (تک) سے واقف ہے', NULL, NULL, '16674e797276d5d732fefb8f68295665e0f46fc837fde4093981eef9e544ff4b'),
  ('ur.jalandhry', 5, 8, 677, 'اے ایمان والوں! خدا کے لیے انصاف کی گواہی دینے کے لیے کھڑے ہو جایا کرو۔ اور لوگوں کی دشمنی تم کو اس بات پر آمادہ نہ کرے کہ انصاف چھوڑ دو۔ انصاف کیا کرو کہ یہی پرہیزگاری کی بات ہے اور خدا سے ڈرتے رہو۔ کچھ شک نہیں کہ خدا تمہارے سب اعمال سے خبردار ہے', NULL, NULL, '1a93266a5240cb61f0e24e559ce93d17074ab24d6f654bdc07bf833c5026ded8'),
  ('ur.jalandhry', 5, 9, 678, 'جو لوگ ایمان لائے اور نیک کام کرتے رہے ان سے خدا نے وعدہ فرمایا ہے کہ ان کے لیے بخشش اور اجر عظیم ہے', NULL, NULL, 'ff457687eaf78c3cf23b0a0ec87db2eca13e68c55cc0fa8b0ac60fa50bae4d44'),
  ('ur.jalandhry', 5, 10, 679, 'اور جنہوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں', NULL, NULL, 'bde3b6d506dcaae8d4609aba190cf4cbda11618bfb98b9532b1986bbede5eeb4'),
  ('ur.jalandhry', 5, 11, 680, 'اے ایمان والو! خدا نے جو تم پر احسان کیا ہے اس کو یاد کرو۔ جب ایک جماعت نے ارادہ کیا کہ تم پر دست درازی کریں تو اس نے ان کے ہاتھ روک دیئے اور خدا سے ڈرتے رہوں اور مومنو کو خدا ہی پر بھروسہ رکھنا چاہیئے', NULL, NULL, 'c7d03fd721f321b663ffae7dbf74fd402cc08e6a3923a7c77d89683e6573408b'),
  ('ur.jalandhry', 5, 12, 681, 'اور خدا نے بنی اسرائیل سے اقرار لیا اور ان میں ہم نے بارہ سردار مقرر کئے پھر خدا نے فرمایا کہ میں تمہارے ساتھ ہوں اگر تم نماز پڑھتے اور زکوٰة دیتے رہو گے اور میرے پیغمبروں پر ایمان لاؤ گے اور ان کی مدد کرو گے اور خدا کو قرض حسنہ دو گے تو میں تم سے تمہارے گناہ دور کر دوں گا اور تم کو بہشتوں میں داخل کروں گا جن کے نیچے نہریں بہہ رہی ہیں پھر جس نے اس کے بعد تم میں سے کفر کیا وہ سیدھے رستے سے بھٹک گیا', NULL, NULL, 'd218064a80c6da31a1135067715f514b08ff39d6e3c581d4aa5a35c1625e4137'),
  ('ur.jalandhry', 5, 13, 682, 'تو ان لوگوں کے عہد توڑ دینے کے سبب ہم نے ان پر لعنت کی اور ان کے دلوں کو سخت کر دیا یہ لوگ کلمات (کتاب) کو اپنے مقامات سے بدل دیتے ہیں اور جن باتوں کی ان کو نصیحت کی گئی تھی ان کا بھی ایک حصہ فراموش کر بیٹھے اور تھوڑے آدمیوں کے سوا ہمیشہ تم ان کی (ایک نہ ایک) خیانت کی خبر پاتے رہتے ہو تو ان کی خطائیں معاف کردو اور (ان سے) درگزر کرو کہ خدا احسان کرنے والوں کو دوست رکھتا ہے', NULL, NULL, 'da642eb557145a2d4602f93c3111ea6340ccff96a90665767dbdd8e51b5fd8c0'),
  ('ur.jalandhry', 5, 14, 683, 'اور جو لوگ (اپنے تئیں) کہتے ہیں کہ ہم نصاریٰ ہیں ہم نے ان سے بھی عہد لیا تھا مگر انہوں نے بھی اس نصیحت کا جو ان کو کی گئی تھی ایک حصہ فراموش کر دیا تو ہم نے ان کے باہم قیامت تک کے لیے دشمنی اور کینہ ڈال دیا اور جو کچھ وہ کرتے رہے خدا عنقریب ان کو اس سے آگاہ کرے گا', NULL, NULL, 'de5df6ad6aa5d5387043196012cb2bd10fa1dabfa573fd7230da410bef304c44'),
  ('ur.jalandhry', 5, 15, 684, 'اے اہل کتاب! تمہارے پاس ہمارے پیغمبر (آخرالزماں) آ گئے ہیں کہ جو کچھ تم کتاب (الہٰی) میں سے چھپاتے تھے وہ اس میں سے بہت کچھ تمہیں کھول کھول کر بتا دیتے ہیں اور تمہارے بہت سے قصور معاف کر دیتے ہیں بےشک تمہارے پاس خدا کی طرف سے نور اور روشن کتاب آ چکی ہے', NULL, NULL, '3f8cee83e3e2ac034934af0182f28ea75c5878610eac30e5892a25470524970b'),
  ('ur.jalandhry', 5, 16, 685, 'جس سے خدا اپنی رضا پر چلنے والوں کو نجات کے رستے دکھاتا ہے اور اپنے حکم سے اندھیرے میں سے نکال کر روشنی کی طرف لے جاتا اور ان کو سیدھے رستہ پر چلاتا ہے', NULL, NULL, '194d07a94cce63bb626e56a0ecea00f35ef5ec4bd9f6db78a955eb8f05f84ac0'),
  ('ur.jalandhry', 5, 17, 686, 'جو لوگ اس بات کے قائل ہیں کہ عیسیٰ بن مریم خدا ہیں وہ بےشک کافر ہیں (ان سے) کہہ دو کہ اگر خدا عیسیٰ بن مریم کو اور ان کی والدہ کو اور جتنے لوگ زمین میں ہیں سب کو ہلاک کرنا چاہے تو اس کے آگے کس کی پیش چل سکتی ہے؟ اور آسمان اور زمین اور جو کچھ ان دونوں میں ہے سب پر خدا ہی کی بادشاہی ہے وہ جو چاہتا ہے پیدا کرتا ہے اور خدا ہر چیز پر قادر ہے', NULL, NULL, '5eaabd96836f08a09140f9f097516d443641d7f6b6852112bda7068c565c4303'),
  ('ur.jalandhry', 5, 18, 687, 'اور یہود اور نصاریٰ کہتے ہیں کہ ہم خدا کے بیٹے اور اس کے پیارے ہیں کہو کہ پھر وہ تمہاری بداعمالیوں کے سبب تمھیں عذاب کیوں دیتا ہے (نہیں) بلکہ تم اس کی مخلوقات میں (دوسروں کی طرح کے) انسان ہو وہ جسے چاہے بخشے اور جسے چاہے عذاب دے اور آسمان زمین اور جو کچھ ان دونوں میں ہے سب پر خدا ہی کی حکومت ہے اور (سب کو) اسی کی طرف لوٹ کر جانا ہے', NULL, NULL, '35f6fa9563f07a0e8eea95cf73fcb3d53a3c2dad7b8240e0a771657ea7f95e1f'),
  ('ur.jalandhry', 5, 19, 688, 'اے اہلِ کتاب پیغمبروں کے آنے کا سلسلہ جو (ایک عرصے تک) منقطع رہا تو (اب) تمہارے پاس ہمارے پیغمبر آ گئے ہیں جو تم سے (ہمارے احکام) بیان کرتے ہیں تاکہ تم یہ نہ کہو کہ ہمارے پاس کوئی خوشخبری یا ڈر سنانے والا نہیں آیا سو (اب) تمہارے پاس خوشخبری اور ڈر سنانے والے آ گئے ہیں اور خدا ہر چیز پر قادر ہے', NULL, NULL, 'a43452ed5665d4954a2473f7797cb9be119895d1f46406d8102a236b94fb8398'),
  ('ur.jalandhry', 5, 20, 689, 'اور جب موسیٰ نے اپنی قوم سے کہا کہ بھائیو تم پر خدا نے جو احسان کئے ہیں ان کو یاد کرو کہ اس نے تم میں پیغمبر پیدا کیے اور تمہیں بادشاہ بنایا اور تم کو اتنا کچھ عنایت کیا کہ اہل عالم میں سے کسی کو نہیں دیا', NULL, NULL, 'dd72aa300fc8f541590c99d5957293a528bbfc4cc16ffabf5993931074e534a7'),
  ('ur.jalandhry', 5, 21, 690, 'تو بھائیو! تم ارض مقدس (یعنی ملک شام) میں جسے خدا نے تمہارے لیے لکھ رکھا ہے چل داخل ہو اور (دیکھنا مقابلے کے وقت) پیٹھ نہ پھیر دینا ورنہ نقصان میں پڑ جاؤ گے', NULL, NULL, '6a7b7d4db076326f5b0bb7638e19e23ea7e911ebca6e4d9944e7f50e8772306b'),
  ('ur.jalandhry', 5, 22, 691, 'وہ کہنے لگے کہ موسیٰ! وہاں تو بڑے زبردست لوگ (رہتے) ہیں اور جب تک وہ اس سرزمین سے نکل نہ جائیں ہم وہاں جا نہیں سکتے ہاں اگر وہ وہاں سے نکل جائیں تو ہم جا داخل ہوں گے', NULL, NULL, '9be015b96e8e6114ce372d06ad0e3cd2ca57f8c7eb9ef51848bc2634e0f4713a'),
  ('ur.jalandhry', 5, 23, 692, 'جو لوگ (خدا سے) ڈرتے تھے ان میں سے دو شخص جن پر خدا کی عنایت تھی کہنے لگے کہ ان لوگوں پر دروازے کے رستے سے حملہ کردو جب تم دروازے میں داخل ہو گئے تو فتح تمہارے ہے اور خدا ہی پر بھروسہ رکھو بشرطیکہ صاحبِ ایمان ہو', NULL, NULL, 'be1cd2ad52d17926636fa36dfb10ad140c7bf3d128883c7a7ed4a56f80885a52'),
  ('ur.jalandhry', 5, 24, 693, 'وہ بولے کہ موسیٰ! جب تک وہ لوگ وہاں ہیں ہم کبھی وہاں نہیں جا سکتے (اگر لڑنا ہی ضرور ہے) تو تم اور تمہارا خدا جاؤ اور لڑو ہم یہیں بیٹھے رہیں گے', NULL, NULL, '158258c02c003998e2ae26cebe6a20c6cf98d6df7cab4c025b97b5057d6693e5'),
  ('ur.jalandhry', 5, 25, 694, 'موسیٰ نے (خدا سے) التجا کی کہ پروردگار میں اپنے اور اپنے بھائی کے سوا اور کسی پر اختیار نہیں رکھتا تو ہم میں اور ان نافرمان لوگوں میں جدائی کردے', NULL, NULL, 'c37a05de3d0416dbd3856872c666545405fa8568045859830cd28673e5e173ab'),
  ('ur.jalandhry', 5, 26, 695, 'خدا نے فرمایا کہ وہ ملک ان پر چالیس برس تک کے لیے حرام کر دیا گیا (کہ وہاں جانے نہ پائیں گے اور جنگل کی) زمین میں سرگرداں پھرتے رہیں گے تو ان نافرمان لوگوں کے حال پر افسوس نہ کرو', NULL, NULL, '449b4052621cf045dcd0815acbc885746cbe637456d1a5d7d165fe36839fef8a'),
  ('ur.jalandhry', 5, 27, 696, 'اور (اے محمد) ان کو آدم کے دو بیٹوں (ہابیل اور قابیل) کے حالات (جو بالکل) سچے (ہیں) پڑھ کر سنا دو کہ جب ان دونوں نے خدا (کی جناب میں) کچھ نیازیں چڑھائیں تو ایک کی نیاز تو قبول ہو گئی اور دوسرے کی قبول نہ ہوئی (تب قابیل ہابیل سے) کہنے لگا کہ میں تجھے قتل کروں گا اس نے کہا کہ خدا پرہیزگاروں ہی کی (نیاز) قبول فرمایا کرتا ہے', NULL, NULL, '7057b790ee6b6b71a679fe8edb54073a91db0077f7d6cc68954474f9f3968b4a'),
  ('ur.jalandhry', 5, 28, 697, 'اور اگر تو مجھے قتل کرنے کے لیے مجھ پر ہاتھ چلائے گا تو میں تجھ کو قتل کرنے کے لئے تجھ پر ہاتھ نہیں چلاؤں گا مجھے تو خدائے رب العالمین سے ڈر لگتا ہے', NULL, NULL, '90ec9b5a837f88acdb2fbc31a09090f78db2927aa1e937d1b763b3d0473b9028'),
  ('ur.jalandhry', 5, 29, 698, 'میں چاہتا ہوں کہ تو میرے گناہ میں بھی ماخوذ ہو اور اپنے گناہ میں بھی پھر (زمرہ) اہل دوزخ میں ہو اور ظالموں کی یہی سزا ہے', NULL, NULL, '5167e151da715cbd3051b99b6cb0ca2088d79b31c595ebff38499b8f19356c4a'),
  ('ur.jalandhry', 5, 30, 699, 'مگر اس کے نفس نے اس کو بھائی کے قتل ہی کی ترغیب دی تو اس نے اسے قتل کر دیا اور خسارہ اٹھانے والوں میں ہو گیا', NULL, NULL, 'c2c696e721b0ad155cc3cf047f78c6a845c1eb801f6dbeeba306d8b05e05fd40'),
  ('ur.jalandhry', 5, 31, 700, 'اب خدا نے ایک کوّا بھیجا جو زمین کریدنے لگا تاکہ اسے دکھائے کہ اپنے بھائی کی لاش کو کیونکر چھپائے کہنے لگا اے ہے مجھ سے اتنا بھی نہ ہو سکا کہ اس کوے کے برابر ہوتا کہ اپنے بھائی کی لاش چھپا دیتا پھر وہ پشیمان ہوا', NULL, NULL, 'cd1297ca4ea09741abb20feb5ad417364884b5017c723b64e28ac78012b4f2fb')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 5, 32, 701, 'اس قتل کی وجہ سے ہم نے بنی اسرائیل پر یہ حکم نازل کیا کہ جو شخص کسی کو (ناحق) قتل کرے گا (یعنی) بغیر اس کے کہ جان کا بدلہ لیا جائے یا ملک میں خرابی کرنے کی سزا دی جائے اُس نے گویا تمام لوگوں کو قتل کیا اور جو اس کی زندگانی کا موجب ہوا تو گویا تمام لوگوں کی زندگانی کا موجب ہوا اور ان لوگوں کے پاس ہمارے پیغمبر روشن دلیلیں لا چکے ہیں پھر اس کے بعد بھی ان سے بہت سے لوگ ملک میں حدِ اعتدال سے نکل جاتے ہیں', NULL, NULL, '5d275e3aa1d849a5b5640c8d5b64bb148988b2bf7210ea29ed43b6ba56b9d509'),
  ('ur.jalandhry', 5, 33, 702, 'جو لوگ خدا اور اس کے رسول سے لڑائی کریں اور ملک میں فساد کرنے کو دوڑتے پھریں ان کی یہی سزا ہے کہ قتل کر دیئے جائیں یا سولی چڑھا دیئے جائیں یا ان کے ایک ایک طرف کے ہاتھ اور ایک ایک طرف کے پاؤں کاٹ دیئے جائیں یا ملک سے نکال دیئے جائیں یہ تو دنیا میں ان کی رسوائی ہے اور آخرت میں ان کے لیے بڑا (بھاری) عذاب تیار ہے', NULL, NULL, '27a4437f1f5d86624a4a10b4861098cf2036fab2d92455693104cf85ed52de8d'),
  ('ur.jalandhry', 5, 34, 703, 'ہاں جن لوگوں نے اس سے پیشتر کہ تمہارے قابو میں آ جائیں توبہ کر لی تو جان رکھو کہ خدا بخشنے والا مہربان ہے', NULL, NULL, '30f8817ed69e85d0e96bcabb37c4b1c3f433c7fcfb3b40fb9b08d6ef7c2e406f'),
  ('ur.jalandhry', 5, 35, 704, 'اے ایمان والو! خدا سے ڈرتے رہو اور اس کا قرب حاصل کرنے کا ذریعہ تلاش کرتے رہو اور اس کے رستے میں جہاد کرو تاکہ رستگاری پاؤ', NULL, NULL, '1ba09c7b86ef573ad221e667492ee61df9e75b85e8fe1d8104c8e235464efcb1'),
  ('ur.jalandhry', 5, 36, 705, 'جو لوگ کافر ہیں اگر ان کے پاس روئے زمین (کے تمام خزانے اور اس) کا سب مال ومتاع ہو اور اس کے ساتھ اسی قدر اور بھی ہو تاکہ قیامت کے روز عذاب (سے رستگاری حاصل کرنے) کا بدلہ دیں تو ان سے قبول نہیں کیا جائے گا اور ان کو درد دینے والا عذاب ہوگا', NULL, NULL, '9abf094f2cbbb07fd87b8ef2c7938c3d1721762e6d8f85f94463e586c8668944'),
  ('ur.jalandhry', 5, 37, 706, '(ہر چند) چاہیں گے کہ آگ سے نکل جائیں مگر اس سے نہیں نکل سکیں گے اور ان کے لئے ہمیشہ کا عذاب ہے', NULL, NULL, '5bc95fb5d7be9157cf9f440825f80f6d6d3cff5b258834e4be1d6c468a9afc55'),
  ('ur.jalandhry', 5, 38, 707, 'اور جو چوری کرے مرد ہو یا عورت ان کے ہاتھ کاٹ ڈالو یہ ان کے فعلوں کی سزا اور خدا کی طرف سے عبرت ہے اور خدا زبردست (اور) صاحب حکمت ہے', NULL, NULL, '32737719d4793d089dc4ee065167d48be12993cfd8f2871f52a3e33c035a793b'),
  ('ur.jalandhry', 5, 39, 708, 'اور جو شخص گناہ کے بعد توبہ کرے اور نیکوکار ہو جائے تو خدا اس کو معاف کر دے گا کچھ شک نہیں کہ خدا بخشنے والا مہربان ہے', NULL, NULL, '552d283e3af422c87549dff5798902c0c42ea151f4dbe40d5c272b41506a08ba'),
  ('ur.jalandhry', 5, 40, 709, 'کیا تم کو معلوم نہیں کہ آسمانوں اور زمین میں خدا ہی کی سلطنت ہے؟ جس کو چاہے عذاب کرے اور جسے چاہے بخش دے اور خدا ہر چیز پر قادر ہے', NULL, NULL, '256e5c01766a4271bc2ee6ec3b3fe7876f834e4be1f51402eb532fb22a476eff'),
  ('ur.jalandhry', 5, 41, 710, 'اے پیغمبر! جو لوگ کفر میں جلدی کرتے ہیں (کچھ تو) ان میں سے (ہیں) جو منہ سے کہتے ہیں کہ ہم مومن ہیں لیکن ان کے دل مومن نہیں ہیں اور (کچھ) ان میں سے جو یہودی ہیں ان کی وجہ سے غمناک نہ ہونا یہ غلط باتیں بنانے کے لیے جاسوسی کرتے پھرتے ہیں اور ایسے لوگوں (کے بہکانے) کے لیے جاسوس بنے ہیں جو ابھی تمہارے پاس نہیں آئے (صحیح) باتوں کو ان کے مقامات (میں ثابت ہونے) کے بعد بدل دیتے ہیں (اور لوگوں سے) کہتے ہیں کہ اگر تم کو یہی (حکم) ملے تو اسے قبول کر لینا اور اگر یہ نہ ملے تو اس سے احتراز کرنا اور اگر کسی کو خدا گمراہ کرنا چاہے تو اس کے لیے تم کچھ بھی خدا سے (ہدایت کا) اختیار نہیں رکھتے یہ وہ لوگ ہیں جن کے دلوں کو خدا نے پاک کرنا نہیں چاہا ان کے لیے دنیا میں بھی ذلت ہے اور آخرت میں بھی بڑا عذاب ہے', NULL, NULL, 'ea2a396dc00d6feb5f0a309c47e6f93e0c6d1b0de38612ce1981a6c148790f57'),
  ('ur.jalandhry', 5, 42, 711, '(یہ) جھوٹی باتیں بنانے کے جاسوسی کرنے والے اور (رشوت کا) حرام مال کھانے والے ہیں اگر یہ تمہارے پاس (کوئی مقدمہ فیصل کرانے کو) آئیں تو تم ان میں فیصلہ کر دینا یا اعراض کرنا اور اگر ان سے اعراض کرو گے تو وہ تمہارا کچھ بھی نہیں بگاڑ سکیں گے اور اگر فیصلہ کرنا چاہو تو انصاف کا فیصلہ کرنا کہ خدا انصاف کرنے والوں کو دوست رکھتا ہے', NULL, NULL, '08946c98281bb7e9b2e73c9fa374367840c74a7e870315fa8db594afaccbd8d4'),
  ('ur.jalandhry', 5, 43, 712, 'اور یہ تم سے (اپنے مقدمات) کیونکر فیصل کرایں گے جبکہ خود ان کے پاس تورات (موجود) ہے جس میں خدا کا حکم (لکھا ہوا) ہے (یہ اسے جانتے ہیں) پھر اس کے بعد اس سے پھر جاتے ہیں اور یہ لوگ ایمان ہی نہیں رکھتے', NULL, NULL, '6e75487a958ebee5a4f5f7a6744228c479c816417d669ec144e80f7a7a5ab0fe'),
  ('ur.jalandhry', 5, 44, 713, 'بیشک ہم نے توریت نازل فرمائی جس میں ہدایت اور روشنی ہے اسی کے مطابق انبیاء جو (خدا کے) فرمانبردار تھے یہودیوں کو حکم دیتے رہے ہیں اور مشائخ اور علماء بھی کیونکہ وہ کتاب خدا کے نگہبان مقرر کیے گئے تھے اور اس پر گواہ تھے (یعنی حکم الہٰی کا یقین رکھتے تھے) تو تم لوگوں سے مت ڈرنا اور مجھی سے ڈرتے رہنا اور میری آیتوں کے بدلے تھوڑی سی قیمت نہ لینا اور جو خدا کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ کافر ہیں', NULL, NULL, '793b10a01d47ec570ee3d3d39be7c3a197a12b4fb617fa3e9dd3a8e235a829e4'),
  ('ur.jalandhry', 5, 45, 714, 'اور ہم نے ان لوگوں کے لیے تورات میں یہ حکم لکھ دیا تھا کہ جان کے بدلے جان اور آنکھ کے بدلے آنکھ اور ناک کے بدلے ناک اور کان کے بدلے کان اور دانت کے بدلے دانت اور سب زخموں کا اسی طرح بدلہ ہے لیکن جو شخص بدلہ معاف کر دے وہ اس کے لیے کفارہ ہوگا اور جو خدا کے نازل فرمائے ہوئے احکام کے مطابق حکم نہ دے تو ایسے ہی لوگ بےانصاف ہیں', NULL, NULL, '3cba665246bbfc121348d211a4af601db57c9e2b9a11a41bb48b08a2815cd3cd'),
  ('ur.jalandhry', 5, 46, 715, 'اور ان پیغمبروں کے بعد انہی کے قدموں پر ہم نے عیسیٰ بن مریم کو بھیجا جو اپنے سے پہلے کی کتاب تورات کی تصدیق کرتے تھے اور ان کو انجیل عنایت کی جس میں ہدایت اور نور ہے اور تورات کی جو اس سے پہلی کتاب (ہے) تصدیق کرتی ہے اور پرہیزگاروں کو راہ بتاتی اور نصیحت کرتی ہے', NULL, NULL, '37d36aba997a0d42f1fbdc6d4bd59e833488a9de678cbec5698052b57b7d5326'),
  ('ur.jalandhry', 5, 47, 716, 'اور اہل انجیل کو چاہیئے کہ جو احکام خدا نے اس میں نازل فرمائے ہیں اس کے مطابق حکم دیا کریں اور جو خدا کے نازل کئے ہوئے احکام کے مطابق حکم نہ دے گا تو ایسے لوگ نافرماں ہیں', NULL, NULL, 'ba1e1de85439be0c78c18b38b71e7e9dcb07092ebbd55e5e8586ddd166dcaa2f'),
  ('ur.jalandhry', 5, 48, 717, 'اور (اے پیغمبر!) ہم نے تم پر سچی کتاب نازل کی ہے جو اپنے سے پہلی کتابوں کی تصدیق کرتی ہے اور ان (سب) پر شامل ہے تو جو حکم خدا نے نازل فرمایا ہے اس کے مطابق ان کا فیصلہ کرنا اور حق جو تمہارے پاس آچکا ہے اس کو چھوڑ کر ان کی خواہشوں کی پیروی نہ کرنا ہم نے تم میں سے ہر ایک (فرقے) کے لیے ایک دستور اور طریقہ مقرر کیا ہے اور اگر خدا چاہتا تو سب کو ایک ہی شریعت پر کر دیتا مگر جو حکم اس نے تم کو دیئے ہیں ان میں وہ تمہاری آزمائش کرنی چاہتا ہے سو نیک کاموں میں جلدی کرو تم سب کو خدا کی طرف لوٹ کر جانا ہے پھر جن باتوں میں تم کو اختلاف تھا وہ تم کو بتا دے گا', NULL, NULL, '12c5bd32ecb70725872ea50eded59cf25f9492323197f9190f89e49cbda5e982'),
  ('ur.jalandhry', 5, 49, 718, 'اور (ہم پھر تاکید کرتے ہیں کہ) جو (حکم) خدا نے نازل فرمایا ہے اسی کے مطابق ان میں فیصلہ کرنا اور ان کی خواہشوں کی پیروی نہ کرنا اور ان سے بچتے رہنا کہ کسی حکم سے جو خدا نے تم پر نازل فرمایا ہے یہ کہیں تم کو بہکانہ دیں اگر یہ نہ مانیں تو جان لو کہ خدا چاہتا ہے کہ ان کے بعض گناہوں کے سبب ان پر مصیبت نازل کرے اور اکثر لوگ تو نافرمان ہیں', NULL, NULL, '2550422eeb914ac40f31278f23fbba44c34c9def3a5549eedf794ee43a462f75'),
  ('ur.jalandhry', 5, 50, 719, 'کیا یہ زمانہٴ جاہلیت کے حکم کے خواہش مند ہیں؟ اور جو یقین رکھتے ہیں ان کے لیے خدا سے اچھا حکم کس کا ہے؟', NULL, NULL, '61888c4e95bcfc767acea06918cf272605a2f4d02c4c50c15e08fdbc8e3c398a'),
  ('ur.jalandhry', 5, 51, 720, 'اے ایمان والو! یہود اور نصاریٰ کو دوست نہ بناؤ یہ ایک دوسرے کے دوست ہیں اور جو شخص تم میں سے ان کو دوست بنائے گا وہ بھی انہیں میں سے ہوگا بیشک خدا ظالم لوگوں کو ہدایت نہیں دیتا', NULL, NULL, '0694d53f501c0fa218d2da28a7cf912aa78e56e4d450d95bce3515d82b4817f2'),
  ('ur.jalandhry', 5, 52, 721, 'تو جن لوگوں کے دلوں میں (نفاق کا) مرض ہے تم ان کو دیکھو گے کہ ان میں دوڑ دوڑ کے ملے جاتے ہیں کہتے ہیں کہ ہمیں خوف ہے کہ کہیں ہم پر زمانے کی گردش نہ آجائے سو قریب ہے کہ خدا فتح بھیجے یا اپنے ہاں سے کوئی اور امر (نازل فرمائے) پھر یہ اپنے دل کی باتوں پر جو چھپایا کرتے تھے پشیمان ہو کر رہ جائیں گے', NULL, NULL, '536019b91f6fb6ef565c3ceb12f9315c48713b312be5865d81a302dd117786ec'),
  ('ur.jalandhry', 5, 53, 722, 'اور اس (وقت) مسلمان (تعجب سے) کہیں گے کہ کیا یہ وہی ہیں جو خدا کی سخت سخت قسمیں کھایا کرتے تھے کہ ہم تمہارے ساتھ ہیں ان کےعمل اکارت گئے اور وہ خسارے میں پڑ گئے', NULL, NULL, '2490417b2a4e197f3f81e11ce143cc469fec7a28245944ad7ecf33ec43d9553c'),
  ('ur.jalandhry', 5, 54, 723, 'اے ایمان والو اگر کوئی تم میں سے اپنے دین سے پھر جائے گا تو خدا ایسے لوگ پیدا کر دے گا جن کو وہ دوست رکھے اور جسے وہ دوست رکھیں اور جو مومنوں کے حق میں نرمی کریں اور کافروں سے سختی سے پیش آئیں خدا کی راہ میں جہاد کریں اور کسی ملامت کرنے والی کی ملامت سے نہ ڈریں یہ خدا کا فضل ہے وہ جسے چاہتا ہے دیتا ہے اور الله بڑی کشائش والا اور جاننے والا ہے', NULL, NULL, '8d3cae6b57fa163ff5b64b7d8bb621410e531c6284bfadd4f785e1b12f5c64e4'),
  ('ur.jalandhry', 5, 55, 724, 'تمہارے دوست تو خدا اور اس کے پیغمبر اور مومن لوگ ہی ہیں جو نماز پڑھتے اور زکوٰة دیتے اور (خدا کے آگے) جھکتے ہیں', NULL, NULL, 'b20a44c3b8473ac5cd8bd5b446913000b6b0b15fb410f74bef08def37558c41c'),
  ('ur.jalandhry', 5, 56, 725, 'اور جو شخص خدا اور اس کے پیغمبر اور مومنوں سے دوستی کرے گا تو (وہ خدا کی جماعت میں داخل ہوگا اور) خدا کی جماعت ہی غلبہ پانے والی ہے', NULL, NULL, '3a33281dba7c0ffc95d6d7906364702ad138a2dd2466d4d964a7a27b440816b0'),
  ('ur.jalandhry', 5, 57, 726, 'اے ایمان والوں! جن لوگوں کو تم سے پہلے کتابیں دی گئی تھیں ان کو اور کافروں کو جنہوں نے تمہارے دین کو ہنسی اور کھیل بنا رکھا ہے دوست نہ بناؤ اور مومن ہو تو خدا سے ڈرتے رہو', NULL, NULL, '384aba3659dfeee371b2ce9df9baf39f95792018608fd12f858cf647d28fd0a5'),
  ('ur.jalandhry', 5, 58, 727, 'اور جب تم لوگ نماز کے لیے اذان دیتے ہو تو یہ اسے بھی ہنسی اور کھیل بناتے ہیں یہ اس لیے کہ سمجھ نہیں رکھتے', NULL, NULL, 'ecb3713d102a25525321bcbdc9b7a0f99d9ff654b1df975a7702a8f930f81ce6'),
  ('ur.jalandhry', 5, 59, 728, 'کہو کہ اے اہل کتاب! تم ہم میں برائی ہی کیا دیکھتے ہو سوا اس کے کہ ہم خدا پر اور جو (کتاب) ہم پر نازل ہوئی اس پر اور جو (کتابیں) پہلے نازل ہوئیں ان پر ایمان لائے ہیں اور تم میں اکثر بدکردار ہیں', NULL, NULL, '67e24d98c0ac342acf9488d606bcfd2b3018b4ec2526b187accb29be7cc881ec'),
  ('ur.jalandhry', 5, 60, 729, 'کہو کہ میں تمہیں بتاؤں کہ خدا کے ہاں اس سے بھی بدتر جزا پانے والے کون ہیں؟ وہ لوگ ہیں جن پر خدا نے لعنت کی اور جن پر وہ غضبناک ہوا اور (جن کو) ان میں سے بندر اور سور بنا دیا اور جنہوں نے شیطان کی پرستش کی ایسے لوگوں کا برا ٹھکانہ ہے اور وہ سیدھے رستے سے بہت دور ہیں', NULL, NULL, 'dd2ce0a6c83aba5be6348efb147fbd4a276192e02c92fa3f0d057f839660774a'),
  ('ur.jalandhry', 5, 61, 730, 'اور جب یہ لوگ تمہارے پاس آتے ہیں تو کہتے ہیں کہ ہم ایمان لے آئے حالانکہ کفر لے کر آتے ہیں اور اسی کو لیکر جاتے ہیں اور جن باتوں کو یہ مخفی رکھتے ہیں خدا ان کو خوب جانتا ہے', NULL, NULL, '2e416ecedf92c80f04897fe0984ed8cfac95aa70c84ccc9b44ddf107af2b8cbe'),
  ('ur.jalandhry', 5, 62, 731, 'اور تم دیکھو گے کہ ان میں اکثر گناہ اور زیادتی اور حرام کھانے میں جلدی کر رہے ہیں بےشک یہ جو کچھ کرتے ہیں برا کرتے ہیں', NULL, NULL, '42dba3b020c564e26e381116e462009302a5001ce2e50366399caa034396d9f7'),
  ('ur.jalandhry', 5, 63, 732, 'بھلا ان کے مشائخ اور علماء انہیں گناہ کی باتوں اور حرام کھانے سے منع کیوں نہیں کرتے؟ بلاشبہ وہ بھی برا کرتے ہیں', NULL, NULL, 'd5b672978819d4707f9eccad92334820c58f27a6e1c0e6412b36b97e10bbb107'),
  ('ur.jalandhry', 5, 64, 733, 'اور یہود کہتے ہیں کہ خدا کا ہاتھ (گردن سے) بندھا ہوا ہے (یعنی الله بخیل ہے) انہیں کے ہاتھ باندھے جائیں اور ایسا کہنے کے سبب ان پر لعنت ہو (اس کا ہاتھ بندھا ہوا نہیں) بلکہ اس کے دونوں ہاتھ کھلے ہیں وہ جس طرح (اور جتنا) چاہتا ہے خرچ کرتا ہے اور (اے محمد) یہ (کتاب) جو تمہارے پروردگار کی طرف سے تم پر نازل ہوئی اس سے ان میں سے اکثر کی شرارت اور انکار اور بڑھے گا اور ہم نے ان کے باہم عداوت اور بغض قیامت تک کے لیے ڈال دیا ہے یہ جب لڑائی کے لیے آگ جلاتے ہیں خدا اس کو بجھا دیتا ہے اور یہ ملک میں فساد کے لیے دوڑے پھرتے ہیں اور خدا فساد کرنے والوں کو دوست نہیں رکھتا', NULL, NULL, 'a8b5e7e740dcc072e7ab2e9ed8a44c447a1492bb1afd450e6ba998a789f4001f'),
  ('ur.jalandhry', 5, 65, 734, 'اور اگر اہل کتاب ایمان لاتے اور پرہیز گاری کرتے تو ہم ان سے ان کے گناہ محو کر دیتے اور ان کو نعمت کے باغوں میں داخل کرتے', NULL, NULL, '2c966117e13e25fcb4d71b8f1a61a7c908ad3ca3e86cfbd4045bd7178f8c16ee'),
  ('ur.jalandhry', 5, 66, 735, 'اور اگر وہ تورات اور انجیل کو اور جو (اور کتابیں) ان کے پروردگار کی طرف سے ان پر نازل ہوئیں ان کو قائم رکھتے (تو ان پر رزق مینہ کی طرح برستا کہ) اپنے اوپر سے پاؤں کے نیچے سے کھاتے ان میں کچھ لوگ میانہ رو ہیں اور بہت سے ایسے ہیں جن کے اعمال برے ہیں', NULL, NULL, '536896982b94f7d086b452755de7d408867eed6c3c6aa093e3671697472b56b0'),
  ('ur.jalandhry', 5, 67, 736, 'اے پیغمبر جو ارشادات خدا کی طرف سے تم پر نازل ہوئے ہیں سب لوگوں کو پہنچا دو اور اگر ایسا نہ کیا تو تم خدا کے پیغام پہنچانے میں قاصر رہے (یعنی پیغمبری کا فرض ادا نہ کیا) اور خدا تم کو لوگوں سے بچائے رکھے گا بیشک خدا منکروں کو ہدایت نہیں دیتا', NULL, NULL, '0cc2d4899cd5577fb2be701c0c5c70ed9545ba724e3511e6f0fb34d53dd0099e'),
  ('ur.jalandhry', 5, 68, 737, 'کہو کہ اے اہل کتاب! جب تک تم تورات اور انجیل کو اور جو (اور کتابیں) تمہارے پروردگار کی طرف سے تم لوگوں پر نازل ہوئیں ان کو قائم نہ رکھو گے کچھ بھی راہ پر نہیں ہو سکتے اور یہ (قرآن) جو تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے ان میں سے اکثر کی سرکشی اور کفر اور بڑھے گا تو تم قوم کفار پر افسوس نہ کرو', NULL, NULL, '09edfad7f8ba057d0650bed599594d8d5a52dcb6ad3ddd2d7be927ca7581cdec'),
  ('ur.jalandhry', 5, 69, 738, 'جو لوگ خدا پر اور روز آخرت پر ایمان لائیں گے اور عمل نیک کریں گے خواہ وہ مسلمان ہوں یا یہودی یا ستارہ پرست یا عیسائی ان کو (قیامت کے دن) نہ کچھ خوف ہو گا اور نہ غمناک ہوں گے', NULL, NULL, 'f12243a41c75dbfb83aa0d556636cf126c36d9041c4d3a87f2c1e3cc422377b1'),
  ('ur.jalandhry', 5, 70, 739, 'ہم نے بنی اسرائیل سے عہد بھی لیا اور ان کی طرف پیغمبر بھی بھیجے (لیکن) جب کوئی پیغمبر ان کے پاس ایسی باتیں لےکر آتا جن کو ان کے دل نہیں چاہتے تھے تو وہ (انبیاء کی) ایک جماعت کو تو جھٹلا دیتے اور ایک جماعت کو قتل کر دیتے تھے', NULL, NULL, '2f7c403029191500132919e18b75a26bd9720961d78f3bcf3e42610a30acb90e'),
  ('ur.jalandhry', 5, 71, 740, 'اور خیال کرتے تھے کہ (اس سے ان پر) کوئی آفت نہیں آنے کی تو وہ اندھے اور بہرے ہو گئے پھر خدا نے ان پر مہربانی فرمائی (لیکن) پھر ان میں سے بہت سے اندھے اور بہرے ہو گئے اور خدا ان کے سب کاموں کو دیکھ رہا ہے', NULL, NULL, '7319f44d864590dbcc0d04138c794744782d6b44752e9d335a8b8917352c29b2'),
  ('ur.jalandhry', 5, 72, 741, 'وہ لوگ بےشبہ کافر ہیں جو کہتے ہیں کہ مریم کے بیٹے (عیسیٰ) مسیح خدا ہیں حالانکہ مسیح یہود سے یہ کہا کرتے تھے کہ اے بنی اسرائیل خدا ہی کی عبادت کرو جو میرا بھی پروردگار ہے اور تمہارا بھی (اور جان رکھو کہ) جو شخص خدا کے ساتھ شرک کرے گا خدا اس پر بہشت حرام کر دے گا اور اس کا ٹھکانہ دوزخ ہے اور ظالموں کا کوئی مددگار نہیں', NULL, NULL, '591bb1a016a9a13e6340be75d3de8f08cb7b03f19ade48a78f35c292fdfb20e6'),
  ('ur.jalandhry', 5, 73, 742, 'وہ لوگ (بھی) کافر ہیں جو اس بات کے قائل ہیں کہ خدا تین میں کا تیسرا ہے حالانکہ اس معبود یکتا کے سوا کوئی عبادت کے لائق نہیں اگر یہ لوگ ایسے اقوال (وعقائد) سے باز نہیں آئیں گے تو ان میں جو کافر ہوئے ہیں وہ تکلیف دینے والا عذاب پائیں گے', NULL, NULL, '19c04a69965e651ebcffe287cb24b6fdcce63a7edf46140b2de9590de761c887'),
  ('ur.jalandhry', 5, 74, 743, 'تو یہ کیوں خدا کے آگے توبہ نہیں کرتے اور اس سے گناہوں کی معافی نہیں مانگتے اور خدا تو بخشنے والا مہربان ہے', NULL, NULL, '10150619020b405ed1e86b54103e93e3c83672ebd8db81a5c571a68e5d505528'),
  ('ur.jalandhry', 5, 75, 744, 'مسیح ابن مریم تو صرف (خدا) کے پیغمبر تھے ان سے پہلے بھی بہت سے رسول گزر چکے تھے اور ان کی والدہ (مریم خدا کی) ولی اور سچی فرمانبردار تھیں دونوں (انسان تھے اور) کھانا کھاتے تھے دیکھو ہم ان لوگوں کے لیے اپنی آیتیں کس طرح کھول کھول کر بیان کرتے ہیں پھر (یہ) دیکھو کہ یہ کدھر الٹے جا رہے ہیں', NULL, NULL, '221e2455116424b7ae963376c4a17ea6e47c28ca5588a3a885751ff16c31f584'),
  ('ur.jalandhry', 5, 76, 745, 'کہو کہ تم خدا کے سوا ایسی چیز کی کیوں پرستش کرتے ہو جس کو تمہارے نفع اور نقصان کا کچھ بھی اختیار نہیں؟ اور خدا ہی (سب کچھ) سنتا جانتا ہے', NULL, NULL, '1abe76989ce02c0d9eec7fb7da9c23fd8a1b4b66137d108911a4cc9ab36a4517'),
  ('ur.jalandhry', 5, 77, 746, 'کہو کہ اے اہل کتاب! اپنے دین (کی بات) میں ناحق مبالغہ نہ کرو اور ایسے لوگوں کی خواہشوں کے پیچھے نہ چلو جو (خود بھی) پہلے گمراہ ہوئے اور اَور بھی اکثروں کو گمراہ کر گئے اور سیدھے رستے سے بھٹک گئے', NULL, NULL, '9a05ffdfb8b54346f5d889f4f04e94f04df4748c00bb64b274245e0ccbac266e'),
  ('ur.jalandhry', 5, 78, 747, 'جو لوگ بنی اسرائیل میں کافر ہوئے ان پر داؤد اور عیسیٰ بن مریم کی زبان سے لعنت کی گئی یہ اس لیے کہ نافرمانی کرتے تھے اور حد سے تجاوز کرتے تھے', NULL, NULL, '6a3fb3e7a2240cd2c1233e279c8777a98fe12cfd5449288cf88cfe51b1f24433'),
  ('ur.jalandhry', 5, 79, 748, '(اور) برے کاموں سے جو وہ کرتے تھے ایک دوسرے کو روکتے نہیں تھے بلاشبہ وہ برا کرتے تھے', NULL, NULL, 'e915a65772fa187d0792c3274389143dda9805a66bcb40408f317ee1f627aabc'),
  ('ur.jalandhry', 5, 80, 749, 'تم ان میں سے بہتوں کو دیکھو گے کہ کافروں سے دوستی رکھتے ہیں انہوں نے جو کچھ اپنے واسطے آگے بھیجا ہے برا ہے (وہ یہ) کہ خدا ان سے ناخوش ہوا اور وہ ہمیشہ عذاب میں (مبتلا) رہیں گے', NULL, NULL, 'a38b155187b014b25321f665c4d6ca79e119c831f29c503414ce907dbeb12dac'),
  ('ur.jalandhry', 5, 81, 750, 'اور اگر وہ خدا پر اور پیغمبر پر اور جو کتاب ان پر نازل ہوئی تھی اس پر یقین رکھتے تو ان لوگوں کو دوست نہ بناتے لیکن ان میں اکثر بدکردار ہیں', NULL, NULL, 'cf055968739aca86b3ceb8a63281597a16a3719a16ccc93b4e3f22e3c4eaf935'),
  ('ur.jalandhry', 5, 82, 751, '(اے پیغمبرﷺ!) تم دیکھو گے کہ مومنوں کے ساتھ سب سے زیادہ دشمنی کرنے والے یہودی اور مشرک ہیں اور دوستی کے لحاظ سے مومنوں سے قریب تر ان لوگوں کو پاؤ گے جو کہتے ہیں کہ ہم نصاریٰ ہیں یہ اس لیے کہ ان میں عالم بھی ہیں اور مشائخ بھی اور وہ تکبر نہیں کرتے', NULL, NULL, 'fb679e2523ba7ad6218f147c9c12b15161f9cd889efeef067326fc6ab3902265'),
  ('ur.jalandhry', 5, 83, 752, 'اور جب اس (کتاب) کو سنتے ہیں جو (سب سے پہلے) پیغمبر (محمدﷺ) پر نازل ہوئی تو تم دیکھتے ہو کہ ان کی آنکھوں سے آنسو جاری ہو جاتے ہیں اس لیے کہ انہوں نے حق بات پہچان لی اور وہ (خدا کی جناب میں) عرض کرتے ہیں کہ اے پروردگار ہم ایمان لے آئے تو ہم کو ماننے والوں میں لکھ لے', NULL, NULL, '364bfcd54c0e15e825c5ac7fae6f1df4f2f07f838d966b91d2470f06b9cfe8cc'),
  ('ur.jalandhry', 5, 84, 753, 'اور ہمیں کیا ہوا ہے کہ خدا پر اور حق بات پر جو ہمارے پاس آئی ہے ایمان نہ لائیں اور ہم امید رکھتے ہیں کہ پروردگار ہم کو نیک بندوں کے ساتھ (بہشت میں) داخل کرے گا', NULL, NULL, 'adbb11bff39d7468cb80ea15b54707fe60bff1b30ce29cbddf89e6974bb0e858'),
  ('ur.jalandhry', 5, 85, 754, 'تو خدا نے ان کو اس کہنے کے عوض (بہشت کے) باغ عطا فرمائے جن کے نیچے نہریں بہہ رہی ہیں وہ ہمیشہ ان میں رہیں گے اور نیکو کاروں کا یہی صلہ ہے', NULL, NULL, '615e7d6ae8a7113a7c3cad067255c5bd0aea3498341ec48fec08da8ea42df2d6'),
  ('ur.jalandhry', 5, 86, 755, 'اور جن لوگوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا وہ جہنمی ہیں', NULL, NULL, '6cddac6b198e03d156a201c033fd6ffd6e9f464f38221514720baeb3bba0a3af'),
  ('ur.jalandhry', 5, 87, 756, 'مومنو! جو پاکیزہ چیزیں خدا نے تمہارے لیے حلال کی ہیں ان کو حرام نہ کرو اور حد سے نہ بڑھو کہ خدا حد سے بڑھنے والوں کو دوست نہیں رکھتا', NULL, NULL, '81d485277c600538a15fc68fd222aef2275b91bfc10dcc45eced3c86f890dedb'),
  ('ur.jalandhry', 5, 88, 757, 'اور جو حلال طیّب روزی خدا نے تم کو دی ہے اسے کھاؤ اور خدا سے جس پر ایمان رکھتے ہو ڈرتے رہو', NULL, NULL, '2ac4f87cf7eeb508a30f7744ed78665d8bb600bcaae1198c9c9a698be07bc535'),
  ('ur.jalandhry', 5, 89, 758, 'خدا تمہاری بےارادہ قسموں پر تم سے مواخذہ نہیں کرے گا لیکن پختہ قسموں پر (جن کے خلاف کرو گے) مواخذہ کرے گا تو اس کا کفارہ دس محتاجوں کو اوسط درجے کا کھانا کھلانا ہے جو تم اپنے اہل وعیال کو کھلاتے ہو یا ان کو کپڑے دینا یا ایک غلام آزاد کرنا اور جس کو میسر نہ ہو وہ تین روزے رکھے یہ تمہاری قسموں کا کفارہ ہے جب تم قسم کھا لو (اور اسے توڑ دو) اور (تم کو) چاہئے کہ اپنی قسموں کی حفاظت کرو اس طرح خدا تمہارے (سمجھانے کے) لیے اپنی آیتیں کھول کھول کر بیان فرماتا ہے تاکہ تم شکر کرو', NULL, NULL, '1662a1032c35cc2aaf536f02072035553a218085cb030930178c9b846608c022'),
  ('ur.jalandhry', 5, 90, 759, 'اے ایمان والو! شراب اور جوا اور بت اور پاسے (یہ سب) ناپاک کام اعمال شیطان سے ہیں سو ان سے بچتے رہنا تاکہ نجات پاؤ', NULL, NULL, '2f36058a23b46de7479eb4ec104048450de6b51817af9a12930eb52fe7aa0963'),
  ('ur.jalandhry', 5, 91, 760, 'شیطان تو یہ چاہتا ہے کہ شراب اور جوئے کے سبب تمہارے آپس میں دشمنی اور رنجش ڈلوا دے اور تمہیں خدا کی یاد سے اور نماز سے روک دے تو تم کو (ان کاموں سے) باز رہنا چاہیئے', NULL, NULL, 'db4afc32c96beb215309c3d6b767585c8f2451fa75cfb571e0c3cae7caf5cb9b'),
  ('ur.jalandhry', 5, 92, 761, 'اور خدا کی فرمانبرداری اور رسولِ (خدا) کی اطاعت کرتے رہو اور ڈرتے رہو اگر منہ پھیرو گے تو جان رکھو کہ ہمارے پیغمبر کے ذمے تو صرف پیغام کا کھول کر پہنچا دینا ہے', NULL, NULL, '3b145e1c31c9f4628f62b49dc30a0c362e62f77d9c6c072f965d0c7236a677f2'),
  ('ur.jalandhry', 5, 93, 762, 'جو لوگ ایمان لائے اور نیک کام کرتے رہے ان پر ان چیزوں کا کچھ گناہ نہیں جو وہ کھا چکے جب کہ انہوں نے پرہیز کیا اور ایمان لائے اور نیک کام کیے پھر پرہیز کیا اور ایمان لائے پھر پرہیز کیا اور نیکو کاری کی اور خدا نیکو کاروں کو دوست رکھتا ہے', NULL, NULL, '0b76781aca692aed442882c77263ac08d1580e4a32730876ce9a05f0a120af0a'),
  ('ur.jalandhry', 5, 94, 763, 'مومنو! کسی قدر شکار سے جن کو تم ہاتھوں اور نیزوں سے پکڑ سکو خدا تمہاری آزمائش کرے گا (یعنی حالت احرام میں شکار کی ممانعت سے) تا کہ معلوم کرے کہ اس سے غائبانہ کون ڈرتا ہے تو جو اس کے بعد زیادتی کرے اس کے لیے دکھ دینے والا عذاب (تیار) ہے', NULL, NULL, 'bf00cbef3268b3a9f5ea764c22ab9dc050967f1e0dc9923c7a294a35ed983b1d'),
  ('ur.jalandhry', 5, 95, 764, 'مومنو! جب تم احرام کی حالت میں ہو تو شکار نہ مارنا اور جو تم میں سے جان بوجھ کر اسے مارے تو (یا تو اس کا) بدلہ (دے اور وہ یہ ہے کہ) اسی طرح کا چارپایہ جسے تم میں دو معتبر شخص مقرر کردیں قربانی (کرے اور یہ قربانی) کعبے پہنچائی جائے یا کفارہ (دے اور وہ) مسکینوں کو کھانا کھلانا (ہے) یا اس کے برابر روزے رکھے تاکہ اپنے کام کی سزا (کا مزہ) چکھے (اور) جو پہلے ہو چکا وہ خدا نے معاف کر دیا اور جو پھر (ایسا کام) کرے گا تو خدا اس سے انتقام لے گا اور خدا غالب اور انتقام لینے والا ہے', NULL, NULL, 'f86a7f7f514592da18f2aebb12a9bccb4f0b87ac1fb68e900b9dddb38af64d98'),
  ('ur.jalandhry', 5, 96, 765, 'تمہارے لیے دریا (کی چیزوں) کا شکار اور ان کا کھانا حلال کر دیا گیا ہے (یعنی) تمہارے اور مسافروں کے فائدے کے لیے اور جنگل (کی چیزوں) کا شکار جب تک تم احرام کی حالت میں رہو تم پر حرام ہے اور خدا سے جس کے پاس تم (سب) جمع کئے جاؤ گے ڈرتے رہو', NULL, NULL, 'f695455c8520afeacfa9b74a7136ca87d42bad834d6d396c461bc15feda83878'),
  ('ur.jalandhry', 5, 97, 766, 'خدا نے عزت کے گھر (یعنی) کعبے کو لوگوں کے لیے موجب امن مقرر فرمایا ہے اور عزت کے مہینوں کو اور قربانی کو اور ان جانوروں کو جن کے گلے میں پٹے بندھے ہوں یہ اس لیے کہ تم جان لو کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے خدا سب کو جانتا ہے اور یہ کہ خدا کو ہر چیز کا علم ہے', NULL, NULL, 'a2435bec3916e711f51ebc0a4b80fe0cf12cfaae324c3aa0718808afc7e7521f'),
  ('ur.jalandhry', 5, 98, 767, 'جان رکھو کہ خدا سخت غداب دینے والا ہے اور یہ کہ خدا بخشنے والا مہربان بھی ہے', NULL, NULL, 'ef0d3b221d5ad90d10e09b4ce7b0398722058a1e627a59776f5743932700f8a5'),
  ('ur.jalandhry', 5, 99, 768, 'پیغمبر کے ذمے تو صرف پیغام خدا کا پہنچا دینا ہے اور جو کچھ تم ظاہر کرتے ہو اور جو کچھ مخفی کرتے ہو خدا کو سب معلوم ہے', NULL, NULL, 'ef1f94400fda883dd428c09547b28c63815f0bc1e0db045bd1dc51a0751b3336'),
  ('ur.jalandhry', 5, 100, 769, 'کہہ دو کہ ناپاک چیزیں اور پاک چیزیں برابر نہیں ہوتیں گو ناپاک چیزوں کی کثرت تمہیں خوش ہی لگے تو عقل والو خدا سے ڈرتے رہو تاکہ رستگاری حاصل کرو', NULL, NULL, '5b9a94e56aff66442c22f3df10bd416317a4ec10ea408d642289288fa5594d59'),
  ('ur.jalandhry', 5, 101, 770, 'مومنو! ایسی چیزوں کے بارے میں مت سوال کرو کہ اگر (ان کی حقیقتیں) تم پر ظاہر کر دی جائیں تو تمہیں بری لگیں اور اگر قرآن کے نازل ہونے کے ایام میں ایسی باتیں پوچھو گے تو تم پر ظاہر بھی کر دی جائیں گی (اب تو) خدا نے ایسی باتوں (کے پوچھنے) سے درگزر فرمایا ہے اور خدا بخشنے والا بردبار ہے', NULL, NULL, 'bbb3f2c2b13311e130a3fd48ab95998c6543d874fd5c5f898cb5e839dfbbe837'),
  ('ur.jalandhry', 5, 102, 771, 'اس طرح کی باتیں تم سے پہلے لوگوں نے بھی پوچھی تھیں (مگر جب بتائی گئیں تو) پھر ان سے منکر ہو گئے', NULL, NULL, '8b8cd86e9b7122e918d8a919ad16f727402157acade9d6e44f5c1f55cdede481'),
  ('ur.jalandhry', 5, 103, 772, 'خدا نے نہ تو بحیرہ کچھ چیز بنایا ہے اور نہ سائبہ اور نہ وصیلہ اور نہ حام بلکہ کافر خدا پر جھوٹ افترا کرتے ہیں اور یہ اکثر عقل نہیں رکھتے', NULL, NULL, 'af61b0b4101da2d94d26df92d1a1876c1309b9f9e580f3bc527a9f4c5d61b61f'),
  ('ur.jalandhry', 5, 104, 773, 'اور جب ان لوگوں سے کہا جاتا ہے کہ جو (کتاب) خدا نے نازل فرمائی ہے اس کی اور رسول الله کی طرف رجوع کرو تو کہتے ہیں کہ جس طریق پر ہم نے اپنے باپ دادا کو پایا ہے وہی ہمیں کافی ہے بھلا اگر ان کے باپ دادا نہ تو کچھ جانتے ہوں اور نہ سیدھے رستے پر ہوں (تب بھی؟)', NULL, NULL, '95aa3fa29616560332f8c0108010ddd0650da0e4acabd788f997b6945f0f876d'),
  ('ur.jalandhry', 5, 105, 774, 'اے ایمان والو! اپنی جانوں کی حفاظت کرو جب تم ہدایت پر ہو تو کوئی گمراہ تمہارا کچھ بھی بگاڑ نہیں سکتا تم سب کو خدا کی طرف لوٹ کر جانا ہے اس وقت وہ تم کو تمہارے سب کاموں سے جو (دنیا میں) کئے تھے آگاہ کرے گا (اور ان کا بدلہ دے گا)', NULL, NULL, 'a99f78870fd40a6bdd9f711c2a498fb12668d0dbc7902e4787c80dec1886e0d5'),
  ('ur.jalandhry', 5, 106, 775, 'مومنو! جب تم میں سے کسی کی موت آموجود ہو تو شہادت (کا نصاب) یہ ہے کہ وصیت کے وقت تم (مسلمانوں) میں سے دو عادل (یعنی صاحب اعتبار) گواہ ہوں یا اگر (مسلمان نہ ملیں اور) تم سفر کر رہے ہو اور (اس وقت) تم پر موت کی مصیبت واقع ہو تو کسی دوسرے مذہب کے دو (شخصوں کو) گواہ (کر لو) اگر تم کو ان گواہوں کی نسبت کچھ شک ہو تو ان کو (عصر کی) نماز کے بعد کھڑا کرو اور دونوں خدا کی قسمیں کھائیں کہ ہم شہادت کا کچھ عوض نہیں لیں گے گو ہمارا رشتہ دار ہی ہو اور نہ ہم الله کی شہادت کو چھپائیں گے اگر ایسا کریں گے تو گنہگار ہوں گے', NULL, NULL, 'c119c1d4b7fa3cc1a97a5a327d255e656bf140c1ba1c254af32bd14548a12d50'),
  ('ur.jalandhry', 5, 107, 776, 'پھر اگر معلوم ہو جائے کہ ان دونوں نے (جھوٹ بول کر) گناہ حاصل کیا ہے تو جن لوگوں کا انہوں نے حق مارنا چاہا تھا ان میں سے ان کی جگہ اور دو گواہ کھڑے ہوں جو (میت سے) قرابت قریبہ رکھتے ہوں پھر وہ خدا کی قسمیں کھائیں کہ ہماری شہادت ان کی شہادت سے بہت اچھی ہے اور ہم نے کوئی زیادتی نہیں کی ایسا کیا ہو تو ہم بےانصاف ہیں', NULL, NULL, '0e33011f756dc7f329b7b211914dfb528ee96c612b816eda29dfd24ec16da1c3'),
  ('ur.jalandhry', 5, 108, 777, 'اس طریق سے بہت قریب ہے کہ یہ لوگ صحیح صحیح شہادت دیں یا اس بات سے خوف کریں کہ (ہماری) قسمیں ان کی قسموں کے بعد رد کر دی جائیں گی اور خدا سے ڈرو اور اس کے حکموں کو (گوشِ ہوش سے) سنو اور خدا نافرمان لوگوں کو ہدایت نہیں دیتا', NULL, NULL, '12daa5aaaf4de6c14743b124c09a13095b6d7adc3571cb8950610c56a78697e9'),
  ('ur.jalandhry', 5, 109, 778, '(وہ دن یاد رکھنے کے لائق ہے) جس دن خدا پیغمبروں کو جمع کرے گا پھر ان سے پوچھے گا کہ تمہیں کیا جواب ملا تھا وہ عرض کریں گے کہ ہمیں کچھ معلوم نہیں توہی غیب کی باتوں سے واقف ہے', NULL, NULL, '0110625d6de052051641011f8dd374b251ed066641eb908ba0cdc9cbef353119'),
  ('ur.jalandhry', 5, 110, 779, 'جب خدا (عیسیٰ سے) فرمائے گا کہ اے عیسیٰ بن مریم! میرے ان احسانوں کو یاد کرو جو میں نے تم پر اور تمہاری والدہ پر کئے جب میں نے روح القدس (یعنی جبرئیل) سے تمہاری مدد کی تم جھولے میں اور جوان ہو کر (ایک ہی نسق پر) لوگوں سے گفتگو کرتے تھے اور جب میں نے تم کو کتاب اور دانائی اور تورات اور انجیل سکھائی اور جب تم میرے حکم سے مٹی کا جانور بنا کر اس میں پھونک مار دیتے تھے تو وہ میرے حکم سے اڑنے لگتا تھا اور مادر زاد اندھے اور سفید داغ والے کو میرے حکم سے چنگا کر دیتے تھے اور مردے کو میرے حکم سے (زندہ کرکے قبر سے) نکال کھڑا کرتے تھے اور جب میں نے بنی اسرائیل (کے ہاتھوں) کو تم سے روک دیا جب تم ان کے پاس کھلے نشان لے کر آئے تو جو ان میں سے کافر تھے کہنے لگے کہ یہ صریح جادو ہے', NULL, NULL, '9e9fdedd7cec95bf873c2d63d52bbf897dbe65a8ae48a8e96c5da259f1d0402e'),
  ('ur.jalandhry', 5, 111, 780, 'اور جب میں نے حواریوں کی طرف حکم بھیجا کہ مجھ پر اور میرے پیغمبر پر ایمان لاؤ وہ کہنے لگے کہ (پروردگار) ہم ایمان لائے تو شاہد رہیو کہ ہم فرمانبردار ہیں', NULL, NULL, '7edc7adb7c360432b81aee47d527b2784c7c78de175a7af8eedf29e7520c9d63'),
  ('ur.jalandhry', 5, 112, 781, '(وہ قصہ بھی یاد کرو) جب حواریوں نے کہا کہ اے عیسیٰ بن مریم! کیا تمہارا پروردگار ایسا کر سکتا ہے کہ ہم پر آسمان سے (طعام کا) خوان نازل کرے؟ انہوں نے کہا کہ اگر ایمان رکھتے ہو تو خدا سے ڈرو', NULL, NULL, '3a4df1864f957889b345309a5cc3f442170d820f0a6eddb718208faf909100bc'),
  ('ur.jalandhry', 5, 113, 782, 'وہ بولے کہ ہماری یہ خواہش ہے کہ ہم اس میں سے کھائیں اور ہمارے دل تسلی پائیں اور ہم جان لیں کہ تم نے ہم سے سچ کہا ہے اور ہم اس (خوان کے نزول) پر گواہ رہیں', NULL, NULL, '3e38b53624e073717acf7c85119ee23dca1910a4c965fecb8c67dedaba99eed4'),
  ('ur.jalandhry', 5, 114, 783, '(تب) عیسیٰ بن مریم نے دعا کی کہ اے ہمارے پروردگار! ہم پر آسمان سے خوان نازل فرما کہ ہمارے لیے (وہ دن) عید قرار پائے یعنی ہمارے اگلوں اور پچھلوں (سب) کے لیے اور وہ تیری طرف سے نشانی ہو اور ہمیں رزق دے تو بہتر رزق دینے والا ہے', NULL, NULL, '9667eecde1561aff74990e31842c6fd09c1270a30e077822141d9bca9e71a1b4'),
  ('ur.jalandhry', 5, 115, 784, 'خدا نے فرمایا میں تم پر ضرور خوان نازل فرماؤں گا لیکن جو اس کے بعد تم میں سے کفر کرے گا اسے ایسا عذاب دوں گا کہ اہل عالم میں کسی کو ایسا عذاب نہ دوں گا', NULL, NULL, '3c0b8ba8d6575b462227453f6cbec6436ea4fb0a13648ff05ced40568720943f'),
  ('ur.jalandhry', 5, 116, 785, 'اور (اس وقت کو بھی یاد رکھو) جب خدا فرمائے گا کہ اے عیسیٰ بن مریم! کیا تم نے لوگوں سے کہا تھا کہ خدا کے سوا مجھے اور میری والدہ کو معبود مقرر کرو؟ وہ کہیں گے کہ تو پاک ہے مجھے کب شایاں تھا کہ میں ایسی بات کہتا جس کا مجھے کچھ حق نہیں اگر میں نے ایسا کہا ہوگا تو تجھ کو معلوم ہوگا (کیونکہ) جو بات میرے دل میں ہے تو اسے جانتا ہے اور جو تیرے ضمیر میں ہے اسے میں نہیں جانتا بےشک تو علاّم الغیوب ہے', NULL, NULL, 'c08700b0eb5c90471f916f9c385d9b3396cb9cb9f0c881a89545d7a8fa84a99c'),
  ('ur.jalandhry', 5, 117, 786, 'میں نے ان سے کچھ نہیں کہا بجز اس کے جس کا تو نے مجھے حکم دیا ہے وہ یہ کہ تم خدا کی عبادت کرو جو میرا اور تمہارا سب کا پروردگار ہے اور جب تک میں ان میں رہا ان (کے حالات) کی خبر رکھتا رہا جب تو نے مجھے دنیا سے اٹھا لیا تو تو ان کا نگران تھا اور تو ہر چیز سے خبردار ہے', NULL, NULL, 'b9c572e0f5ff850e199b53680fe835da8376cb53647bdc1f197dd6c9c4efdc16'),
  ('ur.jalandhry', 5, 118, 787, 'اگر تو ان کو عذاب دے تو یہ تیرے بندے ہیں اور اگر بخش دے تو (تیری مہربانی ہے) بےشک تو غالب اور حکمت والا ہے', NULL, NULL, 'b76d533e31d496613c119a693aaaf4788b9499c4c499e283cc90021c241ae5cb'),
  ('ur.jalandhry', 5, 119, 788, 'خدا فرمائے گا کہ آج وہ دن ہے کہ راست بازوں کو ان کی سچائی ہی فائدہ دے گی ان کے لئے باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں ابدالآباد ان میں بستے رہیں گے خدا ان سے خوش ہے اور وہ خدا سے خوش ہیں یہ بڑی کامیابی ہے', NULL, NULL, 'd60f89ba95670c99f33f5cb3ce5852a5413fc0425e31f79a30e23c43222cece5'),
  ('ur.jalandhry', 5, 120, 789, 'آسمان اور زمین اور جو کچھ ان (دونوں) میں ہے سب پر خدا ہی کی بادشاہی ہے اور وہ ہر چیز پر قادر ہے', NULL, NULL, '9826a995c5b315bb9911314349c507e0e849effc1e36ff20071cf85a21298c53'),
  ('ur.jalandhry', 6, 1, 790, 'ہر طرح کی تعریف خدا ہی کو سزاوار ہے جس نے آسمانوں اور زمین کو پیدا کیا اور اندھیرا اور روشنی بنائی پھر بھی کافر (اور چیزوں کو) خدا کے برابر ٹھیراتے ہیں', NULL, NULL, 'c1233b11893b1ba8d92f35ed0721ea5275378e2e8db53c6c065fdaa76b792b1d'),
  ('ur.jalandhry', 6, 2, 791, 'وہی تو ہے جس نے تم کو مٹی سے پیدا کیا پھر (مرنے کا) ایک وقت مقرر کر دیا اور ایک مدت اس کے ہاں اور مقرر ہے پھر بھی تم (اے کافرو خدا کے بارے میں) شک کرتے ہو', NULL, NULL, 'b50c5df9ad409e5dabea8821bf90e9c786349041c838a796c53df0da1b8fc318'),
  ('ur.jalandhry', 6, 3, 792, 'اور آسمانوں اور زمین میں وہی (ایک) خدا ہے تمہاری پوشیدہ اور ظاہر سب باتیں جانتا ہے اور تم جو عمل کرتے ہو سب سے واقف ہے', NULL, NULL, '1a9d76618a672f834b0bad77f3631078622a939d5d39543392588ff0d32afd98'),
  ('ur.jalandhry', 6, 4, 793, 'اور خدا کی نشانیوں میں سے کوئی نشانی ان لوگوں کے پاس نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں', NULL, NULL, '2637dc5db2d33681491a3e48d9f6c8a8b13c367212526dfd337db7fa8c09f1c7'),
  ('ur.jalandhry', 6, 5, 794, 'جب ان کے پاس حق آیا تو اس کو بھی جھٹلا دیا سو ان کو ان چیزوں کا جن سے یہ استہزا کرتے ہیں عنقریب انجام معلوم ہو جائے گا', NULL, NULL, '74ed91cc1d93b3687663bef6b60f00828bb72b3ca86ec8514f96198215936106'),
  ('ur.jalandhry', 6, 6, 795, 'کیا انہوں نے نہیں دیکھا کہ ہم نے ان سے پہلے کتنی امتوں کو ہلاک کر دیا جن کے پاؤں ملک میں ایسے جما دیئے تھے کہ تمہارے پاؤں بھی ایسے نہیں جمائے اور ان پر آسمان سے لگاتار مینہ برسایا اور نہریں بنا دیں جو ان کے (مکانوں کے) نیچے بہہ رہی تھیں پھر ان کو ان کے گناہوں کے سبب ہلاک کر دیا اور ان کے بعد اور امتیں پیدا کر دیں', NULL, NULL, '5b1ab8e9185bceb6924c25be61cf7c64832207a3e4c2562ee63a64ea78ef323c'),
  ('ur.jalandhry', 6, 7, 796, 'اور اگر ہم تم پر کاغذوں پر لکھی ہوئی کتاب نازل کرتے اور یہ اسے اپنے ہاتھوں سے بھی ٹٹول لیتے تو جو کافر ہیں وہ یہی کہہ دیتے کہ یہ تو (صاف اور) صریح جادو ہے', NULL, NULL, 'a4170d10a402fcba6694c59ef6a89ee310fd1c067fc5b3d517968fbee8aee866'),
  ('ur.jalandhry', 6, 8, 797, 'اور کہتے ہیں کہ ان (پیغمبر) پر فرشتہ کیوں نازل نہ ہوا (جو ان کی تصدیق کرتا) اگر ہم فرشتہ نازل کرتے تو کام ہی فیصل ہو جاتا پھر انھیں (مطلق) مہلت نہ دی جاتی', NULL, NULL, '6229fb04fd57074716b6dac89a476c48ee891f05af1fdaa827062907d592e8b3'),
  ('ur.jalandhry', 6, 9, 798, 'نیز اگر ہم کسی فرشتہ کو بھیجتے تو اسے مرد کی صورت میں بھیجتے اور جو شبہ (اب) کرتے ہیں اسی شبے میں پھر انہیں ڈال دیتے', NULL, NULL, 'febc12990103a4d78075d3a5b19701b295f8945bfd3de5ce32297e1b4ef38e6b'),
  ('ur.jalandhry', 6, 10, 799, 'اور تم سے پہلے بھی پیغمبروں کے ساتھ تمسخر ہوتے رہے ہیں سو جو لوگ ان میں سے تمسخر کیا کرتے تھے ان کو تمسخر کی سزا نے آگھیرا', NULL, NULL, 'f97a24173da062379fc61489784a6b04d86a54ea6317ac66b6f2eebf8423c85d'),
  ('ur.jalandhry', 6, 11, 800, 'کہو کہ (اے منکرین رسالت) ملک میں چلو پھرو پھر دیکھو کہ جھٹلانے والوں کا کیا انجام ہوا', NULL, NULL, 'b3e8217bed048fb4faaacfef092127a618e5248a9caceb5af2c7f53271b1e1d2')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 6, 12, 801, '(ان سے) پوچھو کہ آسمان اور زمین میں جو کچھ ہے کس کا ہے کہہ دو خدا کا اس نے اپنی ذات (پاک) پر رحمت کو لازم کر لیا ہے وہ تم سب کو قیامت کے دن جس میں کچھ بھی شک نہیں ضرور جمع کرے گا جن لوگوں نے اپنے تیئیں نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے', NULL, NULL, '1bb72eae92428c324c6ec8fe5ee3ae3f20b449593ec8dd7118ebc760f25bb98f'),
  ('ur.jalandhry', 6, 13, 802, 'اور جو مخلوق رات اور دن میں بستی ہے سب اسی کی ہے اور وہ سنتا جانتا ہے', NULL, NULL, '6e0081d2485750aa253edcf85bc443a08627b91636f8c1c17e24548b918b6c7b'),
  ('ur.jalandhry', 6, 14, 803, 'کہو کیا میں خدا کو چھوڑ کر کسی اور کو مددگار بناؤں کہ (وہی تو) آسمانوں اور زمین کا پیدا کرنے والا ہے اور وہی (سب کو) کھانا دیتا ہے اور خود کسی سے کھانا نہیں لیتا (یہ بھی) کہہ دو کہ مجھے یہ حکم ہوا ہے کہ میں سب سے پہلے اسلام لانے والا ہوں اور یہ کہ تم (اے پیغمبر!) مشرکوں میں نہ ہونا', NULL, NULL, '0b28873bacdd0ec12cb2f70a99f43878d62c69e55d7f8378a3905cd4d67c058a'),
  ('ur.jalandhry', 6, 15, 804, '(یہ بھی) کہہ دو کہ اگر میں اپنے پروردگار کی نافرمانی کروں تو مجھے بڑے دن کے عذاب کا خوف ہے', NULL, NULL, 'cc9456e828a04a1babea9898a12d29acce4858a9d6c213a9db9f6c0e1f1a328e'),
  ('ur.jalandhry', 6, 16, 805, 'جس شخص سے اس روز عذاب ٹال دیا گیا اس پر خدا نے (بڑی) مہربانی فرمائی اور یہ کھلی کامیابی ہے', NULL, NULL, '4f9e9f07e23428463e890df4f8b3d3c8899459f1930fd25f2fe9702e1ec58c61'),
  ('ur.jalandhry', 6, 17, 806, 'اور اگر خدا تم کو کوئی سختی پہنچائے تو اس کے سوا اس کو کوئی دور کرنے والا نہیں اور اگر نعمت (وراحت) عطا کرے تو (کوئی اس کو روکنے والا نہیں) وہ ہر چیز پر قادر ہے', NULL, NULL, 'cd53d259e014ae59ba674a641c380130169599e8d58a7bdc05cb581e29600935'),
  ('ur.jalandhry', 6, 18, 807, 'اور وہ اپنے بندوں پر غالب ہے اور وہ دانا اور خبردار ہے', NULL, NULL, '138d237262218b9668cec00844979bf7354f7019d02cd9422df772a43f9ec3c6'),
  ('ur.jalandhry', 6, 19, 808, 'ان سے پوچھو کہ سب سے بڑھ کر (قرین انصاف) کس کی شہادت ہے کہہ دو کہ خدا ہی مجھ میں اور تم میں گواہ ہے اور یہ قرآن مجھ پر اس لیے اتارا گیا ہے کہ اس کے ذریعے سے تم کو اور جس شخص تک وہ پہنچ سکے آگاہ کردوں کیا تم لوگ اس بات کی شہادت دیتے ہو کہ خدا کے ساتھ اور بھی معبود ہیں (اے محمدﷺ!) کہہ دو کہ میں تو (ایسی) شہادت نہیں دیتا کہہ دو کہ صرف وہی ایک معبود ہے اور جن کو تم لوگ شریک بناتے ہو میں ان سے بیزار ہوں', NULL, NULL, 'f077c84fe18cc482e96349b5702d194fc74516af9c8ba86c2e1cc6aa3e25eb56'),
  ('ur.jalandhry', 6, 20, 809, 'جن لوگوں کو ہم نے کتاب دی ہے وہ ان (ہمارے پیغمبرﷺ) کو اس طرح پہچانتے ہیں جس طرح اپنے بیٹوں کو پہچانا کرتے ہیں جنہوں نے اپنے تئیں نقصان میں ڈال رکھا ہے وہ ایمان نہیں لاتے', NULL, NULL, 'f25da87d8190ee7d6473315969b8354c9c03df47f1b6ccec6b8a55f2aafa8e11'),
  ('ur.jalandhry', 6, 21, 810, 'اور اس شخص سے زیادہ کون ظالم ہے جس نے خدا پر جھوٹ افتراء کیا یا اس کی آیتوں کو جھٹلایا۔ کچھ شک نہیں کہ ظالم لوگ نجات نہیں پائیں گے', NULL, NULL, '20ccf9d27da2b29abaa0e7e6030b5e0b322677ab4bfa862034a83f4b1c418337'),
  ('ur.jalandhry', 6, 22, 811, 'اور جس دن ہم سب لوگوں کو جمع کریں گے پھر مشرکوں سے پوچھیں گے کہ (آج) وہ تمہارے شریک کہاں ہیں جن کو تمہیں دعویٰ تھا', NULL, NULL, '8e7d21ef643135711cbd0cb7da9b7860a397b83f54d191f63b078401e6215d51'),
  ('ur.jalandhry', 6, 23, 812, 'تو ان سے کچھ عذر نہ بن پڑے گا (اور) بجز اس کے (کچھ چارہ نہ ہوگا) کہ کہیں خدا کی قسم جو ہمارا پروردگار ہے ہم شریک نہیں بناتے تھے', NULL, NULL, 'bbf59959afee80501893171ed8f99ac9fc92a209ceddc040ddb71a101d0362bb'),
  ('ur.jalandhry', 6, 24, 813, 'دیکھو انہوں نے اپنے اوپر کیسا جھوٹ بولا اور جو کچھ یہ افتراء کیا کرتے تھے سب ان سے جاتا رہا', NULL, NULL, 'e79bf0378332dcb389b31510bb03a523b754af6826ef804e83be94917d47bea8'),
  ('ur.jalandhry', 6, 25, 814, 'اور ان میں بعض ایسے ہیں کہ تمہاری (باتوں کی) طرف کان رکھتے ہیں۔ اور ہم نے ان کے دلوں پر تو پردے ڈال دیئے ہیں کہ ان کو سمجھ نہ سکیں اور کانوں میں ثقل پیدا کردیا ہے (کہ سن نہ سکیں) اور اگر یہ تمام نشانیاں بھی دیکھ لیں تب بھی ان پر ایمان نہ لائیں۔ یہاں تک کہ جب تمہارے پاس تم سے بحث کرنے کو آتے ہیں تو جو کافر ہیں کہتے ہیں یہ (قرآن) اور کچھ بھی نہیں صرف پہلے لوگوں کی کہانیاں ہیں', NULL, NULL, 'b78d18a4227ec87c6c5240fcd41f1038e1cc4b18eac69277f2c5749d5c0da804'),
  ('ur.jalandhry', 6, 26, 815, 'وہ اس سے (اوروں کو بھی) روکتے ہیں اور خود بھی پرے رہتے ہیں مگر (ان باتوں سے) اپنے آپ ہی کو ہلاک کرتے ہیں اور (اس سے) بےخبر ہیں', NULL, NULL, '89b0eee72bc4e8869c2a66a3a7725e246e231ed9f7d40d06e702666b7d204859'),
  ('ur.jalandhry', 6, 27, 816, 'کاش تم (ان کو اس وقت) دیکھو جب یہ دوزخ کے کنارے کھڑے کئے جائیں گے اور کہیں گے کہ اے کاش ہم پھر (دنیا میں) لوٹا دیئے جائیں تاکہ اپنے پروردگار کی آیتوں کی تکذیب نہ کریں اور مومن ہوجائیں', NULL, NULL, '94ce1a26915f1ed25c5343c1f6459f4766348d1618f350ed39838ddabaaf5752'),
  ('ur.jalandhry', 6, 28, 817, 'ہاں یہ جو کچھ پہلے چھپایا کرتے تھے (آج) ان پر ظاہر ہوگیا ہے اور اگر یہ (دنیا میں) لوٹائے بھی جائیں تو جن (کاموں) سے ان کو منع کیا گیا تھا وہی پھر کرنے لگیں۔کچھ شک نہیں کہ یہ جھوٹے ہیں', NULL, NULL, '2c4a0d24082c9f868bd0339cefb3169f058559ea0207fc060a6dec373c0943c2'),
  ('ur.jalandhry', 6, 29, 818, 'اور کہتے ہیں کہ ہماری جو دنیا کی زندگی ہے بس یہی (زندگی) ہے اور ہم (مرنے کے بعد) پھر زندہ نہیں کئے جائیں گے', NULL, NULL, 'da85f5a8db56a366c3fb91689d5e53f92905e22403543536620c7630197f21dc'),
  ('ur.jalandhry', 6, 30, 819, 'اور کاش تم (ان کو اس وقت) دیکھو جب یہ اپنے پروردگار کےسامنے کھڑے کئے جائیں گے اور وہ فرمائےگا کیا یہ (دوبارہ زندہ ہونا) برحق نہیں تو کہیں گے کیوں نہیں پروردگار کی قسم (بالکل برحق ہے) خدا فرمائے گا اب کفر کے بدلے (جو دنیا میں کرتے تھے) عذاب (کے مزے) چکھو', NULL, NULL, '744705d7039974cfa1b0c5c51fcb687403221ed2472e0332ccf007c32a9cc915'),
  ('ur.jalandhry', 6, 31, 820, 'جن لوگوں نے خدا کے روبرو حاضر ہونے کو جھوٹ سمجھا وہ گھاٹے میں آگئے۔ یہاں تک کہ جب ان پر قیامت ناگہاں آموجود ہوگی تو بول اٹھیں گے کہ (ہائے) اس تقصیر پر افسوس ہے جو ہم نے قیامت کے بارے میں کی۔ اور وہ اپنے (اعمال کے) بوجھ اپنی پیٹھوں پر اٹھائے ہوئے ہوں گے۔ دیکھو جو بوجھ یہ اٹھا رہے ہیں بہت برا ہے', NULL, NULL, 'dfc1f906c1b6815586b847c209f913f0a7b809862304595d1a9f52e09f8f811f'),
  ('ur.jalandhry', 6, 32, 821, 'اور دنیا کی زندگی تو ایک کھیل اور مشغولہ ہے۔ اور بہت اچھا گھر تو آخرت کا گھر ہے (یعنی) ان کے لئے جو (خدا سے) ڈرتے ہیں۔ کیا تم سمجھتے نہیں', NULL, NULL, 'b0460dbbb8517a7a1b22f411d8976dc13955e85f61ffb020057e454b43435c94'),
  ('ur.jalandhry', 6, 33, 822, 'ہم کو معلوم ہے کہ ان (کافروں) کی باتیں تمہیں رنج پہنچاتی ہیں (مگر) یہ تمہاری تکذیب نہیں کرتے بلکہ ظالم خدا کی آیتوں سے انکار کرتے ہیں', NULL, NULL, '9a8860cc1ff8353023a12d9752f5d2f8b921e214ddc84c8e7f38d23ac1694916'),
  ('ur.jalandhry', 6, 34, 823, 'اور تم سے پہلے کبھی پیغمبر جھٹلائے جاتے رہے تو وہ تکذیب اور ایذا پر صبر کرتے رہے یہاں تک کہ ان کے پاس ہماری مدد پہنچتی رہی اور خدا کی باتوں کو کوئی بھی بدلنے والا نہیں۔ اور تم کو پیغمبروں (کے احوال) کی خبریں پہنچ چکی ہیں (تو تم بھی صبر سے کام لو)', NULL, NULL, '1b71ac88897e838018822561bb085ad10f2864ae6c138d40d8da9c296242a703'),
  ('ur.jalandhry', 6, 35, 824, 'اور اگر ان کی روگردانی تم پر شاق گزرتی ہے تو اگر طاقت ہو تو زمین میں کوئی سرنگ ڈھونڈ نکالو یا آسمان میں سیڑھی (تلاش کرو) پھر ان کے پاس کوئی معجزہ لاؤ۔ اور اگر خدا چاہتا تو سب کو ہدایت پر جمع کردیتا پس تم ہرگز نادانوں میں نہ ہونا', NULL, NULL, 'adb8de96767c9f2702703a4de12920169dcedc9046fefbaa60e689071b9e42db'),
  ('ur.jalandhry', 6, 36, 825, 'بات یہ ہے کہ (حق کو) قبول وہی کرتے ہیں جو سنتے بھی ہیں اور مردوں کو تو خدا (قیامت ہی کو) اٹھائے گا۔ پھر اسی کی طرف لوٹ کر جائیں گے', NULL, NULL, 'e28213ef96237482636c69f580616fd6e424e6e4b4f6d50d1297ae40608952a7'),
  ('ur.jalandhry', 6, 37, 826, 'اور کہتے ہیں کہ ان پر ان کے پروردگارکے پاس کوئی نشانی کیوں نازل نہیں ہوئی۔ کہہ دو کہ خدا نشانی اتارنے پر قادر ہے لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '632bf3e01c474b9d66fce8feb331e61044f91bc8d5341c9025e6f2e32313d192'),
  ('ur.jalandhry', 6, 38, 827, 'اور زمین میں جو چلنے پھرنے والا (حیوان) یا دو پروں سے اڑنے والا جانور ہے ان کی بھی تم لوگوں کی طرح جماعتیں ہیں۔ ہم نے کتاب (یعنی لوح محفوظ) میں کسی چیز (کے لکھنے) میں کوتاہی نہیں کی پھر سب اپنے پروردگار کی طرف جمع کئے جائیں گے', NULL, NULL, 'fd3c0df862d9bf7cb55a370442eee52495137b76aa1dfa15adae991778eac9e0'),
  ('ur.jalandhry', 6, 39, 828, 'اور جن لوگوں نے ہماری آیتوں کو جھٹلایا وہ بہرے اور گونگے ہیں (اس کے علاوہ) اندھیرے میں (پڑے ہوئے) جس کو خدا چاہے گمراہ کردے اور جسے چاہے سیدھے رستے پر چلا دے', NULL, NULL, '9ad60ba1afe445895fe62d61ad2a7a858c95d0d7066f5f63d89e93d9e8cf4475'),
  ('ur.jalandhry', 6, 40, 829, 'کہو (کافرو) بھلا دیکھو تو اگر تم پر خدا کا عذاب آجائےیا قیامت آموجود ہو تو کیا تم (ایسی حالت میں) خدا کے سوا کسی اور کو پکارو گے؟ اگر سچے ہو (تو بتاؤ)', NULL, NULL, '033d1748a01da735fb2b6e4858f197266c4ae159c45f182e50ab2cc8c48c1308'),
  ('ur.jalandhry', 6, 41, 830, 'بلکہ (مصیبت کے وقت تم) اسی کو پکارتے ہو تو جس دکھ کے لئے اسے پکارتے ہو۔ وہ اگر چاہتا ہے تو اس کو دور کردیتا ہے اور جن کو تم شریک بناتے ہو (اس وقت) انہیں بھول جاتے ہو', NULL, NULL, 'c0642c53de38aa52d57436a8febb450e15869e4996946c888cd222d42cfd6dd9'),
  ('ur.jalandhry', 6, 42, 831, 'اور ہم نے تم سے پہلے بہت سی امتوں کی طرف پیغمبر بھیجے۔ پھر (ان کی نافرمانیوں کے سبب) ہم انہیں سختیوں اور تکلیفوں میں پکڑتے رہے تاکہ عاجزی کریں', NULL, NULL, '8640d068974502eb069be3477b6b359b3b5dcfa4b504727a6c02dd160e9646a2'),
  ('ur.jalandhry', 6, 43, 832, 'تو جب ان پر ہمارا عذاب آتا رہا کیوں نہیں عاجزی کرتے رہے۔ مگر ان کے تو دل ہی سخت ہوگئے تھے۔ اور جو وہ کام کرتے تھے شیطان ان کو (ان کی نظروں میں) آراستہ کر دکھاتا تھا', NULL, NULL, '31e4970acf67546e335b3e62be8deafa79f576e88d44bafe0fc4b217da37b500'),
  ('ur.jalandhry', 6, 44, 833, 'پھر جب انہوں نے اس نصیحت کو جو ان کو کے گئی تھی فراموش کردیا تو ہم نے ان پر ہر چیز کے دروازے کھول دیئے۔ یہاں تک کہ جب ان چیزوں سے جو ان کو دی گئی تھیں خوب خوش ہوگئے تو ہم نے ان کو ناگہاں پکڑ لیا اور وہ اس وقت مایوس ہو کر رہ گئے', NULL, NULL, '0af5674331ac285da8fc94255ac102d3b6da94df6ecdfda6ff2e79d804bf0056'),
  ('ur.jalandhry', 6, 45, 834, 'غرض ظالم لوگوں کی جڑ کاٹ دی گئی۔ اور سب تعریف خدائے رب العالمین ہی کو (سزاوار ہے)', NULL, NULL, '536db6e2fef0256bfcc370c23355456c3a88c1ebe56b101671cbacabd8ed7c1f'),
  ('ur.jalandhry', 6, 46, 835, '(ان کافروں سے) کہو کہ بھلا دیکھو تو اگر خدا تمہارے کان اور آنکھیں چھین لے اور تمہارے دلوں پر مہر لگادے تو خداکے سوا کون سا معبود ہے جو تمہیں یہ نعمتیں پھر بخشے؟ دیکھو ہم کس کس طرح اپنی آیتیں بیان کرتے ہیں۔ پھر بھی یہ لوگ ردگردانی کرتے ہیں', NULL, NULL, '7d9888d91c72fa397e5987806ba458107e8dec6a3767c1d911815974e4143246'),
  ('ur.jalandhry', 6, 47, 836, 'کہو کہ بھلا بتاؤ تو اگر تم پر خدا کا عذاب بےخبری میں یا خبر آنے کے بعد آئے تو کیا ظالم لوگوں کے سوا کوئی اور بھی ہلاک ہوگا؟', NULL, NULL, '80cfdea2db86c06ee2921af52a1d23d627836d119e8fa0650312e579aa48abcd'),
  ('ur.jalandhry', 6, 48, 837, 'اور ہم جو پیغمبروں کو بھیجتے رہے ہیں تو خوشخبری سنانے اور ڈرانے کو پھر جو شخص ایمان لائے اور نیکوکار ہوجائے تو ایسے لوگوں کو نہ کچھ خوف ہوگا اور نہ وہ اندوہناک ہوں گے', NULL, NULL, 'b9895095ec5390406219cf87dffee861fc96c1ce5e0182cfc3128e0d09953a8d'),
  ('ur.jalandhry', 6, 49, 838, 'اور جنہوں نے ہماری آیتوں کو جھٹلایا ان کی نافرمانیوں کے سبب انہیں عذاب ہوگا', NULL, NULL, '9e9219dcfbc2c8fdb3cd783441d74eb54db2b543e12ed235faa9033fee69fefd'),
  ('ur.jalandhry', 6, 50, 839, 'کہہ دو کہ میں تم سے یہ نہیں کہتا کہ میرے پاس الله تعالیٰ کے خزانے ہیں اور نہ (یہ کہ) میں غیب جانتا ہوں اور نہ تم سے یہ کہتا کہ میں فرشتہ ہوں۔ میں تو صرف اس حکم پر چلتا ہوں جو مجھے (خدا کی طرف سے) آتا ہے۔ کہہ دو کہ بھلا اندھا اور آنکھ والے برابر ہوتے ہیں؟ تو پھر تم غور کیوں نہیں کرتے', NULL, NULL, '42107dfda0f062e991edcb01b9935923a2f2180f1b532eca8a1acc9cc5b2e7d0'),
  ('ur.jalandhry', 6, 51, 840, 'اور جو لوگ جو خوف رکھتے ہیں کہ اپنے پروردگار کے روبرو حاضر کئے جائیں گے (اور جانتے ہیں کہ) اس کے سوا نہ تو ان کا کوئی دوست ہوگا اور نہ سفارش کرنے والا، ان کو اس (قرآن) کے ذریعے سے نصیحت کر دو تاکہ پرہیزگار بنیں', NULL, NULL, '136a57f3ab662abdf73163d004d7610625d0e2bde6b69579c35103181592560c'),
  ('ur.jalandhry', 6, 52, 841, 'اور جو لوگ صبح وشام اپنی پروردگار سے دعا کرتے ہیں (اور) اس کی ذات کے طالب ہیں ان کو (اپنے پاس سے) مت نکالو۔ ان کے حساب (اعمال) کی جوابدہی تم پر کچھ نہیں اور تمہارے حساب کی جوابدہی ان پر کچھ نہیں (پس ایسا نہ کرنا) اگر ان کو نکالوگے تو ظالموں میں ہوجاؤ گے', NULL, NULL, '5d75f980c815afa7d25f8230f0312f4c34ab6636e5744d71f6625433bbf75983'),
  ('ur.jalandhry', 6, 53, 842, 'اور اسی طرح ہم نے بعض لوگوں کی بعض سے آزمائش کی ہے کہ (جو دولتمند ہیں وہ غریبوں کی نسبت) کہتے ہیں کیا یہی لوگ ہیں جن پر خدا نے ہم میں سے فضل کیا ہے (خدا نے فرمایا) بھلا خدا شکر کرنے والوں سے واقف نہیں؟', NULL, NULL, '387aba16cf9b658a5a8277a34c6218f61162057cb175e4a92a165d87fcfeb0fb'),
  ('ur.jalandhry', 6, 54, 843, 'اور جب تمہارے پاس ایسے لوگ آیا کریں جو ہماری آیتوں پر ایمان لاتے ہیں تو (ان سے) سلام علیکم کہا کرو خدا نے اپنی ذات (پاک) پر رحمت کو لازم کرلیا ہے کہ جو کوئی تم میں نادانی سے کوئی بری حرکت کر بیٹھے پھر اس کے بعد توبہ کرلے اور نیکوکار ہوجائے تو وہ بخشنے والا مہربان ہے', NULL, NULL, '0b0af527f88774fa3c12c77bcd700f550d5e97d3accf9052381212bd3174abaa'),
  ('ur.jalandhry', 6, 55, 844, 'اور اس طرح ہم اپنی آیتیں کھول کھول کر بیان کرتے ہیں (تاکہ تم لوگ ان پر عمل کرو) اور اس لئے کہ گنہگاروں کا رستہ ظاہر ہوجائے', NULL, NULL, '2169d229dc73fafa1bc0c88a1df034e155cac8ea9db7d576446d2c590148b178'),
  ('ur.jalandhry', 6, 56, 845, '(اے پیغمبر! کفار سے) کہہ دو کہ جن کو تم خدا کے سوا پکارتے ہو مجھے ان کی عبادت سے منع کیا گیا ہے۔ (یہ بھی) کہہ دو کہ میں تمہاری خواہشوں کی پیروی نہیں کروں گا ایسا کروں تو گمراہ ہوجاؤں اور ہدایت یافتہ لوگوں میں نہ رہوں', NULL, NULL, '147f4e77b5a7cbde591c6a2d496c89379a41016a6a9787735d775d847541fad3'),
  ('ur.jalandhry', 6, 57, 846, 'کہہ دو کہ میں تو اپنے پروردگار کی دلیل روشن پر ہوں اور تم اس کی تکذیب کرتے ہو۔ جس چیز (یعنی عذاب) کے لئے تم جلدی کر رہے ہو وہ میرے پاس نہیں ہے (ایسا) حکم الله ہی کے اختیار میں ہے وہ سچی بات بیان فرماتا ہے اور وہ سب سے بہتر فیصلہ کرنے والا ہے', NULL, NULL, 'a3502231d06aee83d669741a6d7bfa0ae1696af270f77ea25e51327baeedc7a0'),
  ('ur.jalandhry', 6, 58, 847, 'کہہ دو کہ جس چیز کے لئے تم جلدی کر رہے ہو اگر وہ میرے اختیار میں ہوتی تو مجھ میں اور تم میں فیصلہ ہوچکا ہوتا۔ اور خدا ظالموں سے خوب واقف ہے', NULL, NULL, '696baa88aa97549a4f0a3522e44acd19da0cef6e4ac48af2e180fbf3f07f3524'),
  ('ur.jalandhry', 6, 59, 848, 'اور اسی کے پاس غیب کی کنجیاں ہیں جن کو اس کے سوا کوئی نہیں جانتا۔ اور اسے جنگلوں اور دریاؤں کی سب چیزوں کا علم ہے۔ اور کوئی پتہ نہیں جھڑتا مگر وہ اس کو جانتا ہے اور زمین کے اندھیروں میں کوئی دانہ اور کوئی ہری اور سوکھی چیز نہیں ہے مگر کتاب روشن میں (لکھی ہوئی) ہے', NULL, NULL, '3d7f8a978c8872c7bba904eb6789a78e7c30cc362cf1fa0c7732c777861b69db'),
  ('ur.jalandhry', 6, 60, 849, 'اور وہی تو ہے جو رات کو (سونے کی حالت میں) تمہاری روح قبض کرلیتا ہے اور جو کچھ تم دن میں کرتے ہو اس سے خبر رکھتا ہے پھر تمہیں دن کو اٹھا دیتا ہے تاکہ (یہی سلسلہ جاری رکھ کر زندگی کی) معین مدت پوری کردی جائے پھر تم (سب) کو اسی کی طرف لوٹ کر جانا ہے (اس روز) وہ تم کو تمہارے عمل جو تم کرتے ہو (ایک ایک کرکے) بتائے گا', NULL, NULL, 'a6455755c8161e38173b7317216c1939c4e152db8c0b8cee04f2962fd83df5c8'),
  ('ur.jalandhry', 6, 61, 850, 'اور وہ اپنے بندوں پر غالب ہے۔ اور تم پر نگہبان مقرر کئے رکھتا ہے۔ یہاں تک کہ جب تم میں سے کسی کی موت آتی ہے تو ہمارے فرشتے اس کی روح قبض کرلیتے ہیں اور وہ کسی طرح کی کوتاہی نہیں کرتے', NULL, NULL, '4e33423becedd20cec7e7eed788e3ce5dcb6c3776781ca1c0ff4df68948c850d'),
  ('ur.jalandhry', 6, 62, 851, 'پھر (قیامت کے دن تمام) لوگ اپنے مالک برحق خدا تعالیٰ کے پاس واپس بلائے جائیں گے۔ سن لو کہ حکم اسی کا ہے اور وہ نہایت جلد حساب لینے والا ہے', NULL, NULL, '7ea66bf73f99de1c6b1abf1fd2b7e14de3daa7bc5f58acb0fbd2bb0c11acc09b'),
  ('ur.jalandhry', 6, 63, 852, 'کہو بھلا تم کو جنگلوں اور دریاؤں کے اندھیروں سے کون مخلصی دیتا ہے (جب) کہ تم اسے عاجزی اور نیاز پنہانی سے پکارتے ہو (اور کہتے ہو) اگر خدا ہم کو اس (تنگی) سے نجات بخشے تو ہم اس کے بہت شکر گزار ہوں', NULL, NULL, 'bdab1189b5b1ffde77ce952a1074fe3f66768cc4613dd8c717dd0b5b46ac1168'),
  ('ur.jalandhry', 6, 64, 853, 'کہو کہ خدا ہی تم کو اس (تنگی) سے اور ہر سختی سے نجات بخشتا ہے۔ پھر (تم) اس کے ساتھ شرک کرتے ہو', NULL, NULL, '9b1bbba062cae2a5cff5483aaedd978f19e90d31f650c3cb2733ef32c8e628a8'),
  ('ur.jalandhry', 6, 65, 854, 'کہہ دو کہ وہ (اس پر بھی) قدرت رکھتا ہے کہ تم پر اوپر کی طرف سے یا تمہارے پاؤں کے نیچے سے عذاب بھیجے یا تمہیں فرقہ فرقہ کردے اور ایک کو دوسرے (سے لڑا کر آپس) کی لڑائی کا مزہ چکھادے۔ دیکھو ہم اپنی آیتوں کو کس کس طرح بیان کرتے ہیں تاکہ یہ لوگ سمجھیں', NULL, NULL, '3cdea0ad0d18fff2ad8a22ff42ce9437c6fe5bd40b2f5f6acfecd19055c4b777'),
  ('ur.jalandhry', 6, 66, 855, 'اور اس (قرآن) کو تمہاری قوم نے جھٹلایا حالانکہ وہ سراسر حق ہے۔ کہہ دو کہ میں تمہارا داروغہ نہیں ہوں', NULL, NULL, '5a0997f6da4c4b8afad560ac0436b08bf1ceb4e39fc10da4d8bb8664f4b2980c'),
  ('ur.jalandhry', 6, 67, 856, 'ہر خبر کے لئے ایک وقت مقرر ہے اور تم کو عنقریب معلوم ہوجائے گا', NULL, NULL, '6ffcc14ac6c1e7e6f02ef455f431fff21785e72840e8db2054eacd063c7e40c7'),
  ('ur.jalandhry', 6, 68, 857, 'اور جب تم ایسے لوگوں کو دیکھو جو ہماری آیتوں کے بارے میں بیہودہ بکواس کر رہے ہوں تو ان سے الگ ہوجاؤ یہاں تک کہ اور باتوں میں مصروف ہوجائیں۔ اور اگر (یہ بات) شیطان تمہیں بھلا دے تو یاد آنے پر ظالم لوگوں کے ساتھ نہ بیٹھو', NULL, NULL, '012b6b10d9aa9dbefe060edcadddc61d113ea13a508a6b93d6a321fe024f50b6'),
  ('ur.jalandhry', 6, 69, 858, 'اور پرہیزگاروں پر ان لوگوں کے حساب کی کچھ بھی جواب دہی نہیں ہاں نصیحت تاکہ وہ بھی پرہیزگار ہوں', NULL, NULL, '3174cd26891ef07d65dca4075b18e04df8ef2de753bf35081b024524814ac2a1'),
  ('ur.jalandhry', 6, 70, 859, 'اور جن لوگوں نے اپنےدین کو کھیل اور تماشا بنا رکھا ہے اور دنیا کی زندگی نے ان کو دھوکے میں ڈال رکھا ہے ان سے کچھ کام نہ رکھو ہاں اس (قرآن) کے ذریعے سے نصیحت کرتے رہو تاکہ (قیامت کے دن) کوئی اپنے اعمال کی سزا میں ہلاکت میں نہ ڈالا جائے (اس روز) خدا کےسوا نہ تو کوئی اس کا دوست ہوگا اور نہ سفارش کرنے والا۔ اور اگر وہ ہر چیز (جو روئے زمین پر ہے بطور) معاوضہ دینا چاہے تو وہ اس سے قبول نہ ہو یہی لوگ ہیں کہ اپنے اعمال کے وبال میں ہلاکت میں ڈالے گئے ان کے لئے پینے کو کھولتا ہوا پانی اور دکھ دینے والا عذاب ہے اس لئے کہ کفر کرتے تھے', NULL, NULL, '3cf60ea2ec9e5d00f41ea6024f7b81c0919a10579616394c296aa06e08164264'),
  ('ur.jalandhry', 6, 71, 860, 'کہو۔ کیا ہم خدا کے سوا ایسی چیز کو پکاریں جو نہ ہمارا بھلا کرسکے نہ برا۔ اور جب ہم کو خدا نے سیدھا رستہ دکھا دیا تو (کیا) ہم الٹے پاؤں پھر جائیں؟ (پھر ہماری ایسی مثال ہو) جیسے کسی کو جنات نے جنگل میں بھلا دیا ہو (اور وہ) حیران (ہو رہا ہو) اور اس کے کچھ رفیق ہوں جو اس کو رستے کی طرف بلائیں کہ ہمارے پاس چلا آ۔ کہہ دو کہ رستہ تو وہی ہے جو خدا نے بتایا ہے۔ اور ہمیں تو یہ حکم ملا ہے کہ ہم خدائے رب العالمین کے فرمانبردار ہوں', NULL, NULL, '6ce5d060e837e3974c2a7ed78ae7aac92222736eac3977a3452c53cc7e8ac898'),
  ('ur.jalandhry', 6, 72, 861, 'اور یہ (بھی) کہ نماز پڑھتے رہو اور اس سے ڈرتے رہو۔ اور وہی تو ہے جس کے پاس تم جمع کئے جاؤ گے', NULL, NULL, '55562ff447d3f728635e2efac5c4af99c1648dc37cd9e252512e197aaa777a45'),
  ('ur.jalandhry', 6, 73, 862, 'اور وہی تو ہے جس نے آسمانوں اور زمین کو تدبیر سے پیدا کیا ہے۔ اور جس دن وہ فرمائے گا کہ ہو جا تو (حشر برپا) ہوجائے گا ۔ اس کا ارشاد برحق ہے۔ اور جس دن صور پھونکا جائے گا (اس دن) اسی کی بادشاہت ہوگی۔ وہی پوشیدہ اور ظاہر (سب) کا جاننے والا ہے اور وہی دانا اور خبردار ہے', NULL, NULL, '832a08121d56636fb860e7c55eb2f564219bdc9857af47ba41641a4135fdfd24'),
  ('ur.jalandhry', 6, 74, 863, 'اور (وہ وقت بھی یاد کرنے کے لائق ہے) جب ابراہیم نے اپنے باپ آزر سے کہا کہ تم بتوں کو کیا معبود بناتے ہو۔ میں دیکھتا ہوں کہ تم اور تمہاری قوم صریح گمراہی میں ہو', NULL, NULL, 'd400bd32e32b006eaf942106d2f77db4632107096f222fb6da655cd9597b3ac0'),
  ('ur.jalandhry', 6, 75, 864, 'اور ہم اس طرح ابراہیم کو آسمانوں اور زمین کے عجائبات دکھانے لگے تاکہ وہ خوب یقین کرنے والوں میں ہوجائیں', NULL, NULL, 'e91f66698cc9eb7dbdbd5c6f6d0f72319ea40053fef0a6a02bf60709b7d4ff87'),
  ('ur.jalandhry', 6, 76, 865, '(یعنی) جب رات نے ان کو (پردہٴ تاریکی سے) ڈھانپ لیا (تو آسمان میں) ایک ستارا نظر پڑا۔ کہنے لگے یہ میرا پروردگار ہے۔ جب وہ غائب ہوگیا تو کہنے لگے کہ مجھے غائب ہوجانے والے پسند نہیں', NULL, NULL, 'cc159d138d827fc0138f0cc59c4436cc997c88e4b53f3852c02e0f61725d7ed7'),
  ('ur.jalandhry', 6, 77, 866, 'پھر جب چاند کو دیکھا کہ چمک رہا ہے تو کہنے لگے یہ میرا پروردگار ہے۔ لیکن جب وہ بھی چھپ گیا تو بول اٹھے کہ میرا پروردگار مجھے سیدھا رستہ نہیں دکھائے گا تو میں ان لوگوں میں ہوجاؤں گا جو بھٹک رہے ہیں', NULL, NULL, '206beea1013c29e9e8c4585c4ba950ffa7f013670be2184356196fb412e86b24'),
  ('ur.jalandhry', 6, 78, 867, 'پھر جب سورج کو دیکھا کہ جگمگا رہا ہے تو کہنے لگے میرا پروردگار یہ ہے یہ سب سے بڑا ہے۔ مگر جب وہ بھی غروب ہوگیا تو کہنے لگے لوگو! جن چیزوں کو تم (خدا کا) شریک بناتے ہو میں ان سے بیزار ہوں', NULL, NULL, 'c725f90fa42d0288a449c3c721899dc94ec24df55d806277f20e1e37cc3a632f'),
  ('ur.jalandhry', 6, 79, 868, 'میں نے سب سے یکسو ہو کر اپنے تئیں اسی ذات کی طرف متوجہ کیا جس نے آسمانوں اور زمین کو پیدا کیا ہے اور میں مشرکوں میں سے نہیں ہوں', NULL, NULL, '5f8f263bb6cf9886941770d5e99e5306b0db2c9e32ec7421fbbefa9fd12b2f8e'),
  ('ur.jalandhry', 6, 80, 869, 'اور ان کی قوم ان سے بحث کرنے لگی تو انہوں نے کہا کہ تم مجھ سے خدا کے بارےمیں (کیا) بحث کرتے ہو اس نے تو مجھے سیدھا رستہ دکھا دیا ہے۔ اور جن چیزوں کو تم اس کا شریک بناتے ہو میں ان سے نہیں ڈرتا۔ ہاں جو میرا پروردگار چاہے۔ میرا پروردگار اپنے علم سے ہر چیز پر احاطہ کئے ہوئے ہے۔ کیا تم خیال نہیں کرتے۔', NULL, NULL, '1de955baf62a7352acf528f715298272df9dbe9f66908df46ee2d3d604336fc8'),
  ('ur.jalandhry', 6, 81, 870, 'بھلا میں ان چیزوں سے جن کو تم (خدا کا) شریک بناتے ہو کیونکرڈروں جب کہ تم اس سے نہیں ڈرتے کہ خدا کے ساتھ شریک بناتے ہو جس کی اس نے کوئی سند نازل نہیں کی۔ اب دونوں فریق میں سے کون سا فریق امن (اور جمعیت خاطر) کا مستحق ہے۔ اگر سمجھ رکھتے ہو (تو بتاؤ)', NULL, NULL, 'a37fd973c07642a84b736cf2ab2842f7bb1a28dafd1fd67e6ad4f7ddece005b8'),
  ('ur.jalandhry', 6, 82, 871, 'جو لوگ ایمان لائے اور اپنے ایمان کو (شرک کے) ظلم سے مخلوط نہیں کیا ان کے امن (اور جمعیت خاطر) ہے اور وہی ہدایت پانے والے ہیں', NULL, NULL, 'c94a7cc27559e97380a0368e2db159ae5fd25fea88f7d7e78569641c81102994'),
  ('ur.jalandhry', 6, 83, 872, 'اور یہ ہماری دلیل تھی جو ہم نے ابراہیم کو ان کی قوم کے مقابلے میں عطا کی تھی۔ ہم جس کے چاہتے ہیں درجے بلند کردیتے ہیں۔ بےشک تمہارا پروردگار دانا اور خبردار ہے', NULL, NULL, '92c378cd6a80a17e917ee650c0f2ef70ba5aa8b6b196a270ddb52a2eeac87a26'),
  ('ur.jalandhry', 6, 84, 873, 'اور ہم نے ان کو اسحاق اور یعقوب بخشے۔ (اور) سب کو ہدایت دی۔ اور پہلے نوح کو بھی ہدایت دی تھی اور ان کی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسیٰ اور ہارون کو بھی۔ اور ہم نیک لوگوں کو ایسا ہی بدلا دیا کرتے ہیں', NULL, NULL, '9eda768642dd236edf58ff5e3533e1c42b1ef3caa00e22ab36e38f787db7d57f'),
  ('ur.jalandhry', 6, 85, 874, 'اور زکریا اور یحییٰ اور عیسیٰ اور الیاس کو بھی۔ یہ سب نیکوکار تھے', NULL, NULL, 'ef0ea2d6a5cf40c8cfec37eb7942cb2a6798f0bfa5b70a0cd82c2a38367cb692'),
  ('ur.jalandhry', 6, 86, 875, 'اور اسمٰعیل اور الیسع اور یونس اور لوط کو بھی۔ اور ان سب کو جہان کے لوگوں پر فضلیت بخشی تھی', NULL, NULL, '829ffab53bd0d1bae9b8cefc6c34a59486e312f2956501b41bec121e4a21c135'),
  ('ur.jalandhry', 6, 87, 876, 'اور بعض بعض کو ان کے باپ دادا اور اولاد اور بھائیوں میں سے بھی۔ اور ان کو برگزیدہ بھی کیا تھا اور سیدھا رستہ بھی دکھایا تھا', NULL, NULL, '551702487d8f1c975e081e5075cdf66d3573a4f33562bfb92f77c1be5e1e6b0b'),
  ('ur.jalandhry', 6, 88, 877, 'یہ خدا کی ہدایت ہے اس پر اپنے بندوں میں سے جسے چاہے چلائے۔ اور اگر وہ لوگ شرک کرتے تو جو عمل وہ کرتے تھے سب ضائع ہوجاتے', NULL, NULL, '1b1740c4592df0fcd4c10526b9a6d5881ce2253e8c0ae4478beea880326ca217'),
  ('ur.jalandhry', 6, 89, 878, 'یہ وہ لوگ تھے جن کو ہم نے کتاب اور حکم (شریعت) اور نبوت عطا فرمائی تھی۔ اگر یہ (کفار) ان باتوں سے انکار کریں تو ہم نے ان پر (ایمان لانے کے لئے) ایسے لوگ مقرر کردیئے ہیں کہ وہ ان سے کبھی انکار کرنے والے نہیں', NULL, NULL, 'aa02edb667477fb6296c436761a14499d758adc00c93f2cba57535d542cd09d2'),
  ('ur.jalandhry', 6, 90, 879, 'یہ وہ لوگ ہیں جن کو خدا نے ہدایت دی تھی تو تم انہیں کی ہدایت کی پیروی کرو۔ کہہ دو کہ میں تم سے اس (قرآن) کا صلہ نہیں مانگتا۔ یہ تو جہان کے لوگوں کے لئےمحض نصیحت ہے', NULL, NULL, 'cb380cef8e4663321c095bbcb15c2e2d5e4377c70b848141f3b77ad993f5eb48'),
  ('ur.jalandhry', 6, 91, 880, 'اور ان لوگوں نے خدا کی قدر جیسی جاننی چاہیئے تھی نہ جانی۔ جب انہوں نے کہا کہ خدا نے انسان پر (وحی اور کتاب وغیرہ) کچھ بھی نازل نہیں کیا۔ کہو جو کتاب موسیٰ لے کر آئے تھے اسے کس نے نازل کیا تھا جو لوگوں کے لئے نور اور ہدایت تھی اور جسے تم نے علیحدہ علیحدہ اوراق (پر نقل) کر رکھا ہے ان (کے کچھ حصے) کو تو ظاہر کرتے ہو اور اکثر کو چھپاتے ہو۔ اور تم کو وہ باتیں سکھائی گئیں جن کو نہ تم جانتے تھے اور نہ تمہارے باپ دادا۔ کہہ دو (اس کتاب کو) خدا ہی نے (نازل کیا تھا) پھر ان کو چھوڑ دیا کہ اپنی بیہودہ بکواس میں کھیلتے رہیں', NULL, NULL, '35e319c08cf9204d5d5c8d5972440c557acfe0cc205c51df1d2858b65d3ae665'),
  ('ur.jalandhry', 6, 92, 881, 'اور (ویسی ہی) یہ کتاب ہے جسے ہم نے نازل کیا ہے بابرکت جو اپنے سے پہلی (کتابوں) کی تصدیق کرتی ہے اور (جو) اس لئے (نازل کی گئی ہے) کہ تم مکے اور اس کے آس پاس کے لوگوں کو آگاہ کردو۔ اور جو لوگ آخرت پر ایمان رکھتے ہیں وہ اس کتاب پر بھی ایمان رکھتے ہیں اور وہ اپنی نمازوں کی پوری خبر رکھتے ہیں', NULL, NULL, '88c65a94ffa1bbfe3c99a2398746e43c68d000122c1eb2d4bae8bbabc4a520df'),
  ('ur.jalandhry', 6, 93, 882, 'اور اس سے بڑھ کر ظالم کون ہوگا جو خدا پر جھوٹ افتراء کرے۔ یا یہ کہے کہ مجھ پر وحی آئی ہے حالانکہ اس پر کچھ بھی وحی نہ آئی ہو اور جو یہ کہے کہ جس طرح کی کتاب خدا نے نازل کی ہے اس طرح کی میں بھی بنا لیتا ہوں۔ اور کاش تم ان ظالم (یعنی مشرک) لوگوں کو اس وقت دیکھو جب موت کی سختیوں میں (مبتلا) ہوں اور فرشتے (ان کی طرف عذاب کے لئے) ہاتھ بڑھا رہے ہوں کہ نکالو اپنی جانیں۔ آج تم کو ذلت کے عذاب کی سزا دی جائے گی اس لئے کہ تم خدا پر جھوٹ بولا کرتے تھے اور اس کی آیتوں سے سرکشی کرتے تھے', NULL, NULL, 'cc5f82d0dfd1d5bc919daf4cb36bfbd14f8e7ad0b1b07fe7213faf76e9387fc9'),
  ('ur.jalandhry', 6, 94, 883, 'اور جیسا ہم نے تم کو پہلی دفعہ پیدا کیا تھا ایسا ہی آج اکیلے اکیلے ہمارے پاس آئے اور جو (مال ومتاع) ہم نے تمہیں عطا فرمایا تھا وہ سب اپنی پیٹھ پیچھے چھوڑ آئے اور ہم تمہارے ساتھ تمہارے سفارشیوں کو بھی نہیں دیکھتے جن کی نسبت تم خیال کرتے تھے کہ وہ تمہارے (شفیع اور ہمارے) شریک ہیں۔ (آج) تمہارے آپس کے سب تعلقات منقطع ہوگئے اور جو دعوے تم کیا کرتے تھے سب جاتے رہے', NULL, NULL, 'db380959f4d60761344e17ae41ad88a12804cc5c03e941137cf783f32ad55c57'),
  ('ur.jalandhry', 6, 95, 884, 'بے شک خدا ہی دانے اور گٹھلی کو پھاڑ کر (ان سے درخت وغیرہ) اگاتا ہے وہی جاندار کو بے جان سے نکالتا ہے اور وہی بےجان کا جاندار سے نکالنے والا ہے۔ یہی تو خدا ہے۔ پھر تم کہاں بہکے پھرتے ہو', NULL, NULL, 'd27a6141d69204fd7376eb659816169c11b688e51e842de77b346e8661ec67be'),
  ('ur.jalandhry', 6, 96, 885, 'وہی (رات کے اندھیرے سے) صبح کی روشنی پھاڑ نکالتا ہے اور اسی نے رات کو (موجب) آرام (ٹھہرایا) اور سورج اور چاند کو (ذرائع) شمار بنایا ہے۔ یہ خدا کے (مقرر کئے ہوئے) اندازے ہیں جو غالب (اور) علم والا ہے', NULL, NULL, 'dfcb0c01f40a5a7f53e3873d54e87402385def84d49850a22762effe8a638d46'),
  ('ur.jalandhry', 6, 97, 886, 'اور وہی تو ہے جس نے تمہارے لئے ستارے بنائے تاکہ جنگلوں اور دریاؤں کے اندھیروں میں ان سے رستے معلوم کرو۔ عقل والوں کے لئے ہم نے اپنی آیتیں کھول کھول کر بیان کردی ہیں', NULL, NULL, 'b9fa45527d65714b38670680ad5290daccdd8ac9adc23fd9fd1788143e5947d8'),
  ('ur.jalandhry', 6, 98, 887, 'اور وہی تو ہے جس نے تم کو ایک شخص سے پیدا کیا۔ پھر (تمہارے لئے) ایک ٹھہرنے کی جگہ ہے اور ایک سپرد ہونے کی سمجھنے والوں کے لئے ہم نے (اپنی) آیتیں کھول کھول کر بیان کردی ہیں', NULL, NULL, 'b626c3f98d496de58da78c0fea8a152f2aee093388417a54a1e5c7018175c406'),
  ('ur.jalandhry', 6, 99, 888, 'اور وہی تو ہے جو آسمان سے مینھ برساتا ہے۔ پھر ہم ہی (جو مینھ برساتے ہیں) اس سے ہر طرح کی روئیدگی اگاتے ہیں۔ پھر اس میں سے سبز سبز کونپلیں نکالتے ہیں۔ اور ان کونپلوں میں سے ایک دوسرے کے ساتھ جڑے ہوئے دانے نکالتے ہیں اور کھجور کے گابھے میں سے لٹکتے ہوئے گچھے اور انگوروں کے باغ اور زیتون اور انار جو ایک دوسرے سے ملتے جلتے بھی ہیں۔ اور نہیں بھی ملتے۔ یہ چیزیں جب پھلتی ہیں تو ان کے پھلوں پر اور (جب پکتی ہیں تو) ان کے پکنے پر نظر کرو۔ ان میں ان لوگوں کے لئے جو ایمان لاتے ہیں (قدرت خدا کی بہت سی) نشانیاں ہیں', NULL, NULL, '05e93aee72b016d972f937ea2e129eaae94bfde9764760a4e7bdefe9fd3a2697'),
  ('ur.jalandhry', 6, 100, 889, 'اور ان لوگوں نے جنوں کو خدا کا شریک ٹھہرایا۔ حالانکہ ان کو اسی نے پیدا کیا اور بےسمجھے (جھوٹ بہتان) اس کے لئے بیٹے اور بیٹیاں بنا کھڑی کیں وہ ان باتوں سے جو اس کی نسبت بیان کرتے ہیں پاک ہے اور (اس کی شان ان سے) بلند ہے', NULL, NULL, '6e99ed87abc7a2a6b0653ceb6defa5787fa21be3ef6ddf8a4ad7cddbf0ca643e'),
  ('ur.jalandhry', 6, 101, 890, '(وہی) آسمانوں اور زمین کا پیدا کرنے والا (ہے) ۔ اس کے اولاد کہاں سے ہو جب کہ اس کی بیوی ہی نہیں۔ اور اس نے ہر چیز کو پیدا کیا ہے۔ اور وہ ہر چیز سے باخبر ہے', NULL, NULL, 'a16eebdcd695f7efb14b7f01e23ea96400625a42bd33568838355cd60b18497b'),
  ('ur.jalandhry', 6, 102, 891, 'یہی (اوصاف رکھنے والا) خدا تمہارا پروردگار ہے۔ اس کے سوا کوئی معبود نہیں۔ (وہی) ہر چیز کا پیداکرنے والا (ہے) تو اسی کی عبادت کرو۔ اور وہ ہر چیز کا نگراں ہے', NULL, NULL, '0172464954b8cfc2a26c50a42dd855a12345d8740f4b5d260664131424055d15'),
  ('ur.jalandhry', 6, 103, 892, '(وہ ایسا ہے کہ) نگاہیں اس کا ادراک نہیں کرسکتیں اور وہ نگاہوں کا ادراک کرسکتا ہے اور وہ بھید جاننے والا خبردار ہے', NULL, NULL, '925cc06aaefe9c9430db9f5acf763bd9f81be79510159100edcfefcb017e78c4'),
  ('ur.jalandhry', 6, 104, 893, '(اے محمدﷺ! ان سے کہہ دو کہ) تمہارے (پاس) پروردگار کی طرف سے (روشن) دلیلیں پہنچ چکی ہیں تو جس نے (ان کو آنکھ کھول کر) دیکھا اس نے اپنا بھلا کیا اور جو اندھا بنا رہا اس نے اپنے حق میں برا کیا۔ اور میں تمہارا نگہبان نہیں ہوں', NULL, NULL, '4cf56afa4a4a6f0ca647cc7282e7adb8d0cef212674d4984cd22a71bfe18c691'),
  ('ur.jalandhry', 6, 105, 894, 'اور ہم اسی طرح اپنی آیتیں پھیر پھیر کر بیان کرتے ہیں تاکہ کافر یہ نہ کہیں کہ تم (یہ باتیں اہل کتاب سے) سیکھے ہوئے ہو اور تاکہ سمجھنے والے لوگوں کے لئے تشریح کردیں', NULL, NULL, '24b7504c4871c11fdc098e189e46370ebdb9dbb2a3df525261978ec9b8d79ae3'),
  ('ur.jalandhry', 6, 106, 895, 'اور جو حکم تمہارے پروردگار کی طرف سے تمہارے پاس آتا ہے اسی کی پیروی کرو۔ اس (پروردگار) کے سوا کوئی معبود نہیں۔ اور مشرکوں سے کنارہ کرلو', NULL, NULL, '5f81ab2f2714a968da2ffe513e5a63ba6b906d8d0cfa12b1a7e3fe4424cbe178'),
  ('ur.jalandhry', 6, 107, 896, 'اور اگر خدا چاہتا تو یہ لوگ شرک نہ کرتے۔ اور (اے پیغمبر!) ہم نے تم کو ان پر نگہبان مقرر نہیں کیا۔ اور نہ تم ان کے داروغہ ہو', NULL, NULL, '5be5baf5d92325abd38c4866f7d59829ef43d29de1be13a39c5572d4e7d703fa'),
  ('ur.jalandhry', 6, 108, 897, 'اور جن لوگوں کو یہ مشرک خدا کے سوا پکارتے ہیں ان کو برا نہ کہنا کہ یہ بھی کہیں خدا کو بےادبی سے بے سمجھے برا (نہ) کہہ بیٹھیں۔ اس طرح ہم نے ہر ایک فرقے کے اعمال (ان کی نظروں میں) اچھے کر دکھائے ہیں۔ پھر ان کو اپنے پروردگار ک طرف لوٹ کر جانا ہے تب وہ ان کو بتائے گا کہ وہ کیا کیا کرتے تھے', NULL, NULL, 'a9d7871c919f1423f163078834516be8687c273929e96b938153ad11e1b6451c'),
  ('ur.jalandhry', 6, 109, 898, 'اور یہ لوگ خدا کی سخت سخت قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی نشانی آئے تو وہ اس پر ضروری ایمان لے آئیں۔ کہہ دو کہ نشانیاں تو سب خدا ہی کے پاس ہیں۔ اور (مومنو!) تمہیں کیا معلوم ہے (یہ تو ایسے بدبخت ہیں کہ ان کے پاس) نشانیاں آ بھی جائیں تب بھی ایمان نہ لائیں', NULL, NULL, '7d60444a1b58ad9f3bae6bffa748e50efcbd873a5990441350f9eafd50b2d8da'),
  ('ur.jalandhry', 6, 110, 899, 'اور ہم ان کے دلوں اور آنکھوں کو الٹ دیں گے (تو) جیسے یہ اس (قرآن) پر پہلی دفعہ ایمان نہیں لائے (ویسے پھر نہ لائیں گے) اور ان کو چھوڑ دیں گے کہ اپنی سرکشی میں بہکتے رہیں', NULL, NULL, '4ec0fd9e599b51642ee63e0720c1d9f8bcf2d1e21b5b7e5f883e8412288dce66'),
  ('ur.jalandhry', 6, 111, 900, 'اور اگر ہم ان پر فرشتے بھی اتار دیتے اور مردے بھی ان سے گفتگو کرنے لگتے اور ہم سب چیزوں کو ان کے سامنے لا موجود بھی کر دیتے تو بھی یہ ایمان لانے والے نہ تھے اِلّا ماشائالله بات یہ ہے کہ یہ اکثر نادان ہیں', NULL, NULL, 'e66bc4d3e8989044521ca4078e5b2bf45d64f664b14b6e679a2dfc876ea7f537')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 6, 112, 901, 'اور اسی طرح ہم نے شیطان (سیرت) انسانوں اور جنوں کو ہر پیغمبر کا دشمن بنا دیا تھا وہ دھوکا دینے کے لیے ایک دوسرے کے دل میں ملمع کی باتیں ڈالتے رہتے تھے اور اگر تمہارا پروردگار چاہتا تو وہ ایسا نہ کرتے تو ان کو اور جو کچھ یہ افتراء کرتے ہیں اسے چھوڑ دو', NULL, NULL, 'cf2251d050a2f3d5f1a42c9588b114864e36493e06e1ad40128e5f0fe903dcde'),
  ('ur.jalandhry', 6, 113, 902, 'اور (وہ ایسے کام) اس لیے بھی (کرتے تھے) کہ جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل ان کی باتوں پر مائل ہوں اور وہ انہیں پسند کریں اور جو کام وہ کرتے تھے وہ ہی کرنے لگیں', NULL, NULL, 'f5482dc5b5fbe1b1bdae97c3c10c0975a20ce9cf3b36b9dbf84495a703a69f5b'),
  ('ur.jalandhry', 6, 114, 903, '(کہو) کیا میں خدا کے سوا اور منصف تلاش کروں حالانکہ اس نے تمہاری طرف واضع المطالب کتاب بھیجی ہے اور جن لوگوں کو ہم نے کتاب (تورات) دی ہے وہ جانتے ہیں کہ وہ تمہارے پروردگار کی طرف سے برحق نازل ہوئی ہے تو تم ہرگز شک کرنے والوں میں نہ ہونا', NULL, NULL, 'c32880e3c710a351a67c096ad16d0b177d4cd4fabe7bb4766e5abd55d9e76f87'),
  ('ur.jalandhry', 6, 115, 904, 'اور تمہارے پروردگار کی باتیں سچائی اور انصاف میں پوری ہیں اس کی باتوں کو کوئی بدلنے والا نہیں اور وہ سنتا جانتا ہے', NULL, NULL, '6e025479c66ad9941a32ccbaad92edb7a21dcaedb0107120636d28abce94838a'),
  ('ur.jalandhry', 6, 116, 905, 'اور اکثر لوگ جو زمین پر آباد ہیں (گمراہ ہیں) اگر تم ان کا کہا مان لو گے تو وہ تمہیں خدا کا رستہ بھلا دیں گے یہ محض خیال کے پیچھے چلتے اور نرے اٹکل کے تیر چلاتے ہیں', NULL, NULL, '1119c15ee2b76dfbd19ea9a8e2bd30dd36a49f294bfacb81f73c2f33eeec5ece'),
  ('ur.jalandhry', 6, 117, 906, 'تمہارا پروردگار ان لوگوں کو خوب جانتا ہے جو اس کے رستے سے بھٹکے ہوئے ہیں اور ان سے بھی خوب واقف ہے جو رستے پر چل رہے ہیں', NULL, NULL, '9b0e32277960d42f5509f1f81664544c8f76501de9040333716dff22b4810030'),
  ('ur.jalandhry', 6, 118, 907, 'تو جس چیز پر (ذبح کے وقت) خدا کا نام لیا جائے اگر تم اس کی آیتوں پر ایمان رکھتے ہو تو اسے کھا لیا کرو', NULL, NULL, '509a937c3257c8e36616e303de83ec020a64bd531ec6325f58308d8f3136fafa'),
  ('ur.jalandhry', 6, 119, 908, 'اور سبب کیا ہے کہ جس چیز پر خدا کا نام لیا جائے تم اسے نہ کھاؤ حالانکہ جو چیزیں اس نے تمہارے لیے حرام ٹھیرا دی ہیں وہ ایک ایک کر کے بیان کر دی ہیں (بے شک ان کو نہیں کھانا چاہیے) مگر اس صورت میں کہ ان کے (کھانے کے) لیے ناچار ہو جاؤ اور بہت سے لوگ بےسمجھے بوجھے اپنے نفس کی خواہشوں سے لوگوں کو بہکا رہے ہیں کچھ شک نہیں کہ ایسے لوگوں کو جو (خدا کی مقرر کی ہوئی) حد سے باہر نکل جاتے ہیں تمہارا پروردگار خوب جانتا ہے', NULL, NULL, '7c5903b555a9620d1818912249f0216a94ca5bb17f37e9b2ee21f351160b621a'),
  ('ur.jalandhry', 6, 120, 909, 'اور ظاہری اور پوشیدہ (ہر طرح کا) گناہ ترک کر دو جو لوگ گناہ کرتے ہیں وہ عنقریب اپنے کئے کی سزا پائیں گے', NULL, NULL, '2a8291d7537b6a31e4aad1b63b02030e7148175a96edae65c4c121a3272a92ea'),
  ('ur.jalandhry', 6, 121, 910, 'اور جس چیز پر خدا کا نام نہ لیا جائے اسے مت کھاؤ کہ اس کا کھانا گناہ ہے اور شیطان (لوگ) اپنے رفیقوں کے دلوں میں یہ بات ڈالتے ہیں کہ تم سے جھگڑا کریں اور اگر تم لوگ ان کے کہے پر چلے تو بےشک تم بھی مشرک ہوئے', NULL, NULL, '9b0f4bc73822e34c1cc491ad4ddc0728561ae838c31d798225fcf2d696698e15'),
  ('ur.jalandhry', 6, 122, 911, 'بھلا جو پہلے مردہ تھا پھر ہم نے اس کو زندہ کیا اور اس کے لیے روشنی کر دی جس کے ذریعے سے وہ لوگوں میں چلتا پھرتا ہے کہیں اس شخص جیسا ہو سکتا ہے جو اندھیرے میں پڑا ہوا ہو اور اس سے نکل ہی نہ سکے اسی طرح کافر جو عمل کر رہے ہیں وہ انہیں اچھے معلوم ہوتے ہیں', NULL, NULL, '8f93ebbc0ce06fe92ead493dd71b9a64d4f48033cfe6c1afd5310d50ced3d6cc'),
  ('ur.jalandhry', 6, 123, 912, 'اور اسی طرح ہم نے ہر بستی میں بڑے بڑے مجرم پیدا کئے کہ ان میں مکاریاں کرتے رہیں اور جو مکاریاں یہ کرتے ہیں ان کا نقصان انہیں کو ہے اور (اس سے) بےخبر ہیں', NULL, NULL, '35311d20dfdd38ab97b10c5f0f821667f8371b06eb09ce50e1248de4a3154773'),
  ('ur.jalandhry', 6, 124, 913, 'اور جب ان کے پاس کوئی آیت آتی ہے تو کہتے ہیں کہ جس طرح کی رسالت خدا کے پیغمبروں کو ملی ہے جب تک اسی طرح کی رسالت ہم کو نہ ملے ہم ہرگز ایمان نہیں لائیں گے اس کو خدا ہی خوب جانتا ہے کہ (رسالت کا کون سا محل ہے اور) وہ اپنی پیغمبری کسے عنایت فرمائے جو لوگ جرم کرتے ہیں ان کو خدا کے ہاں ذلّت اور عذابِ شدید ہوگا اس لیے کہ مکّاریاں کرتے تھے', NULL, NULL, '7c02d7585187acf8d498e22fb24d0738f12b412f6f178a3a076e857939b7edaa'),
  ('ur.jalandhry', 6, 125, 914, 'تو جس شخص کو خدا چاہتا ہے کہ ہدایت بخشے اس کا سینہ اسلام کے لیے کھول دیتا ہے اور جسے چاہتا ہے کہ گمراہ کرے اس کا سینہ تنگ اور گھٹا ہوا کر دیتا ہے گویا وہ آسمان پر چڑھ رہا ہے اس طرح خدا ان لوگوں پر جو ایمان نہیں لاتے عذاب بھیجتا ہے', NULL, NULL, '0c4cb9b4786e4e7f2ffd2aaadd42503d681ba12db935af6ab98c3d6e82d06028'),
  ('ur.jalandhry', 6, 126, 915, 'اور یہی تمہارے پروردگار کا سیدھا رستہ ہے جو لوگ غور کرنے والے ہیں ان کے لیے ہم نے اپنی آیتیں کھول کھول کر بیان کر دی ہیں', NULL, NULL, '6705437e72e22b9c6fb9b889f2d77ba94c066d07d014113cde9c7135fa31feee'),
  ('ur.jalandhry', 6, 127, 916, 'ان کے لیے ان کے اعمال کے صلے میں پروردگار کے ہاں سلامتی کا گھر ہے اور وہی ان کا دوستدار ہے', NULL, NULL, '2ffc6ba33eda0fd6aff3243fa838db26bb0a61b7a289363db6503b4b83b0000f'),
  ('ur.jalandhry', 6, 128, 917, 'اور جس دن وہ سب (جنّ وانس) کو جمع کرے گا (اور فرمائے گا کہ) اے گروہ جنّات تم نے انسانوں سے بہت (فائدے) حاصل کئے تو جو انسانوں میں ان کے دوستدار ہوں گے وہ کہیں گے کہ پروردگار ہم ایک دوسرے سے فائدہ اٹھاتے رہے اور (آخر) اس وقت کو پہنچ گئے جو تو نے ہمارے لیے مقرر کیا تھا خدا فرمائے گا (اب) تمہارا ٹھکانہ دوزخ ہے ہمیشہ اس میں (جلتے) رہو گے مگر جو خدا چاہے بےشک تمہارا پروردگار دانا اور خبردار ہے', NULL, NULL, 'ef4792dd9a8407e7cef64017f86ca6eeb940ad67b48503b8822f8d0970df198c'),
  ('ur.jalandhry', 6, 129, 918, 'اور اسی طرح ہم ظالموں کو ان کے اعمال کے سبب جو وہ کرتے تھے ایک دوسرے پر مسلط کر دیتے ہیں', NULL, NULL, '5e18f121e1ec93ac7bccde6ce4bf9b4bf61838a04aa8aed69aaa542a52c46d81'),
  ('ur.jalandhry', 6, 130, 919, 'اے جنّوں اور انسانوں کی جماعت کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آتے رہے جو میری آیتیں تم کو پڑھ پڑھ کر سناتے اور اس دن کے سامنے آموجود ہونے سے ڈراتے تھے وہ کہیں گے کہ (پروردگار) ہمیں اپنے گناہوں کا اقرار ہے ان لوگوں کو دنیاکی زندگی نے دھوکے میں ڈال رکھا تھا اور (اب) خود اپنے اوپر گواہی دی کہ کفر کرتے تھے', NULL, NULL, '186f46970b3cfdaec8c945de7df9c25ef2c04fb2f992dbb308d350ab0fab4f79'),
  ('ur.jalandhry', 6, 131, 920, '(اے محمدﷺ!) یہ (جو پیغمبر آتے رہے اور کتابیں نازل ہوتی رہیں تو) اس لیے کہ تمہارا پروردگار ایسا نہیں کہ بستیوں کو ظلم سے ہلاک کر دے اور وہاں کے رہنے والوں کو (کچھ بھی) خبر نہ ہو', NULL, NULL, 'fc99d69e38e5296e14d7bf8b139174e55dc9ea61535caba05cc963413d50906d'),
  ('ur.jalandhry', 6, 132, 921, 'اور سب لوگوں کے بلحاظ اعمال درجے (مقرر) ہیں اور جو کام یہ لوگ کرتے ہیں خدا ان سے بے خبر نہیں', NULL, NULL, 'ce3f0ccd2ad6f0507305f360cd74f20493135b95ce3c846b4340be80b7ad7f00'),
  ('ur.jalandhry', 6, 133, 922, 'اور تمہارا پروردگار بےپروا (اور) صاحب رحمت ہے اگر چاہے (تو اے بندوں) تمہیں نابود کر دے اور تمہارے بعد جن لوگوں کو چاہے تمہارا جانشین بنا دے جیسا تم کو بھی دوسرے لوگوں کی نسل سے پیدا کیا ہے', NULL, NULL, 'dec7b54674b1766b4b431e11b782cefe03d1c06170b7b69d7f708ab88c8e8c6d'),
  ('ur.jalandhry', 6, 134, 923, 'کچھ شک نہیں کہ جو وعدہ تم سے کیا جاتا ہے وہ (وقوع میں) آنے والا ہے اور تم (خدا کو) مغلوب نہیں کر سکتے', NULL, NULL, '7df1cb2416847cf9479728db821b501d7752517f21bb4ca587c9a1c52a81528a'),
  ('ur.jalandhry', 6, 135, 924, 'کہہ دو کہ لوگو تم اپنی جگہ عمل کئے جاؤ میں (اپنی جگہ) عمل کئے جاتا ہوں عنقریب تم کو معلوم ہو جائے گا کہ آخرت میں (بہشت) کس کا گھر ہوگا کچھ شک نہیں کہ مشرک نجات نہیں پانے کے', NULL, NULL, 'e700b219a780b223ecd82b630a1e4ded5f2994a2243c7c8c2789c00c2f17b815'),
  ('ur.jalandhry', 6, 136, 925, 'اور (یہ لوگ) خدا ہی کی پیدا کی ہوئی چیزوں یعنی کھیتی اور چوپایوں میں خدا کا بھی ایک حصہ مقرر کرتے ہیں اور اپنے خیال (باطل) سے کہتے ہیں کہ یہ (حصہ) تو خدا کا اور یہ ہمارے شریکوں (یعنی بتوں) کا تو جو حصہ ان کے شریکوں کا ہوتا ہے وہ تو خدا کی طرف نہیں جا سکتا اور جو حصہ خدا کا ہوتا ہے وہ ان کے شریکوں کی طرف جا سکتا ہے یہ کیسا برا انصاف ہے', NULL, NULL, 'be2f7a861869dc365d4f9275a575cf8ed48319b19216a55b9e7a3f49d5aea95f'),
  ('ur.jalandhry', 6, 137, 926, 'اسی طرح بہت سے مشرکوں کو ان کے شریکوں نے ان کے بچوں کو جان سے مار ڈالنا اچھا کر دکھایا ہے تاکہ انہیں ہلاکت میں ڈال دیں اور ان کے دین کو ان پر خلط ملط کر دیں اور اگر خدا چاہتا تو وہ ایسا نہ کرتے تو ان کو چھوڑ دو کہ وہ جانیں اور ان کا جھوٹ', NULL, NULL, '64643a968a71d259bc22afe4fefe4a50059597d25f2299fbc6b7abccad77a838'),
  ('ur.jalandhry', 6, 138, 927, 'اور اپنے خیال سے یہ بھی کہتے ہیں کہ یہ چارپائے اور کھیتی منع ہے اسے اس شخص کے سوا جسے ہم چاہیں کوئی نہ کھائے اور (بعض) چارپائے ایسے ہیں کہ ان کی پیٹ پر چڑھنا منع کر دیا گیا ہے اور بعض مویشی ایسے ہیں جن پر (ذبح کرتے وقت) خدا کا نام نہیں لیتے سب خدا پر جھوٹ ہے وہ عنقریب ان کو ان کے جھوٹ کا بدلہ دے گا', NULL, NULL, 'd694011e03b6332fd67bc1e24010e18e9980b34a93139b713a2f8e0dca397fe0'),
  ('ur.jalandhry', 6, 139, 928, 'اور یہ بھی کہتے ہیں کہ جو بچہ ان چارپایوں کے پیٹ میں ہے وہ خاص ہمارے مردوں کے لئے ہے اور ہماری عورتوں کو (اس کا کھانا) حرام ہے اور اگر وہ بچہ مرا ہوا ہو تو سب اس میں شریک ہیں (یعنی اسے مرد اور عورتیں سب کھائیں) عنقریب خدا ان کو ان کے ڈھکوسلوں کی سزا دے گا بےشک وہ حکمت والا خبردار ہے', NULL, NULL, 'b5629a257ee530bd1b75d268448253fcc657f59d1a03b1618b11c664f8aafc5a'),
  ('ur.jalandhry', 6, 140, 929, 'جن لوگوں نے اپنی اولاد کو بیوقوفی سے بے سمجھی سے قتل کیا اور خدا پر افترا کر کے اس کی عطا فرمائی کی ہوئی روزی کو حرام ٹہرایا وہ گھاٹے میں پڑ گئے وہ بےشبہ گمراہ ہیں اور ہدایت یافتہ نہیں ہیں', NULL, NULL, '67ea869c94c9e66b876e5d2d60f1d3316014dcbb5c43c622702afb975234b567'),
  ('ur.jalandhry', 6, 141, 930, 'اور خدا ہی تو ہے جس نے باغ پیدا کئے چھتریوں پر چڑھائے ہوئے بھی اور جو چھتریوں پر نہیں چڑھائے ہوئے وہ بھی اور کھجور اور کھیتی جن کے طرح طرح کے پھل ہوتے ہیں اور زیتون اور انار جو (بعض باتوں میں) ایک دوسرے سے ملتے ہیں جب یہ چیزیں پھلیں تو ان کے پھل کھاؤ اور جس دن (پھل توڑو اور کھیتی) کاٹو تو خدا کا حق بھی اس میں سے ادا کرو اور بےجا نہ اڑاؤ کہ خدا بیجا اڑانے والوں کو دوست نہیں رکھتا', NULL, NULL, '702031eea525d5e2982a3d7014d8303cd561cbdcbbaea95adf425ce88a445d57'),
  ('ur.jalandhry', 6, 142, 931, 'اور چارپایوں میں بوجھ اٹھانے والے (یعنی بڑے بڑے) بھی پیدا کئے اور زمین سے لگے ہوئے (یعنی چھوٹے چھوٹے) بھی (پس) خدا کا دیا ہوا رزق کھاؤ اور شیطان کے قدموں پر نہ چلو وہ تمہارا صریح دشمن ہے', NULL, NULL, '50791fe49a26d2610c45cced83a37548924abce20a06df9c4285006ed43d9cc2'),
  ('ur.jalandhry', 6, 143, 932, '(یہ بڑے چھوٹے چارپائے) آٹھ قسم کے (ہیں) دو (دو) بھیڑوں میں سے اور دو (دو) بکریوں میں سے (یعنی ایک ایک نر اور اور ایک ایک مادہ) (اے پیغمبر ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اسے اگر سچے ہو تو مجھے سند سے بتاؤ', NULL, NULL, 'f9066618f5a340337f85947b76b4824ba464e5bab52c81495c722d9020202f51'),
  ('ur.jalandhry', 6, 144, 933, 'اور دو (دو) اونٹوں میں سے اور دو (دو) گایوں میں سے (ان کے بارے میں بھی ان سے) پوچھو کہ (خدا نے) دونوں (کے) نروں کو حرام کیا ہے یا دونوں (کی) مادنیوں کو یا جو بچہ مادنیوں کے پیٹ میں لپٹ رہا ہو اس کو بھلا جس وقت خدا نے تم کو اس کا حکم دیا تھا تم اس وقت موجود تھے؟ تو اس شخص سے زیادہ کون ظالم ہے جو خدا پر جھوٹ افتراء کرے تاکہ اِز راہ بے دانشی لوگوں کو گمراہ کرے کچھ شک نہیں کہ خدا ظالم لوگوں کو ہدایت نہیں دیتا', NULL, NULL, '921e48efb86234fc14a8c56080418a656f977865de5a823c0602794e187afbb4'),
  ('ur.jalandhry', 6, 145, 934, 'کہو کہ جو احکام مجھ پر نازل ہوئے ہیں ان میں کوئی چیز جسے کھانے والا کھائے حرام نہیں پاتا بجز اس کے کہ وہ مرا ہوا جانور یا بہتا لہو یا سور کا گوشت کہ یہ سب ناپاک ہیں یا کوئی گناہ کی چیز ہو کہ اس پر خدا کے سوا کسی اور کا نام لیا گیا ہو اور اگر کوئی مجبور ہو جائے لیکن نہ تو نافرمانی کرے اور نہ حد سے باہر نکل جائے تو تمہارا پروردگار بخشنے والا مہربان ہے', NULL, NULL, '3a8d93f8fe4ec9fc801d697b9428b03ef54a215422c22d2edef87034c1687a3a'),
  ('ur.jalandhry', 6, 146, 935, 'اور یہودیوں پر ہم نے سب ناخن والے جانور حرام کر دئیے تھے اور گایوں اور بکریوں سے ان کی چربی حرام کر دی تھی سوا اس کے جو ان کی پیٹھ پر لگی ہو یا اوجھڑی میں ہو یا ہڈی میں ملی ہو یہ سزا ہم نے ان کو ان کی شرارت کے سبب دی تھی اور ہم تو سچ کہنے والے ہیں', NULL, NULL, 'e3b8865407809f71fee426cf8ccc1f5e1ba8caed016db2413250c52d8ab67a24'),
  ('ur.jalandhry', 6, 147, 936, 'اور اگر یوں لوگ تمہاری تکذیب کریں تو کہہ دو تمہارا پروردگار صاحب رحمت وسیع ہے مگر اس کا عذاب گنہ گاروں لوگوں سے نہیں ٹلے گا', NULL, NULL, '49c0e31f075fd8d87784e943ec7f9c20c91df9c71fadcb7baaf4ce727229ebb5'),
  ('ur.jalandhry', 6, 148, 937, 'جو لوگ شرک کرتے ہیں وہ کہیں گے کہ اگر خدا چاہتا تو ہم شرک نہ کرتے اور نہ ہمارے باپ دادا (شرک کرتے) اور نہ ہم کسی چیز کو حرام ٹھہراتے اسی طرح ان لوگوں نے تکذیب کی تھی جو ان سے پہلے تھے یہاں تک کہ ہمارے عذاب کا مزہ چکھ کر رہے کہہ دو کیا تمہارے پاس کوئی سند ہے (اگر ہے) تو اسے ہمارے سامنے نکالو تم محض خیال کے پیچھے چلتے اور اٹکل کی تیر چلاتے ہو', NULL, NULL, '26ad05f65f2845007db6d8a9650c2b54beddae51b3ffab654a3296b529459463'),
  ('ur.jalandhry', 6, 149, 938, 'کہہ دو کہ خدا ہی کی حجت غالب ہے اگر وہ چاہتا تو تم سب کو ہدایت دے دیتا', NULL, NULL, '4b20d6c4e43d699e2af22cb49f808be3595d5757bf7435ecbe67b1797d8e06c1'),
  ('ur.jalandhry', 6, 150, 939, 'کہو کہ اپنے گواہوں کو لاؤ جو بتائیں کہ خدا نے یہ چیزیں حرام کی ہیں پھر اگر وہ (آ کر) گواہی دیں تو تم ان کے ساتھ گواہی نہ دینا اور نہ ان لوگوں کی خواہشوں کی پیروی کرنا جو ہماری آیتوں کو جھٹلاتے ہیں اور آخرت پر ایمان نہیں لاتے اور (بتوں کو) اپنے پروردگار کے برابر ٹھہراتے ہیں', NULL, NULL, '7b572a84b5ef931b082ef743ddb0072587eb1e1560a027a946dad290d1c5711f'),
  ('ur.jalandhry', 6, 151, 940, 'کہہ کہ (لوگو) آؤ میں تمہیں وہ چیزیں پڑھ کر سناؤں جو تمہارے پروردگار نے تم پر حرام کر دی ہیں (ان کی نسبت اس نے اس طرح ارشاد فرمایا ہے) کہ کسی چیز کو خدا کا شریک نہ بنانا اور ماں باپ (سے بدسلوکی نہ کرنا بلکہ) سلوک کرتے رہنا اور ناداری (کے اندیشے) سے اپنی اولاد کو قتل نہ کرنا کیونکہ تم کو اور ان کو ہم ہی رزق دیتے ہیں اور بےحیائی کے کام ظاہر ہوں یا پوشیدہ ان کے پاس نہ پھٹکنا اور کسی جان (والے) کو جس کے قتل کو خدا نے حرام کر دیا ہے قتل نہ کرنا مگر جائز طور پر (یعنی جس کا شریعت حکم دے) ان باتوں کا وہ تمہیں ارشاد فرماتا ہے تاکہ تم سمجھو', NULL, NULL, 'ee51677fb419c4d537f3e0160bfb36fca8a4c3340b7b59b3bdb1382f2efcd71b'),
  ('ur.jalandhry', 6, 152, 941, 'اور یتیم کے مال کے پاس بھی نہ جانا مگر ایسے طریق سے کہ بہت ہی پسندیدہ ہو یہاں تک کہ وہ جوانی کو پہنچ جائے اور ناپ تول انصاف کے ساتھ پوری پوری کیا کرو ہم کسی کو تکلیف نہیں دیتے مگر اس کی طاقت کے مطابق اور جب (کسی کی نسبت) کوئی بات کہو تو انصاف سے کہو گو وہ (تمہارا) رشتہ دار ہی ہو اور خدا کے عہد کو پورا کرو ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم نصحیت کرو', NULL, NULL, '89ba027a65d78f7c2c0b23428aa02fbbe1df60aec649e657ad98581c2477f07a'),
  ('ur.jalandhry', 6, 153, 942, 'اور یہ کہ میرا سیدھا رستہ یہی ہے تو تم اسی پر چلنا اور اور رستوں پر نہ چلنا کہ (ان پر چل کر) خدا کے رستے سے الگ ہو جاؤ گے ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم پرہیزگار بنو', NULL, NULL, '4982312cfe4ca5ed932760ffdf9aaee1246abdf9ce669181831d8c6fa7634f48'),
  ('ur.jalandhry', 6, 154, 943, '(ہاں) پھر (سن لو کہ) ہم نے موسیؑ کو کتاب عنایت کی تھی تاکہ ان لوگوں پر جو نیکوکار ہیں نعمت پوری کر دیں اور (اس میں) ہر چیز کا بیان (ہے) اور ہدایت (ہے) اور رحمت ہے تاکہ (ان کی امت کے) لوگ اپنے پروردگار کے رُوبرو حاضر ہونے کا یقین کریں', NULL, NULL, '84dad4d712f039147d832ee9152be8e1d79bbc25a2ceb352f184c34574304296'),
  ('ur.jalandhry', 6, 155, 944, 'اور (اے کفر کرنے والوں) یہ کتاب بھی ہمیں نے اتاری ہے برکت والی تو اس کی پیروی کرو اور (خدا سے) ڈرو تاکہ تم پر مہربانی کی جائے', NULL, NULL, 'a3750c9acd53e0c7a3b18d1ffae092be7057ab4ee49955d11ff2df7f113f6978'),
  ('ur.jalandhry', 6, 156, 945, '(اور اس لیے اتاری ہے) کہ (تم یوں نہ) کہو کہ ہم سے پہلے دو ہی گروہوں پر کتابیں اتری تھیں اور ہم ان کے پڑھنے سے (معذور اور) بےخبر تھے', NULL, NULL, '82e1b4d9234fe5f825c625c848306a47cb2c8f5fe7578460b328e497994845ab'),
  ('ur.jalandhry', 6, 157, 946, 'یا (یہ نہ) کہو کہ اگر ہم پر بھی کتاب نازل ہوتی تو ہم ان لوگوں کی نسبت کہیں سیدھے رستے پر ہوتے سو تمہارے پاس تمہارے پروردگار کی طرف سے دلیل اور ہدایت اور رحمت آ گئی ہے تو اس سے بڑھ کر ظالم کون ہوگا جو خدا کی آیتوں کی تکذیب کرے اور ان سے (لوگوں کو) پھیرے جو لوگ ہماری آیتوں سے پھیرتے ہیں اس پھیرنے کے سبب ہم ان کو برے عذاب کی سزا دیں گے', NULL, NULL, 'dcda1a3f1bd884246dc707d6f5e7de915bd7910e4baef646aff732838bb60d02'),
  ('ur.jalandhry', 6, 158, 947, 'یہ اس کے سوا اور کس بات کے منتظر ہیں کہ ان کے پاس فرشتے آئیں یا خود تمہارا پروردگار آئے یا تمہارے پروردگار کی کچھ نشانیاں آئیں (مگر) جس روز تمہارے پروردگار کی کچھ نشانیاں آ جائیں گی تو جو شخص پہلے ایمان نہیں لایا ہوگا اس وقت اسے ایمان لانا کچھ فائدہ نہیں دے گا یا اپنے ایمان (کی حالت) میں نیک عمل نہیں کئے ہوں گے (تو گناہوں سے توبہ کرنا مفید نہ ہوگا اے پیغمبر ان سے) کہہ دو کہ تم بھی انتظار کرو ہم بھی انتظار کرتے ہیں', NULL, NULL, '82721b64360fda1bf75d2ec98e3c0563b869a0d57b74eca3e2492d9edb84fcf3'),
  ('ur.jalandhry', 6, 159, 948, 'جن لوگوں نے اپنے دین میں (بہت سے) رستے نکالے اور کئی کئی فرقے ہو گئے ان سے تم کو کچھ کام نہیں ان کا کام خدا کے حوالے پھر جو کچھ وہ کرتے رہے ہیں وہ ان کو (سب) بتائے گا', NULL, NULL, '9f09306eb85851c37be6c1522aa85ddeec2b912843433adf4cab64e7cd392830'),
  ('ur.jalandhry', 6, 160, 949, 'اور جو کوئی (خدا کے حضور) نیکی لے کر آئے گا اس کو ویسی دس نیکیاں ملیں گی اور جو برائی لائے گا اسے سزا ویسے ہی ملے گی اور ان پر ظلم نہیں کیا جائے گا', NULL, NULL, '45c6e97912e94afc8d269b5ad7a74b2436f6dc275fb324ca62be6da57015abd1'),
  ('ur.jalandhry', 6, 161, 950, 'کہہ دو کہ مجھے میرے پروردگار نے سیدھا رستہ دکھا دیا ہے (یعنی دین صحیح) مذہب ابراہیم کا جو ایک (خدا) ہی کی طرف کے تھے اور مشرکوں میں سے نہ تھے', NULL, NULL, 'acfbdbf7a6bd187d67888b6d28106fb2e03cb9da74494d2e8b1f61b23bf3c5d7'),
  ('ur.jalandhry', 6, 162, 951, '(یہ بھی) کہہ دو کہ میری نماز اور میری عبادت اور میرا جینا اور میرا مرنا سب خدائے رب العالمین ہی کے لیے ہے', NULL, NULL, '7ad6e71f5e2450b71ad0781f4ad3ff27fe653216fddf437d59fd9898c9d7a726'),
  ('ur.jalandhry', 6, 163, 952, 'جس کا کوئی شریک نہیں اور مجھ کو اسی بات کا حکم ملا ہے اور میں سب سے اول فرمانبردار ہوں', NULL, NULL, '16a2d52ca97fba6dd19eff02303883b079c1ad9a475392fe704811836b580448'),
  ('ur.jalandhry', 6, 164, 953, 'کہو کیا میں خدا کے سوا اور پروردگار تلاش کروں اور وہی تو ہر چیز کا مالک ہے اور جو کوئی (برا) کام کرتا ہے تو اس کا ضرر اسی کو ہوتا ہے اور کوئی شخص کسی (کے گناہ) کا بوجھ نہیں اٹھائے گا پھر تم سب کو اپنے پروردگار کی طرف لوٹ کا جانا ہے تو جن جن باتوں میں تم اختلاف کیا کرتے تھے وہ تم کو بتائے گا', NULL, NULL, '704491e4226ee319cd5d90a722130db50322af4044940b029cb57a24cba7e0ae'),
  ('ur.jalandhry', 6, 165, 954, 'اور وہی تو ہے جس نے زمین میں تم کو اپنا نائب بنایا اور ایک کے دوسرے پر درجے بلند کئے تاکہ جو کچھ اس نے تمہیں بخشا ہے اس میں تمہاری آزمائش ہے بےشک تمہارا پروردگار جلد عذاب دینے والا ہے اور بےشک وہ بخشنے والا مہربان بھی ہے', NULL, NULL, 'a9517ff39b1853f0154b351b727eefa25cc72d3b303741e306f1150be80807ce'),
  ('ur.jalandhry', 7, 1, 955, 'المص', NULL, NULL, '62fb50dac60f538db34c9119ba2520a3ced5e4cfcabd6205b22cc64c9b95e1bb'),
  ('ur.jalandhry', 7, 2, 956, '(اے محمدﷺ) یہ کتاب (جو) تم پر نازل ہوئی ہے۔ اس سے تمہیں تنگ دل نہیں ہونا چاہیئے، (یہ نازل) اس لیے (ہوئی ہے) کہ تم اس کے ذریعے سے (لوگوں) کو ڈر سناؤ اور (یہ) ایمان والوں کے لیے نصیحت ہے', NULL, NULL, '89a263f452967616479cfc92e6cfebd0520abcb0a656502d41ce7c8d03d3f4e3'),
  ('ur.jalandhry', 7, 3, 957, '(لوگو) جو (کتاب) تم پر تمہارے پروردگار کے ہاں نازل ہوئی ہے اس کی پیروی کرو اور اس کے سوا اور رفیقوں کی پیروی نہ کرو (اور) تم کم ہی نصیحت قبول کرتے ہو', NULL, NULL, '647fe21972f4911b92aa8ff5a7ade2a35920ad28537dc0873edc843a52580198'),
  ('ur.jalandhry', 7, 4, 958, 'اور کتنی ہی بستیاں ہیں کہ ہم نے تباہ کر ڈالیں جن پر ہمارا عذاب (یا تو رات کو) آتا تھا جبکہ وہ سوتے تھے یا (دن کو) جب وہ قیلولہ (یعنی دوپہر کو آرام) کرتے تھے', NULL, NULL, 'c0bf948cb1338e96daee5d1800834b869edaadbe8d3b4a632d1dc30dd10505d1'),
  ('ur.jalandhry', 7, 5, 959, 'تو جس وقت ان پر عذاب آتا تھا ان کے منہ سے یہی نکلتا تھا کہ (ہائے) ہم (ہائے) ہم (اپنے اوپر) ظلم کرتے رہے', NULL, NULL, 'ae1c5ae18521da5915016b345d70141bb2dbb186208ac4468bd0236eea5680f9'),
  ('ur.jalandhry', 7, 6, 960, 'تو جن لوگوں کی طرف پیغمبر بھیجے گئے ہم ان سے بھی پرسش کریں گے اور پیغمبروں سے بھی پوچھیں گے', NULL, NULL, '3c90b9c36971871c71027a45a99f04264de19f14e6c61725d0b28ee59f11dde1'),
  ('ur.jalandhry', 7, 7, 961, 'پھر اپنے علم سے ان کے حالات بیان کریں گے اور ہم کہیں غائب تو نہیں تھے', NULL, NULL, '7c9ff4fecfa17db680d427963353c4f47f6adb7527b82320090085055a041b3f'),
  ('ur.jalandhry', 7, 8, 962, 'اور اس روز (اعمال کا) تلنا برحق ہے تو جن لوگوں کے (عملوں کے) وزن بھاری ہوں گے وہ تو نجات پانے والے ہیں', NULL, NULL, '22c61c6de3c2abeac9c9eddb064e5701db40a8148ade3348faff74b09963a625'),
  ('ur.jalandhry', 7, 9, 963, 'اور جن کے وزن ہلکے ہوں گے تو یہی لوگ ہیں جنہوں نے اپنے تئیں خسارے میں ڈالا اس لیے کہ ہماری آیتوں کے بارے میں بےانصافی کرتے تھے', NULL, NULL, '4db393f9fd65e380c87a752878fa0726cff0ce6ecc7f6f83399f5bcea3b9ef2f'),
  ('ur.jalandhry', 7, 10, 964, 'اور ہم ہی نے زمین میں تمہارا ٹھکانہ بنایا اور اس میں تمہارے لیے سامان معشیت پیدا کئے۔ (مگر) تم کم ہی شکر کرتے ہو', NULL, NULL, 'd3cf8de5a1efbc12a2ea04109614cc6c55d1375e872e02be7c1f07d1b064328f'),
  ('ur.jalandhry', 7, 11, 965, 'اور ہم ہی نے تم کو (ابتدا میں مٹی سے) پیدا کیا پھر تمہاری صورت شکل بنائی پھر فرشتوں کو حکم دیا آدم کے آگے سجدہ کرو تو (سب نے) سجدہ کیا لیکن ابلیس کہ وہ سجدہ کرنے والوں میں (شامل) نہ ہوا', NULL, NULL, '68cbd56e59d547d99ea429e2320e62f9c0ffc954eff89ff98de52e78cfd295e3'),
  ('ur.jalandhry', 7, 12, 966, '(خدا نے) فرمایا جب میں نے تجھ کو حکم دیا تو کس چیز نے تجھے سجدہ کرنے سے باز رکھا۔ اس نے کہا کہ میں اس سے افضل ہوں۔ مجھے تو نے آگ سے پیدا کیا ہے اور اسے مٹی سے بنایا ہے', NULL, NULL, '61a6822f86b81d93713715792567e77eaafb9cb5f4bd23f5320317bdd299c034'),
  ('ur.jalandhry', 7, 13, 967, 'فرمایا تو (بہشت سے) اتر جا تجھے شایاں نہیں کہ یہاں غرور کرے پس نکل جا۔ تو ذلیل ہے', NULL, NULL, '5f0fed9c6c8ea6e4cd9c016a783f790429286ed97b1e08073bd04a64a571a1d3'),
  ('ur.jalandhry', 7, 14, 968, 'اس نے کہا کہ مجھے اس دن تک مہلت عطا فرما جس دن لوگ (قبروں سے) اٹھائے جائیں گے', NULL, NULL, 'dbd5f115d65cb76e0d45a95fd3bb77a4c30de8acb8222a20f18eaba7817cbd9b'),
  ('ur.jalandhry', 7, 15, 969, 'فرمایا (اچھا) تجھ کو مہلت دی جاتی ہے', NULL, NULL, '01d04cd4661521621f1db64bec4008e4ca8004675051f930ae9dc58df691473c'),
  ('ur.jalandhry', 7, 16, 970, '(پھر) شیطان نے کہا مجھے تو تُو نے ملعون کیا ہی ہے میں بھی تیرے سیدھے رستے پر ان (کو گمراہ کرنے) کے لیے بیٹھوں گا', NULL, NULL, 'c7c5888dea70a0cc7fcfe2b37e65de68aba8d62c0c4bcbb9da5ef1f15f41fff3'),
  ('ur.jalandhry', 7, 17, 971, 'پھر ان کے آگے سے اور پیچھے سے دائیں سے اور بائیں سے (غرض ہر طرف سے) آؤں گا (اور ان کی راہ ماروں گا) اور تو ان میں اکثر کو شکر گزار نہیں پائے گا', NULL, NULL, '668c666c025ca4aed90898e23be6689fbd8a051ef7706341c3432be4eccbd121'),
  ('ur.jalandhry', 7, 18, 972, '(خدا نے) فرمایا، نکل جا۔ یہاں سے پاجی۔ مردود جو لوگ ان میں سے تیری پیروی کریں گے میں (ان کو اور تجھ کو جہنم میں ڈال کر) تم سب سے جہنم کو بھر دوں گا', NULL, NULL, '2effa4e11f645374063cb35e4c0137c6d19b0d941256ba6f2a6a5ec2fb632b35'),
  ('ur.jalandhry', 7, 19, 973, 'اور ہم نے آدم (سے کہا کہ) تم اور تمہاری بیوی بہشت میں رہو سہو اور جہاں سے چاہو (اور جو چاہو) نوش جان کرو مگر اس درخت کے پاس نہ جاؤ ورنہ گنہگار ہو جاؤ گے', NULL, NULL, 'c0336a35bc252f6ef84278afdd39e70d5bd4a48754d3f45e25cc9d66d15590f4'),
  ('ur.jalandhry', 7, 20, 974, 'تو شیطان دونوں کو بہکانے لگا تاکہ ان کی ستر کی چیزیں جو ان سے پوشیدہ تھیں کھول دے اور کہنے لگا کہ تم کو تمہارے پروردگار نے اس درخت سے صرف اس لیے منع کیا ہے کہ کہ تم فرشتے نہ بن جاؤ یا ہمیشہ جیتے نہ رہو', NULL, NULL, 'cf07e0f766d066ac6e6231d0e264d0f9620ccba766694ad721472d5d554488e5'),
  ('ur.jalandhry', 7, 21, 975, 'اور ان سے قسم کھا کر کہا میں تو تمہارا خیر خواہ ہوں', NULL, NULL, 'd1fe8d803c35a20bf6370d3a8000e858e70d803a0fb53dcc8e757026f1c805f5'),
  ('ur.jalandhry', 7, 22, 976, 'غرض (مردود نے) دھوکہ دے کر ان کو (معصیت کی طرف) کھینچ ہی لیا جب انہوں نے اس درخت (کے پھل) کو کھا لیا تو ان کی ستر کی چیزیں کھل گئیں اور وہ بہشت کے (درختوں کے) پتے توڑ توڑ کر اپنے اوپر چپکانے لگے اور (ستر چھپانے لگے) تب ان کے پروردگار نے ان کو پکارا کہ کیا میں نے تم کو اس درخت (کے پاس جانے) سے منع نہیں کیا تھا اور جتا نہیں دیا تھا کہ شیطان تمہارا کھلم کھلا دشمن ہے', NULL, NULL, '5d53335f7d3eb4105ed749aed4405e72f1b30df804125374c9caf511b7b3ea1e'),
  ('ur.jalandhry', 7, 23, 977, 'دونوں عرض کرنے لگے کہ پروردگار ہم نے اپنی جانوں پر ظلم کیا اور اگر تو ہمیں نہیں بخشے گا اور ہم پر رحم نہیں کرے گا تو ہم تباہ ہو جائیں گے', NULL, NULL, 'f3ca8bc0a883b06bd6a47b89505ad68818b38d1aca0e23237d9d987a14585e9f'),
  ('ur.jalandhry', 7, 24, 978, '(خدا نے) فرمایا (تم سب بہشت سے) اتر جاؤ (اب سے) تم ایک دوسرے کے دشمن ہو اور تمہارے لیے ایک وقت (خاص) تک زمین پر ٹھکانہ اور (زندگی کا) سامان (کر دیا گیا) ہے', NULL, NULL, '81bf25a0f418db7241c30ed1635247cbeaa55c34df4e61898be5dc361c3ff001'),
  ('ur.jalandhry', 7, 25, 979, '(یعنی) فرمایا کہ اسی میں تمہارا جینا ہوگا اور اسی میں مرنا اور اسی میں سے (قیامت کو زندہ کر کے) نکالے جاؤ گے', NULL, NULL, '959e2eb2c74221f5aa502b2265d5d820e8fc19845952e486a525c3e2b437e339'),
  ('ur.jalandhry', 7, 26, 980, 'اے نبی آدم ہم نے تم پر پوشاک اتاری کہ تمہارا ستر ڈھانکے اور (تمہارے بدن کو) زینت (دے) اور (جو) پرہیزگاری کا لباس (ہے) وہ سب سے اچھا ہے۔ یہ خدا کی نشانیاں ہیں تاکہ لوگ نصحیت پکڑ یں', NULL, NULL, '80b22092858d83fb1536542c43e75f1e919b7219dfed3810cc19e4e9591b0bfd'),
  ('ur.jalandhry', 7, 27, 981, 'اے نبی آدم (دیکھنا کہیں) شیطان تمہیں بہکا نہ دے جس طرح تمہارے ماں باپ کو (بہکا کر) بہشت سے نکلوا دیا اور ان سے ان کے کپڑے اتروا دیئے تاکہ ان کے ستر ان کو کھول کر دکھا دے۔ وہ اور اس کے بھائی تم کو ایسی جگہ سے دیکھتے رہے ہیں جہاں سے تم ان کو نہیں دیکھ سکتے ہم نے شیطانوں کو انہیں لوگوں کا رفیق کار بنایا ہے جو ایمان نہیں رکھتے', NULL, NULL, '919517036c3e5fde44f7b6ef4a979b5b8b29c5b1c0f75ad4427092e36e47a3d9'),
  ('ur.jalandhry', 7, 28, 982, 'اور جب کوئی بے حیائی کا کام کرتے ہیں تو کہتے ہیں کہ ہم نے اپنے بزرگوں کو اسی طرح کرتے دیکھا ہے اور خدا نے بھی ہم کو یہی حکم دیا ہے۔ کہہ دو خدا بےحیائی کے کام کرنے کا ہرگز حکم نہیں دیتا۔ بھلا تم خدا کی نسبت ایسی بات کیوں کہتے ہو جس کا تمہیں علم نہیں', NULL, NULL, '1b036c35a44887fcb986ebf1caa70901839c9528f528bbe8960d76a0fb941a1d'),
  ('ur.jalandhry', 7, 29, 983, 'کہہ دو کہ میرے پروردگار نے تو انصاف کرنے کا حکم دیا ہے۔ اور یہ کہ ہر نماز کے وقت سیدھا (قبلے کی طرف) رخ کیا کرو اور خاص اسی کی عبادت کرو اور اسی کو پکارو۔ اس نے جس طرح تم کو ابتداء میں پیدا کیا تھا اسی طرح تم پھر پیدا ہوگے', NULL, NULL, '6265aff4be15f6bcbc223053b1fb2bcba0c63f2bad81005f445b3b250a5914f3'),
  ('ur.jalandhry', 7, 30, 984, 'ایک فریق کو تو اس نے ہدایت دی اور ایک فریق پر گمراہی ثابت ہوچکی۔ ان لوگوں نے خدا کو چھوڑ کر شیطانوں کو رفیق بنا لیا اور سمجھتے (یہ) ہیں کہ ہدایت یاب ہیں', NULL, NULL, '0f84659a470a713c2a26cab1343daed0a71fe0bcdb9836f5c3761ee834718b17'),
  ('ur.jalandhry', 7, 31, 985, 'اے نبی آدم! ہر نماز کے وقت اپنے تئیں مزّین کیا کرو اور کھاؤ اور پیؤ اور بےجا نہ اڑاؤ کہ خدا بےجا اڑانے والوں کو دوست نہیں رکھتا', NULL, NULL, 'e5dde715ddf6f17d59ce210ba5447210f1e36210d1607bbe8bd99a9a714f1704'),
  ('ur.jalandhry', 7, 32, 986, 'پوچھو تو کہ جو زینت (وآرائش) اور کھانے (پینے) کی پاکیزہ چیزیں خدا نے اپنے بندوں کے لیے پیدا کی ہیں ان کو حرام کس نے کیا ہے؟ کہہ دو کہ یہ چیزیں دنیا کی زندگی میں ایمان والوں کے لیے ہیں اور قیامت کے دن خاص ان ہی کا حصہ ہوں گی۔ اسی طرح خدا اپنی آیتیں سمجھنے والوں کے لیے کھول کھول کر بیان فرماتا ہے', NULL, NULL, 'dc206337fe0102108f46b3af276e2f36c28985cfe1558a814e88feef603b4d74'),
  ('ur.jalandhry', 7, 33, 987, 'کہہ دو کہ میرے پروردگار نے تو بےحیائی کی باتوں کو ظاہر ہوں یا پوشیدہ اور گناہ کو اور ناحق زیادتی کرنے کو حرام کیا ہے۔ اور اس کو بھی کہ تم کسی کو خدا کا شریک بناؤ جس کی اس نے کوئی سند نازل نہیں کی اور اس کو بھی کہ خدا کے بارے میں ایسی باتیں کہو جن کا تمہیں کچھ علم نہیں', NULL, NULL, '88a1fa47855555d2b288f7ca8b05797f9cab8fd7a54789a3570b19f61aabc070'),
  ('ur.jalandhry', 7, 34, 988, 'اور ہر ایک فرقے کے لیے (موت کا) ایک وقت مقرر ہے۔ جب وہ آ جاتا ہے تو نہ تو ایک گھڑی دیر کرسکتے ہیں نہ جلدی', NULL, NULL, 'a4108d4a2d393da9974ba0c98bc9df0adf731222442fda74a5f63cc3d63ec364'),
  ('ur.jalandhry', 7, 35, 989, 'اے نبی آدم! (ہم تم کو یہ نصیحت ہمیشہ کرتے رہے ہیں کہ) جب ہمارے پیغمبر تمہارے پاس آیا کریں اور ہماری آیتیں تم کو سنایا کریں (تو ان پر ایمان لایا کرو) کہ جو شخص (ان پر ایمان لا کر خدا سے) ڈرتا رہے گا اور اپنی حالت درست رکھے گا تو ایسے لوگوں کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے', NULL, NULL, '9fa15f1550b54f5e1a7e748e6e46e90abc8758803d8a90a46e71002f1657a142'),
  ('ur.jalandhry', 7, 36, 990, 'اور جنہوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی وہی دوزخی ہیں کہ ہمیشہ اس میں (جلتے) رہیں گے', NULL, NULL, '92105b224d9bc2d32939650c7f76f8238724aa4786b1ac8d706bceaf7636542a'),
  ('ur.jalandhry', 7, 37, 991, 'تو اس سے زیادہ ظالم کون ہے جو خدا پر جھوٹ باندھے یا اس کی آیتوں کو جھٹلائے۔ ان کو ان کے نصیب کا لکھا ملتا ہی رہے گا یہاں تک کہ جب ان کے پاس ہمارے بھیجے ہوئے (فرشتے) جان نکالنے آئیں گے تو کہیں گے کہ جن کو تم خدا کے سوا پکارا کرتے تھے وہ (اب) کہاں ہیں؟ وہ کہیں گے (معلوم نہیں) کہ وہ ہم سے (کہاں) غائب ہوگئے اور اقرار کریں گے کہ بےشک وہ کافر تھے', NULL, NULL, 'd809142298707c193430e8b67daa2185f426b3f2b4af47d37c8670d1f9e8513c'),
  ('ur.jalandhry', 7, 38, 992, 'تو خدا فرمائے گا کہ جنّوں اور انسانوں کی جو جماعتیں تم سے پہلے ہو گزری ہیں ان کے ساتھ تم بھی داخل جہنم ہو جاؤ۔ جب ایک جماعت (وہاں) جا داخل ہو گئی تو اپنی (مذہبی) بہن (یعنی اپنے جیسی دوسری جماعت) پر لعنت کرے گی۔ یہاں تک کہ جب سب اس میں داخل ہو جائیں گے تو پچھلی جماعت پہلی کی نسبت کہے گی کہ اے پروردگار! ان ہی لوگوں نے ہم کو گمراہ کیا تھا تو ان کو آتش جہنم کا دگنا عذاب دے۔ خدا فرمائے گا کہ (تم) سب کو دگنا (عذاب دیا جائے گا) مگر تم نہیں جانتے', NULL, NULL, '271bef6d6e45da724587cb443442778ab6d15d0eedeea798bdc79df53a3e75f7'),
  ('ur.jalandhry', 7, 39, 993, 'اور پہلی جماعت پچھلی جماعت سے کہے گی کہ تم کو ہم پر کچھ بھی فضیلت نہ ہوئی تو جو (عمل) تم کیا کرتے تھے اس کے بدلے میں عذاب کے مزے چکھو', NULL, NULL, 'f3be6614494e2100d99f8af938fa2cae9735790718e74f8ab9f7b107b8668bad'),
  ('ur.jalandhry', 7, 40, 994, 'جن لوگوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی۔ ان کے لیے نہ آسمان کے دروازے کھولے جائیں گے اور نہ وہ بہشت میں داخل ہوں گے۔ یہاں تک کہ اونٹ سوئی کے ناکے میں سے نہ نکل جائے اور گنہگاروں کو ہم ایسی ہی سزا دیا کرتے ہیں', NULL, NULL, '6c9af6b254922e502261747285e5969ecef516ff6cd6e89442cbcabc57fcf94d'),
  ('ur.jalandhry', 7, 41, 995, 'ایسے لوگوں کے لیے (نیچے) بچھونا بھی (آتش) جہنم کا ہوگا اور اوپر سے اوڑھنا بھی (اسی کا) اور ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں', NULL, NULL, '902254e1c8427a730a20628cfcb6754c38b21c956cbe481de7139e46c6ae3157'),
  ('ur.jalandhry', 7, 42, 996, 'اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے اور ہم (عملوں کے لیے) کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے۔ ایسے ہی لوگ اہل بہشت ہیں (کہ) اس میں ہمیشہ رہیں گے', NULL, NULL, '412a90c77935d1f4152849ad309a5101b5fc5bf5c1a8d8259cfa72607e926691'),
  ('ur.jalandhry', 7, 43, 997, 'اور جو کینے ان کے دلوں میں ہوں گے ہم سب نکال ڈالیں گے۔ ان کے محلوں کے نیچے نہریں بہہ رہی ہوں گی اور کہیں گے کہ خدا کا شکر ہے جس نے ہم کو یہاں کا راستہ دکھایا اور اگر خدا ہم کو رستہ نہ دکھاتا تو ہم رستہ نہ پا سکتے۔ بےشک ہمارا پروردگار کے رسول حق بات لے کر آئے تھے اور (اس روز) منادی کر دی جائے گی کہ تم ان اعمال کے صلے میں جو دنیا میں کرتے تھے اس بہشت کے وارث بنا دیئے گئے ہو', NULL, NULL, '2b1c11d29126a666e04f6d829b8a97079d4993ee41bba1e92f404a48b6c33028'),
  ('ur.jalandhry', 7, 44, 998, 'اور اہل بہشت دوزخیوں سے پکار کر کہیں گے کہ جو وعدہ ہمارے پروردگار نے ہم سے کیا تھا ہم نے تو اسے سچا پالیا۔ بھلا جو وعدہ تمہارے پروردگار نے تم سے کیا تھا تم نے بھی اسے سچا پایا؟ وہ کہیں گے ہاں تو (اس وقت) ان میں ایک پکارنے والا پکارے گا کہ بےانصافوں پر خدا کی لعنت', NULL, NULL, '4414f071cc7ec7d6fc07df70e9294e2aab86ca42b54de60a7f8ea3c923b40048'),
  ('ur.jalandhry', 7, 45, 999, 'جو خدا کی راہ سے روکتے اور اس میں کجی ڈھونڈتے اور آخرت سے انکار کرتے تھے', NULL, NULL, '25f1fc2c8fad0e61231d60bbc02873033c223842a3acf01914f1ea46b636fd16'),
  ('ur.jalandhry', 7, 46, 1000, 'ان دونوں (یعنی بہشت اور دوزخ) کے درمیان (اعراف نام) ایک دیوار ہو گی اور اعراف پر کچھ آدمی ہوں گے جو سب کو ان کی صورتوں سے پہچان لیں گے۔ تو وہ اہل بہشت کو پکار کر کہیں گے کہ تم پر سلامتی ہو۔ یہ لوگ بھی بہشت میں داخل تو نہیں ہوں گے مگر امید رکھتے ہوں گے', NULL, NULL, 'c7ded74ba69f5bdaa9206ab6da798e9f53a03bd518762ad331deb3d4a53d116f')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
