  ('ur.jalandhry', 15, 46, 1848, '(ان سے کہا جائے گا کہ) ان میں سلامتی (اور خاطر جمع سے) داخل ہوجاؤ', NULL, NULL, 'aba6db5e7ff4386fdd7bb1f06c0774e28b6c2c83d65c77808e9d3c40e641a85b'),
  ('ur.jalandhry', 15, 47, 1849, 'اور ان کے دلوں میں جو کدورت ہوگی ان کو ہم نکال کر (صاف کر) دیں گے (گویا) بھائی بھائی تختوں پر ایک دوسرے کے سامنے بیٹھے ہوئے ہیں', NULL, NULL, '56688b500da9bf71e9c4efed66b6c4049d8a8cf63924efbbdc5839dd5c1a1df5'),
  ('ur.jalandhry', 15, 48, 1850, 'نہ ان کو وہاں کوئی تکلیف پہنچے گی اور نہ وہاں سے نکالے جائیں گے', NULL, NULL, 'aa82692a3f3a8ef6a3e2145fb5be17016aef5744e6871388f950857031500afa'),
  ('ur.jalandhry', 15, 49, 1851, '(اے پیغمبر) میرے بندوں کو بتادو کہ میں بڑا بخشنے والا (اور) مہربان ہوں', NULL, NULL, '8e1e8b7c73f5d969bb552b4b1ccbbf409cb108972c4927e476f8596f5d65fe4b'),
  ('ur.jalandhry', 15, 50, 1852, 'اور یہ کہ میرا عذاب بھی درد دینے والا عذاب ہے', NULL, NULL, 'aea4914ab972a0f0b3e4078a75c1b82b462c9aa89d3aedfb7af66569c54d729d'),
  ('ur.jalandhry', 15, 51, 1853, 'اور ان کو ابراہیم کے مہمانوں کا احوال سنادو', NULL, NULL, 'f8cfd256e561c70de2d39d33d7646b6439135cb92b2d1c26d997f2f647bfc057'),
  ('ur.jalandhry', 15, 52, 1854, 'جب وہ ابراہیم کے پاس آئے تو سلام کہا۔ (انہوں نے) کہا کہ ہمیں تو تم سے ڈر لگتا ہے', NULL, NULL, '03fef1d001e88a1e0e0eb89035da825d0240740a9608e7af045166049f8f4365'),
  ('ur.jalandhry', 15, 53, 1855, '(مہمانوں نے) کہا کہ ڈریئے نہیں ہم آپ کو ایک دانشمند لڑکے کی خوشخبری دیتے ہیں', NULL, NULL, 'a3d8838dd51b4000cb51c80a16b7f69351134b8ebbdb02a7de766abc32ca5a87'),
