  ('ur.jalandhry', 15, 55, 1857, '(انہوں نے) کہا ہم آپ کو سچی خوشخبری دیتے ہیں آپ مایوس نہ ہوئیے', NULL, NULL, 'aec37cda17e448312339d0c7faad962e60aa6aab81f6ed142a713c85ba234da2'),
  ('ur.jalandhry', 15, 56, 1858, '(ابراہیم نے) کہا کہ خدا کی رحمت سے (میں مایوس کیوں ہونے لگا اس سے) مایوس ہونا گمراہوں کا کام ہے', NULL, NULL, 'a11610469195592a74de123b93514d1b41515648b03f1674237759c8411a6322'),
