  ('ur.jalandhry', 20, 16, 2364, 'تو جو شخص اس پر ایمان نہیں رکھتا اور اپنی خواہش کے پیچھے چلتا ہے (کہیں) تم کو اس (کے یقین) سے روک نہ دے تو (اس صورت میں) تم ہلاک ہوجاؤ', NULL, NULL, '090e426368e4c062ac02c2a2cba98b82cc994d43c795229a8e7ec9805ebca564'),
  ('ur.jalandhry', 20, 17, 2365, 'اور موسی یہ تمہارے داہنے ہاتھ میں کیا ہے', NULL, NULL, '18c63c67bfdf8b418f85db76310d969724e1ea35497c653909a8ab0076fef548'),
  ('ur.jalandhry', 20, 18, 2366, 'انہوں نے کہا یہ میری لاٹھی ہے۔ اس پر میں سہارا لگاتا ہوں اور اس سے اپنی بکریوں کے لئے پتے جھاڑتا ہوں اور اس میں میرے لئے اور بھی کئی فائدے ہیں', NULL, NULL, '8c5be351423f4202ecd3b212c62d918e9ab538e75ccabbadcab745f1c3a232dc'),
  ('ur.jalandhry', 20, 19, 2367, 'فرمایا کہ موسیٰ اسے ڈال دو', NULL, NULL, '96811d6e680941e1bb490f663be1f30d516431d9859f1461b2138dc0a488fb6a'),
  ('ur.jalandhry', 20, 20, 2368, 'تو انہوں نے اس کو ڈال دیا اور وہ ناگہاں سانپ بن کر دوڑنے لگا', NULL, NULL, '348b3cc20e13ac77f05be6d4869cca95edbcf14abf10c5f808e1c84e9bfb5b20'),
  ('ur.jalandhry', 20, 21, 2369, 'خدا نے فرمایا کہ اسے پکڑ لو اور ڈرنا مت۔ ہم اس کو ابھی اس کی پہلی حالت پر لوٹا دیں گے', NULL, NULL, 'c285584b14b63b9481ff0c1457fd44caf228aa824762a36972448c79761f83dc'),
  ('ur.jalandhry', 20, 22, 2370, 'اور اپنا ہاتھ اپنی بغل سے لگالو وہ کسی عیب (وبیماری) کے بغیر سفید (چمکتا دمکتا) نکلے گا۔ (یہ) دوسری نشانی (ہے)', NULL, NULL, '0bc779d455941952c5acd2ee6e9cd51ef0c71fb3f9ea288b8d548c941988f8a8'),
  ('ur.jalandhry', 20, 23, 2371, 'تاکہ ہم تمہیں اپنے نشانات عظیم دکھائیں', NULL, NULL, 'f7062722205a3caa65b792f6ceadf0e666837aa1935856207b4d84037a4a9ae3'),
  ('ur.jalandhry', 20, 24, 2372, 'تم فرعون کے پاس جاؤ (کہ) وہ سرکش ہو رہا ہے', NULL, NULL, 'edb6467f2a58343aa313a8eb696bbcfeddca5cd58744302bb75396bdea6c8636'),
  ('ur.jalandhry', 20, 25, 2373, 'کہا میرے پروردگار (اس کام کے لئے) میرا سینہ کھول دے', NULL, NULL, '8c5e115a498c8df46a2d346bc010326f744764e1877d3d5bf59c76991e69f63a'),
  ('ur.jalandhry', 20, 26, 2374, 'اور میرا کام آسان کردے', NULL, NULL, 'fc0c65259ae79b6a8cc6d1a1d476d8bd64bd29c5f61e0323f4af7e867c6955b9'),
  ('ur.jalandhry', 20, 27, 2375, 'اور میری زبان کی گرہ کھول دے', NULL, NULL, '83977cda0b1e4ec5a3369bb82693ab3f5574bd59ba46d1ebcddbdebecbbe079b'),
  ('ur.jalandhry', 20, 28, 2376, 'تاکہ وہ بات سمجھ لیں', NULL, NULL, '33b5b49f769f66e168d4ca3bf6f0511e6f74895b068d8f64d6ef29bb31810f86'),
  ('ur.jalandhry', 20, 29, 2377, 'اور میرے گھر والوں میں سے (ایک کو) میرا وزیر (یعنی مددگار) مقرر فرما', NULL, NULL, '637d292ef33b512a47141cb9b43854e2a02c4a014c2bcf8ded7e5eca544d041a'),
  ('ur.jalandhry', 20, 30, 2378, '(یعنی) میرے بھائی ہارون کو', NULL, NULL, '2e624215518b40245223d7e112d52032c4ac9d09737b7bdb8e145ef38fc4adff'),
  ('ur.jalandhry', 20, 31, 2379, 'اس سے میری قوت کو مضبوط فرما', NULL, NULL, '91966c7294a0236475088a7b02ce8986afb7f4434808d6cbc891eb740ff24b00'),
  ('ur.jalandhry', 20, 32, 2380, 'اور اسے میرے کام میں شریک کر', NULL, NULL, 'e6d199f308b8770bc31e892902ed122f298c59d0f9077cb41f149364ee85edd6'),
  ('ur.jalandhry', 20, 33, 2381, 'تاکہ ہم تیری بہت سی تسبیح کریں', NULL, NULL, '0e2b128f83322623e4b361d3fe907048802ef760e92d8c48f93d4e5d08dc9062'),
  ('ur.jalandhry', 20, 34, 2382, 'اور تجھے کثرت سے یاد کریں', NULL, NULL, 'ae4e35b462ae4f516bdfb981474f5f1bd6267b190808769f8f075290a7fd4cc5'),
  ('ur.jalandhry', 20, 35, 2383, 'تو ہم کو (ہر حال میں) دیکھ رہا ہے', NULL, NULL, '2573ce341a27e66fbf0b88ffc691bdf0de476c3c58194a9616b55f055270caea'),
  ('ur.jalandhry', 20, 36, 2384, 'فرمایا موسیٰ تمہاری دعا قبول کی گئی', NULL, NULL, 'f9e26191292a5c8168c30f37b96324b0b00fb7a1ceae5f9248fc22fdad801d04'),
  ('ur.jalandhry', 20, 37, 2385, 'اور ہم نے تم پر ایک بار اور بھی احسان کیا تھا', NULL, NULL, '6756ad4da01d524f6d1e601a653a77b1110eeaa5259a3c78fa83c8ab98c98524'),
  ('ur.jalandhry', 20, 38, 2386, 'جب ہم نے تمہاری والدہ کو الہام کیا تھا جو تمہیں بتایا جاتا ہے', NULL, NULL, '2916d793843dd44d54d04a704cb54577679dbe5751fe440eda2ec3050d1ac7f1'),
  ('ur.jalandhry', 20, 39, 2387, '(وہ یہ تھا) کہ اسے (یعنی موسیٰ کو) صندوق میں رکھو پھر اس (صندوق) کو دریا میں ڈال دو تو دریا اسے کنارے پر ڈال دے گا (اور) میرا اور اس کا دشمن اسے اٹھا لے گا۔ اور (موسیٰ) میں نے تم پر اپنی طرف سے محبت ڈال دی ہے (اس لئے کہ تم پر مہربانی کی جائے) اور اس لئے کہ تم میرے سامنے پرورش پاؤ', NULL, NULL, '8187bd09759830c826195c10b659d71c0814ee976b8a9553ce26fdf6e5397f36'),
  ('ur.jalandhry', 20, 40, 2388, 'جب تمہاری بہن (فرعون کے ہاں) گئی اور کہنے لگی کہ میں تمہیں ایسا شخص بتاؤں جو اس کو پالے۔ تو (اس طریق سے) ہم نے تم کو تمہاری ماں کے پاس پہنچا دیا تاکہ ان کی آنکھیں ٹھنڈی ہوں اور وہ رنج نہ کریں۔ اور تم نے ایک شخص کو مار ڈالا تو ہم نے تم کو غم سے مخلصی دی اور ہم نے تمہاری (کئی بار) آزمائش کی۔ پھر تم کئی سال اہل مدین میں ٹھہرے رہے۔ پھر اے موسیٰ تم (قابلیت رسالت کے) اندازے پر آ پہنچے', NULL, NULL, '8fa82025b34a43bd009b2494bca974c055adf7a4a6408290295e5b2de0ef8898'),
  ('ur.jalandhry', 20, 41, 2389, 'اور میں نے تم کو اپنے (کام کے) لئے بنایا ہے', NULL, NULL, '394de2332e56e918e56865ef8000e6255ed32ddf075f9a7fd5f9dc352abe879c'),
  ('ur.jalandhry', 20, 42, 2390, 'تو تم اور تمہارا بھائی دونوں ہماری نشانیاں لے کر جاؤ اور میری یاد میں سستی نہ کرنا', NULL, NULL, 'c321087740950ab5156a36cebe9c6a319781602faf1517d509cc5eea2cb0000c'),
  ('ur.jalandhry', 20, 43, 2391, 'دونوں فرعون کے پاس جاؤ وہ سرکش ہو رہا ہے', NULL, NULL, 'ade7f03c05286ebd744b698c8845b615215c06e7c26e2b2545d7219e94821440'),
  ('ur.jalandhry', 20, 44, 2392, 'اور اس سے نرمی سے بات کرنا شاید وہ غور کرے یا ڈر جائے', NULL, NULL, '012c12851561244944cf3c401725c5777f484bb5feb8dccd52534a175f3e9f91'),
  ('ur.jalandhry', 20, 45, 2393, 'دونوں کہنے لگے کہ ہمارے پروردگار ہمیں خوف ہے کہ ہم پر تعدی کرنے لگے یا زیادہ سرکش ہوجائے', NULL, NULL, '8c172b3163d4bf072672ae2332ac5dbdf16d4b8c2dd155fa81cd38d7efa4ffa8'),
  ('ur.jalandhry', 20, 46, 2394, 'خدا نے فرمایا کہ ڈرو مت میں تمہارے ساتھ ہوں (اور) سنتا اور دیکھتا ہوں', NULL, NULL, '74c15deaa41fa8d3f00707fb3a2649ea25b20dbe55f6d139dddebf398a54d47b'),
  ('ur.jalandhry', 20, 47, 2395, '(اچھا) تو اس کے پاس جاؤ اور کہو کہ ہم آپ کے پروردگار کے بھیجے ہوئے ہیں تو بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیجیئے۔ اور انہیں عذاب نہ کیجیئے۔ ہم آپ کے پاس آپ کے پروردگار کی طرف سے نشانی لے کر آئے ہیں۔ اور جو ہدایت کی بات مانے اس کو سلامتی ہو', NULL, NULL, 'da4385e7a764a7f0e55d0472e1395c6cba5bedd9c4d72df3096d618d371f2824'),
  ('ur.jalandhry', 20, 48, 2396, 'ہماری طرف یہ وحی آئی ہے کہ جو جھٹلائے اور منہ پھیرے اس کے لئے عذاب (تیار) ہے', NULL, NULL, '398645cfc4b72eb8fa3c8295d4c815d338f4c7989336da4022fe425cb1f780de'),
  ('ur.jalandhry', 20, 49, 2397, '(غرض موسیٰ اور ہارون فرعون کے پاس گئے) اس نے کہا کہ موسیٰ تمہارا پروردگار کون ہے؟', NULL, NULL, 'de52968293d542482f6d315f4e52ceccce4ad852d69a16d02599f5588bf8539f'),
  ('ur.jalandhry', 20, 50, 2398, 'کہا کہ ہمارا پروردگار وہ ہے جس نے ہر چیز کو اس کی شکل وصورت بخشی پھر راہ دکھائی', NULL, NULL, '3445f95468c70dbdb5122b65eb5cf7e02a39fd8212375feb3f97591ee95ed429'),
  ('ur.jalandhry', 20, 51, 2399, 'کہا تو پہلی جماعتوں کا کیا حال؟', NULL, NULL, '58ff4315b21fee1d0418e160f727d1b607073cf2db7ed9d7e750765d9c31e495'),
  ('ur.jalandhry', 20, 52, 2400, 'کہا کہ ان کا علم میرے پروردگار کو ہے (جو) کتاب میں (لکھا ہوا ہے) ۔ میرا پروردگار نہ چوکتا ہے نہ بھولتا ہے', NULL, NULL, 'b5aa23b667aa68167bd217046b8201af2c9d29ef76fc79cee7c7200627c92828')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
