INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 20, 53, 2401, 'وہ (وہی تو ہے) جس نے تم لوگوں کے لئے زمین کو فرش بنایا اور اس میں تمہارے لئے رستے جاری کئے اور آسمان سے پانی برسایا۔ پھر اس سے انواع واقسام کی مختلف روئیدگیاں پیدا کیں', NULL, NULL, '05e3db4c6210ea3185cbf15e62c00941d7cb790787e9d997c4e14c59efec84a8'),
  ('ur.jalandhry', 20, 54, 2402, 'کہ (خود بھی) کھاؤ اور اپنے چارپایوں کو بھی چراؤ۔ بےشک ان (باتوں) میں عقل والوں کے لئے (بہت سی) نشانیاں ہیں', NULL, NULL, 'f673a81d2dd3045e7152bf1af717f8759d137cbe7d6dce76965de6b42bdc7e42'),
  ('ur.jalandhry', 20, 55, 2403, 'اسی (زمین) سے ہم تم کو پیدا کیا اور اسی میں تمہیں لوٹائیں گے اور اسی سے دوسری دفعہ نکالیں گے', NULL, NULL, 'afbcf7e76410e848af7267f90b1047b56247eaa698978a07e46a00d1bcb6f92d'),
  ('ur.jalandhry', 20, 56, 2404, 'اور ہم نے فرعون کو اپنی سب نشانیاں دکھائیں مگر وہ تکذیب وانکار ہی کرتا رہا', NULL, NULL, 'e0943fc66ab4124e576ee9977b0c35c08355a45826974fa1cc8c9ff3971bca9f'),
  ('ur.jalandhry', 20, 57, 2405, 'کہنے لگا کہ موسیٰ تم ہمارے پاس اس لئے آئے ہو کہ اپنے جادو (کے زور) سے ہمیں ہمارے ملک سے نکال دو', NULL, NULL, '13ae5ec3591489e8b29a5b84da9252005b6903cc29ae5529ec6738b95ff0a16a'),
  ('ur.jalandhry', 20, 58, 2406, 'تو ہم بھی تمہارے مقابل ایسا ہی جادو لائیں گے تو ہمارے اور اپنے درمیان ایک وقت مقرر کر لو کہ نہ تو ہم اس کے خلاف کریں اور نہ تم (اور یہ مقابلہ) ایک ہموار میدان میں (ہوگا)', NULL, NULL, '458cedc3a4fab41437ae12ea8e75d320731506b5b929440e7b803ee91b9fd91e'),
  ('ur.jalandhry', 20, 59, 2407, 'موسیٰ نے کہا آپ کے لئے (مقابلے کا) دن نو روز (مقرر کیا جاتا ہے) اور یہ کہ لوگ اس دن چاشت کے وقت اکھٹے ہوجائیں', NULL, NULL, '3705978941444274ee15f94cf58a51f0cfb6ed7c73800f212326935e253fd680'),
  ('ur.jalandhry', 20, 60, 2408, 'تو فرعون لوٹ گیا اور اپنے سامان جمع کرکے پھر آیا', NULL, NULL, 'aa23cf47a417badcd139eb8d60b3c3f9be2e6af79337741c222f4aa955808d9f'),
  ('ur.jalandhry', 20, 61, 2409, 'موسیٰ نے ان (جادوگروں) سے کہا کہ ہائے تمہاری کمبختی۔ خدا پر جھوٹ افتراء نہ کرو کہ وہ تمہیں عذاب سے فنا کردے گا اور جس نے افتراء کیا وہ نامراد رہا', NULL, NULL, 'ff654663e52c3758987982a13fd021cd91dbb653471aac86f244f8d95d298105'),
  ('ur.jalandhry', 20, 62, 2410, 'تو وہ باہم اپنے معاملے میں جھگڑانے اور چپکے چپکے سرگوشی کرنے لگے', NULL, NULL, '0e1e85f065565b87ec590ff223a4e78782f3f1ee8c67a423e4096d3b180d3fae'),
  ('ur.jalandhry', 20, 63, 2411, 'کہنے لگے یہ دونوں جادوگر ہیں چاہتے ہیں کہ اپنے جادو (کے زور) سے تم کو تمہارے ملک سے نکل دیں اور تمہارے شائستہ مذہب کو نابود کردیں', NULL, NULL, '558ec58eae133360171e9cdf4a228efa04730a1bbefe18d85abb30b1607e1240'),
  ('ur.jalandhry', 20, 64, 2412, 'تو تم (جادو کا) سامان اکھٹا کرلو اور پھر قطار باندھ کر آؤ۔ آج جو غالب رہا وہی کامیاب ہوا', NULL, NULL, 'a33896ae09d7728be49bd682c12979bacefa441e1178252bf825916036c58e4a'),
  ('ur.jalandhry', 20, 65, 2413, 'بولے کہ موسیٰ یا تم (اپنی چیز) ڈالو یا ہم (اپنی چیزیں) پہلے ڈالتے ہیں', NULL, NULL, '8412e7c027c760da217c89d0061011a1207c26a0c9e54ee461ff235b915cf86e'),
  ('ur.jalandhry', 20, 66, 2414, 'موسیٰ نے کہا نہیں تم ہی ڈالو۔ (جب انہوں نے چیزیں ڈالیں) تو ناگہاں ان کی رسیاں اور لاٹھیاں موسی کے خیال میں ایسی آنے لگیں کہ وہ (میدان) میں ادھر اُدھر دوڑ رہی ہیں', NULL, NULL, '6cab411ab367641e8a17b32f8d8466f1631b618f536338947509953692e89d93'),
  ('ur.jalandhry', 20, 67, 2415, '(اُس وقت) موسیٰ نے اپنے دل میں خوف معلوم کیا', NULL, NULL, '11fdcfce48751391db6bce373327b64ecb013ac3d8bb9e71cd36d6bef17ae2b4'),
  ('ur.jalandhry', 20, 68, 2416, 'ہم نے کہا خوف نہ کرو بلاشبہ تم ہی غالب ہو', NULL, NULL, 'b514a388845d181581c19c423ec6a6c129e33ca94675bdaeb21f6380675d5e83'),
  ('ur.jalandhry', 20, 69, 2417, 'اور جو چیز (یعنی لاٹھی) تمہارے داہنے ہاتھ میں ہے اسے ڈال دو کہ جو کچھ انہوں نے بنایا ہے اس کو نگل جائے گی۔ جو کچھ انہوں نے بنایا ہے (یہ تو) جادوگروں کے ہتھکنڈے ہیں اور جادوگر جہاں جائے فلاح نہیں پائے گا', NULL, NULL, 'e79059433e75a908c37cb14de22731a48be36c321fb275c45a84797167fdd81e'),
  ('ur.jalandhry', 20, 70, 2418, '(القصہ یوں ہی ہوا) تو جادوگر سجدے میں گر پڑے (اور) کہنے لگے کہ ہم موسیٰ اور ہارون کے پروردگار پر ایمان لائے', NULL, NULL, 'be3d36aa4e5a6c6cad176e79f2fa10958aa4c45f3cf740e789a74c52f4000d38'),
  ('ur.jalandhry', 20, 71, 2419, '(فرعون) بولا کہ پیشتر اس کے میں تمہیں اجازت دوں تم اس پر ایمان لے آئے۔ بےشک وہ تمہارا بڑا (یعنی استاد) ہے جس نے تم کو جادو سکھایا ہے۔ سو میں تمہارے ہاتھ اور پاؤں (جانب) خلاف سے کٹوا دوں گا اور کھجور کے تنوں پر سولی چڑھوا دوں گا (اس وقت) تم کو معلوم ہوگا کہ ہم میں سے کس کا عذاب زیادہ سخت اور دیر تک رہنے والا ہے', NULL, NULL, '8ac86ebffe733d857167c757a3a1715e829f6e082b0ce41ba665b9aac9594ff9'),
  ('ur.jalandhry', 20, 72, 2420, 'انہوں نے کہا جو دلائل ہمارے پاس آگئے ہیں ان پر اور جس نے ہم کو پیدا ہے اس پر ہم آپ کو ہرگز ترجیح نہیں دیں گے تو آپ کو جو حکم دینا ہو دے دیجیئے۔ اور آپ (جو) حکم دے سکتے ہیں وہ صرف اسی دنیا کی زندگی میں (دے سکتے ہیں)', NULL, NULL, '50381926f1b3a0945096949ce4bfabd24f48d90d81e38b59dd59970cad007288'),
  ('ur.jalandhry', 20, 73, 2421, 'ہم اپنے پروردگار پر ایمان لے آئے تاکہ وہ ہمارے گناہوں کو معاف کرے اور (اسے بھی) جو آپ نے ہم سے زبردستی جادو کرایا۔ اور خدا بہتر اور باقی رہنے والا ہے', NULL, NULL, 'dda33091c691c3b6a8b69072b64aa7a5bae450c675228cadbfbd3c524723cd7d'),
  ('ur.jalandhry', 20, 74, 2422, 'جو شخص اپنے پروردگار کے پاس گنہگار ہو کر آئے گا تو اس کے لئے جہنم ہے۔ جس میں نہ مرے گا نہ جیئے گا', NULL, NULL, '0aa2bb957ffe4cd2fcb5d6ddb4a30fdc569a4317fd468ead1490ec75703e6192'),
  ('ur.jalandhry', 20, 75, 2423, 'اور جو اس کے روبرو ایماندار ہو کر آئے گا اور عمل بھی نیک کئے ہوں گے تو ایسے لوگوں کے لئے اونچے اونچے درجے ہیں', NULL, NULL, '49cfd8d9e75f19ec096c832f64f001a642ca37825eab66cbf681fd1c79edda20'),
  ('ur.jalandhry', 20, 76, 2424, '(یعنی) ہمیشہ رہنے کے باغ جن کے نیچے نہریں بہہ رہی ہیں۔ ہمیشہ ان میں رہیں گے۔ اور یہ اس شخص کا بدلہ ہے جو پاک ہوا', NULL, NULL, '981a9663001841430a1ce476c86f782ecefd3028b946c26ee9b47686a20dc5e4'),
  ('ur.jalandhry', 20, 77, 2425, 'اور ہم نے موسیٰ کی طرف وحی بھیجی کہ ہمارے بندوں کو راتوں رات نکال لے جاؤ پھر ان کے لئے دریا میں (لاٹھی مار کر) خشک رستہ بنا دو پھر تم کو نہ تو (فرعون کے) آپکڑنے کا خوف ہوگا اور نہ (غرق ہونے کا) ڈر', NULL, NULL, '01627bf920b82052071b22994f154d36f9424a821d768ad1eec53cad045648a8'),
  ('ur.jalandhry', 20, 78, 2426, 'پھر فرعون نے اپنے لشکر کے ساتھ ان کا تعاقب کیا تو دریا (کی موجوں) نے ان پر چڑھ کر انہیں ڈھانک لیا (یعنی ڈبو دیا)', NULL, NULL, '536f094d50d401ae687ff7dab1cff458a09c0aa114cf2ee3d33b0a5437ee1538'),
  ('ur.jalandhry', 20, 79, 2427, 'اور فرعون نے اپنی قوم کو گمراہ کردیا اور سیدھے رستے پر نہ ڈالا', NULL, NULL, 'ce2a9e3e77f8427a6a62ca3ec1e5d4149e145b01ae5bcd29620a2c88adb7171e'),
  ('ur.jalandhry', 20, 80, 2428, 'اے آل یعقوب ہم نے تم کو تمہارے دشمن سے نجات دی اور تورات دینے کے لئے تم سے کوہ طور کی داہنی طرف مقرر کی اور تم پر من اور سلویٰ نازل کیا', NULL, NULL, '54d9793eff039605911da331ec3a3eda662b801172e286171ac15769e1e2602c'),
  ('ur.jalandhry', 20, 81, 2429, '(اور حکم دیا کہ) جو پاکیزہ چیزیں ہم نے تم کو دی ہیں ان کو کھاؤ۔ اور اس میں حد سے نہ نکلنا۔ ورنہ تم پر میرا غضب نازل ہوگا۔ اور جس پر میرا غضب نازل ہوا وہ ہلاک ہوگیا', NULL, NULL, 'c70f1ffcb9587294576e59f01e6f806c9fef5e19a970fab1507aec3e75250054'),
  ('ur.jalandhry', 20, 82, 2430, 'اور جو توبہ کرے اور ایمان لائے اور عمل نیک کرے پھر سیدھے رستے چلے اس کو میں بخش دینے والا ہوں', NULL, NULL, '827a67cad635cd76e2c3b530ca4eb0c966a45e1ac4b5318dc33b9eee64445c05'),
  ('ur.jalandhry', 20, 83, 2431, 'اور اے موسیٰ تم نے اپنی قوم سے (آگے چلے آنے میں) کیوں جلدی کی', NULL, NULL, 'b246d9a71b6c06577c806eb844d68a364b70600f8a1cf7c3a497d7cba2d23fc0'),
  ('ur.jalandhry', 20, 84, 2432, 'کہا وہ میرے پیچھے (آ رہے) ہیں اور اے پروردگار میں نے تیری طرف (آنے کی) جلدی اس لئے کی کہ تو خوش ہو', NULL, NULL, '840242b6efd63723464e5877ebc57b4f28dc66c1a0856f3e038d1090f5f95a43'),
  ('ur.jalandhry', 20, 85, 2433, 'فرمایا کہ ہم نے تمہاری قوم کو تمہارے بعد آزمائش میں ڈال دیا ہے اور سامری نے ان کو بہکا دیا ہے', NULL, NULL, '3ebdb6d4dcac8132276469fb0af9bcc27b64fe9ff65c2fe03cf43f377ffe28fe'),
  ('ur.jalandhry', 20, 86, 2434, 'اور موسیٰ غصّے اور غم کی حالت میں اپنی قوم کے پاس واپس آئے (اور) کہنے لگے کہ اے قوم کیا تمہارے پروردگار نے تم سے ایک اچھا وعدہ نہیں کیا تھا؟ کیا (میری جدائی کی) مدت تمہیں دراز (معلوم) ہوئی یا تم نے چاہا کہ تم پر تمہارے پروردگار کی طرف سے غضب نازل ہو۔ اور (اس لئے) تم نے مجھ سے جو وعدہ کیا تھا (اس کے) خلاف کیا', NULL, NULL, '52aa6f95bcf8b383befeb93af209d94e620543d46412b6688a49f6086500a7a3'),
  ('ur.jalandhry', 20, 87, 2435, 'وہ کہنے لگے کہ ہم نے اپنے اختیار سے تم سے وعدہ خلاف نہیں کیا۔ بلکہ ہم لوگوں کے زیوروں کا بوجھ اٹھائے ہوئے تھے۔ پھر ہم نے اس کو (آگ میں) ڈال دیا اور اسی طرح سامری نے ڈال دیا', NULL, NULL, '3ac41d073570861307765ced4903af0e85009c77ecc98b9d3b0e668793dec473'),
  ('ur.jalandhry', 20, 88, 2436, 'تو اس نے ان کے لئے ایک بچھڑا بنا دیا (یعنی اس کا) قالب جس کی آواز گائے کی سی تھی۔ تو لوگ کہنے لگے کہ یہی تمہارا معبود ہے اور موسیٰ کا بھی معبود ہے۔ مگر وہ بھول گئے ہیں', NULL, NULL, 'b354cfb7c4deab2612d306937f6303920827ec000cca29ccb8ae53057db5d8ac'),
  ('ur.jalandhry', 20, 89, 2437, 'کیا یہ لوگ نہیں دیکھتے کہ وہ ان کی کسی بات کا جواب نہیں دیتا۔ اور نہ ان کے نقصان اور نفع کا کچھ اختیار رکھتا ہے', NULL, NULL, '30441904b98be3c714031c329cf6c27ec7766db2f4b1e4c3b9568a8f1500df86'),
  ('ur.jalandhry', 20, 90, 2438, 'اور ہارون نے ان سے پہلے ہی کہہ دیا تھا کہ لوگو اس سے صرف تمہاری آزمائش کی گئی ہے۔ اور تمہارا پروردگار تو خدا ہے تو میری پیروی کرو اور میرا کہا مانو', NULL, NULL, '9e6c718f19218a4f24c51ecf0d720a79431c951625b7e744181a96bc493b7e1a'),
  ('ur.jalandhry', 20, 91, 2439, 'وہ کہنے لگے کہ جب تک موسیٰ ہمارے پاس واپس نہ آئیں ہم تو اس کی پوجا پر قائم رہیں گے', NULL, NULL, '96b6aab2a634f75376d1e070000ec66d4df2f2cfe38ee1bdc4e510f60c007d92'),
  ('ur.jalandhry', 20, 92, 2440, '(پھر موسیٰ نے ہارون سے) کہا کہ ہارون جب تم نے ان کو دیکھا تھا کہ گمراہ ہو رہے ہیں تو تم کو کس چیز نے روکا', NULL, NULL, '906ce518e3ddd983bce5a3b73506589de35ef41ff325fa49bbad7e140f9e7c0f'),
  ('ur.jalandhry', 20, 93, 2441, '(یعنی) اس بات سے کہ تم میرے پیچھے چلے آؤ۔ بھلا تم نے میرے حکم کے خلاف (کیوں) کیا؟', NULL, NULL, 'c84c73707c7f7952aefef464db3da53c6c52d8d666cf2961b2f2974a700ccdb5'),
  ('ur.jalandhry', 20, 94, 2442, 'کہنے لگے کہ بھائی میری ڈاڑھی اور سر (کے بالوں) کو نہ پکڑیئے۔ میں تو اس سے ڈرا کہ آپ یہ نہ کہیں کہ تم نے بنی اسرائیل میں تفرقہ ڈال دیا اور میری بات کو ملحوظ نہ رکھا', NULL, NULL, 'c8f48520dca4c4ed672ef5217b74d1e2f3ce26618d423a39592032fe66f0b15c'),
  ('ur.jalandhry', 20, 95, 2443, 'پھر (سامری سے) کہنے لگے کہ سامری تیرا کیا حال ہے؟', NULL, NULL, 'e51bc13d891e668c78782ddff3f7e9c10e89351ea200d504f2f7107fa8d59fe7'),
  ('ur.jalandhry', 20, 96, 2444, 'اس نے کہا کہ میں نے ایسی چیز دیکھی جو اوروں نے نہیں دیکھی تو میں نے فرشتے کے نقش پا سے (مٹی کی) ایک مٹھی بھر لی۔ پھر اس کو (بچھڑے کے قالب میں) ڈال دیا اور مجھے میرے جی نے (اس کام کو) اچھا بتایا', NULL, NULL, '0364fec41e1027c346809d9c422264895b93abf0e138b1dddf7f429f7589f8e3'),
  ('ur.jalandhry', 20, 97, 2445, '(موسیٰ نے) کہا جا تجھ کو دنیا کی زندگی میں یہ (سزا) ہے کہ کہتا رہے کہ مجھ کو ہاتھ نہ لگانا اور تیرے لئے ایک اور وعدہ ہے (یعنی عذاب کا) جو تجھ سے ٹل نہ سکے گا اور جس معبود (کی پوجا) پر تو (قائم و) معتکف تھا اس کو دیکھ۔ ہم اسے جلادیں گے پھر اس (کی راکھ) کو اُڑا کر دریا میں بکھیر دیں گے', NULL, NULL, 'c618d69e5d07f790fefa634711d3a6fc64c8a72795adb7afac3811ed8ea8bd50'),
  ('ur.jalandhry', 20, 98, 2446, 'تمہارا معبود خدا ہی ہے جس کے سوا کوئی معبود نہیں۔ اس کا علم ہر چیز پر محیط ہے', NULL, NULL, 'aef8455a66a48c7d0b5fcb0827d531b51cea5252016df4efe544b43c76ce6fc9'),
  ('ur.jalandhry', 20, 99, 2447, 'اس طرح پر ہم تم سے وہ حالات بیان کرتے ہیں جو گذر چکے ہیں۔ اور ہم نے تمہیں اپنے پاس سے نصیحت (کی کتاب) عطا فرمائی ہے', NULL, NULL, '00fee81a0922af2786f6d1046856fe67962c41e006f7df4123e70cbf9e76c56e'),
  ('ur.jalandhry', 20, 100, 2448, 'جو شخص اس سے منہ پھیرے گا وہ قیامت کے دن (گناہ کا) بوجھ اُٹھائے گا', NULL, NULL, '3bb68be076d86543f4560caefdc4e955e275525e846bfb6d9cf5c7320b63fff3'),
  ('ur.jalandhry', 20, 101, 2449, '(ایسے لوگ) ہمیشہ اس (عذاب) میں (مبتلا) رہیں گے اور یہ بوجھ قیامت کے روز ان کے لئے برا ہے', NULL, NULL, '015ccb9ff106517dccd2d6a073816cb45116097d5f1c387ad1c273d0046d7786'),
  ('ur.jalandhry', 20, 102, 2450, 'جس روز صور پھونکا جائے گا اور ہم گنہگاروں کو اکھٹا کریں گے اور ان کی آنکھیں نیلی نیلی ہوں گی', NULL, NULL, '63da5625e09add415ecb6e800ef3af8ca149488303229462ecc0403c56fcb86b'),
  ('ur.jalandhry', 20, 103, 2451, '(تو) وہ آپس میں آہستہ آہستہ کہیں گے کہ تم (دنیا میں) صرف دس ہی دن رہے ہو', NULL, NULL, '580c3314d10f748ff32c7bc933e141a16208c69d41cdfef49c145b356223b276'),
  ('ur.jalandhry', 20, 104, 2452, 'جو باتیں یہ کریں گے ہم خوب جانتے ہیں۔ اس وقت ان میں سب سے اچھی راہ والا (یعنی عاقل وہوشمند) کہے گا کہ (نہیں بلکہ) صرف ایک ہی روز ٹھہرے ہو', NULL, NULL, '1e87687366ed251cfb8528211cb1584c891100ec8387784049734b5e2811710a'),
  ('ur.jalandhry', 20, 105, 2453, 'اور تم سے پہاڑوں کے بارے میں دریافت کرتے ہیں۔ کہہ دو کہ خدا ان کو اُڑا کر بکھیر دے گا', NULL, NULL, 'a8dfda40d4feebf7cbea3343cbbbc1a103d30358ff9acb0672d93836341c38b3'),
  ('ur.jalandhry', 20, 106, 2454, 'اور زمین کو ہموار میدان کر چھوڑے گا', NULL, NULL, '477ad9501ff2a1cf5f251a48105657703ed1c09b508ff1a07d4bbada1de006d5'),
  ('ur.jalandhry', 20, 107, 2455, 'جس میں نہ تم کجی (اور پستی) دیکھو گے نہ ٹیلا (اور بلندی)', NULL, NULL, 'a3d8786f89c01cc5b7203a62106916e53f5a48428922701b5cc42ba1f0fc2fb5'),
  ('ur.jalandhry', 20, 108, 2456, 'اس روز لوگ ایک پکارنے والے کے پیچھے چلیں گے اور اس کی پیروی سے انحراف نہ کرسکیں گے اور خدا کے سامنے آوازیں پست ہوجائیں گی تو تم آواز خفی کے سوا کوئی آواز نہ سنو گے', NULL, NULL, '42285ac14881938ec3ed682ebc273c93a6c4cff43342ef699950c529a6d3a280'),
  ('ur.jalandhry', 20, 109, 2457, 'اس روز (کسی کی) سفارش کچھ فائدہ نہ دے گی مگر اس شخص کی جسے خدا اجازت دے اور اس کی بات کو پسند فرمائے', NULL, NULL, '8b2ab1ea6f2c65ea112208335ec94443e05481311f81e828eb6dd97f8a0190aa'),
  ('ur.jalandhry', 20, 110, 2458, 'جو کچھ ان کے آگے ہے اور کچھ ان کے پیچھے ہے وہ اس کو جانتا ہے اور وہ (اپنے) علم سے خدا (کے علم) پر احاطہ نہیں کرسکتے', NULL, NULL, 'abb3d7ae243094cc8b7a8870e2f75c96c4a8d5a07718f947f8ea5795d370acae'),
  ('ur.jalandhry', 20, 111, 2459, 'اور اس زندہ و قائم کے رو برو منہ نیچے ہوجائیں گے۔ اور جس نے ظلم کا بوجھ اٹھایا وہ نامراد رہا', NULL, NULL, '44a7bdef392e50b56d7f22722e4f2a9ec6606a504b130a62fc9865b939ee02a3'),
  ('ur.jalandhry', 20, 112, 2460, 'اور جو نیک کام کرے گا اور مومن بھی ہوگا تو اس کو نہ ظلم کا خوف ہوگا اور نہ نقصان کا', NULL, NULL, '1dc9543a08fe7130e5945b4eefbc9dddcd3e630d0d3820ad9d6add00243813b1'),
  ('ur.jalandhry', 20, 113, 2461, 'اور ہم نے اس کو اسی طرح کا قرآن عربی نازل کیا ہے اور اس میں طرح طرح کے ڈراوے بیان کردیئے ہیں تاکہ لوگ پرہیزگار بنیں یا خدا ان کے لئے نصیحت پیدا کردے', NULL, NULL, '5f400911dbe2ba4a575019fa8aeec12d2ebf98af4948e1cbe502652ff896a65f'),
  ('ur.jalandhry', 20, 114, 2462, 'تو خدا جو سچا بادشاہ ہے عالی قدر ہے۔ اور قرآن کی وحی جو تمہاری طرف بھیجی جاتی ہے اس کے پورا ہونے سے پہلے قرآن کے (پڑھنے کے) لئے جلدی نہ کیا کرو اور دعا کرو کہ میرے پروردگار مجھے اور زیادہ علم دے', NULL, NULL, '8ded65032383656b7f574318c8733121ea51c345b192a51fa01a023cdfec7ed9'),
  ('ur.jalandhry', 20, 115, 2463, 'اور ہم نے پہلے آدم سے عہد لیا تھا مگر وہ (اسے) بھول گئے اور ہم نے ان میں صبر وثبات نہ دیکھا', NULL, NULL, 'f4bb4ce62ff7e673e3691f931ebc8961610266f1a4e0bbfb354ebe2451208d96'),
  ('ur.jalandhry', 20, 116, 2464, 'اور جب ہم نے فرشتوں سے کہا کہ آدم کے آگے سجدہ کرو تو سب سجدے میں گر پڑے مگر ابلیس نے انکار کیا', NULL, NULL, '2fde383d933825caf466a7ca60527ab8196189dae805dfcb763d47de5e7bf035'),
  ('ur.jalandhry', 20, 117, 2465, 'ہم نے فرمایا کہ آدم یہ تمہارا اور تمہاری بیوی کا دشمن ہے تو یہ کہیں تم دونوں کو بہشت سے نکلوا نہ دے۔ پھر تم تکلیف میں پڑجاؤ', NULL, NULL, 'f3cf9b9e94d872d4d1a1c7c4f8ef111a8981736c19b34a7ad88e8cf8d576c731'),
  ('ur.jalandhry', 20, 118, 2466, 'یہاں تم کو یہ (آسائش) ہوگی کہ نہ بھوکے رہو نہ ننگے', NULL, NULL, '7751687ab5aaa7c1129bc7bdeedc7f64d3d311db4691b5ee1d6345d8a656cde4'),
  ('ur.jalandhry', 20, 119, 2467, 'اور یہ کہ نہ پیاسے رہو اور نہ دھوپ کھاؤ', NULL, NULL, 'be928cb69cc56ec52b2cab564bac39174f69cad17f64b3189deb33d9d23922d1'),
  ('ur.jalandhry', 20, 120, 2468, 'تو شیطان نے ان کے دل میں وسوسہ ڈالا۔ (اور) کہا کہ آدم بھلا میں تم کو (ایسا) درخت بتاؤں (جو) ہمیشہ کی زندگی کا (ثمرہ دے) اور (ایسی) بادشاہت کہ کبھی زائل نہ ہو', NULL, NULL, '52403c0ef427e86bc4cdd703af20660337c7b382a05390ae8704f8bb1f86c046'),
  ('ur.jalandhry', 20, 121, 2469, 'تو دونوں نے اس درخت کا پھل کھا لیا تو ان پر ان کی شرمگاہیں ظاہر ہوگئیں اور وہ اپنے (بدنوں) پر بہشت کے پتّے چپکانے لگے۔ اور آدم نے اپنے پروردگار کے حکم خلاف کیا تو (وہ اپنے مطلوب سے) بےراہ ہو گئے', NULL, NULL, 'c331bb51b921fd41e433f0af4422721fa9068bf7b42729d8e9b5705fe8fed58d'),
  ('ur.jalandhry', 20, 122, 2470, 'پھر ان کے پروردگار نے ان کو نوازا تو ان پر مہربانی سے توجہ فرمائی اور سیدھی راہ بتائی', NULL, NULL, 'c9453d285fb178dd514818e5a349ada31735ecc3a4610f61d18104c44a997772'),
  ('ur.jalandhry', 20, 123, 2471, 'فرمایا کہ تم دونوں یہاں سے نیچے اتر جاؤ۔ تم میں بعض بعض کے دشمن (ہوں گے) پھر اگر میری طرف سے تمہارے پاس ہدایت آئے تو جو شخص میری ہدایت کی پیروی کرے گا وہ نہ گمراہ ہوگا اور نہ تکلیف میں پڑے گا', NULL, NULL, 'ad82a1bd3f3b479f814e4241c730cac4eea7df9050fcba459dabd809c19bee8b'),
  ('ur.jalandhry', 20, 124, 2472, 'اور جو میری نصیحت سے منہ پھیرے گا اس کی زندگی تنگ ہوجائے گی اور قیامت کو ہم اسے اندھا کرکے اٹھائیں گے', NULL, NULL, '563d12c9a10c216f9100127b5151076364ac396f887f1ba40c9a2ee99a002fd7'),
  ('ur.jalandhry', 20, 125, 2473, 'وہ کہے گا میرے پروردگار تو نے مجھے اندھا کرکے کیوں اٹھایا میں تو دیکھتا بھالتا تھا', NULL, NULL, 'ae2830681864ba4a5d48ac10166432601eb87acb401f7840fbb19e5b91770a4d'),
  ('ur.jalandhry', 20, 126, 2474, 'خدا فرمائے گا کہ ایسا ہی (چاہیئے تھا) تیرے پاس میری آیتیں آئیں تو تونے ان کو بھلا دیا۔ اسی طرح آج ہم تجھ کو بھلا دیں گے', NULL, NULL, 'eb6e29ddc4a1ea17b18f1d0fb6fc27924d1ce1db9d964fd9ca963e96bcdef815'),
  ('ur.jalandhry', 20, 127, 2475, 'اور جو شخص حد سے نکل جائے اور اپنے پروردگار کی آیتوں پر ایمان نہ لائے ہم اس کو ایسا ہی بدلہ دیتے ہیں۔ اور آخرت کا عذاب بہت سخت اور بہت دیر رہنے والا ہے', NULL, NULL, 'f92c0a4cd052bc766e50cfd03da676b96f0c081027134b6bcbd191609f328581'),
  ('ur.jalandhry', 20, 128, 2476, 'کیا یہ بات ان لوگوں کے لئے موجب ہدایت نہ ہوئی کہ ہم ان سے پہلے بہت سے لوگوں کو ہلاک کرچکے ہیں جن کے رہنے کے مقامات میں یہ چلتے پھرتے ہیں۔ عقل والوں کے لئے اس میں (بہت سی) نشانیاں ہیں', NULL, NULL, 'bef2ab74284bb07da275ee6e688122d89903c9bdbd168665b237b9d9abf74dfd'),
  ('ur.jalandhry', 20, 129, 2477, 'اور اگر ایک بات تمہارے پروردگار کی طرف سے پہلے صادر اور (جزائے اعمال کے لئے) ایک میعاد مقرر نہ ہوچکی ہوتی تو (نزول) عذاب لازم ہوجاتا', NULL, NULL, 'c40665287f24f4eecb2f4ea5eb604fc42ead75029bac94e1cb0f2a070489f8f8'),
  ('ur.jalandhry', 20, 130, 2478, 'پس جو کچھ یہ بکواس کرتے ہیں اس پر صبر کرو۔ اور سورج کے نکلنے سے پہلے اور اس کے غروب ہونے سے پہلے اپنے پروردگار کی تسبیح وتحمید کیا کرو۔ اور رات کی ساعات (اولین) میں بھی اس کی تسبیح کیا کرو اور دن کی اطراف (یعنی دوپہر کے قریب ظہر کے وقت بھی) تاکہ تم خوش ہوجاؤ', NULL, NULL, 'dff02e2f7a465060053aad0e3040debceeab528ade26e4e51ae06e9c1b72610f'),
  ('ur.jalandhry', 20, 131, 2479, 'اور کئی طرح کے لوگوں کو جو ہم نے دنیا کی زندگی میں آرائش کی چیزوں سے بہرہ مند کیا ہے تاکہ ان کی آزمائش کریں ان پر نگاہ نہ کرنا۔ اور تمہاری پروردگار کی (عطا فرمائی ہوئی) روزی بہت بہتر اور باقی رہنے والی ہے', NULL, NULL, '5b4060c5ca4a65a2e68e14d2222345a0fb8c6cfe0baeff2224739b7c4540cd9f'),
  ('ur.jalandhry', 20, 132, 2480, 'اور اپنے گھر والوں کو نماز کا حکم کرو اور اس پر قائم رہو۔ ہم تم سے روزی کے خواستگار نہیں۔ بلکہ تمہیں ہم روزی دیتے ہیں اور (نیک) انجام (اہل) تقویٰ کا ہے', NULL, NULL, '8f461326d2485cae83fe49d35afec719b42c3a642602c5db0e244696cb0683db'),
  ('ur.jalandhry', 20, 133, 2481, 'اور کہتے ہیں کہ یہ (پیغمبر) اپنے پروردگار کی طرف سے ہمارے پاس کوئی نشانی کیوں نہیں لاتے۔ کیا ان کے پاس پہلی کتابوں کی نشانی نہیں آئی؟', NULL, NULL, 'a883528546f68bd3202ead6fb44ef020b5ef81153e8e50200aabac07f78e0776'),
  ('ur.jalandhry', 20, 134, 2482, 'اور اگر ہم ان کو پیغمبر (کے بھیجنے) سے پیشتر کسی عذاب سے ہلاک کردیتے تو وہ کہتے کہ اے ہمارے پروردگار تو نے ہماری طرف کوئی پیغمبر کیوں نہ بھیجا کہ ہم ذلیل اور رسوا ہونے سے پہلے تیرے کلام (واحکام) کی پیروی کرتے', NULL, NULL, '69825330ce0c41056a51f9e19a87a18ca0f7035584236884e309fc2ccb07f083'),
  ('ur.jalandhry', 20, 135, 2483, 'کہہ دو کہ سب (نتائج اعمال) کے منتظر ہیں سو تم بھی منتظر رہو۔ عنقریب تم کو معلوم ہوجائے گا کہ (دین کے) سیدھے رستے پر چلنے والے کون ہیں اور (جنت کی طرف) راہ پانے والے کون ہیں (ہم یا تم)', NULL, NULL, 'a239a3ed272a02db7a8c97fdc6b13ffdddf0233990ec600d848e13a270e62d47'),
  ('ur.jalandhry', 21, 1, 2484, 'لوگوں کا حساب (اعمال کا وقت) نزدیک آپہنچا ہے اور وہ غفلت میں (پڑے اس سے) منہ پھیر رہے ہیں', NULL, NULL, 'af5f7a482048aef5871f57f09ed53514dcb114f5e72cff617b8aff08707bf0e9'),
  ('ur.jalandhry', 21, 2, 2485, 'ان کے پاس کوئی نئی نصیحت ان کے پروردگار کی طرف سے نہیں آتی مگر وہ اسے کھیلتے ہوئے سنتے ہیں', NULL, NULL, 'a47dc93937a8482834b321a5e7674411bd60f7f103bf9acd886a4623dfed674d'),
  ('ur.jalandhry', 21, 3, 2486, 'ان کے دل غفلت میں پڑے ہوئے ہیں اور ظالم لوگ (آپس میں) چپکے چپکے باتیں کرتے ہیں کہ یہ (شخص کچھ بھی) نہیں مگر تمہارے جیسا آدمی ہے۔ تو تم آنکھوں دیکھتے جادو (کی لپیٹ) میں کیوں آتے ہو', NULL, NULL, '29124b4d3f3c36c485320ec6c10b6e48bcaff14f238b4685e059b3f0641406f0'),
  ('ur.jalandhry', 21, 4, 2487, '(پیغمبر نے) کہا کہ جو بات آسمان اور زمین میں (کہی جاتی) ہے میرا پروردگار اسے جانتا ہے۔ اور وہ سننے والا (اور) جاننے والا ہے', NULL, NULL, 'e45b7e63889300df925136855bed9033f562305f0153ef50b4b07d6c2ae9da38'),
  ('ur.jalandhry', 21, 5, 2488, 'بلکہ (ظالم) کہنے لگے کہ (یہ قرآن) پریشان (باتیں ہیں جو) خواب (میں دیکھ لی) ہیں۔ (نہیں) بلکہ اس نے اس کو اپنی طرف سے بنا لیا ہے (نہیں) بلکہ (یہ شعر ہے جو اس) شاعر (کا نتیجہٴ طبع) ہے۔ تو جیسے پہلے (پیغمبر نشانیاں دے کر) بھیجے گئے تھے (اسی طرح) یہ بھی ہمارے پاس کوئی نشانی لائے', NULL, NULL, 'a94040fe25d143a445b8cb4bcfa6ce5a2f0f0befbaa3c6f73a3017a0dd72f687'),
  ('ur.jalandhry', 21, 6, 2489, 'ان سے پہلے جن بستیوں کو ہم نے ہلاک کیا وہ ایمان نہیں لاتی تھیں۔ تو کیا یہ ایمان لے آئیں گے', NULL, NULL, 'ea8888193cee8692d88675f46b860888dd83c486c533d858fa5c235418673a3f'),
  ('ur.jalandhry', 21, 7, 2490, 'اور ہم نے تم سے پہلے مرد ہی (پیغمبر بنا کر) بھیجے جن کی طرف ہم وحی بھیجتے تھے۔ اگر تم نہیں جانتے تو جو یاد رکھتے ہیں ان سے پوچھ لو', NULL, NULL, '3df3ac63beb4c83a39e5e98735a0d12f17bd125e93b13e11ce95cb60255d7d6f'),
  ('ur.jalandhry', 21, 8, 2491, 'اور ہم نے ان کے لئے ایسے جسم نہیں بنائے تھے کہ کھانا نہ کھائیں اور نہ وہ ہمیشہ رہنے والے تھے', NULL, NULL, '0616022c8be61e2bcd5a9e9210ecae4be21ed4a24861344633ce534cbaa85c58'),
  ('ur.jalandhry', 21, 9, 2492, 'پھر ہم نے ان کے بارے میں (اپنا) وعدہ سچا کردیا تو ان کو اور جس کو چاہا نجات دی اور حد سے نکل جانے والوں کو ہلاک کردیا', NULL, NULL, 'a5abd873321a71804df25443fbcdaac7c2ac5e604042de2d7c346ec8303a2808'),
  ('ur.jalandhry', 21, 10, 2493, 'ہم نے تمہاری طرف ایسی کتاب نازل کی ہے جس میں تمہارا تذکرہ ہے۔ کیا تم نہیں سمجھتے', NULL, NULL, 'e4bfaf16b2d66463db91464ad71e2566d71085447f0aed566d80097e02825790'),
  ('ur.jalandhry', 21, 11, 2494, 'اور ہم نے بہت سی بستیوں کو جو ستمگار تھیں ہلاک کر مارا اور ان کے بعد اور لوگ پیدا کردیئے', NULL, NULL, '8f6436fb5d84d2b26696e0895e84fb16f54ac2c60f4cc99465400393904b66ec'),
  ('ur.jalandhry', 21, 12, 2495, 'جب انہوں نے ہمارے (مقدمہ) عذاب کو دیکھا تو لگے اس سے بھاگنے', NULL, NULL, '6b7d19d3809b4c69330384f815b7d4e6dad072a34c977df2444dc75f984cf62b'),
  ('ur.jalandhry', 21, 13, 2496, 'مت بھاگو اور جن (نعمتوں) میں تم عیش وآسائش کرتے تھے ان کی اور اپنے گھروں کی طرف لوٹ جاؤ۔ شاید تم سے (اس بارے میں) دریافت کیا جائے', NULL, NULL, 'c3fc661e5938d3c597542facf1f3387770c3b0ce561ed4c071b481128eb941f1'),
  ('ur.jalandhry', 21, 14, 2497, 'کہنے لگے ہائے شامت بےشک ہم ظالم تھے', NULL, NULL, '4a524eb68c0e0aef468373f4d844aafcd4c77a6546f785768b2c7abc47f5c080'),
  ('ur.jalandhry', 21, 15, 2498, 'تو وہ ہمیشہ اسی طرح پکارتے رہے یہاں تک کہ ہم نے ان کو (کھیتی کی طرح) کاٹ کر (اور آگ کی طرح) بجھا کر ڈھیر کردیا', NULL, NULL, 'be8dea637cc49e327ca8838da80b7724bacc05455c88bcbfd28cbfa3bcb8dbe8'),
  ('ur.jalandhry', 21, 16, 2499, 'اور ہم نے آسمان اور زمین کو جو اور (مخلوقات) ان دونوں کے درمیان ہے اس کو لہوولعب کے لئے پیدا نہیں کیا', NULL, NULL, '38f166dd0d8075c1b6bfc4045efdbf6305d8f9c54f3685c47b0d12a7c9e30b70'),
  ('ur.jalandhry', 21, 17, 2500, 'اگر ہم چاہتے کہ کھیل (کی چیزیں یعنی زن وفرزند) بنائیں تو اگر ہم کو کرنا ہوتا تو ہم اپنے پاس سے بنالیتے', NULL, NULL, '73d91157a22d355f5d849b59335e8e6e0e653126d186352b19c4a353668e4d62')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 21, 18, 2501, 'بلکہ ہم سچ کو جھوٹ پر کھینچ مارتے ہیں تو وہ اس کا سر توڑ دیتا ہے اور جھوٹ اسی وقت نابود ہوجاتا ہے۔ اور جو باتیں تم بناتے ہو ان سے تمہاری ہی خرابی ہے', NULL, NULL, '67609fa65dd52e6b37e7a8b8465ade6eb10c74d6e7b87623966ac8bb788d14ad'),
  ('ur.jalandhry', 21, 19, 2502, 'اور جو لوگ آسمانوں میں اور جو زمین میں ہیں سب اسی کے (مملوک اور اُسی کا مال) ہیں۔ اور جو (فرشتے) اُس کے پاس ہیں وہ اس کی عبادت سے نہ کنیاتے ہیں اور نہ اکتاتے ہیں', NULL, NULL, 'd1e9839b70c8062bc583b2bfb96ce3a3af569832605b26822819a10899d49027'),
  ('ur.jalandhry', 21, 20, 2503, 'رات دن (اُس کی) تسبیح کرتے رہتے ہیں (نہ تھکتے ہیں) نہ اکتاتے ہیں', NULL, NULL, '34f5594538ef423ae21e2f015dbc0eeccfb70429fc2b330ae09a6353e508a2fe'),
  ('ur.jalandhry', 21, 21, 2504, 'بھلا لوگوں نے جو زمین کی چیزوں سے (بعض کو) معبود بنا لیا ہے (تو کیا) وہ ان کو (مرنے کے بعد) اُٹھا کھڑا کریں گے؟', NULL, NULL, '6792dc84e6bbaf99fcfaae9a8937c8c7f8781ce3e2eb2f1ca70082f383c8e825'),
  ('ur.jalandhry', 21, 22, 2505, 'اگر آسمان اور زمین میں خدا کے سوا اور معبود ہوتے تو زمین وآسمان درہم برہم ہوجاتے۔ جو باتیں یہ لوگ بتاتے ہیں خدائے مالک عرش ان سے پاک ہے', NULL, NULL, 'd4ee7ae1c477807dc8236f0b5b5305345ab960c73f37e256d1ba99c778aaad37'),
  ('ur.jalandhry', 21, 23, 2506, 'وہ جو کام کرتا ہے اس کی پرستش نہیں ہوگی اور (جو کام یہ لوگ کرتے ہیں اس کی) ان سے پرستش ہوگی', NULL, NULL, '6f52f86851048f7a776b29ee64c9a2959c29942ce3d06cfe4cff8e36c6b12d30'),
  ('ur.jalandhry', 21, 24, 2507, 'کیا لوگوں نے خدا کو چھوڑ کر اور معبود بنالئے ہیں۔ کہہ دو کہ (اس بات پر) اپنی دلیل پیش کرو۔ یہ (میری اور) میرے ساتھ والوں کی کتاب بھی ہے اور جو مجھ سے پہلے (پیغمبر) ہوئے ہیں۔ ان کی کتابیں بھی ہیں۔ بلکہ (بات یہ ہے کہ) ان اکثر حق بات کو نہیں جانتے اور اس لئے اس سے منہ پھیر لیتے ہیں', NULL, NULL, 'b5354d897d9b745141c331c8dedd7baa9f3f86afb77be86903fb5cc62d0a27ee'),
  ('ur.jalandhry', 21, 25, 2508, 'اور جو پیغمبر ہم نےتم سے پہلے بھیجے ان کی طرف یہی وحی بھیجی کہ میرے سوا کوئی معبود نہیں تو میری ہی عبادت کرو', NULL, NULL, 'cd7d540103fc9cdf7d441b5f8de67dbc7bc29be88f261354c7f7cfca6f87faf6'),
  ('ur.jalandhry', 21, 26, 2509, 'اور کہتے ہیں کہ خدا بیٹا رکھتا ہے۔ وہ پاک ہے (اس کے نہ بیٹا ہے نہ بیٹی) بلکہ (جن کو یہ لوگ اس کے بیٹے بیٹیاں سمجھتے ہیں) وہ اس کے عزت والے بندے ہیں', NULL, NULL, 'ec7fcd0eb62457907de7c239c03c19338fb08c82aa0bb0bfecb1692aeed9e8ed'),
  ('ur.jalandhry', 21, 27, 2510, 'اس کے آگے بڑھ کر بول نہیں سکتے۔ اور اس کے حکم پر عمل کرتے ہیں', NULL, NULL, '6e4966ee19147a3e963268a12cecdfe8b769f35fb2b445314bcdfb75f98657fb'),
  ('ur.jalandhry', 21, 28, 2511, 'جو کچھ ان کے آگے ہوچکا ہے اور پیچھے ہوگا وہ سب سے واقف ہے اور وہ (اس کے پاس کسی کی) سفارش نہیں کرسکتے مگر اس شخص کی جس سے خدا خوش ہو اور وہ اس کی ہیبت سے ڈرتے رہتے ہیں', NULL, NULL, 'c9349f93f4a966d7df24dedac9c798243e2760c32058761a6e294bc188f4ed03'),
  ('ur.jalandhry', 21, 29, 2512, 'اور جو شخص ان میں سے یہ کہے کہ خدا کے سوا میں معبود ہوں تو اسے ہم دوزخ کی سزا دیں گے اور ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں', NULL, NULL, '0f68d5b33eb3a6cfdd2c7b83b9ba6db8bf3c7e7c1f2a776c8d22a6662ea15c32'),
  ('ur.jalandhry', 21, 30, 2513, 'کیا کافروں نے نہیں دیکھا کہ آسمان اور زمین دونوں ملے ہوئے تھے تو ہم نے جدا جدا کردیا۔ اور تمام جاندار چیزیں ہم نے پانی سے بنائیں۔ پھر یہ لوگ ایمان کیوں نہیں لاتے؟', NULL, NULL, '2a497f997f660f59a8a086ac9eb872bcbced67b0c5d7ffdd8089796e1cda28cb'),
  ('ur.jalandhry', 21, 31, 2514, 'اور ہم نے زمین میں پہاڑ بنائے تاکہ لوگوں (کے بوجھ) سے ہلنے (اور جھکنے) نہ لگے اور اس میں کشادہ راستے بنائے تاکہ لوگ ان پر چلیں', NULL, NULL, '3124ed785ec7d38b84d0b839ffa9d711b331b60c3ae0c431d466b6ddffdddf4d'),
  ('ur.jalandhry', 21, 32, 2515, 'اور آسمان کو محفوظ چھت بنایا۔ اس پر بھی وہ ہماری نشانیوں سے منہ پھیر رہے ہیں', NULL, NULL, 'f26934818b8020241fb80f81cb9c536c53e74d82aa84557ee2f04d9a309ac09c'),
  ('ur.jalandhry', 21, 33, 2516, 'اور وہی تو ہے جس نے رات اور دن اور سورج اور چاند کو بنایا۔ (یہ) سب (یعنی سورج اور چاند اور ستارے) آسمان میں (اس طرح چلتے ہیں گویا) تیر رہے ہیں', NULL, NULL, '2db4c1638003af51aac3a210c6748cb65972d3847963c63e0e21fb5e977fde7e'),
  ('ur.jalandhry', 21, 34, 2517, 'اور (اے پیغمبر) ہم نے تم سے پہلے کسی آدمی کو بقائے دوام نہیں بخشا۔ بھلا اگر تم مرجاؤ تو کیا یہ لوگ ہمیشہ رہیں گے', NULL, NULL, '1c66f112cd3f6ce423f977a51d54d979d168a313680af56bb90a587d1aa12524'),
  ('ur.jalandhry', 21, 35, 2518, 'ہر متنفس کو موت کا مزا چکھنا ہے۔ اور ہم تو لوگوں کو سختی اور آسودگی میں آزمائش کے طور پر مبتلا کرتے ہیں۔ اور تم ہماری طرف ہی لوٹ کر آؤ گے', NULL, NULL, 'fb8fc99701ae2fce30aa6cff4c9d5201e657b22c25e8adbb28845ce62bca2f42'),
  ('ur.jalandhry', 21, 36, 2519, 'اور جب کافر تم کو دیکھتے ہیں تو تم سے استہزاء کرتے ہیں کہ کیا یہی شخص ہے جو تمہارے معبودوں کا ذکر (برائی سے) کیا کرتا ہے حالانکہ وہ خود رحمٰن کے نام سے منکر ہیں', NULL, NULL, '6709c2e55be156897b597b43ee6fd0991eef0245e9c4de29f5e1e2c04b7b22a1'),
  ('ur.jalandhry', 21, 37, 2520, 'انسان (کچھ ایسا جلد باز ہے کہ گویا) جلد بازی ہی سے بنایا گیا ہے۔ میں تم لوگوں کو عنقریب اپنی نشانیاں دکھاؤں گا تو تم جلدی نہ کرو', NULL, NULL, '1d1e976371a2c69b3c6d72c1e026eda8bb815fa039095eee1732fdee0eece83d'),
  ('ur.jalandhry', 21, 38, 2521, 'اور کہتے ہیں کہ اگر تم سچے ہو تو (جس عذاب کا) یہ وعید (ہے وہ) کب (آئے گا)؟', NULL, NULL, '3515aa57030a070ec9669f9e713057b2957a49f6e19d4f92e31ae9b88025ba42'),
  ('ur.jalandhry', 21, 39, 2522, 'اے کاش کافر اس وقت کو جانیں جب وہ اپنے مونہوں پر سے (دوزخ کی) آگ کو روک نہ سکیں گے اور نہ اپنی پیٹھوں پر سے اور نہ ان کا کوئی مددگار ہوگا', NULL, NULL, 'e1c38740b22dad9ad654f2b3db64fb5bc5fcd8bf63c12b81bbe29a5c5d15821c'),
  ('ur.jalandhry', 21, 40, 2523, 'بلکہ قیامت ان پر ناگہاں آ واقع ہوگی۔ اور ان کے ہوش کھو دے گی۔ پھر نہ تو وہ اس کو ہٹا سکیں گے اور نہ ان کو مہلت دی جائے گی', NULL, NULL, '9d5ee198559dac72717af83de0c79635e1e54863e3ea304a2efe823c20290698'),
  ('ur.jalandhry', 21, 41, 2524, 'اور تم سے پہلے بھی پیغمبروں کے ساتھ استہزاء ہوتا رہا ہے تو جو لوگ ان میں سے تمسخر کیا کرتے تھے ان کو اسی (عذاب) نے جس کی ہنسی اُڑاتے تھے آگھیرا', NULL, NULL, 'd1ca4674b04be5ec85de4f08a179803f6066ea2d9b39b523685a257329a7e00b'),
  ('ur.jalandhry', 21, 42, 2525, 'کہو کہ رات اور دن میں خدا سے تمہاری کون حفاظت کرسکتا ہے؟ بات یہ ہے کہ اپنے پروردگار کی یاد سے منہ پھیرے ہوئے ہیں', NULL, NULL, 'a8ec42714ac3bd8d33accf3bd0f639a7670255aa633badf6710a63f8ca6bf383'),
  ('ur.jalandhry', 21, 43, 2526, 'کیا ہمارے سوا ان کے اور معبود ہیں کہ ان کو (مصائب سے) بچاسکیں۔ وہ آپ اپنی مدد تو کر ہی نہیں سکتے اور نہ ہم سے پناہ ہی دیئے جائیں گے', NULL, NULL, '629330abc0716e54f1b46e1c9229b88373d3e3141ac33cb459bb6253748b0039'),
  ('ur.jalandhry', 21, 44, 2527, 'بلکہ ہم ان لوگوں کو اور ان کے باپ دادا کو متمتع کرتے رہے یہاں تک کہ (اسی حالت میں) ان کی عمریں بسر ہوگئیں۔ کیا یہ نہیں دیکھتے کہ ہم زمین کو اس کے کناروں سے گھٹاتے چلے آتے ہیں۔ تو کیا یہ لوگ غلبہ پانے والے ہیں؟', NULL, NULL, 'f405733f8a3b9d85d37db29d02e3de8e6f8edadaf8401acdb52ac812c68283e7'),
  ('ur.jalandhry', 21, 45, 2528, 'کہہ دو کہ میں تم کو حکم خدا کے مطابق نصیحت کرتا ہوں۔ اور بہروں کوجب نصیحت کی جائے تو وہ پکار کر سنتے ہی نہیں', NULL, NULL, 'e3e272172da90a939fa088120aebbb431d0735087a05261e4744281461d2eb00'),
  ('ur.jalandhry', 21, 46, 2529, 'اور اگر ان کو تمہارے پروردگار کا تھوڑا سا عذاب بھی پہنچے تو کہنے لگیں کہ ہائے کم بختی ہم بےشک ستمگار تھے', NULL, NULL, 'b3130cef3a06f4be989c0a0f436a34c762cb518d3e94d915bd153a2fa1ed484c'),
  ('ur.jalandhry', 21, 47, 2530, 'اور ہم قیامت کے دن انصاف کی ترازو کھڑی کریں گے تو کسی شخص کی ذرا بھی حق تلفی نہ کی جائے گی۔ اور اگر رائی کے دانے کے برابر بھی (کسی کا عمل) ہوگا تو ہم اس کو لاحاضر کریں گے۔ اور ہم حساب کرنے کو کافی ہیں', NULL, NULL, '6691d10f5e5b533c940484e547eaa9f259ab402ae600ea4275418a4541e1e086'),
  ('ur.jalandhry', 21, 48, 2531, 'اور ہم نے موسیٰ اور ہارون کو (ہدایت اور گمراہی میں) فرق کر دینے والی اور (سرتاپا) روشنی اور نصیحت (کی کتاب) عطا کی (یعنی) پرہیز گاروں کے لئے', NULL, NULL, '859b47bb67d914d7bdf4b825daeae21b765c6a006c002fdd8a5f6ef80a7a6a44'),
  ('ur.jalandhry', 21, 49, 2532, 'جو بن دیکھے اپنے پروردگار سے ڈرتے ہیں اور قیامت کا بھی خوف رکھتے ہیں', NULL, NULL, 'b87bb96ef926bc44d29fe6a4cee66f3e0af9cd99285f1ed78a31744df89f9720'),
  ('ur.jalandhry', 21, 50, 2533, 'یہ مبارک نصیحت ہے جسے ہم نے نازل فرمایا ہے تو کیا تم اس سے انکار کرتے ہو؟', NULL, NULL, 'abaf439dd93a276a534d69f514d3ab1985c3b5a5171650d9b07d7c600f579dd2'),
  ('ur.jalandhry', 21, 51, 2534, 'اور ہم نے ابراہیمؑ کو پہلے ہی سے ہدایت دی تھی اور ہم ان کے حال سے واقف تھے', NULL, NULL, '8e9dcf8bb8beed12ed769c4ff59e60cd14a7a464f0560ebcd3cc742d4e4754c4'),
  ('ur.jalandhry', 21, 52, 2535, 'جب انہوں نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا یہ کیا مورتیں ہیں جن (کی پرستش) پر تم معتکف (وقائم) ہو؟', NULL, NULL, '6adf2af54c2f02d02c3134ba641d19a5616b2014dc6cc9f482c3d0c5a04d91b9'),
  ('ur.jalandhry', 21, 53, 2536, 'وہ کہنے لگے کہ ہم نے اپنے باپ دادا کو ان کی پرستش کرتے دیکھا ہے', NULL, NULL, '5c8df9d3a02658f3201cfccdefedb6a7567db7b64720b0cebec92903787e3a84'),
  ('ur.jalandhry', 21, 54, 2537, '(ابراہیم نے) کہا کہ تم بھی (گمراہ ہو) اور تمہارے باپ دادا بھی صریح گمراہی میں پڑے رہے', NULL, NULL, '83a4e21901ab27b2c7c8c64ba42271cfdedcb465a30a1af058319d0edafa95db'),
  ('ur.jalandhry', 21, 55, 2538, 'وہ بولے کیا تم ہمارے پاس (واقعی) حق لائے ہو یا (ہم سے) کھیل (کی باتیں) کرتے ہو؟', NULL, NULL, '3b2ec0183e7103ed6f6ab4bbaa43d10ebacc37cc3e7c77e282dd789b8a2318e1'),
  ('ur.jalandhry', 21, 56, 2539, '(ابراہیم نے) کہا (نہیں) بلکہ تمہارا پروردگار آسمانوں اور زمین کا پروردگار ہے جس نے ان کو پیدا کیا ہے۔ اور میں اس (بات) کا گواہ (اور اسی کا قائل) ہوں', NULL, NULL, 'dfe12290d3d2b276e7a567bb4779142cac55883c459e852b064c4d2296235a6d'),
  ('ur.jalandhry', 21, 57, 2540, 'اور خدا کی قسم جب تم پیٹھ پھیر کر چلے جاؤ گے تو میں تمہارے بتوں سے ایک چال چلوں گا', NULL, NULL, 'b8c17b31d0ec718a78c07123ab241d1f8fdcd27a45c00b6ebed16c7197f81621'),
  ('ur.jalandhry', 21, 58, 2541, 'پھر ان کو توڑ کر ریزہ ریزہ کردیا مگر ایک بڑے (بت) کو (نہ توڑا) تاکہ وہ اس کی طرف رجوع کریں', NULL, NULL, 'c7641b1b1ce2dabb4b807ba7191b8b23d501abfd1669c8d70982c98b07c50bb7'),
  ('ur.jalandhry', 21, 59, 2542, 'کہنے لگے کہ ہمارے معبودوں کے ساتھ یہ معاملہ کس نے کیا؟ وہ تو کوئی ظالم ہے', NULL, NULL, '004cdf862cc94ac9bf0a77a883ba6fd1feb63b64236833b6cb09879fbcec48b5'),
  ('ur.jalandhry', 21, 60, 2543, 'لوگوں نے کہا کہ ہم نے ایک جوان کو ان کا ذکر کرتے ہوئے سنا ہے اس کو ابراہیم کہتے ہیں', NULL, NULL, '7ee207e865d6f0d0e21d9941ad15e888a9439a7fea690e6d2bda762b7c552dbd'),
  ('ur.jalandhry', 21, 61, 2544, 'وہ بولے کہ اسے لوگوں کے سامنے لاؤ تاکہ گواہ رہیں', NULL, NULL, '61bcb154faf7b88ad72b38d35753fef610d599f29df301d3d9ac382959f42f1d'),
  ('ur.jalandhry', 21, 62, 2545, '(جب ابراہیم آئے تو) بت پرستوں نے کہا کہ ابراہیم بھلا یہ کام ہمارے معبودوں کے ساتھ تم نے کیا ہے؟', NULL, NULL, 'f33e0ad5300dc0600ff80391d674fe6d75921203157bcded7c873131bc4b3a67'),
  ('ur.jalandhry', 21, 63, 2546, '(ابراہیم نے) کہا (نہیں) بلکہ یہ ان کے اس بڑے (بت) نے کیا (ہوگا) ۔ اگر یہ بولتے ہیں تو ان سے پوچھ لو', NULL, NULL, '993b57a3cd314e994e9be1c6edc9fc29dd5c1877f06d1fa7f4d44530f7942109'),
  ('ur.jalandhry', 21, 64, 2547, 'انہوں نے اپنے دل غور کیا تو آپس میں کہنے لگے بےشک تم ہی بےانصاف ہو', NULL, NULL, '82d8983d2105016d1464f8f351b53b7fb02308a4785c3097298923728ddbc99e'),
  ('ur.jalandhry', 21, 65, 2548, 'پھر (شرمندہ ہو کر) سر نیچا کرلیا (اس پر بھی ابراہیم سے کہنے لگے کہ) تم جانتے ہو یہ بولتے نہیں', NULL, NULL, '6c42bbb2e80d0b479988c9e80c1bcc720f87ffb1145a1ffccfcabed153c7bb34'),
  ('ur.jalandhry', 21, 66, 2549, '(ابراہیم نے) کہا پھر تم خدا کو چھوڑ کر کیوں ایسی چیزوں کو پوجتے ہو جو نہ تمہیں کچھ فائدہ دے سکیں اور نقصان پہنچا سکیں؟', NULL, NULL, 'ccdacd1f2eb8d65bd5814ad5e78ba1051fc2ef5a19c2c7e189727980866b8a77'),
  ('ur.jalandhry', 21, 67, 2550, 'تف ہے تم پر اور جن کو تم خدا کے سوا پوجتے ہو ان پر بھی کیا تم عقل نہیں رکھتے؟', NULL, NULL, '0d72ee472ec2986716f1d6eff219697db784d3a4c903e2ea310d14c0b98c0f85'),
  ('ur.jalandhry', 21, 68, 2551, '(تب وہ) کہنے لگے کہ اگر تمہیں (اس سے اپنے معبود کا انتقام لینا اور) کچھ کرنا ہے تو اس کو جلا دو اور اپنے معبودوں کی مدد کرو', NULL, NULL, 'e88dbbb08983cd7a9c18f07e37797292e30fffc8304a1a5f55a95e7e67334eb0'),
  ('ur.jalandhry', 21, 69, 2552, 'ہم نے حکم دیا اے آگ سرد ہوجا اور ابراہیم پر (موجب) سلامتی (بن جا)', NULL, NULL, 'e4335aa52ed8e40d335e9390cc6d8b6ee53643202853018210d8bb73f080914d'),
  ('ur.jalandhry', 21, 70, 2553, 'اور ان لوگوں نے برا تو ان کا چاہا تھا مگر ہم نے ان ہی کو نقصان میں ڈال دیا', NULL, NULL, '639183d3ab9bed23ad76ed1ed951769db1933a6cb86d2c1231058e09f3c5ab48'),
  ('ur.jalandhry', 21, 71, 2554, 'اور ابراہیم اور لوط کو اس سرزمین کی طرف بچا نکالا جس میں ہم نے اہل عالم کے لئے برکت رکھی تھی', NULL, NULL, '2f10ff548e0ef31150ae97fce05ac926401b4cdf2a579358ca9d93f2dfe2dd04'),
  ('ur.jalandhry', 21, 72, 2555, 'اور ہم نے ابراہیم کو اسحق عطا کئے۔ اور مستزاد برآں یعقوب۔ اور سب کو نیک بخت کیا', NULL, NULL, 'dcee877e6c9f8802b5280aa17745ec7ccac0cf4a193830f4d18110bdd7cb9dff'),
  ('ur.jalandhry', 21, 73, 2556, 'اور ان کو پیشوا بنایا کہ ہمارے حکم سے ہدایت کرتے تھے اور ان کو نیک کام کرنے اور نماز پڑھنے اور زکوٰة دینے کا حکم بھیجا۔ اور وہ ہماری عبادت کیا کرتے تھے', NULL, NULL, 'f853aeacdf4450d009f7244d6f8682ad69bb300b28352872f5960a25aa47f5c5'),
  ('ur.jalandhry', 21, 74, 2557, 'اور لوط (کا قصہ یاد کرو) جب ان کو ہم نے حکم (یعنی حکمت ونبوت) اور علم بخشا اور اس بستی سے جہاں کے لوگ گندے کام کیا کرتے تھے۔ بچا نکالا۔ بےشک وہ برے اور بدکردار لوگ تھے', NULL, NULL, '4d7278557f54aa7e5b2b4b676d40ea473c0cb39b70f6bd347810c6550348dc9f'),
  ('ur.jalandhry', 21, 75, 2558, 'اور انہیں اپنی رحمت کے (محل میں) داخل کیا۔ کچھ شک نہیں کہ وہ نیک بختوں میں تھے', NULL, NULL, '5af623176ba0d4605e1374001684fd4ee051d349a04ff4886edd3f78460f7b5a'),
  ('ur.jalandhry', 21, 76, 2559, 'اور نوح (کا قصہ بھی یاد کرو) جب (اس سے) پیشتر انہوں نے ہم کو پکارا تو ہم نے ان کی دعا قبول فرمائی اور ان کو اور ان کے ساتھیوں کو بڑی گھبراہٹ سے نجات دی', NULL, NULL, 'a8a373d61a96e6609910ec8c8da0e27d5d1b276d4ab6bd4bb07e81e5e11770ce'),
  ('ur.jalandhry', 21, 77, 2560, 'اور جو لوگ ہماری آیتوں کی تکذیب کرتے تھے ان پر نصرت بخشی۔ وہ بےشک برے لوگ تھے سو ہم نے ان سب کو غرق کردیا', NULL, NULL, 'b4c923d6da72a31d76ac3722f48978d5eca710f14768f3040e8bd718f785c256'),
  ('ur.jalandhry', 21, 78, 2561, 'اور داؤد اور سلیمان (کا حال بھی سن لو کہ) جب وہ ایک کھیتی کا مقدمہ فیصلہ کرنے لگے جس میں کچھ لوگوں کی بکریاں رات کو چر گئی (اور اسے روند گئی) تھیں اور ہم ان کے فیصلے کے وقت موجود تھے', NULL, NULL, '354775c6541785ff84571f9406c415324c2a1b70c518a7918422216f384fb1c0'),
  ('ur.jalandhry', 21, 79, 2562, 'تو ہم نے فیصلہ (کرنے کا طریق) سلیمان کو سمجھا دیا۔ اور ہم نے دونوں کو حکم (یعنی حکمت ونبوت) اور علم بخشا تھا۔ اور ہم نے پہاڑوں کو داؤد کا مسخر کردیا تھا کہ ان کے ساتھ تسبیح کرتے تھے اور جانوروں کو بھی (مسخر کردیا تھا اور ہم ہی ایسا) کرنے والے تھے', NULL, NULL, '767ff27104619a853cb5b6c73530288cc4c5fe28ea4a2da53d2979d0064762de'),
  ('ur.jalandhry', 21, 80, 2563, 'اور ہم نے تمہارے لئے ان کو ایک (طرح) کا لباس بنانا بھی سکھا دیا تاکہ تم کو لڑائی (کے ضرر) سے بچائے۔ پس تم کو شکرگزار ہونا چاہیئے', NULL, NULL, 'e17e4fe36318c668836610fb0e094658be449cde2033a0d4aa40ee5ade505421'),
  ('ur.jalandhry', 21, 81, 2564, 'اور ہم نے تیز ہوا سلیمان کے تابع (فرمان) کردی تھی جو ان کے حکم سے اس ملک میں چلتی تھی جس میں ہم نے برکت دی تھی (یعنی شام) اور ہم ہر چیز سے خبردار ہیں', NULL, NULL, '46dfca222eff945bf454c4d5e5f1f6fb28818c4e3b61b164acc9dbf5abac43fd'),
  ('ur.jalandhry', 21, 82, 2565, 'اور دیوؤں (کی جماعت کو بھی ان کے تابع کردیا تھا کہ ان) میں سے بعض ان کے لئے غوطے مارتے تھے اور اس کے سوا اور کام بھی کرتے تھے اور ہم ان کے نگہبان تھے', NULL, NULL, '813597ff9a8df00dce79d2d6136ead32c67f0124f55dad15e82b2a20f576ceea'),
  ('ur.jalandhry', 21, 83, 2566, 'اور ایوب کو (یاد کرو) جب انہوں نے اپنے پروردگار سے دعا کی کہ مجھے ایذا ہو رہی ہے اور تو سب سے بڑھ کر رحم کرنے والا ہے', NULL, NULL, 'ece0be4a37fdc86dee7cb9abc5da13735c4a83f3d32c036eec6c9b680554438b'),
  ('ur.jalandhry', 21, 84, 2567, 'تو ہم نے ان کی دعا قبول کرلی اور جو ان کو تکلیف تھی وہ دور کردی اور ان کو بال بچے بھی عطا فرمائے اور اپنی مہربانی کے ساتھ اتنے ہی اور (بخشے) اور عبادت کرنے والوں کے لئے (یہ) نصیحت ہے', NULL, NULL, '8d6bd2f625d036c72e1ad02f24c7e334580e907e5ba30c8ad2676f2bca6c6c80'),
  ('ur.jalandhry', 21, 85, 2568, 'اور اسمٰعیل اور ادریس اور ذوالکفل (کو بھی یاد کرو) یہ سب صبر کرنے والے تھے', NULL, NULL, 'c8770d95c6248c62b5204293cb1fbd2bcc06ee4bdf28b674d4799a153ead08f4'),
  ('ur.jalandhry', 21, 86, 2569, 'اور ہم نے ان کو اپنی رحمت میں داخل کیا۔ بلاشبہ وہ نیکوکار تھے', NULL, NULL, '6a606c06e9745e3bbdec1de2f25efff413ede219add4395e4ee56b78972e261b'),
  ('ur.jalandhry', 21, 87, 2570, 'اور ذوالنون (کو یاد کرو) جب وہ (اپنی قوم سے ناراض ہو کر) غصے کی حالت میں چل دیئے اور خیال کیا کہ ہم ان پر قابو نہیں پاسکیں گے۔ آخر اندھیرے میں (خدا کو) پکارنے لگے کہ تیرے سوا کوئی معبود نہیں۔ تو پاک ہے (اور) بےشک میں قصوروار ہوں', NULL, NULL, '8b36badf6fde6355d8d681d8f1d2f1ea5aa7e88b3bf1fb766a374eca23f4ae1a'),
  ('ur.jalandhry', 21, 88, 2571, 'تو ہم نے ان کی دعا قبول کرلی اور ان کو غم سے نجات بخشی۔ اور ایمان والوں کو ہم اسی طرح نجات دیا کرتے ہیں', NULL, NULL, '64ac0a7fc6ee5ca727188b15b348eb745be839b532f8349177f9e1b841d3fe4b'),
  ('ur.jalandhry', 21, 89, 2572, 'اور زکریا (کو یاد کرو) جب انہوں نے اپنے پروردگار کو پکارا کہ پروردگار مجھے اکیلا نہ چھوڑ اور تو سب سے بہتر وارث ہے', NULL, NULL, '8372c886a8c4330a9902d3fe4bcf4f1b382e7043a71153449aeb2a751552de42'),
  ('ur.jalandhry', 21, 90, 2573, 'تو ہم نے ان کی پکار سن لی۔ اور ان کو یحییٰ بخشے اور ان کی بیوی کو اُن کے (حسن معاشرت کے) قابل بنادیا۔ یہ لوگ لپک لپک کر نیکیاں کرتے اور ہمیں امید سے پکارتے اور ہمارے آگے عاجزی کیا کرتے تھے', NULL, NULL, 'bddfc10638093e0354cefe6db60c74a953efe047feeaefa0227ddfa30d2bb4b5'),
  ('ur.jalandhry', 21, 91, 2574, 'اور ان (مریم) کو (بھی یاد کرو) جنہوں نے اپنی عفّت کو محفوظ رکھا۔ تو ہم نے ان میں اپنی روح پھونک دی اور ان کے بیٹے کو اہل عالم کے لئے نشانی بنا دیا', NULL, NULL, '3b901a9dce8315df95f1a90e147609758ff8ec38d1ec14053acbb1de001d6038'),
  ('ur.jalandhry', 21, 92, 2575, 'یہ تمہاری جماعت ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو میری ہی عبادت کیا کرو', NULL, NULL, '651d3324d5485291ef68d0b73270921e45da73dbbc19be4f67d9ceacaec388b8'),
  ('ur.jalandhry', 21, 93, 2576, 'اور یہ لوگ اپنے معاملے میں باہم متفرق ہوگئے۔ (مگر) سب ہماری طرف رجوع کرنے والے ہیں', NULL, NULL, 'f94172e0138df14033a8648381eee78eeb8ecbc6820897011cc3759a832f3337'),
  ('ur.jalandhry', 21, 94, 2577, 'جو نیک کام کرے گا اور مومن بھی ہوگا تو اس کی کوشش رائیگاں نہ جائے گی۔ اور ہم اس کے لئے (ثواب اعمال) لکھ رہے ہیں', NULL, NULL, '4200fd1cb1a6b0daf6e2e2b7031748cb684751be16a8150039dca5906a53abb5'),
  ('ur.jalandhry', 21, 95, 2578, 'اور جس بستی (والوں) کو ہم نے ہلاک کردیا محال ہے کہ (وہ دنیا کی طرف رجوع کریں) وہ رجوع نہیں کریں گے', NULL, NULL, '5271c20148041a185d8d16faaa8b505cad28f2bce145ecfb8c99049b606cd6f5'),
  ('ur.jalandhry', 21, 96, 2579, 'یہاں تک کہ یاجوج ماجوج کھول دیئے جائیں اور وہ ہر بلندی سے دوڑ رہے ہوں', NULL, NULL, '6cd770e2bd666ef9da8f6f8b93f1454e7c9a40596a85ccf668cc311138465204'),
  ('ur.jalandhry', 21, 97, 2580, 'اور (قیامت کا) سچا وعدہ قریب آجائے تو ناگاہ کافروں کی آنکھیں کھلی کی کھلی رہ جائیں (اور کہنے لگیں کہ) ہائے شامت ہم اس (حال) سے غفلت میں رہے بلکہ (اپنے حق میں) ظالم تھے', NULL, NULL, '0c18b4b126625ea774552cd06cb531cc104051a64dcbb9266382685640496210'),
  ('ur.jalandhry', 21, 98, 2581, '(کافرو اس روز) تم اور جن کی تم خدا کے سوا عبادت کرتے ہو دوزخ کا ایندھن ہوں گے۔ اور تم سب اس میں داخل ہو کر رہو گے', NULL, NULL, '23024f8a473c379a3638f477e0f7c09f62bbd5011e63cff82eccc9e286f9c75a'),
  ('ur.jalandhry', 21, 99, 2582, 'اگر یہ لوگ (درحقیقت) معبود ہوتے تو اس میں داخل نہ ہوتے۔ سب اس میں ہمیشہ (جلتے) رہیں گے', NULL, NULL, 'd9e2489b62d3e980e7033500d605a9c0e57eb44a277497cec0f12af7df80517f'),
  ('ur.jalandhry', 21, 100, 2583, 'وہاں ان کو چلاّنا ہوگا اور اس میں (کچھ) نہ سن سکیں گے', NULL, NULL, '94bf22756b7f9ee3963b1b4c1566a8701ca8abd4763736da214d9b8246756423'),
  ('ur.jalandhry', 21, 101, 2584, 'جن لوگوں کے لئے ہماری طرف سے پہلے بھلائی مقرر ہوچکی ہے۔ وہ اس سے دور رکھے جائیں گے', NULL, NULL, 'b0dfb72a2b33c8481b7668a7cf6ced80a01590e6d1665b235184613ac211bc11'),
  ('ur.jalandhry', 21, 102, 2585, '(یہاں تک کہ) اس کی آواز بھی تو نہیں سنیں گے۔ اور جو کچھ ان کا جی چاہے گا اس میں (یعنی) ہر طرح کے عیش اور لطف میں ہمیشہ رہیں گے', NULL, NULL, 'db40a17c8df97cc1832e3b607130fe72c38a09e8163fcc9f3a9902833270f9f9'),
  ('ur.jalandhry', 21, 103, 2586, 'ان کو (اس دن کا) بڑا بھاری خوف غمگین نہیں کرے گا۔ اور فرشتے ان کو لینے آئیں گے (اور کہیں گے کہ) یہی وہ دن ہے جس کا تم سے وعدہ کیا جاتا ہے', NULL, NULL, '69a62a4a38240a41cfb12f6b9cc9b1087dda88a5295011a8a3c579502ee46151'),
  ('ur.jalandhry', 21, 104, 2587, 'جس دن ہم آسمان کو اس طرح لپیٹ لیں گے جیسے خطوں کا طومار لپیٹ لیتے ہیں۔ جس طرح ہم نے (کائنات کو) پہلے پیدا کیا اسی طرح دوبارہ پیدا کردیں گے۔ (یہ) وعدہ (جس کا پورا کرنا لازم) ہے۔ ہم (ایسا) ضرور کرنے والے ہیں', NULL, NULL, 'bcde580576a1d704dab0c7da3521b495bbda08a3d21476adcbb461726850d842'),
  ('ur.jalandhry', 21, 105, 2588, 'اور ہم نے نصیحت (کی کتاب یعنی تورات) کے بعد زبور میں لکھ دیا تھا کہ میرے نیکوکار بندے ملک کے وارث ہوں گے', NULL, NULL, '60aaa4fbaf40a681940ad75b9c276c2957c9d42ab93572fbf5c3fd96a14e2aa5'),
  ('ur.jalandhry', 21, 106, 2589, 'عبادت کرنے والے لوگوں کے لئے اس میں (خدا کے حکموں کی) تبلیغ ہے', NULL, NULL, '87b041af477e504f5d443230bb13b38e129b84185bd4d8919e41a4a87130aa95'),
  ('ur.jalandhry', 21, 107, 2590, 'اور (اے محمدﷺ) ہم نے تم کو تمام جہان کے لئے رحمت (بنا کر) بھیجا ہے', NULL, NULL, '51f3a6e22ce7309ce04a46ec704d8d770d62f8b706ec66d0f2539f8a58692ab7'),
  ('ur.jalandhry', 21, 108, 2591, 'کہہ دو کہ مجھ پر (خدا کی طرف سے) یہ وحی آتی ہے کہ تم سب کا معبود خدائے واحد ہے۔ تو تم کو چاہیئے کہ فرمانبردار بن جاؤ', NULL, NULL, '94ad51ff785d0f04ab36c86fd345c652ec559d6b12b614e1d8b28b8da21f4acc'),
  ('ur.jalandhry', 21, 109, 2592, 'اگر یہ لوگ منہ پھیریں تو کہہ دو کہ میں نے تم کو سب کو یکساں (احکام الہیٰ سے) آگاہ کردیا ہے۔ اور مجھ کو معلوم نہیں کہ جس چیز کا تم سے وعدہ کیا جاتا ہے وہ (عن) قریب (آنے والی) ہے یا (اس کا وقت) دور ہے', NULL, NULL, 'dde98bd069cb16ea5ca818c92084cfdd40b5e24bb00df1bd272b3869b2281479'),
  ('ur.jalandhry', 21, 110, 2593, 'اور جو بات پکار کی جائے وہ اسے بھی جانتا ہے اور جو تم پوشیدہ کرتے ہو اس سے بھی واقف ہے', NULL, NULL, '8026549eb43434e0588c79a3442bad9a94a01574ae9aa6e6e92aba7a299b9405'),
  ('ur.jalandhry', 21, 111, 2594, 'اور میں نہیں جانتا شاید وہ تمہارے لئے آزمائش ہو اور ایک مدت تک (تم اس سے) فائدہ (اٹھاتے رہو)', NULL, NULL, '658500d8ee739c58b1f04c5f58e1f65b4392d5e9917752df7a94afeb44c26e11'),
  ('ur.jalandhry', 21, 112, 2595, 'پیغمبر نے کہا کہ اے میرے پروردگار حق کے ساتھ فیصلہ کردے۔ اور ہمارا پروردگار بڑا مہربان ہے اسی سے ان باتوں میں جو تم بیان کرتے ہو مدد مانگی جاتی ہے', NULL, NULL, '056149b7141f41750672f0a29dde17688f5febd0b6c48ea8e967a822fc07c8f0'),
  ('ur.jalandhry', 22, 1, 2596, 'لوگو! اپنے پروردگار سے ڈرو۔ کہ قیامت کا زلزلہ ایک حادثہٴ عظیم ہوگا', NULL, NULL, '3ec09756dde97973fb11f246a302775755e75629de3f23cb0adae677d10496ae'),
  ('ur.jalandhry', 22, 2, 2597, '(اے مخاطب) جس دن تو اس کو دیکھے گا (اُس دن یہ حال ہوگا کہ) تمام دودھ پلانے والی عورتیں اپنے بچوں کو بھول جائیں گی۔ اور تمام حمل والیوں کے حمل گر پڑیں گے۔ اور لوگ تجھ کو متوالے نظر آئیں گے مگر وہ متوالے نہیں ہوں گے بلکہ (عذاب دیکھ کر) مدہوش ہو رہے ہوں گے۔ بےشک خدا کا عذاب بڑا سخت ہے', NULL, NULL, '37f8568970449c257bbac9995fff1b45e13c2251fa536f84565d009f203e253f'),
  ('ur.jalandhry', 22, 3, 2598, 'اور بعض لوگ ایسے ہیں جو خدا (کی شان) میں علم (ودانش) کے بغیر جھگڑتے اور ہر شیطان سرکش کی پیروی کرتے ہیں', NULL, NULL, 'a03e04ebca5f744d89cdbaf52774476490ae3863502c162bcdf9e4e9c49e2d29'),
  ('ur.jalandhry', 22, 4, 2599, 'جس کے بارے میں لکھ دیا گیا ہے کہ جو اسے دوست رکھے گا تو اس کو گمراہ کردے گا اور دوزخ کے عذاب کا رستہ دکھائے گا', NULL, NULL, 'dca2261ca61bf689ce29ea8a2d8c58051c07ad9dd73b81d44f5b7fd777e7784d'),
  ('ur.jalandhry', 22, 5, 2600, 'لوگو اگر تم کو مرنے کے بعد جی اُٹھنے میں کچھ شک ہو تو ہم نے تم کو (پہلی بار بھی تو) پیدا کیا تھا (یعنی ابتدا میں) مٹی سے پھر اس سے نطفہ بنا کر۔ پھر اس سے خون کا لوتھڑا بنا کر۔ پھر اس سے بوٹی بنا کر جس کی بناوٹ کامل بھی ہوتی ہے اور ناقص بھی تاکہ تم پر (اپنی خالقیت) ظاہر کردیں۔ اور ہم جس کو چاہتے ہیں ایک میعاد مقرر تک پیٹ میں ٹھہرائے رکھتے ہیں پھر تم کو بچہ بنا کر نکالتے ہیں۔ پھر تم جوانی کو پہنچتے ہو۔ اور بعض (قبل از پیری مرجاتے ہیں اور بعض شیخ فالی ہوجاتے اور بڑھاپے کی) نہایت خراب عمر کی طرف لوٹائے جاتے ہیں کہ بہت کچھ جاننے کے بعد بالکل بےعلم ہوجاتے ہیں۔ اور (اے دیکھنے والے) تو دیکھتا ہے (کہ ایک وقت میں) زمین خشک (پڑی ہوتی ہے) پھر جب ہم اس پر مینہ برساتے ہیں تو شاداب ہوجاتی اور ابھرنے لگتی ہے اور طرح طرح کی بارونق چیزیں اُگاتی ہے', NULL, NULL, '3579a05327d9dfad8f4922852faa2ada28478528ac33178ca2b1cef5b3ba888a')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 22, 6, 2601, 'ان قدرتوں سے ظاہر ہے کہ خدا ہی (قادر مطلق ہے جو) برحق ہے اور یہ کہ وہ مردوں کو زندہ کردیتا ہے۔ اور یہ کہ وہ ہر چیز پر قدرت رکھتا ہے', NULL, NULL, '49bb5fd4ff90db767503512171c06a7464c44ef79e4322b586241eec64343c73'),
  ('ur.jalandhry', 22, 7, 2602, 'اور یہ کہ قیامت آنے والی ہے۔ اس میں کچھ شک نہیں۔ اور یہ کہ خدا سب لوگوں کو جو قبروں میں ہیں جلا اٹھائے گا', NULL, NULL, '3d30d59acef8a0399e439e01303ffa41f1cfe61d853216e5e66e388e4855a0e2'),
  ('ur.jalandhry', 22, 8, 2603, 'اور لوگوں میں کوئی ایسا بھی ہے جو خدا (کی شان) میں بغیر علم (ودانش) کے اور بغیر ہدایت کے اور بغیر کتاب روشن کے جھگڑتا ہے', NULL, NULL, 'f25fbae04f4fb6163fee75fdf0800b01e5a2ffaffdbe95b1894727a1f5e5c99b'),
  ('ur.jalandhry', 22, 9, 2604, '(اور تکبر سے) گردن موڑ لیتا (ہے) تاکہ (لوگوں کو) خدا کے رستے سے گمراہ کردے۔ اس کے لئے دنیا میں ذلت ہے۔ اور قیامت کے دن ہم اسے عذاب (آتش) سوزاں کا مزہ چکھائیں گے', NULL, NULL, '5f8cb2fdad80cc77496a7850ab6b7191186c86493e5b2eafb0fc64dab1bff102'),
  ('ur.jalandhry', 22, 10, 2605, '(اے سرکش) یہ اس (کفر) کی سزا ہے جو تیرے ہاتھوں نے آگے بھیجا ہے اور خدا اپنے بندوں پر ظلم کرنے والا نہیں', NULL, NULL, '4acf3d0ac66baf014980a79da3179965c47c36e715f39963958575956f6d9905'),
  ('ur.jalandhry', 22, 11, 2606, 'اور لوگوں میں بعض ایسا بھی ہے جو کنارے پر (کھڑا ہو کر) خدا کی عبادت کرتا ہے۔ اگر اس کو کوئی (دنیاوی) فائدہ پہنچے تو اس کے سبب مطمئن ہوجائے اور اگر کوئی آفت پڑے تو منہ کے بل لوٹ جائے (یعنی پھر کافر ہوجائے) اس نے دنیا میں بھی نقصان اٹھایا اور آخرت میں بھی۔ یہی تو نقصان صریح ہے', NULL, NULL, '05b849c1ce7619f71a9624338b3ea39f6b8b6f4f6f531c480413a1b20f3f587d'),
  ('ur.jalandhry', 22, 12, 2607, 'یہ خدا کے سوا ایسی چیز کو پکارتا ہے جو نہ اسے نقصان پہنچائے اور نہ فائدہ دے سکے۔ یہی تو پرلے درجے کی گمراہی ہے', NULL, NULL, '29260fe2d462401527c1ca4aefd56aba7f5a79ea148215d44c249c3e077892dc'),
  ('ur.jalandhry', 22, 13, 2608, 'ایسے شخص کو پکارتا ہے جس کا نقصان فائدہ سے زیادہ قریب ہے۔ ایسا دوست برا بھی اور ایسا ہم صحبت بھی برا', NULL, NULL, '1ab5014299dbd53d4c0ba2a9ea60d67f7e5eb71bcf7fa531b70ed9c5e869ee9a'),
  ('ur.jalandhry', 22, 14, 2609, 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے خدا ان کو بہشتوں میں داخل کرے گا جن کے نیچے نہریں چل رہیں ہیں۔ کچھ شک نہیں کہ خدا جو چاہتا ہے کرتا ہے', NULL, NULL, 'c27b8766be221376aa4cb242635a228d9bca5ce3d5c290ff7ac44ae0b93ad0be'),
  ('ur.jalandhry', 22, 15, 2610, 'جو شخص یہ گمان کرتا ہے کہ خدا اس کو دنیا اور آخرت میں مدد نہیں دے گا تو اس کو چاہیئے کہ اوپر کی طرف (یعنی اپنے گھر کی چھت میں) ایک رسی باندھے پھر (اس سے اپنا) گلا گھونٹ لے۔ پھر دیکھے کہ آیا یہ تدبیر اس کے غصے کو دور کردیتی ہے', NULL, NULL, '0aa3811b0c6bfc06e41ca732cfe89b35dee01f49f9ce5f4c36168ff6f24e3d94'),
  ('ur.jalandhry', 22, 16, 2611, 'اور اسی طرح ہم نے اس قرآن کو اُتارا ہے (جس کی تمام) باتیں کھلی ہوئی (ہیں) اور یہ (یاد رکھو) کہ خدا جس کو چاہتا ہے ہدایات دیتا ہے', NULL, NULL, '3b7a153fb6bf99e8f6b7267d153a1ba7797a35b2859bd8bbaba3693f64cba697'),
  ('ur.jalandhry', 22, 17, 2612, 'جو لوگ مومن (یعنی مسلمان) ہیں اور جو یہودی ہیں اور ستارہ پرست اور عیسائی اور مجوسی اور مشرک۔ خدا ان (سب) میں قیامت کے دن فیصلہ کردے گا۔ بےشک خدا ہر چیز سے باخبر ہے', NULL, NULL, '06ee3560b2e552b13115eb2d8285b19fed3a6710db78ecf696b10ae2bb1fc158'),
  ('ur.jalandhry', 22, 18, 2613, 'کیا تم نے نہیں دیکھا کہ جو (مخلوق) آسمانوں میں ہے اور جو زمین میں ہے اور سورج اور چاند ستارے اور پہاڑ اور درخت اور چار پائے اور بہت سے انسان خدا کو سجدہ کرتے ہیں۔ اور بہت سے ایسے ہیں جن پر عذاب ثابت ہوچکا ہے۔ اور جس شخص کو خدا ذلیل کرے اس کو عزت دینے والا نہیں۔ بےشک خدا جو چاہتا ہے کرتا ہے', NULL, NULL, 'dee6014354ff6b0c9617ccb7fca94b274a050282a49782b7e66e73997e61f080'),
  ('ur.jalandhry', 22, 19, 2614, 'یہ دو (فریق) ایک دوسرے کے دشمن اپنے پروردگار (کے بارے) میں جھگڑتے ہیں۔ تو کافر ہیں ان کے لئے آگ کے کپڑے قطع کئے جائیں گے (اور) ان کے سروں پر جلتا ہوا پانی ڈالا جائے گا', NULL, NULL, 'a1516eb0203a3d562f6ecf08da2c80bba33f64d367e58768ddfe0689c6cab54e'),
  ('ur.jalandhry', 22, 20, 2615, 'اس سے ان کے پیٹ کے اندر کی چیزیں اور کھالیں گل جائیں گی', NULL, NULL, '0fb60888c219b6e6378f78d6517c756c409940e1d4b6b1964e2b60c1f87fde2d'),
  ('ur.jalandhry', 22, 21, 2616, 'اور ان (کے مارنے ٹھوکنے) کے لئے لوہے کے ہتھوڑے ہوں گے', NULL, NULL, 'fa16a5e5261b61d79b587c8ad3f7670e9bf1396f38f94ad6fcf9d9bbfaa2bd19'),
  ('ur.jalandhry', 22, 22, 2617, 'جب وہ چاہیں گے کہ اس رنج (وتکلیف) کی وجہ سے دوزخ سے نکل جائیں تو پھر اسی میں لوٹا دیئے جائیں گے۔ اور (کہا جائے گا کہ) جلنے کے عذاب کا مزہ چکھتے رہو', NULL, NULL, '1d96277785589bb505c49558655277648e195bf49777c083f4506c642c32e746'),
  ('ur.jalandhry', 22, 23, 2618, 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے خدا ان کو بہشتوں میں داخل کرے گا جن کے تلے نہریں بہہ رہیں ہیں۔ وہاں ان کو سونے کے کنگن پہنائے جائیں گے اور موتی۔ اور وہاں ان کا لباس ریشمی ہوگا', NULL, NULL, '7c9b8e40c66f01c708a1ff1b45779d782694a8f401f7e0b1ddcb98f4c8e4b6e9'),
  ('ur.jalandhry', 22, 24, 2619, 'اور ان کو پاکیزہ کلام کی ہدایت کی گئی اور (خدائے) حمید کی راہ بتائی گئی', NULL, NULL, '94ad62fb4423af8bb0ac68a4a2fb0c6587de06685d7911b0d43c9f68bcccbcd3'),
  ('ur.jalandhry', 22, 25, 2620, 'جو لوگ کافر ہیں اور (لوگوں کو) خدا کے رستے سے اور مسجد محترم سے جسے ہم نے لوگوں کے لئے یکساں (عبادت گاہ) بنایا ہے روکتے ہیں۔ خواہ وہاں کے رہنے والے ہوں یا باہر سے آنے والے۔ اور جو اس میں شرارت سے کج روی (وکفر) کرنا چاہے اس کو ہم درد دینے والے عذاب کا مزہ چکھائیں گے۔', NULL, NULL, 'bbba3598184354911ed47df92311df25f6688097a4e982e7e7639fe8381181b3'),
  ('ur.jalandhry', 22, 26, 2621, '(اور ایک وقت تھا) جب ہم نے ابراہیم کے لئے خانہ کعبہ کو مقرر کیا (اور ارشاد فرمایا) کہ میرے ساتھ کسی چیز کو شریک نہ کیجیو اور طواف کرنے والوں اور قیام کرنے والوں اور رکوع کرنے والوں (اور) سجدہ کرنے والوں کے لئے میرے گھر کو صاف رکھا کرو', NULL, NULL, '2fc54d91490aee89c4faf85c813a5f095c46a5de93e5170412bc6554a8947faa'),
  ('ur.jalandhry', 22, 27, 2622, 'اور لوگوں میں حج کے لئے ندا کر دو کہ تمہاری پیدل اور دبلے دبلے اونٹوں پر جو دور دراز رستوں سے چلے آتے ہو (سوار ہو کر) چلے آئیں', NULL, NULL, '79bcc72a837c42abdcfb4b0782582ca759026025402ed8db91d7c6cd0100b8c0'),
  ('ur.jalandhry', 22, 28, 2623, 'تاکہ اپنے فائدے کے کاموں کے لئے حاضر ہوں۔ اور (قربانی کے) ایام معلوم میں چہار پایاں مویشی (کے ذبح کے وقت) جو خدا نے ان کو دیئے ہیں ان پر خدا کا نام لیں۔ اس میں سے تم خود بھی کھاؤ اور فقیر درماندہ کو بھی کھلاؤ', NULL, NULL, '15e7cf8c3fa5f86ba94ad96023dfab362ac36d2d34c47fd7b3080e8452f58c2e'),
  ('ur.jalandhry', 22, 29, 2624, 'پھر چاہیئے کہ لوگ اپنا میل کچیل دور کریں اور نذریں پوری کریں اور خانہٴ قدیم (یعنی بیت الله) کا طواف کریں', NULL, NULL, 'ac78549ea281536249d01cd6472e3e27ac4b57403cfeb36c9d3fa32ee0851f9b'),
  ('ur.jalandhry', 22, 30, 2625, 'یہ (ہمارا حکم ہے) جو شخص ادب کی چیزوں کی جو خدا نے مقرر کی ہیں عظمت رکھے تو یہ پروردگار کے نزدیک اس کے حق میں بہتر ہے۔ اور تمہارے لئے مویشی حلال کردیئے گئے ہیں۔ سوا ان کے جو تمہیں پڑھ کر سنائے جاتے ہیں تو بتوں کی پلیدی سے بچو اور جھوٹی بات سے اجتناب کرو', NULL, NULL, '425b7a1b2a39d3757ffc842d882434ed9e9047ac100b2a88975f55f522902bdf'),
  ('ur.jalandhry', 22, 31, 2626, 'صرف ایک خدا کے ہو کر اس کے ساتھ شریک نہ ٹھیرا کر۔ اور جو شخص (کسی کو) خدا کے ساتھ شریک مقرر کرے تو وہ گویا ایسا ہے جیسے آسمان سے گر پڑے پھر اس کو پرندے اُچک لے جائیں یا ہوا کسی دور جگہ اُڑا کر پھینک دے', NULL, NULL, 'cfe294c47384cbb02d772b00914776b1f112e6dca1689d28d2910e6b9a1d2ee8'),
  ('ur.jalandhry', 22, 32, 2627, '(یہ ہمارا حکم ہے) اور جو شخص ادب کی چیزوں کی جو خدا نے مقرر کی ہیں عظمت رکھے تو یہ (فعل) دلوں کی پرہیزگاری میں سے ہے', NULL, NULL, '552c43c9f4b5ec85a94d2282994fd5ff71ea62a923c49d5e81633fed3c5b0a86'),
  ('ur.jalandhry', 22, 33, 2628, 'ان میں ایک وقت مقرر تک تمہارے لئے فائدے ہیں پھر ان کو خانہٴ قدیم (یعنی بیت الله) تک پہنچانا (اور ذبح ہونا) ہے', NULL, NULL, 'debcc9a59608d3ed4e0c003cbe19446b7c6d258bb176d0b7c1e66fce951814e5'),
  ('ur.jalandhry', 22, 34, 2629, 'اور ہم نے ہر اُمت کے لئے قربانی کا طریق مقرر کردیا ہے تاکہ جو مویشی چارپائے خدا نے ان کو دیئے ہیں (ان کے ذبح کرنے کے وقت) ان پر خدا کا نام لیں۔ سو تمہارا معبود ایک ہی ہے تو اسی کے فرمانبردار ہوجاؤ۔ اور عاجزی کرنے والوں کو خوشخبری سنادو', NULL, NULL, '8651eed5ce98c42834b745665f6321f9097d189914234020955db8d4dd0d0fb8'),
  ('ur.jalandhry', 22, 35, 2630, 'یہ وہ لوگ ہیں کہ جب خدا کا نام لیا جاتا ہے تو ان کے دل ڈر جاتے ہیں اور جب ان پر مصیبت پڑتی ہے تو صبر کرتے ہیں اور نماز آداب سے پڑھتے ہیں اور جو (مال) ہم نے ان کو عطا فرمایا ہے (اس میں سے) (نیک کاموں میں) خرچ کرتے ہیں', NULL, NULL, '299fd2d88f930a0a056f8df43fbcb154e6e77160e5ab1ae70e22e83d3da73a72'),
  ('ur.jalandhry', 22, 36, 2631, 'اور قربانی کے اونٹوں کو بھی ہم نے تمہارے لئے شعائر خدا مقرر کیا ہے۔ ان میں تمہارے لئے فائدے ہیں۔ تو (قربانی کرنے کے وقت) قطار باندھ کر ان پر خدا کا نام لو۔ جب پہلو کے بل گر پڑیں تو ان میں سے کھاؤ اور قناعت سے بیٹھ رہنے والوں اور سوال کرنے والوں کو بھی کھلاؤ۔ اس طرح ہم نے ان کو تمہارے زیرفرمان کردیا ہے تاکہ تم شکر کرو', NULL, NULL, '74c1370d918b89e67290faa151b51a7f5486dae42dc3dd87bcf8b76fb38d3d8f'),
  ('ur.jalandhry', 22, 37, 2632, 'خدا تک نہ اُن کا گوشت پہنچتا ہے اور نہ خون۔ بلکہ اس تک تمہاری پرہیزگاری پہنچتی ہے۔ اسی طرح خدا نے ان کو تمہارا مسخر کر دیا ہے تاکہ اس بات کے بدلے کہ اس نے تم کو ہدایت بخشی ہے اسے بزرگی سے یاد کرو۔ اور (اے پیغمبر) نیکوکاروں کو خوشخبری سنا دو', NULL, NULL, '4dfd66366d789b8df7e61d13b078a8de6955b2b495416558688b0408a92d1f58'),
  ('ur.jalandhry', 22, 38, 2633, 'خدا تو مومنوں سے ان کے دشمنوں کو ہٹاتا رہتا ہے۔ بےشک خدا کسی خیانت کرنے والے اور کفران نعمت کرنے والے کو دوست نہیں رکھتا۔', NULL, NULL, 'acb9948b91c540c01bbb33cc3416e272a5e5ef74f0c3742f7eff44cdb9a07b5e'),
  ('ur.jalandhry', 22, 39, 2634, 'جن مسلمانوں سے (خواہ مخواہ) لڑائی کی جاتی ہے ان کو اجازت ہے (کہ وہ بھی لڑیں) کیونکہ ان پر ظلم ہو رہا ہے۔ اور خدا (ان کی مدد کرے گا وہ) یقیناً ان کی مدد پر قادر ہے', NULL, NULL, '015b5aa5960ddd39859d332de3e54507e37d7b70a3b0ddd48f71b6c227f3ef09'),
  ('ur.jalandhry', 22, 40, 2635, 'یہ وہ لوگ ہیں کہ اپنے گھروں سے ناحق نکال دیئے گئے (انہوں نے کچھ قصور نہیں کیا) ہاں یہ کہتے ہیں کہ ہمارا پروردگار خدا ہے۔ اور اگر خدا لوگوں کو ایک دوسرے سے نہ ہٹاتا رہتا تو (راہبوں کے) صومعے اور (عیسائیوں کے) گرجے اور (یہودیوں کے) عبادت خانے اور (مسلمانوں کی) مسجدیں جن میں خدا کا بہت سا ذکر کیا جاتا ہے ویران ہوچکی ہوتیں۔ اور جو شخص خدا کی مدد کرتا ہے خدا اس کی ضرور مدد کرتا ہے۔ بےشک خدا توانا اور غالب ہے', NULL, NULL, '48e58e74a91b141b202af9a69fb2aa208be03635952217ae00d97c5c4b65191c'),
  ('ur.jalandhry', 22, 41, 2636, 'یہ وہ لوگ ہیں کہ اگر ہم ان کو ملک میں دسترس دیں تو نماز پڑھیں اور زکوٰة ادا کریں اور نیک کام کرنے کا حکم دیں اور برے کاموں سے منع کریں اور سب کاموں کا انجام خدا ہی کے اختیار میں ہے', NULL, NULL, 'a5408bd955c1b7706f37b77ddf0ccb3838ce75e9b3d57796c4e73c09a6f8e41c'),
  ('ur.jalandhry', 22, 42, 2637, 'اور اگر یہ لوگ تم کو جھٹلاتے ہیں ان سے پہلے نوح کی قوم اور عاد وثمود بھی (اپنے پیغمبروں کو) جھٹلا چکے ہیں', NULL, NULL, '80f6abfe2188a597b3c4bd85e58229352af0133208bb8907c68a6dfeddaa2887'),
  ('ur.jalandhry', 22, 43, 2638, 'اور قوم ابراہیم اور قوم لوط بھی', NULL, NULL, '51b9b1cc7bd6f32e9d744b7ca3913be676a86062cb0f6dd511544f7453f79adb'),
  ('ur.jalandhry', 22, 44, 2639, 'اور مدین کے رہنے والے بھی۔ اور موسیٰ بھی تو جھٹلائے جاچکے ہیں لیکن میں کافروں کو مہلت دیتا رہا پھر ان کو پکڑ لیا۔ تو (دیکھ لو) کہ میرا عذاب کیسا (سخت) تھا', NULL, NULL, '59ebd4639e77514f02c2ec85714874f89fd903643b4b0f815aeff6ee310e1ff0'),
  ('ur.jalandhry', 22, 45, 2640, 'اور بہت سی بستیاں ہیں کہ ہم نے ان کو تباہ کر ڈالا کہ وہ نافرمان تھیں۔ سو وہ اپنی چھتوں پر گری پڑی ہیں۔ اور (بہت سے) کنوئیں بےکار اور (بہت سے) محل ویران پڑے ہیں', NULL, NULL, 'f19379f192df677ea99714ea9f261728b68a3ff2c0a66c65d16eca95d36d4fb2'),
  ('ur.jalandhry', 22, 46, 2641, 'کیا ان لوگوں نے ملک میں سیر نہیں کی تاکہ ان کے دل (ایسے) ہوتے کہ ان سے سمجھ سکتے۔ اور کان (ایسے) ہوتے کہ ان سے سن سکتے۔ بات یہ ہے کہ آنکھیں اندھی نہیں ہوتیں بلکہ دل جو سینوں میں ہیں (وہ) اندھے ہوتے ہیں', NULL, NULL, '2df534fecab58d107ccdbf4730dfd97a437b7cd1d2b7aa3dbc4f1acc30dcbb4a'),
  ('ur.jalandhry', 22, 47, 2642, 'اور (یہ لوگ) تم سے عذاب کے لئے جلدی کر رہے ہیں اور خدا اپنا وعدہ ہرگز خلاف نہیں کرے گا۔ اور بےشک تمہارے پروردگار کے نزدیک ایک روز تمہارے حساب کے رو سے ہزار برس کے برابر ہے', NULL, NULL, 'fad4d63e470450e3ea925b3d8c4949a2639b588e311de1a3ab734fb3a84ccbb5'),
  ('ur.jalandhry', 22, 48, 2643, 'اور بہت سی بستیاں ہیں کہ میں ان کو مہلت دیتا رہا اور وہ نافرمان تھیں۔ پھر میں نے ان کو پکڑ لیا۔ اور میری طرف ہی لوٹ کر آنا ہے', NULL, NULL, 'f8e0cd805db127e60080d78428d1d7785fa287e79bc1be0dc939c1d7361ad4cd'),
  ('ur.jalandhry', 22, 49, 2644, '(اے پیغمبر) کہہ دو کہ لوگو! میں تم کو کھلم کھلا نصیحت کرنے والا ہوں', NULL, NULL, '6218e82e6b94d7d5272d6fcbda4e6afba78680bfcc6b1b29addedf7c1407db8a'),
  ('ur.jalandhry', 22, 50, 2645, 'تو جو لوگ ایمان لائے اور نیک کام کئے ان کے لئے بخشش اور آبرو کی روزی ہے', NULL, NULL, '4937cecf4e7b394e18c0aa06f99cca26ade1e1021a48e1c9193b3564a6c9d7bf'),
  ('ur.jalandhry', 22, 51, 2646, 'اور جن لوگوں نے ہماری آیتوں میں (اپنے زعم باطل میں) ہمیں عاجز کرنے کے لئے سعی کی، وہ اہل دوزخ ہیں', NULL, NULL, '145d961d35f311d668b350bd5c6fb11452ed2a2bd84e86068705ca48190acb9c'),
  ('ur.jalandhry', 22, 52, 2647, 'اور ہم نے تم سے پہلے کوئی رسول اور نبی نہیں بھیجا مگر (اس کا یہ حال تھا کہ) جب وہ کوئی آرزو کرتا تھا تو شیطان اس کی آرزو میں (وسوسہ) ڈال دیتا تھا۔ تو جو (وسوسہ) شیطان ڈالتا ہے خدا اس کو دور کردیتا ہے۔ پھر خدا اپنی آیتوں کو مضبوط کردیتا ہے۔ اور خدا علم والا اور حکمت والا ہے', NULL, NULL, 'd40694b718906cf5e5ef149bc40726a3d1a36e1d904fb34b75ba2b45ebf8e28d'),
  ('ur.jalandhry', 22, 53, 2648, 'غرض (اس سے) یہ ہے کہ جو (وسوسہ) شیطان ڈالتا ہے اس کو ان لوگوں کے لئے جن کے دلوں میں بیماری ہے اور جن کے دل سخت ہیں ذریعہ آزمائش ٹھہرائے۔ بےشک ظالم پرلے درجے کی مخالفت میں ہیں', NULL, NULL, '58ee3205990bda1d32dcbb837de1ee22a9091cd4e3e786b3503a5157f1eb3ec2'),
  ('ur.jalandhry', 22, 54, 2649, 'اور یہ بھی غرض ہے کہ جن لوگوں کو علم عطا ہوا ہے وہ جان لیں کہ وہ (یعنی وحی) تمہارے پروردگار کی طرف سے حق ہے تو وہ اس پر ایمان لائیں اور ان کے دل خدا کے آگے عاجزی کریں۔ اور جو لوگ ایمان لائے ہیں خدا ان کو سیدھے رستے کی طرف ہدایت کرتا ہے', NULL, NULL, '6b380caf67db1b10c79c1954f305e769a735388697453ff974c06ccf60ea0912'),
  ('ur.jalandhry', 22, 55, 2650, 'اور کافر لوگ ہمیشہ اس سے شک میں رہیں گے یہاں تک کہ قیامت ان پر ناگہاں آجائے یا ایک نامبارک دن کا عذاب ان پر واقع ہو', NULL, NULL, '0da1277b4773f26a2d0c72d4980103b2bf2d3dc8ddc5aed0ad6a269304bf3e8b'),
  ('ur.jalandhry', 22, 56, 2651, 'اس روز بادشاہی خدا ہی کی ہوگی۔ اور ان میں فیصلہ کردے گا تو جو لوگ ایمان لائے اور عمل نیک کرتے رہے وہ نعمت کے باغوں میں ہوں گے', NULL, NULL, '1bf04536beb6cc1aecbd2b7f8c295f79155d1ffbfe5d0f18d344989d126ae883'),
  ('ur.jalandhry', 22, 57, 2652, 'اور جو کافر ہوئے اور ہماری آیتوں کو جھٹلاتے رہے ان کے لئے ذلیل کرنے والا عذاب ہوگا', NULL, NULL, '71c4043930d126d6d1d92ccd92aad41f5c134d1050f8b068bc0f5b7e71bea2de'),
  ('ur.jalandhry', 22, 58, 2653, 'اور جن لوگوں نے خدا کی راہ میں ہجرت کی پھر مارے گئے یا مر گئے۔ ان کو خدا اچھی روزی دے گا۔ اور بےشک خدا سب سے بہتر رزق دینے والا ہے', NULL, NULL, '3178d224f0f6b9e7f6a86eff123dc7a99dc6d796ebcf6eb2841fbba6db5291b6'),
  ('ur.jalandhry', 22, 59, 2654, 'وہ ان کو ایسے مقام میں داخل کرے گا جسے وہ پسند کریں گے۔ اور خدا تو جاننے والا (اور) بردبار ہے', NULL, NULL, 'b35566ddccadd17baeed7d3de756b104f99479f1eedf996460e5d694cdbce203'),
  ('ur.jalandhry', 22, 60, 2655, 'یہ (بات خدا کے ہاں ٹھہر چکی ہے) اور جو شخص (کسی کو) اتنی ہی ایذا دے جتنی ایذا اس کو دی گئی پھر اس شخص پر زیادتی کی جائے تو خدا اس کی مدد کرے گا۔ بےشک خدا معاف کرنے والا اور بخشنے والا ہے', NULL, NULL, 'e85eed20e96cadfd52194d6ba1f7ba0795b68018e141a2218441a2d0ec165a05'),
  ('ur.jalandhry', 22, 61, 2656, 'یہ اس لئے کہ خدا رات کو دن میں داخل کردیتا ہے اور دن کو رات میں داخل کرتا ہے۔ اور خدا تو سننے والا دیکھنے والا ہے', NULL, NULL, '8e67a926203cb0c7783d3faace4aee27d6d9e47bf21f3649c94c6765de647a4e'),
  ('ur.jalandhry', 22, 62, 2657, 'یہ اس لئے کہ خدا ہی برحق ہے اور جس چیز کو (کافر) خدا کے سوا پکارتے ہیں وہ باطل ہے اور اس لئے خدا رفیع الشان اور بڑا ہے', NULL, NULL, '29ef912ad6c99acb81bea60fbb33c4243a7476a8c01b1bef95fa47777851d0eb'),
  ('ur.jalandhry', 22, 63, 2658, 'کیا تم نہیں دیکھتے کہ خدا آسمان سے مینہ برساتا ہے تو زمین سرسبز ہوجاتی ہے۔ بےشک خدا باریک بین اور خبردار ہے', NULL, NULL, '567005dbf080ffe882b1f105e9ce80c967def5cd42be3ffdb7d9322f801fd966'),
  ('ur.jalandhry', 22, 64, 2659, 'جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اسی کا ہے۔ اور بےشک خدا بےنیاز اور قابل ستائش ہے۔', NULL, NULL, '6b553ed9d5e7402cc529bd8a44c79186d889801cbccb722dcaf13414026fd07e'),
  ('ur.jalandhry', 22, 65, 2660, 'کیا تم نہیں دیکھتے کہ جتنی چیزیں زمین میں ہیں (سب) خدا نے تمہارے زیرفرمان کر رکھی ہیں اور کشتیاں (بھی) جو اسی کے حکم سے دریا میں چلتی ہیں۔ اور وہ آسمان کو تھامے رہتا ہے کہ زمین پر (نہ) گڑ پڑے مگر اس کے حکم سے۔ بےشک خدا لوگوں پر نہایت شفقت کرنے والا مہربان ہے', NULL, NULL, '5e22a3f29c90cc573fd8b21aa1b0cda11174c2c079b34b3bc7cdde44d1d28e78'),
  ('ur.jalandhry', 22, 66, 2661, 'اور وہی تو ہے جس نے تم کو حیات بخشی۔ پھر تم کو مارتا ہے۔ پھر تمہیں زندہ بھی کرے گا۔ اور انسان تو بڑا ناشکر ہے', NULL, NULL, '16c24e9f4b3327930dc78187402fc9273a0dade17b7173286eb1a6f275a44201'),
  ('ur.jalandhry', 22, 67, 2662, 'ہم نے ہر ایک اُمت کے لئے ایک شریعت مقرر کردی ہے جس پر وہ چلتے ہیں تو یہ لوگ تم سے اس امر میں جھگڑا نہ کریں اور تم (لوگوں کو) اپنے پروردگار کی طرف بلاتے رہو۔ بےشک تم سیدھے رستے پر ہو', NULL, NULL, '61404b78e197366665c969bc7bf2855c5b6824bb4afaf04a9103bb7da024fac8'),
  ('ur.jalandhry', 22, 68, 2663, 'اور اگر یہ تم سے جھگڑا کریں تو کہہ دو کہ جو عمل تم کرتے ہو خدا ان سے خوب واقف ہے', NULL, NULL, 'a2d8cc40a344444127889f8490a9e276d8c231d5fe94c82da84b146715270e22'),
  ('ur.jalandhry', 22, 69, 2664, 'جن باتوں میں تم اختلاف کرتے ہو خدا تم میں قیامت کے روز ان کا فیصلہ کردے گا', NULL, NULL, '19ac1107b11b86b79ed110641926b697feebcee4e7d82658ee1dbf46f098f1d0'),
  ('ur.jalandhry', 22, 70, 2665, 'کیا تم نہیں جانتے کہ جو کچھ آسمان اور زمین میں ہے خدا اس کو جانتا ہے۔ یہ (سب کچھ) کتاب میں (لکھا ہوا) ہے۔ بےشک یہ سب خدا کو آسان ہے', NULL, NULL, '7c6e6848f04504164c184086a4500a3fc1c62507900eb0487239256a66dec63c'),
  ('ur.jalandhry', 22, 71, 2666, 'اور (یہ لوگ) خدا کے سوا ایسی چیزوں کی عبادت کرتے ہیں جن کی اس نے کوئی سند نازل نہیں فرمائی اور نہ ان کے پاس اس کی کوئی دلیل ہے۔ اور ظالموں کا کوئی بھی مددگار نہیں ہوگا', NULL, NULL, '5e115089f186e0a7d8700ef6ba800e25b625ee71f7a1cdd2fc393d8020177ad6'),
  ('ur.jalandhry', 22, 72, 2667, 'اور جب ان کو ہماری آیتیں پڑھ کر سنائی جاتی تو (ان کی شکل بگڑ جاتی ہے اور) تم ان کے چہروں میں صاف طور پر ناخوشی (کے آثار) دیکھتے ہو۔ قریب ہوتے ہیں کہ جو لوگ ان کو ہماری آیتیں پڑھ کر سناتے ہیں ان پر حملہ کردیں۔ کہہ دو کہ میں تم کو اس سے بھی بری چیز بتاؤں؟ وہ دوزخ کی آگ ہے۔ جس کا خدا نے کافروں سے وعدہ کیا ہے۔ اور وہ برا ٹھکانا ہے', NULL, NULL, '1b7ed0ed1bd36c11bfdfe1dd07048e09f48e65a4686e7835e9a173b733b54db9'),
  ('ur.jalandhry', 22, 73, 2668, 'لوگو! ایک مثال بیان کی جاتی ہے اسے غور سے سنو۔ کہ جن لوگوں کو تم خدا کے سوا پکارتے ہو وہ ایک مکھی بھی نہیں بنا سکتے اگرچہ اس کے لئے سب مجتمع ہوجائیں۔ اور اگر ان سے مکھی کوئی چیز لے جائے تو اسے اس سے چھڑا نہیں سکتے۔ طالب اور مطلوب (یعنی عابد اور معبود دونوں) گئے گزرے ہیں', NULL, NULL, '3d084d8b3c73c0d584dfcbafb5d7e909d25fe397b37a61efaf4e419383922b2f'),
  ('ur.jalandhry', 22, 74, 2669, 'ان لوگوں نے خدا کی قدر جیسی کرنی چاہیئے تھی نہیں کی۔ کچھ شک نہیں کہ خدا زبردست اور غالب ہے', NULL, NULL, '16536dc9a617cbb19f77ad75168dfed06247e4cf56c3d8df88c0b49bbc020939'),
  ('ur.jalandhry', 22, 75, 2670, 'خدا فرشتوں میں سے پیغام پہنچانے والے منتخب کرلیتا ہے اور انسانوں میں سے بھی۔ بےشک خدا سننے والا (اور) دیکھنے والا ہے', NULL, NULL, 'd6c6ed7a09c58c079cddaf3f1b7aa3b7a40e09b3702a793e2a69f2d16ad1be9d'),
  ('ur.jalandhry', 22, 76, 2671, 'جو ان کے آگے ہے اور جن ان کے پیچھے ہے وہ اس سے واقف ہے۔ اور سب کاموں کا رجوع خدا ہی کی طرف ہے', NULL, NULL, 'bd18c6009d88fc9f4ed93783f1bc327a6b09db8183e8cc2532e8da8fc657a3ef'),
  ('ur.jalandhry', 22, 77, 2672, 'مومنو! رکوع کرتے اور سجدے کرتے اور اپنے پروردگار کی عبادت کرتے رہو اور نیک کام کرو تاکہ فلاح پاؤ', NULL, NULL, '248975a4eba8463a63ced65aaeff10d1850bbcad1c5992403d92a1e4fd4180e0'),
  ('ur.jalandhry', 22, 78, 2673, 'اور خدا (کی راہ) میں جہاد کرو جیسا جہاد کرنے کا حق ہے۔ اس نے تم کو برگزیدہ کیا ہے اور تم پر دین کی (کسی بات) میں تنگی نہیں کی۔ (اور تمہارے لئے) تمہارے باپ ابراہیم کا دین (پسند کیا) اُسی نے پہلے (یعنی پہلی کتابوں میں) تمہارا نام مسلمان رکھا تھا اور اس کتاب میں بھی (وہی نام رکھا ہے تو جہاد کرو) تاکہ پیغمبر تمہارے بارے میں شاہد ہوں۔ اور تم لوگوں کے مقابلے میں شاہد اور نماز پڑھو اور زکوٰة دو اور خدا کے دین کی (رسی کو) پکڑے رہو۔ وہی تمہارا دوست ہے۔ اور خوب دوست اور خوب مددگار ہے', NULL, NULL, 'b10a3be7bda1947f4e3281f25de32e2e476855dba1df2497800ee6a53541ce8b'),
  ('ur.jalandhry', 23, 1, 2674, 'بےشک ایمان والے رستگار ہوگئے', NULL, NULL, '9d3819727dc574b5ffea8b61c3229e400eaf56796beda7d957a584f1fc383476'),
  ('ur.jalandhry', 23, 2, 2675, 'جو نماز میں عجزو نیاز کرتے ہیں', NULL, NULL, 'f83dba1dcf9dd70e777e0a6faa62db8e819ad00567277367213b5832f17aa32a'),
  ('ur.jalandhry', 23, 3, 2676, 'اور جو بیہودہ باتوں سے منہ موڑے رہتے ہیں', NULL, NULL, 'ee342fda0cab8d052224a0c8663ac788fd0f1f85e665f68c24e0b94f562663f6'),
  ('ur.jalandhry', 23, 4, 2677, 'اور جو زکوٰة ادا کرتے ہیں', NULL, NULL, 'b54ec103850d048333e96178914e8c9abae0a8a98a357423358add9cef2e11e5'),
  ('ur.jalandhry', 23, 5, 2678, 'اور جو اپنی شرمگاہوں کی حفاظت کرتے ہیں', NULL, NULL, 'f9d8d481ebd5be1413c3123fea4b571c0214690f4701e70816a7fcf5851b16bf'),
  ('ur.jalandhry', 23, 6, 2679, 'مگر اپنی بیویوں سے یا (کنیزوں سے) جو ان کی مِلک ہوتی ہیں کہ (ان سے) مباشرت کرنے سے انہیں ملامت نہیں', NULL, NULL, 'ddfb14c990add0701bc94ea8c401100d8b706bb018bd66779d9a7c5a7a03ed95'),
  ('ur.jalandhry', 23, 7, 2680, 'اور جو ان کے سوا اوروں کے طالب ہوں وہ (خدا کی مقرر کی ہوئی حد سے) نکل جانے والے ہیں', NULL, NULL, '0cc453e81159e7aff62592071ac63cfb3fa9624789a721902393199330bb5a41'),
  ('ur.jalandhry', 23, 8, 2681, 'اور جو امانتوں اور اقراروں کو ملحوظ رکھتے ہیں', NULL, NULL, '2b29b83cf9100788d20833e82f369435cd064af29664f2c594e613f8de9f1477'),
  ('ur.jalandhry', 23, 9, 2682, 'اور جو نمازوں کی پابندی کرتے ہیں', NULL, NULL, 'e729762f54dd59782d19d2209495d04831174e19fddc7f86206147576d3d0f3a'),
  ('ur.jalandhry', 23, 10, 2683, 'یہ ہی لوگ میراث حاصل کرنے والے ہیں', NULL, NULL, 'd6e184965765f470deb8edd9854dfbdeca5ba5fa7726db8ab7783d4f31fbec89'),
  ('ur.jalandhry', 23, 11, 2684, '(یعنی) جو بہشت کی میراث حاصل کریں گے۔ اور اس میں ہمیشہ رہیں گے', NULL, NULL, '26c1daa764f1e2a9c4d2209614befcc5c5193281aacd9b35b4ab110a74a0f0ce'),
  ('ur.jalandhry', 23, 12, 2685, 'اور ہم نے انسان کو مٹی کے خلاصے سے پیدا کیا ہے', NULL, NULL, '6e9661fa7c8b7c9ae020f2fa97416ccca4ae31011d3b01daecd6e32cee8afb8a'),
  ('ur.jalandhry', 23, 13, 2686, 'پھر اس کو ایک مضبوط (اور محفوظ) جگہ میں نطفہ بنا کر رکھا', NULL, NULL, '77f513d0963324b68b500580b386966c2922af73b3098abfba59f65b36ffeceb'),
  ('ur.jalandhry', 23, 14, 2687, 'پھر نطفے کا لوتھڑا بنایا۔ پھر لوتھڑے کی بوٹی بنائی پھر بوٹی کی ہڈیاں بنائیں پھر ہڈیوں پر گوشت (پوست) چڑھایا۔ پھر اس کو نئی صورت میں بنا دیا۔ تو خدا جو سب سے بہتر بنانے والا بڑا بابرکت ہے', NULL, NULL, '503c31b15e57cd5a11ec400a29ed807233ac74f14dea721946a6d4da8c2fec5c'),
  ('ur.jalandhry', 23, 15, 2688, 'پھر اس کے بعد تم مرجاتے ہو', NULL, NULL, '80cb5b23821c0236bec9597913eb6a896eebb68bb2ab95bd4e588344e63b19b9'),
  ('ur.jalandhry', 23, 16, 2689, 'پھر قیامت کے روز اُٹھا کھڑے کئے جاؤ گے', NULL, NULL, '90098f21fe2b59a9f4a6cc06520bd8b30b19e0960b8905a67aa75885b688b465'),
  ('ur.jalandhry', 23, 17, 2690, 'اور ہم نے تمہارے اوپر (کی جانب) سات آسمان پیدا کئے۔ اور ہم خلقت سے غافل نہیں ہیں', NULL, NULL, '5d4e5296ecb53d45360043cc9124ef53c98a766584ec7d6a0305bbec405e36b1'),
  ('ur.jalandhry', 23, 18, 2691, 'اور ہم ہی نے آسمان سے ایک اندازے کے ساتھ پانی نازل کیا۔ پھر اس کو زمین میں ٹھہرا دیا اور ہم اس کے نابود کردینے پر بھی قادر ہیں', NULL, NULL, '0c23462481d28b50a786a75a999d42d2ba2e3a2039be9cf49f43ed8cc3c87f44'),
  ('ur.jalandhry', 23, 19, 2692, 'پھر ہم نے اس سے تمہارے لئے کھجوروں اور انگوروں کے باغ بنائے، ان میں تمہارے لئے بہت سے میوے پیدا ہوتے ہیں۔ اور ان میں سے تم کھاتے بھی ہو', NULL, NULL, '18a46700fb78da6b0ce98a9058a59c21854e4a081c8d83bf158ef0081bc04d05'),
  ('ur.jalandhry', 23, 20, 2693, 'اور وہ درخت بھی (ہم ہی نے پیدا کیا) جو طور سینا میں پیدا ہوتا ہے (یعنی زیتون کا درخت کہ) کھانے کے لئے روغن اور سالن لئے ہوئے اُگتا ہے', NULL, NULL, '2a61d79af9636e2a8563d97c83efba03f6b730b733c457e88543ac9ec0f61bb7'),
  ('ur.jalandhry', 23, 21, 2694, 'اور تمہارے لئے چارپایوں میں بھی عبرت (اور نشانی) ہے کہ ان کے پیٹوں میں ہے اس سے ہم تمہیں (دودھ) پلاتے ہیں اور تمہارے لئے ان میں اور بھی بہت سے فائدے ہیں اور بعض کو تم کھاتے بھی ہو', NULL, NULL, '198fc87ed59f87e6b322489a1e51406fd24fde35a2f7175e59fec23a6b989627'),
  ('ur.jalandhry', 23, 22, 2695, 'اور ان پر اور کشتیوں پر تم سوار ہوتے ہو', NULL, NULL, '49457c97dae9358b88905d333782eff719589a09add8d5450cdd8224a9a1175f'),
  ('ur.jalandhry', 23, 23, 2696, 'اور ہم نے نوح کو ان کی قوم کی طرف بھیجا تو انہوں نے ان سے کہا کہ اے قوم! خدا ہی کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں، کیا تم ڈرتے نہیں', NULL, NULL, '37787bf30481e27828f533f08e585790cd27c18543be686c68497345abcc419b'),
  ('ur.jalandhry', 23, 24, 2697, 'تو ان کی قوم کے سردار جو کافر تھے کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے۔ تم پر بڑائی حاصل کرنی چاہتا ہے۔ اور اگر خدا چاہتا تو فرشتے اُتار دیتا۔ ہم نے اپنے اگلے باپ دادا میں تو یہ بات کبھی سنی نہیں تھی', NULL, NULL, 'abbef5c27bc520221314f224833e68c8eb2d6e655a3cc0b5433de91a37b2536b'),
  ('ur.jalandhry', 23, 25, 2698, 'اس آدمی کو تو دیوانگی (کا عارضہ) ہے تو اس کے بارے میں کچھ مدت انتظار کرو', NULL, NULL, 'cc23bae43f86e467553086aabf8c2f106ccadcd259e9f770b0e79f03386f7e21'),
  ('ur.jalandhry', 23, 26, 2699, 'نوح نے کہا کہ پروردگار انہوں نے مجھے جھٹلایا ہے تو میری مدد کر', NULL, NULL, 'f76a37e0db6b6a89bed8f9c2bf7e0d2f75f1c9e32b40d745020d822b7c8a405a'),
  ('ur.jalandhry', 23, 27, 2700, 'پس ہم نے ان کی طرف وحی بھیجی کہ ہمارے سامنے اور ہمارے حکم سے ایک کشتی بناؤ۔ پھر جب ہمارا حکم آ پہنچے اور تنور (پانی سے بھر کر) جوش مارنے لگے تو سب (قسم کے حیوانات) میں جوڑا جوڑا (یعنی نر اور مادہ) دو دو کشتی میں بٹھا دو اور اپنے گھر والوں کو بھی، سو ان کے جن کی نسبت ان میں سے (ہلاک ہونے کا) حکم پہلے صادر ہوچکا ہے۔ اور ظالموں کے بارے میں ہم سے کچھ نہ کہنا، وہ ضرور ڈبو دیئے جائیں گے', NULL, NULL, '6a71d0133a2e79ab373ffb9cdcb35525a1d5fb2e7bb1808ba47b5ec074aae521')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 23, 28, 2701, 'اور جب تم اور تمہارے ساتھی کشتی میں بیٹھ جاؤ تو (خدا کا شکر کرنا اور) کہنا کہ سب تعریف خدا ہی کو (سزاوار) ہے۔ جس نے ہم کو نجات بخشی ظالم لوگوں سے', NULL, NULL, '3023995dcbcd2dafbdaacdc182d90f52c8ca8fb72bbb5c8259f51cd5a865fd5b'),
  ('ur.jalandhry', 23, 29, 2702, 'اور (یہ بھی) دعا کرنا کہ اے پروردگار ہم کو مبارک جگہ اُتاریو اور تو سب سے بہتر اُتارنے والا ہے', NULL, NULL, 'b628e090db9d5b6fbdb0f6be597121dde7aac1bc767c8a1dc14038a841aad7af'),
  ('ur.jalandhry', 23, 30, 2703, 'بےشک اس (قصے) میں نشانیاں ہیں اور ہمیں تو آزمائش کرنی تھی', NULL, NULL, '9c21aa4081ad03388ad7b16c6aaa2b7e255893e529f763137e6f43a4856faf06'),
  ('ur.jalandhry', 23, 31, 2704, 'پھر ان کے بعد ہم نے ایک اور جماعت پیدا کی', NULL, NULL, '3a329bea8885c8901c5d4b4b548ad7667dec61078b506619406c49f48c40b4eb'),
  ('ur.jalandhry', 23, 32, 2705, 'اور ان ہی میں سے ان میں ایک پیغمبر بھیجا (جس نے ان سے کہا) کہ خدا ہی کی عبادت کرو (کہ) اس کے سوا تمہارا کوئی معبود نہیں، تو کیا تم ڈرتے نہیں', NULL, NULL, 'e7a9b90fc6b68eee38e8c8fd751ce4ebc705354c61c8c43fece1747f0125d1c8'),
  ('ur.jalandhry', 23, 33, 2706, 'تو ان کی قوم کے سردار جو کافر تھے اور آخرت کے آنے کو جھوٹ سمجھتے تھے اور دنیا کی زندگی میں ہم نے ان کو آسودگی دے رکھی تھی۔ کہنے لگے کہ یہ تو تم ہی جیسا آدمی ہے، جس قسم کا کھانا تم کھاتے ہو، اسی طرح کا یہ بھی کھاتا ہے اور جو پانی تم پیتے ہو اسی قسم کا یہ بھی پیتا ہے', NULL, NULL, '8de0546e8826f3a92fa29ff1e3b8e7addbaa402acd6722b17593c2901ee4302d'),
  ('ur.jalandhry', 23, 34, 2707, 'اور اگر تم اپنے ہی جیسے آدمی کا کہا مان لیا تو گھاٹے میں پڑ گئے', NULL, NULL, '46df12e67a0579d27670dbf147f5a440f0383bf195e7ccfc40a5178445f46007'),
  ('ur.jalandhry', 23, 35, 2708, 'کیا یہ تم سے یہ کہتا ہے کہ جب تم مر جاؤ گے اور مٹی ہو جاؤ گے اور استخوان (کے سوا کچھ نہ رہے گا) تو تم (زمین سے) نکالے جاؤ گے', NULL, NULL, 'a522daface0e2971fd9f61dbecf75df76f19be62a4154ae6a222f115b22f23db'),
  ('ur.jalandhry', 23, 36, 2709, 'جس بات کا تم سے وعدہ کیا جاتا ہے (بہت) بعید اور (بہت) بعید ہے', NULL, NULL, 'b007a75c24bc6e846576f6822bc03357791262e334a9dbd74604f1c3d9536434'),
  ('ur.jalandhry', 23, 37, 2710, 'زندگی تو یہی ہماری دنیا کی زندگی ہے کہ (اسی میں) ہم مرتے اور جیتے ہیں، اور ہم پھر نہیں اُٹھائے جائیں گے', NULL, NULL, '4a8a4482cf15ec70672339a0de94440679a9645228a610742be77c10c38b095b'),
  ('ur.jalandhry', 23, 38, 2711, 'یہ تو ایک ایسا آدمی ہے جس نے خدا پر جھوٹ افتراء کیا ہے اور ہم اس کو ماننے والے نہیں', NULL, NULL, '3a9cc1be7c95ec138039eebca6bc7536699a91752c89f5faad6f814d1124b65e'),
  ('ur.jalandhry', 23, 39, 2712, 'پیغمبر نے کہا کہ اے پروردگار انہوں نے مجھے جھوٹا سمجھا ہے تو میری مدد کر', NULL, NULL, '4767584f4fcea8795a62e8557b01515d77655373b0a39622897607f741939843'),
  ('ur.jalandhry', 23, 40, 2713, 'فرمایا کہ یہ تھوڑے ہی عرصے میں پشیمان ہو کر رہ جائیں گے', NULL, NULL, '2f24f4da09f281cdf1b09693f47e57cdb509ce2f6826903de96bea12059b6176'),
  ('ur.jalandhry', 23, 41, 2714, 'تو ان کو (وعدہٴ برحق کے مطابق) زور کی آواز نے آپکڑا، تو ہم نے ان کو کوڑا کرڈالا۔ پس ظالم لوگوں پر لعنت ہے', NULL, NULL, '351066b4f35d8825f8a1350dd68b88d91e3635e7b49b279b65f1fa10ddd78863'),
  ('ur.jalandhry', 23, 42, 2715, 'پھر ان کے بعد ہم نے اور جماعتیں پیدا کیں', NULL, NULL, '8435db20415c2add02641346fcfb126b7e40d95708229b0cd8bf5bdd1b1c944c'),
  ('ur.jalandhry', 23, 43, 2716, 'کوئی جماعت اپنے وقت سے نہ آگے جاسکتی ہے نہ پیچھے رہ سکتی ہے', NULL, NULL, '1e7a79cbd48b7e33159fa4e4f03c481ef7546e7ef314b275a2aadd1329e61cc1'),
  ('ur.jalandhry', 23, 44, 2717, 'پھر ہم نے پے درپے اپنے پیغمبر بھیجتے رہے۔ جب کسی اُمت کے پاس اس کا پیغمبر آتا تھا تو وہ اسے جھٹلاتے تھے تو ہم بھی بعض کو بعض کے پیچھے (ہلاک کرتے اور ان پر عذاب) لاتے رہے اور ان کے افسانے بناتے رہے۔ پس جو لوگ ایمان نہیں لاتے ان پر لعنت', NULL, NULL, '71cccf463d3a44aff4a446440cf54e4aa8fbb05bad899f2a5f3978c942c5d70c'),
  ('ur.jalandhry', 23, 45, 2718, 'پھر ہم نے موسیٰ اور ان کے بھائی ہارون کو اپنی نشانیاں اور دلیل ظاہر دے کر بھیجا', NULL, NULL, '16bdcc5d5d29a42715cfe15c522f52390b651cc42c582cda224738f2b140b5e0'),
  ('ur.jalandhry', 23, 46, 2719, '(یعنی) فرعون اور اس کی جماعت کی طرف، تو انہوں نے تکبر کیا اور وہ سرکش لوگ تھے', NULL, NULL, 'ff0dcaf6350e67f1cfb8eb73189b7d1c22d2788757d5a4600549a66dd0cbe821'),
  ('ur.jalandhry', 23, 47, 2720, 'کہنے لگے کہ کیا ہم ان اپنے جیسے دو آدمیوں پر ایمان لے آئیں اور اُن کو قوم کے لوگ ہمارے خدمت گار ہیں', NULL, NULL, '3a5fec891c41bf1f872aded0a73a3288739310ad748569753c22649ba6ea2895'),
  ('ur.jalandhry', 23, 48, 2721, 'تو اُن لوگوں نے اُن کی تکذیب کی سو (آخر) ہلاک کر دیئے گئے', NULL, NULL, '5afc9a9e9e74f1cc5385a6cc2f32c87ddb03f2776567cd20dda91181fea5e596'),
  ('ur.jalandhry', 23, 49, 2722, 'اور ہم نے موسیٰ کو کتاب دی تھی تاکہ وہ لوگ ہدایت پائیں', NULL, NULL, '6037f56696f740ad13f28570eaf745e841193ac2a4e27a7373c8b709b3abd772'),
  ('ur.jalandhry', 23, 50, 2723, 'اور ہم نے مریم کے بیٹے (عیسیٰ) اور ان کی ماں کو (اپنی) نشانی بنایا تھا اور ان کو ایک اونچی جگہ پر جو رہنے کے لائق تھی اور جہاں (نتھرا ہوا) پانی جاری تھا، پناہ دی تھی', NULL, NULL, '3ba25857bef1ac7c0623999680521596ae66685fd94987112d16cedb386f097b'),
  ('ur.jalandhry', 23, 51, 2724, 'اے پیغمبرو! پاکیزہ چیزیں کھاؤ اور عمل نیک کرو۔ جو عمل تم کرتے ہو میں ان سے واقف ہوں', NULL, NULL, '070fc82204159b1287ea57a5dd942edaae07fe785fc8eb3bd49e245d394a14a5'),
  ('ur.jalandhry', 23, 52, 2725, 'اور یہ تمہاری جماعت (حقیقت میں) ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو مجھ سے ڈرو', NULL, NULL, 'd119515d67add95e0e685b1c1050f22742b794f06f25dc96e4358d3c7a6a1344'),
  ('ur.jalandhry', 23, 53, 2726, 'تو پھر آپس میں اپنے کام کو متفرق کرکے جدا جدا کردیا۔ جو چیزیں جس فرقے کے پاس ہے وہ اس سے خوش ہو رہا ہے', NULL, NULL, '77dac952f860164084b5ee208fd7621d8318b151bdb90e58a08e8fd380c3f2aa'),
  ('ur.jalandhry', 23, 54, 2727, 'تو ان کو ایک مدت تک ان کی غفلت میں رہنے دو', NULL, NULL, 'd4e5eaa0cf8c6b1a212d0ddbc7754a0a4f261e0470afd333c7f6bd05295a15b7'),
  ('ur.jalandhry', 23, 55, 2728, 'کیا یہ لوگ خیال کرتے ہیں کہ ہم جو دنیا میں ان کو مال اور بیٹوں سے مدد دیتے ہیں', NULL, NULL, 'cefaec086b4da292327769bc1f7daf571e71e4b5e9fd213975486d468cfdf9fd'),
  ('ur.jalandhry', 23, 56, 2729, 'تو (اس سے) ان کی بھلائی میں جلدی کر رہے ہیں (نہیں) بلکہ یہ سمجھتے ہی نہیں', NULL, NULL, '0f0a4d1e324691a3ca0e5cb1972fb57b3649f3db68f07b1ce6631810ef805990'),
  ('ur.jalandhry', 23, 57, 2730, 'جو اپنے پروردگار کے خوف سے ڈرتے ہیں', NULL, NULL, '9cfec6556ef504fe6195cd45212f4a54040d9a48d26665e777997f40236240ab'),
  ('ur.jalandhry', 23, 58, 2731, 'اور جو اپنے پروردگار کی آیتوں پر ایمان رکھتے ہیں', NULL, NULL, '5929a508780ee986729a43c378404076f4739a29efb49cdc97f25e9ef859f102'),
  ('ur.jalandhry', 23, 59, 2732, 'اور جو اپنے پروردگار کے ساتھ شریک نہیں کرتے', NULL, NULL, '0fe385c28dd42ae84e7067b3610f9647deef0116b248d05267a9543593eaf677'),
  ('ur.jalandhry', 23, 60, 2733, 'اور جو دے سکتے ہیں دیتے ہیں اور ان کے دل اس بات سے ڈرتے رہتے ہیں کہ ان کو اپنے پروردگار کی لوٹ کر جانا ہے', NULL, NULL, 'f27d4fb6d53db10e002e192753628ce7ebb2f3edf016ecb7b55ebb71584b3f28'),
  ('ur.jalandhry', 23, 61, 2734, 'یہی لوگ نیکیوں میں جلدی کرے اور یہی اُن کے لئے آگے نکل جاتے ہیں', NULL, NULL, '8620bf92094d6d7d37064218988ae53ece438f013182e4e4efdad5074cea1aad'),
  ('ur.jalandhry', 23, 62, 2735, 'اور ہم کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے اور ہمارے پاس کتاب ہے جو سچ سچ کہہ دیتی ہے اور ان لوگوں پر ظلم نہیں کیا جائے گا', NULL, NULL, '3ed83b78e066632d5ecc272efaaad1d7e3804f9cb3a280e2344b31309bd735a8'),
  ('ur.jalandhry', 23, 63, 2736, 'مگر ان کے دل ان (باتوں) کی طرف سے غفلت میں (پڑے ہوئے) ہیں، اور ان کے سوا اور اعمال بھی ہیں جو یہ کرتے رہتے ہیں', NULL, NULL, '0b17fd29760ca3899ed62424beee51833f87c5c916d201dff2a67b9857fe5511'),
  ('ur.jalandhry', 23, 64, 2737, 'یہاں تک کہ جب ہم نے ان میں سے آسودہ حال لوگوں کو پکڑ لیا تو وہ اس وقت چلاّئیں گے', NULL, NULL, '51731c405145da50970911eba067a044f3c8427bb5297c7de7164b7a059d7a4f'),
  ('ur.jalandhry', 23, 65, 2738, 'آج مت چلاّؤ! تم کو ہم سے کچھ مدد نہیں ملے گی', NULL, NULL, '33433831401867dda9d18a716e450cc2276f6723d6c089989177e611704ac932'),
  ('ur.jalandhry', 23, 66, 2739, 'میری آیتیں تم کو پڑھ پڑھ کر سنائی جاتی تھیں اور تم الٹے پاؤں پھر پھر جاتے تھے', NULL, NULL, 'a4e531b01eaba326e62d080e2fd8d8a80d3db715754555f6012ef18adb8727da'),
  ('ur.jalandhry', 23, 67, 2740, 'ان سے سرکشی کرتے، کہانیوں میں مشغول ہوتے اور بیہودہ بکواس کرتے تھے', NULL, NULL, '365de1a0e9c1cdd3a2910dbb99b690c73106c14dfa42b5064bf12379a691b9e7'),
  ('ur.jalandhry', 23, 68, 2741, 'کیا انہوں نے اس کلام میں غور نہیں کیا یا ان کے پاس کوئی ایسی چیز آئی ہے جو ان کے اگلے باپ دادا کے پاس نہیں تھی', NULL, NULL, '3ca71c4f1d0661e9dff82f3c802ba926d01a2446cd9405f5b580ed07b99f729e'),
  ('ur.jalandhry', 23, 69, 2742, 'یا یہ اپنے پیغمبر کو جانتے پہنچانتے نہیں، اس وجہ سے ان کو نہیں مانتے', NULL, NULL, '22181ddd866440329acee312953aa26ffc651992a0e260f0c14b00a987dc7796'),
  ('ur.jalandhry', 23, 70, 2743, 'کیا یہ کہتے ہیں کہ اسے سودا ہے (نہیں) بلکہ وہ ان کے پاس حق کو لے کر آئے ہیں اور ان میں سے اکثر حق کو ناپسند کرتے ہیں', NULL, NULL, '53eb823a0d6eb2910e36c77629b8db5818cf6b183b3d9dff42315ead841646be'),
  ('ur.jalandhry', 23, 71, 2744, 'اور خدائے (برحق) ان کی خواہشوں پر چلے تو آسمان اور زمین اور جو ان میں ہیں سب درہم برہم ہوجائیں۔ بلکہ ہم نے ان کے پاس ان کی نصیحت (کی کتاب) پہنچا دی ہے اور وہ اپنی (کتاب) نصیحت سے منہ پھیر رہے ہیں', NULL, NULL, 'a4733424e06b12134ef7fb09c588ff56844582fe7d69bcf21706ac2cd6c8eadc'),
  ('ur.jalandhry', 23, 72, 2745, 'کیا تم ان سے (تبلیغ کے صلے میں) کچھ مال مانگتے ہو، تو تمہارا پروردگار کا مال بہت اچھا ہے اور وہ سب سے بہتر رزق دینے والا ہے', NULL, NULL, '269d12b31af732299741dadb18b1ebb551b128ee1e1289724097a36905a49ba8'),
  ('ur.jalandhry', 23, 73, 2746, 'اور تم تو ان کو سیدھے راستے کی طرف بلاتے ہو', NULL, NULL, '78bdb70edafa6985383a867a8a5e1d61a679f3d5adba504685bb6bfd471012b2'),
  ('ur.jalandhry', 23, 74, 2747, 'اور جو لوگ آخرت پر ایمان نہیں لاتے وہ رستے سے الگ ہو رہے ہیں', NULL, NULL, '946ba27861db08a3465abc953c869b099ff386397e7dcc28a43269a8a6e40ec6'),
  ('ur.jalandhry', 23, 75, 2748, 'اور اگر ہم ان پر رحم کریں اور جو تکلیفیں ان کو پہنچ رہی ہیں، وہ دور کردیں تو اپنی سرکشی پر اڑے رہیں (اور) بھٹکتے (پھریں)', NULL, NULL, 'a91ec1d2f2857e65a2ef65acb9f0a58badee6594f4ab0ec4b9a554fd9984895f'),
  ('ur.jalandhry', 23, 76, 2749, 'اور ہم نے ان کو عذاب میں پکڑا تو بھی انہوں نے خدا کے آگے عاجزی نہ کی اور وہ عاجزی کرتے ہی نہیں', NULL, NULL, '4f3b4e6a72dab4e8ffa34e067f61c2228bfe090b94e604c31b4ea797af24db0d'),
  ('ur.jalandhry', 23, 77, 2750, 'یہاں تک کہ جب ہم نے پر عذاب شدید کا دروازہ کھول دیا تو اس وقت وہاں ناامید ہوگئے', NULL, NULL, '7a9a1fa764b627deb9b1e10315749446cf6859db9ddf503cb4162c161f29d56c'),
  ('ur.jalandhry', 23, 78, 2751, 'اور وہی تو ہے جس نے تمہارے کان اور آنکھیں اور دل بنائے۔ (لیکن) تم کم شکرگزاری کرتے ہو', NULL, NULL, '0d213d9c39dc68a44bbe628812639876993968246c4338f395d6307a42a87577'),
  ('ur.jalandhry', 23, 79, 2752, 'اور وہی تو ہے جس نے تم کو زمین میں پیدا کیا اور اسی کی طرف تم جمع ہو کر جاؤ گے', NULL, NULL, '600bad17f783c3225771d65cbc9fc7a53fec3876c8cd4bd83056cbacb4571ad9'),
  ('ur.jalandhry', 23, 80, 2753, 'اور وہی ہے جو زندگی بخشتا ہے اور موت دیتا ہے اور رات اور دن کا بدلتے رہنا اسی کا تصرف ہے، کیا تم سمجھتے نہیں', NULL, NULL, '840dc2db80f190eba2fb4f640a8b4d46830b44746de4031bc012004260af35d2'),
  ('ur.jalandhry', 23, 81, 2754, 'بات یہ ہے کہ جو بات اگلے (کافر) کہتے تھے اسی طرح کی (بات یہ) کہتے ہیں', NULL, NULL, '02ffcee4b89714246d410c9679e142e196f5ee2ed0d2476a48c41a76dbf4ccf9'),
  ('ur.jalandhry', 23, 82, 2755, 'کہتے ہیں کہ جب ہم مر جائیں گے اور مٹی ہو جائیں گے اور استخوان (بوسیدہ کے سوا کچھ) نہ رہے گا تو کیا ہم پھر اٹھائے جائیں گے؟', NULL, NULL, '5ba51d91768f61729bd072ea7e2b21d95adcbff40466849ac9e1411dc17ae788'),
  ('ur.jalandhry', 23, 83, 2756, 'یہ وعدہ ہم سے اور ہم سے پہلے ہمارے باپ دادا سے بھی ہوتا چلا آیا ہے (اجی) یہ تو صرف اگلے لوگوں کی کہانیاں ہیں', NULL, NULL, 'ba2623dcdd21683f930b7ac9b553c5ffc5493d12639fb8981b413957dfd3bb4d'),
  ('ur.jalandhry', 23, 84, 2757, 'کہو کہ اگر تم جانتے ہو تو بتاؤ کہ زمین اور جو کچھ زمین میں ہے سب کس کا مال ہے؟', NULL, NULL, 'e73d7bbd727fec8fdb1d6c670d8a713d1dbd9086cbd26353e036d01c680532b9'),
  ('ur.jalandhry', 23, 85, 2758, 'جھٹ بول اٹھیں گے کہ خدا کا۔ کہو کہ پھر تم سوچتے کیوں نہیں؟', NULL, NULL, 'c826cef1b85764f168168b958f31516bb6f21710192d7f881539d9d3c24fda0b'),
  ('ur.jalandhry', 23, 86, 2759, '(ان سے) پوچھو کہ سات آسمانوں کا کون مالک ہے اور عرش عظیم کا (کون) مالک (ہے؟)', NULL, NULL, '01aa6841ed5ad88ed9bd1c434020e769806bf5c503a9b8cb83ac5ba980e3d4fa'),
  ('ur.jalandhry', 23, 87, 2760, 'بےساختہ کہہ دیں گے کہ یہ (چیزیں) خدا ہی کی ہیں، کہو کہ پھر تم ڈرتے کیوں نہیں؟', NULL, NULL, '99b2216bd252df9804376ce819578f035b2c7eb2e055f4ad69ac750877f9ca28'),
  ('ur.jalandhry', 23, 88, 2761, 'کہو کہ اگر تم جانتے ہو تو بتاؤ کہ وہ کون ہے جس کے ہاتھ میں ہر چیز کی بادشاہی ہے اور وہ پناہ دیتا ہے اور اس کے مقابل کوئی کسی کو پناہ نہیں دے سکتا', NULL, NULL, '6f5712e8a37fa2325049831d6ce5628479211589e1a013004e8cd169b9d6d0fd'),
  ('ur.jalandhry', 23, 89, 2762, 'فوراً کہہ دیں گے کہ (ایسی بادشاہی تو) خدا ہی کی ہے، تو کہو پھر تم پر جادو کہاں سے پڑ جاتا ہے؟', NULL, NULL, '0c3b862ac693bf6cb2da2fb80b79a89ddb00df0315591e7ea2738d9291a05c7c'),
  ('ur.jalandhry', 23, 90, 2763, 'بات یہ ہے کہ ہم نے ان کے پاس حق پہنچا دیا ہے اور جو (بت پرستی کئے جاتے ہیں) بےشک جھوٹے ہیں', NULL, NULL, 'f4aad54f6136465b5c5ebc09a29648c701f058fe4bbf43c7b6ac6091fa11242d'),
  ('ur.jalandhry', 23, 91, 2764, 'خدا نے نہ تو (اپنا) کسی کو بیٹا بنایا ہے اور نہ اس کے ساتھ کوئی معبود ہے، ایسا ہوتا تو ہر معبود اپنی اپنی مخلوقات کو لے کر چل دیتا اور ایک دوسرے پر غالب آجاتا۔ یہ لوگ جو کچھ خدا کے بارے میں بیان کرتے ہیں خدا اس سے پاک ہے', NULL, NULL, '6ba1633b3d694d21b6662f5d7807abbe4437eb92000b763a246e531d2b66068d'),
  ('ur.jalandhry', 23, 92, 2765, 'وہ پوشیدہ اور ظاہر کو جانتا ہے اور (مشرک) جو اس کے ساتھ شریک کرتے ہیں اس کی شان اس سے اونچی ہے', NULL, NULL, '7f88bc9aec0e61101c3f39308ade80f805dfa8c31c5030ce748ce92526c839e3'),
  ('ur.jalandhry', 23, 93, 2766, '(اے محمدﷺ) کہو کہ اے پروردگار جس عذاب کا ان (کفار) سے وعدہ ہو رہا ہے، اگر تو میری زندگی میں ان پر نازل کرکے مجھے بھی دکھادے', NULL, NULL, '9124d5f2de568251d3ae3e26404681597f0cedf9765cccf6cef6c97315cb4616'),
  ('ur.jalandhry', 23, 94, 2767, 'تو اے پروردگار مجھے (اس سے محفوظ رکھیئے اور) ان ظالموں میں شامل نہ کیجیئے', NULL, NULL, 'f9ff94583b6635c861f21b98f2a36740811624c6f71cf1b50089e11524caf635'),
  ('ur.jalandhry', 23, 95, 2768, 'اور جو وعدہ ہم ان سے کر رہے ہیں ہم تم کو دکھا کر ان پر نازل کرنے پر قادر ہیں', NULL, NULL, '1d8476febc13498f94346a136e37594e301b5a1100af73418175d589203e24ce'),
  ('ur.jalandhry', 23, 96, 2769, 'اور بری بات کے جواب میں ایسی بات کہو جو نہایت اچھی ہو۔ اور یہ جو کچھ بیان کرتے ہیں ہمیں خوب معلوم ہے', NULL, NULL, '70255b96c81eb4dcc5b63a90489b6b61763860f7610ac8912c69678d543e3ee6'),
  ('ur.jalandhry', 23, 97, 2770, 'اور کہو کہ اے پروردگار! میں شیطانوں کے وسوسوں سے تیری پناہ مانگتا ہو', NULL, NULL, 'b339d73616eae3c7576b49fc059824644657a3e2d34ee7fed97335684497109b'),
  ('ur.jalandhry', 23, 98, 2771, 'اور اے پروردگار! اس سے بھی تیری پناہ مانگتا ہوں کہ وہ میرے پاس آموجود ہوں', NULL, NULL, 'ad20e15052bd48d5de2d9710828b22064aa2ba3442903bb58320b3411252b7f1'),
  ('ur.jalandhry', 23, 99, 2772, '(یہ لوگ اسی طرح غفلت میں رہیں گے) یہاں تک کہ جب ان میں سے کسی کے پاس موت آجائے گی تو کہے گا کہ اے پروردگار! مجھے پھر (دنیا میں) واپس بھیج دے', NULL, NULL, 'd5d7a0c27dd44851d928333ebbe44804fda79f30cb6e6d28b35fcb655ec57223'),
  ('ur.jalandhry', 23, 100, 2773, 'تاکہ میں اس میں جسے چھوڑ آیا ہوں نیک کام کیا کروں۔ ہرگز نہیں۔ یہ ایک ایسی بات ہے کہ وہ اسے زبان سے کہہ رہا ہوگا (اور اس کے ساتھ عمل نہیں ہوگا) اور اس کے پیچھے برزخ ہے (جہاں وہ) اس دن تک کہ (دوبارہ) اٹھائے جائیں گے، (رہیں گے)', NULL, NULL, '30dcdf22f70121145a95e4374d335e7f437af0e17912103b20198d3c774ba089'),
  ('ur.jalandhry', 23, 101, 2774, 'پھر جب صور پھونکا جائے گا تو نہ تو ان میں قرابتیں ہوں گی اور نہ ایک دوسرے کو پوچھیں گے', NULL, NULL, '1771d2f4369bc6b088960fc1170c9dd61ab718c1fcdc5d12e22d97ce8208471e'),
  ('ur.jalandhry', 23, 102, 2775, 'تو جن کے (عملوں کے) بوجھ بھاری ہوں گے۔ وہ فلاح پانے والے ہیں', NULL, NULL, 'f817e9ce81c40da51c8609ce0dacc4bee588b7a151e6a5bca322455545a2356f'),
  ('ur.jalandhry', 23, 103, 2776, 'اور جن کے بوجھ ہلکے ہوں گے وہ لوگ ہیں جنہوں نے اپنے تئیں خسارے میں ڈالا، ہمیشہ دوزخ میں رہیں گے', NULL, NULL, '2d3cd7a1df5e04921f8e520d47b2d956f031ba3206347f51d7363e54d6ab40bd'),
  ('ur.jalandhry', 23, 104, 2777, 'آگ ان کے مونہوں کو جھلس دے گی اور وہ اس میں تیوری چڑھائے ہوں گے', NULL, NULL, 'b1ca97ca3627d5152fb5c03e0c8e72ad66ccbf7eb5119169bf96b12c81dee54a'),
  ('ur.jalandhry', 23, 105, 2778, 'کیا تم کو میری آیتیں پڑھ کر نہیں سنائی جاتیں تھیں (نہیں) تم ان کو سنتے تھے (اور) جھٹلاتے تھے', NULL, NULL, 'db023ac24537f8bcf8880f8d82eb13ec7242955f82f2033c59d7d8fd9ef6447e'),
  ('ur.jalandhry', 23, 106, 2779, 'اے ہمارے پروردگار! ہم پر ہماری کم بختی غالب ہوگئی اور ہم رستے سے بھٹک گئے', NULL, NULL, '9793de6f8752729ab64fdc94153d9f5df4476e31fa6fe30857396462a14a6bf6'),
  ('ur.jalandhry', 23, 107, 2780, 'اے پروردگار! ہم کو اس میں سے نکال دے، اگر ہم پھر (ایسے کام) کریں تو ظالم ہوں گے', NULL, NULL, '523d849c1de02f8e969ed1fec82f116181ca1311551128a52d27f859d4aae058'),
  ('ur.jalandhry', 23, 108, 2781, '(خدا) فرمائے گا کہ اسی میں ذلت کے ساتھ پڑے رہو اور مجھ سے بات نہ کرو', NULL, NULL, 'b35f414d29a80e3b812bda010e4cc2ecfa9cceab66efb5500bc23043c0050b21'),
  ('ur.jalandhry', 23, 109, 2782, 'میرے بندوں میں ایک گروہ تھا جو دعا کیا کرتا تھا کہ اے ہمارے پروردگار ہم ایمان لائے تو تُو ہم کو بخش دے اور ہم پر رحم کر اور تو سب سے بہتر رحم کرنے والا ہے', NULL, NULL, '9796779d2466ea484e4e98823361c3e702b2eb3f507f47d44f3e5fa75c9c5df8'),
  ('ur.jalandhry', 23, 110, 2783, 'تو تم ان سے تمسخر کرتے رہے یہاں تک کہ ان کے پیچھے میری یاد بھی بھول گئے اور تم (ہمیشہ) ان سے ہنسی کیا کرتے تھے', NULL, NULL, '49d94f1e5a9b5a8e71973f3e1a215b27c034c762a4594bb1efe9cc75b7e14bd7'),
  ('ur.jalandhry', 23, 111, 2784, 'آج میں نے اُن کو اُن کے صبر کا بدلہ دیا، کہ وہ کامیاب ہوگئے', NULL, NULL, 'aeceb2f16504143106dfe8122bec9d5a7830cab41431f01423bb7f05d41e4982'),
  ('ur.jalandhry', 23, 112, 2785, '(خدا) پوچھے گا کہ تم زمین میں کتنے برس رہے؟', NULL, NULL, '70ec60df47070824f31a0d54365f356260321796cd412b97cfcca55f45589b49'),
  ('ur.jalandhry', 23, 113, 2786, 'وہ کہیں گے کہ ہم ایک روز یا ایک روز سے بھی کم رہے تھے، شمار کرنے والوں سے پوچھ لیجیئے', NULL, NULL, '143dbc2533acebcf07cd9f60cb343b2cbe560fabf2e7edcd10a70b0446768757'),
  ('ur.jalandhry', 23, 114, 2787, '(خدا) فرمائے گا کہ (وہاں) تم (بہت ہی) کم رہے۔ کاش تم جانتے ہوتے', NULL, NULL, '15ee66ffe4d40e696702755295b0cd7ed29174aba89a58a213541d616cec04e5'),
  ('ur.jalandhry', 23, 115, 2788, 'کیا تم یہ خیال کرتے ہو کہ ہم نے تم کو بےفائدہ پیدا کیا ہے اور یہ تم ہماری طرف لوٹ کر نہیں آؤ گے؟', NULL, NULL, 'a6e99ad1709a60816a9e4f91d4c5c96da72a131d1da1e362aab5249e099655f8'),
  ('ur.jalandhry', 23, 116, 2789, 'تو خدا جو سچا بادشاہ ہے (اس کی شان) اس سے اونچی ہے، اس کے سوا کوئی معبود نہیں، وہی عرش بزرگ کا مالک ہے', NULL, NULL, '62a34a84f205a89151ac612eb69bc6bb5a7303c94196ba3c0475b2e8ef444bfb'),
  ('ur.jalandhry', 23, 117, 2790, 'اور جو شخص خدا کے ساتھ اور معبود کو پکارتا ہے جس کی اس کے پاس کچھ بھی سند نہیں تو اس کا حساب خدا ہی کے ہاں ہوگا۔ کچھ شک نہیں کہ کافر رستگاری نہیں پائیں گے', NULL, NULL, '0d68ac7b19b42905ac4784314c19ae8efa47a4fa2d65436768af13944436c9ba'),
  ('ur.jalandhry', 23, 118, 2791, 'اور خدا سے دعا کرو کہ میرے پروردگار مجھے بخش دے اور (مجھ پر) رحم کر اور تو سب سے بہتر رحم کرنے والا ہے', NULL, NULL, 'eaafa8c953aa1b1efeb843f215252e82574ac64150d3f78ad26a6f39ad11df42'),
  ('ur.jalandhry', 24, 1, 2792, 'یہ (ایک) سورت ہے جس کو ہم نے نازل کیا اور اس (کے احکام) کو فرض کر دیا، اور اس میں واضح المطالب آیتیں نازل کیں تاکہ تم یاد رکھو', NULL, NULL, 'b9da604154d8dec2e85662d4b9f113efd40812bce65f1714c4684bb7a7bbd5d2'),
  ('ur.jalandhry', 24, 2, 2793, 'بدکاری کرنے والی عورت اور بدکاری کرنے والا مرد (جب ان کی بدکاری ثابت ہوجائے تو) دونوں میں سے ہر ایک کو سو درے مارو۔ اور اگر تم خدا اور روز آخرت پر ایمان رکھتے ہو تو شرع خدا (کے حکم) میں تمہیں ان پر ہرگز ترس نہ آئے۔ اور چاہیئے کہ ان کی سزا کے وقت مسلمانوں کی ایک جماعت بھی موجود ہو', NULL, NULL, '72a6fad0fd1d06d375ff8e29eb22ae2dab6bd6014c3562b60d39450e2ca97932'),
  ('ur.jalandhry', 24, 3, 2794, 'بدکار مرد تو بدکار یا مشرک عورت کے سوا نکاح نہیں کرتا اور بدکار عورت کو بھی بدکار یا مشرک مرد کے سوا اور کوئی نکاح میں نہیں لاتا اور یہ (یعنی بدکار عورت سے نکاح کرنا) مومنوں پر حرام ہے', NULL, NULL, 'f5f28a7cb72af663ae4d5db75997b74c745d0dd66956c0ac6223c15eb6e106e9'),
  ('ur.jalandhry', 24, 4, 2795, 'اور جو لوگ پرہیزگار عورتوں کو بدکاری کا عیب لگائیں اور اس پر چار گواہ نہ لائیں تو ان کو اسی درے مارو اور کبھی ان کی شہادت قبول نہ کرو۔ اور یہی بدکردار ہیں', NULL, NULL, 'af9cdfd4a1b520920e7bd22a274eae120eb8214fa241b1a5747a7db3b4691c31'),
  ('ur.jalandhry', 24, 5, 2796, 'ہاں جو اس کے بعد توبہ کرلیں اور (اپنی حالت) سنوار لیں تو خدا (بھی) بخشنے والا مہربان ہے', NULL, NULL, '4041509333da693045c54dc44428cee48634d197911f8fb31694e161ec7f8e94'),
  ('ur.jalandhry', 24, 6, 2797, 'اور جو لوگ اپنی عورتوں پر بدکاری کی تہمت لگائیں اور خود ان کے سوا ان کے گواہ نہ ہوں تو ہر ایک کی شہادت یہ ہے کہ پہلے تو چار بار خدا کی قسم کھائے کہ بےشک وہ سچا ہے', NULL, NULL, '60b5601116ffddaca7673e7bbd80e857ed60b204b7adcd695f631d5730e5671a'),
  ('ur.jalandhry', 24, 7, 2798, 'اور پانچویں بار یہ (کہے) کہ اگر وہ جھوٹا ہو تو اس پر خدا کی لعنت', NULL, NULL, '1e8b062970da8b85c0e974955a5696bf9fb59c984d1d86c79118689de98cf7d2'),
  ('ur.jalandhry', 24, 8, 2799, 'اور عورت سے سزا کو یہ بات ٹال سکتی ہے کہ وہ پہلے چار بار خدا کی قسم کھائے کہ بےشک یہ جھوٹا ہے', NULL, NULL, '49cc50633bc0cea6740603af2735ac89f39d0ef1987c26a9a08d21b74c20e5ca'),
  ('ur.jalandhry', 24, 9, 2800, 'اور پانچویں دفعہ یوں (کہے) کہ اگر یہ سچا ہو تو مجھ پر خدا کا غضب (نازل ہو)', NULL, NULL, 'e6c83cca63f4c6f1587e11484bb2e8b809fa0ba1670cdf1f840dbd5c29cf7339')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 24, 10, 2801, 'اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو بہت سی خرابیاں پیدا ہوجاتیں۔ مگر وہ صاحب کرم ہے اور یہ کہ خدا توبہ قبول کرنے والا حکیم ہے', NULL, NULL, 'cc1f8709ab836e6843ed46770dcb907e3cc214755e412da855e6b62ec98ed64e'),
  ('ur.jalandhry', 24, 11, 2802, 'جن لوگوں نے بہتان باندھا ہے تم ہی میں سے ایک جماعت ہے اس کو اپنے حق میں برا نہ سمجھنا۔ بلکہ وہ تمہارے لئے اچھا ہے۔ ان میں سے جس شخص نے گناہ کا جتنا حصہ لیا اس کے لئے اتنا ہی وبال ہے۔ اور جس نے ان میں سے اس بہتان کا بڑا بوجھ اٹھایا ہے اس کو بڑا عذاب ہوگا', NULL, NULL, '08fc5e113a92c9c5ee8ef9a3512cd329139b5efe847ad982941c050979ffe121'),
  ('ur.jalandhry', 24, 12, 2803, 'جب تم نے وہ بات سنی تھی تو مومن مردوں اور عورتوں نے کیوں اپنے دلوں میں نیک گمان نہ کیا۔ اور کیوں نہ کہا کہ یہ صریح طوفان ہے', NULL, NULL, '8b5428eb8d20d65211654cc9741fdc9ff81c24e1f65a7cf6e7e4e91ef3b66ef8'),
  ('ur.jalandhry', 24, 13, 2804, 'یہ (افتراء پرداز) اپنی بات (کی تصدیق) کے (لئے) چار گواہ کیوں نہ لائے۔ تو جب یہ گواہ نہیں لاسکے تو خدا کے نزدیک یہی جھوٹے ہیں', NULL, NULL, '603c87c86f8bdcdac82769c13a38f78db7e5aa00f1286148ad15b709c245a227'),
  ('ur.jalandhry', 24, 14, 2805, 'اور اگر دنیا اور آخرت میں تم پر خدا کا فضل اور اس کی رحمت نہ ہوتی تو جس بات کا تم چرچا کرتے تھے اس کی وجہ سے تم پر بڑا (سخت) عذاب نازل ہوتا', NULL, NULL, '7d9d37b2e2df802f45b2b1ea60a4422f0d8ba6b7df765d89a173684ffe924aff'),
  ('ur.jalandhry', 24, 15, 2806, 'جب تم اپنی زبانوں سے اس کا ایک دوسرے سے ذکر کرتے تھے اور اپنے منہ سے ایسی بات کہتے تھے جس کا تم کو کچھ علم نہ تھا اور تم اسے ایک ہلکی بات سمجھتے تھے اور خدا کے نزدیک وہ بڑی بھاری بات تھی', NULL, NULL, '7fdac1af2b746a3f1f324eb932baa16625496f3166d334321195d4344bf5d9ae'),
  ('ur.jalandhry', 24, 16, 2807, 'اور جب تم نے اسے سنا تھا تو کیوں نہ کہہ دیا کہ ہمیں شایاں نہیں کہ ایسی بات زبان پر نہ لائیں۔ (پروردگار) تو پاک ہے یہ تو (بہت) بڑا بہتان ہے', NULL, NULL, '1a83d64f19b1cdb7060b7a71423e294b7093de686f0f04082f1adcd51776f963'),
  ('ur.jalandhry', 24, 17, 2808, 'خدا تمہیں نصیحت کرتا ہے کہ اگر مومن ہو تو پھر کبھی ایسا کام نہ کرنا', NULL, NULL, '5954595c2b3749ffc64107e229699d8ecd2eddc1997d000fd644f15c05228d98'),
  ('ur.jalandhry', 24, 18, 2809, 'اور خدا تمہارے (سمجھانے کے لئے) اپنی آیتیں کھول کھول کر بیان فرماتا ہے۔ اور خدا جاننے والا حکمت والا ہے', NULL, NULL, 'a981cd30e3d15c4916ae785689911eb35756035f782d23a84c93b247cc47a6a3'),
  ('ur.jalandhry', 24, 19, 2810, 'اور جو لوگ اس بات کو پسند کرتے ہیں کہ مومنوں میں بےحیائی یعنی (تہمت بدکاری کی خبر) پھیلے ان کو دنیا اور آخرت میں دکھ دینے والا عذاب ہوگا۔ اور خدا جانتا ہے اور تم نہیں جانتے', NULL, NULL, '8f219b86ad1df15cb6c7520c6326bed320f0c5e8515e66f3a479e6931cd0cf9a'),
  ('ur.jalandhry', 24, 20, 2811, 'اور اگر تم پر خدا کا فضل اور اس کی رحمت نہ ہوتی (تو کیا کچھ نہ ہوتا مگر وہ کریم ہے) اور یہ کہ خدا نہایت مہربان اور رحیم ہے', NULL, NULL, 'bae6991ed97d8b47603b31a4c634a2f724451f69b392d6d619a233cc1670dd56'),
  ('ur.jalandhry', 24, 21, 2812, 'اے مومنو! شیطان کے قدموں پر نہ چلنا۔ اور جو شخص شیطان کے قدموں پر چلے گا تو شیطان تو بےحیائی (کی باتیں) اور برے کام ہی بتائے گا۔ اور اگر تم پر خدا کا فضل اور اس کی مہربانی نہ ہوتی تو ایک شخص بھی تم میں پاک نہ ہوسکتا۔ مگر خدا جس کو چاہتا ہے پاک کردیتا ہے۔ اور خدا سننے والا (اور) جاننے والا ہے', NULL, NULL, '4b1887211144b2244059142588b4cbc9f132ae1a87cbec9b240e7e6856c1ac92'),
  ('ur.jalandhry', 24, 22, 2813, 'اور جو لوگ تم میں صاحب فضل (اور صاحب) وسعت ہیں، وہ اس بات کی قسم نہ کھائیں کہ رشتہ داروں اور محتاجوں اور وطن چھوڑ جانے والوں کو کچھ خرچ پات نہیں دیں گے۔ ان کو چاہیئے کہ معاف کردیں اور درگزر کریں۔ کیا تم پسند نہیں کرتے کہ خدا تم کو بخش دے؟ اور خدا تو بخشنے والا مہربان ہے', NULL, NULL, 'e80640ce7761370a2db28c82d723f96f9c329ed82743cf0eadc038974bf06222'),
  ('ur.jalandhry', 24, 23, 2814, 'جو لوگ پرہیزگار اور برے کاموں سے بےخبر اور ایمان دار عورتوں پر بدکاری کی تہمت لگاتے ہیں ان پر دنیا وآخرت (دونوں) میں لعنت ہے۔ اور ان کو سخت عذاب ہوگا', NULL, NULL, '19f093d679a939ab994a0638078a13f22b2b911c72ed5ea7f8f3f485bdbb6421'),
  ('ur.jalandhry', 24, 24, 2815, '(یعنی قیامت کے روز) جس دن ان کی زبانیں ہاتھ اور پاؤں سب ان کے کاموں کی گواہی دیں گے', NULL, NULL, 'ca1ecc98645d7910ff78dc86a538b5e97a2b879e9265b6371a8a8a4892011b7e'),
  ('ur.jalandhry', 24, 25, 2816, 'اس دن خدا ان کو (ان کے اعمال کا) پورا پورا (اور) ٹھیک بدلہ دے گا اور ان کو معلوم ہوجائے گا کہ خدا برحق (اور حق کو) ظاہر کرنے والا ہے', NULL, NULL, '97c301c80097dd1e2379faacd0c8aaaf4c2b52f80d535945452ba8727d0ab08c'),
  ('ur.jalandhry', 24, 26, 2817, 'ناپاک عورتیں ناپاک مردوں کے لئے اور ناپاک مرد ناپاک عورتوں کے لئے۔ اور پاک عورتیں پاک مردوں کے لئے۔ اور پاک مرد پاک عورتوں کے لئے۔ یہ (پاک لوگ) ان (بدگویوں) کی باتوں سے بری ہیں (اور) ان کے لئے بخشش اور نیک روزی ہے', NULL, NULL, 'ad63823a1be01763234f5fda755695f0c2d6106b6328624b7abf21fd11cfb0b4'),
  ('ur.jalandhry', 24, 27, 2818, 'مومنو! اپنے گھروں کے سوا دوسرے (لوگوں کے) گھروں میں گھر والوں سے اجازت لئے اور ان کو سلام کئے بغیر داخل نہ ہوا کرو۔ یہ تمہارے حق میں بہتر ہے (اور ہم) یہ نصیحت اس لئے کرتے ہیں کہ شاید تم یاد رکھو', NULL, NULL, '1634f1f43c285123310e0d1772673c3f449b4959f9b54a33dccbbc3aef184185'),
  ('ur.jalandhry', 24, 28, 2819, 'اگر تم گھر میں کسی کو موجود نہ پاؤ تو جب تک تم کو اجازت نہ دی جائے اس میں مت داخل ہو۔ اور اگر یہ کہا جائے کہ (اس وقت) لوٹ جاؤ تو لوٹ جایا کرو۔ یہ تمہارے لئے بڑی پاکیزگی کی بات ہے۔ اور جو کام تم کرتے ہو خدا سب جانتا ہے', NULL, NULL, 'acc38b7679dd325dcb28581c88f2de8571bf8c0198886417ef4aab5d01a2ea63'),
  ('ur.jalandhry', 24, 29, 2820, 'ہاں اگر تم کسی ایسے مکان میں جاؤ جس میں کوئی نہ بستا ہو اور اس میں تمہارا اسباب (رکھا) ہو، تم پر کچھ گناہ نہیں، اور جو کچھ تم ظاہر کرتے ہو اور جو پوشیدہ کرتے ہو خدا کو سب معلوم ہے', NULL, NULL, '21f8dbd23eb16613351e2741ab003665e08e48e9eacbc21f6cdf15fbf4be11a6'),
  ('ur.jalandhry', 24, 30, 2821, 'مومن مردوں سے کہہ دو کہ اپنی نظریں نیچی رکھا کریں اور اپنی شرم گاہوں کی حفاظت کیا کریں۔ یہ ان کے لئے بڑی پاکیزگی کی بات ہے اور جو کام یہ کرتے ہیں خدا ان سے خبردار ہے', NULL, NULL, '4399e3e0e3877e8f013f281caf731f8801b4927e7dde3e182a3e05b6420f76e6'),
  ('ur.jalandhry', 24, 31, 2822, 'اور مومن عورتوں سے بھی کہہ دو کہ وہ بھی اپنی نگاہیں نیچی رکھا کریں اور اپنی شرم گاہوں کی حفاظت کیا کریں اور اپنی آرائش (یعنی زیور کے مقامات) کو ظاہر نہ ہونے دیا کریں مگر جو ان میں سے کھلا رہتا ہو۔ اور اپنے سینوں پر اوڑھنیاں اوڑھے رہا کریں اور اپنے خاوند اور باپ اور خسر اور بیٹیوں اور خاوند کے بیٹوں اور بھائیوں اور بھتیجیوں اور بھانجوں اور اپنی (ہی قسم کی) عورتوں اور لونڈی غلاموں کے سوا نیز ان خدام کے جو عورتوں کی خواہش نہ رکھیں یا ایسے لڑکوں کے جو عورتوں کے پردے کی چیزوں سے واقف نہ ہوں (غرض ان لوگوں کے سوا) کسی پر اپنی زینت (اور سنگار کے مقامات) کو ظاہر نہ ہونے دیں۔ اور اپنے پاؤں (ایسے طور سے زمین پر) نہ ماریں (کہ جھنکار کانوں میں پہنچے اور) ان کا پوشیدہ زیور معلوم ہوجائے۔ اور مومنو! سب خدا کے آگے توبہ کرو تاکہ فلاح پاؤ', NULL, NULL, 'b9c73cccf7cad9b327b03af1398b11805ac6995c33e51fccce6a568c79dcb476'),
  ('ur.jalandhry', 24, 32, 2823, 'اور اپنی قوم کی بیوہ عورتوں کے نکاح کردیا کرو۔ اور اپنے غلاموں اور لونڈیوں کے بھی جو نیک ہوں (نکاح کردیا کرو) اگر وہ مفلس ہوں گے تو خدا ان کو اپنے فضل سے خوش حال کردے گا۔ اور خدا (بہت) وسعت والا اور (سب کچھ) جاننے والا ہے', NULL, NULL, '8a120fed355892a8123c62f5c72715d4aa89f5fc0f14722472909218c9b78164'),
  ('ur.jalandhry', 24, 33, 2824, 'اور جن کو بیاہ کا مقدور نہ ہو وہ پاک دامنی کو اختیار کئے رہیں یہاں تک کہ خدا ان کو اپنے فضل سے غنی کردے۔ اور جو غلام تم سے مکاتبت چاہیں اگر تم ان میں (صلاحیت اور) نیکی پاؤ تو ان سے مکاتبت کرلو۔ اور خدا نے جو مال تم کو بخشا ہے اس میں سے ان کو بھی دو۔ اور اپنی لونڈیوں کو اگر وہ پاک دامن رہنا چاہیں تو (بےشرمی سے) دنیاوی زندگی کے فوائد حاصل کرنے کے لئے بدکاری پر مجبور نہ کرنا۔ اور جو ان کو مجبور کرے گا تو ان (بیچاریوں) کے مجبور کئے جانے کے بعد خدا بخشنے والا مہربان ہے', NULL, NULL, '7d32de6b92bf2f340a7f3b4a4454b212ac8b6899fd36a2cd71b48d59ff4ad282'),
  ('ur.jalandhry', 24, 34, 2825, 'اور ہم نے تمہاری طرف روشن آیتیں نازل کی ہیں اور جو لوگ تم سے پہلے گزر چکے ہیں ان کی خبریں اور پرہیزگاروں کے لئے نصیحت', NULL, NULL, '3e55c0f167c510da27b311cdc08edb914d70f6a9951a5b619068ddc38ed31945'),
  ('ur.jalandhry', 24, 35, 2826, 'خدا آسمانوں اور زمین کا نور ہے۔ اس کے نور کی مثال ایسی ہے کہ گویا ایک طاق ہے جس میں چراغ ہے۔ اور چراغ ایک قندیل میں ہے۔ اور قندیل (ایسی صاف شفاف ہے کہ) گویا موتی کا سا چمکتا ہوا تارہ ہے اس میں ایک مبارک درخت کا تیل جلایا جاتا ہے (یعنی) زیتون کہ نہ مشرق کی طرف ہے نہ مغرب کی طرف۔ (ایسا معلوم ہوتا ہے کہ) اس کا تیل خواہ آگ اسے نہ بھی چھوئے جلنے کو تیار ہے (پڑی) روشنی پر روشنی (ہو رہی ہے) خدا اپنے نور سے جس کو چاہتا ہے سیدھی راہ دکھاتا ہے۔ اور خدا نے (جو مثالیں) بیان فرماتا ہے (تو) لوگوں کے (سمجھانے کے) لئے اور خدا ہر چیز سے واقف ہے', NULL, NULL, 'fc95b7edf1c2f2000977527177cf7c7bf4912ad03adbab2fc4abf9d8598c0f0e'),
  ('ur.jalandhry', 24, 36, 2827, '(وہ قندیل) ان گھروں میں (ہے) جن کے بارے میں خدا نے ارشاد فرمایا ہے کہ بلند کئے جائیں اور وہاں خدا کے نام کا ذکر کیا جائے (اور) ان میں صبح وشام اس کی تسبیح کرتے رہیں', NULL, NULL, '9fd813582b5bba2bfe1862ea1e9b38b187253362f540dd85ab06476487079833'),
  ('ur.jalandhry', 24, 37, 2828, '(یعنی ایسے) لوگ جن کو خدا کے ذکر اور نماز پڑھنے اور زکوٰة دینے سے نہ سوداگری غافل کرتی ہے نہ خرید وفروخت۔ وہ اس دن سے جب دل (خوف اور گھبراہٹ کے سبب) الٹ جائیں گے اور آنکھیں (اوپر کو چڑھ جائیں گی) ڈرتے ہیں', NULL, NULL, '499ddaa791697fb6bf22f2ec184cf0cbba724a6a8b9f3d4e9bb24b7e346ce496'),
  ('ur.jalandhry', 24, 38, 2829, 'تاکہ خدا ان کو ان کے عملوں کا بہت اچھا بدلہ دے اور اپنے فضل سے زیادہ بھی عطا کرے۔ اور جس کو چاہتا ہے خدا بےشمار رزق دیتا ہے', NULL, NULL, '30e8f6f5a64e1dbe407fdba2f10cb159043ca95ea0bf8b7384c6864ba17566ae'),
  ('ur.jalandhry', 24, 39, 2830, 'جن لوگوں نے کفر کیا ان کے اعمال کی مثال ایسی ہے جیسے میدان میں ریت کہ پیاسا اسے پانی سمجھے یہاں تک کہ جب اس کے پاس آئے تو اسے کچھ بھی نہ پائے اور خدا ہی کو اپنے پاس دیکھے تو وہ اسے اس کا حساب پورا پورا چکا دے۔ اور خدا جلد حساب کرنے والا ہے', NULL, NULL, '4cae8e2101d53e76abb76e6af39514db1a1aaa8493a88bad2afe903140a56e50'),
  ('ur.jalandhry', 24, 40, 2831, 'یا (ان کے اعمال کی مثال ایسی ہے) جیسے دریائے عمیق میں اندھیرے جس پر لہر چڑھی چلی آتی ہو اور اس کے اوپر اور لہر (آرہی ہو) اور اس کے اوپر بادل ہو، غرض اندھیرے ہی اندھیرے ہوں، ایک پر ایک (چھایا ہوا) جب اپنا ہاتھ نکالے تو کچھ نہ دیکھ سکے۔ اور جس کو خدا روشنی نہ دے اس کو (کہیں بھی) روشنی نہیں (مل سکتی)', NULL, NULL, '3b61da5cb5c89107cf216233a5fe4738c4e812291592a47c1d71996ba8de5b44'),
  ('ur.jalandhry', 24, 41, 2832, 'کیا تم نے نہیں دیکھا کہ جو لوگ آسمانوں اور زمین میں ہیں خدا کی تسبیح کرتے ہیں اور پر پھیلائے ہوئے جانور بھی۔ اور سب اپنی نماز اور تسبیح کے طریقے سے واقف ہیں۔ اور جو کچھ وہ کرتے ہیں (سب) خدا کو معلوم ہے', NULL, NULL, 'eeb16824d8f4163e7291d42f3bf101ff18c8e8f93fab64f4645cd574b005a1ff'),
  ('ur.jalandhry', 24, 42, 2833, 'اور آسمان اور زمین کی بادشاہی خدا کے لئے ہے۔ اور خدا ہی کی طرف لوٹ کر جانا ہے', NULL, NULL, '68d344af4165be939fa64b125f7b9b4e7d8162d37be449ef633c0f3b3ae72483'),
  ('ur.jalandhry', 24, 43, 2834, 'کیا تم نے نہیں دیکھا کہ خدا ہی بادلوں کو چلاتا ہے، اور ان کو آپس میں ملا دیتا ہے، پھر ان کو تہ بہ تہ کردیتا ہے، پھر تم دیکھتے ہو کہ بادل میں سے مینہ نکل (کر برس) رہا ہے اور آسمان میں جو (اولوں کے) پہاڑ ہیں، ان سے اولے نازل کرتا ہے تو جس پر چاہتا ہے اس کو برسا دیتا ہے اور جس سے چاہتا ہے ہٹا دیتا ہے۔ اور بادل میں جو بجلی ہوتی ہے اس کی چمک آنکھوں کو خیرہ کرکے بینائی کو اُچکے لئے جاتی ہے', NULL, NULL, '9a7dd514d47df60850d345e12a761fed3c92b63dd452063fee3da0b8a45f26cd'),
  ('ur.jalandhry', 24, 44, 2835, 'اور خدا ہی رات اور دن کو بدلتا رہتا ہے۔ اہل بصارت کے لئے اس میں بڑی عبرت ہے', NULL, NULL, '750c37647826538f36c6baf4a3ea4b63b8aedc2612a588dc34eaecff68c2aa04'),
  ('ur.jalandhry', 24, 45, 2836, 'اور خدا ہی نے ہر چلنے پھرنے والے جاندار کو پانی سے پیدا کیا۔ تو اس میں بعضے ایسے ہیں کہ پیٹ کے بل چلتے ہیں اور بعض ایسے ہیں جو دو پاؤں پر چلتے ہیں اور بعض ایسے ہیں جو چار پاؤں پر چلتے ہیں۔ خدا جو چاہتا ہے پیدا کرتا ہے، بےشک خدا ہر چیز پر قادر ہے', NULL, NULL, '47e3392a5af7bbb9b5cded84dbdfbb2667749ef19c61cadc6302f3c80d346143'),
  ('ur.jalandhry', 24, 46, 2837, 'ہم ہی نے روشن آیتیں نازل کیں ہیں اور خدا جس کو چاہتا ہے سیدھے رستے کی طرف ہدایات کرتا ہے', NULL, NULL, 'a55ce3907912eb67f771b2d2584e5e7307b9e8ecb34143704bd85661fa891c4c'),
  ('ur.jalandhry', 24, 47, 2838, 'اور بعض لوگ کہتے ہیں کہ ہم خدا پر اور رسول پر ایمان لائے اور (ان کا) حکم مان لیا پھر اس کے بعد ان میں سے ایک فرقہ پھر جاتا ہے اور یہ لوگ صاحب ایمان ہی نہیں ہیں', NULL, NULL, 'aefddeb279fd21e7d8913dbb3c139c382fc9a65bc1c2756be907f319f20d45a8'),
  ('ur.jalandhry', 24, 48, 2839, 'اور جب ان کو خدا اور اس کے رسول کی طرف بلایا جاتا ہے تاکہ (رسول خدا) ان کا قضیہ چکا دیں تو ان میں سے ایک فرقہ منہ پھیر لیتا ہے', NULL, NULL, '8de70f5087b4ac574d4d3290da207cce3d9087e937b559c1f6f1bd55ae5afa45'),
  ('ur.jalandhry', 24, 49, 2840, 'اگر (معاملہ) حق (ہو اور) ان کو (پہنچتا) ہو تو ان کی طرف مطیع ہو کر چلے آتے ہیں', NULL, NULL, 'c6ef381daa589d93fd0e0ba8f728e3a20f497befbdac6d91c3e6c59104f7fd98'),
  ('ur.jalandhry', 24, 50, 2841, 'کیا ان کے دلوں میں بیماری ہے یا (یہ) شک میں ہیں یا ان کو یہ خوف ہے کہ خدا اور اس کا رسول ان کے حق میں ظلم کریں گے (نہیں) بلکہ یہ خود ظالم ہیں', NULL, NULL, '7d41d2c0ca418b7ccae53332e4f5cc8877da450cdcdebf9c2b0729de3fc5de91'),
  ('ur.jalandhry', 24, 51, 2842, 'مومنوں کی تو یہ بات ہے کہ جب خدا اور اس کے رسول کی طرف بلائے جائیں تاکہ وہ ان میں فیصلہ کریں تو کہیں کہ ہم نے (حکم) سن لیا اور مان لیا۔ اور یہی لوگ فلاح پانے والے ہیں', NULL, NULL, 'd193037cfecbdbc0ab5b16e470db3e15d61a2ed5743dedec5806e16f30cd8451'),
  ('ur.jalandhry', 24, 52, 2843, 'اور جو شخص خدا اور اس کے رسول کی فرمانبرداری کرے گا اور اس سے ڈرے گا تو ایسے لوگ مراد کو پہنچنے والے ہیں', NULL, NULL, 'f8032aa7d4febe73f5fad73e183d26c4013414f328abc528c8c275a7d51ac45a'),
  ('ur.jalandhry', 24, 53, 2844, 'اور (یہ) خدا کی سخت سخت قسمیں کھاتے ہیں کہ اگر تم ان کو حکم دو تو (سب گھروں سے) نکل کھڑے ہوں۔ کہہ دو کہ قسمیں مت کھاؤ، پسندیدہ فرمانبرداری (درکار ہے) ۔ بےشک خدا تمہارے سب اعمال سے خبردار ہے', NULL, NULL, 'cf5b54704b1f598835749e11e0a66838a711dc2170c1e4682f371762182ffa6a'),
  ('ur.jalandhry', 24, 54, 2845, 'کہہ دو کہ خدا کی فرمانبرداری کرو اور رسول خدا کے حکم پر چلو۔ اگر منہ موڑو گے تو رسول پر (اس چیز کا ادا کرنا) جو ان کے ذمے ہے اور تم پر (اس چیز کا ادا کرنا) ہے جو تمہارے ذمے ہے اور اگر تم ان کے فرمان پر چلو گے تو سیدھا رستہ پالو گے اور رسول کے ذمے تو صاف صاف (احکام خدا کا) پہنچا دینا ہے', NULL, NULL, '5843342b68d040a9b1374e64d6944bd65a907bffdf78cf4ae655459e0634b9f4'),
  ('ur.jalandhry', 24, 55, 2846, 'جو لوگ تم میں سے ایمان لائے اور نیک کام کرتے رہے ان سے خدا کا وعدہ ہے کہ ان کو ملک کا حاکم بنادے گا جیسا ان سے پہلے لوگوں کو حاکم بنایا تھا اور ان کے دین کو جسے اس نے ان کے لئے پسند کیا ہے مستحکم وپائیدار کرے گا اور خوف کے بعد ان کو امن بخشے گا۔ وہ میری عبادت کریں گے اور میرے ساتھ کسی چیز کو شریک نہ بنائیں گے۔ اور جو اس کے بعد کفر کرے تو ایسے لوگ بدکردار ہیں', NULL, NULL, 'ae8baaaa6002c3e1d7ba896fe3923f5d3ec52839276818f2a89856af39a3b9d5'),
  ('ur.jalandhry', 24, 56, 2847, 'اور نماز پڑھتے رہو اور زکوٰة دیتے رہو اور پیغمبر خدا کے فرمان پر چلتے رہو تاکہ تم پر رحمت کی جائے', NULL, NULL, '46c45312480d16470f16212a73b78639bdfb67ac2b528d308ddd24cf0b576e45'),
  ('ur.jalandhry', 24, 57, 2848, 'اور ایسا خیال نہ کرنا کہ تم پر کافر لوگ غالب آجائیں گے (وہ جا ہی کہاں سکتے ہیں) ان کا ٹھکانا دوزخ ہے اور وہ بہت برا ٹھکانا ہے', NULL, NULL, '898cf2b5ac833944ab07bb28c939cabd7168b25a6ee3a99266dd6115e9038d5d'),
  ('ur.jalandhry', 24, 58, 2849, 'مومنو! تمہارے غلام لونڈیاں اور جو بچّے تم میں سے بلوغ کو نہیں پہنچے تین دفعہ یعنی (تین اوقات میں) تم سے اجازت لیا کریں۔ (ایک تو) نماز صبح سے پہلے اور (دوسرے گرمی کی دوپہر کو) جب تم کپڑے اتار دیتے ہو۔ اور تیسرے عشاء کی نماز کے بعد۔ (یہ) تین (وقت) تمہارے پردے (کے) ہیں ان کے (آگے) پیچھے (یعنی دوسرے وقتوں میں) نہ تم پر کچھ گناہ ہے اور نہ ان پر۔ کہ کام کاج کے لئے ایک دوسرے کے پاس آتے رہتے ہو۔ اس طرح خدا اپنی آیتیں تم سے کھول کھول کر بیان فرماتا ہے اور خدا بڑا علم والا اور بڑا حکمت والا ہے', NULL, NULL, '2e6a4fe4069506ffa7170c217eeb614f8c42088880fda5f804c74129ed58517e'),
  ('ur.jalandhry', 24, 59, 2850, 'اور جب تمہارے لڑکے بالغ ہوجائیں تو ان کو بھی اسی طرح اجازت لینی چاہیئے جس طرح ان سے اگلے (یعنی بڑے آدمی) اجازت حاصل کرتے رہے ہیں۔ اس طرح خدا تم سے اپنی آیتیں کھول کھول کر سناتا ہے۔ اور خدا جاننے والا اور حکمت والا ہے', NULL, NULL, '7c1101e8e627d04fef4f780fb4dac1ef15337d9e371c6d78328454345ba12207'),
  ('ur.jalandhry', 24, 60, 2851, 'اور بڑی عمر کی عورتیں جن کو نکاح کی توقع نہیں رہی، اور وہ کپڑے اتار کر سر ننگا کرلیا کریں تو ان پر کچھ گناہ نہیں بشرطیکہ اپنی زینت کی چیزیں نہ ظاہر کریں۔ اور اس سے بھی بچیں تو یہ ان کے حق میں بہتر ہے۔ اور خدا سنتا اور جانتا ہے', NULL, NULL, '25cd4a476fe2a30713e5964260ef75a3381b78a9f3922e12d4b1635ab0226dd0'),
  ('ur.jalandhry', 24, 61, 2852, 'نہ تو اندھے پر کچھ گناہ ہے اور نہ لنگڑے پر اور نہ بیمار پر اور نہ خود تم پر کہ اپنے گھروں سے کھانا کھاؤ یا اپنے باپوں کے گھروں سے یا اپنی ماؤں کے گھروں سے یا بھائیوں کے گھروں سے یا اپنی بہنوں کے گھروں سے یا اپنے چچاؤں کے گھروں سے یا اپنی پھوپھیوں کے گھروں سے یا اپنے ماموؤں کے گھروں سے یا اپنی خالاؤں کے گھروں سے یا اس گھر سے جس کی کنجیاں تمہارے ہاتھ میں ہوں یا اپنے دوستوں کے گھروں سے (اور اس کا بھی) تم پر کچھ گناہ نہیں کہ سب مل کر کھانا کھاؤ یا جدا جدا۔ اور جب گھروں میں جایا کرو تو اپنے (گھر والوں کو) سلام کیا کرو۔ (یہ) خدا کی طرف سے مبارک اور پاکیزہ تحفہ ہے۔ اس طرح خدا اپنی آیتیں کھول کھول کر بیان فرماتا ہے تاکہ تم سمجھو', NULL, NULL, '614e2ece537770b835856e05e49c7a7a4b6c83eb24a6d0b2682cb7a02107d7b1'),
  ('ur.jalandhry', 24, 62, 2853, 'مومن تو وہ ہیں جو خدا پر اور اس کے رسول پر ایمان لائے اور جب کبھی ایسے کام کے لئے جو جمع ہو کر کرنے کا ہو پیغمبر خدا کے پاس جمع ہوں تو ان سے اجازت لئے بغیر چلے نہیں جاتے۔ اے پیغمبر جو لوگ تم سے اجازت حاصل کرتے ہیں وہی خدا پر اور اس کے رسول پر ایمان رکھتے ہیں۔ سو جب یہ لوگ تم سے کسی کام کے لئے اجازت مانگا کریں تو ان میں سے جسے چاہا کرو اجازت دے دیا کرو اور ان کے لئے خدا سے بخششیں مانگا کرو۔ کچھ شک نہیں کہ خدا بخشنے والا مہربان ہے', NULL, NULL, '205878ca99b7874483eae6a0005e4a00af35184864de9d985d1c9cd087077f11'),
  ('ur.jalandhry', 24, 63, 2854, 'مومنو پیغمبر کے بلانے کو ایسا خیال نہ کرنا جیسا تم آپس میں ایک دوسرے کو بلاتے ہو۔ بےشک خدا کو یہ لوگ معلوم ہیں جو تم میں سے آنکھ بچا کر چل دیتے ہیں تو جو لوگ ان کے حکم کی مخالفت کرتے ہیں ان کو ڈرنا چاہیئے کہ (ایسا نہ ہو کہ) ان پر کوئی آفت پڑ جائے یا تکلیف دینے والا عذاب نازل ہو', NULL, NULL, 'd38f6f34fbe6d8f1d2c410bb98b9e2ffafde121afcaa21501a022aae36d040cf'),
  ('ur.jalandhry', 24, 64, 2855, 'دیکھو جو کچھ آسمانوں اور زمین میں ہے سب خدا ہی کا ہے۔ جس (طریق) پر تم ہو وہ اسے جانتا ہے۔ اور جس روز لوگ اس کی طرف لوٹائے جائیں گے تو جو لوگ عمل کرتے رہے وہ ان کو بتا دے گا۔ اور خدا ہر چیز پر قادر ہے۔', NULL, NULL, '2ce5ba24bf62da2cc9e040b32741a20aa5da80fe7116e72cd7110941145cdb3f'),
  ('ur.jalandhry', 25, 1, 2856, 'وہ (خدائے غزوجل) بہت ہی بابرکت ہے جس نے اپنے بندے پر قرآن نازل فرمایا تاکہ اہل حال کو ہدایت کرے', NULL, NULL, 'bf8f98e00b21d1f252c175426626461dbf300461d69e37c84eb79cfa139b9823'),
  ('ur.jalandhry', 25, 2, 2857, 'وہی کہ آسمان اور زمین کی بادشاہی اسی کی ہے اور جس نے (کسی کو) بیٹا نہیں بنایا اور جس کا بادشاہی میں کوئی شریک نہیں اور جس نے ہر چیز کو پیدا کیا اور پھر اس کا ایک اندازہ ٹھہرایا', NULL, NULL, '12c5e0f8338781931827797b16b23225dad5af57c8f6b8a18a500d65d029d112'),
  ('ur.jalandhry', 25, 3, 2858, 'اور (لوگوں نے) اس کے سوا اور معبود بنا لئے ہیں جو کوئی چیز بھی پیدا نہیں کرسکتے اور خود پیدا کئے گئے ہیں۔ اور نہ اپنے نقصان اور نفع کا کچھ اختیار رکھتے ہیں اور نہ مرنا ان کے اختیار میں ہے اور نہ جینا اور نہ مر کر اُٹھ کھڑے ہونا', NULL, NULL, '8a5b4bb4975e6fdeb265733d2bee86041d761885ebcb8a513ee42facf4fe0725'),
  ('ur.jalandhry', 25, 4, 2859, 'اور کافر کہتے ہیں کہ یہ (قرآن) من گھڑت باتیں ہی جو اس (مدعی رسالت) نے بنالی ہیں۔ اور لوگوں نے اس میں اس کی مدد کی ہے۔ یہ لوگ (ایسا کہنے سے) ظلم اور جھوٹ پر (اُتر) آئے ہیں', NULL, NULL, 'aab06d542cf11054e567c151149bd54707a8005a436ae2089223b78d7637205f'),
  ('ur.jalandhry', 25, 5, 2860, 'اور کہتے ہیں کہ یہ پہلے لوگوں کی کہانیاں ہیں جس کو اس نے لکھ رکھا ہے اور وہ صبح وشام اس کو پڑھ پڑھ کر سنائی جاتی ہیں', NULL, NULL, '48d469c19e289163fe0fc6403be5991b869a6434a07c58cb6169d605c11ac860'),
  ('ur.jalandhry', 25, 6, 2861, 'کہہ دو کہ اُس نے اُس کو اُتارا ہے جو آسمانوں اور زمین کی پوشیدہ باتوں کو جانتا ہے۔ بےشک وہ بخشنے والا مہربان ہے', NULL, NULL, '7e261c82ef4d52570d46f7d6cbfc2d5c78b7edc3d0e0b717e42bba97dea3a9b8'),
  ('ur.jalandhry', 25, 7, 2862, 'اور کہتے ہیں کہ یہ کیسا پیغمبر ہے کہ کھاتا ہے اور بازاروں میں چلتا پھرتا ہے۔ کیوں نازل نہیں کیا گیا اس کے پاس کوئی فرشتہ اس کے ساتھ ہدایت کرنے کو رہتا', NULL, NULL, '877f4568829f50a903b56eb762bfbf1c070a8ea44f295263b47c3868e5018cb4'),
  ('ur.jalandhry', 25, 8, 2863, 'یا اس کی طرف (آسمان سے) خزانہ اتارا جاتا یا اس کا کوئی باغ ہوتا کہ اس میں کھایا کرتا۔ اور ظالم کہتے ہیں کہ تم تو ایک جادو زدہ شخص کی پیروی کرتے ہو', NULL, NULL, 'b0b58bb6bd34d1652ef45797e38c48092fb938f3411797813fdfbdfb2489f1e1'),
  ('ur.jalandhry', 25, 9, 2864, '(اے پیغمبر) دیکھو تو یہ تمہارے بارے میں کس کس طرح کی باتیں کرتے ہیں سو گمراہ ہوگئے اور رستہ نہیں پاسکتے', NULL, NULL, 'd400ff9d92d923ce9825ac0739cbe89a95e1c002b133381f5d183280f415dd48'),
  ('ur.jalandhry', 25, 10, 2865, 'وہ (خدا) بہت بابرکت ہے جو اگر چاہے تو تمہارے لئے اس سے بہتر (چیزیں) بنا دے (یعنی) باغات جن کے نیچے نہریں بہہ رہی ہوں۔ نیز تمہارے لئے محل بنادے', NULL, NULL, '568a9361c0935a1822d4297fd83343a155b2e54dcbb1ccb05b0f9b7d47f81857'),
  ('ur.jalandhry', 25, 11, 2866, 'بلکہ یہ تو قیامت ہی کو جھٹلاتے ہیں اور ہم نے قیامت کے جھٹلانے والوں کے لئے دوزخ تیار کر رکھی ہے', NULL, NULL, 'b151e3603f1c4ddc943d9f05cebc1c82a3486d051e15f887ca4f6704f0530499'),
  ('ur.jalandhry', 25, 12, 2867, 'جس وقت وہ ان کو دور سے دیکھے گی (تو غضبناک ہو رہی ہوگی اور یہ) اس کے جوش (غضب) اور چیخنے چلانے کو سنیں گے', NULL, NULL, 'df2fa9afc6cbc1c577de5bdd31957e26f910274d6229be2ad2330d10b1f3cea7'),
  ('ur.jalandhry', 25, 13, 2868, 'اور جب یہ دوزخ کی کسی تنگ جگہ میں (زنجیروں میں) جکڑ کر ڈالے جائیں گے تو وہاں موت کو پکاریں گے', NULL, NULL, '4e5f627dedc2a33de2f34108cb44e0306f853ae587f53adba87523133122ed19'),
  ('ur.jalandhry', 25, 14, 2869, 'آج ایک ہی موت کو نہ پکارو بہت سی موتوں کو پکارو', NULL, NULL, '68fa751e8f23b10c332e1011436e6af6fb1e02b6ef1d1514a47ba83f811174a6'),
  ('ur.jalandhry', 25, 15, 2870, 'پوچھو کہ یہ بہتر ہے یا بہشت جاودانی جس کا پرہیزگاروں سے وعدہ ہے۔ یہ ان (کے عملوں) کا بدلہ اور رہنے کا ٹھکانہ ہوگا', NULL, NULL, '2655537af1b1e85160467d87b719d7577d2f0cc0bed881ea4473e0445bd81e77'),
  ('ur.jalandhry', 25, 16, 2871, 'وہاں جو چاہیں گے ان کے لئے میسر ہوگا ہمیشہ اس میں رہیں گے۔ یہ وعدہ خدا کو (پورا کرنا) لازم ہے اور اس لائق ہے کہ مانگ لیا جائے', NULL, NULL, 'ec68e44240d9c96066dd42b3ac82ead45cd5d93f669a80c0da556f301e96c526'),
  ('ur.jalandhry', 25, 17, 2872, 'اور جس دن (خدا) ان کو اور اُن کو جنہیں یہ خدا کے سوا پوجتے ہیں جمع کرے گا تو فرمائے گا کیا تم نے میرے ان بندوں کو گمراہ کیا تھا یا یہ خود گمراہ ہوگئے تھے', NULL, NULL, '99b047e0862652c692d0a785bdf80bbe61d313508682ea7cdad95295ad50a408'),
  ('ur.jalandhry', 25, 18, 2873, 'وہ کہیں گے تو پاک ہے ہمیں یہ بات شایان نہ تھی کہ تیرے سوا اوروں کو دوست بناتے۔ لیکن تو نے ہی ان کو اور ان کے باپ دادا کو برتنے کو نعمتیں دیں یہاں تک کہ وہ تیری یاد کو بھول گئے۔ اور یہ ہلاک ہونے والے لوگ تھے', NULL, NULL, 'afd4d8fe24f7781ec80c38fe247aa5dfd8d7f1d2faf72148cf3429bc85c8c491'),
  ('ur.jalandhry', 25, 19, 2874, 'تو (کافرو) انہوں نے تو تم کو تمہاری بات میں جھٹلا دیا۔ پس (اب) تم (عذاب کو) نہ پھیر سکتے ہو۔ نہ (کسی سے) مدد لے سکتے ہو۔ اور جو شخص تم میں سے ظلم کرے گا ہم اس کو بڑے عذاب کا مزا چکھائیں گے', NULL, NULL, 'be90ff841c167fa9859275f54e01201f27545127e528c091ccbd1ca824936cae'),
  ('ur.jalandhry', 25, 20, 2875, 'اور ہم نے تم سے پہلے جتنے پیغمبر بھیجے ہیں سب کھانا کھاتے تھے اور بازاروں میں چلتے پھرتے تھے۔ اور ہم نے تمہیں ایک دوسرے کے لئے آزمائش بنایا ہے۔ کیا تم صبر کرو گے۔ اور تمہارا پروردگار تو دیکھنے والا ہے', NULL, NULL, 'f2b765c22c9b6b6a57eff7abf0ca80e48ba91d2e2be8bb12376597cf16e5ea71'),
  ('ur.jalandhry', 25, 21, 2876, 'اور جو لوگ ہم سے ملنے کی امید نہیں رکھتے۔ کہتے ہیں کہ ہم پر فرشتے کیوں نہ نازل کئے گئے۔ یا ہم اپنی آنکھ سے اپنے پروردگار کو دیکھ لیں۔ یہ اپنے خیال میں بڑائی رکھتے ہیں اور (اسی بنا پر) بڑے سرکش ہو رہے ہی', NULL, NULL, '5c742f01ed76052eb018d13375a0dc98a6c64c92b70c7a61472af4ebaf252aae'),
  ('ur.jalandhry', 25, 22, 2877, 'جس دن یہ فرشتوں کو دیکھیں گے اس دن گنہگاروں کے لئے خوشی کی بات نہیں ہوگی اور کہیں گے (خدا کرے تم) روک لئے (اور بند کردیئے) جاؤ', NULL, NULL, '31155ff779a4ae0b4a61784d40afa091f02668ca9ed5dbf0dd84d4776a4f83f4'),
  ('ur.jalandhry', 25, 23, 2878, 'اور جو انہوں نے عمل کئے ہوں گے ہم ان کی طرف متوجہ ہوں گے تو ان کو اُڑتی خاک کردیں گے', NULL, NULL, 'a295581fc9ebf8015e055000e78c699beaf92d471d3146ce41f26eddc863fec6'),
  ('ur.jalandhry', 25, 24, 2879, 'اس دن اہل جنت کا ٹھکانا بھی بہتر ہوگا اور مقام استراحت بھی ہوگا', NULL, NULL, 'ee73742c1b05072820b17cf3205ef9cf7667b6f4188193e699a725d5efe371c1'),
  ('ur.jalandhry', 25, 25, 2880, 'اور جس دن آسمان ابر کے ساتھ پھٹ جائے گا اور فرشتے نازل کئے جائیں گے', NULL, NULL, '1766650a80eed7a16c6844c7ed19f5a194541ac08b902fbf1d734060ba36fcf7'),
  ('ur.jalandhry', 25, 26, 2881, 'اس دن سچی بادشاہی خدا ہی کی ہوگی۔ اور وہ دن کافروں پر (سخت) مشکل ہوگا', NULL, NULL, 'f5b471c48e19acc77ddb803e578516f686728a668a933fc9b8a9c714ddb54065'),
  ('ur.jalandhry', 25, 27, 2882, 'اور جس دن (ناعاقبت اندیش) ظالم اپنے ہاتھ کاٹ کاٹ کر کھائے گا (اور کہے گا) کہ اے کاش میں نے پیغمبر کے ساتھ رشتہ اختیار کیا ہوتا', NULL, NULL, 'e646d7bff8743ba29dc4e2f7035b199607f2b53563aa03f84f893be98cd3e82d'),
  ('ur.jalandhry', 25, 28, 2883, 'ہائے شامت کاش میں نے فلاں شخص کو دوست نہ بنایا ہوتا', NULL, NULL, '107733fd7a7b7095ce5fbcce5417b17954558fd0758556119e6be59ec42f0d82'),
  ('ur.jalandhry', 25, 29, 2884, 'اس نے مجھ کو (کتاب) نصیحت کے میرے پاس آنے کے بعد بہکا دیا۔ اور شیطان انسان کو وقت پر دغا دینے والا ہے', NULL, NULL, '4cf91817327090cef59ece650dc1e00a709a99082523f6d48b435ae81ec48bae'),
  ('ur.jalandhry', 25, 30, 2885, 'اور پیغمبر کہیں گے کہ اے پروردگار میری قوم نے اس قرآن کو چھوڑ رکھا تھا', NULL, NULL, 'fc0a36eb856543987eb406d442f6e898f45e44f23d173c98e7190be72fa3b350'),
  ('ur.jalandhry', 25, 31, 2886, 'اور اسی طرح ہم نے گنہگاروں میں سے ہر پیغمبر کا دشمن بنا دیا۔ اور تمہارا پروردگار ہدایت دینے اور مدد کرنے کو کافی ہے', NULL, NULL, 'd909083071059fc5e77e6a4eaa6c051882b3121f6397e92e11033099b75d199a'),
  ('ur.jalandhry', 25, 32, 2887, 'اور کافر کہتے ہیں کہ اس پر قرآن ایک ہی دفعہ کیوں نہیں اُتارا گیا۔ اس طرح (آہستہ آہستہ) اس لئے اُتارا گیا کہ اس سے تمہارے دل کو قائم رکھیں۔ اور اسی واسطے ہم اس کو ٹھہر ٹھہر کر پڑھتے رہے ہیں', NULL, NULL, '485b025fe785d0901e4dab447b317900793d8f836cac726606e1593527d4713e'),
  ('ur.jalandhry', 25, 33, 2888, 'اور یہ لوگ تمہارے پاس جو (اعتراض کی) بات لاتے ہیں ہم تمہارے پاس اس کا معقول اور خوب مشرح جواب بھیج دیتے ہیں', NULL, NULL, '32d7c57f48d541c2d5c5ffa005c1ab99313309c9f88ad715b14833f47e533377'),
  ('ur.jalandhry', 25, 34, 2889, 'جو لوگ اپنے مونہوں کے بل دوزخ کی طرف جمع کئے جائیں گے ان کا ٹھکانا بھی برا ہے اور وہ رستے سے بھی بہکے ہوئے ہیں', NULL, NULL, '8a19eba7780faa115038ef1ca8d4a1ace3c8db67387dcdb747c9d787ed6dc686'),
  ('ur.jalandhry', 25, 35, 2890, 'اور ہم نے موسیٰ کو کتاب دی اور ان کے بھائی ہارون کو مددگار بنا کر ان کے ساتھ کیا', NULL, NULL, '3f1a2dda495efd091d2e0731eb28cf6f7aa24154f9d6ca7cc9a433859137cdf3'),
  ('ur.jalandhry', 25, 36, 2891, 'اور کہا کہ دونوں ان لوگوں کے پاس جاؤ جن لوگوں نے ہماری آیتوں کی تکذیب کی۔ (جب تکذیب پر اڑے رہے) تو ہم نے ان کو ہلاک کر ڈالا', NULL, NULL, '31ba8a2d1767dbc9fab6665441d3e4c4acd568708dd910cd1eb5c87cfa265006'),
  ('ur.jalandhry', 25, 37, 2892, 'اور نوح کی قوم نے بھی جب پیغمبروں کو جھٹلایا تو ہم نے انہیں غرق کر ڈالا اور لوگوں کے لئے نشانی بنا دیا۔ اور ظالموں کے لئے ہم نے دکھ دینے والا عذاب تیار کر رکھا ہے', NULL, NULL, '5080311430d7366976f5e2640720c3879e356efd8e870bb9a44bcea4531e56bd'),
  ('ur.jalandhry', 25, 38, 2893, 'اور عاد اور ثمود اور کنوئیں والوں اور ان کے درمیان اور بہت سی جماعتوں کو بھی (ہلاک کر ڈالا)', NULL, NULL, '07e4314aa56aa97e9a29393460ce428e8ffbd2f972e955fb2bd2672f41021cf1'),
  ('ur.jalandhry', 25, 39, 2894, 'اور سب کے (سمجھانے کے لئے) ہم نے مثالیں بیان کیں اور (نہ ماننے پر) سب کا تہس نہس کردیا', NULL, NULL, '9a060031ece6c945399029a4c5489d5e210e6d349d2e9da6069453df161f481d'),
  ('ur.jalandhry', 25, 40, 2895, 'اور یہ کافر اس بستی پر بھی گزر چکے ہیں جس پر بری طرح کا مینہ برسایا گیا تھا۔ کیا وہ اس کو دیکھتے نہ ہوں گے۔ بلکہ ان کو (مرنے کے بعد) جی اُٹھنے کی امید ہی نہیں تھی۔', NULL, NULL, '801bd4647cd6ae3bd86ed4460aff18c1f3d8303268c0f6c637ddccccec31ff65'),
  ('ur.jalandhry', 25, 41, 2896, 'اور یہ لوگ جب تم کو دیکھتے ہیں تو تمہاری ہنسی اُڑاتے ہیں۔ کہ کیا یہی شخص ہے جس کو خدا نے پیغمبر بنا کر بھیجا ہے', NULL, NULL, '60ce75c223f3d1b1551c9a151e046440eaa134068cf9b9957107bfcae351a247'),
  ('ur.jalandhry', 25, 42, 2897, 'اگر ہم نے اپنے معبودوں کے بارے میں ثابت قدم نہ رہتے تو یہ ضرور ہم کو بہکا دیتا۔ (اور ان سے پھیر دیتا) اور یہ عنقریب معلوم کرلیں گے جب عذاب دیکھیں گے کہ سیدھے رستے سے کون بھٹکا ہوا ہے', NULL, NULL, '857b4b4e41a1c5509eefd085a62515d580bac712db96d0964dd20ec0cff33e57'),
  ('ur.jalandhry', 25, 43, 2898, 'کیا تم نے اس شخص کو دیکھا جس نے خواہش نفس کو معبود بنا رکھا ہے تو کیا تم اس پر نگہبان ہوسکتے ہو', NULL, NULL, 'd423d676a50a634aade9c0bb6b243fc78be273078e6c65fe5b07dda1417161b8'),
  ('ur.jalandhry', 25, 44, 2899, 'یا تم یہ خیال کرتے ہو کہ ان میں اکثر سنتے یا سمجھتے ہیں (نہیں) یہ تو چوپایوں کی طرح ہیں بلکہ ان سے بھی زیادہ گمراہ ہیں', NULL, NULL, '9c948030af7ee59eb774af7268991a8f11f317ce89f103bbe3d567ad5c0359d6'),
  ('ur.jalandhry', 25, 45, 2900, 'بلکہ تم نے اپنے پروردگار (کی قدرت) کو نہیں دیکھا کہ وہ سائے کو کس طرح دراز کر (کے پھیلا) دیتا ہے۔ اور اگر وہ چاہتا تو اس کو (بےحرکت) ٹھیرا رکھتا پھر سورج کو اس کا رہنما بنا دیتا ہے', NULL, NULL, '908488920b6a95ba66c3e636f865689699fca9dbc8a6c2d941c75e41c88c63bf')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 25, 46, 2901, 'پھر اس کو ہم آہستہ آہستہ اپنی طرف سمیٹ لیتے ہیں', NULL, NULL, '81b9f26c65abbf1c92a27c843c16f6036cd33d5b8cc53ca2d55ab73d0b6d3219'),
  ('ur.jalandhry', 25, 47, 2902, 'اور وہی تو ہے جس نے رات کو تمہارے لئے پردہ اور نیند کو آرام بنایا اور دن کو اُٹھ کھڑے ہونے کا وقت ٹھہرایا', NULL, NULL, '6960d832bd2075a3106ff54c2f22d1d0fab691a285d783773ad3fa31a0d25bcc'),
  ('ur.jalandhry', 25, 48, 2903, 'اور وہی تو ہے جو اپنی رحمت کے مینھہ کے آگے ہواؤں کو خوش خبری بنا کر بھیجتا ہے۔ اور ہم آسمان سے پاک (اور نتھرا ہوا) پانی برساتے ہیں', NULL, NULL, '103c7e4670f39a8e73da3b950141f8b4b8299d77c9dd02acbfacafb37eed9a66'),
  ('ur.jalandhry', 25, 49, 2904, 'تاکہ اس سے شہر مردہ (یعنی زمین افتادہ) کو زندہ کردیں اور پھر اسے بہت سے چوپایوں اور آدمیوں کو جو ہم نے پیدا کئے ہیں پلاتے ہیں', NULL, NULL, '8492225b6c9cc123fba2e8d081ec186e248bf049336e82c4f035fa26eb7ae256'),
  ('ur.jalandhry', 25, 50, 2905, 'اور ہم نے اس (قرآن کی آیتوں) کو طرح طرح سے لوگوں میں بیان کیا تاکہ نصیحت پکڑیں مگر بہت سے لوگوں نے انکار کے سوا قبول نہ کیا', NULL, NULL, '3c5d4a884b6288093ffe351704670dfecc28e1491140996e8ed03e74b5541ee1'),
  ('ur.jalandhry', 25, 51, 2906, 'اور اگر ہم چاہتے تو ہر بستی میں ڈرانے والا بھیج دیتے', NULL, NULL, 'c2d89a9049d21b65ad4c9cf5d63341327e831a0c72aa92d0224a131acd3be939'),
  ('ur.jalandhry', 25, 52, 2907, 'تو تم کافروں کا کہا نہ مانو اور ان سے اس قرآن کے حکم کے مطابق بڑے شدومد سے لڑو', NULL, NULL, '6c23a6083ef308ed24dbcdb946db20db77433aa879710f58ace0e29293a69293'),
  ('ur.jalandhry', 25, 53, 2908, 'اور وہی تو ہے جس نے دو دریاؤں کو ملا دیا ایک کا پانی شیریں ہے پیاس بجھانے والا اور دوسرے کا کھاری چھاتی جلانے والا۔ اور دونوں کے درمیان ایک آڑ اور مضبوط اوٹ بنادی', NULL, NULL, 'df48e183814ac0f13bb8185b05c4cb52cbbe05ec4b9c7f6328d467ad909a4c39'),
  ('ur.jalandhry', 25, 54, 2909, 'اور وہی تو ہے جس نے پانی سے آدمی پیدا کیا۔ پھر اس کو صاحب نسب اور صاحب قرابت دامادی بنایا۔ اور تمہارا پروردگار (ہر طرح کی) قدرت رکھتا ہے', NULL, NULL, '64ad02be4fac50641265a8a0c33560a9d12b6226289d3e46c75a06a0c74a260c'),
  ('ur.jalandhry', 25, 55, 2910, 'اور یہ لوگ خدا کو چھوڑ کر ایسی چیز کی پرستش کر تے ہیں جو نہ ان کو فائدہ پہنچا سکے اور نہ ضرر۔ اور کافر اپنے پروردگار کی مخالفت میں بڑا زور مارتا ہے', NULL, NULL, 'fccfb3dcef8a4c9704bf89e41fd3f851b301a3ab944bb985c251a86863dd365a'),
  ('ur.jalandhry', 25, 56, 2911, 'اور ہم نے (اے محمدﷺ) تم کو صرف خوشی اور عذاب کی خبر سنانے کو بھیجا ہے', NULL, NULL, 'd92f520605b311698cc6632be89272a07e32a534b0d75ba8d5971c51df56fc02'),
  ('ur.jalandhry', 25, 57, 2912, 'کہہ دو کہ میں تم سے اس (کام) کی اجرت نہیں مانگتا، ہاں جو شخص چاہے اپنے پروردگار کی طرف جانے کا رستہ اختیار کرے', NULL, NULL, 'adbfeede0170f29105c3a68c54fb815f285d1de04230dd6ada2f08b01a5fc130'),
  ('ur.jalandhry', 25, 58, 2913, 'اور اس (خدائے) زندہ پر بھروسہ رکھو جو (کبھی) نہیں مرے گا اور اس کی تعریف کے ساتھ تسبیح کرتے رہو۔ اور وہ اپنے بندوں کے گناہوں سے خبر رکھنے کو کافی ہے', NULL, NULL, 'e6d5c6effa978e94f7011555c5da85390cbd7d004eb479f08afd450329f51ba2'),
  ('ur.jalandhry', 25, 59, 2914, 'جس نے آسمانوں اور زمین کو اور جو کچھ ان دونوں کے درمیان ہے چھ دن میں پیدا کیا پھر عرش پر جا ٹھہرا وہ (جس کا نام) رحمٰن (یعنی بڑا مہربان ہے) تو اس کا حال کسی باخبر سے دریافت کرلو', NULL, NULL, 'd8331b3a25165304a141baee5433e7c56a67b479e7c85a274b82ae4c62b58d92'),
  ('ur.jalandhry', 25, 60, 2915, 'اور جب ان (کفار) سے کہا جاتا ہے کہ رحمٰن کو سجدہ کرو تو کہتے ہیں رحمٰن کیا؟ کیا جس کے لئے تم ہم سے کہتے ہو ہم اس کے آگے سجدہ کریں اور اس سے بدکتے ہیں', NULL, NULL, '5fe7d1bcede8ede1556146f3627b97cd895a23c5685778ac8ed42455e3ef0644'),
  ('ur.jalandhry', 25, 61, 2916, 'اور (خدا) بڑی برکت والا ہے جس نے آسمانوں میں برج بنائے اور ان میں (آفتاب کا نہایت روشن) چراغ اور چمکتا ہوا چاند بھی بنایا', NULL, NULL, 'beb1aae1135c758f87c4f17d9ebc0fdc72cac90bc72d1baa32bf219047dc1b86'),
  ('ur.jalandhry', 25, 62, 2917, 'اور وہی تو ہے جس نے رات اور دن کو ایک دوسرے کے پیچھے آنے جانے والا بنایا۔ (یہ باتیں) اس شخص کے لئے جو غور کرنا چاہے یا شکرگزاری کا ارادہ کرے (سوچنے اور سمجھنے کی ہیں)', NULL, NULL, '91dc87781839119d5c2544465378297ded44a054cd7332baf7701f0b952e30d9'),
  ('ur.jalandhry', 25, 63, 2918, 'اور خدا کے بندے تو وہ ہیں جو زمین پر آہستگی سے چلتے ہیں اور جب جاہل لوگ ان سے (جاہلانہ) گفتگو کرتے ہیں تو سلام کہتے ہیں', NULL, NULL, 'b8143ddcb746e968079846dc634394fa0a845763b7eb9e398e831575270130d8'),
  ('ur.jalandhry', 25, 64, 2919, 'اور جو وہ اپنے پروردگار کے آگے سجدے کرکے اور (عجز وادب سے) کھڑے رہ کر راتیں بسر کرتے ہیں', NULL, NULL, '15528eacb65a5fa3183711f3c79a14597a9998b5ea18f3d913a1bd034e85ba44'),
  ('ur.jalandhry', 25, 65, 2920, 'اور جو دعا مانگتے رہتے ہیں کہ اے پروردگار دوزخ کے عذاب کو ہم سے دور رکھیو کہ اس کا عذاب بڑی تکلیف کی چیز ہے', NULL, NULL, '1d38fd34141b42b1df3ee4b3ba7d2d55a237f5838f79901603540d304461552b'),
  ('ur.jalandhry', 25, 66, 2921, 'اور دوزخ ٹھیرنے اور رہنے کی بہت بری جگہ ہے', NULL, NULL, '1e169d21c2038c4bfa949d5ede385974d64ff1404ce08459b9ecd8bce3dd9ed4'),
  ('ur.jalandhry', 25, 67, 2922, 'اور وہ جب خرچ کرتے ہیں تو نہ بےجا اُڑاتے ہیں اور نہ تنگی کو کام میں لاتے ہیں بلکہ اعتدال کے ساتھ۔ نہ ضرورت سے زیادہ نہ کم', NULL, NULL, '06389304126ccc0ab172ceacfb0c1dc7d0a1588e964fa7d8cd4b89275d7de6f5'),
  ('ur.jalandhry', 25, 68, 2923, 'اور وہ جو خدا کے ساتھ کسی اور معبود کو نہیں پکارتے اور جن جاندار کو مار ڈالنا خدا نے حرام کیا ہے اس کو قتل نہیں کرتے مگر جائز طریق پر (یعنی شریعت کے مطابق) اور بدکاری نہیں کرتے۔ اور جو یہ کام کرے گا سخت گناہ میں مبتلا ہوگا', NULL, NULL, '66504b3268b0a352d014d5c269b83528456fb979c953df0fc1df4789ea8afbbf'),
  ('ur.jalandhry', 25, 69, 2924, 'قیامت کے دن اس کو دونا عذاب ہوگا اور ذلت وخواری سے ہمیشہ اس میں رہے گا', NULL, NULL, '16c3b2ec3315f07226acc77964989c17128d6e9dbcc0168b8607547d6017d87b'),
  ('ur.jalandhry', 25, 70, 2925, 'مگر جس نے توبہ کی اور ایمان لایا اور اچھے کام کئے تو ایسے لوگوں کے گناہوں کو خدا نیکیوں سے بدل دے گا۔ اور خدا تو بخشنے والا مہربان ہے', NULL, NULL, 'd623874ac5f373287e2f6ee318fd69ffcbca2162ce272bbbf7904a6b530bd631'),
  ('ur.jalandhry', 25, 71, 2926, 'اور جو توبہ کرتا اور عمل نیک کرتا ہے تو بےشک وہ خدا کی طرف رجوع کرتا ہے', NULL, NULL, 'a08d9f5c892c32e7fe0019ab1ad4ea04d11786e062bd522f013980afd4cf14a4'),
  ('ur.jalandhry', 25, 72, 2927, 'اور وہ جو جھوٹی گواہی نہیں دیتے اور جب ان کو بیہودہ چیزوں کے پاس سے گزرنے کا اتفاق ہو تو بزرگانہ انداز سے گزرتے ہیں', NULL, NULL, 'ab9947e909ec12e563713191ff06a9c69e4c9f4731e62020a57f972df60584c4'),
  ('ur.jalandhry', 25, 73, 2928, 'اور وہ کہ جب ان کو پروردگار کی باتیں سمجھائی جاتی ہیں تو اُن پر اندھے اور بہرے ہو کر نہیں گرتے (بلکہ غور سے سنتے ہیں)', NULL, NULL, 'bdb905f4800b87fac12a156efd4d13572639ef118af28dada5faf25e42072ea2'),
  ('ur.jalandhry', 25, 74, 2929, 'اور وہ جو (خدا سے) دعا مانگتے ہیں کہ اے پروردگار ہم کو ہماری بیویوں کی طرف سے (دل کا چین) اور اولاد کی طرف سے آنکھ کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا امام بنا', NULL, NULL, '8e59688b2bc2a53de3c051dbca43b425cc43a2e55251020d15b17c346851cf5d'),
  ('ur.jalandhry', 25, 75, 2930, 'ان (صفات کے) لوگوں کو ان کے صبر کے بدلے اونچے اونچے محل دیئے جائیں گے۔ اور وہاں فرشتے ان سے دعا وسلام کے ساتھ ملاقات کریں گے', NULL, NULL, 'd884ec00f87fa32f1cc629014fc9516bac5d4986fd9e45c03e909b4861688eea'),
  ('ur.jalandhry', 25, 76, 2931, 'اس میں وہ ہمیشہ رہیں گے۔ اور وہ ٹھیرنے اور رہنے کی بہت ہی عمدہ جگہ ہے', NULL, NULL, 'b9d9aafb57ac8557b71b94f4e91d6a3805928de8cc98d84835d00fa390571e51'),
  ('ur.jalandhry', 25, 77, 2932, 'کہہ دو کہ اگر تم (خدا کو) نہیں پکارتے تو میرا پروردگار بھی تمہاری کچھ پروا نہیں کرتا۔ تم نے تکذیب کی ہے سو اس کی سزا (تمہارے لئے) لازم ہوگی', NULL, NULL, '8692c57379395364f2c3ebcd94d45b497ae808c597c3bc64654080dae42ef38e'),
  ('ur.jalandhry', 26, 1, 2933, 'طٰسٓمٓ', NULL, NULL, '88457d1dd8c32cae76ad8de986a054fb159c6ad5dd70ee13ea486f5e345ac349'),
  ('ur.jalandhry', 26, 2, 2934, 'یہ کتاب روشن کی آیتیں ہیں', NULL, NULL, 'ffcb460e5411ca420120595615558d3ddc5471a2885eae6b111f351ebf54a5c9'),
  ('ur.jalandhry', 26, 3, 2935, '(اے پیغمبرﷺ) شاید تم اس (رنج) سے کہ یہ لوگ ایمان نہیں لاتے اپنے تئیں ہلاک کردو گے', NULL, NULL, 'e0fc27f4654fcfee96e87c7fa66706460b7da129b1de5cae3554bfed92108f8f'),
  ('ur.jalandhry', 26, 4, 2936, 'اگر ہم چاہیں تو ان پر آسمان سے نشانی اُتار دیں۔ پھر ان کی گردنیں اس کے آگے جھک جائیں', NULL, NULL, 'ec03365f50f88c248f46da90a930848738d5db0e4f007f1b7eaa80687be3e31a'),
  ('ur.jalandhry', 26, 5, 2937, 'اور ان کے پاس (خدائے) رحمٰن کی طرف سے کوئی نصیحت نہیں آتی مگر یہ اس سے منہ پھیر لیتے ہیں', NULL, NULL, '02c390707c0faebecc40d0262700472787c17cda222721e7b8c672e096adbec5'),
  ('ur.jalandhry', 26, 6, 2938, 'سو یہ تو جھٹلا چکے اب ان کو اس چیز کی حقیقت معلوم ہوگی جس کی ہنسی اُڑاتے تھے', NULL, NULL, 'a977d5c1ed6c25c372eb5d327de838e61ca56437fe96a9f4b5873d1f4dc110b0'),
  ('ur.jalandhry', 26, 7, 2939, 'کیا انہوں نے زمین کی طرف نہیں دیکھا کہ ہم نے اس میں ہر قسم کی کتنی نفیس چیزیں اُگائی ہیں', NULL, NULL, '4ad43594330c5879333a1f64c19c8145f3bf7981849253abd3771a2558a86e25'),
  ('ur.jalandhry', 26, 8, 2940, 'کچھ شک نہیں کہ اس میں (قدرت خدا کی) نشانی ہے مگر یہ اکثر ایمان لانے والے نہیں ہیں', NULL, NULL, 'd66ab34c48886ff48c7f5fdb038b9096dc376ec5f28ba326edb484d2abb734a2'),
  ('ur.jalandhry', 26, 9, 2941, 'اور تمہارا پروردگار غالب (اور) مہربان ہے', NULL, NULL, '6999586af06cbb9437b5fc7ff123c369c626aff252ca5dbda1f0b047c667ba71'),
  ('ur.jalandhry', 26, 10, 2942, 'اور جب تمہارے پروردگار نے موسیٰ کو پکارا کہ ظالم لوگوں کے پاس جاؤ', NULL, NULL, '3bbf2a604169e40f5adf706454e35ff355509fc765810c743ea60cec1902d08f'),
  ('ur.jalandhry', 26, 11, 2943, '(یعنی) قوم فرعون کے پاس، کیا یہ ڈرتے نہیں', NULL, NULL, 'b94c2aa3ff575d49d4ca3cb66b12901fb7478ae1d0c35d3907cb98886beff4c7'),
  ('ur.jalandhry', 26, 12, 2944, 'انہوں نے کہا کہ میرے پروردگار میں ڈرتا ہوں کہ یہ مجھے جھوٹا سمجھیں', NULL, NULL, 'abd2ca4e20378eb9049dd833fee29631f129f6ab4f91f195e58c6a80a49fbc7f'),
  ('ur.jalandhry', 26, 13, 2945, 'اور میرا دل تنگ ہوتا ہے اور میری زبان رکتی ہے تو ہارون کو حکم بھیج کہ میرے ساتھ چلیں', NULL, NULL, 'a8c5dd410dd59cc6b38adebde7ead87fbde8c20dc1055cc25d341acf8a64ef2d'),
  ('ur.jalandhry', 26, 14, 2946, 'اور ان لوگوں کا مجھ پر ایک گناہ (یعنی قبطی کے خون کا دعویٰ) بھی ہے سو مجھے یہ بھی خوف ہے کہ مجھ کو مار ہی ڈالیں', NULL, NULL, 'b020610108a0d77b46364b495dcaef7ff2fed52c7b53d511eae55b456eb47d73'),
  ('ur.jalandhry', 26, 15, 2947, 'فرمایا ہرگز نہیں۔ تم دونوں ہماری نشانیاں لے کر جاؤ ہم تمہارے ساتھ سننے والے ہیں', NULL, NULL, '2135424b9af3493b9c3b7b903900394ac5c96ad86ebf734a549c1ac852a83562'),
  ('ur.jalandhry', 26, 16, 2948, 'تو دونوں فرعون کے پاس جاؤ اور کہو کہ ہم تمام جہان کے مالک کے بھیجے ہوئے ہیں', NULL, NULL, '37f5155ba22dca2143a77a48c846cdd3608492d84e85ec3dec6b257c44e0b06b'),
  ('ur.jalandhry', 26, 17, 2949, '(اور اس لئے آئے ہیں) کہ آپ بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیں', NULL, NULL, 'c67f24fdc53d7da383cafe514c1c3970ed7e8f64349bec3dfbb9d77d1ac2c148'),
  ('ur.jalandhry', 26, 18, 2950, '(فرعون نے موسیٰ سے کہا) کیا ہم نے تم کو کہ ابھی بچّے تھے پرورش نہیں کیا اور تم نے برسوں ہمارے ہاں عمر بسر (نہیں) کی', NULL, NULL, '98379740e8ad822ba7b0e5e9ba5f22e385af163d032f3f596ba5dd9710fbe57e'),
  ('ur.jalandhry', 26, 19, 2951, 'اور تم نے وہ کام کیا تھا جو کیا اور تم ناشکرے معلوم ہوتے ہو', NULL, NULL, '2815f8436e7a0f8784c13b02ea6d6286a2c16e2b69770791d03d8d6197028485'),
  ('ur.jalandhry', 26, 20, 2952, '(موسیٰ نے) کہاں (ہاں) وہ حرکت مجھ سے ناگہاں سرزد ہوئی تھی اور میں خطا کاروں میں تھا', NULL, NULL, '4d0f9166c30ec7da7a4e20e4773bf0744d38cfc8157bdcd68ba670847b174418'),
  ('ur.jalandhry', 26, 21, 2953, 'تو جب مجھے تم سے ڈر لگا تو تم میں سے بھاگ گیا۔ پھر خدا نے مجھ کو نبوت وعلم بخشا اور مجھے پیغمبروں میں سے کیا', NULL, NULL, '43c581b18d8d027710562b83da531db158db054d954cbf845728956b696d4f63'),
  ('ur.jalandhry', 26, 22, 2954, 'اور (کیا) یہی احسان ہے جو آپ مجھ پر رکھتے ہیں کہ آپ نے بنی اسرائیل کو غلام بنا رکھا ہے', NULL, NULL, '9cd9e542b684a08cc8ad7f990a6388233a5cf591e3fcd11edfaa0fb2bbd4b8f3'),
  ('ur.jalandhry', 26, 23, 2955, 'فرعون نے کہا کہ تمام جہان مالک کیا', NULL, NULL, 'b97a3200653afd19d33f5dfb027970ccb7efe4d5b0910a3ffbfd0e08ee6c4942'),
  ('ur.jalandhry', 26, 24, 2956, 'کہا کہ آسمانوں اور زمین اور جو کچھ ان دونوں میں ہے سب کا مالک۔ بشرطیکہ تم لوگوں کو یقین ہو', NULL, NULL, '6755efff8d608392b8a72a58bda72a7860c2ebd23d4650ad20cada0c4f1efa3c'),
  ('ur.jalandhry', 26, 25, 2957, 'فرعون نے اپنے اہالی موالی سے کہا کہ کیا تم سنتے نہیں', NULL, NULL, 'b97fb3482f472f9479c465a24dc5e3e0fe70bcd9786118f3fd423ed416722df9'),
  ('ur.jalandhry', 26, 26, 2958, '(موسیٰ نے) کہا کہ تمہارا اور تمہارے پہلے باپ دادا کا مالک', NULL, NULL, 'bd33856554e39682551adb325cc3764736704901db31c87282cab89116211544'),
  ('ur.jalandhry', 26, 27, 2959, '(فرعون نے) کہا کہ (یہ) پیغمبر جو تمہاری طرف بھیجا گیا ہے باؤلا ہے', NULL, NULL, '34687534946da2cac1658c4680dfd06fcef61394324ae250d1bb34f4088c7b2a'),
  ('ur.jalandhry', 26, 28, 2960, 'موسیٰ نے کہا کہ مشرق اور مغرب اور جو کچھ ان دونوں میں ہے سب کا مالک، بشرطیکہ تم کو سمجھ ہو', NULL, NULL, '777a070fb2824f4729f131b7172503b785aa2eeaa135ada7ba61cc05fcd64770'),
  ('ur.jalandhry', 26, 29, 2961, '(فرعون نے) کہا کہ اگر تم نے میرے سوا کسی اور کو معبود بنایا تو میں تمہیں قید کردوں گا', NULL, NULL, '094497a04763f439d980a957174d24fcd1588c5a00c72a89dd3372819e346f68'),
  ('ur.jalandhry', 26, 30, 2962, '(موسیٰ نے) کہا خواہ میں آپ کے پاس روشن چیز لاؤں (یعنی معجزہ)', NULL, NULL, 'e4697f07dc3313d5ffea7e6f24c6784972aa2de3c1857b32d057c70059cf7339'),
  ('ur.jalandhry', 26, 31, 2963, 'فرعون نے کہا اگر سچے ہو تو اسے لاؤ (دکھاؤ)', NULL, NULL, '5d2f71355a9f0bbccd5226b9f780c97cf78727c02d5f76ba5528f6dd175a7de6'),
  ('ur.jalandhry', 26, 32, 2964, 'پس انہوں نے اپنی لاٹھی ڈالی تو وہ اسی وقت صریح اژدہا بن گئی', NULL, NULL, '8bbc307f29b1d903eb0a9228c5cd5bbf9a9dee365bcbbc6ddb5e8efcaed5aa41'),
  ('ur.jalandhry', 26, 33, 2965, 'اور اپنا ہاتھ نکالا تو اسی دم دیکھنے والوں کے لئے سفید (براق نظر آنے لگا)', NULL, NULL, 'c15a10916e3a0f52571c8ca1bb4ad29ee1365218ed770749ce3535c08da2d6f8'),
  ('ur.jalandhry', 26, 34, 2966, 'فرعون نے اپنے گرد کے سرداروں سے کہا کہ یہ تو کامل فن جادوگر ہے', NULL, NULL, 'f864a81977abc9473e8881d33987e0de7a91c75aa3860baa285f45d5b6134b1f'),
  ('ur.jalandhry', 26, 35, 2967, 'چاہتا ہے کہ تم کو اپنے جادو (کے زور) سے تمہارے ملک سے نکال دے تو تمہاری کیا رائے ہے؟', NULL, NULL, '3141b8cda1cc80dff8d6c279238a68b99af6571fa438d2e5b49da1774a3a4bbe'),
  ('ur.jalandhry', 26, 36, 2968, 'انہوں نے کہا کہ اسے اور اس کے بھائی (کے بارے) میں کچھ توقف کیجیئے اور شہروں میں ہرکارے بھیج دیجیئے', NULL, NULL, '7221fa8b93ecbceb4f2f3590cb13cbd7ef559606ebac8c9a8f0a6b56d0bf38e5'),
  ('ur.jalandhry', 26, 37, 2969, 'کہ سب ماہر جادوگروں کو (جمع کرکے) آپ کے پاس لے آئیں', NULL, NULL, '1d5a8ea1564baee9d5bbc56766850c7dc88b3ab647a52f48d833202f6e0a0101'),
  ('ur.jalandhry', 26, 38, 2970, 'تو جادوگر ایک مقررہ دن کی میعاد پر جمع ہوگئے', NULL, NULL, '98d4499802212381084a81a6541b135ce10111b1f6f40e6fd4a6466cda2e5b94'),
  ('ur.jalandhry', 26, 39, 2971, 'اور لوگوں سے کہہ دیا گیا کہ تم (سب) کو اکھٹے ہو کر جانا چاہیئے', NULL, NULL, '65373c0dbe8256307869471bc726ee129ef1ecd2a19125945998224d42466f40'),
  ('ur.jalandhry', 26, 40, 2972, 'تاکہ اگر جادوگر غالب رہیں تو ہم ان کے پیرو ہوجائیں', NULL, NULL, 'ff87413cc579ffc99df68bdf6c78f3963a923c3e25201f892d5192dd24fb0c9f'),
  ('ur.jalandhry', 26, 41, 2973, 'جب جادوگر آگئے تو فرعون سے کہنے لگے اگر ہم غالب رہے تو ہمیں صلہ بھی عطا ہوگا؟', NULL, NULL, '114e6267e48e152b816bf5fa31667750112d016db1d71a1f02d6e018cc8a00a9'),
  ('ur.jalandhry', 26, 42, 2974, 'فرعون نے کہا ہاں اور تم مقربوں میں بھی داخل کرلئے جاؤ گے', NULL, NULL, 'adfb41036ca88f5a2e21c98a856acde063b433ca2c1528e324b308f9d751b4c2'),
  ('ur.jalandhry', 26, 43, 2975, 'موسیٰ نے ان سے کہا کہ جو چیز ڈالنی چاہتے ہو، ڈالو', NULL, NULL, 'e95be1e55222924e136a4cda7cef8b04e5ddd8b0185044a25f9d4b0995daf179'),
  ('ur.jalandhry', 26, 44, 2976, 'تو انہوں نے اپنی رسیاں اور لاٹھیاں ڈالیں اور کہنے لگے کہ فرعون کے اقبال کی قسم ہم ضرور غالب رہیں گے', NULL, NULL, '134759960ae9dbb4699a4f2b6525c349ccf815a759dbb3aa7912c3068ba1b7bc'),
  ('ur.jalandhry', 26, 45, 2977, 'پھر موسیٰ نے اپنی لاٹھی ڈالی تو وہ ان چیزوں کو جو جادوگروں نے بنائی تھیں یکایک نگلنے لگی', NULL, NULL, 'd391e9e569203922738331729678f000b9bac6d862decd2c0adb36fbbb953514'),
  ('ur.jalandhry', 26, 46, 2978, 'تب جادوگر سجدے میں گر پڑے', NULL, NULL, 'af1baa116f4c4a8b743f2b305cb32a534219d7d6860b25ca2a573420db949e30'),
  ('ur.jalandhry', 26, 47, 2979, '(اور) کہنے لگے کہ ہم تمام جہان کے مالک پر ایمان لے آئے', NULL, NULL, 'd9fc56c6114c017c1693b1378916571a8d15ae95e25e85f79ac6f6a3c38977b6'),
  ('ur.jalandhry', 26, 48, 2980, 'جو موسیٰ اور ہارون کا مالک ہے', NULL, NULL, 'ba74a407394d0450109db24845c2466a3780443d26ac4626edc927b29739700c'),
  ('ur.jalandhry', 26, 49, 2981, 'فرعون نے کہا کیا اس سے پہلے کہ میں تم کو اجازت دوں تم اس پر ایمان لے آئے، بےشک یہ تمہارا بڑا ہے جس نے تم کو جادو سکھایا ہے۔ سو عنقریب تم (اس کا انجام) معلوم کرلو گے کہ میں تمہارے ہاتھ اور پاؤں اطراف مخالف سے کٹوا دوں گا اور تم سب کو سولی پر چڑھوا دوں گا', NULL, NULL, '6c6ec147914ca4c8006ca707196c2c2e2e2589cf6104be2c3685b892255e18f5'),
  ('ur.jalandhry', 26, 50, 2982, 'انہوں نے کہا کہ کچھ نقصان (کی بات) نہیں ہم اپنے پروردگار کی طرف لوٹ جانے والے ہیں', NULL, NULL, '87e2e7f1933d0cbd383f5117459a8888315bb28135e22125e24d5a4902092b1c'),
  ('ur.jalandhry', 26, 51, 2983, 'ہمیں امید ہے کہ ہمارا پروردگار ہمارے گناہ بخش دے گا۔ اس لئے کہ ہم اول ایمان لانے والوں میں ہیں', NULL, NULL, '51635554144c41984e1abdc850dff22cbf4d46b921d735e5a78217dd5f98a719'),
  ('ur.jalandhry', 26, 52, 2984, 'اور ہم نے موسیٰ کی طرف وحی بھیجی کہ ہمارے بندوں کو رات کو لے نکلو کہ (فرعونیوں کی طرف سے) تمہارا تعاقب کیا جائے گا', NULL, NULL, 'fe2c878a4c07fcf8f73ba19fedf819192fea8d9be75d5af655e6398699128a28'),
  ('ur.jalandhry', 26, 53, 2985, 'تو فرعون نے شہروں میں نقیب راونہ کئے', NULL, NULL, 'd774fae81790e16207f9559220e15d660228b8ab0ab1acee21b386f14f01aff6'),
  ('ur.jalandhry', 26, 54, 2986, '(اور کہا) کہ یہ لوگ تھوڑی سی جماعت ہے', NULL, NULL, 'fb58e4cd644441e01efae3cafcb47390843e7cb88e01d983a7edbf4c8dfeb33c'),
  ('ur.jalandhry', 26, 55, 2987, 'اور یہ ہمیں غصہ دلا رہے ہیں', NULL, NULL, '49638b98c0ef3372f3503148eb9bd6f92cd20324b9dd1fc1f2e942561011e228'),
  ('ur.jalandhry', 26, 56, 2988, 'اور ہم سب باسازو سامان ہیں', NULL, NULL, '075624888f08aaf7a8dcc93591796fac3df35238723da5455746c279a766f3c4'),
  ('ur.jalandhry', 26, 57, 2989, 'تو ہم نے ان کو باغوں اور چشموں سے نکال دیا', NULL, NULL, '7cd54f3e8e440cd21b98c192968eacf7045147c2a670d5e0506485ea75c4bade'),
  ('ur.jalandhry', 26, 58, 2990, 'اور خزانوں اور نفیس مکانات سے', NULL, NULL, '5130af9566d697818a6e6f2842d8124285a2ed1f34484fb9597c399b2cc2328a'),
  ('ur.jalandhry', 26, 59, 2991, '(ان کے ساتھ ہم نے) اس طرح (کیا) اور ان چیزوں کا وارث بنی اسرائیل کو کر دیا', NULL, NULL, '2e11b28e0ed4d0fb74cab8373507bfe15208fdbe60d96620bd6e1ffc82f97ca8'),
  ('ur.jalandhry', 26, 60, 2992, 'تو انہوں نے سورج نکلتے (یعنی صبح کو) ان کا تعاقب کیا', NULL, NULL, 'b4e6d261497d784c9cc75ac31dbc5fa2a78acfce771a5ebeb050cc7000021958'),
  ('ur.jalandhry', 26, 61, 2993, 'جب دونوں جماعتیں آمنے سامنے ہوئیں تو موسیٰ کے ساتھی کہنے لگے کہ ہم تو پکڑ لئے گئے', NULL, NULL, '805eface238c85ef5795a9dfd6600a17e4cfdc730f1f659d8dc0ef640e5665d0'),
  ('ur.jalandhry', 26, 62, 2994, 'موسیٰ نے کہا ہرگز نہیں میرا پروردگار میرے ساتھ ہے وہ مجھے رستہ بتائے گا', NULL, NULL, 'b671114a97cbb841f79cea39cc9d73857d281548b814628efa7162989a95557d'),
  ('ur.jalandhry', 26, 63, 2995, 'اس وقت ہم نے موسیٰ کی طرف وحی بھیجی کہ اپنی لاٹھی دریا پر مارو۔ تو دریا پھٹ گیا۔ اور ہر ایک ٹکڑا (یوں) ہوگیا (کہ) گویا بڑا پہاڑ (ہے)', NULL, NULL, '593081f855740bcca184581fa3b8cfb580516a69383bc04aa12f62295ab8029c'),
  ('ur.jalandhry', 26, 64, 2996, 'اور دوسروں کو وہاں ہم نے قریب کردیا', NULL, NULL, '3c4a7e503fce3f4c2397556604bb57d4e9ea15cae7237e9f1331a293a775f3b4'),
  ('ur.jalandhry', 26, 65, 2997, 'اور موسیٰ اور ان کے ساتھ والوں کو تو بچا لیا', NULL, NULL, '1e1f0f80691541634d1a145cdf16a41018427780d3d172b9e37c4fcd3df1d30a'),
  ('ur.jalandhry', 26, 66, 2998, 'پھر دوسروں کو ڈبو دیا', NULL, NULL, '360e3c91fa61389b2bd357dba1ef6dd83dc3a754913a86236fc99ae873d60722'),
  ('ur.jalandhry', 26, 67, 2999, 'بےشک اس (قصے) میں نشانی ہے۔ لیکن یہ اکثر ایمان لانے والے نہیں', NULL, NULL, 'f6ed81243497f0382e0b48f45b8f28b090d46906aa82e3325398dcf98d10cf95'),
  ('ur.jalandhry', 26, 68, 3000, 'اور تمہارا پروردگار تو غالب (اور) مہربان ہے', NULL, NULL, '2e2a1cacaa9c754f4fcedde33e8dd7bdc783b7cf393a6025694ac8d32d3fa4f0')
