INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 26, 69, 3001, 'اور ان کو ابراہیم کا حال پڑھ کر سنا دو', NULL, NULL, '7855a11e1ae4b4076abb381ab4e29584607d4cd6570b8564f365944402a7e660'),
  ('ur.jalandhry', 26, 70, 3002, 'جب انہوں نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا کہ تم کس چیز کو پوجتے ہو', NULL, NULL, '65a7ecfac64a5b094fe4b83b19d636c6f89469934f23ef68f3a0f03e517643b2'),
  ('ur.jalandhry', 26, 71, 3003, 'وہ کہنے لگے کہ ہم بتوں کو پوجتے ہیں اور ان کی پوجا پر قائم ہیں', NULL, NULL, 'dee572db2bba6bc77e3ddc5b8b79c0ff5346446ff08138d4d6679f392469341e'),
  ('ur.jalandhry', 26, 72, 3004, 'ابراہیم نے کہا کہ جب تم ان کو پکارتے ہو تو کیا وہ تمہاری آواز کو سنتے ہیں؟', NULL, NULL, '2e2005293096d897e11b4c6b67bfa6ab9370b408bf5f4ce9a97016640622f0a0'),
  ('ur.jalandhry', 26, 73, 3005, 'یا تمہیں کچھ فائدے دے سکتے یا نقصان پہنچا سکتے ہیں؟', NULL, NULL, '1dcd1535ece358a2aa16378477e827af2f2ea3f5bd40e2c316358eb1824e7064'),
  ('ur.jalandhry', 26, 74, 3006, 'انہوں نے کہا (نہیں) بلکہ ہم نے اپنے باپ دادا کو اسی طرح کرتے دیکھا ہے', NULL, NULL, 'f6da052fd7c3479d19790d5538d321e4864b35ed01f3e8b31109b855a4ed0006'),
  ('ur.jalandhry', 26, 75, 3007, 'ابراہیم نے کہا کیا تم نے دیکھا کہ جن کو تم پوجتے رہے ہو', NULL, NULL, '38983bac300e26ebb7d43811d8b30e5673f8bbb6699f411b1bebf4d99561ad90'),
  ('ur.jalandhry', 26, 76, 3008, 'تم بھی اور تمہارے اگلے باپ دادا بھی', NULL, NULL, 'f6ee0fbf7cf4c1ee99b69f7911d4879a91a663ce2b5eb2b455bade2c4ca1753f'),
  ('ur.jalandhry', 26, 77, 3009, 'وہ میرے دشمن ہیں۔ مگر خدائے رب العالمین (میرا دوست ہے)', NULL, NULL, 'bc5f4ebb0c5a66449b06e0e73be96bac41488d841c57f85fe6cdf05d1e30cc1d'),
  ('ur.jalandhry', 26, 78, 3010, 'جس نے مجھے پیدا کیا ہے اور وہی مجھے رستہ دکھاتا ہے', NULL, NULL, '27f69cd68874e89420bd776641996e5cde5da984ee282748aeb2c1a6ae1a5a07'),
