  ('ur.jalandhry', 26, 153, 3085, 'وہ کہنے لگے کہ تم تو جادو زدہ ہو', NULL, NULL, 'e75b375e858d3e84f3fe84cc80b2b773549638fe54503b0d5e0cc51a6fd4e21e'),
  ('ur.jalandhry', 26, 154, 3086, 'تم اور کچھ نہیں ہماری طرح آدمی ہو۔ اگر سچے ہو تو کوئی نشانی پیش کرو', NULL, NULL, '9ec54e2377f87cee99d967da0a19162cd938ec06a2ce98f3df03410345a542bd'),
  ('ur.jalandhry', 26, 155, 3087, 'صالح نے کہا (دیکھو) یہ اونٹنی ہے (ایک دن) اس کی پانی پینے کی باری ہے اور ایک معین روز تمہاری باری', NULL, NULL, '86193867987337c8bf055c85fc344cc59daa102d1f33b1e42a72ced497ad5e45'),
  ('ur.jalandhry', 26, 156, 3088, 'اور اس کو کوئی تکلیف نہ دینا (نہیں تو) تم کو سخت عذاب آ پکڑے گا', NULL, NULL, '87aa09d27d16e792ed6e1b1a1af782bb5e81b99dbed2fac4c4f6fa8949c51eef'),
  ('ur.jalandhry', 26, 157, 3089, 'تو انہوں نے اس کی کونچیں کاٹ ڈالیں پھر نادم ہوئے', NULL, NULL, 'b45e6a6e958ede47fa213d3137ff5d08a3d90f7744e110b9e88302e19de6a6a7'),
  ('ur.jalandhry', 26, 158, 3090, 'سو ان کو عذاب نے آن پکڑا۔ بےشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے', NULL, NULL, '5a3d0717c9159fe0e9f240f40d959130cd77ad3f5ca1e54213e9a8ed92e9d811'),
  ('ur.jalandhry', 26, 159, 3091, 'اور تمہارا پروردگار تو غالب (اور) مہربان ہے', NULL, NULL, '2e2a1cacaa9c754f4fcedde33e8dd7bdc783b7cf393a6025694ac8d32d3fa4f0'),
  ('ur.jalandhry', 26, 160, 3092, '(اور قوم) لوط نے بھی پیغمبروں کو جھٹلایا', NULL, NULL, '8b16a09ae410806a48754fde86d47111e2931d41dcbbcebc8ed3f4f090b05406'),
  ('ur.jalandhry', 26, 161, 3093, 'جب ان سے ان کے بھائی لوط نے کہا کہ تم کیوں نہیں ڈرتے؟', NULL, NULL, '95f037131a1c004db81bebfef0e77185a2c37bb958fda77a666d2f34d60a862d'),
  ('ur.jalandhry', 26, 162, 3094, 'میں تو تمہارا امانت دار پیغمبر ہوں', NULL, NULL, '92ab17aed7afe01dcad820eb6daaeea5c0cf59dca13a0c493a0529178a30e8b5'),
  ('ur.jalandhry', 26, 163, 3095, 'تو خدا سے ڈرو اور میرا کہا مانو', NULL, NULL, 'e63b5417a699dc057e785959b11edc24ca45b5e7611ef1f4f37f919714aff8ca'),
  ('ur.jalandhry', 26, 164, 3096, 'اور میں تم سے اس (کام) کا بدلہ نہیں مانگتا۔ میرا بدلہ (خدائے) رب العالمین کے ذمے ہے', NULL, NULL, 'efd1c6fc8a5fb44e41ff44d48fbc7772041f122a6d5b3b565783d483989ab11a'),
  ('ur.jalandhry', 26, 165, 3097, 'کیا تم اہل عالم میں سے لڑکوں پر مائل ہوتے ہو', NULL, NULL, '5daf1cea2694988cd73c6c4b388897b022e9a25f571714aaca2b74c8e99f4cb0'),
  ('ur.jalandhry', 26, 166, 3098, 'اور تمہارے پروردگار نے جو تمہارے لئے تمہاری بیویاں پیدا کی ہیں ان کو چھوڑ دیتے ہو۔ حقیقت یہ ہے کہ تم حد سے نکل جانے والے ہو', NULL, NULL, '7b507d13d301306dd0c0246cbbcc7b895cdfa92d6c9d869c2feb0f55f5f089fd'),
  ('ur.jalandhry', 26, 167, 3099, 'وہ کہنے لگے کہ لوط اگر تم باز نہ آؤ گے تو شہر بدر کردیئے جاؤ گے', NULL, NULL, '337c15b8486d441b9abaa32a4b1f4623a49ade89ed8338c66165933ecb56b70a'),
  ('ur.jalandhry', 26, 168, 3100, 'لوط نے کہا کہ میں تمہارے کام کا سخت دشمن ہوں', NULL, NULL, 'c3298d3e899f767b6fd52391c1eb0fe13e26c0b0156cc49a4883fc8bfc3d704f')
