INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 26, 169, 3101, 'اے میرے پروردگار مجھ کو اور میرے گھر والوں کو ان کے کاموں (کے وبال) سے نجات دے', NULL, NULL, '7889b60de9fe12f5decdbe62d1738df752ed0abca5deaf18a111b29b48fe8819'),
  ('ur.jalandhry', 26, 170, 3102, 'سو ہم نے ان کو اور ان کے گھر والوں کو سب کو نجات دی', NULL, NULL, '2e4c4723723de9d7539da27a1004a2c7d9a53de6fa35a46f3947c27c1e4adefa'),
  ('ur.jalandhry', 26, 171, 3103, 'مگر ایک بڑھیا کہ پیچھے رہ گئی', NULL, NULL, '6f845530ac43f80b8a3cb48f25411568352c480bf3af4f0cc09fe8ab3cd6cc46'),
  ('ur.jalandhry', 26, 172, 3104, 'پھر ہم نے اوروں کو ہلاک کردیا', NULL, NULL, 'd305ec1d0a33809b23272ae393920872c8287c73f3bc6829f87eecaf7da2df2b'),
  ('ur.jalandhry', 26, 173, 3105, 'اور ان پر مینھہ برسایا۔ سو جو مینھہ ان (لوگوں) پر (برسا) جو ڈرائے گئے برا تھا', NULL, NULL, 'b577092707a1dbeb2810fce35a85a23a3de1092dddc87cbe153593ced4bb008f'),
  ('ur.jalandhry', 26, 174, 3106, 'بےشک اس میں نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے', NULL, NULL, '956719d9860c5e9a75b485bd3d74a08878272cc29831daec0071b90b4ebb0d64'),
  ('ur.jalandhry', 26, 175, 3107, 'اور تمہارا پروردگار تو غالب (اور) مہربان ہے۔', NULL, NULL, '2be3ce510a526efaa0f95ae18b90c6178bc9b4ab1dde54881726ad49db724192'),
  ('ur.jalandhry', 26, 176, 3108, 'اور بن کے رہنے والوں نے بھی پیغمبروں کو جھٹلایا', NULL, NULL, '0ac20fb711ae0d2626fa6ebc689e3159ed7b6c42ef32fe8e2f3235354f9fea4b'),
  ('ur.jalandhry', 26, 177, 3109, 'جب ان سے شعیب نے کہا کہ تم ڈرتے کیوں نہیں؟', NULL, NULL, 'd76b41e3523241a4eca9c40ec5efd4b95b31678e835ae6413f2b52482ff1e6d4'),
  ('ur.jalandhry', 26, 178, 3110, 'میں تو تمہارا امانت دار پیغمبر ہوں', NULL, NULL, '92ab17aed7afe01dcad820eb6daaeea5c0cf59dca13a0c493a0529178a30e8b5'),
  ('ur.jalandhry', 26, 179, 3111, 'تو خدا سے ڈرو اور میرا کہا مانو', NULL, NULL, 'e63b5417a699dc057e785959b11edc24ca45b5e7611ef1f4f37f919714aff8ca'),
  ('ur.jalandhry', 26, 180, 3112, 'اور میں اس کام کا تم سے کچھ بدلہ نہیں مانگتا میرا بدلہ تو خدائے رب العالمین کے ذمے ہے', NULL, NULL, '2f568b245113be189f15dc6d91c9e89e4cb6da69f8699fdaeae9cbae45bb530f'),
  ('ur.jalandhry', 26, 181, 3113, '(دیکھو) پیمانہ پورا بھرا کرو اور نقصان نہ کیا کرو', NULL, NULL, '7ef95f389d9a703f19c564a6bc8eb0bf563ddcbf336c4f44b7d7f8d90c8b5f57'),
  ('ur.jalandhry', 26, 182, 3114, 'اور ترازو سیدھی رکھ کر تولا کرو', NULL, NULL, '7494325c6317abf9be6e403cd019b42b0e32320b0666fc439a2da6447378b0a1'),
  ('ur.jalandhry', 26, 183, 3115, 'اور لوگوں کو ان کی چیزیں کم نہ دیا کرو اور ملک میں فساد نہ کرتے پھرو', NULL, NULL, '24db361789e3d476b878b51420c33280208d13eac2ba0cb91d0d9696c5b03557'),
  ('ur.jalandhry', 26, 184, 3116, 'اور اس سے ڈرو جس نے تم کو اور پہلی خلقت کو پیدا کیا', NULL, NULL, '88a2f6fdbd674ac6255609b7272761c3d14aa3931a6dc0210204dacdb40134a4'),
  ('ur.jalandhry', 26, 185, 3117, 'وہ کہنے لگے کہ تم جادو زدہ ہو', NULL, NULL, '4ed7e08f2ce821d0b22e7188c3d97d80c23d7dd0888f96485205586a778b0975'),
  ('ur.jalandhry', 26, 186, 3118, 'اور تم اور کچھ نہیں ہم ہی جیسے آدمی ہو۔ اور ہمارا خیال ہے کہ تم جھوٹے ہو', NULL, NULL, '20553525277b9c4cd496a8168af10e3397763b47467175ca5f4fcafec7d54211'),
  ('ur.jalandhry', 26, 187, 3119, 'اور اگر سچے ہو تو ہم پر آسمان سے ایک ٹکڑا لا کر گراؤ', NULL, NULL, 'b05514326c127a5c0866c29d8e7bb6f6777cc127b23cea379486a9abe992e01d'),
  ('ur.jalandhry', 26, 188, 3120, 'شعیب نے کہا کہ جو کام تم کرتے ہو میرا پروردگار اس سے خوب واقف ہے', NULL, NULL, 'def9b21b9fc1347236419cd922883836e4dd4594d7969e5952f57d657343a67f'),
  ('ur.jalandhry', 26, 189, 3121, 'تو ان لوگوں نے ان کو جھٹلایا، پس سائبان کے عذاب نے ان کو آ پکڑا۔ بےشک وہ بڑے (سخت) دن کا عذاب تھا', NULL, NULL, '2ff40fa6fd5671894d28ff4f5ae3b6eeb972991eed1596692cd696cb877ea73f'),
  ('ur.jalandhry', 26, 190, 3122, 'اس میں یقیناً نشانی ہے۔ اور ان میں اکثر ایمان لانے والے نہیں تھے', NULL, NULL, '6858084d16e2ee3b18b30f79429ea059b8e8b4a9bc9ff65854a6ca8290ef1ed2'),
  ('ur.jalandhry', 26, 191, 3123, 'اور تمہارا پروردگار تو غالب (اور) مہربان ہے', NULL, NULL, '2e2a1cacaa9c754f4fcedde33e8dd7bdc783b7cf393a6025694ac8d32d3fa4f0'),
  ('ur.jalandhry', 26, 192, 3124, 'اور یہ قرآن (خدائے) پروردگار عالم کا اُتارا ہوا ہے', NULL, NULL, '3f7e3b5f66d39286bb42bcc78f4e8ced3acc68f4bbab1e18380b62435ab0e8f8'),
  ('ur.jalandhry', 26, 193, 3125, 'اس کو امانت دار فرشتہ لے کر اُترا ہے', NULL, NULL, 'a0f11514cfbeda8e3f644b99aff1d9b88d1559e0f4d442296c5ff25bba98ed45'),
  ('ur.jalandhry', 26, 194, 3126, '(یعنی اس نے) تمہارے دل پر (القا) کیا ہے تاکہ (لوگوں کو) نصیحت کرتے رہو', NULL, NULL, 'c67a2ae32731f258e732a5f8c6a672a5c5a9fd1fc72962ca48d4203082bd17a4'),
  ('ur.jalandhry', 26, 195, 3127, 'اور (القا بھی) فصیح عربی زبان میں (کیا ہے)', NULL, NULL, '9e6bc773ff7b29a4efd049c3e45238cd1da19f13c9ab9a01d7b84ea8076598c6'),
  ('ur.jalandhry', 26, 196, 3128, 'اور اس کی خبر پہلے پیغمبروں کی کتابوں میں (لکھی ہوئی) ہے', NULL, NULL, '0746f723499d0b3650057ffa093463cf5ca0061adcef0381c5ac6967e9ae0ead'),
  ('ur.jalandhry', 26, 197, 3129, 'کیا ان کے لئے یہ سند نہیں ہے کہ علمائے بنی اسرائیل اس (بات) کو جانتے ہیں', NULL, NULL, '556622a8c84f1c41e9208b17047e8f787d00245dfff5122f602f4f5f2883dcb2'),
  ('ur.jalandhry', 26, 198, 3130, 'اور اگر ہم اس کو کسی غیر اہل زبان پر اُتارتے', NULL, NULL, '931708cd52e2c2c0f73b5a8fa4239fffe4653873805da15f0fe4dd07c637d6eb'),
  ('ur.jalandhry', 26, 199, 3131, 'اور وہ اسے ان (لوگوں کو) پڑھ کر سناتا تو یہ اسے (کبھی) نہ مانتے', NULL, NULL, '314d3a3c3f2900fe9d1eccb8eecf144e83f9679fb3469a37a6e4904632c3af01'),
  ('ur.jalandhry', 26, 200, 3132, 'اسی طرح ہم نے انکار کو گنہگاروں کے دلوں میں داخل کردیا', NULL, NULL, 'c6ae3a261e9c1a774f96a3f0394646dacf3e57c1749937683304bf9225ba501c'),
  ('ur.jalandhry', 26, 201, 3133, 'وہ جب تک درد دینے والا عذاب نہ دیکھ لیں گے، اس کو نہیں مانیں گے', NULL, NULL, 'fcfcd0b6ebdefe85f3a8af0b6cae3cdd2c8cdb5ccbc3a872235b7f5681c49403'),
  ('ur.jalandhry', 26, 202, 3134, 'وہ ان پر ناگہاں آ واقع ہوگا اور انہیں خبر بھی نہ ہوگی', NULL, NULL, 'd63fce2aac3ba05664c4833d07e254a446b191a0f35a2ddcfb20b035f2e3d53f'),
  ('ur.jalandhry', 26, 203, 3135, 'اس وقت کہیں گے کیا ہمیں ملہت ملے گی؟', NULL, NULL, '623c774b322c70ebf70b97d10d82b4a7cbfc965beb8cdbccc7189e4cdeba5c34'),
  ('ur.jalandhry', 26, 204, 3136, 'تو کیا یہ ہمارے عذاب کو جلدی طلب کر رہے ہیں', NULL, NULL, '56a59a092c844fb0c3a4b9b412b5e771fbd03866541c1c8908c05b099c389596'),
  ('ur.jalandhry', 26, 205, 3137, 'بھلا دیکھو تو اگر ہم ان کو برسوں فائدے دیتے رہے', NULL, NULL, 'd059240b05513c64c5cb9568191a0337a193d54f0fb50669343da57e9429d4ca'),
  ('ur.jalandhry', 26, 206, 3138, 'پھر ان پر وہ (عذاب) آ واقع ہو جس کا تم سے وعدہ کیا جاتا ہے', NULL, NULL, 'c2411a28a2bfcc682f821e921c48cae8473a557bdba39b9be4b42ffff023980f'),
  ('ur.jalandhry', 26, 207, 3139, 'تو جو فائدے یہ اٹھاتے رہے ان کے کس کام آئیں گے', NULL, NULL, 'cd79570868a7ed9b6609bcdde21b1922703fbb122bd8c2da85df20447d76a8a5'),
  ('ur.jalandhry', 26, 208, 3140, 'اور ہم نے کوئی بستی ہلاک نہیں کی مگر اس کے لئے نصیحت کرنے والے (پہلے بھیج دیتے) تھے', NULL, NULL, 'a6091f331d4cd767c5d8598180b93864f79050fccb425714c996a85b1d18f142'),
  ('ur.jalandhry', 26, 209, 3141, 'نصیحت کردیں اور ہم ظالم نہیں ہیں', NULL, NULL, '10bae7b1e66f08e6e570c2d994003eb5091d4e757a01832d361e06b425c21570'),
  ('ur.jalandhry', 26, 210, 3142, 'اور اس (قرآن) کو شیطان لے کر نازل نہیں ہوئے', NULL, NULL, '8df498057970df65f59e645e158ff294aae958ee0144dcddf5fdf4e524126533'),
  ('ur.jalandhry', 26, 211, 3143, 'یہ کام نہ تو ان کو سزاوار ہے اور نہ وہ اس کی طاقت رکھتے ہیں', NULL, NULL, '312c2e50bef164872c28eb636f78e2a4b880f1ef3f50725a88eef22afb68c9b5'),
  ('ur.jalandhry', 26, 212, 3144, 'وہ (آسمانی باتوں) کے سننے (کے مقامات) سے الگ کر دیئے گئے ہیں', NULL, NULL, '06f81c5d333989b4eefa975aa518fd50457421615db3b6dca3b7dd1a4bf56e6f'),
  ('ur.jalandhry', 26, 213, 3145, 'تو خدا کے سوا کسی اور معبود کو مت پکارنا، ورنہ تم کو عذاب دیا جائے گا', NULL, NULL, 'e90ee92ca31f1bc0ecc81ac7bb7e5fc37210996ba0e6df519bb067480b57c575'),
  ('ur.jalandhry', 26, 214, 3146, 'اور اپنے قریب کے رشتہ داروں کو ڈر سنا دو', NULL, NULL, 'aa98d047fca7b28453e2ba9f37bd2e2918ce3e1b2ef6300b5ac797755f9d3d4d'),
  ('ur.jalandhry', 26, 215, 3147, 'اور جو مومن تمہارے پیرو ہوگئے ہیں ان سے متواضع پیش آؤ', NULL, NULL, '0bb3eb98961bbfee9aeb7b4ac6236e1d08191d64fe311f2b646b9bae532d0d23'),
  ('ur.jalandhry', 26, 216, 3148, 'پھر اگر لوگ تمہاری نافرمانی کریں تو کہہ دو کہ میں تمہارے اعمال سے بےتعلق ہوں', NULL, NULL, '3c9d60cbdf8a337c80056afa479f889fe3a939218e6e3361f12cd415dc1e0ee3'),
  ('ur.jalandhry', 26, 217, 3149, 'اور (خدائے) غالب اور مہربان پر بھروسا رکھو', NULL, NULL, 'ba1a3d2307bf20b3a316ebf25c355c2433123802fb5daab11232684b53211efb'),
  ('ur.jalandhry', 26, 218, 3150, 'جو تم کو جب تم (تہجد) کے وقت اُٹھتے ہو دیکھتا ہے', NULL, NULL, 'c9c05132a92105311776ec7013bc4dad3a7e31e3255bdf3a0c9540c130a01425'),
  ('ur.jalandhry', 26, 219, 3151, 'اور نمازیوں میں تمہارے پھرنے کو بھی', NULL, NULL, '87ee4cb2d9abfcb5c91f39780316ae05a46fa444a539cad51b5e270a8790d7d3'),
  ('ur.jalandhry', 26, 220, 3152, 'بےشک وہ سننے اور جاننے والا ہے', NULL, NULL, '3b1bdbd3c8b3660795b0344570014e0e59d22e33c5fa0e114d85a119c668e2a6'),
  ('ur.jalandhry', 26, 221, 3153, '(اچھا) میں تمیں بتاؤں کہ شیطان کس پر اُترتے ہیں', NULL, NULL, '390cf7a3a3015f648650abc2fc0c9a43f2fe643e7d1100462c38e8a9ba9be18b'),
  ('ur.jalandhry', 26, 222, 3154, 'ہر جھوٹے گنہگار پر اُترتے ہیں', NULL, NULL, '9e63d062ef9f0d723d67eca565e756e8eb24b41a89733a0a9ae9ca4bc53333ca'),
  ('ur.jalandhry', 26, 223, 3155, 'جو سنی ہوئی بات (اس کے کام میں) لا ڈالتے ہیں اور وہ اکثر جھوٹے ہیں', NULL, NULL, '733d75379cbcdeb8a96cac1961dba9caac7e4e337aa2c900830fb6c3b2aed06c'),
  ('ur.jalandhry', 26, 224, 3156, 'اور شاعروں کی پیروی گمراہ لوگ کیا کرتے ہیں', NULL, NULL, '49ddccbade995a40c4e1eb097a294050d444a1f18e186f18820e35ad55a69586'),
  ('ur.jalandhry', 26, 225, 3157, 'کیا تم نے نہیں دیکھا کہ وہ ہر وادی میں سر مارتے پھرتے ہیں', NULL, NULL, '40cd12a22b6e65e6425df1e0110f4f6499ad8f10835e041eacaf20836f720707'),
  ('ur.jalandhry', 26, 226, 3158, 'اور کہتے وہ ہیں جو کرتے نہیں', NULL, NULL, 'fa85a8d3f0c1dc653e05ddb9cd1e63ee93d15df2655866cca35e6f3263107fc4'),
  ('ur.jalandhry', 26, 227, 3159, 'مگر جو لوگ ایمان لائے اور نیک کام کئے اور خدا کو بہت یاد کرتے رہے اور اپنے اوپر ظلم ہونے کے بعد انتقام لیا اور ظالم عنقریب جان لیں گے کہ کون سی جگہ لوٹ کر جاتے ہیں', NULL, NULL, '073ea48b95896a37848b9f1fbaa51bf510dd749e94e4f3ad11e302014d8208ea'),
  ('ur.jalandhry', 27, 1, 3160, 'ٰطٰسٓ۔ یہ قرآن اور روشن کتاب کی آیتیں ہیں', NULL, NULL, 'cbc32993284607455dd7d11969c9734df9795a76ecd4c799a99295de99aa285f'),
  ('ur.jalandhry', 27, 2, 3161, 'مومنوں کے لئے ہدایت اور بشارت', NULL, NULL, '4b2b27c44b209df4ae93d23ba0102098d0852bb8027fda25f17cabddbaf3f6b9'),
  ('ur.jalandhry', 27, 3, 3162, 'وہ جو نماز پڑھتے اور زکوٰة دیتے اور آخرت کا یقین رکھتے ہیں', NULL, NULL, '87310503f8b5b6a640f1261296b7ee36a54c267cd9392d0856873ef83072c22a'),
  ('ur.jalandhry', 27, 4, 3163, 'جو لوگ آخرت پر ایمان نہیں رکھتے ہیں ہم نے ان کے اعمال ان کے لئے آرستہ کردیئے ہیں تو وہ سرگرداں ہو رہے ہیں', NULL, NULL, '708b05dbef280e0a1dde8cdfef286e9fdbbb015a71900e841a2b0e7b870a6683'),
  ('ur.jalandhry', 27, 5, 3164, 'یہی لوگ ہیں جن کے لئے بڑا عذاب ہے اور وہ آخرت میں بھی وہ بہت نقصان اٹھانے والے ہیں', NULL, NULL, '89329e8853da376c9900e4c41dc02265a53bef82859edff65f9ca3585e7aa575'),
  ('ur.jalandhry', 27, 6, 3165, 'اور تم کو قرآن (خدائے) حکیم وعلیم کی طرف سے عطا کیا جاتا ہے', NULL, NULL, '042e60bb2913a5b011a3ee596c4e6b147449343e4edb0d291a67ba500bee7be6'),
  ('ur.jalandhry', 27, 7, 3166, 'جب موسیٰ نے اپنے گھر والوں سے کہا کہ میں نے آگ دیکھی ہے، میں وہاں سے (رستے) کا پتہ لاتا ہوں یا سلگتا ہوا انگارہ تمہارے پاس لاتا ہوں تاکہ تم تاپو', NULL, NULL, '464dc28a5b5081251f0f6abe2f4d4ba00f2335be70dbf885059428cccf02b9ec'),
  ('ur.jalandhry', 27, 8, 3167, 'جب موسیٰ اس کے پاس آئے تو ندا آئی کہ وہ جو آگ میں (تجلّی دکھاتا) ہے بابرکت ہے۔ اور جو آگ کے اردگرد ہیں اور خدا جو تمام عالم کا پروردگار ہے پاک ہے', NULL, NULL, 'c3b530174edbce7eaabe2c1c304fbae345ba20be732b67579a421a76429cf447'),
  ('ur.jalandhry', 27, 9, 3168, 'اے موسیٰ میں ہی خدائے غالب ودانا ہوں', NULL, NULL, '69ad05cc17bd36ecfad6a644090739b3b07136379abb43769546ed3b13e92cb1'),
  ('ur.jalandhry', 27, 10, 3169, 'اور اپنی لاٹھی ڈال دو۔ جب اُسے دیکھا تو (اس طرح) ہل رہی تھی گویا سانپ ہے تو پیٹھ پھیر کر بھاگے اور پیچھے مڑ کر نہ دیکھا (حکم ہوا کہ) موسیٰ ڈرو مت۔ ہمارے پاس پیغمبر ڈرا نہیں کرتے', NULL, NULL, 'e978d5aa3d261f7174219d87a97500e50c5cc3f499f186321bbd396b92123f75'),
  ('ur.jalandhry', 27, 11, 3170, 'ہاں جس نے ظلم کیا پھر برائی کے بعد اسے نیکی سے بدل دیا تو میں بخشنے والا مہربان ہوں', NULL, NULL, 'beb3806dd540f36d96931e61d068e48e140978ae93ef9dfe3a7566f85a95a6e1'),
  ('ur.jalandhry', 27, 12, 3171, 'اور اپنا ہاتھ اپنے گریبان میں ڈالو سفید نکلے گا۔ (ان دو معجزوں کے ساتھ جو) نو معجزوں میں (داخل ہیں) فرعون اور اس کی قوم کے پاس جاؤ کہ وہ بےحکم لوگ ہیں', NULL, NULL, 'ba3569a230e551d2efecbed533dc06edb57b88048d0a063b5eb7fdeec1571c13'),
  ('ur.jalandhry', 27, 13, 3172, 'جب ان کے پاس ہماری روشن نشانیاں پہنچیں، کہنے لگے یہ صریح جادو ہے', NULL, NULL, '5e8070128d02406d8ea5ffadf7b1a8092094c37e802e55ff96611178f558b072'),
  ('ur.jalandhry', 27, 14, 3173, 'اور بےانصافی اور غرور سے ان سے انکار کیا لیکن ان کے دل ان کو مان چکے تھے۔ سو دیکھ لو فساد کرنے والوں کا انجام کیسا ہوا', NULL, NULL, 'bf32afb7d3db7b4e61618c399d418798774cf79e4780ee528daecb12656549bf'),
  ('ur.jalandhry', 27, 15, 3174, 'اور ہم نے داؤد اور سلیمان کو علم بخشا اور انہوں نے کہا کہ خدا کا شکر ہے جس نے ہمیں بہت سے مومن بندوں پر فضلیت دی', NULL, NULL, 'b9a0e2e9b9d56117b58a40512a9daee6d58f87f1fd86e76810490ffc5c259c00'),
  ('ur.jalandhry', 27, 16, 3175, 'اور سلیمان اور داؤد کے قائم مقام ہوئے۔ اور کہنے لگے کہ لوگو! ہمیں (خدا کی طرف سے) جانوروں کی بولی سکھائی گئی ہے اور ہر چیز عنایت فرمائی گئی ہے۔ بےشک یہ (اُس کا) صریح فضل ہے', NULL, NULL, '59c50a8ba83cbcafdb4701b420e2094707d4905ae044c73c1659a5459ac7a316'),
  ('ur.jalandhry', 27, 17, 3176, 'اور سلیمان کے لئے جنوں اور انسانوں اور پرندوں کے لشکر جمع کئے گئے اور قسم وار کئے جاتے تھے', NULL, NULL, 'ca35000689ed76aa8bb318ff6bbf3f29ea1e075656dcb867b8327be9d060a2fb'),
  ('ur.jalandhry', 27, 18, 3177, 'یہاں تک کہ جب چیونٹیوں کے میدان میں پہنچے تو ایک چیونٹی نے کہا کہ چیونٹیوں اپنے اپنے بلوں میں داخل ہو جاؤ ایسا نہ ہو کہ سلیمان اور اس کے لشکر تم کو کچل ڈالیں اور ان کو خبر بھی نہ ہو', NULL, NULL, '67f4291fa289b4b9c92bd689209f7cd4fdd0d9b90dcd0861d7831c4a02029f54'),
  ('ur.jalandhry', 27, 19, 3178, 'تو وہ اس کی بات سن کر ہنس پڑے اور کہنے لگے کہ اے پروردگار! مجھے توفیق عطا فرما کہ جو احسان تونے مجھ پر اور میرے ماں باپ پر کئے ہیں ان کا شکر کروں اور ایسے نیک کام کروں کہ تو ان سے خوش ہوجائے اور مجھے اپنی رحمت سے اپنے نیک بندوں میں داخل فرما', NULL, NULL, '22d38078d200d130dbaaaf58ba12e92a4c7c8e3b4ed06caabbbfe806a71fed82'),
  ('ur.jalandhry', 27, 20, 3179, 'انہوں نے جانوروں کا جائزہ لیا تو کہنے لگے کیا سبب ہے کہ ہُدہُد نظر نہیں آتا۔ کیا کہیں غائب ہوگیا ہے؟', NULL, NULL, 'c3fd57b4734b28d1e8b1e6ec17d895ad6e53919ea17d6d8db9e78716cad920f4'),
  ('ur.jalandhry', 27, 21, 3180, 'میں اسے سخت سزا دوں گا یا ذبح کر ڈالوں گا یا میرے سامنے (اپنی بےقصوری کی) دلیل صریح پیش کرے', NULL, NULL, '655e3e21afaae5a1f53fb7d2ef2b2c4a438d06b499e1652d87db1056e34017de'),
  ('ur.jalandhry', 27, 22, 3181, 'ابھی تھوڑی ہی دیر ہوئی تھی کہ ہُدہُد آ موجود ہوا اور کہنے لگا کہ مجھے ایک ایسی چیز معلوم ہوئی ہے جس کی آپ کو خبر نہیں اور میں آپ کے پاس (شہر) سبا سے ایک سچی خبر لے کر آیا ہوں', NULL, NULL, 'e37c1602b923f82e102dc01439ea8b7fca3ceeda8b2bef6796f73cdc1d958f6b'),
  ('ur.jalandhry', 27, 23, 3182, 'میں نے ایک عورت دیکھی کہ ان لوگوں پر بادشاہت کرتی ہے اور ہر چیز اسے میسر ہے اور اس کا ایک بڑا تخت ہے', NULL, NULL, 'e50d8b455c8d45f7708cbeb85742a741b6e95cb52cb5f586393770938d59a129'),
  ('ur.jalandhry', 27, 24, 3183, 'میں نے دیکھا کہ وہ اور اس کی قوم خدا کو چھوڑ کر آفتاب کو سجدہ کرتے ہیں اور شیطان نے ان کے اعمال انہیں آراستہ کر دکھائے ہیں اور ان کو رستے سے روک رکھا ہے پس وہ رستے پر نہیں آئے', NULL, NULL, '1950bfa2ec9266cbcd84b075d98b4e8bee6ddf6f3df68b0cf780f161d7b099ba'),
  ('ur.jalandhry', 27, 25, 3184, '(اور نہیں سمجھتے) کہ خدا کو آسمانوں اور زمین میں چھپی چیزوں کو ظاہر کردیتا اور تمہارے پوشیدہ اور ظاہر اعمال کو جانتا ہے کیوں سجدہ نہ کریں', NULL, NULL, 'ce29c1a78a972194da7bfafe717c0ec3838deae5e8705c596abb1f980c478eac'),
  ('ur.jalandhry', 27, 26, 3185, 'خدا کے سوا کوئی عبادت کے لائق نہیں وہی عرش عظیم کا مالک ہے', NULL, NULL, '7aa270951ec53e7f0e8d759ed1b559268417f9003482efd9a7aacf41740fc660'),
  ('ur.jalandhry', 27, 27, 3186, 'سلیمان نے کہا (اچھا) ہم دیکھیں گے، تونے سچ کہا ہے یا تو جھوٹا ہے', NULL, NULL, 'b05e9ff7d4cda20351f6bb40fe8a5aa45fe526a7f3c583d264be03a7afcf4e24'),
  ('ur.jalandhry', 27, 28, 3187, 'یہ میرا خط لے جا اور اسے ان کی طرف ڈال دے پھر ان کے پاس سے پھر آ اور دیکھ کہ وہ کیا جواب دیتے ہیں', NULL, NULL, '2ba2ce10dc6c22bd86e7a0dd7d42796f6e14ed5dd264d83975f3129da9b2a072'),
  ('ur.jalandhry', 27, 29, 3188, 'ملکہ نے کہا کہ دربار والو! میری طرف ایک نامہ گرامی ڈالا گیا ہے', NULL, NULL, 'e670892772a138dd4bcf85fe2a66e3b186be716e85597532b05a8324e1452f4d'),
  ('ur.jalandhry', 27, 30, 3189, 'وہ سلیمان کی طرف سے ہے اور مضمون یہ ہے کہ شروع خدا کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے', NULL, NULL, 'f1662bef9eea66d6f5d40f583e4e2879f44985e0687327150dc74e03ea77feba'),
  ('ur.jalandhry', 27, 31, 3190, '(بعد اس کے یہ) کہ مجھے سرکشی نہ کرو اور مطیع ومنقاد ہو کر میرے پاس چلے آؤ', NULL, NULL, 'a501e5e7ab400c27fdee42c674765611bcf05fe7fb993f2a006795f24fa95ede'),
  ('ur.jalandhry', 27, 32, 3191, '(خط سنا کر) وہ کہنے لگی کہ اے اہل دربار میرے اس معاملے میں مجھے مشورہ دو، جب تک تم حاضر نہ ہو (اور صلاح نہ دو) میں کسی کام کو فیصل کرنے والی نہیں', NULL, NULL, '388d5e002abd4b4006e511ead3e8424d6d56b0c5a515fc37b9ed10a3f155dc8e'),
  ('ur.jalandhry', 27, 33, 3192, 'وہ بولے کہ ہم بڑے زورآور اور سخت جنگجو ہیں اور حکم آپ کے اختیار ہے تو جو حکم دیجیئے گا (اس کے مآل پر) نظر کرلیجیئے گا', NULL, NULL, '532eb48e066d6268ba868d676611ea752602bf94d61df806aa5ea5def5c93f80'),
  ('ur.jalandhry', 27, 34, 3193, 'اس نے کہا کہ بادشاہ جب کسی شہر میں داخل ہوتے ہیں تو اس کو تباہ کر دیتے ہیں اور وہاں کے عزت والوں کو ذلیل کر دیا کرتے ہیں اور اسی طرح یہ بھی کریں گے', NULL, NULL, '7e954f123a72d4416f73fdbc67f084d7349aa32aec0d1ad992dd70707d9f70f8'),
  ('ur.jalandhry', 27, 35, 3194, 'اور میں ان کی طرف کچھ تحفہ بھیجتی ہوں اور دیکھتی ہوں کہ قاصد کیا جواب لاتے ہیں', NULL, NULL, '54892bc713c8e00aaa98182b22cc0e33a93cb0c7d55c64e5851240d57d7727c1'),
  ('ur.jalandhry', 27, 36, 3195, 'جب (قاصد) سلیمان کے پاس پہنچا تو سلیمان نے کہا کیا تم مجھے مال سے مدد دینا چاہتے ہو، جو کچھ خدا نے مجھے عطا فرمایا ہے وہ اس سے بہتر ہے جو تمہیں دیا ہے حقیقت یہ ہے کہ تم ہی اپنے تحفے سے خوش ہوتے ہوگے', NULL, NULL, '236a6fc8dcc14ece144807a1d7cec08389df9f710abad62dd9131b442c9613fd'),
  ('ur.jalandhry', 27, 37, 3196, 'ان کے پاس واپس جاؤ ہم ان پر ایسے لشکر سے حملہ کریں گے جس کے مقابلے کی ان میں طاقت نہ ہوگی اور ان کو وہاں سے بےعزت کرکے نکال دیں گے اور وہ ذلیل ہوں گے', NULL, NULL, '653011d1df5191f90428e9bcf9b43b9de8c057d41c7f271f588534eed9f29355'),
  ('ur.jalandhry', 27, 38, 3197, 'سلیمان نے کہا کہ اے دربار والو! کوئی تم میں ایسا ہے کہ قبل اس کے کہ وہ لوگ فرمانبردار ہو کر ہمارے پاس آئیں ملکہ کا تخت میرے پاس لے آئے', NULL, NULL, 'ca170d03731a0bfed47e6565db0aa896f3a3b5bfbc0ff06cc8f6fa000d6e87a6'),
  ('ur.jalandhry', 27, 39, 3198, 'جنات میں سے ایک قوی ہیکل جن نے کہا کہ قبل اس کے کہ آپ اپنی جگہ سے اٹھیں میں اس کو آپ کے پاس لاحاضر کرتا ہوں اور میں اس (کے اٹھانے کی) طاقت رکھتا ہوں (اور) امانت دار ہوں', NULL, NULL, '5c68256e54328a5ae631c6e8d5c26b66cbe49073fcf7421d69493ba21f30ae12'),
  ('ur.jalandhry', 27, 40, 3199, 'ایک شخص جس کو کتاب الہیٰ کا علم تھا کہنے لگا کہ میں آپ کی آنکھ کے جھپکنے سے پہلے پہلے اسے آپ کے پاس حاضر کئے دیتا ہوں۔ جب سلیمان نے تخت کو اپنے پاس رکھا ہوا دیکھا تو کہا کہ یہ میرے پروردگار کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا کفران نعمت کرتا ہوں اور جو شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے اور جو ناشکری کرتا ہے تو میرا پروردگار بےپروا (اور) کرم کرنے والا ہے', NULL, NULL, '8b5c1d9569cc56424415364d21e59bf76d3bf9357bda6560bda13b7abbcbaec6'),
  ('ur.jalandhry', 27, 41, 3200, 'سلیمان نے کہا کہ ملکہ کے (امتحان عقل کے) لئے اس کے تخت کی صورت بدل دو۔ دیکھیں کہ وہ سوجھ رکھتی ہے یا ان لوگوں میں ہے جو سوجھ نہیں رکھتے', NULL, NULL, '18f72701d7ae668e6692fbaed98e286cc70584abc5db504bb9a441a883529c78')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 27, 42, 3201, 'جب وہ آ پہنچی تو پوچھا گیا کہ کیا آپ کا تخت بھی اسی طرح کا ہے؟ اس نے کہا کہ یہ تو گویا ہو بہو وہی ہے اور ہم کو اس سے پہلے ہی (سلیمان کی عظمت شان) کا علم ہوگیا تھا اور ہم فرمانبردار ہیں', NULL, NULL, '0ddbcd83fd6c4e4d388c28fccf9e085ceeac7e0e2573e0b0689734bac9ac4f1a'),
  ('ur.jalandhry', 27, 43, 3202, 'اور وہ جو خدا کے سوا (اور کی) پرستش کرتی تھی، سلیمان نے اس کو اس سے منع کیا (اس سے پہلے تو) وہ کافروں میں سے تھی', NULL, NULL, '864d053f05553751710a40ff40f1f9273bf1d70c1625572df831ed33387f29dc'),
  ('ur.jalandhry', 27, 44, 3203, '(پھر) اس سے کہا گیا کہ محل میں چلیے، جب اس نے اس (کے فرش) کو دیکھا تو اسے پانی کا حوض سمجھا اور (کپڑا اٹھا کر) اپنی پنڈلیاں کھول دیں۔ سلیمان نے کہا یہ ایسا محل ہے جس میں (نیچے بھی) شیشے جڑے ہوئے ہیں۔ وہ بول اٹھی کہ پروردگار میں اپنے آپ پر ظلم کرتی رہی تھی اور (اب) میں سلیمان کے ہاتھ پر خدائے رب العالمین پر ایمان لاتی ہوں', NULL, NULL, 'a3fab2d7c24f98e67805ddcb538372bec512b8c8b30d0c2092f9b57c6ae128d5'),
  ('ur.jalandhry', 27, 45, 3204, 'اور ہم نے ثمود کی طرف اس کے بھائی صالح کو بھیجا کہ خدا کی عبادت کرو تو وہ دو فریق ہو کر آپس میں جھگڑنے لگے', NULL, NULL, '4074d437421c13e6e2b006584c7ffdecc2905d861554095230c5e21bd419ed40'),
  ('ur.jalandhry', 27, 46, 3205, 'صالح نے کہا کہ بھائیو تم بھلائی سے پہلے برائی کے لئے کیوں جلدی کرتے ہو (اور) خدا سے بخشش کیوں نہیں مانگتے تاکہ تم پر رحم کیا جائے', NULL, NULL, '9379cfe6920901a91f8a9323fe91bf271b789aa91c551b5c4d95974949e7395b'),
  ('ur.jalandhry', 27, 47, 3206, 'وہ کہنے لگے کہ تم اور تمہارے ساتھی ہمارے لئے شگون بد ہے۔ صالح نے کہا کہ تمہاری بدشگونی خدا کی طرف سے ہے بلکہ تم ایسے لوگ ہو جن کی آزمائش کی جاتی ہے', NULL, NULL, 'dbc01ad746bd142992ba8fc736c6268941f45f16a88b947de60af582c2d2fa13'),
  ('ur.jalandhry', 27, 48, 3207, 'اور شہر میں نو شخص تھے جو ملک میں فساد کیا کرتے تھے اور اصلاح سے کام نہیں لیتے تھے', NULL, NULL, 'bb377dcf397a3190b5d39458b1f5bce9e3c9e963a205cde0185b3adca977b7a1'),
  ('ur.jalandhry', 27, 49, 3208, 'کہنے لگے کہ خدا کی قسم کھاؤ کہ ہم رات کو اس پر اور اس کے گھر والوں پر شب خون ماریں گے پھر اس کے وارث سے کہہ دیں گے کہ ہم تو صالح کے گھر والوں کے موقع ہلاکت پر گئے ہی نہیں اور ہم سچ کہتے ہیں', NULL, NULL, '8daaf22dfd4871da173bc9067c094d08272b83967a29270e58a0086cf7515f7e'),
  ('ur.jalandhry', 27, 50, 3209, 'اور وہ ایک چال چلے اور ان کو کچھ خبر نہ ہوئی', NULL, NULL, 'b247df82a3d1ca314cc8c5d2079bf347c67fe988efbae220212b3695e3530171'),
  ('ur.jalandhry', 27, 51, 3210, 'تو دیکھ لو ان کی چال کا کیسا انجام ہوا۔ ہم نے ان کو اور ان کی قوم سب کو ہلاک کر ڈالا', NULL, NULL, '98aee033f81c649bd7b9e39ff8d6a0ebbae0e77b13cde435d05487a3f6fd84ea'),
  ('ur.jalandhry', 27, 52, 3211, 'اب یہ ان کے گھر ان کے ظلم کے سبب خالی پڑے ہیں۔ جو لوگ دانش رکھتے ہیں، ان کے لئے اس میں نشانی ہے', NULL, NULL, 'b53134b2de894cb6b42f0e0e2516ba3c8c0ecc43ac3eecba3095d231a5c98119'),
  ('ur.jalandhry', 27, 53, 3212, 'اور جو لوگ ایمان لائے اور ڈرتے تھے ان کو ہم نے نجات دی', NULL, NULL, 'd92ca5df3b4aeec72ca5312ce27b7cc3cf05c3e53ab34c4decc60c12721e2ce3'),
  ('ur.jalandhry', 27, 54, 3213, 'اور لوط کو (یاد کرو) جب انہوں نے اپنی قوم سے کہا کہ تم بےحیائی (کے کام) کیوں کرتے ہو اور تم دیکھتے ہو', NULL, NULL, 'd3a9309fb8f8acc39272a18a754ffac785404fdad6b736cc880670549afc71b6'),
  ('ur.jalandhry', 27, 55, 3214, 'کیا تم عورتوں کو چھوڑ کر (لذت حاصل کرنے) کے لئے مردوں کی طرف مائل ہوتے ہو۔ حقیقت یہ ہے کہ تم احمق لوگ ہو', NULL, NULL, 'b0fca999f318467cdd1fe461beb3153718ca92fe73d075d946f9d643a27f3290'),
  ('ur.jalandhry', 27, 56, 3215, 'تو ان کی قوم کے لوگ (بولے تو) یہ بولے اور اس کے سوا ان کا کچھ جواب نہ تھا کہ لوط کے گھر والوں کو اپنے شہر سے نکال دو۔ یہ لوگ پاک رہنا چاہتے ہیں', NULL, NULL, '3ac368d508ad0c100646ad31d1766977c6f70db105af7dfe385e30bb8dd51962'),
  ('ur.jalandhry', 27, 57, 3216, 'تو ہم نے ان کو اور ان کے گھر والوں کو نجات دی۔ مگر ان کی بیوی کہ اس کی نسبت ہم نے مقرر کر رکھا ہے (کہ وہ پیچھے رہنے والوں میں ہوگی)', NULL, NULL, '1d67e4f6f56a815e5c2d00ff9cc10c4dabd662087065bda88971b1dd0e31ef05'),
  ('ur.jalandhry', 27, 58, 3217, 'اور ہم نے ان پر مینھہ برسایا سو (جو) مینھہ ان لوگوں پر برسا جن کو متنبہ کردیا گیا تھا، برا تھا', NULL, NULL, 'b57563d63049787a7bc0860f0d0f5f653b35c2a02cd841ff59bbaa8778b349fb'),
  ('ur.jalandhry', 27, 59, 3218, 'کہہ دو کہ سب تعریف خدا ہی کو سزاوار ہے اور اس کے بندوں پر سلام ہے جن کو اس نے منتخب فرمایا۔ بھلا خدا بہتر ہے یا وہ جن کو یہ (اس کا شریک) ٹھہراتے ہیں', NULL, NULL, '2dd9cec6fb1dce531161b744ddd7724012f1b71ed0d98c6afbd08a9e7155e565'),
  ('ur.jalandhry', 27, 60, 3219, 'بھلا کس نے آسمانوں اور زمین کو پیدا کیا اور (کس نے) تمہارے لئے آسمان سے پانی برسایا۔ (ہم نے) پھر ہم ہی نے اس سے سرسبز باغ اُگائے۔ تمہارا کام تو نہ تھا کہ تم اُن کے درختوں کو اگاتے۔ تو کیا خدا کے ساتھ کوئی اور بھی معبود ہے؟ (ہرگز نہیں) بلکہ یہ لوگ رستے سے الگ ہو رہے ہیں', NULL, NULL, '31cf7303749e75abf6ea6d4b193c80f8398fc367063c44b23ec8dca7cbed8044'),
  ('ur.jalandhry', 27, 61, 3220, 'بھلا کس نے زمین کو قرار گاہ بنایا اور اس کے بیچ نہریں بنائیں اور اس کے لئے پہاڑ بنائے اور (کس نے) دو دریاؤں کے بیچ اوٹ بنائی (یہ سب کچھ خدا نے بنایا) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے؟ (ہرگز نہیں) بلکہ ان میں اکثر دانش نہیں رکھتے', NULL, NULL, '33e3d4b97e1a1cdf9310d521ad8f05047546e8a8ef1a6a51d6588d9ff3352a3b'),
  ('ur.jalandhry', 27, 62, 3221, 'بھلا کون بیقرار کی التجا قبول کرتا ہے۔ جب وہ اس سے دعا کرتا ہے اور (کون اس کی) تکلیف کو دور کرتا ہے اور (کون) تم کو زمین میں (اگلوں کا) جانشین بناتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے (ہرگز نہیں مگر) تم بہت کم غور کرتے ہو', NULL, NULL, '0818216d0c07720e986b0642ac89947a1f737353f6f0e6530671d325881e0261'),
  ('ur.jalandhry', 27, 63, 3222, 'بھلا کون تم کو جنگل اور دریا کے اندھیروں میں رستہ بناتا ہے اور (کون) ہواؤں کو اپنی رحمت کے آگے خوشخبری بناکر بھیجتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے؟ (ہرگز نہیں) ۔ یہ لوگ جو شرک کرتے ہیں خدا (کی شان) اس سے بلند ہے', NULL, NULL, '151c773280b7bbd38e2a8405e095e3adad8a8a01009eafadffeb64b430a84c0c'),
  ('ur.jalandhry', 27, 64, 3223, 'بھلا کون خلقت کو پہلی بار پیدا کرتا۔ پھر اس کو بار بار پیدا کرتا رہتا ہے اور (کون) تم کو آسمان اور زمین سے رزق دیتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے (ہرگز نہیں) کہہ دو کہ (مشرکو) اگر تم سچے ہو تو دلیل پیش کرو', NULL, NULL, '0d1f707e9287b6cd321971f221236a0bcd91a368c6c0c717f306ceab03fd701b'),
  ('ur.jalandhry', 27, 65, 3224, 'کہہ دو کہ جو لوگ آسمانوں اور زمین میں ہیں خدا کے سوا غیب کی باتیں نہیں جانتے۔ اور نہ یہ جانتے ہیں کہ کب (زندہ کرکے) اٹھائے جائیں گے', NULL, NULL, '737672d991229c2e208b68b4c5c72f0c9d79445bb9b99740580276406dbb75a7'),
  ('ur.jalandhry', 27, 66, 3225, 'بلکہ آخرت (کے بارے) میں ان کا علم منتہی ہوچکا ہے بلکہ وہ اس سے شک میں ہیں۔ بلکہ اس سے اندھے ہو رہے ہیں', NULL, NULL, '223df56bfdf7a89f350000afc0cc6f877312564c497c8075188dff1b7f8f56e0'),
  ('ur.jalandhry', 27, 67, 3226, 'اور جو لوگ کافر ہیں کہتے ہیں جب ہم اور ہمارے باپ دادا مٹی ہو جائیں گے تو کیا ہم پھر (قبروں سے) نکالے جائیں گے', NULL, NULL, 'd172f386d7af837023def5a84b373da916905bde549fded25cbf6935c0f01b0d'),
  ('ur.jalandhry', 27, 68, 3227, 'یہ وعدہ ہم سے اور ہمارے باپ دادا سے پہلے سے ہوتا چلا آیا ہے (کہاں کا اُٹھنا اور کیسی قیامت) یہ تو صرف پہلے لوگوں کی کہانیاں ہیں', NULL, NULL, '5857fd35a291071ecc0e5320abedf90126caf6b96167511cf401daa992d2d66c'),
  ('ur.jalandhry', 27, 69, 3228, 'کہہ دو کہ ملک میں چلو پھرو پھر دیکھو کہ گنہگاروں کا انجام کیا ہوا ہے', NULL, NULL, '728074d4aa6ac2f14fdd1077b98e009a90686376e2048a0f43aeff4b9e991d6a'),
  ('ur.jalandhry', 27, 70, 3229, 'اور ان (کے حال) پر غم نہ کرنا اور نہ اُن چالوں سے جو یہ کر رہے ہیں تنگ دل ہونا', NULL, NULL, 'f245911d6800022fd490d16d79cfa55fd2b69afba5782a64a6e51f4317fa76e2'),
  ('ur.jalandhry', 27, 71, 3230, 'اور کہتے ہیں کہ اگر تم سچے ہو تو یہ وعدہ کب پورا ہوگا؟', NULL, NULL, '6a549343ac09099f93f3609ef9d611a787a278f24a91913edd3e8dee480c868f'),
  ('ur.jalandhry', 27, 72, 3231, 'کہہ دو کہ جس (عذاب) کے لئے تم جلدی کر رہے ہو شاید اس میں سے کچھ تمہارے نزدیک آپہنچا ہو', NULL, NULL, '7e289e9013ee106eedb08acc5dd08d9577c213ccb6f389d712aeb92a57e84bce'),
  ('ur.jalandhry', 27, 73, 3232, 'اور تمہارا پروردگار تو لوگوں پر فضل کرنے والا ہے لیکن ان میں سے اکثر شکر نہیں کرتے', NULL, NULL, '1d25b1afda8bb55215f9fd11057e032fdc4095aeee4bc71512b3c503ef8f8afc'),
  ('ur.jalandhry', 27, 74, 3233, 'اور جو باتیں ان کے سینوں میں پوشیدہ ہوتی ہیں اور جو کام وہ ظاہر کرتے ہیں تمہارا پروردگار ان (سب) کو جانتا ہے', NULL, NULL, 'db09c9c4f98c4a153877603489b2ed99a7f0c079b9011f1db81244f7ba1fffe7'),
  ('ur.jalandhry', 27, 75, 3234, 'اور آسمانوں اور زمین میں کوئی پوشیدہ چیز نہیں ہے مگر (وہ) کتاب روشن میں (لکھی ہوئی) ہے', NULL, NULL, 'ca1d4b01d3867365ff38535227f83072b287bdfac9a1264a88959369f54e23fb'),
  ('ur.jalandhry', 27, 76, 3235, 'بےشک یہ قرآن بنی اسرائیل کے سامنے اکثر باتیں جن میں وہ اختلاف کرتے ہیں، بیان کر دیتا ہے', NULL, NULL, '5976ad2f3938b4d351e7fc77b52897a22f500610d6fa5ec44445a7e7e7dc8bea'),
  ('ur.jalandhry', 27, 77, 3236, 'اور بےشک یہ مومنوں کے لئے ہدایات اور رحمت ہے', NULL, NULL, '87c032a366691fcb793c7fc42848e4852d53572025f0a36fc896eb7e269208d5'),
  ('ur.jalandhry', 27, 78, 3237, 'تمہارا پروردگار (قیامت کے روز) اُن میں اپنے حکم سے فیصلہ کر دے گا اور وہ غالب (اور) علم والا ہے', NULL, NULL, 'a9574287f2a6058e9a60036597a712f3faf970af0c3fd738b37ac12318017af1'),
  ('ur.jalandhry', 27, 79, 3238, 'تو خدا پر بھروسہ رکھو تم تو حق صریح پر ہو', NULL, NULL, '3ed494633773315fc6da46c0f14f4a5cfcec87c3e09e5c90336b017ff977e48a'),
  ('ur.jalandhry', 27, 80, 3239, 'کچھ شک نہیں کہ تم مردوں کو (بات) نہیں سنا سکتے اور نہ بہروں کو جب کہ وہ پیٹھ پھیر کر پھر جائیں آواز سنا سکتے ہو', NULL, NULL, '4e05c9a794f493933fdbbdc7136ab49ae2a9520cfe3b011268e975ac98c2b1b3'),
  ('ur.jalandhry', 27, 81, 3240, 'اور نہ اندھوں کو گمراہی سے (نکال کر) رستہ دیکھا سکتے ہو۔ تم ان ہی کو سنا سکتے ہو جو ہماری آیتوں پر ایمان لاتے ہیں اور وہ فرمانبردار ہو جاتے ہیں', NULL, NULL, '684aa578a008055e1e99d9974a78445ef42e68fd1c9c35917a796dc49ad4075f'),
  ('ur.jalandhry', 27, 82, 3241, 'اور جب اُن کے بارے میں (عذاب) کا وعدہ پورا ہوگا تو ہم اُن کے لئے زمین میں سے ایک جانور نکالیں گے جو ان سے بیان کر دے گا۔ اس لئے کہ لوگ ہماری آیتوں پر ایمان نہیں لاتے تھے', NULL, NULL, 'd997f64228683b5d654f135249557a23a2279ccb35f7cc24d3245ec513687f92'),
  ('ur.jalandhry', 27, 83, 3242, 'اور جس روز ہم ہر اُمت میں سے اس گروہ کو جمع کریں گے جو ہماری آیتوں کی تکذیب کرتے تھے تو اُن کی جماعت بندی کی جائے گی', NULL, NULL, 'f1cc1335b74fab23e7d527f52bf50a7f6828845ff99668c3810185183acd5366'),
  ('ur.jalandhry', 27, 84, 3243, 'یہاں تک کہ جب (سب) آجائیں گے تو (خدا) فرمائے گا کہ کیا تم نے میری آیتوں کو جھٹلا دیا تھا اور تم نے (اپنے) علم سے ان پر احاطہ تو کیا ہی نہ تھا۔ بھلا تم کیا کرتے تھے', NULL, NULL, '3037aec511f8a125623d22bbe2711ed288ea3c80cc4825005c2de98e5e23aaf7'),
  ('ur.jalandhry', 27, 85, 3244, 'اور اُن کے ظلم کے سبب اُن کے حق میں وعدہ (عذاب) پورا ہوکر رہے گا تو وہ بول بھی نہ سکیں گے', NULL, NULL, '360b598f2cea5945fb16472a39fd2b9851288d27ab52fd55c7ac47c4dd8721ab'),
  ('ur.jalandhry', 27, 86, 3245, 'کیا اُنہوں نے نہیں دیکھا کہ ہم نے رات کو (اس لئے) بنایا ہے کہ اس میں آرام کریں اور دن کو روشن (بنایا ہے کہ اس میں کام کریں) بےشک اس میں مومن لوگوں کے لئے نشانیاں ہیں', NULL, NULL, '7e0c00df61c76f1c7a69a0e35046b1db9b4864f0e682b545e5c677b38b92b12c'),
  ('ur.jalandhry', 27, 87, 3246, 'اور جس روز صور پھونکا جائے گا تو جو لوگ آسمانوں اور زمین میں ہیں سب گھبرا اُٹھیں گے مگر وہ جسے خدا چاہے اور سب اس کے پاس عاجز ہو کر چلے آئیں گے', NULL, NULL, 'ce688995ffd613d401ffe4408c6d48b6e422c6f8aacd50ae5397b6b11a2e1867'),
  ('ur.jalandhry', 27, 88, 3247, 'اور تم پہاڑوں کو دیکھتے ہو تو خیال کرتے ہو کہ (اپنی جگہ پر) کھڑے ہیں مگر وہ (اس روز) اس طرح اُڑے پھریں گے جیسے بادل۔ (یہ) خدا کی کاریگری ہے جس نے ہر چیز کو مضبوط بنایا۔ بےشک وہ تمہارے سب افعال سے باخبر ہے', NULL, NULL, '8b0387c02876be964e5b3ca80729e3e45613a362209969cd015d85cb9917a6e6'),
  ('ur.jalandhry', 27, 89, 3248, 'جو شخص نیکی لےکر آئے گا تو اس کے لئے اس سے بہتر (بدلہ تیار) ہے اور ایسے لوگ (اُس روز) گھبراہٹ سے بےخوف ہوں گے', NULL, NULL, '37d30f2308b1800f065f6f7a87af35a24c8098dac8e21f0123f42400163aca35'),
  ('ur.jalandhry', 27, 90, 3249, 'اور جو برائی لے کر آئے گا تو ایسے لوگ اوندھے منہ دوزخ میں ڈال دیئے جائیں گے۔ تم کو تو اُن ہی اعمال کا بدلہ ملے گا جو تم کرتے رہے ہو', NULL, NULL, 'bae6b5a76fb584d9d7aef478af241b36dc486cfb3cdb394fdbd62b557396575d'),
  ('ur.jalandhry', 27, 91, 3250, '(کہہ دو) کہ مجھ کو یہی ارشاد ہوا ہے کہ اس شہر (مکہ) کے مالک کی عبادت کروں جس نے اس کو محترم (اور مقام ادب) بنایا ہے اور سب چیز اُسی کی ہے اور یہ بھی حکم ہوا ہے کہ اس کا حکم بردار رہوں', NULL, NULL, '7f1d40e06fa52096011a8e1d713166dfa73da1003add694cddb17856a8422fc5'),
  ('ur.jalandhry', 27, 92, 3251, 'اور یہ بھی کہ قرآن پڑھا کروں۔ تو جو شخص راہ راست اختیار کرتا ہے تو اپنے ہی فائدے کے لئے اختیار کرتا ہے۔ اور جو گمراہ رہتا ہے تو کہہ دو کہ میں تو صرف نصیحت کرنے والا ہوں', NULL, NULL, 'e44d3301ffee920518dcb03aa6c024a67e91273cd42a5ee909637a457d5d68e9'),
  ('ur.jalandhry', 27, 93, 3252, 'اور کہو کہ خدا کا شکر ہے۔ وہ تم کو عنقریب اپنی نشانیاں دکھائے گا تو تم اُن کو پہچان لو گے۔ اور جو کام تم کرتے ہو تمہارا پروردگار اُن سے بےخبر نہیں ہے', NULL, NULL, 'e90c9204c9dbd336a8f3c37b06489e6e88c89e098d12faa1a4dc9645b6f23c86'),
  ('ur.jalandhry', 28, 1, 3253, 'طٰسٓمٓ', NULL, NULL, '88457d1dd8c32cae76ad8de986a054fb159c6ad5dd70ee13ea486f5e345ac349'),
  ('ur.jalandhry', 28, 2, 3254, 'یہ کتاب روشن کی آیتیں ہیں', NULL, NULL, 'ffcb460e5411ca420120595615558d3ddc5471a2885eae6b111f351ebf54a5c9'),
  ('ur.jalandhry', 28, 3, 3255, '(اے محمدﷺ) ہم تمہیں موسٰی اور فرعون کے کچھ حالات مومن لوگوں کو سنانے کے لئے صحیح صحیح سناتے ہیں', NULL, NULL, 'a5358f0309b4b6ca4339fff807a02bcd4972a860317015a37db57ef3496b3103'),
  ('ur.jalandhry', 28, 4, 3256, 'کہ فرعون نے ملک میں سر اُٹھا رکھا تھا اور وہاں کے باشندوں کو گروہ گروہ بنا رکھا تھا اُن میں سے ایک گروہ کو (یہاں تک) کمزور کر دیا تھا کہ اُن کے بیٹوں کو ذبح کر ڈالتا اور اُن کی لڑکیوں کو زندہ رہنے دیتا۔ بیشک وہ مفسدوں میں تھا', NULL, NULL, '8221000b18b693cd200c7d2f5428e2d8c372196ae8d42577b75f6284321f901e'),
  ('ur.jalandhry', 28, 5, 3257, 'اور ہم چاہتے تھے کہ جو لوگ ملک میں کمزور کر دیئے گئے ہیں اُن پر احسان کریں اور اُن کو پیشوا بنائیں اور انہیں (ملک کا) وارث کریں', NULL, NULL, '8fefec5f3bb87e875f88073dafc5115d22574d4c238cae020179475359153e21'),
  ('ur.jalandhry', 28, 6, 3258, 'اور ملک میں ان کو قدرت دیں اور فرعون اور ہامان اور اُن کے لشکر کو وہ چیزیں دکھا دیں جس سے وہ ڈرتے تھے', NULL, NULL, '360efd1c2ad2723f83efeaa16bb6e059fbafbc472ce91cdf800ac9b8684edc6c'),
  ('ur.jalandhry', 28, 7, 3259, 'اور ہم نے موسٰی کی ماں کی طرف وحی بھیجی کہ اس کو دودھ پلاؤ جب تم کو اس کے بارے میں کچھ خوف پیدا ہو تو اسے دریا میں ڈال دینا اور نہ تو خوف کرنا اور نہ رنج کرنا۔ ہم اس کو تمہارے پاس واپس پہنچا دیں گے اور (پھر) اُسے پیغمبر بنا دیں گے', NULL, NULL, '71bcc8a3bc69aeca42473a1bf981fb357c98748221d5ce58f4679f2ae2954dd0'),
  ('ur.jalandhry', 28, 8, 3260, 'تو فرعون کے لوگوں نے اس کو اُٹھا لیا اس لئے کہ (نتیجہ یہ ہونا تھا کہ) وہ اُن کا دشمن اور (ان کے لئے موجب) غم ہو۔ بیشک فرعون اور ہامان اور اُن کے لشکر چوک گئے', NULL, NULL, 'b377ba7300cdb2c947f6c1a08b6a18f94764f2216352b2713d58f56747d7a383'),
  ('ur.jalandhry', 28, 9, 3261, 'اور فرعون کی بیوی نے کہا کہ (یہ) میری اور تمہاری (دونوں کی) آنکھوں کی ٹھنڈک ہے اس کو قتل نہ کرنا۔ شاید یہ ہمیں فائدہ پہنچائے یا ہم اُسے بیٹا بنالیں اور وہ انجام سے بےخبر تھے', NULL, NULL, 'e1c30b1d1bd4d1f8088b125fb92764d73e1943a48888e28abf0b9a54415641b3'),
  ('ur.jalandhry', 28, 10, 3262, 'اور موسٰی کی ماں کا دل بے صبر ہو گیا اگر ہم اُن کے دل مضبوط نہ کر دیتے تو قریب تھا کہ وہ اس (قصّے) کو ظاہر کر دیں۔ غرض یہ تھی کہ وہ مومنوں میں رہیں', NULL, NULL, '8ba2ec7481c9bda858b6e1b79e574e628f89d96a110da9e07f7d74f13ecc3e03'),
  ('ur.jalandhry', 28, 11, 3263, 'اور اس کی بہن سے کہا کہ اس کے پیچھے پیچھے چلی جا تو وہ اُسے دور سے دیکھتی رہی اور ان (لوگوں) کو کچھ خبر نہ تھی', NULL, NULL, '89558073b195807fe2a1b7b53d504e5222b5bf0ad9330708cc88bfd2cd38e7f7'),
  ('ur.jalandhry', 28, 12, 3264, 'اور ہم نے پہلے ہی سے اس پر (دائیوں) کے دودھ حرام کر دیئے تھے۔ تو موسٰی کی بہن نے کہا کہ میں تمہیں ایسے گھر والے بتاؤں کہ تمہارے لئے اس (بچے) کو پالیں اور اس کی خیر خواہی (سے پرورش) کریں', NULL, NULL, '0f47dab649b34c4e97973015a463afa2c50cc0a158757884e8c4eca9cdde8b36'),
  ('ur.jalandhry', 28, 13, 3265, 'تو ہم نے (اس طریق سے) اُن کو ان کی ماں کے پاس واپس پہنچا دیا تاکہ اُن کی آنکھیں ٹھنڈی ہوں اور وہ غم نہ کھائیں اور معلوم کریں کہ خدا کا وعدہ سچا ہے لیکن یہ اکثر نہیں جانتے', NULL, NULL, '982a859ada91e74f640ec44e85223510e5688ebc6f794d6b447e7f39389941bd'),
  ('ur.jalandhry', 28, 14, 3266, 'اور جب موسٰی جوانی کو پہنچے اور بھرپور (جوان) ہو گئے تو ہم نے اُن کو حکمت اور علم عنایت کیا۔ اور ہم نیکو کاروں کو ایسا ہی بدلہ دیا کرتے ہیں', NULL, NULL, 'ad3e6a65b9d314196be9fe29af056b6c6ec3496341eda778fd3857476c4dcb77'),
  ('ur.jalandhry', 28, 15, 3267, 'اور وہ ایسے وقت شہر میں داخل ہوئے کہ وہاں کے باشندے بےخبر ہو رہے تھے تو دیکھا کہ وہاں دو شخص لڑ رہے تھے ایک تو موسٰی کی قوم کا ہے اور دوسرا اُن کے دشمنوں میں سے تو جو شخص اُن کی قوم میں سے تھا اس نے دوسرے شخص کے مقابلے میں جو موسٰی کے دشمنوں میں سے تھا مدد طلب کی تو اُنہوں نے اس کو مکا مارا اور اس کا کام تمام کر دیا کہنے لگے کہ یہ کام تو (اغوائے) شیطان سے ہوا بیشک وہ (انسان کا) دشمن اور صریح بہکانے والا ہے', NULL, NULL, 'f3f4b4dd3ad07c091907ccf33249b4d8223472f7d124b88ec6fde0e3b76c06be'),
  ('ur.jalandhry', 28, 16, 3268, 'بولے کہ اے پروردگار میں نے اپنے آپ پر ظلم کیا تو مجھے بخش دے تو خدا نے اُن کو بخش دیا۔ بیشک وہ بخشنے والا مہربان ہے', NULL, NULL, '34a5320f8fa19f0ca14a18fd4dc65edecaf1833d8b7d34203646e6847992f4a4'),
  ('ur.jalandhry', 28, 17, 3269, 'کہنے لگے کہ اے پروردگار تو نے جو مجھ پر مہربانی فرمائی ہے میں (آئندہ) کبھی گنہگاروں کا مددگار نہ بنوں', NULL, NULL, '06563518a1b9620710100ddc87ec2f49db70b7e4fb76c961f24d88d99f9efe44'),
  ('ur.jalandhry', 28, 18, 3270, 'الغرض صبح کے وقت شہر میں ڈرتے ڈرتے داخل ہوئے کہ دیکھیں (کیا ہوتا ہے) تو ناگہاں وہی شخص جس نے کل اُن سے مدد مانگی تھی پھر اُن کو پکار رہا ہے۔ موسٰی نے اس سے کہا کہ تُو تو صریح گمراہ ہے', NULL, NULL, '911206df05bbe8b49e22dad946c27fcae6fc7a6702182377256976b071268bb2'),
  ('ur.jalandhry', 28, 19, 3271, 'جب موسٰی نے ارادہ کیا کہ اس شخص کو جو ان دونوں کا دشمن تھا پکڑ لیں تو وہ (یعنی موسٰی کی قوم کا آدمی) بول اُٹھا کہ جس طرح تم نے کل ایک شخص کو مار ڈالا تھا اسی طرح چاہتے ہو کہ مجھے بھی مار ڈالو۔ تم تو یہی چاہتے ہو کہ ملک میں ظلم وستم کرتے پھرو اور یہ نہیں چاہتے ہو کہ نیکو کاروں میں ہو', NULL, NULL, 'a0e8828df51b51885a939360579bf29a808b654c3f84dcae5babbd314c2bd56e'),
  ('ur.jalandhry', 28, 20, 3272, 'اور ایک شخص شہر کی پرلی طرف سے دوڑتا ہوا آیا (اور) بولا کہ موسٰی (شہر کے) رئیس تمہارے بارے میں صلاحیں کرتے ہیں کہ تم کو مار ڈالیں سو تم یہاں سے نکل جاؤ۔ میں تمہارا خیر خواہ ہوں', NULL, NULL, '237d7ceb46aafdc37df6178c30c569b03a8580d79a6e1de6965d394ff1f8408e'),
  ('ur.jalandhry', 28, 21, 3273, 'موسٰی وہاں سے ڈرتے ڈرتے نکل کھڑے ہوئے کہ دیکھیں (کیا ہوتا ہے) اور دعا کرنے لگے کہ اے پروردگار مجھے ظالم لوگوں سے نجات دے۔', NULL, NULL, 'df6032d2da7647a80f9e4957184dbd75f620df9014c068548826132e56003129'),
  ('ur.jalandhry', 28, 22, 3274, 'اور جب مدین کی طرف رخ کیا تو کہنے لگے اُمید ہے کہ میرا پروردگار مجھے سیدھا رستہ بتائے', NULL, NULL, '1c994cbdae1baa7985234b1576f3d762f2db980bac86d139c438fc5a2e5e1ef6'),
  ('ur.jalandhry', 28, 23, 3275, 'اور جب مدین کے پانی (کے مقام) پر پہنچے تو دیکھا کہ وہاں لوگ جمع ہو رہے (اور اپنے چارپایوں کو) پانی پلا رہے ہیں اور ان کے ایک طرف دو عورتیں (اپنی بکریوں کو) روکے کھڑی ہیں۔ موسٰی نے (اُن سے) کہا تمہارا کیا کام ہے۔ وہ بولیں کہ جب تک چرواہے (اپنے چارپایوں کو) لے نہ جائیں ہم پانی نہیں پلا سکتے اور ہمارے والد بڑی عمر کے بوڑھے ہیں', NULL, NULL, '82200a4ab045e72457a46bb86ea48a81da06761cf83f025d697e1e80a6a16e54'),
  ('ur.jalandhry', 28, 24, 3276, 'تو موسٰی نے اُن کے لئے (بکریوں کو) پانی پلا دیا پھر سائے کی طرف چلے گئے۔ اور کہنے لگے کہ پروردگار میں اس کا محتاج ہوں کہ تو مجھ پر اپنی نعمت نازل فرمائے', NULL, NULL, '6cb802d6d84e783c2c6ee7eede3735059cfa04394a675b895593e278e902ef5e'),
  ('ur.jalandhry', 28, 25, 3277, '(تھوڑی دیر کے بعد) ان میں سے ایک عورت جو شرماتی اور لجاتی چلی آتی تھی۔ موسٰی کے پاس آئی اور کہنے لگی کہ تم کو میرے والد بلاتے ہیں کہ تم نے جو ہمارے لئے پانی پلایا تھا اس کی تم کو اُجرت دیں۔ جب وہ اُن کے پاس آئے اور اُن سے اپنا ماجرا بیان کیا تو اُنہوں نے کہا کہ کچھ خوف نہ کرو۔ تم ظالم لوگوں سے بچ آئے ہو', NULL, NULL, 'b39f7366ee9f360b18ed3640079dc3346721554985c4043fe7b185fea5d022bb'),
  ('ur.jalandhry', 28, 26, 3278, 'ایک لڑکی بولی کہ ابّا ان کو نوکر رکھ لیجئے کیونکہ بہتر نوکر جو آپ رکھیں وہ ہے (جو) توانا اور امانت دار (ہو)', NULL, NULL, '7cd43448808b9abbb5d0ac3fa28809d73c81834758ee3c8070cf4cf6353cbd91'),
  ('ur.jalandhry', 28, 27, 3279, 'اُنہوں نے (موسٰی سے) کہا کہ میں چاہتا ہوں اپنی دو بیٹیوں میں سے ایک کو تم سے بیاہ دوں اس عہد پر کہ تم آٹھ برس میری خدمت کرو اور اگر دس سال پورے کر دو تو تمہاری طرف سے (احسان) ہے اور میں تم پر تکلیف ڈالنی نہیں چاہتا۔ مجھے انشاء الله نیک لوگوں میں پاؤ گے', NULL, NULL, '98e65704b8fd0264a9c033f1f39a105b6fc4c92d928a6a6dbbb1f07612b8de43'),
  ('ur.jalandhry', 28, 28, 3280, 'موسٰی نے کہا کہ مجھ میں اور آپ میں یہ (عہد پختہ ہوا) میں جونسی مدت (چاہوں) پوری کردوں پھر مجھ پر کوئی زیادتی نہ ہو۔ اور ہم جو معاہدہ کرتے ہیں خدا اس کا گواہ ہے', NULL, NULL, '5f17539d01f81a81ba7b4e1b02393ea284807cf214389d1cb915cd5ae82ec880'),
  ('ur.jalandhry', 28, 29, 3281, 'جب موسٰی نے مدت پوری کردی اور اپنے گھر کے لوگوں کو لے کر چلے تو طور کی طرف سے آگ دکھائی دی تو اپنے گھر والوں سے کہنے لگے کہ تم یہاں ٹھیرو۔ مجھے آگ نظر آئی ہے شاید میں وہاں سے (رستے کا) کچھ پتہ لاؤں یا آگ کا انگارہ لے آؤں تاکہ تم تاپو', NULL, NULL, '47486d5ce718f15724ad2cf43823ba1448c2b77ffc9602951e15e354f9dac0fa'),
  ('ur.jalandhry', 28, 30, 3282, 'جب اس کے پاس پہنچے تو میدان کے دائیں کنارے سے ایک مبارک جگہ میں ایک درخت میں سے آواز آئی کہ موسٰی میں تو خدائے رب العالمین ہوں', NULL, NULL, 'e3544e5573bd279367ed27761715535fba0e66deee16396123b4b29475de0cf5'),
  ('ur.jalandhry', 28, 31, 3283, 'اور یہ کہ اپنی لاٹھی ڈالدو۔ جب دیکھا کہ وہ حرکت کر رہی ہے گویا سانپ ہے، تو پیٹھ پھیر کر چل دیئے اور پیچھے پھر کر بھی نہ دیکھا۔ (ہم نے کہا کہ) موسٰی آگے آؤ اور ڈرومت تم امن پانے والوں میں ہو', NULL, NULL, '4ac4c6604a64ee2adfb41a9a8833a537581af876fe1cba43144df9fdd8b73bb9'),
  ('ur.jalandhry', 28, 32, 3284, 'اپنا ہاتھ گریبان میں ڈالو تو بغیر کسی عیب کے سفید نکل آئے گا اور خوف دور ہونے (کی وجہ) سے اپنے بازو کو اپنی طرف سیکڑلو۔ یہ دو دلیلیں تمہارے پروردگار کی طرف سے ہیں (ان کے ساتھ) فرعون اور اس کے درباریوں کے پاس جاؤ کہ وہ نافرمان لوگ ہیں', NULL, NULL, '391881312ac968b59c3b45f80c652af9f84e6a3d55646fe3a9e1d37c2bf4366e'),
  ('ur.jalandhry', 28, 33, 3285, 'موسٰی نے کہا اے پروردگار اُن میں کا ایک شخص میرے ہاتھ سے قتل ہوچکا ہے سو مجھے خوف ہے کہ وہ (کہیں) مجھ کو مار نہ ڈالیں', NULL, NULL, '7790099cf032d530b2dab8a667d02120f273fcdbcb81761b3b6039aa71d19085'),
  ('ur.jalandhry', 28, 34, 3286, 'اور ہارون (جو) میرا بھائی (ہے) اس کی زبان مجھ سے زیادہ فصیح ہے تو اس کو میرے ساتھ مددگار بناکر بھیج کہ میری تصدیق کرے مجھے خوف ہے کہ وہ میری لوگ تکذیب کریں گے', NULL, NULL, '0810279c713d7975d4f2234829b85ff63fa9cd20018bb8db7958753cef910091'),
  ('ur.jalandhry', 28, 35, 3287, '(خدا نے) فرمایا ہم تمہارے بھائی سے تمہارے بازو مضبوط کریں گے اور تم دونوں کو غلبہ دیں گے تو ہماری نشانیوں کے سبب وہ تم تک پہنچ نہ سکیں گے (اور) تم اور جنہوں نے تمہاری پیروی کی غالب رہو گے', NULL, NULL, 'fff1e586fce946186a991fd6945ca57fb443a0fd2436410c44b16ea6b2a40910'),
  ('ur.jalandhry', 28, 36, 3288, 'اور جب موسٰی اُن کے پاس ہماری کھلی نشانیاں لےکر آئے تو وہ کہنے لگے کہ یہ جادو ہے جو اُس نے بنا کھڑا کیا ہے اور یہ باتیں ہم نے اپنے اگلے باپ دادا میں تو (کبھی) سنی نہیں', NULL, NULL, 'c4765fc86a1b1a369b8002bec367256b5ba152222cf82125194cb4b2107c9f6a'),
  ('ur.jalandhry', 28, 37, 3289, 'اور موسٰی نے کہا کہ میرا پروردگار اس شخص کو خوب جانتا ہے جو اس کی طرف سے حق لےکر آیا ہے اور جس کے لئے عاقبت کا گھر (یعنی بہشت) ہے۔ بیشک ظالم نجات نہیں پائیں گے', NULL, NULL, '66c822d1180870fb3590285b5acca056578b77204b6a7dc82f06cf973551dfdf'),
  ('ur.jalandhry', 28, 38, 3290, 'اور فرعون نے کہا کہ اے اہلِ دربار میں تمہارا اپنے سوا کسی کو خدا نہیں جانتا تو ہامان میرے لئے گارے کو آگ لگوا (کر اینٹیں پکوا) دو پھر ایک (اُونچا) محل بنادو تاکہ میں موسٰی کے خدا کی طرف چڑھ جاؤں اور میں تو اُسے جھوٹا سمجھتا ہوں', NULL, NULL, 'e1abe8fbc6daa42484dac7eaa5758dd263ae4091dff893b3194e86a2cf6f787c'),
  ('ur.jalandhry', 28, 39, 3291, 'اور وہ اور اس کے لشکر ملک میں ناحق مغرور ہورہے تھے اور خیال کرتے تھے کہ وہ ہماری طرف لوٹ کر نہیں آئیں گے', NULL, NULL, '77ad4252d5dca0d0ccd0c5a9c7a4a0581d5a089b6dadcf5294e9ad2fb162a0aa'),
  ('ur.jalandhry', 28, 40, 3292, 'تو ہم نے اُن کو اور اُن کے لشکروں کو پکڑلیا اور دریا میں ڈال دیا۔ سو دیکھ لو ظالموں کا کیسا انجام ہوا', NULL, NULL, '5bade310f2f6783f66f19cda6e5766a40b1a219582c28a4b56665ba0ee772485'),
  ('ur.jalandhry', 28, 41, 3293, 'اور ہم نے ان کو پیشوا بنایا تھا وہ (لوگوں) کو دوزخ کی طرف بلاتے تھے اور قیامت کے دن اُن کی مدد نہیں کی جائے گی', NULL, NULL, '8acc250ed37d7548df2760fb80687af890807dd28e9ac340dfc00320d4fcaa55'),
  ('ur.jalandhry', 28, 42, 3294, 'اور اس دنیا سے ہم نے اُن کے پیچھے لعنت لگادی اور وہ قیامت کے روز بھی بدحالوں میں ہوں گے', NULL, NULL, '7737e28aa905a0266accfe3d75e34692e411b743d2f412c99aef490dc20b5947'),
  ('ur.jalandhry', 28, 43, 3295, 'اور ہم نے پہلی اُمتوں کے ہلاک کرنے کے بعد موسٰی کو کتاب دی جو لوگوں کے لئے بصیرت اور ہدایت اور رحمت ہے تاکہ وہ نصیحت پکڑیں', NULL, NULL, '9b03070eb9d86c3cff21f77193b79abe414a8b028e13a3b80739b1bf1ac410f3'),
  ('ur.jalandhry', 28, 44, 3296, 'اور جب ہم نے موسٰی کی طرف حکم بھیجا تو تم (طور کی) غرب کی طرف نہیں تھے اور نہ اس واقعے کے دیکھنے والوں میں تھے', NULL, NULL, '7d3da57d6d1b5f25c8ec1c9e6a81d445c9326463bc9e0a1545270e5460d352c9'),
  ('ur.jalandhry', 28, 45, 3297, 'لیکن ہم نے (موسٰی کے بعد) کئی اُمتوں کو پیدا کیا پھر ان پر مدت طویل گذر گئی اور نہ تم مدین والوں میں رہنے والے تھے کہ ان کو ہماری آیتیں پڑھ پڑھ کر سناتے تھے۔ ہاں ہم ہی تو پیغمبر بھیجنے والے تھے', NULL, NULL, '17253a35b96c735c1f55d9e4992907fd7d94442b98f358f571b82d03d534720b'),
  ('ur.jalandhry', 28, 46, 3298, 'اور نہ تم اس وقت جب کہ ہم نے (موسٰی کو) آواز دی طور کے کنارے تھے بلکہ (تمہارا بھیجا جانا) تمہارے پروردگار کی رحمت ہے تاکہ تم اُن لوگوں کو جن کے پاس تم سے پہلے کوئی ہدایت کرنے والا نہیں آیا ہدایت کرو تاکہ وہ نصیحت پکڑیں', NULL, NULL, '6cbca6a9d6b18f36b34243ea0ef1cab78f34327a4c6cc0980cda7e3be0b97f54'),
  ('ur.jalandhry', 28, 47, 3299, 'اور (اے پیغمبر ہم نے تو کو اس لئے بھیجا ہے کہ) ایسا نہ ہو کہ اگر ان (اعمال) کے سبب جو اُن کے ہاتھ آگے بھیج چکے ہیں ان پر کوئی مصیبت واقع ہو تو یہ کہنے لگیں کہ اے پروردگار تو نے ہماری طرف کوئی پیغمبر کیوں نہ بھیجا کہ ہم تیری آیتوں کی پیروی کرنے اور ایمان لانے والوں میں ہوتے', NULL, NULL, '68eac6335ee12dbead5142e7535449e64109b7cb07824c10a542c0f289077ae6'),
  ('ur.jalandhry', 28, 48, 3300, 'پھر جب اُن کے پاس ہماری طرف سے حق آپہنچا تو کہنے لگے کہ جیسی (نشانیاں) موسٰی کو ملی تھیں ویسی اس کو کیوں نہیں ملیں۔ کیا جو (نشانیاں) پہلے موسٰی کو دی گئی تھیں اُنہوں نے اُن سے کفر نہیں کیا۔ کہنے لگے کہ دونوں جادوگر ہیں ایک دوسرے کے موافق۔ اور بولے کہ ہم سب سے منکر ہیں', NULL, NULL, '70eab57206196dc09f69849d5775fa40f8292ce698454abf3609dfbb2a2e5366')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 28, 49, 3301, 'کہہ دو کہ اگر سچے ہو تو تم خدا کے پاس سے کوئی کتاب لے آؤ جو ان دونوں (کتابوں) سے بڑھ کر ہدایت کرنے والی ہو۔ تاکہ میں بھی اسی کی پیروی کروں', NULL, NULL, '87bee2f700719faf1a573a8ec105027c39763c5db58ad83ee835e2e55168caf1'),
  ('ur.jalandhry', 28, 50, 3302, 'پھر اگر یہ تمہاری بات قبول نہ کریں تو جان لو کہ یہ صرف اپنی خواہشوں کی پیروی کرتے ہیں۔ اور اس سے زیادہ کون گمراہ ہوگا جو خدا کی ہدایت کو چھوڑ کر اپنی خواہش کے پیچھے چلے۔ بیشک خدا ظالم لوگوں کو ہدایت نہیں دیتا', NULL, NULL, 'ba2dd531a668d1dadc8bd372afc9f8b2b9069c6980a1d9e0296f43b9a2bd7c14'),
  ('ur.jalandhry', 28, 51, 3303, 'اور ہم پے درپے اُن لوگوں کے پاس (ہدایت کی) باتیں بھیجتے رہے ہیں تاکہ نصیحت پکڑیں', NULL, NULL, '20c096541709fdac66d666f4afdbbabcab82bcbcc9baa13fa88ca9673e54fc05'),
  ('ur.jalandhry', 28, 52, 3304, 'جن لوگوں کو ہم نے اس سے پہلے کتاب دی تھی وہ اس پر ایمان لے آتے ہیں', NULL, NULL, '62a5b1b0e7ccdcd2fa06c19d0899535fb08f841ce8e97f3b1be43e40dc49fad7'),
  ('ur.jalandhry', 28, 53, 3305, 'اور جب (قرآن) اُن کو پڑھ کر سنایا جاتا ہے تو کہتے ہیں کہ ہم اس پر ایمان لے آئے بیشک وہ ہمارے پروردگار کی طرف سے برحق ہے اور ہم تو اس سے پہلے کے حکمبردار ہیں', NULL, NULL, '0f95610bb4208a99de2055fb91c508a3e7cce61bcddd45bbd87b02de43819dc1'),
  ('ur.jalandhry', 28, 54, 3306, 'ان لوگوں کو دگنا بدلہ دیا جائے گا کیونکہ صبر کرتے رہے ہیں اور بھلائی کے ساتھ برائی کو دور کرتے ہیں اور جو (مال) ہم نے اُن کو دیا ہے اس میں سے خرچ کرتے ہیں', NULL, NULL, 'eb793fa76ded6724d9df78239e722aed1de08bd54db42ac89962b68993290ee8'),
  ('ur.jalandhry', 28, 55, 3307, 'اور جب بیہودہ بات سنتے ہیں تو اس سے منہ پھیر لیتے ہیں اور کہتے ہیں کہ ہم کو ہمارے اعمال اور تم کو تمہارے اعمال۔ تم کو سلام۔ ہم جاہلوں کے خواستگار نہیں ہیں', NULL, NULL, '7aeb7c28f4e90f1ad1d3e5bf7bad96168a272943e673bd23286ee1a492b6aacb'),
  ('ur.jalandhry', 28, 56, 3308, '(اے محمدﷺ) تم جس کو دوست رکھتے ہو اُسے ہدایت نہیں کر سکتے بلکہ خدا ہی جس کو چاہتا ہے ہدایت کرتا ہے اور وہ ہدایت پانیوالوں کو خوب جانتا ہے', NULL, NULL, '757fbda0f4b30e938e4ae3ef5b747d7cc0c67816c920c35cc961a636fe7d11bc'),
  ('ur.jalandhry', 28, 57, 3309, 'اور کہتے ہیں کہ اگر ہم تمہارے ساتھ ہدایت کی پیروی کریں تو اپنے ملک سے اُچک لئے جائیں۔ کیا ہم نے اُن کو حرم میں جو امن کا مقام ہے جگہ نہیں دی۔ جہاں ہر قسم کے میوے پہنچائے جاتے ہیں (اور یہ) رزق ہماری طرف سے ہے لیکن ان میں سے اکثر نہیں جانتے', NULL, NULL, '83a1c1acabe716cd7a791ee1065faa108a7d7d6da1e3489fec62f2b3fa6ab7dc'),
  ('ur.jalandhry', 28, 58, 3310, 'اور ہم نے بہت سی بستیوں کو ہلاک کر ڈالا جو اپنی (فراخی) معیشت میں اترا رہے تھے۔ سو یہ اُن کے مکانات ہیں جو اُن کے بعد آباد ہی نہیں ہوئے مگر بہت کم۔ اور اُن کے پیچھے ہم ہی اُن کے وارث ہوئے', NULL, NULL, '85f52a47129f41b78f6da9ef6ada15b8018f9e8c4499e79a040d32ba6918ae62'),
  ('ur.jalandhry', 28, 59, 3311, 'اور تمہارا پروردگار بستیوں کو ہلاک نہیں کیا کرتا۔ جب تک اُن کے بڑے شہر میں پیغمبر نہ بھیج لے جو اُن کو ہماری آیتیں پڑھ پڑھ کر سنائے اور ہم بستیوں کو ہلاک نہیں کیا کرتے مگر اس حالت میں کہ وہاں کے باشندے ظالم ہوں', NULL, NULL, 'b4e62710ccf81b0ffabfdbc6a43600e3a0397e4d85e3f9a196e9a020e95726a9'),
  ('ur.jalandhry', 28, 60, 3312, 'اور جو چیز تم کو دی گئی ہے وہ دنیا کی زندگی کا فائدہ اور اس کی زینت ہے۔ اور جو خدا کے پاس ہے وہ بہتر اور باقی رہنے والی ہے۔ کیا تم سمجھتے نہیں؟', NULL, NULL, 'fb28aab07ce3f26e30fc146fd789a5effda443ef11bf47e867ea0f83b3cd1a09'),
  ('ur.jalandhry', 28, 61, 3313, 'بھلا جس شخص سے ہم نے نیک وعدہ کیا اور اُس نے اُسے حاصل کرلیا تو کیا وہ اس شخص کا سا ہے جس کو ہم نے دنیا کی زندگی کے فائدے سے بہرہ مند کیا پھر وہ قیامت کے روز ان لوگوں میں ہو جو (ہمارے روبرو) حاضر کئے جائیں گے', NULL, NULL, '30e8abf290c096b17de839b7fe7104038c74a0000a0c7139d277f40e4db7bf58'),
  ('ur.jalandhry', 28, 62, 3314, 'اور جس روز خدا اُن کو پکارے گا اور کہے گا کہ میرے وہ شریک کہاں ہیں جن کا تمہیں دعویٰ تھا', NULL, NULL, '6225a1b31a184885e22d2234778573c46feb44184a054591c8e4d2f8b5d2d37e'),
  ('ur.jalandhry', 28, 63, 3315, '(تو) جن لوگوں پر (عذاب کا) حکم ثابت ہوچکا ہوگا وہ کہیں گے کہ ہمارے پروردگار یہ وہ لوگ ہیں جن کو ہم نے گمراہ کیا تھا۔ اور جس طرح ہم خود گمراہ ہوئے تھے اسی طرح اُن کو گمراہ کیا تھا (اب) ہم تیری طرف (متوجہ ہوکر) اُن سے بیزار ہوتے ہیں یہ ہمیں نہیں پوجتے تھے', NULL, NULL, '461e461d6d7cd5e0184baceb24ea5937e0cc3c316230b3e8db7d324bff57795c'),
  ('ur.jalandhry', 28, 64, 3316, 'اور کہا جائے گا کہ اپنے شریکوں کو بلاؤ۔ تو وہ اُن کو پکاریں گے اور وہ اُن کو جواب نہ دے سکیں گے اور (جب) عذاب کو دیکھ لیں گے (تو تمنا کریں گے کہ) کاش وہ ہدایت یاب ہوتے', NULL, NULL, 'd7b5c5c4ff84f9425b885b04a6ab248fd9a9a18bb9b61b519f895f8122d79ea7'),
  ('ur.jalandhry', 28, 65, 3317, 'اور جس روز خدا اُن کو پکارے گا اور کہے گا کہ تم نے پیغمبروں کو کیا جواب دیا', NULL, NULL, '8fa2d88aa921a09f17691ed517d4872abc3bd8bfb86c888581432161b9a51a53'),
  ('ur.jalandhry', 28, 66, 3318, 'تو وہ اس روز خبروں سے اندھے ہو جائیں گے، اور آپس میں کچھ بھی پوچھ نہ سکیں گے', NULL, NULL, '1de03756802e31fde253376c34aa410a8e637f20f4d1d3936517b6d6c591e268'),
  ('ur.jalandhry', 28, 67, 3319, 'لیکن جس نے توبہ کی اور ایمان لایا اور عمل نیک کئے تو اُمید ہے کہ وہ نجات پانے والوں میں ہو', NULL, NULL, '7f7f1724b9e6935785e86d521d683edda85f573a899cc9c0578e4f03abeeb0c4'),
  ('ur.jalandhry', 28, 68, 3320, 'اور تمہارا پروردگار جو چاہتا ہے پیدا کرتا ہے اور (جسے چاہتا ہے) برگزیدہ کرلیتا ہے۔ ان کو اس کا اختیار نہیں ہے۔ یہ جو شرک کرتے ہیں خدا اس سے پاک وبالاتر ہے', NULL, NULL, 'c63cd51a96adacbc0de7043d546fd52f280eba94115277752092e38fecc7618c'),
  ('ur.jalandhry', 28, 69, 3321, 'اور ان کے سینے جو کچھ مخفی کرتے اور جو یہ ظاہر کرتے ہیں تمہارا پروردگار اس کو جانتا ہے', NULL, NULL, '55b685b0f2acc41633e738423e26c9fa1aae9d801694b4f9656712682208d0a4'),
  ('ur.jalandhry', 28, 70, 3322, 'اور وہی خدا ہے اس کے سوا کوئی معبود نہیں دنیا اور آخرت میں اُسی کی تعریف ہے اور اُسی کا حکم اور اسی کی طرف تم لوٹائے جاؤ گے', NULL, NULL, 'b76f940d5050a41cf29a0bd38b2c74403048050265e2648312bb100acd492c59'),
  ('ur.jalandhry', 28, 71, 3323, 'کہو بھلا دیکھو تو اگر خدا تم پر ہمیشہ قیامت کے دن تک رات (کی تاریکی) کئے رہے تو خدا کے سوا کون معبود ہے ہے جو تم کو روشنی لا دے تو کیا تم سنتے نہیں؟', NULL, NULL, 'fc61e789e257481349b560e4c42543f701482987ec0d5c308ebc65a3c7c936f5'),
  ('ur.jalandhry', 28, 72, 3324, 'کہو تو بھلا دیکھو تو اگر خدا تم پر ہمیشہ قیامت تک دن کئے رہے تو خدا کے سوا کون معبود ہے کہ تم کو رات لا دے جس میں تم آرام کرو۔ تو کیا تم دیکھتے نہیں؟', NULL, NULL, '9b5a6ff39792cacb001c11757304066637f5cbb88159f91f6cbb23b7982c63ef'),
  ('ur.jalandhry', 28, 73, 3325, 'اور اس نے اپنی رحمت سے تمہارے لئے رات کو اور دن کو بنایا تاکہ تم اس میں آرام کرو اور اس میں اس کا فضل تلاش کرو اور تاکہ شکر کرو', NULL, NULL, '3c8241e7fc537f0f19331a3f2da9364dbe997caf455a0851862e8833ef8d3f0c'),
  ('ur.jalandhry', 28, 74, 3326, 'اور جس دن وہ اُن کو پکارے گا اور کہے گا کہ میرے وہ شریک جن کا تمہیں دعویٰ تھا کہاں گئے؟', NULL, NULL, '46f8a2a24004615e73d6579b8d8a8abb0ab4ddf4d64eef1a79cad3b6e64a7a00'),
  ('ur.jalandhry', 28, 75, 3327, 'اور ہم ہر ایک اُمت میں سے گواہ نکال لیں گے پھر کہیں گے کہ اپنی دلیل پیش کرو تو وہ جان لیں گے کہ سچ بات خدا کی ہے اور جو کچھ وہ افتراء کیا کرتے تھے ان سے جاتا رہے گا', NULL, NULL, '5a169d74c75d2150158467df72fc14b575b4641cf6a9c99f160acd5ffa55fac6'),
  ('ur.jalandhry', 28, 76, 3328, 'قارون موسٰی کی قوم میں سے تھا اور ان پر تعدّی کرتا تھا۔ اور ہم نے اس کو اتنے خزانے دیئے تھے کہ اُن کی کنجیاں ایک طاقتور جماعت کو اُٹھانی مشکل ہوتیں جب اس سے اس کی قوم نے کہا کہ اترائیے مت۔ کہ خدا اترانے والوں کو پسند نہیں کرتا', NULL, NULL, '91997460547dc0ed7c61a2199341fcd693a244e3933af32060ff3fdb532dc9de'),
  ('ur.jalandhry', 28, 77, 3329, 'اور جو (مال) تم کو خدا نے عطا فرمایا ہے اس سے آخرت کی بھلائی طلب کیجئے اور دنیا سے اپنا حصہ نہ بھلائیے اور جیسی خدا نے تم سے بھلائی کی ہے (ویسی) تم بھی (لوگوں سے) بھلائی کرو۔ اور ملک میں طالب فساد نہ ہو۔ کیونکہ خدا فساد کرنے والوں کو دوست نہیں رکھتا', NULL, NULL, 'e1cacf3952cb2e745ec28e65d41281ec3af8c516907d602a80c07ae1300201a3'),
  ('ur.jalandhry', 28, 78, 3330, 'بولا کہ یہ (مال) مجھے میری دانش (کے زور) سے ملا ہے کیا اس کو معلوم نہیں کہ خدا نے اس سے پہلے بہت سی اُمتیں جو اس سے قوت میں بڑھ کر اور جمعیت میں بیشتر تھیں ہلاک کر ڈالی ہیں۔ اور گنہگاروں سے اُن کے گناہوں کے بارے میں پوچھا نہیں جائے گا', NULL, NULL, '868af07a5731e359b09eb4ee79c09a7ceb4887d1b8411af837aac3ce15cc46a4'),
  ('ur.jalandhry', 28, 79, 3331, 'تو (ایک روز) قارون (بڑی) آرائش (اور ٹھاٹھ) سے اپنی قوم کے سامنے نکلا۔ جو لوگ دنیا کی زندگی کے طالب تھے کہنے لگے کہ جیسا (مال ومتاع) قارون کو ملا ہے کاش ایسا ہی ہمیں بھی ملے۔ وہ تو بڑا ہی صاحب نصیب ہے', NULL, NULL, '6ca7b035df2f6feae473d24ff0a20ac3c550c9680fddc9e8d30e7fb562b7ce84'),
  ('ur.jalandhry', 28, 80, 3332, 'اور جن لوگوں کو علم دیا گیا تھا وہ کہنے لگے کہ تم پر افسوس۔ مومنوں اور نیکوکاروں کے لئے (جو) ثواب خدا (کے ہاں تیار ہے وہ) کہیں بہتر ہے اور وہ صرف صبر کرنے والوں ہی کو ملے گا', NULL, NULL, '00f6a59a62fa0f99d94d124951c0a2ef09c475a019ccedda157608d1583ebf92'),
  ('ur.jalandhry', 28, 81, 3333, 'پس ہم نے قارون کو اور اس کے گھر کو زمین میں دھنسا دیا تو خدا کے سوا کوئی جماعت اس کی مددگار نہ ہوسکی۔ اور نہ وہ بدلہ لے سکا', NULL, NULL, '3b4f4b9a0fa4e70be0fe1821f2bb76eba9f8045576a0cc276878b1a7ead0fca6'),
  ('ur.jalandhry', 28, 82, 3334, 'اور وہ لوگ جو کل اُس کے رتبے کی تمنا کرتے تھے صبح کو کہنے لگے ہائے شامت! خدا ہی تو اپنے بندوں میں سے جس کے لئے چاہتا ہے رزق فراخ کر دیتا ہے اور (جس کے لئے چاہتا ہے) تنگ کر دیتا ہے۔ اگر خدا ہم پر احسان نہ کرتا تو ہمیں بھی دھنسا دیتا۔ ہائے خرابی! کافر نجات نہیں پا سکتے', NULL, NULL, 'a74470d2f0a58ec4aec02556cf27ad7bd2b96468fe75a81fa0f16f1a984fdb6b'),
  ('ur.jalandhry', 28, 83, 3335, 'وہ (جو) آخرت کا گھر (ہے) ہم نے اُسے اُن لوگوں کے لئے (تیار) کر رکھا ہے جو ملک میں ظلم اور فساد کا ارادہ نہیں رکھتے اور انجام (نیک) تو پرہیزگاروں ہی کا ہے', NULL, NULL, '712cbe9aa3ba790db28ae8da882534af2c415b73b0fc136ebac19bfe84f4630d'),
  ('ur.jalandhry', 28, 84, 3336, 'جو شخص نیکی لے کر آئے گا اس کے لئے اس سے بہتر (صلہ موجود) ہے اور جو برائی لائے گا تو جن لوگوں نے برے کام کئے ان کو بدلہ بھی اسی طرح کا ملے گا جس طرح کے وہ کام کرتے تھے', NULL, NULL, '7267464dd43ad68ab31acd5d036fb90c8bef29724f89ac3c8657978ebe76923a'),
  ('ur.jalandhry', 28, 85, 3337, '(اے پیغمبر) جس (خدا) نے تم پر قرآن (کے احکام) کو فرض کیا ہے وہ تمہیں بازگشت کی جگہ لوٹا دے گا۔ کہہ دو کہ میرا پروردگار اس شخص کو بھی خوب جانتا ہے جو ہدایت لےکر آیا اور (اس کو بھی) جو صریح گمراہی میں ہے', NULL, NULL, 'e6741e10bd68b2b4294efd9baad7d3bfea09b3ae21f672681daa0d577edd6eb1'),
  ('ur.jalandhry', 28, 86, 3338, 'اور تمہیں اُمید نہ تھی کہ تم پر کتاب نازل کی جائے گی۔ مگر تمہارے پروردگار کی مہربانی سے (نازل ہوئی) تو تم ہرگز کافروں کے مددگار نہ ہونا', NULL, NULL, 'd491654c1145e387440f42db4e4456b1f1e2022e737d2e3667414ff995a64a62'),
  ('ur.jalandhry', 28, 87, 3339, 'اور وہ تمہیں خدا کی آیتوں کی تبلیغ سے بعد اس کے کہ وہ تم پر نازل ہوچکی ہیں روک نہ دیں اور اپنے پروردگار کو پکارتے رہو اور مشرکوں میں ہرگز نہ ہو جیو', NULL, NULL, 'b3447c3e26db9c850cc6cf8b3531dd08cc37424913dc299025d81e328c90742c'),
  ('ur.jalandhry', 28, 88, 3340, 'اور خدا کے ساتھ کسی اور کو معبود (سمجھ کر) نہ پکارنا اس کے سوا کوئی معبود نہیں۔ اس کی ذات (پاک) کے سوا ہر چیز فنا ہونے والی ہے۔ اسی کا حکم ہے اور اسی کی طرف تم لوٹ کر جاؤ گے', NULL, NULL, '846c26ca9f2168a5a32577b748a974a2d0f83212397446fb19fdd9613dd70b5e'),
  ('ur.jalandhry', 29, 1, 3341, 'الم', NULL, NULL, '58bc1e3007bc0ed70b737b562ad04a88867c38e78e58e2f15c3f43c9be783acb'),
  ('ur.jalandhry', 29, 2, 3342, 'کیا لوگ یہ خیال کئے ہوئے ہیں کہ صرف یہ کہنے سے کہ ہم ایمان لے آئے چھوڑ دیئے جائیں گے اور اُن کی آزمائش نہیں کی جائے گی', NULL, NULL, 'd551bb81ddb0df1521affb5433497d60605592c9758a5b6245ff36654a7dd34d'),
  ('ur.jalandhry', 29, 3, 3343, 'اور جو لوگ اُن سے پہلے ہو چکے ہیں ہم نے اُن کو بھی آزمایا تھا (اور ان کو بھی آزمائیں گے) سو خدا اُن کو ضرور معلوم کریں گے جو (اپنے ایمان میں) سچے ہیں اور اُن کو بھی جو جھوٹے ہیں', NULL, NULL, 'f4fc5f3eac928585d202d44756f66f00b623eabbd00f4b4ea9b9ae6e4332a516'),
  ('ur.jalandhry', 29, 4, 3344, 'کیا وہ لوگ جو برے کام کرتے ہیں یہ سمجھے ہوئے ہیں کہ یہ ہمارے قابو سے نکل جائیں گے۔ جو خیال یہ کرتے ہیں برا ہے', NULL, NULL, '6c9e7491f3fa8b059b3ba92053eddf827611ffd119aac9a1107aac4d30946ec6'),
  ('ur.jalandhry', 29, 5, 3345, 'جو شخص خدا کی ملاقات کی اُمید رکھتا ہو خدا کا (مقرر کیا ہوا) وقت ضرور آنے والا ہے۔ اور وہ سننے والا اور جاننے والا ہے', NULL, NULL, 'e142232b2b80cc5c572dfb22f961a373e5db33e656ab70ea003c24818154bce0'),
  ('ur.jalandhry', 29, 6, 3346, 'اور جو شخص محنت کرتا ہے تو اپنے ہی فائدے کے لئے محنت کرتا ہے۔ اور خدا تو سارے جہان سے بےپروا ہے', NULL, NULL, '00975cb44ab0d142a8234761f544fa64fdfd3b3c7809f48a716f76056ff7161c'),
  ('ur.jalandhry', 29, 7, 3347, 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے ہم ان کے گناہوں کو اُن سے دور کردیں گے اور ان کو ان کے اعمال کا بہت اچھا بدلہ دیں گے', NULL, NULL, 'e5aa24c8ee8d4fcd769229ebf18906ed51659ed6d5bb218ebbef157dde0e6d82'),
  ('ur.jalandhry', 29, 8, 3348, 'اور ہم نے انسان کو اپنے ماں باپ کے ساتھ نیک سلوک کرنے کا حکم دیا ہے۔ (اے مخاطب) اگر تیرے ماں باپ تیرے درپے ہوں کہ تو میرے ساتھ کسی کو شریک بنائے جس کی حقیقت کی تجھے واقفیت نہیں۔ تو ان کا کہنا نہ مانیو۔ تم (سب) کو میری طرف لوٹ کر آنا ہے۔ پھر جو کچھ تم کرتے تھے میں تم کو جتا دوں گا', NULL, NULL, '79b3d2bc5fc9dff11396153716b82ee313df3644bdd388ca0c73da3ba431190c'),
  ('ur.jalandhry', 29, 9, 3349, 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے ان کو ہم نیک لوگوں میں داخل کریں گے', NULL, NULL, '65cbb0ae685240fedf9206fa36ec9d2f19accad846126f63f575d9f30e38adf1'),
  ('ur.jalandhry', 29, 10, 3350, 'اور بعض لوگ ایسے ہیں جو کہتے ہیں کہ ہم خدا پر ایمان لائے جب اُن کو خدا (کے رستے) میں کوئی ایذا پہنچتی ہے تو لوگوں کی ایذا کو (یوں) سمجھتے ہیں جیسے خدا کا عذاب۔ اگر تمہارے پروردگار کی طرف سے مدد پہنچے تو کہتے ہیں کہ ہم تمہارے ساتھ تھے۔ کیا جو اہل عالم کے سینوں میں ہے خدا اس سے واقف نہیں؟', NULL, NULL, 'abe3e882aa4148aaa56b5f9e9eb64c6f8df69f7b86fbefee97a769a2c94b28c4'),
  ('ur.jalandhry', 29, 11, 3351, 'اور خدا اُن کو ضرور معلوم کرے گا جو (سچے) مومن ہیں اور منافقوں کو بھی معلوم کرکے رہے گا', NULL, NULL, '5e75e7c7add7979623dba7ae4a44e79a2bd1269b349b542eb5236f09231deaa2'),
  ('ur.jalandhry', 29, 12, 3352, 'اور جو کافر ہیں وہ مومنوں سے کہتے ہیں کہ ہمارے طریق کی پیروی کرو ہم تمہارے گناہ اُٹھالیں گے۔ حالانکہ وہ اُن کے گناہوں کا کچھ بھی بوجھ اُٹھانے والے نہیں۔ کچھ شک نہیں کہ یہ جھوٹے ہیں', NULL, NULL, '30bb36390fc98565cfe665d8572e023204d174bc60866294cf2b25124612ad3c'),
  ('ur.jalandhry', 29, 13, 3353, 'اور یہ اپنے بوجھ بھی اُٹھائیں گے اور اپنے بوجھوں کے ساتھ اور (لوگوں کے) بوجھ بھی۔ اور جو بہتان یہ باندھتے رہے قیامت کے دن اُن کی اُن سے ضرور پرسش ہوگی', NULL, NULL, 'f50a03725cdc97464bd3e3c4e7a2c33ae22ba0f168b5d219899f4894307dc761'),
  ('ur.jalandhry', 29, 14, 3354, 'اور ہم نے نوحؑ کو اُن کی قوم کی طرف بھیجا تو وہ ان میں پچاس برس کم ہزار برس رہے پھر اُن کو طوفان (کے عذاب) نے آپکڑا۔ اور وہ ظالم تھے', NULL, NULL, '7a1d058c8d64558e43614e34c5e7d6fb3a1a9ff2c9168735b718dc4196267d6a'),
  ('ur.jalandhry', 29, 15, 3355, 'پھر ہم نے نوحؑ کو اور کشتی والوں کو نجات دی اور کشتی کو اہل عالم کے لئے نشانی بنا دیا', NULL, NULL, '126e800f5e8881671b2b834db39cb9fb3207ee52ea4c6280d97306949ffe5c80'),
  ('ur.jalandhry', 29, 16, 3356, 'اور ابراہیمؑ کو (یاد کرو) جب اُنہوں نے اپنی قوم سے کہا کہ خدا کی عبادت کرو اور اس سے ڈرو اگر تم سمجھ رکھتے ہو تو یہ تمہارے حق میں بہتر ہے', NULL, NULL, '7a72813d3e11283630081724d1c43c37320148fe946ce81c26c5e782e6a33dba'),
  ('ur.jalandhry', 29, 17, 3357, 'تو تم خدا کو چھوڑ کر بتوں کو پوجتے اور طوفان باندھتے ہو تو جن لوگوں کو تم خدا کے سوا پوجتے ہو وہ تم کو رزق دینے کا اختیار نہیں رکھتے پس خدا ہی کے ہاں سے رزق طلب کرو اور اسی کی عبادت کرو اور اسی کا شکر کرو اسی کی طرف تم لوٹ کر جاؤ گے', NULL, NULL, 'a07648e165a8edf095ba5a177e74e2fe674d90808d1e347efb94b39d0e21441e'),
  ('ur.jalandhry', 29, 18, 3358, 'اور اگر تم (میری) تکذیب کرو تو تم سے پہلے بھی اُمتیں (اپنے پیغمبروں کی) تکذیب کرچکی ہیں۔ اور پیغمبر کے ذمے کھول کر سنا دینے کے سوا اور کچھ نہیں', NULL, NULL, '2834a87d87e67e1705333c0e3f3de9e7ae062ed808a477a38b75b8214238281c'),
  ('ur.jalandhry', 29, 19, 3359, 'کیا اُنہوں نے نہیں دیکھا کہ خدا کس طرح خلقت کو پہلی بار پیدا کرتا پھر (کس طرح) اس کو بار بار پیدا کرتا رہتا ہے۔ یہ خدا کو آسان ہے', NULL, NULL, '3f0d4e552f445ab4ae73649e68646f8b9d21a083f0102b1c88449b44fcc1572a'),
  ('ur.jalandhry', 29, 20, 3360, 'کہہ دو کہ ملک میں چلو پھرو اور دیکھو کہ اس نے کس طرح خلقت کو پہلی دفعہ پیدا کیا ہے پھر خدا ہی پچھلی پیدائش پیدا کرے گا۔ بےشک خدا ہر چیز پر قادر ہے', NULL, NULL, '30418d20fe2b212d438dd7c88a156c8c7b7ff56d40671c12e7fedaeccffa836c'),
  ('ur.jalandhry', 29, 21, 3361, 'وہ جسے چاہے عذاب دے اور جس پر چاہے رحم کرے۔ اور اُسی کی طرف تم لوٹائے جاؤ گے', NULL, NULL, '475cab60ba178085962435aa9cc11b28c682825f523349583c41647a21fbd98c'),
  ('ur.jalandhry', 29, 22, 3362, 'اور تم (اُس کو) نہ زمین میں عاجز کرسکتے ہو نہ آسمان میں اور نہ خدا کے سوا تمہارا کوئی دوست ہے اور نہ مددگار', NULL, NULL, '2b982d547f69e4e71fedc8cd107df7dbd8274706f3ec20c634a689443b8419f0'),
  ('ur.jalandhry', 29, 23, 3363, 'اور جن لوگوں نے خدا کی آیتوں سے اور اس کے ملنے سے انکار کیا وہ میری رحمت سے نااُمید ہوگئے ہیں اور ان کو درد دینے والا عذاب ہوگا', NULL, NULL, '07117d03900b0c02eeab9b61f90d3e49585a41fa97f42caae7a6d3f929ec12f8'),
  ('ur.jalandhry', 29, 24, 3364, 'تو اُن کی قوم کے لوگ جواب میں بولے تو یہ بولے کہ اُسے مار ڈالو یا جلا دو۔ مگر خدا نے اُن کو آگ (کی سوزش) سے بچالیا۔ جو لوگ ایمان رکھتے ہیں اُن کے لئے اس میں نشانیاں ہیں', NULL, NULL, '5f8c6308342cdf4b02f87660e6380cb83f8ece84abe564d942516f142f09b5f5'),
  ('ur.jalandhry', 29, 25, 3365, 'اور ابراہیم نے کہا کہ تم جو خدا کو چھوڑ کر بتوں کو لے بیٹھے ہو تو دنیا کی زندگی میں باہم دوستی کے لئے (مگر) پھر قیامت کے دن تم ایک دوسرے (کی دوستی) سے انکار کر دو گے اور ایک دوسرے پر لعنت بھیجو گے اور تمہارا ٹھکانا دوزخ ہوگا اور کوئی تمہارا مددگار نہ ہوگا', NULL, NULL, '4caddea2572529efd552c95510f13f0216edd2b6bf718efdb10ddc59de23547a'),
  ('ur.jalandhry', 29, 26, 3366, 'پس اُن پر (ایک) لوط ایمان لائے اور (ابراہیم) کہنے لگے کہ میں اپنے پروردگار کی طرف ہجرت کرنے والا ہوں۔ بیشک وہ غالب حکمت والا ہے', NULL, NULL, 'daa121c65836e247d78e4075fc2da517c205f67f444bbe1e09bfce2986ea91c8'),
  ('ur.jalandhry', 29, 27, 3367, 'اور ہم نے اُن کو اسحٰق اور یعقوب بخشے اور اُن کی اولاد میں پیغمبری اور کتاب (مقرر) کر دی اور ان کو دنیا میں بھی اُن کا صلہ عنایت کیا اور وہ آخرت میں بھی نیک لوگوں میں ہوں گے', NULL, NULL, 'c72b86af94115659bef89a7b7bff7ae0246bc7ebee36535bd76f78ceb364fbea'),
  ('ur.jalandhry', 29, 28, 3368, 'اور لوط (کو یاد کرو) جب اُنہوں نے اپنی قوم سے کہا کہ تم (عجب) بےحیائی کے مرتکب ہوتے ہو۔ تم سے پہلے اہل عالم میں سے کسی نے ایسا کام نہیں کیا', NULL, NULL, 'ae1dcd00bd9438c67e82519dfbad8e4d4f85cf6cfed40acc3ce26512df09c1c0'),
  ('ur.jalandhry', 29, 29, 3369, 'تم کیوں (لذت کے ارادے سے) لونڈوں کی طرف مائل ہوتے اور (مسافروں کی) رہزنی کرتے ہو اور اپنی مجلسوں میں ناپسندیدہ کام کرتے ہو۔ تو اُن کی قوم کے لوگ جواب میں بولے تو یہ بولے کہ اگر تم سچے ہو تو ہم پر عذاب لے آؤ', NULL, NULL, 'a99d832022456ebba21fd8e59f6027353a4087cefb14195c010d040967411725'),
  ('ur.jalandhry', 29, 30, 3370, 'لوط نے کہا کہ اے میرے پروردگار ان مفسد لوگوں کے مقابلے میں مجھے نصرت عنایت فرما', NULL, NULL, '5129d1f9366522b00d153d7b74d9efe435d612e8cd768509d0ce86622b2859dc'),
  ('ur.jalandhry', 29, 31, 3371, 'اور جب ہمارے فرشتے ابراہیم کے پاس خوشی کی خبر لے کر آئے تو کہنے لگے کہ ہم اس بستی کے لوگوں کو ہلاک کر دینے والے ہیں کہ یہاں کے رہنے والے نافرمان ہیں', NULL, NULL, '2dc425cc6da52fa2e223e8e77a4655f198cab3e1598609720faaf589603e92ab'),
  ('ur.jalandhry', 29, 32, 3372, 'ابراہیم نے کہا کہ اس میں تو لوط بھی ہیں۔ وہ کہنے لگے کہ جو لوگ یہاں (رہتے) ہیں ہمیں سب معلوم ہیں۔ ہم اُن کو اور اُن کے گھر والوں کو بچالیں گے بجز اُن کی بیوی کے وہ پیچھے رہنے والوں میں ہوگی', NULL, NULL, 'ecc4596e19bdb4d7dab7944923b51fc8ae27a9e5c1e8969c04d950632b212214'),
  ('ur.jalandhry', 29, 33, 3373, 'اور جب ہمارے فرشتے لوط کے پاس آئے تو وہ اُن (کی وجہ) سے ناخوش اور تنگ دل ہوئے۔ فرشتوں نے کہا کچھ خوف نہ کیجئے۔ اور نہ رنج کیجئے ہم آپ کو اور آپ کے گھر والوں کو بچالیں گے مگر آپ کی بیوی کہ پیچھے رہنے والوں میں ہوگی', NULL, NULL, '65d86eb8efaa50ae8287cd0eebd6fe7b7739ae268ed35d98f32f9d5af2d07268'),
  ('ur.jalandhry', 29, 34, 3374, 'ہم اس بستی کے رہنے والوں پر اس سبب سے کہ یہ بدکرداری کرتے رہے ہیں آسمان سے عذاب نازل کرنے والے ہیں', NULL, NULL, 'e79149c4ed360c3b64b21f82e89afe6b48e3381a0971edb18f5a7b30b865ade3'),
  ('ur.jalandhry', 29, 35, 3375, 'اور ہم نے سمجھنے والے لوگوں کے لئے اس بستی سے ایک کھلی نشانی چھوڑ دی', NULL, NULL, 'ca23ce442e5d3bc94c663f93be31725e4457283886a204084a5c3e57746ea740'),
  ('ur.jalandhry', 29, 36, 3376, 'اور مدین کی طرف اُن کے بھائی شعیب کو (بھیجا) تو اُنہوں نے کہا (اے قوم) خدا کی عبادت کرو اور پچھلے دن کے آنے کی اُمید رکھو اور ملک میں فساد نہ مچاؤ', NULL, NULL, '53bdd10f3e156e95956d5f568e5e1dc4c54922c04e43576d3ad8033056d5bb48'),
  ('ur.jalandhry', 29, 37, 3377, 'مگر اُنہوں نے اُن کو جھوٹا سمجھا سو اُن کو زلزلے (کے عذاب) نے آپکڑا اور وہ اپنے گھروں میں اوندھے پڑے رہ گئے', NULL, NULL, 'f6a686883ae52cc77ccd47064adee69257594d21f90bc131c00e4ceb814d36f2'),
  ('ur.jalandhry', 29, 38, 3378, 'اور عاد اور ثمود کو بھی (ہم نے ہلاک کر دیا) چنانچہ اُن کے (ویران گھر) تمہاری آنکھوں کے سامنے ہیں اور شیطان نے اُن کے اعمال ان کو آراستہ کر دکھائے اور ان کو (سیدھے) رستے سے روک دیا۔ حالانکہ وہ دیکھنے والے (لوگ) تھے', NULL, NULL, '9741080fdc772ff20ada383c0eef5d790cbb34a2b397b6b53d8837bcc7587d80'),
  ('ur.jalandhry', 29, 39, 3379, 'اور قارون اور فرعون اور ہامان کو بھی (ہلاک کر دیا) اور اُن کے پاس موسٰی کھلی نشانی لےکر آئے تو وہ ملک میں مغرور ہوگئے اور ہمارے قابو سے نکل جانے والے نہ تھے', NULL, NULL, '680a17f5e5c15814c267e9ff833dce582f869711afd3f026cd5d2fd8dbc91775'),
  ('ur.jalandhry', 29, 40, 3380, 'تو ہم نے سب کو اُن کے گناہوں کے سبب پکڑ لیا۔ سو ان میں کچھ تو ایسے تھے جن پر ہم نے پتھروں کا مینھہ برسایا۔ اور کچھ ایسے تھے جن کو چنگھاڑ نے آپکڑا اور کچھ ایسے تھے جن کو ہم نے زمین میں دھنسا دیا۔ اور کچھ ایسے تھے جن کو غرق کر دیا اور خدا ایسا نہ تھا کہ اُن پر ظلم کرتا لیکن وہی اپنے آپ پر ظلم کرتے تھے', NULL, NULL, 'bad349c8aa3c05c08bbbdf0c0b685088e32fd9e3125b4e275b027d61d0d1050e'),
  ('ur.jalandhry', 29, 41, 3381, 'جن لوگوں نے خدا کے سوا (اوروں کو) کارساز بنا رکھا ہے اُن کی مثال مکڑی کی سی ہے کہ وہ بھی ایک (طرح کا) گھر بناتی ہے۔ اور کچھ شک نہیں کہ تمام گھروں سے کمزور مکڑی کا گھر ہے کاش یہ (اس بات کو) جانتے', NULL, NULL, '03ed781e1873d4480a6a6a667e1c6555f15ba851afd4302b777e54fd436309a9'),
  ('ur.jalandhry', 29, 42, 3382, 'یہ جس چیز کو خدا کے سوا پکارتے ہیں (خواہ) وہ کچھ ہی ہو خدا اُسے جانتا ہے۔ اور وہ غالب اور حکمت والا ہے', NULL, NULL, '6475968fdb25cf3b38e8b6d229bf3fb50055b3e9cd45c495eb42c0a74c6c3dfc'),
  ('ur.jalandhry', 29, 43, 3383, 'اور یہ مثالیں ہم لوگوں کے (سمجھانے کے) لئے بیان کرتے ہیں اور اُسے تو اہلِ دانش ہی سمجھتے ہیں', NULL, NULL, 'aebb5b05363ebfca2709a0f73e4c54cb139bf7be530c101a80486d82cd03826f'),
  ('ur.jalandhry', 29, 44, 3384, 'خدا نے آسمانوں اور زمین کو حکمت کے ساتھ پیدا کیا ہے۔ کچھ شک نہیں کہ ایمان والوں کے لئے اس میں نشانی ہے', NULL, NULL, '4bccea25cd0d2b4790b5495968d520ffe4069ed15f7b7898d109df46f9cc45f8'),
  ('ur.jalandhry', 29, 45, 3385, '(اے محمدﷺ! یہ) کتاب جو تمہاری طرف وحی کی گئی ہے اس کو پڑھا کرو اور نماز کے پابند رہو۔ کچھ شک نہیں کہ نماز بےحیائی اور بری باتوں سے روکتی ہے۔ اور خدا کا ذکر بڑا (اچھا کام) ہے۔ اور جو کچھ تم کرتے ہو خدا اُسے جانتا ہے', NULL, NULL, '42d02efae92cba588f2956f5bfa37228293650b87a4c454bb7dc69ae9d993de1'),
  ('ur.jalandhry', 29, 46, 3386, 'اور اہلِ کتاب سے جھگڑا نہ کرو مگر ایسے طریق سے کہ نہایت اچھا ہو۔ ہاں جو اُن میں سے بےانصافی کریں (اُن کے ساتھ اسی طرح مجادلہ کرو) اور کہہ دو کہ جو (کتاب) ہم پر اُتری اور جو (کتابیں) تم پر اُتریں ہم سب پر ایمان رکھتے ہیں اور ہمارا اور تمہارا معبود ایک ہی ہے اور ہم اُسی کے فرمانبردار ہیں', NULL, NULL, '6a1bf97dea6cd58f8e062d54056c003e159ff0cd6ce6ee990269668d6b64d07a'),
  ('ur.jalandhry', 29, 47, 3387, 'اور اسی طرح ہم نے تمہاری طرف کتاب اُتاری ہے۔ تو جن لوگوں کو ہم نے کتابیں دی تھیں وہ اس پر ایمان لے آتے ہیں۔ اور بعض ان (مشرک) لوگوں میں سے بھی اس پر ایمان لے آتے ہیں۔ اور ہماری آیتوں سے وہی انکار کرتے ہیں جو کافر (ازلی) ہیں', NULL, NULL, '93e65e9436fdc5ea5757809619b89c8671259b541a3ecc8f1ccd45faac76579b'),
  ('ur.jalandhry', 29, 48, 3388, 'اور تم اس سے پہلے کوئی کتاب نہیں پڑھتے تھے اور نہ اُسے اپنے ہاتھ سے لکھ ہی سکتے تھے ایسا ہوتا تو اہلِ باطل ضرور شک کرتے', NULL, NULL, '03eddc397b693a731cc08d6b9218dd6a07c6941694ea0cbf0c4f83eda6549487'),
  ('ur.jalandhry', 29, 49, 3389, 'بلکہ یہ روشن آیتیں ہیں۔ جن لوگوں کو علم دیا گیا ہے اُن کے سینوں میں (محفوظ) اور ہماری آیتوں سے وہی لوگ انکار کرتے ہیں جو بےانصاف ہیں', NULL, NULL, '09b2c4837872c9a529b1264654df70bde2e132fdeccba7b4e75f860902de4864'),
  ('ur.jalandhry', 29, 50, 3390, 'اور (کافر) کہتے ہیں کہ اس پر اس کے پروردگار کی طرف سے نشانیاں کیوں نازل نہیں ہوئیں کہہ دو کہ نشانیاں تو خدا ہی کے پاس ہیں۔ اور میں تو کھلم کھلا ہدایت کرنے والا ہوں', NULL, NULL, 'd5a42a57110d9df55cb4ea22d5b6a0a2bd4bdf88e5286f56f3d1a7c88280cdf4'),
  ('ur.jalandhry', 29, 51, 3391, 'کیا اُن لوگوں کے لئے یہ کافی نہیں کہ ہم نے تم پر کتاب نازل کی جو اُن کو پڑھ کر سنائی جاتی ہے۔ کچھ شک نہیں کہ مومن لوگوں کے لیے اس میں رحمت اور نصیحت ہے', NULL, NULL, '4bf803d55ad6fbe3ce12143473b43c2f7e853d19113bef17e739bdc2e20497a1'),
  ('ur.jalandhry', 29, 52, 3392, 'کہہ دو کہ میرے اور تمہارے درمیان خدا ہی گواہ کافی ہے جو چیز آسمانوں میں اور زمین میں ہے وہ سب کو جانتا ہے۔ اور جن لوگوں نے باطل کو مانا اور خدا سے انکار کیا وہی نقصان اُٹھانے والے ہیں', NULL, NULL, '6e8af8b78ef33a9328dd717971f19ee22525a374201eb2acec0e8f06fa5305d4'),
  ('ur.jalandhry', 29, 53, 3393, 'اور یہ لوگ تم سے عذاب کے لئے جلدی کر رہے ہیں۔ اگر ایک وقت مقرر نہ (ہو چکا) ہوتا تو اُن پر عذاب آبھی گیا ہوتا۔ اور وہ (کسی وقت میں) اُن پر ضرور ناگہاں آکر رہے گا اور اُن کو معلوم بھی نہ ہوگا', NULL, NULL, '5e19548cb6471e5b4c29a1f94fd5cdf2da29a6cabec512f0a78d0f5afb40df24'),
  ('ur.jalandhry', 29, 54, 3394, 'یہ تم سے عذاب کے لئے جلدی کررہے ہیں۔ اور دوزخ تو کافروں کو گھیر لینے والی ہے', NULL, NULL, '9f8c7fc04a5c047a4d7efba7f423d112a0344205886c228efeea9efc3f9ae8d5'),
  ('ur.jalandhry', 29, 55, 3395, 'جس دن عذاب اُن کو اُن کے اُوپر سے اور نیچے سے ڈھانک لے گا اور (خدا) فرمائے گا کہ جو کام تم کیا کرتے تھے (اب) اُن کا مزہ چکھو', NULL, NULL, '59955a134b4f48901a2ed3a38a393162a858811df559c1e2e9558ba600c0675c'),
  ('ur.jalandhry', 29, 56, 3396, 'اے میرے بندو جو ایمان لائے ہو میری زمین فراخ ہے تو میری ہی عبادت کرو', NULL, NULL, 'c9440f3f0735345b854dc50a8810da942fef1726fe48896eac54eeb6bd15ea8e'),
  ('ur.jalandhry', 29, 57, 3397, 'ہر متنفس موت کا مزہ چکھنے والا ہے۔ پھر تم ہماری ہی طرف لوٹ کر آؤ گے', NULL, NULL, '6db8f600dad2e730c3ac6ba4563472cf0acbba1b6d83b75c85067f0607fd9e68'),
  ('ur.jalandhry', 29, 58, 3398, 'اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے اُن کو ہم بہشت کے اُونچے اُونچے محلوں میں جگہ دیں گے۔ جن کے نیچے نہریں بہ رہی ہیں۔ ہمیشہ ان میں رہیں گے۔ (نیک) عمل کرنے والوں کا (یہ) خوب بدلہ ہے', NULL, NULL, 'c6b9d30a72cce9f113b81dda876a8da20ebb8472dd7cb0e52d0fe1144bd19e29'),
  ('ur.jalandhry', 29, 59, 3399, 'جو صبر کرتے اور اپنے پروردگار پر بھروسہ رکھتے ہیں', NULL, NULL, '07846acbb2002b4bae40597bb5b9cb9d12627bb17e65f48329314ede8fa75c23'),
  ('ur.jalandhry', 29, 60, 3400, 'اور بہت سے جانور ہیں جو اپنا رزق اُٹھائے نہیں پھرتے خدا ہی ان کو رزق دیتا ہے اور تم کو بھی۔ اور وہ سننے والا اور جاننے والا ہے', NULL, NULL, 'bc6e6fd96e7fbee73ec2bcc6b435043c8390415a8bf18243422a8c74cd399d48')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 29, 61, 3401, 'اور اگر اُن سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا۔ اور سورج اور چاند کو کس نے (تمہارے) زیر فرمان کیا تو کہہ دیں گے خدا نے۔ تو پھر یہ کہاں اُلٹے جا رہے ہیں', NULL, NULL, '3261a0e1e92cef07651fc9c18f1028cfd54cc4ba59331f5e98746970cc48f3f5'),
  ('ur.jalandhry', 29, 62, 3402, 'خدا ہی اپنے بندوں میں سے جس کے لئے چاہتا ہے روزی فراخ کر دیتا ہے اور جس کے لئے چاہتا ہے تنگ کر دیتا ہے بیشک خدا ہر چیز سے واقف ہے', NULL, NULL, '2ff5c7b42a5b8ecd4e9d75e853c97577d029cbe8883efc1fbea8f5df5aad9b66'),
  ('ur.jalandhry', 29, 63, 3403, 'اور اگر تم ان سے پوچھو کہ آسمان سے پانی کس نے نازل فرمایا پھر اس سے زمین کو اس کے مرنے کے بعد (کس نے) زندہ کیا تو کہہ دیں گے کہ خدا نے۔ کہہ دو کہ خدا کا شکر ہے۔ لیکن ان میں اکثر نہیں سمجھتے', NULL, NULL, '92cdfb627348d7167eb5dbe33fde5532ac688c0f47adf410e9215afb2f6a39b5'),
  ('ur.jalandhry', 29, 64, 3404, 'اور یہ دنیا کی زندگی تو صرف کھیل اور تماشہ ہے اور (ہمیشہ کی) زندگی (کا مقام) تو آخرت کا گھر ہے۔ کاش یہ (لوگ) سمجھتے', NULL, NULL, '7dc2953cf1144f34ff254dd10240a043194e0b6d6030e44e26ac107f6bb16276'),
  ('ur.jalandhry', 29, 65, 3405, 'پھر جب یہ کشتی میں سوار ہوتے ہیں تو خدا کو پکارتے (اور) خالص اُسی کی عبادت کرتے ہیں۔ لیکن جب وہ اُن کو نجات دے کر خشکی پر پہنچا دیتا ہے تو جھٹ شرک کرنے لگے جاتے ہیں', NULL, NULL, '49611c0b22de20c923dec66ace7837225272da9e6f69d1aabbd95634d7fcc027'),
  ('ur.jalandhry', 29, 66, 3406, 'تاکہ جو ہم نے اُن کو بخشا ہے اُس کی ناشکری کریں اور فائدہ اٹھائیں (سو خیر) عنقریب اُن کو معلوم ہوجائے گا', NULL, NULL, '653eb9d36ceab36ad2dc38d52a46865ad31bb05cd502ed58b5ef7f522369ee0c'),
  ('ur.jalandhry', 29, 67, 3407, 'کیا اُنہوں نے نہیں دیکھا کہ ہم نے حرم کو مقام امن بنایا ہے اور لوگ اس کے گرد ونواح سے اُچک لئے جاتے ہیں۔ کیا یہ لوگ باطل پر اعتقاد رکھتے ہیں اور خدا کی نعمتوں کی ناشکری کرتے ہیں', NULL, NULL, 'fd7792a2a9ad55e5729afe909d0e7b4ba38d7702f419403695ce889828861851'),
  ('ur.jalandhry', 29, 68, 3408, 'اور اس سے ظالم کون جو خدا پر جھوٹ بہتان باندھے یا جب حق بات اُس کے پاس آئے تو اس کی تکذیب کرے۔ کیا کافروں کا ٹھکانا جہنم میں نہیں ہے؟', NULL, NULL, 'dd9c2dede803e7f7edad806abe0e0c99ec29848569574cbbed8abf0c579aec08'),
  ('ur.jalandhry', 29, 69, 3409, 'اور جن لوگوں نے ہمارے لئے کوشش کی ہم اُن کو ضرور اپنے رستے دکھا دیں گے۔ اور خدا تو نیکو کاروں کے ساتھ ہے', NULL, NULL, 'ee14e8eaaa60a618b53b932f02944a89a068063b7b9757d7b839b3632cde646c'),
  ('ur.jalandhry', 30, 1, 3410, 'الٓمٓ', NULL, NULL, '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3'),
  ('ur.jalandhry', 30, 2, 3411, '(اہلِ) روم مغلوب ہوگئے', NULL, NULL, '89b33b42fdde596f3734538174a5acabcf91db7cc214d0d1e9a61ab67c2b5a2c'),
  ('ur.jalandhry', 30, 3, 3412, 'نزدیک کے ملک میں اور وہ مغلوب ہونے کے بعد عنقریب غالب آجائیں گے', NULL, NULL, '7ffe77af10c328ae7c7d9d4c2282a68e878727b6c449bb2be4d02919c1444d4e'),
  ('ur.jalandhry', 30, 4, 3413, 'چند ہی سال میں پہلے بھی اور پیچھے بھی خدا ہی کا حکم ہے اور اُس روز مومن خوش ہوجائیں گے', NULL, NULL, 'fc869a64dc91a2394b528f83f4a918e02809c68ed25697fcdbb42bfb3ddbfb3f'),
  ('ur.jalandhry', 30, 5, 3414, '(یعنی) خدا کی مدد سے۔ وہ جسے چاہتا ہے مدد دیتا ہے اور وہ غالب (اور) مہربان ہے', NULL, NULL, 'b8c8181bde065189630530bf143bd3950f9713a5203f59d888662cfa7bc21c24'),
  ('ur.jalandhry', 30, 6, 3415, '(یہ) خدا کا وعدہ (ہے) خدا اپنے وعدے کے خلاف نہیں کرتا لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '208513d468488460ffb055c0645effd0ff58614d430138779c86f8af714c3627'),
  ('ur.jalandhry', 30, 7, 3416, 'یہ تو دنیا کی ظاہری زندگی کو جانتے ہیں۔ اور آخرت (کی طرف) سے غافل ہیں', NULL, NULL, '5351ba14db079c69c1b642228f3dd4870309838dacdf2849a1f67f24cdae93c8'),
  ('ur.jalandhry', 30, 8, 3417, 'کیا اُنہوں نے اپنے دل میں غور نہیں کیا۔ کہ خدا نے آسمانوں اور زمین کو اور جو کچھ ان دونوں کے درمیان ہے اُن کو حکمت سے اور ایک وقت مقرر تک کے لئے پیدا کیا ہے۔ اور بہت سے لوگ اپنے پروردگار سے ملنے کے قائل ہی نہیں', NULL, NULL, '4705eae0822abd9f6b246d85f8415f193566a77ac79df31822698e510d4d8ad7'),
  ('ur.jalandhry', 30, 9, 3418, 'کیا اُن لوگوں نے ملک میں سیر نہیں کی (سیر کرتے) تو دیکھ لیتے کہ جو لوگ اُن سے پہلے تھے ان کا انجام کیسے ہوا۔ وہ اُن سے زورو قوت میں کہیں زیادہ تھے اور اُنہوں نے زمین کو جوتا اور اس کو اس سے زیادہ آباد کیا تھا جو اُنہوں نے آباد کیا۔ اور اُن کے پاس اُن کے پیغمبر نشانیاں لےکر آتے رہے تو خدا ایسا نہ تھا کہ اُن پر ظلم کرتا۔ بلکہ وہی اپنے آپ پر ظلم کرتے تھے', NULL, NULL, '633973bdfc35d90cf221b2931245a4b0223e42878599fabff68358d0519c630f'),
  ('ur.jalandhry', 30, 10, 3419, 'پھر جن لوگوں نے برائی کی اُن کا انجام بھی برا ہوا اس لیے کہ خدا کی آیتوں کو جھٹلاتے اور اُن کی ہنسی اُڑاتے رہے تھے', NULL, NULL, '482123c7788036463bfec3f1953b5c2e756cb18917bd51356d79e19acd29ee0d'),
  ('ur.jalandhry', 30, 11, 3420, 'خدا ہی خلقت کو پہلی بار پیدا کرتا ہے وہی اس کو پھر پیدا کرے گا پھر تم اُسی کی طرف لوٹ جاؤ گے', NULL, NULL, '9e57f356b71fa26f4599ef95d0766d9ce52524a673ca3d4f4c478011b626bc03'),
  ('ur.jalandhry', 30, 12, 3421, 'اور جس دن قیامت برپا ہوگی گنہگار نااُمید ہوجائیں گے', NULL, NULL, '011839d12530a32b5dea77359a237336966c1a91de0c15e06934f5c91e26aa4a'),
  ('ur.jalandhry', 30, 13, 3422, 'اور ان کے (بنائے ہوئے) شریکوں میں سے کوئی ان کا سفارشی نہ ہوگا اور وہ اپنے شریکوں سے نامعتقد ہوجائیں گے', NULL, NULL, '3598e9d207bb75c6b687acd930eeb18153e7ac8eb8946da085f7f58c2ae27717'),
  ('ur.jalandhry', 30, 14, 3423, 'اور جس دن قیامت برپا ہوگی اس روز وہ الگ الگ فرقے ہوجائیں گے', NULL, NULL, 'aa01cecbcb749844cd1cbb31a053e418bcaa9f56b3a39bbd60a85f66b2c4573c'),
  ('ur.jalandhry', 30, 15, 3424, 'تو جو لوگ ایمان لائے اور عمل نیک کرتے رہے وہ (بہشت کے) باغ میں خوش حال ہوں گے', NULL, NULL, '862e985b141784417183b3a4655c7fbfc1f0455e1c6baa33814d0db833f7a4d6'),
  ('ur.jalandhry', 30, 16, 3425, 'اور جنہوں نے کفر کیا اور ہماری آیتوں اور آخرت کے آنے کو جھٹلایا۔ وہ عذاب میں ڈالے جائیں گے', NULL, NULL, 'bd18dab66eb565d97cfc9f5c24c44b550a1f46f57246d5472315a9c982f679d6'),
  ('ur.jalandhry', 30, 17, 3426, 'تو جس وقت تم کو شام ہو اور جس وقت صبح ہو خدا کی تسبیح کرو (یعنی نماز پڑھو)', NULL, NULL, 'c2c566cecd501ca4b45adff7c556a1981a2b1935e62629835d8914b848cce847'),
  ('ur.jalandhry', 30, 18, 3427, 'اور آسمانوں اور زمین میں اُسی کی تعریف ہے۔ اور تیسرے پہر بھی اور جب دوپہر ہو (اُس وقت بھی نماز پڑھا کرو)', NULL, NULL, 'abce582aa7727913eb2f880a00ecae14f46bf1f641b24264401ff1a4ef811f53'),
  ('ur.jalandhry', 30, 19, 3428, 'وہی زندے کو مردے سے نکالتا اور (وہی) مردے کو زندے سے نکالتا ہے اور (وہی) زمین کو اس کے مرنے کے بعد زندہ کرتا ہے۔ اور اسی طرح تم (دوبارہ زمین میں سے) نکالے جاؤ گے', NULL, NULL, '3953d172112ce853b5514dce1e2100651e9c811cf9bdcedb92efcd9cd360d493'),
  ('ur.jalandhry', 30, 20, 3429, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے کہ اُس نے تمہیں مٹی سے پیدا کیا۔ پھر اب تم انسان ہوکر جا بجا پھیل رہے ہو', NULL, NULL, '766b64b40e45b30716194aab27cd2ebe04c1f33e0d837ec757681e241c246c5a'),
  ('ur.jalandhry', 30, 21, 3430, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے کہ اُس نے تمہارے لئے تمہاری ہی جنس کی عورتیں پیدا کیں تاکہ اُن کی طرف (مائل ہوکر) آرام حاصل کرو اور تم میں محبت اور مہربانی پیدا کر دی جو لوگ غور کرتے ہیں اُن کے لئے ان باتوں میں (بہت سی) نشانیاں ہیں', NULL, NULL, '4f1b3d00f0276549db46f9b1dd802bd7907ec0e7466e5d0e811efee92c5b2797'),
  ('ur.jalandhry', 30, 22, 3431, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے آسمانوں اور زمین کا پیدا کرنا اور تمہاری زبانوں اور رنگوں کا جدا جدا ہونا۔ اہلِ دانش کے لیے ان (باتوں) میں (بہت سی) نشانیاں ہیں', NULL, NULL, 'ede8a65f2712c4957a5c0ab9b1321d410d8c4455b6d161a0f66d5f4223eaad88'),
  ('ur.jalandhry', 30, 23, 3432, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے تمہارا رات اور دن میں سونا اور اُس کے فضل کا تلاش کرنا۔ جو لوگ سنتے ہیں اُن کے لیے ان باتوں میں (بہت سی) نشانیاں ہیں', NULL, NULL, 'fd71598afdd35e3869dcace5821d4464add2a2fae12e6ed00263f129bc145e76'),
  ('ur.jalandhry', 30, 24, 3433, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے کہ تم کو خوف اور اُمید دلانے کے لئے بجلی دکھاتا ہے اور آسمان سے مینھہ برساتا ہے۔ پھر زمین کو اس کے مر جانے کے بعد زندہ (و شاداب) کر دیتا ہے۔ عقل والوں کے لئے ان (باتوں) میں (بہت سی) نشانیاں ہیں', NULL, NULL, 'ebe9d23bb236fea95e200857dcfb68404c7b2bbe1bfdb038c3ad5456c979f601'),
  ('ur.jalandhry', 30, 25, 3434, 'اور اسی کے نشانات (اور تصرفات) میں سے ہے کہ آسمان اور زمین اس کے حکم سے قائم ہیں۔ پھر جب وہ تم کو زمین میں سے (نکلنے کے لئے) آواز دے گا تو تم جھٹ نکل پڑو گے', NULL, NULL, '603858a21e4dee8846844777b4fce720664099f03385da5426ff689c36b9bb47'),
  ('ur.jalandhry', 30, 26, 3435, 'اور آسمانوں اور زمین میں (جتنے فرشتے اور انسان وغیرہ ہیں) اسی کے (مملوک) ہیں (اور) تمام اس کے فرمانبردار ہیں', NULL, NULL, 'd70164eac972d97e15c34562eb1b62f9e9ea23c706195752deaaba34753bf2cf'),
  ('ur.jalandhry', 30, 27, 3436, 'اور وہی تو ہے جو خلقت کو پہلی دفعہ پیدا کرتا ہے پھر اُسے دوبارہ پیدا کرے گا۔ اور یہ اس کو بہت آسان ہے۔ اور آسمانوں اور زمین میں اس کی شان بہت بلند ہے۔ اور وہ غالب حکمت والا ہے', NULL, NULL, '18f2632cbca5be99843fd20e6de9c45a460297226653f960d0f34cf14a451399'),
  ('ur.jalandhry', 30, 28, 3437, 'وہ تمہارے لئے تمہارے ہی حال کی ایک مثال بیان فرماتا ہے کہ بھلا جن (لونڈی غلاموں) کے تم مالک ہو وہ اس (مال) میں جو ہم نے تم کو عطا فرمایا ہے تمہارے شریک ہیں، اور (کیا) تم اس میں (اُن کو اپنے) برابر (مالک سمجھتے) ہو (اور کیا) تم اُن سے اس طرح ڈرتے ہو جس طرح اپنوں سے ڈرتے ہو، اسی طرح عقل والوں کے لئے اپنی آیتیں کھول کھول کر بیان کرتے ہیں', NULL, NULL, '60e494cbc1dd1c9008e137e8ebc5849bfa0d505a2cb4a5f5ce4e0929a2b8eb65'),
  ('ur.jalandhry', 30, 29, 3438, 'مگر جو ظالم ہیں بےسمجھے اپنی خواہشوں کے پیچھے چلتے ہیں تو جس کو خدا گمراہ کرے اُسے کون ہدایت دے سکتا ہے؟ اور ان کا کوئی مددگار نہیں', NULL, NULL, '4e7aebe019eb486cc30776345af3ef82b1e562393051c259ac2f226a71c09703'),
  ('ur.jalandhry', 30, 30, 3439, 'تو تم ایک طرف کے ہوکر دین (خدا کے رستے) پر سیدھا منہ کئے چلے جاؤ (اور) خدا کی فطرت کو جس پر اُس نے لوگوں کو پیدا کیا ہے (اختیار کئے رہو) خدا کی بنائی ہوئی (فطرت) میں تغیر وتبدل نہیں ہو سکتا۔ یہی سیدھا دین ہے لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '529cd4b8f0b4cd61579111d6ea7b7bf1206277832687e47cd5bafab5963bfbec'),
  ('ur.jalandhry', 30, 31, 3440, '(مومنو) اُسی (خدا) کی طرف رجوع کئے رہو اور اس سے ڈرتے رہو اور نماز پڑھتے رہو اور مشرکوں میں نہ ہونا', NULL, NULL, '92697a358bc2c12417ecdacbdfd5e356399e700430758a68eb3b9fea148f6d73'),
  ('ur.jalandhry', 30, 32, 3441, '(اور نہ) اُن لوگوں میں (ہونا) جنہوں نے اپنے دین کو ٹکڑے ٹکڑے کر دیا اور (خود) فرقے فرقے ہو گئے۔ سب فرقے اسی سے خوش ہیں جو اُن کے پاس ہے', NULL, NULL, '792cb358973d6321e83702d4d664f7887cab6af40ee1201d44b8f4b66166ccaa'),
  ('ur.jalandhry', 30, 33, 3442, 'اور جب لوگوں کو تکلیف پہنچتی ہے تو اپنے پروردگار کو پکارتے اور اسی کی طرف رجوع ہوتے ہیں۔ پھر جب وہ ان کو اپنی رحمت کا مزا چکھاتا ہے تو ایک فرقہ اُن میں سے اپنے پروردگار سے شرک کرنے لگتا ہے', NULL, NULL, '7cdcebb2b9c62bf1db0a8c49a00e33e5e5dd23dcdd8cef1c10b71d500be71378'),
  ('ur.jalandhry', 30, 34, 3443, 'تاکہ جو ہم نے ان کو بخشا ہے اُس کی ناشکری کریں سو (خیر) فائدے اُٹھالو عنقریب تم کو (اس کا انجام) معلوم ہو جائے گا', NULL, NULL, '1101ce4f84aab539ca243809de301ff5dc61631c77b1c084f0788603b459bf43'),
  ('ur.jalandhry', 30, 35, 3444, 'کیا ہم نے ان پر کوئی ایسی دلیل نازل کی ہے کہ اُن کو خدا کے ساتھ شرک کرنا بتاتی ہے', NULL, NULL, 'ec9560a2024a021fb7acb05f57166b2ce21cb24e2b0261e69678b2650f23be5e'),
  ('ur.jalandhry', 30, 36, 3445, 'اور جب ہم لوگوں کو اپنی رحمت کا مزا چکھاتے ہیں تو اُس سے خوش ہو جاتے ہیں اور اگر اُن کے عملوں کے سبب جو اُن کے ہاتھوں نے آگے بھیجے ہیں کوئی گزند پہنچے تو نااُمید ہو کر رہ جاتے ہیں', NULL, NULL, '2b75346a0b90c4574ed8e8928db520062aaed56884ccf141118f2f07cd8defef'),
  ('ur.jalandhry', 30, 37, 3446, 'کیا اُنہوں نے نہیں دیکھا کہ خدا ہی جس کے لئے چاہتا ہے رزق فراخ کرتا ہے اور (جس کے لئے چاہتا ہے) تنگ کرتا ہے۔ بیشک اس میں ایمان لانے والوں کے لئے نشانیاں ہیں', NULL, NULL, '21eb3efca0fc0d1a2b7f0c7d4f5c81f3568cb3b659a8f0b09b8a1503ef3f0581'),
  ('ur.jalandhry', 30, 38, 3447, 'تو اہلِ قرابت اور محتاجوں اور مسافروں کو ان کا حق دیتے رہو۔ جو لوگ رضائے خدا کے طالب ہیں یہ اُن کے حق میں بہتر ہے۔ اور یہی لوگ نجات حاصل کرنے والے ہیں', NULL, NULL, '56a336deab016bfcbdb37c8d11b0a051452e88ddb52b9ff04e432ba4ebaddbdb'),
  ('ur.jalandhry', 30, 39, 3448, 'اور جو تم سود دیتے ہو کہ لوگوں کے مال میں افزائش ہو تو خدا کے نزدیک اس میں افزائش نہیں ہوتی اور جو تم زکوٰة دیتے ہو اور اُس سے خدا کی رضا مندی طلب کرتے ہو تو (وہ موجبِ برکت ہے اور) ایسے ہی لوگ (اپنے مال کو) دو چند سہ چند کرنے والے ہیں', NULL, NULL, '0e3cdd5743b66be7b5a1aeaac61458a0ee07739459f2287033fb0243ac476dae'),
  ('ur.jalandhry', 30, 40, 3449, 'خدا ہی تو ہے جس نے تم کو پیدا کیا پھر تم کو رزق دیا پھر تمہیں مارے گا۔ پھر زندہ کرے گا۔ بھلا تمہارے (بنائے ہوئے) شریکوں میں بھی کوئی ایسا ہے جو ان کاموں میں سے کچھ کر سکے۔ وہ پاک ہے اور (اس کی شان) ان کے شریکوں سے بلند ہے', NULL, NULL, 'cf186ac6d2140fa99191b36343361387283b695253184f083990eb0f91e98509'),
  ('ur.jalandhry', 30, 41, 3450, 'خشکی اور تری میں لوگوں کے اعمال کے سبب فساد پھیل گیا ہے تاکہ خدا اُن کو اُن کے بعض اعمال کا مزہ چکھائے عجب نہیں کہ وہ باز آجائیں', NULL, NULL, '3013b3c1957ab81210aa3e35c4327d07c1e90c2be80b601c18b05dc58262bfe8'),
  ('ur.jalandhry', 30, 42, 3451, 'کہہ دو کہ ملک میں چلو پھرو اور دیکھو کہ جو لوگ (تم سے) پہلے ہوئے ہیں ان کا کیسا انجام ہوا ہے۔ ان میں زیادہ تر مشرک ہی تھے', NULL, NULL, '9b49227a13b2d44e32b46df324c57b1640ccd61eb37b180d472243f081cc41a4'),
  ('ur.jalandhry', 30, 43, 3452, 'تو اس روز سے پہلے جو خدا کی طرف سے آکر رہے گا اور رک نہیں سکے گا دین (کے رستے) پر سیدھا منہ کئے چلے چلو اس روز (سب) لوگ منتشر ہوجائیں گے', NULL, NULL, 'cbded857c692db5268259d8ebbca1b51f4b17263156691222344a77b2c329ed4'),
  ('ur.jalandhry', 30, 44, 3453, 'جس شخص نے کفر کیا تو اس کے کفر کا ضرر اُسی کو ہے اور جس نے نیک عمل کئے تو ایسے لوگ اپنے ہی لئے آرام گاہ درست کرتے ہیں', NULL, NULL, '0009689f79102f627f10da9970d3d8af1ca3b962b1700a76cd86dc7ecd09c96b'),
  ('ur.jalandhry', 30, 45, 3454, 'جو لوگ ایمان لائے اور نیک عمل کرتے رہے اُن کو خدا اپنے فضل سے بدلہ دے گا۔ بیشک وہ کافروں کو دوست نہیں رکھتا', NULL, NULL, '79d7c5f0f48e97c0199c7272b967195a20c51190f719d6020e7f5597d1fb81f4'),
  ('ur.jalandhry', 30, 46, 3455, 'اور اُسی کی نشانیوں میں سے ہے کہ ہواؤں کو بھیجتا ہے کہ خوشخبری دیتی ہیں تاکہ تم کو اپنی رحمت کے مزے چکھائے اور تاکہ اس کے حکم سے کشتیاں چلیں اور تاکہ اس کے فضل سے (روزی) طلب کرو عجب نہیں کہ تم شکر کرو', NULL, NULL, '1ea1b918a9b889439a97309273d03a527aa906fe84227c0082c6f697ca4a7ec9'),
  ('ur.jalandhry', 30, 47, 3456, 'اور ہم نے تم سے پہلے بھی پیغمبر ان کی قوم کی طرف بھیجے تو وہ اُن کے پاس نشانیاں لےکر آئے سو جو لوگ نافرمانی کرتے تھے ہم نے اُن سے بدلہ لےکر چھوڑا اور مومنوں کی مدد ہم پر لازم تھی', NULL, NULL, 'ba83304539940a69b17cd8b548364989173fcc364db5572b1416f492e45ee065'),
  ('ur.jalandhry', 30, 48, 3457, 'خدا ہی تو ہے جو ہواؤں کو چلاتا ہے تو وہ بادل کو اُبھارتی ہیں۔ پھر خدا اس کو جس طرح چاہتا ہے آسمان میں پھیلا دیتا اور تہ بتہ کر دیتا ہے پھر تم دیکھتے ہو کہ اس کے بیچ میں سے مینھہ نکلنے لگتا ہے پھر جب وہ اپنے بندوں میں سے جن پر چاہتا ہے اُسے برسا دیتا ہے تو وہ خوش ہو جاتے ہیں', NULL, NULL, '5d9aa9549217bb67b75a2d77ad52da5af2672c11d27fb7e41308d17ad56a5c87'),
  ('ur.jalandhry', 30, 49, 3458, 'اور بیشتر تو وہ مینھہ کے اُترنے سے پہلے نااُمید ہو رہے تھے', NULL, NULL, '7f2366bab2889c577f736b3c3807aad2c94746c169e508916ecb745a9756892e'),
  ('ur.jalandhry', 30, 50, 3459, 'تو (اے دیکھنے والے) خدا کی رحمت کی نشانیوں کی طرف دیکھ کہ وہ کس طرح زمین کو اس کے مرنے کے بعد زندہ کرتا ہے۔ بیشک وہ مردوں کو زندہ کرنے والا ہے۔ اور وہ ہر چیز پر قادر ہے', NULL, NULL, '02971b7e244bde6968bce36c0289a0a1a93fc4ff5a384ca8caef024f02ed06f1'),
  ('ur.jalandhry', 30, 51, 3460, 'اور اگر ہم ایسی ہوا بھیجیں کہ وہ (اس کے سبب) کھیتی کو دیکھیں (کہ) زرد (ہو گئی ہے) تو اس کے بعد وہ ناشکری کرنے لگ جائیں', NULL, NULL, '6f53192907102c54ba5fdc3ab537efbd3ccac827c4197aecdd5f30717f72fba8'),
  ('ur.jalandhry', 30, 52, 3461, 'تو تم مردوں کی (بات) نہیں سنا سکتے اور نہ بہروں کو جب وہ پیٹھ پھیر کر پھر جائیں آواز سنا سکتے ہو', NULL, NULL, 'c3009d751ca1bd7be421d720205fc40672131c9aad1805ffb107753edfebbe73'),
  ('ur.jalandhry', 30, 53, 3462, 'اور نہ اندھوں کو اُن کی گمراہی سے (نکال کر) راہ راست پر لاسکتے ہو۔ تم تو انہی لوگوں کو سنا سکتے ہو جو ہماری آیتوں پر ایمان لاتے ہیں سو وہی فرمانبردار ہیں', NULL, NULL, '89d4949a84aed11f4955cfbe1a28decaf3b0b57279cb790b35bcfbd4b44d7177'),
  ('ur.jalandhry', 30, 54, 3463, 'خدا ہی تو ہے جس نے تم کو (ابتدا میں) کمزور حالت میں پیدا کیا پھر کمزوری کے بعد طاقت عنایت کی پھر طاقت کے بعد کمزوری اور بڑھاپا دیا۔ وہ جو چاہتا ہے پیدا کرتا ہے اور وہ صاحب دانش اور صاحب قدرت ہے', NULL, NULL, 'acd2732d5f242a5fbc4f6523c6487bf4a643202d2aec0480474090af0d77af14'),
  ('ur.jalandhry', 30, 55, 3464, 'اور جس روز قیامت برپا ہوگی گنہگار قسمیں کھائیں گے کہ وہ (دنیا میں) ایک گھڑی سے زیادہ نہیں رہے تھے۔ اسی طرح وہ (رستے سے) اُلٹے جاتے تھے', NULL, NULL, '3712dcc08e5a8cddedbd9cb2c470b4ff50d66b6a600727d8e48cef705d0ae6d7'),
  ('ur.jalandhry', 30, 56, 3465, 'اور جن لوگوں کو علم اور ایمان دیا گیا تھا وہ کہیں گے کہ خدا کی کتاب کے مطابق تم قیامت تک رہے ہو۔ اور یہ قیامت ہی کا دن ہے لیکن تم کو اس کا یقین ہی نہیں تھا', NULL, NULL, '047e9e61663afcb09f6c10c5cbc48de583a7dfae415254b21d22d86daca193a2'),
  ('ur.jalandhry', 30, 57, 3466, 'تو اس روز ظالم لوگوں کو ان کا عذر کچھ فائدہ نہ دے گا اور نہ اُن سے توبہ قبول کی جائے گی', NULL, NULL, '7cd41b651225740100e676926dbcf6b9dbf2a31e93dbf4efaa17124aabb34c39'),
  ('ur.jalandhry', 30, 58, 3467, 'اور ہم نے لوگوں کے (سمجھانے کے) لئے اس قرآن میں ہر طرح کی مثال بیان کر دی ہے اور اگر تم اُن کے سامنے کوئی نشانی پیش کرو تو یہ کافر کہہ دیں گے کہ تم تو جھوٹے ہو', NULL, NULL, '1aa6dca34111e775d48e0bc1f240647cbc8fcd350dcbd1aef9533d52abefb6b8'),
  ('ur.jalandhry', 30, 59, 3468, 'اسی طرح خدا اُن لوگوں کے دلوں پر جو سمجھ نہیں رکھتے مہر لگا دیتا ہے', NULL, NULL, 'b7970f5aaded83608a2d161ce2325d2408647f631fb22913488d08dd7e3676d6'),
  ('ur.jalandhry', 30, 60, 3469, 'پس تم صبر کرو بیشک خدا کا وعدہ سچا ہے اور (دیکھو) جو لوگ یقین نہیں رکھتے وہ تمہیں اوچھا نہ بنادیں', NULL, NULL, 'adccc284ac030903e2d831f20b14e93b273b5606ca37494a99a29f98670cae0a'),
  ('ur.jalandhry', 31, 1, 3470, 'الٓمٓ', NULL, NULL, '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3'),
  ('ur.jalandhry', 31, 2, 3471, 'یہ حکمت کی (بھری ہوئی) کتاب کی آیتیں ہیں', NULL, NULL, 'a36664779a94c1b5a426e81c1b989fec7862a23c75a33f103c242277738d6a71'),
  ('ur.jalandhry', 31, 3, 3472, 'نیکوکاروں کے لئے ہدایت اور رحمت ہے', NULL, NULL, 'de34b723d7ee807237968e9be24c144142594c520f76f16b70f299d8f09ad512'),
  ('ur.jalandhry', 31, 4, 3473, 'جو نماز کی پابندی کرتے اور زکوٰة دیتے اور آخرت کا یقین رکھتے ہیں', NULL, NULL, '27cb09817e6521ca1df14e3c8a6d8e5e21a63f70c80ed2c94c4c64ae511364be'),
  ('ur.jalandhry', 31, 5, 3474, 'یہی اپنے پروردگار (کی طرف) سے ہدایت پر ہیں اور یہی نجات پانے والے ہیں', NULL, NULL, '9a721fe1198cf4b8ce587364e935b93e8c83bebe7d7eba0fa2e1c09fce2610e6'),
  ('ur.jalandhry', 31, 6, 3475, 'اور لوگوں میں بعض ایسا ہے جو بیہودہ حکایتیں خریدتا ہے تاکہ (لوگوں کو) بےسمجھے خدا کے رستے سے گمراہ کرے اور اس سے استہزاء کرے یہی لوگ ہیں جن کو ذلیل کرنے والا عذاب ہوگا', NULL, NULL, '7786f6c3083e479d60195077c30f8dba855d99914eecc20bd27767801c309cd9'),
  ('ur.jalandhry', 31, 7, 3476, 'اور جب اس کو ہماری آیتیں سنائی جاتی ہیں تو اکڑ کر منہ پھیر لیتا ہے گویا اُن کو سنا ہی نہیں جیسے اُن کے کانوں میں ثقل ہے تو اس کو درد دینے والے عذاب کی خوشخبری سنادو', NULL, NULL, 'a4209293cd8feff4542883236d08e66a79bc0da49f50316a048d95abd50b41ac'),
  ('ur.jalandhry', 31, 8, 3477, 'جو لوگ ایمان لائے اور نیک کام کرتے رہے اُن کے لئے نعمت کے باغ ہیں', NULL, NULL, '9337de337d200c206889cd7bc6acef9a7b6b9ce55ed0075b325332db1efd11d1'),
  ('ur.jalandhry', 31, 9, 3478, 'ہمیشہ اُن میں رہیں گے۔ خدا کا وعدہ سچا ہے اور وہ غالب حکمت والا ہے', NULL, NULL, '13da73303a178398a51edcd34f0c2a0c18cdfce12e6d4543dcd9636a8efce1b6'),
  ('ur.jalandhry', 31, 10, 3479, 'اُسی نے آسمانوں کو ستونوں کے بغیر پیدا کیا جیسا کہ تم دیکھتے ہو اور زمین پر پہاڑ (بنا کر) رکھ دیئے تاکہ تم کو ہلا ہلا نہ دے اور اس میں ہر طرح کے جانور پھیلا دیئے۔ اور ہم ہی نے آسمانوں سے پانی نازل کیا پھر (اُس سے) اس میں ہر قسم کی نفیس چیزیں اُگائیں', NULL, NULL, '7d66e9f875a4d4b2add5102a6c328397b1ba6fedddd4044a64bbbb428bd273bd'),
  ('ur.jalandhry', 31, 11, 3480, 'یہ تو خدا کی پیدائش ہے تو مجھے دکھاؤ کہ خدا کے سوا جو لوگ ہیں اُنہوں نے کیا پیدا کیا ہے؟ حقیقت یہ ہے کہ یہ ظالم صریح گمراہی میں ہیں', NULL, NULL, '836451d72b1f5a4cc5ad4a1b62762d09e606bfc4cf6bfbb0ab5888358f632050'),
  ('ur.jalandhry', 31, 12, 3481, 'اور ہم نے لقمان کو دانائی بخشی۔ کہ خدا کا شکر کرو۔ اور جو شخص شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے۔ اور جو ناشکری کرتا ہے تو خدا بھی بےپروا اور سزاوار حمد (وثنا) ہے', NULL, NULL, '6fd063fc09e4b831ba3682664d3826ad33f342a2814c64c6d753b4f49cd2ebe1'),
  ('ur.jalandhry', 31, 13, 3482, 'اور (اُس وقت کو یاد کرو) جب لقمان نے اپنے بیٹے کو نصیحت کرتے ہوئے کہا کہ بیٹا خدا کے ساتھ شرک نہ کرنا۔ شرک تو بڑا (بھاری) ظلم ہے', NULL, NULL, '50392a580d5903ba6e63285d026e495ea48eb60cd24873ada73248bb17b62b92'),
  ('ur.jalandhry', 31, 14, 3483, 'اور ہم نے انسان کو جسے اُس کی ماں تکلیف پر تکلیف سہہ کر پیٹ میں اُٹھائے رکھتی ہے (پھر اس کو دودھ پلاتی ہے) اور (آخرکار) دو برس میں اس کا دودھ چھڑانا ہوتا ہے (اپنے نیز) اس کے ماں باپ کے بارے میں تاکید کی ہے کہ میرا بھی شکر کرتا رہ اور اپنے ماں باپ کا بھی (کہ تم کو) میری ہی طرف لوٹ کر آنا ہے', NULL, NULL, 'b7fef045dea09b2c9ee74a509eee67f694d61df97c38a765be7f2b989af6b437'),
  ('ur.jalandhry', 31, 15, 3484, 'اور اگر وہ تیرے درپے ہوں کہ تو میرے ساتھ کسی ایسی چیز کو شریک کرے جس کا تجھے کچھ بھی علم نہیں تو ان کا کہا نہ ماننا۔ ہاں دنیا (کے کاموں) میں ان کا اچھی طرح ساتھ دینا اور جو شخص میری طرف رجوع لائے اس کے رستے پر چلنا پھر تم کو میری طرف لوٹ کر آنا ہے۔ تو جو کام تم کرتے رہے میں سب سے تم کو آگاہ کروں گا', NULL, NULL, 'e4c7359b1276e0a39dac0efa639c6279795507e756633d16235411c9ee1e6b09'),
  ('ur.jalandhry', 31, 16, 3485, '(لقمان نے یہ بھی کہا کہ) بیٹا اگر کوئی عمل (بالفرض) رائی کے دانے کے برابر بھی (چھوٹا) ہو اور ہو بھی کسی پتھر کے اندر یا آسمانوں میں (مخفی ہو) یا زمین میں۔ خدا اُس کو قیامت کے دن لاموجود کرے گا۔ کچھ شک نہیں کہ خدا باریک بین (اور) خبردار ہے', NULL, NULL, '4bcc09c74240a7608e8ecd3ddb9dd20d0e1f78151a104abb61ba13d20968865e'),
  ('ur.jalandhry', 31, 17, 3486, 'بیٹا نماز کی پابندی رکھنا اور (لوگوں کو) اچھے کاموں کے کرنے کا امر اور بری باتوں سے منع کرتے رہنا اور جو مصیبت تجھ پر واقع ہو اس پر صبر کرنا۔ بیشک یہ بڑی ہمت کے کام ہیں', NULL, NULL, '1e1a22329487c5fa36c7d32f974c2a6cfcfacf6feeac74cc8da777a4922ce697'),
  ('ur.jalandhry', 31, 18, 3487, 'اور (ازراہ غرور) لوگوں سے گال نہ پھلانا اور زمین میں اکڑ کر نہ چلنا۔ کہ خدا کسی اترانے والے خود پسند کو پسند نہیں کرتا', NULL, NULL, 'b29d4e1dbc4f380b6c1f3947b82e6cfa8dd0619464e80142e84411dc522c48ec'),
  ('ur.jalandhry', 31, 19, 3488, 'اور اپنی چال میں اعتدال کئے رہنا اور (بولتے وقت) آواز نیچی رکھنا کیونکہ (اُونچی آواز گدھوں کی ہے اور کچھ شک نہیں کہ) سب آوازوں سے بُری آواز گدھوں کی ہے', NULL, NULL, 'e5a0c29fff32d0e59a56a6ca03f987b7a6d9491c72dce704604173482176b1b3'),
  ('ur.jalandhry', 31, 20, 3489, 'کیا تم نے نہیں دیکھا کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب کو خدا نے تمہارے قابو میں کر دیا ہے اور تم پر اپنی ظاہری اور باطنی نعمتیں پوری کردی ہیں۔ اور بعض لوگ ایسے ہیں کہ خدا کے بارے میں جھگڑتے ہیں نہ علم رکھتے ہیں اور نہ ہدایت اور نہ کتاب روشن', NULL, NULL, 'eb3ee62d10dc4550bfb5afaeac07e6fd31a308d282e7e7cffd560e1be819cfcc'),
  ('ur.jalandhry', 31, 21, 3490, 'اور جب اُن سے کہا جاتا ہے کہ جو (کتاب) خدا نے نازل فرمائی ہے اُس کی پیروی کرو۔ تو کہتے ہیں کہ ہم تو اسی کی پیروی کریں گے جس پر اپنے باپ دادا کو پایا۔ بھلا اگرچہ شیطان ان کو دوزخ کے عذاب کی طرف بلاتا ہو (تب بھی؟)', NULL, NULL, '6a0a3bd3cf5b11a73816e1615ac374526ecde2c97b086004c1d4bbdeb18355a7'),
  ('ur.jalandhry', 31, 22, 3491, 'اور جو شخص اپنے تئیں خدا کا فرمانبردار کردے اور نیکوکار بھی ہو تو اُس نے مضبوط دستاویز ہاتھ میں لے لی۔ اور (سب) کاموں کا انجام خدا ہی کی طرف ہے', NULL, NULL, 'dd3b9f453aeec0b98032d76024c7e9b6ec503fe6fc832cf62ff948028d82ab2c'),
  ('ur.jalandhry', 31, 23, 3492, 'اور جو کفر کرے تو اُس کا کفر تمہیں غمناک نہ کردے ان کو ہماری طرف لوٹ کر آنا ہے پھر جو کام وہ کیا کرتے تھے ہم اُن کو جتا ئیں گے۔ بیشک خدا دلوں کی باتوں سے واقف ہے', NULL, NULL, '0925b288a6eb1eee5dad993139b160413e11afad6cb8a60467e53953991837f7'),
  ('ur.jalandhry', 31, 24, 3493, 'ہم اُن کو تھوڑا سا فائدہ پہنچائیں گے پھر عذاب شدید کی طرف مجبور کر کے لیجائیں گے', NULL, NULL, '046b4a6ba9a4cb0ef30e7d707c08339a72897b09a2c7456237e00e15abe00377'),
  ('ur.jalandhry', 31, 25, 3494, 'اور اگر تم اُن سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو بول اُٹھیں گے کہ خدا نے۔ کہہ دو کہ خدا کا شکر ہے لیکن ان میں اکثر سمجھ نہیں رکھتے', NULL, NULL, 'c0db902270f7b22ee982f5f718728b2724d6f62ae693abbf91f5a61d40323752'),
  ('ur.jalandhry', 31, 26, 3495, 'جو کچھ آسمانوں اور زمین میں ہے (سب) خدا ہی کا ہے۔ بیشک خدا بےپروا اور سزا وارِ حمد (وثنا) ہے', NULL, NULL, '897fa75290405a16cff3ecc82625b0d44fb5ff21eaef8f7ae3b5ac6cbfc2c2fe'),
  ('ur.jalandhry', 31, 27, 3496, 'اور اگر یوں ہو کہ زمین میں جتنے درخت ہیں (سب کے سب) قلم ہوں اور سمندر (کا تمام پانی) سیاہی ہو (اور) اس کے بعد سات سمندر اور (سیاہی ہو جائیں) تو خدا کی باتیں (یعنی اس کی صفتیں) ختم نہ ہوں۔ بیشک خدا غالب حکمت والا ہے', NULL, NULL, '8eeb26d36bbb1f79ed926acd4f66efb2154e4d28c393458bb0c71b6f9224ba4f'),
  ('ur.jalandhry', 31, 28, 3497, '(خدا کو) تمہارا پیدا کرنا اور جِلا اُٹھانا ایک شخص (کے پیدا کرنے اور جلا اُٹھانے) کی طرح ہے۔ بیشک خدا سننے والا دیکھنے والا ہے', NULL, NULL, '8f962f73cbcbd880aec7bb189eecc20b7d307168f2ce30a325d80db7c988c0b9'),
  ('ur.jalandhry', 31, 29, 3498, 'کیا تم نے نہیں دیکھا کہ خدا ہی رات کو دن میں داخل کرتا ہے اور (وہی) دن کو رات میں داخل کرتا ہے اور اُسی نے سورج اور چاند کو (تمہارے) زیر فرمان کر رکھا ہے۔ ہر ایک ایک وقتِ مقرر تک چل رہا ہے اور یہ کہ خدا تمہارے سب اعمال سے خبردار ہے', NULL, NULL, 'c528476f08188aed0a19ad2b60f954b1894d6efd945630497ad1ad78b1307191'),
  ('ur.jalandhry', 31, 30, 3499, 'یہ اس لئے کہ خدا کی ذات برحق ہے اور جن کو یہ لوگ خدا کے سوا پکارتے ہیں وہ لغو ہیں اور یہ کہ خدا ہی عالی رتبہ اور گرامی قدر ہے', NULL, NULL, '5f7285f4f762179264ff463da2db22b6aef424e31eb08d276e47ad48b593452c'),
  ('ur.jalandhry', 31, 31, 3500, 'کیا تم نے نہیں دیکھا کہ خدا ہی کی مہربانی سے کشتیاں دریا میں چلتی ہیں۔ تاکہ وہ تم کو اپنی کچھ نشانیاں دکھائے۔ بیشک اس میں ہر صبر کرنے والے (اور) شکر کرنے والے کے لئے نشانیاں ہیں', NULL, NULL, 'eb7d302f73c6c05a3cbcd162b84bb06a1a5bbb08328724465f4829b6eee5ade1')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 31, 32, 3501, 'اور جب اُن پر (دریا کی) لہریں سائبانوں کی طرح چھا جاتی ہیں تو خدا کو پکارنے (اور) خالص اس کی عبادت کرنے لگتے ہیں پھر جب وہ اُن کو نجات دے کر خشکی پر پہنچا دیتا ہے تو بعض ہی انصاف پر قائم رہتے ہیں۔ اور ہماری نشانیوں سے وہی انکار کرتے ہیں جو عہد شکن اور ناشکرے ہیں', NULL, NULL, '9f568e9b4fdf758ea2c7fdf867f7b99727cf4757b5fcec9d3f793ae025c817f2'),
  ('ur.jalandhry', 31, 33, 3502, 'لوگو اپنے پروردگار سے ڈرو اور اُس دن کا خوف کرو کہ نہ تو باپ اپنے بیٹے کے کچھ کام آئے۔ اور نہ بیٹا باپ کے کچھ کام آسکے۔ بیشک خدا کا وعدہ سچا ہے پس دنیا کی زندگی تم کو دھوکے میں نہ ڈال دے۔ اور نہ فریب دینے والا (شیطان) تمہیں خدا کے بارے میں کسی طرح کا فریب دے', NULL, NULL, '074f3c2f4aedb933c0c75c5430cd433de9e4f83cf9c4f16639ef9cdbf0c534d3'),
  ('ur.jalandhry', 31, 34, 3503, 'خدا ہی کو قیامت کا علم ہے اور وہی مینھہ برساتا ہے۔ اور وہی (حاملہ کے) پیٹ کی چیزوں کو جانتا ہے (کہ نر ہے یا مادہ) اور کوئی شخص نہیں جانتا کہ وہ کل کیا کام کرے گا۔ اور کوئی متنفس نہیں جانتا کہ کس سرزمین میں اُسے موت آئے گی بیشک خدا ہی جاننے والا (اور) خبردار ہے', NULL, NULL, 'c469e0d95ae7fbd8db4b214db9a19905cb4582b9262d5e61d4028f848fe2d9cf'),
  ('ur.jalandhry', 32, 1, 3504, 'الٓمٓ', NULL, NULL, '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3'),
  ('ur.jalandhry', 32, 2, 3505, 'اس میں کچھ شک نہیں کہ اس کتاب کا نازل کیا جانا تمام جہان کے پروردگار کی طرف سے ہے', NULL, NULL, '9509e2c1248d05e54f3c8c83233f391e0527ae69226e9e0cb80b2d39d8dbd1a4'),
  ('ur.jalandhry', 32, 3, 3506, 'کیا یہ لوگ یہ کہتے ہیں کہ پیغمبر نے اس کو از خود بنا لیا ہے (نہیں) بلکہ وہ تمہارے پروردگار کی طرف سے برحق ہے تاکہ تم ان لوگوں کو ہدایت کرو جن کے پاس تم سے پہلے کوئی ہدایت کرنے والا نہیں آیا تاکہ یہ رستے پر چلیں', NULL, NULL, '56fa81e09754bdeb7b133c2de34d60ec3d1d37cfc8e1ca07d9c907788fd5a1e2'),
  ('ur.jalandhry', 32, 4, 3507, 'خدا ہی تو ہے جس نے آسمانوں اور زمین کو اور جو چیزیں ان دونوں میں ہیں سب کو چھ دن میں پیدا کیا پھر عرش پر جا ٹھہرا۔ اس کے سوا نہ تمہارا کوئی دوست ہے اور نہ سفارش کرنے والا۔ کیا تم نصیحت نہیں پکڑتے؟', NULL, NULL, '626714d451a6d7cf51ee35cff8b48608f009987194636241fbfba1a402d3f6f8'),
  ('ur.jalandhry', 32, 5, 3508, 'وہی آسمان سے زمین تک (کے) ہر کام کا انتظام کرتا ہے۔ پھر وہ ایک روز جس کی مقدار تمہارے شمار کے مطابق ہزار برس ہوگی۔ اس کی طرف صعود (اور رجوع) کرے گا', NULL, NULL, '7f30fa1fe4014afc4426eab22cbb04e40f7fc05991712704cbe3880feb5c98f2'),
  ('ur.jalandhry', 32, 6, 3509, 'یہی تو پوشیدہ اور ظاہر کا جاننے والا (اور) غالب اور رحم والا (خدا) ہے', NULL, NULL, 'e0dd18ca448f5ea1f23c61dddd4b98265a07cbd7ac2d45f26a19086179546ee8'),
  ('ur.jalandhry', 32, 7, 3510, 'جس نے ہر چیز کو بہت اچھی طرح بنایا (یعنی) اس کو پیدا کیا۔ اور انسان کی پیدائش کو مٹی سے شروع کیا', NULL, NULL, '3608c548d44995bd630fff6248af940e01164c321ae728edd22100821b38535d'),
  ('ur.jalandhry', 32, 8, 3511, 'پھر اس کی نسل خلاصے سے (یعنی) حقیر پانی سے پیدا کی', NULL, NULL, 'a4eaf8cd3305eef657f99bc1b5a7bb166e64c7925e41c1cde6f8a2bb777ba515'),
  ('ur.jalandhry', 32, 9, 3512, 'پھر اُس کو درست کیا پھر اس میں اپنی (طرف سے) روح پھونکی اور تمہارے کان اور آنکھیں اور دل بنائے مگر تم بہت کم شکر کرتے ہو', NULL, NULL, '07a8e57520417d7df797592e2f256d584e262eb0fb9e3cc737b0e71ebb905b7f'),
  ('ur.jalandhry', 32, 10, 3513, 'اور کہنے لگے کہ جب ہم زمین میں ملیامیٹ ہوجائیں گے تو کیا ازسرنو پیدا ہوں گے۔ حقیقت یہ ہے کہ یہ لوگ اپنے پروردگار کے سامنے جانے ہی کے قائل نہیں', NULL, NULL, '70ec385d47afc30c86155c5271a26fe1c8df1ff9f541a7d37c735ddd432ecad3'),
  ('ur.jalandhry', 32, 11, 3514, 'کہہ دو کہ موت کا فرشتہ جو تم پر مقرر کیا گیا ہے تمہاری روحیں قبض کر لیتا ہے پھر تم اپنے پروردگار کی طرف لوٹائے جاؤ گے', NULL, NULL, 'c42826eb509dcec7b2671c1c51f58d521e9f119504a0709ace541afda47d92aa'),
  ('ur.jalandhry', 32, 12, 3515, 'اور تم (تعجب کرو) جب دیکھو کہ گنہگار اپنے پروردگار کے سامنے سرجھکائے ہوں گے (اور کہیں گے کہ) اے ہمارے پروردگار ہم نے دیکھ لیا اور سن لیا تو ہم کو (دنیا میں) واپس بھیج دے کہ نیک عمل کریں بیشک ہم یقین کرنے والے ہیں', NULL, NULL, '64653cc6a986f3abeaa1430479a3173ee4e3f8c16380bb5bcb835f8147e16951'),
  ('ur.jalandhry', 32, 13, 3516, 'اور اگر ہم چاہتے تو ہر شخص کو ہدایت دے دیتے۔ لیکن میری طرف سے یہ بات قرار پاچکی ہے کہ میں دوزخ کو جنوں اور انسانوں سب سے بھردوں گا', NULL, NULL, '96a9a6ba5cddc25e1da6c9fca6adb4250051c046179ded12d6733a64045b2f34'),
  ('ur.jalandhry', 32, 14, 3517, 'سو (اب آگ کے) مزے چکھو اس لئے کہ تم نے اُس دن کے آنے کو بھلا رکھا تھا (آج) ہم بھی تمہیں بھلا دیں گے اور جو کام تم کرتے تھے اُن کی سزا میں ہمیشہ کے عذاب کے مزے چکھتے رہو', NULL, NULL, '11e970ac1904ec8d767d0710660a01b5fdf49b1690aea86d9d766c3084841a56'),
  ('ur.jalandhry', 32, 15, 3518, 'ہماری آیتوں پر تو وہی لوگ ایمان لاتے ہیں کہ جب اُن کو اُن سے نصیحت کی جاتی ہے تو سجدے میں گرپڑتے اور اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے ہیں اور غرور نہیں کرتے', NULL, NULL, '45a885b42d59a73f5e7b96e953fb7a7284b7e768b6315745efd79128750d2ff7'),
  ('ur.jalandhry', 32, 16, 3519, 'اُن کے پہلو بچھونوں سے الگ رہتے ہیں (اور) وہ اپنے پروردگار کو خوف اور اُمید سے پکارتے اور جو (مال) ہم نے اُن کو دیا ہے اس میں سے خرچ کرتے ہیں', NULL, NULL, 'f91abf3dbc45a8ffb75857197d5b624d32ccbfec832addf279dde20776061d32'),
  ('ur.jalandhry', 32, 17, 3520, 'کوئی متنفس نہیں جانتا کہ اُن کے لئے کیسی آنکھوں کی ٹھنڈک چھپا کر رکھی گئی ہے۔ یہ ان اعمال کا صلہ ہے جو وہ کرتے تھے', NULL, NULL, '481c4d09a69268362d7e7bb6d07b95f79c355ada500bdcfc318009ba434ee147'),
  ('ur.jalandhry', 32, 18, 3521, 'بھلا جو مومن ہو وہ اس شخص کی طرح ہوسکتا ہے جو نافرمان ہو؟ دونوں برابر نہیں ہو سکتے', NULL, NULL, '5cf48e9676f9d78ca54cb61377e214040c8a2956e50f660aabe9f1e3a959ce6e'),
  ('ur.jalandhry', 32, 19, 3522, 'جو لوگ ایمان لائے اور نیک عمل کرتے رہے اُن کے (رہنے کے) لئے باغ ہیں یہ مہمانی اُن کاموں کی جزا ہے جو وہ کرتے تھے', NULL, NULL, '1721588bfc39490bd193bd1174819b5feb63e9ac796c012194de4bb87a5b9412'),
  ('ur.jalandhry', 32, 20, 3523, 'اور جنہوں نے نافرمانی کی اُن کے رہنے کے لئے دوزخ ہے جب چاہیں گے کہ اس میں سے نکل جائیں تو اس میں لوٹا دیئے جائیں گے۔ اور اُن سے کہا جائے گا کہ جس دوزخ کے عذاب کو تم جھوٹ سمجھتے تھے اس کے مزے چکھو', NULL, NULL, '5adaf5725b3c23e09c09f71400847bf3bfb9a970c00e7be86fb13132b2bdcb15'),
  ('ur.jalandhry', 32, 21, 3524, 'اور ہم اُن کو (قیامت کے) بڑے عذاب کے سوا عذاب دنیا کا بھی مزہ چکھائیں گے۔ شاید (ہماری طرف) لوٹ آئیں', NULL, NULL, '3c0eab226d57c9b26126031ed2fd3a54f9b1ca4992e5f1a6ad7ceb59f7655d82'),
  ('ur.jalandhry', 32, 22, 3525, 'اور اس شخص سے بڑھ کر ظالم کون جس کو اس کے پروردگار کی آیتوں سے نصیحت کی جائے تو وہ اُن سے منہ پھیر لے۔ ہم گنہگاروں سے ضرور بدلہ لینے والے ہیں', NULL, NULL, '9e13322fbd149ead77cb441bd9bc886d505c219b346dde287cbfa7f4b6bbfa74'),
  ('ur.jalandhry', 32, 23, 3526, 'اور ہم نے موسٰی کو کتاب دی تو تم اُن کے ملنے سے شک میں نہ ہونا اور ہم نے اس (کتاب) کو (یا موسٰی کو) بنی اسرائیل کے لئے (ذریعہ) ہدایت بنایا', NULL, NULL, '92e5d43ff51a5dc5cb67f47816109496cbf51e4bf79220c2f30034bf149da0b6'),
  ('ur.jalandhry', 32, 24, 3527, 'اور ان میں سے ہم نے پیشوا بنائے تھے جو ہمارے حکم سے ہدایت کیا کرتے تھے۔ جب وہ صبر کرتے تھے اور وہ ہماری آیتوں پر یقین رکھتے تھے', NULL, NULL, '54fbf42eb0a86855c521823a36738bfd5c50c80c6b4735cccdc07e476ab88856'),
  ('ur.jalandhry', 32, 25, 3528, 'بلاشبہ تمہارا پروردگار ان میں جن باتوں میں وہ اختلاف کرتے تھے۔ قیامت کے روز فیصلہ کر دے گا', NULL, NULL, '056f0aef0043b44e6f78c92637dbbba78ba1bd471f248687d508136eff4a3bcb'),
  ('ur.jalandhry', 32, 26, 3529, 'کیا اُن کو اس (امر) سے ہدایت نہ ہوئی کہ ہم نے اُن سے پہلے بہت سی اُمتوں کو جن کے مقامات سکونت میں یہ چلتے پھرتے ہیں ہلاک کر دیا۔ بیشک اس میں نشانیاں ہیں۔ تو یہ سنتے کیوں نہیں', NULL, NULL, '088b82234d7ba8fb717fa2fb761ad778186c5979b4fc5c16c8df618d0ee43655'),
  ('ur.jalandhry', 32, 27, 3530, 'کیا اُنہوں نے نہیں دیکھا کہ ہم بنجر زمین کی طرف پانی رواں کرتے ہیں پھر اس سے کھیتی پیدا کرتے ہیں جس میں سے ان کے چوپائے بھی کھاتے ہیں اور وہ خود بھی (کھاتے ہیں) تو یہ دیکھتے کیوں نہیں۔', NULL, NULL, 'e6be62436675608418b50386ecfbd92cd7db53e91e1f162444fb504218adc157'),
  ('ur.jalandhry', 32, 28, 3531, 'اور کہتے ہیں اگر تم سچے ہو تو یہ فیصلہ کب ہوگا؟', NULL, NULL, '8ff472ff97c0f7a2eee0d93724417483d271bd9c1f17522d8bf927567ea5f9fd'),
  ('ur.jalandhry', 32, 29, 3532, 'کہہ دو کہ فیصلے کے دن کافروں کو ان کا ایمان لانا کچھ بھی فائدہ نہ دے گا اور نہ اُن کو مہلت دی جائے گی', NULL, NULL, 'c1f2dfe2ecc73f4a08eeb8afe3fa6c12d0f298c4c83eeba5f624427588b4955b'),
  ('ur.jalandhry', 32, 30, 3533, 'تو اُن سے منہ پھیر لو اور انتظار کرو یہ بھی انتظار کر رہے ہیں', NULL, NULL, '817bbf2a808a8745675248e6da5a62eff496da5adca390a99d69a631d481b9c6'),
  ('ur.jalandhry', 33, 1, 3534, 'اے پیغمبر خدا سے ڈرتے رہنا اور کافروں اور منافقوں کا کہا نہ ماننا۔ بےشک خدا جاننے والا اور حکمت والا ہے', NULL, NULL, '2d73d76e57ebc55cca172dbab492eef42834b6510ede1b1dab799b1594ee2d7f'),
  ('ur.jalandhry', 33, 2, 3535, 'اور جو (کتاب) تم کو تمہارے پروردگار کی طرف سے وحی کی جاتی ہے اُسی کی پیروی کئے جانا۔ بےشک خدا تمہارے سب عملوں سے خبردار ہے', NULL, NULL, '57c79bc9495909af12379eb03d56fc9fad07d4c713836c73360fbfebda97ad9b'),
  ('ur.jalandhry', 33, 3, 3536, 'اور خدا پر بھروسہ رکھنا۔ اور خدا ہی کارساز کافی ہے', NULL, NULL, '3291180485a55ad19499944b49370cdef2b0bb06913c04a00fd2e51c8e6d434c'),
  ('ur.jalandhry', 33, 4, 3537, 'خدا نے کسی آدمی کے پہلو میں دو دل نہیں بنائے۔ اور نہ تمہاری عورتوں کو جن کو تم ماں کہہ بیٹھتے ہو تمہاری ماں بنایا اور نہ تمہارے لے پالکوں کو تمہارے بیٹے بنایا۔ یہ سب تمہارے منہ کی باتیں ہیں۔ اور خدا تو سچی بات فرماتا ہے اور وہی سیدھا رستہ دکھاتا ہے', NULL, NULL, '096c84498afa47511ce86548e87d63806e41364ddc0cd908dba8c2fe625aa490'),
  ('ur.jalandhry', 33, 5, 3538, 'مومنو! لےپالکوں کو اُن کے (اصلی) باپوں کے نام سے پکارا کرو۔ کہ خدا کے نزدیک یہی بات درست ہے۔ اگر تم کو اُن کے باپوں کے نام معلوم نہ ہوں تو دین میں وہ تمہارے بھائی اور دوست ہیں اور جو بات تم سے غلطی سے ہوگئی ہو اس میں تم پر کچھ گناہ نہیں۔ لیکن جو قصد دلی سے کرو (اس پر مواخذہ ہے) اور خدا بخشنے والا مہربان ہے', NULL, NULL, '6fdd4d6e077f3bdfaf113c2ff5cbe839f245de286da14740317ad4fb00abf530'),
  ('ur.jalandhry', 33, 6, 3539, 'پیغمبر مومنوں پر اُن کی جانوں سے بھی زیادہ حق رکھتے ہیں اور پیغمبر کی بیویاں اُن کی مائیں ہیں۔ اور رشتہ دار آپس میں کتاب الله کے رُو سے مسلمانوں اور مہاجروں سے ایک دوسرے (کے ترکے) کے زیادہ حقدار ہیں۔ مگر یہ کہ تم اپنے دوستوں سے احسان کرنا چاہو۔ (تو اور بات ہے) ۔ یہ حکم کتاب یعنی (قرآن) میں لکھ دیا گیا ہے', NULL, NULL, '2b387451642f5dc9d7e8d7b5946f01851401fe9da5207373a2d419c1d5d0f0f8'),
  ('ur.jalandhry', 33, 7, 3540, 'اور جب ہم نے پیغمبروں سے عہد لیا اور تم سے نوح سے اور ابراہیم سے اور موسیٰ سے اور مریم کے بیٹے عیسیٰ سے۔ اور عہد بھی اُن سے پکّا لیا', NULL, NULL, '3cf9978e111b489e58abf120350e0c4c00537870b08891c13722014327a0bfbd'),
  ('ur.jalandhry', 33, 8, 3541, 'تاکہ سچ کہنے والوں سے اُن کی سچائی کے بارے میں دریافت کرے اور اس نے کافروں کے لئے دکھ دینے والا عذاب تیار کر رکھا ہے', NULL, NULL, 'b66bf2ca82f6f2b7eaa79d4b3a18f9817a979525b26af0f0cb9cc78040b013ac'),
  ('ur.jalandhry', 33, 9, 3542, 'مومنو خدا کی اُس مہربانی کو یاد کرو جو (اُس نے) تم پر (اُس وقت کی) جب فوجیں تم پر (حملہ کرنے کو) آئیں۔ تو ہم نے اُن پر ہوا بھیجی اور ایسے لشکر (نازل کئے) جن کو تم دیکھ نہیں سکتے تھے۔ اور جو کام تم کرتے ہو خدا اُن کو دیکھ رہا ہے', NULL, NULL, 'efd92c4d237979ae7564429dc2c2cd106b376a982df8f1b5df36eced94c92b97'),
  ('ur.jalandhry', 33, 10, 3543, 'جب وہ تمہارے اُوپر اور نیچے کی طرف سے تم پر چڑھ آئے اور جب آنکھیں پھر گئیں اور دل (مارے دہشت کے) گلوں تک پہنچ گئے اور تم خدا کی نسبت طرح طرح کے گمان کرنے لگے', NULL, NULL, 'ae6557ba1fbb89d646700e57aa30fd13fae98d990d96edeb7997d0a71ae59707'),
  ('ur.jalandhry', 33, 11, 3544, 'وہاں مومن آزمائے گئے اور سخت طور پر ہلائے گئے', NULL, NULL, '27eadfb673204e28ccc311f35ea30640fc7a4de708cbe0cd22b7f9d5a22dc4b9'),
  ('ur.jalandhry', 33, 12, 3545, 'اور جب منافق اور وہ لوگ جن کے دلوں میں بیماری ہے کہنے لگے کہ خدا اور اس کے رسول نے ہم سے محض دھوکے کا وعدہ کیا تھا', NULL, NULL, 'd3da7c2f3311da53f89f628e36241243eafd700d84e556aaef6526fff69ce127'),
  ('ur.jalandhry', 33, 13, 3546, 'اور جب اُن میں سے ایک جماعت کہتی تھی کہ اے اہل مدینہ (یہاں) تمہارے ٹھہرنے کا مقام نہیں تو لوٹ چلو۔ اور ایک گروہ ان میں سے پیغمبر سے اجازت مانگنے اور کہنے لگا کہ ہمارے گھر کھلے پڑے ہیں حالانکہ وہ کھلے نہیں تھے۔ وہ تو صرف بھاگنا چاہتے تھے', NULL, NULL, '316679c9ba2799fc09ecfe5063e08c21ceb54a740e4aec8d335c055698856fa4'),
  ('ur.jalandhry', 33, 14, 3547, 'اور اگر (فوجیں) اطراف مدینہ سے ان پر آ داخل ہوں پھر اُن سے خانہ جنگی کے لئے کہا جائے تو (فوراً) کرنے لگیں اور اس کے لئے بہت ہی کم توقف کریں', NULL, NULL, '8e7b164a9cd8a345dd73fcfdcf599a65add542dbab9b54d5119c2403c626ce97'),
  ('ur.jalandhry', 33, 15, 3548, 'حالانکہ پہلے خدا سے اقرار کر چکے تھے کہ پیٹھ نہیں پھریں گے۔ اور خدا سے (جو) اقرار (کیا جاتا ہے اُس کی) ضرور پرسش ہوگی', NULL, NULL, '7e912a68271a4025f02642c542c754733f39a6dfbe94a0565424732743eea8f8'),
  ('ur.jalandhry', 33, 16, 3549, 'کہہ دو کہ اگر تم مرنے یا مارے سے بھاگتے ہو تو بھاگنا تم کو فائدہ نہیں دے گا اور اس وقت تم بہت ہی کم فائدہ اٹھاؤ گے', NULL, NULL, 'b5789c1d40593b183da9db9220640d0e4fc9a4ddc6f7bfe53f7d66d4e3df364f'),
  ('ur.jalandhry', 33, 17, 3550, 'کہہ دو کہ اگر خدا تمہارے ساتھ برائی کا ارادہ کرے تو کون تم کو اس سے بچا سکتا ہے یا اگر تم پر مہربانی کرنی چاہے تو (کون اس کو ہٹا سکتا ہے) اور یہ لوگ خدا کے سوا کسی کو نہ اپنا دوست پائیں گے اور نہ مددگار', NULL, NULL, '419422a4519a00da02e54148d7e8db9bb2d4535b1b97154feafe1feb6bf9dfd2'),
  ('ur.jalandhry', 33, 18, 3551, 'خدا تم میں سے ان لوگوں کو بھی جانتا ہے جو (لوگوں کو) منع کرتے ہیں اور اپنے بھائیوں سے کہتے ہیں کہ ہمارے پاس چلے آؤ۔ اور لڑائی میں نہیں آتے مگر کم', NULL, NULL, '89b7d096f7ba77f63721669e26984e4500386bd31857df1be46ce387e4f3339f'),
  ('ur.jalandhry', 33, 19, 3552, '(یہ اس لئے کہ) تمہارے بارے میں بخل کرتے ہیں۔ پھر جب ڈر (کا وقت) آئے تو تم ان کو دیکھو کہ تمہاری طرف دیکھ رہے ہیں (اور) اُن کی آنکھیں (اسی طرح) پھر رہی ہیں جیسے کسی کو موت سے غشی آرہی ہو۔ پھر جب خوف جاتا رہے تو تیز زبانوں کے ساتھ تمہارے بارے میں زبان درازی کریں اور مال میں بخل کریں۔ یہ لوگ (حقیقت میں) ایمان لائے ہی نہ تھے تو خدا نے ان کے اعمال برباد کر دیئے۔ اور یہ خدا کو آسان تھا', NULL, NULL, '753a0e8ae286b3eb3b9ad0119d83522395f031767e453ddbe70e34d2e918702a'),
  ('ur.jalandhry', 33, 20, 3553, '(خوف کے سبب) خیال کرتے ہیں کہ فوجیں نہیں گئیں۔ اور اگر لشکر آجائیں تو تمنا کریں کہ (کاش) گنواروں میں جا رہیں (اور) تمہاری خبر پوچھا کریں۔ اور اگر تمہارے درمیان ہوں تو لڑائی نہ کریں مگر کم', NULL, NULL, 'd4a925f02639e7058660f5f5e17939c1715a7ec85560ebb25a3ae8a05aee3035'),
  ('ur.jalandhry', 33, 21, 3554, 'تم کو پیغمبر خدا کی پیروی (کرنی) بہتر ہے (یعنی) اس شخص کو جسے خدا (سے ملنے) اور روز قیامت (کے آنے) کی اُمید ہو اور وہ خدا کا ذکر کثرت سے کرتا ہو', NULL, NULL, '292707fd00bd4a2d6423335c56434552c8aec4c989faefbeb2235730752ff531'),
  ('ur.jalandhry', 33, 22, 3555, 'اور جب مومنوں نے (کافروں کے) لشکر کو دیکھا تو کہنے لگے یہ وہی ہے جس کا خدا اور اس کے پیغمبر نے ہم سے وعدہ کیا تھا اور خدا اور اس کے پیغمبر نے سچ کہا تھا۔ اور اس سے ان کا ایمان اور اطاعت اور زیادہ ہوگئی', NULL, NULL, '7b85e7e170831e3f80e285212b59fbf5621adacea339cad9703704fd15011985'),
  ('ur.jalandhry', 33, 23, 3556, 'مومنوں میں کتنے ہی ایسے شخص ہیں کہ جو اقرار اُنہوں نے خدا سے کیا تھا اس کو سچ کر دکھایا۔ تو ان میں بعض ایسے ہیں جو اپنی نذر سے فارغ ہوگئے اور بعض ایسے ہیں کہ انتظار کر رہے ہیں اور اُنہوں نے (اپنے قول کو) ذرا بھی نہیں بدلا', NULL, NULL, '7a14e37eb242be672c8dbbad3fe68401bc2deb6b59493bd69026152ce9dcacab'),
  ('ur.jalandhry', 33, 24, 3557, 'تاکہ خدا سچّوں کو اُن کی سچائی کا بدلہ دے اور منافقوں کو چاہے تو عذاب دے اور (چاہے) تو اُن پر مہربانی کرے۔ بےشک خدا بخشنے والا مہربان ہے', NULL, NULL, 'c63cc723568472a2c4f2126fd86b5cea9192a011ee9feb66d3c9024f629895c8'),
  ('ur.jalandhry', 33, 25, 3558, 'اور جو کافر تھے اُن کو خدا نے پھیر دیا وہ اپنے غصے میں (بھرے ہوئے تھے) کچھ بھلائی حاصل نہ کر سکے۔ اور خدا مومنوں کو لڑائی کے بارے میں کافی ہوا۔ اور خدا طاقتور (اور) زبردست ہے', NULL, NULL, 'cb54ef1a83491c3b16e5dbecc9c75a04bd8caa3fd99a5704cd2c056d396d5b46'),
  ('ur.jalandhry', 33, 26, 3559, 'اور اہل کتاب میں سے جنہوں نے اُن کی مدد کی تھی اُن کو اُن کے قلعوں سے اُتار دیا اور اُن کے دلوں میں دہشت ڈال دی۔ تو کتنوں کو تم قتل کر دیتے تھے اور کتنوں کو قید کرلیتے تھے', NULL, NULL, 'fc3e3bb1f9973f3feb04d1090eddcdd18f724ea1c37c0f665b7e518b76a29910'),
  ('ur.jalandhry', 33, 27, 3560, 'اور اُن کی زمین اور ان کے گھروں اور ان کے مال کا اور اس زمین کا جس میں تم نے پاؤں بھی نہیں رکھا تھا تم کو وارث بنا دیا۔ اور خدا ہر چیز پر قدرت رکھتا ہے', NULL, NULL, '4ba66af187d00c370d9fb3cdb688afc4ac1a574b8965485ed2ba391ef908d3a6'),
  ('ur.jalandhry', 33, 28, 3561, 'اے پیغمبر اپنی بیویوں سے کہہ دو کہ اگر تم دنیا کی زندگی اور اس کی زینت وآرائش کی خواستگار ہو تو آؤ میں تمہیں کچھ مال دوں اور اچھی طرح سے رخصت کردوں', NULL, NULL, '5fb3559df683cc4bd3101803fe15b24fd4857bb8cd242daf2f7ab8d2fefe44b1'),
  ('ur.jalandhry', 33, 29, 3562, 'اور اگر تم خدا اور اس کے پیغمبر اور عاقبت کے گھر (یعنی بہشت) کی طلبگار ہو تو تم میں جو نیکوکاری کرنے والی ہیں اُن کے لئے خدا نے اجر عظیم تیار کر رکھا ہے', NULL, NULL, '3117f5e45df737313a25e2938107cf45d15dd3b706447d5651ffc18558528b16'),
  ('ur.jalandhry', 33, 30, 3563, 'اے پیغمبر کی بیویو تم میں سے جو کوئی صریح ناشائستہ (الفاظ کہہ کر رسول الله کو ایذا دینے کی) حرکت کرے گی۔ اس کو دونی سزا دی جائے گی۔ اور یہ (بات) خدا کو آسان ہے', NULL, NULL, '4f482b4e32879d9ad71c10229eb8a2c883d81a29a52eb68bd5518ecbb78b645a'),
  ('ur.jalandhry', 33, 31, 3564, 'اور جو تم میں سے خدا اور اس کے رسول کی فرمانبردار رہے گی اور عمل نیک کرے گی۔ اس کو ہم دونا ثواب دیں گے اور اس کے لئے ہم نے عزت کی روزی تیار کر رکھی ہے', NULL, NULL, '77bc6e4dac929beb5130ebbb280ba773196967d061f02aa83ec444748024d824'),
  ('ur.jalandhry', 33, 32, 3565, 'اے پیغمبر کی بیویو تم اور عورتوں کی طرح نہیں ہو۔ اگر تم پرہیزگار رہنا چاہتی ہو تو کسی (اجنبی شخص سے) نرم نرم باتیں نہ کیا کرو تاکہ وہ شخص جس کے دل میں کسی طرح کا مرض ہے کوئی امید (نہ) پیدا کرے۔ اور ان دستور کے مطابق بات کیا کرو', NULL, NULL, '1e76b45ce5c9cc0ca7e94f3658f652f48c5d924fede495b65591e8c1468c12b9'),
  ('ur.jalandhry', 33, 33, 3566, 'اور اپنے گھروں میں ٹھہری رہو اور جس طرح (پہلے) جاہلیت (کے دنوں) میں اظہار تجمل کرتی تھیں اس طرح زینت نہ دکھاؤ۔ اور نماز پڑھتی رہو اور زکوٰة دیتی رہو اور خدا اور اس کے رسول کی فرمانبرداری کرتی رہو۔ اے (پیغمبر کے) اہل بیت خدا چاہتا ہے کہ تم سے ناپاکی (کا میل کچیل) دور کردے اور تمہیں بالکل پاک صاف کردے', NULL, NULL, '180d3714ad3df3626cf137f8617e269a48212dfaf0f94ba6d4c46553108b572e'),
  ('ur.jalandhry', 33, 34, 3567, 'اور تمہارے گھروں میں جو خدا کی آیتیں پڑھی جاتی ہیں اور حکمت (کی باتیں سنائی جاتی ہیں) ان کو یاد رکھو۔ بےشک خدا باریک بیں اور باخبر ہے', NULL, NULL, '9baaf67df43007d1e6f83b1bd3c4b84deabaece0c2d51b0fa0be0246d74a8a1c'),
  ('ur.jalandhry', 33, 35, 3568, '(جو لوگ خدا کے آگے سر اطاعت خم کرنے والے ہیں یعنی) مسلمان مرد اور مسلمان عورتیں اور مومن مرد اور مومن عورتیں اور فرماں بردار مرد اور فرماں بردار عورتیں اور راست باز مرد اور راست باز عورتیں اور صبر کرنے والے مرد اور صبر کرنے والی عورتیں اور فروتنی کرنے والے مرد اور فروتنی کرنے والی عورتیں اور خیرات کرنے والے مرد اور اور خیرات کرنے والی عورتیں اور روزے رکھنے والے مرد اور روزے رکھنے والی عورتیں اور اپنی شرمگاہوں کی حفاظت کرنے والے مرد اور حفاظت کرنے والی عورتیں اور خدا کو کثرت سے یاد کرنے والے مرد اور کثرت سے یاد کرنے والی عورتیں۔ کچھ شک نہیں کہ ان کے لئے خدا نے بخشش اور اجر عظیم تیار کر رکھا ہے', NULL, NULL, 'dfff99c80d515f45cf67be70cead1f5717cbba274e312a7c4f407b2010a42ee7'),
  ('ur.jalandhry', 33, 36, 3569, 'اور کسی مومن مرد اور مومن عورت کو حق نہیں ہے کہ جب خدا اور اس کا رسول کوئی امر مقرر کردیں تو وہ اس کام میں اپنا بھی کچھ اختیار سمجھیں۔ اور جو کوئی خدا اور اس کے رسول کی نافرمانی کرے وہ صریح گمراہ ہوگیا', NULL, NULL, '0569fb5a002b132f909a77b04a1214ab8b94587c855bd345dadb10fcf32d4825'),
  ('ur.jalandhry', 33, 37, 3570, 'اور جب تم اس شخص سے جس پر خدا نے احسان کیا اور تم نے بھی احسان کیا (یہ) کہتے تھے کہ اپنی بیوی کو اپنے پاس رہنے دے اور خدا سے ڈر اور تم اپنے دل میں وہ بات پوشیدہ کرتے تھے جس کو خدا ظاہر کرنے والا تھا اور تم لوگوں سے ڈرتے تھے۔ حالانکہ خدا ہی اس کا زیادہ مستحق ہے کہ اس سے ڈرو۔ پھر جب زید نے اس سے (کوئی) حاجت (متعلق) نہ رکھی (یعنی اس کو طلاق دے دی) تو ہم نے تم سے اس کا نکاح کردیا تاکہ مومنوں کے لئے ان کے منہ بولے بیٹوں کی بیویوں (کے ساتھ نکاح کرنے کے بارے) میں جب وہ ان سے اپنی حاجت (متعلق) نہ رکھیں (یعنی طلاق دے دیں) کچھ تنگی نہ رہے۔ اور خدا کا حکم واقع ہو کر رہنے والا تھا', NULL, NULL, '4ba0e84a500ff69bac0a5a2a1d59351cb92d862b3063c5455c26b969ceae64db'),
  ('ur.jalandhry', 33, 38, 3571, 'پیغمبر پر اس کام میں کچھ تنگی نہیں جو خدا نے ان کے لئے مقرر کردیا۔ اور جو لوگ پہلے گزر چکے ہیں ان میں بھی خدا کا یہی دستور رہا ہے۔ اور خدا کا حکم ٹھیر چکا ہے', NULL, NULL, '4ed39664daefc8dc4e32d4ac1cef595417e50d8feae7ecaad13c2d97f5ed941f'),
  ('ur.jalandhry', 33, 39, 3572, 'اور جو خدا کے پیغام (جوں کے توں) پہنچاتے اور اس سے ڈرتے ہیں اور خدا کے سوا کسی سے نہیں ڈرتے تھے۔ اور خدا ہی حساب کرنے کو کافی ہے', NULL, NULL, '64de537897ba5c21f28e2d142aa4d1be6a0920f910339e1f77b64a8396e51f83'),
  ('ur.jalandhry', 33, 40, 3573, 'محمدﷺ تمہارے مردوں میں سے کسی کے والد نہیں ہیں بلکہ خدا کے پیغمبر اور نبیوں (کی نبوت) کی مہر (یعنی اس کو ختم کردینے والے) ہیں اور خدا ہر چیز سے واقف ہے', NULL, NULL, 'bce583c464ebbe5f9e0a8e1caeec5a5ed0b48b4476d5c5e2278f3ac37d3cc140'),
  ('ur.jalandhry', 33, 41, 3574, 'اے اہل ایمان خدا کا بہت ذکر کیا کرو', NULL, NULL, '6e46c5eaf7d1e8661a14dd85d2e2985c5f07f8b9f9116ce538bf2a7160723813'),
  ('ur.jalandhry', 33, 42, 3575, 'اور صبح اور شام اس کی پاکی بیان کرتے رہو', NULL, NULL, 'b854a3bac0b83419a90805d488d57bd2a24178735e4c500cdd2670799d9183e4'),
  ('ur.jalandhry', 33, 43, 3576, 'وہی تو ہے جو تم پر رحمت بھیجتا ہے اور اس کے فرشتے بھی۔ تاکہ تم کو اندھیروں سے نکال کر روشنی کی طرف لے جائے۔ اور خدا مومنوں پر مہربان ہے', NULL, NULL, '56bd890cc3b028750c00f5dc633418049bd061300a19054af57eebad2a08bf07'),
  ('ur.jalandhry', 33, 44, 3577, 'جس روز وہ اس سے ملیں گے ان کا تحفہ (خدا کی طرف سے) سلام ہوگا اور اس نے ان کے لئے بڑا ثواب تیار کر رکھا ہے', NULL, NULL, 'daf710bdd057f6fc751f142c24c19c71a8b6322aec7dda9f109a98e5d9cc80cb'),
  ('ur.jalandhry', 33, 45, 3578, 'اے پیغمبر ہم نے تم کو گواہی دینے والا اور خوشخبری سنانے اور ڈرانے والا بنا کر بھیجا ہے', NULL, NULL, '98b0d393c61de97691f0a95255966a97242507db1ba3a8a69b4aaaa31e279571'),
  ('ur.jalandhry', 33, 46, 3579, 'اور خدا کی طرف بلانے والا اور چراغ روشن', NULL, NULL, '4bfa990bfea2479a7b67b09797b8e7e651d63c4ce4a12abfb9db187ad9615298'),
  ('ur.jalandhry', 33, 47, 3580, 'اور مومنوں کو خوشخبری سنا دو کہ ان کے لئے خدا کی طرف سے بڑا فضل ہوگا', NULL, NULL, '5f8c4a58b8c68e1ebcbfeeedfdb386e2b5aef1122538ecbdbf34ff646e606d80'),
  ('ur.jalandhry', 33, 48, 3581, 'اور کافروں اور منافقوں کا کہا نہ ماننا اور نہ ان کے تکلیف دینے پر نظر کرنا اور خدا پر بھروسہ رکھنا۔ اور خدا ہی کارساز کافی ہے', NULL, NULL, '17f4f88d1def16352a1e8436c398ce7dfb8b4af80c731d5c90920f0b2d8a100d'),
  ('ur.jalandhry', 33, 49, 3582, 'مومنو! جب تم مومن عورتوں سے نکاح کرکے ان کو ہاتھ لگانے (یعنی ان کے پاس جانے) سے پہلے طلاق دے دو تو تم کو کچھ اختیار نہیں کہ ان سے عدت پوری کراؤ۔ ان کو کچھ فائدہ (یعنی خرچ) دے کر اچھی طرح سے رخصت کردو', NULL, NULL, '9ec242de3a51b412d014adb7438bd1665bfa94869026f5525c243c236208ca97'),
  ('ur.jalandhry', 33, 50, 3583, 'اے پیغمبر ہم نے تمہارے لئے تمہاری بیویاں جن کو تم نے ان کے مہر دے دیئے ہیں حلال کردی ہیں اور تمہاری لونڈیاں جو خدا نے تم کو (کفار سے بطور مال غنیمت) دلوائی ہیں اور تمہارے چچا کی بیٹیاں اور تمہاری پھوپھیوں کی بیٹیاں اور تمہارے ماموؤں کی بیٹیاں اور تمہاری خالاؤں کی بیٹیاں جو تمہارے ساتھ وطن چھوڑ کر آئی ہیں (سب حلال ہیں) اور کوئی مومن عورت اگر اپنے تئیں پیغمبر کو بخش دے (یعنی مہر لینے کے بغیر نکاح میں آنا چاہے) بشرطیکہ پیغمبر بھی ان سے نکاح کرنا چاہیں (وہ بھی حلال ہے لیکن) یہ اجازت (اے محمدﷺ) خاص تم ہی کو ہے سب مسلمانوں کو نہیں۔ ہم نے ان کی بیویوں اور لونڈیوں کے بارے میں جو (مہر واجب الادا) مقرر کردیا ہے ہم کو معلوم ہے (یہ) اس لئے (کیا گیا ہے) کہ تم پر کسی طرح کی تنگی نہ رہے۔ اور خدا بخشنے والا مہربان ہے', NULL, NULL, 'ee1506bd9ebda992503847e42d73d8081abdb38c59d16a4a3f1f1a30dc6a2b37'),
  ('ur.jalandhry', 33, 51, 3584, '(اور تم کو یہ بھی اختیار ہے کہ) جس بیوی کو چاہو علیحدہ رکھو اور جسے چاہو اپنے پاس رکھو۔ اور جس کو تم نے علیحدہ کردیا ہو اگر اس کو پھر اپنے پاس طلب کرلو تو تم پر کچھ گناہ نہیں۔ یہ (اجازت) اس لئے ہے کہ ان کی آنکھیں ٹھنڈی رہیں اور وہ غمناک نہ ہوں اور جو کچھ تم ان کو دو۔ اسے لے کر سب خوش رہیں۔ اور جو کچھ تمہارے دلوں میں ہے خدا اسے جانتا ہے۔ اور خدا جاننے والا اور بردبار ہے', NULL, NULL, '1da24fdbe5590f42f760b30af1e40a4e0628a75f31d2a428fd121644f93cf3b0'),
  ('ur.jalandhry', 33, 52, 3585, '(اے پیغمبر) ان کے سوا اور عورتیں تم کو جائز نہیں اور نہ یہ کہ ان بیویوں کو چھوڑ کر اور بیویاں کرو خواہ ان کا حسن تم کو (کیسا ہی) اچھا لگے مگر وہ جو تمہارے ہاتھ کا مال ہے (یعنی لونڈیوں کے بارے میں تم کو اختیار ہے) اور خدا ہر چیز پر نگاہ رکھتا ہے', NULL, NULL, '592be8577f611e10628bfcabafc995d78c5c1622abc98040258cea24f382976a'),
  ('ur.jalandhry', 33, 53, 3586, 'مومنو پیغمبر کے گھروں میں نہ جایا کرو مگر اس صورت میں کہ تم کو کھانے کے لئے اجازت دی جائے اور اس کے پکنے کا انتظار بھی نہ کرنا پڑے۔ لیکن جب تمہاری دعوت کی جائے تو جاؤ اور جب کھانا کھاچکو تو چل دو اور باتوں میں جی لگا کر نہ بیٹھ رہو۔ یہ بات پیغمبر کو ایذا دیتی ہے۔ اور وہ تم سے شرم کرتے ہیں (اور کہتے نہیں ہیں) لیکن خدا سچی بات کے کہنے سے شرم نہیں کرتا۔ اور جب پیغمبروں کی بیویوں سے کوئی سامان مانگو تو پردے کے باہر مانگو۔ یہ تمہارے اور ان کے دونوں کے دلوں کے لئے بہت پاکیزگی کی بات ہے۔ اور تم کو یہ شایاں نہیں کہ پیغمبر خدا کو تکلیف دو اور نہ یہ کہ ان کی بیویوں سے کبھی ان کے بعد نکاح کرو۔ بےشک یہ خدا کے نزدیک بڑا (گناہ کا کام) ہے', NULL, NULL, 'f9ab1dc2cbb3d2659c446b7a73eb5c67ddb106f90d83c10ee0d803e85b7f3b97'),
  ('ur.jalandhry', 33, 54, 3587, 'اگر تم کسی چیز کو ظاہر کرو یا اس کو مخفی رکھو تو (یاد رکھو کہ) خدا ہر چیز سے باخبر ہے', NULL, NULL, 'b2b43b74fb97fb2b9e748307ecd290a633cd94caaeaa241545b9ac86bdd09fe7'),
  ('ur.jalandhry', 33, 55, 3588, 'عورتوں پر اپنے باپوں سے (پردہ نہ کرنے میں) کچھ گناہ نہیں اور نہ اپنے بیٹوں سے اور نہ اپنے بھائیوں سے اور نہ اپنے بھتیجوں سے اور نہ اپنے بھانجوں سے نہ اپنی (قسم کی) عورتوں سے اور نہ لونڈیوں سے۔ اور (اے عورتو) خدا سے ڈرتی رہو۔ بےشک خدا ہر چیز سے واقف ہے', NULL, NULL, 'f7402dc534cb736be050db1ed082419a6ce35fe59ca9a76fd8ef1e930e91c9bc'),
  ('ur.jalandhry', 33, 56, 3589, 'خدا اور اس کے فرشتے پیغمبر پر درود بھیجتے ہیں۔ مومنو تم بھی ان پر دُرود اور سلام بھیجا کرو', NULL, NULL, '141ae5984d44bfde486b281c60315c808eb28a6e4f1582d946c184568c62e821'),
  ('ur.jalandhry', 33, 57, 3590, 'جو لوگ خدا اور اس کے پیغمبر کو رنج پہنچاتے ہیں ان پر خدا دنیا اور آخرت میں لعنت کرتا ہے اور ان کے لئے اس نے ذلیل کرنے والا عذاب تیار کر رکھا ہے', NULL, NULL, 'd2cb24e02e39c9ce2d16d13476794abcebb20364f752343a3f736258b80945d6'),
  ('ur.jalandhry', 33, 58, 3591, 'اور جو لوگ مومن مردوں اور مومن عورتوں کو ایسے کام (کی تہمت سے) جو انہوں نے نہ کیا ہو ایذا دیں تو انہوں نے بہتان اور صریح گناہ کا بوجھ اپنے سر پر رکھا', NULL, NULL, 'f67c933b95a3993069e0845e78632a1dc258ff95f485e0514ebb8800698ffc13'),
  ('ur.jalandhry', 33, 59, 3592, 'اے پیغمبر اپنی بیویوں اور بیٹیوں اور مسلمانوں کی عورتوں سے کہہ دو کہ (باہر نکلا کریں تو) اپنے (مونہوں) پر چادر لٹکا (کر گھونگھٹ نکال) لیا کریں۔ یہ امر ان کے لئے موجب شناخت (وامتیاز) ہوگا تو کوئی ان کو ایذا نہ دے گا۔ اور خدا بخشنے والا مہربان ہے', NULL, NULL, '144e4ad27ecb02116b1c5c71b637d9cc713253a7f47ff46ceb5994287d546e22'),
  ('ur.jalandhry', 33, 60, 3593, 'اگر منافق اور وہ لوگ جن کے دلوں میں مرض ہے اور جو مدینے (کے شہر میں) بری بری خبریں اُڑایا کرتے ہیں (اپنے کردار) سے باز نہ آئیں گے تو ہم تم کو ان کے پیچھے لگا دیں گے پھر وہاں تمہارے پڑوس میں نہ رہ سکیں گے مگر تھوڑے دن', NULL, NULL, '96eb96c2f86cb076ae77d2d3edef13edc59ea4c410164606cfe51361c3ca1eae'),
  ('ur.jalandhry', 33, 61, 3594, '(وہ بھی) پھٹکارے ہوئے۔ جہاں پائے گئے پکڑے گئے اور جان سے مار ڈالے گئے', NULL, NULL, '2d7b8112454f6dcaf86faafd65599206364c432522713ee7a3d4c34636150cfa'),
  ('ur.jalandhry', 33, 62, 3595, 'جو لوگ پہلے گزر چکے ہیں ان کے بارے میں بھی خدا کی یہی عادت رہی ہے۔ اور تم خدا کی عادت میں تغیر وتبدل نہ پاؤ گے', NULL, NULL, '54193e8a2c1dcc324e1d916d2df5a6e350a22f22dd45f8043d0712605b8f4626'),
  ('ur.jalandhry', 33, 63, 3596, 'لوگ تم سے قیامت کی نسبت دریافت کرتے ہیں (کہ کب آئے گی) کہہ دو کہ اس کا علم خدا ہی کو ہے۔ اور تمہیں کیا معلوم ہے شاید قیامت قریب ہی آگئی ہو', NULL, NULL, 'bb1bceda99bf04c0476c8889196165049e20451ddf24e07c7fbca56025a1b0d8'),
  ('ur.jalandhry', 33, 64, 3597, 'بےشک خدا نے کافروں پر لعنت کی ہے اور ان کے لئے (جہنم کی) آگ تیار کر رکھی ہے', NULL, NULL, 'd6277758092cd2bc9ccef8a2c567b0fcb2cb280460aac811ddb327e71c0734a6'),
  ('ur.jalandhry', 33, 65, 3598, 'اس میں ابدا لآباد رہیں گے۔ نہ کسی کو دوست پائیں گے اور نہ مددگار', NULL, NULL, '6fd8e4eb68004ce0ee8807927856336e868a48d316ad489498ae3de36bf1d26e'),
  ('ur.jalandhry', 33, 66, 3599, 'جس دن ان کے منہ آگ میں الٹائے جائیں گے کہیں اے کاش ہم خدا کی فرمانبرداری کرتے اور رسول (خدا) کا حکم مانتے', NULL, NULL, 'ba9f5cf7b0d9a7d070191ae5ea3138642c895d571de403ebd64ebc18f670751d'),
  ('ur.jalandhry', 33, 67, 3600, 'اور کہیں گے کہ اے ہمارے پروردگار ہم نے اپنے سرداروں اور بڑے لوگوں کا کہا مانا تو انہوں نے ہم کو رستے سے گمراہ کردیا', NULL, NULL, '770cdd96997411680455fba22a5f8b1eec5b8355521b5e51b58990fe124707e9')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 33, 68, 3601, 'اے ہمارے پروردگار ان کو دگنا عذاب دے اور ان پر بڑی لعنت کر', NULL, NULL, 'f9970809bc8b36d35efc9f016f982cdf9485f32c444e66b450220d4e04e420f8'),
  ('ur.jalandhry', 33, 69, 3602, 'مومنو تم ان لوگوں جیسے نہ ہونا جنہوں نے موسیٰ (کو عیب لگا کر) رنج پہنچایا تو خدا نے ان کو بےعیب ثابت کیا۔ اور وہ خدا کے نزدیک آبرو والے تھے', NULL, NULL, '1751af10924b4552f104e169908c9231fea4f06f4ce52a22fbb5cd1070a78f82'),
  ('ur.jalandhry', 33, 70, 3603, 'مومنو خدا سے ڈرا کرو اور بات سیدھی کہا کرو', NULL, NULL, 'a7a0acd9fd05e605bf4cb0841fdae524e39e4e50a994f3efecdd12ea24afb37d'),
  ('ur.jalandhry', 33, 71, 3604, 'وہ تمہارے اعمال درست کردے گا اور تمہارے گناہ بخش دے گا۔ اور جو شخص خدا اور اس کے رسول کی فرمانبرداری کرے گا تو بےشک بڑی مراد پائے گا', NULL, NULL, '9145204e8bbbdc1dbb7b77575feafd23a964eac419e10c866124b7cd396f9f2d'),
  ('ur.jalandhry', 33, 72, 3605, 'ہم نے (بار) امانت کو آسمانوں اور زمین پر پیش کیا تو انہوں نے اس کے اٹھانے سے انکار کیا اور اس سے ڈر گئے۔ اور انسان نے اس کو اٹھا لیا۔ بےشک وہ ظالم اور جاہل تھا', NULL, NULL, '444421b917c0c228f22ffa5a7abb1fd86ab6fecd0459d6539fa0ca2fb369df96'),
  ('ur.jalandhry', 33, 73, 3606, 'تاکہ خدا منافق مردوں اور منافق عورتوں اور مشرک مردوں اور مشرک عورتوں کو عذاب دے اور خدا مومن مردوں اور مومن عورتوں پر مہربانی کرے۔ اور خدا تو بخشنے والا مہربان ہے', NULL, NULL, '03b2b3ec1dba6ed3681273fdc6d7f9c58e72dd9b720bd0200948e3fc82b495cc'),
  ('ur.jalandhry', 34, 1, 3607, 'سب تعریف خدا ہی کو (سزاوار) ہے (جو سب چیزوں کا مالک ہے یعنی) وہ کہ جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب اسی کا ہے اور آخرت میں بھی اسی کی تعریف ہے۔ اور وہ حکمت والا خبردار ہے', NULL, NULL, '030465e93de322a20c8f5a4cd972329e0ae3eaff6de588f0cf8959de871d0894'),
  ('ur.jalandhry', 34, 2, 3608, 'جو کچھ زمین میں داخل ہوتا ہے اور جو اس میں سے نکلتا ہے اور جو آسمان سے اُترتا ہے اور جو اس پر چڑھتا ہے سب اس کو معلوم ہے۔ اور وہ مہربان (اور) بخشنے والا ہے', NULL, NULL, '55af179443621fdc36be3e5ef44dfdfa2afca7869740f87902801c99337830bd'),
  ('ur.jalandhry', 34, 3, 3609, 'اور کافر کہتے ہیں کہ (قیامت کی) گھڑی ہم پر نہیں آئے گی۔ کہہ دو کیوں نہیں (آئے گی) میرے پروردگار کی قسم وہ تم پر ضرور آکر رہے گی (وہ پروردگار) غیب کا جاننے والا (ہے) ذرہ بھر چیز بھی اس سے پوشیدہ نہیں (نہ) آسمانوں میں اور نہ زمین میں اور کوئی چیز ذرے سے چھوٹی یا بڑی ایسی نہیں مگر کتاب روشن میں (لکھی ہوئی) ہے', NULL, NULL, '45462ae4a81542570397658eca2b601c458e3d711492f18bad8fbe2144c1dccb'),
  ('ur.jalandhry', 34, 4, 3610, 'اس لئے کہ جو لوگ ایمان لائے اور عمل نیک کرتے رہے ان کو بدلہ دے۔ یہی ہیں جن کے لئے بخشش اور عزت کی روزی ہے', NULL, NULL, 'b98af3a6397f6f35eb0db2c297a7186717ac36be88b9ff26f57771cba972aa11'),
  ('ur.jalandhry', 34, 5, 3611, 'اور جنہوں نے ہماری آیتوں میں کوشش کی کہ ہمیں ہرا دیں گے۔ ان کے لئے سخت درد دینے والے عذاب کی سزا ہے', NULL, NULL, '4b7868e9b5261877034aa16a7814e46cf3dccb635ae991d6b9e3f3f9ba46697a'),
  ('ur.jalandhry', 34, 6, 3612, 'اور جن لوگوں کو علم دیا گیا ہے وہ جانتے ہیں کہ جو (قرآن) تمہارے پروردگار کی طرف سے تم پر نازل ہوا ہے وہ حق ہے۔ اور (خدائے) غالب اور سزاوار تعریف کا رستہ بتاتا ہے', NULL, NULL, '4700855cbd8715368b30ca2474f96cd8b4c69f60c5f25edc4751a2b7ff3fe6d3'),
  ('ur.jalandhry', 34, 7, 3613, 'اور کافر کہتے ہیں کہ بھلا ہم تمہیں ایسا آدمی بتائیں جو تمہیں خبر دیتا ہے کہ جب تم (مر کر) بالکل پارہ پارہ ہو جاؤ گے تو نئے سرے سے پیدا ہوگے', NULL, NULL, '667f7652cfc36f3e4620cc827b3b9f3b2cafbd4de2660b6e60f7b9a84a1d27d3'),
  ('ur.jalandhry', 34, 8, 3614, 'یا تو اس نے خدا پر جھوٹ باندھ لیا ہے۔ یا اسے جنون ہے۔ بات یہ ہے کہ جو لوگ آخرت پر ایمان نہیں رکھتے وہ آفت اور پرلے درجے کی گمراہی میں (مبتلا) ہیں', NULL, NULL, 'd1d970cb57ab584e01870cb700c7c959b2cdc6cb6424fabe601da87d751ea9eb'),
  ('ur.jalandhry', 34, 9, 3615, 'کیا انہوں نے اس کو نہیں دیکھا جو ان کے آگے اور پیچھے ہے یعنی آسمان اور زمین۔ اگر ہم چاہیں تو ان کو زمین میں دھنسا دیں یا ان پر آسمان کے ٹکڑے گرا دیں۔ اس میں ہر بندے کے لئے جو رجوع کرنے والا ہے ایک نشانی ہے', NULL, NULL, 'c00a6ca795a981e35c4aaeb6c76a79df576d5fc8a02efc5ae3d926a4aa2f9b2f'),
  ('ur.jalandhry', 34, 10, 3616, 'اور ہم نے داؤد کو اپنی طرف سے برتری بخشی تھی۔ اے پہاڑو ان کے ساتھ تسبیح کرو اور پرندوں کو (ان کا مسخر کردیا) اور ان کے لئے ہم نے لوہے کو نرم کردیا', NULL, NULL, '804a76d5f9ef927a265a4142ee6282590c7d645488781fc1841cc0988efc9793'),
  ('ur.jalandhry', 34, 11, 3617, 'کہ کشادہ زرہیں بناؤ اور کڑیوں کو اندازے سے جوڑو اور نیک عمل کرو۔ جو عمل تم کرتے ہو میں ان کو دیکھنے والا ہوں', NULL, NULL, '3e21ccd2d6fdee490f4e4439bffa70d9ce25b3b24ed3db2d06e67924592e4e1e'),
  ('ur.jalandhry', 34, 12, 3618, 'اور ہوا کو (ہم نے) سلیمان کا تابع کردیا تھا اس کی صبح کی منزل ایک مہینے کی راہ ہوتی اور شام کی منزل بھی مہینے بھر کی ہوتی۔ اور ان کے لئے ہم نے تانبے کا چشمہ بہا دیا تھا اور جِنّوں میں سے ایسے تھے جو ان کے پروردگار کے حکم سے ان کے آگے کام کرتے تھے۔ اور جو کوئی ان میں سے ہمارے حکم سے پھرے گا اس کو ہم (جہنم کی) آگ کا مزہ چکھائیں گے', NULL, NULL, 'e1b2cdd51baf3a90fed843123f6fbb7857d872a34ccfb56deea18f7dab8c223e'),
  ('ur.jalandhry', 34, 13, 3619, 'وہ جو چاہتے یہ ان کے لئے بناتے یعنی قلعے اور مجسمے اور (بڑے بڑے) لگن جیسے تالاب اور دیگیں جو ایک ہی جگہ رکھی رہیں۔ اے داؤد کی اولاد (میرا) شکر کرو اور میرے بندوں میں شکرگزار تھوڑے ہیں', NULL, NULL, '1bfb745b567678d9589d7e1442d8628e0fcff5ce2817e7951358a4ac5df86019'),
  ('ur.jalandhry', 34, 14, 3620, 'پھر جب ہم نے ان کے لئے موت کا حکم صادر کیا تو کسی چیز سے ان کا مرنا معلوم نہ ہوا مگر گھن کے کیڑے سے جو ان کے عصا کو کھاتا رہا۔ جب عصا گر پڑا تب جنوں کو معلوم ہوا (اور کہنے لگے) کہ اگر وہ غیب جانتے ہوتے تو ذلت کی تکلیف میں نہ رہتے', NULL, NULL, '3873ff4a71a0c052656ce6ee8931be1db652978718f92863d5fc5be416ddcbde'),
  ('ur.jalandhry', 34, 15, 3621, '(اہل) سبا کے لئے ان کے مقام بودوباش میں ایک نشانی تھی (یعنی) دو باغ (ایک) داہنی طرف اور (ایک) بائیں طرف۔ اپنے پروردگار کا رزق کھاؤ اور اس کا شکر کرو۔ (یہاں تمہارے رہنے کو یہ) پاکیزہ شہر ہے اور (وہاں بخشنے کو) خدائے غفار', NULL, NULL, '284e9a77483f9fa4b3d80709cfd96b071c5fffaf541202a1e0ad77e12466a3ad'),
  ('ur.jalandhry', 34, 16, 3622, 'تو انہوں نے (شکرگزاری سے) منہ پھیر لیا پس ہم نے ان پر زور کا سیلاب چھوڑ دیا اور انہیں ان کے باغوں کے بدلے دو ایسے باغ دیئے جن کے میوے بدمزہ تھے اور جن میں کچھ تو جھاؤ تھا اور تھوڑی سی بیریاں', NULL, NULL, '45d50883e60fc548d3df2d2d8078664423306fc8a0d5592a4f912f0029da7c96'),
  ('ur.jalandhry', 34, 17, 3623, 'یہ ہم نے ان کی ناشکری کی ان کو سزا دی۔ اور ہم سزا ناشکرے ہی کو دیا کرتے ہیں', NULL, NULL, '2e31d762569f2bebae8f24b36adda9dff9bffbdc0657d113684ac24bb4d14999'),
  ('ur.jalandhry', 34, 18, 3624, 'اور ہم نے ان کے اور (شام کی) ان بستیوں کے درمیان جن میں ہم نے برکت دی تھی (ایک دوسرے کے متصل) دیہات بنائے تھے جو سامنے نظر آتے تھے اور ان میں آمد ورفت کا اندازہ مقرر کردیا تھا کہ رات دن بےخوف وخطر چلتے رہو', NULL, NULL, 'ec8afcc4393d8300a410df3cd6adb81e7ae52972ebd483c187f665e2ef54d081'),
  ('ur.jalandhry', 34, 19, 3625, 'تو انہوں نے دعا کی کہ اے پروردگار ہماری مسافتوں میں بُعد (اور طول پیدا) کردے اور (اس سے) انہوں نے اپنے حق میں ظلم کیا تو ہم نے (انہیں نابود کرکے) ان کے افسانے بنادیئے اور انہیں بالکل منتشر کردیا۔ اس میں ہر صابر وشاکر کے لئے نشانیاں ہیں', NULL, NULL, 'bdc572b6f6f5bd71e2358d057b4ca68152d6c58313d8d9cec29f6a4b5221e023'),
  ('ur.jalandhry', 34, 20, 3626, 'اور شیطان نے ان کے بارے میں اپنا خیال سچ کر دکھایا کہ مومنوں کی ایک جماعت کے سوا وہ اس کے پیچھے چل پڑے', NULL, NULL, 'fd23736ef4e3a291387cb9cc701a2a21b24207c79969b0b0d481b4781bb17be0'),
  ('ur.jalandhry', 34, 21, 3627, 'اور اس کا ان پر کچھ زور نہ تھا مگر (ہمارا) مقصود یہ تھا کہ جو لوگ آخرت میں شک رکھتے ہیں ان سے ان لوگوں کو جو اس پر ایمان رکھتے تھے متمیز کردیں۔ اور تمہارا پروردگار ہر چیز پر نگہبان ہے', NULL, NULL, '0f19d41392f7cba1342683e1581e15373855e39b3064e583c98e889f35138e25'),
  ('ur.jalandhry', 34, 22, 3628, 'کہہ دو کہ جن کو تم خدا کے سوا (معبود) خیال کرتے ہو ان کو بلاؤ۔ وہ آسمانوں اور زمین میں ذرہ بھر چیز کے بھی مالک نہیں ہیں اور نہ ان میں ان کی شرکت ہے اور نہ ان میں سے کوئی خدا کا مددگار ہے', NULL, NULL, '158ad7fdcbb5527025563bbdcbf87914e7608bc5150fd6b0c5aec28d439db269'),
  ('ur.jalandhry', 34, 23, 3629, 'اور خدا کے ہاں (کسی کے لئے) سفارش فائدہ نہ دے گی مگر اس کے لئے جس کے بارے میں وہ اجازت بخشے۔ یہاں تک کہ جب ان کے دلوں سے اضطراب دور کردیا جائے گا تو کہیں گے تمہارے پروردگار نے کیا فرمایا ہے۔ (فرشتے) کہیں گے کہ حق (فرمایا ہے) اور وہ عالی رتبہ اور گرامی قدر ہے', NULL, NULL, '9936cc6c6e8791220cb3d7b8fabd6234ecf0e5e4e53721ad502979ddea1a5894'),
  ('ur.jalandhry', 34, 24, 3630, 'پوچھو کہ تم کو آسمانوں اور زمین سے کون رزق دیتا ہے؟ کہو کہ خدا اور ہم یا تم (یا تو) سیدھے رستے پر ہیں یا صریح گمراہی میں', NULL, NULL, '91d67d075a131431b27fb8660adfe08ee8923acbd230b44d04d4ed2f4a8c7a53'),
  ('ur.jalandhry', 34, 25, 3631, 'کہہ دو کہ نہ ہمارے گناہوں کی تم سے پرسش ہوگی اور نہ تمہارے اعمال کی ہم سے پرسش ہوگی', NULL, NULL, '9bb11bbdb0d26af6a0896b6df8b93df137dd897b3dcc84280d48356165f3c360'),
  ('ur.jalandhry', 34, 26, 3632, 'کہہ دو کہ ہمارا پروردگار ہم کو جمع کرے گا پھر ہمارے درمیان انصاف کے ساتھ فیصلہ کردے گا۔ اور وہ خوب فیصلہ کرنے والا اور صاحب علم ہے', NULL, NULL, '2aba70a15c2fa85dcd483f3950287a5d089c4342ded4083b4b107710f41ac3ea'),
  ('ur.jalandhry', 34, 27, 3633, 'کہو کہ مجھے وہ لوگ تو دکھاؤ جن کو تم نے شریک (خدا) بنا کر اس کے ساتھ ملا رکھا ہے۔ کوئی نہیں بلکہ وہی (اکیلا) خدا غالب (اور) حکمت والا ہے', NULL, NULL, 'dcc2b50b4a6b7854d27b3e91c3beb7f3ef92d05162605271b37e9948e29c2e1d'),
  ('ur.jalandhry', 34, 28, 3634, 'اور (اے محمدﷺ) ہم نے تم کو تمام لوگوں کے لئے خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا ہے لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '91aad0e6caea5dfed4aa7a9e52db5e890010aa9569a18f0e39eff4cd7e71e9bd'),
  ('ur.jalandhry', 34, 29, 3635, 'اور کہتے ہیں اگر تم سچ کہتے ہو تو یہ (قیامت کا) وعدہ کب وقوع میں آئے گا', NULL, NULL, '387a4d3f1660a93e51464899ba160f1b62bc09bb5d0d7dc02682e26a034372c5'),
  ('ur.jalandhry', 34, 30, 3636, 'کہہ دو کہ تم سے ایک دن کا وعدہ ہے جس سے نہ ایک گھڑی پیچھے رہوگے اور نہ آگے بڑھو گے', NULL, NULL, '6def306853c00611d38eaa29e661363a62997e47113df1864198e031b7b19fe0'),
  ('ur.jalandhry', 34, 31, 3637, 'اور جو کافر ہیں وہ کہتے ہیں کہ ہم نہ تو اس قرآن کو مانیں گے اور نہ ان (کتابوں) کو جو ان سے پہلے کی ہیں اور کاش (ان) ظالموں کو تم اس وقت دیکھو جب یہ اپنے پروردگار کے سامنے کھڑے ہوں گے اور ایک دوسرے سے ردوکد کر رہے ہوں گے۔ جو لوگ کمزور سمجھے جاتے تھے وہ بڑے لوگوں سے کہیں گے کہ اگر تم نہ ہوتے تو ہم ضرور مومن ہوجاتے', NULL, NULL, '2f0253337648f2dd9efa785d139afcedfff76f70f025cedf26b8cbe1778ff62a'),
  ('ur.jalandhry', 34, 32, 3638, 'بڑے لوگ کمزوروں سے کہیں گے کہ بھلا ہم نے تم کو ہدایت سے جب وہ تمہارے پاس آچکی تھی روکا تھا؟ (نہیں) بلکہ تم ہی گنہگار تھے', NULL, NULL, 'a5c0503356afc62bc41853e3ec8866211460a36a05992fb73c022a6a22e1ecae'),
  ('ur.jalandhry', 34, 33, 3639, 'اور کمزور لوگ بڑے لوگوں سے کہیں گے (نہیں) بلکہ (تمہاری) رات دن کی چالوں نے (ہمیں روک رکھا تھا) جب تم ہم سے کہتے تھے کہ ہم خدا سے کفر کریں اور اس کا شریک بنائیں۔ اور جب وہ عذاب کو دیکھیں گے تو دل میں پشیمان ہوں گے۔ اور ہم کافروں کی گردنوں میں طوق ڈال دیں گے۔ بس جو عمل وہ کرتے تھے ان ہی کا ان کو بدلہ ملے گا', NULL, NULL, '97d5c135fcc817ee65b9f185d1f08e423ff0e6493a2b59d1e1d41be19ea10b84'),
  ('ur.jalandhry', 34, 34, 3640, 'اور ہم نے کسی بستی میں کوئی ڈرانے والا نہیں بھیجا مگر وہاں کے خوش حال لوگوں نے کہا کہ جو چیز تم دے کر بھیجے گئے ہو ہم اس کے قائل نہیں', NULL, NULL, '6a060be86ede8c0b5c72f25f457b129bb0fb47d2d211fa4f80c5dc45c14446df'),
  ('ur.jalandhry', 34, 35, 3641, 'اور (یہ بھی) کہنے لگے کہ ہم بہت سا مال اور اولاد رکھتے ہیں اور ہم کو عذاب نہیں ہوگا', NULL, NULL, 'a3cbc01e679b8e72e5dced2f0076ef615a8ebb458fbd22d553892d6fe7dd9a56'),
  ('ur.jalandhry', 34, 36, 3642, 'کہہ دو کہ میرا رب جس کے لئے چاہتا ہے روزی فراخ کردیتا ہے (اور جس کے لئے چاہتا ہے) تنگ کردیتا ہے لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '825adcf3d09a0477f1e713b3ab6714606ebcc65979220b52dc5282fd59af4951'),
  ('ur.jalandhry', 34, 37, 3643, 'اور تمہارا مال اور اولاد ایسی چیز نہیں کہ تم کو ہمارا مقرب بنا دیں۔ ہاں (ہمارا مقرب وہ ہے) جو ایمان لایا اور عمل نیک کرتا رہا۔ ایسے ہی لوگوں کو ان کے اعمال کے سبب دگنا بدلہ ملے گا اور وہ خاطر جمع سے بالاخانوں میں بیٹھے ہوں گے', NULL, NULL, '3d5afe92e6cabde3275fb830543b0b34343bf645cfeedfc90be99f7b90d908f0'),
  ('ur.jalandhry', 34, 38, 3644, 'جو لوگ ہماری آیتوں میں کوشش کرتے ہیں کہ ہمیں ہرا دیں وہ عذاب میں حاضر کئے جائیں گے', NULL, NULL, '03a4ee1f83eef16a1e26c58c3f71cdf59c9b7faf125d38339528a9885b3dbac9'),
  ('ur.jalandhry', 34, 39, 3645, 'کہہ دو کہ میرا پروردگار اپنے بندوں میں سے جس کے لئے چاہتا ہے روزی فراخ کردیتا ہے اور (جس کے لئے چاہتا ہے) تنگ کردیتا ہے اور تم جو چیز خرچ کرو گے وہ اس کا (تمہیں) عوض دے گا۔ اور وہ سب سے بہتر رزق دینے والا ہے', NULL, NULL, '6d0dab2106189ffb5282d4e56bad2a51c078a56fc37969b040a2ac3f046e31c9'),
  ('ur.jalandhry', 34, 40, 3646, 'اور جس دن وہ ان سب کو جمع کرے گا پھر فرشتوں سے فرمائے گا کیا یہ لوگ تم کو پوجا کرتے تھے', NULL, NULL, 'a2162dea10ad10efcf4ec1a3de04d559d84c882a91bc248ac5e18727f006e284'),
  ('ur.jalandhry', 34, 41, 3647, 'وہ کہیں گے تو پاک ہے تو ہی ہمارا دوست ہے۔ نہ یہ۔ بلکہ یہ جِنّات کو پوجا کرتے تھے۔ اور اکثر انہی کو مانتے تھے', NULL, NULL, 'a8c13d4f4115039f45375136cf00d3ad31d5a909baa356072d5fce01ccde14b3'),
  ('ur.jalandhry', 34, 42, 3648, 'تو آج تم میں سے کوئی کسی کو نفع اور نقصان پہنچانے کا اختیار نہیں رکھتا۔ اور ہم ظالموں سے کہیں گے کہ دوزخ کے عذاب کا جس کو تم جھوٹ سمجھتے تھے مزہ چکھو', NULL, NULL, 'b9241cb58a89218ac7529a5577aa00959707b116649961792dcdebff19411504'),
  ('ur.jalandhry', 34, 43, 3649, 'اور جب ان کو ہماری روشن آیتیں پڑھ کر سنائی جاتی ہیں تو کہتے ہیں یہ ایک (ایسا) شخص ہے جو چاہتا ہے کہ جن چیزوں کی تمہارے باپ دادا پرستش کیا کرتے تھے ان سے تم کو روک دے اور (یہ بھی) کہتے ہیں کہ یہ (قرآن) محض جھوٹ ہے (جو اپنی طرف سے) بنا لیا گیا ہے۔ اور کافروں کے پاس جب حق آیا تو اس کے بارے میں کہنے لگے کہ یہ تو صریح جادو ہے', NULL, NULL, '4146c66308d767c07b2e6226c3c7515d1275716340b1ba0ad26c0870d970dade'),
  ('ur.jalandhry', 34, 44, 3650, 'اور ہم نے نہ تو ان (مشرکوں) کو کتابیں دیں جن کو یہ پڑھتے ہیں اور نہ تم سے پہلے ان کی طرف کوئی ڈرانے والا بھیجا مگر انہوں نے تکذیب کی', NULL, NULL, '67acf4be9d098b8a02217e49f3dd59427906b6073b5cead60b55885743459eee'),
  ('ur.jalandhry', 34, 45, 3651, 'اور جو لوگ ان سے پہلے تھے انہوں نے تکذیب کی تھی اور جو کچھ ہم نے ان کو دیا تھا یہ اس کے دسویں حصے کو بھی نہیں پہنچے تو انہوں نے میرے پیغمبروں کو جھٹلایا۔ سو میرا عذاب کیسا ہوا', NULL, NULL, '518f287316ef301943f217b9e408a49816091b3e53283c3043ee49e4ec8f97bb'),
  ('ur.jalandhry', 34, 46, 3652, 'کہہ دو کہ میں تمہیں صرف ایک بات کی نصیحت کرتا ہوں کہ تم خدا کے لئے دو دو اور اکیلے اکیلے کھڑے ہوجاؤ پھر غور کرو۔ تمہارے رفیق کو سودا نہیں وہ تم کو عذاب سخت (کے آنے) سے پہلے صرف ڈرانے والے ہیں', NULL, NULL, '2895cd07a1fd00768d6fc38387066fde67e70883b0da52ebd8aea1488abdbf67'),
  ('ur.jalandhry', 34, 47, 3653, 'کہہ دو کہ میں نے تم سے کچھ صلہ مانگا ہو تو وہ تم ہی کو (مبارک رہے) ۔ میرا صلہ خدا ہی کے ذمے ہے۔ اور وہ ہر چیز سے خبردار ہے', NULL, NULL, '9f1e8ad542ed921705a5e33c2695641e1ba86e8554b670def5d7b88d6a9a77d2'),
  ('ur.jalandhry', 34, 48, 3654, 'کہہ دو کہ میرا پروردگار اوپر سے حق اُتارتا ہے (اور وہ) غیب کی باتوں کا جاننے والا ہے', NULL, NULL, 'b72509d48f5ce4c912ca7b98b6476cec050b46fe86623ca19cad4a752cea8a05'),
  ('ur.jalandhry', 34, 49, 3655, 'کہہ دو کہ حق آچکا اور (معبود) باطل نہ تو پہلی بار پیدا کرسکتا ہے اور نہ دوبارہ پیدا کرے گا', NULL, NULL, '4405ced1208168038381576abe29d08c9899dfe6239889ef2932fa1a4df564d1'),
  ('ur.jalandhry', 34, 50, 3656, 'کہہ دو کہ اگر میں گمراہ ہوں تو میری گمراہی کا ضرر مجھی کو ہے۔ اور اگر ہدایت پر ہوں تو یہ اس کا طفیل ہے جو میرا پروردگار میری طرف وحی بھیجتا ہے۔ بےشک وہ سننے والا (اور) نزدیک ہے', NULL, NULL, '4779bf5e6937035b3a04f92fb72525907d07c05b1f53fb1a21c7bb0339dacae6'),
  ('ur.jalandhry', 34, 51, 3657, 'اور کاش تم دیکھو جب یہ گھبرا جائیں گے تو (عذاب سے) بچ نہیں سکیں گے اور نزدیک ہی سے پکڑ لئے جائیں گے', NULL, NULL, 'df050d5c87c2c28d5f2b01a99cb88a0703d64b725ce7b35f03fa88c9c86c8a19'),
  ('ur.jalandhry', 34, 52, 3658, 'اور کہیں گے کہ ہم اس پر ایمان لے آئے اور (اب) اتنی دور سے ان کا ہاتھ ایمان کے لینے کو کیونکر پہنچ سکتا ہے', NULL, NULL, 'e4d97692b00b2484296d5f8aa919dea6be40ce6dd4cbc0c87193e7479543b7cf'),
  ('ur.jalandhry', 34, 53, 3659, 'اور پہلے تو اس سے انکار کرتے رہے اور بن دیکھے دور ہی سے (ظن کے) تیر چلاتے رہے', NULL, NULL, 'fb220a204fa35f02a7e980244ae49fedb9eb62985cbecf49e01e01e40892823a'),
  ('ur.jalandhry', 34, 54, 3660, 'اور ان میں اور ان کی خواہش کی چیزوں میں پردہ حائل کردیا گیا جیسا کہ پہلے ان کے ہم جنسوں سے کیا گیا وہ بھی الجھن میں ڈالنے والے شک میں پڑے ہوئے تھے', NULL, NULL, '457cb209340458490d1a92a19623e94395265dde39b7907784b78a638dfbc0bd'),
  ('ur.jalandhry', 35, 1, 3661, 'سب تعریف خدا ہی کو (سزاوار ہے) جو آسمانوں اور زمین کا پیدا کرنے والا (اور) فرشتوں کو قاصد بنانے والا ہے جن کے دو دو اور تین تین اور چار چار پر ہیں۔ وہ (اپنی) مخلوقات میں جو چاہتا ہے بڑھاتا ہے۔ بےشک خدا ہر چیز پر قادر ہے', NULL, NULL, '872f40d84934fc5383c4f5ac66e7423331e4a4b85c2e93b4be6b56196f50be3d'),
  ('ur.jalandhry', 35, 2, 3662, 'خدا جو اپنی رحمت (کا دروازہ) کھول دے تو کوئی اس کو بند کرنے والا نہیں۔ اور جو بند کردے تو اس کے بعد کوئی اس کو کھولنے والا نہیں۔ اور وہ غالب حکمت والا ہے', NULL, NULL, '896cefc46ccd3274d8c59da6f97a7bd68547f974d1fe1cfcb38f4ad736232808'),
  ('ur.jalandhry', 35, 3, 3663, 'لوگو خدا کے جو تم پر احسانات ہیں ان کو یاد کرو۔ کیا خدا کے سوا کوئی اور خالق (اور رازق ہے) جو تم کو آسمان اور زمین سے رزق دے۔ اس کے سوا کوئی معبود نہیں پس تم کہاں بہکے پھرتے ہو؟', NULL, NULL, 'ef4964edb3cedbe746f171f173bc032a4aedc8d88e9a3f29d44b0619e75e18d5'),
  ('ur.jalandhry', 35, 4, 3664, 'اور (اے پیغمبر) اگر یہ لوگ تم کو جھٹلائیں تو تم سے پہلے بھی پیغمبر جھٹلائے گئے ہیں۔ اور (سب) کام خدا ہی کی طرف لوٹائے جائیں گے', NULL, NULL, 'c639b63b148235df6d46348912a668ad9755d5d0458feef1614ba6eacfa1b447'),
  ('ur.jalandhry', 35, 5, 3665, 'لوگو خدا کا وعدہ سچا ہے۔ تو تم کو دنیا کی زندگی دھوکے میں نہ ڈال دے اور نہ (شیطان) فریب دینے والا تمہیں فریب دے', NULL, NULL, 'da4eaf41cc7e18af18d77c0bc31dee3340db4e5ab3cffe47bb238494ee880abc'),
  ('ur.jalandhry', 35, 6, 3666, 'شیطان تمہارا دشمن ہے تم بھی اسے دشمن ہی سمجھو۔ وہ اپنے (پیروؤں کے) گروہ کو بلاتا ہے تاکہ دوزخ والوں میں ہوں', NULL, NULL, '71bf114bf197f602bc02840b72598c0278c15e133457eb582a25a2c091b501a2'),
  ('ur.jalandhry', 35, 7, 3667, 'جہنوں نے کفر کیا ان کے لئے سخت عذاب ہے۔ اور جو ایمان لائے اور عمل نیک کرتے رہے ان کے لئے بخشش اور بڑا ثواب ہے', NULL, NULL, 'bfe6de393643aa192e12a6bd70c894664da9aff0d81a76f273568e6f6063560e'),
  ('ur.jalandhry', 35, 8, 3668, 'بھلا جس شخص کو اس کے اعمال بد آراستہ کرکے دکھائے جائیں اور وہ ان کو عمدہ سمجھنے لگے تو (کیا وہ نیکوکار آدمی جیسا ہوسکتا ہے) ۔ بےشک خدا جس کو چاہتا ہے گمراہ کرتا ہے اور جس کو چاہتا ہے ہدایت دیتا ہے۔ تو ان لوگوں پر افسوس کرکے تمہارا دم نہ نکل جائے۔ یہ جو کچھ کرتے ہیں خدا اس سے واقف ہے', NULL, NULL, 'b16e2e6e26d7b11c617557ac6200fab74eaff777e96d7e113c323a05f5faa062'),
  ('ur.jalandhry', 35, 9, 3669, 'اور خدا ہی تو ہے جو ہوائیں چلاتا ہے اور وہ بادل کو اُبھارتی ہیں پھر ہم ان کو ایک بےجان شہر کی طرف چلاتے ہیں۔ پھر اس سے زمین کو اس کے مرنے کے بعد زندہ کردیتے ہیں۔ اسی طرح مردوں کو جی اُٹھنا ہوگا', NULL, NULL, '7bb214a7f964ad1fd532a3b3b462f1356b2c02473648aa9fac591fafba5a4f96'),
  ('ur.jalandhry', 35, 10, 3670, 'جو شخص عزت کا طلب گار ہے تو عزت تو سب خدا ہی کی ہے۔ اسی کی طرف پاکیزہ کلمات چڑھتے ہیں اور نیک عمل اس کو بلند کرتے ہیں۔ اور جو لوگ برے برے مکر کرتے ہیں ان کے لئے سخت عذاب ہے۔ اور ان کا مکر نابود ہوجائے گا', NULL, NULL, '2c3baadcab2095f02379012c93c0799d5110dbcff1e1da2db6f32bc17dcdfde5'),
  ('ur.jalandhry', 35, 11, 3671, 'اور خدا ہی نے تم کو مٹی سے پیدا کیا پھر نطفے سے پھر تم کو جوڑا جوڑا بنا دیا۔ اور کوئی عورت نہ حاملہ ہوتی ہے اور نہ جنتی ہے مگر اس کے علم سے۔ اور نہ کسی بڑی عمر والے کو عمر زیادہ دی جاتی ہے اور نہ اس کی عمر کم کی جاتی ہے مگر (سب کچھ) کتاب میں (لکھا ہوا) ہے۔ بےشک یہ خدا کو آسان ہے', NULL, NULL, '954abbbed3c651c520ddbd91aa9ade792e2dcf2b06fa572720d3df9cc3d1b375'),
  ('ur.jalandhry', 35, 12, 3672, 'اور دونوں دریا (مل کر) یکساں نہیں ہوجاتے۔ یہ تو میٹھا ہے پیاس بجھانے والا۔ جس کا پانی خوشگوار ہے اور یہ کھاری ہے کڑوا۔ اور سب سے تم تازہ گوشت کھاتے ہو اور زیور نکالتے ہو جسے پہنتے ہو۔ اور تم دریا میں کشتیوں کو دیکھتے ہو کہ (پانی کو) پھاڑتی چلی آتی ہیں تاکہ تم اس کے فضل سے (معاش) تلاش کرو اور تاکہ شکر کرو', NULL, NULL, 'f8b5dda2b80c1131dee7e686acc94baab78cccad7d9c545a402eeaaba7198e35'),
  ('ur.jalandhry', 35, 13, 3673, 'وہی رات کو دن میں داخل کرتا اور (وہی) دن کو رات میں داخل کرتا ہے اور اسی نے سورج اور چاند کو کام میں لگا دیا ہے۔ ہر ایک ایک وقت مقرر تک چل رہا ہے۔ یہی خدا تمہارا پروردگار ہے اسی کی بادشاہی ہے۔ اور جن لوگوں کو تم اس کے سوا پکارتے ہو وہ کھجور کی گٹھلی کے چھلکے کے برابر بھی تو (کسی چیز کے) مالک نہیں', NULL, NULL, 'b63a08a0333c04e8680f8063b9aadada77bdb696dbb53df6117daafbf4d2b911'),
  ('ur.jalandhry', 35, 14, 3674, 'اگر تم ان کو پکارو تو وہ تمہاری پکار نہ سنیں اور اگر سن بھی لیں تو تمہاری بات کو قبول نہ کرسکیں۔ اور قیامت کے دن تمہارے شرک سے انکار کردیں گے۔ اور (خدائے) باخبر کی طرح تم کو کوئی خبر نہیں دے گا', NULL, NULL, '7bf433aabcf65ba13523504be97289da7000073a49a6758d477a865500c1647e'),
  ('ur.jalandhry', 35, 15, 3675, 'لوگو تم (سب) خدا کے محتاج ہو اور خدا بےپروا سزاوار (حمد وثنا) ہے', NULL, NULL, '63b24f0f359b5cf81b224ba95049069b727dc7e71d6544c041a5950d27a6d0d7'),
  ('ur.jalandhry', 35, 16, 3676, 'اگر چاہے تو تم کو نابود کردے اور نئی مخلوقات لا آباد کرے', NULL, NULL, '5b87f81855b1baa1eb88990d729949864b31aceb148c12b68f89328a5f63fea6'),
  ('ur.jalandhry', 35, 17, 3677, 'اور یہ خدا کو کچھ مشکل نہیں', NULL, NULL, 'b1a100197abb3bf900877a81bfaa0ad013b10cab60c5ac62b860fb6eaed6bb18'),
  ('ur.jalandhry', 35, 18, 3678, 'اور کوئی اٹھانے والا دوسرے کا بوجھ نہ اٹھائے گا۔ اور کوئی بوجھ میں دبا ہوا اپنا بوجھ بٹانے کو کسی کو بلائے تو کوئی اس میں سے کچھ نہ اٹھائے گا اگرچہ قرابت دار ہی ہو۔ (اے پیغمبر) تم انہی لوگوں کو نصیحت کرسکتے ہو جو بن دیکھے اپنے پروردگار سے ڈرتے اور نماز بالالتزام پڑھتے ہیں۔ اور جو شخص پاک ہوتا ہے اپنے ہی لئے پاک ہوتا ہے۔ اور (سب کو) خدا ہی کی طرف لوٹ کر جانا ہے', NULL, NULL, '85d367cf585751c9442a6b39b3f352a04ab5c24250d0a507ccd6d04256a95e3f'),
  ('ur.jalandhry', 35, 19, 3679, 'اور اندھا اور آنکھ والا برابر نہیں', NULL, NULL, 'e47daec9db31bc64f4d7709a3c0d916a0a6a1e3eba573b1ad9dce49b65c06b26'),
  ('ur.jalandhry', 35, 20, 3680, 'اور نہ اندھیرا اور روشنی', NULL, NULL, 'cdce91d05e410a29fa654c42eec93e30a526c8f3872079fea56beb69ecac08f5'),
  ('ur.jalandhry', 35, 21, 3681, 'اور نہ سایہ اور دھوپ', NULL, NULL, 'd4318c716d494413f2862c0efc76ce4cc53917e2e99e6476a9e6210233cfbc37'),
  ('ur.jalandhry', 35, 22, 3682, 'اور نہ زندے اور مردے برابر ہوسکتے ہیں۔ خدا جس کو چاہتا ہے سنا دیتا ہے۔ اور تم ان کو جو قبروں میں مدفون ہیں نہیں سنا سکتے', NULL, NULL, '13b22f2c2f9b3a3ddf4fff5f361d5c2bd6a8b79b5e6fe54e04aa8e9073383e07'),
  ('ur.jalandhry', 35, 23, 3683, 'تم تو صرف ڈرانے والے ہو', NULL, NULL, 'a1b9d4ddabf55051bbf427b95cf3ea6b9bca5115ad7bdf7001ebd5c54f0a04dc'),
  ('ur.jalandhry', 35, 24, 3684, 'ہم نے تم کو حق کے ساتھ خوشخبری سنانے والا اور ڈرانے والا بھیجا ہے۔ اور کوئی اُمت نہیں مگر اس میں ہدایت کرنے والا گزر چکا ہے', NULL, NULL, 'f4d42ef9d5dddf56bd8450c640e8c11702e0e316e4f134d09f8847ad40879fe4'),
  ('ur.jalandhry', 35, 25, 3685, 'اور اگر یہ تمہاری تکذیب کریں تو جو لوگ ان سے پہلے تھے وہ بھی تکذیب کرچکے ہیں ان کے پاس ان کے پیغمبر نشانیاں اور صحیفے اور روشن کتابیں لے لے کر آتے رہے', NULL, NULL, '343bab3a1982163c2008904e92334f4ac38b4e37ddf94a5970a5fd64ea4f6b41'),
  ('ur.jalandhry', 35, 26, 3686, 'پھر میں نے کافروں کو پکڑ لیا سو (دیکھ لو کہ) میرا عذاب کیسا ہوا', NULL, NULL, '6a12cd96507bbd8e83aff027e910a095754080a16143138a80e0caf02f75c0b9'),
  ('ur.jalandhry', 35, 27, 3687, 'کیا تم نے نہیں دیکھا کہ خدا نے آسمان سے مینہ برسایا۔ تو ہم نے اس سے طرح طرح کے رنگوں کے میوے پیدا کئے۔ اور پہاڑوں میں سفید اور سرخ رنگوں کے قطعات ہیں اور (بعض) کالے سیاہ ہیں', NULL, NULL, 'cec4217eb689a3549afdb1b497e16bde1936f57ced15cad240996df462dfbe3b'),
  ('ur.jalandhry', 35, 28, 3688, 'انسانوں اور جانوروں اور چارپایوں کے بھی کئی طرح کے رنگ ہیں۔ خدا سے تو اس کے بندوں میں سے وہی ڈرتے ہیں جو صاحب علم ہیں۔ بےشک خدا غالب (اور) بخشنے والا ہے', NULL, NULL, 'b55a258d1b8eaabafd10be9a3fe659fc8a04045ea0261f6e9a2b0c714e9a5a14'),
  ('ur.jalandhry', 35, 29, 3689, 'جو لوگ خدا کی کتاب پڑھتے اور نماز کی پابندی کرتے ہیں اور جو کچھ ہم نے ان کو دیا ہے اس میں سے پوشیدہ اور ظاہر خرچ کرتے ہیں وہ اس تجارت (کے فائدے) کے امیدوار ہیں جو کبھی تباہ نہیں ہوگی', NULL, NULL, 'dab43b62b64827189fbc5cb2bf271cfb2dd9d4c08e39ce34fe80bf402ecbc5ef'),
  ('ur.jalandhry', 35, 30, 3690, 'کیونکہ خدا ان کو پورا پورا بدلہ دے گا اور اپنے فضل سے کچھ زیادہ بھی دے گا۔ وہ تو بخشنے والا (اور) قدردان ہے', NULL, NULL, '300129c7f23b3686cfb7c48d89404fdd22298dc4f4c1c88f7bbf281511a61bac'),
  ('ur.jalandhry', 35, 31, 3691, 'اور یہ کتاب جو ہم نے تمہاری طرف بھیجی ہے برحق ہے۔ اور ان (کتابوں) کی تصدیق کرتی ہے جو اس سے پہلے کی ہیں۔ بےشک خدا اپنے بندوں سے خبردار (اور ان کو) دیکھنے والا ہے', NULL, NULL, 'b4cc4d42dd78e95777520072bba53dd12b1d7005492414f32cccf457304e6a48'),
  ('ur.jalandhry', 35, 32, 3692, 'پھر ہم نے ان لوگوں کو کتاب کا وارث ٹھیرایا جن کو اپنے بندوں میں سے برگزیدہ کیا۔ تو کچھ تو ان میں سے اپنے آپ پر ظلم کرتے ہیں۔ اور کچھ میانہ رو ہیں۔ اور کچھ خدا کے حکم سے نیکیوں میں آگے نکل جانے والے ہیں۔ یہی بڑا فضل ہے', NULL, NULL, '67de3abad76f33cde5b72b9a43987d4afb76255217994dbfd7cf8b6aeeddedea'),
  ('ur.jalandhry', 35, 33, 3693, '(ان لوگوں کے لئے) بہشتِ جاودانی (ہیں) جن میں وہ داخل ہوں گے۔ وہاں ان کو سونے کے کنگن اور موتی پہنائے جائیں گے۔ اور ان کی پوشاک ریشمی ہوگی', NULL, NULL, '259cb8425e866296ff4d17f00fc9a8eb9e033d41a734c7d5fa8c4748a2eab5fd'),
  ('ur.jalandhry', 35, 34, 3694, 'وہ کہیں گے کہ خدا کا شکر ہے جس نے ہم سے غم دور کیا۔ بےشک ہمارا پروردگار بخشنے والا (اور) قدردان ہے', NULL, NULL, 'd63816d9aac44ef89a39db2bd0f095e3fc2fea547cdfd1ab2433cef5cb730596'),
  ('ur.jalandhry', 35, 35, 3695, 'جس نے ہم کو اپنے فضل سے ہمیشہ کے رہنے کے گھر میں اُتارا۔ یہاں نہ تو ہم کو رنج پہنچے گا اور نہ ہمیں تکان ہی ہوگی', NULL, NULL, '740f979e706c1f50d4ed06cdebbbee99e4567833a65470206b4f4193e5a4ff80'),
  ('ur.jalandhry', 35, 36, 3696, 'اور جن لوگوں نے کفر کیا ان کے لئے دوزخ کی آگ ہے۔ نہ انہیں موت آئے گی کہ مرجائیں اور نہ ان کا عذاب ہی ان سے ہلکا کیا جائے گا۔ ہم ہر ایک ناشکرے کو ایسا ہی بدلہ دیا کرتے ہیں', NULL, NULL, 'bb1a2fcccba4c26ab5a47659d2813b487714579586b3f26bcbdcd68b9260a354'),
  ('ur.jalandhry', 35, 37, 3697, 'وہ اس میں چلائیں گے کہ اے پروردگار ہم کو نکال لے (اب) ہم نیک عمل کیا کریں گے۔ نہ وہ جو (پہلے) کرتے تھے۔ کیا ہم نے تم کو اتنی عمر نہیں دی تھی کہ اس میں جو سوچنا چاہتا سوچ لیتا اور تمہارے پاس ڈرانے والا بھی آیا۔ تو اب مزے چکھو۔ ظالموں کا کوئی مددگار نہیں', NULL, NULL, 'c2b050df221b8cf12d4a8c035d03e902c8f0b285c822566a8b7850fdb936a4be'),
  ('ur.jalandhry', 35, 38, 3698, 'بےشک خدا ہی آسمانوں اور زمین کی پوشیدہ باتوں کا جاننے والا ہے۔ وہ تو دل کے بھیدوں تک سے واقف ہے', NULL, NULL, '54ecd4a8b18a16cb3a3b1c5163dfc42dcc495c8bf08bc3638dfa88ba8433e665'),
  ('ur.jalandhry', 35, 39, 3699, 'وہی تو ہے جس نے تم کو زمین میں (پہلوں کا) جانشین بنایا۔ تو جس نے کفر کیا اس کے کفر کا ضرر اسی کو ہے۔ اور کافروں کے حق میں ان کے کفر سے پروردگار کے ہاں ناخوشی ہی بڑھتی ہے اور کافروں کو ان کا کفر نقصان ہی زیادہ کرتا ہے', NULL, NULL, 'ae7463658c171f7824a5131b18852d2ad1be9fdd054dabe71f6727c23aba33d4'),
  ('ur.jalandhry', 35, 40, 3700, 'بھلا تم نے اپنے شریکوں کو دیکھا جن کو تم خدا کے سوا پکارتے ہو۔ مجھے دکھاؤ کہ انہوں نے زمین سے کون سی چیز پیدا کی ہے یا (بتاؤ کہ) آسمانوں میں ان کی شرکت ہے۔ یا ہم نے ان کو کتاب دی ہے تو وہ اس کی سند رکھتے ہیں (ان میں سے کوئی بات بھی نہیں) بلکہ ظالم جو ایک دوسرے کو وعدہ دیتے ہیں محض فریب ہے', NULL, NULL, '5fe809056368bdb030cd5aa701806ae61b9a619170e8a9fc1de277e9ce7893b0')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 35, 41, 3701, 'خدا ہی آسمانوں اور زمین کو تھامے رکھتا ہے کہ ٹل نہ جائیں۔ اگر وہ ٹل جائیں تو خدا کے سوا کوئی ایسا نہیں جو ان کو تھام سکے۔ بےشک وہ بردبار (اور) بخشنے والا ہے', NULL, NULL, '89caa2d93539935bd12bd4bce02856d00bdbdde35ce526660403ef8b9a593cbd'),
  ('ur.jalandhry', 35, 42, 3702, 'اور یہ خدا کی سخت سخت قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی ہدایت کرنے والا آئے تو ہر ایک اُمت سے بڑھ کر ہدایت پر ہوں۔ مگر جب ان کے پاس ہدایت کرنے والا آیا تو اس سے ان کو نفرت ہی بڑھی', NULL, NULL, '98ac1e0153bb800b26759bfc1c1cd7f1f3084a61f2d53519bcf3b6e77bcf40ba'),
  ('ur.jalandhry', 35, 43, 3703, 'یعنی (انہوں نے) ملک میں غرور کرنا اور بری چال چلنا (اختیار کیا) اور بری چال کا وبال اس کے چلنے والے ہی پر پڑتا ہے۔ یہ اگلے لوگوں کی روش کے سوا اور کسی چیز کے منتظر نہیں۔ سو تم خدا کی عادت میں ہرگز تبدل نہ پاؤ گے۔ اور خدا کے طریقے میں کبھی تغیر نہ دیکھو گے', NULL, NULL, '35c4fe09f6daac6bc4b572d9a50812b486e299b19ba7c316f3dd5eee468bfd6c'),
  ('ur.jalandhry', 35, 44, 3704, 'کیا انہوں نے زمین میں کبھی سیر نہیں کی تاکہ دیکھتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیا ہوا حالانکہ وہ ان سے قوت میں بہت زیادہ تھے۔ اور خدا ایسا نہیں کہ آسمانوں اور زمین میں کوئی چیز اس کو عاجز کرسکے۔ وہ علم والا (اور) قدرت والا ہے', NULL, NULL, '277403c7ccdf043583901f190bfcaa56a6690383a69135c71fb7ab3fa826efd0'),
  ('ur.jalandhry', 35, 45, 3705, 'اور اگر خدا لوگوں کو ان کے اعمال کے سبب پکڑنے لگتا۔ تو روئے زمین پر ایک چلنے پھرنے والے کو نہ چھوڑتا۔ لیکن وہ ان کو ایک وقت مقرر تک مہلت دیئے جاتا ہے۔ سو جب ان کا وقت آجائے گا تو (ان کے اعمال کا بدلہ دے گا) خدا تو اپنے بندوں کو دیکھ رہا ہے', NULL, NULL, 'ecf13ed9f8c94ad1b576138369c414ea8581218e774cfc6696b0ea5276569e41'),
  ('ur.jalandhry', 36, 1, 3706, 'یٰسٓ', NULL, NULL, 'ca7c242c611a056446429234faed45d6e88b2c8c23edb0577291b469061fcd37'),
  ('ur.jalandhry', 36, 2, 3707, 'قسم ہے قرآن کی جو حکمت سے بھرا ہوا ہے', NULL, NULL, 'cd9d06a6646a00ef5196f900065473855819997d77e26ac91380851400023790'),
  ('ur.jalandhry', 36, 3, 3708, 'اے محمدﷺ) بےشک تم پیغمبروں میں سے ہو', NULL, NULL, 'f63d83aeb9103840a196aee775b56424a4963c64dd1f0f9c7a2345b664a8f5ff'),
  ('ur.jalandhry', 36, 4, 3709, 'سیدھے رستے پر', NULL, NULL, '44b95f0d36cee02f2ec1cbf511efc424120b73f7edf6efe20bbe6d1b14e1d99c'),
  ('ur.jalandhry', 36, 5, 3710, 'یہ خدائے) غالب (اور) مہربان نے نازل کیا ہے', NULL, NULL, '45966bedd518cf9dc293703de6978a7605c87bb3c6ffc639fa018e2da66bf339'),
  ('ur.jalandhry', 36, 6, 3711, 'تاکہ تم ان لوگوں کو جن کے باپ دادا کو متنبہ نہیں کیا گیا تھا متنبہ کردو وہ غفلت میں پڑے ہوئے ہیں', NULL, NULL, 'f85ecde04f4c4c029adc9e57b3287b916c63b805ac04bd66b4fac7aee9b408fb'),
  ('ur.jalandhry', 36, 7, 3712, 'ان میں سے اکثر پر (خدا کی) بات پوری ہوچکی ہے سو وہ ایمان نہیں لائیں گے', NULL, NULL, 'c5cda6035e039e98bde588a83c82d64c639351bd3e589ea56cbc682283356a33'),
  ('ur.jalandhry', 36, 8, 3713, 'ہم نے ان کی گردنوں میں طوق ڈال رکھے ہیں اور وہ ٹھوڑیوں تک (پھنسے ہوئے ہیں) تو ان کے سر اُلل رہے ہیں', NULL, NULL, '89ccc5c5e0206da9e53859b3543e37189a6d4653ff67998d797ce6dda0914b50'),
  ('ur.jalandhry', 36, 9, 3714, 'اور ہم نے ان کے آگے بھی دیوار بنا دی اور ان کے پیچھے بھی۔ پھر ان پر پردہ ڈال دیا تو یہ دیکھ نہیں سکتے', NULL, NULL, 'b594ab507ae09d197b47f95ad4c55a8b37cfb873d479ccf794066bba11212722'),
  ('ur.jalandhry', 36, 10, 3715, 'اور تم ان کو نصیحت کرو یا نہ کرو ان کے لئے برابر ہے وہ ایمان نہیں لانے کے', NULL, NULL, '4505dd54a049d30a21aff9b5ac090d89f543c9d9a7fc1cd133523ac54ff1827b'),
  ('ur.jalandhry', 36, 11, 3716, 'تم تو صرف اس شخص کو نصیحت کرسکتے ہو جو نصیحت کی پیروی کرے اور خدا سے غائبانہ ڈرے سو اس کو مغفرت اور بڑے ثواب کی بشارت سنا دو', NULL, NULL, 'a791f5d99994cb3630b5cf73a4b16a8133db4dd2e54520003169ef1b1da8458e'),
  ('ur.jalandhry', 36, 12, 3717, 'بےشک ہم مردوں کو زندہ کریں گے اور جو کچھ وہ آگے بھیج چکے اور (جو) ان کے نشان پیچھے رہ گئے ہم ان کو قلمبند کرلیتے ہیں۔ اور ہر چیز کو ہم نے کتاب روشن (یعنی لوح محفوظ) میں لکھ رکھا ہے۔', NULL, NULL, '3409999ade0568d3b2dac6bd45ca1466081eb092703a12045030d59ae0da3d9d'),
  ('ur.jalandhry', 36, 13, 3718, 'اور ان سے گاؤں والوں کا قصہ بیان کرو جب ان کے پاس پیغمبر آئے', NULL, NULL, '2d652b8dee854fb9326d3576cb7e5e7b09faea6d8236ae5709416d4dca1c113e'),
  ('ur.jalandhry', 36, 14, 3719, '(یعنی) جب ہم نے ان کی طرف دو (پیغمبر) بھیجے تو انہوں نے ان کو جھٹلایا۔ پھر ہم نے تیسرے سے تقویت دی تو انہوں نے کہا کہ ہم تمہاری طرف پیغمبر ہو کر آئے ہیں', NULL, NULL, 'ab821ecdf8f53571d1b67b41d614922a2684d8590b2c3a12c86c94285e441083'),
  ('ur.jalandhry', 36, 15, 3720, 'وہ بولے کہ تم (اور کچھ) نہیں مگر ہماری طرح کے آدمی (ہو) اور خدا نے کوئی چیز نازل نہیں کی تم محض جھوٹ بولتے ہو', NULL, NULL, 'c46f5cec3d4cd8fc0e4634811f9a8b8932f9c045abaa56ddd3edbc9ba1981fde'),
  ('ur.jalandhry', 36, 16, 3721, 'انہوں نے کہا کہ ہمارا پروردگار جانتا ہے کہ ہم تمہاری طرف (پیغام دے کر) بھیجے گئے ہیں', NULL, NULL, '78bb4de16b4f060b879b0d433c97d880aab9fe777b5b35c952bd0fe47fc0fc9d'),
  ('ur.jalandhry', 36, 17, 3722, 'اور ہمارے ذمے تو صاف صاف پہنچا دینا ہے اور بس', NULL, NULL, 'f821032f486750869a26d9f176ca2828dd8e3e160a7e82f0c0cda2f98c76077f'),
  ('ur.jalandhry', 36, 18, 3723, 'وہ بولے کہ ہم تم کو نامبارک سمجھتے ہیں۔ اگر تم باز نہ آؤ گے تو ہم تمہیں سنگسار کردیں گے اور تم کو ہم سے دکھ دینے والا عذاب پہنچے گا', NULL, NULL, 'bf8c2ef5b6720d97fbb520a39ca472b6d705d6c28796ee28ed8a39212d005a18'),
  ('ur.jalandhry', 36, 19, 3724, 'انہوں نے کہا کہ تمہاری نحوست تمہارے ساتھ ہے۔ کیا اس لئے کہ تم کو نصیحت کی گئی۔ بلکہ تم ایسے لوگ ہو جو حد سے تجاوز کر گئے ہو', NULL, NULL, '05f5858b2477598471456a2df3b9abe22bf953466c72b81df29f951390c61427'),
  ('ur.jalandhry', 36, 20, 3725, 'اور شہر کے پرلے کنارے سے ایک آدمی دوڑتا ہوا آیا کہنے لگا کہ اے میری قوم پیغمبروں کے پیچھے چلو', NULL, NULL, '9363eb958ff12a7bfe8c9bacec6568f5ddf46659667bb0cd8b7cdd7c1de71b31'),
