  ('ur.jalandhry', 36, 37, 3742, 'اور ایک نشانی ان کے لئے رات ہے کہ اس میں سے ہم دن کو کھینچ لیتے ہیں تو اس وقت ان پر اندھیرا چھا جاتا ہے', NULL, NULL, '25fbd62310381577d2cdb3c5a19953939642e9b70447cb263eb56867dfa97eba'),
  ('ur.jalandhry', 36, 38, 3743, 'اور سورج اپنے مقرر رستے پر چلتا رہتا ہے۔ یہ (خدائے) غالب اور دانا کا (مقرر کیا ہوا) اندازہ ہے', NULL, NULL, 'a26442b2e073a838837871a91b51a832122bc6496806120ccc020df885318230'),
  ('ur.jalandhry', 36, 39, 3744, 'اور چاند کی بھی ہم نے منزلیں مقرر کردیں یہاں تک کہ (گھٹتے گھٹتے) کھجور کی پرانی شاخ کی طرح ہو جاتا ہے', NULL, NULL, '55fe0b42dc6f4f23eb11d3b36c40721956a5670e6a4dc7f3a9a0d6ef2a53307c'),
  ('ur.jalandhry', 36, 40, 3745, 'نہ تو سورج ہی سے ہوسکتا ہے کہ چاند کو جا پکڑے اور نہ رات ہی دن سے پہلے آسکتی ہے۔ اور سب اپنے اپنے دائرے میں تیر رہے ہیں', NULL, NULL, 'bc3723da845928bf4c03dff8c5382199b2dd32c7342ebdc5fe8ef6e678bc1bb9'),
  ('ur.jalandhry', 36, 41, 3746, 'اور ایک نشانی ان کے لئے یہ ہے کہ ہم نے ان کی اولاد کو بھری ہوئی کشتی میں سوار کیا', NULL, NULL, 'aa86f59a61f5a786d3e21a72a9f7fbe2c4337a092851fe0ec49c98a3fd1211ce'),
  ('ur.jalandhry', 36, 42, 3747, 'اور ان کے لئے ویسی ہی اور چیزیں پیدا کیں جن پر وہ سوار ہوتے ہیں', NULL, NULL, '71e1d28870efa0572ead80fc4d2445e8399e38e0b4b614718ac5d96f6b0ce65a'),
  ('ur.jalandhry', 36, 43, 3748, 'اور اگر ہم چاہیں تو ان کو غرق کردیں۔ پھر نہ تو ان کا کوئی فریاد رس ہوا اور نہ ان کو رہائی ملے', NULL, NULL, 'ad65d11d6e406919a2e18b4371d20c1e35429d852050f5ea1d274d625ff66aa7'),
  ('ur.jalandhry', 36, 44, 3749, 'مگر یہ ہماری رحمت اور ایک مدت تک کے فائدے ہیں', NULL, NULL, 'd2369114e7e78e40942640a38380dbce4456b5e01fa86cb27d2f285ba2465422'),
  ('ur.jalandhry', 36, 45, 3750, 'اور جب ان سے کہا جاتا ہے کہ جو تمہارے آگے اور جو تمہارے پیچھے ہے اس سے ڈرو تاکہ تم پر رحم کیا جائے', NULL, NULL, 'd6626bfb100a4211411cc5343cfa298ff9874153a57f95464e69a4772645cc2d'),
  ('ur.jalandhry', 36, 46, 3751, 'اور ان کے پاس ان کے پروردگار کی کوئی نشانی نہیں آتی مگر اس سے منہ پھیر لیتے ہیں', NULL, NULL, '4336086984f2b77b7434ed8f04935c7ae54a35d1a598a7756f323ed536d81e75'),
  ('ur.jalandhry', 36, 47, 3752, 'اور جب ان سے کہا جاتا ہے کہ جو رزق خدا نے تم کو دیا ہے اس میں سے خرچ کرو۔ تو کافر مومنوں سے کہتے ہیں کہ بھلا ہم ان لوگوں کو کھانا کھلائیں جن کو اگر خدا چاہتا تو خود کھلا دیتا۔ تم تو صریح غلطی میں ہو', NULL, NULL, '11c9b503b1276c6d3ed481b6ac7f6891ee2f7985fcd0fe32648bca952c09c313'),
  ('ur.jalandhry', 36, 48, 3753, 'اور کہتے ہیں اگر تم سچ کہتے ہو تو یہ وعدہ کب (پورا) ہوگا؟', NULL, NULL, '43432ac1aa983df5fb3ee85cc551661f2ce39bfc7350f5127a08d61ab902210a'),
  ('ur.jalandhry', 36, 49, 3754, 'یہ تو ایک چنگھاڑ کے منتظر ہیں جو ان کو اس حال میں کہ باہم جھگڑ رہے ہوں گے آپکڑے گی', NULL, NULL, 'd5f9268febefc3851ac0600527f5336b2b3429985f032e811ce7c5448a1db4e0'),
  ('ur.jalandhry', 36, 50, 3755, 'پھر نہ وصیت کرسکیں گے اور نہ اپنے گھر والوں میں واپس جاسکیں گے', NULL, NULL, '32baa9e1dc6715beed9c2f7152d2c229397703cfd8dde8b94ab85c85aaa28902'),
  ('ur.jalandhry', 36, 51, 3756, 'اور (جس وقت) صور پھونکا جائے گا یہ قبروں سے (نکل کر) اپنے پروردگار کی طرف دوڑ پڑیں گے', NULL, NULL, 'e17233a4c5122b5ddbe4c6871dca35f970b654d25d6c795bb86ab2c40750d779'),
  ('ur.jalandhry', 36, 52, 3757, 'کہیں گے اے ہے ہمیں ہماری خوابگاہوں سے کس نے (جگا) اُٹھایا؟ یہ وہی تو ہے جس کا خدا نے وعدہ کیا تھا اور پیغمبروں نے سچ کہا تھا', NULL, NULL, '92a64baea66a4c423c84b8ebd2bdf7fca6845768599656894d8def21381d1af8'),
  ('ur.jalandhry', 36, 53, 3758, 'صرف ایک زور کی آواز کا ہونا ہوگا کہ سب کے سب ہمارے روبرو آحاضر ہوں گے', NULL, NULL, '314e85177debb4b5f9e26dfe6baa56bc265845799758395d58acdfce1d7c290e'),
  ('ur.jalandhry', 36, 54, 3759, 'اس روز کسی شخص پر کچھ ظلم نہیں کیا جائے گا اور تم کو بدلہ ویسا ہی ملے گا جیسے تم کام کرتے تھے', NULL, NULL, 'c5f64cb1bced032e5476716287804cc8f2fff1aa8bcd71b10151f1630498d839'),
  ('ur.jalandhry', 36, 55, 3760, 'اہل جنت اس روز عیش ونشاط کے مشغلے میں ہوں گے', NULL, NULL, '34ff68ed7914c3823164828ea7c0c2db4692e2b6410ed48d775b309b463afdb5'),
  ('ur.jalandhry', 36, 56, 3761, 'وہ بھی اور ان کی بیویاں بھی سایوں میں تختوں پر تکیے لگائے بیٹھے ہوں گے', NULL, NULL, '7c44bdf128f78e0586234c2aefa82cf9a06f1b71ee35415613e80823aa70bf2e'),
  ('ur.jalandhry', 36, 57, 3762, 'وہاں ان کے لئے میوے اور جو چاہیں گے (موجود ہوگا)', NULL, NULL, 'bdcf7034a27c8acd5497184852fb77c073dd160e424604651a549c2dac7b6977'),
  ('ur.jalandhry', 36, 58, 3763, 'پروردگار مہربان کی طرف سے سلام (کہا جائے گا)', NULL, NULL, '013d0d0cd96a7742c2a4c3e4ede4d9c644af916fc20f1c2b0b486da93fd52b40'),
  ('ur.jalandhry', 36, 59, 3764, 'اور گنہگارو! آج الگ ہوجاؤ', NULL, NULL, 'c00ebfd3446e525902c8c89eff9850079bf7ab27ee9b00b9afa7448114e7cecb'),
  ('ur.jalandhry', 36, 60, 3765, 'اے آدم کی اولاد ہم نے تم سے کہہ نہیں دیا تھا کہ شیطان کو نہ پوجنا وہ تمہارا کھلا دشمن ہے', NULL, NULL, 'd913dbf669768ecf0e820374347a903ec1dc6b84ea77532b48acfadf882d0d72'),
  ('ur.jalandhry', 36, 61, 3766, 'اور یہ کہ میری ہی عبادت کرنا۔ یہی سیدھا رستہ ہے', NULL, NULL, 'c28fc3e0fa0223788b72bb13e1df0f8e5cdc9992cb88122a56acdabdf1a3c83c'),
  ('ur.jalandhry', 36, 62, 3767, 'اور اس نے تم میں سے بہت سی خلقت کو گمراہ کردیا تھا۔ تو کیا تم سمجھتے نہیں تھے؟', NULL, NULL, 'de792df011cb7a3fd5809c53d38ac00a48c1b2b6d0608f229685c9ea67ca19b0'),
  ('ur.jalandhry', 36, 63, 3768, 'یہی وہ جہنم ہے جس کی تمہیں خبر دی جاتی ہے', NULL, NULL, 'b1694f452a2e64b9e484a9b1796b28a4bbb6631ad8b09c5c9ef81660246378cf'),
  ('ur.jalandhry', 36, 64, 3769, '(سو) جو تم کفر کرتے رہے ہو اس کے بدلے آج اس میں داخل ہوجاؤ', NULL, NULL, '3edd1dd7a400aab3c3da51adedeab2c8969626d0dd2930b90b0413828cdc6f12'),
  ('ur.jalandhry', 36, 65, 3770, 'آج ہم ان کے مونہوں پر مہر لگا دیں گے اور جو کچھ یہ کرتے رہے تھے ان کے ہاتھ ہم سے بیان کردیں گے اور ان کے پاؤں (اس کی) گواہی دیں گے', NULL, NULL, '4fc17b5354f793f834bc357ec1b9dfbab10204e4445fe0bf29678c37c0843205'),
  ('ur.jalandhry', 36, 66, 3771, 'اور اگر ہم چاہیں تو ان کی آنکھوں کو مٹا کر (اندھا کر) دیں۔ پھر یہ رستے کو دوڑیں تو کہاں دیکھ سکیں گے', NULL, NULL, '4ded5a6743970efd8c0ce36df52dbc58310fc6162a460fe1783e91d722fb12f1'),
  ('ur.jalandhry', 36, 67, 3772, 'اور اگر ہم چاہیں تو ان کی جگہ پر ان کی صورتیں بدل دیں پھر وہاں سے نہ آگے جاسکیں اور نہ (پیچھے) لوٹ سکیں', NULL, NULL, '9760e7a6cf33137ea61f3569f7ff777a08be2138627b3bef6dc70daedacdd005'),
  ('ur.jalandhry', 36, 68, 3773, 'اور جس کو ہم بڑی عمر دیتے ہیں تو اسے خلقت میں اوندھا کردیتے ہیں تو کیا یہ سمجھتے نہیں؟', NULL, NULL, '41eb904560c131927f0563541c221de6232b199d274c71a71e9dba94e7e7a2c6'),
  ('ur.jalandhry', 36, 69, 3774, 'اور ہم نے ان (پیغمبر) کو شعر گوئی نہیں سکھائی اور نہ وہ ان کو شایاں ہے۔ یہ تو محض نصیحت اور صاف صاف قرآن (پُرازحکمت) ہے', NULL, NULL, 'b3d769777f2fd200f1829812a1d4bc24940c4e5fe4c6374885ae3e5bd103874b'),
  ('ur.jalandhry', 36, 70, 3775, 'تاکہ اس شخص کو جو زندہ ہو ہدایت کا رستہ دکھائے اور کافروں پر بات پوری ہوجائے', NULL, NULL, 'd2c1f061838a1566043dbfc2db53234a250f7f5c1aab04c69aef131c0fad0dfe'),
  ('ur.jalandhry', 36, 71, 3776, 'کیا انہوں نے نہیں دیکھا کہ جو چیزیں ہم نے اپنے ہاتھوں سے بنائیں ان میں سے ہم نے ان کے لئے چارپائے پیدا کر دیئے اور یہ ان کے مالک ہیں', NULL, NULL, '2e015b62c3d18259863ecb95103b216d5c7a72a99c20669a170a778558073b37'),
  ('ur.jalandhry', 36, 72, 3777, 'اور ان کو ان کے قابو میں کردیا تو کوئی تو ان میں سے ان کی سواری ہے اور کسی کو یہ کھاتے ہیں', NULL, NULL, '02c8601f7ee0a347f1613522bbf7dbc45180eab782e13c05ceb52116920ad357'),
  ('ur.jalandhry', 36, 73, 3778, 'اور ان میں ان کے لئے (اور) فائدے اور پینے کی چیزیں ہیں۔ تو یہ شکر کیوں نہیں کرتے؟', NULL, NULL, '687cd8fa69ea2a499d37489f79e475b650583bd833168de79644d9ac057fb34b'),
  ('ur.jalandhry', 36, 74, 3779, 'اور انہوں نے خدا کے سوا (اور) معبود بنا لیے ہیں کہ شاید (ان سے) ان کو مدد پہنچے', NULL, NULL, '0c98b13209148990e122fe33400eb144be6e363f90ae4f735c6b21f4a164748e'),
  ('ur.jalandhry', 36, 75, 3780, '(مگر) وہ ان کی مدد کی (ہرگز) طاقت نہیں رکھتے۔ اور وہ ان کی فوج ہو کر حاضر کیے جائیں گے', NULL, NULL, 'afd8467e1c1be20ecfeea5e4e0b5cc3a50fbb1886e4c475ce371016c6250865b'),
  ('ur.jalandhry', 36, 76, 3781, 'تو ان کی باتیں تمہیں غمناک نہ کردیں۔ یہ جو کچھ چھپاتے اور جو کچھ ظاہر کرتے ہیں ہمیں سب معلوم ہے', NULL, NULL, '2de8ef568ee7c8b3c8a782d730c9c28d02b544a3674699337c497063a8428c9a'),
  ('ur.jalandhry', 36, 77, 3782, 'کیا انسان نے نہیں دیکھا کہ ہم نے اس کو نطفے سے پیدا کیا۔ پھر وہ تڑاق پڑاق جھگڑنے لگا', NULL, NULL, '9f6f56ccf25e6abd0cc5efb4ae12f59a56f93a57ae9b3eed312e075782af7f53'),
  ('ur.jalandhry', 36, 78, 3783, 'اور ہمارے بارے میں مثالیں بیان کرنے لگا اور اپنی پیدائش کو بھول گیا۔ کہنے لگا کہ (جب) ہڈیاں بوسیدہ ہوجائیں گی تو ان کو کون زندہ کرے گا؟', NULL, NULL, 'bf830dac77b6a680983a0505c1d177ff6ffb3f2d026b96d99b4132eb2b594632'),
  ('ur.jalandhry', 36, 79, 3784, 'کہہ دو کہ ان کو وہ زندہ کرے گا جس نے ان کو پہلی بار پیدا کیا تھا۔ اور وہ سب قسم کا پیدا کرنا جانتا ہے', NULL, NULL, '93e2441815ab79283487c1154eb6f6295f824adffe5e8540e348cdef489d4833'),
  ('ur.jalandhry', 36, 80, 3785, 'جس نے تمہارے لئے سبز درخت سے آگ پیدا کی پھر تم اس (کی ٹہنیوں کو رگڑ کر ان) سے آگ نکالتے ہو', NULL, NULL, 'cad3923c3cb84dd3fc317300e609a66301183193441fc447f91500200d308e6d'),
  ('ur.jalandhry', 36, 81, 3786, 'بھلا جس نے آسمانوں اور زمین کو پیدا کیا، کیا وہ اس بات پر قادر نہیں کہ (ان کو پھر) ویسے ہی پیدا کر دے۔ کیوں نہیں۔ اور وہ تو بڑا پیدا کرنے والا اور علم والا ہے', NULL, NULL, '77e26661e07d51b16b7436e2933616126b096d17f38cfd02ae4c566bbf8926f7'),
  ('ur.jalandhry', 36, 82, 3787, 'اس کی شان یہ ہے کہ جب وہ کسی چیز کا ارادہ کرتا ہے تو اس سے فرما دیتا ہے کہ ہوجا تو وہ ہوجاتی ہے', NULL, NULL, '4a677a1c361b4a388c6bf68743e05fe1f85fd44a93262e6ab7272ce97ec419a8'),
  ('ur.jalandhry', 36, 83, 3788, 'وہ (ذات) پاک ہے جس کے ہاتھ میں ہر چیز کی بادشاہت ہے اور اسی کی طرف تم کو لوٹ کر جانا ہے', NULL, NULL, '3be1e84f065ffbf42e2bb9bc74ac68b9db5fb6ffcc72489ccc1f60c9407e2aa7'),
  ('ur.jalandhry', 37, 1, 3789, 'قسم ہے صف باندھنے والوں کی پرا جما کر', NULL, NULL, 'c710ca32dbf911fd0338628760c9661271392913ee97865e0eeb7c52a26be595'),
  ('ur.jalandhry', 37, 2, 3790, 'پھر ڈانٹنے والوں کی جھڑک کر', NULL, NULL, 'c329f0f7cf00e02c0e12e92b8cdc6375b44cae8676878ff6397351c09b15ecaa'),
  ('ur.jalandhry', 37, 3, 3791, 'پھر ذکر (یعنی قرآن) پڑھنے والوں کی (غور کرکر)', NULL, NULL, 'af6c7dd26b9f4f5d0c3a00edf489676798f391cfe9b8c93be8084025c5f3b65f'),
  ('ur.jalandhry', 37, 4, 3792, 'کہ تمہارا معبود ایک ہے', NULL, NULL, 'b254ad9b5e0b67590885bb4a2583dc25d6ff4e4bfee341471ec9970963caa9bb'),
  ('ur.jalandhry', 37, 5, 3793, 'جو آسمانوں اور زمین اور جو چیزیں ان میں ہیں سب کا مالک ہے اور سورج کے طلوع ہونے کے مقامات کا بھی مالک ہے', NULL, NULL, '915a994ac99dc793bbdeb4e55a8a8b182f5035930f8f061ef2a823ca0568b9fb'),
  ('ur.jalandhry', 37, 6, 3794, 'بےشک ہم ہی نے آسمان دنیا کو ستاروں کی زینت سے مزین کیا', NULL, NULL, '8c2c862a09aad99719c23d05b057a51b1e343032fec8a7db9d2bc8b79c607de7'),
  ('ur.jalandhry', 37, 7, 3795, 'اور ہر شیطان سرکش سے اس کی حفاظت کی', NULL, NULL, '332cbcac44a676882c4e849ce2df0f2f5b6014198d029bbc7270523692c8f164'),
  ('ur.jalandhry', 37, 8, 3796, 'کہ اوپر کی مجلس کی طرف کان نہ لگاسکیں اور ہر طرف سے (ان پر انگارے) پھینکے جاتے ہیں', NULL, NULL, 'c49a65fd9e434933460d23a3e1ee63a259a70081ddb26a7181a6b0660f9b08d7'),
  ('ur.jalandhry', 37, 9, 3797, '(یعنی وہاں سے) نکال دینے کو اور ان کے لئے دائمی عذاب ہے', NULL, NULL, 'dc834ac361341483a9b1c5437851b534fdfcda3d71a0ce4a0ef6395710ebc5e8'),
  ('ur.jalandhry', 37, 10, 3798, 'ہاں جو کوئی (فرشتوں کی کسی بات کو) چوری سے جھپٹ لینا چاہتا ہے تو جلتا ہوا انگارہ ان کے پیچھے لگتا ہے', NULL, NULL, '6adc57636d1d0d6c88aa26bebd255ba0979b79d84cc3734ef1c233740ab1fe17'),
  ('ur.jalandhry', 37, 11, 3799, 'تو ان سے پوچھو کہ ان کا بنانا مشکل ہے یا جتنی خلقت ہم نے بنائی ہے؟ انہیں ہم نے چپکتے گارے سے بنایا ہے', NULL, NULL, 'fb68f5f2b093037e40c263492aa1352ab38ce754b1e5de86c63452fc837e135e'),
  ('ur.jalandhry', 37, 12, 3800, 'ہاں تم تو تعجب کرتے ہو اور یہ تمسخر کرتے ہیں', NULL, NULL, '1dbd3b9cb5d620cb30b2778ac7687293c197f5855a3934b1f4fe65acaa1ad859')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
