INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 37, 13, 3801, 'اور جب ان کو نصیحت دی جاتی ہے تو نصیحت قبول نہیں کرتے', NULL, NULL, '2442c5929a4b9baaa3e88e7ffe26b247d30ff718572e8b3c7b0022d6639c742a'),
  ('ur.jalandhry', 37, 14, 3802, 'اور جب کوئی نشانی دیکھتے ہیں تو ٹھٹھے کرتے ہیں', NULL, NULL, 'd614ffa00a982b0ca312fd8958ffb9728b08bbaa6ac61c52374a443257ab3228'),
  ('ur.jalandhry', 37, 15, 3803, 'اور کہتے ہیں کہ یہ تو صریح جادو ہے', NULL, NULL, '54376860cae477ab0abcd1920f29e1a7873963c14a95e8118469689f84126d8e'),
  ('ur.jalandhry', 37, 16, 3804, 'بھلا جب ہم مرگئے اور مٹی اور ہڈیاں ہوگئے تو کیا پھر اٹھائے جائیں گے؟', NULL, NULL, 'c91aaa05abb20b62260ae50332490a45bc9d6b77d3e7483a2d9b747aba7ec943'),
  ('ur.jalandhry', 37, 17, 3805, 'اور کیا ہمارے باپ دادا بھی (جو) پہلے (ہو گزرے ہیں)', NULL, NULL, '0fc74e4e439202b8df9cd92112f25c270b37bdfb037a62acf80f090092f5d88d'),
  ('ur.jalandhry', 37, 18, 3806, 'کہہ دو کہ ہاں اور تم ذلیل ہوگے', NULL, NULL, 'b7fe983d18e89f4fb18d46efb3190a52a7946f40f0272059d674a43afefe7161'),
