  ('ur.jalandhry', 37, 89, 3877, 'اور کہا میں تو بیمار ہوں', NULL, NULL, 'bccc1899730220f51b578eae78050322fe17cd58105e3de034f676f6a60b8342'),
  ('ur.jalandhry', 37, 90, 3878, 'تب وہ ان سے پیٹھ پھیر کر لوٹ گئے', NULL, NULL, '57b36458160debf9a142d3abb6bc8bd6d882e2cd48cdd16f42935bd08416eed2'),
  ('ur.jalandhry', 37, 91, 3879, 'پھر ابراہیم ان کے معبودوں کی طرف متوجہ ہوئے اور کہنے لگے کہ تم کھاتے کیوں نہیں؟', NULL, NULL, 'c04cf7d5708cc9d8d752ef510ad8a718eab8e82d873a765445fabd1d1f4dc5b2'),
  ('ur.jalandhry', 37, 92, 3880, 'تمہیں کیا ہوا ہے تم بولتے نہیں؟', NULL, NULL, 'f2004b78b27c65ef91752467b910907569886162aa416cf342b394911d6ed5f3'),
  ('ur.jalandhry', 37, 93, 3881, 'پھر ان کو داہنے ہاتھ سے مارنا (اور توڑنا) شروع کیا', NULL, NULL, 'f4978a2f7113f5c42af1768e31afd117f340c77fef140c10f28188785a46c1ce'),
  ('ur.jalandhry', 37, 94, 3882, 'تو وہ لوگ ان کے پاس دوڑے ہوئے آئے', NULL, NULL, '7865ed6be1a98c8d3f25d7023e897a89f42ad5b0f09ba5211925e8487c089aed'),
  ('ur.jalandhry', 37, 95, 3883, 'انہوں نے کہا کہ تم ایسی چیزوں کو کیوں پوجتے ہو جن کو خود تراشتے ہو؟', NULL, NULL, 'd4166c19805d059cfb2e063a66fba8afa32543476f64737207342c32cc5530bf'),
  ('ur.jalandhry', 37, 96, 3884, 'حالانکہ تم کو اور جو تم بناتے ہو اس کو خدا ہی نے پیدا کیا ہے', NULL, NULL, '6ef2609a0881be6891e070b00f33107b95b93306263b4bc757545787cfd95b34'),
  ('ur.jalandhry', 37, 97, 3885, 'وہ کہنے لگے کہ اس کے لئے ایک عمارت بناؤ پھر اس کو آگ کے ڈھیر میں ڈال دو', NULL, NULL, 'c547b8e477943c23e26bf72f9cb384fc550ea1f2f8bd0ecda695c9e9881bea0d'),
  ('ur.jalandhry', 37, 98, 3886, 'غرض انہوں نے ان کے ساتھ ایک چال چلنی چاہی اور ہم نے ان ہی کو زیر کردیا', NULL, NULL, '71afe1f5d62292f47c6ed695ab87f6011fc7e95723c52904692f5a087a004c8b'),
  ('ur.jalandhry', 37, 99, 3887, 'اور ابراہیم بولے کہ میں اپنے پروردگار کی طرف جانے والا ہوں وہ مجھے رستہ دکھائے گا', NULL, NULL, 'd46c38900e0c057044c82f57a6de33b480a0e67518c724c15bc8cdb6825c650c'),
  ('ur.jalandhry', 37, 100, 3888, 'اے پروردگار مجھے (اولاد) عطا فرما (جو) سعادت مندوں میں سے (ہو)', NULL, NULL, '94796d47da69addaccf352879cb615621b6ca09d3bf57411e25cd6d208bfd872'),
  ('ur.jalandhry', 37, 101, 3889, 'تو ہم نے ان کو ایک نرم دل لڑکے کی خوشخبری دی', NULL, NULL, '09e3e7afb2251e6576293fcf4eeddeb5f2499de4f02272a8cbd7a277e050eeb5'),
  ('ur.jalandhry', 37, 102, 3890, 'جب وہ ان کے ساتھ دوڑنے (کی عمر) کو پہنچا تو ابراہیم نے کہا کہ بیٹا میں خواب میں دیکھتا ہوں کہ (گویا) تم کو ذبح کر رہا ہوں تو تم سوچو کہ تمہارا کیا خیال ہے؟ انہوں نے کہا کہ ابا جو آپ کو حکم ہوا ہے وہی کیجیئے خدا نے چاہا تو آپ مجھے صابروں میں پایئے گا', NULL, NULL, 'ea0ca811b98bc7da86313ee9ec5e9c2850cb4931bb717bf1980200823bf25e97'),
  ('ur.jalandhry', 37, 103, 3891, 'جب دونوں نے حکم مان لیا اور باپ نے بیٹے کو ماتھے کے بل لٹا دیا', NULL, NULL, '11cbc2edbf7468b67b9fcabf0cc44ea0205140733c307b55d27ccc41d5c897a0'),
  ('ur.jalandhry', 37, 104, 3892, 'تو ہم نے ان کو پکارا کہ اے ابراہیم', NULL, NULL, 'f045d1eb360bb90f314dec9e339ec3b244f0a6cfb0e8a6f2d4b4eec6275e1bf4'),
  ('ur.jalandhry', 37, 105, 3893, 'تم نے خواب کو سچا کر دکھایا۔ ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں', NULL, NULL, '13b09177e9c4c24d432a70048adafbc58dc481e20c1732392c70f16e1f73c0d4'),
  ('ur.jalandhry', 37, 106, 3894, 'بلاشبہ یہ صریح آزمائش تھی', NULL, NULL, '124037b0ccd0dc2e64cb8db53a74cec36f47ed521fa51a0d0507ed94ece6cade'),
  ('ur.jalandhry', 37, 107, 3895, 'اور ہم نے ایک بڑی قربانی کو ان کا فدیہ دیا', NULL, NULL, '7e05bc5c9cdf74dce4ed9b3819894870e5f80d8b0037db30ce2e09832d7f3067'),
  ('ur.jalandhry', 37, 108, 3896, 'اور پیچھے آنے والوں میں ابراہیم کا (ذکر خیر باقی) چھوڑ دیا', NULL, NULL, '3cfaafadb732ac9c75523b82e72116ea979dca16f6c88439da541ec93a1ca5fe'),
  ('ur.jalandhry', 37, 109, 3897, 'کہ ابراہیم پر سلام ہو', NULL, NULL, '24649cc163fd6d857d29afc6b29bb1f14d97c34e8429769a47ff8171c9ebaea3'),
  ('ur.jalandhry', 37, 110, 3898, 'نیکوکاروں کو ہم ایسا ہی بدلہ دیا کرتے ہیں', NULL, NULL, '78cda9a9d1c1b84f31ef030085f88ed8618d55160ecba5761d5eadf8260b35aa'),
  ('ur.jalandhry', 37, 111, 3899, 'وہ ہمارے مومن بندوں میں سے تھے', NULL, NULL, '0162349c017ea798e195836c4d63328ad45e7bcba73c6a72666923aecf6dde07'),
  ('ur.jalandhry', 37, 112, 3900, 'اور ہم نے ان کو اسحاق کی بشارت بھی دی (کہ وہ) نبی (اور) نیکوکاروں میں سے (ہوں گے)', NULL, NULL, '5531bb45a7c7dec87b9b35fabc7861fd5a102dbc6b631d8169f46396f4527885')
