INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 37, 113, 3901, 'اور ہم نے ان پر اور اسحاق پر برکتیں نازل کی تھیں۔ اور ان دونوں اولاد کی میں سے نیکوکار بھی ہیں اور اپنے آپ پر صریح ظلم کرنے والے (یعنی گنہگار) بھی ہیں', NULL, NULL, '8b759318dcd26f36074c0140fe76136f1c385e74aab2dd510d319a8a651143ed'),
  ('ur.jalandhry', 37, 114, 3902, 'اور ہم نے موسیٰ اور ہارون پر بھی احسان کئے', NULL, NULL, '96625175a10dabe603087dbb9bab5758a2ff4c415b2f7ca02689ad47af644174'),
  ('ur.jalandhry', 37, 115, 3903, 'اور ان کو اور ان کی قوم کو مصیبت عظیمہ سے نجات بخشی', NULL, NULL, '3861dabc02f141920f1f861d914102abf10159d796e36cdf224209b657dbe4e1'),
  ('ur.jalandhry', 37, 116, 3904, 'اور ان کی مدد کی تو وہ غالب ہوگئے', NULL, NULL, '9307591bcea7c278a1458a80b59542936a9eb2ec53148d56f734dadb9e6848b5'),
  ('ur.jalandhry', 37, 117, 3905, 'اور ان دونوں کو کتاب واضح (المطالب) عنایت کی', NULL, NULL, '1d26fbd1de84047df12529d6a6b2ed8e75b93fd02d435c2731b67cf0adc03e75'),
  ('ur.jalandhry', 37, 118, 3906, 'اور ان کو سیدھا رستہ دکھایا', NULL, NULL, '1608401fd514716b84faa60072d796ac5aadee47504d6c6afc04cc3286413359'),
  ('ur.jalandhry', 37, 119, 3907, 'اور پیچھے آنے والوں میں ان کا ذکر (خیر باقی) چھوڑ دیا', NULL, NULL, 'ac35cc93470c0faa1e41d59fb44e59bfbffee2e2d484dc71b9a6ebde546dad8c'),
  ('ur.jalandhry', 37, 120, 3908, 'کہ موسیٰ اور ہارون پر سلام', NULL, NULL, 'b6650f5e88a1efaa63a58c9e46cbac96eefabb0e0efe340e6f8740c28f874d06'),
  ('ur.jalandhry', 37, 121, 3909, 'بےشک ہم نیکوکاروں کو ایسا ہی بدلہ دیا کرتے ہیں', NULL, NULL, 'fec2b6565ebf131ebd8e6199a1d79d5b44389dc98bc519c5f4f4668a6dccfa14'),
  ('ur.jalandhry', 37, 122, 3910, 'وہ دونوں ہمارے مومن بندوں میں سے تھے', NULL, NULL, 'b2838b5be07619753d98b48df3ca929de050d336daa6945fe593fe369ff23457'),
  ('ur.jalandhry', 37, 123, 3911, 'اور الیاس بھی پیغمبروں میں سے تھے', NULL, NULL, '640c287206a522718d9c2eca0550c5ba573f904504d744979f638eaea2d53a7b'),
  ('ur.jalandhry', 37, 124, 3912, 'جب انہوں نے اپنی قوم سے کہا کہ تم ڈرتے کیوں نہیں؟', NULL, NULL, '4e387f120e15e83a1330fe5767b765a9de9168c8e2287180571f6c44f913b274'),
  ('ur.jalandhry', 37, 125, 3913, 'کیا تم بعل کو پکارتے (اور اسے پوجتے) ہو اور سب سے بہتر پیدا کرنے والے کو چھوڑ دیتے ہو', NULL, NULL, '46b95c0bc1c8745dccd6883d2a0e1e8306717a084675df2f49b967ec307e199f'),
  ('ur.jalandhry', 37, 126, 3914, '(یعنی) خدا کو جو تمہارا اور تمہارے اگلے باپ دادا کا پروردگار ہے', NULL, NULL, '2eddf0d833ea179da8757bff44f558414fd1f6966680bf42869077cb0385b468'),
  ('ur.jalandhry', 37, 127, 3915, 'تو ان لوگوں نے ان کو جھٹلا دیا۔ سو وہ (دوزخ میں) حاضر کئے جائیں گے', NULL, NULL, '3a6ce377f7ae3c9c0752f12461e313d646c851e12bee2303d288a5b625404e61'),
  ('ur.jalandhry', 37, 128, 3916, 'ہاں خدا کے بندگان خاص (مبتلائے عذاب نہیں) ہوں گے', NULL, NULL, 'e19d267a0e5dea3885eca3feabe2dec9fe70816733939b6753692e1fc36c8d29'),
  ('ur.jalandhry', 37, 129, 3917, 'اور ان کا ذکر (خیر) پچھلوں میں (باقی) چھوڑ دیا', NULL, NULL, 'c9d35a0a2ad358f40e24e58aa08b37aac31fcaa2bdbcedb12c56700004a7bea1'),
  ('ur.jalandhry', 37, 130, 3918, 'کہ اِل یاسین پر سلام', NULL, NULL, '5604adbcf7291addce36b13cc2205bf90e614adf24ce3773881dbd8afe9ed896'),
  ('ur.jalandhry', 37, 131, 3919, 'ہم نیک لوگوں کو ایسا ہی بدلہ دیتے ہیں', NULL, NULL, '338d27d20868b2efed6256d9356946cf0cff8b13a1bf63b9ac1b94a0c106ee7c'),
  ('ur.jalandhry', 37, 132, 3920, 'بےشک وہ ہمارے مومن بندوں میں سے تھے', NULL, NULL, '05f77c637cdb72af22d2570ff16d12e42039c62715b7d7bed4189f288252b08f'),
  ('ur.jalandhry', 37, 133, 3921, 'اور لوط بھی پیغمبروں میں سے تھے', NULL, NULL, 'cadd8fd62b9e03db77cf42560d65157b4af143d193240ec72e9231cfdb1dad44'),
  ('ur.jalandhry', 37, 134, 3922, 'جب ہم نے ان کو اور ان کے گھر والوں کو سب کو (عذاب سے) نجات دی', NULL, NULL, 'c7d77092f5ee273844eef2dfb4fc8601b43446acbf4cb91768037ebc4e6018c2'),
  ('ur.jalandhry', 37, 135, 3923, 'مگر ایک بڑھیا کہ پیچھے رہ جانے والوں میں تھی', NULL, NULL, '9c567d9cd786975869b0164b8fc9e4aae032796c297640d58e57c37a92458a22'),
  ('ur.jalandhry', 37, 136, 3924, 'پھر ہم نے اوروں کو ہلاک کردیا', NULL, NULL, 'd305ec1d0a33809b23272ae393920872c8287c73f3bc6829f87eecaf7da2df2b'),
  ('ur.jalandhry', 37, 137, 3925, 'اور تم دن کو بھی ان (کی بستیوں) کے پاس سے گزرتے رہتے ہو', NULL, NULL, 'b5c22dda9b2a19839610d5660415909256698e3b07212229ff63b15bed1112bb'),
  ('ur.jalandhry', 37, 138, 3926, 'اور رات کو بھی۔ تو کیا تم عقل نہیں رکھتے', NULL, NULL, '3e46bea82d5e0e64363429fbc6e3ad2ece463f3759713c8c1050383128301a63'),
  ('ur.jalandhry', 37, 139, 3927, 'اور یونس بھی پیغمبروں میں سے تھے', NULL, NULL, '22ecd51c3a47167958db94dc31052a99ec1f8795e1515f133955689ad8fee7b1'),
  ('ur.jalandhry', 37, 140, 3928, 'جب بھاگ کر بھری ہوئی کشتی میں پہنچے', NULL, NULL, '47f130290baff87fb45a1b6e7be782ee2d9e6e9539bd5a811d917d62b0569c97'),
  ('ur.jalandhry', 37, 141, 3929, 'اس وقت قرعہ ڈالا تو انہوں نے زک اُٹھائی', NULL, NULL, '8ac35376f82bbc264cac88fcb4333a0d6b62f631133c7f11a77416694cf0d7d7'),
  ('ur.jalandhry', 37, 142, 3930, 'پھر مچھلی نے ان کو نگل لیا اور وہ (قابل) ملامت (کام) کرنے والے تھے', NULL, NULL, '0da3614287fe886b393506acd8ad87bc11602d2b62cc02205093eabab83bebe6'),
  ('ur.jalandhry', 37, 143, 3931, 'پھر اگر وہ (خدا کی) پاکی بیان نہ کرتے', NULL, NULL, '5c2892ead049d9d097617410a2b3262553ee926947b863eb56454987a2a69063'),
  ('ur.jalandhry', 37, 144, 3932, 'تو اس روز تک کہ لوگ دوبارہ زندہ کئے جائیں گے اسی کے پیٹ میں رہتے', NULL, NULL, '20982ab28e294fcd57e4ad933c6d14f0de1fa10feafb814b2744266c545daa30'),
  ('ur.jalandhry', 37, 145, 3933, 'پھر ہم نے ان کو جب کہ وہ بیمار تھے فراخ میدان میں ڈال دیا', NULL, NULL, 'ec4102a4c07819913ef34ae7df5eb2360aba4bc40a02c95f008d363990f0dc70'),
  ('ur.jalandhry', 37, 146, 3934, 'اور ان پر کدو کا درخت اُگایا', NULL, NULL, 'c0f48a8e8a6779d87f971dc924d1bfcfde05cdd38ede6822ef1ec568c84ec5d6'),
  ('ur.jalandhry', 37, 147, 3935, 'اور ان کو لاکھ یا اس سے زیادہ (لوگوں) کی طرف (پیغمبر بنا کر) بھیجا', NULL, NULL, '7bb3c88ae4fac1b9959a80b8cc38b4a0161f185051f20dd28df346e8f9043d75'),
  ('ur.jalandhry', 37, 148, 3936, 'تو وہ ایمان لے آئے سو ہم نے بھی ان کو (دنیا میں) ایک وقت (مقرر) تک فائدے دیتے رہے', NULL, NULL, 'ff079c5d1df1056bcff9003d749cada76b8f04077862a022f3aadba15bc9e1b3'),
  ('ur.jalandhry', 37, 149, 3937, 'ان سے پوچھو تو کہ بھلا تمہارے پروردگار کے لئے تو بیٹیاں اور ان کے لئے بیٹے', NULL, NULL, '7b418f92a6c63d13c2a356749555f441b071250788ea9cda5719d30265ca0713'),
  ('ur.jalandhry', 37, 150, 3938, 'یا ہم نے فرشتوں کو عورتیں بنایا اور وہ (اس وقت) موجود تھے', NULL, NULL, 'c0425b7717cf1a12ded258326bac250241a9cc3c61bfae5252b449c2e07bb400'),
  ('ur.jalandhry', 37, 151, 3939, 'دیکھو یہ اپنی جھوٹ بنائی ہوئی (بات) کہتے ہیں', NULL, NULL, 'd43fbf8d9814bdb4b1749e5e27510a4feee10caa428831ddabc31a2fcbf5506b'),
  ('ur.jalandhry', 37, 152, 3940, 'کہ خدا کے اولاد ہے کچھ شک نہیں کہ یہ جھوٹے ہیں', NULL, NULL, '665032d366b157c8de52aad9dbef3b7d5100f15969a13d2168366ffe38f6d6f1'),
  ('ur.jalandhry', 37, 153, 3941, 'کیا اس نے بیٹوں کی نسبت بیٹیوں کو پسند کیا ہے؟', NULL, NULL, 'bfab4c81dc52f99725ba507b9c5d67259c7fdc19a549abddf3c4e483d7e1907c'),
  ('ur.jalandhry', 37, 154, 3942, 'تم کیسے لوگ ہو، کس طرح کا فیصلہ کرتے ہو', NULL, NULL, 'd52434985d7be39a220f3f06e26c23808f5dd124e7408f66c5309940ebcb5e97'),
  ('ur.jalandhry', 37, 155, 3943, 'بھلا تم غور کیوں نہیں کرتے', NULL, NULL, '288489db0c1b4df17164b079bb52609e297bd87d6529c266e76d7274bb22f351'),
