  ('ur.jalandhry', 38, 17, 3987, '(اے پیغمبر) یہ جو کچھ کہتے ہیں اس پر صبر کرو۔ اور ہمارے بندے داؤد کو یاد کرو جو صاحب قوت تھے (اور) بےشک وہ رجوع کرنے والے تھے', NULL, NULL, 'bfa275496ad296eacc0fab5982b977b165ff45b68ec04e754bc3c0ccac0b23a5'),
  ('ur.jalandhry', 38, 18, 3988, 'ہم نے پہاڑوں کو ان کے زیر فرمان کردیا تھا کہ صبح وشام ان کے ساتھ (خدائے) پاک (کا) ذکر کرتے تھے', NULL, NULL, 'bccec5faea839ff68564f294aa85c3f4be71811d3700e4cfac966800045c75f3'),
  ('ur.jalandhry', 38, 19, 3989, 'اور پرندوں کو بھی کہ جمع رہتے تھے۔ سب ان کے فرمانبردار تھے', NULL, NULL, '57e2724bb03992150ae872a74608a3e76d23e5fbe12e410e5fbfc7630bfd56c3'),
  ('ur.jalandhry', 38, 20, 3990, 'اور ہم نے ان کی بادشاہی کو مستحکم کیا اور ان کو حکمت عطا کی اور (خصومت کی) بات کا فیصلہ (سکھایا)', NULL, NULL, 'a35e43a6263bd12a4534da9b6aed506417c1c07088d5a5586a3b1e30645bcea2'),
  ('ur.jalandhry', 38, 21, 3991, 'بھلا تمہارے پاس ان جھگڑنے والوں کی بھی خبر آئی ہے جب وہ دیوار پھاند کر عبادت خانے میں داخل ہوئے', NULL, NULL, '213b2ff34a756f3b8810b33f1560b26fd920558f6013f4c4f01432c56383d5dd'),
  ('ur.jalandhry', 38, 22, 3992, 'جس وقت وہ داؤد کے پاس آئے تو وہ ان سے گھبرا گئے انہوں نے کہا کہ خوف نہ کیجیئے۔ ہم دونوں کا ایک مقدمہ ہے کہ ہم میں سے ایک نے دوسرے پر زیادتی کی ہے تو آپ ہم میں انصاف کا فیصلہ کر دیجیئے اور بےانصافی نہ کیجیئے گا اور ہم کو سیدھا رستہ دکھا دیجیئے', NULL, NULL, 'b19753c350db3ab86d8230b25adc35a673ddb7b4daae14f2ae5a8db323670da8'),
  ('ur.jalandhry', 38, 23, 3993, '(کیفیت یہ ہے کہ) یہ میرا بھائی ہے اس کے (ہاں) ننانوے دنبیاں ہیں اور میرے (پاس) ایک دُنبی ہے۔ یہ کہتا ہے کہ یہ بھی میرے حوالے کردے اور گفتگو میں مجھ پر زبردستی کرتا ہے', NULL, NULL, 'd46fa03f567e00c72d2b96b9e8ac9a23e8c33317bf2cc5378ef8c8e84ecbf86e'),
  ('ur.jalandhry', 38, 24, 3994, 'انہوں نے کہا کہ یہ جو تیری دنبی مانگتا ہے کہ اپنی دنبیوں میں ملالے بےشک تجھ پر ظلم کرتا ہے۔ اور اکثر شریک ایک دوسرے پر زیادتی ہی کیا کرتے ہیں۔ ہاں جو ایمان لائے اور عمل نیک کرتے رہے اور ایسے لوگ بہت کم ہیں۔ اور داؤد نے خیال کیا کہ (اس واقعے سے) ہم نے ان کو آزمایا ہے تو انہوں نے اپنے پروردگار سے مغفرت مانگی اور جھک کر گڑ پڑے اور (خدا کی طرف) رجوع کیا', NULL, NULL, 'a0103383d1683b5d32b20039df34fe47f1f17ce89fd0d49e39cd3ee34a2ea6b7'),
  ('ur.jalandhry', 38, 25, 3995, 'تو ہم نے ان کو بخش دیا۔ اور بےشک ان کے لئے ہمارے ہاں قرب اور عمدہ مقام ہے', NULL, NULL, '7bc2afecac6f9cd8b5608f79dbd20f7553918bc731cf7fd6c1689e3d8457f9df'),
