    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 38, 31, 4001, 'جب ان کے سامنے شام کو خاصے کے گھوڑے پیش کئے گئے', NULL, NULL, 'ad432a5cc52d2b7c4d54b160e4ffbedbe7b9c98c733a9e57032ee05d9ed249aa'),
  ('ur.jalandhry', 38, 32, 4002, 'تو کہنے لگے کہ میں نے اپنے پروردگار کی یاد سے (غافل ہو کر) مال کی محبت اختیار کی۔ یہاں تک کہ (آفتاب) پردے میں چھپ گیا', NULL, NULL, 'a49c2a3168a083b03f691458e9dccc98c191f6a19ddc39b39c33646902e4ced4'),
  ('ur.jalandhry', 38, 33, 4003, '(بولے کہ) ان کو میرے پاس واپس لے آؤ۔ پھر ان کی ٹانگوں اور گردنوں پر ہاتھ پھیرنے لگے', NULL, NULL, '239e353fa39e279ee585b6bc21d323fda1ed3f77bef3fb693ed2be17f271f9e5'),
  ('ur.jalandhry', 38, 34, 4004, 'اور ہم نے سلیمان کی آزمائش کی اور ان کے تخت پر ایک دھڑ ڈال دیا پھر انہوں نے (خدا کی طرف) رجوع کیا', NULL, NULL, 'bd974c02cb34b23679194605bad8e720c4adfecadd9a04f6fa11cc281b6ef352'),
  ('ur.jalandhry', 38, 35, 4005, '(اور) دعا کی کہ اے پروردگار مجھے مغفرت کر اور مجھ کو ایسی بادشاہی عطا کر کہ میرے بعد کسی کو شایاں نہ ہو۔ بےشک تو بڑا عطا فرمانے والا ہے', NULL, NULL, '9139452ce664878d737f8b2d5a14c3cb10dd4863c961ea294f8bf28b03249c62'),
  ('ur.jalandhry', 38, 36, 4006, 'پھر ہم نے ہوا کو ان کے زیرفرمان کردیا کہ جہاں وہ پہنچنا چاہتے ان کے حکم سے نرم نرم چلنے لگتی', NULL, NULL, '672adb3aa8f94c5c0e4114acefe64604127111a1c36a404934f38417b923aaf7'),
  ('ur.jalandhry', 38, 37, 4007, 'اَور دیووں کو بھی (ان کے زیرفرمان کیا) وہ سب عمارتیں بنانے والے اور غوطہ مارنے والے تھے', NULL, NULL, 'e1df2a7df08a0b670d56779e665e79d402a4d21dab1da96802cb55c3c6da7b5f'),
  ('ur.jalandhry', 38, 38, 4008, 'اور اَوروں کو بھی جو زنجیروں میں جکڑے ہوئے تھے', NULL, NULL, '1c8939064975a44f70b63c09108eb60be755410be9be1833ebae76a63a902e8a'),
  ('ur.jalandhry', 38, 39, 4009, '(ہم نے کہا) یہ ہماری بخشش ہے (چاہو) تو احسان کرو یا (چاہو تو) رکھ چھوڑو (تم سے) کچھ حساب نہیں ہے', NULL, NULL, '9fc044899fb89ea5435f0a5da1e800053652f7e0e6159649a1dfb7126d26067a'),
  ('ur.jalandhry', 38, 40, 4010, 'اور بےشک ان کے لئے ہمارے ہاں قُرب اور عمدہ مقام ہے', NULL, NULL, '7250679eb9557d521e627f65e67e28d82f1cc2f5b874766083133ac036a627d4'),
  ('ur.jalandhry', 38, 41, 4011, 'اور ہمارے بندے ایوب کو یاد کرو جب انہوں نے اپنے رب کو پکارا کہ (بار الہٰا) شیطان نے مجھ کو ایذا اور تکلیف دے رکھی ہے', NULL, NULL, '724eb1d13aa97f0ed22f75981b4ab9f753f35b8facd61df48e99e714ecfdd753'),
  ('ur.jalandhry', 38, 42, 4012, '(ہم نے کہا کہ زمین پر) لات مارو (دیکھو) یہ (چشمہ نکل آیا) نہانے کو ٹھنڈا اور پینے کو (شیریں)', NULL, NULL, '5bae902537dd86414748bbf8bf8911743eb2fc5749b87b359b203699928d9f79'),
  ('ur.jalandhry', 38, 43, 4013, 'اور ہم نے ان کو اہل و عیال اور ان کے ساتھ ان کے برابر اور بخشے۔ (یہ) ہماری طرف سے رحمت اور عقل والوں کے لئے نصیحت تھی', NULL, NULL, '2b716692c68afc67971d58a09a89d1d23cb07cbc18d04112fde43aeaae38568d'),
  ('ur.jalandhry', 38, 44, 4014, 'اور اپنے ہاتھ میں جھاڑو لو اور اس سے مارو اور قسم نہ توڑو۔ بےشک ہم نے ان کو ثابت قدم پایا۔ بہت خوب بندے تھے بےشک وہ رجوع کرنے والے تھے', NULL, NULL, 'ab776e2676e09d18b13226b1a481f75ec9ebd61cc5ca538014e85e5e5abdf2fd'),
  ('ur.jalandhry', 38, 45, 4015, 'اور ہمارے بندوں ابراہیم اور اسحاق اور یعقوب کو یاد کرو جو ہاتھوں والے اور آنکھوں والے تھے', NULL, NULL, '20c6ee1b8ec7fa93561d79eaee4ef4d7f7805320d9a87207bf38a2c0d5fb9fd6'),
  ('ur.jalandhry', 38, 46, 4016, 'ہم نے ان کو ایک (صفت) خاص (آخرت کے) گھر کی یاد سے ممتاز کیا تھا', NULL, NULL, 'd20e368e562fb503006bbda975b54d9fa41fb9e3655efee3d914e85c82f81bfb'),
  ('ur.jalandhry', 38, 47, 4017, 'اور ہمارے نزدیک منتخب اور نیک لوگوں میں سے تھے', NULL, NULL, 'ed750c00c904781bd281517f177b5f09c4c5ff2979f96eb5b411451065040597'),
  ('ur.jalandhry', 38, 48, 4018, 'اور اسمٰعیل اور الیسع اور ذوالکفل کو یاد کرو۔ وہ سب نیک لوگوں میں سے تھے', NULL, NULL, '8c7f90f5fe910f2b3624360c62f0f0d38a6822333b23503d76c3e2b655fc17b6'),
  ('ur.jalandhry', 38, 49, 4019, 'یہ نصیحت ہے اور پرہیزگاروں کے لئے تو عمدہ مقام ہے', NULL, NULL, '7f216976bf84d3fa504d749793a48c781fa1e904af25d4872614520432124ea5'),
  ('ur.jalandhry', 38, 50, 4020, 'ہمیشہ رہنے کے باغ جن کے دروازے ان کے لئے کھلے ہوں گے', NULL, NULL, 'ec5a55635c45ce161f08e3b9cecfe33659e9ce08f3370eec6853d1d1ab004943'),
  ('ur.jalandhry', 38, 51, 4021, 'ان میں تکیٴے لگائے بیٹھے ہوں گے اور (کھانے پینے کے لئے) بہت سے میوے اور شراب منگواتے رہیں گے', NULL, NULL, '3cbe3bd385faac196dd456e0d80bdb524db614915a4bf664c6a01c6a10c1f432'),
  ('ur.jalandhry', 38, 52, 4022, 'اور ان کے پاس نیچی نگاہ رکھنے والی (اور) ہم عمر (عورتیں) ہوں گی', NULL, NULL, '53a2d8ba2d30497946b94072a378db9ebd8c2783d8c258d21e25b6f531f060d3'),
  ('ur.jalandhry', 38, 53, 4023, 'یہ وہ چیزیں ہیں جن کا حساب کے دن کے لئے تم سے وعدہ کیا جاتا تھا', NULL, NULL, '43b0d4c8b58c20439ceab1d66c6f375cc4b3d572be12ffc86d6fbf4e99b8d2de'),
  ('ur.jalandhry', 38, 54, 4024, 'یہ ہمارا رزق ہے جو کبھی ختم نہیں ہوگا', NULL, NULL, 'a2a752dc72bf93590648ba35d13b353b8fa6ee7fde5adfff99d213b3629049af'),
  ('ur.jalandhry', 38, 55, 4025, 'یہ (نعمتیں تو فرمانبرداروں کے لئے ہیں) اور سرکشوں کے لئے برا ٹھکانا ہے', NULL, NULL, '316e7ba545b0007ed2c23f1988ad13aba81aaf195b87b431912f622c8147b2dd'),
  ('ur.jalandhry', 38, 56, 4026, '(یعنی) دوزخ۔ جس میں وہ داخل ہوں گے اور وہ بری آرام گاہ ہے', NULL, NULL, 'c356a8ea8e992dd3a945da6d131ee3bb30e07ba0bc211041bbe6b0a54ad17f6a'),
  ('ur.jalandhry', 38, 57, 4027, 'یہ کھولتا ہوا گرم پانی اور پیپ (ہے) اب اس کے مزے چکھیں', NULL, NULL, 'b59641ff6308c0f385a573278dcbca6fc0ebc71a6eb47231ead69559d5ab0974'),
  ('ur.jalandhry', 38, 58, 4028, 'اور اسی طرح کے اور بہت سے (عذاب ہوں گے)', NULL, NULL, 'cf804bd5341e1fc524dfc065a026faa8fcddfda83a7c3c17a2f7a3e11be35593'),
  ('ur.jalandhry', 38, 59, 4029, 'یہ ایک فوج ہے جو تمہارے ساتھ داخل ہوگی۔ ان کو خوشی نہ ہو یہ دوزخ میں جانے والے ہیں', NULL, NULL, '2669c5e29dfded700b1d5678e60905bfa77589dabbef89f0bbb1df9a792aa876'),
  ('ur.jalandhry', 38, 60, 4030, 'کہیں گے بلکہ تم ہی کو خوشی نہ ہو۔ تم ہی تو یہ (بلا) ہمارے سامنے لائے سو (یہ) برا ٹھکانا ہے', NULL, NULL, 'e1089a5b07ea37eefd5dc1578cf2aebfd8009bacdf423c5311fe00097b064614'),
  ('ur.jalandhry', 38, 61, 4031, 'وہ کہیں گے اے پروردگار جو اس کو ہمارے سامنے لایا ہے اس کو دوزخ میں دونا عذاب دے', NULL, NULL, '8fd5bbefe8641fcc488ad07a63b33271c9c9f0b50be2c982f604e1fb194aa18f'),
  ('ur.jalandhry', 38, 62, 4032, 'اور کہیں گے کیا سبب ہے کہ (یہاں) ہم ان شخصوں کو نہیں دیکھتے جن کو بروں میں شمار کرتے تھے', NULL, NULL, 'bad3a6752e0e3620f05581755d9381b06f5d6791f025792a28db7da8b759fccd'),
  ('ur.jalandhry', 38, 63, 4033, 'کیا ہم نے ان سے ٹھٹھا کیا ہے یا (ہماری) آنکھیں ان (کی طرف) سے پھر گئی ہیں؟', NULL, NULL, '5ac2ccd7213dccdaa25f2545c73f85bc7840e51dbf1cb806f0d67c0d257cba6a'),
  ('ur.jalandhry', 38, 64, 4034, 'بےشک یہ اہل دوزخ کا جھگڑنا برحق ہے', NULL, NULL, '98015ce0c94a2f92f0fa03c44182c83669779b5bd40358e146f4c02b6e60c9ca'),
  ('ur.jalandhry', 38, 65, 4035, 'کہہ دو کہ میں تو صرف ہدایت کرنے والا ہوں۔ اور خدائے یکتا اور غالب کے سوا کوئی معبود نہیں', NULL, NULL, 'b2f5a676d6074cfd5905d2ac8f2cdf58986c45bf40722a6394852ee389d7a13e'),
  ('ur.jalandhry', 38, 66, 4036, 'جو آسمانوں اور زمین اور جو مخلوق ان میں ہے سب کا مالک ہے غالب (اور) بخشنے والا', NULL, NULL, '05e449ff9dc45f1850ab5f1dbe11f2ca152d5a64981eab1f2d1eda50db480353'),
  ('ur.jalandhry', 38, 67, 4037, 'کہہ دو کہ یہ ایک بڑی (ہولناک چیز کی) خبر ہے', NULL, NULL, '29d801e34a6dc5b76ea419ccdf5edd36ddf611fed486ef6c602d77008667236e'),
  ('ur.jalandhry', 38, 68, 4038, 'جس کو تم دھیان میں نہیں لاتے', NULL, NULL, 'f800815536213f31f91bd75493d5e7d3aa40bd9a72b245460f16bf275dfaf719'),
  ('ur.jalandhry', 38, 69, 4039, 'مجھ کو اوپر کی مجلس (والوں) کا جب وہ جھگڑتے تھے کچھ بھی علم نہ تھا', NULL, NULL, 'ce4ea952d026b19858cb89e366b6adf47b54236c207290f3d9f0e39b4f72d790'),
  ('ur.jalandhry', 38, 70, 4040, 'میری طرف تو یہی وحی کی جاتی ہے کہ میں کھلم کھلا ہدایت کرنے والا ہوں', NULL, NULL, '8c6f3798695e4a49b552ca047627bf9b6cb7e3cae36a2d173de59f53a0ab8134'),
  ('ur.jalandhry', 38, 71, 4041, 'جب تمہارے پروردگار نے فرشتوں سے کہا کہ میں مٹی سے انسان بنانے والا ہوں', NULL, NULL, '9d99405174394768d127e56167a95e6def197107d65502e2af4a341d800dc32a'),
  ('ur.jalandhry', 38, 72, 4042, 'جب اس کو درست کرلوں اور اس میں اپنی روح پھونک دوں تو اس کے آگے سجدے میں گر پڑنا', NULL, NULL, '8b26acb6929fe5f48a58c03b31338a5274882577e8a466590775569a3b1cacdc'),
  ('ur.jalandhry', 38, 73, 4043, 'تو تمام فرشتوں نے سجدہ کیا', NULL, NULL, 'accb2f9893bea951633873451176e0e1c072168ee4e1c6603e6599ac3834f781'),
  ('ur.jalandhry', 38, 74, 4044, 'مگر شیطان اکڑ بیٹھا اور کافروں میں ہوگیا', NULL, NULL, '219ba1a397cff400881259d26719671a023647aea3d9763ad008911f86ad1c1e'),
  ('ur.jalandhry', 38, 75, 4045, 'خدا نے) فرمایا کہ اے ابلیس جس شخص کو میں نے اپنے ہاتھوں سے بنایا اس کے آگے سجدہ کرنے سے تجھے کس چیز نے منع کیا۔ کیا تو غرور میں آگیا یا اونچے درجے والوں میں تھا؟', NULL, NULL, '3c81e07717bfd6596a8227e4ee068063c1f499ac552692d537bd0bbb6ba50531'),
  ('ur.jalandhry', 38, 76, 4046, 'بولا کہ میں اس سے بہتر ہوں (کہ) تو نے مجھ کو کو آگ سے پیدا کیا اور اِسے مٹی سے بنایا', NULL, NULL, '311d52673c190f3a30e28fffb7053d8e4c7381c1efd4fa5ab577b6067cd8a5c3'),
  ('ur.jalandhry', 38, 77, 4047, 'فرمایا یہاں سے نکل جا تو مردود ہے', NULL, NULL, 'af60faac7a001b7e2f89e40fb39afadbea0280b8441d01876be763c477eb87fd'),
  ('ur.jalandhry', 38, 78, 4048, 'اور تجھ پر قیامت کے دن تک میری لعنت (پڑتی) رہے گی', NULL, NULL, '964671212a146dfada091b2d6bf04f848ab0577c6b3e510407e33b5a1bad61a1'),
  ('ur.jalandhry', 38, 79, 4049, 'کہنے لگا کہ میرے پروردگار مجھے اس روز تک کہ لوگ اٹھائے جائیں مہلت دے', NULL, NULL, 'acd97ff9ae14ee6514581bc801f75e713a7319292f87dc28baab3fefc449ad0c'),
  ('ur.jalandhry', 38, 80, 4050, 'فرمایا کہ تجھ کو مہلت دی جاتی ہے', NULL, NULL, 'a9dae4896d6086a015dca5b8c93d45e904a55a6c8e764fa76143e663937a25b3'),
  ('ur.jalandhry', 38, 81, 4051, 'اس روز تک جس کا وقت مقرر ہے', NULL, NULL, '993d3c6f3f70a4b7282b874a292bdc81f32c7750cc5233242f4129921405fc4d'),
  ('ur.jalandhry', 38, 82, 4052, 'کہنے لگا کہ مجھے تیری عزت کی قسم میں ان سب کو بہکاتا رہوں گا', NULL, NULL, '7266e2bc23799f92b0cdc47fca0366d924308d0b864f85a4cccc133161592291'),
  ('ur.jalandhry', 38, 83, 4053, 'سوا ان کے جو تیرے خالص بندے ہیں', NULL, NULL, '7486d03bccb9bf2b5c3e11d9bfc53ebdff7f60a71dd176caa270b690c834f597'),
  ('ur.jalandhry', 38, 84, 4054, 'فرمایا سچ (ہے) اور میں بھی سچ کہتا ہوں', NULL, NULL, 'aa55867fc527f12f0717859555f84cc16bc35147a9c0facbb2aeeb912e0771d3'),
  ('ur.jalandhry', 38, 85, 4055, 'کہ میں تجھ سے اور جو ان میں سے تیری پیروی کریں گے سب سے جہنم کو بھر دوں گا', NULL, NULL, '0d9a439bfef9c7f0ac4bd3544e9218fce753f4cdf9db9fb4f9599e4b7999c917'),
  ('ur.jalandhry', 38, 86, 4056, 'اے پیغمبر کہہ دو کہ میں تم سے اس کا صلہ نہیں مانگتا اور نہ میں بناوٹ کرنے والوں میں ہوں', NULL, NULL, '797d53e5848e81cc57f0d65fb44162b9f792cdfb0e4a1e51cb9bca188bfbd449'),
  ('ur.jalandhry', 38, 87, 4057, 'یہ قرآن تو اہل عالم کے لئے نصیحت ہے', NULL, NULL, 'e47932f897fb9264d4b1fe0ea53c918c0b9392d78aaee92e367e5fc6de920364'),
  ('ur.jalandhry', 38, 88, 4058, 'اور تم کو اس کا حال ایک وقت کے بعد معلوم ہوجائے گا', NULL, NULL, '43bb3c2c3779f9a5027df8cba2565d0a62b029dd5714079f3744f9ce1dbbbabf'),
  ('ur.jalandhry', 39, 1, 4059, 'اس کتاب کا اُتارا جانا خدائے غالب (اور) حکمت والے کی طرف سے ہے', NULL, NULL, 'a54e55cec51a266299446c69cee8a063e2cfc8807f96f9337c089093c88439f3'),
  ('ur.jalandhry', 39, 2, 4060, '(اے پیغمبر) ہم نے یہ کتاب تمہاری طرف سچائی کے ساتھ نازل کی ہے تو خدا کی عبادت کرو (یعنی) اس کی عبادت کو (شرک سے) خالص کرکے', NULL, NULL, 'a83b1002ad6afb5a6fa78a8df4cf82f6c425fa47b395db1b05a06c624d8afb31'),
  ('ur.jalandhry', 39, 3, 4061, 'دیکھو خالص عبادت خدا ہی کے لئے (زیبا ہے) اور جن لوگوں نے اس کے سوا اور دوست بنائے ہیں۔ (وہ کہتے ہیں کہ) ہم ان کو اس لئے پوجتے ہیں کہ ہم کو خدا کا مقرب بنادیں۔ تو جن باتوں میں یہ اختلاف کرتے ہیں خدا ان میں ان کا فیصلہ کردے گا۔ بےشک خدا اس شخص کو جو جھوٹا ناشکرا ہے ہدایت نہیں دیتا', NULL, NULL, 'fd1f76eca29fad79ab7b099dd4f76d5bf82cdde71aa627cd038e1f09140ec41c'),
  ('ur.jalandhry', 39, 4, 4062, 'اگر خدا کسی کو اپنا بیٹا بنانا چاہتا تو اپنی مخلوق میں سے جس کو چاہتا انتخاب کرلیتا۔ وہ پاک ہے وہی تو خدا یکتا (اور) غالب ہے', NULL, NULL, '3f075dbb39b9927723641c38b745f176b5470e93de3d397ab92b4b417ba3c138'),
  ('ur.jalandhry', 39, 5, 4063, 'اسی نے آسمانوں اور زمین کو تدبیر کے ساتھ پیدا کیا ہے۔ (اور) وہی رات کو دن پر لپیٹتا ہے اور دن کو رات پر لپیٹتا ہے اور اسی نے سورج اور چاند کو بس میں کر رکھا ہے۔ سب ایک وقت مقرر تک چلتے رہیں گے۔ دیکھو وہی غالب (اور) بخشنے والا ہے', NULL, NULL, 'a0e37a0a7d1d8cb204e84e2e972edf89f90de01ab5b66bd21ae6ba00eb6c28f6'),
  ('ur.jalandhry', 39, 6, 4064, 'اسی نے تم کو ایک شخص سے پیدا کیا پھر اس سے اس کا جوڑا بنایا اور اسی نے تمہارے لئے چار پایوں میں سے آٹھ جوڑے بنائے۔ وہی تم کو تمہاری ماؤں کے پیٹ میں (پہلے) ایک طرح پھر دوسری طرح تین اندھیروں میں بناتا ہے۔ یہی خدا تمہارا پروردگار ہے اسی کی بادشاہی ہے۔ اس کے سوا کوئی معبود نہیں پھر تم کہاں پھرے جاتے ہو؟', NULL, NULL, '419df62386af8577998acc8436efe54516ed8f6444746b8d84a85568c0ff52e9'),
  ('ur.jalandhry', 39, 7, 4065, 'اگر ناشکری کرو گے تو خدا تم سے بےپروا ہے۔ اور وہ اپنے بندوں کے لئے ناشکری پسند نہیں کرتا اور اگر شکر کرو گے تو وہ اس کو تمہارے لئے پسند کرے گا۔ اور کوئی اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا۔ پھر تم اپنے پروردگار کی طرف لوٹنا ہے۔ پھر جو کچھ تم کرتے رہے وہ تم کو بتائے گا۔ وہ تو دلوں کی پوشیدہ باتوں تک سے آگاہ ہے', NULL, NULL, 'eebef111e488cacfdc52afa5e06d74e93f0cd384e7cd3042d9723254aba65b0b'),
  ('ur.jalandhry', 39, 8, 4066, 'اور جب انسان کو تکلیف پہنچتی ہے تو اپنے پروردگار کو پکارتا (اور) اس کی طرف دل سے رجوع کرتا ہے۔ پھر جب وہ اس کو اپنی طرف سے کوئی نعمت دیتا ہے تو جس کام کے لئے پہلے اس کو پکارتا ہے اسے بھول جاتا ہے اور خدا کا شریک بنانے لگتا ہے تاکہ (لوگوں کو) اس کے رستے سے گمراہ کرے۔ کہہ دو کہ (اے کافر نعمت) اپنی ناشکری سے تھوڑا سا فائدہ اٹھالے۔ پھر تُو تو دوزخیوں میں ہوگا', NULL, NULL, 'f3c879ca2d3e8580933369cd0d0ba36589a632e2568c899c6a7d2847620c3143'),
  ('ur.jalandhry', 39, 9, 4067, '(بھلا مشرک اچھا ہے) یا وہ جو رات کے وقتوں میں زمین پر پیشانی رکھ کر اور کھڑے ہو کر عبادت کرتا اور آخرت سے ڈرتا اور اپنے پروردگار کی رحمت کی امید رکھتا ہے۔ کہو بھلا جو لوگ علم رکھتے ہیں اور جو نہیں رکھتے دونوں برابر ہوسکتے ہیں؟ (اور) نصیحت تو وہی پکڑتے ہیں جو عقلمند ہیں', NULL, NULL, 'db6e1dac47be05ac9d4c85798340f3482afb3b6883848f9ccf4ade4416c67d74'),
  ('ur.jalandhry', 39, 10, 4068, 'کہہ دو کہ اے میرے بندو جو ایمان لائے ہو اپنے پروردگار سے ڈرو۔ جنہوں نے اس دنیا میں نیکی کی ان کے لئے بھلائی ہے۔ اور خدا کی زمین کشادہ ہے۔ جو صبر کرنے والے ہیں ان کو بےشمار ثواب ملے گا', NULL, NULL, '63540752871e6640e793723278091bac0583c5e84975fa8e56f80fcac2a38e58'),
  ('ur.jalandhry', 39, 11, 4069, 'کہہ دو کہ مجھ سے ارشاد ہوا ہے کہ خدا کی عبادت کو خالص کرکے اس کی بندگی کروں', NULL, NULL, '18f7b4123e8c1b376d2ee9a8cbd617939c6b04f7cd5da7bbae5d852cbb16a693'),
  ('ur.jalandhry', 39, 12, 4070, 'اور یہ بھی ارشاد ہوا ہے کہ میں سب سے اول مسلمان بنوں', NULL, NULL, '308ae2371e9c3b77154f451fd09938a275e1b2626efe0aebe4ea82802a4dd4d8'),
  ('ur.jalandhry', 39, 13, 4071, 'کہہ دو کہ اگر میں اپنے پروردگار کا حکم نہ مانوں تو مجھے بڑے دن کے عذاب سے ڈر لگتا ہے', NULL, NULL, 'f2f8f5119352ab2ed359dc5a45980495fb75e5f1f3078eff01ca24b93959cfd1'),
  ('ur.jalandhry', 39, 14, 4072, 'کہہ دو کہ میں اپنے دین کو (شرک سے) خالص کرکے اس کی عبادت کرتا ہوں', NULL, NULL, '7516384333e4364db151e3d8119ec5e964c39b2a3ca2c877332ee867a320488a'),
  ('ur.jalandhry', 39, 15, 4073, 'تو تم اس کے سوا جس کی چاہو پرستش کرو۔ کہہ دو کہ نقصان اٹھانے والے وہی لوگ ہیں جنہوں نے قیامت کے دن اپنے آپ کو اور اپنے گھر والوں کو نقصان میں ڈالا۔ دیکھو یہی صریح نقصان ہے', NULL, NULL, '0f4ac78e5ec4f5f21f2b1180eb7357b3a9267a991c74e5fc03970c0660a23e24'),
  ('ur.jalandhry', 39, 16, 4074, 'ان کے اوپر تو آگ کے سائبان ہوں گے اور نیچے (اس کے) فرش ہوں گے۔ یہ وہ (عذاب) ہے جس سے خدا اپنے بندوں کو ڈراتا ہے۔ تو اے میرے بندو مجھ سے ڈرتے رہو', NULL, NULL, 'dad3f1e6021e1676080aa8774d1085c60febc2a375d1809562fb7b461214d252'),
  ('ur.jalandhry', 39, 17, 4075, 'اور جنہوں نے اس سے اجتناب کیا کہ بتوں کو پوجیں اور خدا کی طرف رجوع کیا ان کے لئے بشارت ہے۔ تو میرے بندوں کو بشارت سنا دو', NULL, NULL, 'd5ccf74a137171d687136e464c3c3ee52a82c93b00e54e3ce7130aebb0106793'),
  ('ur.jalandhry', 39, 18, 4076, 'جو بات کو سنتے اور اچھی باتوں کی پیروی کرتے ہیں۔ یہی وہ لوگ ہیں جن کو خدا نے ہدایت دی اور یہی عقل والے ہیں', NULL, NULL, '905905042410eb13f0ef2a9b59321e9f32b62edd88a68d2099a4210788574b0b'),
  ('ur.jalandhry', 39, 19, 4077, 'بھلا جس شخص پر عذاب کا حکم صادر ہوچکا۔ تو کیا تم (ایسے) دوزخی کو مخلصی دے سکو گے؟', NULL, NULL, 'aa10eaf180cbca4fb233c2e561f5a60d674d32fc64f722a10924826cddf26588'),
  ('ur.jalandhry', 39, 20, 4078, 'لیکن جو لوگ اپنے پروردگار سے ڈرتے ہیں ان کے لئے اونچے اونچے محل ہیں جن کے اوپر بالا خانے بنے ہوئے ہیں۔ (اور) ان کے نیچے نہریں بہہ رہی ہیں۔ (یہ) خدا کا وعدہ ہے۔ خدا وعدے کے خلاف نہیں کرتا', NULL, NULL, '7f8a769331a925af8a7349b98e71d6f2ebfc187adb2032822c136858434bb139'),
  ('ur.jalandhry', 39, 21, 4079, 'کیا تم نے نہیں دیکھا کہ خدا آسمان سے پانی نازل کرتا پھر اس کو زمین میں چشمے بنا کر جاری کرتا پھر اس سے کھیتی اُگاتا ہے جس کے طرح طرح کے رنگ ہوتے ہیں۔ پھر وہ خشک ہوجاتی ہے تو تم اس کو دیکھتے ہو (کہ) زرد (ہوگئی ہے) پھر اسے چورا چورا کر دیتا ہے۔ بےشک اس میں عقل والوں کے لئے نصیحت ہے', NULL, NULL, '891b4a72382f79f79cea679099585448cd86970d9283d848b541a42b8936bd7d'),
  ('ur.jalandhry', 39, 22, 4080, 'بھلا جس شخص کا سینہ خدا نے اسلام کے لئے کھول دیا ہو اور وہ اپنے پروردگار کی طرف سے روشنی پر ہو (تو کیا وہ سخت دل کافر کی طرح ہوسکتا ہے) پس ان پر افسوس ہے جن کے دل خدا کی یاد سے سخت ہو رہے ہیں۔ اور یہی لوگ صریح گمراہی میں ہیں', NULL, NULL, 'ce8f2489d3140f753dd55e59e460bb0436a8bbe3aabc941992fee24d3b650c0d'),
  ('ur.jalandhry', 39, 23, 4081, 'خدا نے نہایت اچھی باتیں نازل فرمائی ہیں (یعنی) کتاب (جس کی آیتیں باہم) ملتی جلتی (ہیں) اور دہرائی جاتی (ہیں) جو لوگ اپنے پروردگار سے ڈرتے ہیں ان کے بدن کے (اس سے) رونگٹے کھڑے ہوجاتے ہیں۔ پھر ان کے بدن اور دل نرم (ہو کر) خدا کی یاد کی طرف (متوجہ) ہوجاتے ہیں۔ یہی خدا کی ہدایت ہے وہ اس سے جس کو چاہتا ہے ہدایت دیتا ہے۔ اور جس کو خدا گمراہ کرے اس کو کوئی ہدایت دینے والا نہیں', NULL, NULL, '19b1ca7e9629cccf95961ad9daddb356387d83047544dd15e2340d511daf3abc'),
  ('ur.jalandhry', 39, 24, 4082, 'بھلا جو شخص قیامت کے دن اپنے منہ سے برے عذاب کو روکتا ہو (کیا وہ ویسا ہوسکتا ہے جو چین میں ہو) اور ظالموں سے کہا جائے گا کہ جو کچھ تم کرتے رہے تھے اس کے مزے چکھو', NULL, NULL, 'e1f1a307cdb114e186e027d7048b1e9f3f461c5de753d88b940ca89ea3c56d05'),
  ('ur.jalandhry', 39, 25, 4083, 'جو لوگ ان سے پہلے تھے انہوں نے بھی تکذیب کی تھی تو ان پر عذاب ایسی جگہ سے آگیا کہ ان کو خبر ہی نہ تھی', NULL, NULL, '9cb3cdbc121b8064757164084cf44c25f8f9fbd70f9f05e8c69a490ed22de665'),
  ('ur.jalandhry', 39, 26, 4084, 'پھر ان کو خدا نے دنیا کی زندگی میں رسوائی کا مزہ چکھا دیا۔ اور آخرت کا عذاب تو بہت بڑا ہے۔ کاش یہ سمجھ رکھتے', NULL, NULL, 'd709270b9792d41ddfa4b61db2438f0066324b67590bcbb347f8bee2c5b9133a'),
  ('ur.jalandhry', 39, 27, 4085, 'اور ہم نے لوگوں کے (سمجھانے کے) لئے اس قرآن میں ہر طرح کی مثالیں بیان کی ہیں تاکہ وہ نصیحت پکڑیں', NULL, NULL, '66ee2f5f4a396d56e24898b9059e3d55c23727e09933f45b367b8dac384918b6'),
  ('ur.jalandhry', 39, 28, 4086, 'یہ) قرآن عربی (ہے) جس میں کوئی عیب (اور اختلاف) نہیں تاکہ وہ ڈر مانیں', NULL, NULL, 'eb8500ee0561e12941be0be15502c5477d1b869aa49ad94c503eeccf9c45318b'),
  ('ur.jalandhry', 39, 29, 4087, 'خدا ایک مثال بیان کرتا ہے کہ ایک شخص ہے جس میں کئی (آدمی) شریک ہیں۔ (مختلف المزاج اور) بدخو اور ایک آدمی خاص ایک شخص کا (غلام) ہے۔ بھلا دونوں کی حالت برابر ہے۔ (نہیں) الحمدلله بلکہ یہ اکثر لوگ نہیں جانتے', NULL, NULL, '4b4877f5756634eb7af8f4f64c6ca81027c9ad039bc1b10c2be1afc914c16adf'),
  ('ur.jalandhry', 39, 30, 4088, '(اے پیغمبر) تم بھی مر جاؤ گے اور یہ بھی مر جائیں گے', NULL, NULL, 'd00bd16874919cc779d33ec9cb0cf2422689fd02be82010459a671aa4ebdba54'),
  ('ur.jalandhry', 39, 31, 4089, 'پھر تم سب قیامت کے دن اپنے پروردگار کے سامنے جھگڑو گے (اور جھگڑا فیصل کردیا جائے گا)', NULL, NULL, 'd5bae1f7d810555e0d330426425ccc026a09401b118b5104f20108653ba9fdd8'),
  ('ur.jalandhry', 39, 32, 4090, 'تو اس سے بڑھ کر ظالم کون جو خدا پر جھوٹ بولے اور سچی بات جب اس کے پاس پہنچ جائے تو اسے جھٹلائے۔ کیا جہنم میں کافروں کا ٹھکانا نہیں ہے؟', NULL, NULL, 'd0ec0edb1ade176d3382c51be506ca0cc8eb56ef9f2d6b6fa4efda83e36b984d'),
  ('ur.jalandhry', 39, 33, 4091, 'اور جو شخص سچی بات لے کر آیا اور جس نے اس کی تصدیق کی وہی لوگ متقی ہیں', NULL, NULL, '9d3a61ee2668e13fc9458ac4eb60236bca96782604c9b16255111b732465945e'),
  ('ur.jalandhry', 39, 34, 4092, 'وہ جو چاہیں گے ان کے لئے ان کے پروردگار کے پاس (موجود) ہے۔ نیکوکاروں کا یہی بدلہ ہے', NULL, NULL, '2aae6b92bdf4d78acbfdb9c9e6566757dd2e3cb9ea5e68223e073b26142d23f2'),
  ('ur.jalandhry', 39, 35, 4093, 'تاکہ خدا ان سے برائیوں کو جو انہوں نے کیں دور کردے اور نیک کاموں کا جو وہ کرتے رہے ان کو بدلہ دے', NULL, NULL, 'fbe2afe646139e048f942c7d7e6ce43660daf5994ffb8203641919e5ce3f7f01'),
  ('ur.jalandhry', 39, 36, 4094, 'کیا خدا اپنے بندوں کو کافی نہیں۔ اور یہ تم کو ان لوگوں سے جو اس کے سوا ہیں (یعنی غیر خدا سے) ڈراتے ہیں۔ اور جس کو خدا گمراہ کرے اسے کوئی ہدایت دینے والا نہیں', NULL, NULL, '57b9b1b8685673be7f011271456ad22dcec7959fc6642296e01f7afcb37c3701'),
  ('ur.jalandhry', 39, 37, 4095, 'اور جس کو خدا ہدایت دے اس کو کوئی گمراہ کرنے والا نہیں۔ کیا خدا غالب (اور) بدلہ لینے والا نہیں ہے؟', NULL, NULL, 'd6ee96a6ac04a423917286b11ee8b01d8518f94bac4fc20b388abeea3dbf56ed'),
  ('ur.jalandhry', 39, 38, 4096, 'اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو کہہ دیں کہ خدا نے۔ کہو کہ بھلا دیکھو تو جن کو تم خدا کے سوا پکارتے ہو۔ اگر خدا مجھ کو کوئی تکلیف پہنچانی چاہے تو کیا وہ اس تکلیف کو دور کرسکتے ہیں یا اگر مجھ پر مہربانی کرنا چاہے تو وہ اس کی مہربانی کو روک سکتے ہیں؟ کہہ دو کہ مجھے خدا ہی کافی ہے۔ بھروسہ رکھنے والے اسی پر بھروسہ رکھتے ہیں', NULL, NULL, '9ab39492b711d13f7facac691c5777d80a5fdecd2c835f7a5d54b7b35472ced3'),
  ('ur.jalandhry', 39, 39, 4097, 'کہہ دو کہ اے قوم تم اپنی جگہ عمل کئے جاؤ میں (اپنی جگہ) عمل کئے جاتا ہوں۔ عنقریب تم کو معلوم ہوجائے گا', NULL, NULL, '2388691e5ab03b86fc34342048981c62d6cc132a613f20a1dc84cb487179529f'),
  ('ur.jalandhry', 39, 40, 4098, 'کہ کس پر عذاب آتا ہے جو اسے رسوا کرے گا۔ اور کس پر ہمیشہ کا عذاب نازل ہوتا ہے', NULL, NULL, 'a1c99fca50b5367626a92e940af1047c3186b2aeea655dab220de94d21f58187'),
  ('ur.jalandhry', 39, 41, 4099, 'ہم نے تم پر کتاب لوگوں (کی ہدایت) کے لئے سچائی کے ساتھ نازل کی ہے۔ تو جو شخص ہدایت پاتا ہے تو اپنے (بھلے کے) لئے اور جو گمراہ ہوتا ہے گمراہی سے تو اپنا ہی نقصان کرتا ہے۔ اور (اے پیغمبر) تم ان کے ذمہ دار نہیں ہو', NULL, NULL, 'f42dcf92aabee52599fe3f4ef67932708225d20b12f2f531471e5fa47d987d8b'),
  ('ur.jalandhry', 39, 42, 4100, 'خدا لوگوں کے مرنے کے وقت ان کی روحیں قبض کرلیتا ہے اور جو مرے نہیں (ان کی روحیں) سوتے میں (قبض کرلیتا ہے) پھر جن پر موت کا حکم کرچکتا ہے ان کو روک رکھتا ہے اور باقی روحوں کو ایک وقت مقرر تک کے لئے چھوڑ دیتا ہے۔ جو لوگ فکر کرتے ہیں ان کے لئے اس میں نشانیاں ہیں', NULL, NULL, 'd3ab37b9808b21cae49a9239dbad0261d14aa0020f294fa14e4a607ed9f78fb0')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 39, 43, 4101, 'کیا انہوں نے خدا کے سوا اور سفارشی بنالئے ہیں۔ کہو کہ خواہ وہ کسی چیز کا بھی اختیار نہ رکھتے ہوں اور نہ (کچھ) سمجھتے ہی ہوں', NULL, NULL, '5430fc61133b7f591d7ae2eed3cc525480e5800b932676ce7e3306a111c8736d'),
  ('ur.jalandhry', 39, 44, 4102, 'کہہ دو کہ سفارش تو سب خدا ہی کے اختیار میں ہے۔ اسی کے لئے آسمانوں اور زمین کی بادشاہت ہے۔ پھر تم اسی کی طرف لوٹ کر جاؤ گے', NULL, NULL, '6cc047297f8e87eec7cd1ce846cc576168e67023ff7649cd323e5f0fec6c125a'),
  ('ur.jalandhry', 39, 45, 4103, 'اور جب تنہا خدا کا ذکر کیا جاتا ہے تو جو لوگ آخرت پر ایمان نہیں رکھتے ان کے دل منقبض ہوجاتے ہیں۔ اور جب اس کے سوا اوروں کا ذکر کیا جاتا ہے تو خوش ہوجاتے ہیں', NULL, NULL, '9715b70d5859ba3c2df058bc358153e79be328d9cf3061a78ecee5d9bd03d329'),
  ('ur.jalandhry', 39, 46, 4104, 'کہو کہ اے خدا (اے) آسمانوں اور زمین کے پیدا کرنے والے (اور) پوشیدہ اور ظاہر کے جاننے والے تو ہی اپنے بندوں میں ان باتوں کا جن میں وہ اختلاف کرتے رہے ہیں فیصلہ کرے گا', NULL, NULL, 'de7089e609827efc7c667349ae13e0905cec25157b7c301f14431f425158944b'),
  ('ur.jalandhry', 39, 47, 4105, 'اور اگر ظالموں کے پاس وہ سب (مال ومتاع) ہو جو زمین میں ہے اور اس کے ساتھ اسی قدر اور ہو تو قیامت کے روز برے عذاب (سے مخلصی پانے) کے بدلے میں دے دیں۔ اور ان پر خدا کی طرف سے وہ امر ظاہر ہوجائے گا جس کا ان کو خیال بھی نہ تھا', NULL, NULL, 'f288a6bdc1dbca540adf533d49e7bb06658849d2e00e05420fe06bc213576f81'),
  ('ur.jalandhry', 39, 48, 4106, 'اور ان کے اعمال کی برائیاں ان پر ظاہر ہوجائیں گی اور جس (عذاب) کی وہ ہنسی اُڑاتے تھے وہ ان کو آگھیرے گا', NULL, NULL, 'b23d27b8161813679a52155a954ea0b7c984180748cd865b4b180b7664a3a9fe'),
  ('ur.jalandhry', 39, 49, 4107, 'جب انسان کو تکلیف پہنچتی ہے تو ہمیں پکارنے لگتا ہے۔ پھر جب ہم اس کو اپنی طرف سے نعمت بخشتے ہیں تو کہتا ہے کہ یہ تو مجھے (میرے) علم (ودانش) کے سبب ملی ہے۔ (نہیں) بلکہ وہ آزمائش ہے مگر ان میں سے اکثر نہیں جانتے', NULL, NULL, '6aef66b0bd2000d27737ed86131d4f819dd314d7849973395e40e452b3ecea20'),
  ('ur.jalandhry', 39, 50, 4108, 'جو لوگ ان سے پہلے تھے وہ بھی یہی کہا کرتے تھے تو جو کچھ وہ کیا کرتے تھے ان کے کچھ بھی کام نہ آیا', NULL, NULL, '1fa38b99d38e48e7df5208109f0c453246fc7cb224398b93019e7c31b8d3c736'),
  ('ur.jalandhry', 39, 51, 4109, 'ان پر ان کے اعمال کے وبال پڑ گئے۔ اور جو لوگ ان میں سے ظلم کرتے رہے ہیں ان پر ان کے عملوں کے وبال عنقریب پڑیں گے۔ اور وہ (خدا کو) عاجز نہیں کرسکتے', NULL, NULL, 'c92f1a77bbc7263b0ad0581894385a2390a3e6d54e5ec854e217bb5d218bf745'),
  ('ur.jalandhry', 39, 52, 4110, 'کیا ان کو معلوم نہیں کہ خدا ہی جس کے لئے چاہتا ہے رزق کو فراخ کردیتا ہے اور (جس کے لئے چاہتا ہے) تنگ کر دیتا ہے۔ جو لوگ ایمان لاتے ہیں ان کے لئے اس میں (بہت سی) نشانیاں ہیں', NULL, NULL, 'e72e59ee998f935bfa7a6d69cd210f0005b13b273d6ec16e73378a1179299a36'),
  ('ur.jalandhry', 39, 53, 4111, '(اے پیغمبر میری طرف سے لوگوں کو) کہہ دو کہ اے میرے بندو جنہوں نے اپنی جانوں پر زیادتی کی ہے خدا کی رحمت سے ناامید نہ ہونا۔ خدا تو سب گناہوں کو بخش دیتا ہے۔ (اور) وہ تو بخشنے والا مہربان ہے', NULL, NULL, '27a5d17e7d4034ab2498a90b05827b14d8589942ca90a0e55e3443e733d1eb5b'),
  ('ur.jalandhry', 39, 54, 4112, 'اور اس سے پہلے کہ تم پر عذاب آ واقع ہو، اپنے پروردگار کی طرف رجوع کرو اور اس کے فرمانبردار ہوجاؤ پھر تم کو مدد نہیں ملے گی', NULL, NULL, '16e727d441022e4219201bfac697ba42c7ad9df29d2f4d73d113dd516e4682b5'),
  ('ur.jalandhry', 39, 55, 4113, 'اور اس سے پہلے کہ تم پر ناگہاں عذاب آجائے اور تم کو خبر بھی نہ ہو اس نہایت اچھی (کتاب) کی جو تمہارے پروردگار کی طرف سے تم پر نازل ہوئی ہے پیروی کرو', NULL, NULL, '7c5202afa285d1b90f172dcc39f57801e697625db692b1deb0c7a03b5a8e6f77'),
  ('ur.jalandhry', 39, 56, 4114, 'کہ (مبادا اس وقت) کوئی متنفس کہنے لگے کہ (ہائے ہائے) اس تقصیر پر افسوس ہے جو میں نے خدا کے حق میں کی اور میں تو ہنسی ہی کرتا رہا', NULL, NULL, '07791639daf7a553fe3c1f58057820d678f57a1a24a8c71cb77acf47b0ef2ef2'),
  ('ur.jalandhry', 39, 57, 4115, 'یا یہ کہنے لگے کہ اگر خدا مجھ کو ہدایت دیتا تو میں بھی پرہیزگاروں میں ہوتا', NULL, NULL, 'eacbab977c51888f1232c63e2c495bf4cb70274966fcf9fadd41664762c4d2a2'),
  ('ur.jalandhry', 39, 58, 4116, 'یا جب عذاب دیکھ لے تو کہنے لگے کہ اگر مجھے پھر ایک دفعہ دنیا میں جانا ہو تو میں نیکوکاروں میں ہو جاؤں', NULL, NULL, '2d064274f6cf673c2f640a51e0684a9f3251c3d7deb8c59810c79c07183e31bb'),
  ('ur.jalandhry', 39, 59, 4117, '(خدا فرمائے گا) کیوں نہیں میری آیتیں تیرے پاس پہنچ گئی ہیں مگر تو نے ان کو جھٹلایا اور شیخی میں آگیا اور تو کافر بن گیا', NULL, NULL, '366d91b159f19540b9182d6311d3cb30426eed195e3b9f23c0ed5044c46061e4'),
  ('ur.jalandhry', 39, 60, 4118, 'اور جن لوگوں نے خدا پر جھوٹ بولا تم قیامت کے دن دیکھو گے کہ ان کے منہ کالے ہو رہے ہوں گے۔ کیا غرور کرنے والوں کو ٹھکانا دوزخ میں نہیں ہے', NULL, NULL, '410f84a4b6f9d009fc4652ea884f205d411b550d5c9bebf5cf545a514351c43d'),
  ('ur.jalandhry', 39, 61, 4119, 'اور جو پرہیزگار ہیں ان کی (سعادت اور) کامیابی کے سبب خدا ان کو نجات دے گا نہ تو ان کو کوئی سختی پہنچے گی اور نہ غمناک ہوں گے', NULL, NULL, 'fd5b7fe6bac1b29abd60214ce96d5e5caff1edc085ef7df049a3e8381aa263f3'),
  ('ur.jalandhry', 39, 62, 4120, 'خدا ہی ہر چیز کا پیدا کرنے والا ہے۔ اور وہی ہر چیز کا نگراں ہے', NULL, NULL, '65cd115ead29d93676d11e072896a71386a15cf89acac4581d96c10e561ba583'),
  ('ur.jalandhry', 39, 63, 4121, 'اسی کے پاس آسمانوں اور زمین کی کنجیاں ہیں۔ اور جنہوں نے خدا کی آیتوں سے کفر کیا وہی نقصان اُٹھانے والے ہیں', NULL, NULL, '8b66bb1cba2b3bc844d530c5ae1940b5566924d168ca66f926372032669b795a'),
  ('ur.jalandhry', 39, 64, 4122, 'کہہ دو کہ اے نادانو! تم مجھ سے یہ کہتے ہو کہ میں غیر خدا کی پرستش کرنے لگوں', NULL, NULL, '802fee29b0d6fb6bb1b78ac876339e388d2ebda3024a1313d406a769b16344c2'),
  ('ur.jalandhry', 39, 65, 4123, 'اور (اے محمدﷺ) تمہاری طرف اور ان (پیغمبروں) کی طرف جو تم سے پہلے ہوچکے ہیں یہی وحی بھیجی گئی ہے۔ کہ اگر تم نے شرک کیا تو تمہارے عمل برباد ہوجائیں گے اور تم زیاں کاروں میں ہوجاؤ گے', NULL, NULL, '3756275e777630e03a069a4ab1e21095f289e6b70db40bd79f9dd1241bcfeb38'),
  ('ur.jalandhry', 39, 66, 4124, 'بلکہ خدا ہی کی عبادت کرو اور شکرگزاروں میں ہو', NULL, NULL, 'be3deebf189917a02407ff4f1607010bd00bb88ad7182a7d0e714efef0746225'),
  ('ur.jalandhry', 39, 67, 4125, 'اور انہوں نے خدا کی قدر شناسی جیسی کرنی چاہیئے تھی نہیں کی۔ اور قیامت کے دن تمام زمین اس کی مٹھی میں ہوگی اور آسمان اس کے داہنے ہاتھ میں لپٹے ہوں گے۔ (اور) وہ ان لوگوں کے شرک سے پاک اور عالی شان ہے', NULL, NULL, '3a910371ea6475e53400f8e9b2930cd458612dc7e512c8ec78ba47047ae25170'),
  ('ur.jalandhry', 39, 68, 4126, 'اور جب صور پھونکا جائے گا تو جو لوگ آسمان میں ہیں اور جو زمین میں ہیں سب بےہوش ہو کر گر پڑیں گے مگر وہ جس کو خدا چاہے۔ پھر دوسری دفعہ پھونکا جائے گا تو فوراً سب کھڑے ہو کر دیکھنے لگیں گے', NULL, NULL, 'c87e692a5be592b0ca9e8e24b4bcbafb6d12fa02a4965f83d4b5da982af82198'),
  ('ur.jalandhry', 39, 69, 4127, 'اور زمین اپنے پروردگار کے نور سے جگمگا اُٹھے گی اور (اعمال کی) کتاب (کھول کر) رکھ دی جائے گی اور پیغمبر اور (اور) گواہ حاضر کئے جائیں گے اور ان میں انصاف کے ساتھ فیصلہ کیا جائے گا اور بےانصافی نہیں کی جائے گی', NULL, NULL, 'f00c83c3308b8d2871059515c3c31fb9b21c71e8dd68474c2dfdbe2f49fa28d0'),
  ('ur.jalandhry', 39, 70, 4128, 'اور جس شخص نے جو عمل کیا ہوگا اس کو اس کا پورا پورا بدلہ مل جائے گا اور جو کچھ یہ کرتے ہیں اس کو سب کی خبر ہے', NULL, NULL, '65b94888a52fc5c550e669a52ed429f6d9419bb151e016c3c5f33b6d29d8f135'),
  ('ur.jalandhry', 39, 71, 4129, 'اور کافروں کو گروہ گروہ بنا کر جہنم کی طرف لے جائیں گے۔ یہاں تک کہ جب وہ اس کے پاس پہنچ جائیں گے تو اس کے دروازے کھول دیئے جائیں گے تو اس کے داروغہ ان سے کہیں گے کہ کیا تمہارے پاس تم ہی میں سے پیغمبر نہیں آئے تھے جو تم کو تمہارے پروردگار کی آیتیں پڑھ پڑھ کر سناتے اور اس دن کے پیش آنے سے ڈراتے تھے کہیں گے کیوں نہیں لیکن کافروں کے حق میں عذاب کا حکم متحقق ہوچکا تھا', NULL, NULL, '71788c24dfc01b59d4445d62b5a432cd06dd40c5f0da7afc897eb22a6618d405'),
  ('ur.jalandhry', 39, 72, 4130, 'کہا جائے گا کہ دوزخ کے دروازوں میں داخل ہوجاؤ ہمیشہ اس میں رہو گے۔ تکبر کرنے والوں کا برا ٹھکانا ہے', NULL, NULL, 'f1d3ebb8cc712ec3d372732e7ab9a20985d2b586b2fc5a4628ec1feaf6d4d70c'),
  ('ur.jalandhry', 39, 73, 4131, 'اور جو لوگ اپنے پروردگار سے ڈرتے ہیں ان کو گروہ گروہ بنا کر بہشت کی طرف لے جائیں گے یہاں تک کہ جب اس کے پاس پہنچ جائیں گے اور اس کے دروازے کھول دیئے جائیں گے تو اس کے داروغہ ان سے کہیں کہ تم پر سلام تم بہت اچھے رہے۔ اب اس میں ہمیشہ کے لئے داخل ہوجاؤ', NULL, NULL, '2ffb9eb43c49bdbad1984ddd61469ea04f7f281dcc947521dd0df4d7d31470d1'),
  ('ur.jalandhry', 39, 74, 4132, 'وہ کہیں گے کہ خدا کا شکر ہے جس نے اپنے وعدہ کو ہم سے سچا کردیا اور ہم کو اس زمین کا وارث بنا دیا ہم بہشت میں جس مکان میں چاہیں رہیں تو (اچھے) عمل کرنے والوں کا بدلہ بھی کیسا خوب ہے', NULL, NULL, '10dd3b6d773be89f30d712d19aa0d40db56d066a225f4e220e0dfa0de55d1fa4'),
  ('ur.jalandhry', 39, 75, 4133, 'تم فرشتوں کو دیکھو گے کہ عرش کے گرد گھیرا باندھے ہوئے ہیں (اور) اپنے پروردگار کی تعریف کے ساتھ تسبیح کر رہے ہیں۔ اور ان میں انصاف کے ساتھ فیصلہ کیا جائے گا اور کہا جائے گا کہ ہر طرح کی تعریف خدا ہی کو سزاوار ہے جو سارے جہان کا مالک ہے', NULL, NULL, '2d95742b9fdf794ff0b762c285b978a5be07297cd3f97b8e20d175384c7f1344'),
  ('ur.jalandhry', 40, 1, 4134, 'حٰم', NULL, NULL, 'd986ffe3c6d7ee25895888ccc3f155e8bc4ee20bae5d426418522f2a94027657'),
  ('ur.jalandhry', 40, 2, 4135, 'اس کتاب کا اتارا جانا خدائے غالب ودانا کی طرف سے ہے', NULL, NULL, 'ccc1f4257052cc460c9d004e7b29041267c171626770d134052eb079aea318e8'),
  ('ur.jalandhry', 40, 3, 4136, 'جو گناہ بخشنے والا اور توبہ قبول کرنے والا ہے اور سخت عذاب دینے والا اور صاحب کرم ہے۔ اس کے سوا کوئی معبود نہیں۔ اسی کی طرف پھر کر جانا ہے', NULL, NULL, 'f7796dae1555bf1af74a245ad059c91461f669a5b9226049fceef0ac1cc3aec7'),
  ('ur.jalandhry', 40, 4, 4137, 'خدا کی آیتوں میں وہی لوگ جھگڑتے ہیں جو کافر ہیں۔ تو ان لوگوں کا شہروں میں چلنا پھرنا تمہیں دھوکے میں نہ ڈال دے', NULL, NULL, 'ead706a1ad71b4962725d1d9f881afe27ebe2f18c032abdc8dbb307316ca44bc'),
  ('ur.jalandhry', 40, 5, 4138, 'ان سے پہلے نوح کی قوم اور ان کے بعد اور اُمتوں نے بھی (پیغمبروں کی) تکذیب کی۔ اور ہر اُمت نے اپنے پیغمبر کے بارے میں یہی قصد کیا کہ اس کو پکڑ لیں اور بیہودہ (شہبات سے) جھگڑتے رہے کہ اس سے حق کو زائل کردیں تو میں نے ان کو پکڑ لیا (سو دیکھ لو) میرا عذاب کیسا ہوا', NULL, NULL, 'b20cc5d46cf04de864d538efabc2bfd819303277af234b7878b901458823cdc6'),
  ('ur.jalandhry', 40, 6, 4139, 'اور اسی طرح کافروں کے بارے میں بھی تمہارے پروردگار کی بات پوری ہوچکی ہے کہ وہ اہل دوزخ ہیں', NULL, NULL, 'f78d0b68449b73acd92345c96499632a240b343634bf0ae88c81ae7f5e3c46a6'),
  ('ur.jalandhry', 40, 7, 4140, 'جو لوگ عرش کو اٹھائے ہوئے اور جو اس کے گردا گرد (حلقہ باندھے ہوئے) ہیں (یعنی فرشتے) وہ اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہتے ہیں اور مومنوں کے لئے بخشش مانگتے رہتے ہیں۔ کہ اے ہمارے پروردگار تیری رحمت اور تیرا علم ہر چیز کو احاطہ کئے ہوئے ہے تو جن لوگوں نے توبہ کی اور تیرے رستے پر چلے ان کو بخش دے اور دوزخ کے عذاب سے بچالے', NULL, NULL, 'd7a3dd7219fd9768aaccf1497009511675b74a170c922f266c90de786ec0b36c'),
  ('ur.jalandhry', 40, 8, 4141, 'اے ہمارے پروردگار ان کو ہمیشہ رہنے کے بہشتوں میں داخل کر جن کا تونے ان سے وعدہ کیا ہے اور جو ان کے باپ دادا اور ان کی بیویوں اور ان کی اولاد میں سے نیک ہوں ان کو بھی۔ بےشک تو غالب حکمت والا ہے', NULL, NULL, 'a3c4b7cfad49fb80bafcfadb7d128f79affeafc848b49c04943796211f06e051'),
  ('ur.jalandhry', 40, 9, 4142, 'اور ان کو عذابوں سے بچائے رکھ۔ اور جس کو تو اس روز عذابوں سے بچا لے گا تو بےشک اس پر مہربانی فرمائی اور یہی بڑی کامیابی ہے', NULL, NULL, '6784f1705e0dd6c2c826493dae5b278f979bb06f658741c0690de52bc1ed8a52'),
  ('ur.jalandhry', 40, 10, 4143, 'جن لوگوں نے کفر کیا ان سے پکار کر کہہ دیا جائے گا کہ جب تم (دنیا میں) ایمان کی طرف بلائے جاتے تھے اور مانتے نہیں تھے تو خدا اس سے کہیں زیادہ بیزار ہوتا تھا جس قدر تم اپنے آپ سے بیزار ہو رہے ہو', NULL, NULL, 'df01e79d606815f1d16be5fe42ca6e99eefd1fc99ad9e70cc0b1ca52e13ed288'),
  ('ur.jalandhry', 40, 11, 4144, 'وہ کہیں گے کہ اے ہمارے پروردگار تو نے ہم کو دو دفعہ بےجان کیا اور دو دفعہ جان بخشی۔ ہم کو اپنے گناہوں کا اقرار ہے تو کیا نکلنے کی کوئی سبیل ہے؟', NULL, NULL, '7f47d9a3d2794abe82506600b59606111ed1b40caf8caefa61418ffd35cbd43f'),
  ('ur.jalandhry', 40, 12, 4145, 'یہ اس لئے کہ جب تنہا خدا کو پکارا جاتا تھا تو تم انکار کردیتے تھے۔ اور اگر اس کے ساتھ شریک مقرر کیا جاتا تھا تو تسلیم کرلیتے تھے تو حکم تو خدا ہی کا ہے جو (سب سے) اوپر اور (سب سے) بڑا ہے', NULL, NULL, 'ae54a5c1915bae535d086da29056c6489a983aaa079a6410c39813c65e73a8a3'),
  ('ur.jalandhry', 40, 13, 4146, 'وہی تو ہے جو تم کو اپنی نشانیاں دکھاتا ہے اور تم پر آسمان سے رزق اُتارتا ہے۔ اور نصیحت تو وہی پکڑتا ہے جو (اس کی طرف) رجوع کرتا ہے', NULL, NULL, 'b0b3c11c1f47bf850410ca4ec1c958060d03d94396dcc6c073f0bf34a271035a'),
  ('ur.jalandhry', 40, 14, 4147, 'تو خدا کی عبادت کو خالص کر کر اُسی کو پکارو اگرچہ کافر برا ہی مانیں', NULL, NULL, '59f2d5406ab7d172dfd8617d7cc4d6e6f3d2b3fa415261b922c5396a01e742a4'),
  ('ur.jalandhry', 40, 15, 4148, 'مالک درجات عالی اور صاحب عرش ہے۔ اپنے بندوں میں سے جس پر چاہتا ہے اپنے حکم سے وحی بھیجتا ہے تاکہ ملاقات کے دن سے ڈراوے', NULL, NULL, 'c4322efcbe0acebb73c42adbc50bdc8d5b892020c5da3786a7a885bc99dc0ab1'),
  ('ur.jalandhry', 40, 16, 4149, 'جس روز وہ نکل پڑیں گے ان کی کوئی چیز خدا سے مخفی نہ رہے گی۔ آج کس کی بادشاہت ہے؟ خدا کی جو اکیلا اور غالب ہے', NULL, NULL, '35cc9d2bfc79da7976035f9078d6d2a6bb480c0d78cd8b1d35a9c17cd612df1d'),
  ('ur.jalandhry', 40, 17, 4150, 'آج کے دن ہر شخص کو اس کے اعمال کا بدلہ دیا جائے گا۔ آج (کسی کے حق میں) بےانصافی نہیں ہوگی۔ بےشک خدا جلد حساب لینے والا ہے', NULL, NULL, 'bd6d4d523c5ab35739c6e9b30266b9a9ef6f88a01523a83c4be3c084c9e426b8'),
  ('ur.jalandhry', 40, 18, 4151, 'اور ان کو قریب آنے والے دن سے ڈراؤ جب کہ دل غم سے بھر کر گلوں تک آرہے ہوں گے۔ (اور) ظالموں کا کوئی دوست نہ ہوگا اور نہ کوئی سفارشی جس کی بات قبول کی جائے', NULL, NULL, '0e39602d25ca9fa50237ef38f99dd16c7215026c0a16b0d629c758f03b4b0da2'),
  ('ur.jalandhry', 40, 19, 4152, 'وہ آنکھوں کی خیانت کو جانتا ہے اور جو (باتیں) سینوں میں پوشیدہ ہیں (ان کو بھی)', NULL, NULL, '68974828f6b25b5ace96cbebb5ec34b6ddff2c4701e22987a1b403b301e0bddb'),
  ('ur.jalandhry', 40, 20, 4153, 'اور خدا سچائی کے ساتھ حکم فرماتا ہے اور جن کو یہ لوگ پکارتے ہیں وہ کچھ بھی حکم نہیں دے سکتے۔ بےشک خدا سننے والا (اور) دیکھنے والا ہے', NULL, NULL, '93fadbcc633d7d493d7216392a536dc0455604490ca6a8e2582ac8d288732b44'),
  ('ur.jalandhry', 40, 21, 4154, 'کیا انہوں نے زمین میں سیر نہیں کی تاکہ دیکھ لیتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا۔ وہ ان سے زور اور زمین میں نشانات (بنانے) کے لحاظ سے کہیں بڑھ کر تھے تو خدا نے ان کو ان کے گناہوں کے سبب پکڑ لیا۔ اور ان کو خدا (کے عذاب) سے کوئی بھی بچانے والا نہ تھا', NULL, NULL, '22715ddb83ab557f33c6f6d69acfd147e8db3736b3296cde4b46cfd5b9bd0d5b'),
  ('ur.jalandhry', 40, 22, 4155, 'یہ اس لئے کہ ان کے پاس پیغمبر کھلی دلیلیں لاتے تھے تو یہ کفر کرتے تھے سو خدا نے ان کو پکڑ لیا۔ بےشک وہ صاحب قوت (اور) سخت عذاب دینے والا ہے', NULL, NULL, '339dd1b80352ab108ceaa2de6ef6bc2e4522363a6884e74c6291e5e59f191b8f'),
  ('ur.jalandhry', 40, 23, 4156, 'اور ہم نے موسیٰ کو اپنی نشانیاں اور دلیل روشن دے کر بھیجا', NULL, NULL, '672213c5e90051a459945cb75c670ade97277624c55055a34d57d5be5295ae2d'),
  ('ur.jalandhry', 40, 24, 4157, '(یعنی) فرعون اور ہامان اور قارون کی طرف تو انہوں نے کہا کہ یہ تو جادوگر ہے جھوٹا', NULL, NULL, 'b42610be5bced77f1990ca3318d199f28316a7a8f60f9a72f927535557fd066d'),
  ('ur.jalandhry', 40, 25, 4158, 'غرض جب وہ ان کے پاس ہماری طرف سے حق لے کر پہنچے تو کہنے لگے کہ جو اس کے ساتھ (خدا پر) ایمان لائے ہیں ان کے بیٹوں کو قتل کردو اور بیٹیوں کو زندہ رہنے دو۔ اور کافروں کی تدبیریں بےٹھکانے ہوتی ہیں', NULL, NULL, '7643a304b42bce9b1141d10dba34d2cea5cdbc1c94d6011d3fd135429f176719'),
  ('ur.jalandhry', 40, 26, 4159, 'اور فرعون بولا کہ مجھے چھوڑو کہ موسیٰ کو قتل کردوں اور وہ اپنے پروردگار کو بلالے۔ مجھے ڈر ہے کہ وہ (کہیں) تمہارے دین کو نہ بدل دے یا ملک میں فساد (نہ) پیدا کردے', NULL, NULL, '32cf0a1c29a43e11bc99f123f74c4ccce4153f1fe7ee6fbe58620372b7483838'),
  ('ur.jalandhry', 40, 27, 4160, 'موسیٰ نے کہا کہ میں ہر متکبر سے جو حساب کے دن (یعنی قیامت) پر ایمان نہیں لاتا۔ اپنے اور تمہارے پروردگار کی پناہ لے چکا ہوں', NULL, NULL, 'd9ee821349d08ac56a1e06d8142e21236fe18762d47ec5cf0640a5707ffee759'),
  ('ur.jalandhry', 40, 28, 4161, 'اور فرعون کے لوگوں میں سے ایک مومن شخص جو اپنے ایمان کو پوشیدہ رکھتا تھا کہنے لگا کیا تم ایسے شخص کو قتل کرنا چاہتے ہو جو کہتا ہے کہ میرا پروردگار خدا ہے اور وہ تمہارے پروردگار (کی طرف) سے نشانیاں بھی لے کر آیا ہے۔ اور اگر وہ جھوٹا ہوگا تو اس کے جھوٹ کا ضرر اسی کو ہوگا۔ اور اگر سچا ہوگا تو کوئی سا عذاب جس کا وہ تم سے وعدہ کرتا ہے تم پر واقع ہو کر رہے گا۔ بےشک خدا اس شخص کو ہدایت نہیں دیتا جو بےلحاظ جھوٹا ہے', NULL, NULL, 'c40f6873c2ec592cb24341a96e536ddb90b9d5df714679afd024ba318604e22a'),
  ('ur.jalandhry', 40, 29, 4162, 'اے قوم آج تمہاری ہی بادشاہت ہے اور تم ہی ملک میں غالب ہو۔ (لیکن) اگر ہم پر خدا کا عذاب آگیا تو (اس کے دور کرنے کے لئے) ہماری مدد کون کرے گا۔ فرعون نے کہا کہ میں تمہیں وہی بات سُجھاتا ہوں جو مجھے سوجھی ہے اور وہی راہ بتاتا ہوں جس میں بھلائی ہے', NULL, NULL, '9816580665e56f4ab42e5ce41c259b8f1ec0410fb8118622cb050aef3549ac8a'),
  ('ur.jalandhry', 40, 30, 4163, 'تو جو مومن تھا وہ کہنے لگا کہ اے قوم مجھے تمہاری نسبت خوف ہے کہ (مبادا) تم پر اور اُمتوں کی طرح کے دن کا عذاب آجائے', NULL, NULL, '2e0fb48b5bda71096791abd71c0bcb74e9f45771d416d0b31bbfd403146418d5'),
  ('ur.jalandhry', 40, 31, 4164, 'یعنی) نوح کی قوم اور عاد اور ثمود اور جو لوگ ان کے پیچھے ہوئے ہیں ان کے حال کی طرح (تمہارا حال نہ ہوجائے) اور خدا تو بندوں پر ظلم کرنا نہیں چاہتا', NULL, NULL, '7d479bcf171dd2a5bd3618f859d8cf23375ac50d2fed37ec7e141b03e0b03125'),
  ('ur.jalandhry', 40, 32, 4165, 'اور اے قوم مجھے تمہاری نسبت پکار کے دن (یعنی قیامت) کا خوف ہے', NULL, NULL, '02687d6eee2124b1bc61b12c16cda93c6304d7b88f2ca065084eba98c9e890f3'),
  ('ur.jalandhry', 40, 33, 4166, 'جس دن تم پیٹھ پھیر کر (قیامت کے دن سے) بھاگو گے (اس دن) تم کو کوئی (عذاب) خدا سے بچانے والا نہ ہوگا۔ اور جس شخص کو خدا گمراہ کرے اس کو کوئی ہدایت دینے والا نہیں', NULL, NULL, 'ad7f2083dea6dc6254472cc91a7bced82b08962be4574bb4c43db6acb45d9a2a'),
  ('ur.jalandhry', 40, 34, 4167, 'اور پہلے یوسف بھی تمہارے پاس نشانیاں لے کر آئے تھے تو جو وہ لائے تھے اس سے تم ہمیشہ شک ہی میں رہے۔ یہاں تک کہ جب وہ فوت ہوگئے تو تم کہنے لگے کہ خدا اس کے بعد کبھی کوئی پیغمبر نہیں بھیجے گا۔ اسی طرح خدا اس شخص کو گمراہ کر دیتا ہے جو حد سے نکل جانے والا اور شک کرنے والا ہو', NULL, NULL, '931041f400384e47e2e2fe4c538dd2aa0c00e1698e08bf620d3086c2929a72b6'),
  ('ur.jalandhry', 40, 35, 4168, 'جو لوگ بغیر اس کے کہ ان کے پاس کوئی دلیل آئی ہو خدا کی آیتوں میں جھگڑتے ہیں۔ خدا کے نزدیک اور مومنوں کے نزدیک یہ جھگڑا سخت ناپسند ہے۔ اسی طرح خدا ہر متکبر سرکش کے دل پر مہر لگا دیتا ہے', NULL, NULL, 'a971c5ead4785f7de0a864095728e9fe8de315aa7d61ef7a320c51ffe0138882'),
  ('ur.jalandhry', 40, 36, 4169, 'اور فرعون نے کہا کہ ہامان میرے لئے ایک محل بناؤ تاکہ میں (اس پر چڑھ کر) رستوں پر پہنچ جاؤں', NULL, NULL, '160864967c661087dedfde3d6fcc30eaba9de919958ec587dd122c33253c01f4'),
  ('ur.jalandhry', 40, 37, 4170, '(یعنی) آسمانوں کے رستوں پر، پھر موسیٰ کے خدا کو دیکھ لوں اور میں تو اسے جھوٹا سمجھتا ہوں۔ اور اسی طرح فرعون کو اس کے اعمال بد اچھے معلوم ہوتے تھے اور وہ رستے سے روک دیا گیا تھا۔ اور فرعون کی تدبیر تو بےکار تھی', NULL, NULL, '50f58285fe078a5dd1675e4cf967560a7b9b26444000e234c9f9b24cdb67a092'),
  ('ur.jalandhry', 40, 38, 4171, 'اور وہ شخص جو مومن تھا اس نے کہا کہ بھائیو میرے پیچھے چلو میں تمہیں بھلائی کا رستہ دکھاؤ ں', NULL, NULL, '5eb25a6a02437805d175cff1d072d18aa09d14f7ea03542b8b04f35622e7ba89'),
  ('ur.jalandhry', 40, 39, 4172, 'بھائیو یہ دنیا کی زندگی (چند روزہ) فائدہ اٹھانے کی چیز ہے۔ اور جو آخرت ہے وہی ہمیشہ رہنے کا گھر ہے', NULL, NULL, '61363e965a0c2020cffc2e16ac79539e13473450b00c9ae226a8fe02447d3d77'),
  ('ur.jalandhry', 40, 40, 4173, 'جو برے کام کرے گا اس کو بدلہ بھی ویسا ہی ملے گا۔ اور جو نیک کام کرے گا مرد ہو یا عورت اور وہ صاحب ایمان بھی ہوگا تو ایسے لوگ بہشت میں داخل ہوں گے وہاں ان کو بےشمار رزق ملے گا', NULL, NULL, 'e42c5a980d9c582b17d3ba97379b35a1c70ef80213c6eac89ace3dd4df9552b0'),
  ('ur.jalandhry', 40, 41, 4174, 'اور اے قوم میرا کیا (حال) ہے کہ میں تم کو نجات کی طرف بلاتا ہوں اور تم مجھے (دوزخ کی) آگ کی طرف بلاتے ہو', NULL, NULL, 'e6525317bd74eb12fd4724d5e2b9ebc396d4663beae9b1ae7bb42ceebae4fb4a'),
  ('ur.jalandhry', 40, 42, 4175, 'تم مجھے اس لئے بلاتے ہو کہ خدا کے ساتھ کفر کروں اور اس چیز کو اس کا شریک مقرر کروں جس کا مجھے کچھ بھی علم نہیں۔ اور میں تم کو (خدائے) غالب (اور) بخشنے والے کی طرف بلاتا ہوں', NULL, NULL, '9af740a9a2db3fdc3f01ed1bbda1222c6f9bfcd91ba9ae9adbdd347f1eaf293d'),
  ('ur.jalandhry', 40, 43, 4176, 'سچ تو یہ ہے کہ جس چیز کی طرف تم مجھے بلاتے ہو اس کو دنیا اور آخرت میں بلانے (یعنی دعا قبول کرنے) کا مقدور نہیں اور ہم کو خدا کی طرف لوٹنا ہے اور حد سے نکل جانے والے دوزخی ہیں', NULL, NULL, 'bd983487939c25be3e2abdaf4b5dc334092b84df75fa757a1f854a19ca83b670'),
  ('ur.jalandhry', 40, 44, 4177, 'جو بات میں تم سے کہتا ہوں تم اسے آگے چل کر یاد کرو گے۔ اور میں اپنا کام خدا کے سپرد کرتا ہوں۔ بےشک خدا بندوں کو دیکھنے والا ہے', NULL, NULL, '176040f4a62e4f6413351000b0c9ff2ca4f8cae72184cef33223525b03828995'),
  ('ur.jalandhry', 40, 45, 4178, 'غرض خدا نے موسیٰ کو ان لوگوں کی تدبیروں کی برائیوں سے محفوظ رکھا اور فرعون والوں کو برے عذاب نے آگھیرا', NULL, NULL, '9ca3774c99b1636ef4cd25c22f89ce1a0dc779f9800398f00dd4fcd6afe29e15'),
  ('ur.jalandhry', 40, 46, 4179, 'یعنی) آتش (جہنم) کہ صبح وشام اس کے سامنے پیش کئے جاتے ہیں۔ اور جس روز قیامت برپا ہوگی (حکم ہوگا کہ) فرعون والوں کو نہایت سخت عذاب میں داخل کرو', NULL, NULL, '5fccf5cdb4c76142ae879ea2e6091b92212ede7ea1be9e9fd1a0a541fd9317b5'),
  ('ur.jalandhry', 40, 47, 4180, 'اور جب وہ دوزخ میں جھگڑیں گے تو ادنیٰ درجے کے لوگ بڑے آدمیوں سے کہیں گے کہ ہم تو تمہارے تابع تھے تو کیا تم دوزخ (کے عذاب) کا کچھ حصہ ہم سے دور کرسکتے ہو؟', NULL, NULL, '14dfc7ee6902430293e32c3f8328ff9ed9e19e730d85e0a7aeb3fd0ab70a092e'),
  ('ur.jalandhry', 40, 48, 4181, 'بڑے آدمی کہیں گے کہ تم (بھی اور) ہم (بھی) سب دوزخ میں (رہیں گے) خدا بندوں میں فیصلہ کرچکا ہے', NULL, NULL, '475c7c48f3e9366b01bf11c6c5da471c2b49ee482c9260f0548cfe63b1781176'),
  ('ur.jalandhry', 40, 49, 4182, 'اور جو لوگ آگ میں (جل رہے) ہوں گے وہ دوزخ کے داروغوں سے کہیں گے کہ اپنے پروردگار سے دعا کرو کہ ایک روز تو ہم سے عذاب ہلکا کردے', NULL, NULL, '56051d644d2b4a4007dd7bc754eb06e223990ddae8b2700d674de97ee389f146'),
  ('ur.jalandhry', 40, 50, 4183, 'وہ کہیں گے کہ کیا تمہارے پاس تمہارے پیغمبر نشانیاں لے کر نہیں آئے تھے۔ وہ کہیں گے کیوں نہیں تو وہ کہیں گے کہ تم ہی دعا کرو۔ اور کافروں کی دعا (اس روز) بےکار ہوگی', NULL, NULL, '8ea97d5bcc09af7433058c288be726b773170edd4bfaf3bed8c2a18183e7dd76'),
  ('ur.jalandhry', 40, 51, 4184, 'ہم اپنے پیغمبروں کی اور جو لوگ ایمان لائے ہیں ان کی دنیا کی زندگی میں بھی مدد کرتے ہیں اور جس دن گواہ کھڑے ہوں گے (یعنی قیامت کو بھی)', NULL, NULL, '3937ea4a119cfa90d0898f02a9982119ee1a3bddd35a08607bd1896ab4510d5b'),
  ('ur.jalandhry', 40, 52, 4185, 'جس دن ظالموں کو ان کی معذرت کچھ فائدہ نہ دے گی اور ان کے لئے لعنت اور برا گھر ہے', NULL, NULL, '0dbe88ceca8409b80d2fdb6e0c6254d3f303f46eeee0e41f2d4812d195544115'),
  ('ur.jalandhry', 40, 53, 4186, 'اور ہم نے موسیٰ کو ہدایت (کی کتاب) دی اور بنی اسرائیل کو اس کتاب کا وارث بنایا', NULL, NULL, '34f9da2a7f9428be58b2741f444b4161dd5f2f8e3daf7df91823c24d7513aa83'),
  ('ur.jalandhry', 40, 54, 4187, 'عقل والوں کے لئے ہدایت اور نصیحت ہے', NULL, NULL, '9124895d84616d381df0984f6e99e37782baf78d9aa7c0fe9f2783ee90995bca'),
  ('ur.jalandhry', 40, 55, 4188, 'تو صبر کرو بےشک خدا کا وعدہ سچا ہے اور اپنے گناہوں کی معافی مانگو اور صبح وشام اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہو', NULL, NULL, '119115bd9acb341a43bdd980a5f77d872a01d2f8d97200497d46d77a62f578c2'),
  ('ur.jalandhry', 40, 56, 4189, 'جو لوگ بغیر کسی دلیل کے جو ان کے پاس آئی ہو خدا کی آیتوں میں جھگڑتے ہیں ان کے دلوں میں اور کچھ نہیں (ارادہٴ) عظمت ہے اور وہ اس کو پہنچنے والے نہیں تو خدا کی پناہ مانگو۔ بےشک وہ سننے والا (اور) دیکھنے والا ہے', NULL, NULL, '37a02642635b4c654070df83a1e29e977da3ab104ebd599365fabb055723a897'),
  ('ur.jalandhry', 40, 57, 4190, 'آسمانوں اور زمین کا پیدا کرنا لوگوں کے پیدا کرنے کی نسبت بڑا (کام) ہے لیکن اکثر لوگ نہیں جانتے', NULL, NULL, '90c3b149e674a4727b32b7c3feed1001df57c84bf73ce56fb21beb6112a9f731'),
  ('ur.jalandhry', 40, 58, 4191, 'اور اندھا اور آنکھ والا برابر نہیں۔ اور نہ ایمان لانے والے نیکوکار اور نہ بدکار (برابر ہیں) (حقیقت یہ ہے کہ) تم بہت کم غور کرتے ہو', NULL, NULL, '25b439e6b2d9e65de6054c49299d910ae54b63228c1e96a42e91ffb6d1eb0fe4'),
  ('ur.jalandhry', 40, 59, 4192, 'قیامت آنے والی ہے اس میں کچھ شک نہیں۔ لیکن اکثر لوگ ایمان نہیں رکھتے', NULL, NULL, 'f4a51c432b6e848c2fd58cc48d428c30d2c8f1e136ec226353fcc89a52acf6bd'),
  ('ur.jalandhry', 40, 60, 4193, 'اور تمہارے پروردگار نے کہا ہے کہ تم مجھ سے دعا کرو میں تمہاری (دعا) قبول کروں گا۔ جو لوگ میری عبادت سے ازراہ تکبر کنیاتے ہیں۔ عنقریب جہنم میں ذلیل ہو کر داخل ہوں گے', NULL, NULL, '45d6931b80178f0743962e1fedeb6da556031707d917084cad4676845736ee38'),
  ('ur.jalandhry', 40, 61, 4194, 'خدا ہی تو ہے جس نے تمہارے لئے رات بنائی کہ اس میں آرام کرو اور دن کو روشن بنایا (کہ اس میں کام کرو) بےشک خدا لوگوں پر فضل کرنے والا ہے۔ لیکن اکثر لوگ شکر نہیں کرتے', NULL, NULL, '4c94548ccd72b7a2776a63413060c0cbe4a3c65ff6d3f2a9e0982e363b9563a3'),
  ('ur.jalandhry', 40, 62, 4195, 'یہی خدا تمہارا پروردگار ہے جو ہر چیز کا پیدا کرنے والا ہے۔ اس کے سوا کوئی معبود نہیں پھر تم کہاں بھٹک رہے ہو؟', NULL, NULL, '4dfc717d273033ae9862203f35322b2c8316a9082d532a994ff681fcbb3e1a96'),
  ('ur.jalandhry', 40, 63, 4196, 'اسی طرح وہ لوگ بھٹک رہے تھے جو خدا کی آیتوں سے انکار کرتے تھے', NULL, NULL, 'd6aaaaae58f04018697d2e489023720bdc8f317908a7595bb8632af7c5cd6de5'),
  ('ur.jalandhry', 40, 64, 4197, 'خدا ہی تو ہے جس نے زمین کو تمہارے لئے ٹھیرنے کی جگہ اور آسمان کو چھت بنایا اور تمہاری صورتیں بنائیں اور صورتیں بھی خوب بنائیں اور تمہیں پاکیزہ چیزیں کھانے کو دیں۔ یہی خدا تمہارا پروردگار ہے۔ پس خدائے پروردگار عالم بہت ہی بابرکت ہے', NULL, NULL, 'be9598926c83b4fe7d220ca5126393429c136d3d72b488ebfde75a8510baf636'),
  ('ur.jalandhry', 40, 65, 4198, 'وہ زندہ ہے (جسے موت نہیں) اس کے سوا کوئی عبادت کے لائق نہیں تو اس کی عبادت کو خالص کر کر اسی کو پکارو۔ ہر طرح کی تعریف خدا ہی کو (سزاوار) ہے جو تمام جہان کا پروردگار ہے', NULL, NULL, '57a5cc1c7902b8136d8fc31c3d4a4273ab587ba2254ab746f783251765d7b9ff'),
  ('ur.jalandhry', 40, 66, 4199, '(اے محمدﷺ ان سے) کہہ دو کہ مجھے اس بات کی ممانعت کی گئی ہے کہ جن کو تم خدا کے سوا پکارتے ہو ان کی پرستش کروں (اور میں ان کی کیونکر پرستش کروں) جب کہ میرے پاس میرے پروردگار (کی طرف) سے کھلی دلیلیں آچکی ہیں اور مجھ کو یہ حکم ہوا ہے کہ پروردگار عالم ہی کا تابع فرمان ہوں', NULL, NULL, 'be58d0931903b4a5ad0d3fe514bbaf0b396512683cba580aefe83ffd72b1346b'),
  ('ur.jalandhry', 40, 67, 4200, 'وہی تو ہے جس نے تم کو (پہلے) مٹی سے پیدا کیا۔ ہھر نطفہ بنا کر پھر لوتھڑا بنا کر پھر تم کو نکالتا ہے (کہ تم) بچّے (ہوتے ہو) پھر تم اپنی جوانی کو پہنچتے ہو۔ پھر بوڑھے ہوجاتے ہو۔ اور کوئی تم میں سے پہلے ہی مرجاتا ہے اور تم (موت کے) وقت مقرر تک پہنچ جاتے ہو اور تاکہ تم سمجھو', NULL, NULL, '878d040a53fdddb920317090aa1e6f7c19ebc5c903b29fe1da231d3ea24cf984')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 40, 68, 4201, 'وہی تو ہے جو جلاتا ہے اور مارتا ہے۔ پھر جب وہ کوئی کام کرنا (اور کسی کو پیدا کرنا) چاہتا ہے تو اس سے کہہ دیتا ہے کہ ہوجا تو وہ جاتا ہے', NULL, NULL, '884b73e52fe735c305b761d614add68dd05b793226cbe6fbfae430311d728bc3'),
  ('ur.jalandhry', 40, 69, 4202, 'کیا تم نے ان لوگوں کو نہیں دیکھا جو خدا کی آیتوں میں جھگڑتے ہیں۔ یہ کہاں بھٹک رہے ہیں؟', NULL, NULL, 'b29e5c6728c3e80f3a461b79d5e77234e9b67e5a2b949af66bbee92256f91e1c'),
  ('ur.jalandhry', 40, 70, 4203, 'جن لوگوں نے کتاب (خدا) کو اور جو کچھ ہم نے پیغمبروں کو دے کر بھیجا اس کو جھٹلایا۔ وہ عنقریب معلوم کرلیں گے', NULL, NULL, 'aeff97fb96504fc3a8469a60a2450a72a8cc6579cad27d5b75e72fa4f872c98e'),
  ('ur.jalandhry', 40, 71, 4204, 'جب کہ ان کی گردنوں میں طوق اور زنجیریں ہوں گی (اور) گھسیٹے جائیں گے', NULL, NULL, '67b16ea067de4da2cbdf525ea298a1322d853182ba983b7c7bb26c7eec792ca5'),
  ('ur.jalandhry', 40, 72, 4205, '(یعنی) کھولتے ہوئے پانی میں۔ پھر آگ میں جھونک دیئے جائیں گے', NULL, NULL, '9bc2be52323ac8edb8e1823a4bb26a5e1da13482efc37675c1cb1fb0f1edd763'),
  ('ur.jalandhry', 40, 73, 4206, 'پھر ان سے کہا جائے گا کہ وہ کہاں ہیں جن کو تم (خدا کے) شریک بناتے تھے', NULL, NULL, 'e724620dd8bdd27c2e791f1d884fff59ae44837ebc374d619d87f2be5c51936d'),
  ('ur.jalandhry', 40, 74, 4207, '(یعنی غیر خدا) کہیں گے وہ تو ہم سے جاتے رہے بلکہ ہم تو پہلے کسی چیز کو پکارتے ہی نہیں تھے۔ اسی طرح خدا کافروں کو گمراہ کرتا ہے', NULL, NULL, 'f1e06f9476c30d67432229f5d732caee12c1620621660400dc9be3acb2f961a4'),
  ('ur.jalandhry', 40, 75, 4208, 'یہ اس کا بدلہ ہے کہ تم زمین میں حق کے بغیر (یعنی اس کے خلاف) خوش ہوا کرتے تھے اور اس کی (سزا ہے) کہ اترایا کرتے تھے', NULL, NULL, '535458c6b41f2278952b11649d96a7ad0b05cbeb7ef46f7fd3ab49db5613b8c9'),
  ('ur.jalandhry', 40, 76, 4209, '(اب) جہنم کے دروازوں میں داخل ہوجاؤ۔ ہمیشہ اسی میں رہو گے۔ متکبروں کا کیا برا ٹھکانا ہے', NULL, NULL, '39b8b53a69e1c2b66d30d4e4f1c3cbd75c0a7fbd87c209e4f9eee0f9ce230f11'),
  ('ur.jalandhry', 40, 77, 4210, 'تو (اے پیغمبر) صبر کرو خدا کا وعدہ سچا ہے۔ اگر ہم تم کو کچھ اس میں سے دکھادیں جس کا ہم تم سے وعدہ کرتے ہیں۔ (یعنی کافروں پر عذاب نازل کریں) یا تمہاری مدت حیات پوری کردیں تو ان کو ہماری ہی طرف لوٹ کر آنا ہے', NULL, NULL, '22ac2ac166e703e81d2cefd65b6fba0c92e8365fd6086f9e0ec7d79dbf5c40cd'),
  ('ur.jalandhry', 40, 78, 4211, 'اور ہم نے تم سے پہلے (بہت سے) پیغمبر بھیجے۔ ان میں کچھ تو ایسے ہیں جن کے حالات تم سے بیان کر دیئے ہیں اور کچھ ایسے ہیں جن کے حالات بیان نہیں کئے۔ اور کسی پیغمبر کا مقدور نہ تھا کہ خدا کے حکم کے سوا کوئی نشانی لائے۔ پھر جب خدا کا حکم آپہنچا تو انصاف کے ساتھ فیصلہ کردیا گیا اور اہل باطل نقصان میں پڑ گئے', NULL, NULL, '89656b330d76a0754e2ae3da83dd432b9225560a1150437dafb4f30d5a8043c0'),
  ('ur.jalandhry', 40, 79, 4212, 'خدا ہی تو ہے جس نے تمہارے لئے چارپائے بنائے تاکہ ان میں سے بعض پر سوار ہو اور بعض کو تم کھاتے ہو', NULL, NULL, 'ca450ba7e530ab0f6967eaeb6ac1f739d817e47cdd95aef5995c2204a4c4eada'),
  ('ur.jalandhry', 40, 80, 4213, 'اور تمہارے لئے ان میں (اور بھی) فائدے ہیں اور اس لئے بھی کہ (کہیں جانے کی) تمہارے دلوں میں جو حاجت ہو ان پر (چڑھ کر وہاں) پہنچ جاؤ۔ اور ان پر اور کشتیوں پر تم سوار ہوتے ہو', NULL, NULL, 'a865aca7daff4efd130ebc33ecc356b8b78001a153e0da00e08adcd95c142371'),
  ('ur.jalandhry', 40, 81, 4214, 'اور وہ تمہیں اپنی نشانیاں دکھاتا ہے تو تم خدا کی کن کن نشانیوں کو نہ مانو گے', NULL, NULL, 'e135c944c05503d75fb74175581e1511ab1dad4d179e9ba5c35e9e57f971d555'),
  ('ur.jalandhry', 40, 82, 4215, 'کیا ان لوگوں نے زمین میں سیر نہیں کی تاکہ دیکھتے جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا۔ (حالانکہ) وہ ان سے کہیں زیادہ طاقتور اور زمین میں نشانات (بنانے) کے اعتبار سے بہت بڑھ کر تھے۔ تو جو کچھ وہ کرتے تھے وہ ان کے کچھ کام نہ آیا', NULL, NULL, 'ff1c22cdfbb8221881c5a881ea1f6097183e7648ce6c48d9d1e57dae127ab1c7'),
  ('ur.jalandhry', 40, 83, 4216, 'اور جب ان کے پیغمبر ان کے پاس کھلی نشانیاں لے کر آئے تو جو علم (اپنے خیال میں) ان کے پاس تھا اس پر اترانے لگے اور جس چیز سے تمسخر کیا کرتے تھے اس نے ان کو آ گھیرا', NULL, NULL, '426f23993d3b57325f2f466d9dd2b97464cb7f4251102fd773fe27be3a2ebc63'),
  ('ur.jalandhry', 40, 84, 4217, 'پھر جب انہوں نے ہمارا عذاب دیکھ لیا تو کہنے لگے کہ ہم خدائے واحد پر ایمان لائے اور جس چیز کو اس کے ساتھ شریک بناتے تھے اس سے نامعتقد ہوئے', NULL, NULL, '02afb098e30813fc633e8d9f46c1448be81fe53f188ce3098aea5d844b703dbe'),
  ('ur.jalandhry', 40, 85, 4218, 'لیکن جب وہ ہمارا عذاب دیکھ چکے (اس وقت) ان کے ایمان نے ان کو کچھ بھی فائدہ نہ دیا۔ (یہ) خدا کی عادت (ہے) جو اس کے بندوں (کے بارے) میں چلی آتی ہے۔ اور وہاں کافر گھاٹے میں پڑ گئے', NULL, NULL, '358f1209c0f1c2a7549a6d96e25fd7ceab5310226df318b9d973cabcaccdfda5'),
  ('ur.jalandhry', 41, 1, 4219, 'حٰم', NULL, NULL, 'd986ffe3c6d7ee25895888ccc3f155e8bc4ee20bae5d426418522f2a94027657'),
  ('ur.jalandhry', 41, 2, 4220, '(یہ کتاب خدائے) رحمٰن ورحیم (کی طرف) سے اُتری ہے', NULL, NULL, 'b140860327f90d78eb4b43518197fd2455d35658a48171129a70015c452fbc3d'),
  ('ur.jalandhry', 41, 3, 4221, 'کتاب جس کی آیتیں واضح (المعانی) ہیں (یعنی) قرآن عربی ان لوگوں کے لئے جو سمجھ رکھتے ہیں', NULL, NULL, 'deb894792b56c251834d1de9b9f600480b61f8685d79eeb5c2c241f0f6c5a901'),
  ('ur.jalandhry', 41, 4, 4222, 'جو بشارت بھی سناتا ہے اور خوف بھی دلاتا ہے لیکن ان میں سے اکثروں نے منہ پھیر لیا اور وہ سنتے ہی نہیں', NULL, NULL, '8cfae60e1cc7e4a60506cfd17f848c5fa026cfc7ab0e0a83677854c503b933e0'),
  ('ur.jalandhry', 41, 5, 4223, 'اور کہتے ہیں کہ جس چیز کی طرف تم ہمیں بلاتے ہو اس سے ہمارے دل پردوں میں ہیں اور ہمارے کانوں میں بوجھ (یعنی بہراپن) ہے اور ہمارے اور تمہارے درمیان پردہ ہے تو تم (اپنا) کام کرو ہم (اپنا) کام کرتے ہیں', NULL, NULL, 'e8d946bb82bc92f4a0e46087461b4713b6ff3ac06a12de0521e640a830114f06'),
  ('ur.jalandhry', 41, 6, 4224, 'کہہ دو کہ میں بھی آدمی ہوں جیسے تم۔ (ہاں) مجھ پر یہ وحی آتی ہے کہ تمہارا معبود خدائے واحد ہے تو سیدھے اسی کی طرف (متوجہ) رہو اور اسی سے مغفرت مانگو اور مشرکوں پر افسوس ہے', NULL, NULL, 'd54ac387225d013cbae326dc9c0d80c4084aa69424489c9efe8a29ed2d948660'),
  ('ur.jalandhry', 41, 7, 4225, 'جو زکوٰة نہیں دیتے اور آخرت کے بھی قائل نہیں', NULL, NULL, 'eb773734b5e0471c2aa323faa6407e83375b3b9f36dbff1bafb62eb92f2c9f01'),
  ('ur.jalandhry', 41, 8, 4226, 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے ان کے لئے (ایسا) ثواب ہے جو ختم ہی نہ ہو', NULL, NULL, 'db3cd9cad256570f1c7e910af19fa6ea619dda4beeba6e9ccc2ecb3609550080'),
  ('ur.jalandhry', 41, 9, 4227, 'کہو کیا تم اس سے انکار کرتے ہو جس نے زمین کو دو دن میں پیدا کیا۔ اور (بتوں کو) اس کا مدمقابل بناتے ہو۔ وہی تو سارے جہان کا مالک ہے', NULL, NULL, 'c3dc19c43f6db8f7cd845249f1f36b483f3b6aa5f7b58caa54747ef960e19b3d'),
  ('ur.jalandhry', 41, 10, 4228, 'اور اسی نے زمین میں اس کے اوپر پہاڑ بنائے اور زمین میں برکت رکھی اور اس میں سب سامان معیشت مقرر کیا (سب) چار دن میں۔ (اور تمام) طلبگاروں کے لئے یکساں', NULL, NULL, '6591bc23dc76145634d82e7d94ad9316f44ce39daa5ab7dbd641f5f11041dc7c'),
  ('ur.jalandhry', 41, 11, 4229, 'پھر آسمان کی طرف متوجہ ہوا اور وہ دھواں تھا تو اس نے اس سے اور زمین سے فرمایا کہ دونوں آؤ (خواہ) خوشی سے خواہ ناخوشی سے۔ انہوں نے کہا کہ ہم خوشی سے آتے ہیں', NULL, NULL, 'eab8e21b07c0a848f5f8d4093f7a0bf9eacf4f39b5bdf70cfbd6b9d9088b0a96'),
  ('ur.jalandhry', 41, 12, 4230, 'پھر دو دن میں سات آسمان بنائے اور ہر آسمان میں اس (کے کام) کا حکم بھیجا اور ہم نے آسمان دنیا کو چراغوں (یعنی ستاروں) سے مزین کیا اور (شیطانوں سے) محفوظ رکھا۔ یہ زبردست (اور) خبردار کے (مقرر کئے ہوئے) اندازے ہیں', NULL, NULL, '2c2cd992d8e3c169dc2e8978ca501a21ef0c9196a1a86801a54e10e8f3627a83'),
  ('ur.jalandhry', 41, 13, 4231, 'پھر اگر یہ منہ پھیر لیں تو کہہ دو کہ میں تم کو ایسے چنگھاڑ (کے عذاب) سے آگاہ کرتا ہوں جیسے عاد اور ثمود پر چنگھاڑ (کا عذاب آیا تھا)', NULL, NULL, '02cfd20cffcf6cc9c3a22ac762490a1cc1fb7eaf85b9a63a95e11575e4e666af'),
  ('ur.jalandhry', 41, 14, 4232, 'جب ان کے پاس پیغمبر ان کے آگے اور پیچھے سے آئے کہ خدا کے سوا (کسی کی) عبادت نہ کرو۔ کہنے لگے کہ اگر ہمارا پروردگار چاہتا تو فرشتے اُتار دیتا سو جو تم دے کر بھیجے گئے ہو ہم اس کو نہیں مانتے', NULL, NULL, '4e072786269afc81d35843f5457c48e1d34a4d3c33c8f7cc71f1ee70378a2cc9'),
  ('ur.jalandhry', 41, 15, 4233, 'جو عاد تھے وہ ناحق ملک میں غرور کرنے لگے اور کہنے لگے کہ ہم سے بڑھ کر قوت میں کون ہے؟ کیا انہوں نے نہیں دیکھا کہ خدا جس نے ان کو پیدا کیا وہ ان سے قوت میں بہت بڑھ کر ہے۔ اور وہ ہماری آیتوں سے انکار کرتے رہے', NULL, NULL, '5645c74643e3d86c1c5973357824c5ce3659ac73c5bba436c430f3e1c4219090'),
  ('ur.jalandhry', 41, 16, 4234, 'تو ہم نے بھی ان پر نحوست کے دنوں میں زور کی ہوا چلائی تاکہ ان کو دنیا کی زندگی میں ذلت کے عذاب کا مزہ چکھا دیں۔ اور آخرت کا عذاب تو بہت ہی ذلیل کرنے والا ہے اور (اس روز) ان کو مدد بھی نہ ملے گی', NULL, NULL, 'c0981c8a17b885e88531b25b6b1fe8bfe887e097cf92d3f88b4d7c0fb159c2ae'),
  ('ur.jalandhry', 41, 17, 4235, 'اور جو ثمود تھے ان کو ہم نے سیدھا رستہ دکھا دیا تھا مگر انہوں نے ہدایت کے مقابلے میں اندھا دھند رہنا پسند کیا تو ان کے اعمال کی سزا میں کڑک نے ان کو آپکڑا۔ اور وہ ذلت کا عذاب تھا', NULL, NULL, '4d8583f4a661b9c69c5c9e24d093b6d1ed31d6f645919441e5fc217ae7f7555a'),
  ('ur.jalandhry', 41, 18, 4236, 'اور جو ایمان لائے اور پرہیزگاری کرتے رہے ان کو ہم نے بچا لیا', NULL, NULL, '761f14ea51836d7e6b63ec09b8500c52d1a49c20d2262c504d588d5536b9ccf1'),
  ('ur.jalandhry', 41, 19, 4237, 'اور جس دن خدا کے دشمن دوزخ کی طرف چلائے جائیں گے تو ترتیب وار کرلیئے جائیں گے', NULL, NULL, 'abaac027e7f1c11304696be295fc02bf0b263889a829ce2f774a3a87cd9b3339'),
  ('ur.jalandhry', 41, 20, 4238, 'یہاں تک کہ جب اس کے پاس پہنچ جائیں گے تو ان کے کان اور آنکھیں اور چمڑے (یعنی دوسرے اعضا) ان کے خلاف ان کے اعمال کی شہادت دیں گے', NULL, NULL, '3401ef9dd70379e1217511a37854ca04bcea7325f8e759f658f383d414ba3d08'),
  ('ur.jalandhry', 41, 21, 4239, 'اور وہ اپنے چمڑوں (یعنی اعضا) سے کہیں گے کہ تم نے ہمارے خلاف کیوں شہادت دی؟ وہ کہیں گے کہ جس خدا نے سب چیزوں کو نطق بخشا اسی نے ہم کو بھی گویائی دی اور اسی نے تم کو پہلی بار پیدا کیا تھا اور اسی کی طرف تم کو لوٹ کر جانا ہے', NULL, NULL, '77ceae44a4885d59f0e9a4c2a15c35236fa07db8dfabee5ce242afb2c41dbf19'),
  ('ur.jalandhry', 41, 22, 4240, 'اور تم اس (بات کے خوف) سے تو پردہ نہیں کرتے تھے کہ تمہارے کان اور تمہاری آنکھیں اور چمڑے تمہارے خلاف شہادت دیں گے بلکہ تم یہ خیال کرتے تھے کہ خدا کو تمہارے بہت سے عملوں کی خبر ہی نہیں', NULL, NULL, 'c9f79f90071b3d61c06a3f07a00552f4e14f414a4301b232348a928dc58d0960'),
  ('ur.jalandhry', 41, 23, 4241, 'اور اسی خیال نے جو تم اپنے پروردگار کے بارے میں رکھتے تھے تم کو ہلاک کردیا اور تم خسارہ پانے والوں میں ہوگئے', NULL, NULL, '30cf152d6541a650694ad154650530c961aeada670a2a864f920c2ba1b8df358'),
  ('ur.jalandhry', 41, 24, 4242, 'اب اگر یہ صبر کریں گے تو ان کا ٹھکانا دوزخ ہے۔ اور اگر توبہ کریں گے تو ان کی توبہ قبول نہیں کی جائے گی', NULL, NULL, '4f132895b4646d7b69a1f48222f7f0c43cd233389f1f57849a31c960eb5d4f96'),
  ('ur.jalandhry', 41, 25, 4243, 'اور ہم نے (شیطانوں کو) ان کا ہم نشین مقرر کردیا تھا تو انہوں نے ان کے اگلے اور پچھلے اعمال ان کو عمدہ کر دکھائے تھے اور جنات اور انسانوں کی جماعتیں جو ان سے پہلے گذر چکیں ان پر بھی خدا (کے عذاب) کا وعدہ پورا ہوگیا۔ بےشک یہ نقصان اٹھانے والے ہیں', NULL, NULL, '954ae0f3a3b70744e170361e5da345336660ff321e51524710f0a9a4532b9a53'),
  ('ur.jalandhry', 41, 26, 4244, 'اور کافر کہنے لگے کہ اس قرآن کو سنا ہی نہ کرو اور (جب پڑھنے لگیں تو) شور مچا دیا کرو تاکہ تم غالب رہو', NULL, NULL, '813082758f63a5b301e9b64aeda643993b5f41a53042e6eb02bafe2d7fcd87dc'),
  ('ur.jalandhry', 41, 27, 4245, 'سو ہم بھی کافروں کو سخت عذاب کے مزے چکھائیں گے اور ان کے برے عملوں کی جو وہ کرتے تھے سزا دیں گے', NULL, NULL, '0d102cc880008de64e9661d3343798bed6869477ce66e2a675b9dd6ad77f8fef'),
  ('ur.jalandhry', 41, 28, 4246, 'یہ خدا کے دشمنوں کا بدلہ ہے (یعنی) دوزخ۔ ان کے لئے اسی میں ہمیشہ کا گھر ہے۔ یہ اس کی سزا ہے کہ ہماری آیتوں سے انکار کرتے تھے', NULL, NULL, '84087d526cdb2ea56017aba366808d002f64fc59bdcf2d65a69ccde54dde7c9b'),
  ('ur.jalandhry', 41, 29, 4247, 'اور کافر کہیں گے کہ اے ہمارے پروردگار جنوں اور انسانوں میں سے جن لوگوں نے ہم کو گمراہ کیا تھا ان کو ہمیں دکھا کہ ہم ان کو اپنے پاؤں کے تلے (روند) ڈالیں تاکہ وہ نہایت ذلیل ہوں', NULL, NULL, 'f3f99135f6d66250f2705080ca20e79581291d7f54d638282c5e023e0d91540b'),
  ('ur.jalandhry', 41, 30, 4248, 'جن لوگوں نے کہا کہ ہمارا پروردگار خدا ہے پھر وہ (اس پر) قائم رہے ان پر فرشتے اُتریں گے (اور کہیں گے) کہ نہ خوف کرو اور نہ غمناک ہو اور بہشت کی جس کا تم سے وعدہ کیا جاتا تھا خوشی مناؤ', NULL, NULL, '3c598f3b27e93a2d3984d121011ec7f8cc0efb30fa618671e16533447fe6a79c'),
  ('ur.jalandhry', 41, 31, 4249, 'ہم دنیا کی زندگی میں بھی تمہارے دوست تھے اور آخرت میں بھی (تمہارے رفیق ہیں) ۔ اور وہاں جس (نعمت) کو تمہارا جی چاہے گا تم کو (ملے گی) اور جو چیز طلب کرو گے تمہارے لئے (موجود ہوگی)', NULL, NULL, 'd10ddffe80e0902d171869aa2dc65cfacd38dab24bb73af45bd99d5951ae7a2a'),
  ('ur.jalandhry', 41, 32, 4250, '(یہ) بخشنے والے مہربان کی طرف سے مہمانی ہے', NULL, NULL, '389ce99f98a5b3cd02b238ce44e83de529b7df2df8626e3b62536db234896da6'),
  ('ur.jalandhry', 41, 33, 4251, 'اور اس شخص سے بات کا اچھا کون ہوسکتا ہے جو خدا کی طرف بلائے اور عمل نیک کرے اور کہے کہ میں مسلمان ہوں', NULL, NULL, '1c332ee645bcfceec711722193ca128c33ec573c8fc3bc6202ab467893cf5841'),
  ('ur.jalandhry', 41, 34, 4252, 'اور بھلائی اور برائی برابر نہیں ہوسکتی۔ تو (سخت کلامی کا) ایسے طریق سے جواب دو جو بہت اچھا ہو (ایسا کرنے سے تم دیکھو گے) کہ جس میں اور تم میں دشمنی تھی گویا وہ تمہارا گرم جوش دوست ہے', NULL, NULL, '9fd4f60ba4919180d843b373cd5c5c4f5b8cfe139f1e2c18cabb5ce9a03b110f'),
  ('ur.jalandhry', 41, 35, 4253, 'اور یہ بات ان ہی لوگوں کو حاصل ہوتی ہے جو برداشت کرنے والے ہیں۔ اور ان ہی کو نصیب ہوتی ہے جو بڑے صاحب نصیب ہیں', NULL, NULL, '44f3a2b477a190d718a3306af69a1022916372c46ab16cc4c0db6e9d3232fc23'),
  ('ur.jalandhry', 41, 36, 4254, 'اور اگر تمہیں شیطان کی جانب سے کوئی وسوسہ پیدا ہو تو خدا کی پناہ مانگ لیا کرو۔ بےشک وہ سنتا جانتا ہے', NULL, NULL, 'cd76299f6f285650a0f6bc6b1bca107b0f96009d89d8800918dd9b907d021473'),
  ('ur.jalandhry', 41, 37, 4255, 'اور رات اور دن اور سورج اور چاند اس کی نشانیوں میں سے ہیں۔ تم لوگ نہ تو سورج کو سجدہ کرو اور نہ چاند کو۔ بلکہ خدا ہی کو سجدہ کرو جس نے ان چیزوں کو پیدا کیا ہے اگر تم کو اس کی عبادت منظور ہے', NULL, NULL, 'cfcf63f295bbdaf7e2e24608de7a3d8bfee88371e940c32669bae57e6cc0c3a9'),
  ('ur.jalandhry', 41, 38, 4256, 'اگر یہ لوگ سرکشی کریں تو (خدا کو بھی ان کی پروا نہیں) جو (فرشتے) تمہارے پروردگار کے پاس ہیں وہ رات دن اس کی تسبیح کرتے رہتے ہیں اور (کبھی) تھکتے ہی نہیں', NULL, NULL, 'aab264fc1c0dcdfc6723f83a6db8a6b2bdc38d53663ff5a780db2f41788295bb'),
  ('ur.jalandhry', 41, 39, 4257, 'اور (اے بندے یہ) اسی کی قدرت کے نمونے ہیں کہ تو زمین کو دبی ہوئی (یعنی خشک) دیکھتا ہے۔ جب ہم اس پر پانی برسا دیتے ہیں تو شاداب ہوجاتی اور پھولنے لگتی ہے تو جس نے زمین کو زندہ کیا وہی مردوں کو زندہ کرنے والا ہے۔ بےشک وہ ہر چیز پر قادر ہے', NULL, NULL, '84dcc25dff9d6cd70a7aa4b6ef5c9cb01a2335ddf32c20d6625c5482a2db5c5c'),
  ('ur.jalandhry', 41, 40, 4258, 'جو لوگ ہماری آیتوں میں کج راہی کرتے ہیں وہ ہم سے پوشیدہ نہیں ہیں۔ بھلا جو شخص دوزخ میں ڈالا جائے وہ بہتر ہے یا وہ جو قیامت کے دن امن وامان سے آئے۔ (تو خیر) جو چاہو سو کرلو۔ جو کچھ تم کرتے ہو وہ اس کو دیکھ رہا ہے', NULL, NULL, 'c255392a8ac6244e5e730272979a89d750aed92866f610c12e2fd90919bbed2f'),
  ('ur.jalandhry', 41, 41, 4259, 'جن لوگوں نے نصیحت کو نہ مانا جب وہ ان کے پاس آئی۔ اور یہ تو ایک عالی رتبہ کتاب ہے', NULL, NULL, '328159151a0bcb80ed95e9b3f09a0fb6febbbad5bbfbcf1749a1a57c424c2458'),
  ('ur.jalandhry', 41, 42, 4260, 'اس پر جھوٹ کا دخل نہ آگے سے ہوسکتا ہے نہ پیچھے سے۔ (اور) دانا (اور) خوبیوں والے (خدا) کی اُتاری ہوئی ہے', NULL, NULL, '4f1454138d47f997b0908109072a05ce3944c1504536764d22b6e875c1482134'),
  ('ur.jalandhry', 41, 43, 4261, 'تم سے وہی باتیں کہیں جاتی ہیں جو تم سے پہلے اور پیغمبروں سے کہی گئی تھیں۔ بےشک تمہارا پروردگار بخش دینے والا بھی اور عذاب الیم دینے والا بھی ہے', NULL, NULL, '162997e03ce7c869afb1a428e42b5f2345ea18bb15ca70f4f0bf602ffece373a'),
  ('ur.jalandhry', 41, 44, 4262, 'اور اگر ہم اس قرآن کو غیر زبان عرب میں (نازل) کرتے تو یہ لوگ کہتے کہ اس کی آیتیں (ہماری زبان میں) کیوں کھول کر بیان نہیں کی گئیں۔ کیا (خوب کہ قرآن تو) عجمی اور (مخاطب) عربی۔ کہہ دو کہ جو ایمان لاتے ہیں ان کے لئے (یہ) ہدایت اور شفا ہے۔ اور جو ایمان نہیں لاتے ان کے کانوں میں گرانی (یعنی بہراپن) ہے اور یہ ان کے حق میں (موجب) نابینائی ہے۔ گرانی کے سبب ان کو (گویا) دور جگہ سے آواز دی جاتی ہے', NULL, NULL, '18efc78e975f34f583575e375b2a3d57670c7c6dab2079eca5b117953e40525a'),
  ('ur.jalandhry', 41, 45, 4263, 'اور ہم نے موسیٰ کو کتاب دی تو اس میں اختلاف کیا گیا۔ اور اگر تمہارے پروردگار کی طرف سے ایک بات پہلے نہ ٹھہر چکی ہوتی تو ان میں فیصلہ کردیا جاتا۔ اور یہ اس (قرآن) سے شک میں الجھ رہے ہیں', NULL, NULL, '74e291e3f79d448cb94cf3762658c04b4927ec66a41c003e74277ac9c0ba9da0'),
  ('ur.jalandhry', 41, 46, 4264, 'جو نیک کام کرے گا تو اپنے لئے۔ اور جو برے کام کرے گا تو ان کا ضرر اسی کو ہوگا۔ اور تمہارا پروردگار بندوں پر ظلم کرنے والا نہیں', NULL, NULL, '5853f4a2263e6442d910309377787fd54640aff75061fc29f3c6ffa079a280c8'),
  ('ur.jalandhry', 41, 47, 4265, 'قیامت کے علم کا حوالہ اسی کی طرف دیا جاتا ہے (یعنی قیامت کا علم اسی کو ہے) اور نہ تو پھل گا بھوں سے نکلتے ہیں اور نہ کوئی مادہ حاملہ ہوتی اور نہ جنتی ہے مگر اس کے علم سے۔ اور جس دن وہ ان کو پکارے گا (اور کہے گا) کہ میرے شریک کہاں ہیں تو وہ کہیں گے کہ ہم تجھ سے عرض کرتے ہیں کہ ہم میں سے کسی کو (ان کی) خبر ہی نہیں', NULL, NULL, 'b302d10f2826fb0ad2d019b8e23399618a44fad775128b178f487ce5a028bbba'),
  ('ur.jalandhry', 41, 48, 4266, 'اور جن کو پہلے وہ (خدا کے سوا) پکارا کرتے تھے (سب) ان سے غائب ہوجائیں گے اور وہ یقین کرلیں گے کہ ان کے لئے مخلصی نہیں', NULL, NULL, '66fc0d3172df9e549d701964ffe7884349f08ace451079c20cd6036d88ff42e9'),
  ('ur.jalandhry', 41, 49, 4267, 'انسان بھلائی کی دعائیں کرتا کرتا تو تھکتا نہیں اور اگر تکلیف پہنچ جاتی ہے تو ناامید ہوجاتا اور آس توڑ بیٹھتا ہے', NULL, NULL, '32dbe15920eb15cd162b907fe1fc10f96214fbf50c2173ff36adf714e34b5268'),
  ('ur.jalandhry', 41, 50, 4268, 'اور اگر تکلیف پہنچنے کے بعد ہم اس کو اپنی رحمت کا مزہ چکھاتے ہیں تو کہتا ہے کہ یہ تو میرا حق تھا اور میں نہیں خیال کرتا کہ قیامت برپا ہو۔ اور اگر (قیامت سچ مچ بھی ہو اور) میں اپنے پروردگار کی طرف لوٹایا بھی جاؤں تو میرے لئے اس کے ہاں بھی خوشحالی ہے۔ پس کافر جو عمل کیا کرتے وہ ہم ان کو ضرور جتائیں گے اور ان کو سخت عذاب کا مزہ چکھائیں گے', NULL, NULL, '8bc06c16591eb9dbb2fff460cb7656f2dec23ffc398b0147661ec3ce7da43f41'),
  ('ur.jalandhry', 41, 51, 4269, 'اور جب ہم انسان پر کرم کرتے ہیں تو منہ موڑ لیتا ہے اور پہلو پھیر کر چل دیتا ہے۔ اور جب اس کو تکلیف پہنچتی ہے تو لمبی لمبی دعائیں کرنے لگتا ہے', NULL, NULL, '2081423fab7af39d7221ed2361bea0194415e74e37f8d4ecea6177bd2bec3dc0'),
  ('ur.jalandhry', 41, 52, 4270, 'کہو کہ بھلا دیکھو اگر یہ (قرآن) خدا کی طرف سے ہو پھر تم اس سے انکار کرو تو اس سے بڑھ کر کون گمراہ ہے جو (حق کی) پرلے درجے کی مخالفت میں ہو', NULL, NULL, '432eb8497699b5a35711b281ef8e0338f58823b7f87e7c150003e299416e388d'),
  ('ur.jalandhry', 41, 53, 4271, 'ہم عنقریب ان کو اطراف (عالم) میں بھی اور خود ان کی ذات میں بھی اپنی نشانیاں دکھائیں گے یہاں تک کہ ان پر ظاہر ہوجائے گا کہ (قرآن) حق ہے۔ کیا تم کو یہ کافی نہیں کہ تمہارا پروردگار ہر چیز سے خبردار ہے', NULL, NULL, '0f2d3c0cac141b7bd4a45058201a1dd2ae09f35b6ae1a426ffb6ca9f1e348fe8'),
  ('ur.jalandhry', 41, 54, 4272, 'دیکھو یہ اپنے پروردگار کے روبرو حاضر ہونے سے شک میں ہیں۔ سن رکھو کہ وہ ہر چیز پر احاطہ کئے ہوئے ہے', NULL, NULL, 'b83ac6e3ef7d070abb2b1ca5635788031d943877692e9fa1b2028ace57c7d99a'),
  ('ur.jalandhry', 42, 1, 4273, 'حٰمٓ', NULL, NULL, 'c99bc71dbe738345118c60e4a78a3f87b6ad011c83cd5242746f6b8c168b12aa'),
  ('ur.jalandhry', 42, 2, 4274, 'عٓسٓقٓ', NULL, NULL, 'd80d6c3c7e2954717fe46d541d0a37a34fec17fed61d55b47a185a5988b0d035'),
  ('ur.jalandhry', 42, 3, 4275, 'خدائے غالب و دانا اسی طرح تمہاری طرف مضامین اور (براہین) بھیجتا ہے جس طرح تم سے پہلے لوگوں کی طرف وحی بھیجتا رہا ہے', NULL, NULL, 'ca2afea0f5ced8519015f5ba5c738dad74815934fb40a4928cbf20f843de9c98'),
  ('ur.jalandhry', 42, 4, 4276, 'جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے۔ اور وہ عالی رتبہ اور گرامی قدر ہے', NULL, NULL, 'fc4836721506e4441b7ee894e8fab5c4ae36c25a3a14d31e595c63560fe9b50a'),
  ('ur.jalandhry', 42, 5, 4277, 'قریب ہے کہ آسمان اوپر سے پھٹ پڑیں اور فرشتے اپنے پروردگار کی تعریف کے ساتھ اس کی تسبیج کرتے رہتے ہیں اور جو لوگ زمین میں ہیں ان کے لئے معافی مانگتے رہتے ہیں۔ سن رکھو کہ خدا بخشنے والا مہربان ہے', NULL, NULL, 'f10718afed85fada7e507aeed223e3f950e78f1fae6cae4331d0da38ea5f0731'),
  ('ur.jalandhry', 42, 6, 4278, 'اور جن لوگوں نے اس کے سوا کارساز بنا رکھے ہیں وہ خدا کو یاد ہیں۔ اور تم ان پر داروغہ نہیں ہو', NULL, NULL, '7a66c5b6df5b946e7c7bc7d1156e5f2d3652c811935ebdd8768f10f2ed10fabf'),
  ('ur.jalandhry', 42, 7, 4279, 'اور اسی طرح تمہارے پاس قرآن عربی بھیجا ہے تاکہ تم بڑے گاؤں (یعنی مکّے) کے رہنے والوں کو اور جو لوگ اس کے اردگرد رہتے ہیں ان کو رستہ دکھاؤ اور انہیں قیامت کے دن کا بھی جس میں کچھ شک نہیں ہے خوف دلاؤ۔ اس روز ایک فریق بہشت میں ہوگا اور ایک فریق دوزخ میں', NULL, NULL, '4f74b5f4eccbaf3d997688e3385afc04b2486971e10c44522d91d05b0dda73f8'),
  ('ur.jalandhry', 42, 8, 4280, 'اور اگر خدا چاہتا تو ان کو ایک ہی جماعت کردیتا لیکن وہ جس کو چاہتا ہے اپنی رحمت میں داخل کرلیتا ہے اور ظالموں کا نہ کوئی یار ہے اور نہ مددگار', NULL, NULL, '29c8edac78881955f72811d6eaf054a353244a8d84a45112c8ac9d5920caa202'),
  ('ur.jalandhry', 42, 9, 4281, 'کیا انہوں نے اس کے سوا کارساز بنائے ہیں؟ کارساز تو خدا ہی ہے اور وہی مردوں کو زندہ کرے گا اور وہ ہر چیز پر قدرت رکھتا ہے', NULL, NULL, 'cc41c9d080883e961ea8f05f9b2ad65122e6c39258238bcb937a3d96c6cd0d12'),
  ('ur.jalandhry', 42, 10, 4282, 'اور تم جس بات میں اختلاف کرتے ہو اس کا فیصلہ خدا کی طرف (سے ہوگا) یہی خدا میرا پروردگار ہے میں اسی پر بھروسہ رکھتا ہوں۔ اور اسی کی طرف رجوع کرتا ہوں', NULL, NULL, '651ae412c9942b5c2ea3925dad222bc79dd8a01e6888f4bf238fe530719d758d'),
  ('ur.jalandhry', 42, 11, 4283, 'آسمانوں اور زمین کا پیدا کرنے والا (وہی ہے) ۔ اسی نے تمہارے لئے تمہاری ہی جنس کے جوڑے بنائے اور چارپایوں کے بھی جوڑے (بنائے اور) اسی طریق پر تم کو پھیلاتا رہتا ہے۔ اس جیسی کوئی چیز نہیں۔ اور وہ دیکھتا سنتا ہے', NULL, NULL, '1c2329183fa36adfbfb04e3e6daa061228ea6c98816ad72f89aab6f36c9e733f'),
  ('ur.jalandhry', 42, 12, 4284, 'آسمانوں اور زمین کی کنجیاں اسی کے ہاتھ میں ہیں۔ وہ جس کے لئے چاہتا ہے رزق فراخ کردیتا ہے (اور جس کے لئے چاہتا ہے) تنگ کردیتا ہے۔ بےشک وہ ہر چیز سے واقف ہے', NULL, NULL, 'fcd228f6d3d43618c7f585ed8eda3fce85541d2b1d5b79c0bf051d67e14568f0'),
  ('ur.jalandhry', 42, 13, 4285, 'اسی نے تمہارے لئے دین کا وہی رستہ مقرر کیا جس (کے اختیار کرنے کا) نوح کو حکم دیا تھا اور جس کی (اے محمدﷺ) ہم نے تمہاری طرف وحی بھیجی ہے اور جس کا ابراہیم اور موسیٰ اور عیسیٰ کو حکم دیا تھا (وہ یہ) کہ دین کو قائم رکھنا اور اس میں پھوٹ نہ ڈالنا۔ جس چیز کی طرف تم مشرکوں کو بلاتے ہو وہ ان کو دشوار گزرتی ہے۔ الله جس کو چاہتا ہے اپنی بارگاہ کا برگزیدہ کرلیتا ہے اور جو اس کی طرف رجوع کرے اسے اپنی طرف رستہ دکھا دیتا ہے', NULL, NULL, '003a11209d7d65577b6e080f25e237bf339ff8dbe6d4e429babf67ffc26c0563'),
  ('ur.jalandhry', 42, 14, 4286, 'اور یہ لوگ جو الگ الگ ہوئے ہیں تو علم (حق) آچکنے کے بعد آپس کی ضد سے (ہوئے ہیں) ۔ اور اگر تمہارے پروردگار کی طرف سے ایک وقت مقرر تک کے لئے بات نہ ٹھہر چکی ہوتی تو ان میں فیصلہ کردیا جاتا۔ اور جو لوگ ان کے بعد (خدا کی) کتاب کے وارث ہوئے وہ اس (کی طرف) سے شبہے کی الجھن میں (پھنسے ہوئے) ہیں', NULL, NULL, '849596492091ec8f92c88c03e4cee0ff032edf6c6164cd35235271688f6e45f6'),
  ('ur.jalandhry', 42, 15, 4287, 'تو (اے محمدﷺ) اسی (دین کی) طرف (لوگوں کو) بلاتے رہنا اور جیسا تم کو حکم ہوا ہے (اسی پر) قائم رہنا۔ اور ان کی خواہشوں کی پیروی نہ کرنا۔ اور کہہ دو کہ جو کتاب خدا نے نازل فرمائی ہے میں اس پر ایمان رکھتا ہوں۔ اور مجھے حکم ہوا ہے کہ تم میں انصاف کروں۔ خدا ہی ہمارا اور تمہارا پروردگار ہے۔ ہم کو ہمارے اعمال (کا بدلہ ملے گا) اور تم کو تمہارے اعمال کا۔ ہم میں اور تم میں کچھ بحث وتکرار نہیں۔ خدا ہم (سب) کو اکھٹا کرے گا۔ اور اسی کی طرف لوٹ کر جانا ہے', NULL, NULL, 'cf15f369b77fef4ed5fc90b1a9493db4140694f2792c491582738e6c3df9344e'),
  ('ur.jalandhry', 42, 16, 4288, 'اور جو لوگ خدا (کے بارے) میں بعد اس کے کہ اسے (مومنوں نے) مان لیا ہو جھگڑتے ہیں ان کے پروردگار کے نزدیک ان کا جھگڑا لغو ہے۔ اور ان پر (خدا کا) غضب اور ان کے لئے سخت عذاب ہے', NULL, NULL, 'b0a42a60aecf081ff5cf33d279519a7d26497428980550a9a715cf5fb65532ca'),
  ('ur.jalandhry', 42, 17, 4289, 'خدا ہی تو ہے جس نے سچائی کے ساتھ کتاب نازل فرمائی اور (عدل وانصاف کی) ترازو۔ اور تم کو کیا معلوم شاید قیامت قریب ہی آ پہنچی ہو', NULL, NULL, '1e0e736b8f688d5db9c86623aed40a76475df3949742d4ac633b911703a68d21'),
  ('ur.jalandhry', 42, 18, 4290, 'جو لوگ اس پر ایمان نہیں رکھتے وہ اس کے لئے جلدی کر رہے ہیں۔ اور جو مومن ہیں وہ اس سے ڈرتے ہیں۔ اور جانتے ہیں کہ وہ برحق ہے۔ دیکھو جو لوگ قیامت میں جھگڑتے ہیں وہ پرلے درجے کی گمراہی میں ہیں', NULL, NULL, '0ec4d33e3a3404a832535913e9732c5f2deb0cb708eda3036c5ff73f016c162c'),
  ('ur.jalandhry', 42, 19, 4291, 'خدا اپنے بندوں پر مہربان ہے وہ جس کو چاہتا ہے رزق دیتا ہے۔ اور وہ زور والا (اور) زبردست ہے', NULL, NULL, '79ba3fd87ac656cc77318d3601f6159204bdf37d1644264f63ff3cb3eb1f4a16'),
  ('ur.jalandhry', 42, 20, 4292, 'جو شخص آخرت کی کھیتی کا خواستگار ہو اس کو ہم اس میں سے دیں گے۔ اور جو دنیا کی کھیتی کا خواستگار ہو اس کو ہم اس میں سے دے دیں گے۔ اور اس کا آخرت میں کچھ حصہ نہ ہوگا', NULL, NULL, '02014ce4dacc74b1459e88676b7669033b795cddb7ba2a5f1a4dbfd64d57541b'),
  ('ur.jalandhry', 42, 21, 4293, 'کیا ان کے وہ شریک ہیں جنہوں نے ان کے لئے ایسا دین مقرر کیا ہے جس کا خدا نے حکم نہیں دیا۔ اور اگر فیصلے (کے دن) کا وعدہ نہ ہوتا تو ان میں فیصلہ کردیا جاتا اور جو ظالم ہیں ان کے لئے درد دینے والا عذاب ہے', NULL, NULL, 'e9e54d6943cd519252af82ffeb5ea1dab437ce061831864bfeddfb083f8690dd'),
  ('ur.jalandhry', 42, 22, 4294, 'تم دیکھو گے کہ ظالم اپنے اعمال (کے وبال) سے ڈر رہے ہوں گے اور وہ ان پر پڑے گا۔ اور جو لوگ ایمان لائے اور نیک عمل کرتے رہے وہ بہشت کے باغوں میں ہوں گے۔ وہ جو کچھ چاہیں گے ان کے لیے ان کے پروردگار کے پاس (موجود) ہوگا۔ یہی بڑا فضل ہے', NULL, NULL, 'f0777abc150f0613be54017dd07127c9439eb73b4dd958e178679c2918326c3a'),
  ('ur.jalandhry', 42, 23, 4295, 'یہی وہ (انعام ہے) جس کی خدا اپنے ان بندوں کو جو ایمان لاتے اور عمل نیک کرتے ہیں بشارت دیتا ہے۔ کہہ دو کہ میں اس کا تم سے صلہ نہیں مانگتا مگر (تم کو) قرابت کی محبت (تو چاہیئے) اور جو کوئی نیکی کرے گا ہم اس کے لئے اس میں ثواب بڑھائیں گے۔ بےشک خدا بخشنے والا قدردان ہے', NULL, NULL, '863831542635f07b6b4a98508cbcab7e0d83addbc10b1f4ec173fa6fd1f0ca26'),
  ('ur.jalandhry', 42, 24, 4296, 'کیا یہ لوگ کہتے ہیں کہ پیغمبر نے خدا پر جھوٹ باندھ لیا ہے؟ اگر خدا چاہے تو (اے محمدﷺ) تمہارے دل پر مہر لگا دے۔ اور خدا جھوٹ کو نابود کرتا اور اپنی باتوں سے حق کو ثابت کرتا ہے۔ بےشک وہ سینے تک کی باتوں سے واقف ہے', NULL, NULL, '5191e65f6163568cceb8e71f0439f0e6cd79c0acdbb2a878736f511f0f56c26b'),
  ('ur.jalandhry', 42, 25, 4297, 'اور وہی تو ہے جو اپنے بندوں کی توبہ قبول کرتا اور (ان کے) قصور معاف فرماتا ہے اور جو تم کرتے ہو (سب) جانتا ہے', NULL, NULL, '2b6df8eebca3aa1ebcc34d68c33a668d5755b6784f22db878b9c76576699617b'),
  ('ur.jalandhry', 42, 26, 4298, 'اور جو ایمان لائے اور عمل نیک کئے ان کی (دعا) قبول فرماتا ہے اور ان کو اپنے فضل سے بڑھاتا ہے۔ اور جو کافر ہیں ان کے لئے سخت عذاب ہے', NULL, NULL, 'c3aa85943f868f34a3df759cd64730f406606c1b2eece28fd41a893f077daf42'),
  ('ur.jalandhry', 42, 27, 4299, 'اور اگر خدا اپنے بندوں کے لئے رزق میں فراخی کردیتا تو زمین میں فساد کرنے لگتے۔ لیکن وہ جو چیز چاہتا ہے اندازے کے ساتھ نازل کرتا ہے۔ بےشک وہ اپنے بندوں کو جانتا اور دیکھتا ہے', NULL, NULL, '5ddf7209bc80a6e1fd103ff3156853d13f7cc592b3b89e44c3c3a589220b7799'),
  ('ur.jalandhry', 42, 28, 4300, 'اور وہی تو ہے جو لوگوں کے ناامید ہوجانے کے بعد مینہ برساتا اور اپنی رحمت (یعنی بارش) کی برکت کو پھیلا دیتا ہے۔ اور وہ کارساز اور سزاوار تعریف ہے', NULL, NULL, '4d68f73705a772d80b6156fd497ce7a88bdd86c1333db98feb142e6247c44d94')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 42, 29, 4301, 'اور اسی کی نشانیوں میں سے ہے آسمانوں اور زمین کا پیدا کرنا اور ان جانوروں کا جو اس نے ان میں پھیلا رکھے ہیں اور وہ جب چاہے ان کے جمع کرلینے پر قادر ہے', NULL, NULL, 'b65a01c9ae344d8e23163d273d47139196acadbf274a24fc1bc1b643ca9ab942'),
  ('ur.jalandhry', 42, 30, 4302, 'اور جو مصیبت تم پر واقع ہوتی ہے سو تمہارے اپنے فعلوں سے اور وہ بہت سے گناہ تو معاف ہی کردیتا ہے', NULL, NULL, '27e9888eae647aab530ba450bb61d383cc63381d5c791b530d7aee59a1c5e3e3'),
  ('ur.jalandhry', 42, 31, 4303, 'اور تم زمین میں (خدا کو) عاجز نہیں کرسکتے۔ اور خدا کے سوا نہ تمہارا کوئی دوست ہے اور نہ مددگار', NULL, NULL, '822bb2dfd149287320ee067cec40de167be9323d3afae0753001e58ae7e91e12'),
  ('ur.jalandhry', 42, 32, 4304, 'اور اسی کی نشانیوں میں سے سمندر کے جہاز ہیں (جو) گویا پہاڑ (ہیں)', NULL, NULL, '320675cb0445ee4ca1f635524d43149e09df9a46b9e6e144123abd85e81589f6'),
  ('ur.jalandhry', 42, 33, 4305, 'اگر خدا چاہے تو ہوا کو ٹھیرا دے اور جہاز اس کی سطح پر کھڑے رہ جائیں۔ تمام صبر اور شکر کرنے والوں کے لئے ان (باتوں) میں قدرت خدا کے نمونے ہیں', NULL, NULL, '540a3997c6538d3b017cbc027c8c62437d446ff9a6888808b4de5c60bf087f1d'),
  ('ur.jalandhry', 42, 34, 4306, 'یا ان کے اعمال کے سبب ان کو تباہ کردے۔ اور بہت سے قصور معاف کردے', NULL, NULL, 'd6893fcb8b631451dbd043f7930857d61dfe812d58c205591576966553ba4440'),
  ('ur.jalandhry', 42, 35, 4307, 'اور (انتقام اس لئے لیا جائے کہ) جو لوگ ہماری آیتوں میں جھگڑتے ہیں۔ وہ جان لیں کہ ان کے لئے خلاصی نہیں', NULL, NULL, 'ed021f8b2c59fedb679383c119fb1bf54f26515001b50514aceadfb20a7ffefd'),
  ('ur.jalandhry', 42, 36, 4308, '(لوگو) جو (مال ومتاع) تم کو دیا گیا ہے وہ دنیا کی زندگی کا (ناپائدار) فائدہ ہے۔ اور جو کچھ خدا کے ہاں ہے وہ بہتر اور قائم رہنے والا ہے (یعنی) ان لوگوں کے لئے جو ایمان لائے اور اپنے پروردگار پر بھروسا رکھتے ہیں', NULL, NULL, '7beb63f665d2081c6b3635bf8d1a3247f2517648fff629254ce14a1b26b0b6d4'),
  ('ur.jalandhry', 42, 37, 4309, 'اور جو بڑے بڑے گناہوں اور بےحیائی کی باتوں سے پرہیز کرتے ہیں۔ اور جب غصہ آتا ہے تو معاف کردیتے ہیں', NULL, NULL, '4792bf4946a7b2ba3b9afa77e865ed229817a193336a688758db0ecf44a28d4d'),
  ('ur.jalandhry', 42, 38, 4310, 'اور جو اپنے پروردگار کا فرمان قبول کرتے ہیں اور نماز پڑھتے ہیں۔ اور اپنے کام آپس کے مشورے سے کرتے ہیں۔ اور جو مال ہم نے ان کو عطا فرمایا ہے اس میں سے خرچ کرتے ہیں', NULL, NULL, '5c5c541b7f4420cc085169e19f65ecb92aaf29638578924538e7620b2e52943f'),
  ('ur.jalandhry', 42, 39, 4311, 'اور جو ایسے ہیں کہ جب ان پر ظلم وتعدی ہو تو (مناسب طریقے سے) بدلہ لیتے ہیں', NULL, NULL, '333a53ee36401ca6297ebc66e35ee869db9142a889c5c34a3655fc3025138c46'),
  ('ur.jalandhry', 42, 40, 4312, 'اور برائی کا بدلہ تو اسی طرح کی برائی ہے۔ مگر جو درگزر کرے اور (معاملے کو) درست کردے تو اس کا بدلہ خدا کے ذمے ہے۔ اس میں شک نہیں کہ وہ ظلم کرنے والوں کو پسند نہیں کرتا', NULL, NULL, '321f2dce905a24f49489ea6cf27223a218c1ff49081ad14e1c29d18319e1d252'),
  ('ur.jalandhry', 42, 41, 4313, 'اور جس پر ظلم ہوا ہو اگر وہ اس کے بعد انتقام لے تو ایسے لوگوں پر کچھ الزام نہیں', NULL, NULL, 'ec64befb22e2e6703011e028dae32df97ab0515dc7b49864ea031738048cab18'),
  ('ur.jalandhry', 42, 42, 4314, 'الزام تو ان لوگوں پر ہے جو لوگوں پر ظلم کرتے ہیں اور ملک میں ناحق فساد پھیلاتے ہیں۔ یہی لوگ ہیں جن کو تکلیف دینے والا عذاب ہوگا', NULL, NULL, 'f1daf0136bcfb2456bb3acf0ea070bd0be7a776eec2f4d49ce4589c8190ac650'),
  ('ur.jalandhry', 42, 43, 4315, 'اور جو صبر کرے اور قصور معاف کردے تو یہ ہمت کے کام ہیں', NULL, NULL, 'ad9534d5612b0b49c69928ceaed51f40fc0ea09f8dc534701fc4095e8b800f3d'),
  ('ur.jalandhry', 42, 44, 4316, 'اور جس شخص کو خدا گمراہ کرے تو اس کے بعد اس کا کوئی دوست نہیں۔ اور تم ظالموں کو دیکھو گے کہ جب وہ (دوزخ کا) عذاب دیکھیں گے تو کہیں گے کیا (دنیا میں) واپس جانے کی بھی کوئی سبیل ہے؟', NULL, NULL, 'bda773b95662b181651af10b8cb55faa9f7ca3c1919bfe0d591090261132825a'),
  ('ur.jalandhry', 42, 45, 4317, 'اور تم ان کو دیکھو گے کہ دوزخ کے سامنے لائے جائیں گے ذلت سے عاجزی کرتے ہوئے چھپی (اور نیچی) نگاہ سے دیکھ رہے ہوں گے۔ اور مومن لوگ کہیں کے کہ خسارہ اٹھانے والے تو وہ ہیں جنہوں نے قیامت کے دن اپنے آپ کو اور اپنے گھر والوں کو خسارے میں ڈالا۔ دیکھو کہ بےانصاف لوگ ہمیشہ کے دکھ میں (پڑے) رہیں گے', NULL, NULL, '6658c6e74488c983ea8b4825c0a55b0e831cd63c3418efd034d4a5772ac4c8b6'),
  ('ur.jalandhry', 42, 46, 4318, 'اور خدا کے سوا ان کے کوئی دوست نہ ہوں گے کہ خدا کے سوا ان کو مدد دے سکیں۔ اور جس کو خدا گمراہ کرے اس کے لئے (ہدایت کا) کوئی رستہ نہیں', NULL, NULL, 'd26f19f866f044d0c7453c6dbe4d78144d76a218309c22383785dc1fe33fb11f'),
  ('ur.jalandhry', 42, 47, 4319, 'ان سے کہہ دو کہ) قبل اس کے کہ وہ دن جو ٹلے گا نہیں خدا کی طرف سے آ موجود ہو اپنے پروردگار کا حکم قبول کرو۔ اس دن تمہارے لئے نہ کوئی جائے پناہ ہوگی اور نہ تم سے گناہوں کا انکار ہی بن پڑے گا', NULL, NULL, '1bab7a944213fe50e06ac52e4b1329b7b7f83d6a25c82e37dd4945aeb0c0058a'),
  ('ur.jalandhry', 42, 48, 4320, 'پھر اگر یہ منہ پھیر لیں تو ہم نے تم کو ان پر نگہبان بنا کر نہیں بھیجا۔ تمہارا کام تو صرف (احکام کا) پہنچا دینا ہے۔ اور جب ہم انسان کو اپنی رحمت کا مزہ چکھاتے ہیں تو اس سے خوش ہوجاتا ہے۔ اور اگر ان کو ان ہی کے اعمال کے سبب کوئی سختی پہنچتی ہے تو (سب احسانوں کو بھول جاتے ہیں) بےشک انسان بڑا ناشکرا ہے', NULL, NULL, '2ef673182c0c6f2da505061e8f8f36a81e58d447168aa8746a10c137bcc15b66'),
  ('ur.jalandhry', 42, 49, 4321, '(تمام) بادشاہت خدا ہی کی ہے آسمانوں کی بھی اور زمین کی بھی۔ وہ جو چاہتا ہے پیدا کرتا ہے۔ جسے چاہتا ہے بیٹیاں عطا کرتا ہے اور جسے چاہتا ہے بیٹے بخشتا ہے', NULL, NULL, '81d310fca68388d8b885432e77449627ad670435046a1a4a213d5a0c5d74cfea'),
  ('ur.jalandhry', 42, 50, 4322, 'یا ان کو بیٹے اور بیٹیاں دونوں عنایت فرماتا ہے۔ اور جس کو چاہتا ہے بےاولاد رکھتا ہے۔ وہ تو جاننے والا (اور) قدرت والا ہے', NULL, NULL, 'de6bd851d5a7c6025a8aa1e05804a76b771c3f13f0dfdc8c7dd864f50dd5ae99'),
  ('ur.jalandhry', 42, 51, 4323, 'اور کسی آدمی کے لئے ممکن نہیں کہ خدا اس سے بات کرے مگر الہام (کے ذریعے) سے یا پردے کے پیچھے سے یا کوئی فرشتہ بھیج دے تو وہ خدا کے حکم سے جو خدا چاہے القا کرے۔ بےشک وہ عالی رتبہ (اور) حکمت والا ہے', NULL, NULL, 'da691f0b5d2a4ec035a3a4f4a6acac14b94038c73a5a50f6d831b5f59ea1cbdd'),
  ('ur.jalandhry', 42, 52, 4324, 'اور اسی طرح ہم نے اپنے حکم سے تمہاری طرف روح القدس کے ذریعے سے (قرآن) بھیجا ہے۔ تم نہ تو کتاب کو جانتے تھے اور نہ ایمان کو۔ لیکن ہم نے اس کو نور بنایا ہے کہ اس سے ہم اپنے بندوں میں سے جس کو چاہتے ہیں ہدایت کرتے ہیں۔ اور بےشک (اے محمدﷺ) تم سیدھا رستہ دکھاتے ہو', NULL, NULL, '6491c54186dc192a8fdc3c567a11004e31e8b42eaf1a8d33b5113f68af9e624c'),
  ('ur.jalandhry', 42, 53, 4325, '(یعنی) خدا کا رستہ جو آسمانوں اور زمین کی سب چیزوں کا مالک ہے۔ دیکھو سب کام خدا کی طرف رجوع ہوں گے (اور وہی ان میں فیصلہ کرے گا)', NULL, NULL, 'bb3d3231c18e80c29325256260de5cb660bed5764d208c99d30bd67ea1abe3de'),
  ('ur.jalandhry', 43, 1, 4326, 'حٰم', NULL, NULL, 'd986ffe3c6d7ee25895888ccc3f155e8bc4ee20bae5d426418522f2a94027657'),
  ('ur.jalandhry', 43, 2, 4327, 'کتاب روشن کی قسم', NULL, NULL, '5e3e3e2c1242c41187e0024c325e99cb4b73c757e8a42d1d6ee1fdc49d604fc3'),
  ('ur.jalandhry', 43, 3, 4328, 'کہ ہم نے اس کو قرآن عربی بنایا ہے تاکہ تم سمجھو', NULL, NULL, 'a7104563c596d3bdec087e3c63afee6272a511ee5b5b72c27708519118f65e79'),
  ('ur.jalandhry', 43, 4, 4329, 'اور یہ بڑی کتاب (یعنی لوح محفوظ) میں ہمارے پاس (لکھی ہوئی اور) بڑی فضیلت اور حکمت والی ہے', NULL, NULL, '7956492045765914fa684c5849a4e7592e926c5fe5bcccbfb43af4bfb6758553'),
  ('ur.jalandhry', 43, 5, 4330, 'بھلا اس لئے کہ تم حد سے نکلے ہوئے لوگ ہو ہم تم کو نصیحت کرنے سے باز رہیں گے', NULL, NULL, '237d5504bc46b4c5a1893671b593a2d65254706ada2dd84ad3b0ea2db67259be'),
  ('ur.jalandhry', 43, 6, 4331, 'اور ہم نے پہلے لوگوں میں بھی بہت سے پیغمبر بھیجے تھے', NULL, NULL, '74cc7b399efb279de8871eb9309dcc0f80b1d653f654d05a8d149b4ae7faafe1'),
  ('ur.jalandhry', 43, 7, 4332, 'اور کوئی پیغمبر ان کے پاس نہیں آتا تھا مگر وہ اس سے تمسخر کرتے تھے', NULL, NULL, 'a1a1f1ddbec87dca6a803830c25074b7a0cc9401edd6bb2721337cedbb6ae7c6'),
  ('ur.jalandhry', 43, 8, 4333, 'تو جو ان میں سخت زور والے تھے ان کو ہم نے ہلاک کردیا اور اگلے لوگوں کی حالت گزر گئی', NULL, NULL, 'afb8a457db62729a5371fd2a737fef52d26d78b58cdd3ab37376b62f28c9fa3d'),
  ('ur.jalandhry', 43, 9, 4334, 'اور اگر تم ان سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا ہے تو کہہ دیں گے کہ ان کو غالب اور علم والے (خدا) نے پیدا کیا ہے', NULL, NULL, 'acc91bb57cce5d8dcbb9efce3246e08717fbbbdf71156cea85e2c9f0164b9cf5'),
  ('ur.jalandhry', 43, 10, 4335, 'جس نے تمہارے لئے زمین کو بچھونا بنایا۔ اور اس میں تمہارے لئے رستے بنائے تاکہ تم راہ معلوم کرو', NULL, NULL, '79a27753c325bfb32ef896b67046ff7bfc73850506fe1a1ba88eb166d033cef5'),
  ('ur.jalandhry', 43, 11, 4336, 'اور جس نے ایک اندازے کے ساتھ آسمان سے پانی نازل کیا۔ پھر ہم نے اس سے شہر مردہ کو زندہ کیا۔ اسی طرح تم زمین سے نکالے جاؤ گے', NULL, NULL, 'd26678b8626ce578cb3fdf90bec82a6446953092f00560564bb52ea14943a608'),
  ('ur.jalandhry', 43, 12, 4337, 'اور جس نے تمام قسم کے حیوانات پیدا کئے اور تمہارے لئے کشتیاں اور چارپائے بنائے جن پر تم سوار ہوتے ہو', NULL, NULL, '6885d1be7b5dbf30dd5eb64fc5c013cb6a7132c3eaeeacff998551b6f7354125'),
  ('ur.jalandhry', 43, 13, 4338, 'تاکہ تم ان کی پیٹھ پر چڑھ بیٹھو اور جب اس پر بیٹھ جاؤ پھر اپنے پروردگار کے احسان کو یاد کرو اور کہو کہ وہ (ذات) پاک ہے جس نے اس کو ہمارے زیر فرمان کر دیا اور ہم میں طاقت نہ تھی کہ اس کو بس میں کرلیتے', NULL, NULL, '244c9d3e72ca0101627551dabfe7aeacaafc2edb95febc9373e60acbc8ef38dc'),
  ('ur.jalandhry', 43, 14, 4339, 'اور ہم اپنے پروردگار کی طرف لوٹ کر جانے والے ہیں', NULL, NULL, '22a01511a77cc552d2a03da40cbbcb7e3cdcb3072c6404d615c21aa4421f1cfc'),
  ('ur.jalandhry', 43, 15, 4340, 'اور انہوں نے اس کے بندوں میں سے اس کے لئے اولاد مقرر کی۔ بےشک انسان صریح ناشکرا ہے', NULL, NULL, '8d64e9421e294f28bef042ffab3dc0d11d323b5471757ded598718f49e3a5d62'),
  ('ur.jalandhry', 43, 16, 4341, 'کیا اس نے اپنی مخلوقات میں سے خود تو بیٹیاں لیں اور تم کو چن کر بیٹے دیئے', NULL, NULL, '193d5e85700d4130610d5a27d727628537dad7dbd60e9871b9f04186dba64daa'),
  ('ur.jalandhry', 43, 17, 4342, 'حالانکہ جب ان میں سے کسی کو اس چیز کی خوشخبری دی جاتی ہے جو انہوں نے خدا کے لئے بیان کی ہے تو اس کا منہ سیاہ ہوجاتا اور وہ غم سے بھر جاتا ہے', NULL, NULL, 'a13043190391a13e7f04b34052320b14699df93ca7cd9618f019a77fdb330580'),
  ('ur.jalandhry', 43, 18, 4343, 'کیا وہ جو زیور میں پرورش پائے اور جھگڑے کے وقت بات نہ کرسکے (خدا کی) بیٹی ہوسکتی ہے؟', NULL, NULL, 'a786c56aca0a73b009b37974872327990ceb74e7489daa87abd777e95c11e29b'),
  ('ur.jalandhry', 43, 19, 4344, 'اور انہوں نے فرشتوں کو کہ وہ بھی خدا کے بندے ہیں (خدا کی) بیٹیاں مقرر کیا۔ کیا یہ ان کی پیدائش کے وقت حاضر تھے عنقریب ان کی شہادت لکھ لی جائے گی اور ان سے بازپرس کی جائے گی', NULL, NULL, '07816ba977e02b69f41633839b0948d959a873e992699460adc82eb6b0b5b8da'),
  ('ur.jalandhry', 43, 20, 4345, 'اور کہتے ہیں اگر خدا چاہتا تو ہم ان کو نہ پوجتے۔ ان کو اس کا کچھ علم نہیں۔ یہ تو صرف اٹکلیں دوڑا رہے ہیں', NULL, NULL, '87250cca809c241ad4c7b80756951f9e7fb9372b3ee412e4121e532ea1cbb47b'),
  ('ur.jalandhry', 43, 21, 4346, 'یا ہم نے ان کو اس سے پہلے کوئی کتاب دی تھی تو یہ اس سے سند پکڑتے ہیں', NULL, NULL, 'abfcfc71444c35f80e6633657d488191b9172f240e18dcbb43bbc119b795ddc7'),
  ('ur.jalandhry', 43, 22, 4347, 'بلکہ کہنے لگے کہ ہم نے اپنے باپ دادا کو ایک رستے پر پایا ہے اور ہم انہی کے قدم بقدم چل رہے ہیں', NULL, NULL, '2ec4641b47837a7a820caf7c2ac084b61a15a640bf1a4caa5aa80b382d70c466'),
  ('ur.jalandhry', 43, 23, 4348, 'اور اسی طرح ہم نے تم سے پہلے کسی بستی میں کوئی ہدایت کرنے والا نہیں بھیجا مگر وہاں کے خوشحال لوگوں نے کہا کہ ہم نے اپنے باپ دادا کو ایک راہ پر پایا اور ہم قدم بقدم ان ہی کے پیچھے چلتے ہیں', NULL, NULL, '2c3e02cc129fba9ff7694986f63a9a862035101bcede5108293c95a2b69a474f'),
  ('ur.jalandhry', 43, 24, 4349, 'پیغمبر نے کہا اگرچہ میں تمہارے پاس ایسا (دین) لاؤں کہ جس رستے پر تم نے اپنے باپ دادا کو پایا وہ اس سے کہیں سیدھا رستہ دکھاتا ہے کہنے لگے کہ جو (دین) تم دے کر بھیجے گئے ہو ہم اس کو نہیں مانتے', NULL, NULL, 'da4c7d8fa5bd8f6ff888e72c248090ca15541c9bf3c5e7f89025bf2614800cba'),
  ('ur.jalandhry', 43, 25, 4350, 'تو ہم نے ان سے انتقام لیا سو دیکھ لو کہ جھٹلانے والوں کا انجام کیسا ہوا', NULL, NULL, '8a05e98a682f96e0cd19673463fa5abea9c22e0281ae521da2c4fe49beae1d22'),
  ('ur.jalandhry', 43, 26, 4351, 'اور جب ابراہیم نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا کہ جن چیزوں کو تم پوجتے ہو میں ان سے بیزار ہوں', NULL, NULL, '5891810f90b735d1875e21570ea408f2be3ce89e278f895c081448aa9b2ab5e6'),
  ('ur.jalandhry', 43, 27, 4352, 'ہاں جس نے مجھ کو پیدا کیا وہی مجھے سیدھا رستہ دکھائے گا', NULL, NULL, '4ad788c3660567c2f90671bfec380aea22716574a08f976972226f996cae4a69'),
  ('ur.jalandhry', 43, 28, 4353, 'اور یہی بات اپنی اولاد میں پیچھے چھوڑ گئے تاکہ وہ (خدا کی طرف) رجوع کریں', NULL, NULL, 'c05a1dafdca4a049b395877d58c15976bd754711e1d8a63c036573d6283108f2'),
  ('ur.jalandhry', 43, 29, 4354, 'بات یہ ہے کہ میں ان کفار کو اور ان کے باپ دادا کو متمتع کرتا رہا یہاں تک کہ ان کے پاس حق اور صاف صاف بیان کرنے والا پیغمبر آ پہنچا', NULL, NULL, 'cd8fc14fed6733ff041189d63608961c4f2a0abe56e8e34a3e64996ac29eefe5'),
  ('ur.jalandhry', 43, 30, 4355, 'اور جب ان کے پاس حق (یعنی قرآن) آیا تو کہنے لگے کہ یہ تو جادو ہے اور ہم اس کو نہیں مانتے', NULL, NULL, '0148dd8ee04fc663e3fddf45c0dcded8aa5c8dba6ac1af9eaabed547149991b8'),
  ('ur.jalandhry', 43, 31, 4356, 'اور (یہ بھی) کہنے لگے کہ یہ قرآن ان دونوں بستیوں (یعنی مکّے اور طائف) میں سے کسی بڑے آدمی پر کیوں نازل نہ کیا گیا؟', NULL, NULL, '4bf75d8bc1e782be517fadba144a4747eca3b3d1f86c4f510337a5f1f752df1a'),
  ('ur.jalandhry', 43, 32, 4357, 'کیا یہ لوگ تمہارے پروردگار کی رحمت کو بانٹتے ہیں؟ ہم نے ان میں ان کی معیشت کو دنیا کی زندگی میں تقسیم کردیا اور ایک کے دوسرے پر درجے بلند کئے تاکہ ایک دوسرے سے خدمت لے اور جو کچھ یہ جمع کرتے ہیں تمہارے پروردگار کی رحمت اس سے کہیں بہتر ہے', NULL, NULL, '6b223a002cdf3e287645724912dc8d89cb7a34c1cc477beb622d836b38c748ae'),
  ('ur.jalandhry', 43, 33, 4358, 'اور اگر یہ خیال نہ ہوتا کہ سب لوگ ایک ہی جماعت ہوجائیں گے تو جو لوگ خدا سے انکار کرتے ہیں ہم ان کے گھروں کی چھتیں چاندی کی بنا دیتے اور سیڑھیاں (بھی) جن پر وہ چڑھتے ہیں', NULL, NULL, 'bb96d3c5c824247a53be9b76651ca2d9d273c8e7223b150bd2c954aff5ce1531'),
  ('ur.jalandhry', 43, 34, 4359, 'اور ان کے گھروں کے دروازے بھی اور تخت بھی جن پر تکیہ لگاتے ہیں', NULL, NULL, '59fef561cf390d87690d5c7a462ac1e51720d1d44a71b286dc57e9318e165c2d'),
  ('ur.jalandhry', 43, 35, 4360, 'اور (خوب) تجمل وآرائش (کردیتے) اور یہ سب دنیا کی زندگی کا تھوڑا سا سامان ہے۔ اور آخرت تمہارے پروردگار کے ہاں پرہیزگاروں کے لئے ہے', NULL, NULL, '2a16d36f0584ccc2f9b32c2161a601951041e754145ecbe920285b30894da15b'),
  ('ur.jalandhry', 43, 36, 4361, 'اور جو کوئی خدا کی یاد سے آنکھیں بند کرکے (یعنی تغافل کرے) ہم اس پر ایک شیطان مقرر کردیتے ہیں تو وہ اس کا ساتھی ہوجاتا ہے', NULL, NULL, 'edc87854692143b9a4663a824931f8b83c581569873e8180b2be832c6c7299bc'),
  ('ur.jalandhry', 43, 37, 4362, 'اور یہ (شیطان) ان کو رستے سے روکتے رہتے ہیں اور وہ سمجھتے ہیں کہ سیدھے رستے پر ہیں', NULL, NULL, 'c6a343c37b22b13719f7073abd24a010397d939e2923c6b5143a53a967af2dfd'),
  ('ur.jalandhry', 43, 38, 4363, 'یہاں تک کہ جب ہمارے پاس آئے گا تو کہے گا کہ اے کاش مجھ میں اور تجھ میں مشرق ومغرب کا فاصلہ ہوتا تو برا ساتھی ہے', NULL, NULL, 'b0d5d9c457d3ab0945b0a9b5740d91407395cfa0f0493188b63ea7ad963a8f78'),
  ('ur.jalandhry', 43, 39, 4364, 'اور جب تم ظلم کرتے رہے تو آج تمہیں یہ بات فائدہ نہیں دے سکتی کہ تم (سب) عذاب میں شریک ہو', NULL, NULL, 'cf2ba7856fd17cc6404e2e696185c9adc2441f8b74509dc6bc61481d474875fb'),
  ('ur.jalandhry', 43, 40, 4365, 'کیا تم بہرے کو سنا سکتے ہو یا اندھے کو رستہ دکھا سکتے ہو اور جو صریح گمراہی میں ہو (اسے راہ پر لاسکتے ہو)', NULL, NULL, 'a29c2f77f4783eafb0bb63ca6e566db9c3a4616fd7a79cdff00558e2a59ca5b1'),
  ('ur.jalandhry', 43, 41, 4366, 'اگر ہم تم کو (وفات دے کر) اٹھا لیں تو ان لوگوں سے تو ہم انتقام لے کر رہیں گے', NULL, NULL, 'e99232c2a6833f894da3a161673ab51f4c7af57557a00ab3fbe976b9bd7c601a'),
  ('ur.jalandhry', 43, 42, 4367, 'یا (تمہاری زندگی ہی میں) تمہیں وہ (عذاب) دکھا دیں گے جن کا ہم نے ان سے وعدہ کیا ہے ہم ان پر قابو رکھتے ہیں', NULL, NULL, 'a041e98e709b1b450e06fb915ea1696903afb4ce1b772a8e0d219a29e27ec826'),
  ('ur.jalandhry', 43, 43, 4368, 'پس تمہاری طرف جو وحی کی گئی ہے اس کو مضبوط پکڑے رہو۔ بےشک تم سیدھے رستے پر ہو', NULL, NULL, '3a45e7143bf74c359fcd8394c9e135407950ebc2c936edd76fd605e49080c405'),
  ('ur.jalandhry', 43, 44, 4369, 'اور یہ (قرآن) تمہارے لئے اور تمہاری قوم کے لئے نصیحت ہے اور (لوگو) تم سے عنقریب پرسش ہوگی', NULL, NULL, '50bdb7bcced4fd494cbcbf9bb98f99894b409b5c63fb3b9a0a2da6ac6686c66a'),
  ('ur.jalandhry', 43, 45, 4370, 'اور (اے محمدﷺ) جو اپنے پیغمبر ہم نے تم سے پہلے بھیجے ہیں ان سے دریافت کرلو۔ کیا ہم نے (خدائے) رحمٰن کے سوا اور معبود بنائے تھے کہ ان کی عبادت کی جائے', NULL, NULL, 'bddfde71553fa0b76e6076cb329bcb67620165da3725adfe02242d1f4032bb2b'),
  ('ur.jalandhry', 43, 46, 4371, 'اور ہم نے موسیٰ کو اپنی نشانیاں دے کر فرعون اور اس کے درباریوں کی طرف بھیجا تو انہوں نے کہا کہ میں پروردگار عالم کا بھیجا ہوا ہوں', NULL, NULL, '24c3b5a1c4be5a1cb9c667dec3a2f20b2ecaff895924571153be305a0b87e101'),
  ('ur.jalandhry', 43, 47, 4372, 'جب وہ ان کے پاس ہماری نشانیاں لے کر آئے تو وہ نشانیوں سے ہنسی کرنے لگے', NULL, NULL, 'a15aafaa5751ac0fe5024e004408c1e3f8542c566aa744f39499ebcaf00ee4f0'),
  ('ur.jalandhry', 43, 48, 4373, 'اور جو نشانی ہم ان کو دکھاتے تھے وہ دوسری سے بڑی ہوتی تھی اور ہم نے ان کو عذاب میں پکڑ لیا تاکہ باز آئیں', NULL, NULL, 'ee749e4ea1cb27acdb2442b3c87a02ce035e4b3858a1c77b63ba1c51010b1abd'),
  ('ur.jalandhry', 43, 49, 4374, 'اور کہنے لگے کہ اے جادوگر اس عہد کے مطابق جو تیرے پروردگار نے تجھ سے کر رکھا ہے اس سے دعا کر بےشک ہم ہدایت یاب ہو جائیں گے', NULL, NULL, 'f35abb791c359dbee339e8c07a5f3c8ee743a0a52ff19939adeb33bb5fca1d69'),
  ('ur.jalandhry', 43, 50, 4375, 'سو جب ہم نے ان سے عذاب کو دور کردیا تو وہ عہد شکنی کرنے لگے', NULL, NULL, '12d2e2a29c28f98037d4b3ce1d79e7b881a6e7897b2cf3b16c7a02aa7f8e7997'),
  ('ur.jalandhry', 43, 51, 4376, 'اور فرعون نے اپنی قوم سے پکار کر کہا کہ اے قوم کیا مصر کی حکومت میرے ہاتھ میں نہیں ہے۔ اور یہ نہریں جو میرے (محلوں کے) نیچے بہہ رہی ہیں (میری نہیں ہیں) کیا تم دیکھتے نہیں', NULL, NULL, '0aaa9406970af9bef2e105ded92f5e15a51bda9803eb349432a8d4ba97d31865'),
  ('ur.jalandhry', 43, 52, 4377, 'بےشک میں اس شخص سے جو کچھ عزت نہیں رکھتا اور صاف گفتگو بھی نہیں کرسکتا کہیں بہتر ہوں', NULL, NULL, '2f5c2d2c3222f3af8feb8cce8bccc051b5e6d6cfa6332b531617795b23952921'),
  ('ur.jalandhry', 43, 53, 4378, 'تو اس پر سونے کے کنگن کیوں نہ اُتارے گئے یا (یہ ہوتا کہ) فرشتے جمع ہو کر اس کے ساتھ آتے', NULL, NULL, 'a16a9b1f35bd08aebe88e05e3431bd4a0ea92a3d42c06276d411185387632fb6'),
  ('ur.jalandhry', 43, 54, 4379, 'غرض اس نے اپنی قوم کی عقل مار دی۔ اور انہوں نے اس کی بات مان لی۔ بےشک وہ نافرمان لوگ تھے', NULL, NULL, 'a43f6b23679e29d385899d34c3e6b275bee7fed94a55e50b98716ba9be869113'),
  ('ur.jalandhry', 43, 55, 4380, 'جب انہوں نے ہم کو خفا کیا تو ہم نے ان سے انتقام لے کر اور ان سب کو ڈبو کر چھوڑا', NULL, NULL, '02fffbffad642f8f1b36926c6407d20cb9adf5b4670e21adb37c165b9592b086'),
  ('ur.jalandhry', 43, 56, 4381, 'اور ان کو گئے گزرے کردیا اور پچھلوں کے لئے عبرت بنا دیا', NULL, NULL, '76987023d2421b8cb5a97601d46279341e8d8c446dbdbf77a6caa323b492fbc8'),
  ('ur.jalandhry', 43, 57, 4382, 'اور جب مریم کے بیٹے (عیسیٰ) کا حال بیان کیا گیا تو تمہاری قوم کے لوگ اس سے چِلا اُٹھے', NULL, NULL, '4da2bb5da75b8fe0da227da3a32321586ed729aed4aabc1b473696ff2327beaf'),
  ('ur.jalandhry', 43, 58, 4383, 'اور کہنے لگے کہ بھلا ہمارے معبود اچھے ہیں یا عیسیٰ؟ انہوں نے عیسیٰ کی جو مثال بیان کی ہے تو صرف جھگڑنے کو۔ حقیقت یہ ہے یہ لوگ ہیں ہی جھگڑالو', NULL, NULL, '73fc7e43fa65242431a0030f3b8740006f6ed559c570e9d60fae759d5afc76b4'),
  ('ur.jalandhry', 43, 59, 4384, 'وہ تو ہمارے ایسے بندے تھے جن پر ہم نے فضل کیا اور بنی اسرائیل کے لئے ان کو (اپنی قدرت کا) نمونہ بنا دیا', NULL, NULL, '58300a7cdd4a989e05e86c55cda8f336235ae00dd7a8427eef98eca48b98b4ce'),
  ('ur.jalandhry', 43, 60, 4385, 'اور اگر ہم چاہتے تو تم میں سے فرشتے بنا دیتے جو تمہاری جگہ زمین میں رہتے', NULL, NULL, 'b690ed34782b72d809a4af0a9c16c650c8107132c1d8350db4a2e8b4fc13df1f'),
  ('ur.jalandhry', 43, 61, 4386, 'اور وہ قیامت کی نشانی ہیں۔ تو (کہہ دو کہ لوگو) اس میں شک نہ کرو اور میرے پیچھے چلو۔ یہی سیدھا رستہ ہے', NULL, NULL, 'c471de3dcda3b0e543507b1b0677ac5c0511ee25d748ffd29b5d7af5af60f6fc'),
  ('ur.jalandhry', 43, 62, 4387, 'اور (کہیں) شیطان تم کو (اس سے) روک نہ دے۔ وہ تو تمہارا اعلاینہ دشمن ہے', NULL, NULL, '946e674f2fd8d19a57f1b630e6c79207ae9cca15a108b3405f2b48b6749677ff'),
  ('ur.jalandhry', 43, 63, 4388, 'اور جب عیسیٰ نشانیاں لے کر آئے تو کہنے لگے کہ میں تمہارے پاس دانائی (کی کتاب) لے کر آیا ہوں۔ نیز اس لئے کہ بعض باتیں جن میں تم اختلاف کر رہے ہو تم کو سمجھا دوں۔ تو خدا سے ڈرو اور میرا کہا مانو', NULL, NULL, '8f8765a4f56a16aa24ad371d2604cc28ea02cc001287cd2b273882127d5ad6cd'),
  ('ur.jalandhry', 43, 64, 4389, 'کچھ شک نہیں کہ خدا ہی میرا اور تمہارا پروردگار ہے پس اسی کی عبادت کرو۔ یہی سیدھا رستہ ہے', NULL, NULL, 'b871ca374d7514fa46cc4a3678d2e039b1b3a293bad52ef5bfe1d67d559de5a5'),
  ('ur.jalandhry', 43, 65, 4390, 'پھر کتنے فرقے ان میں سے پھٹ گئے۔ سو جو لوگ ظالم ہیں ان کی درد دینے والے دن کے عذاب سے خرابی ہے', NULL, NULL, '8f2c2d54a66d8b7a6f4d245a1350dfcf76da4fbea48cc035059e90002b0aa968'),
  ('ur.jalandhry', 43, 66, 4391, 'یہ صرف اس بات کے منتظر ہیں کہ قیامت ان پر ناگہاں آموجود ہو اور ان کو خبر تک نہ ہو', NULL, NULL, '127d6c5953e633cebf83aab67c44985836fb0be774c4b3fb14381811d625782c'),
  ('ur.jalandhry', 43, 67, 4392, '(جو آپس میں) دوست (ہیں) اس روز ایک دوسرے کے دشمن ہوں گے۔ مگر پرہیزگار (کہ باہم دوست ہی رہیں گے)', NULL, NULL, '422612a9c75c140769206c83495f6e1357510c778e22b488684f89f9227495b1'),
  ('ur.jalandhry', 43, 68, 4393, 'میرے بندو آج تمہیں نہ کچھ خوف ہے اور نہ تم غمناک ہوگے', NULL, NULL, '50d094ed21f41646ef2859fef88ed5072bc792020bfc3ff2d30b4582522942ca'),
  ('ur.jalandhry', 43, 69, 4394, 'جو لوگ ہماری آیتوں پر ایمان لائے اور فرمانبردار ہوگئے', NULL, NULL, 'c610b32057082b6f74093333d6edafcdf19f2f6df502c5a5d8fd58e9709dbc29'),
  ('ur.jalandhry', 43, 70, 4395, '(ان سے کہا جائے گا) کہ تم اور تمہاری بیویاں عزت (واحترام) کے ساتھ بہشت میں داخل ہوجاؤ', NULL, NULL, 'e3613b4a82cce9d9cdb6a445656ce9aa00e2944f14463c738dfaaefd888669c9'),
  ('ur.jalandhry', 43, 71, 4396, 'ان پر سونے کی پرچوں اور پیالوں کا دور چلے گا۔ اور وہاں جو جی چاہے اور جو آنکھوں کو اچھا لگے (موجود ہوگا) اور (اے اہل جنت) تم اس میں ہمیشہ رہو گے', NULL, NULL, '48ee8ba417199d8bd93cfda3473618db72a969f69ca6324f71892f3b70384906'),
  ('ur.jalandhry', 43, 72, 4397, 'اور یہ جنت جس کے تم مالک کر دیئے گئے ہو تمہارے اعمال کا صلہ ہے', NULL, NULL, 'c9325520d0fb42e337e6c9f23f94533dad61b9c617a6b9f71ee2cb45fdf47745'),
  ('ur.jalandhry', 43, 73, 4398, 'وہاں تمہارے لئے بہت سے میوے ہیں جن کو تم کھاؤ گے', NULL, NULL, 'cd25457a52025e562bddfad75aa26cc09c614b3f2f6a44489fd31e0e0cd522cf'),
  ('ur.jalandhry', 43, 74, 4399, '(اور کفار) گنہگار ہمیشہ دوزخ کے عذاب میں رہیں گے', NULL, NULL, '9c0fbee673175f306242c1f2b213914f7aa43e34f56e6171b0afe927a99d8d3b'),
  ('ur.jalandhry', 43, 75, 4400, 'جو ان سے ہلکا نہ کیا جائے گا اور وہ اس میں نامید ہو کر پڑے رہیں گے', NULL, NULL, '9aca5c08f66d6dc14304459a86cca1316130143454b918c4dd58b81f037aa61c')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 43, 76, 4401, 'اور ہم نے ان پر ظلم نہیں کیا۔ بلکہ وہی (اپنے آپ پر) ظلم کرتے تھے', NULL, NULL, 'f7887a85271729bf10f5a710fdb435ee7f922800dd9663ef242cd9fe78c320ca'),
  ('ur.jalandhry', 43, 77, 4402, 'اور پکاریں گے کہ اے مالک تمہارا پروردگار ہمیں موت دے دے۔ وہ کہے گا کہ تم ہمیشہ (اسی حالت میں) رہو گے', NULL, NULL, '5b21fd183ceb35ceb6c0d0b1c82ce6762a287bdc6859d2758ae1f6e5c7b6fec8'),
  ('ur.jalandhry', 43, 78, 4403, 'ہم تمہارے پاس حق لے کر آئے ہیں لیکن تم اکثر حق سے ناخوش ہوتے رہے', NULL, NULL, 'd4705d0f6de1095c678dc3dcbdc5db896a50e0696143c646f0f1f73444e43eeb'),
  ('ur.jalandhry', 43, 79, 4404, 'کیا انہوں نے کوئی بات ٹھہرا رکھی ہے تو ہم بھی کچھ ٹھہرانے والے ہیں', NULL, NULL, 'a892eeba20246fc723c20bc48ad6ce937e483169ee923f92df5fc834230d59f7'),
  ('ur.jalandhry', 43, 80, 4405, 'کیا یہ لوگ یہ خیال کرتے ہیں کہ ہم ان کی پوشیدہ باتوں اور سرگوشیوں کو سنتے نہیں؟ ہاں ہاں (سب سنتے ہیں) اور ہمارے فرشتے ان کے پاس (ان کی سب باتیں) لکھ لیتے ہیں', NULL, NULL, '8d412193bdd53586438f13d1d80fc5a5a2dbe27b110b198713e3d32e04f2881a'),
  ('ur.jalandhry', 43, 81, 4406, 'کہہ دو کہ اگر خدا کے اولاد ہو تو میں (سب سے) پہلے (اس کی) عبادت کرنے والا ہوں', NULL, NULL, 'c4c626cdcc647afa8ee88372d8cd65cae2be171b90f0aaad6e07ffadd46df2be'),
  ('ur.jalandhry', 43, 82, 4407, 'یہ جو کچھ بیان کرتے ہیں آسمانوں اور زمین کا مالک (اور) عرش کا مالک اس سے پاک ہے', NULL, NULL, 'b008f0152ad42e551ee1504984ff2626788ef75e44589a021ced1fe2771b81fb'),
  ('ur.jalandhry', 43, 83, 4408, 'تو ان کو بک بک کرنے اور کھیلنے دو۔ یہاں تک کہ جس دن کا ان سے وعدہ کیا جاتا ہے اس کو دیکھ لیں', NULL, NULL, 'ae12b6f299d0ea92034f8212778ce88c862e09ec60c8e968ba2874d6f31bbffd'),
  ('ur.jalandhry', 43, 84, 4409, 'اور وہی (ایک) آسمانوں میں معبود ہے اور (وہی) زمین میں معبود ہے۔ اور وہ دانا (اور) علم والا ہے', NULL, NULL, '13c5d73fee4e4c7e313241e87a29c1d09f51770cb4e560da6e807f0574885682'),
  ('ur.jalandhry', 43, 85, 4410, 'اور وہ بہت بابرکت ہے جس کے لئے آسمانوں اور زمین کی اور جو کچھ ان دونوں میں ہے سب کی بادشاہت ہے۔ اور اسی کو قیامت کا علم ہے اور اسی کی طرف تم لوٹ کر جاؤ گے', NULL, NULL, '279620320af92171e64b3991989f2991711da6a05f2218a83de8c30af47c5637'),
