  ('ur.jalandhry', 44, 59, 4473, 'پس تم بھی انتظار کرو یہ بھی انتظار کر رہے ہیں', NULL, NULL, '8558e0605fc15ff22b629c99bb565708f869801f0fc657ebc92276b905a8867b'),
  ('ur.jalandhry', 45, 1, 4474, 'حٰم', NULL, NULL, 'd986ffe3c6d7ee25895888ccc3f155e8bc4ee20bae5d426418522f2a94027657'),
  ('ur.jalandhry', 45, 2, 4475, 'اس کتاب کا اُتارا جانا خدائے غالب (اور) دانا (کی طرف) سے ہے', NULL, NULL, 'c619f5b97fc5e189728da2ac49acb7b46c77c3dce3a178b0d4a972f05b341cf9'),
  ('ur.jalandhry', 45, 3, 4476, 'بےشک آسمانوں اور زمین میں ایمان والوں کے لئے (خدا کی قدرت کی) نشانیاں ہیں', NULL, NULL, 'd1752b35b89069436aefab24a28e3372514fcb0a35850e4fb38fbce12f6a14d3'),
  ('ur.jalandhry', 45, 4, 4477, 'اور تمہاری پیدائش میں بھی۔ اور جانوروں میں بھی جن کو وہ پھیلاتا ہے یقین کرنے والوں کے لئے نشانیاں ہیں', NULL, NULL, 'f6c6dd022b30872d4b69dd5dd0439c966ae6d768b320156cb7101ae56b9163d8'),
  ('ur.jalandhry', 45, 5, 4478, 'اور رات اور دن کے آگے پیچھے آنے جانے میں اور وہ جو خدا نے آسمان سے (ذریعہٴ) رزق نازل فرمایا پھر اس سے زمین کو اس کے مرجانے کے بعد زندہ کیا اس میں اور ہواؤں کے بدلنے میں عقل والوں کے لئے نشانیاں ہیں', NULL, NULL, '79de9e9120f5a45564763f462f78f73b2853be46cb5e28807f0dd1c7e20c0719'),
  ('ur.jalandhry', 45, 6, 4479, 'یہ خدا کی آیتیں ہیں جو ہم تم کو سچائی کے ساتھ پڑھ کر سناتے ہیں۔ تو یہ خدا اور اس کی آیتوں کے بعد کس بات پر ایمان لائیں گے؟', NULL, NULL, '4274d9765aae937f895e39987b38ceeb82f01b9a515d3b5d42a4edf35988f07b'),
  ('ur.jalandhry', 45, 7, 4480, 'ہر جھوٹے گنہگار پر افسوس ہے', NULL, NULL, 'a52f7553518756b7cbeec08a092c7581e6f6201eced9389873b2d388fb9fcc4d'),
  ('ur.jalandhry', 45, 8, 4481, '(کہ) خدا کی آیتیں اس کو پڑھ کر سنائی جاتی ہیں تو ان کو سن تو لیتا ہے (مگر) پھر غرور سے ضد کرتا ہے کہ گویا ان کو سنا ہی نہیں۔ سو ایسے شخص کو دکھ دینے والے عذاب کی خوشخبری سنا دو', NULL, NULL, '0f1325794c9fa98d302a24234d00af68dc87749b346707f2236576fe81c43df3'),
  ('ur.jalandhry', 45, 9, 4482, 'اور جب ہماری کچھ آیتیں اسے معلوم ہوتی ہیں تو ان کی ہنسی اُڑاتا ہے۔ ایسے لوگوں کے لئے ذلیل کرنے والا عذاب ہے', NULL, NULL, 'a09b9dbe55b2f0e4514ba5951ae0d233f86e23ca6bb34b51d35c71a99265f824'),
  ('ur.jalandhry', 45, 10, 4483, 'ان کے سامنے دوزخ ہے۔ اور جو کام وہ کرتے رہے کچھ بھی ان کے کام نہ آئیں گے۔ اور نہ وہی (کام آئیں گے) جن کو انہوں نے خدا کے سوا معبود بنا رکھا تھا۔ اور ان کے لئے بڑا عذاب ہے', NULL, NULL, 'bd26110421d62cf76baa7c8d5aadf192c452c369ddee270bf494e77837df529e'),
  ('ur.jalandhry', 45, 11, 4484, 'یہ ہدایت (کی کتاب) ہے۔ اور جو لوگ اپنے پروردگار کی آیتوں سے انکار کرتے ہیں ان کو سخت قسم کا درد دینے والا عذاب ہوگا', NULL, NULL, '873d1a37947013562fb0a212a4fb2fccae2c3fbff2eeb38f5a290671a222806a'),
  ('ur.jalandhry', 45, 12, 4485, 'خدا ہی تو ہے جس نے دریا کو تمہارے قابو کردیا تاکہ اس کے حکم سے اس میں کشتیاں چلیں اور تاکہ تم اس کے فضل سے (معاش) تلاش کرو اور تاکہ شکر کرو', NULL, NULL, '91a879b7c45314ecc5e939355da573981666ae6e7d3f13676e5c5c5129fcaa70'),
  ('ur.jalandhry', 45, 13, 4486, 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب کو اپنے (حکم) سے تمہارے کام میں لگا دیا۔ جو لوگ غور کرتے ہیں ان کے لئے اس میں (قدرت خدا کی) نشانیاں ہیں', NULL, NULL, '730f9a6906f6c46e1e63946edf3ba7df14abd43be460c7501c42dbf6fb6cfe8a'),
  ('ur.jalandhry', 45, 14, 4487, 'مومنوں سے کہہ دو کہ جو لوگ خدا کے دنوں کی (جو اعمال کے بدلے کے لئے مقرر ہیں) توقع نہیں رکھتے ان سے درگزر کریں۔ تاکہ وہ ان لوگوں کو ان کے اعمال کا بدلے دے', NULL, NULL, '19d6170ec45ae5097c6985f20793b632e2cd4439222568ac71a8d87b35b8c56f'),
  ('ur.jalandhry', 45, 15, 4488, 'جو کوئی عمل نیک کرے گا تو اپنے لئے۔ اور جو برے کام کرے گا تو ان کا ضرر اسی کو ہوگا۔ پھر تم اپنے پروردگار کی طرف لوٹ کر جاؤ گے', NULL, NULL, '0e2c8ad388cc2b24e45d7e34afc56404f81aed44557b9351b06b37361388eb8a'),
  ('ur.jalandhry', 45, 16, 4489, 'اور ہم نے بنی اسرائیل کو کتاب (ہدایت) اور حکومت اور نبوت بخشی اور پاکیزہ چیزیں عطا فرمائیں اور اہل عالم پر فضیلت دی', NULL, NULL, '38ae4a2c98611d0d2a49deced78b40b61273225a3b5051cb303dd100ed15e251'),
  ('ur.jalandhry', 45, 17, 4490, 'اور ان کو دین کے بارے میں دلیلیں عطا کیں۔ تو انہوں نے جو اختلاف کیا تو علم آچکنے کے بعد آپس کی ضد سے کیا۔ بےشک تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا جن میں وہ اختلاف کرتے تھے فیصلہ کرے گا', NULL, NULL, '020dbd4320002233219589222f89741219c774d103f340b2bd50bda1d28b9b96'),
  ('ur.jalandhry', 45, 18, 4491, 'پھر ہم نے تم کو دین کے کھلے رستے پر (قائم) کر دیا تو اسی (رستے) پر چلے چلو اور نادانوں کی خواہشوں کے پیچھے نہ چلنا', NULL, NULL, '53613d3f958834fc0d28fa4faab15b0a98cc7ecf0c8a6a0c40f88390d09c9159'),
  ('ur.jalandhry', 45, 19, 4492, 'یہ خدا کے سامنے تمہارے کسی کام نہیں آئیں گے۔ اور ظالم لوگ ایک دوسرے کے دوست ہوتے ہیں۔ اور خدا پرہیزگاروں کا دوست ہے', NULL, NULL, 'b53f6f238827fc8bcd8b2855ee5ada30d5b72f50818f46ce7acca04816bf46e2'),
  ('ur.jalandhry', 45, 20, 4493, 'یہ قرآن لوگوں کے لئے دانائی کی باتیں ہیں اور جو یقین رکھتے ہیں ان کے لئے ہدایت اور رحمت ہے', NULL, NULL, 'ea6b37a6cf80091855bb137d11338021e3299def95551a79ae89460fc49d439c'),
  ('ur.jalandhry', 45, 21, 4494, 'جو لوگ برے کام کرتے ہیں کیا وہ یہ خیال کرتے ہیں کہ ہم ان کو ان لوگوں جیسا کردیں گے جو ایمان لائے اور عمل نیک کرتے رہے اور ان کی زندگی اور موت یکساں ہوگی۔ یہ جو دعوے کرتے ہیں برے ہیں', NULL, NULL, '1cfc5d71fa26746d4e088be25c03131324de016377590ff4ec45eb7478713ed7'),
  ('ur.jalandhry', 45, 22, 4495, 'اور خدا نے آسمانوں اور زمین کو حکمت سے پیدا کیا ہے اور تاکہ ہر شخص اپنے اعمال کا بدلہ پائے اور ان پر ظلم نہیں کیا جائے گا', NULL, NULL, '5d6338d7dc8e352baafb898aef28858022391869b7bd6e471901ab4c9740fa8c'),
  ('ur.jalandhry', 45, 23, 4496, 'بھلا تم نے اس شخص کو دیکھا جس نے اپنی خواہش کو معبود بنا رکھا ہے اور باوجود جاننے بوجھنے کے (گمراہ ہو رہا ہے تو) خدا نے (بھی) اس کو گمراہ کردیا اور اس کے کانوں اور دل پر مہر لگا دی اور اس کی آنکھوں پر پردہ ڈال دیا۔ اب خدا کے سوا اس کو کون راہ پر لاسکتا ہے۔ بھلا تم کیوں نصیحت نہیں پکڑتے؟', NULL, NULL, '03cd3187b70824664657505669f5e7a8c3e82c2b04020bdcbb518bb4f37e9104'),
  ('ur.jalandhry', 45, 24, 4497, 'اور کہتے ہیں کہ ہماری زندگی تو صرف دنیا ہی کی ہے کہ (یہیں) مرتے اور جیتے ہیں اور ہمیں تو زمانہ مار دیتا ہے۔ اور ان کو اس کا کچھ علم نہیں۔ صرف ظن سے کام لیتے ہیں', NULL, NULL, '9ff0e999d418ca1b8a70e7bbf68181672711fe9da8ef26b6768e7142ee8711ad'),
  ('ur.jalandhry', 45, 25, 4498, 'اور جب ان کے سامنے ہماری کھلی کھلی آیتیں پڑھی جاتی ہیں تو ان کی یہی حجت ہوتی ہے کہ اگر تم سچے ہو تو ہمارے باپ دادا کو (زندہ کر) لاؤ', NULL, NULL, '71dfe569cfecd3f9c8d63a688b522bac335e9b3ffbd27cfc5f4dd5f35c8408cb'),
  ('ur.jalandhry', 45, 26, 4499, 'کہہ دو کہ خدا ہی تم کو جان بخشتا ہے پھر (وہی) تم کو موت دیتا ہے پھر تم کو قیامت کے روز جس (کے آنے) میں کچھ شک نہیں تم کو جمع کرے گا لیکن بہت سے لوگ نہیں جانتے', NULL, NULL, 'e3e95d5a0bac9e0c8c328e8e53f191662f8be48c3e7b1a45f84424e13af0c9af'),
  ('ur.jalandhry', 45, 27, 4500, 'اور آسمانوں اور زمین کی بادشاہت خدا ہی کی ہے۔ اور جس روز قیامت برپا ہوگی اس روز اہل باطل خسارے میں پڑ جائیں گے', NULL, NULL, '6cfcc9bbdbfc6c7506cd94160646ae235c1eaec59c6214167edaf60fb3ef2816')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
    text_checksum = EXCLUDED.text_checksum;

INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 45, 28, 4501, 'اور تم ہر ایک فرقے کو دیکھو گے کہ گھٹنوں کے بل بیٹھا ہوگا۔ اور ہر ایک جماعت اپنی کتاب (اعمال) کی طرف بلائی جائے گی۔ جو کچھ تم کرتے رہے ہو آج تم کو اس کا بدلہ دیا جائے گا', NULL, NULL, 'a46f829ac053a906824530af876b4e22efd1742162059aa3a6220585834f0e5d'),
  ('ur.jalandhry', 45, 29, 4502, 'یہ ہماری کتاب تمہارے بارے میں سچ سچ بیان کردے گی۔ جو کچھ تم کیا کرتے تھے ہم لکھواتے جاتے ہیں', NULL, NULL, '244952c1eeba729cbadf78d88be155b58e232308aabef0ff45c278c239c02b8b'),
  ('ur.jalandhry', 45, 30, 4503, 'تو جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کا پروردگار انہیں رحمت (کے باغ) میں داخل کرے گا۔ یہی صریح کامیابی ہے', NULL, NULL, 'c94309e272fc7c8681e98dd41fc9d11ac62dc137a92a0b05a6fb897c5a8e8312'),
  ('ur.jalandhry', 45, 31, 4504, 'اور جنہوں نے کفر کیا۔ (ان سے کہا جائے گا کہ) بھلا ہماری آیتیں تم کو پڑھ کر سنائی نہیں جاتی تھیں؟ پھر تم نے تکبر کیا اور تم نافرمان لوگ تھے', NULL, NULL, '50c05f7306abd5e4ec5cffe59efe284c492d943adeb8cf90b23f04032d8a4312'),
  ('ur.jalandhry', 45, 32, 4505, 'اور جب کہا جاتا تھا کہ خدا کا وعدہ سچا ہے اور قیامت میں کچھ شک نہیں تو تم کہتے تھے ہم نہیں جانتے کہ قیامت کیا ہے۔ ہم اس کو محض ظنی خیال کرتے ہیں اور ہمیں یقین نہیں آتا', NULL, NULL, '9e65e355bb842a412df74cb6374e323ba451ef14e7938c8646cc480d7f1ae1b4'),
  ('ur.jalandhry', 45, 33, 4506, 'اور ان کے اعمال کی برائیاں ان پر ظاہر ہوجائیں گی اور جس (عذاب) کی وہ ہنسی اُڑاتے تھے وہ ان کو آگھیرے گا', NULL, NULL, 'b23d27b8161813679a52155a954ea0b7c984180748cd865b4b180b7664a3a9fe'),
  ('ur.jalandhry', 45, 34, 4507, 'اور کہا جائے گا کہ جس طرح تم نے اس دن کے آنے کو بھلا رکھا تھا۔ اسی طرح آج ہم تمہیں بھلا دیں گے اور تمہارا ٹھکانا دوزخ ہے اور کوئی تمہارا مددگار نہیں', NULL, NULL, '1e5449bd2619f2d22347a56bfdf0bee4bd3c051a901deac50ac2c9cfd8ff9199'),
  ('ur.jalandhry', 45, 35, 4508, 'یہ اس لئے کہ تم نے خدا کی آیتوں کو مخول بنا رکھا تھا اور دنیا کی زندگی نے تم کو دھوکے میں ڈال رکھا تھا۔ سو آج یہ لوگ نہ دوزخ سے نکالے جائیں گے اور نہ ان کی توبہ قبول کی جائے گی', NULL, NULL, 'bdf9614641526b84f32f4d5ee63950cf3fdcbec7635792549219c53bf1f4e6fa'),
  ('ur.jalandhry', 45, 36, 4509, 'پس خدا ہی کو ہر طرح کی تعریف (سزاوار) ہے جو آسمانوں کا مالک اور زمین کا مالک اور تمام جہان کا پروردگار ہے', NULL, NULL, 'd346c209182a09f15d85d4cb0560b9c0832eec3cd0170235f774758af353e0e1'),
  ('ur.jalandhry', 45, 37, 4510, 'اور آسمانوں اور زمین میں اُسی کے لئے بڑائی ہے۔ اور وہ غالب اور دانا ہے', NULL, NULL, '6a6f585b347a918f14575287c1fa181acc6fc2f7a82bd8784a7a7427c3cade4d'),
  ('ur.jalandhry', 46, 1, 4511, 'حٰم', NULL, NULL, 'd986ffe3c6d7ee25895888ccc3f155e8bc4ee20bae5d426418522f2a94027657'),
  ('ur.jalandhry', 46, 2, 4512, '(یہ) کتاب خدائے غالب (اور) حکمت والے کی طرف سے نازل ہوئی ہے', NULL, NULL, '28dd23b9126e95a23cd9c7d52603a57bb34bec9db0eec1dd5c6d117000d2b3ae'),
  ('ur.jalandhry', 46, 3, 4513, 'ہم نے آسمانوں اور زمین کو اور جو کچھ ان دونوں میں ہے مبنی برحکمت اور ایک وقت مقرر تک کے لئے پیدا کیا ہے۔ اور کافروں کو جس چیز کی نصیحت کی جاتی ہے اس سے منہ پھیر لیتے ہیں', NULL, NULL, '9c9bb3638047fa52becd68c4003f4c1b6e7ffaa048df53497f63f44cf51b922d'),
  ('ur.jalandhry', 46, 4, 4514, 'کہو کہ بھلا تم نے ان چیزوں کو دیکھا ہے جن کو تم خدا کے سوا پکارتے ہو (ذرا) مجھے بھی تو دکھاؤ کہ انہوں نے زمین میں کون سی چیز پیدا کی ہے۔ یا آسمانوں میں ان کی شرکت ہے۔ اگر سچے ہو تو اس سے پہلے کی کوئی کتاب میرے پاس لاؤ۔ یا علم (انبیاء میں) سے کچھ (منقول) چلا آتا ہو (تو اسے پیش کرو)', NULL, NULL, '351776a33e0368dd1f51d22e4e9193f16d081f81bea066aafafd2bc4ed884eab'),
  ('ur.jalandhry', 46, 5, 4515, 'اور اس شخص سے بڑھ کر کون گمراہ ہوسکتا ہے جو ایسے کو پکارے جو قیامت تک اسے جواب نہ دے سکے اور ان کو ان کے پکارنے ہی کی خبر نہ ہو', NULL, NULL, '6be43a636f39ab6e68f3fd065f3147be82d3c3c6eeb3e0ebb27d78d1e4923c02'),
  ('ur.jalandhry', 46, 6, 4516, 'اور جب لوگ جمع کئے جائیں گے تو وہ ان کے دشمن ہوں گے اور ان کی پرستش سے انکار کریں گے', NULL, NULL, '4d5ea3b65173102e16660df3f0bc783dcb78816235430430af5d049dbb99dd2d'),
  ('ur.jalandhry', 46, 7, 4517, 'اور جب ان کے سامنے ہماری کھلی آیتیں پڑھی جاتی ہیں تو کافر حق کے بارے میں جب ان کے پاس آچکا کہتے ہیں کہ یہ تو صریح جادو ہے', NULL, NULL, '7d667eb4d5fc73e78c922235f62d731f804f98ec1433989153c628771d945770'),
  ('ur.jalandhry', 46, 8, 4518, 'کیا یہ کہتے ہیں کہ اس نے اس کو از خود بنا لیا ہے۔ کہہ دو کہ اگر میں نے اس کو اپنی طرف سے بنایا ہو تو تم خدا کے سامنے میرے (بچاؤ کے) لئے کچھ اختیار نہیں رکھتے۔ وہ اس گفتگو کو خوب جانتا ہے جو تم اس کے بارے میں کرتے ہو۔ وہی میرے اور تمہارے درمیان گواہ کافی ہے۔ اور وہ بخشنے والا مہربان ہے', NULL, NULL, '11b7f92524d52fa859480f8a9d78fb288896d86cfff9e4f166ad3c23b3fb0cca'),
  ('ur.jalandhry', 46, 9, 4519, 'کہہ دو کہ میں کوئی نیا پیغمبر نہیں آیا۔ اور میں نہیں جانتا کہ میرے ساتھ کیا سلوک کیا جائے گا اور تمہارے ساتھ کیا (کیا جائے گا) میں تو اسی کی پیروی کرتا ہوں جو مجھ پر وحی آتی ہے اور میرا کام تو علانیہ ہدایت کرنا ہے', NULL, NULL, '6f0bcaa67934e9d8574f11c59ae0db6cd76abc3e3f47e40e35cfda0cc988f428'),
  ('ur.jalandhry', 46, 10, 4520, 'کہو کہ بھلا دیکھو تو اگر یہ (قرآن) خدا کی طرف سے ہو اور تم نے اس سے انکار کیا اور بنی اسرائیل میں سے ایک گواہ اسی طرح کی ایک (کتاب) کی گواہی دے چکا اور ایمان لے آیا اور تم نے سرکشی کی (تو تمہارے ظالم ہونے میں کیا شک ہے) ۔ بےشک خدا ظالم لوگوں کو ہدایت نہیں دیتا', NULL, NULL, 'cb685d59e911e04c6a5334e043034b8fcfd5c8dc055b894e3967af1f6d1cf970'),
  ('ur.jalandhry', 46, 11, 4521, 'اور کافر مومنوں سے کہتے ہیں کہ اگر یہ (دین) کچھ بہتر ہوتا تو یہ لوگ اس کی طرف ہم سے پہلے نہ دوڑ پڑتے اور جب وہ اس سے ہدایت یاب نہ ہوئے تو اب کہیں گے کہ یہ پرانا جھوٹ ہے', NULL, NULL, 'cdd93bd86d167db6db6890de47f9bf14a25c776a4ba60f56340fed9abd95dd34'),
  ('ur.jalandhry', 46, 12, 4522, 'اور اس سے پہلے موسیٰ کی کتاب تھی (لوگوں کے لئے) رہنما اور رحمت۔ اور یہ کتاب عربی زبان میں ہے اسی کی تصدیق کرنے والی تاکہ ظالموں کو ڈرائے۔ اور نیکوکاروں کو خوشخبری سنائے', NULL, NULL, '2cbda6d4013d3ce8efd45f179fec1095b8e858ae9a9e7b84ebbb1c7d4f6f2785'),
  ('ur.jalandhry', 46, 13, 4523, 'جن لوگوں نے کہا کہ ہمارا پروردگار خدا ہے پھر وہ (اس پر) قائم رہے تو ان کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے', NULL, NULL, '8ceeb126f374303d54e886c5fc15667188380ec1fdd5fbe739a60b021256ea58'),
  ('ur.jalandhry', 46, 14, 4524, 'یہی اہل جنت ہیں کہ ہمیشہ اس میں رہیں گے۔ (یہ) اس کا بدلہ (ہے) جو وہ کیا کرتے تھے', NULL, NULL, '9b7d9ff4a1097721d6a71690fe99168eab20d31683d321da114083e9d007ca5a'),
  ('ur.jalandhry', 46, 15, 4525, 'اور ہم نے انسان کو اپنے والدین کے ساتھ بھلائی کرنے کا حکم دیا۔ اس کی ماں نے اس کو تکلیف سے پیٹ میں رکھا اور تکلیف ہی سے جنا۔ اور اس کا پیٹ میں رہنا اور دودھ چھوڑنا ڈھائی برس میں ہوتا ہے۔ یہاں تک کہ جب خوب جوان ہوتا ہے اور چالیس برس کو پہنچ جاتا ہے تو کہتا ہے کہ اے میرے پروردگار مجھے توفیق دے کہ تو نے جو احسان مجھ پر اور میرے ماں باپ پر کئے ہیں ان کا شکر گزار ہوں اور یہ کہ نیک عمل کروں جن کو تو پسند کرے۔ اور میرے لئے میری اولاد میں صلاح (وتقویٰ) دے۔ میں تیری طرف رجوع کرتا ہوں اور میں فرمانبرداروں میں ہوں', NULL, NULL, '2d2f82e190d0a4c8c5bd3debec1bb38d23a28c8b5d17dc6f20f28087e5f1c598'),
  ('ur.jalandhry', 46, 16, 4526, 'یہی لوگ ہیں جن کے اعمال نیک ہم قبول کریں گے اور ان کے گناہوں سے درگزر فرمائیں گے اور (یہی) اہل جنت میں (ہوں گے) ۔ (یہ) سچا وعدہ (ہے) جو ان سے کیا جاتا ہے', NULL, NULL, '96433612a2f41845a5c2bc84efe9127d3caac04eb8c429f31dfea2d78db3d27b'),
  ('ur.jalandhry', 46, 17, 4527, 'اور جس شخص نے اپنے ماں باپ سے کہا کہ اُف اُف! تم مجھے یہ بتاتے ہو کہ میں (زمین سے) نکالا جاؤں گا حالانکہ بہت سے لوگ مجھ سے پہلے گزر چکے ہیں۔ اور وہ دونوں خدا کی جناب میں فریاد کرتے (ہوئے کہتے) تھے کہ کم بخت ایمان لا۔ خدا کا وعدہ تو سچا ہے۔ تو کہنے لگا یہ تو پہلے لوگوں کی کہانیاں ہیں', NULL, NULL, 'a04b5da038badcceca2064be3db903ed6f2d6f13435e20934e2a10aadb53c707'),
  ('ur.jalandhry', 46, 18, 4528, 'یہی وہ لوگ ہیں جن کے بارے میں جنوں اور انسانوں کی (دوسری) اُمتوں میں سے جو ان سے پہلے گزر چکیں عذاب کا وعدہ متحقق ہوگیا۔ بےشک وہ نقصان اٹھانے والے تھے', NULL, NULL, '232fe8d1e4e99a34e4400c6397d0afe9b2a977fcfd6b3910d9ce0b7a63f19e4c'),
  ('ur.jalandhry', 46, 19, 4529, 'اور لوگوں نے جیسے کام کئے ہوں گے ان کے مطابق سب کے درجے ہوں گے۔ غرض یہ ہے کہ ان کو ان کے اعمال کا پورا بدلہ دے اور ان کا نقصان نہ کیا جائے', NULL, NULL, 'f7e68bb2ad6d2e233282015a8d1c9764205f7a27f695013e9077d4392cca2cea'),
  ('ur.jalandhry', 46, 20, 4530, 'اور جس دن کافر دوزخ کے سامنے کئے جائیں گے (تو کہا جائے گا کہ) تم اپنی دنیا کی زندگی میں لذتیں حاصل کرچکے اور ان سے متمتع ہوچکے سو آج تم کو ذلت کا عذاب ہے، (یہ) اس کی سزا (ہے) کہ تم زمین میں ناحق غرور کیا کرتے تھے۔ اور اس کی بدکرداری کرتے تھے', NULL, NULL, 'dd66055ed39abae19d6296700bf3dbcc4cc87da6d62f6999b95caddeaba6bbc5'),
  ('ur.jalandhry', 46, 21, 4531, 'اور (قوم) عاد کے بھائی (ہود) کو یاد کرو کہ جب انہوں نے اپنی قوم کو سرزمین احقاف میں ہدایت کی اور ان سے پہلے اور پیچھے بھی ہدایت کرنے والے گزرچکے تھے کہ خدا کے سوا کسی کی عبادت نہ کرو۔ مجھے تمہارے بارے میں بڑے دن کے عذاب کا ڈر لگتا ہے', NULL, NULL, '259dbcec3d24d0f1774ba9045986967895083c3dd9140f5a843a156244eb139d'),
  ('ur.jalandhry', 46, 22, 4532, 'کہنے لگے کیا تم ہمارے پاس اس لئے آئے ہو کہ ہم کو ہمارے معبودوں سے پھیر دو۔ اگر سچے ہو تو جس چیز سے ہمیں ڈراتے ہو اسے ہم پر لے آؤ', NULL, NULL, 'edce82a65d0623f6230ab25e2e535f5729f1643bfa494b76c46a79775feaab5d'),
  ('ur.jalandhry', 46, 23, 4533, '(انہوں نے) کہا کہ (اس کا) علم تو خدا ہی کو ہے۔ اور میں تو جو (احکام) دے کر بھیجا گیا ہوں وہ تمہیں پہنچا رہا ہوں لیکن میں دیکھتا ہوں کہ تم لوگ نادانی میں پھنس رہے ہو', NULL, NULL, 'fd90ddedfd3e2ba83e6a147d90213a3f4db956e5e7681c80e7a50c5499aeea45'),
  ('ur.jalandhry', 46, 24, 4534, 'پھر جب انہوں نے اس (عذاب کو) دیکھا کہ بادل (کی صورت میں) ان کے میدانوں کی طرف آرہا ہے تو کہنے لگے یہ تو بادل ہے جو ہم پر برس کر رہے گا۔ (نہیں) بلکہ (یہ) وہ چیز ہے جس کے لئے تم جلدی کرتے تھے یعنی آندھی جس میں درد دینے والا عذاب بھرا ہوا ہے', NULL, NULL, 'c495c1d417680fa6bb597bcb57a94b47afdb35f3cdbdb91187d7b8763cd67e75'),
  ('ur.jalandhry', 46, 25, 4535, 'ہر چیز کو اپنے پروردگار کے حکم سے تباہ کئے دیتی ہے تو وہ ایسے ہوگئے کہ ان کے گھروں کے سوا کچھ نظر ہی نہیں آتا تھا۔ گنہگار لوگوں کو ہم اسی طرح سزا دیا کرتے ہیں', NULL, NULL, 'fc2c45101c71aeefbdb4ebbe8feb8f2e9f4d43d109a9cf2684427f198db74176'),
  ('ur.jalandhry', 46, 26, 4536, 'اور ہم نے ان کو ایسے مقدور دیئے تھے جو تم لوگوں کو نہیں دیئے اور انہیں کان اور آنکھیں اور دل دیئے تھے۔ تو جب کہ وہ خدا کی آیتوں سے انکار کرتے تھے تو نہ تو ان کے کان ہی ان کے کچھ کام آسکے اور نہ آنکھیں اور نہ دل۔ اور جس چیز سے استہزاء کیا کرتے تھے اس نے ان کو آ گھیرا', NULL, NULL, '884038957499a0e1c4590f4718a8c9b463127327f2a1f45e036a8eeb8485f6df'),
  ('ur.jalandhry', 46, 27, 4537, 'اور تمہارے اردگرد کی بستیوں کو ہم نے ہلاک کر دیا۔ اور بار بار (اپنی) نشانیاں ظاہر کردیں تاکہ وہ رجوع کریں', NULL, NULL, 'ff040598556adcffc656578aa63fd7958b883810b11bbcab8b7e6e05be505952'),
  ('ur.jalandhry', 46, 28, 4538, 'تو جن کو ان لوگوں نے تقرب (خدا) کے سوا معبود بنایا تھا انہوں نے ان کی کیوں مدد نہ کی۔ بلکہ وہ ان (کے سامنے) سے گم ہوگئے۔ اور یہ ان کا جھوٹ تھا اور یہی وہ افتراء کیا کرتے تھے', NULL, NULL, '468e0aaf93a29f6ad0416bdeecedc540d8427576d5cd6fe411ca96f55820c192'),
  ('ur.jalandhry', 46, 29, 4539, 'اور جب ہم نے جنوں میں سے کئی شخص تمہاری طرف متوجہ کئے کہ قرآن سنیں۔ تو جب وہ اس کے پاس آئے تو (آپس میں) کہنے لگے کہ خاموش رہو۔ جب (پڑھنا) تمام ہوا تو اپنی برادری کے لوگوں میں واپس گئے کہ (ان کو) نصیحت کریں', NULL, NULL, 'c1a6aebc82fc78ddbc5a19df5c61893db1568783a7eed227ef78c09dad998b02'),
  ('ur.jalandhry', 46, 30, 4540, 'کہنے لگے کہ اے قوم! ہم نے ایک کتاب سنی ہے جو موسیٰ کے بعد نازل ہوئی ہے۔ جو (کتابیں) اس سے پہلے (نازل ہوئی) ہیں ان کی تصدیق کرتی ہے (اور) سچا (دین) اور سیدھا رستہ بتاتی ہے', NULL, NULL, 'd2e2fefba0314e36ff4e15c5da604ed5e428a9d6b7fbb9083a02633afd8e4fc9'),
  ('ur.jalandhry', 46, 31, 4541, 'اے قوم! خدا کی طرف بلانے والے کی بات قبول کرو اور اس پر ایمان لاؤ۔ خدا تمہارے گناہ بخش دے گا اور تمہیں دکھ دینے والے عذاب سے پناہ میں رکھے گا', NULL, NULL, 'cf675e9ff91255a85ede38fd127a6725be088a3e2e6fe7250b428a2172beec9e'),
  ('ur.jalandhry', 46, 32, 4542, 'اور جو شخص خدا کی طرف بلانے والے کی بات قبول نہ کرے گا تو وہ زمین میں (خدا کو) عاجز نہیں کرسکے گا اور نہ اس کے سوا اس کے حمایتی ہوں گے۔ یہ لوگ صریح گمراہی میں ہیں', NULL, NULL, '208e263a12454848b89db388be46178796f9ab8cc2ec0d5d3e9ad1580708a205'),
  ('ur.jalandhry', 46, 33, 4543, 'کیا انہوں نے نہیں سمجھا کہ جس خدا نے آسمانوں اور زمین کو پیدا کیا اور ان کے پیدا کرنے سے تھکا نہیں۔ وہ اس (بات) پر بھی قادر ہے کہ مردوں کو زندہ کر دے۔ ہاں ہاں وہ ہر چیز پر قادر ہے', NULL, NULL, '8fbed1eb6ca0982875d0e42a9a4c8751b0443e588cc7d38bc28074a5dc843b54'),
  ('ur.jalandhry', 46, 34, 4544, 'اور جس روز آگ کے سامنے کئے جائیں گے (اور کہا جائے گا) کیا یہ حق نہیں ہے؟ تو کہیں گے کیوں نہیں ہمارے پروردگار کی قسم (حق ہے) حکم ہوگا کہ تم جو (دنیا میں) انکار کیا کرتے تھے (اب) عذاب کے مزے چکھو', NULL, NULL, '1a1c1caa5297bb38d50c74e65380db7b2345a7140978edec9db3bd3eea37c1c1'),
  ('ur.jalandhry', 46, 35, 4545, 'پس (اے محمدﷺ) جس طرح اور عالی ہمت پیغمبر صبر کرتے رہے ہیں اسی طرح تم بھی صبر کرو اور ان کے لئے (عذاب) جلدی نہ مانگو۔ جس دن یہ اس چیز کو دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے تو (خیال کریں گے کہ) گویا (دنیا میں) رہے ہی نہ تھے مگر گھڑی بھر دن۔ (یہ قرآن) پیغام ہے۔ سو (اب) وہی ہلاک ہوں گے جو نافرمان تھے', NULL, NULL, 'a0608e3811660ce61c908600d043ba9256e5e2c5d2592bd7df3e927cc97a21bc'),
  ('ur.jalandhry', 47, 1, 4546, 'جن لوگوں نے کفر کیا اور (اَوروں کو) خدا کے رستے سے روکا۔ خدا نے ان کے اعمال برباد کر دیئے', NULL, NULL, '36b2e34f129179dd8873488555a4f0b233ac3026e4abc6f79a6c4811ea347222'),
  ('ur.jalandhry', 47, 2, 4547, 'اور جو ایمان لائے اور نیک عمل کرتے رہے اور جو (کتاب) محمدﷺ پر نازل ہوئی اسے مانتے رہے اور وہ ان کے پروردگار کی طرف سے برحق ہے ان سے ان کے گناہ دور کردیئے اور ان کی حالت سنوار دی', NULL, NULL, '1d58e881878acab5c4cbb9668f07bab454bc78404a20307992dff4acf3ef5a03'),
  ('ur.jalandhry', 47, 3, 4548, 'یہ (حبط اعمال اور اصلاح حال) اس لئے ہے کہ جن لوگوں نے کفر کیا انہوں نے جھوٹی بات کی پیروی کی اور جو ایمان لائے وہ اپنے پروردگار کی طرف سے (دین) حق کے پیچھے چلے۔ اسی طرح خدا لوگوں سے ان کے حالات بیان فرماتا ہے', NULL, NULL, '4ea17756be33cfc5d79d29f8919895a47542faba44754c9a1b54e39d7fdd4aaa'),
  ('ur.jalandhry', 47, 4, 4549, 'جب تم کافروں سے بھڑ جاؤ تو ان کی گردنیں اُڑا دو۔ یہاں تک کہ جب ان کو خوب قتل کرچکو تو (جو زندہ پکڑے جائیں ان کو) مضبوطی سے قید کرلو۔ پھر اس کے بعد یا تو احسان رکھ کر چھوڑ دینا چاہیئے یا کچھ مال لے کر یہاں تک کہ (فریق مقابل) لڑائی (کے) ہتھیار (ہاتھ سے) رکھ دے۔ (یہ حکم یاد رکھو) اور اگر خدا چاہتا تو (اور طرح) ان سے انتقام لے لیتا۔ لیکن اس نے چاہا کہ تمہاری آزمائش ایک (کو) دوسرے سے (لڑوا کر) کرے۔ اور جو لوگ خدا کی راہ میں مارے گئے ان کے عملوں کو ہرگز ضائع نہ کرے گا', NULL, NULL, '5b6469a9d368854c4d8f338d50116271728e5bb2ad5eed2975e15ecfab7b4037'),
  ('ur.jalandhry', 47, 5, 4550, 'ان کو سیدھے رستے پر چلائے گا اور ان کی حالت درست کر دے گا', NULL, NULL, 'a5e107837f141dc7c7d294617b493b9f1edf8789c7c372347717857409ad34d3'),
  ('ur.jalandhry', 47, 6, 4551, 'اور ان کو بہشت میں جس سے انہیں شناسا کر رکھا ہے داخل کرے گا', NULL, NULL, 'e86c0f01cd5e4913d92b0f298b5de3e97c23f0eac6f1ab0292ebb808e521b9b0'),
  ('ur.jalandhry', 47, 7, 4552, 'اے اہل ایمان! اگر تم خدا کی مدد کرو گے تو وہ بھی تمہاری مدد کرے گا اور تم کو ثابت قدم رکھے گا', NULL, NULL, 'a134cbdf123c95aa3a9bd8dbbd30078dd4970287dbbc6e1431a794b39d480928'),
  ('ur.jalandhry', 47, 8, 4553, 'اور جو کافر ہیں ان کے لئے ہلاکت ہے۔ اور وہ ان کے اعمال کو برباد کر دے گا', NULL, NULL, 'ebb912ff36c47a760e30c5454742039bc37c49318dbae2e96951d2ec637ef016'),
  ('ur.jalandhry', 47, 9, 4554, 'یہ اس لئے کہ خدا نے جو چیز نازل فرمائی انہوں نے اس کو ناپسند کیا تو خدا نے بھی ان کے اعمال اکارت کردیئے', NULL, NULL, '687f7e2f7f612241f55078a9cb40aa283b571d630a5eac135179d9b00b5e09cd'),
  ('ur.jalandhry', 47, 10, 4555, 'کیا انہوں نے ملک میں سیر نہیں کی تاکہ دیکھتے کہ جو لوگ ان سے پہلے تھے ان کا انجام کیسا ہوا؟ خدا نے ان پر تباہی ڈال دی۔ اور اسی طرح کا (عذاب) ان کافروں کو ہوگا', NULL, NULL, '0eb6aa302008a36649295e09e93c688f9bb06faf77df897e17b33239dede2ae2'),
  ('ur.jalandhry', 47, 11, 4556, 'یہ اس لئے کہ جو مومن ہیں ان کا خدا کارساز ہے اور کافروں کا کوئی کارساز نہیں', NULL, NULL, '0bfbc3e247b0738d35ae26dcc16d9c9b86e76a47feb5146424804996c25f7550'),
  ('ur.jalandhry', 47, 12, 4557, 'جو لوگ ایمان لائے اور عمل نیک کرتے رہے ان کو خدا بہشتوں میں جن کے نیچے نہریں بہہ رہی ہیں داخل فرمائے گا۔ اور جو کافر ہیں وہ فائدے اٹھاتے ہیں اور (اس طرح) کھاتے ہیں جیسے حیوان کھاتے ہیں۔ اور ان کا ٹھکانہ دوزخ ہے', NULL, NULL, 'ef539693d4d2e9b00f5b1906681a55ff0cfe5bbf456024e529c1ebcd9cf1ca32'),
  ('ur.jalandhry', 47, 13, 4558, 'اور بہت سی بستیاں تمہاری بستی سے جس (کے باشندوں نے تمہیں وہاں) سے نکال دیا زور وقوت میں کہیں بڑھ کر تھیں ہم نے ان کا ستیاناس کردیا اور ان کا کوئی مددگار نہ ہوا', NULL, NULL, '4349e50e80679d1e42ebf8e7b8debe71067a9f234ee485d1376ccedbd1bbd4b5'),
  ('ur.jalandhry', 47, 14, 4559, 'بھلا جو شخص اپنے پروردگار (کی مہربانی) سے کھلے رستے پر (چل رہا) ہو وہ ان کی طرح (ہوسکتا) ہے جن کے اعمال بد انہیں اچھے کرکے دکھائی جائیں اور جو اپنی خواہشوں کی پیروی کریں', NULL, NULL, '125d920f0ea9c289397dc435eaa6ce78ae3c8455e6dc275555c7e1242f0edb63'),
  ('ur.jalandhry', 47, 15, 4560, 'جنت جس کا پرہیزگاروں سے وعدہ کیا جاتا ہے۔ اس کی صفت یہ ہے کہ اس میں پانی کی نہریں ہیں جو بو نہیں کرے گا۔ اور دودھ کی نہریں ہیں جس کا مزہ نہیں بدلے گا۔ اور شراب کی نہریں ہیں جو پینے والوں کے لئے (سراسر) لذت ہے۔ اور شہد مصفا کی نہریں ہیں (جو حلاوت ہی حلاوت ہے) اور (وہاں) ان کے لئے ہر قسم کے میوے ہیں اور ان کے پروردگار کی طرف سے مغفرت ہے۔ (کیا یہ پرہیزگار) ان کی طرح (ہوسکتے) ہیں جو ہمیشہ دوزخ میں رہیں گے اور جن کو کھولتا ہوا پانی پلایا جائے گا تو ان کی انتڑیوں کو کاٹ ڈالے گا', NULL, NULL, '3f95d29695761b1ccd3e45dc89cdaaf51eef8cfe9fdf0d2b7728ac25c6576eb9'),
  ('ur.jalandhry', 47, 16, 4561, 'اور ان میں بعض ایسے بھی ہیں جو تمہاری طرف کان لگائے یہاں تک کہ (سب کچھ سنتے ہیں لیکن) جب تمہارے پاس سے نکل کر چلے جاتے ہیں تو جن لوگوں کو علم (دین) دیا گیا ہے ان سے کہتے ہیں کہ (بھلا) انہوں نے ابھی کیا کہا تھا؟ یہی لوگ ہیں جن کے دلوں پر خدا نے مہر لگا رکھی ہے اور وہ اپنی خواہشوں کے پیچھے چل رہے ہیں', NULL, NULL, '1a82bcafbb4f618a6ca764429c6e6f81843eeae31addcf9ab1a351a4232727d4'),
  ('ur.jalandhry', 47, 17, 4562, 'اور جو لوگ ہدایت یافتہ ہیں ان کو وہ ہدایت مزید بخشتا اور پرہیزگاری عنایت کرتا ہے', NULL, NULL, '00125bbe844aae6f8422c5764bcc25eb9fc515b114b13e68c1497128be17b043'),
  ('ur.jalandhry', 47, 18, 4563, 'اب تو یہ لوگ قیامت ہی کو دیکھ رہے ہیں کہ ناگہاں ان پر آ واقع ہو۔ سو اس کی نشانیاں (وقوع میں) آچکی ہیں۔ پھر جب وہ ان پر آ نازل ہوگی اس وقت انہیں نصیحت کہاں (مفید ہوسکے گی؟)', NULL, NULL, 'c66827b167d0dd8fae785641615824b267771b84b45d9c53dbcaf6acba086c75'),
  ('ur.jalandhry', 47, 19, 4564, 'پس جان رکھو کہ خدا کے سوا کوئی معبود نہیں اور اپنے گناہوں کی معافی مانگو اور (اور) مومن مردوں اور مومن عورتوں کے لئے بھی۔ اور خدا تم لوگوں کے چلنے پھرنے اور ٹھیرنے سے واقف ہے', NULL, NULL, '7f1bee30d621c5c68a9f6dddab4fa45c9e4877b0109b1a57c2fbe6b9bd5d5863'),
  ('ur.jalandhry', 47, 20, 4565, 'اور مومن لوگ کہتے ہیں کہ (جہاد کی) کوئی سورت کیوں نازل نہیں ہوتی؟ لیکن جب کوئی صاف معنوں کی سورت نازل ہو اور اس میں جہاد کا بیان ہو تو جن لوگوں کے دلوں میں (نفاق کا) مرض ہے تم ان کو دیکھو کہ تمہاری طرف اس طرح دیکھنے لگیں جس طرح کسی پر موت کی بےہوشی (طاری) ہو رہی ہو۔ سو ان کے لئے خرابی ہے', NULL, NULL, '02d0b7d202264a2c13642894851bb4e9ad056a72c01c66880fbd6381cf199e44'),
  ('ur.jalandhry', 47, 21, 4566, '(خوب کام تو) فرمانبرداری اور پسندیدہ بات کہنا (ہے) پھر جب (جہاد کی) بات پختہ ہوگئی تو اگر یہ لوگ خدا سے سچے رہنا چاہتے تو ان کے لئے بہت اچھا ہوتا', NULL, NULL, 'b61257d2ccf368f7e0810ee1e93476fd94c31e50395d85e6557a28594fbe3212'),
  ('ur.jalandhry', 47, 22, 4567, '(اے منافقو!) تم سے عجب نہیں کہ اگر تم حاکم ہو جاؤ تو ملک میں خرابی کرنے لگو اور اپنے رشتوں کو توڑ ڈالو', NULL, NULL, 'fe7dfd54edde800cc0c72fae07c2af9d81176d444eabeeadcd979661605259d6'),
  ('ur.jalandhry', 47, 23, 4568, 'یہی لوگ ہیں جن پر خدا نے لعنت کی ہے اور ان (کے کانوں) کو بہرا اور (ان کی) آنکھوں کو اندھا کردیا ہے', NULL, NULL, 'e3216f70ff01379ca7cc6b96021c499654fc2b1fa76d474601efbd1e9743ce34'),
  ('ur.jalandhry', 47, 24, 4569, 'بھلا یہ لوگ قرآن میں غور نہیں کرتے یا (ان کے) دلوں پر قفل لگ رہے ہیں', NULL, NULL, 'e5c753931536a337e35db3c1617cb46a2161777bdfb723c5a6f4ab3c8f7c554a'),
  ('ur.jalandhry', 47, 25, 4570, 'جو لوگ راہ ہدایت ظاہر ہونے کے بعد پیٹھ دے کر پھر گئے۔ شیطان نے (یہ کام) ان کو مزین کر دکھایا اور انہیں طول (عمر کا وعدہ) دیا', NULL, NULL, 'f0657c5b1c66b4854c7df7344faf31dbd6414c6d88787fa9869eb633aa87dca0'),
  ('ur.jalandhry', 47, 26, 4571, 'یہ اس لئے کہ جو لوگ خدا کی اُتاری ہوئی (کتاب) سے بیزار ہیں یہ ان سے کہتے ہیں کہ بعض کاموں میں ہم تمہاری بات بھی مانیں گے۔ اور خدا ان کے پوشیدہ مشوروں سے واقف ہے', NULL, NULL, '6e65ad0899fa7d1a53e4427947d34420e13f90f9974107e3273b77a026ed1c7f'),
  ('ur.jalandhry', 47, 27, 4572, 'تو اُس وقت (ان کا) کیسا (حال) ہوگا جب فرشتے ان کی جان نکالیں گے اور ان کے مونہوں اور پیٹھوں پر مارتے جائیں گے', NULL, NULL, '6731866779a12f0e590dcb6bedbd0dd95771d4543e78bd02b571c41130839182'),
  ('ur.jalandhry', 47, 28, 4573, 'یہ اس لئے کہ جس چیز سے خدا ناخوش ہے یہ اس کے پیچھے چلے اور اس کی خوشنودی کو اچھا نہ سمجھے تو اُس نے بھی ان کے عملوں کو برباد کر دیا', NULL, NULL, 'bf56c9664534bdfc057672609075c380b955c355f0a1c18ce2f738cf5f4c2e70'),
  ('ur.jalandhry', 47, 29, 4574, 'کیا وہ لوگ جن کے دلوں میں بیماری ہے یہ خیال کئے ہوئے ہیں کہ خدا ان کے کینوں کو ظاہر نہیں کرے گا؟', NULL, NULL, '6685231fd0d398e0652ff3f3955b5542946e8ba674c372e4940a66ae37aba274'),
  ('ur.jalandhry', 47, 30, 4575, 'اور اگر ہم چاہتے تو وہ لوگ تم کو دکھا بھی دیتے اور تم ان کو ان کے چہروں ہی سے پہچان لیتے۔ اور تم انہیں (ان کے) انداز گفتگو ہی سے پہچان لو گے! اور خدا تمہارے اعمال سے واقف ہے', NULL, NULL, '2477b60242356dad9cd866988fd77189bd87e97932ca0b20c0bfa0c77e93ab6a'),
  ('ur.jalandhry', 47, 31, 4576, 'اور ہم تو لوگوں کو آزمائیں گے تاکہ جو تم میں لڑائی کرنے والے اور ثابت قدم رہنے والے ہیں ان کو معلوم کریں۔ اور تمہارے حالات جانچ لیں', NULL, NULL, '19a8d8801094149b3065ab3c4fc5cb9b92349f365ea8d642c601f070d104a900'),
  ('ur.jalandhry', 47, 32, 4577, 'جن لوگوں کو سیدھا رستہ معلوم ہوگیا (اور) پھر بھی انہوں نے کفر کیا اور (لوگوں کو) خدا کی راہ سے روکا اور پیغمبر کی مخالفت کی وہ خدا کا کچھ بھی بگاڑ نہیں سکیں گے۔ اور خدا ان کا سب کیا کرایا اکارت کردے گا', NULL, NULL, '44d7d6bb5fafef2ae87bf49c91f889f7164c87751d20374b0026965167683cf1'),
  ('ur.jalandhry', 47, 33, 4578, 'مومنو! خدا کا ارشاد مانو اور پیغمبر کی فرمانبرداری کرو اور اپنے عملوں کو ضائع نہ ہونے دو', NULL, NULL, '73bfb401e4681d2f5aa3557227899d37352413620e58dc177aa52fed48ced114'),
  ('ur.jalandhry', 47, 34, 4579, 'جو لوگ کافر ہوئے اور خدا کے رستے سے روکتے رہے پھر کافر ہی مرگئے خدا ان کو ہرگز نہیں بخشے گا', NULL, NULL, '78561ba238d12a77a612ce23fd612f19f0e15140f5cb5d993175bb1fad0b226b'),
  ('ur.jalandhry', 47, 35, 4580, 'تو تم ہمت نہ ہارو اور (دشمنوں کو) صلح کی طرف نہ بلاؤ۔ اور تم تو غالب ہو۔ اور خدا تمہارے ساتھ ہے وہ ہرگز تمہارے اعمال کو کم (اور گم) نہیں کرے گا', NULL, NULL, '124a65f2bfe1fdb4912e17ee3948108954262fc406ec8e399b1bc1e371259343'),
  ('ur.jalandhry', 47, 36, 4581, 'دنیا کی زندگی تو محض کھیل اور تماشا ہے۔ اور اگر تم ایمان لاؤ گے اور پرہیزگاری کرو گے تو وہ تم کو تمہارا اجر دے گا۔ اور تم سے تمہارا مال طلب نہیں کرے گا', NULL, NULL, '92f14f7630424c544cd4b3f202fb9c2ae19ff252a84ef893ffb6f40463bdd2f7'),
  ('ur.jalandhry', 47, 37, 4582, 'اگر وہ تم سے مال طلب کرے اور تمہیں تنگ کرے تو تم بخل کرنے لگو اور وہ (بخل) تمہاری بدنیتی ظاہر کرکے رہے', NULL, NULL, '9a846566cfb2196bf2d1edb918cbbf15247a6045d146e0a6ec0696103e752280'),
  ('ur.jalandhry', 47, 38, 4583, 'دیکھو تم وہ لوگ ہو کہ خدا کی راہ میں خرچ کرنے کے لئے بلائے جاتے ہو۔ تو تم میں ایسے شخص بھی ہیں جو بخل کرنے لگتے ہیں۔ اور جو بخل کرتا ہے اپنے آپ سے بخل کرتا ہے۔ اور خدا بےنیاز ہے اور تم محتاج۔ اور اگر تم منہ پھیرو گے تو وہ تمہاری جگہ اور لوگوں کو لے آئے گا اور وہ تمہاری طرح کے نہیں ہوں گے', NULL, NULL, '00fe015850480f7e710fb6f5964f3467950737c646e467c7e501b7acc7d4992c'),
  ('ur.jalandhry', 48, 1, 4584, '(اے محمدﷺ) ہم نے تم کو فتح دی۔ فتح بھی صریح وصاف', NULL, NULL, '8359601d5be4d9a7e530e59380e93cba27be69ffe11ef9681b38ef35ce0b73c2'),
  ('ur.jalandhry', 48, 2, 4585, 'تاکہ خدا تمہارے اگلے اور پچھلے گناہ بخش دے اور تم پر اپنی نعمت پوری کردے اور تمہیں سیدھے رستے چلائے', NULL, NULL, '481cd6420e054c9bfc3b31cc8987286f38306c35e8d30a3fa70c3287aefad365'),
  ('ur.jalandhry', 48, 3, 4586, 'اور خدا تمہاری زبردست مدد کرے', NULL, NULL, '970a4092bfee2527cc3069a5e10c5a4aa41e9361aa597c3e2f3cdb4ab0dd6ec7'),
  ('ur.jalandhry', 48, 4, 4587, 'وہی تو ہے جس نے مومنوں کے دلوں پر تسلی نازل فرمائی تاکہ ان کے ایمان کے ساتھ اور ایمان بڑھے۔ اور آسمانوں اور زمین کے لشکر (سب) خدا ہی کے ہیں۔ اور خدا جاننے والا (اور) حکمت والا ہے', NULL, NULL, '9b7887a8f70e0b04dd5d82d7b0e5aa5807080d626f812b05446f6623cf141d85'),
  ('ur.jalandhry', 48, 5, 4588, '(یہ) اس لئے کہ وہ مومن مردوں اور مومن عورتوں کو بہشتوں میں جن کے نیچے نہریں بہہ رہی ہیں داخل کرے وہ اس میں ہمیشہ رہیں گے اور ان سے ان کے گناہوں کو دور کردے۔ اور یہ خدا کے نزدیک بڑی کامیابی ہے', NULL, NULL, 'd4073ebbf1d8a65196d24010f14946a32abb28d31b3fa70513d5dded3841a0fb'),
  ('ur.jalandhry', 48, 6, 4589, 'اور (اس لئے کہ) منافق مردوں اور منافق عورتوں اور مشرک مردوں اور مشرک عورتوں کو جو خدا کے حق میں برے برے خیال رکھتے ہیں عذاب دے۔ ان ہی پر برے حادثے واقع ہوں۔ اور خدا ان پر غصے ہوا اور ان پر لعنت کی اور ان کے لئے دوزخ تیار کی۔ اور وہ بری جگہ ہے', NULL, NULL, '22b18e5aeb9b1c5bdd93a9483db0434c36fb92a8ba79c5c96be05d3d9d44f637'),
  ('ur.jalandhry', 48, 7, 4590, 'اور آسمانوں اور زمین کے لشکر خدا ہی کے ہیں۔ اور خدا غالب (اور) حکمت والا ہے', NULL, NULL, 'f5dd949763219e087ed6f35143b40c4ce6970edd7ccb3a3497e4decda5d3b453'),
  ('ur.jalandhry', 48, 8, 4591, 'اور ہم نے (اے محمدﷺ) تم کو حق ظاہر کرنے والا اور خوشخبری سنانے والا اور خوف دلانے والا (بنا کر) بھیجا ہے', NULL, NULL, '93fc821d5ba00d3f6b78d5b69ae6f51c820184980a4c3009f5f8522ea6c7c5b1'),
  ('ur.jalandhry', 48, 9, 4592, 'تاکہ (مسلمانو) تم لوگ خدا پر اور اس کے پیغمبر پر ایمان لاؤ اور اس کی مدد کرو اور اس کو بزرگ سمجھو۔ اور صبح وشام اس کی تسبیح کرتے رہو', NULL, NULL, 'cb9098990a8ad1a4c099ad5eb1f92cf5fc2fc56ae7aa5e53e2c303b7abdce660'),
  ('ur.jalandhry', 48, 10, 4593, 'جو لوگ تم سے بیعت کرتے ہیں وہ خدا سے بیعت کرتے ہیں۔ خدا کا ہاتھ ان کے ہاتھوں پر ہے۔ پھر جو عہد کو توڑے تو عہد توڑنے کا نقصان اسی کو ہے۔ اور جو اس بات کو جس کا اس نے خدا سے عہد کیا ہے پورا کرے تو وہ اسے عنقریب اجر عظیم دے گا', NULL, NULL, 'ac2005fd560f2cb5efa84c94c2a8523ce21f80c20c7347949ab696b32038e3dc'),
  ('ur.jalandhry', 48, 11, 4594, 'جو گنوار پیچھے رہ گئے وہ تم سے کہیں گے کہ ہم کو ہمارے مال اور اہل وعیال نے روک رکھا آپ ہمارے لئے (خدا سے) بخشش مانگیں۔ یہ لوگ اپنی زبان سے وہ بات کہتے ہیں جو ان کے دل میں نہیں ہے۔ کہہ دو کہ اگر خدا تم (لوگوں) کو نقصان پہنچانا چاہے یا تمہیں فائدہ پہنچانے کا ارادہ فرمائے تو کون ہے جو اس کے سامنے تمہارے لئے کسی بات کا کچھ اختیار رکھے (کوئی نہیں) بلکہ جو کچھ تم کرتے ہو خدا اس سے واقف ہے', NULL, NULL, 'f95a68c4414f4ca0bd6179bc4794c7fac9de1dfa5246760f4a2229cb8e254f3e'),
  ('ur.jalandhry', 48, 12, 4595, 'بات یہ ہے کہ تم لوگ یہ سمجھ بیٹھے تھے کہ پیغمبر اور مومن اپنے اہل وعیال میں کبھی لوٹ کر آنے ہی کے نہیں۔ اور یہی بات تمہارے دلوں کو اچھی معلوم ہوئی۔ اور (اسی وجہ سے) تم نے برے برے خیال کئے اور (آخرکار) تم ہلاکت میں پڑ گئے', NULL, NULL, '72b5d6664221a4d7143c73684c14887cb755086df653e464a9491c51b8883e16'),
  ('ur.jalandhry', 48, 13, 4596, 'اور جو شخص خدا پر اور اس کے پیغمبر پر ایمان نہ لائے تو ہم نے (ایسے) کافروں کے لئے آگ تیار کر رکھی ہے', NULL, NULL, 'be61d6188393dcfcd3fe9c7b4277da8e446aecf84605a7da43e621da0b8ab995'),
  ('ur.jalandhry', 48, 14, 4597, 'اور آسمانوں اور زمین کی بادشاہی خدا ہی کی ہے۔ وہ جسے چاہے بخشے اور جسے چاہے سزا دے۔ اور خدا بخشنے والا مہربان ہے', NULL, NULL, 'c07914b04a6a2bd108db7fddffdaa8f2618521a86deab707ece63c483df7e1d0'),
  ('ur.jalandhry', 48, 15, 4598, 'جب تم لوگ غنیمتیں لینے چلو گے تو جو لوگ پیچھے رہ گئے تھے وہ کہیں گے ہمیں بھی اجازت دیجیئے کہ آپ کے ساتھ چلیں۔ یہ چاہتے ہیں کہ خدا کے قول کو بدل دیں۔ کہہ دو کہ تم ہرگز ہمارے ساتھ نہیں چل سکتے۔ اسی طرح خدا نے پہلے سے فرما دیا ہے۔ پھر کہیں گے (نہیں) تم تو ہم سے حسد کرتے ہو۔ بات یہ ہے کہ یہ لوگ سمجھتے ہی نہیں مگر بہت کم', NULL, NULL, '45ba5eb2b770d9be1f2c8c346d1086a25c291edcaf2ef4203023acde80162286'),
  ('ur.jalandhry', 48, 16, 4599, 'جو گنوار پیچھے رہ گئے تھے ان سے کہہ دو کہ تم ایک سخت جنگجو قوم کے (ساتھ لڑائی کے) لئے بلائے جاؤ گے ان سے تم (یا تو) جنگ کرتے رہو گے یا وہ اسلام لے آئیں گے۔ اگر تم حکم مانو گے تو خدا تم کو اچھا بدلہ دے گا۔ اور اگر منہ پھیر لو گے جیسے پہلی دفعہ پھیرا تھا تو وہ تم کو بری تکلیف کی سزا دے گا', NULL, NULL, '680573db44ae429498bf1b76874479dfe512a6ce1a45d47d272e14967cd828e7'),
  ('ur.jalandhry', 48, 17, 4600, 'نہ تو اندھے پر گناہ ہے (کہ سفر جنگ سے پیچھے رہ جائے) اور نہ لنگڑے پر گناہ ہے اور نہ بیمار پر گناہ ہے۔ اور جو شخص خدا اور اس کے پیغمبر کے فرمان پر چلے گا خدا اس کو بہشتوں میں داخل کرے گا جن کے تلے نہریں بہہ رہی ہیں۔ اور جو روگردانی کرے گا اسے برے دکھ کی سزا دے گا', NULL, NULL, '4d8416f78b1cbc826b8803dbc010274ac35a945f4274109539dfae3dce01ebf2')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
    translation_text = EXCLUDED.translation_text,
    translator_note = EXCLUDED.translator_note,
