INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 48, 18, 4601, '(اے پیغمبر) جب مومن تم سے درخت کے نیچے بیعت کر رہے تھے تو خدا ان سے خوش ہوا۔ اور جو (صدق وخلوص) ان کے دلوں میں تھا وہ اس نے معلوم کرلیا۔ تو ان پر تسلی نازل فرمائی اور انہیں جلد فتح عنایت کی', NULL, NULL, 'ac2f9952d08fd7924cbf3cbcd16da34238c3265ebc84f1bc8ce8523b0c269aad'),
  ('ur.jalandhry', 48, 19, 4602, 'اور بہت سی غنیمتیں جو انہوں نے حاصل کیں۔ اور خدا غالب حکمت والا ہے', NULL, NULL, 'afe9c70ddb458225e558178517ac3d9d9db5e7f7baba000e25a7d0b7aa92a3d4'),
  ('ur.jalandhry', 48, 20, 4603, 'خدا نے تم سے بہت سی غنیمتوں کا وعدہ فرمایا کہ تم ان کو حاصل کرو گے سو اس نے غنیمت کی تمہارے لئے جلدی فرمائی اور لوگوں کے ہاتھ تم سے روک دیئے۔ غرض یہ تھی کہ یہ مومنوں کے لئے (خدا کی) قدرت کا نمونہ ہو اور وہ تم کو سیدھے رستے پر چلائے', NULL, NULL, '6ea614b726319e42efe0b8c24b5279a2269ae31076fa8f85685102adfd69bdfd'),
  ('ur.jalandhry', 48, 21, 4604, 'اور اَور (غنیمتیں دیں) جن پر تم قدرت نہیں رکھتے تھے (اور) وہ خدا ہی کی قدرت میں تھیں۔ اور خدا ہر چیز پر قادر ہے', NULL, NULL, '442594d25d0c2ee4e1b9472f217a95e0656e5b39a945e32eed5a1f8f76cf1214'),
  ('ur.jalandhry', 48, 22, 4605, 'اور اگر تم سے کافر لڑتے تو پیٹھ پھیر کر بھاگ جاتے پھر کسی کو دوست نہ پاتے اور نہ مددگار', NULL, NULL, '6d5214536a3593941a96f5a0ec9e072a0659b1854d3dae0ceb78f400349d0209'),
  ('ur.jalandhry', 48, 23, 4606, '(یہی) خدا کی عادت ہے جو پہلے سے چلی آتی ہے۔ اور تم خدا کی عادت کبھی بدلتی نہ دیکھو گے', NULL, NULL, 'edd98b275090dce842fa54f6031d17730e9c54c1c22625c6f5a9d61916d5592f'),
  ('ur.jalandhry', 48, 24, 4607, 'اور وہی تو ہے جس نے تم کو ان (کافروں) پر فتحیاب کرنے کے بعد سرحد مکہ میں ان کے ہاتھ تم سے اور تمہارے ہاتھ ان سے روک دیئے۔ اور جو کچھ تم کرتے ہو خدا اس کو دیکھ رہا ہے', NULL, NULL, '2e217b7194437b785a2afede201e9d80a58cf68deecf15145f3b3437c9977865'),
  ('ur.jalandhry', 48, 25, 4608, 'یہ وہی لوگ ہیں جنہوں نے کفر کیا اور تم کو مسجد حرام سے روک دیا اور قربانیوں کو بھی کہ اپنی جگہ پہنچنے سے رکی رہیں۔ اور اگر ایسے مسلمان مرد اور مسلمان عورتیں نہ ہوتیں جن کو تم جانتے نہ تھے کہ اگر تم ان کو پامال کر دیتے تو تم کو ان کی طرف سے بےخبری میں نقصان پہنچ جاتا۔ (تو بھی تمہارے ہاتھ سے فتح ہوجاتی مگر تاخیر) اس لئے (ہوئی) کہ خدا اپنی رحمت میں جس کو چاہے داخل کرلے۔ اور اگر دونوں فریق الگ الگ ہوجاتے تو جو ان میں کافر تھے ان ہم دکھ دینے والا عذاب دیتے', NULL, NULL, 'f45d568640c280cf355d7a6e6657d9cf897d2e36b447c91f282e4d85f5996e77'),
  ('ur.jalandhry', 48, 26, 4609, 'جب کافروں نے اپنے دلوں میں ضد کی اور ضد بھی جاہلیت کی۔ تو خدا نے اپنے پیغمبر اور مومنوں پر اپنی طرف سے تسکین نازل فرمائی اور ان کو پرہیزگاری کی بات پر قائم رکھا اور وہ اسی کے مستحق اور اہل تھے۔ اور خدا ہر چیز سے خبردار ہے', NULL, NULL, '6a5855e7bd4ee163a68f480dbf5a75f7a64d9a8719591973fc04ba952c12ea3f'),
  ('ur.jalandhry', 48, 27, 4610, 'بےشک خدا نے اپنے پیغمبر کو سچا (اور) صحیح خواب دکھایا۔ کہ تم خدا نے چاہا تو مسجد حرام میں اپنے سر منڈوا کر اور اپنے بال کتروا کر امن وامان سے داخل ہوگے۔ اور کسی طرح کا خوف نہ کرو گے۔ جو بات تم نہیں جانتے تھے اس کو معلوم تھی سو اس نے اس سے پہلے ہی جلد فتح کرادی', NULL, NULL, 'e9e5a48e19cb90c0331113b30012a5e8527bec390a3fae588fde917f2de34298'),
  ('ur.jalandhry', 48, 28, 4611, 'وہی تو ہے جس نے اپنے پیغمبر کو ہدایت (کی کتاب) اور دین حق دے کر بھیجا تاکہ اس کو تمام دینوں پر غالب کرے۔ اور حق ظاہر کرنے کے لئے خدا ہی کافی ہے', NULL, NULL, 'eca577c56ea5b373a52eb6754f3519c990253f08db40dee9be54d7e68db351cc'),
  ('ur.jalandhry', 48, 29, 4612, 'محمدﷺ خدا کے پیغمبر ہیں اور جو لوگ ان کے ساتھ ہیں وہ کافروں کے حق میں سخت ہیں اور آپس میں رحم دل، (اے دیکھنے والے) تو ان کو دیکھتا ہے کہ (خدا کے آگے) جھکے ہوئے سر بسجود ہیں اور خدا کا فضل اور اس کی خوشنودی طلب کر رہے ہیں۔ (کثرت) سجود کے اثر سے ان کی پیشانیوں پر نشان پڑے ہوئے ہیں۔ ان کے یہی اوصاف تورات میں (مرقوم) ہیں۔ اور یہی اوصاف انجیل میں ہیں۔ (وہ) گویا ایک کھیتی ہیں جس نے (پہلے زمین سے) اپنی سوئی نکالی پھر اس کو مضبوط کیا پھر موٹی ہوئی اور پھر اپنی نال پر سیدھی کھڑی ہوگئی اور لگی کھیتی والوں کو خوش کرنے تاکہ کافروں کا جی جلائے۔ جو لوگ ان میں سے ایمان لائے اور نیک عمل کرتے رہے ان سے خدا نے گناہوں کی بخشش اور اجر عظیم کا وعدہ کیا ہے', NULL, NULL, 'f7e9f1cb8373da7aac87e7451f3ce2dedea1941737e7d91c13d4ca51216b607c'),
  ('ur.jalandhry', 49, 1, 4613, 'مومنو! (کسی بات کے جواب میں) خدا اور اس کے رسول سے پہلے نہ بول اٹھا کرو اور خدا سے ڈرتے رہو۔ بےشک خدا سنتا جانتا ہے', NULL, NULL, '77b61f857a5336ccba036e769dba5b3aae115fb42c60612e140236b9abe42001'),
  ('ur.jalandhry', 49, 2, 4614, 'اے اہل ایمان! اپنی آوازیں پیغمبر کی آواز سے اونچی نہ کرو اور جس طرح آپس میں ایک دوسرے سے زور سے بولتے ہو (اس طرح) ان کے روبرو زور سے نہ بولا کرو (ایسا نہ ہو) کہ تمہارے اعمال ضائع ہوجائیں اور تم کو خبر بھی نہ ہو', NULL, NULL, '69ab96c4cd67a4e7e7f51147cf7b79290bbfc7a55d8d803157825738e9461f3d'),
  ('ur.jalandhry', 49, 3, 4615, 'جو لوگ پیغمبر خدا کے سامنے دبی آواز سے بولتے ہیں خدا نے ان کے دل تقویٰ کے لئے آزما لئے ہیں۔ ان کے لئے بخشش اور اجر عظیم ہے', NULL, NULL, '11b58c331f467288b3985354a0cd634b8f40dd6fcf5cd847a23993300f0b9844'),
  ('ur.jalandhry', 49, 4, 4616, 'جو لوگ تم کو حجروں کے باہر سے آواز دیتے ہیں ان میں اکثر بےعقل ہیں', NULL, NULL, 'e2cfb2d54f73ba88a0d758fe861b00d4e50404f292a527d59c4d67be549f32ef'),
  ('ur.jalandhry', 49, 5, 4617, 'اور اگر وہ صبر کئے رہتے یہاں تک کہ تم خود نکل کر ان کے پاس آتے تو یہ ان کے لئے بہتر تھا۔ اور خدا تو بخشنے والا مہربان ہے', NULL, NULL, '659abfa5f9eb1e1425cd45c17259a64d42148ca6399bafcc33f896033afa048e'),
  ('ur.jalandhry', 49, 6, 4618, 'مومنو! اگر کوئی بدکردار تمہارے پاس کوئی خبر لے کر آئے تو خوب تحقیق کرلیا کرو (مبادا) کہ کسی قوم کو نادانی سے نقصان پہنچا دو۔ پھر تم کو اپنے کئے پر نادم ہونا پڑے', NULL, NULL, 'd41cac62ac7e9d790904b5ccc5cf51baee4188f2455408051f14f1649a7b3b6b'),
  ('ur.jalandhry', 49, 7, 4619, 'اور جان رکھو کہ تم میں خدا کے پیغمبرﷺ ہیں۔ اگر بہت سی باتوں میں وہ تمہارا کہا مان لیا کریں تو تم مشکل میں پڑ جاؤ لیکن خدا نے تم کو ایمان عزیز بنا دیا اور اس کو تمہارے دلوں میں سجا دیا اور کفر اور گناہ اور نافرمانی سے تم کو بیزار کردیا۔ یہی لوگ راہ ہدایت پر ہیں', NULL, NULL, '5850a789b84635d47a1db2a969be01b1726c707d6ac8aa7028716db0d9d436cd'),
  ('ur.jalandhry', 49, 8, 4620, '(یعنی) خدا کے فضل اور احسان سے۔ اور خدا جاننے والا (اور) حکمت والا ہے', NULL, NULL, 'e6b0f0eab2e21b51fdada3db8276933889ba0edf5a45789cd3dd36fd13d52296'),
  ('ur.jalandhry', 49, 9, 4621, 'اور اگر مومنوں میں سے کوئی دو فریق آپس میں لڑ پڑیں تو ان میں صلح کرا دو۔ اور اگر ایک فریق دوسرے پر زیادتی کرے تو زیادتی کرنے والے سے لڑو یہاں تک کہ وہ خدا کے حکم کی طرف رجوع لائے۔ پس جب وہ رجوع لائے تو وہ دونوں فریق میں مساوات کے ساتھ صلح کرا دو اور انصاف سے کام لو۔ کہ خدا انصاف کرنے والوں کو پسند کرتا ہے', NULL, NULL, '210a3d6a3a05e5cea67c309dd4f272566c7b6942e097f8250194be6bc2dd74d3'),
  ('ur.jalandhry', 49, 10, 4622, 'مومن تو آپس میں بھائی بھائی ہیں۔ تو اپنے دو بھائیوں میں صلح کرادیا کرو۔ اور خدا سے ڈرتے رہو تاکہ تم پر رحمت کی جائے', NULL, NULL, 'fbef6ea4ea2d864064dd6981122fd7b413e5afd160276caa07bf459bcb9f8146'),
  ('ur.jalandhry', 49, 11, 4623, 'مومنو! کوئی قوم کسی قوم سے تمسخر نہ کرے ممکن ہے کہ وہ لوگ ان سے بہتر ہوں اور نہ عورتیں عورتوں سے (تمسخر کریں) ممکن ہے کہ وہ ان سے اچھی ہوں۔ اور اپنے (مومن بھائی) کو عیب نہ لگاؤ اور نہ ایک دوسرے کا برا نام رکھو۔ ایمان لانے کے بعد برا نام (رکھنا) گناہ ہے۔ اور جو توبہ نہ کریں وہ ظالم ہیں', NULL, NULL, 'e96391f4e73513dd0388f35021b749f93952da76e7bcbb8ea361dc03799c70cf'),
  ('ur.jalandhry', 49, 12, 4624, 'اے اہل ایمان! بہت گمان کرنے سے احتراز کرو کہ بعض گمان گناہ ہیں۔ اور ایک دوسرے کے حال کا تجسس نہ کیا کرو اور نہ کوئی کسی کی غیبت کرے۔ کیا تم میں سے کوئی اس بات کو پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے؟ اس سے تو تم ضرور نفرت کرو گے۔ (تو غیبت نہ کرو) اور خدا کا ڈر رکھو بےشک خدا توبہ قبول کرنے والا مہربان ہے', NULL, NULL, 'f9c9bc380a5f253fa679a7af93e29b5618f46430ae8a77aa7af5bbdd8cd6f00e'),
  ('ur.jalandhry', 49, 13, 4625, 'لوگو! ہم نے تم کو ایک مرد اور ایک عورت سے پیدا کیا اور تمہاری قومیں اور قبیلے بنائے۔ تاکہ ایک دوسرے کو شناخت کرو۔ اور خدا کے نزدیک تم میں زیادہ عزت والا وہ ہے جو زیادہ پرہیزگار ہے۔ بےشک خدا سب کچھ جاننے والا (اور) سب سے خبردار ہے', NULL, NULL, '793f8d328001afbc742275ae5af4ecf3a5ec6625307658d87c45a52ac4cdc6f1'),
  ('ur.jalandhry', 49, 14, 4626, 'دیہاتی کہتے ہیں کہ ہم ایمان لے آئے۔ کہہ دو کہ تم ایمان نہیں لائے (بلکہ یوں) کہو کہ ہم اسلام لائے ہیں اور ایمان تو ہنوز تمہارے دلوں میں داخل ہی نہیں ہوا۔ اور تم خدا اور اس کے رسول کی فرمانبرداری کرو گے تو خدا تمہارے اعمال سے کچھ کم نہیں کرے گا۔ بےشک خدا بخشنے والا مہربان ہے', NULL, NULL, '7ae14f76b41cb2a587d1c9663c6fe414172a1f0559f024dd0a9e9eb16d535eac'),
  ('ur.jalandhry', 49, 15, 4627, 'مومن تو وہ ہیں جو خدا اور اس کے رسول پر ایمان لائے پھر شک میں نہ پڑے اور خدا کی راہ میں مال اور جان سے لڑے۔ یہی لوگ (ایمان کے) سچے ہیں', NULL, NULL, 'cef6c2110a833caca82239f81aecb729863d84d1432ed3d068f0a123f73c38cf'),
  ('ur.jalandhry', 49, 16, 4628, 'ان سے کہو کیا تم خدا کو اپنی دینداری جتلاتے ہو۔ اور خدا تو آسمانوں اور زمین کی سب چیزوں سے واقف ہے۔ اور خدا ہر شے کو جانتا ہے', NULL, NULL, '32abb2c5c2221a091068e3c0dc95473142b612f3f4188b0aa02866280a35e493'),
  ('ur.jalandhry', 49, 17, 4629, 'یہ لوگ تم پر احسان رکھتے ہیں کہ مسلمان ہوگئے ہیں۔ کہہ دو کہ اپنے مسلمان ہونے کا مجھ پر احسان نہ رکھو۔ بلکہ خدا تم پر احسان رکھتا ہے کہ اس نے تمہیں ایمان کا رستہ دکھایا بشرطیکہ تم سچے (مسلمان) ہو', NULL, NULL, 'ede1907c45efb101119515ac390ad6c1ee3a5622b08d3849919fa381a9a7428f'),
  ('ur.jalandhry', 49, 18, 4630, 'بےشک خدا آسمانوں اور زمین کی پوشیدہ باتوں کو جانتا ہے اور جو کچھ تم کرتے ہو اسے دیکھتا ہے', NULL, NULL, '3464c76c0f14155423366022f500970036066486cae32896074162395dda92f3'),
  ('ur.jalandhry', 50, 1, 4631, 'قٓ۔ قرآن مجید کی قسم (کہ محمد پیغمبر خدا ہیں)', NULL, NULL, '5222aa2a7ca9b7ac6220dd39b6b4a97454bb900d8c1b42805e419c529cd2f442'),
  ('ur.jalandhry', 50, 2, 4632, 'لیکن ان لوگوں نے تعجب کیا کہ انہی میں سے ایک ہدایت کرنے والا ان کے پاس آیا تو کافر کہنے لگے کہ یہ بات تو (بڑی) عجیب ہے', NULL, NULL, 'ed79e7e05bd7c9b47082b435dcaea6f4056e158a3f9ce6d6464a08da21387fff'),
  ('ur.jalandhry', 50, 3, 4633, 'بھلا جب ہم مر گئے اور مٹی ہوگئے (تو پھر زندہ ہوں گے؟) یہ زندہ ہونا (عقل سے) بعید ہے', NULL, NULL, 'd8a52cbaf4e6db22ea2ef355bcad56df95abd63b88753eae914aea3275d6ca67'),
  ('ur.jalandhry', 50, 4, 4634, 'ان کے جسموں کو زمین جتنا (کھا کھا کر) کم کرتی جاتی ہے ہمیں معلوم ہے۔ اور ہمارے پاس تحریری یادداشت بھی ہے', NULL, NULL, '7fce4f69bdd701a655bc5dce9bd7eb23c2bf59d5773373c3d6d577aa0044a1da'),
  ('ur.jalandhry', 50, 5, 4635, 'بلکہ (عجیب بات یہ ہے کہ) جب ان کے پاس (دین) حق آ پہنچا تو انہوں نے اس کو جھوٹ سمجھا سو یہ ایک الجھی ہوئی بات میں (پڑ رہے) ہیں', NULL, NULL, 'a324311653f0863b03092412dd1464b57c716e6018b11f19c605c949aeb7889f'),
  ('ur.jalandhry', 50, 6, 4636, 'کیا انہوں نے اپنے اوپر آسمان کی طرف نگاہ نہیں کی کہ ہم نے اس کو کیونکر بنایا اور (کیونکر) سجایا اور اس میں کہیں شگاف تک نہیں', NULL, NULL, '9ef7c38f0e5eaf0aeef9cb5a497228dd59191397c1bb39296daa36196fee5e12'),
  ('ur.jalandhry', 50, 7, 4637, 'اور زمین کو (دیکھو اسے) ہم نے پھیلایا اور اس میں پہاڑ رکھ دیئے اور اس میں ہر طرح کی خوشنما چیزیں اُگائیں', NULL, NULL, 'd66cac4718e26aff6785d0199954bc672c0eac409bfe535b2955ac61c9c5d348'),
  ('ur.jalandhry', 50, 8, 4638, 'تاکہ رجوع لانے والے بندے ہدایت اور نصیحت حاصل کریں', NULL, NULL, '2bbd767deb7aa56114c3db81a5504de0f1fe53f5aeb0181e88f3ffacdca27a5d'),
  ('ur.jalandhry', 50, 9, 4639, 'اور آسمان سے برکت والا پانی اُتارا اور اس سے باغ وبستان اُگائے اور کھیتی کا اناج', NULL, NULL, '99bdab60ddd5294012a7762610f07b79d6175f9c72539642b453886bfec7eff3'),
  ('ur.jalandhry', 50, 10, 4640, 'اور لمبی لمبی کھجوریں جن کا گابھا تہہ بہ تہہ ہوتا ہے', NULL, NULL, 'eee278139ce4fb7af1b84c710c6552d9d4e6b25782909c4880518444c1768fad'),
  ('ur.jalandhry', 50, 11, 4641, '(یہ سب کچھ) بندوں کو روزی دینے کے لئے (کیا ہے) اور اس (پانی) سے ہم نے شہر مردہ (یعنی زمین افتادہ) کو زندہ کیا۔ (بس) اسی طرح (قیامت کے روز) نکل پڑنا ہے', NULL, NULL, 'd82997dd71976ea828010d875c75a07533f8cd4e7c5a486bbfce3512c7e70fe3'),
  ('ur.jalandhry', 50, 12, 4642, 'ان سے پہلے نوح کی قوم اور کنوئیں والے اور ثمود جھٹلا چکے ہیں', NULL, NULL, '9ee4284137e3067336d6783521b6da4e5a8eb744a9e5540b7c2ec0821bc70f8c'),
  ('ur.jalandhry', 50, 13, 4643, 'اور عاد اور فرعون اور لوط کے بھائی', NULL, NULL, '4a9c2af7ec5d9493581a40e6ee8709c0e11527dea8f64342bb25128adbfc5188'),
  ('ur.jalandhry', 50, 14, 4644, 'اور بن کے رہنے والے اور تُبّع کی قوم۔ (غرض) ان سب نے پیغمبروں کو جھٹلایا تو ہمارا وعید (عذاب) بھی پورا ہو کر رہا', NULL, NULL, 'd68476c526e04ff55da0fc131e94faa67624e493524795dc37ac858580d542db'),
  ('ur.jalandhry', 50, 15, 4645, 'کیا ہم پہلی بار پیدا کرکے تھک گئے ہیں؟ (نہیں) بلکہ یہ ازسرنو پیدا کرنے میں شک میں (پڑے ہوئے) ہیں', NULL, NULL, '0d6e4eea1c0ac85af2cc7ca40854794a2831f507bf8af624b354b344aed2bda9'),
  ('ur.jalandhry', 50, 16, 4646, 'اور ہم ہی نے انسان کو پیدا کیا ہے اور جو خیالات اس کے دل میں گزرتے ہیں ہم ان کو جانتے ہیں۔ اور ہم اس کی رگ جان سے بھی اس سے زیادہ قریب ہیں', NULL, NULL, 'c738132211eb5bc906799ee246b4ecfe419bdb62cf4d2450de2dee035c7b37e2'),
  ('ur.jalandhry', 50, 17, 4647, 'جب (وہ کوئی کام کرتا ہے تو) دو لکھنے والے جو دائیں بائیں بیٹھے ہیں، لکھ لیتے ہیں', NULL, NULL, 'fcfe8dad778d2a379eef72d92d941eaa7c13dba85990ac8d1be5a064cc5596f5'),
  ('ur.jalandhry', 50, 18, 4648, 'کوئی بات اس کی زبان پر نہیں آتی مگر ایک نگہبان اس کے پاس تیار رہتا ہے', NULL, NULL, '08e212b8f4703abdda79596caa96483ff76e686731dadb02f4e81c3271a8aa7a'),
  ('ur.jalandhry', 50, 19, 4649, 'اور موت کی بےہوشی حقیقت کھولنے کو طاری ہوگئی۔ (اے انسان) یہی (وہ حالت) ہے جس سے تو بھاگتا تھا', NULL, NULL, '51d3a37f3c7e5887ea7b49952d77de9981d57db5db9f94a8a740e745ba5cb4b4'),
  ('ur.jalandhry', 50, 20, 4650, 'اور صور پھونکا جائے گا۔ یہی (عذاب کے) وعید کا دن ہے', NULL, NULL, 'b8caa8738e6512d7876db1e20e7e3971ee718efb3ce81d6e532b1a6474eebc36'),
  ('ur.jalandhry', 50, 21, 4651, 'اور ہر شخص (ہمارے سامنے) آئے گا۔ ایک (فرشتہ) اس کے ساتھ چلانے والا ہوگا اور ایک (اس کے عملوں کی) گواہی دینے والا', NULL, NULL, 'fb9604619354dc0940937c5d447e1c9a930534beafb0b1d50115600cce03a056'),
  ('ur.jalandhry', 50, 22, 4652, '(یہ وہ دن ہے کہ) اس سے تو غافل ہو رہا تھا۔ اب ہم نے تجھ پر سے پردہ اُٹھا دیا۔ تو آج تیری نگاہ تیز ہے', NULL, NULL, '3e728afcc3b0c92f2e1de5140f30f91f062ff26d8217aae225d79fb24f6355bc'),
  ('ur.jalandhry', 50, 23, 4653, 'اور اس کا ہم نشین (فرشتہ) کہے گا کہ یہ (اعمال نامہ) میرے پاس حاضر ہے', NULL, NULL, 'bf76dff6a2f2ff710e102544b2305589a3292eafaa288967c77afef824c00506'),
  ('ur.jalandhry', 50, 24, 4654, '(حکم ہوگا کہ) ہر سرکش ناشکرے کو دوزخ میں ڈال دو', NULL, NULL, 'ed464df7ec173415acc2a7bdbf6b6ae3ec8741c8fc665d001b4df4b34ecf8424'),
  ('ur.jalandhry', 50, 25, 4655, 'جو مال میں بخل کرنے والا حد سے بڑھنے والا شبہے نکالنے والا تھا', NULL, NULL, '0e13cba5ace6c06b051a067bfc988d74a3ac767d044c6d46dbfcbf5e8678b2e2'),
  ('ur.jalandhry', 50, 26, 4656, 'جس نے خدا کے ساتھ اور معبود مقرر کر رکھے تھے۔ تو اس کو سخت عذاب میں ڈال دو', NULL, NULL, '15bd9cf6b03782779618eacdfb96133711912592d95a582ec155a82aebf68c19'),
  ('ur.jalandhry', 50, 27, 4657, 'اس کا ساتھی (شیطان) کہے گا کہ اے ہمارے پروردگار میں نے اس کو گمراہ نہیں کیا تھا بلکہ یہ آپ ہی رستے سے دور بھٹکا ہوا تھا', NULL, NULL, '2c7028054f4efaf903f5976a4092e85859c96beecdd8270e2a7676f29debb129'),
  ('ur.jalandhry', 50, 28, 4658, '(خدا) فرمائے گا کہ ہمارے حضور میں ردوکد نہ کرو۔ ہم تمہارے پاس پہلے ہی (عذاب کی) وعید بھیج چکے تھے', NULL, NULL, '4ef6b6de23eefa97358522f791833eb6ff83d163c4aa4f0910d137cdfd77056c'),
  ('ur.jalandhry', 50, 29, 4659, 'ہمارے ہاں بات بدلا نہیں کرتی اور ہم بندوں پر ظلم نہیں کیا کرتے', NULL, NULL, '1353c06b4a1cef4f0b9130f9b7920beb671a0e33c9470730b6f001aaa9e03dc5'),
  ('ur.jalandhry', 50, 30, 4660, 'اس دن ہم دوزخ سے پوچھیں گے کہ کیا تو بھر گئی؟ وہ کہے گی کہ کچھ اور بھی ہے؟', NULL, NULL, '6c3e6ad8c0196f731eccd5f2966e676a51be3c714e41c3b4098e51ed60edaed9'),
  ('ur.jalandhry', 50, 31, 4661, 'اور بہشت پرہیزگاروں کے قریب کردی جائے گی (کہ مطلق) دور نہ ہوگی', NULL, NULL, '67e6a9277ddc1cf0b6ad8da4b875d28340471471a3fed4eec29c98ef589ecfc8'),
  ('ur.jalandhry', 50, 32, 4662, 'یہی وہ چیز ہے جس کا تم سے وعدہ کیا جاتا تھا (یعنی) ہر رجوع لانے والے حفاظت کرنے والے سے', NULL, NULL, 'abad0db7f85ae6adcb83407406e198f4488e51ca3dbdf8f0c7d97aedadc8f135'),
  ('ur.jalandhry', 50, 33, 4663, 'جو خدا سے بن دیکھے ڈرتا ہے اور رجوع لانے والا دل لے کر آیا', NULL, NULL, 'bdb6c64a5e53ba4bc85818189b4a200795be92d32a88782758934fdc52d371c6'),
  ('ur.jalandhry', 50, 34, 4664, 'اس میں سلامتی کے ساتھ داخل ہوجاؤ۔ یہ ہمیشہ رہنے کا دن ہے', NULL, NULL, '37a9cac804be94e0cd5934be6bdfbb26362d25da033de337204fb5554c5f640f'),
  ('ur.jalandhry', 50, 35, 4665, 'وہاں وہ جو چاہیں گے ان کے لئے حاضر ہے اور ہمارے ہاں اور بھی (بہت کچھ) ہے', NULL, NULL, '6f63ba25bfe3251e053100f279f819754456347f864ff7dd12571267d2a235f1'),
  ('ur.jalandhry', 50, 36, 4666, 'اور ہم نے ان سے پہلے کئی اُمتیں ہلاک کر ڈالیں۔ وہ ان سے قوت میں کہیں بڑھ کر تھے وہ شہروں میں گشت کرنے لگے۔ کیا کہیں بھاگنے کی جگہ ہے؟', NULL, NULL, '6e225470e11a380ad6b657a84c087013ee437c161f309f13b3acdbef1ca3358b'),
  ('ur.jalandhry', 50, 37, 4667, 'جو شخص دل (آگاہ) رکھتا ہے یا دل سے متوجہ ہو کر سنتا ہے اس کے لئے اس میں نصیحت ہے', NULL, NULL, '7cf0c0ba642ecbab30484bf1983d32fc2fdc16e3c1a279c1af46a84772782372'),
  ('ur.jalandhry', 50, 38, 4668, 'اور ہم نے آسمانوں اور زمین کو اور جو (مخلوقات) ان میں ہے سب کو چھ دن میں بنا دیا۔ اور ہم کو ذرا تکان نہیں ہوئی', NULL, NULL, 'dcfb593043af90986988634fd7d12d42ce275594c55655aaa5f8bc5e50ef49e7'),
  ('ur.jalandhry', 50, 39, 4669, 'تو جو کچھ یہ (کفار) بکتے ہیں اس پر صبر کرو اور آفتاب کے طلوع ہونے سے پہلے اور اس کے غروب ہونے سے پہلے اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے رہو', NULL, NULL, '0ff2c8f529561129eff5a1542e795617aa7de9979d2b182f9a5e035e65680b40'),
  ('ur.jalandhry', 50, 40, 4670, 'اور رات کے بعض اوقات میں بھی اور نماز کے بعد بھی اس (کے نام) کی تنزیہ کیا کرو', NULL, NULL, 'baf557915c628d13a8fc81481227d78390bac1c6c514c20604ca434181192dd6'),
  ('ur.jalandhry', 50, 41, 4671, 'اور سنو جس دن پکارنے والا نزدیک کی جگہ سے پکارے گا', NULL, NULL, 'cbb374c802beac4f3299f8d622b7456df7458bcb8424b4cdea1a2c3c8a0600f1'),
  ('ur.jalandhry', 50, 42, 4672, 'جس دن لوگ چیخ یقیناً سن لیں گے۔ وہی نکل پڑنے کا دن ہے', NULL, NULL, 'bc6d3145a6511a587ecfb6aa230c06e119ee356aa9ef51faa976d22b7e844c20'),
  ('ur.jalandhry', 50, 43, 4673, 'ہم ہی تو زندہ کرتے ہیں اور ہم ہی مارتے ہیں اور ہمارے ہی پاس لوٹ کر آنا ہے', NULL, NULL, '26fe8aa72b98fa222629bb4374e05cda973376d062ecd46119cad3c85ba64b70'),
  ('ur.jalandhry', 50, 44, 4674, 'اس دن زمین ان پر سے پھٹ جائے گی اور وہ جھٹ پٹ نکل کھڑے ہوں گے۔ یہ جمع کرنا ہمیں آسان ہے', NULL, NULL, '93efc9b4b8beb7373cb9c0a43a932bd1d99c6423713990a25164c9d03e67fab4'),
  ('ur.jalandhry', 50, 45, 4675, 'یہ لوگ جو کچھ کہتے ہیں ہمیں خوب معلوم ہے اور تم ان پر زبردستی کرنے والے نہیں ہو۔ پس جو ہمارے (عذاب کی) وعید سے ڈرے اس کو قرآن سے نصیحت کرتے رہو', NULL, NULL, 'cb9df4285458077fd2bcab300d0007d84476bee0ba8102e2a84eb4c3ecce8f57'),
  ('ur.jalandhry', 51, 1, 4676, 'بکھیرنے والیوں کی قسم جو اُڑا کر بکھیر دیتی ہیں', NULL, NULL, '9b2b0b32865e9cb89065b411f750110014a24500d385e9c39d1b1a2f5bb51cb3'),
  ('ur.jalandhry', 51, 2, 4677, 'پھر (پانی کا) بوجھ اٹھاتی ہیں', NULL, NULL, '06565d0d58e9569f3aa76bdfc61b15f3fc1891c8982b427c1910e5ed10bc01a6'),
  ('ur.jalandhry', 51, 3, 4678, 'پھر آہستہ آہستہ چلتی ہیں', NULL, NULL, 'df96e1d9120c736f4845c7f5ef8ea246a7d4fefdf9f97b8d6afd3bb0d726877e'),
  ('ur.jalandhry', 51, 4, 4679, 'پھر چیزیں تقسیم کرتی ہیں', NULL, NULL, '097d09484235c5ebd94c1b8c38d01970a1a855a85c956e6f6ee36391e3615b20'),
  ('ur.jalandhry', 51, 5, 4680, 'کہ جس چیز کا تم سے وعدہ کیا جاتا ہے وہ سچا ہے', NULL, NULL, '20ec584ba7caa57585e07c867c272a2840418feeca2497507d735d337f16bbaa'),
  ('ur.jalandhry', 51, 6, 4681, 'اور انصاف (کا دن) ضرور واقع ہوگا', NULL, NULL, 'd83462dd115e651f1779324c6ae8a569f3eb472c4de7d78e1411849f241c5d7f'),
  ('ur.jalandhry', 51, 7, 4682, 'اور آسمان کی قسم جس میں رسے ہیں', NULL, NULL, '5c4c488a5fc6031c95555709d60ba1eff2da978c99b2ceee0dde0e1c9763c081'),
  ('ur.jalandhry', 51, 8, 4683, 'کہ (اے اہل مکہ) تم ایک متناقض بات میں (پڑے ہوئے) ہو', NULL, NULL, 'a2eadbbd2dd9d50bd374efd1753acecc70d46e860fb075be71f1ebcbcfcd0488'),
  ('ur.jalandhry', 51, 9, 4684, 'اس سے وہی پھرتا ہے جو (خدا کی طرف سے) پھیرا جائے', NULL, NULL, '29771b0aab930ca44cdc48a5926a319c34a194e5695ec456601c84697ebf6409'),
  ('ur.jalandhry', 51, 10, 4685, 'اٹکل دوڑانے والے ہلاک ہوں', NULL, NULL, '68d92ba66bbe763374d647b47593ea9b21c2b16df2890c9a094d82093b980d3f'),
  ('ur.jalandhry', 51, 11, 4686, 'جو بےخبری میں بھولے ہوئے ہیں', NULL, NULL, '2a243be11ad5734f7667732a0e87c1d8c7b9abc5d26fdf1c29461b9b8fdc327c'),
  ('ur.jalandhry', 51, 12, 4687, 'پوچھتے ہیں کہ جزا کا دن کب ہوگا؟', NULL, NULL, '8be887acd13c77848ec0df3e079f3d997a352c85054f71d249e1e28ea2909089'),
  ('ur.jalandhry', 51, 13, 4688, 'اُس دن (ہوگا) جب ان کو آگ میں عذاب دیا جائے گا', NULL, NULL, '8a316e0bf902217e7df1b12b790977d52820bec12008e12069cef477277bfbf2'),
  ('ur.jalandhry', 51, 14, 4689, 'اب اپنی شرارت کا مزہ چکھو۔ یہ وہی ہے جس کے لئے تم جلدی مچایا کرتے تھے', NULL, NULL, '2396604126953a9e0e36c54c5dda2341382d676832683c6e7829249c10b35651'),
  ('ur.jalandhry', 51, 15, 4690, 'بےشک پرہیزگار بہشتوں اور چشموں میں (عیش کر رہے) ہوں گے', NULL, NULL, 'b38efd6b0cb123df04e106ee301e517b292385512bd0f0f7264a37c7edfb3fd7'),
  ('ur.jalandhry', 51, 16, 4691, 'اور) جو جو (نعمتیں) ان کا پروردگار انہیں دیتا ہوگا ان کو لے رہے ہوں گے۔ بےشک وہ اس سے پہلے نیکیاں کرتے تھے', NULL, NULL, '6ce3729634155ec9966bf54907a493ac00de2dbb893c492108ef52308e97b9bc'),
  ('ur.jalandhry', 51, 17, 4692, 'رات کے تھوڑے سے حصے میں سوتے تھے', NULL, NULL, '14dcbbf98bc6ba96d93ec61a68175be11f62a416b2b85912242ed8c06b724bc8'),
  ('ur.jalandhry', 51, 18, 4693, 'اور اوقات سحر میں بخشش مانگا کرتے تھے', NULL, NULL, '90c6f98d2e0791289651c82a2c1756bc31d940cf8b651a2d2777e968108dbf3a'),
  ('ur.jalandhry', 51, 19, 4694, 'اور ان کے مال میں مانگنے والے اور نہ مانگنے والے (دونوں) کا حق ہوتا تھا', NULL, NULL, '1c5455732a52ec6089d9c317f6af2593a6a278e7eedd90ba153be47e127b94f4'),
  ('ur.jalandhry', 51, 20, 4695, 'اور یقین کرنے والوں کے لئے زمین میں (بہت سی) نشانیاں ہیں', NULL, NULL, '0ccc1c535b27da8606b45a9b560ba134b535de7860ca076938e709339927c64b'),
  ('ur.jalandhry', 51, 21, 4696, 'اور خود تمہارے نفوس میں تو کیا تم دیکھتے نہیں؟', NULL, NULL, '275ff29afff4db927560396c6d062536f447112cd53867d0a3665cfbcc13743a'),
  ('ur.jalandhry', 51, 22, 4697, 'اور تمہارا رزق اور جس چیز کا تم سے وعدہ کیا جاتا ہے آسمان میں ہے', NULL, NULL, '077c700503b1fdead026901e490d67d932c48fdde32c99e1c60fe9aaf57a8db9'),
  ('ur.jalandhry', 51, 23, 4698, 'تو آسمانوں اور زمین کے مالک کی قسم! یہ (اسی طرح) قابل یقین ہے جس طرح تم بات کرتے ہو', NULL, NULL, '374feadbfc14de086186522d898438adf05d6d37774e9dfbdc66127242be3ad8'),
  ('ur.jalandhry', 51, 24, 4699, 'بھلا تمہارے پاس ابراہیمؑ کے معزز مہمانوں کی خبر پہنچی ہے؟', NULL, NULL, 'ff20b8f4508cac36b128510f755e6b7e9f0fd7eb2074fa49fdadf9d917f4e49b'),
  ('ur.jalandhry', 51, 25, 4700, 'جب وہ ان کے پاس آئے تو سلام کہا۔ انہوں نے بھی (جواب میں) سلام کہا (دیکھا تو) ایسے لوگ کہ نہ جان نہ پہچان', NULL, NULL, '5870f81b585e130d79d286aefebaa99c3798983c8933da0137a6eb86b1586791')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
