INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 51, 26, 4701, 'تو اپنے گھر جا کر ایک (بھنا ہوا) موٹا بچھڑا لائے', NULL, NULL, 'a688d65aea0570ce5014967cde8398366860cdf97c7a124a03b934fbfd7f99d5'),
  ('ur.jalandhry', 51, 27, 4702, '(اور کھانے کے لئے) ان کے آگے رکھ دیا۔ کہنے لگے کہ آپ تناول کیوں نہیں کرتے؟', NULL, NULL, 'b860195d6c1db530f5775e9f0faa7ea30f7933997577f8623e408552b46783e9'),
  ('ur.jalandhry', 51, 28, 4703, 'اور دل میں ان سے خوف معلوم کیا۔ (انہوں نے) کہا کہ خوف نہ کیجیئے۔ اور ان کو ایک دانشمند لڑکے کی بشارت بھی سنائی', NULL, NULL, '3e0142cf1f5f6b27b109b89ec925b6eb2be3e5fac2ffbe8766a6e015e5667909'),
  ('ur.jalandhry', 51, 29, 4704, 'تو ابراہیمؑ کی بیوی چلاّتی آئی اور اپنا منہ پیٹ کر کہنے لگی کہ (اے ہے ایک تو) بڑھیا اور (دوسرے) بانجھ', NULL, NULL, 'e2b8672a2e1f6ed0810724886fb255999cded37889637e630e6de23f31bc5570'),
  ('ur.jalandhry', 51, 30, 4705, '(انہوں نے) کہا (ہاں) تمہارے پروردگار نے یوں ہی فرمایا ہے۔ وہ بےشک صاحبِ حکمت (اور) خبردار ہے', NULL, NULL, 'aaa6326a8701cea9b9d1a9d1a515727b70b54c12f56051d92771d563a09062ba'),
  ('ur.jalandhry', 51, 31, 4706, 'ابراہیمؑ نے کہا کہ فرشتو! تمہارا مدعا کیا ہے؟', NULL, NULL, '2022780713e0af13c0a3271324d17d00f3cfb75bbaa116d513adfd4079c4dc9a'),
  ('ur.jalandhry', 51, 32, 4707, 'انہوں نے کہا کہ ہم گنہگار لوگوں کی طرف بھیجے گئے ہیں', NULL, NULL, '725eaf82ed3a0792abf1c18e6803f2e0b3741b7bd3081c26e6569a79d245edfc'),
  ('ur.jalandhry', 51, 33, 4708, 'تاکہ ان پر کھنگر برسائیں', NULL, NULL, '7fcde4e9ce90a7028101c35747b0eab6fe9a59ea8641f0f1a3a7d83167954224'),
  ('ur.jalandhry', 51, 34, 4709, 'جن پر حد سے بڑھ جانے والوں کے لئے تمہارے پروردگار کے ہاں سے نشان کردیئے گئے ہیں', NULL, NULL, 'c38c91591b87fc50d0b07477b939fb44d9d9bbaa308ca53e30ad63cfcc0b3d13'),
  ('ur.jalandhry', 51, 35, 4710, 'تو وہاں جتنے مومن تھے ان کو ہم نے نکال لیا', NULL, NULL, '546ee72494bf974d5fff425ffe0a73b1eb6386bce89e2398fb0a1e976c906d91'),
  ('ur.jalandhry', 51, 36, 4711, 'اور اس میں ایک گھر کے سوا مسلمانوں کا کوئی گھر نہ پایا', NULL, NULL, '6c0607901f19009d76456f054b2de80ea8f4dc518de9ff0c8ad087aecf0630c2'),
