  ('ur.jalandhry', 52, 37, 4772, 'کیا ان کے پاس تمہارے پروردگار کے خزانے ہیں۔ یا یہ (کہیں کے) داروغہ ہیں؟', NULL, NULL, '77bd0d3372e91e30abbed5466de9ce400fa4f02117b4562d37f83962b9c7d61a'),
  ('ur.jalandhry', 52, 38, 4773, 'یا ان کے پاس کوئی سیڑھی ہے جس پر (چڑھ کر آسمان سے باتیں) سن آتے ہیں۔ تو جو سن آتا ہے وہ صریح سند دکھائے', NULL, NULL, '121f35c7c33ef19b546160607ea74e20565c9563589d29b896454e8b3658bd5e'),
  ('ur.jalandhry', 52, 39, 4774, 'کیا خدا کی تو بیٹیاں اور تمہارے بیٹے', NULL, NULL, '989632d1a3aa9ba5688d33e0b19d353ac2afff4f9c13698b21b7167b372c53d7'),
  ('ur.jalandhry', 52, 40, 4775, '(اے پیغمبر) کیا تم ان سے صلہ مانگتے ہو کہ ان پر تاوان کا بوجھ پڑ رہا ہے', NULL, NULL, '26e3a60627b2be1f3a3ea8fecc26c54fa5af2ad0ee79d09a3f89c7cf2dcb76a5'),
  ('ur.jalandhry', 52, 41, 4776, 'یا ان کے پاس غیب (کا علم) ہے کہ وہ اسے لکھ لیتے ہیں', NULL, NULL, '6c1cea446deb5e85a644077251e7320d98f63d2f2748f31cd3929cbb1b4f4a1a'),
  ('ur.jalandhry', 52, 42, 4777, 'کیا یہ کوئی داؤں کرنا چاہتے ہیں تو کافر تو خود داؤں میں آنے والے ہیں', NULL, NULL, '99c3cca550a82f3330b472d45c435c0c28f0886976d4876e5a6644440b97386e'),
  ('ur.jalandhry', 52, 43, 4778, 'کیا خدا کے سوا ان کا کوئی اور معبود ہے؟ خدا ان کے شریک بنانے سے پاک ہے', NULL, NULL, '1e62e1cc7aa8ab4830d683b912831b94c85cc4aeb9687e1ead78dd10b16f5be6'),
  ('ur.jalandhry', 52, 44, 4779, 'اور اگر یہ آسمان سے (عذاب) کا کوئی ٹکڑا گرتا ہوا دیکھیں تو کہیں کہ یہ گاڑھا بادل ہے', NULL, NULL, 'fcd510055a68ba4d85e66185b5c81bdb0944b362a890f3c09a6652ee847bfe29'),
  ('ur.jalandhry', 52, 45, 4780, 'پس ان کو چھوڑ دو یہاں تک کہ وہ روز جس میں وہ بےہوش کردیئے جائیں گے، سامنے آجائے', NULL, NULL, '7e68d4f4c8cbd1a00a48edd40fcf43973c1cdf2b78e8d87c8f056b2a295c772b'),
  ('ur.jalandhry', 52, 46, 4781, 'جس دن ان کا کوئی داؤں کچھ بھی کام نہ آئے اور نہ ان کو (کہیں سے) مدد ہی ملے', NULL, NULL, 'c89bcbe15c90a01867abc3bb4b13be0c3b4fd7b3a243c4e14a2c4e02d6b4e512'),
  ('ur.jalandhry', 52, 47, 4782, 'اور ظالموں کے لئے اس کے سوا اور عذاب بھی ہے لیکن ان میں کے اکثر نہیں جانتے', NULL, NULL, '84727b16dc9e1a03751102a9be659f15b028c4cbd0e11b3e76db5375e080f7b1'),
  ('ur.jalandhry', 52, 48, 4783, 'اور تم اپنے پروردگار کے حکم کے انتظار میں صبر کئے رہو۔ تم تو ہماری آنکھوں کے سامنے ہو اور جب اُٹھا کرو تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کیا کرو', NULL, NULL, '0bfd67c07b48ad3f4464b496b7c3d5fc3a094548818c9c7fe916471337a7be0e'),
  ('ur.jalandhry', 52, 49, 4784, 'اور رات کے بعض اوقات میں بھی اور ستاروں کے غروب ہونے کے بعد بھی اس کی تنزیہ کیا کرو', NULL, NULL, 'a186b16943192c3239657421e7aab8dfc65ef50015b8d59aa7d8ac7aeaf81b06'),
  ('ur.jalandhry', 53, 1, 4785, 'تارے کی قسم جب غائب ہونے لگے', NULL, NULL, '958dddad1574d4159f5a5d45cb0008e534a17de7ef165facc9438df9cdacd1a8'),
  ('ur.jalandhry', 53, 2, 4786, 'کہ تمہارے رفیق (محمدﷺ) نہ رستہ بھولے ہیں نہ بھٹکے ہیں', NULL, NULL, '6f14e1db44821a0124c9b9556b2f06f9837c3e6cb14bb70f77ca1410b036222e'),
  ('ur.jalandhry', 53, 3, 4787, 'اور نہ خواہش نفس سے منہ سے بات نکالتے ہیں', NULL, NULL, 'f6ec4c4a2ef382153026f895794ede3fc53ef87bd6aab4e346ee804da19f66b4'),
  ('ur.jalandhry', 53, 4, 4788, 'یہ (قرآن) تو حکم خدا ہے جو (ان کی طرف) بھیجا جاتا ہے', NULL, NULL, '687a988327260041beb62974b2b6ed02aa35fa6bb8bca8159f254dfbb48b4df8'),
  ('ur.jalandhry', 53, 5, 4789, 'ان کو نہایت قوت والے نے سکھایا', NULL, NULL, '5b90732ec4fc6399437370eb22d2810b13a97dc84f747bd8aec3afbb4db0a3c5'),
  ('ur.jalandhry', 53, 6, 4790, '(یعنی جبرائیل) طاقتور نے پھر وہ پورے نظر آئے', NULL, NULL, '4707430ef0fa12a64150f73e90da54d57c91aea8b627cb77a63c8c08594d5386'),
  ('ur.jalandhry', 53, 7, 4791, 'اور وہ (آسمان کے) اونچے کنارے میں تھے', NULL, NULL, 'f690fd51c490ac80f58b61b142b2bdd59003ccab244aa41abefd04d7b4b6d0e4'),
  ('ur.jalandhry', 53, 8, 4792, 'پھر قریب ہوئے اوراَور آگے بڑھے', NULL, NULL, '010065304e978cec019cd987c6f3cb54f30f3e0690b7bed6b2f7eea7ba85a200'),
  ('ur.jalandhry', 53, 9, 4793, 'تو دو کمان کے فاصلے پر یا اس سے بھی کم', NULL, NULL, 'aa2169effc3038b372c3d7d81e0627da38c3279d58e0f0cd9879a0b208cccc33'),
  ('ur.jalandhry', 53, 10, 4794, 'پھر خدا نے اپنے بندے کی طرف جو بھیجا سو بھیجا', NULL, NULL, '20b2a3d9eb20e4428583582f760e4a9dc886885713cab73336279c45374a13b1'),
  ('ur.jalandhry', 53, 11, 4795, 'جو کچھ انہوں نے دیکھا ان کے دل نے اس کو جھوٹ نہ مانا', NULL, NULL, 'd548c8be1a4cf04dd9c59491aa22e8821ebc92b3251e0a9964a47b6b5f1c9b3d'),
  ('ur.jalandhry', 53, 12, 4796, 'کیا جو کچھ وہ دیکھتے ہیں تم اس میں ان سے جھگڑتے ہو؟', NULL, NULL, '714ceb1296224ac007a91aabfba1c9944fe8d0bdd371d3db924d3543e2561834'),
  ('ur.jalandhry', 53, 13, 4797, 'اور انہوں نے اس کو ایک بار بھی دیکھا ہے', NULL, NULL, 'd52508e49d8acb111d1a0ae8e2145803425f5dd163acf1a5e261cc1efefb0ffb'),
  ('ur.jalandhry', 53, 14, 4798, 'پرلی حد کی بیری کے پاس', NULL, NULL, 'd4c0528d0448e30c77bf494fffc3d14b00c576e2d7f4335859c260e131098f09'),
  ('ur.jalandhry', 53, 15, 4799, 'اسی کے پاس رہنے کی جنت ہے', NULL, NULL, '0088c5e0a98c4ff6b18ea5fac0bb0f473b4863b62bede78234e6f9996ec58129'),
  ('ur.jalandhry', 53, 16, 4800, 'جب کہ اس بیری پر چھا رہا تھا جو چھا رہا تھا', NULL, NULL, 'e507aa191481f056910f6e48e591f719f835b1b3003ed0a3b9491371fb1226b8')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
