INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 53, 17, 4801, 'ان کی آنکھ نہ تو اور طرف مائل ہوئی اور نہ (حد سے) آگے بڑھی', NULL, NULL, 'df658668e816cee0c84d71c53b3b6158c6a945bc7922621ee95cbe148e3277a0'),
  ('ur.jalandhry', 53, 18, 4802, 'انہوں نے اپنے پروردگار (کی قدرت) کی کتنی ہی بڑی بڑی نشانیاں دیکھیں', NULL, NULL, '7c5dfb99391673ef248bbb67e3dc787e650935b494bab83040967cdb7894803a'),
  ('ur.jalandhry', 53, 19, 4803, 'بھلا تم لوگوں نے لات اور عزیٰ کو دیکھا', NULL, NULL, '69a65e4b374c2c0ac115ef8532fe25a92a73e611c2588d08dae40d5a248e6351'),
  ('ur.jalandhry', 53, 20, 4804, 'اور تیسرے منات کو (کہ یہ بت کہیں خدا ہوسکتے ہیں)', NULL, NULL, '7fd98f54f856c7ac227e8f59a0b51f910ead19601ae3a199b6a60ce9c94274e8'),
  ('ur.jalandhry', 53, 21, 4805, '(مشرکو!) کیا تمہارے لئے تو بیٹے اور خدا کے لئے بیٹیاں', NULL, NULL, 'a26e95df90975beef2914cd14c2154808b79031e67181b0f94fc459f27a61dfe'),
  ('ur.jalandhry', 53, 22, 4806, 'یہ تقسیم تو بہت بےانصافی کی ہے', NULL, NULL, '6495dde78d3b3eb4a31eb3a3ce7bf4bc502d803aff86809e4652fdff4ec5cbe9'),
  ('ur.jalandhry', 53, 23, 4807, 'وہ تو صرف نام ہی نام ہیں جو تم نے اور تمہارے باپ دادا نے گھڑ لئے ہیں۔ خدا نے تو ان کی کوئی سند نازل نہیں کی۔ یہ لوگ محض ظن (فاسد) اور خواہشات نفس کے پیچھے چل رہے ہیں۔ حالانکہ ان کے پروردگار کی طرف سے ان کے پاس ہدایت آچکی ہے', NULL, NULL, 'c77718e6e099e2fa302e1ae80cd77cf2d4f3e5c2f7a134e9eceebba74a76c315'),
  ('ur.jalandhry', 53, 24, 4808, 'کیا جس چیز کی انسان آرزو کرتا ہے وہ اسے ضرور ملتی ہے', NULL, NULL, '542ca5584963577ba3ba8f2eb9c9b61569a6dc6764a33ac9ab830ed16a304d8c'),
  ('ur.jalandhry', 53, 25, 4809, 'آخرت اور دنیا تو الله ہی کے ہاتھ میں ہے', NULL, NULL, 'f3490ae63401cd312431f3a50c0e6bb09f1a1fa9c653639806dc2ca41a795bf1'),
  ('ur.jalandhry', 53, 26, 4810, 'اور آسمانوں میں بہت سے فرشتے ہیں جن کی سفارش کچھ بھی فائدہ نہیں دیتی مگر اس وقت کہ خدا جس کے لئے چاہے اجازت بخشے اور (سفارش) پسند کرے', NULL, NULL, '2d462767436c34be5725d1afe79371a5a4253a793cb30429905277f4328f1c7c'),
  ('ur.jalandhry', 53, 27, 4811, 'جو لوگ آخرت پر ایمان نہیں لاتے وہ فرشتوں کو (خدا کی) لڑکیوں کے نام سے موسوم کرتے ہیں', NULL, NULL, '55bdbf0d386d4b8f45ac3a8fa152535c2bb950dcf82c8a550bfe4cbea8211ab9'),
  ('ur.jalandhry', 53, 28, 4812, 'حالانکہ ان کو اس کی کچھ خبر نہیں۔ وہ صرف ظن پر چلتے ہیں۔ اور ظن یقین کے مقابلے میں کچھ کام نہیں آتا', NULL, NULL, '00b3a7582918c9379a99f3351a4cc43fb90c939be504cddc5f6723210a8f925e'),
  ('ur.jalandhry', 53, 29, 4813, 'تو جو ہماری یاد سے روگردانی اور صرف دنیا ہی کی زندگی کا خواہاں ہو اس سے تم بھی منہ پھیر لو', NULL, NULL, '8d46f0bf21e92b0f52b1c4e87de28aa9f36d032e5a7eeda2ab9ba8f7b538620f'),
  ('ur.jalandhry', 53, 30, 4814, 'ان کے علم کی انتہا یہی ہے۔ تمہارا پروردگار اس کو بھی خوب جانتا ہے جو اس کے رستے سے بھٹک گیا اور اس سے بھی خوب واقف ہے جو رستے پر چلا', NULL, NULL, 'a64c2928850b8f5a3b5440acfbeb3d6667f010ce8be043c35bba9f0be8279074'),
  ('ur.jalandhry', 53, 31, 4815, 'اور جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب خدا ہی کا ہے (اور اس نے خلقت کو) اس لئے (پیدا کیا ہے) کہ جن لوگوں نے برے کام کئے ان کو ان کے اعمال کا (برا) بدلا دے اور جنہوں نے نیکیاں کیں ان کو نیک بدلہ دے', NULL, NULL, 'c0df207d5ff7faadef87bff661db22f5cbc0472a211d0f98e963ba2ee9376a0a'),
  ('ur.jalandhry', 53, 32, 4816, 'جو صغیرہ گناہوں کے سوا بڑے بڑے گناہوں اور بےحیائی کی باتوں سے اجتناب کرتے ہیں۔ بےشک تمہارا پروردگار بڑی بخشش والا ہے۔ وہ تم کو خوب جانتا ہے۔ جب اس نے تم کو مٹی سے پیدا کیا اور جب تم اپنی ماؤں کے پیٹ میں بچّے تھے۔ تو اپنے آپ کو پاک صاف نہ جتاؤ۔ جو پرہیزگار ہے وہ اس سے خوب واقف ہے', NULL, NULL, '1f3626b650a6102be2b6cc03cb8d600f81b13fdcd88f3cf03019e1ad5d6e79e2'),
  ('ur.jalandhry', 53, 33, 4817, 'بھلا تم نے اس شخص کو دیکھا جس نے منہ پھیر لیا', NULL, NULL, 'a5eb4c9d891f76edb0b4cb2efc8a65ddaaafb81053ffafabe9fa5940c1ab7ec1'),
  ('ur.jalandhry', 53, 34, 4818, 'اور تھوڑا سا دیا (پھر) ہاتھ روک لیا', NULL, NULL, 'df7b9cfc0788267a9f7644efe10d9fdbc8d37e31b6986042f9d1ce05805cdeaf'),
  ('ur.jalandhry', 53, 35, 4819, 'کیا اس کے پاس غیب کا علم ہے کہ وہ اس کو دیکھ رہا ہے', NULL, NULL, 'c79c8eca9b2ac3995821b21bbca5ed6cceb5fd76fca70a35265a2ebd3cd42e95'),
  ('ur.jalandhry', 53, 36, 4820, 'کیا جو باتیں موسیٰ کے صحیفوں میں ہیں ان کی اس کو خبر نہیں پہنچی', NULL, NULL, '83d3a02f5c85f0d539f89b05c1c1c1cc8c734f643f4dab134add9fa09f7b119a'),
  ('ur.jalandhry', 53, 37, 4821, 'اور ابراہیمؑ کی جنہوں نے (حق طاعت ورسالت) پورا کیا', NULL, NULL, 'fd54f124904a811c908db7970ac3fd84d48a9a968cff0cf2c26f2fc7fd82a916'),
  ('ur.jalandhry', 53, 38, 4822, 'یہ کہ کوئی شخص دوسرے (کے گناہ) کا بوجھ نہیں اٹھائے گا', NULL, NULL, '2530c01df09b39fb594bc05a2dfe900bb274052e43474fbded7ef0918f7c9a51'),
  ('ur.jalandhry', 53, 39, 4823, 'اور یہ کہ انسان کو وہی ملتا ہے جس کی وہ کوشش کرتا ہے', NULL, NULL, '56f9c8ef27f7b724e1dac2fb22d22746771fdf6a80d51926e2a8a2cdef0d7462'),
  ('ur.jalandhry', 53, 40, 4824, 'اور یہ کہ اس کی کوشش دیکھی جائے گی', NULL, NULL, '8d337ace49cd3982658d68c3d803c3b1e4689fa997c9d3e4783805a410c21c3a'),
  ('ur.jalandhry', 53, 41, 4825, 'پھر اس کو اس کا پورا پورا بدلا دیا جائے گا', NULL, NULL, '2059856d1c0c4d7ffdf4f46da8abdd10264a6f0f58a3056e4dbafdacb14007aa'),
  ('ur.jalandhry', 53, 42, 4826, 'اور یہ کہ تمہارے پروردگار ہی کے پاس پہنچنا ہے', NULL, NULL, '7c06024358439a99357927222078a97658eb80fb9292116095bfa4a58171da2d'),
  ('ur.jalandhry', 53, 43, 4827, 'اور یہ کہ وہ ہنساتا اور رلاتا ہے', NULL, NULL, '305d2b0701a69f667adc31248cac6c40de8e4f271ec26ee64d30dbb59e1f6ac0'),
  ('ur.jalandhry', 53, 44, 4828, 'اور یہ کہ وہی مارتا اور جلاتا ہے', NULL, NULL, 'a948e4a7edadc53581f54e91f3e2b8fe4cb2f75a19d4679e7551ce43e53ca45b'),
  ('ur.jalandhry', 53, 45, 4829, 'اور یہ کہ وہی نر اور مادہ دو قسم (کے حیوان) پیدا کرتا ہے', NULL, NULL, 'a32f1e6d727c68877729e5aa6d52a645fc84a1659b0055eb951e81c7de455f84'),
  ('ur.jalandhry', 53, 46, 4830, '(یعنی) نطفے سے جو (رحم میں) ڈالا جاتا ہے', NULL, NULL, '9e6492b26aba0ab1027fdc6560e89b096f4f80503cd1f9ab18aa3a124e942039'),
  ('ur.jalandhry', 53, 47, 4831, 'اور یہ کہ (قیامت کو) اسی پر دوبارہ اٹھانا لازم ہے', NULL, NULL, 'd52481a4a752a5576419584403b2cf282ca5e41908e6b6ae4b3d9fe314e068f2'),
  ('ur.jalandhry', 53, 48, 4832, 'اور یہ کہ وہی دولت مند بناتا اور مفلس کرتا ہے', NULL, NULL, '682b146fddc2ca9b477b05bef56b3e51b670fb5ab00005c491520558c444e5a6'),
  ('ur.jalandhry', 53, 49, 4833, 'اور یہ کہ وہی شعریٰ کا مالک ہے', NULL, NULL, '2750b44c737ed27a662ed4e63acea035d5f2c67b646668a20569d074a1d3378e'),
  ('ur.jalandhry', 53, 50, 4834, 'اور یہ کہ اسی نے عاد اول کو ہلاک کر ڈالا', NULL, NULL, '66e20ca558971c3c4f2bc8096f18e87e4195d61b961f5150d7c6f8d41a8330cf'),
