  ('ur.jalandhry', 54, 51, 4897, 'اور ہم تمہارے ہم مذہبوں کو ہلاک کرچکے ہیں تو کوئی ہے کہ سوچے سمجھے؟', NULL, NULL, 'fe504c0960f19cfecfdf212dadbca638e123520d58dee7486360642af618eb7b'),
  ('ur.jalandhry', 54, 52, 4898, 'اور جو کچھ انہوں نے کیا، (ان کے) اعمال ناموں میں (مندرج) ہے', NULL, NULL, '332c08080ee502149746e9b135cd5ffef7b225968aca55063dc82d5c92d65844'),
  ('ur.jalandhry', 54, 53, 4899, '(یعنی) ہر چھوٹا اور بڑا کام لکھ دیا گیا ہے', NULL, NULL, '913971da0edbb1f723496445a7b901beda52af2de1419b41b8c73e1d00acb54c'),
  ('ur.jalandhry', 54, 54, 4900, 'جو پرہیزگار ہیں وہ باغوں اور نہروں میں ہوں گے', NULL, NULL, '056581d5c23d63f2f354ee475788f78680c62edfad8c02b8fb426d79a760dfc9')
