  ('ur.jalandhry', 54, 55, 4901, '(یعنی) پاک مقام میں ہر طرح کی قدرت رکھنے والے بادشاہ کی بارگاہ میں', NULL, NULL, '3e95e59fc654517eb0a942132526ef6ba17b059dde51bb678bd0ae8722b5180b'),
  ('ur.jalandhry', 55, 1, 4902, '(خدا جو) نہایت مہربان', NULL, NULL, '8b9ff0e0c04f011a742af48d0c7a560eb05dbd6755243eec609ef3b28a8be3b1'),
  ('ur.jalandhry', 55, 2, 4903, 'اسی نے قرآن کی تعلیم فرمائی', NULL, NULL, '6bd87d67a1005a6ff0f9c01337997ed2703423521ef72bf501212214b0d2f6c8'),
  ('ur.jalandhry', 55, 3, 4904, 'اسی نے انسان کو پیدا کیا', NULL, NULL, 'e79e1b92a5f467d8f56c05e7545ca21c9347ce752c8290acf97ed8f3599959e2'),
  ('ur.jalandhry', 55, 4, 4905, 'اسی نے اس کو بولنا سکھایا', NULL, NULL, 'ad5c133c4990de3bd54b274126cc3e7d804db472fbf8ba3eba61545bdc624517'),
  ('ur.jalandhry', 55, 5, 4906, 'سورج اور چاند ایک حساب مقرر سے چل رہے ہیں', NULL, NULL, 'bcbdd3a9e9a543963202231a983df649c1598634e7549f58af17c48e440f5cb9'),
  ('ur.jalandhry', 55, 6, 4907, 'اور بوٹیاں اور درخت سجدہ کر رہے ہیں', NULL, NULL, '532921f514e513f29da53671a8ab49f406e5641d5bd9c0b590a3600f68cc5b4e'),
  ('ur.jalandhry', 55, 7, 4908, 'اور اسی نے آسمان کو بلند کیا اور ترازو قائم کی', NULL, NULL, '55fce5cc9f24e69dcde592e07acdd22b20a96cfc403098d9103ce8584eeffe72'),
  ('ur.jalandhry', 55, 8, 4909, 'کہ ترازو (سے تولنے) میں حد سے تجاوز نہ کرو', NULL, NULL, '9f49c9955ec9ce0d3160a5437abe232867b27dcc1603b78a0158f9b50fa6d260'),
  ('ur.jalandhry', 55, 9, 4910, 'اور انصاف کے ساتھ ٹھیک تولو۔ اور تول کم مت کرو', NULL, NULL, '317c9afcd234c3e9b909e03c9af338a979d177496f359be5d6b8bb54d975447b'),
  ('ur.jalandhry', 55, 10, 4911, 'اور اسی نے خلقت کے لئے زمین بچھائی', NULL, NULL, '0dae241101a6a7e8d681837d16cbc3697044f4f3b53075c3e45a02459db86f3d'),
  ('ur.jalandhry', 55, 11, 4912, 'اس میں میوے اور کھجور کے درخت ہیں جن کے خوشوں پر غلاف ہوتے ہیں', NULL, NULL, '8aa748ca62b461920c924125e32389b46caa0561a505e624ad2717a44217de93'),
  ('ur.jalandhry', 55, 12, 4913, 'اور اناج جس کے ساتھ بھس ہوتا ہے اور خوشبودار پھول', NULL, NULL, '285affc34b607c34005796adb233cc98940d4e680461b1894da770bad08171d7'),
  ('ur.jalandhry', 55, 13, 4914, 'تو (اے گروہ جن وانس) تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, 'fe439cd1049f79017b64a5adc2dc6f967a37ad9754b8767cea371db2346dd159'),
  ('ur.jalandhry', 55, 14, 4915, 'اسی نے انسان کو ٹھیکرے کی طرح کھنکھناتی مٹی سے بنایا', NULL, NULL, 'df1321a855c76fc6df9a385c20cd0db47baa620de23b65d448df47d16a6d63d1'),
  ('ur.jalandhry', 55, 15, 4916, 'اور جنات کو آگ کے شعلے سے پیدا کیا', NULL, NULL, 'ecbaec6dd90438772ba519a359992cf9b8ad43309786279050c92b1c6c94ff54'),
  ('ur.jalandhry', 55, 16, 4917, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 17, 4918, 'وہی دونوں مشرقوں اور دونوں مغربوں کا مالک (ہے)', NULL, NULL, '389e48018e15880be06c0adef5677217f821ea4704e3f21e1c9ab8a924bf746c'),
  ('ur.jalandhry', 55, 18, 4919, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 19, 4920, 'اسی نے دو دریا رواں کئے جو آپس میں ملتے ہیں', NULL, NULL, '67c11ffa9ce5abfae4cb5ad3bec9f82775246f7bc067c51f5728e80809a683ab'),
  ('ur.jalandhry', 55, 20, 4921, 'دونوں میں ایک آڑ ہے کہ (اس سے) تجاوز نہیں کرسکتے', NULL, NULL, '25fe65ba7b01b0573db1de87d9aea839c3b17118bbecedcf341dae85f583930b'),
  ('ur.jalandhry', 55, 21, 4922, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 22, 4923, 'دونوں دریاؤں سے موتی اور مونگے نکلتے ہیں', NULL, NULL, '3cf0d014f4e613bfe58321a812433668bc5e04f5d4ad7de5c41a241ac7b70eb9'),
  ('ur.jalandhry', 55, 23, 4924, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 24, 4925, 'اور جہاز بھی اسی کے ہیں جو دریا میں پہاڑوں کی طرح اونچے کھڑے ہوتے ہیں', NULL, NULL, '135e68148445bab6a3bf254fc0c46d5d7772ef02e6a13d567609e05927974ebd'),
  ('ur.jalandhry', 55, 25, 4926, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 26, 4927, 'جو (مخلوق) زمین پر ہے سب کو فنا ہونا ہے', NULL, NULL, '4ea5973bd4a7f0f9c3236aa90a08b879ddc92881c51ffefc2c26e75f5a8455e2'),
  ('ur.jalandhry', 55, 27, 4928, 'اور تمہارے پروردگار ہی کی ذات (بابرکات) جو صاحب جلال وعظمت ہے باقی رہے گی', NULL, NULL, '3ed1cd78a2ce53da5faaa97494164991b2e5fc345fc11eed3de99202534d1a3e'),
  ('ur.jalandhry', 55, 28, 4929, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 29, 4930, 'آسمان اور زمین میں جتنے لوگ ہیں سب اسی سے مانگتے ہیں۔ وہ ہر روز کام میں مصروف رہتا ہے', NULL, NULL, '0dcbda429de9b8c4fd5603fee59bca5261d9b3733f9e47801891dd1b42685320'),
  ('ur.jalandhry', 55, 30, 4931, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 31, 4932, 'اے دونوں جماعتو! ہم عنقریب تمہاری طرف متوجہ ہوتے ہیں', NULL, NULL, 'ba630229d09ff4928c540aef9bcf907c98d5899eacd3400c2f29cdf5f99fb505'),
  ('ur.jalandhry', 55, 32, 4933, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 33, 4934, 'اے گروہِ جن وانس اگر تمہیں قدرت ہو کہ آسمان اور زمین کے کناروں سے نکل جاؤ تو نکل جاؤ۔ اور زور کے سوا تم نکل سکنے ہی کے نہیں', NULL, NULL, '864d4e0462d777a471b7770c58f7447ffb043a584cdf7934b11bab34c6e8c1f4'),
  ('ur.jalandhry', 55, 34, 4935, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 35, 4936, 'تم پر آگ کے شعلے اور دھواں چھوڑ دیا جائے گا تو پھر تم مقابلہ نہ کرسکو گے', NULL, NULL, '662a07e55568c1a4c3382416bf6e98d90143d45f7d7e88f2d574176951387d9b'),
  ('ur.jalandhry', 55, 36, 4937, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 37, 4938, 'پھر جب آسمان پھٹ کر تیل کی تلچھٹ کی طرح گلابی ہوجائے گا (تو) وہ کیسا ہولناک دن ہوگا', NULL, NULL, 'dd9ca6c94db1ef036883794b1a43f6a57a624404c36c870e1b089c8a48c81795'),
  ('ur.jalandhry', 55, 38, 4939, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 39, 4940, 'اس روز نہ تو کسی انسان سے اس کے گناہوں کے بارے میں پرسش کی جائے گی اور نہ کسی جن سے', NULL, NULL, '8993f879329fd86f2f75aa77e2620c2d4bf2c2672bf7883862dfcdcc0139cd54'),
  ('ur.jalandhry', 55, 40, 4941, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 41, 4942, 'گنہگار اپنے چہرے ہی سے پہچان لئے جائیں گے تو پیشانی کے بالوں اور پاؤں سے پکڑ لئے جائیں گے', NULL, NULL, 'd47563ca1dc2d506aa787ca6308f15e1d8b0d3fc2db72f63f492216083232a1c'),
  ('ur.jalandhry', 55, 42, 4943, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 43, 4944, 'یہی وہ جہنم ہے جسے گنہگار لوگ جھٹلاتے تھے', NULL, NULL, 'fbffd0e9865927ae0f33d9a6596b536cb2b3b4435cd1a20a32e75ce30bc52aaf'),
  ('ur.jalandhry', 55, 44, 4945, 'وہ دوزخ اور کھولتے ہوئے گرم پانی کے درمیان گھومتے پھریں گے', NULL, NULL, '8104b161d82045a5b4ca2ecc627a8db16cc4c5b95817486fec8e61525f68f77a'),
  ('ur.jalandhry', 55, 45, 4946, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 46, 4947, 'اور جو شخص اپنے پروردگار کے سامنے کھڑے ہونے سے ڈرا اس کے لئے دو باغ ہیں', NULL, NULL, '09d776b7490f48499b683ad2c4f124d5def8fefbd045574e501d7eff8129d1b6'),
  ('ur.jalandhry', 55, 47, 4948, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 48, 4949, 'ان دونوں میں بہت سی شاخیں (یعنی قسم قسم کے میووں کے درخت ہیں)', NULL, NULL, '5634b8c3122ecc585c2ea3f5974ec4b9efe135e5952aeacd7fce61af6148b093'),
  ('ur.jalandhry', 55, 49, 4950, 'تو تم اپنے پروردگار کی کون کون سی نعمت کو جھٹلاؤ گے؟', NULL, NULL, '9bb8c825563b44685583d148a42aab3a5c6b129abea4ca8b5aed05bee56bc530'),
  ('ur.jalandhry', 55, 50, 4951, 'ان میں دو چشمے بہہ رہے ہیں', NULL, NULL, 'c85eb1a538ea4a56764bed2916642515a4e568179f4b9cd23594dbcd2d91bcc4'),
