  ('ur.jalandhry', 55, 70, 4971, 'ان میں نیک سیرت (اور) خوبصورت عورتیں ہیں', NULL, NULL, '7fb174772bbe21b67fd36cde0e37fcf8df5e08a8a075451563917bcf1ed3f405'),
