  ('ur.jalandhry', 55, 72, 4973, '(وہ) حوریں (ہیں جو) خیموں میں مستور (ہیں)', NULL, NULL, '8487a080a35cffa9df901bf846d69adb84b28bf08078b6bd0afbdb39d48812c0'),
