  ('ur.jalandhry', 56, 5, 4984, 'اور پہاڑ ٹوٹ کر ریزہ ریزہ ہوجائیں', NULL, NULL, '10b59d91c009db1805a980560cd8bba8ce33b52dce065809bf75505766df4e4e'),
  ('ur.jalandhry', 56, 6, 4985, 'پھر غبار ہو کر اُڑنے لگیں', NULL, NULL, '5d285f6643bbd3138461be56b6736abbbe50384bf53ad2fc6029e11d8bda1a3c'),
