  ('ur.jalandhry', 56, 14, 4993, 'اور تھوڑے سے پچھلوں میں سے', NULL, NULL, 'dfd4261803c490a9e234ed2cc0216442b5da7572c06e6d125e231ea5fa64ce37'),
