  ('ur.jalandhry', 56, 16, 4995, 'آمنے سامنے تکیہ لگائے ہوئے', NULL, NULL, 'b03dbd4ba8e120f51b4457ed919dae49e38c7f498c1ddb573480132743077ee8'),
  ('ur.jalandhry', 56, 17, 4996, 'نوجوان خدمت گزار جو ہمیشہ (ایک ہی حالت میں) رہیں گے ان کے آس پاس پھریں گے', NULL, NULL, 'feea57f9fbf784ed63c3bbae33d13ae377a637601b3f4c25797efc2e41222f49'),
  ('ur.jalandhry', 56, 18, 4997, 'یعنی آبخورے اور آفتابے اور صاف شراب کے گلاس لے لے کر', NULL, NULL, 'be364b44e9b9a998d4b2c56df0b18c30f9619d1fa8c2ffc7274db550ec4ce0d1'),
