  ('ur.jalandhry', 56, 49, 5028, 'کہہ دو کہ بےشک پہلے اور پچھلے', NULL, NULL, 'e89494b75539db788ba8f42f9b622213c9692ede7755e32d03fb20c7da11937a'),
  ('ur.jalandhry', 56, 50, 5029, '(سب) ایک روز مقرر کے وقت پر جمع کئے جائیں گے', NULL, NULL, 'e47e476d18920cbd0d5615dce08bbb271d7c5ec486f8f2097f7af8feda48024c'),
  ('ur.jalandhry', 56, 51, 5030, 'پھر تم اے جھٹلانے والے گمرا ہو!', NULL, NULL, 'd97e7aa0dab86d8a09b8e8fd01974f75783808f36231b21280c7d8db7964b0a3'),
  ('ur.jalandhry', 56, 52, 5031, 'تھوہر کے درخت کھاؤ گے', NULL, NULL, '758e8afaf53a134f4269ecea03378d637ab5e95900de6dd62f3c17c1f3c2dd17'),
  ('ur.jalandhry', 56, 53, 5032, 'اور اسی سے پیٹ بھرو گے', NULL, NULL, '3ade400473b94c4fa296f525d63f51c570aa619a29c9f07c8e4f3ae8604cbe9f'),
