  ('ur.jalandhry', 68, 25, 5296, 'اور کوشش کے ساتھ سویرے ہی جا پہنچے (گویا کھیتی پر) قادر ہیں', NULL, NULL, 'c649c1adddf5265f9d710a2eb653856286de14d533c8d0865ef4dbe6640cbed7'),
  ('ur.jalandhry', 68, 26, 5297, 'جب باغ کو دیکھا تو (ویران) کہنے لگے کہ ہم رستہ بھول گئے ہیں', NULL, NULL, '899d57add35301919ffbafa67ab4b1f09cfbfcc85e8158d2e681d52658fc3c25'),
  ('ur.jalandhry', 68, 27, 5298, 'نہیں بلکہ ہم (برگشتہ نصیب) بےنصیب ہیں', NULL, NULL, 'd9ab387ed0a37355be681749cc6ff4f6abf816856191f33dad93bd8d532414db'),
  ('ur.jalandhry', 68, 28, 5299, 'ایک جو اُن میں فرزانہ تھا بولا کہ کیا میں نے تم سے نہیں کہا تھا کہ تم تسبیح کیوں نہیں کرتے؟', NULL, NULL, '465e4cdc923eb08f1484a3c72405ae0cf7f428035b6ed03f8e0cf5ca4c43e98c'),
  ('ur.jalandhry', 68, 29, 5300, '(تب) وہ کہنے لگے کہ ہمارا پروردگار پاک ہے بےشک ہم ہی قصوروار تھے', NULL, NULL, '4464fdeea17aa7cb199ec04a64b1404d39b1977fb88728acfe2fcdd41b090c6e')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
