INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 68, 30, 5301, 'پھر لگے ایک دوسرے کو رو در رو ملامت کرنے', NULL, NULL, '9686f7e19beb5cc240d3bd3aa0dddfb81847ef1672177ca22b2c8fbe140eae6c'),
  ('ur.jalandhry', 68, 31, 5302, 'کہنے لگے ہائے شامت ہم ہی حد سے بڑھ گئے تھے', NULL, NULL, '597a54611e4c5c4f8019e607b425fbc1cb1f7978525c3c1af6085af887db0613'),
  ('ur.jalandhry', 68, 32, 5303, 'امید ہے کہ ہمارا پروردگار اس کے بدلے میں ہمیں اس سے بہتر باغ عنایت کرے ہم اپنے پروردگار کی طرف سے رجوع لاتے ہیں', NULL, NULL, '1eb06725bec33ac2e265c411eb5b7388d90a054915f39916fb0f4711a44f43ed'),
  ('ur.jalandhry', 68, 33, 5304, '(دیکھو) عذاب یوں ہوتا ہے۔ اور آخرت کا عذاب اس سے کہیں بڑھ کر ہے۔ کاش! یہ لوگ جانتے ہوتے', NULL, NULL, '28e9c0f47bba5afd6986f61b4e4b4f53a1a8ca6dfffde8ddb6df51958706a250'),
  ('ur.jalandhry', 68, 34, 5305, 'پرہیزگاروں کے لئے ان کے پروردگار کے ہاں نعمت کے باغ ہیں', NULL, NULL, '8099d62f8f50a5233620ec658d99eb129e22088765f00b0f79387984795ce1e7'),
  ('ur.jalandhry', 68, 35, 5306, 'کیا ہم فرمانبرداروں کو نافرمانوں کی طرف (نعمتوں سے) محروم کردیں گے؟', NULL, NULL, 'ea5b44e911e422e08c4b9dbbd75c0269cee7b658a5ed5e2011f23af75dadc512'),
  ('ur.jalandhry', 68, 36, 5307, 'تمہیں کیا ہوگیا ہے کیسی تجویزیں کرتے ہو؟', NULL, NULL, '344d610972afee8e9118b9f69f9713655a2f72c313d60ffe36e6ca9fb8d01d9e'),
  ('ur.jalandhry', 68, 37, 5308, 'کیا تمہارے پاس کوئی کتاب ہے جس میں (یہ) پڑھتے ہو', NULL, NULL, 'f28fa6c955b7da62ee3e548a8654ea8c5dfe4e7cada62e5d5cd6c59c1bd3e486'),
  ('ur.jalandhry', 68, 38, 5309, 'کہ جو چیز تم پسند کرو گے وہ تم کو ضرور ملے گی', NULL, NULL, '95da51b4bea3ae378426b571f317f66bbba901a5f3496fc03a2b2ac908bf8e48'),
  ('ur.jalandhry', 68, 39, 5310, 'یا تم نے ہم سے قسمیں لے رکھی ہیں جو قیامت کے دن تک چلی جائیں گی کہ جس شے کا تم حکم کرو گے وہ تمہارے لئے حاضر ہوگی', NULL, NULL, '7e140489cbbcf21e8830645df75cead1757ecbbe76bcca2fe73d998be67f8fa3'),
  ('ur.jalandhry', 68, 40, 5311, 'ان سے پوچھو کہ ان میں سے اس کا کون ذمہ لیتا ہے؟', NULL, NULL, '60ed7d600b9ba13ffbbbb3fcbdb93265c5221f914a3584d230e275749a1a791f'),
  ('ur.jalandhry', 68, 41, 5312, 'کیا (اس قول میں) ان کے اور بھی شریک ہیں؟ اگر یہ سچے ہیں تو اپنے شریکوں کو لا سامنے کریں', NULL, NULL, 'efb0ea9dedf8aed0199fbc9bfbf2ec1425fe4a41a1b67a9b57a7ee54c6116cad'),
  ('ur.jalandhry', 68, 42, 5313, 'جس دن پنڈلی سے کپڑا اٹھا دیا جائے گا اور کفار سجدے کے لئے بلائے جائیں گے تو سجدہ نہ کرسکیں گے', NULL, NULL, 'a8f7a6c43304b9dabeb261a5b42b23a8fecbc1f4588601bcb9163ce3fa860f01'),
  ('ur.jalandhry', 68, 43, 5314, 'ان کی آنکھیں جھکی ہوئی ہوں گی اور ان پر ذلت چھا رہی ہوگی حالانکہ پہلے (اُس وقت) سجدے کے لئے بلاتے جاتے تھے جب کہ صحیح وسالم تھے', NULL, NULL, '09c81919334beb4ef3b26f27dad2b98e4861db270a081f21fefdc0ebcd96e7b7'),
  ('ur.jalandhry', 68, 44, 5315, 'تو مجھ کو اس کلام کے جھٹلانے والوں سے سمجھ لینے دو۔ ہم ان کو آہستہ آہستہ ایسے طریق سے پکڑیں گے کہ ان کو خبر بھی نہ ہوگی', NULL, NULL, '74c4add05d938b9907f81d067c6fad77cc4c00ee28f0b40d934a58f1afc1b313'),
  ('ur.jalandhry', 68, 45, 5316, 'اور میں ان کو مہلت دیئے جاتا ہوں میری تدبیر قوی ہے', NULL, NULL, '0608755efc81229222fedb0a9a14bad8d85af5de013bb831fe81de99000677fb'),
  ('ur.jalandhry', 68, 46, 5317, 'کیا تم ان سے کچھ اجر مانگتے ہو کہ ان پر تاوان کا بوجھ پڑ رہا ہے', NULL, NULL, 'd3f0270dbb13da9622ac4008de18df68ca02f987d5b6bd604c6d477c2efc24f4'),
  ('ur.jalandhry', 68, 47, 5318, 'یا ان کے پاس غیب کی خبر ہے کہ (اسے) لکھتے جاتے ہیں', NULL, NULL, '31d62b342e9034e1757223f7d01c56bc2d87333f81aab5a26908fa8a7b22357c'),
  ('ur.jalandhry', 68, 48, 5319, 'تو اپنے پروردگار کے حکم کے انتظار میں صبر کئے رہو اور مچھلی (کا لقمہ ہونے) والے یونس کی طرح رہو نا کہ انہوں نے (خدا) کو پکارا اور وہ (غم و) غصے میں بھرے ہوئے تھے', NULL, NULL, '7c4a03537bc152767dc363e6356fba04f34d3cf32a2e075e2533e132292e4a51'),
  ('ur.jalandhry', 68, 49, 5320, 'اگر تمہارے پروردگار کی مہربانی ان کی یاوری نہ کرتی تو وہ چٹیل میدان میں ڈال دیئے جاتے اور ان کا حال ابتر ہوجاتا', NULL, NULL, '758e626e2c3c2dc73d692815184077e52897c7f9ca659d1a0a04dd839278c143'),
  ('ur.jalandhry', 68, 50, 5321, 'پھر پروردگار نے ان کو برگزیدہ کرکے نیکوکاروں میں کرلیا', NULL, NULL, '504ebbe2beff08210f2a18ba4430dce2a60fb972e6043cabf1fa05477bbc6139'),
  ('ur.jalandhry', 68, 51, 5322, 'اور کافر جب (یہ) نصیحت (کی کتاب) سنتے ہیں تو یوں لگتے ہیں کہ تم کو اپنی نگاہوں سے پھسلا دیں گے اور کہتے یہ تو دیوانہ ہے', NULL, NULL, '6348a1d71c99246e264b9b235782237292b99f9330d7b4cf147a14a15b59d760'),
  ('ur.jalandhry', 68, 52, 5323, 'اور (لوگو) یہ (قرآن) اہل عالم کے لئے نصیحت ہے', NULL, NULL, 'c793d8e273462405c0c3734efb7cb054eb9183fee3d149cb30b6b9598b068ed1'),
  ('ur.jalandhry', 69, 1, 5324, 'سچ مچ ہونے والی', NULL, NULL, '07678dd3787267ffce9d7016c209b4a1c8bd50a270cbf4972e4f9e8828fb9df1'),
  ('ur.jalandhry', 69, 2, 5325, 'وہ سچ مچ ہونے والی کیا ہے؟', NULL, NULL, '070975db79c04133bc4230902d7a337fda226dd55ada957242a951c9bb727ad0'),
  ('ur.jalandhry', 69, 3, 5326, 'اور تم کو کیا معلوم ہے کہ سچ مچ ہونے والی کیا ہے؟', NULL, NULL, 'f78da6e5d83b213699129131a46f9134cf29289200efcded880b17b761fb3f67'),
  ('ur.jalandhry', 69, 4, 5327, 'کھڑکھڑانے والی (جس) کو ثمود اور عاد (دونوں) نے جھٹلایا', NULL, NULL, 'c07909a01d2955d184ffeac843c43d8b3efcfda8d4a99a327970fb3b69741230'),
  ('ur.jalandhry', 69, 5, 5328, 'سو ثمود تو کڑک سے ہلاک کردیئے گئے', NULL, NULL, '2f808e6a7065cef3875495928958453d003fe7d194b4075b74930a57e08f2a19'),
  ('ur.jalandhry', 69, 6, 5329, 'رہے عاد تو ان کا نہایت تیز آندھی سے ستیاناس کردیا گیا', NULL, NULL, '744f57adb7ffe37aefab1ccd3bed81a92f39521cf2b1a91ecb40d3b83047ec91'),
  ('ur.jalandhry', 69, 7, 5330, 'خدا نے اس کو سات رات اور آٹھ دن لگاتار ان پر چلائے رکھا تو (اے مخاطب) تو لوگوں کو اس میں (اس طرح) ڈھئے (اور مرے) پڑے دیکھے جیسے کھجوروں کے کھوکھلے تنے', NULL, NULL, '903e3e9244c25f7578414fd76fb4f252f6a51ac00a96c700f5be2be175fe51de'),
  ('ur.jalandhry', 69, 8, 5331, 'بھلا تو ان میں سے کسی کو بھی باقی دیکھتا ہے؟', NULL, NULL, '6156e8b42b5cb050e8a529c92e35a85a6421ee858e87a43d24a427121f6c076e'),
  ('ur.jalandhry', 69, 9, 5332, 'اور فرعون اور جو لوگ اس سے پہلے تھے اور وہ جو الٹی بستیوں میں رہتے تھے سب گناہ کے کام کرتے تھے', NULL, NULL, '684da7ef12c876fbb790483870d3fdaef8faa479f97fd2464f6e6fa6d92aee9f'),
  ('ur.jalandhry', 69, 10, 5333, 'انہوں نے اپنے پروردگار کے پیغمبر کی نافرمانی کی تو خدا نے بھی ان کو بڑا سخت پکڑا', NULL, NULL, 'cba0ec9564fd150f29a35a56a67acd02cf4f8d075d5bceabb043afdac38b73d3'),
  ('ur.jalandhry', 69, 11, 5334, 'جب پانی طغیانی پر آیا تو ہم نے تم (لوگوں) کو کشتی میں سوار کرلیا', NULL, NULL, '50c2cd89ef30f4a37a6ff456ee0b2fc8645026fa3f6dc8be76ab666c9720b1ac'),
  ('ur.jalandhry', 69, 12, 5335, 'تاکہ اس کو تمہارے لئے یادگار بنائیں اور یاد رکھنے والے کان اسے یاد رکھیں', NULL, NULL, '72f062a80a8f8d1ec4f39e4b1f53a1d6e161b68106d7b1d3d2285776a2ba2b38'),
  ('ur.jalandhry', 69, 13, 5336, 'تو جب صور میں ایک (بار) پھونک مار دی جائے گی', NULL, NULL, '3551d70d341729d7b5d3c4b65083b7497e06873b08c4de14b9459ca2eb1e1c19'),
  ('ur.jalandhry', 69, 14, 5337, 'اور زمین اور پہاڑ دونوں اٹھا لئے جائیں گے۔ پھر ایک بارگی توڑ پھوڑ کر برابر کردیئے جائیں گے', NULL, NULL, 'f08f6f4a3c3d6056f3bcef423161e28d39eecadcdb38f9d7ca9585a80d531a4c'),
  ('ur.jalandhry', 69, 15, 5338, 'تو اس روز ہو پڑنے والی (یعنی قیامت) ہو پڑے گی', NULL, NULL, 'fef783dabfc7ee7debe74a66d411a638bf34b58172977d32f1bbd73e3e2df1fe'),
  ('ur.jalandhry', 69, 16, 5339, 'اور آسمان پھٹ جائے گا تو وہ اس دن کمزور ہوگا', NULL, NULL, 'fd896cbcbff8f71b779faa42efa47b92837b38b858f740ce1235ce6398664a80'),
  ('ur.jalandhry', 69, 17, 5340, 'اور فرشتے اس کے کناروں پر (اُتر آئیں گے) اور تمہارے پروردگار کے عرش کو اس روز آٹھ فرشتے اپنے سروں پر اُٹھائے ہوں گے', NULL, NULL, '794296c39298f9b8f728d87c0ee90f36c8683fea939c3ef8c9629d0223e1495b'),
  ('ur.jalandhry', 69, 18, 5341, 'اس روز تم (سب لوگوں کے سامنے) پیش کئے جاؤ گے اور تمہاری کوئی پوشیدہ بات چھپی نہ رہے گی', NULL, NULL, '472e03579405561747de503bc4ece58fb9b6bf79d51b537d7c5320939adce08e'),
  ('ur.jalandhry', 69, 19, 5342, 'تو جس کا (اعمال) نامہ اس کے داہنے ہاتھ میں دیا جائے گا وہ (دوسروں سے) کہے گا کہ لیجیئے میرا نامہ (اعمال) پڑھیئے', NULL, NULL, '2fb8ebe79de419c3a7fbb2fa5567eeeb4947b00d4ac61b09eaa2b66dbabcae66'),
  ('ur.jalandhry', 69, 20, 5343, 'مجھے یقین تھا کہ مجھ کو میرا حساب (کتاب) ضرور ملے گا', NULL, NULL, 'c1935bb6381cb069d14240864e94fc0a4c15806c0a1bd4985cdd7cdda8e52637'),
  ('ur.jalandhry', 69, 21, 5344, 'پس وہ (شخص) من مانے عیش میں ہوگا', NULL, NULL, '1edb698ee7b68688d7c3f7ca3c0ce00021db196e83df4fdbae66fa0514883068'),
  ('ur.jalandhry', 69, 22, 5345, '(یعنی) اونچے (اونچے محلوں) کے باغ میں', NULL, NULL, '8fcc1d1510b72f7503c3e733f7aee85e500568f4cb7c6977b8762d413ed1d69c'),
  ('ur.jalandhry', 69, 23, 5346, 'جن کے میوے جھکے ہوئے ہوں گے', NULL, NULL, '62e367ee0e1514ce2209690e5afa81c26866c2d5c85635744d163e62526ca6c1'),
  ('ur.jalandhry', 69, 24, 5347, 'جو (عمل) تم ایام گزشتہ میں آگے بھیج چکے ہو اس کے صلے میں مزے سے کھاؤ اور پیو', NULL, NULL, '91b8198aa2aa2115cdb0e64c5406cf73b7b54130a56445ace547f40cfd90e113'),
  ('ur.jalandhry', 69, 25, 5348, 'اور جس کا نامہ (اعمال) اس کے بائیں ہاتھ میں یاد جائے گا وہ کہے گا اے کاش مجھ کو میرا (اعمال) نامہ نہ دیا جاتا', NULL, NULL, '3890aefbb0d779209bdcb18866f72b32b1d5b4c8a0abe071191f29bd0fb90b2d'),
  ('ur.jalandhry', 69, 26, 5349, 'اور مجھے معلوم نہ ہو کہ میرا حساب کیا ہے', NULL, NULL, '2a091a9db1aaa70ba9a6162f9f847e48e40571fe745278dd492cea4bc57171b4'),
  ('ur.jalandhry', 69, 27, 5350, 'اے کاش موت (ابد الاآباد کے لئے میرا کام) تمام کرچکی ہوتی', NULL, NULL, 'c7a8cf6f42875b670fefc260b8d6ec318c340b3ceb571d8870bab43348017f79'),
  ('ur.jalandhry', 69, 28, 5351, 'آج) میرا مال میرے کچھ بھی کام بھی نہ آیا', NULL, NULL, '467c92b3cbb5423f3c1da18bc2e9fab36f6cde16ba0e7955f29604be7ce5e57b'),
  ('ur.jalandhry', 69, 29, 5352, '(ہائے) میری سلطنت خاک میں مل گئی', NULL, NULL, 'e21b9bdba7f01697eb4211734ce4b3b5f04caf90f3de49b9fac960c7dead46e8'),
  ('ur.jalandhry', 69, 30, 5353, '(حکم ہوگا کہ) اسے پکڑ لو اور طوق پہنا دو', NULL, NULL, '3cb4b8088115bd8213c7e41c02d39999d8272de6c7021fe973d38aede4780d22'),
  ('ur.jalandhry', 69, 31, 5354, 'پھر دوزخ کی آگ میں جھونک دو', NULL, NULL, 'b235ea6460db8874a62f9c568959a66bce5fe16f6a4aa42d06c31a34619771f4'),
  ('ur.jalandhry', 69, 32, 5355, 'پھر زنجیر سے جس کی ناپ ستر گز ہے جکڑ دو', NULL, NULL, 'a8b3e1f3300ac53cc2696ac1cbd5947d9857d7bb901af48355b138e9f463d49e'),
  ('ur.jalandhry', 69, 33, 5356, 'یہ نہ تو خدائے جل شانہ پر ایمان لاتا تھا', NULL, NULL, 'b22363a4c5253561cd1f43aaf9ea39f7e0004c60490c32cd765f72a8fca87587'),
  ('ur.jalandhry', 69, 34, 5357, 'اور نہ فقیر کے کھانا کھلانے پر آمادہ کرتا تھا', NULL, NULL, 'bca5e963ae5bc28aa813b0c9b3304a4797c291294e6f7b510b848d2aed2faa1b'),
  ('ur.jalandhry', 69, 35, 5358, 'سو آج اس کا بھی یہاں کوئی دوستدار نہیں', NULL, NULL, '9a7b1f6c2a85d942d69292f7f4e06056f452d35dffda110aa2e61545ac837065'),
  ('ur.jalandhry', 69, 36, 5359, 'اور نہ پیپ کے سوا (اس کے لئے) کھانا ہے', NULL, NULL, '2a4e13480bcc9e09233f5ca8a3422b89bb0c8fc414b31dd4aa785691a6ae7062'),
  ('ur.jalandhry', 69, 37, 5360, 'جس کو گنہگاروں کے سوا کوئی نہیں کھائے گا', NULL, NULL, 'cde6026fa7df6f9b885c538b2d779aeb810286d9f27af40fd03c0db0bd3f3d68'),
  ('ur.jalandhry', 69, 38, 5361, 'تو ہم کو ان چیزوں کی قسم جو تم کو نظر آتی ہیں', NULL, NULL, '565f6d1ea8cf4020437b8968291482e4a92cc2beb8c8dd444412a0c39678aaec'),
  ('ur.jalandhry', 69, 39, 5362, 'اور ان کی جو نظر میں نہیں آتیں', NULL, NULL, '64de9e894d7179339324d0d0735d73f6026963bdfbdd8eaed94ebe83da3dbccd'),
  ('ur.jalandhry', 69, 40, 5363, 'کہ یہ (قرآن) فرشتہٴ عالی مقام کی زبان کا پیغام ہے', NULL, NULL, 'f9b68cc0e792dfca670417e3e168e92d04edbe857a3a0a04537dde2761dad72a'),
  ('ur.jalandhry', 69, 41, 5364, 'اور یہ کسی شاعر کا کلام نہیں۔ مگر تم لوگ بہت ہی کم ایمان لاتے ہو', NULL, NULL, '02b0fd30c94e2fb831909fba2856fb0980479cf1d7cbff8d3974a881d01e12a1'),
  ('ur.jalandhry', 69, 42, 5365, 'اور نہ کسی کاہن کے مزخرفات ہیں۔ لیکن تم لوگ بہت ہی کم فکر کرتے ہو', NULL, NULL, '81e5b7ade228db3dc422c6bdd8bf4c1ceab5bc7a6d577e893d335cfee94ce1dd'),
  ('ur.jalandhry', 69, 43, 5366, 'یہ تو) پروردگار عالم کا اُتارا (ہوا) ہے', NULL, NULL, '268c8f54de860b168089c1b07b2f5853eb631b57cf93c38ecda231b439d7d089'),
  ('ur.jalandhry', 69, 44, 5367, 'اگر یہ پیغمبر ہماری نسبت کوئی بات جھوٹ بنا لاتے', NULL, NULL, '009aeb1f1b29973d3d1a5d0e17c59578933ed644e4586e6111375eb9c5cd1f66'),
  ('ur.jalandhry', 69, 45, 5368, 'تو ہم ان کا داہنا ہاتھ پکڑ لیتے', NULL, NULL, '0591f9a267eb7331c7bb25ddafc60a9e0f97a02d8a9f01d5de32171bbc7d1e99'),
  ('ur.jalandhry', 69, 46, 5369, 'پھر ان کی رگ گردن کاٹ ڈالتے', NULL, NULL, '37a3bf4e4aa27ab5fbacd32bcaf620f7e1d30fc0b00d879b12fdf7cf07a600f7'),
  ('ur.jalandhry', 69, 47, 5370, 'پھر تم میں سے کوئی (ہمیں) اس سے روکنے والا نہ ہوتا', NULL, NULL, '9be1597dae8fb0ec6ebce1d894ec51648d605e9acf9022c64c5dd83bc643680e'),
  ('ur.jalandhry', 69, 48, 5371, 'اور یہ (کتاب) تو پرہیزگاروں کے لئے نصیحت ہے', NULL, NULL, '35054ae6607eff08aca1211b45b8126506ae9d058d4b4328ca87fb0c86f27dee'),
  ('ur.jalandhry', 69, 49, 5372, 'اور ہم جانتے ہیں کہ تم میں سے بعض اس کو جھٹلانے والے ہیں', NULL, NULL, '893dac966d33cefbc627a96a1e8b32ac7a650b31886ec35149f2867214b646ba'),
  ('ur.jalandhry', 69, 50, 5373, 'نیز یہ کافروں کے لئے (موجب) حسرت ہے', NULL, NULL, 'eb494d89be3073cea4986d609db5e133b40416b3a71bca2e5590006cae0e360d'),
  ('ur.jalandhry', 69, 51, 5374, 'اور کچھ شک نہیں کہ یہ برحق قابل یقین ہے', NULL, NULL, 'e0773878247c8fc8d3330939afb961a4d5ee113ceaffb2cec85695bef00ffd7e'),
  ('ur.jalandhry', 69, 52, 5375, 'سو تم اپنے پروردگار عزوجل کے نام کی تنزیہ کرتے رہو', NULL, NULL, 'c2070f85ed4f24ed9690ccbb4522be8721583b97dabed5566829691d511c575a'),
  ('ur.jalandhry', 70, 1, 5376, 'ایک طلب کرنے والے نے عذاب طلب کیا جو نازل ہو کر رہے گا', NULL, NULL, '58c77cc020fcacf083a516a0ffa6c2254b82c5530d3e37dd98d05f752f93431b'),
  ('ur.jalandhry', 70, 2, 5377, '(یعنی) کافروں پر (اور) کوئی اس کو ٹال نہ سکے گا', NULL, NULL, '11c459631578d1120602048923243137343956ed628f8bb2335c32f6f58bd345'),
  ('ur.jalandhry', 70, 3, 5378, '(اور وہ) خدائے صاحب درجات کی طرف سے (نازل ہوگا)', NULL, NULL, '17efd0fe12c0a3ca9310b90992b291e2dae3b8ccf2f8a62c44a5ea1f9425fbb8'),
  ('ur.jalandhry', 70, 4, 5379, 'جس کی طرف روح (الامین) اور فرشتے پڑھتے ہیں (اور) اس روز (نازل ہوگا) جس کا اندازہ پچاس ہزار برس کا ہوگا', NULL, NULL, '7b67074b6daa8e24bc8f8e00ff3d532f6cbee57710ad0a1a8b981739e3a02263'),
  ('ur.jalandhry', 70, 5, 5380, '(تو تم کافروں کی باتوں کو) قوت کے ساتھ برداشت کرتے رہو', NULL, NULL, '80b40c8ea43e4a3cbbc5480a59fb129fb0780f922906846db8db4640557d0df1'),
  ('ur.jalandhry', 70, 6, 5381, 'وہ ان لوگوں کی نگاہ میں دور ہے', NULL, NULL, '57bf170fbaf716654c82480b370c8f8634e2d9fdaf6a9f52cef2e2bc2e218efb'),
  ('ur.jalandhry', 70, 7, 5382, 'اور ہماری نظر میں نزدیک', NULL, NULL, '9880598d1d43186eb786d368b4cfb1e17f011fd24acbfa3dfae96c345b8b20dc'),
  ('ur.jalandhry', 70, 8, 5383, 'جس دن آسمان ایسا ہو جائے گا جیسے پگھلا ہوا تانبا', NULL, NULL, 'bbbff0ba5f396b681c92ecddef9d5a9268129e7a70e046a838baded3ce69866a'),
  ('ur.jalandhry', 70, 9, 5384, 'اور پہاڑ (ایسے) جیسے (دھنکی ہوئی) رنگین اون', NULL, NULL, 'da19a491a1e1adad2001b06f11a5748ef38d642f4ea84c839f959dcb93e52420'),
  ('ur.jalandhry', 70, 10, 5385, 'اور کوئی دوست کسی دوست کا پرسان نہ ہوگا', NULL, NULL, 'a7b9c343d5692a66c6dd1bbcf23374dba6f97e99ac0180e4418daaf5e92a7e9d'),
  ('ur.jalandhry', 70, 11, 5386, 'ایک دوسرے کو سامنے دیکھ رہے ہوں گے (اس روز) گنہگار خواہش کرے گا کہ کسی طرح اس دن کے عذاب کے بدلے میں (سب کچھ) دے دے یعنی اپنے بیٹے', NULL, NULL, '55a703e67bd646af15da07e0da3265f439eb2a987b9ac6bb82c96a05027b2e84'),
  ('ur.jalandhry', 70, 12, 5387, 'اور اپنی بیوی اور اپنے بھائی', NULL, NULL, '0f6c2a203a74b5b9158e5ad37f40101573c356feaa81ea03e0fdcf87bc99df73'),
  ('ur.jalandhry', 70, 13, 5388, 'اور اپنا خاندان جس میں وہ رہتا تھا', NULL, NULL, '8dcd938661c95a35486195841142cf57f1eabb2b0b8d028a8e2c80af47ae5cbf'),
  ('ur.jalandhry', 70, 14, 5389, 'اور جتنے آدمی زمین میں ہیں (غرض) سب (کچھ دے دے) اور اپنے تئیں عذاب سے چھڑا لے', NULL, NULL, '436a022dd3d1d0b7ae9fcec20ad0a9fc4bbfbb3facf446d4655d49207d0c3c37'),
  ('ur.jalandhry', 70, 15, 5390, '(لیکن) ایسا ہرگز نہیں ہوگا وہ بھڑکتی ہوئی آگ ہے', NULL, NULL, '562fa225582582b763b2323a3872c0e1a3bc425f954b3afd192468e8677c0220'),
  ('ur.jalandhry', 70, 16, 5391, 'کھال ادھیڑ ڈالنے والی', NULL, NULL, 'b5ff3d954409a850b5f62cb86c97460a485250338167a4027596c57061a6f209'),
  ('ur.jalandhry', 70, 17, 5392, 'ان لوگوں کو اپنی طرف بلائے گی جنہوں نے (دین حق سے) اعراض کیا', NULL, NULL, '7f077aa4cb2be2736fe367153ece6ce0fc649e608181d58b29dded4dd10b1baf'),
  ('ur.jalandhry', 70, 18, 5393, 'اور (مال) جمع کیا اور بند کر رکھا', NULL, NULL, 'ce0710c769c6e15b6f64b0f84b7b09010d7e44762b9e369118583fe782919ab0'),
  ('ur.jalandhry', 70, 19, 5394, 'کچھ شک نہیں کہ انسان کم حوصلہ پیدا ہوا ہے', NULL, NULL, 'faca68d081faf41d038062455b99bda72c6b1704423fec49c490767dd5d3f639'),
  ('ur.jalandhry', 70, 20, 5395, 'جب اسے تکلیف پہنچتی ہے تو گھبرا اٹھتا ہے', NULL, NULL, '981a8e0dbd9d09bc6a00c6fcfa5d77f1ef2b3f34837143173a4e4ed56a0b2838'),
  ('ur.jalandhry', 70, 21, 5396, 'اور جب آسائش حاصل ہوتی ہے تو بخیل بن جاتا ہے', NULL, NULL, 'eb729b2e89ec6b75caeeec2a51429bcb76094b1b11539f7948e84bff6fa27751'),
  ('ur.jalandhry', 70, 22, 5397, 'مگر نماز گزار', NULL, NULL, 'f376ee429dce8af6bd2ccf46f38e9ff3f3f085494e50857a566e2bdd66a9eba5'),
  ('ur.jalandhry', 70, 23, 5398, 'جو نماز کا التزام رکھتے (اور بلاناغہ پڑھتے) ہیں', NULL, NULL, '2cda880a19af209ed639ad51acf489a109a23e5fa600f4cfa51b768016bc1e11'),
  ('ur.jalandhry', 70, 24, 5399, 'اور جن کے مال میں حصہ مقرر ہے', NULL, NULL, '492a1c2c059d615e86707a0fd816b7b3c8519be03537e33db5b615ad4f220424'),
  ('ur.jalandhry', 70, 25, 5400, '(یعنی) مانگنے والے کا۔ اور نہ مانگے والے والا کا', NULL, NULL, 'b587cb3057d509c4b8e6c77bc122c1c38e2272c035ec250ef55aaf272ddf76f8')
