INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 70, 26, 5401, 'اور جو روز جزا کو سچ سمجھتے ہیں', NULL, NULL, '0e5e7d7e770676e56e2064d944fc60e09cd93876f855575a958c532244ce8019'),
  ('ur.jalandhry', 70, 27, 5402, 'اور جو اپنے پروردگار کے عذاب سے خوف رکھتے ہیں', NULL, NULL, '7875ac98f9f0c29ad4cde188cbc86b9898b57acd18deff980eba7c5e150bb4cd'),
  ('ur.jalandhry', 70, 28, 5403, 'بےشک ان کے پروردگار کا عذاب ہے ہی ایسا کہ اس سے بےخوف نہ ہوا جائے', NULL, NULL, '5bfa430987149ee0e7ae600debf79113dfd576eddd88002b47fa8c44fde09fd7'),
  ('ur.jalandhry', 70, 29, 5404, 'اور جو اپنی شرمگاہوں کی حفاظت کرتے ہیں', NULL, NULL, 'f9d8d481ebd5be1413c3123fea4b571c0214690f4701e70816a7fcf5851b16bf'),
  ('ur.jalandhry', 70, 30, 5405, 'مگر اپنی بیویوں یا لونڈیوں سے کہ (ان کے پاس جانے پر) انہیں کچھ ملامت نہیں', NULL, NULL, '4a9286414ca231b596fe730eac4599c36d535a539c46502f8140684ef55e5190'),
  ('ur.jalandhry', 70, 31, 5406, 'اور جو لوگ ان کے سوا اور کے خواستگار ہوں وہ حد سے نکل جانے والے ہیں', NULL, NULL, '54e0d83ed7c2f66fca0cfa84906325dc2896885443ff48b78c5f3b3a9d1d6ef8'),
  ('ur.jalandhry', 70, 32, 5407, 'اور جو اپنی امانتوں اور اقراروں کا پاس کرتے ہیں', NULL, NULL, 'b0690b0cc82723194154f183639cddbf283a587cb8d0e670b2df6643ebd5dd05'),
  ('ur.jalandhry', 70, 33, 5408, 'اور جو اپنی شہادتوں پر قائم رہتے ہیں', NULL, NULL, '3b727405c4d5f077a6c5f871f05c97887613686ee8d528e1c253d925a1636356'),
  ('ur.jalandhry', 70, 34, 5409, 'اور جو اپنی نماز کی خبر رکھتے ہیں', NULL, NULL, 'acdb78ef9a95b0559062ce524154a88c0ac2d735a643dda7c7e7486bdc014fe7'),
  ('ur.jalandhry', 70, 35, 5410, 'یہی لوگ باغہائے بہشت میں عزت واکرام سے ہوں گے', NULL, NULL, '879318b938f2eba09c7b0094c2af2b39218e3a7a0c0de74dee1a4a8f78a72f06'),
  ('ur.jalandhry', 70, 36, 5411, 'تو ان کافروں کو کیا ہوا ہے کہ تمہاری طرف دوڑے چلے آتے ہیں', NULL, NULL, '9fc5e22aecbe17b920eb418eea2dd6fd5b7cecd81cbad41e37475af098e2e31f'),
  ('ur.jalandhry', 70, 37, 5412, 'اور) دائیں بائیں سے گروہ گروہ ہو کر (جمع ہوتے جاتے ہیں)', NULL, NULL, 'bb85b25ed071c7452d8936f42e4b536c5565edea0adde147f74c47f44debe3ca'),
  ('ur.jalandhry', 70, 38, 5413, 'کیا ان میں سے ہر شخص یہ توقع رکھتا ہے کہ نعمت کے باغ میں داخل کیا جائے گا', NULL, NULL, 'c3d03a662d711e832c903a9a8cf800321bbe984de2f4b214ef8f8d26cdcd8ce2'),
  ('ur.jalandhry', 70, 39, 5414, 'ہرگز نہیں۔ ہم نے ان کو اس چیز سے پیدا کیا ہے جسے وہ جانتے ہیں', NULL, NULL, 'b609894ef6027aff1da752e8c8f4f44940625947d8446733120559d0aec526f6'),
  ('ur.jalandhry', 70, 40, 5415, 'ہمیں مشرقوں اور مغربوں کے مالک کی قسم کہ ہم طاقت رکھتے ہیں', NULL, NULL, '6d508d04a8025afc4ca949c1ea3e4aa0919f3b21b8d682b254fc47a09028ed85'),
  ('ur.jalandhry', 70, 41, 5416, '(یعنی) اس بات پر (قادر ہیں) کہ ان سے بہتر لوگ بدل لائیں اور ہم عاجز نہیں ہیں', NULL, NULL, '72818e231f99533c9125553194c7dddcf7982336978bcc11f6e45e3a304146a1'),
  ('ur.jalandhry', 70, 42, 5417, 'تو (اے پیغمبر) ان کو باطل میں پڑے رہنے اور کھیل لینے دو یہاں تک کہ جس دن کا ان سے وعدہ کیا جاتا ہے وہ ان کے سامنے آ موجود ہو', NULL, NULL, '22a3ebba4e930afeecf1e1dee91145edf8e25916699ad4351d0c1fdcfe9580f8'),
  ('ur.jalandhry', 70, 43, 5418, 'اس دن یہ قبر سے نکل کر (اس طرح) دوڑیں گے جیسے (شکاری) شکار کے جال کی طرف دوڑتے ہیں', NULL, NULL, '903b1f7bf218ebf58528e611b1a308aeedfe6dafca1eaa8be0575951badf08e7'),
  ('ur.jalandhry', 70, 44, 5419, 'ان کی آنکھیں جھک رہی ہوں گی اور ذلت ان پر چھا رہی ہوگی۔ یہی وہ دن ہے جس کا ان سے وعدہ کیا جاتا تھا', NULL, NULL, '0a9767c81da173144150fe1c0b46978018a63970f41740eb29d0aa85c26ffd3d'),
  ('ur.jalandhry', 71, 1, 5420, 'ہم نے نوحؑ کو ان کی قوم کی طرف بھیجا کہ پیشتر اس کے کہ ان پر درد دینے والا عذاب واقع ہو اپنی قوم کو ہدایت کردو', NULL, NULL, '3e52e8711e0d8c4394a40615f4c1f4b442de9196caa75242097e9063175631d7'),
  ('ur.jalandhry', 71, 2, 5421, 'انہوں نے کہا کہ اے قوم! میں تم کو کھلے طور پر نصیحت کرتا ہوں', NULL, NULL, '619750eea380835df7c466e3a88dfa1bfabc4f766999ce3ced5f1e893717c670'),
  ('ur.jalandhry', 71, 3, 5422, 'کہ خدا کی عبات کرو اور اس سے ڈرو اور میرا کہا مانو', NULL, NULL, '2bc803ad6cca90a98947f5c54d1009613211a0280a3dc195ac4f90b4d6442b0d'),
  ('ur.jalandhry', 71, 4, 5423, 'وہ تمہارے گناہ بخش دے گا اور (موت کے) وقت مقررہ تک تم کو مہلت عطا کرے گا۔ جب خدا کا مقرر کیا ہوگا وقت آجاتا ہے تو تاخیر نہیں ہوتی۔ کاش تم جانتے ہوتے', NULL, NULL, '551d6a75d3440cc07aefd5286956a140ec3aca83bd49d9af63b5db26c5420a68'),
  ('ur.jalandhry', 71, 5, 5424, 'جب لوگوں نے نہ مانا تو (نوحؑ نے) خدا سے عرض کی کہ پروردگار میں اپنی قوم کو رات دن بلاتا رہا', NULL, NULL, '8c96eec85dd61a9f5cd6edffe8d909699375e5491623934fe3a71cb1df27e101'),
  ('ur.jalandhry', 71, 6, 5425, 'لیکن میرے بلانے سے وہ اور زیادہ گزیر کرتے رہے', NULL, NULL, '03ed566e6a5b2ba7cd67117e1db0d7849060b3c658dc131eb9e7538dc52ed1eb'),
