  ('ur.jalandhry', 73, 2, 5477, 'رات کو قیام کیا کرو مگر تھوڑی سی رات', NULL, NULL, 'e3bb55073b63e4f779cffe090cbe98be43bfbb38b0a277850028b1988080987d'),
  ('ur.jalandhry', 73, 3, 5478, '(قیام) آدھی رات (کیا کرو)', NULL, NULL, 'fb40ddb8669b3931af5db3d3d6b767ce16d371f1243c9fd6c0074225d64061d5'),
  ('ur.jalandhry', 73, 4, 5479, 'یا اس سے کچھ کم یا کچھ زیادہ اور قرآن کو ٹھہر ٹھہر کر پڑھا کرو', NULL, NULL, 'ab16d923ee5c81e553da5db48f7d84d5501f8a5f9b2f07b1b7892db66d9cac1b'),
  ('ur.jalandhry', 73, 5, 5480, 'ہم عنقریب تم پر ایک بھاری فرمان نازل کریں گے', NULL, NULL, '6f7e9669e0c2537ac024c71b272cd9764ae85d5150f21d527c72d6c405bc5f6e'),
  ('ur.jalandhry', 73, 6, 5481, 'کچھ شک نہیں کہ رات کا اٹھنا (نفس بہیمی) کو سخت پامال کرتا ہے اور اس وقت ذکر بھی خوب درست ہوتا ہے', NULL, NULL, 'f7290f2edd8c6cbcbfdcf8c11bdc98ca7666c7666a121122e84f5732fb2248eb'),
  ('ur.jalandhry', 73, 7, 5482, 'دن کے وقت تو تمہیں اور بہت سے شغل ہوتے ہیں', NULL, NULL, 'd85ddf1ee22b2e512b078a0a0b74b1d26f3acfaea5ce88ba89b7f75d23ed514b'),
  ('ur.jalandhry', 73, 8, 5483, 'تو اپنے پروردگار کے نام کا ذکر کرو اور ہر طرف سے بےتعلق ہو کر اسی کی طرف متوجہ ہوجاؤ', NULL, NULL, '697fd48780f758e29846ffafc94c584d3a6c9a00d62c57c5c963e598912adda0'),
  ('ur.jalandhry', 73, 9, 5484, 'مشرق اور مغرب کا مالک (ہے اور) اس کے سوا کوئی معبود نہیں تو اسی کو اپنا کارساز بناؤ', NULL, NULL, 'ab03a50a668d24079757757caafa87bea91632a8fedc984326047780c7f0a09e'),
  ('ur.jalandhry', 73, 10, 5485, 'اور جو جو (دل آزار) باتیں یہ لوگ کہتے ہیں ان کو سہتے رہو اور اچھے طریق سے ان سے کنارہ کش رہو', NULL, NULL, 'ad12b8a940d4d64f459a3a857f1d8f142b826f860b1a26297bc86e6e9048ba51'),
  ('ur.jalandhry', 73, 11, 5486, 'اور مجھے ان جھٹلانے والوں سے جو دولتمند ہیں سمجھ لینے دو اور ان کو تھوڑی سی مہلت دے دو', NULL, NULL, 'b5853b1b13e3fb558e452312f81bf35f046d4c8dcdc5a0b3baa5167854ad6238'),
  ('ur.jalandhry', 73, 12, 5487, 'کچھ شک نہیں کہ ہمارے پاس بیڑیاں ہیں اور بھڑکتی ہوئی آگ ہے', NULL, NULL, 'a7738a6a2e34e22803752708f5d8c10fbff23b0256de8ff28bdec963cfe78796'),
  ('ur.jalandhry', 73, 13, 5488, 'اور گلوگیر کھانا ہے اور درد دینے والا عذاب (بھی) ہے', NULL, NULL, '20f4dcf1fe1c501621c3f3408124d1a85cf30be6ec1c8cd72a44e25ec95095eb'),
  ('ur.jalandhry', 73, 14, 5489, 'جس دن زمین اور پہاڑ کانپنے لگیں اور پہاڑ ایسے بھر بھرے (گویا) ریت کے ٹیلے ہوجائیں', NULL, NULL, 'f797112f47e68309745eb9604b5477716a297cfe80792aa78727e07aa991def3'),
  ('ur.jalandhry', 73, 15, 5490, '(اے اہل مکہ) جس طرح ہم نے فرعون کے پاس (موسیٰ کو) پیغمبر (بنا کر) بھیجا تھا (اسی طرح) تمہارے پاس بھی (محمدﷺ) رسول بھیجے ہیں جو تمہارے مقابلے میں گواہ ہوں گے', NULL, NULL, '5f78b3022d16e90b6b91dbb84ac84d040cf4a1bbb99f9a84d4098dfb4f3897ad'),
  ('ur.jalandhry', 73, 16, 5491, 'سو فرعون نے (ہمارے) پیغمبر کا کہا نہ مانا تو ہم نے اس کو بڑے وبال میں پکڑ لیا', NULL, NULL, '7225f2da6d80138875e28a1c109b88e49793c4f33150fe73277dacb3228c32d5'),
  ('ur.jalandhry', 73, 17, 5492, 'اگر تم بھی (ان پیغمبروں کو) نہ مانو گے تو اس دن سے کیونکر بچو گے جو بچّوں کو بوڑھا کر دے گا', NULL, NULL, '3fc8f6c5fccbc4cac0237370523627decbf7f4065bc3c4d2b2ff107ad662c3f4'),
  ('ur.jalandhry', 73, 18, 5493, '(اور) جس سے آسمان پھٹ جائے گا۔ یہ اس کا وعدہ (پورا) ہو کر رہے گا', NULL, NULL, '283b1f05ee7488b43da996898d6b3b703639baa5c73923eb2d8f751412829dea'),
  ('ur.jalandhry', 73, 19, 5494, 'یہ (قرآن) تو نصیحت ہے۔ سو جو چاہے اپنے پروردگار تک (پہنچنے کا) رستہ اختیار کرلے', NULL, NULL, 'dd604cbcb0caf84b7e6a9ade696acb6147d1eda37c35680ebe08d03950f464e1'),
  ('ur.jalandhry', 73, 20, 5495, 'تمہارا پروردگار خوب جانتا ہے کہ تم اور تمہارے ساتھ کے لوگ (کبھی) دو تہائی رات کے قریب اور (کبھی) آدھی رات اور (کبھی) تہائی رات قیام کیا کرتے ہو۔ اور خدا تو رات اور دن کا اندازہ رکھتا ہے۔ اس نے معلوم کیا کہ تم اس کو نباہ نہ سکو گے تو اس نے تم پر مہربانی کی۔ پس جتنا آسانی سے ہوسکے (اتنا) قرآن پڑھ لیا کرو۔ اس نے جانا کہ تم میں بعض بیمار بھی ہوتے ہیں اور بعض خدا کے فضل (یعنی معاش) کی تلاش میں ملک میں سفر کرتے ہیں اور بعض خدا کی راہ میں لڑتے ہیں۔ تو جتنا آسانی سے ہوسکے اتنا پڑھ لیا کرو۔ اور نماز پڑھتے رہو اور زکوٰة ادا کرتے رہو اور خدا کو نیک (اور خلوص نیت سے) قرض دیتے رہو۔ اور جو عمل نیک تم اپنے لئے آگے بھیجو گے اس کو خدا کے ہاں بہتر اور صلے میں بزرگ تر پاؤ گے۔ اور خدا سے بخشش مانگتے رہو۔ بےشک خدا بخشنے والا مہربان ہے', NULL, NULL, '73b1157f7e6ae73a928709871161c847138998a90dd03c99d4e9ad2cba25cea3'),
  ('ur.jalandhry', 74, 1, 5496, 'اے (محمدﷺ) جو کپڑا لپیٹے پڑے ہو', NULL, NULL, 'd5c330bbf0d85e9a67c6c92716492c74eeed55b18d077e57f025f5fc8af48b8a'),
  ('ur.jalandhry', 74, 2, 5497, 'اُٹھو اور ہدایت کرو', NULL, NULL, '177df164f28b5fc2126086fb8aa159469f0d2c84fc6239b82e37a09cc7303851'),
  ('ur.jalandhry', 74, 3, 5498, 'اور اپنے پروردگار کی بڑائی کرو', NULL, NULL, 'c1dd6ab38e70085605da1eeecf5fabdb4815bea8e83d2e0802c6ef68a95b407f'),
  ('ur.jalandhry', 74, 4, 5499, 'اور اپنے کپڑوں کو پاک رکھو', NULL, NULL, '7ddaa5ba892102ba4e889b135f381a30f6260ee8d855a65ec8cebe294bf6929c'),
  ('ur.jalandhry', 74, 5, 5500, 'اور ناپاکی سے دور رہو', NULL, NULL, 'bdff294f4cecae2f0609a8003b0db1f8d987bb0dcaca1c2418df3ca85b0bb97e')
