  ('ur.jalandhry', 74, 7, 5502, 'اور اپنے پروردگار کے لئے صبر کرو', NULL, NULL, 'f247b144959d4c2342d696d29a4db031f31cdfdfb03d6298a6e68f5a566f1ed1'),
  ('ur.jalandhry', 74, 8, 5503, 'جب صور پھونکا جائے گا', NULL, NULL, '74c29d9d70055ee4ea147bc876b72f7c293009d7a233fd77bddaf682b4e89429'),
  ('ur.jalandhry', 74, 9, 5504, 'وہ دن کا مشکل دن ہوگا', NULL, NULL, 'c8710b95406d45c5335a4d5f7e68a028712844adeb8f264ab04950a3da4d3042'),
  ('ur.jalandhry', 74, 10, 5505, '(یعنی) کافروں پر آسان نہ ہوگا', NULL, NULL, '85aa73dccb9c2f42da8cd48a78d8115af1b53a554b5899b2bc72a1a89882ddd5'),
  ('ur.jalandhry', 74, 11, 5506, 'ہمیں اس شخص سے سمجھ لینے دو جس کو ہم نے اکیلا پیدا کیا', NULL, NULL, '49025b860c746540c114b9f125970ed9d3c87a33a31ec348840ef33e6e45391c'),
  ('ur.jalandhry', 74, 12, 5507, 'اور مال کثیر دیا', NULL, NULL, '47de9d87c4edd048297672336171f361526648b2dcafb0d067770a4169e8792d'),
  ('ur.jalandhry', 74, 13, 5508, 'اور (ہر وقت اس کے پاس) حاضر رہنے والے بیٹے دیئے', NULL, NULL, '091314ee3be8eae4db35f77020ebfa4d05a2d5200837b2b94d73ac49ac72942b'),
  ('ur.jalandhry', 74, 14, 5509, 'اور ہر طرح کے سامان میں وسعت دی', NULL, NULL, 'd5e362a87458d4ba0acf0fc587211adb6b28edfb2be122f885bf5eba913e8f89'),
  ('ur.jalandhry', 74, 15, 5510, 'ابھی خواہش رکھتا ہے کہ اور زیادہ دیں', NULL, NULL, 'eb5e865d1fa8770b97045cfdc32d1f75e0f94d392d0e8f1bb09fcdc09c020d9a'),
  ('ur.jalandhry', 74, 16, 5511, 'ایسا ہرگز نہیں ہوگا۔ یہ ہماری آیتیں کا دشمن رہا ہے', NULL, NULL, 'c187b8d0c1028ce6acaaf84dd60bdfbde651adfcad444903ac4feb6e08cfe3f9'),
  ('ur.jalandhry', 74, 17, 5512, 'ہم اسے صعود پر چڑھائیں گے', NULL, NULL, 'd3b0e1dae1c696a6f60fb3e824eb3ae1b883b8f5c7ec174292df7479f0869e63'),
  ('ur.jalandhry', 74, 18, 5513, 'اس نے فکر کیا اور تجویز کی', NULL, NULL, '03decc77aac958015ba8a89a3c9ff0b133083dd6d7ffe61be64b4e4093bb25de'),
  ('ur.jalandhry', 74, 19, 5514, 'یہ مارا جائے اس نے کیسی تجویز کی', NULL, NULL, '5809389dba37699b360afb0946f576aad29a7f18fda5ea50dae2b016e1c1ca5f'),
  ('ur.jalandhry', 74, 20, 5515, 'پھر یہ مارا جائے اس نے کیسی تجویز کی', NULL, NULL, '00099e63588bbf5b4bf3014b9bbc6a155bc13bad20e12002a31b378d6e6a7880'),
  ('ur.jalandhry', 74, 21, 5516, 'پھر تامل کیا', NULL, NULL, '20fbff8b74ff5147ca5d0c67c608f64261053cfed504b9212a61892e3d8546d8'),
  ('ur.jalandhry', 74, 22, 5517, 'پھر تیوری چڑھائی اور منہ بگاڑ لیا', NULL, NULL, 'b84bfbb0c65c6e0be90d48036801f4b1445cb9f9591edc02d57b37130375bad1'),
  ('ur.jalandhry', 74, 23, 5518, 'پھر پشت پھیر کر چلا اور (قبول حق سے) غرور کیا', NULL, NULL, '5ecc0dc9aed6147475e448cc715747257331b2ff784ab3bbc8a5c47d5be11107'),
  ('ur.jalandhry', 74, 24, 5519, 'پھر کہنے لگا کہ یہ تو جادو ہے جو (اگلوں سے) منتقل ہوتا آیا ہے', NULL, NULL, 'd7c63e70df08774dad5027e74806f15e2c1c2eac51520ddc175839677c405ec6'),
  ('ur.jalandhry', 74, 25, 5520, '(پھر بولا) یہ (خدا کا کلام نہیں بلکہ) بشر کا کلام ہے', NULL, NULL, 'c8d0729ac1220e955a768d9016acd5c34bd9001826b2e37d05b37644fc40659b'),
  ('ur.jalandhry', 74, 26, 5521, 'ہم عنقریب اس کو سقر میں داخل کریں گے', NULL, NULL, '481ac05481270255ccec9f89ef635cd0d08c94f263e7ec0067d433a994d3ad4c'),
  ('ur.jalandhry', 74, 27, 5522, 'اور تم کیا سمجھے کہ سقر کیا ہے؟', NULL, NULL, '23ea2290feddea962184470104d053bbdb01dae3731b00ee809614450bcae5eb'),
  ('ur.jalandhry', 74, 28, 5523, '(وہ آگ ہے کہ) نہ باقی رکھے گی اور نہ چھوڑے گی', NULL, NULL, 'e90df2a1f3a16e1530edb8ad9d6d72eecb6306af49d02491ee864a09416a3709'),
  ('ur.jalandhry', 74, 29, 5524, 'اور بدن جھلس کر سیاہ کردے گی', NULL, NULL, 'c9da0397dc9968475a51fe7218b2e6ef624402d876882f31273ee426ee3a7b0b'),
  ('ur.jalandhry', 74, 30, 5525, 'اس پر اُنیس داروغہ ہیں', NULL, NULL, 'b24a1aa4e4ad55f2082f74d8be04146635499014c781eeffa7054b1cbf89923c'),
  ('ur.jalandhry', 74, 31, 5526, 'اور ہم نے دوزخ کے داروغہ فرشتے بنائے ہیں۔ اور ان کا شمار کافروں کی آزمائش کے لئے مقرر کیا ہے (اور) اس لئے کہ اہل کتاب یقین کریں اور مومنوں کا ایمان اور زیادہ ہو اور اہل کتاب اور مومن شک نہ لائیں۔ اور اس لئے کہ جن لوگوں کے دلوں میں (نفاق کا) مرض ہے اور (جو) کافر (ہیں) کہیں کہ اس مثال (کے بیان کرنے) سے خدا کا مقصد کیا ہے؟ اسی طرح خدا جس کو چاہتا ہے گمراہ کرتا ہے اور جس کو چاہتا ہے ہدایت کرتا ہے اور تمہارے پروردگار کے لشکروں کو اس کے سوا کوئی نہیں جانتا۔ اور یہ تو بنی آدم کے لئے نصیحت ہے', NULL, NULL, 'e8659a240464e97cbc707b3d05d429a4229b855403863436fe7cb9b50bb4598d'),
  ('ur.jalandhry', 74, 32, 5527, 'ہاں ہاں (ہمیں) چاند کی قسم', NULL, NULL, '849398791052bcf77baaddaed186ce524150807f95531b90ac3f214414503c7a'),
  ('ur.jalandhry', 74, 33, 5528, 'اور رات کی جب پیٹھ پھیرنے لگے', NULL, NULL, '094288709e093f919009657b98049830631ee1878a0316497ad4d4b1fe3d5aed'),
  ('ur.jalandhry', 74, 34, 5529, 'اور صبح کی جب روشن ہو', NULL, NULL, '7d99bfe28c4d81b112cbb08aa6f7f45185d2a01325ed6aad9061ce0f9a705b16'),
  ('ur.jalandhry', 74, 35, 5530, 'کہ وہ (آگ) ایک بہت بڑی (آفت) ہے', NULL, NULL, 'e122300a1a67e545119a23a151beb0e46f72724a5f49db380f1d4019cae54965'),
  ('ur.jalandhry', 74, 36, 5531, '(اور) بنی آدم کے لئے مؤجب خوف', NULL, NULL, '755e31da7aeecbd983476ade486f88bd0381e31d97047bed8f1cebecb047a073'),
  ('ur.jalandhry', 74, 37, 5532, 'جو تم میں سے آگے بڑھنا چاہے یا پیچھے رہنا چاہے', NULL, NULL, 'f172b8dfdebc59a57874da4b2c409245898a89c8f5a959048f2416ae402e2aba'),
  ('ur.jalandhry', 74, 38, 5533, 'ہر شخص اپنے اعمال کے بدلے گرو ہے', NULL, NULL, '7ac33fbca056689c3082258178abd83f32c2201e82eac8ab9ff73dfbe4c173f5'),
  ('ur.jalandhry', 74, 39, 5534, 'مگر داہنی طرف والے (نیک لوگ)', NULL, NULL, 'fecfc9d5afb5a6db68aa375079b627b416f67c48eaaf13fa8b35371c0f801ce7'),
  ('ur.jalandhry', 74, 40, 5535, '(کہ) وہ باغہائے بہشت میں (ہوں گے اور) پوچھتے ہوں گے', NULL, NULL, 'addcd6415ae65ac556e28004e07426b089f509854ea3e80e0b188cb7d8cf47f8'),
  ('ur.jalandhry', 74, 41, 5536, '(یعنی آگ میں جلنے والے) گنہگاروں سے', NULL, NULL, '36875f5686ecada8b06ef7a999c2f5a94f80c0ce3ff186c6e195f478e53a5b80'),
  ('ur.jalandhry', 74, 42, 5537, 'کہ تم دوزخ میں کیوں پڑے؟', NULL, NULL, '8a49187c7b265a69efaa0afe46fe2fbc8364d08bfd63aa08b8b25f04f91e050e'),
  ('ur.jalandhry', 74, 43, 5538, 'وہ جواب دیں گے کہ ہم نماز نہیں پڑھتے تھے', NULL, NULL, 'd508239593485bf04e14b2b03c9d0c646b822f94d23d72f97c3c6a5a74a1fb9f'),
  ('ur.jalandhry', 74, 44, 5539, 'اور نہ فقیروں کو کھانا کھلاتے تھے', NULL, NULL, '7e61d83dc46eaca53f674bb5f2c0591a72497917abeeb28c46095af04ade4e70'),
  ('ur.jalandhry', 74, 45, 5540, 'اور اہل باطل کے ساتھ مل کر (حق سے) انکار کرتے تھے', NULL, NULL, 'f89563016163c9965ec5920d3465f3b0d0785a85cc131abdd2e8a718d04cdee7'),
  ('ur.jalandhry', 74, 46, 5541, 'اور روز جزا کو جھٹلاتے تھے', NULL, NULL, '7c085dd2197bfcf6769ecf8dc2bc14f77bad4a22411bb3173705f296c8570789'),
  ('ur.jalandhry', 74, 47, 5542, 'یہاں تک کہ ہمیں موت آگئی', NULL, NULL, 'c66fb3fc1aad0d5b7c63bde1b73f59081a7e39ada6cc8348f32938839b822152'),
  ('ur.jalandhry', 74, 48, 5543, '(تو اس حال میں) سفارش کرنے والوں کی سفارش ان کے حق میں کچھ فائدہ نہ دے گی', NULL, NULL, '77398569808fed7c00a051890eb00a052db9fd836e5be6cd0e6f7ee03279faf9'),
  ('ur.jalandhry', 74, 49, 5544, 'ان کو کیا ہوا ہے کہ نصیحت سے روگرداں ہو رہے ہیں', NULL, NULL, '8c222015d91c9b0c1e8f6754e438777f8421c17c2246077aaacb9156c52b479b'),
  ('ur.jalandhry', 74, 50, 5545, 'گویا گدھے ہیں کہ بدک جاتے ہیں', NULL, NULL, 'af04b2053ce8a5650676b960331bf9ab15f3540a46f8d8ca34add75f35e305e6'),
  ('ur.jalandhry', 74, 51, 5546, '(یعنی) شیر سے ڈر کر بھاگ جاتے ہیں', NULL, NULL, '722dc7e8313ec3a2935e992321a454667b3d5181a8cea3569a4a593a8304baee'),
  ('ur.jalandhry', 74, 52, 5547, 'اصل یہ ہے کہ ان میں سے ہر شخص یہ چاہتا ہے کہ اس کے پاس کھلی ہوئی کتاب آئے', NULL, NULL, '8909cbede38d93da1c8e18a85e0d065e2a81604026d1dfc51dc4f6cdac810857'),
  ('ur.jalandhry', 74, 53, 5548, 'ایسا ہرگز نہیں ہوگا۔ حقیقت یہ ہے کہ ان کو آخرت کا خوف ہی نہیں', NULL, NULL, '90166f7e8ef0743bb5488ccebba41333039c32b601324eaafe1239bec61fbe19'),
  ('ur.jalandhry', 74, 54, 5549, 'کچھ شک نہیں کہ یہ نصیحت ہے', NULL, NULL, '0df570778955b74bf08ab41670cd3ebbfa5ac0eab75e8ea3deb27aed09cd99c1'),
  ('ur.jalandhry', 74, 55, 5550, 'تو جو چاہے اسے یاد رکھے', NULL, NULL, '24f3b525ff8c109c44ca6c9631092430efc5d1cb8184ebb03ed22927d4205ddf'),
  ('ur.jalandhry', 74, 56, 5551, 'اور یاد بھی تب ہی رکھیں گے جب خدا چاہے۔ وہی ڈرنے کے لائق اور بخشش کا مالک ہے', NULL, NULL, 'e4e625bef28e27e74791939cf5d57b390e81fb94569100d729dd557dd9c020f0'),
  ('ur.jalandhry', 75, 1, 5552, 'ہم کو روز قیامت کی قسم', NULL, NULL, '362b7f28694f2a929273830beec398d94192e80b1bfac5c95f632a9167b44ac2'),
  ('ur.jalandhry', 75, 2, 5553, 'اور نفس لوامہ کی (کہ سب لوگ اٹھا کر) کھڑے کئے جائیں گے', NULL, NULL, 'bd4aa4fe5b48e67d2b9fed35250176a17f4145a5b54aabaa1d2908495474f944'),
  ('ur.jalandhry', 75, 3, 5554, 'کیا انسان یہ خیال کرتا ہے کہ ہم اس کی (بکھری ہوئی) ہڈیاں اکٹھی نہیں کریں گے؟', NULL, NULL, '3857f3fb1b2eef5b22fc5d620ad51182af809842d22384af3bdf98d0c3d352a8'),
  ('ur.jalandhry', 75, 4, 5555, 'ضرور کریں گے (اور) ہم اس بات پر قادر ہیں کہ اس کی پور پور درست کردیں', NULL, NULL, 'e773efc1e8e17ec84dda5dac23b29b6deea6d19e0e146eb5775c4f7759347bf8'),
  ('ur.jalandhry', 75, 5, 5556, 'مگر انسان چاہتا ہے کہ آگے کو خود سری کرتا جائے', NULL, NULL, 'c2276875e234722ba68e72d4b37de7b85d9e1beb3a91e9a6917c91ea8ad0553c'),
  ('ur.jalandhry', 75, 6, 5557, 'پوچھتا ہے کہ قیامت کا دن کب ہوگا؟', NULL, NULL, '4a10be728a86eb1278503271b812b720f130e112d49e4ee96f597a5aa24a8451'),
  ('ur.jalandhry', 75, 7, 5558, 'جب آنکھیں چندھیا جائیں', NULL, NULL, '1d2ec4e5357c9bb6f5d6377625f49e319eb081d8d13edaca092b0f233b2185c1'),
  ('ur.jalandhry', 75, 8, 5559, 'اور چاند گہنا جائے', NULL, NULL, '7df1a8073e09b9bf45b33a003682662bc534b9b53ece145d67247cf975a98584'),
  ('ur.jalandhry', 75, 9, 5560, 'اور سورج اور چاند جمع کردیئے جائیں', NULL, NULL, 'e735644d5e77b02d925eba3bacacce2afa5625439e3622b19b9154c73b638b40'),
  ('ur.jalandhry', 75, 10, 5561, 'اس دن انسان کہے گا کہ (اب) کہاں بھاگ جاؤں؟', NULL, NULL, 'd661b2e2f825846347cca7398433afcefa4b11095e5255cd52ad816c32e0655b'),
  ('ur.jalandhry', 75, 11, 5562, 'بےشک کہیں پناہ نہیں', NULL, NULL, '8469da350216fb3f916c09f38c75c43d52763d10c7a677f74048a2c0307d518e'),
  ('ur.jalandhry', 75, 12, 5563, 'اس روز پروردگار ہی کے پاس ٹھکانا ہے', NULL, NULL, '6c95acd2961d2303041a47bb8842770e73cdb94742efe13debe5e13a09ba4dd0'),
  ('ur.jalandhry', 75, 13, 5564, 'اس دن انسان کو جو (عمل) اس نے آگے بھیجے اور پیچھے چھوڑے ہوں گے سب بتا دیئے جائیں گے', NULL, NULL, '7bde78616a2a4224f939e9c501fb7d62dd30a42038487595d18b4350a962fbcd'),
  ('ur.jalandhry', 75, 14, 5565, 'بلکہ انسان آپ اپنا گواہ ہے', NULL, NULL, 'd501b9c3ea7661de43edd8b974790b9ea8a7043ead5645b2a3bca706c4ba66c3'),
  ('ur.jalandhry', 75, 15, 5566, 'اگرچہ عذر ومعذرت کرتا رہے', NULL, NULL, 'f9f61a124f4bcf34faa18b7d17a52fb407368623d4101b7aef721c13d74c2747'),
  ('ur.jalandhry', 75, 16, 5567, 'اور (اے محمدﷺ) وحی کے پڑھنے کے لئے اپنی زبان نہ چلایا کرو کہ اس کو جلد یاد کرلو', NULL, NULL, '26b5906e329e84e8f57d37d543d1f1839ffb966f75516022058bc39e09bfecb9'),
  ('ur.jalandhry', 75, 17, 5568, 'اس کا جمع کرنا اور پڑھانا ہمارے ذمے ہے', NULL, NULL, '7d392cd27df2d8fc144c5ae1b0b934d3022e2add7a96f01912ce85a42f969250'),
  ('ur.jalandhry', 75, 18, 5569, 'جب ہم وحی پڑھا کریں تو تم (اس کو سنا کرو اور) پھر اسی طرح پڑھا کرو', NULL, NULL, '224126e4f3e5f76816a7d0266228ecb55af4eb02ffa8c2e71a5b51f051d852a2'),
  ('ur.jalandhry', 75, 19, 5570, 'پھر اس (کے معانی) کا بیان بھی ہمارے ذمے ہے', NULL, NULL, '417cb03ca01393a730d5d4e38549117f09dfb3939a8620f781054da41fbd7c73'),
  ('ur.jalandhry', 75, 20, 5571, 'مگر (لوگو) تم دنیا کو دوست رکھتے ہو', NULL, NULL, 'a65bfdea0ca6072d6058c13fc5732731a1ef83e2d5f0d52bfa7de3e62d55a35f'),
  ('ur.jalandhry', 75, 21, 5572, 'اور آخرت کو ترک کئے دیتے ہو', NULL, NULL, '37cfa1ff0087aa2d9261e32240775fc3a46dee4f8af121edae6168742ecb259b'),
  ('ur.jalandhry', 75, 22, 5573, 'اس روز بہت سے منہ رونق دار ہوں گے', NULL, NULL, 'd8a8c1fe77f7322c7332049b3fd5dda2f015ed48ed586996dcd5d30f251ee771'),
  ('ur.jalandhry', 75, 23, 5574, 'اور) اپنے پروردگار کے محو دیدار ہوں گے', NULL, NULL, '5ec1fb92558417962f15aa1b12d8e759be4a828208f0dc0a2bd942226dca7f09'),
  ('ur.jalandhry', 75, 24, 5575, 'اور بہت سے منہ اس دن اداس ہوں گے', NULL, NULL, '8b55ebd86f5105aeb167b269cd2e31c61d14bfd28fad020f4a3b0fdfcd0ea219'),
  ('ur.jalandhry', 75, 25, 5576, 'خیال کریں گے کہ ان پر مصیبت واقع ہونے کو ہے', NULL, NULL, '02b4fe00c8f21bdf5c92711cfe0b4b4551dedfe0496b0d96c89b0039e4918c6f'),
  ('ur.jalandhry', 75, 26, 5577, 'دیکھو جب جان گلے تک پہنچ جائے', NULL, NULL, 'ae5d60210e3a151b429ffaf5709425058f8b345034e86df9cb8b06d4ceaea83c'),
  ('ur.jalandhry', 75, 27, 5578, 'اور لوگ کہنے لگیں (اس وقت) کون جھاڑ پھونک کرنے والا ہے', NULL, NULL, '3343c9b4cdfdaa810e450faddb3db0274b0a1bf34e03b0f32f59f70c9c68b7ca'),
  ('ur.jalandhry', 75, 28, 5579, 'اور اس (جان بلب) نے سمجھا کہ اب سب سے جدائی ہے', NULL, NULL, '5ebff2c4c799825ebcf4739c49e7fad936da0a6a1785239c2d8e73748fc1b9db'),
  ('ur.jalandhry', 75, 29, 5580, 'اور پنڈلی سے پنڈلی لپٹ جائے', NULL, NULL, 'c43e8153ed77726bb5d1dd763494a0f7515915f761fd495f14f1e845cab634de'),
  ('ur.jalandhry', 75, 30, 5581, 'اس دن تجھ کو اپنے پروردگار کی طرف چلنا ہے', NULL, NULL, '4bdc14f5e52921282e9e9fcb068eedffc75033a91e749782143cac157760bfe2'),
  ('ur.jalandhry', 75, 31, 5582, 'تو اس (ناعاقبت) اندیش نے نہ تو (کلام خدا) کی تصدیق کی نہ نماز پڑھی', NULL, NULL, '2c3a81d9b517ee1a5f7e4d54aee826f1b301139a25333c438cfaf10f805cf521'),
  ('ur.jalandhry', 75, 32, 5583, 'بلکہ جھٹلایا اور منہ پھیر لیا', NULL, NULL, '1d4d6c202ef7e82d9da0caba7682dbc300874ac00c3fbd18913b2a57d8e87a42'),
  ('ur.jalandhry', 75, 33, 5584, 'پھر اپنے گھر والوں کے پاس اکڑتا ہوا چل دیا', NULL, NULL, 'f2985b7bc0c25c2cb9bdf4389ec2f4b2c2465224d6f109e9d4b301f216143dd0'),
  ('ur.jalandhry', 75, 34, 5585, 'افسوس ہے تجھ پر پھر افسوس ہے', NULL, NULL, 'e44d9105492dda08285cb8049e23245bdb8c6683ac662c4686eabdabe35532b9'),
  ('ur.jalandhry', 75, 35, 5586, 'پھر افسوس ہے تجھ پر پھر افسوس ہے', NULL, NULL, '6b2b0b52b4c39aea8d49a0c50ab0141951324ca99a9e2ed8e657fc6069f7e4aa'),
  ('ur.jalandhry', 75, 36, 5587, 'کیا انسان خیال کرتا ہے کہ یوں ہی چھوڑ دیا جائے گا؟', NULL, NULL, '483ffdf90f1e0fdb6f6adecf08b33296e76eb2815be3a66abda0b0ef2d389200'),
  ('ur.jalandhry', 75, 37, 5588, 'کیا وہ منی کا جو رحم میں ڈالی جاتی ہے ایک قطرہ نہ تھا؟', NULL, NULL, '2ae24b570fcd5899a4e4f316ca39d6a9094cfad83befb02e0219c34aa2f862f4'),
  ('ur.jalandhry', 75, 38, 5589, 'پھر لوتھڑا ہوا پھر (خدا نے) اس کو بنایا پھر (اس کے اعضا کو) درست کیا', NULL, NULL, '80ff5d7487010afd0602b00ead46e10f0abe36779489572505d31bb7034bbf0f'),
  ('ur.jalandhry', 75, 39, 5590, 'پھر اس کی دو قسمیں بنائیں (ایک) مرد اور (ایک) عورت', NULL, NULL, 'b3544c63f4ea4c48988b4c5cbbbda46e97d4eef858b6a785886fe4e1efa51021'),
  ('ur.jalandhry', 75, 40, 5591, 'کیا اس خالق کو اس بات پر قدرت نہیں کہ مردوں کو جلا اُٹھائے؟', NULL, NULL, '91ffe987dd115e98d376243fe4e04f3b37466f6b02067146de15904c0ff222ef'),
  ('ur.jalandhry', 76, 1, 5592, 'بےشک انسان پر زمانے میں ایک ایسا وقت بھی آچکا ہے کہ وہ کوئی چیز قابل ذکر نہ تھی', NULL, NULL, '249d67d1a653b6da6e6d9ced72b8f8274c3020f2003e1a5acce153f30051b211'),
  ('ur.jalandhry', 76, 2, 5593, 'ہم نے انسان کو نطفہٴ مخلوط سے پیدا کیا تاکہ اسے آزمائیں تو ہم نے اس کو سنتا دیکھتا بنایا', NULL, NULL, 'e0bfe730b3ff46db44a2888370f47644fefa1f4883aaa53a3632a544b48c5621'),
  ('ur.jalandhry', 76, 3, 5594, '(اور) اسے رستہ بھی دکھا دیا۔ (اب) وہ خواہ شکرگزار ہو خواہ ناشکرا', NULL, NULL, 'f67d65d680867fcbc030c1da720e3fe72396d0db182a1f18054a3f10c8fb25d6'),
  ('ur.jalandhry', 76, 4, 5595, 'ہم نے کافروں کے لئے زنجیر اور طوق اور دہکتی آگ تیار کر رکھی ہے', NULL, NULL, 'c1f55099166ebd5389eaedd2748fc954a4173e78f828f7fdee8632fb7cec4652'),
  ('ur.jalandhry', 76, 5, 5596, 'جو نیکو کار ہیں اور وہ ایسی شراب نوش جان کریں گے جس میں کافور کی آمیزش ہوگی', NULL, NULL, '7cdd4491c9e3fdc165f9c5a04b9f58ea967019a3a1cb5231dd218e743980e7ae'),
  ('ur.jalandhry', 76, 6, 5597, 'یہ ایک چشمہ ہے جس میں سے خدا کے بندے پئیں گے اور اس میں سے (چھوٹی چھوٹی) نہریں نکالیں گے', NULL, NULL, 'b63ab922b72a17157ec5a6c0c8f67e6cb27906d7f1c2be57e009a55335dbd251'),
  ('ur.jalandhry', 76, 7, 5598, 'یہ لوگ نذریں پوری کرتے ہیں اور اس دن سے جس کی سختی پھیل رہی ہوگی خوف رکھتے ہیں', NULL, NULL, 'f5a6ac10a98bf6fb693a59112d31aa50014026c7818bf4d39f8d00a88086e053'),
  ('ur.jalandhry', 76, 8, 5599, 'اور باوجود یہ کہ ان کو خود طعام کی خواہش (اور حاجت) ہے فقیروں اور یتیموں اور قیدیوں کو کھلاتے ہیں', NULL, NULL, 'ec2374ca6fee1af4fe75680a6e192b4225ed4634cc670b83ae597f5fa421072a'),
  ('ur.jalandhry', 76, 9, 5600, '(اور کہتے ہیں کہ) ہم تم کو خالص خدا کے لئے کھلاتے ہیں۔ نہ تم سے عوض کے خواستگار ہیں نہ شکرگزاری کے (طلبگار)', NULL, NULL, 'a076a243fe1fad9b435f8cbdcfec2efc83a735ad546797ca51aaeba6d7e3c62b')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
    ayah_id = EXCLUDED.ayah_id,
