INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 76, 10, 5601, 'ہم کو اپنے پروردگار سے اس دن کا ڈر لگتا ہے (جو چہروں کو) کریہہ المنظر اور (دلوں کو) سخت (مضطر کر دینے والا) ہے', NULL, NULL, 'b718a58667f5f79ebd8d0c6a0a00856538be1fd6ad324333bcc02dc762d5e7a0'),
  ('ur.jalandhry', 76, 11, 5602, 'تو خدا ان کو اس دن کی سختی سے بچالے گا اور تازگی اور خوش دلی عنایت فرمائے گا', NULL, NULL, '87f24bb581a12b3ea761030bc0ad131b0729a7b308dcfd1ada1064ef942b1988'),
  ('ur.jalandhry', 76, 12, 5603, 'اور ان کے صبر کے بدلے ان کو بہشت (کے باغات) اور ریشم (کے ملبوسات) عطا کرے گا', NULL, NULL, 'c034605eead9527e7f7f79bacf4344c307ca013a1be8ce8cd6fae85f449172b9'),
  ('ur.jalandhry', 76, 13, 5604, 'ان میں وہ تختوں پر تکیے لگائے بیٹھے ہوں گے۔ وہاں نہ دھوپ (کی حدت) دیکھیں گے نہ سردی کی شدت', NULL, NULL, '2ba98d213b0eba9fcbaca2babc59161c078feb1d1ccf74b3fcfbf60bcf200912'),
  ('ur.jalandhry', 76, 14, 5605, 'ان سے (ثمردار شاخیں اور) ان کے سائے قریب ہوں گے اور میوؤں کے گچھے جھکے ہوئے لٹک رہے ہوں گے', NULL, NULL, 'a8e55407f9c4be3975f52480f36d725f8f58e9a69f150ae50bb4fb5d8c3a9013'),
  ('ur.jalandhry', 76, 15, 5606, 'خدام) چاندی کے باسن لئے ہوئے ان کے اردگرد پھریں گے اور شیشے کے (نہایت شفاف) گلاس', NULL, NULL, '9747f173cbcad6a8b69aa48a74945bec3bad3ab929a748ecbcb3b2ac01d17438'),
  ('ur.jalandhry', 76, 16, 5607, 'اور شیشے بھی چاندی کے جو ٹھیک اندازے کے مطابق بنائے گئے ہیں', NULL, NULL, 'a0b9cf67d1e05da047f9038bb35292bea9aad7033c943d4d728ddee75c7dfe66'),
  ('ur.jalandhry', 76, 17, 5608, 'اور وہاں ان کو ایسی شراب (بھی) پلائی جائے گی جس میں سونٹھ کی آمیزش ہوگی', NULL, NULL, '29a4ab204ef635a98f509461584ab837d7f2016ebd001e7bd0e9e6051503312f'),
