  ('ur.jalandhry', 78, 9, 5681, 'اور نیند کو تمہارے لیے (موجب) آرام بنایا', NULL, NULL, '423e06f1dd8e88e6d0fe6c7bb44ee6fb07690bc0cbfdf9d5467eb93e1c946606'),
  ('ur.jalandhry', 78, 10, 5682, 'اور رات کو پردہ مقرر کیا', NULL, NULL, '1b05f570687d818d8026886c0e04a3472cafe154e567e8841412825536a33c47'),
  ('ur.jalandhry', 78, 11, 5683, 'اور دن کو معاش (کا وقت) قرار دیا', NULL, NULL, '9afb65ca268047fa70f9b0cb4eb55a0c1c51214247c5b84c1a93b38becadf8d9'),
  ('ur.jalandhry', 78, 12, 5684, 'اور تمہارے اوپر سات مضبوط (آسمان) بنائے', NULL, NULL, 'dbe9029451a721abf894e932c03ec0297034ee5273919e0f1f2d7b4a2eb3494c'),
  ('ur.jalandhry', 78, 13, 5685, 'اور (آفتاب کا) روشن چراغ بنایا', NULL, NULL, 'e6cc9581fd12222dd4c926650c0c1aa7631482e4f9f3cf992e1b928fde72b3f2'),
  ('ur.jalandhry', 78, 14, 5686, 'اور نچڑتے بادلوں سے موسلا دھار مینہ برسایا', NULL, NULL, 'ac7cad13179dcb5a0597d35070149f37b63e4fe48bf3bafb1bbeee536369f4a6'),
  ('ur.jalandhry', 78, 15, 5687, 'تاکہ اس سے اناج اور سبزہ پیدا کریں', NULL, NULL, '92bc2499f26a9785f40135d7be1190d3462faa7c84aaac8dd6a1bc64e2c0283a'),
  ('ur.jalandhry', 78, 16, 5688, 'اور گھنے گھنے باغ', NULL, NULL, 'a17ed09204be2572e136268ad3d44ab1231950828711fcbab98f53d07c4b0e89'),
  ('ur.jalandhry', 78, 17, 5689, 'بےشک فیصلہ کا دن مقرر ہے', NULL, NULL, '8e3477cbca6590926580a46ae28403080fe9f34ad5f0080688cc07a09eac19ee'),
  ('ur.jalandhry', 78, 18, 5690, 'جس دن صور پھونکا جائے گا تو تم لوگ غٹ کے غٹ آ موجود ہو گے', NULL, NULL, '91d62909d1db91c720a8b5d181abea6f65a50adee162fcba73fe597811083a1d'),
  ('ur.jalandhry', 78, 19, 5691, 'اور آسمان کھولا جائے گا تو (اس میں) دروازے ہو جائیں گے', NULL, NULL, '9b681b2fdd5b360b4ded355f06654f455b9ba9bfe9dbfaa4fae650cdd32ef0f1'),
  ('ur.jalandhry', 78, 20, 5692, 'اور پہاڑ چلائے جائیں گے تو وہ ریت ہو کر رہ جائیں گے', NULL, NULL, 'f0a6cc17d8bbc2f88089ee36f3c397ea9a4e29eafd8b68156c116240d924ee3b'),
  ('ur.jalandhry', 78, 21, 5693, 'بےشک دوزخ گھات میں ہے', NULL, NULL, 'cf35edf60260e26f8ae31357cacde9a326ef0f4b7b4e43034a5ff7ba1260f0af'),
  ('ur.jalandhry', 78, 22, 5694, '(یعنی) سرکشوں کا وہی ٹھکانہ ہے', NULL, NULL, 'b9811ca36bed637a6da6e7c5f8c1cfc8d33ae6848ac8844fc6c715c7fbd2b92b'),
  ('ur.jalandhry', 78, 23, 5695, 'اس میں وہ مدتوں پڑے رہیں گے', NULL, NULL, '3b5d99f7cdbf17fc238dd70ca891ee32bab86963b04576d103719b5d858b053b'),
  ('ur.jalandhry', 78, 24, 5696, 'وہاں نہ ٹھنڈک کا مزہ چکھیں گے۔ نہ (کچھ) پینا (نصیب ہو گا)', NULL, NULL, '9985dc71c0bbdd16235bef70766571ada05af9eb8c13a1e4dac40ae3fe8d41c4'),
  ('ur.jalandhry', 78, 25, 5697, 'مگر گرم پانی اور بہتی پیپ', NULL, NULL, '9cc277c5871f314379f2fe69339f66881bbaccfeb7c9454406b5cb4f2fa072d9'),
  ('ur.jalandhry', 78, 26, 5698, '(یہ) بدلہ ہے پورا پورا', NULL, NULL, 'f77832a6133462858cd293edb6a895ff0cb9f58b0b95bbc9a16a07c6b09a72cc'),
  ('ur.jalandhry', 78, 27, 5699, 'یہ لوگ حساب (آخرت) کی امید ہی نہیں رکھتے تھے', NULL, NULL, 'd1a57fc3803f1f8e5d1ba7382d3ef6a27343605f399b974e1319b7edd978ad1f'),
  ('ur.jalandhry', 78, 28, 5700, 'اور ہماری آیتوں کو جھوٹ سمجھ کر جھٹلاتے رہتے تھے', NULL, NULL, 'a647d2d2ec087912bd0f9f0de5e3d864339036c2d8dc510613674e0f16473e06')
