  ('ur.jalandhry', 78, 29, 5701, 'اور ہم نے ہر چیز کو لکھ کر ضبط کر رکھا ہے', NULL, NULL, '0f80cffcdc41ee350df6b738bff6dc889b5c7be5b59fad7d3624d8aa72875338'),
  ('ur.jalandhry', 78, 30, 5702, 'سو (اب) مزہ چکھو۔ ہم تم پر عذاب ہی بڑھاتے جائیں گے', NULL, NULL, '67695c6ec6d1ee8a43afc84b6bc0bf78975715f09607645efd05a2c1922b9a52'),
  ('ur.jalandhry', 78, 31, 5703, 'بے شک پرہیز گاروں کے لیے کامیابی ہے', NULL, NULL, 'f1dfe6742e12b2eb8e2cc57f50a4686ad148b0614568b38b2fdad3f4c9bef441'),
  ('ur.jalandhry', 78, 32, 5704, '(یعنی) باغ اور انگور', NULL, NULL, '12123391f4baba677927a2492009b47f49a4949a38d0c7e6ea2bbfa669e23fa9'),
  ('ur.jalandhry', 78, 33, 5705, 'اور ہم عمر نوجوان عورتیں', NULL, NULL, '730e41eac306cfdc07aaed60e687f4950240dcf6daeb03adb7c2b6327380e856'),
  ('ur.jalandhry', 78, 34, 5706, 'اور شراب کے چھلکتے ہوئے گلاس', NULL, NULL, '1e549c2de5122cc84216e8f7b96b173297df75a988cd88912fc88f0eaa09d6fe'),
  ('ur.jalandhry', 78, 35, 5707, 'وہاں نہ بیہودہ بات سنیں گے نہ جھوٹ (خرافات)', NULL, NULL, '4f9a68e1fb83b347569caa1fdfb3638b5514228b6d32d108aa4fa85d092ea014'),
  ('ur.jalandhry', 78, 36, 5708, 'یہ تمہارے پروردگار کی طرف سے صلہ ہے انعام کثیر', NULL, NULL, 'd8e0c12ae25560329a2869e2c4cc3f0b28219c75b3b6b4d2d8b6752ebdda8b41'),
  ('ur.jalandhry', 78, 37, 5709, 'وہ جو آسمانوں اور زمین اور جو ان دونوں میں ہے سب کا مالک ہے بڑا مہربان کسی کو اس سے بات کرنے کا یارا نہیں ہوگا', NULL, NULL, 'bbd76e4a55f258d8f5767a2a254a5c91b1994b6b2627fae0f0c19827543a6bd7'),
  ('ur.jalandhry', 78, 38, 5710, 'جس دن روح (الامین) اور فرشتے صف باندھ کر کھڑے ہوں گے تو کوئی بول نہ سکے گا مگر جس کو (خدائے رحمٰن) اجازت بخشے اور اس نے بات بھی درست کہی ہو', NULL, NULL, '11b60a07bad5d311a85d1698543aa20dd464c01c31d1e769ffd09367a355d640'),
  ('ur.jalandhry', 78, 39, 5711, 'یہ دن برحق ہے۔ پس جو شخص چاہے اپنے پروردگار کے پاس ٹھکانہ بنا ئے', NULL, NULL, 'd169e1573a01f3ae22291b951307f1418564d872f7a8f80f5059929cb1bccc39'),
  ('ur.jalandhry', 78, 40, 5712, 'ہم نے تم کو عذاب سے جو عنقریب آنے والا ہے آگاہ کر دیا ہے جس دن ہر شخص ان (اعمال) کو جو اس نے آگے بھیجے ہوں گے دیکھ لے گا اور کافر کہے گا کہ اے کاش میں مٹی ہوتا', NULL, NULL, 'ca92870daf03e109ed88b6b100495e2a2769a88802595a9cace70afca98a1de6'),
  ('ur.jalandhry', 79, 1, 5713, 'ان (فرشتوں) کی قسم جو ڈوب کر کھینچ لیتے ہیں', NULL, NULL, '0c2692b99ff70156cbb0327a87f8f610471e17fb4aea28952df37fb8c50a11a3'),
  ('ur.jalandhry', 79, 2, 5714, 'اور ان کی جو آسانی سے کھول دیتے ہیں', NULL, NULL, '9db603886df26a8ebfea8a6fba3d554e65e3ccdbbeee5837bf96b841f70c78d0'),
  ('ur.jalandhry', 79, 3, 5715, 'اور ان کی جو تیرتے پھرتے ہیں', NULL, NULL, '9fe61a4b36bad1dcbcd150bafe39f0da187540f69f7c06e4b999151befd9d84f'),
  ('ur.jalandhry', 79, 4, 5716, 'پھر لپک کر آگے بڑھتے ہیں', NULL, NULL, 'e2cdb8fba8e77ec22d21224afa93cb220b1fc36c4cccfe2b422c628111eb31e7'),
  ('ur.jalandhry', 79, 5, 5717, 'پھر (دنیا کے) کاموں کا انتظام کرتے ہیں', NULL, NULL, '7589fd62cc66186eca2439a61f2af9ed1386befad33baf45672349002d6b4629'),
  ('ur.jalandhry', 79, 6, 5718, '(کہ وہ دن آ کر رہے گا) جس دن زمین کو بھونچال آئے گا', NULL, NULL, '9cb54c0229611e7c9221a2b623932cc4f22f548c970fc25a27d08f6c8c637fbc'),
  ('ur.jalandhry', 79, 7, 5719, 'پھر اس کے پیچھے اور (بھونچال) آئے گا', NULL, NULL, '822faa52708bc4931c848a59358683d12626f1915958309396b5d22c919f79d3'),
  ('ur.jalandhry', 79, 8, 5720, 'اس دن (لوگوں) کے دل خائف ہو رہے ہوں گے', NULL, NULL, 'e6da7bc6a0c3e8f764ac555970e72f12991adbca18138cb12171c5feb0d6f4b1'),
