  ('ur.jalandhry', 79, 20, 5732, 'غرض انہوں نے اس کو بڑی نشانی دکھائی', NULL, NULL, '32b389dc24db5d22c84b6e3841d892c854af932d4dd233897e2f564836f26117'),
