  ('ur.jalandhry', 79, 22, 5734, 'پھر لوٹ گیا اور تدبیریں کرنے لگا', NULL, NULL, '3ab5a8c6d201c09eb1d4c0420bcc358eba7a82b23c053e51e273596ee724f344'),
  ('ur.jalandhry', 79, 23, 5735, 'اور (لوگوں کو) اکٹھا کیا اور پکارا', NULL, NULL, '2f6cce6f9dc755ac7be49cf733dcb7c12a6c80e98534c1c583ead3ea73110f48'),
