  ('ur.jalandhry', 79, 34, 5746, 'تو جب بڑی آفت آئے گی', NULL, NULL, '8f0db377c2aa4b04516dc181d26ad023aca883f90203b837b069bfff85f85913'),
  ('ur.jalandhry', 79, 35, 5747, 'اس دن انسان اپنے کاموں کو یاد کرے گا', NULL, NULL, '2ad2d4976708c94c4c2f8c815170741897d011f201adc03176551578924c5b33'),
  ('ur.jalandhry', 79, 36, 5748, 'اور دوزخ دیکھنے والے کے سامنے نکال کر رکھ دی جائے گی', NULL, NULL, 'cc9a03fb9cb9c3faf770db472b2bd4c38d8a139536cdd7652b2e902db39a6c9f'),
  ('ur.jalandhry', 79, 37, 5749, 'تو جس نے سرکشی کی', NULL, NULL, 'c47ea08241d655ed7f3c5d766d3398d2c56c8c6f153708afebcda78aa9663ab1'),
