  ('ur.jalandhry', 79, 40, 5752, 'اور جو اپنے پروردگار کے سامنے کھڑے ہونے سے ڈرتا اور جی کو خواہشوں سے روکتا رہا', NULL, NULL, 'e7a9da6072ec0f60898eb022802769c0555fe8ce82988beb90577d237255db2b'),
  ('ur.jalandhry', 79, 41, 5753, 'اس کا ٹھکانہ بہشت ہے', NULL, NULL, '296e19e5138b21ec508ef624614d9299bfc8774afe730905027f62b6f2dd10b8'),
  ('ur.jalandhry', 79, 42, 5754, '(اے پیغمبر، لوگ) تم سے قیامت کے بارے میں پوچھتے ہیں کہ اس کا وقوع کب ہو گا؟', NULL, NULL, '36120863b472c2bb6c442506ce61a9ac82a33e5e35337f6882e63904e45dacb7'),
  ('ur.jalandhry', 79, 43, 5755, 'سو تم اس کے ذکر سے کس فکر میں ہو', NULL, NULL, '76784473e94659d35ec861f10896372b1ed93c6fef7f90951eba41d0790c60b7'),
  ('ur.jalandhry', 79, 44, 5756, 'اس کا منتہا (یعنی واقع ہونے کا وقت) تمہارے پروردگار ہی کو (معلوم ہے)', NULL, NULL, '9cb2b586a18c2aa6928b0d98705e213d0a52894c91df78b99436b2ec572ce33c'),
  ('ur.jalandhry', 79, 45, 5757, 'جو شخص اس سے ڈر رکھتا ہے تم تو اسی کو ڈر سنانے والے ہو', NULL, NULL, 'f997a25e9c75e3cb21b386ddad3406a3b300283e18c8487900a0cfb038e9e6ac'),
  ('ur.jalandhry', 79, 46, 5758, 'جب وہ اس کو دیکھیں گے (تو ایسا خیال کریں گے) کہ گویا (دنیا میں صرف) ایک شام یا صبح رہے تھے', NULL, NULL, '942b11982ab0075375944591ae1d27eb97d383ebcdd491ea474ce9e6189eb40a'),
  ('ur.jalandhry', 80, 1, 5759, '(محمد مصطفٰےﷺ) ترش رُو ہوئے اور منہ پھیر بیٹھے', NULL, NULL, '85f848680409b828558c79840ea8b3cd49c2ca28a3e26a32df66cb9f8121eec4'),
  ('ur.jalandhry', 80, 2, 5760, 'کہ ان کے پاس ایک نابینا آیا', NULL, NULL, 'd1c2ba3e09bfcec512b333b6281fd1f2c422e873316f47db4b9a95f0227d0e47'),
  ('ur.jalandhry', 80, 3, 5761, 'اور تم کو کیا خبر شاید وہ پاکیزگی حاصل کرتا', NULL, NULL, '666c16bee76707f9eeb52b0e2cb2716c7ed2dddab53f99e6372174fe4e17b169'),
  ('ur.jalandhry', 80, 4, 5762, 'یا سوچتا تو سمجھانا اسے فائدہ دیتا', NULL, NULL, '3a8347fd6ca2fd7f83b59bad326bd38927d1ed0949f39b011d03cd7e14c5415c'),
  ('ur.jalandhry', 80, 5, 5763, 'جو پروا نہیں کرتا', NULL, NULL, 'dc81c5219f69c83f23de7628c3e81d6eb63cfa7c4e1bf5e6ef04552cd1be390f'),
  ('ur.jalandhry', 80, 6, 5764, 'اس کی طرف تو تم توجہ کرتے ہو', NULL, NULL, '7feb52c38a66f602d534497cb62ee58bf69a60d0f73de14902609bdd368b8eb8'),
  ('ur.jalandhry', 80, 7, 5765, 'حالانکہ اگر وہ نہ سنورے تو تم پر کچھ (الزام) نہیں', NULL, NULL, '1d83880cd30518b7c864e92e61e0641917732ce8214592385dcc29a3392a7e62'),
  ('ur.jalandhry', 80, 8, 5766, 'اور جو تمہارے پاس دوڑتا ہوا آیا', NULL, NULL, '1bcdd3bbce313318524d956057114ef6cf96e8ca0cb81af20bac560a1a2c84dd'),
