  ('ur.jalandhry', 80, 10, 5768, 'اس سے تم بےرخی کرتے ہو', NULL, NULL, '4ffa06fdc61561cae56f626ae827f76498854eae7b41da90698ec863c51235f9'),
  ('ur.jalandhry', 80, 11, 5769, 'دیکھو یہ (قرآن) نصیحت ہے', NULL, NULL, '507812a0c04a83035df1b2117dbc89ff1fd9c7508704f5dc3d42e005b5b27c41'),
  ('ur.jalandhry', 80, 12, 5770, 'پس جو چاہے اسے یاد رکھے', NULL, NULL, 'afb811ea4361e87e403ee2cb21b3a6bafacbc817822f47f9284b2a7dfec310b1'),
  ('ur.jalandhry', 80, 13, 5771, 'قابل ادب ورقوں میں (لکھا ہوا)', NULL, NULL, 'aac049e9808de67000552f831145c3b67e0a348ab87a4ee97c975dd1ac99b417'),
  ('ur.jalandhry', 80, 14, 5772, 'جو بلند مقام پر رکھے ہوئے (اور) پاک ہیں', NULL, NULL, 'b28e8311a0a45d0b2fa30863f0a7eeda1755fe4d1f9a19f2d58a9d2f9047a560'),
  ('ur.jalandhry', 80, 15, 5773, 'لکھنے والوں کے ہاتھوں میں', NULL, NULL, '86702c62695dab891d8b9dd7813090f27c49268a5ea679eea856b0e7eb41557a'),
  ('ur.jalandhry', 80, 16, 5774, 'جو سردار اور نیکو کار ہیں', NULL, NULL, 'a0f25bf3a8cf24db2289b0fa0a02c74e1b25c3911e24dfbd24e71cd8d16f08f2'),
  ('ur.jalandhry', 80, 17, 5775, 'انسان ہلاک ہو جائے کیسا ناشکرا ہے', NULL, NULL, '5301500fbc862650ea561176ea241615c29751c7ccea3ef286057afc80a7a8d1'),
  ('ur.jalandhry', 80, 18, 5776, 'اُسے (خدا نے) کس چیز سے بنایا؟', NULL, NULL, 'de00b4ebb9e3f52a48ce6837a3b847e39c559d27333c29f0592a24da276a21c4'),
  ('ur.jalandhry', 80, 19, 5777, 'نطفے سے بنایا پھر اس کا اندازہ مقرر کیا', NULL, NULL, 'c076d816ccfef4f343e2f9c806fcf14f27c7aa735ee91ff3cddcb31eff2a91b5'),
  ('ur.jalandhry', 80, 20, 5778, 'پھر اس کے لیے رستہ آسان کر دیا', NULL, NULL, '265c90c4c316fe1508d7daaf5b741999513d490591db9a44f85c10ba6af6ffe1'),
  ('ur.jalandhry', 80, 21, 5779, 'پھر اس کو موت دی پھر قبر میں دفن کرایا', NULL, NULL, '62dc0ee38ea95380be2850de34335da2813ec18b622cd023107c4bc9d225db14'),
  ('ur.jalandhry', 80, 22, 5780, 'پھر جب چاہے گا اسے اٹھا کھڑا کرے گا', NULL, NULL, 'b0c0e78d455d680a48b8e3fa8f2b7a6fcc7d226b818c9e5dcc359a682bb6f839'),
  ('ur.jalandhry', 80, 23, 5781, 'کچھ شک نہیں کہ خدا نے اسے جو حکم دیا اس نے اس پر عمل نہ کیا', NULL, NULL, '717e082f1520c80d9f69f413ea624f23efea75993eb9fe4b50a9c1b5c9832ef4'),
  ('ur.jalandhry', 80, 24, 5782, 'تو انسان کو چاہیئے کہ اپنے کھانے کی طرف نظر کرے', NULL, NULL, '419f5d6609fd73e3a53ba8e678be977dc2b2ff7c632219f470bd067f4b3e55c6'),
  ('ur.jalandhry', 80, 25, 5783, 'بے شک ہم ہی نے پانی برسایا', NULL, NULL, 'd8f163b90a3d34d5a104993c092b9dc38d7ca30684ef762375cb3d1c0f91102d'),
  ('ur.jalandhry', 80, 26, 5784, 'پھر ہم ہی نے زمین کو چیرا پھاڑا', NULL, NULL, '91218cca0580d7206cae899f8f6fa6c699b97227a40bab4c3beed9eb84bf8822'),
  ('ur.jalandhry', 80, 27, 5785, 'پھر ہم ہی نے اس میں اناج اگایا', NULL, NULL, '6948b7cae854d98ceba24ad293628059c3ed686b1b25df78fa9993b9cf2785ee'),
  ('ur.jalandhry', 80, 28, 5786, 'اور انگور اور ترکاری', NULL, NULL, '6573c41875434a2e24c72cae85707ae690499ec8f33eb8237defd293adb6305e'),
  ('ur.jalandhry', 80, 29, 5787, 'اور زیتون اور کھجوریں', NULL, NULL, '9933b118d267ee57ebac4a205b2d58c5b32927adf5a6c3c93e61352342b1d841'),
  ('ur.jalandhry', 80, 30, 5788, 'اور گھنے گھنے باغ', NULL, NULL, 'a17ed09204be2572e136268ad3d44ab1231950828711fcbab98f53d07c4b0e89'),
