  ('ur.jalandhry', 80, 37, 5795, 'ہر شخص اس روز ایک فکر میں ہو گا جو اسے (مصروفیت کے لیے) بس کرے گا', NULL, NULL, '0b08dd2caa276dffc164b6501393d0ba435eede7959cf0368dfd36a3857fcadd'),
  ('ur.jalandhry', 80, 38, 5796, 'اور کتنے منہ اس روز چمک رہے ہوں گے', NULL, NULL, '8f78b9381bfb55e5d8d1dbedf686d51db873cca2426054e9dbc0be2d5fff008a'),
  ('ur.jalandhry', 80, 39, 5797, 'خنداں و شاداں (یہ مومنان نیکو کار ہیں)', NULL, NULL, 'e25998de0879f36c5fed0c7b064beb5256480f621b6c781ee1165cbf11fbe2c5'),
  ('ur.jalandhry', 80, 40, 5798, 'اور کتنے منہ ہوں گے جن پر گرد پڑ رہی ہو گی', NULL, NULL, '50a3e8dda47827c43bf5f9dd221441b5c0d09a966e687a8603d115885437d335'),
  ('ur.jalandhry', 80, 41, 5799, '(اور) سیاہی چڑھ رہی ہو گی', NULL, NULL, 'f701bea3156d8fe9c2d5caba9951292a2900f17fad9cf0cd31b690a1fb5e2fca'),
