  ('ur.jalandhry', 81, 1, 5801, 'جب سورج لپیٹ لیا جائے گا', NULL, NULL, 'a2d682e2db1139dfe490923951be8de8228170cfc3f0a36eeef270989d69ea42'),
  ('ur.jalandhry', 81, 2, 5802, 'جب تارے بےنور ہو جائیں گے', NULL, NULL, '57e20a59f6742461654ed19762abd55579fa13083ea04af24c6bf58708a85316'),
