  ('ur.jalandhry', 81, 10, 5810, 'اور جب (عملوں کے) دفتر کھولے جائیں گے', NULL, NULL, 'd10eae75ce9f90c57cf19ef027bb045e51c659dc669c6aa738104d38487aec4e'),
