  ('ur.jalandhry', 81, 13, 5813, 'اور بہشت جب قریب لائی جائے گی', NULL, NULL, '3a7dc01fc5d45efeaa0f09011d886629e68b5ef42aaa6b724012c06ecc098f2a'),
  ('ur.jalandhry', 81, 14, 5814, 'تب ہر شخص معلوم کر لے گا کہ وہ کیا لے کر آیا ہے', NULL, NULL, '88bb8c49a05291d5f3dfe859cec487cc305f2d0ba0deead382bbd0ee85918ab6'),
  ('ur.jalandhry', 81, 15, 5815, 'ہم کو ان ستاروں کی قسم جو پیچھے ہٹ جاتے ہیں', NULL, NULL, '32ee3be9eef1715d34c13f9f30d4aeb8272641329a89f3fa7138e27c8d9ee524'),
  ('ur.jalandhry', 81, 16, 5816, '(اور) جو سیر کرتے اور غائب ہو جاتے ہیں', NULL, NULL, '0012a32b0c340c8dbab86d274300e74380b28fb967b393c904799f4fa3fe7b18'),
  ('ur.jalandhry', 81, 17, 5817, 'اور رات کی قسم جب ختم ہونے لگتی ہے', NULL, NULL, 'b7d5806903099a21cc7aa78d53dd9ef904649d03d116de4b1bb6fa003cd385d5'),
