  ('ur.jalandhry', 81, 19, 5819, 'کہ بےشک یہ (قرآن) فرشتہٴ عالی مقام کی زبان کا پیغام ہے', NULL, NULL, 'c970eefbd44c6aace0739bef779c4609e928fe13502a061fe8bab72c7d6461b4'),
  ('ur.jalandhry', 81, 20, 5820, 'جو صاحب قوت مالک عرش کے ہاں اونچے درجے والا ہے', NULL, NULL, 'a1edf68991102950d19f90b3151c7d0d32dc137bc81c1d3b25e2cf13f8032d4a'),
  ('ur.jalandhry', 81, 21, 5821, 'سردار (اور) امانت دار ہے', NULL, NULL, 'ffc62d04637c563ee9a201ebba120d4cc98092884532c9f2e41abe1f5e99bd92'),
