  ('ur.jalandhry', 81, 25, 5825, 'اور یہ شیطان مردود کا کلام نہیں', NULL, NULL, '1bfbdd7b31b08dca6ab7183c87a0b110fe7fed7f9a8ce51c308886dcf871c6e0'),
  ('ur.jalandhry', 81, 26, 5826, 'پھر تم کدھر جا رہے ہو', NULL, NULL, '47673f5fe38e33afc0567262ea1c818843acd9c47a0e1b395d090722be176eca'),
  ('ur.jalandhry', 81, 27, 5827, 'یہ تو جہان کے لوگوں کے لیے نصیحت ہے', NULL, NULL, '6d5556cd5a3ad3cb119e6d893fa914d729c246175ba6aed2006adc07adc0afd4'),
  ('ur.jalandhry', 81, 28, 5828, '(یعنی) اس کے لیے جو تم میں سے سیدھی چال چلنا چاہے', NULL, NULL, 'f6862884da86ca7332c8ae79944a5db4fc0659eec3801128dfc2f04dee55a6e6'),
  ('ur.jalandhry', 81, 29, 5829, 'اور تم کچھ بھی نہیں چاہ سکتے مگر وہی جو خدائے رب العالمین چاہے', NULL, NULL, '943abaf3c2cad4fe914f21e7dafea43dd96e37982546b3744a8f3a359671a878'),
  ('ur.jalandhry', 82, 1, 5830, 'جب آسمان پھٹ جائے گا', NULL, NULL, 'e8ed642d87819fd8051dcdfc5a82cb62df79f6d9fae26febdbdbb093e596076d'),
  ('ur.jalandhry', 82, 2, 5831, 'اور جب تارے جھڑ پڑیں گے', NULL, NULL, '461a46c89d50a86f6079c29dc3029d06a35304a3070071f2d65f6fe53a1cacf6'),
  ('ur.jalandhry', 82, 3, 5832, 'اور جب دریا بہہ (کر ایک دوسرے سے مل) جائیں گے', NULL, NULL, 'fe8db29f82dbd6cd78ebf092193b8cfc55a05f779cd99827d41dabc4ecb4fe8b'),
  ('ur.jalandhry', 82, 4, 5833, 'اور جب قبریں اکھیڑ دی جائیں گی', NULL, NULL, '7f47d5b39779e911b22d66ebf5515790f21e303fe00ea7676784f32a7cd3e0ca'),
  ('ur.jalandhry', 82, 5, 5834, 'تب ہر شخص معلوم کرلے گا کہ اس نے آگے کیا بھیجا تھا اور پیچھے کیا چھوڑا تھا', NULL, NULL, '3c3762cf3e8b86e26cb89ba0db339a95c45df16d26011c85ec2c6e6ffc782573'),
  ('ur.jalandhry', 82, 6, 5835, 'اے انسان تجھ کو اپنے پروردگار کرم گستر کے باب میں کس چیز نے دھوکا دیا', NULL, NULL, '5844b1d4066b2117e24436ce369e21024ed97ede3d7cd9b7cf26e3ff7daf3f3f'),
  ('ur.jalandhry', 82, 7, 5836, '(وہی تو ہے) جس نے تجھے بنایا اور (تیرے اعضا کو) ٹھیک کیا اور (تیرے قامت کو) معتدل رکھا', NULL, NULL, 'fee24ee37c5f2e19e66b5d2d4c5282f0fdb5ee4d52c7fed0235d966475f25b38'),
  ('ur.jalandhry', 82, 8, 5837, 'اور جس صورت میں چاہا تجھے جوڑ دیا', NULL, NULL, '8db3879a52f89b7ae52940675103e9cc403773c0ab3d6de69f333a427630f8fd'),
  ('ur.jalandhry', 82, 9, 5838, 'مگر ہیہات تم لوگ جزا کو جھٹلاتے ہو', NULL, NULL, 'd07ad000a06c84ca548d1e7cdb5c4c84583693a4503493b17272d94361832d94'),
  ('ur.jalandhry', 82, 10, 5839, 'حالانکہ تم پر نگہبان مقرر ہیں', NULL, NULL, 'b6a4c88ac2732e4a71902e3d002c007477ae0f871be89f7bba223069add65450'),
  ('ur.jalandhry', 82, 11, 5840, 'عالی قدر (تمہاری باتوں کے) لکھنے والے', NULL, NULL, '7f3cb227a7ebc49e5e58979ee99d5522ec1fec514bd4695c2c29255fb89f0aea'),
  ('ur.jalandhry', 82, 12, 5841, 'جو تم کرتے ہو وہ اسے جانتے ہیں', NULL, NULL, '1087267f8d6a4d9a6dd596f100b75d6873452e5c1eeff15c484208c53b4cb3dd'),
  ('ur.jalandhry', 82, 13, 5842, 'بے شک نیکوکار نعمتوں (کی بہشت) میں ہوں گے۔', NULL, NULL, '484c21da5ca07d199d2fcfc9ce930e5c3674a45575a977a6e941a50c8fd74993'),
  ('ur.jalandhry', 82, 14, 5843, 'اور بدکردار دوزخ میں', NULL, NULL, 'eee8abe7cff45a45fa6d6bcf1bc57a545473dba3e13fbc1111429de6c9642765'),
  ('ur.jalandhry', 82, 15, 5844, '(یعنی) جزا کے دن اس میں داخل ہوں گے', NULL, NULL, '69312e65c67154711270e27c6a3d4f37f232ad91026cde71e041908954198498'),
  ('ur.jalandhry', 82, 16, 5845, 'اور اس سے چھپ نہیں سکیں گے', NULL, NULL, 'cbd6ed9e51cebbbba3a3742609482198185a0d2eaec0ac3af8dd9b68a529484f'),
  ('ur.jalandhry', 82, 17, 5846, 'اور تمہیں کیا معلوم کہ جزا کا دن کیسا ہے؟', NULL, NULL, '05a94fbe3b722c8a4fa3d3e5152a3ed24f38939c299a8be5487ba5107e763841'),
  ('ur.jalandhry', 82, 18, 5847, 'پھر تمہیں کیا معلوم کہ جزا کا دن کیسا ہے؟', NULL, NULL, 'feecfe696f2172d362570d87b023c0281c3a56743b57b3d28d6dba7115fafc5d'),
  ('ur.jalandhry', 82, 19, 5848, 'جس روز کوئی کسی کا بھلا نہ کر سکے گا اور حکم اس روز خدا ہی کا ہو گا', NULL, NULL, '18ad499ac8a0a2e2531a88c45b43617b64f25f0e1d0eebb7594f2f7fbf4f94e6'),
  ('ur.jalandhry', 83, 1, 5849, 'ناپ اور تول میں کمی کرنے والوں کے لیے خرابی ہے', NULL, NULL, 'bc9816c31e128b9027d3f8896ab408630e2368d677bd35350f9524741e320df1'),
  ('ur.jalandhry', 83, 2, 5850, 'جو لوگوں سے ناپ کر لیں تو پورا لیں', NULL, NULL, '74e52785dfa02609477a1659c19d8029e7f713cd786779e1012a1a3f9ea3f58f'),
  ('ur.jalandhry', 83, 3, 5851, 'اور جب ان کو ناپ کر یا تول کر دیں تو کم کر دیں', NULL, NULL, '1992a291548004f00b36c173db0d86710c3abc074d79ff8b8c7d5c349bc6b171'),
  ('ur.jalandhry', 83, 4, 5852, 'کیا یہ لوگ نہیں جانتے کہ اٹھائے بھی جائیں گے', NULL, NULL, 'fc60e20c76c59b67c95a844015cd401500d08fe7c17ec7c1b3b5f40a5f14021e'),
  ('ur.jalandhry', 83, 5, 5853, '(یعنی) ایک بڑے (سخت) دن میں', NULL, NULL, 'e97bfceae4d0d697f1291350571693284c0067132bbfbd55567cf690238ae257'),
  ('ur.jalandhry', 83, 6, 5854, 'جس دن (تمام) لوگ رب العالمین کے سامنے کھڑے ہوں گے', NULL, NULL, '21b6fb250d5f40949d70753c315ecf3d5aae027006a46bcd9ffc2d35cb28968b'),
  ('ur.jalandhry', 83, 7, 5855, 'سن رکھو کہ بدکارروں کے اعمال سجّین میں ہیں', NULL, NULL, '414f0923ceac07002baa33b8df61f61702c0410a05944d5081792f232d937584'),
  ('ur.jalandhry', 83, 8, 5856, 'اور تم کیا جانتے ہوں کہ سجّین کیا چیز ہے؟', NULL, NULL, '8f9316d6cc63f52bba88f5c3437822e35bbafbeba42505c449b490d4473c0712'),
  ('ur.jalandhry', 83, 9, 5857, 'ایک دفتر ہے لکھا ہوا', NULL, NULL, '25445839720ede96c5c9d4c0950eb740abeb055c96038431970ad1e89392a7e6'),
  ('ur.jalandhry', 83, 10, 5858, 'اس دن جھٹلانے والوں کی خرابی ہے', NULL, NULL, 'aba3eb4dd290c6ed54a019b074f84ed1ff7069880871b4cc8ace09f639b298b6'),
  ('ur.jalandhry', 83, 11, 5859, '(یعنی) جو انصاف کے دن کو جھٹلاتے ہیں', NULL, NULL, '9e7569d9fcb2901dcb8e5ed7e23d4df7d34a02be3e8ba0cf70ae088469fe7754'),
  ('ur.jalandhry', 83, 12, 5860, 'اور اس کو جھٹلاتا وہی ہے جو حد سے نکل جانے والا گنہگار ہے', NULL, NULL, '168140f114eb0017ff2dfd0d4be000e897cc7bdf9bb21c332a7654288ff6af22'),
  ('ur.jalandhry', 83, 13, 5861, 'جب اس کو ہماری آیتیں سنائی جاتی ہیں تو کہتا ہے کہ یہ تو اگلے لوگوں کے افسانے ہیں', NULL, NULL, 'a7f6e85f1b983ef63ec59773c4fffef2e7776edb7498f73eee9cd734b4b59319'),
  ('ur.jalandhry', 83, 14, 5862, 'دیکھو یہ جو (اعمال بد) کرتے ہیں ان کا ان کے دلوں پر زنگ بیٹھ گیا ہے', NULL, NULL, '0b922eead5be826b3ffe6c4bcd626068da4c45a44b05da9a72201cfb4555ee2c'),
  ('ur.jalandhry', 83, 15, 5863, 'بےشک یہ لوگ اس روز اپنے پروردگار (کے دیدار) سے اوٹ میں ہوں گے', NULL, NULL, '1de533b26297f4880cdb3c608255eeb74b4bb6bf0c9c63bf0d5ad499dd0cb3dc'),
  ('ur.jalandhry', 83, 16, 5864, 'پھر دوزخ میں جا داخل ہوں گے', NULL, NULL, '021878950077fc3072575a9c4c919dc19d98d5ea7b9d364cc0d290f084a9a0b4'),
  ('ur.jalandhry', 83, 17, 5865, 'پھر ان سے کہا جائے گا کہ یہ وہی چیز ہے جس کو تم جھٹلاتے تھے', NULL, NULL, '291813dedc709d74a8d6e82534cece80d3657dd5c1f682936fcfc01ad69e7035'),
  ('ur.jalandhry', 83, 18, 5866, '(یہ بھی) سن رکھو کہ نیکوکاروں کے اعمال علیین میں ہیں', NULL, NULL, 'b21656c42908341edd12d681ef0f2323e45ce510f562b45c115f0288f4fcfb12'),
  ('ur.jalandhry', 83, 19, 5867, 'اور تم کو کیا معلوم کہ علیین کیا چیز ہے؟', NULL, NULL, '229d2bf5ec3657240202ae9a0f2e3c9ea7d7e85411beadd64b93124141711ae7'),
  ('ur.jalandhry', 83, 20, 5868, 'ایک دفتر ہے لکھا ہوا', NULL, NULL, '25445839720ede96c5c9d4c0950eb740abeb055c96038431970ad1e89392a7e6'),
  ('ur.jalandhry', 83, 21, 5869, 'جس کے پاس مقرب (فرشتے) حاضر رہتے ہیں', NULL, NULL, 'f3eab9857444118e5f19373d1a0484dc0684e01b60da4cc27663a02f34625668'),
  ('ur.jalandhry', 83, 22, 5870, 'بےشک نیک لوگ چین میں ہوں گے', NULL, NULL, '03a98dbab93871ea80dd85ad6984d2b8ce7f313c9fd933664a3ade73b7ac6740'),
  ('ur.jalandhry', 83, 23, 5871, 'تختوں پر بیٹھے ہوئے نظارے کریں گے', NULL, NULL, '147caff946df0a563332a2cd1a28b6389b07db3b0a547128c53bf89ba120aaa4'),
  ('ur.jalandhry', 83, 24, 5872, 'تم ان کے چہروں ہی سے راحت کی تازگی معلوم کر لو گے', NULL, NULL, '1f9dcef4964549df0fd418cc28ecf945f1be61dd1b0be07184d9ee31e0163961'),
  ('ur.jalandhry', 83, 25, 5873, 'ان کو خالص شراب سربمہر پلائی جائے گی', NULL, NULL, '7c8b4c6ae987f515098d8457f8bea78c613a1fcdfc2bd89abc8fd804ebb8f142'),
  ('ur.jalandhry', 83, 26, 5874, 'جس کی مہر مشک کی ہو گی تو (نعمتوں کے) شائقین کو چاہیے کہ اسی سے رغبت کریں', NULL, NULL, 'da12907f6423b922ad00ff4be3efec47abdd416c610e2df38fae026c3d727d54'),
  ('ur.jalandhry', 83, 27, 5875, 'اور اس میں تسنیم (کے پانی) کی آمیزش ہو گی', NULL, NULL, '9927fb869c6a6470a5dd20201697d09b579c68e606a0532362def5c40e359a12'),
  ('ur.jalandhry', 83, 28, 5876, 'وہ ایک چشمہ ہے جس میں سے (خدا کے) مقرب پیئیں گے', NULL, NULL, '958676666fa83f005f55010fa1b19d13f0997d1fe0bb50c2f48401328052c0e1'),
  ('ur.jalandhry', 83, 29, 5877, 'جو گنہگار (یعنی کفار) ہیں وہ (دنیا میں) مومنوں سے ہنسی کیا کرتے تھے', NULL, NULL, '9b8e24a24adb8513f9be4d19b1afd1affaadb9963fca546467a632b41c765f3e'),
  ('ur.jalandhry', 83, 30, 5878, 'اور جب ان کے پاس سے گزرتے تو حقارت سے اشارے کرتے', NULL, NULL, '0000decc50c59ef375fde709d1b49d1e85fe91b32015900d683d2bb36b680dee'),
  ('ur.jalandhry', 83, 31, 5879, 'اور جب اپنے گھر کو لوٹتے تو اتراتے ہوئے لوٹتے', NULL, NULL, 'ac6cbc3779e87a5c0483a7cb64dfbcb1c772927b2902686a72163051a4c9cb82'),
  ('ur.jalandhry', 83, 32, 5880, 'اور جب ان (مومنوں) کو دیکھتے تو کہتے کہ یہ تو گمراہ ہیں', NULL, NULL, 'f6a813f51b5c5ac2f5486091598eb39e91ec404245933ac8428650a38d91ef4e'),
  ('ur.jalandhry', 83, 33, 5881, 'حالانکہ وہ ان پر نگراں بنا کر نہیں بھیجے گئے تھے', NULL, NULL, '566ddbd013327190bd0d3aee596dc6dae80c3adf79164c068cb9da6e22533d4c'),
  ('ur.jalandhry', 83, 34, 5882, 'تو آج مومن کافروں سے ہنسی کریں گے', NULL, NULL, '8c1da8294eda779af4ba1db1027f00de54f4a2c2261f045cad36c467eb348409'),
  ('ur.jalandhry', 83, 35, 5883, '(اور) تختوں پر (بیٹھے ہوئے ان کا حال) دیکھ رہے ہوں گے', NULL, NULL, 'beffb6d37f04a3925d6686f76c7757c3a9ab9d3fa8b92a658a7cee80cb63ca65'),
  ('ur.jalandhry', 83, 36, 5884, 'تو کافروں کو ان کے عملوں کا (پورا پورا) بدلہ مل گیا', NULL, NULL, 'c4be70877958c9593b6a7e48146f93fa8107b095ee25227ff4d521ae58d6bfd1'),
  ('ur.jalandhry', 84, 1, 5885, 'جب آسمان پھٹ جائے گا', NULL, NULL, 'e8ed642d87819fd8051dcdfc5a82cb62df79f6d9fae26febdbdbb093e596076d'),
  ('ur.jalandhry', 84, 2, 5886, 'اور اپنے پروردگار کا فرمان بجا لائے گا اور اسے واجب بھی یہ ہی ہے', NULL, NULL, '2ee43adefa9379067d50395a421bd4c69beaee91a9402047e0376c3335cc2f1b'),
  ('ur.jalandhry', 84, 3, 5887, 'اور جب زمین ہموار کر دی جائے گی', NULL, NULL, 'dd7044d18e03fee8748398bb20837529d900dde36dc7025ef4143834ee8da29d'),
  ('ur.jalandhry', 84, 4, 5888, 'جو کچھ اس میں ہے اسے نکال کر باہر ڈال دے گی اور (بالکل) خالی ہو جائے گی', NULL, NULL, 'b97ead6142185650d9b88c3cbe42b50afbde7fe078f63f32230010bcc93ed217'),
  ('ur.jalandhry', 84, 5, 5889, 'اور اپنے پروردگار کے ارشاد کی تعمیل کرے گی اور اس کو لازم بھی یہی ہے (تو قیامت قائم ہو جائے گی)', NULL, NULL, 'dc10013f910f153d687acb30175d074a8e3a062d9868aee0e0e6ba9ca67e76d0'),
  ('ur.jalandhry', 84, 6, 5890, 'اے انسان! تو اپنے پروردگار کی طرف (پہنچنے میں) خوب کوشِش کرتا ہے سو اس سے جا ملے گا', NULL, NULL, 'eb466b32d8d1012379db5db35e240dd7e1558a904096a38dad6a57c4259aa357'),
  ('ur.jalandhry', 84, 7, 5891, 'تو جس کا نامہٴ (اعمال) اس کے داہنے ہاتھ میں دیا جائے گا', NULL, NULL, '92c195183ba57c82ba40338ebe181f60add43f844dab770bba59ac86f2ace094'),
  ('ur.jalandhry', 84, 8, 5892, 'اس سے حساب آسان لیا جائے گا', NULL, NULL, '7fa0c03a2a7813ccc8b0a41ea2756058cb75d0c10c086fbb21431f17bf70af47'),
  ('ur.jalandhry', 84, 9, 5893, 'اور وہ اپنے گھر والوں میں خوش خوش آئے گا', NULL, NULL, '50ef3deb17c1c7b7466d92d4adef87824ceb60d9526fc341ad5f952aaa3af85c'),
  ('ur.jalandhry', 84, 10, 5894, 'اور جس کا نامہٴ (اعمال) اس کی پیٹھ کے پیچھے سے دیا جائے گا', NULL, NULL, 'c5fbc725b7a7cf2170dd2fe06498538a5e0ca49901ec0a52fb0e438a31a84810'),
  ('ur.jalandhry', 84, 11, 5895, 'وہ موت کو پکارے گا', NULL, NULL, 'b10bcf10675815b61348898df0b55ad0ba075bfe272a57530cca3e51539e3e05'),
  ('ur.jalandhry', 84, 12, 5896, 'اور وہ دوزخ میں داخل ہو گا', NULL, NULL, '6ad8a7817e5382e4dbd38ecad4dc4b31c4e331ce197f334e5d3a01147c1b88f2'),
  ('ur.jalandhry', 84, 13, 5897, 'یہ اپنے اہل (و عیال) میں مست رہتا تھا', NULL, NULL, '9ba7a6ec9659e2bf586528b0d897a6de839098da98f1b864141f34df2ce8a70e'),
  ('ur.jalandhry', 84, 14, 5898, 'اور خیال کرتا تھا کہ (خدا کی طرف) پھر کر نہ جائے گا', NULL, NULL, 'f35ea916e7ed6e11b983299c141798cb44f1940ab8df72610480a26b447540f9'),
  ('ur.jalandhry', 84, 15, 5899, 'ہاں ہاں۔ اس کا پروردگار اس کو دیکھ رہا تھا', NULL, NULL, 'c40e0862ec0660189a92faaaecde400b0beb6778c136b46a71561445dc0427ae'),
  ('ur.jalandhry', 84, 16, 5900, 'ہمیں شام کی سرخی کی قسم', NULL, NULL, '202bb7d188b0701cf76ffcfe7399eeaa730cf510a6beba995fc1b52e6f330a3a')
