INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 84, 17, 5901, 'اور رات کی اور جن چیزوں کو وہ اکٹھا کر لیتی ہے ان کی', NULL, NULL, 'a8bfa7af137d48f29d6df92c8720d04802f63483354ed5d573e46612bfcfb032'),
  ('ur.jalandhry', 84, 18, 5902, 'اور چاند کی جب کامل ہو جائے', NULL, NULL, '6762985c3002fb428ef2dc9b69aac6412084032a71828ff175d6ff6ef3bb205c'),
  ('ur.jalandhry', 84, 19, 5903, 'کہ تم درجہ بدرجہ (رتبہٴ اعلیٰ پر) چڑھو گے', NULL, NULL, '0f8bacf1e1f1fc7152891bc0cd7648b18fff5fac8db23c98d18eddd15d9f20e0'),
