  ('ur.jalandhry', 88, 14, 5981, 'اور آبخورے (قرینے سے) رکھے ہوئے', NULL, NULL, 'a20fb33317f5bf080751a8b0da6c80465abbff3182b5f613d4745be9ee74e8c7'),
  ('ur.jalandhry', 88, 15, 5982, 'اور گاؤ تکیے قطار کی قطار لگے ہوئے', NULL, NULL, 'd6811a2b4c0fc6967dd62dafa99d37441f62640c09ab391df81976bbb612d488'),
  ('ur.jalandhry', 88, 16, 5983, 'اور نفیس مسندیں بچھی ہوئی', NULL, NULL, '06e2ad91bbce27b9ca81201ff161e8f5d58b6afc6bf4c0c37075518c887e9164'),
  ('ur.jalandhry', 88, 17, 5984, 'یہ لوگ اونٹوں کی طرف نہیں دیکھتے کہ کیسے (عجیب) پیدا کیے گئے ہیں', NULL, NULL, '3fed09b998ca861d178661514a85cdc53e4eecb2343c127d6684f70bcedc2fed'),
  ('ur.jalandhry', 88, 18, 5985, 'اور آسمان کی طرف کہ کیسا بلند کیا گیا ہے', NULL, NULL, '96243b137a4ab922453f64965193d0ac92b33260644b979edcf74aa4cecee297'),
  ('ur.jalandhry', 88, 19, 5986, 'اور پہاڑوں کی طرف کہ کس طرح کھڑے کیے گئے ہیں', NULL, NULL, 'e6ecfcb7b5ce68ed111dab522b06b79372bccd4fe6edf325ec835d5d3e5f0c06'),
  ('ur.jalandhry', 88, 20, 5987, 'اور زمین کی طرف کہ کس طرح بچھائی گئی', NULL, NULL, 'd8dd6a0142f326bf261174540fbee212c6565c6400b8524b6989b35d9242e5ae'),
  ('ur.jalandhry', 88, 21, 5988, 'تو تم نصیحت کرتے رہو کہ تم نصیحت کرنے والے ہی ہو', NULL, NULL, '2d922dbea57c0c6ff037764d80831be4e90874c90a38e241e542ca19f0d08b52'),
  ('ur.jalandhry', 88, 22, 5989, 'تم ان پر داروغہ نہیں ہو', NULL, NULL, '864e8a2bbbe7065521d84dffc46d8fb32bad0bca7129a8ff40cd71fb46e58e8b'),
  ('ur.jalandhry', 88, 23, 5990, 'ہاں جس نے منہ پھیرا اور نہ مانا', NULL, NULL, '3b5cce3b775acf0fb0595860a46ad956c381d654da45ca1664daa93ce993ab19'),
  ('ur.jalandhry', 88, 24, 5991, 'تو خدا اس کو بڑا عذاب دے گا', NULL, NULL, '2d363d0bfed256ac5bc15c525c4abc16e56fd814d54d21332a5028608a47c5f1'),
  ('ur.jalandhry', 88, 25, 5992, 'بےشک ان کو ہمارے پاس لوٹ کر آنا ہے', NULL, NULL, 'e6cc33ef43d0d80b202f657409e6fb8a00e4acab2074c90519860b5e54be9ebf'),
  ('ur.jalandhry', 88, 26, 5993, 'پھر ہم ہی کو ان سے حساب لینا ہے', NULL, NULL, 'f1437dec64bf32c9f635c063aa7b2fa98ac8b23e71141e93a3b955864df2098d'),
  ('ur.jalandhry', 89, 1, 5994, 'فجر کی قسم', NULL, NULL, 'ba5ec7bfaa2ac3c2bde55d70730bcfc6f26e4e85593a74429525b5b5f4d36bee'),
  ('ur.jalandhry', 89, 2, 5995, 'اور دس راتوں کی', NULL, NULL, '77e19bde4fb36f7f7c99f2c19b9f99477fcf77cb12158c93c709329236aac3b8'),
  ('ur.jalandhry', 89, 3, 5996, 'اور جفت اور طاق کی', NULL, NULL, '348c5c0d300bd5e4fd8b4c767d7e5c1c2190ba5f3172db8318a7b14c025ce90a'),
  ('ur.jalandhry', 89, 4, 5997, 'اور رات کی جب جانے لگے', NULL, NULL, 'ed00635237e5cd592ba59c9f1741c26ee33ebae3f24d1ed95643cfcea48ce277'),
  ('ur.jalandhry', 89, 5, 5998, 'اور بے شک یہ چیزیں عقلمندوں کے نزدیک قسم کھانے کے لائق ہیں کہ (کافروں کو ضرور عذاب ہو گا)', NULL, NULL, '23fd9819ddc1819d7b01161cf7d91b570e790835186bb54f48f3191093401ce6'),
  ('ur.jalandhry', 89, 6, 5999, 'کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے عاد کے ساتھ کیا کیا', NULL, NULL, '878ebd7e7d5464c1e898647421ca5d526ba455bbf425e7ae597814e9545a9a6e'),
  ('ur.jalandhry', 89, 7, 6000, '(جو) ارم (کہلاتے تھے اتنے) دراز قد', NULL, NULL, '0f084d9d95633f8432ff0707ee0c66b47c1814706f4a9505276d7e2da2eed192')
ON CONFLICT (edition_id, surah_number, ayah_number) DO UPDATE SET
