INSERT INTO public.quran_translations (
    edition_id, surah_number, ayah_number, ayah_id, translation_text, translator_note, source_reference, text_checksum
) VALUES
  ('ur.jalandhry', 89, 8, 6001, 'کہ تمام ملک میں ایسے پیدا نہیں ہوئے تھے', NULL, NULL, '6816b44a1c15d3f646e491a92b2bdc5eecbdd41f87e050189115e854edfdea49'),
  ('ur.jalandhry', 89, 9, 6002, 'اور ثمود کے ساتھ (کیا کیا) جو وادئِ (قریٰ) میں پتھر تراشتے تھے (اور گھر بناتے) تھے', NULL, NULL, '4b71e7f41bb30fe1a6a30b015cb72c8aff0b0f7e57b1a9708b419c6be2af941f'),
  ('ur.jalandhry', 89, 10, 6003, 'اور فرعون کے ساتھ (کیا کیا) جو خیمے اور میخیں رکھتا تھا', NULL, NULL, 'dad92765a82b4e9d9f432b736df8abdff4547c2412cb165ef337a4bc168e80d1'),
  ('ur.jalandhry', 89, 11, 6004, 'یہ لوگ ملکوں میں سرکش ہو رہے تھے', NULL, NULL, '924e14a5f4ebf40275d8009a5b9e4f71377f4a19a4d4b382328e19c688d238cb'),
  ('ur.jalandhry', 89, 12, 6005, 'اور ان میں بہت سی خرابیاں کرتے تھے', NULL, NULL, '7169483dcd05ea6f0e602d0306bd16ab973f7237a8e345bf36ca51afe84ccbb1'),
  ('ur.jalandhry', 89, 13, 6006, 'تو تمہارے پروردگار نے ان پر عذاب کا کوڑا نازل کیا', NULL, NULL, '2fa8add2e283b0cbba7101b9f5c6438bd4db4f4b7436d9b97080e14ecc839bd9'),
  ('ur.jalandhry', 89, 14, 6007, 'بے شک تمہارا پروردگار تاک میں ہے', NULL, NULL, '5dd06f7accc5d2beb7c2df0ef618051538c4007f5ba0fca7f3e549c675f95a06'),
  ('ur.jalandhry', 89, 15, 6008, 'مگر انسان (عجیب مخلوق ہے کہ) جب اس کا پروردگار اس کو آزماتا ہے تو اسے عزت دیتا اور نعمت بخشتا ہے۔ تو کہتا ہے کہ (آہا) میرے پروردگار نے مجھے عزت بخشی', NULL, NULL, '4db88707afe33d972a1d13e95506e70a7a47d2f7d6e108faeab4655945d2ce14'),
  ('ur.jalandhry', 89, 16, 6009, 'اور جب (دوسری طرح) آزماتا ہے کہ اس پر روزی تنگ کر دیتا ہے تو کہتا ہے کہ (ہائے) میرے پروردگار نے مجھے ذلیل کیا', NULL, NULL, '2c886264d633a73aaa6647dfbf84423632e2e92ab2330d5f277a719dcebae904'),
  ('ur.jalandhry', 89, 17, 6010, 'نہیں بلکہ تم لوگ یتیم کی خاطر نہیں کرتے', NULL, NULL, 'eada063fa97b10027e41823d19f31663411ad1203226b649f74adf264959033b'),
  ('ur.jalandhry', 89, 18, 6011, 'اور نہ مسکین کو کھانا کھلانے کی ترغیب دیتے ہو', NULL, NULL, '7bc04278557beb66d7823caa83491b20d5620f3d9fcabd6ada2919416fa97511'),
  ('ur.jalandhry', 89, 19, 6012, 'اور میراث کے مال سمیٹ کر کھا جاتے ہو', NULL, NULL, '110eb0de9f3e594ee5f99a2dd960740f44d0a2fb56eea51423e3dd886dac7adb'),
  ('ur.jalandhry', 89, 20, 6013, 'اور مال کو بہت ہی عزیز رکھتے ہو', NULL, NULL, '1f7652216ab7ac29249954c4a83985eaf91f7fca751728540965c1e9cbea9e08'),
  ('ur.jalandhry', 89, 21, 6014, 'تو جب زمین کی بلندی کوٹ کوٹ کو پست کر دی جائے گی', NULL, NULL, 'd9696e706bb578cdc7d50c0671413c7ee6c852bc91b777408b5e0620244d94d6'),
  ('ur.jalandhry', 89, 22, 6015, 'اور تمہارا پروردگار (جلوہ فرما ہو گا) اور فرشتے قطار باندھ باندھ کر آ موجود ہوں گے', NULL, NULL, '5c05ade0fe170124cb72e777b8519e64ec2b2444d8e93c828d25f318e3b6aaaf'),
  ('ur.jalandhry', 89, 23, 6016, 'اور دوزخ اس دن حاضر کی جائے گی تو انسان اس دن متنبہ ہو گا مگر تنبہ (سے) اسے (فائدہ) کہاں (مل سکے گا)', NULL, NULL, 'a5398ccff0b786f78354759504b9a0446268dcd3eb715aab4da58d5a623c922e'),
  ('ur.jalandhry', 89, 24, 6017, 'کہے گا کاش میں نے اپنی زندگی (جاودانی کے لیے) کچھ آگے بھیجا ہوتا', NULL, NULL, 'df4d25b4f98d2263cf85a1960374d1e2ca40b544569d853bf2616e94b2c3277f'),
  ('ur.jalandhry', 89, 25, 6018, 'تو اس دن نہ کوئی خدا کے عذاب کی طرح کا (کسی کو) عذاب دے گا', NULL, NULL, 'df0b471bdc782ebcbe340de1c21e3fc5a87279d72e96dc662f99841360ccc0e1'),
  ('ur.jalandhry', 89, 26, 6019, 'اور نہ کوئی ویسا جکڑنا جکڑے گا', NULL, NULL, '21038c904a1a8d3203e044947d8aca633c17b89ca778f79deabbc3a630c61994'),
  ('ur.jalandhry', 89, 27, 6020, 'اے اطمینان پانے والی روح!', NULL, NULL, '453ba806fb11af8fa849a94008bc52d92f4cc9eac63a8a7830f594e5c1dedf0c'),
  ('ur.jalandhry', 89, 28, 6021, 'اپنے پروردگار کی طرف لوٹ چل۔ تو اس سے راضی وہ تجھ سے راضی', NULL, NULL, 'f9134357d3b4099925ec37f3e636df5e5a8ef01de7569b8ab570f1da0f0f7219'),
  ('ur.jalandhry', 89, 29, 6022, 'تو میرے (ممتاز) بندوں میں شامل ہو جا', NULL, NULL, '41753d727c13acc546644d0b31798c17f390889c10177431e2d8cfc4ea00496d'),
  ('ur.jalandhry', 89, 30, 6023, 'اور میری بہشت میں داخل ہو جا', NULL, NULL, 'a61eecea9ae5816a3dd4b53376b63ee42b07d92325093863d19834a8a5d5a820'),
  ('ur.jalandhry', 90, 1, 6024, 'ہمیں اس شہر (مکہ) کی قسم', NULL, NULL, 'f72ad82ef6eb0719d91a8aa6d122641c0a41f599a120965fca0f3cba85fe4857'),
  ('ur.jalandhry', 90, 2, 6025, 'اور تم اسی شہر میں تو رہتے ہو', NULL, NULL, '782dc44281cace1e805e76c118198361f8d9ec058caabdd6fdada86632d7f8de'),
  ('ur.jalandhry', 90, 3, 6026, 'اور باپ (یعنی آدم) اور اس کی اولاد کی قسم', NULL, NULL, '98a368413c619411ae93a90557fbcb2801472997c99ab1af6aaee94de823f1dc'),
  ('ur.jalandhry', 90, 4, 6027, 'کہ ہم نے انسان کو تکلیف (کی حالت) میں (رہنے والا) بنایا ہے', NULL, NULL, 'f1226d3bdfdd0bcc39c0918756210b5f152e2f69cce939c74f90d92ad9e8f26d'),
  ('ur.jalandhry', 90, 5, 6028, 'کیا وہ خیال رکھتا ہے کہ اس پر کوئی قابو نہ پائے گا', NULL, NULL, '1c1ffa83d3ea5a1ec616217cdd0cf6c7c479e04a9996bf1dc9bbaa93324daa9c'),
  ('ur.jalandhry', 90, 6, 6029, 'کہتا ہے کہ میں نے بہت سا مال برباد کیا', NULL, NULL, '96190de441521ea86d4aca8f9570b88170f8f3a8b26e96f5d1006ab67425ff22'),
  ('ur.jalandhry', 90, 7, 6030, 'کیا اسے یہ گمان ہے کہ اس کو کسی نے دیکھا نہیں', NULL, NULL, '293ea9501aeeff6e1d198e0ebd615aa14900fb93fb49a17ed526de9fca0b2556'),
  ('ur.jalandhry', 90, 8, 6031, 'بھلا ہم نےاس کو دو آنکھیں نہیں دیں؟', NULL, NULL, 'af80f9e707ed0135ea610a3396ad8c1d7dcb1ee564159726777807bf261d51d0'),
  ('ur.jalandhry', 90, 9, 6032, 'اور زبان اور دو ہونٹ (نہیں دیئے)', NULL, NULL, 'f49f478803c5757897a45d8d2d8b12a4f90a0d62f1462196b1e71e210a954fb8'),
  ('ur.jalandhry', 90, 10, 6033, '(یہ چیزیں بھی دیں) اور اس کو (خیر و شر کے) دونوں رستے بھی دکھا دیئے', NULL, NULL, 'acb616743edbcc0c23c7377c19848d1cfda1d20cdd2f12030c1695d55798cf7c'),
  ('ur.jalandhry', 90, 11, 6034, 'مگر وہ گھاٹی پر سے ہو کر نہ گزرا', NULL, NULL, '2bb3bff3716ce7b8df7fc4d8bb9e9d4e9aceb2290c24c3e71339c7d346be615d'),
  ('ur.jalandhry', 90, 12, 6035, 'اور تم کیا سمجھے کہ گھاٹی کیا ہے؟', NULL, NULL, '97fa927048628d141879f108168b4e5890a5afd85a51a9a260be3c1011696c01'),
  ('ur.jalandhry', 90, 13, 6036, 'کسی (کی) گردن کا چھڑانا', NULL, NULL, 'f1571b223d61c9b5b13d2e609721b5fe0a4e61b2e86494c6b18edc6980ff354a'),
  ('ur.jalandhry', 90, 14, 6037, 'یا بھوک کے دن کھانا کھلانا', NULL, NULL, '98d668ad16c6c85e28ba52a4f2f698bc17e1d80e9acbfeb8fa20fb6ecf69ad0c'),
  ('ur.jalandhry', 90, 15, 6038, 'یتیم رشتہ دار کو', NULL, NULL, '0e4ceba596f25fdbef868e627bb28633201544608f39242be055d567b23d0c66'),
  ('ur.jalandhry', 90, 16, 6039, 'یا فقیر خاکسار کو', NULL, NULL, '7a42c39584a703fa509ed9b5ec5bfe38ee44d9c06323ac07434cf6dfd05e3cde'),
  ('ur.jalandhry', 90, 17, 6040, 'پھر ان لوگوں میں بھی (داخل) ہو جو ایمان لائے اور صبر کی نصیحت اور (لوگوں پر) شفقت کرنے کی وصیت کرتے رہے', NULL, NULL, 'ee9d4bd8486b31fb67f5c18816991c2dfbaf806ce9c891bd17f1b58fa6a59369'),
  ('ur.jalandhry', 90, 18, 6041, 'یہی لوگ صاحب سعادت ہیں', NULL, NULL, '959ea8e41e460492c969fc3a6e51288e6fc764700bf8fc3bf9130a3e9f617385'),
  ('ur.jalandhry', 90, 19, 6042, 'اور جنہوں نے ہماری آیتوں کو نہ مانا وہ بدبخت ہیں', NULL, NULL, 'e886981475aa84d013accf734afc44db90a363ef8d95e00150d4b7cf72dfaef6'),
  ('ur.jalandhry', 90, 20, 6043, 'یہ لوگ آگ میں بند کر دیئے جائیں گے', NULL, NULL, '275c945b7006de64de4f5ebafcc44e56c0cf3c1b83b6f04df13b180d61392dea'),
  ('ur.jalandhry', 91, 1, 6044, 'سورج کی قسم اور اس کی روشنی کی', NULL, NULL, '6c8c410882246fd7f662ad72857ac89f452ff6fcdfb0a96ff4732eb40541258e'),
  ('ur.jalandhry', 91, 2, 6045, 'اور چاند کی جب اس کے پیچھے نکلے', NULL, NULL, 'faf333354f6cc9e4179df25429db60099f1e15b6b30d560a631f304c5707bfb7'),
  ('ur.jalandhry', 91, 3, 6046, 'اور دن کی جب اُسے چمکا دے', NULL, NULL, '60fc3603738c2b3058b2d12714c4ef0e92714389c61d6482ef418e384a96f426'),
  ('ur.jalandhry', 91, 4, 6047, 'اور رات کی جب اُسے چھپا لے', NULL, NULL, '9a848abdbfb792b76cb86909b3c09b4a26267568ca6ddbbca09669dc55526b73'),
  ('ur.jalandhry', 91, 5, 6048, 'اور آسمان کی اور اس ذات کی جس نے اسے بنایا', NULL, NULL, '9a86ea4ae701da37c3fcbc0fd50085424557d34680a6cfb200fa00621e81d164'),
  ('ur.jalandhry', 91, 6, 6049, 'اور زمین کی اور اس کی جس نے اسے پھیلایا', NULL, NULL, '82a4d88709138755ab824ce268e12f9def4ec60941141ef27d2355d71932144e'),
  ('ur.jalandhry', 91, 7, 6050, 'اور انسان کی اور اس کی جس نے اس (کے اعضا) کو برابر کیا', NULL, NULL, 'c10a54c1bb423b6d819f0bcf9a7e8347bac205dfec41828c9e1cbfe82f9e0c72'),
  ('ur.jalandhry', 91, 8, 6051, 'پھر اس کو بدکاری (سے بچنے) اور پرہیزگاری کرنے کی سمجھ دی', NULL, NULL, 'a9ac9ba8dbee923105761105a73bac4738ebe5905ca5cb2e413d1be334ab0e5b'),
  ('ur.jalandhry', 91, 9, 6052, 'کہ جس نے (اپنے) نفس (یعنی روح) کو پاک رکھا وہ مراد کو پہنچا', NULL, NULL, '40924976069954b461d81d391ab3ea5e46bdcf23fa2bedeb69a85b5dcf809f96'),
  ('ur.jalandhry', 91, 10, 6053, 'اور جس نے اسے خاک میں ملایا وہ خسارے میں رہا', NULL, NULL, 'b10a6311a50dc11b4af56f00f446ff5067c91c7dce502a2649171f893ab05310'),
  ('ur.jalandhry', 91, 11, 6054, '(قوم) ثمود نے اپنی سرکشی کے سبب (پیغمبر کو) جھٹلایا', NULL, NULL, 'cb99c0702a49fef7fb56f245497b1f4f0a03dab0273b2080727404bdb4735c36'),
  ('ur.jalandhry', 91, 12, 6055, 'جب ان میں سے ایک نہایت بدبخت اٹھا', NULL, NULL, '5f0f6c29e6acb750fecbc61b74363955e8853bc19aa7f7099d2941628f964ee1'),
  ('ur.jalandhry', 91, 13, 6056, 'تو خدا کے پیغمبر (صالح) نے ان سے کہا کہ خدا کی اونٹنی اور اس کے پانی پینے کی باری سے عذر کرو', NULL, NULL, '01c9d2063500174d912c287df7693cbac5c224c2eb0b639d89281024b3fa4c8a'),
  ('ur.jalandhry', 91, 14, 6057, 'مگر انہوں نے پیغمبر کو جھٹلایا اور اونٹنی کی کونچیں کاٹ دیں تو خدا نے ان کےگناہ کے سبب ان پر عذاب نازل کیا اور سب کو (ہلاک کر کے) برابر کر دیا', NULL, NULL, 'bbaad77270d8f80992383950a35e24b6635171a6ab768b56e5fd350947b2392c'),
  ('ur.jalandhry', 91, 15, 6058, 'اور اس کو ان کے بدلہ لینے کا کچھ بھی ڈر نہیں', NULL, NULL, '320c4901be34f60a68dd4cf300186fa4c0adb7217b087b88a1048af3a2e8254d'),
  ('ur.jalandhry', 92, 1, 6059, 'رات کی قسم جب (دن کو) چھپالے', NULL, NULL, '8461aa89853ac0b9774e3fa06e3f08ad6b31b38c1a49fd9e6636ec199cfab109'),
  ('ur.jalandhry', 92, 2, 6060, 'اور دن کی قسم جب چمک اٹھے', NULL, NULL, 'e5949f67f15a55db24d870bb7f8f22ca80ef1c38d0947e900f1f7f054f246cd5'),
  ('ur.jalandhry', 92, 3, 6061, 'اور اس (ذات) کی قسم جس نے نر اور مادہ پیدا کیے', NULL, NULL, '339e1a241d0ffd794724950f6bdc8a13baa1629295aca7c011d31a1604b4ec32'),
  ('ur.jalandhry', 92, 4, 6062, 'کہ تم لوگوں کی کوششں طرح طرح کی ہے', NULL, NULL, 'c2a2d9938441cafd127efe634e529b92162c6982017a4b81e7128008d21c4665'),
  ('ur.jalandhry', 92, 5, 6063, 'تو جس نے (خدا کے رستے میں مال) دیا اور پرہیز گاری کی', NULL, NULL, '4dca023e0b352b9dde6199b8bad51b28e5422b7d0467234b2ea30ab5bbf4a7a1'),
  ('ur.jalandhry', 92, 6, 6064, 'اور نیک بات کو سچ جانا', NULL, NULL, 'f2ab060c946e25b0b77ae499538da4e344dc8003403d62d94e82cf1dba36f3ed'),
  ('ur.jalandhry', 92, 7, 6065, 'اس کو ہم آسان طریقے کی توفیق دیں گے', NULL, NULL, '3124f4b632e02585a0bbdbb50e99c4070980a3efab8804c194d056f9f204825e'),
  ('ur.jalandhry', 92, 8, 6066, 'اور جس نے بخل کیا اور بےپروا بنا رہا', NULL, NULL, '9dc2e36bfb6af9648d84f6f48b4d6d86e5738a2734e37037434a02e614c7f5f5'),
  ('ur.jalandhry', 92, 9, 6067, 'اور نیک بات کو جھوٹ سمجھا', NULL, NULL, '8144c91ecb666bf3ab70e1f082b82a920758c41e612b811514abc2faf741a2bf'),
  ('ur.jalandhry', 92, 10, 6068, 'اسے سختی میں پہنچائیں گے', NULL, NULL, '5e2a56d9cf73d7d7351f0b1e8a74672262935b0975964811c04fb6bce8276df9'),
  ('ur.jalandhry', 92, 11, 6069, 'اور جب وہ (دوزخ کے گڑھے میں) گرے گا تو اس کا مال اس کے کچھ کام نہ آئے گا', NULL, NULL, '49c5e008fdf85ca27fc76ae83905bfb4a55baca37dcad50d322dc202ec208698'),
  ('ur.jalandhry', 92, 12, 6070, 'ہمیں تو راہ دکھا دینا ہے', NULL, NULL, 'f1194b1e5ad5f6cd903f2ab26cdaf2b98625b2e40b7c53b6f53291d72884226e'),
  ('ur.jalandhry', 92, 13, 6071, 'اور آخرت او ردنیا ہماری ہی چیزیں ہیں', NULL, NULL, '2c0cb616f34a4a9331f4ed043bb18fe0ad8dd01a2c4b7bf6e2f4b84e30380532'),
  ('ur.jalandhry', 92, 14, 6072, 'سو میں نے تم کو بھڑکتی آگ سے متنبہ کر دیا', NULL, NULL, 'f5817fd90a0fcf435ec15c8daa9eda90ce71b5dd3ad696e65cd81c8476e9dc3d'),
  ('ur.jalandhry', 92, 15, 6073, 'اس میں وہی داخل ہو گا جو بڑا بدبخت ہے', NULL, NULL, '8cd7c55012a246a508a409ad302929fde5520f0b2c458851f24194931233ba8d'),
  ('ur.jalandhry', 92, 16, 6074, 'جس نے جھٹلایا اور منہ پھیرا', NULL, NULL, 'a80b1a169c2067aa9c386b916fc971cf80b1d5e31ccadf24088318b98d566f85'),
  ('ur.jalandhry', 92, 17, 6075, 'اور جو بڑا پرہیزگار ہے وہ (اس سے) بچا لیا جائے گا', NULL, NULL, 'd928b8e1c371f0542fba92a68651bf72c10dcb72c34a09c73eb6b3b431baef01'),
  ('ur.jalandhry', 92, 18, 6076, 'جو مال دیتا ہے تاکہ پاک ہو', NULL, NULL, 'de8870311c693213bbb76b818ecbe24d15265c5e921a8815dbc8863bd187b0a7'),
  ('ur.jalandhry', 92, 19, 6077, 'اور (اس لیے) نہیں (دیتا کہ) اس پر کسی کا احسان (ہے) جس کا وہ بدلہ اتارتا ہے', NULL, NULL, '5008890b561cf819691dde7099e5ca0cdc5f595de2e5fea0b5b797533fced7d2'),
  ('ur.jalandhry', 92, 20, 6078, 'بلکہ اپنے خداوند اعلیٰ کی رضامندی حاصل کرنے کے لیے دیتا ہے', NULL, NULL, 'f605157547d573f50f5aedd50f2e5da2af07bb8c146c082011571431aac30e8d'),
  ('ur.jalandhry', 92, 21, 6079, 'اور وہ عنقریب خوش ہو جائے گا', NULL, NULL, '17409d8ff72ea34386c0422a2e9418f857f161672740b3bb2464bce63cbde4d3'),
  ('ur.jalandhry', 93, 1, 6080, 'آفتاب کی روشنی کی قسم', NULL, NULL, '1baf1d00f3c70e9be5a08a995338034546d9a156f18ff9e408e631f3821012d3'),
  ('ur.jalandhry', 93, 2, 6081, 'اور رات (کی تاریکی) کی جب چھا جائے', NULL, NULL, '7978ae8f91c4cb06e32672e791a00162a394f898f39acf3ef945604ceca6545d'),
  ('ur.jalandhry', 93, 3, 6082, 'کہ (اے محمدﷺ) تمہارے پروردگار نے نہ تو تم کو چھوڑا اور نہ (تم سے) ناراض ہوا', NULL, NULL, 'a25184bbaa6e25eaab3aa4f171cd6ff77c90e296c5e37a6d24647501608029bd'),
  ('ur.jalandhry', 93, 4, 6083, 'اور آخرت تمہارے لیے پہلی (حالت یعنی دنیا) سے کہیں بہتر ہے', NULL, NULL, '30679bd18db136f6dac5cd72caddf0411ff4e522963c9d332a8e48e8c63dc593'),
  ('ur.jalandhry', 93, 5, 6084, 'اور تمہیں پروردگار عنقریب وہ کچھ عطا فرمائے گا کہ تم خوش ہو جاؤ گے', NULL, NULL, 'eb48e7e3677dc7aed0835382d30bda01453753e502661d7aafe13d2fccf1b1ee'),
  ('ur.jalandhry', 93, 6, 6085, 'بھلا اس نے تمہیں یتیم پا کر جگہ نہیں دی؟ (بےشک دی)', NULL, NULL, '2450daed50a3ac96d92e870850c3bc3d8daca454429cac42221fbe52dd2a3b94'),
  ('ur.jalandhry', 93, 7, 6086, 'اور رستے سے ناواقف دیکھا تو رستہ دکھایا', NULL, NULL, '24185ca36324aeb4e478157d4e22eb8b467aa2b0eed3bb0df8da17982b3f2f4a'),
  ('ur.jalandhry', 93, 8, 6087, 'اور تنگ دست پایا تو غنی کر دیا', NULL, NULL, '1cc592e257bec54e73788d84d7c32586ff61b49fa20a10fdb006fd1a1120aeb3'),
  ('ur.jalandhry', 93, 9, 6088, 'تو تم بھی یتیم پر ستم نہ کرنا', NULL, NULL, '1a609db19b6a462183fd419ef0a42f81618ea90f409e9f55ef4fa908e48fc1cc'),
  ('ur.jalandhry', 93, 10, 6089, 'اور مانگنے والے کو جھڑکی نہ دینا', NULL, NULL, '67656dbdfc07927769841304f4c92c02d231933e4e65c2fff6815e106fba1744'),
