  ('ur.jalandhry', 94, 1, 6091, '(اے محمدﷺ) کیا ہم نے تمہارا سینہ کھول نہیں دیا؟ (بےشک کھول دیا)', NULL, NULL, '8b2138dc02da168b98d3d2ff67b0e136be4e6352fcc1c16b6bef19828bcd4e91'),
  ('ur.jalandhry', 94, 2, 6092, 'اور تم پر سے بوجھ بھی اتار دیا', NULL, NULL, '4964356f38fe9bae0afbfddcba0c7561fa558c4f6c4d723b57ded95f140140c9'),
  ('ur.jalandhry', 94, 3, 6093, 'جس نے تمہاری پیٹھ توڑ رکھی تھی', NULL, NULL, '8005ce69b6ed5097ef77ab91ed33b07d36f4d77272d87149fcd9df9b376a1725'),
  ('ur.jalandhry', 94, 4, 6094, 'اور تمہارا ذکر بلند کیا', NULL, NULL, '1caf8345283e09f466e2a0f94fa93f98358b368775537198b8bc9de2d6c52074'),
  ('ur.jalandhry', 94, 5, 6095, 'ہاں ہاں مشکل کے ساتھ آسانی بھی ہے', NULL, NULL, '7120df0f6992926eef7e0f69715ce084b4f184f82ee54f25048569b250e4b493'),
  ('ur.jalandhry', 94, 6, 6096, '(اور) بے شک مشکل کے ساتھ آسانی ہے', NULL, NULL, '7153218113f6e8d23009ff13ab87e468c17f90a644568a45d9aa915819f58cdb'),
  ('ur.jalandhry', 94, 7, 6097, 'تو جب فارغ ہوا کرو تو (عبادت میں) محنت کیا کرو', NULL, NULL, '85c346a9132d5677925f730b87ff034f2cf1ae692b248f9b1ea3ae44fbdc9c88'),
  ('ur.jalandhry', 94, 8, 6098, 'اور اپنے پروردگار کی طرف متوجہ ہو جایا کرو', NULL, NULL, 'ea34b614586e896dc67c201d96ceeb45ad98f0bb66785bf3af821b58461788e0'),
  ('ur.jalandhry', 95, 1, 6099, 'انجیر کی قسم اور زیتون کی', NULL, NULL, 'd43879c5b3aaf9f7f91f1ba7d7b5fae5e95158f7ed415994ce626c8bbd968375'),
  ('ur.jalandhry', 95, 2, 6100, 'اور طور سینین کی', NULL, NULL, '7588685cd22e619f16e0d580ef1d55c2145b186b60ac745f6f9419ba50d1c342')
