  ('ur.jalandhry', 95, 3, 6101, 'اور اس امن والے شہر کی', NULL, NULL, 'cc14dfb40734219257b5aac823401a5f365b1797703d067e8140edb5f69ded1d'),
  ('ur.jalandhry', 95, 4, 6102, 'کہ ہم نے انسان کو بہت اچھی صورت میں پیدا کیا ہے', NULL, NULL, '4378c64f0d9a89a19868c0fdd25f0943f0428c8b96fa53ec324a624daca34070'),
  ('ur.jalandhry', 95, 5, 6103, 'پھر (رفتہ رفتہ) اس (کی حالت) کو (بدل کر) پست سے پست کر دیا', NULL, NULL, '6fc591f5e0e3835cb659bba1bf4d0e8f7afe562d76d088218e53f180d3d29ffc'),
  ('ur.jalandhry', 95, 6, 6104, 'مگر جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکے لیے بےانتہا اجر ہے', NULL, NULL, '30b4074785d255acb1c6a4f8e1158818c2aa61fa21f409417307dc7a5241a51b'),
  ('ur.jalandhry', 95, 7, 6105, 'تو (اے آدم زاد) پھر تو جزا کے دن کو کیوں جھٹلاتا ہے؟', NULL, NULL, '160f5e9550d55a1d4e1ee8da7310657c89f84a3c24351389645d6e4e0f8410aa'),
  ('ur.jalandhry', 95, 8, 6106, 'کیا خدا سب سے بڑا حاکم نہیں ہے؟', NULL, NULL, '6f754ae46affab5515e5faaac034e98862ac892d8dec456961528887b6d3c554'),
  ('ur.jalandhry', 96, 1, 6107, '(اے محمدﷺ) اپنے پروردگار کا نام لے کر پڑھو جس نے (عالم کو) پیدا کیا', NULL, NULL, 'e1efec1eb3a4463aefefa31660c947c842546da0891a892677c3d6a8435f503d'),
  ('ur.jalandhry', 96, 2, 6108, 'جس نے انسان کو خون کی پھٹکی سے بنایا', NULL, NULL, '74cca08f9aa54722198cb228a55135fbd57da126e373ee8e55fad330c097a307'),
  ('ur.jalandhry', 96, 3, 6109, 'پڑھو اور تمہارا پروردگار بڑا کریم ہے', NULL, NULL, 'fda1f0193caf82e22def549dcd24c339d28678dc70cc8472c811d2c9ee68145a'),
  ('ur.jalandhry', 96, 4, 6110, 'جس نے قلم کے ذریعے سے علم سکھایا', NULL, NULL, '77fb51c5fcb173852aaee4ae7706c8f4eb884bca64a85d1a8e8106a93f91cb7b'),
  ('ur.jalandhry', 96, 5, 6111, 'اور انسان کو وہ باتیں سکھائیں جس کا اس کو علم نہ تھا', NULL, NULL, 'e9b1c069860ade5f342aa927aa8badecb4a2ac8d00b55cc03b328e9e1ed9267e'),
  ('ur.jalandhry', 96, 6, 6112, 'مگر انسان سرکش ہو جاتا ہے', NULL, NULL, '9e2b822c13020786f96583f6f790d9d55f63d8a06e4f67d189f10d3de1ee6853'),
  ('ur.jalandhry', 96, 7, 6113, 'جب کہ اپنے تیئں غنی دیکھتا ہے', NULL, NULL, '282f5a5d2a460dcbf4cd531c1b2250738091d868a0a119ef9018fcfbf311a14b'),
  ('ur.jalandhry', 96, 8, 6114, 'کچھ شک نہیں کہ (اس کو) تمہارے پروردگار ہی کی طرف لوٹ کر جانا ہے', NULL, NULL, '5d92b366c473d699f061a8cfdff007587108b2445ce9e379e8b00d5fbafb56ba'),
  ('ur.jalandhry', 96, 9, 6115, 'بھلا تم نے اس شخص کو دیکھا جو منع کرتا ہے', NULL, NULL, 'af0d4dd600f8d71eb8a3de2ea9b65b47e646c85b339cd31e75681afc3dd08a99'),
  ('ur.jalandhry', 96, 10, 6116, '(یعنی) ایک بندے کو جب وہ نماز پڑھنے لگتا ہے', NULL, NULL, '45877c537437d6c771801a60292231abed22341378d421a20b184e977721ba6f'),
  ('ur.jalandhry', 96, 11, 6117, 'بھلا دیکھو تو اگر یہ راہِ راست پر ہو', NULL, NULL, '0a4e15b454aff597ad6c0780877b8a4bf7fa92a70c25d4326ac78742692d633a'),
  ('ur.jalandhry', 96, 12, 6118, 'یا پرہیز گاری کا حکم کرے (تو منع کرنا کیسا)', NULL, NULL, 'bfafaf0c64bff79c8160c66dbfd2efe48167b654535335858b7d35a213528199'),
  ('ur.jalandhry', 96, 13, 6119, 'اور دیکھو تو اگر اس نے دین حق کو جھٹلایا اور اس سے منہ موڑا (تو کیا ہوا)', NULL, NULL, '2b248ba58372349d372e04136ac478851018a738a7bf219eb8cd387f1b5abd49'),
  ('ur.jalandhry', 96, 14, 6120, 'کیااس کو معلوم نہیں کہ خدا دیکھ رہا ہے', NULL, NULL, 'b40b34c924ee11594160ed6824ad7e1539336ed6e9e400cc8b352f1b4ff55b43'),
  ('ur.jalandhry', 96, 15, 6121, 'دیکھو اگر وہ باز نہ آئے گا تو ہم (اس کی) پیشانی کے بال پکڑ گھسیٹیں گے', NULL, NULL, 'aafae853464f458297228f375474a19402dd255e959fd6aed4444880aa48e634'),
  ('ur.jalandhry', 96, 16, 6122, 'یعنی اس جھوٹے خطاکار کی پیشانی کے بال', NULL, NULL, '1831f4ef7e36b173571d830759606af3ebcacc8de8fc08c5406f7fa44ec3cb61'),
  ('ur.jalandhry', 96, 17, 6123, 'تو وہ اپنے یاروں کی مجلس کو بلالے', NULL, NULL, '144d15cc508dd7c824405c310ae33efccf365843e073c0a812af52ac613d7574'),
  ('ur.jalandhry', 96, 18, 6124, 'ہم بھی اپنے موکلانِ دوزخ کو بلا لیں گے', NULL, NULL, '66f0072e78bc35ca09a478876d68b2efb793e5ab11414fc94160d266da5e0569'),
  ('ur.jalandhry', 96, 19, 6125, 'دیکھو اس کا کہا نہ ماننا اور قربِ (خدا) حاصل کرتے رہنا', NULL, NULL, 'c78c71e89fa3ad2feb4c58c111a726c5c2f7f68bc383071b2ce87a0bd755075c'),
  ('ur.jalandhry', 97, 1, 6126, 'ہم نے اس (قرآن) کو شب قدر میں نازل (کرنا شروع) کیا', NULL, NULL, '9cf64053984e201eaf644d4e6dd6c7df7c042f27714db1154b8621728a71de6d'),
  ('ur.jalandhry', 97, 2, 6127, 'اور تمہیں کیا معلوم کہ شب قدر کیا ہے؟', NULL, NULL, '8191d0b5c929f925cd08751c0fd7ff3831404878ee3162d59671903668fd7c6f'),
  ('ur.jalandhry', 97, 3, 6128, 'شب قدر ہزار مہینے سے بہتر ہے', NULL, NULL, '54f9a1d9663b3484625bd003c1fc73097a74b5cb42982db45f0abb6c22894973'),
  ('ur.jalandhry', 97, 4, 6129, 'اس میں روح (الامین) اور فرشتے ہر کام کے (انتظام کے) لیے اپنے پروردگار کے حکم سے اترتے ہیں', NULL, NULL, '55124869c38181fc15214d02e2ce265948ccf13d7e81889abdfabdb1ce37cc75'),
  ('ur.jalandhry', 97, 5, 6130, 'یہ (رات) طلوع صبح تک (امان اور) سلامتی ہے', NULL, NULL, '29604abf7eea05b39f5658d275ce16f6128ef68de79ff82239e4165acde5ae83'),
  ('ur.jalandhry', 98, 1, 6131, 'جو لوگ کافر ہیں (یعنی) اہل کتاب اور مشرک وہ (کفر سے) باز رہنے والے نہ تھے جب تک ان کے پاس کھلی دلیل (نہ) آتی', NULL, NULL, 'bac036693a4170c4a3f03465d7e4ab5faaeee6106e12f579330f38ae8f74175f'),
  ('ur.jalandhry', 98, 2, 6132, '(یعنی) خدا کے پیغمبر جو پاک اوراق پڑھتے ہیں', NULL, NULL, '5ae82dc974006a8294128407024ac5340269935de9551cd3c2a48b4f472dd3dd'),
  ('ur.jalandhry', 98, 3, 6133, 'جن میں (مستحکم) آیتیں لکھی ہوئی ہیں', NULL, NULL, 'b45c5d5bedf33cda1f0a89c94244e4cd1fc8cb6b9dbf8d6d10e6774a08ccf51c'),
  ('ur.jalandhry', 98, 4, 6134, 'اور اہل کتاب جو متفرق (و مختلف) ہوئے ہیں تو دلیل واضح آنے کے بعد (ہوئے ہیں)', NULL, NULL, '2f86b2fbd84ff191589b86df22408bf46a7a9cf95bba3199485de357fe2a0432'),
  ('ur.jalandhry', 98, 5, 6135, 'اور ان کو حکم تو یہی ہوا تھا کہ اخلاص عمل کے ساتھ خدا کی عبادت کریں (اور) یکسو ہو کراورنماز پڑھیں اور زکوٰة دیں اور یہی سچا دین ہے', NULL, NULL, '1d4ce734bf83093befd4f59041537ba0db94c14ff2ea54adf9acd91acf4ba04f'),
  ('ur.jalandhry', 98, 6, 6136, 'جو لوگ کافر ہیں (یعنی) اہل کتاب اور مشرک وہ دوزخ کی آگ میں پڑیں گے (اور) ہمیشہ اس میں رہیں گے۔ یہ لوگ سب مخلوق سے بدتر ہیں', NULL, NULL, '260a6c45012cff64056726ce85737653a9efdb6183aecd1165059de48e291784'),
  ('ur.jalandhry', 98, 7, 6137, '(اور) جو لوگ ایمان لائے اور نیک عمل کرتے رہے وہ تمام خلقت سے بہتر ہیں', NULL, NULL, '62d441bc71fb381ffe767ff0f2047dc49a46d6220b414d208a5f036d98fa3fd9'),
  ('ur.jalandhry', 98, 8, 6138, 'ان کا صلہ ان کے پروردگار کے ہاں ہمیشہ رہنے کے باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں ابدالاباد ان میں رہیں گے۔ خدا ان سے خوش اور وہ اس سے خوش۔ یہ (صلہ) اس کے لیے ہے جو اپنے پروردگار سے ڈرتا رہا', NULL, NULL, '0e997abcbb30f4a52be0c2ac7accda709cf2ae75fd3d66149cbae3a2fd9105cb'),
  ('ur.jalandhry', 99, 1, 6139, 'جب زمین بھونچال سے ہلا دی جائے گی', NULL, NULL, 'b7b630a09a0def08221b3a56c91cdbaea6d18482e1e72cd6fb5cf9ea4a6420ce'),
  ('ur.jalandhry', 99, 2, 6140, 'اور زمین اپنے (اندر) کے بوجھ نکال ڈالے گی', NULL, NULL, 'b88aeff830d74cde99b35f11767a120db0b5db7e3e1533c3054c11b83ff250c7'),
  ('ur.jalandhry', 99, 3, 6141, 'اور انسان کہے گا کہ اس کو کیا ہوا ہے؟', NULL, NULL, '758467a5922d8395a6d86e5791d08d51239e94b85a79390f97ec33685daa35fd'),
  ('ur.jalandhry', 99, 4, 6142, 'اس روز وہ اپنے حالات بیان کردے گی', NULL, NULL, 'fd82ff8640503ccd1e348860a5807554c527bcab58f6410efe123f0f22970a7f'),
  ('ur.jalandhry', 99, 5, 6143, 'کیونکہ تمہارے پروردگار نے اس کو حکم بھیجا (ہوگا)', NULL, NULL, '4cf57d1ce5bf6274ce2449078e2ac2810eb3a53dac02a3dd52f24b589bfa1c2e'),
  ('ur.jalandhry', 99, 6, 6144, 'اس دن لوگ گروہ گروہ ہو کر آئیں گے تاکہ ان کو ان کے اعمال دکھا دیئے جائیں', NULL, NULL, 'a06edcbb7ae2411982360e3a80800d6ea30398133a59c30746f4141232970552'),
  ('ur.jalandhry', 99, 7, 6145, 'تو جس نے ذرہ بھر نیکی کی ہو گی وہ اس کو دیکھ لے گا', NULL, NULL, '9578a525dc5185828a636c96ece13ea5a939d72addba5ca231cb25e6cc06ab4e'),
  ('ur.jalandhry', 99, 8, 6146, 'اور جس نے ذرہ بھر برائی کی ہوگی وہ اسے دیکھ لے گا', NULL, NULL, '123e8614a3d6155275314844bc36af49e14253e377da1b19aaadea7694f02762'),
  ('ur.jalandhry', 100, 1, 6147, 'ان سرپٹ دوڑنے والے گھوڑوں کی قسم جو ہانپ اٹھتےہیں', NULL, NULL, 'beba176fe9391b67f8ae578208750643c5accc91b5c6c6711bb25eb4a9f7099c'),
  ('ur.jalandhry', 100, 2, 6148, 'پھر (پتھروں پر نعل) مار کر آگ نکالتے ہیں', NULL, NULL, '0e502db28a30e191aa736a770266c0b13995df778b56c7ba0bbc859db39b9a61'),
  ('ur.jalandhry', 100, 3, 6149, 'پھر صبح کو چھاپہ مارتے ہیں', NULL, NULL, 'ac589ee4490800b0f3e6a4bd5f0928c0d9a160003b2cbdebcfad0f049c120464'),
  ('ur.jalandhry', 100, 4, 6150, 'پھر اس میں گرد اٹھاتے ہیں', NULL, NULL, '131b950fec69068192e2b996c15a1b91a4e16eb7624f6d5d58c64c6bef69a2a7'),
  ('ur.jalandhry', 100, 5, 6151, 'پھر اس وقت دشمن کی فوج میں جا گھستے ہیں', NULL, NULL, '748cac826e153e16e97f997235c036ab4874e19cbe6fcea1c02c9cd262e6a7f3'),
  ('ur.jalandhry', 100, 6, 6152, 'کہ انسان اپنے پروردگار کا احسان ناشناس (اور ناشکرا) ہے', NULL, NULL, '2e6b58b6d17c61ad0f4586aeb62847f0f3da081a218d42153ecc639f77ac969b'),
  ('ur.jalandhry', 100, 7, 6153, 'اور وہ اس سے آگاہ بھی ہے', NULL, NULL, '2f5c209dbfbec655f0ee289687cba5283a0228b9a7255f71a4fff7a009e06a94'),
  ('ur.jalandhry', 100, 8, 6154, 'وہ تو مال سے سخت محبت کرنے والا ہے', NULL, NULL, 'd9508c72c9e08a45c775a75141f32e58e553520490d027920a761f88e9584f6e'),
  ('ur.jalandhry', 100, 9, 6155, 'کیا وہ اس وقت کو نہیں جانتا کہ جو (مردے) قبروں میں ہیں وہ باہر نکال لیے جائیں گے', NULL, NULL, '3a128f88c8f3c0b5fcc9b703e5345a0a2b0ce1bb08e7a7ae9afa99a288433bc7'),
  ('ur.jalandhry', 100, 10, 6156, 'اور جو (بھید) دلوں میں ہیں وہ ظاہر کر دیئے جائیں گے', NULL, NULL, '2253d6095978b763e5e3ac5521e99d21580d9a19eda2203ce0c6621af10793ac'),
  ('ur.jalandhry', 100, 11, 6157, 'بےشک ان کا پروردگار اس روز ان سے خوب واقف ہوگا', NULL, NULL, '9a8f2e26d8d7b8a5d5cc68fc5664338bf02bfd72cca3044148fd19747307ce9a'),
  ('ur.jalandhry', 101, 1, 6158, 'کھڑ کھڑانے والی', NULL, NULL, '9d71b2bae2c7b775aca659e5e332dae9417c0405ac9e27837ae749a283d20370'),
  ('ur.jalandhry', 101, 2, 6159, 'کھڑ کھڑانے والی کیا ہے؟', NULL, NULL, 'c4e2e7da51e10c11bbc767bd9af775120cd48a23507c0390e51b4decf7d5fc6e'),
  ('ur.jalandhry', 101, 3, 6160, 'اور تم کیا جانوں کھڑ کھڑانے والی کیا ہے؟', NULL, NULL, 'ec54857ab446712a2311b31fdba53993825fcdf1652b1254ce9d6ebb7f6be8bf'),
  ('ur.jalandhry', 101, 4, 6161, '(وہ قیامت ہے) جس دن لوگ ایسے ہوں گے جیسے بکھرے ہوئے پتنگے', NULL, NULL, '94d418885bc62e53e33176cabe6cd1b9e795eae8447d8a8d101eaa667ce009f6'),
  ('ur.jalandhry', 101, 5, 6162, 'اور پہاڑ ایسے ہو جائیں گے جیسے دھنکی ہوئی رنگ برنگ کی اون', NULL, NULL, 'c65fe865614daf2d0e4f830f947352c153be1d5dfdb07f6ae76fefe9478c49f8'),
  ('ur.jalandhry', 101, 6, 6163, 'تو جس کے (اعمال کے) وزن بھاری نکلیں گے', NULL, NULL, '52c85ee95365fea05d0a942b554f1d3aac133a6c577e6f38ec3c8c5827239b44'),
  ('ur.jalandhry', 101, 7, 6164, 'وہ دل پسند عیش میں ہو گا', NULL, NULL, '22435aa3654c241494e47514ea92b582c92a25fcb28b29f930c86f0f19a8271b'),
  ('ur.jalandhry', 101, 8, 6165, 'اور جس کے وزن ہلکے نکلیں گے', NULL, NULL, 'd124b584c40001c52bf0a81f79b062356ed4329843d334cc49c0fcb2067dadd5'),
  ('ur.jalandhry', 101, 9, 6166, 'اس کا مرجع ہاویہ ہے', NULL, NULL, '36540e84ca1ccab19b7de06ee94394560dca8121d184ccd175836be6417ed2eb'),
  ('ur.jalandhry', 101, 10, 6167, 'اور تم کیا سمجھے کہ ہاویہ کیا چیز ہے؟', NULL, NULL, 'ede433791d6475eb9c843981c2d4abacc8e3abdc979f11decfaa1a2c678d3d35'),
  ('ur.jalandhry', 101, 11, 6168, 'دہکتی ہوئی آگ ہے', NULL, NULL, '7aa7ba29554c4eade2961c7289b9daa4583ec3f922de88d79fe0120f7d998ee7'),
  ('ur.jalandhry', 102, 1, 6169, '(لوگو) تم کو (مال کی) بہت سی طلب نے غافل کر دیا', NULL, NULL, '497838698f361011f499ab808d55bce9d36bc161444d50bea0293771db6986ce'),
  ('ur.jalandhry', 102, 2, 6170, 'یہاں تک کہ تم نے قبریں جا دیکھیں', NULL, NULL, '2dfece4f28150d7918eb7eb20b9b6c26149ba1e7264afe3c674bddeec37e1f32'),
  ('ur.jalandhry', 102, 3, 6171, 'دیکھو تمہیں عنقریب معلوم ہو جائے گا', NULL, NULL, '468097641f4e0cc21a911a59061507b72587b331c26b9286756ee00871581df0'),
  ('ur.jalandhry', 102, 4, 6172, 'پھر دیکھو تمہیں عنقریب معلوم ہو جائے گا', NULL, NULL, 'a8ca1258e11993054b0cebb1b96ea022592b2350bc000c1febb6bcbbced70bf6'),
  ('ur.jalandhry', 102, 5, 6173, 'دیکھو اگر تم جانتے (یعنی) علم الیقین (رکھتے تو غفلت نہ کرتے)', NULL, NULL, 'e01bad05c94982baaf0fcba9e5b806cddbafa7db9af2fc111ae665803393ad1d'),
  ('ur.jalandhry', 102, 6, 6174, 'تم ضرور دوزخ کو دیکھو گے', NULL, NULL, '470debb7962861d58afda824dc3e83c4b408c83566986bf68e9c6ad7ececfb1a'),
  ('ur.jalandhry', 102, 7, 6175, 'پھر اس کو (ایسا) دیکھو گے (کہ) عین الیقین (آ جائے گا)', NULL, NULL, '2fff492c68fe3e81db0538c787a780c2d49d35a9d458ace28b9a5040b18ff01f'),
  ('ur.jalandhry', 102, 8, 6176, 'پھر اس روز تم سے (شکر) نعمت کے بارے میں پرسش ہو گی', NULL, NULL, '0c5eb143aaf3557c37cc2d136e26249ae56730b60c464cc58975bde4bd65cf90'),
  ('ur.jalandhry', 103, 1, 6177, 'عصر کی قسم', NULL, NULL, 'aa09d55ab75fdf52fb0219259f776a9cd976bb7b660f31485363387a52b4a138'),
  ('ur.jalandhry', 103, 2, 6178, 'کہ انسان نقصان میں ہے', NULL, NULL, 'bab79b6e246719776ad4fe197b857a071fd45c82c72c8aad26f363039c3fa6cd'),
  ('ur.jalandhry', 103, 3, 6179, 'مگر وہ لوگ جو ایمان لائے اور نیک عمل کرتے رہے اور آپس میں حق (بات) کی تلقین اور صبر کی تاکید کرتے رہے', NULL, NULL, 'cb1b8e169e30128911c05337c13917d467d927655ac576d70e1995741b26279f'),
  ('ur.jalandhry', 104, 1, 6180, 'ہر طعن آمیز اشارتیں کرنے والے چغل خور کی خرابی ہے', NULL, NULL, '1998763bf5c279881ddd08e63a19483666584e39d0bc49f885518e22336e5585'),
  ('ur.jalandhry', 104, 2, 6181, 'جو مال جمع کرتا اور اس کو گن گن کر رکھتا ہے', NULL, NULL, '66181a7f55a5edcb0339fe80120f682ce9e78692a6acf71951806ed416d00ef2'),
  ('ur.jalandhry', 104, 3, 6182, '(اور) خیال کرتا ہے کہ اس کا مال اس کی ہمیشہ کی زندگی کا موجب ہو گا', NULL, NULL, '29a9763c2976e9e6b8cbbc98a22ce1e745e0ecf12f0ed2181d85ef6375b9c24f'),
  ('ur.jalandhry', 104, 4, 6183, 'ہر گز نہیں وہ ضرور حطمہ میں ڈالا جائے گا', NULL, NULL, '86f2ba933b4e31617c347fa48e36841d130f426ab0dad81bff9654078cc78925'),
  ('ur.jalandhry', 104, 5, 6184, 'اور تم کیا سمجھے حطمہ کیا ہے؟', NULL, NULL, 'cee58e180474a7dcffef9e2359b0810aaffba1eb50d7a7e832b33d40f783d357'),
  ('ur.jalandhry', 104, 6, 6185, 'وہ خدا کی بھڑکائی ہوئی آگ ہے', NULL, NULL, 'c891986b65379b72da80e9be78293a9682512ef32a995d3592efec678f4abb30'),
  ('ur.jalandhry', 104, 7, 6186, 'جو دلوں پر جا لپٹے گی', NULL, NULL, 'c2bb3747a78438422763e32a059baefe180e66a31ed8b0460b185467a38ca0c4'),
  ('ur.jalandhry', 104, 8, 6187, '(اور) وہ اس میں بند کر دیئے جائیں گے', NULL, NULL, '349846f2b171cb58c1b3d5692ec6d5ead81ca3677f62c271991fd4ecb700cebb'),
  ('ur.jalandhry', 104, 9, 6188, '(یعنی آگ کے) لمبے لمبے ستونوں میں', NULL, NULL, '0e84f7f9d29c0de556f46d5830dce79233567a3c417156f61fb986abb2a346f5'),
  ('ur.jalandhry', 105, 1, 6189, 'کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے ہاتھی والوں کے ساتھ کیا کیا', NULL, NULL, 'ad5fafd496656aa6532353abdd40cb37f71e237527ed0c452e6a589210c5b6fb'),
  ('ur.jalandhry', 105, 2, 6190, 'کیا ان کا داؤں غلط نہیں کیا؟ (گیا)', NULL, NULL, '540670964f888f499b0e4e8b5ac4360692699780c691147ece5eca5ff7241a82'),
  ('ur.jalandhry', 105, 3, 6191, 'اور ان پر جھلڑ کے جھلڑ جانور بھیجے', NULL, NULL, '5f1cffe467f2185557c124295c646fdd07c3cfa99e210b81b148dedfe8b2ad8d'),
  ('ur.jalandhry', 105, 4, 6192, 'جو ان پر کھنگر کی پتھریاں پھینکتے تھے', NULL, NULL, 'fa86ec0a97cb924055e34dad6044116515faaabd844fdb169c93b96a1d6921bd'),
  ('ur.jalandhry', 105, 5, 6193, 'تو ان کو ایسا کر دیا جیسے کھایا ہوا بھس', NULL, NULL, 'e1f16c443292713c5c84c17b237a27a16626667f2b5be8bd8b9ddbf28f7bb6d6'),
  ('ur.jalandhry', 106, 1, 6194, 'قریش کے مانوس کرنے کے سبب', NULL, NULL, 'b11b2a8f98f7e730d0018c61a20cc731f74ae611aa8fb84c9149a600ab570294'),
  ('ur.jalandhry', 106, 2, 6195, '(یعنی) ان کو جاڑے اور گرمی کے سفر سے مانوس کرنے کے سبب', NULL, NULL, 'a0064eb1d1eb8f89d1c601805f172b22339637f27dd06673f7b631f3ada767b2'),
  ('ur.jalandhry', 106, 3, 6196, 'لوگوں کو چاہیئے کہ (اس نعمت کے شکر میں) اس گھر کے مالک کی عبادت کریں', NULL, NULL, 'fe33060f357d26f0c8aff11f13fb05f4fa1e195c07f9ff109042b481679a6eb9'),
  ('ur.jalandhry', 106, 4, 6197, 'جس نے ان کو بھوک میں کھانا کھلایا اور خوف سے امن بخشا', NULL, NULL, 'c68461fafa0f8c65aa235df82092b6f5082e2dd56ba41e24ade8e5cc5b5d4e6a'),
  ('ur.jalandhry', 107, 1, 6198, 'بھلا تم نے اس شخص کو دیکھا جو (روزِ) جزا کو جھٹلاتا ہے؟', NULL, NULL, 'e7e582ce2242fde0f023eba872d6d4c72985e12a9ddda85a1ce05d96d13dde7f'),
  ('ur.jalandhry', 107, 2, 6199, 'یہ وہی (بدبخت) ہے، جو یتیم کو دھکے دیتا ہے', NULL, NULL, '18b5f5707cb597ebd85d56813487333e4928927f116649950001c7ef27db0e36'),
  ('ur.jalandhry', 107, 3, 6200, 'اور فقیر کو کھانا کھلانے کے لیے (لوگوں کو) ترغیب نہیں دیتا', NULL, NULL, '7d78dcdaf18518565fe14c77dbfccb1fd754161aff728344151c3b8ca4962b6d')
