  ('ur.jalandhry', 107, 4, 6201, 'تو ایسے نمازیوں کی خرابی ہے', NULL, NULL, '34064df40c2092fa0be081e37027e8afdb9a9dfec2f764e5876c878d85664594'),
  ('ur.jalandhry', 107, 5, 6202, 'جو نماز کی طرف سے غافل رہتے ہیں', NULL, NULL, 'f89c738661a3be8401c4d02815ccd053051da51f54c6ec36f0a56b39b9e66987'),
  ('ur.jalandhry', 107, 6, 6203, 'جو ریا کاری کرتے ہیں', NULL, NULL, 'd99a116ce7377050455fb089c81464165d75e1d6f82a552fabdc07f9a55ad2dc'),
  ('ur.jalandhry', 107, 7, 6204, 'اور برتنے کی چیزیں عاریتہً نہیں دیتے', NULL, NULL, 'c11854418a07c79284a218f37ca27d1266a58e7ea06ac5a1ad1ae61eb9b120c5'),
  ('ur.jalandhry', 108, 1, 6205, '(اے محمدﷺ) ہم نے تم کو کوثر عطا فرمائی ہے', NULL, NULL, '159d15a5f71e003deeecd6bc4e184776d7a293c8af82e52e6487cfdb606c19fa'),
  ('ur.jalandhry', 108, 2, 6206, 'تو اپنے پروردگار کے لیے نماز پڑھا کرو اور قربانی دیا کرو', NULL, NULL, 'da764555b8f06fef005c21e16517f499c7c2e92f47060e2eac8eba38fc4c551a'),
  ('ur.jalandhry', 108, 3, 6207, 'کچھ شک نہیں کہ تمہارا دشمن ہی بےاولاد رہے گا', NULL, NULL, '7e5be9fea7edb2d17fe9f0da49c9a058844f49595fd749b6b4ed93666e5f5bff'),
  ('ur.jalandhry', 109, 1, 6208, '(اے پیغمبر ان منکران اسلام سے) کہہ دو کہ اے کافرو!', NULL, NULL, '56f585ebdd2429e6977417ac417ae833d94da7fcafecef5e515e2ebd52772573'),
  ('ur.jalandhry', 109, 2, 6209, 'جن (بتوں) کو تم پوچتے ہو ان کو میں نہیں پوجتا', NULL, NULL, '7469e798a8138ee1a53b7909bfcc602537617a1da8e80851553aa8f36c7ec7d6'),
  ('ur.jalandhry', 109, 3, 6210, 'اور جس (خدا) کی میں عبادت کرتا ہوں اس کی تم عبادت نہیں کرتے', NULL, NULL, '7a76da4669e3f831311dfc58dd03b884fa702e255fb3bee457b66d1d58ca00e0'),
  ('ur.jalandhry', 109, 4, 6211, 'اور (میں پھر کہتا ہوں کہ) جن کی تم پرستش کرتے ہوں ان کی میں پرستش کرنے والا نہیں ہوں', NULL, NULL, 'a00da671deb5712f3f245b8d75df914e91b31cc6a9189b4ff661b4027ac568e3'),
  ('ur.jalandhry', 109, 5, 6212, 'اور نہ تم اس کی بندگی کرنے والے (معلوم ہوتے) ہو جس کی میں بندگی کرتا ہوں', NULL, NULL, '3cdae82c6e5f63e6dd4e65870e0c960ecb9731d741a9b57f4785b96f859709dc'),
  ('ur.jalandhry', 109, 6, 6213, 'تم اپنے دین پر میں اپنے دین پر', NULL, NULL, '701b645ca0286c8408031cea051d2724818c848232c93d4faebe45b817dac91a'),
  ('ur.jalandhry', 110, 1, 6214, 'جب خدا کی مدد آ پہنچی اور فتح (حاصل ہو گئی)', NULL, NULL, '86a3abc16fea6a8f07efabe68c1b400f04db08c598c4f382bd6c095c19d765db'),
  ('ur.jalandhry', 110, 2, 6215, 'اور تم نے دیکھ لیا کہ لوگ غول کے غول خدا کے دین میں داخل ہو رہے ہیں', NULL, NULL, 'c8d1fa0f35f160a68610c49b73cc259a8c39e6d666f5cf2b9dc4af4d41fec57f'),
  ('ur.jalandhry', 110, 3, 6216, 'تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کرو اور اس سے مغفرت مانگو، بے شک وہ معاف کرنے والا ہے', NULL, NULL, 'bd0f4c604cce6a28c48352d841e0e08b79c9496fc83a79c9e7c702e8e82500fe'),
  ('ur.jalandhry', 111, 1, 6217, 'ابولہب کے ہاتھ ٹوٹیں اور وہ ہلاک ہو', NULL, NULL, '160b2ac2f0ee53286cffe9054003cf7702634c6ebe7be6f1981a77b682546fa3'),
  ('ur.jalandhry', 111, 2, 6218, 'نہ تو اس کا مال ہی اس کے کچھ کام آیا اور نہ وہ جو اس نے کمایا', NULL, NULL, '0f7976b0824d82ec6474a195e8883cbc71f9aad006cf5081aa446423ec8ee03a'),
  ('ur.jalandhry', 111, 3, 6219, 'وہ جلد بھڑکتی ہوئی آگ میں داخل ہو گا', NULL, NULL, '9161e40d1e4d6c012e40fbd582cf3874dbe8a6bfbbb8c5aa88b60706a1736444'),
  ('ur.jalandhry', 111, 4, 6220, 'اور اس کی جورو بھی جو ایندھن سر پر اٹھائے پھرتی ہے', NULL, NULL, '43d01a1278c03eab3d979595c6247581406a5dc90511f65f01afd651c54fa3f0'),
  ('ur.jalandhry', 111, 5, 6221, 'اس کے گلے میں مونج کی رسّی ہو گی', NULL, NULL, '51b24e6c0f383f728d744533197e26317396cc4185cdc2c2132fc9275abd7930'),
  ('ur.jalandhry', 112, 1, 6222, 'کہو کہ وہ (ذات پاک جس کا نام) الله (ہے) ایک ہے', NULL, NULL, '21c7bf94a48dbbdb3067d6efa12d398423a13c88ce7cac52d5340ef2ca236d0c'),
  ('ur.jalandhry', 112, 2, 6223, 'معبود برحق جو بےنیاز ہے', NULL, NULL, '47ef385de3a09f42ec3af27726171377e4329caeb12d81d6f911d03c0e67bd7f'),
  ('ur.jalandhry', 112, 3, 6224, 'نہ کسی کا باپ ہے اور نہ کسی کا بیٹا', NULL, NULL, '4a52a9bdb111aca2bcc661993b3d3eab57ff50ecf26c0e5605408ed132636903'),
  ('ur.jalandhry', 112, 4, 6225, 'اور کوئی اس کا ہمسر نہیں', NULL, NULL, '0c024afb2c46dacdd9d54725af3dfa7055975f4b1e69e01194e0ba851146d8d3'),
  ('ur.jalandhry', 113, 1, 6226, 'کہو کہ میں صبح کے پروردگار کی پناہ مانگتا ہوں', NULL, NULL, 'c40841b2515636442455a0a7199ea5b7558f027c8791c12a5fd8e0d7780fae0a'),
  ('ur.jalandhry', 113, 2, 6227, 'ہر چیز کی بدی سے جو اس نے پیدا کی', NULL, NULL, '29286699b3b224bbc3aa3bbe48f4fe6d7bb74b91f808a2dc8d64a5c92184dfe5'),
  ('ur.jalandhry', 113, 3, 6228, 'اور شب تاریکی کی برائی سے جب اس کااندھیرا چھا جائے', NULL, NULL, '91330a2332a4e07ff651011c2226c914e1434b6f4d798ad12d6e5c663b2349f6'),
  ('ur.jalandhry', 113, 4, 6229, 'اور گنڈوں پر (پڑھ پڑھ کر) پھونکنے والیوں کی برائی سے', NULL, NULL, '1ed3968acb945cab8ba7c231ee5d94f5899c11a3e24f7ccacec63cfc242f53e3'),
  ('ur.jalandhry', 113, 5, 6230, 'اور حسد کرنے والے کی برائی سے جب حسد کرنے لگے', NULL, NULL, '25270ee362679f901d1099bf55953d944607cf70befd1b631809b1d632c69640'),
  ('ur.jalandhry', 114, 1, 6231, 'کہو کہ میں لوگوں کے پروردگار کی پناہ مانگتا ہوں', NULL, NULL, '606dae60dcaa7e533084fd46cf0b1f13a06c4d0c1b1dd63794172ae84ac4710d'),
  ('ur.jalandhry', 114, 2, 6232, '(یعنی) لوگوں کے حقیقی بادشاہ کی', NULL, NULL, '842dce7f7ba655916f219f8720c60b84a1f8a5d3853039e56f965027702d3912'),
  ('ur.jalandhry', 114, 3, 6233, 'لوگوں کے معبود برحق کی', NULL, NULL, '51852446b0cea818629e0a18838d31832d52887873f5b34b179a79472f796a3e'),
  ('ur.jalandhry', 114, 4, 6234, '(شیطان) وسوسہ انداز کی برائی سے جو (خدا کا نام سن کر) پیچھے ہٹ جاتا ہے', NULL, NULL, '487bbb4ee236be5cb811308b65ea0bf6c287e37586a3d10cd504b372fd604e0c'),
  ('ur.jalandhry', 114, 5, 6235, 'جو لوگوں کے دلوں میں وسوسے ڈالتا ہے', NULL, NULL, '0eadb68530a6e317553a4f28318c0e1e74a0cdb637edecf861d158ef7ef0f539'),
  ('ur.jalandhry', 114, 6, 6236, 'وہ جنّات میں سے (ہو) یا انسانوں میں سے', NULL, NULL, '66b69a48726899cd631346d574093bdfef9a40091bbfb4710b1c0e97d127059b')
